--  DDL for View CHECK_TK_THANG_PT80
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."CHECK_TK_THANG_PT80" ("PHAM_NHAN_ID", "GT_MA", "MA_TOI_DANH", "TD_CHUONG", "LL_SO_TIEN_AN", "LL_GHI_CHU_RIENG", "NAM_SINH", "MA_QUOC_TICH", "MA_DAN_TOC", "TG_MA", "HV_MA", "PD_MA", "NAM_PHAM_TOI", "MA_BENH_TAT", "MA_TAI_PHAM", "MA_NGHE_NGHIEP", "LL_HO_TEN", "LL_TRAI_GIAM_ID", "TG_MA_1", "MUC_AN_NGAY") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT "PHAM_NHAN_ID","GT_MA","MA_TOI_DANH","TD_CHUONG","LL_SO_TIEN_AN","LL_GHI_CHU_RIENG","NAM_SINH","MA_QUOC_TICH","MA_DAN_TOC","TG_MA","HV_MA","PD_MA","NAM_PHAM_TOI","MA_BENH_TAT","MA_TAI_PHAM","MA_NGHE_NGHIEP","LL_HO_TEN","LL_TRAI_GIAM_ID","TG_MA_1","MUC_AN_NGAY" FROM (
  WITH
        /*==============================================================
         * STEP 0 — SCOPE
         * T?p ph?m nhân thu?c ph?m vi báo cáo, l?c theo tr?i giam ngay t? ??u.
         * ??y ?i?u ki?n  261 lên s?m nh?t ?? toàn b? pipeline phía sau
         * (ARRIVED, các EX_*, ACTIVE_*) ch? x? lý ph?m nhân c?a tr?i ???c ch?n.
         * Khi  261 IS NULL: SCOPE = toàn b? dân s? (báo cáo toàn qu?c).
         *============================================================*/
        SCOPE AS (SELECT LL.ID AS LLID
                  FROM QLPN.PN_LAI_LICHS LL
                  WHERE LL.IS_DELETED = 0
                    AND (  LL.LL_TRAI_GIAM_ID =  211)),
        /*==============================================================
         * STEP 1 — ARRIVED
         * Ph?m nhân có ít nh?t m?t THA v?i THA_NGAY_DEN_TRAI <=  TO_DATE('14/09/2026','DD/MM/YYYY').
         * Equivalent v?i "MIN(NGAY_DEN_TRAI) <=  TO_DATE('14/09/2026','DD/MM/YYYY')" c?a hàm g?c.
         *============================================================*/
        ARRIVED AS (SELECT DISTINCT THA.THA_PNLAI_LICH_ID AS LLID
                    FROM QLPN.PN_THI_HANH_AN THA
                             JOIN SCOPE S ON S.LLID = THA.THA_PNLAI_LICH_ID
                    WHERE THA.THA_NGAY_DEN_TRAI IS NOT NULL
                      AND THA.THA_NGAY_DEN_TRAI <  TO_DATE('14/09/2026','DD/MM/YYYY') + 1
                      AND THA.IS_DELETED = 0),

        /*==============================================================
         * EXCLUSION CTEs — m?i CTE = m?t t?p KHÔNG thu?c '111'/'112'.
         *============================================================*/

        -- E1 ? K?t thúc h? s? (return 9999)
        EX_TERMINAL AS (SELECT LL.ID AS LLID
                        FROM QLPN.PN_LAI_LICHS LL
                                 JOIN PN_THI_HANH_AN ptha ON ptha.THA_PNLAI_LICH_ID = LL.ID AND ptha.IS_DELETED = 0
                                 JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS TTPN
                                      ON TTPN.ID = LL.LL_TINH_TRANG_ID
                        WHERE TTPN.TTPN_MA = '9999'
                          AND (LL.IS_DELETED = 0 OR LL.IS_DELETED IS NULL)),

        -- E2 ? Ch?t thông th??ng (return 171)
        --      THC_MA IN ('30','40','50') là ch?t-khi-?ang-tr?n / -TX / -TDC,
        --      ???c lo?i b?i EX_TRON / EX_TRICH_XUAT / EX_TAM_DINH_CHI.
        EX_CHET AS (SELECT KC.KTC_PN_LAI_LICH_ID AS LLID
                    FROM QLPN.PN_KET_THUC_CHETS KC
                             LEFT JOIN QLPN.DM_TRUONG_HOP_CHETS THC
                                       ON THC.ID = KC.KTC_DM_TRUONG_HOP_CHET_ID
                    WHERE KC.KTC_NGAY_CHET <  TO_DATE('14/09/2026','DD/MM/YYYY') + 1 -- ??m c? nh?ng ph?m nhân ch?t ngày 14/xx/yyyy
--                       AND (THC.THC_MA NOT IN ('30', '40', '50') OR THC.THC_MA IS NULL)
                      AND (KC.IS_DELETED = 0 OR KC.IS_DELETED IS NULL)),

        -- E3 ? Tr?n tr?i, ch?a b?t l?i (return 131/132).
        --      Không l?c TTT_MA: tr?n-ch?t (TTT_MA='20') hay tr?n-th??ng ??u EXCLUDE.
        --      TRUNC kh?p v?i check 131 generic c?a hàm g?c (line 143).
        EX_TRON AS (SELECT TT.PHAM_NHAN_ID AS LLID
                    FROM QLPN.TRON_TRAIS TT
                    WHERE TT.NGAY_TRON <  TO_DATE('14/09/2026','DD/MM/YYYY') + 1
                      AND (TT.NGAY_BAT_LAI IS NULL
                        OR TT.NGAY_BAT_LAI >=  TO_DATE('14/09/2026','DD/MM/YYYY') + 1)
                      AND (TT.IS_DELETED = 0 OR TT.IS_DELETED IS NULL)),

        -- E4 ? Hu? án ?ang t? do (return 181). NGAY_TRO_LAI NULL ho?c >  TO_DATE('14/09/2026','DD/MM/YYYY').
        EX_HUY_AN AS (SELECT HA.PHAM_NHAN_ID AS LLID
                      FROM QLPN.HUY_ANS HA
                      WHERE HA.NGAY_TRA_TU_DO <  TO_DATE('14/09/2026','DD/MM/YYYY') + 1
                        AND (HA.NGAY_TRO_LAI IS NULL
                          OR HA.NGAY_TRO_LAI >=  TO_DATE('14/09/2026','DD/MM/YYYY') + 1)
                        AND (HA.IS_DELETED = 0 OR HA.IS_DELETED IS NULL)),

        -- E5 ? Chuy?n giao qu?c t? (return 127). V?nh vi?n lo?i.
        EX_CHUYEN_GIAO AS (SELECT CG.PNCG_LAI_LICH_ID AS LLID
                           FROM QLPN.PN_CHUYEN_GIAO CG
                           WHERE CG.PNCG_NGAY_CHUYEN_GIAO <  TO_DATE('14/09/2026','DD/MM/YYYY') + 1
                             AND (CG.IS_DELETED = 0 OR CG.IS_DELETED IS NULL)),

        -- E6 ? Mi?n hình ph?t (return 124). V?nh vi?n lo?i.
        EX_MIEN_HP AS (SELECT MHP.PN_LAI_LICH_ID AS LLID
                       FROM QLPN.MIEN_HINH_PHATS MHP
                       WHERE MHP.MHP_NGAY_TU_DO <  TO_DATE('14/09/2026','DD/MM/YYYY') + 1
                         AND (MHP.IS_DELETED = 0 OR MHP.IS_DELETED IS NULL)),

        -- E7 ? Chuy?n tr?i ?i, ch?a tr? l?i (return 161).
        --      THCT_MA = '50' là "chuy?n v?" n?i b? — không lo?i.
        EX_CHUYEN_TRAI AS (SELECT CT.PNCT_LAI_LICH_ID AS LLID
                           FROM QLPN.PHAM_NHAN_CHUYEN_TRAI CT
                                    LEFT JOIN QLPN.DM_TRUONG_HOP_CHUYEN_TRAIS THCT
                                              ON THCT.ID = CT.PNCT_TRUONG_HOP_CHUYEN_ID
                           WHERE CT.PNCT_NGAY_CHUYEN <=  TO_DATE('14/09/2026','DD/MM/YYYY')
                             AND (CT.PNCT_NGAY_TRO_LAI IS NULL
                               OR CT.PNCT_NGAY_TRO_LAI >  TO_DATE('14/09/2026','DD/MM/YYYY'))
                             AND (THCT.THCT_MA <> '50' OR THCT.THCT_MA IS NULL)
                             AND (CT.IS_DELETED = 0 OR CT.IS_DELETED IS NULL)),

        -- E8 ? Trích xu?t ?ang hi?u l?c (return 141-150, 126(TX)).
        --      [BUG FIX #1] Ch? lo?i khi:
        --        • TX_LOAI_LENH_ID = 1  ? m?i TTTX_MA (compound block 141/142/146
        --          + các status specific 143/144/145/150/126 trong hàm g?c)
        --        • HO?C TTTX_MA IN ('70','80','98') không có lenh filter
        --          (path 147 Gi?m h?t án / 148 ??c xá / 149 X? t?i m?i c?a hàm g?c)
        --      Các TX khác (lenh<>1 AND TTTX_MA khác) KHÔNG ???c hàm g?c lo?i
        --      ? ph?i ?? qua l??i EX_TRICH_XUAT.
        EX_TRICH_XUAT AS (SELECT TX.PHAM_NHAN_ID AS LLID
                          FROM QLPN.TRICH_XUATS TX
                                   LEFT JOIN QLPN.DM_TINH_TRANG_TRICH_XUATS TTTX
                                             ON TTTX.ID = TX.TX_TINH_TRANG_ID
                          WHERE TX.TX_NGAY_TRICH_XUAT <=  TO_DATE('14/09/2026','DD/MM/YYYY')
                            AND (TX.TX_NGAY_TRA IS NULL OR TX.TX_NGAY_TRA >  TO_DATE('14/09/2026','DD/MM/YYYY') AND TTTX.TTTX_MA = '99')
                            AND (TX.IS_DELETED = 0 OR TX.IS_DELETED IS NULL)
                            AND (TX.TX_LOAI_LENH_ID = 1)
        ),

        -- E9 ? ??c xá (return 123). DX_NGAY_THA NOT NULL ? v?nh vi?n lo?i.
        EX_DAC_XA AS (SELECT DX.PNLAI_LICH_ID AS LLID
                      FROM QLPN.PN_DAC_XAS DX
                      WHERE DX.DX_NGAY_THA <=  TO_DATE('14/09/2026','DD/MM/YYYY')
                        AND (DX.IS_DELETED = 0 OR DX.IS_DELETED IS NULL)),

        -- E10 ? Tha tr??c có ?i?u ki?n, ch?a b? b?t l?i (return 126/TCK).
        EX_THA_CO_DK AS (SELECT TCK.PHAM_NHAN_ID AS LLID
                         FROM QLPN.THA_CO_DIEU_KIENS TCK
                         WHERE TCK.NGAY_THA <  TO_DATE('14/09/2026','DD/MM/YYYY')
                           AND (TCK.NGAY_BAT_LAI IS NULL OR TCK.NGAY_BAT_LAI >=  TO_DATE('14/09/2026','DD/MM/YYYY') + 1)
                           AND (TCK.IS_DELETED = 0 OR TCK.IS_DELETED IS NULL)),

        -- E11 ? Gi?m h?t án (return 122). V?nh vi?n lo?i.
        EX_GIAM_HET_AN AS (SELECT GTH.PHAM_NHAN_ID AS LLID
                           FROM QLPN.GIAM_THOI_HANS GTH
                           WHERE GTH.NGAY_THA_GIAM_HET_AN <=  TO_DATE('14/09/2026','DD/MM/YYYY')
                             AND (GTH.IS_DELETED = 0 OR GTH.IS_DELETED IS NULL)),

        -- E12 ? Hoãn thi hành án ?ang hi?u l?c (return 191).
        --       Hàm g?c dùng strict <, không <= — gi? y nguyên.
        EX_HOAN_THA AS (SELECT HTHA.PHAM_NHAN_ID AS LLID
                        FROM QLPN.HOAN_THI_HANH_ANS HTHA
                        WHERE HTHA.NGAY_HOAN <  TO_DATE('14/09/2026','DD/MM/YYYY')
                          AND (HTHA.NGAY_THI_HANH_AN IS NULL OR
                               HTHA.NGAY_THI_HANH_AN >  TO_DATE('14/09/2026','DD/MM/YYYY'))
                          AND (HTHA.IS_DELETED = 0 OR HTHA.IS_DELETED IS NULL)),

        -- E13 ? T?m ?ình ch? ?ang hi?u l?c (return 151-159).
        --       LOAI_QUYET_DINH_ID=1 cover 151/152/153/154/156/157/158/159.
        --       TTTDC_MA='50' (155) trong hàm g?c không có lenh filter ? OR.
        --       S?A 2026-08-22 (??o l?i fix tr??c ?ó): KHÔNG lo?i TTTDC_MA='20' ('Gia h?n') —
        --       xác nh?n qua d? li?u th?t + chính FN_TINH_TRANG_PN_TAI_NGAY.cand (dòng
        --       LOAI_QUYET_DINH_ID=1 AND TTTDC_MA='20' ? mã '152', v?n coi là ?ANG t?m ?ình
        --       ch?, không ph?i active) r?ng b?n ghi Gia h?n v?i LOAI_QUYET_DINH_ID=1 là T?C m?
        --       h?p l?, không ph?i "b?n ghi ph? nên b? qua" nh? ?ã hi?u nh?m tr??c ?ó (nh?m v?i
        --       quy t?c riêng c?a PKG_TINH_AN — bài toán tính T?NG S? NGÀY, khác bài toán xác
        --       ??nh TR?NG THÁI HI?N T?I ? ?ây).
        --       L?I TH?T n?m ? "OR TTTDC.TTTDC_MA IS NULL": canonical KHÔNG có nhánh này — b?n
        --       ghi T?C c?/ch?a gán TINH_TRANG_ID (TTTDC_MA NULL) v?i LOAI_QUYET_DINH_ID <> 1
        --       b? PT80 lo?i nh?m (coi là ?ang T?C) trong khi canonical không lo?i (không kh?p
        --       LOAI_QUYET_DINH_ID=1, c?ng không kh?p MA='50') — ?ây là nguyên nhân th?t c?a
        --       l?ch PT80 vs dashboard (Nhóm 1, xác nh?n qua ??i chi?u 2026-08-22). B? nhánh
        --       NULL ?? kh?p ?úng canonical.
        EX_TAM_DINH_CHI AS (SELECT TDC.PHAM_NHAN_ID AS LLID
                            FROM QLPN.TAM_DINH_CHIS TDC
                                     LEFT JOIN QLPN.DM_TINH_TRANG_TAM_DINH_CHIES TTTDC
                                               ON TTTDC.ID = TDC.TINH_TRANG_ID
                            WHERE TDC.NGAY_TDC <=  TO_DATE('14/09/2026','DD/MM/YYYY')
                              AND (TDC.NGAY_LAI IS NULL OR TDC.NGAY_LAI >  TO_DATE('14/09/2026','DD/MM/YYYY'))
                              AND (TTTDC.TTTDC_MA = '50' OR TDC.LOAI_QUYET_DINH_ID = 1)
                              AND (TDC.IS_DELETED = 0 OR TDC.IS_DELETED IS NULL)
--                              AND NVL(TTTDC.TTTDC_MA, 'X') <> '20'
),

        -- E14 ? ?ang ch?a b?nh b?t bu?c (return 113).
        --       [BUG FIX #3] Ch? lo?i khi KHÔNG có PN_GIAM_RIENGS active ??ng th?i:
        --       hàm g?c ki?m tra GR TR??C CB ? final block, n?u GR active thì
        --       tr? '112' (INCLUDE) tr??c khi ??n nhánh '113'. NOT EXISTS d??i
        --       ?ây kh?p ?úng precedence ?ó.
        --       Tr??ng h?p V_NGAY_RA_TRAI <=  TO_DATE('14/09/2026','DD/MM/YYYY') + CB active (return '125')
        --       ?ã ???c EX_NGAY_RA_TRAI b?t ??c l?p, không c?n CTE này lo.
--         EX_CHUA_BENH AS (SELECT CB.PHAM_NHAN_ID AS LLID
--                          FROM QLPN.CHUA_BENH_BAT_BUOCS CB
--                          WHERE (CB.NGAY_KET_THUC IS NULL
--                              OR CB.NGAY_KET_THUC  >  TO_DATE('14/09/2026','DD/MM/YYYY'))
--                            AND (CB.IS_DELETED = 0 OR CB.IS_DELETED IS NULL)
--                            AND NOT EXISTS (SELECT 1
--                                            FROM QLPN.PN_GIAM_RIENGS GR
--                                            WHERE GR.GR_PN_LAI_LICH_ID = CB.PHAM_NHAN_ID
--                                              AND (GR.GR_NGAY_KETTHUC IS NULL
--                                                OR GR.GR_NGAY_KETTHUC  >  TO_DATE('14/09/2026','DD/MM/YYYY'))
--                                              AND (GR.IS_DELETED = 0 OR GR.IS_DELETED IS NULL))),

        -- E15 ? V_NGAY_RA_TRAI ?ã set <=  TO_DATE('14/09/2026','DD/MM/YYYY') (return 121/125 — ??u EXCLUDE).
        --       [BUG FIX #2] Ph?i g?p ?? 7 b?ng nh? hàm g?c; b?n c? thi?u
        --       PN_KET_THUC_RA_TRAIS. Dùng UNION ALL — NOT EXISTS không c?n dedup.
        --       M?t s? b?ng ?ã có ? các EX_* khác (E5/E6/E9/E11); ? ?ây b? sung
        --       các tr??ng h?p prisoner ?ã quay l?i (NGAY_TRO_LAI/NGAY_BAT_LAI
        --       <=  TO_DATE('14/09/2026','DD/MM/YYYY')) mà E4/E10 không b?t ???c — vì hàm g?c v?n coi ?ã
        --       ra tr?i do MIN(NGAY_RA) <=  TO_DATE('14/09/2026','DD/MM/YYYY').
        EX_NGAY_RA_TRAI AS (
            -- Theo hàm ALT hi?n t?i, V_NGAY_RA_TRAI ???c l?y t? THA_NGAY_HET_HAN.
            -- N?u THA_NGAY_HET_HAN <=  TO_DATE('14/09/2026','DD/MM/YYYY') thì prisoner không còn thu?c 111/112/113
            -- (s? r?i vào 121 ho?c 125), nên ph?i EXCLUDE.
--            SELECT ptha.THA_PNLAI_LICH_ID AS LLID
--            FROM PN_THI_HANH_AN ptha
--            WHERE ptha.THA_NGAY_HET_HAN <=  TO_DATE('14/09/2026','DD/MM/YYYY')
--              AND ptha.IS_DELETED = 0

                SELECT tl.pn_id AS LLID
                  FROM (
                        SELECT tha.THA_PNLAI_LICH_ID AS pn_id,
                               tha.THA_NGAY_HET_HAN,
                               ROW_NUMBER() OVER (
                                   PARTITION BY tha.THA_PNLAI_LICH_ID
                                   ORDER BY NVL(tha.THA_NGAY_BAN_AN, tha.CREATION_TIME) DESC, tha.ID DESC
                               ) rn
                          FROM QLPN.PN_THI_HANH_AN tha
                         WHERE tha.THA_NGAY_HET_HAN IS NOT NULL and tha.THA_NGAY_HET_HAN <=  TO_DATE('14/09/2026','DD/MM/YYYY')
                           AND NVL(tha.IS_DELETED, 0) = 0
                       ) tl
                 WHERE tl.rn = 1                 


--             SELECT HA.PHAM_NHAN_ID AS LLID
--             FROM QLPN.HUY_ANS HA
--             WHERE HA.NGAY_TRA_TU_DO IS NOT NULL
--               AND HA.NGAY_TRA_TU_DO  <=  TO_DATE('14/09/2026','DD/MM/YYYY')
--               AND (HA.IS_DELETED = 0 OR HA.IS_DELETED IS NULL)
--             UNION ALL
--             -- 2. MIEN_HINH_PHATS
--             SELECT MHP.PN_LAI_LICH_ID
--             FROM QLPN.MIEN_HINH_PHATS MHP
--             WHERE MHP.MHP_NGAY_TU_DO IS NOT NULL
--               AND MHP.MHP_NGAY_TU_DO  <=  TO_DATE('14/09/2026','DD/MM/YYYY')
--               AND (MHP.IS_DELETED = 0 OR MHP.IS_DELETED IS NULL)
--             UNION ALL
--             -- 3. GIAM_THOI_HANS
--             SELECT GTH.PHAM_NHAN_ID
--             FROM QLPN.GIAM_THOI_HANS GTH
--             WHERE GTH.NGAY_THA_GIAM_HET_AN IS NOT NULL
--               AND GTH.NGAY_THA_GIAM_HET_AN  <=  TO_DATE('14/09/2026','DD/MM/YYYY')
--               AND (GTH.IS_DELETED = 0 OR GTH.IS_DELETED IS NULL)
--             UNION ALL
--             -- 4. PN_DAC_XAS
--             SELECT DX.PNLAI_LICH_ID
--             FROM QLPN.PN_DAC_XAS DX
--             WHERE DX.DX_NGAY_THA IS NOT NULL
--               AND DX.DX_NGAY_THA  <=  TO_DATE('14/09/2026','DD/MM/YYYY')
--               AND (DX.IS_DELETED = 0 OR DX.IS_DELETED IS NULL)
--             UNION ALL
--             -- 5. THA_CO_DIEU_KIENS: m?i NGAY_THA <=  TO_DATE('14/09/2026','DD/MM/YYYY') (k? c? ?ã NGAY_BAT_LAI)
--             SELECT TCK.PHAM_NHAN_ID
--             FROM QLPN.THA_CO_DIEU_KIENS TCK
--             WHERE TCK.NGAY_THA IS NOT NULL
--               AND TCK.NGAY_THA  <=  TO_DATE('14/09/2026','DD/MM/YYYY')
--               AND (TCK.IS_DELETED = 0 OR TCK.IS_DELETED IS NULL)
--             UNION ALL
--             -- 6. PN_CHUYEN_GIAO
--             SELECT CG.PNCG_LAI_LICH_ID
--             FROM QLPN.PN_CHUYEN_GIAO CG
--             WHERE CG.PNCG_NGAY_CHUYEN_GIAO IS NOT NULL
--               AND CG.PNCG_NGAY_CHUYEN_GIAO  <=  TO_DATE('14/09/2026','DD/MM/YYYY')
--               AND (CG.IS_DELETED = 0 OR CG.IS_DELETED IS NULL)
--             UNION ALL
--             -- 7. PN_KET_THUC_RA_TRAIS  ? b?ng b? thi?u ? b?n ALT c?
--             SELECT KT.KTRT_PN_LAI_LICH_ID
--             FROM QLPN.PN_KET_THUC_RA_TRAIS KT
--             WHERE KT.KTRT_NGAY_THA IS NOT NULL
--               AND KT.KTRT_NGAY_THA  <=  TO_DATE('14/09/2026','DD/MM/YYYY')
--               AND (KT.IS_DELETED = 0 OR KT.IS_DELETED IS NULL)
        ),

        /*==============================================================
         * STEP 2 — UNION ALL EXCLUSIONS
         * UNION ALL (không UNION) — NOT EXISTS ? STEP 3 t? dedup.
         *============================================================*/
        ALL_EXCLUDED AS (SELECT LLID
                         FROM EX_TERMINAL
                         UNION ALL
                         SELECT LLID
                         FROM EX_CHET
                         UNION ALL
                         SELECT LLID
                         FROM EX_TRON
                         UNION ALL
                         SELECT LLID
                         FROM EX_HUY_AN
                         UNION ALL
                         SELECT LLID
                         FROM EX_CHUYEN_GIAO
                         UNION ALL
                         SELECT LLID
                         FROM EX_MIEN_HP
                         UNION ALL
                         SELECT LLID
                         FROM EX_CHUYEN_TRAI
                         UNION ALL
                         SELECT LLID
                         FROM EX_TRICH_XUAT
                         UNION ALL
                         SELECT LLID
                         FROM EX_DAC_XA
                         UNION ALL
                         SELECT LLID
                         FROM EX_THA_CO_DK
                         UNION ALL
                         SELECT LLID
                         FROM EX_GIAM_HET_AN
                         UNION ALL
                         SELECT LLID
                         FROM EX_HOAN_THA
                         UNION ALL
                         SELECT LLID
                         FROM EX_TAM_DINH_CHI
                         UNION ALL
                         SELECT LLID
                         FROM EX_NGAY_RA_TRAI),

        /*==============================================================
         * STEP 3 — ACTIVE PRISONERS
         * = ?ã ??n tr?i (ARRIVED) VÀ không trong b?t k? t?p exclude nào.
         * T??ng ???ng: FN_GET_TINH_TRANG tr? '111' ho?c '112'.
         *============================================================*/
        ACTIVE_PN AS (SELECT A.LLID
                      FROM ARRIVED A
                      WHERE NOT EXISTS (SELECT 1
                                        FROM ALL_EXCLUDED E
                                        WHERE E.LLID = A.LLID)),

        /*==============================================================
         * STEP 3.1 — ACTIVE STATUS BUCKETS
         * Phân lo?i t?p active theo precedence c?a hàm:
         *   112 -> gi?m riêng active
         *   113 -> ch?a b?nh active, nh?ng không gi?m riêng
         *   111 -> active còn l?i
         *============================================================*/
        ACTIVE_GR AS (SELECT DISTINCT GR.GR_PN_LAI_LICH_ID AS LLID
                      FROM QLPN.PN_GIAM_RIENGS GR
                      WHERE (GR.GR_NGAY_KETTHUC IS NULL
                          OR GR.GR_NGAY_KETTHUC >  TO_DATE('14/09/2026','DD/MM/YYYY'))
                        AND (GR.IS_DELETED = 0 OR GR.IS_DELETED IS NULL)),

        ACTIVE_CB AS (SELECT DISTINCT CB.PHAM_NHAN_ID AS LLID
                      FROM QLPN.CHUA_BENH_BAT_BUOCS CB
                      WHERE (CB.NGAY_KET_THUC IS NULL
                          OR CB.NGAY_KET_THUC >  TO_DATE('14/09/2026','DD/MM/YYYY'))
                        AND (CB.IS_DELETED = 0 OR CB.IS_DELETED IS NULL)),

        ACTIVE_STATUS AS (SELECT AP.LLID,
                                 CASE
                                     WHEN EXISTS (SELECT 1
                                                  FROM ACTIVE_GR AGR
                                                  WHERE AGR.LLID = AP.LLID) THEN '112'
                                     WHEN EXISTS (SELECT 1
                                                  FROM ACTIVE_CB ACB
                                                  WHERE ACB.LLID = AP.LLID) THEN '113'
                                     ELSE '111'
                                     END AS LOGIC_STATUS
                          FROM ACTIVE_PN AP)

    /*==============================================================
     * STEP 4 — FINAL SELECT (gi?ng SELECT c?a SP_POPULATE_TK_PT80 g?c)
     *============================================================*/
    SELECT LL.ID PHAM_NHAN_ID,
           GT.GT_MA,

           -- MA_TOI_DANH: ';'-separated list of TD_MA t? PN_BAN_AN_KHACS
           TD_FIRST.TD_MA                                     AS MA_TOI_DANH,
           TD_FIRST.TD_CHUONG,

           LL.LL_SO_TIEN_AN,
           LL.LL_GHI_CHU_RIENG,
           TO_NUMBER(NVL(SUBSTR(LL.LL_NGAY_SINH, -4), 1970))  AS NAM_SINH, -- raw text, parse qua FN_PARSE_NGAY_SINH
           QT.QT_MA MA_QUOC_TICH,
           DT.DT_MA MA_DAN_TOC,
           TG_RELIGION.TG_MA,
           HV.HV_MA,
           PD.PD_MA,

           -- NGAY_PHAM_TOI: earliest THA_NGAY_PHAM_TOI
           EXTRACT(YEAR FROM NVL(ptha.THA_NGAY_PHAM_TOI, SYSDATE))          AS NAM_PHAM_TOI,

           BT.BT_MA MA_BENH_TAT,
           TO_NCHAR(NVL(TP.TP_MA, 0)) MA_TAI_PHAM,
           NN.NN_MA MA_NGHE_NGHIEP,
           LL.LL_HO_TEN,
           LL.LL_TRAI_GIAM_ID,
           TG_PRISON.TG_MA TG_MA_1,
           CASE
               WHEN MTG_THANG IS NOT NULL AND MTG_NGAY IS NOT NULL
                   THEN MTG.MTG_THANG * 30 + MTG.MTG_NGAY END AS MUC_AN_NGAY

 FROM ACTIVE_STATUS   AP
             JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = AP.LLID AND LL.IS_DELETED = 0
             JOIN QLPN.PN_THI_HANH_AN ptha ON LL.ID = ptha.THA_PNLAI_LICH_ID AND ptha.IS_DELETED = 0
             LEFT JOIN QLPN.DM_GIOI_TINHS GT ON GT.ID = LL.LL_DM_GIOI_TINH_ID AND GT.IS_DELETED = 0
             LEFT JOIN QLPN.DM_TOI_DANHS TD_FIRST
                       ON TD_FIRST.ID = TO_NUMBER(
                               SUBSTR(
                                       ptha.THA_TOI_DANH,
                                       2,
                                       INSTR(TRANSLATE(ptha.THA_TOI_DANH, ']', ','), ',', 1) - 2
                               ))
                           AND (TD_FIRST.IS_DELETED = 0 OR TD_FIRST.IS_DELETED IS NULL)
             LEFT JOIN DM_MA_THOI_GIANS MTG ON ptha.THA_MA_AN_PHAT = MTG.MTG_MA AND MTG.IS_DELETED = 0
             LEFT JOIN QLPN.DM_QUOC_TICHS QT ON QT.ID = LL.LL_DM_QUOC_TICH_ID AND QT.IS_DELETED = 0
             LEFT JOIN QLPN.DM_DAN_TOCS DT ON DT.ID = LL.LL_DM_DAN_TOC_ID AND DT.IS_DELETED = 0
             LEFT JOIN QLPN.DM_TON_GIAOS TG_RELIGION
                       ON TG_RELIGION.ID = LL.LL_DM_TON_GIAO_ID AND TG_RELIGION.IS_DELETED = 0
             LEFT JOIN QLPN.DM_HOC_VANS HV ON HV.ID = LL.LL_DM_HOC_VAN_ID AND HV.IS_DELETED = 0
             LEFT JOIN QLPN.DM_NGHE_NGHIEPS NN ON NN.ID = LL.LL_DM_NGHE_NGHIEP_ID AND NN.IS_DELETED = 0
             LEFT JOIN QLPN.DM_PHAN_DOIS PD ON PD.ID = LL.LL_PHAN_DOI_ID AND PD.IS_DELETED = 0
             LEFT JOIN QLPN.DM_BENH_TATS BT ON BT.ID = LL.LL_BENH_TAT_VAO_ID AND BT.IS_DELETED = 0
             LEFT JOIN QLPN.DM_TRAI_GIAMS TG_PRISON ON TG_PRISON.ID = LL.LL_TRAI_GIAM_ID AND TG_PRISON.IS_DELETED = 0
             LEFT JOIN QLPN.DM_TAI_PHAMS TP ON TP.ID = LL.LL_TAI_PHAM AND TP.IS_DELETED = 0

    WHERE (  LL.LL_TRAI_GIAM_ID =  211 ) )
;
