  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."MIGRATION_PN_LAI_LICHS_V" ("SOURCE_SCHEMA", "SOURCE_PN_ID", "SOURCE_SO_HSLD_NORM", "ID", "LL_ANH", "LL_SO_HO_SO_LAN_DAU", "LL_SO_HO_PHU", "LL_CCCD", "LL_HO_CHIEU", "LL_HO_TEN", "LL_TEN_KHAC", "LL_DIA_CHI_THUONG_TRU_OLD", "LL_NOI_OTRUOC_KHI_BAT", "LL_NOI_OKHAC", "LL_NGUYEN_QUAN", "LL_NOI_THA_VE_CU_TRU", "LL_CHI_TIET_HV", "LL_TOM_TAT_HV", "LL_CHI_MUC_TIM_KIEM", "LL_TRINH_DO_CHUYEN_MON", "LL_NGHE_CU_THE", "LL_CHI_TIET_BENH_VAO", "LL_CHI_TIET_BENH_HIEN_TAI", "LL_GHI_CHU_RIENG", "LL_GHI_CHU_CHI_TIET", "LL_PHAN_DOI_ID", "LL_TINH_TRANG_ID", "LL_TRINH_DO_HOC_VAN_ID", "LL_TRAI_GIAM_ID", "LL_TINH_TRANG_HOC_TAP_ID", "LL_BIET_DOC_VIET_ID", "LL_BENH_TAT_VAO_ID", "LL_DM_GIOI_TINH_ID", "LL_DIA_CHI_THUONG_TRU_PROVICE", "LL_DIA_CHI_THUONG_TRU_WARD", "LL_NOI_OTRUOC_KHI_BAT_PROVICE", "LL_NOI_OTRUOC_KHI_BAT_WARD", "LL_NOI_OKHAC_PROVICE", "LL_NOI_OKHAC_WARD", "LL_NOI_THA_VE_CU_TRU_PROVICE", "LL_NOI_THA_VE_CU_TRU_WARD", "LL_DM_NGHE_NGHIEP_ID", "LL_DM_HOC_VAN_ID", "LL_DM_QUOC_TICH_ID", "LL_DM_TON_GIAO_ID", "LL_DM_DAN_TOC_ID", "LL_PN_GIAO_NHAN_PHAN_NHAN_ID", "LL_SUC_KHOE_KHI_VAO_ID", "LL_SO_TIEN_SU", "LL_GHI_CHU_TIEN_SU", "LL_SO_TIEN_AN", "LL_TAI_PHAM", "LL_NHAN_THAN", "CREATION_TIME", "CREATOR_USER_ID", "LAST_MODIFICATION_TIME", "LAST_MODIFIER_USER_ID", "IS_DELETED", "DELETER_USER_ID", "DELETION_TIME", "LL_PHAN_TRAI_ID", "LL_NGAY_SINH", "LL_SO_GCN", "LL_GHI_CHU_CHUNG_HPBS", "PN_MA_TINH_TRANG_TRICH_XUAT", "LL_DIA_CHI_THA_VE_CU_TRU_CU", "LL_DIA_CHI_THUONG_TRU_CU", "LL_DIA_CHI_TRUOC_KHI_BAT_CU", "LL_BENH_HIEN_TAI_ID", "LL_TINH_TRANG_OLD_ID", "LL_DIA_CHI_THUONG_TRU", "HO_TEN_ORDER", "C06_LAST_SYNC_AT", "C06_SYNC_STATUS", "C06_SYNC_ERROR") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    m.SOURCE_SCHEMA,
    m.SOURCE_PN_ID,
    m.SOURCE_SO_HSLD_NORM,
    ll."ID",ll."LL_ANH",ll."LL_SO_HO_SO_LAN_DAU",ll."LL_SO_HO_PHU",ll."LL_CCCD",ll."LL_HO_CHIEU",ll."LL_HO_TEN",ll."LL_TEN_KHAC",ll."LL_DIA_CHI_THUONG_TRU_OLD",ll."LL_NOI_OTRUOC_KHI_BAT",ll."LL_NOI_OKHAC",ll."LL_NGUYEN_QUAN",ll."LL_NOI_THA_VE_CU_TRU",ll."LL_CHI_TIET_HV",ll."LL_TOM_TAT_HV",ll."LL_CHI_MUC_TIM_KIEM",ll."LL_TRINH_DO_CHUYEN_MON",ll."LL_NGHE_CU_THE",ll."LL_CHI_TIET_BENH_VAO",ll."LL_CHI_TIET_BENH_HIEN_TAI",ll."LL_GHI_CHU_RIENG",ll."LL_GHI_CHU_CHI_TIET",ll."LL_PHAN_DOI_ID",ll."LL_TINH_TRANG_ID",ll."LL_TRINH_DO_HOC_VAN_ID",ll."LL_TRAI_GIAM_ID",ll."LL_TINH_TRANG_HOC_TAP_ID",ll."LL_BIET_DOC_VIET_ID",ll."LL_BENH_TAT_VAO_ID",ll."LL_DM_GIOI_TINH_ID",ll."LL_DIA_CHI_THUONG_TRU_PROVICE",ll."LL_DIA_CHI_THUONG_TRU_WARD",ll."LL_NOI_OTRUOC_KHI_BAT_PROVICE",ll."LL_NOI_OTRUOC_KHI_BAT_WARD",ll."LL_NOI_OKHAC_PROVICE",ll."LL_NOI_OKHAC_WARD",ll."LL_NOI_THA_VE_CU_TRU_PROVICE",ll."LL_NOI_THA_VE_CU_TRU_WARD",ll."LL_DM_NGHE_NGHIEP_ID",ll."LL_DM_HOC_VAN_ID",ll."LL_DM_QUOC_TICH_ID",ll."LL_DM_TON_GIAO_ID",ll."LL_DM_DAN_TOC_ID",ll."LL_PN_GIAO_NHAN_PHAN_NHAN_ID",ll."LL_SUC_KHOE_KHI_VAO_ID",ll."LL_SO_TIEN_SU",ll."LL_GHI_CHU_TIEN_SU",ll."LL_SO_TIEN_AN",ll."LL_TAI_PHAM",ll."LL_NHAN_THAN",ll."CREATION_TIME",ll."CREATOR_USER_ID",ll."LAST_MODIFICATION_TIME",ll."LAST_MODIFIER_USER_ID",ll."IS_DELETED",ll."DELETER_USER_ID",ll."DELETION_TIME",ll."LL_PHAN_TRAI_ID",ll."LL_NGAY_SINH",ll."LL_SO_GCN",ll."LL_GHI_CHU_CHUNG_HPBS",ll."PN_MA_TINH_TRANG_TRICH_XUAT",ll."LL_DIA_CHI_THA_VE_CU_TRU_CU",ll."LL_DIA_CHI_THUONG_TRU_CU",ll."LL_DIA_CHI_TRUOC_KHI_BAT_CU",ll."LL_BENH_HIEN_TAI_ID",ll."LL_TINH_TRANG_OLD_ID",ll."LL_DIA_CHI_THUONG_TRU",ll."HO_TEN_ORDER",ll."C06_LAST_SYNC_AT",ll."C06_SYNC_STATUS",ll."C06_SYNC_ERROR"
FROM QLPN.MIGRATION_PN_MAP m
INNER JOIN QLPN.PN_LAI_LICHS ll
    ON ll.ID = m.TARGET_PN_LAI_LICH_ID
;
