--  DDL for View VHS_TK_GIAM_THOI_HAN
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."VHS_TK_GIAM_THOI_HAN" ("KGTH_ID", "KGTH_NAM", "KGTH_TEN_KY", "KGTH_NGAY_XET_GIAM", "SO_PN") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
  ky.ID AS KGTH_ID,
  ky.KGTH_NAM AS KGTH_NAM,
  ky.KGTH_TEN_KY AS KGTH_TEN_KY,
  TO_CHAR(ky.KGTH_NGAY_XET_GIAM, 'DD/MM/YYYY') AS KGTH_NGAY_XET_GIAM,
  COUNT(DISTINCT hs.HOC_SINH_ID) AS SO_PN
FROM HOCSINH.GTH_KY_GIAM_THOI_HANS ky
LEFT JOIN HOCSINH.HS_GIAM_THOI_HANS hs
  ON hs.NGAY_XET = ky.KGTH_NGAY_XET_GIAM
 AND NVL(hs.IS_DELETED, 0) = 0
WHERE NVL(ky.IS_DELETED, 0) = 0
GROUP BY
  ky.ID,
  ky.KGTH_NAM,
  ky.KGTH_TEN_KY,
  TO_CHAR(ky.KGTH_NGAY_XET_GIAM, 'DD/MM/YYYY')
;
