--  DDL for View VPN_TK_DAC_XA_THA_CDK_DASHBOARD
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."VPN_TK_DAC_XA_THA_CDK_DASHBOARD" ("NAM", "LOAI_THA", "DOT_THA", "MA_TRAI_GIAM", "SO_LUONG") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    NAM,
    LOAI_THA,
    DOT_THA,
    MA_TRAI_GIAM,
    SO_LUONG
  FROM QLPN.PN_TK_DAC_XA_THA_CDK_DASHBOARD
;
--------------------------------------------------------
--  DDL for View VPN_TK_DAC_XA_THA_CDK_DASHBOARD_OLD
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."VPN_TK_DAC_XA_THA_CDK_DASHBOARD_OLD" ("NAM", "LOAI_THA", "DOT_THA", "MA_TRAI_GIAM", "SO_LUONG") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  WITH
trai_map AS (
    SELECT /*+ MATERIALIZE */ ID, TG_MA
    FROM QLPN.DM_TRAI_GIAMS
    WHERE NVL(IS_DELETED, 0) = 0
),
duoc_dac_xa_ids AS (
    -- DM_DUOC_DAC_XAS.ID -> tinh trang thuc su "duoc dac xa" (DDX_MA 10/11/12)
    SELECT /*+ MATERIALIZE */ ID
    FROM QLPN.DM_DUOC_DAC_XAS
    WHERE NVL(IS_DELETED, 0) = 0
      AND DDX_MA IN ('10', '11', '12')
),
dx_status_raw AS (
    SELECT dx.ID                                                                                     AS DX_ID,
           dx.PNLAI_LICH_ID,
           REPLACE(REPLACE(REPLACE(REPLACE(dx.DX_TINH_TRANG_DAC_XA, '[', ''), ']', ''), '"', ''), '''', '') AS TINH_TRANG_CSV
    FROM QLPN.PN_DAC_XAS dx
    WHERE NVL(dx.IS_DELETED, 0) = 0
--      AND dx.DX_NGAY_THA IS NOT NULL
      AND dx.DX_TINH_TRANG_DAC_XA IS NOT NULL
),
dx_status_ids AS (
    -- DX_TINH_TRANG_DAC_XA la list dang '[id1,id2,...]' -> tach tung id
    SELECT r.PNLAI_LICH_ID,
           TO_NUMBER(REGEXP_SUBSTR(r.TINH_TRANG_CSV, '[0-9]+', 1, LEVEL)) AS TINH_TRANG_ID
    FROM dx_status_raw r
    CONNECT BY LEVEL <= REGEXP_COUNT(r.TINH_TRANG_CSV, '[0-9]+')
           AND PRIOR r.DX_ID = r.DX_ID
           AND PRIOR SYS_GUID() IS NOT NULL
),
dx_duoc_dac_xa AS (
    SELECT DISTINCT s.PNLAI_LICH_ID
    FROM dx_status_ids s
    INNER JOIN duoc_dac_xa_ids ids
            ON ids.ID = s.TINH_TRANG_ID
),
dot_ddx AS (
    SELECT
        TRUNC(d.DDX_NGAY_XET)                                          AS NGAY_XET,
        MIN(d.DDX_NAM_DAC_XA) KEEP (DENSE_RANK FIRST ORDER BY d.ID)     AS DDX_NAM_DAC_XA,
        MIN(d.DDX_TEN_DOT)    KEEP (DENSE_RANK FIRST ORDER BY d.ID)     AS DDX_TEN_DOT
    FROM QLPN.PN_DOT_DAC_XAS d
    WHERE NVL(d.IS_DELETED, 0) = 0
      AND d.DDX_NGAY_XET IS NOT NULL
    GROUP BY TRUNC(d.DDX_NGAY_XET)
),
dx_pn AS (
    SELECT DISTINCT
        db.DDX_NAM_DAC_XA                     AS NAM,
        NVL(db.DDX_TEN_DOT, u'Kh\00e1c')          AS DOT_THA,
        tg.TG_MA                              AS MA_TRAI_GIAM,
        dx.PNLAI_LICH_ID                      AS PHAM_NHAN_ID
    FROM QLPN.PN_DAC_XAS dx
    INNER JOIN dx_duoc_dac_xa dda
            ON dda.PNLAI_LICH_ID = dx.PNLAI_LICH_ID
    INNER JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt
            ON rt.PHAM_NHAN_ID = dx.PNLAI_LICH_ID
           AND NVL(rt.IS_DELETED, 0) = 0
    INNER JOIN trai_map tg
            ON tg.ID = rt.LL_TRAI_GIAM_ID
    LEFT JOIN dot_ddx db
      ON dx.DX_NGAY_XET >= db.NGAY_XET
     AND dx.DX_NGAY_XET <  db.NGAY_XET + 1
    WHERE dx.DX_NGAY_THA IS NOT NULL
      AND NVL(dx.IS_DELETED, 0) = 0
),
dot_tcdk AS (
    SELECT
        TRUNC(d.DTCDK_NGAY_XET)                                         AS NGAY_XET,
        MIN(d.DTCDK_NGAY_XET) KEEP (DENSE_RANK FIRST ORDER BY d.ID)      AS DTCDK_NGAY_XET
    FROM QLPN.PN_DOT_THA_CO_DIEU_KIENS d
    WHERE NVL(d.IS_DELETED, 0) = 0
      AND d.DTCDK_NGAY_XET IS NOT NULL
    GROUP BY TRUNC(d.DTCDK_NGAY_XET)
),
tcdk_pn AS (
    SELECT DISTINCT
        CAST(EXTRACT(YEAR FROM tck.NGAY_XET) AS NVARCHAR2(4)) AS NAM,
        NVL(TO_NCHAR(tck.NGAY_XET, 'DD/MM/YYYY'), u'Kh\00e1c') AS DOT_THA,
        tg.TG_MA AS MA_TRAI_GIAM,
        tck.PHAM_NHAN_ID
    FROM QLPN.THA_CO_DIEU_KIENS tck
    INNER JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt
            ON rt.PHAM_NHAN_ID = tck.PHAM_NHAN_ID
           AND NVL(rt.IS_DELETED, 0) = 0
    INNER JOIN DM_THA_CO_DIEU_KIENS DM ON DM.ID = TCK.TINH_TRANG_ID
    INNER JOIN trai_map tg
            ON tg.ID = rt.LL_TRAI_GIAM_ID
--    LEFT JOIN dot_tcdk db
--      ON tck.NGAY_XET >= db.NGAY_XET
--     AND tck.NGAY_XET <  db.NGAY_XET + 1
    WHERE tck.NGAY_THA IS NOT NULL
    AND DM.TCDK_MA IN ('10', '11')
      AND NVL(tck.IS_DELETED, 0) = 0
),
chi_tiet AS (
    SELECT
        NAM,
        u'\0110\1eb7c x\00e1' AS LOAI_THA,
        DOT_THA,
        MA_TRAI_GIAM,
        COUNT(*) AS SO_LUONG
    FROM dx_pn
    GROUP BY NAM, DOT_THA, MA_TRAI_GIAM

    UNION ALL

    SELECT
        NAM,
        u'Tha c\00f3 \0111i\1ec1u ki\1ec7n' AS LOAI_THA,
        DOT_THA,
        MA_TRAI_GIAM,
        COUNT(*) AS SO_LUONG
    FROM tcdk_pn
    GROUP BY NAM, DOT_THA, MA_TRAI_GIAM
)
SELECT NAM, LOAI_THA, DOT_THA, MA_TRAI_GIAM, SO_LUONG
FROM chi_tiet

UNION ALL

SELECT
    NAM,
    LOAI_THA,
    DOT_THA,
    u'C10' AS MA_TRAI_GIAM,
    SUM(SO_LUONG) AS SO_LUONG
FROM chi_tiet
GROUP BY NAM, LOAI_THA, DOT_THA
;
--------------------------------------------------------
--  DDL for View VPN_TK_NAM_DASHBOARD
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."VPN_TK_NAM_DASHBOARD" ("NAM", "TU_NGAY", "DEN_NGAY", "MA_TRAI_GIAM", "SO_PN_NAM_TRUOC_CHUYEN_SANG", "SO_TANG_TRONG_NAM", "SO_GIAM_TRONG_NAM", "DANG_CHAP_HANH_AN", "SO_LIEU_NAM") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    NAM,
    TU_NGAY,
    DEN_NGAY,
    MA_TRAI_GIAM,
    SO_PN_NAM_TRUOC_CHUYEN_SANG,
    SO_TANG_TRONG_NAM,
    SO_GIAM_TRONG_NAM,
    DANG_CHAP_HANH_AN,
    DANG_CHAP_HANH_AN AS SO_LIEU_NAM
FROM QLPN.PN_TK_NAM_DASHBOARD
;
--------------------------------------------------------
--  DDL for View VPN_TK_THANG_DASHBOARD
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."VPN_TK_THANG_DASHBOARD" ("THANG", "TU_NGAY", "DEN_NGAY", "MA_TRAI_GIAM", "SO_PN_THANG_TRUOC_CHUYEN_SANG", "SO_TANG_TRONG_THANG", "SO_GIAM_TRONG_THANG", "DANG_CHAP_HANH_AN") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    THANG,
    TU_NGAY,
    DEN_NGAY,
    MA_TRAI_GIAM,
    SO_PN_THANG_TRUOC_CHUYEN_SANG,
    SO_TANG_TRONG_THANG,
    SO_GIAM_TRONG_THANG,
    DANG_CHAP_HANH_AN
FROM QLPN.PN_TK_THANG_DASHBOARD
;
--------------------------------------------------------
--  DDL for View VW_BAO_CAO_DX_CHI_TIET
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."VW_BAO_CAO_DX_CHI_TIET" ("PN_DOT_DAC_XA_ID", "DDX_NAM_DAC_XA", "DDX_TEN_DOT", "TRAI_GIAM_ID", "TEN_TRAI_GIAM", "PHAN_DOI_ID", "PHAN_DOI", "PN_LAI_LICH_ID", "PHAM_NHAN_ID", "HO_TEN", "GIOI_TINH", "NAM_SINH", "NGAY_XET", "NOI_THUONG_TRU_DAY_DU", "NGHE_NGHIEP", "TOI_DANH", "AN_PHAT", "NGAY_BAT_AN_PHAT", "DA_GIAM", "NGAY_DEN_TRAI", "NOI_THA_VE_CU_TRU", "TINH_THANH_CU_TRU", "FLG_NAM", "FLG_NU", "FLG_TONG", "FLG_TOI_ANQG", "FLG_GIET_NGUOI", "FLG_HIEP_DAM", "FLG_HIEP_DAM_TRE_EM", "FLG_MUA_BAN_NGUOI", "FLG_GAY_THUONG_TICH", "FLG_TOI_KHAC_TM_SK_DD_NP", "FLG_CUOP_TAI_SAN", "FLG_CUOP_GIAT", "FLG_TROM_CAP", "FLG_BAT_COC", "FLG_LUA_DAO", "FLG_TOI_KHAC_SO_HUU", "FLG_MUA_BAN_MA_TUY", "FLG_SAN_XUAT_MA_TUY", "FLG_TO_CHUC_SD_MA_TUY", "FLG_CHIEM_DOAT_MA_TUY", "FLG_MA_TUY_KHAC", "FLG_TOI_QLKT", "FLG_NHUNG_CHUC_VU", "FLG_TOI_KHAC", "FLG_CHUNG_THAN", "FLG_TREN_15_30_NAM", "FLG_TREN_7_15_NAM", "FLG_TREN_3_7_NAM", "FLG_TU_3_NAM_TRO_XUONG", "FLG_KHONG_TIEN_AN", "FLG_CO_TIEN_AN", "FLG_DUOI_18_TUOI", "FLG_TU_18_DUOI_30", "FLG_TU_30_DUOI_70", "FLG_TU_70_TRO_LEN", "FLG_HUAN_CHUONG_KHANG_CHIEN", "FLG_THUONG_BINH", "FLG_LAP_CONG", "FLG_TU_70_UU_TIEN", "FLG_DUOI_18_PHAM_TOI", "FLG_DUOI_18_CHAP_HANH", "FLG_GIA_DINH_LIET_SY", "FLG_OM_DAU", "FLG_BENH_HIEM_NGHEO", "FLG_CON_ME_VNAH", "FLG_GIA_DINH_CONG", "FLG_HOAN_CANH_KHO_KHAN", "FLG_TINH_TIET_KHAC", "FLG_QUOC_TICH_NGOAI", "FLG_TON_GIAO", "FLG_DAN_TOC_IT_NGUOI", "DX_XEP_LOAI_CAI_TAO") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  WITH dm_ton_giao_khong AS (
    SELECT TRIM(TG_MA) AS tg_ma
    FROM QLPN.DM_TON_GIAOS
    WHERE NVL(IS_DELETED, 0) = 0
      AND TRIM(TG_TEN) = u'Kh\00f4ng'
),
dm_dan_toc_chinh AS (
    SELECT TRIM(DT_MA) AS dt_ma
    FROM QLPN.DM_DAN_TOCS
    WHERE NVL(IS_DELETED, 0) = 0
      AND TRIM(DT_TEN) IN (u'Kinh', u'Ng\01b0\1eddi n\01b0\1edbc ngo\00e0i')
),
dot_by_ngay AS (
    SELECT TRUNC(DDX_NGAY_XET) AS ngay_xet, MIN(id) AS dot_id
    FROM QLPN.PN_DOT_DAC_XAS
    WHERE NVL(IS_DELETED, 0) = 0
      AND DDX_NGAY_XET IS NOT NULL
    GROUP BY TRUNC(DDX_NGAY_XET)
),
-- PN ???c ??c xá t? PN_DAC_XAS. Join ??t qua dot_by_ngay; hi?n th? t? RT + DM t?i thi?u.
base AS (
    SELECT
        pdx.PNLAI_LICH_ID AS pn_lai_lich_id,
        dot.id AS pn_dot_dac_xa_id,
        NVL(dot.ddx_ngay_xet, SYSDATE) AS ngay_xet,
        dot.ddx_nam_dac_xa,
        dot.ddx_ten_dot,
        rt.LL_TRAI_GIAM_ID AS trai_giam_id,
        NVL(tg.TG_TEN, '') AS ten_trai_giam,
        rt.LL_PHAN_DOI_ID AS phan_doi_id,
        NVL(pd.PD_TEN, '') AS phan_doi,
        rt.PHAM_NHAN_ID,
        rt.LL_HO_TEN AS HO_TEN,
        gt.GT_TEN AS GIOI_TINH,
        rt.LL_DM_GIOI_TINH_ID AS gioi_tinh_id,
        rt.NAM_SINH,
        rt.THA_TOI_DANH_NAMES AS TOI_DANH,
        rt.THA_TOI_DANH AS toi_danh_id,
        rt.THA_AN_PHAT AS AN_PHAT,
        CASE
            WHEN TRIM(TO_CHAR(rt.THA_MA_AN_PHAT)) IN ('911000', '912000', '921000', '922000')
              OR UPPER(QLPN.FN_NORMALIZE_VN(rt.THA_AN_PHAT)) LIKE '%CHUNGTHAN%'
            THEN 1
            ELSE 0
        END AS flg_chung_than_uu_tien,
        qt.QT_TEN AS QUOC_TICH,
        rt.LL_DM_QUOC_TICH_ID AS quoc_tich_id,
        rt.LL_DM_TON_GIAO_ID AS dm_ton_giao_id,
        rt.LL_DM_DAN_TOC_ID AS dm_dan_toc_id,
        tg2.TG_TEN AS TON_GIAO,
        dt.DT_TEN AS DAN_TOC,
        rt.LL_NHAN_THAN AS NHAN_THAN,
        rt.LL_SO_TIEN_AN AS SO_TIEN_AN,
        CASE
            WHEN rt.LL_BENH_HIEN_TAI_ID IS NULL OR dm_bt.BT_MA = 1 THEN u'B\00ecnh th\01b0\1eddng'
            ELSE dm_bt.BT_TEN
        END AS BENH_HIEN_TAI,
        CASE
            WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_tt.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_tt.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_tt.XP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                            THEN u', ' || dxp_tt.XP_TEN
                            ELSE dxp_tt.XP_TEN
                        END
                    ELSE u''
                   END
                || CASE
                    WHEN NULLIF(TRIM(dttp_tt.TTP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_tt.XP_TEN), u'') IS NOT NULL
                            THEN u', ' || dttp_tt.TTP_TEN
                            ELSE dttp_tt.TTP_TEN
                        END
                    ELSE u''
                   END
            )
            ELSE NULL
        END AS NOI_THUONG_TRU_DAY_DU,
        nn.NN_TEN AS NGHE_NGHIEP,
        rt.THA_NGAY_BAT AS NGAY_BAT_AN_PHAT,
        CAST(NULL AS VARCHAR2(1)) AS DA_GIAM,
        rt.THA_NGAY_DEN_TRAI AS NGAY_DEN_TRAI,
        CASE
            WHEN NULLIF(TRIM(rt.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(ntvct_dxp.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(ntvct_dttp.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(rt.LL_NOI_THA_VE_CU_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(ntvct_dxp.XP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(rt.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
                            THEN u', ' || ntvct_dxp.XP_TEN
                            ELSE ntvct_dxp.XP_TEN
                        END
                    ELSE u''
                   END
                || CASE
                    WHEN NULLIF(TRIM(ntvct_dttp.TTP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(rt.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(ntvct_dxp.XP_TEN), u'') IS NOT NULL
                            THEN u', ' || ntvct_dttp.TTP_TEN
                            ELSE ntvct_dttp.TTP_TEN
                        END
                    ELSE u''
                   END
            )
            ELSE NULL
        END AS NOI_THA_VE_CU_TRU,
        ntvct_dttp.TTP_TEN AS TINH_THANH_CU_TRU,
        rt.LL_GHI_CHU_RIENG AS ghi_chu_rieng,
        pdx.DX_XEP_LOAI_CAI_TAO AS dx_xep_loai_cai_tao
    FROM QLPN.PN_DAC_XAS pdx
    INNER JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        ON rt.PHAM_NHAN_ID = pdx.PNLAI_LICH_ID
       AND NVL(rt.IS_DELETED, 0) = 0
       AND rt.THA_ID IS NOT NULL
    INNER JOIN dot_by_ngay d ON d.ngay_xet = TRUNC(pdx.DX_NGAY_XET)
    INNER JOIN QLPN.PN_DOT_DAC_XAS dot ON dot.id = d.dot_id AND NVL(dot.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_GIOI_TINHS gt ON gt.ID = rt.LL_DM_GIOI_TINH_ID AND NVL(gt.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_QUOC_TICHS qt ON qt.ID = rt.LL_DM_QUOC_TICH_ID AND NVL(qt.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_TON_GIAOS tg2 ON tg2.ID = rt.LL_DM_TON_GIAO_ID AND NVL(tg2.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_DAN_TOCS dt ON dt.ID = rt.LL_DM_DAN_TOC_ID AND NVL(dt.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_NGHE_NGHIEPs nn ON nn.ID = rt.LL_DM_NGHE_NGHIEP_ID AND NVL(nn.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_BENH_TATS dm_bt ON rt.LL_BENH_HIEN_TAI_ID = dm_bt.ID AND NVL(dm_bt.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_TRAI_GIAMS tg ON tg.ID = rt.LL_TRAI_GIAM_ID AND NVL(tg.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_PHAN_DOIS pd ON pd.ID = rt.LL_PHAN_DOI_ID AND NVL(pd.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_TINH_THANH_PHO dttp_tt
        ON rt.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_tt.ID AND NVL(dttp_tt.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_XA_PHUONG dxp_tt
        ON rt.LL_DIA_CHI_THUONG_TRU_WARD = dxp_tt.ID AND NVL(dxp_tt.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_XA_PHUONG ntvct_dxp
        ON rt.LL_NOI_THA_VE_CU_TRU_WARD = ntvct_dxp.ID AND NVL(ntvct_dxp.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_TINH_THANH_PHO ntvct_dttp
        ON rt.LL_NOI_THA_VE_CU_TRU_PROVICE = ntvct_dttp.ID AND NVL(ntvct_dttp.IS_DELETED, 0) = 0
    WHERE NVL(pdx.IS_DELETED, 0) = 0
),
base_age AS (
    SELECT b.pn_lai_lich_id, b.pn_dot_dac_xa_id, b.ngay_xet, b.ddx_nam_dac_xa, b.ddx_ten_dot, b.trai_giam_id, b.ten_trai_giam, b.phan_doi_id, b.phan_doi, b.PHAM_NHAN_ID, b.HO_TEN, b.GIOI_TINH, b.NAM_SINH, b.TOI_DANH, b.toi_danh_id, b.AN_PHAT, b.flg_chung_than_uu_tien, b.dx_xep_loai_cai_tao, b.QUOC_TICH, b.quoc_tich_id, b.dm_ton_giao_id, b.dm_dan_toc_id, b.TON_GIAO, b.DAN_TOC, b.NHAN_THAN, b.BENH_HIEN_TAI, b.NOI_THUONG_TRU_DAY_DU, b.NGHE_NGHIEP, b.NGAY_BAT_AN_PHAT, b.DA_GIAM, b.NGAY_DEN_TRAI, b.NOI_THA_VE_CU_TRU, b.TINH_THANH_CU_TRU,
           CASE WHEN b.NAM_SINH IS NOT NULL AND b.NAM_SINH > 0 THEN EXTRACT(YEAR FROM b.ngay_xet) - b.NAM_SINH ELSE NULL END AS tuoi,
           CASE WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) = '1' THEN 1 ELSE 0 END AS is_nam,
           CASE WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) = '2' THEN 1 ELSE 0 END AS is_nu,
           CASE WHEN TO_NUMBER(b.SO_TIEN_AN DEFAULT NULL ON CONVERSION ERROR) > 0 THEN 1 ELSE 0 END AS has_tien_an
    FROM base b
    LEFT JOIN QLPN.DM_GIOI_TINHS gt ON gt.ID = b.gioi_tinh_id AND NVL(gt.IS_DELETED, 0) = 0
),
toi_danh_raw AS (
    SELECT m.pn_lai_lich_id,
           m.pn_dot_dac_xa_id,
           REGEXP_REPLACE(NVL(TRIM(m.toi_danh_id), ''), '[[:space:]\[\]]', '') AS toi_danh_clean,
           ROW_NUMBER() OVER (ORDER BY m.pn_lai_lich_id, m.pn_dot_dac_xa_id) AS row_id
    FROM base_age m
),
toi_danh_ids AS (
    SELECT r.pn_lai_lich_id,
           r.pn_dot_dac_xa_id,
           TO_NUMBER(REGEXP_SUBSTR(r.toi_danh_clean, '[0-9]+', 1, LEVEL)) AS toi_danh_id_num
    FROM toi_danh_raw r
    WHERE r.toi_danh_clean IS NOT NULL
      AND REGEXP_COUNT(r.toi_danh_clean, '[0-9]+') > 0
    CONNECT BY PRIOR r.pn_lai_lich_id = r.pn_lai_lich_id
       AND PRIOR r.pn_dot_dac_xa_id = r.pn_dot_dac_xa_id
       AND PRIOR r.row_id = r.row_id
       AND PRIOR SYS_GUID() IS NOT NULL
       AND LEVEL <= REGEXP_COUNT(r.toi_danh_clean, '[0-9]+')
),
toi_danh_expanded AS (
    SELECT m.pn_lai_lich_id, m.pn_dot_dac_xa_id, m.ngay_xet, m.ddx_nam_dac_xa, m.ddx_ten_dot, m.trai_giam_id, m.ten_trai_giam, m.phan_doi_id, m.phan_doi, m.PHAM_NHAN_ID, m.HO_TEN, m.GIOI_TINH, m.NAM_SINH, m.TOI_DANH, m.toi_danh_id, m.AN_PHAT, m.flg_chung_than_uu_tien, m.dx_xep_loai_cai_tao, m.QUOC_TICH, m.quoc_tich_id, m.dm_ton_giao_id, m.dm_dan_toc_id, m.TON_GIAO, m.DAN_TOC, m.NHAN_THAN, m.BENH_HIEN_TAI, m.NOI_THUONG_TRU_DAY_DU, m.NGHE_NGHIEP, m.NGAY_BAT_AN_PHAT, m.DA_GIAM, m.NGAY_DEN_TRAI, m.NOI_THA_VE_CU_TRU, m.TINH_THANH_CU_TRU, m.tuoi, m.is_nam, m.is_nu, m.has_tien_an,
           dm.TD_CHUONG AS td_chuong,
           TRIM(dm.TD_MA) AS td_ma
    FROM base_age m
    LEFT JOIN toi_danh_ids tdi ON tdi.pn_lai_lich_id = m.pn_lai_lich_id
                               AND tdi.pn_dot_dac_xa_id = m.pn_dot_dac_xa_id
    LEFT JOIN QLPN.DM_TOI_DANHS dm ON dm.ID = tdi.toi_danh_id_num AND NVL(dm.IS_DELETED, 0) = 0
),
toi_danh_flags AS (
    SELECT e.pn_lai_lich_id, e.pn_dot_dac_xa_id, e.ngay_xet, e.ddx_nam_dac_xa, e.ddx_ten_dot, e.trai_giam_id, e.ten_trai_giam, e.phan_doi_id, e.phan_doi, e.PHAM_NHAN_ID, e.HO_TEN, e.GIOI_TINH, e.NAM_SINH, e.TOI_DANH, e.toi_danh_id, e.AN_PHAT, e.dx_xep_loai_cai_tao, e.QUOC_TICH, e.quoc_tich_id, e.dm_ton_giao_id, e.dm_dan_toc_id, e.TON_GIAO, e.DAN_TOC, e.NHAN_THAN, e.BENH_HIEN_TAI, e.NOI_THUONG_TRU_DAY_DU, e.NGHE_NGHIEP, e.NGAY_BAT_AN_PHAT, e.DA_GIAM, e.NGAY_DEN_TRAI, e.NOI_THA_VE_CU_TRU, e.TINH_THANH_CU_TRU, e.tuoi, e.is_nam, e.is_nu, e.has_tien_an,
           MAX(NVL(e.flg_chung_than_uu_tien, 0)) AS flg_chung_than_uu_tien,
           -- ANQG: TD_CHUONG='13' (DM_CHUONG_TOI_DANHS: Các t?i xâm ph?m an ninh qu?c gia)
           MAX(CASE WHEN e.td_chuong = '13' THEN 1 ELSE 0 END) AS flg_toi_anqg,
           -- Ch??ng 14: tính m?ng, SK, DD, NP — ch? theo TD_MA (tm_phanloai.csv).
           MAX(CASE WHEN e.td_chuong = '14' AND UPPER(NVL(e.td_ma,' ')) IN ('093','094','095','096','097','098','099','099A','099B','100','101','101A','101B','102','103','1123','1124','1124A','1124B','1125','1126','1126A','1126B','1127','1128','1129','1129A','1129B','1130','1131','1131A','1131B','1132','1133') THEN 1 ELSE 0 END) AS flg_giet_nguoi,
           MAX(CASE WHEN e.td_chuong = '14' AND UPPER(NVL(e.td_ma,' ')) IN ('111','113','1141','1143','112','112A','114','115','116','1142','1142A','1144','1145','1145A','1145B','1146','1147') THEN 1 ELSE 0 END) AS flg_hiep_dam,
           CAST(0 AS NUMBER) AS flg_hiep_dam_tre_em,
           MAX(CASE WHEN e.td_chuong = '14' AND UPPER(NVL(e.td_ma,' ')) IN ('119A','120A','120E','1150','1151') THEN 1 ELSE 0 END) AS flg_mua_ban_nguoi,
           MAX(CASE WHEN e.td_chuong = '14' AND UPPER(NVL(e.td_ma,' ')) IN ('104','104A','104B','104C','104Z','105','105A','105B','106','106A','106B','107','107A','107B','108','108A','108B','109','109A','109B','1134','1134A','1134B','1135','1135A','1135B','1136','1136A','1136B','1136C','1136D','1136E','1136F','1137','1137A','1137B','1138','1138A','1138B','1139','1139A','1139B','1139C','1139D','1139E','1139F','1139G','1139H') THEN 1 ELSE 0 END) AS flg_gay_thuong_tich,
           -- 107C = "Xâm ph?m tính m?ng..." (không ph?i s?c kho?) nên thu?c nhóm khác, không ph?i gây th??ng tích
           MAX(CASE WHEN e.td_chuong = '14' AND UPPER(NVL(e.td_ma,' ')) IN ('107C','110','1140','117','118','119','120','120B','120C','120D','121','122','1148','1149','1152','1153','1154','1154A','1154B','1154C','1154D','1154E','1154F','1155','1156') THEN 1 ELSE 0 END) AS flg_toi_khac_tm_sk_dd_np,
           -- Ch??ng 16: s? h?u — ch? theo TD_MA (sh_phanloai.csv).
           MAX(CASE WHEN e.td_chuong = '16' AND UPPER(NVL(e.td_ma,' ')) IN ('133','133T','133U','133X','133Y','133Z','1168') THEN 1 ELSE 0 END) AS flg_cuop_tai_san,
           MAX(CASE WHEN e.td_chuong = '16' AND UPPER(NVL(e.td_ma,' ')) IN ('136','136X','136Y','1171') THEN 1 ELSE 0 END) AS flg_cuop_giat,
           MAX(CASE WHEN e.td_chuong = '16' AND UPPER(NVL(e.td_ma,' ')) IN ('138','138T','138U','138X','138Y','1173') THEN 1 ELSE 0 END) AS flg_trom_cap,
           MAX(CASE WHEN e.td_chuong = '16' AND UPPER(NVL(e.td_ma,' ')) IN ('134','134X','134Z','1169') THEN 1 ELSE 0 END) AS flg_bat_coc,
           MAX(CASE WHEN e.td_chuong = '16' AND UPPER(NVL(e.td_ma,' ')) IN ('139','139X','139Y','139Z','1174') THEN 1 ELSE 0 END) AS flg_lua_dao,
           MAX(CASE WHEN e.td_chuong = '16' AND UPPER(NVL(e.td_ma,' ')) IN ('135','135X','135Y','135Z','137','137X','137Y','140','140Y','140Z','141','141X','141Y','142','142X','142Y','143','143A','143B','143T','143V','143X','143Y','143Z','144','145','145O','145X','145Y','1170','1172','1175','1176','1177','1178','1178A','1178B','1178C','1179','1179A','1179B','1179C','1179D','1180') THEN 1 ELSE 0 END) AS flg_toi_khac_so_huu,
           -- Ch??ng 20: ma túy — ch? theo TD_MA (mt_phanloai.csv).
           MAX(CASE WHEN e.td_chuong = '20' AND UPPER(NVL(e.td_ma,' ')) IN ('194D','1252') THEN 1 ELSE 0 END) AS flg_chiem_doat_ma_tuy,
           MAX(CASE WHEN e.td_chuong = '20' AND UPPER(NVL(e.td_ma,' ')) IN ('194J','196M','196L','196G','196H','196K','196I','196C','195C','194C','194I','194F','196','194G','194E','194','1254J','1254G','1254H','1253C','1251','1254','1253') THEN 1 ELSE 0 END) AS flg_mua_ban_ma_tuy,
           MAX(CASE WHEN e.td_chuong = '20' AND UPPER(NVL(e.td_ma,' ')) IN ('195D','196A','193','195A','195B','1253D','1254A','1254B','1248','1254C','1253A','1254E','1253B') THEN 1 ELSE 0 END) AS flg_san_xuat_ma_tuy,
           MAX(CASE WHEN e.td_chuong = '20' AND UPPER(NVL(e.td_ma,' ')) IN ('198','200','200A','200B','197','1256','1257','1258','1255') THEN 1 ELSE 0 END) AS flg_to_chuc_sd_ma_tuy,
           MAX(CASE WHEN e.td_chuong = '20' AND UPPER(NVL(e.td_ma,' ')) IN ('199','192B','192A','192','196D','194A','194H','195','201F','201E','201B','201D','201','201A','201C','196B','194B','1247D','1247B','1247C','1247A','1247','1254I','1254D','1249','1259A','1259','1259C','1259D','1259B','1254F','1250') THEN 1 ELSE 0 END) AS flg_ma_tuy_khac,
           -- Ch??ng 18: QLKT — ch? theo TD_CHUONG
           MAX(CASE WHEN e.td_chuong = '18' THEN 1 ELSE 0 END) AS flg_toi_qlkt,
           -- Tham nh?ng/ch?c v?: ch? l?y theo DM_TOI_DANHS.TD_CHUONG = '23'
           MAX(CASE WHEN e.td_chuong = '23' THEN 1 ELSE 0 END) AS flg_nhung_chuc_vu,
           -- Các t?i khác: TD_CHUONG không thu?c nhóm ?ã có c?t riêng (13,14,16,18,20,23), ho?c không xác ??nh ???c t?i danh
           MAX(CASE WHEN e.td_chuong IS NULL OR e.td_chuong NOT IN ('13','14','16','18','20','23') THEN 1 ELSE 0 END) AS flg_toi_khac
    FROM toi_danh_expanded e
    GROUP BY e.pn_lai_lich_id, e.pn_dot_dac_xa_id, e.ngay_xet, e.ddx_nam_dac_xa, e.ddx_ten_dot, e.trai_giam_id, e.ten_trai_giam, e.phan_doi_id, e.phan_doi, e.PHAM_NHAN_ID, e.HO_TEN, e.GIOI_TINH, e.NAM_SINH, e.TOI_DANH, e.toi_danh_id, e.AN_PHAT, e.dx_xep_loai_cai_tao, e.QUOC_TICH, e.quoc_tich_id, e.dm_ton_giao_id, e.dm_dan_toc_id, e.TON_GIAO, e.DAN_TOC, e.NHAN_THAN, e.BENH_HIEN_TAI, e.NOI_THUONG_TRU_DAY_DU, e.NGHE_NGHIEP, e.NGAY_BAT_AN_PHAT, e.DA_GIAM, e.NGAY_DEN_TRAI, e.NOI_THA_VE_CU_TRU, e.TINH_THANH_CU_TRU, e.tuoi, e.is_nam, e.is_nu, e.has_tien_an
),
-- Parse ll_ghi_chu_rieng (chu?i id t? PN_LAI_LICHS, map DM_GHI_CHU_RIENGS) thành danh sách gcr_id
gcr_raw AS (
    SELECT b.pn_lai_lich_id,
           REGEXP_REPLACE(NVL(TRIM(b.ghi_chu_rieng), ''), '[[:space:]\[\]]', '') AS gcr_clean,
           ROW_NUMBER() OVER (ORDER BY b.pn_lai_lich_id) AS row_id
    FROM base b
),
gcr_ids AS (
    SELECT r.pn_lai_lich_id,
           TO_NUMBER(REGEXP_SUBSTR(r.gcr_clean, '[0-9]+', 1, LEVEL)) AS gcr_id
    FROM gcr_raw r
    WHERE r.gcr_clean IS NOT NULL
      AND REGEXP_COUNT(r.gcr_clean, '[0-9]+') > 0
    CONNECT BY PRIOR r.pn_lai_lich_id = r.pn_lai_lich_id
       AND PRIOR r.row_id = r.row_id
       AND PRIOR SYS_GUID() IS NOT NULL
       AND LEVEL <= REGEXP_COUNT(r.gcr_clean, '[0-9]+')
),
-- Join DM_GHI_CHU_RIENGS ?? phân lo?i tình ti?t ?u tiên theo GCR_MA (mã nghi?p v?, prefix 2 s? = nhóm),
-- không hardcode ID vì ID là khoá surrogate, không ?n ??nh/không t? mô t? ý ngh?a.
gcr_classified AS (
    SELECT i.pn_lai_lich_id,
           CASE
               WHEN SUBSTR(TRIM(dgcr.GCR_MA), 1, 2) = '11' THEN 'HUAN_CHUONG'         -- Huân/huy ch??ng (k? c? kháng chi?n)
               WHEN SUBSTR(TRIM(dgcr.GCR_MA), 1, 2) = '18' THEN 'THUONG_BINH'         -- Th??ng binh, b?nh binh
               WHEN SUBSTR(TRIM(dgcr.GCR_MA), 1, 2) = '17' THEN 'LAP_CONG'            -- L?p công
               WHEN TRIM(dgcr.GCR_MA) = '1610' THEN 'TU_70'                           -- T? 70 tu?i tr? lên
               WHEN TRIM(dgcr.GCR_MA) IN ('1900','1910','1920') THEN 'DUOI_18_PHAM_TOI' -- D??i 18 tu?i khi ph?m t?i
               WHEN TRIM(dgcr.GCR_MA) = '1930' THEN 'DUOI_18_CHAP_HANH'               -- Hi?n d??i 18 tu?i ?ang ch?p hành án
               WHEN SUBSTR(TRIM(dgcr.GCR_MA), 1, 2) = '15' THEN 'GIA_DINH_LIET_SY'    -- Thân nhân là li?t s?
               WHEN TRIM(dgcr.GCR_MA) = '1620' THEN 'OM_DAU' 
               WHEN SUBSTR(TRIM(dgcr.GCR_MA), 1, 2) = '13' THEN 'BENH_HIEM_NGHEO'     -- M?c b?nh hi?m nghèo
               WHEN SUBSTR(TRIM(dgcr.GCR_MA), 1, 2) = '12' THEN 'CON_ME_VNAH'         -- Con Bà m? Vi?t Nam Anh hùng
               WHEN TRIM(dgcr.GCR_MA) IN ('2500','9901') THEN 'GIA_DINH_CONG'         -- Gia ?ình có công v?i n??c
               WHEN TRIM(dgcr.GCR_MA) IN ('1400','1420') THEN 'HOAN_CANH_KHO_KHAN'    -- Gia ?ình ??c bi?t khó kh?n / lao ??ng duy nh?t
               ELSE NULL
           END AS bucket
    FROM gcr_ids i
    JOIN QLPN.DM_GHI_CHU_RIENGS dgcr
        ON dgcr.ID = i.gcr_id AND NVL(dgcr.IS_DELETED, 0) = 0
),
gcr_flags AS (
    SELECT c.pn_lai_lich_id,
           MAX(CASE WHEN c.bucket = 'HUAN_CHUONG' THEN 1 ELSE 0 END) AS flg_huan_chuong,
           MAX(CASE WHEN c.bucket = 'THUONG_BINH' THEN 1 ELSE 0 END) AS flg_thuong_binh,
           MAX(CASE WHEN c.bucket = 'LAP_CONG' THEN 1 ELSE 0 END) AS flg_lap_cong,
           MAX(CASE WHEN c.bucket = 'TU_70' THEN 1 ELSE 0 END) AS flg_tu_70,
           MAX(CASE WHEN c.bucket = 'DUOI_18_PHAM_TOI' THEN 1 ELSE 0 END) AS flg_duoi_18_pham_toi,
           MAX(CASE WHEN c.bucket = 'DUOI_18_CHAP_HANH' THEN 1 ELSE 0 END) AS flg_duoi_18_chap_hanh_gcr,
           MAX(CASE WHEN c.bucket = 'GIA_DINH_LIET_SY' THEN 1 ELSE 0 END) AS flg_gia_dinh_liet_sy,
           MAX(CASE WHEN c.bucket = 'OM_DAU' THEN 1 ELSE 0 END) AS flg_om_dau,
           MAX(CASE WHEN c.bucket = 'BENH_HIEM_NGHEO' THEN 1 ELSE 0 END) AS flg_benh_hiem_ngheo,
           MAX(CASE WHEN c.bucket = 'CON_ME_VNAH' THEN 1 ELSE 0 END) AS flg_con_me_vnah,
           MAX(CASE WHEN c.bucket = 'GIA_DINH_CONG' THEN 1 ELSE 0 END) AS flg_gia_dinh_cong,
           MAX(CASE WHEN c.bucket = 'HOAN_CANH_KHO_KHAN' THEN 1 ELSE 0 END) AS flg_hoan_canh_kho_khan,
           -- flg_tinh_tiet_khac: có ghi chú riêng nh?ng không kh?p bucket nào ? trên (t? ??ng, không c?n li?t kê lo?i tr?)
           MAX(CASE WHEN c.bucket IS NULL THEN 1 ELSE 0 END) AS flg_tinh_tiet_khac
    FROM gcr_classified c
    GROUP BY c.pn_lai_lich_id
),
uu_tien AS (
    SELECT t.pn_lai_lich_id, t.pn_dot_dac_xa_id, t.ddx_nam_dac_xa, t.ddx_ten_dot, t.trai_giam_id, t.ten_trai_giam, t.phan_doi_id, t.phan_doi, t.PHAM_NHAN_ID, t.HO_TEN, t.GIOI_TINH, t.NAM_SINH, t.TOI_DANH, t.toi_danh_id, t.AN_PHAT, t.QUOC_TICH, t.quoc_tich_id, t.dm_ton_giao_id, t.dm_dan_toc_id, t.TON_GIAO, t.DAN_TOC, t.NHAN_THAN, t.BENH_HIEN_TAI, t.NOI_THUONG_TRU_DAY_DU, t.NGHE_NGHIEP, t.NGAY_BAT_AN_PHAT, t.DA_GIAM, t.NGAY_DEN_TRAI, t.NOI_THA_VE_CU_TRU, t.TINH_THANH_CU_TRU, t.ngay_xet, t.tuoi, t.is_nam, t.is_nu, t.has_tien_an, t.flg_chung_than_uu_tien, t.dx_xep_loai_cai_tao, t.flg_toi_anqg, t.flg_giet_nguoi, t.flg_hiep_dam, t.flg_hiep_dam_tre_em, t.flg_mua_ban_nguoi, t.flg_gay_thuong_tich, t.flg_toi_khac_tm_sk_dd_np, t.flg_cuop_tai_san, t.flg_cuop_giat, t.flg_trom_cap, t.flg_bat_coc, t.flg_lua_dao, t.flg_toi_khac_so_huu, t.flg_mua_ban_ma_tuy, t.flg_san_xuat_ma_tuy, t.flg_to_chuc_sd_ma_tuy, t.flg_chiem_doat_ma_tuy, t.flg_ma_tuy_khac, t.flg_toi_qlkt, t.flg_nhung_chuc_vu, t.flg_toi_khac,
           CASE WHEN t.tuoi IS NOT NULL AND t.tuoi >= 70 THEN 1 ELSE 0 END AS flg_tu_70_uu_tien,
           CASE WHEN t.tuoi IS NOT NULL AND t.tuoi < 18 THEN 1 ELSE 0 END AS flg_duoi_18_chap_hanh
    FROM toi_danh_flags t
),
-- Th?i l??ng án (tháng) t? chu?i AN_PHAT — cùng quy ??c PKG_TINH_AN.FN_GET_MUC_AN_ID_TU_AN_PHAT
an_phat_parsed AS (
    SELECT u.*,
           NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(u.AN_PHAT AS NVARCHAR2(2000)), 'NAM'), 0) AS ap_nam,
           NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(u.AN_PHAT AS NVARCHAR2(2000)), 'THANG'), 0) AS ap_thang,
           NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(u.AN_PHAT AS NVARCHAR2(2000)), 'NGAY'), 0) AS ap_ngay
    FROM uu_tien u
),
an_phat_metrics AS (
    SELECT p.*,
           (p.ap_nam * 12 + p.ap_thang + p.ap_ngay / 30.0) AS tha_thang_tong
    FROM an_phat_parsed p
),
detail AS (
SELECT
    u.pn_dot_dac_xa_id,
    u.ddx_nam_dac_xa,
    u.ddx_ten_dot,
    u.trai_giam_id,
    u.ten_trai_giam,
    u.phan_doi_id,
    u.phan_doi,
    u.pn_lai_lich_id,
    u.PHAM_NHAN_ID,
    u.HO_TEN,
    u.GIOI_TINH,
    u.NAM_SINH,
    u.ngay_xet,
    u.NOI_THUONG_TRU_DAY_DU,
    u.NGHE_NGHIEP,
    u.TOI_DANH,
    u.AN_PHAT,
    u.NGAY_BAT_AN_PHAT,
    u.DA_GIAM,
    u.NGAY_DEN_TRAI,
    u.NOI_THA_VE_CU_TRU,
    u.TINH_THANH_CU_TRU,
    u.is_nam AS flg_nam,
    u.is_nu AS flg_nu,
    1 AS flg_tong,
    u.flg_toi_anqg,
    u.flg_giet_nguoi,
    u.flg_hiep_dam,
    u.flg_hiep_dam_tre_em,
    u.flg_mua_ban_nguoi,
    u.flg_gay_thuong_tich,
    u.flg_toi_khac_tm_sk_dd_np,
    u.flg_cuop_tai_san,
    u.flg_cuop_giat,
    u.flg_trom_cap,
    u.flg_bat_coc,
    u.flg_lua_dao,
    u.flg_toi_khac_so_huu,
    u.flg_mua_ban_ma_tuy,
    u.flg_san_xuat_ma_tuy,
    u.flg_to_chuc_sd_ma_tuy,
    u.flg_chiem_doat_ma_tuy,
    u.flg_ma_tuy_khac,
    u.flg_toi_qlkt,
    u.flg_nhung_chuc_vu,
    u.flg_toi_khac,
    -- M?c án theo th?i l??ng parse t? AN_PHAT (PN_THI_HANH_AN.THA_AN_PHAT); chung thân: u.flg_chung_than_uu_tien (mã án / chu?i)
    CASE WHEN NVL(u.flg_chung_than_uu_tien, 0) = 1 THEN 1 ELSE 0 END AS flg_chung_than,
    CASE
        WHEN NVL(u.flg_chung_than_uu_tien, 0) = 0
         AND u.tha_thang_tong > 180
         AND u.tha_thang_tong <= 360
        THEN 1 ELSE 0
    END AS flg_tren_15_30_nam,
    CASE
        WHEN NVL(u.flg_chung_than_uu_tien, 0) = 0
         AND u.tha_thang_tong >= 84
         AND u.tha_thang_tong <= 180
        THEN 1 ELSE 0
    END AS flg_tren_7_15_nam,
    CASE
        WHEN NVL(u.flg_chung_than_uu_tien, 0) = 0
         AND u.tha_thang_tong > 36
         AND u.tha_thang_tong < 84
        THEN 1 ELSE 0
    END AS flg_tren_3_7_nam,
    CASE
        WHEN NVL(u.flg_chung_than_uu_tien, 0) = 0
         AND u.tha_thang_tong > 0
         AND u.tha_thang_tong <= 36
        THEN 1 ELSE 0
    END AS flg_tu_3_nam_tro_xuong,
    CASE WHEN u.has_tien_an = 0 THEN 1 ELSE 0 END AS flg_khong_tien_an,
    u.has_tien_an AS flg_co_tien_an,
    CASE WHEN u.tuoi IS NOT NULL AND u.tuoi < 18 THEN 1 ELSE 0 END AS flg_duoi_18_tuoi,
    CASE WHEN u.tuoi IS NOT NULL AND u.tuoi >= 18 AND u.tuoi < 30 THEN 1 ELSE 0 END AS flg_tu_18_duoi_30,
    CASE WHEN u.tuoi IS NOT NULL AND u.tuoi >= 30 AND u.tuoi < 70 THEN 1 ELSE 0 END AS flg_tu_30_duoi_70,
    CASE WHEN u.tuoi IS NOT NULL AND u.tuoi >= 70 THEN 1 ELSE 0 END AS flg_tu_70_tro_len,
    GREATEST(0, NVL(g.flg_huan_chuong, 0)) AS flg_huan_chuong_khang_chien,
    GREATEST(0, NVL(g.flg_thuong_binh, 0)) AS flg_thuong_binh,
    GREATEST(0, NVL(g.flg_lap_cong, 0)) AS flg_lap_cong,
    GREATEST(u.flg_tu_70_uu_tien, NVL(g.flg_tu_70, 0)) AS flg_tu_70_uu_tien,
    GREATEST(0, NVL(g.flg_duoi_18_pham_toi, 0)) AS flg_duoi_18_pham_toi,
    GREATEST(u.flg_duoi_18_chap_hanh, NVL(g.flg_duoi_18_chap_hanh_gcr, 0)) AS flg_duoi_18_chap_hanh,
    NVL(g.flg_gia_dinh_liet_sy, 0) AS flg_gia_dinh_liet_sy,
    NVL(g.flg_om_dau, 0) AS flg_om_dau,
    NVL(g.flg_benh_hiem_ngheo, 0) AS flg_benh_hiem_ngheo,
    GREATEST(0, NVL(g.flg_con_me_vnah, 0)) AS flg_con_me_vnah,
    GREATEST(0, NVL(g.flg_gia_dinh_cong, 0)) AS flg_gia_dinh_cong,
    GREATEST(0, NVL(g.flg_hoan_canh_kho_khan, 0)) AS flg_hoan_canh_kho_khan,
    GREATEST(0, NVL(g.flg_tinh_tiet_khac, 0)) AS flg_tinh_tiet_khac,
    CASE WHEN qt.QT_MA IS NOT NULL AND TRIM(qt.QT_MA) <> '250' THEN 1 ELSE 0 END AS flg_quoc_tich_ngoai,
    CASE WHEN tg.TG_MA IS NOT NULL AND tg_k.tg_ma IS NULL THEN 1 ELSE 0 END AS flg_ton_giao,
    CASE WHEN dt.DT_MA IS NOT NULL AND dt_c.dt_ma IS NULL THEN 1 ELSE 0 END AS flg_dan_toc_it_nguoi,
    u.dx_xep_loai_cai_tao
FROM an_phat_metrics u
LEFT JOIN gcr_flags g ON g.pn_lai_lich_id = u.pn_lai_lich_id
LEFT JOIN QLPN.DM_QUOC_TICHS qt ON qt.ID = u.quoc_tich_id AND NVL(qt.IS_DELETED, 0) = 0
LEFT JOIN QLPN.DM_TON_GIAOS tg ON tg.ID = u.dm_ton_giao_id AND NVL(tg.IS_DELETED, 0) = 0
LEFT JOIN dm_ton_giao_khong tg_k ON tg_k.tg_ma = TRIM(tg.TG_MA)
LEFT JOIN QLPN.DM_DAN_TOCS dt ON dt.ID = u.dm_dan_toc_id AND NVL(dt.IS_DELETED, 0) = 0
LEFT JOIN dm_dan_toc_chinh dt_c ON dt_c.dt_ma = TRIM(dt.DT_MA)

)
SELECT
    pn_dot_dac_xa_id,
    MAX(ddx_nam_dac_xa) AS ddx_nam_dac_xa,
    MAX(ddx_ten_dot) AS ddx_ten_dot,
    MAX(trai_giam_id) AS trai_giam_id,
    MAX(ten_trai_giam) AS ten_trai_giam,
    MAX(phan_doi_id) AS phan_doi_id,
