--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."VW_BIEN_LAI_HINH_PHAT_BS" ("HPBS_MA_PHAM_NHAN", "DM_HPBS_ID", "DM_HPBS_MA", "DM_HPBS_TEN", "HPBS_ID", "HPBS_THOI_HAN", "HPBS_TONG_TIEN_PHAT", "HPBS_HE_SO", "HPBS_GHI_CHU", "HPBS_GHI_CHU_CHI_TIET", "HPBS_GHI_CHU_CHUNG_PHAM_NHAN", "BL_ID", "BL_SO_BIEN_LAI", "BL_NGAY_NOP", "BL_SO_TIEN", "BL_NOP_TAI_CO_QUAN", "BL_DIA_PHUONG", "BL_TRUONG_HOP_THUC_HIEN", "BL_GHI_CHU", "HPBS_CREATION_TIME", "HPBS_CREATOR_USER_ID", "HPBS_LAST_MODIFICATION_TIME", "HPBS_LAST_MODIFIER_USER_ID", "DM_HPBS_CREATION_TIME", "DM_HPBS_CREATOR_USER_ID", "DM_HPBS_LAST_MODIFICATION_TIME", "DM_HPBS_LAST_MODIFIER_USER_ID", "BL_CREATION_TIME", "BL_CREATOR_USER_ID", "BL_LAST_MODIFICATION_TIME", "BL_LAST_MODIFIER_USER_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    -- Ph?m nhân
    hp.HPBS_MA_PHAM_NHAN,

    -- Danh m?c hình ph?t b? sung
    dm.ID,
    dm.HPBS_MA,
    dm.HPBS_TEN,

    -- Hình ph?t b? sung (instance)
    hp.ID,
    hp.HPBS_THOI_HAN,
    hp.HPBS_TONG_TIEN_PHAT,
    hp.HPBS_HE_SO,
    hp.HPBS_GHI_CHU,
    hp.HPBS_GHI_CHU_CHI_TIET,
    hp.HPBS_GHI_CHU_CHUNG_PHAM_NHAN,

    -- Biên lai
    bl.ID,
    bl.BL_SO_BIEN_LAI,
    bl.BL_NGAY_NOP,
    bl.BL_SO_TIEN,
    bl.BL_NOP_TAI_CO_QUAN,
    bl.BL_DIA_PHUONG,
    bl.BL_TRUONG_HOP_THUC_HIEN,
    bl.BL_GHI_CHU,

    -- Audit hình ph?t b? sung
    hp.CREATION_TIME,
    hp.CREATOR_USER_ID,
    hp.LAST_MODIFICATION_TIME,
    hp.LAST_MODIFIER_USER_ID,

    -- Audit danh m?c
    dm.CREATION_TIME,
    dm.CREATOR_USER_ID,
    dm.LAST_MODIFICATION_TIME,
    dm.LAST_MODIFIER_USER_ID,

    -- Audit biên lai
    bl.CREATION_TIME,
    bl.CREATOR_USER_ID,
    bl.LAST_MODIFICATION_TIME,
    bl.LAST_MODIFIER_USER_ID
FROM
    PN_HINH_PHAT_BO_SUNGS hp
    LEFT JOIN DM_HINH_PHAT_BO_SUNGS dm
        ON hp.HPBS_HINH_PHAT = dm.ID
       AND dm.IS_DELETED = 0
    LEFT JOIN PN_BIENLAIES bl
        ON bl.HPBS_ID = hp.ID
       AND bl.IS_DELETED = 0
WHERE
    hp.IS_DELETED = 0
;
