    rt.ll_dia_chi_thuong_tru AS dia_chi_thuong_tru,
    rt.ll_dia_chi_thuong_tru_provice AS ll_dia_chi_thuong_tru_provice,
    rt.ll_dia_chi_thuong_tru_ward AS ll_dia_chi_thuong_tru_ward,
    dttp_thuong_tru.ttp_ten AS tinh_thanh_thuong_tru,
    dttp_thuong_tru.ttp_ma AS tinh_thanh_thuong_tru_ma,
    dxp_thuong_tru.xp_ten AS phuong_xa_thuong_tru,
    CASE
        WHEN NULLIF(TRIM(rt.ll_dia_chi_thuong_tru), u'') IS NOT NULL
          OR NULLIF(TRIM(dxp_thuong_tru.xp_ten), u'') IS NOT NULL
          OR NULLIF(TRIM(dttp_thuong_tru.ttp_ten), u'') IS NOT NULL
        THEN TRIM(
            NVL(NULLIF(TRIM(rt.ll_dia_chi_thuong_tru), u''), u'')
            || CASE
                WHEN NULLIF(TRIM(dxp_thuong_tru.xp_ten), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(rt.ll_dia_chi_thuong_tru), u'') IS NOT NULL
                        THEN u', ' || dxp_thuong_tru.xp_ten
                        ELSE dxp_thuong_tru.xp_ten
                    END
                ELSE u''
               END
            || CASE
                WHEN NULLIF(TRIM(dttp_thuong_tru.ttp_ten), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(rt.ll_dia_chi_thuong_tru), u'') IS NOT NULL
                          OR NULLIF(TRIM(dxp_thuong_tru.xp_ten), u'') IS NOT NULL
                        THEN u', ' || dttp_thuong_tru.ttp_ten
                        ELSE dttp_thuong_tru.ttp_ten
                    END
                ELSE u''
               END
        )
        ELSE NULL
    END AS noi_thuong_tru_day_du,
    rt.tha_toi_danh_names toi_danh,
    rt.tha_toi_danh  toi_danh_id,
    rt.toi_danh_dau_tien,
    rt.tha_an_phat AS an_phat,
    rt.tha_ma_an_phat AS tha_ma_an_phat,
    rt.tha_muc_an_id AS muc_an_id,
    rt.tha_so_qd_dieu_chuyen AS so_qd_dieu_chuyen,
    rt.tha_ngay_qd_dieu_chuyen AS ngay_qd_dieu_chuyen,
    rt.tha_doi_tuong AS doi_tuong,
    rt.tha_ngay_bat AS ngay_bat_an_phat,
    rt.tha_thoi_gian_tam_giam AS thoi_gian_tam_giam,
    CAST(NULL AS VARCHAR2(1)) AS da_giam,
    rt.tha_ngay_den_trai AS ngay_den_trai,
    pd.pd_ten AS phan_doi,
    rt.ll_phan_doi_id AS phan_doi_id,
    rt.tha_ngay_het_han AS ngay_het_an,
    rt.ll_so_tien_an AS so_tien_an,
    rt.ll_ghi_chu_chi_tiet AS ghi_chu_chi_tiet,
    rt.ghi_chu,
    rt.ll_ghi_chu_rieng AS ghi_chu_rieng,
    traigiam.tg_ten AS trai_giam,
    rt.ll_trai_giam_id AS trai_giam_id,
    traigiam.tg_ma AS trai_giam_ma,
    plgg.plgg_ten AS phan_loai_giam_giu,
    pd.pd_ten AS pd_ten,
    pt.pt_ten AS phan_trai,
    tp.tp_ten AS tai_pham,
    ttbdv.ttbdv_ten AS tinh_trang_doc_viet,
    rt.ll_so_ho_so_lan_dau AS so_ho_so,
    rt.ll_anh AS ll_anh,
    rt.ll_cccd AS cccd,
    dt.dt_ten AS dan_toc,
    qt.qt_ten AS quoc_tich,
    rt.ll_dm_quoc_tich_id AS quoc_tich_id,
    tg.tg_ten AS ton_giao,
    hv.hv_ten AS hoc_van,
    nn.nn_ten AS nghe_nghiep,
