    rt.ll_noi_tha_ve_cu_tru_provice AS noi_tha_ve_cu_tru_tinh_id,
    rt.tha_so_ban_an AS so_ban_an,
    rt.tha_ngay_ban_an AS ngay_ban_an,
    toa_xu.cq_ten AS toa_xu_ten,
    toa_xu_dttp.ttp_ten AS toa_xu_dia_phuong,
    toa_qd.cq_ten AS co_quan_qd_tha,
    toa_qd_dttp.ttp_ten AS toa_qd_tha_dia_phuong,
    rt.ll_tinh_trang_id,
    ttpn.ttpn_ma as tinh_trang_ma,
    ttpn.ttpn_ten as tinh_trang_ten,
    rt.ll_nhan_than AS nhan_than,
    rt.tha_so_qd_tha AS so_qd_tha,
    rt.tha_ngay_qd_tha AS ngay_qd_tha,
    rt.tha_can_cu_tuyen_phat AS can_cu_tuyen_phat,
    rt.tha_dieu AS dieu,
    rt.tha_khoan AS khoan,
    dm_bt.bt_ten AS benh_hien_tai,
    CASE
        WHEN rt.ll_benh_hien_tai_id IS NULL OR dm_bt.bt_ma = 1 THEN u'Bình th??ng'
        ELSE dm_bt.bt_ten
    END AS tt_suc_khoe_hien_tai,
    rt.ll_so_tien_su AS so_tien_su,
    rt.ll_chi_tiet_hv AS chi_tiet_hanh_vi,
    rt.ll_tom_tat_hv AS tom_tat_hanh_vi,
    rt.tha_so_danh_ban AS so_danh_ban,
    rt.tha_ngay_lap_danh_ban AS ngay_lap_danh_ban,
    cq_lap.cq_ten AS co_quan_lap,
    rt.ll_pn_giao_nhan_phan_nhan_id AS giao_nhan_pham_nhan_id,
    rt.tha_loai_ban_an_id AS loai_ban_an_id,
    rt.tha_thoi_gian_tam_giu AS thoi_gian_tam_giu,
    cq_bat.cq_ten AS co_quan_bat,
    cq_bat_dttp.ttp_ten AS co_quan_bat_dia_phuong,
    rt.ll_so_ho_phu AS so_ho_phu,
    rt.ll_ho_chieu AS ho_chieu,
    rt.ll_noi_otruoc_khi_bat AS noi_otruoc_khi_bat,
    rt.ll_phan_trai_id AS ll_phan_trai_id,
    rt.ll_dm_dan_toc_id AS ll_dm_dan_toc_id,
    rt.ll_dm_ton_giao_id AS ll_dm_ton_giao_id,
    rt.ll_dm_hoc_van_id AS ll_dm_hoc_van_id,
    rt.ll_dm_nghe_nghiep_id AS ll_dm_nghe_nghiep_id,
    rt.ll_suc_khoe_khi_vao_id AS ll_suc_khoe_khi_vao_id,
    rt.ll_so_gcn AS ll_so_gcn,
    rt.ll_creation_time AS creation_time,
    rt.ll_last_modification_time AS last_modification_time,
    NVL(rt.ll_is_deleted, rt.is_deleted) AS is_deleted,
    rt.thoi_gian_da_giam AS thoi_gian_da_giam,
    rt.so_lan_giam AS so_lan_giam,
    mtgch.mtg_title AS thoi_gian_da_chap_hanh,
    mtgcl.mtg_title AS thoi_gian_con_lai,
    rt.tha_ghi_chu_dac_biet,
    rt.tha_ngay_pham_toi,
    rt.tha_thoi_gian_da_chap_hanh AS tha_tgdch_ma,
    rt.tha_thoi_gian_con_lai      AS tha_tgcl_ma,
    rt.tha_ngay_den_trai          AS tha_ngay_den_trai,
