    rt.LL_NOI_CAP_CCCD as noi_cap_cccd
FROM qlpn.pn_lai_lich_chi_tiet_rt rt
LEFT JOIN qlpn.dm_gioi_tinhs gt
    ON rt.ll_dm_gioi_tinh_id = gt.id
   AND gt.is_deleted = 0
LEFT JOIN qlpn.dm_dan_tocs dt
    ON rt.ll_dm_dan_toc_id = dt.id
   AND dt.is_deleted = 0
LEFT JOIN qlpn.dm_quoc_tichs qt
    ON rt.ll_dm_quoc_tich_id = qt.id
   AND qt.is_deleted = 0
LEFT JOIN qlpn.dm_ton_giaos tg
    ON rt.ll_dm_ton_giao_id = tg.id
   AND tg.is_deleted = 0
LEFT JOIN qlpn.dm_hoc_vans hv
    ON rt.ll_dm_hoc_van_id = hv.id
   AND hv.is_deleted = 0
LEFT JOIN qlpn.dm_nghe_nghieps nn
    ON rt.ll_dm_nghe_nghiep_id = nn.id
   AND nn.is_deleted = 0
LEFT JOIN qlpn.dm_tinh_trang_suc_khoe_pham_nhans ttsk
    ON rt.ll_suc_khoe_khi_vao_id = ttsk.id
   AND ttsk.is_deleted = 0
LEFT JOIN qlpn.dm_tinh_thanh_pho dttp_thuong_tru
    ON rt.ll_dia_chi_thuong_tru_provice = dttp_thuong_tru.id
   AND NVL(dttp_thuong_tru.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_xa_phuong dxp_thuong_tru
    ON rt.ll_dia_chi_thuong_tru_ward = dxp_thuong_tru.id
   AND NVL(dxp_thuong_tru.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_trai_giams traigiam
    ON rt.ll_trai_giam_id = traigiam.id
   AND traigiam.is_deleted = 0
LEFT JOIN (
    SELECT pl2.pham_nhan_id,
           pl2.den_loai_id
    FROM (
        SELECT pl_inner.*,
               ROW_NUMBER() OVER (
                   PARTITION BY pl_inner.pham_nhan_id
                   ORDER BY NVL(pl_inner.ngay_phan_loai, pl_inner.creation_time) DESC NULLS LAST,
                            pl_inner.id DESC
               ) AS rn
        FROM qlpn.phan_loais pl_inner
        WHERE NVL(pl_inner.is_deleted, 0) = 0
    ) pl2
    WHERE pl2.rn = 1
) pl
    ON rt.pham_nhan_id = pl.pham_nhan_id
LEFT JOIN qlpn.dm_phan_loai_giam_gius plgg
    ON pl.den_loai_id = plgg.id
   AND plgg.is_deleted = 0
LEFT JOIN qlpn.dm_phan_dois pd
    ON rt.ll_phan_doi_id = pd.id
   AND pd.is_deleted = 0
LEFT JOIN qlpn.dm_phan_trais pt
    ON rt.ll_phan_trai_id = pt.id
   AND pt.is_deleted = 0
LEFT JOIN qlpn.dm_tai_phams tp
    ON rt.ll_tai_pham = tp.id
   AND tp.is_deleted = 0
LEFT JOIN qlpn.dm_tinh_trang_biet_doc_viets ttbdv
    ON rt.ll_biet_doc_viet_id = ttbdv.id
   AND ttbdv.is_deleted = 0
LEFT JOIN qlpn.dm_co_quans toa_xu
    ON rt.tha_cap_toa_id = toa_xu.id
   AND toa_xu.is_deleted = 0
LEFT JOIN qlpn.dm_tinh_thanh_pho toa_xu_dttp
    ON rt.tha_dia_phuong_cap_toa_id = toa_xu_dttp.id
   AND NVL(toa_xu_dttp.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_co_quans toa_qd
    ON rt.tha_toa_qd_id = toa_qd.id
   AND toa_qd.is_deleted = 0
LEFT JOIN qlpn.dm_tinh_thanh_pho toa_qd_dttp
    ON rt.tha_dia_phuong_toa_qd_tha_id = toa_qd_dttp.id
   AND NVL(toa_qd_dttp.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_xa_phuong ntvct_dxp
    ON rt.ll_noi_tha_ve_cu_tru_ward = ntvct_dxp.id
   AND NVL(ntvct_dxp.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_tinh_thanh_pho ntvct_dttp
    ON rt.ll_noi_tha_ve_cu_tru_provice = ntvct_dttp.id
   AND NVL(ntvct_dttp.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_co_quans cq_bat
    ON rt.tha_co_quan_bat_id = cq_bat.id
   AND cq_bat.is_deleted = 0
LEFT JOIN qlpn.dm_tinh_thanh_pho cq_bat_dttp
    ON rt.tha_dia_phuong_co_quan_bat_id = cq_bat_dttp.id
   AND NVL(cq_bat_dttp.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_benh_tats dm_bt
    ON rt.ll_benh_hien_tai_id = dm_bt.id
   AND NVL(dm_bt.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_co_quans cq_lap
    ON rt.tha_co_quan_lap_id = cq_lap.id
   AND cq_lap.is_deleted = 0   
LEFT JOIN qlpn.dm_ma_thoi_gians mtgch
    ON mtgch.mtg_ma = rt.tha_thoi_gian_da_chap_hanh
   AND NVL(mtgch.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_ma_thoi_gians mtgcl
    ON mtgcl.mtg_ma = rt.tha_thoi_gian_con_lai
   AND NVL(mtgcl.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_tinh_trang_pham_nhans ttpn 
    ON ttpn.ID = rt.ll_tinh_trang_id
    AND ttpn.is_deleted = 0
;
