                WHEN NULLIF(TRIM(ntvct_dttp.ttp_ten), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(rt.ll_noi_tha_ve_cu_tru), u'') IS NOT NULL
                          OR NULLIF(TRIM(ntvct_dxp.xp_ten), u'') IS NOT NULL
                        THEN u', ' || ntvct_dttp.ttp_ten
                        ELSE ntvct_dttp.ttp_ten
                    END
                ELSE u''
               END
        )
        ELSE NULL
    END AS noi_tha_ve_cu_tru,
    ntvct_dxp.xp_ten AS noi_tha_ve_cu_tru_xa,
    rt.ll_noi_tha_ve_cu_tru_ward AS noi_tha_ve_cu_tru_xa_id,
    ntvct_dttp.ttp_ten AS noi_tha_ve_cu_tru_tinh,
    rt.ll_noi_tha_ve_cu_tru_provice AS noi_tha_ve_cu_tru_tinh_id,
    rt.tha_so_ban_an AS so_ban_an,
    rt.tha_ngay_ban_an AS ngay_ban_an,
    toa_xu.cq_ten AS toa_xu_ten,
    toa_xu_dttp.ttp_ten AS toa_xu_dia_phuong,
    toa_qd.cq_ten AS co_quan_qd_tha,
    toa_qd_dttp.ttp_ten AS toa_qd_tha_dia_phuong,
    rt.ll_tinh_trang_id,
    rt.ll_nhan_than AS nhan_than,
    rt.tha_so_qd_tha AS so_qd_tha,
    rt.tha_ngay_qd_tha AS ngay_qd_tha,
    rt.tha_can_cu_tuyen_phat AS can_cu_tuyen_phat,
    rt.tha_dieu AS dieu,
    rt.tha_khoan AS khoan,
    dm_bt.bt_ten AS benh_hien_tai,
    CASE
        WHEN rt.ll_benh_hien_tai_id IS NULL OR dm_bt.bt_ma = 1 THEN u'Bình th??ng'
        ELSE dm_bt.bt_ten
    END AS tt_suc_khoe_hien_tai,
    rt.ll_so_tien_su AS so_tien_su,
    rt.ll_chi_tiet_hv AS chi_tiet_hanh_vi,
    rt.ll_tom_tat_hv AS tom_tat_hanh_vi,
    rt.tha_so_danh_ban AS so_danh_ban,
    rt.ll_pn_giao_nhan_phan_nhan_id AS giao_nhan_pham_nhan_id,
    rt.tha_loai_ban_an_id AS loai_ban_an_id,
    rt.tha_thoi_gian_tam_giu AS thoi_gian_tam_giu,
    cq_bat.cq_ten AS co_quan_bat,
    cq_bat_dttp.ttp_ten AS co_quan_bat_dia_phuong,
    rt.ll_so_ho_phu AS so_ho_phu,
    rt.ll_ho_chieu AS ho_chieu,
    rt.ll_noi_otruoc_khi_bat AS noi_otruoc_khi_bat,
    rt.ll_phan_trai_id AS ll_phan_trai_id,
    rt.ll_dm_dan_toc_id AS ll_dm_dan_toc_id,
    rt.ll_dm_ton_giao_id AS ll_dm_ton_giao_id,
    rt.ll_dm_hoc_van_id AS ll_dm_hoc_van_id,
    rt.ll_dm_nghe_nghiep_id AS ll_dm_nghe_nghiep_id,
    rt.ll_suc_khoe_khi_vao_id AS ll_suc_khoe_khi_vao_id,
    rt.ll_so_gcn AS ll_so_gcn,
    rt.ll_creation_time AS creation_time,
    rt.ll_last_modification_time AS last_modification_time,
    NVL(rt.ll_is_deleted, rt.is_deleted) AS is_deleted,
    THOI_GIAN_DA_GIAM,
    SO_LAN_GIAM
FROM qlpn.pn_lai_lich_chi_tiet_rt rt
LEFT JOIN qlpn.dm_gioi_tinhs gt
    ON rt.ll_dm_gioi_tinh_id = gt.id
   AND gt.is_deleted = 0
LEFT JOIN qlpn.dm_dan_tocs dt
    ON rt.ll_dm_dan_toc_id = dt.id
   AND dt.is_deleted = 0
LEFT JOIN qlpn.dm_quoc_tichs qt
    ON rt.ll_dm_quoc_tich_id = qt.id
   AND qt.is_deleted = 0
LEFT JOIN qlpn.dm_ton_giaos tg
    ON rt.ll_dm_ton_giao_id = tg.id
   AND tg.is_deleted = 0
LEFT JOIN qlpn.dm_hoc_vans hv
    ON rt.ll_dm_hoc_van_id = hv.id
   AND hv.is_deleted = 0
LEFT JOIN qlpn.dm_nghe_nghieps nn
    ON rt.ll_dm_nghe_nghiep_id = nn.id
   AND nn.is_deleted = 0
LEFT JOIN qlpn.dm_tinh_trang_suc_khoe_pham_nhans ttsk
    ON rt.ll_suc_khoe_khi_vao_id = ttsk.id
   AND ttsk.is_deleted = 0
LEFT JOIN qlpn.dm_tinh_thanh_pho dttp_thuong_tru
    ON rt.ll_dia_chi_thuong_tru_provice = dttp_thuong_tru.id
   AND NVL(dttp_thuong_tru.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_xa_phuong dxp_thuong_tru
    ON rt.ll_dia_chi_thuong_tru_ward = dxp_thuong_tru.id
   AND NVL(dxp_thuong_tru.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_trai_giams traigiam
    ON rt.ll_trai_giam_id = traigiam.id
   AND traigiam.is_deleted = 0
LEFT JOIN (
    SELECT pl2.pham_nhan_id,
           pl2.den_loai_id
    FROM (
        SELECT pl_inner.*,
               ROW_NUMBER() OVER (
                   PARTITION BY pl_inner.pham_nhan_id
                   ORDER BY NVL(pl_inner.ngay_phan_loai, pl_inner.creation_time) DESC NULLS LAST,
                            pl_inner.id DESC
               ) AS rn
        FROM qlpn.phan_loais pl_inner
        WHERE NVL(pl_inner.is_deleted, 0) = 0
    ) pl2
    WHERE pl2.rn = 1
) pl
    ON rt.pham_nhan_id = pl.pham_nhan_id
LEFT JOIN qlpn.dm_phan_loai_giam_gius plgg
    ON pl.den_loai_id = plgg.id
   AND plgg.is_deleted = 0
LEFT JOIN qlpn.dm_phan_dois pd
    ON rt.ll_phan_doi_id = pd.id
   AND pd.is_deleted = 0
LEFT JOIN qlpn.dm_phan_trais pt
    ON rt.ll_phan_trai_id = pt.id
   AND pt.is_deleted = 0
LEFT JOIN qlpn.dm_tai_phams tp
    ON rt.ll_tai_pham = tp.id
   AND tp.is_deleted = 0
LEFT JOIN qlpn.dm_tinh_trang_biet_doc_viets ttbdv
    ON rt.ll_biet_doc_viet_id = ttbdv.id
   AND ttbdv.is_deleted = 0
LEFT JOIN qlpn.dm_co_quans toa_xu
    ON rt.tha_cap_toa_id = toa_xu.id
   AND toa_xu.is_deleted = 0
LEFT JOIN qlpn.dm_tinh_thanh_pho toa_xu_dttp
    ON rt.tha_dia_phuong_cap_toa_id = toa_xu_dttp.id
   AND NVL(toa_xu_dttp.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_co_quans toa_qd
    ON rt.tha_toa_qd_id = toa_qd.id
   AND toa_qd.is_deleted = 0
LEFT JOIN qlpn.dm_tinh_thanh_pho toa_qd_dttp
    ON rt.tha_dia_phuong_toa_qd_tha_id = toa_qd_dttp.id
   AND NVL(toa_qd_dttp.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_xa_phuong ntvct_dxp
    ON rt.ll_noi_tha_ve_cu_tru_ward = ntvct_dxp.id
   AND NVL(ntvct_dxp.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_tinh_thanh_pho ntvct_dttp
    ON rt.ll_noi_tha_ve_cu_tru_provice = ntvct_dttp.id
   AND NVL(ntvct_dttp.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_co_quans cq_bat
    ON rt.tha_co_quan_bat_id = cq_bat.id
   AND cq_bat.is_deleted = 0
LEFT JOIN qlpn.dm_tinh_thanh_pho cq_bat_dttp
    ON rt.tha_dia_phuong_co_quan_bat_id = cq_bat_dttp.id
   AND NVL(cq_bat_dttp.is_deleted, 0) = 0
LEFT JOIN qlpn.dm_benh_tats dm_bt
    ON rt.ll_benh_hien_tai_id = dm_bt.id
   AND NVL(dm_bt.is_deleted, 0) = 0
;
--------------------------------------------------------
--  DDL for View VW_PN_THA_CO_DK
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."VW_PN_THA_CO_DK" ("PHAM_NHAN_ID", "DA_GIAM", "MUC_AN_ID", "SO_TIEN_AN", "NGAY_BAT", "AN_PHAT", "NMT_ID", "PHAN_TRAI", "PHAN_DOI", "HINH_PHAT_BO_SUNG", "HPBS_SO_TIEN_CAN_DONG") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    -- 1. THA_PHAM_NHAN_ID
    ptha.THA_PNLAI_LICH_ID AS PHAM_NHAN_ID,

    -- 2. THA_TONG_AN_GIAM
    CASE
    	WHEN LOWER(ptha.THA_TONG_AN_GIAM) = u'0 ng\00e0y' THEN u'Kh\00f4ng'
    	ELSE ptha.THA_TONG_AN_GIAM
    END
    AS DA_GIAM,

    -- 3. THA_MUC_AN_ID
    ptha.THA_MUC_AN_ID AS MUC_AN_ID,

    -- 4. LL_SO_TIEN_AN
    pll.LL_SO_TIEN_AN AS SO_TIEN_AN,

    -- 5. THA_NGAY_BAT
    ptha.THA_NGAY_BAT AS NGAY_BAT,

    -- 6. THA_AN_PHAT
    ptha.THA_AN_PHAT AS AN_PHAT,

    -- 7. NMT_ID
    pnm.ID AS NMT_ID,

    -- 8. PHAN_TRAI
    pll.LL_PHAN_TRAI_ID AS PHAN_TRAI,

    -- 9. PHAN_DOI
    pll.LL_PHAN_DOI_ID AS PHAN_DOI,

    -- 10. HINH_PHAT_BO_SUNG
    FN_GET_LIET_KE_HPBS_CHI_TIET(ptha.THA_PNLAI_LICH_ID) AS HINH_PHAT_BO_SUNG,

    -- 11. HPBS_SO_TIEN_CAN_DONG
    FN_GET_SO_DU_HPBS(ptha.THA_PNLAI_LICH_ID) AS SO_DU_HPBS
FROM PN_THI_HANH_AN ptha
LEFT JOIN PN_NGHIEN_MT pnm
       ON pnm.NMT_PN_LAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
LEFT JOIN PN_LAI_LICHS pll
       ON pll.ID = ptha.THA_PNLAI_LICH_ID
WHERE ptha.IS_DELETED = 0
;
--------------------------------------------------------
--  DDL for View VW_PN_TOI_DANH
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."VW_PN_TOI_DANH" ("PN_ID", "GIOI_TINH_ID", "TOI_DANH_IDS", "TOI_DANH_TENS") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  WITH SPLIT_TOI_DANH AS (
    SELECT
        ptha.THA_PNLAI_LICH_ID,
        TO_NUMBER(
            REGEXP_SUBSTR(
                REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
                '[0-9]+',
                1,
                LEVEL
            )
        ) AS TOI_DANH_ID
    FROM PN_THI_HANH_AN ptha
    WHERE ptha.THA_TOI_DANH IS NOT NULL
    CONNECT BY LEVEL <= REGEXP_COUNT(
            REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
            ','
        ) + 1
       AND PRIOR ptha.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
       AND PRIOR SYS_GUID() IS NOT NULL
)
SELECT
    pll.ID AS PN_ID,
    pll.LL_DM_GIOI_TINH_ID AS GIOI_TINH_ID,
    /* g?p mã t?i danh */
    LISTAGG(DISTINCT dtd.ID, ',')
        WITHIN GROUP (ORDER BY dtd.ID) AS TOI_DANH_IDS,
    /* g?p tên t?i danh */
    LISTAGG(DISTINCT dtd.TD_TEN, ', ')
        WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH_TENS
FROM SPLIT_TOI_DANH s
JOIN PN_LAI_LICHS pll
    ON pll.ID = s.THA_PNLAI_LICH_ID
JOIN DM_TOI_DANHS dtd
    ON dtd.ID = s.TOI_DANH_ID
GROUP BY
    pll.ID,
    pll.LL_DM_GIOI_TINH_ID
;
--------------------------------------------------------
--  DDL for View VW_PN_TOI_DANH_CHUONG
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."VW_PN_TOI_DANH_CHUONG" ("PN_ID", "TOI_DANH_ID", "TRAI_GIAM_ID", "TEN_CHUONG_TOI_DANH", "TEN_CHUONG", "TEN_TOI_DANH") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    pll.ID                  AS PN_ID,

    TO_NUMBER(
        REGEXP_SUBSTR(
            REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
            '[^,]+',
            1,
            1
        )
    )                       AS TOI_DANH_ID,

    pll.LL_TRAI_GIAM_ID     AS TRAI_GIAM_ID,
	dctd.CTD_TEN AS 		TEN_CHUONG_TOI_DANH,
    dtd.TD_CHUONG           AS TEN_CHUONG,
    dtd.TD_TEN              AS TEN_TOI_DANH   -- thêm dòng này

FROM PN_LAI_LICHS pll

LEFT JOIN PN_THI_HANH_AN ptha
    ON ptha.THA_PNLAI_LICH_ID = pll.ID 
   


LEFT JOIN DM_TOI_DANHS dtd
    ON dtd.ID = TO_NUMBER(
        REGEXP_SUBSTR(
            REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
            '[^,]+',
            1,
            1
        )
    ) 
LEFT JOIN DM_CHUONG_TOI_DANHS dctd
ON dtd.TD_CHUONG = dctd.CTD_MA
;
--------------------------------------------------------
--  DDL for View VW_QLPN_DASHBOARD
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."VW_QLPN_DASHBOARD" ("SO_PN_THANG_TRUOC_CHUYEN_SANG", "SO_TANG_TRONG_THANG", "SO_GIAM_TRONG_THANG", "DANG_CHAP_HANH_AN") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  WITH
    -- ----------------------------------------------------------------
    -- Date boundaries for the current month
    -- ----------------------------------------------------------------
    THANG AS (
        SELECT TRUNC(SYSDATE, 'MM') AS TU_NGAY,
               LAST_DAY(SYSDATE)    AS DEN_NGAY
        FROM DUAL
    ),

    -- ================================================================
    -- T?NG sub-components
    -- ================================================================

    -- Row 1: S? tháng tr??c chuy?n sang
    --        Prisoners active (status '111'..'114') at TU_NGAY - 1
    TANG_1 AS (
        SELECT COUNT(*) AS V
        FROM QLPN.PN_LAI_LICHS LL
        CROSS JOIN THANG
        WHERE NVL(LL.IS_DELETED, 0) = 0
          AND QLPN.FN_GET_TINH_TRANG_TAI_NGAY_XET(LL.ID, THANG.TU_NGAY - 1)
              IN ('111', '112', '113', '114')
    ),
    -- Row 2: Tr?i t?m giam chuy?n ??n — stub = 0 (MA_LOAI_DOI_TUONG unmapped)

    -- Row 3: Tr?i giam khác chuy?n ??n
    TANG_3 AS (
        SELECT COUNT(*) AS V
        FROM QLPN.PHAM_NHAN_CHUYEN_TRAI CT
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = CT.PNCT_LAI_LICH_ID
        CROSS JOIN THANG
        WHERE CAST(CT.PNCT_NGAY_CHUYEN AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND NVL(CT.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),
    -- Row 4: Tr?n b?t l?i
    TANG_4 AS (
        SELECT COUNT(*) AS V
        FROM QLPN.TRON_TRAIS TT
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TT.PHAM_NHAN_ID
        CROSS JOIN THANG
        WHERE CAST(TT.NGAY_BAT_LAI AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND NVL(TT.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),
    -- Row 5: T?m ?ình ch? tr? l?i
    TANG_5 AS (
        SELECT COUNT(*) AS V
        FROM QLPN.TAM_DINH_CHIS TDC
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TDC.PHAM_NHAN_ID
        CROSS JOIN THANG
        WHERE CAST(TDC.NGAY_LAI AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND TDC.LOAI_QUYET_DINH_ID = 1
          AND NVL(TDC.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),
    -- Row 6: Trích xu?t tr? l?i
    TANG_6 AS (
        SELECT COUNT(*) AS V
        FROM QLPN.TRICH_XUATS TX
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TX.PHAM_NHAN_ID
        CROSS JOIN THANG
        WHERE CAST(TX.TX_NGAY_TRA AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND TX.TX_LOAI_LENH_ID = 1
          AND NVL(TX.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),
    -- Row 7a: Hu? án tr? l?i
    TANG_7A AS (
        SELECT COUNT(*) AS V
        FROM QLPN.HUY_ANS HA
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = HA.PHAM_NHAN_ID
        CROSS JOIN THANG
        WHERE CAST(HA.NGAY_TRO_LAI AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND NVL(HA.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),
    -- Row 7b: Tha có ?i?u ki?n tr? l?i
    TANG_7B AS (
        SELECT COUNT(*) AS V
        FROM QLPN.THA_CO_DIEU_KIENS TCK
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TCK.PHAM_NHAN_ID
        CROSS JOIN THANG
        WHERE CAST(TCK.NGAY_BAT_LAI AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND NVL(TCK.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),
    -- Row 7c: Ch?a b?nh b?t bu?c k?t thúc tr? l?i
    TANG_7C AS (
        SELECT COUNT(*) AS V
        FROM QLPN.CHUA_BENH_BAT_BUOCS CB
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = CB.PHAM_NHAN_ID
        CROSS JOIN THANG
        WHERE CAST(CB.NGAY_KET_THUC AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND NVL(CB.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),

    -- ================================================================
    -- GI?M sub-components
    -- ================================================================

    -- Row 9: Tha (??c xá / gi?m h?t án / tha có ?i?u ki?n, tr? mi?n HP và còn ?ang t?m trích)
    GIAM_9 AS (
        SELECT COUNT(*) AS V
        FROM (
            SELECT PN_LAI_LICH_ID
            FROM (
                SELECT DX.PNLAI_LICH_ID AS PN_LAI_LICH_ID
                FROM QLPN.PN_DAC_XAS DX
                JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = DX.PNLAI_LICH_ID
                CROSS JOIN THANG
                WHERE CAST(DX.DX_NGAY_THA AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                  AND NVL(DX.IS_DELETED, 0) = 0
                  AND NVL(LL.IS_DELETED, 0) = 0
                UNION
                SELECT GTH.PHAM_NHAN_ID
                FROM QLPN.GIAM_THOI_HANS GTH
                JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = GTH.PHAM_NHAN_ID
                CROSS JOIN THANG
                WHERE CAST(GTH.NGAY_THA_GIAM_HET_AN AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                  AND NVL(GTH.IS_DELETED, 0) = 0
                  AND NVL(LL.IS_DELETED, 0) = 0
                UNION
                SELECT TCK.PHAM_NHAN_ID
                FROM QLPN.THA_CO_DIEU_KIENS TCK
                JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TCK.PHAM_NHAN_ID
                CROSS JOIN THANG
                WHERE CAST(TCK.NGAY_THA AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                  AND NVL(TCK.IS_DELETED, 0) = 0
                  AND NVL(LL.IS_DELETED, 0) = 0
            )
            MINUS
            (
                SELECT MHP.PN_LAI_LICH_ID
                FROM QLPN.MIEN_HINH_PHATS MHP
                JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = MHP.PN_LAI_LICH_ID
                CROSS JOIN THANG
                WHERE CAST(MHP.MHP_NGAY_TU_DO AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                  AND NVL(MHP.IS_DELETED, 0) = 0
                  AND NVL(LL.IS_DELETED, 0) = 0
                UNION
                SELECT CB.PHAM_NHAN_ID
                FROM QLPN.CHUA_BENH_BAT_BUOCS CB
                CROSS JOIN THANG
                WHERE CB.NGAY_KET_THUC IS NULL
                   OR CAST(CB.NGAY_KET_THUC AS DATE) > THANG.DEN_NGAY
                UNION
                SELECT TX.PHAM_NHAN_ID
                FROM QLPN.TRICH_XUATS TX
                CROSS JOIN THANG
                WHERE TX.TX_LOAI_LENH_ID = 1
                  AND (TX.TX_NGAY_TRA IS NULL
                       OR CAST(TX.TX_NGAY_TRA AS DATE) > THANG.DEN_NGAY)
            )
        )
    ),
    -- Row 10: Tr?n
    GIAM_10 AS (
        SELECT COUNT(*) AS V
        FROM QLPN.TRON_TRAIS TT
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TT.PHAM_NHAN_ID
        CROSS JOIN THANG
        WHERE CAST(TT.NGAY_TRON AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND NVL(TT.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),
    -- Row 11: Ch?t (tr? THC_MA '30','40','50')
    GIAM_11 AS (
        SELECT COUNT(*) AS V
        FROM QLPN.PN_KET_THUC_CHETS KC
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = KC.KTC_PN_LAI_LICH_ID
        LEFT JOIN QLPN.DM_TRUONG_HOP_CHETS THC ON THC.ID = KC.KTC_DM_TRUONG_HOP_CHET_ID
        CROSS JOIN THANG
        WHERE CAST(KC.KTC_NGAY_CHET AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND NVL(THC.THC_MA, '10') NOT IN ('30', '40', '50')
          AND NVL(KC.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),
    -- Row 12: Trích xu?t ?i
    GIAM_12 AS (
        SELECT COUNT(*) AS V
        FROM QLPN.TRICH_XUATS TX
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TX.PHAM_NHAN_ID
        CROSS JOIN THANG
        WHERE CAST(TX.TX_NGAY_TRICH_XUAT AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND TX.TX_LOAI_LENH_ID = 1
          AND NVL(TX.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),
    -- Row 13: T?m ?ình ch? ?i
    GIAM_13 AS (
        SELECT COUNT(*) AS V
        FROM QLPN.TAM_DINH_CHIS TDC
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TDC.PHAM_NHAN_ID
        CROSS JOIN THANG
        WHERE CAST(TDC.NGAY_TDC AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND TDC.LOAI_QUYET_DINH_ID = 1
          AND NVL(TDC.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),
    -- Row 14: Chuy?n tr?i (THCT_MA IN '10','20','90')
    GIAM_14 AS (
        SELECT COUNT(*) AS V
        FROM QLPN.PHAM_NHAN_CHUYEN_TRAI CT
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = CT.PNCT_LAI_LICH_ID
        LEFT JOIN QLPN.DM_TRUONG_HOP_CHUYEN_TRAIS THCT
               ON THCT.ID = CT.PNCT_TRUONG_HOP_CHUYEN_ID
        CROSS JOIN THANG
        WHERE CAST(CT.PNCT_NGAY_CHUYEN AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND NVL(THCT.THCT_MA, '10') IN ('10', '20', '90')
          AND NVL(CT.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),
    -- Row 15a: Hu? án t? do (tr? còn ?ang trích xu?t)
    GIAM_15A AS (
        SELECT COUNT(*) AS V
        FROM QLPN.HUY_ANS HA
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = HA.PHAM_NHAN_ID
        CROSS JOIN THANG
        WHERE CAST(HA.NGAY_TRA_TU_DO AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND NVL(HA.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
          AND HA.PHAM_NHAN_ID NOT IN (
                SELECT TX.PHAM_NHAN_ID
                FROM QLPN.TRICH_XUATS TX
                WHERE TX.TX_LOAI_LENH_ID = 1
                  AND (TX.TX_NGAY_TRA IS NULL
                       OR CAST(TX.TX_NGAY_TRA AS DATE) > THANG.DEN_NGAY))
    ),
    -- Row 15b: Hoãn thi hành án
    GIAM_15B AS (
        SELECT COUNT(*) AS V
        FROM QLPN.HOAN_THI_HANH_ANS HTHA
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = HTHA.PHAM_NHAN_ID
        CROSS JOIN THANG
        WHERE CAST(HTHA.NGAY_HOAN AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND NVL(HTHA.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),
    -- Row 15c: Mi?n hình ph?t
    GIAM_15C AS (
        SELECT COUNT(*) AS V
        FROM QLPN.MIEN_HINH_PHATS MHP
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = MHP.PN_LAI_LICH_ID
        CROSS JOIN THANG
        WHERE CAST(MHP.MHP_NGAY_TU_DO AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND NVL(MHP.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),
    -- Row 15d: Ch?a b?nh b?t bu?c b?t ??u
    GIAM_15D AS (
        SELECT COUNT(*) AS V
        FROM QLPN.CHUA_BENH_BAT_BUOCS CB
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = CB.PHAM_NHAN_ID
        CROSS JOIN THANG
        WHERE CAST(CB.NGAY_BAT_DAU AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND NVL(CB.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    ),
    -- Row 15e: Chuy?n giao ra n??c ngoài (QT_MA <> '250')
    GIAM_15E AS (
        SELECT COUNT(*) AS V
        FROM QLPN.PN_CHUYEN_GIAO CG
        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = CG.PNCG_LAI_LICH_ID
        LEFT JOIN QLPN.DM_QUOC_TICHS QT ON QT.ID = CG.PNCG_NUOC_CHUYEN_GIAO_ID
        CROSS JOIN THANG
        WHERE CAST(CG.PNCG_NGAY_CHUYEN_GIAO AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
          AND NVL(QT.QT_MA, '000') <> '250'
          AND NVL(CG.IS_DELETED, 0) = 0
          AND NVL(LL.IS_DELETED, 0) = 0
    )

-- ================================================================
-- Final aggregation
-- ================================================================
SELECT
    TANG_1.V                                                              AS SO_PN_THANG_TRUOC_CHUYEN_SANG,

    TANG_3.V  + TANG_4.V  + TANG_5.V  + TANG_6.V
        + TANG_7A.V + TANG_7B.V + TANG_7C.V                              AS SO_TANG_TRONG_THANG,

    GIAM_9.V  + GIAM_10.V + GIAM_11.V + GIAM_12.V + GIAM_13.V
        + GIAM_14.V + GIAM_15A.V + GIAM_15B.V + GIAM_15C.V
        + GIAM_15D.V + GIAM_15E.V                                        AS SO_GIAM_TRONG_THANG,

    TANG_1.V
        + (TANG_3.V  + TANG_4.V  + TANG_5.V  + TANG_6.V
           + TANG_7A.V + TANG_7B.V + TANG_7C.V)
        - (GIAM_9.V  + GIAM_10.V + GIAM_11.V + GIAM_12.V + GIAM_13.V
           + GIAM_14.V + GIAM_15A.V + GIAM_15B.V + GIAM_15C.V
           + GIAM_15D.V + GIAM_15E.V)                                    AS DANG_CHAP_HANH_AN

FROM TANG_1,  TANG_3,  TANG_4,  TANG_5,  TANG_6,
     TANG_7A, TANG_7B, TANG_7C,
     GIAM_9,  GIAM_10, GIAM_11, GIAM_12, GIAM_13, GIAM_14,
     GIAM_15A, GIAM_15B, GIAM_15C, GIAM_15D, GIAM_15E
;
--------------------------------------------------------
--  DDL for View VW_THAN_NHAN
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."VW_THAN_NHAN" ("ID", "HO_TEN_THAN_NHAN", "CCCD", "QUAN_HE", "MA_QUAN_HE", "GIOI_TINH_ID", "GIOI_TINH", "NGAY_SINH", "NGHE_NGHIEP", "NOI_O", "DIEN_THOAI", "GHI_CHU", "PHAM_NHAN_ID", "CREATION_TIME", "CREATOR_USER_ID", "LAST_MODIFICATION_TIME", "LAST_MODIFIER_USER_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    TN.ID,
    TN.HO_TEN_THAN_NHAN,
    TN.CCCD,

    QH.QHVPN_TEN AS QUAN_HE,
    QH.QHVPN_MA AS MA_QUAN_HE,

    TN.GIOI_TINH_ID,
    GT.GT_TEN       AS GIOI_TINH,

    TN.NGAY_SINH,
    TN.NGHE_NGHIEP,
    TN.NOI_O,
    TN.DIEN_THOAI,
    TN.GHI_CHU,

    TN.PHAM_NHAN_ID,

    TN.CREATION_TIME,
    TN.CREATOR_USER_ID,
    TN.LAST_MODIFICATION_TIME,
    TN.LAST_MODIFIER_USER_ID

FROM THAN_NHAN_NGUOI_THANS TN

LEFT JOIN DM_QUAN_HE_VOI_PHAM_NHANS QH
    ON TN.QUAN_HE_ID = QH.ID

LEFT JOIN DM_GIOI_TINHS GT
    ON TN.GIOI_TINH_ID = GT.ID
    AND GT.IS_DELETED = 0

WHERE
    TN.IS_DELETED = 0
    AND QH.IS_DELETED = 0
;
--------------------------------------------------------
--  DDL for View VW_TK_HINH_PHAT_BO_SUNG
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."VW_TK_HINH_PHAT_BO_SUNG" ("HPBS_MA_PHAM_NHAN", "HINH_PHAT_ID", "TEN_HINH_PHAT", "HPBS_TONG_TIEN_PHAT", "SO_LAN", "TONG_TIEN") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    p.HPBS_MA_PHAM_NHAN,
    d.ID AS HINH_PHAT_ID,
    d.HPBS_TEN AS TEN_HINH_PHAT,
    p.HPBS_TONG_TIEN_PHAT,
    COUNT(*) AS SO_LAN,
    SUM(NVL(p.HPBS_TONG_TIEN_PHAT,0)) AS TONG_TIEN
FROM PN_HINH_PHAT_BO_SUNGS p
JOIN DM_HINH_PHAT_BO_SUNGS d
    ON p.HPBS_HINH_PHAT = d.ID
WHERE p.IS_DELETED = 0
GROUP BY
    p.HPBS_MA_PHAM_NHAN,
    d.ID,
    d.HPBS_TEN,
    p.HPBS_TONG_TIEN_PHAT
;
--------------------------------------------------------
--  DDL for View VW_TONG_HOP_GIAM_THOI_HAN
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."VW_TONG_HOP_GIAM_THOI_HAN" ("PHAM_NHAN_ID", "SO_LAN_GIAM", "TONG_AN_GIAM", "CAC_LAN_GIAM") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    LL.ID,
    FN_TINH_AN_DA_GIAM(LL.ID).LAN_GIAM_AN,
    FN_TINH_AN_DA_GIAM(LL.ID).TONG_GIAM_AN,
    FN_TINH_AN_DA_GIAM(LL.ID).CAC_LAN_GIAM
FROM PN_LAI_LICHS LL
WHERE LL.IS_DELETED = 0
;
--------------------------------------------------------
--  DDL for View V_PN_THI_HANH_AN_TOI_DANH
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."V_PN_THI_HANH_AN_TOI_DANH" ("THA_PNLAI_LICH_ID", "THA_MUC_AN_ID", "THA_NGAY_HET_HAN", "THA_NGAY_BAT", "THA_CO_QUAN_BAT_ID", "THA_DIA_PHUONG_CO_QUAN_BAT_ID", "THA_NGAY_DEN_TRAI", "THA_THOI_GIAN_TAM_GIAM", "THA_THOI_GIAN_TAM_GIU", "THA_TOI_DANH_IDS", "TOI_DANH", "THA_AN_PHAT", "THA_MA_AN_PHAT", "THA_SO_BAN_AN", "THA_NGAY_BAN_AN", "THA_NGAY_LAP_DANH_BAN", "THA_LOAI_BAN_AN_ID", "THA_DIA_PHUONG_TOA_QD_THA_ID", "THA_DIA_PHUONG_CAP_TOA_ID", "THA_CAP_TOA_ID", "THA_TOA_QD_ID", "THA_SO_QD_THA", "THA_NGAY_QD_THA", "THA_SO_DANH_BAN", "THA_SO_QD_DIEU_CHUYEN", "THA_DOI_TUONG", "THA_NGAY_QD_DIEU_CHUYEN", "CAN_CU_TUYEN_PHAT", "DIEU", "KHOAN") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    t.THA_PNLAI_LICH_ID,
    t.THA_MUC_AN_ID,
    t.THA_NGAY_HET_HAN,
    t.THA_NGAY_BAT,
    t.THA_CO_QUAN_BAT_ID,
    t.THA_DIA_PHUONG_CO_QUAN_BAT_ID,
    t.THA_NGAY_DEN_TRAI,
    t.THA_THOI_GIAN_TAM_GIAM,
    t.THA_THOI_GIAN_TAM_GIU,
    REPLACE(REPLACE(TRIM(t.THA_TOI_DANH), '[', ''), ']', '')            AS THA_TOI_DANH_IDS,
    t.THA_TOI_DANH_NAMES                                                 AS TOI_DANH,
    t.THA_AN_PHAT,
    t.THA_MA_AN_PHAT,
    t.THA_SO_BAN_AN,
    t.THA_NGAY_BAN_AN,
    t.THA_NGAY_LAP_DANH_BAN,
    t.THA_LOAI_BAN_AN_ID,
    t.THA_DIA_PHUONG_TOA_QD_THA_ID,
    t.THA_DIA_PHUONG_CAP_TOA_ID,
    t.THA_CAP_TOA_ID,
    t.THA_TOA_QD_ID,
    t.THA_SO_QD_THA,
    t.THA_NGAY_QD_THA,
    t.THA_SO_DANH_BAN,
    t.THA_SO_QD_DIEU_CHUYEN,
    t.THA_DOI_TUONG,
    t.THA_NGAY_QD_DIEU_CHUYEN,
    REPLACE(REPLACE(TRIM(t.THA_CAN_CU_TUYEN_PHAT), '[', ''), ']', '')   AS CAN_CU_TUYEN_PHAT,
    REPLACE(REPLACE(TRIM(t.THA_DIEU),              '[', ''), ']', '')   AS DIEU,
    REPLACE(REPLACE(TRIM(t.THA_KHOAN),             '[', ''), ']', '')   AS KHOAN
FROM QLPN.PN_THI_HANH_AN t
WHERE t.THA_TOI_DANH IS NOT NULL
  AND TRIM(t.THA_TOI_DANH) IS NOT NULL
;
--------------------------------------------------------
--  DDL for View V_PN_THI_HANH_AN_TOI_DANH_V2
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."V_PN_THI_HANH_AN_TOI_DANH_V2" ("THA_PNLAI_LICH_ID", "THA_MUC_AN_ID", "THA_NGAY_HET_HAN", "THA_NGAY_BAT", "THA_CO_QUAN_BAT_ID", "THA_DIA_PHUONG_CO_QUAN_BAT_ID", "THA_NGAY_DEN_TRAI", "THA_THOI_GIAN_TAM_GIAM", "THA_THOI_GIAN_TAM_GIU", "THA_TOI_DANH_IDS", "TOI_DANH", "THA_AN_PHAT", "THA_MA_AN_PHAT", "THA_SO_BAN_AN", "THA_NGAY_BAN_AN", "THA_NGAY_LAP_DANH_BAN", "THA_LOAI_BAN_AN_ID", "THA_DIA_PHUONG_TOA_QD_THA_ID", "THA_DIA_PHUONG_CAP_TOA_ID", "THA_CAP_TOA_ID", "THA_TOA_QD_ID", "THA_SO_QD_THA", "THA_NGAY_QD_THA", "THA_SO_DANH_BAN", "THA_SO_QD_DIEU_CHUYEN", "THA_DOI_TUONG", "THA_NGAY_QD_DIEU_CHUYEN", "CAN_CU_TUYEN_PHAT", "DIEU", "KHOAN") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  WITH tha_split AS (
    SELECT
        t."ID",
        t."THA_PNLAI_LICH_ID",
        t.THA_MUC_AN_ID,
        t."THA_AN_PHAT",
        t."THA_MA_AN_PHAT",
        t."THA_CAN_CU_TUYEN_PHAT",
        t."THA_NGAY_BAT",
        t."THA_CO_QUAN_BAT_ID",
        t."THA_DIA_PHUONG_CO_QUAN_BAT_ID",
        t.THA_NGAY_HET_HAN,
        t.THA_NGAY_DEN_TRAI,
        t.THA_THOI_GIAN_TAM_GIAM,
        t.THA_THOI_GIAN_TAM_GIU,
        t.THA_SO_BAN_AN,
        t.THA_NGAY_BAN_AN,
        t.THA_NGAY_LAP_DANH_BAN,
        t.THA_DIA_PHUONG_TOA_QD_THA_ID,
        t.THA_DIA_PHUONG_CAP_TOA_ID,
        t.THA_CAP_TOA_ID,
        t.THA_TOA_QD_ID,
        t.THA_SO_QD_THA,
        t.THA_NGAY_QD_THA,
        t.THA_SO_DANH_BAN,
        t.THA_SO_QD_DIEU_CHUYEN,
        t.THA_DOI_TUONG,
        t.THA_LOAI_BAN_AN_ID,
        t.THA_NGAY_QD_DIEU_CHUYEN,
        REPLACE(REPLACE(TRIM(t."THA_CAN_CU_TUYEN_PHAT"), '[', ''), ']', '') AS can_cu_list,
        REPLACE(REPLACE(TRIM(t."THA_DIEU"),              '[', ''), ']', '') AS dieu_list,
        REPLACE(REPLACE(TRIM(t."THA_KHOAN"),             '[', ''), ']', '') AS khoan_list,
        jt.pos,
        jt.toi_danh_id
    FROM "PN_THI_HANH_AN" t
    -- JSON_TABLE tách m?ng s? [1,2,3] — không c?n REGEXP_COUNT + SYS_GUID
    -- CAST sang VARCHAR2 b?t bu?c: JSON_TABLE không parse ???c NVARCHAR2 AL16UTF16
    CROSS JOIN JSON_TABLE(
        CAST(TRIM(t."THA_TOI_DANH") AS VARCHAR2(4000)),
        '$[*]' COLUMNS (
            pos         FOR ORDINALITY,   -- v? trí g?c ?? align can_cu/dieu/khoan
            toi_danh_id NUMBER PATH '$'
        )
    ) jt
    WHERE t."THA_TOI_DANH" IS NOT NULL
      AND TRIM(t."THA_TOI_DANH") IS NOT NULL
)
SELECT
    "THA_PNLAI_LICH_ID",
    THA_MUC_AN_ID,
    THA_NGAY_HET_HAN,
    "THA_NGAY_BAT",
    "THA_CO_QUAN_BAT_ID",
    "THA_DIA_PHUONG_CO_QUAN_BAT_ID",
    THA_NGAY_DEN_TRAI,
    THA_THOI_GIAN_TAM_GIAM,
    THA_THOI_GIAN_TAM_GIU,
    LISTAGG(TO_CHAR(toi_danh_id), ',') WITHIN GROUP (ORDER BY toi_danh_id) AS THA_TOI_DANH_IDS,
    LISTAGG(d."TD_TEN", '; ')          WITHIN GROUP (ORDER BY toi_danh_id) AS TOI_DANH,
    "THA_AN_PHAT",
    "THA_MA_AN_PHAT",
    THA_SO_BAN_AN,
    THA_NGAY_BAN_AN,
    THA_NGAY_LAP_DANH_BAN,
    THA_LOAI_BAN_AN_ID,
    THA_DIA_PHUONG_TOA_QD_THA_ID,
    THA_DIA_PHUONG_CAP_TOA_ID,
    THA_CAP_TOA_ID,
    THA_TOA_QD_ID,
    THA_SO_QD_THA,
    THA_NGAY_QD_THA,
    THA_SO_DANH_BAN,
    THA_SO_QD_DIEU_CHUYEN,
    THA_DOI_TUONG,
    THA_NGAY_QD_DIEU_CHUYEN,
    -- pos gi? ?úng v? trí g?c c?a can_cu/dieu/khoan t??ng ?ng v?i t?ng t?i danh
    LISTAGG(TRIM(REGEXP_SUBSTR(can_cu_list, '[^,]+', 1, pos)), ',') WITHIN GROUP (ORDER BY toi_danh_id) AS CAN_CU_TUYEN_PHAT,
    LISTAGG(TRIM(REGEXP_SUBSTR(dieu_list,   '[^,]+', 1, pos)), ',') WITHIN GROUP (ORDER BY toi_danh_id) AS DIEU,
    LISTAGG(TRIM(REGEXP_SUBSTR(khoan_list,  '[^,]+', 1, pos)), ',') WITHIN GROUP (ORDER BY toi_danh_id) AS KHOAN
FROM tha_split
LEFT JOIN "DM_TOI_DANHS" d ON d."ID" = toi_danh_id
GROUP BY
    "THA_PNLAI_LICH_ID", THA_MUC_AN_ID, THA_NGAY_HET_HAN, "THA_NGAY_BAT",
    "THA_CO_QUAN_BAT_ID", "THA_DIA_PHUONG_CO_QUAN_BAT_ID",
    THA_NGAY_DEN_TRAI, THA_THOI_GIAN_TAM_GIAM, THA_THOI_GIAN_TAM_GIU,
    "THA_AN_PHAT", "THA_MA_AN_PHAT", THA_SO_BAN_AN, THA_NGAY_BAN_AN,
    THA_NGAY_LAP_DANH_BAN, THA_LOAI_BAN_AN_ID,
    THA_DIA_PHUONG_TOA_QD_THA_ID, THA_DIA_PHUONG_CAP_TOA_ID,
    THA_CAP_TOA_ID, THA_TOA_QD_ID, THA_SO_QD_THA, THA_NGAY_QD_THA,
    THA_SO_DANH_BAN, THA_SO_QD_DIEU_CHUYEN, THA_DOI_TUONG, THA_NGAY_QD_DIEU_CHUYEN
;
--------------------------------------------------------
--  DDL for View V_PN_THONG_BAO_DASHBOARD
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."V_PN_THONG_BAO_DASHBOARD" ("LOAI_CANH_BAO", "MAU_CANH_BAO", "NOI_DUNG_THONG_BAO", "MA_TRAI_GIAM") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  WITH notification_events AS (
    ---------------------------------------------------------------------------
    -- 1. Giao nhan pham nhan
    ---------------------------------------------------------------------------
    SELECT
        1 AS notification_type,
        u'DO' AS warning_color,
        u'GIAO_NHAN_PHAM_NHAN' AS notification_code,
        u'Giao nh\1eadn ph\1ea1m nh\00e2n' AS notification_name,
        u'ph\1ea1m nh\00e2n \0111\01b0\1ee3c giao nh\1eadn' AS message_action,
        TRUNC(bb.BB_NGAY) AS event_date,
        bbpn.PN_LAI_LICH_ID AS prisoner_id,
        bb.ID AS source_id,
        tg.TG_MA AS ma_trai_giam
    FROM QLPN.PN_BIEN_BANS bb
    INNER JOIN QLPN.PN_BIEN_BAN_PHAM_NHANS bbpn
            ON bbpn.PN_BIEN_BAN_ID = bb.ID
           AND NVL(bbpn.IS_DELETED, 0) = 0
           AND bbpn.PN_LAI_LICH_ID IS NOT NULL
    INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.ID = bbpn.PN_LAI_LICH_ID
           AND NVL(ll.IS_DELETED, 0) = 0
    INNER JOIN QLPN.DM_TRAI_GIAMS tg
            ON tg.ID = ll.LL_TRAI_GIAM_ID
           AND NVL(tg.IS_DELETED, 0) = 0
    WHERE NVL(bb.IS_DELETED, 0) = 0
      AND bb.BB_NGAY IS NOT NULL

    UNION ALL

    ---------------------------------------------------------------------------
    -- 2. Chua benh bat buoc
    ---------------------------------------------------------------------------
    SELECT
        2,
        u'DO',
        u'CHUA_BENH_BAT_BUOC',
        u'Ph\1ea1m nh\00e2n \0111i ch\1eefa b\1ec7nh b\1eaft bu\1ed9c',
        u'ph\1ea1m nh\00e2n \0111i ch\1eefa b\1ec7nh b\1eaft bu\1ed9c',
        TRUNC(cbbb.NGAY_BAT_DAU),
        cbbb.PHAM_NHAN_ID,
        cbbb.ID,
        tg.TG_MA
    FROM QLPN.CHUA_BENH_BAT_BUOCS cbbb
    INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.ID = cbbb.PHAM_NHAN_ID
           AND NVL(ll.IS_DELETED, 0) = 0
    INNER JOIN QLPN.DM_TRAI_GIAMS tg
            ON tg.ID = ll.LL_TRAI_GIAM_ID
           AND NVL(tg.IS_DELETED, 0) = 0
    WHERE NVL(cbbb.IS_DELETED, 0) = 0
      AND cbbb.NGAY_BAT_DAU IS NOT NULL
      AND cbbb.PHAM_NHAN_ID IS NOT NULL

    UNION ALL

    ---------------------------------------------------------------------------
    -- 3. Tron trai
    ---------------------------------------------------------------------------
    SELECT
        3,
        u'DO',
        u'TRON_TRAI',
        u'Ph\1ea1m nh\00e2n tr\1ed1n tr\1ea1i',
        u'ph\1ea1m nh\00e2n tr\1ed1n tr\1ea1i',
        TRUNC(tt.NGAY_TRON),
        tt.PHAM_NHAN_ID,
        tt.ID,
        tg.TG_MA
    FROM QLPN.TRON_TRAIS tt
    INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.ID = tt.PHAM_NHAN_ID
           AND NVL(ll.IS_DELETED, 0) = 0
    INNER JOIN QLPN.DM_TRAI_GIAMS tg
            ON tg.ID = ll.LL_TRAI_GIAM_ID
           AND NVL(tg.IS_DELETED, 0) = 0
    WHERE NVL(tt.IS_DELETED, 0) = 0
      AND tt.NGAY_TRON IS NOT NULL
      AND tt.PHAM_NHAN_ID IS NOT NULL

    UNION ALL

    ---------------------------------------------------------------------------
    -- 4. Trich xuat
    ---------------------------------------------------------------------------
    SELECT
        4,
        u'VANG',
        u'TRICH_XUAT',
        u'Ph\1ea1m nh\00e2n \0111i tr\00edch xu\1ea5t',
        u'ph\1ea1m nh\00e2n \0111i tr\00edch xu\1ea5t',
        TRUNC(tx.TX_NGAY_TRICH_XUAT),
        tx.PHAM_NHAN_ID,
        tx.ID,
        tg.TG_MA
    FROM QLPN.TRICH_XUATS tx
    INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.ID = tx.PHAM_NHAN_ID
           AND NVL(ll.IS_DELETED, 0) = 0
    INNER JOIN QLPN.DM_TRAI_GIAMS tg
            ON tg.ID = ll.LL_TRAI_GIAM_ID
           AND NVL(tg.IS_DELETED, 0) = 0
    WHERE NVL(tx.IS_DELETED, 0) = 0
      AND tx.TX_NGAY_TRICH_XUAT IS NOT NULL
      AND tx.PHAM_NHAN_ID IS NOT NULL

    UNION ALL

    ---------------------------------------------------------------------------
    -- 5. Ra trai
    ---------------------------------------------------------------------------
    SELECT
        5,
        u'VANG',
        u'RA_TRAI',
        u'Ph\1ea1m nh\00e2n ra tr\1ea1i',
        u'ph\1ea1m nh\00e2n ra tr\1ea1i',
        TRUNC(ktrt.KTRT_NGAY_THA),
        ktrt.KTRT_PN_LAI_LICH_ID,
        ktrt.ID,
        tg.TG_MA
    FROM QLPN.PN_KET_THUC_RA_TRAIS ktrt
    INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.ID = ktrt.KTRT_PN_LAI_LICH_ID
           AND NVL(ll.IS_DELETED, 0) = 0
    INNER JOIN QLPN.DM_TRAI_GIAMS tg
            ON tg.ID = ll.LL_TRAI_GIAM_ID
           AND NVL(tg.IS_DELETED, 0) = 0
    WHERE NVL(ktrt.IS_DELETED, 0) = 0
      AND ktrt.KTRT_NGAY_THA IS NOT NULL
      AND ktrt.KTRT_PN_LAI_LICH_ID IS NOT NULL

    UNION ALL

    ---------------------------------------------------------------------------
    -- 6. Chet
    ---------------------------------------------------------------------------
    SELECT
        6,
        u'VANG',
        u'CHET',
        u'Ph\1ea1m nh\00e2n ch\1ebft',
        u'ph\1ea1m nh\00e2n ch\1ebft',
        TRUNC(ktc.KTC_NGAY_CHET),
        ktc.KTC_PN_LAI_LICH_ID,
        ktc.ID,
        tg.TG_MA
    FROM QLPN.PN_KET_THUC_CHETS ktc
    INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.ID = ktc.KTC_PN_LAI_LICH_ID
           AND NVL(ll.IS_DELETED, 0) = 0
    INNER JOIN QLPN.DM_TRAI_GIAMS tg
            ON tg.ID = ll.LL_TRAI_GIAM_ID
           AND NVL(tg.IS_DELETED, 0) = 0
    WHERE NVL(ktc.IS_DELETED, 0) = 0
      AND ktc.KTC_NGAY_CHET IS NOT NULL
      AND ktc.KTC_PN_LAI_LICH_ID IS NOT NULL

    UNION ALL

    ---------------------------------------------------------------------------
    -- 7. Chuyen trai
    ---------------------------------------------------------------------------
    SELECT
        7,
        u'XAM',
        u'CHUYEN_TRAI',
        u'Ph\1ea1m nh\00e2n chuy\1ec3n tr\1ea1i',
        u'ph\1ea1m nh\00e2n chuy\1ec3n tr\1ea1i',
        TRUNC(pnct.PNCT_NGAY_CHUYEN),
        pnct.PNCT_LAI_LICH_ID,
        pnct.ID,
        tg.TG_MA
    FROM QLPN.PHAM_NHAN_CHUYEN_TRAI pnct
    INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.ID = pnct.PNCT_LAI_LICH_ID
           AND NVL(ll.IS_DELETED, 0) = 0
    INNER JOIN QLPN.DM_TRAI_GIAMS tg
            ON tg.ID = ll.LL_TRAI_GIAM_ID
           AND NVL(tg.IS_DELETED, 0) = 0
    WHERE NVL(pnct.IS_DELETED, 0) = 0
      AND pnct.PNCT_NGAY_CHUYEN IS NOT NULL
      AND pnct.PNCT_LAI_LICH_ID IS NOT NULL

    UNION ALL

    ---------------------------------------------------------------------------
    -- 8. Chuyen giao
    ---------------------------------------------------------------------------
    SELECT
        8,
        u'XAM',
        u'CHUYEN_GIAO',
        u'Ph\1ea1m nh\00e2n chuy\1ec3n giao',
        u'ph\1ea1m nh\00e2n chuy\1ec3n giao',
        TRUNC(pncg.PNCG_NGAY_CHUYEN_GIAO),
        pncg.PNCG_LAI_LICH_ID,
        pncg.ID,
        tg.TG_MA
    FROM QLPN.PN_CHUYEN_GIAO pncg
    INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.ID = pncg.PNCG_LAI_LICH_ID
           AND NVL(ll.IS_DELETED, 0) = 0
    INNER JOIN QLPN.DM_TRAI_GIAMS tg
            ON tg.ID = ll.LL_TRAI_GIAM_ID
           AND NVL(tg.IS_DELETED, 0) = 0
    WHERE NVL(pncg.IS_DELETED, 0) = 0
      AND pncg.PNCG_NGAY_CHUYEN_GIAO IS NOT NULL
      AND pncg.PNCG_LAI_LICH_ID IS NOT NULL

    UNION ALL

    ---------------------------------------------------------------------------
    -- 9. Dot dac xa / ky xep loai / dot giam thoi han duoc mo
    ---------------------------------------------------------------------------
    SELECT
        9,
        u'XAM',
        u'MO_DOT_DAC_XA',
        u'M\1edf \0111\1ee3t \0111\1eb7c x\00e1',
        u'\0111\1ee3t \0111\1eb7c x\00e1 \0111\01b0\1ee3c m\1edf',
        TRUNC(ddx.CREATION_TIME),
        CAST(NULL AS NUMBER),
        ddx.ID,
        NVL(NULLIF(TRIM(ddx.DDX_TG_MA_TRAI_GIAM), u''), u'C10')
    FROM QLPN.PN_DOT_DAC_XAS ddx
    WHERE NVL(ddx.IS_DELETED, 0) = 0

    UNION ALL

    SELECT
        9,
        u'XAM',
        u'MO_KY_XEP_LOAI',
        u'M\1edf k\1ef3 x\1ebfp lo\1ea1i c\1ea3i t\1ea1o',
        u'k\1ef3 x\1ebfp lo\1ea1i c\1ea3i t\1ea1o \0111\01b0\1ee3c m\1edf',
        TRUNC(mkxl.CREATION_TIME),
        CAST(NULL AS NUMBER),
        mkxl.ID,
        u'C10'
    FROM QLPN.MO_KY_XEP_LOAI_CAI_TAOS mkxl
    WHERE NVL(mkxl.IS_DELETED, 0) = 0

    UNION ALL

    SELECT
        9,
        u'XAM',
        u'MO_DOT_GIAM_THOI_HAN',
        u'M\1edf \0111\1ee3t gi\1ea3m th\1eddi h\1ea1n',
        u'\0111\1ee3t gi\1ea3m th\1eddi h\1ea1n \0111\01b0\1ee3c m\1edf',
        TRUNC(kgth.CREATION_TIME),
        CAST(NULL AS NUMBER),
        kgth.ID,
        u'C10'
    FROM QLPN.GTH_KY_GIAM_THOI_HANS kgth
    WHERE NVL(kgth.IS_DELETED, 0) = 0

    UNION ALL

    ---------------------------------------------------------------------------
    -- 10. Nop luu
    ---------------------------------------------------------------------------
    SELECT
        10,
        u'XAM',
        u'NOP_LUU',
        u'Ph\1ea1m nh\00e2n \0111\01b0\1ee3c n\1ed9p l\01b0u',
        u'ph\1ea1m nh\00e2n \0111\01b0\1ee3c n\1ed9p l\01b0u',
        TRUNC(nl.NGAY_NOP_LUU),
        nl.PHAM_NHAN_ID,
        nl.ID,
        tg.TG_MA
    FROM QLPN.NOP_LUUS nl
    INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.ID = nl.PHAM_NHAN_ID
           AND NVL(ll.IS_DELETED, 0) = 0
    INNER JOIN QLPN.DM_TRAI_GIAMS tg
            ON tg.ID = ll.LL_TRAI_GIAM_ID
           AND NVL(tg.IS_DELETED, 0) = 0
    WHERE NVL(nl.IS_DELETED, 0) = 0
      AND nl.NGAY_NOP_LUU IS NOT NULL
      AND nl.PHAM_NHAN_ID IS NOT NULL
),
aggregated_notifications AS (
    SELECT
        notification_type,
        warning_color,
        notification_code,
        notification_name,
        message_action,
        event_date,
        ma_trai_giam,
        CASE
            WHEN notification_type = 9 THEN
                COUNT(DISTINCT CAST(notification_code AS NVARCHAR2(100)) || u':' || TO_NCHAR(source_id))
            ELSE COUNT(DISTINCT prisoner_id)
        END AS total_count
    FROM notification_events
    WHERE event_date >= TRUNC(SYSDATE) - 13
      AND event_date < TRUNC(SYSDATE) + 1
    GROUP BY
        notification_type,
        warning_color,
        notification_code,
        notification_name,
        message_action,
        event_date,
        ma_trai_giam
),
chi_tiet AS (
    SELECT
        notification_type AS loai_canh_bao,
        warning_color AS mau_canh_bao,
        ma_trai_giam,
        event_date,
        message_action,
        total_count,
        CASE
            WHEN event_date = TRUNC(SYSDATE) - 1 THEN
                u'H\00f4m qua (ng\00e0y ' || CAST(TO_CHAR(event_date, 'DD/MM/YYYY') AS NVARCHAR2(20)) || u') c\00f3 ' ||
                TO_NCHAR(total_count) || u' ' || message_action
            WHEN event_date = TRUNC(SYSDATE) THEN
                u'H\00f4m nay (ng\00e0y ' || CAST(TO_CHAR(event_date, 'DD/MM/YYYY') AS NVARCHAR2(20)) || u') c\00f3 ' ||
                TO_NCHAR(total_count) || u' ' || message_action
            ELSE
                u'Ng\00e0y ' || CAST(TO_CHAR(event_date, 'DD/MM/YYYY') AS NVARCHAR2(20)) || u' c\00f3 ' ||
                TO_NCHAR(total_count) || u' ' || message_action
        END AS noi_dung_thong_bao
    FROM aggregated_notifications
    WHERE total_count > 0
)
SELECT
    loai_canh_bao AS LOAI_CANH_BAO,
    mau_canh_bao AS MAU_CANH_BAO,
    noi_dung_thong_bao AS NOI_DUNG_THONG_BAO,
    ma_trai_giam AS MA_TRAI_GIAM
FROM chi_tiet

UNION ALL

SELECT
    loai_canh_bao,
    mau_canh_bao,
    CASE
        WHEN event_date = TRUNC(SYSDATE) - 1 THEN
            u'H\00f4m qua (ng\00e0y ' || CAST(TO_CHAR(event_date, 'DD/MM/YYYY') AS NVARCHAR2(20)) || u') c\00f3 ' ||
            TO_NCHAR(SUM(total_count)) || u' ' || message_action
        WHEN event_date = TRUNC(SYSDATE) THEN
            u'H\00f4m nay (ng\00e0y ' || CAST(TO_CHAR(event_date, 'DD/MM/YYYY') AS NVARCHAR2(20)) || u') c\00f3 ' ||
            TO_NCHAR(SUM(total_count)) || u' ' || message_action
        ELSE
            u'Ng\00e0y ' || CAST(TO_CHAR(event_date, 'DD/MM/YYYY') AS NVARCHAR2(20)) || u' c\00f3 ' ||
            TO_NCHAR(SUM(total_count)) || u' ' || message_action
    END,
    u'C10'
FROM chi_tiet
WHERE ma_trai_giam <> u'C10'
GROUP BY loai_canh_bao, mau_canh_bao, message_action, event_date
;
--------------------------------------------------------
--  DDL for View V_TK_TONG_HOP_TINH_TRANG_DASHBOARD
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "QLPN"."V_TK_TONG_HOP_TINH_TRANG_DASHBOARD" ("STT", "TEN_TK", "MA_TRAI_GIAM", "TS", "FRM") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  WITH
params AS (
    SELECT /*+ MATERIALIZE */ TRUNC(SYSDATE) AS NGAY_XET,
           TRUNC(SYSDATE, 'YEAR') AS NAM_DAU
      FROM DUAL
),
-- FIX 2026-08-22: thêm TG_MA_DD_DT IS NOT NULL — lo?i các "tr?i" gi?/gán nh?m trong
-- DM_TRAI_GIAMS (tr?i t?m giam t?nh khác..., vd ID 90680/95360/98409) mà vài PN b? gán
-- nh?m/t?m LL_TRAI_GIAM_ID vào ?ó. Kh?p ?úng ?i?u ki?n DS_TRAI ?ã dùng ?
-- SP_QLPN_GET_TK_THANG_DASHBOARD — tr??c khi fix, dòng t?ng "C10" c?a view này c?ng th?a
-- các PN thu?c tr?i gi? trong khi SP_THANG lo?i ?úng, gây l?ch +3 gi?a 2 widget dashboard
-- (xác nh?n qua ??i soát 2026-08-22, ?úng 3 ng??i thu?c tr?i TG_MA_DD_DT IS NULL).
dm_tg AS (
    SELECT /*+ MATERIALIZE */ ID, TG_MA
      FROM QLPN.DM_TRAI_GIAMS
     WHERE NVL(IS_DELETED, 0) = 0
--       AND TG_MA_DD_DT IS NOT NULL
),
dm_lqd_tx1 AS (
    SELECT /*+ MATERIALIZE */ ID
      FROM QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS
     WHERE NVL(IS_DELETED, 0) = 0
       AND LQDTX_MA = '1'
),
dm_lq_tdc1 AS (
    SELECT /*+ MATERIALIZE */ ID
      FROM QLPN.DM_LOAI_QUYET_DINH_TAM_DINH_CHIES
     WHERE NVL(IS_DELETED, 0) = 0
       AND LQDTDC_MA = '1'
),
rt_core AS (
    SELECT /*+ MATERIALIZE */
           rt.PHAM_NHAN_ID,
           rt.LL_TRAI_GIAM_ID,
           c.TTPN_MA,
           rt.THA_NGAY_DEN_TRAI,
           rt.THA_NGAY_HET_HAN
      FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
      JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE c
        ON c.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
       AND c.NGAY_XET = TRUNC(SYSDATE)
     WHERE NVL(rt.IS_DELETED, 0) = 0
       AND rt.LL_TRAI_GIAM_ID IS NOT NULL
),
-- STT 1,6,7,8,9,10: m?t l?n quét rt_core + GROUP BY tr?i
rt_by_trai AS (
    SELECT /*+ MATERIALIZE */
           tg.TG_MA AS MA_TRAI_GIAM,
           COUNT(DISTINCT CASE
               WHEN r.TTPN_MA IN ('111', '112', '113', '114')
               THEN r.PHAM_NHAN_ID
           END) AS TS_STT1,
           COUNT(DISTINCT CASE
               WHEN r.TTPN_MA = '126'
               THEN r.PHAM_NHAN_ID
           END) AS TS_STT6,
           COUNT(DISTINCT CASE
               WHEN r.THA_NGAY_DEN_TRAI IS NOT NULL
                AND r.THA_NGAY_HET_HAN IS NOT NULL
                AND r.THA_NGAY_HET_HAN >= p.NGAY_XET
                AND r.THA_NGAY_HET_HAN < p.NGAY_XET + 1
               THEN r.PHAM_NHAN_ID
           END) AS TS_STT7,
           COUNT(DISTINCT CASE
               WHEN r.TTPN_MA IN ('111', '112', '113', '114')
                AND r.THA_NGAY_DEN_TRAI IS NOT NULL
                AND r.THA_NGAY_HET_HAN IS NOT NULL
                AND r.THA_NGAY_HET_HAN >= p.NGAY_XET + 1
                AND r.THA_NGAY_HET_HAN < p.NGAY_XET + 2
               THEN r.PHAM_NHAN_ID
           END) AS TS_STT8,
           COUNT(DISTINCT CASE
               WHEN r.TTPN_MA IN ('111', '112', '113', '114')
                AND r.THA_NGAY_DEN_TRAI IS NOT NULL
                AND r.THA_NGAY_HET_HAN IS NOT NULL
                AND r.THA_NGAY_HET_HAN >= p.NGAY_XET + 1
                AND r.THA_NGAY_HET_HAN < ADD_MONTHS(p.NGAY_XET + 1, 2) + 1
               THEN r.PHAM_NHAN_ID
           END) AS TS_STT9,
           COUNT(DISTINCT CASE
               WHEN r.TTPN_MA = '123'
               THEN r.PHAM_NHAN_ID
           END) AS TS_STT10
      FROM rt_core r
     CROSS JOIN params p
     INNER JOIN dm_tg tg ON tg.ID = r.LL_TRAI_GIAM_ID
     GROUP BY tg.TG_MA
),
chi_tiet AS (
    SELECT STT, TEN_TK, MA_TRAI_GIAM, TS, FRM
      FROM (
        SELECT 1 AS STT,
               CAST(u' 1. \0110ang ch\1ea5p h\00e0nh \00e1n' AS NVARCHAR2(200)) AS TEN_TK,
               MA_TRAI_GIAM,
               TS_STT1 AS TS,
               CAST(u'DS_CHAP_HANH' AS NVARCHAR2(100)) AS FRM
          FROM rt_by_trai
         WHERE TS_STT1 > 0

        UNION ALL

        SELECT 2,
               CAST(u'    Trong \0111\00f3 giam ri\00eang' AS NVARCHAR2(200)),
               tg.TG_MA,
               COUNT(DISTINCT g.GR_PN_LAI_LICH_ID),
               CAST(u'DS_GIAM_RIENG' AS NVARCHAR2(100))
          FROM QLPN.PN_GIAM_RIENGS g
         INNER JOIN rt_core r ON r.PHAM_NHAN_ID = g.GR_PN_LAI_LICH_ID
         INNER JOIN dm_tg tg ON tg.ID = r.LL_TRAI_GIAM_ID
         CROSS JOIN params p
         WHERE NVL(g.IS_DELETED, 0) = 0
           AND r.TTPN_MA LIKE '112%'
           AND (g.GR_NGAY_KETTHUC IS NULL OR g.GR_NGAY_KETTHUC >= p.NGAY_XET)
         GROUP BY tg.TG_MA

        UNION ALL

        SELECT 3,
               CAST(u' 2. B\1eaft bu\1ed9c ch\1eefa b\1ec7nh' AS NVARCHAR2(200)),
               tg.TG_MA,
               COUNT(DISTINCT c.PHAM_NHAN_ID),
               CAST(u'DS_CHUA_BENH' AS NVARCHAR2(100))
          FROM QLPN.CHUA_BENH_BAT_BUOCS c
         INNER JOIN rt_core r ON r.PHAM_NHAN_ID = c.PHAM_NHAN_ID
         INNER JOIN dm_tg tg ON tg.ID = r.LL_TRAI_GIAM_ID
         WHERE NVL(c.IS_DELETED, 0) = 0
           AND r.TTPN_MA LIKE '113%'
         GROUP BY tg.TG_MA

        UNION ALL

        SELECT 4,
               CAST(u' 3. Tr\00edch xu\1ea5t ch\01b0a tr\1edf l\1ea1i' AS NVARCHAR2(200)),
               tg.TG_MA,
               COUNT(DISTINCT tx.PHAM_NHAN_ID),
               CAST(u'DS_TRICH_XUAT_DI' AS NVARCHAR2(100))
          FROM QLPN.TRICH_XUATS tx
         INNER JOIN dm_lqd_tx1 lqd ON lqd.ID = tx.TX_LOAI_LENH_ID
         INNER JOIN rt_core r ON r.PHAM_NHAN_ID = tx.PHAM_NHAN_ID
         INNER JOIN dm_tg tg ON tg.ID = r.LL_TRAI_GIAM_ID
         WHERE NVL(tx.IS_DELETED, 0) = 0
           AND tx.TX_NGAY_TRA IS NULL
           AND r.TTPN_MA IN ('141', '142')
         GROUP BY tg.TG_MA

        UNION ALL

        SELECT 5,
               CAST(u' 4. T\1ea1m \0111\00ecnh ch\1ec9 ch\01b0a tr\1edf l\1ea1i' AS NVARCHAR2(200)),
               tg.TG_MA,
               COUNT(DISTINCT tdc.PHAM_NHAN_ID),
               CAST(u'DS_TAM_DINH_CHI' AS NVARCHAR2(100))
          FROM QLPN.TAM_DINH_CHIS tdc
         INNER JOIN dm_lq_tdc1 lq ON lq.ID = tdc.LOAI_QUYET_DINH_ID
         INNER JOIN rt_core r ON r.PHAM_NHAN_ID = tdc.PHAM_NHAN_ID
         INNER JOIN dm_tg tg ON tg.ID = r.LL_TRAI_GIAM_ID
         WHERE NVL(tdc.IS_DELETED, 0) = 0
           AND tdc.NGAY_LAI IS NULL
           AND r.TTPN_MA IN ('151', '152', '157')
         GROUP BY tg.TG_MA

        UNION ALL

        SELECT 6,
               CAST(u' 5. Tha tr\01b0\1edbc th\1eddi h\1ea1n c\00f3 \0111k' AS NVARCHAR2(200)),
               MA_TRAI_GIAM,
               TS_STT6,
               CAST(u'danh_sach_tha_co_dk' AS NVARCHAR2(100))
          FROM rt_by_trai
         WHERE TS_STT6 > 0

        UNION ALL

        SELECT 7,
               CAST(u' 6. Ra tr\1ea1i h\00f4m nay' AS NVARCHAR2(200)),
               MA_TRAI_GIAM,
               TS_STT7,
               CAST(u'DS_DA_RA_TRAI' AS NVARCHAR2(100))
          FROM rt_by_trai
         WHERE TS_STT7 > 0

        UNION ALL

        SELECT 8,
               CAST(u' 7. Ra tr\1ea1i h\00f4m sau' AS NVARCHAR2(200)),
               MA_TRAI_GIAM,
               TS_STT8,
               CAST(u'TB_NGAY_CHXHPT' AS NVARCHAR2(100))
          FROM rt_by_trai
         WHERE TS_STT8 > 0

        UNION ALL

        SELECT 9,
               CAST(u' 8. Ra tr\1ea1i tr\01b0\1edbc 2 th\00e1ng' AS NVARCHAR2(200)),
               MA_TRAI_GIAM,
               TS_STT9,
               CAST(u'TB_NGAY_CHXHPT' AS NVARCHAR2(100))
          FROM rt_by_trai
         WHERE TS_STT9 > 0

        UNION ALL

        SELECT 10,
               CAST(u' 9. \0110\01b0\1ee3c \0111\1eb7c x\00e1' AS NVARCHAR2(200)),
               MA_TRAI_GIAM,
               TS_STT10,
               CAST(u'DS_DAC_XA' AS NVARCHAR2(100))
          FROM rt_by_trai
         WHERE TS_STT10 > 0

        UNION ALL

        SELECT 11,
               CAST(u' 10. Chuy\1ec3n tr\1ea1i kh\00e1c' AS NVARCHAR2(200)),
               tg.TG_MA,
               COUNT(DISTINCT ct.PNCT_LAI_LICH_ID),
               CAST(u'DS_CHUYEN_TRAI' AS NVARCHAR2(100))
          FROM QLPN.PHAM_NHAN_CHUYEN_TRAI ct
         INNER JOIN rt_core r ON r.PHAM_NHAN_ID = ct.PNCT_LAI_LICH_ID
         INNER JOIN dm_tg tg ON tg.ID = r.LL_TRAI_GIAM_ID
         WHERE NVL(ct.IS_DELETED, 0) = 0
         GROUP BY tg.TG_MA

        UNION ALL

        SELECT 12,
               CAST(u' 11. Ch\1ebft trong n\0103m' AS NVARCHAR2(200)),
               tg.TG_MA,
               COUNT(DISTINCT k.KTC_PN_LAI_LICH_ID),
               CAST(u'DS_CHET' AS NVARCHAR2(100))
          FROM QLPN.PN_KET_THUC_CHETS k
         INNER JOIN rt_core r ON r.PHAM_NHAN_ID = k.KTC_PN_LAI_LICH_ID
         INNER JOIN dm_tg tg ON tg.ID = r.LL_TRAI_GIAM_ID
         CROSS JOIN params p
         WHERE NVL(k.IS_DELETED, 0) = 0
           AND k.KTC_NGAY_CHET IS NOT NULL
           AND k.KTC_NGAY_CHET >= p.NAM_DAU
         GROUP BY tg.TG_MA

        UNION ALL

        SELECT 13,
               CAST(u' 12. Tr\1ed1n ch\01b0a b\1eaft l\1ea1i' AS NVARCHAR2(200)),
               tg.TG_MA,
               COUNT(DISTINCT tt.PHAM_NHAN_ID),
               CAST(u'DS_TRON_TRAI' AS NVARCHAR2(100))
          FROM QLPN.TRON_TRAIS tt
         INNER JOIN rt_core r ON r.PHAM_NHAN_ID = tt.PHAM_NHAN_ID
         INNER JOIN dm_tg tg ON tg.ID = r.LL_TRAI_GIAM_ID
         WHERE NVL(tt.IS_DELETED, 0) = 0
           AND tt.NGAY_BAT_LAI IS NULL
         GROUP BY tg.TG_MA

        UNION ALL

        SELECT 14,
               CAST(u' 13. H\1ee7y \00e1n' AS NVARCHAR2(200)),
               tg.TG_MA,
               COUNT(DISTINCT h.PHAM_NHAN_ID),
               CAST(u'DS_HUY_AN' AS NVARCHAR2(100))
          FROM QLPN.HUY_ANS h
         INNER JOIN rt_core r ON r.PHAM_NHAN_ID = h.PHAM_NHAN_ID
         INNER JOIN dm_tg tg ON tg.ID = r.LL_TRAI_GIAM_ID
         WHERE NVL(h.IS_DELETED, 0) = 0
           AND h.NGAY_TRA_TU_DO IS NOT NULL
         GROUP BY tg.TG_MA

        UNION ALL

        SELECT 15,
               CAST(u' 14. Mi\1ec5n h\00ecnh ph\1ea1t' AS NVARCHAR2(200)),
               tg.TG_MA,
               COUNT(DISTINCT m.PN_LAI_LICH_ID),
               CAST(u'DS_MIEN_HINH_PHAT' AS NVARCHAR2(100))
          FROM QLPN.MIEN_HINH_PHATS m
         INNER JOIN rt_core r ON r.PHAM_NHAN_ID = m.PN_LAI_LICH_ID
         INNER JOIN dm_tg tg ON tg.ID = r.LL_TRAI_GIAM_ID
         WHERE NVL(m.IS_DELETED, 0) = 0
           AND m.MHP_NGAY_TU_DO IS NOT NULL
         GROUP BY tg.TG_MA

        UNION ALL

        SELECT 16,
               CAST(u' 15. Ho\00e3n thi h\00e0nh \00e1n' AS NVARCHAR2(200)),
               tg.TG_MA,
               COUNT(DISTINCT h.PHAM_NHAN_ID),
               CAST(u'DS_HOAN_THI_HANH_AN' AS NVARCHAR2(100))
          FROM QLPN.HOAN_THI_HANH_ANS h
         INNER JOIN rt_core r ON r.PHAM_NHAN_ID = h.PHAM_NHAN_ID
         INNER JOIN dm_tg tg ON tg.ID = r.LL_TRAI_GIAM_ID
         WHERE NVL(h.IS_DELETED, 0) = 0
         GROUP BY tg.TG_MA
      )
)
SELECT STT, TEN_TK, MA_TRAI_GIAM, TS, FRM
  FROM chi_tiet

UNION ALL

SELECT STT,
       TEN_TK,
       u'C10' AS MA_TRAI_GIAM,
       SUM(TS) AS TS,
       FRM
  FROM chi_tiet
 WHERE STT <> 11
 GROUP BY STT, TEN_TK, FRM
;
