--  DDL for Trigger TRG_LL_SYNC_HO_TEN_ORDER
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "QLPN"."TRG_LL_SYNC_HO_TEN_ORDER" 
BEFORE INSERT OR UPDATE OF LL_HO_TEN
ON "QLPN"."PN_LAI_LICHS"
FOR EACH ROW
BEGIN
    IF :NEW.LL_HO_TEN IS NULL THEN
        :NEW.HO_TEN_ORDER := NULL;
    ELSE
        -- PL/SQL assignment không dùng CAST(... AS VARCHAR2(n)); dùng SUBSTR
        :NEW.HO_TEN_ORDER := SUBSTR(ORDER_HOTEN(:NEW.LL_HO_TEN), 1, 4000);
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        -- Không ch?n DML n?u ORDER_HOTEN l?i edge case
        :NEW.HO_TEN_ORDER := NULL;
END;








