--------------------------------------------------------
--  DDL for Trigger TRG_PN_DTCDK_REFRESH_CACHE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "QLPN"."TRG_PN_DTCDK_REFRESH_CACHE" 
AFTER INSERT OR UPDATE OF DTCDK_TRANG_THAI, DTCDK_NGAY_XET, IS_DELETED
ON QLPN.PN_DOT_THA_CO_DIEU_KIENS
FOR EACH ROW
DECLARE
    v_job NUMBER;
    v_can_run BOOLEAN := FALSE;
BEGIN
    -- INSERT: b?n ghi m?i ?ang active và có ngày xét
    IF INSERTING THEN
        IF NVL(:NEW.IS_DELETED, 0) = 0
           AND :NEW.DTCDK_TRANG_THAI = 1
           AND :NEW.DTCDK_NGAY_XET IS NOT NULL
        THEN
            v_can_run := TRUE;
        END IF;

    -- UPDATE: v?a kích ho?t (TRANG_THAI thành 1), ho?c NGAY_XET ??i khi ?ang active
    ELSIF UPDATING THEN
        IF NVL(:NEW.IS_DELETED, 0) = 0
           AND :NEW.DTCDK_TRANG_THAI = 1
           AND :NEW.DTCDK_NGAY_XET IS NOT NULL
           AND (
               -- V?a chuy?n tr?ng thái sang m?
               NVL(:OLD.DTCDK_TRANG_THAI, 0) <> 1
               -- Ho?c ngày xét b? thay ??i
               OR NVL(TRUNC(:OLD.DTCDK_NGAY_XET), DATE '1900-01-01')
                  <> NVL(TRUNC(:NEW.DTCDK_NGAY_XET), DATE '1900-01-01')
           )
        THEN
            v_can_run := TRUE;
        END IF;
    END IF;

    IF v_can_run THEN
        -- DBMS_JOB ch?y SAU khi transaction commit ? SP_REFRESH ??c ?úng NGAY_XET m?i
        DBMS_JOB.SUBMIT(
            job  => v_job,
            what => 'BEGIN QLPN.SP_REFRESH_PN_TCDK_CACHE; EXCEPTION WHEN OTHERS THEN NULL; END;',
            next_date => SYSDATE
        );
    END IF;
END TRG_PN_DTCDK_REFRESH_CACHE;







/
ALTER TRIGGER "QLPN"."TRG_PN_DTCDK_REFRESH_CACHE" DISABLE;
--------------------------------------------------------
--  DDL for Trigger TRG_PN_LAI_LICH_CHI_TIET_RT_GTH
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "QLPN"."TRG_PN_LAI_LICH_CHI_TIET_RT_GTH" 
FOR INSERT OR UPDATE OR DELETE ON "QLPN"."GIAM_THOI_HANS"
COMPOUND TRIGGER
  TYPE t_ids IS TABLE OF NUMBER INDEX BY PLS_INTEGER;
  g_ids t_ids;
  g_count PLS_INTEGER := 0;

  PROCEDURE add_id(p_id IN NUMBER) IS
  BEGIN
    IF p_id IS NOT NULL THEN
      g_count := g_count + 1;
      g_ids(g_count) := p_id;
    END IF;
  END add_id;

  AFTER EACH ROW IS
  BEGIN
    IF INSERTING THEN
      add_id(:NEW.PHAM_NHAN_ID);
    ELSIF UPDATING THEN
      add_id(:NEW.PHAM_NHAN_ID);
      add_id(:OLD.PHAM_NHAN_ID);
    ELSIF DELETING THEN
      add_id(:OLD.PHAM_NHAN_ID);
    END IF;
  END AFTER EACH ROW;

  AFTER STATEMENT IS
  BEGIN
    FOR i IN 1 .. g_count LOOP
      "QLPN"."PKG_PN_LAI_LICH_CHI_TIET_RT".SAFE_REFRESH_REDUCTION_METRICS_ONE(
        p_pham_nhan_id => g_ids(i),
        p_source_table => 'GIAM_THOI_HANS',
        p_source_row_id => g_ids(i),
        p_action_name => 'INSERT_UPDATE_DELETE'
      );
    END LOOP;
  END AFTER STATEMENT;
END;







/
ALTER TRIGGER "QLPN"."TRG_PN_LAI_LICH_CHI_TIET_RT_GTH" ENABLE;
