--------------------------------------------------------
--  DDL for Trigger TRG_THA_SYNC_TOI_DANH_NAMES
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "QLPN"."TRG_THA_SYNC_TOI_DANH_NAMES" 
BEFORE INSERT OR UPDATE OF THA_TOI_DANH
ON QLPN.PN_THI_HANH_AN
FOR EACH ROW
DECLARE
    v_list   VARCHAR2(4000);
    v_names  NVARCHAR2(4000);
BEGIN
    -- Chu?n hóa: b? d?u ngo?c vuông []
    v_list := REPLACE(REPLACE(TRIM(:NEW.THA_TOI_DANH), '[', ''), ']', '');

    -- NULL / chu?i r?ng / ch? có d?u ngo?c ? clear tên
    IF v_list IS NULL OR TRIM(v_list) IS NULL THEN
        :NEW.THA_TOI_DANH_NAMES := NULL;
        RETURN;
    END IF;

    -- Tách CSV ID ? lookup tên ? LISTAGG
    SELECT LISTAGG(d.TD_TEN, '; ') WITHIN GROUP (ORDER BY pos)
    INTO   v_names
    FROM (
        SELECT
            LEVEL AS pos,
            TO_NUMBER(TRIM(REGEXP_SUBSTR(v_list, '[^,]+', 1, LEVEL))) AS toi_danh_id
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(v_list, ',') + 1
    ) s
    LEFT JOIN QLPN.DM_TOI_DANHS d
        ON d.ID = s.toi_danh_id
       AND NVL(d.IS_DELETED, 0) = 0;

    :NEW.THA_TOI_DANH_NAMES := v_names;
EXCEPTION
    WHEN OTHERS THEN
        -- Không ?? trigger fail ch?n DML; ghi NULL và ti?p t?c
        :NEW.THA_TOI_DANH_NAMES := NULL;
END;







/
ALTER TRIGGER "QLPN"."TRG_THA_SYNC_TOI_DANH_NAMES" ENABLE;
--------------------------------------------------------
--  DDL for Procedure SP_AUDIT_TINH_TRANG_ORPHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_AUDIT_TINH_TRANG_ORPHAN" 
AS
P_RESULT SYS_REFCURSOR;
BEGIN
    OPEN P_RESULT FOR
        WITH AUDIT_DATA AS (
                SELECT KC.ID AS MEMBER_ID,
                       'PN_KET_THUC_CHETS' AS TABLE_NAME,
                       KC.KTC_PN_LAI_LICH_ID AS PHAM_NHAN_ID
                  FROM QLPN.PN_KET_THUC_CHETS KC
                 WHERE NVL(KC.IS_DELETED, 0) = 0
                   AND (KC.KTC_PN_LAI_LICH_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = KC.KTC_PN_LAI_LICH_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT TDC.ID,
                       'TAM_DINH_CHIS',
                       TDC.PHAM_NHAN_ID
                  FROM QLPN.TAM_DINH_CHIS TDC
                 WHERE NVL(TDC.IS_DELETED, 0) = 0
                   AND (TDC.PHAM_NHAN_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = TDC.PHAM_NHAN_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT TX.ID,
                       'TRICH_XUATS',
                       TX.PHAM_NHAN_ID
                  FROM QLPN.TRICH_XUATS TX
                 WHERE NVL(TX.IS_DELETED, 0) = 0
                   AND (TX.PHAM_NHAN_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = TX.PHAM_NHAN_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT TT.ID,
                       'TRON_TRAIS',
                       TT.PHAM_NHAN_ID
                  FROM QLPN.TRON_TRAIS TT
                 WHERE NVL(TT.IS_DELETED, 0) = 0
                   AND (TT.PHAM_NHAN_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = TT.PHAM_NHAN_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT HA.ID,
                       'HUY_ANS',
                       HA.PHAM_NHAN_ID
                  FROM QLPN.HUY_ANS HA
                 WHERE NVL(HA.IS_DELETED, 0) = 0
                   AND (HA.PHAM_NHAN_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = HA.PHAM_NHAN_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT CG.ID,
                       'PN_CHUYEN_GIAO',
                       CG.PNCG_LAI_LICH_ID
                  FROM QLPN.PN_CHUYEN_GIAO CG
                 WHERE NVL(CG.IS_DELETED, 0) = 0
                   AND (CG.PNCG_LAI_LICH_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = CG.PNCG_LAI_LICH_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT MHP.ID,
                       'MIEN_HINH_PHATS',
                       MHP.PN_LAI_LICH_ID
                  FROM QLPN.MIEN_HINH_PHATS MHP
                 WHERE NVL(MHP.IS_DELETED, 0) = 0
                   AND (MHP.PN_LAI_LICH_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = MHP.PN_LAI_LICH_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT CT.ID,
                       'PHAM_NHAN_CHUYEN_TRAI',
                       CT.PNCT_LAI_LICH_ID
                  FROM QLPN.PHAM_NHAN_CHUYEN_TRAI CT
                 WHERE NVL(CT.IS_DELETED, 0) = 0
                   AND (CT.PNCT_LAI_LICH_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = CT.PNCT_LAI_LICH_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT DX.ID,
                       'PN_DAC_XAS',
                       DX.PNLAI_LICH_ID
                  FROM QLPN.PN_DAC_XAS DX
                 WHERE NVL(DX.IS_DELETED, 0) = 0
                   AND (DX.PNLAI_LICH_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = DX.PNLAI_LICH_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT TCK.ID,
                       'THA_CO_DIEU_KIENS',
                       TCK.PHAM_NHAN_ID
                  FROM QLPN.THA_CO_DIEU_KIENS TCK
                 WHERE NVL(TCK.IS_DELETED, 0) = 0
                   AND (TCK.PHAM_NHAN_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = TCK.PHAM_NHAN_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT GTH.ID,
                       'GIAM_THOI_HANS',
                       GTH.PHAM_NHAN_ID
                  FROM QLPN.GIAM_THOI_HANS GTH
                 WHERE NVL(GTH.IS_DELETED, 0) = 0
                   AND (GTH.PHAM_NHAN_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = GTH.PHAM_NHAN_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT HTHA.ID,
                       'HOAN_THI_HANH_ANS',
                       HTHA.PHAM_NHAN_ID
                  FROM QLPN.HOAN_THI_HANH_ANS HTHA
                 WHERE NVL(HTHA.IS_DELETED, 0) = 0
                   AND (HTHA.PHAM_NHAN_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = HTHA.PHAM_NHAN_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT KT.ID,
                       'PN_KET_THUC_RA_TRAIS',
                       KT.KTRT_PN_LAI_LICH_ID
                  FROM QLPN.PN_KET_THUC_RA_TRAIS KT
                 WHERE NVL(KT.IS_DELETED, 0) = 0
                   AND (KT.KTRT_PN_LAI_LICH_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = KT.KTRT_PN_LAI_LICH_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT CB.ID,
                       'CHUA_BENH_BAT_BUOCS',
                       CB.PHAM_NHAN_ID
                  FROM QLPN.CHUA_BENH_BAT_BUOCS CB
                 WHERE NVL(CB.IS_DELETED, 0) = 0
                   AND (CB.PHAM_NHAN_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = CB.PHAM_NHAN_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT GR.ID,
                       'PN_GIAM_RIENGS',
                       GR.GR_PN_LAI_LICH_ID
                  FROM QLPN.PN_GIAM_RIENGS GR
                 WHERE NVL(GR.IS_DELETED, 0) = 0
                   AND (GR.GR_PN_LAI_LICH_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = GR.GR_PN_LAI_LICH_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT THA.ID,
                       'PN_THI_HANH_AN__ORPHAN',
                       THA.THA_PNLAI_LICH_ID
                  FROM QLPN.PN_THI_HANH_AN THA
                 WHERE NVL(THA.IS_DELETED, 0) = 0
                   AND (THA.THA_PNLAI_LICH_ID IS NULL
                        OR NOT EXISTS (
                            SELECT 1
                              FROM QLPN.PN_LAI_LICHS LL
                             WHERE LL.ID = THA.THA_PNLAI_LICH_ID
                               AND NVL(LL.IS_DELETED, 0) = 0
                        ))
                UNION ALL
                SELECT LL.ID,
                       'PN_LAI_LICHS__NO_PN_THI_HANH_AN',
                       LL.ID
                  FROM QLPN.PN_LAI_LICHS LL
                 WHERE NVL(LL.IS_DELETED, 0) = 0
                   AND NOT EXISTS (
                        SELECT 1
                          FROM QLPN.PN_THI_HANH_AN THA
                         WHERE THA.THA_PNLAI_LICH_ID = LL.ID
                           AND NVL(THA.IS_DELETED, 0) = 0
                   )
                UNION ALL
                SELECT THA.ID,
                       'PN_THI_HANH_AN__DUPLICATE_KEYMAP',
                       THA.THA_PNLAI_LICH_ID
                  FROM QLPN.PN_THI_HANH_AN THA
                 WHERE NVL(THA.IS_DELETED, 0) = 0
                   AND THA.THA_PNLAI_LICH_ID IS NOT NULL
                   AND EXISTS (
                        SELECT 1
                          FROM QLPN.PN_LAI_LICHS LL
                         WHERE LL.ID = THA.THA_PNLAI_LICH_ID
                           AND NVL(LL.IS_DELETED, 0) = 0
                   )
                   AND 1 < (
                        SELECT COUNT(*)
                          FROM QLPN.PN_THI_HANH_AN THA2
                         WHERE THA2.THA_PNLAI_LICH_ID = THA.THA_PNLAI_LICH_ID
                           AND NVL(THA2.IS_DELETED, 0) = 0
                   )
        ),
        AUDIT_NUMBERED AS (
            SELECT ROW_NUMBER() OVER (ORDER BY TABLE_NAME, PHAM_NHAN_ID NULLS FIRST, MEMBER_ID) AS AUDIT_ID,
                   MEMBER_ID,
                   TABLE_NAME,
                   PHAM_NHAN_ID,
                   COUNT(*) OVER () AS TONG_CONG
              FROM AUDIT_DATA
        )
        SELECT AUDIT_ID,
               MEMBER_ID,
               TABLE_NAME,
               PHAM_NHAN_ID,
               TONG_CONG
          FROM AUDIT_NUMBERED
        UNION ALL
        SELECT NVL(MAX(AUDIT_ID), 0) + 1 AS AUDIT_ID,
               CAST(NULL AS NUMBER) AS MEMBER_ID,
               'TONG_CONG' AS TABLE_NAME,
               CAST(NULL AS NUMBER) AS PHAM_NHAN_ID,
               COUNT(*) AS TONG_CONG
          FROM AUDIT_NUMBERED
         ORDER BY AUDIT_ID;

    DBMS_SQL.RETURN_RESULT(P_RESULT);
END SP_AUDIT_TINH_TRANG_ORPHAN;






/
--------------------------------------------------------
--  DDL for Procedure SP_AUDIT_TINH_TRANG_PHAM_NHAN_V2
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_AUDIT_TINH_TRANG_PHAM_NHAN_V2" (
    P_PN_LAI_LICH_ID     IN NUMBER   DEFAULT NULL,
    P_AUDIT_DATE         IN DATE     DEFAULT SYSDATE,
    P_INCLUDE_RULE_CODES IN VARCHAR2 DEFAULT NULL,
    P_EXCLUDE_RULE_CODES IN VARCHAR2 DEFAULT NULL
) AS
    v_result SYS_REFCURSOR;
BEGIN
    OPEN v_result FOR
        WITH
        include_rules AS (
            SELECT DISTINCT UPPER(TRIM(REGEXP_SUBSTR(P_INCLUDE_RULE_CODES, '[^,]+', 1, LEVEL))) AS rule_code
              FROM dual
            CONNECT BY REGEXP_SUBSTR(P_INCLUDE_RULE_CODES, '[^,]+', 1, LEVEL) IS NOT NULL
        ),
        exclude_rules AS (
            SELECT DISTINCT UPPER(TRIM(REGEXP_SUBSTR(P_EXCLUDE_RULE_CODES, '[^,]+', 1, LEVEL))) AS rule_code
              FROM dual
            CONNECT BY REGEXP_SUBSTR(P_EXCLUDE_RULE_CODES, '[^,]+', 1, LEVEL) IS NOT NULL
        ),
        targets AS (
            SELECT ll.id,
                   ll.ll_tinh_trang_id
              FROM pn_lai_lichs ll
             WHERE ll.is_deleted = 0
               AND (P_PN_LAI_LICH_ID IS NULL OR ll.id = P_PN_LAI_LICH_ID)
        ),
        current_status AS (
            SELECT t.id AS pn_lai_lich_id,
                   dm.ttpn_ma AS current_status_code,
                   dm.ttpn_ten AS current_status_name
              FROM targets t
              LEFT JOIN dm_tinh_trang_pham_nhans dm
                     ON dm.id = t.ll_tinh_trang_id
                    AND dm.is_deleted = 0
        ),
        death_dates AS (
            SELECT kc.ktc_pn_lai_lich_id AS pn_lai_lich_id,
                   MIN(kc.ktc_ngay_chet) AS death_date
              FROM pn_ket_thuc_chets kc
              JOIN targets t
                ON t.id = kc.ktc_pn_lai_lich_id
             WHERE kc.is_deleted = 0
               AND kc.ktc_ngay_chet IS NOT NULL
               AND kc.ktc_ngay_chet < P_AUDIT_DATE + 1
             GROUP BY kc.ktc_pn_lai_lich_id
        ),
        terminal_dates AS (
            SELECT pn_lai_lich_id,
                   MIN(terminal_date) AS terminal_date
              FROM (
                    SELECT mhp.pn_lai_lich_id,
                           mhp.mhp_ngay_tu_do AS terminal_date
                      FROM mien_hinh_phats mhp
                      JOIN targets t ON t.id = mhp.pn_lai_lich_id
                     WHERE mhp.is_deleted = 0
                       AND mhp.mhp_ngay_tu_do IS NOT NULL
                       AND mhp.mhp_ngay_tu_do < P_AUDIT_DATE + 1
                    UNION ALL
                    SELECT dx.pnlai_lich_id,
                           dx.dx_ngay_tha
                      FROM pn_dac_xas dx
                      JOIN targets t ON t.id = dx.pnlai_lich_id
                     WHERE dx.is_deleted = 0
                       AND dx.dx_ngay_tha IS NOT NULL
                       AND dx.dx_ngay_tha < P_AUDIT_DATE + 1
                    UNION ALL
                    SELECT gth.pham_nhan_id,
                           gth.ngay_tha_giam_het_an
                      FROM giam_thoi_hans gth
                      JOIN targets t ON t.id = gth.pham_nhan_id
                     WHERE gth.is_deleted = 0
                       AND gth.ngay_tha_giam_het_an IS NOT NULL
                       AND gth.ngay_tha_giam_het_an < P_AUDIT_DATE + 1
                    UNION ALL
                    SELECT rt.ktrt_pn_lai_lich_id,
                           rt.ktrt_ngay_tha
                      FROM pn_ket_thuc_ra_trais rt
                      JOIN targets t ON t.id = rt.ktrt_pn_lai_lich_id
                     WHERE rt.is_deleted = 0
                       AND rt.ktrt_ngay_tha IS NOT NULL
                       AND rt.ktrt_ngay_tha < P_AUDIT_DATE + 1
              )
             GROUP BY pn_lai_lich_id
        ),
        post_death_events AS (
            SELECT d.pn_lai_lich_id,
                   TO_NCHAR('TRICH_XUATS') AS source_table,
                   tx.id AS source_id,
                   d.death_date AS death_date,
                   tx.tx_ngay_trich_xuat AS event_date,
                   TO_NCHAR('TX_NGAY_TRICH_XUAT sau ngày ch?t') AS message
              FROM death_dates d
              JOIN trich_xuats tx
                ON tx.pham_nhan_id = d.pn_lai_lich_id
               AND tx.is_deleted = 0
               AND tx.tx_ngay_trich_xuat IS NOT NULL
               AND tx.tx_ngay_trich_xuat > d.death_date
            UNION ALL
            SELECT d.pn_lai_lich_id,
                   TO_NCHAR('TAM_DINH_CHIS'),
                   tdc.id,
                   d.death_date,
                   tdc.ngay_tdc,
                   TO_NCHAR('NGAY_TDC sau ngày ch?t')
              FROM death_dates d
              JOIN tam_dinh_chis tdc
                ON tdc.pham_nhan_id = d.pn_lai_lich_id
               AND tdc.is_deleted = 0
               AND tdc.ngay_tdc IS NOT NULL
               AND tdc.ngay_tdc > d.death_date
            UNION ALL
            SELECT d.pn_lai_lich_id,
                   TO_NCHAR('TRON_TRAIS'),
                   tr.id,
                   d.death_date,
                   tr.ngay_tron,
                   TO_NCHAR('NGAY_TRON sau ngày ch?t')
              FROM death_dates d
              JOIN tron_trais tr
                ON tr.pham_nhan_id = d.pn_lai_lich_id
               AND tr.is_deleted = 0
               AND tr.ngay_tron IS NOT NULL
               AND tr.ngay_tron > d.death_date
            UNION ALL
            SELECT d.pn_lai_lich_id,
                   TO_NCHAR('PHAM_NHAN_CHUYEN_TRAI'),
                   ct.id,
                   d.death_date,
                   ct.pnct_ngay_chuyen,
                   TO_NCHAR('PNCT_NGAY_CHUYEN sau ngày ch?t')
              FROM death_dates d
              JOIN pham_nhan_chuyen_trai ct
                ON ct.pnct_lai_lich_id = d.pn_lai_lich_id
               AND ct.is_deleted = 0
               AND ct.pnct_ngay_chuyen IS NOT NULL
               AND ct.pnct_ngay_chuyen > d.death_date
            UNION ALL
            SELECT d.pn_lai_lich_id,
                   TO_NCHAR('PN_CHUYEN_GIAO'),
                   cg.id,
                   d.death_date,
                   cg.pncg_ngay_chuyen_giao,
                   TO_NCHAR('PNCG_NGAY_CHUYEN_GIAO sau ngày ch?t')
              FROM death_dates d
              JOIN pn_chuyen_giao cg
                ON cg.pncg_lai_lich_id = d.pn_lai_lich_id
               AND cg.is_deleted = 0
               AND cg.pncg_ngay_chuyen_giao IS NOT NULL
               AND cg.pncg_ngay_chuyen_giao > d.death_date
            UNION ALL
            SELECT d.pn_lai_lich_id,
                   TO_NCHAR('PN_KET_THUC_RA_TRAIS'),
                   rt.id,
                   d.death_date,
                   rt.ktrt_ngay_tha,
                   TO_NCHAR('KTRT_NGAY_THA sau ngày ch?t')
              FROM death_dates d
              JOIN pn_ket_thuc_ra_trais rt
                ON rt.ktrt_pn_lai_lich_id = d.pn_lai_lich_id
               AND rt.is_deleted = 0
               AND rt.ktrt_ngay_tha IS NOT NULL
               AND rt.ktrt_ngay_tha > d.death_date
        ),
        post_terminal_open_events AS (
            SELECT td.pn_lai_lich_id,
                   TO_NCHAR('TRICH_XUATS') AS source_table,
                   tx.id AS source_id,
                   tx.tx_ngay_trich_xuat AS event_date,
                   TO_NCHAR('Trích xu?t còn hi?u l?c sau m?c k?t thúc') AS message
              FROM terminal_dates td
              JOIN trich_xuats tx
                ON tx.pham_nhan_id = td.pn_lai_lich_id
               AND tx.is_deleted = 0
               AND tx.tx_loai_lenh_id = 1
               AND tx.tx_ngay_trich_xuat IS NOT NULL
               AND tx.tx_ngay_trich_xuat > td.terminal_date
               AND tx.tx_ngay_trich_xuat < P_AUDIT_DATE + 1
               AND NVL(tx.tx_ngay_tra, P_AUDIT_DATE + 1) >= P_AUDIT_DATE + 1
            UNION ALL
            SELECT td.pn_lai_lich_id,
                   TO_NCHAR('TAM_DINH_CHIS'),
                   tdc.id,
                   tdc.ngay_tdc,
                   TO_NCHAR('T?m ?ình ch? còn hi?u l?c sau m?c k?t thúc')
              FROM terminal_dates td
              JOIN tam_dinh_chis tdc
                ON tdc.pham_nhan_id = td.pn_lai_lich_id
               AND tdc.is_deleted = 0
               AND tdc.ngay_tdc IS NOT NULL
               AND tdc.ngay_tdc > td.terminal_date
               AND tdc.ngay_tdc < P_AUDIT_DATE + 1
               AND NVL(tdc.ngay_lai, P_AUDIT_DATE + 1) >= P_AUDIT_DATE + 1
            UNION ALL
            SELECT td.pn_lai_lich_id,
                   TO_NCHAR('TRON_TRAIS'),
                   tr.id,
                   tr.ngay_tron,
                   TO_NCHAR('Tr?n tr?i còn hi?u l?c sau m?c k?t thúc')
              FROM terminal_dates td
              JOIN tron_trais tr
                ON tr.pham_nhan_id = td.pn_lai_lich_id
               AND tr.is_deleted = 0
               AND tr.ngay_tron IS NOT NULL
               AND tr.ngay_tron > td.terminal_date
               AND tr.ngay_tron < P_AUDIT_DATE + 1
               AND NVL(tr.ngay_bat_lai, P_AUDIT_DATE + 1) >= P_AUDIT_DATE + 1
            UNION ALL
            SELECT td.pn_lai_lich_id,
                   TO_NCHAR('PN_GIAM_RIENGS'),
                   gr.id,
                   gr.gr_ngay_bat_dau,
                   TO_NCHAR('Giam riêng còn hi?u l?c sau m?c k?t thúc')
              FROM terminal_dates td
              JOIN pn_giam_riengs gr
                ON gr.gr_pn_lai_lich_id = td.pn_lai_lich_id
               AND gr.is_deleted = 0
               AND gr.gr_ngay_bat_dau IS NOT NULL
               AND gr.gr_ngay_bat_dau > td.terminal_date
               AND gr.gr_ngay_bat_dau < P_AUDIT_DATE + 1
               AND NVL(gr.gr_ngay_ketthuc, P_AUDIT_DATE + 1) >= P_AUDIT_DATE + 1
            UNION ALL
            SELECT td.pn_lai_lich_id,
                   TO_NCHAR('CHUA_BENH_BAT_BUOCS'),
                   cb.id,
                   cb.tu_ngay,
                   TO_NCHAR('B?t bu?c ch?a b?nh còn hi?u l?c sau m?c k?t thúc')
              FROM terminal_dates td
              JOIN chua_benh_bat_buocs cb
                ON cb.pham_nhan_id = td.pn_lai_lich_id
               AND cb.is_deleted = 0
               AND cb.tu_ngay IS NOT NULL
               AND cb.tu_ngay > td.terminal_date
               AND cb.tu_ngay < P_AUDIT_DATE + 1
               AND NVL(cb.ngay_ket_thuc, P_AUDIT_DATE + 1) >= P_AUDIT_DATE + 1
            UNION ALL
            SELECT td.pn_lai_lich_id,
                   TO_NCHAR('HOAN_THI_HANH_ANS'),
                   ht.id,
                   ht.ngay_hoan,
                   TO_NCHAR('Hoãn thi hành án còn hi?u l?c sau m?c k?t thúc')
              FROM terminal_dates td
              JOIN hoan_thi_hanh_ans ht
                ON ht.pham_nhan_id = td.pn_lai_lich_id
               AND ht.is_deleted = 0
               AND ht.ngay_hoan IS NOT NULL
               AND ht.ngay_hoan > td.terminal_date
               AND ht.ngay_hoan < P_AUDIT_DATE + 1
               AND NVL(ht.ngay_thi_hanh_an, P_AUDIT_DATE + 1) >= P_AUDIT_DATE + 1
        ),
        duplicate_open_events AS (
            SELECT TO_NCHAR('STATUS_002') AS rule_code,
                   TO_NCHAR('DUPLICATE_OPEN') AS rule_group,
                   TO_NCHAR('HIGH') AS severity,
                   tx.pham_nhan_id AS pn_lai_lich_id,
                   tx.pham_nhan_id AS pham_nhan_id,
                   TO_NCHAR('TRICH_XUATS') AS source_table,
                   CAST(NULL AS NUMBER) AS source_id,
                   TO_NCHAR('Có nhi?u b?n ghi trích xu?t ?ang cùng hi?u l?c') AS message,
                   TO_NCHAR('OPEN_COUNT=') || TO_NCHAR(COUNT(*)) AS detail_json
              FROM trich_xuats tx
              JOIN targets t ON t.id = tx.pham_nhan_id
             WHERE tx.is_deleted = 0
               AND tx.tx_loai_lenh_id = 1
               AND tx.tx_ngay_trich_xuat IS NOT NULL
               AND tx.tx_ngay_trich_xuat < P_AUDIT_DATE + 1
               AND NVL(tx.tx_ngay_tra, P_AUDIT_DATE + 1) >= P_AUDIT_DATE + 1
             GROUP BY tx.pham_nhan_id
            HAVING COUNT(*) > 1
            UNION ALL
            SELECT TO_NCHAR('STATUS_002'),
                   TO_NCHAR('DUPLICATE_OPEN'),
                   TO_NCHAR('HIGH'),
                   tdc.pham_nhan_id,
                   tdc.pham_nhan_id,
                   TO_NCHAR('TAM_DINH_CHIS'),
                   CAST(NULL AS NUMBER),
                   TO_NCHAR('Có nhi?u b?n ghi t?m ?ình ch? ?ang cùng hi?u l?c'),
                   TO_NCHAR('OPEN_COUNT=') || TO_NCHAR(COUNT(*))
              FROM tam_dinh_chis tdc
              JOIN targets t ON t.id = tdc.pham_nhan_id
             WHERE tdc.is_deleted = 0
               AND tdc.ngay_tdc IS NOT NULL
               AND tdc.ngay_tdc < P_AUDIT_DATE + 1
               AND NVL(tdc.ngay_lai, P_AUDIT_DATE + 1) >= P_AUDIT_DATE + 1
             GROUP BY tdc.pham_nhan_id
            HAVING COUNT(*) > 1
            UNION ALL
            SELECT TO_NCHAR('STATUS_002'),
                   TO_NCHAR('DUPLICATE_OPEN'),
                   TO_NCHAR('HIGH'),
                   tr.pham_nhan_id,
                   tr.pham_nhan_id,
                   TO_NCHAR('TRON_TRAIS'),
                   CAST(NULL AS NUMBER),
                   TO_NCHAR('Có nhi?u b?n ghi tr?n tr?i ?ang cùng hi?u l?c'),
                   TO_NCHAR('OPEN_COUNT=') || TO_NCHAR(COUNT(*))
              FROM tron_trais tr
              JOIN targets t ON t.id = tr.pham_nhan_id
             WHERE tr.is_deleted = 0
               AND tr.ngay_tron IS NOT NULL
               AND tr.ngay_tron < P_AUDIT_DATE + 1
               AND NVL(tr.ngay_bat_lai, P_AUDIT_DATE + 1) >= P_AUDIT_DATE + 1
             GROUP BY tr.pham_nhan_id
            HAVING COUNT(*) > 1
        ),
        audit_rows AS (
            SELECT TO_NCHAR('GR_001') AS rule_code,
                   TO_NCHAR('GIAM RIENG') AS rule_group,
                   TO_NCHAR('HIGH') AS severity,
                   gr.gr_pn_lai_lich_id AS pn_lai_lich_id,
                   gr.gr_pn_lai_lich_id AS pham_nhan_id,
                   TO_NCHAR('PN_GIAM_RIENGS') AS source_table,
                   gr.id AS source_id,
                   TO_NCHAR('GR_NGAY_KETTHUC < GR_NGAY_QUYET_DINH_GIAM_RIENG') AS message,
                   TO_NCHAR('GR_NGAY_QUYET_DINH_GIAM_RIENG=') || TO_NCHAR(TO_CHAR(gr.gr_ngay_quyet_dinh_giam_rieng, 'YYYY-MM-DD HH24:MI:SS'))
                   || TO_NCHAR(';GR_NGAY_KETTHUC=') || TO_NCHAR(TO_CHAR(gr.gr_ngay_ketthuc, 'YYYY-MM-DD HH24:MI:SS')) AS detail_json
              FROM pn_giam_riengs gr
              JOIN targets t ON t.id = gr.gr_pn_lai_lich_id
             WHERE gr.is_deleted = 0
               AND gr.gr_ngay_quyet_dinh_giam_rieng IS NOT NULL
               AND gr.gr_ngay_ketthuc IS NOT NULL
               AND gr.gr_ngay_ketthuc < gr.gr_ngay_quyet_dinh_giam_rieng
            UNION ALL
            SELECT TO_NCHAR('BBCB_001'),
                   TO_NCHAR('BAT_BUOC_CHUA_BENH'),
                   TO_NCHAR('HIGH'),
                   cb.pham_nhan_id,
                   cb.pham_nhan_id,
                   TO_NCHAR('CHUA_BENH_BAT_BUOCS'),
                   cb.id,
                   TO_NCHAR('NGAY_KET_THUC < TU_NGAY'),
                   TO_NCHAR('TU_NGAY=') || TO_NCHAR(TO_CHAR(cb.tu_ngay, 'YYYY-MM-DD HH24:MI:SS'))
                   || TO_NCHAR(';NGAY_KET_THUC=') || TO_NCHAR(TO_CHAR(cb.ngay_ket_thuc, 'YYYY-MM-DD HH24:MI:SS'))
              FROM chua_benh_bat_buocs cb
              JOIN targets t ON t.id = cb.pham_nhan_id
             WHERE cb.is_deleted = 0
               AND cb.tu_ngay IS NOT NULL
               AND cb.ngay_ket_thuc IS NOT NULL
               AND cb.ngay_ket_thuc < cb.tu_ngay
            UNION ALL
            SELECT TO_NCHAR('TRON_001'),
                   TO_NCHAR('TRON_TRAI'),
                   TO_NCHAR('HIGH'),
                   tr.pham_nhan_id,
                   tr.pham_nhan_id,
                   TO_NCHAR('TRON_TRAIS'),
                   tr.id,
                   TO_NCHAR('NGAY_BAT_LAI < NGAY_TRON'),
                   TO_NCHAR('NGAY_TRON=') || TO_NCHAR(TO_CHAR(tr.ngay_tron, 'YYYY-MM-DD HH24:MI:SS'))
                   || TO_NCHAR(';NGAY_BAT_LAI=') || TO_NCHAR(TO_CHAR(tr.ngay_bat_lai, 'YYYY-MM-DD HH24:MI:SS'))
              FROM tron_trais tr
              JOIN targets t ON t.id = tr.pham_nhan_id
             WHERE tr.is_deleted = 0
               AND tr.ngay_tron IS NOT NULL
               AND tr.ngay_bat_lai IS NOT NULL
               AND tr.ngay_bat_lai < tr.ngay_tron
            UNION ALL
            SELECT TO_NCHAR('TX_001'),
                   TO_NCHAR('TRICH_XUAT'),
                   TO_NCHAR('HIGH'),
                   tx.pham_nhan_id,
                   tx.pham_nhan_id,
                   TO_NCHAR('TRICH_XUATS'),
                   tx.id,
                   TO_NCHAR('TX_NGAY_TRA < TX_NGAY_TRICH_XUAT'),
                   TO_NCHAR('TX_NGAY_TRICH_XUAT=') || TO_NCHAR(TO_CHAR(tx.tx_ngay_trich_xuat, 'YYYY-MM-DD HH24:MI:SS'))
                   || TO_NCHAR(';TX_NGAY_TRA=') || TO_NCHAR(TO_CHAR(tx.tx_ngay_tra, 'YYYY-MM-DD HH24:MI:SS'))
              FROM trich_xuats tx
              JOIN targets t ON t.id = tx.pham_nhan_id
             WHERE tx.is_deleted = 0
               AND tx.tx_ngay_trich_xuat IS NOT NULL
               AND tx.tx_ngay_tra IS NOT NULL
               AND tx.tx_ngay_tra < tx.tx_ngay_trich_xuat
            UNION ALL
            SELECT TO_NCHAR('TDC_001'),
                   TO_NCHAR('TAM_DINH_CHI'),
                   TO_NCHAR('HIGH'),
                   tdc.pham_nhan_id,
                   tdc.pham_nhan_id,
                   TO_NCHAR('TAM_DINH_CHIS'),
                   tdc.id,
                   TO_NCHAR('NGAY_LAI < NGAY_TDC'),
                   TO_NCHAR('NGAY_TDC=') || TO_NCHAR(TO_CHAR(tdc.ngay_tdc, 'YYYY-MM-DD HH24:MI:SS'))
                   || TO_NCHAR(';NGAY_LAI=') || TO_NCHAR(TO_CHAR(tdc.ngay_lai, 'YYYY-MM-DD HH24:MI:SS'))
              FROM tam_dinh_chis tdc
              JOIN targets t ON t.id = tdc.pham_nhan_id
             WHERE tdc.is_deleted = 0
               AND tdc.ngay_tdc IS NOT NULL
               AND tdc.ngay_lai IS NOT NULL
               AND tdc.ngay_lai < tdc.ngay_tdc
            UNION ALL
            SELECT TO_NCHAR('HOAN_001'),
                   TO_NCHAR('HOAN_THI_HANH_AN'),
                   TO_NCHAR('HIGH'),
                   ht.pham_nhan_id,
                   ht.pham_nhan_id,
                   TO_NCHAR('HOAN_THI_HANH_ANS'),
                   ht.id,
                   TO_NCHAR('NGAY_THI_HANH_AN < NGAY_HOAN'),
                   TO_NCHAR('NGAY_HOAN=') || TO_NCHAR(TO_CHAR(ht.ngay_hoan, 'YYYY-MM-DD HH24:MI:SS'))
                   || TO_NCHAR(';NGAY_THI_HANH_AN=') || TO_NCHAR(TO_CHAR(ht.ngay_thi_hanh_an, 'YYYY-MM-DD HH24:MI:SS'))
              FROM hoan_thi_hanh_ans ht
              JOIN targets t ON t.id = ht.pham_nhan_id
             WHERE ht.is_deleted = 0
               AND ht.ngay_hoan IS NOT NULL
               AND ht.ngay_thi_hanh_an IS NOT NULL
               AND ht.ngay_thi_hanh_an < ht.ngay_hoan
            UNION ALL
            SELECT TO_NCHAR('HUYAN_001'),
                   TO_NCHAR('HUY_AN'),
                   TO_NCHAR('HIGH'),
                   ha.pham_nhan_id,
                   ha.pham_nhan_id,
                   TO_NCHAR('HUY_ANS'),
                   ha.id,
                   TO_NCHAR('NGAY_TRO_LAI < NGAY_TRA_TU_DO'),
                   TO_NCHAR('NGAY_TRA_TU_DO=') || TO_NCHAR(TO_CHAR(ha.ngay_tra_tu_do, 'YYYY-MM-DD HH24:MI:SS'))
                   || TO_NCHAR(';NGAY_TRO_LAI=') || TO_NCHAR(TO_CHAR(ha.ngay_tro_lai, 'YYYY-MM-DD HH24:MI:SS'))
              FROM huy_ans ha
              JOIN targets t ON t.id = ha.pham_nhan_id
             WHERE ha.is_deleted = 0
               AND ha.ngay_tra_tu_do IS NOT NULL
               AND ha.ngay_tro_lai IS NOT NULL
               AND ha.ngay_tro_lai < ha.ngay_tra_tu_do
            UNION ALL
            SELECT TO_NCHAR('THACDK_001'),
                   TO_NCHAR('THA_CO_DIEU_KIEN'),
                   TO_NCHAR('HIGH'),
                   tc.pham_nhan_id,
                   tc.pham_nhan_id,
                   TO_NCHAR('THA_CO_DIEU_KIENS'),
                   tc.id,
                   TO_NCHAR('NGAY_BAT_LAI < NGAY_THA'),
                   TO_NCHAR('NGAY_THA=') || TO_NCHAR(TO_CHAR(tc.ngay_tha, 'YYYY-MM-DD HH24:MI:SS'))
                   || TO_NCHAR(';NGAY_BAT_LAI=') || TO_NCHAR(TO_CHAR(tc.ngay_bat_lai, 'YYYY-MM-DD HH24:MI:SS'))
              FROM tha_co_dieu_kiens tc
              JOIN targets t ON t.id = tc.pham_nhan_id
             WHERE tc.is_deleted = 0
               AND tc.ngay_tha IS NOT NULL
               AND tc.ngay_bat_lai IS NOT NULL
               AND tc.ngay_bat_lai < tc.ngay_tha
            UNION ALL
            SELECT TO_NCHAR('END_001'),
                   TO_NCHAR('POST_DEATH_EVENT'),
                   TO_NCHAR('HIGH'),
                   pde.pn_lai_lich_id,
                   pde.pn_lai_lich_id,
                   pde.source_table,
                   pde.source_id,
                   pde.message,
                   TO_NCHAR('NGAY_CHET=') || TO_NCHAR(TO_CHAR(pde.death_date, 'YYYY-MM-DD HH24:MI:SS'))
                   || TO_NCHAR(';EVENT_DATE=') || TO_NCHAR(TO_CHAR(pde.event_date, 'YYYY-MM-DD HH24:MI:SS'))
              FROM post_death_events pde
            UNION ALL
            SELECT TO_NCHAR('END_002'),
                   TO_NCHAR('POST_TERMINAL_OPEN_EVENT'),
                   TO_NCHAR('HIGH'),
                   pto.pn_lai_lich_id,
                   pto.pn_lai_lich_id,
                   pto.source_table,
                   pto.source_id,
                   pto.message,
                   TO_NCHAR('EVENT_DATE=') || TO_NCHAR(TO_CHAR(pto.event_date, 'YYYY-MM-DD HH24:MI:SS'))
              FROM post_terminal_open_events pto
            UNION ALL
            SELECT TO_NCHAR('RATRAI_001'),
                   TO_NCHAR('RA_TRAI_CONFLICT'),
                   TO_NCHAR('HIGH'),
                   pto.pn_lai_lich_id,
                   pto.pn_lai_lich_id,
                   pto.source_table,
                   pto.source_id,
                   pto.message,
                   TO_NCHAR('EVENT_DATE=') || TO_NCHAR(TO_CHAR(pto.event_date, 'YYYY-MM-DD HH24:MI:SS'))
              FROM post_terminal_open_events pto
              JOIN pn_ket_thuc_ra_trais rt
                ON rt.ktrt_pn_lai_lich_id = pto.pn_lai_lich_id
               AND rt.is_deleted = 0
               AND rt.ktrt_ngay_tha IS NOT NULL
               AND pto.event_date > rt.ktrt_ngay_tha
            UNION ALL
            SELECT rule_code,
                   rule_group,
                   severity,
                   pn_lai_lich_id,
                   pham_nhan_id,
                   source_table,
                   source_id,
                   message,
                   detail_json
              FROM duplicate_open_events
        )
        SELECT TO_NCHAR(fr.rule_code) AS rule_code,
               TO_NCHAR(fr.rule_group) AS rule_group,
               fr.pham_nhan_id,
               TO_NCHAR(fr.source_table) AS source_table,
               fr.source_id,
               TO_NCHAR(cs.current_status_code) AS current_status_code,
               TO_NCHAR(cs.current_status_name) AS current_status_name,
               TO_NCHAR(fr.message) AS message,
               TO_NCHAR(fr.detail_json) AS detail_json,
               P_AUDIT_DATE AS audit_date,
               COUNT(*) OVER () AS total_records
          FROM (
                SELECT ar.*
                  FROM audit_rows ar
                 WHERE (
                        P_INCLUDE_RULE_CODES IS NULL
                        OR EXISTS (
                            SELECT 1
                              FROM include_rules ir
                             WHERE ir.rule_code = UPPER(ar.rule_code)
                        )
                 )
                   AND NOT EXISTS (
                        SELECT 1
                          FROM exclude_rules er
                         WHERE er.rule_code = UPPER(ar.rule_code)
                   )
          ) fr
          LEFT JOIN current_status cs
            ON cs.pn_lai_lich_id = fr.pn_lai_lich_id
         ORDER BY fr.severity DESC, fr.rule_code, fr.pn_lai_lich_id, fr.source_table, fr.source_id;
    DBMS_SQL.RETURN_RESULT(v_result);
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_BAO_CAO_THA_TU_TRUOC_THOI_HAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_BAO_CAO_THA_TU_TRUOC_THOI_HAN" (
    p_pn_ids     IN NVARCHAR2 DEFAULT NULL,
    p_dot_tha_id IN NUMBER    DEFAULT NULL,
    p_ma_trai_giam IN varchar2 default null
)
IS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
	ID_LIST AS (
	    SELECT DISTINCT
	        TO_NUMBER(
	            REGEXP_SUBSTR(
	                REPLACE(REPLACE(TRIM(p_pn_ids), '[', ''), ']', ''),
	                '[0-9]+', 1, LEVEL
	            )
	        ) AS PN_ID
	    FROM DUAL
	    WHERE p_pn_ids IS NOT NULL
	      AND LENGTH(TRIM(p_pn_ids)) > 0
	    CONNECT BY LEVEL <= REGEXP_COUNT(
	                    REPLACE(REPLACE(TRIM(p_pn_ids), '[', ''), ']', ''),
	                    '[0-9]+'
	                )
	           AND PRIOR SYS_GUID() IS NOT NULL
	),
    dot_ngay_xet AS (
        SELECT TRUNC(dot.DTCDK_NGAY_XET) AS NGAY_XET
        FROM PN_DOT_THA_CO_DIEU_KIENS dot
        WHERE dot.ID = p_dot_tha_id
          AND NVL(dot.IS_DELETED, 0) = 0
    ),
    tha_filtered AS (
        SELECT
            t.PHAM_NHAN_ID,
            t.NGAY_XET,
            t.TINH_TRANG_ID,
            dmt.TCDK_MA,
            ROW_NUMBER() OVER (
                PARTITION BY t.PHAM_NHAN_ID
                ORDER BY t.NGAY_XET DESC
            ) AS rn
        FROM THA_CO_DIEU_KIENS t
        LEFT JOIN DM_THA_CO_DIEU_KIENS dmt
            ON t.TINH_TRANG_ID = dmt.ID
        WHERE NVL(t.IS_DELETED, 0) = 0
          AND (p_pn_ids IS NULL OR t.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
          AND (p_dot_tha_id IS NULL OR EXISTS (
                SELECT 1
                FROM PN_DOT_THA_CO_DIEU_KIENS dot
                WHERE TRUNC(dot.DTCDK_NGAY_XET) = TRUNC(t.NGAY_XET)
                  AND dot.ID = p_dot_tha_id
                  AND NVL(dot.IS_DELETED, 0) = 0
          ))
    ),
    latest_tha AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            ptha.THA_AN_PHAT,
            ptha.THA_THOI_GIAN_CON_LAI,
            ROW_NUMBER() OVER (
                PARTITION BY ptha.THA_PNLAI_LICH_ID
                ORDER BY NVL(ptha.THA_NGAY_BAN_AN,
                             TO_DATE('01-JAN-1900', 'DD-MON-YYYY')) DESC,
                         ptha.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN ptha
        INNER JOIN tha_filtered tf
            ON tf.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID AND tf.rn = 1
    ),
    an_phat_ymd AS (
        SELECT
            tf.PHAM_NHAN_ID,
            tf.TINH_TRANG_ID,
            lt.THA_AN_PHAT,
            lt.THA_THOI_GIAN_CON_LAI,
            QLPN.FN_PARSE_AN_PHAT_TO_YMD(lt.THA_AN_PHAT) AS YMD,
            tf.TCDK_MA
        FROM tha_filtered tf
        LEFT JOIN latest_tha lt
            ON lt.THA_PNLAI_LICH_ID = tf.PHAM_NHAN_ID AND lt.rn = 1
        WHERE tf.rn = 1
    ),
    an_phat_classified AS (
        SELECT
            apy.PHAM_NHAN_ID,
            apy.TINH_TRANG_ID,
            apy.THA_THOI_GIAN_CON_LAI,
            apy.TCDK_MA,
            CASE
                WHEN LOWER(apy.THA_AN_PHAT) LIKE '%chung th%n%'
                 AND LOWER(apy.THA_AN_PHAT) NOT LIKE '%gi%m%'
                THEN 'CHUNG_THAN'
                ELSE CASE
                    WHEN (NVL(apy.YMD.nam, 0) * 12 + NVL(apy.YMD.thang, 0)
                          + CASE WHEN NVL(apy.YMD.ngay, 0) > 0 THEN 1 ELSE 0 END
                         ) < 36    THEN '3N_TRO_XUONG'
                    WHEN (NVL(apy.YMD.nam, 0) * 12
                          + NVL(apy.YMD.thang, 0)) < 84   THEN '3N_DEN_7N'
                    WHEN (NVL(apy.YMD.nam, 0) * 12
                          + NVL(apy.YMD.thang, 0)) < 120  THEN '7N_DEN_10N'
                    WHEN (NVL(apy.YMD.nam, 0) * 12
                          + NVL(apy.YMD.thang, 0)) < 180  THEN '10N_DEN_15N'
                    ELSE                                        '15N_DEN_30N'
                END
            END AS MUC_AN_PHAN_LOAI
        FROM an_phat_ymd apy
    ),
    metrics AS (
        SELECT
            COUNT(DISTINCT apc.PHAM_NHAN_ID)                                              AS tong_so_pham_nhan,
            COUNT(CASE WHEN apc.TCDK_MA NOT IN (10,11) AND dgt.GT_TEN = u'Nam'     THEN 1 END) AS khong_nhat_tri_nam,
            COUNT(CASE WHEN apc.TCDK_MA NOT IN (10,11) AND dgt.GT_TEN = u'N?'     THEN 1 END) AS khong_nhat_tri_nu,
            COUNT(CASE WHEN apc.TCDK_MA NOT IN (10,11)                             THEN 1 END) AS khong_nhat_tri_cong,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)     AND dgt.GT_TEN = u'Nam'     THEN 1 END) AS nhat_tri_nam,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)     AND dgt.GT_TEN = u'N?'     THEN 1 END) AS nhat_tri_nu,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)                                 THEN 1 END) AS nhat_tri_cong,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11) AND apc.MUC_AN_PHAN_LOAI = '3N_TRO_XUONG'  THEN 1 END) AS muc_an_3n_tro_xuong,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11) AND apc.MUC_AN_PHAN_LOAI = '3N_DEN_7N'     THEN 1 END) AS muc_an_3n_den_7n,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11) AND apc.MUC_AN_PHAN_LOAI = '7N_DEN_10N'    THEN 1 END) AS muc_an_7n_den_10n,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11) AND apc.MUC_AN_PHAN_LOAI = '10N_DEN_15N'   THEN 1 END) AS muc_an_10n_den_15n,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11) AND apc.MUC_AN_PHAN_LOAI = '15N_DEN_30N'   THEN 1 END) AS muc_an_15n_den_30n,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11) AND apc.MUC_AN_PHAN_LOAI = 'CHUNG_THAN'    THEN 1 END) AS muc_an_chung_than,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)
                        AND QLPN.FN_PHAN_LOAI_THOI_GIAN_CON_LAI(apc.THA_THOI_GIAN_CON_LAI) = '3N_TRO_XUONG'   THEN 1 END) AS con_lai_3n_tro_xuong,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)
                        AND QLPN.FN_PHAN_LOAI_THOI_GIAN_CON_LAI(apc.THA_THOI_GIAN_CON_LAI) = 'TREN_3N_DEN_5N' THEN 1 END) AS con_lai_3n_den_5n,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)
                        AND QLPN.FN_PHAN_LOAI_THOI_GIAN_CON_LAI(apc.THA_THOI_GIAN_CON_LAI) = 'TREN_5N_DEN_7N' THEN 1 END) AS con_lai_5n_den_7n,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)
                        AND QLPN.FN_PHAN_LOAI_THOI_GIAN_CON_LAI(apc.THA_THOI_GIAN_CON_LAI) = 'TREN_7N_DEN_10N' THEN 1 END) AS con_lai_7n_den_10n,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)
                        AND QLPN.FN_PHAN_LOAI_THOI_GIAN_CON_LAI(apc.THA_THOI_GIAN_CON_LAI) = 'TREN_10N'        THEN 1 END) AS con_lai_tren_10n,
            COUNT(CASE WHEN apc.TINH_TRANG_ID IN (10,11)
                        AND TRUNC(MONTHS_BETWEEN(
                                -- Neu co dot tha thi lay ngay do, khong thi SYSDATE
                                NVL((SELECT NGAY_XET FROM dot_ngay_xet), SYSDATE),
                                pll.LL_NGAY_SINH
                            ) / 12) < 18
                        THEN 1 END) AS nguoi_duoi_18_tuoi,
            NULL AS ghi_chu,
            NULL AS trai_tam_giam,
            NULL AS cqthahs_cap_huyen
        FROM an_phat_classified apc
        JOIN PN_LAI_LICHS pll ON pll.ID = apc.PHAM_NHAN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    )
    SELECT
        tong_so_pham_nhan,
        khong_nhat_tri_nam, khong_nhat_tri_nu, khong_nhat_tri_cong,
        nhat_tri_nam, nhat_tri_nu, nhat_tri_cong,
        muc_an_3n_tro_xuong, muc_an_3n_den_7n, muc_an_7n_den_10n,
        muc_an_10n_den_15n, muc_an_15n_den_30n, muc_an_chung_than,
        con_lai_3n_tro_xuong, con_lai_3n_den_5n, con_lai_5n_den_7n,
        con_lai_7n_den_10n, con_lai_tren_10n,
        nguoi_duoi_18_tuoi,
        ghi_chu,trai_tam_giam,cqthahs_cap_huyen
    FROM metrics;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            u'L?i báo cáo tha tù tr??c th?i h?n: ' || SQLERRM);
END SP_BAO_CAO_THA_TU_TRUOC_THOI_HAN;



/
--------------------------------------------------------
--  DDL for Procedure SP_BAO_CAO_THA_TU_TRUOC_THOI_HAN_TTG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_BAO_CAO_THA_TU_TRUOC_THOI_HAN_TTG" (
    p_pn_ids     IN NVARCHAR2 DEFAULT NULL,
    p_dot_tha_id IN NUMBER    DEFAULT NULL,
    p_ma_trai_giam IN varchar2 default null
)
IS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
	ID_LIST AS (
	    SELECT DISTINCT
	        TO_NUMBER(
	            REGEXP_SUBSTR(
	                REPLACE(REPLACE(TRIM(p_pn_ids), '[', ''), ']', ''),
	                '[0-9]+', 1, LEVEL
	            )
	        ) AS PN_ID
	    FROM DUAL
	    WHERE p_pn_ids IS NOT NULL
	      AND LENGTH(TRIM(p_pn_ids)) > 0
	    CONNECT BY LEVEL <= REGEXP_COUNT(
	                    REPLACE(REPLACE(TRIM(p_pn_ids), '[', ''), ']', ''),
	                    '[0-9]+'
	                )
	           AND PRIOR SYS_GUID() IS NOT NULL
	),
    dot_ngay_xet AS (
        SELECT TRUNC(dot.DTCDK_NGAY_XET) AS NGAY_XET
        FROM PN_DOT_THA_CO_DIEU_KIENS dot
        WHERE dot.ID = p_dot_tha_id
          AND NVL(dot.IS_DELETED, 0) = 0
    ),
    tha_filtered AS (
        SELECT
            t.PHAM_NHAN_ID,
            t.NGAY_XET,
            t.TINH_TRANG_ID,
            dmt.TCDK_MA,
            ROW_NUMBER() OVER (
                PARTITION BY t.PHAM_NHAN_ID
                ORDER BY t.NGAY_XET DESC
            ) AS rn
        FROM THA_CO_DIEU_KIENS t
        LEFT JOIN DM_THA_CO_DIEU_KIENS dmt
            ON t.TINH_TRANG_ID = dmt.ID
        WHERE NVL(t.IS_DELETED, 0) = 0
          AND (p_pn_ids IS NULL OR t.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
          AND (p_dot_tha_id IS NULL OR EXISTS (
                SELECT 1
                FROM PN_DOT_THA_CO_DIEU_KIENS dot
                WHERE TRUNC(dot.DTCDK_NGAY_XET) = TRUNC(t.NGAY_XET)
                  AND dot.ID = p_dot_tha_id
                  AND NVL(dot.IS_DELETED, 0) = 0
          ))
    ),
    latest_tha AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            ptha.THA_AN_PHAT,
            ptha.THA_THOI_GIAN_CON_LAI,
            ROW_NUMBER() OVER (
                PARTITION BY ptha.THA_PNLAI_LICH_ID
                ORDER BY NVL(ptha.THA_NGAY_BAN_AN,
                             TO_DATE('01-JAN-1900', 'DD-MON-YYYY')) DESC,
                         ptha.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN ptha
        INNER JOIN tha_filtered tf
            ON tf.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID AND tf.rn = 1
    ),
    an_phat_ymd AS (
        SELECT
            tf.PHAM_NHAN_ID,
            tf.TINH_TRANG_ID,
            lt.THA_AN_PHAT,
            lt.THA_THOI_GIAN_CON_LAI,
            QLPN.FN_PARSE_AN_PHAT_TO_YMD(lt.THA_AN_PHAT) AS YMD,
            tf.TCDK_MA
        FROM tha_filtered tf
        LEFT JOIN latest_tha lt
            ON lt.THA_PNLAI_LICH_ID = tf.PHAM_NHAN_ID AND lt.rn = 1
        WHERE tf.rn = 1
    ),
    an_phat_classified AS (
        SELECT
            apy.PHAM_NHAN_ID,
            apy.TINH_TRANG_ID,
            apy.THA_THOI_GIAN_CON_LAI,
            apy.TCDK_MA,
            CASE
                WHEN LOWER(apy.THA_AN_PHAT) LIKE '%chung th%n%'
                 AND LOWER(apy.THA_AN_PHAT) NOT LIKE '%gi%m%'
                THEN 'CHUNG_THAN'
                ELSE CASE
                    WHEN (NVL(apy.YMD.nam, 0) * 12 + NVL(apy.YMD.thang, 0)
                          + CASE WHEN NVL(apy.YMD.ngay, 0) > 0 THEN 1 ELSE 0 END
                         ) < 36    THEN '3N_TRO_XUONG'
                    WHEN (NVL(apy.YMD.nam, 0) * 12
                          + NVL(apy.YMD.thang, 0)) < 84   THEN '3N_DEN_7N'
                    WHEN (NVL(apy.YMD.nam, 0) * 12
                          + NVL(apy.YMD.thang, 0)) < 120  THEN '7N_DEN_10N'
                    WHEN (NVL(apy.YMD.nam, 0) * 12
                          + NVL(apy.YMD.thang, 0)) < 180  THEN '10N_DEN_15N'
                    ELSE                                        '15N_DEN_30N'
                END
            END AS MUC_AN_PHAN_LOAI
        FROM an_phat_ymd apy
    ),
    metrics AS (
        SELECT
            COUNT(DISTINCT apc.PHAM_NHAN_ID)                                              AS tong_so_pham_nhan,
            COUNT(CASE WHEN apc.TCDK_MA NOT IN (10,11) AND dgt.GT_TEN = u'Nam'     THEN 1 END) AS khong_nhat_tri_nam,
            COUNT(CASE WHEN apc.TCDK_MA NOT IN (10,11) AND dgt.GT_TEN = u'N?'     THEN 1 END) AS khong_nhat_tri_nu,
            COUNT(CASE WHEN apc.TCDK_MA NOT IN (10,11)                             THEN 1 END) AS khong_nhat_tri_cong,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)     AND dgt.GT_TEN = u'Nam'     THEN 1 END) AS nhat_tri_nam,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)     AND dgt.GT_TEN = u'N?'     THEN 1 END) AS nhat_tri_nu,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)                                 THEN 1 END) AS nhat_tri_cong,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11) AND apc.MUC_AN_PHAN_LOAI = '3N_TRO_XUONG'  THEN 1 END) AS muc_an_3n_tro_xuong,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11) AND apc.MUC_AN_PHAN_LOAI = '3N_DEN_7N'     THEN 1 END) AS muc_an_3n_den_7n,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11) AND apc.MUC_AN_PHAN_LOAI = '7N_DEN_10N'    THEN 1 END) AS muc_an_7n_den_10n,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11) AND apc.MUC_AN_PHAN_LOAI = '10N_DEN_15N'   THEN 1 END) AS muc_an_10n_den_15n,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11) AND apc.MUC_AN_PHAN_LOAI = '15N_DEN_30N'   THEN 1 END) AS muc_an_15n_den_30n,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11) AND apc.MUC_AN_PHAN_LOAI = 'CHUNG_THAN'    THEN 1 END) AS muc_an_chung_than,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)
                        AND QLPN.FN_PHAN_LOAI_THOI_GIAN_CON_LAI(apc.THA_THOI_GIAN_CON_LAI) = '3N_TRO_XUONG'   THEN 1 END) AS con_lai_3n_tro_xuong,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)
                        AND QLPN.FN_PHAN_LOAI_THOI_GIAN_CON_LAI(apc.THA_THOI_GIAN_CON_LAI) = 'TREN_3N_DEN_5N' THEN 1 END) AS con_lai_3n_den_5n,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)
                        AND QLPN.FN_PHAN_LOAI_THOI_GIAN_CON_LAI(apc.THA_THOI_GIAN_CON_LAI) = 'TREN_5N_DEN_7N' THEN 1 END) AS con_lai_5n_den_7n,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)
                        AND QLPN.FN_PHAN_LOAI_THOI_GIAN_CON_LAI(apc.THA_THOI_GIAN_CON_LAI) = 'TREN_7N_DEN_10N' THEN 1 END) AS con_lai_7n_den_10n,
            COUNT(CASE WHEN apc.TCDK_MA IN (10,11)
                        AND QLPN.FN_PHAN_LOAI_THOI_GIAN_CON_LAI(apc.THA_THOI_GIAN_CON_LAI) = 'TREN_10N'        THEN 1 END) AS con_lai_tren_10n,
            COUNT(CASE WHEN apc.TINH_TRANG_ID IN (10,11)
                        AND TRUNC(MONTHS_BETWEEN(
                                -- Neu co dot tha thi lay ngay do, khong thi SYSDATE
                                NVL((SELECT NGAY_XET FROM dot_ngay_xet), SYSDATE),
                                pll.LL_NGAY_SINH
                            ) / 12) < 18
                        THEN 1 END) AS nguoi_duoi_18_tuoi,
            NULL AS trai_tam_giam,
            NULL AS cqthahs_cap_huyen
        FROM an_phat_classified apc
        JOIN PN_LAI_LICHS pll ON pll.ID = apc.PHAM_NHAN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    )
    SELECT
        tong_so_pham_nhan,
        khong_nhat_tri_nam, khong_nhat_tri_nu, khong_nhat_tri_cong,
        nhat_tri_nam, nhat_tri_nu, nhat_tri_cong,
        muc_an_3n_tro_xuong, muc_an_3n_den_7n, muc_an_7n_den_10n,
        muc_an_10n_den_15n, muc_an_15n_den_30n, muc_an_chung_than,
        con_lai_3n_tro_xuong, con_lai_3n_den_5n, con_lai_5n_den_7n,
        con_lai_7n_den_10n, con_lai_tren_10n,
        nguoi_duoi_18_tuoi
    FROM metrics;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            u'L?i báo cáo tha tù tr??c th?i h?n: ' || SQLERRM);
END SP_BAO_CAO_THA_TU_TRUOC_THOI_HAN_TTG;



