--  DDL for Procedure SP_BC_TIEN_XEP_LOAI_PN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_BC_TIEN_XEP_LOAI_PN" ( p_pham_nhan_id IN NUMBER ) AS C1 SYS_REFCURSOR; BEGIN OPEN C1 FOR WITH yr AS ( SELECT DISTINCT nam FROM ( SELECT XEP_LOAI_NAM AS nam FROM XEP_LOAIS WHERE PHAM_NHAN_ID = p_pham_nhan_id AND NVL(IS_DELETED, 0) = 0 UNION SELECT NAM FROM TIEN_LAO_DONG_SAN_XUATS WHERE PHAM_NHAN_ID = p_pham_nhan_id AND NVL(IS_DELETED, 0) = 0 ) ), xl AS ( SELECT x.XEP_LOAI_NAM AS nam, d1.XL_TEN AS q1_xep_loai, d2.XL_TEN AS q2_xep_loai, d3.XL_TEN AS q3_xep_loai, d4.XL_TEN AS q4_xep_loai FROM XEP_LOAIS x LEFT JOIN DM_XEP_LOAIES d1 ON d1.ID = x.XEP_LOAI_QUY_I AND NVL(d1.IS_DELETED, 0) = 0 LEFT JOIN DM_XEP_LOAIES d2 ON d2.ID = x.XEP_LOAI_QUY_II AND NVL(d2.IS_DELETED, 0) = 0 LEFT JOIN DM_XEP_LOAIES d3 ON d3.ID = x.XEP_LOAI_QUY_III AND NVL(d3.IS_DELETED, 0) = 0 LEFT JOIN DM_XEP_LOAIES d4 ON d4.ID = x.XEP_LOAI_QUY_IV AND NVL(d4.IS_DELETED, 0) = 0 WHERE x.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(x.IS_DELETED, 0) = 0 ), tien AS ( SELECT NAM, NVL(TIEN_Q1, 0) AS q1_tien, NVL(TIEN_Q2, 0) AS q2_tien, NVL(TIEN_Q3, 0) AS q3_tien, NVL(TIEN_Q4, 0) AS q4_tien, NVL(TIEN_Q1, 0) + NVL(TIEN_Q2, 0) + NVL(TIEN_Q3, 0) + NVL(TIEN_Q4, 0) + NVL(TIEN_KHAC, 0) AS tong_tien_nam FROM TIEN_LAO_DONG_SAN_XUATS WHERE PHAM_NHAN_ID = p_pham_nhan_id AND NVL(IS_DELETED, 0) = 0 ), yearly AS ( SELECT y.nam, x.q1_xep_loai, NVL(t.q1_tien, 0) AS q1_tien, x.q2_xep_loai, NVL(t.q2_tien, 0) AS q2_tien, x.q3_xep_loai, NVL(t.q3_tien, 0) AS q3_tien, x.q4_xep_loai, NVL(t.q4_tien, 0) AS q4_tien, NVL(t.tong_tien_nam, 0) AS tong_tien_nam FROM yr y LEFT JOIN xl x ON x.nam = y.nam LEFT JOIN tien t ON t.NAM = y.nam ), total AS ( SELECT SUM(tong_tien_nam) AS tong_tien_nam FROM yearly ) SELECT nam, q1_xep_loai, q1_tien, q2_xep_loai, q2_tien, q3_xep_loai, q3_tien, q4_xep_loai, q4_tien, tong_tien_nam FROM ( SELECT TO_CHAR(yearly.nam) AS nam, q1_xep_loai, q1_tien, q2_xep_loai, q2_tien, q3_xep_loai, q3_tien, q4_xep_loai, q4_tien, tong_tien_nam FROM yearly UNION ALL SELECT 'T?ng c?ng', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, tong_tien_nam FROM total ) u ORDER BY CASE WHEN nam = 'T?ng c?ng' THEN 1 ELSE 0 END, nam; DBMS_SQL.RETURN_RESULT(C1); END SP_BC_TIEN_XEP_LOAI_PN;









