--------------------------------------------------------
--  DDL for Procedure SP_CALC_TINH_TRANG_PHAM_NHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_CALC_TINH_TRANG_PHAM_NHAN" (
    p_pham_nhan_id   IN  NUMBER DEFAULT NULL,
    p_updated_count  OUT NUMBER
) AS
    -- TTPN_MA (DmTinhTrangPhamNhan )
    v_ttpn_dang_chap_hanh_an         CONSTANT NVARCHAR2(10) := '111';
    v_ttpn_giam_rieng                CONSTANT NVARCHAR2(10) := '112';
    v_ttpn_bat_buoc_chua_benh        CONSTANT NVARCHAR2(10) := '113';
    v_ttpn_tron_trai                 CONSTANT NVARCHAR2(10) := '131';
    v_ttpn_tron_trai_chet            CONSTANT NVARCHAR2(10) := '132';
    v_ttpn_tron_trai_truy_na         CONSTANT NVARCHAR2(10) := '133';
    v_ttpn_trich_xuat                CONSTANT NVARCHAR2(10) := '141';
    v_ttpn_trich_xuat_gia_han        CONSTANT NVARCHAR2(10) := '142';
    v_ttpn_trich_xuat_chuyen_trai    CONSTANT NVARCHAR2(10) := '143';
    v_ttpn_trich_xuat_chet           CONSTANT NVARCHAR2(10) := '144';
    v_ttpn_trich_xuat_tron           CONSTANT NVARCHAR2(10) := '145';
    v_ttpn_trich_xuat_giam_tha       CONSTANT NVARCHAR2(10) := '147';
    v_ttpn_trich_xuat_dac_xa         CONSTANT NVARCHAR2(10) := '148';
    v_ttpn_trich_xuat_xu_toi_moi     CONSTANT NVARCHAR2(10) := '149';
    v_ttpn_trich_xuat_huy_an         CONSTANT NVARCHAR2(10) := '150';
    v_ttpn_tam_dinh_chi              CONSTANT NVARCHAR2(10) := '151';
    v_ttpn_tam_dinh_chi_gia_han      CONSTANT NVARCHAR2(10) := '152';
    v_ttpn_tam_dinh_chi_chet         CONSTANT NVARCHAR2(10) := '153';
    v_ttpn_tam_dinh_chi_tron         CONSTANT NVARCHAR2(10) := '154';
    v_ttpn_tam_dinh_chi_dac_xa       CONSTANT NVARCHAR2(10) := '155';
    v_ttpn_tam_dinh_chi_chuyen_trai  CONSTANT NVARCHAR2(10) := '156';
    v_ttpn_tam_dinh_chi_pham_toi_moi CONSTANT NVARCHAR2(10) := '158';
    v_ttpn_tam_dinh_chi_qua_han      CONSTANT NVARCHAR2(10) := '157';
    v_ttpn_tam_dinh_chi_duoc_mien    CONSTANT NVARCHAR2(10) := '159';
    v_ttpn_huy_an                    CONSTANT NVARCHAR2(10) := '181';
    v_ttpn_hoan_thi_hanh_an          CONSTANT NVARCHAR2(10) := '191';
    v_ttpn_giam_het_an               CONSTANT NVARCHAR2(10) := '122';
    v_ttpn_dac_xa                    CONSTANT NVARCHAR2(10) := '123';
    v_ttpn_mien_hinh_phat            CONSTANT NVARCHAR2(10) := '124';
    v_ttpn_tha_truoc_thoi_han        CONSTANT NVARCHAR2(10) := '126';

	--các tr?ng thái khác
	v_ttpn_chap_hanh_xong			 CONSTANT NVARCHAR2(10) := '121';
	v_ttpn_chuyen_giao			 	 CONSTANT NVARCHAR2(10) := '127';
	v_ttpn_chuyen_trai_khac			 CONSTANT NVARCHAR2(10) := '161';

BEGIN

    -- Ngu?n dùng chung v?i SP_REFRESH_PN_TINH_TRANG_NGAY_CACHE — xem
    -- docs/reports/QLPN/Dashboard/FN_TINH_TRANG_PN_TAI_NGAY.sql. Toàn b? logic ?u tiên xác ??nh
    -- tình tr?ng (tr??c ?ây t? vi?t riêng ? ?ây b?ng calc_ma/calc, khác v?i SP_REFRESH — vi ph?m
    -- yêu c?u m?c 3 tài li?u quy ??nh) nay dùng chung 1 ngu?n canonical. Whitelist cur_ttpn_ma
    -- bên d??i là quy t?c RIÊNG c?a SP này (ch? ??ng vào PN có tình tr?ng ?ã bi?t) — không thu?c
    -- ph?m vi h?p nh?t logic xác ??nh tình tr?ng nên gi? nguyên.
    MERGE INTO PN_LAI_LICHS pn
    USING (
        WITH targets AS (
            SELECT t.ID,
                   t.LL_TINH_TRANG_ID AS cur_tinh_trang_id
              FROM PN_LAI_LICHS t
             WHERE t.IS_DELETED = 0
               AND NVL(t.LL_LA_BAN_DONG_BANG, 0) = 0
               AND (p_pham_nhan_id IS NULL OR t.ID = p_pham_nhan_id)
        ),
        calc AS (
            SELECT t.ID,
                   f.TTPN_MA AS new_ttpn_ma,
                   nw.ID AS new_tinh_trang_id,
                   cr.TTPN_MA AS cur_ttpn_ma,
                   t.cur_tinh_trang_id
              FROM targets t
              JOIN TABLE(QLPN.FN_TINH_TRANG_PN_TAI_NGAY(TRUNC(SYSDATE), p_pham_nhan_id)) f
                ON f.PN_ID = t.ID
              -- M?t TTPN_MA có nhi?u dòng (k? c? b?n IS_DELETED) làm MERGE ném ORA-30926.
              JOIN (
                    SELECT TTPN_MA, ID
                      FROM (
                            SELECT d.TTPN_MA,
                                   d.ID,
                                   ROW_NUMBER() OVER (
                                       PARTITION BY d.TTPN_MA
                                       ORDER BY CASE WHEN NVL(d.IS_DELETED, 0) = 0 THEN 0 ELSE 1 END,
                                                d.ID
                                   ) AS rn
                              FROM DM_TINH_TRANG_PHAM_NHANS d
                             WHERE d.TTPN_MA IS NOT NULL
                      ) ranked
                     WHERE ranked.rn = 1
              ) nw ON nw.TTPN_MA = f.TTPN_MA
              LEFT JOIN DM_TINH_TRANG_PHAM_NHANS cr ON cr.ID = t.cur_tinh_trang_id
        )

        SELECT ID,
               MAX(new_tinh_trang_id) AS new_tinh_trang_id,
               MAX(cur_tinh_trang_id) AS cur_tinh_trang_id
          FROM calc
         WHERE NVL(cur_tinh_trang_id, -1) <> NVL(new_tinh_trang_id, -1) -- ch? c?p nh?t các ph?m nhân có tình tr?ng m?i khác v?i tình tr?ng hi?n t?i

         --và ch? c?p nh?t ph?m nhân có tình tr?ng ?ã ???c define trong SP (tránh c?p nh?t các tình tr?ng ??c bi?t)
         AND cur_ttpn_ma IN (
	        v_ttpn_dang_chap_hanh_an,
			v_ttpn_giam_rieng,
			v_ttpn_bat_buoc_chua_benh,
			v_ttpn_tron_trai,
			v_ttpn_tron_trai_chet,
			v_ttpn_tron_trai_truy_na,
			v_ttpn_trich_xuat,
			v_ttpn_trich_xuat_gia_han,
			v_ttpn_trich_xuat_chuyen_trai,
			v_ttpn_trich_xuat_chet,
			v_ttpn_trich_xuat_tron,
			v_ttpn_trich_xuat_giam_tha,
			v_ttpn_trich_xuat_dac_xa,
			v_ttpn_trich_xuat_xu_toi_moi,
			v_ttpn_trich_xuat_huy_an,
			v_ttpn_tam_dinh_chi,
			v_ttpn_tam_dinh_chi_gia_han,
			v_ttpn_tam_dinh_chi_chet,
			v_ttpn_tam_dinh_chi_tron,
			v_ttpn_tam_dinh_chi_dac_xa,
			v_ttpn_tam_dinh_chi_chuyen_trai,
			v_ttpn_tam_dinh_chi_pham_toi_moi,
			v_ttpn_tam_dinh_chi_qua_han,
			v_ttpn_tam_dinh_chi_duoc_mien,
			v_ttpn_huy_an,
			v_ttpn_hoan_thi_hanh_an,
			v_ttpn_giam_het_an,
			v_ttpn_dac_xa,
			v_ttpn_mien_hinh_phat,
			v_ttpn_tha_truoc_thoi_han,

			v_ttpn_chap_hanh_xong,
			v_ttpn_chuyen_giao,
			v_ttpn_chuyen_trai_khac
         )
         GROUP BY ID
    ) src
       ON (pn.ID = src.ID)

     WHEN MATCHED THEN
         UPDATE SET pn.LL_TINH_TRANG_ID = src.new_tinh_trang_id,
     				pn.LAST_MODIFICATION_TIME = SYSTIMESTAMP;

    p_updated_count := SQL%ROWCOUNT;

    COMMIT;
    -- begin
    --      QLPN.SP_CALC_TINH_TRANG_PHAM_NHAN(NULL, :cnt); 

    -- end;

END;


/
--------------------------------------------------------
--  DDL for Procedure SP_CHOT_SO_PHAM_NHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_CHOT_SO_PHAM_NHAN" AS
    v_thang      NUMBER    := EXTRACT(MONTH FROM SYSDATE);
    v_nam        NUMBER    := EXTRACT(YEAR  FROM SYSDATE);
    v_ngay_chot  DATE;
    v_so_nam     NUMBER;
    v_so_nu      NUMBER;
    v_tong_so    NUMBER;
BEGIN
    -- Ngày ch?t = ngày 14 c?a tháng/n?m ?ang ch?y
    v_ngay_chot := TO_DATE(v_nam || '-' || LPAD(v_thang, 2, '0') || '-14', 'YYYY-MM-DD');

    SELECT
        SUM(CASE WHEN gt.GT_MA = '1' THEN 1 ELSE 0 END),
        SUM(CASE WHEN gt.GT_MA = '2' THEN 1 ELSE 0 END),
        COUNT(*)
    INTO v_so_nam, v_so_nu, v_tong_so
    FROM PN_LAI_LICHS             ll
    JOIN DM_TINH_TRANG_PHAM_NHANS tt ON tt.ID = ll.LL_TINH_TRANG_ID
    JOIN DM_GIOI_TINHS             gt ON gt.ID = ll.LL_DM_GIOI_TINH_ID
    WHERE ll.IS_DELETED = 0
      AND tt.IS_DELETED = 0
      AND tt.TTPN_MA IN ('111', '112', '113', '114')
      AND EXISTS (
          SELECT 1
          FROM PN_THI_HANH_AN tha
          WHERE tha.THA_PNLAI_LICH_ID = ll.ID
            AND tha.IS_DELETED        = 0
            AND TRUNC(tha.THA_NGAY_DEN_TRAI) <= v_ngay_chot
      );

    MERGE INTO CHOT_SO_PHAM_NHAN c
    USING (SELECT v_thang AS THANG, v_nam AS NAM FROM DUAL) src
        ON (c.THANG = src.THANG AND c.NAM = src.NAM)
    WHEN MATCHED THEN
        UPDATE SET
            SO_NAM        = v_so_nam,
            SO_NU         = v_so_nu,
            TONG_SO       = v_tong_so,
            CREATION_TIME = SYSTIMESTAMP
    WHEN NOT MATCHED THEN
        INSERT (THANG, NAM, SO_NAM, SO_NU, TONG_SO)
        VALUES (v_thang, v_nam, v_so_nam, v_so_nu, v_tong_so);

    COMMIT;
END SP_CHOT_SO_PHAM_NHAN;





/
--------------------------------------------------------
--  DDL for Procedure SP_DAC_XA_DANH_SACH_DU_DIEU_KIEN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_DAC_XA_DANH_SACH_DU_DIEU_KIEN" (
    p_dx_dieu_kiem_dac_xa_id IN  NUMBER,
    p_ma_trai_giam           IN  NVARCHAR2 DEFAULT NULL,
    p_thong_bao              OUT NVARCHAR2
) AS
    -- Ngày tham chi?u D_x cho tính T?CHAPT, TCHAPTCL: ?u tiên cu?i kho?ng, r?i ??u kho?ng, không truy?n thì SYSDATE
    v_ngay_xet         TIMESTAMP;
    v_pn_dot_dac_xa_id NUMBER;
    v_so_pham_nhan     NUMBER;
    v_ids              QLPN.NUM_TBL;
    v_key              DATE;
    v_trai_giam_id     NUMBER;

BEGIN
    -- L?y ??t ??c xá và ngày xét t??ng ?ng v?i c?u hình ?i?u ki?n (DX_DIEU_KIEN_DAC_XAS)
    BEGIN
        SELECT
            dkx.pn_dot_dac_xa_id,
            CAST(NVL(dot.ddx_ngay_xet, SYSDATE) AS TIMESTAMP)
        INTO v_pn_dot_dac_xa_id,
             v_ngay_xet
        FROM DX_DIEU_KIEN_DAC_XAS dkx
        LEFT JOIN PN_DOT_DAC_XAS dot
               ON dot.id = dkx.pn_dot_dac_xa_id
              AND NVL(dot.is_deleted, 0) = 0
        WHERE dkx.id = p_dx_dieu_kiem_dac_xa_id
          AND NVL(dkx.is_deleted, 0) = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_pn_dot_dac_xa_id := NULL;
            v_ngay_xet := SYSTIMESTAMP;
    END;

    IF v_pn_dot_dac_xa_id IS NULL THEN
        p_thong_bao := u'Kh\00f4ng t\00ecm th\1ea5y \0111i\1ec1u ki\1ec7n \0111\1eb7c x\00e1';
        RETURN;
    END IF;

    -- Resolve tr?i giam ID m?t l?n (tránh join l?p l?i)
    IF p_ma_trai_giam IS NOT NULL THEN
        BEGIN
            SELECT id INTO v_trai_giam_id
            FROM "DM_TRAI_GIAMS"
            WHERE "TG_MA" = p_ma_trai_giam AND NVL("IS_DELETED", 0) = 0;
        EXCEPTION WHEN NO_DATA_FOUND THEN v_trai_giam_id := NULL;
        END;
    END IF;

    -- Scope DELETE theo tr?i giam n?u có filter, tránh xóa d? li?u tr?i khác
    IF v_trai_giam_id IS NULL THEN
        DELETE FROM DX_DU_DIEU_KIEN_DAC_XAS WHERE pn_dot_dac_xa_id = v_pn_dot_dac_xa_id;
        DELETE FROM DX_KHONG_DU_DIEU_KIEN_DAC_XAS WHERE pn_dot_dac_xa_id = v_pn_dot_dac_xa_id;
    ELSE
        DELETE FROM DX_DU_DIEU_KIEN_DAC_XAS
        WHERE pn_dot_dac_xa_id = v_pn_dot_dac_xa_id
          AND pn_lai_lich_id IN (
              SELECT "ID" FROM "PN_LAI_LICHS"
              WHERE "LL_TRAI_GIAM_ID" = v_trai_giam_id AND NVL("IS_DELETED", 0) = 0
          );
        DELETE FROM DX_KHONG_DU_DIEU_KIEN_DAC_XAS
        WHERE pn_dot_dac_xa_id = v_pn_dot_dac_xa_id
          AND pn_lai_lich_id IN (
              SELECT "ID" FROM "PN_LAI_LICHS"
              WHERE "LL_TRAI_GIAM_ID" = v_trai_giam_id AND NVL("IS_DELETED", 0) = 0
          );
    END IF;
    v_key := TRUNC(CAST(v_ngay_xet AS DATE));

    -- ===== B0: gom candidate ids (khong PKG, khong phu thuoc dk) =====
    SELECT DISTINCT tha."THA_PNLAI_LICH_ID" BULK COLLECT INTO v_ids
    FROM "PN_THI_HANH_AN" tha
    INNER JOIN "PN_LAI_LICHS" ll ON ll."ID" = tha."THA_PNLAI_LICH_ID" AND NVL(ll."IS_DELETED",0)=0
    INNER JOIN "DM_TINH_TRANG_PHAM_NHANS" tt ON tt."ID" = ll."LL_TINH_TRANG_ID"
         AND NVL(tt."IS_DELETED",0)=0 AND tt."TTPN_MA" IN ('111','112','113','114','141','142')
    LEFT JOIN (
       SELECT DISTINCT tx."PHAM_NHAN_ID" pn_id FROM "TRICH_XUATS" tx
       INNER JOIN "DM_LY_DO_TRICH_XUATS" dm ON tx."TX_LY_DO_ID"=dm."ID" AND NVL(dm."IS_DELETED",0)=0
       WHERE NVL(tx."IS_DELETED",0)=0 AND tx."TX_NGAY_TRA" IS NULL AND dm."LDTX_MA" IN ('50','51','93')
    ) txc ON txc.pn_id = ll."ID"
    WHERE NVL(tha."IS_DELETED",0)=0 AND tha."THA_PNLAI_LICH_ID" IS NOT NULL
      AND (v_trai_giam_id IS NULL OR ll."LL_TRAI_GIAM_ID" = v_trai_giam_id)
      AND ( tt."TTPN_MA" IN ('111','112','113','114')
            OR (tt."TTPN_MA" IN ('141','142') AND txc.pn_id IS NOT NULL) );

    -- ===== B1: populate memo core (1 lan/PN) =====
    -- Scope DELETE nhu SP_SNAPSHOT_TCDK_BATCH: refresh mot trai chi xoa memo cua PN duoc nap lai,
    -- tranh xoa memo trai khac (con dung cho luong hien thi) va xoa cheo khi 2 phien chay dong thoi
    IF v_trai_giam_id IS NULL THEN
        DELETE FROM DX_CORE_MEMO WHERE ngay_xet_key = v_key;
    ELSIF v_ids IS NOT NULL AND v_ids.COUNT > 0 THEN
        DELETE FROM DX_CORE_MEMO m
         WHERE m.ngay_xet_key = v_key
           AND m.pn_id IN (SELECT COLUMN_VALUE FROM TABLE(v_ids));
    END IF;
    PKG_TINH_AN.SP_POPULATE_CORE_MEMO(v_ids, CAST(v_ngay_xet AS DATE));

    -- ===== B2: phan loai (WITH 1 lan, PKG hit memo) -> GTT =====
    INSERT INTO GTT_DX_SNAP (pn_id, is_du, li_do)
    SELECT pn_lai_lich_id, is_du, li_do_khong_thoa_man FROM (
    WITH
    ngay_xet_ctx AS (
        SELECT CAST(v_ngay_xet AS DATE) AS ngay_xet FROM dual
    ),
    -- ?i?u ki?n ??t ??c xá (m?t dòng: tham s? c?u hình cho toàn b? WITH)
    dk AS (
        SELECT
            dkx.ID,
            dkx.pn_dot_dac_xa_id,
            dkx."DKDX_SO_TIEN_AN"      AS so_tien_an_loai_tru,
            dkx."DKDX_DA_DUOC_DAC_XA" AS loai_tru_da_dac_xa,
            dkx."DKDX_SU_DUNG_MA_TUY" AS loai_tru_ma_tuy,
            dkx."DKDX_DOI_TUONG_HIV_AIDS",
            dkx."DKDX_TINH_CHAT_CON_DO",
            dkx."DKDX_CHU_MUU_CAM_DAU",
            dkx."DKDX_TOI_DANH"       AS toi_danh_loai_tru_str,
            dkx."DKDX_DIEU_KIEN_DAC_BIET" AS dieu_kien_dac_biet_str
        FROM "DX_DIEU_KIEN_DAC_XAS" dkx
        WHERE dkx."ID" = p_dx_dieu_kiem_dac_xa_id
          AND NVL(dkx."IS_DELETED", 0) = 0
    ),
    -- Danh sách t?i danh lo?i tr? t? DKDX_TOI_DANH (chu?i [id1,id2,...])
    toi_loai_tru AS (
        SELECT DISTINCT TO_NUMBER(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL))) AS toi_danh_id
        FROM (
            SELECT REPLACE(REPLACE(TRIM(NVL(dk.toi_danh_loai_tru_str, '[]')), '[', ''), ']', '') AS csv
            FROM dk
            WHERE dk.toi_danh_loai_tru_str IS NOT NULL
        ) r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.csv, ',') + 1
          AND PRIOR r.csv = r.csv
          AND PRIOR SYS_GUID() IS NOT NULL
          AND TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)) IS NOT NULL
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)), '^\d+$')
    ),
    -- Ch? xét ph?m nhân có tình tr?ng (DM_TINH_TRANG_PHAM_NHANS.ID = LL_TINH_TRANG_ID) thu?c các mã TTPN_MA sau
    ttpn_duoc_xet AS (
        SELECT t."ID" AS tinh_trang_id, t."TTPN_MA"
        FROM "DM_TINH_TRANG_PHAM_NHANS" t
        WHERE NVL(t."IS_DELETED", 0) = 0
          AND t."TTPN_MA" IN ('111', '112', '113', '114', '141', '142')
    ),
    -- Trích xu?t ch?a tr? (141/142): gom m?t l?n, tránh EXISTS l?p trên candidates
    trich_xuat_chua_tra AS (
        SELECT DISTINCT tx."PHAM_NHAN_ID" AS pn_id
        FROM "TRICH_XUATS" tx
        INNER JOIN "DM_LY_DO_TRICH_XUATS" dm_ldtx
                ON tx."TX_LY_DO_ID" = dm_ldtx."ID"
               AND NVL(dm_ldtx."IS_DELETED", 0) = 0
        WHERE NVL(tx."IS_DELETED", 0) = 0
          AND tx."TX_NGAY_TRA" IS NULL
          AND dm_ldtx."LDTX_MA" IN ('50', '51', '93')
    ),
    -- ?ng viên ban ??u: PN có b?n ghi thi hành án còn hi?u l?c và tình tr?ng thu?c ttpn_duoc_xet
    candidates AS (
        SELECT DISTINCT tha."THA_PNLAI_LICH_ID" AS pn_id
        FROM "PN_THI_HANH_AN" tha
        INNER JOIN "PN_LAI_LICHS" ll ON ll."ID" = tha."THA_PNLAI_LICH_ID" AND NVL(ll."IS_DELETED", 0) = 0
        INNER JOIN ttpn_duoc_xet tt ON tt.tinh_trang_id = ll."LL_TINH_TRANG_ID"
        LEFT JOIN trich_xuat_chua_tra tx ON tx.pn_id = ll."ID"
        WHERE NVL(tha."IS_DELETED", 0) = 0
          AND tha."THA_PNLAI_LICH_ID" IS NOT NULL
          AND (v_trai_giam_id IS NULL OR ll."LL_TRAI_GIAM_ID" = v_trai_giam_id)
          AND (
              tt."TTPN_MA" IN ('111', '112', '113', '114')
              OR (tt."TTPN_MA" IN ('141', '142') AND tx.pn_id IS NOT NULL)
          )
    ),
    -- PN ?ã t?ng ???c ??c xá (dùng ?? lo?i n?u c?u hình yêu c?u)
    pn_da_tung_duoc_dac_xa AS (
        SELECT DISTINCT pdx."PNLAI_LICH_ID" AS pn_id
        FROM "PN_DAC_XAS" pdx
        INNER JOIN candidates c ON c.pn_id = pdx."PNLAI_LICH_ID"
        WHERE NVL(pdx."IS_DELETED", 0) = 0
    ),
    -- Tách danh sách t?i danh t? THA_TOI_DANH (dùng chung cho các b??c c?n theo dõi theo t?i danh)
    -- Quy ??c d? li?u: THA_TOI_DANH luôn là list id d?ng [id1,id2,...].
    tha_toi_src AS (
        SELECT
            tha."THA_PNLAI_LICH_ID" AS pn_id,
            tha."ID" AS tha_id,
            REPLACE(REPLACE(REPLACE(NVL(tha."THA_TOI_DANH", '[]'), '[', ''), ']', ''), ' ', '') AS csv
        FROM "PN_THI_HANH_AN" tha
        INNER JOIN candidates c ON c.pn_id = tha."THA_PNLAI_LICH_ID"
        WHERE NVL(tha."IS_DELETED", 0) = 0
          AND tha."THA_TOI_DANH" IS NOT NULL
    ),
    tha_toi_ids AS (
        SELECT
            s.pn_id,
            s.tha_id,
            TO_NUMBER(TRIM(REGEXP_SUBSTR(s.csv, '[^,]+', 1, LEVEL))) AS toi_danh_id
        FROM tha_toi_src s
        CONNECT BY LEVEL <= REGEXP_COUNT(s.csv, ',') + 1
          AND PRIOR SYS_GUID() IS NOT NULL
          AND PRIOR s.tha_id = s.tha_id
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(s.csv, '[^,]+', 1, LEVEL)), '^\d+$')
    ),
    -- PN có t?i danh thu?c danh sách lo?i tr?
    pn_co_toi_loai_tru AS (
        SELECT DISTINCT ti.pn_id
        FROM tha_toi_ids ti
        JOIN toi_loai_tru t ON t.toi_danh_id = ti.toi_danh_id
    ),
    -- Ghi chú ??c bi?t: l?y danh sách id t? THA_GHI_CHU_DAC_BIET (m?ng id)
    pn_ghi_chu_raw AS (
        SELECT
            tha."THA_PNLAI_LICH_ID" AS pn_id,
            REPLACE(REPLACE(TRIM(NVL(tha."THA_GHI_CHU_DAC_BIET", '[]')), '[', ''), ']', '') AS csv
        FROM "PN_THI_HANH_AN" tha
        INNER JOIN candidates c ON c.pn_id = tha."THA_PNLAI_LICH_ID"
        WHERE NVL(tha."IS_DELETED", 0) = 0
          AND tha."THA_GHI_CHU_DAC_BIET" IS NOT NULL
    ),
    -- Tách chu?i id ghi chú ??c bi?t thành t?ng dòng (pn_id, ghi_chu_id)
    pn_ghi_chu_ids AS (
        SELECT
            r.pn_id,
            TO_NUMBER(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL))) AS ghi_chu_id
        FROM pn_ghi_chu_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.csv, ',') + 1
          AND PRIOR r.csv   = r.csv
          AND PRIOR r.pn_id = r.pn_id
          AND PRIOR SYS_GUID() IS NOT NULL
          AND TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)) IS NOT NULL
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)), '^\d+$')
    ),
    -- PN có trong b?ng PN_NGHIEN_MT (nghi?n ma túy) ? has_ma_tuy = 1 (?u tiên ki?m tra tr??c)
    pn_co_nghien_mt AS (
        SELECT DISTINCT nmt."NMT_PN_LAI_LICH_ID" AS pn_id
        FROM "PN_NGHIEN_MT" nmt
        INNER JOIN candidates c ON c.pn_id = nmt."NMT_PN_LAI_LICH_ID"
        WHERE NVL(nmt."IS_DELETED", 0) = 0
    ),
    -- G?n c? ma túy / HIV / côn ?? / ch? m?u cho t?ng PN: ma túy = PN_NGHIEN_MT HO?C ghi chú DM_GHI_CHU_DAC_BIETS
    pn_ghi_chu_dac_biet AS (
        SELECT
            ids.pn_id,
            MAX(CASE WHEN UPPER(NVL(dm."GCDB_TEN", '')) LIKE '%MA TÚY%' THEN 1 ELSE 0 END) AS has_ma_tuy_gch,
            MAX(CASE WHEN UPPER(NVL(dm."GCDB_TEN", '')) LIKE '%HIV%' THEN 1 ELSE 0 END)    AS has_hiv,
            MAX(CASE WHEN UPPER(NVL(dm."GCDB_TEN", '')) LIKE '%CÔN ??%' THEN 1 ELSE 0 END) AS has_con_do,
            MAX(CASE
                    WHEN UPPER(NVL(dm."GCDB_TEN", '')) LIKE '%CH? M?U%' OR UPPER(NVL(dm."GCDB_TEN", '')) LIKE '%C?M ??U%'
                    THEN 1 ELSE 0
                END) AS has_chu_muu
        FROM pn_ghi_chu_ids ids
        JOIN "DM_GHI_CHU_DAC_BIETS" dm
          ON dm."ID" = ids.ghi_chu_id
         AND NVL(dm."IS_DELETED", 0) = 0
        GROUP BY ids.pn_id
    ),
    -- Tr??ng h?p ??c bi?t (?u tiên ??c xá) theo ??t: l?y t? DKDX_DIEU_KIEN_DAC_BIET (m?ng GCR_MA, vd ["1700","1111","1500",...]) trong DX_DIEU_KIEN_DAC_XAS
    -- DKDX_DIEU_KIEN_DAC_BIET l?u GCR_MA (DM_GHI_CHU_RIENGS), LL_GHI_CHU_RIENG l?u ID ? map GCR_MA sang ID qua DM_GHI_CHU_RIENGS
    dk_dac_biet_gcr_ma AS (
        SELECT DISTINCT TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)) AS gcr_ma
        FROM (
            SELECT REPLACE(REPLACE(REPLACE(REPLACE(TRIM(NVL(dk.dieu_kien_dac_biet_str, '[]')), '[', ''), ']', ''), '"', ''), '''', '') AS csv
            FROM dk
            WHERE dk.dieu_kien_dac_biet_str IS NOT NULL
        ) r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.csv, ',') + 1
          AND PRIOR r.csv = r.csv
          AND PRIOR SYS_GUID() IS NOT NULL
          AND TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)) IS NOT NULL
    ),
    -- Map GCR_MA ? ID (DM_GHI_CHU_RIENGS) ?? so sánh v?i LL_GHI_CHU_RIENG (l?u ID)
    dk_dac_biet_ids AS (
        SELECT DISTINCT gcr.ID AS ghi_chu_rieng_id
        FROM dk_dac_biet_gcr_ma d
        JOIN "DM_GHI_CHU_RIENGS" gcr ON gcr."GCR_MA" = d.gcr_ma AND NVL(gcr."IS_DELETED", 0) = 0
    ),
    -- LL_GHI_CHU_RIENG (m?ng id) c?a t?ng PN ? tách thành (pn_id, ghi_chu_rieng_id)
    -- Quy ??c d? li?u: *_GHI_CHU_RIENG luôn là list id d?ng [id1,id2,...].
    pn_thdb_raw AS (
        SELECT
            ll."ID" AS pn_id,
            REPLACE(REPLACE(TRIM(NVL(ll."LL_GHI_CHU_RIENG", '[]')), '[', ''), ']', '') AS csv
        FROM "PN_LAI_LICHS" ll
        INNER JOIN candidates c ON c.pn_id = ll."ID"
        WHERE NVL(ll."IS_DELETED", 0) = 0
          AND ll."LL_GHI_CHU_RIENG" IS NOT NULL
    ),
    pn_thdb_ids AS (
        SELECT
            r.pn_id,
            TO_NUMBER(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL))) AS ghi_chu_rieng_id
        FROM pn_thdb_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.csv, ',') + 1
          AND PRIOR r.csv   = r.csv
          AND PRIOR r.pn_id = r.pn_id
          AND PRIOR SYS_GUID() IS NOT NULL
          AND TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)) IS NOT NULL
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)), '^\d+$')
    ),
    -- LL_NGAY_SINH (NVARCHAR): ?u tiên ?? ngày (DD/MM/YYYY), không ?? thì m?i xét n?m sinh (vd "2010")
    pn_nam_sinh AS (
        SELECT
            ll."ID" AS pn_id,
            CASE
                WHEN REGEXP_LIKE(TRIM(ll."LL_NGAY_SINH"), '^\d{1,2}/\d{1,2}/\d{4}$')
                THEN TO_DATE(TRIM(ll."LL_NGAY_SINH"), 'DD/MM/YYYY')
                ELSE NULL
            END AS ngay_sinh_date,
            CASE
                WHEN REGEXP_LIKE(TRIM(ll."LL_NGAY_SINH"), '^\d{1,2}/\d{1,2}/\d{4}$')
                THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll."LL_NGAY_SINH"), '^\d{4}$')
                THEN TO_NUMBER(TRIM(ll."LL_NGAY_SINH"))
                WHEN LENGTH(TRIM(ll."LL_NGAY_SINH")) >= 4
                     AND REGEXP_LIKE(SUBSTR(TRIM(ll."LL_NGAY_SINH"), -4), '^\d{4}$')
                THEN TO_NUMBER(SUBSTR(TRIM(ll."LL_NGAY_SINH"), -4))
                WHEN REGEXP_LIKE(ll."LL_NGAY_SINH", '\d{4}')
                THEN TO_NUMBER(REGEXP_SUBSTR(ll."LL_NGAY_SINH", '\d{4}', 1, 1))
                ELSE NULL
            END AS nam_sinh
        FROM "PN_LAI_LICHS" ll
        INNER JOIN candidates c ON c.pn_id = ll."ID"
        WHERE NVL(ll."IS_DELETED", 0) = 0
          AND ll."LL_NGAY_SINH" IS NOT NULL
    ),
    pn_duoi18_tai_ngay_xet AS (
        SELECT t.pn_id
        FROM pn_nam_sinh t
        CROSS JOIN ngay_xet_ctx nx
        WHERE (
              (t.ngay_sinh_date IS NOT NULL
               AND MONTHS_BETWEEN(nx.ngay_xet, t.ngay_sinh_date) / 12 < 18)
              OR
              (t.nam_sinh IS NOT NULL
               AND (EXTRACT(YEAR FROM nx.ngay_xet) - t.nam_sinh) < 18)
          )
    ),
    -- PN thu?c tr??ng h?p ??c bi?t: có ghi chú riêng trong DKDX_DIEU_KIEN_DAC_BIET HO?C d??i 18 tu?i t?i ngày xét
    pn_thdb_duoi18 AS (
        SELECT DISTINCT ids.pn_id
        FROM pn_thdb_ids ids
        INNER JOIN dk_dac_biet_ids d ON d.ghi_chu_rieng_id = ids.ghi_chu_rieng_id
        UNION
        SELECT pn_id FROM pn_duoi18_tai_ngay_xet
    ),
    -- B??c 1: áp d?ng các ?i?u ki?n lo?i tr? (t?i danh c?m, s? ti?n án, ?ã ???c ??c xá, ghi chú ??c bi?t)
    -- Theo DK_DX.txt: (1) lo?i b? t?i danh lo?i tr?, (2) lo?i b? PN có s? ti?n án >= m?c c?u hình, (3) lo?i b? các TH lo?i tr? ?ã c?u hình
    step1 AS (
        SELECT c.pn_id
        FROM candidates c
        CROSS JOIN dk
        LEFT JOIN pn_co_toi_loai_tru pt ON pt.pn_id = c.pn_id
        LEFT JOIN pn_da_tung_duoc_dac_xa pd ON pd.pn_id = c.pn_id
        LEFT JOIN "PN_LAI_LICHS" ll ON ll."ID" = c.pn_id
        LEFT JOIN pn_ghi_chu_dac_biet gch ON gch.pn_id = c.pn_id
        LEFT JOIN pn_co_nghien_mt nmt ON nmt.pn_id = c.pn_id
        WHERE pt.pn_id IS NULL  -- (1) Không có t?i danh thu?c danh sách lo?i tr?
          -- (2) Lo?i tr? PN có s? ti?n án >= m?c c?u hình => ch? gi? PN có s? ti?n án < m?c (ho?c m?c ch?a c?u hình)
          -- LL_SO_TIEN_AN: s? nguyên ??u tiên trong chu?i (ví d? "500000000" ho?c "500,000"), m?c ??nh 0
          AND (dk.so_tien_an_loai_tru IS NULL OR NVL(TO_NUMBER(REGEXP_SUBSTR(TRIM(ll."LL_SO_TIEN_AN"), '^\d+', 1, 1)), 0) < dk.so_tien_an_loai_tru)
          -- Ch? lo?i n?u ?ã t?ng ???c ??c xá (có trong PN_DAC_XAS); ?? ?i?u ki?n nh?ng ch?a ??c xá v?n xét l?i
          AND (dk.loai_tru_da_dac_xa IS NULL OR dk.loai_tru_da_dac_xa != 1 OR pd.pn_id IS NULL)
          AND (NVL(dk.loai_tru_ma_tuy, 0) != 1 OR (NVL(gch.has_ma_tuy_gch, 0) = 0 AND nmt.pn_id IS NULL))
          AND (NVL(dk."DKDX_DOI_TUONG_HIV_AIDS", 0) != 1 OR NVL(gch.has_hiv, 0) = 0)
          AND (NVL(dk."DKDX_TINH_CHAT_CON_DO", 0) != 1 OR NVL(gch.has_con_do, 0) = 0)
          AND (NVL(dk."DKDX_CHU_MUU_CAM_DAU", 0) != 1 OR NVL(gch.has_chu_muu, 0) = 0)
    ),
    -- B??c 2.1: l?y b?n ghi thi hành án ?ang hi?u l?c t?i ngày xét (m?i PN có th? nhi?u b?n ghi)
    -- N?u sau này có kho?ng p_ngay_xet_tu / den: ch? l?y THA giao v?i kho?ng ?ó
    tha_hien_tai AS (
        SELECT
            tha."THA_PNLAI_LICH_ID",
            tha."ID" AS tha_id,
            tha."THA_NGAY_BAT",
            tha."THA_NGAY_HET_HAN",
            tha."THA_NGAY_BAT_DAU_O_TU",
            tha."THA_AN_PHAT",
            tha."THA_MUC_AN_ID",
            tha."THA_THOI_GIAN_TAM_GIAM",
            tha."THA_TOI_DANH",
            COALESCE(tha."THA_NGAY_BAT_DAU_O_TU", tha."THA_NGAY_BAT") AS ngay_bat_dau
        FROM "PN_THI_HANH_AN" tha
        INNER JOIN step1 s ON s.pn_id = tha."THA_PNLAI_LICH_ID"
        CROSS JOIN ngay_xet_ctx nx
        WHERE NVL(tha."IS_DELETED", 0) = 0
          AND COALESCE(tha."THA_NGAY_BAT_DAU_O_TU", tha."THA_NGAY_BAT") IS NOT NULL
          AND (tha."THA_NGAY_HET_HAN" IS NULL OR tha."THA_NGAY_HET_HAN" >= nx.ngay_xet)
          AND COALESCE(tha."THA_NGAY_BAT_DAU_O_TU", tha."THA_NGAY_BAT") <= nx.ngay_xet
          AND tha."THA_NGAY_BAT" IS NOT NULL
          -- Kho?ng th?i gian xét: n?u truy?n c? tu và den thì ch? THA có ?o?n ch?p hành giao v?i [tu, den]
--          AND (p_ngay_xet_tu IS NULL OR p_ngay_xet_den IS NULL
--               OR (COALESCE(tha."THA_NGAY_BAT_DAU_O_TU", tha."THA_NGAY_BAT") <= CAST(p_ngay_xet_den AS DATE)
--                   AND (tha."THA_NGAY_HET_HAN" IS NULL OR tha."THA_NGAY_HET_HAN" >= CAST(p_ngay_xet_tu AS DATE))))
    ),
    -- Th?i gian th?c s? ?ã ? tù / còn l?i theo PKG_TINH_AN (công th?c: +t?m giam -t?m ?ình ch? -hoãn -tr?n)
    pn_ngay_chap_hanh AS (
        SELECT
            s.pn_id,
            PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH(s.pn_id, nx.ngay_xet) AS da_chapt_ngay,
            PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI(s.pn_id, nx.ngay_xet)      AS con_lai_ngay
        FROM step1 s
        CROSS JOIN ngay_xet_ctx nx
    ),
    -- M?i PN ch?n m?t b?n ghi THA ??i di?n (?u tiên ngày h?t h?n xa nh?t, r?i ID l?n nh?t)
    -- và g?n t?ng th?i gian ph?i ch?p hành = ?ã ch?p hành + còn l?i (theo th?i gian th?c t?)
    tha_mot_per_pn AS (
        SELECT
            t.*,
            p.da_chapt_ngay,
            p.con_lai_ngay,
            (p.da_chapt_ngay + p.con_lai_ngay) AS tong_ngay,
            CASE
                WHEN t."THA_AN_PHAT" IS NOT NULL
                 AND (
                     UPPER(t."THA_AN_PHAT") LIKE u'%CHUNG TH\00c2N%'
                     OR UPPER(t."THA_AN_PHAT") LIKE u'%CHUNG THAN%'
                 )
                THEN 1
                ELSE 0
            END AS is_chung_than,
            CASE
                WHEN t."THA_AN_PHAT" IS NOT NULL
                 AND (
                     UPPER(t."THA_AN_PHAT") LIKE u'%CHUNG TH\00c2N%'
                     OR UPPER(t."THA_AN_PHAT") LIKE u'%CHUNG THAN%'
                 )
                 AND UPPER(t."THA_AN_PHAT") LIKE u'%GI\1ea2M XU\1ed0NG%'
                THEN 1
                ELSE 0
            END AS is_chung_than_giam_xuong
        FROM (
            SELECT t.*,
                   ROW_NUMBER() OVER (PARTITION BY t."THA_PNLAI_LICH_ID" ORDER BY t."THA_NGAY_HET_HAN" DESC NULLS LAST, t.tha_id DESC) AS rn
            FROM tha_hien_tai t
        ) t
        LEFT JOIN pn_ngay_chap_hanh p ON p.pn_id = t."THA_PNLAI_LICH_ID"
        WHERE t.rn = 1
    ),
    -- C?u hình th?i gian ch?p hành (DX_THOI_GIAN_CHAP_HANHS) — ??c m?t l?n
    tgch_cfg AS (
        SELECT
            REPLACE(REPLACE(TRIM(NVL(tgch."TGCH_TOI_DANH_THOI_GIAN_CHAP_HANH", '[]')), '[', ''), ']', '') AS csv,
            tgch."TGCH_TOI_DANH_THUONG",
            tgch."TGCH_TOI_DANH_RIENG",
            tgch."TGCH_TH_DAC_BIET"
        FROM "DX_THOI_GIAN_CHAP_HANHS" tgch
        WHERE tgch."DX_DIEU_KIEN_DAC_XA_ID" = p_dx_dieu_kiem_dac_xa_id
          AND NVL(tgch."IS_DELETED", 0) = 0
    ),
    tgch_toi_rieng AS (
        SELECT DISTINCT TO_NUMBER(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL))) AS toi_danh_id
        FROM tgch_cfg r
        WHERE r.csv IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(r.csv, ',') + 1
          AND PRIOR r.csv = r.csv
          AND PRIOR SYS_GUID() IS NOT NULL
          AND TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)) IS NOT NULL
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)), '^\d+$')
    ),
    -- PN có ít nh?t m?t t?i danh thu?c nhóm t?i danh riêng ? trên
    -- T?i ?u: dùng t?p tha_toi_ids ?ã tách s?n, tránh LIKE chu?i THA_TOI_DANH.
    pn_thuoc_toi_rieng AS (
        SELECT DISTINCT ti.pn_id
        FROM tha_toi_ids ti
        INNER JOIN tgch_toi_rieng tdr
                ON tdr.toi_danh_id = ti.toi_danh_id
    ),
    -- C?u hình cho án tù có th?i h?n: parse t? l? d?ng '1/2', '1/3' t? DB (không hardcode)
    -- TGCH_TOI_DANH_THUONG=t?i th??ng, TGCH_TOI_DANH_RIENG=t?i riêng, TGCH_TH_DAC_BIET=TH?B/d??i 18
    cfg_tgch_huu_han AS (
        SELECT
            TO_NUMBER(REGEXP_SUBSTR(TRIM("TGCH_TOI_DANH_THUONG"), '^\d+')) /
                NULLIF(TO_NUMBER(REGEXP_SUBSTR(TRIM("TGCH_TOI_DANH_THUONG"), '\d+$')), 0) AS ratio_thuong,
            TO_NUMBER(REGEXP_SUBSTR(TRIM("TGCH_TOI_DANH_RIENG"), '^\d+')) /
                NULLIF(TO_NUMBER(REGEXP_SUBSTR(TRIM("TGCH_TOI_DANH_RIENG"), '\d+$')), 0) AS ratio_rieng,
            TO_NUMBER(REGEXP_SUBSTR(TRIM("TGCH_TH_DAC_BIET"), '^\d+')) /
                NULLIF(TO_NUMBER(REGEXP_SUBSTR(TRIM("TGCH_TH_DAC_BIET"), '\d+$')), 0) AS ratio_dac_biet
        FROM tgch_cfg
        WHERE REGEXP_LIKE(TRIM(NVL("TGCH_TOI_DANH_THUONG", '')), '\/')
        FETCH FIRST 1 ROWS ONLY
    ),
    -- C?u hình cho án chung thân gi?m xu?ng tù có th?i h?n: s? n?m t?i thi?u t? DB (không hardcode)
    cfg_tgch_chung_than AS (
        SELECT
            TO_NUMBER(REGEXP_SUBSTR(TRIM("TGCH_TOI_DANH_THUONG"), '^\d+')) AS nam_thuong,
            TO_NUMBER(REGEXP_SUBSTR(TRIM("TGCH_TOI_DANH_RIENG"), '^\d+'))  AS nam_rieng,
            TO_NUMBER(REGEXP_SUBSTR(TRIM("TGCH_TH_DAC_BIET"), '^\d+'))     AS nam_dac_biet
        FROM tgch_cfg
        WHERE NOT REGEXP_LIKE(TRIM(NVL("TGCH_TOI_DANH_THUONG", '')), '\/')
        FETCH FIRST 1 ROWS ONLY
    ),
    -- B??c 2.2: PN ??t ?i?u ki?n th?i gian ?ã ch?p hành theo c?u hình ??ng (DX_THOI_GIAN_CHAP_HANHS)
    -- 3 nhánh: T?i danh riêng / T?i thông th??ng / TH?B ho?c D??i 18 tu?i.
    -- So sánh t? l? theo l?ch th?c (n?m, tháng, ngày th?c t?): tháng 2 có 28 ngày, tháng 3 có 31 ngày...
    -- Ng??ng = CEIL(t?ng_ngày * t?_l?), ví d?: tháng 2 (28 ngày) 1/3 = 10 ngày, tháng 3 (31 ngày) = 11 ngày.
    -- 2.2.1. PN KHÔNG thu?c TH?B/d??i 18: nhánh T?i danh riêng ho?c T?i thông th??ng
    step2_non_thdb AS (
        SELECT t."THA_PNLAI_LICH_ID" AS pn_id
        FROM tha_mot_per_pn t
        CROSS JOIN ngay_xet_ctx nx
        LEFT JOIN pn_thuoc_toi_rieng tr ON tr.pn_id = t."THA_PNLAI_LICH_ID"
        LEFT JOIN pn_thdb_duoi18 td ON td.pn_id = t."THA_PNLAI_LICH_ID"
        LEFT JOIN cfg_tgch_huu_han h ON 1 = 1
        LEFT JOIN cfg_tgch_chung_than c ON 1 = 1
        WHERE t.da_chapt_ngay IS NOT NULL
          AND td.pn_id IS NULL
          AND (
              -- Nhánh 1 & 2: Án tù có th?i h?n (t? l? t? TGCH_*), so sánh theo l?ch th?c qua FN_DA_CHAP_HANH_DAT_TY_LE
              (t.tong_ngay IS NOT NULL AND t.tong_ngay > 0
               AND h.ratio_thuong IS NOT NULL
               AND (
                    -- Nhánh T?i danh riêng: ??t t? l? ratio_rieng (CEIL theo l?ch th?c)
                    (tr.pn_id IS NOT NULL AND h.ratio_rieng IS NOT NULL
                     AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_TY_LE(t."THA_PNLAI_LICH_ID", h.ratio_rieng, nx.ngay_xet) = 1)
                    -- Nhánh T?i thông th??ng: ??t t? l? ratio_thuong (CEIL theo l?ch th?c)
                 OR (tr.pn_id IS NULL
                     AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_TY_LE(t."THA_PNLAI_LICH_ID", h.ratio_thuong, nx.ngay_xet) = 1)
                   )
               AND (t."THA_AN_PHAT" IS NULL OR t.is_chung_than = 0))
              OR
              -- Nhánh 1 & 2: Chung thân gi?m xu?ng tù có th?i h?n (vd: "Chung thân Gi?m xu?ng 30 n?m", "Chung thân gi?m xu?ng 20 n?m")
              -- KHÔNG xét: "Chung thân", "Chung thân (Gi?m t? t? hình)"
              -- So sánh theo l?ch th?c: s? ngày th?c t? c?a X n?m t? ngày b?t (n?m nhu?n, tháng 28/29/30/31 ngày)
              (t.is_chung_than_giam_xuong = 1
               AND c.nam_thuong IS NOT NULL
               AND (
                    (tr.pn_id IS NOT NULL AND c.nam_rieng IS NOT NULL
                     AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_SO_NAM(t."THA_PNLAI_LICH_ID", c.nam_rieng, nx.ngay_xet) = 1)
                 OR (tr.pn_id IS NULL
                     AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_SO_NAM(t."THA_PNLAI_LICH_ID", c.nam_thuong, nx.ngay_xet) = 1)
                   )
              )
          )
    ),
    -- 2.2.2. Nhánh 3: PN thu?c TH?B ho?c D??i 18 tu?i (ng??ng riêng t? TGCH_TH_DAC_BIET)
    step2_thdb AS (
        SELECT t."THA_PNLAI_LICH_ID" AS pn_id
        FROM tha_mot_per_pn t
        CROSS JOIN ngay_xet_ctx nx
        INNER JOIN pn_thdb_duoi18 td ON td.pn_id = t."THA_PNLAI_LICH_ID"
        LEFT JOIN cfg_tgch_huu_han h ON 1 = 1
        LEFT JOIN cfg_tgch_chung_than c ON 1 = 1
        WHERE t.da_chapt_ngay IS NOT NULL
          AND (
              -- Án tù có th?i h?n: ??t t? l? ratio_dac_biet (CEIL theo l?ch th?c)
              (t.tong_ngay IS NOT NULL AND t.tong_ngay > 0
               AND h.ratio_dac_biet IS NOT NULL
               AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_TY_LE(t."THA_PNLAI_LICH_ID", h.ratio_dac_biet, nx.ngay_xet) = 1
               AND (t."THA_AN_PHAT" IS NULL OR t.is_chung_than = 0))
              OR
              -- Chung thân gi?m xu?ng tù có th?i h?n (vd: "Chung thân Gi?m xu?ng 30 n?m"). KHÔNG xét: "Chung thân", "Chung thân (Gi?m t? t? hình)"
              -- So sánh theo l?ch th?c: s? ngày th?c t? c?a X n?m t? ngày b?t (n?m nhu?n, tháng 28/29/30/31 ngày)
              (t.is_chung_than_giam_xuong = 1
               AND c.nam_dac_biet IS NOT NULL
               AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_SO_NAM(t."THA_PNLAI_LICH_ID", c.nam_dac_biet, nx.ngay_xet) = 1)
          )
    ),
    step2 AS (
        SELECT DISTINCT pn_id FROM step2_non_thdb
        UNION
        SELECT DISTINCT pn_id FROM step2_thdb
    ),
    -- ========== B??c 3: X?p lo?i ý th?c c?i t?o ==========
    -- 3.1. C?u hình x?p lo?i c?i t?o theo m?c án (DX_XEP_LOAI_CAI_TAOS) - ??ng t? DB
    cfg_xlct AS (
        SELECT "XLCT_MUC_AN"      AS muc_an,
               "XLCT_XEP_LOAI_LIEN_TUC"      AS quy_lien_tuc_lien_ke,
               "XLCT_SO_QUY_KHONG_LIEN_TUC"  AS quy_khong_lien_tuc,
               "XLCT_SO_QUY_LIEN_KE"         AS quy_lien_ke_neu_khong_lien_tuc,
               "XLCT_TH_DAC_BIET"            AS th_dac_biet
        FROM "DX_XEP_LOAI_CAI_TAOS"
        WHERE "DX_DIEU_KIEN_DAC_XA_ID" = p_dx_dieu_kiem_dac_xa_id
          AND NVL("IS_DELETED", 0) = 0
          AND RTRIM(NVL("XLCT_MUC_AN", ' ')) != ' '
    ),
    -- 3.2. PN t? step2 + c?u hình theo m?c án. Map: THA_AN_PHAT -> FN_GET_MUC_AN_PHAT_DAC_XA -> cfg_xlct.muc_an (XLCT_MUC_AN)
    -- C?u hình DX_XEP_LOAI_CAI_TAOS.XLCT_MUC_AN ph?i kh?p chu?i tr? v? c?a FN_GET_MUC_AN_PHAT_DAC_XA
    step2_with_cfg AS (
        SELECT s.pn_id,
               c.quy_lien_tuc_lien_ke       AS cfg_quy_lien_tuc_lien_ke,
               c.quy_khong_lien_tuc AS cfg_quy_khong_lien_tuc,
               c.quy_lien_ke_neu_khong_lien_tuc        AS cfg_quy_lien_ke_neu_khong_lien_tuc,
               c.th_dac_biet        AS cfg_th_dac_biet
        FROM step2 s
        INNER JOIN tha_mot_per_pn t ON t."THA_PNLAI_LICH_ID" = s.pn_id
        INNER JOIN cfg_xlct c ON TRIM(NVL(c.muc_an, ' ')) = TRIM(NVL(FN_GET_MUC_AN_PHAT_DAC_XA(t."THA_AN_PHAT"), ' '))
    ),
    -- 3.3. T?ng quý Khá/T?t, s? quý liên t?c dài nh?t, s? quý li?n k? ngày xét (dùng function FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC_LIEN_KE)
    pn_so_quy AS (
        SELECT s.pn_id,
               NVL(FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT(s.pn_id, NULL).SO_QUY, 0) AS tong_quy,
--               NVL(FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC(s.pn_id, NULL).SO_QUY, 0) AS quy_lien_tuc,
               NVL(FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC_LIEN_KE(s.pn_id, nx.ngay_xet), 0) AS quy_lien_ke_xet
        FROM step2 s
        CROSS JOIN ngay_xet_ctx nx
    ),
    -- 3.4. Lu?ng if/else: Nhánh TH?B tách riêng; ??i t??ng th??ng: lien_tuc -> khong_lien_tuc
    -- Nhánh 1 (??i t??ng th??ng): S? quý liên t?c li?n k? >= XLCT_XEP_LOAI_LIEN_TUC
    step3_lien_tuc AS (
        SELECT w.pn_id
        FROM step2_with_cfg w
        INNER JOIN pn_so_quy p ON p.pn_id = w.pn_id
--        LEFT JOIN pn_thdb_duoi18 th ON th.pn_id = w.pn_id
        WHERE 
--        th.pn_id IS NULL AND 
        w.cfg_quy_lien_tuc_lien_ke IS NOT NULL
          AND p.quy_lien_ke_xet >= w.cfg_quy_lien_tuc_lien_ke
    ),
    -- Nhánh 2 (??i t??ng th??ng, không ??t liên t?c): (T?ng quý không liên t?c >= XLCT_SO_QUY_KHONG_LIEN_TUC) VÀ (quý li?n k? >= XLCT_SO_QUY_LIEN_KE)
    step3_khong_lien_tuc AS (
        SELECT w.pn_id
        FROM step2_with_cfg w
        INNER JOIN pn_so_quy p ON p.pn_id = w.pn_id
--        LEFT JOIN pn_thdb_duoi18 th ON th.pn_id = w.pn_id
        LEFT JOIN step3_lien_tuc l ON l.pn_id = w.pn_id
        WHERE l.pn_id IS NULL
          AND w.cfg_quy_khong_lien_tuc IS NOT NULL
          AND w.cfg_quy_lien_ke_neu_khong_lien_tuc IS NOT NULL
          AND p.tong_quy >= w.cfg_quy_khong_lien_tuc
          AND p.quy_lien_ke_xet >= w.cfg_quy_lien_ke_neu_khong_lien_tuc
    ),
    -- Nhánh 3 (TH?B/D??i 18 tách riêng): T?ng s? quý li?n k? >= XLCT_TH_DAC_BIET
    step3_thdb AS (
        SELECT w.pn_id
        FROM step2_with_cfg w
        INNER JOIN pn_thdb_duoi18 th ON th.pn_id = w.pn_id
        INNER JOIN pn_so_quy p ON p.pn_id = w.pn_id
        WHERE w.cfg_th_dac_biet IS NOT NULL
          AND p.quy_lien_ke_xet >= w.cfg_th_dac_biet
    ),
    -- 3.5. H?p nh?t: ??t theo liên t?c, ho?c theo không liên t?c, ho?c theo TH?B/d??i 18
    step3 AS (
        SELECT pn_id FROM step3_lien_tuc
        UNION
        SELECT pn_id FROM step3_khong_lien_tuc
        UNION
        SELECT pn_id FROM step3_thdb
    ),
    -- B??c 4: Th?i gian ch?p hành án còn l?i (TC.H.A.P.T.C.L) - c?u hình thu?n t? DB
    -- 4.1. C?u hình th?i gian còn l?i cho t?i danh còn l?i (DX_THOI_GIAN_CON_LAIES)
    -- M?i dòng: TGCL_LOAI_DOI_TUONG (ng??i dùng c?u hình), TGCL_THOI_GIAN_CON_LAI (s? n?m)
    -- Phân lo?i ??ng theo TGCL_LOAI_DOI_TUONG do ng??i dùng nh?p (không hardcode s? n?m)
    cfg_tgcl AS (
        SELECT
            MIN(CASE
                    WHEN UPPER(NVL("TGCL_LOAI_DOI_TUONG", '')) NOT LIKE u'%TR\01af\1edcNG H\1ee2P \0110\1eb6C BI\1ec6T%'
                     AND UPPER(NVL("TGCL_LOAI_DOI_TUONG", '')) NOT LIKE u'%D\01af\1edaI 18%'
                    THEN "TGCL_THOI_GIAN_CON_LAI"
                END) AS tg_con_lai_loai1,
            MIN(CASE
                    WHEN UPPER(NVL("TGCL_LOAI_DOI_TUONG", '')) LIKE u'%TR\01af\1edcNG H\1ee2P \0110\1eb6C BI\1ec6T%'
                      OR UPPER(NVL("TGCL_LOAI_DOI_TUONG", '')) LIKE u'%D\01af\1edaI 18%'
                    THEN "TGCL_THOI_GIAN_CON_LAI"
                END) AS tg_con_lai_loai2
        FROM "DX_THOI_GIAN_CON_LAIES"
        WHERE "DX_DIEU_KIEN_DAC_XA_ID" = p_dx_dieu_kiem_dac_xa_id
          AND NVL("IS_DELETED", 0) = 0
    ),
    -- 4.2. C?u hình t?i danh riêng (DX_TOI_DANH_RIENGS): TOI_DANH [id1,id2], TDR_MUC_AN, TDR_THOI_GIAN_CHAP_HANH_CON_LAI
    tdr_raw AS (
        SELECT
            REPLACE(REPLACE(TRIM(NVL(tdr."TOI_DANH", '[]')), '[', ''), ']', '') AS csv,
            tdr."TDR_MUC_AN"                  AS tdr_muc_an,
            tdr."TDR_THOI_GIAN_CHAP_HANH_CON_LAI" AS tg_con_lai_nam
        FROM "DX_TOI_DANH_RIENGS" tdr
        WHERE tdr."DX_DIEU_KIEN_DAC_XA_ID" = p_dx_dieu_kiem_dac_xa_id
          AND NVL(tdr."IS_DELETED", 0) = 0
    ),
    tdr_cfg AS (
        SELECT DISTINCT
            TO_NUMBER(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL))) AS dm_toi_danh_id,
            r.tdr_muc_an,
            r.tg_con_lai_nam
        FROM tdr_raw r
        WHERE r.csv IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(r.csv, ',') + 1
          AND PRIOR r.csv = r.csv
          AND PRIOR SYS_GUID() IS NOT NULL
          AND TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)) IS NOT NULL
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)), '^\d+$')
    ),
    -- 4.3. Th?i gian còn l?i (n?m) cho t?ng PN trên b?n án ??i di?n - dùng PKG_TINH_AN
    step4_base AS (
        SELECT
            t."THA_PNLAI_LICH_ID" AS pn_id,
            t.tha_id,
            t."THA_MUC_AN_ID" AS muc_an_id,
            CASE
                WHEN t.con_lai_ngay IS NOT NULL
                THEN t.con_lai_ngay / 365.25
                ELSE NULL
            END AS con_lai_nam
        FROM tha_mot_per_pn t
        INNER JOIN step3 s ON s.pn_id = t."THA_PNLAI_LICH_ID"
    ),
    -- 4.4. L?c ?u tiên 1 - T?I DANH RIÊNG: Join THA v?i DX_TOI_DANH_RIENGS (??i sánh ID t?i danh + ID m?c án), con_lai <= TDR_THOI_GIAN_CHAP_HANH_CON_LAI
    step4_rieng AS (
        SELECT DISTINCT b.pn_id
        FROM step4_base b
        INNER JOIN tha_toi_ids tid ON tid.tha_id = b.tha_id
        INNER JOIN tdr_cfg cfg
                ON cfg.dm_toi_danh_id = tid.toi_danh_id
               AND (cfg.tdr_muc_an IS NULL OR cfg.tdr_muc_an = b.muc_an_id)
               AND cfg.tg_con_lai_nam IS NOT NULL
        WHERE b.con_lai_nam IS NOT NULL
          AND b.con_lai_nam <= cfg.tg_con_lai_nam
    ),
    -- PN có ít nh?t m?t t?i danh map ???c v?i DX_TOI_DANH_RIENGS (c? t?i danh + m?c án)
    pn_co_toi_rieng_tgcl AS (
        SELECT DISTINCT b.pn_id
        FROM step4_base b
        INNER JOIN tha_toi_ids tid ON tid.tha_id = b.tha_id
        INNER JOIN tdr_cfg cfg
                ON cfg.dm_toi_danh_id = tid.toi_danh_id
               AND (cfg.tdr_muc_an IS NULL OR cfg.tdr_muc_an = b.muc_an_id)
    ),
    -- 4.5. L?c ?u tiên 2 - T?i danh còn l?i (Thông th??ng): con_lai <= TGCL_THOI_GIAN_CON_LAI (lo?i 1) t? DX_THOI_GIAN_CON_LAIES
    step4_chung AS (
        SELECT b.pn_id
        FROM step4_base b
        LEFT JOIN step4_rieng r ON r.pn_id = b.pn_id
        LEFT JOIN pn_co_toi_rieng_tgcl pr ON pr.pn_id = b.pn_id
        CROSS JOIN cfg_tgcl c
        WHERE r.pn_id IS NULL
          AND pr.pn_id IS NULL
          AND b.con_lai_nam IS NOT NULL
          AND c.tg_con_lai_loai1 IS NOT NULL
          AND b.con_lai_nam <= c.tg_con_lai_loai1
    ),
    -- 4.6. L?c ?u tiên 2 - T?i danh còn l?i (TH?B/d??i 18): con_lai <= TGCL_THOI_GIAN_CON_LAI (lo?i 2) t? DX_THOI_GIAN_CON_LAIES
    step4_thdb AS (
        SELECT b.pn_id
        FROM step4_base b
        INNER JOIN pn_thdb_duoi18 d ON d.pn_id = b.pn_id
        LEFT JOIN step4_rieng r ON r.pn_id = b.pn_id
        LEFT JOIN step4_chung c ON c.pn_id = b.pn_id
        CROSS JOIN cfg_tgcl c2
        WHERE r.pn_id IS NULL
          AND c.pn_id IS NULL
          AND b.con_lai_nam IS NOT NULL
          AND c2.tg_con_lai_loai2 IS NOT NULL
          AND b.con_lai_nam <= c2.tg_con_lai_loai2
    ),
    -- 4.7. H?p nh?t k?t qu? b??c 4
    step4 AS (
        SELECT pn_id FROM step4_rieng
        UNION
        SELECT pn_id FROM step4_chung
        UNION
        SELECT pn_id FROM step4_thdb
    ),
    -- B??c 5: Hình ph?t b? sung (HPBS) theo c?u hình DX_HINH_PHAT_BO_SUNGS
    -- Ngu?n: PN_HINH_PHAT_BO_SUNGS. Xác ??nh ?ã hoàn thành b?ng HPBS_TONG_TIEN_PHAT, HPBS_TONG_TIEN_CON_LAI (không xét PN_BIENLAIES).
    -- HPBS_GHI_CHU (DM_GHI_CHU_HINH_PHAT_BO_SUNGS) dùng cho tr??ng h?p "mi?n" thi hành.
    cfg_hpbs AS (
        SELECT *
        FROM "DX_HINH_PHAT_BO_SUNGS" c
        WHERE c."DX_DIEU_KIEN_DAC_XA_ID" = p_dx_dieu_kiem_dac_xa_id
          AND NVL(c."IS_DELETED", 0) = 0
        FETCH FIRST 1 ROWS ONLY
    ),
    -- Map nhóm HPBS theo DM_HINH_PHAT_BO_SUNGS.HPBS_MA (m?t l?n quét DM)
    dm_hpbs_group AS (
        SELECT
            dm."ID" AS hpbs_hinh_phat_id,
            CASE
                WHEN dm."HPBS_MA" = '220' THEN 'PT'
                WHEN dm."HPBS_MA" = '236' THEN 'BT'
                WHEN dm."HPBS_MA" = '237' THEN 'NVDS'
                WHEN dm."HPBS_MA" IN ('250', '251', '252', '260', '261', '262', '263') THEN 'AP'
                WHEN dm."HPBS_MA" = '235' THEN 'NVTL'
                ELSE 'NVTL'
            END AS hpbs_group
        FROM "DM_HINH_PHAT_BO_SUNGS" dm
        WHERE NVL(dm."IS_DELETED", 0) = 0
          AND dm."HPBS_MA" IN ('220', '236', '237', '235', '250', '251', '252', '260', '261', '262', '263')
    ),
    -- Xác ??nh ?ã hoàn thành HPBS: ch? dùng HPBS_TONG_TIEN_PHAT, HPBS_TONG_TIEN_CON_LAI t? PN_HINH_PHAT_BO_SUNGS (không xét PN_BIENLAIES).
    -- HPBS_GHI_CHU v?n dùng cho tr??ng h?p "mi?n" thi hành.
    hpbs_rows AS (
        SELECT
            hp."HPBS_MA_PHAM_NHAN" AS pn_id,
            hp."ID" AS hpbs_id,
            hp."HPBS_HINH_PHAT" AS hpbs_hinh_phat_id,
            NVL(hp."HPBS_TONG_TIEN_PHAT", 0) AS tong_tien_phat,
            NVL(hp."HPBS_TONG_TIEN_CON_LAI", 0) AS tong_tien_con_lai,
            hp."HPBS_GHI_CHU" AS ghi_chu_id,
            gch."GCHPBS_TEN" AS gchpbs_ten
        FROM "PN_HINH_PHAT_BO_SUNGS" hp
        INNER JOIN step3 s3 ON s3.pn_id = hp."HPBS_MA_PHAM_NHAN"
        LEFT JOIN "DM_GHI_CHU_HINH_PHAT_BO_SUNGS" gch
          ON gch."ID" = hp."HPBS_GHI_CHU"
         AND NVL(gch."IS_DELETED", 0) = 0
        WHERE NVL(hp."IS_DELETED", 0) = 0
          AND hp."HPBS_MA_PHAM_NHAN" IS NOT NULL
    ),
    hpbs_categorized AS (
        SELECT
            r.pn_id,
            r.hpbs_id,
            r.hpbs_hinh_phat_id,
            r.tong_tien_phat,
            r.tong_tien_con_lai,
            r.ghi_chu_id,
            r.gchpbs_ten,
            NVL(dg.hpbs_group, 'NVTL') AS hpbs_group,
            -- Mi?n: HPBS_GHI_CHU -> GCHPBS_TEN ch?a "mi?n"
            CASE
                WHEN r.ghi_chu_id IS NOT NULL AND UPPER(NVL(r.gchpbs_ten, '')) LIKE u'%MI\1ec4N%' THEN 1
                ELSE 0
            END AS is_mien,
            -- ?ã hoàn thành: dùng HPBS_TONG_TIEN_CON_LAI (không xét PN_BIENLAIES). Hoàn thành khi còn l?i <= 0.
            CASE
                WHEN NVL(r.tong_tien_con_lai, 0) <= 0 THEN 1
                ELSE 0
            END AS is_da_nop_note
        FROM hpbs_rows r
        LEFT JOIN dm_hpbs_group dg ON dg.hpbs_hinh_phat_id = r.hpbs_hinh_phat_id
    ),
    -- T?ng h?p theo PN cho t?ng nhóm HPBS
    hpbs_agg AS (
        SELECT
            pn_id,
            -- PT
            SUM(CASE WHEN hpbs_group = 'PT' THEN 1 ELSE 0 END) AS pt_has,
            MIN(CASE WHEN hpbs_group = 'PT'
                     THEN CASE
                              WHEN is_mien = 1 THEN 1
                              WHEN is_da_nop_note = 1 THEN 1
                              ELSE 0
                          END
                     ELSE 1 END) AS pt_done_all,
            MAX(CASE WHEN hpbs_group = 'PT' THEN is_mien ELSE 0 END) AS pt_mien_any,
            -- BT
            SUM(CASE WHEN hpbs_group = 'BT' THEN 1 ELSE 0 END) AS bt_has,
            MIN(CASE WHEN hpbs_group = 'BT'
                     THEN CASE
                              WHEN is_mien = 1 THEN 1
                              WHEN is_da_nop_note = 1 THEN 1
                              ELSE 0
                          END
                     ELSE 1 END) AS bt_done_all,
            MAX(CASE WHEN hpbs_group = 'BT' THEN is_mien ELSE 0 END) AS bt_mien_any,
            -- NVDS
            SUM(CASE WHEN hpbs_group = 'NVDS' THEN 1 ELSE 0 END) AS nvds_has,
            MIN(CASE WHEN hpbs_group = 'NVDS'
                     THEN CASE
                              WHEN is_mien = 1 THEN 1
                              WHEN is_da_nop_note = 1 THEN 1
                              ELSE 0
                          END
                     ELSE 1 END) AS nvds_done_all,
            MAX(CASE WHEN hpbs_group = 'NVDS' THEN is_mien ELSE 0 END) AS nvds_mien_any,
            -- AP
            SUM(CASE WHEN hpbs_group = 'AP' THEN 1 ELSE 0 END) AS ap_has,
            MIN(CASE WHEN hpbs_group = 'AP'
                     THEN CASE
                              WHEN is_mien = 1 THEN 1
                              WHEN is_da_nop_note = 1 THEN 1
                              ELSE 0
                          END
                     ELSE 1 END) AS ap_done_all,
            MAX(CASE WHEN hpbs_group = 'AP' THEN is_mien ELSE 0 END) AS ap_mien_any,
            -- NVTL (fallback)
            SUM(CASE WHEN hpbs_group = 'NVTL' THEN 1 ELSE 0 END) AS nvtl_has,
            MIN(CASE WHEN hpbs_group = 'NVTL'
                     THEN CASE
                              WHEN is_mien = 1 THEN 1
                              WHEN is_da_nop_note = 1 THEN 1
                              ELSE 0
                          END
                     ELSE 1 END) AS nvtl_done_all,
            MAX(CASE WHEN hpbs_group = 'NVTL' THEN is_mien ELSE 0 END) AS nvtl_mien_any
        FROM hpbs_categorized
        GROUP BY pn_id
    ),
    -- Khi không có c?u hình HPBS (cfg_hpbs r?ng): t?t c? step4 ??u ??t (không ràng bu?c HPBS).
    -- Khi có c?u hình: PN không có HPBS c?a nhóm t??ng ?ng (pt_has=0, bt_has=0,...) thì coi nh? ??t nhóm ?ó.
    step5 AS (
        SELECT s.pn_id FROM step4 s
        WHERE NOT EXISTS (SELECT 1 FROM cfg_hpbs)
        UNION
        SELECT t."THA_PNLAI_LICH_ID" AS pn_id
        FROM tha_mot_per_pn t
        INNER JOIN step4 s ON s.pn_id = t."THA_PNLAI_LICH_ID"
        CROSS JOIN cfg_hpbs cfg
        LEFT JOIN hpbs_agg a ON a.pn_id = t."THA_PNLAI_LICH_ID"
        WHERE t."THA_PNLAI_LICH_ID" IS NOT NULL
          -- N?u PN không có HPBS c?a nhóm t??ng ?ng thì không ràng bu?c (coi nh? ??t nhóm ?ó).
          AND (
              NVL(cfg."HPBS_PT_DA_THI_HANH", 0) = 0 AND NVL(cfg."HPBS_PT_MIEN_THI_HANH", 0) = 0
              OR NVL(a.pt_has, 0) = 0
              OR (
                    (NVL(cfg."HPBS_PT_DA_THI_HANH", 0) = 1 AND NVL(cfg."HPBS_PT_MIEN_THI_HANH", 0) = 0 AND NVL(a.pt_done_all, 0) = 1)
                 OR (NVL(cfg."HPBS_PT_DA_THI_HANH", 0) = 0 AND NVL(cfg."HPBS_PT_MIEN_THI_HANH", 0) = 1 AND NVL(a.pt_mien_any, 0) = 1)
                 OR (NVL(cfg."HPBS_PT_DA_THI_HANH", 0) = 1 AND NVL(cfg."HPBS_PT_MIEN_THI_HANH", 0) = 1 AND (NVL(a.pt_done_all, 0) = 1 OR NVL(a.pt_mien_any, 0) = 1))
                 )
          )
          AND (
              NVL(cfg."HPBS_BT_DA_THI_HANH", 0) = 0 AND NVL(cfg."HPBS_BT_MIEN_THI_HANH", 0) = 0
              OR NVL(a.bt_has, 0) = 0
              OR (
                    (NVL(cfg."HPBS_BT_DA_THI_HANH", 0) = 1 AND NVL(cfg."HPBS_BT_MIEN_THI_HANH", 0) = 0 AND NVL(a.bt_done_all, 0) = 1)
                 OR (NVL(cfg."HPBS_BT_DA_THI_HANH", 0) = 0 AND NVL(cfg."HPBS_BT_MIEN_THI_HANH", 0) = 1 AND NVL(a.bt_mien_any, 0) = 1)
                 OR (NVL(cfg."HPBS_BT_DA_THI_HANH", 0) = 1 AND NVL(cfg."HPBS_BT_MIEN_THI_HANH", 0) = 1 AND (NVL(a.bt_done_all, 0) = 1 OR NVL(a.bt_mien_any, 0) = 1))
                 )
          )
          AND (
              NVL(cfg."HPBS_NVDS_DA_THI_HANH", 0) = 0 AND NVL(cfg."HPBS_NVDS_MIEN_THI_HANH", 0) = 0
              OR NVL(a.nvds_has, 0) = 0
              OR (
                    (NVL(cfg."HPBS_NVDS_DA_THI_HANH", 0) = 1 AND NVL(cfg."HPBS_NVDS_MIEN_THI_HANH", 0) = 0 AND NVL(a.nvds_done_all, 0) = 1)
                 OR (NVL(cfg."HPBS_NVDS_DA_THI_HANH", 0) = 0 AND NVL(cfg."HPBS_NVDS_MIEN_THI_HANH", 0) = 1 AND NVL(a.nvds_mien_any, 0) = 1)
                 OR (NVL(cfg."HPBS_NVDS_DA_THI_HANH", 0) = 1 AND NVL(cfg."HPBS_NVDS_MIEN_THI_HANH", 0) = 1 AND (NVL(a.nvds_done_all, 0) = 1 OR NVL(a.nvds_mien_any, 0) = 1))
                 )
          )
          AND (
              NVL(cfg."HPBS_AP_DA_THI_HANH", 0) = 0 AND NVL(cfg."HPBS_AP_MIEN_THI_HANH", 0) = 0
              OR NVL(a.ap_has, 0) = 0
              OR (
                    (NVL(cfg."HPBS_AP_DA_THI_HANH", 0) = 1 AND NVL(cfg."HPBS_AP_MIEN_THI_HANH", 0) = 0 AND NVL(a.ap_done_all, 0) = 1)
                 OR (NVL(cfg."HPBS_AP_DA_THI_HANH", 0) = 0 AND NVL(cfg."HPBS_AP_MIEN_THI_HANH", 0) = 1 AND NVL(a.ap_mien_any, 0) = 1)
                 OR (NVL(cfg."HPBS_AP_DA_THI_HANH", 0) = 1 AND NVL(cfg."HPBS_AP_MIEN_THI_HANH", 0) = 1 AND (NVL(a.ap_done_all, 0) = 1 OR NVL(a.ap_mien_any, 0) = 1))
                 )
          )
          AND (
              NVL(cfg."HPBS_NVTL_DA_THI_HANH", 0) = 0 AND NVL(cfg."HPBS_NVTL_MIEN_THI_HANH", 0) = 0
              OR NVL(a.nvtl_has, 0) = 0
              OR (
                    (NVL(cfg."HPBS_NVTL_DA_THI_HANH", 0) = 1 AND NVL(cfg."HPBS_NVTL_MIEN_THI_HANH", 0) = 0 AND NVL(a.nvtl_done_all, 0) = 1)
                 OR (NVL(cfg."HPBS_NVTL_DA_THI_HANH", 0) = 0 AND NVL(cfg."HPBS_NVTL_MIEN_THI_HANH", 0) = 1 AND NVL(a.nvtl_mien_any, 0) = 1)
                 OR (NVL(cfg."HPBS_NVTL_DA_THI_HANH", 0) = 1 AND NVL(cfg."HPBS_NVTL_MIEN_THI_HANH", 0) = 1 AND (NVL(a.nvtl_done_all, 0) = 1 OR NVL(a.nvtl_mien_any, 0) = 1))
                 )
          )
    ),
    -- PN không ?? ?i?u ki?n theo t?ng b??c: xác ??nh b??c fail ??u tiên và lí do
    khong_du AS (
        SELECT c.pn_id, u'B\01b0\1edbc 1: Kh\00f4ng \0111\1ea1t \0111i\1ec1u ki\1ec7n lo\1ea1i tr\1eeb' AS li_do
        FROM candidates c
        WHERE NOT EXISTS (SELECT 1 FROM step1 s WHERE s.pn_id = c.pn_id)
        UNION ALL
        SELECT c.pn_id, u'B\01b0\1edbc 2: Kh\00f4ng \0111\1ea1t th\1eddi gian ch\1ea5p h\00e0nh'
        FROM step1 c
        WHERE NOT EXISTS (SELECT 1 FROM step2 s WHERE s.pn_id = c.pn_id)
        UNION ALL
        SELECT c.pn_id, u'B\01b0\1edbc 3: Kh\00f4ng \0111\1ea1t x\1ebfp lo\1ea1i c\1ea3i t\1ea1o'
        FROM step2 c
        WHERE NOT EXISTS (SELECT 1 FROM step3 s WHERE s.pn_id = c.pn_id)
        UNION ALL
        SELECT c.pn_id, u'B\01b0\1edbc 4: Kh\00f4ng \0111\1ea1t th\1eddi gian c\00f2n l\1ea1i'
        FROM step3 c
        WHERE NOT EXISTS (SELECT 1 FROM step4 s WHERE s.pn_id = c.pn_id)
        UNION ALL
        SELECT c.pn_id, u'B\01b0\1edbc 5: Kh\00f4ng \0111\1ea1t h\00ecnh ph\1ea1t b\1ed5 sung'
        FROM step4 c
        WHERE NOT EXISTS (SELECT 1 FROM step5 s WHERE s.pn_id = c.pn_id)
    ),
    -- G?p PN ?? và không ?? ?? INSERT ALL (theo t?ng b??c v?i li_do)
    combined AS (
        SELECT COALESCE(v_pn_dot_dac_xa_id, dk.pn_dot_dac_xa_id) AS pn_dot_dac_xa_id,
               s.pn_id AS pn_lai_lich_id,
               CAST(NULL AS NVARCHAR2(2000)) AS li_do_khong_thoa_man,
               1 AS is_du
        FROM dk
        INNER JOIN step5 s ON 1 = 1
        UNION ALL
        SELECT COALESCE(v_pn_dot_dac_xa_id, dk.pn_dot_dac_xa_id) AS pn_dot_dac_xa_id,
               k.pn_id AS pn_lai_lich_id,
               k.li_do AS li_do_khong_thoa_man,
               0 AS is_du
        FROM dk
        CROSS JOIN khong_du k
    )
    SELECT pn_dot_dac_xa_id, pn_lai_lich_id, li_do_khong_thoa_man, is_du FROM combined
    );

    -- ===== B3: snapshot batch (hit memo core) -> MERGE GTT =====
    MERGE INTO GTT_DX_SNAP g
    USING TABLE(PKG_TINH_AN.FN_SNAPSHOT_BATCH(v_ids, CAST(v_ngay_xet AS DATE))) s
    ON (g.pn_id = s.pn_id)
    WHEN MATCHED THEN UPDATE SET
      g.snap_da_ch=s.tg_da, g.snap_con_lai=s.tg_con,
      g.snap_da_ch_text=s.tg_da_text, g.snap_con_lai_text=s.tg_con_text, g.snap_giam=s.tong_giam,
      g.snap_da_ch_thang=s.tg_da_thang, g.snap_con_lai_thang=s.tg_con_thang, g.snap_ngay_bat=s.ngay_bat;

    -- ===== B4: INSERT du =====
    INSERT INTO DX_DU_DIEU_KIEN_DAC_XAS
        (pn_dot_dac_xa_id, pn_lai_lich_id, SNAP_DA_CHAP_HANH, SNAP_CON_LAI,
         SNAP_DA_CHAP_HANH_TEXT, SNAP_CON_LAI_TEXT, SNAP_TONG_THOI_GIAN_GIAM, SNAP_NGAY_XET,
         SNAP_DA_CHAP_HANH_THANG, SNAP_CON_LAI_THANG, SNAP_NGAY_BAT)
    SELECT v_pn_dot_dac_xa_id, g.pn_id, g.snap_da_ch, g.snap_con_lai,
           g.snap_da_ch_text, g.snap_con_lai_text, g.snap_giam, CAST(v_ngay_xet AS DATE),
           g.snap_da_ch_thang, g.snap_con_lai_thang, g.snap_ngay_bat
    FROM GTT_DX_SNAP g WHERE g.is_du = 1;

    -- ===== B5: INSERT khong du =====
    INSERT INTO DX_KHONG_DU_DIEU_KIEN_DAC_XAS
        (pn_dot_dac_xa_id, pn_lai_lich_id, li_do_khong_thoa_man, SNAP_DA_CHAP_HANH, SNAP_CON_LAI,
         SNAP_DA_CHAP_HANH_TEXT, SNAP_CON_LAI_TEXT, SNAP_TONG_THOI_GIAN_GIAM, SNAP_NGAY_XET,
         SNAP_DA_CHAP_HANH_THANG, SNAP_CON_LAI_THANG, SNAP_NGAY_BAT)
    SELECT v_pn_dot_dac_xa_id, g.pn_id, g.li_do, g.snap_da_ch, g.snap_con_lai,
           g.snap_da_ch_text, g.snap_con_lai_text, g.snap_giam, CAST(v_ngay_xet AS DATE),
           g.snap_da_ch_thang, g.snap_con_lai_thang, g.snap_ngay_bat
    FROM GTT_DX_SNAP g WHERE g.is_du = 0;


    SELECT COUNT(*) INTO v_so_pham_nhan
    FROM DX_DU_DIEU_KIEN_DAC_XAS
    WHERE pn_dot_dac_xa_id = v_pn_dot_dac_xa_id;
    p_thong_bao := u'C\00f3 ' || TO_CHAR(v_so_pham_nhan) || u' ph\1ea1m nh\00e2n \0111\1ee7 \0111i\1ec1u ki\1ec7n';

    -- L?u log m?i l?n ch?y
    INSERT INTO DX_SP_DANH_SACH_DU_DIEU_KIEN_LOGS (
        DX_DIEU_KIEN_DAC_XA_ID,
        PN_DOT_DAC_XA_ID,
        NGAY_CHAY,
        SO_PHAM_NHAN,
        THONG_BAO
    ) VALUES (
        p_dx_dieu_kiem_dac_xa_id,
        v_pn_dot_dac_xa_id,
        SYSTIMESTAMP,
        v_so_pham_nhan,
        p_thong_bao
    );

    Commit;


      QLPN.SP_MATERIALIZE_DISPLAY(
         p_dot_dac_xa_id => v_pn_dot_dac_xa_id,
         p_ma_trai_giam  =>  p_ma_trai_giam   -- TG_MA t? DM_TRAI_GIAMS
     );
END;

/
