--  DDL for Procedure SP_DEBUG_DIEU_KIEN_GTH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_DEBUG_DIEU_KIEN_GTH" (
    p_pham_nhan_id IN NUMBER,
    p_ky_giam_id   IN NUMBER
)
AS
    -- ??? K? GI?M ????????????????????????????????????????????????????????????????
    v_dieu_kien_id      NUMBER;
    v_ngay_xet          DATE;
    v_ten_ky            NVARCHAR2(500);
    v_nguong_text_ap_dung   NVARCHAR2(100);
    v_co_pham_toi_moi       NUMBER := 0;

    -- ??? PH?M NHÂN ??????????????????????????????????????????????????????????????
    v_ho_ten            NVARCHAR2(500);
    v_tinh_trang        NVARCHAR2(500);

    -- ??? ÁN PH?T ????????????????????????????????????????????????????????????????
    v_an_phat           NVARCHAR2(500);
    v_tong_ngay_an      NUMBER := 0;
    v_ngay_bat          DATE;
    v_ngay_het_han      DATE;
    v_tam_giam_text     NVARCHAR2(500);
    v_tam_giu_text      NVARCHAR2(500);
    v_tam_giam_ngay     NUMBER := 0;
    v_tam_giu_ngay      NUMBER := 0;
    v_da_chap_hanh      YMD_OBJ;

    -- ??? TI?N ÁN ????????????????????????????????????????????????????????????????
    v_tong_tien_an      NUMBER := 0;

    -- án gi?m
    v_tong_an_giam      YMD_OBJ;
    v_con_lai_ymd       YMD_OBJ;

    -- ??? NG??NG TH?I GIAN CH?P HÀNH ?????????????????????????????????????????????
    v_tgch_loai         NVARCHAR2(500);
    v_nguong_db_text    NVARCHAR2(100);
    v_nguong_tt_text    NVARCHAR2(100);
    v_nguong_ap_dung    YMD_OBJ;
    v_nguong_text       NVARCHAR2(100);
    v_is_dac_biet       NUMBER := 0;
    v_du_tgch           NUMBER := 0;

    -- ??? ?I?U KI?N ??T ??????????????????????????????????????????????????????????
    v_so_lan_giam       NUMBER := 0;
    v_ngay_xet_gan_nhat DATE;
    v_con_lai_text      NVARCHAR2(500);
    v_con_lai_ngay      NUMBER := 0;
    v_khoang_cach_thang NUMBER := 0;
    v_so_lan_trong_nam  NUMBER := 0;
    v_nam_xet           NUMBER;
    v_dk_thoi_gian      NVARCHAR2(200);

    -- ??? QUÝ X?P LO?I ???????????????????????????????????????????????????????????
    v_yc                SO_QUY_YEU_CAU_OBJ;
    v_so_quy_thuc_te    NUMBER := 0;
    v_lien_ke_thuc_te   NUMBER := 0;
    v_tong_thuc_te      NUMBER := 0;
    v_he_so_tren3       NUMBER := 0;
    v_he_so_duoi3       NUMBER := 0;
    v_he_so_cc          NUMBER := 0;
    v_he_so_kl          NUMBER := 0;
    v_he_so_db_tren10   NUMBER := 0;
    v_he_so_db_duoi10   NUMBER := 0;
    v_rang_buoc_lien_ke NUMBER := 0;
    v_du_rang_buoc      NUMBER := 1;
    v_du_khung_chinh    NUMBER := 0;
    v_ly_do_dat         NVARCHAR2(500);
    v_co_canh_cao       NUMBER := 0;
    v_co_canh_cao_4quy  NUMBER := 0;
    v_co_khien_trach    NUMBER := 0;
    v_co_khien_trach_4quy NUMBER := 0;
    v_co_giam_buong     NUMBER := 0;
    v_muc_an_text       NVARCHAR2(255);
    v_cong_them_tien_an NUMBER := 0;
    v_dk_xlct           NVARCHAR2(200);
    v_du_quy            NUMBER := 0;

    -- ??? K?T LU?N ???????????????????????????????????????????????????????????????
    v_du_dk_dot         NUMBER := 0;

    -- ??? HELPER ?????????????????????????????????????????????????????????????????
    PROCEDURE PRINT(p_text IN VARCHAR2) IS
    BEGIN
        DBMS_OUTPUT.PUT_LINE(p_text);
    END;

    PROCEDURE SECTION(p_title IN VARCHAR2) IS
    BEGIN
        DBMS_OUTPUT.PUT_LINE('');
        DBMS_OUTPUT.PUT_LINE('??????????????????????????????????????????????????????????');
        DBMS_OUTPUT.PUT_LINE('  ' || p_title);
        DBMS_OUTPUT.PUT_LINE('??????????????????????????????????????????????????????????');
    END;

    FUNCTION YMD_TEXT(p_ymd IN YMD_OBJ) RETURN VARCHAR2 IS
    BEGIN
        IF p_ymd IS NULL THEN RETURN '0 n?m 0 tháng 0 ngày'; END IF;
        RETURN NVL(p_ymd.nam,0)   || ' n?m '
            || NVL(p_ymd.thang,0) || ' tháng '
            || NVL(p_ymd.ngay,0)  || ' ngày';
    END;

BEGIN
    DBMS_OUTPUT.ENABLE(1000000);

    PRINT('????????????????????????????????????????????????????????????');
    PRINT('?       DEBUG ?I?U KI?N GI?M TH?I H?N CH?P HÀNH           ?');
    PRINT('????????????????????????????????????????????????????????????');

    -- ??????????????????????????????????????????????????????????????????????????????
    -- [1] THÔNG TIN PH?M NHÂN & K? GI?M
    -- ??????????????????????????????????????????????????????????????????????????????
    SECTION('[1] THÔNG TIN PH?M NHÂN & K? GI?M');

    BEGIN
        SELECT ll.LL_HO_TEN, dttph.TTPN_TEN
          INTO v_ho_ten, v_tinh_trang
          FROM PN_LAI_LICHS ll
          JOIN DM_TINH_TRANG_PHAM_NHANS dttph ON ll.LL_TINH_TRANG_ID = dttph.ID
         WHERE ll.ID = p_pham_nhan_id
           AND  dttph.TTPN_MA IN ('111','112','113','114')
           AND NVL(ll.IS_DELETED, 0) = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            PRINT('  [L?I] Không tìm th?y ph?m nhân ID: ' || p_pham_nhan_id);
            RETURN;
    END;

    BEGIN
        SELECT dk.ID,
               CAST(kg.KGTH_NGAY_XET_GIAM AS DATE),
               kg.KGTH_TEN_KY
          INTO v_dieu_kien_id, v_ngay_xet, v_ten_ky
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS dk
          JOIN GTH_KY_GIAM_THOI_HANS kg ON kg.ID = p_ky_giam_id
         WHERE dk.GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
           AND dk.IS_DELETED = 0
           AND kg.IS_DELETED = 0
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            PRINT('  [L?I] Không tìm th?y k? gi?m ID: ' || p_ky_giam_id);
            RETURN;
    END;

    v_nam_xet     := EXTRACT(YEAR FROM v_ngay_xet);
    v_is_dac_biet := FN_IS_TRUONG_HOP_DAC_BIET(p_pham_nhan_id, p_ky_giam_id);

    PRINT('  Ph?m nhân ID  : ' || p_pham_nhan_id);
    PRINT('  H? tên        : ' || v_ho_ten);
    PRINT('  Tình tr?ng    : ' || v_tinh_trang);
    PRINT('  K? gi?m ID   : ' || p_ky_giam_id || ' - ' || v_ten_ky);
    PRINT('  ?i?u ki?n ID  : ' || v_dieu_kien_id);
    PRINT('  Ngày xét      : ' || TO_CHAR(v_ngay_xet, 'DD/MM/YYYY'));
    PRINT('  TH ??c bi?t   : ' || CASE v_is_dac_biet WHEN 1 THEN '? CÓ' ELSE '? KHÔNG' END);

    -- ??????????????????????????????????????????????????????????????????????????????
    -- [2] ÁN PH?T & TH?I GIAN CH?P HÀNH
    -- ??????????????????????????????????????????????????????????????????????????????
    SECTION('[2] ÁN PH?T & TH?I GIAN CH?P HÀNH');

    BEGIN
        SELECT THA_AN_PHAT,
               THA_NGAY_BAT,
               THA_NGAY_HET_HAN,
               THA_THOI_GIAN_TAM_GIAM,
               THA_THOI_GIAN_TAM_GIU
          INTO v_an_phat, v_ngay_bat, v_ngay_het_han,
               v_tam_giam_text, v_tam_giu_text
          FROM PN_THI_HANH_AN
         WHERE THA_PNLAI_LICH_ID = p_pham_nhan_id
           AND NVL(IS_DELETED, 0) = 0
           AND ROWNUM = 1;

        v_tong_ngay_an  := FN_PARSE_AN_PHAT_TO_NGAY(v_an_phat);
        v_tam_giam_ngay := FN_PARSE_AN_PHAT_TO_NGAY(v_tam_giam_text);
        v_tam_giu_ngay  := FN_PARSE_AN_PHAT_TO_NGAY(v_tam_giu_text);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            PRINT('  [!] Không có thông tin thi hành án');
    END;

    v_da_chap_hanh := FN_GET_DA_CHAP_HANH_THEO_NGAY(p_pham_nhan_id, v_ngay_xet);

    PRINT('  Án ph?t       : ' || NVL(v_an_phat, 'Không có'));
    PRINT('  T?ng ngày án  : ' || v_tong_ngay_an
        || CASE
               WHEN v_tong_ngay_an = -1 THEN ' (Chung thân)'
               WHEN v_tong_ngay_an >  0 THEN ' (~' || ROUND(v_tong_ngay_an / 365, 1) || ' n?m)'
               ELSE ''
           END);
    PRINT('  Ngày b?t      : ' || TO_CHAR(v_ngay_bat,     'DD/MM/YYYY'));
    PRINT('  Ngày h?t h?n  : ' || TO_CHAR(v_ngay_het_han, 'DD/MM/YYYY'));
    PRINT('  T?m giam      : ' || NVL(v_tam_giam_text, 'Không có') || '  (' || v_tam_giam_ngay || ' ngày)');
    PRINT('  T?m gi?       : ' || NVL(v_tam_giu_text,  'Không có') || '  (' || v_tam_giu_ngay  || ' ngày)');
    PRINT('  ?ã ch?p hành  : ' || YMD_TEXT(v_da_chap_hanh));

    -- L?y ng??ng TGCH qua FN_GET_NGUONG_TGCH
    v_nguong_text_ap_dung := FN_GET_NGUONG_TGCH(
        p_pham_nhan_id, p_ky_giam_id, v_is_dac_biet, v_an_phat
    );
    v_nguong_ap_dung := FN_PARSE_NGUONG(v_an_phat, v_nguong_text_ap_dung);
    v_nguong_text    := v_nguong_text_ap_dung;

    -- Ki?m tra có ph?m t?i m?i không (?? hi?n th?)
    SELECT COUNT(*) INTO v_co_pham_toi_moi
      FROM PHAM_TOI_MOIS ptm
     WHERE ptm.PHAM_NHAN_ID = p_pham_nhan_id
       AND NVL(ptm.IS_DELETED, 0) = 0;

    v_du_tgch := FN_YMD_GTE(v_da_chap_hanh, v_nguong_ap_dung);

    -- L?y thêm ng??ng TT và ?B ?? in ra so sánh
    BEGIN
        SELECT TGCH_TRUONG_HOP_DAC_BIET,
               TGCH_DOI_TUONG_THONG_THUONG
          INTO v_nguong_db_text, v_nguong_tt_text
          FROM GTH_THOI_GIAN_CHAP_HANHS
         WHERE GTH_DIEU_KIEN_GIAM_THOI_HAN_ID = v_dieu_kien_id
           AND IS_DELETED = 0
           AND (   (TGCH_LOAI_DOI_TUONG LIKE '%th?i h?n%' AND v_tong_ngay_an >  0)
                OR (TGCH_LOAI_DOI_TUONG LIKE '%Chung th%'  AND v_tong_ngay_an = -1))
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN NULL;
    END;

    PRINT('  Lo?i ??i t??ng: ' || NVL(v_tgch_loai, 'Không xác ??nh'));
    PRINT('  Ng??ng TT     : ' || NVL(v_nguong_tt_text, '?')
        || '  = ' || YMD_TEXT(FN_PARSE_NGUONG(v_an_phat, v_nguong_tt_text)));
    PRINT('  Ng??ng ?B     : ' || NVL(v_nguong_db_text, '?')
        || '  = ' || YMD_TEXT(FN_PARSE_NGUONG(v_an_phat, v_nguong_db_text)));

    -- In thêm ng??ng ph?m t?i m?i n?u có
    IF v_so_lan_giam > 0 AND v_co_pham_toi_moi > 0 THEN
        DECLARE
            v_nguong_ptm_it  NVARCHAR2(100);
            v_nguong_ptm     NVARCHAR2(100);
            v_muc_do_nt      NVARCHAR2(200);
        BEGIN
            SELECT TGCH_DA_GIAM_PHAM_TOI_MOI_IT_NT,
                   TGCH_DA_GIAM_PHAM_TOI_MOI
              INTO v_nguong_ptm_it, v_nguong_ptm
              FROM GTH_THOI_GIAN_CHAP_HANHS
             WHERE GTH_DIEU_KIEN_GIAM_THOI_HAN_ID = v_dieu_kien_id
               AND IS_DELETED = 0
               AND (   (TGCH_LOAI_DOI_TUONG LIKE '%th?i h?n%' AND v_tong_ngay_an >  0)
                    OR (TGCH_LOAI_DOI_TUONG LIKE '%Chung th%'  AND v_tong_ngay_an = -1))
               AND ROWNUM = 1;

            SELECT MAX(ptm.MUC_DO_NGHIEM_TRONG)
              INTO v_muc_do_nt
              FROM PHAM_TOI_MOIS ptm
             WHERE ptm.PHAM_NHAN_ID = p_pham_nhan_id
               AND NVL(ptm.IS_DELETED, 0) = 0;

            PRINT('  ?? Ph?m t?i m?i (' || v_co_pham_toi_moi || ' t?i) ?????????????????????????');
            PRINT('  M?c ?? NT     : ' || NVL(v_muc_do_nt, 'Không xác ??nh'));
            PRINT('  Ng??ng ít NT  : ' || NVL(v_nguong_ptm_it, '?')
                || '  = ' || YMD_TEXT(FN_PARSE_NGUONG(v_an_phat, v_nguong_ptm_it)));
            PRINT('  Ng??ng NT+    : ' || NVL(v_nguong_ptm, '?')
                || '  = ' || YMD_TEXT(FN_PARSE_NGUONG(v_an_phat, v_nguong_ptm)));
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
        END;
    END IF;

    PRINT('  Ng??ng áp d?ng: ' || NVL(v_nguong_text, '?')
        || CASE
               WHEN v_so_lan_giam > 0 AND v_co_pham_toi_moi > 0
                   THEN ' (?ã gi?m + ph?m t?i m?i)'
               WHEN v_is_dac_biet = 1
                   THEN ' (??c bi?t)'
               ELSE ' (thông th??ng)'
           END
        || '  = ' || YMD_TEXT(v_nguong_ap_dung));
    PRINT('  ?ã CH / Ng??ng: ' || YMD_TEXT(v_da_chap_hanh)
        || '  /  ' || YMD_TEXT(v_nguong_ap_dung)
        || CASE v_du_tgch WHEN 1 THEN '   ? ??T' ELSE '   ? CH?A ??T' END);
    v_tong_an_giam := FN_TINH_TONG_AN_GIAM(p_pham_nhan_id);
    v_con_lai_ymd  := FN_TINH_CON_LAI(v_an_phat, v_tong_an_giam, v_da_chap_hanh);

    PRINT('  T?ng án gi?m  : ' || YMD_TEXT(v_tong_an_giam));
    PRINT('  Còn l?i       : ' || YMD_TEXT(v_con_lai_ymd)
        || '  (= ' || v_an_phat
        || ' - gi?m ' || YMD_TEXT(v_tong_an_giam)
        || ' - CH '   || YMD_TEXT(v_da_chap_hanh) || ')');

    -- ??????????????????????????????????????????????????????????????????????????????
    -- [3] TI?N ÁN
    -- ??????????????????????????????????????????????????????????????????????????????
    SECTION('[3] TI?N ÁN');

    BEGIN
        SELECT NVL(pll.LL_SO_TIEN_AN, 0)
          INTO v_tong_tien_an
          FROM PN_LAI_LICHS pll
         WHERE pll.ID = p_pham_nhan_id
           AND NVL(IS_DELETED, 0) = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN v_tong_tien_an := 0;
    END;

    BEGIN
        SELECT NVL(DKGTH_HE_SO_AN_TREN3_NAM, 0),
               NVL(DKGTH_HE_SO_AN_DUOI3_NAM, 0)
          INTO v_he_so_tren3, v_he_so_duoi3
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS
         WHERE ID = v_dieu_kien_id
           AND IS_DELETED = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN NULL;
    END;

    IF v_tong_ngay_an > 0 AND v_tong_ngay_an < 3 * 365 THEN
        v_cong_them_tien_an := v_tong_tien_an * v_he_so_duoi3;
        PRINT('  Án ph?t < 3 n?m  ? dùng h? s? duoi3');
    ELSIF v_tong_ngay_an >= 3 * 365 OR v_tong_ngay_an = -1 THEN
        v_cong_them_tien_an := v_tong_tien_an * v_he_so_tren3;
        PRINT('  Án ph?t >= 3 n?m / Chung thân  ? dùng h? s? tren3');
    END IF;

    PRINT('  T?ng ti?n án  : ' || v_tong_tien_an || ' b?n án');
    PRINT('  H? s? < 3 n?m : ' || v_he_so_duoi3);
    PRINT('  H? s? >= 3 n?m: ' || v_he_so_tren3);
    PRINT('  C?ng thêm quý : ' || v_tong_tien_an
        || ' × '
        || CASE WHEN v_tong_ngay_an < 3 * 365 AND v_tong_ngay_an > 0
                THEN v_he_so_duoi3 ELSE v_he_so_tren3 END
        || ' = ' || v_cong_them_tien_an || ' quý');

    -- ??????????????????????????????????????????????????????????????????????????????
    -- [4] L?CH S? GI?M ÁN
    -- ??????????????????????????????????????????????????????????????????????????????
    SECTION('[4] L?CH S? GI?M ÁN');

    SELECT COUNT(*)
      INTO v_so_lan_giam
      FROM GIAM_THOI_HANS
     WHERE PHAM_NHAN_ID = p_pham_nhan_id
       AND IS_DELETED = 0;

    PRINT('  T?ng l?n gi?m : ' || v_so_lan_giam);

    IF v_so_lan_giam > 0 THEN
        SELECT NGAY_XET, CON_LAI
          INTO v_ngay_xet_gan_nhat, v_con_lai_text
          FROM (
              SELECT NGAY_XET, CON_LAI
                FROM GIAM_THOI_HANS
               WHERE PHAM_NHAN_ID = p_pham_nhan_id
                 AND IS_DELETED = 0
               ORDER BY NGAY_XET DESC
          )
         WHERE ROWNUM = 1;

        SELECT COUNT(*)
          INTO v_so_lan_trong_nam
          FROM GIAM_THOI_HANS
         WHERE PHAM_NHAN_ID = p_pham_nhan_id
           AND IS_DELETED = 0
           AND EXTRACT(YEAR FROM NGAY_XET) = v_nam_xet;

        v_khoang_cach_thang := MONTHS_BETWEEN(v_ngay_xet, v_ngay_xet_gan_nhat);
        v_con_lai_ngay      := FN_PARSE_AN_PHAT_TO_NGAY(v_con_lai_text);

        PRINT('  L?n g?n nh?t  : ' || TO_CHAR(v_ngay_xet_gan_nhat, 'DD/MM/YYYY'));
        PRINT('  Còn l?i (DB)  : ' || NVL(v_con_lai_text, 'Không có'));
        -- ? Dùng YMD tính toán thay vì parse DB
        PRINT('  Còn l?i (tính): ' || YMD_TEXT(v_con_lai_ymd));
        PRINT('  Kho?ng cách   : ' || ROUND(v_khoang_cach_thang, 1) || ' tháng');
        PRINT('  L?n gi?m n?m ' || v_nam_xet || ': ' || v_so_lan_trong_nam);
    ELSE
        PRINT('  ? Ch?a có l?n gi?m nào');
        PRINT('  Còn l?i       : ' || YMD_TEXT(v_con_lai_ymd));
    END IF;

    -- ??????????????????????????????????????????????????????????????????????????????
    -- [5] ?I?U KI?N QUÝ X?P LO?I
    -- ??????????????????????????????????????????????????????????????????????????????
    SECTION('[5] ?I?U KI?N QUÝ X?P LO?I');

    BEGIN
        SELECT
            CASE
                WHEN COUNT(CASE WHEN THA_MUC_AN_ID = 2         THEN 1 END) > 0 THEN u'\00c1n t\00f9 20 - 30 n\0103m'
                WHEN COUNT(CASE WHEN THA_MUC_AN_ID = 1         THEN 1 END) > 0 THEN u'\00c1n t\00f9 15 - 20 n\0103m'
                WHEN COUNT(CASE WHEN THA_MUC_AN_ID = 12        THEN 1 END) > 0 THEN u'\00c1n t\00f9 10 - 15 n\0103m'
                WHEN COUNT(CASE WHEN THA_MUC_AN_ID IN (10, 13) THEN 1 END) > 0 THEN u'\00c1n t\00f9 5 - 10 n\0103m'
                WHEN COUNT(CASE WHEN THA_MUC_AN_ID = 11        THEN 1 END) > 0 THEN u'\00c1n t\00f9 3 - 5 n\0103m'
                WHEN COUNT(CASE WHEN THA_MUC_AN_ID = 6         THEN 1 END) > 0 THEN u'Chung th\00e2n'
                WHEN COUNT(CASE WHEN THA_MUC_AN_ID = 15        THEN 1 END) > 0 THEN u'\00c1n d\01b0\1edbi 3 n\0103m'
                ELSE NULL
            END
          INTO v_muc_an_text
          FROM PN_THI_HANH_AN
         WHERE THA_PNLAI_LICH_ID = p_pham_nhan_id
           AND NVL(IS_DELETED, 0) = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN NULL;
    END;

    -- 6. ??m k? lu?t theo kho?ng th?i gian
    -- C?nh cáo trong 4 quý (~12 tháng)
    SELECT COUNT(*) INTO v_co_canh_cao_4quy
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%C%NH C%O%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH <  v_ngay_xet;

    -- Khi?n trách trong 4 quý
    SELECT COUNT(*) INTO v_co_khien_trach_4quy
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%KHI%N TR%CH%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH <  v_ngay_xet;

    -- Giam bu?ng trong 1 n?m
    SELECT COUNT(*) INTO v_co_giam_buong
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%GIAM BU%NG%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH <  v_ngay_xet;

    -- Gán bi?n t?ng ?? dùng cho ràng bu?c
    v_co_canh_cao    := v_co_canh_cao_4quy;
    v_co_khien_trach := v_co_khien_trach_4quy;

    BEGIN
        SELECT NVL(DKGTH_TH_TAI_PHAM_CANH_CAO,      0),
               NVL(DKGTH_TH_TAI_PHAM_KY_LUAT,       0),
               NVL(DKGTH_TH_DAC_BIET_AN_TREN10_NAM, 0),
               NVL(DKGTH_TH_DAC_BIET_AN_DUOI10_NAM, 0)
          INTO v_he_so_cc, v_he_so_kl, v_he_so_db_tren10, v_he_so_db_duoi10
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS
         WHERE ID = v_dieu_kien_id
           AND IS_DELETED = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN NULL;
    END;

    v_yc              := FN_TINH_SO_QUY_YEU_CAU(p_pham_nhan_id, p_ky_giam_id);
    v_lien_ke_thuc_te := QLPN.FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC_LIEN_KE(p_pham_nhan_id, v_ngay_xet);
    v_tong_thuc_te    := FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT(p_pham_nhan_id, NULL).so_quy;
    v_du_quy          := FN_XET_DU_DIEU_KIEN_QUY(p_pham_nhan_id, p_ky_giam_id);

    PRINT('  M?c án (ti?n án): ' || NVL(v_muc_an_text, 'Không có'));
    PRINT('');
    PRINT('  ?? S? quý th?c t? ??????????????????????????????????????');
    PRINT('  T?ng Khá/T?t    : ' || v_tong_thuc_te    || ' quý');
    PRINT('  Li?n k? hi?n t?i: ' || v_lien_ke_thuc_te || ' quý');
    PRINT('');
    PRINT('  ?? S? quý yêu c?u  (base + ti?n án ' || v_cong_them_tien_an || ' quý) ????');
    PRINT('  YC liên t?c     : ' || TO_CHAR(v_yc.SO_QUY_LIEN_TUC+v_cong_them_tien_an));
    PRINT('  YC không LT     : ' || TO_CHAR(v_yc.SO_QUY_KHONG_LIEN_TUC+v_cong_them_tien_an));
    PRINT('  YC li?n k?      : ' || TO_CHAR(v_yc.SO_QUY_LIEN_KE_YC));
    PRINT('  YC TH ??c bi?t  : ' || TO_CHAR(v_yc.SO_QUY_TRUONG_HOP_DB+v_cong_them_tien_an));
    PRINT('');
    PRINT('  ?? K? lu?t & ràng bu?c ?????????????????????????????????');
    PRINT('  C?nh cáo (4 quý): ' || v_co_canh_cao_4quy
        || CASE WHEN v_co_canh_cao_4quy > 1 THEN '  ? VI PH?M NG??NG (>1 l?n)' ELSE '' END);
    PRINT('  Khi?n trách (4q): ' || v_co_khien_trach_4quy
        || CASE WHEN v_co_khien_trach_4quy > 2 THEN '  ? VI PH?M NG??NG (>2 l?n)' ELSE '' END);
    PRINT('  C?nh cáo/KT áp d?ng: '
        || CASE WHEN (v_co_canh_cao > 0 OR v_co_khien_trach > 1)
                THEN '? CÓ  (h? s? cc=' || v_he_so_cc || ')'
                ELSE '? KHÔNG' END);
    PRINT('  Giam bu?ng KL (1 n?m): '
        || v_co_giam_buong
        || CASE WHEN v_co_giam_buong > 0 THEN '  ? CÓ  (h? s? kl=' || v_he_so_kl || ')' ELSE '  ? KHÔNG' END);

    IF v_is_dac_biet = 1 THEN
        PRINT('  HS ?B tren10   : ' || v_he_so_db_tren10 || '   |   HS ?B duoi10: ' || v_he_so_db_duoi10);
    END IF;

    -- Ki?m tra rule lo?i s?m: > 1 CC ho?c > 2 KT trong 4 quý
    IF v_co_canh_cao_4quy > 1 OR v_co_khien_trach_4quy > 2 THEN
        PRINT('');
        PRINT('  ? LO?I S?M: CC trong 4 quý=' || v_co_canh_cao_4quy
            || '  KT trong 4 quý=' || v_co_khien_trach_4quy
            || '  ? Không ?? ?K x?p lo?i');
        v_du_rang_buoc  := 0;
        v_du_khung_chinh := 0;
        -- B? qua các b??c xét khung chính, nh?y th?ng ??n k?t lu?n
        GOTO ket_luan;
    END IF;

    -- Tính ràng bu?c li?n k?
    IF v_so_lan_giam > 0 THEN
        IF    v_co_canh_cao > 0 AND v_co_giam_buong > 0 THEN
            v_rang_buoc_lien_ke := GREATEST(v_he_so_cc, v_he_so_kl);
        ELSIF v_co_canh_cao  > 0 THEN
            v_rang_buoc_lien_ke := v_he_so_cc;
        ELSIF v_co_giam_buong > 0 THEN
            v_rang_buoc_lien_ke := v_he_so_kl;
        END IF;
    END IF;

    IF v_is_dac_biet = 1 THEN
        IF v_tong_ngay_an >= 10 * 365 THEN
            v_rang_buoc_lien_ke := GREATEST(v_rang_buoc_lien_ke, v_he_so_db_tren10);
        ELSE
            v_rang_buoc_lien_ke := GREATEST(v_rang_buoc_lien_ke, v_he_so_db_duoi10);
        END IF;
    END IF;

    IF v_rang_buoc_lien_ke > 0 AND v_lien_ke_thuc_te < v_rang_buoc_lien_ke THEN
        v_du_rang_buoc := 0;
    END IF;

    PRINT('  Ràng bu?c LK   : '
        || CASE WHEN v_rang_buoc_lien_ke > 0 THEN '>= ' || v_rang_buoc_lien_ke ELSE 'Không có' END);
    PRINT('  Ràng bu?c      : '
        || CASE v_du_rang_buoc WHEN 1 THEN '? ??T' ELSE '? CH?A ??T' END);

    -- Xét khung chính
    IF v_du_rang_buoc = 1 THEN
        PRINT('');
        PRINT('  ?? Xét khung chính ?????????????????????????????????????');

-- Khung 1: Liên t?c
        PRINT('  --- X?p lo?i liên t?c');
        PRINT('      C?u hình YC        : ' || v_yc.SO_QUY_LIEN_TUC || ' quý');
        PRINT('      Liên t?c th?c t?   : ' || v_lien_ke_thuc_te     || ' quý');
        PRINT('      K?t qu?            : ' ||
            CASE WHEN v_lien_ke_thuc_te >= v_yc.SO_QUY_LIEN_TUC
                 THEN '? ??t x?p lo?i liên t?c'
                 ELSE '? Không ??t x?p lo?i liên t?c'
            END);

        IF v_lien_ke_thuc_te >= v_yc.SO_QUY_LIEN_TUC THEN
            v_du_khung_chinh := 1;
            v_ly_do_dat      := 'Li?n k? (' || v_lien_ke_thuc_te
                              || ') >= YC liên t?c (' || v_yc.SO_QUY_LIEN_TUC || ')';
        END IF;

        -- Khung 2: Không liên t?c
        IF v_du_khung_chinh = 0 THEN
            PRINT('');
            PRINT('  --- X?p lo?i không liên t?c');
            PRINT('      C?u hình YC t?ng   : ' || v_yc.SO_QUY_KHONG_LIEN_TUC || ' quý');
            PRINT('      T?ng th?c t?       : ' || v_tong_thuc_te              || ' quý');
            PRINT('      C?u hình YC li?n k?: ' || v_yc.SO_QUY_LIEN_KE_YC     || ' quý');
            PRINT('      Li?n k? th?c t?    : ' || v_lien_ke_thuc_te           || ' quý');
            PRINT('      K?t qu?            : ' ||
                CASE
                    WHEN v_yc.SO_QUY_KHONG_LIEN_TUC > 0
                     AND v_tong_thuc_te    >= v_yc.SO_QUY_KHONG_LIEN_TUC
                     AND v_lien_ke_thuc_te >= v_yc.SO_QUY_LIEN_KE_YC
                    THEN '? ??t x?p lo?i không liên t?c'
                    ELSE '? Không ??t x?p lo?i không liên t?c'
                END);

            IF v_yc.SO_QUY_KHONG_LIEN_TUC > 0
             AND v_tong_thuc_te    >= v_yc.SO_QUY_KHONG_LIEN_TUC
             AND v_lien_ke_thuc_te >= v_yc.SO_QUY_LIEN_KE_YC
            THEN
                v_du_khung_chinh := 1;
                v_ly_do_dat      := 'T?ng (' || v_tong_thuc_te
                                  || ') >= KLT (' || v_yc.SO_QUY_KHONG_LIEN_TUC
                                  || ')  VÀ  LK (' || v_lien_ke_thuc_te
                                  || ') >= LK_YC (' || v_yc.SO_QUY_LIEN_KE_YC || ')';
            END IF;
        END IF;

        -- Khung 3: ??c bi?t
        IF v_du_khung_chinh = 0 AND v_is_dac_biet = 1 THEN
            PRINT('');
            PRINT('  --- X?p lo?i ??c bi?t');
            PRINT('      C?u hình YC        : ' || v_yc.SO_QUY_TRUONG_HOP_DB || ' quý');
            PRINT('      Li?n k? th?c t?    : ' || v_lien_ke_thuc_te          || ' quý');
            PRINT('      K?t qu?            : ' ||
                CASE
                    WHEN v_lien_ke_thuc_te >= v_yc.SO_QUY_TRUONG_HOP_DB
                    THEN '? ??t x?p lo?i ??c bi?t'
                    ELSE '? Không ??t x?p lo?i ??c bi?t'
                END);

            IF v_lien_ke_thuc_te >= v_yc.SO_QUY_TRUONG_HOP_DB THEN
                v_du_khung_chinh := 1;
                v_ly_do_dat      := 'TH ??c bi?t: LK (' || v_lien_ke_thuc_te
                                  || ') >= YC ?B (' || v_yc.SO_QUY_TRUONG_HOP_DB || ')';
            END IF;
        END IF;

	    v_dk_xlct := FN_DIEU_KIEN_XLCT(p_pham_nhan_id, p_ky_giam_id, v_is_dac_biet);
	    PRINT('  K?t qu? XLCT   : ' || v_dk_xlct);
        PRINT('  Khung chính    : '
            || CASE v_du_khung_chinh
                   WHEN 1 THEN '? ??T  - ' || v_ly_do_dat
                   ELSE        '? CH?A ??T'
               END);
    	END IF;

    <<ket_luan>>
     -- ??????????????????????????????????????????????????????????????????????????????
    -- [5.5] ?I?U KI?N HÌNH PH?T B? SUNG
    -- ??????????????????????????????????????????????????????????????????????????????
        SECTION('[5.5] ?I?U KI?N HÌNH PH?T B? SUNG');

            DECLARE
                v_hpbs_1phan    NUMBER := 0;
                v_nguong_text   NVARCHAR2(255);
                v_tong_tien     NUMBER := 0;
                v_da_dong       NUMBER := 0;
                v_con_lai       NUMBER := 0;
                v_nguong_tien   NUMBER := 0;
                v_du_hpbs       NUMBER := 0;
                v_tu            NUMBER;
                v_mau           NUMBER;
            BEGIN
                -- L?y c?u hình
                BEGIN
                    SELECT NVL(HPBS_BOI_THUONG1PHAN_NVDS, 0),
                        HPBS_BOI_THUONG_DAN_SU
                    INTO v_hpbs_1phan, v_nguong_text
                    FROM GTH_HINH_PHAT_BO_SUNGS
                    WHERE GTH_DIEU_KIEN_GIAM_THOI_HAN_ID = v_dieu_kien_id
                    AND IS_DELETED = 0
                    AND ROWNUM = 1;
                    PRINT('  C?u hình 1 ph?n  : ' || CASE v_hpbs_1phan WHEN 1 THEN '? Ch? c?n ?óng 1 ph?n' ELSE '? Ph?i ?óng theo t? l?' END);
                    PRINT('  T? l? yêu c?u   : ' || NVL(v_nguong_text, 'Không có'));
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        PRINT('  [!] Không có c?u hình HPBS ? m?c ??nh ??t');
                        v_du_hpbs := 1;
                        GOTO end_hpbs;
                END;

                -- L?y t?ng ti?n
				SELECT 
				    NVL(SUM(NVL(phpbs.HPBS_TONG_TIEN_PHAT,    0)), 0),
				    NVL(SUM(NVL(phpbs.HPBS_TONG_TIEN_PHAT,    0)), 0)
				  - NVL(SUM(NVL(phpbs.HPBS_TONG_TIEN_CON_LAI, 0)), 0),
				    NVL(SUM(NVL(phpbs.HPBS_TONG_TIEN_CON_LAI, 0)), 0)
				INTO v_tong_tien, v_da_dong, v_con_lai
				FROM PN_HINH_PHAT_BO_SUNGS phpbs
				WHERE phpbs.HPBS_MA_PHAM_NHAN = p_pham_nhan_id
				  AND NVL(phpbs.IS_DELETED, 0) = 0;

                PRINT('  T?ng ti?n        : ' || v_tong_tien);
                PRINT('  ?ã ?óng          : ' || v_da_dong);
                PRINT('  Còn l?i          : ' || v_con_lai);

                IF v_tong_tien = 0 THEN
                    PRINT('  [!] Không có ti?n HPBS ? m?c ??nh ??t');
                    v_du_hpbs := 1;
                    GOTO end_hpbs;
                END IF;

                -- Xét rule
                IF v_hpbs_1phan = 1 THEN
                    v_du_hpbs := CASE WHEN v_da_dong > 0 THEN 1 ELSE 0 END;
                    PRINT('  Rule             : Ch? c?n ?óng 1 ph?n');
                    PRINT('  K?t qu?          : '
                        || CASE v_du_hpbs WHEN 1 THEN '? ??T (?ã ?óng ' || v_da_dong || ')' ELSE '? CH?A ??T (ch?a ?óng ??ng nào)' END);
                ELSIF v_nguong_text IS NOT NULL AND INSTR(v_nguong_text, '/') > 0 THEN
                    v_tu          := TO_NUMBER(TRIM(SUBSTR(v_nguong_text, 1, INSTR(v_nguong_text, '/') - 1)));
                    v_mau         := TO_NUMBER(TRIM(SUBSTR(v_nguong_text, INSTR(v_nguong_text, '/') + 1)));
                    v_nguong_tien := CEIL((v_tong_tien * v_tu) / v_mau);
                    v_du_hpbs     := CASE WHEN v_da_dong >= v_nguong_tien THEN 1 ELSE 0 END;
                    PRINT('  Rule             : ?óng >= ' || v_nguong_text || ' t?ng ti?n');
                    PRINT('  Ng??ng tính ra   : ' || v_nguong_tien);
                    PRINT('  ?ã ?óng / Ng??ng : ' || v_da_dong || ' / ' || v_nguong_tien
                        || CASE v_du_hpbs WHEN 1 THEN '   ? ??T' ELSE '   ? CH?A ??T' END);
                ELSE
                    PRINT('  [!] Không xác ??nh ???c rule ? m?c ??nh ??t');
                    v_du_hpbs := 1;
                END IF;

                <<end_hpbs>>
                PRINT('  K?t qu? HPBS     : ' || CASE v_du_hpbs WHEN 1 THEN '? ??T' ELSE '? KHÔNG ??T' END);
            END;
    -- ??????????????????????????????????????????????????????????????????????????????
    -- [6] ?I?U KI?N TH?I GIAN (??T)
    -- ??????????????????????????????????????????????????????????????????????????????
    SECTION('[6] ?I?U KI?N TH?I GIAN (??T)');

    v_dk_thoi_gian := FN_DIEU_KIEN_THOI_GIAN(p_pham_nhan_id, v_ngay_xet, v_is_dac_biet);

    IF v_so_lan_giam = 0 THEN
        PRINT('  Ch?a gi?m l?n nào');
        PRINT('  ? Xét l?n ??u '
            || CASE v_is_dac_biet WHEN 1 THEN '(??c bi?t)' ELSE '(thông th??ng)' END);
    ELSE
        PRINT('  Kho?ng cách   : ' || ROUND(v_khoang_cach_thang, 1) || ' tháng'
            || CASE WHEN v_khoang_cach_thang >= 12 THEN '  ? >= 12 tháng' ELSE '  ? < 12 tháng' END);

        IF v_khoang_cach_thang < 12 THEN
            IF v_is_dac_biet = 1 THEN
                PRINT('  TH ??c bi?t - l?n/n?m ' || v_nam_xet || ': '
                    || v_so_lan_trong_nam || '/2'
                    || CASE WHEN v_so_lan_trong_nam < 2 THEN '  ? còn quota' ELSE '  ? h?t quota' END);
            ELSE
                PRINT('  CON_LAI < 365 ngày : '
                    || CASE WHEN v_con_lai_ngay < 365
                            THEN '? (' || v_con_lai_ngay || ' ngày)'
                            ELSE '? (' || v_con_lai_ngay || ' ngày)' END);
            END IF;
        END IF;
    END IF;

    PRINT('  K?t qu? ?K ??T : ' || v_dk_thoi_gian);
    -- v_dk_xlct  := FN_DIEU_KIEN_XLCT(p_pham_nhan_id, p_ky_giam_id, v_is_dac_biet);
    PRINT('  K?t qu? XLCT   : ' || v_dk_xlct);

    -- Tính v_du_dk_dot
    v_du_dk_dot := CASE
        WHEN v_du_tgch = 1
         AND v_dk_thoi_gian <> TO_NCHAR('Không ?? ?K v? th?i gian')
        THEN 1
        ELSE 0
    END;

    -- ??????????????????????????????????????????????????????????????????????????????
    -- [7] K?T LU?N T?NG H?P
    -- ??????????????????????????????????????????????????????????????????????????????
    SECTION('[7] K?T LU?N T?NG H?P');

    PRINT('  ??????????????????????????????????????????????????????????');
    PRINT('  ?  [1] ?I?U KI?N TH?I GIAN CH?P HÀNH');
    PRINT('  ?      K?t qu? : ' || CASE v_du_tgch WHEN 1 THEN '? ??T' ELSE '? KHÔNG ??T' END);
    PRINT('  ?      Chi ti?t: ' || YMD_TEXT(v_da_chap_hanh)
        || '  /  Ng??ng: ' || YMD_TEXT(v_nguong_ap_dung));
    PRINT('  ??????????????????????????????????????????????????????????');
    PRINT('  ?  [2] ?I?U KI?N ??T');
    PRINT('  ?      K?t qu? : ' || CASE v_du_dk_dot WHEN 1 THEN '? ??T' ELSE '? KHÔNG ??T' END);
    PRINT('  ?      Chi ti?t: ' || v_dk_thoi_gian);
    PRINT('  ??????????????????????????????????????????????????????????');
    PRINT('  ?  [3] ?I?U KI?N X?P LO?I QUÝ');
    PRINT('  ?      K?t qu? : ' || CASE v_du_quy WHEN 1 THEN '? ??T' ELSE '? KHÔNG ??T' END);
    PRINT('  ?      Chi ti?t: ' || v_dk_xlct);
    PRINT('  ??????????????????????????????????????????????????????????');

    DECLARE
            v_du_hpbs_ket NUMBER := FN_XET_DU_DIEU_KIEN_HPBS(p_pham_nhan_id, v_dieu_kien_id);
            v_tat_ca_dat  NUMBER :=
                CASE WHEN v_du_tgch    = 1
                    AND v_du_dk_dot  = 1
                    AND v_du_quy     = 1
                    AND v_du_hpbs_ket = 1
                    AND v_dk_xlct   <> TO_NCHAR('Không ?? ?K x?p lo?i')
                    THEN 1 ELSE 0 END;
        BEGIN
            PRINT('  ??????????????????????????????????????????????????????????');
            PRINT('  ?  [4] ?I?U KI?N HÌNH PH?T B? SUNG');
            PRINT('  ?      K?t qu? : ' || CASE v_du_hpbs_ket WHEN 1 THEN '? ??T' ELSE '? KHÔNG ??T' END);
            PRINT('  ??????????????????????????????????????????????????????????');
            PRINT('  ?  K?T QU? T?NG H?P : '
                || CASE v_tat_ca_dat WHEN 1 THEN '? ??T' ELSE '? KHÔNG ??T' END);
            IF v_tat_ca_dat = 0 THEN
                PRINT('  ?  Lý do            : ' ||
                    CASE
                        WHEN v_du_tgch    = 0 THEN 'Ch?a ?? TGCH'
                        WHEN v_du_dk_dot  = 0 THEN 'Không ?? ?K ??t: '   || v_dk_thoi_gian
                        WHEN v_du_quy     = 0 THEN 'Không ?? ?K x?p lo?i quý: ' || v_dk_xlct
                        WHEN v_du_hpbs_ket = 0 THEN 'Ch?a n?p ?? hình ph?t b? sung'
                        ELSE v_dk_xlct
                    END);
            END IF;
        END;

    PRINT('  ??????????????????????????????????????????????????????????');

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('[L?I] ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
END SP_DEBUG_DIEU_KIEN_GTH;







/
--------------------------------------------------------
--  DDL for Procedure SP_DEBUG_KY_XEP_LOAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_DEBUG_KY_XEP_LOAI" (
    p_pham_nhan_id IN NUMBER,
    p_ky_giam_id   IN NUMBER
)
AS
    -- ??? BI?N CHÍNH ????????????????????????????????????????????
    v_so_lan_giam      NUMBER := 0;
    v_ngay_giam_gan    DATE;
    v_ngay_xet         DATE;
    v_dieu_kien_id     NUMBER;

    v_lien_ke_thuc_te  NUMBER := 0;
    v_tong_thuc_te     NUMBER := 0;

    v_co_canh_cao      NUMBER := 0;
    v_co_khien_trach   NUMBER := 0;
    v_co_giam_buong    NUMBER := 0;
    v_tong_ngay_an     NUMBER := 0;
    v_so_quy_can_lay   NUMBER := 0;

    v_result           NVARCHAR2(4000) := '';
    v_nam_xl           NUMBER;

    -- ??? BI?N HI?N TH? ?????????????????????????????????????????
    v_ho_ten           NVARCHAR2(500);
    v_an_phat          NVARCHAR2(500);
    v_xl_ten           NVARCHAR2(100);
    v_dem_quy          NUMBER := 0;
    v_ten_ky           NVARCHAR2(50);

    -- ??? DEBUG ??????????????????????????????????????????????????
    PROCEDURE P(p_text IN VARCHAR2) IS
    BEGIN
        DBMS_OUTPUT.PUT_LINE(p_text);
    END;

    PROCEDURE HR IS
    BEGIN
        P('??????????????????????????????????????????????????????????');
    END;

BEGIN
    DBMS_OUTPUT.ENABLE(1000000);

    -- ?? [0] L?y ngày xét t? k? gi?m ??????????????????????????
    HR;
    P('  DEBUG KY XEP LOAI - Check lay danh sach quy xep loai');
    HR;

    BEGIN
        SELECT dk.ID, CAST(kg.KGTH_NGAY_XET_GIAM AS DATE)
          INTO v_dieu_kien_id, v_ngay_xet
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS dk
          JOIN GTH_KY_GIAM_THOI_HANS kg ON kg.ID = p_ky_giam_id
         WHERE dk.GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
           AND dk.IS_DELETED = 0
           AND kg.IS_DELETED = 0
           AND ROWNUM = 1;
        P('  [0] Dieukien ID   : ' || v_dieu_kien_id);
        P('  [0] Ngay xet     : ' || TO_CHAR(v_ngay_xet, 'DD/MM/YYYY'));
    EXCEPTION
        WHEN NO_DATA_FOUND THEN P('  [!] Khong tim thay ky giam ID: ' || p_ky_giam_id); RETURN;
        WHEN OTHERS THEN P('  [!] LOI lay ngay xet: ' || SQLERRM); RETURN;
    END;

    -- ?? [1] Thong tin pham nhan ????????????????????????????????
    P('');
    P('[1] PHAM NHAN');
    BEGIN
        SELECT LL_HO_TEN
          INTO v_ho_ten
          FROM PN_LAI_LICHS
         WHERE ID = p_pham_nhan_id
           AND NVL(IS_DELETED, 0) = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN P('  [!] Khong tim thay pham nhan ID: ' || p_pham_nhan_id); RETURN;
    END;
    P('  ID         : ' || p_pham_nhan_id);
    P('  Ho ten     : ' || v_ho_ten);
    P('  Ngay xet   : ' || TO_CHAR(v_ngay_xet, 'DD/MM/YYYY'));
    P('  Nam xet    : ' || EXTRACT(YEAR FROM v_ngay_xet));
    P('  Quy xet    : ' || CASE EXTRACT(MONTH FROM v_ngay_xet)
                              WHEN 1 THEN 1 WHEN 2 THEN 1 WHEN 3 THEN 1
                              WHEN 4 THEN 2 WHEN 5 THEN 2 WHEN 6 THEN 2
                              WHEN 7 THEN 3 WHEN 8 THEN 3 WHEN 9 THEN 3
                              WHEN 10 THEN 4 WHEN 11 THEN 4 WHEN 12 THEN 4
                          END);

    -- ?? [2] Da giam chua ???????????????????????????????????????
    P('');
    P('[2] DA GIAM');
    SELECT COUNT(*), MAX(CAST(NGAY_XET AS DATE))
      INTO v_so_lan_giam, v_ngay_giam_gan
      FROM GIAM_THOI_HANS
     WHERE PHAM_NHAN_ID = p_pham_nhan_id
       AND IS_DELETED = 0
       AND CAST(NGAY_XET AS DATE) < v_ngay_xet;
    P('  So lan giam   : ' || v_so_lan_giam);
    P('  Ngay giam gan  : ' || CASE WHEN v_ngay_giam_gan IS NULL THEN 'CHUA GIAM' ELSE TO_CHAR(v_ngay_giam_gan,'DD/MM/YYYY') END);

    -- ?? [3] An phat ?????????????????????????????????????????????
    P('');
    P('[3] AN PHAT');
    BEGIN
        SELECT THA_AN_PHAT
          INTO v_an_phat
          FROM PN_THI_HANH_AN
         WHERE THA_PNLAI_LICH_ID = p_pham_nhan_id
           AND NVL(IS_DELETED, 0) = 0
           AND ROWNUM = 1;
        v_tong_ngay_an := QLPN.FN_PARSE_AN_PHAT_TO_NGAY(v_an_phat);
        P('  An phat      : ' || NVL(v_an_phat,'NULL'));
        P('  Tong ngay an : ' || v_tong_ngay_an ||
            CASE WHEN v_tong_ngay_an = -1 THEN ' (CHUNG THAN)'
                 WHEN v_tong_ngay_an > 0 THEN ' (' || ROUND(v_tong_ngay_an/365,1) || ' nam)'
                 ELSE '' END);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_tong_ngay_an := 0;
            P('  [!] Khong co an phat');
    END;

    -- ?? [4] So quy thuc te ????????????????????????????????????????
    P('');
    P('[4] SO QUY THUC TE');
    v_lien_ke_thuc_te := QLPN.FN_TINH_SO_QUY_LIEN_KE_THEO_NGAY(p_pham_nhan_id, v_ngay_xet);
    P('  Lien ke thuc te : ' || v_lien_ke_thuc_te || ' quy');

    v_tong_thuc_te := QLPN.FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT(p_pham_nhan_id, NULL).SO_QUY;
    P('  Tong thuc te    : ' || v_tong_thuc_te || ' quy');

    -- ?? [5] Ky luat ?????????????????????????????????????????????
    P('');
    P('[5] KY LUAT (4 quy gan nhat)');
    SELECT COUNT(*) INTO v_co_canh_cao
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%C%NH C%O%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH < v_ngay_xet;
    P('  Canh cao    : ' || v_co_canh_cao);

    SELECT COUNT(*) INTO v_co_khien_trach
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%KHI%N TR%CH%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH < v_ngay_xet;
    P('  Khiên trách : ' || v_co_khien_trach);

    SELECT COUNT(*) INTO v_co_giam_buong
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%GIAM BU%NG%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH < v_ngay_xet;
    P('  Giam buong  : ' || v_co_giam_buong);

    IF v_co_canh_cao > 1 OR v_co_khien_trach > 2 THEN
        P('  => LOAI vi vuot nguong ky luat');
    END IF;

    -- ?? [6] Danh sach quy XEP_LOAIS ????????????????????????????
    P('');
    P('[6] BANG XEP_LOAIS (tat ca quy truoc ngay xet)');
    v_dem_quy := 0;
    FOR rec IN (
        SELECT xl.XEP_LOAI_NAM, q.quy,
            CASE q.quy
                WHEN 1 THEN xl.XEP_LOAI_QUY_I
                WHEN 2 THEN xl.XEP_LOAI_QUY_II
                WHEN 3 THEN xl.XEP_LOAI_QUY_III
                WHEN 4 THEN xl.XEP_LOAI_QUY_IV
            END AS xlct_id,
            CASE q.quy
                WHEN 1 THEN 'Q1' WHEN 2 THEN 'Q2' WHEN 3 THEN 'Q3' WHEN 4 THEN 'Q4'
            END AS ten_ky
          FROM XEP_LOAIS xl
          CROSS JOIN (
              SELECT 1 AS quy FROM DUAL UNION ALL
              SELECT 2 FROM DUAL UNION ALL
              SELECT 3 FROM DUAL UNION ALL
              SELECT 4 FROM DUAL
          ) q
         WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id
           AND NVL(xl.IS_DELETED, 0) = 0
           AND (   xl.XEP_LOAI_NAM < EXTRACT(YEAR FROM v_ngay_xet)
                OR (xl.XEP_LOAI_NAM = EXTRACT(YEAR FROM v_ngay_xet)
                    AND q.quy < CASE EXTRACT(MONTH FROM v_ngay_xet)
                                    WHEN 12 THEN 1 WHEN 1 THEN 1 WHEN 2 THEN 1
                                    WHEN 3  THEN 2 WHEN 4 THEN 2 WHEN 5 THEN 2
                                    WHEN 6  THEN 3 WHEN 7 THEN 3 WHEN 8 THEN 3
                                    ELSE 4
                                END))
         ORDER BY xl.XEP_LOAI_NAM DESC, q.quy DESC
    ) LOOP
        BEGIN
            SELECT NVL(xlct.XLCT_TEN, u'Ch\01b0a x\1ebfp lo\1ea1i')
              INTO v_xl_ten
              FROM DM_XEP_LOAI_CAI_TAOS xlct
             WHERE xlct.ID = rec.xlct_id AND NVL(xlct.IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_xl_ten := u'Ch\01b0a x\1ebfp lo\1ea1i';
        END;
        v_dem_quy := v_dem_quy + 1;
        P('    [' || LPAD(v_dem_quy, 2, ' ') || '] Nam ' || rec.XEP_LOAI_NAM || ' '
          || rec.ten_ky || ' -> xlct_id=' || rec.xlct_id || ' | xlct_ten=' || v_xl_ten);
    END LOOP;
    P('  Tong so quy tim duoc: ' || v_dem_quy);

    IF v_dem_quy = 0 THEN
        P('  [!] KHONG CO DU LIEU XEP_LOAIS - kiem tra lai bang XEP_LOAIS cho pham nhan nay');
    END IF;

    -- ?? [7] L?y YC t? FN_TINH_SO_QUY_YEU_CAU ?????????????????
    P('');
    P('[7] SO QUY YEU CAU (tu FN_TINH_SO_QUY_YEU_CAU)');
    DECLARE
        v_yc QLPN.SO_QUY_YEU_CAU_OBJ;
    BEGIN
        v_yc := QLPN.FN_TINH_SO_QUY_YEU_CAU(p_pham_nhan_id, p_ky_giam_id);
        P('  YC lien tuc        : ' || v_yc.SO_QUY_LIEN_TUC);
        P('  YC khong lien tuc  : ' || v_yc.SO_QUY_KHONG_LIEN_TUC);
        P('  YC lien ke         : ' || v_yc.SO_QUY_LIEN_KE_YC);
        P('  YC dac biet        : ' || v_yc.SO_QUY_TRUONG_HOP_DB);
        v_so_quy_can_lay := v_yc.SO_QUY_LIEN_TUC; 
    EXCEPTION
        WHEN OTHERS THEN
            P('  [!] LOI khi goi FN_TINH_SO_QUY_YEU_CAU: ' || SQLERRM);
    END;

    -- ?? [8] Ket qua ham FN_GET_DS_KY_XEP_LOAI ?????????????????
    P('');
    HR;
    P('[8] KET QUA HAM FN_GET_DS_KY_XEP_LOAI(pn=' || p_pham_nhan_id || ', ky=' || p_ky_giam_id || ')');
    P('  => ' || NVL(QLPN.FN_GET_DS_KY_XEP_LOAI(p_pham_nhan_id, p_ky_giam_id), 'NULL'));
    HR;

EXCEPTION
    WHEN OTHERS THEN
        P('[LOI] ' || SQLERRM);
        P(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
END SP_DEBUG_KY_XEP_LOAI;





/
--------------------------------------------------------
--  DDL for Procedure SP_DS_C10_DUYET
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_DS_C10_DUYET" AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    -- Tap pham nhan cua bao cao = dung danh sach id da loc (endpoint nap truoc khi goi SP).
    PNS AS (
        SELECT ll.ID,
               ll.LL_HO_TEN,
               ll.LL_TEN_KHAC,
               ll.LL_NGAY_SINH,
               ll.LL_DM_GIOI_TINH_ID,
               ll.LL_DIA_CHI_THUONG_TRU,
               ll.LL_DIA_CHI_THUONG_TRU_WARD,
               ll.LL_DIA_CHI_THUONG_TRU_PROVICE,
               ll.LL_TRAI_GIAM_ID,
               ll.LL_SO_TIEN_AN
        FROM QLPN.PN_LAI_LICHS ll
        JOIN QLPN.GTT_PN_IDS g ON g.PN_ID = ll.ID
        WHERE NVL(ll.IS_DELETED, 0) = 0
    ),
    -- OI-1: ky dang mo moi nhat thuoc (cac) trai cua tap id. KGTH_TRAI_GIAM_MA giu MA trai
    -- (chuoi), nen phai dich LL_TRAI_GIAM_ID (surrogate) qua DM_TRAI_GIAMS.ID -> TG_MA.
    KY AS (
         SELECT MAX(k.KGTH_NGAY_XET_GIAM) AS NGAY_XET,
               MAX(k.ID) KEEP (DENSE_RANK LAST ORDER BY k.KGTH_NGAY_XET_GIAM) AS KY_ID
        FROM QLPN.GTH_KY_GIAM_THOI_HANS k
        WHERE NVL(k.IS_DELETED, 0) = 0
          AND k.KGTH_TRANG_THAI = 1
          AND k.KGTH_NGAY_XET_GIAM IS NOT NULL
          AND k.KGTH_TRAI_GIAM_MA IN (
                SELECT DISTINCT tg.TG_MA
                FROM PNS p
                JOIN QLPN.DM_TRAI_GIAMS tg ON tg.ID = p.LL_TRAI_GIAM_ID
              )
    ),
    -- Cac lan giam cua DUNG ky dang xet (BR-2 scope theo ky).
    GTH AS (
        SELECT gth.PHAM_NHAN_ID, gth.MUC_DE_NGHI_ID
        FROM QLPN.GIAM_THOI_HANS gth
        JOIN KY ON TRUNC(gth.NGAY_XET) = TRUNC(KY.NGAY_XET)
        WHERE NVL(gth.IS_DELETED, 0) = 0
          AND gth.MUC_DE_NGHI_ID IS NOT NULL
          AND gth.PHAM_NHAN_ID IN (SELECT p.ID FROM PNS p)
    ),
    XEP_LOAI_TD AS (
        SELECT PHAM_NHAN_ID, KQCT_DANHSACH
        FROM (
            SELECT gth.PHAM_NHAN_ID,
                   gth.KQCT_DANHSACH,
                   ROW_NUMBER() OVER (PARTITION BY gth.PHAM_NHAN_ID
                                      ORDER BY gth.ID DESC) AS RN
            FROM QLPN.GIAM_THOI_HANS gth
            JOIN KY ON TRUNC(gth.NGAY_XET) = TRUNC(KY.NGAY_XET)
            WHERE NVL(gth.IS_DELETED, 0) = 0
              AND gth.PHAM_NHAN_ID IN (SELECT p.ID FROM PNS p)
        )
        WHERE RN = 1
    ),
    CON_LAI AS (
        SELECT gth.PHAM_NHAN_ID,
               MAX(gth.CON_LAI) KEEP (DENSE_RANK LAST ORDER BY gth.ID) AS CON_LAI
        FROM QLPN.GIAM_THOI_HANS gth
        JOIN KY ON TRUNC(gth.NGAY_XET) = TRUNC(KY.NGAY_XET)
        WHERE NVL(gth.IS_DELETED, 0) = 0
          AND gth.PHAM_NHAN_ID IN (SELECT p.ID FROM PNS p)
        GROUP BY gth.PHAM_NHAN_ID
    ),
    GTD AS (
        SELECT gth.PHAM_NHAN_ID,
               MAX(gth.DA_CHAP_HANH) KEEP (DENSE_RANK LAST ORDER BY gth.ID) AS DA_CHAP_HANH
        FROM QLPN.GIAM_THOI_HANS gth
        JOIN KY ON TRUNC(gth.NGAY_XET) = TRUNC(KY.NGAY_XET) 
        WHERE NVL(gth.IS_DELETED, 0) = 0
          AND gth.PHAM_NHAN_ID IN (SELECT p.ID FROM PNS p)
        GROUP BY gth.PHAM_NHAN_ID
    ),
    -- OI-3: MTG_TITLE la thoi luong tran; boc tien to "N lan = " neu danh muc lo co san.
    TG_TITLE AS (
        SELECT dmtg.ID,
               REGEXP_REPLACE(NVL(dmtg.MTG_TITLE, ''),
                              '^[[:space:]]*[0-9]+[[:space:]]*l?n[[:space:]]*=[[:space:]]*', '') AS MTG_TITLE
        FROM QLPN.DM_MA_THOI_GIANS dmtg
        WHERE NVL(dmtg.IS_DELETED, 0) = 0
          AND dmtg.MTG_MA NOT IN ('921000', '912000', '911000', '922000')
    ),
    -- BR-2/BR-3: "da giam an" = liet ke tung lan giam cua ky.
    DA_GIAM_TD AS (
        SELECT gth.PHAM_NHAN_ID,
               MAX(gth.DA_GIAM) KEEP (DENSE_RANK LAST ORDER BY gth.ID) AS DA_GIAM
        FROM QLPN.GIAM_THOI_HANS gth
        JOIN KY ON TRUNC(gth.NGAY_XET) = TRUNC(KY.NGAY_XET)
        WHERE NVL(gth.IS_DELETED, 0) = 0
          AND gth.PHAM_NHAN_ID IN (SELECT p.ID FROM PNS p)
        GROUP BY gth.PHAM_NHAN_ID
    ),
    -- SEC-03: token hoa THA_TOI_DANH; chi giu cum [0-9]+ va ghep lai thanh CSV digit-only.
    TOI_DANH_TOKENS AS (
        SELECT t.THA_PNLAI_LICH_ID, t.TOKEN_CSV
        FROM (
            SELECT ptha.THA_PNLAI_LICH_ID,
                   (SELECT LISTAGG(REGEXP_SUBSTR(ptha.THA_TOI_DANH, '[0-9]+', 1, LEVEL), ',')
                           WITHIN GROUP (ORDER BY LEVEL)
                    FROM dual
                    CONNECT BY REGEXP_SUBSTR(ptha.THA_TOI_DANH, '[0-9]+', 1, LEVEL) IS NOT NULL
                   ) AS TOKEN_CSV
            FROM QLPN.PN_THI_HANH_AN ptha
            WHERE ptha.THA_TOI_DANH IS NOT NULL
              AND ptha.THA_PNLAI_LICH_ID IN (SELECT p.ID FROM PNS p)
        ) t
        WHERE t.TOKEN_CSV IS NOT NULL
    ),
    -- Chuoi dua vao XMLTABLE duoc dung lai tu CSV digit-only ("12,15" -> '"12","15"').
    TOI_DANH_SPLIT AS (
        SELECT tk.THA_PNLAI_LICH_ID,
               TO_NUMBER(x.COLUMN_VALUE) AS TOI_DANH_ID
        FROM TOI_DANH_TOKENS tk,
             XMLTABLE(('"' || REPLACE(tk.TOKEN_CSV, ',', '","') || '"')) x
        WHERE REGEXP_LIKE(x.COLUMN_VALUE, '^[0-9]+$')
    ),
    TOI_DANH_AGG AS (
        SELECT tds.THA_PNLAI_LICH_ID,
               LISTAGG(dtd.TD_TEN, u', ') WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH
        FROM TOI_DANH_SPLIT tds
        JOIN QLPN.DM_TOI_DANHS dtd ON tds.TOI_DANH_ID = dtd.ID
        GROUP BY tds.THA_PNLAI_LICH_ID
    ),
    -- BR-5: dung dung cap ham nghiep vu ma 4 SP anh em dang dung, khong tu tinh lai.
    FN_DATA AS (
        SELECT ll.ID,
               QLPN.FN_GET_DA_CHAP_HANH_THEO_NGAY(ll.ID, SYSDATE) AS DA_CHAP_HANH_OBJ,
               QLPN.FN_TINH_THOI_GIAN_CON_LAI(ll.ID, SYSDATE)     AS CON_LAI_TEXT
        FROM QLPN.PN_LAI_LICHS ll
        WHERE ll.ID IN (SELECT p.ID FROM PNS p)
    )
    SELECT
        -- 1
        (SELECT tg.TG_TEN FROM QLPN.DM_TRAI_GIAMS tg WHERE tg.ID = p.LL_TRAI_GIAM_ID)
                                                        AS "TRAI_GIAM",
        -- 2 — BR-6: danh so lai tu 1 theo thu tu bao cao.
        ROW_NUMBER() OVER (ORDER BY FN_SWAP_FIRST_LAST_SORT(p.LL_HO_TEN))
                                                        AS "STT",
        -- 3
        p.LL_HO_TEN                                     AS "HO_TEN",
        p.LL_TEN_KHAC                    				AS "TEN_KHAC",
        p.LL_SO_TIEN_AN                                 AS "SO_TA",
        -- 4 — quy uoc san xuat (:97 cua SP anh em).
        p.LL_NGAY_SINH                      			AS "NAM_SINH",
        -- 5
        dgt.GT_TEN                                      AS "GIOI_TINH",
        -- 6 — dia chi day du, ghep bang dau phay (CASE cua SP anh em :99-124).
        CASE
            WHEN NULLIF(TRIM(p.LL_DIA_CHI_THUONG_TRU),      u'') IS NOT NULL
              OR NULLIF(TRIM(dvhcx.XP_TEN),   u'') IS NOT NULL
              OR NULLIF(TRIM(dvhct.TTP_TEN),  u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(p.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dvhcx.XP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(p.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || dvhcx.XP_TEN
                            ELSE dvhcx.XP_TEN
                        END
                    ELSE u''
                   END
                || CASE
                    WHEN NULLIF(TRIM(dvhct.TTP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(p.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dvhcx.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || dvhct.TTP_TEN
                            ELSE dvhct.TTP_TEN
                        END
                    ELSE u''
                   END
            )
            ELSE NULL
        END                                             AS "NOI_DKHKTT",
        -- 7
        tda.TOI_DANH                                    AS "TOI_DANH",
        -- 8 — NFR-4: SP la noi cuoi con kieu DATE, nen xuat chuoi bang format co dinh.
        TO_CHAR(ptha.THA_NGAY_BAT, 'DD/MM/YYYY')        AS "NGAY_BAT",
        -- 9
        ptha.THA_AN_PHAT                                AS "AN_PHAT",
        -- 10 — BR-4: chuoi da luu thang, neu rong thi render tu ham (CASE :150-164).
        CASE
            WHEN NULLIF(TRIM(dc.DA_CHAP_HANH), u'') IS NOT NULL
            THEN dc.DA_CHAP_HANH
            WHEN NULLIF(TRIM(ptha.THA_THOI_GIAN_DA_CHAP_HANH), u'') IS NOT NULL
            THEN ptha.THA_THOI_GIAN_DA_CHAP_HANH
            ELSE
                CASE
                    WHEN NVL(fn.DA_CHAP_HANH_OBJ.nam, 0)   = 0
                     AND NVL(fn.DA_CHAP_HANH_OBJ.thang, 0) = 0
                     AND NVL(fn.DA_CHAP_HANH_OBJ.ngay, 0)  = 0
                    THEN u'Kh\00f4ng'
                    ELSE
                        CASE WHEN NVL(fn.DA_CHAP_HANH_OBJ.nam, 0) > 0
                             THEN TO_CHAR(fn.DA_CHAP_HANH_OBJ.nam) || u' n\0103m ' ELSE u'' END ||
                        CASE WHEN NVL(fn.DA_CHAP_HANH_OBJ.thang, 0) > 0
                             THEN TO_CHAR(fn.DA_CHAP_HANH_OBJ.thang) || u' th\00e1ng ' ELSE u'' END ||
                        CASE WHEN NVL(fn.DA_CHAP_HANH_OBJ.ngay, 0) > 0
                             THEN TO_CHAR(fn.DA_CHAP_HANH_OBJ.ngay) || u' ng\00e0y' ELSE u'' END
                END
        END                                             AS "DA_CHAP_HANH",
        -- 11 — khong co lan giam trong ky -> 'Không' (khuon :132-136).
         dgtl.DA_GIAM                                     AS "DA_GIAM_AN",
        -- 12
        COALESCE(NULLIF(TRIM(cl.CON_LAI), u''), fn.CON_LAI_TEXT) AS "AN_CON_LAI", 
        -- 13 — quy gan nhat, khong chieu.
        DBMS_LOB.SUBSTR(xtd.KQCT_DANHSACH, 4000, 1)     AS "XEP_LOAI_THI_DUA",
        -- 15
        TO_CHAR(ptha.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY')   AS "NGAY_DEN_TRAI",
        -- 16 — BR-7: luon rong o F-002.
        CAST(NULL AS VARCHAR2(4000))                    AS "GHI_CHU"
    FROM PNS p
    LEFT JOIN QLPN.DM_GIOI_TINHS dgt
        ON dgt.ID = p.LL_DM_GIOI_TINH_ID
    LEFT JOIN QLPN.PN_THI_HANH_AN ptha
        ON ptha.THA_PNLAI_LICH_ID = p.ID
       AND NVL(ptha.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_XA_PHUONG dvhcx
        ON dvhcx.ID = p.LL_DIA_CHI_THUONG_TRU_WARD
    LEFT JOIN QLPN.DM_TINH_THANH_PHO dvhct
        ON dvhct.ID = p.LL_DIA_CHI_THUONG_TRU_PROVICE
    LEFT JOIN TOI_DANH_AGG tda
        ON tda.THA_PNLAI_LICH_ID = p.ID
    LEFT JOIN DA_GIAM_TD dgtl 
   		ON dgtl.PHAM_NHAN_ID = p.ID
    LEFT JOIN FN_DATA fn
        ON fn.ID = p.ID
    LEFT JOIN GTD dc
        ON dc.PHAM_NHAN_ID = p.ID
    LEFT JOIN XEP_LOAI_TD xtd
        ON xtd.PHAM_NHAN_ID = p.ID
    LEFT JOIN CON_LAI cl 
    	ON cl.PHAM_NHAN_ID = p.ID
   	
    ORDER BY FN_SWAP_FIRST_LAST_SORT(p.LL_HO_TEN);

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            'L?i SP_DS_C10_DUYET: ' || SQLERRM);
END;

/
--------------------------------------------------------
--  DDL for Procedure SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE" (
    p_ngay_xet IN DATE
) AS
BEGIN
    QLPN.SP_REFRESH_PN_TINH_TRANG_NGAY_CACHE(p_ngay_xet => p_ngay_xet, p_force => 0);
END SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE;

/
--------------------------------------------------------
--  DDL for Procedure SP_GEN_TABLE_DOCUMENTATION
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GEN_TABLE_DOCUMENTATION" (
    p_TABLE_NAME IN VARCHAR2 DEFAULT NULL,
    p_CURSOR OUT SYS_REFCURSOR
) AS
BEGIN
    OPEN p_CURSOR FOR
    WITH TABLE_LIST AS (
        SELECT 'DX_DIEU_KIEN_DAC_XAS' AS TABLE_NAME, 'Nhóm ??c xá' AS NHOM_BANG FROM DUAL UNION ALL
        SELECT 'DX_DU_DIEU_KIEN_DAC_XAS', 'Nhóm ??c xá' FROM DUAL UNION ALL
        SELECT 'DX_HINH_PHAT_BO_SUNGS', 'Nhóm ??c xá' FROM DUAL UNION ALL
        SELECT 'DX_THOI_GIAN_CHAP_HANHS', 'Nhóm ??c xá' FROM DUAL UNION ALL
        SELECT 'DX_THOI_GIAN_CON_LAIES', 'Nhóm ??c xá' FROM DUAL UNION ALL
        SELECT 'DX_TOI_DANH_RIENGS', 'Nhóm ??c xá' FROM DUAL UNION ALL
        SELECT 'DX_TRUONG_HOP_DAC_BIETS', 'Nhóm ??c xá' FROM DUAL UNION ALL
        SELECT 'DX_XEP_LOAI_CAI_TAOS', 'Nhóm ??c xá' FROM DUAL UNION ALL
        SELECT 'FILE_ATTACHMENTS', 'Nhóm File ?ính kèm' FROM DUAL UNION ALL
        SELECT 'GIAM_THOI_HANS', 'Nhóm Gi?m th?i h?n' FROM DUAL UNION ALL
        SELECT 'HOAN_THI_HANH_ANS', 'Nhóm Hoãn thi hành án' FROM DUAL UNION ALL
        SELECT 'HO_SO_DINH_KEMS', 'Nhóm H? s?/Tài li?u' FROM DUAL UNION ALL
        SELECT 'HUY_ANS', 'Nhóm H?y án' FROM DUAL UNION ALL
        SELECT 'KHEN_THUONGS', 'Nhóm Khen th??ng' FROM DUAL UNION ALL
        SELECT 'KY_LUATS', 'Nhóm K? lu?t' FROM DUAL UNION ALL
        SELECT 'MIEN_HINH_PHATS', 'Nhóm Mi?n hình ph?t' FROM DUAL UNION ALL
        SELECT 'MO_KY_XEP_LOAI_CAI_TAOS', 'Nhóm X?p lo?i' FROM DUAL UNION ALL
        SELECT 'MO_KY_XEP_LOAI_CAI_TAO_PN_LAI_LICH', 'Nhóm X?p lo?i' FROM DUAL UNION ALL
        SELECT 'NOP_LUUS', 'Nhóm N?p l?u' FROM DUAL UNION ALL
        SELECT 'PHAM_NHAN_CHUYEN_TRAI', 'Nhóm Phân lo?i ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PHAM_NHAN_PHAN_BUONG', 'Nhóm Phân lo?i ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PHAM_NHAN_PHAN_DOI', 'Nhóm Phân lo?i ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PHAM_TOI_MOIS', 'Nhóm Ph?m t?i m?i' FROM DUAL UNION ALL
        SELECT 'PHAN_LOAIS', 'Nhóm Phân lo?i' FROM DUAL UNION ALL
        SELECT 'PN_BAN_AN_KHACS', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PN_BIENLAIES', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PN_CHUYEN_GIAO', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PN_DAC_XAS', 'Nhóm ??c xá' FROM DUAL UNION ALL
        SELECT 'PN_DOT_DAC_XAS', 'Nhóm ??c xá' FROM DUAL UNION ALL
        SELECT 'PN_DOT_THA_CO_DIEU_KIENS', 'Nhóm Tha có ?i?u ki?n' FROM DUAL UNION ALL
        SELECT 'PN_DU_DIEU_KIEN_XET_THAS', 'Nhóm Tha có ?i?u ki?n' FROM DUAL UNION ALL
        SELECT 'PN_GIAM_RIENGS', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PN_GIAO_NHAN_PHAN_NHANS', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PN_HINH_PHAT_BO_SUNGS', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PN_KET_THUC_CHETS', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PN_KET_THUC_RA_TRAIS', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PN_LAI_LICHS', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PN_NGHIEN_MT', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PN_NHAN_DANGS', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PN_QUYET_DINH_BAN_AN_KHACS', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PN_TAI_LIEU_DINH_KEMS', 'Nhóm H? s?/Tài li?u' FROM DUAL UNION ALL
        SELECT 'PN_THI_HANH_AN', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PN_TIEN_AN', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'PN_TIEN_SUS', 'Nhóm Ph?m nhân' FROM DUAL UNION ALL
        SELECT 'TAM_DINH_CHIS', 'Nhóm T?m ?ình ch?' FROM DUAL UNION ALL
        SELECT 'TANG_GIAM_HINH_PHATS', 'Nhóm T?ng/Gi?m hình ph?t' FROM DUAL UNION ALL
        SELECT 'TANG_GIAM_TRONG_THANG', 'Nhóm T?ng/Gi?m hình ph?t' FROM DUAL UNION ALL
        SELECT 'THAM_SO_HE_THONGS', 'Nhóm Tham s? h? th?ng' FROM DUAL UNION ALL
        SELECT 'THAN_NHAN_CON_CAIS', 'Nhóm Thân nhân' FROM DUAL UNION ALL
        SELECT 'THAN_NHAN_NGUOI_THANS', 'Nhóm Thân nhân' FROM DUAL UNION ALL
        SELECT 'THA_CO_DIEU_KIENS', 'Nhóm Tha có ?i?u ki?n' FROM DUAL UNION ALL
        SELECT 'TIEN_CHI_LAO_DONG_SAN_XUATS', 'Nhóm Ti?n l??ng' FROM DUAL UNION ALL
        SELECT 'TIEN_LAO_DONG_SAN_XUATS', 'Nhóm Ti?n l??ng' FROM DUAL UNION ALL
        SELECT 'TRICH_XUATS', 'Nhóm Trích xu?t' FROM DUAL UNION ALL
        SELECT 'TRON_TRAIS', 'Nhóm Tr?n tr?i' FROM DUAL UNION ALL
        SELECT 'XEP_LOAIS', 'Nhóm X?p lo?i' FROM DUAL
    )
    SELECT 
        tl.NHOM_BANG,
        tl.TABLE_NAME AS TEN_BANG,
        NVL(at.NUM_ROWS, 0) AS SO_DONG,
        at.LAST_ANALYZED AS NGAY_PHAN_TICH
    FROM TABLE_LIST tl
    LEFT JOIN ALL_TABLES at 
        ON at.OWNER = 'QLPN' 
        AND at.TABLE_NAME = tl.TABLE_NAME
    WHERE (p_TABLE_NAME IS NULL OR tl.TABLE_NAME = p_TABLE_NAME)
    ORDER BY tl.NHOM_BANG, tl.TABLE_NAME;
END;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_ALL_PN_INFO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_ALL_PN_INFO" (
    p_PN_ID IN NUMBER
) AS
    c1  SYS_REFCURSOR; c2  SYS_REFCURSOR; c3  SYS_REFCURSOR; c4  SYS_REFCURSOR;
    c5  SYS_REFCURSOR; c6  SYS_REFCURSOR; c7  SYS_REFCURSOR; c8  SYS_REFCURSOR;
    c9  SYS_REFCURSOR; c10 SYS_REFCURSOR; c11 SYS_REFCURSOR; c12 SYS_REFCURSOR;
    c13 SYS_REFCURSOR; c14 SYS_REFCURSOR; c15 SYS_REFCURSOR; c16 SYS_REFCURSOR;
    c17 SYS_REFCURSOR; c18 SYS_REFCURSOR; c19 SYS_REFCURSOR; c20 SYS_REFCURSOR;
    c21 SYS_REFCURSOR; c22 SYS_REFCURSOR;
    v_id_max_tha   PN_THI_HANH_AN.ID%TYPE;
    v_id_max_tt    TRON_TRAIS.ID%TYPE;
    v_id_max_tdc   TAM_DINH_CHIS.ID%TYPE;
    v_id_max_gth   GIAM_THOI_HANS.ID%TYPE;
BEGIN
    -- Lay ID thi hanh an moi nhat
    BEGIN
        SELECT ID INTO v_id_max_tha
        FROM (
            SELECT ID, ROW_NUMBER() OVER (
                ORDER BY NVL(THA_NGAY_BAN_AN, TO_DATE('01-JAN-1900','DD-MON-YYYY')) DESC, ID DESC
            ) AS rn
            FROM PN_THI_HANH_AN WHERE THA_PNLAI_LICH_ID = p_PN_ID
        ) WHERE rn = 1;
    EXCEPTION WHEN NO_DATA_FOUND THEN v_id_max_tha := NULL; END;

    BEGIN
        SELECT ID INTO v_id_max_tt
        FROM (
            SELECT ID, ROW_NUMBER() OVER (
                ORDER BY NVL(NGAY_TRON, TO_DATE('01-JAN-1900','DD-MON-YYYY')) DESC, ID DESC
            ) AS rn
            FROM TRON_TRAIS WHERE PHAM_NHAN_ID = p_PN_ID
        ) WHERE rn = 1;
    EXCEPTION WHEN NO_DATA_FOUND THEN v_id_max_tt := NULL; END;

    BEGIN
        SELECT ID INTO v_id_max_tdc
        FROM (
            SELECT ID, ROW_NUMBER() OVER (
                ORDER BY NVL(NGAY_TDC, TO_DATE('01-JAN-1900','DD-MON-YYYY')) DESC, ID DESC
            ) AS rn
            FROM TAM_DINH_CHIS WHERE PHAM_NHAN_ID = p_PN_ID
        ) WHERE rn = 1;
    EXCEPTION WHEN NO_DATA_FOUND THEN v_id_max_tdc := NULL; END;

    BEGIN
        SELECT ID INTO v_id_max_gth
        FROM (
            SELECT ID, ROW_NUMBER() OVER (ORDER BY ID DESC) AS rn
            FROM GIAM_THOI_HANS WHERE PHAM_NHAN_ID = p_PN_ID
        ) WHERE rn = 1;
    EXCEPTION WHEN NO_DATA_FOUND THEN v_id_max_gth := NULL; END;

    -- ===== ResultSet #1: ThongTinLaiLich =====
    OPEN c1 FOR
    WITH SPLIT_TOI_DANH AS (
        SELECT ptha.THA_PNLAI_LICH_ID,
            TO_NUMBER(REGEXP_SUBSTR(REPLACE(REPLACE(ptha.THA_TOI_DANH,'[',''),']',''),'[0-9]+',1,LEVEL)) AS TD_ID
        FROM PN_THI_HANH_AN ptha
        WHERE ptha.THA_TOI_DANH IS NOT NULL AND ptha.THA_PNLAI_LICH_ID = p_PN_ID
        CONNECT BY LEVEL <= REGEXP_COUNT(REPLACE(REPLACE(ptha.THA_TOI_DANH,'[',''),']',''),',')+1
           AND PRIOR ptha.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID AND PRIOR SYS_GUID() IS NOT NULL
    ),
    TOI_DANH_AGG AS (
        SELECT s.THA_PNLAI_LICH_ID, LISTAGG(DISTINCT dtd.TD_TEN,'; ') WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH
        FROM SPLIT_TOI_DANH s LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID=s.TD_ID GROUP BY s.THA_PNLAI_LICH_ID
    )
    SELECT
        pll.LL_SO_HO_SO_LAN_DAU AS Sohsld, dttpn.TTPN_TEN AS TinhTrang, pll.LL_HO_TEN AS HoTen,
        dgt.GT_TEN AS GioiTinh, pll.LL_NGAY_SINH AS NamSinh, pll.LL_TEN_KHAC AS HoTenKhac,
        pll.LL_NGUYEN_QUAN AS NguyenQuan, pll.LL_DIA_CHI_THUONG_TRU AS DiaChiThuongTru,
        ddt.DT_TEN AS DanToc, dqt.QT_TEN AS QuocTich, dtg.TG_TEN AS TonGiao,
        pll.LL_NGHE_CU_THE AS NgheNghiep, pll.LL_TRINH_DO_HOC_VAN_ID AS TrinhDoHocVan,
        pll.LL_CHI_TIET_BENH_VAO AS TinhTrangSucKhoeKhiVao, pll.LL_BENH_HIEN_TAI AS TinhTrangSucKhoeHienTai,
        pll.LL_GHI_CHU_RIENG AS GhiChuRieng, NVL(cc.SO_CON,0) AS SoCon,
        pll.LL_SO_TIEN_AN AS SoTienAn, pll.LL_SO_TIEN_SU AS SoTienSu,
        pll.LL_NHAN_THAN AS NhanThan, td_agg.TOI_DANH AS ToiDanh,
        TO_CHAR(TRUNC(ptha.THA_NGAY_BAT),'DD/MM/YYYY') AS NgayBat,
        ptha.THA_AN_PHAT AS AnPhat, ptha.THA_SO_BAN_AN AS BanAnSo, ptha.THA_NGAY_BAN_AN AS NgayBanAn,
        dcq.CQ_TEN AS ToaQuyetDinh, ptha.THA_SO_QD_THA AS SoQuyetDinh,
        ptha.THA_SO_QD_DIEU_CHUYEN AS SoQuyetDinhDieuChuyen, dcq1.CQ_TEN AS ChuyenDenTu,
        ptha.THA_THOI_GIAN_TAM_GIAM AS ThoiGianTamGiam, ptha.THA_THOI_GIAN_TAM_GIU AS ThoiGianTamGiu,
        TO_CHAR(TRUNC(ptha.THA_NGAY_DEN_TRAI),'DD/MM/YYYY') AS NgayDenTrai,
        dpd.PD_TEN AS PhanDoi, dpt.PT_TEN AS PhanTrai, dtg2.TG_TEN AS TraiGiam,
        TO_CHAR(TRUNC(tt.NGAY_TRON),'DD/MM/YYYY') AS ThoiGianTron,
        TO_CHAR(TRUNC(tdc.NGAY_TDC),'DD/MM/YYYY') AS ThoiGianTamDinhChi,
        dmtg.MTG_TITLE AS ThoiGianDuocGiam, mhp.MHP_THM_YEAR AS MienHinhPhat,
        PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(pll.ID) AS DaChapHanh,
        PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(pll.ID) AS ThoiGianConLai,
        TO_CHAR(TRUNC(ptha.THA_NGAY_HET_HAN),'DD/MM/YYYY') AS NgayTha,
        'Chua ro' AS HanhViPhamToi
    FROM PN_LAI_LICHS pll
    LEFT JOIN PN_THI_HANH_AN ptha ON ptha.ID = v_id_max_tha
    LEFT JOIN TRON_TRAIS tt ON tt.ID = v_id_max_tt
    LEFT JOIN TAM_DINH_CHIS tdc ON tdc.ID = v_id_max_tdc
    LEFT JOIN GIAM_THOI_HANS gth ON gth.ID = v_id_max_gth
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
    LEFT JOIN MIEN_HINH_PHATS mhp ON mhp.PN_LAI_LICH_ID = pll.ID
    LEFT JOIN DM_CO_QUANS dcq ON ptha.THA_TOA_QD_ID = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq1 ON ptha.THA_CHUYEN_DEN_TU_ID = dcq1.ID
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dttpn ON pll.LL_TINH_TRANG_ID = dttpn.ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_DAN_TOCS ddt ON pll.LL_DM_DAN_TOC_ID = ddt.ID
    LEFT JOIN DM_TON_GIAOS dtg ON pll.LL_DM_TON_GIAO_ID = dtg.ID
    LEFT JOIN DM_QUOC_TICHS dqt ON pll.LL_DM_QUOC_TICH_ID = dqt.ID
    LEFT JOIN DM_PHAN_DOIS dpd ON pll.LL_PHAN_DOI_ID = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt ON pll.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg2 ON pll.LL_TRAI_GIAM_ID = dtg2.ID
    LEFT JOIN TOI_DANH_AGG td_agg ON pll.ID = td_agg.THA_PNLAI_LICH_ID
    LEFT JOIN (SELECT PHAM_NHAN_ID, COUNT(DISTINCT ID) AS SO_CON FROM THAN_NHAN_CON_CAIS GROUP BY PHAM_NHAN_ID) cc
        ON pll.ID = cc.PHAM_NHAN_ID
    WHERE pll.ID = p_PN_ID;

    -- ===== ResultSet #2: QuanHeGiaDinh =====
    OPEN c2 FOR
    SELECT tnnt.PHAM_NHAN_ID, tnnt.HO_TEN_THAN_NHAN AS "HoTen", dqhvpn.QHVPN_TEN AS "QuanHe",
        dgt.GT_TEN AS "GioiTinh", tnnt.NGAY_SINH AS "NgaySinh", tnnt.NOI_O AS "NoiO"
    FROM THAN_NHAN_NGUOI_THANS tnnt
    LEFT JOIN DM_QUAN_HE_VOI_PHAM_NHANS dqhvpn ON tnnt.QUAN_HE_ID = dqhvpn.ID
    LEFT JOIN DM_GIOI_TINHS dgt ON tnnt.GIOI_TINH_ID = dgt.ID
    WHERE tnnt.PHAM_NHAN_ID = p_PN_ID;

    -- ===== ResultSet #3: TienAn =====
    OPEN c3 FOR
    SELECT pta.PNTA_LAI_LICH_ID, dcq.CQ_TEN AS "ToaXu", pta.PNTA_NAM_XU AS "NamXu",
        RTRIM(XMLAGG(XMLELEMENT(e,dtd.TD_TEN||', ') ORDER BY dtd.TD_TEN).extract('//text()').GETCLOBVAL(),', ') AS "ToiDanh",
        pta.PNTA_MUC_AN_ID AS "MucAn", pta.PNTA_NAM_THA AS "NamTha"
    FROM PN_TIEN_AN pta
    LEFT JOIN DM_CO_QUANS dcq ON pta.PNTA_TOA_XU_ID = dcq.ID
    LEFT JOIN (
        SELECT DISTINCT pta2.PNTA_LAI_LICH_ID, TO_NUMBER(REGEXP_SUBSTR(REPLACE(REPLACE(pta2.PNTA_TOI_DANH_ID,'[',''),']',''),'[^,]+',1,LEVEL)) AS TD_ID
        FROM PN_TIEN_AN pta2 WHERE pta2.PNTA_LAI_LICH_ID = p_PN_ID
        CONNECT BY LEVEL <= REGEXP_COUNT(REPLACE(REPLACE(pta2.PNTA_TOI_DANH_ID,'[',''),']',''),',')+1
        AND PRIOR pta2.PNTA_LAI_LICH_ID = pta2.PNTA_LAI_LICH_ID AND PRIOR SYS_GUID() IS NOT NULL
    ) td ON pta.PNTA_LAI_LICH_ID = td.PNTA_LAI_LICH_ID
    LEFT JOIN DM_TOI_DANHS dtd ON td.TD_ID = dtd.ID
    WHERE pta.PNTA_LAI_LICH_ID = p_PN_ID
    GROUP BY pta.PNTA_LAI_LICH_ID, pta.PNTA_NAM_XU, dcq.CQ_TEN, pta.PNTA_MUC_AN_ID, pta.PNTA_NAM_THA;

    -- ===== ResultSet #4: TienSu =====
    OPEN c4 FOR
    SELECT pts.TS_PN_LAI_LICH_ID, pts.TS_THOI_GIAN AS "ThoiGian", pts.TS_HANH_VI_VI_PHAM AS "HanhViViPham",
        pts.TS_DON_VI_XU_LY AS "DonViXuLy", pts.TS_HINH_THUC_XU_LY AS "HinhThuc",
        pts.TS_NGAY_BAT_DAU AS "TuNgay", pts.TS_NGAY_KET_THUC AS "DenNgay"
    FROM PN_TIEN_SUS pts WHERE pts.TS_PN_LAI_LICH_ID = p_PN_ID;

    -- ===== ResultSet #5: BanAnKhac =====
    OPEN c5 FOR
    SELECT pbak.BAK_PN_LAI_LICH_ID, pbak.BAK_SO_BAN_AN AS "BanAnSo", pbak.BAK_NGAY_BAN_AN AS "Ngay",
        dctx.CTX_TEN AS "CapXu", dctx2.CTX_TEN AS "ToaXu", dtd.TD_TEN AS "ToiDanh", dma.MA_TEN_CHI_TIEU AS "MucAn"
    FROM PN_BAN_AN_KHACS pbak
    LEFT JOIN DM_CAP_TOA_XUS dctx ON pbak.BAK_CAP_TOA_XU_ID = dctx.ID
    LEFT JOIN DM_CAP_TOA_XUS dctx2 ON pbak.BAK_TOA_XU_ID = dctx2.ID
    LEFT JOIN DM_TOI_DANHS dtd ON pbak.BAK_TOI_DANH_ID = dtd.ID
    LEFT JOIN DM_MUC_ANS dma ON pbak.BAK_MUC_AN_ID = dma.ID
    WHERE pbak.BAK_PN_LAI_LICH_ID = p_PN_ID;

    -- ===== ResultSet #6: QDT HAM Khac =====
    OPEN c6 FOR
    SELECT pbak.BAK_PN_LAI_LICH_ID, pbak.BAK_SO_QUYET_DINH AS "SoQD", pbak.BAK_NGAY_QUYET_DINH AS "NgayQD",
        dcq.CQ_TEN AS "ToaQD", pbak.BAK_SO_BAN_AN AS "SoBanAn", pbak.BAK_NGAY_BAN_AN AS "Ngay", dcq2.CQ_TEN AS "ToaXu"
    FROM PN_BAN_AN_KHACS pbak
    LEFT JOIN DM_CO_QUANS dcq ON pbak.BAK_TOA_QUYET_DINH_ID = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq2 ON pbak.BAK_TOA_XU_ID = dcq2.ID
    WHERE pbak.BAK_PN_LAI_LICH_ID = p_PN_ID;

    -- ===== ResultSet #7: HinhPhatBoSung =====
    OPEN c7 FOR
    SELECT phpbs.HPBS_MA_PHAM_NHAN, phpbs.HPBS_HINH_PHAT AS "HinhPhat",
        phpbs.HPBS_THOI_HAN AS "ThoiHan", phpbs.HPBS_GHI_CHU_CHI_TIET AS "GhiChu"
    FROM PN_HINH_PHAT_BO_SUNGS phpbs WHERE phpbs.HPBS_MA_PHAM_NHAN = p_PN_ID;

    -- ===== ResultSet #8: PhanLoaiGiamGiu =====
    OPEN c8 FOR
    SELECT pl.PHAM_NHAN_ID, pl.NGAY_PHAN_LOAI AS "NgayPhanLoai", pl.GHI_CHU AS "GhiChu",
        dplgg.PLGG_TEN AS "TuLoai", dplgg2.PLGG_TEN AS "DenLoai"
    FROM PHAN_LOAIS pl
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg ON pl.TU_LOAI_ID = dplgg.ID
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg2 ON pl.DEN_LOAI_ID = dplgg2.ID
    WHERE pl.PHAM_NHAN_ID = p_PN_ID;

    -- ===== ResultSet #9: KhenThuong =====
    OPEN c9 FOR
    SELECT kt.PHAM_NHAN_ID, kt.NGAY_KHEN AS "NgayKhen", kt.LY_DO AS "LyDoKhen", kt.HINH_THUC_KHEN AS "HinhThucKhen"
    FROM KHEN_THUONGS kt WHERE kt.PHAM_NHAN_ID = p_PN_ID;

    -- ===== ResultSet #10: KyLuat =====
    OPEN c10 FOR
    SELECT kl.PHAM_NHAN_ID, kl.NGAY_QUYET_DINH AS "NgayKyLuat", kl.LY_DO_KY_LUAT_CU_THE AS "LyDoKyLuat",
        kl.HINH_THUC_KY_LUAT_CU_THE AS "HinhThucKyLuat", kl.NGAY_QUYET_DINH_TIEN_BO AS "NgayCNTienBo"
    FROM KY_LUATS kl WHERE kl.PHAM_NHAN_ID = p_PN_ID;

    -- ===== ResultSet #11: GiamRieng =====
    OPEN c11 FOR
    SELECT pgr.GR_PN_LAI_LICH_ID, pgr.GR_LY_DO AS "LyDoGiamRieng", pgr.GR_THOI_HAN_GIAM_RIENG AS "ThoiHan",
        pgr.GR_NGAY_BAT_DAU AS "NgayBatDau", pgr.GR_NGAY_KETTHUC AS "NgayKetThuc", pgr.GR_LY_DO_DUA_RA AS "LyDoDuaRa"
    FROM PN_GIAM_RIENGS pgr WHERE pgr.GR_PN_LAI_LICH_ID = p_PN_ID;

    -- ===== ResultSet #12: PhamToiMoi =====
    OPEN c12 FOR
    SELECT ptm.PHAM_NHAN_ID, ptm.NGAY_PHAM_TOI AS "NgayPhamToi", dtd.TD_TEN AS "ToiDanh", ptm.HINH_THUC_XU_LY AS "HinhThucXuLy"
    FROM PHAM_TOI_MOIS ptm LEFT JOIN DM_TOI_DANHS dtd ON ptm.TOI_DANH_ID = dtd.ID
    WHERE ptm.PHAM_NHAN_ID = p_PN_ID;

    -- ===== ResultSet #13: KetQuaCaiTao =====
    OPEN c13 FOR
    SELECT xl.PHAM_NHAN_ID, xl.XEP_LOAI_NAM AS "Nam", xl.XEP_LOAI_QUY_I AS "Quy1",
        xl.XEP_LOAI_QUY_II AS "Quy2", xl.XEP_LOAI_6_THANG_DAU_NAM AS "DauNam",
        xl.XEP_LOAI_QUY_III AS "Quy3", xl.XEP_LOAI_QUY_IV AS "Quy4",
        xl.XEP_LOAI_6_THANG_CUOI_NAM AS "CuoiNam", xl.XEP_LOAI_CA_NAM AS "CaNam"
    FROM XEP_LOAIS xl WHERE xl.PHAM_NHAN_ID = p_PN_ID;

    -- ===== ResultSet #14: GiamThoiHan =====
    OPEN c14 FOR
    SELECT gth.PHAM_NHAN_ID, gth.NGAY_XET AS "NgayXet", gth.SO_QUYET_DINH AS "SoQD",
        gth.NGAY_QUYET_DINH AS "NgayQD", dcq.CQ_TEN AS "ToaQD", dmtg.MTG_TITLE AS "MucGiam"
    FROM GIAM_THOI_HANS gth
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
    LEFT JOIN DM_CO_QUANS dcq ON gth.TOA_QUYET_DINH_ID = dcq.ID
    WHERE gth.PHAM_NHAN_ID = p_PN_ID;

    -- ===== ResultSet #15: TangGiamHinhPhat =====
    OPEN c15 FOR
    SELECT tghp.PHAM_NHAN_ID, tghp.LOAI_TANG_GIAM_ID AS "TangGiam", tghp.SO_QUYET_DINH AS "SoQuyetDinh",
        tghp.NGAY_QUYET_DINH AS "NgayQuyetDinh", dcq.CQ_TEN AS "CoQuanQuyetDinh", dmtg.MTG_TITLE AS "ThoiHan"
    FROM TANG_GIAM_HINH_PHATS tghp
    JOIN DM_MA_THOI_GIANS dmtg ON tghp.THOI_HAN_ID = dmtg.ID
    JOIN DM_CO_QUANS dcq ON tghp.DON_VI_QUYET_DINH_ID = dcq.ID
    WHERE tghp.PHAM_NHAN_ID = p_PN_ID;

    -- ===== ResultSet #16: MienHinhPhat =====
    OPEN c16 FOR
    SELECT mhp.PN_LAI_LICH_ID, mhp.MHP_SO_QUYET_DINH AS "SoQD", mhp.MHP_NGAY_QUYET_DINH AS "NgayQD",
        dcq.CQ_TEN AS "ToaQD", td_agg.TOI_DANH_MIEN AS "ToiDanhMien"
    FROM MIEN_HINH_PHATS mhp
    LEFT JOIN DM_CO_QUANS dcq ON mhp.MHP_TOA_QUYET_DINH = dcq.ID
    LEFT JOIN (
        SELECT mhp2.PN_LAI_LICH_ID, RTRIM(XMLAGG(XMLELEMENT(e,dtd.TD_TEN||', ') ORDER BY dtd.TD_TEN).extract('//text()').GETCLOBVAL(),', ') AS TOI_DANH_MIEN
        FROM MIEN_HINH_PHATS mhp2
        LEFT JOIN (
            SELECT DISTINCT mhp3.PN_LAI_LICH_ID, TO_NUMBER(REGEXP_SUBSTR(REPLACE(REPLACE(mhp3.MHP_TOI_DANH_MIEN,'[',''),']',''),'[^,]+',1,LEVEL)) AS TD_ID
            FROM MIEN_HINH_PHATS mhp3 WHERE mhp3.PN_LAI_LICH_ID = p_PN_ID
            CONNECT BY LEVEL <= REGEXP_COUNT(REPLACE(REPLACE(mhp3.MHP_TOI_DANH_MIEN,'[',''),']',''),',')+1
            AND PRIOR mhp3.PN_LAI_LICH_ID = mhp3.PN_LAI_LICH_ID AND PRIOR SYS_GUID() IS NOT NULL
        ) td ON mhp2.PN_LAI_LICH_ID = td.PN_LAI_LICH_ID
        LEFT JOIN DM_TOI_DANHS dtd ON td.TD_ID = dtd.ID
        WHERE mhp2.PN_LAI_LICH_ID = p_PN_ID
        GROUP BY mhp2.PN_LAI_LICH_ID
    ) td_agg ON mhp.PN_LAI_LICH_ID = td_agg.PN_LAI_LICH_ID
    WHERE mhp.PN_LAI_LICH_ID = p_PN_ID;

    -- ===== ResultSet #17: HoanTHAs =====
    OPEN c17 FOR
    SELECT htha.PHAM_NHAN_ID, htha.SO_QUYET_DINH AS "SoQD", htha.NGAY_QUYET_DINH AS "NgayQD",
        dcq.CQ_TEN AS "ToaQD", htha.LY_DO_HOAN AS "LyDoHoan", htha.NGAY_THI_HANH_AN AS "NgayThiHanh"
    FROM HOAN_THI_HANH_ANS htha LEFT JOIN DM_CO_QUANS dcq ON htha.TOA_QUYET_DINH_ID = dcq.ID
    WHERE htha.PHAM_NHAN_ID = p_PN_ID;

    -- ===== ResultSet #18: TronTrai =====
    OPEN c18 FOR
    SELECT tt.PHAM_NHAN_ID, tt.NGAY_TRON AS "NgayTron", dtht.THT_TEN AS "TruongHopTron",
        tt.NGAY_BAT_LAI AS "NgayBat", dhtkl.HTKL_TEN AS "HinhThucXuLy"
    FROM TRON_TRAIS tt
    LEFT JOIN DM_TRUONG_HOP_TRONS dtht ON tt.TRUONG_HOP_TRON_ID = dtht.ID
    LEFT JOIN DM_HINH_THUC_KY_LUATS dhtkl ON tt.HINH_THUC_XU_LY_ID = dhtkl.ID
    WHERE tt.PHAM_NHAN_ID = p_PN_ID;

    -- ===== ResultSet #19: TrichXuat =====
    OPEN c19 FOR
    SELECT tx.PHAM_NHAN_ID, tx.TX_SO_LENH AS "SoLenh", tx.TX_NGAY_RA_LENH AS "NgayRaLenh",
        dmtg.MTG_TITLE AS "ThoiHan", tx.TX_TU_NGAY AS "TuNgay", dldtx.LDTX_TEN AS "LyDo", tx.TX_NGAY_TRA AS "NgayVe"
    FROM TRICH_XUATS tx
    LEFT JOIN DM_LY_DO_TRICH_XUATS dldtx ON tx.TX_LY_DO_ID = dldtx.ID
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON tx.TX_THOI_HAN_ID = dmtg.ID
    WHERE tx.PHAM_NHAN_ID = p_PN_ID;

    -- ===== ResultSet #20: TamDinhChi =====
    OPEN c20 FOR
    SELECT tdc.PHAM_NHAN_ID, tdc.TU_NGAY AS "TuNgay", dmtg.MTG_TITLE AS "ThoiHan",
        tdc.LY_DO_CHI_TIET AS "LyDo", tdc.NOI_VE_DIA_PHUONG_ID AS "NoiVe", tdc.NGAY_LAI AS "NgayLai"
    FROM TAM_DINH_CHIS tdc LEFT JOIN DM_MA_THOI_GIANS dmtg ON tdc.THOI_HAN_ID = dmtg.ID
    WHERE tdc.PHAM_NHAN_ID = p_PN_ID;

    -- ===== ResultSet #21: ChuaBenhBatBuoc =====
    OPEN c21 FOR
    SELECT cbbb.PHAM_NHAN_ID,
        (cbbb.SO_QUYET_DINH||', '||TO_CHAR(cbbb.NGAY_QUYET_DINH,'DD/MM/YYYY')) AS "SoQD",
        cbbb.THOI_HAN AS "ThoiHan", cbbb.TU_NGAY AS "TuNgay", cbbb.BENH_TAT_ID AS "MaBenhTat",
        cbbb.NGAY_BAT_DAU AS "NgayDi", cbbb.NGAY_KET_THUC AS "NgayVe"
    FROM CHUA_BENH_BAT_BUOCS cbbb WHERE cbbb.PHAM_NHAN_ID = p_PN_ID;

    -- ===== ResultSet #22: NghiemMaTuy =====
    OPEN c22 FOR
    SELECT pnm.NMT_PN_LAI_LICH_ID,
        cmt_agg.CHAT_MA_TUY AS "ChatMaTuy", htsd_agg.HINH_THUC_SD AS "HinhThuc",
        dccxdmt.CCXDMT_TEN AS "CanCuXacDinh", dmthnmt.THNMT_TEN AS "TruongHopNghien", pnm.NMT_GHI_CHU AS "GhiChu"
    FROM PN_NGHIEN_MT pnm
    LEFT JOIN (
        SELECT s.NMT_PN_LAI_LICH_ID, LISTAGG(DISTINCT dcmt.CMT_TEN,', ') WITHIN GROUP (ORDER BY dcmt.CMT_TEN) AS CHAT_MA_TUY
        FROM (
            SELECT pnm2.NMT_PN_LAI_LICH_ID, TO_NUMBER(REGEXP_SUBSTR(REPLACE(REPLACE(pnm2.NMT_CHAT_MA_TUY,'[',''),']',''),'[0-9]+',1,LEVEL)) AS CMT_ID
            FROM PN_NGHIEN_MT pnm2 WHERE pnm2.NMT_CHAT_MA_TUY IS NOT NULL AND pnm2.NMT_PN_LAI_LICH_ID = p_PN_ID
            CONNECT BY LEVEL <= REGEXP_COUNT(REPLACE(REPLACE(pnm2.NMT_CHAT_MA_TUY,'[',''),']',''),',')+1
            AND PRIOR pnm2.NMT_PN_LAI_LICH_ID = pnm2.NMT_PN_LAI_LICH_ID AND PRIOR SYS_GUID() IS NOT NULL
        ) s LEFT JOIN DM_CHAT_MA_TUIES dcmt ON dcmt.ID = s.CMT_ID GROUP BY s.NMT_PN_LAI_LICH_ID
    ) cmt_agg ON pnm.NMT_PN_LAI_LICH_ID = cmt_agg.NMT_PN_LAI_LICH_ID
    LEFT JOIN (
        SELECT s.NMT_PN_LAI_LICH_ID, LISTAGG(DISTINCT dhtsd.HTSDMT_TEN,', ') WITHIN GROUP (ORDER BY dhtsd.HTSDMT_TEN) AS HINH_THUC_SD
        FROM (
            SELECT pnm2.NMT_PN_LAI_LICH_ID, TO_NUMBER(REGEXP_SUBSTR(REPLACE(REPLACE(pnm2.NMT_HINH_THUC_SD,'[',''),']',''),'[0-9]+',1,LEVEL)) AS HTSD_ID
            FROM PN_NGHIEN_MT pnm2 WHERE pnm2.NMT_HINH_THUC_SD IS NOT NULL AND pnm2.NMT_PN_LAI_LICH_ID = p_PN_ID
            CONNECT BY LEVEL <= REGEXP_COUNT(REPLACE(REPLACE(pnm2.NMT_HINH_THUC_SD,'[',''),']',''),',')+1
            AND PRIOR pnm2.NMT_PN_LAI_LICH_ID = pnm2.NMT_PN_LAI_LICH_ID AND PRIOR SYS_GUID() IS NOT NULL
        ) s LEFT JOIN DM_HINH_THUC_SU_DUNG_MA_TUIES dhtsd ON dhtsd.ID = s.HTSD_ID GROUP BY s.NMT_PN_LAI_LICH_ID
    ) htsd_agg ON pnm.NMT_PN_LAI_LICH_ID = htsd_agg.NMT_PN_LAI_LICH_ID
    LEFT JOIN DM_MT_TRUONG_HOP_NGHIEN_MA_TUIES dmthnmt ON pnm.NMT_TRUONG_HOP_NGHIEN = dmthnmt.ID
    LEFT JOIN DM_CAN_CU_XAC_DINH_MA_TUIES dccxdmt ON pnm.NMT_CAN_CU_XAC_DINH = dccxdmt.ID
    WHERE pnm.NMT_PN_LAI_LICH_ID = p_PN_ID;

    -- RETURN ALL
    DBMS_SQL.RETURN_RESULT(c1); DBMS_SQL.RETURN_RESULT(c2); DBMS_SQL.RETURN_RESULT(c3); DBMS_SQL.RETURN_RESULT(c4);
    DBMS_SQL.RETURN_RESULT(c5); DBMS_SQL.RETURN_RESULT(c6); DBMS_SQL.RETURN_RESULT(c7); DBMS_SQL.RETURN_RESULT(c8);
    DBMS_SQL.RETURN_RESULT(c9); DBMS_SQL.RETURN_RESULT(c10); DBMS_SQL.RETURN_RESULT(c11); DBMS_SQL.RETURN_RESULT(c12);
    DBMS_SQL.RETURN_RESULT(c13); DBMS_SQL.RETURN_RESULT(c14); DBMS_SQL.RETURN_RESULT(c15); DBMS_SQL.RETURN_RESULT(c16);
    DBMS_SQL.RETURN_RESULT(c17); DBMS_SQL.RETURN_RESULT(c18); DBMS_SQL.RETURN_RESULT(c19); DBMS_SQL.RETURN_RESULT(c20);
    DBMS_SQL.RETURN_RESULT(c21); DBMS_SQL.RETURN_RESULT(c22);

EXCEPTION
    WHEN NO_DATA_FOUND THEN NULL;
    WHEN TOO_MANY_ROWS THEN RAISE_APPLICATION_ERROR(-20001,'Co nhieu hon 1 ban ghi cho PN ID: '||p_PN_ID);
    WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('Error: '||SQLCODE||' - '||SQLERRM); RAISE;
END SP_GET_ALL_PN_INFO;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_AN_GIAM
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_AN_GIAM" (
    p_PHAM_NHAN_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 

        ag.PHAM_NHAN_ID, 
        ag.AG_SO_QD_TOA_AN  AS "SoQD",
        ag.AG_NGAY_QD_TOA_AN  AS "NgayQD",
        ag.AG_LY_DO_AN_GIAM   AS "LyDoAnGiam",
        ag.AG_GHI_CHU  AS "ChuThich"
    FROM AN_GIAMS ag
    WHERE ag.PHAM_NHAN_ID = p_PHAM_NHAN_ID;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_AN_GIAM;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAN_AN_KHAC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAN_AN_KHAC" (
    p_LAI_LICH_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        pbak.BAK_PN_LAI_LICH_ID,
        pbak.BAK_SO_BAN_AN  AS "BanAnSo",
        TO_CHAR(pbak.BAK_NGAY_BAN_AN, 'DD/MM/YYYY')  AS "Ngay",
        dctx.CTX_TEN   AS "CapXu",
        dctx2.CTX_TEN   AS "ToaXu",
        dtd.TD_TEN  AS "ToiDanh",
        dma.MA_TEN_CHI_TIEU  AS "MucAn"
    FROM PN_BAN_AN_KHACS pbak 
    LEFT JOIN DM_CAP_TOA_XUS dctx ON pbak.BAK_CAP_TOA_XU_ID = dctx.ID 
    LEFT JOIN DM_CAP_TOA_XUS dctx2 ON pbak.BAK_TOA_XU_ID = dctx2.ID
    LEFT JOIN DM_TOI_DANHS dtd ON pbak.BAK_TOI_DANH_ID = dtd.ID 
    LEFT JOIN DM_MUC_ANS dma ON pbak.BAK_MUC_AN_ID = dma.ID
    WHERE pbak.BAK_PN_LAI_LICH_ID = p_LAI_LICH_ID;
--	AND pbak.IS_DELETED = 0;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_BAN_AN_KHAC;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAN_GIAO_PN_CHXAPT_QUAN_CHE_PT76
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAN_GIAO_PN_CHXAPT_QUAN_CHE_PT76" (
--    p_pham_nhan_id  IN VARCHAR2 DEFAULT NULL,
    p_ma_trai_giam  IN VARCHAR2 DEFAULT NULL
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
        PN_ID_LIST AS (
   		
        SELECT PN_ID 
    	FROM QLPN.GTT_PN_IDS
    	),
--    pn_filter AS (
--        SELECT /*+ MATERIALIZE */
--            TO_NUMBER(TRIM(REGEXP_SUBSTR(p_pham_nhan_id, '[^,]+', 1, LEVEL))) AS pn_id
--        FROM DUAL
--        WHERE p_pham_nhan_id IS NOT NULL
--        CONNECT BY NOCYCLE LEVEL <= REGEXP_COUNT(p_pham_nhan_id, ',') + 1
--    ),
    quan_che_pn AS (
        SELECT /*+ MATERIALIZE */ DISTINCT
               hp.HPBS_MA_PHAM_NHAN AS PHAM_NHAN_ID
        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
        INNER JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
            ON dm.ID = hp.HPBS_HINH_PHAT
           AND NVL(dm.IS_DELETED, 0) = 0
           AND dm.HPBS_MA = '120'
        WHERE NVL(hp.IS_DELETED, 0) = 0
    ),
    vw_core AS (
        SELECT /*+ MATERIALIZE */ v.*
        FROM QLPN.VW_PN_LAI_LICH_CHI_TIET v
        INNER JOIN quan_che_pn qc ON qc.PHAM_NHAN_ID = v.PHAM_NHAN_ID
        INNER JOIN PN_ID_LIST pil ON pil.PN_ID = qc.PHAM_NHAN_ID
        WHERE NVL(v.IS_DELETED, 0) = 0
          -- AND (p_pham_nhan_id IS NULL OR EXISTS (SELECT 1 FROM pn_filter f WHERE f.pn_id = v.PHAM_NHAN_ID))
          AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_MA = p_ma_trai_giam)
    ),
    kt_one AS (
        SELECT k.KTRT_PN_LAI_LICH_ID, k.KTRT_NGAY_THA
        FROM (
            SELECT k0.KTRT_PN_LAI_LICH_ID,
                   k0.KTRT_NGAY_THA,
                   ROW_NUMBER() OVER (
                       PARTITION BY k0.KTRT_PN_LAI_LICH_ID
                       ORDER BY NVL(k0.KTRT_NGAY_THA, k0.CREATION_TIME) DESC NULLS LAST
                   ) AS rn
            FROM QLPN.PN_KET_THUC_RA_TRAIS k0
            WHERE NVL(k0.IS_DELETED, 0) = 0
              AND EXISTS (SELECT 1 FROM vw_core b WHERE b.PHAM_NHAN_ID = k0.KTRT_PN_LAI_LICH_ID)
        ) k
        WHERE k.rn = 1
    ),
    than_nhan_agg AS (
        SELECT /*+ MATERIALIZE */
            tn.PHAM_NHAN_ID,
            MAX(CASE WHEN qh.QHVPN_MA = '121' THEN tn.HO_TEN_THAN_NHAN END) AS HO_TEN_BO,
            MAX(CASE WHEN qh.QHVPN_MA = '122' THEN tn.HO_TEN_THAN_NHAN END) AS HO_TEN_ME,
            COALESCE(
                MAX(CASE WHEN qh.QHVPN_MA = '132' THEN tn.HO_TEN_THAN_NHAN END),
                MAX(CASE WHEN qh.QHVPN_MA = '131' THEN tn.HO_TEN_THAN_NHAN END)
            ) AS HO_TEN_VC
        FROM QLPN.THAN_NHAN_NGUOI_THANS tn
        INNER JOIN QLPN.DM_QUAN_HE_VOI_PHAM_NHANS qh
            ON qh.ID = tn.QUAN_HE_ID
           AND NVL(qh.IS_DELETED, 0) = 0
           AND qh.QHVPN_MA IN ('121', '122', '131', '132')
        WHERE NVL(tn.IS_DELETED, 0) = 0
          AND EXISTS (SELECT 1 FROM vw_core b WHERE b.PHAM_NHAN_ID = tn.PHAM_NHAN_ID)
        GROUP BY tn.PHAM_NHAN_ID
    ),
    con_cai_agg AS (
        SELECT /*+ MATERIALIZE */
            tn.PHAM_NHAN_ID,
            LISTAGG(
                NULLIF(TRIM(CAST(tn.HO_TEN_THAN_NHAN AS NVARCHAR2(500))), u''),
                u'; '
            ) WITHIN GROUP (ORDER BY tn.ID) AS HO_TEN_CON
        FROM QLPN.THAN_NHAN_NGUOI_THANS tn
        INNER JOIN QLPN.DM_QUAN_HE_VOI_PHAM_NHANS qh
            ON qh.ID = tn.QUAN_HE_ID
           AND NVL(qh.IS_DELETED, 0) = 0
           AND qh.QHVPN_MA = '151'
        WHERE NVL(tn.IS_DELETED, 0) = 0
          AND EXISTS (SELECT 1 FROM vw_core b WHERE b.PHAM_NHAN_ID = tn.PHAM_NHAN_ID)
        GROUP BY tn.PHAM_NHAN_ID
    ),
    scalar_fns AS (
        SELECT /*+ MATERIALIZE */
            b.PHAM_NHAN_ID,
            COALESCE(TRUNC(kt.KTRT_NGAY_THA), TRUNC(b.NGAY_HET_AN), TRUNC(SYSDATE)) AS ngay_moc,
            QLPN.PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(b.PHAM_NHAN_ID) AS giam_an_hien_thi
        FROM vw_core b
        LEFT JOIN kt_one kt ON kt.KTRT_PN_LAI_LICH_ID = b.PHAM_NHAN_ID
    )
    SELECT
        b.PHAM_NHAN_ID,
        NVL(TRIM(CAST(b.HO_TEN AS NVARCHAR2(500))), u'') AS HO_TEN,
        NVL(TRIM(CAST(b.GIOI_TINH AS NVARCHAR2(100))), u'') AS GIOI_TINH,
        CASE
            WHEN b.NGAY_SINH IS NOT NULL
                 AND REGEXP_LIKE(TRIM(CAST(b.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(CAST(b.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN b.NAM_SINH IS NOT NULL AND b.NAM_SINH > 0 THEN TO_CHAR(b.NAM_SINH)
            WHEN b.NGAY_SINH IS NOT NULL THEN TRIM(CAST(b.NGAY_SINH AS VARCHAR2(100)))
            ELSE NULL
        END AS NGAY_SINH,
        NVL(TRIM(CAST(b.TEN_KHAC AS NVARCHAR2(500))), u'') AS TEN_KHAC,
        NVL(TRIM(CAST(b.NGUYEN_QUAN AS NVARCHAR2(4000))), u'') AS NGUYEN_QUAN,
        NVL(TRIM(CAST(tna.HO_TEN_BO AS NVARCHAR2(500))), u'') AS HO_TEN_BO,
        NVL(TRIM(CAST(tna.HO_TEN_ME AS NVARCHAR2(500))), u'') AS HO_TEN_ME,
        NVL(TRIM(CAST(tna.HO_TEN_VC AS NVARCHAR2(500))), u'') AS HO_TEN_VC,
        NVL(TRIM(CAST(cc.HO_TEN_CON AS NVARCHAR2(4000))), u'') AS HO_TEN_CON,
        NVL(TRIM(CAST(NVL(b.NOI_THUONG_TRU_DAY_DU, b.DIA_CHI_THUONG_TRU) AS NVARCHAR2(4000))), u'') AS NOI_THUONG_TRU,
        NVL(TRIM(CAST(b.CCCD AS VARCHAR2(100))), '') AS SO_CCCD,
        NVL(TRIM(CAST(ll.LL_NGAY_CAP_CCCD AS NVARCHAR2(4000))), u'') AS NGAY_CAP_CCCD,
        NVL(TRIM(CAST(ll.LL_NOI_CAP_CCCD AS NVARCHAR2(4000))), u'') AS NOI_CAP_CCCD,
        COALESCE(
            NULLIF(TRIM(CAST(b.TOI_DANH AS NVARCHAR2(4000))), u''),
            CAST(u'Ch\01b0a x\00e1c \0111\1ecbnh' AS NVARCHAR2(200))
        ) AS TOI_DANH,
        TO_CHAR(TRUNC(b.NGAY_BAT_AN_PHAT), 'DD/MM/YYYY') AS NGAY_BAT,
        NVL(NULLIF(TRIM(CAST(b.AN_PHAT AS NVARCHAR2(4000))), u''), NVL(CAST(mta_phat.MTG_TITLE AS NVARCHAR2(500)), u'')) AS AN_PHAT,
        NVL(TRIM(CAST(b.SO_BAN_AN AS VARCHAR2(500))), '') AS BAN_AN_SO,
        TO_CHAR(TRUNC(b.NGAY_BAN_AN), 'DD/MM/YYYY') AS NGAY_BAN_AN,
        NVL(TRIM(CAST(b.TOA_XU_TEN AS NVARCHAR2(500))), u'') AS TOA_XU_BAN_AN,
        NVL(TRIM(CAST(b.TOA_XU_DIA_PHUONG AS NVARCHAR2(500))), u'') AS DIA_PHUONG_TOA_XU_BAN_AN,
        NVL(TRIM(CAST(b.SO_QD_THA AS VARCHAR2(500))), '') AS SO_QD_THA,
        TO_CHAR(TRUNC(b.NGAY_QD_THA), 'DD/MM/YYYY') AS NGAY_QD_THA,
        NVL(TRIM(CAST(b.CO_QUAN_QD_THA AS NVARCHAR2(500))), u'') AS CO_QUAN_QD_THA,
        NVL(TRIM(CAST(b.TOA_QD_THA_DIA_PHUONG AS NVARCHAR2(500))), u'') AS DIA_PHUONG_CO_QUAN_QD_THA,
        TO_CHAR(TRUNC(b.NGAY_DEN_TRAI), 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
        TO_CHAR(TRUNC(b.NGAY_HET_AN), 'DD/MM/YYYY') AS NGAY_HET_HAN,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(b.PHAM_NHAN_ID, fn.ngay_moc), u'') AS THOI_GIAN_DA_CHAP_HANH,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(b.PHAM_NHAN_ID, fn.ngay_moc), u'') AS THOI_GIAN_CON_LAI,
        NVL(CAST(fn.giam_an_hien_thi AS NVARCHAR2(500)), u'Kh\00f4ng') AS GIAM_AN_HIEN_THI,
        NVL(TRIM(CAST(b.TT_SUC_KHOE_HIEN_TAI AS NVARCHAR2(500))), u'') AS TINH_TRANG_SUC_KHOE_HIEN_TAI,
        NVL(TRIM(CAST(b.NOI_THA_VE_CU_TRU AS NVARCHAR2(2000))), u'') AS NOI_VE_CU_TRU
    FROM vw_core b
    LEFT JOIN QLPN.PN_LAI_LICHS ll
        ON ll.ID = b.PHAM_NHAN_ID
       AND NVL(ll.IS_DELETED, 0) = 0
    LEFT JOIN than_nhan_agg tna ON tna.PHAM_NHAN_ID = b.PHAM_NHAN_ID
    LEFT JOIN con_cai_agg cc ON cc.PHAM_NHAN_ID = b.PHAM_NHAN_ID
    LEFT JOIN scalar_fns fn ON fn.PHAM_NHAN_ID = b.PHAM_NHAN_ID
    LEFT JOIN QLPN.DM_MA_THOI_GIANS mta_phat
        ON mta_phat.ID = b.MUC_AN_ID
       AND NVL(mta_phat.IS_DELETED, 0) = 0
    ORDER BY b.HO_TEN_ORDER, b.PHAM_NHAN_ID;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, u'L\1ed7i khi l\1ea5y danh s\00e1ch b\00e0n giao PN CHXAPT c\00f3 HPBS qu\1ea3n ch\1ebf: ' || SQLERRM);
END SP_GET_BAN_GIAO_PN_CHXAPT_QUAN_CHE_PT76;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_CON_THEO_CM_VAO_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_CON_THEO_CM_VAO_TRAI" (
p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
p_me_vao_trai_tu_ngay      IN  VARCHAR2  DEFAULT NULL,
p_me_vao_trai_den_ngay      IN  VARCHAR2  DEFAULT NULL,
p_me_ra_trai_tu_ngay      IN  VARCHAR2  DEFAULT NULL,
p_me_ra_trai_den_ngay      IN  VARCHAR2  DEFAULT NULL,
p_con_vao_trai_tu_ngay      IN  VARCHAR2  DEFAULT NULL,
p_con_vao_trai_den_ngay      IN  VARCHAR2  DEFAULT NULL,
p_con_ra_trai_tu_ngay      IN  VARCHAR2  DEFAULT NULL,
p_con_ra_trai_den_ngay      IN  VARCHAR2  DEFAULT NULL,
p_trang_thai_me_id IN  NUMBER    DEFAULT NULL,
p_phan_doi_id IN  NUMBER    DEFAULT NULL,
p_tinh_trang_con_id IN  NUMBER    DEFAULT NULL,
p_thang_tuoi_con_id IN  NUMBER    DEFAULT NULL,
p_maxresultcount IN  NUMBER    DEFAULT NULL,
p_skipcount      IN  NUMBER    DEFAULT 0  
)
AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_trai_giam_id NUMBER;

v_me_vao_trai_tu_ngay   DATE;
v_me_vao_trai_den_ngay  DATE;
v_me_ra_trai_tu_ngay    DATE;
v_me_ra_trai_den_ngay   DATE;
v_con_vao_trai_tu_ngay  DATE;
v_con_vao_trai_den_ngay DATE;
v_con_ra_trai_tu_ngay   DATE;
v_con_ra_trai_den_ngay  DATE;

    C1 SYS_REFCURSOR;  
BEGIN

    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
      IF p_ma_trai_giam IS NULL OR p_ma_trai_giam = '' THEN
        v_trai_giam_id := NULL;
    ELSE
        v_trai_giam_id := p_ma_trai_giam;
    END IF;
 IF p_me_vao_trai_tu_ngay IS NULL OR TRIM(p_me_vao_trai_tu_ngay) = '' THEN
    v_me_vao_trai_tu_ngay := NULL;
ELSE
    v_me_vao_trai_tu_ngay := TO_DATE(TRIM(p_me_vao_trai_tu_ngay), 'DD/MM/YYYY');
END IF;                                        

IF p_me_vao_trai_den_ngay IS NULL OR TRIM(p_me_vao_trai_den_ngay) = '' THEN
    v_me_vao_trai_den_ngay := NULL;
ELSE
    v_me_vao_trai_den_ngay := TO_DATE(TRIM(p_me_vao_trai_den_ngay), 'DD/MM/YYYY');
END IF;

IF p_me_ra_trai_tu_ngay IS NULL OR TRIM(p_me_ra_trai_tu_ngay) = '' THEN
    v_me_ra_trai_tu_ngay := NULL;
ELSE
    v_me_ra_trai_tu_ngay := TO_DATE(TRIM(p_me_ra_trai_tu_ngay), 'DD/MM/YYYY');
END IF;

IF p_me_ra_trai_den_ngay IS NULL OR TRIM(p_me_ra_trai_den_ngay) = '' THEN
    v_me_ra_trai_den_ngay := NULL;
ELSE
    v_me_ra_trai_den_ngay := TO_DATE(TRIM(p_me_ra_trai_den_ngay), 'DD/MM/YYYY');
END IF;

IF p_con_vao_trai_tu_ngay IS NULL OR TRIM(p_con_vao_trai_tu_ngay) = '' THEN
    v_con_vao_trai_tu_ngay := NULL;
ELSE
    v_con_vao_trai_tu_ngay := TO_DATE(TRIM(p_con_vao_trai_tu_ngay), 'DD/MM/YYYY');
END IF;

IF p_con_vao_trai_den_ngay IS NULL OR TRIM(p_con_vao_trai_den_ngay) = '' THEN
    v_con_vao_trai_den_ngay := NULL;
ELSE
    v_con_vao_trai_den_ngay := TO_DATE(TRIM(p_con_vao_trai_den_ngay), 'DD/MM/YYYY');
END IF;

IF p_con_ra_trai_tu_ngay IS NULL OR TRIM(p_con_ra_trai_tu_ngay) = '' THEN
    v_con_ra_trai_tu_ngay := NULL;
ELSE
    v_con_ra_trai_tu_ngay := TO_DATE(TRIM(p_con_ra_trai_tu_ngay), 'DD/MM/YYYY');
END IF;

IF p_con_ra_trai_den_ngay IS NULL OR TRIM(p_con_ra_trai_den_ngay) = '' THEN
    v_con_ra_trai_den_ngay := NULL;
ELSE
    v_con_ra_trai_den_ngay := TO_DATE(TRIM(p_con_ra_trai_den_ngay), 'DD/MM/YYYY');
END IF;

      OPEN C1 FOR

WITH TN_FIX AS (
    SELECT
        tn.*,
        TRIM(tn.ngay_sinh) AS ngay_sinh_raw,
        CASE
    WHEN tn.ngay_sinh IS NULL OR TRIM(tn.ngay_sinh) IS NULL THEN NULL

    -- YYYY
    WHEN REGEXP_LIKE(TRIM(tn.ngay_sinh), '^\d{4}$') THEN
        TO_DATE('01/01/' || TRIM(tn.ngay_sinh), 'DD/MM/YYYY')

    -- MM/YYYY
    WHEN REGEXP_LIKE(TRIM(tn.ngay_sinh), '^\d{2}/\d{4}$') THEN
        TO_DATE('01/' || TRIM(tn.ngay_sinh), 'DD/MM/YYYY')

    -- DD/MM/YYYY
    WHEN REGEXP_LIKE(TRIM(tn.ngay_sinh), '^\d{2}/\d{2}/\d{4}$') THEN
        TO_DATE(TRIM(tn.ngay_sinh), 'DD/MM/YYYY')

    ELSE NULL
END AS ngay_sinh_dt,

CASE
    WHEN REGEXP_LIKE(TRIM(tn.ngay_sinh), '^\d{4}$') THEN 1
    WHEN REGEXP_LIKE(TRIM(tn.ngay_sinh), '^\d{2}/\d{4}$') THEN 2
    WHEN REGEXP_LIKE(TRIM(tn.ngay_sinh), '^\d{2}/\d{2}/\d{4}$') THEN 3
    ELSE 0
END AS loai_ngay_sinh,
        CASE
            WHEN REGEXP_LIKE(TRIM(tn.ngay_sinh), '^\d{4}$') THEN 1
            ELSE 0
        END AS chi_co_nam
    FROM than_nhan_con_cais tn
    WHERE NVL(TN.IS_DELETED,0) = 0
),
TUOI_FIX AS (
--    SELECT
--        tn.*,
--        CASE
--            WHEN tn.ngay_sinh_dt IS NOT NULL
--                THEN FLOOR(MONTHS_BETWEEN(TRUNC(SYSDATE), tn.ngay_sinh_dt) / 12)
--        END AS tuoi_nam,
--        CASE
--            WHEN tn.ngay_sinh_dt IS NOT NULL
--                THEN MOD(FLOOR(MONTHS_BETWEEN(TRUNC(SYSDATE), tn.ngay_sinh_dt)), 12)
--        END AS tuoi_thang,
--        CASE
--            WHEN tn.ngay_sinh_dt IS NOT NULL
--                THEN TRUNC(
--                    TRUNC(SYSDATE)
--                    - ADD_MONTHS(
--                        tn.ngay_sinh_dt,
--                        FLOOR(MONTHS_BETWEEN(TRUNC(SYSDATE), tn.ngay_sinh_dt))
--                    )
--                )
--        END AS tuoi_ngay
--    FROM TN_FIX tn

    SELECT
    tn.*,

    -- TU?I N?M
    CASE 
        WHEN tn.loai_ngay_sinh = 1 THEN 
            EXTRACT(YEAR FROM SYSDATE) - EXTRACT(YEAR FROM tn.ngay_sinh_dt)

        WHEN tn.loai_ngay_sinh IN (2,3) THEN 
            FLOOR(MONTHS_BETWEEN(TRUNC(SYSDATE), tn.ngay_sinh_dt) / 12)
    END AS tuoi_nam,

    -- TU?I THÁNG
    CASE 
        WHEN tn.loai_ngay_sinh = 1 THEN 0

        WHEN tn.loai_ngay_sinh IN (2,3) THEN 
            MOD(FLOOR(MONTHS_BETWEEN(TRUNC(SYSDATE), tn.ngay_sinh_dt)), 12)
    END AS tuoi_thang,

    -- TU?I NGÀY
    CASE 
        WHEN tn.loai_ngay_sinh IN (1,2) THEN 0

        WHEN tn.loai_ngay_sinh = 3 THEN 
            TRUNC(
                TRUNC(SYSDATE)
                - ADD_MONTHS(
                    tn.ngay_sinh_dt,
                    FLOOR(MONTHS_BETWEEN(TRUNC(SYSDATE), tn.ngay_sinh_dt))
                )
            )
    END AS tuoi_ngay

FROM TN_FIX tn
)
select * from (
SELECT
--ROW_NUMBER() OVER (ORDER BY LL.ho_ten, MTG_MA NULLS LAST) AS rn_all,
ROW_NUMBER() OVER (ORDER BY   ORDER_HOTEN(LL.HO_TEN) NULLS LAST) AS rn_all,
COUNT(*) OVER() AS total_count,
    LL.ho_ten,
    LL.nam_sinh,
    LL.ngay_sinh AS NGAY_SINH_PN,
    LL.gioi_tinh,
    LL.noi_thuong_tru_day_du,
    LL.toi_danh,
    LL.an_phat,
    --LL.ngay_bat_an_phat,
    TO_CHAR(LL.ngay_bat_an_phat, 'DD/mm/yyyy') AS ngay_bat_an_phat,
    --LL.ngay_den_trai,
    TO_CHAR(LL.ngay_den_trai, 'DD/mm/yyyy') AS ngay_den_trai,
    --LL.ngay_het_an,
    TO_CHAR(LL.ngay_het_an, 'DD/mm/yyyy') AS ngay_het_an,
    b.ttpn_ten AS trang_thai,
    	        -- PHAN_DOI: phân ??i, phân tr?i
	        NVL(TRIM(CAST(ll.PHAN_DOI AS VARCHAR2(4000))), '') ||
	        CASE WHEN ll.PHAN_DOI IS NOT NULL AND ll.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
	        NVL(TRIM(CAST(ll.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI,
    TN.ho_ten_con,
    TN.ngay_sinh,
    --TN.ngay_den,
    TO_CHAR(TN.ngay_den, 'DD/mm/yyyy') AS ngay_den,
    --TN.ngay_ra AS ngay_di,
    TO_CHAR(TN.ngay_ra, 'DD/mm/yyyy') AS ngay_di,
    tr.ttctmvt_ten AS tinh_trang_con
FROM TUOI_FIX TN
INNER JOIN vw_pn_lai_lich_chi_tiet LL
    ON TN.pham_nhan_id = LL.pham_nhan_id
LEFT JOIN DM_TINH_TRANG_PHAM_NHANS b
    ON LL.LL_TINH_TRANG_ID = b.ID and b.is_deleted= 0
LEFT JOIN DM_TINH_TRANG_CON_THEO_ME_VAO_TRAIES tr
    ON TN.TINH_TRANG_ID = tr.ID and tr.is_deleted= 0
INNER JOIN (
    SELECT tha.tha_pnlai_lich_id
    FROM PN_THI_HANH_AN tha
    WHERE NVL(tha.is_deleted, 0) = 0
      AND tha.tha_pnlai_lich_id IS NOT NULL
) t
    ON t.tha_pnlai_lich_id = LL.PHAM_NHAN_ID
--LEFT JOIN DM_MA_THOI_GIANS DMTG
--    ON DMTG.MTG_THANG = (NVL(TN.tuoi_nam, 0) * 12 + NVL(TN.tuoi_thang, 0))
--   AND DMTG.MTG_NGAY  = NVL(TN.tuoi_ngay, 0)

WHERE 1 = 1
AND LL.gioi_tinh = 'N?'

 AND (v_me_vao_trai_tu_ngay  IS NULL OR TRUNC(LL.ngay_den_trai) >= v_me_vao_trai_tu_ngay)
AND (v_me_vao_trai_den_ngay IS NULL OR TRUNC(LL.ngay_den_trai) <= v_me_vao_trai_den_ngay)

AND (v_me_ra_trai_tu_ngay   IS NULL OR TRUNC(LL.ngay_het_an)   >= v_me_ra_trai_tu_ngay)
AND (v_me_ra_trai_den_ngay  IS NULL OR TRUNC(LL.ngay_het_an)   <= v_me_ra_trai_den_ngay)

AND (v_con_vao_trai_tu_ngay  IS NULL OR TRUNC(TN.ngay_den) >= v_con_vao_trai_tu_ngay)
AND (v_con_vao_trai_den_ngay IS NULL OR TRUNC(TN.ngay_den) <= v_con_vao_trai_den_ngay)

AND (v_con_ra_trai_tu_ngay   IS NULL OR TRUNC(TN.ngay_ra) >= v_con_ra_trai_tu_ngay)
AND (v_con_ra_trai_den_ngay  IS NULL OR TRUNC(TN.ngay_ra) <= v_con_ra_trai_den_ngay)
AND (p_ma_trai_giam IS NULL  OR (TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))

and (p_trang_thai_me_id is null or b.id = p_trang_thai_me_id)
AND (p_tinh_trang_con_id is null or TR.id = p_tinh_trang_con_id)
AND (p_phan_doi_id is null or LL.PHAN_DOI_ID = p_phan_doi_id)
--AND (p_thang_tuoi_con_id is null or DMTG.ID = p_thang_tuoi_con_id)
AND (p_thang_tuoi_con_id IS NULL OR
(p_thang_tuoi_con_id = 1 AND TN.tuoi_nam < 2  )--D??I 24 THÁNG TU?I
OR (p_thang_tuoi_con_id = 2 AND TN.tuoi_nam <3 AND TN.tuoi_nam >=2 )-- T? 24-D??I 36 THÁNG TU?I
OR (p_thang_tuoi_con_id = 3 AND TN.tuoi_nam >= 3  )-- T? 36 THÁNG TU?I TR? LÊN 
)
)
        -- AND (v_trai_giam_id IS NULL  OR LL.TRAI_GIAM_ID = v_trai_giam_id)
    WHERE  rn_all > v_skip
      AND (v_limit = 0 OR rn_all <= v_skip + v_limit)
    ORDER BY rn_all ;
        -- AND   ((LL.LAST_MODIFICATION_TIME IS NOT NULL AND LL.LAST_MODIFICATION_TIME BETWEEN TO_TIMESTAMP(v_tu_ngay, 'DD/MM/YYYY') AND  TO_TIMESTAMP(v_den_ngay, 'DD/MM/YYYY'))
        --OR  ( LL.CREATION_TIME BETWEEN TO_TIMESTAMP(v_tu_ngay, 'DD/MM/YYYY') AND  TO_TIMESTAMP(v_den_ngay, 'DD/MM/YYYY')))

      DBMS_SQL.RETURN_RESULT(C1);
END;



