AND (p_tinh_trang_id IS NULL OR dmttpn.ID = p_tinh_trang_id)
AND (p_phan_doi_id IS NULL OR ll.PHAN_DOI_ID = p_phan_doi_id)
AND (p_tinh_trang_giam_an IS NULL OR 
