OR (p_tinh_trang_giam_an = 2 AND PHAM_NHAN_ID IN (SELECT PHAM_NHAN_ID FROM GIAM_THOI_HANS WHERE MUC_GIAM_ID IS NOT NULL)) )
--AND (
--    p_tinh_trang_giam_an IS NULL
--    OR (
--        p_tinh_trang_giam_an = 0
--        AND (
--            NOT EXISTS (
--                SELECT 1 
