;

      DBMS_SQL.RETURN_RESULT(C1);
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DANH_SACH_TRICH_XUAT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DANH_SACH_TRICH_XUAT" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL, 
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY
    p_tra_lai_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_tra_lai_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY    
    p_ly_do_id IN  NUMBER    DEFAULT NULL,
    p_loai_lenh_tx IN  NUMBER    DEFAULT NULL,
    p_ban_giao_tx IN  NUMBER    DEFAULT NULL,
    p_tinh_trang_tx IN  NUMBER    DEFAULT NULL,
    --p_phan_doi_id IN  NUMBER    DEFAULT NULL,
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT 0         
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_trai_giam_id NUMBER;
    v_tu_ngay   DATE;
    v_den_ngay  DATE;
    v_tra_lai_tu_ngay   DATE;
    v_tra_lai_den_ngay  DATE;    
    c1          SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
     IF p_ma_trai_giam IS NULL OR p_ma_trai_giam = '' THEN
        v_trai_giam_id := NULL;
    ELSE
        v_trai_giam_id := p_ma_trai_giam;
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_tra_lai_tu_ngay IS NULL OR TRIM(p_tra_lai_tu_ngay) = '' THEN
        v_tra_lai_tu_ngay := NULL;
    ELSE
        v_tra_lai_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_tra_lai_den_ngay IS NULL OR TRIM(p_tra_lai_den_ngay) = '' THEN
        v_tra_lai_den_ngay := NULL;
    ELSE
        v_tra_lai_den_ngay := TO_DATE(TRIM(p_tra_lai_den_ngay), 'DD/MM/YYYY');
    END IF;    

    OPEN c1 FOR
    WITH
    -- PN có trích xu?t trong kho?ng ngày (dùng cho gcr)
    tx_pn AS (
        SELECT DISTINCT tx.PHAM_NHAN_ID
        FROM TRICH_XUATS tx
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET v ON v.PHAM_NHAN_ID = tx.PHAM_NHAN_ID AND NVL(v.IS_DELETED, 0) = 0
        WHERE NVL(tx.IS_DELETED, 0) = 0
        AND tx.TX_NGAY_TRICH_XUAT IS NOT NULL
        --AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_ID = p_ma_trai_giam)
        AND (v_tu_ngay IS NULL OR   tx.TX_NGAY_TRICH_XUAT  >=  v_tu_ngay) 
        AND (v_den_ngay IS NULL OR         tx.TX_NGAY_TRICH_XUAT  <=  v_den_ngay)  
        AND (v_tra_lai_tu_ngay IS NULL OR  tx.TX_NGAY_TRA  >=  v_tra_lai_tu_ngay) 
        AND (v_tra_lai_den_ngay IS NULL OR  tx.TX_NGAY_TRA  <= v_tra_lai_den_ngay)   
        and (p_tinh_trang_tx  IS NULL OR p_tinh_trang_tx = TX_TINH_TRANG_ID)
        and (p_ly_do_id  IS NULL OR p_ly_do_id =  TX_LY_DO_ID )
        and (p_loai_lenh_tx  IS NULL OR p_loai_lenh_tx = TX_LOAI_LENH_ID )
        and (p_ban_giao_tx  IS NULL OR p_ban_giao_tx = TX_BAN_GIAO_ID )          
    ),
    -- Ghi chú riêng Lai l?ch: parse LL_GHI_CHU_RIENG (chu?i id) ? map DM_GHI_CHU_RIENGS.GCR_TEN
    gcr_raw AS (
        SELECT v.PHAM_NHAN_ID,
               REGEXP_REPLACE(NVL(TRIM(CAST(v.GHI_CHU_RIENG AS VARCHAR2(4000))), u''), '[[:space:]\[\]]', u'') AS gcr_clean
        FROM VW_PN_LAI_LICH_CHI_TIET v
        INNER JOIN tx_pn tp ON tp.PHAM_NHAN_ID = v.PHAM_NHAN_ID
        WHERE v.GHI_CHU_RIENG IS NOT NULL
          AND REGEXP_COUNT(REGEXP_REPLACE(NVL(TRIM(CAST(v.GHI_CHU_RIENG AS VARCHAR2(4000))), u''), '[[:space:]\[\]]', u''), '[0-9]+') > 0
          AND NVL(v.IS_DELETED, 0) = 0
    ),
    gcr_ids AS (
        SELECT r.PHAM_NHAN_ID,
               TO_NUMBER(REGEXP_SUBSTR(r.gcr_clean, '[0-9]+', 1, LEVEL)) AS gcr_id,
               LEVEL AS ord
        FROM gcr_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.gcr_clean, '[0-9]+')
          AND PRIOR r.PHAM_NHAN_ID = r.PHAM_NHAN_ID
          AND PRIOR SYS_GUID() IS NOT NULL
    ),
    gcr_agg AS (
        SELECT ids.PHAM_NHAN_ID,
               SUBSTR(LISTAGG(CAST(g.GCR_TEN AS VARCHAR2(500)), ', ') WITHIN GROUP (ORDER BY ids.ord), 1, 2000) AS ghi_chu_rieng_ten
        FROM gcr_ids ids
        JOIN DM_GHI_CHU_RIENGS g ON g.ID = ids.gcr_id AND NVL(g.IS_DELETED, 0) = 0
        GROUP BY ids.PHAM_NHAN_ID
    ),
    -- M?t LL m?i nh?t m?i PN (tránh dup t? VW_PN_LAI_LICH_CHI_TIET)
    LL_one AS (
        SELECT * FROM (
            SELECT v.* 
            FROM VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
             AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
        ) x  
    )
    SELECT * FROM (
    SELECT
         COUNT(*) OVER() AS total_count,          
        v.SO_HO_SO                    AS SO_HSLD,
        -- H? TÊN: h? tên, gi?i tính-n?m sinh (vd: TH?CH LÂM, Nam-1991)
        v.HO_TEN AS HO_TEN,
        v.NGAY_SINH,
        v.NAM_SINH,
        V.GIOI_TINH,
        NVL(TRIM(CAST(v.NOI_THUONG_TRU_DAY_DU AS NVARCHAR2(2000))), u'') AS DIA_CHI_THUONG_TRU,
        NVL(TRIM(CAST(v.TOI_DANH AS NVARCHAR2(2000))), u'') AS TOI_DANH,
        -- S? TA: s? th? án (SO_BAN_AN ho?c SO_HO_SO)
        NVL(TRIM(CAST(v.SO_BAN_AN AS NVARCHAR2(100))), NVL(TRIM(CAST(v.SO_HO_SO AS NVARCHAR2(100))), u'')) AS SO_TA,
        --v.NGAY_BAT_AN_PHAT AS NGAY_BAT,
        TO_CHAR(v.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT,
        v.AN_PHAT AS AN_PHAT,
        --V.NGAY_DEN_TRAI,
        TO_CHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
        CQ_TEN CO_QUAN_DE_NGHI, 
        -- NGÀY VÀO PHÂN ??I: ngày ??n tr?i, ??i X, Phân tr?i Y (vd: 05/09/2014, ??i 27, Phân tr?i S? 1)
--        NVL(CAST(TO_CHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NVARCHAR2(20)), u'') ||
--        CASE WHEN v.PHAN_DOI IS NOT NULL OR v.PHAN_TRAI IS NOT NULL
--             THEN NVL2(v.NGAY_DEN_TRAI, u', ', u'') ||
--                  NVL(TRIM(CAST(v.PHAN_DOI AS NVARCHAR2(200))), u'') ||
--                  CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
--                  NVL(TRIM(CAST(v.PHAN_TRAI AS NVARCHAR2(200))), u'')
--             ELSE u''
--        END AS NGAY_VAO_PHAN_DOI,
        -- S? - NGÀY / LO?I Q?: s? l?nh - ngày ra l?nh, lo?i quy?t ??nh (vd: 0012 - 01/12/2025, L?nh trích xu?t)
        --LY_DO,
        tx.TX_SO_LENH AS SO_LENH,
        --tx.TX_NGAY_RA_LENH AS NGAY_RA_LENH,
        TO_CHAR(tx.TX_NGAY_RA_LENH, 'DD/MM/YYYY') AS NGAY_RA_LENH,
        lqdtx.LQDTX_TEN AS LOAI_QD,
--        CAST(NVL(TRIM(CAST(tx.TX_SO_LENH AS VARCHAR2(255))), u'') AS NVARCHAR2(1000)) ||
--        CASE WHEN tx.TX_NGAY_RA_LENH IS NOT NULL
--             THEN u' - ' || CAST(TO_CHAR(tx.TX_NGAY_RA_LENH, 'DD/MM/YYYY') AS NVARCHAR2(20))
--             ELSE u''
--        END ||
--        CASE WHEN lqdtx.LQDTX_TEN IS NOT NULL
--             THEN u', ' || NVL(TRIM(CAST(lqdtx.LQDTX_TEN AS NVARCHAR2(500))), u'')
--             ELSE u''
--        END AS SO_NGAY_LOAI_QD,
        -- NGÀY TX / TH?I H?N: ngày trích xu?t, th?i h?n (vd: 01/12/2025, 10 ngày)
        --TO_CHAR(tx.TX_NGAY_TRICH_XUAT, 'DD/MM/YYYY') TU_NGAY, --t? ngày
        TO_CHAR(tx.TX_TU_NGAY, 'DD/MM/YYYY') TU_NGAY, --t? ngày
        NVL(CAST(TO_CHAR(tx.TX_NGAY_TRICH_XUAT, 'DD/MM/YYYY') AS NVARCHAR2(20)), u'') ||
--        CASE WHEN mtg.MTG_TITLE IS NOT NULL
--             THEN u', ' || NVL(TRIM(CAST(mtg.MTG_TITLE AS NVARCHAR2(200))), u'')
--             ELSE u''
--        END AS NGAY_TX_THOI_HAN,

        null AS NGAY_TX_THOI_HAN,

        mtg.MTG_TITLE AS THOI_HAN,
        -- LÝ DO TRÍCH XU?T
        NVL(TRIM(CAST(ldtr.LDTX_TEN AS NVARCHAR2(500))), u'') AS LY_DO_TRICH_XUAT,
        TO_CHAR(tx.TX_NGAY_TRA, 'DD/MM/YYYY')   as NGAY_LAI, --den ngay, ngay tra
        -- NGÀY L?I TÌNH TR?NG: ngày tr? + tình tr?ng (n?u ?ã tr?); n?u ch?a tr? = "Trích xu?t"
--        CASE WHEN tx.TX_NGAY_TRA IS NOT NULL
--             THEN CAST(TO_CHAR(tx.TX_NGAY_TRA, 'DD/MM/YYYY') AS NVARCHAR2(20)) ||
--                  CASE WHEN txtx.TTTX_TEN IS NOT NULL THEN u', ' || NVL(TRIM(CAST(txtx.TTTX_TEN AS NVARCHAR2(200))), u'') ELSE u'' END
--             ELSE NVL(TRIM(CAST(txtx.TTTX_TEN AS NVARCHAR2(200))), u'Tr\00edch xu\1ea5t')
--        END AS NGAY_LAI_TINH_TRANG,
        TO_CHAR(tx.TX_NGAY_TRA, 'DD/MM/YYYY')   as DEN_NGAY, --den ngay, ngay tra
         NVL(TRIM(CAST(txtx.TTTX_TEN AS NVARCHAR2(200))), u'Tr\00edch xu\1ea5t') AS TRANG_THAI,
        -- v.PHAN_DOI,
    	        -- PHAN_DOI: phân ??i, phân tr?i
	        NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
	        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
	        NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI ,         
--        -- GHI CHÚ = ghi chú riêng Lai l?ch (LL_GHI_CHU_RIENG ? DM_GHI_CHU_RIENGS.GCR_TEN)
        NVL(CAST(ga.ghi_chu_rieng_ten AS NVARCHAR2(2000)), u'') AS GHI_CHU
    FROM TRICH_XUATS tx
    INNER JOIN LL_one v ON v.PHAM_NHAN_ID = tx.PHAM_NHAN_ID
    LEFT JOIN gcr_agg ga ON ga.PHAM_NHAN_ID = v.PHAM_NHAN_ID
    LEFT JOIN DM_LOAI_QUYET_DINH_TRICH_XUATS lqdtx
        ON tx.TX_LOAI_LENH_ID = lqdtx.ID AND NVL(lqdtx.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS DMCQ ON DMCQ.ID = TX.TX_DON_VI_DE_NGHI_ID
    LEFT JOIN DM_LY_DO_TRICH_XUATS ldtr
        ON tx.TX_LY_DO_ID = ldtr.ID AND NVL(ldtr.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_TRANG_TRICH_XUATS txtx
        ON tx.TX_TINH_TRANG_ID = txtx.ID AND NVL(txtx.IS_DELETED, 0) = 0
    LEFT JOIN DM_MA_THOI_GIANS mtg
        ON tx.TX_THOI_HAN_ID = mtg.ID AND NVL(mtg.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn  ON v.LL_TINH_TRANG_ID = dmttpn.ID  AND NVL(dmttpn.IS_DELETED, 0) = 0        
    WHERE NVL(tx.IS_DELETED, 0) = 0
      --AND tx.TX_NGAY_TRICH_XUAT IS NOT NULL
      --AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_ID = p_ma_trai_giam)
     AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))            
      AND (v_tu_ngay IS NULL OR  tx.TX_TU_NGAY  >=  v_tu_ngay) 
      AND (v_den_ngay IS NULL OR  tx.TX_TU_NGAY  <=  v_den_ngay) 
    --AND (p_tinh_trang_id IS NULL OR dmttpn.ID = p_tinh_trang_id)
       AND (v_tra_lai_tu_ngay IS NULL OR  tx.TX_NGAY_TRA  >=  v_tra_lai_tu_ngay) 
      AND (v_tra_lai_den_ngay IS NULL OR  tx.TX_NGAY_TRA  <= v_tra_lai_den_ngay)   
      and (p_tinh_trang_tx  IS NULL OR p_tinh_trang_tx = TX_TINH_TRANG_ID)
      and (p_ly_do_id  IS NULL OR p_ly_do_id =  TX_LY_DO_ID )
      and (p_loai_lenh_tx  IS NULL OR p_loai_lenh_tx = TX_LOAI_LENH_ID )
      and (p_ban_giao_tx  IS NULL OR p_ban_giao_tx = TX_BAN_GIAO_ID )
  --  AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)  

      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY)
          ; 


    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân trích xu?t: ' || SQLERRM);
END SP_GET_BAO_CAO_DANH_SACH_TRICH_XUAT;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_CHET
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_CHET" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,   
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY
    p_chet_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_chet_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY   
    p_truong_hop_chet_id IN  NUMBER    DEFAULT NULL,
    p_nn_chet_id IN  NUMBER    DEFAULT NULL,
    p_hinh_thuc IN  NUMBER    DEFAULT NULL,
    p_boc_mo IN  NUMBER    DEFAULT NULL,
    p_loai_chet IN  NUMBER    DEFAULT NULL,
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT 0      
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_tu_ngay   DATE;
    v_den_ngay  DATE;
    v_chet_tu_ngay   DATE;
    v_chet_den_ngay  DATE;    
    c1          SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_chet_tu_ngay IS NULL OR TRIM(p_chet_tu_ngay) = '' THEN
        v_chet_tu_ngay := NULL;
    ELSE
        v_chet_tu_ngay := TO_DATE(TRIM(p_chet_tu_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_chet_den_ngay IS NULL OR TRIM(p_chet_den_ngay) = '' THEN
        v_chet_den_ngay := NULL;
    ELSE
        v_chet_den_ngay := TO_DATE(TRIM(p_chet_den_ngay), 'DD/MM/YYYY');
    END IF;

--    OPEN c1 FOR
--     --
--    SELECT * FROM ( 
--    select 
--ROW_NUMBER() OVER (ORDER BY ORDER_HOTEN( HO_TEN)  ) AS rn_all,
--COUNT(*) OVER() AS total_count,    
--v.HO_TEN                      AS HO_TEN,
--v.NGAY_SINH                   AS NGAY_SINH,
--v.NAM_SINH,
--v.GIOI_TINH                   AS GT,
--v.NOI_THUONG_TRU_DAY_DU,
--v.SO_TIEN_AN,
--v.TOI_DANH,
----v.NGAY_BAT_AN_PHAT,
--TO_CHAR(NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT_AN_PHAT,
--
----v.NGAY_DEN_TRAI,
--TO_CHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
--
--v.AN_PHAT,
----KTC.KTC_NGAY_CHET,
----TO_CHAR(KTC.KTC_NGAY_CHET, 'DD/MM/YYYY') AS KTC_NGAY_CHET,
--KTC_NGAY_CHET AS KTC_NGAY_CHET,
--THC.THC_TEN TRUONG_HOP_CHET,
--KTC_NOI_CHET,
--DNNC.NNC_TEN  NGUYEN_NHAN_CHET,
----KTC_NGAY_BOC_MO,
--TO_CHAR(KTC_NGAY_BOC_MO, 'DD/MM/YYYY') AS KTC_NGAY_BOC_MO,
--KTC_NOI_HOA_TANG AN_TANG,
--NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
--CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
--NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI,
--
--GHI_CHU
--
--from VW_PN_LAI_LICH_CHI_TIET v
--INNER JOIN PN_KET_THUC_CHETS KTC ON KTC.KTC_PN_LAI_LICH_ID = v.PHAM_NHAN_ID AND KTC.IS_DELETED = 0
--LEFT JOIN DM_TRUONG_HOP_CHETS THC ON THC.ID = KTC.KTC_DM_TRUONG_HOP_CHET_ID AND THC.IS_DELETED = 0
--LEFT JOIN DM_NGUYEN_NHAN_CHETS DNNC ON DNNC.ID = KTC.KTC_NGUYEN_NHAN_CHET_ID AND DNNC.IS_DELETED = 0
--WHERE 1=1
--AND ( v_tu_ngay IS NULL OR  TRUNC(NGAY_DEN_TRAI) >= TRUNC(v_tu_ngay) )
--AND ( v_den_ngay IS NULL OR TRUNC(NGAY_DEN_TRAI) <= TRUNC(v_den_ngay) )
--AND ( v_chet_tu_ngay IS NULL OR  KTC_NGAY_CHET >= v_chet_tu_ngay )
--AND ( v_chet_den_ngay IS NULL OR KTC_NGAY_CHET <= v_chet_den_ngay )
--and (p_truong_hop_chet_id is NULL OR KTC_DM_TRUONG_HOP_CHET_ID = p_truong_hop_chet_id)
--AND (p_nn_chet_id IS NULL OR KTC_NGUYEN_NHAN_CHET_ID = p_nn_chet_id)
--AND (p_hinh_thuc IS NULL OR  KTC_DM_HINH_THUC_CHON_ID = p_hinh_thuc)
--AND (p_boc_mo IS NULL OR (p_boc_mo = 1 AND KTC_NGAY_BOC_MO IS NOT NULL) OR (p_boc_mo = 2 AND KTC_NGAY_BOC_MO IS NULL) )
--AND (p_ma_trai_giam IS NULL OR  TRAI_GIAM_MA = p_ma_trai_giam)
--AND (p_loai_chet IS NULL OR (p_loai_chet = 1 and NNC_MA in (5100,5505,5701,5905 )  ) or (p_loai_chet = 2 and NNC_MA  not in (5100,5505,5701,5905 ) and KTC_NGUYEN_NHAN_CHET_ID is not null) or  (p_loai_chet = 3 AND KTC_NGUYEN_NHAN_CHET_ID IS NULL) OR (p_loai_chet = 4 AND KTC_DM_TRUONG_HOP_CHET_ID IS NULL) )
--    )
--    WHERE  rn_all > v_skip
--      AND (v_limit = 0 OR rn_all <= v_skip + v_limit)
--    ORDER BY rn_all      
--    ;
OPEN c1 FOR
WITH nnc_split AS (
    SELECT
        ktc.ID AS ktc_id,
        LEVEL AS pos,
        TRIM(REGEXP_SUBSTR(
            ktc.KTC_DANH_SACH_NGUYEN_NHAN_CHET_IDS,
            '[^;]+',
            1,
            LEVEL
        )) AS nnc_id_str
    FROM PN_KET_THUC_CHETS ktc
    WHERE ktc.KTC_DANH_SACH_NGUYEN_NHAN_CHET_IDS IS NOT NULL
      AND (v_tu_ngay IS NULL OR KTC_TU_NGAY >= v_tu_ngay)
      AND (v_den_ngay IS NULL OR KTC_TU_NGAY <= v_den_ngay)
      AND (v_chet_tu_ngay IS NULL OR KTC_NGAY_CHET >= v_chet_tu_ngay)
      AND (v_chet_den_ngay IS NULL OR KTC_NGAY_CHET <= v_chet_den_ngay)    
    CONNECT BY PRIOR ktc.ID = ktc.ID
       AND PRIOR SYS_GUID() IS NOT NULL
       AND LEVEL <= REGEXP_COUNT(ktc.KTC_DANH_SACH_NGUYEN_NHAN_CHET_IDS, ';') + 1
),
nnc_agg AS (
    SELECT
        s.ktc_id,
        LISTAGG(dnnc.NNC_TEN, '; ') WITHIN GROUP (ORDER BY s.pos) AS NGUYEN_NHAN_CHET,
        MAX(CASE WHEN dnnc.NNC_MA IN (5100, 5505, 5701, 5905) THEN 1 ELSE 0 END) AS CO_NNC_LOAI_1,
        COUNT(dnnc.ID) AS SO_NGUYEN_NHAN
    FROM nnc_split s
    JOIN DM_NGUYEN_NHAN_CHETS dnnc
      ON REGEXP_LIKE(s.nnc_id_str, '^\d+$')
     AND dnnc.ID = TO_NUMBER(s.nnc_id_str)
     AND dnnc.IS_DELETED = 0
    GROUP BY s.ktc_id
),
VW_PN_LAI_LICH_CHI_TIET_TG AS 
(SELECT * FROM VW_PN_LAI_LICH_CHI_TIET WHERE (p_ma_trai_giam IS NULL OR ( TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam))) )
SELECT *
FROM (
    SELECT
        --ROW_NUMBER() OVER (ORDER BY ORDER_HOTEN(HO_TEN)) AS rn_all,
        COUNT(*) OVER() AS total_count,
        v.HO_TEN AS HO_TEN,
        v.NGAY_SINH AS NGAY_SINH,
        v.NAM_SINH,
        v.GIOI_TINH AS GT,
        v.NOI_THUONG_TRU_DAY_DU,
        v.SO_TIEN_AN,
        v.TOI_DANH,
        TO_CHAR(NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT_AN_PHAT,
        TO_CHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
        v.AN_PHAT,
        TO_CHAR(KTC_NGAY_CHET, 'DD/MM/YYYY HH24:MI') AS KTC_NGAY_CHET,
        THC.THC_TEN AS TRUONG_HOP_CHET,
        KTC_NOI_CHET,
        nnc_agg.NGUYEN_NHAN_CHET AS NGUYEN_NHAN_CHET,
        TO_CHAR(KTC_NGAY_BOC_MO, 'DD/MM/YYYY HH24:MI') AS KTC_NGAY_BOC_MO,
        HTC_TEN AS AN_TANG,
        NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
        NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI,
        KTC_GHI_CHU GHI_CHU
    FROM VW_PN_LAI_LICH_CHI_TIET_TG v
    INNER JOIN PN_KET_THUC_CHETS KTC
        ON KTC.KTC_PN_LAI_LICH_ID = v.PHAM_NHAN_ID
       AND KTC.IS_DELETED = 0
       left join DM_HINH_THUC_CHONS htc on htc.id = KTC_DM_HINH_THUC_CHON_ID and htc.IS_DELETED = 0
    LEFT JOIN DM_TRUONG_HOP_CHETS THC
        ON THC.ID = KTC.KTC_DM_TRUONG_HOP_CHET_ID
       AND THC.IS_DELETED = 0
    LEFT JOIN nnc_agg
        ON nnc_agg.ktc_id = KTC.ID
    WHERE 1 = 1
      AND (v_tu_ngay IS NULL OR KTC_TU_NGAY >= v_tu_ngay)
      AND (v_den_ngay IS NULL OR KTC_TU_NGAY <= v_den_ngay)
      AND (v_chet_tu_ngay IS NULL OR KTC_NGAY_CHET >= v_chet_tu_ngay)
      AND (v_chet_den_ngay IS NULL OR KTC_NGAY_CHET <= v_chet_den_ngay)
      AND (p_truong_hop_chet_id IS NULL OR KTC_DM_TRUONG_HOP_CHET_ID = p_truong_hop_chet_id)
      AND (
            p_nn_chet_id IS NULL
            OR EXISTS (
                SELECT 1
                FROM nnc_split s
                WHERE s.ktc_id = KTC.ID
                  AND REGEXP_LIKE(s.nnc_id_str, '^\d+$')
                  AND TO_NUMBER(s.nnc_id_str) = p_nn_chet_id
            )
          )
      AND (p_hinh_thuc IS NULL OR KTC_DM_HINH_THUC_CHON_ID = p_hinh_thuc)
      AND (
            p_boc_mo IS NULL
            OR (p_boc_mo = 1 AND KTC_NGAY_BOC_MO IS NOT NULL AND KTC_NGAY_BOC_MO <= SYSTIMESTAMP)
            OR (p_boc_mo = 2 AND ((KTC_NGAY_BOC_MO IS NULL) OR (KTC_NGAY_BOC_MO > SYSTIMESTAMP)) )
          )
      --AND (p_ma_trai_giam IS NULL OR TRAI_GIAM_MA = p_ma_trai_giam)
    AND (p_ma_trai_giam IS NULL OR ( TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
      AND (
            p_loai_chet IS NULL
            OR (p_loai_chet = 1 AND NVL(nnc_agg.CO_NNC_LOAI_1, 0) = 1)
            OR (p_loai_chet = 2 AND NVL(nnc_agg.SO_NGUYEN_NHAN, 0) > 0 AND NVL(nnc_agg.CO_NNC_LOAI_1, 0) = 0)
            OR (p_loai_chet = 3 AND NVL(nnc_agg.SO_NGUYEN_NHAN, 0) = 0)
            OR (p_loai_chet = 4 AND KTC_DM_TRUONG_HOP_CHET_ID IS NULL)
          )
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
)
--WHERE rn_all > v_skip
--  AND (v_limit = 0 OR rn_all <= v_skip + v_limit)
--ORDER BY rn_all
;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân ph?m t?i m?i: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_CHET;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_DAN_TOC_THIEU_SO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_DAN_TOC_THIEU_SO" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tinh_trang_con_id IN  NUMBER    DEFAULT NULL,
    p_dan_toc_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id IN  NUMBER    DEFAULT NULL,
    p_den_trai_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_den_trai_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY
    p_ra_trai_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_ra_trai_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY    
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT 0      
)
AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_trai_giam_id NUMBER;
    v_den_trai_tu_ngay DATE;
    v_den_trai_den_ngay DATE;
    v_ra_trai_tu_ngay DATE;
    v_ra_trai_den_ngay DATE;    
    C1 SYS_REFCURSOR;  
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
--      IF p_ma_trai_giam IS NULL OR p_ma_trai_giam = '' THEN
--        v_trai_giam_id := NULL;
--    ELSE
--        v_trai_giam_id := p_ma_trai_giam;
--    END IF;

     IF p_den_trai_tu_ngay IS NULL OR TRIM(p_den_trai_tu_ngay) = '' THEN
        v_den_trai_tu_ngay := NULL;
    ELSE
        v_den_trai_tu_ngay := TO_DATE(TRIM(p_den_trai_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_den_trai_den_ngay IS NULL OR TRIM(p_den_trai_den_ngay) = '' THEN
        v_den_trai_den_ngay :=  NULL;
    ELSE
        v_den_trai_den_ngay := TO_DATE(TRIM(p_den_trai_den_ngay), 'DD/MM/YYYY');
    END IF;
     IF p_ra_trai_tu_ngay IS NULL OR TRIM(p_ra_trai_tu_ngay) = '' THEN
        v_ra_trai_tu_ngay := NULL;
    ELSE
        v_ra_trai_tu_ngay := TO_DATE(TRIM(p_ra_trai_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_ra_trai_den_ngay IS NULL OR TRIM(p_ra_trai_den_ngay) = '' THEN
        v_ra_trai_den_ngay :=  NULL;
    ELSE
        v_ra_trai_den_ngay := TO_DATE(TRIM(p_ra_trai_den_ngay), 'DD/MM/YYYY');
    END IF;
      OPEN C1 FOR

SELECT * FROM (
  SELECT /*+ USE_HASH( ll  C) */
  COUNT(*) OVER() AS total_count,
    ll.LL_SO_HO_SO_LAN_DAU so_ho_so,
    LL_HO_TEN ho_ten,
       CASE 
        WHEN ll.LL_NGAY_SINH IS NOT NULL THEN
            CASE 
                -- N?u ch? có 4 s?, coi nh? là n?m
                WHEN REGEXP_LIKE(TO_CHAR(ll.LL_NGAY_SINH), '^\d{4}$') 
                THEN TO_NUMBER(TO_CHAR(ll.LL_NGAY_SINH))
                -- Extract n?m t? format DD/MM/YYYY ho?c DD-MM-YYYY (l?y 4 s? cu?i)
                -- L?y 4 ký t? cu?i cùng n?u chúng là s?
                WHEN LENGTH(TO_CHAR(ll.LL_NGAY_SINH)) >= 4 
                     AND REGEXP_LIKE(SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), -4), '^\d{4}$')
                THEN TO_NUMBER(SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), -4))
                -- N?u không, tìm nhóm 4 s? ??u tiên (có th? là n?m trong format khác)
                WHEN REGEXP_LIKE(TO_CHAR(ll.LL_NGAY_SINH), '\d{4}') 
                THEN TO_NUMBER(REGEXP_SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), '\d{4}', 1, 1))
                ELSE NULL
            END
        ELSE NULL 
    END AS  nam_sinh,
    LL_NGAY_SINH NGAY_SINH,
    gt.GT_TEN gioi_tinh,
    CASE
        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
          OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
        THEN TRIM(
            NVL(NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u''), u'')
            || CASE
                WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                            THEN u', ' || dxp_thuong_tru.XP_TEN
                        ELSE dxp_thuong_tru.XP_TEN
                    END
                ELSE u''
               END
            || CASE
                WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                            THEN u', ' || dttp_thuong_tru.TTP_TEN
                        ELSE dttp_thuong_tru.TTP_TEN
                    END
                ELSE u''
               END
        )
        ELSE NULL
    END AS NOI_THUONG_TRU_DAY_DU,
     td.TOI_DANH toi_danh,
    --td.THA_NGAY_BAT AS ngay_bat_an_phat,
    TO_CHAR(td.THA_NGAY_BAT, 'DD/mm/yyyy') AS ngay_bat_an_phat,
    td.THA_AN_PHAT AS an_phat,
    TO_CHAR(td.THA_NGAY_DEN_TRAI, 'DD/mm/yyyy') AS ngay_den_trai,
    --td.THA_NGAY_DEN_TRAI AS ngay_den_trai,
    --td.THA_NGAY_HET_HAN  AS ngay_het_an,
    TO_CHAR(td.THA_NGAY_HET_HAN, 'DD/mm/yyyy') AS ngay_het_an,
    dt.DT_TEN AS DAN_TOC,
/*   CASE WHEN NULLIF(TRIM(FN_TINH_AN_DA_GIAM(ll.PHAM_NHAN_ID).TONG_GIAM_AN), u'0') IS NULL
             THEN u'Kh\00f4ng'
             ELSE FN_TINH_AN_DA_GIAM(ll.PHAM_NHAN_ID).LAN_GIAM_AN || u' L\1ea7n = ' || FN_TINH_AN_DA_GIAM(ll.PHAM_NHAN_ID).TONG_GIAM_AN
        END                    AS DA_GIAM,
        NVL(FN_GET_DA_CHAP_HANH(p_pn_id =>ll.PHAM_NHAN_ID), '')    AS DA_CHAP_HANH,
        NVL(FN_GET_CON_LAI(ll.PHAM_NHAN_ID), '')                   AS CON_LAI, */
    --PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(ll.ID)  DA_CHAP_HANH,
    MTGCH.MTG_TITLE   DA_CHAP_HANH,
    PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(ll.ID) DA_GIAM,       
    --PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(ll.ID)  CON_LAI, 
    MTGCL.MTG_TITLE   CON_LAI,
    b.ttpn_ten tinh_trang,
    	        -- PHAN_DOI: phân ??i, phân tr?i
	        NVL(TRIM(CAST(pd.PD_TEN AS VARCHAR2(4000))), '') ||
	        CASE WHEN pd.PD_TEN IS NOT NULL AND pt.PT_TEN IS NOT NULL THEN u', ' ELSE u'' END ||
	        NVL(TRIM(CAST(pt.PT_TEN AS VARCHAR2(4000))), '') AS PHAN_DOI 
FROM
    PN_LAI_LICHS LL
   left join  DM_TINH_TRANG_PHAM_NHANS b on LL.LL_TINH_TRANG_ID = b.ID
   left join  PN_THI_HANH_AN c on c.THA_PNLAI_LICH_ID = LL.ID
LEFT JOIN DM_MA_THOI_GIANS MTGCH 
    ON THA_THOI_GIAN_DA_CHAP_HANH = MTGCH.MTG_MA 
LEFT JOIN DM_MA_THOI_GIANS MTGCL 
    ON THA_THOI_GIAN_CON_LAI = MTGCL.MTG_MA  
LEFT JOIN DM_GIOI_TINHS gt 
    ON ll.LL_DM_GIOI_TINH_ID = gt.ID 
    AND gt.IS_DELETED = 0
LEFT JOIN V_PN_THI_HANH_AN_TOI_DANH td 
    ON ll.ID = td.THA_PNLAI_LICH_ID     
LEFT JOIN DM_PHAN_DOIS pd
    ON ll.ll_phan_doi_id = pd.ID
    AND pd.IS_DELETED = 0
LEFT JOIN DM_PHAN_TRAIS pt
    ON ll.ll_phan_trai_id = pt.ID
    AND pt.IS_DELETED = 0
LEFT JOIN DM_DAN_TOCS dt 
    ON ll.LL_DM_DAN_TOC_ID = dt.ID 
    AND dt.IS_DELETED = 0    
LEFT JOIN DM_QUOC_TICHS qt 
    ON ll.LL_DM_QUOC_TICH_ID = qt.ID 
    AND qt.IS_DELETED = 0  
LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru 
    ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID 
    AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
LEFT JOIN DM_XA_PHUONG dxp_thuong_tru 
    ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID 
    AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0 
LEFT JOIN DM_TRAI_GIAMS traigiam 
    ON ll.LL_TRAI_GIAM_ID = traigiam.ID 
    AND traigiam.IS_DELETED = 0
WHERE 1=1
--AND  UPPER(DAN_TOC) NOT LIKE 'KINH'
--AND dt.DT_MA NOT IN ('6500','1100') and ll.is_deleted = 0
AND dt.DT_MA NOT IN ('1','55') and ll.is_deleted = 0

          --AND UPPER(TRIM(NVL(dt.DT_TEN, ''))) != 'KINH'
          --AND UPPER(TRIM(NVL(qt.QT_TEN, ''))) IN ('VI?T NAM', 'VIET NAM', '')         
         AND (p_ma_trai_giam IS NULL OR (LL_TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))  

AND (v_den_trai_tu_ngay IS NULL OR TD.THA_NGAY_DEN_TRAI >= v_den_trai_tu_ngay) 
AND (v_den_trai_den_ngay IS NULL OR TD.THA_NGAY_DEN_TRAI <= v_den_trai_den_ngay)
AND  (v_ra_trai_tu_ngay IS NULL OR TD.THA_NGAY_HET_HAN >= v_ra_trai_tu_ngay) 
AND (v_ra_trai_den_ngay IS NULL OR TD.THA_NGAY_HET_HAN <= v_ra_trai_den_ngay)
AND (p_tinh_trang_con_id is null or b.id =  p_tinh_trang_con_id)
AND (p_dan_toc_id IS NULL OR DT.ID = p_dan_toc_id )
AND (p_phan_doi_id IS NULL OR pd.ID = p_phan_doi_id)
        -- AND   ((LL.LAST_MODIFICATION_TIME IS NOT NULL AND LL.LAST_MODIFICATION_TIME BETWEEN TO_TIMESTAMP(v_tu_ngay, 'DD/MM/YYYY') AND  TO_TIMESTAMP(v_den_ngay, 'DD/MM/YYYY'))
       -- OR  ( LL.CREATION_TIME BETWEEN TO_TIMESTAMP(v_tu_ngay, 'DD/MM/YYYY') AND  TO_TIMESTAMP(v_den_ngay, 'DD/MM/YYYY'))) 
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
       )
--    WHERE  rn_all > v_skip
--      AND (v_limit = 0 OR rn_all <= v_skip + v_limit)

        ;

      DBMS_SQL.RETURN_RESULT(C1);
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_DO_VAT_GUI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_DO_VAT_GUI" (
    p_tu_ngay            IN VARCHAR2 DEFAULT NULL,
    p_den_ngay           IN VARCHAR2 DEFAULT NULL,
    p_tinh_trang_id      IN NUMBER   DEFAULT NULL,
    p_phan_doi_id        IN NUMBER   DEFAULT NULL,
    p_maxresultcount     IN NUMBER   DEFAULT NULL,
    p_skipcount          IN NUMBER   DEFAULT NULL
) AS
    v_tu_ngay    DATE;
    v_den_ngay   DATE;
    v_skip       NUMBER;
    v_limit      NUMBER;
    v_filter_ngay NUMBER;
    c1           SYS_REFCURSOR;
BEGIN
    v_skip := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
    END IF;

    v_filter_ngay := CASE WHEN v_tu_ngay IS NOT NULL OR v_den_ngay IS NOT NULL THEN 1 ELSE 0 END;

    OPEN c1 FOR
    WITH
    oll_one AS (
        SELECT *
        FROM (
            SELECT
                o.*,
                ROW_NUMBER() OVER (
                    PARTITION BY o.PN_ID
                    ORDER BY o.SO_HSLD
                ) AS rn_oll
            FROM QLPN_OLD.PN_LAI_LICH o
        ) z
        WHERE rn_oll = 1
    ),
    lk_detail AS (
        SELECT
            k.MA_PN_LK,
            k.PN_ID,
            k.NGAY_GUI,
            ct.DO_VAT,
            ct.SO_LUONG,
            ct.CHU_THICH AS CT_CHU_THICH
        FROM QLPN_OLD.PN_LUU_KY k
        INNER JOIN QLPN_OLD.PN_LUU_KY_CT ct
            ON ct.MA_PN_LK = k.MA_PN_LK
    ),
    base_join AS (
        SELECT
            ld.MA_PN_LK,
            ld.NGAY_GUI,
            ld.DO_VAT,
            ld.SO_LUONG,
            ld.CT_CHU_THICH,
            ll.ID AS pn_lai_lich_id
        FROM lk_detail ld
        INNER JOIN oll_one oll
            ON oll.PN_ID = ld.PN_ID
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.LL_SO_HO_SO_LAN_DAU = oll.SO_HSLD
           AND NVL(ll.is_deleted, 0) = 0
        WHERE (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (
              v_filter_ngay = 0
              OR (
                  ld.NGAY_GUI IS NOT NULL
                  AND (v_tu_ngay IS NULL OR TRUNC(ld.NGAY_GUI) >= v_tu_ngay)
                  AND (v_den_ngay IS NULL OR TRUNC(ld.NGAY_GUI) <= v_den_ngay)
              )
          )
    ),
    vw_one AS (
        SELECT *
        FROM (
            SELECT
                v.*,
                ROW_NUMBER() OVER (
                    PARTITION BY v.PHAM_NHAN_ID
                    ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
                             v.CREATION_TIME DESC NULLS LAST
                ) AS rn_vw
            FROM QLPN.VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
        ) x
        WHERE rn_vw = 1
    ),
    result_rows AS (
        SELECT
            b.MA_PN_LK,
            TRUNC(CAST(b.NGAY_GUI AS DATE)) AS ngay_gui_sort,
            CAST(v.SO_HO_SO AS NVARCHAR2(100)) AS SO_HSLD,
            v.HO_TEN,
            CAST(v.NGAY_SINH AS DATE) AS NGAY_SINH,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            v.TOI_DANH,
            CAST(v.NGAY_BAT_AN_PHAT AS DATE) AS NGAY_BAT,
            v.AN_PHAT,
            CAST(v.NGAY_DEN_TRAI AS DATE) AS NGAY_DEN_TRAI,
            CAST(v.NGAY_HET_AN AS DATE) AS NGAY_HET_HAN,
            CAST(b.NGAY_GUI AS DATE) AS NGAY_GUI,
            CAST(NVL(TRIM(b.DO_VAT), '') AS NVARCHAR2(500)) AS DO_VAT,
            CAST(NVL(TRIM(b.SO_LUONG), '') AS NVARCHAR2(100)) AS SO_LUONG,
            NVL(
                NULLIF(TRIM(CAST(b.CT_CHU_THICH AS NVARCHAR2(2000))), ''),
                NVL(CAST(ttpn.TTPN_TEN AS NVARCHAR2(500)), '')
            ) AS TINH_TRANG,
            NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE
                WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN ', '
                ELSE ''
            END ||
            NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
        FROM base_join b
        INNER JOIN vw_one v
            ON v.PHAM_NHAN_ID = b.pn_lai_lich_id
        LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
            ON ttpn.ID = v.LL_TINH_TRANG_ID
           AND NVL(ttpn.IS_DELETED, 0) = 0
        WHERE (p_tinh_trang_id IS NULL OR v.LL_TINH_TRANG_ID = p_tinh_trang_id)
    )
    SELECT
        v_skip + ROW_NUMBER() OVER (
            ORDER BY r.ngay_gui_sort DESC NULLS LAST,
                     r.MA_PN_LK,
                     r.DO_VAT
        ) AS STT,
        r.SO_HSLD,
        r.HO_TEN,
        r.NGAY_SINH,
        r.NOI_DKTT,
        r.TOI_DANH,
        r.NGAY_BAT,
        r.AN_PHAT,
        r.NGAY_DEN_TRAI,
        r.NGAY_HET_HAN,
        r.NGAY_GUI,
        r.DO_VAT,
        r.SO_LUONG,
        r.TINH_TRANG,
        r.PHAN_DOI
    FROM (
        SELECT x.*
        FROM result_rows x
        ORDER BY
            x.ngay_gui_sort DESC NULLS LAST,
            x.MA_PN_LK,
            x.DO_VAT
        OFFSET v_skip ROWS
        FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY
    ) r;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            'L?i khi l?y danh sách ?? v?t g?i: ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_DO_VAT_GUI;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_GHI_CHU_RIENG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_GHI_CHU_RIENG" (
    P_TU_NGAY     IN  VARCHAR2  DEFAULT NULL, 
    P_DEN_NGAY     IN  VARCHAR2  DEFAULT NULL, 
    P_PHAN_DOI_ID          NUMBER  DEFAULT NULL,
    P_TINH_TRANG_ID     NUMBER  DEFAULT NULL,
    P_GHI_CHU_RIENG     NUMBER  DEFAULT NULL,     
    P_MA_TRAI_GIAM         NVARCHAR2  DEFAULT NULL,
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT 0    
)
AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_tu_ngay   DATE;
    v_den_ngay  DATE;
    c1          SYS_REFCURSOR;
BEGIN

    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN C1 FOR

WITH VW_PN_LAI_LICH_CHI_TIET_TG AS 
(SELECT * FROM VW_PN_LAI_LICH_CHI_TIET WHERE (p_ma_trai_giam IS NULL OR ( TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
AND (v_tu_ngay IS NULL OR NGAY_DEN_TRAI >=  v_tu_ngay)
AND (v_den_ngay IS NULL OR  NGAY_DEN_TRAI <=  v_den_ngay))

SELECT * FROM (
        SELECT            
           -- ROW_NUMBER() OVER (ORDER BY HO_TEN_ORDER NULLS LAST) AS rn_all,
            COUNT(*) OVER() AS total_count,
            v.SO_HO_SO                        AS SO_HSLD,
            v.HO_TEN,
            upper(v.HO_TEN) HO_TEN_HOA,
            v.NAM_SINH,
            v.NGAY_SINH,
            v.GIOI_TINH,
            TEN_KHAC,
            v.NOI_THUONG_TRU_DAY_DU           AS NOI_DKTT,
            v.TOI_DANH,
            --SO_TIEN_AN,
            --v.NGAY_BAT_AN_PHAT                AS NGAY_BAT,
            TO_CHAR(v.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT,
            v.AN_PHAT,
            --v.NGAY_DEN_TRAI,
            TO_CHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
            --v.NGAY_HET_AN NGAY_HET_HAN,  
            TO_CHAR(v.NGAY_HET_AN, 'DD/MM/YYYY') AS NGAY_HET_HAN,
            --GHI_CHU_RIENG,

--                (SELECT LISTAGG(dgcr.GCR_TEN, ', ') WITHIN GROUP (ORDER BY dgcr.ID)
--                FROM (
--                    SELECT TO_NUMBER(REGEXP_SUBSTR(v.GHI_CHU_RIENG, '[^,]+', 1, LEVEL)) AS ID
--                    FROM dual
--                    CONNECT BY REGEXP_SUBSTR(v.GHI_CHU_RIENG, '[^,]+', 1, LEVEL) IS NOT NULL
--                ) t
--                JOIN DM_GHI_CHU_RIENGS dgcr 
--                    ON dgcr.ID = t.ID
--            ) AS GHI_CHU_RIENG,
            (
                SELECT LISTAGG(dgcr.GCR_TEN, ', ') WITHIN GROUP (ORDER BY dgcr.ID)
                FROM (
                    SELECT TO_NUMBER(val) AS ID
                    FROM (
                        SELECT TRIM(REGEXP_SUBSTR(v.GHI_CHU_RIENG, '[^,]+', 1, LEVEL)) AS val
                        FROM dual
                        CONNECT BY REGEXP_SUBSTR(v.GHI_CHU_RIENG, '[^,]+', 1, LEVEL) IS NOT NULL
                    )
                    WHERE REGEXP_LIKE(val, '^\d+$')
                ) t
                JOIN DM_GHI_CHU_RIENGS dgcr
                    ON dgcr.ID = t.ID
            ) AS GHI_CHU_RIENG,
            v.PHAN_DOI PHAN_DOI_RIENG,
            v.PHAN_TRAI,
	        NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
	        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
	        NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI,
            dmttpn.TTPN_TEN AS TINH_TRANG

        FROM VW_PN_LAI_LICH_CHI_TIET_TG v
        --LEFT JOIN PN_THI_HANH_AN PTHA ON PTHA.THA_PNLAI_LICH_ID = v.PHAM_NHAN_ID
        LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn ON v.LL_TINH_TRANG_ID = dmttpn.ID AND NVL(dmttpn.IS_DELETED, 0) = 0 
        WHERE 1=1
        AND GHI_CHU_RIENG IS NOT NULL
        AND (
            P_GHI_CHU_RIENG IS NULL
            OR INSTR(
                ',' || REPLACE(v.GHI_CHU_RIENG, ' ', '') || ',',
                ',' || TO_CHAR(P_GHI_CHU_RIENG) || ','
            ) > 0
        )
--                    -- Filter ngày
            AND (v_tu_ngay IS NULL OR  v.NGAY_DEN_TRAI >= v_tu_ngay )
            AND (v_den_ngay IS NULL OR  v.NGAY_DEN_TRAI <= v_den_ngay )
            -- Phân ??i
            AND (P_PHAN_DOI_ID IS NULL OR v.PHAN_DOI_ID = P_PHAN_DOI_ID)
           AND (p_ma_trai_giam IS NULL OR ( TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
            AND (P_TINH_TRANG_ID IS NULL OR  dmttpn.ID = P_TINH_TRANG_ID)
          ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
)
--    WHERE  rn_all > v_skip
--      AND (v_limit = 0 OR rn_all <= v_skip + v_limit)

            ;
DBMS_SQL.RETURN_RESULT(C1);
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_HINH_PHAT_BO_SUNG_KHAC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_HINH_PHAT_BO_SUNG_KHAC" (
p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay_den_trai   IN VARCHAR2 DEFAULT NULL,
    p_den_ngay_den_trai  IN VARCHAR2 DEFAULT NULL,
    p_tu_ngay_ra_trai    IN VARCHAR2 DEFAULT NULL,
    p_den_ngay_ra_trai   IN VARCHAR2 DEFAULT NULL,
    p_hpbs_hinh_id       IN NUMBER   DEFAULT NULL,
    p_tinh_trang_id      IN NUMBER   DEFAULT NULL,
    p_phan_doi_id        IN NUMBER   DEFAULT NULL,
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT 0   
) AS
    v_tu_dt      DATE;
    v_den_dt     DATE;
    v_tu_rt      DATE;
    v_den_rt     DATE;
    v_ref_ngay   DATE;
    v_skip       NUMBER;
    v_limit      NUMBER;
    c1           SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);

    IF p_tu_ngay_den_trai IS NULL OR TRIM(p_tu_ngay_den_trai) = '' THEN
        v_tu_dt := NULL;
    ELSE
        v_tu_dt := TRUNC(TO_DATE(TRIM(p_tu_ngay_den_trai), 'DD/MM/YYYY'));
    END IF;

    IF p_den_ngay_den_trai IS NULL OR TRIM(p_den_ngay_den_trai) = '' THEN
        v_den_dt := NULL;
    ELSE
        v_den_dt := TRUNC(TO_DATE(TRIM(p_den_ngay_den_trai), 'DD/MM/YYYY'));
    END IF;

    IF p_tu_ngay_ra_trai IS NULL OR TRIM(p_tu_ngay_ra_trai) = '' THEN
        v_tu_rt := NULL;
    ELSE
        v_tu_rt := TRUNC(TO_DATE(TRIM(p_tu_ngay_ra_trai), 'DD/MM/YYYY'));
    END IF;

    IF p_den_ngay_ra_trai IS NULL OR TRIM(p_den_ngay_ra_trai) = '' THEN
        v_den_rt := NULL;
    ELSE
        v_den_rt := TRUNC(TO_DATE(TRIM(p_den_ngay_ra_trai), 'DD/MM/YYYY'));
    END IF;

    v_ref_ngay := NVL(v_den_dt, NVL(v_den_rt, TRUNC(SYSDATE)));

    OPEN c1 FOR
    WITH
    hp_khac AS (
        SELECT
            hp.ID AS hpbs_row_id,
            hp.HPBS_MA_PHAM_NHAN AS pn_id,
            hp.HPBS_THOI_HAN AS hpbs_thoi_han_id,
            dm.HPBS_TEN,
            dm.HPBS_MA
        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
        INNER JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
            ON dm.ID = hp.HPBS_HINH_PHAT
           AND NVL(dm.IS_DELETED, 0) = 0
           AND dm.HPBS_MA IN (110,120,130,140,150,160,170,310)
        WHERE NVL(hp.IS_DELETED, 0) = 0
          AND hp.HPBS_MA_PHAM_NHAN IS NOT NULL
          AND (p_hpbs_hinh_id IS NULL OR dm.ID = p_hpbs_hinh_id)
    ),
    vw_one AS (
        SELECT *
        FROM (
            SELECT
                v.* 
            FROM QLPN.VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
            AND (p_ma_trai_giam IS NULL OR ( TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))   
        ) x

    ),
    dang_chap_hanh AS (
        SELECT tha.THA_PNLAI_LICH_ID AS pn_id
        FROM QLPN.PN_THI_HANH_AN tha
        WHERE NVL(tha.IS_DELETED, 0) = 0
--          AND tha.THA_PNLAI_LICH_ID IS NOT NULL
--          AND COALESCE(tha.THA_NGAY_BAT_DAU_O_TU, tha.THA_NGAY_BAT) IS NOT NULL
--          AND COALESCE(tha.THA_NGAY_BAT_DAU_O_TU, tha.THA_NGAY_BAT) <= v_ref_ngay
--          AND (tha.THA_NGAY_HET_HAN IS NULL OR tha.THA_NGAY_HET_HAN >= v_ref_ngay)
    ),
    base AS (
        SELECT
            k.hpbs_row_id,
            k.pn_id,
            k.HPBS_TEN,
            k.hpbs_thoi_han_id
        FROM hp_khac k
        INNER JOIN vw_one v ON v.PHAM_NHAN_ID = k.pn_id
        WHERE (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)
          AND (
              (v_tu_dt IS NULL AND v_den_dt IS NULL)
              OR (
                  v.NGAY_DEN_TRAI IS NOT NULL
--                  AND (v_tu_dt IS NULL OR TRUNC(CAST(v.NGAY_DEN_TRAI AS DATE)) >= v_tu_dt)
--                  AND (v_den_dt IS NULL OR TRUNC(CAST(v.NGAY_DEN_TRAI AS DATE)) <= v_den_dt)
                  AND (v_tu_dt IS NULL OR v.NGAY_DEN_TRAI >= v_tu_dt)
                  AND (v_den_dt IS NULL OR v.NGAY_DEN_TRAI <= v_den_dt)
              )
          )
          AND (
              (v_tu_rt IS NULL AND v_den_rt IS NULL)
              OR (
                  v.NGAY_HET_AN IS NOT NULL
--                  AND (v_tu_rt IS NULL OR TRUNC(CAST(v.NGAY_HET_AN AS DATE)) >= v_tu_rt)
--                  AND (v_den_rt IS NULL OR TRUNC(CAST(v.NGAY_HET_AN AS DATE)) <= v_den_rt)
                  AND (v_tu_rt IS NULL OR v.NGAY_HET_AN >= v_tu_rt)
                  AND (v_den_rt IS NULL OR v.NGAY_HET_AN <= v_den_rt)
              )
          )
--          AND (
--              p_tinh_trang_id IS NULL
--              OR (p_tinh_trang_id = 1 AND k.pn_id IN (SELECT pn_id FROM dang_chap_hanh))
--              OR (p_tinh_trang_id = 2 AND k.pn_id NOT IN (SELECT pn_id FROM dang_chap_hanh))
--          )
    ),
    ordered AS (
        SELECT
            b.hpbs_row_id,
            TRUNC(CAST(v.NGAY_DEN_TRAI AS DATE)) AS ngay_den_sort,
            v.SO_HO_SO,
            v.GIOI_TINH,
            v.HO_TEN,
            v.NAM_SINH,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            v.TOI_DANH,
            TO_CHAR(v.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT_AN_PHAT,
            --v.NGAY_BAT_AN_PHAT,
            v.AN_PHAT,
            TO_CHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
            --CAST(v.NGAY_DEN_TRAI AS DATE) AS NGAY_DEN_TRAI,
            CAST(b.HPBS_TEN AS NVARCHAR2(500)) AS HINH_PHAT,
            CAST(NVL(dmtg.MTG_TITLE, u'') AS NVARCHAR2(500)) AS THOI_HAN_PHAT,
            TO_CHAR(v.NGAY_HET_AN, 'DD/MM/YYYY') AS NGAY_HET_HAN,
            --CAST(v.NGAY_HET_AN AS DATE) AS NGAY_HET_HAN,
            NVL(CAST(ttpn.TTPN_TEN AS NVARCHAR2(500)), u'') AS TINH_TRANG,
            NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE
                WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', '
                ELSE u''
            END ||
            NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI,
            --ROW_NUMBER() OVER (ORDER BY   ORDER_HOTEN(v.HO_TEN) NULLS LAST) AS rn_all,
            HO_TEN_ORDER,
            COUNT(*) OVER () AS TOTAL_COUNT
        FROM base b
        INNER JOIN vw_one v ON v.PHAM_NHAN_ID = b.pn_id
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg
            ON NVL(dmtg.IS_DELETED, 0) = 0
           AND dmtg.ID = b.hpbs_thoi_han_id
        LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
            ON ttpn.ID = v.LL_TINH_TRANG_ID
           AND NVL(ttpn.IS_DELETED, 0) = 0
           where (
              p_tinh_trang_id IS NULL
              OR p_tinh_trang_id = ttpn.id
          )          
    )
    SELECT
--        v_skip + ROW_NUMBER() OVER (
--            ORDER BY q.ngay_den_sort DESC NULLS LAST,
--                     q.HO_TEN,
--                     q.hpbs_row_id
--        ) AS rn_all,

  total_count,
        q.SO_HO_SO,
        q.GIOI_TINH,
        q.HO_TEN,
        q.NAM_SINH,
        q.NOI_DKTT,
        q.TOI_DANH,
        q.NGAY_BAT_AN_PHAT,
        q.AN_PHAT,
        q.NGAY_DEN_TRAI,
        q.HINH_PHAT,
        q.THOI_HAN_PHAT,
        q.NGAY_HET_HAN,
        q.TINH_TRANG,
        q.PHAN_DOI,
        HO_TEN_ORDER
    FROM (
        SELECT o.*


        FROM ordered o

--        ORDER BY
--        ORDER_HOTEN(o.HO_TEN)
--            REGEXP_SUBSTR(o.HO_TEN, '[^ ]+$') DESC NULLS LAST,
--            o.ngay_den_sort DESC NULLS LAST,
--            o.HO_TEN,
--            o.hpbs_row_id
--        OFFSET v_skip ROWS
--        FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY
       ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
    ) q  
        ;
    --

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i khi l\1ea5y danh s\00e1ch HPBS kh\00e1c (MA LIKE 1%): ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_HINH_PHAT_BO_SUNG_KHAC;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_HUY_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_HUY_AN" (
p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay              IN VARCHAR2 DEFAULT NULL,
    p_den_ngay             IN VARCHAR2 DEFAULT NULL,
    p_tu_ngay_tra_tu_do    IN VARCHAR2 DEFAULT NULL,
    p_den_ngay_tra_tu_do   IN VARCHAR2 DEFAULT NULL,
    p_phan_doi_id          IN NUMBER   DEFAULT NULL,
    p_maxresultcount       IN NUMBER   DEFAULT NULL,
    p_skipcount            IN NUMBER   DEFAULT NULL
) AS
    v_tu_qd      DATE;
    v_den_qd     DATE;
    v_tu_ttd     DATE;
    v_den_ttd    DATE;
    v_skip       NUMBER;
    v_limit      NUMBER;
    v_filter_qd  NUMBER;
    v_filter_ttd NUMBER;
    c1           SYS_REFCURSOR;
BEGIN
    v_skip := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_qd := NULL;
    ELSE
        v_tu_qd := TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_qd := NULL;
    ELSE
        v_den_qd := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_tu_ngay_tra_tu_do IS NULL OR TRIM(p_tu_ngay_tra_tu_do) = '' THEN
        v_tu_ttd := NULL;
    ELSE
        v_tu_ttd := TRUNC(TO_DATE(TRIM(p_tu_ngay_tra_tu_do), 'DD/MM/YYYY'));
    END IF;

    IF p_den_ngay_tra_tu_do IS NULL OR TRIM(p_den_ngay_tra_tu_do) = '' THEN
        v_den_ttd := NULL;
    ELSE
        v_den_ttd := TRUNC(TO_DATE(TRIM(p_den_ngay_tra_tu_do), 'DD/MM/YYYY'));
    END IF;

    v_filter_qd  := CASE WHEN v_tu_qd IS NOT NULL OR v_den_qd IS NOT NULL THEN 1 ELSE 0 END;
    v_filter_ttd := CASE WHEN v_tu_ttd IS NOT NULL OR v_den_ttd IS NOT NULL THEN 1 ELSE 0 END;

    OPEN c1 FOR
    WITH
    h_base AS (
        SELECT h.*
        FROM QLPN.HUY_ANS h
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.id = h.PHAM_NHAN_ID
           AND NVL(ll.is_deleted, 0) = 0
        WHERE NVL(h.IS_DELETED, 0) = 0
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (
              v_filter_qd = 0
              OR (
                  h.NGAY_QUYET_DINH IS NOT NULL
                  AND (v_tu_qd IS NULL OR TRUNC(h.NGAY_QUYET_DINH) >= v_tu_qd)
                  AND (v_den_qd IS NULL OR TRUNC(h.NGAY_QUYET_DINH) <= v_den_qd)
              )
          )
          AND (
              v_filter_ttd = 0
              OR (
                  h.NGAY_TRA_TU_DO IS NOT NULL
                  AND (v_tu_ttd IS NULL OR TRUNC(h.NGAY_TRA_TU_DO) >= v_tu_ttd)
                  AND (v_den_ttd IS NULL OR TRUNC(h.NGAY_TRA_TU_DO) <= v_den_ttd)
              )
          )
    ),
    pn_scope AS (
        SELECT DISTINCT x.PHAM_NHAN_ID AS pn_id
        FROM h_base x
    ),
    vw_dedup AS (
        SELECT
            v.*,
            ROW_NUMBER() OVER (PARTITION BY v.PHAM_NHAN_ID ORDER BY v.HO_TEN) AS rn_vw
        FROM pn_scope p
        INNER JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = p.pn_id
           AND NVL(v.IS_DELETED, 0) = 0
         WHERE (p_ma_trai_giam IS NULL OR ( TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))  
    ),
    result_rows AS (
        SELECT
            h.ID AS H_ID,
            TRUNC(h.NGAY_QUYET_DINH) AS NGAY_QD_SORT,
            v.SO_HO_SO,
            v.HO_TEN,
            v.NAM_SINH,
            v.GIOI_TINH,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            v.TOI_DANH,
            v.NGAY_BAT_AN_PHAT,
            v.AN_PHAT,
            CAST(v.NGAY_DEN_TRAI AS DATE) AS NGAY_DEN_TRAI,
            CAST(h.SO_QUYET_DINH AS NVARCHAR2(500)) AS SO_QD,
            CAST(h.NGAY_QUYET_DINH AS DATE) AS NGAY_QD,
            NVL(
                CAST(
                    CASE
                        WHEN h.LY_DO_HUY IS NULL THEN NULL
                        ELSE DBMS_LOB.SUBSTR(h.LY_DO_HUY, 4000, 1)
                    END AS NVARCHAR2(4000)
                ),
                u''
            ) AS LY_DO_HUY,
            CAST(h.NGAY_TRA_TU_DO AS DATE) AS NGAY_TRA_TU_DO,
            NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE
                WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', '
                ELSE u''
            END ||
            NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
        FROM h_base h
        INNER JOIN vw_dedup v
            ON v.PHAM_NHAN_ID = h.PHAM_NHAN_ID
           AND v.rn_vw = 1
    )
    SELECT
        v_skip + ROW_NUMBER() OVER (
            ORDER BY ORDER_HOTEN(r.HO_TEN)
        ) AS STT,
        r.SO_HO_SO,
        r.HO_TEN,
        r.NAM_SINH,
        r.GIOI_TINH,
        r.NOI_DKTT,
        r.TOI_DANH,
        --r.NGAY_BAT_AN_PHAT,
        TO_CHAR(r.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT_AN_PHAT,
        r.AN_PHAT,
        --r.NGAY_DEN_TRAI,
        TO_CHAR(r.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
        r.SO_QD,
        --r.NGAY_QD,
        TO_CHAR(r.NGAY_QD, 'DD/MM/YYYY') AS NGAY_QD,
        r.LY_DO_HUY,
        --r.NGAY_TRA_TU_DO,
        TO_CHAR(r.NGAY_TRA_TU_DO, 'DD/MM/YYYY') AS NGAY_TRA_TU_DO,
        r.PHAN_DOI,
        COUNT(*) OVER () AS TOTAL_COUNT

    FROM (
        SELECT x.*
        FROM result_rows x
        ORDER BY REGEXP_SUBSTR(x.HO_TEN, '[^ ]+$') DESC NULLS LAST, x.NGAY_QD_SORT DESC NULLS LAST, x.H_ID DESC
        OFFSET v_skip ROWS
        FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY
    ) r;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i khi l\1ea5y danh s\00e1ch h\1ee7y \00e1n: ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_HUY_AN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_KHEN_THUONG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_KHEN_THUONG" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id IN  NUMBER    DEFAULT NULL,
    p_bao_cao IN  NUMBER    DEFAULT 1,
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT 0  
)
AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_trai_giam_id NUMBER;
    v_tu_ngay DATE;
    v_den_ngay DATE;
    C1 SYS_REFCURSOR;  
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
--
--      IF p_ma_trai_giam IS NULL OR p_ma_trai_giam = '' THEN
--        v_trai_giam_id := NULL;
--    ELSE
--        v_trai_giam_id := p_ma_trai_giam;
--    END IF;    

     IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;

      OPEN C1 FOR

SELECT * FROM (
 SELECT  
 --ROW_NUMBER() OVER (ORDER BY LL.SO_HO_SO NULLS LAST) AS rn_all,
 --ROW_NUMBER() OVER (ORDER BY   ORDER_HOTEN(LL.HO_TEN) NULLS LAST) AS rn_all,
 COUNT(*) OVER() AS total_count,
   ll.SO_HO_SO,
    LL.ho_ten,
    upper(LL.ho_ten)ho_ten_hoa,
    LL.gioi_tinh,
    LL.ngay_sinh,
    ll.nam_sinh,
    ten_khac,
    LL.noi_thuong_tru_day_du,
    LL.toi_danh,
    TO_CHAR(ll.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT_AN_PHAT, 
    SO_BAN_AN BAN_AN_SO,
    TO_CHAR(NGAY_BAN_AN, 'DD/MM/YYYY') AS NGAY_XU,
    --NGAY_BAN_AN NGAY_XU,
    TOA_XU_TEN,
    TOA_XU_DIA_PHUONG,
    SO_QD_THA,
    TO_CHAR(NGAY_QD_THA, 'DD/MM/YYYY') AS NGAY_QD_THA,
    CO_QUAN_QD_THA TOA_QD_THA,
    TOA_QD_THA_DIA_PHUONG,
    ll.an_phat,
    TO_CHAR(ngay_het_an, 'DD/MM/YYYY') AS  ngay_het_an,
    --NGAY_KHEN,
    TO_CHAR(NGAY_KHEN, 'DD/MM/YYYY') AS NGAY_KHEN,
    LDK_TEN MA_LY_DO_KHEN,
    HTKT_TEN MA_HINH_THUC_KHEN, 
    b.ttpn_ten tinh_trang,
    NVL(TRIM(CAST(LL.PHAN_DOI AS VARCHAR2(4000))), '') ||
    CASE WHEN LL.PHAN_DOI IS NOT NULL AND LL.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
    NVL(TRIM(CAST(LL.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI_PHAN_TRAI,
    --ll.phan_doi,
        NVL(TRIM(CAST(LL.PHAN_DOI AS VARCHAR2(4000))), '') ||
    CASE WHEN LL.PHAN_DOI IS NOT NULL AND LL.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
    NVL(TRIM(CAST(LL.PHAN_TRAI AS VARCHAR2(4000))), '') AS phan_doi,
    LL.PHAN_TRAI,
    NOI_DE_NGHI,
    TO_CHAR(NGAY_DE_NGHI, 'DD/MM/YYYY') AS NGAY_DE_NGHI
FROM
    vw_pn_lai_lich_chi_tiet LL
    inner join KHEN_THUONGS kt on ll.PHAM_NHAN_ID = kt.PHAM_NHAN_ID AND kt.IS_DELETED = 0
   left join  DM_TINH_TRANG_PHAM_NHANS b on LL.LL_TINH_TRANG_ID = b.ID AND b.IS_DELETED = 0
   left join DM_HINH_THUC_KHEN_THUONGS HTKT ON HTKT.ID = KT.MA_HINH_THUC_KHEN_ID AND HTKT.IS_DELETED = 0
      left join (   SELECT kt.ID,
       LISTAGG(dm.LDK_TEN, ', ')  WITHIN GROUP (ORDER BY dm.ID) AS LDK_TEN
FROM KHEN_THUONGS kt
JOIN DM_LY_DO_KHENS dm
ON dm.ID IN (
    SELECT REGEXP_SUBSTR(
           REPLACE(REPLACE(kt.MA_LY_DO_KHEN_ID,'[',''),']',''),
           '[^,]+',1,LEVEL)
    FROM dual
    CONNECT BY REGEXP_SUBSTR(
           REPLACE(REPLACE(kt.MA_LY_DO_KHEN_ID,'[',''),']',''),
           '[^,]+',1,LEVEL) IS NOT NULL
)
WHERE kt.IS_DELETED = 0 AND dm.IS_DELETED = 0
GROUP BY kt.ID) LKD ON LKD.ID = KT.ID
--neu can lay ra nhung pn dang tna
/*
        INNER JOIN (
            SELECT tha.tha_pnlai_lich_id
            FROM PN_THI_HANH_AN tha
            WHERE NVL(tha.is_deleted, 0) = 0
              AND tha.tha_pnlai_lich_id IS NOT NULL
              AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
              AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) <= TRUNC(SYSDATE)
              AND (tha.tha_ngay_het_han IS NULL OR tha.tha_ngay_het_han >= TRUNC(SYSDATE))
        ) t ON t.tha_pnlai_lich_id = ll.PHAM_NHAN_ID */
WHERE 1=1
and NGAY_KHEN is not null
and (v_tu_ngay IS NULL   OR  NGAY_KHEN  >=  v_tu_ngay  ) 
and (v_den_ngay IS NULL   OR  NGAY_KHEN  <=  v_den_ngay   ) 
--AND (v_trai_giam_id IS NULL  OR LL.TRAI_GIAM_MA = v_trai_giam_id)
AND (p_ma_trai_giam IS NULL OR ( TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))  
AND (p_phan_doi_id IS NULL OR ll.phan_doi_id = p_phan_doi_id)
AND (p_tinh_trang_id IS NULL OR b.ID = p_tinh_trang_id)
--AND (p_bao_cao IS NULL)
      ORDER BY HO_TEN_ORDER
      OFFSET p_skipcount ROWS
      FETCH NEXT NVL(p_maxresultcount, 99999999999) ROWS ONLY
) ;



      DBMS_SQL.RETURN_RESULT(C1);
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_KY_LUAT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_KY_LUAT" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_ky_luat_tu_ngay     IN VARCHAR2  DEFAULT NULL,
    p_ky_luat_den_ngay    IN VARCHAR2  DEFAULT NULL,
    p_qd_tu_ngay          IN VARCHAR2  DEFAULT NULL,
    p_qd_den_ngay         IN VARCHAR2  DEFAULT NULL,
    p_phan_doi_id         IN NUMBER    DEFAULT NULL,
    p_tinh_trang_id       IN NUMBER    DEFAULT NULL,
    p_noi_ky_luat_id      IN NUMBER    DEFAULT NULL,  -- 1=trong trai, 2=ngoai trai
    p_ly_do_id            IN NUMBER    DEFAULT NULL,
    p_hinh_thuc_id        IN NUMBER    DEFAULT NULL,
    p_bao_cao             IN NUMBER    DEFAULT 1,
    p_phan_trai_id        IN NUMBER    DEFAULT NULL,  -- phan trai hien tai, NULL=tat ca
    p_maxresultcount      IN NUMBER    DEFAULT NULL,
    p_skipcount           IN NUMBER    DEFAULT 0
)
AS
    v_skip               NUMBER;
    v_limit              NUMBER;
    v_trai_giam_id NUMBER;
    v_ky_luat_tu_ngay   DATE;
    v_ky_luat_den_ngay   DATE;
    v_qd_tu_ngay         DATE;
    v_qd_den_ngay        DATE;
    C1                   SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

--      IF p_ma_trai_giam IS NULL OR p_ma_trai_giam = '' THEN
--        v_trai_giam_id := NULL;
--    ELSE
--        v_trai_giam_id := p_ma_trai_giam;
--    END IF;     

    IF p_ky_luat_tu_ngay IS NULL OR TRIM(p_ky_luat_tu_ngay) = '' THEN
        v_ky_luat_tu_ngay := NULL;
    ELSE
        v_ky_luat_tu_ngay := TO_DATE(TRIM(p_ky_luat_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_ky_luat_den_ngay IS NULL OR TRIM(p_ky_luat_den_ngay) = '' THEN
        v_ky_luat_den_ngay := NULL;
    ELSE
        v_ky_luat_den_ngay := TO_DATE(TRIM(p_ky_luat_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_qd_tu_ngay IS NULL OR TRIM(p_qd_tu_ngay) = '' THEN
        v_qd_tu_ngay := NULL;
    ELSE
        v_qd_tu_ngay := TO_DATE(TRIM(p_qd_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_qd_den_ngay IS NULL OR TRIM(p_qd_den_ngay) = '' THEN
        v_qd_den_ngay := NULL;
    ELSE
        v_qd_den_ngay := TO_DATE(TRIM(p_qd_den_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN C1 FOR
    SELECT *
    FROM (
        SELECT
            --ROW_NUMBER() OVER (ORDER BY LL.SO_HO_SO NULLS LAST) AS rn_all,
           -- ROW_NUMBER() OVER (ORDER BY   HO_TEN_ORDER NULLS LAST) AS rn_all,
            COUNT(*) OVER() AS total_count,
            LL.HO_TEN                         AS ho_ten,
            gioi_tinh,
            upper(LL.HO_TEN)                         AS ho_ten_hoa,
            LL.NGAY_SINH                      AS ngay_sinh,
            LL.NAM_SINH                      AS NAM_SINH,
            TEN_KHAC,
            LL.NOI_THUONG_TRU_DAY_DU         AS noi_thuong_tru_day_du,
            LL.TOI_DANH                      AS toi_danh,
            LL.SO_TIEN_AN                    AS so_tien_an,
            --LL.NGAY_BAT_AN_PHAT              AS ngay_bat_an_phat,
            TO_CHAR(LL.NGAY_BAT_AN_PHAT , 'DD/mm/yyyy') AS ngay_bat_an_phat,
            LL.AN_PHAT                       AS an_phat,
            LL.SO_BAN_AN,       
            TO_CHAR(LL.NGAY_BAN_AN, 'DD/MM/YYYY') AS NGAY_XU,
            LL.TOA_XU_TEN,
            LL.TOA_XU_DIA_PHUONG,
            LL.SO_QD_THA,
            TO_CHAR(LL.NGAY_QD_THA, 'DD/MM/YYYY') AS NGAY_QD_THA,
            LL.CO_QUAN_QD_THA TOA_QD_THA,
            LL.TOA_QD_THA_DIA_PHUONG,

            LL.SO_TIEN_SU,
            KL.NOI_DUNG_VI_PHAM,
            SO_QUYET_DINH, 
            TO_CHAR(NGAY_DE_NGHI_KY_LUAT , 'DD/mm/yyyy') NGAY_DE_NGHI, 
            TO_CHAR(NGAY_BIEN_BAN , 'DD/mm/yyyy')   NGAY_BIEN_BAN,
            --LL.NGAY_DEN_TRAI                 AS ngay_vao,
            TO_CHAR(LL.NGAY_DEN_TRAI , 'DD/mm/yyyy') AS ngay_vao,
            --LL.NGAY_HET_AN                   AS ngay_het_an,
            TO_CHAR(LL.NGAY_HET_AN , 'DD/mm/yyyy') AS NGAY_HET_AN,
         NVL(TRIM(CAST(LL.PHAN_DOI AS VARCHAR2(4000))), '') ||
         CASE WHEN LL.PHAN_DOI IS NOT NULL AND LL.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
         NVL(TRIM(CAST(LL.PHAN_TRAI AS VARCHAR2(4000))), '') AS       phan_doi ,    
            LL.PHAN_DOI                      AS phan_doi_rieng,
            LL.PHAN_TRAI                      AS phan_trai,
            --KL.NGAY_QUYET_DINH              AS ngay_quyet_dinh,
             TO_CHAR( KL.NGAY_QUYET_DINH , 'DD/mm/yyyy') AS ngay_quyet_dinh,
            KL.HINH_THUC_KY_LUAT_CU_THE     AS HINH_THUC_KY_LUAT,
            --KL.NGAY_DE_NGHI_KY_LUAT         AS tu_ngay,
            --KL.NGAY_QUYET_DINH         AS tu_ngay,
             TO_CHAR(KL.NGAY_QUYET_DINH , 'DD/mm/yyyy') AS tu_ngay,
--            NULL                             AS thoi_han,
--            NULL                             AS den_ngay,
            CASE 
                WHEN HTKLPN_MA IN (310, 311 , 312, 313, 314) 
                THEN '10 Ngày'
                ELSE NULL
            END AS thoi_han,

            CASE 
                WHEN HTKLPN_MA IN (310, 311 , 312, 313, 314) 
                THEN --KL.NGAY_QUYET_DINH + 10
                TO_CHAR(KL.NGAY_QUYET_DINH + 10, 'DD/mm/yyyy') 
                ELSE NULL
            END AS den_ngay,            
            --KL.LY_DO_KY_LUAT_CU_THE         AS LY_DO_KY_LUAT,
            ldkl.LY_DO_KY_LUAT               AS LY_DO_KY_LUAT,
            --KL.NGAY_DE_NGHI_TIEN_BO         AS ngay_tien_bo,
             TO_CHAR(KL.NGAY_DE_NGHI_TIEN_BO , 'DD/mm/yyyy') AS ngay_tien_bo,
            b.ttpn_ten                       AS tinh_trang
        FROM vw_pn_lai_lich_chi_tiet LL
        INNER JOIN KY_LUATS KL
            ON LL.PHAM_NHAN_ID = KL.PHAM_NHAN_ID
        LEFT JOIN DM_TINH_TRANG_PHAM_NHANS b
            ON LL.LL_TINH_TRANG_ID = b.ID
        LEFT JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS HTKLPN ON HTKLPN.ID = MA_HINH_THUC_KY_LUAT_ID
        OUTER APPLY (
            SELECT LISTAGG(d.LDKL_TEN, u'; ' ON OVERFLOW TRUNCATE)
                       WITHIN GROUP (ORDER BY d.LDKL_TEN) AS LY_DO_KY_LUAT
              FROM JSON_TABLE(
                       CASE WHEN KL.MA_LY_DO_KY_LUAT_IDS IS JSON
                            THEN KL.MA_LY_DO_KY_LUAT_IDS
                            ELSE u'[' || TO_CHAR(KL.MA_LY_DO_KY_LUAT_ID) || u']'
                       END,
                       '$[*]' COLUMNS (ly_do_id NUMBER PATH '$')) jt
              JOIN DM_LY_DO_KY_LUATS d
                ON d.ID = jt.ly_do_id
               AND d.IS_DELETED = 0
        ) ldkl
        LEFT JOIN (
            SELECT
                p_inner.*,
                ROW_NUMBER() OVER (
                    PARTITION BY p_inner.THA_PNLAI_LICH_ID
                    ORDER BY NVL(p_inner.THA_NGAY_BAN_AN, DATE '1900-01-01') DESC,
                             p_inner.ID DESC
                ) AS rn_tha
            FROM PN_THI_HANH_AN p_inner
            WHERE p_inner.THA_PNLAI_LICH_ID IS NOT NULL
        ) PTHA
            ON PTHA.THA_PNLAI_LICH_ID = LL.PHAM_NHAN_ID
           AND PTHA.rn_tha = 1
        WHERE 1 = 1
        --and KL.MA_HINH_THUC_KY_LUAT_ID IN (9,16,17,22) 
          AND NVL(PTHA.IS_DELETED, 0) = 0 AND PTHA.tha_pnlai_lich_id IS NOT NULL
          --AND (v_ky_luat_tu_ngay IS NULL OR v_ky_luat_den_ngay IS NULL OR NGAY_QUYET_DINH BETWEEN v_ky_luat_tu_ngay AND v_ky_luat_den_ngay)
          AND (v_ky_luat_tu_ngay IS NULL OR   NGAY_QUYET_DINH   >=  v_ky_luat_tu_ngay  )
          AND (v_ky_luat_den_ngay IS NULL OR   NGAY_QUYET_DINH   <=  v_ky_luat_den_ngay  )
          --AND (v_qd_tu_ngay IS NULL OR v_qd_den_ngay IS NULL OR NGAY_QUYET_DINH_TIEN_BO BETWEEN v_qd_tu_ngay AND v_qd_den_ngay)
          AND (v_qd_tu_ngay IS NULL OR  NGAY_QUYET_DINH_TIEN_BO  >=  v_qd_tu_ngay )
          AND (v_qd_den_ngay IS NULL OR  NGAY_QUYET_DINH_TIEN_BO  <=  v_qd_den_ngay )
          AND (p_phan_doi_id IS NULL OR ll.phan_doi_id = p_phan_doi_id)
          AND (p_tinh_trang_id IS NULL OR b.id = p_tinh_trang_id)
          AND (p_ly_do_id IS NULL OR EXISTS (
                SELECT 1 FROM JSON_TABLE(
                         CASE WHEN KL.MA_LY_DO_KY_LUAT_IDS IS JSON
                              THEN KL.MA_LY_DO_KY_LUAT_IDS
                              ELSE u'[' || TO_CHAR(KL.MA_LY_DO_KY_LUAT_ID) || u']'
                         END,
                         '$[*]' COLUMNS (ly_do_id NUMBER PATH '$')) j
                 WHERE j.ly_do_id = p_ly_do_id))
          AND (p_hinh_thuc_id IS NULL OR KL.MA_HINH_THUC_KY_LUAT_ID = p_hinh_thuc_id)
          AND (p_noi_ky_luat_id IS NULL OR (p_noi_ky_luat_id = 1 AND KL.NGUOI_DE_NGHI_KY_LUAT IS NOT NULL) OR (p_noi_ky_luat_id = 2 AND KL.NGUOI_DE_NGHI_KY_LUAT IS NULL))
          --AND (p_bao_cao IS NULL)
          AND (p_ma_trai_giam IS NULL OR ( LL.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))  

          AND (p_phan_trai_id IS NULL OR LL.ll_phan_trai_id = p_phan_trai_id)
                ORDER BY HO_TEN_ORDER
      OFFSET p_skipcount ROWS
      FETCH NEXT NVL(p_maxresultcount, 99999999999) ROWS ONLY
    ) ;

    DBMS_SQL.RETURN_RESULT(C1);
END;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_LUU_KY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_LUU_KY" (
    p_tu_ngay            IN VARCHAR2 DEFAULT NULL,
    p_den_ngay           IN VARCHAR2 DEFAULT NULL,
    p_tinh_trang_id      IN NUMBER   DEFAULT NULL,
    p_phan_doi_id        IN NUMBER   DEFAULT NULL,
    p_maxresultcount     IN NUMBER   DEFAULT NULL,
    p_skipcount          IN NUMBER   DEFAULT NULL
) AS
    v_tu_ngay    DATE;
    v_den_ngay   DATE;
    v_skip       NUMBER;
    v_limit      NUMBER;
    v_filter_ngay NUMBER;
    c1           SYS_REFCURSOR;
BEGIN
    v_skip := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
    END IF;

    v_filter_ngay := CASE WHEN v_tu_ngay IS NOT NULL OR v_den_ngay IS NOT NULL THEN 1 ELSE 0 END;

    OPEN c1 FOR
    WITH
    oll_one AS (
        SELECT *
        FROM (
            SELECT
                o.*,
                ROW_NUMBER() OVER (
                    PARTITION BY o.PN_ID
                    ORDER BY o.SO_HSLD
                ) AS rn_oll
            FROM QLPN_OLD.PN_LAI_LICH o
        ) z
        WHERE rn_oll = 1
    ),
    lk_detail AS (
        SELECT
            k.MA_PN_LK,
            k.PN_ID,
            k.NGAY_GUI,
            ct.DO_VAT,
            ct.SO_LUONG,
            ct.CHU_THICH AS CT_CHU_THICH
        FROM QLPN_OLD.PN_LUU_KY k
        INNER JOIN QLPN_OLD.PN_LUU_KY_CT ct
            ON ct.MA_PN_LK = k.MA_PN_LK
    ),
    base_join AS (
        SELECT
            ld.MA_PN_LK,
            ld.NGAY_GUI,
            ld.DO_VAT,
            ld.SO_LUONG,
            ld.CT_CHU_THICH,
            ll.ID AS pn_lai_lich_id
        FROM lk_detail ld
        INNER JOIN oll_one oll
            ON oll.PN_ID = ld.PN_ID
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.LL_SO_HO_SO_LAN_DAU = oll.SO_HSLD
           AND NVL(ll.is_deleted, 0) = 0
        WHERE (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (
              v_filter_ngay = 0
              OR (
                  ld.NGAY_GUI IS NOT NULL
                  AND (v_tu_ngay IS NULL OR TRUNC(ld.NGAY_GUI) >= v_tu_ngay)
                  AND (v_den_ngay IS NULL OR TRUNC(ld.NGAY_GUI) <= v_den_ngay)
              )
          )--
    ),
    vw_one AS (
        SELECT *
        FROM (
            SELECT
                v.*,
                ROW_NUMBER() OVER (
                    PARTITION BY v.PHAM_NHAN_ID
                    ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
                             v.CREATION_TIME DESC NULLS LAST
                ) AS rn_vw
            FROM QLPN.VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
        ) x
        WHERE rn_vw = 1
    ),
    result_rows AS (
        SELECT
            b.MA_PN_LK,
            TRUNC(CAST(b.NGAY_GUI AS DATE)) AS ngay_gui_sort,
            CAST(v.SO_HO_SO AS NVARCHAR2(100)) AS SO_HSLD,
            v.HO_TEN,
            CAST(
                CASE
                    WHEN v.NGAY_SINH IS NOT NULL
                         AND REGEXP_LIKE(
                             TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))),
                             '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$'
                         )
                    THEN TO_CHAR(
                             TO_DATE(TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'),
                             'DD/MM/YYYY'
                         )
                    WHEN v.NAM_SINH IS NOT NULL AND v.NAM_SINH > 0
                    THEN TO_CHAR(v.NAM_SINH)
                    WHEN v.NGAY_SINH IS NOT NULL
                    THEN TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100)))
                    ELSE NULL
                END AS NVARCHAR2(100)
            ) AS NGAY_SINH,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            v.TOI_DANH,
            CAST(v.NGAY_BAT_AN_PHAT AS DATE) AS NGAY_BAT,
            v.AN_PHAT,
            CAST(v.NGAY_DEN_TRAI AS DATE) AS NGAY_DEN_TRAI,
            CAST(v.NGAY_HET_AN AS DATE) AS NGAY_HET_HAN,
            CAST(b.NGAY_GUI AS DATE) AS NGAY_GUI,
            CAST(NVL(TRIM(b.DO_VAT), u'') AS NVARCHAR2(500)) AS DO_VAT,
            CAST(NVL(TRIM(b.SO_LUONG), u'') AS NVARCHAR2(100)) AS SO_LUONG,
            NVL(
                NULLIF(TRIM(CAST(b.CT_CHU_THICH AS NVARCHAR2(2000))), u''),
                NVL(CAST(ttpn.TTPN_TEN AS NVARCHAR2(500)), u'')
            ) AS TINH_TRANG,
            NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE
                WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', '
                ELSE u''
            END ||
            NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
        FROM base_join b
        INNER JOIN vw_one v
            ON v.PHAM_NHAN_ID = b.pn_lai_lich_id
        LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
            ON ttpn.ID = v.LL_TINH_TRANG_ID
           AND NVL(ttpn.IS_DELETED, 0) = 0
        WHERE (p_tinh_trang_id IS NULL OR v.LL_TINH_TRANG_ID = p_tinh_trang_id)
    )
    SELECT
        v_skip + ROW_NUMBER() OVER (
            ORDER BY r.ngay_gui_sort DESC NULLS LAST,
                     r.MA_PN_LK,
                     r.DO_VAT
        ) AS STT,
        r.SO_HSLD,
        r.HO_TEN,
        r.NGAY_SINH,
        r.NOI_DKTT,
        r.TOI_DANH,
        r.NGAY_BAT,
        r.AN_PHAT,
        r.NGAY_DEN_TRAI,
        r.NGAY_HET_HAN,
        r.NGAY_GUI,
        r.DO_VAT,
        r.SO_LUONG,
        r.TINH_TRANG,
        r.PHAN_DOI
    FROM (
        SELECT x.*
        FROM result_rows x
        ORDER BY
            x.ngay_gui_sort DESC NULLS LAST,
            x.MA_PN_LK,
            x.DO_VAT
        OFFSET v_skip ROWS
        FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY
    ) r;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i khi l\1ea5y danh s\00e1ch \0111\1ed3 v\1eadt g\1eedi: ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_LUU_KY;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_MIEN_HINH_PHAT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_MIEN_HINH_PHAT" (
	p_trai_giam_id 		   IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay              IN VARCHAR2 DEFAULT NULL,
    p_den_ngay             IN VARCHAR2 DEFAULT NULL,
    p_tu_ngay_tra_tu_do    IN VARCHAR2 DEFAULT NULL,
    p_den_ngay_tra_tu_do   IN VARCHAR2 DEFAULT NULL,
    p_truong_hop_mien_id   IN NUMBER   DEFAULT NULL,
    p_phan_doi_id          IN NUMBER   DEFAULT NULL,
    p_noi_nop_id           IN NUMBER   DEFAULT NULL,
    p_maxresultcount       IN NUMBER   DEFAULT NULL,
    p_skipcount            IN NUMBER   DEFAULT NULL
) AS
    v_tu_qd      DATE;
    v_den_qd     DATE;
    v_tu_ttd     DATE;
    v_den_ttd    DATE;
    v_skip       NUMBER;
    v_limit      NUMBER;
    v_filter_qd  NUMBER;
    v_filter_ttd NUMBER;
    c1           SYS_REFCURSOR;
BEGIN
    v_skip := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_qd := NULL;
    ELSE
        v_tu_qd := TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_qd := NULL;
    ELSE
        v_den_qd := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_tu_ngay_tra_tu_do IS NULL OR TRIM(p_tu_ngay_tra_tu_do) = '' THEN
        v_tu_ttd := NULL;
    ELSE
        v_tu_ttd := TRUNC(TO_DATE(TRIM(p_tu_ngay_tra_tu_do), 'DD/MM/YYYY'));
    END IF;

    IF p_den_ngay_tra_tu_do IS NULL OR TRIM(p_den_ngay_tra_tu_do) = '' THEN
        v_den_ttd := NULL;
    ELSE
        v_den_ttd := TRUNC(TO_DATE(TRIM(p_den_ngay_tra_tu_do), 'DD/MM/YYYY'));
    END IF;

    v_filter_qd  := CASE WHEN v_tu_qd IS NOT NULL OR v_den_qd IS NOT NULL THEN 1 ELSE 0 END;
    v_filter_ttd := CASE WHEN v_tu_ttd IS NOT NULL OR v_den_ttd IS NOT NULL THEN 1 ELSE 0 END;

    OPEN c1 FOR
    WITH
    m_base AS (
        SELECT m.*
        FROM QLPN.MIEN_HINH_PHATS m
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.id = m.PN_LAI_LICH_ID
           AND NVL(ll.is_deleted, 0) = 0
        WHERE NVL(m.IS_DELETED, 0) = 0
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (
              p_truong_hop_mien_id IS NULL
              OR TRIM(TO_CHAR(m.MHP_TRUONG_HOP_MIEN)) = TO_CHAR(p_truong_hop_mien_id)
          )
          AND (
              v_filter_qd = 0
              OR (
                  m.MHP_NGAY_QUYET_DINH IS NOT NULL
                  AND (v_tu_qd IS NULL OR  m.MHP_NGAY_QUYET_DINH  >= v_tu_qd)
                  AND (v_den_qd IS NULL OR  m.MHP_NGAY_QUYET_DINH  <= v_den_qd)
              )
          )
          AND (
              v_filter_ttd = 0
              OR (
                  m.MHP_NGAY_TU_DO IS NOT NULL
                  AND (v_tu_ttd IS NULL OR  m.MHP_NGAY_TU_DO  >= v_tu_ttd)
                  AND (v_den_ttd IS NULL OR  m.MHP_NGAY_TU_DO  <= v_den_ttd)
              )
          )
    ),
    vw_one AS (
        SELECT *
        FROM (
            SELECT
                v.*
--                ,
--                ROW_NUMBER() OVER (
--                    PARTITION BY v.PHAM_NHAN_ID
--                    ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
--                             v.CREATION_TIME DESC NULLS LAST
--                ) AS rn_vw
            FROM QLPN.VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
            AND (p_trai_giam_id IS NULL OR v.TRAI_GIAM_MA = p_trai_giam_id)
        ) x
        --WHERE rn_vw = 1
    ),
    result_rows AS (
        SELECT
            m.ID AS M_ID,
            TRUNC(m.MHP_NGAY_QUYET_DINH) AS ngay_qd_sort,
            CAST(v.SO_HO_SO AS NVARCHAR2(100)) AS SO_HSLD,
            v.HO_TEN,
            v.GIOI_TINH,
--            CAST(
--                CASE
--                    WHEN v.NGAY_SINH IS NOT NULL
--                         AND REGEXP_LIKE(
--                             TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))),
--                             '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$'
--                         )
--                    THEN TO_CHAR(
--                             TO_DATE(TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'),
--                             'DD/MM/YYYY'
--                         )
--                    WHEN v.NAM_SINH IS NOT NULL AND v.NAM_SINH > 0
--                    THEN TO_CHAR(v.NAM_SINH)
--                    WHEN v.NGAY_SINH IS NOT NULL
--                    THEN TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100)))
--                    ELSE NULL
--                END AS NVARCHAR2(100)
--            ) AS NGAY_SINH,
                v.NGAY_SINH,  
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            v.TOI_DANH,
            --CAST(v.NGAY_BAT_AN_PHAT AS DATE) AS NGAY_BAT,
            TO_CHAR(v.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT,
            v.AN_PHAT,
            --CAST(v.NGAY_DEN_TRAI AS DATE) AS NGAY_DEN_TRAI,
            TO_CHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
            CAST(m.MHP_SO_QUYET_DINH AS NVARCHAR2(500)) AS SO_QD,
            --CAST(m.MHP_NGAY_QUYET_DINH AS DATE) AS NGAY_QD,
            TO_CHAR(m.MHP_NGAY_QUYET_DINH, 'DD/MM/YYYY') AS NGAY_QD,
            CAST(
                (
                    SELECT SUBSTR(LISTAGG(dtd.TD_TEN, ', ') WITHIN GROUP (ORDER BY dtd.ID), 1, 4000)
                    FROM (
                        SELECT TO_NUMBER(REGEXP_SUBSTR(
                            REPLACE(TRIM(m.MHP_TOI_DANH_MIEN), ' ', ''),
                            '[^,]+',
                            1,
                            LEVEL
                        )) AS tid
                        FROM dual
                        CONNECT BY LEVEL <= REGEXP_COUNT(NVL(TRIM(m.MHP_TOI_DANH_MIEN), ','), ',') + 1
                          AND REGEXP_SUBSTR(
                                  REPLACE(TRIM(m.MHP_TOI_DANH_MIEN), ' ', ''),
                                  '[^,]+',
                                  1,
                                  LEVEL
                              ) IS NOT NULL
                          AND REGEXP_LIKE(
                                  REGEXP_SUBSTR(
                                      REPLACE(TRIM(m.MHP_TOI_DANH_MIEN), ' ', ''),
                                      '[^,]+',
                                      1,
                                      LEVEL
                                  ),
                                  '^[0-9]+$'
                              )
                    ) tok
                    INNER JOIN QLPN.DM_TOI_DANHS dtd
                        ON dtd.ID = tok.tid
                       AND NVL(dtd.IS_DELETED, 0) = 0
                ) AS NVARCHAR2(4000)
            ) AS TOI_DANH_MIEN,
            CAST(
                CASE
                    WHEN NVL(m.MHP_THM_YEAR, 0) + NVL(m.MHP_THM_MONTH, 0) + NVL(m.MHP_THM_DAY, 0) = 0
                    THEN u''
                    ELSE
                        TRIM(
                            CASE WHEN NVL(m.MHP_THM_YEAR, 0) > 0
                                 THEN TO_CHAR(m.MHP_THM_YEAR) || u' n\0103m ' ELSE u'' END
                            || CASE WHEN NVL(m.MHP_THM_MONTH, 0) > 0
                                    THEN TO_CHAR(m.MHP_THM_MONTH) || u' th\00e1ng ' ELSE u'' END
                            || CASE WHEN NVL(m.MHP_THM_DAY, 0) > 0
                                    THEN TO_CHAR(m.MHP_THM_DAY) || u' ng\00e0y' ELSE u'' END
                        )
                END AS NVARCHAR2(500)
            ) AS THOI_GIAN_MIEN,
            --CAST(m.MHP_NGAY_TU_DO AS DATE) AS NGAY_TRA_TU_DO,
            TO_CHAR(m.MHP_NGAY_TU_DO, 'DD/MM/YYYY') AS NGAY_TRA_TU_DO,
            NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE
                WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', '
                ELSE u''
            END ||
            NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
        FROM m_base m
        INNER JOIN vw_one v
            ON v.PHAM_NHAN_ID = m.PN_LAI_LICH_ID
    )
    SELECT
        v_skip + ROW_NUMBER() OVER (
            ORDER BY r.ngay_qd_sort DESC NULLS LAST, r.M_ID DESC
        ) AS STT,
        r.SO_HSLD,
        r.HO_TEN,
        r.GIOI_TINH,
        r.NGAY_SINH,
        r.NOI_DKTT,
        r.TOI_DANH,
        r.NGAY_BAT,
        r.AN_PHAT,
        r.NGAY_DEN_TRAI,
        r.SO_QD,
        r.NGAY_QD,
        r.TOI_DANH_MIEN,
        r.THOI_GIAN_MIEN,
        r.NGAY_TRA_TU_DO,
        r.PHAN_DOI,
        COUNT(*) OVER () AS TOTAL_COUNT
    FROM (
        SELECT x.*
        FROM result_rows x
        ORDER BY ORDER_HOTEN(x.HO_TEN) -- REGEXP_SUBSTR(x.HO_TEN, '[^ ]+$') DESC NULLS LAST, x.ngay_qd_sort DESC NULLS LAST, x.M_ID DESC
        OFFSET v_skip ROWS
        FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY
    ) r;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i khi l\1ea5y danh s\00e1ch mi\1ec5n h\00ecnh ph\1ea1t: ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_MIEN_HINH_PHAT;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_NGUOI_CHUA_THANH_NIEN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_NGUOI_CHUA_THANH_NIEN" (
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_den_trai_tu_ngay IN VARCHAR2 DEFAULT NULL,
    p_den_trai_den_ngay IN VARCHAR2 DEFAULT NULL,
    p_ra_trai_tu_ngay IN VARCHAR2 DEFAULT NULL,
    p_ra_trai_den_ngay IN VARCHAR2 DEFAULT NULL,
    p_trang_thai_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_loai_chua_thanh_nien IN NUMBER DEFAULT NULL,
    p_maxresultcount IN NUMBER DEFAULT NULL,
    p_skipcount IN NUMBER DEFAULT 0
)
AS
    v_skip NUMBER;
    v_limit NUMBER;
    v_trai_giam_id NUMBER;
    v_den_trai_tu_ngay DATE;
    v_den_trai_den_ngay DATE;
    v_ra_trai_tu_ngay DATE;
    v_ra_trai_den_ngay DATE;
    c1 SYS_REFCURSOR;
BEGIN
    v_skip := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
--
--    IF p_ma_trai_giam IS NULL OR TRIM(p_ma_trai_giam) = '' THEN
--        v_trai_giam_id := NULL;
--    ELSE
--        v_trai_giam_id := TO_NUMBER(p_ma_trai_giam);
--    END IF;

    IF p_den_trai_tu_ngay IS NULL OR TRIM(p_den_trai_tu_ngay) = '' THEN
        v_den_trai_tu_ngay := NULL;
    ELSE
        v_den_trai_tu_ngay := TO_DATE(TRIM(p_den_trai_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_den_trai_den_ngay IS NULL OR TRIM(p_den_trai_den_ngay) = '' THEN
        v_den_trai_den_ngay := NULL;
    ELSE
        v_den_trai_den_ngay := TO_DATE(TRIM(p_den_trai_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_ra_trai_tu_ngay IS NULL OR TRIM(p_ra_trai_tu_ngay) = '' THEN
        v_ra_trai_tu_ngay := NULL;
    ELSE
        v_ra_trai_tu_ngay := TO_DATE(TRIM(p_ra_trai_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_ra_trai_den_ngay IS NULL OR TRIM(p_ra_trai_den_ngay) = '' THEN
        v_ra_trai_den_ngay := NULL;
    ELSE
        v_ra_trai_den_ngay := TO_DATE(TRIM(p_ra_trai_den_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
    SELECT *
    FROM (
        SELECT
           -- ROW_NUMBER() OVER (ORDER BY ORDER_HOTEN(ll.ho_ten) NULLS LAST) AS rn_all,
            COUNT(*) OVER() AS total_count,
            ll.so_ho_so,
            ll.ho_ten,
            ll.ngay_sinh,
            ll.nam_sinh,
            ll.gioi_tinh,
            ll.noi_thuong_tru_day_du,
            ll.toi_danh,
            TO_CHAR(ll.ngay_bat_an_phat, 'DD/mm/yyyy') AS ngay_bat_an_phat,
            ll.an_phat,
            TO_CHAR(ll.ngay_den_trai, 'DD/mm/yyyy') AS ngay_den_trai,
            TO_CHAR(ll.ngay_het_an, 'DD/mm/yyyy') AS ngay_het_an,
            PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(ll.pham_nhan_id) AS da_giam,
            PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(ll.pham_nhan_id) AS da_chap_hanh,
            PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(ll.pham_nhan_id) AS con_lai,
            b.ttpn_ten AS tinh_trang,
            ll.phan_doi
        FROM (
            SELECT x.*,
                   CASE
                       WHEN REGEXP_LIKE(TRIM(TO_CHAR(x.ngay_sinh)), '^[0-9]{2}/[0-9]{2}/[0-9]{4}$')
                       THEN TO_DATE(TRIM(TO_CHAR(x.ngay_sinh)), 'DD/MM/YYYY')

                       WHEN REGEXP_LIKE(TRIM(TO_CHAR(x.ngay_sinh)), '^[0-9]{2}/[0-9]{4}$')
                       THEN TO_DATE('01/' || TRIM(TO_CHAR(x.ngay_sinh)), 'DD/MM/YYYY')

                       WHEN REGEXP_LIKE(TRIM(TO_CHAR(x.ngay_sinh)), '^[0-9]{4}$')
                       THEN TO_DATE('01/01/' || TRIM(TO_CHAR(x.ngay_sinh)), 'DD/MM/YYYY')
                   END AS ngay_sinh_date
            FROM vw_pn_lai_lich_chi_tiet x
        ) ll
        LEFT JOIN DM_TINH_TRANG_PHAM_NHANS b
            ON ll.ll_tinh_trang_id = b.id
        LEFT JOIN PN_THI_HANH_AN c
            ON c.tha_pnlai_lich_id = ll.pham_nhan_id
        WHERE 1 = 1
          AND ll.ngay_sinh_date IS NOT NULL
          AND (
                (
                    p_loai_chua_thanh_nien = 1
                    AND ll.ngay_sinh_date > ADD_MONTHS(TRUNC(SYSDATE), -12 * 18)
                )
                OR
                (
                    (p_loai_chua_thanh_nien IS NULL OR p_loai_chua_thanh_nien = 2)
                    AND c.tha_ngay_bat IS NOT NULL
                    AND ll.ngay_sinh_date > ADD_MONTHS(TRUNC(c.tha_ngay_bat), -12 * 18)
                )
              )
          AND NVL(c.is_deleted, 0) = 0
          AND c.tha_pnlai_lich_id IS NOT NULL
          AND (v_den_trai_tu_ngay IS NULL OR  c.tha_ngay_den_trai  >=  v_den_trai_tu_ngay )
          AND (v_den_trai_den_ngay IS NULL OR  c.tha_ngay_den_trai  <=  v_den_trai_den_ngay )
          AND (v_ra_trai_tu_ngay IS NULL OR  ll.ngay_het_an  >=  v_ra_trai_tu_ngay  )
          AND (v_ra_trai_den_ngay IS NULL OR  ll.ngay_het_an  <=  v_ra_trai_den_ngay )
          AND (p_ma_trai_giam IS NULL OR ( ll.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
          AND (p_trang_thai_id IS NULL OR b.id = p_trang_thai_id)
          AND (p_phan_doi_id IS NULL OR ll.phan_doi_id = p_phan_doi_id)
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
    )
 ;

    DBMS_SQL.RETURN_RESULT(c1);
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_NGUOI_NUOC_NGOAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_NGUOI_NUOC_NGOAI" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id IN  NUMBER    DEFAULT NULL,
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT 0
)
AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_trai_giam_id NUMBER;
    v_tu_ngay DATE;
    v_den_ngay DATE;
    C1 SYS_REFCURSOR;  
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);

    IF p_ma_trai_giam IS NULL OR p_ma_trai_giam = '' THEN
        v_trai_giam_id := NULL;
    ELSE
        v_trai_giam_id := p_ma_trai_giam;
    END IF;    

    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN C1 FOR
    SELECT * FROM (
        SELECT
            --ROW_NUMBER() OVER (ORDER BY REGEXP_SUBSTR(HO_TEN, '[^ ]+$') NULLS LAST) AS rn_all,
            COUNT(*) OVER() AS total_count,
            so_ho_so,
            ho_ten,
            nam_sinh,
            gioi_tinh,
            noi_thuong_tru_day_du,
            toi_danh,
            TO_CHAR(ngay_bat_an_phat, 'DD/MM/YYYY') AS ngay_bat_an_phat,
            an_phat,
            TO_CHAR(ngay_den_trai, 'DD/MM/YYYY') AS ngay_den_trai,
            TO_CHAR(ngay_het_an, 'DD/MM/YYYY') AS ngay_het_an,
            QUOC_TICH,
--            PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(ll.PHAM_NHAN_ID) DA_GIAM,
--            PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(ll.PHAM_NHAN_ID) DA_CHAP_HANH,
--            PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(ll.PHAM_NHAN_ID) CON_LAI,
            ll.THOI_GIAN_DA_GIAM DA_GIAM,
            ll.THOI_GIAN_CON_LAI CON_LAI ,
            ll.THOI_GIAN_DA_CHAP_HANH DA_CHAP_HANH,
            b.ttpn_ten tinh_trang,
            NVL(TRIM(CAST(ll.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE WHEN ll.PHAN_DOI IS NOT NULL AND ll.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
            NVL(TRIM(CAST(ll.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
        FROM
            vw_pn_lai_lich_chi_tiet LL
            LEFT JOIN DM_TINH_TRANG_PHAM_NHANS b ON LL.LL_TINH_TRANG_ID = b.ID
            --LEFT JOIN PN_THI_HANH_AN c ON c.THA_PNLAI_LICH_ID = LL.PHAM_NHAN_ID
        WHERE 1=1
            --AND UPPER(QUOC_TICH) NOT LIKE 'VI?T NAM'
            AND LL.quoc_tich_id  NOT IN (66)
--            AND NVL(C.is_deleted, 0) = 0 
--            AND C.tha_pnlai_lich_id IS NOT NULL
        --AND (v_trai_giam_id IS NULL OR LL.TRAI_GIAM_MA = v_trai_giam_id)
          AND (p_ma_trai_giam IS NULL OR ( ll.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))

            AND (v_tu_ngay IS NULL OR v_den_ngay IS NULL 
                 OR ngay_den_trai BETWEEN v_tu_ngay AND v_den_ngay)
            AND (p_tinh_trang_id IS NULL OR B.ID = p_tinh_trang_id)
            AND (p_phan_doi_id IS NULL OR LL.PHAN_DOI_ID = p_phan_doi_id)
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
    )
   ;

    DBMS_SQL.RETURN_RESULT(C1);
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_NOP_LUU
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_NOP_LUU" (
p_trai_giam_id IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay_ket_thuc       IN VARCHAR2 DEFAULT NULL,
    p_den_ngay_ket_thuc      IN VARCHAR2 DEFAULT NULL,
    p_tu_ngay_den_trai       IN VARCHAR2 DEFAULT NULL,
    p_den_ngay_den_trai      IN VARCHAR2 DEFAULT NULL,
    p_loai_doi_tuong_id      IN NUMBER   DEFAULT NULL,
    p_ly_do_ket_thuc_id      IN NUMBER   DEFAULT NULL,
    p_phan_doi_id            IN NUMBER   DEFAULT NULL,
    p_thoi_han_bao_quan_id   IN NUMBER   DEFAULT NULL,
    p_maxresultcount         IN NUMBER   DEFAULT NULL,
    p_skipcount              IN NUMBER   DEFAULT NULL
) AS
    v_tu_kt      DATE;
    v_den_kt     DATE;
    v_tu_dt      DATE;
    v_den_dt     DATE;
    v_skip       NUMBER;
    v_limit      NUMBER;
    v_filter_kt  NUMBER;
    v_filter_dt  NUMBER;
    c1           SYS_REFCURSOR;
BEGIN
    v_skip := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    IF p_tu_ngay_ket_thuc IS NULL OR TRIM(p_tu_ngay_ket_thuc) = '' THEN
        v_tu_kt := NULL;
    ELSE
        v_tu_kt := TRUNC(TO_DATE(TRIM(p_tu_ngay_ket_thuc), 'DD/MM/YYYY'));
    END IF;

    IF p_den_ngay_ket_thuc IS NULL OR TRIM(p_den_ngay_ket_thuc) = '' THEN
        v_den_kt := NULL;
    ELSE
        v_den_kt := TRUNC(TO_DATE(TRIM(p_den_ngay_ket_thuc), 'DD/MM/YYYY'));
    END IF;

    IF p_tu_ngay_den_trai IS NULL OR TRIM(p_tu_ngay_den_trai) = '' THEN
        v_tu_dt := NULL;
    ELSE
        v_tu_dt := TRUNC(TO_DATE(TRIM(p_tu_ngay_den_trai), 'DD/MM/YYYY'));
    END IF;

    IF p_den_ngay_den_trai IS NULL OR TRIM(p_den_ngay_den_trai) = '' THEN
        v_den_dt := NULL;
    ELSE
        v_den_dt := TRUNC(TO_DATE(TRIM(p_den_ngay_den_trai), 'DD/MM/YYYY'));
    END IF;

    v_filter_kt := CASE WHEN v_tu_kt IS NOT NULL OR v_den_kt IS NOT NULL THEN 1 ELSE 0 END;
    v_filter_dt := CASE WHEN v_tu_dt IS NOT NULL OR v_den_dt IS NOT NULL THEN 1 ELSE 0 END;

    OPEN c1 FOR
    WITH
    phan_loai_latest AS (
        SELECT pl.PHAM_NHAN_ID,
               pl.LOAI_PHAN_LOAI_ID
        FROM (
            SELECT
                pl2.*,
                ROW_NUMBER() OVER (
                    PARTITION BY pl2.PHAM_NHAN_ID
                    ORDER BY pl2.NGAY_PHAN_LOAI DESC NULLS LAST, pl2.ID DESC
                ) AS rn_pl
            FROM QLPN.PHAN_LOAIS pl2
            WHERE NVL(pl2.IS_DELETED, 0) = 0
        ) pl
        WHERE pl.rn_pl = 1
    ),
    nl_base AS (
        SELECT nl.*,LTGBQHSPN_TEN 
        FROM QLPN.NOP_LUUS nl
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.id = nl.PHAM_NHAN_ID
           AND NVL(ll.is_deleted, 0) = 0
        LEFT JOIN DM_LOAI_THOI_GIAN_BAO_QUAN_HO_SO_PHAM_NHANS TGBQ ON TGBQ.ID = nl.THOI_GIAN_BAO_QUAN
        WHERE NVL(nl.IS_DELETED, 0) = 0
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (
              p_thoi_han_bao_quan_id IS NULL
              OR nl.THOI_GIAN_BAO_QUAN = p_thoi_han_bao_quan_id
          )
          AND (
              v_filter_kt = 0
              OR (
                  nl.NGAY_KET_THUC IS NOT NULL
                  AND (v_tu_kt IS NULL OR TRUNC(nl.NGAY_KET_THUC) >= v_tu_kt)
                  AND (v_den_kt IS NULL OR TRUNC(nl.NGAY_KET_THUC) <= v_den_kt)
              )
          )
          AND (
              p_loai_doi_tuong_id IS NULL
              OR EXISTS (
                  SELECT 1
                  FROM phan_loai_latest pl
                  WHERE pl.PHAM_NHAN_ID = nl.PHAM_NHAN_ID
                    AND pl.LOAI_PHAN_LOAI_ID = p_loai_doi_tuong_id
              )
          )
    ),
    vw_one AS (
        SELECT *
        FROM (
            SELECT
                v.*,
                ROW_NUMBER() OVER (
                    PARTITION BY v.PHAM_NHAN_ID
                    ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
                             v.CREATION_TIME DESC NULLS LAST
                ) AS rn_vw
            FROM QLPN.VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
            AND (p_trai_giam_id IS NULL OR v.TRAI_GIAM_MA = p_trai_giam_id)
        ) x
        WHERE rn_vw = 1
    ),
    result_rows AS (
        SELECT
            nl.ID AS NL_ID,
            TRUNC(nl.NGAY_KET_THUC) AS ngay_kt_sort,
            CAST(v.SO_HO_SO AS NVARCHAR2(100)) AS SO_HSLD,
            CAST(v.CCCD AS NVARCHAR2(50)) AS CCCD,
            v.HO_TEN,
            CAST(
                CASE
                    WHEN v.NGAY_SINH IS NOT NULL
                         AND REGEXP_LIKE(
                             TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))),
                             '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$'
                         )
                    THEN TO_CHAR(
                             TO_DATE(TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'),
                             'DD/MM/YYYY'
                         )
                    WHEN v.NAM_SINH IS NOT NULL AND v.NAM_SINH > 0
                    THEN TO_CHAR(v.NAM_SINH)
                    WHEN v.NGAY_SINH IS NOT NULL
                    THEN TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100)))
                    ELSE NULL
                END AS NVARCHAR2(100)
            ) AS NGAY_SINH,
            v.GIOI_TINH,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            v.TOI_DANH,
            v.AN_PHAT,
            v.NGAY_BAT_AN_PHAT,
            CAST(v.NGAY_DEN_TRAI AS DATE) AS NGAY_DEN_TRAI,
            CAST(nl.SO_DANG_KY AS NVARCHAR2(100)) AS SO_DANG_KY,
            CAST(nl.NGAY_KET_THUC AS DATE) AS NGAY_KET_THUC,
            CAST(nl.NGAY_NOP_LUU AS DATE) AS NGAY_NOP_LUU,
            nl.SO_NAM_BAO_QUAN AS SO_NAM_BAO_QUAN,
            --CAST(u'' AS NVARCHAR2(500)) AS LOAI_NOP_LUU,
            TTPN_TEN as LOAI_NOP_LUU,
            LTGBQHSPN_TEN as THOI_HAN_BAO_QUAN,
            NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE
                WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', '
                ELSE u''
            END ||
            NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI,
            COUNT(*) OVER () AS TOTAL_COUNT

        FROM nl_base nl
        INNER JOIN vw_one v
         left join  DM_TINH_TRANG_PHAM_NHANS b on v.LL_TINH_TRANG_ID = b.ID
            ON v.PHAM_NHAN_ID = nl.PHAM_NHAN_ID
        WHERE (
            v_filter_dt = 0
            OR (
                v.NGAY_DEN_TRAI IS NOT NULL
                AND (v_tu_dt IS NULL OR TRUNC(CAST(v.NGAY_DEN_TRAI AS DATE)) >= v_tu_dt)
                AND (v_den_dt IS NULL OR TRUNC(CAST(v.NGAY_DEN_TRAI AS DATE)) <= v_den_dt)
            )
        )
    )
    SELECT
    ROW_NUMBER() OVER (ORDER BY ORDER_HOTEN(r.HO_TEN) NULLS LAST ) AS rn_all,
    COUNT(*) OVER() AS total_count,
        r.SO_HSLD,
        r.CCCD,
        r.HO_TEN,
        r.NGAY_SINH,
        r.GIOI_TINH,
        r.NOI_DKTT,
        r.TOI_DANH,
        r.AN_PHAT,
        --r.NGAY_BAT_AN_PHAT,
        TO_CHAR(r.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT_AN_PHAT,
        --r.NGAY_DEN_TRAI,
        TO_CHAR(r.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
        r.SO_DANG_KY,
        --r.NGAY_KET_THUC,
        TO_CHAR(r.NGAY_KET_THUC, 'DD/MM/YYYY') AS NGAY_KET_THUC,
        --r.NGAY_NOP_LUU,
        TO_CHAR(r.NGAY_NOP_LUU, 'DD/MM/YYYY') AS NGAY_NOP_LUU,
        r.SO_NAM_BAO_QUAN,
        r.LOAI_NOP_LUU,
        r.THOI_HAN_BAO_QUAN,
        r.PHAN_DOI
    FROM result_rows r
    ORDER BY ORDER_HOTEN(r.HO_TEN) --REGEXP_SUBSTR(r.HO_TEN, '[^ ]+$') DESC NULLS LAST, r.ngay_kt_sort DESC NULLS LAST, r.NL_ID DESC
    OFFSET v_skip ROWS
    FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i khi l\1ea5y danh s\00e1ch n\1ed9p l\01b0u: ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_NOP_LUU;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PHAM_NHAN_DUOC_AN_GIAM
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PHAM_NHAN_DUOC_AN_GIAM" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id IN  NUMBER    DEFAULT NULL,
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY
    p_skipcount  IN NUMBER DEFAULT NULL,
    p_maxresultcount  IN NUMBER DEFAULT NULL
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
   -- v_trai_giam_id NUMBER;
    v_tu_ngay   DATE;
    v_den_ngay  DATE;
    c1          SYS_REFCURSOR;
BEGIN

    v_skip  := NVL(p_skipcount, 0);
    v_limit := p_maxresultcount;
    -- Parse ngày
--     IF p_ma_trai_giam IS NULL OR p_ma_trai_giam = '' THEN
--        v_trai_giam_id := NULL;
--    ELSE
--        v_trai_giam_id := p_ma_trai_giam;
--    END IF;     
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
    WITH
    -- PN có ít nh?t 1 b?n ghi ân gi?m trong AN_GIAMS trong kho?ng ngày
    an_giam_one AS (
        SELECT ag.*
--        ,
--               ROW_NUMBER() OVER (
--                   PARTITION BY ag.PHAM_NHAN_ID
--                   ORDER BY NVL(ag.AG_NGAY_QD_CHU_TICH_NUOC, ag.AG_NGAY_QD_TOA_AN) DESC NULLS LAST,
--                            ag.ID DESC
--               ) AS rn --
        FROM AN_GIAMS ag
        WHERE NVL(ag.IS_DELETED, 0) = 0
--          AND (v_tu_ngay IS NULL OR TRUNC(NVL(ag.AG_NGAY_QD_CHU_TICH_NUOC, ag.AG_NGAY_QD_TOA_AN)) >= TRUNC(v_tu_ngay))
--          AND (v_den_ngay IS NULL OR TRUNC(NVL(ag.AG_NGAY_QD_CHU_TICH_NUOC, ag.AG_NGAY_QD_TOA_AN)) <= TRUNC(v_den_ngay))
--          AND (v_tu_ngay IS NULL OR TRUNC(ag.AG_NGAY_QD_CHU_TICH_NUOC) >= TRUNC(v_tu_ngay))
--          AND (v_den_ngay IS NULL OR TRUNC(ag.AG_NGAY_QD_CHU_TICH_NUOC) <= TRUNC(v_den_ngay))   
        AND (v_tu_ngay IS NULL OR TRUNC(ag.AG_NGAY_QD_CHU_TICH_NUOC) >= TRUNC(v_tu_ngay))
        AND (v_den_ngay IS NULL OR TRUNC(ag.AG_NGAY_QD_CHU_TICH_NUOC) <= TRUNC(v_den_ngay))               
    ),
    -- Ghi chú riêng (rule Lai l?ch): parse LL_GHI_CHU_RIENG (chu?i id) ? map DM_GHI_CHU_RIENGS.GCR_TEN
    gcr_raw AS (
        SELECT v.PHAM_NHAN_ID,
               REGEXP_REPLACE(NVL(TRIM(CAST(v.GHI_CHU_RIENG AS VARCHAR2(4000))), ''), '[[:space:]\[\]]', '') AS gcr_clean
        FROM VW_PN_LAI_LICH_CHI_TIET v
        INNER JOIN an_giam_one ag ON ag.PHAM_NHAN_ID = v.PHAM_NHAN_ID --AND ag.rn = 1
        WHERE v.GHI_CHU_RIENG IS NOT NULL
          AND REGEXP_COUNT(REGEXP_REPLACE(NVL(TRIM(CAST(v.GHI_CHU_RIENG AS VARCHAR2(4000))), ''), '[[:space:]\[\]]', ''), '[0-9]+') > 0
          AND NVL(v.IS_DELETED, 0) = 0

    ),
    gcr_ids AS (
        SELECT r.PHAM_NHAN_ID,
               TO_NUMBER(REGEXP_SUBSTR(r.gcr_clean, '[0-9]+', 1, LEVEL)) AS gcr_id,
               LEVEL AS ord
        FROM gcr_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.gcr_clean, '[0-9]+')
          AND PRIOR r.PHAM_NHAN_ID = r.PHAM_NHAN_ID
          AND PRIOR SYS_GUID() IS NOT NULL
    ),
    gcr_agg AS (
        SELECT ids.PHAM_NHAN_ID,
               SUBSTR(LISTAGG(CAST(g.GCR_TEN AS VARCHAR2(500)), ', ') WITHIN GROUP (ORDER BY ids.ord), 1, 2000) AS ghi_chu_rieng_ten
        FROM gcr_ids ids
        JOIN DM_GHI_CHU_RIENGS g ON g.ID = ids.gcr_id AND NVL(g.IS_DELETED, 0) = 0
        GROUP BY ids.PHAM_NHAN_ID
    )
    select   *
    from (
    SELECT
	        --ROW_NUMBER() OVER (ORDER BY v.HO_TEN, NVL(ag.AG_NGAY_QD_CHU_TICH_NUOC, ag.AG_NGAY_QD_TOA_AN) DESC NULLS LAST) AS rn_all,
            ROW_NUMBER() OVER (ORDER BY   ORDER_HOTEN(v.HO_TEN) NULLS LAST) AS rn_all,
            HO_TEN_ORDER,
	        COUNT(*) OVER() AS total_count,
	        v.SO_HO_SO                    AS SO_HSLD,
	        v.HO_TEN                      AS HO_TEN,
	        v.NGAY_SINH                   AS NS,
	        v.GIOI_TINH                   AS GT,
	        v.NOI_THUONG_TRU_DAY_DU       AS NOI_DKTT,
	        v.TOI_DANH                    AS TOI_DANH,
	        --v.NGAY_BAT_AN_PHAT            AS NGAY_BAT,
            TO_CHAR(v.NGAY_BAT_AN_PHAT, 'DD/mm/yyyy') AS NGAY_BAT,
	        v.AN_PHAT                     AS AN_PHAT,
	        --v.NGAY_DEN_TRAI               AS NGAY_DEN_TRAI,
             TO_CHAR(v.NGAY_DEN_TRAI, 'DD/mm/yyyy') AS NGAY_DEN_TRAI,
	        --v.NGAY_HET_AN                 AS NGAY_HET_HAN,
            TO_CHAR(v.NGAY_HET_AN, 'DD/mm/yyyy') AS NGAY_HET_HAN,
	        NVL(ag.AG_SO_QD_CHU_TICH_NUOC, ag.AG_SO_QD_TOA_AN) AS SO_QD,
	        NVL(TO_CHAR(ag.AG_NGAY_QD_CHU_TICH_NUOC, 'DD/mm/yyyy'), TO_CHAR(ag.AG_NGAY_QD_TOA_AN, 'DD/mm/yyyy')) AS NGAY_QD,
            --NVL(ag.AG_NGAY_QD_CHU_TICH_NUOC,ag.AG_NGAY_QD_TOA_AN) AS NGAY_QD,
	        -- GHI_CHU: ?u tiên AG_GHI_CHU; n?u không có thì dùng rule ghi chú riêng Lai l?ch (parse LL_GHI_CHU_RIENG ? DM_GHI_CHU_RIENGS.GCR_TEN) + GHI_CHU_CHI_TIET
	        NVL(ag.AG_GHI_CHU,
	            NVL(CAST(ga.ghi_chu_rieng_ten AS NVARCHAR2(2000)), u'') ||
	            CASE WHEN ga.ghi_chu_rieng_ten IS NOT NULL AND v.GHI_CHU_CHI_TIET IS NOT NULL THEN u' | ' ELSE u'' END ||
	            NVL(CAST(v.GHI_CHU_CHI_TIET AS NVARCHAR2(2000)), u'')) AS GHI_CHU,
	        dmttpn.TTPN_TEN               AS TINH_TRANG,
	        -- PHAN_DOI: phân ??i, phân tr?i
	        NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
	        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
	        NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
	    FROM an_giam_one ag
	    INNER JOIN VW_PN_LAI_LICH_CHI_TIET v
	        ON v.PHAM_NHAN_ID = ag.PHAM_NHAN_ID
	       AND NVL(v.IS_DELETED, 0) = 0
	    LEFT JOIN gcr_agg ga ON ga.PHAM_NHAN_ID = ag.PHAM_NHAN_ID
	    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn
	        ON v.LL_TINH_TRANG_ID = dmttpn.ID
	       AND NVL(dmttpn.IS_DELETED, 0) = 0
	    WHERE 1=1
        --ag.rn = 1
--	      AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_MA = p_ma_trai_giam)
--	      AND (p_tinh_trang_id is null or dmttpn.ID =  p_tinh_trang_id)
--	      AND (p_phan_doi_id is null or v.PHAN_DOI_ID = p_phan_doi_id)
     -- AND (p_ma_trai_giam IS NULL OR TRAI_GIAM_MA = p_ma_trai_giam)
      AND (p_ma_trai_giam IS NULL OR TRAI_GIAM_ID = (select id from dm_trai_giams where tg_ma = p_ma_trai_giam))
      AND (p_tinh_trang_id is null or dmttpn.ID =  p_tinh_trang_id)
      AND (p_phan_doi_id is null or PHAN_DOI_ID = p_phan_doi_id)          
	   -- ORDER BY v.HO_TEN, NVL(ag.AG_NGAY_QD_CHU_TICH_NUOC, ag.AG_NGAY_QD_TOA_AN) DESC NULLS LAST
--         ORDER BY HO_TEN_ORDER
--      OFFSET p_skipcount ROWS
--      FETCH NEXT NVL(p_maxresultcount, 99999999999) ROWS ONLY
    ) t
--             ORDER BY HO_TEN_ORDER
--      OFFSET p_skipcount ROWS
--      FETCH NEXT NVL(p_maxresultcount, 99999999999) ROWS ONLY
      WHERE t.rn_all > v_skip
      AND (v_limit  IS NULL  OR t.rn_all <= v_skip + v_limit)
    ORDER BY t.rn_all
    ;



    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân ???c ân gi?m: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_PHAM_NHAN_DUOC_AN_GIAM;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PHAM_NHAN_HIV_AIDS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PHAM_NHAN_HIV_AIDS" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id  IN  NUMBER    DEFAULT NULL,
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT 0  
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_den_ngay DATE;
    v_tu_ngay  DATE;
    c1         SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := TRUNC(SYSDATE);
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;
    OPEN c1 FOR

    WITH
    tha_hieu_luc AS (
        SELECT tha.tha_pnlai_lich_id AS pn_id
        FROM PN_THI_HANH_AN tha
        WHERE NVL(tha.is_deleted, 0) = 0
          AND tha.tha_pnlai_lich_id IS NOT NULL
          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) <= v_den_ngay
          AND (tha.tha_ngay_het_han IS NULL OR tha.tha_ngay_het_han >= v_den_ngay)
    ),
    pn_ghi_chu_raw AS (
        SELECT tha.tha_pnlai_lich_id AS pn_id,
               REPLACE(REPLACE(TRIM(NVL(tha.tha_ghi_chu_dac_biet, '[]')), '[', ''), ']', '') AS csv
        FROM PN_THI_HANH_AN tha
        WHERE NVL(tha.is_deleted, 0) = 0
          AND tha.tha_ghi_chu_dac_biet IS NOT NULL
          AND tha.tha_pnlai_lich_id IN (SELECT pn_id FROM tha_hieu_luc)
    ),
    pn_ghi_chu_ids AS (
        SELECT r.pn_id,
               TO_NUMBER(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL))) AS ghi_chu_id,
               LEVEL AS ord
        FROM pn_ghi_chu_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.csv, ',') + 1
          AND PRIOR r.csv   = r.csv
          AND PRIOR r.pn_id = r.pn_id
          AND PRIOR SYS_GUID() IS NOT NULL
          AND TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)) IS NOT NULL
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)), '^\d+$')
    ),
    pn_hiv_aids AS (
        SELECT DISTINCT ids.pn_id
        FROM pn_ghi_chu_ids ids
        JOIN DM_GHI_CHU_DAC_BIETS dm
          ON dm.id = ids.ghi_chu_id
         AND NVL(dm.is_deleted, 0) = 0
         AND (UPPER(NVL(dm.gcdb_ten, '')) LIKE '%HIV%' OR UPPER(NVL(dm.gcdb_ten, '')) LIKE '%AIDS%')
    ),
    gcdb_agg AS (
        SELECT ids.pn_id,
               SUBSTR(LISTAGG(CAST(dm.gcdb_ten AS VARCHAR2(500)), ', ') WITHIN GROUP (ORDER BY ids.ord), 1, 2000) AS benh_tat_ten
        FROM pn_ghi_chu_ids ids
        JOIN DM_GHI_CHU_DAC_BIETS dm
          ON dm.id = ids.ghi_chu_id
         AND NVL(dm.is_deleted, 0) = 0
        WHERE ids.pn_id IN (SELECT pn_id FROM pn_hiv_aids)
        GROUP BY ids.pn_id
    ),
    tha_den_trai AS (
        SELECT tha.tha_pnlai_lich_id AS pn_id,
               tha.tha_ngay_den_trai AS ngay_den_trai 
        FROM PN_THI_HANH_AN tha
        WHERE NVL(tha.is_deleted, 0) = 0
          AND tha.tha_pnlai_lich_id IN (SELECT pn_id FROM pn_hiv_aids)
    ),
    LL_one AS (
        SELECT * FROM (
            SELECT v.* 
            FROM VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
        ) x  
    ),
    dang_chap_hanh_hiv AS (
        SELECT ll.PHAM_NHAN_ID AS pn_lai_lich_id
        FROM LL_one ll
        INNER JOIN pn_hiv_aids h ON h.pn_id = ll.PHAM_NHAN_ID
        LEFT JOIN tha_den_trai td ON td.pn_id = ll.PHAM_NHAN_ID 
        WHERE 1 =1
        --and (p_ma_trai_giam IS NULL OR ll.TRAI_GIAM_MA = p_ma_trai_giam)
    AND (p_ma_trai_giam IS NULL OR ( ll.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))

          AND (v_tu_ngay IS NULL OR (td.ngay_den_trai IS NOT NULL AND TRUNC(td.ngay_den_trai) >= v_tu_ngay))
    )
    SELECT * FROM (
    SELECT
        --ROW_NUMBER() OVER (ORDER BY v.SO_HO_SO NULLS LAST) AS rn_all,
        ROW_NUMBER() OVER (ORDER BY  ORDER_HOTEN(v.HO_TEN) NULLS LAST) AS rn_all,
        COUNT(*) OVER() AS total_count,
        v.SO_HO_SO                    AS SO_HSLD,
        v.HO_TEN                      AS HO_TEN,
        v.NGAY_SINH                   AS NS,
        v.GIOI_TINH                   AS GT,
        v.NOI_THUONG_TRU_DAY_DU       AS NOI_DKTT,
        v.TOI_DANH                    AS TOI_DANH,
        --v.NGAY_BAT_AN_PHAT            AS NGAY_BAT,
        TO_CHAR(v.NGAY_BAT_AN_PHAT , 'DD/mm/yyyy') AS NGAY_BAT,
        v.AN_PHAT                     AS AN_PHAT,
        --v.NGAY_DEN_TRAI               AS NGAY_DEN_TRAI,
        TO_CHAR(v.NGAY_DEN_TRAI , 'DD/mm/yyyy') AS NGAY_DEN_TRAI,
        --v.NGAY_HET_AN                 AS NGAY_HET_HAN,
        TO_CHAR(v.NGAY_HET_AN , 'DD/mm/yyyy') AS NGAY_HET_HAN,
        NVL(CAST(ga.benh_tat_ten AS NVARCHAR2(2000)), u'') AS BENH_TAT,
--        CASE
--            WHEN NULLIF(TRIM(CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(d.pn_lai_lich_id) AS VARCHAR2(100))), '0') IS NULL
--            THEN u'Kh\00f4ng'
--            ELSE CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(d.pn_lai_lich_id) AS NVARCHAR2(2000))
--        END                            AS THOI_GIAN_DA_GIAM,
        case when THOI_GIAN_DA_GIAM is null or THOI_GIAN_DA_GIAM = 0 then  THOI_GIAN_DA_GIAM else null end  THOI_GIAN_DA_GIAM,
        --NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(d.pn_lai_lich_id), u'') AS THOI_GIAN_DA_CHAP_HANH,
        THOI_GIAN_DA_CHAP_HANH AS THOI_GIAN_DA_CHAP_HANH,
        --NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(d.pn_lai_lich_id), u'') AS THOI_GIAN_CON_LAI,
        THOI_GIAN_CON_LAI  AS THOI_GIAN_CON_LAI,
        dmttpn.TTPN_TEN                AS TINH_TRANG,
        NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), u'') ||
        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
        NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), u'') AS PHAN_DOI
    FROM dang_chap_hanh_hiv d
    INNER JOIN LL_one v ON v.PHAM_NHAN_ID = d.pn_lai_lich_id
    LEFT JOIN gcdb_agg ga ON ga.pn_id = v.PHAM_NHAN_ID
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn
        ON v.LL_TINH_TRANG_ID = dmttpn.ID
       AND NVL(dmttpn.IS_DELETED, 0) = 0
    WHERE 1 =1
    AND (p_tinh_trang_id IS NULL OR dmttpn.ID  = p_tinh_trang_id)
    AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)
   -- ORDER BY v.HO_TEN 
    )
    WHERE  rn_all > v_skip
      AND (v_limit = 0 OR rn_all <= v_skip + v_limit)
    ORDER BY rn_all ;      

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân nhi?m HIV/AIDS: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_PHAM_NHAN_HIV_AIDS;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PHAM_NHAN_HPBS_TIEN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PHAM_NHAN_HPBS_TIEN" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_noi_nop IN  NUMBER    DEFAULT NULL,
    p_tinh_trang_nop_tien IN  NUMBER    DEFAULT NULL, --1 DA NOP TIEN, 0 CH?A NOP TIEN
    p_toa_qd_tha IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id IN  NUMBER    DEFAULT NULL,
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
    p_in IN  NUMBER    DEFAULT 1,
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT 0     
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_den_ngay DATE;
    v_tu_ngay  DATE;
    c1         SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := TRUNC(SYSDATE);
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
    WITH
    -- PN ?ang ch?p hành án t?i ngày v_den_ngay: có THA hi?u l?c
    tha_hieu_luc AS (
        SELECT tha.tha_pnlai_lich_id AS pn_id
        FROM PN_THI_HANH_AN tha
        WHERE NVL(tha.is_deleted, 0) = 0
          AND tha.tha_pnlai_lich_id IS NOT NULL
          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) <= v_den_ngay
          AND (tha.tha_ngay_het_han IS NULL OR tha.tha_ngay_het_han >= v_den_ngay)
    ),
    tha_den_trai AS (
        SELECT tha.tha_pnlai_lich_id AS pn_id,
               tha.tha_ngay_den_trai AS ngay_den_trai,
               ROW_NUMBER() OVER (PARTITION BY tha.tha_pnlai_lich_id ORDER BY tha.tha_ngay_den_trai DESC NULLS LAST) AS rn
        FROM PN_THI_HANH_AN tha
        WHERE NVL(tha.is_deleted, 0) = 0
          AND tha.tha_pnlai_lich_id IN (SELECT pn_id FROM tha_hieu_luc)
    ),
    -- PN có HPBS ti?n: HPBS_TONG_TIEN_PHAT > 0 ho?c có PN_BIENLAIES
    hpbs_tien_pn AS (   
        SELECT DISTINCT hp.HPBS_MA_PHAM_NHAN AS pn_id,HPBS_TONG_TIEN_PHAT,  tong_da_nop
        FROM PN_HINH_PHAT_BO_SUNGS hp
        LEFT JOIN (
            SELECT HPBS_ID, SUM(NVL(BL_SO_TIEN, 0)) AS tong_da_nop
            FROM PN_BIENLAIES
            WHERE NVL(IS_DELETED, 0) = 0
            GROUP BY HPBS_ID
        ) bl ON bl.HPBS_ID = hp.ID

        LEFT JOIN (
            SELECT HPBS_ID,CQ_MA  FROM PN_BIENLAIES BL
            LEFT JOIN DM_CO_QUANS DMCQ ON DMCQ.CQ_MA = BL.BL_NOP_TAI_CO_QUAN
        ) bl ON bl.HPBS_ID = hp.ID     

        WHERE NVL(hp.IS_DELETED, 0) = 0
          AND hp.HPBS_MA_PHAM_NHAN IS NOT NULL
          AND HPBS_HINH_PHAT in (8, 12, 27)
          AND (NVL(hp.HPBS_TONG_TIEN_PHAT, 0) > 0 OR NVL(bl.tong_da_nop, 0) > 0)
          AND (p_noi_nop IS NULL OR CQ_MA = p_noi_nop)
    ),
    -- Ghi chú riêng Lai l?ch: parse LL_GHI_CHU_RIENG (chu?i id) ? map DM_GHI_CHU_RIENGS.GCR_TEN
    gcr_raw AS (
        SELECT v.PHAM_NHAN_ID,
               REGEXP_REPLACE(NVL(TRIM(CAST(v.GHI_CHU_RIENG AS VARCHAR2(4000))), u''), '[[:space:]\[\]]', u'') AS gcr_clean
        FROM VW_PN_LAI_LICH_CHI_TIET v
        INNER JOIN hpbs_tien_pn tp ON tp.pn_id = v.PHAM_NHAN_ID
        WHERE v.GHI_CHU_RIENG IS NOT NULL
          AND REGEXP_COUNT(REGEXP_REPLACE(NVL(TRIM(CAST(v.GHI_CHU_RIENG AS VARCHAR2(4000))), u''), '[[:space:]\[\]]', u''), '[0-9]+') > 0
          AND NVL(v.IS_DELETED, 0) = 0
    ),
    gcr_ids AS (
        SELECT r.PHAM_NHAN_ID,
               TO_NUMBER(REGEXP_SUBSTR(r.gcr_clean, '[0-9]+', 1, LEVEL)) AS gcr_id,
               LEVEL AS ord
        FROM gcr_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.gcr_clean, '[0-9]+')
          AND PRIOR r.PHAM_NHAN_ID = r.PHAM_NHAN_ID
          AND PRIOR SYS_GUID() IS NOT NULL
    ),
    gcr_agg AS (
        SELECT ids.PHAM_NHAN_ID,
               SUBSTR(LISTAGG(CAST(g.GCR_TEN AS VARCHAR2(500)), ', ') WITHIN GROUP (ORDER BY ids.ord), 1, 2000) AS ghi_chu_rieng_ten
        FROM gcr_ids ids
        JOIN DM_GHI_CHU_RIENGS g ON g.ID = ids.gcr_id AND NVL(g.IS_DELETED, 0) = 0
        GROUP BY ids.PHAM_NHAN_ID
    ),
    -- M?t LL m?i nh?t m?i PN (tránh dup t? VW_PN_LAI_LICH_CHI_TIET)
    LL_one AS (
        SELECT * FROM (
            SELECT v.*, ROW_NUMBER() OVER (PARTITION BY v.PHAM_NHAN_ID
                ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
                         v.CREATION_TIME DESC NULLS LAST) AS rn
            FROM VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
        ) x WHERE rn = 1
    ),
    -- PN ?ang ch?p hành án + có HPBS ti?n
    dang_chap_hanh_co_hpbs_tien AS (
        SELECT ll.PHAM_NHAN_ID AS pn_lai_lich_id, HPBS_TONG_TIEN_PHAT,tong_da_nop
        FROM LL_one ll
        INNER JOIN tha_hieu_luc t ON t.pn_id = ll.PHAM_NHAN_ID
        INNER JOIN hpbs_tien_pn h ON h.pn_id = ll.PHAM_NHAN_ID
        LEFT JOIN tha_den_trai td ON td.pn_id = ll.PHAM_NHAN_ID AND td.rn = 1
        WHERE 1 =1
        AND (p_ma_trai_giam IS NULL OR ll.TRAI_GIAM_MA = p_ma_trai_giam)
          AND (p_tinh_trang_nop_tien IS NULL OR( p_tinh_trang_nop_tien = 1 AND tong_da_nop IS NOT NULL )  OR ( p_tinh_trang_nop_tien = 0 AND tong_da_nop IS NULL ))
          AND (v_tu_ngay IS NULL OR (td.ngay_den_trai IS NOT NULL AND TRUNC(td.ngay_den_trai) >= v_tu_ngay))
    )
    SELECT * FROM (
    SELECT
        --ROW_NUMBER() OVER (ORDER BY v.HO_TEN NULLS LAST) AS rn_all,
        ROW_NUMBER() OVER (ORDER BY   ORDER_HOTEN(v.HO_TEN) NULLS LAST) AS rn_all,
        COUNT(*) OVER() AS total_count,
        SO_HO_SO,
        v.HO_TEN                      AS HO_TEN,
        v.NAM_SINH,
        v.NOI_THUONG_TRU_DAY_DU       AS DIA_CHI_THUONG_TRU,
        v.TOI_DANH                    AS TOI_DANH,
        NVL(TRIM(CAST(v.SO_TIEN_AN AS NVARCHAR2(200))), u'') AS SO_TA,
        v.ngay_den_trai,
        v.ngay_het_an,
        HPBS_TONG_TIEN_PHAT phai_nop,
        tong_da_nop,
        HPBS_TONG_TIEN_PHAT - nvl(tong_da_nop,0) as con_lai,
        v.NGAY_BAT_AN_PHAT            AS NGAY_BAT,
        v.AN_PHAT                     AS AN_PHAT,
        v.SO_BAN_AN                   AS AN_SO,
        v.NGAY_BAN_AN                 AS NGAY_XU_TOA_XU,
        TOA_XU_TEN as toa_xu,
        TOA_XU_DIA_PHUONG as toa_xu_dp,
        v.SO_QD_THA                   AS QD_THAN,
        v.NGAY_QD_THA                 AS NGAY_XU_TOA_QD,
        CO_QUAN_QD_THA as toa_qd,
        TOA_QD_THA_DIA_PHUONG toa_qd_tha_dp,
        CASE
            WHEN NULLIF(TRIM(CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(d.pn_lai_lich_id) AS VARCHAR2(100))), '0') IS NULL
            THEN u'Kh\00f4ng'
            ELSE CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(d.pn_lai_lich_id) AS NVARCHAR2(2000))
        END                           AS DA_GIAM,
        v.NGAY_DEN_TRAI               AS DEN_TRAI,
        v.NGAY_HET_AN                  AS HET_HAN,
        NVL(FN_GET_LIET_KE_HPBS_TIEN(d.pn_lai_lich_id), u'') AS HPBS,
        -- GHI_CHU = ghi chú riêng Lai l?ch (LL_GHI_CHU_RIENG ? DM_GHI_CHU_RIENGS.GCR_TEN)
        NVL(CAST(ga.ghi_chu_rieng_ten AS NVARCHAR2(2000)), u'') AS GHI_CHU,
        NVL(TRIM(CAST(v.PHAN_DOI AS NVARCHAR2(200))), u'') ||
        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
        NVL(TRIM(CAST(v.PHAN_TRAI AS NVARCHAR2(200))), u'') AS PHAN_DOI        
    FROM dang_chap_hanh_co_hpbs_tien d
    INNER JOIN LL_one v ON v.PHAM_NHAN_ID = d.pn_lai_lich_id
    LEFT JOIN gcr_agg ga ON ga.PHAM_NHAN_ID = v.PHAM_NHAN_ID
    LEFT JOIN DM_TINH_THANH_PHO toa_qd_dttp 
    ON v.TOA_QD_THA_DIA_PHUONG = toa_qd_dttp.TTP_TEN 
    AND NVL(toa_qd_dttp.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn
        ON v.LL_TINH_TRANG_ID = dmttpn.ID
       AND NVL(dmttpn.IS_DELETED, 0) = 0    
    WHERE 1 = 1
        AND (p_tinh_trang_id IS NULL OR dmttpn.ID = p_tinh_trang_id)
        AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)
        AND (p_toa_qd_tha IS NULL OR toa_qd_dttp.id = p_toa_qd_tha)
    --ORDER BY v.HO_TEN
    )
    WHERE  rn_all > v_skip
    AND (v_limit = 0 OR rn_all <= v_skip + v_limit)
    ORDER BY rn_all   ;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân có HPBS ti?n: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_PHAM_NHAN_HPBS_TIEN;




/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PHAM_NHAN_NGHIEN_MA_TUY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PHAM_NHAN_NGHIEN_MA_TUY" (
    p_ma_trai_giam         IN  NVARCHAR2 DEFAULT NULL,
    p_tu_ngay              IN  VARCHAR2 DEFAULT NULL,
    p_den_ngay             IN  VARCHAR2 DEFAULT NULL,
    p_don_vi_id            IN  NUMBER DEFAULT NULL,
    p_tinh_trang_id        IN  NUMBER DEFAULT NULL,
    p_chat_ma_tuy_id       IN  VARCHAR2 DEFAULT NULL,
    p_hinh_thuc_sd_id      IN  VARCHAR2 DEFAULT NULL,
    p_thuong_tru_tinh_id   IN  NUMBER DEFAULT NULL,
    p_ra_trai_tu_ngay      IN  VARCHAR2 DEFAULT NULL,
    p_ra_trai_den_ngay     IN  VARCHAR2 DEFAULT NULL,
    p_so_ngay_sd_tu        IN  NUMBER DEFAULT NULL,
    p_so_ngay_sd_den       IN  NUMBER DEFAULT NULL,
    p_tinh_trang_nghien    IN  NUMBER DEFAULT NULL,
    p_skipcount            IN  NUMBER DEFAULT NULL,
    p_maxresultcount       IN  NUMBER DEFAULT NULL
)
AS
    v_den_ngay     DATE;
    v_tu_ngay      DATE;
    v_ra_trai_tu   DATE;
    v_ra_trai_den  DATE;
    v_skip         NUMBER;
    v_limit        NUMBER;
    v_trai_giam_id NUMBER;
    c1             SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    IF p_ma_trai_giam IS NULL OR p_ma_trai_giam = '' THEN
        v_trai_giam_id := NULL;
    ELSE
        v_trai_giam_id := p_ma_trai_giam;
    END IF;

    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := TRUNC(SYSDATE);
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_ra_trai_tu_ngay IS NULL OR TRIM(p_ra_trai_tu_ngay) = '' THEN
        v_ra_trai_tu := NULL;
    ELSE
        v_ra_trai_tu := TO_DATE(TRIM(p_ra_trai_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_ra_trai_den_ngay IS NULL OR TRIM(p_ra_trai_den_ngay) = '' THEN
        v_ra_trai_den := NULL;
    ELSE
        v_ra_trai_den := TO_DATE(TRIM(p_ra_trai_den_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
    SELECT *
    FROM (
        SELECT
            ROW_NUMBER() OVER (ORDER BY ORDER_HOTEN(q.HO_TEN) NULLS LAST) AS STT,
            q.HO_TEN,
            q.GIOI_TINH,
            q.NAM_SINH,
            q.DIA_CHI_THUONG_TRU,
            q.TOI_DANH,
            q.SO_TA,
            TO_CHAR(q.NGAY_BAT, 'DD/mm/yyyy') AS NGAY_BAT,
            q.AN_PHAT,
            TO_CHAR(q.NGAY_DEN_TRAI, 'DD/mm/yyyy') AS NGAY_DEN_TRAI,
            q.DA_GIAM,
            q.DA_CHAP_HANH,
            q.CON_LAI,
            TO_CHAR(q.HET_HAN, 'DD/mm/yyyy') AS HET_HAN,
            q.CHAT_MA_TUY,
            q.HINH_THUC_SU_DUNG,
            q.THOI_GIAN_SU_DUNG,
            PHAN_DOI,
            q.GHI_CHU,
            COUNT(*) OVER () AS total_count
        FROM (
            WITH
            chat_mt_filter AS (
                SELECT DISTINCT
                    TRIM(
                        REGEXP_SUBSTR(
                            REGEXP_REPLACE(TRIM(CAST(p_chat_ma_tuy_id AS VARCHAR2(4000))), '\s+', ''),
                            '[^,]+',
                            1,
                            LEVEL
                        )
                    ) AS chat_ma_tuy_id
                FROM dual
                CONNECT BY REGEXP_SUBSTR(
                    REGEXP_REPLACE(TRIM(CAST(p_chat_ma_tuy_id AS VARCHAR2(4000))), '\s+', ''),
                    '[^,]+',
                    1,
                    LEVEL
                ) IS NOT NULL
            ),
            hinh_thuc_sd_filter AS (
                SELECT DISTINCT
                    TRIM(
                        REGEXP_SUBSTR(
                            REGEXP_REPLACE(TRIM(CAST(p_hinh_thuc_sd_id AS VARCHAR2(4000))), '\s+', ''),
                            '[^,]+',
                            1,
                            LEVEL
                        )
                    ) AS hinh_thuc_sd_id
                FROM dual
                CONNECT BY REGEXP_SUBSTR(
                    REGEXP_REPLACE(TRIM(CAST(p_hinh_thuc_sd_id AS VARCHAR2(4000))), '\s+', ''),
                    '[^,]+',
                    1,
                    LEVEL
                ) IS NOT NULL
            ),
            base AS (
                SELECT ll.PHAM_NHAN_ID AS pn_lai_lich_id,
                       ll.GIOI_TINH,
                       ll.NAM_SINH,
                       ll.NGAY_DEN_TRAI,
                       PHAN_DOI
                FROM (
                    SELECT v.PHAM_NHAN_ID,
                           v.HO_TEN,
                           v.GIOI_TINH,
                           v.NAM_SINH,
                           v.NOI_THUONG_TRU_DAY_DU,
                           v.TOI_DANH,
                           v.SO_TIEN_AN,
                           v.NGAY_BAT_AN_PHAT,
                           v.AN_PHAT,
                           v.NGAY_HET_AN,
                           v.NGAY_DEN_TRAI,
                           v.TRAI_GIAM_MA,
                           v.TRAI_GIAM_ID,
                           v.PHAN_DOI_ID,
                           v.LL_TINH_TRANG_ID,
                           v.CREATION_TIME,
                           NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
                           CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
                           NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
--                           ROW_NUMBER() OVER (
--                               PARTITION BY v.PHAM_NHAN_ID
--                               ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
--                                        v.CREATION_TIME DESC NULLS LAST
--                           ) AS rn
                    FROM VW_PN_LAI_LICH_CHI_TIET v
                    WHERE NVL(v.IS_DELETED, 0) = 0
                ) ll
                INNER JOIN (
                    SELECT DISTINCT tha.tha_pnlai_lich_id
                    FROM PN_THI_HANH_AN tha
                    WHERE NVL(tha.is_deleted, 0) = 0
                      AND tha.tha_pnlai_lich_id IS NOT NULL
                      AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
                ) t ON t.tha_pnlai_lich_id = ll.PHAM_NHAN_ID
                INNER JOIN (
                    SELECT DISTINCT nmt.NMT_PN_LAI_LICH_ID
                    FROM PN_NGHIEN_MT nmt
                    WHERE NVL(nmt.IS_DELETED, 0) = 0
                    AND (p_tinh_trang_nghien IS NULL OR NMT_TINH_TRANG_NGHIEN = p_tinh_trang_nghien)
                      AND nmt.NMT_PN_LAI_LICH_ID IS NOT NULL
                      AND (
                          p_chat_ma_tuy_id IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM chat_mt_filter ctf
                              WHERE INSTR(
                                  ',' || REPLACE(REPLACE(REPLACE(NVL(TRIM(CAST(nmt.NMT_CHAT_MA_TUY AS VARCHAR2(4000))), ''), '[', ''), ']', ''), ' ', '') || ',',
                                  ',' || ctf.chat_ma_tuy_id || ','
                              ) > 0
                          )
                      )
                      AND (
                          p_hinh_thuc_sd_id IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM hinh_thuc_sd_filter htf
                              WHERE INSTR(
                                  ',' || REPLACE(REPLACE(REPLACE(NVL(TRIM(CAST(nmt.NMT_HINH_THUC_SD AS VARCHAR2(4000))), ''), '[', ''), ']', ''), ' ', '') || ',',
                                  ',' || htf.hinh_thuc_sd_id || ','
                              ) > 0
                          )
                      )
                      AND (
                          p_so_ngay_sd_tu IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM PN_NGHIEN_MT n2
                              WHERE n2.NMT_PN_LAI_LICH_ID = nmt.NMT_PN_LAI_LICH_ID
                                AND NVL(n2.IS_DELETED, 0) = 0
                                AND n2.NMT_THOI_HAN_SD IS NOT NULL
                                AND n2.NMT_THOI_HAN_SD >= p_so_ngay_sd_tu
                          )
                      )
                      AND (
                          p_so_ngay_sd_den IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM PN_NGHIEN_MT n2
                              WHERE n2.NMT_PN_LAI_LICH_ID = nmt.NMT_PN_LAI_LICH_ID
                                AND NVL(n2.IS_DELETED, 0) = 0
                                AND n2.NMT_THOI_HAN_SD IS NOT NULL
                                AND n2.NMT_THOI_HAN_SD <= p_so_ngay_sd_tu
                          )
                      )
                ) p ON p.NMT_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                LEFT JOIN (
                    SELECT tha.tha_pnlai_lich_id,
                           tha.tha_ngay_den_trai
--                           ROW_NUMBER() OVER (
--                               PARTITION BY tha.tha_pnlai_lich_id
--                               ORDER BY tha.tha_ngay_den_trai DESC NULLS LAST
--                           ) AS rn
                    FROM PN_THI_HANH_AN tha
                    WHERE NVL(tha.is_deleted, 0) = 0
                      AND tha.tha_pnlai_lich_id IN (
                          SELECT tha2.tha_pnlai_lich_id
                          FROM PN_THI_HANH_AN tha2
                          WHERE NVL(tha2.is_deleted, 0) = 0
--                            AND tha2.tha_pnlai_lich_id IS NOT NULL
--                            AND COALESCE(tha2.tha_ngay_bat_dau_o_tu, tha2.tha_ngay_bat) IS NOT NULL
                      )
                ) td ON td.tha_pnlai_lich_id = ll.PHAM_NHAN_ID --AND td.rn = 1
                WHERE 1=1 --ll.rn = 1
                  --AND (p_ma_trai_giam IS NULL OR ll.TRAI_GIAM_MA = p_ma_trai_giam)
                  AND (p_ma_trai_giam IS NULL OR ( ll.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
                  AND (p_don_vi_id IS NULL OR ll.PHAN_DOI_ID = p_don_vi_id)
                  AND (p_tinh_trang_id IS NULL OR ll.LL_TINH_TRANG_ID = p_tinh_trang_id)
                  AND (
                      p_thuong_tru_tinh_id IS NULL
                      OR EXISTS (
                          SELECT 1
                          FROM PN_LAI_LICHS pll
                          WHERE pll.ID = ll.PHAM_NHAN_ID
                            AND NVL(pll.IS_DELETED, 0) = 0
                            AND pll.LL_DIA_CHI_THUONG_TRU_PROVICE = p_thuong_tru_tinh_id
                      )
                  )
                  AND (
                      v_tu_ngay IS NULL
                      OR (
                          td.tha_ngay_den_trai IS NOT NULL
                          AND  td.tha_ngay_den_trai  >= v_tu_ngay
                      )
                  )
                  AND (
                      v_den_ngay IS NULL
                      OR (
                          td.tha_ngay_den_trai IS NOT NULL
                          AND  td.tha_ngay_den_trai  <= v_den_ngay
                      )
                  )
                  AND (
                      v_ra_trai_tu IS NULL
                      OR EXISTS (
                          SELECT 1
                          FROM PN_THI_HANH_AN tha_r
                          WHERE tha_r.tha_pnlai_lich_id = ll.PHAM_NHAN_ID
                            AND NVL(tha_r.is_deleted, 0) = 0
                            AND COALESCE(tha_r.tha_ngay_bat_dau_o_tu, tha_r.tha_ngay_bat) IS NOT NULL
                            AND tha_r.tha_ngay_het_han IS NOT NULL
                            AND TRUNC(tha_r.tha_ngay_het_han) >= v_ra_trai_tu
                      )
                  )
                  AND (
                      v_ra_trai_den IS NULL
                      OR EXISTS (
                          SELECT 1
                          FROM PN_THI_HANH_AN tha_r
                          WHERE tha_r.tha_pnlai_lich_id = ll.PHAM_NHAN_ID
                            AND NVL(tha_r.is_deleted, 0) = 0
                            AND COALESCE(tha_r.tha_ngay_bat_dau_o_tu, tha_r.tha_ngay_bat) IS NOT NULL
                            AND tha_r.tha_ngay_het_han IS NOT NULL
                            AND TRUNC(tha_r.tha_ngay_het_han) <= v_ra_trai_den
                      )
                  )
            )
            SELECT
                v.HO_TEN,
                v.HO_TEN AS HO_TEN_SORT,
                v.NAM_SINH,
                v.GIOI_TINH,
                PHAN_DOI,
                NVL(TRIM(CAST(v.NOI_THUONG_TRU_DAY_DU AS NVARCHAR2(2000))), u'') AS DIA_CHI_THUONG_TRU,
                NVL(TRIM(CAST(v.TOI_DANH AS NVARCHAR2(2000))), u'') AS TOI_DANH,
                NVL(TRIM(CAST(v.SO_TIEN_AN AS NVARCHAR2(200))), u'') AS SO_TA,
                v.NGAY_BAT_AN_PHAT AS NGAY_BAT,
                v.AN_PHAT AS AN_PHAT,
                CASE
                    WHEN NULLIF(TRIM(CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(d.pn_lai_lich_id) AS VARCHAR2(2000))), '0') IS NULL
                    THEN u'Không'
                    ELSE CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(d.pn_lai_lich_id) AS NVARCHAR2(2000))
                END AS DA_GIAM,
                THOI_GIAN_DA_CHAP_HANH AS DA_CHAP_HANH,
                THOI_GIAN_CON_LAI AS CON_LAI,
                v.NGAY_HET_AN AS HET_HAN,
                v.NGAY_DEN_TRAI AS NGAY_DEN_TRAI,
                NVL(TRIM(CAST(ca.chat_ma_tuy AS NVARCHAR2(2000))), u'') AS CHAT_MA_TUY,
                NVL(TRIM(CAST(ha.hinh_thuc_sd AS NVARCHAR2(2000))), u'') AS HINH_THUC_SU_DUNG,
                NVL(TRIM(CAST(ta.thoi_gian_sd AS NVARCHAR2(500))), u'') AS THOI_GIAN_SU_DUNG,
                NVL(CAST(dmttpn.TTPN_TEN AS NVARCHAR2(2000)), u'') AS GHI_CHU
            FROM base d
            INNER JOIN (
                SELECT v.PHAM_NHAN_ID,
                       v.HO_TEN,
                       v.GIOI_TINH,
                       v.NAM_SINH,
                       v.NOI_THUONG_TRU_DAY_DU,
                       v.TOI_DANH,
                       v.SO_TIEN_AN,
                       v.NGAY_BAT_AN_PHAT,
                       v.AN_PHAT,
                       v.NGAY_HET_AN,
                       v.TRAI_GIAM_MA,
                       v.TRAI_GIAM_ID,
                       v.PHAN_DOI_ID,
                       v.LL_TINH_TRANG_ID,
                       v.CREATION_TIME,
                       v.NGAY_DEN_TRAI,
                       v.THOI_GIAN_DA_CHAP_HANH,
                       v.THOI_GIAN_CON_LAI
                FROM (
                    SELECT v.*
--                           ROW_NUMBER() OVER (
--                               PARTITION BY v.PHAM_NHAN_ID
--                               ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
--                                        v.CREATION_TIME DESC NULLS LAST
--                           ) AS rn
                    FROM VW_PN_LAI_LICH_CHI_TIET v
                    WHERE NVL(v.IS_DELETED, 0) = 0
                ) v
--                INNER JOIN (
--                    SELECT DISTINCT tha.tha_pnlai_lich_id,
--                           MTGCH.MTG_TITLE THA_THOI_GIAN_DA_CHAP_HANH,
--                           MTGCL.MTG_TITLE THA_THOI_GIAN_CON_LAI
--                    FROM PN_THI_HANH_AN tha
--                    LEFT JOIN DM_MA_THOI_GIANS MTGCH
--                        ON THA_THOI_GIAN_DA_CHAP_HANH = MTGCH.MTG_MA
--                    LEFT JOIN DM_MA_THOI_GIANS MTGCL
--                        ON THA_THOI_GIAN_CON_LAI = MTGCL.MTG_MA
--                    WHERE NVL(tha.is_deleted, 0) = 0
--                      AND tha.tha_pnlai_lich_id IS NOT NULL
--                      AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
--                ) t ON t.tha_pnlai_lich_id = v.PHAM_NHAN_ID
                INNER JOIN (
                    SELECT DISTINCT nmt.NMT_PN_LAI_LICH_ID
                    FROM PN_NGHIEN_MT nmt
                    WHERE NVL(nmt.IS_DELETED, 0) = 0
                      AND nmt.NMT_PN_LAI_LICH_ID IS NOT NULL
                      AND (p_tinh_trang_nghien IS NULL OR NMT_TINH_TRANG_NGHIEN = p_tinh_trang_nghien)
                      AND (
                          p_chat_ma_tuy_id IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM chat_mt_filter ctf
                              WHERE INSTR(
                                  ',' || REPLACE(REPLACE(REPLACE(NVL(TRIM(CAST(nmt.NMT_CHAT_MA_TUY AS VARCHAR2(4000))), ''), '[', ''), ']', ''), ' ', '') || ',',
                                  ',' || ctf.chat_ma_tuy_id || ','
                              ) > 0
                          )
                      )
                      AND (
                          p_hinh_thuc_sd_id IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM hinh_thuc_sd_filter htf
                              WHERE INSTR(
                                  ',' || REPLACE(REPLACE(REPLACE(NVL(TRIM(CAST(nmt.NMT_HINH_THUC_SD AS VARCHAR2(4000))), ''), '[', ''), ']', ''), ' ', '') || ',',
                                  ',' || htf.hinh_thuc_sd_id || ','
                              ) > 0
                          )
                      )
                      AND (
                          p_so_ngay_sd_tu IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM PN_NGHIEN_MT n2
                              LEFT JOIN DM_MA_THOI_GIANS DMTG ON DMTG.ID = n2.NMT_THOI_HAN_SD
                              WHERE n2.NMT_PN_LAI_LICH_ID = nmt.NMT_PN_LAI_LICH_ID
                                AND NVL(n2.IS_DELETED, 0) = 0
                                AND n2.NMT_THOI_HAN_SD IS NOT NULL
                                AND DMTG.MTG_MA >= (SELECT MTG_MA FROM DM_MA_THOI_GIANS WHERE ID = p_so_ngay_sd_tu)
                          )
                      )
                      AND (
                          p_so_ngay_sd_den IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM PN_NGHIEN_MT n2
                              LEFT JOIN DM_MA_THOI_GIANS DMTG ON DMTG.ID = n2.NMT_THOI_HAN_SD
                              WHERE n2.NMT_PN_LAI_LICH_ID = nmt.NMT_PN_LAI_LICH_ID
                                AND NVL(n2.IS_DELETED, 0) = 0
                                AND n2.NMT_THOI_HAN_SD IS NOT NULL
                                AND DMTG.MTG_MA <= (SELECT MTG_MA FROM DM_MA_THOI_GIANS WHERE ID = p_so_ngay_sd_den)
                          )
                      )
                ) p ON p.NMT_PN_LAI_LICH_ID = v.PHAM_NHAN_ID
                LEFT JOIN (
                    SELECT tha.tha_pnlai_lich_id,
                           tha.tha_ngay_den_trai
--                           ROW_NUMBER() OVER (
--                               PARTITION BY tha.tha_pnlai_lich_id
--                               ORDER BY tha.tha_ngay_den_trai DESC NULLS LAST
--                           ) AS rn
                    FROM PN_THI_HANH_AN tha
                    WHERE NVL(tha.is_deleted, 0) = 0
                      AND tha.tha_pnlai_lich_id IN (
                          SELECT tha2.tha_pnlai_lich_id
                          FROM PN_THI_HANH_AN tha2
                          WHERE NVL(tha2.is_deleted, 0) = 0 
                      )
                ) td ON td.tha_pnlai_lich_id = v.PHAM_NHAN_ID --AND td.rn = 1
                WHERE 1=1 -- v.rn = 1
                  --AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_MA = p_ma_trai_giam)
          AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))  

                  AND (p_don_vi_id IS NULL OR v.PHAN_DOI_ID = p_don_vi_id)
                  AND (p_tinh_trang_id IS NULL OR v.LL_TINH_TRANG_ID = p_tinh_trang_id)
                  AND (
                      p_thuong_tru_tinh_id IS NULL
                      OR EXISTS (
                          SELECT 1
                          FROM PN_LAI_LICHS pll
                          WHERE pll.ID = v.PHAM_NHAN_ID
                            AND NVL(pll.IS_DELETED, 0) = 0
                            AND pll.LL_DIA_CHI_THUONG_TRU_PROVICE = p_thuong_tru_tinh_id
                      )
                  )
                  AND (
                      v_tu_ngay IS NULL
                      OR (  td.tha_ngay_den_trai  >= v_tu_ngay
                      )
                  )
                  AND (
                      v_den_ngay IS NULL
                      OR (   td.tha_ngay_den_trai  <= v_den_ngay
                      )
                  )
                  AND (
                      v_ra_trai_tu IS NULL
                      OR EXISTS (
                          SELECT 1
                          FROM PN_THI_HANH_AN tha_r
                          WHERE tha_r.tha_pnlai_lich_id = v.PHAM_NHAN_ID
                            AND NVL(tha_r.is_deleted, 0) = 0
                            AND COALESCE(tha_r.tha_ngay_bat_dau_o_tu, tha_r.tha_ngay_bat) IS NOT NULL
                            AND tha_r.tha_ngay_het_han IS NOT NULL
                            AND TRUNC(tha_r.tha_ngay_het_han) >= v_ra_trai_tu
                      )
                  )
                  AND (
                      v_ra_trai_den IS NULL
                      OR EXISTS (
                          SELECT 1
                          FROM PN_THI_HANH_AN tha_r
                          WHERE tha_r.tha_pnlai_lich_id = v.PHAM_NHAN_ID
                            AND NVL(tha_r.is_deleted, 0) = 0
                            AND COALESCE(tha_r.tha_ngay_bat_dau_o_tu, tha_r.tha_ngay_bat) IS NOT NULL
                            AND tha_r.tha_ngay_het_han IS NOT NULL
                            AND TRUNC(tha_r.tha_ngay_het_han) <= v_ra_trai_den
                      )
                  )
            ) v ON v.PHAM_NHAN_ID = d.pn_lai_lich_id
            LEFT JOIN (
                SELECT pn_id,
                       LISTAGG(chat_ten, ', ') WITHIN GROUP (ORDER BY chat_ten) AS chat_ma_tuy
                FROM (
                    SELECT DISTINCT nmt.NMT_PN_LAI_LICH_ID AS pn_id,
                           CAST(dmcmt.CMT_TEN AS VARCHAR2(2000)) AS chat_ten
                    FROM PN_NGHIEN_MT nmt
                    INNER JOIN (
                        SELECT v.PHAM_NHAN_ID,
                               v.TRAI_GIAM_MA,
                               v.TRAI_GIAM_ID,
                               v.PHAN_DOI_ID,
                               v.LL_TINH_TRANG_ID
--                               ROW_NUMBER() OVER (
--                                   PARTITION BY v.PHAM_NHAN_ID
--                                   ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
--                                            v.CREATION_TIME DESC NULLS LAST
--                               ) AS rn
                        FROM VW_PN_LAI_LICH_CHI_TIET v
                        WHERE NVL(v.IS_DELETED, 0) = 0
                    ) v_ll ON v_ll.PHAM_NHAN_ID = nmt.NMT_PN_LAI_LICH_ID --AND v_ll.rn = 1
                    INNER JOIN PN_THI_HANH_AN tha ON tha.tha_pnlai_lich_id = nmt.NMT_PN_LAI_LICH_ID
                    INNER JOIN (
                        SELECT LEVEL AS lv FROM dual CONNECT BY LEVEL <= 30
                    ) nums ON nums.lv <= REGEXP_COUNT(REGEXP_REPLACE(NVL(TRIM(nmt.NMT_CHAT_MA_TUY), ''), '[][]', ''), '\d+')
                    LEFT JOIN DM_CHAT_MA_TUIES dmcmt
                        ON dmcmt.ID = TO_NUMBER(
                            TRIM(
                                REGEXP_SUBSTR(
                                    REGEXP_REPLACE(NVL(TRIM(nmt.NMT_CHAT_MA_TUY), ''), '[][]', ''),
                                    '\d+',
                                    1,
                                    nums.lv
                                )
                            )
                        )
                       AND NVL(dmcmt.IS_DELETED, 0) = 0
                    WHERE NVL(nmt.IS_DELETED, 0) = 0
                      AND NVL(tha.is_deleted, 0) = 0
                      AND tha.tha_pnlai_lich_id IS NOT NULL
                      AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
                     -- AND (p_ma_trai_giam IS NULL OR v_ll.TRAI_GIAM_MA = p_ma_trai_giam)
                      AND (p_ma_trai_giam IS NULL OR ( v_ll.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam))) 
                      AND (p_don_vi_id IS NULL OR v_ll.PHAN_DOI_ID = p_don_vi_id)
                      AND (p_tinh_trang_id IS NULL OR v_ll.LL_TINH_TRANG_ID = p_tinh_trang_id)
                      AND (
                          p_thuong_tru_tinh_id IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM PN_LAI_LICHS pll
                              WHERE pll.ID = nmt.NMT_PN_LAI_LICH_ID
                                AND NVL(pll.IS_DELETED, 0) = 0
                                AND pll.LL_DIA_CHI_THUONG_TRU_PROVICE = p_thuong_tru_tinh_id
                          )
                      )
                      AND (
                          v_tu_ngay IS NULL
                          OR ( tha.tha_ngay_den_trai  >= v_tu_ngay
                          )
                      )
                      AND (
                          v_den_ngay IS NULL
                          OR ( tha.tha_ngay_den_trai  <= v_den_ngay
                          )
                      )
                      AND (
                          v_ra_trai_tu IS NULL
                          OR ( tha.tha_ngay_het_han  >= v_ra_trai_tu
                          )
                      )
                      AND (
                          v_ra_trai_den IS NULL
                          OR (
                              tha.tha_ngay_het_han IS NOT NULL
                              AND TRUNC(tha.tha_ngay_het_han) <= v_ra_trai_den
                          )
                      )
                      AND (
                          p_chat_ma_tuy_id IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM chat_mt_filter ctf
                              WHERE INSTR(
                                  ',' || REPLACE(REPLACE(REPLACE(NVL(TRIM(CAST(nmt.NMT_CHAT_MA_TUY AS VARCHAR2(4000))), ''), '[', ''), ']', ''), ' ', '') || ',',
                                  ',' || ctf.chat_ma_tuy_id || ','
                              ) > 0
                          )
                      )
                      AND (
                          p_hinh_thuc_sd_id IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM hinh_thuc_sd_filter htf
                              WHERE INSTR(
                                  ',' || REPLACE(REPLACE(REPLACE(NVL(TRIM(CAST(nmt.NMT_HINH_THUC_SD AS VARCHAR2(4000))), ''), '[', ''), ']', ''), ' ', '') || ',',
                                  ',' || htf.hinh_thuc_sd_id || ','
                              ) > 0
                          )
                      )
                      AND (
                          p_so_ngay_sd_tu IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM PN_NGHIEN_MT n2
                              LEFT JOIN DM_MA_THOI_GIANS DMTG ON DMTG.ID = n2.NMT_THOI_HAN_SD
                              WHERE n2.NMT_PN_LAI_LICH_ID = nmt.NMT_PN_LAI_LICH_ID
                                AND NVL(n2.IS_DELETED, 0) = 0
                                AND n2.NMT_THOI_HAN_SD IS NOT NULL
                                AND DMTG.MTG_MA >= (SELECT MTG_MA FROM DM_MA_THOI_GIANS WHERE ID = p_so_ngay_sd_tu)
                          )
                      )
                      AND (
                          p_so_ngay_sd_den IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM PN_NGHIEN_MT n2
                              LEFT JOIN DM_MA_THOI_GIANS DMTG ON DMTG.ID = n2.NMT_THOI_HAN_SD
                              WHERE n2.NMT_PN_LAI_LICH_ID = nmt.NMT_PN_LAI_LICH_ID
                                AND NVL(n2.IS_DELETED, 0) = 0
                                AND n2.NMT_THOI_HAN_SD IS NOT NULL
                                AND DMTG.MTG_MA <= (SELECT MTG_MA FROM DM_MA_THOI_GIANS WHERE ID = p_so_ngay_sd_den)
                          )
                      )
                      AND nmt.NMT_CHAT_MA_TUY IS NOT NULL
                      AND REGEXP_SUBSTR(
                          REGEXP_REPLACE(NVL(TRIM(nmt.NMT_CHAT_MA_TUY), ''), '[][]', ''),
                          '\d+',
                          1,
                          nums.lv
                      ) IS NOT NULL
                )
                GROUP BY pn_id
            ) ca ON ca.pn_id = d.pn_lai_lich_id
            LEFT JOIN (
                SELECT x.pn_id_lv AS pn_id,
                       LISTAGG(CAST(x.ht_ten AS VARCHAR2(2000)), ', ') WITHIN GROUP (ORDER BY x.ht_ten) AS hinh_thuc_sd
                FROM (
                    SELECT DISTINCT
                        nmt.NMT_PN_LAI_LICH_ID AS pn_id_lv,
                        dm.HTSDMT_TEN AS ht_ten
                    FROM PN_NGHIEN_MT nmt
                    INNER JOIN (
                        SELECT v.PHAM_NHAN_ID,
                               v.TRAI_GIAM_MA,
                               v.TRAI_GIAM_ID,
                               v.PHAN_DOI_ID,
                               v.LL_TINH_TRANG_ID
--                               ROW_NUMBER() OVER (
--                                   PARTITION BY v.PHAM_NHAN_ID
--                                   ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
--                                            v.CREATION_TIME DESC NULLS LAST
--                               ) AS rn
                        FROM VW_PN_LAI_LICH_CHI_TIET v
                        WHERE NVL(v.IS_DELETED, 0) = 0
                    ) v_ll ON v_ll.PHAM_NHAN_ID = nmt.NMT_PN_LAI_LICH_ID --AND v_ll.rn = 1
                    INNER JOIN PN_THI_HANH_AN tha ON tha.tha_pnlai_lich_id = nmt.NMT_PN_LAI_LICH_ID
                    INNER JOIN (
                        SELECT LEVEL AS lv FROM dual CONNECT BY LEVEL <= 30
                    ) nums
                        ON nums.lv <= REGEXP_COUNT(
                            REGEXP_REPLACE(NVL(TRIM(CAST(nmt.NMT_HINH_THUC_SD AS VARCHAR2(4000))), ''), '[][]', ''),
                            '\d+'
                        )
                    INNER JOIN DM_HINH_THUC_SU_DUNG_MA_TUIES dm
                        ON dm.ID = TO_NUMBER(
                            TRIM(
                                REGEXP_SUBSTR(
                                    REGEXP_REPLACE(NVL(TRIM(CAST(nmt.NMT_HINH_THUC_SD AS VARCHAR2(4000))), ''), '[][]', ''),
                                    '\d+',
                                    1,
                                    nums.lv
                                )
                            )
                        )
                       AND NVL(dm.IS_DELETED, 0) = 0
                    WHERE NVL(nmt.IS_DELETED, 0) = 0
                      AND NVL(tha.is_deleted, 0) = 0
                      AND tha.tha_pnlai_lich_id IS NOT NULL
                      AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
                     -- AND (p_ma_trai_giam IS NULL OR v_ll.TRAI_GIAM_MA = p_ma_trai_giam)
                      AND (p_ma_trai_giam IS NULL OR ( v_ll.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam))) 
                      AND (p_don_vi_id IS NULL OR v_ll.PHAN_DOI_ID = p_don_vi_id)
                      AND (p_tinh_trang_id IS NULL OR v_ll.LL_TINH_TRANG_ID = p_tinh_trang_id)
                      AND (
                          p_thuong_tru_tinh_id IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM PN_LAI_LICHS pll
                              WHERE pll.ID = nmt.NMT_PN_LAI_LICH_ID
                                AND NVL(pll.IS_DELETED, 0) = 0
                                AND pll.LL_DIA_CHI_THUONG_TRU_PROVICE = p_thuong_tru_tinh_id
                          )
                      )
                      AND (
                          v_tu_ngay IS NULL
                          OR ( tha.tha_ngay_den_trai  >= v_tu_ngay
                          )
                      )
                      AND (
                          v_den_ngay IS NULL
                          OR ( tha.tha_ngay_den_trai  <= v_den_ngay
                          )
                      )
                      AND (
                          v_ra_trai_tu IS NULL
                          OR (
                              tha.tha_ngay_het_han IS NOT NULL
                              AND TRUNC(tha.tha_ngay_het_han) >= v_ra_trai_tu
                          )
                      )
                      AND (
                          v_ra_trai_den IS NULL
                          OR (
                              tha.tha_ngay_het_han IS NOT NULL
                              AND TRUNC(tha.tha_ngay_het_han) <= v_ra_trai_den
                          )
                      )
                      AND (
                          p_chat_ma_tuy_id IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM chat_mt_filter ctf
                              WHERE INSTR(
                                  ',' || REPLACE(REPLACE(REPLACE(NVL(TRIM(CAST(nmt.NMT_CHAT_MA_TUY AS VARCHAR2(4000))), ''), '[', ''), ']', ''), ' ', '') || ',',
                                  ',' || ctf.chat_ma_tuy_id || ','
                              ) > 0
                          )
                      )
                      AND (
                          p_hinh_thuc_sd_id IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM hinh_thuc_sd_filter htf
                              WHERE INSTR(
                                  ',' || REPLACE(REPLACE(REPLACE(NVL(TRIM(CAST(nmt.NMT_HINH_THUC_SD AS VARCHAR2(4000))), ''), '[', ''), ']', ''), ' ', '') || ',',
                                  ',' || htf.hinh_thuc_sd_id || ','
                              ) > 0
                          )
                      )
                      AND (
                          p_so_ngay_sd_tu IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM PN_NGHIEN_MT n2
                              LEFT JOIN DM_MA_THOI_GIANS DMTG ON DMTG.ID = n2.NMT_THOI_HAN_SD
                              WHERE n2.NMT_PN_LAI_LICH_ID = nmt.NMT_PN_LAI_LICH_ID
                                AND NVL(n2.IS_DELETED, 0) = 0
                                AND n2.NMT_THOI_HAN_SD IS NOT NULL
                                AND DMTG.MTG_MA >= (SELECT MTG_MA FROM DM_MA_THOI_GIANS WHERE ID = p_so_ngay_sd_tu)
                          )
                      )
                      AND (
                          p_so_ngay_sd_den IS NULL
                          OR EXISTS (
                              SELECT 1
                              FROM PN_NGHIEN_MT n2
                              LEFT JOIN DM_MA_THOI_GIANS DMTG ON DMTG.ID = n2.NMT_THOI_HAN_SD
                              WHERE n2.NMT_PN_LAI_LICH_ID = nmt.NMT_PN_LAI_LICH_ID
                                AND NVL(n2.IS_DELETED, 0) = 0
                                AND n2.NMT_THOI_HAN_SD IS NOT NULL
                                AND DMTG.MTG_MA <= (SELECT MTG_MA FROM DM_MA_THOI_GIANS WHERE ID = p_so_ngay_sd_den)
                          )
                      )
                      AND REGEXP_LIKE(NVL(TRIM(CAST(nmt.NMT_HINH_THUC_SD AS VARCHAR2(4000))), ''), '\[.*\]')
                      AND REGEXP_SUBSTR(
                          REGEXP_REPLACE(NVL(TRIM(CAST(nmt.NMT_HINH_THUC_SD AS VARCHAR2(4000))), ''), '[][]', ''),
                          '\d+',
                          1,
                          nums.lv
                      ) IS NOT NULL
                ) x
                GROUP BY x.pn_id_lv
            ) ha ON ha.pn_id = d.pn_lai_lich_id
            LEFT JOIN (
                SELECT nmt.NMT_PN_LAI_LICH_ID AS pn_id,
                       DMMTG.MTG_TITLE AS thoi_gian_sd
                FROM PN_NGHIEN_MT nmt
                LEFT JOIN DM_MA_THOI_GIANS DMMTG ON DMMTG.ID = NMT.NMT_THOI_HAN_SD
                INNER JOIN (
                    SELECT v.PHAM_NHAN_ID,
                           v.TRAI_GIAM_MA,
                           v.PHAN_DOI_ID,
                           v.LL_TINH_TRANG_ID,
                           TRAI_GIAM_ID
--                           ROW_NUMBER() OVER (
--                               PARTITION BY v.PHAM_NHAN_ID
--                               ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
--                                        v.CREATION_TIME DESC NULLS LAST
--                           ) AS rn
                    FROM VW_PN_LAI_LICH_CHI_TIET v
                    WHERE NVL(v.IS_DELETED, 0) = 0
                ) v_ll ON v_ll.PHAM_NHAN_ID = nmt.NMT_PN_LAI_LICH_ID --AND v_ll.rn = 1
                INNER JOIN PN_THI_HANH_AN tha ON tha.tha_pnlai_lich_id = nmt.NMT_PN_LAI_LICH_ID
                WHERE NVL(nmt.IS_DELETED, 0) = 0
                  AND NVL(tha.is_deleted, 0) = 0
                  AND tha.tha_pnlai_lich_id IS NOT NULL
                  AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
                 -- AND (p_ma_trai_giam IS NULL OR v_ll.TRAI_GIAM_MA = p_ma_trai_giam)
                AND (p_ma_trai_giam IS NULL OR ( v_ll.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam))) 
                  AND (p_don_vi_id IS NULL OR v_ll.PHAN_DOI_ID = p_don_vi_id)
                  AND (p_tinh_trang_nghien IS NULL OR NMT_TINH_TRANG_NGHIEN = p_tinh_trang_nghien)
                  AND (p_tinh_trang_id IS NULL OR v_ll.LL_TINH_TRANG_ID = p_tinh_trang_id)
                  AND (
                      p_thuong_tru_tinh_id IS NULL
                      OR EXISTS (
                          SELECT 1
                          FROM PN_LAI_LICHS pll
                          WHERE pll.ID = nmt.NMT_PN_LAI_LICH_ID
                            AND NVL(pll.IS_DELETED, 0) = 0
                            AND pll.LL_DIA_CHI_THUONG_TRU_PROVICE = p_thuong_tru_tinh_id
                      )
                  )
                  AND (
                      v_tu_ngay IS NULL
                      OR ( tha.tha_ngay_den_trai  >= v_tu_ngay
                      )
                  )
                  AND (
                      v_den_ngay IS NULL
                      OR ( tha.tha_ngay_den_trai  <= v_den_ngay
                      )
                  )
                  AND (
                      v_ra_trai_tu IS NULL
                      OR ( tha.tha_ngay_het_han  >= v_ra_trai_tu
                      )
                  )
                  AND (
                      v_ra_trai_den IS NULL
                      OR (
                          tha.tha_ngay_het_han IS NOT NULL
                          AND TRUNC(tha.tha_ngay_het_han) <= v_ra_trai_den
                      )
                  )
                  AND (
                      p_chat_ma_tuy_id IS NULL
                      OR EXISTS (
                          SELECT 1
                          FROM chat_mt_filter ctf
                          WHERE INSTR(
                              ',' || REPLACE(REPLACE(REPLACE(NVL(TRIM(CAST(nmt.NMT_CHAT_MA_TUY AS VARCHAR2(4000))), ''), '[', ''), ']', ''), ' ', '') || ',',
                              ',' || ctf.chat_ma_tuy_id || ','
                          ) > 0
                      )
                  )
                  AND (
                      p_hinh_thuc_sd_id IS NULL
                      OR EXISTS (
                          SELECT 1
                          FROM hinh_thuc_sd_filter htf
                          WHERE INSTR(
                              ',' || REPLACE(REPLACE(REPLACE(NVL(TRIM(CAST(nmt.NMT_HINH_THUC_SD AS VARCHAR2(4000))), ''), '[', ''), ']', ''), ' ', '') || ',',
                              ',' || htf.hinh_thuc_sd_id || ','
                          ) > 0
                      )
                  )
                  AND (
                      p_so_ngay_sd_tu IS NULL
                      OR EXISTS (
                          SELECT 1
                          FROM PN_NGHIEN_MT n2
                          LEFT JOIN DM_MA_THOI_GIANS DMTG ON DMTG.ID = n2.NMT_THOI_HAN_SD
                          WHERE n2.NMT_PN_LAI_LICH_ID = nmt.NMT_PN_LAI_LICH_ID
                            AND NVL(n2.IS_DELETED, 0) = 0
                            AND n2.NMT_THOI_HAN_SD IS NOT NULL
                            AND DMTG.MTG_MA >= (SELECT MTG_MA FROM DM_MA_THOI_GIANS WHERE ID = p_so_ngay_sd_tu)
                      )
                  )
                  AND (
                      p_so_ngay_sd_den IS NULL
                      OR EXISTS (
                          SELECT 1
                          FROM PN_NGHIEN_MT n2
                          LEFT JOIN DM_MA_THOI_GIANS DMTG ON DMTG.ID = n2.NMT_THOI_HAN_SD
                          WHERE n2.NMT_PN_LAI_LICH_ID = nmt.NMT_PN_LAI_LICH_ID
                            AND NVL(n2.IS_DELETED, 0) = 0
                            AND n2.NMT_THOI_HAN_SD IS NOT NULL
                            AND DMTG.MTG_MA <= (SELECT MTG_MA FROM DM_MA_THOI_GIANS WHERE ID = p_so_ngay_sd_den)
                      )
                  )
                  AND nmt.NMT_THOI_HAN_SD IS NOT NULL
            ) ta ON ta.pn_id = d.pn_lai_lich_id
            LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn
                ON v.LL_TINH_TRANG_ID = dmttpn.ID AND NVL(dmttpn.IS_DELETED, 0) = 0
        ) q
    ) z
    WHERE z.STT > v_skip
      AND (v_limit = 0 OR z.STT <= v_skip + v_limit)
    ORDER BY z.STT;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L?i khi l?y danh sách ph?m nhân nghi?n ma túy: ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_PHAM_NHAN_NGHIEN_MA_TUY;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PHAM_NHAN_PHAM_TOI_MOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PHAM_NHAN_PHAM_TOI_MOI" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id  IN  NUMBER    DEFAULT NULL,   
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT 0      
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_tu_ngay   DATE;
    v_den_ngay  DATE;
    c1          SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
    WITH
    -- M?t LL m?i nh?t m?i PN (tránh dup t? VW_PN_LAI_LICH_CHI_TIET)
    LL_one AS (
        SELECT * FROM (
            SELECT v.* 
            FROM VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
        ) x  
    )
    SELECT * FROM (
    SELECT
        --ROW_NUMBER() OVER (ORDER BY ptm.NGAY_PHAM_TOI NULLS LAST,v.HO_TEN) AS rn_all,
        ROW_NUMBER() OVER (ORDER BY   ORDER_HOTEN(v.HO_TEN) NULLS LAST) AS rn_all,
        COUNT(*) OVER() AS total_count,
        v.SO_HO_SO                    AS SO_HSLD,
        v.CCCD,
        v.HO_TEN                      AS HO_TEN,
        v.NGAY_SINH                   AS NS,
        v.GIOI_TINH                   AS GT,
        v.NOI_THUONG_TRU_DAY_DU       AS DKTT,
        v.TOI_DANH                    AS TOI_DANH,
        --v.NGAY_BAT_AN_PHAT            AS NGAY_BAT,
        TO_CHAR(v.NGAY_BAT_AN_PHAT , 'DD/mm/yyyy') AS NGAY_BAT,
        v.AN_PHAT                     AS AN_PHAT,
        --v.NGAY_DEN_TRAI               AS NGAY_DEN_TRAI,
        TO_CHAR(v.NGAY_DEN_TRAI , 'DD/mm/yyyy') AS NGAY_DEN_TRAI,
        --v.NGAY_HET_AN                 AS NGAY_HET_HAN,
        TO_CHAR(v.NGAY_HET_AN , 'DD/mm/yyyy') AS NGAY_HET_HAN,
        --ptm.NGAY_PHAM_TOI             AS NGAY_PHAM,
        TO_CHAR(ptm.NGAY_PHAM_TOI , 'DD/mm/yyyy') AS NGAY_PHAM,
        -- T?i danh m?i: ?u tiên DM_TOI_DANHS.TD_TEN, fallback ptm.DM_TOI_DANH
        NVL(TRIM(CAST(dmtd.TD_TEN AS NVARCHAR2(2000))),
            NVL(TRIM(CAST(ptm.DM_TOI_DANH AS NVARCHAR2(2000))), u'')) AS TOI_DANH_MOI,
        NVL(TRIM(CAST(ptm.HINH_THUC_XU_LY AS NVARCHAR2(500))), u'') AS HINH_THUC_XU_LY,
        dmttpn.TTPN_TEN               AS TINH_TRANG,
        -- PHAN_DOI: phân ??i, phân tr?i
        NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), u'') ||
        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
        NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), u'') AS PHAN_DOI
    FROM PHAM_TOI_MOIS ptm
    INNER JOIN LL_one v ON v.PHAM_NHAN_ID = ptm.PHAM_NHAN_ID
    --LEFT JOIN DM_TOI_DANHS dmtd
        --ON ptm.TOI_DANH_ID = dmtd.ID AND NVL(dmtd.IS_DELETED, 0) = 0
       LEFT JOIN DM_TOI_DANHS dmtd
    ON TO_NUMBER(
           SUBSTR(
               TRIM(ptm.DM_TOI_DANH),
               1,
               INSTR(TRIM(ptm.DM_TOI_DANH) || ',', ',') - 1
           )
       ) = dmtd.ID
   AND NVL(dmtd.IS_DELETED, 0) = 0

    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn
        ON v.LL_TINH_TRANG_ID = dmttpn.ID AND NVL(dmttpn.IS_DELETED, 0) = 0
    WHERE NVL(ptm.IS_DELETED, 0) = 0
      --AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_MA = p_ma_trai_giam)
      AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
      AND (v_tu_ngay IS NULL OR (ptm.NGAY_PHAM_TOI IS NOT NULL AND  ptm.NGAY_PHAM_TOI  >=  v_tu_ngay ))
      AND (v_den_ngay IS NULL OR (ptm.NGAY_PHAM_TOI IS NOT NULL AND  ptm.NGAY_PHAM_TOI  <=  v_den_ngay ))
    AND (p_tinh_trang_id IS NULL OR dmttpn.ID  = p_tinh_trang_id)
    AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)      
    --ORDER BY ptm.NGAY_PHAM_TOI DESC NULLS LAST, v.HO_TEN
    )
    WHERE  rn_all > v_skip
      AND (v_limit = 0 OR rn_all <= v_skip + v_limit)
    ORDER BY rn_all     
    ;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân ph?m t?i m?i: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_PHAM_NHAN_PHAM_TOI_MOI;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PHAM_NHAN_TAI_PHAM
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PHAM_NHAN_TAI_PHAM" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id  IN  NUMBER    DEFAULT NULL,
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT 0      
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_den_ngay DATE;
    v_tu_ngay  DATE;
    c1         SYS_REFCURSOR;
BEGIN

    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
--    WITH
--    -- PN ?ang ch?p hành án t?i ngày v_den_ngay: có THA hi?u l?c
--    tha_hieu_luc AS (
--        SELECT tha.tha_pnlai_lich_id AS pn_id
--        FROM PN_THI_HANH_AN tha
--        WHERE NVL(tha.is_deleted, 0) = 0
--          AND tha.tha_pnlai_lich_id IS NOT NULL
--          AND trunc(THA_NGAY_DEN_TRAI) <= trunc(v_tu_ngay)
--          AND trunc(THA_NGAY_DEN_TRAI) >= trunc(v_den_ngay)
--    ),
--    tha_den_trai AS (
--        SELECT tha.tha_pnlai_lich_id AS pn_id,
--               tha.tha_ngay_den_trai AS ngay_den_trai,
--               ROW_NUMBER() OVER (PARTITION BY tha.tha_pnlai_lich_id ORDER BY tha.tha_ngay_den_trai DESC NULLS LAST) AS rn
--        FROM PN_THI_HANH_AN tha
--        WHERE NVL(tha.is_deleted, 0) = 0
--          AND tha.tha_pnlai_lich_id IN (SELECT pn_id FROM tha_hieu_luc)
--    ),
--    -- M?t LL m?i nh?t m?i PN (tránh dup t? VW_PN_LAI_LICH_CHI_TIET)
--    LL_one AS (
--        SELECT * FROM (
--            SELECT v.*, ROW_NUMBER() OVER (PARTITION BY v.PHAM_NHAN_ID
--                ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
--                         v.CREATION_TIME DESC NULLS LAST) AS rn
--            FROM VW_PN_LAI_LICH_CHI_TIET v
--            WHERE NVL(v.IS_DELETED, 0) = 0
--        ) x WHERE rn = 1
--    ),
--    -- PN ?ang ch?p hành án + có tái ph?m (LL_TAI_PHAM IS NOT NULL)
--    dang_chap_hanh_co_tai_pham AS (
--        SELECT ll.PHAM_NHAN_ID AS pn_lai_lich_id
--        FROM LL_one ll
--        INNER JOIN tha_hieu_luc t ON t.pn_id = ll.PHAM_NHAN_ID
--        LEFT JOIN tha_den_trai td ON td.pn_id = ll.PHAM_NHAN_ID AND td.rn = 1
--        WHERE  1 =1
--        AND (p_ma_trai_giam IS NULL OR ll.TRAI_GIAM_MA = p_ma_trai_giam)
--          AND (v_tu_ngay IS NULL OR (td.ngay_den_trai IS NOT NULL AND TRUNC(td.ngay_den_trai) >= v_tu_ngay))
----          AND ll.TAI_PHAM IS NOT NULL
----          and ll.TAI_PHAM not in ('Không tái ph?m')
--        AND ll.TAI_PHAM <> 'Không tái ph?m'
--    )
    SELECT * FROM (
    SELECT
        --ROW_NUMBER() OVER (ORDER BY v.HO_TEN NULLS LAST) AS rn_all,
       -- ROW_NUMBER() OVER (ORDER BY   ORDER_HOTEN(v.HO_TEN) NULLS LAST) AS rn_all,
        COUNT(*) OVER() AS total_count,    
        v.SO_HO_SO                    AS SO_HSLD,
        v.CCCD as CCCD,
        v.HO_TEN                       AS HO_TEN,
        v.NGAY_SINH                    AS NS,
        v.GIOI_TINH                    AS GT,
        v.NOI_THUONG_TRU_DAY_DU        AS DKTT,
        v.TOI_DANH                     AS TOI_DANH,
        --v.NGAY_BAT_AN_PHAT             AS NGAY_BAT,
        TO_CHAR(v.NGAY_BAT_AN_PHAT , 'DD/mm/yyyy') AS NGAY_BAT,
        v.AN_PHAT                      AS AN_PHAT,
        --v.NGAY_DEN_TRAI                AS NGAY_DEN_TRAI,
        TO_CHAR(v.NGAY_DEN_TRAI , 'DD/mm/yyyy') AS NGAY_DEN_TRAI,
        --v.NGAY_HET_AN                  AS NGAY_HET_HAN,
        TO_CHAR(v.NGAY_HET_AN , 'DD/mm/yyyy') AS NGAY_HET_AN,

        NVL(TRIM(CAST(v.TAI_PHAM AS NVARCHAR2(2000))), u'') AS TAI_PHAM,
        -- Th?i gian ?ã gi?m, ?ã ch?p hành, còn l?i: dùng PKG_TINH_AN
--        CASE
--            WHEN NULLIF(TRIM(CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(v.PHAM_NHAN_ID) AS VARCHAR2(100))), '0') IS NULL
--            THEN u'Kh\00f4ng'
--            ELSE CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(v.PHAM_NHAN_ID) AS NVARCHAR2(2000))
--        END                            AS THOI_GIAN_DA_GIAM,
        CASE
            WHEN v.THOI_GIAN_DA_GIAM is null or v.THOI_GIAN_DA_GIAM = 0   
            THEN u'Kh\00f4ng'
            ELSE v.THOI_GIAN_DA_GIAM
        END                            AS THOI_GIAN_DA_GIAM,        
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(v.PHAM_NHAN_ID), u'') AS THOI_GIAN_DA_CHAP_HANH,
         --THOI_GIAN_DA_CHAP_HANH
        --NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(v.PHAM_NHAN_ID), u'') AS THOI_GIAN_CON_LAI,
         THOI_GIAN_CON_LAI,
        dmttpn.TTPN_TEN                AS TINH_TRANG,
        -- PHAN_DOI: phân ??i, phân tr?i
        NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), u'') ||
        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
        NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), u'') AS PHAN_DOI
    FROM  VW_PN_LAI_LICH_CHI_TIET v 
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn
        ON v.LL_TINH_TRANG_ID = dmttpn.ID
       AND NVL(dmttpn.IS_DELETED, 0) = 0
    WHERE 1 =1
          AND v.TAI_PHAM IS NOT NULL
          and v.TAI_PHAM not in ('Không tái ph?m')
    AND (p_tinh_trang_id IS NULL OR dmttpn.ID  = p_tinh_trang_id)
    AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)       
	  AND (v_tu_ngay IS NULL OR NGAY_DEN_TRAI >= v_tu_ngay )
	  AND (v_den_ngay IS NULL OR NGAY_DEN_TRAI <= v_den_ngay) 
    AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
    --ORDER BY v.HO_TEN
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
    )  ;    

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân tái ph?m: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_PHAM_NHAN_TAI_PHAM;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PHAM_NHAN_TAM_DINH_CHI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PHAM_NHAN_TAM_DINH_CHI" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY
    p_ngay_lai_tu_ngay     IN  VARCHAR2  DEFAULT NULL,
    p_ngay_lai_den_ngay     IN  VARCHAR2  DEFAULT NULL,
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id IN  NUMBER    DEFAULT NULL,
    p_loai_quyet_dinh_id IN  NUMBER    DEFAULT NULL,
    p_ds_in IN  NUMBER    DEFAULT 1,
    p_maxresultcount IN  NUMBER    DEFAULT 25,
    p_skipcount      IN  NUMBER    DEFAULT 0      
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_tu_ngay   DATE;
    v_den_ngay  DATE;
    v_ngay_lai_tu_ngay   DATE;
    v_ngay_lai_den_ngay  DATE;    
    c1          SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_ngay_lai_tu_ngay IS NULL OR TRIM(p_ngay_lai_tu_ngay) = '' THEN
        v_ngay_lai_tu_ngay := NULL;
    ELSE
        v_ngay_lai_tu_ngay := TO_DATE(TRIM(p_ngay_lai_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_ngay_lai_den_ngay IS NULL OR TRIM(p_ngay_lai_den_ngay) = '' THEN
        v_ngay_lai_den_ngay := NULL;
    ELSE
        v_ngay_lai_den_ngay := TO_DATE(TRIM(p_ngay_lai_den_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
    WITH
    -- PN có t?m ?ình ch? trong kho?ng ngày
--    tdc_pn AS (
--        SELECT DISTINCT td.PHAM_NHAN_ID
--        FROM TAM_DINH_CHIS td
--        INNER JOIN VW_PN_LAI_LICH_CHI_TIET v ON v.PHAM_NHAN_ID = td.PHAM_NHAN_ID AND NVL(v.IS_DELETED, 0) = 0
--        WHERE NVL(td.IS_DELETED, 0) = 0
--          --AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_MA = p_ma_trai_giam)
--          AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
--          AND (v_tu_ngay IS NULL OR (td.TU_NGAY IS NOT NULL AND td.TU_NGAY >= v_tu_ngay))
--          AND (v_den_ngay IS NULL OR (td.TU_NGAY IS NOT NULL AND td.TU_NGAY <= v_den_ngay))
--          AND (v_ngay_lai_tu_ngay IS NULL OR (td.NGAY_LAI IS NOT NULL AND td.NGAY_LAI >= v_ngay_lai_tu_ngay))
--          AND (v_ngay_lai_den_ngay IS NULL OR (td.NGAY_LAI IS NOT NULL AND td.NGAY_LAI <= v_ngay_lai_den_ngay))          
--    ),
    -- M?t LL m?i nh?t m?i PN (tránh dup t? VW_PN_LAI_LICH_CHI_TIET)
    LL_one AS (
        SELECT * FROM (
            SELECT v.* 
            FROM VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
            AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
        ) x  
    )
    SELECT * FROM (
    SELECT
       -- ROW_NUMBER() OVER (ORDER BY td.TU_NGAY DESC NULLS LAST, v.HO_TEN) AS rn_all,
        --ROW_NUMBER() OVER (ORDER BY   ORDER_HOTEN(v.HO_TEN) NULLS LAST) AS rn_all,
        COUNT(*) OVER() AS total_count,  
        SO_HO_SO,
        NVL(TRIM(CAST(v.HO_TEN AS NVARCHAR2(2000))), u'') AS HO_TEN,
        v.NAM_SINH,
        --v.NGAY_SINH,
        v.NGAY_SINH,
        --TO_CHAR(v.NGAY_SINH , 'DD/mm/yyyy') AS NGAY_SINH,
        GIOI_TINH,
        NVL(TRIM(CAST(v.NOI_THUONG_TRU_DAY_DU AS NVARCHAR2(2000))), u'') AS DIA_CHI_THUONG_TRU,
        NVL(TRIM(CAST(v.TOI_DANH AS NVARCHAR2(2000))), u'') AS TOI_DANH,
        SO_TIEN_AN AS SO_TA,
        -- NGÀY B?T, ÁN PH?T: 2 c?t riêng
        --.NGAY_BAT_AN_PHAT AS NGAY_BAT,
        TO_CHAR(NGAY_BAT_AN_PHAT , 'DD/mm/yyyy') AS NGAY_BAT,
        v.AN_PHAT AS AN_PHAT,
        --td.NGAY_TDC,
        TO_CHAR(td.NGAY_TDC , 'DD/mm/yyyy') AS NGAY_TDC,
        TTP.TTP_TEN AS NOI_VE,
        -- NGÀY VÀO TR?I, PHÂN ??I: 2 c?t riêng
        --v.NGAY_DEN_TRAI AS NGAY_VAO_TRAI,
        TO_CHAR(v.NGAY_DEN_TRAI , 'DD/mm/yyyy') AS NGAY_VAO_TRAI,
        --v.NGAY_HET_AN NGAY_HET_HAN, 
        TO_CHAR(v.NGAY_HET_AN , 'DD/mm/yyyy') AS NGAY_HET_HAN,

        NVL(TRIM(CAST(v.PHAN_DOI AS NVARCHAR2(200))), u'') ||
        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
        NVL(TRIM(CAST(v.PHAN_TRAI AS NVARCHAR2(200))), u'') AS PHAN_DOI,
        -- S? Q?, NGÀY Q?: 2 c?t riêng
        NVL(TRIM(CAST(td.SO_QUYET_DINH AS NVARCHAR2(255))), u'') AS SO_QD,
        --td.NGAY_QUYET_DINH AS NGAY_QD,
        TO_CHAR(td.NGAY_QUYET_DINH , 'DD/mm/yyyy') AS NGAY_QD,
        -- T? NGÀY, TH?I H?N: 2 c?t riêng
        --td.TU_NGAY AS TU_NGAY,
        TO_CHAR(td.TU_NGAY , 'DD/mm/yyyy') AS TU_NGAY,
        NVL(TRIM(CAST(mtg.MTG_TITLE AS NVARCHAR2(200))), u'') AS THOI_HAN,

--        DBT.BT_TEN BENH_TAT,
--        CBBB.NGAY_KET_THUC,
--        CBBB.NGAY_BAT_DAU,
         '' BENH_TAT,
         '' NGAY_KET_THUC,
         '' NGAY_BAT_DAU,        
        -- LÝ DO T?C: ?u tiên DM, fallback ly_do_chi_tiet
        NVL(TRIM(CAST(ldtdc.LDTDC_TEN AS NVARCHAR2(500))), NVL(TRIM(CAST(td.LY_DO_CHI_TIET AS NVARCHAR2(1000))), u'')) AS LY_DO_TDC,
        -- NGÀY L?I, TÌNH TR?NG: 2 c?t riêng (ngày l?i tình tr?ng)
        --td.NGAY_LAI AS NGAY_LAI,
        TO_CHAR(td.NGAY_LAI , 'DD/mm/yyyy') AS NGAY_LAI,
        NVL(TRIM(CAST(tttdc.TTTDC_TEN AS NVARCHAR2(200))), u'') AS TINH_TRANG_TDC,
        -- GHI CHÚ
        NVL(TRIM(CAST(td.NHAN_XET AS NVARCHAR2(1000))), u'') AS GHI_CHU
    FROM TAM_DINH_CHIS td
    INNER JOIN LL_one v ON v.PHAM_NHAN_ID = td.PHAM_NHAN_ID
--    LEFT JOIN CHUA_BENH_BAT_BUOCS CBBB ON V.PHAM_NHAN_ID = CBBB.PHAM_NHAN_ID
--    LEFT JOIN DM_BENH_TATS DBT ON CBBB.BENH_TAT_ID = DBT.ID
    LEFT JOIN DM_MA_THOI_GIANS mtg
        ON td.THOI_HAN_ID = mtg.ID AND NVL(mtg.IS_DELETED, 0) = 0
    LEFT JOIN DM_LY_DO_TAM_DINH_CHIES ldtdc
        ON td.LY_DO_SUC_KHOE_ID = ldtdc.ID AND NVL(ldtdc.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_TRANG_TAM_DINH_CHIES tttdc
        ON td.TINH_TRANG_ID = tttdc.ID AND NVL(tttdc.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_THANH_PHO TTP ON TTP.ID = TD.NOI_VE_DIA_PHUONG_ID
    WHERE td.IS_DELETED = 0
          AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
      AND (v_tu_ngay IS NULL OR (td.TU_NGAY IS NOT NULL AND td.TU_NGAY >= v_tu_ngay))
      AND (v_den_ngay IS NULL OR (td.TU_NGAY IS NOT NULL AND td.TU_NGAY <= v_den_ngay))
      AND (v_ngay_lai_tu_ngay IS NULL OR (td.NGAY_LAI IS NOT NULL AND td.NGAY_LAI >= v_ngay_lai_tu_ngay))
      AND (v_ngay_lai_den_ngay IS NULL OR (td.NGAY_LAI IS NOT NULL AND td.NGAY_LAI <= v_ngay_lai_den_ngay))       
      AND (p_tinh_trang_id IS NULL OR tttdc.ID = p_tinh_trang_id)
      AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)
      AND (p_loai_quyet_dinh_id IS NULL OR td.LOAI_QUYET_DINH_ID = p_loai_quyet_dinh_id)
    --ORDER BY td.TU_NGAY DESC NULLS LAST, v.HO_TEN
    ORDER BY HO_TEN_ORDER
      OFFSET p_skipcount ROWS
      FETCH NEXT p_maxresultcount ROWS ONLY
    )  ; 

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân t?m ?ình ch?: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_PHAM_NHAN_TAM_DINH_CHI;



