--  DDL for Procedure SP_GET_BAO_CAO_DS_PHAM_NHAN_TANG_GIAM_HP
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PHAM_NHAN_TANG_GIAM_HP" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id IN  NUMBER    DEFAULT NULL,
    p_maxresultcount IN  NUMBER    DEFAULT 25,
    p_skipcount      IN  NUMBER    DEFAULT 0       
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_tu_ngay   DATE;
    v_den_ngay  DATE;
    c1          SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
    WITH
    -- PN có t?ng/gi?m HP trong kho?ng ngày
    tg_pn AS (
        SELECT DISTINCT tg.PHAM_NHAN_ID
        FROM TANG_GIAM_HINH_PHATS tg
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET v ON v.PHAM_NHAN_ID = tg.PHAM_NHAN_ID AND NVL(v.IS_DELETED, 0) = 0
        WHERE NVL(tg.IS_DELETED, 0) = 0
          --AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_MA = p_ma_trai_giam)
          AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))         
          AND (v_tu_ngay IS NULL OR (tg.NGAY_QUYET_DINH IS NOT NULL AND  tg.NGAY_QUYET_DINH  >=   v_tu_ngay)) 
          AND (v_den_ngay IS NULL OR (tg.NGAY_QUYET_DINH IS NOT NULL AND  tg.NGAY_QUYET_DINH  <=   v_den_ngay)) 
    ),
    -- M?t LL m?i nh?t m?i PN (tránh dup t? VW_PN_LAI_LICH_CHI_TIET)
    LL_one AS (
        SELECT * FROM (
            SELECT v.* 
            FROM VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
        ) x  
    )
    SELECT * FROM (
    SELECT
        --ROW_NUMBER() OVER (ORDER BY tg.NGAY_QUYET_DINH DESC NULLS LAST, v.HO_TEN) AS rn_all,
         COUNT(*) OVER() AS total_count,     
        v.SO_HO_SO                    AS SO_HSLD,
        NVL(TRIM(CAST(v.HO_TEN AS NVARCHAR2(2000))), u'') AS HO_TEN,
        v.NGAY_SINH                   AS NGAY_SINH,
        NVL(TRIM(CAST(v.GIOI_TINH AS NVARCHAR2(100))), u'') AS GIOI_TINH,
        NVL(TRIM(CAST(v.NOI_THUONG_TRU_DAY_DU AS NVARCHAR2(2000))), u'') AS DKTT,
        NVL(TRIM(CAST(v.TOI_DANH AS NVARCHAR2(2000))), u'') AS TOI_DANH,
        --v.NGAY_BAT_AN_PHAT            AS NGAY_BAT,
        TO_CHAR(v.NGAY_BAT_AN_PHAT , 'DD/mm/yyyy') AS NGAY_BAT,
        v.AN_PHAT                     AS AN_PHAT,
        --v.NGAY_DEN_TRAI               AS NGAY_DEN_TRAI,
        TO_CHAR(v.NGAY_DEN_TRAI , 'DD/mm/yyyy') AS NGAY_DEN_TRAI,
        --v.NGAY_HET_AN                 AS NGAY_HET_HAN,
        TO_CHAR(v.NGAY_HET_AN , 'DD/mm/yyyy') AS NGAY_HET_HAN,
        NVL(TRIM(CAST(tg.SO_QUYET_DINH AS NVARCHAR2(255))), u'') AS SO_QD,
        --tg.NGAY_QUYET_DINH            AS NGAY_QD,
        TO_CHAR(tg.NGAY_QUYET_DINH , 'DD/mm/yyyy') AS NGAY_QD,
        -- Tòa Q?: ?u tiên DM_CO_QUANS, fallback DM_DON_VI_HANH_CHINH
        NVL(TRIM(CAST(cq.CQ_TEN AS NVARCHAR2(500))), NVL(TRIM(CAST(dvhc.TTP_Ten AS NVARCHAR2(500))), u'')) AS TOA_QD,
        NVL(TRIM(CAST(mtg.MTG_TITLE AS NVARCHAR2(200))), u'') AS THOI_HAN,
        NVL(TRIM(CAST(dmttpn.TTPN_TEN AS NVARCHAR2(200))), u'') AS TINH_TRANG,
        NVL(TRIM(CAST(v.PHAN_DOI AS NVARCHAR2(200))), u'') ||
        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
        NVL(TRIM(CAST(v.PHAN_TRAI AS NVARCHAR2(200))), u'') AS PHAN_DOI
    FROM TANG_GIAM_HINH_PHATS tg
    INNER JOIN LL_one v ON v.PHAM_NHAN_ID = tg.PHAM_NHAN_ID
    LEFT JOIN DM_CO_QUANS cq
        ON tg.DON_VI_QUYET_DINH_ID = cq.ID AND NVL(cq.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_THANH_PHO dvhc
        ON tg.DIA_PHUONG_QUYET_DINH_ID = dvhc.ID AND NVL(dvhc.IS_DELETED, 0) = 0
    LEFT JOIN DM_MA_THOI_GIANS mtg
        ON tg.THOI_HAN_ID = mtg.ID AND NVL(mtg.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn
        ON v.LL_TINH_TRANG_ID = dmttpn.ID AND NVL(dmttpn.IS_DELETED, 0) = 0
    WHERE NVL(tg.IS_DELETED, 0) = 0
          -- AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_MA = p_ma_trai_giam)
       AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))    
        AND (v_tu_ngay IS NULL OR (tg.NGAY_QUYET_DINH IS NOT NULL AND   tg.NGAY_QUYET_DINH  >=  v_tu_ngay)) 
        AND (v_den_ngay IS NULL OR (tg.NGAY_QUYET_DINH IS NOT NULL AND  tg.NGAY_QUYET_DINH  <=  v_den_ngay)) 
        AND (p_tinh_trang_id IS NULL OR dmttpn.ID = p_tinh_trang_id)
        AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)
    --ORDER BY tg.NGAY_QUYET_DINH DESC NULLS LAST, v.HO_TEN
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
    ) ;     

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân t?ng/gi?m hình ph?t: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_PHAM_NHAN_TANG_GIAM_HP;



