WITH 
PN_LAI_LICHS_TG AS (
select * from PN_LAI_LICH_CHI_TIET_RT where 
(p_ma_trai_giam IS NULL OR LL_TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam))      
 )
    select * from (
