                WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                            THEN u', ' || dxp_thuong_tru.XP_TEN
                        ELSE dxp_thuong_tru.XP_TEN
                    END
                ELSE u''
               END
            || CASE
                WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                            THEN u', ' || dttp_thuong_tru.TTP_TEN
                        ELSE dttp_thuong_tru.TTP_TEN
                    END
                ELSE u''
               END
        )
        ELSE NULL
    END AS NOI_DKTT,  
    THA_TOI_DANH_NAMES AS TOI_DANH,
    --td.THA_NGAY_BAT AS NGAY_BAT,
    TO_CHAR(THA_NGAY_BAT,        'DD/MM/YYYY') AS NGAY_BAT,
    THA_AN_PHAT AS AN_PHAT,  
    --td.THA_NGAY_DEN_TRAI AS NGAY_DEN_TRAI,
    TO_CHAR(THA_NGAY_DEN_TRAI,        'DD/MM/YYYY') AS NGAY_DEN_TRAI,
    --td.THA_NGAY_HET_HAN  AS NGAY_HET_HAN,
    TO_CHAR(THA_NGAY_HET_HAN,        'DD/MM/YYYY') AS NGAY_HET_HAN,

        NNC.NNC_TEN AS BENH_TAT,
--        CASE
--            WHEN NULLIF(TRIM(CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(ll.ID) AS VARCHAR2(2000))), '0') IS NULL
--            THEN u'Kh\00f4ng'
--            ELSE CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(ll.ID) AS NVARCHAR2(2000))
--        END                            AS THOI_GIAN_DA_GIAM,
        --PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(ll.ID) AS THOI_GIAN_DA_GIAM,
        --THA_THOI_GIAN_DA_GIAM,

        CASE
            WHEN THOI_GIAN_DA_GIAM = '0'
            THEN u'Kh\00f4ng'
            ELSE THOI_GIAN_DA_GIAM
        END                            AS THOI_GIAN_DA_GIAM,
         --THOI_GIAN_DA_GIAM THOI_GIAN_DA_GIAM,
            mtgch.MTG_TITLE AS THOI_GIAN_DA_CHAP_HANH,
            mtgcl.MTG_TITLE AS THOI_GIAN_CON_LAI,        

--        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(ll.ID), u'') AS THOI_GIAN_DA_CHAP_HANH,
--        
--        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(ll.ID), u'') AS THOI_GIAN_CON_LAI,
        dmttpn.TTPN_TEN                AS TINH_TRANG,
        -- PHAN_DOI: phân ??i, phân tr?i
        NVL(TRIM(CAST(pd.PD_TEN  AS VARCHAR2(4000))), '') ||
        CASE WHEN pd.PD_TEN  IS NOT NULL AND pt.PT_TEN IS NOT NULL THEN u', ' ELSE u'' END ||
        NVL(TRIM(CAST(pt.PT_TEN AS VARCHAR2(4000))), '') AS PHAN_DOI
    FROM 
--    cbbb_one c
--    LEFT JOIN DM_BENH_TATS DBT ON DBT.ID = C.BENH_TAT_ID
    -- VW_PN_LAI_LICH_CHI_TIET v
     PN_LAI_LICHS_TG ll
        --ON v.PHAM_NHAN_ID = c.PHAM_NHAN_ID
       --AND NVL(v.IS_DELETED, 0) = 0
    --left JOIN PN_THI_HANH_AN tha on v.PHAM_NHAN_ID = tha.THA_PNLAI_LICH_ID 
    --INNER JOIN PN_THI_HANH_AN tha on LL.ID = tha.THA_PNLAI_LICH_ID    and tha.IS_DELETED = 0

    left join DM_MA_THOI_GIANS mtgch on mtgch.MTG_MA = THA_THOI_GIAN_DA_CHAP_HANH    and mtgch.IS_DELETED = 0
    left join DM_MA_THOI_GIANS mtgcl on mtgcl.MTG_MA = THA_THOI_GIAN_CON_LAI    and mtgcl.IS_DELETED = 0
    --left join DM_MA_THOI_GIANS mtgdg on mtgdg.MTG_MA = THA_THOI_GIAN_DA_GIAM    and mtgdg.IS_DELETED = 0

    LEFT JOIN DM_PHAN_TRAIS pt
    ON ll.ll_phan_trai_id = pt.ID
    AND pt.IS_DELETED = 0
    LEFT JOIN DM_PHAN_DOIS pd
    ON ll.ll_phan_doi_id = pd.ID
    AND pd.IS_DELETED = 0
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru 
    ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID 
    AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru 
    ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID 
    AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
--    LEFT JOIN V_PN_THI_HANH_AN_TOI_DANH td 
--    ON ll.ID = td.THA_PNLAI_LICH_ID 
    left join DM_NGUYEN_NHAN_CHETS nnc on nnc.id =  LL.LL_BENH_TAT_VAO_ID
    --LEFT JOIN gcr_agg ga ON ga.PHAM_NHAN_ID = c.PHAM_NHAN_ID
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn
        ON LL.LL_TINH_TRANG_ID = dmttpn.ID
       AND NVL(dmttpn.IS_DELETED, 0) = 0
    LEFT JOIN DM_TRAI_GIAMS traigiam 
    ON ll.LL_TRAI_GIAM_ID = traigiam.ID 
    AND traigiam.IS_DELETED = 0   
    LEFT JOIN DM_GIOI_TINHS gt 
    ON ll.LL_DM_GIOI_TINH_ID = gt.ID 
    AND gt.IS_DELETED = 0
    WHERE 1=1 --c.rn = 1
    and ll.IS_DELETED = 0
    and LL_BENH_TAT_VAO_ID is not null
--        AND (v_tu_ngay IS NULL OR TRUNC(td.THA_NGAY_BAT) >= TRUNC(v_tu_ngay))
--        AND (v_den_ngay IS NULL OR TRUNC(td.THA_NGAY_BAT) <= TRUNC(v_den_ngay))
--AND (v_tu_ngay IS NULL OR td.THA_NGAY_DEN_TRAI >= TRUNC(v_tu_ngay))
--AND (v_den_ngay IS NULL OR td.THA_NGAY_DEN_TRAI < TRUNC(v_den_ngay) + 1)
        AND (v_tu_ngay IS NULL OR  THA_NGAY_DEN_TRAI >= v_tu_ngay)
        AND (v_den_ngay IS NULL OR  THA_NGAY_DEN_TRAI <= v_den_ngay)        
     -- AND (p_ma_trai_giam IS NULL OR traigiam.TG_MA = p_ma_trai_giam)
      --AND (p_ma_trai_giam IS NULL OR LL_TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam))      
      AND (p_tinh_trang_id is null or dmttpn.ID =  p_tinh_trang_id)
      AND (p_phan_doi_id is null or LL.LL_PHAN_DOI_ID = p_phan_doi_id)
      --and tha.IS_DELETED         = 0
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
    )
--    WHERE  rn_all > v_skip
--      AND (v_limit = 0 OR rn_all <= v_skip + v_limit)
--    ORDER BY rn_all    
    ;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân tình tr?ng b?nh t?t: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_PHAM_NHAN_TINH_TRANG_BENH_TAT;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PHAM_NHAN_TINH_TRANG_BENH_TAT_RT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PHAM_NHAN_TINH_TRANG_BENH_TAT_RT" (
    p_ma_trai_giam     IN NVARCHAR2 DEFAULT NULL,
    p_tinh_trang_id    IN NUMBER DEFAULT NULL,
    p_phan_doi_id      IN NUMBER DEFAULT NULL,
    p_tu_ngay          IN VARCHAR2 DEFAULT NULL,
    p_den_ngay         IN VARCHAR2 DEFAULT NULL,
    p_maxresultcount   IN NUMBER DEFAULT NULL,
    p_skipcount        IN NUMBER DEFAULT 0
) AS
    v_skip          NUMBER;
    v_limit         NUMBER;
    v_trai_giam_id  NUMBER;
    v_tu_ngay       DATE;
    v_den_ngay      DATE;
    c1              SYS_REFCURSOR;
BEGIN
    v_skip := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    IF p_ma_trai_giam IS NULL OR p_ma_trai_giam = '' THEN
        v_trai_giam_id := NULL;
    ELSE
        v_trai_giam_id := p_ma_trai_giam;
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
    WITH base_data AS (
        SELECT
            rt.ll_so_ho_so_lan_dau AS so_hsld,
            rt.ll_ho_ten AS ho_ten,
            rt.ll_ngay_sinh AS ns,
            gt.gt_ten AS gt,
            CASE
                WHEN NULLIF(TRIM(rt.ll_dia_chi_thuong_tru), u'') IS NOT NULL
                  OR NULLIF(TRIM(dxp_thuong_tru.xp_ten), u'') IS NOT NULL
                  OR NULLIF(TRIM(dttp_thuong_tru.ttp_ten), u'') IS NOT NULL
                THEN TRIM(
                    NVL(NULLIF(TRIM(rt.ll_dia_chi_thuong_tru), u''), u'')
                    || CASE
                        WHEN NULLIF(TRIM(dxp_thuong_tru.xp_ten), u'') IS NOT NULL THEN
                            CASE
                                WHEN NULLIF(TRIM(rt.ll_dia_chi_thuong_tru), u'') IS NOT NULL
                                THEN u', ' || dxp_thuong_tru.xp_ten
                                ELSE dxp_thuong_tru.xp_ten
                            END
                        ELSE u''
                       END
                    || CASE
                        WHEN NULLIF(TRIM(dttp_thuong_tru.ttp_ten), u'') IS NOT NULL THEN
                            CASE
                                WHEN NULLIF(TRIM(rt.ll_dia_chi_thuong_tru), u'') IS NOT NULL
                                  OR NULLIF(TRIM(dxp_thuong_tru.xp_ten), u'') IS NOT NULL
                                THEN u', ' || dttp_thuong_tru.ttp_ten
                                ELSE dttp_thuong_tru.ttp_ten
                            END
                        ELSE u''
                       END
                )
                ELSE NULL
            END AS noi_dktt,
            rt.tha_toi_danh_names AS toi_danh,
            TO_CHAR(rt.tha_ngay_bat, 'DD/MM/YYYY') AS ngay_bat,
            rt.tha_an_phat AS an_phat,
            TO_CHAR(rt.tha_ngay_den_trai, 'DD/MM/YYYY') AS ngay_den_trai,
            TO_CHAR(rt.tha_ngay_het_han, 'DD/MM/YYYY') AS ngay_het_han,
            nnc.nnc_ten AS benh_tat,
            --PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(rt.pham_nhan_id) AS thoi_gian_da_giam,
            THOI_GIAN_DA_GIAM AS thoi_gian_da_giam,
            mtgch.mtg_title AS thoi_gian_da_chap_hanh,
            mtgcl.mtg_title AS thoi_gian_con_lai,
            dmttpn.ttpn_ten AS tinh_trang,
            NVL(TRIM(CAST(pd.pd_ten AS VARCHAR2(4000))), '') ||
            CASE WHEN pd.pd_ten IS NOT NULL AND pt.pt_ten IS NOT NULL THEN u', ' ELSE u'' END ||
            NVL(TRIM(CAST(pt.pt_ten AS VARCHAR2(4000))), '') AS phan_doi,
            rt.ho_ten_order
        FROM qlpn.pn_lai_lich_chi_tiet_rt rt
        LEFT JOIN qlpn.dm_ma_thoi_gians mtgch
            ON mtgch.mtg_ma = rt.tha_thoi_gian_da_chap_hanh
           AND mtgch.is_deleted = 0
        LEFT JOIN qlpn.dm_ma_thoi_gians mtgcl
            ON mtgcl.mtg_ma = rt.tha_thoi_gian_con_lai
           AND mtgcl.is_deleted = 0
        LEFT JOIN qlpn.dm_phan_trais pt
            ON rt.ll_phan_trai_id = pt.id
           AND pt.is_deleted = 0
        LEFT JOIN qlpn.dm_phan_dois pd
            ON rt.ll_phan_doi_id = pd.id
           AND pd.is_deleted = 0
        LEFT JOIN qlpn.dm_tinh_thanh_pho dttp_thuong_tru
            ON rt.ll_dia_chi_thuong_tru_provice = dttp_thuong_tru.id
           AND NVL(dttp_thuong_tru.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_xa_phuong dxp_thuong_tru
            ON rt.ll_dia_chi_thuong_tru_ward = dxp_thuong_tru.id
           AND NVL(dxp_thuong_tru.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_nguyen_nhan_chets nnc
            ON nnc.id = rt.ll_benh_tat_vao_id
        LEFT JOIN qlpn.dm_tinh_trang_pham_nhans dmttpn
            ON rt.ll_tinh_trang_id = dmttpn.id
           AND NVL(dmttpn.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_trai_giams traigiam
            ON rt.ll_trai_giam_id = traigiam.id
           AND traigiam.is_deleted = 0
        LEFT JOIN qlpn.dm_gioi_tinhs gt
            ON rt.ll_dm_gioi_tinh_id = gt.id
           AND gt.is_deleted = 0
        WHERE rt.ll_is_deleted = 0
          AND rt.is_deleted = 0
          AND rt.ll_benh_tat_vao_id IS NOT NULL
          AND NVL(rt.tha_is_deleted, 0) = 0
          AND (v_tu_ngay IS NULL OR TRUNC(rt.tha_ngay_den_trai) >= TRUNC(v_tu_ngay))
          AND (v_den_ngay IS NULL OR TRUNC(rt.tha_ngay_den_trai) <= TRUNC(v_den_ngay))
          AND (p_ma_trai_giam IS NULL OR traigiam.tg_ma = p_ma_trai_giam)
          AND (p_tinh_trang_id IS NULL OR dmttpn.id = p_tinh_trang_id)
          AND (p_phan_doi_id IS NULL OR rt.ll_phan_doi_id = p_phan_doi_id)
    ),
    count_data AS (
        SELECT COUNT(*) AS total_count
        FROM base_data
    ),
    page_data AS (
        SELECT *
        FROM base_data
        ORDER BY ho_ten_order NULLS LAST
        OFFSET p_skipcount ROWS
        FETCH NEXT p_maxresultcount ROWS ONLY
    )
    SELECT
        c.total_count,
        p.so_hsld,
        p.ho_ten,
        p.ns,
        p.gt,
        p.noi_dktt,
        p.toi_danh,
        p.ngay_bat,
        p.an_phat,
        p.ngay_den_trai,
        p.ngay_het_han,
        p.benh_tat,
        p.thoi_gian_da_giam,
        p.thoi_gian_da_chap_hanh,
        p.thoi_gian_con_lai,
        p.tinh_trang,
        p.phan_doi
    FROM page_data p
    CROSS JOIN count_data c;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            'L?i khi l?y danh sách ph?m nhân tình tr?ng b?nh t?t: ' || SQLERRM
        );
END ;




/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PHAM_NHAN_TRICH_XUAT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PHAM_NHAN_TRICH_XUAT" (
    p_trai_giam_id IN  NVARCHAR2    DEFAULT NULL, 
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id IN  NUMBER    DEFAULT NULL,
    p_maxresultcount IN  NUMBER    DEFAULT 25,
    p_skipcount      IN  NUMBER    DEFAULT 0         
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_trai_giam_id NUMBER;
    v_tu_ngay   DATE;
    v_den_ngay  DATE;
    c1          SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
     IF p_trai_giam_id IS NULL OR p_trai_giam_id = '' THEN
        v_trai_giam_id := NULL;
    ELSE
        v_trai_giam_id := p_trai_giam_id;
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
    WITH
    -- PN có trích xu?t trong kho?ng ngày (dùng cho gcr)
    tx_pn AS (
        SELECT DISTINCT tx.PHAM_NHAN_ID
        FROM TRICH_XUATS tx
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET v ON v.PHAM_NHAN_ID = tx.PHAM_NHAN_ID AND NVL(v.IS_DELETED, 0) = 0
        WHERE NVL(tx.IS_DELETED, 0) = 0
          AND tx.TX_NGAY_TRICH_XUAT IS NOT NULL
          AND (p_trai_giam_id IS NULL OR v.TRAI_GIAM_ID = p_trai_giam_id)
          AND (v_tu_ngay IS NULL OR TRUNC(tx.TX_NGAY_TRICH_XUAT) >= TRUNC(v_tu_ngay))
          AND (v_den_ngay IS NULL OR TRUNC(tx.TX_NGAY_TRICH_XUAT) <= TRUNC(v_den_ngay))
    ),
    -- Ghi chú riêng Lai l?ch: parse LL_GHI_CHU_RIENG (chu?i id) ? map DM_GHI_CHU_RIENGS.GCR_TEN
    gcr_raw AS (
        SELECT v.PHAM_NHAN_ID,
               REGEXP_REPLACE(NVL(TRIM(CAST(v.GHI_CHU_RIENG AS VARCHAR2(4000))), u''), '[[:space:]\[\]]', u'') AS gcr_clean
        FROM VW_PN_LAI_LICH_CHI_TIET v
        INNER JOIN tx_pn tp ON tp.PHAM_NHAN_ID = v.PHAM_NHAN_ID
        WHERE v.GHI_CHU_RIENG IS NOT NULL
          AND REGEXP_COUNT(REGEXP_REPLACE(NVL(TRIM(CAST(v.GHI_CHU_RIENG AS VARCHAR2(4000))), u''), '[[:space:]\[\]]', u''), '[0-9]+') > 0
          AND NVL(v.IS_DELETED, 0) = 0
    ),
    gcr_ids AS (
        SELECT r.PHAM_NHAN_ID,
               TO_NUMBER(REGEXP_SUBSTR(r.gcr_clean, '[0-9]+', 1, LEVEL)) AS gcr_id,
               LEVEL AS ord
        FROM gcr_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.gcr_clean, '[0-9]+')
          AND PRIOR r.PHAM_NHAN_ID = r.PHAM_NHAN_ID
          AND PRIOR SYS_GUID() IS NOT NULL
    ),
    gcr_agg AS (
        SELECT ids.PHAM_NHAN_ID,
               SUBSTR(LISTAGG(CAST(g.GCR_TEN AS VARCHAR2(500)), ', ') WITHIN GROUP (ORDER BY ids.ord), 1, 2000) AS ghi_chu_rieng_ten
        FROM gcr_ids ids
        JOIN DM_GHI_CHU_RIENGS g ON g.ID = ids.gcr_id AND NVL(g.IS_DELETED, 0) = 0
        GROUP BY ids.PHAM_NHAN_ID
    ),
    -- M?t LL m?i nh?t m?i PN (tránh dup t? VW_PN_LAI_LICH_CHI_TIET)
    LL_one AS (
        SELECT * FROM (
            SELECT v.*, ROW_NUMBER() OVER (PARTITION BY v.PHAM_NHAN_ID
                ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
                         v.CREATION_TIME DESC NULLS LAST) AS rn
            FROM VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
        ) x WHERE rn = 1
    )
    SELECT * FROM (
    SELECT
        --ROW_NUMBER() OVER (ORDER BY tx.TX_NGAY_TRICH_XUAT DESC NULLS LAST, v.HO_TEN) AS rn_all,
        ROW_NUMBER() OVER (ORDER BY   ORDER_HOTEN(v.HO_TEN) NULLS LAST) AS rn_all,
        COUNT(*) OVER() AS total_count,          
        v.SO_HO_SO                    AS SO_HSLD,
        -- H? TÊN: h? tên, gi?i tính-n?m sinh (vd: TH?CH LÂM, Nam-1991)
--        CAST(NVL(TRIM(CAST(v.HO_TEN AS NVARCHAR2(2000))), u'') AS NVARCHAR2(2000)) ||
--        CASE WHEN v.GIOI_TINH IS NOT NULL OR v.NAM_SINH IS NOT NULL
--             THEN u', ' || NVL(TRIM(CAST(v.GIOI_TINH AS NVARCHAR2(100))), u'') ||
--                  CASE WHEN v.NAM_SINH IS NOT NULL THEN u'-' || CAST(TO_CHAR(v.NAM_SINH) AS NVARCHAR2(10)) ELSE u'' END
--             ELSE u''
--        END AS HO_TEN,
        v.HO_TEN,
        v.NGAY_SINH,
        v.NAM_SINH,
        V.GIOI_TINH,
        NVL(TRIM(CAST(v.NOI_THUONG_TRU_DAY_DU AS NVARCHAR2(2000))), u'') AS DIA_CHI_THUONG_TRU,
        NVL(TRIM(CAST(v.TOI_DANH AS NVARCHAR2(2000))), u'') AS TOI_DANH,
        -- S? TA: s? th? án (SO_BAN_AN ho?c SO_HO_SO)
        NVL(TRIM(CAST(v.SO_BAN_AN AS NVARCHAR2(100))), NVL(TRIM(CAST(v.SO_HO_SO AS NVARCHAR2(100))), u'')) AS SO_TA,
        v.NGAY_BAT_AN_PHAT AS NGAY_BAT,
        v.AN_PHAT AS AN_PHAT,
        V.NGAY_DEN_TRAI,
        CQ_TEN CO_QUAN_DE_NGHI, 
        -- NGÀY VÀO PHÂN ??I: ngày ??n tr?i, ??i X, Phân tr?i Y (vd: 05/09/2014, ??i 27, Phân tr?i S? 1)
        NVL(CAST(TO_CHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NVARCHAR2(20)), u'') ||
        CASE WHEN v.PHAN_DOI IS NOT NULL OR v.PHAN_TRAI IS NOT NULL
             THEN NVL2(v.NGAY_DEN_TRAI, u', ', u'') ||
                  NVL(TRIM(CAST(v.PHAN_DOI AS NVARCHAR2(200))), u'') ||
                  CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
                  NVL(TRIM(CAST(v.PHAN_TRAI AS NVARCHAR2(200))), u'')
             ELSE u''
        END AS NGAY_VAO_PHAN_DOI,
        -- S? - NGÀY / LO?I Q?: s? l?nh - ngày ra l?nh, lo?i quy?t ??nh (vd: 0012 - 01/12/2025, L?nh trích xu?t)
        tx.TX_SO_LENH AS SO_LENH,
        CAST(NVL(TRIM(CAST(tx.TX_SO_LENH AS VARCHAR2(255))), u'') AS NVARCHAR2(1000)) ||
        CASE WHEN tx.TX_NGAY_RA_LENH IS NOT NULL
             THEN u' - ' || CAST(TO_CHAR(tx.TX_NGAY_RA_LENH, 'DD/MM/YYYY') AS NVARCHAR2(20))
             ELSE u''
        END ||
        CASE WHEN lqdtx.LQDTX_TEN IS NOT NULL
             THEN u', ' || NVL(TRIM(CAST(lqdtx.LQDTX_TEN AS NVARCHAR2(500))), u'')
             ELSE u''
        END AS SO_NGAY_LOAI_QD,
        -- NGÀY TX / TH?I H?N: ngày trích xu?t, th?i h?n (vd: 01/12/2025, 10 ngày)
        TO_CHAR(tx.TX_NGAY_TRICH_XUAT, 'DD/MM/YYYY') TU_NGAY, --t? ngày
        NVL(CAST(TO_CHAR(tx.TX_NGAY_TRICH_XUAT, 'DD/MM/YYYY') AS NVARCHAR2(20)), u'') ||
        CASE WHEN mtg.MTG_TITLE IS NOT NULL
             THEN u', ' || NVL(TRIM(CAST(mtg.MTG_TITLE AS NVARCHAR2(200))), u'')
             ELSE u''
        END AS NGAY_TX_THOI_HAN,
        mtg.MTG_TITLE AS THOI_HAN,
        -- LÝ DO TRÍCH XU?T
        NVL(TRIM(CAST(ldtr.LDTX_TEN AS NVARCHAR2(500))), u'') AS LY_DO_TRICH_XUAT,
        -- NGÀY L?I TÌNH TR?NG: ngày tr? + tình tr?ng (n?u ?ã tr?); n?u ch?a tr? = "Trích xu?t"
        CASE WHEN tx.TX_NGAY_TRA IS NOT NULL
             THEN CAST(TO_CHAR(tx.TX_NGAY_TRA, 'DD/MM/YYYY') AS NVARCHAR2(20)) ||
                  CASE WHEN txtx.TTTX_TEN IS NOT NULL THEN u', ' || NVL(TRIM(CAST(txtx.TTTX_TEN AS NVARCHAR2(200))), u'') ELSE u'' END
             ELSE NVL(TRIM(CAST(txtx.TTTX_TEN AS NVARCHAR2(200))), u'Tr\00edch xu\1ea5t')
        END AS NGAY_LAI_TINH_TRANG,
        TO_CHAR(tx.TX_NGAY_TRA, 'DD/MM/YYYY')   as DEN_NGAY, --den ngay
         NVL(TRIM(CAST(txtx.TTTX_TEN AS NVARCHAR2(200))), u'Tr\00edch xu\1ea5t') AS TRANG_THAI,
         v.PHAN_DOI,
        -- GHI CHÚ = ghi chú riêng Lai l?ch (LL_GHI_CHU_RIENG ? DM_GHI_CHU_RIENGS.GCR_TEN)
        NVL(CAST(ga.ghi_chu_rieng_ten AS NVARCHAR2(2000)), u'') AS GHI_CHU
    FROM TRICH_XUATS tx
    INNER JOIN LL_one v ON v.PHAM_NHAN_ID = tx.PHAM_NHAN_ID
    LEFT JOIN gcr_agg ga ON ga.PHAM_NHAN_ID = v.PHAM_NHAN_ID
    LEFT JOIN DM_LOAI_QUYET_DINH_TRICH_XUATS lqdtx
        ON tx.TX_LOAI_LENH_ID = lqdtx.ID AND NVL(lqdtx.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS DMCQ ON DMCQ.ID = TX.TX_DON_VI_DE_NGHI_ID
    LEFT JOIN DM_LY_DO_TRICH_XUATS ldtr
        ON tx.TX_LY_DO_ID = ldtr.ID AND NVL(ldtr.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_TRANG_TRICH_XUATS txtx
        ON tx.TX_TINH_TRANG_ID = txtx.ID AND NVL(txtx.IS_DELETED, 0) = 0
    LEFT JOIN DM_MA_THOI_GIANS mtg
        ON tx.TX_THOI_HAN_ID = mtg.ID AND NVL(mtg.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn  ON v.LL_TINH_TRANG_ID = dmttpn.ID  AND NVL(dmttpn.IS_DELETED, 0) = 0        
    WHERE NVL(tx.IS_DELETED, 0) = 0
      AND tx.TX_NGAY_TRICH_XUAT IS NOT NULL
      AND (p_trai_giam_id IS NULL OR v.TRAI_GIAM_ID = p_trai_giam_id)
      AND (v_tu_ngay IS NULL OR TRUNC(tx.TX_NGAY_TRICH_XUAT) >= TRUNC(v_tu_ngay))
      AND (v_den_ngay IS NULL OR TRUNC(tx.TX_NGAY_TRICH_XUAT) <= TRUNC(v_den_ngay))
    AND (p_tinh_trang_id IS NULL OR dmttpn.ID = p_tinh_trang_id)
    AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)      
    --ORDER BY tx.TX_NGAY_TRICH_XUAT DESC NULLS LAST, v.HO_TEN
          ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
    )
          ; 


    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân trích xu?t: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_PHAM_NHAN_TRICH_XUAT;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PHAM_NHAN_TRICH_XUAT_DEN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PHAM_NHAN_TRICH_XUAT_DEN" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL, 
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id IN  NUMBER    DEFAULT NULL,
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT NULL        
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_trai_giam_id NUMBER;
    v_tu_ngay   DATE;
    v_den_ngay  DATE;
    c1          SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
     IF p_ma_trai_giam IS NULL OR p_ma_trai_giam = '' THEN
        v_trai_giam_id := NULL;
    ELSE
        v_trai_giam_id := p_ma_trai_giam;
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
    WITH
    -- PN có trích xu?t trong kho?ng ngày (dùng cho gcr)
    tx_pn AS (
        SELECT DISTINCT tx.PHAM_NHAN_ID
        FROM TRICH_XUATS tx
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET v ON v.PHAM_NHAN_ID = tx.PHAM_NHAN_ID AND NVL(v.IS_DELETED, 0) = 0
        WHERE NVL(tx.IS_DELETED, 0) = 0
          AND tx.TX_NGAY_TRICH_XUAT IS NOT NULL
          --AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_ID = p_ma_trai_giam)
          AND (v_tu_ngay IS NULL OR tx.TX_NGAY_TRICH_XUAT >= v_tu_ngay)
          AND (v_den_ngay IS NULL OR tx.TX_NGAY_TRICH_XUAT <= v_den_ngay)
    ),
    -- Ghi chú riêng Lai l?ch: parse LL_GHI_CHU_RIENG (chu?i id) ? map DM_GHI_CHU_RIENGS.GCR_TEN
    gcr_raw AS (
        SELECT v.PHAM_NHAN_ID,
               REGEXP_REPLACE(NVL(TRIM(CAST(v.GHI_CHU_RIENG AS VARCHAR2(4000))), u''), '[[:space:]\[\]]', u'') AS gcr_clean
        FROM VW_PN_LAI_LICH_CHI_TIET v
        INNER JOIN tx_pn tp ON tp.PHAM_NHAN_ID = v.PHAM_NHAN_ID
        WHERE v.GHI_CHU_RIENG IS NOT NULL
          AND REGEXP_COUNT(REGEXP_REPLACE(NVL(TRIM(CAST(v.GHI_CHU_RIENG AS VARCHAR2(4000))), u''), '[[:space:]\[\]]', u''), '[0-9]+') > 0
          AND NVL(v.IS_DELETED, 0) = 0
    ),
    gcr_ids AS (
        SELECT r.PHAM_NHAN_ID,
               TO_NUMBER(REGEXP_SUBSTR(r.gcr_clean, '[0-9]+', 1, LEVEL)) AS gcr_id,
               LEVEL AS ord
        FROM gcr_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.gcr_clean, '[0-9]+')
          AND PRIOR r.PHAM_NHAN_ID = r.PHAM_NHAN_ID
          AND PRIOR SYS_GUID() IS NOT NULL
    ),
    gcr_agg AS (
        SELECT ids.PHAM_NHAN_ID,
               SUBSTR(LISTAGG(CAST(g.GCR_TEN AS VARCHAR2(500)), ', ') WITHIN GROUP (ORDER BY ids.ord), 1, 2000) AS ghi_chu_rieng_ten
        FROM gcr_ids ids
        JOIN DM_GHI_CHU_RIENGS g ON g.ID = ids.gcr_id AND NVL(g.IS_DELETED, 0) = 0
        GROUP BY ids.PHAM_NHAN_ID
    ),
    -- M?t LL m?i nh?t m?i PN (tránh dup t? VW_PN_LAI_LICH_CHI_TIET)
    LL_one AS (
        SELECT * FROM (
            SELECT v.* 
            FROM VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
    AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))            

        ) x  
    )
    SELECT * FROM (
    SELECT
         COUNT(*) OVER() AS total_count,          
        v.SO_HO_SO                    AS SO_HSLD,
        -- H? TÊN: h? tên, gi?i tính-n?m sinh (vd: TH?CH LÂM, Nam-1991)
        v.HO_TEN AS HO_TEN,
        v.NGAY_SINH,
        v.NAM_SINH,
        V.GIOI_TINH,
        NVL(TRIM(CAST(v.NOI_THUONG_TRU_DAY_DU AS NVARCHAR2(2000))), u'') AS DIA_CHI_THUONG_TRU,
        NVL(TRIM(CAST(v.TOI_DANH AS NVARCHAR2(2000))), u'') AS TOI_DANH,
        -- S? TA: s? th? án (SO_BAN_AN ho?c SO_HO_SO)
        NVL(TRIM(CAST(v.SO_BAN_AN AS NVARCHAR2(100))), NVL(TRIM(CAST(v.SO_HO_SO AS NVARCHAR2(100))), u'')) AS SO_TA,
        --v.NGAY_BAT_AN_PHAT AS NGAY_BAT,
        TO_CHAR(v.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT,
        v.AN_PHAT AS AN_PHAT,
        --V.NGAY_DEN_TRAI,
        TO_CHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
        CQ_TEN CO_QUAN_DE_NGHI, 
        -- NGÀY VÀO PHÂN ??I: ngày ??n tr?i, ??i X, Phân tr?i Y (vd: 05/09/2014, ??i 27, Phân tr?i S? 1)
--        NVL(CAST(TO_CHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NVARCHAR2(20)), u'') ||
--        CASE WHEN v.PHAN_DOI IS NOT NULL OR v.PHAN_TRAI IS NOT NULL
--             THEN NVL2(v.NGAY_DEN_TRAI, u', ', u'') ||
--                  NVL(TRIM(CAST(v.PHAN_DOI AS NVARCHAR2(200))), u'') ||
--                  CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
--                  NVL(TRIM(CAST(v.PHAN_TRAI AS NVARCHAR2(200))), u'')
--             ELSE u''
--        END AS NGAY_VAO_PHAN_DOI,
        -- S? - NGÀY / LO?I Q?: s? l?nh - ngày ra l?nh, lo?i quy?t ??nh (vd: 0012 - 01/12/2025, L?nh trích xu?t)
        --LY_DO,
        tx.TX_SO_LENH AS SO_LENH,
        --tx.TX_NGAY_RA_LENH,
        TO_CHAR(tx.TX_NGAY_RA_LENH, 'DD/MM/YYYY') AS TX_NGAY_RA_LENH,
        lqdtx.LQDTX_TEN AS LOAI_QD,
--        CAST(NVL(TRIM(CAST(tx.TX_SO_LENH AS VARCHAR2(255))), u'') AS NVARCHAR2(1000)) ||
--        CASE WHEN tx.TX_NGAY_RA_LENH IS NOT NULL
--             THEN u' - ' || CAST(TO_CHAR(tx.TX_NGAY_RA_LENH, 'DD/MM/YYYY') AS NVARCHAR2(20))
--             ELSE u''
--        END ||
--        CASE WHEN lqdtx.LQDTX_TEN IS NOT NULL
--             THEN u', ' || NVL(TRIM(CAST(lqdtx.LQDTX_TEN AS NVARCHAR2(500))), u'')
--             ELSE u''
--        END AS SO_NGAY_LOAI_QD,
        -- NGÀY TX / TH?I H?N: ngày trích xu?t, th?i h?n (vd: 01/12/2025, 10 ngày)
        TO_CHAR(tx.TX_NGAY_TRICH_XUAT, 'DD/MM/YYYY') TU_NGAY, --t? ngày
        TO_CHAR(tx.TX_NGAY_TRICH_XUAT, 'DD/MM/YYYY') NGAY_TRICH_XUAT,
        NVL(CAST(TO_CHAR(tx.TX_NGAY_TRICH_XUAT, 'DD/MM/YYYY') AS NVARCHAR2(20)), u'') ||
        CASE WHEN mtg.MTG_TITLE IS NOT NULL
             THEN u', ' || NVL(TRIM(CAST(mtg.MTG_TITLE AS NVARCHAR2(200))), u'')
             ELSE u''
        END AS NGAY_TX_THOI_HAN,
        mtg.MTG_TITLE AS THOI_HAN,
        -- LÝ DO TRÍCH XU?T
        NVL(TRIM(CAST(ldtr.LDTX_TEN AS NVARCHAR2(500))), u'') AS LY_DO_TRICH_XUAT,
        -- NGÀY L?I TÌNH TR?NG: ngày tr? + tình tr?ng (n?u ?ã tr?); n?u ch?a tr? = "Trích xu?t"
--        CASE WHEN tx.TX_NGAY_TRA IS NOT NULL
--             THEN CAST(TO_CHAR(tx.TX_NGAY_TRA, 'DD/MM/YYYY') AS NVARCHAR2(20)) ||
--                  CASE WHEN txtx.TTTX_TEN IS NOT NULL THEN u', ' || NVL(TRIM(CAST(txtx.TTTX_TEN AS NVARCHAR2(200))), u'') ELSE u'' END
--             ELSE NVL(TRIM(CAST(txtx.TTTX_TEN AS NVARCHAR2(200))), u'Tr\00edch xu\1ea5t')
--        END AS NGAY_LAI_TINH_TRANG,
        TO_CHAR(tx.TX_NGAY_TRA, 'DD/MM/YYYY')   as DEN_NGAY, --den ngay
        TO_CHAR(tx.TX_NGAY_TRA, 'DD/MM/YYYY')   as NGAY_LAI, --den ngay
         NVL(TRIM(CAST(txtx.TTTX_TEN AS NVARCHAR2(200))), u'Tr\00edch xu\1ea5t') AS TRANG_THAI,
        -- v.PHAN_DOI,
    	        -- PHAN_DOI: phân ??i, phân tr?i
	        NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
	        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
	        NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI  ,        
--        -- GHI CHÚ = ghi chú riêng Lai l?ch (LL_GHI_CHU_RIENG ? DM_GHI_CHU_RIENGS.GCR_TEN)
        NVL(CAST(ga.ghi_chu_rieng_ten AS NVARCHAR2(2000)), u'') AS GHI_CHU
    FROM TRICH_XUATS tx
    INNER JOIN LL_one v ON v.PHAM_NHAN_ID = tx.PHAM_NHAN_ID
    LEFT JOIN gcr_agg ga ON ga.PHAM_NHAN_ID = v.PHAM_NHAN_ID
    LEFT JOIN DM_LOAI_QUYET_DINH_TRICH_XUATS lqdtx
        ON tx.TX_LOAI_LENH_ID = lqdtx.ID AND NVL(lqdtx.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS DMCQ ON DMCQ.ID = TX.TX_DON_VI_DE_NGHI_ID
    LEFT JOIN DM_LY_DO_TRICH_XUATS ldtr
        ON tx.TX_LY_DO_ID = ldtr.ID AND NVL(ldtr.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_TRANG_TRICH_XUATS txtx
        ON tx.TX_TINH_TRANG_ID = txtx.ID AND NVL(txtx.IS_DELETED, 0) = 0
    LEFT JOIN DM_MA_THOI_GIANS mtg
        ON tx.TX_THOI_HAN_ID = mtg.ID AND NVL(mtg.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn  ON v.LL_TINH_TRANG_ID = dmttpn.ID  AND NVL(dmttpn.IS_DELETED, 0) = 0        
    WHERE NVL(tx.IS_DELETED, 0) = 0
      AND tx.TX_NGAY_TRICH_XUAT IS NOT NULL
      --AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_ID = p_ma_trai_giam)
    AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))            
      AND (v_tu_ngay IS NULL OR  tx.TX_NGAY_TRICH_XUAT  >=  v_tu_ngay) 
      AND (v_den_ngay IS NULL OR  tx.TX_NGAY_TRICH_XUAT  <=  v_den_ngay) 
    AND (p_tinh_trang_id IS NULL OR dmttpn.ID = p_tinh_trang_id)
    AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id) 
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
     )
        ; 


    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân trích xu?t: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_PHAM_NHAN_TRICH_XUAT_DEN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PHAM_NHAN_TRON_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PHAM_NHAN_TRON_TRAI" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY
    p_bat_lai_tu_ngay      IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_bat_lai_den_ngay     IN  VARCHAR2  DEFAULT NULL,   -- DD/MM/YYYY    
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id IN  NUMBER    DEFAULT NULL,
    p_maxresultcount IN  NUMBER    DEFAULT 25,
    p_skipcount      IN  NUMBER    DEFAULT 0
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_tu_ngay   DATE;
    v_den_ngay  DATE;
    v_bat_lai_tu_ngay   DATE;
    v_bat_lai_den_ngay  DATE;    
    c1          SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
    -- Parse ngày
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_bat_lai_tu_ngay IS NULL OR TRIM(p_bat_lai_tu_ngay) = '' THEN
        v_bat_lai_tu_ngay := NULL;
    ELSE
        v_bat_lai_tu_ngay := TO_DATE(TRIM(p_bat_lai_tu_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_bat_lai_den_ngay IS NULL OR TRIM(p_bat_lai_den_ngay) = '' THEN
        v_bat_lai_den_ngay := NULL;
    ELSE
        v_bat_lai_den_ngay := TO_DATE(TRIM(p_bat_lai_den_ngay), 'DD/MM/YYYY');
    END IF;
    OPEN c1 FOR
    WITH
    -- PN có tr?n tr?i trong kho?ng ngày (dùng cho gcr)
    tron_pn AS (
        SELECT DISTINCT tt.PHAM_NHAN_ID
        FROM TRON_TRAIS tt
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET v ON v.PHAM_NHAN_ID = tt.PHAM_NHAN_ID AND NVL(v.IS_DELETED, 0) = 0
        WHERE NVL(tt.IS_DELETED, 0) = 0
          AND tt.NGAY_TRON IS NOT NULL
    AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))            
          AND (v_tu_ngay IS NULL OR  tt.NGAY_TRON  >=  v_tu_ngay)  
          AND (v_den_ngay IS NULL OR  tt.NGAY_TRON  <=  v_den_ngay) 
          AND (v_bat_lai_tu_ngay IS NULL OR  tt.NGAY_BAT_LAI  >=  v_bat_lai_tu_ngay) 
          AND (v_bat_lai_den_ngay IS NULL OR  tt.NGAY_BAT_LAI  <=  v_bat_lai_den_ngay)           
    ),
    -- Ghi chú riêng Lai l?ch: parse LL_GHI_CHU_RIENG (chu?i id) ? map DM_GHI_CHU_RIENGS.GCR_TEN
    gcr_raw AS (
        SELECT v.PHAM_NHAN_ID,
               REGEXP_REPLACE(NVL(TRIM(CAST(v.GHI_CHU_RIENG AS VARCHAR2(4000))), ''), '[[:space:]\[\]]', '') AS gcr_clean
        FROM VW_PN_LAI_LICH_CHI_TIET v
        INNER JOIN tron_pn tp ON tp.PHAM_NHAN_ID = v.PHAM_NHAN_ID
        WHERE v.GHI_CHU_RIENG IS NOT NULL
          AND REGEXP_COUNT(REGEXP_REPLACE(NVL(TRIM(CAST(v.GHI_CHU_RIENG AS VARCHAR2(4000))), ''), '[[:space:]\[\]]', ''), '[0-9]+') > 0
          AND NVL(v.IS_DELETED, 0) = 0
    ),
    gcr_ids AS (
        SELECT r.PHAM_NHAN_ID,
               TO_NUMBER(REGEXP_SUBSTR(r.gcr_clean, '[0-9]+', 1, LEVEL)) AS gcr_id,
               LEVEL AS ord
        FROM gcr_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.gcr_clean, '[0-9]+')
          AND PRIOR r.PHAM_NHAN_ID = r.PHAM_NHAN_ID
          AND PRIOR SYS_GUID() IS NOT NULL
    ),
    gcr_agg AS (
        SELECT ids.PHAM_NHAN_ID,
               SUBSTR(LISTAGG(CAST(g.GCR_TEN AS VARCHAR2(500)), ', ') WITHIN GROUP (ORDER BY ids.ord), 1, 2000) AS ghi_chu_rieng_ten
        FROM gcr_ids ids
        JOIN DM_GHI_CHU_RIENGS g ON g.ID = ids.gcr_id AND NVL(g.IS_DELETED, 0) = 0
        GROUP BY ids.PHAM_NHAN_ID
    )
    select * from (
    SELECT
        --ROW_NUMBER() OVER (ORDER BY tt.NGAY_TRON DESC NULLS LAST, v.HO_TEN) AS rn_all,
        --ROW_NUMBER() OVER (ORDER BY   ORDER_HOTEN(v.HO_TEN) NULLS LAST) AS rn_all,
        COUNT(*) OVER() AS total_count, 
        v.SO_HO_SO                    AS SO_HSLD,
        v.HO_TEN                      AS HO_TEN,
        v.NGAY_SINH                   AS NS,
        v.GIOI_TINH                   AS GT,
        v.NOI_THUONG_TRU_DAY_DU       AS NOI_DKTT,
        v.TOI_DANH                    AS TOI_DANH,
        --v.NGAY_BAT_AN_PHAT            AS NGAY_BAT,
        TO_CHAR(v.NGAY_BAT_AN_PHAT , 'DD/mm/yyyy') AS NGAY_BAT,
        v.AN_PHAT                     AS AN_PHAT,
        --v.NGAY_DEN_TRAI               AS NGAY_DEN_TRAI,
        TO_CHAR(v.NGAY_DEN_TRAI , 'DD/mm/yyyy') AS NGAY_DEN_TRAI,
        --tt.NGAY_TRON                  AS NGAY_TRON,
        TO_CHAR(tt.NGAY_TRON , 'DD/mm/yyyy') AS NGAY_TRON,
        --TO_CHAR(tt.NGAY_TRON, 'DD/MM/YYYY') AS NGAY_TRON,
        NVL(CAST(dthtr.THT_TEN AS NVARCHAR2(500)), u'') AS HINH_THUC_TRON,
        NVL(CAST(dhtxlb.HTXLB_TEN AS NVARCHAR2(500)), u'') AS HINH_THUC_XU_LY,
        --tt.NGAY_BAT_LAI               AS NGAY_BAT_LAI,
        TO_CHAR(tt.NGAY_BAT_LAI , 'DD/mm/yyyy') AS NGAY_BAT_LAI,
        -- GHI_CHU = ghi chú riêng Lai l?ch (LL_GHI_CHU_RIENG ? DM_GHI_CHU_RIENGS.GCR_TEN)
        NVL(CAST(ga.ghi_chu_rieng_ten AS NVARCHAR2(2000)), u'') AS GHI_CHU,
        -- PHAN_DOI: phân ??i, phân tr?i (gi?ng SP_GET_BAO_CAO_DS_PHAM_NHAN_TINH_TRANG_BENH_TAT)
        NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
        NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
    FROM TRON_TRAIS tt
    INNER JOIN VW_PN_LAI_LICH_CHI_TIET v
        ON v.PHAM_NHAN_ID = tt.PHAM_NHAN_ID
       AND NVL(v.IS_DELETED, 0) = 0
    LEFT JOIN gcr_agg ga ON ga.PHAM_NHAN_ID = v.PHAM_NHAN_ID
    LEFT JOIN DM_TRUONG_HOP_TRONS dthtr
        ON tt.TRUONG_HOP_TRON_ID = dthtr.ID
       AND NVL(dthtr.IS_DELETED, 0) = 0
    LEFT JOIN DM_HINH_THUC_XU_LY_BATS dhtxlb
        ON tt.HINH_THUC_XU_LY_ID = dhtxlb.ID
       AND NVL(dhtxlb.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn
        ON v.LL_TINH_TRANG_ID = dmttpn.ID
       AND NVL(dmttpn.IS_DELETED, 0) = 0       
    WHERE NVL(tt.IS_DELETED, 0) = 0
    AND tt.NGAY_TRON IS NOT NULL
    AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))            
    AND (v_tu_ngay IS NULL OR  tt.NGAY_TRON  >=  v_tu_ngay) 
    AND (v_den_ngay IS NULL OR  tt.NGAY_TRON  <= v_den_ngay) 
    AND (v_bat_lai_tu_ngay IS NULL OR  tt.NGAY_BAT_LAI  >=  v_bat_lai_tu_ngay) 
    AND (v_bat_lai_den_ngay IS NULL OR  tt.NGAY_BAT_LAI <=  v_bat_lai_den_ngay)
    AND (p_tinh_trang_id IS NULL OR dmttpn.ID = p_tinh_trang_id)
    AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)
               ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY )
     ;    

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân tr?n tr?i: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_PHAM_NHAN_TRON_TRAI;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PHAN_LOAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PHAN_LOAI" (
    p_ma_trai_giam           IN NVARCHAR2 DEFAULT NULL,
    p_den_trai_tu_ngay       IN VARCHAR2  DEFAULT NULL,
    p_den_trai_den_ngay      IN VARCHAR2  DEFAULT NULL,
    p_phan_loai_tu_ngay      IN VARCHAR2  DEFAULT NULL,
    p_phan_loai_den_ngay     IN VARCHAR2  DEFAULT NULL,
    p_tinh_trang_id          IN NUMBER    DEFAULT NULL,
    p_phan_doi_id            IN NUMBER    DEFAULT NULL,
    p_loai_quyet_dinh_id     IN NUMBER    DEFAULT NULL,
    p_maxresultcount         IN NUMBER    DEFAULT NULL,
    p_skipcount              IN NUMBER    DEFAULT NULL
) AS
    v_den_trai_tu   DATE;
    v_den_trai_den  DATE;
    v_phan_loai_tu  DATE;
    v_phan_loai_den DATE;
    v_skip          NUMBER;
    v_limit         NUMBER;
    c1              SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    v_den_trai_tu  := CASE WHEN p_den_trai_tu_ngay  IS NULL OR TRIM(p_den_trai_tu_ngay)  = '' THEN NULL
                           ELSE TRUNC(TO_DATE(TRIM(p_den_trai_tu_ngay),  'DD/MM/YYYY')) END;
    v_den_trai_den := CASE WHEN p_den_trai_den_ngay IS NULL OR TRIM(p_den_trai_den_ngay) = '' THEN NULL
                           ELSE TRUNC(TO_DATE(TRIM(p_den_trai_den_ngay), 'DD/MM/YYYY')) END;
    v_phan_loai_tu := CASE WHEN p_phan_loai_tu_ngay  IS NULL OR TRIM(p_phan_loai_tu_ngay)  = '' THEN NULL
                           ELSE TRUNC(TO_DATE(TRIM(p_phan_loai_tu_ngay),  'DD/MM/YYYY')) END;
    v_phan_loai_den := CASE WHEN p_phan_loai_den_ngay IS NULL OR TRIM(p_phan_loai_den_ngay) = '' THEN NULL
                            ELSE TRUNC(TO_DATE(TRIM(p_phan_loai_den_ngay), 'DD/MM/YYYY')) END;

    OPEN c1 FOR
    WITH
    phan_loai_f AS (
        -- Phân lo?i th?a ngày, m?i pn l?y m?i nh?t (rn=1)
        SELECT /*+ MATERIALIZE */
            pl2.pham_nhan_id, pl2.ngay_phan_loai,
            pl2.loai_phan_loai_id, pl2.tu_loai_id, pl2.den_loai_id
        FROM (
            SELECT pl.pham_nhan_id, pl.ngay_phan_loai,
                   pl.loai_phan_loai_id, pl.tu_loai_id, pl.den_loai_id,
                   ROW_NUMBER() OVER (
                       PARTITION BY pl.pham_nhan_id
                       ORDER BY NVL(pl.NGAY_PHAN_LOAI, pl.CREATION_TIME) DESC NULLS LAST,
                                pl.ID DESC
                   ) AS rn
            FROM PHAN_LOAIS pl
            WHERE NVL(pl.IS_DELETED, 0) = 0
              AND (p_loai_quyet_dinh_id IS NULL OR pl.LOAI_PHAN_LOAI_ID = p_loai_quyet_dinh_id)
              AND (v_phan_loai_tu  IS NULL OR pl.NGAY_PHAN_LOAI >= v_phan_loai_tu)
              AND (v_phan_loai_den IS NULL OR pl.NGAY_PHAN_LOAI <  v_phan_loai_den + 1)
        ) pl2
        WHERE pl2.rn = 1
    ),
    ptha_one AS (
        -- THA m?i nh?t (l?c ngày ??n tr?i)
        SELECT /*+ MATERIALIZE */
            x.THA_PNLAI_LICH_ID, x.THA_NGAY_DEN_TRAI,
            x.THA_NGAY_HET_HAN, x.THA_NGAY_QD_THA
        FROM (
            SELECT t.THA_PNLAI_LICH_ID, t.THA_NGAY_DEN_TRAI,
                   t.THA_NGAY_HET_HAN, t.THA_NGAY_QD_THA,
                   ROW_NUMBER() OVER (
                       PARTITION BY t.THA_PNLAI_LICH_ID
                       ORDER BY NVL(t.THA_NGAY_QD_THA, t.CREATION_TIME) DESC NULLS LAST,
                                t.ID DESC
                   ) AS rn
            FROM PN_THI_HANH_AN t
            WHERE NVL(t.IS_DELETED, 0) = 0
        ) x
        WHERE x.rn = 1
    ),
    base AS (
        SELECT
            ll.ID                    AS pn_id,
            ll.LL_TINH_TRANG_ID,
            CAST(ll.LL_SO_HO_SO_LAN_DAU AS NVARCHAR2(100)) AS SO_HSLD,
            ll.LL_HO_TEN             AS HO_TEN,
            pl.NGAY_PHAN_LOAI,
            pl.LOAI_PHAN_LOAI_ID,
            pl.TU_LOAI_ID,
            pl.DEN_LOAI_ID,
            ptha.THA_NGAY_DEN_TRAI,
            ptha.THA_NGAY_HET_HAN
        FROM phan_loai_f pl
        INNER JOIN PN_LAI_LICHS ll
            ON ll.ID = pl.pham_nhan_id
           AND NVL(ll.IS_DELETED, 0) = 0
        LEFT JOIN ptha_one ptha
            ON ptha.THA_PNLAI_LICH_ID = ll.ID
        WHERE (p_tinh_trang_id IS NULL OR ll.LL_TINH_TRANG_ID = p_tinh_trang_id)
          --AND (p_ma_trai_giam  IS NULL OR ll.LL_TRAI_GIAM_ID  = TO_NUMBER(p_ma_trai_giam))
        AND (p_ma_trai_giam IS NULL OR ( ll.LL_TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))


          AND (p_phan_doi_id   IS NULL OR ll.LL_PHAN_DOI_ID   = p_phan_doi_id)
          AND (v_den_trai_tu   IS NULL
               OR (ptha.THA_NGAY_DEN_TRAI IS NOT NULL
                   AND ptha.THA_NGAY_DEN_TRAI >= v_den_trai_tu))
          AND (v_den_trai_den  IS NULL
               OR (ptha.THA_NGAY_DEN_TRAI IS NOT NULL
                   AND ptha.THA_NGAY_DEN_TRAI < v_den_trai_den + 1))
    ),
    cnt_agg AS (
        SELECT COUNT(*) AS total_count FROM base
    ),
    page_b AS (
        SELECT b.pn_id, b.SO_HSLD, b.HO_TEN, b.LL_TINH_TRANG_ID,
               b.NGAY_PHAN_LOAI, b.LOAI_PHAN_LOAI_ID,
               b.TU_LOAI_ID, b.DEN_LOAI_ID,
               b.THA_NGAY_HET_HAN
        FROM base b
        ORDER BY ORDER_HOTEN(b.HO_TEN)
        OFFSET v_skip ROWS
        FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY
    ),
    gth_one AS (
        -- GIAM_THOI_HANS m?i nh?t cho ~page rows
        SELECT /*+ LEADING(p gth) USE_NL(gth) */
            gth.PHAM_NHAN_ID,
            gth.MUC_DE_NGHI_ID, gth.CAP_TREN_DUYET_ID, gth.MUC_GIAM_ID
        FROM (SELECT DISTINCT pn_id FROM page_b) p
        INNER JOIN GIAM_THOI_HANS gth
            ON gth.PHAM_NHAN_ID = p.pn_id
           AND NVL(gth.IS_DELETED, 0) = 0
    )
    SELECT
        v_skip + ROW_NUMBER() OVER (ORDER BY ORDER_HOTEN(p.HO_TEN)) AS STT,
        p.SO_HSLD,
        p.HO_TEN,
        p.THA_NGAY_HET_HAN AS NGAY_HET_HAN,
        CAST(NVL(ttpn.TTPN_TEN, u'') AS NVARCHAR2(500)) AS TINH_TRANG,
        TO_CHAR(p.NGAY_PHAN_LOAI, 'DD/MM/YYYY') AS NGAY_PHAN_LOAI,
        CAST(NVL(mpl.MPL_TEN, u'')      AS NVARCHAR2(500)) AS LOAI_QUYET_DINH,
        CAST(NVL(tu_plgg.PLGG_TEN, u'') AS NVARCHAR2(500)) AS TU_LOAI,
        CAST(NVL(den_plgg.PLGG_TEN,u'') AS NVARCHAR2(500)) AS DEN_LOAI,
        mtg_trai.MTG_TITLE  AS TRAI_DN,
        mtg_cap.MTG_TITLE   AS CAP_TREN_DUYET,
        mtg_toa.MTG_TITLE   AS TOA_QD,
        ca.total_count       AS TOTAL_COUNT
    FROM page_b p
    CROSS JOIN cnt_agg ca
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS ttpn
        ON ttpn.ID = p.LL_TINH_TRANG_ID AND NVL(ttpn.IS_DELETED,0) = 0
    LEFT JOIN DM_MA_PHAN_LOAIES mpl
        ON mpl.ID = p.LOAI_PHAN_LOAI_ID AND NVL(mpl.IS_DELETED,0) = 0
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS tu_plgg
        ON tu_plgg.ID = p.TU_LOAI_ID    AND NVL(tu_plgg.IS_DELETED,0) = 0
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS den_plgg
        ON den_plgg.ID = p.DEN_LOAI_ID  AND NVL(den_plgg.IS_DELETED,0) = 0
    LEFT JOIN gth_one gth
        ON gth.PHAM_NHAN_ID = p.pn_id
    LEFT JOIN DM_MA_THOI_GIANS mtg_trai
        ON mtg_trai.MTG_MA = gth.MUC_DE_NGHI_ID  AND NVL(mtg_trai.IS_DELETED,0) = 0
    LEFT JOIN DM_MA_THOI_GIANS mtg_cap
        ON mtg_cap.MTG_MA  = gth.CAP_TREN_DUYET_ID AND NVL(mtg_cap.IS_DELETED,0) = 0
    LEFT JOIN DM_MA_THOI_GIANS mtg_toa
        ON mtg_toa.MTG_MA  = gth.MUC_GIAM_ID      AND NVL(mtg_toa.IS_DELETED,0) = 0
      ;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, u'L\1ed7i khi l\1ea5y danh s\00e1ch ph\00e2n lo\1ea1i: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_PHAN_LOAI;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PN_CHAP_HANH_DUOC_12_34_MUC_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PN_CHAP_HANH_DUOC_12_34_MUC_AN" (
	p_ma_trai_giam 	   IN  NVARCHAR2    DEFAULT NULL,
    p_den_ngay         IN  VARCHAR2  DEFAULT NULL,
    p_muc_chap_hanh    IN  NUMBER  DEFAULT NULL,
    p_phan_doi_id      IN  NUMBER    DEFAULT NULL,
    p_phan_trai_id     IN  NUMBER    DEFAULT NULL,  -- phan trai hien tai, NULL=tat ca
    p_maxresultcount   IN  NUMBER    DEFAULT NULL,
    --p_pn_ids IN NVARCHAR2 DEFAULT NULL,
    p_skipcount        IN  NUMBER    DEFAULT NULL
)
AS
    v_den_ngay DATE;
    v_muc      VARCHAR2(20);
    v_skip     NUMBER;
    v_limit    NUMBER;
    c1         SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);

    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := TRUNC(SYSDATE);
    ELSE
        v_den_ngay := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
    END IF;

--    v_muc := UPPER(TRIM(NVL(p_muc_chap_hanh, '')));
--    IF v_muc IS NULL OR v_muc = '' THEN
--        v_muc := 'ALL';
--    END IF;

    OPEN c1 FOR
    WITH
--    ID_LIST AS (
--            SELECT DISTINCT TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
--            FROM DUAL
--            CONNECT BY LEVEL <= CASE
--                    WHEN p_pn_ids IS NULL THEN 0
--                    WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
--                    ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
--                END
--              AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
--              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
--    ),    
    tha_one AS (
        SELECT /*+ MATERIALIZE */
            tha_pnlai_lich_id,
            tha_so_ban_an,
            tha_ngay_bat,
            tha_ngay_den_trai,
            tha_ngay_het_han,
            tha_an_phat 
        FROM QLPN.PN_THI_HANH_AN
        WHERE NVL(is_deleted, 0) = 0
    ),

    base AS (
        SELECT
            vw.PHAM_NHAN_ID AS pn_lai_lich_id,
            vw.SO_HO_SO,
            vw.CCCD,
            vw.HO_TEN,
            vw.HO_TEN_ORDER,
            vw.NGAY_SINH,
            vw.NAM_SINH,
            vw.GIOI_TINH,
            vw.NOI_THUONG_TRU_DAY_DU,
            vw.TOI_DANH,
            vw.AN_PHAT,
            vw.SO_TIEN_AN,
            vw.NGAY_BAT_AN_PHAT AS vw_ngay_bat,
            vw.PHAN_DOI AS phan_doi_ten,
            vw.PHAN_TRAI AS phan_trai_ten,
            t.tha_ngay_bat,
            t.tha_ngay_den_trai,
            t.tha_ngay_het_han,
            t.tha_an_phat AS tha_an_phat
        FROM QLPN.VW_PN_LAI_LICH_CHI_TIET vw
        INNER JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
                ON ttpn.ID = vw.LL_TINH_TRANG_ID
               AND NVL(ttpn.IS_DELETED, 0) = 0
               AND ttpn.TTPN_MA IN ('111', '112', '113', '114')  -- ?ang ch?p hành án
        LEFT JOIN tha_one t ON t.tha_pnlai_lich_id = vw.PHAM_NHAN_ID --AND t.rn = 1
        WHERE NVL(vw.IS_DELETED, 0) = 0
         AND (p_ma_trai_giam IS NULL OR vw.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam))
          AND EXISTS (
                SELECT 1
                FROM QLPN.PN_THI_HANH_AN tha
                WHERE NVL(tha.is_deleted, 0) = 0
                  AND tha.tha_pnlai_lich_id = vw.PHAM_NHAN_ID
                  AND tha.tha_pnlai_lich_id IS NOT NULL
--                  AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
--                  AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) <= v_den_ngay
--                  AND (tha.tha_ngay_het_han IS NULL OR tha.tha_ngay_het_han >= v_den_ngay)
          )
          AND (p_phan_doi_id IS NULL OR vw.PHAN_DOI_ID = p_phan_doi_id)
          AND (
                p_muc_chap_hanh IS NULL
             OR (p_muc_chap_hanh = 1
                 AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_TY_LE(vw.PHAM_NHAN_ID, 0.5, v_den_ngay) = 1)
             OR (p_muc_chap_hanh = 2
                 AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_TY_LE(vw.PHAM_NHAN_ID, 1 / 3, v_den_ngay) = 1)
             OR (p_muc_chap_hanh = 3
                 AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_TY_LE(vw.PHAM_NHAN_ID, 0.25, v_den_ngay) = 1)
             OR (p_muc_chap_hanh = 4
                 AND EXISTS (
                     SELECT 1
                     FROM QLPN.PN_THI_HANH_AN tha_ct
                     WHERE NVL(tha_ct.is_deleted, 0) = 0
                       AND tha_ct.tha_pnlai_lich_id = vw.PHAM_NHAN_ID
                        AND THA_MA_AN_PHAT IN ('911000','912000','921000','922000') 
--                       AND UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(tha_ct.tha_an_phat), u'')))
--                           LIKE '%' || 'CHUNGTHAN' || '%'
                 )
                 AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_SO_NAM(vw.PHAM_NHAN_ID, 12, v_den_ngay) = 1
                 AND NVL(PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_SO_NAM(vw.PHAM_NHAN_ID, 14, v_den_ngay), 0) = 0)
             OR (p_muc_chap_hanh = 5
                 AND EXISTS (
                     SELECT 1
                     FROM QLPN.PN_THI_HANH_AN tha_ct
                     WHERE NVL(tha_ct.is_deleted, 0) = 0
                       AND tha_ct.tha_pnlai_lich_id = vw.PHAM_NHAN_ID
                        AND THA_MA_AN_PHAT IN ('911000','912000','921000','922000') 
--                       AND UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(tha_ct.tha_an_phat), u'')))
--                           LIKE '%' || 'CHUNGTHAN' || '%'
                 )
                 AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_SO_NAM(vw.PHAM_NHAN_ID, 14, v_den_ngay) = 1)
          )
    )
 SELECT
        --ROW_NUMBER() OVER (ORDER BY b.HO_TEN NULLS LAST, b.pn_lai_lich_id) AS STT,
        COUNT(1) OVER() AS total_count,
        b.SO_HO_SO                   AS SO_HSLD,
        b.HO_TEN                                   AS HO_TEN,
        b.NAM_SINH                                            AS NAM_SINH,
        b.GIOI_TINH                                AS GIOI_TINH,
        b.NOI_THUONG_TRU_DAY_DU                     AS NOI_DKTT,
        b.TOI_DANH                                 AS TOI_DANH,
        TO_CHAR(b.tha_ngay_bat, 'DD/MM/YYYY')      AS NGAY_BAT,
        NVL(b.tha_an_phat, b.AN_PHAT)                         AS AN_PHAT,
        CASE
            WHEN b.tha_ngay_den_trai IS NULL THEN NULL
            ELSE TO_CHAR(b.tha_ngay_den_trai, 'DD/MM/YYYY')
        END                                                   AS NGAY_DEN_TRAI,
        NVL(PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(b.pn_lai_lich_id), u'Kh\00f4ng') AS DA_GIAM,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(b.pn_lai_lich_id, v_den_ngay), u'') AS DA_CHAP_HANH,
--        CASE
--            WHEN UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(b.tha_an_phat), u'')))
--                     LIKE '%' || 'CHUNGTHAN' || '%'
--                 OR UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(b.AN_PHAT), u'')))
--                     LIKE '%' || 'CHUNGTHAN' || '%'
--            THEN u'Chung th\00e2n'
--            ELSE NVL(
--                PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(b.pn_lai_lich_id, v_den_ngay),
--                u''
--            )
--        END                                                   AS CON_LAI,
        NVL(
                PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(b.pn_lai_lich_id, v_den_ngay),
                u''
            ) AS CON_LAI,
        TO_CHAR(b.tha_ngay_het_han, 'DD/MM/YYYY')        AS NGAY_HET_HAN,
        NVL(TRIM(CAST(b.phan_doi_ten AS NVARCHAR2(500))), u'')
            || CASE
                WHEN TRIM(NVL(CAST(b.phan_doi_ten AS NVARCHAR2(500)), u'')) IS NOT NULL
                 AND LENGTH(TRIM(NVL(CAST(b.phan_doi_ten AS NVARCHAR2(500)), u''))) > 0
                 AND TRIM(NVL(CAST(b.phan_trai_ten AS NVARCHAR2(500)), u'')) IS NOT NULL
                 AND LENGTH(TRIM(NVL(CAST(b.phan_trai_ten AS NVARCHAR2(500)), u''))) > 0
                THEN u', '
                ELSE u''
               END
            || NVL(TRIM(CAST(b.phan_trai_ten AS NVARCHAR2(500))), u'') AS PHAN_DOI

    FROM base b
    --where (p_pn_ids IS NULL OR b.pn_lai_lich_id IN (SELECT PN_ID FROM ID_LIST))
    --ORDER BY b.HO_TEN NULLS LAST, b.pn_lai_lich_id;
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L?i khi l?y danh sách ch?p hành ??t 1/2 ho?c 3/4 m?c án: ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_PN_CHAP_HANH_DUOC_12_34_MUC_AN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PN_CHUA_BENH_BAT_BUOC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PN_CHUA_BENH_BAT_BUOC" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay          IN  VARCHAR2  DEFAULT NULL,
    p_den_ngay         IN  VARCHAR2  DEFAULT NULL,
    p_tinh_trang_id    IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id      IN  NUMBER    DEFAULT NULL,
    p_maxresultcount   IN  NUMBER    DEFAULT NULL,
    p_skipcount        IN  NUMBER    DEFAULT NULL
) AS
    v_tu_ngay   DATE;
    v_den_ngay  DATE;
    v_filter_tt NUMBER; -- 1 = l?c theo kho?ng ngày tr?n
    v_skip      NUMBER;
    v_limit     NUMBER;
    c1          SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY'));
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
    END IF;

    --v_filter_tt := CASE WHEN v_tu_ngay IS NOT NULL OR v_den_ngay IS NOT NULL THEN 1 ELSE 0 END;

    OPEN c1 FOR
    WITH
    cbbb_base AS (
        SELECT
			c.*,
			ll.LL_DM_GIOI_TINH_ID, 
			TO_CHAR(ptha.THA_NGAY_BAT, 'DD/MM/YYYY') AS NGAY_BAT 
        FROM QLPN.CHUA_BENH_BAT_BUOCS c
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.id = c.PHAM_NHAN_ID
           AND NVL(ll.is_deleted, 0) = 0
         LEFT JOIN QLPN.PN_THI_HANH_AN ptha
         	ON ptha.THA_PNLAI_LICH_ID = ll.ID
        WHERE NVL(c.IS_DELETED, 0) = 0
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
               AND (v_tu_ngay IS NULL OR TRUNC(NGAY_BAT_DAU) >= v_tu_ngay)
            AND (v_den_ngay IS NULL OR TRUNC(NGAY_BAT_DAU) <= v_den_ngay)
--          AND (
--              v_filter_tt = 0
--              OR EXISTS (
--                  SELECT 1
--                  FROM QLPN.TRON_TRAIS tt
--                  WHERE NVL(tt.IS_DELETED, 0) = 0
--                    AND tt.PHAM_NHAN_ID = c.PHAM_NHAN_ID
--                    AND tt.NGAY_TRON IS NOT NULL
--                    AND (v_tu_ngay IS NULL OR TRUNC(tt.NGAY_TRON) >= v_tu_ngay)
--                    AND (v_den_ngay IS NULL OR TRUNC(tt.NGAY_TRON) <= v_den_ngay)
--              )
--          )
    ),
    pn_scope AS (
        SELECT DISTINCT c.PHAM_NHAN_ID AS pn_id
        FROM cbbb_base c
    ),
    vw_dedup AS (
        SELECT
            v.*,
            ROW_NUMBER() OVER (PARTITION BY v.PHAM_NHAN_ID ORDER BY v.HO_TEN) AS rn_vw
        FROM pn_scope p
        INNER JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = p.pn_id
           AND NVL(v.IS_DELETED, 0) = 0
    ),
    result_rows AS (
        SELECT
            c.TU_NGAY AS TU_NGAY_SORT,
            c.ID AS CBBB_ID,
            v.SO_HO_SO AS SO_HSLD,
            v.HO_TEN,
            c.NGAY_BAT,
            v.NAM_SINH,
            gt.GT_TEN AS GIOI_TINH,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            v.TOI_DANH,
            v.AN_PHAT,
            v.NGAY_DEN_TRAI,
            v.NGAY_HET_AN AS NGAY_HET_HAN,
--            CASE
--                WHEN c.TU_NGAY IS NOT NULL THEN
--                    TO_CHAR(c.TU_NGAY, 'DD/MM/YYYY HH24:MI') -- Format nao day
--                ELSE NULL
--            END AS TU_NGAY,
            TO_CHAR(c.TU_NGAY, 'DD/mm/yyyy') AS TU_NGAY,
            CASE
                WHEN dmtg.ID IS NOT NULL THEN CAST(dmtg.MTG_TITLE AS NVARCHAR2(500))
                WHEN c.THOI_HAN IS NOT NULL AND LENGTH(TRIM(CAST(c.THOI_HAN AS VARCHAR2(100)))) > 0
                THEN CAST(TRIM(CAST(c.THOI_HAN AS VARCHAR2(500))) AS NVARCHAR2(500))
                ELSE u'Kh\00f4ng'
            END AS THOI_HAN_HIEN_THI,
            NVL(CAST(dbt.NNC_TEN AS NVARCHAR2(500)), CAST(NVL(c.CHI_TIET_BENH, '') AS NVARCHAR2(500))) AS BENH_TAT,
            CAST(c.NGAY_BAT_DAU AS DATE) AS NGAY_BAT_DAU,
            CAST(c.NGAY_KET_THUC AS DATE) AS NGAY_KET_THUC,
            NVL(CAST(dmttpn.TTPN_TEN AS NVARCHAR2(500)), u'') AS TINH_TRANG,
            NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
            NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
        FROM cbbb_base c
        INNER JOIN vw_dedup v
            ON v.PHAM_NHAN_ID = c.PHAM_NHAN_ID
           AND v.rn_vw = 1
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg
--            ON REGEXP_LIKE(TRIM(CAST(c.THOI_HAN AS VARCHAR2(100))), '^[0-9]+$')
--           AND dmtg.ID = TO_NUMBER(TRIM(CAST(c.THOI_HAN AS VARCHAR2(100))))
           ON c.THOI_HAN = dmtg.MTG_TITLE
           AND NVL(dmtg.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
        	ON gt.ID = c.LL_DM_GIOI_TINH_ID
        LEFT JOIN QLPN.DM_NGUYEN_NHAN_CHETS dbt
            ON dbt.ID = c.BENH_TAT_ID
           AND NVL(dbt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS dmttpn
            ON v.LL_TINH_TRANG_ID = dmttpn.ID
           AND NVL(dmttpn.IS_DELETED, 0) = 0
        WHERE 1=1
        --and FN_GET_TINH_TRANG_TAI_NGAY_XET(v.PHAM_NHAN_ID,v_den_ngay )   = '113'
        --and (p_tinh_trang_id IS NULL OR v.LL_TINH_TRANG_ID = p_tinh_trang_id)
        and (p_tinh_trang_id IS NULL 
        OR (p_tinh_trang_id = 1 AND (NGAY_KET_THUC IS NOT NULL AND NGAY_KET_THUC <= SYSTIMESTAMP  ))
        OR (p_tinh_trang_id = 2 AND (NGAY_KET_THUC IS NULL OR NGAY_KET_THUC > SYSTIMESTAMP ))
        OR (p_tinh_trang_id = 3 AND THOI_HAN NOT IN ('000000') AND NGAY_KET_THUC IS NULL AND ((
    ADD_MONTHS(
        TU_NGAY,
          NVL(TO_NUMBER(REGEXP_SUBSTR(dmtg.MTG_TITLE, '(\d+)\s*n?m', 1, 1, NULL, 1)), 0) * 12
        + NVL(TO_NUMBER(REGEXP_SUBSTR(dmtg.MTG_TITLE, '(\d+)\s*tháng', 1, 1, NULL, 1)), 0)
    )
    +
    NVL(TO_NUMBER(REGEXP_SUBSTR(dmtg.MTG_TITLE, '(\d+)\s*ngày', 1, 1, NULL, 1)), 0)
)
< SYSDATE)
        )
        )
        AND (p_ma_trai_giam IS NULL OR (TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
    )
    SELECT
        r.SO_HSLD,
        r.HO_TEN,
        r.NAM_SINH,
        r.NOI_DKTT,
        r.GIOI_TINH,
        r.TOI_DANH,
        r.AN_PHAT,
        TO_CHAR(r.NGAY_DEN_TRAI, 'DD/mm/yyyy') AS NGAY_DEN_TRAI,
        TO_CHAR(r.NGAY_HET_HAN, 'DD/mm/yyyy') AS NGAY_HET_HAN,
        r.NGAY_BAT,
		r.TU_NGAY AS TU_NGAY,
        r.THOI_HAN_HIEN_THI,
        r.BENH_TAT,
        TO_CHAR(r.NGAY_BAT_DAU, 'DD/mm/yyyy') AS NGAY_BAT_DAU,
        TO_CHAR(r.NGAY_KET_THUC, 'DD/mm/yyyy') AS NGAY_KET_THUC,
        r.TINH_TRANG,
        r.PHAN_DOI,
        COUNT(*) OVER () AS TOTAL_COUNT
    FROM result_rows r
    ORDER BY ORDER_HOTEN(r.HO_TEN), r.TU_NGAY_SORT   NULLS LAST, r.CBBB_ID
    OFFSET v_skip ROWS
    FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i khi l\1ea5y danh s\00e1ch ph\1ea1m nh\00e2n ch\1eefa b\1ec7nh b\1eaft bu\1ed9c: ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_PN_CHUA_BENH_BAT_BUOC;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PN_CHUYEN_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PN_CHUYEN_TRAI" (
 p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay              IN  VARCHAR2  DEFAULT NULL,
    p_den_ngay             IN  VARCHAR2  DEFAULT NULL,
    p_truong_hop_chuyen_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id          IN  NUMBER    DEFAULT NULL,
    p_maxresultcount       IN  NUMBER    DEFAULT NULL,
    p_skipcount            IN  NUMBER    DEFAULT NULL
) AS
    v_tu_ngay   DATE;
    v_den_ngay  DATE;
    v_skip      NUMBER;
    v_limit     NUMBER;
    c1          SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY'));
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
    END IF;

    OPEN c1 FOR
    WITH
    ct_base AS (
        SELECT pct.*
        FROM QLPN.PHAM_NHAN_CHUYEN_TRAI pct
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.id = pct.PNCT_LAI_LICH_ID
           AND NVL(ll.is_deleted, 0) = 0
        WHERE NVL(pct.IS_DELETED, 0) = 0
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (p_truong_hop_chuyen_id IS NULL OR pct.PNCT_TRUONG_HOP_CHUYEN_ID = p_truong_hop_chuyen_id)
         AND (p_ma_trai_giam IS NULL OR ( LL_TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
          AND (
              (v_tu_ngay IS NULL AND v_den_ngay IS NULL)
              OR (
                  pct.PNCT_NGAY_CHUYEN IS NOT NULL
                  AND (v_tu_ngay IS NULL OR  pct.PNCT_NGAY_CHUYEN  >= v_tu_ngay)
                  AND (v_den_ngay IS NULL OR  pct.PNCT_NGAY_CHUYEN  <= v_den_ngay)
              )
          )
    ),
    pn_scope AS (
        SELECT DISTINCT c.PNCT_LAI_LICH_ID AS pn_id
        FROM ct_base c
    ),
    vw_dedup AS (
        SELECT
            v.*,
            ROW_NUMBER() OVER (PARTITION BY v.PHAM_NHAN_ID ORDER BY v.HO_TEN) AS rn_vw
        FROM pn_scope p
        INNER JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = p.pn_id
           AND NVL(v.IS_DELETED, 0) = 0
    ),
    result_rows AS (
        SELECT
            c.ID AS CT_ID,
            c.PNCT_NGAY_CHUYEN AS NGAY_CHUYEN_SORT,
            v.SO_HO_SO,
            v.HO_TEN,
            HO_TEN_ORDER,
            v.NAM_SINH,
            v.GIOI_TINH,
            v.NOI_THUONG_TRU_DAY_DU AS THUONG_TRU,
            v.TOI_DANH,
            v.NGAY_BAT_AN_PHAT NGAY_BAT,
            v.AN_PHAT,
            v.NGAY_DEN_TRAI,
            thct.THCT_TEN AS TRUONG_HOP_CHUYEN,
            --NULL AS TRAI_DI, -- NULL Thi?u c?t
            --NVL(CAST(tg_di.TG_TEN AS NVARCHAR2(500)), u'') AS TRAI_DI,
            NVL(CAST(tg.MHT_TEN AS NVARCHAR2(500)), u'') AS TRAI_DI,
            CAST(c.PNCT_SO_QDDIEU_CHUYEN AS NVARCHAR2(500)) AS SO_QD,
            CAST(c.PNCT_NGAY_QDCHUYEN AS DATE) AS NGAY_QD,
            CAST(c.PNCT_NGAY_CHUYEN AS DATE) AS NGAY_CHUYEN,
            NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
            NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI,
            --NVL(CAST(tg.TG_TEN AS NVARCHAR2(500)), u'') AS TRAI_CHUYEN_DEN
            CO_QUAN_BAT AS TRAI_CHUYEN_DEN
        FROM ct_base c
        LEFT JOIN QLPN.DM_TRUONG_HOP_CHUYEN_TRAIS thct
        ON thct.id = c.PNCT_TRUONG_HOP_CHUYEN_ID
        INNER JOIN vw_dedup v
            ON v.PHAM_NHAN_ID = c.PNCT_LAI_LICH_ID
           AND v.rn_vw = 1
        LEFT JOIN QLPN.DM_MA_HIEU_TRAIES tg
            ON tg.ID = c.PNCT_TRAI_DEN_ID
           AND NVL(tg.IS_DELETED, 0) = 0
           LEFT JOIN QLPN.DM_TRAI_GIAMS tg_di
            ON tg_di.ID = v.TRAI_GIAM_ID
           AND NVL(tg_di.IS_DELETED, 0) = 0   
           WHERE   (p_ma_trai_giam IS NULL OR ( TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
    )
    SELECT
        r.SO_HO_SO,
        r.HO_TEN,
        r.NAM_SINH,
        r.GIOI_TINH,
        r.THUONG_TRU,
        r.TOI_DANH,
        TO_CHAR(r.NGAY_BAT, 'DD/MM/YYYY')   AS  NGAY_BAT,
        r.AN_PHAT,
        TO_CHAR(r.NGAY_DEN_TRAI, 'DD/MM/YYYY')   AS  NGAY_DEN_TRAI,
        --(select TSHT_GIA_TRI from THAM_SO_HE_THONGS where TSHT_THAM_SO = 'DON_VI') as TRAI_DI,
        TRAI_DI,
        r.TRUONG_HOP_CHUYEN,
        r.SO_QD,
        TO_CHAR(r.NGAY_QD, 'DD/MM/YYYY')   AS  NGAY_QD,
        TO_CHAR(r.NGAY_CHUYEN, 'DD/MM/YYYY')   AS  NGAY_CHUYEN,
        r.PHAN_DOI,
        r.TRAI_CHUYEN_DEN,
        COUNT(*) OVER () AS TOTAL_COUNT
    FROM result_rows r
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i khi l\1ea5y danh s\00e1ch chuy\1ec3n tr\1ea1i: ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_PN_CHUYEN_TRAI;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PN_CO_TIEN_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PN_CO_TIEN_AN" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
