--        GROUP BY pta.PNTA_LAI_LICH_ID
--    ),
--    -- PN ?ang ch?p hành án + có ti?n án (>= 1 b?n ghi PN_TIEN_AN ho?c LL_SO_TIEN_AN > 0)
--    dang_chap_hanh_co_ta AS (
