/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PN_DAC_XA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PN_DAC_XA" (
p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay        IN  VARCHAR2 DEFAULT NULL,
    p_den_ngay       IN  VARCHAR2 DEFAULT NULL,
    p_phan_doi_id    IN  NUMBER   DEFAULT NULL,
    p_ho_ten         IN  NVARCHAR2 DEFAULT NULL,
    p_maxresultcount IN  NUMBER   DEFAULT NULL,
    p_skipcount      IN  NUMBER   DEFAULT NULL
) AS
    v_tu_ngay   DATE;
    v_den_ngay  DATE;
    v_like_hoten  VARCHAR2(4000);
    v_skip      NUMBER;
    v_limit     NUMBER;
    v_like      VARCHAR2(4000);
    c1          SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY'));
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
    END IF;

--    IF p_ho_ten IS NOT NULL AND LENGTH(TRIM(p_ho_ten)) > 0 THEN
--        v_like := '%' || UPPER(TRIM(p_ho_ten)) || '%';
--    ELSE
--        v_like := NULL;
--    END IF;
    IF p_ho_ten IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ho_ten))) > 0 THEN
        v_like_hoten := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ho_ten, u''))))) || '%';
    ELSE
        v_like_hoten := NULL;
    END IF;

    OPEN c1 FOR
    WITH
    pdx_base AS (
        SELECT pdx.*
        FROM QLPN.PN_DAC_XAS pdx
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.id = pdx.PNLAI_LICH_ID
           AND NVL(ll.is_deleted, 0) = 0
        WHERE NVL(pdx.IS_DELETED, 0) = 0
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
           AND (p_ma_trai_giam IS NULL OR ( LL_TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))          
          AND (
              (v_tu_ngay IS NULL AND v_den_ngay IS NULL)
              OR (
                  pdx.DX_NGAY_XET IS NOT NULL
                  AND (v_tu_ngay IS NULL OR pdx.DX_NGAY_XET >= v_tu_ngay)
                  AND (v_den_ngay IS NULL OR pdx.DX_NGAY_XET <= v_den_ngay)
              )
          )
    ),
    pn_scope AS (
        SELECT DISTINCT b.PNLAI_LICH_ID AS pn_id
        FROM pdx_base b
    ),
    vw_dedup AS (
        SELECT
            v.*,
            ROW_NUMBER() OVER (PARTITION BY v.PHAM_NHAN_ID ORDER BY v.HO_TEN) AS rn_vw
        FROM pn_scope p
        INNER JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = p.pn_id
           AND NVL(v.IS_DELETED, 0) = 0
    ),
    result_rows AS (
        SELECT
            pdx.ID AS PDX_ID,
            pdx.DX_NGAY_XET AS NGAY_XET_SORT,
            v.SO_HO_SO, 
            v.HO_TEN,        
            v.GIOI_TINH,
            v.NAM_SINH,
            NVL(CAST(v.QUOC_TICH AS NVARCHAR2(500)), u'') AS QUOC_TICH,
            v.NOI_THUONG_TRU_DAY_DU,
            RTRIM(
                NVL2(
                    NULLIF(TRIM(CAST(v.NOI_THA_VE_CU_TRU AS NVARCHAR2(2000))), u''),
                    TRIM(CAST(v.NOI_THA_VE_CU_TRU AS NVARCHAR2(2000))) || u', ',
                    u''
                ) ||
                NVL2(
                    NULLIF(TRIM(CAST(v.NOI_THA_VE_CU_TRU_XA AS NVARCHAR2(500))), u''),
                    TRIM(CAST(v.NOI_THA_VE_CU_TRU_XA AS NVARCHAR2(500))) || u', ',
                    u''
                ) ||
                NVL(TRIM(CAST(v.NOI_THA_VE_CU_TRU_TINH AS NVARCHAR2(500))), u''),
                u', '
            ) AS DIA_CHI_VE,
            NVL(CAST(v.TOI_DANH AS NVARCHAR2(2000)), u'') AS TOI_DANH,
            CAST(v.NGAY_BAT_AN_PHAT AS DATE) AS NGAY_BAT,
            NVL(CAST(v.AN_PHAT AS NVARCHAR2(2000)), u'') AS AN_PHAT,
            v.NGAY_DEN_TRAI,
            CAST(pdx.DX_NGAY_XET AS DATE) AS NGAY_XET,
            CAST(pdx.DX_NGAY_THA AS DATE) AS NGAY_THA,
            CAST(pdx.DX_NGAY_TRINH_DIEN AS DATE) AS NGAY_TRINH_DIEN,
            NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
            NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI,
            COUNT(*) OVER () AS TOTAL_COUNT
        FROM pdx_base pdx
        INNER JOIN vw_dedup v
            ON v.PHAM_NHAN_ID = pdx.PNLAI_LICH_ID
           AND v.rn_vw = 1
        WHERE (v_like IS NULL
           OR UPPER(TRIM(CAST(v.HO_TEN AS VARCHAR2(4000)))) LIKE v_like)
           AND (p_ma_trai_giam IS NULL OR ( TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
            AND (v_like_hoten IS NULL OR SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(v.HO_TEN)), 1, 400) LIKE v_like_hoten)
    )
    SELECT
        r.SO_HO_SO,
        r.HO_TEN,
        r.GIOI_TINH,
        r.NAM_SINH,
        r.QUOC_TICH,
        r.NOI_THUONG_TRU_DAY_DU,
        r.DIA_CHI_VE,
        r.TOI_DANH,
        --r.NGAY_BAT,
        TO_CHAR(r.NGAY_BAT, 'DD/mm/yyyy') AS NGAY_BAT,
        r.AN_PHAT,
        TO_CHAR(r.NGAY_DEN_TRAI, 'DD/mm/yyyy') AS NGAY_DEN_TRAI,
        --r.NGAY_DEN_TRAI,
       -- r.NGAY_XET,
        TO_CHAR(r.NGAY_XET, 'DD/mm/yyyy') AS NGAY_XET,
       -- r.NGAY_THA,
        TO_CHAR(r.NGAY_THA, 'DD/mm/yyyy') AS NGAY_THA,
        --r.NGAY_TRINH_DIEN,
        TO_CHAR(r.NGAY_TRINH_DIEN, 'DD/mm/yyyy') AS NGAY_TRINH_DIEN,
        r.PHAN_DOI,
         TOTAL_COUNT
    FROM result_rows r
    ORDER BY ORDER_HOTEN(r.HO_TEN) NULLS LAST--,r.NGAY_XET_SORT DESC NULLS LAST, r.PDX_ID DESC
    OFFSET v_skip ROWS
    FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i khi l\1ea5y danh s\00e1ch \0111\1eb7c x\00e1: ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_PN_DAC_XA;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PN_DANG_CHAP_HANH_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PN_DANG_CHAP_HANH_AN" (
    p_phan_doi_id     IN  NUMBER    DEFAULT NULL,
    p_tu_ngay         IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_den_ngay        IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_gioi_tinh_id  IN  NUMBER    DEFAULT NULL,
    p_quoc_tich_id  IN  NUMBER    DEFAULT NULL,
    p_maxresultcount  IN  NUMBER    DEFAULT NULL,
    p_skipcount       IN  NUMBER    DEFAULT 0
) AS
    v_skip      NUMBER;
    v_limit     NUMBER;
    v_tu_ngay   DATE;
    v_den_ngay  DATE;
    c1          SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    -- Parse ngày
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := TRUNC(SYSDATE);
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
        WITH
        -- PN ?ang ch?p hành án t?i ngày v_den_ngay: có THA hi?u l?c (ngày b?t <= den_ngay, ngày h?t >= den_ngay)
    tha_hieu_luc AS (
        SELECT tha.tha_pnlai_lich_id AS pn_id
        FROM PN_THI_HANH_AN tha
        WHERE NVL(tha.is_deleted, 0) = 0
          AND tha.tha_pnlai_lich_id IS NOT NULL
          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) <= v_den_ngay
          AND (tha.tha_ngay_het_han IS NULL OR tha.tha_ngay_het_han >= v_den_ngay)
    ),
    tha_den_trai AS (
        SELECT tha.tha_pnlai_lich_id AS pn_id,
               tha.tha_ngay_den_trai AS ngay_den_trai,
               ROW_NUMBER() OVER (PARTITION BY tha.tha_pnlai_lich_id ORDER BY tha.tha_ngay_den_trai DESC NULLS LAST) AS rn
        FROM PN_THI_HANH_AN tha
        WHERE NVL(tha.is_deleted, 0) = 0
          AND tha.tha_pnlai_lich_id IN (SELECT pn_id FROM tha_hieu_luc)
    )
    SELECT * FROM (
        SELECT 
            --ROW_NUMBER() OVER (ORDER BY LL.LL_HO_TEN) AS rn_all,
            ROW_NUMBER() OVER (ORDER BY  ORDER_HOTEN(LL.LL_HO_TEN) NULLS LAST) AS rn_all,
            COUNT(*) OVER() AS total_count,

            ll.LL_SO_HO_SO_LAN_DAU AS SO_HO_SO,
             ll.LL_CCCD AS CCCD,
            ll.LL_HO_TEN AS HO_TEN,
           ll.LL_NGAY_SINH AS NGAY_SINH,
            gt.GT_TEN AS GIOI_TINH,
               CASE
        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
          OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
        THEN TRIM(
            NVL(NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u''), u'')
            || CASE
                WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                            THEN u', ' || dxp_thuong_tru.XP_TEN
                        ELSE dxp_thuong_tru.XP_TEN
                    END
                ELSE u''
               END
            || CASE
                WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                            THEN u', ' || dttp_thuong_tru.TTP_TEN
                        ELSE dttp_thuong_tru.TTP_TEN
                    END
                ELSE u''
               END
        )
        ELSE NULL
    END AS  DIA_CHI_THUONG_TRU,
            td.TOI_DANH AS TOI_DANH,
            --td.THA_NGAY_DEN_TRAI AS NGAY_DEN_TRAI,
     TO_CHAR(td.THA_NGAY_DEN_TRAI, 'DD/mm/yyyy') AS NGAY_DEN_TRAI,
            CASE
                WHEN NULLIF(TRIM(CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(ll.ID) AS VARCHAR2(100))), '0') IS NULL
                THEN u'Không'
                ELSE CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(ll.id) AS NVARCHAR2(2000))
            END AS THOI_GIAN_DA_GIAM,

            ptha.THA_THOI_GIAN_DA_CHAP_HANH AS DA_CHAP_HANH,
            ptha.THA_THOI_GIAN_CON_LAI AS CON_LAI,

            --td.THA_NGAY_HET_HAN  AS NGAY_HET_AN,
      TO_CHAR(td.THA_NGAY_HET_HAN, 'DD/mm/yyyy') AS NGAY_HET_AN,      
            --td.THA_NGAY_BAN_AN AS NGAY_BAT,
            TO_CHAR(td.THA_NGAY_BAN_AN, 'DD/mm/yyyy') AS NGAY_BAT,  
             td.THA_AN_PHAT AS AN_PHAT,
           --pd.PD_TEN AS PHAN_DOI
	        -- PHAN_DOI: phân ??i, phân tr?i
	        NVL(TRIM(CAST(pd.PD_TEN AS VARCHAR2(4000))), '') ||
	        CASE WHEN pd.PD_TEN IS NOT NULL AND pt.PT_TEN IS NOT NULL THEN u', ' ELSE u'' END ||
	        NVL(TRIM(CAST(pt.PT_TEN AS VARCHAR2(4000))), '') AS PHAN_DOI
        FROM PN_LAI_LICHS ll
         INNER JOIN tha_hieu_luc t ON t.pn_id = ll.id
        LEFT JOIN tha_den_trai tdt ON tdt.pn_id = ll.id AND tdt.rn = 1
        inner JOIN PN_THI_HANH_AN ptha 
            ON ll.ID = ptha.THA_PNLAI_LICH_ID
            LEFT JOIN V_PN_THI_HANH_AN_TOI_DANH td 
    ON ll.ID = td.THA_PNLAI_LICH_ID 
-- Join v?i b?ng danh m?c Gi?i tính
        LEFT JOIN DM_GIOI_TINHS gt 
            ON ll.LL_DM_GIOI_TINH_ID = gt.ID 
            AND gt.IS_DELETED = 0
    LEFT JOIN DM_PHAN_DOIS pd
    ON ll.ll_phan_doi_id = pd.ID
    AND pd.IS_DELETED = 0 
   LEFT JOIN DM_XA_PHUONG dxp_thuong_tru 
    ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID 
    AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0 
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru 
    ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID 
    AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
LEFT JOIN DM_PHAN_TRAIS pt
    ON ll.ll_phan_trai_id = pt.ID
    AND pt.IS_DELETED = 0
        WHERE 1=1
            AND (v_tu_ngay IS NULL OR TRUNC(td.THA_NGAY_DEN_TRAI) >= TRUNC(v_tu_ngay))
            AND (v_den_ngay IS NULL OR TRUNC(td.THA_NGAY_DEN_TRAI) <= TRUNC(v_den_ngay))
            AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
            AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
            AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
            AND ptha.IS_DELETED = 0

    )
    WHERE rn_all > v_skip
      AND (v_limit = 0 OR rn_all <= v_skip + v_limit)
    ORDER BY rn_all;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 
            'L?i khi l?y danh sách PN lai l?ch chi ti?t: ' || SQLERRM);
END;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PN_DANG_CHAP_HANH_THEO_TON_GIAO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PN_DANG_CHAP_HANH_THEO_TON_GIAO" (
--    p_PHAM_NHAN_ID IN  VARCHAR2 DEFAULT NULL,
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay      IN  VARCHAR2 DEFAULT NULL,
    p_den_ngay     IN  VARCHAR2 DEFAULT NULL,
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id IN  NUMBER    DEFAULT NULL,
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT 0         
) AS

    v_skip  NUMBER;
    v_limit NUMBER;
    v_den_ngay DATE;
    v_tu_ngay  DATE;
    c1         SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
--    WITH
--    -- PN ?ang ch?p hành án t?i ngày v_den_ngay: có THA hi?u l?c
--    tha_hieu_luc AS (
--        SELECT tha.tha_pnlai_lich_id AS pn_id
--        FROM PN_THI_HANH_AN tha
--        WHERE NVL(tha.is_deleted, 0) = 0
--          AND tha.tha_pnlai_lich_id IS NOT NULL
--          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
--          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) <= v_den_ngay
--          AND (tha.tha_ngay_het_han IS NULL OR tha.tha_ngay_het_han >= v_den_ngay)
--    ),
--    tha_den_trai AS (
--        SELECT tha.tha_pnlai_lich_id AS pn_id,
--               tha.tha_ngay_den_trai AS ngay_den_trai,
--               ROW_NUMBER() OVER (PARTITION BY tha.tha_pnlai_lich_id ORDER BY tha.tha_ngay_den_trai DESC NULLS LAST) AS rn
--        FROM PN_THI_HANH_AN tha
--        WHERE NVL(tha.is_deleted, 0) = 0
--          AND tha.tha_pnlai_lich_id IN (SELECT pn_id FROM tha_hieu_luc)
--    ),
--    -- M?t LL m?i nh?t m?i PN (tránh dup t? VW_PN_LAI_LICH_CHI_TIET)
--    LL_one AS (
--        SELECT * FROM (
--            SELECT v.*, ROW_NUMBER() OVER (PARTITION BY v.PHAM_NHAN_ID
--                ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
--                         v.CREATION_TIME DESC NULLS LAST) AS rn
--            FROM VW_PN_LAI_LICH_CHI_TIET v
--            WHERE NVL(v.IS_DELETED, 0) = 0
--        ) x WHERE rn = 1
--    ),
--    -- PN ?ang ch?p hành án (có THA hi?u l?c)
--    dang_chap_hanh AS (
--        SELECT ll.PHAM_NHAN_ID AS pn_lai_lich_id
--        FROM LL_one ll
--        INNER JOIN tha_hieu_luc t ON t.pn_id = ll.PHAM_NHAN_ID
--        LEFT JOIN tha_den_trai td ON td.pn_id = ll.PHAM_NHAN_ID AND td.rn = 1
--        WHERE  1 =1 
----        and (p_PHAM_NHAN_ID IS NULL OR TRIM(NVL(p_PHAM_NHAN_ID, '')) = ''
----               OR (',' || REPLACE(REPLACE(REPLACE(TRIM(NVL(p_PHAM_NHAN_ID, '')), ' ', ''), '[', ''), ']', '') || ',')
----                   LIKE '%,' || TO_CHAR(ll.PHAM_NHAN_ID) || ',%')
--          AND (v_tu_ngay IS NULL OR (td.ngay_den_trai IS NOT NULL AND TRUNC(td.ngay_den_trai) >= v_tu_ngay))
--    )
    SELECT * FROM (    
    SELECT
        --ROW_NUMBER() OVER (ORDER BY v.TON_GIAO, v.HO_TEN) AS rn_all,
        --ROW_NUMBER() OVER (ORDER BY   ORDER_HOTEN(v.HO_TEN) NULLS LAST) AS rn_all,
        COUNT(*) OVER() AS total_count,       
        v.SO_HO_SO                    AS SO_HSLD,
        v.HO_TEN                      AS HO_TEN,
        v.NGAY_SINH                   AS NS,
        v.GIOI_TINH                   AS GT,
        v.NOI_THUONG_TRU_DAY_DU       AS NOI_DKTT,
        NVL(CAST(v.TON_GIAO AS VARCHAR2(4000)), '') AS TON_GIAO,
        v.TOI_DANH                    AS TOI_DANH,
        --v.NGAY_BAT_AN_PHAT            AS NGAY_BAT,
        TO_CHAR(v.NGAY_BAT_AN_PHAT , 'DD/mm/yyyy') AS NGAY_BAT,
        v.AN_PHAT                     AS AN_PHAT,
        --v.NGAY_DEN_TRAI               AS NGAY_DEN_TRAI,
        TO_CHAR(v.NGAY_DEN_TRAI , 'DD/mm/yyyy') AS NGAY_DEN_TRAI,
        --v.NGAY_HET_AN                 AS NGAY_HET_HAN,
        TO_CHAR(v.NGAY_HET_AN , 'DD/mm/yyyy') AS NGAY_HET_HAN,
        -- Th?i gian ?ã gi?m, ?ã ch?p hành, còn l?i: dùng PKG_TINH_AN (không dùng FN_GET_*_THEO_NGAY)
--        CASE
--            WHEN NULLIF(TRIM(CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(v.PHAM_NHAN_ID) AS VARCHAR2(100))), '0') IS NULL
--            THEN u'Kh\00f4ng'
--            ELSE CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(v.PHAM_NHAN_ID) AS NVARCHAR2(2000))
--        END                            AS THOI_GIAN_DA_GIAM,
--      CASE
--            WHEN v.THOI_GIAN_DA_GIAM is null or v.THOI_GIAN_DA_GIAM = 0   
--            THEN u'Kh\00f4ng'
--            ELSE v.THOI_GIAN_DA_GIAM
--        END                            AS THOI_GIAN_DA_GIAM,
        v.THOI_GIAN_DA_GIAM,
        --NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(v.PHAM_NHAN_ID, v_den_ngay), u'') AS THOI_GIAN_DA_CHAP_HANH,
        v.THOI_GIAN_DA_CHAP_HANH TG_DA_CHAP_HANH,
       -- NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(v.PHAM_NHAN_ID, v_den_ngay), u'') AS THOI_GIAN_CON_LAI,
        v.THOI_GIAN_CON_LAI TG_CON_LAI,
        dmttpn.TTPN_TEN                AS TINH_TRANG,
        -- PHAN_DOI: phân ??i, phân tr?i
        NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
        NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
    FROM   VW_PN_LAI_LICH_CHI_TIET v 
--    INNER JOIN PN_THI_HANH_AN ptha 
--    ON v.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn
        ON v.LL_TINH_TRANG_ID = dmttpn.ID
       AND NVL(dmttpn.IS_DELETED, 0) = 0
    where 1 =1 
    and v.TON_GIAO is not null
--    AND ptha.IS_DELETED = 0
      AND (v_tu_ngay IS NULL OR (ngay_den_trai IS NOT NULL AND ngay_den_trai >= v_tu_ngay))
      AND (v_den_ngay IS NULL OR (ngay_den_trai IS NOT NULL AND ngay_den_trai <= v_den_ngay))
        --AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_MA = p_ma_trai_giam)
       AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))        
        AND (p_tinh_trang_id IS NULL OR dmttpn.ID = p_tinh_trang_id)
        AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)
    --ORDER BY v.TON_GIAO, v.HO_TEN
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
    )  ;       

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân ?ang ch?p hành theo tôn giáo: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_PN_DANG_CHAP_HANH_THEO_TON_GIAO;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PN_GIAM_RIENG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PN_GIAM_RIENG" (
p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay        IN VARCHAR2 DEFAULT NULL,
    p_den_ngay       IN VARCHAR2 DEFAULT NULL,
    p_loai_qd        IN VARCHAR2 DEFAULT NULL,
    p_tinh_trang     IN NUMBER   DEFAULT NULL,
    p_phan_doi_id    IN NUMBER   DEFAULT NULL,
    p_maxresultcount IN NUMBER   DEFAULT NULL,
    p_skipcount      IN NUMBER   DEFAULT NULL
) AS
    v_tu_ngay DATE;
    v_den_ngay DATE;
    v_skip     NUMBER;
    v_limit    NUMBER;
    v_filter_ngay NUMBER;
    c1         SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY'));
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
    END IF;
    v_filter_ngay := CASE WHEN v_tu_ngay IS NOT NULL OR v_den_ngay IS NOT NULL THEN 1 ELSE 0 END;

    OPEN c1 FOR
    WITH
    gr_base AS (
        SELECT gr.*, ttpn_ten
        FROM QLPN.PN_GIAM_RIENGS gr
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.id = gr.GR_PN_LAI_LICH_ID
           AND NVL(ll.is_deleted, 0) = 0
        LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn ON ll.LL_TINH_TRANG_ID = dmttpn.ID AND NVL(dmttpn.IS_DELETED, 0) = 0
        WHERE NVL(gr.IS_DELETED, 0) = 0
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (p_ma_trai_giam IS NULL OR ( LL_TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
          --AND (p_loai_qd IS NULL OR TRIM(p_loai_qd) = '' OR TO_NUMBER(TRIM(gr.GR_LOAI_QUYET_DINH)) = TRIM(p_loai_qd))
          AND (p_loai_qd IS NULL OR p_loai_qd = gr.GR_LOAI_QUYET_DINH)
--          AND (
--              p_tinh_trang IS NULL
--              OR (p_tinh_trang = 1 AND (
--                      gr.GR_NGAY_KETTHUC IS NULL
--                      OR TRUNC(gr.GR_NGAY_KETTHUC) >= TRUNC(SYSDATE)
--                  ))
--              OR (p_tinh_trang = 2 AND (
--                      gr.GR_NGAY_KETTHUC IS NOT NULL
--                      AND TRUNC(gr.GR_NGAY_KETTHUC) < TRUNC(SYSDATE)
--                  ))
--          )        
         AND (p_tinh_trang IS NULL OR  dmttpn.ID = p_tinh_trang)
          AND (
              v_filter_ngay = 0
              OR (gr.GR_NGAY_BAT_DAU IS NOT NULL
                AND (v_tu_ngay IS NULL
                     OR TRUNC(gr.GR_NGAY_BAT_DAU) >= TRUNC(v_tu_ngay))
                AND (v_den_ngay IS NULL
                     OR TRUNC(gr.GR_NGAY_BAT_DAU) <= TRUNC(v_den_ngay))
              )
          )
    ),
    pn_scope AS (
        SELECT DISTINCT g.GR_PN_LAI_LICH_ID AS pn_id
        FROM gr_base g
    ),
    vw_dedup AS (
        SELECT
            v.*,
            ROW_NUMBER() OVER (PARTITION BY v.PHAM_NHAN_ID ORDER BY v.HO_TEN) AS rn_vw
        FROM pn_scope p
        INNER JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = p.pn_id
           AND NVL(v.IS_DELETED, 0) = 0
    ),
    result_rows AS (
        SELECT
            g.ID AS GR_ID,
            COALESCE(g.GR_NGAY_BAT_DAU, g.GR_NGAY_QUYET_DINH_GIAM_RIENG) AS NGAY_LOC_SORT,
            v.SO_HO_SO AS SO_HSLD,
            v.CCCD,
            v.HO_TEN,
            v.NGAY_SINH,
            v.GIOI_TINH,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            v.TOI_DANH,
            v.NGAY_BAT_AN_PHAT,
            v.AN_PHAT,
            v.NGAY_DEN_TRAI,
            CAST(v.NGAY_HET_AN AS DATE) AS NGAY_HET_HAN,
            --CAST(g.GR_SO_QUYET_DINH_GIAM_RIENG AS NVARCHAR2(500)) AS SO_QD,
            g.GR_SO_QUYET_DINH_GIAM_RIENG AS SO_QD,
            CAST(g.GR_NGAY_QUYET_DINH_GIAM_RIENG AS DATE) AS NGAY_QD,
--            CASE
--                WHEN dmtg.ID IS NOT NULL THEN CAST(dmtg.MTG_TITLE AS NVARCHAR2(500))
--                WHEN g.GR_THOI_HAN_GIAM_RIENG IS NOT NULL
--                     AND LENGTH(TRIM(CAST(g.GR_THOI_HAN_GIAM_RIENG AS VARCHAR2(100)))) > 0
--                THEN CAST(TRIM(CAST(g.GR_THOI_HAN_GIAM_RIENG AS VARCHAR2(500))) AS NVARCHAR2(500))
--                ELSE u''
--            END AS THOI_HAN_HIEN_THI,
            dmtg.MTG_TITLE as THOI_HAN_HIEN_THI,
--            NVL(
--                NULLIF(TRIM(CAST(g.GR_CHI_TIET_LY_DO AS NVARCHAR2(2000))), u''),
--                CAST(NVL(g.GR_LY_DO, '') AS NVARCHAR2(2000))
--            ) AS LY_DO_GIAM_RIENG,
            LDGRPN_TEN AS LY_DO_GIAM_RIENG,
            CAST(g.GR_NGAY_BAT_DAU AS DATE) AS NGAY_BAT_DAU,
            CAST(g.GR_NGAY_KETTHUC AS DATE) AS NGAY_KET_THUC,
--            CASE
--                WHEN g.GR_NGAY_KETTHUC IS NULL THEN u'\0110ang giam ri\00eang'
--                WHEN TRUNC(g.GR_NGAY_KETTHUC) >= TRUNC(SYSDATE) THEN u'\0110ang giam ri\00eang'
--                ELSE u'\0110\00e3 k\1ebft th\00fac'
--            END AS TINH_TRANG,
         ttpn_ten TINH_TRANG,
            NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
            NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
        FROM gr_base g
        INNER JOIN vw_dedup v
            ON v.PHAM_NHAN_ID = g.GR_PN_LAI_LICH_ID
           AND v.rn_vw = 1
--        LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg
--            ON NVL(dmtg.IS_DELETED, 0) = 0
--            and g.GR_THOI_HAN_GIAM_RIENG = dmtg.ID 
--            left join DM_LY_DO_GIAM_RIENG_PHAM_NHANS ldgr on ldgr.id = GR_LY_DO
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg
            ON NVL(dmtg.IS_DELETED, 0) = 0
           AND REGEXP_LIKE(TRIM(g.GR_THOI_HAN_GIAM_RIENG), '^\d+$')
           AND dmtg.MTG_MA = TO_NUMBER(TRIM(g.GR_THOI_HAN_GIAM_RIENG))

        LEFT JOIN DM_LY_DO_GIAM_RIENG_PHAM_NHANS ldgr
            ON REGEXP_LIKE(TRIM(g.GR_LY_DO), '^\d+$')
           AND ldgr.ID = TO_NUMBER(TRIM(g.GR_LY_DO))
--           AND (
--                (REGEXP_LIKE(TRIM(CAST(g.GR_THOI_HAN_GIAM_RIENG AS VARCHAR2(100))), '^[0-9]+$')
--                 AND dmtg.ID = TO_NUMBER(TRIM(CAST(g.GR_THOI_HAN_GIAM_RIENG AS VARCHAR2(100)))))
--                OR TRIM(dmtg.MTG_MA) = TRIM(CAST(g.GR_THOI_HAN_GIAM_RIENG AS VARCHAR2(100)))
--               )
        WHERE (p_ma_trai_giam IS NULL OR ( TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))   
    )
    SELECT
        r.SO_HSLD,
        r.CCCD,
        r.HO_TEN,
        r.NGAY_SINH,
        r.GIOI_TINH,
        r.NOI_DKTT,
        r.TOI_DANH,
        --r.NGAY_BAT_AN_PHAT,
        TO_CHAR(r.NGAY_BAT_AN_PHAT , 'DD/mm/yyyy') AS NGAY_BAT_AN_PHAT,
        r.AN_PHAT,
        --r.NGAY_DEN_TRAI,
        TO_CHAR(r.NGAY_DEN_TRAI , 'DD/mm/yyyy') AS NGAY_DEN_TRAI,
        --r.NGAY_HET_HAN,
        TO_CHAR(r.NGAY_HET_HAN , 'DD/mm/yyyy') AS NGAY_HET_HAN,
        r.SO_QD,
        --r.NGAY_QD,
        TO_CHAR(r.NGAY_QD , 'DD/mm/yyyy') AS NGAY_QD,
        r.THOI_HAN_HIEN_THI,
        r.LY_DO_GIAM_RIENG,
        --r.NGAY_BAT_DAU,
        TO_CHAR(r.NGAY_BAT_DAU , 'DD/mm/yyyy') AS NGAY_BAT_DAU,
        --r.NGAY_KET_THUC,
        TO_CHAR(r.NGAY_KET_THUC , 'DD/mm/yyyy') AS NGAY_KET_THUC,
        r.TINH_TRANG,
        r.PHAN_DOI,
        COUNT(*) OVER () AS TOTAL_COUNT
    FROM result_rows r
    ORDER BY REGEXP_SUBSTR(r.HO_TEN, '[^ ]+$') DESC NULLS LAST,r.NGAY_LOC_SORT DESC NULLS LAST, r.GR_ID DESC
    OFFSET v_skip ROWS
    FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i khi l\1ea5y danh s\00e1ch giam ri\00eang: ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_PN_GIAM_RIENG;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PN_HOAN_THI_HANH_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PN_HOAN_THI_HANH_AN" (
p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay        IN VARCHAR2 DEFAULT NULL,
    p_den_ngay       IN VARCHAR2 DEFAULT NULL,
    p_phan_doi_id    IN NUMBER   DEFAULT NULL,
    p_maxresultcount IN NUMBER   DEFAULT NULL,
    p_skipcount      IN NUMBER   DEFAULT NULL
) AS
    v_tu_ngay DATE;
    v_den_ngay DATE;
    v_skip     NUMBER;
    v_limit    NUMBER;
    v_filter_ngay NUMBER;
    c1         SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY'));
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
    END IF;
    v_filter_ngay := CASE WHEN v_tu_ngay IS NOT NULL OR v_den_ngay IS NOT NULL THEN 1 ELSE 0 END;

    OPEN c1 FOR
    WITH
    h_base AS (
        SELECT h.*
        FROM QLPN.HOAN_THI_HANH_ANS h
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.id = h.PHAM_NHAN_ID
           AND NVL(ll.is_deleted, 0) = 0
        WHERE NVL(h.IS_DELETED, 0) = 0
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (
              v_filter_ngay = 0
              OR (
                  h.NGAY_QUYET_DINH IS NOT NULL
                  AND (v_tu_ngay IS NULL OR TRUNC(h.NGAY_QUYET_DINH) >= v_tu_ngay)
                  AND (v_den_ngay IS NULL OR TRUNC(h.NGAY_QUYET_DINH) <= v_den_ngay)
              )
          )
    ),
    pn_scope AS (
        SELECT DISTINCT x.PHAM_NHAN_ID AS pn_id
        FROM h_base x
    ),
    vw_dedup AS (
        SELECT
            v.*,
            ROW_NUMBER() OVER (PARTITION BY v.PHAM_NHAN_ID ORDER BY v.HO_TEN) AS rn_vw
        FROM pn_scope p
        INNER JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = p.pn_id
           AND NVL(v.IS_DELETED, 0) = 0
    ),
    result_rows AS (
        SELECT
            h.ID AS H_ID,
            TRUNC(h.NGAY_QUYET_DINH) AS NGAY_QD_SORT,
            v.SO_HO_SO AS SO_HSLD,
            v.HO_TEN,
            v.NAM_SINH,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            v.TOI_DANH,
            --v.NGAY_DEN_TRAI,
            TO_CHAR(v.NGAY_DEN_TRAI , 'DD/mm/yyyy') AS NGAY_DEN_TRAI,
            v.GIOI_TINH,
            --CAST(v.NGAY_BAT_AN_PHAT AS DATE) AS NGAY_BAT,
            TO_CHAR(v.NGAY_BAT_AN_PHAT , 'DD/mm/yyyy') AS NGAY_BAT,
            v.AN_PHAT,
            CAST(h.SO_QUYET_DINH AS NVARCHAR2(500)) AS SO_QD,
            --CAST(h.NGAY_QUYET_DINH AS DATE) AS NGAY_QD,
            TO_CHAR(h.NGAY_QUYET_DINH , 'DD/mm/yyyy') AS NGAY_QD,
            NVL(CAST(h.LY_DO_HOAN AS NVARCHAR2(2000)), u'') AS LY_DO_HOAN,
            --CAST(h.NGAY_THI_HANH_AN AS DATE) AS NGAY_THI_HANH,
            TO_CHAR(h.NGAY_THI_HANH_AN , 'DD/mm/yyyy') AS NGAY_THI_HANH,
            NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
            NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI,
            COUNT(*) OVER () AS TOTAL_COUNT
        FROM h_base h
        INNER JOIN vw_dedup v
            ON v.PHAM_NHAN_ID = h.PHAM_NHAN_ID
           AND v.rn_vw = 1
        WHERE (p_ma_trai_giam IS NULL OR ( TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam))) 
    )
    SELECT
        ROW_NUMBER() OVER (ORDER BY   ORDER_HOTEN(r.HO_TEN) NULLS LAST) AS rn_all,
         COUNT(*) OVER() AS total_count,
        r.SO_HSLD,
        r.HO_TEN,
        r.GIOI_TINH,
        r.NAM_SINH,
        r.NOI_DKTT,
        r.TOI_DANH,
        r.NGAY_BAT,
        r.AN_PHAT,
        r.NGAY_DEN_TRAI,
        r.SO_QD,
        r.NGAY_QD,
        r.LY_DO_HOAN,
        r.NGAY_THI_HANH,
        r.PHAN_DOI
    FROM result_rows r
    ORDER BY ORDER_HOTEN(r.HO_TEN) NULLS LAST--,r.NGAY_QD_SORT DESC NULLS LAST, r.H_ID DESC
    OFFSET v_skip ROWS
    FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i khi l\1ea5y danh s\00e1ch ho\00e3n thi h\00e0nh \00e1n: ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_PN_HOAN_THI_HANH_AN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PN_HPBS_PHAT_TIEN_LTTLT07
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PN_HPBS_PHAT_TIEN_LTTLT07" (
p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay            IN VARCHAR2 DEFAULT NULL,
    p_den_ngay           IN VARCHAR2 DEFAULT NULL,
    p_tinh_trang_id      IN NUMBER   DEFAULT NULL,
    p_phan_doi_id        IN NUMBER   DEFAULT NULL,
    p_noi_nop_id         IN NUMBER   DEFAULT NULL,
    p_maxresultcount     IN NUMBER   DEFAULT NULL,
    p_skipcount          IN NUMBER   DEFAULT NULL
) AS
    v_tu_ngay    DATE;
    v_den_ngay   DATE;
    --v_ref_ngay   DATE;
    v_skip       NUMBER;
    v_limit      NUMBER;
    c1           SYS_REFCURSOR;
BEGIN
    v_skip := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

--    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
--        v_tu_ngay := NULL;
--    ELSE
--        v_tu_ngay := TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY'));
--    END IF;
--
--    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
--        v_den_ngay := NULL;
--    ELSE
--        v_den_ngay := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
--    END IF;
--
--    v_ref_ngay := NVL(v_den_ngay, TRUNC(SYSDATE));
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
    WITH
    hp_phat_tien AS (
        SELECT
            hp.ID AS hpbs_id,
            hp.HPBS_MA_PHAM_NHAN AS pn_id,
            NVL(hp.HPBS_TONG_TIEN_PHAT, 0) AS phai_nop,
            NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0) AS chua_nop
        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
        INNER JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
            ON dm.ID = hp.HPBS_HINH_PHAT
           AND NVL(dm.IS_DELETED, 0) = 0
           --AND dm.HPBS_MA in ( '220', '211', '210')
           AND dm.HPBS_LOAI_HPBS = 'HPBST'
        WHERE NVL(hp.IS_DELETED, 0) = 0
          AND hp.HPBS_MA_PHAM_NHAN IS NOT NULL
    ),
    vw_one AS (
        SELECT *
        FROM VW_PN_LAI_LICH_CHI_TIET
    ),
    dang_chap_hanh AS (
        SELECT tha.THA_PNLAI_LICH_ID AS pn_id
        FROM QLPN.PN_THI_HANH_AN tha
        WHERE NVL(tha.IS_DELETED, 0) = 0
    ),
    bl_for_agg AS (
        SELECT
            bl.HPBS_ID,
            bl.BL_NGAY_NOP,
            bl.BL_SO_TIEN
        FROM QLPN.PN_BIENLAIES bl
        WHERE NVL(bl.IS_DELETED, 0) = 0
          AND bl.BL_NGAY_NOP IS NOT NULL
          AND (v_tu_ngay IS NULL OR TRUNC(bl.BL_NGAY_NOP) >= TRUNC(v_tu_ngay))
          AND (v_den_ngay IS NULL OR TRUNC(bl.BL_NGAY_NOP) <= TRUNC(v_den_ngay))
          AND (p_noi_nop_id IS NULL OR bl.BL_NOP_TAI_CO_QUAN = p_noi_nop_id)
    ),
base AS (
    SELECT
        h.hpbs_id,
        h.pn_id,
        h.phai_nop,
        h.chua_nop,
        ba.BL_NGAY_NOP,
        ba.BL_SO_TIEN AS da_nop
    FROM hp_phat_tien h
    INNER JOIN vw_one v ON v.PHAM_NHAN_ID = h.pn_id
    LEFT JOIN bl_for_agg ba ON ba.HPBS_ID = h.hpbs_id
    WHERE (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)
     -- AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_MA = p_ma_trai_giam)
     AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))
      AND (p_tinh_trang_id IS NULL OR v.LL_TINH_TRANG_ID = p_tinh_trang_id)
      AND (
            (v_tu_ngay IS NULL AND v_den_ngay IS NULL AND p_noi_nop_id IS NULL)
            OR ba.HPBS_ID IS NOT NULL
          )
),
    ordered AS (
        SELECT
            b.hpbs_id,
            TRUNC(CAST(v.NGAY_DEN_TRAI AS DATE)) AS ngay_den_sort,
            CAST(b.BL_NGAY_NOP AS DATE) AS ngay_nop_sort,
            v.SO_HO_SO,
            v.NGAY_SINH,
            v.HO_TEN,
            v.NAM_SINH,
            v.GIOI_TINH,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            v.TOI_DANH,
TO_CHAR(v.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT_AN_PHAT,
v.AN_PHAT,
TO_CHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
TO_CHAR(v.NGAY_HET_AN, 'DD/MM/YYYY') AS NGAY_HET_HAN,
TO_CHAR(b.BL_NGAY_NOP, 'DD/MM/YYYY') AS NGAY_NOP,
            b.phai_nop AS PHAI_NOP,
            b.da_nop AS DA_NOP,
            b.chua_nop AS CHUA_NOP,
            c.ttpn_ten tinh_trang,
            --v.PHAN_DOI,
	        NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
	        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
	        NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI,            
            THA_SO_BAN_AN,
--TO_CHAR(THA_NGAY_BAT, 'DD/MM/YYYY') AS NGAY_XU,
--THA_GHI_CHU_DAC_BIET AS TOA_XU,
--THA_SO_DE_NGHI AS SO_QUYET_DINH,
--THA_GHI_CHU_DAC_BIET AS NGAY_QUYET_DINH,
--THA_GHI_CHU_DAC_BIET AS TOA_QUYET_DINH
        TO_CHAR(THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS NGAY_XU,
        dcqct.CQ_TEN AS TOA_XU,
        THA_SO_QD_THA AS SO_QUYET_DINH,
        TO_CHAR(THA_NGAY_QD_THA, 'DD/MM/YYYY') AS  NGAY_QUYET_DINH,
        dcqtqd.CQ_TEN AS TOA_QUYET_DINH
        FROM base b
        INNER JOIN vw_one v ON v.PHAM_NHAN_ID = b.pn_id
        left join  DM_TINH_TRANG_PHAM_NHANS c on V.LL_TINH_TRANG_ID = C.ID
        left join  PN_THI_HANH_AN PTHA ON PTHA.THA_PNLAI_LICH_ID = v.PHAM_NHAN_ID AND PTHA.IS_DELETED = 0
        left join DM_CO_QUANS dcqct on dcqct.ID = THA_CAP_TOA_ID
        left join DM_CO_QUANS dcqtqd on dcqtqd.ID = THA_TOA_QD_ID
    )
    SELECT
        v_skip + ROW_NUMBER() OVER (
            ORDER BY q.ngay_nop_sort DESC NULLS LAST,
                     q.ngay_den_sort DESC NULLS LAST,
                     q.HO_TEN,
                     q.hpbs_id
        ) AS STT,
        q.SO_HO_SO,
        q.HO_TEN,
        q.NGAY_SINH,
        q.NAM_SINH,
        q.GIOI_TINH,
        q.NOI_DKTT,
        q.TOI_DANH,
        q.NGAY_BAT_AN_PHAT,
        q.AN_PHAT,
        q.NGAY_DEN_TRAI,
        q.NGAY_HET_HAN,
        q.NGAY_NOP,
        q.PHAI_NOP,
        q.DA_NOP,
        q.CHUA_NOP,
        q.tinh_trang,
        q.PHAN_DOI,
         THA_SO_BAN_AN,
              NGAY_XU,
              TOA_XU,
              SO_QUYET_DINH,
              NGAY_QUYET_DINH,
              TOA_QUYET_DINH,
        COUNT(*) OVER () AS total_count

    FROM (
        SELECT o.*
        FROM ordered o
        ORDER BY
        ORDER_HOTEN(o.HO_TEN)
--        REGEXP_SUBSTR(o.HO_TEN, '[^ ]+$') DESC NULLS LAST,
--            o.ngay_nop_sort DESC NULLS LAST,
--            o.ngay_den_sort DESC NULLS LAST,
--            o.HO_TEN,
--            o.hpbs_id
        OFFSET v_skip ROWS
        FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY
    ) q;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i khi l\1ea5y danh s\00e1ch ph\1ea1t ti\1ec1n HPBS (TTLT 07): ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_PN_HPBS_PHAT_TIEN_LTTLT07;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_PN_TOI_ANQG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_PN_TOI_ANQG" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay      IN  VARCHAR2  DEFAULT NULL,
    p_den_ngay     IN  VARCHAR2  DEFAULT NULL,
    p_tinh_trang_id IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id IN  NUMBER    DEFAULT NULL,
    p_maxresultcount IN  NUMBER    DEFAULT 25,
    p_skipcount      IN  NUMBER    DEFAULT 0      
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_den_ngay DATE;
    v_tu_ngay  DATE;
    c1         SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := TRUNC(SYSDATE);
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN c1 FOR
    WITH
    -- PN ?ang ch?p hành án t?i ngày v_den_ngay: có THA hi?u l?c
    tha_hieu_luc AS (
        SELECT tha.tha_pnlai_lich_id AS pn_id
        FROM PN_THI_HANH_AN tha
        WHERE NVL(tha.is_deleted, 0) = 0
          AND tha.tha_pnlai_lich_id IS NOT NULL
          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) <= v_den_ngay
          AND (tha.tha_ngay_het_han IS NULL OR tha.tha_ngay_het_han >= v_den_ngay)
    ),
    tha_den_trai AS (
        SELECT tha.tha_pnlai_lich_id AS pn_id,
               tha.tha_ngay_den_trai AS ngay_den_trai,
               ROW_NUMBER() OVER (PARTITION BY tha.tha_pnlai_lich_id ORDER BY tha.tha_ngay_den_trai DESC NULLS LAST) AS rn
        FROM PN_THI_HANH_AN tha
        WHERE NVL(tha.is_deleted, 0) = 0
          AND tha.tha_pnlai_lich_id IN (SELECT pn_id FROM tha_hieu_luc)
    ),
    -- PN ?ang ch?p hành án + t?i ch??ng 13 (ANQG): map TOI_DANH_ID ? DM_TOI_DANHS.TD_CHUONG
    dang_chap_hanh_anqg AS (
        SELECT ll.id AS pn_lai_lich_id
        FROM PN_LAI_LICHS ll
        INNER JOIN tha_hieu_luc t ON t.pn_id = ll.id
        LEFT JOIN tha_den_trai td ON td.pn_id = ll.id AND td.rn = 1
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = ll.id
           AND NVL(v.IS_DELETED, 0) = 0
        LEFT JOIN DM_TOI_DANHS dm
            ON dm.ID = TO_NUMBER(REGEXP_SUBSTR(NVL(TRIM(CAST(v.TOI_DANH_ID AS VARCHAR2(4000))), ''), '[0-9]+', 1, 1))
           AND NVL(dm.IS_DELETED, 0) = 0
        WHERE NVL(ll.is_deleted, 0) = 0
          --AND (p_ma_trai_giam IS NULL OR ll.ll_trai_giam_id = p_ma_trai_giam)
         AND (p_ma_trai_giam IS NULL OR ( ll.ll_trai_giam_id = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))            
          AND (v_tu_ngay IS NULL OR (td.ngay_den_trai IS NOT NULL AND td.ngay_den_trai >= v_tu_ngay))
          -- T?i ch??ng 13: An ninh qu?c gia (fallback: td_chuong NULL + TOI_DANH ch?a ANQG/AN NINH)
          AND  TRIM(CAST(NVL(dm.TD_CHUONG, '') AS VARCHAR2(10))) = '13'

    )
    SELECT * FROM (

    SELECT
        ---ROW_NUMBER() OVER (ORDER BY v.HO_TEN) AS rn_all,
        --ROW_NUMBER() OVER (ORDER BY   ORDER_HOTEN(v.HO_TEN) NULLS LAST) AS rn_all,
        COUNT(*) OVER() AS total_count,      
        v.SO_HO_SO                    AS SO_HSLD,
        v.HO_TEN                      AS HO_TEN,
        v.NGAY_SINH                   AS NS,
        v.GIOI_TINH                   AS GT,
        v.NOI_THUONG_TRU_DAY_DU       AS NOI_DKTT,
        v.TOI_DANH                    AS TOI_DANH,
        --v.NGAY_BAT_AN_PHAT            AS NGAY_BAT,
        TO_CHAR(v.NGAY_BAT_AN_PHAT , 'DD/mm/yyyy') AS NGAY_BAT,
        v.AN_PHAT                     AS AN_PHAT,
        --v.NGAY_DEN_TRAI               AS NGAY_DEN_TRAI,
        TO_CHAR(v.NGAY_DEN_TRAI , 'DD/mm/yyyy') AS NGAY_DEN_TRAI,
        --v.NGAY_HET_AN                 AS NGAY_HET_HAN,
        TO_CHAR(v.NGAY_HET_AN , 'DD/mm/yyyy') AS NGAY_HET_HAN,
        CASE
            WHEN NULLIF(TRIM(CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(v.PHAM_NHAN_ID) AS VARCHAR2(100))), '0') IS NULL
            THEN u'Kh\00f4ng'
            ELSE CAST(PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(v.PHAM_NHAN_ID) AS NVARCHAR2(2000))
        END                            AS THOI_GIAN_DA_GIAM,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(v.PHAM_NHAN_ID), u'') AS THOI_GIAN_DA_CHAP_HANH,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(v.PHAM_NHAN_ID), u'') AS THOI_GIAN_CON_LAI,
        dmttpn.TTPN_TEN                AS TINH_TRANG,
        -- PHAN_DOI: phân ??i, phân tr?i
        NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
        NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
    FROM dang_chap_hanh_anqg d
    INNER JOIN VW_PN_LAI_LICH_CHI_TIET v
        ON v.PHAM_NHAN_ID = d.pn_lai_lich_id
       AND NVL(v.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn
        ON v.LL_TINH_TRANG_ID = dmttpn.ID
       AND NVL(dmttpn.IS_DELETED, 0) = 0
    WHERE 1 = 1
    AND (p_tinh_trang_id IS NULL OR dmttpn.ID = p_tinh_trang_id)
    AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)
    --ORDER BY v.HO_TEN
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
    )
--     WHERE  rn_all > v_skip
--    AND (v_limit = 0 OR rn_all <= v_skip + v_limit)
--    ORDER BY rn_all 
    ; 

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân t?i ANQG ?ang ch?p hành án: ' || SQLERRM);
END SP_GET_BAO_CAO_DS_PN_TOI_ANQG;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_THAM_GAP
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_THAM_GAP" (
    p_tu_ngay            IN VARCHAR2 DEFAULT NULL,
    p_den_ngay           IN VARCHAR2 DEFAULT NULL,
    p_tinh_trang_id      IN NUMBER   DEFAULT NULL,
    p_phan_doi_id        IN NUMBER   DEFAULT NULL,
    p_maxresultcount     IN NUMBER   DEFAULT NULL,
    p_skipcount          IN NUMBER   DEFAULT NULL
) AS
    v_tu_ngay     DATE;
    v_den_ngay    DATE;
    v_skip        NUMBER;
    v_limit       NUMBER;
    v_filter_ngay NUMBER;
    c1            SYS_REFCURSOR;
BEGIN
    v_skip := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
    END IF;

    v_filter_ngay := CASE WHEN v_tu_ngay IS NOT NULL OR v_den_ngay IS NOT NULL THEN 1 ELSE 0 END;

    OPEN c1 FOR
    WITH
    oll_one AS (
        SELECT *
        FROM (
            SELECT
                o.*,
                ROW_NUMBER() OVER (
                    PARTITION BY o.PN_ID
                    ORDER BY o.SO_HSLD
                ) AS rn_oll
            FROM QLPN_OLD.PN_LAI_LICH o
        ) z
        WHERE rn_oll = 1
    ),
    base_join AS (
        SELECT
            tg.NGAY_THAM,
            tg.HO_TEN_NGUOI_THAM,
            tg.TU_THOI_GIAN,
            tg.DEN_THOI_GIAN,
            tg.PN_ID AS old_pn_id,
            ll.ID AS pn_lai_lich_id
        FROM QLPN_OLD.PN_THAM_GAP tg
        INNER JOIN oll_one oll
            ON oll.PN_ID = tg.PN_ID
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.LL_SO_HO_SO_LAN_DAU = oll.SO_HSLD
           AND NVL(ll.is_deleted, 0) = 0
        WHERE (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (
              v_filter_ngay = 0
              OR (
                  tg.NGAY_THAM IS NOT NULL
                  AND (v_tu_ngay IS NULL OR TRUNC(tg.NGAY_THAM) >= v_tu_ngay)
                  AND (v_den_ngay IS NULL OR TRUNC(tg.NGAY_THAM) <= v_den_ngay)
              )
          )
    ),
    vw_one AS (
        SELECT *
        FROM (
            SELECT
                v.*,
                ROW_NUMBER() OVER (
                    PARTITION BY v.PHAM_NHAN_ID
                    ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
                             v.CREATION_TIME DESC NULLS LAST
                ) AS rn_vw
            FROM QLPN.VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
        ) x
        WHERE rn_vw = 1
    ),
    result_rows AS (
        SELECT
            TRUNC(CAST(b.NGAY_THAM AS DATE)) AS ngay_tham_sort,
            b.old_pn_id,
            CAST(NVL(TRIM(b.HO_TEN_NGUOI_THAM), u'') AS NVARCHAR2(500)) AS HO_TEN_NGUOI_THAM_RAW,
            b.TU_THOI_GIAN,
            b.DEN_THOI_GIAN,
            CAST(v.SO_HO_SO AS NVARCHAR2(100)) AS SO_HSLD,
            v.HO_TEN,
            CAST(
                CASE
                    WHEN v.NGAY_SINH IS NOT NULL
                         AND REGEXP_LIKE(
                             TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))),
                             '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$'
                         )
                    THEN TO_CHAR(
                             TO_DATE(TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'),
                             'DD/MM/YYYY'
                         )
                    WHEN v.NAM_SINH IS NOT NULL AND v.NAM_SINH > 0
                    THEN TO_CHAR(v.NAM_SINH)
                    WHEN v.NGAY_SINH IS NOT NULL
                    THEN TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100)))
                    ELSE NULL
                END AS NVARCHAR2(100)
            ) AS NGAY_SINH,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            v.TOI_DANH,
            CAST(v.NGAY_BAT_AN_PHAT AS DATE) AS NGAY_BAT,
            v.AN_PHAT,
            CAST(v.NGAY_DEN_TRAI AS DATE) AS NGAY_DEN_TRAI,
            CAST(v.NGAY_HET_AN AS DATE) AS NGAY_HET_HAN,
            CAST(b.NGAY_THAM AS DATE) AS NGAY_THAM,
            CAST(NVL(TRIM(b.TU_THOI_GIAN), u'') AS NVARCHAR2(100)) AS BAT_DAU,
            CAST(NVL(TRIM(b.DEN_THOI_GIAN), u'') AS NVARCHAR2(100)) AS KET_THUC,
            NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE
                WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', '
                ELSE u''
            END ||
            NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
        FROM base_join b
        INNER JOIN vw_one v
            ON v.PHAM_NHAN_ID = b.pn_lai_lich_id
        WHERE (p_tinh_trang_id IS NULL OR v.LL_TINH_TRANG_ID = p_tinh_trang_id)
    ),
    with_total AS (
        SELECT
            r.*,
            COUNT(*) OVER () AS TOTAL_RECORDS
        FROM result_rows r
    )
    SELECT
        v_skip + ROW_NUMBER() OVER (
            ORDER BY r.ngay_tham_sort DESC NULLS LAST,
                     r.old_pn_id,
                     r.HO_TEN_NGUOI_THAM_RAW,
                     r.BAT_DAU,
                     r.KET_THUC
        ) AS STT,
        r.SO_HSLD,
        r.HO_TEN,
        r.NGAY_SINH,
        r.NOI_DKTT,
        r.TOI_DANH,
        r.NGAY_BAT,
        r.AN_PHAT,
        r.NGAY_DEN_TRAI,
        r.NGAY_HET_HAN,
        r.HO_TEN_NGUOI_THAM_RAW AS HO_TEN_NGUOI_THAM,
        r.NGAY_THAM,
        r.BAT_DAU,
        r.KET_THUC,
        r.PHAN_DOI,
        r.TOTAL_RECORDS
    FROM (
        SELECT x.*
        FROM with_total x
        ORDER BY
            x.ngay_tham_sort DESC NULLS LAST,
            x.old_pn_id,
            x.HO_TEN_NGUOI_THAM_RAW,
            x.BAT_DAU,
            x.KET_THUC
        OFFSET v_skip ROWS
        FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY
    ) r;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i khi l\1ea5y danh s\00e1ch th\0103m g\1eb7p: ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_THAM_GAP;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_TRUONG_HOP_GIAM
