	        NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI,
            dmttpn.TTPN_TEN AS TINH_TRANG

        FROM VW_PN_LAI_LICH_CHI_TIET v
        --LEFT JOIN PN_THI_HANH_AN PTHA ON PTHA.THA_PNLAI_LICH_ID = v.PHAM_NHAN_ID
        INNER JOIN DM_TINH_TRANG_PHAM_NHANS dmttpn ON v.LL_TINH_TRANG_ID = dmttpn.ID AND NVL(dmttpn.IS_DELETED, 0) = 0 
        --LEFT JOIN PN_KET_THUC_RA_TRAIS KTT ON KTT.KTRT_PN_LAI_LICH_ID = V.PHAM_NHAN_ID
        WHERE 1=1

            -- Filter ngày
