--            AND (v_den_ngay IS NULL OR TRUNC(KTT.KTRT_NGAY_THA) <= TRUNC(v_den_ngay) )
            AND (v_tu_ngay IS NULL OR TRUNC(NGAY_HET_AN) >= TRUNC(v_tu_ngay) )
