       AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))             

            AND (P_TRUONG_HOP_GIAM IS NULL
--            OR (P_TRUONG_HOP_GIAM = 1 AND EXISTS (SELECT 1 FROM PN_THI_HANH_AN T WHERE t.THA_PNLAI_LICH_ID = v.PHAM_NHAN_ID
