            OR  EXISTS (SELECT 1 FROM GIAM_THOI_HANS T WHERE t.PHAM_NHAN_ID = v.PHAM_NHAN_ID
          AND  TRUNC(NGAY_THA_GIAM_HET_AN) >=  TRUNC(v_tu_ngay) AND TRUNC(NGAY_THA_GIAM_HET_AN)  <= TRUNC(v_den_ngay) )   -- --GI?M H?T TH?I H?N
            OR  EXISTS (SELECT 1 FROM PN_DAC_XAS T WHERE t.PNLAI_LICH_ID = v.PHAM_NHAN_ID
          AND  TRUNC(DX_NGAY_THA) >=  TRUNC(v_tu_ngay) AND TRUNC(DX_NGAY_THA)  <= TRUNC(v_den_ngay) )   -- ??C XÁ
