--            OR (P_TRUONG_HOP_GIAM = 14 AND EXISTS (SELECT 1 FROM PN_CHUYEN_GIAO T WHERE t.PNCG_LAI_LICH_ID = v.PHAM_NHAN_ID
--          AND  TRUNC(PNCG_NGAY_CHUYEN_GIAO) >=  TRUNC(v_tu_ngay) AND TRUNC(PNCG_NGAY_CHUYEN_GIAO)  <= TRUNC(v_den_ngay) ))    --  CHUY?N GIAO

            OR (P_TRUONG_HOP_GIAM = 7 AND 
           ( EXISTS (SELECT 1 FROM HUY_ANS T WHERE t.PHAM_NHAN_ID = v.PHAM_NHAN_ID
          AND  TRUNC(NGAY_TRA_TU_DO) >=  TRUNC(v_tu_ngay) AND TRUNC(NGAY_TRA_TU_DO)  <= TRUNC(v_den_ngay) )    -- H?Y ÁN
            OR  EXISTS (SELECT 1 FROM HOAN_THI_HANH_ANS T WHERE t.PHAM_NHAN_ID = v.PHAM_NHAN_ID
          AND  TRUNC(NGAY_HOAN) >=  TRUNC(v_tu_ngay) AND TRUNC(NGAY_HOAN)  <= TRUNC(v_den_ngay) )    -- HOÃN THI HÀNH ÁN
            OR  EXISTS (SELECT 1 FROM MIEN_HINH_PHATS T WHERE t.PN_LAI_LICH_ID = v.PHAM_NHAN_ID
          AND  TRUNC(MHP_NGAY_TU_DO) >=  TRUNC(v_tu_ngay) AND TRUNC(MHP_NGAY_TU_DO)  <= TRUNC(v_den_ngay) )   -- MI?N HÌNH PH?T
            OR EXISTS (SELECT 1 FROM CHUA_BENH_BAT_BUOCS T WHERE t.PHAM_NHAN_ID = v.PHAM_NHAN_ID
          AND  TRUNC(NGAY_QUYET_DINH) >=  TRUNC(v_tu_ngay) AND TRUNC(NGAY_QUYET_DINH)  <= TRUNC(v_den_ngay) )    -- CH?A B?NH B?T BU?C
