            AND (P_MUC_AN_ID IS NULL OR P_MUC_AN_ID = v.MUC_AN_ID)--
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
