            --v.NGAY_DEN_TRAI,
            TO_CHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
            --v.NGAY_HET_AN,
            TO_CHAR(v.NGAY_HET_AN, 'DD/MM/YYYY') AS NGAY_HET_AN,
            FN_GET_LIET_KE_HPBS_CHI_TIET(v.PHAM_NHAN_ID) HPBS,
            --PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(v.PHAM_NHAN_ID)   AS DA_GIAM,
            THOI_GIAN_DA_GIAM  AS DA_GIAM,
            mtgch.MTG_TITLE AS TG_CHAP_HANH,
            mtgcl.MTG_TITLE AS TG_CON_LAI,
	        NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
	        CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
	        NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI,
            COUNT(*) OVER (PARTITION BY v.PHAN_DOI_ID) AS TOTAL_PHAN_DOI,
            GHI_CHU,
            COUNT(*) OVER () AS TOTAL_COUNT

        FROM VW_PN_LAI_LICH_CHI_TIET v
        left join DM_MA_THOI_GIANS mtgch on mtgch.MTG_MA = THOI_GIAN_DA_CHAP_HANH
        left join DM_MA_THOI_GIANS mtgcl on mtgcl.MTG_MA = THOI_GIAN_CON_LAI
        WHERE 1=1

            -- Filter ngày
--            AND (v_tu_ngay IS NULL OR TRUNC(v.NGAY_DEN_TRAI) >= TRUNC(v_tu_ngay) )
--            AND (v_den_ngay IS NULL OR TRUNC(v.NGAY_DEN_TRAI) <= TRUNC(v_den_ngay) )
            -- Phân ??i
            AND (P_PHAN_DOI_ID IS NULL OR v.PHAN_DOI_ID = P_PHAN_DOI_ID)
            -- Gi?i tính
            AND (P_GIOI_TINH_ID IS NULL OR v.GIOI_TINH_ID = P_GIOI_TINH_ID)
            -- Qu?c t?ch
            AND (P_QUOC_TICH_ID IS NULL OR v.QUOC_TICH_ID = P_QUOC_TICH_ID)
            -- Tr?i giam
           -- AND (P_MA_TRAI_GIAM IS NULL OR v.TRAI_GIAM_MA = P_MA_TRAI_GIAM)
       AND (p_ma_trai_giam IS NULL OR ( v.TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))             
           -- AND (P_QD_DIEU_CHUYEN IS NULL  P_QD_DIEU_CHUYEN = SO_QD_DIEU_CHUYEN)
            AND P_DIA_PHUONG_ID IS NULL
--            AND (P_TRUONG_HOP_DEN_TRAI IS NULL
--            OR  (P_TRUONG_HOP_DEN_TRAI =  1 AND DOI_TUONG = 8 )-- TR?I T?M GIAM CHUY?N ??N
--            OR  (P_TRUONG_HOP_DEN_TRAI =  2 AND DOI_TUONG = 10 )  -- TR?I GIAM CHUY?N ??N
--            OR  (P_TRUONG_HOP_DEN_TRAI =  3     ) -- ??I T??NG KHÁC CHUY?N ??N
--            OR  (P_TRUONG_HOP_DEN_TRAI =  4 AND EXSIT (SELECT 1 FROM TRON_TRAIS WHERE TRUNC(NGAY_TRON) >=  TRUNC(v_tu_ngay) AND TRUNC(NGAY_TRON)  <= TRUNC(v_den_ngay) ) ) -- TR?N B?T
--            OR  (P_TRUONG_HOP_DEN_TRAI =  5 AND EXSIT (SELECT 1 FROM TAM_DINH_CHIS WHERE TRUNC(NGAY_LAI) >=  TRUNC(v_tu_ngay) AND TRUNC(NGAY_LAI)  <= TRUNC(v_den_ngay) )) -- T?M ?ÌNH CH? TR? L?I
--            OR  (P_TRUONG_HOP_DEN_TRAI =  6 AND EXSIT (SELECT 1 FROM TRICH_XUATS WHERE TRUNC(TX_NGAY_TRA) >=  TRUNC(v_tu_ngay) AND TRUNC(TX_NGAY_TRA)  <= TRUNC(v_den_ngay) )) --TRÍCH XU?T TR? L?I
--            OR  (P_TRUONG_HOP_DEN_TRAI =  7 AND EXSIT (SELECT 1 FROM PN_CHUYEN_GIAO WHERE TRUNC(PNCG_NGAY_CHUYEN_GIAO) >=  TRUNC(v_tu_ngay) AND TRUNC(PNCG_NGAY_CHUYEN_GIAO)  <= TRUNC(v_den_ngay) )) --PH?M NHÂN CHUY?N GIAO ??N TR?I
--            OR  (P_TRUONG_HOP_DEN_TRAI =  8 AND  AND EXSIT (SELECT 1 FROM THA_CO_DIEU_KIENS  WHERE TRUNC(NGAY_BAT_LAI) >=  TRUNC(v_tu_ngay) AND TRUNC(NGAY_BAT_LAI)  <= TRUNC(v_den_ngay) )) --THA TR??C CÓ ?I?U KI?N TR? L?I
--            )
AND (
    P_TRUONG_HOP_DEN_TRAI IS NULL

    OR (P_TRUONG_HOP_DEN_TRAI = 1 AND v.DOI_TUONG IN( 8 ,9)           
    AND (v_tu_ngay IS NULL OR v.NGAY_DEN_TRAI >= v_tu_ngay )
    AND (v_den_ngay IS NULL OR v.NGAY_DEN_TRAI <= v_den_ngay ))

    OR (P_TRUONG_HOP_DEN_TRAI = 2 AND v.DOI_TUONG = 10
    AND (v_tu_ngay IS NULL OR v.NGAY_DEN_TRAI >= v_tu_ngay) 
    AND (v_den_ngay IS NULL OR v.NGAY_DEN_TRAI <= v_den_ngay ))    

    OR (P_TRUONG_HOP_DEN_TRAI = 3 AND v.DOI_TUONG NOT IN (8,9,10)
    AND (v_tu_ngay IS NULL OR v.NGAY_DEN_TRAI >= v_tu_ngay) 
    AND (v_den_ngay IS NULL OR v.NGAY_DEN_TRAI <= v_den_ngay) )

    OR (P_TRUONG_HOP_DEN_TRAI = 4 AND EXISTS (
        SELECT 1 
        FROM TRON_TRAIS t
        WHERE t.PHAM_NHAN_ID = v.PHAM_NHAN_ID
          AND (v_tu_ngay IS NULL OR t.NGAY_BAT_LAI >= v_tu_ngay)
          AND (v_den_ngay IS NULL OR t.NGAY_BAT_LAI <= v_den_ngay)
          AND NGAY_TRON > NGAY_DEN_TRAI
    ))

    OR (P_TRUONG_HOP_DEN_TRAI = 5 AND EXISTS (
        SELECT 1 
        FROM TAM_DINH_CHIS t
        WHERE t.PHAM_NHAN_ID = v.PHAM_NHAN_ID
          AND (v_tu_ngay IS NULL OR t.NGAY_LAI >= v_tu_ngay)
          AND (v_den_ngay IS NULL OR t.NGAY_LAI <= v_den_ngay)
    ))

    OR (P_TRUONG_HOP_DEN_TRAI = 6 AND EXISTS (
        SELECT 1 
        FROM TRICH_XUATS t
        WHERE t.PHAM_NHAN_ID = v.PHAM_NHAN_ID
          AND (v_tu_ngay IS NULL OR t.TX_NGAY_TRA >= v_tu_ngay)
          AND (v_den_ngay IS NULL OR t.TX_NGAY_TRA <= v_den_ngay)
    ))

    OR (P_TRUONG_HOP_DEN_TRAI = 7 AND v.DOI_TUONG IN( 36)           
    AND (v_tu_ngay IS NULL OR v.NGAY_DEN_TRAI >= v_tu_ngay) 
    AND (v_den_ngay IS NULL OR v.NGAY_DEN_TRAI <= v_den_ngay) )

--    AND EXISTS (
--        SELECT 1 
--        FROM PN_CHUYEN_GIAO t
--        WHERE t.PNCG_LAI_LICH_ID = v.PHAM_NHAN_ID
--          AND (v_tu_ngay IS NULL OR TRUNC(t.PNCG_NGAY_CHUYEN_GIAO) >= TRUNC(v_tu_ngay))
--          AND (v_den_ngay IS NULL OR TRUNC(t.PNCG_NGAY_CHUYEN_GIAO) <= TRUNC(v_den_ngay))
--    )


    OR (P_TRUONG_HOP_DEN_TRAI = 8 AND v.DOI_TUONG IN( 35)           
    AND (v_tu_ngay IS NULL OR v.NGAY_DEN_TRAI >= v_tu_ngay) 
    AND (v_den_ngay IS NULL OR v.NGAY_DEN_TRAI <= v_den_ngay) )

--    AND EXISTS (
--        SELECT 1 
--        FROM THA_CO_DIEU_KIENS t
--        WHERE t.PHAM_NHAN_ID = v.PHAM_NHAN_ID
--          AND (v_tu_ngay IS NULL OR TRUNC(t.NGAY_BAT_LAI) >= TRUNC(v_tu_ngay))
--          AND (v_den_ngay IS NULL OR TRUNC(t.NGAY_BAT_LAI) <= TRUNC(v_den_ngay))
--    )

)
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
)

            ;
DBMS_SQL.RETURN_RESULT(C1);
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_DS_XEP_LOAI_CAI_TAO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_DS_XEP_LOAI_CAI_TAO" (
p_trai_giam_id IN  NVARCHAR2    DEFAULT NULL,
    p_nam_xep_loai                IN NUMBER   DEFAULT NULL,
    p_mo_ky_xep_loai_cai_taos_id  IN NUMBER   DEFAULT NULL,
    p_phan_doi_id                 IN NUMBER   DEFAULT NULL,
    p_tinh_trang_id               IN NUMBER   DEFAULT NULL,
    p_loai_xep_loai_cai_tao_id    IN NUMBER   DEFAULT NULL,
    p_bao_cao_ma                  IN VARCHAR2 DEFAULT NULL,
    p_maxresultcount              IN NUMBER   DEFAULT NULL,
    p_skipcount                   IN NUMBER   DEFAULT NULL
) AS
    v_skip   NUMBER;
    v_limit  NUMBER;
    c1       SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    OPEN c1 FOR
    WITH
    x_base AS (
        SELECT x.*
        FROM QLPN.XEP_LOAIS x
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.ID = x.PHAM_NHAN_ID
           AND NVL(ll.is_deleted, 0) = 0
        WHERE NVL(x.IS_DELETED, 0) = 0
          AND (p_nam_xep_loai IS NULL OR x.XEP_LOAI_NAM = p_nam_xep_loai)
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (
              p_mo_ky_xep_loai_cai_taos_id IS NULL
              OR EXISTS (
                  SELECT 1
                  FROM QLPN.MO_KY_XEP_LOAI_CAI_TAO_PN_LAI_LICH mk
                  INNER JOIN QLPN.MO_KY_XEP_LOAI_CAI_TAOS mo
                      ON mo.ID = mk.MO_KY_XEP_LOAI_CAI_TAOS_ID
                     AND NVL(mo.IS_DELETED, 0) = 0
                  left JOIN DM_KY_XEP_LOAI_CAI_TAOS dmk on mo.KY_XEP_LOAI = dmk.KXLCT_TEN   
                  WHERE mk.PN_LAI_LICHS_ID = x.PHAM_NHAN_ID
                    --AND mo.ID = p_mo_ky_xep_loai_cai_taos_id
                    AND dmk.ID = p_mo_ky_xep_loai_cai_taos_id
                    AND x.XEP_LOAI_NAM = mo.NAM_XEP_LOAI
              )
          )
          AND (
              p_loai_xep_loai_cai_tao_id IS NULL
              OR x.XEP_LOAI_QUY_I = p_loai_xep_loai_cai_tao_id
              OR x.XEP_LOAI_QUY_II = p_loai_xep_loai_cai_tao_id
              OR x.XEP_LOAI_QUY_III = p_loai_xep_loai_cai_tao_id
              OR x.XEP_LOAI_QUY_IV = p_loai_xep_loai_cai_tao_id
              OR x.XEP_LOAI_6_THANG_DAU_NAM = p_loai_xep_loai_cai_tao_id
              OR x.XEP_LOAI_6_THANG_CUOI_NAM = p_loai_xep_loai_cai_tao_id
              OR x.XEP_LOAI_CA_NAM = p_loai_xep_loai_cai_tao_id
          )
    ),
    vw_one AS (
        SELECT *
        FROM (
            SELECT
                v.*,
                ROW_NUMBER() OVER (
                    PARTITION BY v.PHAM_NHAN_ID
                    ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
                             v.CREATION_TIME DESC NULLS LAST
                ) AS rn_vw
            FROM QLPN.VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
        ) z
        WHERE rn_vw = 1
    ),
    result_rows AS (
        SELECT
            x.ID AS XEP_LOAI_ROW_ID,
            x.XEP_LOAI_NAM,
            CAST(v.SO_HO_SO AS NVARCHAR2(100)) AS SO_HSLD,
            CAST(v.CCCD AS NVARCHAR2(50)) AS CCCD,
            v.HO_TEN,
            CAST(
                CASE
                    WHEN v.NGAY_SINH IS NOT NULL
                         AND REGEXP_LIKE(
                             TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))),
                             '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$'
                         )
                    THEN TO_CHAR(
                             TO_DATE(TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'),
                             'DD/MM/YYYY'
                         )
                    WHEN v.NAM_SINH IS NOT NULL AND v.NAM_SINH > 0
                    THEN TO_CHAR(v.NAM_SINH)
                    WHEN v.NGAY_SINH IS NOT NULL
                    THEN TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100)))
                    ELSE NULL
                END AS NVARCHAR2(100)
            ) AS NGAY_SINH,
            v.GIOI_TINH,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            v.TOI_DANH,
            v.AN_PHAT,
            CAST(NVL(dm1.XLCT_TEN, u'') AS NVARCHAR2(500)) AS QUY_I,
            CAST(NVL(dm2.XLCT_TEN, u'') AS NVARCHAR2(500)) AS QUY_II,
            CAST(NVL(dm6d.XLCT_TEN, u'') AS NVARCHAR2(500)) AS SAU_THANG_DAU_NAM,
            CAST(NVL(dm3.XLCT_TEN, u'') AS NVARCHAR2(500)) AS QUY_III,
            CAST(NVL(dm4.XLCT_TEN, u'') AS NVARCHAR2(500)) AS QUY_IV,
            CAST(NVL(dm6c.XLCT_TEN, u'') AS NVARCHAR2(500)) AS SAU_THANG_CUOI_NAM,
            CAST(NVL(dmca.XLCT_TEN, u'') AS NVARCHAR2(500)) AS CA_NAM,
            CAST(v.NGAY_HET_AN AS DATE) AS NGAY_HET_HAN,
            NVL(TRIM(CAST(v.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE
                WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', '
                ELSE u''
            END ||
            NVL(TRIM(CAST(v.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
        FROM x_base x
        INNER JOIN vw_one v
            ON v.PHAM_NHAN_ID = x.PHAM_NHAN_ID
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm1
            ON dm1.ID = x.XEP_LOAI_QUY_I
           AND NVL(dm1.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm2
            ON dm2.ID = x.XEP_LOAI_QUY_II
           AND NVL(dm2.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm3
            ON dm3.ID = x.XEP_LOAI_QUY_III
           AND NVL(dm3.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm4
            ON dm4.ID = x.XEP_LOAI_QUY_IV
           AND NVL(dm4.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm6d
            ON dm6d.ID = x.XEP_LOAI_6_THANG_DAU_NAM
           AND NVL(dm6d.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm6c
            ON dm6c.ID = x.XEP_LOAI_6_THANG_CUOI_NAM
           AND NVL(dm6c.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dmca
            ON dmca.ID = x.XEP_LOAI_CA_NAM
           AND NVL(dmca.IS_DELETED, 0) = 0
        WHERE (p_tinh_trang_id IS NULL OR v.LL_TINH_TRANG_ID = p_tinh_trang_id)
        AND (p_trai_giam_id IS NULL OR v.TRAI_GIAM_MA = p_trai_giam_id)
    ),
    with_total AS (
        SELECT
            r.*,
            COUNT(*) OVER () AS TOTAL_COUNT
        FROM result_rows r
    )
    SELECT
        v_skip + ROW_NUMBER() OVER (
            ORDER BY r.XEP_LOAI_NAM DESC NULLS LAST,
                     r.XEP_LOAI_ROW_ID,
                     r.SO_HSLD
        ) AS STT,
        r.SO_HSLD,
        r.CCCD,
        r.HO_TEN,
        r.NGAY_SINH,
        r.GIOI_TINH,
        r.NOI_DKTT,
        r.TOI_DANH,
        r.AN_PHAT,
        r.QUY_I,
        r.QUY_II,
        r.SAU_THANG_DAU_NAM,
        r.QUY_III,
        r.QUY_IV,
        r.SAU_THANG_CUOI_NAM,
        r.CA_NAM,
        --r.NGAY_HET_HAN,
        TO_CHAR(NGAY_HET_HAN, 'DD/MM/YYYY') AS NGAY_HET_HAN,
        r.PHAN_DOI,
        r.XEP_LOAI_NAM,
        r.TOTAL_COUNT
    FROM (
        SELECT x.*
        FROM with_total x
        ORDER BY
        ORDER_HOTEN(x.HO_TEN)
--        REGEXP_SUBSTR(x.HO_TEN, '[^ ]+$') DESC NULLS LAST,
--            x.XEP_LOAI_NAM DESC NULLS LAST,
--            x.XEP_LOAI_ROW_ID,
--            x.SO_HSLD
        OFFSET v_skip ROWS
        FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY
    ) r;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i khi l\1ea5y danh s\00e1ch x\1ebfp lo\1ea1i c\1ea3i t\1ea1o: ' || SQLERRM
        );
END SP_GET_BAO_CAO_DS_XEP_LOAI_CAI_TAO;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_GIAM_THOI_HAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_GIAM_THOI_HAN" (
    p_ma_trai_giam IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay        IN VARCHAR2 DEFAULT NULL,
    p_den_ngay       IN VARCHAR2 DEFAULT NULL,
    p_phan_doi_id        IN NUMBER   DEFAULT NULL,
    p_quoc_tich_id       IN NUMBER   DEFAULT NULL,
    p_loai_doi_tuong_id  IN NUMBER   DEFAULT NULL,
    p_cap_duyet_id       IN NUMBER   DEFAULT NULL,
    p_muc_dn_giam_id     IN NUMBER   DEFAULT NULL,
    p_muc_qd_toa_id      IN NUMBER   DEFAULT NULL,
    p_tinh_trang_id      IN NUMBER   DEFAULT NULL,
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT 0  
)
AS
    v_skip  NUMBER;
    v_limit NUMBER;
    --v_trai_giam_id NUMBER;
    v_tu_ngay DATE;
    v_den_ngay DATE;
    C1 SYS_REFCURSOR;  
BEGIN

    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 99999999999);
--      IF p_ma_trai_giam IS NULL OR p_ma_trai_giam = '' THEN
--        v_trai_giam_id := NULL;
--    ELSE
--        v_trai_giam_id := p_ma_trai_giam;
--    END IF;
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
    END IF;

--     IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
--        v_den_ngay :=  TRUNC(SYSDATE);
--    ELSE
--        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
--    END IF;
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY'));
    END IF;

--    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
--        v_tu_ngay := NULL;
--    ELSE
--        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
--    END IF;

      OPEN C1 FOR
/*
SELECT * FROM (
 SELECT
 ROW_NUMBER() OVER (ORDER BY ll.LL_HO_TEN NULLS LAST) AS rn_all,
    ll.LL_HO_TEN AS ho_ten,
    ll.LL_TEN_KHAC AS ten_khac,
    CASE 
        WHEN ll.LL_NGAY_SINH IS NOT NULL THEN
            CASE 
                -- N?u ch? có 4 s?, coi nh? là n?m
                WHEN REGEXP_LIKE(TO_CHAR(ll.LL_NGAY_SINH), '^\d{4}$') 
                THEN TO_NUMBER(TO_CHAR(ll.LL_NGAY_SINH))
                -- Extract n?m t? format DD/MM/YYYY ho?c DD-MM-YYYY (l?y 4 s? cu?i)
                -- L?y 4 ký t? cu?i cùng n?u chúng là s?
                WHEN LENGTH(TO_CHAR(ll.LL_NGAY_SINH)) >= 4 
                     AND REGEXP_LIKE(SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), -4), '^\d{4}$')
                THEN TO_NUMBER(SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), -4))
                -- N?u không, tìm nhóm 4 s? ??u tiên (có th? là n?m trong format khác)
                WHEN REGEXP_LIKE(TO_CHAR(ll.LL_NGAY_SINH), '\d{4}') 
                THEN TO_NUMBER(REGEXP_SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), '\d{4}', 1, 1))
                ELSE NULL
            END
        ELSE NULL 
    END AS     nam_sinh,
    gt.GT_TEN AS gioi_tinh,
    CASE 
        WHEN ll.LL_DIA_CHI_THUONG_TRU IS NOT NULL 
             OR dvhc_province.TTP_TEN IS NOT NULL 
             OR dvhc_ward.XP_TEN IS NOT NULL
        THEN COALESCE(ll.LL_DIA_CHI_THUONG_TRU, u'') || 
             CASE WHEN dvhc_ward.XP_TEN IS NOT NULL 
                  THEN u', ' || dvhc_ward.XP_TEN 
                  ELSE u'' 
             END ||
             CASE WHEN dvhc_province.TTP_TEN IS NOT NULL 
                  THEN u', ' || dvhc_province.TTP_TEN 
                  ELSE u'' 
             END
        ELSE NULL
    END AS     noi_thuong_tru_day_du,
    qt.QT_TEN AS quoc_tich,
    td.TOI_DANH AS toi_danh,
    td.THA_NGAY_BAT AS ngay_bat_an_phat,
    td.THA_AN_PHAT AS an_phat,
    ll.LL_SO_TIEN_AN AS so_tien_an,
    NVL(PTHA.THA_THOI_GIAN_TAM_GIAM,'Không') tam_giam,
    nvl(PTHA.THA_THOI_GIAN_TAM_GIU, 'Không') tam_giu,
    PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(ll.ID)  DA_CHAP_HANH,
    PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(ll.ID) DA_GIAM,  
    PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(ll.ID)  CON_LAI,
    td.THA_NGAY_DEN_TRAI AS ngay_den_trai ,
    td.THA_NGAY_HET_HAN  AS NGAY_HET_AN,
   DMTGDN.ID MUC_DN_GIAM,
   DMTGCTD.ID CAP_TREN_DUYET,
    td.THA_SO_BAN_AN AS SO_BAN_AN,
td.THA_NGAY_BAN_AN AS NGAY_BAN_AN,
toa_qd.CQ_TEN AS CO_QUAN_QD_THA,
td.THA_SO_QD_THA AS SO_QD_THA,
td.THA_NGAY_QD_THA AS NGAY_QD_THA,
toa_qd_dp.TTP_Ten AS TOA_QD_THA_DIA_PHUONG,
PKG_QUAN_HE_GIA_DINH.FN_GET_HO_TEN_BO(ll.ID) ho_ten_bo,
PKG_QUAN_HE_GIA_DINH.FN_GET_HO_TEN_ME(ll.ID) ho_ten_me,
PKG_QUAN_HE_GIA_DINH.FN_GET_HO_TEN_VC(ll.ID) ho_ten_vo_chong,
FN_GHI_CHU_PHAM_NHAN(ll.ID)  ghi_chu  

FROM
    PN_LAI_LICHS LL
    INNER JOIN GIAM_THOI_HANS GTH ON GTH.PHAM_NHAN_ID = LL.ID
    LEFT JOIN  DM_TINH_TRANG_PHAM_NHANS b on LL.LL_TINH_TRANG_ID = b.ID
    LEFT JOIN PN_THI_HANH_AN PTHA ON PTHA.tha_pnlai_lich_id = ll.ID 
    LEFT JOIN DM_QUOC_TICHS qt ON ll.LL_DM_QUOC_TICH_ID = qt.ID 
    LEFT JOIN DM_MA_THOI_GIANS DMTGDN ON DMTGDN.MTG_MA = GTH.MUC_DE_NGHI_ID
    LEFT JOIN DM_MA_THOI_GIANS DMTGCTD ON DMTGCTD.MTG_MA = GTH.CAP_TREN_DUYET_ID
    LEFT JOIN DM_MA_THOI_GIANS DMTGQDT ON DMTGQDT.MTG_MA = GTH.TOA_QUYET_DINH_ID  
    LEFT JOIN DM_GIOI_TINHS gt  ON ll.LL_DM_GIOI_TINH_ID = gt.ID 
    LEFT JOIN DM_TINH_THANH_PHO dvhc_province  ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dvhc_province.ID 
    LEFT JOIN DM_XA_PHUONG dvhc_ward  ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dvhc_ward.ID 
LEFT JOIN DM_QUOC_TICHS qt   ON ll.LL_DM_QUOC_TICH_ID = qt.ID 
LEFT JOIN V_PN_THI_HANH_AN_TOI_DANH td   ON ll.ID = td.THA_PNLAI_LICH_ID     
LEFT JOIN DM_CO_QUANS toa_qd  ON td.THA_TOA_QD_ID = toa_qd.ID
LEFT JOIN DM_TINH_THANH_PHO toa_qd_dp  ON td.THA_DIA_PHUONG_TOA_QD_THA_ID  = toa_qd_dp.ID
--LEFT JOIN DM_PHAN_DOIS pd ON ll.ll_phan_doi_id = pd.ID
WHERE 1=1
AND NVL(PTHA.is_deleted, 0) = 0 AND PTHA.tha_pnlai_lich_id IS NOT NULL
        -- AND (v_trai_giam_id IS NULL OR LL.TRAI_GIAM_ID = v_trai_giam_id)
         AND (v_tu_ngay IS NULL OR v_den_ngay IS NULL OR PTHA.THA_NGAY_DEN_TRAI BETWEEN v_tu_ngay AND v_den_ngay)
         AND (p_loai_doi_tuong_id IS NULL OR PTHA.THA_DOI_TUONG = p_loai_doi_tuong_id)
         AND (p_quoc_tich_id IS NULL OR QT.ID = p_quoc_tich_id)
         AND (p_muc_dn_giam_id IS NULL OR GTH.MUC_DE_NGHI_ID = p_muc_dn_giam_id)
         AND (p_cap_duyet_id IS NULL OR GTH.CAP_TREN_DUYET_ID = p_cap_duyet_id)
         AND (p_phan_doi_id IS NULL OR ll.ll_phan_doi_id = p_phan_doi_id)
         AND (p_muc_qd_toa_id IS NULL OR GTH.TOA_QUYET_DINH_ID = p_muc_qd_toa_id)
         AND (p_tinh_trang_id IS NULL)
         )
    WHERE  rn_all > v_skip
      AND (v_limit = 0 OR rn_all <= v_skip + v_limit)
    ORDER BY rn_all          
         ;

*/

WITH THAN_NHAN_RN AS (
    SELECT
        v.PHAM_NHAN_ID,
        v.HO_TEN_THAN_NHAN,
        CASE
            WHEN UPPER(TRIM(v.QUAN_HE)) LIKE 'B?%' THEN 'BO'
            WHEN UPPER(TRIM(v.QUAN_HE)) LIKE 'M?%' THEN 'ME'
            WHEN UPPER(TRIM(v.QUAN_HE)) IN ('V?', 'CH?NG') THEN 'VC'
        END AS LOAI_QH,
        ROW_NUMBER() OVER (
            PARTITION BY v.PHAM_NHAN_ID,
                         CASE
                             WHEN UPPER(TRIM(v.QUAN_HE)) LIKE 'B?%' THEN 'BO'
                             WHEN UPPER(TRIM(v.QUAN_HE)) LIKE 'M?%' THEN 'ME'
                             WHEN UPPER(TRIM(v.QUAN_HE)) IN ('V?', 'CH?NG') THEN 'VC'
                         END
            ORDER BY v.ID
        ) AS RN
    FROM QLPN.VW_THAN_NHAN v
    WHERE UPPER(TRIM(v.QUAN_HE)) LIKE 'B?%'
       OR UPPER(TRIM(v.QUAN_HE)) LIKE 'M?%'
       OR UPPER(TRIM(v.QUAN_HE)) IN ('V?', 'CH?NG')
),
THAN_NHAN_QH AS (
    SELECT
        PHAM_NHAN_ID,
        MAX(CASE WHEN LOAI_QH = 'BO' AND RN = 1 THEN HO_TEN_THAN_NHAN END) AS ho_ten_bo,
        MAX(CASE WHEN LOAI_QH = 'ME' AND RN = 1 THEN HO_TEN_THAN_NHAN END) AS ho_ten_me,
        MAX(CASE WHEN LOAI_QH = 'VC' AND RN = 1 THEN HO_TEN_THAN_NHAN END) AS ho_ten_vo_chong
    FROM THAN_NHAN_RN
    GROUP BY PHAM_NHAN_ID
),
PN_LAI_LICHS_TG AS (
SELECT * FROM PN_LAI_LICHS
WHERE (p_ma_trai_giam IS NULL OR ( ll_TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))  
),
GIAM_THOI_HANS_NX AS(
SELECT * FROM GIAM_THOI_HANS GTH WHERE GTH.is_deleted = 0
         AND (v_tu_ngay IS NULL OR  GTH.NGAY_XET  >=  v_tu_ngay) 
          AND (v_den_ngay IS NULL OR  GTH.NGAY_XET  <=  v_den_ngay) 
)

SELECT * FROM (
SELECT 
    --ROW_NUMBER() OVER (ORDER BY ll.LL_HO_TEN NULLS LAST) AS rn_all,
   -- ROW_NUMBER() OVER (ORDER BY   HO_TEN_ORDER NULLS LAST) AS rn_all,
    COUNT(*) OVER() AS total_count,
    ll.ID AS PHAM_NHAN_ID,
    ll.LL_HO_TEN AS ho_ten,
    ll.LL_TEN_KHAC AS ten_khac,
    CASE 
        WHEN ll.LL_NGAY_SINH IS NOT NULL THEN
            CASE 
                WHEN REGEXP_LIKE(TO_CHAR(ll.LL_NGAY_SINH), '^\d{4}$') 
                    THEN TO_NUMBER(TO_CHAR(ll.LL_NGAY_SINH))
                WHEN LENGTH(TO_CHAR(ll.LL_NGAY_SINH)) >= 4 
                     AND REGEXP_LIKE(SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), -4), '^\d{4}$')
                    THEN TO_NUMBER(SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), -4))
                WHEN REGEXP_LIKE(TO_CHAR(ll.LL_NGAY_SINH), '\d{4}') 
                    THEN TO_NUMBER(REGEXP_SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), '\d{4}', 1, 1))
                ELSE NULL
            END
        ELSE NULL 
    END AS nam_sinh,
    gt.GT_TEN AS gioi_tinh,
    CASE
        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
          OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
        THEN TRIM(
            NVL(NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u''), u'')
            || CASE
                WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                            THEN u', ' || dxp_thuong_tru.XP_TEN
                        ELSE dxp_thuong_tru.XP_TEN
                    END
                ELSE u''
               END
            || CASE
                WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                            THEN u', ' || dttp_thuong_tru.TTP_TEN
                        ELSE dttp_thuong_tru.TTP_TEN
                    END
                ELSE u''
               END
        )
        ELSE NULL
    END AS NOI_THUONG_TRU_DAY_DU,
    qt.QT_TEN AS quoc_tich,
    td.TOI_DANH AS toi_danh,
    --td.THA_NGAY_BAT AS ngay_bat_an_phat,
    TO_CHAR(td.THA_NGAY_BAT, 'DD/mm/yyyy') AS ngay_bat_an_phat,
    td.THA_AN_PHAT AS an_phat,
    ll.LL_SO_TIEN_AN AS so_tien_an,
    NVL(PTHA.THA_THOI_GIAN_TAM_GIAM, u'Kh\00f4ng') AS tam_giam,
    NVL(PTHA.THA_THOI_GIAN_TAM_GIU, u'Kh\00f4ng') AS tam_giu,
    DMTGDCHA.MTG_TITLE AS THA_THOI_GIAN_DA_CHAP_HANH,
    --NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(GTH.PHAM_NHAN_ID, v_den_ngay), u'') AS DA_CHAP_HANH,
    PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(ll.ID) AS DA_GIAM,
    PD.PD_TEN AS PHAN_DOI,
    PT.PT_TEN AS PHAN_TRAI,
    TTPN_TEN as TINH_TRANG,
    --PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(GTH.PHAM_NHAN_ID, v_den_ngay) AS THA_THOI_GIAN_CON_LAI,
    DMTGCL.MTG_TITLE AS THA_THOI_GIAN_CON_LAI,
    --td.THA_NGAY_DEN_TRAI AS ngay_den_trai,
    TO_CHAR(td.THA_NGAY_DEN_TRAI, 'DD/mm/yyyy') AS ngay_den_trai,
    --td.THA_NGAY_HET_HAN AS NGAY_HET_AN,
    TO_CHAR(td.THA_NGAY_HET_HAN, 'DD/mm/yyyy') AS NGAY_HET_AN,
    DMTGDN.MTG_TITLE AS MUC_DN_GIAM,
    DMTGCTD.MTG_TITLE AS CAP_TREN_DUYET,
    DMTGQDT.MTG_TITLE AS TOA_QUYET_DINH_GIAM,
    td.THA_SO_BAN_AN AS SO_BAN_AN,
    --td.THA_NGAY_BAN_AN AS NGAY_BAN_AN,
    TO_CHAR(td.THA_NGAY_BAN_AN, 'DD/mm/yyyy') AS NGAY_BAN_AN,
    toa_qd.CQ_TEN AS CO_QUAN_QD_THA,
    td.THA_SO_QD_THA AS SO_QD_THA,
    --td.THA_NGAY_QD_THA AS NGAY_QD_THA,
    TO_CHAR(td.THA_NGAY_QD_THA, 'DD/mm/yyyy') AS NGAY_QD_THA,
    toa_qd_dp.TTP_TEN AS TOA_QD_THA_DIA_PHUONG,
    qh.ho_ten_bo,
    qh.ho_ten_me,
    NVL(TRIM(qh.ho_ten_vo_chong), u'Ch\01b0a c\00f3') AS ho_ten_vo_chong,
    --FN_GHI_CHU_PHAM_NHAN(ll.ID) AS ghi_chu,
    TO_CHAR(ngay_xet, 'DD/mm/yyyy') AS ngay_xet
FROM GIAM_THOI_HANS_NX GTH   
INNER JOIN PN_LAI_LICHS_TG LL
    ON GTH.PHAM_NHAN_ID = LL.ID AND LL.is_deleted = 0
LEFT JOIN DM_TINH_TRANG_PHAM_NHANS b 
    ON LL.LL_TINH_TRANG_ID = b.ID AND b.is_deleted = 0
LEFT JOIN PN_THI_HANH_AN PTHA 
    ON PTHA.tha_pnlai_lich_id = ll.ID  AND PTHA.is_deleted = 0
LEFT JOIN DM_QUOC_TICHS qt 
    ON ll.LL_DM_QUOC_TICH_ID = qt.ID  AND qt.is_deleted = 0
LEFT JOIN DM_MA_THOI_GIANS DMTGDN 
    ON DMTGDN.ID = GTH.MUC_DE_NGHI_ID AND DMTGDN.is_deleted = 0
LEFT JOIN DM_MA_THOI_GIANS DMTGCL 
    ON DMTGCL.MTG_MA = PTHA.THA_THOI_GIAN_CON_LAI AND DMTGCL.is_deleted = 0
LEFT JOIN DM_MA_THOI_GIANS DMTGDCHA 
    ON DMTGDCHA.MTG_MA = PTHA.THA_THOI_GIAN_DA_CHAP_HANH AND DMTGDCHA.is_deleted = 0
LEFT JOIN DM_MA_THOI_GIANS DMTGCTD 
    ON DMTGCTD.ID = GTH.CAP_TREN_DUYET_ID AND DMTGCTD.is_deleted = 0
LEFT JOIN DM_MA_THOI_GIANS DMTGQDT 
    ON DMTGQDT.ID = GTH.MUC_GIAM_ID   AND DMTGQDT.is_deleted = 0
LEFT JOIN DM_GIOI_TINHS gt  
    ON ll.LL_DM_GIOI_TINH_ID = gt.ID  AND gt.is_deleted = 0
LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru 
    ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID 
    AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
LEFT JOIN DM_XA_PHUONG dxp_thuong_tru 
    ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID 
    AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
LEFT JOIN V_PN_THI_HANH_AN_TOI_DANH td
    ON ll.ID = td.THA_PNLAI_LICH_ID     
LEFT JOIN DM_CO_QUANS toa_qd
    ON td.THA_TOA_QD_ID = toa_qd.ID
LEFT JOIN DM_TINH_THANH_PHO toa_qd_dp
    ON td.THA_DIA_PHUONG_TOA_QD_THA_ID = toa_qd_dp.ID
LEFT JOIN THAN_NHAN_QH qh
    ON qh.PHAM_NHAN_ID = ll.ID
LEFT JOIN DM_PHAN_DOIS PD
	ON PD.ID = LL.LL_PHAN_DOI_ID
LEFT JOIN DM_PHAN_TRAIS PT
	ON PT.ID = LL.LL_PHAN_TRAI_ID
WHERE 1 = 1
--AND NVL(PTHA.is_deleted, 0) = 0 
--AND PTHA.tha_pnlai_lich_id IS NOT NULL
AND NVL(GTH.is_deleted, 0) = 0
        -- AND (v_trai_giam_id IS NULL OR LL.TRAI_GIAM_ID = v_trai_giam_id)
         --AND (v_tu_ngay IS NULL OR v_den_ngay IS NULL OR PTHA.THA_NGAY_DEN_TRAI BETWEEN v_tu_ngay AND v_den_ngay)
         --AND (v_tu_ngay IS NULL OR v_den_ngay IS NULL OR GTH.NGAY_XET BETWEEN v_tu_ngay AND v_den_ngay)
AND (p_ma_trai_giam IS NULL OR ( ll_TRAI_GIAM_ID = (select id from DM_TRAI_GIAMS where TG_MA= p_ma_trai_giam)))   
         AND (v_tu_ngay IS NULL OR  GTH.NGAY_XET  >=  v_tu_ngay) 
          AND (v_den_ngay IS NULL OR  GTH.NGAY_XET  <=  v_den_ngay) 
         AND (p_loai_doi_tuong_id IS NULL OR PTHA.THA_DOI_TUONG = p_loai_doi_tuong_id)
         AND (p_quoc_tich_id IS NULL OR QT.ID = p_quoc_tich_id)
         AND (p_muc_dn_giam_id IS NULL OR GTH.MUC_DE_NGHI_ID = p_muc_dn_giam_id)
         AND (p_cap_duyet_id IS NULL OR GTH.CAP_TREN_DUYET_ID = p_cap_duyet_id)
         AND (p_phan_doi_id IS NULL OR ll.ll_phan_doi_id = p_phan_doi_id)
         --AND (p_muc_qd_toa_id IS NULL OR GTH.TOA_QUYET_DINH_ID = p_muc_qd_toa_id)
         AND (p_muc_qd_toa_id IS NULL OR GTH.MUC_GIAM_ID = p_muc_qd_toa_id)
         --AND (p_tinh_trang_id IS NULL or b.id = p_tinh_trang_id)
         AND (p_tinh_trang_id IS NULL or   
         (GTH.MUC_DE_NGHI_ID = GTH.CAP_TREN_DUYET_ID AND GTH.MUC_DE_NGHI_ID IS NOT NULL AND GTH.CAP_TREN_DUYET_ID is not null and p_tinh_trang_id = 2) or  --MUC_DE_NGHI_ID = MUC_GIAM_ID = CAP_TREN_DUYET_ID
         (GTH.MUC_DE_NGHI_ID <> GTH.CAP_TREN_DUYET_ID and p_tinh_trang_id = 1) or
         (GTH.CAP_TREN_DUYET_ID = ( select id from DM_MA_THOI_GIANS where MTG_MA = '000000') and p_tinh_trang_id = 4) or
         (GTH.CAP_TREN_DUYET_ID not in ( select id from DM_MA_THOI_GIANS where MTG_MA = '000000') and p_tinh_trang_id = 3) or
         --(GTH.MUC_GIAM_ID <> GTH.CAP_TREN_DUYET_ID and p_tinh_trang_id = 6) or
         (GTH.MUC_GIAM_ID <> MUC_DE_NGHI_ID and p_tinh_trang_id = 5) or
         --(GTH.MUC_GIAM_ID = GTH.CAP_TREN_DUYET_ID AND GTH.MUC_GIAM_ID IS NOT NULL  AND GTH.CAP_TREN_DUYET_ID is not null and p_tinh_trang_id = 5) or
         (GTH.MUC_GIAM_ID = MUC_DE_NGHI_ID AND GTH.MUC_GIAM_ID IS NOT NULL  AND MUC_DE_NGHI_ID is not null and p_tinh_trang_id = 6) or
         ( (GTH.MUC_GIAM_ID IS NULL or GTH.MUC_GIAM_ID = (select id from DM_MA_THOI_GIANS where MTG_MA = '000000') ) and p_tinh_trang_id = 8) or
         (GTH.MUC_GIAM_ID IS NOT NULL and GTH.MUC_GIAM_ID not in (select id from DM_MA_THOI_GIANS where MTG_MA = '000000') and p_tinh_trang_id = 7)
         )
      ORDER BY HO_TEN_ORDER
      OFFSET v_skip ROWS
      FETCH NEXT NVL(v_limit, 99999999999) ROWS ONLY
)     
--WHERE  rn_all > v_skip
--      AND (v_limit = 0 OR rn_all <= v_skip + v_limit)
   ;
--
      DBMS_SQL.RETURN_RESULT(C1);
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_GIAM_THOI_HAN_2
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_GIAM_THOI_HAN_2" (
p_trai_giam_id IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay            IN VARCHAR2  DEFAULT NULL,
    p_den_ngay           IN VARCHAR2  DEFAULT NULL,
    p_phan_doi_id        IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id       IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id  IN NUMBER    DEFAULT NULL,
    p_cap_duyet_id       IN NUMBER    DEFAULT NULL,
    p_muc_dn_giam_id     IN NUMBER    DEFAULT NULL,
    p_muc_qd_toa_id      IN NUMBER    DEFAULT NULL,
    p_tinh_trang_id      IN NUMBER    DEFAULT NULL,
    p_phan_trai_id       IN NUMBER    DEFAULT NULL,
    p_maxresultcount     IN NUMBER    DEFAULT NULL,
    p_skipcount          IN NUMBER    DEFAULT 0
)
AS
    v_skip       NUMBER;
    v_limit      NUMBER;
    v_tu_ngay    NVARCHAR2(10);
    v_den_ngay   NVARCHAR2(10);
    C1           SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := TRUNC(SYSDATE);
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN C1 FOR
    WITH THAN_NHAN_RN AS (
        SELECT
            v.PHAM_NHAN_ID,
            v.HO_TEN_THAN_NHAN,
            CASE
                WHEN UPPER(TRIM(v.QUAN_HE)) LIKE 'B%' THEN 'BO'
                WHEN UPPER(TRIM(v.QUAN_HE)) LIKE 'M%' THEN 'ME'
                WHEN UPPER(TRIM(v.QUAN_HE)) IN ('V', 'CH') THEN 'VC'
            END AS LOAI_QH,
            ROW_NUMBER() OVER (
                PARTITION BY v.PHAM_NHAN_ID,
                    CASE
                        WHEN UPPER(TRIM(v.QUAN_HE)) LIKE 'B%' THEN 'BO'
                        WHEN UPPER(TRIM(v.QUAN_HE)) LIKE 'M%' THEN 'ME'
                        WHEN UPPER(TRIM(v.QUAN_HE)) IN ('V', 'CH') THEN 'VC'
                    END
                ORDER BY v.ID
            ) AS RN
        FROM QLPN.VW_THAN_NHAN v
        WHERE UPPER(TRIM(v.QUAN_HE)) LIKE 'B%'
           OR UPPER(TRIM(v.QUAN_HE)) LIKE 'M%'
           OR UPPER(TRIM(v.QUAN_HE)) IN ('V', 'CH')
    ),
    THAN_NHAN_QH AS (
        SELECT
            PHAM_NHAN_ID,
            MAX(CASE WHEN LOAI_QH = 'BO' AND RN = 1 THEN HO_TEN_THAN_NHAN END) AS ho_ten_bo,
            MAX(CASE WHEN LOAI_QH = 'ME' AND RN = 1 THEN HO_TEN_THAN_NHAN END) AS ho_ten_me,
            MAX(CASE WHEN LOAI_QH = 'VC' AND RN = 1 THEN HO_TEN_THAN_NHAN END) AS ho_ten_vo_chong
        FROM THAN_NHAN_RN
        GROUP BY PHAM_NHAN_ID
    )
    SELECT * FROM (
        SELECT
            ROW_NUMBER() OVER (ORDER BY ll.LL_HO_TEN NULLS LAST) AS rn_all,
            COUNT(*) OVER() AS total_count,
            ll.ID AS PHAM_NHAN_ID,
            -- So HSLD, Ho ten, NS, GT, DKTT, Quoc tich
            ll.LL_SO_HO_SO_LAN_DAU     AS so_hsld,
            ll.LL_HO_TEN               AS ho_ten,
            CASE
                WHEN ll.LL_NGAY_SINH IS NOT NULL THEN
                    CASE
                        WHEN REGEXP_LIKE(TO_CHAR(ll.LL_NGAY_SINH), '^\d{4}$')
                            THEN TO_NUMBER(TO_CHAR(ll.LL_NGAY_SINH))
                        WHEN LENGTH(TO_CHAR(ll.LL_NGAY_SINH)) >= 4
                             AND REGEXP_LIKE(SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), -4), '^\d{4}$')
                            THEN TO_NUMBER(SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), -4))
                        WHEN REGEXP_LIKE(TO_CHAR(ll.LL_NGAY_SINH), '\d{4}')
                            THEN TO_NUMBER(REGEXP_SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), '\d{4}', 1, 1))
                        ELSE NULL
                    END
                ELSE NULL
            END AS nam_sinh,
            gt.GT_TEN AS gioi_tinh,
            CASE
                WHEN ll.LL_DIA_CHI_THUONG_TRU IS NOT NULL
                     OR dvhc_province.TTP_TEN IS NOT NULL
                     OR dvhc_ward.XP_TEN IS NOT NULL
                THEN COALESCE(ll.LL_DIA_CHI_THUONG_TRU, u'') ||
                     CASE WHEN dvhc_ward.XP_TEN IS NOT NULL
                          THEN u', ' || dvhc_ward.XP_TEN ELSE u'' END ||
                     CASE WHEN dvhc_province.TTP_TEN IS NOT NULL
                          THEN u', ' || dvhc_province.TTP_TEN ELSE u'' END
                ELSE NULL
            END AS noi_thuong_tru_day_du,
            qt.QT_TEN AS quoc_tich,
            -- Toi danh, Ngay bat, An phat, Tien an
            TD.TOI_DANH AS toi_danh,
            TD.THA_NGAY_BAT AS ngay_bat,
            TD.THA_AN_PHAT AS an_phat,
            ll.LL_SO_TIEN_AN AS tien_an,
            -- Muc DN giam (3 cot: trai / cap tren / Toa)
            GTHMUC.MTG_TITLE AS muc_dn_giam_tra_i,
            CT.MTG_TITLE AS muc_dn_cap_tren,
            GTHMGIA.MTG_TITLE AS muc_giam_toa,
            -- Ngay ra trai
            GTH.NGAY_THA_GIAM_HET_AN AS ngay_ra_trai,
            -- Tinh trang, Phan doi
            b.TTPN_TEN AS tinh_trang,
            pd.PD_TEN AS phan_doi,
            -- Ho ten than nhan
            qh.ho_ten_bo,
            qh.ho_ten_me,
            NVL(TRIM(qh.ho_ten_vo_chong), u'Ch\01b0a c\00f3') AS ho_ten_vo_chong,
            -- Ghi chu
            GTH.NHAN_XET AS ghi_chu
        FROM PN_LAI_LICHS LL
        INNER JOIN GIAM_THOI_HANS GTH
            ON GTH.PHAM_NHAN_ID = LL.ID
        LEFT JOIN DM_TINH_TRANG_PHAM_NHANS b
            ON LL.LL_TINH_TRANG_ID = b.ID
        LEFT JOIN PN_THI_HANH_AN PTHA
            ON PTHA.tha_pnlai_lich_id = ll.ID
        LEFT JOIN DM_QUOC_TICHS qt
            ON ll.LL_DM_QUOC_TICH_ID = qt.ID
        -- Muc DN giam (de nghi cua trai)
        LEFT JOIN DM_MA_THOI_GIANS GTHMUC
            ON GTHMUC.MTG_MA = GTH.MUC_DE_NGHI_ID
        -- Muc DN cap tren duyet
        LEFT JOIN DM_MA_THOI_GIANS CT
            ON CT.MTG_MA = GTH.CAP_TREN_DUYET_ID
        -- Muc giam theo QD Toa
        LEFT JOIN DM_MA_THOI_GIANS GTHMGIA
            ON GTHMGIA.MTG_MA = GTH.MUC_GIAM_ID
        LEFT JOIN DM_GIOI_TINHS gt
            ON ll.LL_DM_GIOI_TINH_ID = gt.ID
        LEFT JOIN DM_TINH_THANH_PHO dvhc_province
            ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dvhc_province.ID
        LEFT JOIN DM_XA_PHUONG dvhc_ward
            ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dvhc_ward.ID
        LEFT JOIN V_PN_THI_HANH_AN_TOI_DANH TD
            ON ll.ID = TD.THA_PNLAI_LICH_ID
        LEFT JOIN DM_PHAN_DOIS pd
            ON pd.ID = LL.LL_PHAN_DOI_ID
        LEFT JOIN THAN_NHAN_QH qh
            ON qh.PHAM_NHAN_ID = ll.ID
        LEFT JOIN DM_PHAN_TRAIS PT
	ON PT.ID = LL.LL_PHAN_TRAI_ID
        WHERE 1 = 1
          AND NVL(PTHA.is_deleted, 0) = 0
          AND PTHA.tha_pnlai_lich_id IS NOT NULL
          AND (p_trai_giam_id IS NULL  OR PT.PT_MA = p_trai_giam_id)
          AND (v_tu_ngay IS NULL OR v_den_ngay IS NULL OR PTHA.THA_NGAY_DEN_TRAI BETWEEN v_tu_ngay AND v_den_ngay)
          AND (p_loai_doi_tuong_id IS NULL OR PTHA.THA_DOI_TUONG = p_loai_doi_tuong_id)
          AND (p_quoc_tich_id IS NULL OR QT.ID = p_quoc_tich_id)
          AND (p_muc_dn_giam_id IS NULL OR GTH.MUC_DE_NGHI_ID = p_muc_dn_giam_id)
          AND (p_cap_duyet_id IS NULL OR GTH.CAP_TREN_DUYET_ID = p_cap_duyet_id)
          AND (p_phan_doi_id IS NULL OR ll.ll_phan_doi_id = p_phan_doi_id)
          AND (p_muc_qd_toa_id IS NULL OR GTH.TOA_QUYET_DINH_ID = p_muc_qd_toa_id)
          AND (p_tinh_trang_id IS NULL OR b.id = p_tinh_trang_id)
          AND (p_phan_trai_id IS NULL OR LL.LL_TRAI_GIAM_ID = p_phan_trai_id)
    )
    WHERE rn_all > v_skip
      AND (v_limit = 0 OR rn_all <= v_skip + v_limit)
    ORDER BY rn_all;

    DBMS_SQL.RETURN_RESULT(C1);
END;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_KY_LUAT_CHI_TIET
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_KY_LUAT_CHI_TIET" (
    p_pham_nhan_id IN NUMBER,
    p_ky_luat_id   IN NUMBER DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    SELECT
        /* Header / co quan */
        CAST(NULL AS NVARCHAR2(500))     AS cq_tw,
        tg.TG_TEN                        AS trai_hoa,
        NVL(tg.TG_TEN, LL.TRAI_GIAM)     AS trai_giam_ten,
        NVL(tg.TG_DIA_CHI_DP, tg.TG_DIA_CHI) AS dia_danh,
        /* Quyet dinh ky luat */
        kl.SO_QUYET_DINH                 AS so_qd,
        kl.NGAY_QUYET_DINH               AS ngay_quyet_dinh,
        kl.NGAY_BIEN_BAN                 AS ngay_bb,
        kl.NGAY_DE_NGHI_KY_LUAT          AS ngay_de_nghi,
        kl.NGUOI_DE_NGHI_KY_LUAT        AS noi_de_nghi,
        kl.NOI_DUNG_VI_PHAM              AS noi_dung_vi_pham,
        kl.SO_BIEN_BAN                   AS so_bien_ban,
        /* Tien bo (neu can hien thi phu) */
        kl.NGAY_DE_NGHI_TIEN_BO          AS ngay_de_nghi_tien_bo,
        kl.NOI_DE_NGHI_TIEN_BO           AS noi_de_nghi_tien_bo,
        kl.SO_QUYET_DINH_TIEN_BO         AS so_qd_tien_bo,
        kl.NGAY_QUYET_DINH_TIEN_BO       AS ngay_qd_tien_bo,
        /* Ly do / hinh thuc */
        ldkl.LY_DO_KY_LUAT               AS ly_do_dm,
        kl.LY_DO_KY_LUAT_CU_THE          AS ly_do_cu_the,
        ht.HTKL_TEN                      AS hinh_thuc_dm,
        kl.HINH_THUC_KY_LUAT_CU_THE      AS hinh_thuc_kl,
        /* Ho so PN */
        UPPER(NVL(LL.HO_TEN, ''))        AS ho_ten_hoa,
        LL.HO_TEN                        AS ho_ten,
        LL.GIOI_TINH                     AS gioi_tinh,
        LL.NAM_SINH                      AS nam_sinh,
        LL.NGAY_SINH                     AS ngay_sinh,
        LL.TEN_KHAC                      AS ten_khac,
        LL.NOI_THUONG_TRU_DAY_DU         AS dc_tt,
        LL.TOI_DANH                      AS toi_danh,
        LL.NGAY_BAT_AN_PHAT              AS ngay_bat,
        LL.AN_PHAT                       AS an_phat,
        LL.SO_BAN_AN                     AS ban_an_so,
        LL.NGAY_BAN_AN                   AS ngay_xu,
        LL.TOA_XU_TEN                    AS toa_xu,
        LL.SO_QD_THA                     AS so_qd_tha,
        LL.NGAY_QD_THA                   AS ngay_qd_tha,
        LL.CO_QUAN_QD_THA                AS toa_qd,
        LL.TOA_QD_THA_DIA_PHUONG        AS toa_qd_tha_dia_phuong,
        LL.SO_TIEN_AN                    AS tien_an,
        LL.SO_TIEN_SU                    AS tien_su,
        LL.PHAN_DOI                      AS phan_doi,
        LL.PHAN_TRAI                     AS phan_trai,
        LL.SO_HO_SO                      AS so_ho_so,
        LL.CCCD                          AS cccd,
        b.TTPN_TEN                       AS tinh_trang,
        kl.ID                            AS ky_luat_id,
        LL.PHAM_NHAN_ID                  AS pham_nhan_id
    FROM vw_pn_lai_lich_chi_tiet LL
    INNER JOIN KY_LUATS kl
        ON kl.PHAM_NHAN_ID = LL.PHAM_NHAN_ID
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS b
        ON LL.LL_TINH_TRANG_ID = b.ID
        AND NVL(b.IS_DELETED, 0) = 0
     OUTER APPLY (
            SELECT LISTAGG(d.LDKL_TEN, u'; ' ON OVERFLOW TRUNCATE)
                       WITHIN GROUP (ORDER BY d.LDKL_TEN) AS LY_DO_KY_LUAT
              FROM JSON_TABLE(
                       CASE WHEN KL.MA_LY_DO_KY_LUAT_IDS IS JSON
                            THEN KL.MA_LY_DO_KY_LUAT_IDS
                            ELSE u'[' || TO_CHAR(KL.MA_LY_DO_KY_LUAT_ID) || u']'
                       END,
                       '$[*]' COLUMNS (ly_do_id NUMBER PATH '$')) jt
              JOIN DM_LY_DO_KY_LUATS d
                ON d.ID = jt.ly_do_id
               AND d.IS_DELETED = 0
        ) ldkl
    LEFT JOIN DM_HINH_THUC_KY_LUATS ht
        ON ht.ID = kl.MA_HINH_THUC_KY_LUAT_ID
        AND NVL(ht.IS_DELETED, 0) = 0
    LEFT JOIN DM_TRAI_GIAMS tg
        ON tg.ID = LL.TRAI_GIAM_ID
        AND NVL(tg.IS_DELETED, 0) = 0
    WHERE NVL(LL.IS_DELETED, 0) = 0
      AND LL.PHAM_NHAN_ID = p_pham_nhan_id
      AND (
            (p_ky_luat_id IS NOT NULL AND kl.ID = p_ky_luat_id)
         OR (p_ky_luat_id IS NULL AND kl.ID = (
                SELECT k2.ID
                FROM (
                    SELECT k2.ID,
                           ROW_NUMBER() OVER (
                               ORDER BY k2.NGAY_QUYET_DINH DESC NULLS LAST,
                                        k2.ID DESC
                           ) AS rn
                    FROM KY_LUATS k2
                    WHERE k2.PHAM_NHAN_ID = p_pham_nhan_id
                ) k2
                WHERE k2.rn = 1
            ))
          );

    DBMS_SQL.RETURN_RESULT(C1);
END;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_PHAM_NHAN_BAN_CHI_DAO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_PHAM_NHAN_BAN_CHI_DAO" (
    p_ma_trai_giam      IN NVARCHAR2 DEFAULT NULL,
    p_tinh_trang_id     IN NUMBER    DEFAULT NULL,
    p_phan_doi_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id  IN NUMBER    DEFAULT NULL,
    p_in                IN NUMBER    DEFAULT 1,
    p_tu_ngay           IN VARCHAR2  DEFAULT NULL,
    p_den_ngay          IN VARCHAR2  DEFAULT NULL,
    p_maxresultcount    IN NUMBER    DEFAULT NULL,
    p_skipcount         IN NUMBER    DEFAULT 0
)
AS
    v_skip         NUMBER;
    v_limit        NUMBER;
     v_tu_ngay      DATE;
    v_den_ngay     DATE;
    -- ID c?a ghi chú "BAN CH? ??O" trong DM_GHI_CHU_RIENGS — resolve 1 l?n
    v_ban_chi_dao_id NUMBER;
    C1             SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);


    v_tu_ngay := CASE
        WHEN p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN NULL
        ELSE TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY'))
    END;

    v_den_ngay := CASE
        WHEN p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN NULL
        ELSE TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'))
    END;

    -- Resolve ID c?a "BAN CH? ??O" 1 l?n duy nh?t thay vì REGEXP_LIKE sau LISTAGG
    BEGIN
  SELECT gcr.ID into v_ban_chi_dao_id
        FROM DM_GHI_CHU_RIENGS gcr
        WHERE upper(gcr.GCR_TEN) LIKE '%BAN CH? ??O%'
          AND NVL(gcr.IS_DELETED, 0) = 0
          AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN v_ban_chi_dao_id := NULL;
    END;

    OPEN C1 FOR
    WITH
    /*
       T?i ?u chính:
       1. pn_base: filter tr?i giam / phân ??i / ngày / thi hành án TR??C
          ? thu h?p t?p d? li?u tr??c khi ??ng ??n LL_GHI_CHU_RIENG
       2. pn_ban_chi_dao: dùng LIKE '%,ID,%' thay CONNECT BY ?? ki?m tra
          ID có trong chu?i [1,2,3] — nhanh h?n ~100x, không c?n hierarchy
       3. ghi_chu_agg: ch? LISTAGG trên t?p ?ã l?c xong (vài tr?m dòng)
          thay vì toàn b? PN_LAI_LICHS
       4. B? CONNECT BY trong EXISTS — thay b?ng cùng k? thu?t LIKE
    */
    pn_base AS (
        -- B??c 1: thu h?p theo các filter r? nh?t (index ???c)
        SELECT /*+ MATERIALIZE */
            ll.PHAM_NHAN_ID,
            ll.so_ho_so,
            ll.ho_ten,
            ll.nam_sinh,
            ll.gioi_tinh,
            ll.noi_thuong_tru_day_du,
            ll.toi_danh,
            ll.ngay_bat_an_phat,
            ll.an_phat,
            ll.ngay_den_trai,
            ll.ngay_het_an,
            ll.PHAN_DOI,
            ll.PHAN_TRAI,
            ttpn.TTPN_TEN as tinh_trang,
            ll.phan_doi_id,
            ll.TRAI_GIAM_MA
          ---  ll.LL_GHI_CHU_RIENG  -- c?n ?? ki?m tra BAN CH? ??O và p_ghi_chu_rieng_id
        FROM QLPN.vw_pn_lai_lich_chi_tiet ll
        inner join dm_tinh_trang_pham_nhans ttpn on ttpn.id = ll.LL_TINH_TRANG_ID and ttpn.is_deleted = 0
        WHERE (p_ma_trai_giam IS NULL OR ll.TRAI_GIAM_ID = (select id from dm_trai_giams where tg_ma = p_ma_trai_giam))
          AND (p_phan_doi_id  IS NULL OR ll.phan_doi_id  = p_phan_doi_id)
          AND (p_tinh_trang_id IS NULL OR ll.LL_TINH_TRANG_ID = p_tinh_trang_id)
          AND EXISTS (
                SELECT 1
                FROM QLPN.PN_THI_HANH_AN c
                WHERE c.THA_PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                  AND NVL(c.IS_DELETED, 0) = 0
                  AND (v_tu_ngay  IS NULL OR  c.THA_NGAY_DEN_TRAI  >= v_tu_ngay)
                  AND (v_den_ngay IS NULL OR  c.THA_NGAY_DEN_TRAI  <= v_den_ngay)
          )
    ),
    pn_ban_chi_dao AS (
        -- B??c 2: l?c ch? nh?ng ph?m nhân có ghi chú "BAN CH? ??O"
        -- Dùng LIKE trên chu?i g?c [1,2,3] thay vì CONNECT BY
        -- Wrap b?ng d?u ph?y ?? tránh nh?m ID 1 match "10","11"...
        SELECT /*+ MATERIALIZE */ b.*
        FROM pn_base b
        JOIN QLPN.PN_LAI_LICHS pll
          ON pll.ID = b.PHAM_NHAN_ID
         AND NVL(pll.IS_DELETED, 0) = 0
        WHERE v_ban_chi_dao_id IS NOT NULL
          AND ',' || REPLACE(REPLACE(pll.LL_GHI_CHU_RIENG, '[', ''), ']', '') || ','
              LIKE '%,' || TO_CHAR(v_ban_chi_dao_id) || ',%'
          -- Filter p_ghi_chu_rieng_id c?ng t?i ?ây luôn, tránh subquery EXISTS
          AND (
                p_ghi_chu_rieng_id IS NULL
                OR ',' || REPLACE(REPLACE(pll.LL_GHI_CHU_RIENG, '[', ''), ']', '') || ','
                   LIKE '%,' || TO_CHAR(p_ghi_chu_rieng_id) || ',%'
          )
    ),
    ghi_chu_agg AS (
        -- B??c 3: ch? LISTAGG trên t?p nh? ?ã l?c xong
        SELECT
            x.PHAM_NHAN_ID,
            LISTAGG(gcr.GCR_TEN, '; ')
                WITHIN GROUP (ORDER BY gcr.GCR_TEN) AS GHI_CHU_RIENG
        FROM (
            -- Tách chu?i ID b?ng CONNECT BY nh?ng ch? trên t?p nh? (vài tr?m dòng)
            SELECT
                p.PHAM_NHAN_ID,
                TRIM(REGEXP_SUBSTR(
                    REPLACE(REPLACE(pll.LL_GHI_CHU_RIENG, '[', ''), ']', ''),
                    '[^,]+', 1, lv.COLUMN_VALUE
                )) AS CHI_CHU_RIENG_ID
            FROM pn_ban_chi_dao p
            JOIN QLPN.PN_LAI_LICHS pll
              ON pll.ID = p.PHAM_NHAN_ID
             AND NVL(pll.IS_DELETED, 0) = 0
            JOIN TABLE(
                CAST(
                    MULTISET(
                        SELECT LEVEL FROM DUAL
                        CONNECT BY LEVEL <= REGEXP_COUNT(
                            REPLACE(REPLACE(pll.LL_GHI_CHU_RIENG, '[', ''), ']', ''), ','
                        ) + 1
                    ) AS SYS.ODCINUMBERLIST
                )
            ) lv ON 1 = 1
            WHERE TRIM(REGEXP_SUBSTR(
                    REPLACE(REPLACE(pll.LL_GHI_CHU_RIENG, '[', ''), ']', ''),
                    '[^,]+', 1, lv.COLUMN_VALUE
                )) IS NOT NULL
        ) x
        JOIN QLPN.DM_GHI_CHU_RIENGS gcr
          ON gcr.ID = TO_NUMBER(x.CHI_CHU_RIENG_ID)
         AND NVL(gcr.IS_DELETED, 0) = 0
        GROUP BY x.PHAM_NHAN_ID
    ),
    ranked_rows AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY ORDER_HOTEN(p.HO_TEN) NULLS LAST) AS rn_all,
            COUNT(*) OVER ()                                                AS total_count,
            p.PHAM_NHAN_ID,
            p.so_ho_so,
            p.ho_ten,
            p.nam_sinh,
            p.gioi_tinh,
            p.noi_thuong_tru_day_du,
            p.toi_danh,
            TO_CHAR(p.ngay_bat_an_phat, 'DD/MM/YYYY') AS ngay_bat_an_phat,
            p.an_phat,
            TO_CHAR(p.ngay_den_trai,    'DD/MM/YYYY') AS ngay_den_trai,
            TO_CHAR(p.ngay_het_an,      'DD/MM/YYYY') AS ngay_het_an,
            gc.GHI_CHU_RIENG,
            tinh_trang,
            NVL(TRIM(CAST(p.PHAN_DOI AS VARCHAR2(4000))), '') ||
            CASE WHEN p.PHAN_DOI IS NOT NULL AND p.PHAN_TRAI IS NOT NULL
                 THEN u', ' ELSE u'' END ||
            NVL(TRIM(CAST(p.PHAN_TRAI AS VARCHAR2(4000))), '') AS PHAN_DOI
        FROM pn_ban_chi_dao p
        LEFT JOIN ghi_chu_agg gc ON gc.PHAM_NHAN_ID = p.PHAM_NHAN_ID
--        LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS b
--               ON b.ID = p.LL_TINH_TRANG_ID
--              AND NVL(b.IS_DELETED, 0) = 0
    )
    SELECT
        rn_all,
        total_count,
        so_ho_so,
        ho_ten,
        nam_sinh,
        gioi_tinh,
        noi_thuong_tru_day_du,
        toi_danh,
        ngay_bat_an_phat,
        an_phat,
        ngay_den_trai,
        ngay_het_an,
        GHI_CHU_RIENG,
        tinh_trang,
        PHAN_DOI
    FROM ranked_rows
    WHERE rn_all > v_skip
      AND (v_limit = 0 OR rn_all <= v_skip + v_limit)
    ORDER BY rn_all;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_BAO_CAO_PHAM_NHAN_BAN_CHI_DAO;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_PHAN_LOAI_PHAM_NHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_PHAN_LOAI_PHAM_NHAN" (
    p_trai_giam_id       IN  NUMBER   DEFAULT NULL,
    p_den_trai_tu_ngay   IN  VARCHAR2 DEFAULT NULL,
    p_den_trai_den_ngay  IN  VARCHAR2 DEFAULT NULL,
    p_phan_loai_tu_ngay  IN  VARCHAR2 DEFAULT NULL,
    p_phan_loai_den_ngay IN  VARCHAR2 DEFAULT NULL,
    p_tinh_trang_id      IN  NUMBER   DEFAULT NULL,
    p_phan_doi_id        IN  NUMBER   DEFAULT NULL,
    p_loai_quyet_dinh    IN  NUMBER   DEFAULT NULL
) AS
    v_den_trai_tu    DATE;
    v_den_trai_den   DATE;
    v_phan_loai_tu   DATE;
    v_phan_loai_den  DATE;
    v_trai_giam_id   NUMBER;
    c1               SYS_REFCURSOR;
BEGIN
    IF p_den_trai_tu_ngay IS NULL OR TRIM(p_den_trai_tu_ngay) = '' THEN
        v_den_trai_tu := NULL;
    ELSE
        v_den_trai_tu := TRUNC(TO_DATE(TRIM(p_den_trai_tu_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_den_trai_den_ngay IS NULL OR TRIM(p_den_trai_den_ngay) = '' THEN
        v_den_trai_den := NULL;
    ELSE
        v_den_trai_den := TRUNC(TO_DATE(TRIM(p_den_trai_den_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_phan_loai_tu_ngay IS NULL OR TRIM(p_phan_loai_tu_ngay) = '' THEN
        v_phan_loai_tu := NULL;
    ELSE
        v_phan_loai_tu := TRUNC(TO_DATE(TRIM(p_phan_loai_tu_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_phan_loai_den_ngay IS NULL OR TRIM(p_phan_loai_den_ngay) = '' THEN
        v_phan_loai_den := NULL;
    ELSE
        v_phan_loai_den := TRUNC(TO_DATE(TRIM(p_phan_loai_den_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_trai_giam_id IS NULL THEN
        v_trai_giam_id := NULL;
    ELSE
        BEGIN
            SELECT tg.ID
            INTO v_trai_giam_id
            FROM QLPN.DM_TRAI_GIAMS tg
            WHERE NVL(tg.IS_DELETED, 0) = 0
              AND (tg.ID = p_trai_giam_id
                   OR tg.TG_MA = TRIM(TO_CHAR(p_trai_giam_id)))
            FETCH FIRST 1 ROW ONLY;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20002,
                    'Không tìm th?y tr?i giam (mã/ID): ' || p_trai_giam_id
                );
        END;
    END IF;

    OPEN c1 FOR
    WITH
    ll_scope AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            rt.PHAM_NHAN_ID AS ll_id,
            rt.LL_SO_HO_SO_LAN_DAU,
            rt.LL_HO_TEN,
            rt.HO_TEN_ORDER,
            rt.LL_NGAY_SINH,
            rt.LL_SO_TIEN_AN,
            rt.LL_GHI_CHU_RIENG,
            rt.LL_GHI_CHU_CHI_TIET,
            rt.LL_DM_GIOI_TINH_ID,
            rt.LL_DIA_CHI_THUONG_TRU,
            rt.LL_DIA_CHI_THUONG_TRU_WARD,
            rt.LL_DIA_CHI_THUONG_TRU_PROVICE,
            rt.LL_PHAN_DOI_ID,
            rt.LL_PHAN_TRAI_ID,
            rt.THA_NGAY_BAT,
            rt.THA_TOI_DANH_NAMES,
            rt.THA_AN_PHAT,
            rt.THA_NGAY_DEN_TRAI,
            rt.THA_NGAY_HET_HAN
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        WHERE NVL(rt.IS_DELETED, 0) = 0
          AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
          AND (p_tinh_trang_id IS NULL OR rt.LL_TINH_TRANG_ID = p_tinh_trang_id)
          AND (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (
              (v_den_trai_tu IS NULL AND v_den_trai_den IS NULL)
              OR (
                  rt.THA_TOI_DANH_NAMES IS NOT NULL
                  AND rt.THA_NGAY_DEN_TRAI IS NOT NULL
                  AND (v_den_trai_tu IS NULL OR rt.THA_NGAY_DEN_TRAI >= v_den_trai_tu)
                  AND (v_den_trai_den IS NULL OR rt.THA_NGAY_DEN_TRAI < v_den_trai_den + 1)
              )
          )
    ),
    ll_pl AS (
        SELECT
            x.PHAM_NHAN_ID,
            x.NGAY_PHAN_LOAI,
            x.LOAI_PHAN_LOAI_ID,
            x.TU_LOAI_ID,
            x.DEN_LOAI_ID,
            x.ll_id,
            x.LL_SO_HO_SO_LAN_DAU,
            x.LL_HO_TEN,
            x.HO_TEN_ORDER,
            x.LL_NGAY_SINH,
            x.LL_SO_TIEN_AN,
            x.LL_GHI_CHU_RIENG,
            x.LL_GHI_CHU_CHI_TIET,
            x.LL_DM_GIOI_TINH_ID,
            x.LL_DIA_CHI_THUONG_TRU,
            x.LL_DIA_CHI_THUONG_TRU_WARD,
            x.LL_DIA_CHI_THUONG_TRU_PROVICE,
            x.LL_PHAN_DOI_ID,
            x.LL_PHAN_TRAI_ID,
            x.THA_NGAY_BAT,
            x.THA_TOI_DANH_NAMES,
            x.THA_AN_PHAT,
            x.THA_NGAY_DEN_TRAI,
            x.THA_NGAY_HET_HAN
        FROM (
            SELECT /*+ LEADING(ls pl) USE_NL(ls pl) INDEX(pl IX_PHANLOAI_DEL_PN_NGAY) */
                pl.PHAM_NHAN_ID,
                pl.NGAY_PHAN_LOAI,
                pl.LOAI_PHAN_LOAI_ID,
                pl.TU_LOAI_ID,
                pl.DEN_LOAI_ID,
                ls.ll_id,
                ls.LL_SO_HO_SO_LAN_DAU,
                ls.LL_HO_TEN,
                ls.HO_TEN_ORDER,
                ls.LL_NGAY_SINH,
                ls.LL_SO_TIEN_AN,
                ls.LL_GHI_CHU_RIENG,
                ls.LL_GHI_CHU_CHI_TIET,
                ls.LL_DM_GIOI_TINH_ID,
                ls.LL_DIA_CHI_THUONG_TRU,
                ls.LL_DIA_CHI_THUONG_TRU_WARD,
                ls.LL_DIA_CHI_THUONG_TRU_PROVICE,
                ls.LL_PHAN_DOI_ID,
                ls.LL_PHAN_TRAI_ID,
                ls.THA_NGAY_BAT,
                ls.THA_TOI_DANH_NAMES,
                ls.THA_AN_PHAT,
                ls.THA_NGAY_DEN_TRAI,
                ls.THA_NGAY_HET_HAN,
                ROW_NUMBER() OVER (
                    PARTITION BY pl.PHAM_NHAN_ID
                    ORDER BY NVL(pl.NGAY_PHAN_LOAI, pl.CREATION_TIME) DESC NULLS LAST,
                             pl.ID DESC
                ) AS rn
            FROM ll_scope ls
            INNER JOIN QLPN.PHAN_LOAIS pl
                ON pl.PHAM_NHAN_ID = ls.ll_id
               AND NVL(pl.IS_DELETED, 0) = 0
               AND (p_loai_quyet_dinh IS NULL OR pl.LOAI_PHAN_LOAI_ID = p_loai_quyet_dinh)
               AND (v_phan_loai_tu IS NULL OR pl.NGAY_PHAN_LOAI >= v_phan_loai_tu)
               AND (v_phan_loai_den IS NULL OR pl.NGAY_PHAN_LOAI < v_phan_loai_den + 1)
        ) x
        WHERE x.rn = 1
    ),
    base AS (
        SELECT
            lp.PHAM_NHAN_ID           AS pn_id,
            lp.LL_SO_HO_SO_LAN_DAU    AS so_hsld,
            lp.LL_HO_TEN              AS ho_ten,
            lp.HO_TEN_ORDER           AS ho_ten_order,
            CASE
                WHEN lp.LL_NGAY_SINH IS NOT NULL THEN
                    CASE
                        WHEN REGEXP_LIKE(TO_CHAR(lp.LL_NGAY_SINH), '^\d{4}$')
                        THEN TO_NUMBER(TO_CHAR(lp.LL_NGAY_SINH))
                        WHEN LENGTH(TO_CHAR(lp.LL_NGAY_SINH)) >= 4
                             AND REGEXP_LIKE(SUBSTR(TO_CHAR(lp.LL_NGAY_SINH), -4), '^\d{4}$')
                        THEN TO_NUMBER(SUBSTR(TO_CHAR(lp.LL_NGAY_SINH), -4))
                        WHEN REGEXP_LIKE(TO_CHAR(lp.LL_NGAY_SINH), '\d{4}')
                        THEN TO_NUMBER(REGEXP_SUBSTR(TO_CHAR(lp.LL_NGAY_SINH), '\d{4}', 1, 1))
                        ELSE NULL
                    END
                ELSE NULL
            END                       AS nam_sinh,
            gt.GT_TEN                 AS gioi_tinh,
            CASE
                WHEN NULLIF(TRIM(lp.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                  OR NULLIF(TRIM(dxp.XP_TEN), u'') IS NOT NULL
                  OR NULLIF(TRIM(dttp.TTP_TEN), u'') IS NOT NULL
                THEN TRIM(
                    NVL(NULLIF(TRIM(lp.LL_DIA_CHI_THUONG_TRU), u''), u'')
                    || CASE
                        WHEN NULLIF(TRIM(dxp.XP_TEN), u'') IS NOT NULL THEN
                            CASE
                                WHEN NULLIF(TRIM(lp.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || dxp.XP_TEN
                                ELSE dxp.XP_TEN
                            END
                        ELSE u''
                       END
                    || CASE
                        WHEN NULLIF(TRIM(dttp.TTP_TEN), u'') IS NOT NULL THEN
                            CASE
                                WHEN NULLIF(TRIM(lp.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                  OR NULLIF(TRIM(dxp.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || dttp.TTP_TEN
                                ELSE dttp.TTP_TEN
                            END
                        ELSE u''
                       END
                )
                ELSE NULL
            END                       AS noi_dktt,
            lp.LL_SO_TIEN_AN          AS so_tien_an,
            lp.THA_NGAY_BAT           AS ngay_bat,
            lp.THA_TOI_DANH_NAMES     AS toi_danh,
            lp.THA_AN_PHAT            AS an_phat,
            lp.THA_NGAY_DEN_TRAI      AS ngay_den_trai,
            lp.THA_NGAY_HET_HAN       AS ngay_het_han,
            lp.NGAY_PHAN_LOAI         AS ngay_phan_loai,
            lp.LOAI_PHAN_LOAI_ID,
            lp.TU_LOAI_ID,
            lp.DEN_LOAI_ID,
            pd.PD_TEN                 AS phan_doi,
            pt.PT_TEN                 AS phan_trai,
            lp.LL_GHI_CHU_RIENG       AS ll_ghi_chu_rieng,
            lp.LL_GHI_CHU_CHI_TIET    AS ll_ghi_chu_chi_tiet
        FROM ll_pl lp
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = lp.LL_DM_GIOI_TINH_ID
           AND NVL(gt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XA_PHUONG dxp
            ON dxp.ID = lp.LL_DIA_CHI_THUONG_TRU_WARD
           AND NVL(dxp.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO dttp
            ON dttp.ID = lp.LL_DIA_CHI_THUONG_TRU_PROVICE
           AND NVL(dttp.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_DOIS pd
            ON pd.ID = lp.LL_PHAN_DOI_ID
           AND NVL(pd.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_TRAIS pt
            ON pt.ID = lp.LL_PHAN_TRAI_ID
           AND NVL(pt.IS_DELETED, 0) = 0
    ),
    xep_loai_agg AS (
        SELECT /*+ USE_NL(lp x) INDEX(x IX_XEPLOAI_DEL_PN_NAM) */
            x.PHAM_NHAN_ID AS pn_id,
            LISTAGG(
                TO_NCHAR(x.XEP_LOAI_NAM) || u': ?N: ' ||
                NVL(dn_dm.XLCT_TEN, TO_NCHAR(x.XEP_LOAI_6_THANG_DAU_NAM)) ||
                u'; CN: ' ||
                NVL(cn_dm.XLCT_TEN, TO_NCHAR(x.XEP_LOAI_6_THANG_CUOI_NAM)) ||
                u'; C? n?m: ' ||
                CASE
                    WHEN NULLIF(TRIM(TO_NCHAR(x.XEP_LOAI_CA_NAM)), u'') IS NULL
                    THEN u'Ch?a ?? TGXL'
                    ELSE NVL(y_dm.XLCT_TEN, TO_NCHAR(x.XEP_LOAI_CA_NAM))
                END,
                u' '
            ) WITHIN GROUP (ORDER BY x.XEP_LOAI_NAM) AS TONG_HOP_XEP_LOAI
        FROM QLPN.XEP_LOAIS x
        INNER JOIN ll_pl lp
            ON lp.PHAM_NHAN_ID = x.PHAM_NHAN_ID
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dn_dm
            ON dn_dm.ID = CASE
                              WHEN REGEXP_LIKE(TRIM(TO_NCHAR(x.XEP_LOAI_6_THANG_DAU_NAM)), '^[0-9]+$')
                              THEN TO_NUMBER(TRIM(TO_NCHAR(x.XEP_LOAI_6_THANG_DAU_NAM)))
                              ELSE NULL
                           END
           AND NVL(dn_dm.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS cn_dm
            ON cn_dm.ID = CASE
                              WHEN REGEXP_LIKE(TRIM(TO_NCHAR(x.XEP_LOAI_6_THANG_CUOI_NAM)), '^[0-9]+$')
                              THEN TO_NUMBER(TRIM(TO_NCHAR(x.XEP_LOAI_6_THANG_CUOI_NAM)))
                              ELSE NULL
                           END
           AND NVL(cn_dm.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS y_dm
            ON y_dm.ID = CASE
                             WHEN REGEXP_LIKE(TRIM(TO_NCHAR(x.XEP_LOAI_CA_NAM)), '^[0-9]+$')
                             THEN TO_NUMBER(TRIM(TO_NCHAR(x.XEP_LOAI_CA_NAM)))
                             ELSE NULL
                           END
           AND NVL(y_dm.IS_DELETED, 0) = 0
        WHERE NVL(x.IS_DELETED, 0) = 0
          AND x.XEP_LOAI_NAM IS NOT NULL
        GROUP BY x.PHAM_NHAN_ID
    ),
    result_rows AS (
        SELECT
            b.so_hsld,
            b.ho_ten,
            b.ho_ten_order,
            b.nam_sinh,
            b.gioi_tinh,
            b.noi_dktt,
            b.toi_danh,
            b.so_tien_an,
            b.ngay_bat,
            b.an_phat,
            b.pn_id,
            b.ngay_den_trai,
            b.ngay_het_han,
            b.ngay_phan_loai,
            b.phan_doi,
            b.phan_trai,
            b.ll_ghi_chu_chi_tiet,
            b.LOAI_PHAN_LOAI_ID,
            b.TU_LOAI_ID,
            b.DEN_LOAI_ID,
            NVL(QLPN.PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(b.pn_id), u'Không') AS da_giam,
            NVL(
                QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(b.pn_id, TRUNC(SYSDATE)),
                u''
            ) AS da_chap_hanh,
            NVL(
                QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(b.pn_id, TRUNC(SYSDATE)),
                u''
            ) AS con_lai,
            NVL(xla.TONG_HOP_XEP_LOAI, u'') AS tong_hop_xep_loai,
            mpl.MPL_TEN AS loai_quyet_dinh,
            tu_plgg.PLGG_TEN AS tu_loai,
            den_plgg.PLGG_TEN AS den_loai,
            SUBSTR(
                REPLACE(
                    QLPN.FN_GET_LIST_GHI_CHU_RIENG(CAST(b.ll_ghi_chu_rieng AS NVARCHAR2(2000))),
                    u'; ',
                    u', '
                ),
                1,
                2000
            ) AS ghi_chu_rieng_ten
        FROM base b
        LEFT JOIN QLPN.DM_MA_PHAN_LOAIES mpl
            ON mpl.ID = b.LOAI_PHAN_LOAI_ID
           AND NVL(mpl.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_LOAI_GIAM_GIUS tu_plgg
            ON tu_plgg.ID = b.TU_LOAI_ID
           AND NVL(tu_plgg.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_LOAI_GIAM_GIUS den_plgg
            ON den_plgg.ID = b.DEN_LOAI_ID
           AND NVL(den_plgg.IS_DELETED, 0) = 0
        LEFT JOIN xep_loai_agg xla
            ON xla.pn_id = b.pn_id
    )
    SELECT
        r.so_hsld                                              AS SO_HSLD,
        r.ho_ten                                               AS HO_TEN,
        TO_CHAR(r.nam_sinh)                                    AS NGAY_SINH,
        r.gioi_tinh                                            AS GIOI_TINH,
        r.noi_dktt                                             AS NOI_DKTT,
        r.toi_danh                                             AS TOI_DANH,
        r.so_tien_an                                           AS SO_TIEN_AN,
        CASE WHEN r.ngay_bat IS NULL THEN NULL
             ELSE TO_CHAR(r.ngay_bat, 'DD/MM/YYYY')
        END                                                    AS NGAY_BAT,
        r.an_phat                                              AS AN_PHAT,
        r.da_giam                                              AS DA_GIAM,
        r.da_chap_hanh                                         AS DA_CHAP_HANH,
        r.con_lai                                              AS CON_LAI,
        r.tong_hop_xep_loai                                    AS TONG_HOP_XEP_LOAI,
        CASE WHEN r.ngay_den_trai IS NULL THEN NULL
             ELSE TO_CHAR(r.ngay_den_trai, 'DD/MM/YYYY')
        END                                                    AS NGAY_DEN_TRAI,
        CASE WHEN r.ngay_het_han IS NULL THEN NULL
             ELSE TO_CHAR(r.ngay_het_han, 'DD/MM/YYYY')
        END                                                    AS NGAY_HET_HAN,
        CASE WHEN r.ngay_phan_loai IS NULL THEN NULL
             ELSE TO_CHAR(r.ngay_phan_loai, 'DD/MM/YYYY')
        END                                                    AS NGAY_PHAN_LOAI,
        r.loai_quyet_dinh                                      AS LOAI_QUYET_DINH,
        r.tu_loai                                              AS TU_LOAI,
        r.den_loai                                             AS DEN_LOAI,
        CASE
            WHEN r.phan_doi IS NOT NULL AND r.phan_trai IS NOT NULL THEN r.phan_doi || u', ' || r.phan_trai
            WHEN r.phan_doi IS NOT NULL THEN r.phan_doi
            WHEN r.phan_trai IS NOT NULL THEN r.phan_trai
            ELSE NULL
        END                                                    AS PHAN_DOI_PHAN_TRAI,
        r.phan_doi                                             AS PHAN_DOI,
        r.phan_trai                                            AS PHAN_TRAI,
        r.ghi_chu_rieng_ten                                    AS GHI_CHU_RIENG,
        r.ll_ghi_chu_chi_tiet                                  AS GHI_CHU_CHI_TIET
    FROM result_rows r
    ORDER BY r.ho_ten_order;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_BAO_CAO_PHAN_LOAI_PHAM_NHAN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_PHAN_LOAI_PHAM_NHAN_2
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_PHAN_LOAI_PHAM_NHAN_2" (
    p_trai_giam_id       IN  NUMBER   DEFAULT NULL,
    p_den_trai_tu_ngay   IN  VARCHAR2 DEFAULT NULL,
    p_den_trai_den_ngay  IN  VARCHAR2 DEFAULT NULL,
    p_phan_loai_tu_ngay  IN  VARCHAR2 DEFAULT NULL,
    p_phan_loai_den_ngay  IN  VARCHAR2 DEFAULT NULL,
    p_tinh_trang_id      IN  NUMBER   DEFAULT NULL,
    p_phan_doi_id        IN  NUMBER   DEFAULT NULL,
    p_loai_quyet_dinh    IN  NUMBER   DEFAULT NULL
) AS
    v_den_trai_tu   DATE;
    v_den_trai_den  DATE;
    v_phan_loai_tu  DATE;
    v_phan_loai_den  DATE;
    C1              SYS_REFCURSOR;
BEGIN

    -- Parse ngày
    IF p_den_trai_tu_ngay IS NULL OR TRIM(p_den_trai_tu_ngay) = '' THEN
        v_den_trai_tu := NULL;
    ELSE
        v_den_trai_tu := TO_DATE(TRIM(p_den_trai_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_den_trai_den_ngay IS NULL OR TRIM(p_den_trai_den_ngay) = '' THEN
        v_den_trai_den := NULL;
    ELSE
        v_den_trai_den := TO_DATE(TRIM(p_den_trai_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_phan_loai_tu_ngay IS NULL OR TRIM(p_phan_loai_tu_ngay) = '' THEN
        v_phan_loai_tu := NULL;
    ELSE
        v_phan_loai_tu := TO_DATE(TRIM(p_phan_loai_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_phan_loai_den_ngay IS NULL OR TRIM(p_phan_loai_den_ngay) = '' THEN
        v_phan_loai_den := NULL;
    ELSE
        v_phan_loai_den := TO_DATE(TRIM(p_phan_loai_den_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN C1 FOR
    WITH
    vw_one AS (
        SELECT v.*,
               ROW_NUMBER() OVER (
                   PARTITION BY v.PHAM_NHAN_ID
                   ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
                            v.CREATION_TIME DESC NULLS LAST
               ) AS rn
        FROM VW_PN_LAI_LICH_CHI_TIET v
        WHERE NVL(v.IS_DELETED, 0) = 0
    ),
    phan_loai_one AS (
        SELECT
            pl.PHAM_NHAN_ID,
            pl.NGAY_PHAN_LOAI,
            pl.LOAI_PHAN_LOAI_ID,
            pl.TU_LOAI_ID,
            pl.DEN_LOAI_ID,
            ROW_NUMBER() OVER (
                PARTITION BY pl.PHAM_NHAN_ID
                ORDER BY NVL(pl.NGAY_PHAN_LOAI, pl.CREATION_TIME) DESC NULLS LAST,
                         pl.ID DESC
            ) AS rn
        FROM PHAN_LOAIS pl
        WHERE NVL(pl.IS_DELETED, 0) = 0
    ),
    base AS (
        SELECT
            v.PHAM_NHAN_ID           AS pn_id,
            v.SO_HO_SO               AS so_hsld,
            v.HO_TEN                 AS ho_ten,
            v.NGAY_SINH              AS ngay_sinh,
            v.GIOI_TINH              AS gioi_tinh,
            v.NOI_THUONG_TRU_DAY_DU  AS noi_dktt,
            v.SO_TIEN_AN             AS so_tien_an,
            v.NGAY_BAT_AN_PHAT       AS ngay_bat,
            v.TOI_DANH               AS toi_danh,
            v.TOI_DANH_ID            AS toi_danh_id,
            v.AN_PHAT                AS an_phat,
            v.NGAY_DEN_TRAI          AS ngay_den_trai,
            v.NGAY_HET_AN            AS ngay_het_han,
            pl.NGAY_PHAN_LOAI        AS ngay_phan_loai,
            pl.LOAI_PHAN_LOAI_ID,
            pl.TU_LOAI_ID,
            pl.DEN_LOAI_ID,
            v.PHAN_DOI                AS phan_doi,
            v.PHAN_TRAI               AS phan_trai
        FROM vw_one v
        INNER JOIN phan_loai_one pl
            ON pl.PHAM_NHAN_ID = v.PHAM_NHAN_ID AND pl.rn = 1
        WHERE v.rn = 1
          AND (p_trai_giam_id IS NULL OR v.TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tinh_trang_id IS NULL OR v.LL_TINH_TRANG_ID = p_tinh_trang_id)
          AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)
          AND (p_loai_quyet_dinh IS NULL OR pl.LOAI_PHAN_LOAI_ID = p_loai_quyet_dinh)
          AND (v_phan_loai_tu IS NULL OR TRUNC(pl.NGAY_PHAN_LOAI) >= v_phan_loai_tu)
          AND (v_phan_loai_den IS NULL OR TRUNC(pl.NGAY_PHAN_LOAI) <= v_phan_loai_den)
          AND (v_den_trai_tu IS NULL OR TRUNC(v.NGAY_DEN_TRAI) >= v_den_trai_tu)
          AND (v_den_trai_den IS NULL OR TRUNC(v.NGAY_DEN_TRAI) <= v_den_trai_den)
    ),
    pn_ids AS (
        SELECT DISTINCT b.pn_id
        FROM base b
    ),
    xep_loai_agg AS (
        SELECT
            x.PHAM_NHAN_ID AS pn_id,
            LISTAGG(
                TO_NCHAR(x.XEP_LOAI_NAM) || u': ?N: ' ||
                NVL(dn_dm.XLCT_TEN, TO_NCHAR(x.XEP_LOAI_6_THANG_DAU_NAM)) ||
                u'; CN: ' ||
                NVL(cn_dm.XLCT_TEN, TO_NCHAR(x.XEP_LOAI_6_THANG_CUOI_NAM)) ||
                u'; C? n?m: ' ||
                CASE
                    WHEN NULLIF(TRIM(TO_NCHAR(x.XEP_LOAI_CA_NAM)), u'') IS NULL
                    THEN u'Ch?a ?? TGXL'
                    ELSE NVL(y_dm.XLCT_TEN, TO_NCHAR(x.XEP_LOAI_CA_NAM))
                END,
                u' '
            ) WITHIN GROUP (ORDER BY x.XEP_LOAI_NAM) AS TONG_HOP_XEP_LOAI
        FROM QLPN.XEP_LOAIS x
        JOIN pn_ids i
            ON i.pn_id = x.PHAM_NHAN_ID
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dn_dm
            ON dn_dm.ID = CASE
                              WHEN REGEXP_LIKE(TRIM(TO_NCHAR(x.XEP_LOAI_6_THANG_DAU_NAM)), '^[0-9]+$')
                              THEN TO_NUMBER(TRIM(TO_NCHAR(x.XEP_LOAI_6_THANG_DAU_NAM)))
                              ELSE NULL
                           END
           AND NVL(dn_dm.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS cn_dm
            ON cn_dm.ID = CASE
                              WHEN REGEXP_LIKE(TRIM(TO_NCHAR(x.XEP_LOAI_6_THANG_CUOI_NAM)), '^[0-9]+$')
                              THEN TO_NUMBER(TRIM(TO_NCHAR(x.XEP_LOAI_6_THANG_CUOI_NAM)))
                              ELSE NULL
                           END
           AND NVL(cn_dm.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS y_dm
            ON y_dm.ID = CASE
                             WHEN REGEXP_LIKE(TRIM(TO_NCHAR(x.XEP_LOAI_CA_NAM)), '^[0-9]+$')
                             THEN TO_NUMBER(TRIM(TO_NCHAR(x.XEP_LOAI_CA_NAM)))
                             ELSE NULL
                          END
           AND NVL(y_dm.IS_DELETED, 0) = 0
        WHERE NVL(x.IS_DELETED, 0) = 0
          AND x.XEP_LOAI_NAM IS NOT NULL
        GROUP BY x.PHAM_NHAN_ID
    )
    SELECT
        b.so_hsld              AS SO_HSLD,
        b.HO_TEN               AS HO_TEN,
        b.NGAY_SINH            AS NGAY_SINH,
        b.GIOI_TINH            AS GIOI_TINH,
        b.NOI_DKTT             AS NOI_DKTT,
        b.TOI_DANH             AS TOI_DANH,
        b.SO_TIEN_AN           AS SO_TIEN_AN,
        b.NGAY_BAT              AS NGAY_BAT,
        b.AN_PHAT               AS AN_PHAT,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(b.pn_id), u'Kh\00f4ng') AS DA_GIAM,
        NVL(mtg_da.MTG_TITLE, '')                           AS DA_CHAP_HANH,
        NVL(mtg_con.MTG_TITLE, '')                          AS CON_LAI,
        NVL(xla.TONG_HOP_XEP_LOAI, '')                      AS TONG_HOP_XEP_LOAI,
        b.NGAY_DEN_TRAI        AS NGAY_DEN_TRAI,
        b.NGAY_HET_HAN         AS NGAY_HET_HAN,
        b.NGAY_PHAN_LOAI       AS NGAY_PHAN_LOAI,
        mpl.MPL_TEN            AS LOAI_QUYET_DINH,
        tu_plgg.PLGG_TEN       AS TU_LOAI,
        den_plgg.PLGG_TEN      AS DEN_LOAI,

        -- ? CH? S?A DUY NH?T CH? NÀY
        TRIM(
            NVL(TO_CHAR(b.PHAN_DOI), '') ||
            CASE 
                WHEN b.PHAN_DOI IS NOT NULL AND b.PHAN_TRAI IS NOT NULL THEN ', ' 
                ELSE '' 
            END ||
            NVL(b.PHAN_TRAI, '')
        ) AS PHAN_DOI

    FROM base b
    LEFT JOIN DM_MA_PHAN_LOAIES mpl
        ON mpl.ID = b.LOAI_PHAN_LOAI_ID AND NVL(mpl.IS_DELETED, 0) = 0
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS tu_plgg
        ON tu_plgg.ID = b.TU_LOAI_ID AND NVL(tu_plgg.IS_DELETED, 0) = 0
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS den_plgg
        ON den_plgg.ID = b.DEN_LOAI_ID AND NVL(den_plgg.IS_DELETED, 0) = 0
    LEFT JOIN xep_loai_agg xla
        ON xla.pn_id = b.pn_id
    LEFT JOIN PN_THI_HANH_AN ptha
        ON ptha.THA_PNLAI_LICH_ID = b.pn_id
       AND NVL(ptha.IS_DELETED, 0) = 0
    LEFT JOIN DM_MA_THOI_GIANS mtg_da
        ON TO_CHAR(mtg_da.MTG_MA) = TO_CHAR(ptha.THA_THOI_GIAN_DA_CHAP_HANH)
       AND NVL(mtg_da.IS_DELETED, 0) = 0
    LEFT JOIN DM_MA_THOI_GIANS mtg_con
        ON TO_CHAR(mtg_con.MTG_MA) = TO_CHAR(ptha.THA_THOI_GIAN_CON_LAI)
       AND NVL(mtg_con.IS_DELETED, 0) = 0
    ORDER BY b.HO_TEN;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_BAO_CAO_PHAN_LOAI_PHAM_NHAN_2;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_PN_DE_NGHI_DAC_XA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_PN_DE_NGHI_DAC_XA" (
--    p_pn_ids            IN  VARCHAR2   DEFAULT NULL,
    p_ma_trai_giam      IN  NVARCHAR2  DEFAULT NULL
) AS
    c1 SYS_REFCURSOR;
    v_trai_giam_id NUMBER;
BEGIN
    -- Resolve TG_MA -> ID m?t l?n, dùng filter s?m trên RT.LL_TRAI_GIAM_ID
    IF p_ma_trai_giam IS NOT NULL THEN
        BEGIN
            SELECT id INTO v_trai_giam_id
            FROM DM_TRAI_GIAMS
            WHERE TG_MA = p_ma_trai_giam AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION WHEN NO_DATA_FOUND THEN v_trai_giam_id := NULL;
        END;
    END IF;

    OPEN c1 FOR
    WITH
    pn_ids_input AS (
            SELECT PN_ID AS pn_id
		    FROM QLPN.GTT_PN_IDS
    ),
    pn_dac_xa AS (
        SELECT pdx.PNLAI_LICH_ID AS pn_lai_lich_id,
               pdx.DX_XEP_LOAI_CAI_TAO,
               pdx.DX_NGAY_XET AS ngay_xet
        FROM PN_DAC_XAS pdx
        INNER JOIN pn_ids_input i
            ON i.pn_id = pdx.PNLAI_LICH_ID
        INNER JOIN PN_LAI_LICH_CHI_TIET_RT rt_f
            ON rt_f.PHAM_NHAN_ID = pdx.PNLAI_LICH_ID
           AND NVL(rt_f.IS_DELETED, 0) = 0
           AND NVL(rt_f.LL_IS_DELETED, 0) = 0
           AND NVL(rt_f.THA_IS_DELETED, 0) = 0
           AND (p_ma_trai_giam IS NULL OR rt_f.LL_TRAI_GIAM_ID = v_trai_giam_id)
        WHERE NVL(pdx.IS_DELETED, 0) = 0
    ),
    -- Thông tin PN t? VW + LL_GIOI_TINH_ID, LL_GHI_CHU_CHI_TIET t? PN_LAI_LICHS
    base AS (
        SELECT
            v.PHAM_NHAN_ID,
            v.HO_TEN,
            v.CCCD,
            v.GIOI_TINH,
            ll.LL_DM_GIOI_TINH_ID AS GIOI_TINH_ID,
            TO_CHAR(v.NGAY_SINH) AS NGAY_SINH,
            v.NAM_SINH,
            v.NOI_THUONG_TRU_DAY_DU,
            v.NOI_THA_VE_CU_TRU,
            ll.LL_NOI_THA_VE_CU_TRU_WARD,
            ll.LL_NOI_THA_VE_CU_TRU_PROVICE,
            v.NGHE_NGHIEP,
            v.NGAY_BAT_AN_PHAT,
            v.TOI_DANH,
            v.AN_PHAT,
            v.SO_TIEN_AN,
            v.SO_TIEN_SU,
            v.MUC_AN_ID,
            v.TRAI_GIAM_ID,
            v.TRAI_GIAM,
            v.PHAN_DOI_ID,
            v.PHAN_DOI,
            v.PHAN_TRAI,
            v.QUOC_TICH_ID,
            ll.LL_GHI_CHU_RIENG,
            rt.THA_CO_QUAN_LAP_ID,
            p.ngay_xet,
            ll.LL_GHI_CHU_CHI_TIET AS GHI_CHU_CHI_TIET,
            p.DX_XEP_LOAI_CAI_TAO,
            xlt.XLCT_TEN AS DX_XEP_LOAI_CAI_TAO_TEN,
            v.TEN_KHAC,
            v.NGUYEN_QUAN,
            v.THOI_GIAN_TAM_GIAM,
            v.SO_BAN_AN,
            v.NGAY_BAN_AN,
            v.SO_QD_THA,
            v.NGAY_QD_THA,
            v.TOA_XU_TEN,
            v.TOA_XU_DIA_PHUONG,
            v.CO_QUAN_QD_THA,
            v.TOA_QD_THA_DIA_PHUONG

        FROM pn_dac_xa p
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = p.pn_lai_lich_id
           AND NVL(v.IS_DELETED, 0) = 0
        LEFT JOIN PN_LAI_LICHS ll
            ON ll.ID = v.PHAM_NHAN_ID
           AND NVL(ll.IS_DELETED, 0) = 0
        INNER JOIN PN_LAI_LICH_CHI_TIET_RT rt
            ON rt.PHAM_NHAN_ID = p.pn_lai_lich_id
           AND NVL(rt.IS_DELETED, 0) = 0
           AND NVL(rt.LL_IS_DELETED, 0) = 0
           AND NVL(rt.THA_IS_DELETED, 0) = 0
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xlt ON xlt.ID = p.DX_XEP_LOAI_CAI_TAO AND NVL(xlt.IS_DELETED, 0) = 0
    )
    SELECT
        -- Gi?ng SP_GET_DX_DON_PHAM_NHAN_DAC_XA
        NVL(tg.TG_TEN, bt.TRAI_GIAM)           AS TEN_TRAI,
        NVL(TRIM(bt.HO_TEN), '')               AS HO_TEN,
        NVL(TRIM(CAST(bt.CCCD AS VARCHAR2(255))), '') AS SO_CCCD,
        NULL AS NGAY_CAP_CCCD,
        NULL AS NOI_CAP_CCCD,
        bt.NAM_SINH                            AS NAM_SINH,
        NVL(TRIM(bt.GIOI_TINH), '')            AS GIOI_TINH,
        NVL(CAST(bt.TEN_KHAC AS VARCHAR2(4000)), '') AS TEN_KHAC,
        NVL(CAST(bt.NGUYEN_QUAN AS VARCHAR2(4000)), '') AS NGUYEN_QUAN,
        CASE
            WHEN bt.NGAY_SINH IS NOT NULL AND REGEXP_LIKE(TRIM(bt.NGAY_SINH), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(bt.NGAY_SINH), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN bt.NAM_SINH IS NOT NULL AND bt.NAM_SINH > 0
            THEN TO_CHAR(bt.NAM_SINH)
            WHEN bt.NGAY_SINH IS NOT NULL AND REGEXP_LIKE(TRIM(bt.NGAY_SINH), '^[0-9]{4}$')
            THEN TRIM(bt.NGAY_SINH)
            ELSE NULL
        END                                    AS NGAY_SINH,
        NVL(TRIM(bt.NOI_THUONG_TRU_DAY_DU), '') AS NOI_DKTT,
        NVL(TRIM(bt.NOI_THA_VE_CU_TRU), '')  AS NOI_VE_CU_TRU,
        NVL(CAST(bt.NGHE_NGHIEP AS VARCHAR2(4000)), '')       AS NGHE_NGHIEP,
        TO_CHAR(bt.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT,
        NVL(CAST(bt.TOI_DANH AS VARCHAR2(4000)), '')                 AS TOI_DANH,
        NVL(CAST(bt.AN_PHAT AS VARCHAR2(4000)), '')                  AS AN_PHAT,
        NVL(TRIM(CAST(bt.SO_TIEN_AN AS VARCHAR2(4000))), '0')           AS SO_TIEN_AN,
        NVL(TRIM(CAST(bt.SO_TIEN_SU AS VARCHAR2(4000))), '0')           AS SO_TIEN_SU,
        -- PKG_TINH_AN: gi?m án, ?ã ch?p hành, còn l?i
        NVL(PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(bt.PHAM_NHAN_ID), u'Kh\00f4ng') AS THOI_GIAN_GIAM,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(bt.PHAM_NHAN_ID, bt.ngay_xet), u'') AS THOI_GIAN_DA_CHAP_HANH,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(bt.PHAM_NHAN_ID, bt.ngay_xet), u'') AS THOI_GIAN_CON_LAI,
        NVL(CAST(bt.DX_XEP_LOAI_CAI_TAO_TEN AS VARCHAR2(4000)), '')         AS XEP_LOAI_CHAP_HANH,
        NVL(CAST(FN_GET_LIST_GHI_CHU_RIENG(CAST(bt.LL_GHI_CHU_RIENG AS NVARCHAR2(2000))) AS VARCHAR2(4000)), '') AS TINH_TIET_UU_TIEN,
        NVL(CAST(bt.GHI_CHU_CHI_TIET AS VARCHAR2(4000)), '') AS GHI_CHU,
        NVL(CAST(bt.PHAN_DOI AS VARCHAR2(4000)), '')                 AS PHAN_DOI,
        NVL(CAST(bt.PHAN_TRAI AS VARCHAR2(4000)), '')                AS PHAN_TRAI,
        TO_CHAR(bt.THOI_GIAN_TAM_GIAM) AS MUC_TAM_GIAM,
        NVL(CAST(FN_GET_LIET_KE_HPBS_KHAC(bt.PHAM_NHAN_ID) AS VARCHAR2(4000)), '') AS HINH_PHAT,
        NVL(CAST(FN_GET_LIET_KE_HPBST_TNDST(bt.PHAM_NHAN_ID) AS VARCHAR2(4000)), '') AS HPBS_TIEN,
        (
            SELECT CASE
                WHEN NVL(SUM(NVL(hp.HPBS_TONG_TIEN_PHAT, 0)), 0) > 0
                THEN CONVERT_ARAB(TO_CHAR(SUM(NVL(hp.HPBS_TONG_TIEN_PHAT, 0)))) || u' ??ng'
                ELSE u''
            END
            FROM PN_HINH_PHAT_BO_SUNGS hp
            JOIN DM_HINH_PHAT_BO_SUNGS dm
                ON dm.ID = hp.HPBS_HINH_PHAT
               AND NVL(dm.IS_DELETED, 0) = 0
            WHERE NVL(hp.IS_DELETED, 0) = 0
              AND hp.HPBS_MA_PHAM_NHAN = bt.PHAM_NHAN_ID
              AND UPPER(TRIM(NVL(CAST(dm.HPBS_LOAI_HPBS AS VARCHAR2(50)), ''))) <> 'HPBS'
        ) AS HPBS_TIEN_CHU,
        NULL AS DIA_DANH,
        NULL AS GIAM_THI,
        bt.SO_BAN_AN   AS BA_QD,
        bt.SO_BAN_AN                             AS BAN_AN_SO,
        TO_CHAR(NVL(bt.NGAY_BAN_AN, bt.NGAY_QD_THA), 'DD/MM/YYYY')   AS NGAY_XU,
        TRIM(NVL(bt.CO_QUAN_QD_THA, '') || NVL2(bt.TOA_QD_THA_DIA_PHUONG, u', ' || bt.TOA_QD_THA_DIA_PHUONG, '')) AS TOA_XU,
        NVL(CQ_LAP.CQ_TEN, '')                                       AS TOA_DAN_SU
    FROM base bt
    LEFT JOIN DM_XA_PHUONG xp_ntv ON xp_ntv.ID = bt.LL_NOI_THA_VE_CU_TRU_WARD AND NVL(xp_ntv.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_THANH_PHO ttp_ntv ON ttp_ntv.ID = bt.LL_NOI_THA_VE_CU_TRU_PROVICE AND NVL(ttp_ntv.IS_DELETED, 0) = 0
    LEFT JOIN DM_TRAI_GIAMS tg ON tg.ID = bt.TRAI_GIAM_ID AND NVL(tg.IS_DELETED, 0) = 0
    LEFT JOIN dm_tinh_thanh_pho DVHC ON DVHC.ID = tg.TG_DIA_CHI_DP AND NVL(DVHC.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS CQ_LAP ON bt.THA_CO_QUAN_LAP_ID = CQ_LAP.ID AND NVL(CQ_LAP.IS_DELETED, 0) = 0
    ORDER BY bt.PHAN_TRAI, bt.PHAN_DOI, ORDER_HOTEN(bt.HO_TEN);

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_BAO_CAO_PN_DE_NGHI_DAC_XA;





-- Ví d? g?i:
-- EXEC SP_GET_BAO_CAO_PN_DE_NGHI_DAC_XA('101,102,103');
-- EXEC SP_GET_BAO_CAO_PN_DE_NGHI_DAC_XA('[101, 102, 103]');
-- EXEC SP_GET_BAO_CAO_PN_DE_NGHI_DAC_XA('101,102,103', N'94280');


-- =============================================================================
-- SP_GET_BAO_CAO_PN_DE_NGHI_DAC_XA
-- Báo cáo ph?m nhân ???c ?? ngh? ??c xá.
-- Ngu?n: PN_DAC_XAS + PN_LAI_LICH_CHI_TIET_RT + VW_PN_LAI_LICH_CHI_TIET.
-- M?i PN ch? ??c xá m?t l?n — l?y tr?c ti?p PN_DAC_XAS theo p_pn_ids, không l?c ??t m?i nh?t.
--
-- Input:
--   p_pn_ids           : Danh sách ID ph?m nhân (chu?i), h? tr? d?ng '1,2,3' ho?c '[1,2,3]'
--   p_ma_trai_giam     : Mã tr?i giam (DM_TRAI_GIAMS.TG_MA); NULL = t?t c? tr?i
--
-- Output: Gi?ng SP_GET_DX_DON_PHAM_NHAN_DAC_XA + các c?t báo cáo ??c xá
--   TEN_TRAI, HO_TEN, GIOI_TINH, TEN_KHAC, NGUYEN_QUAN, NGAY_SINH, NOI_DKTT, NOI_VE_CU_TRU, NGHE_NGHIEP,
--   NGAY_BAT, TOI_DANH, AN_PHAT, SO_TIEN_AN, SO_TIEN_SU, THOI_GIAN_GIAM, THOI_GIAN_DA_CHAP_HANH, THOI_GIAN_CON_LAI,
--   XEP_LOAI_CHAP_HANH (PN_DAC_XAS.DX_XEP_LOAI_CAI_TAO), XEP_LOAI_CHAP_HANH_TEN (DM_XEP_LOAI_CAI_TAOS.XLCT_TEN), TINH_TIET_UU_TIEN, GHI_CHU, PHAN_DOI, PHAN_TRAI,
--   MUC_TAM_GIAM, HPBS_TIEN, DIA_DANH, GIAM_THI, BA_QD, BAN_AN_SO, NGAY_XU, TOA_XU, TOA_DAN_SU
-- =============================================================================

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_PN_DE_NGHI_DAC_XA_FILTER
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_PN_DE_NGHI_DAC_XA_FILTER" (
    p_trai_giam_id      IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id       IN  NUMBER    DEFAULT NULL,
    p_muc_an_phat_id    IN  NUMBER    DEFAULT NULL,
    p_tinh_trang_xet_id IN  NUMBER    DEFAULT NULL,
    p_doi_tuong         IN  NUMBER    DEFAULT NULL,
    p_quoc_tich         IN  NUMBER    DEFAULT NULL,
    p_gioi_tinh_id      IN  NUMBER    DEFAULT NULL,
    p_ho_ten            IN  NVARCHAR2       DEFAULT NULL
) AS
    c1 SYS_REFCURSOR;
    v_ngay_xet DATE := SYSDATE;
BEGIN
    OPEN c1 FOR
    WITH
    -- ??t ??c xá m?i nh?t ?ang m? (ddx_trang_thai = 0)
    dot_moi_nhat AS (
        SELECT id AS dot_id,
               NVL(ddx_ngay_xet, SYSDATE) AS ngay_xet
        FROM (
            SELECT id,
                   ddx_ngay_xet,
                   ROW_NUMBER() OVER (ORDER BY id DESC) AS rn
            FROM PN_DOT_DAC_XAS
            WHERE NVL(IS_DELETED, 0) = 0
              AND ddx_trang_thai = 1
        )
        WHERE rn = 1
    ),
    -- Danh sách PN ?ã ???c ??c xá trong ??t m?i nh?t (PN_DAC_XAS); 1 dòng / PN (b?n ghi m?i nh?t n?u trùng ngày xét)
    pn_dac_xa AS (
        SELECT pn_lai_lich_id, DX_XEP_LOAI_CAI_TAO
        FROM (
            SELECT pdx.PNLAI_LICH_ID AS pn_lai_lich_id,
                   pdx.DX_XEP_LOAI_CAI_TAO,
                   ROW_NUMBER() OVER (
                       PARTITION BY pdx.PNLAI_LICH_ID
                       ORDER BY pdx.ID DESC, pdx.CREATION_TIME DESC NULLS LAST
                   ) AS rn
            FROM PN_DAC_XAS pdx
            INNER JOIN dot_moi_nhat dm
                ON TRUNC(pdx.DX_NGAY_XET) = TRUNC(dm.ngay_xet)
            WHERE NVL(pdx.IS_DELETED, 0) = 0
        )
        WHERE rn = 1
    ),
    -- Thông tin PN t? VW + LL_GIOI_TINH_ID, LL_GHI_CHU_CHI_TIET t? PN_LAI_LICHS
    base AS (
        SELECT
            v.PHAM_NHAN_ID,
            v.HO_TEN,
            v.GIOI_TINH,
            ll.LL_DM_GIOI_TINH_ID AS GIOI_TINH_ID,
            TO_CHAR(v.NGAY_SINH) AS NGAY_SINH,
            v.NAM_SINH,
            v.NOI_THUONG_TRU_DAY_DU,
            v.NOI_THA_VE_CU_TRU,
            v.NGHE_NGHIEP,
            v.NGAY_BAT_AN_PHAT,
            v.TOI_DANH,
            v.AN_PHAT,
            v.SO_TIEN_AN,
            v.MUC_AN_ID,
            v.TRAI_GIAM_ID,
            v.TRAI_GIAM,
            v.PHAN_DOI_ID,
            v.PHAN_DOI,
            v.PHAN_TRAI,
            v.QUOC_TICH_ID,
            v.GHI_CHU_RIENG,
            v.TOI_DANH_ID,
            dm.ngay_xet,
            ll.LL_GHI_CHU_CHI_TIET AS GHI_CHU_CHI_TIET,
            p.DX_XEP_LOAI_CAI_TAO,
            v.TEN_KHAC,
            v.NGUYEN_QUAN,
            v.THOI_GIAN_TAM_GIAM,
            v.SO_BAN_AN,
            v.NGAY_BAN_AN,
            v.SO_QD_THA,
            v.NGAY_QD_THA,
            v.TOA_XU_TEN,
            v.TOA_XU_DIA_PHUONG
        FROM pn_dac_xa p
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = p.pn_lai_lich_id
           AND NVL(v.IS_DELETED, 0) = 0
        LEFT JOIN PN_LAI_LICHS ll
            ON ll.ID = v.PHAM_NHAN_ID
           AND NVL(ll.IS_DELETED, 0) = 0
        CROSS JOIN dot_moi_nhat dm
    ),
    -- Thi hành án m?i nh?t theo PN (?? l?y MUC_TAM_GIAM, THA_CO_QUAN_LAP_ID) - gi?ng SP_GET_DX_DON_PHAM_NHAN_DAC_XA
    tha_one AS (
        SELECT * FROM (
            SELECT t.THA_PNLAI_LICH_ID AS PHAM_NHAN_ID,
                   t.THA_THOI_GIAN_TAM_GIAM,
                   t.THA_CO_QUAN_LAP_ID,
                   ROW_NUMBER() OVER (PARTITION BY t.THA_PNLAI_LICH_ID
                       ORDER BY NVL(t.THA_NGAY_HET_HAN, t.THA_NGAY_BAT) DESC NULLS LAST,
                                NVL(t.THA_NGAY_DEN_TRAI, t.THA_NGAY_BAT) DESC NULLS LAST,
                                t.ID DESC) AS rn
            FROM PN_THI_HANH_AN t
            WHERE NVL(t.IS_DELETED, 0) = 0
              AND t.THA_PNLAI_LICH_ID IN (SELECT pn_lai_lich_id FROM pn_dac_xa)
        ) x WHERE rn = 1
    ),
    -- Tham s? h? th?ng: ??a danh báo cáo, ch?c v? ký - gi?ng SP_GET_DX_DON_PHAM_NHAN_DAC_XA
    tsht AS (
        SELECT
            MAX(CASE WHEN tsht.tsht_tham_so = 'CHUC_VU_KY' THEN tsht.tsht_gia_tri END) AS giam_thi,
            MAX(CASE WHEN tsht.tsht_tham_so = 'DIA_DANH_BC' THEN tsht.tsht_gia_tri END) AS dia_danh
        FROM THAM_SO_HE_THONGS tsht
        WHERE NVL(tsht.IS_DELETED, 0) = 0
          AND tsht.tsht_tham_so IN ('CHUC_VU_KY', 'DIA_DANH_BC')
    ),
    -- L?y TD_CHUONG (ch??ng t?i) + QT_MA (qu?c t?ch) ?? filter p_doi_tuong, p_quoc_tich
    base_toi AS (
        SELECT b.*,
               dm.TD_CHUONG AS td_chuong,
               qt.QT_MA AS quoc_tich_ma
        FROM base b
        LEFT JOIN DM_TOI_DANHS dm
            ON dm.ID = TO_NUMBER(REGEXP_SUBSTR(NVL(TRIM(CAST(b.TOI_DANH_ID AS VARCHAR2(4000))), ''), '[0-9]+', 1, 1))
           AND NVL(dm.IS_DELETED, 0) = 0
        LEFT JOIN DM_QUOC_TICHS qt
            ON qt.ID = b.QUOC_TICH_ID
           AND NVL(qt.IS_DELETED, 0) = 0
    ),
    gcr_raw AS (
        SELECT bt.PHAM_NHAN_ID,
               REGEXP_REPLACE(NVL(TRIM(CAST(bt.GHI_CHU_RIENG AS VARCHAR2(4000))), ''), '[[:space:]\[\]]', '') AS gcr_clean
        FROM base_toi bt
        WHERE bt.GHI_CHU_RIENG IS NOT NULL
          AND REGEXP_COUNT(REGEXP_REPLACE(NVL(TRIM(CAST(bt.GHI_CHU_RIENG AS VARCHAR2(4000))), ''), '[[:space:]\[\]]', ''), '[0-9]+') > 0
    ),
    gcr_ids AS (
        SELECT r.PHAM_NHAN_ID,
               TO_NUMBER(REGEXP_SUBSTR(r.gcr_clean, '[0-9]+', 1, LEVEL)) AS gcr_id,
               LEVEL AS ord
        FROM gcr_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.gcr_clean, '[0-9]+')
          AND PRIOR r.PHAM_NHAN_ID = r.PHAM_NHAN_ID
          AND PRIOR SYS_GUID() IS NOT NULL
    ),
    gcr_agg AS (
        SELECT ids.PHAM_NHAN_ID,
               LISTAGG(CAST(g.GCR_TEN AS VARCHAR2(4000)), ', ') WITHIN GROUP (ORDER BY ids.ord) AS ghi_chu_rieng_ten
        FROM gcr_ids ids
        JOIN DM_GHI_CHU_RIENGS g ON g.ID = ids.gcr_id AND NVL(g.IS_DELETED, 0) = 0
        GROUP BY ids.PHAM_NHAN_ID
    )
    SELECT
        -- Gi?ng SP_GET_DX_DON_PHAM_NHAN_DAC_XA
        NVL(tg.TG_TEN, bt.TRAI_GIAM)           AS TEN_TRAI,
        NVL(TRIM(bt.HO_TEN), '')               AS HO_TEN,
        bt.NAM_SINH                            AS NAM_SINH,
        NVL(TRIM(bt.GIOI_TINH), '')            AS GIOI_TINH,
        NVL(CAST(bt.TEN_KHAC AS VARCHAR2(4000)), '') AS TEN_KHAC,
        NVL(CAST(bt.NGUYEN_QUAN AS VARCHAR2(4000)), '') AS NGUYEN_QUAN,
        CASE
            WHEN bt.NGAY_SINH IS NOT NULL AND REGEXP_LIKE(TRIM(bt.NGAY_SINH), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(bt.NGAY_SINH), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN bt.NAM_SINH IS NOT NULL AND bt.NAM_SINH > 0
            THEN TO_CHAR(bt.NAM_SINH)
            WHEN bt.NGAY_SINH IS NOT NULL AND REGEXP_LIKE(TRIM(bt.NGAY_SINH), '^[0-9]{4}$')
            THEN TRIM(bt.NGAY_SINH)
            ELSE NULL
        END                                    AS NGAY_SINH,
        NVL(TRIM(bt.NOI_THUONG_TRU_DAY_DU), '') AS NOI_DKTT,
        NVL(CAST(bt.NOI_THA_VE_CU_TRU AS VARCHAR2(4000)), '') AS NOI_VE_CU_TRU,
        NVL(CAST(bt.NGHE_NGHIEP AS VARCHAR2(4000)), '')       AS NGHE_NGHIEP,
        TO_CHAR(bt.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT,
        NVL(CAST(bt.TOI_DANH AS VARCHAR2(4000)), '')                 AS TOI_DANH,
        NVL(CAST(bt.AN_PHAT AS VARCHAR2(4000)), '')                  AS AN_PHAT,
        NVL(TRIM(CAST(bt.SO_TIEN_AN AS VARCHAR2(4000))), '0')           AS SO_TIEN_AN,
        -- PKG_TINH_AN: gi?m án, ?ã ch?p hành, còn l?i
        NVL(PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(bt.PHAM_NHAN_ID), u'Kh\00f4ng') AS THOI_GIAN_GIAM,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(bt.PHAM_NHAN_ID, bt.ngay_xet), u'') AS THOI_GIAN_DA_CHAP_HANH,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(bt.PHAM_NHAN_ID, bt.ngay_xet), u'') AS THOI_GIAN_CON_LAI,
        NVL(TRIM(CAST(bt.DX_XEP_LOAI_CAI_TAO AS VARCHAR2(4000))), '')      AS XEP_LOAI_CHAP_HANH,
        NVL(ga.ghi_chu_rieng_ten, '') AS TINH_TIET_UU_TIEN,
        NVL(CAST(bt.GHI_CHU_CHI_TIET AS VARCHAR2(4000)), '') AS GHI_CHU,
        NVL(CAST(bt.PHAN_DOI AS VARCHAR2(4000)), '')                 AS PHAN_DOI,
        NVL(CAST(bt.PHAN_TRAI AS VARCHAR2(4000)), '')                AS PHAN_TRAI,
        -- Gi?ng SP_GET_DX_DON_PHAM_NHAN_DAC_XA
        TO_CHAR(NVL(tha.THA_THOI_GIAN_TAM_GIAM, bt.THOI_GIAN_TAM_GIAM)) AS MUC_TAM_GIAM,
        NVL(CAST(FN_GET_LIET_KE_HPBS_TIEN(bt.PHAM_NHAN_ID) AS VARCHAR2(4000)), '') AS HPBS_TIEN,
        NVL(tsht.dia_danh, NVL(DVHC.TTP_TEN, tg.TG_DIA_CHI)) AS DIA_DANH,
        NVL(tsht.giam_thi, '')                                       AS GIAM_THI,
        CASE WHEN bt.SO_BAN_AN IS NOT NULL THEN u'B\1ea3n \00e1n' WHEN bt.SO_QD_THA IS NOT NULL THEN u'Quy\1ebft \0111\1ecbnh thi h\00e0nh \00e1n' ELSE NULL END AS BA_QD,
        NVL(bt.SO_BAN_AN, bt.SO_QD_THA)                             AS BAN_AN_SO,
        TO_CHAR(NVL(bt.NGAY_BAN_AN, bt.NGAY_QD_THA), 'DD/MM/YYYY')   AS NGAY_XU,
        TRIM(NVL(bt.TOA_XU_TEN, '') || NVL2(bt.TOA_XU_DIA_PHUONG, u', ' || bt.TOA_XU_DIA_PHUONG, '')) AS TOA_XU,
        NVL(CQ_LAP.CQ_TEN, '')                                       AS TOA_DAN_SU
    FROM base_toi bt
    LEFT JOIN gcr_agg ga ON ga.PHAM_NHAN_ID = bt.PHAM_NHAN_ID
    CROSS JOIN tsht
    LEFT JOIN tha_one tha ON tha.PHAM_NHAN_ID = bt.PHAM_NHAN_ID
    LEFT JOIN DM_TRAI_GIAMS tg ON tg.ID = bt.TRAI_GIAM_ID AND NVL(tg.IS_DELETED, 0) = 0
    LEFT JOIN dm_tinh_thanh_pho DVHC ON DVHC.ID = tg.TG_DIA_CHI_DP AND NVL(DVHC.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS CQ_LAP ON tha.THA_CO_QUAN_LAP_ID = CQ_LAP.ID AND NVL(CQ_LAP.IS_DELETED, 0) = 0
    WHERE (p_trai_giam_id IS NULL  OR p_trai_giam_id = 0  OR bt.TRAI_GIAM_ID = p_trai_giam_id)
      AND (p_phan_doi_id IS NULL OR p_phan_doi_id = 0 OR bt.PHAN_DOI_ID = p_phan_doi_id)
      AND (p_muc_an_phat_id IS NULL OR p_muc_an_phat_id = 0 OR bt.MUC_AN_ID = p_muc_an_phat_id)
      AND (p_tinh_trang_xet_id IS NULL OR p_tinh_trang_xet_id = 0 
           OR EXISTS (
               SELECT 1 FROM PN_DAC_XAS pdx
               INNER JOIN DM_DUOC_DAC_XAS ddx
                   ON ddx.ID = p_tinh_trang_xet_id
                  AND NVL(ddx.IS_DELETED, 0) = 0
                  AND TRIM(CAST(NVL(pdx.DX_TINH_TRANG_DAC_XA, '') AS VARCHAR2(100))) = TRIM(CAST(NVL(ddx.DDX_MA, '') AS VARCHAR2(100)))
               WHERE pdx.PNLAI_LICH_ID = bt.PHAM_NHAN_ID
                 AND NVL(pdx.IS_DELETED, 0) = 0
                 AND TRUNC(NVL(pdx.DX_NGAY_XET, pdx.CREATION_TIME)) = TRUNC(bt.ngay_xet)
           ))
      AND (p_doi_tuong IS NULL OR p_doi_tuong = 0 
           OR (p_doi_tuong = 1 AND TRIM(CAST(NVL(bt.td_chuong, '') AS VARCHAR2(10))) = '13')
           OR (p_doi_tuong = 2 AND (bt.td_chuong IS NULL OR TRIM(CAST(NVL(bt.td_chuong, '') AS VARCHAR2(10))) <> '13')))
      AND (p_quoc_tich IS NULL OR p_quoc_tich = 0 
           OR (p_quoc_tich = 250 AND bt.quoc_tich_ma = 250)   /* Vi?t Nam: QT_MA=250 (DM_QUOC_TICHS) */
           OR (p_quoc_tich = 999 AND (bt.quoc_tich_ma IS NULL OR bt.quoc_tich_ma <> 250)))  /* 999: N??c ngoài = các mã còn l?i */
      AND (p_gioi_tinh_id IS NULL OR p_gioi_tinh_id = 0  OR bt.GIOI_TINH_ID = p_gioi_tinh_id)
      AND (p_ho_ten IS NULL OR UPPER(CAST(NVL(bt.HO_TEN, '') AS VARCHAR2(2000))) LIKE '%' || UPPER(TRIM(CAST(NVL(p_ho_ten, '') AS VARCHAR2(2000)))) || '%')
    ORDER BY bt.PHAN_TRAI, bt.PHAN_DOI, bt.HO_TEN;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_BAO_CAO_PN_DE_NGHI_DAC_XA_FILTER;


-- Ví d? g?i:
-- EXEC SP_GET_BAO_CAO_PN_DE_NGHI_DAC_XA(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
-- EXEC SP_GET_BAO_CAO_PN_DE_NGHI_DAC_XA(5, NULL, NULL, NULL, 1, 250, 1, N'Nguy?n');


-- =============================================================================
-- SP_GET_BAO_CAO_PN_DE_NGHI_DAC_XA
-- Báo cáo ph?m nhân ???c ?? ngh? ??c xá (k? m?i nh?t ?ang m?).
-- Ngu?n: DX_DU_DIEU_KIEN_DAC_XAS + PN_DOT_DAC_XAS (ddx_trang_thai=0) + VW_PN_LAI_LICH_CHI_TIET.
--
-- Filters:
--   p_trai_giam_id      : Tr?i giam (DM_TRAI_GIAMS.ID)
--   p_phan_doi_id       : Phân ??i (DM_PHAN_DOIS.ID)
--   p_muc_an_phat_id    : M?c án (DM_MUC_ANS.ID)
--   p_tinh_trang_xet_id : Tình tr?ng xét (DM_DUOC_DAC_XAS.ID). Map: PN_DAC_XAS.DX_TINH_TRANG_DAC_XA = DM_DUOC_DAC_XAS.DDX_MA
--   p_doi_tuong         : 1=T?i ANQG (TD_CHUONG='13'), 2=Án hình s? (TD_CHUONG<>'13'), null=T?t c?
--   p_quoc_tich        : 250=Vi?t Nam (QT_MA), 999=N??c ngoài (các mã còn l?i), null=T?t c?
--   p_gioi_tinh_id     : Gi?i tính (DM_GIOI_TINHS.ID)
--   p_ho_ten           : Tìm ki?m LIKE (không phân bi?t hoa th??ng)
--
-- Output: Gi?ng SP_GET_DX_DON_PHAM_NHAN_DAC_XA + các c?t báo cáo ??c xá
--   TEN_TRAI, HO_TEN, GIOI_TINH, TEN_KHAC, NGUYEN_QUAN, NGAY_SINH, NOI_DKTT, NOI_VE_CU_TRU, NGHE_NGHIEP,
--   NGAY_BAT, TOI_DANH, AN_PHAT, SO_TIEN_AN, THOI_GIAN_GIAM, THOI_GIAN_DA_CHAP_HANH, THOI_GIAN_CON_LAI,
--   XEP_LOAI_CHAP_HANH (PN_DAC_XAS.DX_XEP_LOAI_CAI_TAO), TINH_TIET_UU_TIEN, GHI_CHU, PHAN_DOI, PHAN_TRAI,
--   MUC_TAM_GIAM, HPBS_TIEN, DIA_DANH, GIAM_THI, BA_QD, BAN_AN_SO, NGAY_XU, TOA_XU, TOA_DAN_SU
-- =============================================================================






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_PN_DUOC_DAC_XA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_PN_DUOC_DAC_XA" (
--    p_pn_ids            IN  VARCHAR2   DEFAULT NULL,
    p_ma_trai_giam      IN  NVARCHAR2  DEFAULT NULL
) AS
    c1 SYS_REFCURSOR;
    v_trai_giam_id NUMBER;
BEGIN
    IF p_ma_trai_giam IS NOT NULL THEN
        BEGIN
            SELECT id INTO v_trai_giam_id
            FROM DM_TRAI_GIAMS
            WHERE TG_MA = p_ma_trai_giam AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION WHEN NO_DATA_FOUND THEN v_trai_giam_id := NULL;
        END;
    END IF;

    OPEN c1 FOR
    WITH
    pn_ids_input AS (
            SELECT PN_ID AS pn_id
		    FROM QLPN.GTT_PN_IDS
    ),
    pn_dac_xa AS (
        SELECT x.pn_lai_lich_id,
               x.dx_ngay_tha,
               x.dx_ngay_trinh_dien,
               x.dx_kqct_phieu,
               x.dx_ngay_xet,
               x.dx_xep_loai_cai_tao,
               x.dot_id,
               x.THA_CO_QUAN_LAP_ID,
               x.THA_NGAY_LAP_DANH_BAN,
               x.LL_NGUYEN_QUAN
        FROM (
            SELECT pdx.PNLAI_LICH_ID AS pn_lai_lich_id,
                   pdx.DX_NGAY_THA AS dx_ngay_tha,
                   pdx.DX_NGAY_TRINH_DIEN AS dx_ngay_trinh_dien,
                   pdx.DX_KQCT_PHIEU AS dx_kqct_phieu,
                   pdx.DX_NGAY_XET AS dx_ngay_xet,
                   pdx.DX_XEP_LOAI_CAI_TAO AS dx_xep_loai_cai_tao,
                   dot.ID AS dot_id,
                   rt_f.THA_CO_QUAN_LAP_ID,
                   rt_f.THA_NGAY_LAP_DANH_BAN,
                   rt_f.LL_NGUYEN_QUAN,
                   ROW_NUMBER() OVER (
                       PARTITION BY pdx.PNLAI_LICH_ID
                       ORDER BY pdx.DX_NGAY_XET DESC NULLS LAST,
                                pdx.ID DESC
                   ) AS rn
            FROM PN_DAC_XAS pdx
            INNER JOIN pn_ids_input i
                ON i.pn_id = pdx.PNLAI_LICH_ID
            INNER JOIN PN_LAI_LICH_CHI_TIET_RT rt_f
                ON rt_f.PHAM_NHAN_ID = pdx.PNLAI_LICH_ID
               AND NVL(rt_f.IS_DELETED, 0) = 0
               AND NVL(rt_f.LL_IS_DELETED, 0) = 0
               AND NVL(rt_f.THA_IS_DELETED, 0) = 0
               AND (p_ma_trai_giam IS NULL OR rt_f.LL_TRAI_GIAM_ID = v_trai_giam_id)
            LEFT JOIN PN_DOT_DAC_XAS dot
                ON NVL(dot.IS_DELETED, 0) = 0
               AND dot.DDX_NGAY_XET IS NOT NULL
               AND pdx.DX_NGAY_XET >= TRUNC(dot.DDX_NGAY_XET)
               AND pdx.DX_NGAY_XET < TRUNC(dot.DDX_NGAY_XET) + 1
            WHERE NVL(pdx.IS_DELETED, 0) = 0
        ) x
        WHERE x.rn = 1
    ),
    tn AS (
        SELECT
            t.PHAM_NHAN_ID,
            MAX(CASE WHEN t.QHVPN_MA = '121' THEN t.HO_TEN_THAN_NHAN END) AS HO_TEN_BO,
            MAX(CASE WHEN t.QHVPN_MA = '122' THEN t.HO_TEN_THAN_NHAN END) AS HO_TEN_ME
        FROM (
            SELECT tn.PHAM_NHAN_ID,
                   tn.HO_TEN_THAN_NHAN,
                   qh.QHVPN_MA,
                   ROW_NUMBER() OVER (
                       PARTITION BY tn.PHAM_NHAN_ID, qh.QHVPN_MA
                       ORDER BY tn.ID
                   ) AS rn
            FROM THAN_NHAN_NGUOI_THANS tn
            INNER JOIN pn_dac_xa p
                ON p.pn_lai_lich_id = tn.PHAM_NHAN_ID
            INNER JOIN DM_QUAN_HE_VOI_PHAM_NHANS qh
                ON qh.ID = tn.QUAN_HE_ID
               AND NVL(qh.IS_DELETED, 0) = 0
               AND qh.QHVPN_MA IN ('121', '122')
            WHERE NVL(tn.IS_DELETED, 0) = 0
        ) t
        WHERE t.rn = 1
        GROUP BY t.PHAM_NHAN_ID
    ),
    ky_latest AS (
        SELECT pn_lai_lich_id,
               NGAY_QDXEP_LOAI AS ngay_xet_ky,
               SO_QUYET_DINH_TU AS so_quyet_dinh_tu
        FROM (
            SELECT m.PN_LAI_LICHS_ID AS pn_lai_lich_id,
                   k.NGAY_QDXEP_LOAI,
                   k.SO_QUYET_DINH_TU,
                   ROW_NUMBER() OVER (
                       PARTITION BY m.PN_LAI_LICHS_ID
                       ORDER BY k.NAM_XEP_LOAI DESC NULLS LAST,
                                k.NGAY_HOP_XEP_LOAI DESC NULLS LAST
                   ) AS rn
            FROM MO_KY_XEP_LOAI_CAI_TAO_PN_LAI_LICH m
            INNER JOIN pn_dac_xa p
                ON p.pn_lai_lich_id = m.PN_LAI_LICHS_ID
            INNER JOIN MO_KY_XEP_LOAI_CAI_TAOS k
                ON k.ID = m.MO_KY_XEP_LOAI_CAI_TAOS_ID
               AND NVL(k.IS_DELETED, 0) = 0
        )
        WHERE rn = 1
    )
    SELECT
        NULL AS CO_QUAN_CHU_QUAN,
        NULL AS TEN_TRAI_GIAM,
        NULL AS SO_QUYET_DINH,
        NULL AS DIA_DANH,
        CASE
            WHEN dot.DDX_TG_NGAY_HOP IS NOT NULL
            THEN TO_CHAR(TRUNC(dot.DDX_TG_NGAY_HOP), 'DD/MM/YYYY')
            ELSE NULL
        END AS NGAY_HOP,
        NVL(TRIM(v.HO_TEN), '') AS HO_TEN,
        NVL(TRIM(CAST(v.CCCD AS VARCHAR2(255))), '') AS SO_CCCD,
        NVL(TRIM(CAST(v.NGAY_CAP_CCCD AS VARCHAR2(255))), '') AS NGAY_CAP_CCCD,
        NVL(TRIM(CAST(v.NOI_CAP_CCCD AS VARCHAR2(255))), '')  AS NOI_CAP_CCCD,
        NVL(TRIM(v.GIOI_TINH), '') AS GIOI_TINH,
        CASE
            WHEN v.NGAY_SINH IS NOT NULL
                 AND REGEXP_LIKE(CAST(v.NGAY_SINH AS VARCHAR2(50)), '^\d{1,2}/\d{1,2}/\d{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(CAST(v.NGAY_SINH AS VARCHAR2(50))), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN v.NAM_SINH IS NOT NULL AND v.NAM_SINH > 0
            THEN TO_CHAR(v.NAM_SINH)
            WHEN v.NGAY_SINH IS NOT NULL
                 AND LENGTH(TRIM(CAST(v.NGAY_SINH AS VARCHAR2(50)))) >= 4
            THEN TRIM(CAST(v.NGAY_SINH AS VARCHAR2(50)))
            ELSE NULL
        END AS NGAY_SINH,
        NVL(CAST(v.TEN_KHAC AS VARCHAR2(4000)), '') AS TEN_KHAC,
        NVL(TRIM(CAST(p.LL_NGUYEN_QUAN AS VARCHAR2(4000))), '') AS NGUYEN_QUAN,
        NVL(TRIM(v.NOI_THUONG_TRU_DAY_DU), '') AS NOI_DKTT,
        NVL(CAST(tn.HO_TEN_BO AS VARCHAR2(4000)), '') AS HO_TEN_BO,
        NVL(CAST(tn.HO_TEN_ME AS VARCHAR2(4000)), '') AS HO_TEN_ME,
        TO_CHAR(v.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT,
        v.THOI_GIAN_TAM_GIAM AS THOI_GIAN_TAM_GIAM,
        v.THOI_GIAN_TAM_GIU AS THOI_GIAN_TAM_GIU,
        v.SO_BAN_AN AS SO_BA,
        CASE WHEN v.NGAY_BAN_AN IS NOT NULL THEN TO_CHAR(v.NGAY_BAN_AN, 'DD/MM/YYYY') ELSE NULL END AS NGAY_BA,
        NVL(CAST(v.TOA_XU_TEN AS VARCHAR2(4000)), '') AS TOA_BA,
        NVL(CAST(v.TOA_XU_DIA_PHUONG AS VARCHAR2(4000)), '') AS CO_QUAN_XU_DIA_PHUONG,
        v.SO_QD_THA AS SO_QDTHA,
        CASE WHEN v.NGAY_QD_THA IS NOT NULL THEN TO_CHAR(v.NGAY_QD_THA, 'DD/MM/YYYY') ELSE NULL END AS NGAY_QDTHA,
        NVL(CAST(v.CO_QUAN_QD_THA AS VARCHAR2(4000)), '') AS TOA_QDTHA,
        NVL(CAST(v.SO_DANH_BAN AS VARCHAR2(4000)), '') AS SO_DB,
        NVL(CAST(cq_lap.CQ_TEN AS VARCHAR2(4000)), '') AS DV_LAP_DB,
        CASE WHEN p.THA_NGAY_LAP_DANH_BAN IS NOT NULL THEN TO_CHAR(p.THA_NGAY_LAP_DANH_BAN, 'DD/MM/YYYY') ELSE NULL END AS NGAY_DB,
        NVL(CAST(v.CO_QUAN_QD_THA AS VARCHAR2(4000)), '') AS TOA_GUI,
        NVL(CAST(v.TOA_QD_THA_DIA_PHUONG AS VARCHAR2(4000)), '') AS TOA_TINH_DC,
        NVL(CAST(v.TOA_QD_THA_DIA_PHUONG AS VARCHAR2(4000)), '') AS CO_QUAN_THA_DIA_PHUONG,
        NVL(CAST(cq_lap.CQ_TEN AS VARCHAR2(4000)), '') AS TOA_DAN_SU,
         v.SO_BAN_AN  AS BA_QD,
        NVL(CAST(v.SO_HO_SO AS VARCHAR2(255)), '') AS SO_HSLD,
        NVL(CAST(v.DAN_TOC AS VARCHAR2(4000)), '') AS DAN_TOC,
        NVL(CAST(v.QUOC_TICH AS VARCHAR2(4000)), '') AS QUOC_TICH,
        NVL(CAST(v.PHAN_LOAI_GIAM_GIU AS VARCHAR2(4000)), '') AS giam_giu,
        NVL(CAST(v.NGHE_NGHIEP AS VARCHAR2(4000)), '') AS NGHE_NGHIEP,
        NVL(CAST(v.TOI_DANH AS VARCHAR2(4000)), '') AS TOI_DANH,
        NVL(CAST(v.AN_PHAT AS VARCHAR2(4000)), '') AS AN_PHAT,
        NVL(TRIM(CAST(v.SO_TIEN_AN AS VARCHAR2(4000))), '0') AS SO_TIEN_AN,
        NVL(CAST(PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(p.pn_lai_lich_id) AS VARCHAR2(4000)), '') AS GIAM_AN,
        NVL(
            PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(p.pn_lai_lich_id, p.dx_ngay_xet),
            u''
        )  AS THOI_GIAN_CHAP_HANH,
        NVL(
            PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(p.pn_lai_lich_id, p.dx_ngay_xet),
            u''
        )  AS THOI_GIAN_CON_LAI,
        CASE
            WHEN v.NGAY_HET_AN IS NOT NULL
            THEN TO_CHAR(v.NGAY_HET_AN, 'DD/MM/YYYY')
            ELSE NULL
        END AS NGAY_HET_HAN,
        CASE WHEN v.NGAY_DEN_TRAI IS NOT NULL THEN TO_CHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') ELSE NULL END AS NGAY_DEN_TRAI,
        NVL(CAST(v.PHAN_DOI AS VARCHAR2(4000)), '') AS PHAN_DOI,
        NVL(CAST(p.dx_kqct_phieu AS VARCHAR2(4000)), '') AS DANH_GIA_CAI_TAO,
        CASE
            WHEN p.dx_ngay_tha IS NOT NULL
            THEN TO_CHAR(p.dx_ngay_tha, 'DD/MM/YYYY')
            ELSE NULL
        END AS NGAY_THA,
        CASE
            WHEN p.dx_ngay_trinh_dien IS NOT NULL
            THEN TO_CHAR(p.dx_ngay_trinh_dien, 'DD/MM/YYYY')
            ELSE NULL
        END AS NGAY_TRINH_DIEN,
        NVL(dot.DDX_TG_SO_PHIEU, dot.DDX_SO_HUONG_DAN) AS SO_CONG_VAN,
        dot.DDX_SO_HUONG_DAN AS SO_HUONG_DAN,
        dot.DDX_SO_QUYET_DINH AS SO_QUYET_DINH_DAC_XA,
        NVL(CAST(dot.DDX_SO_QUYET_DINH AS VARCHAR2(4000)), '') AS SO_QD_DX,
        CASE
            WHEN dot.DDX_NGAY_QUYET_DINH IS NOT NULL
            THEN TO_CHAR(TRUNC(dot.DDX_NGAY_QUYET_DINH), 'DD/MM/YYYY')
            ELSE NULL
        END AS NGAY_QD_DX,
        NVL(CAST(FN_GET_LIET_KE_HPBS(p.pn_lai_lich_id) AS VARCHAR2(4000)), '') AS HPBS_KHAC,
        NVL(CAST(FN_GET_LIET_KE_TRACH_NHIEM_DAN_SU_TIEN(p.pn_lai_lich_id) AS VARCHAR2(4000)), '') AS HPBS,
        NVL(CAST(FN_GET_LIET_KE_HPBS_KHAC(p.pn_lai_lich_id) AS VARCHAR2(4000)), '') AS HINH_PHAT,
        NVL(CAST(FN_GET_LIET_KE_HPBST_TNDST(p.pn_lai_lich_id) AS VARCHAR2(4000)), '') AS HINH_PHAT_TIEN,
        (
            SELECT CASE
                WHEN NVL(SUM(NVL(hp.HPBS_TONG_TIEN_PHAT, 0)), 0) > 0
                THEN TO_NCHAR(CONVERT_ARAB(TO_CHAR(SUM(NVL(hp.HPBS_TONG_TIEN_PHAT, 0))))) || u' ??ng'
                ELSE u''
            END
            FROM PN_HINH_PHAT_BO_SUNGS hp
            JOIN DM_HINH_PHAT_BO_SUNGS dm
                ON dm.ID = hp.HPBS_HINH_PHAT
               AND NVL(dm.IS_DELETED, 0) = 0
            WHERE NVL(hp.IS_DELETED, 0) = 0
              AND hp.HPBS_MA_PHAM_NHAN = p.pn_lai_lich_id
              AND UPPER(TRIM(NVL(CAST(dm.HPBS_LOAI_HPBS AS VARCHAR2(50)), ''))) <> 'HPBS'
        ) AS HINH_PHAT_TIEN_CHU,
        NVL(CAST(v.NOI_THA_VE_CU_TRU_XA AS VARCHAR2(4000)), '') AS PX_VE,
        NVL(CAST(v.NOI_THA_VE_CU_TRU_TINH AS VARCHAR2(4000)), '') AS TINH_VE,
        -- v.NOI_THA_VE_CU_TRU (VW_PN_LAI_LICH_CHI_TIET) ?ã t? n?i s?n xã + t?nh vào cu?i chu?i;
        -- không ???c n?i XA/TINH thêm l?n n?a ? ?ây (gây l?p "..., Ph??ng X, T?nh Y, Ph??ng X, T?nh Y").
        NULLIF(TRIM(CAST(v.NOI_THA_VE_CU_TRU AS NVARCHAR2(4000))), u'') AS DIA_CHI_VE,
        CASE
            WHEN ky.ngay_xet_ky IS NOT NULL
            THEN TO_CHAR(ky.ngay_xet_ky, 'DD/MM/YYYY')
            ELSE NULL
        END AS XEP_LOAI_TU_NGAY,
        CASE
            WHEN p.dx_ngay_xet IS NOT NULL
            THEN TO_CHAR(p.dx_ngay_xet, 'DD/MM/YYYY')
            ELSE NULL
        END AS XEP_LOAI_DEN_NGAY,
        NVL(CAST(xlct.XLCT_TEN AS VARCHAR2(4000)), '') AS DX_XEP_LOAI_CAI_TAO
    FROM pn_dac_xa p
    INNER JOIN VW_PN_LAI_LICH_CHI_TIET v
        ON v.PHAM_NHAN_ID = p.pn_lai_lich_id
       AND NVL(v.IS_DELETED, 0) = 0
    LEFT JOIN ky_latest ky
        ON ky.pn_lai_lich_id = p.pn_lai_lich_id
    LEFT JOIN PN_DOT_DAC_XAS dot
        ON dot.ID = p.dot_id
       AND NVL(dot.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS cq_lap
        ON cq_lap.ID = p.THA_CO_QUAN_LAP_ID
       AND NVL(cq_lap.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_THANH_PHO tinh
        ON tinh.ID = v.NOI_THA_VE_CU_TRU_TINH_ID
       AND NVL(tinh.IS_DELETED, 0) = 0
    LEFT JOIN tn
        ON tn.PHAM_NHAN_ID = p.pn_lai_lich_id
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xlct
        ON xlct.ID = CASE
            WHEN REGEXP_LIKE(TRIM(CAST(p.dx_xep_loai_cai_tao AS VARCHAR2(100))), '^[0-9]+$')
            THEN TO_NUMBER(TRIM(CAST(p.dx_xep_loai_cai_tao AS VARCHAR2(100))))
        END
       AND NVL(xlct.IS_DELETED, 0) = 0
    ORDER BY v.PHAN_TRAI, v.PHAN_DOI, ORDER_HOTEN(v.HO_TEN);

    DBMS_SQL.RETURN_RESULT(c1);


    -- Ví d? g?i:
-- EXEC SP_GET_BAO_CAO_PN_DUOC_DAC_XA('101,102,103');
-- EXEC SP_GET_BAO_CAO_PN_DUOC_DAC_XA('[101, 102, 103]');
-- EXEC SP_GET_BAO_CAO_PN_DUOC_DAC_XA('101,102,103', N'94280');

-- =============================================================================
-- SP_GET_BAO_CAO_PN_DUOC_DAC_XA
-- Báo cáo ph?m nhân ?ã ???c ??c xá theo ??t.
-- Ngu?n: PN_DAC_XAS + PN_LAI_LICH_CHI_TIET_RT (filter/THA cols) + VW_PN_LAI_LICH_CHI_TIET.
--
-- Input:
--   p_pn_ids           : Danh sách ID ph?m nhân (chu?i), h? tr? '1,2,3' ho?c '[1,2,3]'
--   p_ma_trai_giam     : Mã tr?i giam (DM_TRAI_GIAMS.TG_MA); NULL = t?t c? tr?i
-- =============================================================================
END SP_GET_BAO_CAO_PN_DUOC_DAC_XA;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_PN_DUOC_DAC_XA_FILTER
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_PN_DUOC_DAC_XA_FILTER" (
    p_dot_dac_xa_id     IN NUMBER,
    p_phan_doi_id       IN NUMBER DEFAULT NULL,
    p_doi_tuong         IN NUMBER DEFAULT NULL,
    p_quoc_tich         IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id      IN NUMBER DEFAULT NULL,
    p_tinh_trang_xet_id IN NUMBER DEFAULT NULL,
    p_tinh_ve_id        IN NUMBER DEFAULT NULL,
    p_xa_ve_id          IN NUMBER DEFAULT NULL,
    p_ngay_tha          IN DATE   DEFAULT NULL,
    p_ngay_trinh_dien   IN DATE   DEFAULT NULL,
    p_ho_ten            IN NVARCHAR2 DEFAULT NULL
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    -- Danh sách PN ?ã ???c ??c xá theo ??t (PN_DAC_XAS join PN_DOT_DAC_XAS qua DX_NGAY_XET = DDX_NGAY_XET)
    pn_dac_xa AS (
        SELECT pdx.PNLAI_LICH_ID AS pn_lai_lich_id
        FROM PN_DAC_XAS pdx
        INNER JOIN PN_DOT_DAC_XAS dot ON dot.ID = p_dot_dac_xa_id
           AND NVL(dot.IS_DELETED, 0) = 0
           AND TRUNC(NVL(dot.DDX_NGAY_XET, dot.CREATION_TIME)) = TRUNC(NVL(pdx.DX_NGAY_XET, pdx.CREATION_TIME))
        WHERE NVL(pdx.IS_DELETED, 0) = 0
    ),
    -- Thông tin chi ti?t t? VW_PN_LAI_LICH_CHI_TIET (có TOI_DANH_ID, QUOC_TICH_ID, NGAY_HET_AN,
    -- NOI_THA_VE_CU_TRU_XA_ID, NOI_THA_VE_CU_TRU_TINH_ID, GIOI_TINH_ID)
    src AS (
        SELECT
            p.pn_lai_lich_id,
            v.HO_TEN,
            v.GIOI_TINH,
            v.NAM_SINH,
            v.NGAY_SINH,
            v.NOI_THUONG_TRU_DAY_DU,
            v.NGAY_BAT_AN_PHAT,
            v.TOI_DANH,
            v.TOI_DANH_ID,
            v.AN_PHAT,
            v.NGAY_HET_AN,
            v.PHAN_DOI,
            v.PHAN_DOI_ID,
            v.NOI_THA_VE_CU_TRU,
            v.NOI_THA_VE_CU_TRU_XA_ID,
            v.NOI_THA_VE_CU_TRU_TINH_ID,
            v.NOI_THA_VE_CU_TRU_XA,
            v.GIOI_TINH_ID,
            v.QUOC_TICH_ID,
            v.TRAI_GIAM,
            v.NGUYEN_QUAN,
            v.NGAY_DEN_TRAI,
            v.TEN_KHAC,
            v.DAN_TOC,
            v.QUOC_TICH,
            v.TOA_XU_TEN,
            v.TOA_XU_DIA_PHUONG,
            v.CO_QUAN_QD_THA,
            v.TOA_QD_THA_DIA_PHUONG
        FROM pn_dac_xa p
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = p.pn_lai_lich_id
           AND NVL(v.IS_DELETED, 0) = 0
    ),
    -- Thân nhân: cha (QUAN_HE_ID=19), m? (QUAN_HE_ID=18) - gi?ng SP_GET_CHI_TIET
    tn_bo AS (
        SELECT t.PHAM_NHAN_ID, t.HO_TEN_THAN_NHAN AS HO_TEN_BO
        FROM (SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN,
                     ROW_NUMBER() OVER (PARTITION BY PHAM_NHAN_ID ORDER BY ID) AS rn
              FROM THAN_NHAN_NGUOI_THANS
              WHERE QUAN_HE_ID = 19 AND NVL(IS_DELETED, 0) = 0
                AND PHAM_NHAN_ID IN (SELECT pn_lai_lich_id FROM pn_dac_xa)) t
        WHERE t.rn = 1
    ),
    tn_me AS (
        SELECT t.PHAM_NHAN_ID, t.HO_TEN_THAN_NHAN AS HO_TEN_ME
        FROM (SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN,
                     ROW_NUMBER() OVER (PARTITION BY PHAM_NHAN_ID ORDER BY ID) AS rn
              FROM THAN_NHAN_NGUOI_THANS
              WHERE QUAN_HE_ID = 18 AND NVL(IS_DELETED, 0) = 0
                AND PHAM_NHAN_ID IN (SELECT pn_lai_lich_id FROM pn_dac_xa)) t
        WHERE t.rn = 1
    ),
    src_toi_qt AS (
        SELECT
            s.*,
            dm.TD_CHUONG AS td_chuong,
            qt.QT_MA     AS quoc_tich_ma
        FROM src s
        LEFT JOIN DM_TOI_DANHS dm
               ON dm.ID = TO_NUMBER(
                    REGEXP_SUBSTR(
                        NVL(TRIM(CAST(s.TOI_DANH_ID AS VARCHAR2(4000))), ''),
                        '[0-9]+', 1, 1
                    )
                  )
              AND NVL(dm.IS_DELETED, 0) = 0
        LEFT JOIN DM_QUOC_TICHS qt
               ON qt.ID = s.QUOC_TICH_ID
              AND NVL(qt.IS_DELETED, 0) = 0
    ),
    dx_one AS (
        SELECT
            pdx.PNLAI_LICH_ID AS pnlai_lich_id,
            pdx.DX_NGAY_THA AS dx_ngay_tha,
            pdx.DX_NGAY_TRINH_DIEN AS dx_ngay_trinh_dien,
            pdx.DX_XEP_LOAI_CAI_TAO AS dx_xep_loai_cai_tao,
            ROW_NUMBER() OVER (PARTITION BY pdx.PNLAI_LICH_ID ORDER BY pdx.CREATION_TIME DESC) AS rn
        FROM PN_DAC_XAS pdx
        INNER JOIN PN_DOT_DAC_XAS dot ON dot.ID = p_dot_dac_xa_id
           AND NVL(dot.IS_DELETED, 0) = 0
           AND TRUNC(NVL(dot.DDX_NGAY_XET, dot.CREATION_TIME)) = TRUNC(NVL(pdx.DX_NGAY_XET, pdx.CREATION_TIME))
        WHERE NVL(pdx.IS_DELETED, 0) = 0
    ),
    -- K? x?p lo?i g?n nh?t mà PN tham gia (?? l?y s? Q?, ngày h?p) - gi?ng SP_GET_KQTD_CHAP_HANH_AN_PHAT_TU_DX
    ky_xep_loai_cua_pn AS (
        SELECT
            m.PN_LAI_LICHS_ID AS pn_lai_lich_id,
            k.NGAY_HOP_XEP_LOAI,
            k.SO_QUYET_DINH_TU,
            k.NAM_XEP_LOAI,
            ROW_NUMBER() OVER (PARTITION BY m.PN_LAI_LICHS_ID ORDER BY k.NAM_XEP_LOAI DESC NULLS LAST, k.NGAY_HOP_XEP_LOAI DESC NULLS LAST) AS rn
        FROM MO_KY_XEP_LOAI_CAI_TAO_PN_LAI_LICH m
        INNER JOIN MO_KY_XEP_LOAI_CAI_TAOS k ON k.ID = m.MO_KY_XEP_LOAI_CAI_TAOS_ID AND NVL(k.IS_DELETED, 0) = 0
        WHERE m.PN_LAI_LICHS_ID IN (SELECT pn_lai_lich_id FROM pn_dac_xa)
    ),
    ky_latest AS (
        SELECT pn_lai_lich_id, NGAY_HOP_XEP_LOAI AS ngay_hop_xep_loai, SO_QUYET_DINH_TU AS so_quyet_dinh_tu
        FROM ky_xep_loai_cua_pn
        WHERE rn = 1
    ),
    -- ??t ??c xá (?? l?y so_cong_van, so_quyet_dinh_dac_xa) - gi?ng SP_GET_CHI_TIET_PN_DUOC_DAC_XA
    dot_once AS (
        SELECT NVL(DDX_TG_SO_PHIEU, DDX_SO_HUONG_DAN) AS so_cong_van,
               DDX_SO_QUYET_DINH AS so_quyet_dinh_dac_xa
        FROM PN_DOT_DAC_XAS
        WHERE ID = p_dot_dac_xa_id AND NVL(IS_DELETED, 0) = 0
    ),
    -- Thi hành án m?i nh?t theo PN (?? l?y th?i gian t?m giam/gi?, b?n án, Q? tha) - gi?ng SP_GET_CHI_TIET
    tha_one AS (
        SELECT THA_PNLAI_LICH_ID AS pn_lai_lich_id,
               THA_THOI_GIAN_TAM_GIAM, THA_THOI_GIAN_TAM_GIU,
               THA_SO_BAN_AN, THA_NGAY_BAN_AN,
               THA_SO_QD_THA, THA_NGAY_QD_THA,
               ROW_NUMBER() OVER (PARTITION BY THA_PNLAI_LICH_ID ORDER BY THA_NGAY_DEN_TRAI DESC NULLS LAST) AS rn
        FROM PN_THI_HANH_AN
        WHERE THA_PNLAI_LICH_ID IN (SELECT pn_lai_lich_id FROM pn_dac_xa) AND NVL(IS_DELETED, 0) = 0
    )
    SELECT
        -- Gi?ng SP_GET_KQTD_CHAP_HANH_AN_PHAT_TU_DX
        u'C10' AS CO_QUAN_CHU_QUAN,
        NVL(CAST(tq.TRAI_GIAM AS VARCHAR2(4000)), '') AS TEN_TRAI_GIAM,
        TO_CHAR(ky.SO_QUYET_DINH_TU) AS SO_QUYET_DINH,
        CAST(NULL AS VARCHAR2(255)) AS DIA_DANH,
        ky.NGAY_HOP_XEP_LOAI AS NGAY_HOP,
        -- H? tên
        NVL(TRIM(tq.HO_TEN), '') AS HO_TEN,
        -- Gi?i tính
        NVL(TRIM(tq.GIOI_TINH), '') AS GIOI_TINH,
        -- Ngày sinh
        CASE
            WHEN tq.NGAY_SINH IS NOT NULL
                 AND REGEXP_LIKE(CAST(tq.NGAY_SINH AS VARCHAR2(50)), '^\d{1,2}/\d{1,2}/\d{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(CAST(tq.NGAY_SINH AS VARCHAR2(50))), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN tq.NAM_SINH IS NOT NULL AND tq.NAM_SINH > 0
            THEN TO_CHAR(tq.NAM_SINH)
            WHEN tq.NGAY_SINH IS NOT NULL
                 AND LENGTH(TRIM(CAST(tq.NGAY_SINH AS VARCHAR2(50)))) >= 4
            THEN TRIM(CAST(tq.NGAY_SINH AS VARCHAR2(50)))
            ELSE NULL
        END AS NGAY_SINH,
        -- Tên khác, Nguyên quán
        NVL(CAST(tq.TEN_KHAC AS VARCHAR2(4000)), '') AS TEN_KHAC,
        NVL(CAST(tq.NGUYEN_QUAN AS VARCHAR2(4000)), '') AS NGUYEN_QUAN,
        -- N?i ??ng ký th??ng trú
        NVL(TRIM(tq.NOI_THUONG_TRU_DAY_DU), '') AS NOI_DKTT,
        -- H? tên cha, m? (gi?ng SP_GET_CHI_TIET)
        NVL(CAST(tnb.HO_TEN_BO AS VARCHAR2(4000)), '') AS HO_TEN_BO,
        NVL(CAST(tnm.HO_TEN_ME AS VARCHAR2(4000)), '') AS HO_TEN_ME,
        -- Ngày b?t, Th?i gian t?m giam/gi?, B?n án (gi?ng SP_GET_CHI_TIET)
        TO_CHAR(tq.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT,
        tha.THA_THOI_GIAN_TAM_GIAM AS THOI_GIAN_TAM_GIAM,
        tha.THA_THOI_GIAN_TAM_GIU AS THOI_GIAN_TAM_GIU,
        tha.THA_SO_BAN_AN AS SO_BA,
        CASE WHEN tha.THA_NGAY_BAN_AN IS NOT NULL THEN TO_CHAR(tha.THA_NGAY_BAN_AN, 'DD/MM/YYYY') ELSE NULL END AS NGAY_BA,
        NVL(CAST(tq.TOA_XU_TEN AS VARCHAR2(4000)), CAST(tq.TOA_XU_DIA_PHUONG AS VARCHAR2(4000))) AS TOA_BA,
        tha.THA_SO_QD_THA AS SO_QDTHA,
        CASE WHEN tha.THA_NGAY_QD_THA IS NOT NULL THEN TO_CHAR(tha.THA_NGAY_QD_THA, 'DD/MM/YYYY') ELSE NULL END AS NGAY_QDTHA,
        NVL(CAST(tq.CO_QUAN_QD_THA AS VARCHAR2(4000)), CAST(tq.TOA_QD_THA_DIA_PHUONG AS VARCHAR2(4000))) AS TOA_QDTHA,
        -- Dân t?c, Qu?c t?ch
        NVL(CAST(tq.DAN_TOC AS VARCHAR2(4000)), '') AS DAN_TOC,
        NVL(CAST(tq.QUOC_TICH AS VARCHAR2(4000)), '') AS QUOC_TICH,
        -- T?i danh
        NVL(CAST(tq.TOI_DANH AS VARCHAR2(4000)), '') AS TOI_DANH,
        -- Án ph?t
        NVL(CAST(tq.AN_PHAT AS VARCHAR2(4000)), '') AS AN_PHAT,
        -- Ngày h?t h?n
        CASE
            WHEN tq.NGAY_HET_AN IS NOT NULL
            THEN TO_CHAR(tq.NGAY_HET_AN, 'DD/MM/YYYY')
            ELSE NULL
        END AS NGAY_HET_HAN,
        -- Ngày ??n tr?i
        CASE WHEN tq.NGAY_DEN_TRAI IS NOT NULL THEN TO_CHAR(tq.NGAY_DEN_TRAI, 'DD/MM/YYYY') ELSE NULL END AS NGAY_DEN_TRAI,
        -- Phân ??i
        NVL(CAST(tq.PHAN_DOI AS VARCHAR2(4000)), '') AS PHAN_DOI,
        -- ?ánh giá c?i t?o (t? PN_DAC_XAS.DX_XEP_LOAI_CAI_TAO)
        NVL(CAST(dx.DX_XEP_LOAI_CAI_TAO AS VARCHAR2(4000)), '') AS DANH_GIA_CAI_TAO,
        -- Ngày tha
        CASE
            WHEN dx.DX_NGAY_THA IS NOT NULL
            THEN TO_CHAR(dx.DX_NGAY_THA, 'DD/MM/YYYY')
            ELSE NULL
        END AS NGAY_THA,
        -- Ngày trình di?n
        CASE
            WHEN dx.DX_NGAY_TRINH_DIEN IS NOT NULL
            THEN TO_CHAR(dx.DX_NGAY_TRINH_DIEN, 'DD/MM/YYYY')
            ELSE NULL
        END AS NGAY_TRINH_DIEN,
        -- S? công v?n, S? Q? ??c xá (gi?ng SP_GET_CHI_TIET)
        dot.so_cong_van AS SO_CONG_VAN,
        dot.so_quyet_dinh_dac_xa AS SO_QUYET_DINH_DAC_XA,
        -- HPBS, Ph??ng/xã v?
        NVL(CAST(FN_GET_LIET_KE_HPBS(tq.pn_lai_lich_id) AS VARCHAR2(4000)), '') AS HPBS_KHAC,
        NVL(CAST(FN_GET_LIET_KE_HPBS_CHI_TIET(tq.pn_lai_lich_id) AS VARCHAR2(4000)), '') AS HPBS,
        NVL(CAST(tq.NOI_THA_VE_CU_TRU_XA AS VARCHAR2(4000)), '') AS PX_VE,
        -- ??a ch? v?
        NVL(CAST(tq.NOI_THA_VE_CU_TRU AS VARCHAR2(4000)), '') AS DIA_CHI_VE
    FROM src_toi_qt tq
    LEFT JOIN dx_one dx
           ON dx.pnlai_lich_id = tq.pn_lai_lich_id
          AND dx.rn = 1
    LEFT JOIN ky_latest ky
           ON ky.pn_lai_lich_id = tq.pn_lai_lich_id
    CROSS JOIN dot_once dot
    LEFT JOIN (
        SELECT pn_lai_lich_id, THA_THOI_GIAN_TAM_GIAM, THA_THOI_GIAN_TAM_GIU,
               THA_SO_BAN_AN, THA_NGAY_BAN_AN, THA_SO_QD_THA, THA_NGAY_QD_THA
        FROM tha_one WHERE rn = 1
    ) tha ON tha.pn_lai_lich_id = tq.pn_lai_lich_id
    LEFT JOIN tn_bo tnb ON tnb.PHAM_NHAN_ID = tq.pn_lai_lich_id
    LEFT JOIN tn_me tnm ON tnm.PHAM_NHAN_ID = tq.pn_lai_lich_id
    WHERE 1 = 1
      AND (p_phan_doi_id IS NULL OR tq.PHAN_DOI_ID = p_phan_doi_id)
      -- ??i t??ng: 1 = ANQG (TD_CHUONG='13'), 2 = án hình s?
      AND (p_doi_tuong IS NULL
           OR (p_doi_tuong = 1 AND TRIM(CAST(NVL(tq.td_chuong, '') AS VARCHAR2(10))) = '13')
           OR (p_doi_tuong = 2 AND (tq.td_chuong IS NULL
                                    OR TRIM(CAST(NVL(tq.td_chuong, '') AS VARCHAR2(10))) <> '13')))
      -- Qu?c t?ch: 250 = Vi?t Nam (QT_MA=250), 999 = n??c ngoài
      AND (p_quoc_tich IS NULL
           OR (p_quoc_tich = 250 AND tq.quoc_tich_ma = 250)
           OR (p_quoc_tich = 999 AND (tq.quoc_tich_ma IS NULL OR tq.quoc_tich_ma <> 250)))
      -- Gi?i tính
      AND (p_gioi_tinh_id IS NULL OR tq.GIOI_TINH_ID = p_gioi_tinh_id)
      -- Tình tr?ng xét
      AND (p_tinh_trang_xet_id IS NULL
           OR EXISTS (
               SELECT 1
               FROM PN_DAC_XAS pdx
               JOIN DM_DUOC_DAC_XAS ddx
                 ON ddx.ID = p_tinh_trang_xet_id
                AND NVL(ddx.IS_DELETED, 0) = 0
                AND TRIM(CAST(NVL(pdx.DX_TINH_TRANG_DAC_XA, '') AS VARCHAR2(100)))
                    = TRIM(CAST(NVL(ddx.DDX_MA, '') AS VARCHAR2(100)))
               INNER JOIN PN_DOT_DAC_XAS dot2 ON dot2.ID = p_dot_dac_xa_id
                  AND NVL(dot2.IS_DELETED, 0) = 0
                  AND TRUNC(NVL(dot2.DDX_NGAY_XET, dot2.CREATION_TIME)) = TRUNC(NVL(pdx.DX_NGAY_XET, pdx.CREATION_TIME))
               WHERE pdx.PNLAI_LICH_ID = tq.pn_lai_lich_id
                 AND NVL(pdx.IS_DELETED, 0) = 0
           ))
      -- T?nh ???c tha v?
      AND (p_tinh_ve_id IS NULL OR tq.NOI_THA_VE_CU_TRU_TINH_ID = p_tinh_ve_id)
      -- Xã/ph??ng ???c tha v?
      AND (p_xa_ve_id IS NULL OR tq.NOI_THA_VE_CU_TRU_XA_ID = p_xa_ve_id)
      -- Ngày tha
      AND (p_ngay_tha IS NULL
           OR (dx.DX_NGAY_THA IS NOT NULL AND TRUNC(dx.DX_NGAY_THA) = TRUNC(p_ngay_tha)))
      -- Ngày trình di?n
      AND (p_ngay_trinh_dien IS NULL
           OR (dx.DX_NGAY_TRINH_DIEN IS NOT NULL AND TRUNC(dx.DX_NGAY_TRINH_DIEN) = TRUNC(p_ngay_trinh_dien)))
      -- H? tên LIKE
      AND (p_ho_ten IS NULL
           OR UPPER(CAST(NVL(tq.HO_TEN, '') AS VARCHAR2(4000)))
              LIKE '%' || UPPER(TRIM(CAST(NVL(p_ho_ten, '') AS VARCHAR2(4000)))) || '%')
    ORDER BY tq.PHAN_DOI, tq.HO_TEN;

    DBMS_SQL.RETURN_RESULT(c1);
END ;


-- Ví d? g?i:
-- EXEC SP_GET_BAO_CAO_PN_DUOC_DAC_XA_FILTER(198, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL)

-- =============================================================================
-- SP_GET_BAO_CAO_PN_DUOC_DAC_XA
-- Báo cáo ph?m nhân ?ã ???c ??c xá theo ??t.
-- Ngu?n chính: PN_DAC_XAS + VW_PN_LAI_LICH_CHI_TIET + DM_TOI_DANHS + DM_QUOC_TICHS.
--
-- Filters:
--   p_dot_dac_xa_id    : ??t ??c xá (PN_DOT_DAC_XAS.ID)
--   p_phan_doi_id      : Phân ??i (DM_PHAN_DOIS.ID)
--   p_doi_tuong        : 1=T?i ANQG (TD_CHUONG='13'), 2=Án hình s? (TD_CHUONG<>'13'), null=T?t c?
--   p_quoc_tich        : 250=Vi?t Nam (QT_MA=250), 999=N??c ngoài (QT_MA<>250), null=T?t c?
--   p_gioi_tinh_id     : Gi?i tính (DM_GIOI_TINHS.ID) t? VW_PN_LAI_LICH_CHI_TIET.GIOI_TINH_ID
--   p_tinh_trang_xet_id: Tình tr?ng xét (DM_DUOC_DAC_XAS.ID), map PN_DAC_XAS.DX_TINH_TRANG_DAC_XA = DM_DUOC_DAC_XAS.DDX_MA
--   p_tinh_ve_id       : T?nh ???c tha v? (NOI_THA_VE_CU_TRU_TINH_ID)
--   p_xa_ve_id         : Xã/ph??ng ???c tha v? (NOI_THA_VE_CU_TRU_XA_ID)
--   p_ngay_tha         : L?c theo ngày tha (DX_NGAY_THA)
--   p_ngay_trinh_dien  : L?c theo ngày trình di?n
--   p_ho_ten           : Tìm ki?m LIKE, không phân bi?t hoa/th??ng
--
-- Output (gi?ng SP_GET_CHI_TIET_PN_DUOC_DAC_XA + SP_GET_KQTD_CHAP_HANH_AN_PHAT_TU_DX):
--   CO_QUAN_CHU_QUAN, TEN_TRAI_GIAM, SO_QUYET_DINH, DIA_DANH, NGAY_HOP,
--   HO_TEN, GIOI_TINH, NGAY_SINH, TEN_KHAC, NGUYEN_QUAN, NOI_DKTT,
--   HO_TEN_BO, HO_TEN_ME, NGAY_BAT, THOI_GIAN_TAM_GIAM, THOI_GIAN_TAM_GIU,
--   SO_BA, NGAY_BA, TOA_BA, SO_QDTHA, NGAY_QDTHA, TOA_QDTHA,
--   DAN_TOC, QUOC_TICH, TOI_DANH, AN_PHAT, NGAY_HET_HAN, NGAY_DEN_TRAI,
--   PHAN_DOI, DANH_GIA_CAI_TAO, NGAY_THA, NGAY_TRINH_DIEN,
--   SO_CONG_VAN, SO_QUYET_DINH_DAC_XA, HPBS_KHAC, HPBS, PX_VE, DIA_CHI_VE
-- =============================================================================;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_BAO_CAO_TK_PN_DANG_CHAP_HANH_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_BAO_CAO_TK_PN_DANG_CHAP_HANH_AN" (
    p_trai_giam_id   IN  NVARCHAR2    DEFAULT NULL,
    p_tu_ngay        IN  VARCHAR2  DEFAULT NULL,
    p_den_ngay       IN  VARCHAR2  DEFAULT NULL
) AS
    v_den_ngay DATE;
    v_tu_ngay  DATE;
    C1         SYS_REFCURSOR;
BEGIN
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := TRUNC(SYSDATE);
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN C1 FOR
    WITH
    -- PN ?ang ch?p hành án t?i ngày v_den_ngay: có THA hi?u l?c (ngày b?t <= den_ngay, ngày h?t >= den_ngay)
    tha_hieu_luc AS (
        SELECT tha.tha_pnlai_lich_id AS pn_id
        FROM PN_THI_HANH_AN tha
        WHERE NVL(tha.is_deleted, 0) = 0
          AND tha.tha_pnlai_lich_id IS NOT NULL
          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) <= v_den_ngay
          AND (tha.tha_ngay_het_han IS NULL OR tha.tha_ngay_het_han >= v_den_ngay)
    ),
    tha_den_trai AS (
        SELECT tha.tha_pnlai_lich_id AS pn_id,
               tha.tha_ngay_den_trai AS ngay_den_trai,
               ROW_NUMBER() OVER (PARTITION BY tha.tha_pnlai_lich_id ORDER BY tha.tha_ngay_den_trai DESC NULLS LAST) AS rn
        FROM PN_THI_HANH_AN tha
        WHERE NVL(tha.is_deleted, 0) = 0
          AND tha.tha_pnlai_lich_id IN (SELECT pn_id FROM tha_hieu_luc)
    ),
    dang_chap_hanh AS (
        SELECT ll.id AS pn_lai_lich_id,
               ll.ll_phan_trai_id AS phan_trai_id,
               ll.ll_phan_doi_id AS phan_doi_id,
               ll.ll_dm_gioi_tinh_id AS gioi_tinh_id
        FROM PN_LAI_LICHS ll
        INNER JOIN tha_hieu_luc t ON t.pn_id = ll.id
        LEFT JOIN tha_den_trai td ON td.pn_id = ll.id AND td.rn = 1
        WHERE NVL(ll.is_deleted, 0) = 0
          AND (p_trai_giam_id IS NULL OR ll.ll_trai_giam_id = p_trai_giam_id)
          AND (v_tu_ngay IS NULL OR (td.ngay_den_trai IS NOT NULL AND TRUNC(td.ngay_den_trai) >= v_tu_ngay))
    ),
    src AS (
        SELECT
            d.pn_lai_lich_id,
            d.phan_trai_id,
            d.phan_doi_id,
            TRIM(NVL(pt.pt_ten, u'Ch\01b0a x\00e1c \0111\1ecbnh') || u' - ' || NVL(pd.pd_ten, u'Ch\01b0a x\00e1c \0111\1ecbnh')) AS don_vi,
            CASE WHEN d.gioi_tinh_id = 22 THEN 1 ELSE 0 END AS is_nam,
            CASE WHEN d.gioi_tinh_id = 23 THEN 1 ELSE 0 END AS is_nu,
            CASE WHEN d.gioi_tinh_id NOT IN (22, 23) OR d.gioi_tinh_id IS NULL THEN 1 ELSE 0 END AS is_khac
        FROM dang_chap_hanh d
        LEFT JOIN DM_PHAN_TRAIS pt ON pt.id = d.phan_trai_id AND NVL(pt.is_deleted, 0) = 0
        LEFT JOIN DM_PHAN_DOIS pd ON pd.id = d.phan_doi_id AND NVL(pd.is_deleted, 0) = 0
    ),
    agg AS (
        SELECT
            s.phan_trai_id,
            s.phan_doi_id,
            s.don_vi,
            SUM(s.is_nam) AS so_nam,
            SUM(s.is_nu)  AS so_nu,
            SUM(s.is_khac) AS so_khac,
            COUNT(*)      AS tong_so
        FROM src s
        GROUP BY s.phan_trai_id, s.phan_doi_id, s.don_vi
    ),
    with_tt AS (
        SELECT ROW_NUMBER() OVER (ORDER BY NVL(phan_trai_id, 0), NVL(phan_doi_id, 0)) AS tt,
               don_vi AS don_vi,
               so_nam AS nam,
               so_nu  AS nu,
               so_khac AS khac,
               tong_so
        FROM agg
    )
    SELECT tt, don_vi, nam, nu, khac, tong_so
    FROM with_tt
    ORDER BY tt;

    DBMS_SQL.RETURN_RESULT(C1);
END;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_CHI_TIET_PN_CHAP_HANH_XONG_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_CHI_TIET_PN_CHAP_HANH_XONG_AN" (
    p_dot_dac_xa_id   IN  NUMBER,
    p_ten_trai_giam   IN  VARCHAR2 DEFAULT NULL
) AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    WITH
    dot AS (
        SELECT id,
               ddx_so_quyet_dinh,
               ddx_ngay_quyet_dinh,
               ddx_tg_so_gcn,
               ddx_tg_so_huong_dan,
               ddx_ngay_xet
        FROM PN_DOT_DAC_XAS
        WHERE id = p_dot_dac_xa_id AND is_deleted = 0
    ),
    -- PN ch?p hành xong án (có b?n ghi k?t thúc ra tr?i) trong n?m c?a ??t, l?c tr?i
    src AS (
        SELECT
            k.id AS ktrt_id,
            k.ktrt_pn_lai_lich_id AS pn_lai_lich_id,
            k.ktrt_ngay_tha,
            k.ktrt_ngay_trinh_dien,
            k.ktrt_cong_an_tinh_thanh_pho_id,
            ll.ll_trai_giam_id,
            ll.ll_ngay_sinh,
            ll.ll_ten_khac,
            ll.ll_nguyen_quan,
            ll.ll_noi_tha_ve_cu_tru_ward,
            ll.ll_phan_doi_id,
            NVL(tg.TG_TEN, '') AS ten_trai_giam
        FROM PN_KET_THUC_RA_TRAIS k
        INNER JOIN dot ON 1 = 1
        INNER JOIN PN_LAI_LICHS ll ON ll.id = k.ktrt_pn_lai_lich_id AND ll.is_deleted = 0
        LEFT JOIN DM_TRAI_GIAMS tg ON tg.id = ll.ll_trai_giam_id AND tg.is_deleted = 0
        WHERE k.is_deleted = 0
          AND EXTRACT(YEAR FROM k.ktrt_ngay_tha) = EXTRACT(YEAR FROM dot.ddx_ngay_xet)
          AND (p_ten_trai_giam IS NULL OR TRIM(p_ten_trai_giam) = ''
               OR UPPER(NVL(tg.TG_TEN, '')) LIKE '%' || UPPER(TRIM(p_ten_trai_giam)) || '%')
    ),
    v AS (
        SELECT
            s.pn_lai_lich_id,
            s.ten_trai_giam,
            s.ll_ngay_sinh,
            s.ll_ten_khac,
            s.ll_nguyen_quan,
            s.ll_noi_tha_ve_cu_tru_ward,
            s.ll_phan_doi_id,
            s.ktrt_ngay_tha,
            s.ktrt_ngay_trinh_dien,
            s.ktrt_cong_an_tinh_thanh_pho_id,
            vw.HO_TEN,
            vw.GIOI_TINH,
            vw.NAM_SINH,
            vw.NOI_THUONG_TRU_DAY_DU,
            vw.TOI_DANH,
            vw.NGAY_BAT_AN_PHAT,
            vw.AN_PHAT,
            vw.NOI_THA_VE_CU_TRU,
            vw.DAN_TOC,
            vw.QUOC_TICH
        FROM src s
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET vw ON vw.PHAM_NHAN_ID = s.pn_lai_lich_id
    ),
    tha_one AS (
        SELECT tha_pnlai_lich_id,
               tha_so_ban_an,
               tha_ngay_ban_an,
               tha_an_phat,
               tha_thoi_gian_tam_giam,
               tha_thoi_gian_tam_giu,
               tha_dia_phuong_cap_toa_id,
               ROW_NUMBER() OVER (PARTITION BY tha_pnlai_lich_id ORDER BY tha_ngay_den_trai DESC NULLS LAST) AS rn
        FROM PN_THI_HANH_AN
        WHERE is_deleted = 0
    ),
    xl AS (
        SELECT pham_nhan_id, xep_loai_ca_nam,
               ROW_NUMBER() OVER (PARTITION BY pham_nhan_id ORDER BY xep_loai_nam DESC NULLS LAST) AS rn
        FROM XEP_LOAIS WHERE is_deleted = 0
    )
    SELECT
        CAST(NULL AS VARCHAR2(500)) AS co_quan_chu_quan,
        v.ten_trai_giam,
        NVL(dot.ddx_tg_so_gcn, dot.ddx_tg_so_huong_dan) AS so_thong_bao,
        CAST(NULL AS VARCHAR2(255)) AS tinh_trai_giam,
        (SELECT dvh.XP_TEN FROM DM_XA_PHUONG dvh WHERE dvh.id = v.ll_noi_tha_ve_cu_tru_ward AND ROWNUM = 1) AS px_ve,
        (SELECT dvh.TTP_TEN FROM DM_TINH_THANH_PHO dvh WHERE dvh.id = v.ktrt_cong_an_tinh_thanh_pho_id AND ROWNUM = 1) AS cong_an_dia_phuong_ve,
        dot.ddx_so_quyet_dinh AS so_quyet_dinh_dac_xa,
        dot.ddx_ngay_quyet_dinh AS ngay_quyet_dinh_dac_xa,
        v.HO_TEN AS ho_ten,
        v.GIOI_TINH AS gioi_tinh,
        NVL(v.ll_ngay_sinh, CASE WHEN v.NAM_SINH IS NOT NULL AND v.NAM_SINH > 0 THEN TO_CHAR(v.NAM_SINH) ELSE NULL END) AS ngay_sinh,
        v.ll_ten_khac AS ten_khac,
        v.ll_nguyen_quan AS nguyen_quan,
        v.NOI_THUONG_TRU_DAY_DU AS dia_chi_thuong_tru,
        v.DAN_TOC AS dan_toc,
        v.QUOC_TICH AS quoc_tich,
        v.TOI_DANH AS toi_danh,
        v.NGAY_BAT_AN_PHAT AS ngay_bat,
        t.tha_an_phat AS muc_an_phat,
        TRIM(NVL(t.tha_thoi_gian_tam_giam,'') || ' ' || NVL(t.tha_thoi_gian_tam_giu,'')) AS giam_giu,
        t.tha_so_ban_an AS ban_an_so,
        t.tha_ngay_ban_an AS ngay_xu,
        (SELECT dvh.TTP_TEN FROM DM_TINH_THANH_PHO dvh WHERE dvh.id = t.tha_dia_phuong_cap_toa_id AND ROWNUM = 1) AS toa_xu,
        (SELECT LISTAGG(g.so_quyet_dinh || ' ' || TO_CHAR(g.ngay_quyet_dinh,'DD/MM/YYYY'), '; ') WITHIN GROUP (ORDER BY g.ngay_quyet_dinh DESC)
         FROM GIAM_THOI_HANS g WHERE g.pham_nhan_id = v.pn_lai_lich_id AND g.is_deleted = 0) AS da_giam,
        (SELECT pd.PD_Ten FROM DM_PHAN_DOIS pd WHERE pd.id = v.ll_phan_doi_id AND ROWNUM = 1) AS phan_doi,
        v.NOI_THA_VE_CU_TRU AS dia_chi_ve_cu_tru,
        xl.xep_loai_ca_nam AS ket_qua_chap_hanh_an_phat_tu,
        FN_GET_LIET_KE_HPBS_CHI_TIET(v.pn_lai_lich_id) AS hpbs,
        FN_GET_LIET_KE_HPBS(v.pn_lai_lich_id) AS hpbs_khac
    FROM v
    CROSS JOIN dot
    LEFT JOIN tha_one t ON t.tha_pnlai_lich_id = v.pn_lai_lich_id AND t.rn = 1
    LEFT JOIN xl ON xl.pham_nhan_id = v.pn_lai_lich_id AND xl.rn = 1
    ORDER BY v.ten_trai_giam, v.HO_TEN, v.pn_lai_lich_id;
    DBMS_SQL.RETURN_RESULT(C1);

    --   EXEC SP_GET_CHI_TIET_PN_CHAP_HANH_XONG_AN(28, 'B?n Giá');

END SP_GET_CHI_TIET_PN_CHAP_HANH_XONG_AN;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_CHI_TIET_PN_DUOC_DAC_XA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_CHI_TIET_PN_DUOC_DAC_XA" (
    p_pham_nhan_id    IN  NUMBER
) AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    WITH
    src AS (
        SELECT
            v.pn_lai_lich_id,
            v.pn_dot_dac_xa_id,
            v.HO_TEN,
            v.GIOI_TINH,
            v.NAM_SINH,
            v.NOI_THUONG_TRU_DAY_DU,
            v.TOI_DANH,
            v.NGAY_BAT_AN_PHAT,
            v.AN_PHAT,
            v.NGAY_DEN_TRAI,
            v.NOI_THA_VE_CU_TRU,
            v2.DAN_TOC,
            v2.QUOC_TICH,
            ll.ll_ngay_sinh,
            ll.ll_ten_khac,
            ll.ll_nguyen_quan,
            ll.ll_nhan_than,
            ll.ll_noi_tha_ve_cu_tru_ward,
            NVL(v.ten_trai_giam, '') AS ten_trai_giam,
            v2.TOA_XU_TEN,
            v2.TOA_XU_DIA_PHUONG,
            v2.CO_QUAN_QD_THA,
            v2.TOA_QD_THA_DIA_PHUONG,
            v2.NOI_THA_VE_CU_TRU_XA,
            v2.NOI_THA_VE_CU_TRU_TINH,
            tnb.HO_TEN_THAN_NHAN AS ho_ten_bo,
            tnm.HO_TEN_THAN_NHAN AS ho_ten_me
        FROM VW_BAO_CAO_DX_CHI_TIET v
        LEFT JOIN VW_PN_LAI_LICH_CHI_TIET v2 ON v2.PHAM_NHAN_ID = v.pn_lai_lich_id
        LEFT JOIN PN_LAI_LICHS ll ON ll.id = v.pn_lai_lich_id AND ll.is_deleted = 0
        LEFT JOIN THAN_NHAN_NGUOI_THANS tnb ON tnb.PHAM_NHAN_ID = v.pn_lai_lich_id AND tnb.QUAN_HE_ID = 19 AND NVL(tnb.IS_DELETED, 0) = 0
        LEFT JOIN THAN_NHAN_NGUOI_THANS tnm ON tnm.PHAM_NHAN_ID = v.pn_lai_lich_id AND tnm.QUAN_HE_ID = 18 AND NVL(tnm.IS_DELETED, 0) = 0
        WHERE v.pn_lai_lich_id = p_pham_nhan_id
    ),
    tha_one AS (
        SELECT tha_pnlai_lich_id,
               tha_so_ban_an,
               tha_ngay_ban_an,
               tha_thoi_gian_tam_giam,
               tha_thoi_gian_tam_giu,
               tha_so_qd_tha,
               tha_ngay_qd_tha,
               tha_dia_phuong_cap_toa_id,
               tha_dia_phuong_toa_qd_tha_id,
               ROW_NUMBER() OVER (PARTITION BY tha_pnlai_lich_id ORDER BY tha_ngay_den_trai DESC NULLS LAST) AS rn
        FROM PN_THI_HANH_AN
        WHERE tha_pnlai_lich_id = p_pham_nhan_id AND is_deleted = 0
    ),
    dx_one AS (
        SELECT pnlai_lich_id, dx_ngay_tha, dx_ngay_trinh_dien,
               ROW_NUMBER() OVER (PARTITION BY pnlai_lich_id ORDER BY creation_time DESC) AS rn
        FROM PN_DAC_XAS
        WHERE pnlai_lich_id = p_pham_nhan_id AND is_deleted = 0
    )
    SELECT
         u'C10' AS co_quan_chu_quan,
        s.ten_trai_giam,
        NVL(dot.ddx_tg_so_phieu, dot.ddx_so_huong_dan) AS so_cong_van,
        dot.ddx_so_quyet_dinh AS so_quyet_dinh_dac_xa,
        s.HO_TEN AS ho_ten,
        s.GIOI_TINH AS gioi_tinh,
        NVL(s.ll_ngay_sinh, CASE WHEN s.NAM_SINH IS NOT NULL AND s.NAM_SINH > 0 THEN TO_CHAR(s.NAM_SINH) ELSE NULL END) AS ngay_sinh,
        s.ll_ten_khac AS ten_khac,
        s.ll_nguyen_quan AS nguyen_quan,
        s.NOI_THUONG_TRU_DAY_DU AS dia_chi_thuong_tru,
        s.ho_ten_bo,
        s.ho_ten_me,
        s.DAN_TOC AS dan_toc,
        s.QUOC_TICH AS quoc_tich,
        s.TOI_DANH AS toi_danh,
        s.NGAY_BAT_AN_PHAT AS ngay_bat,
        t.tha_thoi_gian_tam_giam AS thoi_gian_tam_giam,
        t.tha_thoi_gian_tam_giu AS thoi_gian_tam_giu,
        t.tha_so_ban_an AS so_ba,
        t.tha_ngay_ban_an AS ngay_ba,
        NVL(s.TOA_XU_TEN, s.TOA_XU_DIA_PHUONG) AS toa_ba,
        t.tha_so_qd_tha AS so_qdtha,
        t.tha_ngay_qd_tha AS ngay_qdtha,
        NVL(s.CO_QUAN_QD_THA, s.TOA_QD_THA_DIA_PHUONG) AS toa_qdtha,
        dx.dx_ngay_tha AS ngay_tha,
        s.NOI_THA_VE_CU_TRU AS dc_ve,
        FN_GET_LIET_KE_HPBS(s.pn_lai_lich_id) AS hpbs_khac,
        FN_GET_LIET_KE_HPBS_CHI_TIET(s.pn_lai_lich_id) AS hpbs,
        s.NOI_THA_VE_CU_TRU_XA AS px_ve,
        dx.dx_ngay_trinh_dien AS ngay_trinh_dien
    FROM src s
    INNER JOIN PN_DOT_DAC_XAS dot ON dot.id = s.pn_dot_dac_xa_id AND dot.is_deleted = 0
    LEFT JOIN tha_one t ON t.tha_pnlai_lich_id = s.pn_lai_lich_id AND t.rn = 1
    LEFT JOIN dx_one dx ON dx.pnlai_lich_id = s.pn_lai_lich_id AND dx.rn = 1
    ORDER BY s.ten_trai_giam, s.HO_TEN, s.pn_lai_lich_id;
    DBMS_SQL.RETURN_RESULT(C1);


    --   EXEC SP_GET_CHI_TIET_PN_DUOC_DAC_XA(22);

END ;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_CHUA_BENH_BAT_BUOC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_CHUA_BENH_BAT_BUOC" (
    p_PHAM_NHAN_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        cbbb.PHAM_NHAN_ID,
        cbbb.SO_QUYET_DINH || ', ' || TO_CHAR(cbbb.NGAY_QUYET_DINH, 'DD/MM/YYYY') AS "SoQD",
        dmtg.MTG_TITLE  AS "ThoiHan",
        cbbb.TU_NGAY AS "TuNgay",
        dnnc.NNC_TEN  AS "MaBenhTat",
        cbbb.NGAY_BAT_DAU AS "NgayDi",
        cbbb.NGAY_KET_THUC AS "NgayVe"
    FROM CHUA_BENH_BAT_BUOCS cbbb
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON cbbb.THOI_HAN = dmtg.ID
    LEFT JOIN DM_NGUYEN_NHAN_CHETS dnnc ON cbbb.BENH_TAT_ID = dnnc.ID
    WHERE cbbb.PHAM_NHAN_ID = p_PHAM_NHAN_ID
	AND cbbb.IS_DELETED = 0;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_CHUA_BENH_BAT_BUOC;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_CHUA_BENH_BAT_BUOC_PT99
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_CHUA_BENH_BAT_BUOC_PT99" (
    p_cbbb_id    IN NUMBER DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        WITH cb_one AS (
            SELECT cb.*
            FROM qlpn.chua_benh_bat_buocs cb
            WHERE NVL(cb.is_deleted, 0) = 0
              AND (p_cbbb_id IS NULL OR cb.id = p_cbbb_id)
        ),
        vw_one AS (
            SELECT v.*
            FROM qlpn.vw_pn_lai_lich_chi_tiet v
            WHERE NVL(v.is_deleted, 0) = 0
              AND v.pham_nhan_id IN (SELECT cb0.pham_nhan_id FROM cb_one cb0)
        ),
        cb_info AS (
            SELECT
                cb.id AS cb_id,
                cb.pham_nhan_id,
                cb.so_quyet_dinh,
                TO_CHAR(CAST(cb.ngay_quyet_dinh AS DATE), 'DD/MM/YYYY') AS NGAY_QUYET_DINH,
                cb.thoi_han,
                TO_CHAR(CAST(cb.tu_ngay AS DATE), 'DD/MM/YYYY') AS TU_NGAY,
                TO_CHAR(CAST(cb.ngay_bat_dau AS DATE), 'DD/MM/YYYY') AS NGAY_BAT_DAU,
                TO_CHAR(CAST(cb.ngay_ket_thuc AS DATE), 'DD/MM/YYYY') AS NGAY_KET_THUC,
                cb.noi_chua_benh,
                cb.chi_tiet_benh,
                NVL(dbt.bt_ten, dnnc.nnc_ten) AS TEN_BENH,
                cq.cq_ten AS CO_QUAN_QUYET_DINH,
                ttp.ttp_ten AS DIA_PHUONG_QUYET_DINH,
                TRIM(NVL(CAST(cq.cq_ten AS VARCHAR2(500)), '') ||
                     CASE
                         WHEN ttp.ttp_ten IS NOT NULL THEN ' ' || CAST(ttp.ttp_ten AS VARCHAR2(500))
                         ELSE ''
                     END) AS TOA_AN_QUYET_DINH_DAY_DU
            FROM cb_one cb
            LEFT JOIN qlpn.dm_benh_tats dbt
                   ON dbt.id = cb.benh_tat_id
                  AND NVL(dbt.is_deleted, 0) = 0
            LEFT JOIN qlpn.dm_nguyen_nhan_chets dnnc
                   ON dnnc.id = cb.benh_tat_id
                  AND NVL(dnnc.is_deleted, 0) = 0
            LEFT JOIN qlpn.dm_toa_news cq
                   ON cq.id = cb.co_quan_quyet_dinh_id
            LEFT JOIN qlpn.dm_tinh_thanh_pho ttp
                   ON ttp.id = cb.dia_phuong_quyet_dinh_id
                  AND NVL(ttp.is_deleted, 0) = 0
        ),
        than_nhan_agg AS (
            SELECT
                tn.pham_nhan_id,
                MAX(CASE WHEN REGEXP_LIKE(UPPER(tn.quan_he), 'Bá»|BO') THEN tn.ho_ten_than_nhan END) AS HO_TEN_BO,
                MAX(CASE WHEN REGEXP_LIKE(UPPER(tn.quan_he), 'Bá»|BO') THEN tn.ngay_sinh END) AS NAM_SINH_BO,
                MAX(CASE WHEN REGEXP_LIKE(UPPER(tn.quan_he), 'Bá»|BO') THEN tn.nghe_nghiep END) AS NGHE_NGHIEP_BO,
                MAX(CASE WHEN REGEXP_LIKE(UPPER(tn.quan_he), 'Bá»|BO') THEN tn.noi_o END) AS NOI_O_BO,
                MAX(CASE WHEN REGEXP_LIKE(UPPER(tn.quan_he), 'Máº¸|ME') THEN tn.ho_ten_than_nhan END) AS HO_TEN_ME,
                MAX(CASE WHEN REGEXP_LIKE(UPPER(tn.quan_he), 'Máº¸|ME') THEN tn.ngay_sinh END) AS NAM_SINH_ME,
                MAX(CASE WHEN REGEXP_LIKE(UPPER(tn.quan_he), 'Máº¸|ME') THEN tn.nghe_nghiep END) AS NGHE_NGHIEP_ME,
                MAX(CASE WHEN REGEXP_LIKE(UPPER(tn.quan_he), 'Máº¸|ME') THEN tn.noi_o END) AS NOI_O_ME,
                MAX(CASE WHEN REGEXP_LIKE(UPPER(tn.quan_he), 'Vá»¢|VO|CHá»’NG|CHONG') THEN tn.ho_ten_than_nhan END) AS HO_TEN_VO_CHONG,
                MAX(CASE WHEN REGEXP_LIKE(UPPER(tn.quan_he), 'Vá»¢|VO|CHá»’NG|CHONG') THEN tn.ngay_sinh END) AS NAM_SINH_VO_CHONG,
                MAX(CASE WHEN REGEXP_LIKE(UPPER(tn.quan_he), 'Vá»¢|VO|CHá»’NG|CHONG') THEN tn.nghe_nghiep END) AS NGHE_NGHIEP_VO_CHONG,
                MAX(CASE WHEN REGEXP_LIKE(UPPER(tn.quan_he), 'Vá»¢|VO|CHá»’NG|CHONG') THEN tn.noi_o END) AS NOI_O_VO_CHONG,
                LISTAGG(
                    CASE
                        WHEN REGEXP_LIKE(UPPER(tn.quan_he), 'CON') THEN
                            CAST(tn.ho_ten_than_nhan AS VARCHAR2(500)) ||
                            CASE WHEN tn.ngay_sinh IS NOT NULL THEN ' (' || CAST(tn.ngay_sinh AS VARCHAR2(100)) || ')' ELSE '' END
                    END,
                    ', '
                ) WITHIN GROUP (ORDER BY tn.id) AS CAC_CON
            FROM qlpn.vw_than_nhan tn
            WHERE tn.pham_nhan_id IN (SELECT DISTINCT cb0.pham_nhan_id FROM cb_one cb0)
            GROUP BY tn.pham_nhan_id
        ),
        giam_ranked AS (
            SELECT
                cb.id AS cb_id,
                g.id,
                g.pham_nhan_id,
                g.da_giam,
                g.con_lai,
                g.so_quyet_dinh,
                TO_CHAR(CAST(g.ngay_quyet_dinh AS DATE), 'DD/MM/YYYY') AS NGAY_QUYET_DINH,
                TRIM(NVL(CAST(cq.cq_ten AS VARCHAR2(500)), '') ||
                     CASE
                         WHEN ttp.ttp_ten IS NOT NULL THEN ' ' || CAST(ttp.ttp_ten AS VARCHAR2(500))
                         ELSE ''
                     END) AS TOA_AN,
                ROW_NUMBER() OVER (
                    PARTITION BY cb.id
                    ORDER BY g.ngay_quyet_dinh, g.id
                ) AS rn
            FROM cb_one cb
            JOIN qlpn.vw_giam_thoi_hans g
              ON g.pham_nhan_id = cb.pham_nhan_id
             AND NVL(g.is_deleted, 0) = 0
             AND g.muc_giam_id IS NOT NULL
             AND NVL(TO_NCHAR(g.mtg_ma), u'000000') <> u'000000'
             AND g.ngay_quyet_dinh IS NOT NULL
             AND TRUNC(CAST(g.ngay_quyet_dinh AS DATE)) < TRUNC(CAST(cb.ngay_quyet_dinh AS DATE))
            LEFT JOIN qlpn.dm_toa_news cq
                   ON cq.id = g.toa_quyet_dinh_id
            LEFT JOIN qlpn.dm_tinh_thanh_pho ttp
                   ON ttp.id = g.dia_phuong_id
                  AND NVL(ttp.is_deleted, 0) = 0
        ),
        giam_agg AS (
            SELECT
                cb_id,
                COUNT(*) AS SO_LAN_GIAM,
                MAX(con_lai) KEEP (DENSE_RANK LAST ORDER BY rn) AS THOI_HAN_TU_CON_LAI,
                LISTAGG(
                    u'- L\1ea7n ' || TO_NCHAR(rn) ||
                    u': gi\1ea3m ' || NVL(TO_NCHAR(da_giam), u'') ||
                    u' theo Quy\1ebft \0111\1ecbnh s\1ed1 ' || NVL(TO_NCHAR(so_quyet_dinh), u'') ||
                    u' ng\00e0y ' || NVL(TO_NCHAR(ngay_quyet_dinh), u'') ||
                    u'  c\1ee7a TAND ' || NVL(TO_NCHAR(toa_an), u''),
                    NCHR(10)
                ) WITHIN GROUP (ORDER BY rn) AS CAC_LAN_GIAM
            FROM giam_ranked
            GROUP BY cb_id
        ),
        tien_an_toi_danh AS (
            SELECT
                src.pnta_id,
                TO_NUMBER(TRIM(REGEXP_SUBSTR(src.csv, '[^,]+', 1, LEVEL))) AS toi_danh_id
            FROM (
                SELECT
                    ta.id AS pnta_id,
                    REPLACE(REPLACE(TRIM(ta.pnta_toi_danh_id), '[', ''), ']', '') AS csv
                FROM qlpn.pn_tien_an ta
                WHERE NVL(ta.is_deleted, 0) = 0
                  AND ta.pnta_lai_lich_id IN (SELECT DISTINCT cb0.pham_nhan_id FROM cb_one cb0)
                  AND ta.pnta_toi_danh_id IS NOT NULL
                  AND TRIM(ta.pnta_toi_danh_id) IS NOT NULL
            ) src
            WHERE src.csv IS NOT NULL
              AND REGEXP_LIKE(TRIM(src.csv), '[0-9]')
            CONNECT BY LEVEL <= REGEXP_COUNT(src.csv, ',') + 1
              AND PRIOR src.pnta_id = src.pnta_id
              AND PRIOR SYS_GUID() IS NOT NULL
              AND REGEXP_SUBSTR(src.csv, '[^,]+', 1, LEVEL) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(src.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
        ),
        tien_an_chi_tiet AS (
            SELECT
                ta.pnta_lai_lich_id AS pham_nhan_id,
                LISTAGG(
                    TO_NCHAR(
                        u'N?m x?: ' || NVL(TO_NCHAR(ta.pnta_nam_xu), u'Không rõ')
                        || u'; Tòa x?: ' || NVL(TO_NCHAR(ta.toa_xu), u'Không rõ')
                        || u'; ??a ph??ng: ' || NVL(TO_NCHAR(ta.dia_phuong), u'Không rõ')
                        || u'; T?i danh: ' || NVL(TO_NCHAR(ta.toi_danh), u'Không rõ')
                        || u'; M?c án: ' || NVL(TO_NCHAR(ta.muc_an), u'Không rõ')
                    ),
                    NCHR(10)
                ) WITHIN GROUP (ORDER BY NVL(ta.pnta_nam_xu, 0), ta.id) AS TIEN_AN
            FROM (
                SELECT
                    pta.id,
                    pta.pnta_lai_lich_id,
                    pta.pnta_nam_xu,
                    dcq.cq_ten AS toa_xu,
                    dttp.ttp_ten AS dia_phuong,
                    dmtg.mtg_title AS muc_an,
                    LISTAGG(CAST(dtd.td_ten AS NVARCHAR2(500)), ', ')
                        WITHIN GROUP (ORDER BY dtd.td_ten) AS toi_danh
                FROM qlpn.pn_tien_an pta
                LEFT JOIN qlpn.dm_co_quans dcq
                       ON dcq.id = pta.pnta_toa_xu_id
                      AND NVL(dcq.is_deleted, 0) = 0
                LEFT JOIN qlpn.dm_tinh_thanh_pho dttp
                       ON dttp.id = pta.pnta_dia_phuong_id
                      AND NVL(dttp.is_deleted, 0) = 0
                LEFT JOIN qlpn.dm_ma_thoi_gians dmtg
                       ON dmtg.id = pta.pnta_muc_an_id
                      AND NVL(dmtg.is_deleted, 0) = 0
                LEFT JOIN tien_an_toi_danh tatd
                       ON tatd.pnta_id = pta.id
                LEFT JOIN qlpn.dm_toi_danhs dtd
                       ON dtd.id = tatd.toi_danh_id
                      AND NVL(dtd.is_deleted, 0) = 0
                WHERE NVL(pta.is_deleted, 0) = 0
                  AND pta.pnta_lai_lich_id IN (SELECT DISTINCT cb0.pham_nhan_id FROM cb_one cb0)
                GROUP BY
                    pta.id,
                    pta.pnta_lai_lich_id,
                    pta.pnta_nam_xu,
                    dcq.cq_ten,
                    dttp.ttp_ten,
                    dmtg.mtg_title
            ) ta
            GROUP BY ta.pnta_lai_lich_id
        ),
        tien_su_chi_tiet AS (
            SELECT
                ts.ts_pn_lai_lich_id AS pham_nhan_id,
                LISTAGG(
                    TO_NCHAR(
                        u'N?m x?: ' || NVL(TO_NCHAR(TO_CHAR(CAST(ts.ts_thoi_gian AS DATE), 'YYYY')), u'Không rõ')
                        || u'; Hành vi vi ph?m: ' || NVL(TO_NCHAR(ts.ts_hanh_vi_vi_pham), u'Không rõ')
                        || u'; Hình th?c x? lý: ' || NVL(TO_NCHAR(ts.ts_hinh_thuc_xu_ly), u'Không rõ')
                    ),
                    NCHR(10)
                ) WITHIN GROUP (ORDER BY ts.ts_thoi_gian, ts.id) AS TIEN_SU
            FROM qlpn.pn_tien_sus ts
            WHERE NVL(ts.is_deleted, 0) = 0
              AND ts.ts_pn_lai_lich_id IN (SELECT DISTINCT cb0.pham_nhan_id FROM cb_one cb0)
            GROUP BY ts.ts_pn_lai_lich_id
        ),
        tron_agg AS (
            SELECT
                tt.pham_nhan_id,
                SUM(
                    CASE
                        WHEN tt.ngay_tron IS NOT NULL THEN
                            GREATEST(
                                TRUNC(NVL(CAST(tt.ngay_bat_lai AS DATE), SYSDATE)) - TRUNC(CAST(tt.ngay_tron AS DATE)),
                                0
                            )
                        ELSE 0
                    END
                ) AS TONG_SO_NGAY_TRON
            FROM qlpn.tron_trais tt
            WHERE NVL(tt.is_deleted, 0) = 0
              AND tt.pham_nhan_id IN (SELECT DISTINCT cb0.pham_nhan_id FROM cb_one cb0)
            GROUP BY tt.pham_nhan_id
        ),
        tdc_agg AS (
            SELECT
                tdc.pham_nhan_id,
                SUM(
                    CASE
                        WHEN tdc.ngay_tdc IS NOT NULL THEN
                            GREATEST(
                                TRUNC(NVL(CAST(tdc.ngay_lai AS DATE), SYSDATE)) - TRUNC(CAST(tdc.ngay_tdc AS DATE)),
                                0
                            )
                        ELSE 0
                    END
                ) AS TONG_SO_NGAY_TDC
            FROM qlpn.tam_dinh_chis tdc
            WHERE NVL(tdc.is_deleted, 0) = 0
              AND tdc.pham_nhan_id IN (SELECT DISTINCT cb0.pham_nhan_id FROM cb_one cb0)
            GROUP BY tdc.pham_nhan_id
        ),
        xl_recent AS (
            SELECT x.*
            FROM qlpn.xep_loais x
            WHERE NVL(x.is_deleted, 0) = 0
              AND x.pham_nhan_id IN (SELECT DISTINCT cb0.pham_nhan_id FROM cb_one cb0)
        ),
        xl_ranked AS (
            SELECT
                xr.pham_nhan_id,
                ROW_NUMBER() OVER (PARTITION BY xr.pham_nhan_id ORDER BY xr.xep_loai_nam, xr.id) AS rn,
                xr.xep_loai_nam,
                q1.xlct_ten AS QUY_I,
                q2.xlct_ten AS QUY_II,
                q3.xlct_ten AS QUY_III,
                q4.xlct_ten AS QUY_IV
            FROM xl_recent xr
            LEFT JOIN qlpn.dm_xep_loai_cai_taos q1
                   ON q1.id = xr.xep_loai_quy_i
                  AND NVL(q1.is_deleted, 0) = 0
            LEFT JOIN qlpn.dm_xep_loai_cai_taos q2
                   ON q2.id = xr.xep_loai_quy_ii
                  AND NVL(q2.is_deleted, 0) = 0
            LEFT JOIN qlpn.dm_xep_loai_cai_taos q3
                   ON q3.id = xr.xep_loai_quy_iii
                  AND NVL(q3.is_deleted, 0) = 0
            LEFT JOIN qlpn.dm_xep_loai_cai_taos q4
                   ON q4.id = xr.xep_loai_quy_iv
                  AND NVL(q4.is_deleted, 0) = 0
        ),
        xl_agg_fmt AS (
            SELECT
                pham_nhan_id,
                LISTAGG(
                    TO_NCHAR(
                        u'+N\0103m ' || NVL(TO_NCHAR(xep_loai_nam), u'')
                        || u'....................: Qu\00fd 1 ' || NVL(TO_NCHAR(QUY_I), u'')
                        || u'....................; Qu\00fd 2 ' || NVL(TO_NCHAR(QUY_II), u'')
                        || u'....................; Qu\00fd 3 ' || NVL(TO_NCHAR(QUY_III), u'')
                        || u'....................; Qu\00fd 4 ' || NVL(TO_NCHAR(QUY_IV), u'')
                        || u'....................;'
                    ),
                    NCHR(10)
                ) WITHIN GROUP (ORDER BY rn) AS THONG_TIN_XEP_LOAI
            FROM xl_ranked
            GROUP BY pham_nhan_id
        )
        SELECT
            v.ho_ten AS HO_TEN,
            v.gioi_tinh AS GIOI_TINH,
            v.ngay_sinh AS NGAY_SINH,
            v.ten_khac AS HO_TEN_KHAC,
            v.nguyen_quan AS QUE_QUAN,
            NVL(v.noi_thuong_tru_day_du, v.dia_chi_thuong_tru) AS NOI_THUONG_TRU,
            NVL(v.cccd, v.ho_chieu) AS SO_CCCD_CC_HO_CHIEU,
            TO_CHAR(ngay_cap_cccd, 'DD/MM/YYYY') AS NGAY_CAP,
            noi_cap_cccd AS NOI_CAP,
            v.dan_toc AS DAN_TOC,
            v.quoc_tich AS QUOC_TICH,
            v.nghe_nghiep AS NGHE_NGHIEP_TRUOC_KHI_BI_BAT,
            v.toi_danh AS TOI_DANH,
            TO_CHAR(v.ngay_bat_an_phat, 'DD/MM/YYYY') AS NGAY_BAT,
            v.an_phat AS AN_PHAT,
            v.thoi_gian_tam_giam AS TRU_TAM_GIAM,
            v.so_ban_an AS SO_BAN_AN,
            TO_CHAR(v.ngay_ban_an, 'DD/MM/YYYY') AS NGAY_BAN_AN,
            v.toa_xu_ten AS TOA_XU,
            v.toa_xu_dia_phuong AS DIA_PHUONG_XU,
            v.so_qd_tha AS SO_QD_THA,
            TO_CHAR(v.ngay_qd_tha, 'DD/MM/YYYY') AS NGAY_QD_THA,
            v.co_quan_qd_tha AS TOA_QD_THA,
            v.toa_qd_tha_dia_phuong AS DIA_PHUONG_QD_THA,
--            v.trai_giam AS DEN_CHAP_HANH_AN_TAI,
            TO_CHAR(v.ngay_den_trai, 'DD/MM/YYYY') AS NGAY_DEN_CHAP_HANH_AN,
--            TO_CHAR(cb.ngay_quyet_dinh, 'DD/MM/YYYY') AS NGAY_TINH_THOI_GIAN_DA_CHAP_HANH,
            NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(cb.pham_nhan_id, CAST(cb.ngay_quyet_dinh AS DATE)), '') AS THOI_GIAN_DA_CHAP_HANH,
            QLPN.FN_FORMAT_YMD(
                TRUNC(NVL(tr.TONG_SO_NGAY_TRON, 0) / 365),
                TRUNC(MOD(NVL(tr.TONG_SO_NGAY_TRON, 0), 365) / 30),
                MOD(MOD(NVL(tr.TONG_SO_NGAY_TRON, 0), 365), 30)
            ) AS THOI_GIAN_TRON,
            QLPN.FN_FORMAT_YMD(
                TRUNC(NVL(td.TONG_SO_NGAY_TDC, 0) / 365),
                TRUNC(MOD(NVL(td.TONG_SO_NGAY_TDC, 0), 365) / 30),
                MOD(MOD(NVL(td.TONG_SO_NGAY_TDC, 0), 365), 30)
            ) AS THOI_GIAN_TAM_DINH_CHI,
            TO_NCHAR(NVL(QLPN.PKG_TINH_AN.FN_TINH_SO_LAN_GIAM_AN_TINH_DEN_NGAY(cb.pham_nhan_id, CAST(cb.ngay_quyet_dinh AS DATE)), 0)) AS SO_LAN_GIAM_THOI_HAN_CHAP_HANH_AN,
            NVL(QLPN.PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM_TINH_DEN_NGAY(cb.pham_nhan_id, CAST(cb.ngay_quyet_dinh AS DATE)), u'Kh\00f4ng') AS TONG_THOI_GIAN_DA_GIAM,
            CASE
                WHEN NVL(QLPN.PKG_TINH_AN.FN_TINH_SO_LAN_GIAM_AN_TINH_DEN_NGAY(cb.pham_nhan_id, CAST(cb.ngay_quyet_dinh AS DATE)), 0) > 0
                THEN TO_NCHAR(TRIM(
                TO_NCHAR(u'?ã ???c gi?m th?i h?n ch?p hành hình ph?t tù: ')
                || TO_NCHAR(NVL(QLPN.PKG_TINH_AN.FN_TINH_SO_LAN_GIAM_AN_TINH_DEN_NGAY(cb.pham_nhan_id, CAST(cb.ngay_quyet_dinh AS DATE)), 0))
                || u' l?n = '
                || TO_NCHAR(NVL(QLPN.PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM_TINH_DEN_NGAY(cb.pham_nhan_id, CAST(cb.ngay_quyet_dinh AS DATE)), u'Không'))
                || u';'
                || CASE
                       WHEN g.CAC_LAN_GIAM IS NOT NULL AND TRIM(g.CAC_LAN_GIAM) IS NOT NULL
                       THEN NCHR(10) || TO_NCHAR(g.CAC_LAN_GIAM)
                       ELSE u''
                   END
            ))
                ELSE NULL
            END AS THONG_TIN_GIAM_THOI_HAN,
            g.THOI_HAN_TU_CON_LAI AS THOI_HAN_TU_CON_LAI,
            NVL(QLPN.FN_GET_THONG_TIN_HPBS_PT(v.pham_nhan_id), 'KhÃ´ng') AS HINH_PHAT_BO_SUNG,
            CAST(NULL AS NVARCHAR2(4000)) AS HINH_PHAT_BO_SUNG_KHAC,
            NVL(ta.TIEN_AN, TO_NCHAR(v.so_tien_an)) AS TIEN_AN,
            NVL(ts.TIEN_SU, TO_NCHAR(v.so_tien_su)) AS TIEN_SU,
            v.nhan_than AS NHAN_THAN,
            v.tinh_trang_suc_khoe AS TINH_TRANG_SUC_KHOE_HIEN_NAY,
--            v.tha_ghi_chu_dac_biet AS TINH_TIET_DAC_BIET,
            NVL(v.tom_tat_hanh_vi, v.chi_tiet_hanh_vi) AS TOM_TAT_HANH_VI_PHAM_TOI,
            tn.HO_TEN_BO AS HO_TEN_BO,
            tn.NAM_SINH_BO AS NAM_SINH_BO,
            tn.NGHE_NGHIEP_BO AS NGHE_NGHIEP_BO,
            tn.NOI_O_BO AS CHO_O_BO,
            tn.HO_TEN_ME AS HO_TEN_ME,
            tn.NAM_SINH_ME AS NAM_SINH_ME,
            tn.NGHE_NGHIEP_ME AS NGHE_NGHIEP_ME,
            tn.NOI_O_ME AS CHO_O_ME,
            tn.HO_TEN_VO_CHONG AS HO_TEN_VO_CHONG,
            tn.NAM_SINH_VO_CHONG AS NAM_SINH_VO_CHONG,
            tn.NGHE_NGHIEP_VO_CHONG AS NGHE_NGHIEP_VO_CHONG,
            tn.NOI_O_VO_CHONG AS CHO_O_VO_CHONG,
            tn.CAC_CON AS CAC_CON,
            xlf.THONG_TIN_XEP_LOAI AS THONG_TIN_XEP_LOAI
        FROM cb_one cb
        INNER JOIN vw_one v
                ON v.pham_nhan_id = cb.pham_nhan_id
        LEFT JOIN cb_info ci
               ON ci.cb_id = cb.id
        LEFT JOIN than_nhan_agg tn
               ON tn.pham_nhan_id = cb.pham_nhan_id
        LEFT JOIN giam_agg g
               ON g.cb_id = cb.id
        LEFT JOIN tien_an_chi_tiet ta
               ON ta.pham_nhan_id = cb.pham_nhan_id
        LEFT JOIN tien_su_chi_tiet ts
               ON ts.pham_nhan_id = cb.pham_nhan_id
        LEFT JOIN tron_agg tr
               ON tr.pham_nhan_id = cb.pham_nhan_id
        LEFT JOIN tdc_agg td
               ON td.pham_nhan_id = cb.pham_nhan_id
        LEFT JOIN xl_agg_fmt xlf
               ON xlf.pham_nhan_id = cb.pham_nhan_id;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_CHUA_BENH_BAT_BUOC_PT99: ' || SQLERRM);
END SP_GET_CHUA_BENH_BAT_BUOC_PT99;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DAC_XA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DAC_XA" (
    p_LAI_LICH_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        pdx.PNLAI_LICH_ID,
        TO_CHAR(pdx.DX_NGAY_XET, 'DD/MM/YYYY')   AS "NgayXet",
        TO_CHAR(pdx.DX_NGAY_THA, 'DD/MM/YYYY')   AS "NgayTha",
        TO_CHAR(pdx.DX_NGAY_TRINH_DIEN, 'DD/MM/YYYY')   AS "NgayTrinhDien",
 		CASE
        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
          OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
        THEN TRIM(
            NVL(NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u''), u'')
            || CASE
                WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                            THEN u', ' || dxp_thuong_tru.XP_TEN
                        ELSE dxp_thuong_tru.XP_TEN
                    END
                ELSE u''
               END
            || CASE
                WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                            THEN u', ' || dttp_thuong_tru.TTP_TEN
                        ELSE dttp_thuong_tru.TTP_TEN
                    END
                ELSE u''
               END
        )
        ELSE NULL
    	END AS "NoiVe"
    FROM PN_DAC_XAS pdx
    JOIN PN_LAI_LICHS ll
    ON pdx.PNLAI_LICH_ID = ll.ID 
   	LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru 
    ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID 
    AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
	LEFT JOIN DM_XA_PHUONG dxp_thuong_tru 
	    ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID 
	    AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    WHERE pdx.PNLAI_LICH_ID = p_LAI_LICH_ID;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_DAC_XA;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DANH_SACH_DONG_1
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DANH_SACH_DONG_1" (
    Skipcount        IN NUMBER DEFAULT 0,
    MaxResultCount   IN NUMBER DEFAULT 20
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH pn_src AS (
        SELECT
            v.PHAM_NHAN_ID,
            NVL(CAST(v.SO_HO_SO AS NVARCHAR2(2000)), CAST(pl.LL_SO_HO_SO_LAN_DAU AS NVARCHAR2(2000))) AS ho_so_lan_dau,
            v.HO_TEN,
            v.HO_TEN_ORDER,
            v.GIOI_TINH,
            CASE
                WHEN v.NGAY_SINH IS NOT NULL
                     AND REGEXP_LIKE(TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
                THEN CAST(TO_CHAR(TO_DATE(TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'), 'DD/MM/YYYY') AS NVARCHAR2(20))
                WHEN v.NAM_SINH IS NOT NULL AND v.NAM_SINH > 0
                THEN CAST(TO_CHAR(v.NAM_SINH) AS NVARCHAR2(20))
                WHEN v.NGAY_SINH IS NOT NULL
                THEN CAST(TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))) AS NVARCHAR2(100))
                ELSE NULL
            END AS ngay_sinh,
            v.DAN_TOC AS dan_toc,
            v.QUOC_TICH AS quoc_tich,
            NVL(CAST(v.NOI_THUONG_TRU_DAY_DU AS NVARCHAR2(2000)), CAST(v.DIA_CHI_THUONG_TRU AS NVARCHAR2(2000))) AS noi_dktt,
            NVL(CAST(v.TOI_DANH AS NVARCHAR2(2000)), u'') AS toi_danh,
            pl.LL_SO_TIEN_AN AS so_tien_an,
            CAST(TO_CHAR(v.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NVARCHAR2(20)) AS ngay_bat,
            NVL(CAST(v.AN_PHAT AS NVARCHAR2(2000)), u'') AS an_phat,
            CAST(TO_CHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NVARCHAR2(20)) AS ngay_den_trai,
            CAST(TO_CHAR(v.NGAY_HET_AN, 'DD/MM/YYYY') AS NVARCHAR2(20)) AS ngay_het_han,
            TRIM(
                NVL(CAST(v.PHAN_DOI AS NVARCHAR2(500)), u'')
                || CASE
                    WHEN NULLIF(TRIM(CAST(v.PHAN_TRAI AS NVARCHAR2(500))), u'') IS NOT NULL
                    THEN u', ' || TRIM(CAST(v.PHAN_TRAI AS NVARCHAR2(500)))
                    ELSE u''
                   END
            ) AS phan_doi,
            ROW_NUMBER() OVER (
                PARTITION BY v.PHAM_NHAN_ID
                ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
                         v.CREATION_TIME DESC NULLS LAST
            ) AS rn
        FROM QLPN.VW_PN_LAI_LICH_CHI_TIET v
        INNER JOIN QLPN.PN_LAI_LICHS pl
                ON pl.ID = v.PHAM_NHAN_ID
               AND NVL(pl.IS_DELETED, 0) = 0
        WHERE NVL(v.IS_DELETED, 0) = 0
          AND NVL(pl.LL_SO_TIEN_AN, 0) >= 2
    )
    SELECT *
    FROM (
        SELECT
            ROW_NUMBER() OVER (ORDER BY p.HO_TEN_ORDER, p.PHAM_NHAN_ID) AS STT,
            p.ho_so_lan_dau,
            p.HO_TEN,
            p.gioi_tinh,
            p.ngay_sinh,
            p.dan_toc,
            p.quoc_tich,
            p.noi_dktt,
            p.toi_danh,
            p.so_tien_an,
            p.ngay_bat,
            p.an_phat,
            p.ngay_den_trai,
            p.ngay_het_han,
            p.phan_doi,
            COUNT(*) OVER () AS TOTAL_COUNT
        FROM pn_src p
        WHERE p.rn = 1
    )
    WHERE STT > NVL(Skipcount, 0)
      AND (
            MaxResultCount IS NULL
            OR MaxResultCount <= 0
            OR STT <= NVL(Skipcount, 0) + MaxResultCount
          )
    ORDER BY STT;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_DANH_SACH_DONG_1;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DANH_SACH_DONG_2
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DANH_SACH_DONG_2" (
    SKIPCOUNT IN NUMBER DEFAULT 0,
    MAXRESULTCOUNT IN NUMBER DEFAULT 20
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
        WITH DANH_SACH_DONG AS (SELECT PL.ID,
                                       PL.LL_SO_HO_SO_LAN_DAU                                             AS HO_SO_LAN_DAU,
                                       PL.LL_HO_TEN                                                       AS HO_TEN,
                                       DT.GT_TEN                                                          AS GIOI_TINH,
                                       PL.LL_NGAY_SINH                                                    AS NGAY_SINH,
                                       DD.DT_TEN                                                          AS DAN_TOC,
                                       DQ.QT_TEN                                                          AS QUOC_TICH,
                                       PL.LL_DIA_CHI_THUONG_TRU || ' ' || PX.XP_TEN || ' ' || TTP.TTP_TEN AS NOI_DKTT,
                                       THA.THA_TOI_DANH                                                   AS TOI_DANH,
                                       PL.LL_SO_TIEN_AN                                                   AS SO_TIEN_AN,
                                       TO_NCHAR(THA.THA_NGAY_BAT, 'dd/mm/yyyy')                           AS NGAY_BAT,
                                       THA.THA_AN_PHAT                                                    AS AN_PHAT,
                                       THA.THA_MA_AN_PHAT                                                 AS MA_AN_PHAT,
                                       TO_NCHAR(THA.THA_NGAY_DEN_TRAI, 'dd/mm/yyyy')                      AS NGAY_DEN_TRAI,
                                       TO_NCHAR(THA.THA_NGAY_HET_HAN, 'dd/mm/yyyy')                       AS NGAY_HET_HAN,
                                       PD.PD_TEN || u', ' || PT.PT_TEN                                     AS PHAN_DOI
                                FROM QLPN.PN_LAI_LICHS PL
                                         LEFT JOIN
                                     QLPN.PN_THI_HANH_AN THA -- Loc cac truong hop ban ghi loi
                                     ON THA.THA_PNLAI_LICH_ID = PL.ID AND THA.IS_DELETED = 0
                                         LEFT JOIN
                                     QLPN.DM_GIOI_TINHS DT ON PL.LL_DM_GIOI_TINH_ID = DT.ID AND DT.IS_DELETED = 0
                                         LEFT JOIN
                                     QLPN.DM_DAN_TOCS DD ON PL.LL_DM_DAN_TOC_ID = DD.ID AND DD.IS_DELETED = 0
                                         LEFT JOIN
                                     QLPN.DM_QUOC_TICHS DQ ON PL.LL_DM_QUOC_TICH_ID = DQ.ID AND DQ.IS_DELETED = 0
                                         LEFT JOIN
                                     QLPN.DM_PHAN_DOIS PD ON PL.LL_PHAN_DOI_ID = PD.ID AND PD.IS_DELETED = 0
                                         LEFT JOIN
                                     QLPN.DM_XA_PHUONG PX ON PL.LL_DIA_CHI_THUONG_TRU_WARD = PX.ID AND PX.IS_DELETED = 0
                                         LEFT JOIN
                                     QLPN.DM_TINH_THANH_PHO TTP
                                     ON PL.LL_DIA_CHI_THUONG_TRU_PROVICE = TTP.ID AND TTP.IS_DELETED = 0
                                         LEFT JOIN
                                     QLPN.DM_PHAN_TRAIS PT ON PD.PD_DM_PHAN_TRAI_ID = PT.ID AND PT.IS_DELETED = 0
                                WHERE PL.IS_DELETED = 0),
             THA_FILTERED AS (SELECT /*+ NO_MERGE MATERIALIZE */
                                  PTHA.THA_PNLAI_LICH_ID,
                                  REPLACE(REPLACE(PTHA.THA_TOI_DANH, '[', ''), ']', '') AS TOI_DANH_CLEAN
                              FROM PN_THI_HANH_AN PTHA
                              WHERE PTHA.THA_TOI_DANH IS NOT NULL
                                AND NVL(PTHA.IS_DELETED, 0) = 0),
             NUM_GEN AS (SELECT LEVEL AS N
                         FROM DUAL
                         CONNECT BY LEVEL <= 20),
             SPLIT_TOI_DANH AS (SELECT TF.THA_PNLAI_LICH_ID,
                                       TO_NUMBER(TRIM(
                                               REGEXP_SUBSTR(TF.TOI_DANH_CLEAN, '[^,]+', 1, NG.N)
                                                 )) AS TOI_DANH_ID
                                FROM THA_FILTERED TF
                                         JOIN NUM_GEN NG
                                              ON NG.N <= REGEXP_COUNT(TF.TOI_DANH_CLEAN, ',') + 1
                                WHERE REGEXP_SUBSTR(TF.TOI_DANH_CLEAN, '[^,]+', 1, NG.N) IS NOT NULL),
             TOI_DANH_AGG AS (SELECT S.THA_PNLAI_LICH_ID,
                                     LISTAGG(DISTINCT DTD.TD_TEN, ', ')
                                             WITHIN GROUP (ORDER BY DTD.TD_TEN) AS TOI_DANH
                              FROM SPLIT_TOI_DANH S
                                       LEFT JOIN DM_TOI_DANHS DTD ON DTD.ID = S.TOI_DANH_ID
                              GROUP BY S.THA_PNLAI_LICH_ID)
        SELECT *
        FROM (SELECT ROW_NUMBER() OVER (ORDER BY HO_TEN) AS STT,
                     D.HO_SO_LAN_DAU,
                     D.HO_TEN,
                     D.GIOI_TINH,
                     D.NGAY_SINH,
                     D.DAN_TOC,
                     D.QUOC_TICH,
                     D.NOI_DKTT,
                     TDA.TOI_DANH,
                     D.NGAY_BAT,
                     D.AN_PHAT,
                     D.NGAY_DEN_TRAI,
                     D.NGAY_HET_HAN,
                     D.PHAN_DOI,
                     D.MA_AN_PHAT,
                     D.ID,
                     COUNT(*) OVER ()                    AS TOTAL_COUNT
              FROM DANH_SACH_DONG D
                       LEFT JOIN TOI_DANH_AGG TDA ON D.ID = TDA.THA_PNLAI_LICH_ID
              WHERE TO_NUMBER(SUBSTR(D.MA_AN_PHAT, 1, 2)) > 15)
        WHERE STT > NVL(Skipcount, 0)
          AND (
            MaxResultCount IS NULL
                OR MaxResultCount = 0
                OR STT <= NVL(Skipcount, 0) + MaxResultCount
            )
        ORDER BY STT;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_DANH_SACH_DONG_2;





