                                AND NVL(PTHA.IS_DELETED, 0) = 0),
             NUM_GEN AS (SELECT LEVEL AS N
                         FROM DUAL
                         CONNECT BY LEVEL <= 20),
             SPLIT_TOI_DANH AS (SELECT TF.THA_PNLAI_LICH_ID,
                                       TO_NUMBER(TRIM(
                                               REGEXP_SUBSTR(TF.TOI_DANH_CLEAN, '[^,]+', 1, NG.N)
                                                 )) AS TOI_DANH_ID
                                FROM THA_FILTERED TF
                                         JOIN NUM_GEN NG
                                              ON NG.N <= REGEXP_COUNT(TF.TOI_DANH_CLEAN, ',') + 1
                                WHERE REGEXP_SUBSTR(TF.TOI_DANH_CLEAN, '[^,]+', 1, NG.N) IS NOT NULL),
             TOI_DANH_AGG AS (SELECT S.THA_PNLAI_LICH_ID,
                                     LISTAGG(DISTINCT DTD.TD_TEN, '; ')
                                             WITHIN GROUP (ORDER BY DTD.TD_TEN) AS TOI_DANH,
                                     LISTAGG(DISTINCT DTD.TD_MA, ', ')
                                             WITHIN GROUP (ORDER BY DTD.TD_MA)  AS TOI_DANH_MA_LIST
                              FROM SPLIT_TOI_DANH S
                                       LEFT JOIN DM_TOI_DANHS DTD ON DTD.ID = S.TOI_DANH_ID
                              GROUP BY S.THA_PNLAI_LICH_ID)
        SELECT ROW_NUMBER() OVER (ORDER BY HO_TEN) AS STT,
               D.HO_SO_LAN_DAU,
               D.HO_TEN,
               D.GIOI_TINH,
               D.NGAY_SINH,
               D.DAN_TOC,
               D.QUOC_TICH,
               D.NOI_DKTT,
               TDA.TOI_DANH,
               D.NGAY_BAT,
               D.AN_PHAT,
               D.NGAY_DEN_TRAI,
               D.NGAY_HET_HAN,
               D.PHAN_DOI,
               COUNT(*) OVER ()                    AS TOTAL_COUNT
        FROM DANH_SACH_DONG D
                 LEFT JOIN TOI_DANH_AGG TDA ON D.ID = TDA.THA_PNLAI_LICH_ID
                 LEFT JOIN DM_MUC_ANS MA
                           ON D.MUC_AN_ID = MA.ID
        WHERE TOI_DANH_MA_LIST LIKE u'190.2%'
           OR TOI_DANH_MA_LIST LIKE u'190.3%'
           OR TOI_DANH_MA_LIST LIKE u'191.1b%'
           OR TOI_DANH_MA_LIST LIKE u'191.2e%'
           OR TOI_DANH_MA_LIST LIKE u'191.2k%'
           OR TOI_DANH_MA_LIST LIKE u'191.3b%'
        OFFSET SKIPCOUNT ROWS FETCH NEXT MAXRESULTCOUNT ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_DANH_SACH_DONG_5;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DANH_SACH_DONG_6
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DANH_SACH_DONG_6" (
    SKIPCOUNT IN NUMBER DEFAULT 0,
    MAXRESULTCOUNT IN NUMBER DEFAULT 20
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
        WITH DANH_SACH_DONG AS (SELECT PL.ID,
                                       PL.LL_SO_HO_SO_LAN_DAU                                             AS HO_SO_LAN_DAU,
                                       PL.LL_HO_TEN                                                       AS HO_TEN,
                                       DT.GT_TEN                                                          AS GIOI_TINH,
                                       PL.LL_NGAY_SINH                                                    AS NGAY_SINH,
                                       CASE
                                           WHEN LENGTH(LL_NGAY_SINH) = 10 THEN TO_DATE(LL_NGAY_SINH, 'DD/MM/YYYY')
                                           WHEN LENGTH(LL_NGAY_SINH) = 7
                                               THEN TO_DATE('01/' || LL_NGAY_SINH, 'DD/MM/YYYY')
                                           WHEN LENGTH(LL_NGAY_SINH) = 4
                                               THEN TO_DATE('01/01/' || LL_NGAY_SINH, 'DD/MM/YYYY')
                                           END                                                            AS NGAY_SINH_DATE,
                                       DD.DT_TEN                                                          AS DAN_TOC,
                                       DQ.QT_TEN                                                          AS QUOC_TICH,
                                       PL.LL_DIA_CHI_THUONG_TRU || ' ' || PX.XP_TEN || ' ' || TTP.TTP_TEN AS NOI_DKTT,
                                       THA.THA_TOI_DANH                                                   AS TOI_DANH,
                                       PL.LL_SO_TIEN_AN                                                   AS SO_TIEN_AN,
                                       TO_NCHAR(THA.THA_NGAY_BAT, 'dd/mm/yyyy')                           AS NGAY_BAT,
                                       THA.THA_AN_PHAT                                                    AS AN_PHAT,
                                       THA.THA_MUC_AN_ID                                                  AS MUC_AN_ID,
                                       TO_NCHAR(THA.THA_NGAY_DEN_TRAI, 'dd/mm/yyyy')                      AS NGAY_DEN_TRAI,
                                       TO_NCHAR(THA.THA_NGAY_HET_HAN, 'dd/mm/yyyy')                       AS NGAY_HET_HAN,

                                       PD.PD_TEN || u', ' || PT.PT_TEN                                    AS PHAN_DOI
                                FROM QLPN.PN_LAI_LICHS PL
                                         LEFT JOIN
                                     QLPN.PN_THI_HANH_AN THA
                                     ON THA.THA_PNLAI_LICH_ID = PL.ID AND THA.IS_DELETED = 0
                                         LEFT JOIN
                                     QLPN.DM_GIOI_TINHS DT ON PL.LL_DM_GIOI_TINH_ID = DT.ID
                                         LEFT JOIN
                                     QLPN.DM_DAN_TOCS DD ON PL.LL_DM_DAN_TOC_ID = DD.ID
                                         LEFT JOIN
                                     QLPN.DM_QUOC_TICHS DQ ON PL.LL_DM_QUOC_TICH_ID = DQ.ID
                                         LEFT JOIN
                                     QLPN.DM_PHAN_DOIS PD ON PL.LL_PHAN_DOI_ID = PD.ID
                                         LEFT JOIN
                                     QLPN.DM_XA_PHUONG PX ON PL.LL_DIA_CHI_THUONG_TRU_WARD = PX.ID
                                         LEFT JOIN
                                     QLPN.DM_TINH_THANH_PHO TTP ON PL.LL_DIA_CHI_THUONG_TRU_PROVICE = TTP.ID
                                         LEFT JOIN
                                     QLPN.DM_PHAN_TRAIS PT ON PD.PD_DM_PHAN_TRAI_ID = PT.ID AND PT.IS_DELETED = 0
                                WHERE PL.IS_DELETED = 0),
             CTE_TUOI AS (SELECT ID,
                                 FLOOR(MONTHS_BETWEEN(SYSDATE, NGAY_SINH_DATE) / 12) AS TUOI
                          FROM DANH_SACH_DONG),
             THA_FILTERED AS (SELECT /*+ NO_MERGE MATERIALIZE */
                                  PTHA.THA_PNLAI_LICH_ID,
                                  REPLACE(REPLACE(PTHA.THA_TOI_DANH, '[', ''), ']', '') AS TOI_DANH_CLEAN
                              FROM PN_THI_HANH_AN PTHA
                              WHERE PTHA.THA_TOI_DANH IS NOT NULL
                                AND NVL(PTHA.IS_DELETED, 0) = 0),
             NUM_GEN AS (SELECT LEVEL AS N
                         FROM DUAL
                         CONNECT BY LEVEL <= 20),
             SPLIT_TOI_DANH AS (SELECT TF.THA_PNLAI_LICH_ID,
                                       TO_NUMBER(TRIM(
                                               REGEXP_SUBSTR(TF.TOI_DANH_CLEAN, '[^,]+', 1, NG.N)
                                                 )) AS TOI_DANH_ID
                                FROM THA_FILTERED TF
                                         JOIN NUM_GEN NG
                                              ON NG.N <= REGEXP_COUNT(TF.TOI_DANH_CLEAN, ',') + 1
                                WHERE REGEXP_SUBSTR(TF.TOI_DANH_CLEAN, '[^,]+', 1, NG.N) IS NOT NULL),
             TOI_DANH_AGG AS (SELECT S.THA_PNLAI_LICH_ID,
                                     LISTAGG(DISTINCT DTD.TD_TEN, '; ')
                                             WITHIN GROUP (ORDER BY DTD.TD_TEN) AS TOI_DANH
                              FROM SPLIT_TOI_DANH S
                                       LEFT JOIN DM_TOI_DANHS DTD ON DTD.ID = S.TOI_DANH_ID
                              GROUP BY S.THA_PNLAI_LICH_ID)
        SELECT ROW_NUMBER() OVER (ORDER BY HO_TEN) AS STT,
               D.HO_SO_LAN_DAU,
               D.HO_TEN,
               D.GIOI_TINH,
               D.NGAY_SINH,
               D.DAN_TOC,
               D.QUOC_TICH,
               D.NOI_DKTT,
               TDA.TOI_DANH,
               D.NGAY_BAT,
               D.AN_PHAT,
               D.NGAY_DEN_TRAI,
               D.NGAY_HET_HAN,
               D.PHAN_DOI,
               COUNT(*) OVER ()                    AS TOTAL_COUNT
        FROM DANH_SACH_DONG D
                 LEFT JOIN TOI_DANH_AGG TDA ON D.ID = TDA.THA_PNLAI_LICH_ID
                 LEFT JOIN DM_MUC_ANS MA
                           ON D.MUC_AN_ID = MA.ID
                 LEFT JOIN CTE_TUOI T
                           ON D.ID = T.ID
        WHERE T.TUOI >= 55
        OFFSET SKIPCOUNT ROWS FETCH NEXT MAXRESULTCOUNT ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_DANH_SACH_DONG_6;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DANH_SACH_DU_DIEU_KIEN_GTH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DANH_SACH_DU_DIEU_KIEN_GTH" (
    p_ky_giam_id IN NUMBER,
    p_dk_thoi_gian IN NUMBER DEFAULT NULL,
    p_dk_xlct IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL, -- 1=không có, 2=có
    p_doi_tuong IN NUMBER DEFAULT NULL,
    p_ho_ten IN NVARCHAR2 DEFAULT NULL,
    p_muc_an IN NUMBER DEFAULT NULL,
    p_tinh_trang IN NUMBER DEFAULT NULL,
    p_ma_trai_giam IN VARCHAR2 DEFAULT null,
    p_skip_count IN NUMBER DEFAULT NULL,
    p_max_result_count IN NUMBER DEFAULT NULL,
    p_total_count OUT NUMBER
)
AS
    c1      SYS_REFCURSOR;
    v_skip  NUMBER;
    v_limit NUMBER;
BEGIN
    v_skip := NVL(p_skip_count, 0);
    v_limit := NVL(p_max_result_count, 0);

    -- ==========================================
    -- ??M T?NG
    -- ==========================================
    SELECT COUNT(*)
    INTO p_total_count
    FROM GTH_DU_DIEU_KIEN_CHI_TIETS ct
             JOIN DM_QUOC_TICHS dqt
                  ON ct.DDKCT_QUOC_TICH_ID = dqt.ID
    WHERE ct.IS_DELETED = 0
      AND (p_ma_trai_giam IS NULL or ct.MA_TRAI_GIAM = p_ma_trai_giam)
      AND ct.DDKCT_KY_ID = p_ky_giam_id
      -- Filter ?i?u ki?n th?i gian
      AND (p_dk_thoi_gian IS NULL OR p_dk_thoi_gian = 0
        OR ct.DDKCT_DIEUKIEN_THOI_GIAN_ID = p_dk_thoi_gian)
      -- Filter ?i?u ki?n x?p lo?i
      AND (p_dk_xlct IS NULL OR p_dk_xlct = 0
        OR ct.DDKCT_DIEU_KIEN_XLCT_ID = p_dk_xlct)
      -- Filter phân ??i
      AND (p_phan_doi_id IS NULL
        OR ct.DDKCT_PHAN_DOI_ID = p_phan_doi_id)
      -- Filter qu?c t?ch: 1=VN(ID=87), 2=n??c ngoài
      AND (p_quoc_tich_id IS NULL OR p_quoc_tich_id = 0
        OR (p_quoc_tich_id = 1 AND dqt.QT_MA = '250')
        OR (p_quoc_tich_id = 2 AND (dqt.QT_MA IS NULL OR dqt.QT_MA <> '250')))
      -- Filter ti?n án: 1=không có, 2=có (dùng SO_TIEN_AN)
      AND (p_co_tien_an IS NULL OR p_co_tien_an = 0
        OR (p_co_tien_an = 1 AND NVL(ct.DDKCT_SO_TIEN_AN, 0) = 0)
        OR (p_co_tien_an = 2 AND NVL(ct.DDKCT_SO_TIEN_AN, 0) > 0))
      -- Filter ??i t??ng: 10=ANQG, 20=hình s?
      AND (p_doi_tuong IS NULL
        OR ct.DDKCT_DOI_TUONG_ID = p_doi_tuong)
      -- Filter h? tên
	  AND (
		    p_ho_ten IS NULL OR TRIM(p_ho_ten) = ''
		    OR (
		        FN_REMOVE_DIACRITICS(UPPER(TRIM(p_ho_ten))) = UPPER(TRIM(p_ho_ten))
		        AND FN_REMOVE_DIACRITICS(UPPER(ct.DDKCT_HO_TEN))
		            LIKE '%' || FN_REMOVE_DIACRITICS(UPPER( TRIM(p_ho_ten))) || '%'
		    )
		    OR (
		        FN_REMOVE_DIACRITICS(UPPER(TRIM(p_ho_ten))) <> UPPER(TRIM(p_ho_ten))
		        AND UPPER(ct.DDKCT_HO_TEN) LIKE '%' || UPPER(TRIM(p_ho_ten)) || '%'
		    )
		) 
      -- Filter m?c án
      AND (p_muc_an IS NULL OR p_muc_an = 0
        OR ct.DDKCT_MUC_AN_PHAT_ID = p_muc_an)
      -- Filter tình tr?ng: 1=?ã ??a vào DS, 2=ch?a
      AND (p_tinh_trang IS NULL OR p_tinh_trang = 0
        OR (p_tinh_trang = 1 AND ct.DDKCT_IS_DU_DIEU_KIEN = 1)
        OR (p_tinh_trang = 2 AND ct.DDKCT_IS_DU_DIEU_KIEN = 0));

    -- ==========================================
    -- QUERY CHÍNH
    -- ==========================================
    OPEN c1 FOR
        SELECT ct.DDKCT_PN_ID                                    AS "Pham_Nhan_ID",
               ct.DDKCT_HO_TEN                                   AS "HoTen",
               ct.DDKCT_GIOI_TINH                                AS "GioiTinh",
               SUBSTR(ct.DDKCT_NGAY_SINH, -4)                    AS "NgaySinh",
               ct.DDKCT_NOI_DKTT                                 AS "DCTT",
               NVL(ct.DDKCT_SO_TIEN_AN, 0)                       AS "SoTienAn",
               ct.DDKCT_TOI_DANH                                 AS "ToiDanh",
               ct.DDKCT_NGAY_BAT       AS "NgayBat",
               ct.DDKCT_AN_PHAT                                  AS "AnPhat",
               ct.DDKCT_THOI_GIAN_DA_GIAM                        AS "TongAnGiam",
               ct.DDKCT_THOI_GIAN_DA_CHAP_HANH                   AS "DaChapHanh",
               ct.DDKCT_THOI_GIAN_CON_LAI                        AS "ThoiGianConLai",
               ct.DDKCT_PHAN_DOI                                 AS "PhanDoi",
               ct.DDKCT_NGAY_DEN_TRAI   AS "NgayVao",
               ct.DDKCT_HET_HAN                                  AS "NgayHetHan",
               ct.DDKCT_GHI_CHU AS "KQCT",
               FN_GET_LIET_KE_HPBS_CHI_TIET_GHI_CHU(ct.DDKCT_PN_ID)      AS "HPBS",
               ct.DDKCT_DIEU_KIEN_THOI_GIAN                      AS "DieuKienThoiGian",
               ct.DDKCT_DIEUKIEN_THOI_GIAN_ID                    AS "DieuKienThoiGianId",
               ct.DDKCT_DIEU_KIEN_XLCT                           AS "DieuKienXLCT",
               ct.DDKCT_DIEU_KIEN_XLCT_ID                        AS "DieuKienXLCTId",
               ct.DDKCT_IS_DU_DIEU_KIEN                          AS "IsDuDieuKien",
               ct.DDKCT_IS_NOP_DU                                AS "IsNopDu",
               ct.DDKCT_LL_GHI_CHU                           AS "GHICHU"
        FROM QLPN.GTH_DU_DIEU_KIEN_CHI_TIETS ct
                 LEFT JOIN QLPN.DM_QUOC_TICHS dqt
                      ON ct.DDKCT_QUOC_TICH_ID = dqt.ID
        WHERE ct.IS_DELETED = 0
      AND (p_ma_trai_giam IS NULL or  ct.MA_TRAI_GIAM = p_ma_trai_giam)
          AND ct.DDKCT_KY_ID = p_ky_giam_id
          AND (p_dk_thoi_gian IS NULL OR p_dk_thoi_gian = 0
          	OR (p_dk_thoi_gian = 6 AND (ct.DDKCT_DIEUKIEN_THOI_GIAN_ID BETWEEN 1 AND 4))
            OR (ct.DDKCT_DIEUKIEN_THOI_GIAN_ID = p_dk_thoi_gian))
          AND (p_dk_xlct IS NULL OR p_dk_xlct = 0
          	OR (p_dk_xlct = 5 AND (ct.DDKCT_DIEU_KIEN_XLCT_ID BETWEEN 1 AND 3))
            OR (ct.DDKCT_DIEU_KIEN_XLCT_ID = p_dk_xlct))
          AND (p_phan_doi_id IS NULL
            OR ct.DDKCT_PHAN_DOI_ID = p_phan_doi_id)
          AND (p_quoc_tich_id IS NULL OR p_quoc_tich_id = 0
            OR (p_quoc_tich_id = 1 AND dqt.QT_MA = '250')
            OR (p_quoc_tich_id = 2 AND (dqt.QT_MA IS NULL OR dqt.QT_MA <> '250')))
          AND (p_co_tien_an IS NULL OR p_co_tien_an = 0
            OR (p_co_tien_an = 1 AND NVL(ct.DDKCT_SO_TIEN_AN, 0) = 0)
            OR (p_co_tien_an = 2 AND NVL(ct.DDKCT_SO_TIEN_AN, 0) > 0))
          AND (p_doi_tuong IS NULL
            OR ct.DDKCT_DOI_TUONG_ID = TO_NUMBER(p_doi_tuong) )
		  AND (
		    p_ho_ten IS NULL 
		    OR TRIM(p_ho_ten) = ''
		    OR (
		        -- N?u param truy?n vào KHÔNG có d?u ? tìm theo b? d?u (b?t c? van/Van/V?n/v?n)
		        FN_REMOVE_DIACRITICS(UPPER(TRIM(p_ho_ten))) = UPPER(TRIM(p_ho_ten))
		        AND FN_REMOVE_DIACRITICS(UPPER(ct.DDKCT_HO_TEN)) 
		            LIKE '%' || FN_REMOVE_DIACRITICS(UPPER(TRIM(p_ho_ten))) || '%'
		    )
		    OR (
		        -- N?u param truy?n vào CÓ d?u ? tìm chính xác có d?u
		        FN_REMOVE_DIACRITICS(UPPER(TRIM(p_ho_ten))) <> UPPER(TRIM(p_ho_ten))
		        AND UPPER(ct.DDKCT_HO_TEN) LIKE '%' || UPPER(TRIM(p_ho_ten)) || '%'
		    )
			)
          AND (p_muc_an IS NULL OR p_muc_an = 0
            OR ct.DDKCT_MUC_AN_PHAT_ID = p_muc_an)
          AND (p_tinh_trang IS NULL OR p_tinh_trang = 0
            OR (p_tinh_trang = 1 AND ct.DDKCT_IS_DU_DIEU_KIEN = 1)
            OR (p_tinh_trang = 2 AND ct.DDKCT_IS_DU_DIEU_KIEN = 0))
		  ORDER BY 
			    -- L?y t? cu?i cùng (tên) ?? sort
			    FN_REMOVE_DIACRITICS(REGEXP_SUBSTR(UPPER(ct.DDKCT_HO_TEN), '\S+$')),
			    -- Sau ?ó sort toàn b? h? tên
			    FN_REMOVE_DIACRITICS(UPPER(ct.DDKCT_HO_TEN))
        OFFSET v_skip ROWS FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        p_total_count := 0;
        DBMS_OUTPUT.PUT_LINE('[L?I] ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
END SP_GET_DANH_SACH_DU_DIEU_KIEN_GTH;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DANH_SACH_PN_KY_GTH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DANH_SACH_PN_KY_GTH" (
    p_ky_id                 IN NUMBER  DEFAULT NULL,
    p_phan_doi_id           IN NUMBER  DEFAULT NULL,
    p_doi_tuong_id          IN NUMBER  DEFAULT NULL,
    p_quoc_tich_id          IN NUMBER  DEFAULT NULL,
    p_tinh_trang_id         IN NUMBER  DEFAULT NULL,
    p_muc_trai_de_nghi_id   IN NUMBER  DEFAULT NULL,
    p_muc_cap_tren_duyet_id IN NUMBER  DEFAULT NULL,
    p_muc_toa_id            IN NUMBER  DEFAULT NULL,
    p_ma_trai_giam          IN VARCHAR2 DEFAULT NULL,
    p_skipcount             IN NUMBER  DEFAULT 0,
    p_maxresultcount        IN NUMBER  DEFAULT NULL
)
AS 
    v_refcursor SYS_REFCURSOR;
BEGIN
    OPEN v_refcursor FOR
        SELECT *
        FROM (
            SELECT 
                gddkct.DDKCT_PN_ID          AS PN_ID,
                gddkct.DDKCT_HO_TEN         AS HO_TEN,
                dqt.QT_TEN                  AS QUOC_TICH,
                gddkct.DDKCT_NGAY_SINH      AS NGAY_SINH,
                gddkct.DDKCT_TOI_DANH       AS TOI_DANH,
                gddkct.DDKCT_NOI_DKTT       AS DKTT,
                gddkct.DDKCT_SO_TIEN_AN     AS SO_TIEN_AN,
                gddkct.DDKCT_AN_PHAT        AS AN_PHAT,
                dttpn.TTPN_TEN              AS TINH_TRANG,
                gddkct.DDKCT_PHAN_DOI       AS PHAN_DOI,
                dmtg.MTG_TITLE              AS MUC_GIAM_TRAI_DE_NGHI,
                dmtg1.MTG_TITLE             AS MUC_GIAM_CAP_TREN_DUYET,
                dmtg2.MTG_TITLE             AS MUC_GIAM_TOA,
                gddkct.DDKCT_NGAY_HET_HAN_SAU_GIAM AS NGAY_HET_HAN,
                ROW_NUMBER() OVER (ORDER BY gddkct.DDKCT_PN_ID) AS RN
            FROM GTH_DU_DIEU_KIEN_CHI_TIETS gddkct
            LEFT JOIN GTH_KY_GIAM_THOI_HANS gkgth 
                ON gddkct.DDKCT_KY_ID = gkgth.ID
            LEFT JOIN GIAM_THOI_HANS gth 
                ON gddkct.DDKCT_PN_ID = gth.PHAM_NHAN_ID 
                AND gkgth.KGTH_NGAY_XET_GIAM = gth.NGAY_XET
            LEFT JOIN DM_MA_THOI_GIANS dmtg 
                ON gth.MUC_DE_NGHI_ID = dmtg.ID
            LEFT JOIN DM_MA_THOI_GIANS dmtg1 
                ON gth.CAP_TREN_DUYET_ID = dmtg1.ID
            LEFT JOIN DM_MA_THOI_GIANS dmtg2 
                ON gth.MUC_GIAM_ID = dmtg2.ID
            LEFT JOIN DM_QUOC_TICHS dqt 
                ON gddkct.DDKCT_QUOC_TICH_ID = dqt.ID
            LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dttpn 
                ON gddkct.DDKCT_TINH_TRANG_ID = dttpn.ID
            WHERE gth.MUC_GIAM_ID IS NOT NULL
            AND gddkct.DDKCT_KY_ID = p_ky_id
            AND( p_ma_trai_giam IS NULL OR  gddkct.MA_TRAI_GIAM = p_ma_trai_giam)
            AND (p_phan_doi_id IS NULL OR gddkct.DDKCT_PHAN_DOI_ID = p_phan_doi_id)
            AND (p_doi_tuong_id IS NULL OR 
                (p_doi_tuong_id = 1 AND gddkct.DDKCT_DOI_TUONG_ID = 10)
                OR (p_doi_tuong_id = 2 AND gddkct.DDKCT_DOI_TUONG_ID = 20))
            AND (p_quoc_tich_id IS NULL OR 
                (p_quoc_tich_id = 1 AND dqt.QT_MA = '250'))
            OR (p_quoc_tich_id = 2 AND dqt.QT_MA <> '250')
            AND (p_muc_trai_de_nghi_id IS NULL OR gth.MUC_DE_NGHI_ID = p_muc_trai_de_nghi_id)
            AND (p_muc_cap_tren_duyet_id IS NULL OR gth.CAP_TREN_DUYET_ID = p_muc_cap_tren_duyet_id)
            AND (p_muc_toa_id IS NULL OR gth.MUC_GIAM_ID = p_muc_toa_id)
            AND (p_tinh_trang_id IS NULL 
                OR (p_tinh_trang_id = 1 AND gddkct.DDKCT_DIEU_KIEN_THOI_GIAN IN (1,2,3,4))
                OR (p_tinh_trang_id = 2  AND gddkct.DDKCT_DIEU_KIEN_THOI_GIAN = 5)
                OR (p_tinh_trang_id = 3  AND gth.MUC_DE_NGHI_ID <> gth.CAP_TREN_DUYET_ID)
                OR (p_tinh_trang_id = 4  AND gth.MUC_DE_NGHI_ID = gth.CAP_TREN_DUYET_ID))
        )
        WHERE RN > p_skipcount
        AND (p_maxresultcount IS NULL OR RN <= p_skipcount + p_maxresultcount);

    DBMS_SQL.RETURN_RESULT(v_refcursor);
END SP_GET_DANH_SACH_PN_KY_GTH;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DANH_SACH_THA_CO_DIEU_KIEN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DANH_SACH_THA_CO_DIEU_KIEN" (
    p_dot_tha_id IN NUMBER DEFAULT NULL,
    p_tinh_trang_tha IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_quoc_tich IN NUMBER DEFAULT NULL,
    p_nghien_ma_tuy IN NUMBER DEFAULT NULL,
    p_dia_chi_thuong_tru IN NUMBER DEFAULT NULL,
    p_ma_trai_giam IN VARCHAR2 DEFAULT NULL,
    p_tim_kiem IN NVARCHAR2 DEFAULT NULL,
    p_skip_count IN NUMBER DEFAULT 0,
    p_max_value IN NUMBER DEFAULT 10
    -- tr? trên màn
)
AS
    v_skip NUMBER;
    v_limit NUMBER;
    c1 SYS_REFCURSOR;
BEGIN
    v_skip := NVL(p_skip_count, 0);
    v_limit := NVL(p_max_value, 10);

    /* ========================= QUERY CHÍNH V?I PHÂN TRANG ========================= */
    OPEN c1 FOR
    WITH 
    -- L?c s?m theo ??t th? và tình tr?ng
    tha_filtered AS (
        SELECT
            t.PHAM_NHAN_ID,
            t.NGAY_XET,
            t.NGAY_THA,
            t.SO_QUYET_DINH_THA,
            t.NGAY_QUYET_DINH_THA,
            t.TINH_TRANG_ID,
            t.ID AS THA_CO_DIEU_KIEN_ID,
            ROW_NUMBER() OVER (PARTITION BY t.PHAM_NHAN_ID ORDER BY t.NGAY_XET DESC) AS rn
        FROM THA_CO_DIEU_KIENS t
        LEFT JOIN PN_DOT_THA_CO_DIEU_KIENS dot
            ON TRUNC(t.NGAY_XET) = TRUNC(dot.DTCDK_NGAY_XET)
           AND NVL(dot.IS_DELETED, 0) = 0
        WHERE NVL(t.IS_DELETED, 0) = 0
          AND (p_dot_tha_id IS NULL OR dot.ID = p_dot_tha_id)
          AND (
              p_tinh_trang_tha IS NULL
              OR (p_tinh_trang_tha NOT IN (0, 1) AND t.TINH_TRANG_ID = p_tinh_trang_tha)
          )
    ),
    nghien_mt AS (
        SELECT DISTINCT nmt.NMT_PN_LAI_LICH_ID AS PHAM_NHAN_ID
        FROM PN_NGHIEN_MT nmt
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = nmt.NMT_PN_LAI_LICH_ID AND tf.rn = 1
        WHERE NVL(nmt.IS_DELETED, 0) = 0
    ),
    split_toi_danh AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            TO_NUMBER(REGEXP_SUBSTR(REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''), '[0-9]+', 1, LEVEL)) AS TOI_DANH_ID
        FROM PN_THI_HANH_AN ptha
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID AND tf.rn = 1
        WHERE ptha.THA_TOI_DANH IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
               AND PRIOR ptha.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    toi_danh_agg AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            LISTAGG(DISTINCT dtd.TD_TEN, ', ') WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH
        FROM split_toi_danh s
        LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
        GROUP BY s.THA_PNLAI_LICH_ID
    ),
    toi_danh_chuong AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            dtd.TD_CHUONG
        FROM (
            SELECT THA_PNLAI_LICH_ID, TOI_DANH_ID,
                   ROW_NUMBER() OVER (PARTITION BY THA_PNLAI_LICH_ID ORDER BY TOI_DANH_ID) AS rn
            FROM split_toi_danh
        ) s
        LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
        WHERE s.rn = 1
    ),
    quoc_tich_info AS (
        SELECT
            ll.ID AS PHAM_NHAN_ID,
            qt.QT_MA
        FROM PN_LAI_LICHS ll
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = ll.ID AND tf.rn = 1
        LEFT JOIN DM_QUOC_TICHS qt ON qt.ID = ll.LL_DM_QUOC_TICH_ID AND NVL(qt.IS_DELETED, 0) = 0
        WHERE ll.IS_DELETED = 0
    ),
    latest_tha AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            ptha.THA_NGAY_BAT,
            ptha.THA_AN_PHAT,
            ptha.THA_NGAY_BAN_AN,
            ptha.THA_NGAY_HET_HAN,
            ptha.THA_GHI_CHU_DAC_BIET,
            ROW_NUMBER() OVER (
                PARTITION BY ptha.THA_PNLAI_LICH_ID 
                ORDER BY NVL(ptha.THA_NGAY_BAN_AN, TO_DATE('01-JAN-1900', 'DD-MON-YYYY')) DESC, ptha.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN ptha
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID AND tf.rn = 1
    ),
    latest_phan_loai AS (
        SELECT
            pl1.PHAM_NHAN_ID,
            pl1.LOAI_PHAN_LOAI_ID,
            pl1.NGAY_PHAN_LOAI
        FROM PHAN_LOAIS pl1
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = pl1.PHAM_NHAN_ID AND tf.rn = 1
        INNER JOIN (
            SELECT PHAM_NHAN_ID, MAX(NGAY_PHAN_LOAI) AS MAX_NGAY
            FROM PHAN_LOAIS
            GROUP BY PHAM_NHAN_ID
        ) pl2 ON pl1.PHAM_NHAN_ID = pl2.PHAM_NHAN_ID AND pl1.NGAY_PHAN_LOAI = pl2.MAX_NGAY
    ),
    latest_gth AS (
        SELECT
            gth.PHAM_NHAN_ID,
            gth.MUC_GIAM_ID,
            ROW_NUMBER() OVER (PARTITION BY gth.PHAM_NHAN_ID ORDER BY gth.ID DESC) AS rn
        FROM GIAM_THOI_HANS gth
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = gth.PHAM_NHAN_ID AND tf.rn = 1
    )
    SELECT  
        ll.ID AS pham_nhan_id,
        ll.LL_HO_TEN AS ho_ten,
        EXTRACT(YEAR FROM TO_DATE(ll.LL_NGAY_SINH, 'DD/MM/YYYY')) AS ngay_sinh,
        dgt.GT_TEN AS gioi_tinh,
        ll.LL_DIA_CHI_THUONG_TRU AS dia_chi_thuong_tru,
        dvhc.TTP_TEN AS noi_tha_ve,
        ll.LL_SO_TIEN_AN AS so_tien_an,
        td_agg.TOI_DANH AS toi_danh,
        ptha.THA_NGAY_BAT AS ngay_bat,
        ptha.THA_AN_PHAT AS an_phat,
        dmtg.MTG_TITLE AS muc_giam,
		PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(ll.ID, tf.NGAY_XET) AS da_chap_hanh,
		PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_THANG_NGAY(ll.ID, tf.NGAY_XET) AS con_lai,
        ptha.THA_NGAY_HET_HAN AS ngay_het_han,
        dpd.PD_TEN AS phan_doi,
        dplgg.PLGG_TEN AS phan_loai,
        pl_latest.NGAY_PHAN_LOAI AS ngay_phan_loai,
        ptha.THA_GHI_CHU_DAC_BIET AS ghi_chu_dac_biet,
        tf.NGAY_XET AS ngay_xet,
        tf.NGAY_THA AS ngay_tha,
        tf.SO_QUYET_DINH_THA AS so_quyet_dinh_tha,
        tf.NGAY_QUYET_DINH_THA AS ngay_quyet_dinh_tha,
        tf.TINH_TRANG_ID AS tinh_trang_id,
        tf.THA_CO_DIEU_KIEN_ID AS tha_co_dieu_kien_id
    FROM PN_LAI_LICHS ll
    INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = ll.ID AND tf.rn = 1
    LEFT JOIN DM_TINH_THANH_PHO dvhc ON ll.LL_NOI_THA_VE_CU_TRU_PROVICE = dvhc.ID
    LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN latest_tha ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID AND ptha.rn = 1
    LEFT JOIN DM_PHAN_DOIS dpd ON ll.LL_PHAN_DOI_ID = dpd.ID
    LEFT JOIN latest_phan_loai pl_latest ON ll.ID = pl_latest.PHAM_NHAN_ID
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg ON pl_latest.LOAI_PHAN_LOAI_ID = dplgg.ID
    LEFT JOIN toi_danh_agg td_agg ON ll.ID = td_agg.THA_PNLAI_LICH_ID
    LEFT JOIN latest_gth gth ON ll.ID = gth.PHAM_NHAN_ID AND gth.rn = 1
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
    LEFT JOIN nghien_mt nm ON nm.PHAM_NHAN_ID = ll.ID
    LEFT JOIN toi_danh_chuong tdc ON tdc.THA_PNLAI_LICH_ID = ll.ID
    LEFT JOIN quoc_tich_info qti ON qti.PHAM_NHAN_ID = ll.ID
    WHERE ll.IS_DELETED = 0
      AND (p_ma_trai_giam is null or ll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA =p_ma_trai_giam ))
      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
      AND (p_dia_chi_thuong_tru IS NULL OR dvhc.ID = p_dia_chi_thuong_tru)
      AND (p_doi_tuong_id IS NULL
           OR (p_doi_tuong_id = 1 AND TRIM(NVL(CAST(tdc.TD_CHUONG AS VARCHAR2(10)), '')) = '13')
           OR (p_doi_tuong_id = 2 AND (tdc.TD_CHUONG IS NULL OR TRIM(NVL(CAST(tdc.TD_CHUONG AS VARCHAR2(10)), '')) <> '13')))
      AND (p_quoc_tich IS NULL
           OR (p_quoc_tich = 250 AND TRIM(NVL(CAST(qti.QT_MA AS VARCHAR2(20)), '')) = '250')
           OR (p_quoc_tich = 999 AND (qti.QT_MA IS NULL OR TRIM(NVL(CAST(qti.QT_MA AS VARCHAR2(20)), '')) <> '250')))
      AND (p_nghien_ma_tuy IS NULL
           OR (p_nghien_ma_tuy = 1 AND nm.PHAM_NHAN_ID IS NOT NULL)
           OR (p_nghien_ma_tuy = 0 AND nm.PHAM_NHAN_ID IS NULL))
      AND (p_tim_kiem IS NULL OR TRIM(p_tim_kiem) = ''
           OR UPPER(CAST(NVL(ll.LL_HO_TEN, '') AS VARCHAR2(2000))) LIKE '%' || UPPER(TRIM(p_tim_kiem)) || '%'
           OR UPPER(CAST(NVL(ll.LL_CCCD, '') AS VARCHAR2(200))) LIKE '%' || UPPER(TRIM(p_tim_kiem)) || '%')
    ORDER BY ll.LL_HO_TEN
    OFFSET v_skip ROWS
    FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách th? có ?i?u ki?n: ' || SQLERRM);
END SP_GET_DANH_SACH_THA_CO_DIEU_KIEN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DONG_Y_THA_CO_DK
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DONG_Y_THA_CO_DK" (
--    p_pn_ids     IN NVARCHAR2 DEFAULT NULL,
    p_dot_tha_id IN NUMBER    DEFAULT NULL,
    p_ma_trai_giam IN varchar2 default null
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
	ID_LIST AS (
    SELECT PN_ID 
    FROM QLPN.GTT_PN_IDS
--	    SELECT DISTINCT
--	        TO_NUMBER(
--	            REGEXP_SUBSTR(
--	                REPLACE(REPLACE(TRIM(p_pn_ids), '[', ''), ']', ''),
--	                '[0-9]+', 1, LEVEL
--	            )
--	        ) AS PN_ID
--	    FROM DUAL
--	    WHERE p_pn_ids IS NOT NULL
--	      AND LENGTH(TRIM(p_pn_ids)) > 0
--	    CONNECT BY LEVEL <= REGEXP_COUNT(
--	                    REPLACE(REPLACE(TRIM(p_pn_ids), '[', ''), ']', ''),
--	                    '[0-9]+'
--	                )
--	           AND PRIOR SYS_GUID() IS NOT NULL
	),
    tha_filtered AS (
        SELECT
            t.PHAM_NHAN_ID,
            t.NGAY_XET,
            t.NGAY_THA,
            t.SO_QUYET_DINH_THA,
            t.NGAY_QUYET_DINH_THA,
            t.TINH_TRANG_ID,
            t.QQCT_PHIEU,
            t.DANH_GIA_CAI_TAO_ID,
            t.ID AS THA_CO_DIEU_KIEN_ID,
            ROW_NUMBER() OVER (
                PARTITION BY t.PHAM_NHAN_ID
                ORDER BY t.NGAY_XET DESC
            ) AS rn
        FROM THA_CO_DIEU_KIENS t
        WHERE NVL(t.IS_DELETED, 0) = 0
--          AND t.SO_QUYET_DINH_THA IS NOT NULL
--          AND (p_pn_ids IS NULL OR t.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
          AND (p_dot_tha_id IS NULL OR EXISTS (
                SELECT 1
                FROM PN_DOT_THA_CO_DIEU_KIENS dot
                WHERE TRUNC(dot.DTCDK_NGAY_XET) = TRUNC(t.NGAY_XET)
                  AND dot.ID = p_dot_tha_id
                  AND NVL(dot.IS_DELETED, 0) = 0
          ))
    ),
    split_toi_danh AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            TO_NUMBER(
                REGEXP_SUBSTR(
                    REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
                    '[0-9]+', 1, LEVEL
                )
            ) AS TOI_DANH_ID
        FROM PN_THI_HANH_AN ptha
        INNER JOIN tha_filtered tf
            ON tf.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID AND tf.rn = 1
        WHERE ptha.THA_TOI_DANH IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                       REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
               AND PRIOR ptha.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    toi_danh_agg AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            LISTAGG(DISTINCT dtd.TD_TEN, ', ')
                WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH
        FROM split_toi_danh s
        LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
        GROUP BY s.THA_PNLAI_LICH_ID
    ),
    split_ghi_chu_dac_biet AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            TO_NUMBER(
                REGEXP_SUBSTR(
                    REPLACE(REPLACE(ptha.THA_GHI_CHU_DAC_BIET, '[', ''), ']', ''),
                    '[0-9]+', 1, LEVEL
                )
            ) AS GCDB_ID
        FROM PN_THI_HANH_AN ptha
        INNER JOIN tha_filtered tf
            ON tf.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID AND tf.rn = 1
        WHERE ptha.THA_GHI_CHU_DAC_BIET IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                       REPLACE(REPLACE(ptha.THA_GHI_CHU_DAC_BIET, '[', ''), ']', ''), ',') + 1
               AND PRIOR ptha.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    ghi_chu_dac_biet_agg AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            LISTAGG(DISTINCT dgcdb.GCDB_TEN, ', ')
                WITHIN GROUP (ORDER BY dgcdb.GCDB_TEN) AS GHI_CHU_DAC_BIET
        FROM split_ghi_chu_dac_biet s
        LEFT JOIN DM_GHI_CHU_DAC_BIETS dgcdb ON dgcdb.ID = s.GCDB_ID
        GROUP BY s.THA_PNLAI_LICH_ID
    ),
    latest_tha AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            ptha.THA_NGAY_BAT,
            ptha.THA_AN_PHAT,
            ptha.THA_NGAY_BAN_AN,
            ptha.THA_NGAY_HET_HAN,
            ptha.THA_GHI_CHU_DAC_BIET,
            ptha.THA_NGAY_DEN_TRAI,
            ROW_NUMBER() OVER (
                PARTITION BY ptha.THA_PNLAI_LICH_ID
                ORDER BY NVL(ptha.THA_NGAY_BAN_AN,
                             TO_DATE('01-JAN-1900', 'DD-MON-YYYY')) DESC,
                         ptha.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN ptha
        INNER JOIN tha_filtered tf
            ON tf.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID AND tf.rn = 1
    ),
    latest_phan_loai AS (
        SELECT pl1.PHAM_NHAN_ID, pl1.LOAI_PHAN_LOAI_ID, pl1.NGAY_PHAN_LOAI
        FROM PHAN_LOAIS pl1
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = pl1.PHAM_NHAN_ID AND tf.rn = 1
        INNER JOIN (
            SELECT PHAM_NHAN_ID, MAX(NGAY_PHAN_LOAI) AS MAX_NGAY
            FROM PHAN_LOAIS
            GROUP BY PHAM_NHAN_ID
        ) pl2 ON pl1.PHAM_NHAN_ID = pl2.PHAM_NHAN_ID
             AND pl1.NGAY_PHAN_LOAI = pl2.MAX_NGAY
    ),
    latest_gth AS (
        SELECT
            gth.PHAM_NHAN_ID,
            gth.MUC_GIAM_ID,
            ROW_NUMBER() OVER (
                PARTITION BY gth.PHAM_NHAN_ID ORDER BY gth.ID DESC
            ) AS rn
        FROM GIAM_THOI_HANS gth
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = gth.PHAM_NHAN_ID AND tf.rn = 1
    ),
    da_chap_hanh_data AS (
        SELECT
            tf.PHAM_NHAN_ID,
            QLPN.FN_GET_DA_CHAP_HANH_THEO_NGAY(tf.PHAM_NHAN_ID, tf.NGAY_XET) AS DA_CH_OBJ
        FROM tha_filtered tf
        WHERE tf.rn = 1
    )
    SELECT
        ll.ID                                                       AS pham_nhan_id,
        ll.LL_HO_TEN                                                AS ho_ten,
        SUBSTR(TRIM(ll.LL_NGAY_SINH), -4)                           AS ngay_sinh,
        dgt.GT_TEN                                                  AS gioi_tinh,
        CASE
            WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                             THEN u', ' || dxp_thuong_tru.XP_TEN ELSE dxp_thuong_tru.XP_TEN END
                   ELSE u'' END
                || CASE WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                               OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                             THEN u', ' || dttp_thuong_tru.TTP_TEN ELSE dttp_thuong_tru.TTP_TEN END
                   ELSE u'' END
            )
            ELSE NULL
        END                                                         AS dia_chi_thuong_tru,
        CASE
            WHEN NULLIF(TRIM(ll.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_tha_ve.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_tha_ve.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(ll.LL_NOI_THA_VE_CU_TRU), u''), u'')
                || CASE WHEN NULLIF(TRIM(dxp_tha_ve.XP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(ll.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
                             THEN u', ' || dxp_tha_ve.XP_TEN ELSE dxp_tha_ve.XP_TEN END
                   ELSE u'' END
                || CASE WHEN NULLIF(TRIM(dttp_tha_ve.TTP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(ll.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
                               OR NULLIF(TRIM(dxp_tha_ve.XP_TEN), u'') IS NOT NULL
                             THEN u', ' || dttp_tha_ve.TTP_TEN ELSE dttp_tha_ve.TTP_TEN END
                   ELSE u'' END
            )
            ELSE NULL
        END                                                         AS noi_ve_cu_tru,
        CASE WHEN ll.LL_SO_TIEN_AN IS NULL THEN u'Không'
             ELSE ll.LL_SO_TIEN_AN END                              AS so_tien_an,
        td_agg.TOI_DANH                                             AS toi_danh,
        TO_CHAR(TRUNC(ptha.THA_NGAY_BAT), 'DD-MM-YYYY')            AS ngay_bat,
        TO_CHAR(TRUNC(ptha.THA_NGAY_DEN_TRAI), 'DD-MM-YYYY')       AS ngay_den_chap_hanh,
        ptha.THA_AN_PHAT                                            AS an_phat,
        QLPN.FN_TINH_AN_DA_GIAM_CHI_TIET(ll.ID)                   AS muc_giam,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(ll.ID, tf.NGAY_XET), u'') AS da_chap_hanh,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(ll.ID), u'Không')    AS da_giam_an,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(ll.ID, tf.NGAY_XET), u'') AS con_lai,
        TO_CHAR(TRUNC(ptha.THA_NGAY_HET_HAN), 'DD-MM-YYYY')        AS ngay_het_han,
        dpd.PD_TEN                                                  AS phan_doi,
        dplgg.PLGG_TEN                                              AS phan_loai,
        dxlct.XLCT_TEN                                              AS danh_gia_cai_tao,
        TO_CHAR(TRUNC(pl_latest.NGAY_PHAN_LOAI), 'DD-MM-YYYY')     AS ngay_phan_loai,
        gcdb_agg.GHI_CHU_DAC_BIET                                   AS ghi_chu_dac_biet,
        TO_CHAR(TRUNC(tf.NGAY_XET), 'DD-MM-YYYY')                  AS ngay_xet,
        TO_CHAR(TRUNC(tf.NGAY_THA), 'DD-MM-YYYY')                  AS ngay_tha,
        tf.SO_QUYET_DINH_THA                                        AS so_quyet_dinh_tha,
        TO_CHAR(TRUNC(tf.NGAY_QUYET_DINH_THA), 'DD-MM-YYYY')       AS ngay_quyet_dinh_tha,
        tf.TINH_TRANG_ID                                            AS tinh_trang_id,
        tf.THA_CO_DIEU_KIEN_ID                                      AS tha_co_dieu_kien_id,
        tf.QQCT_PHIEU
    FROM PN_LAI_LICHS ll
    INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = ll.ID AND tf.rn = 1
    LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN latest_tha ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID AND ptha.rn = 1
    LEFT JOIN DM_PHAN_DOIS dpd ON ll.LL_PHAN_DOI_ID = dpd.ID
    LEFT JOIN latest_phan_loai pl_latest ON ll.ID = pl_latest.PHAM_NHAN_ID
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg ON pl_latest.LOAI_PHAN_LOAI_ID = dplgg.ID
    LEFT JOIN toi_danh_agg td_agg ON ll.ID = td_agg.THA_PNLAI_LICH_ID
    LEFT JOIN latest_gth gth ON ll.ID = gth.PHAM_NHAN_ID AND gth.rn = 1
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
    LEFT JOIN da_chap_hanh_data dch ON dch.PHAM_NHAN_ID = ll.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS dxlct ON tf.DANH_GIA_CAI_TAO_ID = dxlct.ID
    LEFT JOIN ghi_chu_dac_biet_agg gcdb_agg ON ll.ID = gcdb_agg.THA_PNLAI_LICH_ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
        ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
       AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
        ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
       AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_THANH_PHO dttp_tha_ve
        ON ll.LL_NOI_THA_VE_CU_TRU_PROVICE = dttp_tha_ve.ID
       AND NVL(dttp_tha_ve.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_tha_ve
        ON ll.LL_NOI_THA_VE_CU_TRU_WARD = dxp_tha_ve.ID
       AND NVL(dxp_tha_ve.IS_DELETED, 0) = 0
    WHERE ll.IS_DELETED = 0
    ORDER BY ll.LL_HO_TEN;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            u'L?i khi l?y danh sách ??ng ý th? có ?i?u ki?n: ' || SQLERRM);
END SP_GET_DONG_Y_THA_CO_DK;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_BD_THOI_HAN_NOP_LUU_HS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_BD_THOI_HAN_NOP_LUU_HS" (
    p_ma_trai_giam           IN NVARCHAR2 DEFAULT NULL,
    p_ngay_ket_thuc_tu_ngay  IN NVARCHAR2 DEFAULT NULL,
    p_ngay_ket_thuc_den_ngay IN NVARCHAR2 DEFAULT NULL,
    p_ngay_den_trai_tu_ngay  IN NVARCHAR2 DEFAULT NULL,
    p_ngay_den_trai_den_ngay IN NVARCHAR2 DEFAULT NULL,
    p_loai_doi_tuong         IN NVARCHAR2 DEFAULT NULL,
    p_ly_do_ket_thuc         IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi               IN NVARCHAR2 DEFAULT NULL,
    p_thoi_han_bao_quan      IN NVARCHAR2 DEFAULT NULL,
    p_skipcount              IN NUMBER    DEFAULT 0,
    p_maxresultcount         IN NUMBER    DEFAULT null
)
AS
    v_ngay_ket_thuc_tu_ngay  TIMESTAMP;
    v_ngay_ket_thuc_den_ngay TIMESTAMP;
    v_ngay_den_trai_tu_ngay  TIMESTAMP;
    v_ngay_den_trai_den_ngay TIMESTAMP;
    v_skip                   NUMBER;
    v_limit                  NUMBER;
    v_filter_het_han         NUMBER;
    v_filter_den_trai        NUMBER;
    v_ma_trai_giam           NVARCHAR2(100);
    v_trai_giam_id           NUMBER;
    v_phan_doi_id            NUMBER;
    c1                       SYS_REFCURSOR;
BEGIN
    v_skip := NVL(p_skipcount, 0);
    v_trai_giam_id := NULL;

    IF p_ma_trai_giam IS NOT NULL or TRIM(p_ma_trai_giam) <> '' THEN
        v_ma_trai_giam := TRIM(p_ma_trai_giam);
        BEGIN
            SELECT dtg.ID
              INTO v_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS dtg
             WHERE dtg.TG_MA = v_ma_trai_giam
               AND NVL(dtg.IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20002,
                    u'M\00e3 tr\1ea1i giam kh\00f4ng h\1ee3p l\1ec7: ' || v_ma_trai_giam
                );
        END;
    END IF;

    v_phan_doi_id :=
        CASE
            WHEN p_phan_doi IS NULL OR TRIM(p_phan_doi) = '' THEN NULL
            ELSE TO_NUMBER(TRIM(p_phan_doi))
        END;

    IF p_ngay_ket_thuc_tu_ngay IS NULL OR TRIM(p_ngay_ket_thuc_tu_ngay) = '' THEN
        v_ngay_ket_thuc_tu_ngay := NULL;
    ELSE
        v_ngay_ket_thuc_tu_ngay := TO_TIMESTAMP(TRIM(p_ngay_ket_thuc_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_ngay_ket_thuc_den_ngay IS NULL OR TRIM(p_ngay_ket_thuc_den_ngay) = '' THEN
        v_ngay_ket_thuc_den_ngay := NULL;
    ELSE
        v_ngay_ket_thuc_den_ngay := TO_TIMESTAMP(TRIM(p_ngay_ket_thuc_den_ngay), 'DD/MM/YYYY') + INTERVAL '1' DAY;
    END IF;

    IF p_ngay_den_trai_tu_ngay IS NULL OR TRIM(p_ngay_den_trai_tu_ngay) = '' THEN
        v_ngay_den_trai_tu_ngay := NULL;
    ELSE
        v_ngay_den_trai_tu_ngay := TO_TIMESTAMP(TRIM(p_ngay_den_trai_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_ngay_den_trai_den_ngay IS NULL OR TRIM(p_ngay_den_trai_den_ngay) = '' THEN
        v_ngay_den_trai_den_ngay := NULL;
    ELSE
        v_ngay_den_trai_den_ngay := TO_TIMESTAMP(TRIM(p_ngay_den_trai_den_ngay), 'DD/MM/YYYY') + INTERVAL '1' DAY;
    END IF;

    v_filter_het_han  := CASE WHEN v_ngay_ket_thuc_tu_ngay IS NOT NULL OR v_ngay_ket_thuc_den_ngay IS NOT NULL THEN 1 ELSE 0 END;
    v_filter_den_trai := CASE WHEN v_ngay_den_trai_tu_ngay IS NOT NULL OR v_ngay_den_trai_den_ngay IS NOT NULL THEN 1 ELSE 0 END;

    v_limit := CASE
        WHEN NVL(p_maxresultcount, 0) <= 0 THEN 999999999
        ELSE p_maxresultcount
    END;

    OPEN c1 FOR
    WITH
    nl_f AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            nl.ID,
            nl.PHAM_NHAN_ID,
            nl.CAN_BO_NOP_LUU,
            nl.CAP_BAC,
            nl.CHUC_VU,
            nl.SO_LUU_TRU,
            nl.NGAY_DANG_KY,
            nl.NGAY_KET_THUC,
            nl.SO_DANG_KY,
            nl.NGAY_NOP_LUU,
            nl.SO_NAM_BAO_QUAN
        FROM QLPN.NOP_LUUS nl
        WHERE nl.IS_DELETED = 0
          AND nl.NGAY_NOP_LUU IS NOT NULL
          AND (
              p_thoi_han_bao_quan IS NULL
              OR EXISTS (
                  SELECT /*+ INDEX(bqhs) */ 1
                  FROM QLPN.DM_LOAI_THOI_GIAN_BAO_QUAN_HO_SO_PHAM_NHANS bqhs
                  WHERE bqhs.ID        = nl.THOI_GIAN_BAO_QUAN
                    AND bqhs.IS_DELETED = 0
                    AND (
                        (p_thoi_han_bao_quan = u'1' AND bqhs.LTGBQHSPN_MA IN ('11','12','13','14','111','112','113'))
                     OR (p_thoi_han_bao_quan = u'2' AND bqhs.LTGBQHSPN_MA IN ('21','22','23','24','121','122','123','124','125'))
                    )
              )
          )
    ),
    rt_f AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            rt.PHAM_NHAN_ID,
            rt.LL_SO_HO_SO_LAN_DAU,
            rt.LL_HO_TEN,
            rt.LL_TEN_KHAC,
            rt.LL_CCCD,
            rt.HO_TEN_ORDER,
            rt.LL_NGAY_SINH,
            rt.LL_DM_GIOI_TINH_ID,
            rt.LL_DIA_CHI_THUONG_TRU,
            rt.LL_DIA_CHI_THUONG_TRU_WARD,
            rt.LL_DIA_CHI_THUONG_TRU_PROVICE,
            rt.LL_PHAN_DOI_ID,
            rt.LL_PHAN_TRAI_ID,
            rt.LL_TRAI_GIAM_ID,
            rt.LL_TINH_TRANG_ID,
            rt.LL_DM_QUOC_TICH_ID,
            rt.LL_CREATION_TIME,
            rt.THA_TOI_DANH,
            rt.THA_TOI_DANH_NAMES,
            rt.THA_AN_PHAT,
            rt.THA_NGAY_BAT,
            rt.THA_NGAY_DEN_TRAI,
            rt.THA_NGAY_HET_HAN,
            rt.THA_SO_BAN_AN,
            rt.THA_NGAY_BAN_AN,
            rt.THA_SO_DANH_BAN,
            rt.THA_TOA_QD_ID,
            rt.THA_CREATION_TIME,
            rt.THA_SO_QD_THA,
            rt.THA_NGAY_QD_THA,
            rt.THA_DIA_PHUONG_CAP_TOA_ID,
            rt.THA_CAP_TOA_ID,
            rt.THA_DIA_PHUONG_TOA_QD_THA_ID,
            TO_NUMBER(
                REGEXP_SUBSTR(
                    NVL(TRIM(CAST(rt.THA_TOI_DANH AS VARCHAR2(4000))), ''),
                    '[0-9]+', 1, 1
                )
            ) AS THA_TOI_DANH_NUM,
            MAX(
                CASE
                    WHEN dtd.IS_DELETED = 0
                     AND TRIM(CAST(dtd.TD_CHUONG AS VARCHAR2(10))) = '13'
                    THEN 1
                    ELSE 0
                END
            ) OVER (PARTITION BY rt.PHAM_NHAN_ID) AS IS_CHUONG_13,
            ROW_NUMBER() OVER (
                PARTITION BY rt.PHAM_NHAN_ID
                ORDER BY
                    NVL(rt.THA_NGAY_HET_HAN, rt.LL_CREATION_TIME) DESC NULLS LAST,
                    rt.LL_CREATION_TIME DESC NULLS LAST,
                    rt.THA_CREATION_TIME DESC NULLS LAST
            ) AS rn_tha
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        LEFT JOIN QLPN.DM_TOI_DANHS dtd
            ON dtd.IS_DELETED = 0
           AND dtd.ID = TO_NUMBER(
                            REGEXP_SUBSTR(
                                NVL(TRIM(CAST(rt.THA_TOI_DANH AS VARCHAR2(4000))), ''),
                                '[0-9]+', 1, 1
                            )
                        )
        WHERE rt.IS_DELETED = 0
          AND rt.THA_TOI_DANH IS NOT NULL
          AND TRIM(CAST(rt.THA_TOI_DANH AS VARCHAR2(4000))) IS NOT NULL
          AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
          AND (v_phan_doi_id  IS NULL OR rt.LL_PHAN_DOI_ID  = v_phan_doi_id)
          AND (
              v_filter_het_han = 0
              OR (
                  rt.THA_NGAY_HET_HAN IS NOT NULL
                  AND (v_ngay_ket_thuc_tu_ngay  IS NULL OR rt.THA_NGAY_HET_HAN >= v_ngay_ket_thuc_tu_ngay)
                  AND (v_ngay_ket_thuc_den_ngay IS NULL OR rt.THA_NGAY_HET_HAN <  v_ngay_ket_thuc_den_ngay)
              )
          )
          AND (
              v_filter_den_trai = 0
              OR (
                  rt.THA_NGAY_DEN_TRAI IS NOT NULL
                  AND (v_ngay_den_trai_tu_ngay  IS NULL OR rt.THA_NGAY_DEN_TRAI >= v_ngay_den_trai_tu_ngay)
                  AND (v_ngay_den_trai_den_ngay IS NULL OR rt.THA_NGAY_DEN_TRAI <  v_ngay_den_trai_den_ngay)
              )
          )
    ),
    ll_nl AS (
        SELECT /*+ MATERIALIZE USE_HASH(rt nl) SWAP_JOIN_INPUTS(nl) */
            nl.ID,
            nl.PHAM_NHAN_ID,
            nl.CAN_BO_NOP_LUU,
            nl.CAP_BAC,
            nl.CHUC_VU,
            nl.SO_LUU_TRU,
            nl.NGAY_DANG_KY,
            nl.NGAY_KET_THUC,
            nl.SO_DANG_KY,
            nl.NGAY_NOP_LUU,
            nl.SO_NAM_BAO_QUAN,
            rt.PHAM_NHAN_ID AS ll_id,
            rt.LL_SO_HO_SO_LAN_DAU,
            rt.LL_HO_TEN,
            rt.LL_TEN_KHAC,
            rt.LL_CCCD,
            rt.HO_TEN_ORDER,
            rt.LL_NGAY_SINH,
            rt.LL_DM_GIOI_TINH_ID,
            rt.LL_DIA_CHI_THUONG_TRU,
            rt.LL_DIA_CHI_THUONG_TRU_WARD,
            rt.LL_DIA_CHI_THUONG_TRU_PROVICE,
            rt.LL_PHAN_DOI_ID,
            rt.LL_PHAN_TRAI_ID,
            rt.LL_TRAI_GIAM_ID,
            rt.LL_TINH_TRANG_ID,
            rt.LL_DM_QUOC_TICH_ID,
            rt.THA_TOI_DANH,
            rt.THA_TOI_DANH_NAMES,
            rt.THA_AN_PHAT,
            rt.THA_NGAY_BAT,
            rt.THA_NGAY_DEN_TRAI,
            rt.THA_NGAY_HET_HAN,
            rt.THA_SO_BAN_AN,
            rt.THA_NGAY_BAN_AN,
            rt.THA_SO_DANH_BAN,
            rt.THA_TOA_QD_ID,
            rt.THA_SO_QD_THA,
            rt.THA_NGAY_QD_THA,
            rt.THA_DIA_PHUONG_CAP_TOA_ID,
            rt.THA_CAP_TOA_ID,
            rt.THA_DIA_PHUONG_TOA_QD_THA_ID,
            rt.THA_TOI_DANH_NUM,
            rt.IS_CHUONG_13
        FROM nl_f nl
        INNER JOIN rt_f rt
            ON rt.PHAM_NHAN_ID = nl.PHAM_NHAN_ID
           AND rt.rn_tha = 1
        LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn_f
            ON p_ly_do_ket_thuc IS NOT NULL
           AND ttpn_f.ID = rt.LL_TINH_TRANG_ID
           AND NVL(ttpn_f.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_QUOC_TICHS dqt_f
            ON p_loai_doi_tuong = u'NUOC_NGOAI'
           AND dqt_f.ID = rt.LL_DM_QUOC_TICH_ID
           AND NVL(dqt_f.IS_DELETED, 0) = 0
        WHERE (p_ly_do_ket_thuc IS NULL OR ttpn_f.TTPN_MA = p_ly_do_ket_thuc)
          AND (
              p_loai_doi_tuong IS NULL
              OR p_loai_doi_tuong <> u'NUOC_NGOAI'
              OR dqt_f.QT_MA <> u'250'
          )
    ),

    nl_ll_tha AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            ln.*
        FROM ll_nl ln
        WHERE (
            p_loai_doi_tuong IS NULL
            OR p_loai_doi_tuong = u'NUOC_NGOAI'
            OR (p_loai_doi_tuong = u'ANQG'   AND ln.IS_CHUONG_13 = 1)
            OR (p_loai_doi_tuong = u'HINH_SU' AND ln.IS_CHUONG_13 = 0)
        )
    ),

    cnt_agg AS (
        SELECT /*+ NO_MERGE */ COUNT(*) AS total_count
        FROM nl_ll_tha
    ),
    page_pn AS (
        SELECT /*+ MATERIALIZE */
            ln.ID AS nl_id,
            ln.PHAM_NHAN_ID,
            ln.CAN_BO_NOP_LUU,
            ln.CAP_BAC,
            ln.CHUC_VU,
            ln.SO_LUU_TRU,
            ln.NGAY_DANG_KY,
            ln.NGAY_KET_THUC,
            ln.SO_DANG_KY,
            ln.NGAY_NOP_LUU,
            ln.SO_NAM_BAO_QUAN,
            ln.LL_SO_HO_SO_LAN_DAU,
            ln.LL_HO_TEN,
            ln.LL_TEN_KHAC,
            ln.LL_CCCD,
            ln.HO_TEN_ORDER,
            ln.LL_NGAY_SINH,
            ln.LL_DM_GIOI_TINH_ID,
            ln.LL_DIA_CHI_THUONG_TRU,
            ln.LL_DIA_CHI_THUONG_TRU_WARD,
            ln.LL_DIA_CHI_THUONG_TRU_PROVICE,
            ln.LL_PHAN_DOI_ID,
            ln.LL_PHAN_TRAI_ID,
            ln.LL_TRAI_GIAM_ID,
            ln.LL_TINH_TRANG_ID,
            ln.LL_DM_QUOC_TICH_ID,
            ln.THA_TOI_DANH,
            ln.THA_TOI_DANH_NAMES,
            ln.THA_AN_PHAT,
            ln.THA_NGAY_BAT,
            ln.THA_NGAY_DEN_TRAI,
            ln.THA_NGAY_HET_HAN,
            ln.THA_SO_BAN_AN,
            ln.THA_NGAY_BAN_AN,
            ln.THA_SO_DANH_BAN,
            ln.THA_TOA_QD_ID,
            ln.THA_SO_QD_THA,
            ln.THA_NGAY_QD_THA,
            ln.THA_DIA_PHUONG_CAP_TOA_ID,
            ln.THA_CAP_TOA_ID,
            ln.THA_DIA_PHUONG_TOA_QD_THA_ID
        FROM nl_ll_tha ln
        ORDER BY ln.HO_TEN_ORDER, ln.LL_HO_TEN, ln.ID
        OFFSET v_skip ROWS
        FETCH NEXT v_limit ROWS ONLY
    ),
    than_nhan_page AS (
        SELECT /*+ ORDERED USE_NL(p tn) NO_USE_HASH(tn) INDEX(tn IDX_TN_PN_QH_TEN_NORM) */
            tn.PHAM_NHAN_ID,
            MAX(CASE WHEN tn.QUAN_HE_ID = 17 THEN tn.HO_TEN_THAN_NHAN END) AS BO_DE,
            MAX(CASE WHEN tn.QUAN_HE_ID = 2  THEN tn.HO_TEN_THAN_NHAN END) AS BO_NUOI,
            MAX(CASE WHEN tn.QUAN_HE_ID = 18 THEN tn.HO_TEN_THAN_NHAN END) AS ME_DE,
            MAX(CASE WHEN tn.QUAN_HE_ID = 3  THEN tn.HO_TEN_THAN_NHAN END) AS ME_NUOI
        FROM page_pn p
        INNER JOIN QLPN.THAN_NHAN_NGUOI_THANS tn
            ON tn.PHAM_NHAN_ID = p.PHAM_NHAN_ID
        WHERE NVL(tn.IS_DELETED, 0) = 0
          AND tn.QUAN_HE_ID IN (2, 3, 17, 18)
        GROUP BY tn.PHAM_NHAN_ID
    ),
    page_enrich AS (
        SELECT /*+ LEADING(p nl) USE_NL(nl) */
            p.CAN_BO_NOP_LUU,
            dcb.CB_TEN AS CAP_BAC,
            dcv.CV_TEN AS CHUC_VU,
            p.PHAM_NHAN_ID,
            p.LL_SO_HO_SO_LAN_DAU AS SO_HSLD,
            p.LL_HO_TEN            AS HO_TEN,
            p.LL_TEN_KHAC          AS TEN_KHAC,
            gt.GT_TEN              AS GIOI_TINH,
            p.LL_CCCD              AS CCCD,
            CASE
                WHEN p.LL_NGAY_SINH IS NOT NULL THEN
                    CASE
                        WHEN REGEXP_LIKE(CAST(TO_CHAR(p.LL_NGAY_SINH) AS VARCHAR2(100)), '^\d{4}$')
                        THEN TO_NUMBER(CAST(TO_CHAR(p.LL_NGAY_SINH) AS VARCHAR2(100)))
                        WHEN LENGTH(CAST(TO_CHAR(p.LL_NGAY_SINH) AS VARCHAR2(100))) >= 4
                             AND REGEXP_LIKE(SUBSTR(CAST(TO_CHAR(p.LL_NGAY_SINH) AS VARCHAR2(100)), -4), '^\d{4}$')
                        THEN TO_NUMBER(SUBSTR(CAST(TO_CHAR(p.LL_NGAY_SINH) AS VARCHAR2(100)), -4))
                        WHEN REGEXP_LIKE(CAST(TO_CHAR(p.LL_NGAY_SINH) AS VARCHAR2(100)), '\d{4}')
                        THEN TO_NUMBER(REGEXP_SUBSTR(CAST(TO_CHAR(p.LL_NGAY_SINH) AS VARCHAR2(100)), '\d{4}', 1, 1))
                        ELSE NULL
                    END
                ELSE NULL
            END AS NAM_SINH,
            CASE
                WHEN NULLIF(TRIM(p.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                  OR NULLIF(TRIM(dxp.XP_TEN), u'') IS NOT NULL
                  OR NULLIF(TRIM(dttp.TTP_TEN), u'') IS NOT NULL
                THEN TRIM(
                    NVL(NULLIF(TRIM(p.LL_DIA_CHI_THUONG_TRU), u''), u'')
                    || CASE WHEN NULLIF(TRIM(dxp.XP_TEN), u'') IS NOT NULL
                            THEN CASE WHEN NULLIF(TRIM(p.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                      THEN u', ' || dxp.XP_TEN ELSE dxp.XP_TEN END
                            ELSE u'' END
                    || CASE WHEN NULLIF(TRIM(dttp.TTP_TEN), u'') IS NOT NULL
                            THEN CASE WHEN NULLIF(TRIM(p.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                        OR NULLIF(TRIM(dxp.XP_TEN), u'') IS NOT NULL
                                      THEN u', ' || dttp.TTP_TEN ELSE dttp.TTP_TEN END
                            ELSE u'' END
                )
                ELSE NULL
            END AS NOI_THUONG_TRU_DAY_DU,
            p.THA_TOI_DANH_NAMES AS TOI_DANH,
            p.THA_TOI_DANH       AS TOI_DANH_ID,
            TRUNC(p.THA_NGAY_BAT)    AS NGAY_BAT,
            p.THA_AN_PHAT            AS AN_PHAT,
            p.THA_NGAY_HET_HAN       AS NGAY_HET_HAN,
            p.THA_SO_DANH_BAN        AS SO_DANH_BAN,
            p.THA_SO_BAN_AN          AS SO_BAN_AN,
            TRUNC(p.THA_NGAY_BAN_AN) AS NGAY_BAN_AN,
            toa_qd.CQ_TEN            AS CO_QUAN_QD_THA,
            p.SO_LUU_TRU             AS SO_HO_SO,
            TRUNC(p.NGAY_DANG_KY)    AS NGAY_LAP,
            TRUNC(p.NGAY_KET_THUC)   AS NGAY_KET_THUC_SRC,
            tg.TG_TEN                AS DON_VI_LAP,
            nl.LY_DO_KET_THUC_HO_SO,
            p.SO_DANG_KY             AS SO_DANG_KY_HO_SO,
            TRUNC(p.NGAY_NOP_LUU)    AS NGAY_NOP_LUU,
            tg.TG_TEN                AS DON_VI_NOP_LUU,
            NVL2(p.SO_NAM_BAO_QUAN,
                TO_NCHAR(p.SO_NAM_BAO_QUAN) || u' n\0103m',
                u'V\0129nh vi\1ec5n'
            ) AS THOI_HAN_BAO_QUAN,
            p.SO_NAM_BAO_QUAN,
            TO_CHAR(p.NGAY_NOP_LUU, 'YYYY') AS NAM_BAO_QUAN,
            CASE
                WHEN p.SO_NAM_BAO_QUAN IS NOT NULL AND p.NGAY_NOP_LUU IS NOT NULL
                THEN TO_NUMBER(TO_CHAR(p.NGAY_NOP_LUU, 'YYYY')) + p.SO_NAM_BAO_QUAN
                ELSE NULL
            END AS BAO_QUAN_DEN_NAM,
            TRUNC(p.THA_NGAY_DEN_TRAI) AS NGAY_DEN_TRAI,
            CAST(pd.PD_TEN AS NVARCHAR2(500)) || u', ' || CAST(pt.PT_TEN AS NVARCHAR2(500)) AS PHAN_DOI,
            p.LL_PHAN_DOI_ID    AS PHAN_DOI_ID,
            p.LL_TRAI_GIAM_ID   AS TRAI_GIAM_ID,
            p.LL_TINH_TRANG_ID,
            ttpn.TTPN_TEN       AS LOAI_NOP_LUU,
            ttpn.TTPN_MA        AS LY_DO_KET_THUC_MA,
            dqt.QT_MA           AS MA_QUOC_TICH,
            p.HO_TEN_ORDER      AS HO_TEN_ORDER_SORT,
            p.THA_SO_QD_THA     AS SO_QD_THA,
            TRUNC(p.THA_NGAY_QD_THA) AS NGAY_QD_THA,
            toa_xu.CQ_TEN       AS TOA_XU,
            dp_toa_xu.TTP_TEN   AS DIA_PHUONG_TOA_XU,
            dp_toa_qd.TTP_TEN   AS DIA_PHUONG_TOA_QD,
            ca.total_count
        FROM page_pn p
        CROSS JOIN cnt_agg ca
        INNER JOIN QLPN.NOP_LUUS nl
            ON nl.ID = p.nl_id
           AND NVL(nl.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = p.LL_DM_GIOI_TINH_ID
           AND NVL(gt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XA_PHUONG dxp
            ON dxp.ID = p.LL_DIA_CHI_THUONG_TRU_WARD
           AND NVL(dxp.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO dttp
            ON dttp.ID = p.LL_DIA_CHI_THUONG_TRU_PROVICE
           AND NVL(dttp.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_DOIS pd
            ON pd.ID = p.LL_PHAN_DOI_ID
           AND NVL(pd.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_TRAIS pt
            ON pt.ID = p.LL_PHAN_TRAI_ID
           AND NVL(pt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TRAI_GIAMS tg
            ON tg.ID = p.LL_TRAI_GIAM_ID
           AND NVL(tg.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_CO_QUANS toa_qd
            ON toa_qd.ID = p.THA_TOA_QD_ID
           AND NVL(toa_qd.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_CO_QUANS toa_xu
            ON toa_xu.ID = p.THA_TOA_QD_ID
           AND NVL(toa_xu.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO dp_toa_xu
            ON dp_toa_xu.ID = p.THA_DIA_PHUONG_CAP_TOA_ID
           AND NVL(dp_toa_xu.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO dp_toa_qd
            ON dp_toa_qd.ID = p.THA_DIA_PHUONG_TOA_QD_THA_ID
           AND NVL(dp_toa_qd.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_CAP_BACS dcb
            ON dcb.ID = p.CAP_BAC
           AND NVL(dcb.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_QUOC_TICHS dqt
            ON dqt.ID = p.LL_DM_QUOC_TICH_ID
           AND NVL(dqt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_CHUC_VUS dcv
            ON dcv.ID = p.CHUC_VU
           AND NVL(dcv.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
            ON ttpn.ID = p.LL_TINH_TRANG_ID
           AND NVL(ttpn.IS_DELETED, 0) = 0
    )
    SELECT
        pe.CAN_BO_NOP_LUU,
        pe.CAP_BAC,
        pe.CHUC_VU,
        pe.PHAM_NHAN_ID,
        pe.SO_HSLD,
        pe.HO_TEN,
        pe.GIOI_TINH,
        pe.TEN_KHAC,
        pe.CCCD,
        NVL(tn.BO_DE,  tn.BO_NUOI) AS HO_TEN_BO,
        NVL(tn.ME_DE,  tn.ME_NUOI) AS HO_TEN_ME,
        pe.NOI_THUONG_TRU_DAY_DU,
        pe.NAM_SINH,
        pe.TOI_DANH,
        TO_CHAR(pe.NGAY_BAT,     'DD/MM/YYYY') AS NGAY_BAT,
        pe.AN_PHAT,
        TO_CHAR(pe.NGAY_HET_HAN, 'DD/MM/YYYY') AS NGAY_HET_HAN,
        pe.SO_DANH_BAN,
        pe.SO_BAN_AN,
        TO_CHAR(pe.NGAY_BAN_AN,  'DD/MM/YYYY') AS NGAY_BAN_AN,
        pe.CO_QUAN_QD_THA,
        pe.SO_QD_THA,
        TO_CHAR(pe.NGAY_QD_THA, 'DD/MM/YYYY') AS NGAY_QD_THA,
        pe.TOA_XU,
        pe.DIA_PHUONG_TOA_XU,
        pe.DIA_PHUONG_TOA_QD,
        pe.SO_HO_SO,
        TO_CHAR(pe.NGAY_LAP,         'DD/MM/YYYY') AS NGAY_LAP,
        TO_CHAR(pe.NGAY_KET_THUC_SRC,'DD/MM/YYYY') AS NGAY_KET_THUC,
        pe.DON_VI_LAP,
        pe.LY_DO_KET_THUC_HO_SO,
        pe.SO_DANG_KY_HO_SO,
        TO_CHAR(pe.NGAY_NOP_LUU, 'DD/MM/YYYY') AS NGAY_NOP_LUU,
        pe.DON_VI_NOP_LUU,
        pe.THOI_HAN_BAO_QUAN,
        pe.SO_NAM_BAO_QUAN,
        pe.NAM_BAO_QUAN,
        pe.BAO_QUAN_DEN_NAM,
        TO_CHAR(pe.NGAY_DEN_TRAI,'DD/MM/YYYY') AS NGAY_DEN_TRAI,
        pe.LOAI_NOP_LUU,
        pe.PHAN_DOI,
        pe.total_count
    FROM page_enrich pe
    LEFT JOIN than_nhan_page tn
        ON tn.PHAM_NHAN_ID = pe.PHAM_NHAN_ID
    ORDER BY pe.HO_TEN_ORDER_SORT, pe.HO_TEN;

    DBMS_SQL.RETURN_RESULT(c1);
END;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_BD_THOI_HAN_NOP_LUU_HS_bk
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_BD_THOI_HAN_NOP_LUU_HS_bk" (
    p_ma_trai_giam           IN NVARCHAR2 DEFAULT NULL,
    p_ngay_ket_thuc_tu_ngay  IN NVARCHAR2 DEFAULT NULL,
    p_ngay_ket_thuc_den_ngay IN NVARCHAR2 DEFAULT NULL,
    p_ngay_den_trai_tu_ngay  IN NVARCHAR2 DEFAULT NULL,
    p_ngay_den_trai_den_ngay IN NVARCHAR2 DEFAULT NULL,
    p_loai_doi_tuong         IN NVARCHAR2 DEFAULT NULL,
    p_ly_do_ket_thuc         IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi               IN NVARCHAR2 DEFAULT NULL,
    p_thoi_han_bao_quan      IN NVARCHAR2 DEFAULT NULL,
    p_skipcount              IN NUMBER    DEFAULT 0,
    p_maxresultcount         IN NUMBER    DEFAULT null
)
AS
    v_ngay_ket_thuc_tu_ngay  TIMESTAMP;
    v_ngay_ket_thuc_den_ngay TIMESTAMP;
    v_ngay_den_trai_tu_ngay  TIMESTAMP;
    v_ngay_den_trai_den_ngay TIMESTAMP;
    v_skip                   NUMBER;
    v_limit                  NUMBER;
    v_filter_het_han         NUMBER;
    v_filter_den_trai        NUMBER;
    v_ma_trai_giam           NVARCHAR2(100);
    v_trai_giam_id           NUMBER;
    v_phan_doi_id            NUMBER;
    c1                       SYS_REFCURSOR;
BEGIN
    v_skip := NVL(p_skipcount, 0);
    v_trai_giam_id := NULL;

    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) <> '' THEN
        v_ma_trai_giam := TRIM(p_ma_trai_giam);
        BEGIN
            SELECT dtg.ID
              INTO v_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS dtg
             WHERE dtg.TG_MA = v_ma_trai_giam
               AND NVL(dtg.IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20002,
                    u'M\00e3 tr\1ea1i giam kh\00f4ng h\1ee3p l\1ec7: ' || v_ma_trai_giam
                );
        END;
    END IF;

    v_phan_doi_id :=
        CASE
            WHEN p_phan_doi IS NULL OR TRIM(p_phan_doi) = '' THEN NULL
            ELSE TO_NUMBER(TRIM(p_phan_doi))
        END;

    IF p_ngay_ket_thuc_tu_ngay IS NULL OR TRIM(p_ngay_ket_thuc_tu_ngay) = '' THEN
        v_ngay_ket_thuc_tu_ngay := NULL;
    ELSE
        v_ngay_ket_thuc_tu_ngay := TO_TIMESTAMP(TRIM(p_ngay_ket_thuc_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_ngay_ket_thuc_den_ngay IS NULL OR TRIM(p_ngay_ket_thuc_den_ngay) = '' THEN
        v_ngay_ket_thuc_den_ngay := NULL;
    ELSE
        v_ngay_ket_thuc_den_ngay := TO_TIMESTAMP(TRIM(p_ngay_ket_thuc_den_ngay), 'DD/MM/YYYY') + INTERVAL '1' DAY;
    END IF;

    IF p_ngay_den_trai_tu_ngay IS NULL OR TRIM(p_ngay_den_trai_tu_ngay) = '' THEN
        v_ngay_den_trai_tu_ngay := NULL;
    ELSE
        v_ngay_den_trai_tu_ngay := TO_TIMESTAMP(TRIM(p_ngay_den_trai_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_ngay_den_trai_den_ngay IS NULL OR TRIM(p_ngay_den_trai_den_ngay) = '' THEN
        v_ngay_den_trai_den_ngay := NULL;
    ELSE
        v_ngay_den_trai_den_ngay := TO_TIMESTAMP(TRIM(p_ngay_den_trai_den_ngay), 'DD/MM/YYYY') + INTERVAL '1' DAY;
    END IF;

    v_filter_het_han  := CASE WHEN v_ngay_ket_thuc_tu_ngay IS NOT NULL OR v_ngay_ket_thuc_den_ngay IS NOT NULL THEN 1 ELSE 0 END;
    v_filter_den_trai := CASE WHEN v_ngay_den_trai_tu_ngay IS NOT NULL OR v_ngay_den_trai_den_ngay IS NOT NULL THEN 1 ELSE 0 END;

    v_limit := CASE
        WHEN NVL(p_maxresultcount, 0) <= 0 THEN 999999999
        ELSE p_maxresultcount
    END;

    OPEN c1 FOR
    WITH
    nl_f AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            nl.ID,
            nl.PHAM_NHAN_ID,
            nl.CAN_BO_NOP_LUU,
            nl.CAP_BAC,
            nl.CHUC_VU,
            nl.SO_LUU_TRU,
            nl.NGAY_DANG_KY,
            nl.NGAY_KET_THUC,
            nl.SO_DANG_KY,
            nl.NGAY_NOP_LUU,
            nl.SO_NAM_BAO_QUAN
        FROM QLPN.NOP_LUUS nl
        WHERE nl.IS_DELETED = 0
          AND nl.NGAY_NOP_LUU IS NOT NULL
          AND (
              p_thoi_han_bao_quan IS NULL
              OR EXISTS (
                  SELECT /*+ INDEX(bqhs) */ 1
                  FROM QLPN.DM_LOAI_THOI_GIAN_BAO_QUAN_HO_SO_PHAM_NHANS bqhs
                  WHERE bqhs.ID        = nl.THOI_GIAN_BAO_QUAN
                    AND bqhs.IS_DELETED = 0
                    AND (
                        (p_thoi_han_bao_quan = u'1' AND bqhs.LTGBQHSPN_MA IN ('11','12','13','14','111','112','113'))
                     OR (p_thoi_han_bao_quan = u'2' AND bqhs.LTGBQHSPN_MA IN ('21','22','23','24','121','122','123','124','125'))
                    )
              )
          )
    ),
    rt_f AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            rt.PHAM_NHAN_ID,
            rt.LL_SO_HO_SO_LAN_DAU,
            rt.LL_HO_TEN,
            rt.LL_TEN_KHAC,
            rt.LL_CCCD,
            rt.HO_TEN_ORDER,
            rt.LL_NGAY_SINH,
            rt.LL_DM_GIOI_TINH_ID,
            rt.LL_DIA_CHI_THUONG_TRU,
            rt.LL_DIA_CHI_THUONG_TRU_WARD,
            rt.LL_DIA_CHI_THUONG_TRU_PROVICE,
            rt.LL_PHAN_DOI_ID,
            rt.LL_PHAN_TRAI_ID,
            rt.LL_TRAI_GIAM_ID,
            rt.LL_TINH_TRANG_ID,
            rt.LL_DM_QUOC_TICH_ID,
            rt.LL_CREATION_TIME,
            rt.THA_TOI_DANH,
            rt.THA_TOI_DANH_NAMES,
            rt.THA_AN_PHAT,
            rt.THA_NGAY_BAT,
            rt.THA_NGAY_DEN_TRAI,
            rt.THA_NGAY_HET_HAN,
            rt.THA_SO_BAN_AN,
            rt.THA_NGAY_BAN_AN,
            rt.THA_SO_DANH_BAN,
            rt.THA_TOA_QD_ID,
            rt.THA_DIA_PHUONG_TOA_QD_THA_ID,
            rt.THA_SO_QD_THA,
            rt.THA_NGAY_QD_THA,
            rt.THA_CAP_TOA_ID,
            rt.THA_DIA_PHUONG_CAP_TOA_ID,
            rt.THA_CREATION_TIME,
            TO_NUMBER(
                REGEXP_SUBSTR(
                    NVL(TRIM(CAST(rt.THA_TOI_DANH AS VARCHAR2(4000))), ''),
                    '[0-9]+', 1, 1
                )
            ) AS THA_TOI_DANH_NUM,
            MAX(
                CASE
                    WHEN dtd.IS_DELETED = 0
                     AND TRIM(CAST(dtd.TD_CHUONG AS VARCHAR2(10))) = '13'
                    THEN 1
                    ELSE 0
                END
            ) OVER (PARTITION BY rt.PHAM_NHAN_ID) AS IS_CHUONG_13,
            ROW_NUMBER() OVER (
                PARTITION BY rt.PHAM_NHAN_ID
                ORDER BY
                    NVL(rt.THA_NGAY_HET_HAN, rt.LL_CREATION_TIME) DESC NULLS LAST,
                    rt.LL_CREATION_TIME DESC NULLS LAST,
                    rt.THA_CREATION_TIME DESC NULLS LAST
            ) AS rn_tha
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        LEFT JOIN QLPN.DM_TOI_DANHS dtd
            ON dtd.IS_DELETED = 0
           AND dtd.ID = TO_NUMBER(
                            REGEXP_SUBSTR(
                                NVL(TRIM(CAST(rt.THA_TOI_DANH AS VARCHAR2(4000))), ''),
                                '[0-9]+', 1, 1
                            )
                        )
        WHERE rt.IS_DELETED = 0
          AND rt.THA_TOI_DANH IS NOT NULL
          AND TRIM(CAST(rt.THA_TOI_DANH AS VARCHAR2(4000))) IS NOT NULL
          AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
          AND (v_phan_doi_id  IS NULL OR rt.LL_PHAN_DOI_ID  = v_phan_doi_id)
          AND (
              v_filter_het_han = 0
              OR (
                  rt.THA_NGAY_HET_HAN IS NOT NULL
                  AND (v_ngay_ket_thuc_tu_ngay  IS NULL OR rt.THA_NGAY_HET_HAN >= v_ngay_ket_thuc_tu_ngay)
                  AND (v_ngay_ket_thuc_den_ngay IS NULL OR rt.THA_NGAY_HET_HAN <  v_ngay_ket_thuc_den_ngay)
              )
          )
          AND (
              v_filter_den_trai = 0
              OR (
                  rt.THA_NGAY_DEN_TRAI IS NOT NULL
                  AND (v_ngay_den_trai_tu_ngay  IS NULL OR rt.THA_NGAY_DEN_TRAI >= v_ngay_den_trai_tu_ngay)
                  AND (v_ngay_den_trai_den_ngay IS NULL OR rt.THA_NGAY_DEN_TRAI <  v_ngay_den_trai_den_ngay)
              )
          )
    ),
    ll_nl AS (
        SELECT /*+ MATERIALIZE USE_HASH(rt nl) SWAP_JOIN_INPUTS(nl) */
            nl.ID,
            nl.PHAM_NHAN_ID,
            nl.CAN_BO_NOP_LUU,
            nl.CAP_BAC,
            nl.CHUC_VU,
            nl.SO_LUU_TRU,
            nl.NGAY_DANG_KY,
            nl.NGAY_KET_THUC,
            nl.SO_DANG_KY,
            nl.NGAY_NOP_LUU,
            nl.SO_NAM_BAO_QUAN,
            rt.PHAM_NHAN_ID AS ll_id,
            rt.LL_SO_HO_SO_LAN_DAU,
            rt.LL_HO_TEN,
            rt.LL_TEN_KHAC,
            rt.LL_CCCD,
            rt.HO_TEN_ORDER,
            rt.LL_NGAY_SINH,
            rt.LL_DM_GIOI_TINH_ID,
            rt.LL_DIA_CHI_THUONG_TRU,
            rt.LL_DIA_CHI_THUONG_TRU_WARD,
            rt.LL_DIA_CHI_THUONG_TRU_PROVICE,
            rt.LL_PHAN_DOI_ID,
            rt.LL_PHAN_TRAI_ID,
            rt.LL_TRAI_GIAM_ID,
            rt.LL_TINH_TRANG_ID,
            rt.LL_DM_QUOC_TICH_ID,
            rt.THA_TOI_DANH,
            rt.THA_TOI_DANH_NAMES,
            rt.THA_AN_PHAT,
            rt.THA_NGAY_BAT,
            rt.THA_NGAY_DEN_TRAI,
            rt.THA_NGAY_HET_HAN,
            rt.THA_SO_BAN_AN,
            rt.THA_NGAY_BAN_AN,
            rt.THA_SO_DANH_BAN,
            rt.THA_TOA_QD_ID,
            rt.THA_DIA_PHUONG_TOA_QD_THA_ID,
            rt.THA_SO_QD_THA,
            rt.THA_NGAY_QD_THA,
            rt.THA_CAP_TOA_ID,
            rt.THA_DIA_PHUONG_CAP_TOA_ID,
            rt.THA_TOI_DANH_NUM,
            rt.IS_CHUONG_13
        FROM nl_f nl
        INNER JOIN rt_f rt
            ON rt.PHAM_NHAN_ID = nl.PHAM_NHAN_ID
           AND rt.rn_tha = 1
        LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn_f
            ON p_ly_do_ket_thuc IS NOT NULL
           AND ttpn_f.ID = rt.LL_TINH_TRANG_ID
           AND NVL(ttpn_f.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_QUOC_TICHS dqt_f
            ON p_loai_doi_tuong = u'NUOC_NGOAI'
           AND dqt_f.ID = rt.LL_DM_QUOC_TICH_ID
           AND NVL(dqt_f.IS_DELETED, 0) = 0
        WHERE (p_ly_do_ket_thuc IS NULL OR ttpn_f.TTPN_MA = p_ly_do_ket_thuc)
          AND (
              p_loai_doi_tuong IS NULL
              OR p_loai_doi_tuong <> u'NUOC_NGOAI'
              OR dqt_f.QT_MA <> u'250'
          )
    ),

    nl_ll_tha AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            ln.*
        FROM ll_nl ln
        WHERE (
            p_loai_doi_tuong IS NULL
            OR p_loai_doi_tuong = u'NUOC_NGOAI'
            OR (p_loai_doi_tuong = u'ANQG'   AND ln.IS_CHUONG_13 = 1)
            OR (p_loai_doi_tuong = u'HINH_SU' AND ln.IS_CHUONG_13 = 0)
        )
    ),

    cnt_agg AS (
        SELECT /*+ NO_MERGE */ COUNT(*) AS total_count
        FROM nl_ll_tha
    ),
    page_pn AS (
        SELECT /*+ MATERIALIZE */
            ln.ID AS nl_id,
            ln.PHAM_NHAN_ID,
            ln.CAN_BO_NOP_LUU,
            ln.CAP_BAC,
            ln.CHUC_VU,
            ln.SO_LUU_TRU,
            ln.NGAY_DANG_KY,
            ln.NGAY_KET_THUC,
            ln.SO_DANG_KY,
            ln.NGAY_NOP_LUU,
            ln.SO_NAM_BAO_QUAN,
            ln.LL_SO_HO_SO_LAN_DAU,
            ln.LL_HO_TEN,
            ln.LL_TEN_KHAC,
            ln.LL_CCCD,
            ln.HO_TEN_ORDER,
            ln.LL_NGAY_SINH,
            ln.LL_DM_GIOI_TINH_ID,
            ln.LL_DIA_CHI_THUONG_TRU,
            ln.LL_DIA_CHI_THUONG_TRU_WARD,
            ln.LL_DIA_CHI_THUONG_TRU_PROVICE,
            ln.LL_PHAN_DOI_ID,
            ln.LL_PHAN_TRAI_ID,
            ln.LL_TRAI_GIAM_ID,
            ln.LL_TINH_TRANG_ID,
            ln.LL_DM_QUOC_TICH_ID,
            ln.THA_TOI_DANH,
            ln.THA_TOI_DANH_NAMES,
            ln.THA_AN_PHAT,
            ln.THA_NGAY_BAT,
            ln.THA_NGAY_DEN_TRAI,
            ln.THA_NGAY_HET_HAN,
            ln.THA_SO_BAN_AN,
            ln.THA_NGAY_BAN_AN,
            ln.THA_SO_DANH_BAN,
            ln.THA_TOA_QD_ID,
            ln.THA_DIA_PHUONG_TOA_QD_THA_ID,
            ln.THA_SO_QD_THA,
            ln.THA_NGAY_QD_THA,
            ln.THA_CAP_TOA_ID,
            ln.THA_DIA_PHUONG_CAP_TOA_ID
        FROM nl_ll_tha ln
        ORDER BY ln.HO_TEN_ORDER, ln.LL_HO_TEN, ln.ID
        OFFSET v_skip ROWS
        FETCH NEXT v_limit ROWS ONLY
    ),
    than_nhan_page AS (
        SELECT /*+ ORDERED USE_NL(p tn) NO_USE_HASH(tn) INDEX(tn IDX_TN_PN_QH_TEN_NORM) */
            tn.PHAM_NHAN_ID,
            MAX(CASE WHEN tn.QUAN_HE_ID = 17 THEN tn.HO_TEN_THAN_NHAN END) AS BO_DE,
            MAX(CASE WHEN tn.QUAN_HE_ID = 2  THEN tn.HO_TEN_THAN_NHAN END) AS BO_NUOI,
            MAX(CASE WHEN tn.QUAN_HE_ID = 18 THEN tn.HO_TEN_THAN_NHAN END) AS ME_DE,
            MAX(CASE WHEN tn.QUAN_HE_ID = 3  THEN tn.HO_TEN_THAN_NHAN END) AS ME_NUOI
        FROM page_pn p
        INNER JOIN QLPN.THAN_NHAN_NGUOI_THANS tn
            ON tn.PHAM_NHAN_ID = p.PHAM_NHAN_ID
        WHERE NVL(tn.IS_DELETED, 0) = 0
          AND tn.QUAN_HE_ID IN (2, 3, 17, 18)
        GROUP BY tn.PHAM_NHAN_ID
    ),
    page_enrich AS (
        SELECT /*+ LEADING(p nl) USE_NL(nl) */
            p.CAN_BO_NOP_LUU,
            dcb.CB_TEN AS CAP_BAC,
            dcv.CV_TEN AS CHUC_VU,
            p.PHAM_NHAN_ID,
            p.LL_SO_HO_SO_LAN_DAU AS SO_HSLD,
            p.LL_HO_TEN            AS HO_TEN,
            p.LL_TEN_KHAC          AS TEN_KHAC,
            gt.GT_TEN              AS GIOI_TINH,
            p.LL_CCCD              AS CCCD,
            CASE
                WHEN p.LL_NGAY_SINH IS NOT NULL THEN
                    CASE
                        WHEN REGEXP_LIKE(CAST(TO_CHAR(p.LL_NGAY_SINH) AS VARCHAR2(100)), '^\d{4}$')
                        THEN TO_NUMBER(CAST(TO_CHAR(p.LL_NGAY_SINH) AS VARCHAR2(100)))
                        WHEN LENGTH(CAST(TO_CHAR(p.LL_NGAY_SINH) AS VARCHAR2(100))) >= 4
                             AND REGEXP_LIKE(SUBSTR(CAST(TO_CHAR(p.LL_NGAY_SINH) AS VARCHAR2(100)), -4), '^\d{4}$')
                        THEN TO_NUMBER(SUBSTR(CAST(TO_CHAR(p.LL_NGAY_SINH) AS VARCHAR2(100)), -4))
                        WHEN REGEXP_LIKE(CAST(TO_CHAR(p.LL_NGAY_SINH) AS VARCHAR2(100)), '\d{4}')
                        THEN TO_NUMBER(REGEXP_SUBSTR(CAST(TO_CHAR(p.LL_NGAY_SINH) AS VARCHAR2(100)), '\d{4}', 1, 1))
                        ELSE NULL
                    END
                ELSE NULL
            END AS NAM_SINH,
            CASE
                WHEN NULLIF(TRIM(p.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                  OR NULLIF(TRIM(dxp.XP_TEN), u'') IS NOT NULL
                  OR NULLIF(TRIM(dttp.TTP_TEN), u'') IS NOT NULL
                THEN TRIM(
                    NVL(NULLIF(TRIM(p.LL_DIA_CHI_THUONG_TRU), u''), u'')
                    || CASE WHEN NULLIF(TRIM(dxp.XP_TEN), u'') IS NOT NULL
                            THEN CASE WHEN NULLIF(TRIM(p.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                      THEN u', ' || dxp.XP_TEN ELSE dxp.XP_TEN END
                            ELSE u'' END
                    || CASE WHEN NULLIF(TRIM(dttp.TTP_TEN), u'') IS NOT NULL
                            THEN CASE WHEN NULLIF(TRIM(p.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                        OR NULLIF(TRIM(dxp.XP_TEN), u'') IS NOT NULL
                                      THEN u', ' || dttp.TTP_TEN ELSE dttp.TTP_TEN END
                            ELSE u'' END
                )
                ELSE NULL
            END AS NOI_THUONG_TRU_DAY_DU,
            p.THA_TOI_DANH_NAMES AS TOI_DANH,
            p.THA_TOI_DANH       AS TOI_DANH_ID,
            TRUNC(p.THA_NGAY_BAT)    AS NGAY_BAT,
            p.THA_AN_PHAT            AS AN_PHAT,
            p.THA_NGAY_HET_HAN       AS NGAY_HET_HAN,
            p.THA_SO_DANH_BAN        AS SO_DANH_BAN,
            p.THA_SO_BAN_AN          AS SO_BAN_AN,
            TRUNC(p.THA_NGAY_BAN_AN) AS NGAY_BAN_AN,
            p.THA_SO_QD_THA AS SO_QD_THA,
            p.THA_NGAY_QD_THA AS NGAY_QD_THA,
            toa_qd.CQ_TEN            AS CO_QUAN_QD_THA,
            dttp_toa_qd.TTP_TEN      AS DIA_PHUONG_TOA_QD,
            toa_xu.CQ_TEN            AS TOA_XU,
            dttp_toa_xu.TTP_TEN      AS DIA_PHUONG_TOA_XU,
            p.SO_LUU_TRU             AS SO_HO_SO,
            TRUNC(p.NGAY_DANG_KY)    AS NGAY_LAP,
            TRUNC(p.NGAY_KET_THUC)   AS NGAY_KET_THUC_SRC,
            tg.TG_TEN                AS DON_VI_LAP,
            nl.LY_DO_KET_THUC_HO_SO,
            p.SO_DANG_KY             AS SO_DANG_KY_HO_SO,
            TRUNC(p.NGAY_NOP_LUU)    AS NGAY_NOP_LUU,
            tg.TG_TEN                AS DON_VI_NOP_LUU,
            NVL2(p.SO_NAM_BAO_QUAN,
                TO_NCHAR(p.SO_NAM_BAO_QUAN) || u' n\0103m',
                u'V\0129nh vi\1ec5n'
            ) AS THOI_HAN_BAO_QUAN,
            p.SO_NAM_BAO_QUAN,
            TO_CHAR(p.NGAY_NOP_LUU, 'YYYY') AS NAM_BAO_QUAN,
            CASE
                WHEN p.SO_NAM_BAO_QUAN IS NOT NULL AND p.NGAY_NOP_LUU IS NOT NULL
                THEN TO_NUMBER(TO_CHAR(p.NGAY_NOP_LUU, 'YYYY')) + p.SO_NAM_BAO_QUAN
                ELSE NULL
            END AS BAO_QUAN_DEN_NAM,
            TRUNC(p.THA_NGAY_DEN_TRAI) AS NGAY_DEN_TRAI,
            CAST(pd.PD_TEN AS NVARCHAR2(500)) || u', ' || CAST(pt.PT_TEN AS NVARCHAR2(500)) AS PHAN_DOI,
            p.LL_PHAN_DOI_ID    AS PHAN_DOI_ID,
            p.LL_TRAI_GIAM_ID   AS TRAI_GIAM_ID,
            p.LL_TINH_TRANG_ID,
            ttpn.TTPN_TEN       AS LOAI_NOP_LUU,
            ttpn.TTPN_MA        AS LY_DO_KET_THUC_MA,
            dqt.QT_MA           AS MA_QUOC_TICH,
            p.HO_TEN_ORDER      AS HO_TEN_ORDER_SORT,
            ca.total_count
        FROM page_pn p
        CROSS JOIN cnt_agg ca
        INNER JOIN QLPN.NOP_LUUS nl
            ON nl.ID = p.nl_id
           AND NVL(nl.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = p.LL_DM_GIOI_TINH_ID
           AND NVL(gt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XA_PHUONG dxp
            ON dxp.ID = p.LL_DIA_CHI_THUONG_TRU_WARD
           AND NVL(dxp.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO dttp
            ON dttp.ID = p.LL_DIA_CHI_THUONG_TRU_PROVICE
           AND NVL(dttp.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_DOIS pd
            ON pd.ID = p.LL_PHAN_DOI_ID
           AND NVL(pd.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_TRAIS pt
            ON pt.ID = p.LL_PHAN_TRAI_ID
           AND NVL(pt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TRAI_GIAMS tg
            ON tg.ID = p.LL_TRAI_GIAM_ID
           AND NVL(tg.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_CO_QUANS toa_qd
            ON toa_qd.ID = p.THA_TOA_QD_ID
           AND NVL(toa_qd.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO dttp_toa_qd
            ON dttp_toa_qd.ID = p.THA_DIA_PHUONG_TOA_QD_THA_ID
           AND NVL(dttp_toa_qd.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_CO_QUANS toa_xu
            ON toa_xu.ID = p.THA_CAP_TOA_ID
           AND NVL(toa_xu.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO dttp_toa_xu
            ON dttp_toa_xu.ID = p.THA_DIA_PHUONG_CAP_TOA_ID
           AND NVL(dttp_toa_xu.IS_DELETED, 0) = 0  
        LEFT JOIN QLPN.DM_CAP_BACS dcb
            ON dcb.ID = p.CAP_BAC
           AND NVL(dcb.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_QUOC_TICHS dqt
            ON dqt.ID = p.LL_DM_QUOC_TICH_ID
           AND NVL(dqt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_CHUC_VUS dcv
            ON dcv.ID = p.CHUC_VU
           AND NVL(dcv.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
            ON ttpn.ID = p.LL_TINH_TRANG_ID
           AND NVL(ttpn.IS_DELETED, 0) = 0
    )
    SELECT
        pe.CAN_BO_NOP_LUU,
        pe.CAP_BAC,
        pe.CHUC_VU,
        pe.PHAM_NHAN_ID,
        pe.SO_HSLD,
        pe.HO_TEN,
        pe.GIOI_TINH,
        pe.TEN_KHAC,
        pe.CCCD,
        NVL(tn.BO_DE,  tn.BO_NUOI) AS HO_TEN_BO,
        NVL(tn.ME_DE,  tn.ME_NUOI) AS HO_TEN_ME,
        pe.NOI_THUONG_TRU_DAY_DU,
        pe.NAM_SINH,
        pe.TOI_DANH,
        TO_CHAR(pe.NGAY_BAT,     'DD/MM/YYYY') AS NGAY_BAT,
        pe.AN_PHAT,
        TO_CHAR(pe.NGAY_HET_HAN, 'DD/MM/YYYY') AS NGAY_HET_HAN,
        pe.SO_DANH_BAN,
        pe.SO_BAN_AN,
        TO_CHAR(pe.NGAY_BAN_AN,  'DD/MM/YYYY') AS NGAY_BAN_AN,
        pe.SO_QD_THA,
        pe.NGAY_QD_THA,
        pe.CO_QUAN_QD_THA,
        pe.DIA_PHUONG_TOA_QD,
        pe.TOA_XU,
        pe.DIA_PHUONG_TOA_XU,
        pe.SO_HO_SO,
        TO_CHAR(pe.NGAY_LAP,         'DD/MM/YYYY') AS NGAY_LAP,
        TO_CHAR(pe.NGAY_KET_THUC_SRC,'DD/MM/YYYY') AS NGAY_KET_THUC,
        pe.DON_VI_LAP,
        pe.LY_DO_KET_THUC_HO_SO,
        pe.SO_DANG_KY_HO_SO,
        TO_CHAR(pe.NGAY_NOP_LUU, 'DD/MM/YYYY') AS NGAY_NOP_LUU,
        pe.DON_VI_NOP_LUU,
        pe.THOI_HAN_BAO_QUAN,
        pe.SO_NAM_BAO_QUAN,
        pe.NAM_BAO_QUAN,
        pe.BAO_QUAN_DEN_NAM,
        TO_CHAR(pe.NGAY_DEN_TRAI,'DD/MM/YYYY') AS NGAY_DEN_TRAI,
        pe.LOAI_NOP_LUU,
        pe.PHAN_DOI,
        pe.total_count
    FROM page_enrich pe
    LEFT JOIN than_nhan_page tn
        ON tn.PHAM_NHAN_ID = pe.PHAM_NHAN_ID
    ORDER BY pe.HO_TEN_ORDER_SORT, pe.HO_TEN;

    DBMS_SQL.RETURN_RESULT(c1);
END;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_DE_NGHI_THA_CO_DK_QLPN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_DE_NGHI_THA_CO_DK_QLPN" (
    p_pn_ids     IN NVARCHAR2 DEFAULT NULL,
    p_dot_tha_id IN NUMBER    DEFAULT NULL,
    p_ma_trai_giam IN VARCHAR2 DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
	ID_LIST AS (
	    SELECT DISTINCT
	        TO_NUMBER(
	            REGEXP_SUBSTR(
	                REPLACE(REPLACE(TRIM(p_pn_ids), '[', ''), ']', ''),
	                '[0-9]+', 1, LEVEL
	            )
	        ) AS PN_ID
	    FROM DUAL
	    WHERE p_pn_ids IS NOT NULL
	      AND LENGTH(TRIM(p_pn_ids)) > 0
	    CONNECT BY LEVEL <= REGEXP_COUNT(
	                    REPLACE(REPLACE(TRIM(p_pn_ids), '[', ''), ']', ''),
	                    '[0-9]+'
	                )
	           AND PRIOR SYS_GUID() IS NOT NULL
	),
    tha_filtered AS (
        SELECT
            t.PHAM_NHAN_ID,
            t.NGAY_XET,
            t.NGAY_THA,
            t.SO_QUYET_DINH_THA,
            t.NGAY_QUYET_DINH_THA,
            t.TINH_TRANG_ID,
            t.QQCT_PHIEU,
            t.DANH_GIA_CAI_TAO_ID,
            t.ID AS THA_CO_DIEU_KIEN_ID,
            t.NHAN_XET,
            ROW_NUMBER() OVER (
                PARTITION BY t.PHAM_NHAN_ID
                ORDER BY t.NGAY_XET DESC
            ) AS rn
        FROM THA_CO_DIEU_KIENS t
        WHERE NVL(t.IS_DELETED, 0) = 0
          AND (p_pn_ids IS NULL OR t.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
          AND (p_dot_tha_id IS NULL OR EXISTS (
                SELECT 1
                FROM PN_DOT_THA_CO_DIEU_KIENS dot
                WHERE TRUNC(dot.DTCDK_NGAY_XET) = TRUNC(t.NGAY_XET)
                  AND dot.ID = p_dot_tha_id
                  AND NVL(dot.IS_DELETED, 0) = 0
          ))
    ),
    split_toi_danh AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            TO_NUMBER(
                REGEXP_SUBSTR(
                    REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
                    '[0-9]+', 1, LEVEL
                )
            ) AS TOI_DANH_ID
        FROM PN_THI_HANH_AN ptha
        INNER JOIN tha_filtered tf
            ON tf.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID AND tf.rn = 1
        WHERE ptha.THA_TOI_DANH IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                       REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
               AND PRIOR ptha.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    toi_danh_agg AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            LISTAGG(DISTINCT dtd.TD_TEN, ', ')
                WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH
        FROM split_toi_danh s
        LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
        GROUP BY s.THA_PNLAI_LICH_ID
    ),
    split_ghi_chu_dac_biet AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            TO_NUMBER(
                REGEXP_SUBSTR(
                    REPLACE(REPLACE(ptha.THA_GHI_CHU_DAC_BIET, '[', ''), ']', ''),
                    '[0-9]+', 1, LEVEL
                )
            ) AS GCDB_ID
        FROM PN_THI_HANH_AN ptha
        INNER JOIN tha_filtered tf
            ON tf.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID AND tf.rn = 1
        WHERE ptha.THA_GHI_CHU_DAC_BIET IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                       REPLACE(REPLACE(ptha.THA_GHI_CHU_DAC_BIET, '[', ''), ']', ''), ',') + 1
               AND PRIOR ptha.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    ghi_chu_dac_biet_agg AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            LISTAGG(DISTINCT dgcdb.GCDB_TEN, ', ')
                WITHIN GROUP (ORDER BY dgcdb.GCDB_TEN) AS GHI_CHU_DAC_BIET
        FROM split_ghi_chu_dac_biet s
        LEFT JOIN DM_GHI_CHU_DAC_BIETS dgcdb ON dgcdb.ID = s.GCDB_ID
        GROUP BY s.THA_PNLAI_LICH_ID
    ),
    latest_tha AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            ptha.THA_NGAY_BAT,
            ptha.THA_AN_PHAT,
            ptha.THA_NGAY_BAN_AN,
            ptha.THA_NGAY_HET_HAN,
            ptha.THA_NGAY_DEN_TRAI,
            ROW_NUMBER() OVER (
                PARTITION BY ptha.THA_PNLAI_LICH_ID
                ORDER BY NVL(ptha.THA_NGAY_BAN_AN,
                             TO_DATE('01-JAN-1900', 'DD-MON-YYYY')) DESC,
                         ptha.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN ptha
        INNER JOIN tha_filtered tf
            ON tf.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID AND tf.rn = 1
    ),
    latest_phan_loai AS (
        SELECT pl1.PHAM_NHAN_ID, pl1.LOAI_PHAN_LOAI_ID, pl1.NGAY_PHAN_LOAI
        FROM PHAN_LOAIS pl1
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = pl1.PHAM_NHAN_ID AND tf.rn = 1
        INNER JOIN (
            SELECT PHAM_NHAN_ID, MAX(NGAY_PHAN_LOAI) AS MAX_NGAY
            FROM PHAN_LOAIS
            GROUP BY PHAM_NHAN_ID
        ) pl2 ON pl1.PHAM_NHAN_ID = pl2.PHAM_NHAN_ID
             AND pl1.NGAY_PHAN_LOAI = pl2.MAX_NGAY
    ),
    latest_gth AS (
        SELECT
            gth.PHAM_NHAN_ID,
            gth.MUC_GIAM_ID,
            ROW_NUMBER() OVER (
                PARTITION BY gth.PHAM_NHAN_ID ORDER BY gth.ID DESC
            ) AS rn
        FROM GIAM_THOI_HANS gth
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = gth.PHAM_NHAN_ID AND tf.rn = 1
    ),
    da_chap_hanh_data AS (
        SELECT
            tf.PHAM_NHAN_ID,
            QLPN.FN_GET_DA_CHAP_HANH_THEO_NGAY(tf.PHAM_NHAN_ID, tf.NGAY_XET) AS DA_CH_OBJ
        FROM tha_filtered tf
        WHERE tf.rn = 1
    )
    SELECT
        ll.ID                                                       AS pham_nhan_id,
        ll.LL_HO_TEN                                                AS ho_ten,
        SUBSTR(TRIM(ll.LL_NGAY_SINH), -4)                           AS ngay_sinh,
        dgt.GT_TEN                                                  AS gioi_tinh,
        CASE
            WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                             THEN u', ' || dxp_thuong_tru.XP_TEN ELSE dxp_thuong_tru.XP_TEN END
                   ELSE u'' END
                || CASE WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                               OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                             THEN u', ' || dttp_thuong_tru.TTP_TEN ELSE dttp_thuong_tru.TTP_TEN END
                   ELSE u'' END
            )
            ELSE NULL
        END                                                         AS dia_chi_thuong_tru,
        CASE
            WHEN NULLIF(TRIM(ll.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_tha_ve.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_tha_ve.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(ll.LL_NOI_THA_VE_CU_TRU), u''), u'')
                || CASE WHEN NULLIF(TRIM(dxp_tha_ve.XP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(ll.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
                             THEN u', ' || dxp_tha_ve.XP_TEN ELSE dxp_tha_ve.XP_TEN END
                   ELSE u'' END
                || CASE WHEN NULLIF(TRIM(dttp_tha_ve.TTP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(ll.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
                               OR NULLIF(TRIM(dxp_tha_ve.XP_TEN), u'') IS NOT NULL
                             THEN u', ' || dttp_tha_ve.TTP_TEN ELSE dttp_tha_ve.TTP_TEN END
                   ELSE u'' END
            )
            ELSE NULL
        END                                                         AS noi_ve_cu_tru,
        CASE WHEN ll.LL_SO_TIEN_AN IS NULL THEN u'Không'
             ELSE ll.LL_SO_TIEN_AN END                              AS so_tien_an,
        td_agg.TOI_DANH                                             AS toi_danh,
        TO_CHAR(TRUNC(ptha.THA_NGAY_BAT), 'DD-MM-YYYY')            AS ngay_bat,
        TO_CHAR(TRUNC(ptha.THA_NGAY_DEN_TRAI), 'DD-MM-YYYY')       AS ngay_den_chap_hanh,
        ptha.THA_AN_PHAT                                            AS an_phat,
        QLPN.FN_TINH_AN_DA_GIAM_CHI_TIET(ll.ID)                   AS muc_giam,
        CASE
            WHEN NVL(dch.DA_CH_OBJ.nam, 0) = 0
             AND NVL(dch.DA_CH_OBJ.thang, 0) = 0
             AND NVL(dch.DA_CH_OBJ.ngay, 0) = 0
            THEN TO_NCHAR('Không')
            ELSE TRIM(
                CASE WHEN NVL(dch.DA_CH_OBJ.nam,   0) > 0 THEN dch.DA_CH_OBJ.nam   || u' n?m '  END ||
                CASE WHEN NVL(dch.DA_CH_OBJ.thang, 0) > 0 THEN dch.DA_CH_OBJ.thang || u' tháng ' END ||
                CASE WHEN NVL(dch.DA_CH_OBJ.ngay,  0) > 0 THEN dch.DA_CH_OBJ.ngay  || u' ngày'  END
            )
        END                                                         AS da_chap_hanh,
        QLPN.FN_GET_GIAM_THOI_HAN(ll.ID)                           AS da_giam_an,
        QLPN.FN_GET_CON_LAI(ll.ID)                                 AS con_lai,
        TO_CHAR(TRUNC(ptha.THA_NGAY_HET_HAN), 'DD-MM-YYYY')        AS ngay_het_han,
        dpd.PD_TEN                                                  AS phan_doi,
        dplgg.PLGG_TEN                                              AS phan_loai,
        dxlct.XLCT_TEN                                              AS danh_gia_cai_tao,
        TO_CHAR(TRUNC(pl_latest.NGAY_PHAN_LOAI), 'DD-MM-YYYY')     AS ngay_phan_loai,
        gcdb_agg.GHI_CHU_DAC_BIET                                   AS ghi_chu_dac_biet,
        TO_CHAR(TRUNC(tf.NGAY_XET), 'DD-MM-YYYY')                  AS ngay_xet,
        TO_CHAR(TRUNC(tf.NGAY_THA), 'DD-MM-YYYY')                  AS ngay_tha,
        tf.SO_QUYET_DINH_THA                                        AS so_quyet_dinh_tha,
        TO_CHAR(TRUNC(tf.NGAY_QUYET_DINH_THA), 'DD-MM-YYYY')       AS ngay_quyet_dinh_tha,
        tf.TINH_TRANG_ID                                            AS tinh_trang_id,
        tf.THA_CO_DIEU_KIEN_ID                                      AS tha_co_dieu_kien_id,
        tf.QQCT_PHIEU,
        tf.NHAN_XET
    FROM PN_LAI_LICHS ll
    INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = ll.ID AND tf.rn = 1
    LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN latest_tha ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID AND ptha.rn = 1
    LEFT JOIN DM_PHAN_DOIS dpd ON ll.LL_PHAN_DOI_ID = dpd.ID
    LEFT JOIN latest_phan_loai pl_latest ON ll.ID = pl_latest.PHAM_NHAN_ID
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg ON pl_latest.LOAI_PHAN_LOAI_ID = dplgg.ID
    LEFT JOIN toi_danh_agg td_agg ON ll.ID = td_agg.THA_PNLAI_LICH_ID
    LEFT JOIN latest_gth gth ON ll.ID = gth.PHAM_NHAN_ID AND gth.rn = 1
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
    LEFT JOIN da_chap_hanh_data dch ON dch.PHAM_NHAN_ID = ll.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS dxlct ON tf.DANH_GIA_CAI_TAO_ID = dxlct.ID
    LEFT JOIN ghi_chu_dac_biet_agg gcdb_agg ON ll.ID = gcdb_agg.THA_PNLAI_LICH_ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
        ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
       AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
        ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
       AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_THANH_PHO dttp_tha_ve
        ON ll.LL_NOI_THA_VE_CU_TRU_PROVICE = dttp_tha_ve.ID
       AND NVL(dttp_tha_ve.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_tha_ve
        ON ll.LL_NOI_THA_VE_CU_TRU_WARD = dxp_tha_ve.ID
       AND NVL(dxp_tha_ve.IS_DELETED, 0) = 0
    WHERE ll.IS_DELETED = 0
    and (p_ma_trai_giam is null or  ll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
    ORDER BY ll.LL_HO_TEN;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            u'L?i khi l?y danh sách ?? ngh? th? có ?i?u ki?n: ' || SQLERRM);
END SP_GET_DS_DE_NGHI_THA_CO_DK_QLPN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_DU_DIEU_KIEN_DAC_XA_V2
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_DU_DIEU_KIEN_DAC_XA_V2" (
    p_dot_dac_xa_id                    IN NUMBER,
    p_dieu_kien_xet_ma                IN VARCHAR2 DEFAULT NULL,
    p_mode_key                         IN VARCHAR2 DEFAULT 'DU_DIEU_KIEN',
    p_phan_doi_id                      IN NUMBER DEFAULT NULL,
    p_het_an_sau_ngay                  IN DATE DEFAULT NULL,
    p_filter_text                      IN NVARCHAR2 DEFAULT NULL,
    p_dan_toc_id                       IN NUMBER DEFAULT NULL,
    p_quoc_tich_id                     IN NUMBER DEFAULT NULL,
    p_ton_giao_id                      IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id                   IN NUMBER DEFAULT NULL,
    p_dia_phuong_dktt                  IN NVARCHAR2 DEFAULT NULL,
    p_dia_phuong_ve                    IN NVARCHAR2 DEFAULT NULL,
    p_toi_danh_id                      IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id                 IN NUMBER DEFAULT NULL,
    p_hinh_phat_bo_sung_id             IN NUMBER DEFAULT NULL,
    p_benh_tat_id                      IN NUMBER DEFAULT NULL,
    p_do_tuoi_tu                       IN NUMBER DEFAULT NULL,
    p_do_tuoi_den                      IN NUMBER DEFAULT NULL,
    p_muc_an_id                        IN NUMBER DEFAULT NULL,
    p_so_tien_su_tu                    IN NUMBER DEFAULT NULL,
    p_so_tien_su_den                   IN NUMBER DEFAULT NULL,
    p_den_trai_tu_ngay                 IN DATE DEFAULT NULL,
    p_den_trai_den_ngay                IN DATE DEFAULT NULL,
    p_ngay_het_han_tu                  IN DATE DEFAULT NULL,
    p_ngay_het_han_den                 IN DATE DEFAULT NULL,
    p_ngay_het_an                      IN DATE DEFAULT NULL,
    p_so_ngay_thieu                    IN NUMBER DEFAULT NULL,
    p_hoan_xong_tien_hpbs              IN NUMBER DEFAULT NULL,
    p_chua_hoan_xong_tien_hpbs         IN NUMBER DEFAULT NULL,
    p_tinh_tiet_dac_biet               IN NUMBER DEFAULT NULL,
    p_khong_co_tien_an                 IN NUMBER DEFAULT NULL,
    p_co_1_tien_an                     IN NUMBER DEFAULT NULL,
    p_pham_toi_anqg                    IN NUMBER DEFAULT NULL,
    p_vi_thanh_nien                    IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so                 IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai                       IN NUMBER DEFAULT NULL,
    p_phu_nu_mang_thai                 IN NUMBER DEFAULT NULL,
    p_con_nho_duoi_36_thang            IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai             IN NUMBER DEFAULT NULL,
    p_nhan_than                        IN NUMBER DEFAULT NULL,
    p_da_su_dung_ma_tuy                IN NUMBER DEFAULT NULL,
    p_doi_tuong_hiv_aids               IN NUMBER DEFAULT NULL,
    p_da_xet_dieu_kien                 IN NUMBER DEFAULT NULL,
    p_chua_xet_dieu_kien               IN NUMBER DEFAULT NULL,
    p_loc_ket_qua_cai_tao_kha_tro_len  IN NUMBER DEFAULT NULL,
    p_sort_field                       IN VARCHAR2 DEFAULT NULL,
    p_sort_dir                         IN VARCHAR2 DEFAULT 'Desc',
    p_skip_count                       IN NUMBER DEFAULT 0,
    p_max_result_count                 IN NUMBER DEFAULT 10,
    p_total_count                      OUT NUMBER
)
AS
    c1                  SYS_REFCURSOR;
    v_ngay_xet          DATE := SYSDATE;
    v_sort_field        VARCHAR2(50);
    v_sort_dir          VARCHAR2(4);
    v_skip_count        NUMBER := 0;
    v_max_result_count  NUMBER := 10;
BEGIN
    IF p_dot_dac_xa_id IS NULL THEN
        RAISE_APPLICATION_ERROR(-20002, 'DOT_DAC_XA_ID la bat buoc');
    END IF;

    BEGIN
        SELECT TRUNC(ddx.DDX_NGAY_XET)
        INTO v_ngay_xet
        FROM PN_DOT_DAC_XAS ddx
        WHERE ddx.ID = p_dot_dac_xa_id
          AND ddx.IS_DELETED = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_ngay_xet := SYSDATE;
    END;

    v_sort_field := UPPER(TRIM(NVL(p_sort_field, 'NGAY_HET_HAN')));
    IF v_sort_field IN ('HOTEN', 'HO_TEN') THEN
        v_sort_field := 'HO_TEN';
    ELSIF v_sort_field IN ('NGAYSINH', 'NGAY_SINH') THEN
        v_sort_field := 'NGAY_SINH';
    ELSE
        v_sort_field := 'NGAY_HET_HAN';
    END IF;

    v_sort_dir := UPPER(TRIM(NVL(p_sort_dir, 'DESC')));
    IF v_sort_dir NOT IN ('ASC', 'DESC') THEN
        v_sort_dir := 'DESC';
    END IF;

    v_skip_count := GREATEST(NVL(p_skip_count, 0), 0);
    v_max_result_count := GREATEST(NVL(p_max_result_count, 10), 1);

    -- =====================================================
    -- COUNT QUERY: WITH ... SELECT INTO
    -- =====================================================
    WITH ELIGIBLE AS (
        SELECT DISTINCT ddk.PN_LAI_LICH_ID
        FROM DX_DU_DIEU_KIEN_DAC_XAS ddk
        WHERE ddk.IS_DELETED = 0
          AND ddk.PN_DOT_DAC_XA_ID = p_dot_dac_xa_id
          AND ddk.PN_LAI_LICH_ID IS NOT NULL
    ),
    LATEST_THA AS (
        SELECT tha.THA_PNLAI_LICH_ID,
               tha.ID AS THA_ID,
               tha.THA_NGAY_BAT,
               tha.THA_NGAY_HET_HAN,
               tha.THA_AN_PHAT,
               tha.THA_TOI_DANH,
               tha.THA_MUC_AN_ID,
               tha.THA_NGAY_DEN_TRAI,
               tha.THA_GHI_CHU_DAC_BIET,
               tha.THA_NGAY_BAN_AN,
               ROW_NUMBER() OVER (
                   PARTITION BY tha.THA_PNLAI_LICH_ID
                   ORDER BY NVL(tha.THA_NGAY_BAN_AN, DATE '1900-01-01') DESC, tha.ID DESC
               ) AS RN
        FROM PN_THI_HANH_AN tha
        WHERE tha.IS_DELETED = 0
    ),
    SPLIT_TOI_DANH AS (
        SELECT ltha.THA_PNLAI_LICH_ID,
               TO_NUMBER(
                   REGEXP_SUBSTR(
                       REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''),
                       '[0-9]+',
                       1,
                       LEVEL
                   )
               ) AS TOI_DANH_ID
        FROM LATEST_THA ltha
        WHERE ltha.RN = 1
          AND ltha.THA_TOI_DANH IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
               AND PRIOR ltha.THA_PNLAI_LICH_ID = ltha.THA_PNLAI_LICH_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    TOI_DANH_ANQG AS (
        SELECT DISTINCT s.THA_PNLAI_LICH_ID, 1 AS IS_ANQG
        FROM SPLIT_TOI_DANH s
        LEFT JOIN DM_TOI_DANHS td ON td.ID = s.TOI_DANH_ID AND td.IS_DELETED = 0
        WHERE UPPER(TRIM(td.TD_CHUONG)) = '13'
    ),
    BASE_DATA AS (
        SELECT ll.ID AS PN_LAI_LICH_ID,
               ll.LL_HO_TEN,
               ll.LL_NGAY_SINH,
               ll.LL_PHAN_DOI_ID,
               ll.LL_DM_DAN_TOC_ID,
               ll.LL_DM_QUOC_TICH_ID,
               ll.LL_DM_TON_GIAO_ID,
               ll.LL_DM_NGHE_NGHIEP_ID,
               ll.LL_DIA_CHI_THUONG_TRU,
               ll.LL_NOI_THA_VE_CU_TRU,
               ll.LL_GHI_CHU_RIENG,
               ll.LL_GHI_CHU_CHI_TIET,
               ll.LL_GHI_CHU_CHUNG_HPBS,
               ll.LL_NHAN_THAN,
               ll.LL_SO_TIEN_AN,
               ll.LL_SO_TIEN_SU,
               ll.LL_DM_GIOI_TINH_ID,
               ll.LL_BENH_TAT_VAO_ID,
               ltha.THA_ID,
               ltha.THA_NGAY_BAT,
               ltha.THA_NGAY_HET_HAN,
               ltha.THA_AN_PHAT,
               ltha.THA_TOI_DANH,
               ltha.THA_MUC_AN_ID,
               ltha.THA_NGAY_DEN_TRAI,
               ltha.THA_GHI_CHU_DAC_BIET,
               dt.DT_MA,
               dt.DT_TEN,
               qt.QT_MA,
               qt.QT_TEN,
               gt.GT_TEN AS GIOI_TINH_NAME,
               NVL(tanqg.IS_ANQG, 0) AS IS_ANQG,
               CASE
                   WHEN REGEXP_LIKE(TRIM(NVL(ll.LL_SO_TIEN_AN, '')), '^[0-9]+$')
                       THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                   ELSE 0
               END AS SO_TIEN_AN_NUM,
               CASE
                   WHEN REGEXP_LIKE(TRIM(NVL(ll.LL_SO_TIEN_SU, '')), '^[0-9]+$')
                       THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_SU))
                   ELSE 0
               END AS SO_TIEN_SU_NUM,
               CASE
                   WHEN ll.LL_NGAY_SINH IS NULL THEN NULL
                   WHEN REGEXP_LIKE(TRIM(ll.LL_NGAY_SINH), '^[0-9]{4}$')
                       THEN EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(TRIM(ll.LL_NGAY_SINH))
                   WHEN REGEXP_LIKE(TRIM(ll.LL_NGAY_SINH), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
                       THEN EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(TRIM(ll.LL_NGAY_SINH), -4))
                   WHEN REGEXP_LIKE(REGEXP_REPLACE(TRIM(ll.LL_NGAY_SINH), '[^0-9]', ''), '^[0-9]{4,}$')
                       THEN EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(REGEXP_REPLACE(TRIM(ll.LL_NGAY_SINH), '[^0-9]', ''), -4))
                   ELSE NULL
               END AS TUOI,
               CASE
                   WHEN EXISTS (
                       SELECT 1
                       FROM PN_HINH_PHAT_BO_SUNGS h
                       WHERE h.IS_DELETED = 0
                         AND h.HPBS_MA_PHAM_NHAN = ll.ID
                         AND (
                             NVL(h.HPBS_TONG_TIEN_PHAT, 0)
                             - NVL((
                                 SELECT SUM(NVL(bl.BL_SO_TIEN, 0))
                                 FROM PN_BIENLAIES bl
                                 WHERE bl.IS_DELETED = 0 AND bl.HPBS_ID = h.ID
                             ), 0)
                         ) > 0
                   ) THEN 1 ELSE 0
               END AS IS_CHUA_HOAN_XONG_HPBS,
               CASE
                   WHEN EXISTS (
                       SELECT 1 FROM PN_NGHIEN_MT nmt
                       WHERE nmt.IS_DELETED = 0 AND nmt.NMT_PN_LAI_LICH_ID = ll.ID
                   ) THEN 1 ELSE 0
               END AS IS_DA_SU_DUNG_MA_TUY,
               CASE
                   WHEN EXISTS (
                       SELECT 1 FROM PN_DAC_XAS dx
                       WHERE dx.IS_DELETED = 0 AND dx.PNLAI_LICH_ID = ll.ID AND dx.DX_NGAY_XET IS NOT NULL
                   ) THEN 1 ELSE 0
               END AS IS_DA_DAC_XA,
               CASE
                   WHEN EXISTS (
                       SELECT 1 FROM XEP_LOAIS xl
                       INNER JOIN DM_XEP_LOAI_CAI_TAOS xldm ON xldm.ID = xl.XEP_LOAI_CA_NAM AND xldm.IS_DELETED = 0
                       WHERE xl.IS_DELETED = 0
                         AND xl.PHAM_NHAN_ID = ll.ID
                         AND UPPER(TRIM(xldm.XLCT_TEN)) IN ('KHA', 'KHÁ', 'TOT', 'T?T')
                   ) THEN 1 ELSE 0
               END AS IS_XEP_LOAI_KHA_TRO_LEN
        FROM ELIGIBLE e
        INNER JOIN PN_LAI_LICHS ll ON ll.ID = e.PN_LAI_LICH_ID AND ll.IS_DELETED = 0
        LEFT JOIN LATEST_THA ltha ON ltha.THA_PNLAI_LICH_ID = ll.ID AND ltha.RN = 1
        LEFT JOIN DM_DAN_TOCS dt ON dt.ID = ll.LL_DM_DAN_TOC_ID AND dt.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS qt ON qt.ID = ll.LL_DM_QUOC_TICH_ID AND qt.IS_DELETED = 0
        LEFT JOIN DM_GIOI_TINHS gt ON gt.ID = ll.LL_DM_GIOI_TINH_ID AND gt.IS_DELETED = 0
        LEFT JOIN TOI_DANH_ANQG tanqg ON tanqg.THA_PNLAI_LICH_ID = ll.ID
    )
    SELECT COUNT(1)
    INTO p_total_count
    FROM BASE_DATA b
    WHERE (p_phan_doi_id IS NULL OR b.LL_PHAN_DOI_ID = p_phan_doi_id)
      AND (p_het_an_sau_ngay IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN >= p_het_an_sau_ngay))
      AND (p_filter_text IS NULL OR RAWTOHEX(NLSSORT(UPPER(NVL(b.LL_HO_TEN, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT(UPPER(TRIM(p_filter_text)), 'NLS_SORT=BINARY_AI')) || '%')
      AND (p_dan_toc_id IS NULL OR b.LL_DM_DAN_TOC_ID = p_dan_toc_id)
      AND (p_quoc_tich_id IS NULL OR b.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
      AND (p_ton_giao_id IS NULL OR b.LL_DM_TON_GIAO_ID = p_ton_giao_id)
      AND (p_nghe_nghiep_id IS NULL OR b.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
      AND (p_dia_phuong_dktt IS NULL OR UPPER(NVL(b.LL_DIA_CHI_THUONG_TRU, '')) LIKE '%' || UPPER(TRIM(p_dia_phuong_dktt)) || '%')
      AND (p_dia_phuong_ve IS NULL OR UPPER(NVL(b.LL_NOI_THA_VE_CU_TRU, '')) LIKE '%' || UPPER(TRIM(p_dia_phuong_ve)) || '%')
      AND (p_do_tuoi_tu IS NULL OR (b.TUOI IS NOT NULL AND b.TUOI >= p_do_tuoi_tu))
      AND (p_do_tuoi_den IS NULL OR (b.TUOI IS NOT NULL AND b.TUOI <= p_do_tuoi_den))
      AND (p_muc_an_id IS NULL OR b.THA_MUC_AN_ID = p_muc_an_id)
      AND (p_so_tien_su_tu IS NULL OR b.SO_TIEN_SU_NUM >= p_so_tien_su_tu)
      AND (p_so_tien_su_den IS NULL OR b.SO_TIEN_SU_NUM <= p_so_tien_su_den)
      AND (p_den_trai_tu_ngay IS NULL OR (b.THA_NGAY_DEN_TRAI IS NOT NULL AND b.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay))
      AND (p_den_trai_den_ngay IS NULL OR (b.THA_NGAY_DEN_TRAI IS NOT NULL AND b.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay))
      AND (p_ngay_het_han_tu IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN >= p_ngay_het_han_tu))
      AND (p_ngay_het_han_den IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN <= p_ngay_het_han_den))
      AND (p_ngay_het_an IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN >= p_ngay_het_an))
      AND (p_so_ngay_thieu IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND (TRUNC(b.THA_NGAY_HET_HAN) - TRUNC(v_ngay_xet)) <= p_so_ngay_thieu))
      AND (p_hoan_xong_tien_hpbs IS NULL OR p_hoan_xong_tien_hpbs <> 1 OR b.IS_CHUA_HOAN_XONG_HPBS = 0)
      AND (p_chua_hoan_xong_tien_hpbs IS NULL OR p_chua_hoan_xong_tien_hpbs <> 1 OR b.IS_CHUA_HOAN_XONG_HPBS = 1)
      AND (p_tinh_tiet_dac_biet IS NULL OR p_tinh_tiet_dac_biet <> 1 OR NVL(TRIM(b.THA_GHI_CHU_DAC_BIET), 'X') <> 'X')
      AND (p_khong_co_tien_an IS NULL OR p_khong_co_tien_an <> 1 OR b.SO_TIEN_AN_NUM = 0)
      AND (p_co_1_tien_an IS NULL OR p_co_1_tien_an <> 1 OR b.SO_TIEN_AN_NUM = 1)
      AND (p_pham_toi_anqg IS NULL OR p_pham_toi_anqg <> 1 OR b.IS_ANQG = 1)
      AND (p_vi_thanh_nien IS NULL OR p_vi_thanh_nien <> 1 OR (b.TUOI IS NOT NULL AND b.TUOI < 18))
      AND (p_dan_toc_thieu_so IS NULL OR p_dan_toc_thieu_so <> 1 OR (b.LL_DM_DAN_TOC_ID IS NOT NULL AND NVL(TRIM(b.DT_MA), '0') NOT IN ('1', '01', '001') AND UPPER(NVL(b.DT_TEN, '')) NOT LIKE '%KINH%'))
      AND (p_nuoc_ngoai IS NULL OR p_nuoc_ngoai <> 1 OR (b.LL_DM_QUOC_TICH_ID IS NOT NULL AND b.LL_DM_QUOC_TICH_ID <> 87 AND UPPER(NVL(b.QT_TEN, '')) NOT LIKE '%VIET NAM%'))
      AND (p_nhan_than IS NULL OR p_nhan_than <> 1 OR NVL(TRIM(b.LL_NHAN_THAN), 'X') <> 'X')
      AND (p_da_su_dung_ma_tuy IS NULL OR p_da_su_dung_ma_tuy <> 1 OR b.IS_DA_SU_DUNG_MA_TUY = 1)
      AND (p_doi_tuong_hiv_aids IS NULL OR p_doi_tuong_hiv_aids <> 1 OR (UPPER(NVL(b.LL_GHI_CHU_RIENG, '') || ' ' || NVL(b.LL_GHI_CHU_CHI_TIET, '')) LIKE '%HIV%' OR UPPER(NVL(b.LL_GHI_CHU_RIENG, '') || ' ' || NVL(b.LL_GHI_CHU_CHI_TIET, '')) LIKE '%AIDS%'))
      AND (p_da_xet_dieu_kien IS NULL OR p_da_xet_dieu_kien <> 1 OR b.IS_DA_DAC_XA = 1)
      AND (p_chua_xet_dieu_kien IS NULL OR p_chua_xet_dieu_kien <> 1 OR b.IS_DA_DAC_XA = 0)
      AND (p_loc_ket_qua_cai_tao_kha_tro_len IS NULL OR p_loc_ket_qua_cai_tao_kha_tro_len <> 1 OR b.IS_XEP_LOAI_KHA_TRO_LEN = 1)
      AND (
          p_toi_danh_id IS NULL
          OR EXISTS (
              SELECT 1
              FROM SPLIT_TOI_DANH s
              WHERE s.THA_PNLAI_LICH_ID = b.PN_LAI_LICH_ID
                AND s.TOI_DANH_ID = p_toi_danh_id
          )
      )
      AND (
          p_ghi_chu_rieng_id IS NULL
          OR EXISTS (
              SELECT 1
              FROM DM_GHI_CHU_RIENGS gcr
              WHERE gcr.ID = p_ghi_chu_rieng_id
                AND gcr.IS_DELETED = 0
                AND (
                    (
                        RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_MA, '') || ' ' || NVL(gcr.GCR_TEN, '')), 'NLS_SORT=BINARY_AI'))
                        LIKE '%' || RAWTOHEX(NLSSORT('MA TUY', 'NLS_SORT=BINARY_AI')) || '%'
                        AND RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_MA, '') || ' ' || NVL(gcr.GCR_TEN, '')), 'NLS_SORT=BINARY_AI'))
                            LIKE '%' || RAWTOHEX(NLSSORT('SU DUNG', 'NLS_SORT=BINARY_AI')) || '%'
                        AND b.IS_DA_SU_DUNG_MA_TUY = 1
                    )
                    OR (
                        NOT (
                            RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_MA, '') || ' ' || NVL(gcr.GCR_TEN, '')), 'NLS_SORT=BINARY_AI'))
                            LIKE '%' || RAWTOHEX(NLSSORT('MA TUY', 'NLS_SORT=BINARY_AI')) || '%'
                            AND RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_MA, '') || ' ' || NVL(gcr.GCR_TEN, '')), 'NLS_SORT=BINARY_AI'))
                                LIKE '%' || RAWTOHEX(NLSSORT('SU DUNG', 'NLS_SORT=BINARY_AI')) || '%'
                        )
                        AND (
                            UPPER(NVL(b.LL_GHI_CHU_RIENG, '')) LIKE '%' || UPPER(NVL(gcr.GCR_MA, '')) || '%'
                            OR UPPER(NVL(b.LL_GHI_CHU_RIENG, '')) LIKE '%' || UPPER(NVL(gcr.GCR_TEN, '')) || '%'
                            OR UPPER(NVL(b.LL_GHI_CHU_CHI_TIET, '')) LIKE '%' || UPPER(NVL(gcr.GCR_MA, '')) || '%'
                            OR UPPER(NVL(b.LL_GHI_CHU_CHI_TIET, '')) LIKE '%' || UPPER(NVL(gcr.GCR_TEN, '')) || '%'
                        )
                    )
                )
          )
      )
      AND (
          p_hinh_phat_bo_sung_id IS NULL
          OR EXISTS (
              SELECT 1
              FROM PN_HINH_PHAT_BO_SUNGS h
              WHERE h.IS_DELETED = 0
                AND h.HPBS_MA_PHAM_NHAN = b.PN_LAI_LICH_ID
                AND h.HPBS_HINH_PHAT = p_hinh_phat_bo_sung_id
          )
      )
      AND (p_benh_tat_id IS NULL OR b.LL_BENH_TAT_VAO_ID = p_benh_tat_id)
      AND (
          p_dieu_kien_xet_ma IS NULL
          OR (
              p_dieu_kien_xet_ma = '1000' AND (
                  (UPPER(TRIM(b.THA_AN_PHAT)) LIKE '%CHUNG%THÂN%' AND PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) >= 144)
                  OR (UPPER(TRIM(b.THA_AN_PHAT)) NOT LIKE '%CHUNG%THÂN%' AND b.THA_AN_PHAT IS NOT NULL AND REGEXP_LIKE(TRIM(b.THA_AN_PHAT), '^[0-9]+$') AND TO_NUMBER(TRIM(b.THA_AN_PHAT)) > 0 AND (PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) / 12 / TO_NUMBER(TRIM(b.THA_AN_PHAT))) < 0.5)
              )
              OR p_dieu_kien_xet_ma = '1100' AND UPPER(TRIM(b.THA_AN_PHAT)) LIKE '%CHUNG%THÂN%' AND PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) >= 144
              OR p_dieu_kien_xet_ma = '1200' AND UPPER(TRIM(b.THA_AN_PHAT)) NOT LIKE '%CHUNG%THÂN%' AND b.THA_AN_PHAT IS NOT NULL AND REGEXP_LIKE(TRIM(b.THA_AN_PHAT), '^[0-9]+$') AND TO_NUMBER(TRIM(b.THA_AN_PHAT)) > 0 AND (PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) / 12 / TO_NUMBER(TRIM(b.THA_AN_PHAT))) < 0.5
              OR p_dieu_kien_xet_ma = '2401' AND b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN < v_ngay_xet
              OR p_dieu_kien_xet_ma = '2407' AND b.IS_DA_DAC_XA = 1
              OR p_dieu_kien_xet_ma = '2409' AND b.SO_TIEN_AN_NUM >= 2
              OR p_dieu_kien_xet_ma = '2413' AND b.IS_ANQG = 1
              OR p_dieu_kien_xet_ma = '2473' AND b.IS_CHUA_HOAN_XONG_HPBS = 1
              OR p_dieu_kien_xet_ma = '1930' AND b.THA_NGAY_HET_HAN IS NOT NULL AND v_ngay_xet <= b.THA_NGAY_HET_HAN
              OR p_dieu_kien_xet_ma = '1935' AND b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN <= v_ngay_xet
          )
      );

    -- =====================================================
    -- MAIN QUERY: OPEN c1 FOR WITH ... SELECT ... OFFSET
    -- =====================================================
    OPEN c1 FOR
    WITH ELIGIBLE AS (
        SELECT DISTINCT ddk.PN_LAI_LICH_ID
        FROM DX_DU_DIEU_KIEN_DAC_XAS ddk
        WHERE ddk.IS_DELETED = 0
          AND ddk.PN_DOT_DAC_XA_ID = p_dot_dac_xa_id
          AND ddk.PN_LAI_LICH_ID IS NOT NULL
    ),
    LATEST_THA AS (
        SELECT tha.THA_PNLAI_LICH_ID,
               tha.ID AS THA_ID,
               tha.THA_NGAY_BAT,
               tha.THA_NGAY_HET_HAN,
               tha.THA_AN_PHAT,
               tha.THA_TOI_DANH,
               tha.THA_MUC_AN_ID,
               tha.THA_NGAY_DEN_TRAI,
               tha.THA_GHI_CHU_DAC_BIET,
               tha.THA_NGAY_BAN_AN,
               ROW_NUMBER() OVER (
                   PARTITION BY tha.THA_PNLAI_LICH_ID
                   ORDER BY NVL(tha.THA_NGAY_BAN_AN, DATE '1900-01-01') DESC, tha.ID DESC
               ) AS RN
        FROM PN_THI_HANH_AN tha
        WHERE tha.IS_DELETED = 0
    ),
    SPLIT_TOI_DANH AS (
        SELECT ltha.THA_PNLAI_LICH_ID,
               TO_NUMBER(
                   REGEXP_SUBSTR(
                       REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''),
                       '[0-9]+',
                       1,
                       LEVEL
                   )
               ) AS TOI_DANH_ID
        FROM LATEST_THA ltha
        WHERE ltha.RN = 1
          AND ltha.THA_TOI_DANH IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
               AND PRIOR ltha.THA_PNLAI_LICH_ID = ltha.THA_PNLAI_LICH_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    TOI_DANH_ANQG AS (
        SELECT DISTINCT s.THA_PNLAI_LICH_ID, 1 AS IS_ANQG
        FROM SPLIT_TOI_DANH s
        LEFT JOIN DM_TOI_DANHS td ON td.ID = s.TOI_DANH_ID AND td.IS_DELETED = 0
        WHERE UPPER(TRIM(td.TD_CHUONG)) = '13'
    ),
    TOI_DANH_AGG AS (
        SELECT t.THA_PNLAI_LICH_ID,
               LISTAGG(t.TD_TEN, ', ') WITHIN GROUP (ORDER BY t.TD_TEN) AS TOI_DANH_TEXT
        FROM (
            SELECT DISTINCT s.THA_PNLAI_LICH_ID, td.TD_TEN
            FROM SPLIT_TOI_DANH s
            LEFT JOIN DM_TOI_DANHS td ON td.ID = s.TOI_DANH_ID AND td.IS_DELETED = 0
        ) t
        GROUP BY t.THA_PNLAI_LICH_ID
    ),
    BASE_DATA AS (
        SELECT ll.ID AS PN_LAI_LICH_ID,
               ll.LL_HO_TEN,
               ll.LL_NGAY_SINH,
               ll.LL_PHAN_DOI_ID,
               ll.LL_DM_DAN_TOC_ID,
               ll.LL_DM_QUOC_TICH_ID,
               ll.LL_DM_TON_GIAO_ID,
               ll.LL_DM_NGHE_NGHIEP_ID,
               ll.LL_DIA_CHI_THUONG_TRU,
               ll.LL_NOI_THA_VE_CU_TRU,
               ll.LL_GHI_CHU_RIENG,
               ll.LL_GHI_CHU_CHI_TIET,
               ll.LL_GHI_CHU_CHUNG_HPBS,
               ll.LL_NHAN_THAN,
               ll.LL_SO_TIEN_AN,
               ll.LL_SO_TIEN_SU,
               ll.LL_DM_GIOI_TINH_ID,
               ll.LL_BENH_TAT_VAO_ID,
               ltha.THA_ID,
               ltha.THA_NGAY_BAT,
               ltha.THA_NGAY_HET_HAN,
               ltha.THA_AN_PHAT,
               ltha.THA_TOI_DANH,
               ltha.THA_MUC_AN_ID,
               ltha.THA_NGAY_DEN_TRAI,
               ltha.THA_GHI_CHU_DAC_BIET,
               dt.DT_MA,
               dt.DT_TEN,
               qt.QT_MA,
               qt.QT_TEN,
               gt.GT_TEN AS GIOI_TINH_NAME,
               NVL(tanqg.IS_ANQG, 0) AS IS_ANQG,
               CASE
                   WHEN REGEXP_LIKE(TRIM(NVL(ll.LL_SO_TIEN_AN, '')), '^[0-9]+$')
                       THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                   ELSE 0
               END AS SO_TIEN_AN_NUM,
               CASE
                   WHEN REGEXP_LIKE(TRIM(NVL(ll.LL_SO_TIEN_SU, '')), '^[0-9]+$')
                       THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_SU))
                   ELSE 0
               END AS SO_TIEN_SU_NUM,
               CASE
                   WHEN ll.LL_NGAY_SINH IS NULL THEN NULL
                   WHEN REGEXP_LIKE(TRIM(ll.LL_NGAY_SINH), '^[0-9]{4}$')
                       THEN EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(TRIM(ll.LL_NGAY_SINH))
                   WHEN REGEXP_LIKE(TRIM(ll.LL_NGAY_SINH), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
                       THEN EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(TRIM(ll.LL_NGAY_SINH), -4))
                   WHEN REGEXP_LIKE(REGEXP_REPLACE(TRIM(ll.LL_NGAY_SINH), '[^0-9]', ''), '^[0-9]{4,}$')
                       THEN EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(REGEXP_REPLACE(TRIM(ll.LL_NGAY_SINH), '[^0-9]', ''), -4))
                   ELSE NULL
               END AS TUOI,
               CASE
                   WHEN EXISTS (
                       SELECT 1
                       FROM PN_HINH_PHAT_BO_SUNGS h
                       WHERE h.IS_DELETED = 0
                         AND h.HPBS_MA_PHAM_NHAN = ll.ID
                         AND (
                             NVL(h.HPBS_TONG_TIEN_PHAT, 0)
                             - NVL((
                                 SELECT SUM(NVL(bl.BL_SO_TIEN, 0))
                                 FROM PN_BIENLAIES bl
                                 WHERE bl.IS_DELETED = 0 AND bl.HPBS_ID = h.ID
                             ), 0)
                         ) > 0
                   ) THEN 1 ELSE 0
               END AS IS_CHUA_HOAN_XONG_HPBS,
               CASE
                   WHEN EXISTS (
                       SELECT 1 FROM PN_NGHIEN_MT nmt
                       WHERE nmt.IS_DELETED = 0 AND nmt.NMT_PN_LAI_LICH_ID = ll.ID
                   ) THEN 1 ELSE 0
               END AS IS_DA_SU_DUNG_MA_TUY,
               CASE
                   WHEN EXISTS (
                       SELECT 1 FROM PN_DAC_XAS dx
                       WHERE dx.IS_DELETED = 0 AND dx.PNLAI_LICH_ID = ll.ID AND dx.DX_NGAY_XET IS NOT NULL
                   ) THEN 1 ELSE 0
               END AS IS_DA_DAC_XA,
               CASE
                   WHEN EXISTS (
                       SELECT 1 FROM XEP_LOAIS xl
                       INNER JOIN DM_XEP_LOAI_CAI_TAOS xldm ON xldm.ID = xl.XEP_LOAI_CA_NAM AND xldm.IS_DELETED = 0
                       WHERE xl.IS_DELETED = 0
                         AND xl.PHAM_NHAN_ID = ll.ID
                         AND UPPER(TRIM(xldm.XLCT_TEN)) IN ('KHA', 'KHÁ', 'TOT', 'T?T')
                   ) THEN 1 ELSE 0
               END AS IS_XEP_LOAI_KHA_TRO_LEN
        FROM ELIGIBLE e
        INNER JOIN PN_LAI_LICHS ll ON ll.ID = e.PN_LAI_LICH_ID AND ll.IS_DELETED = 0
        LEFT JOIN LATEST_THA ltha ON ltha.THA_PNLAI_LICH_ID = ll.ID AND ltha.RN = 1
        LEFT JOIN DM_DAN_TOCS dt ON dt.ID = ll.LL_DM_DAN_TOC_ID AND dt.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS qt ON qt.ID = ll.LL_DM_QUOC_TICH_ID AND qt.IS_DELETED = 0
        LEFT JOIN DM_GIOI_TINHS gt ON gt.ID = ll.LL_DM_GIOI_TINH_ID AND gt.IS_DELETED = 0
        LEFT JOIN TOI_DANH_ANQG tanqg ON tanqg.THA_PNLAI_LICH_ID = ll.ID
    )
    SELECT x.PN_LAI_LICH_ID,
           x.LL_HO_TEN,
           x.LL_NGAY_SINH,
           x.GIOI_TINH_NAME,
           x.NOI_DKTT,
           x.NGAY_BAT,
           x.TOI_DANH,
           x.AN_PHAT,
           x.THOI_GIAN_GIAM,
           x.THOI_GIAN_DA_CHAP_HANH,
           x.THOI_GIAN_CON_LAI,
           x.XEP_LOAI,
           x.NGAY_HET_HAN,
           x.RULE_1000_ELIGIBLE,
           x.RULE_1100_CHUNG_THAN_ELIGIBLE,
           x.RULE_1200_CO_THOI_HAN_ELIGIBLE,
           x.RULE_1935_CON_LAI_NGAN,
           x.RULE_1930_RA_TRAI_SAU_NGAY_XET,
           x.RULE_2401_HET_AN,
           x.RULE_2407_DA_DAC_XA,
           x.RULE_2409_TIEN_AN_2,
           x.RULE_2413_ANQG,
           x.RULE_2473_CHUA_NOP_HPBS
    FROM (
        SELECT b.PN_LAI_LICH_ID,
               b.LL_HO_TEN,
               b.LL_NGAY_SINH,
               b.GIOI_TINH_NAME,
               b.LL_DIA_CHI_THUONG_TRU AS NOI_DKTT,
               b.THA_NGAY_BAT AS NGAY_BAT,
               NVL(tda.TOI_DANH_TEXT, b.THA_TOI_DANH) AS TOI_DANH,
               b.THA_AN_PHAT AS AN_PHAT,
               PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(b.PN_LAI_LICH_ID) AS THOI_GIAN_GIAM,
               PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) AS THOI_GIAN_DA_CHAP_HANH,
               PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(b.PN_LAI_LICH_ID) AS THOI_GIAN_CON_LAI,
               xl.XLCT_TEN AS XEP_LOAI,
               b.THA_NGAY_HET_HAN AS NGAY_HET_HAN,
               CASE
                   WHEN UPPER(TRIM(b.THA_AN_PHAT)) LIKE '%CHUNG%THÂN%' THEN
                       CASE
                           WHEN PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) >= 168 THEN 1
                           WHEN PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) >= 144
                                AND PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) < 168
                                AND NVL(TRIM(b.THA_GHI_CHU_DAC_BIET), 'X') <> 'X' THEN 1
                           ELSE 0
                       END
                   ELSE
                       CASE
                           WHEN b.THA_AN_PHAT IS NOT NULL
                                AND REGEXP_LIKE(TRIM(b.THA_AN_PHAT), '^[0-9]+$')
                                AND TO_NUMBER(TRIM(b.THA_AN_PHAT)) > 0
                                AND (PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) / 12 / TO_NUMBER(TRIM(b.THA_AN_PHAT))) < 0.5 THEN 1
                           WHEN b.THA_AN_PHAT IS NOT NULL
                                AND REGEXP_LIKE(TRIM(b.THA_AN_PHAT), '^[0-9]+$')
                                AND TO_NUMBER(TRIM(b.THA_AN_PHAT)) > 0
                                AND (PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) / 12 / TO_NUMBER(TRIM(b.THA_AN_PHAT))) >= 0.33
                                AND (PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) / 12 / TO_NUMBER(TRIM(b.THA_AN_PHAT))) < 0.5
                                AND NVL(TRIM(b.THA_GHI_CHU_DAC_BIET), 'X') <> 'X' THEN 1
                           ELSE 0
                       END
               END AS RULE_1000_ELIGIBLE,
               CASE
                   WHEN UPPER(TRIM(b.THA_AN_PHAT)) LIKE '%CHUNG%THÂN%' THEN
                       CASE
                           WHEN PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) >= 168 THEN 1
                           WHEN PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) >= 144
                                AND NVL(TRIM(b.THA_GHI_CHU_DAC_BIET), 'X') <> 'X' THEN 1
                           ELSE 0
                       END
                   ELSE 0
               END AS RULE_1100_CHUNG_THAN_ELIGIBLE,
               CASE
                   WHEN UPPER(TRIM(b.THA_AN_PHAT)) NOT LIKE '%CHUNG%THÂN%'
                        AND b.THA_AN_PHAT IS NOT NULL
                        AND REGEXP_LIKE(TRIM(b.THA_AN_PHAT), '^[0-9]+$')
                        AND TO_NUMBER(TRIM(b.THA_AN_PHAT)) > 0
                        THEN CASE
                           WHEN (PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) / 12 / TO_NUMBER(TRIM(b.THA_AN_PHAT))) < 0.5 THEN 1
                           WHEN (PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) / 12 / TO_NUMBER(TRIM(b.THA_AN_PHAT))) >= 0.33
                                AND (PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) / 12 / TO_NUMBER(TRIM(b.THA_AN_PHAT))) < 0.5
                                AND NVL(TRIM(b.THA_GHI_CHU_DAC_BIET), 'X') <> 'X' THEN 1
                           ELSE 0
                        END
                   ELSE 0
               END AS RULE_1200_CO_THOI_HAN_ELIGIBLE,
               CASE
                   WHEN b.THA_NGAY_HET_HAN IS NOT NULL AND v_ngay_xet <= b.THA_NGAY_HET_HAN THEN 1
                   ELSE 0
               END AS RULE_1935_CON_LAI_NGAN,
               CASE
                   WHEN b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN <= v_ngay_xet THEN 1
                   ELSE 0
               END AS RULE_1930_RA_TRAI_SAU_NGAY_XET,
               CASE
                   WHEN b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN < v_ngay_xet THEN 1
                   ELSE 0
               END AS RULE_2401_HET_AN,
               CASE WHEN b.IS_DA_DAC_XA = 1 THEN 1 ELSE 0 END AS RULE_2407_DA_DAC_XA,
               CASE WHEN b.SO_TIEN_AN_NUM >= 2 THEN 1 ELSE 0 END AS RULE_2409_TIEN_AN_2,
               CASE WHEN b.IS_ANQG = 1 THEN 1 ELSE 0 END AS RULE_2413_ANQG,
               CASE WHEN b.IS_CHUA_HOAN_XONG_HPBS = 1 THEN 1 ELSE 0 END AS RULE_2473_CHUA_NOP_HPBS,
               ROW_NUMBER() OVER (
                   ORDER BY
                       CASE WHEN v_sort_field = 'HO_TEN' AND v_sort_dir = 'ASC' THEN b.LL_HO_TEN END ASC,
                       CASE WHEN v_sort_field = 'HO_TEN' AND v_sort_dir = 'DESC' THEN b.LL_HO_TEN END DESC,
                       CASE WHEN v_sort_field = 'NGAY_SINH' AND v_sort_dir = 'ASC' THEN b.LL_NGAY_SINH END ASC,
                       CASE WHEN v_sort_field = 'NGAY_SINH' AND v_sort_dir = 'DESC' THEN b.LL_NGAY_SINH END DESC,
                       CASE WHEN v_sort_field = 'NGAY_HET_HAN' AND v_sort_dir = 'ASC' THEN b.THA_NGAY_HET_HAN END ASC,
                       CASE WHEN v_sort_field = 'NGAY_HET_HAN' AND v_sort_dir = 'DESC' THEN b.THA_NGAY_HET_HAN END DESC,
                       b.LL_HO_TEN ASC
               ) AS RN
        FROM BASE_DATA b
        LEFT JOIN (
            SELECT xl2.PHAM_NHAN_ID, xldm2.XLCT_TEN
            FROM (
                SELECT xl3.PHAM_NHAN_ID, xl3.XEP_LOAI_CA_NAM,
                       ROW_NUMBER() OVER (
                           PARTITION BY xl3.PHAM_NHAN_ID
                           ORDER BY NVL(xl3.XEP_LOAI_NAM, 0) DESC, xl3.ID DESC
                       ) AS RN
                FROM XEP_LOAIS xl3
                WHERE xl3.IS_DELETED = 0
            ) xl2
            INNER JOIN DM_XEP_LOAI_CAI_TAOS xldm2 ON xldm2.ID = xl2.XEP_LOAI_CA_NAM AND xldm2.IS_DELETED = 0
            WHERE xl2.RN = 1
        ) xl ON xl.PHAM_NHAN_ID = b.PN_LAI_LICH_ID
        LEFT JOIN TOI_DANH_AGG tda ON tda.THA_PNLAI_LICH_ID = b.PN_LAI_LICH_ID
        WHERE (p_phan_doi_id IS NULL OR b.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (p_het_an_sau_ngay IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN >= p_het_an_sau_ngay))
          AND (p_filter_text IS NULL OR RAWTOHEX(NLSSORT(UPPER(NVL(b.LL_HO_TEN, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT(UPPER(TRIM(p_filter_text)), 'NLS_SORT=BINARY_AI')) || '%')
          AND (p_dan_toc_id IS NULL OR b.LL_DM_DAN_TOC_ID = p_dan_toc_id)
          AND (p_quoc_tich_id IS NULL OR b.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
          AND (p_ton_giao_id IS NULL OR b.LL_DM_TON_GIAO_ID = p_ton_giao_id)
          AND (p_nghe_nghiep_id IS NULL OR b.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
          AND (p_dia_phuong_dktt IS NULL OR UPPER(NVL(b.LL_DIA_CHI_THUONG_TRU, '')) LIKE '%' || UPPER(TRIM(p_dia_phuong_dktt)) || '%')
          AND (p_dia_phuong_ve IS NULL OR UPPER(NVL(b.LL_NOI_THA_VE_CU_TRU, '')) LIKE '%' || UPPER(TRIM(p_dia_phuong_ve)) || '%')
          AND (p_do_tuoi_tu IS NULL OR (b.TUOI IS NOT NULL AND b.TUOI >= p_do_tuoi_tu))
          AND (p_do_tuoi_den IS NULL OR (b.TUOI IS NOT NULL AND b.TUOI <= p_do_tuoi_den))
          AND (p_muc_an_id IS NULL OR b.THA_MUC_AN_ID = p_muc_an_id)
          AND (p_so_tien_su_tu IS NULL OR b.SO_TIEN_SU_NUM >= p_so_tien_su_tu)
          AND (p_so_tien_su_den IS NULL OR b.SO_TIEN_SU_NUM <= p_so_tien_su_den)
          AND (p_den_trai_tu_ngay IS NULL OR (b.THA_NGAY_DEN_TRAI IS NOT NULL AND b.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay))
          AND (p_den_trai_den_ngay IS NULL OR (b.THA_NGAY_DEN_TRAI IS NOT NULL AND b.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay))
          AND (p_ngay_het_han_tu IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN >= p_ngay_het_han_tu))
          AND (p_ngay_het_han_den IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN <= p_ngay_het_han_den))
          AND (p_ngay_het_an IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN >= p_ngay_het_an))
          AND (p_so_ngay_thieu IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND (TRUNC(b.THA_NGAY_HET_HAN) - TRUNC(v_ngay_xet)) <= p_so_ngay_thieu))
          AND (p_hoan_xong_tien_hpbs IS NULL OR p_hoan_xong_tien_hpbs <> 1 OR b.IS_CHUA_HOAN_XONG_HPBS = 0)
          AND (p_chua_hoan_xong_tien_hpbs IS NULL OR p_chua_hoan_xong_tien_hpbs <> 1 OR b.IS_CHUA_HOAN_XONG_HPBS = 1)
          AND (p_tinh_tiet_dac_biet IS NULL OR p_tinh_tiet_dac_biet <> 1 OR NVL(TRIM(b.THA_GHI_CHU_DAC_BIET), 'X') <> 'X')
          AND (p_khong_co_tien_an IS NULL OR p_khong_co_tien_an <> 1 OR b.SO_TIEN_AN_NUM = 0)
          AND (p_co_1_tien_an IS NULL OR p_co_1_tien_an <> 1 OR b.SO_TIEN_AN_NUM = 1)
          AND (p_pham_toi_anqg IS NULL OR p_pham_toi_anqg <> 1 OR b.IS_ANQG = 1)
          AND (p_vi_thanh_nien IS NULL OR p_vi_thanh_nien <> 1 OR (b.TUOI IS NOT NULL AND b.TUOI < 18))
          AND (p_dan_toc_thieu_so IS NULL OR p_dan_toc_thieu_so <> 1 OR (b.LL_DM_DAN_TOC_ID IS NOT NULL AND NVL(TRIM(b.DT_MA), '0') NOT IN ('1', '01', '001') AND UPPER(NVL(b.DT_TEN, '')) NOT LIKE '%KINH%'))
          AND (p_nuoc_ngoai IS NULL OR p_nuoc_ngoai <> 1 OR (b.LL_DM_QUOC_TICH_ID IS NOT NULL AND b.LL_DM_QUOC_TICH_ID <> 87 AND UPPER(NVL(b.QT_TEN, '')) NOT LIKE '%VIET NAM%'))
          AND (p_phu_nu_mang_thai IS NULL OR p_phu_nu_mang_thai <> 1 OR (UPPER(NVL(b.GIOI_TINH_NAME, '')) LIKE '%N?%' AND UPPER(NVL(b.LL_GHI_CHU_RIENG, '') || ' ' || NVL(b.LL_GHI_CHU_CHI_TIET, '')) LIKE '%MANG THAI%'))
          AND (p_con_nho_duoi_36_thang IS NULL OR p_con_nho_duoi_36_thang <> 1 OR UPPER(NVL(b.LL_GHI_CHU_RIENG, '') || ' ' || NVL(b.LL_GHI_CHU_CHI_TIET, '')) LIKE '%CON NHO%36%')
          AND (p_con_theo_me_vao_trai IS NULL OR p_con_theo_me_vao_trai <> 1 OR UPPER(NVL(b.LL_GHI_CHU_RIENG, '') || ' ' || NVL(b.LL_GHI_CHU_CHI_TIET, '')) LIKE '%CON THEO ME%')
          AND (p_nhan_than IS NULL OR p_nhan_than <> 1 OR NVL(TRIM(b.LL_NHAN_THAN), 'X') <> 'X')
          AND (p_da_su_dung_ma_tuy IS NULL OR p_da_su_dung_ma_tuy <> 1 OR b.IS_DA_SU_DUNG_MA_TUY = 1)
          AND (p_doi_tuong_hiv_aids IS NULL OR p_doi_tuong_hiv_aids <> 1 OR (UPPER(NVL(b.LL_GHI_CHU_RIENG, '') || ' ' || NVL(b.LL_GHI_CHU_CHI_TIET, '')) LIKE '%HIV%' OR UPPER(NVL(b.LL_GHI_CHU_RIENG, '') || ' ' || NVL(b.LL_GHI_CHU_CHI_TIET, '')) LIKE '%AIDS%'))
          AND (p_da_xet_dieu_kien IS NULL OR p_da_xet_dieu_kien <> 1 OR b.IS_DA_DAC_XA = 1)
          AND (p_chua_xet_dieu_kien IS NULL OR p_chua_xet_dieu_kien <> 1 OR b.IS_DA_DAC_XA = 0)
          AND (p_loc_ket_qua_cai_tao_kha_tro_len IS NULL OR p_loc_ket_qua_cai_tao_kha_tro_len <> 1 OR b.IS_XEP_LOAI_KHA_TRO_LEN = 1)
          AND (
              p_toi_danh_id IS NULL
              OR EXISTS (
                  SELECT 1
                  FROM SPLIT_TOI_DANH s
                  WHERE s.THA_PNLAI_LICH_ID = b.PN_LAI_LICH_ID
                    AND s.TOI_DANH_ID = p_toi_danh_id
              )
          )
          AND (
              p_ghi_chu_rieng_id IS NULL
              OR EXISTS (
                  SELECT 1
                  FROM DM_GHI_CHU_RIENGS gcr
                  WHERE gcr.ID = p_ghi_chu_rieng_id
                    AND gcr.IS_DELETED = 0
                    AND (
                        (
                            RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_MA, '') || ' ' || NVL(gcr.GCR_TEN, '')), 'NLS_SORT=BINARY_AI'))
                            LIKE '%' || RAWTOHEX(NLSSORT('MA TUY', 'NLS_SORT=BINARY_AI')) || '%'
                            AND RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_MA, '') || ' ' || NVL(gcr.GCR_TEN, '')), 'NLS_SORT=BINARY_AI'))
                                LIKE '%' || RAWTOHEX(NLSSORT('SU DUNG', 'NLS_SORT=BINARY_AI')) || '%'
                            AND b.IS_DA_SU_DUNG_MA_TUY = 1
                        )
                        OR (
                            NOT (
                                RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_MA, '') || ' ' || NVL(gcr.GCR_TEN, '')), 'NLS_SORT=BINARY_AI'))
                                LIKE '%' || RAWTOHEX(NLSSORT('MA TUY', 'NLS_SORT=BINARY_AI')) || '%'
                                AND RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_MA, '') || ' ' || NVL(gcr.GCR_TEN, '')), 'NLS_SORT=BINARY_AI'))
                                    LIKE '%' || RAWTOHEX(NLSSORT('SU DUNG', 'NLS_SORT=BINARY_AI')) || '%'
                            )
                            AND (
                                UPPER(NVL(b.LL_GHI_CHU_RIENG, '')) LIKE '%' || UPPER(NVL(gcr.GCR_MA, '')) || '%'
                                OR UPPER(NVL(b.LL_GHI_CHU_RIENG, '')) LIKE '%' || UPPER(NVL(gcr.GCR_TEN, '')) || '%'
                                OR UPPER(NVL(b.LL_GHI_CHU_CHI_TIET, '')) LIKE '%' || UPPER(NVL(gcr.GCR_MA, '')) || '%'
                                OR UPPER(NVL(b.LL_GHI_CHU_CHI_TIET, '')) LIKE '%' || UPPER(NVL(gcr.GCR_TEN, '')) || '%'
                            )
                        )
                    )
              )
          )
          AND (
              p_hinh_phat_bo_sung_id IS NULL
              OR EXISTS (
                  SELECT 1
                  FROM PN_HINH_PHAT_BO_SUNGS h
                  WHERE h.IS_DELETED = 0
                    AND h.HPBS_MA_PHAM_NHAN = b.PN_LAI_LICH_ID
                    AND h.HPBS_HINH_PHAT = p_hinh_phat_bo_sung_id
              )
          )
          AND (p_benh_tat_id IS NULL OR b.LL_BENH_TAT_VAO_ID = p_benh_tat_id)
          AND (
              p_dieu_kien_xet_ma IS NULL
              OR (
                  p_dieu_kien_xet_ma = '1000' AND (
                      (UPPER(TRIM(b.THA_AN_PHAT)) LIKE '%CHUNG%THÂN%' AND PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) >= 144)
                      OR (UPPER(TRIM(b.THA_AN_PHAT)) NOT LIKE '%CHUNG%THÂN%' AND b.THA_AN_PHAT IS NOT NULL AND REGEXP_LIKE(TRIM(b.THA_AN_PHAT), '^[0-9]+$') AND TO_NUMBER(TRIM(b.THA_AN_PHAT)) > 0 AND (PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) / 12 / TO_NUMBER(TRIM(b.THA_AN_PHAT))) < 0.5)
                  )
                  OR p_dieu_kien_xet_ma = '1100' AND UPPER(TRIM(b.THA_AN_PHAT)) LIKE '%CHUNG%THÂN%' AND PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) >= 144
                  OR p_dieu_kien_xet_ma = '1200' AND UPPER(TRIM(b.THA_AN_PHAT)) NOT LIKE '%CHUNG%THÂN%' AND b.THA_AN_PHAT IS NOT NULL AND REGEXP_LIKE(TRIM(b.THA_AN_PHAT), '^[0-9]+$') AND TO_NUMBER(TRIM(b.THA_AN_PHAT)) > 0 AND (PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(b.PN_LAI_LICH_ID) / 12 / TO_NUMBER(TRIM(b.THA_AN_PHAT))) < 0.5
                  OR p_dieu_kien_xet_ma = '2401' AND b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN < v_ngay_xet
                  OR p_dieu_kien_xet_ma = '2407' AND b.IS_DA_DAC_XA = 1
                  OR p_dieu_kien_xet_ma = '2409' AND b.SO_TIEN_AN_NUM >= 2
                  OR p_dieu_kien_xet_ma = '2413' AND b.IS_ANQG = 1
                  OR p_dieu_kien_xet_ma = '2473' AND b.IS_CHUA_HOAN_XONG_HPBS = 1
                  OR p_dieu_kien_xet_ma = '1930' AND b.THA_NGAY_HET_HAN IS NOT NULL AND v_ngay_xet <= b.THA_NGAY_HET_HAN
                  OR p_dieu_kien_xet_ma = '1935' AND b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN <= v_ngay_xet
              )
          )
    ) x
    WHERE x.RN > v_skip_count
      AND x.RN <= (v_skip_count + v_max_result_count)
    ORDER BY x.RN;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('SP_GET_DS_DU_DIEU_KIEN_DAC_XA_V2 Error: ' || SQLCODE || ' - ' || SQLERRM);
        RAISE;
END;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_DU_DIEU_KIEN_DAC_XA_V3
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_DU_DIEU_KIEN_DAC_XA_V3" (
    p_dot_dac_xa_id            IN NUMBER,
    p_phan_doi_id              IN NUMBER   DEFAULT NULL,
    p_het_an_sau_ngay          IN DATE     DEFAULT NULL,
    p_filter_text              IN NVARCHAR2 DEFAULT NULL,
    p_dan_toc_id               IN NUMBER   DEFAULT NULL,
    p_quoc_tich_id             IN NUMBER   DEFAULT NULL,
    p_ton_giao_id              IN NUMBER   DEFAULT NULL,
    p_nghe_nghiep_id           IN NUMBER   DEFAULT NULL,
    p_dia_phuong_dktt          IN NVARCHAR2 DEFAULT NULL,
    p_dia_phuong_ve            IN NVARCHAR2 DEFAULT NULL,
    p_do_tuoi_tu               IN NUMBER   DEFAULT NULL,
    p_do_tuoi_den              IN NUMBER   DEFAULT NULL,
    p_muc_an_id                IN NUMBER   DEFAULT NULL,
    p_so_tien_su_tu            IN NUMBER   DEFAULT NULL,
    p_so_tien_su_den           IN NUMBER   DEFAULT NULL,
    p_den_trai_tu_ngay         IN DATE     DEFAULT NULL,
    p_den_trai_den_ngay        IN DATE     DEFAULT NULL,
    p_ngay_het_han_tu          IN DATE     DEFAULT NULL,
    p_ngay_het_han_den         IN DATE     DEFAULT NULL,
    p_ngay_het_an              IN DATE     DEFAULT NULL,
    p_so_ngay_thieu            IN NUMBER   DEFAULT NULL,
    p_hoan_xong_tien_hpbs      IN NUMBER   DEFAULT NULL,
    p_chua_hoan_xong_tien_hpbs IN NUMBER   DEFAULT NULL,
    p_tinh_tiet_dac_biet       IN NUMBER   DEFAULT NULL,
    p_khong_co_tien_an         IN NUMBER   DEFAULT NULL,
    p_co_1_tien_an             IN NUMBER   DEFAULT NULL,
    p_pham_toi_anqg            IN NUMBER   DEFAULT NULL,
    p_vi_thanh_nien            IN NUMBER   DEFAULT NULL,
    p_dan_toc_thieu_so         IN NUMBER   DEFAULT NULL,
    p_nuoc_ngoai               IN NUMBER   DEFAULT NULL,
    p_phu_nu_mang_thai         IN NUMBER   DEFAULT NULL,
    p_con_nho_duoi_36_thang    IN NUMBER   DEFAULT NULL,
    p_con_theo_me_vao_trai     IN NUMBER   DEFAULT NULL,
    p_nhan_than                IN NUMBER   DEFAULT NULL,
    p_da_su_dung_ma_tuy        IN NUMBER   DEFAULT NULL,
    p_doi_tuong_hiv_aids       IN NUMBER   DEFAULT NULL,
    p_da_xet_dieu_kien         IN NUMBER   DEFAULT NULL,
    p_chua_xet_dieu_kien       IN NUMBER   DEFAULT NULL,
    p_loc_ket_qua_cai_tao_kha_tro_len IN NUMBER DEFAULT NULL,
    p_toi_danh_id              IN NUMBER   DEFAULT NULL,
    p_ghi_chu_rieng_id         IN NUMBER   DEFAULT NULL,
    p_hinh_phat_bo_sung_id     IN NUMBER   DEFAULT NULL,
    p_benh_tat_id              IN NUMBER   DEFAULT NULL,
    p_dieu_kien_xet_ma         IN NVARCHAR2 DEFAULT NULL,
    p_ma_trai_giam               IN NVARCHAR2 DEFAULT NULL,
    p_sort_field               IN NVARCHAR2 DEFAULT NULL,
    p_sort_dir                 IN NVARCHAR2 DEFAULT NULL,
    p_skip_count               IN NUMBER   DEFAULT NULL,
    p_max_result_count         IN NUMBER   DEFAULT NULL,
    p_total_count              OUT NUMBER
) AS
    c1 SYS_REFCURSOR;
    v_ngay_xet DATE;
    v_sort_field NVARCHAR2(50);
    v_sort_dir NVARCHAR2(10);
    v_skip_count NUMBER;
    v_max_result_count NUMBER;
    v_like_filter_text     VARCHAR2(4000);
BEGIN
    BEGIN
        SELECT TRUNC(dd.DDX_NGAY_XET)
        INTO v_ngay_xet
        FROM PN_DOT_DAC_XAS dd
        WHERE dd.ID = p_dot_dac_xa_id
          AND dd.IS_DELETED = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_ngay_xet := TRUNC(SYSDATE);
    END;

    v_sort_field := UPPER(TRIM(NVL(p_sort_field, 'NGAY_HET_HAN')));
    IF v_sort_field IN ('HOTEN', 'HO_TEN') THEN
        v_sort_field := 'HO_TEN';
    ELSIF v_sort_field IN ('NGAYSINH', 'NGAY_SINH') THEN
        v_sort_field := 'NGAY_SINH';
    ELSIF v_sort_field IN ('NGAYBAT', 'NGAY_BAT') THEN
        v_sort_field := 'NGAY_BAT';
    ELSE
        v_sort_field := 'NGAY_HET_HAN';
    END IF;

    v_sort_dir := UPPER(TRIM(NVL(p_sort_dir, 'DESC')));
    IF v_sort_dir NOT IN ('ASC', 'DESC') THEN
        v_sort_dir := 'DESC';
    END IF;

    v_skip_count := GREATEST(NVL(p_skip_count, 0), 0);
    v_max_result_count := GREATEST(NVL(p_max_result_count, 20), 1);

    IF p_filter_text IS NOT NULL AND LENGTH(TRIM(p_filter_text)) > 0 THEN
        v_like_filter_text := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_filter_text, ''))))) || '%';
    END IF;

    OPEN c1 FOR
    WITH
        FILTERED AS (
        SELECT b.*,
               COUNT(1) OVER () AS TOTAL_COUNT_ALL,
               ROW_NUMBER() OVER (
                   ORDER BY
                       CASE WHEN v_sort_field = 'HO_TEN' AND v_sort_dir = 'ASC' THEN b.LL_HO_TEN END ASC,
                       CASE WHEN v_sort_field = 'HO_TEN' AND v_sort_dir = 'DESC' THEN b.LL_HO_TEN END DESC,
                       CASE WHEN v_sort_field = 'NGAY_SINH' AND v_sort_dir = 'ASC' THEN b.LL_NGAY_SINH END ASC,
                       CASE WHEN v_sort_field = 'NGAY_SINH' AND v_sort_dir = 'DESC' THEN b.LL_NGAY_SINH END DESC,
                       CASE WHEN v_sort_field = 'NGAY_BAT' AND v_sort_dir = 'ASC' THEN b.THA_NGAY_BAT END ASC,
                       CASE WHEN v_sort_field = 'NGAY_BAT' AND v_sort_dir = 'DESC' THEN b.THA_NGAY_BAT END DESC,
                       CASE WHEN v_sort_field = 'NGAY_HET_HAN' AND v_sort_dir = 'ASC' THEN b.THA_NGAY_HET_HAN END ASC,
                       CASE WHEN v_sort_field = 'NGAY_HET_HAN' AND v_sort_dir = 'DESC' THEN b.THA_NGAY_HET_HAN END DESC,
                       b.LL_HO_TEN ASC
               ) AS RN
        FROM DX_DISPLAY b
        WHERE b.PN_DOT_DAC_XA_ID = p_dot_dac_xa_id
          AND (p_phan_doi_id IS NULL OR b.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (p_het_an_sau_ngay IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN < p_het_an_sau_ngay))
          AND (v_like_filter_text IS NULL OR b.LL_HO_TEN_NORM LIKE v_like_filter_text)
          AND (p_dan_toc_id IS NULL OR b.LL_DM_DAN_TOC_ID = p_dan_toc_id)
          AND (p_quoc_tich_id IS NULL OR b.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
          AND (p_ton_giao_id IS NULL OR b.LL_DM_TON_GIAO_ID = p_ton_giao_id)
          AND (p_nghe_nghiep_id IS NULL OR b.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
          AND (p_dia_phuong_dktt IS NULL OR RAWTOHEX(NLSSORT(UPPER(NVL(b.LL_DIA_CHI_THUONG_TRU, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT(UPPER(TRIM(p_dia_phuong_dktt)), 'NLS_SORT=BINARY_AI')) || '%')
          AND (p_dia_phuong_ve IS NULL OR RAWTOHEX(NLSSORT(UPPER(NVL(b.LL_NOI_THA_VE_CU_TRU, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT(UPPER(TRIM(p_dia_phuong_ve)), 'NLS_SORT=BINARY_AI')) || '%')
          AND (p_do_tuoi_tu IS NULL OR (b.TUOI IS NOT NULL AND b.TUOI >= p_do_tuoi_tu))
          AND (p_do_tuoi_den IS NULL OR (b.TUOI IS NOT NULL AND b.TUOI <= p_do_tuoi_den))
          AND (p_muc_an_id IS NULL OR b.THA_MUC_AN_ID = p_muc_an_id)
          AND (p_so_tien_su_tu IS NULL OR b.SO_TIEN_SU_NUM >= p_so_tien_su_tu)
          AND (p_so_tien_su_den IS NULL OR b.SO_TIEN_SU_NUM <= p_so_tien_su_den)
          AND (p_den_trai_tu_ngay IS NULL OR (b.THA_NGAY_DEN_TRAI IS NOT NULL AND b.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay))
          AND (p_den_trai_den_ngay IS NULL OR (b.THA_NGAY_DEN_TRAI IS NOT NULL AND b.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay))
          AND (p_ngay_het_han_tu IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN >= p_ngay_het_han_tu))
          AND (p_ngay_het_han_den IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND b.THA_NGAY_HET_HAN <= p_ngay_het_han_den))
          AND (p_ngay_het_an IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND TRUNC(b.THA_NGAY_HET_HAN) = TRUNC(p_ngay_het_an)))
          AND (p_so_ngay_thieu IS NULL OR (b.THA_NGAY_HET_HAN IS NOT NULL AND (TRUNC(b.THA_NGAY_HET_HAN) - TRUNC(v_ngay_xet)) <= p_so_ngay_thieu))
          AND (p_hoan_xong_tien_hpbs IS NULL OR p_hoan_xong_tien_hpbs <> 1 OR (b.IS_CHUA_HOAN_XONG_HPBS = 0 AND EXISTS (SELECT 1 FROM PN_HINH_PHAT_BO_SUNGS h WHERE h.IS_DELETED = 0 AND h.HPBS_MA_PHAM_NHAN = b.PN_LAI_LICH_ID)))
          AND (p_chua_hoan_xong_tien_hpbs IS NULL OR p_chua_hoan_xong_tien_hpbs <> 1 OR b.IS_CHUA_HOAN_XONG_HPBS = 1)
          AND (p_tinh_tiet_dac_biet IS NULL OR p_tinh_tiet_dac_biet <> 1 OR b.HAS_GHI_CHU_RIENG = 1)
          AND (p_khong_co_tien_an IS NULL OR p_khong_co_tien_an <> 1 OR b.SO_TIEN_AN_NUM = 0)
          AND (p_co_1_tien_an IS NULL OR p_co_1_tien_an <> 1 OR b.SO_TIEN_AN_NUM = 1)
          AND (p_pham_toi_anqg IS NULL OR p_pham_toi_anqg <> 1 OR b.IS_ANQG = 1)
          AND (p_vi_thanh_nien IS NULL OR p_vi_thanh_nien <> 1 OR ((b.TUOI IS NOT NULL AND b.TUOI < 18) OR b.IS_VI_THANH_NIEN = 1))
          AND (p_dan_toc_thieu_so IS NULL OR p_dan_toc_thieu_so <> 1 OR (b.LL_DM_DAN_TOC_ID IS NOT NULL AND b.LL_DM_DAN_TOC_ID NOT IN (SELECT dt.ID FROM DM_DAN_TOCS dt WHERE NVL(dt.IS_DELETED, 0) = 0 AND RAWTOHEX(NLSSORT(UPPER(NVL(dt.DT_TEN, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('KINH', 'NLS_SORT=BINARY_AI')) || '%')))
          AND (p_nuoc_ngoai IS NULL OR p_nuoc_ngoai <> 1 OR (b.LL_DM_QUOC_TICH_ID IS NOT NULL AND b.LL_DM_QUOC_TICH_ID NOT IN (SELECT qt.ID FROM DM_QUOC_TICHS qt WHERE NVL(qt.IS_DELETED, 0) = 0 AND RAWTOHEX(NLSSORT(UPPER(NVL(qt.QT_TEN, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('VIET NAM', 'NLS_SORT=BINARY_AI')) || '%')))
          AND (p_phu_nu_mang_thai IS NULL OR p_phu_nu_mang_thai <> 1 OR (RAWTOHEX(NLSSORT(UPPER(NVL(b.GIOI_TINH_NAME, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('NU', 'NLS_SORT=BINARY_AI')) || '%' AND b.IS_MANG_THAI = 1))
