              OR p_dieu_kien_xet_ma = '2461' AND b.IN_KHONG_DU_DIEU_KIEN = 1 AND b.SO_TIEN_AN_NUM = 1 AND b.HAS_CHONG_THI_HANH_CONG_VU = 1
              OR p_dieu_kien_xet_ma = '2463' AND b.IN_KHONG_DU_DIEU_KIEN = 1 AND b.SO_TIEN_AN_NUM = 1 AND b.HAS_MUA_BAN_NGUOI = 1
              OR p_dieu_kien_xet_ma = '2465' AND b.IN_KHONG_DU_DIEU_KIEN = 1 AND b.SO_TIEN_AN_NUM = 1 AND b.HAS_TRE_EM = 1
              OR p_dieu_kien_xet_ma = '2467' AND b.IN_KHONG_DU_DIEU_KIEN = 1 AND b.SO_TIEN_AN_NUM = 1 AND b.HAS_GAY_ROI_TTCC = 1
              OR p_dieu_kien_xet_ma = '2469' AND b.IN_KHONG_DU_DIEU_KIEN = 1 AND b.SO_TIEN_AN_NUM = 1 AND b.HAS_TIEU_THU_TAI_SAN = 1
              OR p_dieu_kien_xet_ma = '2471' AND b.IN_KHONG_DU_DIEU_KIEN = 1 AND b.SO_TIEN_AN_NUM = 1 AND (b.HAS_CO_Y_GAY_THUONG_TICH_CON_DO = 1 OR (b.IS_CON_DO = 1 AND RAWTOHEX(NLSSORT(UPPER(NVL(b.TOI_DANH_TEXT, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('CO Y GAY THUONG TICH', 'NLS_SORT=BINARY_AI')) || '%'))
              OR p_dieu_kien_xet_ma = '2473' AND b.IN_KHONG_DU_DIEU_KIEN = 1 AND b.IS_CHUA_HOAN_XONG_HPBS = 1
              OR p_dieu_kien_xet_ma = '2999' AND b.IN_DU_DIEU_KIEN = 1 AND b.CHUA_CAP_NHAT_NGAY_XET = 1
              OR p_dieu_kien_xet_ma = '3010' AND b.IN_KHONG_DU_DIEU_KIEN = 1 AND b.DANG_TO_TUNG = 1
              OR p_dieu_kien_xet_ma = '3020' AND b.IN_KHONG_DU_DIEU_KIEN = 1 AND b.DANG_TO_TUNG = 1
              OR p_dieu_kien_xet_ma = '3030' AND b.IN_KHONG_DU_DIEU_KIEN = 1 AND b.DA_DAC_XA_TRUOC_DO = 1
              OR p_dieu_kien_xet_ma = '3040' AND b.IN_KHONG_DU_DIEU_KIEN = 1 AND b.SO_TIEN_AN_NUM >= 2
              OR p_dieu_kien_xet_ma = '3050' AND b.IN_KHONG_DU_DIEU_KIEN = 1 AND b.IS_ANQG = 1
              OR p_dieu_kien_xet_ma = '3060' AND b.IN_KHONG_DU_DIEU_KIEN = 1 AND b.THOI_GIAN_CON_LAI > 2190 AND b.HAS_GHI_CHU_RIENG = 1
          )
    )
    SELECT f.PN_LAI_LICH_ID AS PHAM_NHAN_ID,
           f.PN_LAI_LICH_ID,
           f.LL_HO_TEN AS HO_TEN,
           f.LL_NGAY_SINH AS NGAY_SINH,
           f.GIOI_TINH_NAME,
           f.LL_DIA_CHI_THUONG_TRU AS NOI_DKTT,
           f.THA_NGAY_BAT AS NGAY_BAT,
           f.TOI_DANH_TEXT AS TOI_DANH,
           f.THA_AN_PHAT AS AN_PHAT,
           TO_CHAR(f.THOI_GIAN_GIAM) AS THOI_GIAN_GIAM,
           -- TO_CHAR(f.THOI_GIAN_DA_CHAP_HANH) AS THOI_GIAN_DA_CHAP_HANH,
           -- TO_CHAR(f.THOI_GIAN_CON_LAI) AS THOI_GIAN_CON_LAI,
						f.THOI_GIAN_DA_CHAP_HANH AS THOI_GIAN_DA_CHAP_HANH_SO,
						f.THOI_GIAN_DA_CHAP_HANH_TEXT AS THOI_GIAN_DA_CHAP_HANH,
						f.THOI_GIAN_CON_LAI AS THOI_GIAN_CON_LAI_SO,
						f.THOI_GIAN_CON_LAI_TEXT AS THOI_GIAN_CON_LAI,
					NVL(f.XEP_LOAI_TEXT, '') AS XEP_LOAI,
           f.THA_NGAY_HET_HAN AS NGAY_HET_HAN,
           f.TOTAL_COUNT_ALL AS TOTAL_COUNT
    FROM FILTERED f
    WHERE f.RN > v_skip_count
      AND f.RN <= v_skip_count + v_max_result_count
    ORDER BY f.RN;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('ERR_LINE: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END ;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_DU_DK_THA_CO_DK
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_DU_DK_THA_CO_DK" (
    p_ma_trai_giam            IN  NVARCHAR2 DEFAULT NULL,  -- DM_TRAI_GIAMS.TG_MA; NULL = t?t c? tr?i
    p_dot_tha_id              IN  NUMBER    DEFAULT NULL,
    p_dieu_kien_thoi_gian_id  IN  NUMBER    DEFAULT NULL,
    p_dieu_kien_xep_loai_id   IN  NUMBER    DEFAULT NULL,
    p_dieu_kien_khac_id       IN  NUMBER    DEFAULT NULL,
    -- Ma túy: 1=?ã s? d?ng; 2=ch?a t?ng; NULL=không l?c
    p_nghien_ma_tuy_id        IN  NUMBER    DEFAULT NULL,
    p_muc_an_phat_id          IN  NUMBER    DEFAULT NULL,
    -- Tình tr?ng PN: 0=T?t c? (?ang CH án + trích xu?t l?n ??u + TX gia h?n); 1=?ang CH án (111); 2=Trích xu?t (TX l?n ??u 141 + gia h?n 142); NULL=không l?c theo nhóm
    p_trang_thai_pn_id        IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN  NUMBER    DEFAULT NULL,
    p_dia_phuong_cu_tru    IN  NUMBER    DEFAULT NULL,
    p_het_an_sau_ngay         IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_filter_text             IN  NVARCHAR2 DEFAULT NULL,
    p_khong_xet_nhieu_toi     IN  NUMBER    DEFAULT NULL,  -- 1=filter
    p_xong_hpbs_tien          IN  NUMBER    DEFAULT NULL,   -- 1=?ã thi hành xong HPBS ti?n (không xét C?p d??ng, Nuôi d??ng, Án phí); 0/null=ch?n t?t c?
    p_da_thuc_hien_xong_hpbs  IN  NUMBER    DEFAULT NULL,   -- 1=?ã thi hành xong HPBS (n?u có) tính t?t c? các lo?i; 0/null=ch?n t?t c?
    p_noi_cu_tru_ro_rang      IN  NUMBER    DEFAULT NULL,
    -- Khác NULL: s?p x?p thêm theo VW.TINH_THANH_THUONG_TRU_MA tr??c p_SORTING
    p_sort                     IN  VARCHAR2  DEFAULT NULL,
    p_SORTING                  IN  NVARCHAR2 DEFAULT NULL,
    p_maxresultcount          IN  NUMBER    DEFAULT 25,
    p_skipcount               IN  NUMBER    DEFAULT 0
) AS
    v_het_an_sau_ngay DATE;
    v_den_ngay        DATE;   -- ngày xét (PN ?ang ch?p hành án t?i ngày này)
    v_skip            NUMBER;
    v_limit           NUMBER;
    v_filter_like     VARCHAR2(4000);
    v_sorting_upper   VARCHAR2(100);
    v_trai_giam_id    NUMBER;  -- resolve TG_MA ? ID ?? partition prune PN_LAI_LICH_CHI_TIET_RT (qua VW)
    v_ma_trai_giam    NVARCHAR2(20);
    c1                SYS_REFCURSOR;
BEGIN
    v_skip          := NVL(p_skipcount, 0);
    v_limit         := NVL(p_maxresultcount, 0);
    v_sorting_upper := UPPER(TRIM(NVL(p_SORTING, '')));
    IF p_filter_text IS NOT NULL AND LENGTH(TRIM(p_filter_text)) > 0 THEN
        v_filter_like := '%' || UPPER(TRIM(TO_CHAR(p_filter_text))) || '%';
    ELSE
        v_filter_like := NULL;
    END IF;
    -- Logic v_dp_like ?ã ???c g? b? ?? chuy?n sang dùng p_dia_phuong_cu_tru (ID) tr?c ti?p ? d??i.
    IF p_het_an_sau_ngay IS NOT NULL AND TRIM(p_het_an_sau_ngay) IS NOT NULL THEN
        v_het_an_sau_ngay := TO_DATE(TRIM(p_het_an_sau_ngay), 'DD/MM/YYYY');
    ELSE
        v_het_an_sau_ngay := NULL;
    END IF;
    -- Ngày xét: l?y t? ??t tha có ?i?u ki?n ?ang m? (IS_DELETED=0, DTCDK_TRANG_THAI=1) - luôn có duy nh?t 1 ??t
    BEGIN
        SELECT TRUNC(dt.DTCDK_NGAY_XET)
        INTO v_den_ngay
        FROM PN_DOT_THA_CO_DIEU_KIENS dt
        WHERE NVL(dt.IS_DELETED, 0) = 0
          AND dt.DTCDK_TRANG_THAI = 1
          AND dt.DTCDK_NGAY_XET IS NOT NULL
          AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_den_ngay := TRUNC(SYSDATE);
        WHEN OTHERS THEN
            v_den_ngay := TRUNC(SYSDATE);
    END;

    v_trai_giam_id := NULL;
    v_ma_trai_giam := NULL;
    IF p_ma_trai_giam IS NOT NULL
       AND TRIM(p_ma_trai_giam) IS NOT NULL
    THEN
        v_ma_trai_giam := TRIM(p_ma_trai_giam);
        BEGIN
            SELECT ID INTO v_trai_giam_id
              FROM DM_TRAI_GIAMS
             WHERE TG_MA = v_ma_trai_giam
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                v_trai_giam_id := NULL;
        END;
    END IF;

    OPEN c1 FOR
    WITH
    -- PN ?ang ch?p hành án t?i v_den_ngay: có THA hi?u l?c
    tha_hieu_luc AS (
        SELECT /*+ MATERIALIZE */ tha.tha_pnlai_lich_id AS pn_id,
               MAX(tha.tha_ngay_bat)      AS ngay_bat,
               MAX(tha.tha_ngay_den_trai) AS ngay_den_trai
        FROM PN_THI_HANH_AN tha
        WHERE NVL(tha.is_deleted, 0) = 0
          AND tha.tha_pnlai_lich_id IS NOT NULL
          AND tha.tha_ngay_bat IS NOT NULL
          AND tha.tha_ngay_bat <= v_den_ngay
          AND (tha.tha_ngay_het_han IS NULL OR tha.tha_ngay_het_han >= v_den_ngay)
        GROUP BY tha.tha_pnlai_lich_id
    ),
    active_tinh_trang_ids AS (
        SELECT /*+ MATERIALIZE */ ID
        FROM DM_TINH_TRANG_PHAM_NHANS
        WHERE NVL(IS_DELETED, 0) = 0
          AND (
              ((p_trang_thai_pn_id IS NULL OR p_trang_thai_pn_id = 0)
               AND TTPN_MA IN ('111', '112', '113', '114', '141', '142'))
              OR (p_trang_thai_pn_id = 1 AND TTPN_MA IN ('111', '112', '113', '114'))
              OR (p_trang_thai_pn_id = 2 AND TTPN_MA IN ('141', '142'))
          )
    ),
    -- L?c s?m qua cache khi UI b?t filter ?K th?i gian (tránh scan pn_vw l?n)
    cache_tg_ok AS (
        SELECT /*+ MATERIALIZE */ c.PHAM_NHAN_ID
        FROM QLPN.PN_DK_THOI_GIAN_CACHE c
        WHERE p_dieu_kien_thoi_gian_id IS NOT NULL
          AND TRUNC(c.NGAY_XET) = TRUNC(v_den_ngay)
          AND (v_ma_trai_giam IS NULL OR c.MA_TRAI_GIAM = v_ma_trai_giam)
          AND (
              (p_dieu_kien_thoi_gian_id = 1 AND c.DIEU_KIEN_THOI_GIAN IN (1, 2))
              OR (p_dieu_kien_thoi_gian_id = 2 AND c.DIEU_KIEN_THOI_GIAN = 1)
              OR (p_dieu_kien_thoi_gian_id = 3 AND c.DIEU_KIEN_THOI_GIAN = 2)
              OR (p_dieu_kien_thoi_gian_id = 4 AND c.DIEU_KIEN_THOI_GIAN = 3)
          )
    ),
    -- Ngu?n PN: ??c tr?c ti?p PN_LAI_LICH_CHI_TIET_RT (tránh expand VW + PHAN_LOAIS).
    -- Drive tha_hieu_luc ? RT (PK lookup) thay full scan RT qua view.
    pn_vw AS (
        SELECT /*+ MATERIALIZE LEADING(th rt) USE_NL(rt) */
            rt.PHAM_NHAN_ID,
            v_den_ngay AS NGAY_XET,
            CAST(NULL AS NUMBER) AS tha_co_dieu_kien_id,
            CAST(NULL AS NVARCHAR2(500)) AS so_quyet_dinh,
            rt.LL_GHI_CHU_RIENG AS GHI_CHU_RIENG,
            rt.LL_NGAY_SINH AS NGAY_SINH,
            rt.NAM_SINH,
            rt.THA_AN_PHAT AS AN_PHAT,
            rt.THA_MUC_AN_ID AS MUC_AN_ID,
            rt.LL_SO_TIEN_AN AS SO_TIEN_AN,
            rt.THA_TOI_DANH_NAMES AS TOI_DANH,
            rt.THA_TOI_DANH AS TOI_DANH_ID,
            REPLACE(REPLACE(TRIM(CAST(rt.THA_TOI_DANH AS VARCHAR2(4000))), '[', ''), ']', '') AS toi_csv,
            rt.LL_HO_TEN AS HO_TEN,
            rt.HO_TEN_ORDER,
            rt.LL_DM_GIOI_TINH_ID AS GIOI_TINH_ID,
            gt.GT_TEN AS GIOI_TINH,
            CASE
                WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                  OR NULLIF(TRIM(xp_ttru.XP_TEN), u'') IS NOT NULL
                  OR NULLIF(TRIM(dttp.TTP_TEN), u'') IS NOT NULL
                THEN TRIM(
                    NVL(NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u''), u'')
                    || CASE
                        WHEN NULLIF(TRIM(xp_ttru.XP_TEN), u'') IS NOT NULL THEN
                            CASE
                                WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || xp_ttru.XP_TEN
                                ELSE xp_ttru.XP_TEN
                            END
                        ELSE u''
                       END
                    || CASE
                        WHEN NULLIF(TRIM(dttp.TTP_TEN), u'') IS NOT NULL THEN
                            CASE
                                WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                  OR NULLIF(TRIM(xp_ttru.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || dttp.TTP_TEN
                                ELSE dttp.TTP_TEN
                            END
                        ELSE u''
                       END
                )
                ELSE NULL
            END AS NOI_THUONG_TRU_DAY_DU,
            dttp.TTP_MA AS TINH_THANH_THUONG_TRU_MA,
            rt.THA_NGAY_HET_HAN AS NGAY_HET_AN,
            rt.LL_PHAN_DOI_ID AS PHAN_DOI_ID,
            pd.PD_TEN AS PHAN_DOI,
            pt.PT_TEN AS PHAN_TRAI,
            rt.LL_TRAI_GIAM_ID AS TRAI_GIAM_ID,
            COALESCE(rt.THA_NGAY_BAT, th.ngay_bat) AS NGAY_BAT_AN_PHAT,
            COALESCE(rt.THA_NGAY_DEN_TRAI, th.ngay_den_trai) AS NGAY_DEN_TRAI,
            rt.LL_TINH_TRANG_ID,
            rt.LL_NOI_THA_VE_CU_TRU AS NOI_THA_VE_CU_TRU,
            ntvct_xp.XP_TEN AS NOI_THA_VE_CU_TRU_XA,
            ntvct_ttp.TTP_TEN AS NOI_THA_VE_CU_TRU_TINH,
            rt.LL_NOI_THA_VE_CU_TRU_PROVICE AS NOI_THA_VE_CU_TRU_TINH_ID
        FROM tha_hieu_luc th
        INNER JOIN PN_LAI_LICH_CHI_TIET_RT rt
                ON rt.PHAM_NHAN_ID = th.pn_id
               AND NVL(rt.IS_DELETED, 0) = 0
               AND NVL(rt.LL_IS_DELETED, 0) = 0
               AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
        INNER JOIN active_tinh_trang_ids tt
                ON tt.ID = rt.LL_TINH_TRANG_ID
        LEFT JOIN DM_PHAN_DOIS pd
               ON pd.ID = rt.LL_PHAN_DOI_ID
              AND NVL(pd.IS_DELETED, 0) = 0
        LEFT JOIN DM_PHAN_TRAIS pt
               ON pt.ID = rt.LL_PHAN_TRAI_ID
              AND NVL(pt.IS_DELETED, 0) = 0
        LEFT JOIN DM_TINH_THANH_PHO dttp
               ON dttp.ID = rt.LL_DIA_CHI_THUONG_TRU_PROVICE
              AND NVL(dttp.IS_DELETED, 0) = 0
        LEFT JOIN DM_XA_PHUONG xp_ttru
               ON xp_ttru.ID = rt.LL_DIA_CHI_THUONG_TRU_WARD
              AND NVL(xp_ttru.IS_DELETED, 0) = 0
        LEFT JOIN DM_GIOI_TINHS gt
               ON gt.ID = rt.LL_DM_GIOI_TINH_ID
              AND NVL(gt.IS_DELETED, 0) = 0
        LEFT JOIN DM_XA_PHUONG ntvct_xp
               ON ntvct_xp.ID = rt.LL_NOI_THA_VE_CU_TRU_WARD
             AND NVL(ntvct_xp.IS_DELETED, 0) = 0
        LEFT JOIN DM_TINH_THANH_PHO ntvct_ttp
               ON ntvct_ttp.ID = rt.LL_NOI_THA_VE_CU_TRU_PROVICE
              AND NVL(ntvct_ttp.IS_DELETED, 0) = 0
        WHERE (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (p_muc_an_phat_id IS NULL OR rt.THA_MUC_AN_ID = p_muc_an_phat_id)
          AND (p_dia_phuong_cu_tru IS NULL OR rt.LL_NOI_THA_VE_CU_TRU_PROVICE = p_dia_phuong_cu_tru)
          AND (v_het_an_sau_ngay IS NULL OR CAST(rt.THA_NGAY_HET_HAN AS DATE) >= v_het_an_sau_ngay)
          AND (v_filter_like IS NULL
               OR UPPER(CAST(NVL(rt.LL_HO_TEN, '') AS VARCHAR2(2000))) LIKE v_filter_like)
          AND (p_khong_xet_nhieu_toi IS NULL OR p_khong_xet_nhieu_toi <> 1
               OR REGEXP_COUNT(
                      NVL(REPLACE(REPLACE(TRIM(CAST(rt.THA_TOI_DANH AS VARCHAR2(4000))), '[', ''), ']', ''), ''),
                      '[0-9]+'
                  ) < 2)
          AND (p_dieu_kien_thoi_gian_id IS NULL
               OR EXISTS (SELECT 1 FROM cache_tg_ok ctg WHERE ctg.PHAM_NHAN_ID = th.pn_id))
    ),
    -- T?p PHAM_NHAN_ID duy nh?t t? pn_vw: dùng chung cho semi-join / IN (tránh l?p scan pn_vw)
    pn_id_set AS (
        SELECT /*+ MATERIALIZE */ PHAM_NHAN_ID FROM pn_vw
    ),
    -- PN nghi?n ma túy (ch? trong pn_vw) ?? l?c p_nghien_ma_tuy_id
    nghien_mt AS (
        SELECT DISTINCT nmt.NMT_PN_LAI_LICH_ID AS PHAM_NHAN_ID
        FROM PN_NGHIEN_MT nmt
        WHERE p_nghien_ma_tuy_id IS NOT NULL
          AND NVL(nmt.IS_DELETED, 0) = 0
          AND EXISTS (SELECT 1 FROM pn_id_set s WHERE s.PHAM_NHAN_ID = nmt.NMT_PN_LAI_LICH_ID)
    ),
    -- Ngày/n?m sinh: cùng ngu?n và quy t?c SP_GET_THA_CDK_BAN_GIAO_PN (VW NGAY_SINH, NAM_SINH; [0-9] thay \d)
    pn_nam_sinh AS (
        SELECT w.PHAM_NHAN_ID,
               w.NGAY_XET,
               CASE
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND REGEXP_LIKE(TRIM(CAST(w.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
                 THEN TO_DATE(TRIM(CAST(w.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY')
                 ELSE NULL
               END AS ngay_sinh_date,
               CASE
                 WHEN w.NAM_SINH IS NOT NULL AND w.NAM_SINH > 0 THEN w.NAM_SINH
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND REGEXP_LIKE(TRIM(TO_CHAR(w.NGAY_SINH)), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
                 THEN EXTRACT(YEAR FROM TO_DATE(TRIM(TO_CHAR(w.NGAY_SINH)), 'DD/MM/YYYY'))
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND REGEXP_LIKE(TRIM(TO_CHAR(w.NGAY_SINH)), '^[0-9]{4}$')
                 THEN TO_NUMBER(TRIM(TO_CHAR(w.NGAY_SINH)))
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND LENGTH(TRIM(TO_CHAR(w.NGAY_SINH))) >= 4
                      AND REGEXP_LIKE(SUBSTR(TRIM(TO_CHAR(w.NGAY_SINH)), -4), '^[0-9]{4}$')
                 THEN TO_NUMBER(SUBSTR(TRIM(TO_CHAR(w.NGAY_SINH)), -4))
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND REGEXP_LIKE(TO_CHAR(w.NGAY_SINH), '[0-9]{4}')
                 THEN TO_NUMBER(REGEXP_SUBSTR(TO_CHAR(w.NGAY_SINH), '[0-9]{4}', 1, 1))
                 ELSE NULL
               END AS nam_sinh
        FROM pn_vw w
        WHERE w.NGAY_SINH IS NOT NULL OR (w.NAM_SINH IS NOT NULL AND w.NAM_SINH > 0)
    ),
    pn_duoi18 AS (
        SELECT DISTINCT ns.PHAM_NHAN_ID, ns.NGAY_XET
        FROM pn_nam_sinh ns
        WHERE p_dieu_kien_khac_id = 1
          AND ((ns.ngay_sinh_date IS NOT NULL AND MONTHS_BETWEEN(CAST(ns.NGAY_XET AS DATE), ns.ngay_sinh_date) / 12 < 18)
           OR (ns.nam_sinh IS NOT NULL AND (EXTRACT(YEAR FROM CAST(ns.NGAY_XET AS DATE)) - ns.nam_sinh) < 18))
    ),
    -- ?i?u ki?n th?i gian: ??c t? cache (refresh b?ng SP_REFRESH_PN_TCDK_CACHE)
    -- 1=?? TG th??ng; 2=?? TG ??c bi?t; 3=không ??
    dk_tg_mapped AS (
        SELECT /*+ MATERIALIZE */ w.PHAM_NHAN_ID,
               w.NGAY_XET,
               NVL(c.DIEU_KIEN_THOI_GIAN, 3) AS dieu_kien_thoi_gian_id
        FROM pn_vw w
        LEFT JOIN QLPN.PN_DK_THOI_GIAN_CACHE c
            ON c.PHAM_NHAN_ID = w.PHAM_NHAN_ID
           AND TRUNC(c.NGAY_XET) = TRUNC(w.NGAY_XET)
    ),
    -- ?i?u ki?n x?p lo?i: ng??ng quý Khá/T?t theo m?c án; s? quý l?y t? cache
    cfg_xl_muc_an AS (
        SELECT u'Chung th\00e2n gi\1ea3m xu\1ed1ng t\00f9 c\00f3 th\1eddi h\1ea1n' AS muc_an, 20 AS quy_yc FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 20 - 30 n\0103m', 16 FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 15 - 20 n\0103m', 12 FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 10 - 15 n\0103m', 8 FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 5 - 10 n\0103m', 6 FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 3 - 5 n\0103m', 4 FROM DUAL
        UNION ALL SELECT u'\00c1n d\01b0\1edbi 3 n\0103m', 2 FROM DUAL
    ),
    dk_xl_mapped AS (
        SELECT /*+ MATERIALIZE */ z.PHAM_NHAN_ID,
               z.NGAY_XET,
               CASE
                 WHEN cfg.quy_yc IS NULL THEN 1
                 WHEN NVL(xlc.QUY_LIEN_KE, 0) >= cfg.quy_yc THEN 2
                 ELSE 3
               END AS dieu_kien_xep_loai_id
        FROM (
            SELECT w.PHAM_NHAN_ID,
                   w.NGAY_XET,
                   FN_GET_MUC_AN_PHAT_TCDK(w.AN_PHAT) AS muc_an
            FROM pn_vw w
        ) z
        LEFT JOIN cfg_xl_muc_an cfg ON TRIM(NVL(cfg.muc_an, ' ')) = TRIM(NVL(z.muc_an, ' '))
        LEFT JOIN QLPN.PN_XL_CONSEC_CACHE xlc
            ON xlc.PHAM_NHAN_ID = z.PHAM_NHAN_ID
           AND TRUNC(xlc.NGAY_XET) = TRUNC(z.NGAY_XET)
    ),
    -- ?i?u ki?n khác (6 tiêu chí ? du_dieu_kien_khac). UI: p=0 không xét; p=1 ch? PN du_dieu_kien_khac=1
    ta_agg AS (
        SELECT /*+ MATERIALIZE */ pta.PNTA_LAI_LICH_ID AS pn_id, COUNT(DISTINCT pta.ID) AS so_tien_an
        FROM PN_TIEN_AN pta
        WHERE NVL(pta.IS_DELETED, 0) = 0
          AND EXISTS (SELECT 1 FROM pn_id_set s WHERE s.PHAM_NHAN_ID = pta.PNTA_LAI_LICH_ID)
        GROUP BY pta.PNTA_LAI_LICH_ID
    ),
    -- Chu?i id t?i (VW): COALESCE(TOI_DANH_ID, TOI_DANH), b? ngo?c — dùng th?ng nh?t cho join DM_TOI_DANHS và REGEXP_COUNT (tránh ORA-01722)
    toi_danh_first AS (
        SELECT x.PHAM_NHAN_ID,
               CASE
                 WHEN REGEXP_LIKE(x.first_token, '^[0-9]+$')
                 THEN TO_NUMBER(x.first_token)
               END AS toi_danh_id
        FROM (
            SELECT w.PHAM_NHAN_ID,
                   REGEXP_SUBSTR(w.toi_csv, '[0-9]+', 1, 1) AS first_token
            FROM pn_vw w
            WHERE p_dieu_kien_khac_id = 1
        ) x
    ),
    pn_bi_loai_truoc AS (
        SELECT DISTINCT tc.PHAM_NHAN_ID
        FROM THA_CO_DIEU_KIENS tc
        WHERE p_dieu_kien_khac_id = 1
          AND NVL(tc.IS_DELETED, 0) = 0
          AND tc.TINH_TRANG_ID IN (1, 4, 5, 6)
          AND EXISTS (SELECT 1 FROM pn_id_set s WHERE s.PHAM_NHAN_ID = tc.PHAM_NHAN_ID)
    ),
    -- S? l?n gi?m án: inline FN_TINH_SO_LAN_GIAM_AN thành set-based (??c GIAM_THOI_HANS 1 l?n)
    -- Luôn tính (không gate theo p_dieu_kien_khac_id) — BR1 (bên d??i) c?n dùng cho m?i PN.
    giam_an_agg AS (
        SELECT /*+ MATERIALIZE */ gth.PHAM_NHAN_ID,
               COUNT(*) AS so_lan_giam
        FROM GIAM_THOI_HANS gth
        JOIN DM_MA_THOI_GIANS dm ON dm.ID = gth.MUC_GIAM_ID AND NVL(dm.IS_DELETED, 0) = 0
        WHERE NVL(gth.IS_DELETED, 0) = 0
          AND gth.MUC_GIAM_ID IS NOT NULL
          AND NVL(dm.MTG_MA, '000000') <> '000000'
          AND EXISTS (SELECT 1 FROM pn_id_set s WHERE s.PHAM_NHAN_ID = gth.PHAM_NHAN_ID)
        GROUP BY gth.PHAM_NHAN_ID
    ),
    -- BR1 (quy t?c c?t lõi, LUÔN áp d?ng — không ph? thu?c p_dieu_kien_khac_id):
    -- T?i nghiêm tr?ng/r?t nghiêm tr?ng/??c bi?t nghiêm tr?ng (proxy: m?c án >= 3 n?m)
    -- ch? ???c xét n?u ?ã ???c gi?m th?i h?n ch?p hành (so_lan_giam > 0).
    br1_eval AS (
        SELECT w.PHAM_NHAN_ID,
               CASE
                 WHEN NVL(FN_PARSE_THOI_GIAN_TEXT(w.AN_PHAT, 'NAM'), 0) +
                      NVL(FN_PARSE_THOI_GIAN_TEXT(w.AN_PHAT, 'THANG'), 0)/12 +
                      NVL(FN_PARSE_THOI_GIAN_TEXT(w.AN_PHAT, 'NGAY'), 0)/365 <= 3
                 THEN 1
                 WHEN NVL(ga.so_lan_giam, 0) > 0 THEN 1
                 ELSE 0
               END AS dat_br1
        FROM pn_vw w
        LEFT JOIN giam_an_agg ga ON ga.PHAM_NHAN_ID = w.PHAM_NHAN_ID
    ),
    dk_khac AS (
        SELECT w.PHAM_NHAN_ID,
               w.NGAY_XET,
               w.AN_PHAT,
               w.toi_csv,
               w.MUC_AN_ID,
               TRIM(dm.TD_CHUONG) AS td_chuong,
               UPPER(TRIM(dm.TD_MA)) AS td_ma,
               NVL(FN_PARSE_THOI_GIAN_TEXT(w.AN_PHAT, 'NAM'), 0) +
                 NVL(FN_PARSE_THOI_GIAN_TEXT(w.AN_PHAT, 'THANG'), 0)/12 +
                 NVL(FN_PARSE_THOI_GIAN_TEXT(w.AN_PHAT, 'NGAY'), 0)/365 AS muc_an_so_nam,
               NVL(ta.so_tien_an, 0) AS so_tien_an,
               NVL(TO_NUMBER(REGEXP_SUBSTR(TRIM(w.SO_TIEN_AN), '^[0-9]+')), 0) AS ll_so_tien_an,
               NVL(ga.so_lan_giam, 0) AS so_lan_giam,
               CASE WHEN du18.PHAM_NHAN_ID IS NOT NULL THEN 1 ELSE 0 END AS is_duoi18,
               CASE WHEN ploai.PHAM_NHAN_ID IS NOT NULL THEN 1 ELSE 0 END AS da_bi_loai_truoc
        FROM pn_vw w
        LEFT JOIN ta_agg ta ON ta.pn_id = w.PHAM_NHAN_ID
        LEFT JOIN toi_danh_first tdf ON tdf.PHAM_NHAN_ID = w.PHAM_NHAN_ID
        LEFT JOIN DM_TOI_DANHS dm ON dm.ID = tdf.toi_danh_id AND NVL(dm.IS_DELETED, 0) = 0
        LEFT JOIN pn_duoi18 du18 ON du18.PHAM_NHAN_ID = w.PHAM_NHAN_ID AND TRUNC(du18.NGAY_XET) = TRUNC(w.NGAY_XET)
        LEFT JOIN pn_bi_loai_truoc ploai ON ploai.PHAM_NHAN_ID = w.PHAM_NHAN_ID
        LEFT JOIN giam_an_agg ga ON ga.PHAM_NHAN_ID = w.PHAM_NHAN_ID
        WHERE p_dieu_kien_khac_id = 1
    ),
    dk_khac_eval AS (
        SELECT d.PHAM_NHAN_ID,
               d.NGAY_XET,
               CASE
                 WHEN (UPPER(NVL(d.AN_PHAT, '')) LIKE u'%CHUNG TH\00c2N%' OR UPPER(NVL(d.AN_PHAT, '')) LIKE u'%CHUNG THAN%')
                      AND NOT (UPPER(NVL(d.AN_PHAT, '')) LIKE u'%GI\1ea2M XU\1ed0NG%')
                 THEN 0
                 ELSE 1
               END AS dk1_muc_an_ko_chung_than,
               CASE WHEN (NVL(d.so_tien_an, 0) + NVL(d.ll_so_tien_an, 0)) = 0 THEN 1 ELSE 0 END AS dk2_tien_an_0,
               CASE
                 WHEN d.td_chuong <> u'13' THEN 1
                 WHEN d.muc_an_so_nam IS NOT NULL AND d.muc_an_so_nam <= 10 THEN 1
                 ELSE 0
               END AS dk3_anqg_thi_muc_an_le10,
               -- dk4: DM_TOI_DANHS.TD_CHUONG + TD_MA (không LIKE TD_TEN). C??p gi?t ? VW_BAO_CAO_DX_THONG_KE flg_cuop_giat; mua bán MT ? flg_mua_ban_ma_tuy; v?n chuy?n MT = TD_MA các t?i ch.20 có TD_TEN ch?a "v?n chuy?n" (DM QLPN).
               CASE
                 WHEN (NOT (
                        (d.td_chuong IS NULL OR d.td_chuong = u'16')
                        AND d.td_ma IN (u'136', u'136X', u'136Y', u'1171')
                      )
                      AND (d.td_chuong <> u'20'
                           OR (NOT (
                                 (d.td_chuong IS NULL OR d.td_chuong = u'20')
                                 AND d.td_ma IN (
                                   u'194J', u'196M', u'196L', u'196G', u'196H', u'196K', u'196I', u'196C', u'195C', u'194C',
                                   u'194I', u'194F', u'196', u'194G', u'194E', u'194', u'1254J', u'1254G', u'1254H', u'1253C',
                                   u'1251', u'1254', u'1253'
                                 )
                               )
                               AND NOT (
                                 (d.td_chuong IS NULL OR d.td_chuong = u'20')
                                 AND d.td_ma IN (
                                   u'194B', u'194F', u'1253', u'1254E', u'194E', u'195', u'1254', u'196', u'194H', u'194',
                                   u'1250', u'195B', u'196B', u'1254F', u'1253B'
                                 )
                               ))))
                 THEN 1
                 WHEN REGEXP_COUNT(NVL(d.toi_csv, ''), '[0-9]+') < 2
                      AND NVL(d.muc_an_so_nam, 999) < 7
                 THEN 1
                 ELSE 0
               END AS dk4_cuop_giat_ma_tuy,
               -- M?c 5 "?i?u ki?n khác": d??i 18 tu?i ? m?c án < 3 n?m; t? 18 tr? lên ? ch?a t?ng ???c gi?m án (gi?m = 0).
               -- Khác BR1 (luôn b?t, ? br1_eval) — BR1 yêu c?u ?Ã gi?m cho t?i nghiêm tr?ng+, m?c 5 yêu c?u CH?A gi?m cho ng??i 18+.
               CASE
                 WHEN d.is_duoi18 = 1 THEN
                   CASE WHEN d.muc_an_so_nam IS NOT NULL AND d.muc_an_so_nam < 3 THEN 1 ELSE 0 END
                 ELSE
                   CASE WHEN NVL(d.so_lan_giam, 0) = 0 THEN 1 ELSE 0 END
               END AS dk5_tuoi_hoac_chua_giam,
               CASE WHEN d.da_bi_loai_truoc = 0 THEN 1 ELSE 0 END AS dk6_chua_bi_loai
        FROM dk_khac d
    ),
    dk_khac_mapped AS (
        SELECT /*+ MATERIALIZE */ PHAM_NHAN_ID,
               NGAY_XET,
               CASE WHEN dk1_muc_an_ko_chung_than = 1 AND dk2_tien_an_0 = 1 AND dk3_anqg_thi_muc_an_le10 = 1
                         AND dk4_cuop_giat_ma_tuy = 1 AND dk5_tuoi_hoac_chua_giam = 1 AND dk6_chua_bi_loai = 1
                    THEN 1 ELSE 0 END AS du_dieu_kien_khac
        FROM dk_khac_eval
    ),
    -- T?p PN ?ã pass filter dk_tg / dk_xl / dk_khac.
    -- Dùng làm ngu?n bán-join cho hpbs (thu nh? t? pn_id_set 194K xu?ng t?p này).
    pn_dk_filtered AS (
        SELECT /*+ MATERIALIZE */ w.PHAM_NHAN_ID
        FROM pn_vw w
        LEFT JOIN dk_tg_mapped  dktg ON dktg.PHAM_NHAN_ID = w.PHAM_NHAN_ID AND dktg.NGAY_XET = w.NGAY_XET
        LEFT JOIN dk_xl_mapped  dkxl ON dkxl.PHAM_NHAN_ID = w.PHAM_NHAN_ID AND dkxl.NGAY_XET = w.NGAY_XET
        LEFT JOIN dk_khac_mapped dkk ON dkk.PHAM_NHAN_ID  = w.PHAM_NHAN_ID AND dkk.NGAY_XET  = w.NGAY_XET
        JOIN br1_eval br1 ON br1.PHAM_NHAN_ID = w.PHAM_NHAN_ID
        WHERE
          br1.dat_br1 = 1
          AND (p_dieu_kien_thoi_gian_id IS NULL
           OR (p_dieu_kien_thoi_gian_id = 1 AND dktg.dieu_kien_thoi_gian_id IN (1, 2))
           OR (p_dieu_kien_thoi_gian_id = 2 AND dktg.dieu_kien_thoi_gian_id = 1)
           OR (p_dieu_kien_thoi_gian_id = 3 AND dktg.dieu_kien_thoi_gian_id = 2)
           OR (p_dieu_kien_thoi_gian_id = 4 AND dktg.dieu_kien_thoi_gian_id = 3))
          AND (p_dieu_kien_xep_loai_id IS NULL OR p_dieu_kien_xep_loai_id = 0
               OR (p_dieu_kien_xep_loai_id = 1 AND dkxl.dieu_kien_xep_loai_id = 2)
               OR (p_dieu_kien_xep_loai_id = 2 AND dkxl.dieu_kien_xep_loai_id = 3))
          AND (p_dieu_kien_khac_id IS NULL OR p_dieu_kien_khac_id = 0
               OR (p_dieu_kien_khac_id = 1 AND dkk.DU_DIEU_KIEN_KHAC = 1))
    ),
    -- HPBS: không xét C?p d??ng, Nuôi d??ng, Án phí (p_xong_hpbs_tien)
    -- Dùng pn_dk_filtered thay pn_id_set ? gi?m s? dòng scan PN_HINH_PHAT_BO_SUNGS
    dm_hpbs_ko_xet AS (
        SELECT dm.ID AS hpbs_hinh_phat_id
        FROM DM_HINH_PHAT_BO_SUNGS dm
        WHERE NVL(dm.IS_DELETED, 0) = 0
          AND dm.HPBS_MA IN ('232', '233', '250', '251', '252', '260', '261', '262', '263', '237')
    ),
    hpbs_rows AS (
        SELECT hp.HPBS_MA_PHAM_NHAN AS pn_id,
               hp.ID AS hpbs_id,
               hp.HPBS_HINH_PHAT AS hpbs_hinh_phat_id,
               NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0) AS tong_tien_con_lai
        FROM PN_HINH_PHAT_BO_SUNGS hp
        WHERE (NVL(p_xong_hpbs_tien, 0) = 1 OR NVL(p_da_thuc_hien_xong_hpbs, 0) = 1)
          AND NVL(hp.IS_DELETED, 0) = 0
          AND EXISTS (SELECT 1 FROM pn_dk_filtered s WHERE s.PHAM_NHAN_ID = hp.HPBS_MA_PHAM_NHAN)
    ),
    hpbs_cat AS (
        SELECT r.*,
               CASE WHEN d.hpbs_hinh_phat_id IS NOT NULL
                    THEN 'KO_XET'
                    ELSE 'TIEN_KHAC'
               END AS hpbs_group,
               CASE WHEN NVL(r.tong_tien_con_lai, 0) = 0 THEN 1 ELSE 0 END AS is_done
        FROM hpbs_rows r
        LEFT JOIN dm_hpbs_ko_xet d ON d.hpbs_hinh_phat_id = r.hpbs_hinh_phat_id
    ),
    hpbs_agg_ko_nvds AS (
        SELECT pn_id,
               SUM(CASE WHEN hpbs_group <> 'KO_XET' THEN 1 ELSE 0 END) AS so_hpbs_xet,
               SUM(CASE WHEN hpbs_group <> 'KO_XET' AND is_done = 1 THEN 1 ELSE 0 END) AS so_hpbs_done
        FROM hpbs_cat
        GROUP BY pn_id
    ),
    hpbs_agg_all AS (
        SELECT pn_id,
               COUNT(*) AS so_hpbs_xet,
               SUM(CASE WHEN is_done = 1 THEN 1 ELSE 0 END) AS so_hpbs_done
        FROM hpbs_cat
        GROUP BY pn_id
    ),
    -- T?p PN cu?i sau khi áp thêm p_xong_hpbs_tien và p_noi_cu_tru_ro_rang:
    -- Ch? t?p này ???c dùng trong pn_tg_hien_thi và làm driving table final SELECT.
    pn_id_filtered AS (
        SELECT /*+ MATERIALIZE */ f.PHAM_NHAN_ID
        FROM pn_dk_filtered f
        JOIN pn_vw w ON w.PHAM_NHAN_ID = f.PHAM_NHAN_ID
        LEFT JOIN hpbs_agg_ko_nvds hko ON hko.pn_id = f.PHAM_NHAN_ID
        LEFT JOIN hpbs_agg_all hall ON hall.pn_id = f.PHAM_NHAN_ID
        LEFT JOIN nghien_mt nm ON nm.PHAM_NHAN_ID = f.PHAM_NHAN_ID
        WHERE
          (p_xong_hpbs_tien IS NULL OR p_xong_hpbs_tien <> 1
           OR (NVL(hko.so_hpbs_xet, 0) > 0 AND NVL(hko.so_hpbs_done, 0) = hko.so_hpbs_xet))
          AND (p_noi_cu_tru_ro_rang IS NULL OR p_noi_cu_tru_ro_rang <> 1
               OR (w.NOI_THA_VE_CU_TRU IS NOT NULL))
          AND (p_nghien_ma_tuy_id IS NULL
               OR (p_nghien_ma_tuy_id = 1 AND nm.PHAM_NHAN_ID IS NOT NULL)
               OR (p_nghien_ma_tuy_id = 2 AND nm.PHAM_NHAN_ID IS NULL))
          AND (p_da_thuc_hien_xong_hpbs IS NULL OR p_da_thuc_hien_xong_hpbs <> 1
               OR (NVL(hall.so_hpbs_xet, 0) > 0 AND NVL(hall.so_hpbs_done, 0) = hall.so_hpbs_xet))
    ),
    -- Th?i gian ?ã CH / còn l?i: ??c t? cache (refresh b?ng SP_REFRESH_PN_TCDK_CACHE)
    pn_tg_hien_thi AS (
        SELECT x.PHAM_NHAN_ID,
               c.TG_DA_GIAM,
               NVL(c.TG_CHAP_HANH, u'') AS tg_chap_hanh,
               NVL(c.TG_CON_LAI,   u'') AS tg_con_lai
        FROM pn_id_filtered x
        LEFT JOIN QLPN.PN_TG_HIEN_THI_CACHE c
            ON c.PHAM_NHAN_ID = x.PHAM_NHAN_ID
           AND TRUNC(c.NGAY_XET) = TRUNC(v_den_ngay)
    ),
    -- T?p ?ã l?c ?? (ch?a g?i FN HPBS/GHI_CHU — ch? trên trang k?t qu?)
    filtered_core AS (
        SELECT f.PHAM_NHAN_ID,
               w.HO_TEN,
               w.HO_TEN_ORDER,
               w.NGAY_SINH,
               w.NAM_SINH,
               w.GIOI_TINH_ID,
               w.GIOI_TINH,
               w.NOI_THUONG_TRU_DAY_DU,
               w.NOI_THA_VE_CU_TRU,
               w.TOI_DANH,
               w.AN_PHAT,
               w.SO_TIEN_AN,
               w.NGAY_HET_AN,
               w.NGAY_DEN_TRAI,
               w.PHAN_DOI_ID,
               w.PHAN_DOI,
               w.PHAN_TRAI,
               w.NGAY_BAT_AN_PHAT,
               w.tha_co_dieu_kien_id,
               w.so_quyet_dinh,
               w.GHI_CHU_RIENG,
               w.TINH_THANH_THUONG_TRU_MA,
               w.NGAY_XET,
               NVL(ta.so_tien_an, 0) AS SO_TIEN_AN_COUNT,
               ptg.tg_da_giam,
               ptg.tg_chap_hanh,
               ptg.tg_con_lai,
               ns.ngay_sinh_date,
               ns.nam_sinh AS ns_nam_sinh
        FROM pn_id_filtered f
        JOIN pn_vw w ON w.PHAM_NHAN_ID = f.PHAM_NHAN_ID
        LEFT JOIN pn_tg_hien_thi ptg ON ptg.PHAM_NHAN_ID = f.PHAM_NHAN_ID
        LEFT JOIN pn_nam_sinh ns ON ns.PHAM_NHAN_ID = f.PHAM_NHAN_ID AND TRUNC(ns.NGAY_XET) = TRUNC(w.NGAY_XET)
        LEFT JOIN ta_agg ta ON ta.pn_id = f.PHAM_NHAN_ID
    ),
    with_count AS (
        SELECT fc.*,
               COUNT(*) OVER() AS TOTAL_COUNT
        FROM filtered_core fc
    ),
    paged AS (
        SELECT *
        FROM with_count wc
        ORDER BY
            CASE WHEN p_sort IS NOT NULL
                 THEN wc.TINH_THANH_THUONG_TRU_MA END ASC NULLS LAST,
            CASE WHEN v_sorting_upper NOT IN ('HOTEN ASC', 'HOTEN DESC', 'NGAYSINH ASC', 'NGAYSINH DESC')
                 THEN 0 ELSE 1 END ASC,
            CASE WHEN v_sorting_upper = 'HOTEN ASC'    THEN wc.HO_TEN_ORDER END ASC NULLS LAST,
            CASE WHEN v_sorting_upper = 'HOTEN DESC'   THEN wc.HO_TEN_ORDER END DESC NULLS LAST,
            CASE WHEN v_sorting_upper = 'NGAYSINH ASC' THEN wc.ngay_sinh_date END ASC NULLS LAST,
            CASE WHEN v_sorting_upper = 'NGAYSINH DESC' THEN wc.ngay_sinh_date END DESC NULLS LAST,
            CASE WHEN v_sorting_upper NOT IN ('HOTEN ASC', 'HOTEN DESC', 'NGAYSINH ASC', 'NGAYSINH DESC')
                 THEN wc.HO_TEN_ORDER END ASC NULLS LAST,
            CASE WHEN v_sorting_upper NOT IN ('HOTEN ASC', 'HOTEN DESC', 'NGAYSINH ASC', 'NGAYSINH DESC')
                 THEN wc.NGAY_XET END DESC NULLS LAST
        OFFSET v_skip ROWS
        FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY
    ),
    -- K?t qu? c?i t?o: ch? aggregate cho PN trên trang hi?n t?i
    ket_qua_cai_tao_agg AS (
        SELECT /*+ MATERIALIZE */
            x.PHAM_NHAN_ID,
            LISTAGG(
                u'N\0103m ' || x.nam || u' ' || x.ky_label || u': ' || NVL(d.XLCT_TEN, u''),
                u'; '
            ) WITHIN GROUP (ORDER BY x.nam, x.sort_order) AS ket_qua_cai_tao
        FROM (
            SELECT k.PHAM_NHAN_ID, k.XEP_LOAI_NAM AS nam, u'Qu\00fd I'   AS ky_label, 1 AS sort_order, k.XEP_LOAI_QUY_I    AS xl_id FROM QLPN.XEP_LOAIS k JOIN paged p ON p.PHAM_NHAN_ID = k.PHAM_NHAN_ID WHERE NVL(k.IS_DELETED,0)=0 AND k.XEP_LOAI_QUY_I    IS NOT NULL
            UNION ALL
            SELECT k.PHAM_NHAN_ID, k.XEP_LOAI_NAM,     u'Qu\00fd II',  2,           k.XEP_LOAI_QUY_II          FROM QLPN.XEP_LOAIS k JOIN paged p ON p.PHAM_NHAN_ID = k.PHAM_NHAN_ID WHERE NVL(k.IS_DELETED,0)=0 AND k.XEP_LOAI_QUY_II   IS NOT NULL
            UNION ALL
            SELECT k.PHAM_NHAN_ID, k.XEP_LOAI_NAM,     u'Qu\00fd III', 3,           k.XEP_LOAI_QUY_III         FROM QLPN.XEP_LOAIS k JOIN paged p ON p.PHAM_NHAN_ID = k.PHAM_NHAN_ID WHERE NVL(k.IS_DELETED,0)=0 AND k.XEP_LOAI_QUY_III  IS NOT NULL
            UNION ALL
            SELECT k.PHAM_NHAN_ID, k.XEP_LOAI_NAM,     u'Qu\00fd IV',  4,           k.XEP_LOAI_QUY_IV          FROM QLPN.XEP_LOAIS k JOIN paged p ON p.PHAM_NHAN_ID = k.PHAM_NHAN_ID WHERE NVL(k.IS_DELETED,0)=0 AND k.XEP_LOAI_QUY_IV   IS NOT NULL
            UNION ALL
            SELECT k.PHAM_NHAN_ID, k.XEP_LOAI_NAM,     u'C\1ea3 n\0103m',  7,           k.XEP_LOAI_CA_NAM          FROM QLPN.XEP_LOAIS k JOIN paged p ON p.PHAM_NHAN_ID = k.PHAM_NHAN_ID WHERE NVL(k.IS_DELETED,0)=0 AND k.XEP_LOAI_CA_NAM   IS NOT NULL
        ) x
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS d ON d.ID = x.xl_id AND NVL(d.IS_DELETED, 0) = 0
        GROUP BY x.PHAM_NHAN_ID
    )
    SELECT
        p.PHAM_NHAN_ID                    AS pham_nhan_id,
        NVL(TRIM(CAST(p.HO_TEN AS VARCHAR2(4000))), '') AS ho_ten,
        CASE
            WHEN p.ngay_sinh_date IS NOT NULL
            THEN TO_CHAR(p.ngay_sinh_date, 'DD/MM/YYYY')
            WHEN p.ns_nam_sinh IS NOT NULL
            THEN TO_CHAR(p.ns_nam_sinh)
            WHEN p.NGAY_SINH IS NOT NULL
            THEN TRIM(CAST(p.NGAY_SINH AS VARCHAR2(100)))
            ELSE NULL
        END                               AS ngay_sinh,
        p.GIOI_TINH_ID AS gioi_tinh_id,
        NVL(TRIM(CAST(p.GIOI_TINH AS VARCHAR2(4000))), '') AS gioi_tinh_name,
        NVL(TRIM(CAST(p.NOI_THUONG_TRU_DAY_DU AS VARCHAR2(4000))), '') AS dia_chi_thuong_tru,
        NVL(TRIM(CAST(p.NOI_THA_VE_CU_TRU AS VARCHAR2(4000))), '') AS NOI_THA_VE_CU_TRU,
        NVL(TRIM(CAST(p.TOI_DANH AS VARCHAR2(4000))), '') AS toi_danh,
        NVL(TRIM(CAST(p.AN_PHAT AS VARCHAR2(4000))), '') AS an_phat,
        NVL(TRIM(CAST(p.SO_TIEN_AN AS VARCHAR2(4000))), '') AS tien_an,
        p.so_tien_an,
        p.tg_da_giam,
        NVL(p.tg_chap_hanh, u'') AS tg_chap_hanh,
        NVL(p.tg_con_lai, u'') AS tg_con_lai,
        p.NGAY_HET_AN                      AS ngay_het_han,
        p.NGAY_DEN_TRAI                    AS ngay_den_trai,
        p.PHAN_DOI_ID                      AS phan_doi_id,
        NVL(TRIM(CAST(p.PHAN_DOI AS VARCHAR2(4000))), '') ||
        CASE WHEN p.PHAN_DOI IS NOT NULL AND p.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
        NVL(TRIM(CAST(p.PHAN_TRAI AS VARCHAR2(4000))), '') AS phan_doi_name,
        p.NGAY_BAT_AN_PHAT                 AS ngay_bat,
        p.PHAM_NHAN_ID                     AS pn_lai_lich_id,
        p.tha_co_dieu_kien_id              AS tha_co_dieu_kien_id,
        NVL(TRIM(CAST(p.so_quyet_dinh AS NVARCHAR2(500))), '') AS so_quyet_dinh,
--        tcdk.TINH_TRANG_ID                 AS tinh_trang_id,                       -- M?I
--        NVL(TRIM(CAST(dmtcdk.TCDK_TEN AS NVARCHAR2(4000))), '') AS tinh_trang_ten, -- M?I (tu? ch?n)
        NVL(CAST(kqct.ket_qua_cai_tao AS NVARCHAR2(4000)), u'') AS ket_qua_cai_tao,
        CAST(NVL(FN_GET_LIET_KE_HPBS(p.PHAM_NHAN_ID), '') AS NVARCHAR2(4000)) AS hpbs,
        CAST(QLPN.FN_GET_LIST_GHI_CHU_RIENG(p.GHI_CHU_RIENG) AS NVARCHAR2(4000)) AS GHI_CHU,
        p.TOTAL_COUNT
    FROM paged p
    LEFT JOIN ket_qua_cai_tao_agg kqct ON kqct.PHAM_NHAN_ID = p.PHAM_NHAN_ID
--    LEFT JOIN (                                                        -- M?I
--        SELECT tc.PHAM_NHAN_ID, tc.ID AS tha_co_dieu_kien_id, tc.TINH_TRANG_ID
--        FROM THA_CO_DIEU_KIENS tc
--        WHERE NVL(tc.IS_DELETED, 0) = 0
--          AND TRUNC(tc.NGAY_XET) = TRUNC(v_den_ngay)
--          --AND (v_ma_trai_giam IS NULL OR tc.<C?T_MÃ_TR?I> = v_ma_trai_giam)
--    ) tcdk ON tcdk.PHAM_NHAN_ID = p.PHAM_NHAN_ID
--    LEFT JOIN DM_THA_CO_DIEU_KIENS dmtcdk ON dmtcdk.ID = tcdk.TINH_TRANG_ID AND NVL(dmtcdk.IS_DELETED, 0) = 0
    ORDER BY
        CASE WHEN p_sort IS NOT NULL
             THEN p.TINH_THANH_THUONG_TRU_MA END ASC NULLS LAST,
        CASE WHEN v_sorting_upper NOT IN ('HOTEN ASC', 'HOTEN DESC', 'NGAYSINH ASC', 'NGAYSINH DESC')
             THEN 0 ELSE 1 END ASC,
        CASE WHEN v_sorting_upper = 'HOTEN ASC'    THEN p.HO_TEN_ORDER END ASC NULLS LAST,
        CASE WHEN v_sorting_upper = 'HOTEN DESC'   THEN p.HO_TEN_ORDER END DESC NULLS LAST,
        CASE WHEN v_sorting_upper = 'NGAYSINH ASC' THEN p.ngay_sinh_date END ASC NULLS LAST,
        CASE WHEN v_sorting_upper = 'NGAYSINH DESC' THEN p.ngay_sinh_date END DESC NULLS LAST,
        CASE WHEN v_sorting_upper NOT IN ('HOTEN ASC', 'HOTEN DESC', 'NGAYSINH ASC', 'NGAYSINH DESC')
             THEN p.HO_TEN_ORDER END ASC NULLS LAST,
        CASE WHEN v_sorting_upper NOT IN ('HOTEN ASC', 'HOTEN DESC', 'NGAYSINH ASC', 'NGAYSINH DESC')
             THEN p.NGAY_XET END DESC NULLS LAST;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ?? ?K tha có ?i?u ki?n: ' || SQLERRM);


-- BEGIN
--   QLPN.SP_GET_DS_DU_DK_THA_CO_DK(
--     p_ma_trai_giam            => NULL,
--     p_dot_tha_id              => NULL,
--     p_dieu_kien_thoi_gian_id  => NULL,
--     p_dieu_kien_xep_loai_id   => NULL,
--     p_dieu_kien_khac_id       => NULL,
--     p_nghien_ma_tuy_id        => NULL,
--     p_muc_an_phat_id          => NULL,
--     p_trang_thai_pn_id        => NULL,
--     p_phan_doi_id             => NULL,
--     p_dia_phuong_cu_tru    => NULL,
--     p_het_an_sau_ngay         => NULL,
--     p_filter_text             => NULL,
--     p_khong_xet_nhieu_toi     => NULL,
--     p_xong_hpbs_tien          => NULL,
--     p_da_thuc_hien_xong_hpbs  => NULL,
--     p_noi_cu_tru_ro_rang      => NULL,
--     p_sort                    => '1',
--     p_SORTING                 => NULL,
--     p_maxresultcount          => 25,
--     p_skipcount               => 0
--   );
-- END;

END ;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_DU_DK_THA_CO_DK_OPTIMIZE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_DU_DK_THA_CO_DK_OPTIMIZE" (
    p_dot_tha_id              IN  NUMBER    DEFAULT NULL,
    p_dieu_kien_thoi_gian_id  IN  NUMBER    DEFAULT NULL,
    p_dieu_kien_xep_loai_id   IN  NUMBER    DEFAULT NULL,
    p_dieu_kien_khac_id       IN  NUMBER    DEFAULT NULL,
    p_nghien_ma_tuy_id        IN  NUMBER    DEFAULT NULL,
    p_muc_an_phat_id          IN  NUMBER    DEFAULT NULL,
    p_trang_thai_pn_id        IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN  NUMBER    DEFAULT NULL,
    p_dia_phuong_cu_tru       IN  NVARCHAR2 DEFAULT NULL,
    p_het_an_sau_ngay         IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_filter_text             IN  NVARCHAR2 DEFAULT NULL,
    p_khong_xet_nhieu_toi     IN  NUMBER    DEFAULT NULL,  -- 1=filter
    p_xong_hpbs_tien          IN  NUMBER    DEFAULT NULL,   -- 1=?ã thi hành xong HPBS ti?n (không xét C?p d??ng, Nuôi d??ng, Án phí); 0/null=ch?n t?t c?
    p_da_thuc_hien_xong_hpbs  IN  NUMBER    DEFAULT NULL,   -- 1=?ã thi hành xong HPBS (n?u có) tính t?t c? các lo?i; 0/null=ch?n t?t c?
    p_noi_cu_tru_ro_rang      IN  NUMBER    DEFAULT NULL,
    p_SORTING      IN  NVARCHAR2    DEFAULT NULL,
    p_maxresultcount          IN  NUMBER    DEFAULT 25,
    p_skipcount               IN  NUMBER    DEFAULT 0
) AS
    v_het_an_sau_ngay DATE;
    v_den_ngay        DATE;   -- ngày xét (PN ?ang ch?p hành án t?i ngày này)
    v_skip            NUMBER;
    v_limit           NUMBER;
    v_dk_tg_id        NUMBER;
    v_dk_xl_id        NUMBER;
    v_filter_like     VARCHAR2(4000);
    v_dp_like         VARCHAR2(4000);
    c1                SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    IF p_filter_text IS NOT NULL AND LENGTH(TRIM(p_filter_text)) > 0 THEN
        v_filter_like := '%' || UPPER(TRIM(TO_CHAR(p_filter_text))) || '%';
    ELSE
        v_filter_like := NULL;
    END IF;
    IF p_dia_phuong_cu_tru IS NOT NULL AND LENGTH(TRIM(p_dia_phuong_cu_tru)) > 0 THEN
        v_dp_like := '%' || UPPER(TRIM(TO_CHAR(p_dia_phuong_cu_tru))) || '%';
    ELSE
        v_dp_like := NULL;
    END IF;
    -- dieuKienThoiGianList: 1=?? th??ng, 2=?? ??c bi?t, 3=Không ??
    v_dk_tg_id := p_dieu_kien_thoi_gian_id;
    -- dieuKienXepLoaiCaiTaoList: 1=Không xét, 2=??, 3=Không ??
    v_dk_xl_id := p_dieu_kien_xep_loai_id;
    IF p_het_an_sau_ngay IS NOT NULL AND TRIM(p_het_an_sau_ngay) <> '' THEN
        v_het_an_sau_ngay := TO_DATE(TRIM(p_het_an_sau_ngay), 'DD/MM/YYYY');
    ELSE
        v_het_an_sau_ngay := NULL;
    END IF;
    -- Ngày xét: l?y t? ??t tha có ?i?u ki?n ?ang m? (IS_DELETED=0, DTCDK_TRANG_THAI=1) - luôn có duy nh?t 1 ??t
    BEGIN
        SELECT TRUNC(dt.DTCDK_NGAY_XET)
        INTO v_den_ngay
        FROM PN_DOT_THA_CO_DIEU_KIENS dt
        WHERE NVL(dt.IS_DELETED, 0) = 0
          AND dt.DTCDK_TRANG_THAI = 1
          AND dt.DTCDK_NGAY_XET IS NOT NULL
          AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_den_ngay := TRUNC(SYSDATE);
        WHEN OTHERS THEN
            v_den_ngay := TRUNC(SYSDATE);
    END;

    OPEN c1 FOR
    WITH
    -- PN ?ang ch?p hành án t?i v_den_ngay: có THA hi?u l?c
    tha_hieu_luc AS (
        SELECT tha.tha_pnlai_lich_id AS pn_id
        FROM PN_THI_HANH_AN tha
        WHERE NVL(tha.is_deleted, 0) = 0
          AND tha.tha_pnlai_lich_id IS NOT NULL
          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) <= v_den_ngay
          AND (tha.tha_ngay_het_han IS NULL OR tha.tha_ngay_het_han >= v_den_ngay)
    ),
    ttpn_duoc_xet AS (
        SELECT t.ID AS tinh_trang_id
        FROM DM_TINH_TRANG_PHAM_NHANS t
        WHERE NVL(t.IS_DELETED, 0) = 0
          AND t.TTPN_MA IN ('111', '112', '113', '114', '141')
    ),
    -- Ngu?n PN: ch? VW_PN_LAI_LICH_CHI_TIET (không ??c PN_LAI_LICHS). DISTINCT n?u join trong view t?o nhi?u dòng cùng PHAM_NHAN_ID.
    pn_vw AS (
        SELECT DISTINCT
            v.PHAM_NHAN_ID,
            v_den_ngay AS NGAY_XET,
            CAST(NULL AS NUMBER) AS tha_co_dieu_kien_id,
            CAST(NULL AS NVARCHAR2(500)) AS so_quyet_dinh,
            v.GHI_CHU_RIENG,
            v.NGAY_SINH,
            v.NAM_SINH,
            v.AN_PHAT,
            v.MUC_AN_ID,
            v.SO_TIEN_AN,
            v.TOI_DANH,
            v.TOI_DANH_ID,
            REPLACE(REPLACE(TRIM(CAST(COALESCE(v.TOI_DANH_ID, v.TOI_DANH) AS VARCHAR2(4000))), '[', ''), ']', '') AS toi_csv,
            v.HO_TEN,
            v.GIOI_TINH_ID,
            v.GIOI_TINH,
            v.NOI_THUONG_TRU_DAY_DU,
            v.NGAY_HET_AN,
            v.PHAN_DOI_ID,
            v.PHAN_DOI,
            v.PHAN_TRAI,
            v.NGAY_BAT_AN_PHAT,
            v.LL_TINH_TRANG_ID,
            v.NOI_THA_VE_CU_TRU,
            v.NOI_THA_VE_CU_TRU_XA,
            v.NOI_THA_VE_CU_TRU_TINH
        FROM VW_PN_LAI_LICH_CHI_TIET v
        INNER JOIN tha_hieu_luc th ON th.pn_id = v.PHAM_NHAN_ID
        WHERE NVL(v.IS_DELETED, 0) = 0
          AND v.LL_TINH_TRANG_ID IN (SELECT x.tinh_trang_id FROM ttpn_duoc_xet x)
    ),
    -- PN nghi?n ma túy (ch? trong pn_vw) ?? l?c p_nghien_ma_tuy_id
    nghien_mt AS (
        SELECT DISTINCT nmt.NMT_PN_LAI_LICH_ID AS PHAM_NHAN_ID
        FROM PN_NGHIEN_MT nmt
        WHERE NVL(nmt.IS_DELETED, 0) = 0
          AND nmt.NMT_PN_LAI_LICH_ID IN (SELECT w.PHAM_NHAN_ID FROM pn_vw w)
    ),
    -- ?i?u ki?n th?i gian (theo b?ng ?K th?i gian): ?? th??ng / ?? ??c bi?t / Ko ??
    -- ?? th??ng: Chung thân gi?m xu?ng >=15 n?m; Còn l?i >=1/2 án
    -- ?? ??c bi?t: ??i t??ng ??c bi?t (công CM, thân nhân, >70, khuy?t t?t, ph? n? nuôi con <36 tháng) - Chung thân >=12 n?m; Còn l?i >=1/3
    -- DM_DIEU_KIEN_THOI_GIANS: 22=??, 23=?? ??c bi?t, 27=?? 1/3, 28=Ko ??, 26=Ko ?? 1/3, 21=Ko ?? ??c bi?t
    gcr_dac_biet_ids AS (
        SELECT g.ID AS gcr_id
        FROM DM_GHI_CHU_RIENGS g
        WHERE NVL(g.IS_DELETED, 0) = 0
          AND (UPPER(NVL(g.GCR_TEN, '')) LIKE '%CÔNG%'
               OR UPPER(NVL(g.GCR_TEN, '')) LIKE '%70%'
               OR UPPER(NVL(g.GCR_TEN, '')) LIKE '%KHUY?T T?T%'
               OR UPPER(NVL(g.GCR_TEN, '')) LIKE '%TÀN T?T%'
               OR (UPPER(NVL(g.GCR_TEN, '')) LIKE '%PH? N?%' AND UPPER(NVL(g.GCR_TEN, '')) LIKE '%CON%')
               OR (UPPER(NVL(g.GCR_TEN, '')) LIKE '%CON%' AND (UPPER(NVL(g.GCR_TEN, '')) LIKE '%36%' OR UPPER(NVL(g.GCR_TEN, '')) LIKE '%24%'))
               OR UPPER(NVL(g.GCR_TEN, '')) LIKE '%LI?T S?%'
               OR UPPER(NVL(g.GCR_TEN, '')) LIKE '%CÁCH M?NG%'
               OR (UPPER(NVL(g.GCR_TEN, '')) LIKE '%THÂN NHÂN%' AND UPPER(NVL(g.GCR_TEN, '')) LIKE '%CÔNG%'))
    ),
    pn_gcr_raw AS (
        SELECT w.PHAM_NHAN_ID,
               w.NGAY_XET,
               REPLACE(REPLACE(TRIM(NVL(w.GHI_CHU_RIENG, '[]')), '[', ''), ']', '') AS csv
        FROM pn_vw w
        WHERE w.GHI_CHU_RIENG IS NOT NULL
    ),
    pn_gcr_ids AS (
        SELECT r.PHAM_NHAN_ID,
               r.NGAY_XET,
               CASE
                 WHEN REGEXP_LIKE(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
                 THEN TO_NUMBER(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)))
               END AS gcr_id
        FROM pn_gcr_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.csv, ',') + 1
          AND PRIOR r.PHAM_NHAN_ID = r.PHAM_NHAN_ID
          AND PRIOR r.NGAY_XET = r.NGAY_XET
          AND PRIOR SYS_GUID() IS NOT NULL
          AND REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL) IS NOT NULL
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
    ),
    -- Ngày/n?m sinh: cùng ngu?n và quy t?c SP_GET_THA_CDK_BAN_GIAO_PN (VW NGAY_SINH, NAM_SINH; [0-9] thay \d)
    pn_nam_sinh AS (
        SELECT w.PHAM_NHAN_ID,
               w.NGAY_XET,
               CASE
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND REGEXP_LIKE(TRIM(CAST(w.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
                 THEN TO_DATE(TRIM(CAST(w.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY')
                 ELSE NULL
               END AS ngay_sinh_date,
               CASE
                 WHEN w.NAM_SINH IS NOT NULL AND w.NAM_SINH > 0 THEN w.NAM_SINH
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND REGEXP_LIKE(TRIM(TO_CHAR(w.NGAY_SINH)), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
                 THEN EXTRACT(YEAR FROM TO_DATE(TRIM(TO_CHAR(w.NGAY_SINH)), 'DD/MM/YYYY'))
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND REGEXP_LIKE(TRIM(TO_CHAR(w.NGAY_SINH)), '^[0-9]{4}$')
                 THEN TO_NUMBER(TRIM(TO_CHAR(w.NGAY_SINH)))
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND LENGTH(TRIM(TO_CHAR(w.NGAY_SINH))) >= 4
                      AND REGEXP_LIKE(SUBSTR(TRIM(TO_CHAR(w.NGAY_SINH)), -4), '^[0-9]{4}$')
                 THEN TO_NUMBER(SUBSTR(TRIM(TO_CHAR(w.NGAY_SINH)), -4))
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND REGEXP_LIKE(TO_CHAR(w.NGAY_SINH), '[0-9]{4}')
                 THEN TO_NUMBER(REGEXP_SUBSTR(TO_CHAR(w.NGAY_SINH), '[0-9]{4}', 1, 1))
                 ELSE NULL
               END AS nam_sinh
        FROM pn_vw w
        WHERE w.NGAY_SINH IS NOT NULL OR (w.NAM_SINH IS NOT NULL AND w.NAM_SINH > 0)
    ),
    pn_duoi18 AS (
        SELECT DISTINCT ns.PHAM_NHAN_ID, ns.NGAY_XET
        FROM pn_nam_sinh ns
        WHERE (ns.ngay_sinh_date IS NOT NULL AND MONTHS_BETWEEN(CAST(ns.NGAY_XET AS DATE), ns.ngay_sinh_date) / 12 < 18)
           OR (ns.nam_sinh IS NOT NULL AND (EXTRACT(YEAR FROM CAST(ns.NGAY_XET AS DATE)) - ns.nam_sinh) < 18)
    ),
    pn_doi_tuong_dac_biet AS (
        SELECT DISTINCT gi.PHAM_NHAN_ID, gi.NGAY_XET
        FROM pn_gcr_ids gi
        INNER JOIN gcr_dac_biet_ids g ON g.gcr_id = gi.gcr_id
        UNION
        SELECT PHAM_NHAN_ID, NGAY_XET FROM pn_duoi18
    ),
    dk_tg AS (
        SELECT w.PHAM_NHAN_ID,
               w.NGAY_XET,
               w.AN_PHAT,
               CASE WHEN (UPPER(NVL(w.AN_PHAT, '')) LIKE u'%CHUNG TH\00c2N%' OR UPPER(NVL(w.AN_PHAT, '')) LIKE u'%CHUNG THAN%')
                     AND UPPER(NVL(w.AN_PHAT, '')) LIKE u'%GI\1ea2M XU\1ed0NG%'
                    THEN 1 ELSE 0 END AS is_chung_than_giam,
               CASE WHEN (UPPER(NVL(w.AN_PHAT, '')) LIKE u'%CHUNG TH\00c2N%' OR UPPER(NVL(w.AN_PHAT, '')) LIKE u'%CHUNG THAN%')
                     AND NOT (UPPER(NVL(w.AN_PHAT, '')) LIKE u'%GI\1ea2M XU\1ed0NG%')
                    THEN 1 ELSE 0 END AS is_chung_than_chua_giam,
               CASE WHEN dt.PHAM_NHAN_ID IS NOT NULL THEN 1 ELSE 0 END AS is_doi_tuong_dac_biet,
               PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_SO_NAM(w.PHAM_NHAN_ID, 15, CAST(w.NGAY_XET AS DATE)) AS dat_15_nam,
               PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_SO_NAM(w.PHAM_NHAN_ID, 12, CAST(w.NGAY_XET AS DATE)) AS dat_12_nam,
               PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_TY_LE(w.PHAM_NHAN_ID, 0.5, CAST(w.NGAY_XET AS DATE)) AS dat_1_2,
               PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_TY_LE(w.PHAM_NHAN_ID, 1/3, CAST(w.NGAY_XET AS DATE)) AS dat_1_3
        FROM pn_vw w
        LEFT JOIN pn_doi_tuong_dac_biet dt ON dt.PHAM_NHAN_ID = w.PHAM_NHAN_ID AND TRUNC(dt.NGAY_XET) = TRUNC(w.NGAY_XET)
    ),
    dk_tg_mapped AS (
        SELECT d.PHAM_NHAN_ID,
               d.NGAY_XET,
               CASE
                 WHEN d.is_chung_than_chua_giam = 1 THEN 3
                 WHEN d.is_doi_tuong_dac_biet = 1
                   AND ((d.is_chung_than_giam = 1 AND d.dat_12_nam = 1)
                        OR (d.is_chung_than_giam = 0 AND d.dat_1_3 = 1))
                 THEN 2
                 WHEN (d.is_chung_than_giam = 1 AND d.dat_15_nam = 1)
                   OR (d.is_chung_than_giam = 0 AND d.dat_1_2 = 1)
                 THEN 1
                 ELSE 3
               END AS dieu_kien_thoi_gian_id
        FROM dk_tg d
    ),
    -- ?i?u ki?n x?p lo?i c?i t?o (theo b?ng ?K x?p lo?i): 1=Ko xét, 2=??, 3=Không ??
    -- S? quý Khá/T?t liên t?c li?n k? >= ng??ng theo m?c án
    cfg_xl_muc_an AS (
        SELECT u'Chung th\00e2n gi\1ea3m xu\1ed1ng t\00f9 c\00f3 th\1eddi h\1ea1n' AS muc_an, 20 AS quy_yc FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 20 - 30 n\0103m', 16 FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 15 - 20 n\0103m', 12 FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 10 - 15 n\0103m', 8 FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 5 - 10 n\0103m', 6 FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 3 - 5 n\0103m', 4 FROM DUAL
        UNION ALL SELECT u'\00c1n d\01b0\1edbi 3 n\0103m', 2 FROM DUAL
    ),
    dk_xl AS (
        SELECT w.PHAM_NHAN_ID,
               w.NGAY_XET,
               FN_GET_MUC_AN_PHAT_DAC_XA(w.AN_PHAT) AS muc_an,
               cfg.quy_yc,
               NVL(FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC_LIEN_KE(w.PHAM_NHAN_ID, CAST(w.NGAY_XET AS DATE)), 0) AS quy_lien_ke
        FROM pn_vw w
        LEFT JOIN cfg_xl_muc_an cfg ON TRIM(NVL(cfg.muc_an, ' ')) = TRIM(NVL(FN_GET_MUC_AN_PHAT_DAC_XA(w.AN_PHAT), ' '))
    ),
    dk_xl_mapped AS (
        SELECT d.PHAM_NHAN_ID,
               d.NGAY_XET,
               CASE
                 WHEN d.quy_yc IS NULL THEN 1
                 WHEN d.quy_lien_ke >= d.quy_yc THEN 2
                 ELSE 3
               END AS dieu_kien_xep_loai_id
        FROM dk_xl d
    ),
    -- ?i?u ki?n khác (Xét thêm ?K khác): 6 ?i?u ki?n ph?i th?a t?t c?. p_dieu_kien_khac_id: null=T?t c?, 1=Không xét, 2=Xét thêm
    ta_agg AS (
        SELECT pta.PNTA_LAI_LICH_ID AS pn_id, COUNT(DISTINCT pta.ID) AS so_tien_an
        FROM PN_TIEN_AN pta
        WHERE NVL(pta.IS_DELETED, 0) = 0
          AND pta.PNTA_LAI_LICH_ID IN (SELECT w.PHAM_NHAN_ID FROM pn_vw w)
        GROUP BY pta.PNTA_LAI_LICH_ID
    ),
    -- Chu?i id t?i (VW): COALESCE(TOI_DANH_ID, TOI_DANH), b? ngo?c — dùng th?ng nh?t cho join DM_TOI_DANHS và REGEXP_COUNT (tránh ORA-01722)
    pn_toi_csv AS (
        SELECT w.PHAM_NHAN_ID,
               w.toi_csv
        FROM pn_vw w
    ),
    toi_danh_first AS (
        SELECT p.PHAM_NHAN_ID,
               CASE
                 WHEN REGEXP_LIKE(REGEXP_SUBSTR(p.toi_csv, '[0-9]+', 1, 1), '^[0-9]+$')
                 THEN TO_NUMBER(REGEXP_SUBSTR(p.toi_csv, '[0-9]+', 1, 1))
               END AS toi_danh_id
        FROM pn_toi_csv p
    ),
    pn_bi_loai_truoc AS (
        SELECT DISTINCT tc.PHAM_NHAN_ID
        FROM THA_CO_DIEU_KIENS tc
        WHERE NVL(tc.IS_DELETED, 0) = 0
          AND tc.TINH_TRANG_ID IN (1, 4, 5, 6)
          AND tc.PHAM_NHAN_ID IN (SELECT w.PHAM_NHAN_ID FROM pn_vw w)
    ),
    dk_khac AS (
        SELECT w.PHAM_NHAN_ID,
               w.NGAY_XET,
               w.AN_PHAT,
               w.toi_csv,
               w.MUC_AN_ID,
               dm.TD_CHUONG AS td_chuong,
               dm.TD_MA AS td_ma,
               NVL(FN_PARSE_THOI_GIAN_TEXT(w.AN_PHAT, 'NAM'), 0) +
                 NVL(FN_PARSE_THOI_GIAN_TEXT(w.AN_PHAT, 'THANG'), 0)/12 +
                 NVL(FN_PARSE_THOI_GIAN_TEXT(w.AN_PHAT, 'NGAY'), 0)/365 AS muc_an_so_nam,
               NVL(ta.so_tien_an, 0) AS so_tien_an,
               CASE
                 WHEN REGEXP_LIKE(REGEXP_SUBSTR(TRIM(NVL(TO_CHAR(w.SO_TIEN_AN), '')), '^[0-9]+', 1, 1), '^[0-9]+$')
                 THEN TO_NUMBER(REGEXP_SUBSTR(TRIM(NVL(TO_CHAR(w.SO_TIEN_AN), '')), '^[0-9]+', 1, 1))
                 ELSE 0
               END AS ll_so_tien_an,
               NVL(PKG_TINH_AN.FN_TINH_SO_LAN_GIAM_AN(w.PHAM_NHAN_ID), 0) AS so_lan_giam,
               CASE WHEN du18.PHAM_NHAN_ID IS NOT NULL THEN 1 ELSE 0 END AS is_duoi18,
               CASE WHEN ploai.PHAM_NHAN_ID IS NOT NULL THEN 1 ELSE 0 END AS da_bi_loai_truoc
        FROM pn_vw w
        LEFT JOIN ta_agg ta ON ta.pn_id = w.PHAM_NHAN_ID
        LEFT JOIN toi_danh_first tdf ON tdf.PHAM_NHAN_ID = w.PHAM_NHAN_ID
        LEFT JOIN DM_TOI_DANHS dm ON dm.ID = tdf.toi_danh_id AND NVL(dm.IS_DELETED, 0) = 0
        LEFT JOIN pn_duoi18 du18 ON du18.PHAM_NHAN_ID = w.PHAM_NHAN_ID AND TRUNC(du18.NGAY_XET) = TRUNC(w.NGAY_XET)
        LEFT JOIN pn_bi_loai_truoc ploai ON ploai.PHAM_NHAN_ID = w.PHAM_NHAN_ID
    ),
    dk_khac_eval AS (
        SELECT d.PHAM_NHAN_ID,
               d.NGAY_XET,
               CASE
                 WHEN (UPPER(NVL(d.AN_PHAT, '')) LIKE u'%CHUNG TH\00c2N%' OR UPPER(NVL(d.AN_PHAT, '')) LIKE u'%CHUNG THAN%')
                      AND NOT (UPPER(NVL(d.AN_PHAT, '')) LIKE u'%GI\1ea2M XU\1ed0NG%')
                 THEN 0
                 ELSE 1
               END AS dk1_muc_an_ko_chung_than,
               CASE WHEN (NVL(d.so_tien_an, 0) + NVL(d.ll_so_tien_an, 0)) = 0 THEN 1 ELSE 0 END AS dk2_tien_an_0,
               CASE
                 WHEN TRIM(NVL(TO_CHAR(d.td_chuong), '')) <> '13' THEN 1
                 WHEN d.muc_an_so_nam IS NOT NULL AND d.muc_an_so_nam <= 10 THEN 1
                 ELSE 0
               END AS dk3_anqg_thi_muc_an_le10,
               -- dk4: DM_TOI_DANHS.TD_CHUONG + TD_MA (không LIKE TD_TEN). C??p gi?t ? VW_BAO_CAO_DX_THONG_KE flg_cuop_giat; mua bán MT ? flg_mua_ban_ma_tuy; v?n chuy?n MT = TD_MA các t?i ch.20 có TD_TEN ch?a "v?n chuy?n" (DM QLPN).
               CASE
                 WHEN (NOT (
                        (d.td_chuong IS NULL OR TRIM(NVL(TO_CHAR(d.td_chuong), '')) = '16')
                        AND UPPER(TRIM(NVL(TO_CHAR(d.td_ma), ''))) IN ('136', '136X', '136Y', '1171')
                      )
                      AND (TRIM(NVL(TO_CHAR(d.td_chuong), '')) <> '20'
                           OR (NOT (
                                 (d.td_chuong IS NULL OR TRIM(NVL(TO_CHAR(d.td_chuong), '')) = '20')
                                 AND UPPER(TRIM(NVL(TO_CHAR(d.td_ma), ''))) IN (
                                   '194J', '196M', '196L', '196G', '196H', '196K', '196I', '196C', '195C', '194C',
                                   '194I', '194F', '196', '194G', '194E', '194', '1254J', '1254G', '1254H', '1253C',
                                   '1251', '1254', '1253'
                                 )
                               )
                               AND NOT (
                                 (d.td_chuong IS NULL OR TRIM(NVL(TO_CHAR(d.td_chuong), '')) = '20')
                                 AND UPPER(TRIM(NVL(TO_CHAR(d.td_ma), ''))) IN (
                                   '194B', '194F', '1253', '1254E', '194E', '195', '1254', '196', '194H', '194',
                                   '1250', '195B', '196B', '1254F', '1253B'
                                 )
                               ))))
                 THEN 1
                 WHEN REGEXP_COUNT(NVL(d.toi_csv, ''), '[0-9]+') < 2
                      AND NVL(d.muc_an_so_nam, 999) < 7
                 THEN 1
                 ELSE 0
               END AS dk4_cuop_giat_ma_tuy,
               -- T?i nghiêm tr?ng, r?t nghiêm tr?ng, ??c bi?t nghiêm tr?ng (muc_an >= 3 n?m): ph?i ?ã ???c gi?m án
               CASE
                 WHEN NVL(d.muc_an_so_nam, 999) < 3 THEN 1
                 WHEN NVL(d.so_lan_giam, 0) > 0 THEN 1
                 ELSE 0
               END AS dk5_tuoi_hoac_chua_giam,
               CASE WHEN d.da_bi_loai_truoc = 0 THEN 1 ELSE 0 END AS dk6_chua_bi_loai
        FROM dk_khac d
    ),
    dk_khac_mapped AS (
        SELECT PHAM_NHAN_ID,
               NGAY_XET,
               CASE WHEN dk1_muc_an_ko_chung_than = 1 AND dk2_tien_an_0 = 1 AND dk3_anqg_thi_muc_an_le10 = 1
                         AND dk4_cuop_giat_ma_tuy = 1 AND dk5_tuoi_hoac_chua_giam = 1 AND dk6_chua_bi_loai = 1
                    THEN 1 ELSE 0 END AS du_dieu_kien_khac
        FROM dk_khac_eval
    ),
    -- HPBS: không xét C?p d??ng, Nuôi d??ng, Án phí (p_xong_hpbs_tien)
    dm_hpbs_ko_xet AS (
        SELECT dm.ID AS hpbs_hinh_phat_id
        FROM DM_HINH_PHAT_BO_SUNGS dm
        WHERE NVL(dm.IS_DELETED, 0) = 0
          AND dm.HPBS_MA IN ('232', '233', '250', '251', '252', '260', '261', '262', '263', '237')
    ),
    hpbs_rows AS (
        SELECT hp.HPBS_MA_PHAM_NHAN AS pn_id,
               hp.ID AS hpbs_id,
               hp.HPBS_HINH_PHAT AS hpbs_hinh_phat_id,
               NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0) AS tong_tien_con_lai
        FROM PN_HINH_PHAT_BO_SUNGS hp
        WHERE NVL(hp.IS_DELETED, 0) = 0
          AND hp.HPBS_MA_PHAM_NHAN IN (SELECT w.PHAM_NHAN_ID FROM pn_vw w)
    ),
    hpbs_cat AS (
        SELECT r.*,
               CASE WHEN d.hpbs_hinh_phat_id IS NOT NULL
                    THEN 'KO_XET'
                    ELSE 'TIEN_KHAC'
               END AS hpbs_group,
               CASE WHEN NVL(r.tong_tien_con_lai, 0) = 0 THEN 1 ELSE 0 END AS is_done
        FROM hpbs_rows r
        LEFT JOIN dm_hpbs_ko_xet d ON d.hpbs_hinh_phat_id = r.hpbs_hinh_phat_id
    ),
    hpbs_agg_ko_nvds AS (
        SELECT pn_id,
               SUM(CASE WHEN hpbs_group <> 'KO_XET' THEN 1 ELSE 0 END) AS so_hpbs_xet,
               SUM(CASE WHEN hpbs_group <> 'KO_XET' AND is_done = 1 THEN 1 ELSE 0 END) AS so_hpbs_done
        FROM hpbs_cat
        GROUP BY pn_id
    ),
    hpbs_agg_all AS (
        SELECT pn_id,
               COUNT(*) AS so_hpbs_xet,
               SUM(CASE WHEN is_done = 1 THEN 1 ELSE 0 END) AS so_hpbs_done
        FROM hpbs_cat
        GROUP BY pn_id
    )
    SELECT
        w.PHAM_NHAN_ID                    AS pham_nhan_id,
        NVL(TRIM(CAST(w.HO_TEN AS VARCHAR2(4000))), '') AS ho_ten,
        CASE
            WHEN w.NGAY_SINH IS NOT NULL AND REGEXP_LIKE(TRIM(CAST(w.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(CAST(w.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN w.NAM_SINH IS NOT NULL AND w.NAM_SINH > 0 THEN TO_CHAR(w.NAM_SINH)
            WHEN w.NGAY_SINH IS NOT NULL THEN TRIM(CAST(w.NGAY_SINH AS VARCHAR2(100)))
            ELSE NULL
        END                               AS ngay_sinh,
        w.GIOI_TINH_ID AS gioi_tinh_id,
        NVL(TRIM(CAST(w.GIOI_TINH AS VARCHAR2(4000))), '') AS gioi_tinh_name,
        NVL(TRIM(CAST(w.NOI_THUONG_TRU_DAY_DU AS VARCHAR2(4000))), '') AS dia_chi_thuong_tru,
        NVL(TRIM(CAST(w.TOI_DANH AS VARCHAR2(4000))), '') AS toi_danh,
        NVL(TRIM(CAST(w.AN_PHAT AS VARCHAR2(4000))), '') AS an_phat,
        NVL(TRIM(CAST(w.SO_TIEN_AN AS VARCHAR2(4000))), '') AS tien_an,
        (SELECT CASE
                    WHEN NULLIF(TRIM(CAST(x.g AS VARCHAR2(100))), '0') IS NULL
                    THEN u'Kh\00f4ng'
                    ELSE CAST(x.g AS NVARCHAR2(2000))
                END
           FROM (SELECT PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(w.PHAM_NHAN_ID) AS g FROM DUAL) x
        )                                 AS tg_da_giam,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(w.PHAM_NHAN_ID), u'') AS tg_chap_hanh,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(w.PHAM_NHAN_ID), u'') AS tg_con_lai,
        w.NGAY_HET_AN                      AS ngay_het_han,
        w.PHAN_DOI_ID                      AS phan_doi_id,
        NVL(TRIM(CAST(w.PHAN_DOI AS VARCHAR2(4000))), '') ||
        CASE WHEN w.PHAN_DOI IS NOT NULL AND w.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
        NVL(TRIM(CAST(w.PHAN_TRAI AS VARCHAR2(4000))), '') AS phan_doi_name,
        w.NGAY_BAT_AN_PHAT                 AS ngay_bat,
        w.PHAM_NHAN_ID                     AS pn_lai_lich_id,
        w.tha_co_dieu_kien_id              AS tha_co_dieu_kien_id,
        NVL(TRIM(CAST(w.so_quyet_dinh AS NVARCHAR2(500))), '') AS so_quyet_dinh
    FROM pn_vw w
    LEFT JOIN nghien_mt nm ON nm.PHAM_NHAN_ID = w.PHAM_NHAN_ID
    LEFT JOIN dk_tg_mapped dktg ON dktg.PHAM_NHAN_ID = w.PHAM_NHAN_ID AND TRUNC(dktg.NGAY_XET) = TRUNC(w.NGAY_XET)
    LEFT JOIN dk_xl_mapped dkxl ON dkxl.PHAM_NHAN_ID = w.PHAM_NHAN_ID AND TRUNC(dkxl.NGAY_XET) = TRUNC(w.NGAY_XET)
    LEFT JOIN dk_khac_mapped dkk ON dkk.PHAM_NHAN_ID = w.PHAM_NHAN_ID AND TRUNC(dkk.NGAY_XET) = TRUNC(w.NGAY_XET)
    WHERE 1 = 1
      AND (p_trang_thai_pn_id IS NULL OR w.LL_TINH_TRANG_ID = p_trang_thai_pn_id)
      AND (p_phan_doi_id IS NULL OR w.PHAN_DOI_ID = p_phan_doi_id)
      AND (p_nghien_ma_tuy_id IS NULL
           OR (p_nghien_ma_tuy_id = 1 AND nm.PHAM_NHAN_ID IS NOT NULL)
           OR (p_nghien_ma_tuy_id = -1 AND nm.PHAM_NHAN_ID IS NULL))
      AND (p_dieu_kien_thoi_gian_id IS NULL OR dktg.dieu_kien_thoi_gian_id = v_dk_tg_id)
      -- p_dieu_kien_xep_loai_id: 1=Không xét, 2=??, 3=Không ??
      -- N?u ch?n "Không xét" thì không l?c theo x?p lo?i
      AND (p_dieu_kien_xep_loai_id IS NULL OR p_dieu_kien_xep_loai_id = 1 OR dkxl.dieu_kien_xep_loai_id = v_dk_xl_id)
      AND (p_dieu_kien_khac_id IS NULL OR p_dieu_kien_khac_id = 1 OR (p_dieu_kien_khac_id = 2 AND dkk.DU_DIEU_KIEN_KHAC = 1))
      AND (p_muc_an_phat_id IS NULL OR w.MUC_AN_ID = p_muc_an_phat_id)
      -- L?c ngày h?t án >= ngày nh?p (?ã parse vào v_het_an_sau_ngay ? ??u th? t?c)
      AND (v_het_an_sau_ngay IS NULL OR TRUNC(CAST(w.NGAY_HET_AN AS DATE)) >= v_het_an_sau_ngay)
      AND (v_filter_like IS NULL OR UPPER(CAST(NVL(w.HO_TEN, '') AS VARCHAR2(2000))) LIKE v_filter_like)
      AND (v_dp_like IS NULL
           OR UPPER(NVL(CAST(w.NOI_THA_VE_CU_TRU AS VARCHAR2(4000)), '') || ' ' ||
                     NVL(CAST(w.NOI_THA_VE_CU_TRU_XA AS VARCHAR2(4000)), '') || ' ' ||
                     NVL(CAST(w.NOI_THA_VE_CU_TRU_TINH AS VARCHAR2(4000)), '')) LIKE v_dp_like)
      AND (p_noi_cu_tru_ro_rang IS NULL OR p_noi_cu_tru_ro_rang <> 1
           OR (   (w.NOI_THA_VE_CU_TRU IS NOT NULL AND TRIM(CAST(w.NOI_THA_VE_CU_TRU AS VARCHAR2(4000))) <> '')
               OR (w.NOI_THA_VE_CU_TRU_XA IS NOT NULL OR w.NOI_THA_VE_CU_TRU_TINH IS NOT NULL)
               OR (w.NOI_THUONG_TRU_DAY_DU IS NOT NULL AND TRIM(CAST(w.NOI_THUONG_TRU_DAY_DU AS VARCHAR2(4000))) <> '')))
      AND (p_khong_xet_nhieu_toi IS NULL OR p_khong_xet_nhieu_toi <> 1
           OR REGEXP_COUNT(NVL(w.toi_csv, ''), '[0-9]+') < 2)
      AND (p_xong_hpbs_tien IS NULL OR p_xong_hpbs_tien <> 1
           OR w.PHAM_NHAN_ID NOT IN (SELECT pn_id FROM hpbs_agg_ko_nvds WHERE so_hpbs_xet > 0 AND so_hpbs_done < so_hpbs_xet))
      AND (p_da_thuc_hien_xong_hpbs IS NULL OR p_da_thuc_hien_xong_hpbs <> 1
           OR w.PHAM_NHAN_ID NOT IN (SELECT pn_id FROM hpbs_agg_all WHERE so_hpbs_xet > 0 AND so_hpbs_done < so_hpbs_xet))
    ORDER BY w.HO_TEN, w.NGAY_XET DESC NULLS LAST
    OFFSET v_skip ROWS
    FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ?? ?K tha có ?i?u ki?n: ' || SQLERRM);
END SP_GET_DS_DU_DK_THA_CO_DK_OPTIMIZE;







/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_DU_DK_THA_CO_DK_PRINT_SQL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_DU_DK_THA_CO_DK_PRINT_SQL" (

    p_dot_tha_id              IN  NUMBER    DEFAULT NULL,
    p_dieu_kien_thoi_gian_id  IN  NUMBER    DEFAULT NULL,
    p_dieu_kien_xep_loai_id   IN  NUMBER    DEFAULT NULL,
    p_dieu_kien_khac_id       IN  NUMBER    DEFAULT NULL,
    p_nghien_ma_tuy_id        IN  NUMBER    DEFAULT NULL,
    p_muc_an_phat_id          IN  NUMBER    DEFAULT NULL,
    p_trang_thai_pn_id        IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN  NUMBER    DEFAULT NULL,
    p_dia_phuong_cu_tru       IN  NVARCHAR2 DEFAULT NULL,
    p_het_an_sau_ngay         IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_filter_text             IN  NVARCHAR2 DEFAULT NULL,
    p_khong_xet_nhieu_toi     IN  NUMBER    DEFAULT NULL,  -- 1=filter
    p_xong_hpbs_tien          IN  NUMBER    DEFAULT NULL,   -- 1=?ã thi hành xong HPBS ti?n (không xét C?p d??ng, Nuôi d??ng, Án phí); 0/null=ch?n t?t c?
    p_da_thuc_hien_xong_hpbs  IN  NUMBER    DEFAULT NULL,   -- 1=?ã thi hành xong HPBS (n?u có) tính t?t c? các lo?i; 0/null=ch?n t?t c?
    p_noi_cu_tru_ro_rang      IN  NUMBER    DEFAULT NULL,
    p_SORTING      IN  NVARCHAR2    DEFAULT NULL,
    p_maxresultcount          IN  NUMBER    DEFAULT 25,
    p_skipcount               IN  NUMBER    DEFAULT 0

) AS
v_het_an_sau_ngay DATE;
    v_den_ngay        DATE;   -- ngày xét (PN ?ang ch?p hành án t?i ngày này)
    v_skip            NUMBER;
    v_limit           NUMBER;
    v_dk_tg_id        NUMBER;
    v_dk_xl_id        NUMBER;
    v_filter_like     VARCHAR2(4000);
    v_dp_like         VARCHAR2(4000);
    c1                SYS_REFCURSOR;
    v_sql             CLOB;

    FUNCTION sql_num(p_value IN NUMBER) RETURN VARCHAR2 IS
    BEGIN
        IF p_value IS NULL THEN
            RETURN 'NULL';
        END IF;
        RETURN TO_CHAR(p_value, 'TM9', 'NLS_NUMERIC_CHARACTERS=.,');
    END sql_num;

    FUNCTION sql_str(p_value IN VARCHAR2) RETURN VARCHAR2 IS
    BEGIN
        IF p_value IS NULL THEN
            RETURN 'NULL';
        END IF;
        RETURN '''' || REPLACE(p_value, '''', '''''') || '''';
    END sql_str;

    FUNCTION sql_nstr(p_value IN NVARCHAR2) RETURN VARCHAR2 IS
    BEGIN
        IF p_value IS NULL THEN
            RETURN 'NULL';
        END IF;
        RETURN '''' || REPLACE(TO_CHAR(p_value), '''', '''''') || '''';
    END sql_nstr;

    FUNCTION sql_date(p_value IN DATE) RETURN VARCHAR2 IS
    BEGIN
        IF p_value IS NULL THEN
            RETURN 'NULL';
        END IF;
        RETURN 'TO_DATE(''' || TO_CHAR(p_value, 'DD/MM/YYYY HH24:MI:SS') || ''', ''DD/MM/YYYY HH24:MI:SS'')';
    END sql_date;

    PROCEDURE print_clob(p_clob IN CLOB) IS
        l_pos    PLS_INTEGER := 1;
        l_chunk  VARCHAR2(32767);
        l_len    PLS_INTEGER;
    BEGIN
        IF p_clob IS NULL THEN
            DBMS_OUTPUT.PUT_LINE('NULL');
            RETURN;
        END IF;

        l_len := DBMS_LOB.GETLENGTH(p_clob);
        WHILE l_pos <= l_len LOOP
            l_chunk := DBMS_LOB.SUBSTR(p_clob, 32767, l_pos);
            DBMS_OUTPUT.PUT_LINE(l_chunk);
            l_pos := l_pos + 32767;
        END LOOP;
    END print_clob;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    IF p_filter_text IS NOT NULL AND LENGTH(TRIM(p_filter_text)) > 0 THEN
        v_filter_like := '%' || UPPER(TRIM(TO_CHAR(p_filter_text))) || '%';
    ELSE
        v_filter_like := NULL;
    END IF;
    IF p_dia_phuong_cu_tru IS NOT NULL AND LENGTH(TRIM(p_dia_phuong_cu_tru)) > 0 THEN
        v_dp_like := '%' || UPPER(TRIM(TO_CHAR(p_dia_phuong_cu_tru))) || '%';
    ELSE
        v_dp_like := NULL;
    END IF;
    -- dieuKienThoiGianList: 1=?? th??ng, 2=?? ??c bi?t, 3=Không ??
    v_dk_tg_id := p_dieu_kien_thoi_gian_id;
    -- dieuKienXepLoaiCaiTaoList: 1=Không xét, 2=??, 3=Không ??
    v_dk_xl_id := p_dieu_kien_xep_loai_id;
    IF p_het_an_sau_ngay IS NOT NULL AND TRIM(p_het_an_sau_ngay) <> '' THEN
        v_het_an_sau_ngay := TO_DATE(TRIM(p_het_an_sau_ngay), 'DD/MM/YYYY');
    ELSE
        v_het_an_sau_ngay := NULL;
    END IF;
    -- Ngày xét: l?y t? ??t tha có ?i?u ki?n ?ang m? (IS_DELETED=0, DTCDK_TRANG_THAI=1) - luôn có duy nh?t 1 ??t
    BEGIN
        SELECT TRUNC(dt.DTCDK_NGAY_XET)
        INTO v_den_ngay
        FROM PN_DOT_THA_CO_DIEU_KIENS dt
        WHERE NVL(dt.IS_DELETED, 0) = 0
          AND dt.DTCDK_TRANG_THAI = 1
          AND dt.DTCDK_NGAY_XET IS NOT NULL
          AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_den_ngay := TRUNC(SYSDATE);
        WHEN OTHERS THEN
            v_den_ngay := TRUNC(SYSDATE);
    END;

    v_sql := q'~
    WITH
    -- PN ?ang ch?p hành án t?i __V_DEN_NGAY__: có THA hi?u l?c
    tha_hieu_luc AS (
        SELECT tha.tha_pnlai_lich_id AS pn_id
        FROM PN_THI_HANH_AN tha
        WHERE NVL(tha.is_deleted, 0) = 0
          AND tha.tha_pnlai_lich_id IS NOT NULL
          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
          AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) <= __V_DEN_NGAY__
          AND (tha.tha_ngay_het_han IS NULL OR tha.tha_ngay_het_han >= __V_DEN_NGAY__)
    ),
    ttpn_duoc_xet AS (
        SELECT t.ID AS tinh_trang_id
        FROM DM_TINH_TRANG_PHAM_NHANS t
        WHERE NVL(t.IS_DELETED, 0) = 0
          AND t.TTPN_MA IN ('111', '112', '113', '114', '141')
    ),
    -- Ngu?n PN: ch? VW_PN_LAI_LICH_CHI_TIET (không ??c PN_LAI_LICHS). DISTINCT n?u join trong view t?o nhi?u dòng cùng PHAM_NHAN_ID.
    pn_vw AS (
        SELECT DISTINCT
            v.PHAM_NHAN_ID,
            __V_DEN_NGAY__ AS NGAY_XET,
            CAST(NULL AS NUMBER) AS tha_co_dieu_kien_id,
            CAST(NULL AS NVARCHAR2(500)) AS so_quyet_dinh,
            v.GHI_CHU_RIENG,
            v.NGAY_SINH,
            v.NAM_SINH,
            v.AN_PHAT,
            v.MUC_AN_ID,
            v.SO_TIEN_AN,
            v.TOI_DANH,
            v.TOI_DANH_ID,
            REPLACE(REPLACE(TRIM(CAST(COALESCE(v.TOI_DANH_ID, v.TOI_DANH) AS VARCHAR2(4000))), '[', ''), ']', '') AS toi_csv,
            v.HO_TEN,
            v.GIOI_TINH_ID,
            v.GIOI_TINH,
            v.NOI_THUONG_TRU_DAY_DU,
            v.NGAY_HET_AN,
            v.PHAN_DOI_ID,
            v.PHAN_DOI,
            v.PHAN_TRAI,
            v.NGAY_BAT_AN_PHAT,
            v.LL_TINH_TRANG_ID,
            v.NOI_THA_VE_CU_TRU,
            v.NOI_THA_VE_CU_TRU_XA,
            v.NOI_THA_VE_CU_TRU_TINH
        FROM VW_PN_LAI_LICH_CHI_TIET v
        INNER JOIN tha_hieu_luc th ON th.pn_id = v.PHAM_NHAN_ID
        WHERE NVL(v.IS_DELETED, 0) = 0
          AND v.LL_TINH_TRANG_ID IN (SELECT x.tinh_trang_id FROM ttpn_duoc_xet x)
    ),
    -- PN nghi?n ma túy (ch? trong pn_vw) ?? l?c __P_NGHIEN_MA_TUY_ID__
    nghien_mt AS (
        SELECT DISTINCT nmt.NMT_PN_LAI_LICH_ID AS PHAM_NHAN_ID
        FROM PN_NGHIEN_MT nmt
        WHERE NVL(nmt.IS_DELETED, 0) = 0
          AND nmt.NMT_PN_LAI_LICH_ID IN (SELECT w.PHAM_NHAN_ID FROM pn_vw w)
    ),
    -- ?i?u ki?n th?i gian (theo b?ng ?K th?i gian): ?? th??ng / ?? ??c bi?t / Ko ??
    -- ?? th??ng: Chung thân gi?m xu?ng >=15 n?m; Còn l?i >=1/2 án
    -- ?? ??c bi?t: ??i t??ng ??c bi?t (công CM, thân nhân, >70, khuy?t t?t, ph? n? nuôi con <36 tháng) - Chung thân >=12 n?m; Còn l?i >=1/3
    -- DM_DIEU_KIEN_THOI_GIANS: 22=??, 23=?? ??c bi?t, 27=?? 1/3, 28=Ko ??, 26=Ko ?? 1/3, 21=Ko ?? ??c bi?t
    gcr_dac_biet_ids AS (
        SELECT g.ID AS gcr_id
        FROM DM_GHI_CHU_RIENGS g
        WHERE NVL(g.IS_DELETED, 0) = 0
          AND (UPPER(NVL(g.GCR_TEN, '')) LIKE '%CÔNG%'
               OR UPPER(NVL(g.GCR_TEN, '')) LIKE '%70%'
               OR UPPER(NVL(g.GCR_TEN, '')) LIKE '%KHUY?T T?T%'
               OR UPPER(NVL(g.GCR_TEN, '')) LIKE '%TÀN T?T%'
               OR (UPPER(NVL(g.GCR_TEN, '')) LIKE '%PH? N?%' AND UPPER(NVL(g.GCR_TEN, '')) LIKE '%CON%')
               OR (UPPER(NVL(g.GCR_TEN, '')) LIKE '%CON%' AND (UPPER(NVL(g.GCR_TEN, '')) LIKE '%36%' OR UPPER(NVL(g.GCR_TEN, '')) LIKE '%24%'))
               OR UPPER(NVL(g.GCR_TEN, '')) LIKE '%LI?T S?%'
               OR UPPER(NVL(g.GCR_TEN, '')) LIKE '%CÁCH M?NG%'
               OR (UPPER(NVL(g.GCR_TEN, '')) LIKE '%THÂN NHÂN%' AND UPPER(NVL(g.GCR_TEN, '')) LIKE '%CÔNG%'))
    ),
    pn_gcr_raw AS (
        SELECT w.PHAM_NHAN_ID,
               w.NGAY_XET,
               REPLACE(REPLACE(TRIM(NVL(w.GHI_CHU_RIENG, '[]')), '[', ''), ']', '') AS csv
        FROM pn_vw w
        WHERE w.GHI_CHU_RIENG IS NOT NULL
    ),
    pn_gcr_ids AS (
        SELECT r.PHAM_NHAN_ID,
               r.NGAY_XET,
               CASE
                 WHEN REGEXP_LIKE(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
                 THEN TO_NUMBER(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)))
               END AS gcr_id
        FROM pn_gcr_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.csv, ',') + 1
          AND PRIOR r.PHAM_NHAN_ID = r.PHAM_NHAN_ID
          AND PRIOR r.NGAY_XET = r.NGAY_XET
          AND PRIOR SYS_GUID() IS NOT NULL
          AND REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL) IS NOT NULL
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
    ),
    -- Ngày/n?m sinh: cùng ngu?n và quy t?c SP_GET_THA_CDK_BAN_GIAO_PN (VW NGAY_SINH, NAM_SINH; [0-9] thay \d)
    pn_nam_sinh AS (
        SELECT w.PHAM_NHAN_ID,
               w.NGAY_XET,
               CASE
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND REGEXP_LIKE(TRIM(CAST(w.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
                 THEN TO_DATE(TRIM(CAST(w.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY')
                 ELSE NULL
               END AS ngay_sinh_date,
               CASE
                 WHEN w.NAM_SINH IS NOT NULL AND w.NAM_SINH > 0 THEN w.NAM_SINH
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND REGEXP_LIKE(TRIM(TO_CHAR(w.NGAY_SINH)), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
                 THEN EXTRACT(YEAR FROM TO_DATE(TRIM(TO_CHAR(w.NGAY_SINH)), 'DD/MM/YYYY'))
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND REGEXP_LIKE(TRIM(TO_CHAR(w.NGAY_SINH)), '^[0-9]{4}$')
                 THEN TO_NUMBER(TRIM(TO_CHAR(w.NGAY_SINH)))
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND LENGTH(TRIM(TO_CHAR(w.NGAY_SINH))) >= 4
                      AND REGEXP_LIKE(SUBSTR(TRIM(TO_CHAR(w.NGAY_SINH)), -4), '^[0-9]{4}$')
                 THEN TO_NUMBER(SUBSTR(TRIM(TO_CHAR(w.NGAY_SINH)), -4))
                 WHEN w.NGAY_SINH IS NOT NULL
                      AND REGEXP_LIKE(TO_CHAR(w.NGAY_SINH), '[0-9]{4}')
                 THEN TO_NUMBER(REGEXP_SUBSTR(TO_CHAR(w.NGAY_SINH), '[0-9]{4}', 1, 1))
                 ELSE NULL
               END AS nam_sinh
        FROM pn_vw w
        WHERE w.NGAY_SINH IS NOT NULL OR (w.NAM_SINH IS NOT NULL AND w.NAM_SINH > 0)
    ),
    pn_duoi18 AS (
        SELECT DISTINCT ns.PHAM_NHAN_ID, ns.NGAY_XET
        FROM pn_nam_sinh ns
        WHERE (ns.ngay_sinh_date IS NOT NULL AND MONTHS_BETWEEN(CAST(ns.NGAY_XET AS DATE), ns.ngay_sinh_date) / 12 < 18)
           OR (ns.nam_sinh IS NOT NULL AND (EXTRACT(YEAR FROM CAST(ns.NGAY_XET AS DATE)) - ns.nam_sinh) < 18)
    ),
    pn_doi_tuong_dac_biet AS (
        SELECT DISTINCT gi.PHAM_NHAN_ID, gi.NGAY_XET
        FROM pn_gcr_ids gi
        INNER JOIN gcr_dac_biet_ids g ON g.gcr_id = gi.gcr_id
        UNION
        SELECT PHAM_NHAN_ID, NGAY_XET FROM pn_duoi18
    ),
    dk_tg AS (
        SELECT w.PHAM_NHAN_ID,
               w.NGAY_XET,
               w.AN_PHAT,
               CASE WHEN (UPPER(NVL(w.AN_PHAT, '')) LIKE u'%CHUNG TH\00c2N%' OR UPPER(NVL(w.AN_PHAT, '')) LIKE u'%CHUNG THAN%')
                     AND UPPER(NVL(w.AN_PHAT, '')) LIKE u'%GI\1ea2M XU\1ed0NG%'
                    THEN 1 ELSE 0 END AS is_chung_than_giam,
               CASE WHEN (UPPER(NVL(w.AN_PHAT, '')) LIKE u'%CHUNG TH\00c2N%' OR UPPER(NVL(w.AN_PHAT, '')) LIKE u'%CHUNG THAN%')
                     AND NOT (UPPER(NVL(w.AN_PHAT, '')) LIKE u'%GI\1ea2M XU\1ed0NG%')
                    THEN 1 ELSE 0 END AS is_chung_than_chua_giam,
               CASE WHEN dt.PHAM_NHAN_ID IS NOT NULL THEN 1 ELSE 0 END AS is_doi_tuong_dac_biet,
               PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_SO_NAM(w.PHAM_NHAN_ID, 15, CAST(w.NGAY_XET AS DATE)) AS dat_15_nam,
               PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_SO_NAM(w.PHAM_NHAN_ID, 12, CAST(w.NGAY_XET AS DATE)) AS dat_12_nam,
               PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_TY_LE(w.PHAM_NHAN_ID, 0.5, CAST(w.NGAY_XET AS DATE)) AS dat_1_2,
               PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_TY_LE(w.PHAM_NHAN_ID, 1/3, CAST(w.NGAY_XET AS DATE)) AS dat_1_3
        FROM pn_vw w
        LEFT JOIN pn_doi_tuong_dac_biet dt ON dt.PHAM_NHAN_ID = w.PHAM_NHAN_ID AND TRUNC(dt.NGAY_XET) = TRUNC(w.NGAY_XET)
    ),
    dk_tg_mapped AS (
        SELECT d.PHAM_NHAN_ID,
               d.NGAY_XET,
               CASE
                 WHEN d.is_chung_than_chua_giam = 1 THEN 3
                 WHEN d.is_doi_tuong_dac_biet = 1
                   AND ((d.is_chung_than_giam = 1 AND d.dat_12_nam = 1)
                        OR (d.is_chung_than_giam = 0 AND d.dat_1_3 = 1))
                 THEN 2
                 WHEN (d.is_chung_than_giam = 1 AND d.dat_15_nam = 1)
                   OR (d.is_chung_than_giam = 0 AND d.dat_1_2 = 1)
                 THEN 1
                 ELSE 3
               END AS dieu_kien_thoi_gian_id
        FROM dk_tg d
    ),
    -- ?i?u ki?n x?p lo?i c?i t?o (theo b?ng ?K x?p lo?i): 1=Ko xét, 2=??, 3=Không ??
    -- S? quý Khá/T?t liên t?c li?n k? >= ng??ng theo m?c án
    cfg_xl_muc_an AS (
        SELECT u'Chung th\00e2n gi\1ea3m xu\1ed1ng t\00f9 c\00f3 th\1eddi h\1ea1n' AS muc_an, 20 AS quy_yc FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 20 - 30 n\0103m', 16 FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 15 - 20 n\0103m', 12 FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 10 - 15 n\0103m', 8 FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 5 - 10 n\0103m', 6 FROM DUAL
        UNION ALL SELECT u'\00c1n t\00f9 3 - 5 n\0103m', 4 FROM DUAL
        UNION ALL SELECT u'\00c1n d\01b0\1edbi 3 n\0103m', 2 FROM DUAL
    ),
    dk_xl AS (
        SELECT w.PHAM_NHAN_ID,
               w.NGAY_XET,
               FN_GET_MUC_AN_PHAT_DAC_XA(w.AN_PHAT) AS muc_an,
               cfg.quy_yc,
               NVL(FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC_LIEN_KE(w.PHAM_NHAN_ID, CAST(w.NGAY_XET AS DATE)), 0) AS quy_lien_ke
        FROM pn_vw w
        LEFT JOIN cfg_xl_muc_an cfg ON TRIM(NVL(cfg.muc_an, ' ')) = TRIM(NVL(FN_GET_MUC_AN_PHAT_DAC_XA(w.AN_PHAT), ' '))
    ),
    dk_xl_mapped AS (
        SELECT d.PHAM_NHAN_ID,
               d.NGAY_XET,
               CASE
                 WHEN d.quy_yc IS NULL THEN 1
                 WHEN d.quy_lien_ke >= d.quy_yc THEN 2
                 ELSE 3
               END AS dieu_kien_xep_loai_id
        FROM dk_xl d
    ),
    -- ?i?u ki?n khác (Xét thêm ?K khác): 6 ?i?u ki?n ph?i th?a t?t c?. __P_DIEU_KIEN_KHAC_ID__: null=T?t c?, 1=Không xét, 2=Xét thêm
    ta_agg AS (
        SELECT pta.PNTA_LAI_LICH_ID AS pn_id, COUNT(DISTINCT pta.ID) AS so_tien_an
        FROM PN_TIEN_AN pta
        WHERE NVL(pta.IS_DELETED, 0) = 0
          AND pta.PNTA_LAI_LICH_ID IN (SELECT w.PHAM_NHAN_ID FROM pn_vw w)
        GROUP BY pta.PNTA_LAI_LICH_ID
    ),
    -- Chu?i id t?i (VW): COALESCE(TOI_DANH_ID, TOI_DANH), b? ngo?c — dùng th?ng nh?t cho join DM_TOI_DANHS và REGEXP_COUNT (tránh ORA-01722)
    pn_toi_csv AS (
        SELECT w.PHAM_NHAN_ID,
               w.toi_csv
        FROM pn_vw w
    ),
    toi_danh_first AS (
        SELECT p.PHAM_NHAN_ID,
               CASE
                 WHEN REGEXP_LIKE(REGEXP_SUBSTR(p.toi_csv, '[0-9]+', 1, 1), '^[0-9]+$')
                 THEN TO_NUMBER(REGEXP_SUBSTR(p.toi_csv, '[0-9]+', 1, 1))
               END AS toi_danh_id
        FROM pn_toi_csv p
    ),
    pn_bi_loai_truoc AS (
        SELECT DISTINCT tc.PHAM_NHAN_ID
        FROM THA_CO_DIEU_KIENS tc
        WHERE NVL(tc.IS_DELETED, 0) = 0
          AND tc.TINH_TRANG_ID IN (1, 4, 5, 6)
          AND tc.PHAM_NHAN_ID IN (SELECT w.PHAM_NHAN_ID FROM pn_vw w)
    ),
    dk_khac AS (
        SELECT w.PHAM_NHAN_ID,
               w.NGAY_XET,
               w.AN_PHAT,
               w.toi_csv,
               w.MUC_AN_ID,
               dm.TD_CHUONG AS td_chuong,
               dm.TD_MA AS td_ma,
               NVL(FN_PARSE_THOI_GIAN_TEXT(w.AN_PHAT, 'NAM'), 0) +
                 NVL(FN_PARSE_THOI_GIAN_TEXT(w.AN_PHAT, 'THANG'), 0)/12 +
                 NVL(FN_PARSE_THOI_GIAN_TEXT(w.AN_PHAT, 'NGAY'), 0)/365 AS muc_an_so_nam,
               NVL(ta.so_tien_an, 0) AS so_tien_an,
               CASE
                 WHEN REGEXP_LIKE(REGEXP_SUBSTR(TRIM(NVL(TO_CHAR(w.SO_TIEN_AN), '')), '^[0-9]+', 1, 1), '^[0-9]+$')
                 THEN TO_NUMBER(REGEXP_SUBSTR(TRIM(NVL(TO_CHAR(w.SO_TIEN_AN), '')), '^[0-9]+', 1, 1))
                 ELSE 0
               END AS ll_so_tien_an,
               NVL(PKG_TINH_AN.FN_TINH_SO_LAN_GIAM_AN(w.PHAM_NHAN_ID), 0) AS so_lan_giam,
               CASE WHEN du18.PHAM_NHAN_ID IS NOT NULL THEN 1 ELSE 0 END AS is_duoi18,
               CASE WHEN ploai.PHAM_NHAN_ID IS NOT NULL THEN 1 ELSE 0 END AS da_bi_loai_truoc
        FROM pn_vw w
        LEFT JOIN ta_agg ta ON ta.pn_id = w.PHAM_NHAN_ID
        LEFT JOIN toi_danh_first tdf ON tdf.PHAM_NHAN_ID = w.PHAM_NHAN_ID
        LEFT JOIN DM_TOI_DANHS dm ON dm.ID = tdf.toi_danh_id AND NVL(dm.IS_DELETED, 0) = 0
        LEFT JOIN pn_duoi18 du18 ON du18.PHAM_NHAN_ID = w.PHAM_NHAN_ID AND TRUNC(du18.NGAY_XET) = TRUNC(w.NGAY_XET)
        LEFT JOIN pn_bi_loai_truoc ploai ON ploai.PHAM_NHAN_ID = w.PHAM_NHAN_ID
    ),
    dk_khac_eval AS (
        SELECT d.PHAM_NHAN_ID,
               d.NGAY_XET,
               CASE
                 WHEN (UPPER(NVL(d.AN_PHAT, '')) LIKE u'%CHUNG TH\00c2N%' OR UPPER(NVL(d.AN_PHAT, '')) LIKE u'%CHUNG THAN%')
                      AND NOT (UPPER(NVL(d.AN_PHAT, '')) LIKE u'%GI\1ea2M XU\1ed0NG%')
                 THEN 0
                 ELSE 1
               END AS dk1_muc_an_ko_chung_than,
               CASE WHEN (NVL(d.so_tien_an, 0) + NVL(d.ll_so_tien_an, 0)) = 0 THEN 1 ELSE 0 END AS dk2_tien_an_0,
               CASE
                 WHEN TRIM(NVL(TO_CHAR(d.td_chuong), '')) <> '13' THEN 1
                 WHEN d.muc_an_so_nam IS NOT NULL AND d.muc_an_so_nam <= 10 THEN 1
                 ELSE 0
               END AS dk3_anqg_thi_muc_an_le10,
               -- dk4: DM_TOI_DANHS.TD_CHUONG + TD_MA (không LIKE TD_TEN). C??p gi?t ? VW_BAO_CAO_DX_THONG_KE flg_cuop_giat; mua bán MT ? flg_mua_ban_ma_tuy; v?n chuy?n MT = TD_MA các t?i ch.20 có TD_TEN ch?a "v?n chuy?n" (DM QLPN).
               CASE
                 WHEN (NOT (
                        (d.td_chuong IS NULL OR TRIM(NVL(TO_CHAR(d.td_chuong), '')) = '16')
                        AND UPPER(TRIM(NVL(TO_CHAR(d.td_ma), ''))) IN ('136', '136X', '136Y', '1171')
                      )
                      AND (TRIM(NVL(TO_CHAR(d.td_chuong), '')) <> '20'
                           OR (NOT (
                                 (d.td_chuong IS NULL OR TRIM(NVL(TO_CHAR(d.td_chuong), '')) = '20')
                                 AND UPPER(TRIM(NVL(TO_CHAR(d.td_ma), ''))) IN (
                                   '194J', '196M', '196L', '196G', '196H', '196K', '196I', '196C', '195C', '194C',
                                   '194I', '194F', '196', '194G', '194E', '194', '1254J', '1254G', '1254H', '1253C',
                                   '1251', '1254', '1253'
                                 )
                               )
                               AND NOT (
                                 (d.td_chuong IS NULL OR TRIM(NVL(TO_CHAR(d.td_chuong), '')) = '20')
                                 AND UPPER(TRIM(NVL(TO_CHAR(d.td_ma), ''))) IN (
                                   '194B', '194F', '1253', '1254E', '194E', '195', '1254', '196', '194H', '194',
                                   '1250', '195B', '196B', '1254F', '1253B'
                                 )
                               ))))
                 THEN 1
                 WHEN REGEXP_COUNT(NVL(d.toi_csv, ''), '[0-9]+') < 2
                      AND NVL(d.muc_an_so_nam, 999) < 7
                 THEN 1
                 ELSE 0
               END AS dk4_cuop_giat_ma_tuy,
               -- T?i nghiêm tr?ng, r?t nghiêm tr?ng, ??c bi?t nghiêm tr?ng (muc_an >= 3 n?m): ph?i ?ã ???c gi?m án
               CASE
                 WHEN NVL(d.muc_an_so_nam, 999) < 3 THEN 1
                 WHEN NVL(d.so_lan_giam, 0) > 0 THEN 1
                 ELSE 0
               END AS dk5_tuoi_hoac_chua_giam,
               CASE WHEN d.da_bi_loai_truoc = 0 THEN 1 ELSE 0 END AS dk6_chua_bi_loai
        FROM dk_khac d
    ),
    dk_khac_mapped AS (
        SELECT PHAM_NHAN_ID,
               NGAY_XET,
               CASE WHEN dk1_muc_an_ko_chung_than = 1 AND dk2_tien_an_0 = 1 AND dk3_anqg_thi_muc_an_le10 = 1
                         AND dk4_cuop_giat_ma_tuy = 1 AND dk5_tuoi_hoac_chua_giam = 1 AND dk6_chua_bi_loai = 1
                    THEN 1 ELSE 0 END AS du_dieu_kien_khac
        FROM dk_khac_eval
    ),
    -- HPBS: không xét C?p d??ng, Nuôi d??ng, Án phí (__P_XONG_HPBS_TIEN__)
    dm_hpbs_ko_xet AS (
        SELECT dm.ID AS hpbs_hinh_phat_id
        FROM DM_HINH_PHAT_BO_SUNGS dm
        WHERE NVL(dm.IS_DELETED, 0) = 0
          AND dm.HPBS_MA IN ('232', '233', '250', '251', '252', '260', '261', '262', '263', '237')
    ),
    hpbs_rows AS (
        SELECT hp.HPBS_MA_PHAM_NHAN AS pn_id,
               hp.ID AS hpbs_id,
               hp.HPBS_HINH_PHAT AS hpbs_hinh_phat_id,
               NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0) AS tong_tien_con_lai
        FROM PN_HINH_PHAT_BO_SUNGS hp
        WHERE NVL(hp.IS_DELETED, 0) = 0
          AND hp.HPBS_MA_PHAM_NHAN IN (SELECT w.PHAM_NHAN_ID FROM pn_vw w)
    ),
    hpbs_cat AS (
        SELECT r.*,
               CASE WHEN d.hpbs_hinh_phat_id IS NOT NULL
                    THEN 'KO_XET'
                    ELSE 'TIEN_KHAC'
               END AS hpbs_group,
               CASE WHEN NVL(r.tong_tien_con_lai, 0) = 0 THEN 1 ELSE 0 END AS is_done
        FROM hpbs_rows r
        LEFT JOIN dm_hpbs_ko_xet d ON d.hpbs_hinh_phat_id = r.hpbs_hinh_phat_id
    ),
    hpbs_agg_ko_nvds AS (
        SELECT pn_id,
               SUM(CASE WHEN hpbs_group <> 'KO_XET' THEN 1 ELSE 0 END) AS so_hpbs_xet,
               SUM(CASE WHEN hpbs_group <> 'KO_XET' AND is_done = 1 THEN 1 ELSE 0 END) AS so_hpbs_done
        FROM hpbs_cat
        GROUP BY pn_id
    ),
    hpbs_agg_all AS (
        SELECT pn_id,
               COUNT(*) AS so_hpbs_xet,
               SUM(CASE WHEN is_done = 1 THEN 1 ELSE 0 END) AS so_hpbs_done
        FROM hpbs_cat
        GROUP BY pn_id
    )
    SELECT
        w.PHAM_NHAN_ID                    AS pham_nhan_id,
        NVL(TRIM(CAST(w.HO_TEN AS VARCHAR2(4000))), '') AS ho_ten,
        CASE
            WHEN w.NGAY_SINH IS NOT NULL AND REGEXP_LIKE(TRIM(CAST(w.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(CAST(w.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN w.NAM_SINH IS NOT NULL AND w.NAM_SINH > 0 THEN TO_CHAR(w.NAM_SINH)
            WHEN w.NGAY_SINH IS NOT NULL THEN TRIM(CAST(w.NGAY_SINH AS VARCHAR2(100)))
            ELSE NULL
        END                               AS ngay_sinh,
        w.GIOI_TINH_ID AS gioi_tinh_id,
        NVL(TRIM(CAST(w.GIOI_TINH AS VARCHAR2(4000))), '') AS gioi_tinh_name,
        NVL(TRIM(CAST(w.NOI_THUONG_TRU_DAY_DU AS VARCHAR2(4000))), '') AS dia_chi_thuong_tru,
        NVL(TRIM(CAST(w.TOI_DANH AS VARCHAR2(4000))), '') AS toi_danh,
        NVL(TRIM(CAST(w.AN_PHAT AS VARCHAR2(4000))), '') AS an_phat,
        NVL(TRIM(CAST(w.SO_TIEN_AN AS VARCHAR2(4000))), '') AS tien_an,
        (SELECT CASE
                    WHEN NULLIF(TRIM(CAST(x.g AS VARCHAR2(100))), '0') IS NULL
                    THEN u'Kh\00f4ng'
                    ELSE CAST(x.g AS NVARCHAR2(2000))
                END
           FROM (SELECT PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(w.PHAM_NHAN_ID) AS g FROM DUAL) x
        )                                 AS tg_da_giam,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(w.PHAM_NHAN_ID), u'') AS tg_chap_hanh,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(w.PHAM_NHAN_ID), u'') AS tg_con_lai,
        w.NGAY_HET_AN                      AS ngay_het_han,
        w.PHAN_DOI_ID                      AS phan_doi_id,
        NVL(TRIM(CAST(w.PHAN_DOI AS VARCHAR2(4000))), '') ||
        CASE WHEN w.PHAN_DOI IS NOT NULL AND w.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
        NVL(TRIM(CAST(w.PHAN_TRAI AS VARCHAR2(4000))), '') AS phan_doi_name,
        w.NGAY_BAT_AN_PHAT                 AS ngay_bat,
        w.PHAM_NHAN_ID                     AS pn_lai_lich_id,
        w.tha_co_dieu_kien_id              AS tha_co_dieu_kien_id,
        NVL(TRIM(CAST(w.so_quyet_dinh AS NVARCHAR2(500))), '') AS so_quyet_dinh
    FROM pn_vw w
    LEFT JOIN nghien_mt nm ON nm.PHAM_NHAN_ID = w.PHAM_NHAN_ID
    LEFT JOIN dk_tg_mapped dktg ON dktg.PHAM_NHAN_ID = w.PHAM_NHAN_ID AND TRUNC(dktg.NGAY_XET) = TRUNC(w.NGAY_XET)
    LEFT JOIN dk_xl_mapped dkxl ON dkxl.PHAM_NHAN_ID = w.PHAM_NHAN_ID AND TRUNC(dkxl.NGAY_XET) = TRUNC(w.NGAY_XET)
    LEFT JOIN dk_khac_mapped dkk ON dkk.PHAM_NHAN_ID = w.PHAM_NHAN_ID AND TRUNC(dkk.NGAY_XET) = TRUNC(w.NGAY_XET)
    WHERE 1 = 1
      AND (__P_TRANG_THAI_PN_ID__ IS NULL OR w.LL_TINH_TRANG_ID = __P_TRANG_THAI_PN_ID__)
      AND (__P_PHAN_DOI_ID__ IS NULL OR w.PHAN_DOI_ID = __P_PHAN_DOI_ID__)
      AND (__P_NGHIEN_MA_TUY_ID__ IS NULL
           OR (__P_NGHIEN_MA_TUY_ID__ = 1 AND nm.PHAM_NHAN_ID IS NOT NULL)
           OR (__P_NGHIEN_MA_TUY_ID__ = -1 AND nm.PHAM_NHAN_ID IS NULL))
      AND (__P_DIEU_KIEN_THOI_GIAN_ID__ IS NULL OR dktg.dieu_kien_thoi_gian_id = __V_DK_TG_ID__)
      -- __P_DIEU_KIEN_XEP_LOAI_ID__: 1=Không xét, 2=??, 3=Không ??
      -- N?u ch?n "Không xét" thì không l?c theo x?p lo?i
      AND (__P_DIEU_KIEN_XEP_LOAI_ID__ IS NULL OR __P_DIEU_KIEN_XEP_LOAI_ID__ = 1 OR dkxl.dieu_kien_xep_loai_id = __V_DK_XL_ID__)
      AND (__P_DIEU_KIEN_KHAC_ID__ IS NULL OR __P_DIEU_KIEN_KHAC_ID__ = 1 OR (__P_DIEU_KIEN_KHAC_ID__ = 2 AND dkk.DU_DIEU_KIEN_KHAC = 1))
      AND (__P_MUC_AN_PHAT_ID__ IS NULL OR w.MUC_AN_ID = __P_MUC_AN_PHAT_ID__)
      -- L?c ngày h?t án >= ngày nh?p (?ã parse vào __V_HET_AN_SAU_NGAY__ ? ??u th? t?c)
      AND (__V_HET_AN_SAU_NGAY__ IS NULL OR TRUNC(CAST(w.NGAY_HET_AN AS DATE)) >= __V_HET_AN_SAU_NGAY__)
      AND (__V_FILTER_LIKE__ IS NULL OR UPPER(CAST(NVL(w.HO_TEN, '') AS VARCHAR2(2000))) LIKE __V_FILTER_LIKE__)
      AND (__V_DP_LIKE__ IS NULL
           OR UPPER(NVL(CAST(w.NOI_THA_VE_CU_TRU AS VARCHAR2(4000)), '') || ' ' ||
                     NVL(CAST(w.NOI_THA_VE_CU_TRU_XA AS VARCHAR2(4000)), '') || ' ' ||
                     NVL(CAST(w.NOI_THA_VE_CU_TRU_TINH AS VARCHAR2(4000)), '')) LIKE __V_DP_LIKE__)
      AND (__P_NOI_CU_TRU_RO_RANG__ IS NULL OR __P_NOI_CU_TRU_RO_RANG__ <> 1
           OR (   (w.NOI_THA_VE_CU_TRU IS NOT NULL AND TRIM(CAST(w.NOI_THA_VE_CU_TRU AS VARCHAR2(4000))) <> '')
               OR (w.NOI_THA_VE_CU_TRU_XA IS NOT NULL OR w.NOI_THA_VE_CU_TRU_TINH IS NOT NULL)
               OR (w.NOI_THUONG_TRU_DAY_DU IS NOT NULL AND TRIM(CAST(w.NOI_THUONG_TRU_DAY_DU AS VARCHAR2(4000))) <> '')))
      AND (__P_KHONG_XET_NHIEU_TOI__ IS NULL OR __P_KHONG_XET_NHIEU_TOI__ <> 1
           OR REGEXP_COUNT(NVL(w.toi_csv, ''), '[0-9]+') < 2)
      AND (__P_XONG_HPBS_TIEN__ IS NULL OR __P_XONG_HPBS_TIEN__ <> 1
           OR w.PHAM_NHAN_ID NOT IN (SELECT pn_id FROM hpbs_agg_ko_nvds WHERE so_hpbs_xet > 0 AND so_hpbs_done < so_hpbs_xet))
      AND (__P_DA_THUC_HIEN_XONG_HPBS__ IS NULL OR __P_DA_THUC_HIEN_XONG_HPBS__ <> 1
           OR w.PHAM_NHAN_ID NOT IN (SELECT pn_id FROM hpbs_agg_all WHERE so_hpbs_xet > 0 AND so_hpbs_done < so_hpbs_xet))
    ORDER BY w.HO_TEN, w.NGAY_XET DESC NULLS LAST
    OFFSET __V_SKIP__ ROWS
    FETCH NEXT CASE WHEN __V_LIMIT__ > 0 THEN __V_LIMIT__ ELSE 999999999 END ROWS ONLY;
~';

    v_sql := REPLACE(v_sql, '__V_DEN_NGAY__', sql_date(v_den_ngay));
    v_sql := REPLACE(v_sql, '__V_DK_TG_ID__', sql_num(v_dk_tg_id));
    v_sql := REPLACE(v_sql, '__V_DK_XL_ID__', sql_num(v_dk_xl_id));
    v_sql := REPLACE(v_sql, '__V_HET_AN_SAU_NGAY__', sql_date(v_het_an_sau_ngay));
    v_sql := REPLACE(v_sql, '__V_FILTER_LIKE__', sql_str(v_filter_like));
    v_sql := REPLACE(v_sql, '__V_DP_LIKE__', sql_str(v_dp_like));
    v_sql := REPLACE(v_sql, '__P_TRANG_THAI_PN_ID__', sql_num(p_trang_thai_pn_id));
    v_sql := REPLACE(v_sql, '__P_PHAN_DOI_ID__', sql_num(p_phan_doi_id));
    v_sql := REPLACE(v_sql, '__P_NGHIEN_MA_TUY_ID__', sql_num(p_nghien_ma_tuy_id));
    v_sql := REPLACE(v_sql, '__P_DIEU_KIEN_THOI_GIAN_ID__', sql_num(p_dieu_kien_thoi_gian_id));
    v_sql := REPLACE(v_sql, '__P_DIEU_KIEN_XEP_LOAI_ID__', sql_num(p_dieu_kien_xep_loai_id));
    v_sql := REPLACE(v_sql, '__P_DIEU_KIEN_KHAC_ID__', sql_num(p_dieu_kien_khac_id));
    v_sql := REPLACE(v_sql, '__P_MUC_AN_PHAT_ID__', sql_num(p_muc_an_phat_id));
    v_sql := REPLACE(v_sql, '__P_NOI_CU_TRU_RO_RANG__', sql_num(p_noi_cu_tru_ro_rang));
    v_sql := REPLACE(v_sql, '__P_KHONG_XET_NHIEU_TOI__', sql_num(p_khong_xet_nhieu_toi));
    v_sql := REPLACE(v_sql, '__P_XONG_HPBS_TIEN__', sql_num(p_xong_hpbs_tien));
    v_sql := REPLACE(v_sql, '__P_DA_THUC_HIEN_XONG_HPBS__', sql_num(p_da_thuc_hien_xong_hpbs));
    v_sql := REPLACE(v_sql, '__V_SKIP__', sql_num(v_skip));
    v_sql := REPLACE(v_sql, '__V_LIMIT__', sql_num(v_limit));

    DBMS_OUTPUT.PUT_LINE('===== FINAL SQL START =====');
    print_clob(v_sql);
    DBMS_OUTPUT.PUT_LINE('===== FINAL SQL END =====');

    OPEN c1 FOR
        SELECT v_sql AS final_sql
        FROM DUAL;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi d?ng SQL cu?i cùng: ' || SQLERRM);
END SP_GET_DS_DU_DK_THA_CO_DK_PRINT_SQL;







/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_GIAM_AN_TOA_EXCEL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_GIAM_AN_TOA_EXCEL" (
    p_pn_ids IN NVARCHAR2 DEFAULT NULL,
    p_ky_xet IN NUMBER DEFAULT NULL,
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL
) AS
    p_cursor SYS_REFCURSOR;
BEGIN
    OPEN p_cursor FOR
        WITH ID_LIST AS (SELECT DISTINCT TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
                         FROM DUAL
                         CONNECT BY LEVEL <= CASE
                                                 WHEN p_pn_ids IS NULL THEN 0
                                                 WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                                                 ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                             END
                                AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
                                AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')),
             td_split AS (SELECT ptha.THA_PNLAI_LICH_ID,
                                 REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', '') AS TOI_DANH_ID,
                                 ptha.THA_MUC_AN_ID
                          FROM QLPN.PN_THI_HANH_AN ptha
                                   LEFT JOIN DM_TOI_DANHS td ON td.ID = ptha.THA_TOI_DANH
                          WHERE ptha.IS_DELETED = 0),
             NUM_GEN AS (SELECT LEVEL AS N
                         FROM DUAL
                         CONNECT BY LEVEL <= 20),
             SPLIT_TOI_DANH AS (SELECT TF.THA_PNLAI_LICH_ID,
                                       TO_NUMBER(TRIM(
                                               REGEXP_SUBSTR(TF.TOI_DANH_ID, '[^,]+', 1, NG.N)
                                                 )) AS TOI_DANH_ID
                                FROM td_split TF
                                         JOIN NUM_GEN NG
                                              ON NG.N <= REGEXP_COUNT(TF.TOI_DANH_ID, ',') + 1
                                WHERE REGEXP_SUBSTR(TF.TOI_DANH_ID, '[^,]+', 1, NG.N) IS NOT NULL),
             TD_AGG AS (SELECT S.THA_PNLAI_LICH_ID,
                               LISTAGG(DISTINCT DTD.TD_CHUONG, ', ')
                                       WITHIN GROUP (ORDER BY DTD.TD_TEN) AS TOI_DANH_CHUONGS,
                               LISTAGG(DISTINCT DTD.TD_TEN, '; ')
                                       WITHIN GROUP (ORDER BY DTD.TD_TEN) AS TOI_DANH_TENS
                        FROM SPLIT_TOI_DANH S
                                 LEFT JOIN DM_TOI_DANHS DTD ON DTD.ID = S.TOI_DANH_ID
                        GROUP BY S.THA_PNLAI_LICH_ID),
             GCR_SPLIT AS (SELECT lls.ID,
                                  REPLACE(REPLACE(lls.LL_GHI_CHU_RIENG, '[', ''), ']', '') AS ghi_chu_rieng_id
                           FROM QLPN.PN_LAI_LICHS lls),
             NUM_GEN_GCR AS (SELECT LEVEL AS N
                             FROM DUAL
                             CONNECT BY LEVEL <= 20),
             SPLIT_GCR AS (SELECT GS.ID,
                                  TO_NUMBER(TRIM(
                                          REGEXP_SUBSTR(GS.ghi_chu_rieng_id, '[^,]+', 1, NG.N)
                                            )) AS ghi_chu_rieng_id
                           FROM GCR_SPLIT GS
                                    JOIN NUM_GEN_GCR NG
                                         ON NG.N <= REGEXP_COUNT(GS.ghi_chu_rieng_id, ',') + 1
                           WHERE REGEXP_SUBSTR(GS.ghi_chu_rieng_id, '[^,]+', 1, NG.N) IS NOT NULL),
             GCR_AGG AS (SELECT S.ID,
                                LISTAGG(DISTINCT dm.GCR_TEN, '; ')
                                        WITHIN GROUP (ORDER BY dm.GCR_TEN) AS ghi_chu_riengs
                         FROM SPLIT_GCR S
                                  LEFT JOIN QLPN.DM_GHI_CHU_RIENGS dm
                                            ON dm.ID = s.ghi_chu_rieng_id
                         GROUP BY S.ID)
        SELECT ROW_NUMBER() OVER (ORDER BY ll.ID)                       AS TT,
               ll.LL_HO_TEN                                             AS HO_TEN,
               ll.LL_TEN_KHAC                                           AS TEN_KHAC,
               SUBSTR(ll.LL_NGAY_SINH, -4)                              AS NS,
               gt.GT_TEN                                                AS GT,
               NVL2(ll.LL_DIA_CHI_THUONG_TRU, ll.LL_DIA_CHI_THUONG_TRU || ', ' || xp.XP_TEN || ', ' ||
                                              ttp.TTP_TEN, xp.XP_TEN || ', ' ||
                                                           ttp.TTP_TEN) AS DKTT,
               qt.QT_TEN                                                AS QUOC_TICH,
               tda.TOI_DANH_TENS                                        AS TOI_DANH,
               TO_CHAR(tha.THA_NGAY_BAT, 'dd/mm/yyyy')                  AS NGAY_BAT,
               tha.THA_AN_PHAT                                          AS AN_PHAT,
               NVL(TO_NCHAR(ll.LL_SO_TIEN_AN), u'Kh\00f4ng')            AS TIEN_AN,
               NVL(tha.THA_THOI_GIAN_TAM_GIAM, u'Kh\00f4ng')            AS TAM_GIAM,
               NVL(tha.THA_THOI_GIAN_TAM_GIU, u'Kh\00f4ng')             AS TAM_GIU,
               NVL(dmtg_ch.MTG_TITLE, g.DA_CHAP_HANH)                   AS DA_CHAP_HANH,
               g.DA_GIAM                                                AS DA_GIAM,
               NVL(dmtg_cl.MTG_TITLE, g.CON_LAI)                        AS CON_LAI,

               TO_NCHAR(tha.THA_NGAY_DEN_TRAI, 'dd/mm/yyyy')            AS NGAY_DEN_TRAI,
               TO_NCHAR(tha.THA_NGAY_HET_HAN, 'dd/mm/yyyy')             AS NGAY_HET_HAN,
               tha.THA_SO_BAN_AN                                        AS BAN_AN_SO,
               TO_CHAR(tha.THA_NGAY_BAN_AN, 'dd/mm/yyyy')               AS BAN_AN_NGAY,
               toa_ba.CQ_TEN || u' ' || TTP_BA.TTP_TEN                  AS CUA_TOA_BAN_AN,
               tha.THA_SO_QD_THA                                        AS QD_THA_SO,
               TO_CHAR(tha.THA_NGAY_QD_THA, 'dd/mm/yyyy')               AS QD_THA_NGAY,
               toa_qd.CQ_TEN || u' ' || ttp_qd.TTP_TEN                  AS CUA_TOA_QD_THA,

               tn_bo.HO_TEN_THAN_NHAN                                   AS HO_TEN_BO,
               tn_me.HO_TEN_THAN_NHAN                                   AS HO_TEN_ME,
               tn_vc.HO_TEN_THAN_NHAN                                   AS HO_TEN_VO_CHONG,
               (SELECT MTG_TITLE
                FROM QLPN.DM_MA_THOI_GIANS
                WHERE DM_MA_THOI_GIANS.ID = g.MUC_DE_NGHI_ID)           AS MUC_DN_GIAM,
               (SELECT MTG_TITLE
                FROM QLPN.DM_MA_THOI_GIANS
                WHERE DM_MA_THOI_GIANS.ID = g.CAP_TREN_DUYET_ID)        AS MUC_GIAM_BCA,
               (SELECT MTG_TITLE
                FROM QLPN.DM_MA_THOI_GIANS
                WHERE DM_MA_THOI_GIANS.ID = g.MUC_GIAM_ID)              AS MUC_GIAM_TOA,
               gcr.ghi_chu_riengs                                       AS GHI_CHU
        FROM PN_LAI_LICHS ll
                 LEFT JOIN PN_THI_HANH_AN tha ON tha.THA_PNLAI_LICH_ID = ll.ID AND tha.IS_DELETED = 0
                 LEFT JOIN DM_GIOI_TINHS gt ON gt.ID = ll.LL_DM_GIOI_TINH_ID AND gt.IS_DELETED = 0
                 LEFT JOIN DM_QUOC_TICHS qt ON qt.ID = ll.LL_DM_QUOC_TICH_ID AND qt.IS_DELETED = 0
                 LEFT JOIN DM_CO_QUANS toa_ba ON toa_ba.ID = tha.THA_CAP_TOA_ID AND toa_ba.IS_DELETED = 0
                 LEFT JOIN DM_TINH_THANH_PHO ttp_ba
                           ON tha.THA_DIA_PHUONG_CAP_TOA_ID = TTP_BA.ID AND TTP_BA.IS_DELETED = 0
                 LEFT JOIN DM_CO_QUANS toa_qd ON toa_qd.ID = tha.THA_TOA_QD_ID AND toa_qd.IS_DELETED = 0
                 LEFT JOIN DM_TINH_THANH_PHO ttp_qd
                           ON TTP_QD.ID = tha.THA_DIA_PHUONG_TOA_QD_THA_ID AND TTP_QD.IS_DELETED = 0
                 LEFT JOIN GCR_AGG gcr ON gcr.ID = ll.ID
                 LEFT JOIN TD_AGG tda ON tda.THA_PNLAI_LICH_ID = ll.ID
                 LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg_ch ON dmtg_ch.MTG_MA = tha.THA_THOI_GIAN_DA_CHAP_HANH
                 LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg_cl ON dmtg_cl.MTG_MA = tha.THA_THOI_GIAN_CON_LAI
                 LEFT JOIN (SELECT tn.PHAM_NHAN_ID, MAX(tn.HO_TEN_THAN_NHAN) AS HO_TEN_THAN_NHAN
                            FROM THAN_NHAN_NGUOI_THANS tn
                                     INNER JOIN DM_QUAN_HE_VOI_PHAM_NHANS qh
                                                ON qh.ID = tn.QUAN_HE_ID AND qh.IS_DELETED = 0
                            WHERE tn.IS_DELETED = 0
                              AND (UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%B?%' OR UPPER(TRIM(qh.QHVPN_MA)) IN ('BO', 'CHA'))
                            GROUP BY tn.PHAM_NHAN_ID) tn_bo ON tn_bo.PHAM_NHAN_ID = ll.ID
                 LEFT JOIN (SELECT tn.PHAM_NHAN_ID, MAX(tn.HO_TEN_THAN_NHAN) AS HO_TEN_THAN_NHAN
                            FROM THAN_NHAN_NGUOI_THANS tn
                                     INNER JOIN DM_QUAN_HE_VOI_PHAM_NHANS qh
                                                ON qh.ID = tn.QUAN_HE_ID AND qh.IS_DELETED = 0
                            WHERE tn.IS_DELETED = 0
                              AND (UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%M?%' OR UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%ME%' OR
                                   UPPER(TRIM(qh.QHVPN_MA)) = 'ME')
                            GROUP BY tn.PHAM_NHAN_ID) tn_me ON tn_me.PHAM_NHAN_ID = ll.ID
                 LEFT JOIN (SELECT tn.PHAM_NHAN_ID, MAX(tn.HO_TEN_THAN_NHAN) AS HO_TEN_THAN_NHAN
                            FROM THAN_NHAN_NGUOI_THANS tn
                                     INNER JOIN DM_QUAN_HE_VOI_PHAM_NHANS qh
                                                ON qh.ID = tn.QUAN_HE_ID AND qh.IS_DELETED = 0
                            WHERE tn.IS_DELETED = 0
                              AND (UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%V?%' OR UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%CH?NG%' OR
                                   UPPER(TRIM(qh.QHVPN_MA)) IN ('VC', 'VO', 'CHONG'))
                            GROUP BY tn.PHAM_NHAN_ID) tn_vc ON tn_vc.PHAM_NHAN_ID = ll.ID
                 INNER JOIN (SELECT gths1.PHAM_NHAN_ID,
                                    gths1.MUC_DE_NGHI_ID,
                                    gths1.DA_CHAP_HANH,
                                    gths1.DA_GIAM,
                                    gths1.MUC_GIAM_ID,
                                    gths1.CAP_TREN_DUYET_ID,
                                    gths1.NGAY_THA_GIAM_HET_AN,
                                    gths1.CON_LAI,
                                    gths1.NGAY_XET,
                                    ROW_NUMBER() OVER (PARTITION BY gths1.PHAM_NHAN_ID ORDER BY gths1.NGAY_QUYET_DINH DESC NULLS LAST) rn
                             FROM GIAM_THOI_HANS gths1
                                      LEFT JOIN GTH_KY_GIAM_THOI_HANS kgth
                                                ON kgth.KGTH_NGAY_XET_GIAM = gths1.NGAY_XET
                             WHERE gths1.IS_DELETED = 0
                               AND kgth.IS_DELETED = 0
                               AND kgth.ID IS NOT NULL
                               AND (kgth.ID = p_ky_xet OR p_ky_xet IS NULL)) g ON g.PHAM_NHAN_ID = ll.ID AND g.rn = 1
                 LEFT JOIN DM_TINH_THANH_PHO ttp ON ttp.ID = ll.LL_DIA_CHI_THUONG_TRU_PROVICE
                 LEFT JOIN DM_XA_PHUONG xp ON xp.ID = ll.LL_DIA_CHI_THUONG_TRU_WARD
        WHERE ll.IS_DELETED = 0
          AND (    p_ma_trai_giam IS NULL OR ll.LL_TRAI_GIAM_ID = p_ma_trai_giam)
          AND (p_pn_ids IS NULL OR LL.ID IN (SELECT PN_ID FROM ID_LIST));

    DBMS_SQL.RETURN_RESULT(p_cursor);
END SP_GET_DS_GIAM_AN_TOA_EXCEL;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_HD_XET_DE_NGHI_TTTTH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_HD_XET_DE_NGHI_TTTTH" (                  
 p_ngay_xet_tu_ngay IN NVARCHAR2 DEFAULT NULL,
    p_ngay_xet_den_ngay IN NVARCHAR2 DEFAULT NULL,
    p_ngay_tha_tu_ngay IN NVARCHAR2 DEFAULT NULL,
    p_ngay_tha_den_ngay IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi IN NVARCHAR2 DEFAULT NULL,
    p_tinh_trang IN NVARCHAR2 DEFAULT NULL,
    p_dia_phuong_cu_tru IN NVARCHAR2 DEFAULT NULL,
    p_tinh_trang_tha IN NVARCHAR2 DEFAULT NULL,
    p_chon_in IN NVARCHAR2 DEFAULT 'Danh sách chung'
)
AS
    v_ngay_xet_tu_ngay NVARCHAR2(10);
    v_ngay_xet_den_ngay NVARCHAR2(10);
    v_ngay_tha_tu_ngay NVARCHAR2(10);
    v_ngay_tha_den_ngay NVARCHAR2(10);
    C1 SYS_REFCURSOR;
BEGIN
    IF p_ngay_xet_tu_ngay IS NULL OR p_ngay_xet_tu_ngay = '' THEN
        v_ngay_xet_tu_ngay := TO_CHAR(SYSDATE - 1, 'DD/MM/YYYY');
    ELSE
        v_ngay_xet_tu_ngay := p_ngay_xet_tu_ngay;
    END IF;

    IF p_ngay_xet_den_ngay IS NULL OR p_ngay_xet_den_ngay = '' THEN
        v_ngay_xet_den_ngay := TO_CHAR(SYSDATE - 1, 'DD/MM/YYYY');
    ELSE
        v_ngay_xet_den_ngay := p_ngay_xet_den_ngay;
    END IF;

    IF p_ngay_tha_tu_ngay IS NULL OR p_ngay_tha_tu_ngay = '' THEN
        v_ngay_tha_tu_ngay := TO_CHAR(SYSDATE - 1, 'DD/MM/YYYY');
    ELSE
        v_ngay_tha_tu_ngay := p_ngay_tha_tu_ngay;
    END IF;

    IF p_ngay_tha_den_ngay IS NULL OR p_ngay_tha_den_ngay = '' THEN
        v_ngay_tha_den_ngay := TO_CHAR(SYSDATE - 1, 'DD/MM/YYYY');
    ELSE
        v_ngay_tha_den_ngay := p_ngay_tha_den_ngay;
    END IF;

      OPEN C1 FOR
		 SELECT tcdk.PHAM_NHAN_ID,
				vpllct.HO_TEN ,
				vpllct.NGAY_SINH,
				vpllct.GIOI_TINH ,
				vpllct.NOI_THUONG_TRU_DAY_DU ,
				vpllct.NOI_THA_VE_CU_TRU ,
				vpllct.TOI_DANH ,
				vpllct.NGAY_BAT_AN_PHAT AS NGAY_BAT,
				vpllct.AN_PHAT , 
				vpllct.NGAY_DEN_TRAI NGAY_CHAP_HANH_APT,
				FN_GET_DA_CHAP_HANH (tcdk.PHAM_NHAN_ID) THOI_GIAN_DA_O_TU,
				NULL AS THOI_GIAN_DA_GIAM,
				FN_GET_CON_LAI (tcdk.PHAM_NHAN_ID) THOI_GIAN_CON_LAI,
				xlct.XLCT_TEN DANH_GIA_CAI_TAO,
				vpllct.GHI_CHU 
			FROM
				THA_CO_DIEU_KIENS tcdk
			INNER JOIN VW_PN_LAI_LICH_CHI_TIET vpllct ON
				tcdk.PHAM_NHAN_ID = vpllct.PHAM_NHAN_ID AND tcdk.TINH_TRANG_ID IN (10,11)
			LEFT JOIN DM_XEP_LOAI_CAI_TAOS xlct ON xlct.ID = tcdk.DANH_GIA_CAI_TAO_ID
			INNER JOIN DM_TINH_THANH_PHO ddvhc ON ddvhc.TTP_TEN = vpllct.TINH_THANH_THUONG_TRU
        	WHERE
            	(tcdk.NGAY_XET BETWEEN TO_TIMESTAMP(v_ngay_xet_tu_ngay, 'DD/MM/YYYY') AND TO_TIMESTAMP(v_ngay_xet_den_ngay || ' 23:59:59', 'DD/MM/YYYY HH24:MI:SS'))
            	AND (tcdk.NGAY_THA BETWEEN TO_TIMESTAMP(v_ngay_tha_tu_ngay, 'DD/MM/YYYY')
                AND TO_TIMESTAMP(v_ngay_tha_den_ngay || ' 23:59:59', 'DD/MM/YYYY HH24:MI:SS'))
	            AND (p_tinh_trang IS NULL OR vpllct.LL_TINH_TRANG_ID = p_tinh_trang)
	            AND (p_phan_doi IS NULL OR vpllct.PHAN_DOI_ID = p_phan_doi)
	            AND (p_dia_phuong_cu_tru IS NULL OR ddvhc.ID = p_dia_phuong_cu_tru)
	            AND (p_tinh_trang_tha IS NULL OR tcdk.TINH_TRANG_ID = p_tinh_trang_tha);

	DBMS_SQL.RETURN_RESULT(C1);

END;     








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_KY_NHAN_TIEN_THNCD
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_KY_NHAN_TIEN_THNCD" SP_GET_DS_KY_NHAN_TIEN_THNCD
(                            
    p_ngay_xet_tu_ngay IN NVARCHAR2 DEFAULT NULL,
    p_ngay_xet_den_ngay IN NVARCHAR2 DEFAULT NULL,
    p_ngay_tha_tu_ngay IN NVARCHAR2 DEFAULT NULL,
    p_ngay_tha_den_ngay IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi IN NVARCHAR2 DEFAULT NULL,
    p_tinh_trang IN NVARCHAR2 DEFAULT NULL,
    p_dia_phuong_cu_tru IN NVARCHAR2 DEFAULT NULL,
    p_tinh_trang_tha IN NVARCHAR2 DEFAULT NULL,
    p_chon_in IN NVARCHAR2 DEFAULT '6'
)
AS
    v_ngay_xet_tu_ngay NVARCHAR2(10);
    v_ngay_xet_den_ngay NVARCHAR2(10);
    v_ngay_tha_tu_ngay NVARCHAR2(10);
    v_ngay_tha_den_ngay NVARCHAR2(10);
    C1 SYS_REFCURSOR; 
BEGIN

    IF p_ngay_xet_tu_ngay IS NULL OR p_ngay_xet_tu_ngay = '' THEN
        v_ngay_xet_tu_ngay := TO_CHAR(SYSDATE - 1, 'DD/MM/YYYY');
    ELSE
        v_ngay_xet_tu_ngay := p_ngay_xet_tu_ngay;
    END IF;

    IF p_ngay_xet_den_ngay IS NULL OR p_ngay_xet_den_ngay = '' THEN
        v_ngay_xet_den_ngay := TO_CHAR(SYSDATE - 1, 'DD/MM/YYYY');
    ELSE
        v_ngay_xet_den_ngay := p_ngay_xet_den_ngay;
    END IF;

    IF p_ngay_tha_tu_ngay IS NULL OR p_ngay_tha_tu_ngay = '' THEN
        v_ngay_tha_tu_ngay := TO_CHAR(SYSDATE - 1, 'DD/MM/YYYY');
    ELSE
        v_ngay_tha_tu_ngay := p_ngay_tha_tu_ngay;
    END IF;

    IF p_ngay_tha_den_ngay IS NULL OR p_ngay_tha_den_ngay = '' THEN
        v_ngay_tha_den_ngay := TO_CHAR(SYSDATE - 1, 'DD/MM/YYYY');
    ELSE
        v_ngay_tha_den_ngay := p_ngay_tha_den_ngay;
    END IF;

      OPEN C1 FOR
		  SELECT
			tcdk.PHAM_NHAN_ID,
			vpllct.HO_TEN ,
			vpllct.NAM_SINH ,
			vpllct.GIOI_TINH ,
			vpllct.NOI_THUONG_TRU_DAY_DU ,
			vpllct.TOI_DANH ,
			CASE
				WHEN vpllct.SO_TIEN_AN IS NOT NULL
				AND vpllct.SO_TIEN_AN <> u'0'
		                THEN vpllct.SO_TIEN_AN
				ELSE u'Kh\00f4ng'
			END AS SO_TIEN_AN,
			vpllct.NGAY_BAT_AN_PHAT AS NGAY_BAT,
			vpllct.AN_PHAT , 
			vpllct.THOI_GIAN_TAM_GIAM ,
			NULL AS DA_GIAM,
			vpllct.NGAY_DEN_TRAI ,
			tcdk.NGAY_THA,
			vpllct.PHAN_DOI,
			NULL AS TIEN_AN_DUONG,
			NULL AS TIEN_TAU_XE,
			NULL AS KY_NHAN,
			NULL AS TONG_TIEN,
			vpllct.TINH_THANH_THUONG_TRU,
			ddvhc.ID,
			tcdk.TINH_TRANG_ID,
			vpllct.LL_TINH_TRANG_ID,
			vpllct.PHAN_DOI_ID,
			vpllct.PHAN_DOI,
			tcdk.NGAY_XET 
		FROM THA_CO_DIEU_KIENS tcdk
		INNER JOIN VW_PN_LAI_LICH_CHI_TIET vpllct ON tcdk.PHAM_NHAN_ID = vpllct.PHAM_NHAN_ID
													AND tcdk.TINH_TRANG_ID IN (10, 11)
		INNER JOIN DM_TINH_THANH_PHO ddvhc
            ON ddvhc.TTP_TEN = vpllct.TINH_THANH_THUONG_TRU											
		WHERE
			(tcdk.NGAY_XET BETWEEN TO_TIMESTAMP(v_ngay_xet_tu_ngay, 'DD/MM/YYYY')
                AND TO_TIMESTAMP(v_ngay_xet_den_ngay || ' 23:59:59', 'DD/MM/YYYY HH24:MI:SS'))
            AND (tcdk.NGAY_THA BETWEEN TO_TIMESTAMP(v_ngay_tha_tu_ngay, 'DD/MM/YYYY')
                AND TO_TIMESTAMP(v_ngay_tha_den_ngay || ' 23:59:59', 'DD/MM/YYYY HH24:MI:SS'))
            AND (p_tinh_trang IS NULL OR vpllct.LL_TINH_TRANG_ID = p_tinh_trang)
            AND (p_phan_doi IS NULL OR vpllct.PHAN_DOI_ID = p_phan_doi)
            AND (p_dia_phuong_cu_tru IS NULL OR ddvhc.ID = p_dia_phuong_cu_tru)
            AND (p_tinh_trang_tha IS NULL OR tcdk.TINH_TRANG_ID = p_tinh_trang_tha)
;

	DBMS_SQL.RETURN_RESULT(C1);

END;     








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PHAM_NHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PHAM_NHAN" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    c1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN c1 FOR
    WITH selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1
    ),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE,
            CASE WHEN ll.THA_MA_AN_PHAT IS NULL THEN NULL
                 ELSE TO_NUMBER(ll.THA_MA_AN_PHAT)
            END AS THA_MA_AN_PHAT_NUM
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    )
    SELECT
        ll.PHAM_NHAN_ID                                                         AS PHAM_NHAN_ID,
        ll.LL_HO_TEN                                                            AS "HoTen",
        SUBSTR(ll.LL_NGAY_SINH, -4)                                             AS "NamSinh",
        dgt.GT_TEN                                                              AS "GioiTinh",
        ll.LL_DIA_CHI_THUONG_TRU                                                 AS "DiaChi",
        td_agg.TOI_DANH                                                         AS "ToiDanh",
        NVL(ll.LL_SO_TIEN_AN, u'0')                                             AS "SoTienAn",
        TO_CHAR(TRUNC(ll.THA_NGAY_BAT), 'DD/MM/YYYY')                           AS "NgayBat",
        ll.THA_AN_PHAT                                                          AS "AnPhat",
        CASE WHEN NVL(ll.SO_LAN_GIAM, 0) = 0 THEN u'Kh\00f4ng'
             ELSE TO_CHAR(ll.SO_LAN_GIAM) || u' l\1ea7n = ' || ll.THOI_GIAN_DA_GIAM
        END                                                                     AS "DaGiam",
        NVL(dmtg_dch.MTG_TITLE, u'Kh\00f4ng')                                      AS "DaChapHanh",
        NVL(dmtg_cl.MTG_TITLE,  u'Kh\00f4ng')                                      AS "ConLai",
        TO_CHAR(TRUNC(ll.THA_NGAY_DEN_TRAI), 'DD/MM/YYYY')                      AS "NgayDenTrai",
        TO_CHAR(TRUNC(ll.THA_NGAY_HET_HAN),   'DD/MM/YYYY')                     AS "NgayHetHan",
        QLPN.FN_GET_LIET_KE_HPBS_CHI_TIET(ll.PHAM_NHAN_ID)                    AS "HinhPhatBoSung",
        gcr_agg.GHI_CHU_RIENG                                                  AS "GhiChu"

    FROM pn_base ll
    LEFT JOIN DM_QUOC_TICHS dqt
        ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
       AND dqt.IS_DELETED = 0
    LEFT JOIN DM_GIOI_TINHS dgt
        ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg_cl
        ON dmtg_cl.MTG_MA = ll.THA_THOI_GIAN_CON_LAI
       AND dmtg_cl.IS_DELETED = 0
    LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg_dch
        ON dmtg_dch.MTG_MA = ll.THA_THOI_GIAN_DA_CHAP_HANH
       AND dmtg_dch.IS_DELETED = 0
    LEFT JOIN LATERAL (
        SELECT RTRIM(XMLAGG(XMLELEMENT(e, dtd.TD_TEN || ', ')
                   ORDER BY dtd.TD_TEN).extract('//text()').GETCLOBVAL(), ', ') AS TOI_DANH
        FROM (
            SELECT TRIM(REGEXP_SUBSTR(
                REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                '[^,]+', 1, LEVEL)) AS TD_ID
            FROM DUAL
            WHERE ll.THA_TOI_DANH IS NOT NULL
            CONNECT BY LEVEL <= REGEXP_COUNT(
                REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
        ) td
        LEFT JOIN DM_TOI_DANHS dtd ON TO_NUMBER(td.TD_ID) = dtd.ID
    ) td_agg ON 1 = 1
    LEFT JOIN LATERAL (
        SELECT RTRIM(XMLAGG(XMLELEMENT(e, dgcr.GCR_TEN || ', ')
                   ORDER BY dgcr.GCR_TEN).extract('//text()').GETCLOBVAL(), ', ') AS GHI_CHU_RIENG
        FROM (
            SELECT TRIM(REGEXP_SUBSTR(ll.LL_GHI_CHU_RIENG, '[^,]+', 1, LEVEL)) AS GHI_CHU_RIENG_MA
            FROM DUAL
            WHERE ll.LL_GHI_CHU_RIENG IS NOT NULL
            CONNECT BY LEVEL <= REGEXP_COUNT(ll.LL_GHI_CHU_RIENG, ',') + 1
        ) gcr
        LEFT JOIN DM_GHI_CHU_RIENGS dgcr ON gcr.GHI_CHU_RIENG_MA = TRIM(dgcr.ID)
    ) gcr_agg ON 1 = 1

    WHERE
            (p_ma_trai_giam IS NULL OR v_ll_trai_giam_id IS NOT NULL)
        AND (p_den_trai_tu_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
        AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
        AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN   >= p_ra_trai_tu_ngay)
        AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN   <= p_ra_trai_den_ngay)
        AND (
            (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
            OR EXISTS (
                SELECT 1
                FROM PN_DAC_XAS dxa
                WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                  AND dxa.IS_DELETED = 0
                  AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                  AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
            )
        )
        AND (
            (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
            OR EXISTS (
                SELECT 1
                FROM GIAM_THOI_HANS gaan
                WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                  AND gaan.IS_DELETED   = 0
                  AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                  AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
            )
        )
        AND (p_so_tien_an_tu IS NULL OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu))
        AND (p_so_tien_an_den IS NULL OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den))
        AND (p_muc_an_tu IS NULL OR ll.THA_MA_AN_PHAT_NUM >= p_muc_an_tu)
        AND (p_muc_an_den IS NULL OR ll.THA_MA_AN_PHAT_NUM <= p_muc_an_den)
        AND (p_tuoi_tu IS NULL OR
                (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu)
            )
        AND (p_tuoi_den IS NULL OR
                (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den)
            )
        AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
        AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
        AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
        AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
        AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
        AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID        = p_dan_toc_id)
        AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
        AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID    = p_nghe_nghiep_id)
        AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID        = p_hoc_van_id)
        AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID       = p_ton_giao_id)
        AND (
            p_toi_danh_ids IS NULL
            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
            OR EXISTS (
                SELECT 1
                FROM selected_toi_danh_filter loc
                WHERE INSTR(
                    ',' || REPLACE(REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''), ' ', '') || ',',
                    ',' || TRIM(loc.ma_loc) || ','
                ) > 0
            )
        )
        AND (p_dp_dktt_id       IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
        AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG                = p_loai_doi_tuong_id)
        AND (
            p_ghi_chu_rieng_id IS NULL
            OR INSTR(
                ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
            ) > 0
        )
        AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
        AND (p_nuoc_ngoai IS NULL OR (
            CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
        ))
        AND (p_co_benh_tat IS NULL OR (
            CASE
                WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL THEN 1
                WHEN EXISTS (
                    SELECT 1 FROM DM_BENH_TATS dbt
                    WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                      AND dbt.IS_DELETED = 0 AND dbt.BT_MA = '1'
                ) THEN 0
                ELSE 1
            END = p_co_benh_tat
        ))
        AND (p_giam_rieng IS NULL OR (
            CASE WHEN EXISTS (
                SELECT 1 FROM PN_GIAM_RIENGS gr
                WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
            ) THEN 1 ELSE 0 END = p_giam_rieng
        ))
        AND (
            p_dan_toc_thieu_so IS NULL
            OR (CASE
                    WHEN EXISTS (
                        SELECT 1 FROM DM_DAN_TOCS dt
                        WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                          AND dt.IS_DELETED = 0
                          AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                    ) THEN 1 ELSE 0
                END = p_dan_toc_thieu_so)
        )
        AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
            CASE
                WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                ELSE 0
            END = p_vtn_thoi_diem_pham_toi
        ))
        AND (p_pham_toi_moi IS NULL OR (
            CASE WHEN EXISTS (
                SELECT 1 FROM PHAM_TOI_MOIS ptm
                WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
            ) THEN 1 ELSE 0 END = p_pham_toi_moi
        ))
        AND (p_theo_ton_giao IS NULL OR (
            CASE WHEN EXISTS (
                SELECT 1 FROM DM_TON_GIAOS tg
                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID AND tg.IS_DELETED = 0
            ) THEN 1 ELSE 0 END = p_theo_ton_giao
        ))
        AND (p_vtn_hien_tai IS NULL OR (
            CASE
                WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                ELSE 0
            END = p_vtn_hien_tai
        ))
        AND (p_khong_pham_toi_moi IS NULL OR (
            CASE WHEN NOT EXISTS (
                SELECT 1 FROM PHAM_TOI_MOIS ptm
                WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
            ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
        ))
        AND (
            p_co_nghe_nghiep IS NULL
            OR (CASE
                    WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                         AND EXISTS (
                             SELECT 1 FROM DM_NGHE_NGHIEPS dnn
                             WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                               AND dnn.IS_DELETED = 0
                               AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                         ) THEN 1
                    ELSE 0
                END = p_co_nghe_nghiep)
        )
        AND (p_chung_than IS NULL OR (
            CASE WHEN ll.THA_MA_AN_PHAT_NUM IN (SELECT ID FROM chung_than_ids)
                 THEN 1 ELSE 0 END = p_chung_than
        ))
        AND (p_da_bi_ky_luat IS NULL OR (
            CASE WHEN EXISTS (
                SELECT 1 FROM KY_LUATS kl WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
            ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
        ))
        AND (p_co_ghi_chu_dac_biet IS NULL OR (
            CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                  AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                 THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
        ))
        AND (p_toi_pham_anqg IS NULL OR (
            CASE WHEN EXISTS (
                SELECT 1 FROM DM_TOI_DANHS td
                WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                  AND td.IS_DELETED = 0
                  AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
            ) THEN 1 ELSE 0 END = p_toi_pham_anqg
        ))
        AND (p_da_duoc_khen_thuong IS NULL OR (
            CASE WHEN EXISTS (
                SELECT 1 FROM KHEN_THUONGS kt
                WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
            ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
        ))
        AND (p_co_tien_an IS NULL OR (
            CASE WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0' THEN 1 ELSE 0 END = p_co_tien_an
        ))
        AND (p_co_tien_su IS NULL OR (
            CASE WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0' THEN 1 ELSE 0 END = p_co_tien_su
        ))
        AND (p_con_theo_me_vao_trai IS NULL OR (
            CASE WHEN EXISTS (
                SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
            ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
        ))
        AND (p_hp_bo_sung_la_tien IS NULL OR (
            CASE WHEN EXISTS (
                SELECT 1
                FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                    ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                  AND hpbs.IS_DELETED = 0
                  AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
            ) THEN 1 ELSE 0 END = p_hp_bo_sung_la_tien
        ))
        AND (p_bat_buoc_chua_benh IS NULL OR (
            CASE WHEN EXISTS (
                SELECT 1 FROM CHUA_BENH_BAT_BUOCS cb
                WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND cb.IS_DELETED = 0
            ) THEN 1 ELSE 0 END = p_bat_buoc_chua_benh
        ))
        AND (
            p_hoan_xong_hpbs_la_tien IS NULL OR
            (CASE WHEN EXISTS (
                SELECT 1
                FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                    ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                  AND hpbs.IS_DELETED = 0
                  AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
            ) THEN 1 ELSE 0 END = p_hoan_xong_hpbs_la_tien)
        )
        AND (
            p_chua_hoan_hpbs_la_tien IS NULL OR
            (CASE WHEN EXISTS (
                SELECT 1
                FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                    ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                  AND hpbs.IS_DELETED = 0
                  AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
            ) THEN 1 ELSE 0 END = p_chua_hoan_hpbs_la_tien)
        )
    ORDER BY ll.HO_TEN_ORDER
    ;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_DS_PHAM_NHAN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PHAM_NHAN_DU_DIEU_KIEN_THA_CDK
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PHAM_NHAN_DU_DIEU_KIEN_THA_CDK" (
   p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_tu_ngay IN NVARCHAR2 DEFAULT NULL,
    p_den_ngay IN NVARCHAR2 DEFAULT NULL
)
AS
    v_ten_trai_giam NVARCHAR2(2000);
    v_tu_ngay NVARCHAR2(10);
    v_den_ngay NVARCHAR2(10);
    C1 SYS_REFCURSOR;  
BEGIN
    --exec SP_GET_TK_PHAM_NHAN_CHAP_HANH_AN(NULL, '01/01/2020', '01/01/2027')
    IF p_ma_trai_giam IS NULL OR p_ma_trai_giam = '' THEN
        v_ten_trai_giam := NULL;
    ELSE
        v_ten_trai_giam := p_ma_trai_giam;
    END IF;

     IF p_tu_ngay IS NULL OR p_tu_ngay = '' THEN
        v_tu_ngay := to_char(sysdate - 1, 'DD/MM/YYYY');
        ELSE v_tu_ngay := p_tu_ngay;
    END IF;


    IF p_den_ngay IS NULL OR p_den_ngay = '' THEN
        v_den_ngay := to_char(sysdate - 1, 'DD/MM/YYYY');
        ELSE v_den_ngay := p_den_ngay;
    END IF;

      OPEN C1 FOR   
        WITH GIAM AS
        (
        SELECT
            PHAM_NHAN_ID
            ,LAN_GIAM_AN
            ,CASE 
                WHEN TONG_NGAY IS NULL OR TONG_NGAY = 0 THEN '0'
                ELSE 
                    TRUNC(TONG_NGAY / 365) || ' n?m ' ||
                    TRUNC(MOD(TONG_NGAY, 365) / 30) || ' tháng ' ||
                    MOD(MOD(TONG_NGAY, 365), 30) || ' ngày'
            END AS TONG_GIAM_AN
        FROM (
            SELECT 
                PHAM_NHAN_ID
                ,COUNT(
                    CASE
                        WHEN DA_GIAM IS NULL
                        OR DA_GIAM = 'Không'
                        OR DA_GIAM = ''
                        THEN NULL
                    ELSE 1
                    END
                    ) AS LAN_GIAM_AN
                ,SUM(
                    NVL(TO_NUMBER(REGEXP_SUBSTR(REPLACE(DA_GIAM, 'Không', '0'), '([0-9]+) n?m', 1, 1, 'i', 1)), 0) * 365 +
                    NVL(TO_NUMBER(REGEXP_SUBSTR(REPLACE(DA_GIAM, 'Không', '0'), '([0-9]+) tháng', 1, 1, 'i', 1)), 0) * 30 +
                    NVL(TO_NUMBER(REGEXP_SUBSTR(REPLACE(DA_GIAM, 'Không', '0'), '([0-9]+) ngày', 1, 1, 'i', 1)), 0)
                ) as TONG_NGAY
            FROM GIAM_THOI_HANS
            WHERE IS_DELETED =0
            GROUP BY PHAM_NHAN_ID
        )
        )
        SELECT LL.PHAM_NHAN_ID 
        , LL.HO_TEN 
        , LL.GIOI_TINH 
        , LL.NAM_SINH 
        , LL.DIA_CHI_THUONG_TRU 
        , LL.SO_TIEN_AN 
        , LL.NGAY_DEN_TRAI 
        , LL.NGAY_HET_AN 
        , VTHA.TOI_DANH 
        , THA.THA_NGAY_BAT 
        , THA.THA_AN_PHAT 
        , GIAM.LAN_GIAM_AN 
        , GIAM.TONG_GIAM_AN 
        , NULL AS KET_QUA_CAI_TAO
        , FN_GET_DA_CHAP_HANH(LL.PHAM_NHAN_ID ) AS DA_CHAP_HANH
        , FN_GET_CON_LAI(LL.PHAM_NHAN_ID) AS CON_LAI
        , FN_GET_LIET_KE_HPBS(LL.PHAM_NHAN_ID ) AS HPBS
        FROM PN_DU_DIEU_KIEN_XET_THAS DDK
        LEFT JOIN VW_PN_LAI_LICH_CHI_TIET LL
            ON DDK.PN_LAI_LICH_ID = LL.PHAM_NHAN_ID 
        LEFT JOIN V_PN_THI_HANH_AN_TOI_DANH VTHA
            ON DDK.PN_LAI_LICH_ID = VTHA.THA_PNLAI_LICH_ID 
        LEFT JOIN PN_THI_HANH_AN THA
            ON DDK.PN_LAI_LICH_ID = THA.THA_PNLAI_LICH_ID 
        LEFT JOIN GIAM
            ON DDK.PN_LAI_LICH_ID = GIAM.PHAM_NHAN_ID 
        where ll.TRAI_GIAM_MA = p_ma_trai_giam;
      DBMS_SQL.RETURN_RESULT(C1);


      --      exec SP_GET_DS_PHAM_NHAN_DU_DIEU_KIEN_THA_CDK( NULL, '01/01/2025', '01/01/2027');
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PHAM_NHAN_KTHS_KHONG_PHAN_DOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PHAM_NHAN_KTHS_KHONG_PHAN_DOI" (
    p_phan_doi_id     IN NUMBER DEFAULT NULL,
    p_tu_ngay         IN DATE DEFAULT NULL,
    p_den_ngay        IN DATE DEFAULT NULL,
    p_gioi_tinh_id    IN NUMBER DEFAULT NULL,
    p_quoc_tich_id    IN NUMBER DEFAULT NULL,
    is_ket_thuc       IN NUMBER DEFAULT NULL,
    p_trai_giam_id    IN NUMBER DEFAULT NULL
)
AS
    v_tu_ngay  DATE := NVL(p_tu_ngay, SYSDATE - 1);
    v_den_ngay DATE := NVL(p_den_ngay, SYSDATE);
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    HPBS_AGG AS (
        SELECT hpbs.HPBS_MA_PHAM_NHAN,
               LISTAGG(dmhpbs.HPBS_TEN, ', ')
                   WITHIN GROUP (ORDER BY dmhpbs.HPBS_TEN) AS HINH_PHAT_BO_SUNG
        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
        JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dmhpbs ON hpbs.HPBS_HINH_PHAT = dmhpbs.ID
        WHERE hpbs.IS_DELETED = 0
          AND hpbs.HPBS_MA_PHAM_NHAN IN (
              SELECT rt2.PHAM_NHAN_ID
              FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt2
              JOIN DM_TINH_TRANG_PHAM_NHANS tt2
                  ON rt2.LL_TINH_TRANG_ID = tt2.ID AND tt2.TTPN_MA = 111
              WHERE rt2.IS_DELETED = 0
                AND (p_phan_doi_id IS NULL OR rt2.LL_PHAN_DOI_ID = p_phan_doi_id)
          )
        GROUP BY hpbs.HPBS_MA_PHAM_NHAN
    )
    SELECT
        rt.LL_HO_TEN                         AS "HoTen",
        rt.LL_SO_HO_SO_LAN_DAU               AS "SoHSLD",
        SUBSTR(rt.LL_NGAY_SINH, -4)           AS "NamSinh",
        dgt.GT_TEN                            AS "GioiTinh",
        CASE
            WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dvhcx.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dvhct.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dvhcx.XP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                             THEN u', ' || dvhcx.XP_TEN ELSE dvhcx.XP_TEN END
                    ELSE u'' END
                || CASE
                    WHEN NULLIF(TRIM(dvhct.TTP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                               OR NULLIF(TRIM(dvhcx.XP_TEN), u'') IS NOT NULL
                             THEN u', ' || dvhct.TTP_TEN ELSE dvhct.TTP_TEN END
                    ELSE u'' END
            )
            ELSE NULL
        END                                   AS "DiaChi",
        TRIM(rt.THA_TOI_DANH_NAMES)          AS "ToiDanh",
        rt.LL_SO_TIEN_AN                     AS "SoTienAn",
        rt.THA_NGAY_BAT                      AS "NgayBat",
        rt.THA_AN_PHAT                       AS "AnPhat",
        CASE WHEN NVL(rt.SO_LAN_GIAM, 0) = 0 THEN 'Không'
             ELSE TO_CHAR(rt.SO_LAN_GIAM) || ' l?n = ' || NVL(LOWER(TO_CHAR(rt.THOI_GIAN_DA_GIAM)), '')
        END                                  AS "DaGiam",
        CASE WHEN rt.THA_THOI_GIAN_DA_CHAP_HANH IS NULL
              OR rt.THA_THOI_GIAN_DA_CHAP_HANH = '000000' THEN 'Không'
             ELSE TRIM(
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 1, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 1, 2))) || ' n?m ' ELSE '' END ||
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 3, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 3, 2))) || ' tháng ' ELSE '' END ||
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 5, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 5, 2))) || ' ngày' ELSE '' END
             )
        END                                  AS "DaChapHanh",
        CASE WHEN rt.THA_THOI_GIAN_CON_LAI IS NULL
              OR rt.THA_THOI_GIAN_CON_LAI = '000000' THEN 'Không'
             ELSE TRIM(
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 1, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 1, 2))) || ' n?m ' ELSE '' END ||
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 3, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 3, 2))) || ' tháng ' ELSE '' END ||
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 5, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 5, 2))) || ' ngày' ELSE '' END
             )
        END                                  AS "ConLai",
        rt.THA_NGAY_DEN_TRAI                 AS "NgayDenTrai",
        rt.THA_NGAY_HET_HAN                  AS "NgayHetHan",
        hpbs_agg.HINH_PHAT_BO_SUNG           AS "HinhPhatBoSung",
        rt.THA_GHI_CHU_DAC_BIET              AS "GhiChu"
    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
    JOIN DM_TINH_TRANG_PHAM_NHANS tt
        ON rt.LL_TINH_TRANG_ID = tt.ID AND tt.TTPN_MA = 111
    LEFT JOIN DM_GIOI_TINHS dgt
        ON rt.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN HPBS_AGG hpbs_agg
        ON rt.PHAM_NHAN_ID = hpbs_agg.HPBS_MA_PHAM_NHAN
    LEFT JOIN DM_XA_PHUONG dvhcx
        ON rt.LL_DIA_CHI_THUONG_TRU_WARD = dvhcx.ID
    LEFT JOIN DM_TINH_THANH_PHO dvhct
        ON rt.LL_DIA_CHI_THUONG_TRU_PROVICE = dvhct.ID
    WHERE rt.IS_DELETED = 0
      AND (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = p_phan_doi_id)
      AND (p_tu_ngay IS NULL OR (CASE WHEN is_ket_thuc = 1
                                      THEN rt.THA_NGAY_HET_HAN
                                      ELSE rt.THA_NGAY_DEN_TRAI END >= v_tu_ngay))
      AND (p_den_ngay IS NULL OR (CASE WHEN is_ket_thuc = 1
                                       THEN rt.THA_NGAY_HET_HAN
                                       ELSE rt.THA_NGAY_DEN_TRAI END <= v_den_ngay))
      AND (p_gioi_tinh_id IS NULL OR rt.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
      AND (p_quoc_tich_id IS NULL OR rt.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
      AND (p_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = p_trai_giam_id)
    ORDER BY rt.HO_TEN_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            'L?i SP_GET_DS_PHAM_NHAN_KTHS_KHONG_PHAN_DOI: ' || SQLERRM);
END;




/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PHAM_NHAN_KTHS_PHAN_DOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PHAM_NHAN_KTHS_PHAN_DOI" (
    p_phan_doi_id     IN NUMBER DEFAULT NULL,
    p_tu_ngay         IN DATE DEFAULT NULL,
    p_den_ngay        IN DATE DEFAULT NULL,
    p_gioi_tinh_id    IN NUMBER DEFAULT NULL,
    p_quoc_tich_id    IN NUMBER DEFAULT NULL,
    is_ket_thuc       IN NUMBER DEFAULT NULL,
    p_trai_giam_id    IN NUMBER DEFAULT NULL
)
AS
    v_tu_ngay  DATE := NVL(p_tu_ngay, SYSDATE - 1);
    v_den_ngay DATE := NVL(p_den_ngay, SYSDATE);
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    HPBS_AGG AS (
        SELECT hpbs.HPBS_MA_PHAM_NHAN,
               LISTAGG(dmhpbs.HPBS_TEN, ', ')
                   WITHIN GROUP (ORDER BY dmhpbs.HPBS_TEN) AS HINH_PHAT_BO_SUNG
        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
        JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dmhpbs ON hpbs.HPBS_HINH_PHAT = dmhpbs.ID
        WHERE hpbs.IS_DELETED = 0
          AND hpbs.HPBS_MA_PHAM_NHAN IN (
              SELECT rt2.PHAM_NHAN_ID
              FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt2
              JOIN DM_TINH_TRANG_PHAM_NHANS tt2
                  ON rt2.LL_TINH_TRANG_ID = tt2.ID AND tt2.TTPN_MA = 111
              WHERE rt2.IS_DELETED = 0
                AND (p_phan_doi_id IS NULL OR rt2.LL_PHAN_DOI_ID = p_phan_doi_id)
          )
        GROUP BY hpbs.HPBS_MA_PHAM_NHAN
    )
    SELECT
        rt.LL_HO_TEN                         AS "HoTen",
        rt.LL_SO_HO_SO_LAN_DAU               AS "SoHSLD",
        SUBSTR(rt.LL_NGAY_SINH, -4)           AS "NamSinh",
        dgt.GT_TEN                            AS "GioiTinh",
        CASE
            WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dvhcx.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dvhct.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dvhcx.XP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                             THEN u', ' || dvhcx.XP_TEN ELSE dvhcx.XP_TEN END
                    ELSE u'' END
                || CASE
                    WHEN NULLIF(TRIM(dvhct.TTP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                               OR NULLIF(TRIM(dvhcx.XP_TEN), u'') IS NOT NULL
                             THEN u', ' || dvhct.TTP_TEN ELSE dvhct.TTP_TEN END
                    ELSE u'' END
            )
            ELSE NULL
        END                                   AS "DiaChi",
        TRIM(rt.THA_TOI_DANH_NAMES)          AS "ToiDanh",
        rt.LL_SO_TIEN_AN                     AS "SoTienAn",
        rt.THA_NGAY_BAT                      AS "NgayBat",
        rt.THA_AN_PHAT                       AS "AnPhat",
        CASE WHEN NVL(rt.SO_LAN_GIAM, 0) = 0 THEN 'Không'
             ELSE TO_CHAR(rt.SO_LAN_GIAM) || ' l?n = ' || NVL(LOWER(TO_CHAR(rt.THOI_GIAN_DA_GIAM)), '')
        END                                  AS "DaGiam",
        CASE WHEN rt.THA_THOI_GIAN_DA_CHAP_HANH IS NULL
              OR rt.THA_THOI_GIAN_DA_CHAP_HANH = '000000' THEN 'Không'
             ELSE TRIM(
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 1, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 1, 2))) || ' n?m ' ELSE '' END ||
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 3, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 3, 2))) || ' tháng ' ELSE '' END ||
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 5, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 5, 2))) || ' ngày' ELSE '' END
             )
        END                                  AS "DaChapHanh",
        CASE WHEN rt.THA_THOI_GIAN_CON_LAI IS NULL
              OR rt.THA_THOI_GIAN_CON_LAI = '000000' THEN 'Không'
             ELSE TRIM(
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 1, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 1, 2))) || ' n?m ' ELSE '' END ||
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 3, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 3, 2))) || ' tháng ' ELSE '' END ||
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 5, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 5, 2))) || ' ngày' ELSE '' END
             )
        END                                  AS "ConLai",
        rt.THA_NGAY_DEN_TRAI                 AS "NgayDenTrai",
        rt.THA_NGAY_HET_HAN                  AS "NgayHetHan",
        rt.LL_SO_HO_SO_LAN_DAU               AS "SoHoSoLanDau",
        rt.THA_GHI_CHU_DAC_BIET              AS "GhiChu",
        dpd.PD_TEN                           AS "PhanDoi",
        dpt.PT_TEN                           AS "PhanTrai",
        hpbs_agg.HINH_PHAT_BO_SUNG           AS "HinhPhatBoSung"
    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
    JOIN DM_TINH_TRANG_PHAM_NHANS tt
        ON rt.LL_TINH_TRANG_ID = tt.ID AND tt.TTPN_MA = 111
    LEFT JOIN DM_GIOI_TINHS dgt
        ON rt.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_PHAN_DOIS dpd
        ON rt.LL_PHAN_DOI_ID = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt
        ON rt.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN HPBS_AGG hpbs_agg
        ON rt.PHAM_NHAN_ID = hpbs_agg.HPBS_MA_PHAM_NHAN
    LEFT JOIN DM_XA_PHUONG dvhcx
        ON rt.LL_DIA_CHI_THUONG_TRU_WARD = dvhcx.ID
    LEFT JOIN DM_TINH_THANH_PHO dvhct
        ON rt.LL_DIA_CHI_THUONG_TRU_PROVICE = dvhct.ID
    WHERE rt.IS_DELETED = 0
      AND (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = p_phan_doi_id)
      AND (p_tu_ngay IS NULL OR (CASE WHEN is_ket_thuc = 1
                                      THEN rt.THA_NGAY_HET_HAN
                                      ELSE rt.THA_NGAY_DEN_TRAI END >= v_tu_ngay))
      AND (p_den_ngay IS NULL OR (CASE WHEN is_ket_thuc = 1
                                       THEN rt.THA_NGAY_HET_HAN
                                       ELSE rt.THA_NGAY_DEN_TRAI END <= v_den_ngay))
      AND (p_gioi_tinh_id IS NULL OR rt.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
      AND (p_quoc_tich_id IS NULL OR rt.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
      AND (p_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = p_trai_giam_id)
    ORDER BY rt.HO_TEN_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            'L?i SP_GET_DS_PHAM_NHAN_KTHS_PHAN_DOI: ' || SQLERRM);
END;






