      AND pnd.ND_ANH IS NOT NULL 
    ORDER BY rt.HO_TEN_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            'L?i SP_GET_DS_PHAM_NHAN_KTHS_PHAN_DOI_CO_ANH: ' || SQLERRM);
