--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PHAM_NHAN_KTHS_SO_HSLD
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PHAM_NHAN_KTHS_SO_HSLD" (
    p_phan_doi_id     IN NUMBER DEFAULT NULL,
    p_tu_ngay         IN DATE DEFAULT NULL,
    p_den_ngay        IN DATE DEFAULT NULL,
    p_gioi_tinh_id    IN NUMBER DEFAULT NULL,
    p_quoc_tich_id    IN NUMBER DEFAULT NULL,
    is_ket_thuc       IN NUMBER DEFAULT NULL,
    p_trai_giam_id    IN NUMBER DEFAULT NULL
)
AS
    v_tu_ngay  DATE := NVL(p_tu_ngay, SYSDATE - 1);
    v_den_ngay DATE := NVL(p_den_ngay, SYSDATE);
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    HPBS_AGG AS (
        SELECT hpbs.HPBS_MA_PHAM_NHAN,
               LISTAGG(dmhpbs.HPBS_TEN, ', ')
                   WITHIN GROUP (ORDER BY dmhpbs.HPBS_TEN) AS HINH_PHAT_BO_SUNG
        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
        JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dmhpbs ON hpbs.HPBS_HINH_PHAT = dmhpbs.ID
        WHERE hpbs.IS_DELETED = 0
          AND hpbs.HPBS_MA_PHAM_NHAN IN (
              SELECT rt2.PHAM_NHAN_ID
              FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt2
              JOIN DM_TINH_TRANG_PHAM_NHANS tt2
                  ON rt2.LL_TINH_TRANG_ID = tt2.ID AND tt2.TTPN_MA = 111
              WHERE rt2.IS_DELETED = 0
                AND (p_phan_doi_id IS NULL OR rt2.LL_PHAN_DOI_ID = p_phan_doi_id)
          )
        GROUP BY hpbs.HPBS_MA_PHAM_NHAN
    )
    SELECT
        rt.LL_HO_TEN                         AS "HoTen",
        rt.LL_SO_HO_SO_LAN_DAU               AS "SoHSLD",
        SUBSTR(rt.LL_NGAY_SINH, -4)           AS "NamSinh",
        dgt.GT_TEN                            AS "GioiTinh",
        CASE
            WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dvhcx.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dvhct.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dvhcx.XP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                             THEN u', ' || dvhcx.XP_TEN ELSE dvhcx.XP_TEN END
                    ELSE u'' END
                || CASE
                    WHEN NULLIF(TRIM(dvhct.TTP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                               OR NULLIF(TRIM(dvhcx.XP_TEN), u'') IS NOT NULL
                             THEN u', ' || dvhct.TTP_TEN ELSE dvhct.TTP_TEN END
                    ELSE u'' END
            )
            ELSE NULL
        END                                   AS "DiaChi",
        TRIM(rt.THA_TOI_DANH_NAMES)          AS "ToiDanh",
        rt.LL_SO_TIEN_AN                     AS "SoTienAn",
        rt.THA_NGAY_BAT                      AS "NgayBat",
        rt.THA_AN_PHAT                       AS "AnPhat",
        CASE WHEN NVL(rt.SO_LAN_GIAM, 0) = 0 THEN 'Không'
             ELSE TO_CHAR(rt.SO_LAN_GIAM) || ' l?n = ' || NVL(LOWER(TO_CHAR(rt.THOI_GIAN_DA_GIAM)), '')
        END                                  AS "DaGiam",
        CASE WHEN rt.THA_THOI_GIAN_DA_CHAP_HANH IS NULL
              OR rt.THA_THOI_GIAN_DA_CHAP_HANH = '000000' THEN 'Không'
             ELSE TRIM(
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 1, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 1, 2))) || ' n?m ' ELSE '' END ||
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 3, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 3, 2))) || ' tháng ' ELSE '' END ||
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 5, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_DA_CHAP_HANH, 5, 2))) || ' ngày' ELSE '' END
             )
        END                                  AS "DaChapHanh",
        CASE WHEN rt.THA_THOI_GIAN_CON_LAI IS NULL
              OR rt.THA_THOI_GIAN_CON_LAI = '000000' THEN 'Không'
             ELSE TRIM(
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 1, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 1, 2))) || ' n?m ' ELSE '' END ||
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 3, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 3, 2))) || ' tháng ' ELSE '' END ||
                 CASE WHEN TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 5, 2)) > 0
                      THEN TO_CHAR(TO_NUMBER(SUBSTR(rt.THA_THOI_GIAN_CON_LAI, 5, 2))) || ' ngày' ELSE '' END
             )
        END                                  AS "ConLai",
        rt.THA_NGAY_DEN_TRAI                 AS "NgayDenTrai",
        rt.THA_NGAY_HET_HAN                  AS "NgayHetHan",
        rt.LL_SO_HO_SO_LAN_DAU               AS "SoHoSoLanDau",
        rt.THA_GHI_CHU_DAC_BIET              AS "GhiChu",
        dpd.PD_TEN                           AS "PhanDoi",
        dpt.PT_TEN                           AS "PhanTrai",
        hpbs_agg.HINH_PHAT_BO_SUNG           AS "HinhPhatBoSung"
    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
    JOIN DM_TINH_TRANG_PHAM_NHANS tt
        ON rt.LL_TINH_TRANG_ID = tt.ID AND tt.TTPN_MA = 111
    LEFT JOIN DM_GIOI_TINHS dgt
        ON rt.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_PHAN_DOIS dpd
        ON rt.LL_PHAN_DOI_ID = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt
        ON rt.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN HPBS_AGG hpbs_agg
        ON rt.PHAM_NHAN_ID = hpbs_agg.HPBS_MA_PHAM_NHAN
    LEFT JOIN DM_XA_PHUONG dvhcx
        ON rt.LL_DIA_CHI_THUONG_TRU_WARD = dvhcx.ID
    LEFT JOIN DM_TINH_THANH_PHO dvhct
        ON rt.LL_DIA_CHI_THUONG_TRU_PROVICE = dvhct.ID
    WHERE rt.IS_DELETED = 0
      AND (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = p_phan_doi_id)
      AND (p_tu_ngay IS NULL OR (CASE WHEN is_ket_thuc = 1
                                      THEN rt.THA_NGAY_HET_HAN
                                      ELSE rt.THA_NGAY_DEN_TRAI END >= v_tu_ngay))
      AND (p_den_ngay IS NULL OR (CASE WHEN is_ket_thuc = 1
                                       THEN rt.THA_NGAY_HET_HAN
                                       ELSE rt.THA_NGAY_DEN_TRAI END <= v_den_ngay))
      AND (p_gioi_tinh_id IS NULL OR rt.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
      AND (p_quoc_tich_id IS NULL OR rt.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
      AND (p_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = p_trai_giam_id)
    ORDER BY rt.HO_TEN_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            'L?i SP_GET_DS_PHAM_NHAN_KTHS_SO_HSLD: ' || SQLERRM);
END;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PHAM_NHAN_THA_TRUOC_THOI_HAN_CDK
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PHAM_NHAN_THA_TRUOC_THOI_HAN_CDK" (
   p_ten_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_tu_ngay IN NVARCHAR2 DEFAULT NULL,
    p_den_ngay IN NVARCHAR2 DEFAULT NULL
)
AS
    v_ten_trai_giam NVARCHAR2(2000);
    v_tu_ngay NVARCHAR2(10);
    v_den_ngay NVARCHAR2(10);
    C1 SYS_REFCURSOR;  
BEGIN

    IF p_ten_trai_giam IS NULL OR p_ten_trai_giam = '' THEN
        v_ten_trai_giam := NULL;
    ELSE
        v_ten_trai_giam := p_ten_trai_giam;
    END IF;

     IF p_tu_ngay IS NULL OR p_tu_ngay = '' THEN
        v_tu_ngay := to_char(sysdate - 1, 'DD/MM/YYYY');
        ELSE v_tu_ngay := p_tu_ngay;
    END IF;


    IF p_den_ngay IS NULL OR p_den_ngay = '' THEN
        v_den_ngay := to_char(sysdate - 1, 'DD/MM/YYYY');
        ELSE v_den_ngay := p_den_ngay;
    END IF;

      OPEN C1 FOR

WITH GIAM AS
(
SELECT
	PHAM_NHAN_ID
	,LAN_GIAM_AN
    ,CASE 
        WHEN TONG_NGAY IS NULL OR TONG_NGAY = 0 THEN '0'
        ELSE 
            TRUNC(TONG_NGAY / 365) || ' n?m ' ||
            TRUNC(MOD(TONG_NGAY, 365) / 30) || ' tháng ' ||
            MOD(MOD(TONG_NGAY, 365), 30) || ' ngày'
    END AS TONG_GIAM_AN
FROM (
    SELECT 
    	PHAM_NHAN_ID
    	,COUNT(
    		CASE
    			WHEN DA_GIAM IS NULL
    			OR DA_GIAM = 'Không'
    			OR DA_GIAM = ''
    			THEN NULL
    		ELSE 1
    		END
    		) AS LAN_GIAM_AN
        ,SUM(
            NVL(TO_NUMBER(REGEXP_SUBSTR(REPLACE(DA_GIAM, 'Không', '0'), '([0-9]+) n?m', 1, 1, 'i', 1)), 0) * 365 +
            NVL(TO_NUMBER(REGEXP_SUBSTR(REPLACE(DA_GIAM, 'Không', '0'), '([0-9]+) tháng', 1, 1, 'i', 1)), 0) * 30 +
            NVL(TO_NUMBER(REGEXP_SUBSTR(REPLACE(DA_GIAM, 'Không', '0'), '([0-9]+) ngày', 1, 1, 'i', 1)), 0)
        ) as TONG_NGAY
    FROM GIAM_THOI_HANS
    GROUP BY PHAM_NHAN_ID
)
    )
    SELECT LL.GIOI_TINH 
    , LL.HO_TEN  
    , LL.NAM_SINH
    , LL.DIA_CHI_THUONG_TRU
    , LL.SO_TIEN_AN 
    , VTHA.TOI_DANH
    , THA.THA_NGAY_BAT
    , THA.THA_AN_PHAT
    , THA.THA_NGAY_DEN_TRAI
    , GIAM.LAN_GIAM_AN
    , GIAM.TONG_GIAM_AN
    , TCDK.NGAY_THA
    , NULL AS HPBS_TIEN
    , NULL AS HPBS_KHAC
    FROM VW_PN_LAI_LICH_CHI_TIET LL
    LEFT JOIN GIAM
        ON LL.PHAM_NHAN_ID = GIAM.PHAM_NHAN_ID
    LEFT JOIN V_PN_THI_HANH_AN_TOI_DANH VTHA
        ON LL.PHAM_NHAN_ID = VTHA.THA_PNLAI_LICH_ID
    LEFT JOIN PN_THI_HANH_AN THA
        ON LL.PHAM_NHAN_ID = THA.ID
    INNER JOIN THA_CO_DIEU_KIENS TCDK
        ON LL.PHAM_NHAN_ID = TCDK.PHAM_NHAN_ID 
        AND TCDK.TINH_TRANG_ID IN (10,11)
	 AND (v_ten_trai_giam IS NULL  OR UPPER(LL.TRAI_GIAM) = UPPER(v_ten_trai_giam))

            AND  ( TCDK.NGAY_THA BETWEEN TO_TIMESTAMP(v_tu_ngay, 'DD/MM/YYYY') AND  TO_TIMESTAMP(v_den_ngay, 'DD/MM/YYYY'));

      DBMS_SQL.RETURN_RESULT(C1);


--      exec SP_GET_DS_PHAM_NHAN_THA_TRUOC_THOI_HAN_CDK( NULL, '01/01/2025', '01/01/2027');
END;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PHAM_NHAN_THA_TU_TRUOC_THOI_HAN_CDK
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PHAM_NHAN_THA_TU_TRUOC_THOI_HAN_CDK" (
   P_TEN_TRAI_GIAM IN NVARCHAR2 DEFAULT NULL,
    P_TU_NGAY IN NVARCHAR2 DEFAULT NULL,
    P_DEN_NGAY IN NVARCHAR2 DEFAULT NULL
)
AS
    V_TEN_TRAI_GIAM NVARCHAR2(2000);
    V_TU_NGAY NVARCHAR2(10);
    V_DEN_NGAY NVARCHAR2(10);
    C1 SYS_REFCURSOR;  
BEGIN

    IF P_TEN_TRAI_GIAM IS NULL OR P_TEN_TRAI_GIAM = '' THEN
        V_TEN_TRAI_GIAM := NULL;
    ELSE
        V_TEN_TRAI_GIAM := P_TEN_TRAI_GIAM;
    END IF;

     IF P_TU_NGAY IS NULL OR P_TU_NGAY = '' THEN
        V_TU_NGAY := TO_CHAR(SYSDATE - 1, 'DD/MM/YYYY');
        ELSE V_TU_NGAY := P_TU_NGAY;
    END IF;


    IF P_DEN_NGAY IS NULL OR P_DEN_NGAY = '' THEN
        V_DEN_NGAY := TO_CHAR(SYSDATE - 1, 'DD/MM/YYYY');
        ELSE V_DEN_NGAY := P_DEN_NGAY;
    END IF;

      OPEN C1 FOR
        SELECT 
             LL.HO_TEN  
            ,LL.NAM_SINH
            ,LL.GIOI_TINH 
            ,LL.DIA_CHI_THUONG_TRU
            ,VTHA.TOI_DANH
            ,LL.SO_TIEN_AN 
            ,THA.THA_NGAY_BAT
            ,THA.THA_AN_PHAT
            ,THA.THA_NGAY_DEN_TRAI
            , TCDK.NGAY_THA
            , NULL AS KET_QUA_CAI_TAO
            , NULL AS TIEN_TAI_HNCD
        FROM VW_PN_LAI_LICH_CHI_TIET LL
        LEFT JOIN V_PN_THI_HANH_AN_TOI_DANH VTHA ON LL.PHAM_NHAN_ID = VTHA.THA_PNLAI_LICH_ID
        LEFT JOIN PN_THI_HANH_AN THA ON LL.PHAM_NHAN_ID = THA.ID
        INNER JOIN THA_CO_DIEU_KIENS TCDK ON LL.PHAM_NHAN_ID = TCDK.PHAM_NHAN_ID  AND TCDK.TINH_TRANG_ID IN (10,11)
        WHERE   (V_TEN_TRAI_GIAM IS NULL 
                 OR UPPER(LL.TRAI_GIAM) = UPPER(V_TEN_TRAI_GIAM))
          AND (TCDK.NGAY_THA BETWEEN TO_TIMESTAMP(V_TU_NGAY, 'DD/MM/YYYY') AND  TO_TIMESTAMP(V_DEN_NGAY, 'DD/MM/YYYY'))
        ORDER BY LL.HO_TEN  
                ,LL.NAM_SINH
                ,LL.GIOI_TINH 
                ,LL.DIA_CHI_THUONG_TRU;

      DBMS_SQL.RETURN_RESULT(C1);

--      EXEC  SP_GET_DS_PHAM_NHAN_THA_TU_TRUOC_THOI_HAN_CDK (NULL, '01/01/2020', '01/01/2027');
END;            








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PN_CHAP_HANH_TU_THEO_TGIAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PN_CHAP_HANH_TU_THEO_TGIAN" (
    p_phan_doi_id           IN  NUMBER DEFAULT NULL,
    p_ngay_xet              IN  DATE DEFAULT NULL,
    p_muc_an_da_chap_hanh   IN  NUMBER DEFAULT NULL,
    p_maxresultcount        IN  NUMBER    DEFAULT 25,
    p_trai_giam_id          IN  VARCHAR2 DEFAULT NULL,
    p_skipcount             IN  NUMBER    DEFAULT 0   
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_den_ngay DATE;
    v_tu_ngay  DATE;
    v_ratio NUMBER := 0;
    C1         SYS_REFCURSOR;
BEGIN
    v_skip := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    v_ratio := CASE
                    WHEN p_muc_an_da_chap_hanh = 12 THEN 0.5 -- N?u ?ã ch?p hành 1/2 án thì tính là ?ã ch?p hành 50% th?i gian
                    WHEN p_muc_an_da_chap_hanh = 13 THEN 1 / 3 -- N?u ?ã ch?p hành 1/3 án thì tính là ?ã ch?p hành 33.33% th?i gian
                    WHEN p_muc_an_da_chap_hanh = 14 THEN 0.25 -- N?u ?ã ch?p hành 1/4 án thì tính là ?ã ch?p hành 25% th?i gian
                    ELSE 0
                END;
    -- 15: Chung thân ?ã ch?p hành >= 12 n?m <14 n?m
    -- 16: Chung thân ?ã ch?p hành >= 14 n?m

    OPEN C1 FOR
    WITH
    dang_chap_hanh AS (
        SELECT ll.id AS pn_lai_lich_id
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_TRAI_GIAMS traigiam 
        ON ll.LL_TRAI_GIAM_ID = traigiam.ID 
        AND traigiam.IS_DELETED = 0
        WHERE ll.is_deleted = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
          AND (p_trai_giam_id IS NULL OR traigiam.TG_MA = p_trai_giam_id)
          AND (p_phan_doi_id IS NULL OR ll.ll_phan_doi_id = p_phan_doi_id)
          AND ll.ll_tinh_trang_id = 14
          AND ll.ll_so_ho_so_lan_dau IS NOT NULL
    ),
    tha_one AS (
        SELECT tha_pnlai_lich_id, tha_so_ban_an, tha_ngay_bat, tha_ngay_den_trai, tha_ngay_het_han, tha_an_phat, THA_THOI_GIAN_DA_CHAP_HANH,
               ROW_NUMBER() OVER (PARTITION BY tha_pnlai_lich_id ORDER BY tha_ngay_den_trai DESC NULLS LAST) AS rn,
               CASE 
                    WHEN p_muc_an_da_chap_hanh IS NULL THEN 1
                    WHEN p_muc_an_da_chap_hanh IN (12, 13, 14) THEN PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_TY_LE(tha_pnlai_lich_id, v_ratio)
                    WHEN p_muc_an_da_chap_hanh = 15 
                        AND REGEXP_LIKE(THA_THOI_GIAN_DA_CHAP_HANH, '^\s*\d+')
                        AND TO_NUMBER(REGEXP_SUBSTR(THA_THOI_GIAN_DA_CHAP_HANH, '^\s*\d+')) >= 12
                        AND TO_NUMBER(REGEXP_SUBSTR(THA_THOI_GIAN_DA_CHAP_HANH, '^\s*\d+')) < 14
                    THEN 1

                    WHEN p_muc_an_da_chap_hanh = 16
                        AND REGEXP_LIKE(THA_THOI_GIAN_DA_CHAP_HANH, '^\s*\d+')
                        AND TO_NUMBER(REGEXP_SUBSTR(THA_THOI_GIAN_DA_CHAP_HANH, '^\s*\d+')) >= 14
                    THEN 1
                    ELSE 0
               END AS is_condition_matched
        FROM PN_THI_HANH_AN
        WHERE is_deleted = 0
    ),
    base AS (
        SELECT d.pn_lai_lich_id,vw.CCCD, vw.HO_TEN,vw.NGAY_SINH, vw.GIOI_TINH, vw.NAM_SINH, vw.NOI_THUONG_TRU_DAY_DU, vw.TOI_DANH, vw.AN_PHAT,
               vw.NGAY_BAT_AN_PHAT AS vw_ngay_bat, ll.ll_so_ho_so_lan_dau, ll.ll_phan_doi_id, ll.ll_phan_trai_id,
               t.tha_so_ban_an, t.tha_ngay_bat, t.tha_ngay_den_trai, t.tha_ngay_het_han, t.tha_an_phat AS tha_an_phat, t.is_condition_matched,
               (SELECT TO_NCHAR(pd.PD_TEN) FROM DM_PHAN_DOIS pd WHERE pd.id = ll.ll_phan_doi_id AND (pd.is_deleted = 0 OR pd.is_deleted IS NULL) AND ROWNUM = 1) AS ten_phan_doi,
               (SELECT TO_NCHAR(pt.PT_TEN) FROM DM_PHAN_TRAIS pt WHERE pt.id = ll.ll_phan_trai_id AND (pt.is_deleted = 0 OR pt.is_deleted IS NULL) AND ROWNUM = 1) AS ten_phan_trai,
               pha.THA_THOI_GIAN_DA_CHAP_HANH AS DA_CHAP_HANH,
               pha.THA_THOI_GIAN_CON_LAI AS CON_LAI
        FROM dang_chap_hanh d
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET vw ON vw.PHAM_NHAN_ID = d.pn_lai_lich_id
        LEFT JOIN PN_THI_HANH_AN pha ON pha.tha_pnlai_lich_id = d.pn_lai_lich_id AND pha.is_deleted = 0
        LEFT JOIN PN_LAI_LICHS ll ON ll.id = d.pn_lai_lich_id AND ll.is_deleted = 0
        LEFT JOIN tha_one t ON t.tha_pnlai_lich_id = d.pn_lai_lich_id AND t.rn = 1
        WHERE 
        (
            p_ngay_xet IS NULL OR (t.THA_NGAY_HET_HAN IS NOT NULL AND TRUNC(t.THA_NGAY_HET_HAN) >= p_ngay_xet)
            AND (t.THA_NGAY_BAT IS NOT NULL AND TRUNC(t.THA_NGAY_BAT) <= p_ngay_xet)
        )
    )
    SELECT * FROM (
    SELECT
    ROW_NUMBER() OVER (ORDER BY ORDER_HOTEN(b.HO_TEN) DESC NULLS LAST) AS STT,
        TO_NCHAR(b.ll_so_ho_so_lan_dau) AS so_hsld,
        B.CCCD,
        TO_NCHAR(b.HO_TEN) AS ho_ten,
        b.NGAY_SINH AS NGAY_SINH,
        TO_NCHAR(b.GIOI_TINH) AS gioi_tinh,
        TO_NCHAR(b.NOI_THUONG_TRU_DAY_DU) AS NOI_DKTT,
        TO_NCHAR(b.TOI_DANH) AS toi_danh,    
        NVL(b.tha_ngay_bat, b.vw_ngay_bat) AS ngay_bat,
        NVL(b.tha_an_phat, b.AN_PHAT) AS an_phat,
        b.tha_ngay_den_trai AS ngay_den_trai,
        CASE WHEN NULLIF(TRIM(FN_TINH_AN_DA_GIAM(b.pn_lai_lich_id).TONG_GIAM_AN), u'0') IS NULL THEN u'Kh\00f4ng' ELSE FN_TINH_AN_DA_GIAM(b.pn_lai_lich_id).TONG_GIAM_AN END AS da_giam,
        (SELECT MTG_TITLE FROM DM_MA_THOI_GIANS WHERE MTG_MA = b.DA_CHAP_HANH) AS da_chap_hanh,
        CASE WHEN UPPER(NVL(b.tha_an_phat, u'')) LIKE u'%CHUNG THAN%' OR UPPER(NVL(TO_NCHAR(b.AN_PHAT), u'')) LIKE u'%CHUNG THAN%'
            THEN NULL
            ELSE (SELECT MTG_TITLE FROM DM_MA_THOI_GIANS WHERE MTG_MA = b.CON_LAI)
        END AS con_lai,
        b.tha_ngay_het_han AS ngay_het_han,
        	        NVL(TRIM(CAST(b.ten_phan_doi AS VARCHAR2(4000))), '') ||
	        CASE WHEN b.ten_phan_doi IS NOT NULL AND b.ten_phan_trai IS NOT NULL THEN u', ' ELSE u'' END ||
	        NVL(TRIM(CAST(b.ten_phan_trai AS VARCHAR2(4000))), '') AS PHAN_DOI,
        b.is_condition_matched,
        COUNT(*) OVER() AS total_count

    FROM base b
    ORDER BY b.HO_TEN, b.pn_lai_lich_id) T
    WHERE  STT > v_skip
        AND (v_limit = 0 OR STT <= v_skip + v_limit)
        AND (p_muc_an_da_chap_hanh IS NULL OR is_condition_matched = 1)
    ORDER BY STT;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_DS_PN_CHAP_HANH_TU_THEO_TGIAN;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PN_DANG_CHAP_HANH_AN_CHI_TIET
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PN_DANG_CHAP_HANH_AN_CHI_TIET" (
    p_den_ngay              IN  VARCHAR2 DEFAULT NULL,
    p_muc_an_da_chap_hanh   IN  NUMBER   DEFAULT NULL,
   	p_pn_ids IN NVARCHAR2 DEFAULT NULL,
    /*
      DM m?c ?ã ch?p hành (UI 1..5; NULL = t?t c?):
        1 ? MA 012 — ??t 1/2 m?c án (FN_DA_CHAP_HANH_DAT_TY_LE 0,5)
        2 ? MA 013 — ??t 1/3 m?c án (t? l? 1/3)
        3 ? MA 014 — ??t 1/4 m?c án (t? l? 1/4)
        4 ? MA 112 — chung thân, ?ã CHA t? 12 n?m ??n d??i 14 n?m
        5 ? MA 114 — chung thân, ?ã CHA t? 14 n?m tr? lên
    */
    p_phan_doi_id           IN  NUMBER   DEFAULT NULL
) AS
    v_den_ngay DATE;
    C1         SYS_REFCURSOR;
BEGIN
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := TRUNC(SYSDATE);
    ELSE
        v_den_ngay := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
    END IF;

    OPEN C1 FOR
    WITH
    ID_LIST AS (
            SELECT DISTINCT TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
            FROM DUAL
            CONNECT BY LEVEL <= CASE
                    WHEN p_pn_ids IS NULL THEN 0
                    WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                    ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                END
              AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
    ),
    tha_one AS (
        SELECT /*+ MATERIALIZE */
            tha_pnlai_lich_id,
            tha_so_ban_an,
            tha_ngay_bat,
            tha_ngay_den_trai,
            tha_ngay_het_han,
            tha_an_phat,
            ROW_NUMBER() OVER (
                PARTITION BY tha_pnlai_lich_id
                ORDER BY tha_ngay_den_trai DESC NULLS LAST
            ) AS rn
        FROM QLPN.PN_THI_HANH_AN
        WHERE NVL(is_deleted, 0) = 0
    ),
    base AS (
        SELECT
            vw.PHAM_NHAN_ID AS pn_lai_lich_id,
            vw.SO_HO_SO,
            vw.CCCD,
            vw.HO_TEN,
            vw.NGAY_SINH,
            vw.NAM_SINH,
            vw.GIOI_TINH,
            vw.NOI_THUONG_TRU_DAY_DU,
            vw.TOI_DANH,
            vw.AN_PHAT,
            vw.SO_TIEN_AN,
            vw.NGAY_BAT_AN_PHAT AS vw_ngay_bat,
            vw.PHAN_DOI AS phan_doi_ten,
            vw.PHAN_TRAI AS phan_trai_ten,
            t.tha_ngay_bat,
            t.tha_ngay_den_trai,
            t.tha_ngay_het_han,
            t.tha_an_phat AS tha_an_phat
        FROM QLPN.VW_PN_LAI_LICH_CHI_TIET vw
        INNER JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
                ON ttpn.ID = vw.LL_TINH_TRANG_ID
               AND NVL(ttpn.IS_DELETED, 0) = 0
               AND ttpn.TTPN_MA IN ('111', '112', '113', '114')  -- ?ang ch?p hành án
        LEFT JOIN tha_one t ON t.tha_pnlai_lich_id = vw.PHAM_NHAN_ID AND t.rn = 1
        WHERE NVL(vw.IS_DELETED, 0) = 0
          AND EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = vw.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0)
          AND EXISTS (
                SELECT 1
                FROM QLPN.PN_THI_HANH_AN tha
                WHERE NVL(tha.is_deleted, 0) = 0
                  AND tha.tha_pnlai_lich_id = vw.PHAM_NHAN_ID
                  AND tha.tha_pnlai_lich_id IS NOT NULL
--                  AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
--                  AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) <= v_den_ngay
--                  AND (tha.tha_ngay_het_han IS NULL OR tha.tha_ngay_het_han >= v_den_ngay)
          )
          AND (p_phan_doi_id IS NULL OR vw.PHAN_DOI_ID = p_phan_doi_id)
          AND (
                p_muc_an_da_chap_hanh IS NULL
             OR (p_muc_an_da_chap_hanh = 1
                 AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_TY_LE(vw.PHAM_NHAN_ID, 0.5, v_den_ngay) = 1)
             OR (p_muc_an_da_chap_hanh = 2
                 AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_TY_LE(vw.PHAM_NHAN_ID, 1 / 3, v_den_ngay) = 1)
             OR (p_muc_an_da_chap_hanh = 3
                 AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_TY_LE(vw.PHAM_NHAN_ID, 0.25, v_den_ngay) = 1)
             OR (p_muc_an_da_chap_hanh = 4
                 AND EXISTS (
                     SELECT 1
                     FROM QLPN.PN_THI_HANH_AN tha_ct
                     WHERE NVL(tha_ct.is_deleted, 0) = 0
                       AND tha_ct.tha_pnlai_lich_id = vw.PHAM_NHAN_ID
                       AND UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(tha_ct.tha_an_phat), u'')))
                           LIKE '%' || 'CHUNGTHAN' || '%'
                 )
                 AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_SO_NAM(vw.PHAM_NHAN_ID, 12, v_den_ngay) = 1
                 AND NVL(PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_SO_NAM(vw.PHAM_NHAN_ID, 14, v_den_ngay), 0) = 0)
             OR (p_muc_an_da_chap_hanh = 5
                 AND EXISTS (
                     SELECT 1
                     FROM QLPN.PN_THI_HANH_AN tha_ct
                     WHERE NVL(tha_ct.is_deleted, 0) = 0
                       AND tha_ct.tha_pnlai_lich_id = vw.PHAM_NHAN_ID
                       AND UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(tha_ct.tha_an_phat), u'')))
                           LIKE '%' || 'CHUNGTHAN' || '%'
                 )
                 AND PKG_TINH_AN.FN_DA_CHAP_HANH_DAT_SO_NAM(vw.PHAM_NHAN_ID, 14, v_den_ngay) = 1)
          )
    )
    SELECT
        ROW_NUMBER() OVER (ORDER BY b.HO_TEN NULLS LAST, b.pn_lai_lich_id) AS STT,
        CAST(b.SO_HO_SO AS NVARCHAR2(100))                    AS SO_HSLD,
        CAST(b.CCCD AS NVARCHAR2(50))                         AS CCCD,
        TO_NCHAR(b.HO_TEN)                                    AS HO_TEN,
        b.NGAY_SINH                                           AS NGAY_SINH,
        b.NAM_SINH                                            AS NAM_SINH,
        TO_NCHAR(b.GIOI_TINH)                                 AS GIOI_TINH,
        TO_NCHAR(b.NOI_THUONG_TRU_DAY_DU)                     AS NOI_DKTT,
        TO_NCHAR(b.TOI_DANH)                                  AS TOI_DANH,
        TO_NCHAR(b.SO_TIEN_AN)                             AS SO_TA,
        CASE
            WHEN NVL(b.tha_ngay_bat, b.vw_ngay_bat) IS NULL THEN NULL
            ELSE TO_CHAR(NVL(b.tha_ngay_bat, b.vw_ngay_bat), 'DD/MM/YYYY')
        END                                                   AS NGAY_BAT,
        NVL(b.tha_an_phat, b.AN_PHAT)                         AS AN_PHAT,
        CASE
            WHEN b.tha_ngay_den_trai IS NULL THEN NULL
            ELSE TO_CHAR(b.tha_ngay_den_trai, 'DD/MM/YYYY')
        END                                                   AS NGAY_DEN_TRAI,
        NVL(PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(b.pn_lai_lich_id), u'Kh\00f4ng') AS DA_GIAM,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(b.pn_lai_lich_id, v_den_ngay), u'') AS DA_CHAP_HANH,
        CASE
            WHEN UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(b.tha_an_phat), u'')))
                     LIKE '%' || 'CHUNGTHAN' || '%'
                 OR UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(b.AN_PHAT), u'')))
                     LIKE '%' || 'CHUNGTHAN' || '%'
            THEN u'Chung th\00e2n'
            ELSE NVL(
                PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(b.pn_lai_lich_id, v_den_ngay),
                u''
            )
        END                                                   AS CON_LAI,
        CASE
            WHEN b.tha_ngay_het_han IS NULL THEN NULL
            ELSE TO_CHAR(b.tha_ngay_het_han, 'DD/MM/YYYY')
        END                                                   AS NGAY_HET_HAN,
        NVL(TRIM(CAST(b.phan_doi_ten AS NVARCHAR2(500))), u'')
            || CASE
                WHEN TRIM(NVL(CAST(b.phan_doi_ten AS NVARCHAR2(500)), u'')) IS NOT NULL
                 AND LENGTH(TRIM(NVL(CAST(b.phan_doi_ten AS NVARCHAR2(500)), u''))) > 0
                 AND TRIM(NVL(CAST(b.phan_trai_ten AS NVARCHAR2(500)), u'')) IS NOT NULL
                 AND LENGTH(TRIM(NVL(CAST(b.phan_trai_ten AS NVARCHAR2(500)), u''))) > 0
                THEN u', '
                ELSE u''
               END
            || NVL(TRIM(CAST(b.phan_trai_ten AS NVARCHAR2(500))), u'') AS PHAN_DOI,
        b.phan_doi_ten                                        AS TEN_PHAN_DOI,
        b.phan_trai_ten                                       AS TEN_PHAN_TRAI,
        FN_GET_LIET_KE_HPBS_CHI_TIET(b.pn_lai_lich_id)        AS HPBS
    FROM base b
    WHERE (p_pn_ids IS NULL OR b.pn_lai_lich_id IN (SELECT PN_ID FROM ID_LIST))
    ORDER BY b.HO_TEN NULLS LAST, b.pn_lai_lich_id;

    DBMS_SQL.RETURN_RESULT(C1);

    -- EXEC SP_GET_DS_PN_DANG_CHAP_HANH_AN_CHI_TIET('30/03/2026', NULL, NULL);
    -- EXEC SP_GET_DS_PN_DANG_CHAP_HANH_AN_CHI_TIET('30/03/2026', 1, 11);
END SP_GET_DS_PN_DANG_CHAP_HANH_AN_CHI_TIET;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PN_DANG_CHAP_HANH_AN_CHUNG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PN_DANG_CHAP_HANH_AN_CHUNG" (
    p_pn_ids         IN  CLOB DEFAULT NULL
) AS
    v_den_ngay DATE;
    C1         SYS_REFCURSOR;
    v_ids_clean CLOB;
BEGIN
    v_den_ngay := TRUNC(SYSDATE);
    v_ids_clean := REGEXP_REPLACE(p_pn_ids, '[[:space:]\[\]]', '');

    OPEN C1 FOR
    WITH
    pn_ids AS (
        SELECT /*+ MATERIALIZE */
               TO_NUMBER(REGEXP_SUBSTR(v_ids_clean, '[0-9]+', 1, LEVEL)) AS pn_lai_lich_id,
               LEVEL AS id_pos_theo_p_pn_ids
        FROM dual
        CONNECT BY LEVEL <= REGEXP_COUNT(v_ids_clean, '[0-9]+')
    ),
    tha_one AS (
        SELECT /*+ MATERIALIZE */
            tha_pnlai_lich_id,
            tha_so_ban_an,
            tha_ngay_bat,
            tha_ngay_den_trai,
            tha_ngay_het_han,
            tha_an_phat,
            ROW_NUMBER() OVER (
                PARTITION BY tha_pnlai_lich_id
                ORDER BY tha_ngay_den_trai DESC NULLS LAST
            ) AS rn
        FROM QLPN.PN_THI_HANH_AN
        WHERE NVL(is_deleted, 0) = 0
    ),
    base AS (
        SELECT
            p.id_pos_theo_p_pn_ids,
            vw.PHAM_NHAN_ID AS pn_lai_lich_id,
            vw.SO_HO_SO,
            vw.CCCD,
            vw.HO_TEN,
            vw.NGAY_SINH,
            vw.NAM_SINH,
            vw.GIOI_TINH,
            vw.NOI_THUONG_TRU_DAY_DU,
            vw.TOI_DANH,
            vw.SO_TIEN_AN,
            vw.AN_PHAT,
            vw.NGAY_BAT_AN_PHAT AS vw_ngay_bat,
            vw.PHAN_DOI AS phan_doi_ten,
            vw.PHAN_TRAI AS phan_trai_ten,
            t.tha_so_ban_an,
            t.tha_ngay_bat,
            t.tha_ngay_den_trai,
            t.tha_ngay_het_han,
            t.tha_an_phat AS tha_an_phat
        FROM QLPN.VW_PN_LAI_LICH_CHI_TIET vw
        INNER JOIN pn_ids p ON p.pn_lai_lich_id = vw.PHAM_NHAN_ID
        INNER JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
                ON ttpn.ID = vw.LL_TINH_TRANG_ID
               AND NVL(ttpn.IS_DELETED, 0) = 0
        LEFT JOIN tha_one t ON t.tha_pnlai_lich_id = vw.PHAM_NHAN_ID AND t.rn = 1
        WHERE NVL(vw.IS_DELETED, 0) = 0
          AND EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = vw.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0)
          AND EXISTS (
                SELECT 1
                FROM QLPN.PN_THI_HANH_AN tha
                WHERE NVL(tha.is_deleted, 0) = 0
                  AND tha.tha_pnlai_lich_id = vw.PHAM_NHAN_ID
                  AND tha.tha_pnlai_lich_id IS NOT NULL
                  AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) IS NOT NULL
                  AND COALESCE(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) <= v_den_ngay
                  AND (tha.tha_ngay_het_han IS NULL OR tha.tha_ngay_het_han >= v_den_ngay)
          )
    )
    SELECT
        ROW_NUMBER() OVER (ORDER BY b.id_pos_theo_p_pn_ids, b.pn_lai_lich_id) AS STT,
        b.pn_lai_lich_id AS PN_ID,
        CAST(b.SO_HO_SO AS NVARCHAR2(100))                    AS SO_HSLD,
        CAST(b.CCCD AS NVARCHAR2(50))                         AS CCCD,
        TO_NCHAR(b.HO_TEN)                                    AS HO_TEN,
        b.NGAY_SINH                                           AS NGAY_SINH,
        b.NAM_SINH                                            AS NAM_SINH,
        TO_NCHAR(b.GIOI_TINH)                                 AS GIOI_TINH,
        TO_NCHAR(b.NOI_THUONG_TRU_DAY_DU)                     AS NOI_DKTT,
        TO_NCHAR(b.TOI_DANH)                                  AS TOI_DANH,
        b.SO_TIEN_AN                                           AS SO_TA,
        TO_CHAR(NVL(b.tha_ngay_bat, b.vw_ngay_bat), 'DD/MM/YYYY') AS NGAY_BAT,
        NVL(b.tha_an_phat, b.AN_PHAT)                         AS AN_PHAT,
        TO_CHAR(b.tha_ngay_den_trai, 'DD/MM/YYYY')            AS NGAY_DEN_TRAI,
        NVL(PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(b.pn_lai_lich_id), u'Không') AS DA_GIAM,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(b.pn_lai_lich_id, v_den_ngay), u'') AS DA_CHAP_HANH,
        CASE
            WHEN UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(b.tha_an_phat), u'')))
                     LIKE '%' || 'CHUNGTHAN' || '%'
                 OR UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(b.AN_PHAT), u'')))
                     LIKE '%' || 'CHUNGTHAN' || '%'
            THEN u'Chung thân'
            ELSE NVL(
                PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(b.pn_lai_lich_id, v_den_ngay),
                u''
            )
        END                                                   AS CON_LAI,
        TO_CHAR(b.tha_ngay_het_han, 'DD/MM/YYYY')             AS NGAY_HET_HAN,
        NVL(TRIM(CAST(b.phan_doi_ten AS NVARCHAR2(500))), u'')
            || CASE
                WHEN TRIM(NVL(CAST(b.phan_doi_ten AS NVARCHAR2(500)), u'')) IS NOT NULL
                 AND LENGTH(TRIM(NVL(CAST(b.phan_doi_ten AS NVARCHAR2(500)), u''))) > 0
                 AND TRIM(NVL(CAST(b.phan_trai_ten AS NVARCHAR2(500)), u'')) IS NOT NULL
                 AND LENGTH(TRIM(NVL(CAST(b.phan_trai_ten AS NVARCHAR2(500)), u''))) > 0
                THEN u', '
                ELSE u''
               END
            || NVL(TRIM(CAST(b.phan_trai_ten AS NVARCHAR2(500))), u'') AS PHAN_DOI,
        b.phan_doi_ten                                        AS TEN_PHAN_DOI,
        b.phan_trai_ten                                       AS TEN_PHAN_TRAI,
        TO_NCHAR(NVL(QLPN.FN_GHI_CHU_PHAM_NHAN(b.pn_lai_lich_id), u'')) AS GHI_CHU,
        FN_GET_LIET_KE_HPBS_CHI_TIET(b.pn_lai_lich_id)        AS HPBS
    FROM base b
    ORDER BY b.id_pos_theo_p_pn_ids, b.pn_lai_lich_id;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_DS_PN_DANG_CHAP_HANH_AN_CHUNG;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PN_DANG_CHAP_HANH_AN_CO_ANH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PN_DANG_CHAP_HANH_AN_CO_ANH" (
    p_pn_ids         IN  CLOB DEFAULT NULL
) AS
    v_den_ngay DATE;
    C1         SYS_REFCURSOR;
    v_ids_clean CLOB;
BEGIN
    v_den_ngay := TRUNC(SYSDATE);
    v_ids_clean := REGEXP_REPLACE(p_pn_ids, '[[:space:]\[\]]', '');

    OPEN C1 FOR
    WITH
    pn_ids AS (
        SELECT
               TO_NUMBER(REGEXP_SUBSTR(v_ids_clean, '[0-9]+', 1, LEVEL)) AS pn_lai_lich_id,
               LEVEL AS id_pos_theo_p_pn_ids
        FROM dual
        CONNECT BY LEVEL <= REGEXP_COUNT(v_ids_clean, '[0-9]+')
    ),
    tha_one AS (
        SELECT
               tha_pnlai_lich_id, tha_so_ban_an, tha_ngay_bat, tha_ngay_den_trai, tha_ngay_het_han, tha_an_phat,
               ROW_NUMBER() OVER (PARTITION BY tha_pnlai_lich_id ORDER BY tha_ngay_den_trai DESC NULLS LAST) AS rn
        FROM QLPN.PN_THI_HANH_AN
        WHERE NVL(is_deleted, 0) = 0
    ),
    base AS (
        SELECT p.id_pos_theo_p_pn_ids, vw.PHAM_NHAN_ID AS pn_lai_lich_id, vw.HO_TEN, vw.CCCD, vw.GIOI_TINH, vw.NAM_SINH, vw.NOI_THUONG_TRU_DAY_DU, vw.TOI_DANH, vw.AN_PHAT,
               vw.SO_TIEN_AN,
               vw.NGAY_BAT_AN_PHAT AS vw_ngay_bat,
               vw.LL_ANH AS ll_anh,
               vw.GHI_CHU_RIENG AS ll_ghi_chu_rieng,
               vw.PHAN_DOI AS ten_phan_doi,
               vw.PHAN_TRAI AS ten_phan_trai,
               t.tha_so_ban_an, t.tha_ngay_bat, t.tha_ngay_den_trai, t.tha_ngay_het_han, t.tha_an_phat AS tha_an_phat
        FROM QLPN.VW_PN_LAI_LICH_CHI_TIET vw
        INNER JOIN pn_ids p ON p.pn_lai_lich_id = vw.PHAM_NHAN_ID
        INNER JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
                ON ttpn.ID = vw.LL_TINH_TRANG_ID
               AND NVL(ttpn.IS_DELETED, 0) = 0
        LEFT JOIN tha_one t ON t.tha_pnlai_lich_id = vw.PHAM_NHAN_ID AND t.rn = 1
        WHERE NVL(vw.IS_DELETED, 0) = 0
          AND EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = vw.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0)
    ),
    gcr_raw AS (
        SELECT
            b.pn_lai_lich_id,
            REGEXP_REPLACE(NVL(TRIM(CAST(b.ll_ghi_chu_rieng AS VARCHAR2(4000))), ''), '[[:space:]\[\]]', '') AS gcr_clean
        FROM base b
        WHERE b.ll_ghi_chu_rieng IS NOT NULL
          AND REGEXP_COUNT(REGEXP_REPLACE(NVL(TRIM(CAST(b.ll_ghi_chu_rieng AS VARCHAR2(4000))), ''), '[[:space:]\[\]]', ''), '[0-9]+') > 0
    ),
    gcr_ids AS (
        SELECT
            r.pn_lai_lich_id,
            TO_NUMBER(REGEXP_SUBSTR(r.gcr_clean, '[0-9]+', 1, LEVEL)) AS gcr_id,
            LEVEL AS ord
        FROM gcr_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.gcr_clean, '[0-9]+')
          AND PRIOR r.pn_lai_lich_id = r.pn_lai_lich_id
          AND PRIOR SYS_GUID() IS NOT NULL
    ),
    gcr_agg AS (
        SELECT
            ids.pn_lai_lich_id,
            SUBSTR(LISTAGG(CAST(g.GCR_TEN AS VARCHAR2(500)), ', ') WITHIN GROUP (ORDER BY ids.ord), 1, 2000) AS ghi_chu_rieng_ten
        FROM gcr_ids ids
        JOIN QLPN.DM_GHI_CHU_RIENGS g
            ON g.ID = ids.gcr_id
           AND NVL(g.IS_DELETED, 0) = 0
        GROUP BY ids.pn_lai_lich_id
    )
    SELECT
        TO_NCHAR(b.HO_TEN) AS ho_ten,
        CAST(b.CCCD AS NVARCHAR2(50)) AS cccd,
        b.NAM_SINH AS nam_sinh,
        TO_NCHAR(b.GIOI_TINH) AS gioi_tinh,
        TO_NCHAR(b.NOI_THUONG_TRU_DAY_DU) AS dia_chi_thuong_tru,
        TO_NCHAR(b.TOI_DANH) AS toi_danh,
        TO_NCHAR(b.SO_TIEN_AN) AS so_ta,
        TO_NCHAR(TO_CHAR(NVL(b.tha_ngay_bat, b.vw_ngay_bat), 'DD/MM/YYYY')) AS ngay_bat,
        NVL(b.tha_an_phat, b.AN_PHAT) AS an_phat,
        TO_NCHAR(TO_CHAR(b.tha_ngay_den_trai, 'DD/MM/YYYY')) AS ngay_den_trai,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(b.pn_lai_lich_id), u'Không') AS da_giam,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(b.pn_lai_lich_id, v_den_ngay), u'') AS da_chap_hanh,
        CASE WHEN UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(b.tha_an_phat), u''))) LIKE '%' || 'CHUNGTHAN' || '%'
               OR UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(b.AN_PHAT), u''))) LIKE '%' || 'CHUNGTHAN' || '%'
            THEN u'Chung thân'
            ELSE NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(b.pn_lai_lich_id, v_den_ngay), u'')
        END AS con_lai,
        TO_NCHAR(TO_CHAR(b.tha_ngay_het_han, 'DD/MM/YYYY')) AS ngay_het_han,
        QLPN.FN_GET_LIET_KE_HPBS_CHI_TIET(b.pn_lai_lich_id) AS hpbs,
        TO_NCHAR(ga.ghi_chu_rieng_ten) AS GHI_CHU,
        b.ten_phan_doi AS ten_phan_doi,
        b.ten_phan_trai AS ten_phan_trai,
        b.ll_anh AS ll_anh
    FROM base b
    LEFT JOIN gcr_agg ga ON ga.pn_lai_lich_id = b.pn_lai_lich_id
    ORDER BY b.id_pos_theo_p_pn_ids, b.pn_lai_lich_id;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_DS_PN_DANG_CHAP_HANH_AN_CO_ANH;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PN_DANG_CHAP_HANH_AN_CO_HSLD
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PN_DANG_CHAP_HANH_AN_CO_HSLD" (
    p_pn_ids         IN  CLOB DEFAULT NULL
) AS
    v_den_ngay DATE;
    C1         SYS_REFCURSOR;
    v_ids_clean CLOB;
BEGIN
    v_den_ngay := TRUNC(SYSDATE);
    v_ids_clean := REGEXP_REPLACE(p_pn_ids, '[[:space:]\[\]]', '');

    OPEN C1 FOR
    WITH
    pn_ids AS (
        SELECT /*+ MATERIALIZE */
               TO_NUMBER(REGEXP_SUBSTR(v_ids_clean, '[0-9]+', 1, LEVEL)) AS pn_lai_lich_id,
               LEVEL AS id_pos_theo_p_pn_ids
        FROM dual
        CONNECT BY LEVEL <= REGEXP_COUNT(v_ids_clean, '[0-9]+')
    ),
    tha_one AS (
        SELECT /*+ MATERIALIZE */
               tha_pnlai_lich_id, tha_so_ban_an, tha_ngay_bat, tha_ngay_den_trai, tha_ngay_het_han, tha_an_phat,
               ROW_NUMBER() OVER (PARTITION BY tha_pnlai_lich_id ORDER BY tha_ngay_den_trai DESC NULLS LAST) AS rn
        FROM QLPN.PN_THI_HANH_AN
        WHERE NVL(is_deleted, 0) = 0
    ),
    base AS (
        SELECT /*+ MATERIALIZE */
               p.id_pos_theo_p_pn_ids,
               vw.PHAM_NHAN_ID AS pn_lai_lich_id,
               vw.HO_TEN, vw.CCCD, vw.GIOI_TINH, vw.NAM_SINH, vw.NOI_THUONG_TRU_DAY_DU, vw.TOI_DANH, vw.AN_PHAT,
               vw.SO_TIEN_AN,
               vw.NGAY_BAT_AN_PHAT AS vw_ngay_bat,
               vw.SO_HO_SO AS ll_so_ho_so_lan_dau,
               vw.PHAN_DOI AS ten_phan_doi,
               vw.PHAN_TRAI AS ten_phan_trai,
               t.tha_so_ban_an, t.tha_ngay_bat, t.tha_ngay_den_trai, t.tha_ngay_het_han, t.tha_an_phat AS tha_an_phat
        FROM QLPN.VW_PN_LAI_LICH_CHI_TIET vw
        INNER JOIN pn_ids p ON p.pn_lai_lich_id = vw.PHAM_NHAN_ID
        INNER JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
                ON ttpn.ID = vw.LL_TINH_TRANG_ID
               AND NVL(ttpn.IS_DELETED, 0) = 0
        LEFT JOIN tha_one t
               ON t.tha_pnlai_lich_id = vw.PHAM_NHAN_ID
              AND t.rn = 1
        WHERE NVL(vw.IS_DELETED, 0) = 0
          AND EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = vw.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0)
          AND vw.SO_HO_SO IS NOT NULL
          AND (t.tha_ngay_den_trai IS NULL OR TRUNC(t.tha_ngay_den_trai) <= v_den_ngay)
    )
    SELECT
        TO_NCHAR(b.HO_TEN) AS ho_ten,
        CAST(b.CCCD AS NVARCHAR2(50)) AS cccd,
        b.NAM_SINH AS nam_sinh,
        TO_NCHAR(b.GIOI_TINH) AS gioi_tinh,
        TO_NCHAR(b.NOI_THUONG_TRU_DAY_DU) AS dia_chi_thuong_tru,
        TO_NCHAR(b.TOI_DANH) AS toi_danh,
        TO_NCHAR(b.SO_TIEN_AN) AS so_ta,
        TO_NCHAR(TO_CHAR(NVL(b.tha_ngay_bat, b.vw_ngay_bat), 'DD/MM/YYYY')) AS ngay_bat,
        NVL(b.tha_an_phat, b.AN_PHAT) AS an_phat,
        TO_NCHAR(TO_CHAR(b.tha_ngay_den_trai, 'DD/MM/YYYY')) AS ngay_den_trai,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(b.pn_lai_lich_id), u'Không') AS da_giam,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(b.pn_lai_lich_id, v_den_ngay), u'') AS da_chap_hanh,
        CASE WHEN UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(b.tha_an_phat), u''))) LIKE '%' || 'CHUNGTHAN' || '%'
               OR UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(b.AN_PHAT), u''))) LIKE '%' || 'CHUNGTHAN' || '%'
            THEN u'Chung thân'
            ELSE NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(b.pn_lai_lich_id, v_den_ngay), u'')
        END AS con_lai,
        TO_NCHAR(TO_CHAR(b.tha_ngay_het_han, 'DD/MM/YYYY')) AS ngay_het_han,
        QLPN.FN_GET_LIET_KE_HPBS(b.pn_lai_lich_id) AS hpbs,
        b.ten_phan_doi AS ten_phan_doi,
        b.ten_phan_trai AS ten_phan_trai,
        TO_NCHAR(b.ll_so_ho_so_lan_dau) AS so_hsld,
        QLPN.FN_GHI_CHU_PHAM_NHAN(b.pn_lai_lich_id) AS GHI_CHU
    FROM base b
    ORDER BY b.id_pos_theo_p_pn_ids, b.pn_lai_lich_id;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_DS_PN_DANG_CHAP_HANH_AN_CO_HSLD;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PN_DANG_CHAP_HANH_AN_KHONG_ANH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PN_DANG_CHAP_HANH_AN_KHONG_ANH" (
    p_pn_ids         IN  CLOB DEFAULT NULL
) AS
    v_den_ngay DATE;
    C1         SYS_REFCURSOR;
    v_ids_clean CLOB;
BEGIN
    v_den_ngay := TRUNC(SYSDATE);
    v_ids_clean := REGEXP_REPLACE(p_pn_ids, '[[:space:]\[\]]', '');

    OPEN C1 FOR
    WITH
    pn_ids AS (
        SELECT 
               TO_NUMBER(REGEXP_SUBSTR(v_ids_clean, '[0-9]+', 1, LEVEL)) AS pn_lai_lich_id,
               LEVEL AS id_pos_theo_p_pn_ids
        FROM dual
        CONNECT BY LEVEL <= REGEXP_COUNT(v_ids_clean, '[0-9]+')
    ),
    tha_one AS (
        SELECT 
               tha_pnlai_lich_id, tha_so_ban_an, tha_ngay_bat, tha_ngay_den_trai, tha_ngay_het_han, tha_an_phat,
               ROW_NUMBER() OVER (PARTITION BY tha_pnlai_lich_id ORDER BY tha_ngay_den_trai DESC NULLS LAST) AS rn
        FROM QLPN.PN_THI_HANH_AN
        WHERE NVL(is_deleted, 0) = 0
    ),
    base AS (
        SELECT p.id_pos_theo_p_pn_ids, vw.PHAM_NHAN_ID AS pn_lai_lich_id, vw.HO_TEN, vw.CCCD, vw.GIOI_TINH, vw.NAM_SINH, vw.NOI_THUONG_TRU_DAY_DU, vw.TOI_DANH, vw.AN_PHAT,
               vw.SO_TIEN_AN,
               vw.NGAY_BAT_AN_PHAT AS vw_ngay_bat,
               vw.PHAN_DOI AS ten_phan_doi,
               vw.PHAN_TRAI AS ten_phan_trai,
               t.tha_so_ban_an, t.tha_ngay_bat, t.tha_ngay_den_trai, t.tha_ngay_het_han, t.tha_an_phat AS tha_an_phat
        FROM QLPN.VW_PN_LAI_LICH_CHI_TIET vw
        INNER JOIN pn_ids p ON p.pn_lai_lich_id = vw.PHAM_NHAN_ID
        INNER JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
                ON ttpn.ID = vw.LL_TINH_TRANG_ID
               AND NVL(ttpn.IS_DELETED, 0) = 0
        LEFT JOIN tha_one t ON t.tha_pnlai_lich_id = vw.PHAM_NHAN_ID AND t.rn = 1
        WHERE NVL(vw.IS_DELETED, 0) = 0
          AND EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = vw.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0)
    )
    SELECT
        TO_NCHAR(b.HO_TEN) AS ho_ten,
        CAST(b.CCCD AS NVARCHAR2(50)) AS cccd,
        b.NAM_SINH AS nam_sinh,
        TO_NCHAR(b.GIOI_TINH) AS gioi_tinh,
        TO_NCHAR(b.NOI_THUONG_TRU_DAY_DU) AS dia_chi_thuong_tru,
        TO_NCHAR(b.TOI_DANH) AS toi_danh,
        TO_NCHAR(b.SO_TIEN_AN) AS so_ta,
        TO_NCHAR(TO_CHAR(NVL(b.tha_ngay_bat, b.vw_ngay_bat), 'DD/MM/YYYY')) AS ngay_bat,
        NVL(b.tha_an_phat, b.AN_PHAT) AS an_phat,
        TO_NCHAR(TO_CHAR(b.tha_ngay_den_trai, 'DD/MM/YYYY')) AS ngay_den_trai,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(b.pn_lai_lich_id), u'Không') AS da_giam,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(b.pn_lai_lich_id, v_den_ngay), u'') AS da_chap_hanh,
        CASE WHEN UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(b.tha_an_phat), u''))) LIKE '%' || 'CHUNGTHAN' || '%'
               OR UPPER(FN_NORMALIZE_VN(NVL(TO_NCHAR(b.AN_PHAT), u''))) LIKE '%' || 'CHUNGTHAN' || '%'
            THEN u'Chung thân'
            ELSE NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(b.pn_lai_lich_id, v_den_ngay), u'')
        END AS con_lai,
        TO_NCHAR(TO_CHAR(b.tha_ngay_het_han, 'DD/MM/YYYY')) AS ngay_het_han,
        QLPN.FN_GET_LIET_KE_HPBS_CHI_TIET(b.pn_lai_lich_id) AS hpbs,
        b.ten_phan_doi AS ten_phan_doi,
        b.ten_phan_trai AS ten_phan_trai
    FROM base b
    ORDER BY b.id_pos_theo_p_pn_ids, b.pn_lai_lich_id;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_DS_PN_DANG_CHAP_HANH_AN_KHONG_ANH;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PN_DANG_CHAP_HANH_AN_PHAT_TU
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PN_DANG_CHAP_HANH_AN_PHAT_TU" (
    p_phan_doi_id     IN  NUMBER    DEFAULT NULL,
    p_tu_ngay         IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_den_ngay        IN  VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY
    p_gioi_tinh_id  IN  NUMBER    DEFAULT NULL,
    p_quoc_tich_id  IN  NUMBER    DEFAULT NULL,
    p_maxresultcount        IN  NUMBER    DEFAULT NULL,
    p_trai_giam_id          IN  VARCHAR2 DEFAULT NULL,
    p_skipcount             IN  NUMBER    DEFAULT 0   
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_den_ngay DATE;
    v_tu_ngay  DATE;
    C1         SYS_REFCURSOR;
BEGIN
    v_skip := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := TRUNC(SYSDATE);
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;
    OPEN C1 FOR
    WITH
    dang_chap_hanh AS (
        SELECT ll.id AS pn_lai_lich_id
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_TRAI_GIAMS traigiam 
        ON ll.LL_TRAI_GIAM_ID = traigiam.ID 
        AND traigiam.IS_DELETED = 0
        WHERE ll.is_deleted = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
          AND (p_trai_giam_id IS NULL OR traigiam.ID = p_trai_giam_id)
          AND (p_phan_doi_id IS NULL OR ll.ll_phan_doi_id = p_phan_doi_id)
          AND ll.ll_tinh_trang_id = 14
          AND ll.ll_so_ho_so_lan_dau IS NOT NULL
    ),
    tha_one AS (
        SELECT tha_pnlai_lich_id, tha_so_ban_an, tha_ngay_bat, tha_ngay_den_trai, tha_ngay_het_han, tha_an_phat,
               ROW_NUMBER() OVER (PARTITION BY tha_pnlai_lich_id ORDER BY tha_ngay_den_trai DESC NULLS LAST) AS rn
        FROM PN_THI_HANH_AN
        WHERE is_deleted = 0
    ),
    base AS (
        SELECT d.pn_lai_lich_id,vw.CCCD, vw.HO_TEN,vw.NGAY_SINH, vw.GIOI_TINH, vw.NAM_SINH, vw.NOI_THUONG_TRU_DAY_DU, vw.TOI_DANH, vw.AN_PHAT,
               vw.NGAY_BAT_AN_PHAT AS vw_ngay_bat, ll.ll_so_ho_so_lan_dau, ll.ll_phan_doi_id, ll.ll_phan_trai_id,
               t.tha_so_ban_an, t.tha_ngay_bat, t.tha_ngay_den_trai, t.tha_ngay_het_han, t.tha_an_phat AS tha_an_phat,
               (SELECT TO_NCHAR(pd.PD_TEN) FROM DM_PHAN_DOIS pd WHERE pd.id = ll.ll_phan_doi_id AND (pd.is_deleted = 0 OR pd.is_deleted IS NULL) AND ROWNUM = 1) AS ten_phan_doi,
               (SELECT TO_NCHAR(pt.PT_TEN) FROM DM_PHAN_TRAIS pt WHERE pt.id = ll.ll_phan_trai_id AND (pt.is_deleted = 0 OR pt.is_deleted IS NULL) AND ROWNUM = 1) AS ten_phan_trai,
               PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(d.pn_lai_lich_id) AS DA_GIAM,
               MTGCH.MTG_TITLE AS DA_CHAP_HANH,
               MTGCL.MTG_TITLE AS CON_LAI
        FROM dang_chap_hanh d
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET vw ON vw.PHAM_NHAN_ID = d.pn_lai_lich_id
        LEFT JOIN PN_THI_HANH_AN pha ON pha.tha_pnlai_lich_id = d.pn_lai_lich_id AND pha.is_deleted = 0
        LEFT JOIN PN_LAI_LICHS ll ON ll.id = d.pn_lai_lich_id AND ll.is_deleted = 0
        LEFT JOIN tha_one t ON t.tha_pnlai_lich_id = d.pn_lai_lich_id AND t.rn = 1
        LEFT JOIN DM_MA_THOI_GIANS MTGCH ON THA_THOI_GIAN_DA_CHAP_HANH = MTGCH.MTG_MA
        LEFT JOIN DM_MA_THOI_GIANS MTGCL ON THA_THOI_GIAN_CON_LAI = MTGCL.MTG_MA
        WHERE 1=1
--        (
--            p_ngay_xet IS NULL OR (t.THA_NGAY_HET_HAN IS NOT NULL AND TRUNC(t.THA_NGAY_HET_HAN) >= p_ngay_xet)
--            AND (t.THA_NGAY_BAT IS NOT NULL AND TRUNC(t.THA_NGAY_BAT) <= p_ngay_xet)
--        )
            AND (v_tu_ngay IS NULL OR TRUNC(t.THA_NGAY_DEN_TRAI) >= TRUNC(v_tu_ngay))
            AND (v_den_ngay IS NULL OR TRUNC(t.THA_NGAY_DEN_TRAI) <= TRUNC(v_den_ngay))
            AND (p_gioi_tinh_id IS NULL OR  vw.GIOI_TINH_ID = p_gioi_tinh_id )
            AND (p_quoc_tich_id IS NULL OR vw.QUOC_TICH_ID = p_quoc_tich_id)
    )
    SELECT * FROM (
    SELECT
    ROW_NUMBER() OVER (ORDER BY ORDER_HOTEN(b.HO_TEN), b.pn_lai_lich_id DESC NULLS LAST) AS STT,
        TO_NCHAR(b.ll_so_ho_so_lan_dau) AS so_hsld,
        B.CCCD,
        TO_NCHAR(b.HO_TEN) AS ho_ten,
        b.NGAY_SINH AS NGAY_SINH,
        TO_NCHAR(b.GIOI_TINH) AS gioi_tinh,
        TO_NCHAR(b.NOI_THUONG_TRU_DAY_DU) AS NOI_DKTT,
        TO_NCHAR(b.TOI_DANH) AS toi_danh,    
        NVL(b.tha_ngay_bat, b.vw_ngay_bat) AS ngay_bat,
        NVL(b.tha_an_phat, b.AN_PHAT) AS an_phat,
        b.tha_ngay_den_trai AS ngay_den_trai,
        --CASE WHEN NULLIF(TRIM(FN_TINH_AN_DA_GIAM(b.pn_lai_lich_id).TONG_GIAM_AN), u'0') IS NULL THEN u'Kh\00f4ng' ELSE FN_TINH_AN_DA_GIAM(b.pn_lai_lich_id).TONG_GIAM_AN END AS da_giam,
          DA_GIAM,
        b.DA_CHAP_HANH da_chap_hanh,
--        CASE WHEN UPPER(NVL(b.tha_an_phat, u'')) LIKE u'%CHUNG THAN%' OR UPPER(NVL(TO_NCHAR(b.AN_PHAT), u'')) LIKE u'%CHUNG THAN%'
--            THEN NULL
--            ELSE b.CON_LAI
--        END AS con_lai,
CON_LAI,
        b.tha_ngay_het_han AS ngay_het_han,
        	        NVL(TRIM(CAST(b.ten_phan_doi AS VARCHAR2(4000))), '') ||
	        CASE WHEN b.ten_phan_doi IS NOT NULL AND b.ten_phan_trai IS NOT NULL THEN u', ' ELSE u'' END ||
	        NVL(TRIM(CAST(b.ten_phan_trai AS VARCHAR2(4000))), '') AS PHAN_DOI,
        COUNT(*) OVER() AS total_count

    FROM base b 
    ORDER BY ORDER_HOTEN(b.HO_TEN), b.pn_lai_lich_id) T
    WHERE  STT > v_skip
      AND (v_limit = 0 OR STT <= v_skip + v_limit)
    ORDER BY STT;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_DS_PN_DANG_CHAP_HANH_AN_PHAT_TU;
/

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PN_DANG_CHAP_HANH_AN_THEO_PHAN_DOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PN_DANG_CHAP_HANH_AN_THEO_PHAN_DOI" (
    p_ma_trai_giam   IN  VARCHAR2 DEFAULT NULL,
    p_den_ngay       IN  VARCHAR2 DEFAULT NULL,
    p_tu_ngay        IN  VARCHAR2 DEFAULT NULL,
    p_gioi_tinh_id   IN  NUMBER DEFAULT NULL,
    p_quoc_tich_id   IN  NUMBER DEFAULT NULL,
    p_phan_doi_id    IN  NUMBER DEFAULT NULL,
    p_phan_trai_id   IN  NUMBER DEFAULT NULL
) AS
    v_den_ngay DATE;
    v_tu_ngay  DATE;
    C1         SYS_REFCURSOR;
BEGIN
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := TRUNC(SYSDATE);
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN C1 FOR
    WITH
    tha_latest AS (
        SELECT /*+ MATERIALIZE */
               tha_pnlai_lich_id, tha_ngay_den_trai,
               ROW_NUMBER() OVER (PARTITION BY tha_pnlai_lich_id ORDER BY tha_ngay_den_trai DESC NULLS LAST) AS rn
        FROM QLPN.PN_THI_HANH_AN
        WHERE NVL(is_deleted, 0) = 0
    ),
    src AS (
        SELECT /*+ MATERIALIZE */
               ll.ID AS pn_lai_lich_id,
               vw.PHAN_TRAI AS phan_trai_ten,
               vw.PD_TEN AS phan_doi_ten,
               CASE WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) = '1' THEN 1 ELSE 0 END AS is_nam,
               CASE WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) = '2' THEN 1 ELSE 0 END AS is_nu,
               CASE WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) NOT IN ('1', '2') THEN 1 ELSE 0 END AS is_khac
        FROM QLPN.PN_LAI_LICHS ll
        INNER JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
                ON ttpn.ID = ll.LL_TINH_TRANG_ID
               AND NVL(ttpn.IS_DELETED, 0) = 0
                AND ttpn.TTPN_MA ='111'

        INNER JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET vw ON vw.PHAM_NHAN_ID = ll.ID
            AND NVL(vw.IS_DELETED, 0) = 0
          AND EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = vw.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0)
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
               ON gt.ID = ll.LL_DM_GIOI_TINH_ID
              AND NVL(gt.IS_DELETED, 0) = 0
        LEFT JOIN tha_latest t ON t.tha_pnlai_lich_id = ll.ID AND t.rn = 1
        WHERE NVL(ll.is_deleted, 0) = 0
          AND (p_ma_trai_giam IS NULL OR ll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = TO_NCHAR(p_ma_trai_giam)))
          AND (p_phan_trai_id IS NULL OR ll.LL_PHAN_TRAI_ID = p_phan_trai_id)
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
          AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
          AND (v_tu_ngay IS NULL OR (t.tha_ngay_den_trai IS NOT NULL AND TRUNC(t.tha_ngay_den_trai) BETWEEN v_tu_ngay and v_den_ngay))
    ),
    agg_doi AS (
        SELECT
            NVL(s.phan_trai_ten, 'Ch?a xác ??nh') AS phan_trai,
            NVL(s.phan_doi_ten, 'Ch?a xác ??nh') AS phan_doi,
            SUM(s.is_nam) AS so_nam,
            SUM(s.is_nu)  AS so_nu,
            SUM(s.is_khac) AS so_khac,
            SUM(1)        AS tong_so
        FROM src s
        GROUP BY NVL(s.phan_trai_ten, 'Ch?a xác ??nh'), NVL(s.phan_doi_ten, 'Ch?a xác ??nh')
    )
    SELECT phan_trai, phan_doi, so_nam AS nam, so_nu AS nu, so_khac AS so_khac, tong_so
    FROM agg_doi
    ORDER BY phan_trai NULLS LAST, phan_doi NULLS LAST;
    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_DS_PN_DANG_CHAP_HANH_AN_THEO_PHAN_DOI;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PN_DANG_CHAP_HANH_AN_THEO_PHAN_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PN_DANG_CHAP_HANH_AN_THEO_PHAN_TRAI" (
    p_ma_trai_giam   IN  VARCHAR2 DEFAULT NULL,
    p_den_ngay       IN  VARCHAR2 DEFAULT NULL,
    p_tu_ngay        IN  VARCHAR2 DEFAULT NULL,
    p_gioi_tinh_id   IN  NUMBER DEFAULT NULL,
    p_quoc_tich_id   IN  NUMBER DEFAULT NULL,
    p_phan_doi_id    IN  NUMBER DEFAULT NULL,
    p_phan_trai_id   IN  NUMBER DEFAULT NULL
) AS
    v_den_ngay DATE;
    v_tu_ngay  DATE;
    C1         SYS_REFCURSOR;
BEGIN
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := TRUNC(SYSDATE);
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;

    OPEN C1 FOR
    WITH
    tha_latest AS (
        SELECT /*+ MATERIALIZE */
               tha_pnlai_lich_id, tha_ngay_den_trai,
               ROW_NUMBER() OVER (PARTITION BY tha_pnlai_lich_id ORDER BY tha_ngay_den_trai DESC NULLS LAST) AS rn
        FROM QLPN.PN_THI_HANH_AN
        WHERE NVL(is_deleted, 0) = 0
    ),
    eligible AS (
        SELECT /*+ MATERIALIZE */
               ll.ID AS pn_lai_lich_id,
               ll.LL_PHAN_TRAI_ID AS ll_phan_trai_id,
               TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) AS gt_ma_u
        FROM QLPN.PN_LAI_LICHS ll
        INNER JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
                ON ttpn.ID = ll.LL_TINH_TRANG_ID
               AND NVL(ttpn.IS_DELETED, 0) = 0
                AND ttpn.TTPN_MA ='111'

        LEFT JOIN QLPN.DM_GIOI_TINHS gt
               ON gt.ID = ll.LL_DM_GIOI_TINH_ID
              AND NVL(gt.IS_DELETED, 0) = 0
        LEFT JOIN tha_latest t ON t.tha_pnlai_lich_id = ll.ID AND t.rn = 1
        WHERE NVL(ll.is_deleted, 0) = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
          AND (p_ma_trai_giam IS NULL OR ll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = TO_NCHAR(p_ma_trai_giam)))
          AND (p_phan_trai_id IS NULL OR ll.LL_PHAN_TRAI_ID = p_phan_trai_id)
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
          AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
          AND (v_tu_ngay IS NULL OR (t.tha_ngay_den_trai IS NOT NULL AND TRUNC(t.tha_ngay_den_trai) BETWEEN v_tu_ngay and v_den_ngay))
    ),
    src AS (
        SELECT
            d.pn_lai_lich_id,
            (SELECT pt.PT_TEN
             FROM QLPN.DM_PHAN_TRAIS pt
             WHERE pt.id = d.ll_phan_trai_id AND (pt.is_deleted = 0 OR pt.is_deleted IS NULL)
             AND ROWNUM = 1) AS don_vi_ten,
            CASE WHEN d.gt_ma_u = '1' THEN 1 ELSE 0 END AS is_nam,
            CASE WHEN d.gt_ma_u = '2' THEN 1 ELSE 0 END AS is_nu,
            CASE WHEN d.gt_ma_u NOT IN ('1', '2') THEN 1 ELSE 0 END AS is_khac
        FROM eligible d
    ),
    agg AS (
        SELECT
            NVL(s.don_vi_ten, 'Ch?a xác ??nh') AS don_vi,
            SUM(s.is_nam) AS so_nam,
            SUM(s.is_nu)  AS so_nu,
            SUM(s.is_khac) AS so_khac,
            SUM(1)        AS tong_so
        FROM src s
        GROUP BY NVL(s.don_vi_ten, 'Ch?a xác ??nh')
    ),
    with_rows AS (
        SELECT a.don_vi AS don_vi, a.so_nam AS nam, a.so_nu AS nu, a.so_khac AS so_khac, a.tong_so AS tong_so
        FROM agg a
    )
    SELECT don_vi, nam, nu, so_khac, tong_so FROM with_rows
    ORDER BY don_vi;
    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_DS_PN_DANG_CHAP_HANH_AN_THEO_PHAN_TRAI;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PN_DE_NGHI_THA_CO_DK
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PN_DE_NGHI_THA_CO_DK" (
    p_pn_ids            IN  NVARCHAR2  DEFAULT NULL,
    p_dot_tha_id        IN  NUMBER     DEFAULT NULL,
    p_phan_doi_id       IN  NUMBER     DEFAULT NULL,
    p_doi_tuong_id      IN  NUMBER     DEFAULT NULL,
    p_tinh_trang_tha_id IN  NUMBER     DEFAULT NULL,
    p_nghien_ma_tuy     IN  NUMBER     DEFAULT NULL,
    p_quoc_tich         IN  NUMBER     DEFAULT NULL,
    p_tim_kiem          IN  NVARCHAR2  DEFAULT NULL,
    p_ma_trai_giam IN  VARCHAR2  DEFAULT NULL,
    p_maxresultcount    IN  NUMBER     DEFAULT 0,
    p_skipcount         IN  NUMBER     DEFAULT 0,
    p_id_list_result OUT CLOB         -- << THEM: danh sach ID thoa man
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    c1      SYS_REFCURSOR;

    /* ------------------------------------------------------------------ */
    /* Macro CTE dung chung cho ca 2 truy van (ID + data)                 */
    /* Dinh nghia 1 lan, dung 2 lan bang cach inline vao tung WITH block  */
    /* ------------------------------------------------------------------ */
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    /* ================================================================== */
    /* BUOC 1: Lay danh sach ID thoa man toan bo dieu kien (khong phan trang) */
    /* ================================================================== */
    SELECT
        -- LISTAGG toan bo ID, khong bi cat boi OFFSET/FETCH
	RTRIM(XMLAGG(XMLELEMENT(e, TO_CHAR(sub.PHAM_NHAN_ID) || ',')
	    ORDER BY sub.PHAM_NHAN_ID).EXTRACT('//text()').GETCLOBVAL(), ',')
    INTO p_id_list_result
    FROM (
        WITH
        ID_LIST AS (
            SELECT DISTINCT
                TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
            FROM DUAL
            CONNECT BY LEVEL <= CASE
                    WHEN p_pn_ids IS NULL           THEN 0
                    WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                    ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                END
              AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
        ),
        trai_filter AS (
            SELECT dtg.ID AS TRAI_GIAM_ID
            FROM DM_TRAI_GIAMS dtg
            WHERE p_ma_trai_giam IS NOT NULL
              AND TRIM(p_ma_trai_giam) IS NOT NULL
              AND dtg.TG_MA = p_ma_trai_giam
              AND NVL(dtg.IS_DELETED, 0) = 0
              AND ROWNUM = 1
        ),
        tha_one AS (
            SELECT DISTINCT
               t.ID AS tha_co_dieu_kien_id,
                   t.PHAM_NHAN_ID,
                   t.SO_QUYET_DINH_THA AS so_quyet_dinh,
                   t.NGAY_XET,
                   t.TINH_TRANG_ID
            FROM THA_CO_DIEU_KIENS t
            LEFT JOIN PN_DOT_THA_CO_DIEU_KIENS dot
                ON TRUNC(t.NGAY_XET) = TRUNC(dot.DTCDK_NGAY_XET)
               AND NVL(dot.IS_DELETED, 0) = 0
            WHERE NVL(t.IS_DELETED, 0) = 0
              AND (p_pn_ids IS NULL OR t.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
              AND (p_dot_tha_id IS NULL OR dot.ID = p_dot_tha_id)
              AND (p_tinh_trang_tha_id IS NULL OR t.TINH_TRANG_ID = p_tinh_trang_tha_id)
        ),
        tha_pn AS (
            SELECT DISTINCT PHAM_NHAN_ID FROM tha_one
        ),
        base_toi AS (
            SELECT v.PHAM_NHAN_ID,
                   v.HO_TEN,
                   v.PHAN_DOI_ID,
                   v.CCCD,
                   v.TOI_DANH_ID,
                   v.QUOC_TICH_ID,
                   dm.TD_CHUONG AS td_chuong,
                   qt.QT_MA     AS quoc_tich_ma
            FROM tha_pn t
            INNER JOIN VW_PN_LAI_LICH_CHI_TIET v
                ON v.PHAM_NHAN_ID = t.PHAM_NHAN_ID
               AND NVL(v.IS_DELETED, 0) = 0
            LEFT JOIN DM_TOI_DANHS dm
                ON dm.ID = TO_NUMBER(REGEXP_SUBSTR(NVL(TRIM(CAST(v.TOI_DANH_ID AS VARCHAR2(2000))), ''), '[0-9]+', 1, 1))
               AND NVL(dm.IS_DELETED, 0) = 0
            LEFT JOIN DM_QUOC_TICHS qt
                ON qt.ID = v.QUOC_TICH_ID
               AND NVL(qt.IS_DELETED, 0) = 0
            WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = v.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND (
                    p_ma_trai_giam IS NULL
                 OR v.TRAI_GIAM_ID IN (SELECT TRAI_GIAM_ID FROM trai_filter)
            )
        ),
        nghien_mt AS (
            SELECT DISTINCT nmt.NMT_PN_LAI_LICH_ID AS PHAM_NHAN_ID
            FROM PN_NGHIEN_MT nmt
            INNER JOIN tha_pn t ON t.PHAM_NHAN_ID = nmt.NMT_PN_LAI_LICH_ID
            WHERE NVL(nmt.IS_DELETED, 0) = 0
        )
        SELECT DISTINCT t.PHAM_NHAN_ID
        FROM tha_one t
        INNER JOIN base_toi bt ON bt.PHAM_NHAN_ID = t.PHAM_NHAN_ID
        LEFT JOIN  nghien_mt nm ON nm.PHAM_NHAN_ID = t.PHAM_NHAN_ID
        WHERE 1 = 1
          AND (p_phan_doi_id IS NULL OR bt.PHAN_DOI_ID = p_phan_doi_id)
          AND (p_doi_tuong_id IS NULL
               OR (p_doi_tuong_id = 1 AND TRIM(CAST(NVL(bt.td_chuong, '') AS VARCHAR2(10))) = '13')
               OR (p_doi_tuong_id = 2 AND (bt.td_chuong IS NULL
                   OR TRIM(CAST(NVL(bt.td_chuong, '') AS VARCHAR2(10))) <> '13')))
          AND (p_quoc_tich IS NULL
               OR (p_quoc_tich = 250 AND TRIM(CAST(NVL(bt.quoc_tich_ma, '') AS VARCHAR2(20))) = '250')
               OR (p_quoc_tich = 999 AND (bt.quoc_tich_ma IS NULL
                   OR TRIM(CAST(NVL(bt.quoc_tich_ma, '') AS VARCHAR2(20))) <> '250')))
          AND (p_tim_kiem IS NULL OR TRIM(p_tim_kiem) = ''
               OR UPPER(CAST(NVL(bt.HO_TEN, '') AS VARCHAR2(2000)))
                    LIKE '%' || UPPER(TRIM(CAST(NVL(p_tim_kiem, '') AS VARCHAR2(2000)))) || '%'
               OR UPPER(CAST(NVL(bt.CCCD, '') AS VARCHAR2(200)))
                    LIKE '%' || UPPER(TRIM(CAST(NVL(p_tim_kiem, '') AS VARCHAR2(200)))) || '%')
          AND (p_nghien_ma_tuy IS NULL
               OR (p_nghien_ma_tuy = 1 AND nm.PHAM_NHAN_ID IS NOT NULL)
               OR (p_nghien_ma_tuy = 2 AND nm.PHAM_NHAN_ID IS NULL))
    ) sub;

    /* ================================================================== */
    /* BUOC 2: Mo cursor tra du lieu phan trang (giu nguyen logic cu)     */
    /* ================================================================== */
    OPEN c1 FOR
    WITH
    ID_LIST AS (
        SELECT DISTINCT
            TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
        FROM DUAL
        CONNECT BY LEVEL <= CASE
                WHEN p_pn_ids IS NULL           THEN 0
                WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
            END
          AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
    ),
    trai_filter AS (
        SELECT dtg.ID AS TRAI_GIAM_ID
        FROM DM_TRAI_GIAMS dtg
        WHERE p_ma_trai_giam IS NOT NULL
          AND TRIM(p_ma_trai_giam) IS NOT NULL
          AND dtg.TG_MA = p_ma_trai_giam
          AND NVL(dtg.IS_DELETED, 0) = 0
          AND ROWNUM = 1
    ),
    tha_one AS (
        SELECT DISTINCT
               t.ID AS tha_co_dieu_kien_id,
               t.PHAM_NHAN_ID,
               t.SO_QUYET_DINH_THA AS so_quyet_dinh,
               t.NGAY_XET,
               t.TINH_TRANG_ID,
               t.NGAY_THA,
               t.TG_CH_TT,
               t.GIAM_AN_TT,
               t.TG_CON_LAI_TT
        FROM THA_CO_DIEU_KIENS t
        LEFT JOIN PN_DOT_THA_CO_DIEU_KIENS dot
            ON TRUNC(t.NGAY_XET) = TRUNC(dot.DTCDK_NGAY_XET)
           AND NVL(dot.IS_DELETED, 0) = 0
        WHERE NVL(t.IS_DELETED, 0) = 0
          AND (p_pn_ids IS NULL OR t.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
          AND (p_dot_tha_id IS NULL OR dot.ID = p_dot_tha_id)
          AND (p_tinh_trang_tha_id IS NULL OR t.TINH_TRANG_ID = p_tinh_trang_tha_id)
    ),
    tha_pn AS (
        SELECT DISTINCT PHAM_NHAN_ID FROM tha_one
    ),
    base_toi AS (
        SELECT v.PHAM_NHAN_ID,
               v.HO_TEN, v.NGAY_SINH, v.NAM_SINH, v.GIOI_TINH,
               v.NGUYEN_QUAN, v.NOI_THUONG_TRU_DAY_DU,
               v.NOI_THA_VE_CU_TRU, v.NOI_THA_VE_CU_TRU_XA, v.NOI_THA_VE_CU_TRU_TINH,
               v.DAN_TOC, v.TON_GIAO, v.QUOC_TICH, v.HOC_VAN, v.NGHE_NGHIEP,
               v.SO_TIEN_AN, v.TOI_DANH, v.NGAY_BAT_AN_PHAT, v.AN_PHAT, v.NGAY_HET_AN,
               v.PHAN_DOI_ID, v.PHAN_DOI, v.PHAN_TRAI, v.TOI_DANH_ID, v.CCCD,
               v.SO_BAN_AN, v.NGAY_BAN_AN, v.TOA_XU_TEN, v.TOA_XU_DIA_PHUONG,
               v.SO_QD_THA, v.NGAY_QD_THA, v.CO_QUAN_QD_THA, v.TOA_QD_THA_DIA_PHUONG,
               v.NGAY_DEN_TRAI, v.TRAI_GIAM, v.TRAI_GIAM_ID, v.THOI_GIAN_TAM_GIAM,
               v.GHI_CHU_RIENG, v.GHI_CHU_CHI_TIET, v.SO_TIEN_SU, v.TT_SUC_KHOE_HIEN_TAI,
               dm.TD_CHUONG AS td_chuong,
               qt.QT_MA     AS quoc_tich_ma
        FROM tha_pn t
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = t.PHAM_NHAN_ID
           AND NVL(v.IS_DELETED, 0) = 0
        LEFT JOIN DM_TOI_DANHS dm
            ON dm.ID = TO_NUMBER(REGEXP_SUBSTR(NVL(TRIM(CAST(v.TOI_DANH_ID AS VARCHAR2(2000))), ''), '[0-9]+', 1, 1))
           AND NVL(dm.IS_DELETED, 0) = 0
        LEFT JOIN DM_QUOC_TICHS qt
            ON qt.ID = v.QUOC_TICH_ID
           AND NVL(qt.IS_DELETED, 0) = 0
        WHERE (
                p_ma_trai_giam IS NULL
             OR v.TRAI_GIAM_ID IN (SELECT TRAI_GIAM_ID FROM trai_filter)
        )
    ),
    gcr_raw AS (
        SELECT bt.PHAM_NHAN_ID,
               REGEXP_REPLACE(NVL(TRIM(CAST(bt.GHI_CHU_RIENG AS VARCHAR2(2000))), ''), '[[:space:]\[\]]', '') AS gcr_clean
        FROM base_toi bt
        WHERE bt.GHI_CHU_RIENG IS NOT NULL
          AND REGEXP_COUNT(REGEXP_REPLACE(NVL(TRIM(CAST(bt.GHI_CHU_RIENG AS VARCHAR2(2000))), ''), '[[:space:]\[\]]', ''), '[0-9]+') > 0
    ),
    gcr_ids AS (
        SELECT r.PHAM_NHAN_ID,
               TO_NUMBER(REGEXP_SUBSTR(r.gcr_clean, '[0-9]+', 1, LEVEL)) AS gcr_id,
               LEVEL AS ord
        FROM gcr_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.gcr_clean, '[0-9]+')
          AND PRIOR r.PHAM_NHAN_ID = r.PHAM_NHAN_ID
          AND PRIOR SYS_GUID() IS NOT NULL
    ),
    gcr_agg AS (
        SELECT ids.PHAM_NHAN_ID,
               LISTAGG(CAST(g.GCR_TEN AS VARCHAR2(500)), ', ')
                   WITHIN GROUP (ORDER BY ids.ord) AS tinh_tiet_uu_tien
        FROM (
            SELECT ids2.*,
                   ROW_NUMBER() OVER (PARTITION BY ids2.PHAM_NHAN_ID ORDER BY ids2.ord) AS rn
            FROM gcr_ids ids2
        ) ids
        JOIN DM_GHI_CHU_RIENGS g ON g.ID = ids.gcr_id AND NVL(g.IS_DELETED, 0) = 0
        WHERE ids.rn <= 30
        GROUP BY ids.PHAM_NHAN_ID
    ),
    nghien_mt AS (
        SELECT DISTINCT nmt.NMT_PN_LAI_LICH_ID AS PHAM_NHAN_ID
        FROM PN_NGHIEN_MT nmt
        INNER JOIN tha_pn t ON t.PHAM_NHAN_ID = nmt.NMT_PN_LAI_LICH_ID
        WHERE NVL(nmt.IS_DELETED, 0) = 0
    ),
    ds AS (
        SELECT t.PHAM_NHAN_ID, t.tha_co_dieu_kien_id, t.so_quyet_dinh, t.NGAY_XET,
               t.NGAY_THA, t.TG_CH_TT, t.GIAM_AN_TT, t.TG_CON_LAI_TT,
               bt.HO_TEN, bt.NGAY_SINH, bt.NAM_SINH, bt.GIOI_TINH, bt.NGUYEN_QUAN,
               bt.NOI_THUONG_TRU_DAY_DU, bt.NOI_THA_VE_CU_TRU,
               bt.NOI_THA_VE_CU_TRU_XA, bt.NOI_THA_VE_CU_TRU_TINH,
               bt.DAN_TOC, bt.TON_GIAO, bt.QUOC_TICH, bt.HOC_VAN, bt.NGHE_NGHIEP,
               bt.SO_TIEN_AN, bt.TOI_DANH, bt.NGAY_BAT_AN_PHAT, bt.AN_PHAT, bt.NGAY_HET_AN,
               bt.PHAN_DOI_ID, bt.PHAN_DOI, bt.PHAN_TRAI, bt.td_chuong, bt.quoc_tich_ma,
               bt.CCCD, bt.SO_BAN_AN, bt.NGAY_BAN_AN, bt.TOA_XU_TEN, bt.TOA_XU_DIA_PHUONG,
               bt.SO_QD_THA, bt.NGAY_QD_THA, bt.CO_QUAN_QD_THA, bt.TOA_QD_THA_DIA_PHUONG,
               bt.NGAY_DEN_TRAI, bt.TRAI_GIAM, bt.THOI_GIAN_TAM_GIAM,
               bt.GHI_CHU_CHI_TIET, bt.SO_TIEN_SU, bt.TT_SUC_KHOE_HIEN_TAI
        FROM tha_one t
        INNER JOIN base_toi bt ON bt.PHAM_NHAN_ID = t.PHAM_NHAN_ID
        LEFT JOIN  nghien_mt nm ON nm.PHAM_NHAN_ID = t.PHAM_NHAN_ID
        WHERE 1 = 1
          AND (p_phan_doi_id IS NULL OR bt.PHAN_DOI_ID = p_phan_doi_id)
          AND (p_doi_tuong_id IS NULL
               OR (p_doi_tuong_id = 1 AND TRIM(CAST(NVL(bt.td_chuong, '') AS VARCHAR2(10))) = '13')
               OR (p_doi_tuong_id = 2 AND (bt.td_chuong IS NULL
                   OR TRIM(CAST(NVL(bt.td_chuong, '') AS VARCHAR2(10))) <> '13')))
          AND (p_quoc_tich IS NULL
               OR (p_quoc_tich = 250 AND TRIM(CAST(NVL(bt.quoc_tich_ma, '') AS VARCHAR2(20))) = '250')
               OR (p_quoc_tich = 999 AND (bt.quoc_tich_ma IS NULL
                   OR TRIM(CAST(NVL(bt.quoc_tich_ma, '') AS VARCHAR2(20))) <> '250')))
          AND (p_tim_kiem IS NULL OR TRIM(p_tim_kiem) = ''
               OR UPPER(CAST(NVL(bt.HO_TEN, '') AS VARCHAR2(2000)))
                    LIKE '%' || UPPER(TRIM(CAST(NVL(p_tim_kiem, '') AS VARCHAR2(2000)))) || '%'
               OR UPPER(CAST(NVL(bt.CCCD, '') AS VARCHAR2(200)))
                    LIKE '%' || UPPER(TRIM(CAST(NVL(p_tim_kiem, '') AS VARCHAR2(200)))) || '%')
          AND (p_nghien_ma_tuy IS NULL
               OR (p_nghien_ma_tuy = 1 AND nm.PHAM_NHAN_ID IS NOT NULL)
               OR (p_nghien_ma_tuy = 2 AND nm.PHAM_NHAN_ID IS NULL))
    )
    SELECT
        d.PHAM_NHAN_ID                                                                      AS pham_nhan_id,
        NVL(TRIM(CAST(d.HO_TEN AS VARCHAR2(2000))), '')                                     AS ho_ten,
        NVL(TRIM(CAST(d.GIOI_TINH AS VARCHAR2(2000))), '')                                  AS gioi_tinh,
        CASE
            WHEN d.NGAY_SINH IS NOT NULL
             AND REGEXP_LIKE(TRIM(CAST(d.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(CAST(d.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN d.NAM_SINH IS NOT NULL AND d.NAM_SINH > 0 THEN TO_CHAR(d.NAM_SINH)
            WHEN d.NGAY_SINH IS NOT NULL THEN TRIM(CAST(d.NGAY_SINH AS VARCHAR2(100)))
            ELSE NULL
        END                                                                                  AS ngay_sinh,
        NVL(TRIM(CAST(d.NGUYEN_QUAN AS VARCHAR2(2000))), '')                                AS nguyen_quan,
        NVL(TRIM(CAST(d.NOI_THUONG_TRU_DAY_DU AS VARCHAR2(2000))), '')                      AS noi_dktt,
        SUBSTR(
            NVL(TRIM(CAST(d.NOI_THA_VE_CU_TRU AS VARCHAR2(2000))), '')
            || CASE WHEN d.NOI_THA_VE_CU_TRU_XA   IS NOT NULL THEN u', ' || NVL(TRIM(CAST(d.NOI_THA_VE_CU_TRU_XA   AS VARCHAR2(500))), '') ELSE u'' END
            || CASE WHEN d.NOI_THA_VE_CU_TRU_TINH IS NOT NULL THEN u', ' || NVL(TRIM(CAST(d.NOI_THA_VE_CU_TRU_TINH AS VARCHAR2(500))), '') ELSE u'' END,
        1, 2000)                                                                             AS noi_tha_ve_cu_tru,
        NVL(TRIM(CAST(d.DAN_TOC    AS VARCHAR2(2000))), '')                                  AS dan_toc,
        NVL(TRIM(CAST(d.TON_GIAO   AS VARCHAR2(2000))), '')                                  AS ton_giao,
        NVL(TRIM(CAST(d.QUOC_TICH  AS VARCHAR2(2000))), '')                                  AS quoc_tich,
        NVL(TRIM(CAST(d.HOC_VAN    AS VARCHAR2(2000))), '')                                  AS hoc_van,
        NVL(TRIM(CAST(d.NGHE_NGHIEP AS VARCHAR2(2000))), '')                                 AS nghe_nghiep,
        NVL(TRIM(CAST(d.TOI_DANH   AS VARCHAR2(2000))), '')                                  AS toi_danh,
        d.NGAY_BAT_AN_PHAT                                                                   AS ngay_bat,
        NVL(TRIM(CAST(d.AN_PHAT    AS VARCHAR2(2000))), '')                                  AS an_phat,
        NVL(TRIM(CAST(d.SO_BAN_AN  AS VARCHAR2(2000))), '')                                  AS so_ban_an,
        CASE WHEN d.NGAY_BAN_AN  IS NOT NULL THEN TO_CHAR(d.NGAY_BAN_AN,  'DD/MM/YYYY') ELSE NULL END AS ngay_ban_an,
        SUBSTR(TRIM(
            NVL(CAST(d.TOA_XU_TEN AS VARCHAR2(500)), '')
            || NVL2(d.TOA_XU_DIA_PHUONG, u', ' || CAST(d.TOA_XU_DIA_PHUONG AS VARCHAR2(500)), '')
        ), 1, 2000)                                                                          AS toa_xu,
        NVL(TRIM(CAST(d.SO_QD_THA  AS VARCHAR2(2000))), '')                                  AS so_qd_tha,
        CASE WHEN d.NGAY_QD_THA  IS NOT NULL THEN TO_CHAR(d.NGAY_QD_THA,  'DD/MM/YYYY') ELSE NULL END AS ngay_qd_tha,
        NVL(TRIM(CAST(d.CO_QUAN_QD_THA       AS VARCHAR2(2000))), '')                        AS co_quan_qd_tha,
        NVL(TRIM(CAST(d.TOA_QD_THA_DIA_PHUONG AS VARCHAR2(2000))), '')                       AS toa_qd_tha_dia_phuong,
        CASE WHEN d.NGAY_DEN_TRAI IS NOT NULL THEN TO_CHAR(d.NGAY_DEN_TRAI, 'DD/MM/YYYY') ELSE NULL END AS ngay_den_trai,
        NVL(TRIM(CAST(d.TRAI_GIAM  AS VARCHAR2(2000))), '')                                  AS trai_giam,
        -- ?ã có NGAY_THA (?ã ra quy?t ??nh tha) => ?óng b?ng, l?y snapshot l?u t?i th?i ?i?m ?? ngh?
        -- (TG_CH_TT/GIAM_AN_TT/TG_CON_LAI_TT), KHÔNG g?i l?i PKG_TINH_AN (?ã ??i tr?ng thái PN
        -- sau khi có NGAY_THA nên tính l?i cho k?t qu? sai/"Không").
        CASE WHEN d.NGAY_THA IS NOT NULL
             THEN NVL(TRIM(CAST(d.TG_CH_TT AS NVARCHAR2(2000))), u'')
             ELSE NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(d.PHAM_NHAN_ID, d.NGAY_XET), u'')
        END                                                                                  AS tg_chap_hanh,
        CASE WHEN d.NGAY_THA IS NOT NULL
             THEN NVL(TRIM(CAST(d.GIAM_AN_TT AS NVARCHAR2(2000))), u'Khong')
             ELSE NVL(PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(d.PHAM_NHAN_ID), u'Khong')
        END                                                                                  AS tg_da_giam,
        CASE WHEN d.NGAY_THA IS NOT NULL
             THEN NVL(TRIM(CAST(d.TG_CON_LAI_TT AS NVARCHAR2(2000))), u'')
             ELSE NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(d.PHAM_NHAN_ID, d.NGAY_XET), u'')
        END                                                                                  AS tg_con_lai,
        SUBSTR(NVL(CAST(FN_GET_LIET_KE_HPBS_CHI_TIET(d.PHAM_NHAN_ID) AS NVARCHAR2(2000)), u''), 1, 2000) AS hpbs,
        NVL(TRIM(CAST(d.SO_TIEN_AN AS VARCHAR2(2000))), '')                                  AS tien_an,
        NVL(TRIM(CAST(d.SO_TIEN_SU AS VARCHAR2(2000))), '')                                  AS so_tien_su,
        NVL(TRIM(CAST(d.TT_SUC_KHOE_HIEN_TAI AS VARCHAR2(2000))), u'Binh thuong')            AS tt_suc_khoe,
        SUBSTR(NVL(ga.tinh_tiet_uu_tien, u''), 1, 2000)                                     AS tinh_tiet_uu_tien,
        FN_TRON_TRAI_HIEN_THI(d.PHAM_NHAN_ID)                                               AS tong_tiet_tron_trai,
        FN_TAM_DINH_CHI_HIEN_THI(d.PHAM_NHAN_ID)                                            AS tong_tiet_tam_dinh_chi,
        SUBSTR(NVL(CAST(FN_TONG_HOP_KET_QUA_CAI_TAO(d.PHAM_NHAN_ID,
            EXTRACT(YEAR FROM NVL(d.NGAY_XET, SYSDATE))) AS NVARCHAR2(2000)), u''), 1, 2000) AS xep_loai_chap_hanh,
        NVL(TRIM(CAST(d.GHI_CHU_CHI_TIET AS VARCHAR2(2000))), '')                            AS ghi_chu,
        SUBSTR(
            NVL(TRIM(CAST(d.PHAN_DOI AS VARCHAR2(500))), '')
            || CASE WHEN d.PHAN_DOI IS NOT NULL AND d.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END
            || NVL(TRIM(CAST(d.PHAN_TRAI AS VARCHAR2(500))), ''),
        1, 2000)                                                                              AS phan_doi,
        d.NGAY_HET_AN                                                                        AS ngay_het_han,
        d.tha_co_dieu_kien_id,
        NVL(TRIM(CAST(d.so_quyet_dinh AS VARCHAR2(2000))), '')                               AS so_quyet_dinh,
        COUNT(*) OVER ()                                                                      AS TOTAL_COUNT
    FROM ds d
    LEFT JOIN gcr_agg ga ON ga.PHAM_NHAN_ID = d.PHAM_NHAN_ID
    ORDER BY d.HO_TEN, d.NGAY_XET DESC NULLS LAST
    OFFSET v_skip ROWS
    FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            'Loi khi lay danh sach PN de nghi tha co dieu kien: ' || SQLERRM);
END SP_GET_DS_PN_DE_NGHI_THA_CO_DK;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PN_DE_NGHI_THA_CO_DK_NEW
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PN_DE_NGHI_THA_CO_DK_NEW" (
    --p_pn_ids IN QLPN.T_TABLE_ID DEFAULT NULL,
    p_dot_tha_id IN NUMBER    DEFAULT NULL,
    p_ma_trai_giam IN  VARCHAR2  DEFAULT NULL, 
    p_maxresultcount    IN  NUMBER    DEFAULT 0,
    p_skipcount         IN  NUMBER    DEFAULT 0
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
	--v_pn_ids QLPN.T_TABLE_ID;
    c1      SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
	--v_pn_ids := NVL(p_pn_ids,T_TABLE_ID());
    OPEN c1 FOR
    WITH
    /* ------------------------------------------------------------------ */
    /* 1. Parse danh sach PN ID tu chuoi p_pn_ids                         */
    /* ------------------------------------------------------------------ */
    ID_LIST AS (
    SELECT PN_ID 
    FROM QLPN.GTT_PN_IDS
--        SELECT DISTINCT
--            TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
--        FROM DUAL
--        CONNECT BY LEVEL <= CASE
--                WHEN p_pn_ids IS NULL           THEN 0
--                WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
--                ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
--            END
--          AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
--          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
    ),
    /* ------------------------------------------------------------------ */
    /* 2. Lay ban ghi THA_CO_DIEU_KIENS                                   */
    /* ------------------------------------------------------------------ */
	tha_one AS (
	    SELECT
	        t.ID              AS tha_co_dieu_kien_id,
	        t.PHAM_NHAN_ID,
	        t.SO_QUYET_DINH_THA AS so_quyet_dinh,
	        t.NGAY_XET,
	        t.TINH_TRANG_ID,
	        t.NHAN_XET,
	        t.QQCT_PHIEU
	    FROM (
	        SELECT
	            t_inner.ID,
	            t_inner.PHAM_NHAN_ID,
	            t_inner.SO_QUYET_DINH_THA,
	            t_inner.NGAY_XET,
	            t_inner.TINH_TRANG_ID,
	            t_inner.NHAN_XET,
	            t_inner.QQCT_PHIEU,
	            ROW_NUMBER() OVER (
	                PARTITION BY t_inner.PHAM_NHAN_ID
	                ORDER BY t_inner.NGAY_XET DESC NULLS LAST, t_inner.ID DESC
	            ) AS rn
	        FROM THA_CO_DIEU_KIENS t_inner
	        WHERE NVL(t_inner.IS_DELETED, 0) = 0
	         -- AND (p_pn_ids IS NULL OR t_inner.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
             AND (NOT EXISTS (SELECT 1 FROM QLPN.GTT_PN_IDS) 
                                OR t_inner.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
	          AND (p_dot_tha_id IS NULL OR EXISTS (
	                SELECT 1
	                FROM PN_DOT_THA_CO_DIEU_KIENS dot
	                WHERE TRUNC(dot.DTCDK_NGAY_XET) = TRUNC(t_inner.NGAY_XET)
	                  AND dot.ID = p_dot_tha_id
	                  AND NVL(dot.IS_DELETED, 0) = 0
	          ))
	    ) t
	    WHERE t.rn = 1
	),
    /* ------------------------------------------------------------------ */
    /* 3. Distinct PN trong dot de dung lam filter som                     */
    /* ------------------------------------------------------------------ */
    tha_pn AS (
        SELECT DISTINCT PHAM_NHAN_ID FROM tha_one
    ),
    /* ------------------------------------------------------------------ */
    /* 4. Thi hanh an (1 ban ghi / PN)  -- FIX: khu trung lap bang ROW_NUMBER */
    /*    Tranh lay nham ban ghi THA lam sai ngay ban an / QD THA /        */
    /*    ngay den trai / tam giam / tam giu.                              */
    /* ------------------------------------------------------------------ */
    latest_tha AS (
        SELECT * FROM (
            SELECT
                tha.THA_PNLAI_LICH_ID,
                tha.THA_NGAY_BAT,
                tha.THA_AN_PHAT,
                tha.THA_SO_BAN_AN,
                tha.THA_CAP_TOA_ID,
                tha.THA_NGAY_BAN_AN,
                tha.THA_DIA_PHUONG_CAP_TOA_ID,
                tha.THA_SO_QD_THA,
                tha.THA_NGAY_QD_THA,
                tha.THA_TOA_QD_ID,
                tha.THA_DIA_PHUONG_TOA_QD_THA_ID,
                tha.THA_DON_VI_DE_NGHI_ID,
                tha.THA_CHUYEN_DEN_TU_ID,
                tha.THA_THOI_GIAN_TAM_GIAM,
                tha.THA_THOI_GIAN_TAM_GIU,
                tha.THA_NGAY_DEN_TRAI,
                tha.THA_NGAY_HET_HAN,
                tha.THA_TOI_DANH,
                ROW_NUMBER() OVER (
                    PARTITION BY tha.THA_PNLAI_LICH_ID
                    ORDER BY tha.THA_NGAY_BAT DESC NULLS LAST, tha.ID DESC
                ) AS rn
            FROM PN_THI_HANH_AN tha
            INNER JOIN tha_pn t ON t.PHAM_NHAN_ID = tha.THA_PNLAI_LICH_ID
            WHERE NVL(tha.IS_DELETED, 0) = 0
        )
        WHERE rn = 1
    ),
    /* ------------------------------------------------------------------ */
    /* 5. Toi danh cho tung PN                                             */
    /* ------------------------------------------------------------------ */
    split_toi_danh AS (
        SELECT
            lt.THA_PNLAI_LICH_ID,
            TO_NUMBER(
                REGEXP_SUBSTR(
                    REPLACE(REPLACE(lt.THA_TOI_DANH, '[', ''), ']', ''),
                    '[0-9]+', 1, LEVEL
                )
            ) AS TOI_DANH_ID
        FROM latest_tha lt
        WHERE lt.THA_TOI_DANH IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                REPLACE(REPLACE(lt.THA_TOI_DANH, '[', ''), ']', ''), ','
            ) + 1
          AND PRIOR lt.THA_PNLAI_LICH_ID = lt.THA_PNLAI_LICH_ID
          AND PRIOR SYS_GUID() IS NOT NULL
    ),
    toi_danh_agg AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            LISTAGG(DISTINCT dtd.TD_TEN, ', ')
                WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH
        FROM split_toi_danh s
        LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
        GROUP BY s.THA_PNLAI_LICH_ID
    ),
    /* ------------------------------------------------------------------ */
    /* 6. Tinh tiet uu tien tu GHI_CHU_RIENG                              */
    /* ------------------------------------------------------------------ */
    gcr_agg AS (
        SELECT
            ll2.ID AS PHAM_NHAN_ID,
            RTRIM(
                XMLAGG(
                    XMLELEMENT(e, dgcr.GCR_TEN || ', ')
                    ORDER BY dgcr.GCR_TEN
                ).extract('//text()').GETCLOBVAL(),
                ', '
            ) AS TINH_TIET_UU_TIEN
        FROM PN_LAI_LICHS ll2
        INNER JOIN tha_pn t ON t.PHAM_NHAN_ID = ll2.ID
        LEFT JOIN LATERAL (
            SELECT TRIM(REGEXP_SUBSTR(ll2.LL_GHI_CHU_RIENG, '[^,]+', 1, LEVEL)) AS GCR_MA
            FROM DUAL
            WHERE
              NVL(ll2.LL_LA_BAN_DONG_BANG, 0) = 0 AND ll2.LL_GHI_CHU_RIENG IS NOT NULL
            CONNECT BY LEVEL <= REGEXP_COUNT(ll2.LL_GHI_CHU_RIENG, ',') + 1
        ) gcr_split ON 1 = 1
        LEFT JOIN DM_GHI_CHU_RIENGS dgcr
            ON gcr_split.GCR_MA = TRIM(dgcr.ID)
           AND NVL(dgcr.IS_DELETED, 0) = 0
        GROUP BY ll2.ID
    ),
    /* ------------------------------------------------------------------ */
    /* 7. PN nghien ma tuy                                                 */
    /* ------------------------------------------------------------------ */
    nghien_mt AS (
        SELECT DISTINCT nmt.NMT_PN_LAI_LICH_ID AS PHAM_NHAN_ID
        FROM PN_NGHIEN_MT nmt
        INNER JOIN tha_pn t ON t.PHAM_NHAN_ID = nmt.NMT_PN_LAI_LICH_ID
        WHERE NVL(nmt.IS_DELETED, 0) = 0
    ),
    /* ------------------------------------------------------------------ */
    /* 8. So con                                                           */
    /* ------------------------------------------------------------------ */
    con_count AS (
        SELECT PHAM_NHAN_ID, COUNT(DISTINCT ID) AS SO_CON
        FROM THAN_NHAN_CON_CAIS
        WHERE NVL(IS_DELETED, 0) = 0
        GROUP BY PHAM_NHAN_ID
    ),
    /* ------------------------------------------------------------------ */
    /* 8b. Than nhan: bo de (121), me de (122), vo (132), chong (131)      */
    /* ------------------------------------------------------------------ */
    than_nhan_raw AS (
        SELECT
            tn.PHAM_NHAN_ID,
            dm.QHVPN_MA,
            NULLIF(TRIM(CAST(tn.HO_TEN_THAN_NHAN AS VARCHAR2(500))), '') AS ho_ten,
            NULLIF(TRIM(CAST(tn.NGAY_SINH        AS VARCHAR2(100))),  '') AS nam_sinh,
            NULLIF(TRIM(CAST(tn.NGHE_NGHIEP      AS VARCHAR2(500))),  '') AS nghe_nghiep,
            NULLIF(TRIM(CAST(tn.NOI_O            AS VARCHAR2(2000))), '') AS noi_o
        FROM THAN_NHAN_NGUOI_THANS tn
        INNER JOIN tha_pn t ON t.PHAM_NHAN_ID = tn.PHAM_NHAN_ID
        INNER JOIN DM_QUAN_HE_VOI_PHAM_NHANS dm ON dm.ID = tn.QUAN_HE_ID
        WHERE NVL(tn.IS_DELETED, 0) = 0
          AND dm.QHVPN_MA IN ('121', '122', '131', '132')
    ),
    than_nhan_agg AS (
        SELECT
            PHAM_NHAN_ID,
            MAX(CASE WHEN QHVPN_MA = '121' THEN ho_ten END)      AS ho_ten_bo,
            MAX(CASE WHEN QHVPN_MA = '121' THEN nam_sinh END)    AS nam_sinh_bo,
            MAX(CASE WHEN QHVPN_MA = '121' THEN nghe_nghiep END) AS nghe_nghiep_bo,
            MAX(CASE WHEN QHVPN_MA = '121' THEN noi_o END)       AS cho_o_hien_nay_bo,
            MAX(CASE WHEN QHVPN_MA = '122' THEN ho_ten END)      AS ho_ten_me,
            MAX(CASE WHEN QHVPN_MA = '122' THEN nam_sinh END)    AS nam_sinh_me,
            MAX(CASE WHEN QHVPN_MA = '122' THEN nghe_nghiep END) AS nghe_nghiep_me,
            MAX(CASE WHEN QHVPN_MA = '122' THEN noi_o END)       AS cho_o_hien_nay_me,
            MAX(CASE WHEN QHVPN_MA = '132' THEN ho_ten END)      AS ho_ten_vo,
            MAX(CASE WHEN QHVPN_MA = '132' THEN nam_sinh END)    AS nam_sinh_vo,
            MAX(CASE WHEN QHVPN_MA = '132' THEN nghe_nghiep END) AS nghe_nghiep_vo,
            MAX(CASE WHEN QHVPN_MA = '132' THEN noi_o END)       AS cho_o_hien_nay_vo,
            MAX(CASE WHEN QHVPN_MA = '131' THEN ho_ten END)      AS ho_ten_chong,
            MAX(CASE WHEN QHVPN_MA = '131' THEN nam_sinh END)    AS nam_sinh_chong,
            MAX(CASE WHEN QHVPN_MA = '131' THEN nghe_nghiep END) AS nghe_nghiep_chong,
            MAX(CASE WHEN QHVPN_MA = '131' THEN noi_o END)       AS cho_o_hien_nay_chong,
            /* Chuoi gop (giu tuong thich template cu) */
            MAX(CASE WHEN QHVPN_MA = '121' THEN
                NVL(ho_ten, u'Ch?a có')
                || CASE WHEN nam_sinh    IS NOT NULL THEN u'; N?m sinh: '    || nam_sinh    ELSE u'' END
                || CASE WHEN nghe_nghiep IS NOT NULL THEN u'; Ngh? nghi?p: ' || nghe_nghiep ELSE u'' END
                || CASE WHEN noi_o       IS NOT NULL THEN u'; Ch? ? hi?n nay: ' || noi_o   ELSE u'' END
            END) AS thong_tin_bo,
            MAX(CASE WHEN QHVPN_MA = '122' THEN
                NVL(ho_ten, u'Ch?a có')
                || CASE WHEN nam_sinh    IS NOT NULL THEN u'; N?m sinh: '    || nam_sinh    ELSE u'' END
                || CASE WHEN nghe_nghiep IS NOT NULL THEN u'; Ngh? nghi?p: ' || nghe_nghiep ELSE u'' END
                || CASE WHEN noi_o       IS NOT NULL THEN u'; Ch? ? hi?n nay: ' || noi_o   ELSE u'' END
            END) AS thong_tin_me,
            MAX(CASE WHEN QHVPN_MA = '132' THEN
                NVL(ho_ten, u'Ch?a có')
                || CASE WHEN nam_sinh    IS NOT NULL THEN u'; N?m sinh: '    || nam_sinh    ELSE u'' END
                || CASE WHEN nghe_nghiep IS NOT NULL THEN u'; Ngh? nghi?p: ' || nghe_nghiep ELSE u'' END
                || CASE WHEN noi_o       IS NOT NULL THEN u'; Ch? ? hi?n nay: ' || noi_o   ELSE u'' END
            END) AS thong_tin_vo,
            MAX(CASE WHEN QHVPN_MA = '131' THEN
                NVL(ho_ten, u'Ch?a có')
                || CASE WHEN nam_sinh    IS NOT NULL THEN u'; N?m sinh: '    || nam_sinh    ELSE u'' END
                || CASE WHEN nghe_nghiep IS NOT NULL THEN u'; Ngh? nghi?p: ' || nghe_nghiep ELSE u'' END
                || CASE WHEN noi_o       IS NOT NULL THEN u'; Ch? ? hi?n nay: ' || noi_o   ELSE u'' END
            END) AS thong_tin_chong
        FROM than_nhan_raw
        GROUP BY PHAM_NHAN_ID
    ),
    /* ------------------------------------------------------------------ */
    /* 8c. Con cai: quan he "Con" (QHVPN_MA = 151) trong THAN_NHAN_NGUOI_THANS */
    /*     Nhieu con -> gop chuoi, cach nhau dau cham phay                  */
    /* ------------------------------------------------------------------ */
    con_cai_agg AS (
        SELECT
            tn.PHAM_NHAN_ID,
            LISTAGG(
                TRIM(
                    NVL(NULLIF(TRIM(CAST(tn.HO_TEN_THAN_NHAN AS VARCHAR2(500))), ''), u'Ch?a có')
                    || CASE WHEN NULLIF(TRIM(CAST(tn.NGAY_SINH AS VARCHAR2(100))), '') IS NOT NULL
                            THEN u', N?m sinh: ' || TRIM(CAST(tn.NGAY_SINH AS VARCHAR2(100)))
                            ELSE u'' END
                    || CASE WHEN NULLIF(TRIM(CAST(tn.NGHE_NGHIEP AS VARCHAR2(500))), '') IS NOT NULL
                            THEN u', Ngh? nghi?p: ' || TRIM(CAST(tn.NGHE_NGHIEP AS VARCHAR2(500)))
                            ELSE u'' END
                    || CASE WHEN NULLIF(TRIM(CAST(tn.NOI_O AS VARCHAR2(2000))), '') IS NOT NULL
                            THEN u', Ch? ? hi?n nay: ' || TRIM(CAST(tn.NOI_O AS VARCHAR2(2000)))
                            ELSE u'' END
                ),
                u'; '
            ) WITHIN GROUP (ORDER BY tn.ID) AS CAC_CON
        FROM THAN_NHAN_NGUOI_THANS tn
        INNER JOIN tha_pn t ON t.PHAM_NHAN_ID = tn.PHAM_NHAN_ID
        INNER JOIN DM_QUAN_HE_VOI_PHAM_NHANS dm ON dm.ID = tn.QUAN_HE_ID
        WHERE NVL(tn.IS_DELETED, 0) = 0
          AND dm.QHVPN_MA = '151'
        GROUP BY tn.PHAM_NHAN_ID
    ),
    /* ------------------------------------------------------------------ */
    /* 8d. Giam an chi tiet                                                */
    /* ------------------------------------------------------------------ */
    giam_an_chi_tiet AS (
        SELECT
            g.PHAM_NHAN_ID,
            LISTAGG(
                TRIM(
                    NVL(NULLIF(TRIM(CAST(g.SO_QUYET_DINH AS VARCHAR2(100))), ''), u'')
                    || CASE WHEN g.NGAY_QUYET_DINH IS NOT NULL
                            THEN u', ' || TO_CHAR(g.NGAY_QUYET_DINH, 'DD/MM/YYYY')
                            ELSE u'' END
                    || CASE WHEN dcq_ga.CQ_TEN IS NOT NULL
                            THEN u', ' || TRIM(CAST(dcq_ga.CQ_TEN AS VARCHAR2(500)))
                            ELSE u'' END
                    || CASE WHEN dttp_ga.TTP_TEN IS NOT NULL
                            THEN u', ' || TRIM(CAST(dttp_ga.TTP_TEN AS VARCHAR2(500)))
                            ELSE u'' END
                ),
                u'; '
            ) WITHIN GROUP (ORDER BY g.NGAY_QUYET_DINH, g.ID) AS giam_an_chi_tiet
        FROM GIAM_THOI_HANS g
        INNER JOIN tha_pn t ON t.PHAM_NHAN_ID = g.PHAM_NHAN_ID
        LEFT JOIN DM_CO_QUANS dcq_ga
            ON dcq_ga.ID = g.TOA_QUYET_DINH_ID
        LEFT JOIN DM_TINH_THANH_PHO dttp_ga
            ON dttp_ga.ID = g.DIA_PHUONG_ID
           AND NVL(dttp_ga.IS_DELETED, 0) = 0
        WHERE NVL(g.IS_DELETED, 0) = 0
        GROUP BY g.PHAM_NHAN_ID
    ),
    /* ------------------------------------------------------------------ */
    /* 8e. Tien an: parse PNTA_TOI_DANH_ID -> join DM_TOI_DANHS           */
    /* ------------------------------------------------------------------ */
    tien_an_split AS (
        SELECT
            ta.PNTA_LAI_LICH_ID,
            ta.ID AS PNTA_ID,
            TO_NUMBER(
                REGEXP_SUBSTR(
                    REPLACE(REPLACE(ta.PNTA_TOI_DANH_ID, '[', ''), ']', ''),
                    '[0-9]+', 1, LEVEL
                )
            ) AS TOI_DANH_ID
        FROM PN_TIEN_AN ta
        INNER JOIN tha_pn t ON t.PHAM_NHAN_ID = ta.PNTA_LAI_LICH_ID
        WHERE NVL(ta.IS_DELETED, 0) = 0
          AND ta.PNTA_TOI_DANH_ID IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                        REPLACE(REPLACE(ta.PNTA_TOI_DANH_ID, '[', ''), ']', ''),
                        ','
                    ) + 1
          AND PRIOR ta.PNTA_LAI_LICH_ID = ta.PNTA_LAI_LICH_ID
          AND PRIOR ta.ID               = ta.ID
          AND PRIOR SYS_GUID()          IS NOT NULL
    ),
    tien_an_agg AS (
        SELECT
            s.PNTA_LAI_LICH_ID                     AS PHAM_NHAN_ID,
            LISTAGG(DISTINCT dtd.TD_TEN, ', ')
                WITHIN GROUP (ORDER BY dtd.TD_TEN)  AS TIEN_AN
        FROM tien_an_split s
        LEFT JOIN DM_TOI_DANHS dtd
            ON dtd.ID = s.TOI_DANH_ID
           AND NVL(dtd.IS_DELETED, 0) = 0
        GROUP BY s.PNTA_LAI_LICH_ID
    ),
    /* Chi tiet tien an: thoi gian (nam xu), toa an xu phat, muc an */
    tien_an_detail AS (
        SELECT
            ta.PNTA_LAI_LICH_ID AS PHAM_NHAN_ID,
            LISTAGG(
                CASE WHEN ta.PNTA_NAM_XU IS NOT NULL AND ta.PNTA_NAM_XU > 0
                     THEN TO_NCHAR(ta.PNTA_NAM_XU) ELSE NULL END,
                '; '
            ) WITHIN GROUP (ORDER BY ta.PNTA_NAM_XU, ta.ID) AS THOI_GIAN_TIEN_AN,
            LISTAGG(
                NULLIF(TRIM(CAST(dcq_ta.CQ_TEN AS VARCHAR2(500))), ''),
                '; '
            ) WITHIN GROUP (ORDER BY ta.PNTA_NAM_XU, ta.ID) AS TOA_AN_XU_PHAT,
            LISTAGG(
                NULLIF(TRIM(CAST(dmtg_ta.MTG_TITLE AS VARCHAR2(500))), ''),
                '; '
            ) WITHIN GROUP (ORDER BY ta.PNTA_NAM_XU, ta.ID) AS MUC_AN
        FROM PN_TIEN_AN ta
        INNER JOIN tha_pn t ON t.PHAM_NHAN_ID = ta.PNTA_LAI_LICH_ID
        LEFT JOIN DM_CO_QUANS dcq_ta
            ON dcq_ta.ID = ta.PNTA_TOA_XU_ID
           AND NVL(dcq_ta.IS_DELETED, 0) = 0
        LEFT JOIN DM_MA_THOI_GIANS dmtg_ta
            ON dmtg_ta.ID = ta.PNTA_MUC_AN_ID
           AND NVL(dmtg_ta.IS_DELETED, 0) = 0
        WHERE NVL(ta.IS_DELETED, 0) = 0
        GROUP BY ta.PNTA_LAI_LICH_ID
    ),
    /* ------------------------------------------------------------------ */
    /* 8f. Tien su: noi TS_HANH_VI_VI_PHAM                                */
    /* ------------------------------------------------------------------ */
    tien_su_agg AS (
        SELECT
            ts.TS_PN_LAI_LICH_ID                   AS PHAM_NHAN_ID,
            LISTAGG(TRIM(CAST(ts.TS_HANH_VI_VI_PHAM AS VARCHAR2(500))), ', ')
                WITHIN GROUP (ORDER BY ts.TS_THOI_GIAN, ts.ID) AS TIEN_SU,
            LISTAGG(
                CASE WHEN ts.TS_THOI_GIAN IS NOT NULL
                     THEN TO_CHAR(ts.TS_THOI_GIAN, 'DD/MM/YYYY') ELSE NULL END,
                '; '
            ) WITHIN GROUP (ORDER BY ts.TS_THOI_GIAN, ts.ID) AS THOI_GIAN_TIEN_SU,
            LISTAGG(
                NULLIF(TRIM(CAST(ts.TS_HINH_THUC_XU_LY AS VARCHAR2(500))), ''),
                '; '
            ) WITHIN GROUP (ORDER BY ts.TS_THOI_GIAN, ts.ID) AS HINH_THUC_XU_LY
        FROM PN_TIEN_SUS ts
        INNER JOIN tha_pn t ON t.PHAM_NHAN_ID = ts.TS_PN_LAI_LICH_ID
        WHERE NVL(ts.IS_DELETED, 0) = 0
          AND ts.TS_HANH_VI_VI_PHAM IS NOT NULL
        GROUP BY ts.TS_PN_LAI_LICH_ID
    ),
    /* ------------------------------------------------------------------ */
    /* 9. Tong ngay tron                                                   */
    /* ------------------------------------------------------------------ */
    tong_tron AS (
        SELECT
            tt.PHAM_NHAN_ID,
            SUM(FLOOR(CAST(tt.NGAY_BAT_LAI AS DATE) - CAST(tt.NGAY_TRON AS DATE)) + 1) AS TONG_NGAY_TRON
        FROM TRON_TRAIS tt
        INNER JOIN tha_pn t ON t.PHAM_NHAN_ID = tt.PHAM_NHAN_ID
        WHERE NVL(tt.IS_DELETED, 0) = 0
          AND tt.NGAY_TRON    IS NOT NULL
          AND tt.NGAY_BAT_LAI IS NOT NULL
        GROUP BY tt.PHAM_NHAN_ID
    ),
    /* ------------------------------------------------------------------ */
    /* 10. Tong ngay tam dinh chi                                          */
    /* ------------------------------------------------------------------ */
    tong_tdc AS (
        SELECT
            tdc.PHAM_NHAN_ID,
            SUM(FLOOR(CAST(tdc.NGAY_LAI AS DATE) - CAST(tdc.TU_NGAY AS DATE)) + 1) AS TONG_NGAY_TDC
        FROM TAM_DINH_CHIS tdc
        INNER JOIN tha_pn t ON t.PHAM_NHAN_ID = tdc.PHAM_NHAN_ID
        WHERE NVL(tdc.IS_DELETED, 0) = 0
          AND tdc.TU_NGAY  IS NOT NULL
          AND tdc.NGAY_LAI IS NOT NULL
        GROUP BY tdc.PHAM_NHAN_ID
    ),
    /* ------------------------------------------------------------------ */
    /* 11. Mien hinh phat                                                  */
    /* ------------------------------------------------------------------ */
    mien_hp AS (
        SELECT PN_LAI_LICH_ID, MHP_THM_YEAR, MHP_THM_MONTH, MHP_THM_DAY
        FROM MIEN_HINH_PHATS
        WHERE IS_DELETED = 0
    ),
    /* ------------------------------------------------------------------ */
    /* 12. Bo loc chinh + join lai lich                                    */
    /* ------------------------------------------------------------------ */
    ds AS (
        SELECT
            t.PHAM_NHAN_ID,
            t.tha_co_dieu_kien_id,
            t.so_quyet_dinh,
            t.NGAY_XET,
            t.TINH_TRANG_ID,
            pll.LL_SO_HO_SO_LAN_DAU,
            pll.LL_HO_TEN,
            pll.LL_NGAY_SINH,
            pll.LL_TEN_KHAC,
            pll.LL_NGUYEN_QUAN,
            pll.LL_DIA_CHI_THUONG_TRU,
            pll.LL_DIA_CHI_THUONG_TRU_WARD,
            pll.LL_DIA_CHI_THUONG_TRU_PROVICE,
            pll.LL_SO_TIEN_AN,
            pll.LL_SO_TIEN_SU,
            pll.LL_NHAN_THAN,
            pll.LL_TOM_TAT_HV,
            pll.LL_GHI_CHU_CHI_TIET,
            dttpn.TTPN_TEN                          AS tinh_trang,
            dgt.GT_TEN                              AS gioi_tinh,
            pll.LL_DM_GIOI_TINH_ID                 AS gioi_tinh_id,
            ddt.DT_TEN                              AS dan_toc,
            dqt.QT_TEN                              AS quoc_tich,
            dqt.QT_MA                               AS quoc_tich_ma,
            dtg2.TG_TEN                             AS ton_giao,
            dnn.NN_TEN                              AS nghe_nghiep,
            dhv.HV_TEN                              AS hoc_van,
            dskpn.TTSKPN_TEN                        AS tt_sk_khi_vao,
            dbt.BT_TEN                              AS tt_sk_hien_tai,
            dpd.PD_TEN                              AS phan_doi_ten,
            dpt.PT_TEN                              AS phan_trai_ten,
            dtg.TG_TEN                              AS trai_giam,
            pll.LL_PHAN_DOI_ID                      AS phan_doi_id,
            ltha.THA_NGAY_BAT,
            ltha.THA_AN_PHAT,
            ltha.THA_SO_BAN_AN,
            ltha.THA_NGAY_BAN_AN,
            ltha.THA_SO_QD_THA,
            ltha.THA_NGAY_QD_THA,
            ltha.THA_THOI_GIAN_TAM_GIAM,
            ltha.THA_THOI_GIAN_TAM_GIU,
            ltha.THA_NGAY_DEN_TRAI,
            ltha.THA_NGAY_HET_HAN,
            /* Tong so ngay tam giam + tam giu, quy doi ve ngay theo quy uoc 30 ngay/thang, 360 ngay/nam */
            NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(ltha.THA_THOI_GIAN_TAM_GIAM, 'NAM'),   0) * 360
          + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(ltha.THA_THOI_GIAN_TAM_GIAM, 'THANG'), 0) * 30
          + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(ltha.THA_THOI_GIAN_TAM_GIAM, 'NGAY'),  0)
          + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(ltha.THA_THOI_GIAN_TAM_GIU,  'NAM'),   0) * 360
          + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(ltha.THA_THOI_GIAN_TAM_GIU,  'THANG'), 0) * 30
          + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(ltha.THA_THOI_GIAN_TAM_GIU,  'NGAY'),  0)
                                                     AS TAM_GIAM_GIU_NGAY,
            dcq_toa.CQ_TEN                          AS toa_quyet_dinh_ten,
            dttp_toa_ba.TTP_TEN                     AS toa_ban_an_dp,
            dcq5_cap_toa.CQ_TEN                     AS cap_toa_ten,
            dttp_cap_toa.TTP_TEN                    AS cap_toa_dp,
            dcq1_cdt.CQ_TEN                         AS chuyen_den_tu,
            dxp_thuong_tru.XP_TEN                   AS xa_phuong_ten,
            dttp_thuong_tru.TTP_TEN                 AS tinh_tp_ten,
            t.NHAN_XET                              AS NHAN_XET,
            t.QQCT_PHIEU                            AS QQCT_PHIEU
        FROM tha_one t
        INNER JOIN PN_LAI_LICHS pll
            ON pll.ID = t.PHAM_NHAN_ID
           AND NVL(pll.IS_DELETED, 0) = 0
        LEFT JOIN latest_tha ltha
            ON ltha.THA_PNLAI_LICH_ID = t.PHAM_NHAN_ID
        LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dttpn
            ON pll.LL_TINH_TRANG_ID = dttpn.ID
        LEFT JOIN DM_GIOI_TINHS dgt
            ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_DAN_TOCS ddt
            ON pll.LL_DM_DAN_TOC_ID = ddt.ID
        LEFT JOIN DM_TON_GIAOS dtg2
            ON pll.LL_DM_TON_GIAO_ID = dtg2.ID
        LEFT JOIN DM_QUOC_TICHS dqt
            ON pll.LL_DM_QUOC_TICH_ID = dqt.ID
        LEFT JOIN DM_NGHE_NGHIEPS dnn
            ON pll.LL_DM_NGHE_NGHIEP_ID = dnn.ID
        LEFT JOIN DM_HOC_VANS dhv
            ON pll.LL_DM_HOC_VAN_ID = dhv.ID
        LEFT JOIN DM_TINH_TRANG_SUC_KHOE_PHAM_NHANS dskpn
            ON pll.LL_SUC_KHOE_KHI_VAO_ID = dskpn.ID
        LEFT JOIN DM_BENH_TATS dbt
            ON pll.LL_BENH_HIEN_TAI_ID = dbt.ID
        LEFT JOIN DM_PHAN_DOIS dpd
            ON pll.LL_PHAN_DOI_ID = dpd.ID
        LEFT JOIN DM_PHAN_TRAIS dpt
            ON pll.LL_PHAN_TRAI_ID = dpt.ID
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON pll.LL_TRAI_GIAM_ID = dtg.ID
        LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
            ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
           AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
        LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
            ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
           AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
        LEFT JOIN DM_CO_QUANS dcq_toa
            ON ltha.THA_TOA_QD_ID = dcq_toa.ID
        LEFT JOIN DM_TINH_THANH_PHO dttp_toa_ba
            ON ltha.THA_DIA_PHUONG_CAP_TOA_ID = dttp_toa_ba.ID
        LEFT JOIN DM_CO_QUANS dcq5_cap_toa
            ON ltha.THA_CAP_TOA_ID = dcq5_cap_toa.ID
        LEFT JOIN DM_TINH_THANH_PHO dttp_cap_toa
            ON ltha.THA_DIA_PHUONG_TOA_QD_THA_ID = dttp_cap_toa.ID
        LEFT JOIN DM_CO_QUANS dcq1_cdt
            ON ltha.THA_CHUYEN_DEN_TU_ID = dcq1_cdt.ID
    )
    /* ------------------------------------------------------------------ */
    /* SELECT cuoi                                                         */
    /* ------------------------------------------------------------------ */
    SELECT
        d.PHAM_NHAN_ID                                                              AS pham_nhan_id,
        NVL(TRIM(d.LL_SO_HO_SO_LAN_DAU), '')                                       AS so_hs_lan_dau,
        NVL(d.tinh_trang, '')                                                       AS tinh_trang,
        NVL(TRIM(CAST(d.LL_HO_TEN AS VARCHAR2(2000))), '')                          AS ho_ten,
        d.gioi_tinh                                                                 AS gioi_tinh,
        d.LL_NGAY_SINH                                                              AS ngay_sinh,
        NVL(TRIM(CAST(d.LL_TEN_KHAC AS VARCHAR2(500))), '')                         AS ho_ten_khac,
        NVL(TRIM(CAST(d.LL_NGUYEN_QUAN AS VARCHAR2(2000))), '')                     AS nguyen_quan,
        CASE
            WHEN NULLIF(TRIM(d.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(d.xa_phuong_ten), u'') IS NOT NULL
              OR NULLIF(TRIM(d.tinh_tp_ten), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(d.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE WHEN NULLIF(TRIM(d.xa_phuong_ten), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(d.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                             THEN u', ' || d.xa_phuong_ten ELSE d.xa_phuong_ten END
                   ELSE u'' END
                || CASE WHEN NULLIF(TRIM(d.tinh_tp_ten), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(d.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                               OR NULLIF(TRIM(d.xa_phuong_ten), u'') IS NOT NULL
                             THEN u', ' || d.tinh_tp_ten ELSE d.tinh_tp_ten END
                   ELSE u'' END
            )
            ELSE NULL
        END                                                                         AS dia_chi_thuong_tru,
        d.dan_toc                                                                   AS dan_toc,
        d.ton_giao                                                                  AS ton_giao,
        d.quoc_tich                                                                 AS quoc_tich,
        CASE WHEN d.nghe_nghiep IS NULL THEN u'Không' ELSE d.nghe_nghiep END       AS nghe_nghiep,
        CASE WHEN d.hoc_van     IS NULL THEN u'Không' ELSE d.hoc_van     END       AS hoc_van,
        d.tt_sk_khi_vao                                                             AS tt_suc_khoe_khi_vao,
        NVL(d.tt_sk_hien_tai, u'Bình th??ng')                                      AS tt_suc_khoe_hien_tai,
        SUBSTR(NVL(CAST(ga.TINH_TIET_UU_TIEN AS VARCHAR2(2000)), u''), 1, 2000)    AS tinh_tiet_uu_tien,
        CASE WHEN NVL(cc.SO_CON, 0) = 0 THEN u'Không'
             ELSE TO_NCHAR(cc.SO_CON) END                                           AS so_con,
        CASE WHEN d.LL_SO_TIEN_AN IS NULL THEN u'Không' ELSE d.LL_SO_TIEN_AN END  AS tien_an,
        NVL(ta_agg.TIEN_AN, u'Không')                                              AS tien_an_chi_tiet,
        NVL(ta_dt.THOI_GIAN_TIEN_AN, u'')                                          AS thoi_gian_tien_an,
        NVL(ta_dt.TOA_AN_XU_PHAT,    u'')                                          AS toa_an_xu_phat,
        NVL(ta_dt.MUC_AN,            u'')                                          AS muc_an,
        CASE WHEN d.LL_SO_TIEN_SU IS NULL THEN u'Không' ELSE d.LL_SO_TIEN_SU END  AS so_tien_su,
        NVL(ts_agg.TIEN_SU,  u'Không')                                             AS tien_su_chi_tiet,
        NVL(ts_agg.THOI_GIAN_TIEN_SU, u'')                                         AS thoi_gian_tien_su,
        NVL(ts_agg.HINH_THUC_XU_LY,   u'')                                         AS hinh_thuc_xu_ly,
        NVL(TRIM(CAST(d.LL_NHAN_THAN AS VARCHAR2(2000))), '')                      AS nhan_than,
        NVL(td_agg.TOI_DANH, '')                                                   AS toi_danh,
        TO_CHAR(TRUNC(d.THA_NGAY_BAT), 'DD/MM/YYYY')                              AS ngay_bat,
        NVL(TRIM(CAST(d.THA_AN_PHAT AS VARCHAR2(500))), '')                        AS an_phat,
        NVL(TRIM(CAST(d.THA_SO_BAN_AN AS VARCHAR2(500))), '')                      AS so_ban_an,
        CASE WHEN d.THA_NGAY_BAN_AN IS NOT NULL
             THEN TO_CHAR(d.THA_NGAY_BAN_AN, 'DD/MM/YYYY') ELSE NULL END          AS ngay_ban_an,
        /* FIX bug 1: thu tu [TOA_AN], [dia phuong cua toa] */
        SUBSTR(TRIM(
            NVL(d.cap_toa_ten, '')
            || NVL2(d.cap_toa_ten, u', ', u'')
            || NVL(d.toa_ban_an_dp, '')
        ), 1, 2000)                                                                 AS toa_xu,
        NVL(TRIM(CAST(d.THA_SO_QD_THA AS VARCHAR2(500))), '')                      AS so_quyet_dinh,
        CASE WHEN d.THA_NGAY_QD_THA IS NOT NULL
             THEN TO_CHAR(d.THA_NGAY_QD_THA, 'DD/MM/YYYY') ELSE NULL END          AS ngay_qd_tha,
        /* FIX bug 2: thu tu [TOA_AN], [dia phuong cua toa] */
        SUBSTR(TRIM(
            NVL(d.toa_quyet_dinh_ten, '')
            || NVL2(d.toa_quyet_dinh_ten, u', ', u'')
            || NVL(d.cap_toa_dp, '')
        ), 1, 2000)                                                                 AS co_quan_qd_tha,
        NVL(d.chuyen_den_tu, '')                                                   AS chuyen_den_tu,
        /* FIX bug 5: tam giam / tam giu lay text nguyen tu THA (dung ban ghi sau fix latest_tha) */
        CASE WHEN d.THA_THOI_GIAN_TAM_GIAM IS NULL THEN u'Không'
             ELSE d.THA_THOI_GIAN_TAM_GIAM END                                     AS thoi_gian_tam_giam,
        CASE WHEN d.THA_THOI_GIAN_TAM_GIU  IS NULL THEN u'Không'
             ELSE d.THA_THOI_GIAN_TAM_GIU  END                                     AS thoi_gian_tam_giu,
        /* Tong tam giam + tam giu: > 30 ngay thi quy doi ra thang (30 ngay/thang) */
        CASE
            WHEN NVL(d.TAM_GIAM_GIU_NGAY, 0) = 0 THEN u'Không'
            WHEN d.TAM_GIAM_GIU_NGAY > 30 THEN
                TO_CHAR(TRUNC(d.TAM_GIAM_GIU_NGAY / 30)) || u' tháng'
                || CASE WHEN MOD(d.TAM_GIAM_GIU_NGAY, 30) > 0
                        THEN u' ' || TO_CHAR(MOD(d.TAM_GIAM_GIU_NGAY, 30)) || u' ngày'
                        ELSE u'' END
            ELSE TO_CHAR(d.TAM_GIAM_GIU_NGAY) || u' ngày'
        END                                                                        AS tg_tam_giam_giu,
        TO_CHAR(TRUNC(d.THA_NGAY_DEN_TRAI), 'DD/MM/YYYY')                         AS ngay_den_trai,
        SUBSTR(
            NVL(d.phan_doi_ten, '')
            || CASE WHEN d.phan_doi_ten IS NOT NULL AND d.phan_trai_ten IS NOT NULL
                    THEN u', ' ELSE u'' END
            || NVL(d.phan_trai_ten, ''),
        1, 2000)                                                                    AS phan_doi,
        d.phan_trai_ten                                                             AS phan_trai,
        d.trai_giam                                                                 AS trai_giam,
        CASE WHEN NVL(tron.TONG_NGAY_TRON, 0) = 0 THEN u'Không'
             ELSE TO_CHAR(tron.TONG_NGAY_TRON) || u' ngày' END                    AS thoi_gian_tron,
        /* FIX bug 7: thoi gian tam dinh chi = tong so ngay (10 ngay), khong phai ngay lai */
        CASE WHEN NVL(tdc.TONG_NGAY_TDC, 0) = 0 THEN u'Không'
             ELSE TO_CHAR(tdc.TONG_NGAY_TDC) || u' ngày' END                      AS thoi_gian_tam_dinh_chi,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(d.PHAM_NHAN_ID, d.NGAY_XET), u'')  AS tg_chap_hanh,
        NVL(PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(d.PHAM_NHAN_ID), u'Không')                               AS tg_da_giam,
        QLPN.FN_TINH_AN_DA_GIAM_CHI_TIET(d.PHAM_NHAN_ID)                                                  AS thoi_gian_duoc_giam,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(d.PHAM_NHAN_ID, d.NGAY_XET), u'')       AS tg_con_lai,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(d.PHAM_NHAN_ID, d.NGAY_XET), u'')    AS da_chap_hanh,
        NVL(PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(d.PHAM_NHAN_ID, d.NGAY_XET), u'')        AS thoi_gian_con_lai,
        QLPN.FN_FORMAT_YMD(mhp.MHP_THM_YEAR, mhp.MHP_THM_MONTH, mhp.MHP_THM_DAY)                         AS mien_hinh_phat,
        FN_GET_LIET_KE_HPBST_TNDST(d.PHAM_NHAN_ID)                                                      AS hpbs,
        FN_GET_LIET_KE_HPBS_KHAC(d.PHAM_NHAN_ID)                                                      AS hpbs_khac,
        NVL(TRIM(CAST(d.QQCT_PHIEU AS VARCHAR2(4000))), u'')                                          AS xep_loai_chap_hanh,
        TO_CHAR(TRUNC(d.THA_NGAY_HET_HAN), 'DD/MM/YYYY')                          AS ngay_het_han,
        NVL(TRIM(CAST(d.LL_TOM_TAT_HV AS VARCHAR2(2000))), '')                     AS hanh_vi_pham_toi,
        NVL(TRIM(CAST(d.LL_GHI_CHU_CHI_TIET AS VARCHAR2(2000))), '')              AS ghi_chu,
        NVL(tn_agg.ho_ten_bo, u'')                                                 AS ho_ten_bo,
        NVL(tn_agg.nam_sinh_bo, u'')                                               AS nam_sinh_bo,
        NVL(tn_agg.nghe_nghiep_bo, u'')                                            AS nghe_nghiep_bo,
        NVL(tn_agg.cho_o_hien_nay_bo, u'')                                         AS cho_o_hien_nay_bo,
        NVL(tn_agg.ho_ten_me, u'')                                                 AS ho_ten_me,
        NVL(tn_agg.nam_sinh_me, u'')                                               AS nam_sinh_me,
        NVL(tn_agg.nghe_nghiep_me, u'')                                            AS nghe_nghiep_me,
        NVL(tn_agg.cho_o_hien_nay_me, u'')                                         AS cho_o_hien_nay_me,
        CASE WHEN d.gioi_tinh_id = 2
             THEN NVL(tn_agg.ho_ten_chong, u'')
             ELSE NVL(tn_agg.ho_ten_vo, u'')
        END                                                                         AS ho_ten_vo_chong,
        CASE WHEN d.gioi_tinh_id = 2
             THEN NVL(tn_agg.nam_sinh_chong, u'')
             ELSE NVL(tn_agg.nam_sinh_vo, u'')
        END                                                                         AS nam_sinh_vo_chong,
        CASE WHEN d.gioi_tinh_id = 2
             THEN NVL(tn_agg.nghe_nghiep_chong, u'')
             ELSE NVL(tn_agg.nghe_nghiep_vo, u'')
        END                                                                         AS nghe_nghiep_vo_chong,
        CASE WHEN d.gioi_tinh_id = 2
             THEN NVL(tn_agg.cho_o_hien_nay_chong, u'')
             ELSE NVL(tn_agg.cho_o_hien_nay_vo, u'')
        END                                                                         AS cho_o_hien_nay_vo_chong,
        /* Than nhan: chuoi gop (template cu) */
        NVL(tn_agg.thong_tin_bo,    u'Ch?a có')                                    AS thong_tin_bo,
        NVL(tn_agg.thong_tin_me,    u'Ch?a có')                                    AS thong_tin_me,
        CASE
            WHEN d.gioi_tinh_id = 2
            THEN NVL(tn_agg.thong_tin_chong, u'Ch?a có')
            ELSE NVL(tn_agg.thong_tin_vo,    u'Ch?a có')
        END                                                                         AS thong_tin_vo_chong,
        CASE WHEN NVL(cc.SO_CON, 0) = 0 THEN u'Ch?a có'
             ELSE TO_NCHAR(cc.SO_CON) END                                            AS thong_tin_con,
        SUBSTR(NVL(cc_agg.CAC_CON, u'Ch?a có'), 1, 4000)                           AS cac_con,
        SUBSTR(NVL(ga_ct.giam_an_chi_tiet, ''), 1, 2000)                           AS giam_an_chi_tiet,
        d.tha_co_dieu_kien_id,
        TO_CHAR(d.NGAY_XET, 'DD/MM/YYYY')                                          AS ngay_xet,
        NVL(TRIM(CAST(d.NHAN_XET AS VARCHAR2(4000))), u'')                          AS nhan_xet,
        pdtcdk.DTCDK_SO_PHIEU AS so_phieu,
  		CASE
        WHEN NULLIF(TRIM(pll.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
          OR NULLIF(TRIM(dxp_tha_ve.XP_TEN), u'') IS NOT NULL
          OR NULLIF(TRIM(dttp_tha_ve.TTP_TEN), u'') IS NOT NULL
        THEN TRIM(
            NVL(NULLIF(TRIM(pll.LL_NOI_THA_VE_CU_TRU), u''), u'')
            || CASE
                WHEN NULLIF(TRIM(dxp_tha_ve.XP_TEN), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(pll.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
                            THEN u', ' || dxp_tha_ve.XP_TEN
                        ELSE dxp_tha_ve.XP_TEN
                    END
                ELSE u''
               END
            || CASE
                WHEN NULLIF(TRIM(dttp_tha_ve.TTP_TEN), u'') IS NOT NULL THEN
                    CASE
                        WHEN NULLIF(TRIM(pll.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
                          OR NULLIF(TRIM(dxp_tha_ve.XP_TEN), u'') IS NOT NULL
                            THEN u', ' || dttp_tha_ve.TTP_TEN
                        ELSE dttp_tha_ve.TTP_TEN
                    END
                ELSE u''
               END
        )
        ELSE NULL
    	END AS noi_ve,
        COUNT(*) OVER ()                                                            AS total_count
    FROM ds d
    LEFT JOIN PN_LAI_LICHS pll ON d.PHAM_NHAN_ID = pll.ID
    LEFT JOIN PN_DOT_THA_CO_DIEU_KIENS pdtcdk
        ON p_dot_tha_id IS NOT NULL
       AND pdtcdk.ID = p_dot_tha_id
       AND NVL(pdtcdk.IS_DELETED, 0) = 0
    LEFT JOIN gcr_agg          ga      ON ga.PHAM_NHAN_ID           = d.PHAM_NHAN_ID
    LEFT JOIN toi_danh_agg     td_agg  ON td_agg.THA_PNLAI_LICH_ID = d.PHAM_NHAN_ID
    LEFT JOIN con_count        cc      ON cc.PHAM_NHAN_ID           = d.PHAM_NHAN_ID
    LEFT JOIN con_cai_agg      cc_agg  ON cc_agg.PHAM_NHAN_ID       = d.PHAM_NHAN_ID
    LEFT JOIN tong_tron        tron    ON tron.PHAM_NHAN_ID         = d.PHAM_NHAN_ID
    LEFT JOIN tong_tdc         tdc     ON tdc.PHAM_NHAN_ID          = d.PHAM_NHAN_ID
    LEFT JOIN mien_hp          mhp     ON mhp.PN_LAI_LICH_ID        = d.PHAM_NHAN_ID
    LEFT JOIN than_nhan_agg    tn_agg  ON tn_agg.PHAM_NHAN_ID       = d.PHAM_NHAN_ID
    LEFT JOIN giam_an_chi_tiet ga_ct   ON ga_ct.PHAM_NHAN_ID        = d.PHAM_NHAN_ID
    LEFT JOIN tien_an_agg      ta_agg  ON ta_agg.PHAM_NHAN_ID       = d.PHAM_NHAN_ID
    LEFT JOIN tien_an_detail   ta_dt   ON ta_dt.PHAM_NHAN_ID        = d.PHAM_NHAN_ID
    LEFT JOIN tien_su_agg      ts_agg  ON ts_agg.PHAM_NHAN_ID       = d.PHAM_NHAN_ID
	LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru 
	    ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID 
	    AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
	-- Join danh muc phuong/xa - thuong tru
	LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
	    ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
	    AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
	-- Join danh muc tinh/tp - noi tha ve cu tru
	LEFT JOIN DM_TINH_THANH_PHO dttp_tha_ve
	    ON pll.LL_NOI_THA_VE_CU_TRU_PROVICE = dttp_tha_ve.ID
	    AND NVL(dttp_tha_ve.IS_DELETED, 0) = 0
	-- Join danh muc phuong/xa - noi tha ve cu tru
	LEFT JOIN DM_XA_PHUONG dxp_tha_ve
	    ON pll.LL_NOI_THA_VE_CU_TRU_WARD = dxp_tha_ve.ID
	    AND NVL(dxp_tha_ve.IS_DELETED, 0) = 0
    where p_ma_trai_giam is null or pll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA =     p_ma_trai_giam) 
    ORDER BY d.LL_HO_TEN, d.NGAY_XET DESC NULLS LAST
    OFFSET v_skip ROWS
    FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY;
    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi khi lay danh sach PN de nghi tha co dieu kien: ' || SQLERRM);
END SP_GET_DS_PN_DE_NGHI_THA_CO_DK_NEW;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PN_DU_DIEU_KIEN_DAC_XA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PN_DU_DIEU_KIEN_DAC_XA" (
    p_pham_nhan_id    IN  NUMBER
) AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    WITH     gcr_raw AS (
        SELECT ll.id AS pn_lai_lich_id,
               REGEXP_REPLACE(NVL(TRIM(ll.LL_GHI_CHU_RIENG), ''), '[[:space:]\[\]]', '') AS gcr_clean,
               1 AS row_id
        FROM PN_LAI_LICHS ll
        WHERE ll.id = p_pham_nhan_id
          AND NVL(ll.IS_DELETED, 0) = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
          AND ll.LL_GHI_CHU_RIENG IS NOT NULL
          AND REGEXP_COUNT(REGEXP_REPLACE(NVL(TRIM(ll.LL_GHI_CHU_RIENG), ''), '[[:space:]\[\]]', ''), '[0-9]+') > 0
    ),
    gcr_ids AS (
        SELECT r.pn_lai_lich_id,
               TO_NUMBER(REGEXP_SUBSTR(r.gcr_clean, '[0-9]+', 1, LEVEL)) AS gcr_id,
               LEVEL AS ord
        FROM gcr_raw r
        CONNECT BY PRIOR r.pn_lai_lich_id = r.pn_lai_lich_id
          AND PRIOR r.row_id = r.row_id
          AND PRIOR SYS_GUID() IS NOT NULL
          AND LEVEL <= REGEXP_COUNT(r.gcr_clean, '[0-9]+')
    ),
    tinh_tiet_agg AS (
        SELECT ids.pn_lai_lich_id,
               LISTAGG(g.GCR_TEN, ', ') WITHIN GROUP (ORDER BY ids.ord) AS tinh_tiet_uu_tien
        FROM gcr_ids ids
        JOIN DM_GHI_CHU_RIENGS g ON g.ID = ids.gcr_id AND NVL(g.IS_DELETED, 0) = 0
        GROUP BY ids.pn_lai_lich_id
    ),
    src AS (
        SELECT
            v.pn_dot_dac_xa_id,
            v.ten_trai_giam,
            v.pn_lai_lich_id,
            v.HO_TEN,
            v.GIOI_TINH,
            v.NAM_SINH,
            v.ngay_xet,
            v.NOI_THUONG_TRU_DAY_DU,
            v.NGHE_NGHIEP,
            v.TOI_DANH,
            v.AN_PHAT,
            v.NGAY_BAT_AN_PHAT,
            v.NGAY_DEN_TRAI,
            v.NOI_THA_VE_CU_TRU,
            v.flg_co_tien_an,
            v.dx_xep_loai_cai_tao
        FROM VW_BAO_CAO_DX_CHI_TIET v
        WHERE v.pn_lai_lich_id = p_pham_nhan_id
    ),
    with_calc AS (
        SELECT
            s.pn_lai_lich_id,
            s.HO_TEN,
            s.GIOI_TINH,
            s.NAM_SINH,
            s.NOI_THUONG_TRU_DAY_DU,
            s.NGHE_NGHIEP,
            s.TOI_DANH,
            s.AN_PHAT,
            s.NGAY_BAT_AN_PHAT,
            FN_TINH_AN_DA_GIAM(s.pn_lai_lich_id).LAN_GIAM_AN || u' L\1ea7n = ' || FN_TINH_AN_DA_GIAM(s.pn_lai_lich_id).TONG_GIAM_AN AS DA_GIAM,
            s.NGAY_DEN_TRAI,
            s.ngay_xet,
            s.NOI_THA_VE_CU_TRU,
            s.flg_co_tien_an,
            s.dx_xep_loai_cai_tao AS xep_loai_chap_hanh,
            tt.tinh_tiet_uu_tien,
            ll.LL_GHI_CHU_CHI_TIET AS ghi_chu,
            FN_GET_DA_CHAP_HANH(p_pn_id => s.pn_lai_lich_id) AS thoi_gian_da_chap_hanh,
            FN_GET_CON_LAI(s.pn_lai_lich_id) AS thoi_han_tu_con_lai
        FROM src s
        LEFT JOIN tinh_tiet_agg tt ON tt.pn_lai_lich_id = s.pn_lai_lich_id
        LEFT JOIN PN_LAI_LICHS ll ON ll.id = s.pn_lai_lich_id AND ll.is_deleted = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
    )
    SELECT
        c.HO_TEN AS ho_ten,
        c.NAM_SINH AS nam_sinh,
        c.GIOI_TINH AS gioi_tinh,
        c.NOI_THUONG_TRU_DAY_DU AS noi_dang_ky_thuong_tru,
        c.NOI_THA_VE_CU_TRU AS noi_ve_cu_tru,
        c.NGHE_NGHIEP AS nghe_nghiep,
        c.TOI_DANH AS toi_danh,
        c.NGAY_BAT_AN_PHAT AS ngay_bat,
        c.AN_PHAT AS an_phat,
        c.flg_co_tien_an AS tien_an,
        c.thoi_gian_da_chap_hanh,
        c.DA_GIAM AS da_giam,
        c.thoi_han_tu_con_lai,
        c.xep_loai_chap_hanh,
        c.tinh_tiet_uu_tien,
        c.ghi_chu
    FROM with_calc c;
    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_DS_PN_DU_DIEU_KIEN_DAC_XA;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PN_TTTHCDK
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PN_TTTHCDK" (
    p_ngay_xet_tu_ngay IN NVARCHAR2 DEFAULT NULL,
    p_ngay_xet_den_ngay IN NVARCHAR2 DEFAULT NULL,
    p_ngay_tha_tu_ngay IN NVARCHAR2 DEFAULT NULL,
    p_ngay_tha_den_ngay IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi IN NVARCHAR2 DEFAULT NULL,
    p_tinh_trang IN NVARCHAR2 DEFAULT NULL,
    p_dia_phuong_cu_tru IN NVARCHAR2 DEFAULT NULL,
    p_tinh_trang_tha IN NVARCHAR2 DEFAULT NULL,
    p_chon_in IN NVARCHAR2 DEFAULT 'Danh sách chung'
)
AS
    v_ngay_xet_tu_ngay NVARCHAR2(10);
    v_ngay_xet_den_ngay NVARCHAR2(10);
    v_ngay_tha_tu_ngay NVARCHAR2(10);
    v_ngay_tha_den_ngay NVARCHAR2(10);
    C1 SYS_REFCURSOR;
BEGIN
    IF p_ngay_xet_tu_ngay IS NULL OR p_ngay_xet_tu_ngay = '' THEN
        v_ngay_xet_tu_ngay := TO_CHAR(SYSDATE - 1, 'DD/MM/YYYY');
    ELSE
        v_ngay_xet_tu_ngay := p_ngay_xet_tu_ngay;
    END IF;

    IF p_ngay_xet_den_ngay IS NULL OR p_ngay_xet_den_ngay = '' THEN
        v_ngay_xet_den_ngay := TO_CHAR(SYSDATE - 1, 'DD/MM/YYYY');
    ELSE
        v_ngay_xet_den_ngay := p_ngay_xet_den_ngay;
    END IF;

    IF p_ngay_tha_tu_ngay IS NULL OR p_ngay_tha_tu_ngay = '' THEN
        v_ngay_tha_tu_ngay := TO_CHAR(SYSDATE - 1, 'DD/MM/YYYY');
    ELSE
        v_ngay_tha_tu_ngay := p_ngay_tha_tu_ngay;
    END IF;

    IF p_ngay_tha_den_ngay IS NULL OR p_ngay_tha_den_ngay = '' THEN
        v_ngay_tha_den_ngay := TO_CHAR(SYSDATE - 1, 'DD/MM/YYYY');
    ELSE
        v_ngay_tha_den_ngay := p_ngay_tha_den_ngay;
    END IF;

    OPEN C1 FOR
        SELECT
            vpllct.PHAM_NHAN_ID,
            vpllct.HO_TEN,
            vpllct.NAM_SINH,
            vpllct.GIOI_TINH,
            vpllct.DIA_CHI_THUONG_TRU,
            vpllct.TOI_DANH,
            vpllct.SO_TIEN_AN,
            vpllct.NGAY_BAT_AN_PHAT,
            vpllct.AN_PHAT,
            vpllct.THOI_GIAN_TAM_GIAM,
            '1' AS DA_GIAM,
            vpllct.NGAY_DEN_TRAI,
            vpllct.PHAN_DOI,
            vpllct.NGAY_HET_AN,
            vpllct.TINH_THANH_THUONG_TRU,
            NOI_THA_VE_CU_TRU_TINH_ID AS TINH_THANH_THUONG_TRU_ID,
            NULL AS GHI_CHU
        FROM VW_PN_LAI_LICH_CHI_TIET vpllct
        INNER JOIN THA_CO_DIEU_KIENS tcdk
            ON vpllct.PHAM_NHAN_ID = tcdk.PHAM_NHAN_ID
            AND vpllct.IS_DELETED = 0
            AND tcdk.IS_DELETED = 0

        WHERE
              (EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = vpllct.PHAM_NHAN_ID AND NVL(ll_song.IS_DELETED, 0) = 0 AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0) OR EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_db WHERE ll_db.ID = vpllct.PHAM_NHAN_ID AND NVL(ll_db.IS_DELETED, 0) = 0 AND NVL(ll_db.LL_LA_BAN_DONG_BANG, 0) = 1 AND p_tinh_trang IS NOT NULL AND ll_db.LL_TINH_TRANG_ID = p_tinh_trang)) AND
            (tcdk.NGAY_XET BETWEEN TO_TIMESTAMP(v_ngay_xet_tu_ngay, 'DD/MM/YYYY')
                AND TO_TIMESTAMP(v_ngay_xet_den_ngay || ' 23:59:59', 'DD/MM/YYYY HH24:MI:SS'))
            AND (tcdk.NGAY_THA BETWEEN TO_TIMESTAMP(v_ngay_tha_tu_ngay, 'DD/MM/YYYY')
                AND TO_TIMESTAMP(v_ngay_tha_den_ngay || ' 23:59:59', 'DD/MM/YYYY HH24:MI:SS'))
            AND (p_tinh_trang IS NULL OR vpllct.LL_TINH_TRANG_ID = p_tinh_trang)
            AND (p_phan_doi IS NULL OR vpllct.PHAN_DOI_ID = p_phan_doi)
            AND (p_dia_phuong_cu_tru IS NULL OR vpllct.NOI_THA_VE_CU_TRU_TINH_ID = p_dia_phuong_cu_tru)
            AND (p_tinh_trang_tha IS NULL OR tcdk.TINH_TRANG_ID = p_tinh_trang_tha);

    DBMS_SQL.RETURN_RESULT(C1);
END;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PN_XEP_LOAI_THEO_KY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PN_XEP_LOAI_THEO_KY" (
    P_PHAN_DOI_ID            IN  NUMBER        DEFAULT NULL,
    P_LOAI_XEP_LOAI_ID       IN  NUMBER        DEFAULT NULL,
    P_HPBS_TIEN_ID           IN  NUMBER        DEFAULT NULL,
    P_DOI_TUONG_ID           IN  NUMBER        DEFAULT NULL,
    P_HO_TEN_FILTER_NOSPACE  IN  NVARCHAR2     DEFAULT NULL,
    P_NGAY_DEN_TRAI_TRUOC    IN  DATE          DEFAULT NULL,
    P_DIEU_KIEN_ID           IN  NUMBER        DEFAULT NULL,
    P_TINH_TRANG_ID          IN  NUMBER        DEFAULT NULL,
    P_MOC_NGAY_DEN_TRAI_TU   IN  DATE          DEFAULT NULL,
    P_NAM_XEP_LOAI_FOR_XL    IN  NUMBER        DEFAULT NULL,
    P_KY_XEP_LOAI_TEN        IN  NVARCHAR2     DEFAULT NULL,
    P_MKXL_KY_XEP_LOAI       IN  NVARCHAR2     DEFAULT NULL,
    P_MKXL_NAM_XEP_LOAI      IN  NUMBER        DEFAULT NULL,
    P_MKXL_NGAY_DEN_TRAI_TU  IN  DATE          DEFAULT NULL,
    P_KY_XEP_LOAI_CAI_TAO_ID IN  NUMBER        DEFAULT NULL,
    P_SKIP_COUNT             IN  NUMBER        DEFAULT 0,
    P_MAX_RESULT_COUNT       IN  NUMBER        DEFAULT NULL,
    P_SORTING                IN  NVARCHAR2     DEFAULT NULL,
    P_TOTAL_COUNT            OUT NUMBER,
    P_MO_KY_NOT_FOUND        OUT NUMBER,
    P_CURSOR                 OUT SYS_REFCURSOR
) AS
    V_DU_THOI_GIAN_ID        NUMBER;
    V_CHUA_DU_THOI_GIAN_ID     NUMBER;
    V_DK_TAT_CA              NUMBER(1) := 0;
    V_TT_TAT_CA              NUMBER(1) := 0;
    V_IS_DU                  NUMBER(1) := 0;
    V_IS_CHUA                NUMBER(1) := 0;
    V_IS_DANG_TT             NUMBER(1) := 0;
    V_IS_DA_RA_TT            NUMBER(1) := 0;
    V_CO_MOC_NGAY            NUMBER(1) := 0;
    V_VIET_NAM_QUOC_TICH_ID  NUMBER;
    V_KY_XEP_LOAI_LOWER      NVARCHAR2(500);
    V_HAS_LOAI_FILTER        NUMBER(1) := 0;
    V_SORT_ASC               NUMBER(1) := 1;
    V_SORT_HOTEN             NUMBER(1) := 0;
    V_SORT_GIOITINH          NUMBER(1) := 0;
    V_SORT_PHANDOI           NUMBER(1) := 0;
    V_SORT_NGAYSINH          NUMBER(1) := 0;
    V_SORT_DIACHI            NUMBER(1) := 0;
    V_SORT_ANPHAT            NUMBER(1) := 0;
    V_SORT_NGAYDENTRAI       NUMBER(1) := 0;
    V_SORT_NGAYHETHAN        NUMBER(1) := 0;
    V_SORT_DEFAULT           NUMBER(1) := 0;
    V_SORT_XL_Q1             NUMBER(1) := 0;
    V_SORT_XL_Q2             NUMBER(1) := 0;
    V_SORT_XL_Q3             NUMBER(1) := 0;
    V_SORT_XL_Q4             NUMBER(1) := 0;
    V_SORT_FIELD             NVARCHAR2(100);
    V_SORTING_LOWER          NVARCHAR2(200);
    V_MOC_NGAY               DATE;
    V_NAM_XL                 NUMBER;
    V_TODAY                  DATE := TRUNC(SYSDATE);
BEGIN
    P_MO_KY_NOT_FOUND := 0;
    V_MOC_NGAY := P_MOC_NGAY_DEN_TRAI_TU;
    V_NAM_XL   := P_NAM_XEP_LOAI_FOR_XL;

    IF P_MKXL_KY_XEP_LOAI IS NOT NULL AND P_MKXL_NAM_XEP_LOAI IS NOT NULL THEN
        BEGIN
            SELECT NGAY_DEN_TRAI_TU, NAM_XEP_LOAI
              INTO V_MOC_NGAY, V_NAM_XL
              FROM QLPN.MO_KY_XEP_LOAI_CAI_TAOS
             WHERE KY_XEP_LOAI = P_MKXL_KY_XEP_LOAI
               AND NAM_XEP_LOAI = P_MKXL_NAM_XEP_LOAI
               AND NVL(IS_DELETED, 0) = 0
               AND ROWNUM = 1;
            V_MOC_NGAY := NVL(P_MKXL_NGAY_DEN_TRAI_TU, V_MOC_NGAY);
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                P_MO_KY_NOT_FOUND := 1;
                P_TOTAL_COUNT := 0;
                OPEN P_CURSOR FOR
                    SELECT CAST(NULL AS NUMBER) AS PHAM_NHAN_ID FROM DUAL WHERE 1 = 0;
                RETURN;
        END;
    ELSIF V_MOC_NGAY IS NULL OR V_NAM_XL IS NULL THEN
        BEGIN
            SELECT NGAY_DEN_TRAI_TU, NAM_XEP_LOAI INTO V_MOC_NGAY, V_NAM_XL
              FROM (
                    SELECT NGAY_DEN_TRAI_TU, NAM_XEP_LOAI
                      FROM QLPN.MO_KY_XEP_LOAI_CAI_TAOS
                     WHERE NVL(IS_DELETED, 0) = 0 AND TRANG_THAI = 1
                     ORDER BY ID DESC
                   )
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                BEGIN
                    SELECT NGAY_DEN_TRAI_TU, NAM_XEP_LOAI INTO V_MOC_NGAY, V_NAM_XL
                      FROM (
                            SELECT NGAY_DEN_TRAI_TU, NAM_XEP_LOAI
                              FROM QLPN.MO_KY_XEP_LOAI_CAI_TAOS
                             WHERE NVL(IS_DELETED, 0) = 0
                               AND TRUNC(TU_NGAY) <= V_TODAY AND V_TODAY <= TRUNC(DEN_NGAY)
                             ORDER BY NAM_XEP_LOAI DESC, TU_NGAY DESC
                           )
                     WHERE ROWNUM = 1;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        BEGIN
                            SELECT NGAY_DEN_TRAI_TU, NAM_XEP_LOAI INTO V_MOC_NGAY, V_NAM_XL
                              FROM (
                                    SELECT NGAY_DEN_TRAI_TU, NAM_XEP_LOAI
                                      FROM QLPN.MO_KY_XEP_LOAI_CAI_TAOS
                                     WHERE NVL(IS_DELETED, 0) = 0 AND TRUNC(DEN_NGAY) < V_TODAY
                                     ORDER BY DEN_NGAY DESC
                                   )
                             WHERE ROWNUM = 1;
                        EXCEPTION
                            WHEN NO_DATA_FOUND THEN
                                BEGIN
                                    SELECT NGAY_DEN_TRAI_TU, NAM_XEP_LOAI INTO V_MOC_NGAY, V_NAM_XL
                                      FROM (
                                            SELECT NGAY_DEN_TRAI_TU, NAM_XEP_LOAI
                                              FROM QLPN.MO_KY_XEP_LOAI_CAI_TAOS
                                             WHERE NVL(IS_DELETED, 0) = 0 AND TRUNC(TU_NGAY) > V_TODAY
                                             ORDER BY TU_NGAY ASC
                                           )
                                     WHERE ROWNUM = 1;
                                EXCEPTION
                                    WHEN NO_DATA_FOUND THEN
                                        BEGIN
                                            SELECT NGAY_DEN_TRAI_TU, NAM_XEP_LOAI INTO V_MOC_NGAY, V_NAM_XL
                                              FROM (
                                                    SELECT NGAY_DEN_TRAI_TU, NAM_XEP_LOAI
                                                      FROM QLPN.MO_KY_XEP_LOAI_CAI_TAOS
                                                     WHERE NVL(IS_DELETED, 0) = 0
                                                     ORDER BY NAM_XEP_LOAI DESC, TU_NGAY DESC
                                                   )
                                             WHERE ROWNUM = 1;
                                        EXCEPTION
                                            WHEN NO_DATA_FOUND THEN NULL;
                                        END;
                                END;
                        END;
                END;
        END;
    END IF;

    SELECT MAX(CASE WHEN TRIM(DKXL_MA) = '10'  THEN ID END),
           MAX(CASE WHEN TRIM(DKXL_MA) = '-20' THEN ID END)
      INTO V_DU_THOI_GIAN_ID, V_CHUA_DU_THOI_GIAN_ID
      FROM QLPN.DM_DIEU_KIEN_XEP_LOAIES;

    V_DK_TAT_CA  := CASE WHEN P_DIEU_KIEN_ID IS NULL OR P_DIEU_KIEN_ID = 0 THEN 1 ELSE 0 END;
    V_TT_TAT_CA  := CASE WHEN P_TINH_TRANG_ID IS NULL OR P_TINH_TRANG_ID = 0 THEN 1 ELSE 0 END;
    V_IS_DU      := CASE WHEN V_DU_THOI_GIAN_ID IS NOT NULL AND P_DIEU_KIEN_ID = V_DU_THOI_GIAN_ID THEN 1 ELSE 0 END;
    V_IS_CHUA    := CASE WHEN V_CHUA_DU_THOI_GIAN_ID IS NOT NULL AND P_DIEU_KIEN_ID = V_CHUA_DU_THOI_GIAN_ID THEN 1 ELSE 0 END;
    V_IS_DANG_TT := CASE WHEN P_TINH_TRANG_ID = 1 THEN 1 ELSE 0 END;
    V_IS_DA_RA_TT:= CASE WHEN P_TINH_TRANG_ID = 2 THEN 1 ELSE 0 END;
    V_CO_MOC_NGAY:= CASE WHEN V_MOC_NGAY IS NOT NULL THEN 1 ELSE 0 END;

    BEGIN
        SELECT ID INTO V_VIET_NAM_QUOC_TICH_ID
          FROM QLPN.DM_QUOC_TICHS
         WHERE NVL(IS_DELETED, 0) = 0 AND TRIM(QT_MA) = '250' AND ROWNUM = 1;
    EXCEPTION WHEN NO_DATA_FOUND THEN V_VIET_NAM_QUOC_TICH_ID := NULL; END;

    IF (P_KY_XEP_LOAI_TEN IS NULL OR TRIM(P_KY_XEP_LOAI_TEN) IS NULL)
       AND P_KY_XEP_LOAI_CAI_TAO_ID IS NOT NULL AND P_KY_XEP_LOAI_CAI_TAO_ID <> 0 THEN
        BEGIN
            SELECT KXLCT_TEN INTO V_KY_XEP_LOAI_LOWER
              FROM QLPN.DM_KY_XEP_LOAI_CAI_TAOS
             WHERE ID = P_KY_XEP_LOAI_CAI_TAO_ID AND ROWNUM = 1;
            V_KY_XEP_LOAI_LOWER := LOWER(V_KY_XEP_LOAI_LOWER);
        EXCEPTION
            WHEN NO_DATA_FOUND THEN V_KY_XEP_LOAI_LOWER := '';
        END;
    ELSE
        V_KY_XEP_LOAI_LOWER := LOWER(NVL(P_KY_XEP_LOAI_TEN, ''));
    END IF;
    V_HAS_LOAI_FILTER   := CASE WHEN P_LOAI_XEP_LOAI_ID IS NOT NULL AND P_LOAI_XEP_LOAI_ID <> 0 THEN 1 ELSE 0 END;

    V_SORTING_LOWER := LOWER(NVL(P_SORTING, ''));
    V_SORT_FIELD    := LOWER(TRIM(REGEXP_SUBSTR(V_SORTING_LOWER, '^\S+')));
    IF V_SORTING_LOWER LIKE '%desc%' THEN V_SORT_ASC := 0; END IF;

    IF V_SORT_FIELD = 'ngaysinh'        THEN V_SORT_NGAYSINH    := 1;
    ELSIF V_SORT_FIELD = 'diachithuongtru' THEN V_SORT_DIACHI    := 1;
    ELSIF V_SORT_FIELD = 'anphat'       THEN V_SORT_ANPHAT      := 1;
    ELSIF V_SORT_FIELD = 'ngaydentrai' THEN V_SORT_NGAYDENTRAI := 1;
    ELSIF V_SORT_FIELD = 'ngayhethan'  THEN V_SORT_NGAYHETHAN  := 1;
    ELSIF V_SORT_FIELD = 'hoten'       THEN V_SORT_HOTEN       := 1;
    ELSIF V_SORT_FIELD = 'gioitinh'    THEN V_SORT_GIOITINH    := 1;
    ELSIF V_SORT_FIELD = 'phandoi'     THEN V_SORT_PHANDOI     := 1;
    ELSIF V_SORT_FIELD = 'xeploaiquyi'  THEN V_SORT_XL_Q1      := 1;
    ELSIF V_SORT_FIELD = 'xeploaiquyii' THEN V_SORT_XL_Q2      := 1;
    ELSIF V_SORT_FIELD = 'xeploaiquyiii' THEN V_SORT_XL_Q3     := 1;
    ELSIF V_SORT_FIELD = 'xeploaiquyiv' THEN V_SORT_XL_Q4      := 1;
    ELSIF LENGTH(TRIM(V_SORTING_LOWER)) > 0 THEN V_SORT_DEFAULT := 1;
    END IF;

    OPEN P_CURSOR FOR
        WITH
        dang_o_trai AS (
            SELECT ID FROM QLPN.DM_TINH_TRANG_PHAM_NHANS
             WHERE TTPN_MA IN ('111','112','113','114')
        ),
        da_ra_trai AS (
            SELECT ID FROM QLPN.DM_TINH_TRANG_PHAM_NHANS
             WHERE TTPN_MA IN (
                '121','122','123','124','125','126','127','131','132','133',
                '141','142','143','144','145','146','147','148','149','150',
                '151','152','153','154','155','156','157','158','159','161',
                '162','171','181','191','9999'
             )
        ),
        case4_da_ra AS (
            SELECT ID FROM QLPN.DM_TINH_TRANG_PHAM_NHANS
             WHERE TTPN_MA IN (
                '121','122','123','124','125','126','127','131','132','133',
                '141','142','143','144','145','146','147','148','149','150',
                '151','152','153','154','155','156','157','158','159','161','162',
                '171','181','191','9999'
             )
        ),
        tha_max_ngay AS (
            SELECT THA_PNLAI_LICH_ID AS PN_ID, MAX(THA_NGAY_DEN_TRAI) AS MAX_NGAY
              FROM QLPN.PN_THI_HANH_AN
             WHERE NVL(IS_DELETED,0)=0 AND THA_PNLAI_LICH_ID IS NOT NULL
             GROUP BY THA_PNLAI_LICH_ID
        ),
        tha_max_id AS (
            SELECT t.THA_PNLAI_LICH_ID AS PN_ID, MAX(t.ID) AS MAX_ID
              FROM QLPN.PN_THI_HANH_AN t
              JOIN tha_max_ngay mn ON mn.PN_ID = t.THA_PNLAI_LICH_ID
             WHERE NVL(t.IS_DELETED,0)=0
               AND (t.THA_NGAY_DEN_TRAI = mn.MAX_NGAY OR (t.THA_NGAY_DEN_TRAI IS NULL AND mn.MAX_NGAY IS NULL))
             GROUP BY t.THA_PNLAI_LICH_ID
        ),
        tha_latest AS (
            SELECT t.THA_PNLAI_LICH_ID AS PN_ID,
                   t.THA_TOI_DANH, t.THA_AN_PHAT, t.THA_MA_AN_PHAT,
                   t.THA_NGAY_DEN_TRAI, t.THA_NGAY_HET_HAN
              FROM QLPN.PN_THI_HANH_AN t
              JOIN tha_max_id mi ON mi.MAX_ID = t.ID
        ),
        xl_base AS (
            SELECT x.* FROM QLPN.XEP_LOAIS x
             WHERE (V_NAM_XL IS NULL OR x.XEP_LOAI_NAM = V_NAM_XL)
        ),
        xl_max_nam AS (
            SELECT PHAM_NHAN_ID AS PN_ID, MAX(XEP_LOAI_NAM) AS MAX_NAM
              FROM xl_base GROUP BY PHAM_NHAN_ID
        ),
        xl_max_id AS (
            SELECT x.PHAM_NHAN_ID AS PN_ID, MAX(x.ID) AS MAX_ID
              FROM xl_base x
              JOIN xl_max_nam mn ON mn.PN_ID = x.PHAM_NHAN_ID AND x.XEP_LOAI_NAM = mn.MAX_NAM
             GROUP BY x.PHAM_NHAN_ID
        ),
        xl_latest AS (
            SELECT x.PHAM_NHAN_ID AS PN_ID,
                   x.XEP_LOAI_QUY_I, x.XEP_LOAI_QUY_II, x.XEP_LOAI_QUY_III, x.XEP_LOAI_QUY_IV,
                   x.XEP_LOAI_6_THANG_DAU_NAM, x.XEP_LOAI_6_THANG_CUOI_NAM, x.XEP_LOAI_CA_NAM
              FROM xl_base x JOIN xl_max_id mi ON mi.MAX_ID = x.ID
        ),
        hpbs_con_tien AS (
            SELECT DISTINCT HPBS_MA_PHAM_NHAN AS PN_ID
              FROM QLPN.PN_HINH_PHAT_BO_SUNGS
             WHERE NVL(IS_DELETED,0)=0 AND HPBS_MA_PHAM_NHAN IS NOT NULL
               AND HPBS_TONG_TIEN_CON_LAI > 0
               AND NVL(HPBS_THUOC_LOAI_TRACH_NHIEM_DAN_SU,0) <> 1
        ),
        anqg_toi_danh AS (
            SELECT ID, TD_MA FROM QLPN.DM_TOI_DANHS WHERE TD_CHUONG = '13'
        ),
        filtered AS (
            SELECT
                pll.ID                                              AS PHAM_NHAN_ID,
                pll.LL_SO_HO_SO_LAN_DAU,
                pll.LL_CCCD,
                pll.LL_HO_TEN,
                QLPN.FN_FORMAT_SORT_TEN_PN(pll.LL_HO_TEN)          AS SORT_THEO_TEN,
                pll.LL_NGAY_SINH,
                gt.GT_TEN                                           AS TEN_GIOI_TINH,
                CASE WHEN pt.PT_TEN IS NOT NULL
                     THEN TO_CHAR(pd.PD_TEN) || ', ' || TO_CHAR(pt.PT_TEN)
                     ELSE TO_CHAR(pd.PD_TEN) END AS TEN_PHAN_DOI,
                tha.THA_TOI_DANH                                    AS TOI_DANH,
                tha.THA_AN_PHAT                                     AS AN_PHAT,
                tha.THA_MA_AN_PHAT                                  AS SORT_AN_PHAT,
                tha.THA_NGAY_DEN_TRAI                               AS NGAY_DEN_TRAI,
                tha.THA_NGAY_HET_HAN                                AS NGAY_HET_HAN,
                pll.LL_TINH_TRANG_ID,
                TO_CHAR(xl.XEP_LOAI_QUY_I)                          AS XEP_LOAI_QUY_I,
                TO_CHAR(xl.XEP_LOAI_QUY_II)                         AS XEP_LOAI_QUY_II,
                TO_CHAR(xl.XEP_LOAI_QUY_III)                        AS XEP_LOAI_QUY_III,
                TO_CHAR(xl.XEP_LOAI_QUY_IV)                         AS XEP_LOAI_QUY_IV,
                TO_CHAR(xl.XEP_LOAI_6_THANG_DAU_NAM)                AS XEP_LOAI_6_THANG_DAU_NAM,
                TO_CHAR(xl.XEP_LOAI_6_THANG_CUOI_NAM)               AS XEP_LOAI_6_THANG_CUOI_NAM,
                TO_CHAR(xl.XEP_LOAI_CA_NAM)                         AS XEP_LOAI_CA_NAM,
                pll.LL_DM_QUOC_TICH_ID,
                NVL(TO_CHAR(pll.LL_DIA_CHI_THUONG_TRU), '')
                    || CASE WHEN xp.XP_TEN IS NOT NULL
                            THEN CASE WHEN pll.LL_DIA_CHI_THUONG_TRU IS NOT NULL THEN ', ' END || TO_CHAR(xp.XP_TEN) END
                    || CASE WHEN ttp.TTP_TEN IS NOT NULL THEN
                        CASE WHEN pll.LL_DIA_CHI_THUONG_TRU IS NOT NULL OR xp.XP_TEN IS NOT NULL THEN ', ' END
                             || TO_CHAR(ttp.TTP_TEN) END
                    AS DIA_CHI_THUONG_TRU,
                CASE
                    WHEN pll.LL_NGAY_SINH IS NULL THEN CASE WHEN V_SORT_ASC = 1 THEN '00000000' ELSE '99999999' END
                    WHEN LENGTH(TO_CHAR(pll.LL_NGAY_SINH)) = 10 THEN
                        SUBSTR(TO_CHAR(pll.LL_NGAY_SINH), 7, 4)
                        || SUBSTR(TO_CHAR(pll.LL_NGAY_SINH), 4, 2)
                        || SUBSTR(TO_CHAR(pll.LL_NGAY_SINH), 1, 2)
                    WHEN LENGTH(TO_CHAR(pll.LL_NGAY_SINH)) = 7 THEN
                        SUBSTR(TO_CHAR(pll.LL_NGAY_SINH), 4, 4)
                        || SUBSTR(TO_CHAR(pll.LL_NGAY_SINH), 1, 2) || '00'
                    WHEN LENGTH(TO_CHAR(pll.LL_NGAY_SINH)) = 4 THEN TO_CHAR(pll.LL_NGAY_SINH) || '0000'
                    ELSE CASE WHEN V_SORT_ASC = 1 THEN '00000000' ELSE '99999999' END
                END AS SORT_NGAY_SINH
            FROM QLPN.PN_LAI_LICHS pll
            LEFT JOIN tha_latest tha ON tha.PN_ID = pll.ID
            LEFT JOIN QLPN.DM_GIOI_TINHS gt ON gt.ID = pll.LL_DM_GIOI_TINH_ID
            LEFT JOIN QLPN.DM_PHAN_DOIS pd ON pd.ID = pll.LL_PHAN_DOI_ID
            LEFT JOIN QLPN.DM_PHAN_TRAIS pt ON pt.ID = pd.PD_DM_PHAN_TRAI_ID
            LEFT JOIN xl_latest xl ON xl.PN_ID = pll.ID
            LEFT JOIN QLPN.DM_XA_PHUONG xp ON xp.ID = pll.LL_DIA_CHI_THUONG_TRU_WARD
            LEFT JOIN QLPN.DM_TINH_THANH_PHO ttp ON ttp.ID = pll.LL_DIA_CHI_THUONG_TRU_PROVICE
            WHERE NVL(pll.IS_DELETED,0) = 0
              AND (
                    NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                 OR (
                        NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 1
                    AND (V_TT_TAT_CA = 1 OR V_IS_DA_RA_TT = 1)
                    AND pll.LL_TINH_TRANG_ID IN (SELECT ID FROM da_ra_trai)
                    )
              )
              AND (P_PHAN_DOI_ID IS NULL OR pll.LL_PHAN_DOI_ID = P_PHAN_DOI_ID)

              -- Ma tr?n 9 case + NgayDenTraiTruoc (gi? logic C#)
              AND 1 = CASE
                  WHEN V_DK_TAT_CA = 0 AND V_IS_DU = 0 AND V_IS_CHUA = 0 THEN 0
                  WHEN V_TT_TAT_CA = 0 AND V_IS_DANG_TT = 0 AND V_IS_DA_RA_TT = 0 THEN 0
                  WHEN V_DK_TAT_CA = 1 AND V_TT_TAT_CA = 1 THEN
                      CASE WHEN V_IS_CHUA = 0 AND P_NGAY_DEN_TRAI_TRUOC IS NOT NULL THEN
                          CASE WHEN tha.THA_NGAY_DEN_TRAI IS NOT NULL AND TRUNC(tha.THA_NGAY_DEN_TRAI) <= TRUNC(P_NGAY_DEN_TRAI_TRUOC) THEN 1 ELSE 0 END
                      ELSE 1 END
                  WHEN V_IS_DU = 1 AND V_TT_TAT_CA = 1 AND V_CO_MOC_NGAY = 1
                       AND tha.THA_NGAY_DEN_TRAI IS NOT NULL AND TRUNC(tha.THA_NGAY_DEN_TRAI) <= TRUNC(V_MOC_NGAY)
                       AND pll.LL_TINH_TRANG_ID IN (SELECT ID FROM dang_o_trai UNION SELECT ID FROM da_ra_trai) THEN 1
                  WHEN V_IS_CHUA = 1 AND V_TT_TAT_CA = 1 AND V_CO_MOC_NGAY = 1
                       AND tha.THA_NGAY_DEN_TRAI IS NOT NULL AND TRUNC(tha.THA_NGAY_DEN_TRAI) > TRUNC(V_MOC_NGAY)
                       AND pll.LL_TINH_TRANG_ID IN (SELECT ID FROM case4_da_ra) THEN 1
                  WHEN V_IS_DU = 1 AND V_IS_DANG_TT = 1 AND V_CO_MOC_NGAY = 1
                       AND tha.THA_NGAY_DEN_TRAI IS NOT NULL AND TRUNC(tha.THA_NGAY_DEN_TRAI) <= TRUNC(V_MOC_NGAY)
                       AND pll.LL_TINH_TRANG_ID IN (SELECT ID FROM dang_o_trai) THEN 1
                  WHEN V_IS_DU = 1 AND V_IS_DA_RA_TT = 1 AND V_CO_MOC_NGAY = 1
                       AND tha.THA_NGAY_DEN_TRAI IS NOT NULL AND TRUNC(tha.THA_NGAY_DEN_TRAI) <= TRUNC(V_MOC_NGAY)
                       AND pll.LL_TINH_TRANG_ID IN (SELECT ID FROM da_ra_trai) THEN 1
                  WHEN V_IS_CHUA = 1 AND V_IS_DANG_TT = 1 AND V_CO_MOC_NGAY = 1
                       AND tha.THA_NGAY_DEN_TRAI IS NOT NULL AND TRUNC(tha.THA_NGAY_DEN_TRAI) > TRUNC(V_MOC_NGAY)
                       AND pll.LL_TINH_TRANG_ID IN (SELECT ID FROM dang_o_trai) THEN 1
                  WHEN V_IS_CHUA = 1 AND V_IS_DA_RA_TT = 1 AND V_CO_MOC_NGAY = 1
                       AND pll.LL_TINH_TRANG_ID IN (SELECT ID FROM case4_da_ra)
                       AND tha.THA_NGAY_DEN_TRAI IS NOT NULL AND TRUNC(tha.THA_NGAY_DEN_TRAI) > TRUNC(V_MOC_NGAY) THEN 1
                  WHEN V_DK_TAT_CA = 1 AND V_IS_DANG_TT = 1
                       AND tha.THA_NGAY_DEN_TRAI IS NOT NULL
                       AND pll.LL_TINH_TRANG_ID IN (SELECT ID FROM dang_o_trai) THEN 1
                  WHEN V_DK_TAT_CA = 1 AND V_IS_DA_RA_TT = 1
                       AND tha.THA_NGAY_DEN_TRAI IS NOT NULL
                       AND pll.LL_TINH_TRANG_ID IN (SELECT ID FROM da_ra_trai) THEN 1
                  ELSE 0
              END

              -- ??i t??ng
              AND (P_DOI_TUONG_ID IS NULL OR P_DOI_TUONG_ID = 0
                   OR (P_DOI_TUONG_ID = 1 AND pll.LL_DM_QUOC_TICH_ID IS NOT NULL AND pll.LL_DM_QUOC_TICH_ID <> V_VIET_NAM_QUOC_TICH_ID)
                   OR (P_DOI_TUONG_ID = 2 AND EXISTS (
                        SELECT 1 FROM QLPN.PN_THI_HANH_AN t2
                         WHERE t2.THA_PNLAI_LICH_ID = pll.ID AND NVL(t2.IS_DELETED,0)=0 AND t2.THA_TOI_DANH IS NOT NULL
                           AND EXISTS (
                               SELECT 1 FROM anqg_toi_danh td
                                WHERE REGEXP_LIKE(t2.THA_TOI_DANH, '(^|[^0-9])' || td.ID || '([^0-9]|$)')
                                   OR (t2.THA_TOI_DANH NOT LIKE '[%' AND TRIM(t2.THA_TOI_DANH) = TRIM(td.TD_MA))
                           )
                   ))
                   OR (P_DOI_TUONG_ID = 3 AND pll.LL_NGAY_SINH IS NOT NULL
                       AND (
                           (REGEXP_LIKE(TRIM(pll.LL_NGAY_SINH), '^\d{4}$')
                            AND TO_NUMBER(TRIM(pll.LL_NGAY_SINH)) BETWEEN EXTRACT(YEAR FROM ADD_MONTHS(SYSDATE,-216)) AND EXTRACT(YEAR FROM ADD_MONTHS(SYSDATE,-120)))
                           OR (REGEXP_LIKE(TRIM(pll.LL_NGAY_SINH), '^\d{1,2}/\d{1,2}/\d{4}$')
                               AND TO_DATE(TRIM(pll.LL_NGAY_SINH),'DD/MM/YYYY','NLS_DATE_LANGUAGE=AMERICAN')
                                   BETWEEN ADD_MONTHS(TRUNC(SYSDATE),-216) AND ADD_MONTHS(TRUNC(SYSDATE),-120))
                           OR (REGEXP_LIKE(TRIM(pll.LL_NGAY_SINH), '^\d{4}-\d{2}-\d{2}$')
                               AND TO_DATE(TRIM(pll.LL_NGAY_SINH),'YYYY-MM-DD','NLS_DATE_LANGUAGE=AMERICAN')
                                   BETWEEN ADD_MONTHS(TRUNC(SYSDATE),-216) AND ADD_MONTHS(TRUNC(SYSDATE),-120))
                       ))
              )

              -- HPBS ti?n
              AND (P_HPBS_TIEN_ID IS NULL OR P_HPBS_TIEN_ID = 0
                   OR (P_HPBS_TIEN_ID = 1 AND pll.ID NOT IN (SELECT PN_ID FROM hpbs_con_tien))
                   OR (P_HPBS_TIEN_ID = 2 AND pll.ID IN (SELECT PN_ID FROM hpbs_con_tien))
              )

              -- K? x?p lo?i + lo?i x?p lo?i (ch? khi có c? hai)
              AND (V_HAS_LOAI_FILTER = 0 OR V_KY_XEP_LOAI_LOWER IS NULL OR EXISTS (
                  SELECT 1 FROM QLPN.XEP_LOAIS xlf
                   WHERE NVL(xlf.IS_DELETED,0)=0 AND xlf.PHAM_NHAN_ID = pll.ID
                     AND (V_NAM_XL IS NULL OR xlf.XEP_LOAI_NAM = V_NAM_XL)
                     AND (
                         (V_KY_XEP_LOAI_LOWER LIKE '%quý i%' OR V_KY_XEP_LOAI_LOWER LIKE '%quy i%' OR V_KY_XEP_LOAI_LOWER LIKE '%quý 1%' OR V_KY_XEP_LOAI_LOWER LIKE '%quy 1%')
                         AND ((P_LOAI_XEP_LOAI_ID = 10000 AND xlf.XEP_LOAI_QUY_I IS NULL)
                           OR (P_LOAI_XEP_LOAI_ID = 10001 AND xlf.XEP_LOAI_QUY_I IS NOT NULL)
                           OR (P_LOAI_XEP_LOAI_ID NOT IN (10000,10001) AND xlf.XEP_LOAI_QUY_I = P_LOAI_XEP_LOAI_ID))
                         OR (V_KY_XEP_LOAI_LOWER LIKE '%quý ii%' OR V_KY_XEP_LOAI_LOWER LIKE '%quy ii%' OR V_KY_XEP_LOAI_LOWER LIKE '%quý 2%' OR V_KY_XEP_LOAI_LOWER LIKE '%quy 2%')
                         AND ((P_LOAI_XEP_LOAI_ID = 10000 AND xlf.XEP_LOAI_QUY_II IS NULL)
                           OR (P_LOAI_XEP_LOAI_ID = 10001 AND xlf.XEP_LOAI_QUY_II IS NOT NULL)
                           OR (P_LOAI_XEP_LOAI_ID NOT IN (10000,10001) AND xlf.XEP_LOAI_QUY_II = P_LOAI_XEP_LOAI_ID))
                         OR (V_KY_XEP_LOAI_LOWER LIKE '%6 tháng ??u%' OR V_KY_XEP_LOAI_LOWER LIKE '%6 thang dau%' OR V_KY_XEP_LOAI_LOWER LIKE '%??u n?m%' OR V_KY_XEP_LOAI_LOWER LIKE '%dau nam%')
                         AND ((P_LOAI_XEP_LOAI_ID = 10000 AND xlf.XEP_LOAI_6_THANG_DAU_NAM IS NULL)
                           OR (P_LOAI_XEP_LOAI_ID = 10001 AND xlf.XEP_LOAI_6_THANG_DAU_NAM IS NOT NULL)
                           OR (P_LOAI_XEP_LOAI_ID NOT IN (10000,10001) AND xlf.XEP_LOAI_6_THANG_DAU_NAM = P_LOAI_XEP_LOAI_ID))
                         OR (V_KY_XEP_LOAI_LOWER LIKE '%quý iii%' OR V_KY_XEP_LOAI_LOWER LIKE '%quy iii%' OR V_KY_XEP_LOAI_LOWER LIKE '%quý 3%' OR V_KY_XEP_LOAI_LOWER LIKE '%quy 3%')
                         AND ((P_LOAI_XEP_LOAI_ID = 10000 AND xlf.XEP_LOAI_QUY_III IS NULL)
                           OR (P_LOAI_XEP_LOAI_ID = 10001 AND xlf.XEP_LOAI_QUY_III IS NOT NULL)
                           OR (P_LOAI_XEP_LOAI_ID NOT IN (10000,10001) AND xlf.XEP_LOAI_QUY_III = P_LOAI_XEP_LOAI_ID))
                         OR (V_KY_XEP_LOAI_LOWER LIKE '%quý iv%' OR V_KY_XEP_LOAI_LOWER LIKE '%quy iv%' OR V_KY_XEP_LOAI_LOWER LIKE '%quý 4%' OR V_KY_XEP_LOAI_LOWER LIKE '%quy 4%')
                         AND ((P_LOAI_XEP_LOAI_ID = 10000 AND xlf.XEP_LOAI_QUY_IV IS NULL)
                           OR (P_LOAI_XEP_LOAI_ID = 10001 AND xlf.XEP_LOAI_QUY_IV IS NOT NULL)
                           OR (P_LOAI_XEP_LOAI_ID NOT IN (10000,10001) AND xlf.XEP_LOAI_QUY_IV = P_LOAI_XEP_LOAI_ID))
                         OR (V_KY_XEP_LOAI_LOWER LIKE '%6 tháng cu?i%' OR V_KY_XEP_LOAI_LOWER LIKE '%6 thang cuoi%' OR V_KY_XEP_LOAI_LOWER LIKE '%cu?i n?m%' OR V_KY_XEP_LOAI_LOWER LIKE '%cuoi nam%')
                         AND ((P_LOAI_XEP_LOAI_ID = 10000 AND xlf.XEP_LOAI_6_THANG_CUOI_NAM IS NULL)
                           OR (P_LOAI_XEP_LOAI_ID = 10001 AND xlf.XEP_LOAI_6_THANG_CUOI_NAM IS NOT NULL)
                           OR (P_LOAI_XEP_LOAI_ID NOT IN (10000,10001) AND xlf.XEP_LOAI_6_THANG_CUOI_NAM = P_LOAI_XEP_LOAI_ID))
                         OR (V_KY_XEP_LOAI_LOWER LIKE '%c? n?m%' OR V_KY_XEP_LOAI_LOWER LIKE '%ca nam%')
                         AND ((P_LOAI_XEP_LOAI_ID = 10000 AND xlf.XEP_LOAI_CA_NAM IS NULL)
                           OR (P_LOAI_XEP_LOAI_ID = 10001 AND xlf.XEP_LOAI_CA_NAM IS NOT NULL)
                           OR (P_LOAI_XEP_LOAI_ID NOT IN (10000,10001) AND xlf.XEP_LOAI_CA_NAM = P_LOAI_XEP_LOAI_ID))
                     )
              ))

              -- H? tên: BO_DAU c? tên PN và filter, so sánh contains (BO_DAU tr? UPPER)
              AND (P_HO_TEN_FILTER_NOSPACE IS NULL OR LENGTH(TRIM(P_HO_TEN_FILTER_NOSPACE)) = 0 OR
                   INSTR(
                       QLPN.BO_DAU(NVL(pll.LL_HO_TEN, '')),
                       QLPN.BO_DAU(TRIM(P_HO_TEN_FILTER_NOSPACE))
                   ) > 0
              )
        ),
        numbered AS (
            SELECT f.*,
                   COUNT(*) OVER() AS TOTAL_COUNT,
                   ROW_NUMBER() OVER (
                       ORDER BY
                           CASE WHEN V_SORT_NGAYSINH = 1 AND V_SORT_ASC = 1 THEN f.SORT_NGAY_SINH END ASC,
                           CASE WHEN V_SORT_NGAYSINH = 1 AND V_SORT_ASC = 0 THEN f.SORT_NGAY_SINH END DESC NULLS LAST,
                           CASE WHEN V_SORT_NGAYSINH = 1 AND V_SORT_ASC = 1 THEN f.PHAM_NHAN_ID END ASC,
                           CASE WHEN V_SORT_NGAYSINH = 1 AND V_SORT_ASC = 0 THEN f.PHAM_NHAN_ID END DESC NULLS LAST,
                           CASE WHEN V_SORT_DIACHI = 1 AND V_SORT_ASC = 1 THEN LOWER(f.DIA_CHI_THUONG_TRU) END ASC,
                           CASE WHEN V_SORT_DIACHI = 1 AND V_SORT_ASC = 0 THEN LOWER(f.DIA_CHI_THUONG_TRU) END DESC NULLS LAST,
                           CASE WHEN V_SORT_ANPHAT = 1 AND V_SORT_ASC = 1 THEN f.SORT_AN_PHAT END ASC,
                           CASE WHEN V_SORT_ANPHAT = 1 AND V_SORT_ASC = 0 THEN f.SORT_AN_PHAT END DESC NULLS LAST,
                           CASE WHEN V_SORT_NGAYDENTRAI = 1 AND V_SORT_ASC = 1 THEN f.NGAY_DEN_TRAI END ASC,
                           CASE WHEN V_SORT_NGAYDENTRAI = 1 AND V_SORT_ASC = 0 THEN f.NGAY_DEN_TRAI END DESC NULLS LAST,
                           CASE WHEN V_SORT_NGAYHETHAN = 1 AND V_SORT_ASC = 1 THEN f.NGAY_HET_HAN END ASC,
                           CASE WHEN V_SORT_NGAYHETHAN = 1 AND V_SORT_ASC = 0 THEN f.NGAY_HET_HAN END DESC NULLS LAST,
                           CASE WHEN V_SORT_HOTEN = 1 AND V_SORT_ASC = 1 THEN f.SORT_THEO_TEN END ASC,
                           CASE WHEN V_SORT_HOTEN = 1 AND V_SORT_ASC = 0 THEN f.SORT_THEO_TEN END DESC NULLS LAST,
                           CASE WHEN V_SORT_GIOITINH = 1 AND V_SORT_ASC = 1 THEN f.TEN_GIOI_TINH END ASC,
                           CASE WHEN V_SORT_GIOITINH = 1 AND V_SORT_ASC = 0 THEN f.TEN_GIOI_TINH END DESC NULLS LAST,
                           CASE WHEN V_SORT_GIOITINH = 1 AND V_SORT_ASC = 1 THEN f.PHAM_NHAN_ID END ASC,
                           CASE WHEN V_SORT_GIOITINH = 1 AND V_SORT_ASC = 0 THEN f.PHAM_NHAN_ID END DESC NULLS LAST,
                           CASE WHEN V_SORT_PHANDOI = 1 AND V_SORT_ASC = 1 THEN f.TEN_PHAN_DOI END ASC,
                           CASE WHEN V_SORT_PHANDOI = 1 AND V_SORT_ASC = 0 THEN f.TEN_PHAN_DOI END DESC NULLS LAST,
                           CASE WHEN V_SORT_PHANDOI = 1 AND V_SORT_ASC = 1 THEN f.PHAM_NHAN_ID END ASC,
                           CASE WHEN V_SORT_PHANDOI = 1 AND V_SORT_ASC = 0 THEN f.PHAM_NHAN_ID END DESC NULLS LAST,
                           CASE WHEN V_SORT_XL_Q1 = 1 AND V_SORT_ASC = 1 THEN f.XEP_LOAI_QUY_I END ASC,
                           CASE WHEN V_SORT_XL_Q1 = 1 AND V_SORT_ASC = 0 THEN f.XEP_LOAI_QUY_I END DESC NULLS LAST,
                           CASE WHEN V_SORT_XL_Q2 = 1 AND V_SORT_ASC = 1 THEN f.XEP_LOAI_QUY_II END ASC,
                           CASE WHEN V_SORT_XL_Q2 = 1 AND V_SORT_ASC = 0 THEN f.XEP_LOAI_QUY_II END DESC NULLS LAST,
                           CASE WHEN V_SORT_XL_Q3 = 1 AND V_SORT_ASC = 1 THEN f.XEP_LOAI_QUY_III END ASC,
                           CASE WHEN V_SORT_XL_Q3 = 1 AND V_SORT_ASC = 0 THEN f.XEP_LOAI_QUY_III END DESC NULLS LAST,
                           CASE WHEN V_SORT_XL_Q4 = 1 AND V_SORT_ASC = 1 THEN f.XEP_LOAI_QUY_IV END ASC,
                           CASE WHEN V_SORT_XL_Q4 = 1 AND V_SORT_ASC = 0 THEN f.XEP_LOAI_QUY_IV END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND V_SORT_FIELD = 'sohosolandau' THEN f.LL_SO_HO_SO_LAN_DAU END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND V_SORT_FIELD = 'sohosolandau' THEN f.LL_SO_HO_SO_LAN_DAU END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND V_SORT_FIELD = 'cccd' THEN f.LL_CCCD END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND V_SORT_FIELD = 'cccd' THEN f.LL_CCCD END DESC NULLS LAST,
                           CASE WHEN V_SORT_NGAYSINH = 0 AND V_SORT_DIACHI = 0 AND V_SORT_ANPHAT = 0
                                 AND V_SORT_NGAYDENTRAI = 0 AND V_SORT_NGAYHETHAN = 0
                                 AND V_SORT_HOTEN = 0 AND V_SORT_GIOITINH = 0
                                 AND V_SORT_PHANDOI = 0 AND V_SORT_XL_Q1 = 0 AND V_SORT_XL_Q2 = 0
                                 AND V_SORT_XL_Q3 = 0 AND V_SORT_XL_Q4 = 0 AND V_SORT_DEFAULT = 0 THEN f.PHAM_NHAN_ID END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 THEN f.PHAM_NHAN_ID END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 THEN f.PHAM_NHAN_ID END DESC NULLS LAST,
                           f.PHAM_NHAN_ID DESC
                   ) AS RN
              FROM filtered f
        )
        SELECT PHAM_NHAN_ID, LL_SO_HO_SO_LAN_DAU AS SO_HO_SO_LAN_DAU, LL_CCCD AS CCCD, LL_HO_TEN AS HO_TEN,
               SORT_THEO_TEN, LL_NGAY_SINH AS NGAY_SINH, TEN_GIOI_TINH, TEN_PHAN_DOI, TOI_DANH, AN_PHAT,
               NGAY_DEN_TRAI, NGAY_HET_HAN, LL_TINH_TRANG_ID, XEP_LOAI_QUY_I, XEP_LOAI_QUY_II, XEP_LOAI_QUY_III,
               XEP_LOAI_QUY_IV, XEP_LOAI_6_THANG_DAU_NAM, XEP_LOAI_6_THANG_CUOI_NAM, XEP_LOAI_CA_NAM,
               LL_DM_QUOC_TICH_ID, DIA_CHI_THUONG_TRU, TOTAL_COUNT
          FROM numbered
         WHERE P_MAX_RESULT_COUNT IS NULL
            OR (RN > NVL(P_SKIP_COUNT,0) AND RN <= NVL(P_SKIP_COUNT,0) + P_MAX_RESULT_COUNT);

    P_TOTAL_COUNT := 0;
END SP_GET_DS_PN_XEP_LOAI_THEO_KY;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_PT35_QLPN_THONG_KE_DE_NGHI_GTHA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_PT35_QLPN_THONG_KE_DE_NGHI_GTHA" (
--    SP_GET_DS_PT35_QLPN_THONG_KE_DE_NGHI_GTHA
-- BEGIN 
--     SP_GET_DS_PT35_QLPN_THONG_KE_DE_NGHI_GTHA(
--         -- p_ngay_xet => TO_DATE('01/01/2024', 'dd/mm/yyyy')
--         p_ngay_xet => NULL,
--         p_phan_doi_id => NULL,
--         p_ma_toi => 0
--     );
-- END;
-- N?u không truy?n tham s? p_ngay_xet, p_phan_doi_id, p_ma_toi thì s? l?y t?t c? d? li?u
-- M?t ph?m nhân n?u 

    p_ngay_xet          IN DATE DEFAULT NULL,
    p_phan_doi_id		IN NUMBER DEFAULT NULL,
    p_ma_doi_tuong            IN NUMBER DEFAULT 0, -- 0: t?t c?, 1: có ch??ng 13, 2: không có ch??ng 13
    p_ma_trai_giam IN VARCHAR2 DEFAULT NULL
) AS
    p_cursor            SYS_REFCURSOR;
    v_id_lap_cong       NUMBER DEFAULT 0;
    v_id_gia_yeu        NUMBER DEFAULT 0;
    v_benh_hiem_ngheo   NUMBER DEFAULT 0;
    v_duoi_18_tuoi      NUMBER DEFAULT 0;
    v_16_toi_18_tuoi    NUMBER DEFAULT 0;
BEGIN
    SELECT ID
    INTO v_id_lap_cong
    FROM DM_GHI_CHU_RIENGS
    WHERE GCR_TEN = 'L?p công' and GCR_TRANG_THAI = 1 and IS_DELETED = 0
    FETCH FIRST 1 ROWS ONLY;

    select ID
    INTO v_id_gia_yeu
    FROM DM_GHI_CHU_RIENGS
    WHERE GCR_TEN = 'Già y?u' and GCR_TRANG_THAI = 1 and IS_DELETED = 0
    FETCH FIRST 1 ROWS ONLY;

    SELECT ID
    INTO v_benh_hiem_ngheo
    FROM DM_GHI_CHU_RIENGS
    WHERE GCR_TEN = 'M?c b?nh hi?m nghèo' and GCR_TRANG_THAI = 1 and IS_DELETED = 0
    FETCH FIRST 1 ROWS ONLY;

    SELECT ID
    INTO v_duoi_18_tuoi
    FROM DM_GHI_CHU_RIENGS
    WHERE GCR_TEN = 'Ng??i d??i 18 tu?i ph?m t?i' and GCR_TRANG_THAI = 1 and IS_DELETED = 0
    FETCH FIRST 1 ROWS ONLY;

    SELECT ID
    INTO v_16_toi_18_tuoi
    FROM DM_GHI_CHU_RIENGS
    WHERE GCR_TEN = 'Ph?m t?i lúc t? 16 ??n d??i 18 tu?i' and GCR_TRANG_THAI = 1 and IS_DELETED = 0
    FETCH FIRST 1 ROWS ONLY;

    OPEN p_cursor FOR 
    WITH td_split AS (
            SELECT 
                ptha.THA_PNLAI_LICH_ID,
                replace(replace(ptha.THA_TOI_DANH,'[',''),']','') AS TOI_DANH_ID,
                ptha.THA_MUC_AN_ID
            FROM QLPN.PN_THI_HANH_AN ptha
            LEFT JOIN DM_TOI_DANHS td ON td.ID = ptha.THA_TOI_DANH
            WHERE ptha.IS_DELETED = 0
        ),
    NUM_GEN AS (
        SELECT LEVEL AS N
        FROM DUAL
        CONNECT BY LEVEL <= 20
    ),
    SPLIT_TOI_DANH AS (
        SELECT
            TF.THA_PNLAI_LICH_ID,
            TO_NUMBER(TRIM(
                REGEXP_SUBSTR(TF.TOI_DANH_ID, '[^,]+', 1, NG.N)
            )) AS TOI_DANH_ID
        FROM td_split TF
        JOIN NUM_GEN NG
            ON NG.N <= REGEXP_COUNT(TF.TOI_DANH_ID, ',') + 1
        WHERE REGEXP_SUBSTR(TF.TOI_DANH_ID, '[^,]+', 1, NG.N) IS NOT NULL
    ),
    TD_AGG AS (
        SELECT
            S.THA_PNLAI_LICH_ID,
            LISTAGG(DISTINCT DTD.TD_CHUONG, ', ')
                WITHIN GROUP (ORDER BY DTD.TD_TEN) AS TOI_DANH_CHUONGS,
            LISTAGG(DISTINCT DTD.TD_TEN, ', ')
                WITHIN GROUP (ORDER BY DTD.TD_TEN) AS TOI_DANH_TENS
        FROM SPLIT_TOI_DANH S
        LEFT JOIN DM_TOI_DANHS DTD ON DTD.ID = S.TOI_DANH_ID
        GROUP BY S.THA_PNLAI_LICH_ID
    )

	SELECT
        COUNT(DISTINCT CASE WHEN UPPER(TD.GIOI_TINH) = u'NAM' THEN TD.PHAM_NHAN_ID END ) AS NAM,
        COUNT(DISTINCT CASE WHEN UPPER(TD.GIOI_TINH) = u'N\1eee' THEN TD.PHAM_NHAN_ID END ) AS NU,
        COUNT(DISTINCT CASE WHEN UPPER(TD.GIOI_TINH) NOT IN (u'NAM', u'N\1eee') OR UPPER(TD.GIOI_TINH) IS NULL THEN TD.PHAM_NHAN_ID END ) AS KHAC,
        COUNT(DISTINCT TD.PHAM_NHAN_ID) AS TONG_CONG,
        COUNT(DISTINCT CASE WHEN TD.TOI_DANH_CHUONGS LIKE '%13%' THEN PHAM_NHAN_ID END) AS PT_CAC_TOI_ANQG, -- C13
        COUNT(DISTINCT CASE WHEN UPPER(TD.TOI_DANH_TENS) LIKE '%GI?T%' THEN PHAM_NHAN_ID END ) AS PT_GIET_NGUOI, -- C14
        COUNT(DISTINCT CASE WHEN UPPER(TD.TOI_DANH_TENS) LIKE '%C??P%' THEN PHAM_NHAN_ID END ) AS PT_CUOP, -- C15
        COUNT(DISTINCT CASE WHEN UPPER(TD.TOI_DANH_TENS) LIKE '%HI?P DÂM%' THEN PHAM_NHAN_ID END ) AS PT_HIEP_DAM, -- C16
        COUNT(DISTINCT CASE WHEN UPPER(TD.TOI_DANH_TENS) LIKE '%MA TÚY%' THEN PHAM_NHAN_ID END ) AS PT_MA_TUY, -- C17
        COUNT(DISTINCT CASE WHEN UPPER(TD.TOI_DANH_TENS) LIKE UPPER('%C? ý làm tráI%') THEN PHAM_NHAN_ID END ) AS PT_CO_Y_LAM_TRAI, -- C18
        -- T?i danh tham nh?ng l?y theo ch??ng 23
        -- Trang BA 30/3/2026--
        COUNT(DISTINCT CASE WHEN TD.TOI_DANH_CHUONGS LIKE '%23%' THEN PHAM_NHAN_ID END ) AS PT_THAM_NHUNG, -- C19
        COUNT(DISTINCT CASE WHEN 
                TD.TOI_DANH_CHUONGS NOT LIKE '%23%'   
            AND TD.TOI_DANH_CHUONGS NOT LIKE '%13%'
            AND UPPER(TD.TOI_DANH_TENS) NOT LIKE '%GI?T%'
            AND UPPER(TD.TOI_DANH_TENS) NOT LIKE '%C??P%'
            AND UPPER(TD.TOI_DANH_TENS) NOT LIKE '%HI?P DÂM%'
            AND UPPER(TD.TOI_DANH_TENS) NOT LIKE '%MA TÚY%'
            AND UPPER(TD.TOI_DANH_TENS) NOT LIKE UPPER('%C? ý làm tráI%')
            THEN 1 
            END ) AS PT_KHAC, -- C20
        COUNT(CASE WHEN TD.THA_AN_PHAT LIKE '%chung thân%' THEN PHAM_NHAN_ID END) AS AN_CHUNG_THAN,
        COUNT(CASE WHEN TD.MUC_AN_NAM IS NOT NULL AND TD.MUC_AN_NAM <= 30 AND TD.MUC_AN_NAM > 15 THEN PHAM_NHAN_ID END) AS MUC_AN_NAM,
        COUNT(CASE WHEN TD.MUC_AN_NAM IS NOT NULL AND TD.MUC_AN_NAM <= 15 AND TD.MUC_AN_NAM > 7 THEN PHAM_NHAN_ID END) AS MUC_AN_7_DEN_15, -- C21
        COUNT(CASE WHEN TD.MUC_AN_NAM IS NOT NULL AND TD.MUC_AN_NAM <= 7  AND TD.MUC_AN_NAM > 3 THEN PHAM_NHAN_ID END) AS MUC_AN_3_DEN_7,
        COUNT(CASE WHEN TD.MUC_AN_NAM IS NOT NULL AND TD.MUC_AN_NAM <= 3 THEN PHAM_NHAN_ID END) AS MUC_AN_DUOI_3,
        COUNT(CASE WHEN REGEXP_LIKE( TD.GHI_CHU_RIENG, '(^|[^0-9])' || TO_CHAR(v_id_lap_cong) || '([^0-9]|$)' ) THEN PHAM_NHAN_ID END) AS LAP_CONG,
        COUNT(CASE WHEN REGEXP_LIKE( TD.GHI_CHU_RIENG, '(^|[^0-9])' || TO_CHAR(v_id_gia_yeu) || '([^0-9]|$)' ) THEN PHAM_NHAN_ID END) AS GIA_YEU,
        COUNT(CASE WHEN REGEXP_LIKE( TD.GHI_CHU_RIENG, '(^|[^0-9])' || TO_CHAR(v_benh_hiem_ngheo) || '([^0-9]|$)' ) THEN PHAM_NHAN_ID END) AS BENH_HIEM_NGHEO,
        COUNT(CASE WHEN REGEXP_LIKE( TD.GHI_CHU_RIENG, '(^|[^0-9])' || TO_CHAR(v_duoi_18_tuoi) || '([^0-9]|$)' ) THEN PHAM_NHAN_ID END) AS DUOI_18_TUOI

    FROM (
		SELECT 
			GTH.NGAY_XET,
			LL.GIOI_TINH,
            LL.PHAM_NHAN_ID,
            LL.GHI_CHU_RIENG,
			THA.THA_TOI_DANH,
			THA.THA_MUC_AN_ID,
            LOWER(THA.THA_AN_PHAT) AS THA_AN_PHAT,
            FN_AN_PHAT_TO_NAM(THA.THA_AN_PHAT) as MUC_AN_NAM,
            TDA.TOI_DANH_CHUONGS,
            TDA.TOI_DANH_TENS,
            LL.PHAN_DOI_ID
		FROM QLPN.GIAM_THOI_HANS GTH
		LEFT JOIN QLPN.PN_THI_HANH_AN THA 
        ON GTH.PHAM_NHAN_ID = THA.THA_PNLAI_LICH_ID
        LEFT JOIN TD_AGG TDA
        ON TDA.THA_PNLAI_LICH_ID = THA.THA_PNLAI_LICH_ID
		LEFT JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET LL
        ON GTH.PHAM_NHAN_ID = LL.PHAM_NHAN_ID
        where ll.TRAI_GIAM_MA = p_ma_trai_giam
	) TD

    WHERE 1= 1
	AND (p_ngay_xet IS NULL OR TD.NGAY_XET = p_ngay_xet)
    AND (p_phan_doi_id IS NULL OR TD.PHAN_DOI_ID = p_phan_doi_id)
    AND (
        p_ma_doi_tuong = 0 OR p_ma_doi_tuong IS NULL
        OR (p_ma_doi_tuong = 1 AND TD.TOI_DANH_CHUONGS LIKE '%13%')
        OR (p_ma_doi_tuong = 2 AND (TD.TOI_DANH_CHUONGS NOT LIKE '%13%'  OR TD.TOI_DANH_CHUONGS IS NULL))
    );

	DBMS_SQL.RETURN_RESULT(p_cursor);

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('L?i: ' || SQLERRM);
        RAISE;

END SP_GET_DS_PT35_QLPN_THONG_KE_DE_NGHI_GTHA;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_THA_CO_DIEU_KIEN_CAP_NHAT_QD_TOA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_THA_CO_DIEU_KIEN_CAP_NHAT_QD_TOA" (
    p_dot_tha_id   IN NUMBER    DEFAULT NULL,
    p_phan_doi_id  IN NUMBER    DEFAULT NULL,
    p_doi_tuong_id IN NUMBER    DEFAULT NULL,  -- 2=ANQG, 1=hình s?
    p_ho_ten       IN NVARCHAR2 DEFAULT NULL,
    p_quoc_tich_id IN NUMBER    DEFAULT NULL ,  -- 1=VN, 2=n??c ngoài
    p_ma_trai_giam IN VARCHAR2 default null
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    -- T?i danh split
    toi_danh_split AS (
        SELECT
            ptha2.THA_PNLAI_LICH_ID,
            TO_NUMBER(REGEXP_SUBSTR(
                REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''),
                '[^,]+',1,LEVEL
            )) AS TOI_DANH_ID
          FROM PN_THI_HANH_AN ptha2
         WHERE ptha2.THA_TOI_DANH IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                       REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''),',') + 1
               AND PRIOR ptha2.THA_PNLAI_LICH_ID = ptha2.THA_PNLAI_LICH_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    -- T?i danh text g?p
    toi_danh_agg AS (
        SELECT s.THA_PNLAI_LICH_ID,
               RTRIM(
                   XMLAGG(
                       XMLELEMENT(e, dtd.TD_TEN || '; ')
                       ORDER BY dtd.TD_TEN
                   ).extract('//text()').GETSTRINGVAL(), '; '
               ) AS TOI_DANH
          FROM toi_danh_split s
          LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
         GROUP BY s.THA_PNLAI_LICH_ID
    ),
    -- ??i t??ng: 1=ANQG(ch??ng 13), 2=hình s?
    doi_tuong_agg AS (
        SELECT s.THA_PNLAI_LICH_ID,
               CASE WHEN COUNT(CASE WHEN dtd.TD_CHUONG = '13' THEN 1 END) > 0
                    THEN 2 ELSE 1
               END AS DOI_TUONG_ID
          FROM toi_danh_split s
          LEFT JOIN DM_TOI_DANHS dtd
            ON dtd.ID = s.TOI_DANH_ID
           AND NVL(dtd.IS_DELETED,0) = 0
         GROUP BY s.THA_PNLAI_LICH_ID
    )
    SELECT
        ll.LL_HO_TEN                                               AS "HoTen",
        SUBSTR(ll.LL_NGAY_SINH,-4)                                 AS "NamSinh",
        dgt.GT_TEN                                                 AS "GioiTinh",
        CASE
            WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                       WHEN NULLIF(TRIM(dxp.XP_TEN), u'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || dxp.XP_TEN
                                ELSE dxp.XP_TEN END
                       ELSE u'' END
                || CASE
                       WHEN NULLIF(TRIM(dttp.TTP_TEN), u'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                  OR NULLIF(TRIM(dxp.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || dttp.TTP_TEN
                                ELSE dttp.TTP_TEN END
                       ELSE u'' END
            )
            ELSE NULL
        END                                                        AS "DiaChiThuongTru",
        td_agg.TOI_DANH                                            AS "ToiDanh",
        ll.LL_SO_TIEN_AN                                           AS "SoTienAn",
        TO_CHAR(ptha.THA_NGAY_BAT,'DD/MM/YYYY')                  AS "NgayBat",
        ptha.THA_AN_PHAT                                           AS "AnPhat",
        TO_CHAR(ptha.THA_NGAY_HET_HAN,'DD/MM/YYYY')              AS "NgayHetHan",
        tcdk.NGAY_THA                                              AS "NgayTha",
        TO_CHAR(tcdk.NGAY_QUYET_DINH,'DD/MM/YYYY')                                       AS "NgayQuyetDinh",
        TO_CHAR(tcdk.NGAY_TRINH_DIEN,'DD/MM/YYYY')                                       AS "NgayTrinhDien",
        dpd.PD_TEN                                                 AS "PhanDoi"
    FROM THA_CO_DIEU_KIENS tcdk
    JOIN PN_LAI_LICHS ll
        ON tcdk.PHAM_NHAN_ID = ll.ID
       AND ll.IS_DELETED = 0
    JOIN PN_THI_HANH_AN ptha
        ON ll.ID = ptha.THA_PNLAI_LICH_ID
       AND NVL(ptha.IS_DELETED,0) = 0
    JOIN PN_DOT_THA_CO_DIEU_KIENS pdtcdk
        ON TRUNC(tcdk.NGAY_XET) = TRUNC(pdtcdk.DTCDK_NGAY_XET)
       AND NVL(pdtcdk.IS_DELETED,0) = 0
    LEFT JOIN DM_PHAN_DOIS dpd
        ON ll.LL_PHAN_DOI_ID = dpd.ID
    LEFT JOIN DM_GIOI_TINHS dgt
        ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_QUOC_TICHS dqt 
        ON ll.LL_DM_QUOC_TICH_ID = dqt.ID
       AND NVL(dqt.IS_DELETED,0) = 0
    LEFT JOIN DM_TINH_THANH_PHO dttp
        ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp.ID
       AND NVL(dttp.IS_DELETED,0) = 0
    LEFT JOIN DM_XA_PHUONG dxp
        ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dxp.ID
       AND NVL(dxp.IS_DELETED,0) = 0
    LEFT JOIN toi_danh_agg td_agg
        ON ll.ID = td_agg.THA_PNLAI_LICH_ID
    LEFT JOIN doi_tuong_agg dt_agg
        ON ll.ID = dt_agg.THA_PNLAI_LICH_ID

    WHERE NVL(tcdk.IS_DELETED,0) = 0
      and (p_ma_trai_giam is null or ll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA =p_ma_trai_giam))
      -- Filter ??t tha
      AND (p_dot_tha_id IS NULL OR pdtcdk.ID = p_dot_tha_id)
      -- Filter phân ??i
      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
      -- Filter h? tên
      AND (p_ho_ten IS NULL OR TRIM(p_ho_ten) = u''
           OR UPPER(ll.LL_HO_TEN) LIKE u'%' || UPPER(TRIM(p_ho_ten)) || u'%')
      -- Filter qu?c t?ch: 1=VN, 2=n??c ngoài
      AND (p_quoc_tich_id IS NULL OR p_quoc_tich_id = 0
           OR (p_quoc_tich_id = 2 AND dqt.QT_MA = '250')
           OR (p_quoc_tich_id = -1 AND (dqt.QT_MA IS NULL OR dqt.QT_MA <> '250')))
      -- Filter ??i t??ng: 1=ANQG, 2=hình s?
      AND (p_doi_tuong_id IS NULL
           OR dt_agg.DOI_TUONG_ID = p_doi_tuong_id)

    ORDER BY ll.LL_HO_TEN;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            u'L\1ed7i SP_GET_DS_THA_CO_DIEU_KIEN: ' || SQLERRM);
END SP_GET_DS_THA_CO_DIEU_KIEN_CAP_NHAT_QD_TOA;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_THA_CO_DK_EXCEL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_THA_CO_DK_EXCEL" (
	p_pn_ids IN NVARCHAR2 DEFAULT NULL,
    p_dot_tha_id         IN NUMBER DEFAULT NULL,
    p_tinh_trang_tha     IN NUMBER DEFAULT NULL,
    p_phan_doi_id        IN NUMBER DEFAULT NULL,
    p_doi_tuong_id       IN NUMBER DEFAULT NULL,
    p_quoc_tich          IN NUMBER DEFAULT NULL,
    p_nghien_ma_tuy      IN NUMBER DEFAULT NULL,
    p_tim_kiem           IN NVARCHAR2 DEFAULT NULL,
    p_dia_chi_thuong_tru IN NUMBER DEFAULT NULL,
    p_ma_trai_giam       IN NUMBER DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    -- ====================== L?c tha có ?i?u ki?n (gi?ng procedure c?) ======================
    		ID_LIST AS (
	            SELECT DISTINCT TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
	            FROM DUAL
	            CONNECT BY LEVEL <= CASE
	                    WHEN p_pn_ids IS NULL THEN 0
	                    WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
	                    ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
	                END
	              AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
	              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
	    ),
    tha_filtered AS (
        SELECT
            t.PHAM_NHAN_ID,
            t.NGAY_XET,
            t.NGAY_THA,
            t.SO_QUYET_DINH_THA,
            t.NGAY_QUYET_DINH_THA,
            t.TINH_TRANG_ID,
            t.ID AS THA_CO_DIEU_KIEN_ID,
            ROW_NUMBER() OVER (PARTITION BY t.PHAM_NHAN_ID ORDER BY t.NGAY_XET DESC) AS rn
        FROM THA_CO_DIEU_KIENS t
        LEFT JOIN PN_DOT_THA_CO_DIEU_KIENS dot
            ON TRUNC(t.NGAY_XET) = TRUNC(dot.DTCDK_NGAY_XET)
           AND NVL(dot.IS_DELETED, 0) = 0
        WHERE NVL(t.IS_DELETED, 0) = 0
                 AND (p_pn_ids IS NULL OR t.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
          AND t.SO_QUYET_DINH_THA IS NOT NULL
          AND (p_dot_tha_id IS NULL OR dot.ID = p_dot_tha_id)
          AND (p_tinh_trang_tha IS NULL OR p_tinh_trang_tha = 0 OR t.TINH_TRANG_ID = p_tinh_trang_tha)
    ),

    -- ====================== Các CTE h? tr? khác (gi? nguyên logic c?) ======================
    nghien_mt AS (
        SELECT DISTINCT nmt.NMT_PN_LAI_LICH_ID AS PHAM_NHAN_ID
        FROM PN_NGHIEN_MT nmt
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = nmt.NMT_PN_LAI_LICH_ID AND tf.rn = 1
        WHERE NVL(nmt.IS_DELETED, 0) = 0
    ),

    split_toi_danh AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            TO_NUMBER(REGEXP_SUBSTR(REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''), '[0-9]+', 1, LEVEL)) AS TOI_DANH_ID
        FROM PN_THI_HANH_AN ptha
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID AND tf.rn = 1
        WHERE ptha.THA_TOI_DANH IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
             AND PRIOR ptha.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
             AND PRIOR SYS_GUID() IS NOT NULL
    ),

    toi_danh_agg AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            LISTAGG(DISTINCT dtd.TD_TEN, ', ') WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH
        FROM split_toi_danh s
        LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
        GROUP BY s.THA_PNLAI_LICH_ID
    ),

    toi_danh_chuong AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            dtd.TD_CHUONG
        FROM (
            SELECT THA_PNLAI_LICH_ID, TOI_DANH_ID,
                   ROW_NUMBER() OVER (PARTITION BY THA_PNLAI_LICH_ID ORDER BY TOI_DANH_ID) AS rn
            FROM split_toi_danh
        ) s
        LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
        WHERE s.rn = 1
    ),

    quoc_tich_info AS (
        SELECT ll.ID AS PHAM_NHAN_ID, qt.QT_MA
        FROM PN_LAI_LICHS ll
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = ll.ID AND tf.rn = 1
        LEFT JOIN DM_QUOC_TICHS qt ON qt.ID = ll.LL_DM_QUOC_TICH_ID AND NVL(qt.IS_DELETED, 0) = 0
        WHERE ll.IS_DELETED = 0
    ),

    latest_tha AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            ptha.THA_NGAY_BAT,
            ptha.THA_AN_PHAT,
            ptha.THA_NGAY_BAN_AN,
            ptha.THA_NGAY_HET_HAN,
            ptha.THA_GHI_CHU_DAC_BIET,
            ptha.THA_THOI_GIAN_TAM_GIAM,
            ptha.THA_THOI_GIAN_TAM_GIU,
            ptha.THA_NGAY_DEN_TRAI,
            ptha.THA_SO_BAN_AN,
            ptha.THA_CO_QUAN_LAP_ID,
            ptha.THA_TOA_QD_ID,
            ROW_NUMBER() OVER (
                PARTITION BY ptha.THA_PNLAI_LICH_ID
                ORDER BY NVL(ptha.THA_NGAY_BAN_AN, TO_DATE('01-JAN-1900','DD-MON-YYYY')) DESC, ptha.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN ptha
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID AND tf.rn = 1
    ),

    latest_phan_loai AS (
        SELECT pl1.PHAM_NHAN_ID, pl1.LOAI_PHAN_LOAI_ID, pl1.NGAY_PHAN_LOAI
        FROM PHAN_LOAIS pl1
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = pl1.PHAM_NHAN_ID AND tf.rn = 1
        INNER JOIN (
            SELECT PHAM_NHAN_ID, MAX(NGAY_PHAN_LOAI) AS MAX_NGAY
            FROM PHAN_LOAIS
            GROUP BY PHAM_NHAN_ID
        ) pl2 ON pl1.PHAM_NHAN_ID = pl2.PHAM_NHAN_ID AND pl1.NGAY_PHAN_LOAI = pl2.MAX_NGAY
    ),

    latest_gth AS (
        SELECT
            gth.PHAM_NHAN_ID,
            gth.MUC_GIAM_ID,
            ROW_NUMBER() OVER (PARTITION BY gth.PHAM_NHAN_ID ORDER BY gth.ID DESC) AS rn
        FROM GIAM_THOI_HANS gth
        INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = gth.PHAM_NHAN_ID AND tf.rn = 1
    ),

    -- ====================== THÊM: Thông tin thân nhân (B? - M? - V?/Ch?ng) ======================
    than_nhan_bo AS (
        SELECT 
            tnnt.PHAM_NHAN_ID,
            tnnt.HO_TEN_THAN_NHAN,
            ROW_NUMBER() OVER (PARTITION BY tnnt.PHAM_NHAN_ID ORDER BY tnnt.ID) AS rn   -- l?y cái ??u tiên n?u có nhi?u
        FROM THAN_NHAN_NGUOI_THANS tnnt
        JOIN DM_QUAN_HE_VOI_PHAM_NHANS dqh ON tnnt.QUAN_HE_ID = dqh.ID
        WHERE dqh.QHVPN_MA = '121'
          AND NVL(tnnt.IS_DELETED, 0) = 0
    ),

    than_nhan_me AS (
        SELECT 
            tnnt.PHAM_NHAN_ID,
            tnnt.HO_TEN_THAN_NHAN,
            ROW_NUMBER() OVER (PARTITION BY tnnt.PHAM_NHAN_ID ORDER BY tnnt.ID) AS rn
        FROM THAN_NHAN_NGUOI_THANS tnnt
        JOIN DM_QUAN_HE_VOI_PHAM_NHANS dqh ON tnnt.QUAN_HE_ID = dqh.ID
        WHERE dqh.QHVPN_MA = '122'
          AND NVL(tnnt.IS_DELETED, 0) = 0
    ),

    than_nhan_vc AS (
        SELECT 
            tnnt.PHAM_NHAN_ID,
            tnnt.HO_TEN_THAN_NHAN,
            ROW_NUMBER() OVER (PARTITION BY tnnt.PHAM_NHAN_ID ORDER BY tnnt.ID) AS rn
        FROM THAN_NHAN_NGUOI_THANS tnnt
        JOIN DM_QUAN_HE_VOI_PHAM_NHANS dqh ON tnnt.QUAN_HE_ID = dqh.ID
        WHERE dqh.QHVPN_MA IN ('131', '132')
          AND NVL(tnnt.IS_DELETED, 0) = 0
    ),
    da_chap_hanh_data AS (
        SELECT 
            tf.PHAM_NHAN_ID,
            QLPN.FN_GET_DA_CHAP_HANH_THEO_NGAY(tf.PHAM_NHAN_ID, tf.NGAY_XET) AS DA_CH_OBJ
        FROM tha_filtered tf 
        WHERE tf.rn = 1
    )

    -- ====================== QUERY CHÍNH ======================
    SELECT
        ll.ID AS pham_nhan_id,
        ll.LL_HO_TEN AS ho_ten,
        ll.LL_TEN_KHAC AS ten_khac,
        SUBSTR(ll.LL_NGAY_SINH, -4)  AS nam_sinh,
        dgt.GT_TEN AS gioi_tinh,
	    CASE
		        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
		          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
		          OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
		        THEN TRIM(
		            NVL(NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u''), u'')
		            || CASE
		                WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
		                    CASE
		                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
		                            THEN u', ' || dxp_thuong_tru.XP_TEN
		                        ELSE dxp_thuong_tru.XP_TEN
		                    END
		                ELSE u''
		               END
		            || CASE
		                WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
		                    CASE
		                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
		                          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
		                            THEN u', ' || dttp_thuong_tru.TTP_TEN
		                        ELSE dttp_thuong_tru.TTP_TEN
		                    END
		                ELSE u''
		               END
		        )
		        ELSE NULL
		    END AS noi_dang_ky_thuong_tru,
	    CASE
		        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
		          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
		          OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
		        THEN TRIM(
		            NVL(NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u''), u'')
		            || CASE
		                WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
		                    CASE
		                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
		                            THEN u', ' || dxp_thuong_tru.XP_TEN
		                        ELSE dxp_thuong_tru.XP_TEN
		                    END
		                ELSE u''
		               END
		            || CASE
		                WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
		                    CASE
		                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
		                          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
		                            THEN u', ' || dttp_thuong_tru.TTP_TEN
		                        ELSE dttp_thuong_tru.TTP_TEN
		                    END
		                ELSE u''
		               END
		        )
		        ELSE NULL
		    END AS noi_ve_cu_tru,     
        td_agg.TOI_DANH AS toi_danh,
        TO_CHAR(ptha.THA_NGAY_BAT, 'DD/MM/YYYY') AS ngay_bat,
        ptha.THA_AN_PHAT AS an_phat,
        dttpn.TTPN_TEN AS tinh_trang,
        -- t?m giam, t?m gi?
        ptha.THA_THOI_GIAN_TAM_GIAM AS tam_giam,                                 
        ptha.THA_THOI_GIAN_TAM_GIU AS tam_giu,                              

        TO_CHAR(ptha.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY') AS ngay_den_trai,
		CASE
            WHEN NVL(dch.DA_CH_OBJ.nam, 0) = 0
             AND NVL(dch.DA_CH_OBJ.thang, 0) = 0
             AND NVL(dch.DA_CH_OBJ.ngay, 0) = 0
            THEN TO_NCHAR('Không')
            ELSE TRIM(
                CASE WHEN NVL(dch.DA_CH_OBJ.nam,   0)>0 THEN TO_CHAR(dch.DA_CH_OBJ.nam)   ||u' n\0103m '   ELSE u'' END ||
                CASE WHEN NVL(dch.DA_CH_OBJ.thang, 0)>0 THEN TO_CHAR(dch.DA_CH_OBJ.thang) ||u' th\00e1ng ' ELSE u'' END ||
                CASE WHEN NVL(dch.DA_CH_OBJ.ngay, 0)>0 THEN TO_CHAR(dch.DA_CH_OBJ.ngay)  ||u' ng\00e0y'   ELSE u'' END
            )
        END AS da_chap_hanh, 
        QLPN.FN_GET_GIAM_THOI_HAN(ll.ID) AS da_giam_an,
        QLPN.FN_TINH_THOI_GIAN_CON_LAI(ll.ID,sysdate) AS an_con_lai, 

        ptha.THA_SO_BAN_AN AS ban_an_so,                      
        TO_CHAR(ptha.THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS ngay_ban_an,
        dcq.CQ_TEN  AS toa_ban_an,                                   
        tf.SO_QUYET_DINH_THA AS so_qd_tha,
        TO_CHAR(tf.NGAY_QUYET_DINH_THA, 'DD/MM/YYYY') AS ngay_qd_tha,
        dcq2.CQ_TEN  AS toa_qd_tha,                        

        bo_agg.HO_TEN_THAN_NHAN AS ho_ten_bo,
        me_agg.HO_TEN_THAN_NHAN AS ho_ten_me,
        vc_agg.HO_TEN_THAN_NHAN AS ho_ten_vo_chong,

        FN_TONG_HOP_KET_QUA_CAI_TAO(ll.ID) AS xep_loai_cai_tao,

        NULL AS ghi_chu  
    FROM PN_LAI_LICHS ll
    INNER JOIN tha_filtered tf ON tf.PHAM_NHAN_ID = ll.ID AND tf.rn = 1
    LEFT JOIN DM_TRAI_GIAMS dtg ON ll.LL_TRAI_GIAM_ID = dtg.ID
    LEFT JOIN DM_TINH_THANH_PHO dvhc ON ll.LL_NOI_THA_VE_CU_TRU_PROVICE = dvhc.ID
    LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN latest_tha ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID AND ptha.rn = 1
    LEFT JOIN DM_PHAN_DOIS dpd ON ll.LL_PHAN_DOI_ID = dpd.ID
    LEFT JOIN latest_phan_loai pl_latest ON ll.ID = pl_latest.PHAM_NHAN_ID
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg ON pl_latest.LOAI_PHAN_LOAI_ID = dplgg.ID
    LEFT JOIN toi_danh_agg td_agg ON ll.ID = td_agg.THA_PNLAI_LICH_ID
    LEFT JOIN latest_gth gth ON ll.ID = gth.PHAM_NHAN_ID AND gth.rn = 1
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
    LEFT JOIN DM_CO_QUANS dcq ON ptha.THA_CO_QUAN_LAP_ID = dcq.ID 
    LEFT JOIN DM_CO_QUANS dcq2 ON ptha.THA_TOA_QD_ID = dcq2.ID 
    LEFT JOIN PN_NGHIEN_MT pnm ON ll.ID = pnm.NMT_PN_LAI_LICH_ID 
    LEFT JOIN DM_QUOC_TICHS dqt ON ll.LL_DM_QUOC_TICH_ID  = dqt.ID
    LEFT JOIN toi_danh_chuong tdc ON ll.ID = tdc.THA_PNLAI_LICH_ID
	LEFT JOIN da_chap_hanh_data dch ON dch.PHAM_NHAN_ID = ll.ID
	LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru 
		    ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID 
		    AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
		-- Join danh m?c ph??ng/xã — th??ng trú
	LEFT JOIN DM_XA_PHUONG dxp_thuong_tru 
		    ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID 
		    AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
	LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dttpn
	ON ll.LL_TINH_TRANG_ID = dttpn.ID
    -- Thân nhân
    LEFT JOIN than_nhan_bo bo_agg ON ll.ID = bo_agg.PHAM_NHAN_ID AND bo_agg.rn = 1
    LEFT JOIN than_nhan_me me_agg ON ll.ID = me_agg.PHAM_NHAN_ID AND me_agg.rn = 1
    LEFT JOIN than_nhan_vc vc_agg ON ll.ID = vc_agg.PHAM_NHAN_ID AND vc_agg.rn = 1

    WHERE ll.IS_DELETED = 0
      AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)
      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
      AND (p_dia_chi_thuong_tru IS NULL OR dvhc.ID = p_dia_chi_thuong_tru)
      AND (p_doi_tuong_id IS NULL OR p_doi_tuong_id = 0
           OR (p_doi_tuong_id = 2 
           AND TRIM(NVL(CAST(tdc.TD_CHUONG AS VARCHAR2(10)), '')) <> '13')
           OR (p_doi_tuong_id = 1
           AND (tdc.TD_CHUONG IS NULL
           OR TRIM(NVL(CAST(tdc.TD_CHUONG AS VARCHAR2(10)), '')) = '13')))
      AND (p_quoc_tich IS NULL OR p_quoc_tich = 0
           OR (p_quoc_tich = 250 AND TRIM(NVL(CAST(dqt.QT_MA AS VARCHAR2(20)), '')) = '250')
           OR (p_quoc_tich = 999 AND (dqt.QT_MA IS NULL OR TRIM(NVL(CAST(dqt.QT_MA AS VARCHAR2(20)), '')) <> '250')))
      AND (p_nghien_ma_tuy IS NULL OR p_nghien_ma_tuy = 0
           OR (p_nghien_ma_tuy = 1 AND pnm.NMT_PN_LAI_LICH_ID IS NOT NULL)
           OR (p_nghien_ma_tuy = 2 AND pnm.NMT_PN_LAI_LICH_ID IS NULL))
      AND (p_tim_kiem IS NULL OR TRIM(p_tim_kiem) = ''
           OR UPPER(ll.LL_HO_TEN) LIKE '%' || UPPER(TRIM(p_tim_kiem)) || '%'
           OR UPPER(NVL(ll.LL_CCCD, '')) LIKE '%' || UPPER(TRIM(p_tim_kiem)) || '%')
    ORDER BY ll.LL_HO_TEN;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 
            'L?i khi l?y danh sách ??ng ý th? có ?i?u ki?n (extended): ' || SQLERRM);
END SP_GET_DS_THA_CO_DK_EXCEL;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_THOI_HAN_CHUNG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_THOI_HAN_CHUNG" (
    p_pn_ids IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi_id IN NVARCHAR2 DEFAULT NULL,
    p_ky_xet IN NUMBER DEFAULT NULL,
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL
) AS
    p_cursor SYS_REFCURSOR;
BEGIN
    OPEN p_cursor FOR
        WITH ID_LIST AS (
                 SELECT DISTINCT TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
                 FROM DUAL
                 CONNECT BY LEVEL <= CASE
                                         WHEN p_pn_ids IS NULL THEN 0
                                         WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                                         ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                     END
                        AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
                        AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
             ),
             -- ############ L?C PH?M NHÂN S?M NH?T CÓ TH? ############
            PN_FILTERED AS (
                SELECT /*+ MATERIALIZE */
                    ll.ID,
                    ll.LL_SO_HO_SO_LAN_DAU,
                    ll.LL_HO_TEN,
                    ll.LL_NGAY_SINH,
                    ll.LL_DM_GIOI_TINH_ID,
                    ll.LL_DM_QUOC_TICH_ID,
                    ll.LL_DIA_CHI_THUONG_TRU,
                    ll.LL_DIA_CHI_THUONG_TRU_PROVICE,
                    ll.LL_DIA_CHI_THUONG_TRU_WARD,
                    ll.LL_SO_TIEN_AN,
                    ll.LL_TINH_TRANG_ID,
                    ll.LL_PHAN_DOI_ID,
                    ll.LL_GHI_CHU_RIENG,
                    ll.LL_GHI_CHU_CHI_TIET,
                    ll.LL_TRAI_GIAM_ID
                FROM PN_LAI_LICHS ll
                WHERE ll.IS_DELETED = 0
                AND (p_ma_trai_giam IS NULL OR ll.LL_TRAI_GIAM_ID = (SELECT dtg.ID FROM DM_TRAI_GIAMS dtg WHERE dtg.TG_MA = p_ma_trai_giam))
                AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
                AND (p_pn_ids IS NULL OR ll.ID IN (SELECT PN_ID FROM ID_LIST))
            ),
             td_split AS (
                 SELECT ptha.THA_PNLAI_LICH_ID,
                        REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', '') AS TOI_DANH_ID,
                        ptha.THA_MUC_AN_ID
                 FROM QLPN.PN_THI_HANH_AN ptha
                          LEFT JOIN DM_TOI_DANHS td ON td.ID = ptha.THA_TOI_DANH
                 WHERE ptha.IS_DELETED = 0
                   AND ptha.THA_PNLAI_LICH_ID IN (SELECT ID FROM PN_FILTERED)   -- l?c s?m
             ),
             NUM_GEN AS (SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL <= 20),
             SPLIT_TOI_DANH AS (
                 SELECT TF.THA_PNLAI_LICH_ID,
                        TO_NUMBER(TRIM(REGEXP_SUBSTR(TF.TOI_DANH_ID, '[^,]+', 1, NG.N))) AS TOI_DANH_ID
                 FROM td_split TF
                          JOIN NUM_GEN NG ON NG.N <= REGEXP_COUNT(TF.TOI_DANH_ID, ',') + 1
                 WHERE REGEXP_SUBSTR(TF.TOI_DANH_ID, '[^,]+', 1, NG.N) IS NOT NULL
             ),
             TD_AGG AS (
                 SELECT S.THA_PNLAI_LICH_ID,
                        LISTAGG(DISTINCT DTD.TD_CHUONG, ', ') WITHIN GROUP (ORDER BY DTD.TD_TEN) AS TOI_DANH_CHUONGS,
                        LISTAGG(DISTINCT DTD.TD_TEN, ', ') WITHIN GROUP (ORDER BY DTD.TD_TEN)     AS TOI_DANH_TENS
                 FROM SPLIT_TOI_DANH S
                          LEFT JOIN DM_TOI_DANHS DTD ON DTD.ID = S.TOI_DANH_ID
                 GROUP BY S.THA_PNLAI_LICH_ID
             ),
             GCR_SPLIT AS (
                 SELECT lls.ID,
                        REPLACE(REPLACE(lls.LL_GHI_CHU_RIENG, '[', ''), ']', '') AS ghi_chu_rieng_id
                 FROM PN_FILTERED lls          -- l?c s?m, không ??c l?i full PN_LAI_LICHS
             ),
             NUM_GEN_GCR AS (SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL <= 20),
             SPLIT_GCR AS (
                 SELECT GS.ID,
                        TO_NUMBER(TRIM(REGEXP_SUBSTR(GS.ghi_chu_rieng_id, '[^,]+', 1, NG.N))) AS ghi_chu_rieng_id
                 FROM GCR_SPLIT GS
                          JOIN NUM_GEN_GCR NG ON NG.N <= REGEXP_COUNT(GS.ghi_chu_rieng_id, ',') + 1
                 WHERE REGEXP_SUBSTR(GS.ghi_chu_rieng_id, '[^,]+', 1, NG.N) IS NOT NULL
             ),
             GCR_AGG AS (
                 SELECT S.ID,
                        LISTAGG(DISTINCT dm.GCR_TEN, ', ') WITHIN GROUP (ORDER BY dm.GCR_TEN) AS ghi_chu_riengs
                 FROM SPLIT_GCR S
                          LEFT JOIN QLPN.DM_GHI_CHU_RIENGS dm ON dm.ID = s.ghi_chu_rieng_id
                 GROUP BY S.ID
             ),
             -- ############ L?C GI?M TH?I H?N S?M THEO PN_FILTERED ############
             GTH_FILTERED AS (
                 SELECT gths1.PHAM_NHAN_ID,
                        gths1.MUC_DE_NGHI_ID,
                        gths1.MUC_GIAM_ID,
                        gths1.CAP_TREN_DUYET_ID,
                        gths1.NGAY_THA_GIAM_HET_AN,
                        gths1.NGAY_QUYET_DINH,
                        kgth.ID AS KGTH_ID
                 FROM GIAM_THOI_HANS gths1
                          LEFT JOIN GTH_KY_GIAM_THOI_HANS kgth
                                    ON TRUNC(kgth.KGTH_NGAY_XET_GIAM) = TRUNC(gths1.NGAY_XET)
                                   AND kgth.IS_DELETED = 0
                 WHERE gths1.IS_DELETED = 0
                   AND gths1.PHAM_NHAN_ID IN (SELECT ID FROM PN_FILTERED)   -- l?c s?m, g?n t?p join
             ),
             G AS (
                 SELECT PHAM_NHAN_ID, MUC_DE_NGHI_ID, MUC_GIAM_ID, CAP_TREN_DUYET_ID, NGAY_THA_GIAM_HET_AN,
                        ROW_NUMBER() OVER (PARTITION BY PHAM_NHAN_ID ORDER BY NGAY_QUYET_DINH DESC NULLS LAST) rn
                 FROM GTH_FILTERED
                 WHERE (KGTH_ID = p_ky_xet OR p_ky_xet IS NULL)
             )
        SELECT ROW_NUMBER() OVER (ORDER BY ll.ID)                       AS TT,
               ll.LL_SO_HO_SO_LAN_DAU                                   AS SO_HSLD,
               ll.LL_HO_TEN                                             AS HO_TEN,
               SUBSTR(ll.LL_NGAY_SINH, -4)                              AS NS,
               gt.GT_TEN                                                AS GT,
               NVL2(ll.LL_DIA_CHI_THUONG_TRU, ll.LL_DIA_CHI_THUONG_TRU || ', ' || xp.XP_TEN || ', ' ||
                                              ttp.TTP_TEN, xp.XP_TEN || ', ' ||
                                                           ttp.TTP_TEN) AS DKTT,
               qt.QT_TEN                                                AS QUOC_TICH,
               tdagg.TOI_DANH_TENS                                      AS TOI_DANH,
               TO_NCHAR(tha.THA_NGAY_BAT, 'dd/mm/yyyy')                 AS NGAY_BAT,
               tha.THA_AN_PHAT                                          AS AN_PHAT,
               NVL(ll.LL_SO_TIEN_AN, u'Kh\00f4ng')                      AS TIEN_AN,
               mdn_trai.MTG_TITLE                                       AS MUC_DE_NGHI_GIAM_TRAI,
               mdn_captren.MTG_TITLE                                    AS MUC_DE_NGHI_CAP_TREN,
               mg_toa.MTG_TITLE                                         AS MUC_GIAM_CUA_TOA,
               TO_NCHAR(tha.THA_NGAY_HET_HAN, 'dd/mm/yyyy')             AS NGAY_RA_TRAI,
               ttpnn.TTPN_TEN                                           AS TINH_TRANG,
               pd.PD_TEN || ', ' || pt.PT_TEN                            AS PHAN_DOI,
               tn_bo.HO_TEN_THAN_NHAN                                   AS HO_TEN_BO,
               tn_me.HO_TEN_THAN_NHAN                                   AS HO_TEN_ME,
               tn_vc.HO_TEN_THAN_NHAN                                   AS HO_TEN_VO_CHONG,
               ll.LL_GHI_CHU_CHI_TIET                                   AS GHI_CHU
        FROM PN_FILTERED ll                                            -- ?ã l?c s?n, không còn WHERE ? cu?i
                 LEFT JOIN PN_THI_HANH_AN tha ON tha.THA_PNLAI_LICH_ID = ll.ID AND tha.IS_DELETED = 0
                 LEFT JOIN TD_AGG tdagg ON tdagg.THA_PNLAI_LICH_ID = ll.ID
                 LEFT JOIN DM_GIOI_TINHS gt ON gt.ID = ll.LL_DM_GIOI_TINH_ID AND gt.IS_DELETED = 0
                 LEFT JOIN DM_QUOC_TICHS qt ON qt.ID = ll.LL_DM_QUOC_TICH_ID AND qt.IS_DELETED = 0
                 LEFT JOIN DM_TINH_THANH_PHO ttp ON ttp.ID = ll.LL_DIA_CHI_THUONG_TRU_PROVICE
                 LEFT JOIN DM_XA_PHUONG xp ON xp.ID = ll.LL_DIA_CHI_THUONG_TRU_WARD
                 INNER JOIN G g ON g.PHAM_NHAN_ID = ll.ID AND g.rn = 1
                 LEFT JOIN DM_MA_THOI_GIANS mdn_trai ON mdn_trai.ID = g.MUC_DE_NGHI_ID AND mdn_trai.IS_DELETED = 0
                 LEFT JOIN DM_MA_THOI_GIANS mdn_captren
                           ON mdn_captren.ID = g.CAP_TREN_DUYET_ID AND mdn_captren.IS_DELETED = 0
                 LEFT JOIN DM_MA_THOI_GIANS mg_toa ON mg_toa.ID = g.MUC_GIAM_ID AND mg_toa.IS_DELETED = 0
                 LEFT JOIN DM_TINH_TRANG_PHAM_NHANS ttpnn ON ttpnn.ID = ll.LL_TINH_TRANG_ID AND ttpnn.IS_DELETED = 0
                 LEFT JOIN DM_PHAN_DOIS pd ON pd.ID = ll.LL_PHAN_DOI_ID AND pd.IS_DELETED = 0
                 LEFT JOIN DM_PHAN_TRAIS pt ON pd.PD_DM_PHAN_TRAI_ID = pt.ID
                 LEFT JOIN (SELECT tn.PHAM_NHAN_ID, MAX(tn.HO_TEN_THAN_NHAN) AS HO_TEN_THAN_NHAN
                            FROM THAN_NHAN_NGUOI_THANS tn
                                     INNER JOIN DM_QUAN_HE_VOI_PHAM_NHANS qh
                                                ON qh.ID = tn.QUAN_HE_ID AND qh.IS_DELETED = 0
                            WHERE tn.IS_DELETED = 0
                              AND tn.PHAM_NHAN_ID IN (SELECT ID FROM PN_FILTERED)   -- l?c s?m
                              AND (UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%B?%' OR UPPER(TRIM(qh.QHVPN_MA)) IN ('BO', 'CHA'))
                            GROUP BY tn.PHAM_NHAN_ID) tn_bo ON tn_bo.PHAM_NHAN_ID = ll.ID
                 LEFT JOIN (SELECT tn.PHAM_NHAN_ID, MAX(tn.HO_TEN_THAN_NHAN) AS HO_TEN_THAN_NHAN
                            FROM THAN_NHAN_NGUOI_THANS tn
                                     INNER JOIN DM_QUAN_HE_VOI_PHAM_NHANS qh
                                                ON qh.ID = tn.QUAN_HE_ID AND qh.IS_DELETED = 0
                            WHERE tn.IS_DELETED = 0
                              AND tn.PHAM_NHAN_ID IN (SELECT ID FROM PN_FILTERED)   -- l?c s?m
                              AND (UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%M?%' OR UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%ME%' OR
                                   UPPER(TRIM(qh.QHVPN_MA)) = 'ME')
                            GROUP BY tn.PHAM_NHAN_ID) tn_me ON tn_me.PHAM_NHAN_ID = ll.ID
                 LEFT JOIN (SELECT tn.PHAM_NHAN_ID, MAX(tn.HO_TEN_THAN_NHAN) AS HO_TEN_THAN_NHAN
                            FROM THAN_NHAN_NGUOI_THANS tn
                                     INNER JOIN DM_QUAN_HE_VOI_PHAM_NHANS qh
                                                ON qh.ID = tn.QUAN_HE_ID AND qh.IS_DELETED = 0
                            WHERE tn.IS_DELETED = 0
                              AND tn.PHAM_NHAN_ID IN (SELECT ID FROM PN_FILTERED)   -- l?c s?m
                              AND (UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%V?%' OR UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%CH?NG%' OR
                                   UPPER(TRIM(qh.QHVPN_MA)) IN ('VC', 'VO', 'CHONG'))
                            GROUP BY tn.PHAM_NHAN_ID) tn_vc ON tn_vc.PHAM_NHAN_ID = ll.ID
                 LEFT JOIN GCR_AGG gcr ON gcr.ID = ll.ID;
    DBMS_SQL.RETURN_RESULT(p_cursor);
END SP_GET_DS_THOI_HAN_CHUNG;



