             ),
             -- ############ L?C PH?M NHÂN S?M NH?T CÓ TH? ############
            PN_FILTERED AS (
                SELECT /*+ MATERIALIZE */
                    ll.ID,
                    ll.LL_SO_HO_SO_LAN_DAU,
                    ll.LL_HO_TEN,
                    ll.LL_NGAY_SINH,
                    ll.LL_DM_GIOI_TINH_ID,
                    ll.LL_DM_QUOC_TICH_ID,
                    ll.LL_DIA_CHI_THUONG_TRU,
                    ll.LL_DIA_CHI_THUONG_TRU_PROVICE,
                    ll.LL_DIA_CHI_THUONG_TRU_WARD,
                    ll.LL_SO_TIEN_AN,
                    ll.LL_TINH_TRANG_ID,
                    ll.LL_PHAN_DOI_ID,
                    ll.LL_GHI_CHU_RIENG,
                    ll.LL_GHI_CHU_CHI_TIET,
                    ll.LL_TRAI_GIAM_ID
                FROM PN_LAI_LICHS ll
                WHERE ll.IS_DELETED = 0
                AND (p_ma_trai_giam IS NULL OR ll.LL_TRAI_GIAM_ID = (SELECT dtg.ID FROM DM_TRAI_GIAMS dtg WHERE dtg.TG_MA = p_ma_trai_giam))
                AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
                AND (p_pn_ids IS NULL OR ll.ID IN (SELECT PN_ID FROM ID_LIST))
            ),
             td_split AS (
                 SELECT ptha.THA_PNLAI_LICH_ID,
                        REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', '') AS TOI_DANH_ID,
                        ptha.THA_MUC_AN_ID
                 FROM QLPN.PN_THI_HANH_AN ptha
                          LEFT JOIN DM_TOI_DANHS td ON td.ID = ptha.THA_TOI_DANH
                 WHERE ptha.IS_DELETED = 0
                   AND ptha.THA_PNLAI_LICH_ID IN (SELECT ID FROM PN_FILTERED)   -- l?c s?m
             ),
             NUM_GEN AS (SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL <= 20),
             SPLIT_TOI_DANH AS (
                 SELECT TF.THA_PNLAI_LICH_ID,
                        TO_NUMBER(TRIM(REGEXP_SUBSTR(TF.TOI_DANH_ID, '[^,]+', 1, NG.N))) AS TOI_DANH_ID
                 FROM td_split TF
                          JOIN NUM_GEN NG ON NG.N <= REGEXP_COUNT(TF.TOI_DANH_ID, ',') + 1
                 WHERE REGEXP_SUBSTR(TF.TOI_DANH_ID, '[^,]+', 1, NG.N) IS NOT NULL
             ),
             TD_AGG AS (
                 SELECT S.THA_PNLAI_LICH_ID,
                        LISTAGG(DISTINCT DTD.TD_CHUONG, ', ') WITHIN GROUP (ORDER BY DTD.TD_TEN) AS TOI_DANH_CHUONGS,
                        LISTAGG(DISTINCT DTD.TD_TEN, ', ') WITHIN GROUP (ORDER BY DTD.TD_TEN)     AS TOI_DANH_TENS
                 FROM SPLIT_TOI_DANH S
                          LEFT JOIN DM_TOI_DANHS DTD ON DTD.ID = S.TOI_DANH_ID
                 GROUP BY S.THA_PNLAI_LICH_ID
             ),
             GCR_SPLIT AS (
                 SELECT lls.ID,
                        REPLACE(REPLACE(lls.LL_GHI_CHU_RIENG, '[', ''), ']', '') AS ghi_chu_rieng_id
                 FROM PN_FILTERED lls          -- l?c s?m, không ??c l?i full PN_LAI_LICHS
             ),
             NUM_GEN_GCR AS (SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL <= 20),
             SPLIT_GCR AS (
                 SELECT GS.ID,
                        TO_NUMBER(TRIM(REGEXP_SUBSTR(GS.ghi_chu_rieng_id, '[^,]+', 1, NG.N))) AS ghi_chu_rieng_id
                 FROM GCR_SPLIT GS
                          JOIN NUM_GEN_GCR NG ON NG.N <= REGEXP_COUNT(GS.ghi_chu_rieng_id, ',') + 1
                 WHERE REGEXP_SUBSTR(GS.ghi_chu_rieng_id, '[^,]+', 1, NG.N) IS NOT NULL
             ),
             GCR_AGG AS (
                 SELECT S.ID,
                        LISTAGG(DISTINCT dm.GCR_TEN, ', ') WITHIN GROUP (ORDER BY dm.GCR_TEN) AS ghi_chu_riengs
                 FROM SPLIT_GCR S
                          LEFT JOIN QLPN.DM_GHI_CHU_RIENGS dm ON dm.ID = s.ghi_chu_rieng_id
                 GROUP BY S.ID
             ),
             -- ############ L?C GI?M TH?I H?N S?M THEO PN_FILTERED ############
             GTH_FILTERED AS (
                 SELECT gths1.PHAM_NHAN_ID,
                        gths1.MUC_DE_NGHI_ID,
                        gths1.MUC_GIAM_ID,
                        gths1.CAP_TREN_DUYET_ID,
                        gths1.NGAY_THA_GIAM_HET_AN,
                        gths1.NGAY_QUYET_DINH,
                        kgth.ID AS KGTH_ID
                 FROM GIAM_THOI_HANS gths1
                          LEFT JOIN GTH_KY_GIAM_THOI_HANS kgth
                                    ON TRUNC(kgth.KGTH_NGAY_XET_GIAM) = TRUNC(gths1.NGAY_XET)
                                   AND kgth.IS_DELETED = 0
                 WHERE gths1.IS_DELETED = 0
                   AND gths1.PHAM_NHAN_ID IN (SELECT ID FROM PN_FILTERED)   -- l?c s?m, g?n t?p join
             ),
             G AS (
                 SELECT PHAM_NHAN_ID, MUC_DE_NGHI_ID, MUC_GIAM_ID, CAP_TREN_DUYET_ID, NGAY_THA_GIAM_HET_AN,
                        ROW_NUMBER() OVER (PARTITION BY PHAM_NHAN_ID ORDER BY NGAY_QUYET_DINH DESC NULLS LAST) rn
                 FROM GTH_FILTERED
                 WHERE (KGTH_ID = p_ky_xet OR p_ky_xet IS NULL)
             )
        SELECT ROW_NUMBER() OVER (ORDER BY ll.ID)                       AS TT,
               ll.LL_SO_HO_SO_LAN_DAU                                   AS SO_HSLD,
               ll.LL_HO_TEN                                             AS HO_TEN,
               SUBSTR(ll.LL_NGAY_SINH, -4)                              AS NS,
               gt.GT_TEN                                                AS GT,
               NVL2(ll.LL_DIA_CHI_THUONG_TRU, ll.LL_DIA_CHI_THUONG_TRU || ', ' || xp.XP_TEN || ', ' ||
                                              ttp.TTP_TEN, xp.XP_TEN || ', ' ||
                                                           ttp.TTP_TEN) AS DKTT,
               qt.QT_TEN                                                AS QUOC_TICH,
               tdagg.TOI_DANH_TENS                                      AS TOI_DANH,
               TO_NCHAR(tha.THA_NGAY_BAT, 'dd/mm/yyyy')                 AS NGAY_BAT,
               tha.THA_AN_PHAT                                          AS AN_PHAT,
               NVL(ll.LL_SO_TIEN_AN, u'Kh\00f4ng')                      AS TIEN_AN,
               mdn_trai.MTG_TITLE                                       AS MUC_DE_NGHI_GIAM_TRAI,
               mdn_captren.MTG_TITLE                                    AS MUC_DE_NGHI_CAP_TREN,
               mg_toa.MTG_TITLE                                         AS MUC_GIAM_CUA_TOA,
               TO_NCHAR(tha.THA_NGAY_HET_HAN, 'dd/mm/yyyy')             AS NGAY_RA_TRAI,
               ttpnn.TTPN_TEN                                           AS TINH_TRANG,
               pd.PD_TEN || ', ' || pt.PT_TEN                            AS PHAN_DOI,
               tn_bo.HO_TEN_THAN_NHAN                                   AS HO_TEN_BO,
               tn_me.HO_TEN_THAN_NHAN                                   AS HO_TEN_ME,
               tn_vc.HO_TEN_THAN_NHAN                                   AS HO_TEN_VO_CHONG,
               ll.LL_GHI_CHU_CHI_TIET                                   AS GHI_CHU
        FROM PN_FILTERED ll                                            -- ?ã l?c s?n, không còn WHERE ? cu?i
                 LEFT JOIN PN_THI_HANH_AN tha ON tha.THA_PNLAI_LICH_ID = ll.ID AND tha.IS_DELETED = 0
                 LEFT JOIN TD_AGG tdagg ON tdagg.THA_PNLAI_LICH_ID = ll.ID
                 LEFT JOIN DM_GIOI_TINHS gt ON gt.ID = ll.LL_DM_GIOI_TINH_ID AND gt.IS_DELETED = 0
                 LEFT JOIN DM_QUOC_TICHS qt ON qt.ID = ll.LL_DM_QUOC_TICH_ID AND qt.IS_DELETED = 0
                 LEFT JOIN DM_TINH_THANH_PHO ttp ON ttp.ID = ll.LL_DIA_CHI_THUONG_TRU_PROVICE
                 LEFT JOIN DM_XA_PHUONG xp ON xp.ID = ll.LL_DIA_CHI_THUONG_TRU_WARD
                 INNER JOIN G g ON g.PHAM_NHAN_ID = ll.ID AND g.rn = 1
                 LEFT JOIN DM_MA_THOI_GIANS mdn_trai ON mdn_trai.ID = g.MUC_DE_NGHI_ID AND mdn_trai.IS_DELETED = 0
                 LEFT JOIN DM_MA_THOI_GIANS mdn_captren
                           ON mdn_captren.ID = g.CAP_TREN_DUYET_ID AND mdn_captren.IS_DELETED = 0
                 LEFT JOIN DM_MA_THOI_GIANS mg_toa ON mg_toa.ID = g.MUC_GIAM_ID AND mg_toa.IS_DELETED = 0
                 LEFT JOIN DM_TINH_TRANG_PHAM_NHANS ttpnn ON ttpnn.ID = ll.LL_TINH_TRANG_ID AND ttpnn.IS_DELETED = 0
                 LEFT JOIN DM_PHAN_DOIS pd ON pd.ID = ll.LL_PHAN_DOI_ID AND pd.IS_DELETED = 0
                 LEFT JOIN DM_PHAN_TRAIS pt ON pd.PD_DM_PHAN_TRAI_ID = pt.ID
                 LEFT JOIN (SELECT tn.PHAM_NHAN_ID, MAX(tn.HO_TEN_THAN_NHAN) AS HO_TEN_THAN_NHAN
                            FROM THAN_NHAN_NGUOI_THANS tn
                                     INNER JOIN DM_QUAN_HE_VOI_PHAM_NHANS qh
                                                ON qh.ID = tn.QUAN_HE_ID AND qh.IS_DELETED = 0
                            WHERE tn.IS_DELETED = 0
                              AND tn.PHAM_NHAN_ID IN (SELECT ID FROM PN_FILTERED)   -- l?c s?m
                              AND (UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%B?%' OR UPPER(TRIM(qh.QHVPN_MA)) IN ('BO', 'CHA'))
                            GROUP BY tn.PHAM_NHAN_ID) tn_bo ON tn_bo.PHAM_NHAN_ID = ll.ID
                 LEFT JOIN (SELECT tn.PHAM_NHAN_ID, MAX(tn.HO_TEN_THAN_NHAN) AS HO_TEN_THAN_NHAN
                            FROM THAN_NHAN_NGUOI_THANS tn
                                     INNER JOIN DM_QUAN_HE_VOI_PHAM_NHANS qh
                                                ON qh.ID = tn.QUAN_HE_ID AND qh.IS_DELETED = 0
                            WHERE tn.IS_DELETED = 0
                              AND tn.PHAM_NHAN_ID IN (SELECT ID FROM PN_FILTERED)   -- l?c s?m
                              AND (UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%M?%' OR UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%ME%' OR
                                   UPPER(TRIM(qh.QHVPN_MA)) = 'ME')
                            GROUP BY tn.PHAM_NHAN_ID) tn_me ON tn_me.PHAM_NHAN_ID = ll.ID
                 LEFT JOIN (SELECT tn.PHAM_NHAN_ID, MAX(tn.HO_TEN_THAN_NHAN) AS HO_TEN_THAN_NHAN
                            FROM THAN_NHAN_NGUOI_THANS tn
                                     INNER JOIN DM_QUAN_HE_VOI_PHAM_NHANS qh
                                                ON qh.ID = tn.QUAN_HE_ID AND qh.IS_DELETED = 0
                            WHERE tn.IS_DELETED = 0
                              AND tn.PHAM_NHAN_ID IN (SELECT ID FROM PN_FILTERED)   -- l?c s?m
                              AND (UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%V?%' OR UPPER(TRIM(qh.QHVPN_TEN)) LIKE '%CH?NG%' OR
                                   UPPER(TRIM(qh.QHVPN_MA)) IN ('VC', 'VO', 'CHONG'))
                            GROUP BY tn.PHAM_NHAN_ID) tn_vc ON tn_vc.PHAM_NHAN_ID = ll.ID
                 LEFT JOIN GCR_AGG gcr ON gcr.ID = ll.ID;
    DBMS_SQL.RETURN_RESULT(p_cursor);
END SP_GET_DS_THOI_HAN_CHUNG_PHI_TEST;



