--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_TIM_KIEM
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_TIM_KIEM" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
	p_ghi_chu_rieng_id  	  IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH
             selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ), 
             pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID                      AS pham_nhan_id,
            ll.LL_SO_HO_SO_LAN_DAU,
            ll.LL_DM_GIOI_TINH_ID                AS GIOI_TINH_ID
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON  dtg.ID = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED         = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                AND dqt.IS_DELETED = 0
        WHERE
            ll.IS_DELETED = 0
            AND (p_ma_trai_giam IS NULL OR v_ll_trai_giam_id IS NOT NULL)

            AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                      AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                      AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                      AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)		
			AND (
				    (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM PN_DAC_XAS dxa
				        WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
				          AND dxa.IS_DELETED = 0
				          AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
				          AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
				    )
				)
			AND (
				    (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM GIAM_THOI_HANS gaan
				        WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
				          AND gaan.IS_DELETED   = 0
				          AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
				          AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
				    )
				)
                AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
            AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
            AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
            AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))

            AND (p_tg_chap_hanh_tu  IS NULL OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
			AND (p_tg_chap_hanh_den IS NULL OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
            AND (p_tg_con_lai_tu  IS NULL OR
                    ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
            AND (p_tg_con_lai_den IS NULL OR
                    ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

            -- NHÃ“M 3: Danh má»¥c
            AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
            AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
            AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
            AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
            AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
            AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

            -- [Tá»™i danh]
	AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
            AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
            AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG             = p_loai_doi_tuong_id)

            -- [Ghi chÃº riÃªng]
            AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

            AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

            -- NHÃ“M 4: Checkbox
            AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
            AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
            AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
            ))
            AND (
									    p_dan_toc_thieu_so IS NULL
									    OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_DAN_TOCS dt
									                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
									                  AND dt.IS_DELETED = 0
									                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
									            )
									            THEN 1
									            ELSE 0
									        END = p_dan_toc_thieu_so
									    )
									)

            AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
			    CASE
			        WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
			        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
			        WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
			        ELSE 0
			    END = p_vtn_thoi_diem_pham_toi
			))
            AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
            ))
            AND (p_theo_ton_giao IS NULL OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_TON_GIAOS tg
									                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
									                  AND tg.IS_DELETED = 0
									            )
									            THEN 1
									            ELSE 0
									        END = p_theo_ton_giao ))
            AND (p_vtn_hien_tai IS NULL OR (
			    CASE
			        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
			        WHEN FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
			        ELSE 0
			    END = p_vtn_hien_tai
			))			
            AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
            ))
            AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
            AND (p_chung_than IS NULL OR (
    CASE
        WHEN ll.THA_MA_AN_PHAT IN (
            SELECT dmtg.ID
            FROM DM_MA_THOI_GIANS dmtg
            WHERE dmtg.MTG_MA IN ('911000', '912000')
              AND dmtg.IS_DELETED = 0
        ) THEN 1
        ELSE 0
    END = p_chung_than
))
            AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
            ))
            AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
            ))
            AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))
            AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
            ))
            AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
			AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
            AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
            ))
            AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
            AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
            AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
            AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))
    ) 
	      	SELECT
            	pnf.PHAM_NHAN_ID,
            	pnf.LL_SO_HO_SO_LAN_DAU,
            	rt.LL_HO_TEN AS HO_TEN,
            	rt.NAM_SINH,
            	rt.LL_NGAY_SINH AS NGAY_SINH,
            	dgt.GT_TEN AS GIOI_TINH,
            	rt.LL_DIA_CHI_THUONG_TRU AS NOI_THUONG_TRU_DAY_DU,
            	rt.THA_TOI_DANH_NAMES AS TOI_DANH,
            	NVL(rt.LL_SO_TIEN_AN, u'0') AS SO_TIEN_AN,
            	TO_CHAR(TRUNC(rt.THA_NGAY_BAT), 'DD/MM/YYYY') AS NGAY_BAT,
            	rt.THA_AN_PHAT AS AN_PHAT,
            	TO_CHAR(TRUNC(rt.THA_NGAY_DEN_TRAI), 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
            	NVL(dmtg_cl.MTG_TITLE,  u'Kh\00f4ng') AS THOI_GIAN_CON_LAI,
            	NVL(dmtg_dch.MTG_TITLE, u'Kh\00f4ng') AS THOI_GIAN_DA_CHAP_HANH,
            	CASE
                    WHEN NVL(rt.SO_LAN_GIAM, 0) = 0 THEN u'Kh\00f4ng'
                    ELSE TO_CHAR(rt.SO_LAN_GIAM) || u' l\1ea7n = ' || rt.THOI_GIAN_DA_GIAM
                END AS DA_GIAM,
            	QLPN.FN_GET_LIET_KE_HPBS_CHI_TIET (rt.PHAM_NHAN_ID) AS HPBS,
            	TO_CHAR(TRUNC(rt.THA_NGAY_HET_HAN), 'DD/MM/YYYY') AS NGAY_HET_HAN,
            	gcr_agg.GHI_CHU_RIENG  AS GHI_CHU,
            	NVL(pd.PD_TEN, u'') || CASE WHEN pt.PT_TEN IS NOT NULL THEN u', ' || pt.PT_TEN ELSE u'' END AS PHAN_DOI
	        FROM pham_nhan_filtered pnf
	        INNER JOIN pn_base rt ON rt.PHAM_NHAN_ID = pnf.PHAM_NHAN_ID
	        LEFT JOIN DM_GIOI_TINHS dgt ON rt.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
	        LEFT JOIN DM_PHAN_DOIS pd ON rt.LL_PHAN_DOI_ID = pd.ID AND pd.IS_DELETED = 0
	        LEFT JOIN DM_PHAN_TRAIS pt ON rt.LL_PHAN_TRAI_ID = pt.ID AND pt.IS_DELETED = 0
	        LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg_cl  ON dmtg_cl.MTG_MA  = rt.THA_THOI_GIAN_CON_LAI      AND dmtg_cl.IS_DELETED  = 0
	        LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg_dch ON dmtg_dch.MTG_MA = rt.THA_THOI_GIAN_DA_CHAP_HANH AND dmtg_dch.IS_DELETED = 0
		    LEFT JOIN (
		        SELECT
		            pll2.PHAM_NHAN_ID AS PHAM_NHAN_ID,
		            RTRIM(XMLAGG(XMLELEMENT(e, dgcr.GCR_TEN || ', ')
		                ORDER BY dgcr.GCR_TEN).extract('//text()').GETCLOBVAL(), ', ') AS GHI_CHU_RIENG
		        FROM pham_nhan_filtered pnf2
		        INNER JOIN pn_base pll2 ON pll2.PHAM_NHAN_ID = pnf2.pham_nhan_id
		        LEFT JOIN LATERAL (
		            SELECT TRIM(REGEXP_SUBSTR(pll2.LL_GHI_CHU_RIENG, '[^,]+', 1, LEVEL)) AS GHI_CHU_RIENG_MA
		            FROM DUAL
		            WHERE pll2.LL_GHI_CHU_RIENG IS NOT NULL
		            CONNECT BY LEVEL <= REGEXP_COUNT(pll2.LL_GHI_CHU_RIENG, ',') + 1
		        ) gcr ON 1 = 1
		        LEFT JOIN DM_GHI_CHU_RIENGS dgcr
		            ON gcr.GHI_CHU_RIENG_MA = TRIM(dgcr.ID)
		        GROUP BY pll2.PHAM_NHAN_ID, pll2.LL_GHI_CHU_RIENG
		    ) gcr_agg ON gcr_agg.PHAM_NHAN_ID = pnf.PHAM_NHAN_ID
            ORDER BY rt.HO_TEN_ORDER ;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_DS_TIM_KIEM;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_XEP_LOAI_CAI_TAO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_XEP_LOAI_CAI_TAO" (
    p_pn_ids IN VARCHAR2 DEFAULT NULL
) AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
        WITH id_list AS (
                -- FIX: B? DISTINCT, thêm LEVEL AS stt ?? gi? th? t? truy?n vào
                SELECT
                    TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS pn_id,
                    LEVEL AS stt
                FROM dual
                CONNECT BY LEVEL <= CASE
                                        WHEN LENGTH(TRIM(NVL(p_pn_ids, ''))) = 0 THEN 0
                                        ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                                    END
                AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
                AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
            ),
            vw_one AS (
                SELECT v.*,
                       i.stt,  -- FIX: kéo stt vào ?? dùng cho ORDER BY cu?i
                       ROW_NUMBER() OVER (
                           PARTITION BY v.PHAM_NHAN_ID
                           ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
                                    v.CREATION_TIME DESC NULLS LAST
                       ) AS rn
                FROM VW_PN_LAI_LICH_CHI_TIET v
                INNER JOIN id_list i ON v.PHAM_NHAN_ID = i.pn_id
                WHERE NVL(v.IS_DELETED, 0) = 0
            ),
            base AS (
                SELECT v.PHAM_NHAN_ID,
                       v.stt,  -- FIX: gi? l?i stt trong base
                       v.HO_TEN,
                       v.NAM_SINH,
                       v.GIOI_TINH,
                       v.NOI_THUONG_TRU_DAY_DU,
                       v.TOI_DANH,
                       v.SO_TIEN_AN,
                       v.NGAY_BAT_AN_PHAT,
                       v.AN_PHAT,
                       v.NGAY_DEN_TRAI,
                       v.NGAY_HET_AN,
                       v.PHAN_DOI,
                       v.PHAN_TRAI,
                       v.GHI_CHU
                FROM vw_one v
                WHERE v.rn = 1
            ),
            pn_ids AS (
                SELECT DISTINCT b.PHAM_NHAN_ID AS pn_id
                FROM base b
            )
        SELECT NVL(CAST(b.HO_TEN AS NVARCHAR2(500)), u'')                  AS HO_TEN,
               b.NAM_SINH                                                   AS NAM_SINH,
               NVL(CAST(b.GIOI_TINH AS NVARCHAR2(100)), u'')               AS GIOI_TINH,
               NVL(CAST(b.NOI_THUONG_TRU_DAY_DU AS NVARCHAR2(2000)), u'')  AS NOI_THUONG_TRU_DAY_DU,
               NVL(CAST(b.TOI_DANH AS NVARCHAR2(2000)), u'')               AS TOI_DANH,
               b.SO_TIEN_AN                                                 AS SO_TIEN_AN,
               TO_NCHAR(b.NGAY_BAT_AN_PHAT, 'dd/mm/yyyy')                  AS NGAY_BAT_AN_PHAT,
               NVL(CAST(b.AN_PHAT AS NVARCHAR2(2000)), u'')                AS AN_PHAT,
               NVL(QLPN.PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(b.PHAM_NHAN_ID), u'Không') AS DA_GIAM,
               NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(b.PHAM_NHAN_ID, TRUNC(SYSDATE)), u'') AS DA_CHAP_HANH,
               NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(b.PHAM_NHAN_ID, TRUNC(SYSDATE)), u'') AS CON_LAI,
               NVL(QLPN.FN_GET_LIET_KE_HPBS(b.PHAM_NHAN_ID), u'')   AS HPBS,
               TO_NCHAR(b.NGAY_DEN_TRAI, 'dd/mm/yyyy')                     AS NGAY_DEN_TRAI,
               TO_NCHAR(b.NGAY_HET_AN, 'dd/mm/yyyy')                       AS NGAY_HET_AN,
               NVL(CAST(b.GHI_CHU AS NVARCHAR2(2000)), u'')                AS GHI_CHU,
               NVL(CAST(b.PHAN_DOI AS NVARCHAR2(500)), u'')                AS PHAN_DOI,
               NVL(CAST(b.PHAN_TRAI AS NVARCHAR2(500)), u'')               AS PHAN_TRAI,
               b.PHAM_NHAN_ID,
               xl_all.XEP_LOAI_TAT_CA_NAM                                  AS XEP_LOAI_CAI_TAO,
               COUNT(*) OVER ()                                             AS TONG_SO_PHAM_NHAN
        FROM base b
		LEFT JOIN (
		            SELECT xl.PHAM_NHAN_ID,
		                   SUBSTR(
		                       RTRIM(
		                           XMLAGG(
										XMLELEMENT(
										    e,
										    TO_NCHAR(xl.XEP_LOAI_NAM) || TO_NCHAR(': ') ||
										    RTRIM(
										        CASE WHEN xl_q1.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q1: ') || xl_q1.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END ||
										        CASE WHEN xl_q2.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q2: ') || xl_q2.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END ||
										        CASE WHEN xl_q3.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q3: ') || xl_q3.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END ||
										        CASE WHEN xl_q4.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q4: ') || xl_q4.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END,
										        '; '
										    )
										)
		                               ORDER BY xl.XEP_LOAI_NAM
		                           ).extract('//text()').GETSTRINGVAL(),
		                           CHR(10)
		                       ), 1, 4000
		                   ) AS XEP_LOAI_TAT_CA_NAM
		            FROM XEP_LOAIS xl
		            LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q1 ON xl.XEP_LOAI_QUY_I   = xl_q1.ID
		            LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q2 ON xl.XEP_LOAI_QUY_II  = xl_q2.ID
		            LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q3 ON xl.XEP_LOAI_QUY_III = xl_q3.ID
		            LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q4 ON xl.XEP_LOAI_QUY_IV  = xl_q4.ID
		            WHERE xl.XEP_LOAI_NAM = EXTRACT(YEAR FROM SYSDATE)  -- ? CH? N?M HI?N T?I
		            GROUP BY xl.PHAM_NHAN_ID
		        ) xl_all ON b.PHAM_NHAN_ID = xl_all.PHAM_NHAN_ID
        -- FIX: ??i ORDER BY theo stt ?? gi? ?úng th? t? danh sách ID truy?n vào
        -- Ví d? truy?n '1,3,15,2,11' ? xu?t ra ?úng th? t? 1, 3, 15, 2, 11
        ORDER BY b.stt;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_DS_XEP_LOAI_CAI_TAO;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_XEP_LOAI_TRONG_KY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_XEP_LOAI_TRONG_KY" (
    P_PHAN_DOI_ID            IN  NUMBER        DEFAULT NULL,
    P_LOAI_XEP_LOAI_ID       IN  NUMBER        DEFAULT NULL,
    P_HPBS_TIEN_ID           IN  NUMBER        DEFAULT NULL,
    P_HO_TEN_FILTER          IN  NVARCHAR2     DEFAULT NULL,
    P_MKXL_KY_XEP_LOAI       IN  NVARCHAR2     DEFAULT NULL,
    P_MKXL_NAM_XEP_LOAI      IN  NUMBER        DEFAULT NULL,
    P_KY_XEP_LOAI_CAI_TAO_ID IN  NUMBER        DEFAULT NULL,
    P_SKIP_COUNT             IN  NUMBER        DEFAULT 0,
    P_MAX_RESULT_COUNT       IN  NUMBER        DEFAULT NULL,
    P_SORTING                IN  NVARCHAR2     DEFAULT NULL,
    P_TOTAL_COUNT            OUT NUMBER,
    P_MO_KY_NOT_FOUND        OUT NUMBER,
    P_CURSOR                 OUT SYS_REFCURSOR
) AS
    V_NAM_XL                 NUMBER;
    V_NGAY_DEN_TRAI_TU       DATE;
    V_KY_XLCT_MA             NVARCHAR2(100);
    V_HAS_KY_FILTER          NUMBER(1) := 0;
    V_HAS_LOAI_FILTER        NUMBER(1) := 0;
    V_SORT_ASC               NUMBER(1) := 1;
    V_SORT_NGAYSINH          NUMBER(1) := 0;
    V_SORT_DIACHI            NUMBER(1) := 0;
    V_SORT_TOIDANH           NUMBER(1) := 0;
    V_SORT_ANPHAT            NUMBER(1) := 0;
    V_SORT_HOTEN             NUMBER(1) := 0;
    V_SORT_GIOITINH          NUMBER(1) := 0;
    V_SORT_PHANDOI           NUMBER(1) := 0;
    V_SORT_DEFAULT           NUMBER(1) := 0;
    V_SORTING_LOWER          NVARCHAR2(200);
BEGIN
    P_MO_KY_NOT_FOUND := 0;
    P_TOTAL_COUNT := 0;

    -- Resolve k? (gi? logic C#):
    -- MKXL c? ??nh ? lookup theo MKXL; không có MKXL ? k? ?ang m?; v?n null ? m?i nh?t theo TU_NGAY
    IF P_MKXL_KY_XEP_LOAI IS NOT NULL AND P_MKXL_NAM_XEP_LOAI IS NOT NULL THEN
        BEGIN
            SELECT NAM_XEP_LOAI, NGAY_DEN_TRAI_TU
              INTO V_NAM_XL, V_NGAY_DEN_TRAI_TU
              FROM QLPN.MO_KY_XEP_LOAI_CAI_TAOS
             WHERE NVL(IS_DELETED, 0) = 0
               AND KY_XEP_LOAI = P_MKXL_KY_XEP_LOAI
               AND NAM_XEP_LOAI = P_MKXL_NAM_XEP_LOAI
               AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
        END;
    ELSE
        BEGIN
            SELECT NAM_XEP_LOAI, NGAY_DEN_TRAI_TU
              INTO V_NAM_XL, V_NGAY_DEN_TRAI_TU
              FROM (
                    SELECT NAM_XEP_LOAI, NGAY_DEN_TRAI_TU
                      FROM QLPN.MO_KY_XEP_LOAI_CAI_TAOS
                     WHERE NVL(IS_DELETED, 0) = 0 AND TRANG_THAI = 1
                     ORDER BY ID DESC
                   )
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
        END;
    END IF;

    IF V_NAM_XL IS NULL THEN
        BEGIN
            SELECT NAM_XEP_LOAI, NGAY_DEN_TRAI_TU
              INTO V_NAM_XL, V_NGAY_DEN_TRAI_TU
              FROM (
                    SELECT NAM_XEP_LOAI, NGAY_DEN_TRAI_TU
                      FROM QLPN.MO_KY_XEP_LOAI_CAI_TAOS
                     WHERE NVL(IS_DELETED, 0) = 0
                     ORDER BY TU_NGAY DESC
                   )
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                P_MO_KY_NOT_FOUND := 1;
                OPEN P_CURSOR FOR
                    SELECT CAST(NULL AS NUMBER) AS PHAM_NHAN_ID FROM DUAL WHERE 1 = 0;
                RETURN;
        END;
    END IF;

    IF P_KY_XEP_LOAI_CAI_TAO_ID IS NOT NULL AND P_KY_XEP_LOAI_CAI_TAO_ID <> 0 THEN
        V_HAS_KY_FILTER := 1;
        BEGIN
            SELECT KXLCT_MA INTO V_KY_XLCT_MA
              FROM QLPN.DM_KY_XEP_LOAI_CAI_TAOS
             WHERE ID = P_KY_XEP_LOAI_CAI_TAO_ID AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN V_KY_XLCT_MA := NULL;
        END;
    END IF;

    V_HAS_LOAI_FILTER := CASE WHEN P_LOAI_XEP_LOAI_ID IS NOT NULL AND P_LOAI_XEP_LOAI_ID > 0 THEN 1 ELSE 0 END;

    V_SORTING_LOWER := LOWER(NVL(P_SORTING, u''));
    IF V_SORTING_LOWER LIKE u'%desc%' THEN V_SORT_ASC := 0; END IF;

    IF V_SORTING_LOWER LIKE u'%ngaysinh%'       THEN V_SORT_NGAYSINH  := 1;
    ELSIF V_SORTING_LOWER LIKE u'%diachithuongtru%' THEN V_SORT_DIACHI := 1;
    ELSIF V_SORTING_LOWER LIKE u'%toidanh%'     THEN V_SORT_TOIDANH  := 1;
    ELSIF V_SORTING_LOWER LIKE u'%anphat%'      THEN V_SORT_ANPHAT   := 1;
    ELSIF V_SORTING_LOWER LIKE u'%hoten%'       THEN V_SORT_HOTEN    := 1;
    ELSIF V_SORTING_LOWER LIKE u'%gioitinh%'    THEN V_SORT_GIOITINH := 1;
    ELSIF V_SORTING_LOWER LIKE u'%phandoi%'     THEN V_SORT_PHANDOI  := 1;
    ELSIF LENGTH(TRIM(V_SORTING_LOWER)) > 0    THEN V_SORT_DEFAULT  := 1;
    END IF;

    OPEN P_CURSOR FOR
        WITH
        dang_o_trai AS (
            SELECT ID FROM QLPN.DM_TINH_TRANG_PHAM_NHANS
             WHERE TTPN_MA IN ('111', '112', '113', '114')
        ),
        tha_max_id AS (
            SELECT THA_PNLAI_LICH_ID AS PN_ID, MAX(ID) AS MAX_ID
              FROM QLPN.PN_THI_HANH_AN
             WHERE NVL(IS_DELETED, 0) = 0 AND THA_PNLAI_LICH_ID IS NOT NULL
             GROUP BY THA_PNLAI_LICH_ID
        ),
        tha_latest AS (
            SELECT t.THA_PNLAI_LICH_ID AS PN_ID,
                   t.THA_TOI_DANH,
                   t.THA_AN_PHAT,
                   t.THA_MA_AN_PHAT,
                   t.THA_NGAY_DEN_TRAI,
                   t.THA_NGAY_HET_HAN
              FROM QLPN.PN_THI_HANH_AN t
              JOIN tha_max_id mi ON mi.MAX_ID = t.ID
        ),
        xl_year AS (
            SELECT x.PHAM_NHAN_ID AS PN_ID, MAX(x.ID) AS MAX_ID
              FROM QLPN.XEP_LOAIS x
             WHERE NVL(x.IS_DELETED, 0) = 0
               AND x.XEP_LOAI_NAM = V_NAM_XL
             GROUP BY x.PHAM_NHAN_ID
        ),
        xl_latest AS (
            SELECT x.PHAM_NHAN_ID AS PN_ID,
                   x.XEP_LOAI_QUY_I,
                   x.XEP_LOAI_QUY_II,
                   x.XEP_LOAI_QUY_III,
                   x.XEP_LOAI_QUY_IV,
                   x.XEP_LOAI_6_THANG_DAU_NAM,
                   x.XEP_LOAI_6_THANG_CUOI_NAM,
                   x.XEP_LOAI_CA_NAM
              FROM QLPN.XEP_LOAIS x
              JOIN xl_year xy ON xy.MAX_ID = x.ID
        ),
        hpbs_con_tien AS (
            SELECT DISTINCT HPBS_MA_PHAM_NHAN AS PN_ID
              FROM QLPN.PN_HINH_PHAT_BO_SUNGS
             WHERE NVL(IS_DELETED, 0) = 0
               AND HPBS_MA_PHAM_NHAN IS NOT NULL
               AND HPBS_TONG_TIEN_CON_LAI > 0
        ),
        filtered AS (
            SELECT
                pll.ID                                              AS PHAM_NHAN_ID,
                pll.LL_SO_HO_SO_LAN_DAU,
                pll.LL_CCCD,
                pll.LL_HO_TEN,
                QLPN.FN_FORMAT_SORT_TEN_PN(pll.LL_HO_TEN)          AS SORT_THEO_TEN,
                pll.LL_NGAY_SINH,
                gt.GT_TEN                                           AS TEN_GIOI_TINH,
                CASE WHEN pt.PT_TEN IS NOT NULL
                     THEN TO_CHAR(pd.PD_TEN) || ', ' || TO_CHAR(pt.PT_TEN)
                     ELSE TO_CHAR(pd.PD_TEN) END AS TEN_PHAN_DOI,
                tha.THA_AN_PHAT                                     AS AN_PHAT,
                tha.THA_MA_AN_PHAT                                  AS SORT_AN_PHAT,
                tha.THA_NGAY_HET_HAN                                AS NGAY_HET_HAN,
                TO_CHAR(xl.XEP_LOAI_QUY_I)                          AS XEP_LOAI_QUY_I,
                TO_CHAR(xl.XEP_LOAI_QUY_II)                         AS XEP_LOAI_QUY_II,
                TO_CHAR(xl.XEP_LOAI_QUY_III)                        AS XEP_LOAI_QUY_III,
                TO_CHAR(xl.XEP_LOAI_QUY_IV)                         AS XEP_LOAI_QUY_IV,
                TO_CHAR(xl.XEP_LOAI_6_THANG_DAU_NAM)                AS XEP_LOAI_6_THANG_DAU_NAM,
                TO_CHAR(xl.XEP_LOAI_6_THANG_CUOI_NAM)               AS XEP_LOAI_6_THANG_CUOI_NAM,
                TO_CHAR(xl.XEP_LOAI_CA_NAM)                         AS XEP_LOAI_CA_NAM,
                NVL(TO_CHAR(pll.LL_DIA_CHI_THUONG_TRU), '')
                    || CASE WHEN xp.XP_TEN IS NOT NULL
                            THEN CASE WHEN pll.LL_DIA_CHI_THUONG_TRU IS NOT NULL THEN ', ' END || TO_CHAR(xp.XP_TEN) END
                    || CASE WHEN ttp.TTP_TEN IS NOT NULL THEN
                        CASE WHEN pll.LL_DIA_CHI_THUONG_TRU IS NOT NULL OR xp.XP_TEN IS NOT NULL THEN ', ' END
                             || TO_CHAR(ttp.TTP_TEN) END
                    AS DIA_CHI_THUONG_TRU,
                CASE
                    WHEN tha.THA_TOI_DANH IS NULL THEN NULL
                    ELSE (
                        SELECT LISTAGG(TRIM(TO_CHAR(td.TD_TEN)), '; ') WITHIN GROUP (ORDER BY TRIM(TO_CHAR(td.TD_TEN)))
                          FROM QLPN.DM_TOI_DANHS td
                         WHERE INSTR(
                                   ',' || REPLACE(REPLACE(REPLACE(TO_CHAR(tha.THA_TOI_DANH), '[', ''), ']', ''), ' ', '') || ',',
                                   ',' || TO_CHAR(td.ID) || ','
                               ) > 0
                    )
                END AS TOI_DANH,
                CASE
                    WHEN tha.THA_TOI_DANH IS NULL THEN NULL
                    ELSE (
                        SELECT MIN(TRIM(TO_CHAR(td.TD_TEN)))
                          FROM QLPN.DM_TOI_DANHS td
                         WHERE INSTR(
                                   ',' || REPLACE(REPLACE(REPLACE(TO_CHAR(tha.THA_TOI_DANH), '[', ''), ']', ''), ' ', '') || ',',
                                   ',' || TO_CHAR(td.ID) || ','
                               ) > 0
                    )
                END AS SORT_TOI_DANH,
                CASE
                    WHEN pll.LL_NGAY_SINH IS NULL THEN CASE WHEN V_SORT_ASC = 1 THEN '00000000' ELSE '99999999' END
                    WHEN LENGTH(TO_CHAR(pll.LL_NGAY_SINH)) = 10 THEN
                        SUBSTR(TO_CHAR(pll.LL_NGAY_SINH), 7, 4)
                        || SUBSTR(TO_CHAR(pll.LL_NGAY_SINH), 4, 2)
                        || SUBSTR(TO_CHAR(pll.LL_NGAY_SINH), 1, 2)
                    WHEN LENGTH(TO_CHAR(pll.LL_NGAY_SINH)) = 7 THEN
                        SUBSTR(TO_CHAR(pll.LL_NGAY_SINH), 4, 4)
                        || SUBSTR(TO_CHAR(pll.LL_NGAY_SINH), 1, 2) || '00'
                    WHEN LENGTH(TO_CHAR(pll.LL_NGAY_SINH)) = 4 THEN TO_CHAR(pll.LL_NGAY_SINH) || '0000'
                    ELSE CASE WHEN V_SORT_ASC = 1 THEN '00000000' ELSE '99999999' END
                END AS SORT_NGAY_SINH
            FROM QLPN.PN_LAI_LICHS pll
            INNER JOIN dang_o_trai tt ON tt.ID = pll.LL_TINH_TRANG_ID
            LEFT JOIN tha_latest tha ON tha.PN_ID = pll.ID
            LEFT JOIN QLPN.DM_GIOI_TINHS gt ON gt.ID = pll.LL_DM_GIOI_TINH_ID
            LEFT JOIN QLPN.DM_PHAN_DOIS pd ON pd.ID = pll.LL_PHAN_DOI_ID
            LEFT JOIN QLPN.DM_PHAN_TRAIS pt ON pt.ID = pd.PD_DM_PHAN_TRAI_ID
            LEFT JOIN xl_latest xl ON xl.PN_ID = pll.ID
            LEFT JOIN QLPN.DM_XA_PHUONG xp ON xp.ID = pll.LL_DIA_CHI_THUONG_TRU_WARD
            LEFT JOIN QLPN.DM_TINH_THANH_PHO ttp ON ttp.ID = pll.LL_DIA_CHI_THUONG_TRU_PROVICE
            WHERE NVL(pll.IS_DELETED, 0) = 0
              AND (P_PHAN_DOI_ID IS NULL OR pll.LL_PHAN_DOI_ID = P_PHAN_DOI_ID)
              AND (V_NGAY_DEN_TRAI_TU IS NULL
                   OR (tha.THA_NGAY_DEN_TRAI IS NOT NULL AND TRUNC(tha.THA_NGAY_DEN_TRAI) <= TRUNC(V_NGAY_DEN_TRAI_TU)))
              AND (P_HO_TEN_FILTER IS NULL OR LENGTH(TRIM(P_HO_TEN_FILTER)) = 0 OR
                   INSTR(
                       REPLACE(QLPN.BO_DAU(NVL(TO_CHAR(pll.LL_HO_TEN), '')), ' ', ''),
                       REPLACE(QLPN.BO_DAU(TO_CHAR(TRIM(P_HO_TEN_FILTER))), ' ', '')
                   ) > 0)
              AND (P_HPBS_TIEN_ID IS NULL OR P_HPBS_TIEN_ID = 0
                   OR (P_HPBS_TIEN_ID = 1 AND pll.ID NOT IN (SELECT PN_ID FROM hpbs_con_tien))
                   OR (P_HPBS_TIEN_ID = 2 AND pll.ID IN (SELECT PN_ID FROM hpbs_con_tien)))
              AND (V_HAS_KY_FILTER = 0 OR V_KY_XLCT_MA IS NULL OR
                   (TO_CHAR(V_KY_XLCT_MA) = 'MA_XEP_LOAI_Q1'  AND xl.XEP_LOAI_QUY_I IS NOT NULL) OR
                   (TO_CHAR(V_KY_XLCT_MA) = 'MA_XEP_LOAI_Q2'  AND xl.XEP_LOAI_QUY_II IS NOT NULL) OR
                   (TO_CHAR(V_KY_XLCT_MA) = 'MA_XEP_LOAI_Q3'  AND xl.XEP_LOAI_QUY_III IS NOT NULL) OR
                   (TO_CHAR(V_KY_XLCT_MA) = 'MA_XEP_LOAI_Q4'  AND xl.XEP_LOAI_QUY_IV IS NOT NULL) OR
                   (TO_CHAR(V_KY_XLCT_MA) = 'MA_XEP_LOAI_CUOI' AND xl.XEP_LOAI_6_THANG_CUOI_NAM IS NOT NULL) OR
                   (TO_CHAR(V_KY_XLCT_MA) = 'MA_XEP_LOAI_DAU'  AND xl.XEP_LOAI_6_THANG_DAU_NAM IS NOT NULL) OR
                   (TO_CHAR(V_KY_XLCT_MA) = 'MA_XEP_LOAI_CA'   AND xl.XEP_LOAI_CA_NAM IS NOT NULL))
              AND (V_HAS_LOAI_FILTER = 0 OR V_KY_XLCT_MA IS NULL OR
                   (TO_CHAR(V_KY_XLCT_MA) = 'MA_XEP_LOAI_Q1'  AND xl.XEP_LOAI_QUY_I = P_LOAI_XEP_LOAI_ID) OR
                   (TO_CHAR(V_KY_XLCT_MA) = 'MA_XEP_LOAI_Q2'  AND xl.XEP_LOAI_QUY_II = P_LOAI_XEP_LOAI_ID) OR
                   (TO_CHAR(V_KY_XLCT_MA) = 'MA_XEP_LOAI_Q3'  AND xl.XEP_LOAI_QUY_III = P_LOAI_XEP_LOAI_ID) OR
                   (TO_CHAR(V_KY_XLCT_MA) = 'MA_XEP_LOAI_Q4'  AND xl.XEP_LOAI_QUY_IV = P_LOAI_XEP_LOAI_ID) OR
                   (TO_CHAR(V_KY_XLCT_MA) = 'MA_XEP_LOAI_DAU'  AND xl.XEP_LOAI_6_THANG_DAU_NAM = P_LOAI_XEP_LOAI_ID) OR
                   (TO_CHAR(V_KY_XLCT_MA) = 'MA_XEP_LOAI_CUOI' AND xl.XEP_LOAI_6_THANG_CUOI_NAM = P_LOAI_XEP_LOAI_ID) OR
                   (TO_CHAR(V_KY_XLCT_MA) = 'MA_XEP_LOAI_CA'   AND xl.XEP_LOAI_CA_NAM = P_LOAI_XEP_LOAI_ID))
        ),
        numbered AS (
            SELECT f.*,
                   COUNT(*) OVER() AS TOTAL_COUNT,
                   ROW_NUMBER() OVER (
                       ORDER BY
                           CASE WHEN V_SORT_NGAYSINH = 1 AND V_SORT_ASC = 1 THEN f.SORT_NGAY_SINH END ASC,
                           CASE WHEN V_SORT_NGAYSINH = 1 AND V_SORT_ASC = 0 THEN f.SORT_NGAY_SINH END DESC NULLS LAST,
                           CASE WHEN V_SORT_NGAYSINH = 1 AND V_SORT_ASC = 1 THEN f.PHAM_NHAN_ID END ASC,
                           CASE WHEN V_SORT_NGAYSINH = 1 AND V_SORT_ASC = 0 THEN f.PHAM_NHAN_ID END DESC NULLS LAST,
                           CASE WHEN V_SORT_DIACHI = 1 AND V_SORT_ASC = 1 THEN LOWER(f.DIA_CHI_THUONG_TRU) END ASC,
                           CASE WHEN V_SORT_DIACHI = 1 AND V_SORT_ASC = 0 THEN LOWER(f.DIA_CHI_THUONG_TRU) END DESC NULLS LAST,
                           CASE WHEN V_SORT_TOIDANH = 1 AND V_SORT_ASC = 1 THEN LOWER(f.SORT_TOI_DANH) END ASC,
                           CASE WHEN V_SORT_TOIDANH = 1 AND V_SORT_ASC = 0 THEN LOWER(f.SORT_TOI_DANH) END DESC NULLS LAST,
                           CASE WHEN V_SORT_ANPHAT = 1 AND V_SORT_ASC = 1 THEN f.SORT_AN_PHAT END ASC,
                           CASE WHEN V_SORT_ANPHAT = 1 AND V_SORT_ASC = 0 THEN f.SORT_AN_PHAT END DESC NULLS LAST,
                           CASE WHEN V_SORT_HOTEN = 1 AND V_SORT_ASC = 1 THEN f.SORT_THEO_TEN END ASC,
                           CASE WHEN V_SORT_HOTEN = 1 AND V_SORT_ASC = 0 THEN f.SORT_THEO_TEN END DESC NULLS LAST,
                           CASE WHEN V_SORT_GIOITINH = 1 AND V_SORT_ASC = 1 THEN f.TEN_GIOI_TINH END ASC,
                           CASE WHEN V_SORT_GIOITINH = 1 AND V_SORT_ASC = 0 THEN f.TEN_GIOI_TINH END DESC NULLS LAST,
                           CASE WHEN V_SORT_GIOITINH = 1 AND V_SORT_ASC = 1 THEN f.PHAM_NHAN_ID END ASC,
                           CASE WHEN V_SORT_GIOITINH = 1 AND V_SORT_ASC = 0 THEN f.PHAM_NHAN_ID END DESC NULLS LAST,
                           CASE WHEN V_SORT_PHANDOI = 1 AND V_SORT_ASC = 1 THEN f.TEN_PHAN_DOI END ASC,
                           CASE WHEN V_SORT_PHANDOI = 1 AND V_SORT_ASC = 0 THEN f.TEN_PHAN_DOI END DESC NULLS LAST,
                           CASE WHEN V_SORT_PHANDOI = 1 AND V_SORT_ASC = 1 THEN f.PHAM_NHAN_ID END ASC,
                           CASE WHEN V_SORT_PHANDOI = 1 AND V_SORT_ASC = 0 THEN f.PHAM_NHAN_ID END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND TO_CHAR(V_SORTING_LOWER) LIKE '%sohosolandau%' THEN f.LL_SO_HO_SO_LAN_DAU END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND TO_CHAR(V_SORTING_LOWER) LIKE '%sohosolandau%' THEN f.LL_SO_HO_SO_LAN_DAU END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND TO_CHAR(V_SORTING_LOWER) LIKE '%cccd%' THEN f.LL_CCCD END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND TO_CHAR(V_SORTING_LOWER) LIKE '%cccd%' THEN f.LL_CCCD END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND TO_CHAR(V_SORTING_LOWER) LIKE '%ngayhethan%' THEN f.NGAY_HET_HAN END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND TO_CHAR(V_SORTING_LOWER) LIKE '%ngayhethan%' THEN f.NGAY_HET_HAN END DESC NULLS LAST,
                           CASE WHEN V_SORT_NGAYSINH = 0 AND V_SORT_DIACHI = 0 AND V_SORT_TOIDANH = 0
                                 AND V_SORT_ANPHAT = 0 AND V_SORT_HOTEN = 0 AND V_SORT_GIOITINH = 0
                                 AND V_SORT_PHANDOI = 0 AND V_SORT_DEFAULT = 0 THEN f.PHAM_NHAN_ID END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1
                                 AND TO_CHAR(V_SORTING_LOWER) NOT LIKE '%sohosolandau%'
                                 AND TO_CHAR(V_SORTING_LOWER) NOT LIKE '%cccd%'
                                 AND TO_CHAR(V_SORTING_LOWER) NOT LIKE '%ngayhethan%' THEN f.PHAM_NHAN_ID END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0
                                 AND TO_CHAR(V_SORTING_LOWER) NOT LIKE '%sohosolandau%'
                                 AND TO_CHAR(V_SORTING_LOWER) NOT LIKE '%cccd%'
                                 AND TO_CHAR(V_SORTING_LOWER) NOT LIKE '%ngayhethan%' THEN f.PHAM_NHAN_ID END DESC NULLS LAST,
                           f.PHAM_NHAN_ID DESC
                   ) AS RN
              FROM filtered f
        )
        SELECT PHAM_NHAN_ID,
               LL_SO_HO_SO_LAN_DAU AS SO_HO_SO_LAN_DAU,
               LL_CCCD AS CCCD,
               LL_HO_TEN AS HO_TEN,
               SORT_THEO_TEN,
               LL_NGAY_SINH AS NGAY_SINH,
               TEN_GIOI_TINH,
               TEN_PHAN_DOI,
               TOI_DANH,
               AN_PHAT,
               NGAY_HET_HAN,
               XEP_LOAI_QUY_I,
               XEP_LOAI_QUY_II,
               XEP_LOAI_QUY_III,
               XEP_LOAI_QUY_IV,
               XEP_LOAI_6_THANG_DAU_NAM,
               XEP_LOAI_6_THANG_CUOI_NAM,
               XEP_LOAI_CA_NAM,
               DIA_CHI_THUONG_TRU,
               TOTAL_COUNT
          FROM numbered
         WHERE P_MAX_RESULT_COUNT IS NULL
            OR (RN > NVL(P_SKIP_COUNT, 0) AND RN <= NVL(P_SKIP_COUNT, 0) + P_MAX_RESULT_COUNT);

END SP_GET_DS_XEP_LOAI_TRONG_KY;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_XLCT_CHUNG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_XLCT_CHUNG" (
    p_phan_doi_id      IN NUMBER   DEFAULT NULL,
    p_phan_trai_id     IN NUMBER   DEFAULT NULL,
    p_nam_xl           IN NUMBER   DEFAULT NULL,
    p_ky_xep_loai      IN VARCHAR2 DEFAULT NULL,
    p_tinh_trang_id    IN NUMBER   DEFAULT NULL,
    p_loai_xep_loai_id IN NUMBER   DEFAULT NULL,
    p_pn_ids           IN VARCHAR2 DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        WITH
        -- ?? 1. Parse danh sách ID truy?n vào (CSV ? rows) ????????????????
        ID_LIST AS (
            SELECT /*+ MATERIALIZE */ PN_ID, MIN(PN_ORD) AS PN_ORD
            FROM (
                SELECT LEVEL AS PN_ORD,
                       TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
                FROM DUAL
                CONNECT BY LEVEL <= CASE
                        WHEN p_pn_ids IS NULL THEN 0
                        WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                        ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                    END
                  AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
                  AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
            )
            GROUP BY PN_ID
        ),

        -- ?? 2. L?c XEP_LOAIS theo n?m / k? / lo?i ???????????????????????
        pn_xl AS (
            SELECT xl.PHAM_NHAN_ID,
                   xl.XEP_LOAI_NAM,
                   xl.XEP_LOAI_QUY_I,
                   xl.XEP_LOAI_QUY_II,
                   xl.XEP_LOAI_QUY_III,
                   xl.XEP_LOAI_QUY_IV,
                   xl.XEP_LOAI_CA_NAM
            FROM XEP_LOAIS xl
            WHERE NVL(xl.IS_DELETED, 0) = 0
              AND (p_pn_ids IS NULL OR EXISTS (
                      SELECT 1 FROM ID_LIST il WHERE il.PN_ID = xl.PHAM_NHAN_ID
                  ))
              AND (p_nam_xl IS NULL OR xl.XEP_LOAI_NAM = p_nam_xl)
              AND (
                  p_loai_xep_loai_id IS NULL
                  OR (
                      p_ky_xep_loai IS NOT NULL
                      AND (
                          CASE
                              WHEN p_ky_xep_loai = 'MA_XEP_LOAI_Q1' THEN xl.XEP_LOAI_QUY_I
                              WHEN p_ky_xep_loai = 'MA_XEP_LOAI_Q2' THEN xl.XEP_LOAI_QUY_II
                              WHEN p_ky_xep_loai = 'MA_XEP_LOAI_Q3' THEN xl.XEP_LOAI_QUY_III
                              WHEN p_ky_xep_loai = 'MA_XEP_LOAI_Q4' THEN xl.XEP_LOAI_QUY_IV
                              WHEN p_ky_xep_loai = '6_THANG_DAU_NAM' THEN xl.XEP_LOAI_6_THANG_DAU_NAM
                              WHEN p_ky_xep_loai = '6_THANG_CUOI_NAM' THEN xl.XEP_LOAI_6_THANG_CUOI_NAM
                              WHEN p_ky_xep_loai = 'MA_XEP_LOAI_CA' THEN xl.XEP_LOAI_CA_NAM
                          END = p_loai_xep_loai_id
                      )
                  )
                  OR (
                      p_ky_xep_loai IS NULL
                      AND (
                          xl.XEP_LOAI_QUY_I            = p_loai_xep_loai_id
                          OR xl.XEP_LOAI_QUY_II           = p_loai_xep_loai_id
                          OR xl.XEP_LOAI_QUY_III          = p_loai_xep_loai_id
                          OR xl.XEP_LOAI_QUY_IV           = p_loai_xep_loai_id
                          OR xl.XEP_LOAI_6_THANG_DAU_NAM  = p_loai_xep_loai_id
                          OR xl.XEP_LOAI_6_THANG_CUOI_NAM = p_loai_xep_loai_id
                          OR xl.XEP_LOAI_CA_NAM           = p_loai_xep_loai_id
                      )
                  )
              )
        ),

        -- ?? 3. Join v?i RT table (thay PN_LAI_LICHS + PN_THI_HANH_AN) ????
        --   RT ?ã pre-join + pre-compute:
        --     THA_TOI_DANH_NAMES, THA_THOI_GIAN_DA_CHAP_HANH,
        --     THA_THOI_GIAN_CON_LAI, THOI_GIAN_DA_GIAM, SO_LAN_GIAM
        pn_filtered AS (
            SELECT /*+ MATERIALIZE */
                   rt.PHAM_NHAN_ID                       AS ID,
                   rt.LL_HO_TEN,
                   rt.LL_NGAY_SINH,
                   rt.LL_DM_GIOI_TINH_ID,
                   rt.LL_PHAN_TRAI_ID,
                   rt.LL_PHAN_DOI_ID,
                   rt.LL_DIA_CHI_THUONG_TRU,
                   rt.LL_DIA_CHI_THUONG_TRU_PROVICE,
                   rt.LL_DIA_CHI_THUONG_TRU_WARD,
                   rt.LL_SO_TIEN_AN,
                   rt.LL_TINH_TRANG_ID,
                   -- THA fields (pre-joined t? PN_THI_HANH_AN)
                   rt.THA_NGAY_BAT,
                   rt.THA_AN_PHAT,
                   rt.THA_NGAY_DEN_TRAI,
                   rt.THA_NGAY_HET_HAN,
                   rt.THA_GHI_CHU_DAC_BIET,
                   -- Pre-computed: thay th? 4 scalar functions + 2 CTE CONNECT BY
                   rt.THA_TOI_DANH_NAMES,
                   rt.THA_THOI_GIAN_DA_CHAP_HANH,
                   rt.THA_THOI_GIAN_CON_LAI,
                   rt.THOI_GIAN_DA_GIAM,
                   rt.SO_LAN_GIAM,
                   -- XEP_LOAI fields t? pn_xl
                   xl.XEP_LOAI_NAM,
                   xl.XEP_LOAI_QUY_I,
                   xl.XEP_LOAI_QUY_II,
                   xl.XEP_LOAI_QUY_III,
                   xl.XEP_LOAI_QUY_IV,
                   xl.XEP_LOAI_CA_NAM
            FROM pn_xl xl
            JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt
                ON rt.PHAM_NHAN_ID = xl.PHAM_NHAN_ID
               AND rt.IS_DELETED = 0
            WHERE (p_phan_trai_id  IS NULL OR rt.LL_PHAN_TRAI_ID  = p_phan_trai_id)
              AND (p_phan_doi_id   IS NULL OR rt.LL_PHAN_DOI_ID   = p_phan_doi_id)
              AND (p_tinh_trang_id IS NULL OR rt.LL_TINH_TRANG_ID = p_tinh_trang_id)
              AND (p_pn_ids IS NULL OR EXISTS (
                      SELECT 1 FROM ID_LIST il WHERE il.PN_ID = rt.PHAM_NHAN_ID
                  ))
        ),

        -- ?? 4. T?ng h?p x?p lo?i t?t c? n?m ?????????????????????????????
        --   (thêm MATERIALIZE; b? dead join xl_canam)
        xep_loai_agg AS (
            SELECT /*+ MATERIALIZE */
                   xl.PHAM_NHAN_ID,
                   SUBSTR(
                       RTRIM(
                           XMLAGG(
                               XMLELEMENT(
                                   e,
                                   TO_NCHAR(xl.XEP_LOAI_NAM) || TO_NCHAR(': ') ||
                                   RTRIM(
                                       CASE WHEN xl_q1.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q1: ') || xl_q1.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END ||
                                       CASE WHEN xl_q2.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q2: ') || xl_q2.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END ||
                                       CASE WHEN xl_q3.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q3: ') || xl_q3.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END ||
                                       CASE WHEN xl_q4.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q4: ') || xl_q4.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END,
                                       '; '
                                   )
                               )
                               ORDER BY xl.XEP_LOAI_NAM
                           ).EXTRACT('//text()').GETSTRINGVAL(),
                           CHR(10)
                       ), 1, 4000
                   ) AS XEP_LOAI_TAT_CA_NAM
            FROM XEP_LOAIS xl
            LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q1 ON xl.XEP_LOAI_QUY_I   = xl_q1.ID
            LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q2 ON xl.XEP_LOAI_QUY_II  = xl_q2.ID
            LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q3 ON xl.XEP_LOAI_QUY_III = xl_q3.ID
            LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q4 ON xl.XEP_LOAI_QUY_IV  = xl_q4.ID
            WHERE xl.PHAM_NHAN_ID IN (SELECT ID FROM pn_filtered)
              AND (p_nam_xl IS NULL OR xl.XEP_LOAI_NAM = p_nam_xl)
            GROUP BY xl.PHAM_NHAN_ID
        )

        -- ?? 5. SELECT cu?i ????????????????????????????????????????????????
        SELECT pnf.ID                                           AS "ID",
               pnf.LL_HO_TEN                                   AS "HoTen",
               SUBSTR(pnf.LL_NGAY_SINH, -4)                    AS "NamSinh",
               dgt.GT_TEN                                      AS "GioiTinh",
               dpt.PT_TEN                                      AS "PhanTrai",
               dpd.PD_TEN                                      AS "PhanDoi",
               CASE
                   WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                     OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
                     OR NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL
                   THEN TRIM(
                       NVL(NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U''), U'')
                       || CASE
                              WHEN NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL THEN
                                  CASE
                                      WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                          THEN U', ' || dxp.XP_TEN
                                      ELSE dxp.XP_TEN
                                  END
                              ELSE U''
                          END
                       || CASE
                              WHEN NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL THEN
                                  CASE
                                      WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                        OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
                                          THEN U', ' || dttp.TTP_TEN
                                      ELSE dttp.TTP_TEN
                                  END
                              ELSE U''
                          END
                   )
                   ELSE NULL
               END                                             AS "DiaChiThuongTru",
               TRIM(pnf.THA_TOI_DANH_NAMES)                   AS "ToiDanh",
               pnf.LL_SO_TIEN_AN                               AS "SoTienAn",
               TO_NCHAR(pnf.THA_NGAY_BAT, 'dd/mm/yyyy')       AS "NgayBat",
               pnf.THA_AN_PHAT                                 AS "AnPhat",
               TO_NCHAR(pnf.THA_NGAY_DEN_TRAI, 'dd/mm/yyyy')  AS "NgayDenTrai",
               TO_NCHAR(pnf.THA_NGAY_HET_HAN, 'dd/mm/yyyy')   AS "NgayHetHan",
               -- DaGiam: SO_LAN_GIAM + THOI_GIAN_DA_GIAM t? RT (thay FN_TINH_AN_DA_GIAM_CHI_TIET)
               CASE
                   WHEN NVL(pnf.SO_LAN_GIAM, 0) = 0
                   THEN TO_NCHAR(U'Không')
                   WHEN NVL(TO_NCHAR(pnf.THOI_GIAN_DA_GIAM), U'0') = U'0' OR pnf.THOI_GIAN_DA_GIAM IS NULL
                   THEN TO_NCHAR(pnf.SO_LAN_GIAM) || TO_NCHAR(U' l?n')
                   ELSE TO_NCHAR(pnf.SO_LAN_GIAM) || TO_NCHAR(U' l?n = ') || TO_NCHAR(pnf.THOI_GIAN_DA_GIAM)
               END                                             AS "DaGiam",
               -- DaChapHanh: decode MTG_MA "YYMMDD" t? RT (thay FN_GET_DA_CHAP_HANH_THEO_NGAY)
               CASE
                   WHEN pnf.THA_THOI_GIAN_DA_CHAP_HANH IS NULL
                     OR pnf.THA_THOI_GIAN_DA_CHAP_HANH = U'000000'
                   THEN TO_NCHAR(U'Không')
                   ELSE TRIM(
                       CASE WHEN TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_DA_CHAP_HANH, 1, 2)) > 0
                            THEN TO_NCHAR(TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_DA_CHAP_HANH, 1, 2))) || TO_NCHAR(U' n?m ')   ELSE TO_NCHAR(U'') END ||
                       CASE WHEN TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_DA_CHAP_HANH, 3, 2)) > 0
                            THEN TO_NCHAR(TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_DA_CHAP_HANH, 3, 2))) || TO_NCHAR(U' tháng ') ELSE TO_NCHAR(U'') END ||
                       CASE WHEN TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_DA_CHAP_HANH, 5, 2)) > 0
                            THEN TO_NCHAR(TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_DA_CHAP_HANH, 5, 2))) || TO_NCHAR(U' ngày')   ELSE TO_NCHAR(U'') END
                   )
               END                                             AS "DaChapHanh",
               -- ConLai: decode MTG_MA "YYMMDD" t? RT (thay FN_TINH_THOI_GIAN_CON_LAI)
               CASE
                   WHEN pnf.THA_THOI_GIAN_CON_LAI IS NULL
                     OR pnf.THA_THOI_GIAN_CON_LAI = U'000000'
                   THEN TO_NCHAR(U'?ã h?t án')
                   ELSE TRIM(
                       CASE WHEN TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_CON_LAI, 1, 2)) > 0
                            THEN TO_NCHAR(TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_CON_LAI, 1, 2))) || TO_NCHAR(U' n?m ')   ELSE TO_NCHAR(U'') END ||
                       CASE WHEN TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_CON_LAI, 3, 2)) > 0
                            THEN TO_NCHAR(TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_CON_LAI, 3, 2))) || TO_NCHAR(U' tháng ') ELSE TO_NCHAR(U'') END ||
                       CASE WHEN TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_CON_LAI, 5, 2)) > 0
                            THEN TO_NCHAR(TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_CON_LAI, 5, 2))) || TO_NCHAR(U' ngày')   ELSE TO_NCHAR(U'') END
                   )
               END                                             AS "ConLai",
               pnf.THA_GHI_CHU_DAC_BIET                       AS "GhiChu",
               pnf.XEP_LOAI_NAM                                AS "NamXepLoai",
               xla.XEP_LOAI_TAT_CA_NAM                         AS "KetQuaCaiTao",
               QLPN.FN_GET_LIET_KE_HPBS_CHI_TIET(pnf.ID)      AS "HPBS"

        FROM pn_filtered pnf
        LEFT JOIN ID_LIST il
            ON il.PN_ID = pnf.ID
        LEFT JOIN DM_GIOI_TINHS dgt
            ON pnf.LL_DM_GIOI_TINH_ID = dgt.ID
           AND NVL(dgt.IS_DELETED, 0) = 0
        LEFT JOIN DM_PHAN_TRAIS dpt
            ON pnf.LL_PHAN_TRAI_ID = dpt.ID
           AND NVL(dpt.IS_DELETED, 0) = 0
        LEFT JOIN DM_PHAN_DOIS dpd
            ON pnf.LL_PHAN_DOI_ID = dpd.ID
           AND NVL(dpd.IS_DELETED, 0) = 0
        LEFT JOIN DM_TINH_THANH_PHO dttp
            ON pnf.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp.ID
           AND NVL(dttp.IS_DELETED, 0) = 0
        LEFT JOIN DM_XA_PHUONG dxp
            ON pnf.LL_DIA_CHI_THUONG_TRU_WARD = dxp.ID
           AND NVL(dxp.IS_DELETED, 0) = 0
        LEFT JOIN xep_loai_agg xla
            ON pnf.ID = xla.PHAM_NHAN_ID
        ORDER BY
            CASE WHEN p_pn_ids IS NULL     THEN pnf.ID    ELSE NULL END,
            CASE WHEN p_pn_ids IS NOT NULL THEN il.PN_ORD ELSE NULL END;
    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_DS_XLCT_CHUNG;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_XLCT_EXCEL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_XLCT_EXCEL" (
    p_pn_ids            IN VARCHAR2  DEFAULT NULL,
    p_nam_xep_loai      IN NUMBER,
    p_ngay_den_trai_tu  IN DATE      DEFAULT NULL,
    p_dieu_kien_id      IN NUMBER    DEFAULT NULL,
    p_ky_da_xep_loai    IN VARCHAR2  DEFAULT NULL,
    p_doi_tuong_id      IN NUMBER    DEFAULT NULL,
    p_ho_ten            IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi_id       IN NUMBER    DEFAULT NULL,
    p_tinh_trang_id     IN NUMBER    DEFAULT NULL,
    p_loai_xep_loai_id  IN NUMBER    DEFAULT NULL,
    p_hpbs_id           IN NUMBER    DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    -- ?? 1. Parse danh sách ID ?????????????????????????????????????????
    ID_LIST AS (
        SELECT /*+ MATERIALIZE */ PN_ID, MIN(PN_ORD) AS PN_ORD
        FROM (
            SELECT LEVEL AS PN_ORD,
                   TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
            FROM DUAL
            CONNECT BY LEVEL <= CASE
                    WHEN p_pn_ids IS NULL THEN 0
                    WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                    ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                END
              AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
        )
        GROUP BY PN_ID
    ),

    -- ?? 2. L?c XEP_LOAIS theo n?m + p_pn_ids ????????????????????????
    pn_xl AS (
        SELECT xl.PHAM_NHAN_ID
        FROM XEP_LOAIS xl
        WHERE NVL(xl.IS_DELETED, 0) = 0
          AND (p_pn_ids IS NULL OR EXISTS (
                  SELECT 1 FROM ID_LIST il WHERE il.PN_ID = xl.PHAM_NHAN_ID
              ))
          AND (p_nam_xep_loai IS NULL OR xl.XEP_LOAI_NAM = p_nam_xep_loai)
    ),

    -- ?? 3. L?c ph?m nhân t? RT (thay PN_LAI_LICHS) ???????????????????
    pn_filtered AS (
        SELECT /*+ MATERIALIZE */
               rt.PHAM_NHAN_ID                         AS ID,
               rt.LL_HO_TEN,
               rt.LL_NGAY_SINH,
               rt.LL_DM_GIOI_TINH_ID,
               rt.LL_PHAN_TRAI_ID,
               rt.LL_PHAN_DOI_ID,
               rt.LL_DIA_CHI_THUONG_TRU,
               rt.LL_DIA_CHI_THUONG_TRU_PROVICE,
               rt.LL_DIA_CHI_THUONG_TRU_WARD,
               rt.LL_SO_TIEN_AN,
               rt.LL_TINH_TRANG_ID,
               rt.LL_SO_HO_SO_LAN_DAU,
               rt.THA_NGAY_BAT,
               rt.THA_AN_PHAT,
               rt.THA_NGAY_DEN_TRAI,
               rt.THA_NGAY_HET_HAN,
               rt.THA_TOI_DANH_NAMES
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        JOIN pn_xl ON pn_xl.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
        WHERE rt.IS_DELETED = 0
--          AND (p_phan_doi_id   IS NULL OR rt.LL_PHAN_DOI_ID   = p_phan_doi_id)
--          AND (p_tinh_trang_id IS NULL OR rt.LL_TINH_TRANG_ID = p_tinh_trang_id)
          AND (p_pn_ids IS NULL OR EXISTS (
                  SELECT 1 FROM ID_LIST il WHERE il.PN_ID = rt.PHAM_NHAN_ID
              ))
    ),

    -- ?? 4. T?ng h?p HPBS ?????????????????????????????????????????????
    hpbs_agg AS (
        SELECT phpbs.HPBS_MA_PHAM_NHAN,
               SUM(phpbs.HPBS_TONG_TIEN_PHAT) AS TONG_TIEN_PHAT,
               CASE WHEN SUM(phpbs.HPBS_TONG_TIEN_PHAT) = 0 THEN 1
                    WHEN SUM(phpbs.HPBS_TONG_TIEN_PHAT)
                       - SUM(NVL(phpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0 THEN 1
                    ELSE 2 END AS HPBS_TINH_TRANG
        FROM PN_HINH_PHAT_BO_SUNGS phpbs
        WHERE NVL(phpbs.IS_DELETED, 0) = 0
          AND phpbs.HPBS_MA_PHAM_NHAN IN (SELECT ID FROM pn_filtered)
        GROUP BY phpbs.HPBS_MA_PHAM_NHAN
    )

    -- ?? 5. SELECT cu?i ????????????????????????????????????????????????
    SELECT
        ROWNUM                                                      AS "Stt",
        pnf.LL_SO_HO_SO_LAN_DAU                                     AS "SoHoSoLanDau",
        pnf.LL_HO_TEN                                               AS "HoTen",
        dgt.GT_TEN                                                  AS "GioiTinh",
        SUBSTR(pnf.LL_NGAY_SINH, -4)                                AS "NamSinh",
        CASE
            WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
              OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
              OR NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U''), U'')
                || CASE
                       WHEN NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                THEN U', ' || dxp.XP_TEN ELSE dxp.XP_TEN END
                       ELSE U''
                   END
                || CASE
                       WHEN NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                  OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
                                THEN U', ' || dttp.TTP_TEN ELSE dttp.TTP_TEN END
                       ELSE U''
                   END
            )
            ELSE NULL
        END                                                         AS "DiaChiThuongTru",
        TRIM(pnf.THA_TOI_DANH_NAMES)                               AS "ToiDanh",
        TO_NCHAR(pnf.THA_NGAY_BAT,      'DD/MM/YYYY')              AS "NgayBat",
        pnf.THA_AN_PHAT                                             AS "AnPhat",
        TO_NCHAR(pnf.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY')              AS "NgayDenTrai",
        TO_NCHAR(pnf.THA_NGAY_HET_HAN,  'DD/MM/YYYY')              AS "NgayHetHan",
        xl_q1.XLCT_TEN                                              AS "Quy1",
        xl_q2.XLCT_TEN                                              AS "Quy2",
        xl_6dau.XLCT_TEN                                            AS "DauNam",
        xl_q3.XLCT_TEN                                              AS "Quy3",
        xl_q4.XLCT_TEN                                              AS "Quy4",
        xl_6cuoi.XLCT_TEN                                           AS "CuoiNam",
        xl_canam.XLCT_TEN                                           AS "CaNam",
        dttpn.TTPN_TEN                                              AS "TinhTrang",
        CONCAT(CONCAT(dpd.PD_TEN, ', '), dpt.PT_TEN)                AS "PhanDoi"
    FROM pn_filtered pnf
    LEFT JOIN ID_LIST il ON il.PN_ID = pnf.ID
    LEFT JOIN DM_GIOI_TINHS dgt
        ON pnf.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_PHAN_TRAIS dpt
        ON pnf.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_PHAN_DOIS dpd
        ON pnf.LL_PHAN_DOI_ID = dpd.ID
    LEFT JOIN hpbs_agg ON pnf.ID = hpbs_agg.HPBS_MA_PHAM_NHAN
    -- X?p lo?i theo n?m
    LEFT JOIN XEP_LOAIS xl
        ON pnf.ID = xl.PHAM_NHAN_ID
       AND xl.XEP_LOAI_NAM = p_nam_xep_loai
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q1    ON xl.XEP_LOAI_QUY_I            = xl_q1.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q2    ON xl.XEP_LOAI_QUY_II           = xl_q2.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q3    ON xl.XEP_LOAI_QUY_III          = xl_q3.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q4    ON xl.XEP_LOAI_QUY_IV           = xl_q4.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_6dau  ON xl.XEP_LOAI_6_THANG_DAU_NAM  = xl_6dau.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_6cuoi ON xl.XEP_LOAI_6_THANG_CUOI_NAM = xl_6cuoi.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_canam ON xl.XEP_LOAI_CA_NAM            = xl_canam.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp
        ON pnf.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp.ID
       AND NVL(dttp.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp
        ON pnf.LL_DIA_CHI_THUONG_TRU_WARD = dxp.ID
       AND NVL(dxp.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dttpn ON pnf.LL_TINH_TRANG_ID = dttpn.ID
    ORDER BY
        CASE WHEN p_pn_ids IS NULL THEN pnf.ID ELSE il.PN_ORD END;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            U'L?i SP_GET_DS_XLCT_EXCEL: ' || SQLERRM);
END SP_GET_DS_XLCT_EXCEL;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_XLCT_EXCEL_TONG_HOP
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_XLCT_EXCEL_TONG_HOP" (
    p_pn_ids           IN VARCHAR2 DEFAULT NULL,
    p_phan_doi_id      IN NUMBER   DEFAULT NULL,
    p_nam_xl           IN NUMBER   DEFAULT NULL,
    p_ky_xep_loai      IN VARCHAR2 DEFAULT NULL,
    p_tinh_trang_id    IN NUMBER   DEFAULT NULL,
    p_loai_xep_loai_id IN NUMBER   DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    -- ?? 1. Parse danh sách ID ?????????????????????????????????????????
    ID_LIST AS (
        SELECT /*+ MATERIALIZE */ PN_ID, MIN(PN_ORD) AS PN_ORD
        FROM (
            SELECT LEVEL AS PN_ORD,
                   TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
            FROM DUAL
            CONNECT BY LEVEL <= CASE
                    WHEN p_pn_ids IS NULL THEN 0
                    WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                    ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                END
              AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
        )
        GROUP BY PN_ID
    ),

    -- ?? 2. L?c XEP_LOAIS theo n?m / k? / lo?i ???????????????????????
    pn_xl AS (
        SELECT xl.PHAM_NHAN_ID
        FROM XEP_LOAIS xl
        WHERE NVL(xl.IS_DELETED, 0) = 0
          AND (p_pn_ids IS NULL OR EXISTS (
                  SELECT 1 FROM ID_LIST il WHERE il.PN_ID = xl.PHAM_NHAN_ID
              ))
          AND (p_nam_xl IS NULL OR xl.XEP_LOAI_NAM = p_nam_xl)
          AND (
              p_loai_xep_loai_id IS NULL
              OR (
                  p_ky_xep_loai IS NOT NULL
                  AND (
                      CASE
                          WHEN p_ky_xep_loai = 'MA_XEP_LOAI_Q1'   THEN xl.XEP_LOAI_QUY_I
                          WHEN p_ky_xep_loai = 'MA_XEP_LOAI_Q2'   THEN xl.XEP_LOAI_QUY_II
                          WHEN p_ky_xep_loai = 'MA_XEP_LOAI_Q3'   THEN xl.XEP_LOAI_QUY_III
                          WHEN p_ky_xep_loai = 'MA_XEP_LOAI_Q4'   THEN xl.XEP_LOAI_QUY_IV
                          WHEN p_ky_xep_loai = '6_THANG_DAU_NAM'  THEN xl.XEP_LOAI_6_THANG_DAU_NAM
                          WHEN p_ky_xep_loai = '6_THANG_CUOI_NAM' THEN xl.XEP_LOAI_6_THANG_CUOI_NAM
                          WHEN p_ky_xep_loai = 'MA_XEP_LOAI_CA'   THEN xl.XEP_LOAI_CA_NAM
                      END = p_loai_xep_loai_id
                  )
              )
              OR (
                  -- Không ch?n k? ? t?t c? các k? ?ã nh?p ph?i kh?p (logic g?c AND)
                  p_ky_xep_loai IS NULL
                  AND (xl.XEP_LOAI_QUY_I            IS NULL OR xl.XEP_LOAI_QUY_I            = p_loai_xep_loai_id)
                  AND (xl.XEP_LOAI_QUY_II           IS NULL OR xl.XEP_LOAI_QUY_II           = p_loai_xep_loai_id)
                  AND (xl.XEP_LOAI_QUY_III          IS NULL OR xl.XEP_LOAI_QUY_III          = p_loai_xep_loai_id)
                  AND (xl.XEP_LOAI_QUY_IV           IS NULL OR xl.XEP_LOAI_QUY_IV           = p_loai_xep_loai_id)
                  AND (xl.XEP_LOAI_6_THANG_DAU_NAM  IS NULL OR xl.XEP_LOAI_6_THANG_DAU_NAM  = p_loai_xep_loai_id)
                  AND (xl.XEP_LOAI_6_THANG_CUOI_NAM IS NULL OR xl.XEP_LOAI_6_THANG_CUOI_NAM = p_loai_xep_loai_id)
              )
          )
    ),

    -- ?? 3. L?c ph?m nhân t? RT (thay PN_LAI_LICHS + latest_tha) ?????
    pn_filtered AS (
        SELECT /*+ MATERIALIZE */
               rt.PHAM_NHAN_ID                         AS ID,
               rt.LL_HO_TEN,
               rt.LL_NGAY_SINH,
               rt.LL_DM_GIOI_TINH_ID,
               rt.LL_PHAN_TRAI_ID,
               rt.LL_PHAN_DOI_ID,
               rt.LL_DIA_CHI_THUONG_TRU,
               rt.LL_DIA_CHI_THUONG_TRU_PROVICE,
               rt.LL_DIA_CHI_THUONG_TRU_WARD,
               rt.LL_TINH_TRANG_ID,
               rt.LL_SO_HO_SO_LAN_DAU,
               rt.THA_NGAY_BAT,
               rt.THA_AN_PHAT,
               rt.THA_NGAY_DEN_TRAI,
               rt.THA_NGAY_HET_HAN,
               rt.THA_TOI_DANH_NAMES
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        JOIN pn_xl ON pn_xl.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
        WHERE rt.IS_DELETED = 0
          AND (p_phan_doi_id   IS NULL OR rt.LL_PHAN_DOI_ID   = p_phan_doi_id)
          AND (p_tinh_trang_id IS NULL OR rt.LL_TINH_TRANG_ID = p_tinh_trang_id)
          AND (p_pn_ids IS NULL OR EXISTS (
                  SELECT 1 FROM ID_LIST il WHERE il.PN_ID = rt.PHAM_NHAN_ID
              ))
    )

    -- ?? 4. SELECT cu?i ????????????????????????????????????????????????
    SELECT
        ROWNUM                                                      AS "Stt",
        pnf.LL_SO_HO_SO_LAN_DAU                                     AS "SoHoSoLanDau",
        pnf.LL_HO_TEN                                               AS "HoTen",
        dgt.GT_TEN                                                  AS "GioiTinh",
        SUBSTR(pnf.LL_NGAY_SINH, -4)                                AS "NamSinh",
        CASE
            WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
              OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
              OR NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U''), U'')
                || CASE
                       WHEN NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                THEN U', ' || dxp.XP_TEN ELSE dxp.XP_TEN END
                       ELSE U''
                   END
                || CASE
                       WHEN NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                  OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
                                THEN U', ' || dttp.TTP_TEN ELSE dttp.TTP_TEN END
                       ELSE U''
                   END
            )
            ELSE NULL
        END                                                         AS "DiaChiThuongTru",
        TRIM(pnf.THA_TOI_DANH_NAMES)                               AS "ToiDanh",
        TO_NCHAR(pnf.THA_NGAY_BAT,      'DD/MM/YYYY')              AS "NgayBat",
        pnf.THA_AN_PHAT                                             AS "AnPhat",
        TO_NCHAR(pnf.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY')              AS "NgayDenTrai",
        TO_NCHAR(pnf.THA_NGAY_HET_HAN,  'DD/MM/YYYY')              AS "NgayHetHan",
        xl_q1.XLCT_TEN                                              AS "Quy1",
        xl_q2.XLCT_TEN                                              AS "Quy2",
        xl_6dau.XLCT_TEN                                            AS "DauNam",
        xl_q3.XLCT_TEN                                              AS "Quy3",
        xl_q4.XLCT_TEN                                              AS "Quy4",
        xl_6cuoi.XLCT_TEN                                           AS "CuoiNam",
        xl_canam.XLCT_TEN                                           AS "CaNam",
        CASE
            WHEN pnf.THA_NGAY_HET_HAN IS NULL    THEN U'?ang ch?p hành án'
            WHEN pnf.THA_NGAY_HET_HAN > SYSDATE  THEN U'?ang ch?p hành án'
            ELSE U'?ã ra tù'
        END                                                         AS "TinhTrang",
        CONCAT(CONCAT(dpd.PD_TEN, ', '), dpt.PT_TEN)                AS "PhanDoi"
    FROM pn_filtered pnf
    LEFT JOIN ID_LIST il ON il.PN_ID = pnf.ID
    LEFT JOIN DM_GIOI_TINHS dgt
        ON pnf.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_PHAN_TRAIS dpt
        ON pnf.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_PHAN_DOIS dpd
        ON pnf.LL_PHAN_DOI_ID = dpd.ID
    -- X?p lo?i theo n?m (cho output các c?t quý/c? n?m)
    LEFT JOIN XEP_LOAIS xl
        ON pnf.ID = xl.PHAM_NHAN_ID
       AND (p_nam_xl IS NULL OR xl.XEP_LOAI_NAM = p_nam_xl)
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q1    ON xl.XEP_LOAI_QUY_I            = xl_q1.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q2    ON xl.XEP_LOAI_QUY_II           = xl_q2.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q3    ON xl.XEP_LOAI_QUY_III          = xl_q3.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q4    ON xl.XEP_LOAI_QUY_IV           = xl_q4.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_6dau  ON xl.XEP_LOAI_6_THANG_DAU_NAM  = xl_6dau.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_6cuoi ON xl.XEP_LOAI_6_THANG_CUOI_NAM = xl_6cuoi.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_canam ON xl.XEP_LOAI_CA_NAM            = xl_canam.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp
        ON pnf.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp.ID
       AND NVL(dttp.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp
        ON pnf.LL_DIA_CHI_THUONG_TRU_WARD = dxp.ID
       AND NVL(dxp.IS_DELETED, 0) = 0
    ORDER BY
        CASE WHEN p_pn_ids IS NULL     THEN pnf.ID      ELSE NULL END,
        CASE WHEN p_pn_ids IS NOT NULL THEN il.PN_ORD   ELSE NULL END;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_DS_XLCT_EXCEL_TONG_HOP;







/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_XLCT_HPBS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_XLCT_HPBS" (
    p_pn_ids           IN VARCHAR2 DEFAULT NULL,
    p_phan_doi_id      IN NUMBER   DEFAULT NULL,
    p_nam_xl           IN NUMBER   DEFAULT NULL,
    p_ky_xep_loai      IN VARCHAR2 DEFAULT NULL,
    p_tinh_trang_id    IN NUMBER   DEFAULT NULL,
    p_loai_xep_loai_id IN NUMBER   DEFAULT NULL,
    p_doi_tuong_id     IN NUMBER   DEFAULT NULL,
    p_ho_ten           IN VARCHAR2 DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    -- ?? 1. Parse danh sách ID ?????????????????????????????????????????
    ID_LIST AS (
        SELECT /*+ MATERIALIZE */ PN_ID, MIN(PN_ORD) AS PN_ORD
        FROM (
            SELECT LEVEL AS PN_ORD,
                   TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
            FROM DUAL
            CONNECT BY LEVEL <= CASE
                    WHEN p_pn_ids IS NULL THEN 0
                    WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                    ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                END
              AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
        )
        GROUP BY PN_ID
    ),

    -- ?? 2. L?c ph?m nhân t? RT (thay PN_LAI_LICHS + PN_THI_HANH_AN) ?
    pn_filtered AS (
        SELECT /*+ MATERIALIZE */
               rt.PHAM_NHAN_ID                         AS ID,
               rt.LL_HO_TEN,
               rt.LL_NGAY_SINH,
               rt.LL_DM_GIOI_TINH_ID,
               rt.LL_PHAN_TRAI_ID,
               rt.LL_PHAN_DOI_ID,
               rt.LL_DIA_CHI_THUONG_TRU,
               rt.LL_DIA_CHI_THUONG_TRU_PROVICE,
               rt.LL_DIA_CHI_THUONG_TRU_WARD,
               rt.LL_SO_TIEN_AN,
               rt.LL_TINH_TRANG_ID,
               rt.THA_NGAY_BAT,
               rt.THA_AN_PHAT,
               rt.THA_NGAY_DEN_TRAI,
               rt.THA_NGAY_HET_HAN,
               rt.THA_TOI_DANH_NAMES,
               rt.THOI_GIAN_DA_GIAM,
               rt.SO_LAN_GIAM,
               il.PN_ORD
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        LEFT JOIN ID_LIST il ON il.PN_ID = rt.PHAM_NHAN_ID
        WHERE rt.IS_DELETED = 0
          AND (p_pn_ids IS NULL OR il.PN_ID IS NOT NULL)
          AND (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = p_phan_doi_id)
--        AND (p_tinh_trang_id IS NULL OR rt.LL_TINH_TRANG_ID = p_tinh_trang_id)
--        AND (p_ho_ten IS NULL OR TRIM(p_ho_ten) = ''
--             OR UPPER(rt.LL_HO_TEN) LIKE '%' || UPPER(TRIM(p_ho_ten)) || '%')
    ),

    -- ?? 3. X?p lo?i t?t c? n?m (n?m k? ?ang m?) ?????????????????????
    xl_all AS (
        SELECT xl.PHAM_NHAN_ID,
               SUBSTR(
                   RTRIM(
                       XMLAGG(
                           XMLELEMENT(
                               e,
                               TO_NCHAR(xl.XEP_LOAI_NAM) || TO_NCHAR(': ') ||
                               RTRIM(
                                   CASE WHEN xl_q1.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q1: ') || xl_q1.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END ||
                                   CASE WHEN xl_q2.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q2: ') || xl_q2.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END ||
                                   CASE WHEN xl_q3.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q3: ') || xl_q3.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END ||
                                   CASE WHEN xl_q4.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q4: ') || xl_q4.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END,
                                   '; '
                               )
                           )
                           ORDER BY xl.XEP_LOAI_NAM
                       ).extract('//text()').GETSTRINGVAL(),
                       CHR(10)
                   ), 1, 4000
               ) AS XEP_LOAI_TAT_CA_NAM
        FROM XEP_LOAIS xl
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q1 ON xl.XEP_LOAI_QUY_I   = xl_q1.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q2 ON xl.XEP_LOAI_QUY_II  = xl_q2.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q3 ON xl.XEP_LOAI_QUY_III = xl_q3.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q4 ON xl.XEP_LOAI_QUY_IV  = xl_q4.ID
        WHERE xl.XEP_LOAI_NAM = p_nam_xl
--        (
--              SELECT NAM_XEP_LOAI
--              FROM MO_KY_XEP_LOAI_CAI_TAOS
--              WHERE TRANG_THAI = 1
--                AND IS_DELETED = 0
--                FETCH FIRST ROW ONLY 
--          )
      	 	AND xl.PHAM_NHAN_ID IN (SELECT ID FROM pn_filtered)

          and xl.IS_DELETED = 0 
        GROUP BY xl.PHAM_NHAN_ID
    ),

    -- ?? 4. T?ng h?p HPBS ?????????????????????????????????????????????
    hpbs_agg AS (
        SELECT phpbs.HPBS_MA_PHAM_NHAN,
               SUM(NVL(phpbs.HPBS_TONG_TIEN_PHAT,   0)) AS TONG_TIEN_PHAT,
               SUM(NVL(phpbs.HPBS_TONG_TIEN_CON_LAI, 0)) AS TONG_CON_LAI
        FROM PN_HINH_PHAT_BO_SUNGS phpbs
        WHERE NVL(phpbs.IS_DELETED, 0) = 0
          AND phpbs.HPBS_MA_PHAM_NHAN IN (SELECT ID FROM pn_filtered)
        GROUP BY phpbs.HPBS_MA_PHAM_NHAN
    )

    -- ?? 5. SELECT cu?i ????????????????????????????????????????????????
    SELECT
        dpd.PD_TEN                                                  AS "PhanDoi",
        dpt.PT_TEN                                                  AS "PhanTrai",
        pnf.ID                                                      AS "Id",
        pnf.LL_HO_TEN                                               AS "HoTen",
        SUBSTR(pnf.LL_NGAY_SINH, -4)                                AS "NamSinh",
        dgt.GT_TEN                                                  AS "GioiTinh",
        CASE
            WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
              OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
              OR NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U''), U'')
                || CASE
                       WHEN NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                THEN U', ' || dxp.XP_TEN ELSE dxp.XP_TEN END
                       ELSE U''
                   END
                || CASE
                       WHEN NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                  OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
                                THEN U', ' || dttp.TTP_TEN ELSE dttp.TTP_TEN END
                       ELSE U''
                   END
            )
            ELSE NULL
        END                                                         AS "DiaChiThuongTru",
        TRIM(pnf.THA_TOI_DANH_NAMES)                               AS "ToiDanh",
        pnf.LL_SO_TIEN_AN                                           AS "SoTienAn",
        TO_NCHAR(pnf.THA_NGAY_BAT,      'DD/MM/YYYY')              AS "NgayBat",
        TO_NCHAR(pnf.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY')              AS "NgayDenTrai",
        TO_NCHAR(pnf.THA_NGAY_HET_HAN,  'DD/MM/YYYY')              AS "NgayHetHan",
        pnf.THA_AN_PHAT                                             AS "AnPhat",
        -- DaGiam: SO_LAN_GIAM + THOI_GIAN_DA_GIAM t? RT (thay scalar subquery FN_PARSE_THOI_GIAN_TEXT×N)
        CASE
            WHEN NVL(pnf.SO_LAN_GIAM, 0) = 0
            THEN TO_NCHAR(U'Không')
            WHEN NVL(TO_NCHAR(pnf.THOI_GIAN_DA_GIAM), U'0') = U'0' OR pnf.THOI_GIAN_DA_GIAM IS NULL
            THEN TO_NCHAR(pnf.SO_LAN_GIAM) || TO_NCHAR(U' l?n')
            ELSE TO_NCHAR(pnf.SO_LAN_GIAM) || TO_NCHAR(U' l?n = ') || TO_NCHAR(pnf.THOI_GIAN_DA_GIAM)
        END                                                         AS "DaGiam",
        xl_all.XEP_LOAI_TAT_CA_NAM                                  AS "XepLoaiCacNam",
        QLPN.FN_GET_LIET_KE_HPBS(pnf.ID)                           AS "HPBS",
        NULL                                                        AS "GhiChu"
    FROM pn_filtered pnf
    LEFT JOIN DM_GIOI_TINHS dgt
        ON pnf.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_PHAN_TRAIS dpt
        ON pnf.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_PHAN_DOIS dpd
        ON pnf.LL_PHAN_DOI_ID = dpd.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp
        ON pnf.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp.ID
       AND NVL(dttp.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp
        ON pnf.LL_DIA_CHI_THUONG_TRU_WARD = dxp.ID
       AND NVL(dxp.IS_DELETED, 0) = 0
    LEFT JOIN xl_all ON pnf.ID = xl_all.PHAM_NHAN_ID
    LEFT JOIN hpbs_agg hpbs ON pnf.ID = hpbs.HPBS_MA_PHAM_NHAN
--  Các filter sau khi uncomment, thêm t?i pn_filtered ho?c WHERE bên d??i:
--    AND (p_tinh_trang_id IS NULL OR pnf.LL_TINH_TRANG_ID = p_tinh_trang_id)
--    AND (p_doi_tuong_id IS NULL OR pnf.THA_DOI_TUONG = p_doi_tuong_id)
    ORDER BY
        CASE WHEN p_pn_ids IS NULL     THEN pnf.ID      ELSE NULL END,
        CASE WHEN p_pn_ids IS NOT NULL THEN pnf.PN_ORD  ELSE NULL END;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_DS_XLCT_HPBS;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_XLCT_QUY_1
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_XLCT_QUY_1" (
    p_pn_ids            IN VARCHAR2  DEFAULT NULL,
    p_nam_xep_loai      IN NUMBER,
    p_ngay_den_trai_tu  IN DATE      DEFAULT NULL,
    p_dieu_kien_id      IN NUMBER    DEFAULT NULL,
    p_ky_da_xep_loai    IN VARCHAR2  DEFAULT NULL,
    p_doi_tuong_id      IN NUMBER    DEFAULT NULL,
    p_ho_ten            IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi_id       IN NUMBER    DEFAULT NULL,
    p_tinh_trang_id     IN NUMBER    DEFAULT NULL,
    p_loai_xep_loai_id  IN NUMBER    DEFAULT NULL,
    p_hpbs_id           IN NUMBER    DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    -- ?? 1. Parse danh sách ID ?????????????????????????????????????????
    ID_LIST AS (
        SELECT /*+ MATERIALIZE */ PN_ID, MIN(PN_ORD) AS PN_ORD
        FROM (
            SELECT LEVEL AS PN_ORD,
                   TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
            FROM DUAL
            CONNECT BY LEVEL <= CASE
                    WHEN p_pn_ids IS NULL THEN 0
                    WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                    ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                END
              AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
        )
        GROUP BY PN_ID
    ),

    -- ?? 2. Materialized ID set cho filter hpbs/bl ????????????????????
    pn_filtered AS (
        SELECT /*+ MATERIALIZE */ rt.PHAM_NHAN_ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        WHERE rt.IS_DELETED = 0
          AND (p_pn_ids IS NULL OR EXISTS (SELECT 1 FROM ID_LIST il WHERE il.PN_ID = rt.PHAM_NHAN_ID))
    ),

    -- ?? 3. HPBS t?ng h?p (filter theo pn_filtered) ???????????????????
    hpbs_agg AS (
        SELECT phpbs.HPBS_MA_PHAM_NHAN,
               SUM(phpbs.HPBS_TONG_TIEN_PHAT)                         AS TONG_TIEN_PHAT,
               SUM(phpbs.HPBS_TONG_TIEN_PHAT)
                   - SUM(NVL(phpbs.HPBS_TONG_TIEN_CON_LAI, 0))        AS DA_NOP,
               CASE WHEN SUM(phpbs.HPBS_TONG_TIEN_PHAT) = 0 THEN 1
                    WHEN SUM(phpbs.HPBS_TONG_TIEN_PHAT)
                       - SUM(NVL(phpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0 THEN 1
                    ELSE 2
               END AS HPBS_TINH_TRANG
        FROM PN_HINH_PHAT_BO_SUNGS phpbs
        WHERE NVL(phpbs.IS_DELETED, 0) = 0
          AND phpbs.HPBS_MA_PHAM_NHAN IN (SELECT PHAM_NHAN_ID FROM pn_filtered)
        GROUP BY phpbs.HPBS_MA_PHAM_NHAN
    ),

    -- ?? 4. Biên lai t?ng h?p (filter theo pn_filtered) ???????????????
    bl_agg AS (
        SELECT phpbs.HPBS_MA_PHAM_NHAN, SUM(bl.BL_SO_TIEN) AS TONG_TIEN_NOP
        FROM PN_BIENLAIES bl
        JOIN PN_HINH_PHAT_BO_SUNGS phpbs ON bl.HPBS_ID = phpbs.ID
        WHERE phpbs.HPBS_MA_PHAM_NHAN IN (SELECT PHAM_NHAN_ID FROM pn_filtered)
--      WHERE (EXTRACT(MONTH FROM bl.BL_NGAY_NOP) = 12 AND EXTRACT(YEAR FROM bl.BL_NGAY_NOP) = p_nam_xep_loai - 1)
--         OR (EXTRACT(MONTH FROM bl.BL_NGAY_NOP) IN (1, 2) AND EXTRACT(YEAR FROM bl.BL_NGAY_NOP) = p_nam_xep_loai)
        GROUP BY phpbs.HPBS_MA_PHAM_NHAN
    )

    -- ?? 5. SELECT cu?i ????????????????????????????????????????????????
    SELECT
        rt.LL_HO_TEN                                                AS "HoTen",
        rt.LL_NGAY_SINH                                             AS "NgaySinh",
        dgt.GT_TEN                                                  AS "GioiTinh",
        SUBSTR(rt.LL_NGAY_SINH, -4)                                 AS "NamSinh",
        CASE
            WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
              OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
              OR NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U''), U'')
                || CASE
                       WHEN NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                THEN U', ' || dxp.XP_TEN ELSE dxp.XP_TEN END
                       ELSE U''
                   END
                || CASE
                       WHEN NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                  OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
                                THEN U', ' || dttp.TTP_TEN ELSE dttp.TTP_TEN END
                       ELSE U''
                   END
            )
            ELSE NULL
        END                                                         AS "DiaChiThuongTru",
        TRIM(rt.THA_TOI_DANH_NAMES)                                 AS "ToiDanh",
        TO_NCHAR(rt.THA_NGAY_BAT, 'DD/MM/YYYY')                    AS "NgayBat",
        rt.THA_AN_PHAT                                              AS "AnPhat",
        CASE WHEN rt.LL_SO_TIEN_AN IS NULL OR rt.LL_SO_TIEN_AN = U'0' THEN NULL
             ELSE rt.LL_SO_TIEN_AN
        END                                                         AS "TienAn",
        CASE WHEN rt.LL_SO_TIEN_SU IS NULL OR rt.LL_SO_TIEN_SU = U'0' THEN NULL
             ELSE rt.LL_SO_TIEN_SU
        END                                                         AS "TienSu",
        TO_NCHAR(rt.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY')               AS "NgayDenTrai",
        NVL(hpbs_agg.TONG_TIEN_PHAT, 0)                            AS "TongTienPhat",
        NVL(bl_agg.TONG_TIEN_NOP, 0)                               AS "TongTienNop",
        xl_canam_truoc.XLCT_TEN                                     AS "KqctCaNam",
        xl_t12.XLCT_TEN                                             AS "KqctThang12",
        xl_t1.XLCT_TEN                                              AS "KqctThang1",
        xl_t2.XLCT_TEN                                              AS "KqctThang2",
        NULL                                                        AS "QuanGiaoDeNghi",
        NULL                                                        AS "TieuBanDuyet",
        xl_q1.XLCT_TEN                                                         AS "HoiDongDuyet"
    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
    LEFT JOIN ID_LIST il ON il.PN_ID = rt.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt         ON rt.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_PHAN_DOIS dpd          ON rt.LL_PHAN_DOI_ID = dpd.ID
    LEFT JOIN hpbs_agg                  ON rt.PHAM_NHAN_ID = hpbs_agg.HPBS_MA_PHAM_NHAN
    LEFT JOIN bl_agg                    ON rt.PHAM_NHAN_ID = bl_agg.HPBS_MA_PHAM_NHAN
    LEFT JOIN DM_TINH_THANH_PHO dttp
        ON rt.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp.ID
       AND NVL(dttp.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp
        ON rt.LL_DIA_CHI_THUONG_TRU_WARD = dxp.ID
       AND NVL(dxp.IS_DELETED, 0) = 0
    -- XL n?m tr??c n?m x?p lo?i
    LEFT JOIN XEP_LOAIS xl_truoc
        ON rt.PHAM_NHAN_ID = xl_truoc.PHAM_NHAN_ID
       AND xl_truoc.XEP_LOAI_NAM = p_nam_xep_loai - 1
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_canam_truoc ON xl_truoc.XEP_LOAI_CA_NAM  = xl_canam_truoc.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_t12         ON xl_truoc.XEP_LOAI_THANG_12 = xl_t12.ID
    -- XL n?m x?p lo?i
    LEFT JOIN XEP_LOAIS xl_hientai
        ON rt.PHAM_NHAN_ID = xl_hientai.PHAM_NHAN_ID
       AND xl_hientai.XEP_LOAI_NAM = p_nam_xep_loai
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_t1 ON xl_hientai.XEP_LOAI_THANG_1 = xl_t1.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_t2 ON xl_hientai.XEP_LOAI_THANG_2 = xl_t2.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q1 ON xl_hientai.XEP_LOAI_QUY_I = xl_q1.ID
    WHERE rt.IS_DELETED = 0
      AND (p_pn_ids IS NULL OR il.PN_ID IS NOT NULL)
    ORDER BY
        CASE WHEN p_pn_ids IS NULL     THEN rt.PHAM_NHAN_ID ELSE NULL END,
        CASE WHEN p_pn_ids IS NOT NULL THEN il.PN_ORD       ELSE NULL END;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_DS_XLCT_QUY_1;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_XLCT_QUY_2
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_XLCT_QUY_2" (
    p_pn_ids            IN VARCHAR2  DEFAULT NULL,
    p_nam_xep_loai      IN NUMBER,
    p_ngay_den_trai_tu  IN DATE      DEFAULT NULL,
    p_dieu_kien_id      IN NUMBER    DEFAULT NULL,
    p_ky_da_xep_loai    IN VARCHAR2  DEFAULT NULL,
    p_doi_tuong_id      IN NUMBER    DEFAULT NULL,
    p_ho_ten            IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi_id       IN NUMBER    DEFAULT NULL,
    p_tinh_trang_id     IN NUMBER    DEFAULT NULL,
    p_loai_xep_loai_id  IN NUMBER    DEFAULT NULL,
    p_hpbs_id           IN NUMBER    DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    -- ?? 1. Parse danh sách ID ?????????????????????????????????????????
    ID_LIST AS (
        SELECT /*+ MATERIALIZE */ PN_ID, MIN(PN_ORD) AS PN_ORD
        FROM (
            SELECT LEVEL AS PN_ORD,
                   TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
            FROM DUAL
            CONNECT BY LEVEL <= CASE
                    WHEN p_pn_ids IS NULL THEN 0
                    WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                    ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                END
              AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
        )
        GROUP BY PN_ID
    ),

    -- ?? 2. Materialized ID set cho filter hpbs/bl ????????????????????
    pn_filtered AS (
        SELECT /*+ MATERIALIZE */ rt.PHAM_NHAN_ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        WHERE rt.IS_DELETED = 0
          AND (p_pn_ids IS NULL OR EXISTS (SELECT 1 FROM ID_LIST il WHERE il.PN_ID = rt.PHAM_NHAN_ID))
    ),

    -- ?? 3. HPBS t?ng h?p (filter theo pn_filtered) ???????????????????
    hpbs_agg AS (
        SELECT phpbs.HPBS_MA_PHAM_NHAN,
               SUM(phpbs.HPBS_TONG_TIEN_PHAT)                         AS TONG_TIEN_PHAT,
               CASE WHEN SUM(phpbs.HPBS_TONG_TIEN_PHAT) = 0 THEN 1
                    WHEN SUM(phpbs.HPBS_TONG_TIEN_PHAT)
                       - SUM(NVL(phpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0 THEN 1
                    ELSE 2
               END AS HPBS_TINH_TRANG
        FROM PN_HINH_PHAT_BO_SUNGS phpbs
        WHERE NVL(phpbs.IS_DELETED, 0) = 0
          AND phpbs.HPBS_MA_PHAM_NHAN IN (SELECT PHAM_NHAN_ID FROM pn_filtered)
        GROUP BY phpbs.HPBS_MA_PHAM_NHAN
    ),

    -- ?? 4. Biên lai Quý 2 (tháng 3,4,5 — filter theo pn_filtered) ????
    bl_agg AS (
        SELECT phpbs.HPBS_MA_PHAM_NHAN, SUM(bl.BL_SO_TIEN) AS TONG_TIEN_NOP
        FROM PN_BIENLAIES bl
        JOIN PN_HINH_PHAT_BO_SUNGS phpbs ON bl.HPBS_ID = phpbs.ID
        WHERE phpbs.HPBS_MA_PHAM_NHAN IN (SELECT PHAM_NHAN_ID FROM pn_filtered)
--      AND EXTRACT(MONTH FROM bl.BL_NGAY_NOP) IN (3, 4, 5)
--      AND EXTRACT(YEAR  FROM bl.BL_NGAY_NOP) = p_nam_xep_loai
        GROUP BY phpbs.HPBS_MA_PHAM_NHAN
    )

    -- ?? 5. SELECT cu?i ????????????????????????????????????????????????
    SELECT
        rt.LL_HO_TEN                                                AS "HoTen",
        rt.LL_NGAY_SINH                                             AS "NgaySinh",
        dgt.GT_TEN                                                  AS "GioiTinh",
        SUBSTR(rt.LL_NGAY_SINH, -4)                                 AS "NamSinh",
        CASE
            WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
              OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
              OR NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U''), U'')
                || CASE
                       WHEN NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                THEN U', ' || dxp.XP_TEN ELSE dxp.XP_TEN END
                       ELSE U''
                   END
                || CASE
                       WHEN NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                  OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
                                THEN U', ' || dttp.TTP_TEN ELSE dttp.TTP_TEN END
                       ELSE U''
                   END
            )
            ELSE NULL
        END                                                         AS "DiaChiThuongTru",
        TRIM(rt.THA_TOI_DANH_NAMES)                                 AS "ToiDanh",
        TO_NCHAR(rt.THA_NGAY_BAT, 'DD/MM/YYYY')                    AS "NgayBat",
        rt.THA_AN_PHAT                                              AS "AnPhat",
        CASE WHEN rt.LL_SO_TIEN_AN IS NULL OR rt.LL_SO_TIEN_AN = U'0' THEN NULL
             ELSE rt.LL_SO_TIEN_AN
        END                                                         AS "TienAn",
        CASE WHEN rt.LL_SO_TIEN_SU IS NULL OR rt.LL_SO_TIEN_SU = U'0' THEN NULL
             ELSE rt.LL_SO_TIEN_SU
        END                                                         AS "TienSu",
        TO_NCHAR(rt.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY')               AS "NgayDenTrai",
        NVL(hpbs_agg.TONG_TIEN_PHAT, 0)                            AS "TongTienPhat",
        NVL(bl_agg.TONG_TIEN_NOP, 0)                               AS "TongTienNop",
        xl_q1.XLCT_TEN                                              AS "KqctQuy1",
        xl_t3.XLCT_TEN                                              AS "KqctThang3",
        xl_t4.XLCT_TEN                                              AS "KqctThang4",
        xl_t5.XLCT_TEN                                              AS "KqctThang5",
        NULL                                                        AS "QuanGiaoDeNghi_Quy2",
        NULL                                                        AS "QuanGiaoDeNghi_6thang",
        NULL                                                        AS "TieuBanDuyet_Quy2",
        NULL                                                        AS "TieuBanDuyet_6thang",
        xl_q2.XLCT_TEN                                                       AS "HoiDongTraiDuyet_Quy2",
        xl_6t.XLCT_TEN                                                        AS "HoiDongTraiDuyet_6thang"
    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
    LEFT JOIN ID_LIST il ON il.PN_ID = rt.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt         ON rt.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN hpbs_agg                  ON rt.PHAM_NHAN_ID = hpbs_agg.HPBS_MA_PHAM_NHAN
    LEFT JOIN bl_agg                    ON rt.PHAM_NHAN_ID = bl_agg.HPBS_MA_PHAM_NHAN
    LEFT JOIN XEP_LOAIS xl
        ON rt.PHAM_NHAN_ID = xl.PHAM_NHAN_ID
       AND xl.XEP_LOAI_NAM = p_nam_xep_loai
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q1 ON xl.XEP_LOAI_QUY_I   = xl_q1.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_t3 ON xl.XEP_LOAI_THANG_3 = xl_t3.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_t4 ON xl.XEP_LOAI_THANG_4 = xl_t4.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_t5 ON xl.XEP_LOAI_THANG_5 = xl_t5.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q2 ON xl.XEP_LOAI_QUY_II = xl_q2.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_6t ON xl.XEP_LOAI_6_THANG_DAU_NAM  = xl_6t.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp
        ON rt.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp.ID
       AND NVL(dttp.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp
        ON rt.LL_DIA_CHI_THUONG_TRU_WARD = dxp.ID
       AND NVL(dxp.IS_DELETED, 0) = 0
    WHERE rt.IS_DELETED = 0
      AND (p_pn_ids IS NULL OR il.PN_ID IS NOT NULL)
--  AND (p_ho_ten IS NULL OR TRIM(p_ho_ten) = U'' OR UPPER(rt.LL_HO_TEN) LIKE U'%'||UPPER(TRIM(p_ho_ten))||U'%')
--  AND (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = p_phan_doi_id)
--  AND (p_hpbs_id IS NULL OR hpbs_agg.HPBS_TINH_TRANG = p_hpbs_id)
    ORDER BY
        CASE WHEN p_pn_ids IS NULL     THEN rt.PHAM_NHAN_ID ELSE NULL END,
        CASE WHEN p_pn_ids IS NOT NULL THEN il.PN_ORD       ELSE NULL END;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_DS_XLCT_QUY_2;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DS_XLCT_QUY_3
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_XLCT_QUY_3" (
    p_pn_ids            IN VARCHAR2  DEFAULT NULL,
    p_nam_xep_loai      IN NUMBER,
    p_ngay_den_trai_tu  IN DATE      DEFAULT NULL,
    p_dieu_kien_id      IN NUMBER    DEFAULT NULL,
    p_ky_da_xep_loai    IN VARCHAR2  DEFAULT NULL,
    p_doi_tuong_id      IN NUMBER    DEFAULT NULL,
    p_ho_ten            IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi_id       IN NUMBER    DEFAULT NULL,
    p_tinh_trang_id     IN NUMBER    DEFAULT NULL,
    p_loai_xep_loai_id  IN NUMBER    DEFAULT NULL,
    p_hpbs_id           IN NUMBER    DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    -- ?? 1. Parse danh sách ID ?????????????????????????????????????????
    ID_LIST AS (
        SELECT /*+ MATERIALIZE */ PN_ID, MIN(PN_ORD) AS PN_ORD
        FROM (
            SELECT LEVEL AS PN_ORD,
                   TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
            FROM DUAL
            CONNECT BY LEVEL <= CASE
                    WHEN p_pn_ids IS NULL THEN 0
                    WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                    ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                END
              AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
        )
        GROUP BY PN_ID
    ),

    -- ?? 2. Materialized ID set cho filter hpbs/bl ????????????????????
    pn_filtered AS (
        SELECT /*+ MATERIALIZE */ rt.PHAM_NHAN_ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        WHERE rt.IS_DELETED = 0
          AND (p_pn_ids IS NULL OR EXISTS (SELECT 1 FROM ID_LIST il WHERE il.PN_ID = rt.PHAM_NHAN_ID))
    ),

    -- ?? 3. HPBS t?ng h?p (filter theo pn_filtered) ???????????????????
    hpbs_agg AS (
        SELECT phpbs.HPBS_MA_PHAM_NHAN,
               SUM(phpbs.HPBS_TONG_TIEN_PHAT)                         AS TONG_TIEN_PHAT,
               CASE WHEN SUM(phpbs.HPBS_TONG_TIEN_PHAT) = 0 THEN 1
                    WHEN SUM(phpbs.HPBS_TONG_TIEN_PHAT)
                       - SUM(NVL(phpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0 THEN 1
                    ELSE 2
               END AS HPBS_TINH_TRANG
        FROM PN_HINH_PHAT_BO_SUNGS phpbs
        WHERE NVL(phpbs.IS_DELETED, 0) = 0
          AND phpbs.HPBS_MA_PHAM_NHAN IN (SELECT PHAM_NHAN_ID FROM pn_filtered)
        GROUP BY phpbs.HPBS_MA_PHAM_NHAN
    ),

    -- ?? 4. Biên lai Quý 3 (tháng 6,7,8 — filter theo pn_filtered) ????
    bl_agg AS (
        SELECT phpbs.HPBS_MA_PHAM_NHAN, SUM(bl.BL_SO_TIEN) AS TONG_TIEN_NOP
        FROM PN_BIENLAIES bl
        JOIN PN_HINH_PHAT_BO_SUNGS phpbs ON bl.HPBS_ID = phpbs.ID
        WHERE phpbs.HPBS_MA_PHAM_NHAN IN (SELECT PHAM_NHAN_ID FROM pn_filtered)
--      AND EXTRACT(MONTH FROM bl.BL_NGAY_NOP) IN (6, 7, 8)
--      AND EXTRACT(YEAR  FROM bl.BL_NGAY_NOP) = p_nam_xep_loai
        GROUP BY phpbs.HPBS_MA_PHAM_NHAN
    )

    -- ?? 5. SELECT cu?i ????????????????????????????????????????????????
    SELECT
        rt.LL_HO_TEN                                                AS "HoTen",
        rt.LL_NGAY_SINH                                             AS "NgaySinh",
        dgt.GT_TEN                                                  AS "GioiTinh",
        SUBSTR(rt.LL_NGAY_SINH, -4)                                 AS "NamSinh",
        CASE
            WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
              OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
              OR NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U''), U'')
                || CASE
                       WHEN NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                THEN U', ' || dxp.XP_TEN ELSE dxp.XP_TEN END
                       ELSE U''
                   END
                || CASE
                       WHEN NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                  OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
                                THEN U', ' || dttp.TTP_TEN ELSE dttp.TTP_TEN END
                       ELSE U''
                   END
            )
            ELSE NULL
        END                                                         AS "DiaChiThuongTru",
        TRIM(rt.THA_TOI_DANH_NAMES)                                 AS "ToiDanh",
        TO_NCHAR(rt.THA_NGAY_BAT, 'DD/MM/YYYY')                    AS "NgayBat",
        rt.THA_AN_PHAT                                              AS "AnPhat",
        CASE WHEN rt.LL_SO_TIEN_AN IS NULL OR rt.LL_SO_TIEN_AN = U'0' THEN NULL
             ELSE rt.LL_SO_TIEN_AN
        END                                                         AS "TienAn",
        CASE WHEN rt.LL_SO_TIEN_SU IS NULL OR rt.LL_SO_TIEN_SU = U'0' THEN NULL
             ELSE rt.LL_SO_TIEN_SU
        END                                                         AS "TienSu",
        TO_NCHAR(rt.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY')               AS "NgayDenTrai",
        NVL(hpbs_agg.TONG_TIEN_PHAT, 0)                            AS "TongTienPhat",
        NVL(bl_agg.TONG_TIEN_NOP, 0)                               AS "TongTienNop",
        xl_q1.XLCT_TEN                                              AS "KqctQuy1",
        xl_q2.XLCT_TEN                                              AS "KqctQuy2",
        xl_6dau.XLCT_TEN                                            AS "Kqct6ThangDau",
        xl_t6.XLCT_TEN                                              AS "KqctThang6",
        xl_t7.XLCT_TEN                                              AS "KqctThang7",
        xl_t8.XLCT_TEN                                              AS "KqctThang8",
        NULL                                                        AS "QuanGiaoDeNghi",
        NULL                                                        AS "TieuBanDuyet",
        xl_q3.XLCT_TEN                                                        AS "HoiDongDuyet"
    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
    LEFT JOIN ID_LIST il ON il.PN_ID = rt.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt         ON rt.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN hpbs_agg                  ON rt.PHAM_NHAN_ID = hpbs_agg.HPBS_MA_PHAM_NHAN
    LEFT JOIN bl_agg                    ON rt.PHAM_NHAN_ID = bl_agg.HPBS_MA_PHAM_NHAN
    LEFT JOIN XEP_LOAIS xl
        ON rt.PHAM_NHAN_ID = xl.PHAM_NHAN_ID
       AND xl.XEP_LOAI_NAM = p_nam_xep_loai
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q1   ON xl.XEP_LOAI_QUY_I           = xl_q1.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q2   ON xl.XEP_LOAI_QUY_II          = xl_q2.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_6dau ON xl.XEP_LOAI_6_THANG_DAU_NAM = xl_6dau.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_t6   ON xl.XEP_LOAI_THANG_6         = xl_t6.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_t7   ON xl.XEP_LOAI_THANG_7         = xl_t7.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_t8   ON xl.XEP_LOAI_THANG_8         = xl_t8.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q3 ON xl.XEP_LOAI_QUY_III = xl_q3.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp
        ON rt.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp.ID
       AND NVL(dttp.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp
        ON rt.LL_DIA_CHI_THUONG_TRU_WARD = dxp.ID
       AND NVL(dxp.IS_DELETED, 0) = 0
    WHERE rt.IS_DELETED = 0
      AND (p_pn_ids IS NULL OR il.PN_ID IS NOT NULL)
--  AND (p_ho_ten IS NULL OR TRIM(p_ho_ten) = U'' OR UPPER(rt.LL_HO_TEN) LIKE U'%'||UPPER(TRIM(p_ho_ten))||U'%')
--  AND (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = p_phan_doi_id)
--  AND (p_hpbs_id IS NULL OR hpbs_agg.HPBS_TINH_TRANG = p_hpbs_id)
    ORDER BY
        CASE WHEN p_pn_ids IS NULL     THEN rt.PHAM_NHAN_ID ELSE NULL END,
        CASE WHEN p_pn_ids IS NOT NULL THEN il.PN_ORD       ELSE NULL END;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_DS_XLCT_QUY_3;



