  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_XLCT_QUY_4" (
    p_pn_ids            IN VARCHAR2  DEFAULT NULL,
    p_nam_xep_loai      IN NUMBER,
    p_ngay_den_trai_tu  IN DATE      DEFAULT NULL,
    p_dieu_kien_id      IN NUMBER    DEFAULT NULL,
    p_ky_da_xep_loai    IN VARCHAR2  DEFAULT NULL,
    p_doi_tuong_id      IN NUMBER    DEFAULT NULL,
    p_ho_ten            IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi_id       IN NUMBER    DEFAULT NULL,
    p_tinh_trang_id     IN NUMBER    DEFAULT NULL,
    p_loai_xep_loai_id  IN NUMBER    DEFAULT NULL,
    p_hpbs_id           IN NUMBER    DEFAULT NULL
)
AS
