        FROM PN_HINH_PHAT_BO_SUNGS phpbs
        WHERE NVL(phpbs.IS_DELETED, 0) = 0
          AND phpbs.HPBS_MA_PHAM_NHAN IN (SELECT PHAM_NHAN_ID FROM pn_filtered)
        GROUP BY phpbs.HPBS_MA_PHAM_NHAN
    ),

    -- ?? 4. Biên lai Quý 4 (tháng 9,10,11 — filter theo pn_filtered) ??
    bl_agg AS (
        SELECT phpbs.HPBS_MA_PHAM_NHAN, SUM(bl.BL_SO_TIEN) AS TONG_TIEN_NOP
        FROM PN_BIENLAIES bl
        JOIN PN_HINH_PHAT_BO_SUNGS phpbs ON bl.HPBS_ID = phpbs.ID
        WHERE phpbs.HPBS_MA_PHAM_NHAN IN (SELECT PHAM_NHAN_ID FROM pn_filtered)
--      AND EXTRACT(MONTH FROM bl.BL_NGAY_NOP) IN (9, 10, 11)
--      AND EXTRACT(YEAR  FROM bl.BL_NGAY_NOP) = p_nam_xep_loai
        GROUP BY phpbs.HPBS_MA_PHAM_NHAN
    )

    -- ?? 5. SELECT cu?i ????????????????????????????????????????????????
    SELECT
