             ELSE rt.LL_SO_TIEN_SU
        END                                                         AS "TienSu",
        TO_NCHAR(rt.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY')               AS "NgayDenTrai",
        NVL(hpbs_agg.TONG_TIEN_PHAT, 0)                            AS "TongTienPhat",
        NVL(bl_agg.TONG_TIEN_NOP, 0)                               AS "TongTienNop",
        xl_6dau.XLCT_TEN                                            AS "Kqct6ThangDau",
        xl_q3.XLCT_TEN                                              AS "KqctQuy3",
        xl_t8.XLCT_TEN                                              AS "KqctThang8",
        xl_t9.XLCT_TEN                                              AS "KqctThang9",
        xl_t10.XLCT_TEN                                             AS "KqctThang10",
        xl_t11.XLCT_TEN                                             AS "KqctThang11",
        NULL                                                        AS "QuanGiaoDeNghi_Q4",
        NULL                                                        AS "QuanGiaoDeNghi_6ThangCuoiNam",
        NULL                                                        AS "QuanGiaoDeNghi_CuoiNam",
        NULL                                                        AS "TieuBanDuyet_Q4",
        NULL                                                        AS "TieuBanDuyet_6ThangCuoiNam",
        NULL                                                        AS "TieuBanDuyet_CuoiNam",
        xl_q4.XLCT_TEN                                                       AS "HoiDongDuyet_Q4",
        xl_6t.XLCT_TEN                                                        AS "HoiDongDuyet_6ThangCuoiNam",
        xl_cn.XLCT_TEN                                                        AS "HoiDongDuyet_CuoiNam"
    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
    LEFT JOIN ID_LIST il ON il.PN_ID = rt.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt         ON rt.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN hpbs_agg                  ON rt.PHAM_NHAN_ID = hpbs_agg.HPBS_MA_PHAM_NHAN
    LEFT JOIN bl_agg                    ON rt.PHAM_NHAN_ID = bl_agg.HPBS_MA_PHAM_NHAN
    LEFT JOIN XEP_LOAIS xl
        ON rt.PHAM_NHAN_ID = xl.PHAM_NHAN_ID
       AND xl.XEP_LOAI_NAM = p_nam_xep_loai
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_6dau ON xl.XEP_LOAI_6_THANG_DAU_NAM = xl_6dau.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q3   ON xl.XEP_LOAI_QUY_III         = xl_q3.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_t8   ON xl.XEP_LOAI_THANG_8         = xl_t8.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_t9   ON xl.XEP_LOAI_THANG_9         = xl_t9.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_t10  ON xl.XEP_LOAI_THANG_10        = xl_t10.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_t11  ON xl.XEP_LOAI_THANG_11        = xl_t11.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q4  ON xl.XEP_LOAI_QUY_IV         = xl_q4.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_6t  ON xl.XEP_LOAI_6_THANG_CUOI_NAM   = xl_6t.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_cn  ON xl.XEP_LOAI_CA_NAM          = xl_cn.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp
        ON rt.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp.ID
       AND NVL(dttp.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp
        ON rt.LL_DIA_CHI_THUONG_TRU_WARD = dxp.ID
       AND NVL(dxp.IS_DELETED, 0) = 0
    WHERE rt.IS_DELETED = 0
      AND (p_pn_ids IS NULL OR il.PN_ID IS NOT NULL)
--  AND (p_ho_ten IS NULL OR TRIM(p_ho_ten) = U'' OR UPPER(rt.LL_HO_TEN) LIKE U'%'||UPPER(TRIM(p_ho_ten))||U'%')
--  AND (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = p_phan_doi_id)
--  AND (p_hpbs_id IS NULL OR hpbs_agg.HPBS_TINH_TRANG = p_hpbs_id)
    ORDER BY
        CASE WHEN p_pn_ids IS NULL     THEN rt.PHAM_NHAN_ID ELSE NULL END,
        CASE WHEN p_pn_ids IS NOT NULL THEN il.PN_ORD       ELSE NULL END;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_DS_XLCT_QUY_4;



