  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DS_XLCT_TAT_CA" (
    p_pn_ids           IN VARCHAR2 DEFAULT NULL,
    p_phan_doi_id      IN NUMBER   DEFAULT NULL,
    p_phan_trai_id     IN NUMBER   DEFAULT NULL,
    p_nam_xl           IN NUMBER   DEFAULT NULL,
    p_ky_xep_loai      IN VARCHAR2 DEFAULT NULL,
    p_tinh_trang_id    IN NUMBER   DEFAULT NULL,
    p_loai_xep_loai_id IN NUMBER   DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    -- ?? 1. Parse danh sách ID truy?n vào (CSV ? rows) ????????????????
    ID_LIST AS (
        SELECT /*+ MATERIALIZE */ PN_ID, MIN(PN_ORD) AS PN_ORD
        FROM (
            SELECT LEVEL AS PN_ORD,
                   TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
            FROM DUAL
            CONNECT BY LEVEL <= CASE
                    WHEN p_pn_ids IS NULL THEN 0
                    WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                    ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                END
              AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
        )
        GROUP BY PN_ID
    ),

    -- ?? 2. L?c XEP_LOAIS theo n?m / k? / lo?i ???????????????????????
    pn_xl AS (
        SELECT xl.PHAM_NHAN_ID,
               xl.XEP_LOAI_NAM,
               xl.XEP_LOAI_QUY_I,
               xl.XEP_LOAI_QUY_II,
               xl.XEP_LOAI_QUY_III,
               xl.XEP_LOAI_QUY_IV,
               xl.XEP_LOAI_6_THANG_DAU_NAM,
               xl.XEP_LOAI_6_THANG_CUOI_NAM,
               xl.XEP_LOAI_CA_NAM
        FROM XEP_LOAIS xl
        WHERE NVL(xl.IS_DELETED, 0) = 0
          AND (p_pn_ids IS NULL OR EXISTS (
                  SELECT 1 FROM ID_LIST il WHERE il.PN_ID = xl.PHAM_NHAN_ID
              ))
          AND (p_nam_xl IS NULL OR xl.XEP_LOAI_NAM = p_nam_xl)
          AND (
              p_loai_xep_loai_id IS NULL
              OR (
                  p_ky_xep_loai IS NOT NULL
                  AND (
                      CASE
                          WHEN p_ky_xep_loai = 'MA_XEP_LOAI_Q1'   THEN xl.XEP_LOAI_QUY_I
                          WHEN p_ky_xep_loai = 'MA_XEP_LOAI_Q2'   THEN xl.XEP_LOAI_QUY_II
                          WHEN p_ky_xep_loai = 'MA_XEP_LOAI_Q3'   THEN xl.XEP_LOAI_QUY_III
                          WHEN p_ky_xep_loai = 'MA_XEP_LOAI_Q4'   THEN xl.XEP_LOAI_QUY_IV
                          WHEN p_ky_xep_loai = '6_THANG_DAU_NAM'  THEN xl.XEP_LOAI_6_THANG_DAU_NAM
                          WHEN p_ky_xep_loai = '6_THANG_CUOI_NAM' THEN xl.XEP_LOAI_6_THANG_CUOI_NAM
                          WHEN p_ky_xep_loai = 'MA_XEP_LOAI_CA'   THEN xl.XEP_LOAI_CA_NAM
                      END = p_loai_xep_loai_id
                  )
              )
              OR (
                  p_ky_xep_loai IS NULL
                  AND (
                      xl.XEP_LOAI_QUY_I            = p_loai_xep_loai_id
                      OR xl.XEP_LOAI_QUY_II           = p_loai_xep_loai_id
                      OR xl.XEP_LOAI_QUY_III          = p_loai_xep_loai_id
                      OR xl.XEP_LOAI_QUY_IV           = p_loai_xep_loai_id
                      OR xl.XEP_LOAI_6_THANG_DAU_NAM  = p_loai_xep_loai_id
                      OR xl.XEP_LOAI_6_THANG_CUOI_NAM = p_loai_xep_loai_id
                      OR xl.XEP_LOAI_CA_NAM           = p_loai_xep_loai_id
                  )
              )
          )
    ),

    -- ?? 3. Join v?i RT table (thay PN_LAI_LICHS + PN_THI_HANH_AN) ????
    pn_filtered AS (
        SELECT /*+ MATERIALIZE */
               rt.PHAM_NHAN_ID                         AS ID,
               rt.LL_HO_TEN,
               rt.LL_NGAY_SINH,
               rt.LL_DM_GIOI_TINH_ID,
               rt.LL_PHAN_TRAI_ID,
               rt.LL_PHAN_DOI_ID,
               rt.LL_DIA_CHI_THUONG_TRU,
               rt.LL_DIA_CHI_THUONG_TRU_PROVICE,
               rt.LL_DIA_CHI_THUONG_TRU_WARD,
               rt.LL_SO_TIEN_AN,
               rt.LL_TINH_TRANG_ID,
               rt.THA_NGAY_BAT,
               rt.THA_AN_PHAT,
               rt.THA_NGAY_DEN_TRAI,
               rt.THA_NGAY_HET_HAN,
               rt.THA_GHI_CHU_DAC_BIET,
               rt.THA_TOI_DANH_NAMES,
               rt.THA_THOI_GIAN_DA_CHAP_HANH,
               rt.THA_THOI_GIAN_CON_LAI,
               rt.THOI_GIAN_DA_GIAM,
               rt.SO_LAN_GIAM,
               il.PN_ORD
        FROM pn_xl xl
        JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt
            ON rt.PHAM_NHAN_ID = xl.PHAM_NHAN_ID
           AND rt.IS_DELETED = 0
        LEFT JOIN ID_LIST il ON il.PN_ID = rt.PHAM_NHAN_ID
        WHERE 
        --(p_phan_trai_id  IS NULL OR rt.LL_PHAN_TRAI_ID  = p_phan_trai_id)
--          AND (p_phan_doi_id   IS NULL OR rt.LL_PHAN_DOI_ID   = p_phan_doi_id)
--          AND (p_tinh_trang_id IS NULL OR rt.LL_TINH_TRANG_ID = p_tinh_trang_id)
          (p_pn_ids IS NULL OR EXISTS (
                  SELECT 1 FROM ID_LIST il2 WHERE il2.PN_ID = rt.PHAM_NHAN_ID
              ))
    ),

    -- ?? 4. T?ng h?p x?p lo?i t?t c? n?m ?????????????????????????????
    xep_loai_agg AS (
        SELECT /*+ MATERIALIZE */
               xl.PHAM_NHAN_ID,
               SUBSTR(
                   RTRIM(
                       XMLAGG(
                           XMLELEMENT(
                               e,
                               TO_NCHAR(xl.XEP_LOAI_NAM) || TO_NCHAR(': ') ||
                               RTRIM(
                                   CASE WHEN xl_q1.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q1: ') || xl_q1.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END ||
                                   CASE WHEN xl_q2.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q2: ') || xl_q2.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END ||
                                   CASE WHEN xl_q3.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q3: ') || xl_q3.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END ||
                                   CASE WHEN xl_q4.XLCT_TEN IS NOT NULL THEN TO_NCHAR('Q4: ') || xl_q4.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END ||
                                   CASE WHEN xl_canam.XLCT_TEN IS NOT NULL THEN TO_NCHAR(U'C? n?m: ') || xl_canam.XLCT_TEN || TO_NCHAR('; ') ELSE TO_NCHAR('') END,
                                   '; '
                               )
                           )
                           ORDER BY xl.XEP_LOAI_NAM
                       ).EXTRACT('//text()').GETSTRINGVAL(),
                       CHR(10)
                   ), 1, 4000
               ) AS XEP_LOAI_TAT_CA_NAM
        FROM XEP_LOAIS xl
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q1    ON xl.XEP_LOAI_QUY_I   = xl_q1.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q2    ON xl.XEP_LOAI_QUY_II  = xl_q2.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q3    ON xl.XEP_LOAI_QUY_III = xl_q3.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q4    ON xl.XEP_LOAI_QUY_IV  = xl_q4.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_canam ON xl.XEP_LOAI_CA_NAM  = xl_canam.ID
        WHERE xl.PHAM_NHAN_ID IN (SELECT ID FROM pn_filtered)
          AND (p_nam_xl IS NULL OR xl.XEP_LOAI_NAM = p_nam_xl)
        GROUP BY xl.PHAM_NHAN_ID
    )

    -- ?? 5. SELECT cu?i ????????????????????????????????????????????????
    SELECT
        dpt.PT_TEN                                                   AS "PhanTrai",
        dpd.PD_TEN                                                   AS "PhanDoi",
        pnf.ID                                                       AS "Id",
        pnf.LL_HO_TEN                                                AS "HoTen",
        SUBSTR(pnf.LL_NGAY_SINH, -4)                                 AS "NamSinh",
        dgt.GT_TEN                                                   AS "GioiTinh",
        CASE
            WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
              OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
              OR NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U''), U'')
                || CASE
                       WHEN NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL THEN
                           CASE
                               WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                   THEN U', ' || dxp.XP_TEN
                               ELSE dxp.XP_TEN
                           END
                       ELSE U''
                   END
                || CASE
                       WHEN NULLIF(TRIM(dttp.TTP_TEN), U'') IS NOT NULL THEN
                           CASE
                               WHEN NULLIF(TRIM(pnf.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                 OR NULLIF(TRIM(dxp.XP_TEN), U'') IS NOT NULL
                                   THEN U', ' || dttp.TTP_TEN
                               ELSE dttp.TTP_TEN
                           END
                       ELSE U''
                   END
            )
            ELSE NULL
        END                                                          AS "DiaChiThuongTru",
        TRIM(pnf.THA_TOI_DANH_NAMES)                                AS "ToiDanh",
        CASE
            WHEN pnf.LL_SO_TIEN_AN IS NULL OR TRIM(pnf.LL_SO_TIEN_AN) = '0'
            THEN TO_NCHAR(U'Không')
            ELSE pnf.LL_SO_TIEN_AN
        END                                                          AS "SoTienAn",
        TO_NCHAR(pnf.THA_NGAY_BAT,      'DD/MM/YYYY')               AS "NgayBat",
        TO_NCHAR(pnf.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY')               AS "NgayDenTrai",
        TO_NCHAR(pnf.THA_NGAY_HET_HAN,  'DD/MM/YYYY')               AS "NgayHetHan",
        pnf.THA_AN_PHAT                                              AS "AnPhat",
        -- DaGiam: SO_LAN_GIAM + THOI_GIAN_DA_GIAM t? RT
        CASE
            WHEN NVL(pnf.SO_LAN_GIAM, 0) = 0
            THEN TO_NCHAR(U'Không')
            WHEN NVL(TO_NCHAR(pnf.THOI_GIAN_DA_GIAM), U'0') = U'0' OR pnf.THOI_GIAN_DA_GIAM IS NULL
            THEN TO_NCHAR(pnf.SO_LAN_GIAM) || TO_NCHAR(U' l?n')
            ELSE TO_NCHAR(pnf.SO_LAN_GIAM) || TO_NCHAR(U' l?n = ') || TO_NCHAR(pnf.THOI_GIAN_DA_GIAM)
        END                                                          AS "DaGiam",
        -- DaChapHanh: decode MTG_MA "YYMMDD" t? RT
        CASE
            WHEN pnf.THA_THOI_GIAN_DA_CHAP_HANH IS NULL
              OR pnf.THA_THOI_GIAN_DA_CHAP_HANH = U'000000'
            THEN TO_NCHAR(U'Không')
            ELSE TRIM(
                CASE WHEN TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_DA_CHAP_HANH, 1, 2)) > 0
                     THEN TO_NCHAR(TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_DA_CHAP_HANH, 1, 2))) || TO_NCHAR(U' n?m ')   ELSE TO_NCHAR(U'') END ||
                CASE WHEN TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_DA_CHAP_HANH, 3, 2)) > 0
                     THEN TO_NCHAR(TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_DA_CHAP_HANH, 3, 2))) || TO_NCHAR(U' tháng ') ELSE TO_NCHAR(U'') END ||
                CASE WHEN TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_DA_CHAP_HANH, 5, 2)) > 0
                     THEN TO_NCHAR(TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_DA_CHAP_HANH, 5, 2))) || TO_NCHAR(U' ngày')   ELSE TO_NCHAR(U'') END
            )
        END                                                          AS "DaChapHanh",
        -- ConLai: decode MTG_MA "YYMMDD" t? RT
        CASE
            WHEN pnf.THA_THOI_GIAN_CON_LAI IS NULL
              OR pnf.THA_THOI_GIAN_CON_LAI = U'000000'
            THEN TO_NCHAR(U'?ã h?t án')
            ELSE TRIM(
                CASE WHEN TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_CON_LAI, 1, 2)) > 0
                     THEN TO_NCHAR(TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_CON_LAI, 1, 2))) || TO_NCHAR(U' n?m ')   ELSE TO_NCHAR(U'') END ||
                CASE WHEN TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_CON_LAI, 3, 2)) > 0
                     THEN TO_NCHAR(TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_CON_LAI, 3, 2))) || TO_NCHAR(U' tháng ') ELSE TO_NCHAR(U'') END ||
                CASE WHEN TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_CON_LAI, 5, 2)) > 0
                     THEN TO_NCHAR(TO_NUMBER(SUBSTR(pnf.THA_THOI_GIAN_CON_LAI, 5, 2))) || TO_NCHAR(U' ngày')   ELSE TO_NCHAR(U'') END
            )
        END                                                          AS "ConLai",
        pnf.THA_GHI_CHU_DAC_BIET                                     AS "GhiChu",
        xla.XEP_LOAI_TAT_CA_NAM                                      AS "XepLoaiCacNam"
    FROM pn_filtered pnf
    LEFT JOIN DM_GIOI_TINHS dgt
        ON pnf.LL_DM_GIOI_TINH_ID = dgt.ID
       AND NVL(dgt.IS_DELETED, 0) = 0
    LEFT JOIN DM_PHAN_TRAIS dpt
        ON pnf.LL_PHAN_TRAI_ID = dpt.ID
       AND NVL(dpt.IS_DELETED, 0) = 0
    LEFT JOIN DM_PHAN_DOIS dpd
        ON pnf.LL_PHAN_DOI_ID = dpd.ID
       AND NVL(dpd.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_THANH_PHO dttp
        ON pnf.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp.ID
       AND NVL(dttp.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp
        ON pnf.LL_DIA_CHI_THUONG_TRU_WARD = dxp.ID
       AND NVL(dxp.IS_DELETED, 0) = 0
    LEFT JOIN xep_loai_agg xla ON pnf.ID = xla.PHAM_NHAN_ID
    ORDER BY
        CASE WHEN p_pn_ids IS NULL     THEN pnf.ID       ELSE NULL END,
        CASE WHEN p_pn_ids IS NOT NULL THEN pnf.PN_ORD   ELSE NULL END;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_DS_XLCT_TAT_CA;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DX_PHIEU_DE_NGHI_DAC_XA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DX_PHIEU_DE_NGHI_DAC_XA" (
--    p_pn_ids            IN  VARCHAR2   DEFAULT NULL,
    p_ma_trai_giam      IN  NVARCHAR2  DEFAULT NULL
) AS
    c1 SYS_REFCURSOR;
    v_trai_giam_id NUMBER;
BEGIN
    IF p_ma_trai_giam IS NOT NULL THEN
        BEGIN
            SELECT id INTO v_trai_giam_id
            FROM DM_TRAI_GIAMS
            WHERE TG_MA = p_ma_trai_giam AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION WHEN NO_DATA_FOUND THEN v_trai_giam_id := NULL;
        END;
    END IF;

    OPEN c1 FOR
    WITH
--    pn_ids_str AS (
--        SELECT REPLACE(REPLACE(TRIM(NVL(p_pn_ids, '')), '[', ''), ']', '') AS ids
--        FROM dual
--    ),
    pn_ids_input AS (
            SELECT PN_ID AS pn_id
		    FROM QLPN.GTT_PN_IDS
    ),
    base AS (
        SELECT v.*,
               pdx.DX_NGAY_XET AS ngay_xet,
               dot.DDX_TEN_DOT,
               pdx.DX_YKIEN_DOI_PN,
               pdx.DX_NHAN_XET_TRAI,
               pdx.DX_KQCT_PHIEU
        FROM pn_ids_input i
        INNER JOIN PN_LAI_LICH_CHI_TIET_RT rt_f
            ON rt_f.PHAM_NHAN_ID = i.pn_id
           AND NVL(rt_f.IS_DELETED, 0) = 0
           AND NVL(rt_f.LL_IS_DELETED, 0) = 0
           AND NVL(rt_f.THA_IS_DELETED, 0) = 0
           AND (p_ma_trai_giam IS NULL OR rt_f.LL_TRAI_GIAM_ID = v_trai_giam_id)
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = i.pn_id
           AND NVL(v.IS_DELETED, 0) = 0
        LEFT JOIN PN_DAC_XAS pdx
            ON pdx.PNLAI_LICH_ID = i.pn_id
           AND NVL(pdx.IS_DELETED, 0) = 0
        LEFT JOIN PN_DOT_DAC_XAS dot
            ON NVL(dot.IS_DELETED, 0) = 0
           AND dot.DDX_NGAY_XET IS NOT NULL
           AND pdx.DX_NGAY_XET >= TRUNC(dot.DDX_NGAY_XET)
           AND pdx.DX_NGAY_XET < TRUNC(dot.DDX_NGAY_XET) + 1
    ),
    than_nhan_agg AS (
        SELECT
            t.PHAM_NHAN_ID,
            MAX(CASE WHEN t.loai = 'BO' THEN t.HO_TEN_THAN_NHAN END) AS HO_TEN_BO,
            MAX(CASE WHEN t.loai = 'BO' THEN t.NGAY_SINH END) AS NAM_SINH_BO,
            MAX(CASE WHEN t.loai = 'BO' THEN t.NGHE_NGHIEP END) AS NGHE_NGHIEP_BO,
            MAX(CASE WHEN t.loai = 'BO' THEN t.NOI_O END) AS CHO_O_HIEN_TAI_BO,
            MAX(CASE WHEN t.loai = 'ME' THEN t.HO_TEN_THAN_NHAN END) AS HO_TEN_ME,
            MAX(CASE WHEN t.loai = 'ME' THEN t.NGAY_SINH END) AS NAM_SINH_ME,
            MAX(CASE WHEN t.loai = 'ME' THEN t.NGHE_NGHIEP END) AS NGHE_NGHIEP_ME,
            MAX(CASE WHEN t.loai = 'ME' THEN t.NOI_O END) AS CHO_O_HIEN_TAI_ME,
            MAX(CASE WHEN t.loai = 'VC' THEN t.HO_TEN_THAN_NHAN END) AS HO_TEN_VC,
            MAX(CASE WHEN t.loai = 'VC' THEN t.NGAY_SINH END) AS NAM_SINH_VC,
            MAX(CASE WHEN t.loai = 'VC' THEN t.NGHE_NGHIEP END) AS NGHE_NGHIEP_VC,
            MAX(CASE WHEN t.loai = 'VC' THEN t.NOI_O END) AS CHO_O_HIEN_TAI_VC
        FROM (
            SELECT tn.PHAM_NHAN_ID,
                   TRIM(CAST(tn.HO_TEN_THAN_NHAN AS NVARCHAR2(2000))) AS HO_TEN_THAN_NHAN,
                   CAST(tn.NGAY_SINH AS NVARCHAR2(200)) AS NGAY_SINH,
                   CAST(tn.NGHE_NGHIEP AS NVARCHAR2(2000)) AS NGHE_NGHIEP,
                   CAST(tn.NOI_O AS NVARCHAR2(2000)) AS NOI_O,
                   CASE
                       WHEN qh.QHVPN_MA IN ('121', '123') THEN 'BO'
                       WHEN qh.QHVPN_MA IN ('122', '124') THEN 'ME'
                       WHEN qh.QHVPN_MA IN ('131', '132') THEN 'VC'
                   END AS loai,
                   ROW_NUMBER() OVER (
                       PARTITION BY tn.PHAM_NHAN_ID,
                           CASE
                               WHEN qh.QHVPN_MA IN ('121', '123') THEN 'BO'
                               WHEN qh.QHVPN_MA IN ('122', '124') THEN 'ME'
                               WHEN qh.QHVPN_MA IN ('131', '132') THEN 'VC'
                           END
                       ORDER BY tn.ID
                   ) AS rn
            FROM THAN_NHAN_NGUOI_THANS tn
            INNER JOIN base b ON b.PHAM_NHAN_ID = tn.PHAM_NHAN_ID
            INNER JOIN DM_QUAN_HE_VOI_PHAM_NHANS qh
                ON qh.ID = tn.QUAN_HE_ID
               AND NVL(qh.IS_DELETED, 0) = 0
               AND qh.QHVPN_MA IN ('121', '122', '123', '124', '131', '132')
            WHERE NVL(tn.IS_DELETED, 0) = 0
        ) t
        WHERE t.rn = 1
        GROUP BY t.PHAM_NHAN_ID
    ),
    fn_vals AS (
        SELECT
            x.PHAM_NHAN_ID,
            x.ta_obj.SO_TIEN_AN AS SO_TIEN_AN,
            CAST(x.ta_obj.CHI_TIET_TIEN_AN AS NVARCHAR2(4000)) AS CHI_TIET_TIEN_AN,
            x.ts_obj.SO_TIEN_SU AS SO_TIEN_SU,
            CAST(x.ts_obj.HANH_VI_TIEN_SU AS NVARCHAR2(4000)) AS HANH_VI_TIEN_SU
        FROM (
            SELECT
                b.PHAM_NHAN_ID,
                FN_GET_TIEN_AN_TONG_HOP(b.PHAM_NHAN_ID) AS ta_obj,
                FN_TONG_HOP_TIEN_SU(b.PHAM_NHAN_ID) AS ts_obj
            FROM base b
        ) x
    ),
    tdc_all AS (
        SELECT td.PHAM_NHAN_ID, td.TU_NGAY, td.NGAY_LAI
        FROM TAM_DINH_CHIS td
        INNER JOIN base b ON b.PHAM_NHAN_ID = td.PHAM_NHAN_ID
        WHERE NVL(td.IS_DELETED, 0) = 0
          AND td.TU_NGAY IS NOT NULL
    ),
    tdc_span AS (
        SELECT
            a.PHAM_NHAN_ID,
            a.TU_NGAY,
            a.NGAY_LAI,
            TRUNC(a.TU_NGAY) AS d1,
            TRUNC(a.TU_NGAY) + GREATEST(0, TRUNC(a.NGAY_LAI) - TRUNC(a.TU_NGAY) + 1) AS d2
        FROM tdc_all a
    ),
    tdc_ymd_final AS (
        SELECT
            s.PHAM_NHAN_ID,
            s.TU_NGAY,
            CASE WHEN s.v_d >= 0 THEN s.v_y WHEN s.v_m > 0 THEN s.v_y ELSE GREATEST(s.v_y - 1, 0) END AS adj_y,
            CASE WHEN s.v_d >= 0 THEN s.v_m WHEN s.v_m > 0 THEN s.v_m - 1 ELSE 11 END AS adj_m,
            CASE
                WHEN s.d2 <= s.d1 THEN 0
                WHEN s.v_d >= 0 THEN s.v_d
                ELSE GREATEST(
                    TRUNC(s.d2 - ADD_MONTHS(
                        s.d1,
                        (CASE WHEN s.v_d >= 0 THEN s.v_y WHEN s.v_m > 0 THEN s.v_y ELSE GREATEST(s.v_y - 1, 0) END) * 12
                        + (CASE WHEN s.v_d >= 0 THEN s.v_m WHEN s.v_m > 0 THEN s.v_m - 1 ELSE 11 END)
                    )),
                    0
                )
            END AS adj_d
        FROM (
            SELECT
                c.PHAM_NHAN_ID,
                c.TU_NGAY,
                c.d1,
                c.d2,
                TRUNC(y.v_months / 12) AS v_y,
                MOD(y.v_months, 12) AS v_m,
                CASE
                    WHEN c.d2 <= c.d1 THEN 0
                    ELSE TRUNC(c.d2 - ADD_MONTHS(c.d1, TRUNC(y.v_months / 12) * 12 + MOD(y.v_months, 12)))
                END AS v_d
            FROM tdc_span c
            CROSS APPLY (
                SELECT CASE WHEN c.d2 <= c.d1 THEN 0 ELSE TRUNC(MONTHS_BETWEEN(c.d2, c.d1)) END AS v_months
                FROM dual
            ) y
            WHERE c.NGAY_LAI IS NOT NULL
        ) s
    ),
    tdc_agg AS (
        SELECT
            a.PHAM_NHAN_ID,
            LISTAGG(
                u'T\1eeb ng\00e0y '
                || TO_CHAR(a.TU_NGAY, 'DD/MM/YYYY')
                || u': '
                || CASE
                       WHEN a.NGAY_LAI IS NULL THEN u'Kh\00f4ng'
                       WHEN f.PHAM_NHAN_ID IS NULL THEN u'Kh\00f4ng'
                       ELSE NVL(
                           NULLIF(
                               TRIM(
                                   CASE WHEN NVL(f.adj_y, 0) > 0 THEN TO_NCHAR(f.adj_y) || u' n\0103m ' ELSE u'' END
                                   || CASE WHEN NVL(f.adj_m, 0) > 0 THEN TO_NCHAR(f.adj_m) || u' th\00e1ng ' ELSE u'' END
                                   || CASE WHEN NVL(f.adj_d, 0) > 0 THEN TO_NCHAR(f.adj_d) || u' ng\00e0y' ELSE u'' END
                               ),
                               u''
                           ),
                           u'Kh\00f4ng'
                       )
                   END,
                u'; '
            ) WITHIN GROUP (ORDER BY a.TU_NGAY NULLS LAST) AS TAM_DINH_CHI
        FROM tdc_all a
        LEFT JOIN tdc_ymd_final f
            ON f.PHAM_NHAN_ID = a.PHAM_NHAN_ID
           AND f.TU_NGAY = a.TU_NGAY
        GROUP BY a.PHAM_NHAN_ID
    )
    SELECT
        b.PHAM_NHAN_ID AS PHAM_NHAN_ID,
        NVL(b.TRAI_GIAM, '') AS TEN_TRAI_GIAM,
        NVL(b.DDX_TEN_DOT, '') AS DOT_DX,
        NVL(b.HO_TEN, '') AS HO_TEN_HOA,
        NVL(TRIM(CAST(b.CCCD AS VARCHAR2(255))), '') AS SO_CCCD,
        NULL AS NGAY_CAP_CCCD,
        NULL AS NOI_CAP_CCCD,
        NVL(b.GIOI_TINH, '') AS GIOI_TINH,
        CASE
            WHEN b.NGAY_SINH IS NOT NULL AND LENGTH(TRIM(b.NGAY_SINH)) >= 4
            THEN SUBSTR(TRIM(b.NGAY_SINH), -4)
            WHEN b.NAM_SINH IS NOT NULL AND b.NAM_SINH > 0
            THEN TO_NCHAR(b.NAM_SINH)
            ELSE NULL
        END AS NAM_SINH,
        NVL(b.TEN_KHAC, '') AS TEN_KHAC,
        NVL(b.NGUYEN_QUAN, '') AS NGUYEN_QUAN,
        b.NOI_THUONG_TRU_DAY_DU AS DIA_CHI_TT,
        b.NOI_THA_VE_CU_TRU AS DC_VE,
        NVL(b.DAN_TOC, '') AS DAN_TOC,
        NVL(b.QUOC_TICH, '') AS QUOC_TICH,
        NVL(b.TON_GIAO, '') AS TON_GIAO,
        NVL(b.HOC_VAN, '') AS HOC_VAN,
        NVL(b.NGHE_NGHIEP, '') AS NGHE_NGHIEP,
        NVL(b.TOI_DANH, '') AS TOI_DANH,
        NVL(CAST(b.TOM_TAT_HANH_VI AS NVARCHAR2(4000)), '') AS LL_TOM_TAT_HANH_VI,
        TO_CHAR(b.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT,
        NVL(b.AN_PHAT, '') AS AN_PHAT,
        NVL(b.THOI_GIAN_TAM_GIAM, '') AS MUC_TAM_GIAM,
        u'B\1ea3n \00e1n' AS BA_QD,
        NVL(b.SO_BAN_AN, '') AS BAN_AN_SO,
        TO_CHAR(b.NGAY_BAN_AN, 'DD/MM/YYYY') AS NGAY_XU,
        TRIM(NVL(b.TOA_XU_TEN, '') || NVL2(b.TOA_XU_DIA_PHUONG, u', ' || b.TOA_XU_DIA_PHUONG, '')) AS TOA_XU,
        NVL(b.SO_QD_THA, '') AS SO_QD_THAN,
        TO_CHAR(b.NGAY_QD_THA, 'DD/MM/YYYY') AS NGAY_QD_THAN,
        NVL(b.CO_QUAN_QD_THA, '') AS TOA_QD_THAN,
        TO_CHAR(b.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
        NVL(FN_GET_TONG_SO_NGAY_TRON(b.PHAM_NHAN_ID), '') AS TRON_TRAI,
        NVL(tdc.TAM_DINH_CHI, u'Kh\00f4ng') AS TAM_DINH_CHI,
        TO_CHAR(b.ngay_xet, 'DD/MM/YYYY') AS DEN_NGAY_XET,
        PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(b.PHAM_NHAN_ID, b.ngay_xet) AS TG_CHAP_HANH,
        NVL(PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(b.PHAM_NHAN_ID), u'Kh\00f4ng') AS TG_DA_GIAM,
        PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(b.PHAM_NHAN_ID, b.ngay_xet) AS TG_CON_LAI,
        NVL(fn.SO_TIEN_AN, 0) AS SO_TA,
        CASE
            WHEN NVL(fn.SO_TIEN_AN, 0) = 0 THEN u'Kh\00f4ng'
            ELSE REPLACE(NVL(fn.CHI_TIET_TIEN_AN, u''), CHR(10), CHR(13) || CHR(10))
        END AS TIEN_AN,
        NVL(fn.SO_TIEN_SU, 0) AS SO_TS,
        CASE
            WHEN NVL(fn.SO_TIEN_SU, 0) = 0 THEN u'Kh\00f4ng'
            ELSE REPLACE(NVL(fn.HANH_VI_TIEN_SU, u''), CHR(10), CHR(13) || CHR(10))
        END AS TIEN_SU,
        NVL(b.NHAN_THAN, '') AS NHAN_THAN,
        NVL(FN_GET_LIET_KE_HPBST_TNDST(b.PHAM_NHAN_ID), '') AS HPBS_TIEN,
        NVL(FN_GET_LIET_KE_HPBS_KHAC(b.PHAM_NHAN_ID), '') AS KHAC_HPBS,
        NVL(FN_GET_THONG_TIN_HPBS_PT(b.PHAM_NHAN_ID), '') AS HPBS_PT,
        NVL(b.PHAN_DOI, '') AS PHAN_DOI,
        NVL(b.PHAN_TRAI, '') AS PHAN_TRAI,
        NVL(b.TT_SUC_KHOE_HIEN_TAI, NVL(b.TINH_TRANG_SUC_KHOE, u'B\00ecnh th\01b0\1eddng')) AS SUC_KHOE,
        NVL(FN_GET_LIST_GHI_CHU_RIENG(b.GHI_CHU_RIENG), '') AS GHI_CHU_RIENG,
        NVL(tna.HO_TEN_BO, '') AS HO_TEN_BO,
        NVL(
            CASE
                WHEN tna.NAM_SINH_BO IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(tna.NAM_SINH_BO), '^\d{1,2}/\d{1,2}/\d{4}$')
                THEN SUBSTR(TRIM(tna.NAM_SINH_BO), -4)
                WHEN LENGTH(TRIM(tna.NAM_SINH_BO)) >= 4
                THEN SUBSTR(TRIM(tna.NAM_SINH_BO), -4)
                ELSE TRIM(tna.NAM_SINH_BO)
            END,
            ''
        ) AS NAM_SINH_BO,
        NVL(tna.NGHE_NGHIEP_BO, '') AS NGHE_NGHIEP_BO,
        NVL(tna.CHO_O_HIEN_TAI_BO, '') AS CHO_O_HIEN_TAI_BO,
        NVL(tna.HO_TEN_ME, '') AS HO_TEN_ME,
        NVL(
            CASE
                WHEN tna.NAM_SINH_ME IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(tna.NAM_SINH_ME), '^\d{1,2}/\d{1,2}/\d{4}$')
                THEN SUBSTR(TRIM(tna.NAM_SINH_ME), -4)
                WHEN LENGTH(TRIM(tna.NAM_SINH_ME)) >= 4
                THEN SUBSTR(TRIM(tna.NAM_SINH_ME), -4)
                ELSE TRIM(tna.NAM_SINH_ME)
            END,
            ''
        ) AS NAM_SINH_ME,
        NVL(tna.NGHE_NGHIEP_ME, '') AS NGHE_NGHIEP_ME,
        NVL(tna.CHO_O_HIEN_TAI_ME, '') AS CHO_O_HIEN_TAI_ME,
        NVL(tna.HO_TEN_VC, '') AS HO_TEN_VC,
        NVL(
            CASE
                WHEN tna.NAM_SINH_VC IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(tna.NAM_SINH_VC), '^\d{1,2}/\d{1,2}/\d{4}$')
                THEN SUBSTR(TRIM(tna.NAM_SINH_VC), -4)
                WHEN LENGTH(TRIM(tna.NAM_SINH_VC)) >= 4
                THEN SUBSTR(TRIM(tna.NAM_SINH_VC), -4)
                ELSE TRIM(tna.NAM_SINH_VC)
            END,
            ''
        ) AS NAM_SINH_VC,
        NVL(tna.NGHE_NGHIEP_VC, '') AS NGHE_NGHIEP_VC,
        NVL(tna.CHO_O_HIEN_TAI_VC, '') AS CHO_O_HIEN_TAI_VC,
        NVL(NULLIF(FN_GET_TEN_CON_CAI(b.PHAM_NHAN_ID), u'Kh\00f4ng c\00f3'), u'') AS CAC_CON,
        NVL(CAST(b.DX_KQCT_PHIEU AS NVARCHAR2(2000)), u'') AS XEP_LOAI_CAI_TAO,
        NVL(CAST(b.DX_YKIEN_DOI_PN AS NVARCHAR2(2000)), u'') AS YK_DOI,
        NVL(CAST(b.DX_NHAN_XET_TRAI AS NVARCHAR2(2000)), u'') AS NHAN_XET_DE_NGHI,
        NVL(b.CHI_TIET_HANH_VI, '') AS CHI_TIET_HANH_VI
    FROM base b
    LEFT JOIN fn_vals fn ON fn.PHAM_NHAN_ID = b.PHAM_NHAN_ID
    LEFT JOIN than_nhan_agg tna ON tna.PHAM_NHAN_ID = b.PHAM_NHAN_ID
    LEFT JOIN tdc_agg tdc ON tdc.PHAM_NHAN_ID = b.PHAM_NHAN_ID
    ORDER BY b.PHAN_TRAI, b.PHAN_DOI, ORDER_HOTEN(b.HO_TEN);

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_DX_PHIEU_DE_NGHI_DAC_XA;


-- Ví d? g?i:
-- EXEC SP_GET_DX_PHIEU_DE_NGHI_DAC_XA('101,102,103');
-- EXEC SP_GET_DX_PHIEU_DE_NGHI_DAC_XA('[101, 102, 103]');
-- EXEC SP_GET_DX_PHIEU_DE_NGHI_DAC_XA('101,102,103', N'94280');


-- =============================================================================
-- SP_GET_DX_PHIEU_DE_NGHI_DAC_XA
-- Phi?u ?? ngh? ??c xá.
-- M?i PN ch? ??c xá m?t l?n — l?y tr?c ti?p PN_DAC_XAS theo p_pn_ids, không l?c ??t m?i nh?t.
--
-- Input:
--   p_pn_ids           : Danh sách ID ph?m nhân (chu?i), h? tr? '1,2,3' ho?c '[1,2,3]'
--   p_ma_trai_giam     : Mã tr?i giam (DM_TRAI_GIAMS.TG_MA); NULL = t?t c? tr?i
-- =============================================================================

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_DX_PHIEU_DE_NGHI_DAC_XA_FILTER
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_DX_PHIEU_DE_NGHI_DAC_XA_FILTER" (
    p_trai_giam_id      IN NUMBER     DEFAULT NULL,
    p_phan_doi_id       IN NUMBER     DEFAULT NULL,
    p_muc_an_phat_id    IN NUMBER     DEFAULT NULL,
    p_tinh_trang_xet_id IN NUMBER     DEFAULT NULL,
    p_doi_tuong         IN NUMBER     DEFAULT NULL,
    p_quoc_tich         IN NUMBER     DEFAULT NULL,
    p_gioi_tinh_id      IN NUMBER     DEFAULT NULL,
    p_ho_ten            IN NVARCHAR2  DEFAULT NULL
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH dot_moi_nhat AS (
        SELECT id AS dot_id,
               NVL(ddx_ngay_xet, SYSDATE) AS ngay_xet
        FROM (
            SELECT id,
                   ddx_ngay_xet,
                   ROW_NUMBER() OVER (ORDER BY id DESC) AS rn
            FROM QLPN.PN_DOT_DAC_XAS
            WHERE NVL(IS_DELETED, 0) = 0
              AND ddx_trang_thai = 1
        )
        WHERE rn = 1
    )
    , pn_dac_xa AS (
        SELECT pn_lai_lich_id
        FROM (
            SELECT pdx.PNLAI_LICH_ID AS pn_lai_lich_id,
                   ROW_NUMBER() OVER (
                       PARTITION BY pdx.PNLAI_LICH_ID
                       ORDER BY pdx.ID DESC, pdx.CREATION_TIME DESC NULLS LAST
                   ) AS rn
            FROM QLPN.PN_DAC_XAS pdx
            INNER JOIN dot_moi_nhat dm
                ON TRUNC(NVL(pdx.DX_NGAY_XET, pdx.CREATION_TIME)) = TRUNC(dm.ngay_xet)
            WHERE NVL(pdx.IS_DELETED, 0) = 0
        )
        WHERE rn = 1
    )
    , filter_ctx AS (
        SELECT x.PHAM_NHAN_ID,
               x.ngay_xet,
               x.dot_id
        FROM (
            SELECT v.PHAM_NHAN_ID,
                   v.TRAI_GIAM_ID,
                   v.PHAN_DOI_ID,
                   v.MUC_AN_ID,
                   v.QUOC_TICH_ID,
                   v.HO_TEN,
                   v.TOI_DANH_ID,
                   NVL(ll.LL_DM_GIOI_TINH_ID, v.GIOI_TINH_ID) AS GIOI_TINH_ID,
                   dm.ngay_xet,
                   dm.dot_id,
                   dm_toi.TD_CHUONG AS td_chuong,
                   qt.QT_MA AS quoc_tich_ma
            FROM pn_dac_xa p
            INNER JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET v
                ON v.PHAM_NHAN_ID = p.pn_lai_lich_id
               AND NVL(v.IS_DELETED, 0) = 0
            LEFT JOIN QLPN.PN_LAI_LICHS ll
                ON ll.ID = v.PHAM_NHAN_ID
               AND NVL(ll.IS_DELETED, 0) = 0
            CROSS JOIN dot_moi_nhat dm
            LEFT JOIN QLPN.DM_TOI_DANHS dm_toi
                ON dm_toi.ID = TO_NUMBER(REGEXP_SUBSTR(NVL(TRIM(CAST(v.TOI_DANH_ID AS VARCHAR2(4000))), ''), '[0-9]+', 1, 1))
               AND NVL(dm_toi.IS_DELETED, 0) = 0
            LEFT JOIN QLPN.DM_QUOC_TICHS qt
                ON qt.ID = v.QUOC_TICH_ID
               AND NVL(qt.IS_DELETED, 0) = 0
        ) x
        WHERE (p_trai_giam_id IS NULL OR p_trai_giam_id = 0 OR x.TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_phan_doi_id IS NULL OR p_phan_doi_id = 0 OR x.PHAN_DOI_ID = p_phan_doi_id)
          AND (p_muc_an_phat_id IS NULL OR p_muc_an_phat_id = 0 OR x.MUC_AN_ID = p_muc_an_phat_id)
          AND (p_tinh_trang_xet_id IS NULL OR p_tinh_trang_xet_id = 0
               OR EXISTS (
                   SELECT 1 FROM QLPN.PN_DAC_XAS pdx
                   INNER JOIN QLPN.DM_DUOC_DAC_XAS ddx
                       ON ddx.ID = p_tinh_trang_xet_id
                      AND NVL(ddx.IS_DELETED, 0) = 0
                      AND TRIM(CAST(NVL(pdx.DX_TINH_TRANG_DAC_XA, '') AS VARCHAR2(100))) = TRIM(CAST(NVL(ddx.DDX_MA, '') AS VARCHAR2(100)))
                   WHERE pdx.PNLAI_LICH_ID = x.PHAM_NHAN_ID
                     AND NVL(pdx.IS_DELETED, 0) = 0
                     AND TRUNC(NVL(pdx.DX_NGAY_XET, pdx.CREATION_TIME)) = TRUNC(x.ngay_xet)
               ))
          AND (p_doi_tuong IS NULL OR p_doi_tuong = 0
               OR (p_doi_tuong = 1 AND TRIM(CAST(NVL(x.td_chuong, '') AS VARCHAR2(10))) = '13')
               OR (p_doi_tuong = 2 AND (x.td_chuong IS NULL OR TRIM(CAST(NVL(x.td_chuong, '') AS VARCHAR2(10))) <> '13')))
          AND (p_quoc_tich IS NULL OR p_quoc_tich = 0
               OR (p_quoc_tich = 250 AND x.quoc_tich_ma = 250)
               OR (p_quoc_tich = 999 AND (x.quoc_tich_ma IS NULL OR x.quoc_tich_ma <> 250)))
          AND (p_gioi_tinh_id IS NULL OR p_gioi_tinh_id = 0 OR x.GIOI_TINH_ID = p_gioi_tinh_id)
          AND (p_ho_ten IS NULL OR UPPER(CAST(NVL(x.HO_TEN, '') AS VARCHAR2(2000))) LIKE '%' || UPPER(TRIM(CAST(NVL(p_ho_ten, '') AS VARCHAR2(2000)))) || '%')
    )
    , LL_one AS (
        SELECT * FROM (
            SELECT v.*, ROW_NUMBER() OVER (PARTITION BY v.PHAM_NHAN_ID
                ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
                         v.CREATION_TIME DESC NULLS LAST) AS rn
            FROM QLPN.VW_PN_LAI_LICH_CHI_TIET v
            INNER JOIN filter_ctx fc_ll ON fc_ll.PHAM_NHAN_ID = v.PHAM_NHAN_ID
            WHERE NVL(v.IS_DELETED, 0) = 0
        ) x WHERE rn = 1
    )
    , THA_one AS (
        SELECT * FROM (
            SELECT t.*, ROW_NUMBER() OVER (PARTITION BY t.THA_PNLAI_LICH_ID
                ORDER BY NVL(t.THA_NGAY_HET_HAN, t.THA_NGAY_BAT) DESC NULLS LAST,
                         NVL(t.THA_NGAY_DEN_TRAI, t.THA_NGAY_BAT) DESC NULLS LAST,
                         t.ID DESC) AS rn
            FROM QLPN.PN_THI_HANH_AN t
            INNER JOIN filter_ctx fc_tha ON fc_tha.PHAM_NHAN_ID = t.THA_PNLAI_LICH_ID
            WHERE NVL(t.IS_DELETED, 0) = 0
        ) x WHERE rn = 1
    )
    , toi_ids AS (
        SELECT q.PHAM_NHAN_ID,
               TRIM(REGEXP_SUBSTR(q.csv, '[^,]+', 1, LEVEL)) AS id_str,
               LEVEL AS ord
        FROM (
            SELECT LL.PHAM_NHAN_ID,
                   REPLACE(REPLACE(NVL(LL.TOI_DANH_ID, LL.TOI_DANH), '[', ''), ']', '') AS csv
            FROM LL_one LL
            WHERE NVL(LL.TOI_DANH_ID, LL.TOI_DANH) IS NOT NULL
              AND TRIM(REPLACE(REPLACE(NVL(LL.TOI_DANH_ID, LL.TOI_DANH), '[', ''), ']', '')) IS NOT NULL
        ) q
        CONNECT BY LEVEL <= REGEXP_COUNT(q.csv, ',') + 1
          AND PRIOR q.PHAM_NHAN_ID = q.PHAM_NHAN_ID
          AND PRIOR SYS_GUID() IS NOT NULL
    )
    , toi_ids_numeric AS (
        SELECT PHAM_NHAN_ID, TRIM(id_str) AS id_str, ord
        FROM toi_ids
        WHERE TRIM(id_str) IS NOT NULL
          AND VALIDATE_CONVERSION(TRIM(id_str) AS NUMBER) = 1
    )
    , toi_text AS (
        SELECT t.PHAM_NHAN_ID,
               LISTAGG(d.TD_TEN, ', ') WITHIN GROUP (ORDER BY t.ord) AS toi_danh_str
        FROM toi_ids_numeric t
        JOIN QLPN.DM_TOI_DANHS d ON d.ID = TO_NUMBER(t.id_str) AND NVL(d.IS_DELETED, 0) = 0
        GROUP BY t.PHAM_NHAN_ID
    )
    , ta_agg AS (
        SELECT ta_inner.PNTA_LAI_LICH_ID,
               COUNT(DISTINCT ta_inner.ID) AS TONG_TIEN_AN,
               LISTAGG(ta_inner.td_str, ', ') WITHIN GROUP (ORDER BY ta_inner.ID) AS TIEN_AN
        FROM (
            SELECT pta2.PNTA_LAI_LICH_ID, pta2.ID,
                   NVL(dtd.TD_TEN, '') AS td_str
            FROM QLPN.PN_TIEN_AN pta2
            LEFT JOIN (
                SELECT ID AS PNTA_ID,
                       TO_NUMBER(TRIM(REGEXP_SUBSTR(REPLACE(REPLACE(PNTA_TOI_DANH_ID, '[', ''), ']', ''), '[^,]+', 1, 1))) AS TOI_DANH_ID
                FROM QLPN.PN_TIEN_AN
                WHERE PNTA_TOI_DANH_ID IS NOT NULL
            ) td2 ON pta2.ID = td2.PNTA_ID
            LEFT JOIN QLPN.DM_TOI_DANHS dtd ON td2.TOI_DANH_ID = dtd.ID AND NVL(dtd.IS_DELETED, 0) = 0
            WHERE NVL(pta2.IS_DELETED, 0) = 0
              AND EXISTS (SELECT 1 FROM filter_ctx f_ta WHERE f_ta.PHAM_NHAN_ID = pta2.PNTA_LAI_LICH_ID)
        ) ta_inner
        GROUP BY ta_inner.PNTA_LAI_LICH_ID
    )
    , ts_agg AS (
        SELECT TS_PN_LAI_LICH_ID,
               COUNT(DISTINCT pts2.ID) AS TONG_TIEN_SU,
               LISTAGG(NVL(pts2.TS_HANH_VI_VI_PHAM, ''), ', ') WITHIN GROUP (ORDER BY pts2.ID) AS TIEN_SU
        FROM QLPN.PN_TIEN_SUS pts2
        WHERE NVL(pts2.IS_DELETED, 0) = 0
          AND EXISTS (SELECT 1 FROM filter_ctx f_ts WHERE f_ts.PHAM_NHAN_ID = pts2.TS_PN_LAI_LICH_ID)
        GROUP BY TS_PN_LAI_LICH_ID
    )
    , con_cai_agg AS (
        SELECT c.PHAM_NHAN_ID,
               LISTAGG(TRIM(NVL(c.HO_TEN_CON, u'')), u', ') WITHIN GROUP (ORDER BY c.ID) AS CAC_CON
        FROM QLPN.THAN_NHAN_CON_CAIS c
        WHERE NVL(c.IS_DELETED, 0) = 0
          AND LENGTH(TRIM(NVL(c.HO_TEN_CON, u''))) > 0
          AND EXISTS (SELECT 1 FROM filter_ctx f_cc WHERE f_cc.PHAM_NHAN_ID = c.PHAM_NHAN_ID)
        GROUP BY c.PHAM_NHAN_ID
    )
    , phiieu_vals AS (
        SELECT LL.PHAM_NHAN_ID,
               CASE WHEN TRIM(LL.SO_TIEN_AN) IS NOT NULL AND VALIDATE_CONVERSION(TRIM(LL.SO_TIEN_AN) AS NUMBER) = 1
                    THEN TO_NUMBER(TRIM(LL.SO_TIEN_AN)) ELSE NVL(ta_agg.TONG_TIEN_AN, 0) END AS so_ta,
               CASE WHEN TRIM(LL.SO_TIEN_SU) IS NOT NULL AND VALIDATE_CONVERSION(TRIM(LL.SO_TIEN_SU) AS NUMBER) = 1
                    THEN TO_NUMBER(TRIM(LL.SO_TIEN_SU)) ELSE NVL(ts_agg.TONG_TIEN_SU, 0) END AS so_ts,
               NVL(TREAT(QLPN.FN_GET_TIEN_AN_TONG_HOP(LL.PHAM_NHAN_ID) AS QLPN.OBJ_TIEN_AN_TONG_HOP).CHI_TIET_TIEN_AN,
                    NVL(ta_agg.TIEN_AN, u'')) AS ta_raw,
               NVL(TREAT(QLPN.FN_TONG_HOP_TIEN_SU(LL.PHAM_NHAN_ID) AS QLPN.OBJ_TIEN_SU_TONG_HOP).HANH_VI_TIEN_SU,
                    NVL(ts_agg.TIEN_SU, u'')) AS ts_raw,
               NVL(QLPN.FN_TONG_HOP_KET_QUA_CAI_TAO(LL.PHAM_NHAN_ID), u'') AS xep_fn_txt
        FROM LL_one LL
        LEFT JOIN ta_agg ON LL.PHAM_NHAN_ID = ta_agg.PNTA_LAI_LICH_ID
        LEFT JOIN ts_agg ON LL.PHAM_NHAN_ID = ts_agg.TS_PN_LAI_LICH_ID
    )
    SELECT
        LL.PHAM_NHAN_ID AS PHAM_NHAN_ID,
        NVL(LL.TRAI_GIAM, '') AS TEN_TRAI_GIAM,
        NVL(TO_CHAR(fc.dot_id), '') AS DOT,
        NVL(LL.HO_TEN, '') AS HO_TEN_HOA,
        NVL(LL.GIOI_TINH, '') AS GIOI_TINH,
        CASE
            WHEN LL.NGAY_SINH IS NOT NULL AND REGEXP_LIKE(CAST(TRIM(LL.NGAY_SINH) AS VARCHAR2(50)), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(CAST(TRIM(LL.NGAY_SINH) AS VARCHAR2(50)), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN LL.NAM_SINH IS NOT NULL AND LL.NAM_SINH > 0
            THEN TO_CHAR(LL.NAM_SINH)
            WHEN LL.NGAY_SINH IS NOT NULL AND REGEXP_LIKE(CAST(TRIM(LL.NGAY_SINH) AS VARCHAR2(50)), '^[0-9]{4}$')
            THEN CAST(TRIM(LL.NGAY_SINH) AS VARCHAR2(50))
            ELSE NULL
        END AS NAM_SINH,
        NVL(LL.TEN_KHAC, '') AS TEN_KHAC,
        NVL(LL.NGUYEN_QUAN, '') AS NGUYEN_QUAN,
        NVL(LL.NOI_THUONG_TRU_DAY_DU, LL.DIA_CHI_THUONG_TRU) AS DIA_CHI_TT,
        NVL(LL.NOI_THA_VE_CU_TRU, '') AS DC_VE,
        NVL(LL.DAN_TOC, '') AS DAN_TOC,
        NVL(LL.QUOC_TICH, '') AS QUOC_TICH,
        NVL(LL.TON_GIAO, '') AS TON_GIAO,
        NVL(LL.HOC_VAN, '') AS HOC_VAN,
        NVL(LL.NGHE_NGHIEP, '') AS NGHE_NGHIEP,
        NVL(tt.toi_danh_str, NVL(LL.TOI_DANH, '')) AS TOI_DANH,
        TO_CHAR(THA.THA_NGAY_BAT, 'DD/MM/YYYY') AS NGAY_BAT,
        NVL(THA.THA_AN_PHAT, LL.AN_PHAT) AS AN_PHAT,
        NVL(THA.THA_THOI_GIAN_TAM_GIAM, LL.THOI_GIAN_TAM_GIAM) AS MUC_TAM_GIAM,
        CASE WHEN LL.SO_BAN_AN IS NOT NULL THEN u'B\1ea3n \00e1n' WHEN LL.SO_QD_THA IS NOT NULL THEN u'Quy\1ebft \0111\1ecbnh thi h\00e0nh \00e1n' ELSE NULL END AS BA_QD,
        NVL(LL.SO_BAN_AN, LL.SO_QD_THA) AS BAN_AN_SO,
        TO_CHAR(NVL(LL.NGAY_BAN_AN, LL.NGAY_QD_THA), 'DD/MM/YYYY') AS NGAY_XU,
        TRIM(NVL(LL.TOA_XU_TEN, '') || NVL2(LL.TOA_XU_DIA_PHUONG, u', ' || LL.TOA_XU_DIA_PHUONG, '')) AS TOA_XU,
        NVL(LL.SO_QD_THA, '') AS SO_QD_THAN,
        TO_CHAR(LL.NGAY_QD_THA, 'DD/MM/YYYY') AS NGAY_QD_THAN,
        NVL(LL.CO_QUAN_QD_THA, '') AS TOA_QD_THAN,
        TO_CHAR(THA.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
        NVL(QLPN.FN_GET_TONG_SO_NGAY_TRON(LL.PHAM_NHAN_ID), '') AS TRON_TRAI,
        tdc_agg.TAM_DINH_CHI,
        TO_CHAR(fc.ngay_xet, 'DD/MM/YYYY') AS DEN_NGAY_XET,
        QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(LL.PHAM_NHAN_ID, fc.ngay_xet) AS TG_CHAP_HANH,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(LL.PHAM_NHAN_ID),
            NVL(THA.THA_TONG_AN_GIAM, '')) AS TG_DA_GIAM,
        QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(LL.PHAM_NHAN_ID, fc.ngay_xet) AS TG_CON_LAI,
        pv.so_ta AS SO_TA,
        NVL(pv.ta_raw, u'') AS TIEN_AN,
        pv.so_ts AS SO_TS,
        NVL(pv.ts_raw, u'') AS TIEN_SU,
        NVL(LL.NHAN_THAN, '') AS NHAN_THAN,
        NVL(QLPN.FN_GET_LIET_KE_HPBS_TIEN(LL.PHAM_NHAN_ID), '') AS HPBS_TIEN,
        NVL(QLPN.FN_GET_LIET_KE_HPBS_KHAC(LL.PHAM_NHAN_ID), '') AS KHAC_HPBS,
        NVL(dpd.PD_TEN, '') AS PHAN_DOI,
        NVL(LL.PHAN_TRAI, '') AS PHAN_TRAI,
        NVL(LL.TT_SUC_KHOE_HIEN_TAI, NVL(LL.TINH_TRANG_SUC_KHOE, 'Bình th??ng')) AS SUC_KHOE,
        NVL(gcr_agg.GCR_TEN_LIST, '') AS GHI_CHU_RIENG,
        NVL(bo_agg.HO_TEN_THAN_NHAN, '') AS HO_TEN_BO,
        NVL(me_agg.HO_TEN_THAN_NHAN, '') AS HO_TEN_ME,
        NVL(vc_agg.HO_TEN_THAN_NHAN, '') AS HO_TEN_VC,
        NVL(cca.CAC_CON, '') AS CAC_CON,
        NVL(pv.xep_fn_txt, u'') AS XEP_LOAI_CAI_TAO,
        NVL(LL.CHI_TIET_HANH_VI, '') AS CHI_TIET_HANH_VI
    FROM LL_one LL
    INNER JOIN filter_ctx fc ON fc.PHAM_NHAN_ID = LL.PHAM_NHAN_ID
    LEFT JOIN phiieu_vals pv ON pv.PHAM_NHAN_ID = LL.PHAM_NHAN_ID
    LEFT JOIN con_cai_agg cca ON cca.PHAM_NHAN_ID = LL.PHAM_NHAN_ID
    LEFT JOIN THA_one THA ON THA.THA_PNLAI_LICH_ID = LL.PHAM_NHAN_ID
    LEFT JOIN toi_text tt ON tt.PHAM_NHAN_ID = LL.PHAM_NHAN_ID
    LEFT JOIN QLPN.DM_PHAN_DOIS dpd ON LL.PHAN_DOI_ID = dpd.ID AND NVL(dpd.IS_DELETED, 0) = 0
    LEFT JOIN (
        SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN
        FROM (SELECT tn.*, ROW_NUMBER() OVER (PARTITION BY tn.PHAM_NHAN_ID ORDER BY tn.ID) AS rn
              FROM QLPN.THAN_NHAN_NGUOI_THANS tn
              WHERE tn.QUAN_HE_ID = 19 AND NVL(tn.IS_DELETED, 0) = 0
                AND EXISTS (SELECT 1 FROM filter_ctx f_bo WHERE f_bo.PHAM_NHAN_ID = tn.PHAM_NHAN_ID))
        WHERE rn = 1
    ) bo_agg ON LL.PHAM_NHAN_ID = bo_agg.PHAM_NHAN_ID
    LEFT JOIN (
        SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN
        FROM (SELECT tn.*, ROW_NUMBER() OVER (PARTITION BY tn.PHAM_NHAN_ID ORDER BY tn.ID) AS rn
              FROM QLPN.THAN_NHAN_NGUOI_THANS tn
              WHERE tn.QUAN_HE_ID = 18 AND NVL(tn.IS_DELETED, 0) = 0
                AND EXISTS (SELECT 1 FROM filter_ctx f_me WHERE f_me.PHAM_NHAN_ID = tn.PHAM_NHAN_ID))
        WHERE rn = 1
    ) me_agg ON LL.PHAM_NHAN_ID = me_agg.PHAM_NHAN_ID
    LEFT JOIN (
        SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN
        FROM (SELECT tn.*, ROW_NUMBER() OVER (PARTITION BY tn.PHAM_NHAN_ID ORDER BY tn.ID) AS rn
              FROM QLPN.THAN_NHAN_NGUOI_THANS tn
              JOIN QLPN.DM_QUAN_HE_VOI_PHAM_NHANS dqh ON tn.QUAN_HE_ID = dqh.ID
              WHERE dqh.QHVPN_MA IN ('VO', 'CHONG') AND NVL(tn.IS_DELETED, 0) = 0
                AND EXISTS (SELECT 1 FROM filter_ctx f_vc WHERE f_vc.PHAM_NHAN_ID = tn.PHAM_NHAN_ID))
        WHERE rn = 1
    ) vc_agg ON LL.PHAM_NHAN_ID = vc_agg.PHAM_NHAN_ID
    LEFT JOIN (
        SELECT pll2.PHAM_NHAN_ID,
               SUBSTR(RTRIM(XMLAGG(XMLELEMENT(e, gcr.GCR_TEN || ', ') ORDER BY gcr.GCR_TEN).extract('//text()').GETCLOBVAL(), ', '), 1, 2000) AS GCR_TEN_LIST
        FROM LL_one pll2
        LEFT JOIN (
            SELECT DISTINCT src.ID AS PHAM_NHAN_ID,
                   TO_NUMBER(TRIM(REGEXP_SUBSTR(src.LL_GHI_CHU_RIENG, '[^,]+', 1, LEVEL))) AS GCR_ID
            FROM (SELECT ID, LL_GHI_CHU_RIENG FROM QLPN.PN_LAI_LICHS
                  WHERE LL_GHI_CHU_RIENG IS NOT NULL AND TRIM(LL_GHI_CHU_RIENG) <> ''
                    AND ID IN (SELECT PHAM_NHAN_ID FROM filter_ctx)) src
            CONNECT BY LEVEL <= REGEXP_COUNT(src.LL_GHI_CHU_RIENG, ',') + 1 AND PRIOR src.ID = src.ID AND PRIOR SYS_GUID() IS NOT NULL
        ) gcr_ids ON pll2.PHAM_NHAN_ID = gcr_ids.PHAM_NHAN_ID
        LEFT JOIN QLPN.DM_GHI_CHU_RIENGS gcr ON gcr_ids.GCR_ID = gcr.ID AND NVL(gcr.IS_DELETED, 0) = 0
        WHERE pll2.GHI_CHU_RIENG IS NOT NULL
        GROUP BY pll2.PHAM_NHAN_ID
    ) gcr_agg ON LL.PHAM_NHAN_ID = gcr_agg.PHAM_NHAN_ID
    LEFT JOIN (
        SELECT td.PHAM_NHAN_ID,
               LISTAGG(NVL(TO_CHAR(td.TU_NGAY, 'DD/MM/YYYY'), '') ||
                       NVL2(td.NGAY_LAI, u' - ' || TO_CHAR(td.NGAY_LAI, 'DD/MM/YYYY'), ''),
                       CHR(10)) WITHIN GROUP (ORDER BY td.TU_NGAY NULLS LAST) AS TAM_DINH_CHI
        FROM QLPN.TAM_DINH_CHIS td
        WHERE NVL(td.IS_DELETED, 0) = 0
          AND td.PHAM_NHAN_ID IN (SELECT PHAM_NHAN_ID FROM filter_ctx)
        GROUP BY td.PHAM_NHAN_ID
    ) tdc_agg ON LL.PHAM_NHAN_ID = tdc_agg.PHAM_NHAN_ID;

    DBMS_SQL.RETURN_RESULT(c1);
END ;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GIAM_RIENG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_GIAM_RIENG" (
    p_LAI_LICH_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        pgr.GR_PN_LAI_LICH_ID,
        d.LDGRPN_TEN  AS "LyDoGiamRieng",
        dmtg.MTG_TITLE  AS "ThoiHan",
        pgr.GR_NGAY_BAT_DAU  AS "NgayBatDau",
        pgr.GR_NGAY_KETTHUC  AS "NgayKetThuc",
        pgr.GR_LY_DO_DUA_RA  AS "LyDoDuaRa"
    FROM PN_GIAM_RIENGS pgr
    LEFT JOIN DM_LY_DO_GIAM_RIENG_PHAM_NHANS d ON pgr.GR_LY_DO = d.ID
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON pgr.GR_THOI_HAN_GIAM_RIENG = dmtg.ID
    WHERE pgr.GR_PN_LAI_LICH_ID = p_LAI_LICH_ID
        AND pgr.is_deleted = 0;
DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_GIAM_RIENG;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GIAM_RIENG_PT42A
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_GIAM_RIENG_PT42A" (
    p_gr_id IN  NVARCHAR2 
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH 
    SPLIT_TOI_DANH AS (
        SELECT /*+ NO_MERGE */
               ptha.THA_PNLAI_LICH_ID,
               dtd.ID  AS TOI_DANH_ID,
               dtd.TD_TEN
          FROM PN_THI_HANH_AN ptha
          JOIN DM_TOI_DANHS dtd
            ON INSTR(',' || REPLACE(REPLACE(ptha.THA_TOI_DANH,'[',''),']','') || ',',
                     ',' || dtd.ID || ',') > 0
         WHERE ptha.THA_TOI_DANH IS NOT NULL
           AND NVL(dtd.IS_DELETED, 0) = 0
    ),
    TOI_DANH_AGG AS (
        SELECT /*+ NO_MERGE */
               THA_PNLAI_LICH_ID,
               RTRIM(
                   XMLAGG(XMLELEMENT(e, TD_TEN || '; ') ORDER BY TD_TEN)
                       .extract('//text()').GETCLOBVAL(),
                   '; '
               ) AS TOI_DANH
          FROM SPLIT_TOI_DANH
         GROUP BY THA_PNLAI_LICH_ID
    ),

    LATEST_THA AS (
        SELECT
            THA_PNLAI_LICH_ID,
            THA_NGAY_BAT,
            THA_AN_PHAT,
            THA_SO_BAN_AN,
            TO_CHAR(THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS THA_NGAY_BAN_AN,
            THA_TOA_QD_ID,
            d2.TTP_TEN AS DIA_PHUONG_TOA,
            THA_SO_QD_THA,
            TO_CHAR(THA_NGAY_QD_THA, 'DD/MM/YYYY') AS THA_NGAY_QD_THA,
            THA_CAP_TOA_ID,
            d.TTP_TEN AS DIA_PHUONG_THA,
            TO_CHAR(THA_NGAY_DEN_TRAI, 'DD/MM/YYYY') as THA_NGAY_DEN_TRAI,
            ROW_NUMBER() OVER (
                PARTITION BY THA_PNLAI_LICH_ID
                ORDER BY NVL(THA_NGAY_BAN_AN, TO_DATE('01-JAN-1900', 'DD-MON-YYYY')) DESC, PN_THI_HANH_AN.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN
        LEFT JOIN DM_TINH_THANH_PHO d  ON PN_THI_HANH_AN.THA_DIA_PHUONG_TOA_QD_THA_ID = d.ID
        LEFT JOIN DM_TINH_THANH_PHO d2 ON PN_THI_HANH_AN.THA_DIA_PHUONG_CAP_TOA_ID    = d2.ID
    )
    SELECT
        pll.LL_HO_TEN          AS HoTen,
        pll.LL_TEN_KHAC        AS TenKhac,
        dgt.GT_TEN             AS GioiTinh,
        pll.LL_NGAY_SINH       AS NgaySinh,

        CASE
            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || dxp_thuong_tru.XP_TEN
                            ELSE dxp_thuong_tru.XP_TEN
                        END
                    ELSE u''
                   END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || dttp_thuong_tru.TTP_TEN
                            ELSE dttp_thuong_tru.TTP_TEN
                        END
                    ELSE u''
                   END
            )
            ELSE NULL
        END AS DiaChiThuongTru,

        ddt.DT_TEN              AS DanToc,
        dtg2.TG_TEN              AS TonGiao,
        dqt.QT_TEN               AS QuocTich,

        TO_CHAR(TRUNC(ptha.THA_NGAY_BAT), 'DD/MM/YYYY') AS NgayBat,
        ptha.THA_AN_PHAT          AS AnPhat,
        pll.LL_SO_TIEN_AN as SoTienAn,
        pll.LL_SO_TIEN_SU as SoTienSu,
        td_agg.TOI_DANH  AS ToiDanh,
        ptha.THA_SO_BAN_AN        AS BanAnSo,
        ptha.THA_NGAY_BAN_AN      AS NgayBanAn,
        dcq.CQ_TEN                AS ToaQuyetDinh,
        ptha.DIA_PHUONG_TOA       AS DiaPhuongToa,

        ptha.THA_SO_QD_THA        AS SoQuyetDinhTHA,
        ptha.THA_NGAY_QD_THA      AS NgayQuyetDinhTHA,
        dcq5.CQ_TEN                AS CoQuanQuyetDinh,
        ptha.DIA_PHUONG_THA       AS DiaPhuongQuyetDinh,
        ptha.THA_NGAY_DEN_TRAI AS NgayDenTrai,
        dpd.PD_TEN                AS PhanDoi,
        dpt.PT_TEN                 AS PhanTrai,
        dtg.TG_TEN                 AS TraiGiam,
        pll.LL_NHAN_THAN as NhanThan,
        d.LDGRPN_TEN AS LyDoDuaRa,
--        pgr.GR_LY_DO_DUA_RA as LyDoDuaRa,
        mtg.MTG_TITLE as ThoiHanGiamRieng,
       TO_CHAR(TRUNC(GR_NGAY_BAT_DAU), 'DD/MM/YYYY')  AS NGAYBATDAU
    FROM PN_LAI_LICHS pll
    LEFT JOIN LATEST_THA ptha
           ON pll.ID = ptha.THA_PNLAI_LICH_ID
          AND ptha.rn = 1
    left join PN_GIAM_RIENGS pgr on pll.ID = pgr.GR_PN_LAI_LICH_ID
    LEFT JOIN DM_LY_DO_GIAM_RIENG_PHAM_NHANS d  ON d.ID =  TO_NUMBER(pgr.GR_LY_DO)
    left JOIN DM_MA_THOI_GIANS mtg on pgr.GR_THOI_HAN_GIAM_RIENG = mtg.MTG_MA
    LEFT JOIN DM_GIOI_TINHS dgt   ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_DAN_TOCS  ddt    ON pll.LL_DM_DAN_TOC_ID   = ddt.ID
    LEFT JOIN DM_TON_GIAOS dtg2   ON pll.LL_DM_TON_GIAO_ID  = dtg2.ID
    LEFT JOIN DM_QUOC_TICHS dqt   ON pll.LL_DM_QUOC_TICH_ID = dqt.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
          AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
          AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS dcq     ON ptha.THA_TOA_QD_ID  = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq5    ON ptha.THA_CAP_TOA_ID = dcq5.ID
    LEFT JOIN DM_PHAN_DOIS dpd    ON pll.LL_PHAN_DOI_ID  = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt   ON pll.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg   ON pll.LL_TRAI_GIAM_ID = dtg.ID
    LEFT JOIN TOI_DANH_AGG td_agg    ON pll.ID                           = td_agg.THA_PNLAI_LICH_ID
    WHERE pgr.ID = TO_NUMBER(p_gr_id);

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        NULL;
    WHEN TOO_MANY_ROWS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Có nhi?u h?n 1 b?n ghi cho ph?m nhân : ' || p_gr_id);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: ' || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GIAM_RIENG_PT42B
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_GIAM_RIENG_PT42B" (
    p_gr_id IN NVARCHAR2
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH 
        SPLIT_TOI_DANH AS (
        SELECT /*+ NO_MERGE */
               ptha.THA_PNLAI_LICH_ID,
               dtd.ID  AS TOI_DANH_ID,
               dtd.TD_TEN
          FROM PN_THI_HANH_AN ptha
          JOIN DM_TOI_DANHS dtd
            ON INSTR(',' || REPLACE(REPLACE(ptha.THA_TOI_DANH,'[',''),']','') || ',',
                     ',' || dtd.ID || ',') > 0
         WHERE ptha.THA_TOI_DANH IS NOT NULL
           AND NVL(dtd.IS_DELETED, 0) = 0
    ),                             
    TOI_DANH_AGG AS (
        SELECT /*+ NO_MERGE */
               THA_PNLAI_LICH_ID,
               RTRIM(
                   XMLAGG(XMLELEMENT(e, TD_TEN || '; ') ORDER BY TD_TEN)
                       .extract('//text()').GETCLOBVAL(),
                   '; '
               ) AS TOI_DANH
          FROM SPLIT_TOI_DANH
         GROUP BY THA_PNLAI_LICH_ID
    ),
    LATEST_THA AS (
        SELECT
            THA_PNLAI_LICH_ID,
            THA_NGAY_BAT,
            THA_AN_PHAT,
            THA_SO_BAN_AN,
            TO_CHAR(THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS THA_NGAY_BAN_AN,
            THA_TOA_QD_ID,
            d2.TTP_TEN AS DIA_PHUONG_TOA,
            THA_SO_QD_THA,
            TO_CHAR(THA_NGAY_QD_THA, 'DD/MM/YYYY') AS THA_NGAY_QD_THA,
            THA_CAP_TOA_ID,
            d1.TTP_TEN AS DIA_PHUONG_THA,
            TO_CHAR(THA_NGAY_DEN_TRAI, 'DD/MM/YYYY') as THA_NGAY_DEN_TRAI,
            ROW_NUMBER() OVER (
                PARTITION BY THA_PNLAI_LICH_ID
                ORDER BY NVL(THA_NGAY_BAN_AN, TO_DATE('01-JAN-1900', 'DD-MON-YYYY')) DESC, PN_THI_HANH_AN.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN
        LEFT JOIN DM_TINH_THANH_PHO d1  ON PN_THI_HANH_AN.THA_DIA_PHUONG_TOA_QD_THA_ID = d1.ID
        LEFT JOIN DM_TINH_THANH_PHO d2 ON PN_THI_HANH_AN.THA_DIA_PHUONG_CAP_TOA_ID    = d2.ID
    ),
    GR_INFO AS (
        SELECT gr.GR_PN_LAI_LICH_ID, gr.GR_NGAY_QUYET_DINH_GIAM_RIENG
          FROM PN_GIAM_RIENGS gr
         WHERE gr.ID = TO_NUMBER(p_gr_id)
    ),
    PHAN_LOAI_TAI_GR AS (
        -- Ban ghi PHAN_LOAIS gan nhat co NGAY_PHAN_LOAI <= ngay quyet dinh giam rieng
        -- (khong lay ban ghi phan loai moi hon, vi do la phan loai SAU thoi diem giam rieng)
        SELECT
            pl.PHAM_NHAN_ID,
            pl.DEN_LOAI_ID,
            ROW_NUMBER() OVER (
                PARTITION BY pl.PHAM_NHAN_ID
                ORDER BY pl.NGAY_PHAN_LOAI DESC, pl.ID DESC
            ) AS rn
          FROM PHAN_LOAIS pl
          JOIN GR_INFO gi ON gi.GR_PN_LAI_LICH_ID = pl.PHAM_NHAN_ID
         WHERE NVL(pl.IS_DELETED, 0) = 0
           AND pl.NGAY_PHAN_LOAI <= gi.GR_NGAY_QUYET_DINH_GIAM_RIENG
    )
    SELECT
        pll.LL_HO_TEN          AS HoTen,
        pll.LL_TEN_KHAC        AS TenKhac,
        dgt.GT_TEN             AS GioiTinh,
        pll.LL_NGAY_SINH       AS NgaySinh,

        CASE
            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || dxp_thuong_tru.XP_TEN
                            ELSE dxp_thuong_tru.XP_TEN
                        END
                    ELSE u''
                   END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || dttp_thuong_tru.TTP_TEN
                            ELSE dttp_thuong_tru.TTP_TEN
                        END
                    ELSE u''
                   END
            )
            ELSE NULL
        END AS DiaChiThuongTru,

        ddt.DT_TEN              AS DanToc,
        dtg2.TG_TEN              AS TonGiao,
        dqt.QT_TEN               AS QuocTich,

        TO_CHAR(TRUNC(ptha.THA_NGAY_BAT), 'DD/MM/YYYY') AS NgayBat,
        ptha.THA_AN_PHAT          AS AnPhat,
        pll.LL_SO_TIEN_AN as SoTienAn,
        pll.LL_SO_TIEN_SU as SoTienSu,
        td_agg.TOI_DANH  AS ToiDanh,
        ptha.THA_SO_BAN_AN        AS BanAnSo,
        ptha.THA_NGAY_BAN_AN      AS NgayBanAn,
        dcq.CQ_TEN                AS ToaQuyetDinh,
        ptha.DIA_PHUONG_TOA       AS DiaPhuongToa,

        ptha.THA_SO_QD_THA        AS SoQuyetDinhTHA,
        ptha.THA_NGAY_QD_THA      AS NgayQuyetDinhTHA,
        dcq5.CQ_TEN                AS CoQuanQuyetDinh,
        ptha.DIA_PHUONG_THA       AS DiaPhuongQuyetDinh,
        THA_NGAY_DEN_TRAI AS NgayDenTrai,
        dpd.PD_TEN                AS PhanDoi,
        dpt.PT_TEN                 AS PhanTrai,
        dtg.TG_TEN                 AS TraiGiam,
        pll.LL_NHAN_THAN as NhanThan,
        pgr.GR_LY_DO_DUA_RA as LyDoDuaRa,
        mtg.MTG_TITLE as ThoiHanGiamRieng,
        pgr.GR_SO_QUYET_DINH_GIAM_RIENG AS SoQuyetDinhGr,
        TO_CHAR(TRUNC(pgr.GR_NGAY_QUYET_DINH_GIAM_RIENG), 'DD/MM/YYYY') AS NgayQdGiamRieng,
	    pgr.GR_SO_QUYET_DINH_RA AS SoQuyetDinhRa,
        TO_CHAR(TRUNC(pgr.GR_NGAY_QUYET_DINH_RA), 'DD/MM/YYYY') AS NgayQuyetDinhRa,
        dplgg_gr.PLGG_TEN AS PhanLoaiTaiThoiDiemGiamRieng
    FROM PN_LAI_LICHS pll
    LEFT JOIN LATEST_THA ptha
           ON pll.ID = ptha.THA_PNLAI_LICH_ID
          AND ptha.rn = 1
    left join PN_GIAM_RIENGS pgr on pll.ID = pgr.GR_PN_LAI_LICH_ID
    left JOIN DM_MA_THOI_GIANS mtg on pgr.GR_THOI_HAN_GIAM_RIENG = mtg.MTG_MA
    LEFT JOIN PHAN_LOAI_TAI_GR pltgr ON pltgr.PHAM_NHAN_ID = pll.ID AND pltgr.rn = 1
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg_gr ON dplgg_gr.ID = pltgr.DEN_LOAI_ID AND NVL(dplgg_gr.IS_DELETED, 0) = 0
    LEFT JOIN DM_GIOI_TINHS dgt   ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_DAN_TOCS  ddt    ON pll.LL_DM_DAN_TOC_ID   = ddt.ID
    LEFT JOIN DM_TON_GIAOS dtg2   ON pll.LL_DM_TON_GIAO_ID  = dtg2.ID
    LEFT JOIN DM_QUOC_TICHS dqt   ON pll.LL_DM_QUOC_TICH_ID = dqt.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
          AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
          AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS dcq     ON ptha.THA_TOA_QD_ID  = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq5    ON ptha.THA_CAP_TOA_ID = dcq5.ID
    LEFT JOIN DM_PHAN_DOIS dpd    ON pll.LL_PHAN_DOI_ID  = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt   ON pll.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg   ON pll.LL_TRAI_GIAM_ID = dtg.ID
    LEFT JOIN TOI_DANH_AGG td_agg    ON pll.ID                           = td_agg.THA_PNLAI_LICH_ID
    WHERE pgr.ID = TO_NUMBER(p_gr_id);

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        NULL;
    WHEN TOO_MANY_ROWS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Có nhi?u h?n 1 b?n ghi cho ph?m nhân : ' || p_gr_id);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: ' || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GIAM_RIENG_PT42C
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_GIAM_RIENG_PT42C" (
    p_gr_id IN NVARCHAR2
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH 
        SPLIT_TOI_DANH AS (
        SELECT /*+ NO_MERGE */
               ptha.THA_PNLAI_LICH_ID,
               dtd.ID  AS TOI_DANH_ID,
               dtd.TD_TEN
          FROM PN_THI_HANH_AN ptha
          JOIN DM_TOI_DANHS dtd
            ON INSTR(',' || REPLACE(REPLACE(ptha.THA_TOI_DANH,'[',''),']','') || ',',
                     ',' || dtd.ID || ',') > 0
         WHERE ptha.THA_TOI_DANH IS NOT NULL
           AND NVL(dtd.IS_DELETED, 0) = 0
    ),
    TOI_DANH_AGG AS (
        SELECT /*+ NO_MERGE */
               THA_PNLAI_LICH_ID,
               RTRIM(
                   XMLAGG(XMLELEMENT(e, TD_TEN || '; ') ORDER BY TD_TEN)
                       .extract('//text()').GETCLOBVAL(),
                   '; '
               ) AS TOI_DANH
          FROM SPLIT_TOI_DANH
         GROUP BY THA_PNLAI_LICH_ID
    ),
    LATEST_THA AS (
        SELECT
            THA_PNLAI_LICH_ID,
            THA_NGAY_BAT,
            THA_AN_PHAT,
            THA_SO_BAN_AN,
            TO_CHAR(THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS THA_NGAY_BAN_AN,
            THA_TOA_QD_ID,
            d2.TTP_TEN AS DIA_PHUONG_TOA,
            THA_SO_QD_THA,
            TO_CHAR(THA_NGAY_QD_THA, 'DD/MM/YYYY') AS THA_NGAY_QD_THA,
            THA_CAP_TOA_ID,
            d.TTP_TEN AS DIA_PHUONG_THA,
            TO_CHAR(THA_NGAY_DEN_TRAI, 'DD/MM/YYYY') as THA_NGAY_DEN_TRAI,
            ROW_NUMBER() OVER (
                PARTITION BY THA_PNLAI_LICH_ID
                ORDER BY NVL(THA_NGAY_BAN_AN, TO_DATE('01-JAN-1900', 'DD-MON-YYYY')) DESC, PN_THI_HANH_AN.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN
        LEFT JOIN DM_TINH_THANH_PHO d  ON PN_THI_HANH_AN.THA_DIA_PHUONG_TOA_QD_THA_ID = d.ID
        LEFT JOIN DM_TINH_THANH_PHO d2 ON PN_THI_HANH_AN.THA_DIA_PHUONG_CAP_TOA_ID    = d2.ID
    ),
    GR_INFO AS (
        SELECT gr.GR_PN_LAI_LICH_ID, gr.GR_NGAY_BAT_DAU
          FROM PN_GIAM_RIENGS gr
         WHERE gr.ID = TO_NUMBER(p_gr_id)
    ),
    PHAN_LOAI_TAI_GR AS (
        -- Ban ghi PHAN_LOAIS gan nhat co NGAY_PHAN_LOAI <= ngay bat dau giam rieng
        -- (khong lay ban ghi phan loai moi hon, vi do la phan loai SAU thoi diem giam rieng)
        SELECT
            pl.PHAM_NHAN_ID,
            pl.DEN_LOAI_ID,
            ROW_NUMBER() OVER (
                PARTITION BY pl.PHAM_NHAN_ID
                ORDER BY pl.NGAY_PHAN_LOAI DESC, pl.ID DESC
            ) AS rn
          FROM PHAN_LOAIS pl
          JOIN GR_INFO gi ON gi.GR_PN_LAI_LICH_ID = pl.PHAM_NHAN_ID
         WHERE NVL(pl.IS_DELETED, 0) = 0
           AND pl.NGAY_PHAN_LOAI <= gi.GR_NGAY_BAT_DAU
    )
    SELECT
        pll.LL_HO_TEN          AS HoTen,
        pll.LL_TEN_KHAC        AS TenKhac,
        dgt.GT_TEN             AS GioiTinh,
        pll.LL_NGAY_SINH       AS NgaySinh,

        CASE
            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || dxp_thuong_tru.XP_TEN
                            ELSE dxp_thuong_tru.XP_TEN
                        END
                    ELSE u''
                   END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || dttp_thuong_tru.TTP_TEN
                            ELSE dttp_thuong_tru.TTP_TEN
                        END
                    ELSE u''
                   END
            )
            ELSE NULL
        END AS DiaChiThuongTru,

        ddt.DT_TEN              AS DanToc,
        dtg2.TG_TEN              AS TonGiao,
        dqt.QT_TEN               AS QuocTich,

        TO_CHAR(TRUNC(ptha.THA_NGAY_BAT), 'DD/MM/YYYY') AS NgayBat,
        ptha.THA_AN_PHAT          AS AnPhat,
        pll.LL_SO_TIEN_AN as SoTienAn,
        pll.LL_SO_TIEN_SU as SoTienSu,
        td_agg.TOI_DANH  AS ToiDanh,
        ptha.THA_SO_BAN_AN        AS BanAnSo,
        ptha.THA_NGAY_BAN_AN      AS NgayBanAn,
        dcq.CQ_TEN                AS ToaQuyetDinh,
        ptha.DIA_PHUONG_TOA       AS DiaPhuongToa,
        THA_NGAY_DEN_TRAI AS NgayDenTrai,
        ptha.THA_SO_QD_THA        AS SoQuyetDinhTHA,
        ptha.THA_NGAY_QD_THA      AS NgayQuyetDinhTHA,
        dcq5.CQ_TEN                AS CoQuanQuyetDinh,
        ptha.DIA_PHUONG_THA       AS DiaPhuongQuyetDinh,

        dpd.PD_TEN                AS PhanDoi,
        dpt.PT_TEN                 AS PhanTrai,
        dtg.TG_TEN                 AS TraiGiam,
        pll.LL_NHAN_THAN as NhanThan,
        pgr.GR_LY_DO_DUA_RA as LyDoDuaRa,
        pgr.GR_SO_QUYET_DINH_RA AS SoQuyetDinhRa,
        TO_CHAR(TRUNC(pgr.GR_NGAY_QUYET_DINH_RA), 'DD/MM/YYYY') AS NgayQuyetDinhRa,  
        mtg.MTG_TITLE as ThoiHanGiamRieng,
        TO_CHAR(pgr.GR_NGAY_BAT_DAU, 'DD/MM/YYYY') AS NgayBatDauGiamRieng,
        pgr.GR_CHI_TIET_LY_DO AS LyDoGiamRieng,
        dplgg_gr.PLGG_TEN AS PhanLoaiTaiThoiDiemGiamRieng
    FROM PN_LAI_LICHS pll
    LEFT JOIN LATEST_THA ptha
           ON pll.ID = ptha.THA_PNLAI_LICH_ID
          AND ptha.rn = 1
    left join PN_GIAM_RIENGS pgr on pll.ID = pgr.GR_PN_LAI_LICH_ID
    left JOIN DM_MA_THOI_GIANS mtg on pgr.GR_THOI_HAN_GIAM_RIENG = mtg.MTG_MA
    LEFT JOIN PHAN_LOAI_TAI_GR pltgr ON pltgr.PHAM_NHAN_ID = pll.ID AND pltgr.rn = 1
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg_gr ON dplgg_gr.ID = pltgr.DEN_LOAI_ID AND NVL(dplgg_gr.IS_DELETED, 0) = 0
    LEFT JOIN DM_GIOI_TINHS dgt   ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_DAN_TOCS  ddt    ON pll.LL_DM_DAN_TOC_ID   = ddt.ID
    LEFT JOIN DM_TON_GIAOS dtg2   ON pll.LL_DM_TON_GIAO_ID  = dtg2.ID
    LEFT JOIN DM_QUOC_TICHS dqt   ON pll.LL_DM_QUOC_TICH_ID = dqt.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
          AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
          AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS dcq     ON ptha.THA_TOA_QD_ID  = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq5    ON ptha.THA_CAP_TOA_ID = dcq5.ID
    LEFT JOIN DM_PHAN_DOIS dpd    ON pll.LL_PHAN_DOI_ID  = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt   ON pll.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg   ON pll.LL_TRAI_GIAM_ID = dtg.ID
    LEFT JOIN TOI_DANH_AGG td_agg    ON pll.ID                           = td_agg.THA_PNLAI_LICH_ID
    WHERE pgr.ID = TO_NUMBER(p_gr_id);

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        NULL;
    WHEN TOO_MANY_ROWS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Có nhi?u h?n 1 b?n ghi cho ph?m nhân : ' || p_gr_id);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: ' || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END;

