--------------------------------------------------------
--  DDL for Procedure SP_GET_GIAM_THOI_HAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_GIAM_THOI_HAN" (
    p_PHAM_NHAN_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        gth.PHAM_NHAN_ID,
        gth.NGAY_XET AS "NgayXet",
        gth.SO_QUYET_DINH  AS "SoQD",
        gth.NGAY_QUYET_DINH  AS "NgayQD",
        dcq.CQ_TEN  AS "ToaQD",
        dmtg.MTG_TITLE   AS "MucGiam"
    FROM GIAM_THOI_HANS gth 
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID  
    LEFT JOIN DM_CO_QUANS dcq ON gth.TOA_QUYET_DINH_ID = dcq.ID
    WHERE gth.PHAM_NHAN_ID = p_PHAM_NHAN_ID;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_GIAM_THOI_HAN;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GIAO_NHAN_PHAM_NHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_GIAO_NHAN_PHAM_NHAN" (
    p_bien_ban_id IN NUMBER 
)
AS
    p_cursor SYS_REFCURSOR;
BEGIN
    OPEN p_cursor FOR

	WITH TOI_DANH_MAP AS (
	    SELECT 
	        bbpnn.ID AS BBPNN_ID,
	        LISTAGG(dm.TD_TEN, ', ') 
	            WITHIN GROUP (ORDER BY dm.TD_TEN) AS TOI_DANH_TEN
	    FROM PN_BIEN_BAN_PHAM_NHANS bbpnn
	    LEFT JOIN (
	        SELECT 
	            ID,
	            TO_NUMBER(REGEXP_SUBSTR(
	                REPLACE(REPLACE(TOI_DANH, '[', ''), ']', ''),
	                '[^,]+', 1, LEVEL
	            )) AS TOI_DANH_ID
	        FROM PN_BIEN_BAN_PHAM_NHANS
	        CONNECT BY REGEXP_SUBSTR(
	            REPLACE(REPLACE(TOI_DANH, '[', ''), ']', ''),
	            '[^,]+', 1, LEVEL
	        ) IS NOT NULL
	        AND PRIOR ID = ID
	        AND PRIOR SYS_GUID() IS NOT NULL
	    ) t
	        ON bbpnn.ID = t.ID
	    LEFT JOIN DM_TOI_DANHS dm
	        ON dm.ID = t.TOI_DANH_ID
	    GROUP BY bbpnn.ID
	)

    SELECT
        bb.BB_NGAY                  AS "NgayGiaoNhan",
        bb.HO_TEN_BG                AS "HoTenBenGiao",
        cvbg.CV_TEN               	AS "ChucVuBenGiao",
        cqg.CQ_TEN                  AS "DonViBenGiao",
        bb.SO_CMND_BG               AS "SoCmBenGiao",
        bb.NGAY_CAP_CMND_BG         AS "NgayCapCmBenGiao",
        ncg.CQ_TEN                  AS "NoiCapCmBenGiao",
		CASE 
		    WHEN dpx_bg.XP_TEN IS NULL AND dpt_bg.TTP_TEN IS NULL 
		    THEN NULL
		    ELSE NVL(dpx_bg.XP_TEN, '') || ', ' || NVL(dpt_bg.TTP_TEN, '')
		END 						AS "DiaPhuongBenGiao",

        bb.HO_TEN_BN                AS "HoTenBenNhan",
        cvbn.CV_TEN               	AS "ChucVuBenNhan",
        cqn.CQ_TEN                  AS "DonViBenNhan",
        bb.SO_CMND_BN               AS "SoCmBenNhan",
        bb.NGAY_CAP_CMND_BN         AS "NgayCapCmBenNhan",
        ncn.CQ_TEN                  AS "NoiCapCmBenNhan",
		CASE 
		    WHEN dpx_bn.XP_TEN IS NULL AND dpt_bn.TTP_TEN IS NULL 
		    THEN NULL
		    ELSE NVL(dpx_bn.XP_TEN, '') || ', ' || NVL(dpt_bn.TTP_TEN, '')
		END 						AS "DiaPhuongBenNhan",

        COUNT(DISTINCT bbpnn.ID) OVER (PARTITION BY bb.ID) AS "SoPhamNhan",

        bbpnn.HO_TEN                AS "HoTen",
        SUBSTR(bbpnn.NGAY_SINH, -4) AS "NamSinh",
        gt.GT_TEN                   AS "GioiTinh",

        (NVL(bbpnn.DC_TT_THON_PHO, '') || ', ' ||
    	NVL(xp.XP_TEN, '') || ', ' ||
    	NVL(tp.TTP_TEN, ''))	AS "NoiThuongTru",

        bbpnn.NGAY_BAT              AS "NgayBat",
        ap.MTG_TITLE                AS "AnPhat",

        tdm.TOI_DANH_TEN            AS "ToiDanh",

        NULL                        AS "SoTrang",
        vpllct.GHI_CHU              AS "GhiChu"

    FROM PN_BIEN_BANS bb

    LEFT JOIN PN_BIEN_BAN_PHAM_NHANS bbpnn
        ON bb.ID = bbpnn.PN_BIEN_BAN_ID
        AND bbpnn.IS_DELETED = 0

    LEFT JOIN TOI_DANH_MAP tdm
        ON bbpnn.ID = tdm.BBPNN_ID

    LEFT JOIN PN_LAI_LICHS pll
        ON bbpnn.PN_LAI_LICH_ID = pll.ID

    LEFT JOIN VW_PN_LAI_LICH_CHI_TIET vpllct
        ON pll.ID = vpllct.PHAM_NHAN_ID

    LEFT JOIN DM_MA_THOI_GIANS ap
        ON bbpnn.AN_PHAT = ap.ID

    LEFT JOIN DM_GIOI_TINHS gt
        ON bbpnn.GIOI_TINH_ID = gt.ID

    LEFT JOIN DM_CO_QUANS cqg
        ON bb.MA_CQ_BG = TO_CHAR(cqg.ID)

    LEFT JOIN DM_CO_QUANS ncg
        ON bb.NOI_CAP_CMND_BG = TO_CHAR(ncg.ID)

    LEFT JOIN DM_CO_QUANS cqn
        ON bb.MA_CQ_BN = TO_CHAR(cqn.ID)

    LEFT JOIN DM_CO_QUANS ncn
        ON bb.NOI_CAP_CMND_BN = TO_CHAR(ncn.ID)

    LEFT JOIN DM_TINH_THANH_PHO tp
        ON bbpnn.DC_TT_TINH_ID = tp.ID 

    LEFT JOIN DM_XA_PHUONG xp
        ON bbpnn.DC_TT_PHUONG_XA_ID = xp.ID

    LEFT JOIN DM_CHUC_VUS cvbn
        ON bb.CHUC_VU_BN = TO_CHAR(cvbn.ID)

    LEFT JOIN DM_CHUC_VUS cvbg
        ON bb.CHUC_VU_BG = TO_CHAR(cvbg.ID)

    LEFT JOIN DM_XA_PHUONG dpx_bg
   		ON bb.MA_DP_BG = TO_CHAR(dpx_bg.ID)
   	LEFT JOIN DM_TINH_THANH_PHO dpt_bg
        ON dpx_bg.XP_MA_TINH_THANH_PHO = dpt_bg.TTP_MA

    LEFT JOIN DM_XA_PHUONG dpx_bn
   		ON bb.MA_DP_BN = TO_CHAR(dpx_bn.ID)
   	LEFT JOIN DM_TINH_THANH_PHO dpt_bn
        ON dpx_bn.XP_MA_TINH_THANH_PHO = dpt_bn.TTP_MA

    WHERE bb.ID = p_bien_ban_id
    ORDER BY bbpnn.ID DESC;

    DBMS_SQL.RETURN_RESULT(p_cursor);
END SP_GET_GIAO_NHAN_PHAM_NHAN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GIAO_NHAN_PT6
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_GIAO_NHAN_PT6" (
    p_bien_ban_id IN NUMBER 
)
AS
    p_cursor SYS_REFCURSOR;
BEGIN
    OPEN p_cursor FOR

	WITH TOI_DANH_MAP AS (
	    SELECT 
	        bbpnn.ID AS BBPNN_ID,
	        LISTAGG(dm.TD_TEN, ', ') 
	            WITHIN GROUP (ORDER BY dm.TD_TEN) AS TOI_DANH_TEN
	    FROM PN_BIEN_BAN_PHAM_NHANS bbpnn
	    LEFT JOIN (
	        SELECT 
	            ID,
	            TO_NUMBER(REGEXP_SUBSTR(
	                REPLACE(REPLACE(TOI_DANH, '[', ''), ']', ''),
	                '[^,]+', 1, LEVEL
	            )) AS TOI_DANH_ID
	        FROM PN_BIEN_BAN_PHAM_NHANS
	        CONNECT BY REGEXP_SUBSTR(
	            REPLACE(REPLACE(TOI_DANH, '[', ''), ']', ''),
	            '[^,]+', 1, LEVEL
	        ) IS NOT NULL
	        AND PRIOR ID = ID
	        AND PRIOR SYS_GUID() IS NOT NULL
	    ) t
	        ON bbpnn.ID = t.ID
	    LEFT JOIN DM_TOI_DANHS dm
	        ON dm.ID = t.TOI_DANH_ID
	    GROUP BY bbpnn.ID
	)

    SELECT
        bb.BB_NGAY                  AS "NgayGiaoNhan",
        bb.HO_TEN_BG                AS "HoTenBenGiao",
        cvbg.CV_TEN               	AS "ChucVuBenGiao",
        cqg.CQ_TEN                  AS "DonViBenGiao",
        bb.SO_CMND_BG               AS "SoCmBenGiao",
        bb.NGAY_CAP_CMND_BG         AS "NgayCapCmBenGiao",
        ncg.CQ_TEN                  AS "NoiCapCmBenGiao",
		CASE 
		    WHEN dpx_bg.XP_TEN IS NULL AND dpt_bg.TTP_TEN IS NULL 
		    THEN NULL
		    ELSE NVL(dpx_bg.XP_TEN, '') || ', ' || NVL(dpt_bg.TTP_TEN, '')
		END 						AS "DiaPhuongBenGiao",

        bb.HO_TEN_BN                AS "HoTenBenNhan",
        cvbn.CV_TEN               	AS "ChucVuBenNhan",
        cqn.CQ_TEN                  AS "DonViBenNhan",
        bb.SO_CMND_BN               AS "SoCmBenNhan",
        bb.NGAY_CAP_CMND_BN         AS "NgayCapCmBenNhan",
        ncn.CQ_TEN                  AS "NoiCapCmBenNhan",
		CASE 
		    WHEN dpx_bn.XP_TEN IS NULL AND dpt_bn.TTP_TEN IS NULL 
		    THEN NULL
		    ELSE NVL(dpx_bn.XP_TEN, '') || ', ' || NVL(dpt_bn.TTP_TEN, '')
		END 						AS "DiaPhuongBenNhan",

        COUNT(DISTINCT bbpnn.ID) OVER (PARTITION BY bb.ID) AS "SoPhamNhan",

        bbpnn.HO_TEN                AS "HoTen",
        SUBSTR(bbpnn.NGAY_SINH, -4) AS "NamSinh",
        gt.GT_TEN                   AS "GioiTinh",

        (NVL(bbpnn.DC_TT_THON_PHO, '') || ', ' ||
    	NVL(xp.XP_TEN, '') || ', ' ||
    	NVL(tp.TTP_TEN, ''))	AS "NoiThuongTru",

        bbpnn.NGAY_BAT              AS "NgayBat",
        ap.MTG_TITLE                AS "AnPhat",

        tdm.TOI_DANH_TEN            AS "ToiDanh",

        bbpnn.SO_TRANG                      AS "SoTrang",
        vpllct.GHI_CHU              AS "GhiChu"

    FROM PN_BIEN_BANS bb

    LEFT JOIN PN_BIEN_BAN_PHAM_NHANS bbpnn
        ON bb.ID = bbpnn.PN_BIEN_BAN_ID
        AND bbpnn.IS_DELETED = 0

    LEFT JOIN TOI_DANH_MAP tdm
        ON bbpnn.ID = tdm.BBPNN_ID

    LEFT JOIN PN_LAI_LICHS pll
        ON bbpnn.PN_LAI_LICH_ID = pll.ID

    LEFT JOIN VW_PN_LAI_LICH_CHI_TIET vpllct
        ON pll.ID = vpllct.PHAM_NHAN_ID

    LEFT JOIN DM_MA_THOI_GIANS ap
        ON bbpnn.AN_PHAT = ap.MTG_MA

    LEFT JOIN DM_GIOI_TINHS gt
        ON bbpnn.GIOI_TINH_ID = gt.ID

    LEFT JOIN DM_CO_QUANS cqg
        ON bb.MA_CQ_BG = TO_CHAR(cqg.ID)

    LEFT JOIN DM_CO_QUANS ncg
        ON bb.NOI_CAP_CMND_BG = TO_CHAR(ncg.ID)

    LEFT JOIN DM_CO_QUANS cqn
        ON bb.MA_CQ_BN = TO_CHAR(cqn.ID)

    LEFT JOIN DM_CO_QUANS ncn
        ON bb.NOI_CAP_CMND_BN = TO_CHAR(ncn.ID)

    LEFT JOIN DM_TINH_THANH_PHO tp
        ON bbpnn.DC_TT_TINH_ID = tp.ID 

    LEFT JOIN DM_XA_PHUONG xp
        ON bbpnn.DC_TT_PHUONG_XA_ID = xp.ID

    LEFT JOIN DM_CHUC_VUS cvbn
        ON bb.CHUC_VU_BN = TO_CHAR(cvbn.ID)

    LEFT JOIN DM_CHUC_VUS cvbg
        ON bb.CHUC_VU_BG = TO_CHAR(cvbg.ID)

    LEFT JOIN DM_XA_PHUONG dpx_bg
   		ON bb.MA_DP_BG = TO_CHAR(dpx_bg.ID)
   	LEFT JOIN DM_TINH_THANH_PHO dpt_bg
        ON dpx_bg.XP_MA_TINH_THANH_PHO = dpt_bg.TTP_MA

    LEFT JOIN DM_XA_PHUONG dpx_bn
   		ON bb.MA_DP_BN = TO_CHAR(dpx_bn.ID)
   	LEFT JOIN DM_TINH_THANH_PHO dpt_bn
        ON dpx_bn.XP_MA_TINH_THANH_PHO = dpt_bn.TTP_MA

    WHERE bb.ID = p_bien_ban_id
    ORDER BY bbpnn.ID DESC;

    DBMS_SQL.RETURN_RESULT(p_cursor);
END SP_GET_GIAO_NHAN_PT6;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GIA_HAN_TRICH_XUAT_PT74A
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_GIA_HAN_TRICH_XUAT_PT74A" (
--    p_pham_nhan_id  IN NUMBER,
--    p_trich_xuat_id IN NVARCHAR2   -- ID b?ng TRICH_XUATS, nh?n chu?i và convert 1 l?n sang NUMBER
      p_trich_xuat_id IN NVARCHAR2
)
AS
    c1 SYS_REFCURSOR;
--    v_trich_xuat_id NUMBER;
BEGIN
--    IF p_pham_nhan_id IS NULL THEN
--        RAISE_APPLICATION_ERROR(-20001, 'p_pham_nhan_id khong duoc de trong');
--    END IF;
--
--    v_trich_xuat_id := TO_NUMBER(TRIM(p_trich_xuat_id) DEFAULT NULL ON CONVERSION ERROR);
--    IF v_trich_xuat_id IS NULL THEN
--        RAISE_APPLICATION_ERROR(-20001, 'p_trich_xuat_id khong duoc de trong hoac khong phai so hop le');
--    END IF;

    OPEN c1 FOR
        -- tx_ranked v?n quét toàn b? l?nh gia h?n (loai_lenh = 2) c?a ph?m nhân
        -- ?? ?ánh s? LAN_GIA_HAN ?úng th? t?, sau ?ó m?i l?c theo ID
        WITH tx_ranked AS (
            SELECT tx.*,
                   ROW_NUMBER() OVER (
                       ORDER BY tx.tx_ngay_trich_xuat NULLS LAST,
                                tx.tx_ngay_ra_lenh NULLS LAST,
                                tx.id
                   ) AS lan_gia_han
            FROM qlpn.trich_xuats tx
            WHERE NVL(tx.is_deleted, 0) = 0
              AND tx.tx_loai_lenh_id = 2
              --AND tx.pham_nhan_id = p_pham_nhan_id
              AND ID = p_trich_xuat_id
        ),
        tx_one AS (
            SELECT tx.*
            FROM tx_ranked tx
            --WHERE tx.id = v_trich_xuat_id
        )
        SELECT
            tx.lan_gia_han AS LAN_GIA_HAN,
            mtg.mtg_title AS THOI_HAN_GIA_HAN,
            TO_CHAR(CAST(tx.tx_ngay_trich_xuat AS DATE), 'DD/MM/YYYY') AS TU_NGAY,
            TO_CHAR(CAST(tx.tx_ngay_tra AS DATE), 'DD/MM/YYYY') AS DEN_NGAY,
            v.ho_ten AS HO_TEN,
            v.gioi_tinh AS GIOI_TINH,
            v.ngay_sinh AS NGAY_SINH,
            v.ten_khac AS HO_TEN_KHAC,
            NVL(v.noi_thuong_tru_day_du, v.dia_chi_thuong_tru) AS NOI_THUONG_TRU,
            v.toi_danh AS TOI_DANH,
            TO_CHAR(CAST(v.ngay_bat_an_phat AS DATE), 'DD/MM/YYYY') AS NGAY_BAT,
            v.an_phat AS AN_PHAT,
            v.so_ban_an AS SO_BAN_AN,
            TO_CHAR(CAST(v.ngay_ban_an AS DATE), 'DD/MM/YYYY') AS NGAY_BAN_AN,
            v.toa_xu_ten AS TOA_XU,
            v.toa_xu_dia_phuong AS DIA_PHUONG_XU,
            v.so_qd_tha AS SO_QD_THA,
            TO_CHAR(CAST(v.ngay_qd_tha AS DATE), 'DD/MM/YYYY') AS NGAY_QD_THA,
            v.co_quan_qd_tha AS TOA_QD_THA,
            v.toa_qd_tha_dia_phuong AS DIA_PHUONG_QD_THA,
--            v.trai_giam AS CO_QUAN_RA_LENH,
            cq_dn.cq_ten AS CO_QUAN_DE_NGHI_TX,
            cq_nhan.cq_ten AS CO_QUAN_NHAN_PHAM_NHAN,
            tx.tx_so_lenh AS SO_LENH_TX,
            tx.lan_gia_han AS LAN_GIA_HAN_TX
        FROM tx_one tx
        -- Join theo h?ng s? p_pham_nhan_id ?? optimizer ??y predicate vào view lai l?ch
        INNER JOIN qlpn.vw_pn_lai_lich_chi_tiet v
                ON v.pham_nhan_id = tx.pham_nhan_id
               AND NVL(v.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_co_quans cq_dn
               ON cq_dn.id = tx.tx_don_vi_de_nghi_id
              AND NVL(cq_dn.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_co_quans cq_nhan
               ON cq_nhan.id = tx.tx_don_vi_ve_id
              AND NVL(cq_nhan.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_ma_thoi_gians mtg
               ON mtg.id = tx.tx_thoi_han_id
              AND NVL(mtg.is_deleted, 0) = 0;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_GIA_HAN_TRICH_XUAT_PT74A: ' || SQLERRM);
END SP_GET_GIA_HAN_TRICH_XUAT_PT74A;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GTH_DS_GTH_CHUNG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_GTH_DS_GTH_CHUNG" (
    p_ky_giam_id IN NUMBER DEFAULT NULL,
    p_ho_ten IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_doi_tuong IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_muc_trai_de_nghi_id IN NUMBER DEFAULT NULL,
    p_muc_cap_tren_id IN NUMBER DEFAULT NULL,
    p_muc_toa_id IN NUMBER DEFAULT NULL,
    p_trang_thai_id IN NUMBER DEFAULT NULL,
    p_ma_trai_giam in VARCHAR2 DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        WITH GCR_SPLIT AS (SELECT lls.ID,
                                  REPLACE(REPLACE(lls.LL_GHI_CHU_RIENG, '[', ''), ']', '') AS ghi_chu_rieng_id
                           FROM QLPN.PN_LAI_LICHS lls),
             NUM_GEN_GCR AS (SELECT LEVEL AS N
                             FROM DUAL
                             CONNECT BY LEVEL <= 20),
             SPLIT_GCR AS (SELECT GS.ID,
                                  TO_NUMBER(TRIM(
                                          REGEXP_SUBSTR(GS.ghi_chu_rieng_id, '[^,]+', 1, NG.N)
                                            )) AS ghi_chu_rieng_id
                           FROM GCR_SPLIT GS
                                    JOIN NUM_GEN_GCR NG
                                         ON NG.N <= REGEXP_COUNT(GS.ghi_chu_rieng_id, ',') + 1
                           WHERE REGEXP_SUBSTR(GS.ghi_chu_rieng_id, '[^,]+', 1, NG.N) IS NOT NULL),
             GCR_AGG AS (SELECT S.ID,
                                LISTAGG(DISTINCT dm.GCR_TEN, '; ')
                                        WITHIN GROUP (ORDER BY dm.GCR_TEN) AS ghi_chu_riengs
                         FROM SPLIT_GCR S
                                  LEFT JOIN QLPN.DM_GHI_CHU_RIENGS dm
                                            ON dm.ID = s.ghi_chu_rieng_id
                         GROUP BY S.ID)
        SELECT TO_CHAR(gkgth.KGTH_NGAY_XET_GIAM, 'DD/MM/YYYY') AS "NgayXetGiam",
               ct.DDKCT_PN_ID                                  AS "PhamNhanId",
               ct.DDKCT_HO_TEN                                 AS "HoTen",
               SUBSTR(ct.DDKCT_NGAY_SINH, -4)                  AS "NamSinh",
               ct.DDKCT_GIOI_TINH                              AS "GioiTinh",
               NVL2(ll.LL_DIA_CHI_THUONG_TRU, ll.LL_DIA_CHI_THUONG_TRU || u', ', u'') || xp.XP_TEN || u', ' ||
               ttp.TTP_TEN                                     AS "DiaChiThuongTru",
               dqt.QT_TEN                                      AS "QuocTich",
               ct.DDKCT_TOI_DANH                               AS "ToiDanh",
               TO_CHAR(ptha.THA_NGAY_BAT, 'DD/MM/YYYY')        AS "NgayBat",
               ct.DDKCT_AN_PHAT                                AS "AnPhat",
               CASE
                   WHEN
                       ct.DDKCT_SO_TIEN_AN IS NULL THEN 'Không'
                   ELSE NVL(TO_CHAR(ct.DDKCT_SO_TIEN_AN), u'')
                   END                                         AS "SoTienAn",
               ct.DDKCT_THOI_GIAN_DA_GIAM                      AS "DaGiam",
               FN_GET_DA_CHAP_HANH_TEXT(ct.DDKCT_PN_ID,gkgth.KGTH_NGAY_XET_GIAM)                AS "DaChapHanh",
               mtg_trai.MTG_TITLE                              AS "MucDeNghiGiamTrai",
               mtg_cap_tren.MTG_TITLE                          AS "MucDeNghiCapTren",
               mtg_toa.MTG_TITLE                               AS "MucGiamToa",
               TO_CHAR(ct.DDKCT_NGAY_HET_HAN_SAU_GIAM, 'DD/MM/YYYY')         AS "NgayRaTrai",
               CASE
                   WHEN ct.DDKCT_HET_HAN IS NULL THEN u'\0110ang ch\1ea5p h\00e0nh \00e1n'
                   WHEN ct.DDKCT_HET_HAN > SYSDATE THEN u'\0110ang ch\1ea5p h\00e0nh \00e1n'
                   ELSE u'\0110\00e3 ra t\00f9'
                   END                                         AS "TinhTrang",
               ct.DDKCT_PHAN_DOI                               AS "PhanDoi", 
               bo_agg.HO_TEN_THAN_NHAN                         AS "HoTenBo",
               me_agg.HO_TEN_THAN_NHAN                         AS "HoTenMe",
               vc_agg.HO_TEN_THAN_NHAN                         AS "HoTenVoChong",
               xl_chapt.XLCHAPT                                AS "XLCHAPT",
               NVL(hpbs_agg.HPBS_TEXT, '')                     AS "HPBS",
               gcr.GHI_CHU_RIENGS                              AS "GhiChu",
               FN_TINH_THOI_GIAN_CON_LAI(ct.DDKCT_PN_ID,gkgth.KGTH_NGAY_XET_GIAM)  AS "ConLai",
               TO_CHAR(ptha.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY')   AS "NgayDenTrai",
               ll.LL_GHI_CHU_CHI_TIET                          AS "GhiChuChiTiet"
        FROM GTH_DU_DIEU_KIEN_CHI_TIETS ct
                 LEFT JOIN PN_LAI_LICHS ll ON ct.DDKCT_PN_ID = ll.ID
                 LEFT JOIN PN_THI_HANH_AN ptha
                           ON ct.DDKCT_PN_ID = ptha.THA_PNLAI_LICH_ID
                 JOIN DM_TINH_THANH_PHO ttp ON ttp.ID = ll.LL_DIA_CHI_THUONG_TRU_PROVICE
                 JOIN DM_XA_PHUONG xp ON xp.ID = ll.LL_DIA_CHI_THUONG_TRU_WARD
                 JOIN GTH_KY_GIAM_THOI_HANS gkgth
                      ON ct.DDKCT_KY_ID = gkgth.ID
                 JOIN GIAM_THOI_HANS gth2
                      ON ct.DDKCT_PN_ID = gth2.PHAM_NHAN_ID
                          AND (gkgth.KGTH_NGAY_XET_GIAM) = (gth2.NGAY_XET)
                 LEFT JOIN GCR_AGG gcr ON gcr.ID = ll.ID
            -- Qu?c t?ch (l?y tên)
                 LEFT JOIN DM_QUOC_TICHS dqt
                           ON ct.DDKCT_QUOC_TICH_ID = dqt.ID
            -- GTH m?i nh?t (cho filter m?c tr?i/c?p trên/tòa + s? Q? + ngày Q?)
                 LEFT JOIN (SELECT PHAM_NHAN_ID,
                                   MUC_DE_NGHI_ID,
                                   CAP_TREN_DUYET_ID,
                                   MUC_GIAM_ID,
                                   SO_QUYET_DINH,
                                   NGAY_QUYET_DINH,
                                   ROW_NUMBER() OVER (
                                       PARTITION BY PHAM_NHAN_ID ORDER BY ID DESC
                                       ) AS rn
                            FROM GIAM_THOI_HANS
                            WHERE NVL(IS_DELETED, 0) = 0) gth ON ct.DDKCT_PN_ID = gth.PHAM_NHAN_ID AND gth.rn = 1
                 LEFT JOIN DM_MA_THOI_GIANS mtg_trai
                           ON gth.MUC_DE_NGHI_ID = mtg_trai.ID
                 LEFT JOIN DM_MA_THOI_GIANS mtg_cap_tren
                           ON gth.CAP_TREN_DUYET_ID = mtg_cap_tren.ID
                 LEFT JOIN DM_MA_THOI_GIANS mtg_toa
                           ON gth.MUC_GIAM_ID = mtg_toa.ID
            -- XLCHAPT
                 LEFT JOIN (SELECT xl.PHAM_NHAN_ID,
                                   SUBSTR(
                                           RTRIM(
                                                   XMLAGG(
                                                           XMLELEMENT(e,
                                                                      TO_NCHAR(xl.XEP_LOAI_NAM) || TO_NCHAR(': ') ||
                                                                      CASE
                                                                          WHEN xl_6dau.XLCT_TEN IS NOT NULL
                                                                              THEN TO_NCHAR('?N: ') || xl_6dau.XLCT_TEN || TO_NCHAR('; ')
                                                                          ELSE TO_NCHAR('?N: ; ') END ||
                                                                      CASE
                                                                          WHEN xl_6cuoi.XLCT_TEN IS NOT NULL
                                                                              THEN TO_NCHAR('CN: ') || xl_6cuoi.XLCT_TEN || TO_NCHAR('; ')
                                                                          ELSE TO_NCHAR('CN: ; ') END ||
                                                                      CASE
                                                                          WHEN xl_canam.XLCT_TEN IS NOT NULL
                                                                              THEN TO_NCHAR('C? n?m: ') || xl_canam.XLCT_TEN
                                                                          ELSE TO_NCHAR('C? n?m: Ch?a ?? TGXL') END ||
                                                                      TO_NCHAR(CHR(10))
                                                           )
                                                           ORDER BY xl.XEP_LOAI_NAM
                                                   ).extract('//text()').GETSTRINGVAL(),
                                                   CHR(10)
                                           ), 1, 4000
                                   ) AS XLCHAPT
                            FROM XEP_LOAIS xl
                                     -- Ch? l?y ph?m nhân trong k? gi?m
                                     JOIN GTH_DU_DIEU_KIEN_CHI_TIETS ct2
                                          ON ct2.DDKCT_PN_ID = xl.PHAM_NHAN_ID
                                              AND ct2.DDKCT_KY_ID = p_ky_giam_id
                                              AND ct2.IS_DELETED = 0
                                     LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_6dau
                                               ON xl.XEP_LOAI_6_THANG_DAU_NAM = xl_6dau.ID
                                     LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_6cuoi
                                               ON xl.XEP_LOAI_6_THANG_CUOI_NAM = xl_6cuoi.ID
                                     LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_canam
                                               ON xl.XEP_LOAI_CA_NAM = xl_canam.ID
                            GROUP BY xl.PHAM_NHAN_ID) xl_chapt ON ct.DDKCT_PN_ID = xl_chapt.PHAM_NHAN_ID
            -- HPBS
                 LEFT JOIN (SELECT hp.HPBS_MA_PHAM_NHAN                  AS PHAM_NHAN_ID,
                                   LISTAGG(
                                           dm.HPBS_TEN
                                               || ' ' || TO_CHAR(hp.HPBS_TONG_TIEN_PHAT, 'FM999G999G999')
                                               || u' \0111\1ed3ng, '
                                               || CASE
                                                      WHEN NVL(bl.TONG_DA_NOP, 0) > 0
                                                          THEN u'\0111\00e3 n\1ed9p '
                                                          || TO_CHAR(bl.TONG_DA_NOP, 'FM999G999G999')
                                                          || u' \0111\1ed3ng'
                                                      ELSE u'ch\01b0a \0111\00f3ng'
                                               END,
                                           '; '
                                   ) WITHIN GROUP (ORDER BY dm.HPBS_TEN) AS HPBS_TEXT
                            FROM PN_HINH_PHAT_BO_SUNGS hp
                                     JOIN DM_HINH_PHAT_BO_SUNGS dm
                                          ON dm.ID = hp.HPBS_HINH_PHAT
                                              AND dm.IS_DELETED = 0
                                -- Ch? tính ph?m nhân trong k?
                                     JOIN GTH_DU_DIEU_KIEN_CHI_TIETS ct3
                                          ON ct3.DDKCT_PN_ID = hp.HPBS_MA_PHAM_NHAN
                                              AND ct3.DDKCT_KY_ID = p_ky_giam_id
                                              AND ct3.IS_DELETED = 0
                                     LEFT JOIN (SELECT HPBS_ID, SUM(BL_SO_TIEN) AS TONG_DA_NOP
                                                FROM PN_BIENLAIES
                                                WHERE IS_DELETED = 0
                                                GROUP BY HPBS_ID) bl ON bl.HPBS_ID = hp.ID
                            WHERE hp.IS_DELETED = 0
                            GROUP BY hp.HPBS_MA_PHAM_NHAN) hpbs_agg ON ct.DDKCT_PN_ID = hpbs_agg.PHAM_NHAN_ID
            -- B?
                 LEFT JOIN (SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN
                            FROM THAN_NHAN_NGUOI_THANS tnnt
                                     JOIN DM_QUAN_HE_VOI_PHAM_NHANS dqhvpn
                                          ON tnnt.QUAN_HE_ID = dqhvpn.ID
                            WHERE QHVPN_MA = '121'
                              AND ROWNUM = 1) bo_agg ON ct.DDKCT_PN_ID = bo_agg.PHAM_NHAN_ID
            -- M?
                 LEFT JOIN (SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN
                            FROM THAN_NHAN_NGUOI_THANS tnnt
                                     JOIN DM_QUAN_HE_VOI_PHAM_NHANS dqhvpn
                                          ON tnnt.QUAN_HE_ID = dqhvpn.ID
                            WHERE QHVPN_MA = '122'
                              AND ROWNUM = 1) me_agg ON ct.DDKCT_PN_ID = me_agg.PHAM_NHAN_ID
            -- V?/Ch?ng
                 LEFT JOIN (SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN
                            FROM THAN_NHAN_NGUOI_THANS tnnt
                                     JOIN DM_QUAN_HE_VOI_PHAM_NHANS dqhvpn
                                          ON tnnt.QUAN_HE_ID = dqhvpn.ID
                            WHERE QHVPN_MA IN ('132', '131')
                              AND ROWNUM = 1) vc_agg ON ct.DDKCT_PN_ID = vc_agg.PHAM_NHAN_ID

        WHERE ct.IS_DELETED = 0
          AND ct.DDKCT_KY_ID = p_ky_giam_id
        AND( p_ma_trai_giam IS NULL OR ct.MA_TRAI_GIAM = p_ma_trai_giam)
          -- Filter h? tên
          AND (p_ho_ten IS NULL OR TRIM(p_ho_ten) = ''
            OR UPPER(ct.DDKCT_HO_TEN) LIKE '%' || UPPER(TRIM(p_ho_ten)) || '%')
          -- Filter phân ??i
          AND (p_phan_doi_id IS NULL
            OR ct.DDKCT_PHAN_DOI_ID = p_phan_doi_id)
          -- Filter qu?c t?ch: 1=VN, 2=n??c ngoài
          AND (p_quoc_tich_id IS NULL OR p_quoc_tich_id = 0
            OR (p_quoc_tich_id = 250 AND dqt.QT_MA = '250')
            OR (p_quoc_tich_id = 999 AND (dqt.QT_MA IS NULL OR dqt.QT_MA <> '250')))
          -- Filter m?c tr?i ?? ngh?
          AND (p_muc_trai_de_nghi_id IS NULL
            OR gth.MUC_DE_NGHI_ID = p_muc_trai_de_nghi_id)
          -- Filter m?c c?p trên duy?t
          AND (p_muc_cap_tren_id IS NULL
            OR gth.CAP_TREN_DUYET_ID = p_muc_cap_tren_id)
          -- TI?N ÁN
--      AND  (p_tien_an IS NULL
--      	   OR (p_tien_an = 0 AND DDKCT_SO_TIEN_AN IS NULL )
--      	   OR (p_tien_an = 1 AND DDKCT_SO_TIEN_AN > 0)
--      	   )
          -- Filter m?c tòa quy?t ??nh
          AND (p_muc_toa_id IS NULL
            OR gth.MUC_GIAM_ID = p_muc_toa_id)
          -- Filter ??i t??ng: 1=ANQG, 2=hình s?
          AND (p_doi_tuong IS NULL
            OR ct.DDKCT_DOI_TUONG_ID = p_doi_tuong)
          -- Filter tr?ng thái
          AND (p_trang_thai_id IS NULL
            OR (p_trang_thai_id = 1 AND ct.DDKCT_DIEUKIEN_THOI_GIAN_ID IN (1, 2, 3, 4))
            OR (p_trang_thai_id = 2 AND ct.DDKCT_DIEUKIEN_THOI_GIAN_ID = 5)
            OR (p_trang_thai_id = 3 AND gth.CAP_TREN_DUYET_ID IS NOT NULL
                AND gth.MUC_DE_NGHI_ID IS NOT NULL
                AND gth.CAP_TREN_DUYET_ID <> gth.MUC_DE_NGHI_ID)
            OR (p_trang_thai_id = 4 AND gth.CAP_TREN_DUYET_ID IS NOT NULL
                AND gth.MUC_DE_NGHI_ID IS NOT NULL
                AND gth.CAP_TREN_DUYET_ID = gth.MUC_DE_NGHI_ID))

        ORDER BY ct.DDKCT_HO_TEN;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
                                u'L\1ed7i SP_GET_GTH_DS_GTH_CHUNG: ' || SQLERRM);
END SP_GET_GTH_DS_GTH_CHUNG;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GTH_PT34_TRAI_DE_NGHI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_GTH_PT34_TRAI_DE_NGHI" (
    p_ky_id        IN VARCHAR2,
   -- p_pn_ids       IN VARCHAR2 DEFAULT NULL ,
    p_ma_trai_giam IN VARCHAR2 DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    /* ==================== PH?N X? LÝ LIST IDs (l?y t? store kia) ==================== */
    ID_LIST AS (
        SELECT PN_ID 
    	FROM QLPN.GTT_PN_IDS

    ),
    /* ==================== PH?N QUERY CHÍNH (gi? nguyên logic c?) ==================== */
    HPBS_AGG AS (
        SELECT 
            hp.HPBS_MA_PHAM_NHAN AS PHAM_NHAN_ID,
            LISTAGG(
                dm.HPBS_TEN
                || ' ' || TO_CHAR(hp.HPBS_TONG_TIEN_PHAT, 'FM999G999G999G999')
                || ' ??ng, '
                || CASE
                       WHEN NVL(bl.TONG_DA_NOP, 0) > 0
                       THEN '?ã n?p ' || TO_CHAR(bl.TONG_DA_NOP,'FM999G999G999G999') || ' ??ng'
                       ELSE 'ch?a ?óng'
                   END,
                '; '
            ) WITHIN GROUP (ORDER BY dm.HPBS_TEN) AS HPBS_TEXT
        FROM PN_HINH_PHAT_BO_SUNGS hp
        JOIN DM_HINH_PHAT_BO_SUNGS dm ON dm.ID = hp.HPBS_HINH_PHAT
        LEFT JOIN (
            SELECT HPBS_ID, SUM(BL_SO_TIEN) AS TONG_DA_NOP
            FROM PN_BIENLAIES
            WHERE IS_DELETED = 0
            GROUP BY HPBS_ID
        ) bl ON bl.HPBS_ID = hp.ID
        WHERE hp.IS_DELETED = 0
        AND hp.HPBS_MA_PHAM_NHAN IN (SELECT PN_ID FROM ID_LIST)
        GROUP BY hp.HPBS_MA_PHAM_NHAN
    )

    SELECT
        ct.DDKCT_HO_TEN AS "HoTen",
        ct.DDKCT_GIOI_TINH AS "GioiTinh",
        pll.LL_TEN_KHAC AS "TenKhac",
        SUBSTR(ct.DDKCT_NGAY_SINH, -4) AS "NamSinh",
        ct.DDKCT_NOI_DKTT AS "DiaChiThuongTru",
        ct.DDKCT_TOI_DANH AS "ToiDanh",
        TO_CHAR(ptha.THA_NGAY_BAT, 'DD/MM/YYYY') AS "NgayBat",
        ct.DDKCT_AN_PHAT AS "AnPhat",
        CASE
            WHEN ct.DDKCT_SO_TIEN_AN IS NULL THEN 'Không'
            ELSE TO_CHAR(ct.DDKCT_SO_TIEN_AN)
        END AS "SoTienAn",
        TO_CHAR(ptha.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY') AS "NgayDenTrai",
        ct.DDKCT_THOI_GIAN_DA_CHAP_HANH AS "ThoiGianDaChapHanh",
        QLPN.FN_TINH_AN_DA_GIAM_CHI_TIET_GTH(ct.DDKCT_PN_ID,gkgth.KGTH_NGAY_XET_GIAM) AS "GiamAn",
        ct.DDKCT_THOI_GIAN_CON_LAI AS "ThoiGianConLai",
        ct.DDKCT_GHI_CHU  AS "XepLoaiChapHanh",
        dmtg.MTG_TITLE AS "MucGiam",
        NVL(TRIM(CAST(pll.LL_GHI_CHU_CHI_TIET AS VARCHAR2(2000))), '') AS "GhiChu"
    FROM GTH_DU_DIEU_KIEN_CHI_TIETS ct
    JOIN PN_LAI_LICHS pll 
    ON ct.DDKCT_PN_ID = pll.ID
    AND pll.IS_DELETED  = 0
    LEFT JOIN PN_THI_HANH_AN ptha
        ON ct.DDKCT_PN_ID = ptha.THA_PNLAI_LICH_ID
	JOIN GTH_KY_GIAM_THOI_HANS gkgth ON ct.DDKCT_KY_ID = gkgth.ID
    LEFT JOIN HPBS_AGG hpbs_agg
        ON ct.DDKCT_PN_ID = hpbs_agg.PHAM_NHAN_ID
	JOIN GIAM_THOI_HANS gth 
	ON ct.DDKCT_PN_ID = gth.PHAM_NHAN_ID
	AND trunc(KGTH_NGAY_XET_GIAM)	= trunc(gth.NGAY_XET)
	JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_DE_NGHI_ID = dmtg.ID  
    WHERE ct.IS_DELETED = 0
        AND( p_ma_trai_giam IS NULL OR ct.MA_TRAI_GIAM = p_ma_trai_giam)
      AND ct.DDKCT_KY_ID = TO_NUMBER(p_ky_id)
      AND gth.IS_DELETED  = 0
      AND pll.IS_DELETED  = 0
      -- Filter theo list IDs (?u tiên p_pn_ids m?i)
     AND ct.DDKCT_PN_ID IN (SELECT PN_ID FROM ID_LIST);
    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            'Loi SP_GET_GTH_PT34_TRAI_DE_NGHI: ' || SQLERRM);
END;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GTH_QUYET_DINH_GIAM
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_GTH_QUYET_DINH_GIAM" (
    p_pll_ids IN NVARCHAR2 DEFAULT NULL,
    p_ma_trai_giam  IN NVARCHAR2 DEFAULT NULL
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    ID_LIST AS (
        SELECT DISTINCT
            TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pll_ids), '[^,]+', 1, LEVEL))) AS PLL_ID
        FROM DUAL
        CONNECT BY LEVEL <= CASE
                WHEN p_pll_ids IS NULL THEN 0
                WHEN LENGTH(TRIM(p_pll_ids)) = 0 THEN 0
                ELSE REGEXP_COUNT(TRIM(p_pll_ids), ',') + 1
            END
          AND REGEXP_SUBSTR(TRIM(p_pll_ids), '[^,]+', 1, LEVEL) IS NOT NULL
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pll_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
    ),
    SPLIT_TOI_DANH AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            TO_NUMBER(
                REGEXP_SUBSTR(
                    REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
                    '[0-9]+', 1, LEVEL
                )
            ) AS TOI_DANH_ID
        FROM PN_THI_HANH_AN ptha
        WHERE ptha.THA_TOI_DANH IS NOT NULL
          AND ptha.THA_PNLAI_LICH_ID IN (SELECT PLL_ID FROM ID_LIST)
        CONNECT BY LEVEL <= REGEXP_COUNT(
                REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
           AND PRIOR ptha.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
           AND PRIOR SYS_GUID() IS NOT NULL
    ),
    TOI_DANH_AGG AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            LISTAGG(DISTINCT dtd.TD_TEN, ', ')
                WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH
        FROM SPLIT_TOI_DANH s
        LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
        GROUP BY s.THA_PNLAI_LICH_ID
    ),
    LATEST_THA AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            ptha.THA_AN_PHAT,
            ptha.THA_SO_BAN_AN,
            TO_CHAR(ptha.THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS THA_NGAY_BAN_AN,
            dcq_toa.CQ_TEN                               AS CAP_TOA,
            dttp_toa.TTP_TEN                             AS DIA_PHUONG_TOA,
            ptha.THA_SO_QD_THA 							AS SO_QD_THA,
            ROW_NUMBER() OVER (
                PARTITION BY ptha.THA_PNLAI_LICH_ID
                ORDER BY NVL(ptha.THA_NGAY_BAN_AN, TO_DATE('01-JAN-1900','DD-MON-YYYY')) DESC,
                         ptha.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN ptha
        LEFT JOIN DM_CO_QUANS       dcq_toa  ON ptha.THA_CAP_TOA_ID            = dcq_toa.ID
        LEFT JOIN DM_TINH_THANH_PHO dttp_toa ON ptha.THA_DIA_PHUONG_CAP_TOA_ID = dttp_toa.ID
        WHERE ptha.THA_PNLAI_LICH_ID IN (SELECT PLL_ID FROM ID_LIST)
    ),
    BO AS (
        SELECT
            tnnt.PHAM_NHAN_ID,
            tnnt.HO_TEN_THAN_NHAN AS TEN_BO,
            tnnt.NOI_O             AS NOI_O_BO
        FROM THAN_NHAN_NGUOI_THANS tnnt
        LEFT JOIN DM_QUAN_HE_VOI_PHAM_NHANS dqhvpn
            ON tnnt.QUAN_HE_ID = dqhvpn.ID
        WHERE dqhvpn.QHVPN_MA = '121'
          AND NVL(tnnt.IS_DELETED, 0) = 0
          AND tnnt.PHAM_NHAN_ID IN (SELECT PLL_ID FROM ID_LIST)
    ),
    ME AS (
        SELECT
            tnnt.PHAM_NHAN_ID,
            tnnt.HO_TEN_THAN_NHAN AS TEN_ME,
            tnnt.NOI_O             AS NOI_O_ME
        FROM THAN_NHAN_NGUOI_THANS tnnt
        LEFT JOIN DM_QUAN_HE_VOI_PHAM_NHANS dqhvpn
            ON tnnt.QUAN_HE_ID = dqhvpn.ID
        WHERE dqhvpn.QHVPN_MA = '122'
          AND NVL(tnnt.IS_DELETED, 0) = 0
          AND tnnt.PHAM_NHAN_ID IN (SELECT PLL_ID FROM ID_LIST)
    )
    SELECT
        pll.LL_HO_TEN                                                AS HoTen,
        dgt.GT_TEN                                                   AS GioiTinh,
        SUBSTR(pll.LL_NGAY_SINH, -4)                                 AS NamSinh,
        pll.LL_TEN_KHAC                                              AS TenKhac,
        CASE
            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'')     IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'')   IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || dxp_thuong_tru.XP_TEN
                            ELSE dxp_thuong_tru.XP_TEN
                        END
                    ELSE u''
                END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'')     IS NOT NULL
                                THEN u', ' || dttp_thuong_tru.TTP_TEN
                            ELSE dttp_thuong_tru.TTP_TEN
                        END
                    ELSE u''
                END
            )
            ELSE NULL
        END                                                          AS DiaChiThuongTru,
        bo.TEN_BO                                                    AS TenBo,
        bo.NOI_O_BO                                                  AS NoiOBo,
        me.TEN_ME                                                    AS TenMe,
        me.NOI_O_ME                                                  AS NoiOMe,
        ptha.THA_AN_PHAT                                             AS AnPhat,
        td_agg.TOI_DANH                                              AS ToiDanh,
        ptha.THA_SO_BAN_AN                                           AS SoBanAn,
        ptha.THA_NGAY_BAN_AN                                         AS NgayBanAn,
        ptha.SO_QD_THA												AS SoQD,
        CASE
            WHEN ptha.CAP_TOA    IS NOT NULL AND ptha.DIA_PHUONG_TOA IS NOT NULL
                THEN ptha.CAP_TOA || u', ' || ptha.DIA_PHUONG_TOA
            WHEN ptha.CAP_TOA    IS NOT NULL THEN ptha.CAP_TOA
            WHEN ptha.DIA_PHUONG_TOA IS NOT NULL THEN ptha.DIA_PHUONG_TOA
            ELSE NULL
        END                                                          AS CapToaDiaPhuong,
        dtg.TG_TEN                                                   AS TenTraiGiam
    FROM PN_LAI_LICHS pll
    JOIN ID_LIST il
        ON pll.ID = il.PLL_ID
    LEFT JOIN LATEST_THA ptha
        ON pll.ID = ptha.THA_PNLAI_LICH_ID
       AND ptha.rn = 1
    LEFT JOIN TOI_DANH_AGG td_agg
        ON pll.ID = td_agg.THA_PNLAI_LICH_ID
    LEFT JOIN BO bo
        ON pll.ID = bo.PHAM_NHAN_ID
    LEFT JOIN ME me
        ON pll.ID = me.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt
        ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
       AND NVL(dgt.IS_DELETED, 0) = 0
    LEFT JOIN DM_TRAI_GIAMS dtg
        ON pll.LL_TRAI_GIAM_ID = dtg.ID
       AND NVL(dtg.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
        ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
       AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
        ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
       AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: '      || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: '   || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GTH_THONG_KE_SO_LIEU_GIAM_MUC_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_GTH_THONG_KE_SO_LIEU_GIAM_MUC_AN" (
--     p_tu_ngay         IN DATE DEFAULT NULL,
--     p_den_ngay        IN DATE DEFAULT NULL,
    p_ngay_xet        IN DATE DEFAULT NULL,
    p_phan_doi_id     IN NUMBER DEFAULT NULL,
    p_ma_doi_tuong    IN NUMBER DEFAULT 0, -- 0: tat ca, 1: co chuong 13, 2: khong co chuong 13
    p_MaxResultCount  IN NUMBER DEFAULT NULL,
    p_SkipCount       IN NUMBER DEFAULT NULL,
    p_ma_trai_giam    IN VARCHAR2 DEFAULT NULL

) AS
    p_cursor SYS_REFCURSOR;
BEGIN
    OPEN p_cursor FOR
    WITH tha_src AS (
        SELECT
            tha.ID,
            tha.THA_PNLAI_LICH_ID,
            tha.THA_TOI_DANH,
            tha.THA_MUC_AN_ID,
            ROW_NUMBER() OVER (
                PARTITION BY tha.THA_PNLAI_LICH_ID
                ORDER BY NVL(tha.LAST_MODIFICATION_TIME, tha.CREATION_TIME) DESC, tha.ID DESC
            ) AS rn
        FROM QLPN.PN_THI_HANH_AN tha
        WHERE tha.IS_DELETED = 0
    ),
    tha_pick AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            s.THA_TOI_DANH,
            s.THA_MUC_AN_ID
        FROM tha_src s
        WHERE s.rn = 1
    ),
    td_split AS (
        SELECT
            t.THA_PNLAI_LICH_ID,
            REPLACE(REPLACE(t.THA_TOI_DANH, '[', ''), ']', '') AS TOI_DANH_ID
        FROM tha_pick t
    ),
    num_gen AS (
        SELECT LEVEL AS n
        FROM DUAL
        CONNECT BY LEVEL <= 30
    ),
    split_toi_danh AS (
        SELECT
            ts.THA_PNLAI_LICH_ID,
            TO_NUMBER(TRIM(REGEXP_SUBSTR(ts.TOI_DANH_ID, '[^,]+', 1, ng.n))) AS TOI_DANH_ID
        FROM td_split ts
        JOIN num_gen ng
            ON ng.n <= REGEXP_COUNT(ts.TOI_DANH_ID, ',') + 1
        WHERE REGEXP_SUBSTR(ts.TOI_DANH_ID, '[^,]+', 1, ng.n) IS NOT NULL
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(ts.TOI_DANH_ID, '[^,]+', 1, ng.n)), '^[0-9]+$')
    ),
    td_agg AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            LISTAGG(DISTINCT td.TD_CHUONG, ', ') WITHIN GROUP (ORDER BY td.TD_TEN) AS TOI_DANH_CHUONGS
        FROM split_toi_danh s
        LEFT JOIN QLPN.DM_TOI_DANHS td
            ON td.ID = s.TOI_DANH_ID
           AND td.IS_DELETED = 0
        GROUP BY s.THA_PNLAI_LICH_ID
    ),
    base AS (
        SELECT
            gth.PHAM_NHAN_ID,
            gth.NGAY_XET,
            gth.MUC_DE_NGHI_ID,
            gth.CAP_TREN_DUYET_ID,
            gth.MUC_GIAM_ID,
            ll.PHAN_DOI_ID,
            UPPER(NVL(ll.GIOI_TINH, '')) AS GIOI_TINH_UPPER,
            tp.THA_MUC_AN_ID,
            tda.TOI_DANH_CHUONGS
        FROM QLPN.GIAM_THOI_HANS gth
        LEFT JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET ll
            ON ll.PHAM_NHAN_ID = gth.PHAM_NHAN_ID
            AND ll.IS_DELETED = 0
        LEFT JOIN tha_pick tp
            ON tp.THA_PNLAI_LICH_ID = gth.PHAM_NHAN_ID
        LEFT JOIN td_agg tda
            ON tda.THA_PNLAI_LICH_ID = gth.PHAM_NHAN_ID
        WHERE gth.IS_DELETED = 0
           AND( p_ma_trai_giam IS NULL OR ll.TRAI_GIAM_MA = p_ma_trai_giam)
          AND (p_ngay_xet IS NULL OR gth.NGAY_XET = p_ngay_xet)
          AND (p_phan_doi_id IS NULL OR ll.PHAN_DOI_ID = p_phan_doi_id)
          AND (
                p_ma_doi_tuong = 0 OR p_ma_doi_tuong IS NULL
                OR (p_ma_doi_tuong = 1 AND tda.TOI_DANH_CHUONGS LIKE '%13%')
                OR (p_ma_doi_tuong = 2 AND (tda.TOI_DANH_CHUONGS NOT LIKE '%13%' OR tda.TOI_DANH_CHUONGS IS NULL))
              )
    ),
    agg AS (
        SELECT
            b.THA_MUC_AN_ID AS MUC_AN_ID,
            CAST(ma.MA_MA AS NVARCHAR2(50)) AS MUC_AN_MA,
            CAST(ma.MA_TEN_CHI_TIEU AS NVARCHAR2(2000)) AS MUC_AN_TEN,

            COUNT(DISTINCT CASE WHEN b.MUC_DE_NGHI_ID IS NOT NULL AND b.GIOI_TINH_UPPER = u'NAM' THEN b.PHAM_NHAN_ID END) AS TRAI_DUYET_NAM,
            COUNT(DISTINCT CASE WHEN b.MUC_DE_NGHI_ID IS NOT NULL AND b.GIOI_TINH_UPPER IN (u'N\1eee', u'NU') THEN b.PHAM_NHAN_ID END) AS TRAI_DUYET_NU,
            COUNT(DISTINCT CASE WHEN b.MUC_DE_NGHI_ID IS NOT NULL AND (b.GIOI_TINH_UPPER NOT IN (u'NAM', u'N\1eee', u'NU') OR b.GIOI_TINH_UPPER IS NULL OR b.GIOI_TINH_UPPER = '') THEN b.PHAM_NHAN_ID END) AS TRAI_DUYET_KHAC,
            COUNT(DISTINCT CASE WHEN b.MUC_DE_NGHI_ID IS NOT NULL THEN b.PHAM_NHAN_ID END) AS TRAI_DUYET_TONG,

            COUNT(DISTINCT CASE WHEN b.CAP_TREN_DUYET_ID IS NOT NULL AND b.GIOI_TINH_UPPER = u'NAM' THEN b.PHAM_NHAN_ID END) AS BCA_DUYET_NAM,
            COUNT(DISTINCT CASE WHEN b.CAP_TREN_DUYET_ID IS NOT NULL AND b.GIOI_TINH_UPPER IN (u'N\1eee', u'NU') THEN b.PHAM_NHAN_ID END) AS BCA_DUYET_NU,
            COUNT(DISTINCT CASE WHEN b.CAP_TREN_DUYET_ID IS NOT NULL AND (b.GIOI_TINH_UPPER NOT IN (u'NAM', u'N\1eee', u'NU') OR b.GIOI_TINH_UPPER IS NULL OR b.GIOI_TINH_UPPER = '') THEN b.PHAM_NHAN_ID END) AS BCA_DUYET_KHAC,
            COUNT(DISTINCT CASE WHEN b.CAP_TREN_DUYET_ID IS NOT NULL THEN b.PHAM_NHAN_ID END) AS BCA_DUYET_TONG,

            COUNT(DISTINCT CASE WHEN b.MUC_GIAM_ID IS NOT NULL AND b.GIOI_TINH_UPPER = u'NAM' THEN b.PHAM_NHAN_ID END) AS TOA_DUYET_NAM,
            COUNT(DISTINCT CASE WHEN b.MUC_GIAM_ID IS NOT NULL AND b.GIOI_TINH_UPPER IN (u'N\1eee', u'NU') THEN b.PHAM_NHAN_ID END) AS TOA_DUYET_NU,
            COUNT(DISTINCT CASE WHEN b.MUC_GIAM_ID IS NOT NULL AND (b.GIOI_TINH_UPPER NOT IN (u'NAM', u'N\1eee', u'NU') OR b.GIOI_TINH_UPPER IS NULL OR b.GIOI_TINH_UPPER = '') THEN b.PHAM_NHAN_ID END) AS TOA_DUYET_KHAC,
            COUNT(DISTINCT CASE WHEN b.MUC_GIAM_ID IS NOT NULL THEN b.PHAM_NHAN_ID END) AS TOA_DUYET_TONG
        FROM base b
        LEFT JOIN QLPN.DM_MUC_ANS ma
            ON ma.ID = b.THA_MUC_AN_ID
           AND ma.IS_DELETED = 0
        GROUP BY
            b.THA_MUC_AN_ID,
            ma.MA_MA,
            ma.MA_TEN_CHI_TIEU
    ),
    ordered_data AS (
        SELECT
            a.*,
            COUNT(*) OVER() AS TOTAL_COUNT,
            ROW_NUMBER() OVER (
                ORDER BY
                    CASE WHEN REGEXP_LIKE(a.MUC_AN_MA, '^[0-9]+$') THEN TO_NUMBER(a.MUC_AN_MA) END NULLS LAST,
                    a.MUC_AN_MA,
                    a.MUC_AN_ID
            ) AS RN
        FROM agg a
    )
    SELECT
        MUC_AN_ID,
        MUC_AN_MA,
        MUC_AN_TEN,
        TRAI_DUYET_NAM,
        TRAI_DUYET_NU,
        TRAI_DUYET_KHAC,
        TRAI_DUYET_TONG,
        BCA_DUYET_NAM,
        BCA_DUYET_NU,
        BCA_DUYET_KHAC,
        BCA_DUYET_TONG,
        TOA_DUYET_NAM,
        TOA_DUYET_NU,
        TOA_DUYET_KHAC,
        TOA_DUYET_TONG,
        TOTAL_COUNT
    FROM ordered_data
    WHERE
        (NVL(p_MaxResultCount, 0) = 0 AND NVL(p_SkipCount, 0) = 0)
        OR (
            NVL(p_MaxResultCount, 0) > 0
            AND RN > NVL(p_SkipCount, 0)
            AND RN <= NVL(p_SkipCount, 0) + NVL(p_MaxResultCount, 0)
        )
    ORDER BY RN;

    DBMS_SQL.RETURN_RESULT(p_cursor);
EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('L?i: ' || SQLERRM);
        RAISE;
END SP_GET_GTH_THONG_KE_SO_LIEU_GIAM_MUC_AN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GTH_THONG_KE_TAT_CA_KY_GIAM_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_GTH_THONG_KE_TAT_CA_KY_GIAM_AN" (
    p_tu_ngay       IN DATE DEFAULT NULL,
    p_den_ngay      IN DATE DEFAULT NULL,
    p_ngay_xet      IN DATE DEFAULT NULL,
    p_phan_doi_id   IN NUMBER DEFAULT NULL,
    p_ma_doi_tuong  IN NUMBER DEFAULT 0, -- 0: tat ca, 1: co chuong 13, 2: khong co chuong 13
    p_ma_trai_giam IN VARCHAR2 default null
) AS
    p_cursor SYS_REFCURSOR;
BEGIN
    OPEN p_cursor FOR
    WITH tha_src AS (
        SELECT
            tha.ID,
            tha.THA_PNLAI_LICH_ID,
            tha.THA_TOI_DANH,
            ROW_NUMBER() OVER (
                PARTITION BY tha.THA_PNLAI_LICH_ID
                ORDER BY NVL(tha.LAST_MODIFICATION_TIME, tha.CREATION_TIME) DESC, tha.ID DESC
            ) AS rn
        FROM QLPN.PN_THI_HANH_AN tha
        WHERE tha.IS_DELETED = 0
    ),
    tha_pick AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            s.THA_TOI_DANH
        FROM tha_src s
        WHERE s.rn = 1
    ),
    td_split AS (
        SELECT
            t.THA_PNLAI_LICH_ID,
            REPLACE(REPLACE(t.THA_TOI_DANH, '[', ''), ']', '') AS TOI_DANH_ID
        FROM tha_pick t
    ),
    num_gen AS (
        SELECT LEVEL AS n
        FROM DUAL
        CONNECT BY LEVEL <= 30
    ),
    split_toi_danh AS (
        SELECT
            ts.THA_PNLAI_LICH_ID,
            TO_NUMBER(TRIM(REGEXP_SUBSTR(ts.TOI_DANH_ID, '[^,]+', 1, ng.n))) AS TOI_DANH_ID
        FROM td_split ts
        JOIN num_gen ng
            ON ng.n <= REGEXP_COUNT(ts.TOI_DANH_ID, ',') + 1
        WHERE REGEXP_SUBSTR(ts.TOI_DANH_ID, '[^,]+', 1, ng.n) IS NOT NULL
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(ts.TOI_DANH_ID, '[^,]+', 1, ng.n)), '^[0-9]+$')
    ),
    toi_danh_flags AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            MAX(CASE WHEN td.TD_CHUONG = '13' THEN 1 ELSE 0 END) AS HAS_CHUONG_13
        FROM split_toi_danh s
        JOIN QLPN.DM_TOI_DANHS td
            ON td.ID = s.TOI_DANH_ID
           AND td.IS_DELETED = 0
        GROUP BY s.THA_PNLAI_LICH_ID
    ),
    gth_filtered AS (
        SELECT
            gth.PHAM_NHAN_ID,
            TRUNC(gth.NGAY_XET) AS NGAY_XET_GIAM,
            gth.MUC_GIAM_ID,
            gth.NGAY_XET
        FROM QLPN.GIAM_THOI_HANS gth
        WHERE gth.IS_DELETED = 0
          AND gth.MUC_GIAM_ID IS NOT NULL
          AND (p_tu_ngay IS NULL OR gth.NGAY_XET >= TRUNC(p_tu_ngay))
          AND (p_den_ngay IS NULL OR gth.NGAY_XET < TRUNC(p_den_ngay) + 1)
          AND (
                p_ngay_xet IS NULL
                OR (gth.NGAY_XET >= TRUNC(p_ngay_xet) AND gth.NGAY_XET < TRUNC(p_ngay_xet) + 1)
              )
    ),
    base AS (
        SELECT
            gth.NGAY_XET_GIAM,
            gth.PHAM_NHAN_ID,
            gth.MUC_GIAM_ID,
            UPPER(NVL(ll.GIOI_TINH, '')) AS GIOI_TINH_UPPER,
            ll.PHAN_DOI_ID,
            NVL(tdf.HAS_CHUONG_13, 0) AS HAS_CHUONG_13
        FROM gth_filtered gth
        LEFT JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET ll
            ON ll.PHAM_NHAN_ID = gth.PHAM_NHAN_ID
        LEFT JOIN toi_danh_flags tdf
            ON tdf.THA_PNLAI_LICH_ID = gth.PHAM_NHAN_ID
        WHERE 1 = 1
        AND( p_ma_trai_giam IS NULL OR ll.TRAI_GIAM_MA = p_ma_trai_giam)
          AND (p_phan_doi_id IS NULL OR ll.PHAN_DOI_ID = p_phan_doi_id)
          AND (
                p_ma_doi_tuong = 0 OR p_ma_doi_tuong IS NULL
                OR (p_ma_doi_tuong = 1 AND NVL(tdf.HAS_CHUONG_13, 0) = 1)
                OR (p_ma_doi_tuong = 2 AND NVL(tdf.HAS_CHUONG_13, 0) = 0)
              )
    ),
    ky_order AS (
        SELECT
            d.KGTH_NGAY_XET_GIAM as NGAY_XET_GIAM,
            DENSE_RANK() OVER (ORDER BY d.KGTH_NGAY_XET_GIAM DESC) AS KY_SORT
        FROM GTH_KY_GIAM_THOI_HANS d
    ),
    ky_header AS (
        SELECT
            CAST(ko.KY_SORT AS NUMBER) AS SORT_ORDER,
            '-' AS LOAI_DONG,
            CAST(NULL AS NUMBER) AS TT,
            b.NGAY_XET_GIAM,
            CAST(NULL AS NUMBER) AS MUC_GIAM_ID,
            CAST(NULL AS NVARCHAR2(2000)) AS MUC_GIAM,
            CAST(COUNT(DISTINCT CASE WHEN b.GIOI_TINH_UPPER = u'NAM' THEN b.PHAM_NHAN_ID END) AS NUMBER) AS NAM,
            CAST(COUNT(DISTINCT CASE WHEN b.GIOI_TINH_UPPER IN (u'N\1eee', u'NU') THEN b.PHAM_NHAN_ID END) AS NUMBER) AS NU,
            CAST(COUNT(DISTINCT CASE WHEN b.GIOI_TINH_UPPER NOT IN (u'NAM', u'N\1eee', u'NU') OR b.GIOI_TINH_UPPER IS NULL OR b.GIOI_TINH_UPPER = '' THEN b.PHAM_NHAN_ID END) AS NUMBER) AS KHAC,
            CAST(COUNT(DISTINCT b.PHAM_NHAN_ID) AS NUMBER) AS TONG_SO
        FROM base b
        JOIN ky_order ko
            ON ko.NGAY_XET_GIAM >= TRUNC(b.NGAY_XET_GIAM)
            AND ko.NGAY_XET_GIAM <  TRUNC(b.NGAY_XET_GIAM) + 1
        GROUP BY
            ko.KY_SORT,
            b.NGAY_XET_GIAM
    ),
    detail_group AS (
        SELECT
            b.NGAY_XET_GIAM,
            b.MUC_GIAM_ID,
            COUNT(DISTINCT CASE WHEN b.GIOI_TINH_UPPER = u'NAM' THEN b.PHAM_NHAN_ID END) AS NAM,
            COUNT(DISTINCT CASE WHEN b.GIOI_TINH_UPPER IN (u'N\1eee', u'NU') THEN b.PHAM_NHAN_ID END) AS NU,
            COUNT(DISTINCT CASE WHEN b.GIOI_TINH_UPPER NOT IN (u'NAM', u'N\1eee', u'NU') OR b.GIOI_TINH_UPPER IS NULL OR b.GIOI_TINH_UPPER = '' THEN b.PHAM_NHAN_ID END) AS KHAC,
            COUNT(DISTINCT b.PHAM_NHAN_ID) AS TONG_SO
        FROM base b
        GROUP BY
            b.NGAY_XET_GIAM,
            b.MUC_GIAM_ID
    ),
    detail_ranked AS (
        SELECT
            ko.KY_SORT,
            ROW_NUMBER() OVER (
                PARTITION BY dg.NGAY_XET_GIAM
                ORDER BY
                    NVL(dm.MTG_NAM, 0) DESC,
                    NVL(dm.MTG_THANG, 0) DESC,
                    NVL(dm.MTG_NGAY, 0) DESC,
                    dg.MUC_GIAM_ID
            ) AS RN,
            dg.NGAY_XET_GIAM,
            dg.MUC_GIAM_ID,
            dm.MTG_TITLE,
            dg.NAM,
            dg.NU,
            dg.KHAC,
            dg.TONG_SO
        FROM detail_group dg
        JOIN ky_order ko
            ON ko.NGAY_XET_GIAM = dg.NGAY_XET_GIAM
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dm
            ON dm.ID = dg.MUC_GIAM_ID
           AND NVL(dm.IS_DELETED, 0) = 0
    ),
    detail_rows AS (
        SELECT
            CAST(dr.KY_SORT + dr.RN * 0.01 AS NUMBER) AS SORT_ORDER,
            '+' AS LOAI_DONG,
            CAST(dr.RN AS NUMBER) AS TT,
            dr.NGAY_XET_GIAM,
            CAST(dr.MUC_GIAM_ID AS NUMBER) AS MUC_GIAM_ID,
            CAST(dr.MTG_TITLE AS NVARCHAR2(2000)) AS MUC_GIAM,
            CAST(dr.NAM AS NUMBER) AS NAM,
            CAST(dr.NU AS NUMBER) AS NU,
            CAST(dr.KHAC AS NUMBER) AS KHAC,
            CAST(dr.TONG_SO AS NUMBER) AS TONG_SO
        FROM detail_ranked dr
    )
    SELECT
        u.TT,
        u.NGAY_XET_GIAM,
        u.MUC_GIAM,
        u.NAM,
        u.NU,
        u.KHAC,
        u.TONG_SO,
        COUNT(*) OVER () AS TOTAL_ROW_COUNT
    FROM (
        SELECT
            SORT_ORDER,
            NULL AS TT,
            TO_NCHAR(NGAY_XET_GIAM, 'dd/mm/yyyy') AS NGAY_XET_GIAM,
            MUC_GIAM,
            NAM,
            NU,
            KHAC,
            TONG_SO
        FROM ky_header
        UNION ALL
        SELECT
           SORT_ORDER,
            TT,
            NULL AS NGAY_XET_GIAM,
            MUC_GIAM,
            NAM,
            NU,
            KHAC,
            TONG_SO
        FROM detail_rows
    ) u
    ORDER BY u.SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(p_cursor);
EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Loi: ' || SQLERRM);
        RAISE;
END SP_GET_GTH_THONG_KE_TAT_CA_KY_GIAM_AN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GTH_TK_KHONG_GIAM_THOI_HAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_GTH_TK_KHONG_GIAM_THOI_HAN" (
    p_dot_giam_id  IN DATE,
    p_phan_doi_id  IN NUMBER DEFAULT NULL,
    p_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ma_trai_giam IN varchar2 default null
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam' AND TRIM(mtg_bca.MTG_TITLE) = 'Không' THEN gth.PHAM_NHAN_ID END) AS "BoCongAnNam",
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'  AND TRIM(mtg_bca.MTG_TITLE) = 'Không' THEN gth.PHAM_NHAN_ID END) AS "BoCongAnNu",
        COUNT(DISTINCT CASE WHEN                        TRIM(mtg_bca.MTG_TITLE) = 'Không' THEN gth.PHAM_NHAN_ID END) AS "BoCongAnTong",
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam' AND TRIM(mtg_toa.MTG_TITLE) = 'Không' THEN gth.PHAM_NHAN_ID END) AS "ToaQuyetDinhNam",
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'  AND TRIM(mtg_toa.MTG_TITLE) = 'Không' THEN gth.PHAM_NHAN_ID END) AS "ToaQuyetDinhNu",
        COUNT(DISTINCT CASE WHEN                        TRIM(mtg_toa.MTG_TITLE) = 'Không' THEN gth.PHAM_NHAN_ID END) AS "ToaQuyetDinhTong"
    FROM GIAM_THOI_HANS gth
    JOIN PN_LAI_LICHS pll
        ON gth.PHAM_NHAN_ID = pll.ID
       AND (p_phan_doi_id IS NULL OR pll.LL_PHAN_DOI_ID = p_phan_doi_id)
       AND( p_ma_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
    LEFT JOIN DM_GIOI_TINHS dgt
        ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_MA_THOI_GIANS mtg_bca 
        ON gth.CAP_TREN_DUYET_ID = mtg_bca.ID
    LEFT JOIN DM_MA_THOI_GIANS mtg_toa 
        ON gth.MUC_GIAM_ID = mtg_toa.ID
    LEFT JOIN (
        SELECT ptha.THA_PNLAI_LICH_ID,
               CASE WHEN COUNT(CASE WHEN td.TD_CHUONG = '13' THEN 1 END) > 0
                    THEN 1 ELSE 2
               END AS DOI_TUONG_ID
          FROM PN_THI_HANH_AN ptha
          JOIN (
              SELECT ptha2.THA_PNLAI_LICH_ID,
                     TO_NUMBER(TRIM(REGEXP_SUBSTR(
                         REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''),
                         '[^,]+', 1, n.N
                     ))) AS TOI_DANH_ID
                FROM PN_THI_HANH_AN ptha2
                JOIN (SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL <= 20) n
                  ON n.N <= REGEXP_COUNT(
                         REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''), ','
                     ) + 1
               WHERE ptha2.THA_TOI_DANH IS NOT NULL
                 AND NVL(ptha2.IS_DELETED, 0) = 0
          ) td_split ON td_split.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
          JOIN DM_TOI_DANHS td ON td.ID = td_split.TOI_DANH_ID
         WHERE NVL(ptha.IS_DELETED, 0) = 0
         GROUP BY ptha.THA_PNLAI_LICH_ID
    ) doi_tuong ON doi_tuong.THA_PNLAI_LICH_ID = pll.ID
    WHERE NVL(gth.IS_DELETED, 0) = 0
      AND TRUNC(CAST(gth.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
      AND (p_doi_tuong_id IS NULL OR doi_tuong.DOI_TUONG_ID = p_doi_tuong_id)
      AND (TRIM(mtg_bca.MTG_TITLE) = 'Không' OR TRIM(mtg_toa.MTG_TITLE) = 'Không');

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            u'L?i SP_GET_GTH_TK_KHONG_GIAM_THOI_HAN: ' || SQLERRM);
END SP_GET_GTH_TK_KHONG_GIAM_THOI_HAN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_HINH_PHAT_BO_SUNG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_HINH_PHAT_BO_SUNG" (
    p_PHAM_NHAN_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        phpbs.HPBS_MA_PHAM_NHAN,
        dhpbs.HPBS_TEN  AS "HinhPhat",
        dmtg.MTG_TITLE  AS "ThoiHan",
        phpbs.HPBS_GHI_CHU_CHI_TIET AS "GhiChu"
    FROM PN_HINH_PHAT_BO_SUNGS phpbs
    JOIN DM_HINH_PHAT_BO_SUNGS dhpbs ON phpbs.HPBS_HINH_PHAT = dhpbs.ID
    JOIN DM_MA_THOI_GIANS dmtg ON phpbs.HPBS_THOI_HAN = dmtg.ID
    WHERE phpbs.HPBS_MA_PHAM_NHAN = p_PHAM_NHAN_ID
	AND dhpbs.HPBS_MA IN ('110','120','130','140','150','160','170','310')
	AND phpbs.IS_DELETED = 0;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_HINH_PHAT_BO_SUNG;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_HOAN_THI_HANH_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_HOAN_THI_HANH_AN" (
    p_PHAM_NHAN_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        htha.PHAM_NHAN_ID,
        htha.SO_QUYET_DINH  AS "SoQD",
        htha.NGAY_QUYET_DINH  AS "NgayQD",
        dcq.CQ_TEN  AS "ToaQD",
        htha.LY_DO_HOAN AS "LyDoHoan",
        htha.NGAY_THI_HANH_AN AS "NgayThiHanh"
    FROM HOAN_THI_HANH_ANS htha  
    LEFT JOIN DM_CO_QUANS dcq ON htha.TOA_QUYET_DINH_ID = dcq.ID
    WHERE htha.PHAM_NHAN_ID = p_PHAM_NHAN_ID
	AND htha.IS_DELETED = 0;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_HOAN_THI_HANH_AN;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_HOC_SINH_PHIEU_LAI_LICH_ALL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_HOC_SINH_PHIEU_LAI_LICH_ALL" (
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_HOC_SINH_ID IN NUMBER
)
IS
    v_cur_main            SYS_REFCURSOR;
    v_cur_anh_chi_em      SYS_REFCURSOR;
    v_cur_chet            SYS_REFCURSOR;
    v_cur_giam_thoi_han   SYS_REFCURSOR;
    v_cur_ra_truong       SYS_REFCURSOR;
    v_cur_tam_dinh_chi    SYS_REFCURSOR;
    v_cur_tam_thoi_dua_ra SYS_REFCURSOR;
    v_cur_tien_an         SYS_REFCURSOR;
    v_cur_tien_su         SYS_REFCURSOR;
    v_cur_tron            SYS_REFCURSOR;
    v_cur_xep_loai        SYS_REFCURSOR;
BEGIN

    -- ===================== MAIN =====================
    OPEN v_cur_main FOR
     WITH split_hanh_vi AS (
        SELECT
            hhvvp.ID AS HVVP_ID,
            TO_NUMBER(
                REGEXP_SUBSTR(
                    REPLACE(REPLACE(hhvvp.HVVP_HANH_VI, '[', ''), ']', ''),
                    '[0-9]+', 1, LEVEL
                )
            ) AS HANH_VI_ID
        FROM HS_HANH_VI_VI_PHAMS hhvvp
        WHERE hhvvp.HVVP_HSLAI_LICH_ID = p_HOC_SINH_ID
          AND hhvvp.HVVP_HANH_VI IS NOT NULL
          AND hhvvp.IS_DELETED = 0
        CONNECT BY LEVEL <= REGEXP_COUNT(
                       REPLACE(REPLACE(hhvvp.HVVP_HANH_VI, '[', ''), ']', ''), ',') + 1
               AND PRIOR hhvvp.ID = hhvvp.ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    hanh_vi_agg AS (
        SELECT
            s.HVVP_ID,
            LISTAGG(DISTINCT dtd.TD_TEN, ', ')
                WITHIN GROUP (ORDER BY dtd.TD_TEN) AS HANH_VI_TEN
        FROM split_hanh_vi s
        LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.HANH_VI_ID
        GROUP BY s.HVVP_ID
    ),

    /*==========================================================
      CTE TÁCH M?NG GHI CHÚ RIÊNG
    ==========================================================*/
    split_ghi_chu AS (
        SELECT
            hll.ID AS HOC_SINH_ID,
            TO_NUMBER(TRIM(REGEXP_SUBSTR(REPLACE(REPLACE(hll.LL_GHI_CHU_RIENG, '[', ''), ']', ''), '[^,]+', 1, LEVEL))) AS GHI_CHU_ID
        FROM HS_LAI_LICHS hll
        WHERE hll.ID = p_HOC_SINH_ID
           AND (p_ma_trai_giam IS NULL OR hll.LL_MA_TRAI_GIAM = p_ma_trai_giam)
          AND hll.LL_GHI_CHU_RIENG IS NOT NULL
          AND hll.IS_DELETED = 0
        CONNECT BY LEVEL <= REGEXP_COUNT(
                       REPLACE(REPLACE(hll.LL_GHI_CHU_RIENG, '[', ''), ']', ''), ',') + 1
               AND PRIOR hll.ID = hll.ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    ghi_chu_agg AS (
        SELECT
            s.HOC_SINH_ID,
            LISTAGG(dgcr.GCR_TEN, '; ') WITHIN GROUP (ORDER BY dgcr.GCR_TEN) AS GHI_CHU_RIENG
        FROM split_ghi_chu s
        LEFT JOIN DM_GHI_CHU_RIENGS dgcr ON dgcr.ID = s.GHI_CHU_ID
        GROUP BY s.HOC_SINH_ID
    ),
    /*==========================================================
      CTE TÁCH M?NG S?C KH?E KHI VÀO
      - D? li?u l?u d?ng: ["99"] ho?c ["1","2"]
      - C?n b? [ ] và d?u " tr??c khi tách theo d?u ph?y
    ==========================================================*/
    split_suc_khoe AS (
        SELECT
            hll.ID AS HOC_SINH_ID,
            TO_NUMBER(TRIM(REGEXP_SUBSTR(
                REPLACE(REPLACE(REPLACE(hll.LL_SUC_KHOE_KHI_VAO_ID, '[', ''), ']', ''), '"', ''),
                '[^,]+', 1, LEVEL
            ))) AS SUC_KHOE_ID
        FROM HS_LAI_LICHS hll
        WHERE hll.ID = p_HOC_SINH_ID
          AND (p_ma_trai_giam IS NULL OR hll.LL_MA_TRAI_GIAM = p_ma_trai_giam)
          AND hll.LL_SUC_KHOE_KHI_VAO_ID IS NOT NULL
          AND hll.IS_DELETED = 0
        CONNECT BY LEVEL <= REGEXP_COUNT(
                       REPLACE(REPLACE(REPLACE(hll.LL_SUC_KHOE_KHI_VAO_ID, '[', ''), ']', ''), '"', ''), ',') + 1
               AND PRIOR hll.ID = hll.ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    suc_khoe_agg AS (
        SELECT
            s.HOC_SINH_ID,
            LISTAGG(DISTINCT dsk.SK_ND, ', ') WITHIN GROUP (ORDER BY dsk.SK_ND) AS SUC_KHOE
        FROM split_suc_khoe s
        LEFT JOIN DM_SUC_KHOE dsk
               ON dsk.ID = s.SUC_KHOE_ID
              AND NVL(dsk.IS_DELETED, 0) = 0
        GROUP BY s.HOC_SINH_ID
    ),
    /*==========================================================
      CTE TÍNH TH?I GIAN TR?N
      - Ch? tính l?n tr?n ?ã có ngày b?t l?i
      - Dùng MONTHS_BETWEEN ?? tính chính xác tháng/ngày
    ==========================================================*/
    tron_agg AS (
        SELECT
            tt.TT_HS_LAI_LICH_ID                                       AS LAI_LICH_ID,
            SUM(TRUNC(tt.TT_NGAY_BAT_LAI) - TRUNC(tt.TT_NGAY_TRON) + 1) AS TONG_NGAY_RAW
        FROM HS_TRON_TRUONGS tt
        WHERE NVL(tt.IS_DELETED, 0) = 0
          AND tt.TT_NGAY_TRON    IS NOT NULL
          AND tt.TT_NGAY_BAT_LAI IS NOT NULL
        GROUP BY tt.TT_HS_LAI_LICH_ID
    ),

    /*==========================================================
      CTE TÍNH TH?I GIAN T?M ?ÌNH CH?
    ==========================================================*/
    tdc_agg AS (
        SELECT
            tdc.HOC_SINH_ID                                              AS LAI_LICH_ID,
            SUM(TRUNC(tdc.NGAY_LAI) - TRUNC(tdc.TU_NGAY) + 1)          AS TONG_NGAY_RAW
        FROM HS_TAM_DINH_CHIS tdc
        WHERE NVL(tdc.IS_DELETED, 0) = 0
          AND tdc.DA_HUY   = 0
          AND tdc.TU_NGAY  IS NOT NULL
          AND tdc.NGAY_LAI IS NOT NULL
        GROUP BY tdc.HOC_SINH_ID
    ),

    /*==========================================================
      CTE L?Y NGÀY MI?N CH?P HÀNH (m?i nh?t)
      - T? HS_MIEN_CHAP_HANHS
    ==========================================================*/
    mien_agg AS (
        SELECT
            mhp.MHP_HS_LAI_LICH_ID            AS LAI_LICH_ID,
            CAST(mhp.MHP_NGAY_RA AS DATE)     AS NGAY_RA,
            mhp.MHP_SO_QUYET_DINH             AS SO_QD
        FROM (
            SELECT m.*,
                   ROW_NUMBER() OVER (
                       PARTITION BY m.MHP_HS_LAI_LICH_ID
                       ORDER BY m.MHP_NGAY_QUYET_DINH DESC
                   ) AS rn
              FROM HS_MIEN_CHAP_HANHS m
             WHERE NVL(m.IS_DELETED, 0) = 0
               AND m.MHP_NGAY_RA IS NOT NULL
        ) mhp
        WHERE mhp.rn = 1
    )

    SELECT
        /*------------------------------------------------------
          THÔNG TIN C? B?N
        ------------------------------------------------------*/
        hll.LL_SO_HO_SO_LAN_DAU                        AS SO_HSLD,
        dtths.TTPN_TEN                                  AS TINH_TRANG,
        hll.LL_HO_TEN                                   AS HO_TEN,
        dgt.GT_TEN                                      AS GIOI_TINH,
        hll.LL_TEN_KHAC                                 AS TEN_KHAC,
        hll.LL_NGAY_SINH       AS NGAY_SINH,
        dttp.TTP_TEN                                    AS NGUYEN_QUAN,

        /*------------------------------------------------------
          ??A CH? TH??NG TRÚ (ghép: s? nhà + xã/ph??ng + t?nh)
        ------------------------------------------------------*/
        CASE
            WHEN NULLIF(TRIM(hll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'')     IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'')    IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(hll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(hll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                             THEN u', ' || dxp_thuong_tru.XP_TEN
                             ELSE dxp_thuong_tru.XP_TEN END
                    ELSE u'' END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(hll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'')      IS NOT NULL
                             THEN u', ' || dttp_thuong_tru.TTP_TEN
                             ELSE dttp_thuong_tru.TTP_TEN END
                    ELSE u'' END
            )
            ELSE NULL
        END                                             AS DIA_CHI_THUONG_TRU,

        hll.LL_NOI_OTRUOC_KHI_BAT                      AS CHO_O_TRUOC_KHI_VAO,
        ddt.DT_TEN                                      AS DAN_TOC,
        dtg.TG_TEN                                      AS TON_GIAO,
        dhv.HV_ND                                      AS HOC_VAN,
        dnn.NN_TEN                                      AS NGHE_NGHIEP,
        dncd.NCD_ND 									AS NOI_CHUYEN_DEN,

        /*------------------------------------------------------
          THÂN NHÂN
        ------------------------------------------------------*/----
        nvl(hll.LL_HO_TEN_CHA, bo.HO_TEN_THAN_NHAN)                             AS TEN_BO,
        CASE
            WHEN hll.LL_NGAY_SINH_CHA IS NOT NULL AND TRIM(hll.LL_NGAY_SINH_CHA) IS NOT NULL
                THEN TRIM(CAST(hll.LL_NGAY_SINH_CHA AS NVARCHAR2(20)))
            ELSE CAST(TO_CHAR(CAST(bo.NGAY_SINH AS DATE), 'DD/MM/YYYY') AS NVARCHAR2(20))
        END AS NGAY_SINH_BO,
        --NVL(TO_CHAR(hll.LL_NGAY_SINH_CHA, 'DD/MM/YYYY') , TO_CHAR(bo.NGAY_SINH, 'DD/MM/YYYY')  )          AS NGAY_SINH_BO,
        nvl(dnn_bo_ll.NN_TEN, dnn_bo.NN_TEN)                               AS NGHE_NGHIEP_BO,
        nvl(hll.LL_HO_TEN_ME, me.HO_TEN_THAN_NHAN)                             AS TEN_ME,
        CASE
            WHEN hll.LL_NGAY_SINH_ME IS NOT NULL AND TRIM(hll.LL_NGAY_SINH_ME) IS NOT NULL
                THEN TRIM(CAST(hll.LL_NGAY_SINH_ME AS NVARCHAR2(20)))
            ELSE CAST(TO_CHAR(CAST(me.NGAY_SINH AS DATE), 'DD/MM/YYYY') AS NVARCHAR2(20))
        END AS NGAY_SINH_ME,
        nvl(dnn_me_ll.NN_TEN, dnn_me.NN_TEN)                               AS NGHE_NGHIEP_ME,

        /*------------------------------------------------------
          THÔNG TIN KHÁC
        ------------------------------------------------------*/
        ska.SUC_KHOE                                       AS SUC_KHOE_KHI_VAO,
        CASE WHEN hll.LL_SO_TIEN_AN IS NULL THEN u'Không'
             ELSE hll.LL_SO_TIEN_AN END                 AS SO_TIEN_AN,
        CASE WHEN hll.LL_SO_TIEN_SU IS NULL THEN u'Không'
             ELSE hll.LL_SO_TIEN_SU END                 AS SO_TIEN_SU,
        hhvvp.HVVP_SO_LAN_VAO                          AS SO_LAN_VAO,
        gc_agg.GHI_CHU_RIENG                            AS GHI_CHU_RIENG,
        hva.HANH_VI_TEN                                 AS HANH_VI_VI_PHAM,

        /*------------------------------------------------------
          THÔNG TIN QUY?T ??NH
        ------------------------------------------------------*/
        hhvvp.HVVP_SO_DE_NGHI                          AS SO_QD,
        TO_CHAR(hhvvp.HVVP_NGAY_QUYET_DINH, 'DD/MM/YYYY') AS NGAY_QD,
        dcq2.CQ_TEN                                     AS CO_QUAN_QD,
        hhvvp.HVVP_THOI_HAN                            AS AN_PHAT,
        TO_CHAR(hhvvp.HVVP_NGAY_DUA_DI, 'DD/MM/YYYY') AS NGAY_DUA_DI,
        TO_CHAR(hhvvp.HVVP_NGAY_VAO,    'DD/MM/YYYY') AS NGAY_VAO,

        NULL                                            AS TRUONG_GIAO_DUONG,
        dpd.PD_TEN                                      AS PHAN_DOI,

        /*------------------------------------------------------
          TH?I GIAN TR?N
          Dùng MONTHS_BETWEEN ?? tính chính xác n?m/tháng/ngày:
          - L?y t?ng ngày raw t? CTE
          - Quy ??i: n?m = FLOOR(t?ng_tháng / 12)
                     tháng còn l?i = MOD(t?ng_tháng, 12)
                     ngày l? = t?ng_ngày_raw - (n?m*365 + tháng*30) [x?p x?]
          Dùng ADD_MONTHS t? m?c c? ??nh ?? quy ??i chính xác:
        ------------------------------------------------------*/
        CASE
            WHEN tron.TONG_NGAY_RAW IS NULL OR tron.TONG_NGAY_RAW = 0 THEN NULL
            ELSE (
                -- Tính n?m
                CASE WHEN FLOOR(
                         MONTHS_BETWEEN(
                             DATE '2000-01-01' + tron.TONG_NGAY_RAW,
                             DATE '2000-01-01'
                         ) / 12
                     ) > 0
                     THEN TO_CHAR(FLOOR(
                             MONTHS_BETWEEN(
                                 DATE '2000-01-01' + tron.TONG_NGAY_RAW,
                                 DATE '2000-01-01'
                             ) / 12
                         )) || u' n?m '
                     ELSE u'' END
                -- Tính tháng l?
             || CASE WHEN MOD(FLOOR(
                         MONTHS_BETWEEN(
                             DATE '2000-01-01' + tron.TONG_NGAY_RAW,
                             DATE '2000-01-01'
                         )
                     ), 12) > 0
                     THEN TO_CHAR(MOD(FLOOR(
                             MONTHS_BETWEEN(
                                 DATE '2000-01-01' + tron.TONG_NGAY_RAW,
                                 DATE '2000-01-01'
                             )
                         ), 12)) || u' tháng '
                     ELSE u'' END
                -- Tính ngày l? (sau khi tr? ph?n n?m và tháng)
             || CASE WHEN (
                         tron.TONG_NGAY_RAW
                         - (
                             ADD_MONTHS(
                                 DATE '2000-01-01',
                                 FLOOR(
                                     MONTHS_BETWEEN(
                                         DATE '2000-01-01' + tron.TONG_NGAY_RAW,
                                         DATE '2000-01-01'
                                     )
                                 )
                             ) - DATE '2000-01-01'
                           )
                     ) > 0
                     THEN TO_CHAR(
                             tron.TONG_NGAY_RAW
                             - (
                                 ADD_MONTHS(
                                     DATE '2000-01-01',
                                     FLOOR(
                                         MONTHS_BETWEEN(
                                             DATE '2000-01-01' + tron.TONG_NGAY_RAW,
                                             DATE '2000-01-01'
                                         )
                                     )
                                 ) - DATE '2000-01-01'
                               )
                         ) || u' ngày'
                     ELSE u'' END
            )
        END                                             AS THOI_GIAN_TRON,

        /*------------------------------------------------------
          TH?I GIAN T?M ?ÌNH CH? (cùng công th?c MONTHS_BETWEEN)
        ------------------------------------------------------*/
        CASE
            WHEN tdc.TONG_NGAY_RAW IS NULL OR tdc.TONG_NGAY_RAW = 0 THEN NULL
            ELSE (
                CASE WHEN FLOOR(
                         MONTHS_BETWEEN(
                             DATE '2000-01-01' + tdc.TONG_NGAY_RAW,
                             DATE '2000-01-01'
                         ) / 12
                     ) > 0
                     THEN TO_CHAR(FLOOR(
                             MONTHS_BETWEEN(
                                 DATE '2000-01-01' + tdc.TONG_NGAY_RAW,
                                 DATE '2000-01-01'
                             ) / 12
                         )) || u' n?m '
                     ELSE u'' END
             || CASE WHEN MOD(FLOOR(
                         MONTHS_BETWEEN(
                             DATE '2000-01-01' + tdc.TONG_NGAY_RAW,
                             DATE '2000-01-01'
                         )
                     ), 12) > 0
                     THEN TO_CHAR(MOD(FLOOR(
                             MONTHS_BETWEEN(
                                 DATE '2000-01-01' + tdc.TONG_NGAY_RAW,
                                 DATE '2000-01-01'
                             )
                         ), 12)) || u' tháng '
                     ELSE u'' END
             || CASE WHEN (
                         tdc.TONG_NGAY_RAW
                         - (
                             ADD_MONTHS(
                                 DATE '2000-01-01',
                                 FLOOR(
                                     MONTHS_BETWEEN(
                                         DATE '2000-01-01' + tdc.TONG_NGAY_RAW,
                                         DATE '2000-01-01'
                                     )
                                 )
                             ) - DATE '2000-01-01'
                           )
                     ) > 0
                     THEN TO_CHAR(
                             tdc.TONG_NGAY_RAW
                             - (
                                 ADD_MONTHS(
                                     DATE '2000-01-01',
                                     FLOOR(
                                         MONTHS_BETWEEN(
                                             DATE '2000-01-01' + tdc.TONG_NGAY_RAW,
                                             DATE '2000-01-01'
                                         )
                                     )
                                 ) - DATE '2000-01-01'
                               )
                         ) || u' ngày'
                     ELSE u'' END
            )
        END                                             AS THOI_GIAN_TDC,

        /*------------------------------------------------------
          NGÀY MI?N CH?P HÀNH
          - Ngày ra t? HS_MIEN_CHAP_HANHS (m?i nh?t)
        ------------------------------------------------------*/
        TO_CHAR(mien.NGAY_RA, 'DD/MM/YYYY')            AS NGAY_MIEN,

        /*------------------------------------------------------
          TH?I GIAN GI?M S? L?N
          - T?ng gi?m án t? HS_GIAM_THOI_HANS
          - ?ã lo?i mã '0000' và '9999'
        ------------------------------------------------------*/
		HOCSINH.FN_GET_GIAM_AN_CHI_TIET(hll.ID)  AS THOI_GIAN_GIAM_SO_LAN,
        HOCSINH.PKG_HOCSINH_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(hll.ID,sysdate) AS DA_CHAP_HANH,      -- ch? hàm riêng
        HOCSINH.PKG_HOCSINH_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_THANG_NGAY(hll.ID,sysdate)      AS THOI_GIAN_CON_LAI, -- ch? hàm riêng

        /*------------------------------------------------------
          NGÀY H?T H?N & TÓM T?T
        ------------------------------------------------------*/
        TO_CHAR(hhvvp.HVVP_NGAY_HET_HAN, 'DD/MM/YYYY') AS NGAY_HET_HAN,
        hhvvp.HVVP_TOM_TAT_HANH_VI                      AS TOM_TAT_HANH_VI,

        /*------------------------------------------------------
          N?I V? C? TRÚ (cùng logic DIA_CHI_THUONG_TRU)
        ------------------------------------------------------*/
        CASE
            WHEN NULLIF(TRIM(hll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'')     IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'')    IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(hll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(hll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                             THEN u', ' || dxp_thuong_tru.XP_TEN
                             ELSE dxp_thuong_tru.XP_TEN END
                    ELSE u'' END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(hll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'')      IS NOT NULL
                             THEN u', ' || dttp_thuong_tru.TTP_TEN
                             ELSE dttp_thuong_tru.TTP_TEN END
                    ELSE u'' END
            )
            ELSE NULL
        END                                             AS NOI_VE_CU_TRU

    FROM HS_LAI_LICHS hll

    JOIN HS_HANH_VI_VI_PHAMS hhvvp
        ON hll.ID = hhvvp.HVVP_HSLAI_LICH_ID
       AND hhvvp.IS_DELETED = 0

    /*----------------------------------------------------------
      FIX: l?c quan h? b?/m? ngay trong ?i?u ki?n ON
      dùng join DM_QUAN_HE riêng tr??c ?? l?y ID
      (tránh ORA-01799 subquery in outer join)
    ----------------------------------------------------------*/
    LEFT JOIN DM_QUAN_HE dqh_bo
        ON dqh_bo.QH_MA = '09'
    LEFT JOIN HS_THAN_NHAN_NGUOI_THANS bo
        ON hll.ID        = bo.PHAM_NHAN_ID
       AND bo.IS_DELETED = 0
       AND bo.QUAN_HE_ID = dqh_bo.ID
--       AND bo.NGHE_NGHIEP_ID        = dnn_me.id 
    LEFT JOIN DM_NGHE_NGHIEPS dnn_bo
    on bo.NGHE_NGHIEP_ID        = dnn_bo.id   

    LEFT JOIN DM_QUAN_HE dqh_me
        ON dqh_me.QH_MA = '07'
    LEFT JOIN HS_THAN_NHAN_NGUOI_THANS me
        ON hll.ID        = me.PHAM_NHAN_ID
       AND me.IS_DELETED = 0
       AND me.QUAN_HE_ID = dqh_me.ID
    LEFT JOIN DM_NGHE_NGHIEPS dnn_me
    on bo.NGHE_NGHIEP_ID        = dnn_me.id        

    LEFT JOIN DM_QUAN_HE dqh_me_ll
        ON hll.LL_THAN_NHAN_ME        = dqh_me_ll.QH_MA and dqh_me_ll.QH_MA = '07'
    LEFT JOIN DM_QUAN_HE dqh_bo_ll
        ON hll.LL_THAN_NHAN_CHA        = dqh_bo_ll.QH_MA and dqh_bo_ll.QH_MA = '09'

    LEFT JOIN DM_NGHE_NGHIEPS dnn_me_ll
        ON hll.LL_DM_NGHE_NGHIEP_ME_ID        = dnn_me_ll.id 
    LEFT JOIN DM_NGHE_NGHIEPS dnn_bo_ll
        ON hll.LL_DM_NGHE_NGHIEP_CHA_ID        = dnn_bo_ll.id 

    LEFT JOIN DM_TINH_TRANG_HOC_SINH dtths
        ON hll.LL_TINH_TRANG_ID = dtths.ID
    LEFT JOIN hanh_vi_agg hva
        ON hhvvp.ID = hva.HVVP_ID
    LEFT JOIN DM_CO_QUANS dcq
        ON hll.LL_DM_CO_QUAN_LAP_SO_DANH_BAN_ID = dcq.ID
    LEFT JOIN DM_GIOI_TINHS dgt
        ON hll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp
        ON hll.LL_DIA_CHI_NGUYEN_QUAN_PROVICE = dttp.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
        ON hll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
        ON hll.LL_DIA_CHI_THUONG_TRU_WARD   = dxp_thuong_tru.ID
       AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_DAN_TOCS ddt
        ON hll.LL_DM_DAN_TOC_ID = ddt.ID
    LEFT JOIN DM_TON_GIAOS dtg
        ON hll.LL_DM_TON_GIAO_ID = dtg.ID
    LEFT JOIN DM_QUOC_TICHS dqt
        ON hll.LL_DM_QUOC_TICH_ID = dqt.ID
    LEFT JOIN DM_HOCVAN dhv
        ON hll.LL_VAN_HOA = dhv.ID
    LEFT JOIN DM_NGHE_NGHIEPS dnn
        ON hll.LL_DM_NGHE_NGHIEP_ID = dnn.ID
    LEFT JOIN ghi_chu_agg gc_agg
        ON hll.ID = gc_agg.HOC_SINH_ID
     LEFT JOIN suc_khoe_agg ska
        ON hll.ID = ska.HOC_SINH_ID
    LEFT JOIN DM_CO_QUANS dcq2
        ON hhvvp.HVVP_CO_QUAN_QUYET_DINH = dcq2.ID
    LEFT JOIN DM_PHAN_DOIS dpd
        ON hll.LL_PHAN_DOI_ID = dpd.ID
    LEFT JOIN DM_NOI_CHUYEN_DEN dncd
        ON hhvvp.HVVP_NOI_CHUYEN_DEN = dncd.ID

    /*----------------------------------------------------------
      JOIN CÁC CTE TÍNH TOÁN
    ----------------------------------------------------------*/
    LEFT JOIN tron_agg tron ON tron.LAI_LICH_ID = hll.ID
    LEFT JOIN tdc_agg  tdc  ON tdc.LAI_LICH_ID  = hll.ID
    LEFT JOIN mien_agg mien ON mien.LAI_LICH_ID  = hll.ID

    WHERE hll.ID       = p_HOC_SINH_ID
       AND (p_ma_trai_giam IS NULL OR hll.LL_MA_TRAI_GIAM = p_ma_trai_giam)
      AND hll.IS_DELETED = 0;

    -- ===================== ANH CHI EM =====================
    OPEN v_cur_anh_chi_em FOR
    SELECT
        htnnt.HO_TEN_THAN_NHAN                     AS HO_TEN,
        EXTRACT(YEAR FROM htnnt.NGAY_SINH)         AS NAM_SINH,
        dgt.GT_TEN                                  AS GIOI_TINH,
        htnnt.NOI_THUONG_TRU_CHI_TIET              AS NOI_O,
        dnn.NN_TEN                                  AS NGHE_NGHIEP
    FROM HS_THAN_NHAN_NGUOI_THANS htnnt
    LEFT JOIN DM_GIOI_TINHS dgt ON htnnt.GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_NGHE_NGHIEPS dnn ON htnnt.NGHE_NGHIEP_ID = dnn.ID
    LEFT JOIN DM_QUAN_HE dqh ON htnnt.QUAN_HE_ID = dqh.ID
    WHERE dqh.QH_MA = '11'
      AND htnnt.PHAM_NHAN_ID = p_HOC_SINH_ID
      AND NVL(htnnt.IS_DELETED, 0) = 0;

    -- ===================== CHET =====================
    OPEN v_cur_chet FOR
    SELECT
        TO_CHAR(hktc.KTC_NGAY_CHET, 'DD/MM/YYYY') AS NGAY_CHET,
        dldc.LDC_ND                                 AS LY_DO_CHET,
        dnc.NC_ND                                AS NOI_CHET,
        hktc.KTC_NOI_AN_TANG                     AS NOI_AN_TANG
    FROM HS_KET_THUC_CHET hktc
    LEFT JOIN DM_LY_DO_CHET dldc ON hktc.KTC_LY_DO_CHET_ID = dldc.ID
    LEFT JOIN DM_NOI_CHET dnc ON hktc.KTC_NOI_CHET_ID = dnc.ID
    WHERE hktc.IS_DELETED = 0
      AND hktc.KTC_LAI_LICH_ID = p_HOC_SINH_ID;

    -- ===================== GIAM THOI HAN =====================
    OPEN v_cur_giam_thoi_han FOR
    SELECT
        hgth.SO_QUYET_DINH                              AS SO_QD,
        TO_CHAR(hgth.NGAY_QUYET_DINH, 'DD/MM/YYYY')   AS NGAY_QD,
        dmtg.MTG_TITLE                                  AS MUC_GIAM,
        dldg.LDG_ND                                     AS LY_DO_GIAM
    FROM HS_GIAM_THOI_HANS hgth
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON hgth.MUC_DUYET_TOA = dmtg.ID
    LEFT JOIN DM_LY_DO_GIAM dldg ON hgth.LY_DO_GIAM_ID = dldg.ID
    WHERE hgth.HOC_SINH_ID = p_HOC_SINH_ID
      AND hgth.IS_DELETED = 0;

    -- ===================== RA TRUONG =====================
    OPEN v_cur_ra_truong FOR
    SELECT
        TO_CHAR(hktrt.KTRT_NGAY_RA_TRUONG, 'DD/MM/YYYY') AS NGAY_RA,
        dldr.LDR_ND                                        AS LY_DO,
        ddv.DV_ND                              AS NGUOI_DON_VE
    FROM HS_KET_THUC_RA_TRUONG hktrt
    LEFT JOIN DM_LY_DO_RA dldr ON hktrt.KTRT_LY_DO_RA_TRUONG_ID = dldr.ID
    LEFT JOIN DM_DON_VE ddv ON hktrt.KTRT_DON_VE_ID = ddv.ID 
    WHERE hktrt.IS_DELETED = 0
      AND hktrt.KTRT_LAI_LICH_ID = p_HOC_SINH_ID;

    -- ===================== TAM DINH CHI =====================
    OPEN v_cur_tam_dinh_chi FOR
    SELECT
        TO_CHAR(tdc.NGAY_QUYET_DINH, 'DD/MM/YYYY')  AS NGAY_TDC,
        dmtg.MTG_TITLE                                  AS THOI_HAN,
        TO_CHAR(tdc.TU_NGAY, 'DD/MM/YYYY')          AS TU_NGAY,
        NULL                                          AS VE_CU_TRU,
        TO_CHAR(tdc.NGAY_LAI, 'DD/MM/YYYY')         AS NGAY_TRA_LAI
    FROM HS_TAM_DINH_CHIS tdc
    LEFT JOIN DM_LY_DO_TAM_DINH_CHIES dldtdc ON tdc.LY_DO_TAM_DINH_CHI_ID = dldtdc.ID
     LEFT JOIN DM_MA_THOI_GIANS dmtg ON tdc.THOI_HAN = TO_CHAR(dmtg.ID)
    WHERE tdc.HOC_SINH_ID = p_HOC_SINH_ID
      AND tdc.IS_DELETED = 0;

    -- ===================== TAM THOI DUA RA =====================
    OPEN v_cur_tam_thoi_dua_ra FOR
    SELECT
        TO_CHAR(htx.TX_NGAY_QUYET_DINH, 'DD/MM/YYYY') AS NGAY_QUYET_DINH,
        dldtx.LDT_ND                                  AS LY_DO_DUA_RA,
        TO_CHAR(htx.TX_NGAY_TRICH_XUAT, 'DD/MM/YYYY') AS NGAY_TTDR,
        dttp.TTP_TEN                                    AS DIA_PHUONG_VE,
        TO_CHAR(htx.TX_NGAY_TRA_LAI, 'DD/MM/YYYY')    AS NGAY_LAI
    FROM HS_TRICH_XUATS htx
    LEFT JOIN DM_LY_DO_TX dldtx ON htx.TX_LY_DO_TRICH_XUAT_ID = dldtx.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp ON htx.TX_DIA_PHUONG_VE_ID = dttp.ID
    WHERE htx.TX_HS_LAI_LICH_ID = p_HOC_SINH_ID
      AND htx.IS_DELETED = 0;

    -- ===================== TIEN AN =====================
    OPEN v_cur_tien_an FOR
    WITH base_ta AS (
        SELECT tats.*
        FROM HS_TIEN_AN_TIEN_SU tats
        INNER JOIN DM_LOAI_TIEN_AN_TIEN_SU dloai
            ON tats.TATS_LOAI = dloai.ID AND dloai.LTATS_MA = '2'
        WHERE tats.TATS_LAI_LICH_ID = p_HOC_SINH_ID
--          AND NVL(tats.IS_DELETED, 0) = 0
    ),
    split_toi_danh AS (
        SELECT
            ta.ID AS TIEN_AN_ID,
            TO_NUMBER(REGEXP_SUBSTR(
                REPLACE(REPLACE(ta.TATS_DM_TOI_DANH_ID, '[', ''), ']', ''),
                '[0-9]+', 1, LEVEL
            )) AS TOI_DANH_ID
        FROM base_ta ta
        WHERE ta.TATS_DM_TOI_DANH_ID IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                        REPLACE(REPLACE(ta.TATS_DM_TOI_DANH_ID, '[', ''), ']', ''), ',') + 1
                AND PRIOR ta.ID = ta.ID
                AND PRIOR SYS_GUID() IS NOT NULL
    ),
    toi_danh_agg AS (
        SELECT s.TIEN_AN_ID,
               LISTAGG(DISTINCT dtd.TD_TEN, ', ') WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH
        FROM split_toi_danh s
        LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
        GROUP BY s.TIEN_AN_ID
    )
    SELECT
        TO_CHAR(ta.TATS_THOI_GIAN, 'DD/MM/YYYY')   AS THOI_GIAN,
        td_agg.TOI_DANH                              AS TOI_DANH,
        dcq.CQ_TEN                                   AS CO_QUAN_XU_LY,
        dmtg.MTG_TITLE                               AS MUC_AN,
        TRIM(NVL(dhtxl.HTXL_TEN, '') ||
            CASE WHEN dhtxl.HTXL_TEN IS NOT NULL AND dmtg.MTG_TITLE IS NOT NULL THEN ' - ' ELSE '' END ||
            NVL(dmtg.MTG_TITLE, ''))                 AS HINH_THUC_MUC_DO_XU_LY
    FROM base_ta ta
    LEFT JOIN toi_danh_agg td_agg ON ta.ID = td_agg.TIEN_AN_ID
    LEFT JOIN DM_CO_QUANS dcq ON ta.TATS_DM_CO_QUAN_XL_ID = dcq.ID
    LEFT JOIN DM_HINH_THUC_XU_LY dhtxl ON ta.TATS_HINH_THUC_XL_ID = dhtxl.ID
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON ta.TATS_DM_MUC_AN_ID = dmtg.ID;
    -- ===================== TIEN SU =====================
    OPEN v_cur_tien_su FOR
     WITH split_hanh_vi AS (
        SELECT
            tats.ID AS ID,
            TO_NUMBER(
                REGEXP_SUBSTR(
                    REPLACE(REPLACE(tats.TATS_DM_TOI_DANH_ID, '[', ''), ']', ''),
                    '[0-9]+', 1, LEVEL
                )
            ) AS TIEN_SU_ID
        FROM HS_TIEN_AN_TIEN_SU tats
        WHERE tats.TATS_LAI_LICH_ID = p_HOC_SINH_ID
          AND tats.TATS_DM_TOI_DANH_ID IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                       REPLACE(REPLACE(tats.TATS_DM_TOI_DANH_ID, '[', ''), ']', ''), ',') + 1
               AND PRIOR tats.ID = tats.ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
	hanh_vi_agg AS (
	    SELECT
	        s.ID,                        -- ? group theo ID c?a tats
	        LISTAGG(DISTINCT dtd.TD_TEN, ', ')
	            WITHIN GROUP (ORDER BY dtd.TD_TEN) AS HANH_VI_TEN
	    FROM split_hanh_vi s
	    LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TIEN_SU_ID
	    GROUP BY s.ID
	)
    SELECT
        TO_CHAR(tats.TATS_THOI_GIAN, 'DD/MM/YYYY') AS THOI_GIAN,
		hva.HANH_VI_TEN AS TOI_DANH,
        dcq.CQ_TEN                                   AS CO_QUAN_XU_LY,
        dmtg.MTG_TITLE                               AS MUC_AN,
        CASE
            WHEN NULLIF(TRIM(dxp.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dtp.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(dxp.XP_TEN), u''), u'')
                || CASE WHEN NULLIF(TRIM(dtp.TTP_TEN), u'') IS NOT NULL THEN
                    CASE WHEN NULLIF(TRIM(dxp.XP_TEN), u'') IS NOT NULL
                        THEN u', ' || dtp.TTP_TEN ELSE dtp.TTP_TEN END
                   ELSE u'' END
            ) ELSE NULL
        END                                          AS DIA_PHUONG_XU_LY,
        TRIM(NVL(dhtxl.HTXL_TEN, '') ||
            CASE WHEN dhtxl.HTXL_TEN IS NOT NULL AND dmtg.MTG_TITLE IS NOT NULL THEN ' - ' ELSE '' END ||
            NVL(dmtg.MTG_TITLE, ''))                 AS HINH_THUC_MUC_DO_XU_LY
    FROM HS_TIEN_AN_TIEN_SU tats
    INNER JOIN DM_LOAI_TIEN_AN_TIEN_SU dloai
        ON tats.TATS_LOAI = dloai.ID AND dloai.LTATS_MA = '1'
	LEFT JOIN hanh_vi_agg hva ON tats.ID = hva.ID
    LEFT JOIN DM_CO_QUANS dcq ON tats.TATS_DM_CO_QUAN_XL_ID = dcq.ID
    LEFT JOIN DM_TINH_THANH_PHO dtp ON tats.TATS_DM_DIA_PHUONG_XL_ID = dtp.ID
    LEFT JOIN DM_XA_PHUONG dxp ON tats.TATS_DM_PHUONG_XA_ID = dxp.ID
    LEFT JOIN DM_HINH_THUC_XU_LY dhtxl ON tats.TATS_HINH_THUC_XL_ID = dhtxl.ID
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON tats.TATS_DM_MUC_AN_ID = dmtg.ID
    WHERE tats.TATS_LAI_LICH_ID = p_HOC_SINH_ID;
--      AND NVL(tats.IS_DELETED, 0) = 0;

    -- ===================== TRON =====================
    OPEN v_cur_tron FOR
    SELECT
        TO_CHAR(htt.TT_NGAY_TRON, 'DD/MM/YYYY')    AS NGAY_TRON,
        dtht.THT_ND                                 AS TRUONG_HOP_TRON,
        TO_CHAR(htt.TT_NGAY_BAT_LAI, 'DD/MM/YYYY') AS NGAY_BAT_LAI
    FROM HS_TRON_TRUONGS htt
    LEFT JOIN DM_TRUONG_HOP_TRON dtht ON htt.TRUONG_HOP_TRON_ID = dtht.ID
    WHERE htt.IS_DELETED = 0
      AND htt.TT_HS_LAI_LICH_ID = p_HOC_SINH_ID;

    -- ===================== XEP LOAI =====================
    OPEN v_cur_xep_loai FOR
    SELECT
        hxl.XEP_LOAI_NAM,
        dxl.XLR_ND  AS QUY_I,
        dxl2.XLR_ND AS QUY_II,
        dxl3.XLR_ND AS QUY_III,
        dxl4.XLR_ND AS QUY_IV,
        NULL         AS GHI_CHU
    FROM HS_XEP_LOAIS hxl
    JOIN HS_LAI_LICHS hll ON hxl.PHAM_NHAN_ID = hll.ID
    LEFT JOIN DM_XEP_LOAI_RL dxl  ON hxl.XEP_LOAI_QUY_I   = dxl.ID
    LEFT JOIN DM_XEP_LOAI_RL dxl2 ON hxl.XEP_LOAI_QUY_II  = dxl2.ID
    LEFT JOIN DM_XEP_LOAI_RL dxl3 ON hxl.XEP_LOAI_QUY_III = dxl3.ID
    LEFT JOIN DM_XEP_LOAI_RL dxl4 ON hxl.XEP_LOAI_QUY_IV  = dxl4.ID
    WHERE hll.IS_DELETED = 0
       AND (p_ma_trai_giam IS NULL OR hll.LL_MA_TRAI_GIAM = p_ma_trai_giam)
      AND hxl.IS_DELETED = 0
      AND hll.ID = p_HOC_SINH_ID;

    -- ===== RETURN T?T C? 11 CURSOR =====
    DBMS_SQL.RETURN_RESULT(v_cur_main);
    DBMS_SQL.RETURN_RESULT(v_cur_anh_chi_em);
    DBMS_SQL.RETURN_RESULT(v_cur_chet);
    DBMS_SQL.RETURN_RESULT(v_cur_giam_thoi_han);
    DBMS_SQL.RETURN_RESULT(v_cur_ra_truong);
    DBMS_SQL.RETURN_RESULT(v_cur_tam_dinh_chi);
    DBMS_SQL.RETURN_RESULT(v_cur_tam_thoi_dua_ra);
    DBMS_SQL.RETURN_RESULT(v_cur_tien_an);
    DBMS_SQL.RETURN_RESULT(v_cur_tien_su);
    DBMS_SQL.RETURN_RESULT(v_cur_tron);
    DBMS_SQL.RETURN_RESULT(v_cur_xep_loai);

END SP_GET_HOC_SINH_PHIEU_LAI_LICH_ALL;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_HO_SO_GIAO_NHAN_PHAM_NHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_HO_SO_GIAO_NHAN_PHAM_NHAN" (
    p_bien_ban_id IN NUMBER
)
AS
    p_cursor SYS_REFCURSOR;
BEGIN
    OPEN p_cursor FOR

	WITH TOI_DANH_MAP AS (
	    SELECT
	        bbpnn.ID AS BBPNN_ID,
	        LISTAGG(dm.TD_TEN, ', ')
	            WITHIN GROUP (ORDER BY dm.TD_TEN) AS TOI_DANH_TEN
	    FROM PN_BIEN_BAN_PHAM_NHANS bbpnn
	    LEFT JOIN (
	        SELECT
	            ID,
	            TO_NUMBER(REGEXP_SUBSTR(
	                REPLACE(REPLACE(TOI_DANH, '[', ''), ']', ''),
	                '[^,]+', 1, LEVEL
	            )) AS TOI_DANH_ID
	        FROM PN_BIEN_BAN_PHAM_NHANS
	        CONNECT BY REGEXP_SUBSTR(
	            REPLACE(REPLACE(TOI_DANH, '[', ''), ']', ''),
	            '[^,]+', 1, LEVEL
	        ) IS NOT NULL
	        AND PRIOR ID = ID
	        AND PRIOR SYS_GUID() IS NOT NULL
	    ) t
	        ON bbpnn.ID = t.ID
	    LEFT JOIN DM_TOI_DANHS dm
	        ON dm.ID = t.TOI_DANH_ID
	    GROUP BY bbpnn.ID
	)
    SELECT
        bb.BB_NGAY                  AS "NgayGiaoNhan",
        bb.HO_TEN_BG                AS "HoTenBenGiao",
        cvbg.CV_TEN               	AS "ChucVuBenGiao",
        cqg.CQ_TEN                  AS "DonViBenGiao",
        bb.SO_CMND_BG               AS "SoCmBenGiao",
        bb.NGAY_CAP_CMND_BG         AS "NgayCapCmBenGiao",
        ncg.CQ_TEN                  AS "NoiCapCmBenGiao",
		CASE
		    WHEN dpx_bg.XP_TEN IS NULL AND dpt_bg.TTP_TEN IS NULL
		    THEN NULL
		    ELSE NVL(dpx_bg.XP_TEN, '') || ', ' || NVL(dpt_bg.TTP_TEN, '')
		END 						AS "DiaPhuongBenGiao",

        bb.HO_TEN_BN                AS "HoTenBenNhan",
        cvbn.CV_TEN               	AS "ChucVuBenNhan",
        cqn.CQ_TEN                  AS "DonViBenNhan",
        bb.SO_CMND_BN               AS "SoCmBenNhan",
        bb.NGAY_CAP_CMND_BN         AS "NgayCapCmBenNhan",
        ncn.CQ_TEN                  AS "NoiCapCmBenNhan",
		CASE
		    WHEN dpx_bn.XP_TEN IS NULL AND dpt_bn.TTP_TEN IS NULL
		    THEN NULL
		    ELSE NVL(dpx_bn.XP_TEN, '') || ', ' || NVL(dpt_bn.TTP_TEN, '')
		END 						AS "DiaPhuongBenNhan",

        COUNT(DISTINCT bbpnn.ID) OVER (PARTITION BY bb.ID) AS "SoPhamNhan",

        bbpnn.HO_TEN                AS "HoTen",
        SUBSTR(bbpnn.NGAY_SINH, -4) AS "NamSinh",
        gt.GT_TEN                   AS "GioiTinh",
        (NVL(bbpnn.DC_TT_THON_PHO, '') || ', ' ||
    	NVL(xp.XP_TEN, '') || ', ' ||
    	NVL(tp.TTP_TEN, ''))		AS "NoiThuongTru",
        bbpnn.NGAY_BAT              AS "NgayBat",
        ap.MTG_TITLE                AS "AnPhat",

        tdm.TOI_DANH_TEN            AS "ToiDanh",

        NULL                        AS "SoTrang",
        pll.LL_GHI_CHU_CHI_TIET              AS "GhiChu"

    FROM PN_BIEN_BANS bb

    LEFT JOIN PN_BIEN_BAN_PHAM_NHANS bbpnn
        ON bb.ID = bbpnn.PN_BIEN_BAN_ID
        AND bbpnn.IS_DELETED = 0

    LEFT JOIN TOI_DANH_MAP tdm
        ON bbpnn.ID = tdm.BBPNN_ID

    LEFT JOIN PN_LAI_LICHS pll
        ON bbpnn.PN_LAI_LICH_ID = pll.ID

    LEFT JOIN VW_PN_LAI_LICH_CHI_TIET vpllct
        ON pll.ID = vpllct.PHAM_NHAN_ID
--	LEFT JOIN GHI_CHU_RIENG_MAP gcrm
--	    ON pll.ID = gcrm.PLL_ID
    LEFT JOIN DM_MA_THOI_GIANS ap
        ON bbpnn.AN_PHAT = ap.id

    LEFT JOIN DM_GIOI_TINHS gt
        ON bbpnn.GIOI_TINH_ID = gt.ID

    LEFT JOIN DM_CO_QUANS cqg
        ON bb.MA_CQ_BG = TO_CHAR(cqg.ID)

    LEFT JOIN DM_CO_QUANS ncg
        ON bb.NOI_CAP_CMND_BG = TO_CHAR(ncg.ID)

    LEFT JOIN DM_CO_QUANS cqn
        ON bb.MA_CQ_BN = TO_CHAR(cqn.ID)

    LEFT JOIN DM_CO_QUANS ncn
        ON bb.NOI_CAP_CMND_BN = TO_CHAR(ncn.ID)

    LEFT JOIN DM_TINH_THANH_PHO tp
        ON bbpnn.DC_TT_TINH_ID = tp.ID

    LEFT JOIN DM_XA_PHUONG xp
        ON bbpnn.DC_TT_PHUONG_XA_ID = xp.ID

    LEFT JOIN DM_CHUC_VUS cvbn
        ON bb.CHUC_VU_BN = TO_CHAR(cvbn.ID)

    LEFT JOIN DM_CHUC_VUS cvbg
        ON bb.CHUC_VU_BG = TO_CHAR(cvbg.ID)

    LEFT JOIN DM_XA_PHUONG dpx_bg
   		ON bb.MA_DP_BG = TO_CHAR(dpx_bg.ID)
   	LEFT JOIN DM_TINH_THANH_PHO dpt_bg
        ON dpx_bg.XP_MA_TINH_THANH_PHO = dpt_bg.TTP_MA

    LEFT JOIN DM_XA_PHUONG dpx_bn
   		ON bb.MA_DP_BN = TO_CHAR(dpx_bn.ID)
   	LEFT JOIN DM_TINH_THANH_PHO dpt_bn
        ON dpx_bn.XP_MA_TINH_THANH_PHO = dpt_bn.TTP_MA

    WHERE bb.ID = p_bien_ban_id
    ORDER BY bbpnn.ID DESC;

    DBMS_SQL.RETURN_RESULT(p_cursor);
END SP_GET_HO_SO_GIAO_NHAN_PHAM_NHAN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_HO_SO_PHAM_NHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_HO_SO_PHAM_NHAN" (
    p_pn_ids   IN VARCHAR2 DEFAULT NULL -- Danh sách ID phân cách b?i d?u ph?y, VD: '1,2,3,4'
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
         WITH PN_ID_LIST AS (
            -- Tách chu?i ID thành các dòng riêng bi?t
            SELECT TO_NUMBER(
                REGEXP_SUBSTR(p_pn_ids, '[^,]+', 1, LEVEL)
            ) AS PN_ID
            FROM DUAL
            WHERE p_pn_ids IS NOT NULL
            CONNECT BY LEVEL <= REGEXP_COUNT(p_pn_ids, ',') + 1
        ),
        NGUOI_THAN_UU_TIEN AS (
            -- L?y ng??i thân theo th? t? ?u tiên: 19 > 18 > 17 > 44
            SELECT
                tnnt.PHAM_NHAN_ID,
                tnnt.HO_TEN_THAN_NHAN,
                tnnt.NOI_O,
                tnnt.CREATION_TIME AS TU_NGAY,
                tnnt.LAST_MODIFICATION_TIME AS DEN_NGAY,
                ROW_NUMBER() OVER (
                    PARTITION BY tnnt.PHAM_NHAN_ID 
                    ORDER BY 
                        CASE tnnt.QUAN_HE_ID
                            WHEN 19 THEN 1
                            WHEN 18 THEN 2
                            WHEN 17 THEN 3
                            WHEN 44 THEN 4
                            ELSE 99
                        END,
                        tnnt.ID
                ) AS RN
            FROM THAN_NHAN_NGUOI_THANS tnnt
            WHERE tnnt.IS_DELETED = 0
              AND tnnt.QUAN_HE_ID IN (19, 18, 17, 44)
        )
        SELECT
            v.PHAM_NHAN_ID,
            v.HO_TEN,
            ll.LL_TEN_KHAC AS HO_TEN_KHAC,
            v.NAM_SINH,
            v.NGAY_SINH,
            v.GIOI_TINH,
            ll.LL_NGUYEN_QUAN AS NGUYEN_QUAN,
            v.SO_HO_SO,
            v.CCCD,
            ll.LL_NOI_OTRUOC_KHI_BAT AS "NoiOTruocKhiBat",
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            ll.LL_NOI_THA_VE_CU_TRU AS NOI_CHAP_HANH_THOI_GIAN_THU_THACH,
            v.DIA_CHI_THUONG_TRU,
            v.TINH_THANH_THUONG_TRU,
            v.PHUONG_XA_THUONG_TRU,
            v.DAN_TOC,
            v.TON_GIAO,
            v.QUOC_TICH,
            v.HOC_VAN AS TRINH_DO_HOC_VAN,
            v.NGHE_NGHIEP AS NGHE_NGHIEP_TRUOC_KHI_BAT,
            v.TOI_DANH,
            v.AN_PHAT,
            v.NGAY_BAT_AN_PHAT,
            v.DA_GIAM,
            v.NGAY_DEN_TRAI AS NGAY_DEN_CHAP_HANH_AN,
            v.NGAY_HET_AN,
            v.PHAN_DOI,
            v.TRAI_GIAM AS NOI_CHAP_HANH_AN,
            v.TINH_TRANG_SUC_KHOE AS TINH_TRANG_SUC_KHOE_HIEN_NAY,
            v.GHI_CHU,
            v.GHI_CHU_RIENG,
            v.GHI_CHU_CHI_TIET,
            v.TOI_DANH_ID,
            v.TRAI_GIAM_ID,
            v.PHAN_DOI_ID,
            -- Thông tin b?n án (t? PN_THI_HANH_AN)
            tha.THA_SO_BAN_AN AS SO_BAN_AN,
            tha.THA_NGAY_BAN_AN AS NGAY_BAN_AN,
            tha.THA_AN_PHAT AS AN_PHAT_THA,
            tha.THA_CAN_CU_TUYEN_PHAT AS CAN_CU_TUYEN_PHAT,
            tha.THA_NGAY_BAT AS NGAY_BAT_THA,
            tha.THA_NGAY_PHAM_TOI AS NGAY_PHAM_TOI,
            tha.THA_THOI_GIAN_TAM_GIAM AS THOI_GIAN_TAM_GIAM,
            tha.THA_THOI_GIAN_TAM_GIU AS THOI_GIAN_TAM_GIU,
            tha.THA_NGAY_DEN_TRAI AS NGAY_DEN_TRAI_THA,
            tha.THA_NGAY_HET_HAN AS NGAY_HET_HAN_THA,
            --tha."THA_TONG_AN_GIAM" AS TONG_AN_GIAM,
            tha."THA_NGAY_BAT_DAU_O_TU" AS NGAY_BAT_DAU_O_TU,
            -- Quy?t ??nh (t? PN_THI_HANH_AN)
            tha.THA_SO_QD_THA AS SO_QUYET_DINH_THA,
            tha.THA_NGAY_QD_THA AS NGAY_QUYET_DINH_THA,
            tha.THA_SO_QD_DIEU_CHUYEN AS SO_QD_DIEU_CHUYEN,
            tha.THA_NGAY_QD_DIEU_CHUYEN AS NGAY_QD_DIEU_CHUYEN,
            tha."THA_SO_DE_NGHI" AS SO_DE_NGHI,
            tha."THA_NGAY_DE_NGHI" AS NGAY_DE_NGHI,
            -- II. Tóm t?t quá trình ph?m t?i (theo b?n án)
            tha."THA_DIEU" AS TOM_TAT_QUA_TRINH_PHAM_TOI_DIEM,
            tha."THA_KHOAN" AS TOM_TAT_QUA_TRINH_PHAM_TOI_KHOAN,
            -- III. Quan h? gia ?ình
            ntut.HO_TEN_THAN_NHAN AS "NguoiThan",
            ntut.NOI_O AS "DiaChiNguoiThan",
            -- V. Nh?n xét và ?? ngh?
            tha."THA_GHI_CHU_DAC_BIET" AS NHAN_XET_VA_DE_NGHI,
            -- B? sung: Tr?n, T?m ?ình ch?, Hình ph?t b? sung, Tình ti?t ???c ?u tiên (dùng NULL do ch?a có c?t; khi ?ã có c?t thì ??i l?i ll."LL_TRON", ll."LL_TAM_DINH_CHI", tha."THA_HINH_PHAT_BO_SUNG", ll."LL_TINH_TIET_UU_TIEN")
            CAST(NULL AS NVARCHAR2(500)) AS TRON,
            CAST(NULL AS NVARCHAR2(500)) AS TAM_DINH_CHI,
            CAST(NULL AS NVARCHAR2(2000)) AS HINH_PHAT_BO_SUNG,
            CAST(NULL AS NVARCHAR2(2000)) AS TINH_TIET_UU_TIEN,
            -- IV. X?p lo?i ch?p hành án t?ng quý (format v?n b?n: + N?m YYYY: Quý N: x?p lo?i, xu?ng dòng; dòng k?t "Th?i gian ti?p theo...")
            xl.XEP_LOAI_CHAP_HANH_AN,
            v.CREATION_TIME,
            v.LAST_MODIFICATION_TIME
        FROM VW_PN_LAI_LICH_CHI_TIET v
        INNER JOIN PN_LAI_LICHS ll ON ll.ID = v.PHAM_NHAN_ID AND ll.IS_DELETED = 0
        LEFT JOIN NGUOI_THAN_UU_TIEN ntut
            ON ntut.PHAM_NHAN_ID = ll.ID AND ntut.RN = 1
        LEFT JOIN (
            SELECT tha2.*,
                   ROW_NUMBER() OVER (PARTITION BY tha2.THA_PNLAI_LICH_ID ORDER BY tha2.THA_NGAY_BAN_AN DESC NULLS LAST, tha2.ID DESC) AS rn
            FROM PN_THI_HANH_AN tha2
        ) tha ON tha.THA_PNLAI_LICH_ID = v.PHAM_NHAN_ID AND tha.rn = 1
        LEFT JOIN (
            SELECT u.PHAM_NHAN_ID,
                   TO_NCHAR( LISTAGG(u'+ N\0103m ' || u.NAM || u': Qu\00fd ' || u.Q || u': ' || NVL(u.GHI_CHU, u''), NCHR(10)) WITHIN GROUP (ORDER BY u.NAM, u.Q) )
                     || CASE WHEN MAX(u.GHI_CHU_CUOI) IS NOT NULL THEN NCHR(10) || u'Th\1eddi gian ti\1ebfp theo \0111\01b0\1ee3c \0111\00e1nh gi\00e1 c\1ea3i t\1ea1o: ' || MAX(u.GHI_CHU_CUOI) ELSE u'' END
                   AS XEP_LOAI_CHAP_HANH_AN
            FROM (
                SELECT t.PHAM_NHAN_ID, t.NAM, q.Q, t.GHI_CHU,
                       FIRST_VALUE(t.GHI_CHU) OVER (PARTITION BY t.PHAM_NHAN_ID ORDER BY t.NAM DESC) AS GHI_CHU_CUOI
                FROM TIEN_LAO_DONG_SAN_XUATS t
                CROSS JOIN (SELECT 1 AS Q FROM DUAL UNION ALL SELECT 2 FROM DUAL UNION ALL SELECT 3 FROM DUAL UNION ALL SELECT 4 FROM DUAL) q
                WHERE t.IS_DELETED = 0
            ) u
            GROUP BY u.PHAM_NHAN_ID
        ) xl ON xl.PHAM_NHAN_ID = v.PHAM_NHAN_ID
        WHERE v.IS_DELETED = 0
		AND  (p_pn_ids IS NULL OR ll.ID IN (SELECT PN_ID FROM PN_ID_LIST));

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i l?y thông tin ph?m nhân: ' || SQLERRM);
END;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_HUY_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_HUY_AN" (
    p_PHAM_NHAN_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        ha.PHAM_NHAN_ID,
        ha.SO_QUYET_DINH  AS "SoQD",
        ha.NGAY_QUYET_DINH  AS "NgayQD",
        dcq.CQ_TEN   AS "ToaQD",
        ha.NGAY_TRA_TU_DO  AS "NgayTraTuDo"
    FROM HUY_ANS ha 
    LEFT JOIN DM_CO_QUANS dcq ON ha.TOA_QUYET_DINH_ID = dcq.ID
    WHERE ha.PHAM_NHAN_ID = p_PHAM_NHAN_ID
	AND ha.IS_DELETED = 0;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_HUY_AN;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_KET_QUA_CAI_TAO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_KET_QUA_CAI_TAO" (
    p_PHAM_NHAN_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        xl.PHAM_NHAN_ID,
        xl.XEP_LOAI_NAM  AS "Nam",
        d2.XLCT_TEN  AS "Quy1",
        d3.XLCT_TEN  AS "Quy2",
        d4.XLCT_TEN  AS "DauNam",
        d5.XLCT_TEN    AS "Quy3",
        d6.XLCT_TEN  AS "Quy4",
        d7.XLCT_TEN  AS "CuoiNam",
        d8.XLCT_TEN  AS "CaNam"
    FROM XEP_LOAIS xl
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d1 ON xl.XEP_LOAI_NAM  = d1.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d2 ON xl.XEP_LOAI_QUY_I  = d2.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d3 ON xl.XEP_LOAI_QUY_II  = d3.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d4 ON xl.XEP_LOAI_6_THANG_DAU_NAM  = d4.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d5 ON xl.XEP_LOAI_QUY_III  = d5.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d6 ON xl.XEP_LOAI_QUY_IV  = d6.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d7 ON xl.XEP_LOAI_6_THANG_CUOI_NAM  = d7.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d8 ON xl.XEP_LOAI_CA_NAM  = d8.ID

    WHERE xl.PHAM_NHAN_ID = p_PHAM_NHAN_ID;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_KET_QUA_CAI_TAO;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_KHEN_THUONG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_KHEN_THUONG" (
    p_PHAM_NHAN_ID IN NUMBER
)
AS
