          FROM PN_THI_HANH_AN ptha
          JOIN DM_TOI_DANHS dtd
            ON INSTR(',' || REPLACE(REPLACE(ptha.THA_TOI_DANH,'[',''),']','') || ',',
                     ',' || dtd.ID || ',') > 0
         WHERE ptha.THA_TOI_DANH IS NOT NULL
           AND NVL(dtd.IS_DELETED, 0) = 0
           AND ptha.THA_PNLAI_LICH_ID = (SELECT PHAM_NHAN_ID FROM KY_LUATS WHERE ID = TO_NUMBER(p_kl_id))
    ),
    TOI_DANH_AGG AS (
        SELECT /*+ NO_MERGE */
               THA_PNLAI_LICH_ID,
               LISTAGG(TD_TEN, '; ' ON OVERFLOW TRUNCATE) WITHIN GROUP (ORDER BY TD_TEN) AS TOI_DANH
          FROM SPLIT_TOI_DANH
         GROUP BY THA_PNLAI_LICH_ID
    ),
    LATEST_THA AS (
        SELECT
            THA_PNLAI_LICH_ID,
            THA_NGAY_BAT,
            THA_AN_PHAT,
            THA_SO_BAN_AN,
            THA_NGAY_BAN_AN AS THA_NGAY_BAN_AN,
            THA_CAP_TOA_ID,
            d2.TTP_TEN AS DIA_PHUONG_CAP_TOA,
            THA_TOA_QD_ID,
            d.TTP_TEN AS DIA_PHUONG_TOA_QD_THA,
            THA_SO_QD_THA,
            THA_NGAY_QD_THA AS THA_NGAY_QD_THA,
           	THA_NGAY_DEN_TRAI  AS THA_NGAY_DEN_TRAI,
            PN_THI_HANH_AN.THA_TOI_DANH_NAMES,
            ROW_NUMBER() OVER (
                PARTITION BY THA_PNLAI_LICH_ID
                ORDER BY NVL(THA_NGAY_BAN_AN, TO_DATE('01-JAN-1900', 'DD-MON-YYYY')) DESC, PN_THI_HANH_AN.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN
        LEFT JOIN DM_TINH_THANH_PHO d  ON PN_THI_HANH_AN.THA_DIA_PHUONG_TOA_QD_THA_ID = d.ID
        LEFT JOIN DM_TINH_THANH_PHO d2 ON PN_THI_HANH_AN.THA_DIA_PHUONG_CAP_TOA_ID    = d2.ID
        WHERE PN_THI_HANH_AN.THA_PNLAI_LICH_ID = (SELECT PHAM_NHAN_ID FROM KY_LUATS WHERE ID = TO_NUMBER(p_kl_id))
    )
    SELECT
        pll.LL_HO_TEN          AS HoTen,
        pll.LL_TEN_KHAC        AS TenKhac,
        dgt.GT_TEN             AS GioiTinh,
        pll.LL_NGAY_SINH       AS NgaySinh,

        CASE
            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || dxp_thuong_tru.XP_TEN
                            ELSE dxp_thuong_tru.XP_TEN
                        END
                    ELSE u''
                   END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || dttp_thuong_tru.TTP_TEN
                            ELSE dttp_thuong_tru.TTP_TEN
                        END
                    ELSE u''
                   END
            )
            ELSE NULL
        END AS DiaChiThuongTru,

        ddt.DT_TEN              AS DanToc,
        dtg2.TG_TEN              AS TonGiao,
        dqt.QT_TEN               AS QuocTich,

        TO_CHAR(TRUNC(ptha.THA_NGAY_BAT), 'DD/MM/YYYY') AS NgayBat,
        ptha.THA_AN_PHAT          AS AnPhat,
        pll.LL_SO_TIEN_AN as SoTienAn,
        pll.LL_SO_TIEN_SU as SoTienSu,
        ptha.THA_SO_BAN_AN        AS BanAnSo,
        TO_CHAR(TRUNC(ptha.THA_NGAY_BAN_AN), 'DD/MM/YYYY')      AS NgayBanAn,
        dcq5.CQ_TEN               AS ToaBanAn,
        ptha.DIA_PHUONG_CAP_TOA   AS DiaPhuongBanAn,
        dcq5.CQ_TEN               AS ToaQuyetDinh,
        ptha.DIA_PHUONG_CAP_TOA   AS DiaPhuongToa,

        ptha.THA_SO_QD_THA        AS SoQuyetDinhTHA,
        TO_CHAR(TRUNC(ptha.THA_NGAY_QD_THA), 'DD/MM/YYYY')      AS NgayQuyetDinhTHA,
        dcq.CQ_TEN                AS ToaQdTha,
        ptha.DIA_PHUONG_TOA_QD_THA AS DiaPhuongQdTha,
        dcq.CQ_TEN                AS CoQuanQuyetDinh,
        ptha.DIA_PHUONG_TOA_QD_THA AS DiaPhuongQuyetDinh,
        TO_CHAR(TRUNC(ptha.THA_NGAY_DEN_TRAI), 'DD/MM/YYYY') AS NgayDenTrai,
        TRIM(NVL(ptha.THA_TOI_DANH_NAMES, td_agg.TOI_DANH))  AS ToiDanh,
        dpd.PD_TEN                AS PhanDoi,
        dpt.PT_TEN                 AS PhanTrai,
        dtg.TG_TEN                 AS TraiGiam,
        kly.NOI_DUNG_VI_PHAM as HanhVi,
        kly.LY_DO_KY_LUAT_CU_THE as LyDoKyLuatCuThe,
        dm_ld.LDKL_TEN as TenLyDoKyLuat,
        kly.HINH_THUC_KY_LUAT_CU_THE as HinhThucKyLuat,
        dm_ht.HTKLPN_TEN as TenHinhThucKyLuat,
        TO_CHAR(TRUNC(kly.NGAY_DE_NGHI_KY_LUAT), 'DD/MM/YYYY') as NgayKyLuat,
        NULL AS ThoiHanKyLuat,
        TO_CHAR(TRUNC(kly.NGAY_DE_NGHI_TIEN_BO), 'DD/MM/YYYY') AS NgayTheoDoi,
        kly.SO_QUYET_DINH AS SoQuyetDinhKL,
        TO_CHAR(TRUNC(kly.NGAY_QUYET_DINH), 'DD/MM/YYYY') AS NgayQuyetDinhKL,
        TO_CHAR(TRUNC(kly.NGAY_DE_NGHI_KY_LUAT), 'DD/MM/YYYY') AS NgayDeNghi,
        TO_CHAR(TRUNC(kly.NGAY_BIEN_BAN), 'DD/MM/YYYY') AS NgayBienBan,
        kly.NGUOI_DE_NGHI_KY_LUAT AS NguoiDeNghi
    FROM PN_LAI_LICHS pll
    LEFT JOIN LATEST_THA ptha
           ON pll.ID = ptha.THA_PNLAI_LICH_ID
          AND ptha.rn = 1
    join KY_LUATS kly on pll.ID = kly.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt   ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_DAN_TOCS  ddt    ON pll.LL_DM_DAN_TOC_ID   = ddt.ID
    LEFT JOIN DM_TON_GIAOS dtg2   ON pll.LL_DM_TON_GIAO_ID  = dtg2.ID
    LEFT JOIN DM_QUOC_TICHS dqt   ON pll.LL_DM_QUOC_TICH_ID = dqt.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
          AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
          AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS dcq     ON ptha.THA_TOA_QD_ID  = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq5    ON ptha.THA_CAP_TOA_ID = dcq5.ID
    LEFT JOIN DM_PHAN_DOIS dpd    ON pll.LL_PHAN_DOI_ID  = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt   ON pll.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg   ON pll.LL_TRAI_GIAM_ID = dtg.ID
    LEFT JOIN DM_LY_DO_KY_LUATS dm_ld ON kly.MA_LY_DO_KY_LUAT_ID = dm_ld.ID AND NVL(dm_ld.IS_DELETED, 0) = 0
    LEFT JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm_ht ON kly.MA_HINH_THUC_KY_LUAT_ID = dm_ht.ID AND NVL(dm_ht.IS_DELETED, 0) = 0
    LEFT JOIN TOI_DANH_AGG td_agg    ON pll.ID           = td_agg.THA_PNLAI_LICH_ID
    WHERE kly.ID = TO_NUMBER(p_kl_id);

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        NULL;
    WHEN TOO_MANY_ROWS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Có nhi?u h?n 1 b?n ghi cho ph?m nhân ID: ' || p_kl_id);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: ' || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END;


