        -- dcq5.CQ_TEN                AS CoQuanQuyetDinh,
        -- ptha.DIA_PHUONG_THA       AS DiaPhuongQuyetDinh,
        dpd.PD_TEN                AS PhanDoi,
        dpt.PT_TEN                 AS PhanTrai,
        dtg.TG_TEN                 AS TraiGiam,
        kly.NOI_DUNG_VI_PHAM as HanhVi,
        kly.HINH_THUC_KY_LUAT_CU_THE as HinhThucKyLuat,
        kly.SO_QUYET_DINH AS SOQDKYLUAT,
        TO_CHAR(TRUNC(kly.NGAY_DE_NGHI_KY_LUAT), 'DD/MM/YYYY') as NgayKyLuat,
        kly.NGUOI_DE_NGHI_KY_LUAT as NguoiDeNghiKyLuat,
		kly.SO_QUYET_DINH_TIEN_BO AS SoQDTienBo,
		TO_CHAR(TRUNC(kly.NGAY_QUYET_DINH_TIEN_BO), 'DD/MM/YYYY') AS NgayQDTienBo,
		kly.NOI_DE_NGHI_TIEN_BO AS NoiDeNghiTienBo
    FROM PN_LAI_LICHS pll
    LEFT JOIN LATEST_THA ptha
           ON pll.ID = ptha.THA_PNLAI_LICH_ID
          AND ptha.rn = 1
    left join KY_LUATS kly on pll.ID = kly.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt   ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_DAN_TOCS  ddt    ON pll.LL_DM_DAN_TOC_ID   = ddt.ID
    LEFT JOIN DM_TON_GIAOS dtg2   ON pll.LL_DM_TON_GIAO_ID  = dtg2.ID
    LEFT JOIN DM_QUOC_TICHS dqt   ON pll.LL_DM_QUOC_TICH_ID = dqt.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
          AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
          AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS dcq     ON ptha.THA_TOA_QD_ID  = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq5    ON ptha.THA_CAP_TOA_ID = dcq5.ID
    LEFT JOIN DM_PHAN_DOIS dpd    ON pll.LL_PHAN_DOI_ID  = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt   ON pll.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg   ON pll.LL_TRAI_GIAM_ID = dtg.ID
    LEFT JOIN TOI_DANH_AGG td_agg    ON pll.ID                           = td_agg.THA_PNLAI_LICH_ID
    WHERE kly.ID = p_kl_id;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        NULL;
    WHEN TOO_MANY_ROWS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Có nhi?u h?n 1 b?n ghi cho ph?m nhân ID: ' );
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: ' || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END;

