    LEFT JOIN DM_CO_QUANS dcq     ON ptha.THA_TOA_QD_ID  = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq5    ON ptha.THA_CAP_TOA_ID = dcq5.ID
    LEFT JOIN DM_PHAN_DOIS dpd    ON pll.LL_PHAN_DOI_ID  = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt   ON pll.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg   ON pll.LL_TRAI_GIAM_ID = dtg.ID
    WHERE pll.ID = p_pll_id;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        NULL;
    WHEN TOO_MANY_ROWS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Có nhi?u h?n 1 b?n ghi cho ph?m nhân ID: ' || p_pll_id);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: ' || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_LAI_LICH_FULL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_LAI_LICH_FULL" (
    p_pll_id        IN NUMBER,
    p_ma_trai_giam  IN VARCHAR2 DEFAULT NULL   -- Mã tr?i giam (TG_MA); NULL = không filter
) AS

    -- ----------------------------------------------------------------
    -- Bi?n n?i b?
    -- ----------------------------------------------------------------
    v_trai_giam_id  DM_TRAI_GIAMS.ID%TYPE := NULL;

    -- ----------------------------------------------------------------
    -- 27 SYS_REFCURSOR
    -- ----------------------------------------------------------------
    c_thong_tin_lai_lich    SYS_REFCURSOR;   --  1
    c_quan_he_gia_dinh      SYS_REFCURSOR;   --  2
    c_tien_an               SYS_REFCURSOR;   --  3
    c_tien_su               SYS_REFCURSOR;   --  4
    c_ban_an_khac           SYS_REFCURSOR;   --  5
    c_quyet_dinh_tha_khac   SYS_REFCURSOR;   --  6
    c_hinh_phat_bo_sung_tien   SYS_REFCURSOR;   --  7a: HPBS tien (210/211/220)
    c_hinh_phat_bo_sung_khac   SYS_REFCURSOR;   --  7b: HPBS khac (110..310)
    c_trach_nhiem_dan_su_tien  SYS_REFCURSOR;   --  7c: Trach nhiem dan su tien
    c_phan_loai_giam_giu    SYS_REFCURSOR;   --  8
    c_khen_thuong           SYS_REFCURSOR;   --  9
    c_ky_luat               SYS_REFCURSOR;   -- 10
    c_giam_rieng            SYS_REFCURSOR;   -- 11
    c_pham_toi_moi          SYS_REFCURSOR;   -- 12
    c_ket_qua_cai_tao       SYS_REFCURSOR;   -- 13
    c_giam_thoi_han         SYS_REFCURSOR;   -- 14
    c_tang_giam_hinh_phat   SYS_REFCURSOR;   -- 15
    c_mien_hinh_phat        SYS_REFCURSOR;   -- 16
    c_hoan_thi_hanh_an      SYS_REFCURSOR;   -- 17
    c_tron_trai             SYS_REFCURSOR;   -- 18
    c_thong_tin_chet        SYS_REFCURSOR;   -- 19
    c_trich_xuat            SYS_REFCURSOR;   -- 20
    c_tam_dinh_chi          SYS_REFCURSOR;   -- 21
    c_chua_benh_bat_buoc    SYS_REFCURSOR;   -- 22
    c_nghien_ma_tuy         SYS_REFCURSOR;   -- 23
    c_huy_an                SYS_REFCURSOR;   -- 24
    c_an_giam               SYS_REFCURSOR;   -- 25
    c_dac_xa                SYS_REFCURSOR;   -- 26
    c_ra_trai               SYS_REFCURSOR;   -- 27

BEGIN

    -- ----------------------------------------------------------------
    -- B??c 0: Resolve mã tr?i giam ? ID (1 l?n duy nh?t cho c? SP)
    -- N?u p_ma_trai_giam IS NULL thì v_trai_giam_id gi? NULL
    -- và ?i?u ki?n filter s? b? b? qua nh?: (p_ma_trai_giam IS NULL OR ...)
    -- ----------------------------------------------------------------
    IF p_ma_trai_giam IS NOT NULL THEN
        BEGIN
            SELECT dtg.ID
              INTO v_trai_giam_id
              FROM DM_TRAI_GIAMS dtg
             WHERE dtg.TG_MA = p_ma_trai_giam
               AND ROWNUM = 1;   -- phòng khi TG_MA không unique
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                v_trai_giam_id := NULL;   -- mã không t?n t?i ? tr? v? r?ng
        END;
    END IF;

    ------------------------------------------------------------
    -- 1. SP_GET_THONG_TIN_LAI_LICH
    ------------------------------------------------------------
    OPEN c_thong_tin_lai_lich FOR
    WITH
    SPLIT_TOI_DANH AS (
        SELECT /*+ NO_MERGE */
               ptha.THA_PNLAI_LICH_ID,
               dtd.ID  AS TOI_DANH_ID,
               dtd.TD_TEN
          FROM PN_THI_HANH_AN ptha
          JOIN DM_TOI_DANHS dtd
            ON INSTR(',' || REPLACE(REPLACE(ptha.THA_TOI_DANH,'[',''),']','') || ',',
                     ',' || dtd.ID || ',') > 0
         WHERE ptha.THA_TOI_DANH IS NOT NULL
           AND ptha.THA_PNLAI_LICH_ID = p_pll_id
           AND NVL(dtd.IS_DELETED, 0) = 0
    ),
    TOI_DANH_AGG AS (
        SELECT /*+ NO_MERGE */
               THA_PNLAI_LICH_ID,
               RTRIM(
                   XMLAGG(XMLELEMENT(e, TD_TEN || '; ') ORDER BY TD_TEN)
                       .extract('//text()').GETCLOBVAL(),
                   '; '
               ) AS TOI_DANH
          FROM SPLIT_TOI_DANH
         GROUP BY THA_PNLAI_LICH_ID
    ),
    LATEST_THA AS (
        SELECT /*+ NO_MERGE */
               THA_PNLAI_LICH_ID,
               THA_NGAY_BAT,
               THA_AN_PHAT,
               THA_SO_BAN_AN,
               THA_CAP_TOA_ID,
               TO_CHAR(THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS THA_NGAY_BAN_AN,
               d2.TTP_TEN AS DIA_PHUONG_TOA,
               THA_SO_QD_THA,
               TO_CHAR(THA_NGAY_QD_THA, 'DD/MM/YYYY') AS THA_NGAY_QD_THA,
               THA_TOA_QD_ID,
               d.TTP_TEN  AS DIA_PHUONG_THA,
               THA_SO_QD_DIEU_CHUYEN,
               TO_CHAR(THA_NGAY_QD_DIEU_CHUYEN, 'DD/MM/YYYY') AS THA_NGAY_QD_DIEU_CHUYEN,
               THA_DON_VI_DE_NGHI_ID,
               THA_CHUYEN_DEN_TU_ID,
               THA_THOI_GIAN_TAM_GIAM,
               THA_THOI_GIAN_TAM_GIU,
               THA_NGAY_DEN_TRAI,
               THA_NGAY_HET_HAN
          FROM PN_THI_HANH_AN
          LEFT JOIN DM_TINH_THANH_PHO d  ON PN_THI_HANH_AN.THA_DIA_PHUONG_TOA_QD_THA_ID = d.ID
          LEFT JOIN DM_TINH_THANH_PHO d2 ON PN_THI_HANH_AN.THA_DIA_PHUONG_CAP_TOA_ID    = d2.ID
         WHERE THA_PNLAI_LICH_ID = p_pll_id
         ORDER BY NVL(THA_NGAY_BAN_AN, DATE '1900-01-01') DESC,
                  PN_THI_HANH_AN.ID DESC
         FETCH FIRST 1 ROW ONLY
    ),
    TONG_TRON AS (
        SELECT /*+ NO_MERGE */
               tt.PHAM_NHAN_ID,
               SUM(FLOOR(CAST(tt.NGAY_BAT_LAI AS DATE)
                       - CAST(tt.NGAY_TRON    AS DATE)) + 1) AS TONG_NGAY_TRON
          FROM TRON_TRAIS tt
         WHERE tt.PHAM_NHAN_ID  = p_pll_id
           AND NVL(tt.IS_DELETED, 0) = 0
           AND tt.NGAY_TRON     IS NOT NULL
           AND tt.NGAY_BAT_LAI  IS NOT NULL
         GROUP BY tt.PHAM_NHAN_ID
    ),
    TONG_TDC AS (
        SELECT /*+ NO_MERGE */
               tdc.PHAM_NHAN_ID,
               SUM(FLOOR(CAST(tdc.NGAY_LAI AS DATE)
                       - CAST(tdc.TU_NGAY  AS DATE)) + 1) AS TONG_NGAY_TDC
          FROM TAM_DINH_CHIS tdc
         WHERE tdc.PHAM_NHAN_ID = p_pll_id
           AND NVL(tdc.IS_DELETED, 0) = 0
           AND tdc.TU_NGAY   IS NOT NULL
           AND tdc.NGAY_LAI  IS NOT NULL
         GROUP BY tdc.PHAM_NHAN_ID
    )
    SELECT
        pll.LL_SO_HO_SO_LAN_DAU AS SoHSLD,
        dttpn.TTPN_TEN           AS TinhTrang,
        pll.LL_HO_TEN            AS HoTen,
        dgt.GT_TEN               AS GioiTinh,
        pll.LL_NGAY_SINH         AS NamSinh,
        pll.LL_TEN_KHAC          AS HoTenKhac,
        pll.LL_NGUYEN_QUAN       AS NguyenQuan,
        CASE
            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN),      u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN),     u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                             THEN u', ' || dxp_thuong_tru.XP_TEN
                             ELSE dxp_thuong_tru.XP_TEN END
                    ELSE u'' END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                             THEN u', ' || dttp_thuong_tru.TTP_TEN
                             ELSE dttp_thuong_tru.TTP_TEN END
                    ELSE u'' END
            )
            ELSE NULL
        END AS DiaChiThuongTru,
        ddt.DT_TEN  AS DanToc,
        dqt.QT_TEN  AS QuocTich,
        dtg2.TG_TEN AS TonGiao,
        CASE WHEN dnn.NN_TEN IS NULL THEN u'Không' ELSE dnn.NN_TEN END AS NgheNghiep,
        CASE WHEN dhv.HV_TEN IS NULL THEN u'Không' ELSE dhv.HV_TEN END AS TrinhDoHocVan,
        dskpn.TTSKPN_TEN AS TinhTrangSucKhoeKhiVao,
        dbt.BT_TEN       AS TinhTrangSucKhoeHienTai,
        gcr_agg.GHI_CHU_RIENG AS GhiChuRieng,
        CASE WHEN NVL(con_count.SO_CON, 0) = 0 THEN 'Không'
             ELSE TO_CHAR(NVL(con_count.SO_CON, 0)) END AS SoCon,
        CASE WHEN pll.LL_SO_TIEN_AN IS NULL THEN u'Không' ELSE pll.LL_SO_TIEN_AN END AS SoTienAn,
        CASE WHEN pll.LL_SO_TIEN_SU IS NULL THEN u'Không' ELSE pll.LL_SO_TIEN_SU END AS SoTienSu,
        pll.LL_NHAN_THAN AS NhanThan,
        td_agg.TOI_DANH  AS ToiDanh,
        TO_CHAR(TRUNC(ptha.THA_NGAY_BAT),      'DD/MM/YYYY') AS NgayBat,
        ptha.THA_AN_PHAT  AS AnPhat,
        ptha.THA_SO_BAN_AN AS BanAnSo,
        ptha.THA_NGAY_BAN_AN AS NgayBanAn,
        dcq5.CQ_TEN  || ', ' || ptha.DIA_PHUONG_TOA AS ToaQuyetDinh,
        ptha.THA_SO_QD_THA  AS SoQuyetDinh,
        ptha.THA_NGAY_QD_THA AS NgayQuyetDinhTHA,
        dcq.CQ_TEN || ', ' || ptha.DIA_PHUONG_THA AS DiaPhuongTha,
        ptha.THA_SO_QD_DIEU_CHUYEN  AS SoQuyetDinhDieuChuyen,
        ptha.THA_NGAY_QD_DIEU_CHUYEN AS NgayQuyetDinhDieuChuyen,
        dcq2.CQ_TEN AS ToaQuyetDinhDieuChuyen,
        dcq1.CQ_TEN AS ChuyenDenTu,
        CASE WHEN ptha.THA_THOI_GIAN_TAM_GIAM IS NULL THEN u'Không' ELSE ptha.THA_THOI_GIAN_TAM_GIAM END AS ThoiGianTamGiam,
        CASE WHEN ptha.THA_THOI_GIAN_TAM_GIU  IS NULL THEN u'Không' ELSE ptha.THA_THOI_GIAN_TAM_GIU  END AS ThoiGianTamGiu,
        TO_CHAR(TRUNC(ptha.THA_NGAY_DEN_TRAI), 'DD/MM/YYYY') AS NgayDenTrai,
        dpd.PD_TEN || ', ' || dpt.PT_TEN AS PhanDoi,
        dpt.PT_TEN AS PhanTrai,
        dtg.TG_TEN AS TraiGiam,
        CASE WHEN NVL(tron_agg.TONG_NGAY_TRON, 0) = 0 THEN u'Không'
             ELSE TO_CHAR(tron_agg.TONG_NGAY_TRON) || u' ngày' END AS ThoiGianTron,
        CASE WHEN NVL(tdc_agg.TONG_NGAY_TDC, 0) = 0 THEN u'Không'
             ELSE TO_CHAR(tdc_agg.TONG_NGAY_TDC)  || u' ngày' END AS ThoiGianTamDinhChi,
        QLPN.FN_TINH_AN_DA_GIAM_CHI_TIET(pll.ID)          AS ThoiGianDuocGiam,
        QLPN.FN_FORMAT_YMD(mhp.MHP_THM_YEAR, mhp.MHP_THM_MONTH, mhp.MHP_THM_DAY) AS MienHinhPhat,
        QLPN.FN_GET_DA_CHAP_HANH_TEXT(pll.ID, SYSDATE)
            || u' (Tính ??n ngày: ' || TO_CHAR(SYSDATE, 'DD/MM/YYYY') || u')' AS DaChapHanh,
        QLPN.FN_TINH_THOI_GIAN_CON_LAI(pll.ID, SYSDATE)   AS ThoiGianConLai,
        TO_CHAR(TRUNC(ptha.THA_NGAY_HET_HAN),  'DD/MM/YYYY') AS NgayTha,
        pll.LL_TOM_TAT_HV AS HanhViPhamToi
    FROM PN_LAI_LICHS pll
    LEFT JOIN DM_NGHE_NGHIEPS dnn    ON pll.LL_DM_NGHE_NGHIEP_ID        = dnn.ID
    LEFT JOIN LATEST_THA ptha        ON pll.ID                           = ptha.THA_PNLAI_LICH_ID
    LEFT JOIN MIEN_HINH_PHATS mhp    ON pll.ID                           = mhp.PN_LAI_LICH_ID
                                    AND mhp.IS_DELETED                  = 0
    LEFT JOIN DM_CO_QUANS dcq        ON ptha.THA_TOA_QD_ID               = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq1       ON ptha.THA_CHUYEN_DEN_TU_ID        = dcq1.ID
    LEFT JOIN DM_CO_QUANS dcq5       ON ptha.THA_CAP_TOA_ID              = dcq5.ID
    LEFT JOIN DM_CO_QUANS dcq2       ON ptha.THA_DON_VI_DE_NGHI_ID       = dcq2.ID
    LEFT JOIN DM_TINH_TRANG_SUC_KHOE_PHAM_NHANS dskpn
                                     ON pll.LL_SUC_KHOE_KHI_VAO_ID      = dskpn.ID
    LEFT JOIN DM_BENH_TATS dbt       ON pll.LL_BENH_HIEN_TAI_ID          = dbt.ID
    LEFT JOIN TONG_TRON tron_agg     ON pll.ID                           = tron_agg.PHAM_NHAN_ID
    LEFT JOIN TONG_TDC  tdc_agg      ON pll.ID                           = tdc_agg.PHAM_NHAN_ID
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dttpn ON pll.LL_TINH_TRANG_ID    = dttpn.ID
    LEFT JOIN DM_GIOI_TINHS dgt      ON pll.LL_DM_GIOI_TINH_ID           = dgt.ID
    LEFT JOIN DM_DAN_TOCS ddt        ON pll.LL_DM_DAN_TOC_ID             = ddt.ID
    LEFT JOIN DM_TON_GIAOS dtg2      ON pll.LL_DM_TON_GIAO_ID            = dtg2.ID
    LEFT JOIN DM_QUOC_TICHS dqt      ON pll.LL_DM_QUOC_TICH_ID           = dqt.ID
    LEFT JOIN DM_PHAN_DOIS dpd       ON pll.LL_PHAN_DOI_ID               = dpd.ID
    LEFT JOIN TOI_DANH_AGG td_agg    ON pll.ID                           = td_agg.THA_PNLAI_LICH_ID
    LEFT JOIN DM_PHAN_TRAIS dpt      ON pll.LL_PHAN_TRAI_ID              = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg      ON pll.LL_TRAI_GIAM_ID              = dtg.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
                                     ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
                                    AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
                                     ON pll.LL_DIA_CHI_THUONG_TRU_WARD   = dxp_thuong_tru.ID
                                    AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_HOC_VANS dhv        ON pll.LL_DM_HOC_VAN_ID             = dhv.ID
    LEFT JOIN (
        SELECT /*+ NO_MERGE */
               p_pll_id AS PHAM_NHAN_ID,
               RTRIM(
                   XMLAGG(XMLELEMENT(e, dgcr.GCR_TEN || ', ') ORDER BY dgcr.GCR_TEN)
                       .extract('//text()').GETCLOBVAL(), ', '
               ) AS GHI_CHU_RIENG
          FROM PN_LAI_LICHS ll2
          JOIN DM_GHI_CHU_RIENGS dgcr
            ON INSTR(',' || ll2.LL_GHI_CHU_RIENG || ',', ',' || dgcr.ID || ',') > 0
         WHERE ll2.ID = p_pll_id
           AND ll2.LL_GHI_CHU_RIENG IS NOT NULL
    ) gcr_agg ON pll.ID = gcr_agg.PHAM_NHAN_ID
    LEFT JOIN (
        SELECT /*+ NO_MERGE */
               PHAM_NHAN_ID,
               COUNT(DISTINCT ID) AS SO_CON
          FROM THAN_NHAN_CON_CAIS
         WHERE PHAM_NHAN_ID = p_pll_id
         GROUP BY PHAM_NHAN_ID
    ) con_count ON pll.ID = con_count.PHAM_NHAN_ID
    WHERE pll.ID = p_pll_id
      AND (p_ma_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id);

    ------------------------------------------------------------
    -- 2. SP_GET_QUAN_HE_GIA_DINH
    ------------------------------------------------------------
    OPEN c_quan_he_gia_dinh FOR
    SELECT
        tnnt.PHAM_NHAN_ID,
        tnnt.HO_TEN_THAN_NHAN  AS "HoTen",
        dqhvpn.QHVPN_TEN       AS "QuanHe",
        dgt.GT_TEN              AS "GioiTinh",
        tnnt.NGAY_SINH          AS "NgaySinh",
        tnnt.NOI_O              AS "NoiO"
    FROM THAN_NHAN_NGUOI_THANS tnnt
    LEFT JOIN DM_QUAN_HE_VOI_PHAM_NHANS dqhvpn ON tnnt.QUAN_HE_ID   = dqhvpn.ID
    LEFT JOIN DM_GIOI_TINHS dgt                ON tnnt.GIOI_TINH_ID  = dgt.ID
    WHERE tnnt.PHAM_NHAN_ID = p_pll_id
    AND tnnt.IS_DELETED = 0;

    ------------------------------------------------------------
    -- 3. SP_GET_TIEN_AN
    ------------------------------------------------------------
    OPEN c_tien_an FOR
    WITH tien_an_base AS (
        SELECT /*+ NO_MERGE */
               pta.PNTA_LAI_LICH_ID,
               dcq.CQ_TEN           AS "ToaXu",
               pta.PNTA_NAM_XU      AS "NamXu",
               pta.PNTA_NAM_THA     AS "NamTha",
               dmtg.MTG_TITLE       AS "MucAn",
               TRIM(BOTH ',' FROM
                   REPLACE(REPLACE(pta.PNTA_TOI_DANH_ID, '[', ''), ']', '')
               ) AS cleaned_toi_danh
          FROM PN_TIEN_AN pta
          LEFT JOIN DM_CO_QUANS      dcq  ON pta.PNTA_TOA_XU_ID = dcq.ID
          LEFT JOIN DM_MA_THOI_GIANS dmtg ON pta.PNTA_MUC_AN_ID = dmtg.ID
         WHERE pta.PNTA_LAI_LICH_ID = p_pll_id
           AND pta.IS_DELETED = 0
    ),
    toi_danh_split AS (
        SELECT b.*,
               TRIM(REGEXP_SUBSTR(b.cleaned_toi_danh, '[^,]+', 1, LEVEL)) AS TOI_DANH_ID
          FROM tien_an_base b
        CONNECT BY LEVEL <= REGEXP_COUNT(b.cleaned_toi_danh, ',') + 1
           AND PRIOR b.PNTA_LAI_LICH_ID = b.PNTA_LAI_LICH_ID
           AND PRIOR SYS_GUID() IS NOT NULL
    )
    SELECT
        s.PNTA_LAI_LICH_ID,
        s."ToaXu",
        s."NamXu",
        dtd.TD_TEN AS "ToiDanh",
        s."MucAn",
        s."NamTha"
    FROM toi_danh_split s
    LEFT JOIN DM_TOI_DANHS dtd ON TO_NUMBER(s.TOI_DANH_ID) = dtd.ID
    WHERE s.TOI_DANH_ID IS NOT NULL
    ORDER BY s.PNTA_LAI_LICH_ID, dtd.TD_TEN;

    ------------------------------------------------------------
    -- 4. SP_GET_TIEN_SU
    ------------------------------------------------------------
    OPEN c_tien_su FOR
    SELECT
        pts.TS_PN_LAI_LICH_ID,
        pts.TS_THOI_GIAN              AS "ThoiGian",
        pts.TS_HANH_VI_VI_PHAM        AS "HanhViViPham",
        pts.TS_DON_VI_XU_LY           AS "DonViXuLy",
        pts.TS_HINH_THUC_XU_LY        AS "HinhThuc",
        TO_CHAR(pts.TS_NGAY_BAT_DAU,  'DD/MM/YYYY') AS "TuNgay",
        TO_CHAR(pts.TS_NGAY_KET_THUC, 'DD/MM/YYYY') AS "DenNgay"
    FROM PN_TIEN_SUS pts
    WHERE pts.TS_PN_LAI_LICH_ID = p_pll_id
      AND pts.IS_DELETED = 0;

    ------------------------------------------------------------
    -- 5. SP_GET_BAN_AN_KHAC
    ------------------------------------------------------------
    OPEN c_ban_an_khac 
    FOR
    WITH SPLIT_TOI_DANH AS (
        SELECT /*+ NO_MERGE */
               pbak.BAK_PN_LAI_LICH_ID,
               dtd.ID  AS TOI_DANH_ID,
               dtd.TD_TEN
          FROM PN_BAN_AN_KHACS pbak
          JOIN DM_TOI_DANHS dtd
            ON INSTR(',' || REPLACE(REPLACE(pbak.BAK_DANH_SACH_TOI_DANH_IDS,'[',''),']','') || ',',
                     ',' || dtd.ID || ',') > 0
         WHERE pbak.BAK_DANH_SACH_TOI_DANH_IDS IS NOT NULL
           AND pbak.BAK_PN_LAI_LICH_ID = p_pll_id
           AND NVL(dtd.IS_DELETED, 0) = 0
    ),
    TOI_DANH_AGG AS (
        SELECT /*+ NO_MERGE */
               BAK_PN_LAI_LICH_ID,
               RTRIM(
                   XMLAGG(XMLELEMENT(e, TD_TEN || '; ') ORDER BY TD_TEN)
                       .extract('//text()').GETCLOBVAL(),
                   '; '
               ) AS TOI_DANH
          FROM SPLIT_TOI_DANH
         GROUP BY BAK_PN_LAI_LICH_ID
    )
    SELECT
        pbak.BAK_PN_LAI_LICH_ID,
        pbak.BAK_SO_BAN_AN                           AS "BanAnSo",
        TO_CHAR(pbak.BAK_NGAY_BAN_AN, 'DD/MM/YYYY')  AS "Ngay",
        dctx.CTX_TEN                                 AS "CapXu",
        dcq.CQ_TEN                                AS "ToaXu",
        tda.TOI_DANH                                   AS "ToiDanh",
        dma.MTG_TITLE                         AS "MucAn"
    FROM PN_BAN_AN_KHACS pbak
    LEFT JOIN DM_CAP_TOA_XUS dctx  ON pbak.BAK_CAP_TOA_XU_ID = dctx.ID
    LEFT JOIN DM_CO_QUANS dcq ON pbak.BAK_TOA_XU_ID     = dcq.ID
    LEFT JOIN DM_MA_THOI_GIANS dma       ON pbak.BAK_MUC_AN_ID      = dma.ID
    JOIN TOI_DANH_AGG tda ON pbak.BAK_PN_LAI_LICH_ID = tda.BAK_PN_LAI_LICH_ID
    WHERE pbak.BAK_PN_LAI_LICH_ID = p_pll_id;

    ------------------------------------------------------------
    -- 6. SP_GET_QUYET_DINH_THI_HANH_AN_KHAC
    ------------------------------------------------------------
    OPEN c_quyet_dinh_tha_khac FOR
    SELECT
        pqdbak.QDBAK_PN_LAI_LICH_ID,
        pqdbak.QDBAK_SO_QUYET_DINH                       AS "SoQD",
        TO_CHAR(pqdbak.QDBAK_NGAY_QUYET_DINH, 'DD/MM/YYYY')    AS "NgayQD",
        dcq.CQ_TEN                                       AS "ToaQD",
        pqdbak.QDBAK_SO_BAN_AN                           AS "SoBanAn",
        TO_CHAR(pqdbak.QDBAK_NGAY_BAN_AN, 'DD/MM/YYYY')  AS "Ngay",
        dcq2.CQ_TEN                                      AS "ToaXu"
    FROM PN_QUYET_DINH_BAN_AN_KHACS pqdbak
    LEFT JOIN DM_CO_QUANS dcq  ON pqdbak.QDBAK_TOA_QUYET_DINH_ID = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq2 ON pqdbak.QDBAK_TOA_XU_ID         = dcq2.ID
    WHERE pqdbak.QDBAK_PN_LAI_LICH_ID = p_pll_id;

    ------------------------------------------------------------
    -- 7. 3 store HPBS: tien / khac / trac niem dan su
    --    Thay the -- 7. SP_GET_HINH_PHAT_BO_SUNG
    ------------------------------------------------------------
    OPEN c_hinh_phat_bo_sung_tien FOR
        SELECT
            CAST(NVL(dm.HPBS_TEN, u'') AS NVARCHAR2(2000)) AS HINH_PHAT,
            CAST(NVL(dmtg.MTG_TITLE, u'') AS NVARCHAR2(500)) AS THOI_HAN,
            TO_CHAR(NVL(hp.HPBS_TONG_TIEN_PHAT, 0), 'FM999,999,999,999,999') AS TONG_TIEN,
            TO_CHAR(
                GREATEST(0, NVL(hp.HPBS_TONG_TIEN_PHAT, 0) - NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0)),
                'FM999,999,999,999,999'
            ) AS DA_HOAN,
            TO_CHAR(NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0), 'FM999,999,999,999,999') AS CHUA_HOAN,
            CAST(NVL(gch.GCHPBS_TEN, u'') AS NVARCHAR2(2000)) AS GHI_CHU
        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
        INNER JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
            ON dm.ID = hp.HPBS_HINH_PHAT
           AND NVL(dm.IS_DELETED, 0) = 0
           AND dm.HPBS_MA IN ('210', '211', '220')
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg
            ON NVL(dmtg.IS_DELETED, 0) = 0
           AND dmtg.ID = hp.HPBS_THOI_HAN
        LEFT JOIN QLPN.DM_GHI_CHU_HINH_PHAT_BO_SUNGS gch
            ON gch.ID = hp.HPBS_GHI_CHU
           AND NVL(gch.IS_DELETED, 0) = 0
        WHERE NVL(hp.IS_DELETED, 0) = 0
          AND hp.HPBS_MA_PHAM_NHAN = p_pll_id
        ORDER BY dm.HPBS_MA;

    OPEN c_hinh_phat_bo_sung_khac FOR
        SELECT
            CAST(NVL(dm.HPBS_TEN, u'') AS NVARCHAR2(2000)) AS HINH_PHAT,
            CAST(NVL(dmtg.MTG_TITLE, u'') AS NVARCHAR2(500)) AS THOI_HAN,
            CAST(NVL(gch.GCHPBS_TEN, u'') AS NVARCHAR2(2000)) AS GHI_CHU
        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
        INNER JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
            ON dm.ID = hp.HPBS_HINH_PHAT
           AND NVL(dm.IS_DELETED, 0) = 0
           AND dm.HPBS_MA IN ('110', '120', '130', '140', '150', '160', '170', '310')
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg
            ON NVL(dmtg.IS_DELETED, 0) = 0
           AND dmtg.ID = hp.HPBS_THOI_HAN
        LEFT JOIN QLPN.DM_GHI_CHU_HINH_PHAT_BO_SUNGS gch
            ON gch.ID = hp.HPBS_GHI_CHU
           AND NVL(gch.IS_DELETED, 0) = 0
        WHERE NVL(hp.IS_DELETED, 0) = 0
          AND hp.HPBS_MA_PHAM_NHAN = p_pll_id
        ORDER BY dm.HPBS_MA;

    OPEN c_trach_nhiem_dan_su_tien FOR
        SELECT
            CAST(NVL(dm.HPBS_TEN, u'') AS NVARCHAR2(2000)) AS HINH_PHAT,
            TO_CHAR(NVL(hp.HPBS_TONG_TIEN_PHAT, 0), 'FM999,999,999,999,999') AS TONG_TIEN,
            TO_CHAR(
                GREATEST(0, NVL(hp.HPBS_TONG_TIEN_PHAT, 0) - NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0)),
                'FM999,999,999,999,999'
            ) AS DA_HOAN,
            TO_CHAR(NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0), 'FM999,999,999,999,999') AS CHUA_HOAN,
            hp.HPBS_GHI_CHU_CHI_TIET AS GHI_CHU
            --CAST(NVL(gch.GCHPBS_TEN, u'') AS NVARCHAR2(2000)) AS GHI_CHU
        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
        INNER JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
            ON dm.ID = hp.HPBS_HINH_PHAT
           AND NVL(dm.IS_DELETED, 0) = 0
           AND dm.HPBS_MA IN (
               '250', '251', '252', '260', '261', '262', '263',
               '212', '213', '214',
               '231', '232', '233', '234',
               '240', '999'
           )
        LEFT JOIN QLPN.DM_GHI_CHU_HINH_PHAT_BO_SUNGS gch
            ON gch.ID = hp.HPBS_GHI_CHU
           AND NVL(gch.IS_DELETED, 0) = 0
        WHERE NVL(hp.IS_DELETED, 0) = 0
          AND hp.HPBS_MA_PHAM_NHAN = p_pll_id
        ORDER BY dm.HPBS_MA;
    ------------------------------------------------------------
    -- 8. SP_GET_PHAN_LOAI_GIAM_GIU
    ------------------------------------------------------------
    OPEN c_phan_loai_giam_giu FOR
    SELECT
        pl.PHAM_NHAN_ID,
        TO_CHAR(pl.NGAY_PHAN_LOAI, 'DD/MM/YYYY') AS "NgayPhanLoai",
        dmpl.MPL_TEN         AS "GhiChu",
        dplgg.PLGG_TEN       AS "TuLoai",
        dplgg2.PLGG_TEN      AS "DenLoai"
    FROM PHAN_LOAIS pl
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg  ON pl.TU_LOAI_ID        = dplgg.ID
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg2 ON pl.DEN_LOAI_ID       = dplgg2.ID
    LEFT JOIN DM_MA_PHAN_LOAIES dmpl         ON pl.LOAI_PHAN_LOAI_ID = dmpl.ID
    WHERE pl.PHAM_NHAN_ID = p_pll_id;

    ------------------------------------------------------------
    -- 9. SP_GET_KHEN_THUONG
    ------------------------------------------------------------
    OPEN c_khen_thuong FOR
    SELECT
        kt.PHAM_NHAN_ID,
        TO_CHAR(kt.NGAY_KHEN, 'DD/MM/YYYY')  AS "NgayKhen",
        kt.LY_DO           AS "LyDoKhen",
        kt.HINH_THUC_KHEN  AS "HinhThucKhen"
    FROM KHEN_THUONGS kt
    WHERE kt.PHAM_NHAN_ID = p_pll_id;

    ------------------------------------------------------------
    -- 10. SP_GET_KY_LUAT
    ------------------------------------------------------------
    OPEN c_ky_luat FOR
    SELECT
        kl.PHAM_NHAN_ID,
        TO_CHAR(kl.NGAY_QUYET_DINH, 'DD/MM/YYYY')   AS "NgayKyLuat",
        kl.LY_DO_KY_LUAT_CU_THE       AS "LyDoKyLuat",
        kl.HINH_THUC_KY_LUAT_CU_THE   AS "HinhThucKyLuat",
        TO_CHAR(kl.NGAY_QUYET_DINH_TIEN_BO, 'DD/MM/YYYY')  AS "NgayCNTienBo"
    FROM KY_LUATS kl
    WHERE kl.PHAM_NHAN_ID = p_pll_id;

    ------------------------------------------------------------
    -- 11. SP_GET_GIAM_RIENG
    ------------------------------------------------------------
    OPEN c_giam_rieng FOR
    SELECT
        pgr.GR_PN_LAI_LICH_ID,
        d.LDGRPN_TEN       AS "LyDoGiamRieng",
        dmtg.MTG_TITLE     AS "ThoiHan",
        TO_CHAR(pgr.GR_NGAY_BAT_DAU,  'DD/MM/YYYY') AS "NgayBatDau",
        TO_CHAR(pgr.GR_NGAY_KETTHUC, 'DD/MM/YYYY') AS "NgayKetThuc",
        pgr.GR_LY_DO_DUA_RA  AS "LyDoDuaRa"
    FROM PN_GIAM_RIENGS pgr
    LEFT JOIN DM_LY_DO_GIAM_RIENG_PHAM_NHANS d ON pgr.GR_LY_DO               = d.ID
    LEFT JOIN DM_MA_THOI_GIANS dmtg             ON pgr.GR_THOI_HAN_GIAM_RIENG = dmtg.ID
    WHERE pgr.GR_PN_LAI_LICH_ID = p_pll_id
      AND pgr.IS_DELETED = 0;

    ------------------------------------------------------------
    -- 12. SP_GET_PHAM_TOI_MOI
    ------------------------------------------------------------
    OPEN c_pham_toi_moi FOR
    SELECT
        ptm.PHAM_NHAN_ID,
        TO_CHAR(ptm.NGAY_PHAM_TOI, 'DD/MM/YYYY') AS "NgayPhamToi",
        dtd.TD_TEN           AS "ToiDanh",
        ptm.HINH_THUC_XU_LY  AS "HinhThucXuLy"
    FROM PHAM_TOI_MOIS ptm
    LEFT JOIN DM_TOI_DANHS dtd ON ptm.TOI_DANH_ID = dtd.ID
    WHERE ptm.PHAM_NHAN_ID = p_pll_id;

    ------------------------------------------------------------
    -- 13. SP_GET_KET_QUA_CAI_TAO
    ------------------------------------------------------------
    OPEN c_ket_qua_cai_tao FOR
    SELECT
        xl.PHAM_NHAN_ID,
        xl.XEP_LOAI_NAM  AS "Nam",
        d2.XLCT_TEN      AS "Quy1",
        d3.XLCT_TEN      AS "Quy2",
        d4.XLCT_TEN      AS "DauNam",
        d5.XLCT_TEN      AS "Quy3",
        d6.XLCT_TEN      AS "Quy4",
        d7.XLCT_TEN      AS "CuoiNam",
        d8.XLCT_TEN      AS "CaNam"
    FROM XEP_LOAIS xl
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d1 ON xl.XEP_LOAI_NAM              = d1.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d2 ON xl.XEP_LOAI_QUY_I            = d2.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d3 ON xl.XEP_LOAI_QUY_II           = d3.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d4 ON xl.XEP_LOAI_6_THANG_DAU_NAM  = d4.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d5 ON xl.XEP_LOAI_QUY_III          = d5.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d6 ON xl.XEP_LOAI_QUY_IV           = d6.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d7 ON xl.XEP_LOAI_6_THANG_CUOI_NAM = d7.ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS d8 ON xl.XEP_LOAI_CA_NAM           = d8.ID
    WHERE xl.PHAM_NHAN_ID = p_pll_id;

    ------------------------------------------------------------
    -- 14. SP_GET_GIAM_THOI_HAN
    ------------------------------------------------------------
    OPEN c_giam_thoi_han FOR
    SELECT
        gth.PHAM_NHAN_ID,
        TO_CHAR(gth.NGAY_XET, 'DD/MM/YYYY') AS "NgayXet",
        gth.SO_QUYET_DINH      AS "SoQD",
        TO_CHAR(gth.NGAY_QUYET_DINH, 'DD/MM/YYYY') AS "NgayQD",
        dcq.CQ_TEN || ' ' || d.TTP_TEN             AS "ToaQD",
        dmtg.MTG_TITLE         AS "MucGiam"
    FROM GIAM_THOI_HANS gth
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID        = dmtg.ID
    LEFT JOIN DM_CO_QUANS dcq       ON gth.TOA_QUYET_DINH_ID  = dcq.ID
    left join dm_tinh_thanh_pho d on gth.DIA_PHUONG_ID = d.ID
    WHERE gth.PHAM_NHAN_ID = p_pll_id; 

    ------------------------------------------------------------
    -- 15. SP_GET_TANG_GIAM_HINH_PHAT
    ------------------------------------------------------------
    OPEN c_tang_giam_hinh_phat FOR
    SELECT
        tghp.PHAM_NHAN_ID,
        d.LTGHP_TEN           AS "TangGiam",
        tghp.SO_QUYET_DINH    AS "SoQuyetDinh",
        TO_CHAR(tghp.NGAY_QUYET_DINH, 'DD/MM/YYYY') AS "NgayQuyetDinh",
        dcq.CQ_TEN            AS "CoQuanQuyetDinh",
        dmtg.MTG_TITLE        AS "ThoiHan"
    FROM TANG_GIAM_HINH_PHATS tghp
    JOIN DM_MA_THOI_GIANS dmtg           ON tghp.THOI_HAN_ID          = dmtg.ID
    JOIN DM_CO_QUANS dcq                 ON tghp.DON_VI_QUYET_DINH_ID = dcq.ID
    JOIN DM_LOAI_TANG_GIAM_HINH_PHATS d  ON tghp.LOAI_TANG_GIAM_ID   = d.ID
    WHERE tghp.PHAM_NHAN_ID = p_pll_id
      AND tghp.IS_DELETED = 0;

    ------------------------------------------------------------
    -- 16. SP_GET_MIEN_HINH_PHAT
    ------------------------------------------------------------
    OPEN c_mien_hinh_phat FOR
    WITH mhp_toi_danh_split AS (
        SELECT /*+ NO_MERGE */
               mhp3.PN_LAI_LICH_ID,
               TO_NUMBER(
                   REGEXP_SUBSTR(
                       REPLACE(REPLACE(mhp3.MHP_TOI_DANH_MIEN, '[', ''), ']', ''),
                       '[^,]+', 1, LEVEL)
               ) AS TOI_DANH_ID
          FROM MIEN_HINH_PHATS mhp3
         WHERE mhp3.IS_DELETED = 0
           AND mhp3.PN_LAI_LICH_ID = p_pll_id   -- filter s?m, tránh scan toàn b?ng
        CONNECT BY LEVEL <= REGEXP_COUNT(
                       REPLACE(REPLACE(mhp3.MHP_TOI_DANH_MIEN, '[', ''), ']', ''), ',') + 1
           AND PRIOR mhp3.PN_LAI_LICH_ID = mhp3.PN_LAI_LICH_ID
           AND PRIOR SYS_GUID() IS NOT NULL
    ),
    mhp_toi_danh_agg AS (
        SELECT /*+ NO_MERGE */
               s.PN_LAI_LICH_ID,
               RTRIM(
                   XMLAGG(XMLELEMENT(e, dtd.TD_TEN || ', ') ORDER BY dtd.TD_TEN)
                       .extract('//text()').GETCLOBVAL(), ', '
               ) AS TOI_DANH_MIEN
          FROM mhp_toi_danh_split s
          LEFT JOIN DM_TOI_DANHS dtd ON s.TOI_DANH_ID = dtd.ID
                                    AND NVL(dtd.IS_DELETED, 0) = 0
         GROUP BY s.PN_LAI_LICH_ID
    )
    SELECT
        mhp.PN_LAI_LICH_ID,
        mhp.MHP_SO_QUYET_DINH                         AS "SoQD",
        TO_CHAR(mhp.MHP_NGAY_QUYET_DINH, 'DD/MM/YYYY') AS "NgayQD",
        dcq.CQ_TEN                                     AS "ToaQD",
        td_agg.TOI_DANH_MIEN                           AS "ToiDanhMien",
        CASE
            WHEN NVL(mhp.MHP_THM_YEAR,  0) = 0
             AND NVL(mhp.MHP_THM_MONTH, 0) = 0
             AND NVL(mhp.MHP_THM_DAY,   0) = 0
            THEN 'Không'
            ELSE RTRIM(TRIM(
                CASE WHEN NVL(mhp.MHP_THM_YEAR,  0) > 0 THEN TO_CHAR(mhp.MHP_THM_YEAR)  || ' n?m '   ELSE '' END ||
                CASE WHEN NVL(mhp.MHP_THM_MONTH, 0) > 0 THEN TO_CHAR(mhp.MHP_THM_MONTH) || ' tháng ' ELSE '' END ||
                CASE WHEN NVL(mhp.MHP_THM_DAY,   0) > 0 THEN TO_CHAR(mhp.MHP_THM_DAY)   || ' ngày '  ELSE '' END
            ), ' ')
        END AS "ThoiHanMien"
    FROM MIEN_HINH_PHATS mhp
    LEFT JOIN DM_CO_QUANS dcq ON mhp.MHP_TOA_QUYET_DINH = dcq.ID
                              AND NVL(dcq.IS_DELETED, 0) = 0
    LEFT JOIN mhp_toi_danh_agg td_agg ON mhp.PN_LAI_LICH_ID = td_agg.PN_LAI_LICH_ID
    WHERE mhp.PN_LAI_LICH_ID = p_pll_id
      AND mhp.IS_DELETED = 0;

    ------------------------------------------------------------
    -- 17. SP_GET_HOAN_THI_HANH_AN
    ------------------------------------------------------------
    OPEN c_hoan_thi_hanh_an FOR
    SELECT
        htha.PHAM_NHAN_ID,
        htha.SO_QUYET_DINH     AS "SoQD",
        TO_CHAR(htha.NGAY_QUYET_DINH, 'DD/MM/YYYY') AS "NgayQD",
        dcq.CQ_TEN             AS "ToaQD",
        htha.LY_DO_HOAN        AS "LyDoHoan",
        TO_CHAR(htha.NGAY_THI_HANH_AN, 'DD/MM/YYYY') AS "NgayThiHanh"
    FROM HOAN_THI_HANH_ANS htha
    LEFT JOIN DM_CO_QUANS dcq ON htha.TOA_QUYET_DINH_ID = dcq.ID
    WHERE htha.PHAM_NHAN_ID = p_pll_id
      AND htha.IS_DELETED = 0;

    ------------------------------------------------------------
    -- 18. SP_GET_TRON_TRAI
    ------------------------------------------------------------
    OPEN c_tron_trai FOR
    SELECT
        tt.PHAM_NHAN_ID,
        TO_CHAR(tt.NGAY_TRON, 'DD/MM/YYYY') AS "NgayTron",
        dtht.THT_TEN          AS "TruongHopTron",
        TO_CHAR(tt.NGAY_BAT_LAI, 'DD/MM/YYYY') AS "NgayBat",
        dhtkl.HTKLPN_TEN      AS "HinhThucXuLy"
    FROM TRON_TRAIS tt
    LEFT JOIN DM_TRUONG_HOP_TRONS dtht               ON tt.TRUONG_HOP_TRON_ID  = dtht.ID
    LEFT JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dhtkl  ON tt.HINH_THUC_XU_LY_ID = dhtkl.ID
    WHERE tt.PHAM_NHAN_ID = p_pll_id
      AND tt.IS_DELETED = 0;

    ------------------------------------------------------------
    -- 19. SP_GET_THONG_TIN_CHET
    ------------------------------------------------------------
    OPEN c_thong_tin_chet FOR
    SELECT
        pktc.KTC_PN_LAI_LICH_ID,
        TO_CHAR(pktc.KTC_NGAY_CHET, 'DD/MM/YYYY') AS "NgayChet",
        dthc.THC_TEN                         AS "TruongHopChet",
        pktc.KTC_NGUYEN_NHAN_CHET_CHI_TIET   AS "NguyenNhanChet",
        pktc.KTC_NOI_CHET                    AS "NoiChet"
    FROM PN_KET_THUC_CHETS pktc
    LEFT JOIN DM_TRUONG_HOP_CHETS dthc ON pktc.KTC_DM_TRUONG_HOP_CHET_ID = dthc.ID
    WHERE pktc.KTC_PN_LAI_LICH_ID = p_pll_id;

    ------------------------------------------------------------
    -- 20. SP_GET_TRICH_XUAT
    ------------------------------------------------------------
    OPEN c_trich_xuat FOR
    SELECT
        tx.PHAM_NHAN_ID,
        tx.TX_SO_LENH       AS "SoLenh",
        TO_CHAR(tx.TX_NGAY_RA_LENH, 'DD/MM/YYYY') AS "NgayRaLenh",
        dmtg.MTG_TITLE      AS "ThoiHan",
        TO_CHAR(tx.TX_TU_NGAY, 'DD/MM/YYYY') AS "TuNgay",
        dldtx.LDTX_TEN      AS "LyDo",
        TO_CHAR(tx.TX_NGAY_TRA, 'DD/MM/YYYY') AS "NgayVe"
    FROM TRICH_XUATS tx
    LEFT JOIN DM_LY_DO_TRICH_XUATS dldtx ON tx.TX_LY_DO_ID    = dldtx.ID
    LEFT JOIN DM_MA_THOI_GIANS dmtg      ON tx.TX_THOI_HAN_ID = dmtg.ID
    WHERE tx.PHAM_NHAN_ID = p_pll_id
      AND tx.IS_DELETED = 0;

    ------------------------------------------------------------
    -- 21. SP_GET_TAM_DINH_CHI
    ------------------------------------------------------------
    OPEN c_tam_dinh_chi FOR
    SELECT
        tdc.PHAM_NHAN_ID,
        TO_CHAR(tdc.TU_NGAY, 'DD/MM/YYYY') AS "TuNgay",
        dmtg.MTG_TITLE          AS "ThoiHan",
        d.LDTDC_TEN      AS "LyDo",
        tdc.NOI_VE_XA || ', ' || dttp.TTP_TEN AS "NoiVe",
        TO_CHAR(tdc.NGAY_LAI, 'DD/MM/YYYY') AS "NgayLai"
    FROM TAM_DINH_CHIS tdc
    LEFT JOIN DM_MA_THOI_GIANS  dmtg ON tdc.THOI_HAN_ID          = dmtg.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp ON tdc.NOI_VE_DIA_PHUONG_ID = dttp.ID
    LEFT JOIN DM_LY_DO_TAM_DINH_CHIES d ON tdc.LY_DO_SUC_KHOE_ID = d.ID
    WHERE tdc.PHAM_NHAN_ID = p_pll_id
      AND tdc.IS_DELETED = 0;

    ------------------------------------------------------------
    -- 22. SP_GET_CHUA_BENH_BAT_BUOC
    ------------------------------------------------------------
    OPEN c_chua_benh_bat_buoc FOR
    SELECT
        cbbb.PHAM_NHAN_ID,
        cbbb.SO_QUYET_DINH || ', ' || TO_CHAR(cbbb.NGAY_QUYET_DINH, 'DD/MM/YYYY') AS "SoQD",
        dmtg.MTG_TITLE     AS "ThoiHan",
        TO_CHAR(cbbb.TU_NGAY, 'DD/MM/YYYY') AS "TuNgay",
        dnnc.NNC_TEN       AS "MaBenhTat",
        TO_CHAR(cbbb.NGAY_BAT_DAU, 'DD/MM/YYYY') AS "NgayDi",
        TO_CHAR(cbbb.NGAY_KET_THUC, 'DD/MM/YYYY') AS "NgayVe"
    FROM CHUA_BENH_BAT_BUOCS cbbb
    LEFT JOIN DM_MA_THOI_GIANS   dmtg ON cbbb.THOI_HAN    = dmtg.ID
    LEFT JOIN DM_NGUYEN_NHAN_CHETS dnnc ON cbbb.BENH_TAT_ID = dnnc.ID
    WHERE cbbb.PHAM_NHAN_ID = p_pll_id
      AND cbbb.IS_DELETED = 0;

    ------------------------------------------------------------
    -- 23. SP_GET_NGHIEN_MA_TUY
    ------------------------------------------------------------
    OPEN c_nghien_ma_tuy FOR
    WITH SPLIT_CHAT_MA_TUY AS (
        SELECT /*+ NO_MERGE */
               pnm.NMT_PN_LAI_LICH_ID,
               TO_NUMBER(REGEXP_SUBSTR(
                   REPLACE(REPLACE(pnm.NMT_CHAT_MA_TUY, '[', ''), ']', ''),
                   '[0-9]+', 1, LEVEL)) AS CHAT_MA_TUY_ID
          FROM PN_NGHIEN_MT pnm
         WHERE pnm.NMT_CHAT_MA_TUY IS NOT NULL
           AND pnm.NMT_PN_LAI_LICH_ID = p_pll_id
           AND pnm.IS_DELETED = 0
        CONNECT BY LEVEL <= REGEXP_COUNT(
                       REPLACE(REPLACE(pnm.NMT_CHAT_MA_TUY, '[', ''), ']', ''), ',') + 1
           AND PRIOR pnm.NMT_PN_LAI_LICH_ID = pnm.NMT_PN_LAI_LICH_ID
           AND PRIOR SYS_GUID() IS NOT NULL
    ),
    CHAT_MA_TUY_AGG AS (
        SELECT /*+ NO_MERGE */
               s.NMT_PN_LAI_LICH_ID,
               LISTAGG(DISTINCT dcmt.CMT_TEN, ', ')
                   WITHIN GROUP (ORDER BY dcmt.CMT_TEN) AS CHAT_MA_TUY
          FROM SPLIT_CHAT_MA_TUY s
          LEFT JOIN DM_CHAT_MA_TUIES dcmt ON dcmt.ID = s.CHAT_MA_TUY_ID
         GROUP BY s.NMT_PN_LAI_LICH_ID
    ),
    SPLIT_HINH_THUC_SD AS (
        SELECT /*+ NO_MERGE */
               pnm.NMT_PN_LAI_LICH_ID,
               TO_NUMBER(REGEXP_SUBSTR(
                   REPLACE(REPLACE(pnm.NMT_HINH_THUC_SD, '[', ''), ']', ''),
                   '[0-9]+', 1, LEVEL)) AS HINH_THUC_SD_ID
          FROM PN_NGHIEN_MT pnm
         WHERE pnm.NMT_HINH_THUC_SD IS NOT NULL
           AND pnm.NMT_PN_LAI_LICH_ID = p_pll_id
           AND pnm.IS_DELETED = 0
        CONNECT BY LEVEL <= REGEXP_COUNT(
                       REPLACE(REPLACE(pnm.NMT_HINH_THUC_SD, '[', ''), ']', ''), ',') + 1
           AND PRIOR pnm.NMT_PN_LAI_LICH_ID = pnm.NMT_PN_LAI_LICH_ID
           AND PRIOR SYS_GUID() IS NOT NULL
    ),
    HINH_THUC_SD_AGG AS (
        SELECT /*+ NO_MERGE */
               s.NMT_PN_LAI_LICH_ID,
               LISTAGG(DISTINCT dhtsd.HTSDMT_TEN, ', ')
                   WITHIN GROUP (ORDER BY dhtsd.HTSDMT_TEN) AS HINH_THUC_SD
          FROM SPLIT_HINH_THUC_SD s
          LEFT JOIN DM_HINH_THUC_SU_DUNG_MA_TUIES dhtsd ON dhtsd.ID = s.HINH_THUC_SD_ID
         GROUP BY s.NMT_PN_LAI_LICH_ID
    )
    SELECT
        pnm.NMT_PN_LAI_LICH_ID,
        cmt.CHAT_MA_TUY       AS "ChatMaTuy",
        htsd.HINH_THUC_SD     AS "HinhThuc",
        dccxdmt.CCXDMT_TEN    AS "CanCuXacDinh",
        dmthnmt.THNMT_TEN     AS "TruongHopNghien",
        pnm.NMT_GHI_CHU       AS "GhiChu"
    FROM PN_NGHIEN_MT pnm
    LEFT JOIN CHAT_MA_TUY_AGG cmt    ON cmt.NMT_PN_LAI_LICH_ID  = pnm.NMT_PN_LAI_LICH_ID
    LEFT JOIN HINH_THUC_SD_AGG htsd  ON htsd.NMT_PN_LAI_LICH_ID = pnm.NMT_PN_LAI_LICH_ID
    LEFT JOIN DM_MT_TRUONG_HOP_NGHIEN_MA_TUIES dmthnmt ON pnm.NMT_TRUONG_HOP_NGHIEN = dmthnmt.ID
    LEFT JOIN DM_CAN_CU_XAC_DINH_MA_TUIES dccxdmt      ON pnm.NMT_CAN_CU_XAC_DINH  = dccxdmt.ID
    WHERE pnm.NMT_PN_LAI_LICH_ID = p_pll_id
      AND pnm.IS_DELETED = 0;

    ------------------------------------------------------------
    -- 24. SP_GET_HUY_AN
    ------------------------------------------------------------
    OPEN c_huy_an FOR
    SELECT
        ha.PHAM_NHAN_ID,
        ha.SO_QUYET_DINH    AS "SoQD",
        TO_CHAR(ha.NGAY_QUYET_DINH, 'DD/MM/YYYY') AS "NgayQD",
        dcq.CQ_TEN          AS "ToaQD",
        TO_CHAR(ha.NGAY_TRA_TU_DO, 'DD/MM/YYYY') AS "NgayTraTuDo"
    FROM HUY_ANS ha
    LEFT JOIN DM_CO_QUANS dcq ON ha.TOA_QUYET_DINH_ID = dcq.ID
    WHERE ha.PHAM_NHAN_ID = p_pll_id
      AND ha.IS_DELETED = 0;

    ------------------------------------------------------------
    -- 25. SP_GET_AN_GIAM
    ------------------------------------------------------------
    OPEN c_an_giam FOR
    SELECT
        ag.PHAM_NHAN_ID,
        ag.AG_SO_QD_TOA_AN    AS "SoQD",
        TO_CHAR(ag.AG_NGAY_QD_TOA_AN, 'DD/MM/YYYY') AS "NgayQD",
        ag.AG_LY_DO_AN_GIAM   AS "LyDoAnGiam",
        ag.AG_GHI_CHU         AS "ChuThich"
    FROM AN_GIAMS ag
    WHERE ag.PHAM_NHAN_ID = p_pll_id;

    ------------------------------------------------------------
    -- 26. SP_GET_DAC_XA
    ------------------------------------------------------------
    OPEN c_dac_xa FOR
    SELECT
        pdx.PNLAI_LICH_ID,
        TO_CHAR(pdx.DX_NGAY_XET,        'DD/MM/YYYY') AS "NgayXet",
        TO_CHAR(pdx.DX_NGAY_THA,        'DD/MM/YYYY') AS "NgayTha",
        TO_CHAR(pdx.DX_NGAY_TRINH_DIEN, 'DD/MM/YYYY') AS "NgayTrinhDien",
        CASE
            WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN),    u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN),   u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                             THEN u', ' || dxp_thuong_tru.XP_TEN
                             ELSE dxp_thuong_tru.XP_TEN END
                    ELSE u'' END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                             THEN u', ' || dttp_thuong_tru.TTP_TEN
                             ELSE dttp_thuong_tru.TTP_TEN END
                    ELSE u'' END
            )
            ELSE NULL
        END AS "NoiVe"
    FROM PN_DAC_XAS pdx
    JOIN PN_LAI_LICHS ll ON pdx.PNLAI_LICH_ID = ll.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
           ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
          AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
           ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
          AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    WHERE pdx.PNLAI_LICH_ID = p_pll_id;

    ------------------------------------------------------------
    -- 27. SP_GET_RA_TRAI
    ------------------------------------------------------------
    OPEN c_ra_trai FOR
    SELECT
        pktrt.KTRT_PN_LAI_LICH_ID,
        TO_CHAR(pktrt.KTRT_NGAY_THA, 'DD/MM/YYYY') AS "NgayTha",
        dtht.THT_TEN                 AS "TruongHopTha",
        TO_CHAR(pktrt.KTRT_NGAY_TRINH_DIEN, 'DD/MM/YYYY') AS "NgayTrinhDien",
        CASE
            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN),    u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN),   u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                             THEN u', ' || dxp_thuong_tru.XP_TEN
                             ELSE dxp_thuong_tru.XP_TEN END
                    ELSE u'' END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                             THEN u', ' || dttp_thuong_tru.TTP_TEN
                             ELSE dttp_thuong_tru.TTP_TEN END
                    ELSE u'' END
            )
            ELSE NULL
        END AS "NoiVe"
    FROM PN_KET_THUC_RA_TRAIS pktrt
    LEFT JOIN DM_TRUONG_HOP_THAS dtht ON pktrt.KTRT_TRUONG_HOP_THA_ID = dtht.ID
    JOIN PN_LAI_LICHS pll 
    ON  pktrt.KTRT_PN_LAI_LICH_ID = pll.ID
    AND  pll.ID = p_pll_id
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
                                     ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
                                    AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
                                     ON pll.LL_DIA_CHI_THUONG_TRU_WARD   = dxp_thuong_tru.ID
                                    AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    WHERE pktrt.KTRT_PN_LAI_LICH_ID = p_pll_id;

    ------------------------------------------------------------
    -- Tr? v? t?t c? 27 cursor
    ------------------------------------------------------------
    DBMS_SQL.RETURN_RESULT(c_thong_tin_lai_lich);   --  1
    DBMS_SQL.RETURN_RESULT(c_quan_he_gia_dinh);     --  2
    DBMS_SQL.RETURN_RESULT(c_tien_an);              --  3
    DBMS_SQL.RETURN_RESULT(c_tien_su);              --  4
    DBMS_SQL.RETURN_RESULT(c_ban_an_khac);          --  5
    DBMS_SQL.RETURN_RESULT(c_quyet_dinh_tha_khac);  --  6
    DBMS_SQL.RETURN_RESULT(c_hinh_phat_bo_sung_tien);      --  7a
    DBMS_SQL.RETURN_RESULT(c_hinh_phat_bo_sung_khac);      --  7b
    DBMS_SQL.RETURN_RESULT(c_trach_nhiem_dan_su_tien);     --  7c
    DBMS_SQL.RETURN_RESULT(c_phan_loai_giam_giu);   --  8
    DBMS_SQL.RETURN_RESULT(c_khen_thuong);          --  9
    DBMS_SQL.RETURN_RESULT(c_ky_luat);              -- 10
    DBMS_SQL.RETURN_RESULT(c_giam_rieng);           -- 11
    DBMS_SQL.RETURN_RESULT(c_pham_toi_moi);         -- 12
    DBMS_SQL.RETURN_RESULT(c_ket_qua_cai_tao);      -- 13
    DBMS_SQL.RETURN_RESULT(c_giam_thoi_han);        -- 14
    DBMS_SQL.RETURN_RESULT(c_tang_giam_hinh_phat);  -- 15
    DBMS_SQL.RETURN_RESULT(c_mien_hinh_phat);       -- 16
    DBMS_SQL.RETURN_RESULT(c_hoan_thi_hanh_an);     -- 17
    DBMS_SQL.RETURN_RESULT(c_tron_trai);            -- 18
    DBMS_SQL.RETURN_RESULT(c_thong_tin_chet);       -- 19
    DBMS_SQL.RETURN_RESULT(c_trich_xuat);           -- 20
    DBMS_SQL.RETURN_RESULT(c_tam_dinh_chi);         -- 21
    DBMS_SQL.RETURN_RESULT(c_chua_benh_bat_buoc);   -- 22
    DBMS_SQL.RETURN_RESULT(c_nghien_ma_tuy);        -- 23
    DBMS_SQL.RETURN_RESULT(c_huy_an);               -- 24
    DBMS_SQL.RETURN_RESULT(c_an_giam);              -- 25
    DBMS_SQL.RETURN_RESULT(c_dac_xa);               -- 26
    DBMS_SQL.RETURN_RESULT(c_ra_trai);              -- 27

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        NULL;
    WHEN TOO_MANY_ROWS THEN
        RAISE_APPLICATION_ERROR(-20001,
            'Có nhi?u h?n 1 b?n ghi cho ph?m nhân ID: ' || p_pll_id);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: '      || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: '   || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END SP_GET_LAI_LICH_FULL;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_LAP_HO_SO_PHAM_NHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_LAP_HO_SO_PHAM_NHAN" (
    p_pham_nhan_ids IN VARCHAR2
)
AS
    p_cursor SYS_REFCURSOR;
BEGIN
--	BEGIN
--	SP_GET_LAP_HO_SO_PHAM_NHAN(1);
--END;
    OPEN p_cursor FOR
    SELECT *
    FROM (
	    SELECT
            hs.NGAY_DK             				 AS "NgayLapHoSo",
            NULL                                 AS "CanCuQuyetDinh",

            -- BÊN GIAO (BG)
            hs.HO_TEN_BG                         AS "HoTenBenGiao",
            cvbg.CV_TEN                          AS "ChucVuBenGiao",
            cbg.CB_TEN                           AS "CapBacBenGiao",
            cqg.CQ_TEN                           AS "DonViBenGiao",

            -- BÊN NH?N (BN)
            hs.HO_TEN_BN                         AS "HoTenBenNhan",
            cvbn.CV_TEN                          AS "ChucVuBenNhan",
            cbn.CB_TEN                           AS "CapBacBenNhan",
            cqn.CQ_TEN                           AS "DonViBenNhan",


            -- CÁN B? ??NG KÝ (DK)
            hs.HO_TEN_DK                         AS "TenCanBoDangKy",
            cvcb.CV_TEN                          AS "ChucVuCanBoDangKy",
            cbc.CB_TEN                           AS "CapBacCanBoDangKy",
            cqc.CQ_TEN                           AS "DonViCanBoDangKy",

            -- PH?M NHÂN
            vpllct.SO_HO_SO                      AS "SoHSLD",
            vpllct.HO_TEN                        AS "HoTen",
            vpllct.NAM_SINH                      AS "NamSinh",
            vpllct.GIOI_TINH                     AS "GioiTinh",
            vpllct.NOI_THUONG_TRU_DAY_DU         AS "DiaChiThuongTru",
            vpllct.TOI_DANH                      AS "ToiDanh",
            vpllct.NGAY_BAT_AN_PHAT              AS "NgayBat",
            vpllct.AN_PHAT                       AS "AnPhat",

			ROW_NUMBER() OVER (
		        PARTITION BY pll.ID
		        ORDER BY hspn.PN_HSNV_ID DESC
		    ) rn

        FROM PN_LAI_LICHS pll
        JOIN VW_PN_LAI_LICH_CHI_TIET vpllct
            ON pll.ID = vpllct.PHAM_NHAN_ID
        LEFT JOIN PN_HSNV_PHAM_NHANS hspn
        	ON hspn.PN_LAI_LICH_ID = pll.ID
        LEFT JOIN PN_HSNVS hs
            ON hs.ID = hspn.PN_HSNV_ID
	    LEFT JOIN DM_CHUC_VUS cvbg
	        ON hs.CHUC_VU_BG = TO_CHAR(cvbg.ID) 
	    LEFT JOIN DM_CHUC_VUS cvbn
	        ON hs.CHUC_VU_BN = TO_CHAR(cvbn.ID)
	    LEFT JOIN DM_CHUC_VUS cvcb
	        ON hs.CHUC_VU_DK = TO_CHAR(cvcb.ID)
	    LEFT JOIN DM_CO_QUANS cqg
        	ON hs.MA_CQ_BG = TO_CHAR(cqg.ID)
        LEFT JOIN DM_CO_QUANS cqn
        	ON hs.MA_CQ_BN = TO_CHAR(cqn.ID)
        LEFT JOIN DM_CO_QUANS cqc
        	ON hs.MA_CQ_DK = TO_CHAR(cqc.ID)
        LEFT JOIN DM_CAP_BACS cbg
        	ON hs.CAP_BAC_BG = TO_CHAR(cbg.ID)
        LEFT JOIN DM_CAP_BACS cbn
        	ON hs.CAP_BAC_BN = TO_CHAR(cbn.ID)
        LEFT JOIN DM_CAP_BACS cbc
        	ON hs.CAP_BAC_DK = TO_CHAR(cbc.ID) 

        -- x? lý multiple ID
        WHERE pll.ID IN (
            SELECT TO_NUMBER(REGEXP_SUBSTR(p_pham_nhan_ids, '[^,]+', 1, LEVEL))
            FROM dual
            CONNECT BY REGEXP_SUBSTR(p_pham_nhan_ids, '[^,]+', 1, LEVEL) IS NOT NULL
        )
    ) rs
    WHERE rn = 1

    ORDER BY FN_SWAP_FIRST_LAST_SORT(rs."HoTen");

    DBMS_SQL.RETURN_RESULT(p_cursor);
END SP_GET_LAP_HO_SO_PHAM_NHAN;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_MIEN_HINH_PHAT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_MIEN_HINH_PHAT" (
    p_PHAM_NHAN_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT
        mhp.PN_LAI_LICH_ID,
        mhp.MHP_SO_QUYET_DINH   AS "SoQD",
        TO_CHAR(mhp.MHP_NGAY_QUYET_DINH,'DD/MM/YYYY') AS "NgayQD",
        dcq.CQ_TEN               AS "ToaQD",
        td_agg.TOI_DANH_MIEN     AS "ToiDanhMien",
        CASE
            WHEN NVL(mhp.MHP_THM_YEAR, 0) = 0
             AND NVL(mhp.MHP_THM_MONTH, 0) = 0
             AND NVL(mhp.MHP_THM_DAY, 0) = 0
            THEN 'Không'
            ELSE RTRIM(
                    TRIM(
                        CASE WHEN NVL(mhp.MHP_THM_YEAR,  0) > 0 THEN TO_CHAR(mhp.MHP_THM_YEAR)  || ' n?m '   ELSE '' END ||
                        CASE WHEN NVL(mhp.MHP_THM_MONTH, 0) > 0 THEN TO_CHAR(mhp.MHP_THM_MONTH) || ' tháng ' ELSE '' END ||
                        CASE WHEN NVL(mhp.MHP_THM_DAY,   0) > 0 THEN TO_CHAR(mhp.MHP_THM_DAY)   || ' ngày '  ELSE '' END
                    ), ' ')
        END AS "ThoiHanMien"
    FROM MIEN_HINH_PHATS mhp
    LEFT JOIN DM_CO_QUANS dcq 
           ON mhp.MHP_TOA_QUYET_DINH = dcq.ID
          AND NVL(dcq.IS_DELETED, 0) = 0   -- ? thêm
    LEFT JOIN (
        SELECT
            mhp2.PN_LAI_LICH_ID,
            RTRIM(
                XMLAGG(
                    XMLELEMENT(e, dtd.TD_TEN || ', ')
                    ORDER BY dtd.TD_TEN
                ).extract('//text()').GETCLOBVAL(),
                ', '
            ) AS TOI_DANH_MIEN
FROM MIEN_HINH_PHATS mhp2
        LEFT JOIN (
            SELECT DISTINCT
                mhp3.PN_LAI_LICH_ID,
                TO_NUMBER(
                    REGEXP_SUBSTR(
                        REPLACE(REPLACE(mhp3.MHP_TOI_DANH_MIEN, '[', ''), ']', ''),
                        '[^,]+',
                        1,
                        LEVEL
                    )
                ) AS TOI_DANH_ID
            FROM MIEN_HINH_PHATS mhp3
            WHERE mhp3.IS_DELETED = 0
            CONNECT BY LEVEL <= REGEXP_COUNT(
                REPLACE(REPLACE(mhp3.MHP_TOI_DANH_MIEN, '[', ''), ']', ''),
                ','
            ) + 1
            AND PRIOR mhp3.PN_LAI_LICH_ID = mhp3.PN_LAI_LICH_ID
            AND PRIOR SYS_GUID() IS NOT NULL
        ) td ON mhp2.PN_LAI_LICH_ID = td.PN_LAI_LICH_ID
        LEFT JOIN DM_TOI_DANHS dtd
               ON td.TOI_DANH_ID = dtd.ID
              AND NVL(dtd.IS_DELETED, 0) = 0
        WHERE mhp2.IS_DELETED = 0   -- ? chuy?n xu?ng sau t?t c? JOIN
        GROUP BY mhp2.PN_LAI_LICH_ID
    ) td_agg ON mhp.PN_LAI_LICH_ID = td_agg.PN_LAI_LICH_ID
    WHERE mhp.PN_LAI_LICH_ID = p_PHAM_NHAN_ID
      AND mhp.IS_DELETED = 0;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_MIEN_HINH_PHAT;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_NANG_HA_LOAI_PHAM_NHAN_PT45D
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_NANG_HA_LOAI_PHAM_NHAN_PT45D" (
    p_pham_nhan_id   IN NUMBER,
    p_ngay_phan_loai IN VARCHAR2
)
AS
    c1 SYS_REFCURSOR;
    v_ngay_phan_loai DATE;
BEGIN
    IF p_pham_nhan_id IS NULL THEN
        RAISE_APPLICATION_ERROR(-20001, 'p_pham_nhan_id khong duoc de trong');
    END IF;

    IF p_ngay_phan_loai IS NULL OR TRIM(p_ngay_phan_loai) = '' THEN
        RAISE_APPLICATION_ERROR(-20001, 'p_ngay_phan_loai khong duoc de trong');
    END IF;

    v_ngay_phan_loai := TO_DATE(TRIM(p_ngay_phan_loai), 'DD/MM/YYYY');

    OPEN c1 FOR
        WITH pl_one AS (
            SELECT *
            FROM (
                SELECT
                    pl.id,
                    pl.pham_nhan_id,
                    pl.ngay_phan_loai,
                    pl.loai_phan_loai_id,
                    pl.tu_loai_id,
                    pl.den_loai_id,
                    ROW_NUMBER() OVER (
                        ORDER BY pl.id DESC
                    ) AS rn
                FROM qlpn.phan_loais pl
                WHERE NVL(pl.is_deleted, 0) = 0
                  AND pl.pham_nhan_id = p_pham_nhan_id
                  AND TRUNC(pl.ngay_phan_loai) = TRUNC(v_ngay_phan_loai)
            )
            WHERE rn = 1
        ),
        vw_one AS (
            SELECT v.*
            FROM qlpn.vw_pn_lai_lich_chi_tiet v
            WHERE NVL(v.is_deleted, 0) = 0
              AND v.pham_nhan_id = p_pham_nhan_id
        )
        SELECT
            tu_plgg.plgg_ten AS TU_LOAI,
            den_plgg.plgg_ten AS DEN_LOAI,
            v.ho_ten AS HO_TEN,
            v.gioi_tinh AS GIOI_TINH,
            v.ngay_sinh AS NGAY_SINH,
            v.ten_khac AS HO_TEN_KHAC,
            NVL(v.noi_thuong_tru_day_du, v.dia_chi_thuong_tru) AS NOI_THUONG_TRU,
            v.dan_toc AS DAN_TOC,
            v.quoc_tich AS QUOC_TICH,
            v.toi_danh AS TOI_DANH,
            TO_CHAR(v.ngay_bat_an_phat, 'DD/MM/YYYY') AS NGAY_BAT,
            v.an_phat AS AN_PHAT,
            v.so_ban_an AS SO_BAN_AN,
            TO_CHAR(v.ngay_ban_an, 'DD/MM/YYYY') AS NGAY_BAN_AN,
            v.toa_xu_ten AS TOA_AN_XU,
            v.toa_xu_dia_phuong AS DIA_PHUONG_XU,
            v.so_qd_tha AS SO_QD_THA,
            TO_CHAR(v.ngay_qd_tha, 'DD/MM/YYYY') AS NGAY_QD_THA,
            v.co_quan_qd_tha AS TOA_AN_QD_THA,
            v.toa_qd_tha_dia_phuong AS DIA_PHUONG_QD_THA,
            TO_CHAR(v.ngay_den_trai, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
            v.nhan_than AS NHAN_THAN,
            v.phan_doi ,
            v.phan_trai ,
--            TRIM(NVL(v.phan_doi, '') ||
--                 CASE
--                     WHEN v.phan_doi IS NOT NULL AND v.phan_trai IS NOT NULL THEN ', '
--                     ELSE ''
--                 END ||
--                 NVL(v.phan_trai, '')) AS PHAN_DOI,
            TO_CHAR(ngay_phan_loai, 'DD/MM/YYYY') AS ngay_phan_loai     
        FROM pl_one pl
        INNER JOIN vw_one v
                ON v.pham_nhan_id = pl.pham_nhan_id
        LEFT JOIN qlpn.dm_phan_loai_giam_gius tu_plgg
               ON tu_plgg.id = pl.tu_loai_id
              AND NVL(tu_plgg.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_phan_loai_giam_gius den_plgg
               ON den_plgg.id = pl.den_loai_id
              AND NVL(den_plgg.is_deleted, 0) = 0;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_NANG_HA_LOAI_PHAM_NHAN_PT45D: ' || SQLERRM);
END SP_GET_NANG_HA_LOAI_PHAM_NHAN_PT45D;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_NGHIEN_MA_TUY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_NGHIEN_MA_TUY" (
    p_LAI_LICH_ID IN NUMBER
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH SPLIT_CHAT_MA_TUY AS (
        SELECT
            pnm.NMT_PN_LAI_LICH_ID,
            TO_NUMBER(
                REGEXP_SUBSTR(
                    REPLACE(REPLACE(pnm.NMT_CHAT_MA_TUY, '[', ''), ']', ''),
                    '[0-9]+',
                    1,
                    LEVEL
                )
            ) AS CHAT_MA_TUY_ID
        FROM PN_NGHIEN_MT pnm
        WHERE pnm.NMT_CHAT_MA_TUY IS NOT NULL
          AND pnm.NMT_PN_LAI_LICH_ID = p_LAI_LICH_ID
          AND pnm.IS_DELETED = 0
        CONNECT BY LEVEL <= REGEXP_COUNT(
                REPLACE(REPLACE(pnm.NMT_CHAT_MA_TUY, '[', ''), ']', ''),
                ','
            ) + 1
           AND PRIOR pnm.NMT_PN_LAI_LICH_ID = pnm.NMT_PN_LAI_LICH_ID
           AND PRIOR SYS_GUID() IS NOT NULL
    ),
    CHAT_MA_TUY_AGG AS (
        SELECT
            s.NMT_PN_LAI_LICH_ID,
            LISTAGG(DISTINCT dcmt.CMT_TEN, ', ')
                WITHIN GROUP (ORDER BY dcmt.CMT_TEN) AS CHAT_MA_TUY
        FROM SPLIT_CHAT_MA_TUY s
        LEFT JOIN DM_CHAT_MA_TUIES dcmt
            ON dcmt.ID = s.CHAT_MA_TUY_ID
        GROUP BY s.NMT_PN_LAI_LICH_ID
    ),
    SPLIT_HINH_THUC_SD AS (
        SELECT
            pnm.NMT_PN_LAI_LICH_ID,
            TO_NUMBER(
                REGEXP_SUBSTR(
                    REPLACE(REPLACE(pnm.NMT_HINH_THUC_SD, '[', ''), ']', ''),
                    '[0-9]+',
                    1,
                    LEVEL
                )
            ) AS HINH_THUC_SD_ID
        FROM PN_NGHIEN_MT pnm
        WHERE pnm.NMT_HINH_THUC_SD IS NOT NULL
          AND pnm.NMT_PN_LAI_LICH_ID = p_LAI_LICH_ID
          AND pnm.IS_DELETED = 0
        CONNECT BY LEVEL <= REGEXP_COUNT(
                REPLACE(REPLACE(pnm.NMT_HINH_THUC_SD, '[', ''), ']', ''),
                ','
            ) + 1
           AND PRIOR pnm.NMT_PN_LAI_LICH_ID = pnm.NMT_PN_LAI_LICH_ID
           AND PRIOR SYS_GUID() IS NOT NULL
    ),
    HINH_THUC_SD_AGG AS (
        SELECT
            s.NMT_PN_LAI_LICH_ID,
            LISTAGG(DISTINCT dhtsd.HTSDMT_TEN, ', ')
                WITHIN GROUP (ORDER BY dhtsd.HTSDMT_TEN) AS HINH_THUC_SD
        FROM SPLIT_HINH_THUC_SD s
        LEFT JOIN DM_HINH_THUC_SU_DUNG_MA_TUIES dhtsd
            ON dhtsd.ID = s.HINH_THUC_SD_ID
        GROUP BY s.NMT_PN_LAI_LICH_ID
    )
    SELECT
        pnm.NMT_PN_LAI_LICH_ID,
        cmt.CHAT_MA_TUY AS "ChatMaTuy",
        htsd.HINH_THUC_SD AS "HinhThuc",
        dccxdmt.CCXDMT_TEN AS "CanCuXacDinh",
        dmthnmt.THNMT_TEN AS "TruongHopNghien",
        pnm.NMT_GHI_CHU AS "GhiChu"
    FROM PN_NGHIEN_MT pnm
    LEFT JOIN CHAT_MA_TUY_AGG cmt
        ON cmt.NMT_PN_LAI_LICH_ID = pnm.NMT_PN_LAI_LICH_ID
    LEFT JOIN HINH_THUC_SD_AGG htsd
        ON htsd.NMT_PN_LAI_LICH_ID = pnm.NMT_PN_LAI_LICH_ID
    LEFT JOIN DM_MT_TRUONG_HOP_NGHIEN_MA_TUIES dmthnmt
        ON pnm.NMT_TRUONG_HOP_NGHIEN = dmthnmt.ID
    LEFT JOIN DM_CAN_CU_XAC_DINH_MA_TUIES dccxdmt
        ON pnm.NMT_CAN_CU_XAC_DINH = dccxdmt.ID
    WHERE pnm.NMT_PN_LAI_LICH_ID = p_LAI_LICH_ID
	AND pnm.IS_DELETED = 0;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_NGHIEN_MA_TUY;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAM_NHAN_BY_ID
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAM_NHAN_BY_ID" (
    p_pham_nhan_id IN NVARCHAR2 DEFAULT ''
) AS
    v_pham_nhan_id NUMBER;
    c1 SYS_REFCURSOR;
BEGIN
    -- X? lý tham s? ID ph?m nhân
    IF p_pham_nhan_id IS NULL OR TRIM(p_pham_nhan_id) = '' THEN
        v_pham_nhan_id := NULL;
    ELSE
        v_pham_nhan_id := TO_NUMBER(TRIM(p_pham_nhan_id));
    END IF;

    -- Debug output
    DBMS_OUTPUT.PUT_LINE('L?y thông tin ph?m nhân theo ID: ' || NVL(TO_CHAR(v_pham_nhan_id), '(tr?ng)'));

    -- Tr? v? 1 dòng thông tin ph?m nhân (s? l??c lý l?ch), g?m thông tin b?n án và quy?t ??nh t? PN_THI_HANH_AN
    OPEN c1 FOR
        SELECT
            v.PHAM_NHAN_ID,
            v.HO_TEN,
            ll.LL_TEN_KHAC AS HO_TEN_KHAC,
            v.NAM_SINH,
            v.NGAY_SINH,
            v.GIOI_TINH,
            ll.LL_NGUYEN_QUAN AS NGUYEN_QUAN,
            v.SO_HO_SO,
            v.CCCD,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            ll.LL_NOI_THA_VE_CU_TRU AS NOI_CHAP_HANH_THOI_GIAN_THU_THACH,
            v.DIA_CHI_THUONG_TRU,
            v.TINH_THANH_THUONG_TRU,
            v.PHUONG_XA_THUONG_TRU,
            v.DAN_TOC,
            v.TON_GIAO,
            v.QUOC_TICH,
            v.HOC_VAN AS TRINH_DO_HOC_VAN,
            v.NGHE_NGHIEP AS NGHE_NGHIEP_TRUOC_KHI_BAT,
            v.TOI_DANH,
            v.AN_PHAT,
            v.NGAY_BAT_AN_PHAT,
            v.TAM_GIAM,
            v.DA_GIAM,
            v.NGAY_DEN_TRAI AS NGAY_DEN_CHAP_HANH_AN,
            v.NGAY_HET_AN,
            v.PHAN_DOI,
            v.TRAI_GIAM AS NOI_CHAP_HANH_AN,
            v.TINH_TRANG_SUC_KHOE AS TINH_TRANG_SUC_KHOE_HIEN_NAY,
            v.GHI_CHU,
            v.GHI_CHU_RIENG,
            v.GHI_CHU_CHI_TIET,
            v.TOI_DANH_ID,
            v.TRAI_GIAM_ID,
            v.PHAN_DOI_ID,
            -- Thông tin b?n án (t? PN_THI_HANH_AN)
            tha.THA_SO_BAN_AN AS SO_BAN_AN,
            tha.THA_NGAY_BAN_AN AS NGAY_BAN_AN,
            tha.THA_AN_PHAT AS AN_PHAT_THA,
            tha.THA_CAN_CU_TUYEN_PHAT AS CAN_CU_TUYEN_PHAT,
            tha.THA_NGAY_BAT AS NGAY_BAT_THA,
            tha.THA_NGAY_PHAM_TOI AS NGAY_PHAM_TOI,
            tha.THA_THOI_GIAN_TAM_GIAM AS THOI_GIAN_TAM_GIAM,
            tha.THA_THOI_GIAN_TAM_GIU AS THOI_GIAN_TAM_GIU,
            tha.THA_NGAY_DEN_TRAI AS NGAY_DEN_TRAI_THA,
            tha.THA_NGAY_HET_HAN AS NGAY_HET_HAN_THA,
            tha."THA_TONG_AN_GIAM" AS TONG_AN_GIAM,
            tha."THA_NGAY_BAT_DAU_O_TU" AS NGAY_BAT_DAU_O_TU,
            -- Quy?t ??nh (t? PN_THI_HANH_AN)
            tha.THA_SO_QD_THA AS SO_QUYET_DINH_THA,
            tha.THA_NGAY_QD_THA AS NGAY_QUYET_DINH_THA,
            tha.THA_SO_QD_DIEU_CHUYEN AS SO_QD_DIEU_CHUYEN,
            tha.THA_NGAY_QD_DIEU_CHUYEN AS NGAY_QD_DIEU_CHUYEN,
            tha."THA_SO_DE_NGHI" AS SO_DE_NGHI,
            tha."THA_NGAY_DE_NGHI" AS NGAY_DE_NGHI,
            -- II. Tóm t?t quá trình ph?m t?i (theo b?n án)
            tha."THA_DIEU" AS TOM_TAT_QUA_TRINH_PHAM_TOI_DIEM,
            tha."THA_KHOAN" AS TOM_TAT_QUA_TRINH_PHAM_TOI_KHOAN,
            -- III. Quan h? gia ?ình
            ll."LL_NHAN_THAN" AS QUAN_HE_GIA_DINH,
            -- V. Nh?n xét và ?? ngh?
            tha."THA_GHI_CHU_DAC_BIET" AS NHAN_XET_VA_DE_NGHI,
            -- B? sung: Tr?n, T?m ?ình ch?, Hình ph?t b? sung, Tình ti?t ???c ?u tiên (dùng NULL do ch?a có c?t; khi ?ã có c?t thì ??i l?i ll."LL_TRON", ll."LL_TAM_DINH_CHI", tha."THA_HINH_PHAT_BO_SUNG", ll."LL_TINH_TIET_UU_TIEN")
            CAST(NULL AS NVARCHAR2(500)) AS TRON,
            CAST(NULL AS NVARCHAR2(500)) AS TAM_DINH_CHI,
            CAST(NULL AS NVARCHAR2(2000)) AS HINH_PHAT_BO_SUNG,
            CAST(NULL AS NVARCHAR2(2000)) AS TINH_TIET_UU_TIEN,
            -- IV. X?p lo?i ch?p hành án t?ng quý (format v?n b?n: + N?m YYYY: Quý N: x?p lo?i, xu?ng dòng; dòng k?t "Th?i gian ti?p theo...")
            xl.XEP_LOAI_CHAP_HANH_AN,
            v.CREATION_TIME,
            v.LAST_MODIFICATION_TIME
        FROM VW_PN_LAI_LICH_CHI_TIET v
        INNER JOIN PN_LAI_LICHS ll ON ll.ID = v.PHAM_NHAN_ID AND ll.IS_DELETED = 0
        LEFT JOIN (
            SELECT tha2.*,
                   ROW_NUMBER() OVER (PARTITION BY tha2.THA_PNLAI_LICH_ID ORDER BY tha2.THA_NGAY_BAN_AN DESC NULLS LAST, tha2.ID DESC) AS rn
            FROM PN_THI_HANH_AN tha2
        ) tha ON tha.THA_PNLAI_LICH_ID = v.PHAM_NHAN_ID AND tha.rn = 1
        LEFT JOIN (
            SELECT u.PHAM_NHAN_ID,
                   TO_NCHAR( LISTAGG(u'+ N\0103m ' || u.NAM || u': Qu\00fd ' || u.Q || u': ' || NVL(u.GHI_CHU, u''), NCHR(10)) WITHIN GROUP (ORDER BY u.NAM, u.Q) )
                     || CASE WHEN MAX(u.GHI_CHU_CUOI) IS NOT NULL THEN NCHR(10) || u'Th\1eddi gian ti\1ebfp theo \0111\01b0\1ee3c \0111\00e1nh gi\00e1 c\1ea3i t\1ea1o: ' || MAX(u.GHI_CHU_CUOI) ELSE u'' END
                   AS XEP_LOAI_CHAP_HANH_AN
            FROM (
                SELECT t.PHAM_NHAN_ID, t.NAM, q.Q, t.GHI_CHU,
                       FIRST_VALUE(t.GHI_CHU) OVER (PARTITION BY t.PHAM_NHAN_ID ORDER BY t.NAM DESC) AS GHI_CHU_CUOI
                FROM TIEN_LAO_DONG_SAN_XUATS t
                CROSS JOIN (SELECT 1 AS Q FROM DUAL UNION ALL SELECT 2 FROM DUAL UNION ALL SELECT 3 FROM DUAL UNION ALL SELECT 4 FROM DUAL) q
                WHERE t.IS_DELETED = 0
            ) u
            GROUP BY u.PHAM_NHAN_ID
        ) xl ON xl.PHAM_NHAN_ID = v.PHAM_NHAN_ID
        WHERE v.IS_DELETED = 0
          AND (v_pham_nhan_id IS NULL OR v.PHAM_NHAN_ID = v_pham_nhan_id);

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i l?y thông tin ph?m nhân: ' || SQLERRM);
END SP_GET_PHAM_NHAN_BY_ID;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAM_NHAN_CHA_BY_PHAN_DOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAM_NHAN_CHA_BY_PHAN_DOI" (
    p_ten_phan_trai_id      IN NUMBER   DEFAULT NULL,
    p_ten_phan_doi_id       IN NUMBER   DEFAULT NULL,
    p_tinh_trang_id         IN NUMBER   DEFAULT NULL,
    p_loai_phan_loai_id     IN NUMBER   DEFAULT NULL,
    p_trai_tu_ngay          IN DATE     DEFAULT NULL,
    p_trai_den_ngay         IN DATE     DEFAULT NULL,
    p_phan_loai_tu_ngay     IN DATE     DEFAULT NULL,
    p_phan_loai_den_ngay    IN DATE     DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT
        ll.LL_HO_TEN AS "HoTen",
        SUBSTR(ll.LL_NGAY_SINH, -4) AS "NamSinh",
        dgt.GT_TEN AS "GioiTinh",
        ll.LL_DIA_CHI_THUONG_TRU AS "DiaChi",
        td_agg.TOI_DANH AS "ToiDanh",
        ll.LL_SO_TIEN_AN AS "SoTienAn",
        ptha.THA_NGAY_BAT AS "NgayBat",
        ptha.THA_AN_PHAT AS "AnPhat",
        '1' AS "DaGiam",
        FN_GET_DA_CHAP_HANH(ll.ID) AS "DaChapHanh",
        FN_GET_CON_LAI(ll.ID) AS "ConLai",
        ptha.THA_NGAY_DEN_TRAI AS "NgayDenTrai",
        ptha.THA_NGAY_HET_HAN AS "NgayHetHan",
        dplgg.PLGG_TEN AS "LoaiPhanLoai",
        pl_latest.NGAY_PHAN_LOAI AS "NgayPhanLoai",
        ptha.THA_GHI_CHU_DAC_BIET AS "GhiChu"
    FROM PN_LAI_LICHS ll
    LEFT JOIN DM_GIOI_TINHS dgt
        ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
    -- PN_THI_HANH_AN: lay ban ghi moi nhat (dung index IX_PN_THA_PN_NGAY)
    LEFT JOIN (
        SELECT ptha1.*
        FROM PN_THI_HANH_AN ptha1
        WHERE ptha1.THA_NGAY_BAN_AN = (
            SELECT MAX(ptha2.THA_NGAY_BAN_AN)
            FROM PN_THI_HANH_AN ptha2
            WHERE ptha2.THA_PNLAI_LICH_ID = ptha1.THA_PNLAI_LICH_ID
        )
        AND ROWNUM = 1
    ) ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
    LEFT JOIN DM_PHAN_DOIS dpd
        ON ll.LL_PHAN_DOI_ID = dpd.ID
    -- PHAN_LOAIS: lay ban ghi moi nhat (toi uu - dua predicate vao trong subquery)
    LEFT JOIN (
        SELECT pl1.PHAM_NHAN_ID, pl1.LOAI_PHAN_LOAI_ID, pl1.NGAY_PHAN_LOAI
        FROM PHAN_LOAIS pl1
        WHERE pl1.NGAY_PHAN_LOAI = (
            SELECT MAX(pl2.NGAY_PHAN_LOAI)
            FROM PHAN_LOAIS pl2
            WHERE pl2.PHAM_NHAN_ID = pl1.PHAM_NHAN_ID
        )
        AND ROWNUM = 1
    ) pl_latest ON ll.ID = pl_latest.PHAM_NHAN_ID
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg
        ON pl_latest.LOAI_PHAN_LOAI_ID = dplgg.ID
    -- TOI_DANH: tach string array
    LEFT JOIN (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            RTRIM(
                XMLAGG(
                    XMLELEMENT(e, dtd.TD_TEN || ', ')
                    ORDER BY dtd.TD_TEN
                ).extract('//text()').GETCLOBVAL(),
                ', '
            ) AS TOI_DANH
        FROM PN_THI_HANH_AN ptha
        LEFT JOIN (
            SELECT DISTINCT
                ptha2.THA_PNLAI_LICH_ID,
                TO_NUMBER(
                    REGEXP_SUBSTR(
                        REPLACE(REPLACE(ptha2.THA_TOI_DANH, '[', ''), ']', ''),
                        '[^,]+',
                        1,
                        LEVEL
                    )
                ) AS TOI_DANH_ID
            FROM PN_THI_HANH_AN ptha2
            WHERE ptha2.THA_TOI_DANH IS NOT NULL
            CONNECT BY LEVEL <= REGEXP_COUNT(
                REPLACE(REPLACE(ptha2.THA_TOI_DANH, '[', ''), ']', ''),
                ','
            ) + 1
            AND PRIOR ptha2.THA_PNLAI_LICH_ID = ptha2.THA_PNLAI_LICH_ID
            AND PRIOR SYS_GUID() IS NOT NULL
        ) td ON ptha.THA_PNLAI_LICH_ID = td.THA_PNLAI_LICH_ID
        LEFT JOIN DM_TOI_DANHS dtd ON td.TOI_DANH_ID = dtd.ID
        GROUP BY ptha.THA_PNLAI_LICH_ID
    ) td_agg ON ll.ID = td_agg.THA_PNLAI_LICH_ID
    WHERE (p_ten_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_ten_phan_doi_id)
      AND (p_ten_phan_trai_id IS NULL OR ll.LL_PHAN_TRAI_ID = p_ten_phan_trai_id)
      AND (p_tinh_trang_id IS NULL OR ll.LL_TINH_TRANG_ID = p_tinh_trang_id)
      AND (p_loai_phan_loai_id IS NULL OR pl_latest.LOAI_PHAN_LOAI_ID = p_loai_phan_loai_id)
      AND (p_trai_tu_ngay IS NULL OR TRUNC(ptha.THA_NGAY_DEN_TRAI) >= TRUNC(p_trai_tu_ngay))
      AND (p_trai_den_ngay IS NULL OR TRUNC(ptha.THA_NGAY_DEN_TRAI) <= TRUNC(p_trai_den_ngay))
      AND (p_phan_loai_tu_ngay IS NULL OR TRUNC(pl_latest.NGAY_PHAN_LOAI) >= TRUNC(p_phan_loai_tu_ngay))
      AND (p_phan_loai_den_ngay IS NULL OR TRUNC(pl_latest.NGAY_PHAN_LOAI) <= TRUNC(p_phan_loai_den_ngay));

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_PHAM_NHAN_CHA_BY_PHAN_DOI;







/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAM_NHAN_CHA_BY_PHAN_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAM_NHAN_CHA_BY_PHAN_TRAI" (
    p_phan_doi_id      IN NUMBER   DEFAULT NULL,
