            WHERE ptha2.THA_PNLAI_LICH_ID = ptha1.THA_PNLAI_LICH_ID
        )
        AND ROWNUM = 1
    ) ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
    LEFT JOIN DM_PHAN_TRAIS dpt
        ON ll.LL_PHAN_TRAI_ID = dpt.ID
    -- PHAN_LOAIS: lay ban ghi moi nhat (toi uu)
    LEFT JOIN (
        SELECT pl1.PHAM_NHAN_ID, pl1.LOAI_PHAN_LOAI_ID, pl1.NGAY_PHAN_LOAI
        FROM PHAN_LOAIS pl1
        WHERE pl1.NGAY_PHAN_LOAI = (
            SELECT MAX(pl2.NGAY_PHAN_LOAI)
            FROM PHAN_LOAIS pl2
            WHERE pl2.PHAM_NHAN_ID = pl1.PHAM_NHAN_ID
        )
        AND ROWNUM = 1
    ) pl_latest ON ll.ID = pl_latest.PHAM_NHAN_ID
    LEFT JOIN DM_MA_PHAN_LOAIES dplgg
        ON pl_latest.LOAI_PHAN_LOAI_ID = dplgg.ID
    -- TOI_DANH
    LEFT JOIN (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            RTRIM(
                XMLAGG(
                    XMLELEMENT(e, dtd.TD_TEN || ', ')
                    ORDER BY dtd.TD_TEN
                ).extract('//text()').GETCLOBVAL(),
                ', '
            ) AS TOI_DANH
        FROM PN_THI_HANH_AN ptha
        LEFT JOIN (
            SELECT DISTINCT
                ptha2.THA_PNLAI_LICH_ID,
                TO_NUMBER(
                    REGEXP_SUBSTR(
                        REPLACE(REPLACE(ptha2.THA_TOI_DANH, '[', ''), ']', ''),
                        '[^,]+',
                        1,
                        LEVEL
                    )
                ) AS TOI_DANH_ID
            FROM PN_THI_HANH_AN ptha2
            WHERE ptha2.THA_TOI_DANH IS NOT NULL
            CONNECT BY LEVEL <= REGEXP_COUNT(
                REPLACE(REPLACE(ptha2.THA_TOI_DANH, '[', ''), ']', ''),
                ','
            ) + 1
            AND PRIOR ptha2.THA_PNLAI_LICH_ID = ptha2.THA_PNLAI_LICH_ID
            AND PRIOR SYS_GUID() IS NOT NULL
        ) td ON ptha.THA_PNLAI_LICH_ID = td.THA_PNLAI_LICH_ID
        LEFT JOIN DM_TOI_DANHS dtd ON td.TOI_DANH_ID = dtd.ID
        GROUP BY ptha.THA_PNLAI_LICH_ID
    ) td_agg ON ll.ID = td_agg.THA_PNLAI_LICH_ID
    WHERE (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
      AND (p_tinh_trang_id IS NULL OR ll.LL_TINH_TRANG_ID = p_tinh_trang_id)
      AND (p_loai_phan_loai_id IS NULL OR pl_latest.LOAI_PHAN_LOAI_ID = p_loai_phan_loai_id)
      AND (p_trai_tu_ngay IS NULL OR TRUNC(ptha.THA_NGAY_DEN_TRAI) >= TRUNC(p_trai_tu_ngay))
      AND (p_trai_den_ngay IS NULL OR TRUNC(ptha.THA_NGAY_DEN_TRAI) <= TRUNC(p_trai_den_ngay))
      AND (p_phan_loai_tu_ngay IS NULL OR TRUNC(pl_latest.NGAY_PHAN_LOAI) >= TRUNC(p_phan_loai_tu_ngay))
      AND (p_phan_loai_den_ngay IS NULL OR TRUNC(pl_latest.NGAY_PHAN_LOAI) <= TRUNC(p_phan_loai_den_ngay));

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_PHAM_NHAN_CHA_BY_PHAN_TRAI;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAM_NHAN_CHA_BY_PHAN_TRAI_KQCT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAM_NHAN_CHA_BY_PHAN_TRAI_KQCT" (
    p_ten_phan_trai_id      IN NUMBER   DEFAULT NULL,
    p_tinh_trang_id         IN NUMBER   DEFAULT NULL,
    p_loai_phan_loai_id     IN NUMBER   DEFAULT NULL,
    p_trai_tu_ngay          IN DATE     DEFAULT NULL,
    p_trai_den_ngay         IN DATE     DEFAULT NULL,
    p_phan_loai_tu_ngay     IN DATE     DEFAULT NULL,
    p_phan_loai_den_ngay    IN DATE     DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT
        ll.LL_HO_TEN AS "HoTen",
        SUBSTR(ll.LL_NGAY_SINH, -4) AS "NamSinh",
        dgt.GT_TEN AS "GioiTinh",
        ll.LL_DIA_CHI_THUONG_TRU AS "DiaChi",
        td_agg.TOI_DANH AS "ToiDanh",
        ll.LL_SO_TIEN_AN AS "SoTienAn",
        ptha.THA_NGAY_BAT AS "NgayBat",
        ptha.THA_AN_PHAT AS "AnPhat",
        '1' AS "DaGiam",
        FN_GET_DA_CHAP_HANH(ll.ID) AS "DaChapHanh",
        FN_GET_CON_LAI(ll.ID) AS "ConLai",
        ptha.THA_NGAY_DEN_TRAI AS "NgayDenTrai",
        ptha.THA_NGAY_HET_HAN AS "NgayHetHan",
        dplgg.PLGG_TEN AS "LoaiPhanLoai",
        pl_latest.NGAY_PHAN_LOAI AS "NgayPhanLoai",
        ptha.THA_GHI_CHU_DAC_BIET AS "GhiChu",
        xl_agg.KET_QUA_CAI_TAO AS "KetQuaCaiTao"
    FROM PN_LAI_LICHS ll
    LEFT JOIN DM_GIOI_TINHS dgt
        ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
    -- PN_THI_HANH_AN: lay ban ghi moi nhat
    LEFT JOIN (
        SELECT ptha1.*
        FROM PN_THI_HANH_AN ptha1
        WHERE ptha1.THA_NGAY_BAN_AN = (
            SELECT MAX(ptha2.THA_NGAY_BAN_AN)
            FROM PN_THI_HANH_AN ptha2
            WHERE ptha2.THA_PNLAI_LICH_ID = ptha1.THA_PNLAI_LICH_ID
        )
        AND ROWNUM = 1
    ) ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
    LEFT JOIN DM_PHAN_TRAIS dpt
        ON ll.LL_PHAN_TRAI_ID = dpt.ID
    -- PHAN_LOAIS: lay ban ghi moi nhat (toi uu)
    LEFT JOIN (
        SELECT pl1.PHAM_NHAN_ID, pl1.LOAI_PHAN_LOAI_ID, pl1.NGAY_PHAN_LOAI
        FROM PHAN_LOAIS pl1
        WHERE pl1.NGAY_PHAN_LOAI = (
            SELECT MAX(pl2.NGAY_PHAN_LOAI)
            FROM PHAN_LOAIS pl2
            WHERE pl2.PHAM_NHAN_ID = pl1.PHAM_NHAN_ID
        )
        AND ROWNUM = 1
    ) pl_latest ON ll.ID = pl_latest.PHAM_NHAN_ID
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg
        ON pl_latest.LOAI_PHAN_LOAI_ID = dplgg.ID
    -- TOI_DANH
    LEFT JOIN (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            RTRIM(
                XMLAGG(
                    XMLELEMENT(e, dtd.TD_TEN || ', ')
                    ORDER BY dtd.TD_TEN
                ).extract('//text()').GETCLOBVAL(),
                ', '
            ) AS TOI_DANH
        FROM PN_THI_HANH_AN ptha
        LEFT JOIN (
            SELECT DISTINCT
                ptha2.THA_PNLAI_LICH_ID,
                TO_NUMBER(
                    REGEXP_SUBSTR(
                        REPLACE(REPLACE(ptha2.THA_TOI_DANH, '[', ''), ']', ''),
                        '[^,]+',
                        1,
                        LEVEL
                    )
                ) AS TOI_DANH_ID
            FROM PN_THI_HANH_AN ptha2
            WHERE ptha2.THA_TOI_DANH IS NOT NULL
            CONNECT BY LEVEL <= REGEXP_COUNT(
                REPLACE(REPLACE(ptha2.THA_TOI_DANH, '[', ''), ']', ''),
                ','
            ) + 1
            AND PRIOR ptha2.THA_PNLAI_LICH_ID = ptha2.THA_PNLAI_LICH_ID
            AND PRIOR SYS_GUID() IS NOT NULL
        ) td ON ptha.THA_PNLAI_LICH_ID = td.THA_PNLAI_LICH_ID
        LEFT JOIN DM_TOI_DANHS dtd ON td.TOI_DANH_ID = dtd.ID
        GROUP BY ptha.THA_PNLAI_LICH_ID
    ) td_agg ON ll.ID = td_agg.THA_PNLAI_LICH_ID
    -- KET QUA CAI TAO (dung XMLAGG de tranh ORA-01489)
    LEFT JOIN (
        SELECT
            xl.PHAM_NHAN_ID,
            RTRIM(
                XMLAGG(
                    XMLELEMENT(e,
                        xl.XEP_LOAI_NAM || ':' ||
                        'Q1: ' || NVL(xl_q1.XLCT_TEN, 'N/A') || ';' ||
                        'Q2: ' || NVL(xl_q2.XLCT_TEN, 'N/A') || ';' ||
                        '6D: ' || NVL(xl_6dau.XLCT_TEN, 'N/A') || ';' ||
                        'Q3: ' || NVL(xl_q3.XLCT_TEN, 'N/A') || ';' ||
                        'Q4: ' || NVL(xl_q4.XLCT_TEN, 'N/A') || ';' ||
                        '6C: ' || NVL(xl_6cuoi.XLCT_TEN, 'N/A') || ';' ||
                        'CN: ' || NVL(xl_canam.XLCT_TEN, 'N/A') || ' | '
                    )
                    ORDER BY xl.XEP_LOAI_NAM
                ).extract('//text()').GETCLOBVAL(),
                ' | '
            ) AS KET_QUA_CAI_TAO
        FROM XEP_LOAIS xl
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q1
            ON TO_NUMBER(xl.XEP_LOAI_QUY_I) = xl_q1.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q2
            ON TO_NUMBER(xl.XEP_LOAI_QUY_II) = xl_q2.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q3
            ON TO_NUMBER(xl.XEP_LOAI_QUY_III) = xl_q3.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q4
            ON TO_NUMBER(xl.XEP_LOAI_QUY_IV) = xl_q4.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_6dau
            ON TO_NUMBER(xl.XEP_LOAI_6_THANG_DAU_NAM) = xl_6dau.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_6cuoi
            ON TO_NUMBER(xl.XEP_LOAI_6_THANG_CUOI_NAM) = xl_6cuoi.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_canam
            ON TO_NUMBER(xl.XEP_LOAI_CA_NAM) = xl_canam.ID
        GROUP BY xl.PHAM_NHAN_ID
    ) xl_agg ON ll.ID = xl_agg.PHAM_NHAN_ID
    WHERE (p_ten_phan_trai_id IS NULL OR ll.LL_PHAN_TRAI_ID = p_ten_phan_trai_id)
      AND (p_tinh_trang_id IS NULL OR ll.LL_TINH_TRANG_ID = p_tinh_trang_id)
      AND (p_loai_phan_loai_id IS NULL OR pl_latest.LOAI_PHAN_LOAI_ID = p_loai_phan_loai_id)
      AND (p_trai_tu_ngay IS NULL OR TRUNC(ptha.THA_NGAY_DEN_TRAI) >= TRUNC(p_trai_tu_ngay))
      AND (p_trai_den_ngay IS NULL OR TRUNC(ptha.THA_NGAY_DEN_TRAI) <= TRUNC(p_trai_den_ngay))
      AND (p_phan_loai_tu_ngay IS NULL OR TRUNC(pl_latest.NGAY_PHAN_LOAI) >= TRUNC(p_phan_loai_tu_ngay))
      AND (p_phan_loai_den_ngay IS NULL OR TRUNC(pl_latest.NGAY_PHAN_LOAI) <= TRUNC(p_phan_loai_den_ngay));

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_PHAM_NHAN_CHA_BY_PHAN_TRAI_KQCT;







/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAM_NHAN_CHET_PT55
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAM_NHAN_CHET_PT55" (
    p_pham_nhan_id IN NUMBER
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        WITH vw_one AS (
            SELECT v.*
            FROM qlpn.vw_pn_lai_lich_chi_tiet v
            WHERE NVL(v.is_deleted, 0) = 0
              AND v.pham_nhan_id = p_pham_nhan_id
        ),
        than_nhan_one AS (
            SELECT *
            FROM (
                SELECT
                    tn.ho_ten_than_nhan,
                    tn.noi_o,
                    ROW_NUMBER() OVER (
                        ORDER BY
                            CASE WHEN NVL(tn.thong_bao, 0) = 1 THEN 0 ELSE 1 END,
                            CASE
                                WHEN qh.qhvpn_ten = 'V?' THEN 1
                                WHEN qh.qhvpn_ten = 'Ch?ng' THEN 2
                                WHEN qh.qhvpn_ten = 'M? ??' THEN 3
                                WHEN qh.qhvpn_ten = 'B? ??' THEN 4
                                ELSE 9
                            END,
                            tn.id
                    ) AS rn
                FROM qlpn.than_nhan_nguoi_thans tn
                LEFT JOIN qlpn.dm_quan_he_voi_pham_nhans qh
                       ON qh.id = tn.quan_he_id
                      AND NVL(qh.is_deleted, 0) = 0
                WHERE tn.pham_nhan_id = p_pham_nhan_id
                  AND NVL(tn.is_deleted, 0) = 0
            )
            WHERE rn = 1
        )
        SELECT

            TRIM(
                NVL(v.co_quan_qd_tha, '') ||
                CASE
                    WHEN v.co_quan_qd_tha IS NOT NULL AND v.toa_qd_tha_dia_phuong IS NOT NULL THEN ', '
                    ELSE ''
                END ||
                NVL(v.toa_qd_tha_dia_phuong, '')
            ) AS   TOA_QD_THA,
            v.noi_tha_ve_cu_tru_tinh as NOI_CHAP_HANH_AN,
            CASE
                WHEN v.noi_tha_ve_cu_tru_xa IS NOT NULL OR v.noi_tha_ve_cu_tru_tinh IS NOT NULL
                THEN 'UBND ' || NVL(v.noi_tha_ve_cu_tru_xa, '') ||
                     CASE
                         WHEN v.noi_tha_ve_cu_tru_xa IS NOT NULL AND v.noi_tha_ve_cu_tru_tinh IS NOT NULL THEN ', '
                         ELSE ''
                     END ||
                     NVL(v.noi_tha_ve_cu_tru_tinh, '')
                ELSE NULL
            END AS NOI_CU_TRU,
            tn.ho_ten_than_nhan AS NGUOI_THAN_THICH,
            v.ho_ten AS HO_TEN,
            v.gioi_tinh AS GIOI_TINH,
            v.ngay_sinh AS NGAY_SINH,
            v.ten_khac AS TEN_KHAC,
            v.nguyen_quan AS QUE_QUAN,
            v.noi_thuong_tru_day_du AS NOI_THUONG_TRU,
            NVL(v.cccd, v.ho_chieu) AS SO_CCCD_CC_HO_CHIEU,
            TO_CHAR(ngay_cap_cccd, 'DD/MM/YYYY')  AS NGAY_CAP,
            noi_cap_cccd AS NOI_CAP,
            v.toi_danh AS TOI_DANH,
            TO_CHAR(v.ngay_bat_an_phat, 'DD/MM/YYYY') AS NGAY_BAT,
            v.an_phat AS AN_PHAT,
            v.so_ban_an AS SO_BAN_AN,
            TO_CHAR(v.ngay_ban_an, 'DD/MM/YYYY') AS NGAY_BAN_AN,
            v.toa_xu_ten AS TOA_XU,
            v.toa_xu_dia_phuong AS DIA_PHUONG_XU,
            v.so_qd_tha AS SO_QD_THA,
            TO_CHAR(v.ngay_qd_tha, 'DD/MM/YYYY') AS NGAY_QD_THA,
            v.co_quan_qd_tha AS TOA_QD_THA,
            v.toa_qd_tha_dia_phuong AS DIA_PHUONG_QD_THA,
            v.trai_giam AS NOI_CHAP_HANH_AN_PHAT_TU_TAI,
            TO_CHAR(v.ngay_den_trai, 'DD/MM/YYYY') AS NGAY_DEN_CHAP_HANH_AN,
            ktc.ktc_noi_dieu_tri AS NOI_DIEU_TRI,
            TO_CHAR(CAST(ktc.ktc_ngay_chet AS DATE), 'HH24') AS GIO_CHET,
            TO_CHAR(CAST(ktc.ktc_ngay_chet AS DATE), 'MI') AS PHUT_CHET,
            TO_CHAR(CAST(ktc.ktc_ngay_chet AS DATE), 'DD/MM/YYYY') AS NGAY_CHET,
            ktc.ktc_noi_chet AS NOI_CHET
        FROM qlpn.pn_ket_thuc_chets ktc
        INNER JOIN vw_one v
                ON v.pham_nhan_id = ktc.ktc_pn_lai_lich_id
        LEFT JOIN than_nhan_one tn
               ON 1 = 1
        WHERE NVL(ktc.is_deleted, 0) = 0
          AND ktc.ktc_pn_lai_lich_id = p_pham_nhan_id
        ORDER BY ktc.ktc_ngay_chet, ktc.id
        FETCH FIRST 1 ROW ONLY;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_PHAM_NHAN_CHET_PT55: ' || SQLERRM);
END SP_GET_PHAM_NHAN_CHET_PT55;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAM_NHAN_CO_DIEU_KIEN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAM_NHAN_CO_DIEU_KIEN" (
    p_ten_pham_nhan IN VARCHAR2 DEFAULT NULL,
    p_ten_phan_doi IN NUMBER DEFAULT NULL,
    p_dia_phuong_ve IN NUMBER DEFAULT NULL,
    p_dot IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong IN NUMBER DEFAULT NULL,
    p_loai_in IN NUMBER DEFAULT NULL,
    p_skip_count IN NUMBER DEFAULT 0,
    p_max_value IN NUMBER DEFAULT 10,
    p_count OUT NUMBER
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    /* ========================= ??M T?NG S? B?N GHI ========================= */
    SELECT COUNT(*)
    INTO p_count
    FROM PN_LAI_LICHS ll
    LEFT JOIN DM_PHAN_DOIS dpd ON ll.LL_PHAN_DOI_ID = dpd.ID
    LEFT JOIN PN_DU_DIEU_KIEN_XET_THAS ddkxt 
        ON ll.ID = ddkxt.PN_LAI_LICH_ID 
        AND ddkxt.IS_DELETED = 0
    WHERE 1 = 1
      AND (p_ten_pham_nhan IS NULL OR UPPER(ll.LL_HO_TEN) = UPPER(p_ten_pham_nhan))
      AND (p_ten_phan_doi IS NULL OR dpd.ID = p_ten_phan_doi)
      AND (p_dia_phuong_ve IS NULL OR ll.LL_DIA_CHI_THUONG_TRU LIKE '%' || p_dia_phuong_ve || '%')
      AND (p_dot IS NULL OR ddkxt.PN_DOT_THA_CO_DIEU_KIEN_ID = p_dot);

    /* ========================= QUERY CHÍNH V?I PHÂN TRANG ========================= */
    OPEN c1 FOR
    WITH SPLIT_TOI_DANH AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            TO_NUMBER(
                REGEXP_SUBSTR(
                    REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
                    '[0-9]+',
                    1,
                    LEVEL
                )
            ) AS TOI_DANH_ID
        FROM PN_THI_HANH_AN ptha
        WHERE ptha.THA_TOI_DANH IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
                ','
            ) + 1
           AND PRIOR ptha.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
           AND PRIOR SYS_GUID() IS NOT NULL
    ),
    TOI_DANH_AGG AS (
        SELECT
            s.THA_PNLAI_LICH_ID,
            LISTAGG(DISTINCT dtd.TD_TEN, ', ')
                WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH
        FROM SPLIT_TOI_DANH s
        LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
        GROUP BY s.THA_PNLAI_LICH_ID
    ),
    LATEST_THA AS (
        SELECT
            THA_PNLAI_LICH_ID,
            THA_NGAY_BAT,
            THA_AN_PHAT,
            THA_NGAY_BAN_AN,
            THA_NGAY_HET_HAN,
            THA_GHI_CHU_DAC_BIET,
            ROW_NUMBER() OVER (
                PARTITION BY THA_PNLAI_LICH_ID 
                ORDER BY NVL(THA_NGAY_BAN_AN, TO_DATE('01-JAN-1900', 'DD-MON-YYYY')) DESC, ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN
    ),
    LATEST_PHAN_LOAI AS (
        SELECT
            pl1.PHAM_NHAN_ID,
            pl1.LOAI_PHAN_LOAI_ID,
            pl1.NGAY_PHAN_LOAI
        FROM PHAN_LOAIS pl1
        INNER JOIN (
            SELECT
                PHAM_NHAN_ID,
                MAX(NGAY_PHAN_LOAI) AS MAX_NGAY
            FROM PHAN_LOAIS
            GROUP BY PHAM_NHAN_ID
        ) pl2 ON pl1.PHAM_NHAN_ID = pl2.PHAM_NHAN_ID
             AND pl1.NGAY_PHAN_LOAI = pl2.MAX_NGAY
    ),
    LATEST_GTH AS (
        SELECT
            PHAM_NHAN_ID,
            MUC_GIAM_ID,
            ROW_NUMBER() OVER (
                PARTITION BY PHAM_NHAN_ID 
                ORDER BY ID DESC
            ) AS rn
        FROM GIAM_THOI_HANS
    ),
    BASE_QUERY AS (
        SELECT 
            ll.LL_HO_TEN AS HO_TEN,
            EXTRACT(YEAR FROM TO_DATE(LL.LL_NGAY_SINH, 'DD/MM/YYYY')) AS NGAY_SINH,
            dgt.GT_TEN,
            ll.LL_DIA_CHI_THUONG_TRU AS DIA_CHI_THUONG_TRU,
            ll.LL_SO_TIEN_AN AS SO_TIEN_AN,
            td_agg.TOI_DANH,
            ptha.THA_NGAY_BAT,
            ptha.THA_AN_PHAT,
            dmtg.MTG_TITLE,
            FN_GET_DA_CHAP_HANH(ll.ID) AS DA_CHAP_HANH,
            FN_GET_CON_LAI(ll.ID) AS CON_LAI,
            ptha.THA_NGAY_HET_HAN AS NGAY_HET_HAN,
            dpd.PD_TEN,
            dplgg.PLGG_TEN,
            pl_latest.NGAY_PHAN_LOAI,
            ptha.THA_GHI_CHU_DAC_BIET AS GHI_CHU_DAC_BIET
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN LATEST_THA ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID AND ptha.rn = 1
        LEFT JOIN DM_PHAN_DOIS dpd ON ll.LL_PHAN_DOI_ID = dpd.ID
        LEFT JOIN LATEST_PHAN_LOAI pl_latest ON ll.ID = pl_latest.PHAM_NHAN_ID
        LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg ON pl_latest.LOAI_PHAN_LOAI_ID = dplgg.ID
        LEFT JOIN TOI_DANH_AGG td_agg ON ll.ID = td_agg.THA_PNLAI_LICH_ID
        LEFT JOIN LATEST_GTH gth ON ll.ID = gth.PHAM_NHAN_ID AND gth.rn = 1
        LEFT JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
        LEFT JOIN PN_DU_DIEU_KIEN_XET_THAS ddkxt 
            ON ll.ID = ddkxt.PN_LAI_LICH_ID 
            AND ddkxt.IS_DELETED = 0
        WHERE 1=1
          AND (p_ten_pham_nhan IS NULL OR UPPER(ll.LL_HO_TEN) = UPPER(p_ten_pham_nhan))
          AND (p_ten_phan_doi IS NULL OR dpd.ID = p_ten_phan_doi)
          AND (p_dia_phuong_ve IS NULL OR ll.LL_DIA_CHI_THUONG_TRU LIKE '%' || p_dia_phuong_ve || '%')
          AND (p_dot IS NULL OR ddkxt.PN_DOT_THA_CO_DIEU_KIEN_ID = p_dot)
    )
    SELECT *
    FROM BASE_QUERY
    ORDER BY HO_TEN
    OFFSET NVL(p_skip_count, 0) ROWS
    FETCH NEXT NVL(p_max_value, 10) ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        p_count := 0;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: ' || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAM_NHAN_QDXL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAM_NHAN_QDXL" (
    p_pn_ids IN VARCHAR2 DEFAULT NULL,
    p_ky_xl  IN NUMBER   DEFAULT NULL
)
AS
    c1         SYS_REFCURSOR;
    v_nam_xl   NUMBER;
    v_ky_xl    VARCHAR2(50);
    v_ngay_hop DATE;
BEGIN
    BEGIN
        SELECT NAM_XEP_LOAI, KY_XEP_LOAI, NGAY_HOP_XEP_LOAI
          INTO v_nam_xl, v_ky_xl, v_ngay_hop
          FROM MO_KY_XEP_LOAI_CAI_TAOS
         WHERE ID = p_ky_xl;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_nam_xl   := NULL;
            v_ky_xl    := NULL;
            v_ngay_hop := NULL;
    END;

    OPEN c1 FOR
        WITH
        /* 1. Parse danh sách ID */
        NUM_GEN AS (
            SELECT LEVEL AS N FROM DUAL
            CONNECT BY LEVEL <= 100  -- t?ng n?u c?n nhi?u h?n 100 ID
        ),
        PN_ID_LIST AS (
            SELECT DISTINCT
                TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, ng.N))) AS pn_id,
                ng.N AS stt
            FROM NUM_GEN ng
            WHERE p_pn_ids IS NOT NULL
              AND LENGTH(TRIM(p_pn_ids)) > 0
              AND ng.N <= REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
              AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, ng.N) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, ng.N)), '^[0-9]+$')
        ),

        /* 2. B?n án m?i nh?t m?i ph?m nhân */
        LATEST_THA AS (
            SELECT
                THA_PNLAI_LICH_ID,
                THA_AN_PHAT,
                THA_NGAY_BAT,
                THA_NGAY_DEN_TRAI,
                THA_TOI_DANH,
                ROW_NUMBER() OVER (
                    PARTITION BY THA_PNLAI_LICH_ID
                    ORDER BY NVL(THA_NGAY_BAN_AN, DATE '1900-01-01') DESC, ID DESC
                ) AS rn
            FROM PN_THI_HANH_AN
            WHERE NVL(IS_DELETED, 0) = 0
              AND (p_pn_ids IS NULL OR THA_PNLAI_LICH_ID IN (SELECT pn_id FROM PN_ID_LIST))
        ),

        /* 3. Tách t?i danh — dùng NUM_GEN thay CONNECT BY trên b?ng th?c */
        SPLIT_TOI_DANH AS (
            SELECT
                ltha.THA_PNLAI_LICH_ID,
                TO_NUMBER(TRIM(REGEXP_SUBSTR(
                    REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''),
                    '[^,]+', 1, ng.N
                ))) AS TOI_DANH_ID
            FROM LATEST_THA ltha                      -- ch? dùng b?n án m?i nh?t
            JOIN NUM_GEN ng
                ON ng.N <= REGEXP_COUNT(
                       REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
            WHERE ltha.rn = 1
              AND ltha.THA_TOI_DANH IS NOT NULL
              AND REGEXP_SUBSTR(
                      REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''),
                      '[^,]+', 1, ng.N) IS NOT NULL
        ),

        /* 4. LISTAGG t?i danh — dedup tr??c ?? tránh l?i Oracle < 19c */
        SPLIT_TOI_DANH_DEDUP AS (
            SELECT DISTINCT THA_PNLAI_LICH_ID, TOI_DANH_ID
            FROM SPLIT_TOI_DANH
        ),
        TOI_DANH_AGG AS (
            SELECT
                s.THA_PNLAI_LICH_ID,
                LISTAGG(dtd.TD_TEN, '; ')
                    WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH
            FROM SPLIT_TOI_DANH_DEDUP s
            LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
            GROUP BY s.THA_PNLAI_LICH_ID
        )

        SELECT
            pll.ID,
            pll.LL_HO_TEN                                   AS "HoTen",
            dgt.GT_TEN                                       AS "GioiTinh",
            SUBSTR(pll.LL_NGAY_SINH, -4)                     AS "NamSinh",
            pll.LL_TEN_KHAC                                  AS "TenKhac",
            pll.LL_NGUYEN_QUAN                               AS "NguyenQuan",
			-- THAY TH? toàn b? ph?n CASE DiaChiThuongTru trong SELECT:
			CASE
			    WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
			      OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'')     IS NOT NULL
			      OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'')    IS NOT NULL
			    THEN TRIM(
			            NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
			            || CASE WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
			                    CASE WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
			                         THEN u', ' || dxp_thuong_tru.XP_TEN
			                         ELSE dxp_thuong_tru.XP_TEN END
			               ELSE u'' END
			            || CASE WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
			                    CASE WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
			                           OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
			                         THEN u', ' || dttp_thuong_tru.TTP_TEN
			                         ELSE dttp_thuong_tru.TTP_TEN END
			               ELSE u'' END
			        )
			    ELSE NULL
			END AS "DiaChiThuongTru",
            tda.TOI_DANH                                     AS "ToiDanh",
            TO_CHAR(ptha.THA_NGAY_BAT, 'DD/MM/YYYY')        AS "NgayBat",
            ptha.THA_AN_PHAT                                 AS "AnPhat",
            TO_CHAR(ptha.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY')   AS "NgayDenTrai",
            dpd.PD_TEN || ', ' || pt.PT_TEN                  AS "PhanDoi",
            xl.XEP_LOAI_NAM                                  AS "NamXepLoai",
            CASE WHEN v_ky_xl = 'MA_XEP_LOAI_Q1' THEN xl_q1.XLCT_TEN END AS "Quy1",
            CASE WHEN v_ky_xl = 'MA_XEP_LOAI_Q2' THEN xl_q2.XLCT_TEN END AS "Quy2",
            CASE WHEN v_ky_xl = 'MA_XEP_LOAI_Q3' THEN xl_q3.XLCT_TEN END AS "Quy3",
            CASE WHEN v_ky_xl = 'MA_XEP_LOAI_Q4' THEN xl_q4.XLCT_TEN END AS "Quy4",
            xl_6cuoi.XLCT_TEN                                AS "6thangcuoi",  -- FIX: tr? th?c thay NULL
            xl_6dau.XLCT_TEN                                 AS "6thangdau",
            xl_canam.XLCT_TEN                                AS "CaNam",
            TO_CHAR(v_ngay_hop, 'DD/MM/YYYY')               AS "NgayHopXL"

        FROM PN_LAI_LICHS pll
        LEFT JOIN PN_ID_LIST pil          ON pll.ID = pil.pn_id
        LEFT JOIN DM_GIOI_TINHS dgt       ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
            ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
           AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
        LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
            ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
           AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
        LEFT JOIN LATEST_THA ptha
            ON ptha.THA_PNLAI_LICH_ID = pll.ID AND ptha.rn = 1
        LEFT JOIN DM_PHAN_DOIS dpd        ON pll.LL_PHAN_DOI_ID = dpd.ID
        LEFT JOIN DM_PHAN_TRAIS pt        ON dpd.PD_DM_PHAN_TRAI_ID = pt.ID
        LEFT JOIN XEP_LOAIS xl
            ON pll.ID = xl.PHAM_NHAN_ID
           AND xl.XEP_LOAI_NAM = v_nam_xl
           AND NVL(xl.IS_DELETED, 0) = 0
        LEFT JOIN TOI_DANH_AGG tda        ON tda.THA_PNLAI_LICH_ID = pll.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q1    ON xl.XEP_LOAI_QUY_I             = xl_q1.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q2    ON xl.XEP_LOAI_QUY_II            = xl_q2.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q3    ON xl.XEP_LOAI_QUY_III           = xl_q3.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q4    ON xl.XEP_LOAI_QUY_IV            = xl_q4.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_6cuoi ON xl.XEP_LOAI_6_THANG_CUOI_NAM  = xl_6cuoi.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_6dau  ON xl.XEP_LOAI_6_THANG_DAU_NAM   = xl_6dau.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_canam ON xl.XEP_LOAI_CA_NAM             = xl_canam.ID

        WHERE (p_pn_ids IS NULL OR pll.ID IN (SELECT pn_id FROM PN_ID_LIST))

        ORDER BY pil.stt NULLS LAST;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_PHAM_NHAN_QDXL;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAM_NHAN_QDXL_CA_NHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAM_NHAN_QDXL_CA_NHAN" (
--    p_pn_ids IN VARCHAR2 DEFAULT NULL,
    p_ky_xl  IN NUMBER   DEFAULT NULL
)
AS
    c1         SYS_REFCURSOR;
    v_nam_xl   NUMBER;
    v_ky_xl    VARCHAR2(50);
    v_ngay_hop DATE;
BEGIN
    BEGIN
        SELECT NAM_XEP_LOAI, KY_XEP_LOAI, NGAY_HOP_XEP_LOAI
          INTO v_nam_xl, v_ky_xl, v_ngay_hop
          FROM MO_KY_XEP_LOAI_CAI_TAOS
         WHERE ID = p_ky_xl;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_nam_xl   := NULL;
            v_ky_xl    := NULL;
            v_ngay_hop := NULL;
    END;

    OPEN c1 FOR
        WITH
        /* 1. Parse danh sách ID */
        NUM_GEN AS (
            SELECT LEVEL AS N FROM DUAL
            CONNECT BY LEVEL <= 100  -- t?ng n?u c?n nhi?u h?n 100 ID
        ),
        PN_ID_LIST AS (
        SELECT PN_ID 
    	FROM QLPN.GTT_PN_IDS
        ),

        /* 2. B?n án m?i nh?t m?i ph?m nhân */
        LATEST_THA AS (
            SELECT
                THA_PNLAI_LICH_ID,
                THA_AN_PHAT,
                THA_NGAY_BAT,
                THA_NGAY_DEN_TRAI,
                THA_TOI_DANH,
                ROW_NUMBER() OVER (
                    PARTITION BY THA_PNLAI_LICH_ID
                    ORDER BY NVL(THA_NGAY_BAN_AN, DATE '1900-01-01') DESC, ID DESC
                ) AS rn
            FROM PN_THI_HANH_AN
            WHERE NVL(IS_DELETED, 0) = 0
              AND ( THA_PNLAI_LICH_ID IN (SELECT pn_id FROM PN_ID_LIST))
        ),

        /* 3. Tách t?i danh — dùng NUM_GEN thay CONNECT BY trên b?ng th?c */
        SPLIT_TOI_DANH AS (
            SELECT
                ltha.THA_PNLAI_LICH_ID,
                TO_NUMBER(TRIM(REGEXP_SUBSTR(
                    REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''),
                    '[^,]+', 1, ng.N
                ))) AS TOI_DANH_ID
            FROM LATEST_THA ltha                      -- ch? dùng b?n án m?i nh?t
            JOIN NUM_GEN ng
                ON ng.N <= REGEXP_COUNT(
                       REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
            WHERE ltha.rn = 1
              AND ltha.THA_TOI_DANH IS NOT NULL
              AND REGEXP_SUBSTR(
                      REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''),
                      '[^,]+', 1, ng.N) IS NOT NULL
        ),

        /* 4. LISTAGG t?i danh — dedup tr??c ?? tránh l?i Oracle < 19c */
        SPLIT_TOI_DANH_DEDUP AS (
            SELECT DISTINCT THA_PNLAI_LICH_ID, TOI_DANH_ID
            FROM SPLIT_TOI_DANH
        ),
        TOI_DANH_AGG AS (
            SELECT
                s.THA_PNLAI_LICH_ID,
                LISTAGG(dtd.TD_TEN, '; ')
                    WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH
            FROM SPLIT_TOI_DANH_DEDUP s
            LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
            GROUP BY s.THA_PNLAI_LICH_ID
        )

        SELECT
            pll.ID,
            pll.LL_HO_TEN                                   AS "HoTen",
            dgt.GT_TEN                                       AS "GioiTinh",
            SUBSTR(pll.LL_NGAY_SINH, -4)                     AS "NamSinh",
            pll.LL_TEN_KHAC                                  AS "TenKhac",
            pll.LL_NGUYEN_QUAN                               AS "NguyenQuan",
			-- THAY TH? toàn b? ph?n CASE DiaChiThuongTru trong SELECT:
			CASE
			    WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
			      OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'')     IS NOT NULL
			      OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'')    IS NOT NULL
			    THEN TRIM(
			            NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
			            || CASE WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
			                    CASE WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
			                         THEN u', ' || dxp_thuong_tru.XP_TEN
			                         ELSE dxp_thuong_tru.XP_TEN END
			               ELSE u'' END
			            || CASE WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
			                    CASE WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
			                           OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
			                         THEN u', ' || dttp_thuong_tru.TTP_TEN
			                         ELSE dttp_thuong_tru.TTP_TEN END
			               ELSE u'' END
			        )
			    ELSE NULL
			END AS "DiaChiThuongTru",
            tda.TOI_DANH                                     AS "ToiDanh",
            TO_CHAR(ptha.THA_NGAY_BAT, 'DD/MM/YYYY')        AS "NgayBat",
            ptha.THA_AN_PHAT                                 AS "AnPhat",
            TO_CHAR(ptha.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY')   AS "NgayDenTrai",
            dpd.PD_TEN               AS "PhanDoi",
            pt.PT_TEN AS "PhanTrai",
            dtg.TG_TEN AS "TraiGiam",
            xl.XEP_LOAI_NAM                                  AS "NamXepLoai",
            CASE WHEN v_ky_xl = 'MA_XEP_LOAI_Q1' THEN xl_q1.XLCT_TEN END AS "Quy1",
            CASE WHEN v_ky_xl = 'MA_XEP_LOAI_Q2' THEN xl_q2.XLCT_TEN END AS "Quy2",
            CASE WHEN v_ky_xl = 'MA_XEP_LOAI_Q3' THEN xl_q3.XLCT_TEN END AS "Quy3",
            CASE WHEN v_ky_xl = 'MA_XEP_LOAI_Q4' THEN xl_q4.XLCT_TEN END AS "Quy4",
            TO_CHAR(v_ngay_hop, 'DD/MM/YYYY')               AS "NgayHopXL"

        FROM PN_LAI_LICHS pll
        LEFT JOIN PN_ID_LIST pil          ON pll.ID = pil.pn_id
        LEFT JOIN DM_GIOI_TINHS dgt       ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
            ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
           AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
        LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
            ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
           AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
        LEFT JOIN LATEST_THA ptha
            ON ptha.THA_PNLAI_LICH_ID = pll.ID AND ptha.rn = 1
        LEFT JOIN DM_PHAN_DOIS dpd        ON pll.LL_PHAN_DOI_ID = dpd.ID
        LEFT JOIN DM_PHAN_TRAIS pt        ON dpd.PD_DM_PHAN_TRAI_ID = pt.ID
        LEFT JOIN DM_TRAI_GIAMS dtg ON pll.LL_TRAI_GIAM_ID = dtg.ID 
        LEFT JOIN XEP_LOAIS xl
            ON pll.ID = xl.PHAM_NHAN_ID
           AND xl.XEP_LOAI_NAM = v_nam_xl
           AND NVL(xl.IS_DELETED, 0) = 0
        LEFT JOIN TOI_DANH_AGG tda        ON tda.THA_PNLAI_LICH_ID = pll.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q1    ON xl.XEP_LOAI_QUY_I             = xl_q1.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q2    ON xl.XEP_LOAI_QUY_II            = xl_q2.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q3    ON xl.XEP_LOAI_QUY_III           = xl_q3.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q4    ON xl.XEP_LOAI_QUY_IV            = xl_q4.ID

        WHERE ( pll.ID IN (SELECT pn_id FROM PN_ID_LIST));

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_PHAM_NHAN_QDXL_CA_NHAN;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAM_NHAN_RA_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAM_NHAN_RA_TRAI" 
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        WITH pn_filter AS (
            SELECT PN_ID AS pn_id
            FROM QLPN.GTT_PN_IDS
        ),
        KT_one AS (
            SELECT k.*
            FROM (
                SELECT k0.*, ROW_NUMBER() OVER (PARTITION BY k0.KTRT_PN_LAI_LICH_ID ORDER BY NVL(k0.KTRT_NGAY_THA, k0.CREATION_TIME) DESC NULLS LAST) AS rn
                FROM PN_KET_THUC_RA_TRAIS k0
                WHERE NVL(k0.IS_DELETED, 0) = 0
                  AND (NOT EXISTS (SELECT 1 FROM QLPN.GTT_PN_IDS)
                       OR k0.KTRT_PN_LAI_LICH_ID IN (SELECT pn_id FROM pn_filter))
            ) k
            WHERE k.rn = 1
        ),
        -- Ghi chú riêng Lai l?ch: parse LL_GHI_CHU_RIENG (chu?i id) ? map DM_GHI_CHU_RIENGS.GCR_TEN
        gcr_raw AS (
            SELECT v.PHAM_NHAN_ID,
                   REGEXP_REPLACE(NVL(TRIM(CAST(v.GHI_CHU_RIENG AS VARCHAR2(4000))), ''), '[[:space:]\[\]]', '') AS gcr_clean
            FROM VW_PN_LAI_LICH_CHI_TIET v
            WHERE (NOT EXISTS (SELECT 1 FROM QLPN.GTT_PN_IDS) OR v.PHAM_NHAN_ID IN (SELECT pn_id FROM pn_filter))
              AND NVL(v.IS_DELETED, 0) = 0
              AND v.GHI_CHU_RIENG IS NOT NULL
              AND REGEXP_COUNT(REGEXP_REPLACE(NVL(TRIM(CAST(v.GHI_CHU_RIENG AS VARCHAR2(4000))), ''), '[[:space:]\[\]]', ''), '[0-9]+') > 0
        ),
        gcr_ids AS (
            SELECT r.PHAM_NHAN_ID,
                   TO_NUMBER(REGEXP_SUBSTR(r.gcr_clean, '[0-9]+', 1, LEVEL)) AS gcr_id,
                   LEVEL AS ord
            FROM gcr_raw r
            CONNECT BY LEVEL <= REGEXP_COUNT(r.gcr_clean, '[0-9]+')
              AND PRIOR r.PHAM_NHAN_ID = r.PHAM_NHAN_ID
              AND PRIOR SYS_GUID() IS NOT NULL
        ),
        gcr_agg AS (
            SELECT ids.PHAM_NHAN_ID,
                   SUBSTR(LISTAGG(CAST(g.GCR_TEN AS VARCHAR2(500)), ', ') WITHIN GROUP (ORDER BY ids.ord), 1, 2000) AS ghi_chu_rieng_ten
            FROM gcr_ids ids
            JOIN DM_GHI_CHU_RIENGS g ON g.ID = ids.gcr_id AND NVL(g.IS_DELETED, 0) = 0
            GROUP BY ids.PHAM_NHAN_ID
        )
        SELECT
            v.PHAM_NHAN_ID,
            v.HO_TEN,
            v.NAM_SINH,
            v.NGAY_SINH,
            v.GIOI_TINH,
            CASE
                WHEN v.HO_TEN IS NOT NULL AND v.NAM_SINH IS NOT NULL AND v.GIOI_TINH IS NOT NULL
                THEN v.HO_TEN || u' - ' || TO_CHAR(v.NAM_SINH) || u' - ' || v.GIOI_TINH
                WHEN v.HO_TEN IS NOT NULL AND v.NAM_SINH IS NOT NULL
                THEN v.HO_TEN || u' - ' || TO_CHAR(v.NAM_SINH)
                WHEN v.HO_TEN IS NOT NULL AND v.GIOI_TINH IS NOT NULL
                THEN v.HO_TEN || u' - ' || v.GIOI_TINH
                ELSE v.HO_TEN
            END AS HO_TEN_NAM_SINH_GIOI_TINH,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_THUONG_TRU,
            v.TOI_DANH,
            v.SO_TIEN_AN AS TA,
            v.AN_PHAT AS AN_PHAT,
            TO_CHAR(v.NGAY_BAT_AN_PHAT,'DD/MM/YYYY') AS NGAY_BAT_AN_PHAT,
            v.THOI_GIAN_TAM_GIAM,
            PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(v.PHAM_NHAN_ID, NULL) AS THOI_GIAN_DA_CHAP_HANH,
            PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(v.PHAM_NHAN_ID) AS DA_GIAM,
            TO_CHAR(v.NGAY_DEN_TRAI,'DD/MM/YYYY') AS NGAY_DEN_TRAI,
            TO_CHAR(v.NGAY_HET_AN,'DD/MM/YYYY') AS NGAY_HET_AN,
            TO_CHAR(t.KTRT_NGAY_TRINH_DIEN,'DD/MM/YYYY') AS NGAY_TRINH_DIEN,
            NVL(TRIM(CAST(v.PHAN_DOI AS NVARCHAR2(500))), u'') ||
                CASE WHEN v.PHAN_DOI IS NOT NULL AND v.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
                NVL(TRIM(CAST(v.PHAN_TRAI AS NVARCHAR2(500))), u'') AS PHAN_DOI,
            v.PHAN_TRAI,
            -- GHI_CHU = ghi chú riêng Lai l?ch (LL_GHI_CHU_RIENG ? DM_GHI_CHU_RIENGS.GCR_TEN)
            NVL(CAST(ga.ghi_chu_rieng_ten AS NVARCHAR2(2000)), u'') AS GHI_CHU,
            v.TRAI_GIAM,
            v.TRAI_GIAM_ID,
            -- Các tr??ng b? sung
            dtht.THT_TEN AS TH_RA_TRAI,
            v.DAN_TOC,
            v.QUOC_TICH,
            v.TON_GIAO,
            v.HOC_VAN,
            v.NGHE_NGHIEP,
            v.TINH_TRANG_SUC_KHOE,
            v.SO_HO_SO,
            v.CCCD,
            v.NGUYEN_QUAN,
            v.NOI_THA_VE_CU_TRU,
            FN_GET_LIET_KE_HPBST_TNDST(v.PHAM_NHAN_ID)     AS HPBS_TIEN,
            FN_GET_LIET_KE_HPBS_KHAC(v.PHAM_NHAN_ID)          AS HPBS_KHAC,
            --- Các tr??ng ti?n (không CAST chu?i ?ã format sang NUMBER — ?? tránh ORA-01722 theo NLS)
            TO_CHAR(NVL(200000, 0), 'FM999G999G999') || ' ??ng' AS TIEN_AN_DUONG,
            TO_CHAR(NVL(200000, 0), 'FM999G999G999') || ' ??ng' AS TIEN_TAU_XE,
            -- X?p lo?i c?i t?o (ch? g?i 1 l?n, không l?p l?i KET_QUA_CAI_TAO)
            FN_TONG_HOP_KET_QUA_CAI_TAO(v.PHAM_NHAN_ID) AS XEP_LOAI_CAI_TAO,
            t.KTRT_MUC_CAN_CU_THONG_TU_ID,
            t.KTRT_THOI_GIAN_CAI_TAO_KEM,
            t.KTRT_NHAN_XET_CAI_TAO_KEM,
            t.KTRT_KET_QUA_CAI_TAO_KEM,
            FN_GET_TONG_CON_LAI_TIEN_LAO_DONG(v.PHAM_NHAN_ID) AS TIEN_TAI_HNCD
        FROM VW_PN_LAI_LICH_CHI_TIET v
        LEFT JOIN KT_one t ON v.PHAM_NHAN_ID = t.KTRT_PN_LAI_LICH_ID
        LEFT JOIN DM_TRUONG_HOP_THAS dtht ON t.KTRT_TRUONG_HOP_THA_ID = dtht.ID
        LEFT JOIN gcr_agg ga ON ga.PHAM_NHAN_ID = v.PHAM_NHAN_ID
        WHERE (NOT EXISTS (SELECT 1 FROM QLPN.GTT_PN_IDS) OR v.PHAM_NHAN_ID IN (SELECT pn_id FROM pn_filter));

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi khi lay du lieu pham nhan ra trai: ' || SQLERRM);

        -- Lenh test (SQLcl / SQL Developer):
        --   Insert vao GTT_PN_IDS truoc de loc theo danh sach ID cu the, hoac de trong = tat ca:
        -- BEGIN QLPN.SP_GET_PHAM_NHAN_RA_TRAI(); END;
        -- EXEC QLPN.SP_GET_PHAM_NHAN_RA_TRAI;

END SP_GET_PHAM_NHAN_RA_TRAI;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAM_NHAN_RA_TRAI_KET_QUA_TIEN_THNCD
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAM_NHAN_RA_TRAI_KET_QUA_TIEN_THNCD" (
    p_pham_nhan_id IN NUMBER
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        SELECT
            x.XEP_LOAI_NAM AS nam,
            d1.XLCT_TEN AS xep_loai_quy_1,
            CASE WHEN x.TIEN_LDSX_QUYI IS NULL THEN NULL
                 ELSE TO_CHAR(CAST(x.TIEN_LDSX_QUYI AS NUMBER), 'FM999G999G999') || ' ??ng'
            END AS tien_quy_1,
            d2.XLCT_TEN AS xep_loai_quy_2,
            CASE WHEN x.TIEN_LDSX_QUYII IS NULL THEN NULL
                 ELSE TO_CHAR(CAST(x.TIEN_LDSX_QUYII AS NUMBER), 'FM999G999G999') || ' ??ng'
            END AS tien_quy_2,
            d3.XLCT_TEN AS xep_loai_quy_3,
            CASE WHEN x.TIEN_LDSX_QUYIII IS NULL THEN NULL
                 ELSE TO_CHAR(CAST(x.TIEN_LDSX_QUYIII AS NUMBER), 'FM999G999G999') || ' ??ng'
            END AS tien_quy_3,
            d4.XLCT_TEN AS xep_loai_quy_4,
            CASE WHEN x.TIEN_LDSX_QUYIV IS NULL THEN NULL
                 ELSE TO_CHAR(CAST(x.TIEN_LDSX_QUYIV AS NUMBER), 'FM999G999G999') || ' ??ng'
            END AS tien_quy_4,
            TO_CHAR(
                NVL(CAST(x.TIEN_LDSX_QUYI AS NUMBER), 0)
                + NVL(CAST(x.TIEN_LDSX_QUYII AS NUMBER), 0)
                + NVL(CAST(x.TIEN_LDSX_QUYIII AS NUMBER), 0)
                + NVL(CAST(x.TIEN_LDSX_QUYIV AS NUMBER), 0),
                'FM999G999G999'
            ) || ' ??ng' AS tong_tien_nam
        FROM QLPN.XEP_LOAIS x
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS d1
            ON d1.ID = x.XEP_LOAI_QUY_I
           AND NVL(d1.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS d2
            ON d2.ID = x.XEP_LOAI_QUY_II
           AND NVL(d2.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS d3
            ON d3.ID = x.XEP_LOAI_QUY_III
           AND NVL(d3.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS d4
            ON d4.ID = x.XEP_LOAI_QUY_IV
           AND NVL(d4.IS_DELETED, 0) = 0
        WHERE x.PHAM_NHAN_ID = p_pham_nhan_id
          AND NVL(x.IS_DELETED, 0) = 0
        ORDER BY x.XEP_LOAI_NAM;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20002, 'L?i SP_GET_PHAM_NHAN_RA_TRAI_KET_QUA_TIEN_THNCD: ' || SQLERRM);
END SP_GET_PHAM_NHAN_RA_TRAI_KET_QUA_TIEN_THNCD;

