        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân ra tr?i có ti?n: ' || SQLERRM);
END SP_GET_PHAM_NHAN_RA_TRAI_TIEN_LDSX_CO_KQCT;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAM_NHAN_RA_TRAI_VE_DIA_PHUONG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAM_NHAN_RA_TRAI_VE_DIA_PHUONG" (
    p_ten_trai_giam IN NVARCHAR2 DEFAULT '',
    p_tu_ngay IN NVARCHAR2 DEFAULT '',
    p_den_ngay IN NVARCHAR2 DEFAULT '',
    p_tinh_thanh IN NVARCHAR2 DEFAULT '',
    p_phuong_xa IN NVARCHAR2 DEFAULT ''
) AS
    v_ten_trai_giam NVARCHAR2(2000);
    v_tu_ngay DATE;
    v_den_ngay DATE;
    v_tinh_thanh NVARCHAR2(2000);
    v_phuong_xa NVARCHAR2(2000);
    c1 SYS_REFCURSOR;
BEGIN

--    begin
--        SP_GET_PHAM_NHAN_RA_TRAI_VE_DIA_PHUONG('', '', '');
--    end;

    -- X? lý default value cho tên tr?i giam
    IF p_ten_trai_giam IS NULL OR p_ten_trai_giam = '' THEN
        v_ten_trai_giam := NULL;
    ELSE
        v_ten_trai_giam := p_ten_trai_giam;
    END IF;

    -- X? lý default value cho t? ngày
    IF p_tu_ngay IS NULL OR p_tu_ngay = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(p_tu_ngay, 'DD/MM/YYYY');
    END IF;

    -- X? lý default value cho ??n ngày
    IF p_den_ngay IS NULL OR p_den_ngay = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(p_den_ngay, 'DD/MM/YYYY');
    END IF;

    -- X? lý default value cho t?nh/thành
    IF p_tinh_thanh IS NULL OR p_tinh_thanh = '' THEN
        v_tinh_thanh := NULL;
    ELSE
        v_tinh_thanh := p_tinh_thanh;
    END IF;

    -- X? lý default value cho ph??ng/xã
    IF p_phuong_xa IS NULL OR p_phuong_xa = '' THEN
        v_phuong_xa := NULL;
    ELSE
        v_phuong_xa := p_phuong_xa;
    END IF;

    -- Debug output
    DBMS_OUTPUT.PUT_LINE('Danh sách ph?m nhân ra tr?i v? ??a ph??ng');
    DBMS_OUTPUT.PUT_LINE('Tên tr?i giam: ' || NVL(v_ten_trai_giam, 'T?t c?'));
    DBMS_OUTPUT.PUT_LINE('T? ngày: ' || NVL(TO_CHAR(v_tu_ngay, 'DD/MM/YYYY'), 'Không gi?i h?n'));
    DBMS_OUTPUT.PUT_LINE('??n ngày: ' || NVL(TO_CHAR(v_den_ngay, 'DD/MM/YYYY'), 'Không gi?i h?n'));
    DBMS_OUTPUT.PUT_LINE('T?nh/Thành: ' || NVL(v_tinh_thanh, 'T?t c?'));
    DBMS_OUTPUT.PUT_LINE('Ph??ng/Xã: ' || NVL(v_phuong_xa, 'T?t c?'));

    -- M? cursor v?i k?t qu? có STT và COUNT
    OPEN c1 FOR
        SELECT 
            ROW_NUMBER() OVER (ORDER BY v.NGAY_HET_AN NULLS LAST, v.HO_TEN) AS STT,
            COUNT(*) OVER() AS TONG_SO_BAN_GHI,
            v.PHAM_NHAN_ID,
            v.HO_TEN,
            v.NAM_SINH,
            v.NGAY_SINH,
            v.GIOI_TINH,
            CASE 
                WHEN v.HO_TEN IS NOT NULL AND v.NAM_SINH IS NOT NULL AND v.GIOI_TINH IS NOT NULL
                THEN v.HO_TEN || u' - ' || TO_CHAR(v.NAM_SINH) || u' - ' || v.GIOI_TINH
                WHEN v.HO_TEN IS NOT NULL AND v.NAM_SINH IS NOT NULL
                THEN v.HO_TEN || u' - ' || TO_CHAR(v.NAM_SINH)
                WHEN v.HO_TEN IS NOT NULL AND v.GIOI_TINH IS NOT NULL
                THEN v.HO_TEN || u' - ' || v.GIOI_TINH
                ELSE v.HO_TEN
            END AS HO_TEN_NAM_SINH_GIOI_TINH,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_THUONG_TRU,
            v.DIA_CHI_THUONG_TRU AS DIA_CHI_CHI_TIET,
            v.TINH_THANH_THUONG_TRU AS TINH_THANH,
            v.PHUONG_XA_THUONG_TRU AS PHUONG_XA,
            v.TOI_DANH,
            v.AN_PHAT AS TA,
            v.NGAY_BAT_AN_PHAT,
            v.THOI_GIAN_TAM_GIAM,
            v.DA_GIAM,
            v.NGAY_DEN_TRAI,
            v.PHAN_DOI,
            v.NGAY_HET_AN,
            v.GHI_CHU,
            v.TRAI_GIAM,
            v.TRAI_GIAM_ID,
            -- Các tr??ng b? sung
            v.DAN_TOC,
            v.QUOC_TICH,
            v.TON_GIAO,
            v.HOC_VAN,
            v.NGHE_NGHIEP,
            v.TINH_TRANG_SUC_KHOE,
            v.SO_HO_SO,
            v.CCCD,
            -- Thông tin v? n?i tr? v?
            v.NOI_THUONG_TRU_DAY_DU AS NOI_TRA_VE_DIA_PHUONG,
            v.ho_ten_order
        FROM VW_PN_LAI_LICH_CHI_TIET v
        INNER JOIN PN_KET_THUC_RA_TRAIS t
        ON v.PHAM_NHAN_ID = t.KTRT_PN_LAI_LICH_ID
        WHERE 1=1
            -- Filter theo tên tr?i giam
            AND (v_ten_trai_giam IS NULL 
                 OR UPPER(v.TRAI_GIAM) = UPPER(v_ten_trai_giam))

            -- Filter theo ngày h?t án (th?i gian ra tr?i)
            AND (v_tu_ngay IS NULL OR v.NGAY_HET_AN >= v_tu_ngay)
            AND (v_den_ngay IS NULL OR v.NGAY_HET_AN <= v_den_ngay)

            -- Filter theo t?nh/thành (n?i th??ng trú)
            AND (v_tinh_thanh IS NULL 
                 OR UPPER(v.TINH_THANH_THUONG_TRU) LIKE UPPER('%' || v_tinh_thanh || '%')
                 OR UPPER(v.NOI_THUONG_TRU_DAY_DU) LIKE UPPER('%' || v_tinh_thanh || '%'))

            -- Filter theo ph??ng/xã (n?i th??ng trú)
            AND (v_phuong_xa IS NULL 
                 OR UPPER(v.PHUONG_XA_THUONG_TRU) LIKE UPPER('%' || v_phuong_xa || '%')
                 OR UPPER(v.NOI_THUONG_TRU_DAY_DU) LIKE UPPER('%' || v_phuong_xa || '%'))
        ORDER BY  v.NGAY_HET_AN NULLS LAST, v.ho_ten_order;

    -- Tr? v? k?t qu?
    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách ph?m nhân ra tr?i v? ??a ph??ng: ' || SQLERRM);
END SP_GET_PHAM_NHAN_RA_TRAI_VE_DIA_PHUONG;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAM_TOI_MOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAM_TOI_MOI" (
    p_PHAM_NHAN_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        ptm.PHAM_NHAN_ID,
        ptm.NGAY_PHAM_TOI  AS "NgayPhamToi",
        dtd.TD_TEN   AS "ToiDanh",
        ptm.HINH_THUC_XU_LY  AS "HinhThucXuLy"
    FROM PHAM_TOI_MOIS ptm 
    LEFT JOIN DM_TOI_DANHS dtd ON ptm.TOI_DANH_ID = dtd.ID
    WHERE ptm.PHAM_NHAN_ID = p_PHAM_NHAN_ID;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_PHAM_TOI_MOI;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAN_DOI_PT44A
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAN_DOI_PT44A" (
    P_PN_PHAN_DOI_ID IN VARCHAR2 DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    IF P_PN_PHAN_DOI_ID IS NULL THEN
        RAISE_APPLICATION_ERROR(-20001, 'P_PN_PHAN_DOI_ID KHONG DUOC DE TRONG');
    END IF;

    OPEN C1 FOR
    WITH
        PHAN_DOI_DIEU_CHUYEN AS (
            SELECT P.*
            FROM QLPN.PHAM_NHAN_PHAN_DOI P
            WHERE P.ID = P_PN_PHAN_DOI_ID
              AND NVL(P.IS_DELETED, 0) = 0
        )
        SELECT
            V.HO_TEN AS HO_TEN,
            V.GIOI_TINH AS GIOI_TINH,
            V.NGAY_SINH AS NGAY_SINH,
            V.TEN_KHAC AS HO_TEN_KHAC,
            V.NGUYEN_QUAN AS QUE_QUAN,
            V.DAN_TOC AS DAN_TOC,
            V.QUOC_TICH AS QUOC_TICH,
            NVL(V.NOI_THUONG_TRU_DAY_DU, V.DIA_CHI_THUONG_TRU) AS NOI_THUONG_TRU,
            V.TOI_DANH AS TOI_DANH,
            TO_CHAR(V.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT,
            V.AN_PHAT AS AN_PHAT,
            V.SO_BAN_AN AS SO_BAN_AN,
            TO_CHAR(V.NGAY_BAN_AN, 'DD/MM/YYYY') AS NGAY_BAN_AN,
            V.TOA_XU_TEN AS TOA_AN_XU,
            V.TOA_XU_DIA_PHUONG AS DIA_PHUONG_XU,
            V.SO_QD_THA AS SO_QD_THA,
            TO_CHAR(V.NGAY_QD_THA, 'DD/MM/YYYY') AS NGAY_QD_THA,
            V.CO_QUAN_QD_THA AS CO_QUAN_QD_THA,
            V.TOA_QD_THA_DIA_PHUONG AS DIA_PHUONG_QD_THA,
            TO_CHAR(V.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
            V.NHAN_THAN AS NHAN_THAN,
            PD_TU.PD_TEN AS PHAN_DOI_TU,
            PT_TU.PT_TEN AS PHAN_TRAI_TU,
            V.PHAN_DOI AS PHAN_DOI_DEN,
            V.PHAN_TRAI AS PHAN_TRAI_DEN,
            TO_CHAR(PNPD.PNPD_NGAY_CHUYEN, 'DD/MM/YYYY') AS NGAY_HIEU_LUC
--            V.PHAN_TRAI AS PHAN_TRAI_BAN_GIAO,
--            PNPD.PNPD_GHI_CHU AS GHI_CHU_DIEU_CHUYEN
        FROM PHAN_DOI_DIEU_CHUYEN PNPD
        INNER JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET V
                ON V.PHAM_NHAN_ID = PNPD.PNPD_LAI_LICH_ID
               AND NVL(V.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_DOIS PD_TU
               ON PD_TU.ID = PNPD.PNPD_PHAN_DOI_ID
              AND NVL(PD_TU.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_TRAIS PT_TU
               ON PT_TU.ID = PNPD.PNPD_PHAN_TRAI_ID
              AND NVL(PT_TU.IS_DELETED, 0) = 0;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_PHAN_DOI_PT44A;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAN_LOAI_GIAM_GIU
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAN_LOAI_GIAM_GIU" (
    p_PHAM_NHAN_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        pl.PHAM_NHAN_ID,
        pl.NGAY_PHAN_LOAI  AS "NgayPhanLoai",
        dmpl.MPL_TEN   AS "GhiChu",
        dplgg.PLGG_TEN   AS "TuLoai",
        dplgg2.PLGG_TEN  AS "DenLoai"
    FROM PHAN_LOAIS pl
   	LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg ON pl.TU_LOAI_ID = dplgg.ID 
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg2 ON pl.DEN_LOAI_ID = dplgg2.ID
    LEFT JOIN DM_MA_PHAN_LOAIES dmpl ON pl.LOAI_PHAN_LOAI_ID = dmpl.ID
    WHERE pl.PHAM_NHAN_ID = p_PHAM_NHAN_ID;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_PHAN_LOAI_GIAM_GIU;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAN_LOAI_PT11
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAN_LOAI_PT11" AS 
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH 

    NUM_GEN AS (
            SELECT LEVEL AS N FROM DUAL
            CONNECT BY LEVEL <= 100  -- t?ng n?u c?n nhi?u h?n 100 ID
        ),
     PN_ID_LIST AS (
        SELECT PN_ID 
    	FROM QLPN.GTT_PN_IDS
      ),
    SPLIT_TOI_DANH AS (
        SELECT /*+ NO_MERGE */ 
               ptha.THA_PNLAI_LICH_ID,
               dtd.ID  AS TOI_DANH_ID,
               dtd.TD_TEN
          FROM PN_THI_HANH_AN ptha
          JOIN DM_TOI_DANHS dtd
            ON INSTR(',' || REPLACE(REPLACE(ptha.THA_TOI_DANH,'[',''),']','') || ',',
                     ',' || dtd.ID || ',') > 0
         WHERE ptha.THA_TOI_DANH IS NOT NULL
           AND NVL(dtd.IS_DELETED, 0) = 0
    ),
    TOI_DANH_AGG AS (
        SELECT /*+ NO_MERGE */
               THA_PNLAI_LICH_ID,
               RTRIM(
                   XMLAGG(XMLELEMENT(e, TD_TEN || '; ') ORDER BY TD_TEN)
                       .extract('//text()').GETCLOBVAL(),
                   '; '
               ) AS TOI_DANH
          FROM SPLIT_TOI_DANH
         GROUP BY THA_PNLAI_LICH_ID
    ),
    LATEST_THA AS (
        SELECT
            THA_PNLAI_LICH_ID,
            THA_NGAY_BAT,
            THA_AN_PHAT,
            THA_SO_BAN_AN,
            TO_CHAR(THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS THA_NGAY_BAN_AN,
            THA_TOA_QD_ID,
            d2.TTP_TEN AS DIA_PHUONG_TOA,
            THA_SO_QD_THA,
            TO_CHAR(THA_NGAY_QD_THA, 'DD/MM/YYYY') AS THA_NGAY_QD_THA,
            THA_CAP_TOA_ID,
            d.TTP_TEN AS DIA_PHUONG_THA,
            ROW_NUMBER() OVER (
                PARTITION BY THA_PNLAI_LICH_ID
                ORDER BY NVL(THA_NGAY_BAN_AN, TO_DATE('01-JAN-1900', 'DD-MON-YYYY')) DESC, PN_THI_HANH_AN.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN
        LEFT JOIN DM_TINH_THANH_PHO d  ON PN_THI_HANH_AN.THA_DIA_PHUONG_TOA_QD_THA_ID = d.ID
        LEFT JOIN DM_TINH_THANH_PHO d2 ON PN_THI_HANH_AN.THA_DIA_PHUONG_CAP_TOA_ID    = d2.ID
    )
    SELECT
        dmml.MPL_TEN            AS LoaiPhanLoai,
        dplgg.PLGG_TEN            AS TuLoai,
        dplgg2.PLGG_TEN            AS DenLoai,
        pll.LL_HO_TEN          AS HoTen,
        pll.LL_TEN_KHAC        AS TenKhac,
        dgt.GT_TEN             AS GioiTinh,
        pll.LL_NGAY_SINH       AS NgaySinh,

        CASE
            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || dxp_thuong_tru.XP_TEN
                            ELSE dxp_thuong_tru.XP_TEN
                        END
                    ELSE u''
                   END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || dttp_thuong_tru.TTP_TEN
                            ELSE dttp_thuong_tru.TTP_TEN
                        END
                    ELSE u''
                   END
            )
            ELSE NULL
        END AS DiaChiThuongTru,

        ddt.DT_TEN              AS DanToc,
        dtg2.TG_TEN              AS TonGiao,
        dqt.QT_TEN               AS QuocTich,

        TO_CHAR(TRUNC(ptha.THA_NGAY_BAT), 'DD/MM/YYYY') AS NgayBat,
        ptha.THA_AN_PHAT          AS AnPhat,
        td_agg.TOI_DANH  AS ToiDanh,
--        ptha.THA_SO_BAN_AN        AS BanAnSo,
--        ptha.THA_NGAY_BAN_AN      AS NgayBanAn,
--        dcq.CQ_TEN                AS ToaQuyetDinh,
--        ptha.DIA_PHUONG_TOA       AS DiaPhuongToa,
--
--        ptha.THA_SO_QD_THA        AS SoQuyetDinhTHA,
--        ptha.THA_NGAY_QD_THA      AS NgayQuyetDinhTHA,
--        dcq5.CQ_TEN                AS CoQuanQuyetDinh,
--        ptha.DIA_PHUONG_THA       AS DiaPhuongQuyetDinh,
		pll.LL_NHAN_THAN AS NhanThan,
        dpd.PD_TEN                AS PhanDoi,
        dpt.PT_TEN                 AS PhanTrai,
        dtg.TG_TEN                 AS TraiGiam

    FROM PN_LAI_LICHS pll
    LEFT JOIN TOI_DANH_AGG td_agg    ON pll.ID                           = td_agg.THA_PNLAI_LICH_ID
    LEFT JOIN PN_ID_LIST pil          ON pll.ID = pil.pn_id
    LEFT JOIN LATEST_THA ptha
           ON pll.ID = ptha.THA_PNLAI_LICH_ID
          AND ptha.rn = 1
    left join PHAN_LOAIS pl ON pll.ID = pl.PHAM_NHAN_ID
    left join DM_MA_PHAN_LOAIES dmml ON pl.LOAI_PHAN_LOAI_ID = dmml.ID
    left join DM_PHAN_LOAI_GIAM_GIUS dplgg ON pl.TU_LOAI_ID = dplgg.ID
    left join DM_PHAN_LOAI_GIAM_GIUS dplgg2 ON pl.DEN_LOAI_ID = dplgg2.ID
    LEFT JOIN DM_GIOI_TINHS dgt   ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_DAN_TOCS  ddt    ON pll.LL_DM_DAN_TOC_ID   = ddt.ID
    LEFT JOIN DM_TON_GIAOS dtg2   ON pll.LL_DM_TON_GIAO_ID  = dtg2.ID
    LEFT JOIN DM_QUOC_TICHS dqt   ON pll.LL_DM_QUOC_TICH_ID = dqt.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
          AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
          AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS dcq     ON ptha.THA_TOA_QD_ID  = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq5    ON ptha.THA_CAP_TOA_ID = dcq5.ID
    LEFT JOIN DM_PHAN_DOIS dpd    ON pll.LL_PHAN_DOI_ID  = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt   ON pll.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg   ON pll.LL_TRAI_GIAM_ID = dtg.ID
    WHERE (pll.ID IN (SELECT pn_id FROM PN_ID_LIST));
    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        NULL;
    WHEN TOO_MANY_ROWS THEN
        RAISE_APPLICATION_ERROR(-20001,'Loi roi');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: ' || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END;

/
