        ddt.DT_TEN              AS DanToc,
        dtg2.TG_TEN              AS TonGiao,
        dqt.QT_TEN               AS QuocTich,
        rt.LL_NHAN_THAN          AS NhanThan,

        TO_CHAR(TRUNC(rt.THA_NGAY_BAT), 'DD/MM/YYYY') AS NgayBat,
        rt.THA_AN_PHAT          AS AnPhat,

        rt.THA_SO_BAN_AN        AS BanAnSo,
        TO_CHAR(rt.THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS NgayBanAn,
        dcq.CQ_TEN                AS ToaQuyetDinh,
        dttp_cap_toa.TTP_TEN      AS DiaPhuongToa,
        rt.THA_TOI_DANH_NAMES  AS ToiDanh,
        rt.THA_SO_QD_THA        AS SoQuyetDinhTHA,
        TO_CHAR(rt.THA_NGAY_QD_THA, 'DD/MM/YYYY') AS NgayQuyetDinhTHA,
        dcq5.CQ_TEN                AS CoQuanQuyetDinh,
        dttp_toa_qd_tha.TTP_TEN   AS DiaPhuongQuyetDinh,

        dpd.PD_TEN                AS PhanDoi,
        dpt.PT_TEN                 AS PhanTrai,
        dtg.TG_TEN                 AS TraiGiam

    FROM PN_LAI_LICH_CHI_TIET_RT rt
    left join PHAN_LOAIS pl ON rt.PHAM_NHAN_ID = pl.PHAM_NHAN_ID
    left join DM_MA_PHAN_LOAIES dmml ON pl.LOAI_PHAN_LOAI_ID = dmml.ID
    left join DM_PHAN_LOAI_GIAM_GIUS dplgg ON pl.TU_LOAI_ID = dplgg.ID
    left join DM_PHAN_LOAI_GIAM_GIUS dplgg2 ON pl.DEN_LOAI_ID = dplgg2.ID
    LEFT JOIN DM_GIOI_TINHS dgt   ON rt.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_DAN_TOCS  ddt    ON rt.LL_DM_DAN_TOC_ID   = ddt.ID
    LEFT JOIN DM_TON_GIAOS dtg2   ON rt.LL_DM_TON_GIAO_ID  = dtg2.ID
    LEFT JOIN DM_QUOC_TICHS dqt   ON rt.LL_DM_QUOC_TICH_ID = dqt.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
           ON rt.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
          AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
           ON rt.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
          AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS dcq     ON rt.THA_TOA_QD_ID  = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq5    ON rt.THA_CAP_TOA_ID = dcq5.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_cap_toa
           ON rt.THA_DIA_PHUONG_CAP_TOA_ID = dttp_cap_toa.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_toa_qd_tha
           ON rt.THA_DIA_PHUONG_TOA_QD_THA_ID = dttp_toa_qd_tha.ID
    LEFT JOIN DM_PHAN_DOIS dpd    ON rt.LL_PHAN_DOI_ID  = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt   ON rt.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg   ON rt.LL_TRAI_GIAM_ID = dtg.ID
    WHERE (NOT EXISTS (SELECT 1 FROM QLPN.GTT_PN_IDS)
           OR rt.PHAM_NHAN_ID IN (SELECT pn_id FROM pn_filter));

    DBMS_SQL.RETURN_RESULT(c1);

END;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PHAN_LOAI_PT20
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PHAN_LOAI_PT20" AS
    c1 SYS_REFCURSOR;
BEGIN
    -- Danh sách PN c?n l?y do caller n?p s?n vào GTT_PN_IDS (ON COMMIT DELETE ROWS) trong cùng
    -- transaction — xem XepLoaiCaiTaosAppService.InsertIdsToGttAsync.
    OPEN c1 FOR
    WITH  ID_LIST AS (
        SELECT DISTINCT PN_ID
    	FROM QLPN.GTT_PN_IDS
        ),
    LATEST_THA AS (
        SELECT
            THA_PNLAI_LICH_ID,
            THA_NGAY_BAT,
            THA_AN_PHAT,
            THA_TOI_DANH,
            THA_SO_BAN_AN,
            THA_NGAY_DEN_TRAI,
            TO_CHAR(THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS THA_NGAY_BAN_AN,
            THA_TOA_QD_ID,
            d2.TTP_TEN AS DIA_PHUONG_TOA,
            THA_SO_QD_THA,
            TO_CHAR(THA_NGAY_QD_THA, 'DD/MM/YYYY') AS THA_NGAY_QD_THA,
            THA_CAP_TOA_ID,
            d.TTP_TEN AS DIA_PHUONG_THA,
            ROW_NUMBER() OVER (
                PARTITION BY THA_PNLAI_LICH_ID
                ORDER BY NVL(THA_NGAY_BAN_AN, DATE '1900-01-01') DESC, PN_THI_HANH_AN.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN
        LEFT JOIN DM_TINH_THANH_PHO d  ON PN_THI_HANH_AN.THA_DIA_PHUONG_TOA_QD_THA_ID = d.ID
        LEFT JOIN DM_TINH_THANH_PHO d2 ON PN_THI_HANH_AN.THA_DIA_PHUONG_CAP_TOA_ID    = d2.ID
        WHERE THA_PNLAI_LICH_ID IN (SELECT PN_ID FROM ID_LIST)
    ),
    -- Quy?t ??nh phân lo?i m?i nh?t (ch?a xóa) c?a m?i PN — tránh nhân dòng khi PN có nhi?u
    -- l?n phân lo?i và tránh l?y nh?m b?n ghi ?ã xóa m?m.
    LATEST_PL AS (
        SELECT
            PHAM_NHAN_ID,
            LOAI_PHAN_LOAI_ID,
            TU_LOAI_ID,
            DEN_LOAI_ID,
            ROW_NUMBER() OVER (
                PARTITION BY PHAM_NHAN_ID
                ORDER BY NGAY_PHAN_LOAI DESC NULLS LAST, CREATION_TIME DESC, ID DESC
            ) AS rn
        FROM PHAN_LOAIS
        WHERE NVL(IS_DELETED, 0) = 0
          AND PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST)
    )
    SELECT
        pll.ID                 AS PhamNhanId,
        dmml.MPL_TEN            AS LoaiPhanLoai,
        dplgg.PLGG_TEN            AS TuLoai,
        dplgg2.PLGG_TEN            AS DenLoai,
        pll.LL_HO_TEN          AS HoTen,
        pll.LL_TEN_KHAC        AS TenKhac,
        dgt.GT_TEN             AS GioiTinh,
        pll.LL_NGAY_SINH       AS NgaySinh,

        CASE
            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || dxp_thuong_tru.XP_TEN
                            ELSE dxp_thuong_tru.XP_TEN
                        END
                    ELSE u''
                   END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || dttp_thuong_tru.TTP_TEN
                            ELSE dttp_thuong_tru.TTP_TEN
                        END
                    ELSE u''
                   END
            )
            ELSE NULL
        END AS DiaChiThuongTru,
        TO_CHAR(TRUNC(ptha.THA_NGAY_BAT), 'DD/MM/YYYY') AS NgayBat,
        TO_CHAR(TRUNC(ptha.THA_NGAY_DEN_TRAI), 'DD/MM/YYYY') AS NgayDenTrai,
        ptha.THA_AN_PHAT          AS AnPhat,
        ptha.THA_TOI_DANH         AS ToiDanh,

        dpd.PD_TEN                AS PhanDoi,
        dpt.PT_TEN                 AS PhanTrai,
        dtg.TG_TEN                 AS TraiGiam

    FROM PN_LAI_LICHS pll
    -- INNER JOIN ?? L?C theo danh sách PN truy?n vào. Tr??c ?ây là LEFT JOIN (không có WHERE)
    -- nên SP tr? v? TOÀN B? PN_LAI_LICHS, caller ch? ??c dòng ??u -> báo cáo PT20 in nh?m PN khác.
    JOIN ID_LIST il ON il.PN_ID = pll.ID
    LEFT JOIN LATEST_THA ptha
           ON pll.ID = ptha.THA_PNLAI_LICH_ID
          AND ptha.rn = 1
    LEFT JOIN LATEST_PL pl
           ON pll.ID = pl.PHAM_NHAN_ID
          AND pl.rn = 1
    left join DM_MA_PHAN_LOAIES dmml ON pl.LOAI_PHAN_LOAI_ID = dmml.ID
    left join DM_PHAN_LOAI_GIAM_GIUS dplgg ON pl.TU_LOAI_ID = dplgg.ID
    left join DM_PHAN_LOAI_GIAM_GIUS dplgg2 ON pl.DEN_LOAI_ID = dplgg2.ID
    LEFT JOIN DM_GIOI_TINHS dgt   ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
          AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
          AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_PHAN_DOIS dpd    ON pll.LL_PHAN_DOI_ID  = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt   ON pll.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg   ON pll.LL_TRAI_GIAM_ID = dtg.ID
    ORDER BY pll.ID;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: ' || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PN_CHAP_HANH_XONG_AN_PHAT_TU
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PN_CHAP_HANH_XONG_AN_PHAT_TU" (
    p_ma_trai_giam IN VARCHAR2 DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
        WITH
        -- has_ids tính m?t l?n. Nhánh GTT ?i nested loop theo PHAM_NHAN_ID.
        -- Nhánh còn l?i ch? ch?y khi GTT r?ng (l?c theo mã tr?i). Không g?p b?ng OR NOT EXISTS:
        -- d?ng ?ó bu?c Oracle full-scan VW_PN_LAI_LICH_CHI_TIET r?i m?i l?c.
        gtt_flag AS (
            SELECT /*+ MATERIALIZE */
                   NVL(MAX(1), 0) AS has_ids
            FROM QLPN.GTT_PN_IDS
            WHERE ROWNUM = 1
        ),
        vw_raw AS (
            SELECT /*+ MATERIALIZE */
                x.PHAM_NHAN_ID,
                x.HO_TEN,
                x.CCCD,
                x.NGAY_CAP_CCCD,
                x.NOI_CAP_CCCD,
                x.GIOI_TINH,
                x.NAM_SINH,
                x.NGAY_SINH,
                x.TEN_KHAC,
                x.NGUYEN_QUAN,
                x.DAN_TOC,
                x.QUOC_TICH,
                x.PHAN_DOI,
                x.PHAN_TRAI,
                x.SO_HO_SO,
                x.NOI_THUONG_TRU_DAY_DU,
                x.DIA_CHI_THUONG_TRU,
                x.NOI_THA_VE_CU_TRU,
                x.NOI_THA_VE_CU_TRU_XA,
                x.NOI_THA_VE_CU_TRU_TINH,
                x.NOI_O_KHAC,
                x.TRAI_GIAM,
                x.TRAI_GIAM_ID,
                x.TOI_DANH,
                x.KHOAN,
                x.DIEU,
                x.CAN_CU_TUYEN_PHAT,
                x.SO_QD_THA,
                x.NGAY_QD_THA,
                x.NGAY_BAT_AN_PHAT,
                x.AN_PHAT,
                x.SO_BAN_AN,
                x.NGAY_BAN_AN,
                x.TOA_QD_THA_DIA_PHUONG,
                x.CO_QUAN_QD_THA,
                x.SO_DANH_BAN,
                x.THOI_GIAN_TAM_GIAM,
                x.THOI_GIAN_TAM_GIU,
                x.NGAY_HET_AN,
                x.NGAY_LAP_DANH_BAN,
                x.TOA_XU_TEN,
                x.TOA_XU_DIA_PHUONG,
                x.TINH_THANH_THUONG_TRU,
                x.PHUONG_XA_THUONG_TRU,
                x.HO_TEN_ORDER,
                x.LL_SO_GCN
            FROM (
                SELECT /*+ LEADING(g) USE_NL(v) */
                    v.PHAM_NHAN_ID,
                    v.HO_TEN,
                    v.CCCD,
                    v.NGAY_CAP_CCCD,
                    v.NOI_CAP_CCCD,
                    v.GIOI_TINH,
                    v.NAM_SINH,
                    v.NGAY_SINH,
                    v.TEN_KHAC,
                    v.NGUYEN_QUAN,
                    v.DAN_TOC,
                    v.QUOC_TICH,
                    v.PHAN_DOI,
                    v.PHAN_TRAI,
                    v.SO_HO_SO,
                    v.NOI_THUONG_TRU_DAY_DU,
                    v.DIA_CHI_THUONG_TRU,
                    v.NOI_THA_VE_CU_TRU,
                    v.NOI_THA_VE_CU_TRU_XA,
                    v.NOI_THA_VE_CU_TRU_TINH,
                    v.NOI_O_KHAC,
                    v.TRAI_GIAM,
                    v.TRAI_GIAM_ID,
                    v.TOI_DANH,
                    v.KHOAN,
                    v.DIEU,
                    v.CAN_CU_TUYEN_PHAT,
                    v.SO_QD_THA,
                    v.NGAY_QD_THA,
                    v.NGAY_BAT_AN_PHAT,
                    v.AN_PHAT,
                    v.SO_BAN_AN,
                    v.NGAY_BAN_AN,
                    v.TOA_QD_THA_DIA_PHUONG,
                    v.CO_QUAN_QD_THA,
                    v.SO_DANH_BAN,
                    v.THOI_GIAN_TAM_GIAM,
                    v.THOI_GIAN_TAM_GIU,
                    v.NGAY_HET_AN,
                    v.NGAY_LAP_DANH_BAN,
                    v.TOA_XU_TEN,
                    v.TOA_XU_DIA_PHUONG,
                    v.TINH_THANH_THUONG_TRU,
                    v.PHUONG_XA_THUONG_TRU,
                    v.HO_TEN_ORDER,
                    v.LL_SO_GCN
                FROM (
                    SELECT DISTINCT g0.PN_ID
                    FROM QLPN.GTT_PN_IDS g0
                ) g
                JOIN VW_PN_LAI_LICH_CHI_TIET v
                    ON v.PHAM_NHAN_ID = g.PN_ID
                WHERE NVL(v.IS_DELETED, 0) = 0
                  AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_MA = p_ma_trai_giam)
                UNION ALL
                SELECT
                    v.PHAM_NHAN_ID,
                    v.HO_TEN,
                    v.CCCD,
                    v.NGAY_CAP_CCCD,
                    v.NOI_CAP_CCCD,
                    v.GIOI_TINH,
                    v.NAM_SINH,
                    v.NGAY_SINH,
                    v.TEN_KHAC,
                    v.NGUYEN_QUAN,
                    v.DAN_TOC,
                    v.QUOC_TICH,
                    v.PHAN_DOI,
                    v.PHAN_TRAI,
                    v.SO_HO_SO,
                    v.NOI_THUONG_TRU_DAY_DU,
                    v.DIA_CHI_THUONG_TRU,
                    v.NOI_THA_VE_CU_TRU,
                    v.NOI_THA_VE_CU_TRU_XA,
                    v.NOI_THA_VE_CU_TRU_TINH,
                    v.NOI_O_KHAC,
                    v.TRAI_GIAM,
                    v.TRAI_GIAM_ID,
                    v.TOI_DANH,
                    v.KHOAN,
                    v.DIEU,
                    v.CAN_CU_TUYEN_PHAT,
                    v.SO_QD_THA,
                    v.NGAY_QD_THA,
                    v.NGAY_BAT_AN_PHAT,
                    v.AN_PHAT,
                    v.SO_BAN_AN,
                    v.NGAY_BAN_AN,
                    v.TOA_QD_THA_DIA_PHUONG,
                    v.CO_QUAN_QD_THA,
                    v.SO_DANH_BAN,
                    v.THOI_GIAN_TAM_GIAM,
                    v.THOI_GIAN_TAM_GIU,
                    v.NGAY_HET_AN,
                    v.NGAY_LAP_DANH_BAN,
                    v.TOA_XU_TEN,
                    v.TOA_XU_DIA_PHUONG,
                    v.TINH_THANH_THUONG_TRU,
                    v.PHUONG_XA_THUONG_TRU,
                    v.HO_TEN_ORDER,
                    v.LL_SO_GCN
                FROM VW_PN_LAI_LICH_CHI_TIET v
                WHERE (SELECT f.has_ids FROM gtt_flag f) = 0
                  AND NVL(v.IS_DELETED, 0) = 0
                  AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_MA = p_ma_trai_giam)
            ) x
        ),
        pn_ids AS (
            SELECT /*+ MATERIALIZE */
                DISTINCT r.PHAM_NHAN_ID AS pn_id
            FROM vw_raw r
        ),
        vw_core AS (
            SELECT
                v.*,
                cq_lap.CQ_TEN AS THA_CO_QUAN_LAP,
                v.TOA_QD_THA_DIA_PHUONG AS THA_DIA_PHUONG_TOA_QD_THA,
                dttp_lap.TTP_TEN AS THA_DIA_PHUONG_CO_QUAN_LAP,
                v.CO_QUAN_QD_THA AS THA_TOA_QD_THA
            FROM vw_raw v
            LEFT JOIN PN_LAI_LICH_CHI_TIET_RT rt
                ON rt.PHAM_NHAN_ID = v.PHAM_NHAN_ID
               AND NVL(rt.IS_DELETED, 0) = 0
               AND NVL(rt.LL_IS_DELETED, 0) = 0
               AND NVL(rt.THA_IS_DELETED, 0) = 0
            LEFT JOIN DM_CO_QUANS cq_lap
                ON cq_lap.ID = rt.THA_CO_QUAN_LAP_ID
               AND NVL(cq_lap.IS_DELETED, 0) = 0
            LEFT JOIN DM_TINH_THANH_PHO dttp_lap
                ON dttp_lap.ID = rt.THA_DIA_PHUONG_DON_CO_QUAN_LAP_ID
               AND NVL(dttp_lap.IS_DELETED, 0) = 0
        ),
        kt_one AS (
            SELECT
                k.KTRT_PN_LAI_LICH_ID,
                k.KTRT_NGAY_THA,
                k.KTRT_NGAY_TRINH_DIEN,
                k.KTRT_SO_GCN
            FROM (
                SELECT
                    k0.KTRT_PN_LAI_LICH_ID,
                    k0.KTRT_NGAY_THA,
                    k0.KTRT_NGAY_TRINH_DIEN,
                    k0.KTRT_SO_GCN,
                    ROW_NUMBER() OVER (
                        PARTITION BY k0.KTRT_PN_LAI_LICH_ID
                        ORDER BY NVL(k0.KTRT_NGAY_THA, k0.CREATION_TIME) DESC NULLS LAST
                    ) AS rn
                FROM PN_KET_THUC_RA_TRAIS k0
                WHERE NVL(k0.IS_DELETED, 0) = 0
                  AND k0.KTRT_PN_LAI_LICH_ID IN (SELECT pn_id FROM pn_ids)
            ) k
            WHERE k.rn = 1
        ),
        than_nhan_agg AS (
            SELECT
                tn.PHAM_NHAN_ID,
                MAX(CASE WHEN qh.QHVPN_MA = '121' THEN tn.HO_TEN_THAN_NHAN END) AS HO_TEN_BO,
                MAX(CASE WHEN qh.QHVPN_MA = '122' THEN tn.HO_TEN_THAN_NHAN END) AS HO_TEN_ME
            FROM THAN_NHAN_NGUOI_THANS tn
            INNER JOIN DM_QUAN_HE_VOI_PHAM_NHANS qh
                ON qh.ID = tn.QUAN_HE_ID
               AND NVL(qh.IS_DELETED, 0) = 0
               AND qh.QHVPN_MA IN ('121', '122')
            WHERE NVL(tn.IS_DELETED, 0) = 0
              AND tn.PHAM_NHAN_ID IN (SELECT pn_id FROM pn_ids)
            GROUP BY tn.PHAM_NHAN_ID
        ),
        base AS (
            SELECT /*+ MATERIALIZE */
                d.*,
                kt.KTRT_NGAY_THA,
                kt.KTRT_NGAY_TRINH_DIEN,
                kt.KTRT_SO_GCN,
                NVL(DVHC_TG.TTP_TEN, TG.TG_DIA_CHI) AS DIA_DIEM_BAN_HANH
            FROM vw_core d
            LEFT JOIN kt_one kt
                ON kt.KTRT_PN_LAI_LICH_ID = d.PHAM_NHAN_ID
            LEFT JOIN DM_TRAI_GIAMS TG
                ON TG.ID = d.TRAI_GIAM_ID
               AND NVL(TG.IS_DELETED, 0) = 0
            LEFT JOIN DM_TINH_THANH_PHO DVHC_TG
                ON DVHC_TG.ID = TG.TG_DIA_CHI_DP
               AND NVL(DVHC_TG.IS_DELETED, 0) = 0
        ),
        fn_vals AS (
            SELECT /*+ MATERIALIZE */
                s.pn_id AS PHAM_NHAN_ID,
                PKG_TINH_AN.FN_TINH_SO_LAN_GIAM_AN(s.pn_id) AS so_lan_giam,
                PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(s.pn_id) AS giam_an_hien_thi,
                PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(s.pn_id) AS tong_giam_an,
                SUBSTR(NVL(CAST(FN_GET_LIET_KE_HPBST_TNDST(s.pn_id) AS VARCHAR2(4000)), ''), 1, 4000) AS hpbs_ten
            FROM pn_ids s
        ),
        scalar_fns AS (
            SELECT /*+ MATERIALIZE */
                b.PHAM_NHAN_ID,
                f.so_lan_giam,
                f.giam_an_hien_thi,
                f.tong_giam_an,
                f.hpbs_ten
            FROM base b
            LEFT JOIN fn_vals f
                ON f.PHAM_NHAN_ID = b.PHAM_NHAN_ID
        )
        SELECT
            b.PHAM_NHAN_ID,
            b.HO_TEN,
            NVL(TRIM(CAST(b.CCCD AS VARCHAR2(100))), '') AS SO_CCCD,
            TO_CHAR(b.NGAY_CAP_CCCD, 'DD/MM/YYYY') AS NGAY_CAP_CCCD,
            b.NOI_CAP_CCCD AS NOI_CAP_CCCD,
            b.GIOI_TINH,
            b.NAM_SINH,
            b.NGAY_SINH,
            b.TEN_KHAC,
            b.NGUYEN_QUAN,
            b.DAN_TOC,
            b.QUOC_TICH,
            NVL(TRIM(CAST(b.PHAN_DOI AS NVARCHAR2(500))), u'') ||
                CASE WHEN b.PHAN_DOI IS NOT NULL AND b.PHAN_TRAI IS NOT NULL THEN u', ' ELSE u'' END ||
                NVL(TRIM(CAST(b.PHAN_TRAI AS NVARCHAR2(500))), u'') AS PHAN_DOI,
            b.PHAN_TRAI,
            b.SO_HO_SO,
            NVL(b.NOI_THUONG_TRU_DAY_DU, b.DIA_CHI_THUONG_TRU) AS NOI_DKTT,
            b.NOI_THUONG_TRU_DAY_DU,
            b.NOI_THA_VE_CU_TRU,
            b.NOI_THA_VE_CU_TRU_XA,
            b.NOI_THA_VE_CU_TRU_TINH,
            b.NOI_O_KHAC,
            u'UBND ' || NVL(b.NOI_THA_VE_CU_TRU_XA, u'') || u', ' || NVL(b.NOI_THA_VE_CU_TRU_TINH, u'') AS NOI_GUI_UBND,
            u'C\00f4ng an ' || NVL(b.NOI_THA_VE_CU_TRU_TINH, u'') AS NOI_GUI_CONG_AN,
            u'Trung t\00e2m Y t\1ebf d\1ef1 ph\00f2ng ' || NVL(b.NOI_THA_VE_CU_TRU_TINH, u'') AS NOI_GUI_YTDP,
            TRIM(NVL(b.PHAN_DOI, u'') || NVL2(b.PHAN_DOI, u', ', u'') || NVL(b.PHAN_TRAI, u'')) AS DANG_CHAP_HANH_TAI,
            b.TRAI_GIAM,
            NVL(tna.HO_TEN_BO, u'') AS HO_TEN_BO,
            NVL(tna.HO_TEN_ME, u'') AS HO_TEN_ME,
            b.TOI_DANH,
            b.KHOAN AS THA_KHOAN,
            b.DIEU AS THA_DIEU,
            b.CAN_CU_TUYEN_PHAT AS THA_CAN_CU_TUYEN_PHAT,
            b.SO_QD_THA AS THA_SO_QD_THA,
            TO_CHAR(b.NGAY_QD_THA, 'DD/MM/YYYY') AS THA_NGAY_QD_THA,
            TO_CHAR(b.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS THA_NGAY_BAT,
            b.AN_PHAT AS THA_AN_PHAT,
            b.SO_BAN_AN AS THA_SO_BAN_AN,
            TO_CHAR(b.NGAY_BAN_AN, 'DD/MM/YYYY') AS THA_NGAY_BAN_AN,
            b.THA_TOA_QD_THA,
            b.THA_CO_QUAN_LAP,
            b.THA_DIA_PHUONG_TOA_QD_THA,
            b.THA_DIA_PHUONG_CO_QUAN_LAP,
            b.SO_DANH_BAN AS THA_SO_DANH_BAN,
            fn.hpbs_ten AS HPBS_TEN,
            u'' AS HPBS_HIEN_THI,
            fn.so_lan_giam AS LAN_GIAM_AN,
            fn.tong_giam_an AS TONG_GIAM_AN,
            CASE
                WHEN fn.so_lan_giam > 0
                THEN TRIM(CAST(fn.giam_an_hien_thi AS VARCHAR2(500)))
                ELSE NULL
            END AS DA_GIAM_FORMAT,
            CASE
                WHEN b.SO_BAN_AN IS NOT NULL
                THEN u'B\1ea3n \00e1n s\1ed1 ' || b.SO_BAN_AN || u' ng\00e0y '
                    || TO_CHAR(b.NGAY_BAN_AN, 'DD/MM/YYYY') || u' c\1ee7a To\00e0 \00e1n nh\00e2n d\00e2n '
                    || NVL(b.THA_DIA_PHUONG_TOA_QD_THA, u'')
                ELSE NULL
            END AS CAN_CU_BAN_AN,
            CASE
                WHEN b.SO_QD_THA IS NOT NULL
                THEN u'Quy\1ebft \0111\1ecbnh thi h\00e0nh \00e1n s\1ed1 ' || b.SO_QD_THA || u' ng\00e0y '
                    || TO_CHAR(b.NGAY_QD_THA, 'DD/MM/YYYY') || u' c\1ee7a TAND '
                    || NVL(b.THA_DIA_PHUONG_CO_QUAN_LAP, u'')
                ELSE NULL
            END AS CAN_CU_QD_THA,
            TO_CHAR(b.KTRT_NGAY_THA, 'DD/MM/YYYY') AS KTRT_NGAY_THA,
            TO_CHAR(b.KTRT_NGAY_TRINH_DIEN, 'DD/MM/YYYY') AS KTRT_NGAY_TRINH_DIEN,
            b.KTRT_SO_GCN,
            b.LL_SO_GCN,
            b.DIA_DIEM_BAN_HANH,
            TO_CHAR(SYSDATE, 'DD/MM/YYYY') AS NGAY_BAN_HANH_STR,
            b.THOI_GIAN_TAM_GIAM AS MUC_TAM_GIAM,
            b.THOI_GIAN_TAM_GIU AS MUC_TAM_GIU,
            TO_CHAR(b.NGAY_HET_AN, 'DD/MM/YYYY') AS NGAY_HET_AN,
            b.SO_DANH_BAN,
            TO_CHAR(b.NGAY_LAP_DANH_BAN, 'DD/MM/YYYY') AS NGAY_LAP_DANH_BAN,
            b.TOA_XU_TEN,
            b.TOA_XU_DIA_PHUONG,
            b.TINH_THANH_THUONG_TRU,
            b.PHUONG_XA_THUONG_TRU,
            hpbs.HPBS_TONG_TIEN_CON_LAI
        FROM base b
        LEFT JOIN scalar_fns fn
            ON fn.PHAM_NHAN_ID = b.PHAM_NHAN_ID
        LEFT JOIN than_nhan_agg tna
            ON tna.PHAM_NHAN_ID = b.PHAM_NHAN_ID
        LEFT JOIN PN_HINH_PHAT_BO_SUNGS hpbs
            ON hpbs.HPBS_MA_PHAM_NHAN = b.PHAM_NHAN_ID
        ORDER BY b.HO_TEN_ORDER, b.PHAM_NHAN_ID;

    DBMS_SQL.RETURN_RESULT(C1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_PN_CHAP_HANH_XONG_AN_PHAT_TU: ' || SQLERRM);
END;

