--------------------------------------------------------
--  DDL for Procedure SP_GET_PT26
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PT26" (
    p_pll_id IN NUMBER
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH 
    SPLIT_TOI_DANH AS (
        SELECT /*+ NO_MERGE */
               ptha.THA_PNLAI_LICH_ID,
               dtd.ID  AS TOI_DANH_ID,
               dtd.TD_TEN
          FROM PN_THI_HANH_AN ptha
          JOIN DM_TOI_DANHS dtd
            ON INSTR(',' || REPLACE(REPLACE(ptha.THA_TOI_DANH,'[',''),']','') || ',',
                     ',' || dtd.ID || ',') > 0
         WHERE ptha.THA_TOI_DANH IS NOT NULL
           AND ptha.THA_PNLAI_LICH_ID = p_pll_id
           AND NVL(dtd.IS_DELETED, 0) = 0
    ),
    TOI_DANH_AGG AS (
        SELECT /*+ NO_MERGE */
               THA_PNLAI_LICH_ID,
               RTRIM(
                   XMLAGG(XMLELEMENT(e, TD_TEN || '; ') ORDER BY TD_TEN)
                       .extract('//text()').GETCLOBVAL(),
                   '; '
               ) AS TOI_DANH
          FROM SPLIT_TOI_DANH
         GROUP BY THA_PNLAI_LICH_ID
    ),
    LATEST_THA AS (
        SELECT /*+ NO_MERGE */
               THA_PNLAI_LICH_ID,
               THA_NGAY_BAT,
               THA_AN_PHAT,
               THA_SO_BAN_AN,
               THA_CAP_TOA_ID,
               TO_CHAR(THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS THA_NGAY_BAN_AN,
               d2.TTP_TEN AS DIA_PHUONG_TOA,
               THA_SO_QD_THA,
               TO_CHAR(THA_NGAY_QD_THA, 'DD/MM/YYYY') AS THA_NGAY_QD_THA,
               THA_TOA_QD_ID,
               d.TTP_TEN  AS DIA_PHUONG_THA,
               THA_SO_QD_DIEU_CHUYEN,
               TO_CHAR(THA_NGAY_QD_DIEU_CHUYEN, 'DD/MM/YYYY') AS THA_NGAY_QD_DIEU_CHUYEN,
               THA_DON_VI_DE_NGHI_ID,
               THA_CHUYEN_DEN_TU_ID,
               THA_THOI_GIAN_TAM_GIAM,
               THA_THOI_GIAN_TAM_GIU,
               THA_NGAY_DEN_TRAI,
               THA_NGAY_HET_HAN
          FROM PN_THI_HANH_AN
          LEFT JOIN DM_TINH_THANH_PHO d  ON PN_THI_HANH_AN.THA_DIA_PHUONG_TOA_QD_THA_ID = d.ID
          LEFT JOIN DM_TINH_THANH_PHO d2 ON PN_THI_HANH_AN.THA_DIA_PHUONG_CAP_TOA_ID    = d2.ID
         WHERE THA_PNLAI_LICH_ID = p_pll_id
         ORDER BY NVL(THA_NGAY_BAN_AN, DATE '1900-01-01') DESC,
                  PN_THI_HANH_AN.ID DESC
         FETCH FIRST 1 ROW ONLY
    ),
    LATEST_CON AS (
        SELECT
            tnc.PHAM_NHAN_ID,
            tnc.ID           AS CON_ID,
            tnc.HO_TEN_CON,
            tnc.GIOI_TINH_ID,
            tnc.NGAY_SINH,
            tnc.NOI_SINH,
            tnc.NGAY_DEN,
            tnc.NGAY_RA,
            tnc.GHI_CHU,
            ROW_NUMBER() OVER (
                PARTITION BY tnc.PHAM_NHAN_ID
                ORDER BY tnc.ID DESC
            ) AS rn
        FROM THAN_NHAN_CON_CAIS tnc
        LEFT JOIN DM_TINH_TRANG_CON_THEO_ME_VAO_TRAIES d on tnc.TINH_TRANG_ID = d.ID
        WHERE tnc.PHAM_NHAN_ID = p_pll_id
          AND NVL(tnc.IS_DELETED, 0) = 0 
 -- ch?a có tình tr?ng ch?t 

    )
    SELECT
        pll.LL_HO_TEN          AS HoTen,
        pll.LL_TEN_KHAC        AS TenKhac,
        dgt.GT_TEN              AS GioiTinh,
        pll.LL_NGAY_SINH       AS NgaySinh,
		pll.LL_NGUYEN_QUAN AS QueQuan,
        CASE
            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || dxp_thuong_tru.XP_TEN
                            ELSE dxp_thuong_tru.XP_TEN
                        END
                    ELSE u''
                   END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || dttp_thuong_tru.TTP_TEN
                            ELSE dttp_thuong_tru.TTP_TEN
                        END
                    ELSE u''
                   END
            )
            ELSE NULL
        END AS DiaChiThuongTru,

        TO_CHAR(TRUNC(ptha.THA_NGAY_BAT), 'DD/MM/YYYY') AS NgayBat,
        ptha.THA_AN_PHAT          AS AnPhat,
		tda.TOI_DANH   AS ToiDanh,
        ptha.THA_SO_BAN_AN        AS BanAnSo,
        ptha.THA_NGAY_BAN_AN      AS NgayBanAn,
        dcq.CQ_TEN                AS ToaQuyetDinh,
        ptha.DIA_PHUONG_TOA       AS DiaPhuongToa,
		TO_CHAR(TRUNC(ptha.THA_NGAY_DEN_TRAI), 'DD/MM/YYYY') AS NgayDenTrai,
        ptha.THA_SO_QD_THA        AS SoQuyetDinhTHA,
        ptha.THA_NGAY_QD_THA      AS NgayQuyetDinhTHA,
        dcq5.CQ_TEN                AS CoQuanQuyetDinh,
        ptha.DIA_PHUONG_THA       AS DiaPhuongQuyetDinh,

        dpd.PD_TEN                AS PhanDoi,
        dpt.PT_TEN                 AS PhanTrai,
        dtg.TG_TEN                 AS TraiGiam,

        -- Thông tin con
        con.HO_TEN_CON             AS HoTenCon,
        dgt2.GT_TEN                 AS GioiTinhCon,
        con.NGAY_SINH               AS NgaySinhCon,
        con.NOI_SINH                AS NoiSinhCon,
        TO_CHAR(con.NGAY_DEN, 'DD/MM/YYYY') AS NgayDenCon,
        TO_CHAR(con.NGAY_RA,  'DD/MM/YYYY') AS NgayRaCon,
        con.GHI_CHU                 AS GhiChuCon

    FROM PN_LAI_LICHS pll
    LEFT JOIN LATEST_THA ptha
           ON pll.ID = ptha.THA_PNLAI_LICH_ID
    LEFT JOIN TOI_DANH_AGG tda ON pll.ID = tda.THA_PNLAI_LICH_ID
    LEFT JOIN DM_GIOI_TINHS dgt   ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
          AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
          AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS dcq     ON ptha.THA_TOA_QD_ID  = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq5    ON ptha.THA_CAP_TOA_ID = dcq5.ID
    LEFT JOIN DM_PHAN_DOIS dpd    ON pll.LL_PHAN_DOI_ID  = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt   ON pll.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg   ON pll.LL_TRAI_GIAM_ID = dtg.ID
    LEFT JOIN LATEST_CON con
           ON pll.ID = con.PHAM_NHAN_ID
          AND con.rn = 1
    LEFT JOIN DM_GIOI_TINHS dgt2  ON con.GIOI_TINH_ID = dgt2.ID
    WHERE pll.ID = p_pll_id;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        NULL;
    WHEN TOO_MANY_ROWS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Có nhi?u h?n 1 b?n ghi cho ph?m nhân ID: ' || p_pll_id);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: ' || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PT3
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PT3" (
    p_ma_trai_giam IN VARCHAR2 DEFAULT NULL
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    /* ------------------------------------------------------------------ */
    /* 0. Danh sach PN can lay: luon doc tu QLPN.GTT_PN_IDS - noi goi phai */
    /*    nap san ID (array binding) truoc khi goi SP nay, ke ca truong   */
    /*    hop chi lay 1 PN (xem 1 phieu don le).                          */
    /* ------------------------------------------------------------------ */
    ID_LIST AS (
        SELECT PN_ID FROM QLPN.GTT_PN_IDS
    ),
    LATEST_THA AS (
        SELECT
            THA_PNLAI_LICH_ID,
            THA_NGAY_BAT,
            THA_AN_PHAT,
            THA_SO_BAN_AN,
            TO_CHAR(THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS THA_NGAY_BAN_AN,
            THA_TOA_QD_ID,
            d2.TTP_TEN AS DIA_PHUONG_TOA,
            THA_SO_QD_THA,
            TO_CHAR(THA_NGAY_QD_THA, 'DD/MM/YYYY') AS THA_NGAY_QD_THA,
            THA_CAP_TOA_ID,
            d.TTP_TEN AS DIA_PHUONG_THA,
            THA_TOI_DANH_NAMES,
            THA_CHUYEN_DEN_TU_ID,
            ROW_NUMBER() OVER (
                PARTITION BY THA_PNLAI_LICH_ID
                ORDER BY NVL(THA_NGAY_BAN_AN, TO_DATE('01-JAN-1900', 'DD-MON-YYYY')) DESC, PN_THI_HANH_AN.ID DESC
            ) AS rn,
            TO_CHAR(THA_NGAY_QD_DIEU_CHUYEN, 'DD/MM/YYYY') AS THA_NGAY_QD_DIEU_CHUYEN,
            dcqQD.CQ_TEN AS DON_VI_DE_NGHI,
            d3.TTP_TEN AS DIA_PHUONG_DON_VI_DE_NGHI,
            PN_THI_HANH_AN.THA_SO_DE_NGHI,
            TO_CHAR(THA_NGAY_DE_NGHI, 'DD/MM/YYYY') AS THA_NGAY_DE_NGHI,
            TO_CHAR(THA_NGAY_DEN_TRAI, 'DD/MM/YYYY') AS THA_NGAY_DEN_TRAI,
            THA_SO_QD_DIEU_CHUYEN
        FROM PN_THI_HANH_AN
        LEFT JOIN DM_TINH_THANH_PHO d  ON PN_THI_HANH_AN.THA_DIA_PHUONG_TOA_QD_THA_ID = d.ID
        LEFT JOIN DM_TINH_THANH_PHO d2 ON PN_THI_HANH_AN.THA_DIA_PHUONG_CAP_TOA_ID    = d2.ID
        LEFT JOIN DM_TINH_THANH_PHO d3 ON PN_THI_HANH_AN.THA_DIA_PHUONG_DON_VI_DE_NGHI_ID    = d3.ID
        LEFT JOIN DM_CO_QUANS dcqQD    ON PN_THI_HANH_AN.THA_DON_VI_DE_NGHI_ID = dcqQD.ID
        WHERE THA_PNLAI_LICH_ID IN (SELECT PN_ID FROM ID_LIST)
    )
    SELECT
        dmml.MPL_TEN            AS LoaiPhanLoai,
        dplgg.PLGG_TEN            AS TuLoai,
        dplgg2.PLGG_TEN            AS DenLoai,
        pll.LL_HO_TEN          AS HoTen,
        pll.LL_TEN_KHAC        AS TenKhac,
        dgt.GT_TEN             AS GioiTinh,
        pll.LL_NGAY_SINH       AS NgaySinh,

        CASE
            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || dxp_thuong_tru.XP_TEN
                            ELSE dxp_thuong_tru.XP_TEN
                        END
                    ELSE u''
                   END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || dttp_thuong_tru.TTP_TEN
                            ELSE dttp_thuong_tru.TTP_TEN
                        END
                    ELSE u''
                   END
            )
            ELSE NULL
        END AS DiaChiThuongTru,

        ddt.DT_TEN              AS DanToc,
        dtg2.TG_TEN              AS TonGiao,
        dqt.QT_TEN               AS QuocTich,

        TO_CHAR(TRUNC(ptha.THA_NGAY_BAT), 'DD/MM/YYYY') AS NgayBat,
        ptha.THA_AN_PHAT          AS AnPhat,

        ptha.THA_SO_BAN_AN        AS BanAnSo,
        ptha.THA_NGAY_BAN_AN      AS NgayBanAn,
        dcq.CQ_TEN                AS ToaQuyetDinhTHA,
        ptha.DIA_PHUONG_TOA       AS DiaPhuongToa,
        

        ptha.THA_SO_QD_THA        AS SoQuyetDinhTHA,
        ptha.THA_NGAY_QD_THA      AS NgayQuyetDinhTHA,
        dcq5.CQ_TEN                AS CoQuanQuyetDinh,
        ptha.DIA_PHUONG_THA       AS DiaPhuongQuyetDinh,

        dpd.PD_TEN                AS PhanDoi,
        dpt.PT_TEN                 AS PhanTrai,
        dtg.TG_TEN                 AS TraiGiam,

        ptha.THA_TOI_DANH_NAMES   AS TOIDANH,
        dcq_cdt.CQ_TEN             AS CHUYENDENTU,
        dtg.TG_TEN                 AS NOICHUYENDEN,
        ptha.THA_NGAY_QD_DIEU_CHUYEN AS NGAYQDDIEUCHUYEN,
        ptha.DON_VI_DE_NGHI AS DONVIDENGHI,
        ptha.DIA_PHUONG_DON_VI_DE_NGHI AS DIAPHUONGDONVIDENGHI,
        ptha.THA_SO_DE_NGHI AS SODENGHI,
        ptha.THA_NGAY_DE_NGHI AS NGAYDENGHI,
        pnct.PNCT_CONG_VAN_DE_NGHI_SO AS CONGVANDENGHI,
        TO_CHAR(TRUNC(pnct.PNCT_CONG_VAN_DE_NGHI_NGAY), 'DD/MM/YYYY') AS CONGVANDENGHINGAY,
        dcq6.CQ_TEN AS COQUANDENGHICHUYEN,
        dttp_thuong_tru_chuyen_trai.TTP_TEN AS TINHCOQUANDENGHICHUYEN,
        ptha.THA_NGAY_DEN_TRAI AS NGAYDENTRAI,
        ptha.THA_SO_QD_DIEU_CHUYEN AS SOQDDIEUCHUYEN
    FROM PN_LAI_LICHS pll
    LEFT JOIN pham_nhan_chuyen_trai pnct on pll.ID = pnct.PNCT_LAI_LICH_ID
    LEFT JOIN LATEST_THA ptha
           ON pll.ID = ptha.THA_PNLAI_LICH_ID
          AND ptha.rn = 1
    left join PHAN_LOAIS pl ON pll.ID = pl.PHAM_NHAN_ID
    left join DM_MA_PHAN_LOAIES dmml ON pl.LOAI_PHAN_LOAI_ID = dmml.ID
    left join DM_PHAN_LOAI_GIAM_GIUS dplgg ON pl.TU_LOAI_ID = dplgg.ID
    left join DM_PHAN_LOAI_GIAM_GIUS dplgg2 ON pl.DEN_LOAI_ID = dplgg2.ID
    LEFT JOIN DM_GIOI_TINHS dgt   ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_DAN_TOCS  ddt    ON pll.LL_DM_DAN_TOC_ID   = ddt.ID
    LEFT JOIN DM_TON_GIAOS dtg2   ON pll.LL_DM_TON_GIAO_ID  = dtg2.ID
    LEFT JOIN DM_QUOC_TICHS dqt   ON pll.LL_DM_QUOC_TICH_ID = dqt.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
          AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru_chuyen_trai
           ON dttp_thuong_tru_chuyen_trai.ID = pnct.PNCT_CO_QUAN_DE_NGHI_DIA_PHUONG_ID
          AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
          AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_CO_QUANS dcq     ON ptha.THA_TOA_QD_ID  = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq5    ON ptha.THA_CAP_TOA_ID = dcq5.ID
    LEFT JOIN DM_CO_QUANS dcq6    ON pnct.PNCT_CO_QUAN_DE_NGHI_CHUYEN_ID = dcq6.ID
    LEFT JOIN DM_PHAN_DOIS dpd    ON pll.LL_PHAN_DOI_ID  = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt   ON pll.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg   ON pll.LL_TRAI_GIAM_ID = dtg.ID
    LEFT JOIN DM_CO_QUANS dcq_cdt ON ptha.THA_CHUYEN_DEN_TU_ID = dcq_cdt.ID
    WHERE pll.ID IN (SELECT PN_ID FROM ID_LIST)
      AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam);

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        NULL;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: ' || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END;

