set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PT80" (
    P_TU_NGAY IN DATE,
    P_DEN_NGAY IN DATE,
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL
) IS
    I               NUMBER;
    TS_TMP          NUMBER;
    L_TMP_CH16      NUMBER;   -- n?n cho c?t 32 (TD_CHUONG = '16')
    L_TMP_CH21      NUMBER;   -- n?n cho c?t 38 (TD_CHUONG = '21')
    TYPE COLVAL IS TABLE OF NUMBER(10) INDEX BY BINARY_INTEGER;
    COLV            COLVAL;
    V_TRAI_GIAM_ID  NUMBER;
    V_DEN_NGAY      DATE;
	V_NAM_HIEN_TAI	NUMBER;			
    V_DEN_NGAY_EXCL DATE;
    L_RESULT        T_PT80;
    L_CUR           SYS_REFCURSOR;
BEGIN
    IF p_ma_trai_giam IS NOT NULL THEN
        BEGIN
            SELECT ID
            INTO V_TRAI_GIAM_ID
            FROM DM_TRAI_GIAMS
            WHERE TG_MA = p_ma_trai_giam
              AND IS_DELETED = 0
              AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN V_TRAI_GIAM_ID := -1;
        END;
    END IF;

    V_DEN_NGAY := LEAST(
            CAST(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh' AS DATE),
            P_DEN_NGAY);
    V_DEN_NGAY_EXCL := V_DEN_NGAY + 1;

    V_NAM_HIEN_TAI := EXTRACT(YEAR FROM V_DEN_NGAY);

    SP_POPULATE_TK_PT80_ALT(V_DEN_NGAY, V_TRAI_GIAM_ID);

    -- L?u ý: b? SP_POPULATE_TK_PT80T vì c?t 1 nay ???c tính b?ng công th?c
    -- C1 = C20 - C8 + C16 (xem ph?n cu?i). N?u SP_POPULATE_TK_PT80T còn tác d?ng
    -- ph? c?n thi?t, hãy gi? l?i; ng??c l?i lo?i b? ?? ti?t ki?m th?i gian ch?y.

    -- 2026-08-22: cache tình tr?ng ??u k? (T1 = P_TU_NGAY-1) cho guard nhóm 111-114 bên d??i
    -- (cùng c? ch? PN_TINH_TRANG_TAI_NGAY_CACHE dùng ? 2 SP dashboard/FN_PN_TANG_GIAM_TRONG_KY).
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(P_TU_NGAY - 1);

    L_RESULT := T_PT80();

--    C1: S? tháng tr??c chuy?n sang -- GI? CH?, tính l?i sau khi có C8, C16, C20
    L_RESULT.EXTEND;
    COLV(1) := 0;
    L_RESULT(L_RESULT.COUNT) := O_PT80(1, u'S\1ed1 th\00e1ng tr\01b0\1edbc chuy\1ec3n sang', 0);

    -- ===================================================================
    -- C2-C16 (T?NG/GI?M): 1 l?n quét WITH 3 t?ng (RAW -> ALL_TANG/GIAM_RAW -> GUARDED).
    -- 2026-08-22: thêm guard "ch? tính khi PN th?c s? ??i nhóm 111-114" (cùng nguyên lý
    -- FN_PN_TANG_GIAM_TRONG_KY 2026-08-21) + 2 fix TX_NGAY_TRA validity (RAW_C6, RAW_C9) —
    -- xem plan/th-m-i-u-ki-n-lo-i-ticklish-breeze.md. Gi? NGUYÊN m?i ??nh ngh?a s? ki?n g?c
    -- hi?n có c?a PT80 (không ??i ranh gi?i c?t C2/C7/C9/C14 theo hàm dùng chung — xem plan).
    -- RAW_C3 (chuy?n tr?i n?i b?, LDT_MA=20221) KHÔNG guard — gi?ng TANG_3_IDS, ch? ??i tr?i
    -- v?t lý, không ??i nhóm 111-114.
    -- ===================================================================
    -- C3: Trai giam khac chuyen den — tách riêng thành 1 câu ??c l?p (không ??a vào WITH
    -- chung bên d??i): tr?n 1 scalar subquery COUNT(*) không t??ng quan v?i các c?t
    -- SUM(CASE...) khác trong cùng SELECT list gây ORA-00937 (not a single-group group
    -- function) — phát hi?n lúc ki?m th? 2026-08-22.
    SELECT COUNT(*)
    INTO COLV(3)
    FROM PN_THI_HANH_AN THA
             JOIN PN_LAI_LICHS LL ON LL.ID = THA.THA_PNLAI_LICH_ID AND LL.IS_DELETED = 0
             LEFT JOIN DM_LOAI_DOI_TUONGS LDT ON LDT.ID = THA.THA_DOI_TUONG AND LDT.IS_DELETED = 0
    WHERE THA.THA_NGAY_DEN_TRAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
      AND LDT.LDT_MA = u'20221';

    WITH
    RAW_C2 AS (
        SELECT THA.THA_PNLAI_LICH_ID AS ID, CAST(THA.THA_NGAY_DEN_TRAI AS DATE) AS EVENT_DATE
          FROM PN_THI_HANH_AN THA
                   JOIN PN_LAI_LICHS LL
                        ON LL.ID = THA.THA_PNLAI_LICH_ID AND LL.IS_DELETED = 0 AND THA.IS_DELETED = 0
                   LEFT JOIN DM_LOAI_DOI_TUONGS LDT ON LDT.ID = THA.THA_DOI_TUONG AND LDT.IS_DELETED = 0
         WHERE THA.THA_NGAY_DEN_TRAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
           AND LDT.LDT_MA IN (u'20211', u'110', u'120')
    ),
    RAW_C4 AS (
        SELECT TT.PHAM_NHAN_ID AS ID, CAST(TT.NGAY_BAT_LAI AS DATE) AS EVENT_DATE
          FROM TRON_TRAIS TT
                   JOIN PN_LAI_LICHS LL ON LL.ID = TT.PHAM_NHAN_ID AND TT.IS_DELETED = 0 AND LL.IS_DELETED = 0
                   JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
         WHERE TT.NGAY_BAT_LAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND TT.NGAY_TRON >= THA.THA_NGAY_DEN_TRAI
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
    ),
    RAW_C5 AS (
        SELECT TDC.PHAM_NHAN_ID AS ID, CAST(TDC.NGAY_LAI AS DATE) AS EVENT_DATE
          FROM TAM_DINH_CHIS TDC
                   JOIN PN_LAI_LICHS LL
                        ON LL.ID = TDC.PHAM_NHAN_ID AND TDC.IS_DELETED = 0 AND LL.IS_DELETED = 0
                   JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
                   LEFT JOIN QLPN.DM_LOAI_QUYET_DINH_TAM_DINH_CHIES ldtdc ON LDTDC.ID = TDC.LOAI_QUYET_DINH_ID
         WHERE TDC.NGAY_LAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND TDC.NGAY_TDC > THA.THA_NGAY_DEN_TRAI
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
    ),
    -- FIX 2026-08-22: thêm "TX_NGAY_TRA >= TX_NGAY_TRICH_XUAT" — TX_NGAY_TRA l?i nh?p li?u
    -- (??ng tr??c c? ngày trích xu?t) coi nh? CH?A TR? L?I, không phát sinh s? ki?n t?ng gi?
    -- ? m?t k? báo cáo SAI (??ng b? fix ?ã áp d?ng cho TANG_6_IDS 2026-08-21).
    RAW_C6 AS (
        SELECT TX.PHAM_NHAN_ID AS ID, CAST(TX.TX_NGAY_TRA AS DATE) AS EVENT_DATE
          FROM TRICH_XUATS TX
                   JOIN PN_LAI_LICHS LL ON LL.ID = TX.PHAM_NHAN_ID AND LL.IS_DELETED = 0
                   JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
                   LEFT JOIN QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS ldtx
                             ON ldtx.ID = TX.TX_LOAI_LENH_ID AND ldtx.IS_DELETED = 0
         WHERE TX.TX_NGAY_TRA BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND TX.IS_DELETED = 0
           AND TX.TX_NGAY_TRICH_XUAT > THA.THA_NGAY_DEN_TRAI
           AND CAST(TX.TX_NGAY_TRA AS DATE) >= CAST(TX.TX_NGAY_TRICH_XUAT AS DATE)
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
           AND LQDTX_MA = 1
    ),
    -- C7: Tang khac (THA khac/huy an tro lai/tha_co_dk bat lai/CBBB ket thuc/hoan ket thuc)
    -- gi? nguyên 5 nhánh hi?n có, g?p UNION ALL ?? cùng ?i qua guard bên d??i.
    RAW_C7 AS (
        SELECT THA.THA_PNLAI_LICH_ID AS ID, CAST(THA.THA_NGAY_DEN_TRAI AS DATE) AS EVENT_DATE
          FROM PN_THI_HANH_AN THA
                   JOIN PN_LAI_LICHS LL
                        ON LL.ID = THA.THA_PNLAI_LICH_ID AND LL.IS_DELETED = 0 AND THA.IS_DELETED = 0
                   LEFT JOIN DM_LOAI_DOI_TUONGS LDT ON LDT.ID = THA.THA_DOI_TUONG AND LDT.IS_DELETED = 0
         WHERE THA.THA_NGAY_DEN_TRAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND LDT.LDT_MA NOT IN (u'20211', u'110', u'120', u'20221')
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
        UNION ALL
        SELECT HA.PHAM_NHAN_ID AS ID, CAST(HA.NGAY_TRO_LAI AS DATE) AS EVENT_DATE
          FROM HUY_ANS HA
                   JOIN PN_LAI_LICHS LL ON LL.ID = HA.PHAM_NHAN_ID AND LL.IS_DELETED = 0
                   JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
         WHERE HA.NGAY_TRO_LAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND HA.NGAY_TRA_TU_DO > THA.THA_NGAY_DEN_TRAI
           AND HA.IS_DELETED = 0
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
        UNION ALL
        SELECT TCK.PHAM_NHAN_ID AS ID, CAST(TCK.NGAY_BAT_LAI AS DATE) AS EVENT_DATE
          FROM THA_CO_DIEU_KIENS TCK
                   JOIN PN_LAI_LICHS LL ON LL.ID = TCK.PHAM_NHAN_ID AND LL.IS_DELETED = 0
         WHERE TCK.NGAY_BAT_LAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND TCK.IS_DELETED = 0
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
        UNION ALL
        SELECT CB.PHAM_NHAN_ID AS ID, CAST(CB.NGAY_KET_THUC AS DATE) AS EVENT_DATE
          FROM CHUA_BENH_BAT_BUOCS CB
                   JOIN PN_LAI_LICHS LL ON LL.ID = CB.PHAM_NHAN_ID
         WHERE CB.NGAY_KET_THUC BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND LL.IS_DELETED = 0
           AND CB.IS_DELETED = 0
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
        UNION ALL
        SELECT HOAN.PHAM_NHAN_ID AS ID, CAST(HOAN.NGAY_THI_HANH_AN AS DATE) AS EVENT_DATE
          FROM HOAN_THI_HANH_ANS HOAN
                   JOIN PN_LAI_LICHS LL ON LL.ID = HOAN.PHAM_NHAN_ID
         WHERE HOAN.NGAY_THI_HANH_AN BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND LL.IS_DELETED = 0
           AND HOAN.IS_DELETED = 0
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
    ),
    -- C9: Tha — gi? nguyên 4 NOT EXISTS hi?n có. FIX 2026-08-22: NOT EXISTS trích xu?t active
    -- thêm "OR TX_NGAY_TRA < TX_NGAY_TRICH_XUAT" (TX_NGAY_TRA l?i coi nh? ch?a v?, ??ng b?
    -- RAW_C6) — tránh ??m "Tha" cho PN th?c ra v?n ?ang trích xu?t do d? li?u ngày l?i.
    RAW_C9 AS (
        SELECT DISTINCT ll.ID AS ID, CAST(tha.THA_NGAY_HET_HAN AS DATE) AS EVENT_DATE
          FROM PN_LAI_LICHS ll
                   JOIN PN_THI_HANH_AN tha
                        ON tha.THA_PNLAI_LICH_ID = ll.ID AND tha.IS_DELETED = 0
         WHERE tha.THA_NGAY_HET_HAN BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND ll.IS_DELETED = 0
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
           AND NOT EXISTS (SELECT 1
                           FROM MIEN_HINH_PHATS mhp
                          WHERE mhp.PN_LAI_LICH_ID = ll.ID
                            AND mhp.IS_DELETED = 0
                            AND mhp.MHP_NGAY_TU_DO BETWEEN P_TU_NGAY AND V_DEN_NGAY
                            AND (V_TRAI_GIAM_ID IS NULL OR ll.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID))
           AND NOT EXISTS (SELECT 1
                           FROM CHUA_BENH_BAT_BUOCS cb
                          WHERE cb.PHAM_NHAN_ID = ll.ID
                            AND (cb.NGAY_KET_THUC IS NULL
                              OR cb.NGAY_KET_THUC > V_DEN_NGAY)
                            AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID))
           AND NOT EXISTS (SELECT 1
                           FROM TRICH_XUATS tx
                                    JOIN QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS ldtx
                                         ON ldtx.ID = tx.TX_LOAI_LENH_ID
                                             AND ldtx.IS_DELETED = 0
                          WHERE tx.PHAM_NHAN_ID = ll.ID
                            AND tx.IS_DELETED = 0
                            AND ldtx.LQDTX_MA = '1'
                            AND (tx.TX_NGAY_TRA IS NULL
                              OR tx.TX_NGAY_TRA > V_DEN_NGAY
                              OR tx.TX_NGAY_TRA < tx.TX_NGAY_TRICH_XUAT)
                            AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID))
           AND NOT EXISTS (SELECT 1
                           FROM HUY_ANS ha
                          WHERE ha.PHAM_NHAN_ID = ll.ID
                            AND ha.IS_DELETED = 0
                            AND ha.NGAY_TRA_TU_DO BETWEEN P_TU_NGAY AND V_DEN_NGAY)
    ),
    RAW_C10 AS (
        SELECT TT.PHAM_NHAN_ID AS ID, CAST(TT.NGAY_TRON AS DATE) AS EVENT_DATE
          FROM TRON_TRAIS TT
                   JOIN PN_LAI_LICHS LL ON LL.ID = TT.PHAM_NHAN_ID AND LL.IS_DELETED = 0
                   JOIN PN_THI_HANH_AN THA ON THA.THA_PNLAI_LICH_ID = LL.ID AND THA.IS_DELETED = 0
         WHERE TT.NGAY_TRON >= P_TU_NGAY AND TT.NGAY_TRON < V_DEN_NGAY_EXCL
           AND TT.IS_DELETED = 0
           AND TT.NGAY_TRON >= THA.THA_NGAY_DEN_TRAI
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
    ),
    RAW_C11 AS (
        SELECT KC.KTC_PN_LAI_LICH_ID AS ID, CAST(KC.KTC_NGAY_CHET AS DATE) AS EVENT_DATE
          FROM PN_KET_THUC_CHETS KC
                   JOIN PN_LAI_LICHS LL ON LL.ID = KC.KTC_PN_LAI_LICH_ID
                   JOIN PN_THI_HANH_AN THA ON THA.THA_PNLAI_LICH_ID = LL.ID AND THA.IS_DELETED = 0
                   LEFT JOIN DM_TRUONG_HOP_CHETS THC ON THC.ID = KC.KTC_DM_TRUONG_HOP_CHET_ID
         WHERE KC.KTC_NGAY_CHET >= P_TU_NGAY
           AND KC.KTC_NGAY_CHET < (V_DEN_NGAY + 1)
           AND KC.KTC_NGAY_CHET > THA.THA_NGAY_DEN_TRAI
           AND NVL(THC.THC_MA, '10') NOT IN ('30', '40', '50')
           AND KC.IS_DELETED = 0
           AND LL.IS_DELETED = 0
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
    ),
    RAW_C12 AS (
        SELECT TX.PHAM_NHAN_ID AS ID, CAST(TX.TX_NGAY_TRICH_XUAT AS DATE) AS EVENT_DATE
          FROM TRICH_XUATS TX
                   JOIN PN_LAI_LICHS LL ON LL.ID = TX.PHAM_NHAN_ID AND LL.IS_DELETED = 0
                   JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
                   LEFT JOIN QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS ldtx
                             ON ldtx.ID = TX.TX_LOAI_LENH_ID AND ldtx.IS_DELETED = 0
         WHERE TX.TX_NGAY_TRICH_XUAT BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND ldtx.LQDTX_MA = '1'
           AND TX.IS_DELETED = 0
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
    ),
    RAW_C13 AS (
        SELECT TDC.PHAM_NHAN_ID AS ID, CAST(TDC.NGAY_TDC AS DATE) AS EVENT_DATE
          FROM TAM_DINH_CHIS TDC
                   JOIN PN_LAI_LICHS LL ON LL.ID = TDC.PHAM_NHAN_ID AND LL.IS_DELETED = 0
                   JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
                   LEFT JOIN QLPN.DM_LOAI_QUYET_DINH_TAM_DINH_CHIES lqdtdc ON LQDTDC.ID = TDC.LOAI_QUYET_DINH_ID
         WHERE TDC.NGAY_TDC BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND LQDTDC.LQDTDC_MA = '1'
           AND TDC.IS_DELETED = 0
           AND TDC.NGAY_TDC > THA.THA_NGAY_DEN_TRAI
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
    ),
    RAW_C14 AS (
        SELECT CT.PNCT_LAI_LICH_ID AS ID, CAST(CT.PNCT_NGAY_CHUYEN AS DATE) AS EVENT_DATE
          FROM PHAM_NHAN_CHUYEN_TRAI CT
                   JOIN PN_LAI_LICHS LL ON LL.ID = CT.PNCT_LAI_LICH_ID AND LL.IS_DELETED = 0
                   JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
                   LEFT JOIN DM_TRUONG_HOP_CHUYEN_TRAIS THCT
                             ON THCT.ID = CT.PNCT_TRUONG_HOP_CHUYEN_ID
         WHERE CT.PNCT_NGAY_CHUYEN BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND NVL(THCT.THCT_MA, '10') IN ('10', '20', '90')
           AND CT.IS_DELETED = 0
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
    ),
    RAW_C15 AS (
        SELECT HA.PHAM_NHAN_ID AS ID, CAST(HA.NGAY_TRA_TU_DO AS DATE) AS EVENT_DATE
          FROM HUY_ANS HA
                   JOIN PN_LAI_LICHS LL ON LL.ID = HA.PHAM_NHAN_ID
                   JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
         WHERE HA.NGAY_TRA_TU_DO BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND HA.IS_DELETED = 0
           AND LL.IS_DELETED = 0
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
        UNION ALL
        SELECT HTHA.PHAM_NHAN_ID AS ID, CAST(HTHA.NGAY_HOAN AS DATE) AS EVENT_DATE
          FROM HOAN_THI_HANH_ANS HTHA
                   JOIN PN_LAI_LICHS LL ON LL.ID = HTHA.PHAM_NHAN_ID
                   JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
         WHERE HTHA.NGAY_HOAN BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND HTHA.IS_DELETED = 0
           AND LL.IS_DELETED = 0
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
           AND NOT EXISTS (SELECT 1
                           FROM TRICH_XUATS TX
                                    JOIN QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS LDTX
                                         ON LDTX.ID = TX.TX_LOAI_LENH_ID AND LDTX.IS_DELETED = 0
                                    JOIN PN_THI_HANH_AN THA2
                                         ON LL.ID = THA2.THA_PNLAI_LICH_ID AND THA2.IS_DELETED = 0
                          WHERE TX.PHAM_NHAN_ID = HTHA.PHAM_NHAN_ID
                            AND TX.IS_DELETED = 0
                            AND LDTX.LQDTX_MA = '1'
                            AND (TX.TX_NGAY_TRA IS NULL OR TX.TX_NGAY_TRA >= V_DEN_NGAY + 1)
                            AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
                            AND TX.TX_NGAY_TRICH_XUAT >= THA2.THA_NGAY_DEN_TRAI)
        UNION ALL
        SELECT MHP.PN_LAI_LICH_ID AS ID, CAST(MHP.MHP_NGAY_TU_DO AS DATE) AS EVENT_DATE
          FROM MIEN_HINH_PHATS MHP
                   JOIN PN_LAI_LICHS LL ON LL.ID = MHP.PN_LAI_LICH_ID
                   JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
         WHERE MHP.MHP_NGAY_TU_DO BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND MHP.IS_DELETED = 0
           AND LL.IS_DELETED = 0
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
        UNION ALL
        SELECT CB.PHAM_NHAN_ID AS ID, CAST(CB.NGAY_BAT_DAU AS DATE) AS EVENT_DATE
          FROM CHUA_BENH_BAT_BUOCS CB
                   JOIN PN_LAI_LICHS LL ON LL.ID = CB.PHAM_NHAN_ID
                   JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
         WHERE CB.NGAY_BAT_DAU BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND CB.IS_DELETED = 0
           AND LL.IS_DELETED = 0
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
        UNION ALL
        SELECT CG.PNCG_LAI_LICH_ID AS ID, CAST(CG.PNCG_NGAY_CHUYEN_GIAO AS DATE) AS EVENT_DATE
          FROM PN_CHUYEN_GIAO CG
                   JOIN PN_LAI_LICHS LL ON LL.ID = CG.PNCG_LAI_LICH_ID
                   JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
                   LEFT JOIN DM_QUOC_TICHS QT ON QT.ID = CG.PNCG_NUOC_CHUYEN_GIAO_ID
         WHERE CG.PNCG_NGAY_CHUYEN_GIAO BETWEEN P_TU_NGAY AND V_DEN_NGAY
           AND NVL(QT.QT_MA, '000') <> '250'
           AND CG.IS_DELETED = 0
           AND LL.IS_DELETED = 0
           AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
    ),
    ALL_TANG_RAW AS (
        SELECT ID, EVENT_DATE FROM RAW_C2 UNION ALL
        SELECT ID, EVENT_DATE FROM RAW_C4 UNION ALL
        SELECT ID, EVENT_DATE FROM RAW_C5 UNION ALL
        SELECT ID, EVENT_DATE FROM RAW_C6 UNION ALL
        SELECT ID, EVENT_DATE FROM RAW_C7
    ),
    ALL_GIAM_RAW AS (
        SELECT ID, EVENT_DATE FROM RAW_C9  UNION ALL
        SELECT ID, EVENT_DATE FROM RAW_C10 UNION ALL
        SELECT ID, EVENT_DATE FROM RAW_C11 UNION ALL
        SELECT ID, EVENT_DATE FROM RAW_C12 UNION ALL
        SELECT ID, EVENT_DATE FROM RAW_C13 UNION ALL
        SELECT ID, EVENT_DATE FROM RAW_C14 UNION ALL
        SELECT ID, EVENT_DATE FROM RAW_C15
    ),
    C2_GUARDED AS (
        SELECT T.ID FROM RAW_C2 T
         WHERE NOT EXISTS (SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                            WHERE ctt.PN_LAI_LICH_ID = T.ID AND ctt.NGAY_XET = P_TU_NGAY - 1
                              AND ctt.TTPN_MA IN ('111', '112', '113', '114'))
            OR EXISTS (SELECT 1 FROM ALL_GIAM_RAW g WHERE g.ID = T.ID AND g.EVENT_DATE <= T.EVENT_DATE)
    ),
    C4_GUARDED AS (
        SELECT T.ID FROM RAW_C4 T
         WHERE NOT EXISTS (SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                            WHERE ctt.PN_LAI_LICH_ID = T.ID AND ctt.NGAY_XET = P_TU_NGAY - 1
                              AND ctt.TTPN_MA IN ('111', '112', '113', '114'))
            OR EXISTS (SELECT 1 FROM ALL_GIAM_RAW g WHERE g.ID = T.ID AND g.EVENT_DATE <= T.EVENT_DATE)
    ),
    C5_GUARDED AS (
        SELECT T.ID FROM RAW_C5 T
         WHERE NOT EXISTS (SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                            WHERE ctt.PN_LAI_LICH_ID = T.ID AND ctt.NGAY_XET = P_TU_NGAY - 1
                              AND ctt.TTPN_MA IN ('111', '112', '113', '114'))
            OR EXISTS (SELECT 1 FROM ALL_GIAM_RAW g WHERE g.ID = T.ID AND g.EVENT_DATE <= T.EVENT_DATE)
    ),
    C6_GUARDED AS (
        SELECT T.ID FROM RAW_C6 T
         WHERE NOT EXISTS (SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                            WHERE ctt.PN_LAI_LICH_ID = T.ID AND ctt.NGAY_XET = P_TU_NGAY - 1
                              AND ctt.TTPN_MA IN ('111', '112', '113', '114'))
            OR EXISTS (SELECT 1 FROM ALL_GIAM_RAW g WHERE g.ID = T.ID AND g.EVENT_DATE <= T.EVENT_DATE)
    ),
    C7_GUARDED AS (
        SELECT T.ID FROM RAW_C7 T
         WHERE NOT EXISTS (SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                            WHERE ctt.PN_LAI_LICH_ID = T.ID AND ctt.NGAY_XET = P_TU_NGAY - 1
                              AND ctt.TTPN_MA IN ('111', '112', '113', '114'))
            OR EXISTS (SELECT 1 FROM ALL_GIAM_RAW g WHERE g.ID = T.ID AND g.EVENT_DATE <= T.EVENT_DATE)
    ),
    C9_GUARDED AS (
        SELECT G.ID FROM RAW_C9 G
         WHERE EXISTS (SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                        WHERE ctt.PN_LAI_LICH_ID = G.ID AND ctt.NGAY_XET = P_TU_NGAY - 1
                          AND ctt.TTPN_MA IN ('111', '112', '113', '114'))
            OR EXISTS (SELECT 1 FROM ALL_TANG_RAW t WHERE t.ID = G.ID AND t.EVENT_DATE <= G.EVENT_DATE)
    ),
    C10_GUARDED AS (
        SELECT G.ID FROM RAW_C10 G
         WHERE EXISTS (SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                        WHERE ctt.PN_LAI_LICH_ID = G.ID AND ctt.NGAY_XET = P_TU_NGAY - 1
                          AND ctt.TTPN_MA IN ('111', '112', '113', '114'))
            OR EXISTS (SELECT 1 FROM ALL_TANG_RAW t WHERE t.ID = G.ID AND t.EVENT_DATE <= G.EVENT_DATE)
    ),
    C11_GUARDED AS (
        SELECT G.ID FROM RAW_C11 G
         WHERE EXISTS (SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                        WHERE ctt.PN_LAI_LICH_ID = G.ID AND ctt.NGAY_XET = P_TU_NGAY - 1
                          AND ctt.TTPN_MA IN ('111', '112', '113', '114'))
            OR EXISTS (SELECT 1 FROM ALL_TANG_RAW t WHERE t.ID = G.ID AND t.EVENT_DATE <= G.EVENT_DATE)
    ),
    C12_GUARDED AS (
        SELECT G.ID FROM RAW_C12 G
         WHERE EXISTS (SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                        WHERE ctt.PN_LAI_LICH_ID = G.ID AND ctt.NGAY_XET = P_TU_NGAY - 1
                          AND ctt.TTPN_MA IN ('111', '112', '113', '114'))
            OR EXISTS (SELECT 1 FROM ALL_TANG_RAW t WHERE t.ID = G.ID AND t.EVENT_DATE <= G.EVENT_DATE)
    ),
    C13_GUARDED AS (
        SELECT G.ID FROM RAW_C13 G
         WHERE EXISTS (SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                        WHERE ctt.PN_LAI_LICH_ID = G.ID AND ctt.NGAY_XET = P_TU_NGAY - 1
                          AND ctt.TTPN_MA IN ('111', '112', '113', '114'))
            OR EXISTS (SELECT 1 FROM ALL_TANG_RAW t WHERE t.ID = G.ID AND t.EVENT_DATE <= G.EVENT_DATE)
    ),
    C14_GUARDED AS (
        SELECT G.ID FROM RAW_C14 G
         WHERE EXISTS (SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                        WHERE ctt.PN_LAI_LICH_ID = G.ID AND ctt.NGAY_XET = P_TU_NGAY - 1
                          AND ctt.TTPN_MA IN ('111', '112', '113', '114'))
            OR EXISTS (SELECT 1 FROM ALL_TANG_RAW t WHERE t.ID = G.ID AND t.EVENT_DATE <= G.EVENT_DATE)
    ),
    C15_GUARDED AS (
        SELECT G.ID FROM RAW_C15 G
         WHERE EXISTS (SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                        WHERE ctt.PN_LAI_LICH_ID = G.ID AND ctt.NGAY_XET = P_TU_NGAY - 1
                          AND ctt.TTPN_MA IN ('111', '112', '113', '114'))
            OR EXISTS (SELECT 1 FROM ALL_TANG_RAW t WHERE t.ID = G.ID AND t.EVENT_DATE <= G.EVENT_DATE)
    ),
    ALL_GUARDED AS (
        SELECT 'C2'  AS COL FROM C2_GUARDED  UNION ALL
        SELECT 'C4'  AS COL FROM C4_GUARDED  UNION ALL
        SELECT 'C5'  AS COL FROM C5_GUARDED  UNION ALL
        SELECT 'C6'  AS COL FROM C6_GUARDED  UNION ALL
        SELECT 'C7'  AS COL FROM C7_GUARDED  UNION ALL
        SELECT 'C9'  AS COL FROM C9_GUARDED  UNION ALL
        SELECT 'C10' AS COL FROM C10_GUARDED UNION ALL
        SELECT 'C11' AS COL FROM C11_GUARDED UNION ALL
        SELECT 'C12' AS COL FROM C12_GUARDED UNION ALL
        SELECT 'C13' AS COL FROM C13_GUARDED UNION ALL
        SELECT 'C14' AS COL FROM C14_GUARDED UNION ALL
        SELECT 'C15' AS COL FROM C15_GUARDED
    )
    SELECT
        NVL(SUM(CASE WHEN COL = 'C2'  THEN 1 END), 0),
        NVL(SUM(CASE WHEN COL = 'C4'  THEN 1 END), 0),
        NVL(SUM(CASE WHEN COL = 'C5'  THEN 1 END), 0),
        NVL(SUM(CASE WHEN COL = 'C6'  THEN 1 END), 0),
        NVL(SUM(CASE WHEN COL = 'C7'  THEN 1 END), 0),
        NVL(SUM(CASE WHEN COL = 'C9'  THEN 1 END), 0),
        NVL(SUM(CASE WHEN COL = 'C10' THEN 1 END), 0),
        NVL(SUM(CASE WHEN COL = 'C11' THEN 1 END), 0),
        NVL(SUM(CASE WHEN COL = 'C12' THEN 1 END), 0),
        NVL(SUM(CASE WHEN COL = 'C13' THEN 1 END), 0),
        NVL(SUM(CASE WHEN COL = 'C14' THEN 1 END), 0),
        NVL(SUM(CASE WHEN COL = 'C15' THEN 1 END), 0)
    INTO
        COLV(2), COLV(4), COLV(5), COLV(6), COLV(7),
        COLV(9), COLV(10), COLV(11), COLV(12), COLV(13), COLV(14), COLV(15)
    FROM ALL_GUARDED;

    L_RESULT.EXTEND; L_RESULT(L_RESULT.COUNT) := O_PT80(2, u'Tr\1ea1i t\1ea1m giam chuy\1ec3n \0111\1ebfn', COLV(2));
    L_RESULT.EXTEND; L_RESULT(L_RESULT.COUNT) := O_PT80(3, u'Tr\1ea1i giam kh\00e1c chuy\1ec3n \0111\1ebfn', COLV(3));
    L_RESULT.EXTEND; L_RESULT(L_RESULT.COUNT) := O_PT80(4, u'Tr\1ed1n b\1eaft l\1ea1i', COLV(4));
    L_RESULT.EXTEND; L_RESULT(L_RESULT.COUNT) := O_PT80(5, u'T\1ea1m \0111\00ecnh ch\1ec9 tr\1ea3 l\1ea1i', COLV(5));
    L_RESULT.EXTEND; L_RESULT(L_RESULT.COUNT) := O_PT80(6, u'Tr\00edch xu\1ea5t tr\1ea3 l\1ea1i', COLV(6));
    L_RESULT.EXTEND; L_RESULT(L_RESULT.COUNT) := O_PT80(7, u'T\0103ng kh\00e1c', COLV(7));

    -- C8: Cong tang
    L_RESULT.EXTEND;
    COLV(8) := COLV(2) + COLV(3) + COLV(4) + COLV(5) + COLV(6) + COLV(7);
    L_RESULT(L_RESULT.COUNT) := O_PT80(8, u'C\1ed9ng', COLV(8));

    -- ============================ GIAM PHAM NHAN ============================

    L_RESULT.EXTEND; L_RESULT(L_RESULT.COUNT) := O_PT80(9, u'Tha', COLV(9));
    L_RESULT.EXTEND; L_RESULT(L_RESULT.COUNT) := O_PT80(10, u'Tr\1ed1n', COLV(10));
    L_RESULT.EXTEND; L_RESULT(L_RESULT.COUNT) := O_PT80(11, u'Ch\1ebft', COLV(11));
    L_RESULT.EXTEND; L_RESULT(L_RESULT.COUNT) := O_PT80(12, u'Tr\00edch xu\1ea5t', COLV(12));
    L_RESULT.EXTEND; L_RESULT(L_RESULT.COUNT) := O_PT80(13, u'T\1ea1m \0111\00ecnh ch\1ec9', COLV(13));
    L_RESULT.EXTEND; L_RESULT(L_RESULT.COUNT) := O_PT80(14, u'Chuy\1ec3n tr\1ea1i', COLV(14));
    L_RESULT.EXTEND; L_RESULT(L_RESULT.COUNT) := O_PT80(15, u'Gi\1ea3m kh\00e1c', COLV(15));

    -- C16: Cong giam
    L_RESULT.EXTEND;
    COLV(16) := COLV(9) + COLV(10) + COLV(11) + COLV(12) + COLV(13) + COLV(14) + COLV(15);
    L_RESULT(L_RESULT.COUNT) := O_PT80(16, u'C\1ed9ng', COLV(16));

    -- ===================================================================
    -- C17..C60: G?P TOÀN B? THÀNH M?T L?N QUÉT TK_PT80 (t?i ?u hi?u n?ng)
    -- ===================================================================

    -- C?p phát s?n các ph?n t? 17..60 ?? gán theo index
    FOR k IN 17..61 LOOP
        L_RESULT.EXTEND;
    END LOOP;

    SELECT
        COUNT(CASE WHEN LL.MA_GIOI_TINH = '1' THEN 1 END),                              -- 17
        COUNT(CASE WHEN LL.MA_GIOI_TINH = '2' THEN 1 END),                              -- 18
        COUNT(CASE WHEN LL.MA_GIOI_TINH = '3' THEN 1 END),                              -- 19
        COUNT(*),                                                                       -- 20
        COUNT(CASE WHEN LL.CHUONG_TD = '13' THEN 1 END),                                -- 21
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1123', '093')  THEN 1 END),                             -- 22 Giet nguoi
        COUNT(CASE WHEN REGEXP_SUBSTR(LL.MA_TOI_DANH, '^[0-9]+') IN ('104','106','1134','1136') THEN 1 END), -- 23 Co y gay thuong tich: Dieu 104/134 (goc) + Dieu 106/136 (vuot qua gioi han phong ve chinh dang / vuot qua muc can thiet khi bat giu) - khop theo ma goc, gom ca bien the "gay thuong tich" lan "ton hai suc khoe"
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('111', '1141', '1142a')  THEN 1 END),                   -- 24 Hiep dam (1142a = "doi voi nguoi tu du 16 den duoi 18 tuoi" la tinh tiet dinh khung cua Dieu 141, khong phai Dieu 142 "duoi 16 tuoi" -> chuyen tu cot 25 sang day)
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('112a', '1142') THEN 1 END),                            -- 25 Hiep dam nguoi duoi 16 tuoi
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1151', '120a') THEN 1 END),                 -- 26 Mua ban nguoi duoi 16 tuoi (+ 120a: ma cu)
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1168', '1171', '133', '136') THEN 1 END),   -- 28 Cuop, Cuop giat (+ 133/136: ma cu)
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1173', '138') THEN 1 END),                            -- 29 Trom cap
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1175', '140') THEN 1 END),                            -- 30 Lam dung tin nhiem chiem doat tai san
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1174', '139') THEN 1 END),                            -- 31 Lua dao chiem doat tai san
        COUNT(CASE WHEN LL.CHUONG_TD = '14' THEN 1 END),                                -- n?n cho 27
        COUNT(CASE WHEN LL.CHUONG_TD = '16' THEN 1 END),                                -- n?n cho 32
        COUNT(CASE WHEN LL.CHUONG_TD = '18' THEN 1 END),                                -- 33 cac toi xp trat tu qlkt
        COUNT(CASE WHEN LL.CHUONG_TD = '20' THEN 1 END),                                -- 34 cac toi ma tuy
        COUNT(CASE WHEN REGEXP_SUBSTR(LL.MA_TOI_DANH, '^[0-9]+') IN
                            ('1285','1286','1287','1288','1289',
                             '1290','1291','1292','1293','1294')
                   THEN 1 END),                                                         -- 35 cac toi ve cntt, mvt (khop theo ma goc, tu dong bao gom cac bien the hau to a/b/c/...)
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1321','1322','1322a','248','249','249a') THEN 1 END), -- 36 cac toi danh bac (+ 1322a/248/249/249a)
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1327','1328','1329','254','255','256') THEN 1 END),   -- 37 cac toi mai dam (+ 254/255/256: ma cu)
        COUNT(CASE WHEN LL.CHUONG_TD = '21' THEN 1 END),                                -- n?n cho 38
        COUNT(CASE WHEN LL.CHUONG_TD = '22' THEN 1 END),                                -- 39 cac toi xam pham trat tu qlhc
        COUNT(CASE WHEN LL.CHUONG_TD = '23' THEN 1 END),                                -- 40 cac toi chuc vu
        COUNT(CASE WHEN LL.CHUONG_TD = '24' THEN 1 END),                                -- 41 cac toi xam pham hoat dong tu phap
        COUNT(CASE WHEN LL.MUC_AN_NGAY IS NULL THEN 1 END),                             -- 43 chung than
        COUNT(CASE WHEN LL.MUC_AN_NGAY BETWEEN 15*12*30+1 AND 30*12*30 THEN 1 END),     -- 44 (15 - 30] nam
        COUNT(CASE WHEN LL.MUC_AN_NGAY BETWEEN 7*12*30+1  AND 15*12*30 THEN 1 END),     -- 45 (7-15] nam
        COUNT(CASE WHEN LL.MUC_AN_NGAY BETWEEN 3*12*30+1  AND 7*12*30  THEN 1 END),     -- 46 (3-7] nam
        COUNT(CASE WHEN LL.MUC_AN_NGAY BETWEEN 1          AND 3*12*30  THEN 1 END),     -- 47 (0, 3] nam
        COUNT(CASE WHEN NAM_PHAM_TOI - NAM_SINH
                        BETWEEN 14 AND 16 - 0.01 THEN 1 END),                     -- 48 14-16tuoi luc pham toi
        COUNT(CASE WHEN NAM_PHAM_TOI - NAM_SINH
                        BETWEEN 16 AND 18 - 0.01 THEN 1 END),                     -- 49 16-18 tuoi luc pham toi
        COUNT(CASE WHEN V_NAM_HIEN_TAI - NAM_SINH
                        < 18 THEN 1 END),                                            -- 50 duoi 18 tuoi
        COUNT(CASE WHEN V_NAM_HIEN_TAI - NAM_SINH
                        BETWEEN 18 AND 30 - 0.01 THEN 1 END),                     -- 51 18-30 tuoi
        COUNT(CASE WHEN V_NAM_HIEN_TAI - NAM_SINH
                        BETWEEN 30 AND 45 - 0.01 THEN 1 END),                     -- 52 30-45 tuoi
        COUNT(CASE WHEN V_NAM_HIEN_TAI - NAM_SINH
                        BETWEEN 45 AND 60 - 0.01 THEN 1 END),                     -- 53 45-60 tuoi
        COUNT(CASE WHEN V_NAM_HIEN_TAI - NAM_SINH BETWEEN 60 AND 69 THEN 1 END),  -- 60-69 tuoi
        COUNT(CASE WHEN V_NAM_HIEN_TAI - NAM_SINH >= 70 THEN 1 END),              -- 70 tuoi
        COUNT(CASE WHEN NVL(LL.MA_TAI_PHAM,'0') = '1' THEN 1 END),                      -- 56 tai pham
        COUNT(CASE WHEN NVL(LL.MA_TAI_PHAM,'0') = '2' THEN 1 END),                      -- 57 tai pham nguy hiem
        COUNT(CASE WHEN LL.MA_QUOC_TICH <> '250' THEN 1 END),                           -- 58 quoc tich vn
        COUNT(CASE WHEN LL.MA_TON_GIAO  <> '9999' OR LL.MA_TON_GIAO IS NULL THEN 1 END),                           -- 59 co ton giao
        COUNT(CASE WHEN LL.MA_DAN_TOC NOT IN ('01', '55') THEN 1 END),               -- 60 dan toc thieu so
        COUNT(CASE WHEN LL.MA_HOC_VAN = '100' THEN 1 END)                               -- 61 
    INTO
        COLV(17), COLV(18), COLV(19), COLV(20), COLV(21),
        COLV(22), COLV(23), COLV(24), COLV(25), COLV(26),
        COLV(28), COLV(29), COLV(30), COLV(31),
        TS_TMP,            -- TD_CHUONG = '14'
        L_TMP_CH16,        -- TD_CHUONG = '16'
        COLV(33), COLV(34), COLV(35), COLV(36), COLV(37),
        L_TMP_CH21,        -- TD_CHUONG = '21'
        COLV(39), COLV(40), COLV(41),
        COLV(43), COLV(44), COLV(45), COLV(46), COLV(47),
        COLV(48), COLV(49), COLV(50), COLV(51), COLV(52),
        COLV(53), COLV(54), COLV(55), COLV(56), COLV(57),
        COLV(58), COLV(59), COLV(60), COLV(61)
    FROM TK_PT80 LL
    LEFT JOIN DM_TOI_DANHS TD ON TD.TD_MA = LL.MA_TOI_DANH;

    -- Các c?t d?n xu?t (không c?n quét b?ng thêm)
    COLV(27) := TS_TMP     - (COLV(24) + COLV(23) + COLV(22) + COLV(25) + COLV(26));
    COLV(32) := L_TMP_CH16 - (COLV(30) + COLV(29) + COLV(28) + COLV(31));
    COLV(38) := L_TMP_CH21 - (COLV(35) + COLV(36) + COLV(37));
    COLV(42) := COLV(20) - (COLV(21) + COLV(22) + COLV(23) + COLV(24) + COLV(25)
        + COLV(26) + COLV(27) + COLV(28) + COLV(29) + COLV(30)
        + COLV(31) + COLV(32) + COLV(33) + COLV(34) + COLV(35)
        + COLV(36) + COLV(37) + COLV(38) + COLV(39) + COLV(40) + COLV(41));

    -- N?p C17..C60 vào L_RESULT theo index (?úng nhãn c?)
    L_RESULT(17) := O_PT80(17, u'Nam', COLV(17));
    L_RESULT(18) := O_PT80(18, u'N\1eef', COLV(18));
    L_RESULT(19) := O_PT80(19, u'Gi\1edbi t\00ednh kh\00e1c', COLV(19));
    L_RESULT(20) := O_PT80(20, u'C\1ed9ng', COLV(20));
    L_RESULT(21) := O_PT80(21, u'T\1ed5ng c\00e1c t\1ed9i XP ANQG', COLV(21));
    L_RESULT(22) := O_PT80(22, u'C\00e1c t\1ed9i gi\1ebft ng\01b0\1eddi', COLV(22));
    L_RESULT(23) := O_PT80(23, u'C\00e1c t\1ed9i c\1ed1 \00fd g\00e2y th\01b0\01a1ng t\00edch', COLV(23));
    L_RESULT(24) := O_PT80(24, u'Hi\1ebfp d\00e2m', COLV(24));
    L_RESULT(25) := O_PT80(25, u'Hi\1ebfp d\00e2m ng\01b0\1eddi d\01b0\1edbi 16 tu\1ed5i', COLV(25));
    L_RESULT(26) := O_PT80(26, u'Mua b\00e1n ng\01b0\1eddi d\01b0\1edbi 16 tu\1ed5i', COLV(26));
    L_RESULT(27) := O_PT80(27, u'C\00e1c t\1ed9i kh\00e1c c\00f2n l\1ea1i v\1ec1 XP TM,SK con ng\01b0\1eddi', COLV(27));
    L_RESULT(28) := O_PT80(28, u'C\01b0\1edbp, c\01b0\1edbp gi\1eadt', COLV(28));
    L_RESULT(29) := O_PT80(29, u'Tr\1ed9m c\1eafp t\00e0i s\1ea3n', COLV(29));
    L_RESULT(30) := O_PT80(30, u'L\1ea1m d\1ee5ng t\00edn nhi\1ec7m chi\1ebfm \0111o\1ea1t t\00e0i s\1ea3n', COLV(30));
    L_RESULT(31) := O_PT80(31, u'L\1eeba \0111\1ea3o chi\1ebfm \0111o\1ea1t t\00e0i s\1ea3n', COLV(31));
    L_RESULT(32) := O_PT80(32, u'C\00e1c t\1ed9i kh\00e1c c\00f2n l\1ea1i v\1ec1 XPSH', COLV(32));
    L_RESULT(33) := O_PT80(33, u'C\00e1c t\1ed9i x\00e2m ph\1ea1m TTQL KT', COLV(33));
    L_RESULT(34) := O_PT80(34, u'C\00e1c t\1ed9i v\1ec1 ma t\00fay', COLV(34));
    L_RESULT(35) := O_PT80(35, u'C\00e1c t\1ed9i CNTT, m\1ea1ng vi\1ec5n th\00f4ng', COLV(35));
    L_RESULT(36) := O_PT80(36, u'C\00e1c t\1ed9i v\1ec1 \0111\00e1nh b\1ea1c', COLV(36));
    L_RESULT(37) := O_PT80(37, u'C\00e1c t\1ed9i v\1ec1 m\1ea1i d\00e2m', COLV(37));
    L_RESULT(38) := O_PT80(38, u'C\00e1c t\1ed9i kh\00e1c c\00f2n l\1ea1i An to\00e0n c\00f4ng c\1ed9ng, tr\1eadt t\1ef1 c\00f4ng c\1ed9ng', COLV(38));
    L_RESULT(39) := O_PT80(39, u'C\00e1c t\1ed9i qu\1ea3n l\00fd h\00e0nh ch\00ednh', COLV(39));
    L_RESULT(40) := O_PT80(40, u'C\00e1c t\1ed9i v\1ec1 ch\1ee9c v\1ee5', COLV(40));
    L_RESULT(41) := O_PT80(41, u'C\00e1c t\1ed9i v\1ec1 t\01b0 ph\00e1p', COLV(41));
    L_RESULT(42) := O_PT80(42, u'C\00e1c t\1ed9i \1edf c\00e1c ch\01b0\01a1ng kh\00e1c c\00f2n l\1ea1i', COLV(42));
    L_RESULT(43) := O_PT80(43, u'Chung th\00e2n', COLV(43));
    L_RESULT(44) := O_PT80(44, u'T\1eeb tr\00ean 15 n\0103m \0111\1ebfn 30 n\0103m', COLV(44));
    L_RESULT(45) := O_PT80(45, u'T\1eeb tr\00ean 7 n\0103m \0111\1ebfn 15 n\0103m', COLV(45));
    L_RESULT(46) := O_PT80(46, u'T\1eeb tr\00ean 3 n\0103m \0111\1ebfn 7 n\0103m', COLV(46));
    L_RESULT(47) := O_PT80(47, u'T\1eeb 3 tr\1edf n\0103m xu\1ed1ng', COLV(47));
    L_RESULT(48) := O_PT80(48, u'T\1eeb 14t \0111\1ebfn d\01b0\1edbi 16 tu\1ed5i', COLV(48));
    L_RESULT(49) := O_PT80(49, u'T\1eeb 16t \0111\1ebfn d\01b0\1edbi 18 tu\1ed5i', COLV(49));
    L_RESULT(50) := O_PT80(50, u'D\01b0\1edbi 18 tu\1ed5i', COLV(50));
    L_RESULT(51) := O_PT80(51, u'T\1eeb 18t \0111\1ebfn d\01b0\1edbi 30 tu\1ed5i', COLV(51));
    L_RESULT(52) := O_PT80(52, u'T\1eeb 30t \0111\1ebfn d\01b0\1edbi 45 tu\1ed5i', COLV(52));
    L_RESULT(53) := QLPN.O_PT80(53, u'T\1eeb 45t \0111\1ebfn d\01b0\1edbi 60 tu\1ed5i', COLV(53));
    L_RESULT(54) := QLPN.O_PT80(54, u'T\1eeb 60t \0111\1ebfn d\01b0\1edbi 70 tu\1ed5i', COLV(54));
    L_RESULT(55) := QLPN.O_PT80(55, u'Tr\00ean 70 tu\1ed5i', COLV(55));
    L_RESULT(56) := QLPN.O_PT80(56, u'T\00e1i ph\1ea1m', COLV(56));
    L_RESULT(57) := QLPN.O_PT80(57, u'T\00e1i ph\1ea1m nguy hi\1ec3m', COLV(57));
    L_RESULT(58) := QLPN.O_PT80(58, u'N\01b0\1edbc ngo\00e0i', COLV(58));
    L_RESULT(59) := QLPN.O_PT80(59, u'T\00f4n gi\00e1o', COLV(59));
    L_RESULT(60) := QLPN.O_PT80(60, u'D\00e2n t\1ed9c \00edt ng\01b0\1eddi', COLV(60));
    L_RESULT(61) := QLPN.O_PT80(61, u'Kh\00f4ng bi\1ebft ch\1eef', COLV(61));

    -- ===================================================================
    -- C61..C63: con ph?m nhân (join THAN_NHAN_CON_CAIS - quan h? 1-nhi?u,
    -- gi? riêng ?? tránh nhân dòng). G?p 3 c?t vào 1 l?n quét.
    -- L?u ý: c?t 61 gi? ?i?u ki?n g?c (NGAY_DEN IS NULL OR NGAY_DEN <= V_DEN_NGAY),
    -- c?t 62/63 ch? NGAY_DEN <= V_DEN_NGAY.
    -- ===================================================================
    SELECT
        COUNT(CASE WHEN (CP.NGAY_DEN IS NULL OR CP.NGAY_DEN <= V_DEN_NGAY)
                        AND (V_NAM_HIEN_TAI
                             - TO_NUMBER(SUBSTR(CP.NGAY_SINH,-4))) < 2  THEN 1 END), -- 62
        COUNT(CASE WHEN CP.NGAY_DEN <= V_DEN_NGAY
                        AND (V_NAM_HIEN_TAI
                             - TO_NUMBER(SUBSTR(CP.NGAY_SINH,-4))) = 2  THEN 1 END), -- 63
        COUNT(CASE WHEN CP.NGAY_DEN <= V_DEN_NGAY
                        AND (V_NAM_HIEN_TAI
                             - TO_NUMBER(SUBSTR(CP.NGAY_SINH,-4))) >= 3 THEN 1 END)  -- 64
    INTO COLV(62), COLV(63), COLV(64)
    FROM TK_PT80 LL
    JOIN THAN_NHAN_CON_CAIS CP ON CP.PHAM_NHAN_ID = LL.PN_LAI_LICH_ID AND CP.IS_DELETED = 0
    WHERE NVL(CP.NGAY_RA, V_DEN_NGAY + 1) > V_DEN_NGAY
      AND CP.NGAY_SINH IS NOT NULL
      AND CP.IS_DELETED = 0;

    L_RESULT.EXTEND;
    L_RESULT(L_RESULT.COUNT) := O_PT80(62, u'Con PN d\01b0\1edbi 24 th\00e1ng', COLV(62));
    L_RESULT.EXTEND;
    L_RESULT(L_RESULT.COUNT) := O_PT80(63, u'Con PN d\01b0\1edbi t\1eeb 24 \0111\1ebfn d\01b0\1edbi 36 th\00e1ng', COLV(63));
    L_RESULT.EXTEND;
    L_RESULT(L_RESULT.COUNT) := O_PT80(64, u'T\1eeb 36 th\00e1ng tr\1edf l\00ean', COLV(64));

    -- ===================================================================
    -- C1 = C20 - C8 + C16 (tính sau cùng, c?p nh?t vào ph?n t? index 1)
    -- ===================================================================
    COLV(1) := COLV(20) - COLV(8) + COLV(16);
    L_RESULT(1) := O_PT80(1, u'S\1ed1 th\00e1ng tr\01b0\1edbc chuy\1ec3n sang', COLV(1));

    OPEN L_CUR FOR
        SELECT *
        FROM (SELECT STT, SL
              FROM TABLE (L_RESULT))
            PIVOT (
            MAX(SL) FOR STT IN (
                1 AS "1", 2 AS "2", 3 AS "3", 4 AS "4", 5 AS "5",
                6 AS "6", 7 AS "7", 8 AS "8", 9 AS "9", 10 AS "10",
                11 AS "11", 12 AS "12", 13 AS "13", 14 AS "14", 15 AS "15",
                16 AS "16", 17 AS "17", 18 AS "18", 19 AS "19", 20 AS "20",
                21 AS "21", 22 AS "22", 23 AS "23", 24 AS "24", 25 AS "25",
                26 AS "26", 27 AS "27", 28 AS "28", 29 AS "29", 30 AS "30",
                31 AS "31", 32 AS "32", 33 AS "33", 34 AS "34", 35 AS "35",
                36 AS "36", 37 AS "37", 38 AS "38", 39 AS "39", 40 AS "40",
                41 AS "41", 42 AS "42", 43 AS "43", 44 AS "44", 45 AS "45",
                46 AS "46", 47 AS "47", 48 AS "48", 49 AS "49", 50 AS "50",
                51 AS "51", 52 AS "52", 53 AS "53", 54 AS "54", 56 AS "55",
                57 AS "56", 58 AS "57", 59 AS "58", 60 AS "59", 61 AS "60",
                62 AS "61", 63 AS "62", 64 AS "63", 54 AS "64", 55 AS "65"
                )
            );

    DBMS_SQL.RETURN_RESULT(L_CUR);

    COMMIT;
END SP_GET_PT80;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PT80_B
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PT80_B" (
    P_TU_NGAY IN DATE,
    P_DEN_NGAY IN DATE,
    P_MA_TRAI_GIAM IN NVARCHAR2 DEFAULT NULL
) IS
    -- ================================================================
    -- Báo cáo PT80b (Th?ng kê tháng) - BH theo TT 74/2026/TT-BCA.
    -- Khung store d?ng theo SP_GET_PT80: gi? nguyên tham s? + cách tr?
    -- d? li?u (pivot -> DBMS_SQL.RETURN_RESULT), ch? khác 26 c?t.
    --
    -- B? c?c 26 c?t:
    --   C1..C8  : Ph?n I (b? can, b? cáo t?m giam/t?m gi?) - ch?a có
    --             nghi?p v? -> tr? NULL.
    --   C9      : S? tháng tr??c chuy?n sang = C26 - C14 + C21 (??u k?).
    --   C10     : PN trích xu?t tr?i khác v? = PT80.C2 + PT80.C3 (ngo?i l?,
    --             t?m l?y s? "tr?i t?m giam + tr?i giam khác chuy?n ??n").
    --   C11..C13: = PT80.C4, C5, C6.
    --   C14     : C?ng t?ng = C10+C11+C12+C13.
    --   C15..C20: = PT80.C9, C10, C11, C12, C13, C14.
    --   C21     : C?ng gi?m = C15+..+C20.
    --   C22     : Án <= 5 n?m (MUC_AN_NGAY 1..5*12*30).
    --   C23     : Án > 5 n?m  (MUC_AN_NGAY > 5*12*30 ho?c NULL - chung thân).
    --   C24     : Nam ; C25 : N? ; C26 : T?ng s? (COUNT(*)).
    --   Cân ??i: C26 = C22+C23 = C24+C25 = C9+C14-C21.
    -- ================================================================
    I               NUMBER;
    TS_TMP          NUMBER;
    TYPE COLVAL IS TABLE OF NUMBER(10) INDEX BY BINARY_INTEGER;
    COLV            COLVAL;
    V_TRAI_GIAM_ID  NUMBER;
    V_DEN_NGAY      DATE;
    V_DEN_NGAY_EXCL DATE;
    L_RESULT        T_PT80;
    L_CUR           SYS_REFCURSOR;
BEGIN
    IF P_MA_TRAI_GIAM IS NOT NULL THEN
        BEGIN
            SELECT ID
            INTO V_TRAI_GIAM_ID
            FROM DM_TRAI_GIAMS
            WHERE TG_MA = P_MA_TRAI_GIAM
              AND IS_DELETED = 0
              AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN V_TRAI_GIAM_ID := -1;
        END;
    END IF;

    V_DEN_NGAY := LEAST(
            CAST(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh' AS DATE),
            P_DEN_NGAY);
    V_DEN_NGAY_EXCL := V_DEN_NGAY + 1;

    SP_POPULATE_TK_PT80_ALT(V_DEN_NGAY, V_TRAI_GIAM_ID);

    L_RESULT := T_PT80();

    -- C?p phát s?n 26 ph?n t? ?? gán theo index.
    FOR k IN 1..26 LOOP
        L_RESULT.EXTEND;
    END LOOP;

    -- ============================ PH?N I (C1..C8) ============================
    -- Ch?a có nghi?p v? -> tr? NULL (SL = NULL).
    L_RESULT(1) := O_PT80(1, u'\0110\1ed1i t\01b0\1ee3ng b\1ecb t\1ea1m gi\1eef', NULL);
    L_RESULT(2) := O_PT80(2, u'B\1ecb can, b\1ecb c\00e1o \0111ang t\1ea1m giam', NULL);
    L_RESULT(3) := O_PT80(3, u'S\1ed1 ng\01b0\1eddi c\00f3 \00e1n ph\1ea1t t\00f9', NULL);
    L_RESULT(4) := O_PT80(4, u'\00c1n ch\01b0a c\00f3 hi\1ec7u l\1ef1c PL', NULL);
    L_RESULT(5) := O_PT80(5, u'\00c1n c\00f3 HLPL ch\01b0a c\00f3 Q\0110 THA', NULL);
    L_RESULT(6) := O_PT80(6, u'C\00f3 Q\0110 THA ch\1edd \0111i CHA', NULL);
    L_RESULT(7) := O_PT80(7, u'PN tr\00edch xu\1ea5t tr\1ea1i kh\00e1c v\1ec1 (kh\00f4ng l\00e0 b\1ecb can, b\1ecb c\00e1o)', NULL);
    L_RESULT(8) := O_PT80(8, u'C\1ed9ng', NULL);

    -- ============================ T?NG (C10..C14) ============================

    -- C10: PN trích xu?t tr?i khác v? = PT80.C2 (tr?i t?m giam chuy?n ??n)
    --      + PT80.C3 (tr?i giam khác chuy?n ??n).
    SELECT COUNT(*)
    INTO TS_TMP
    FROM PN_THI_HANH_AN THA
             JOIN PN_LAI_LICHS LL
                  ON LL.ID = THA.THA_PNLAI_LICH_ID AND LL.IS_DELETED = 0 AND THA.IS_DELETED = 0
             LEFT JOIN DM_LOAI_DOI_TUONGS LDT ON LDT.ID = THA.THA_DOI_TUONG AND LDT.IS_DELETED = 0
    WHERE THA.THA_NGAY_DEN_TRAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
      AND LDT.LDT_MA IN (u'20211', u'110', u'120');
    I := TS_TMP;

    SELECT COUNT(*)
    INTO TS_TMP
    FROM PN_THI_HANH_AN THA
             JOIN PN_LAI_LICHS LL ON LL.ID = THA.THA_PNLAI_LICH_ID AND LL.IS_DELETED = 0
             LEFT JOIN DM_LOAI_DOI_TUONGS LDT ON LDT.ID = THA.THA_DOI_TUONG AND LDT.IS_DELETED = 0
    WHERE THA.THA_NGAY_DEN_TRAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
      AND LDT.LDT_MA = u'20221';
    I := I + TS_TMP;

    COLV(10) := I;
    L_RESULT(10) := O_PT80(10, u'PN tr\00edch xu\1ea5t tr\1ea1i kh\00e1c v\1ec1', I);

    -- C11: Tr?n b?t l?i (= PT80.C4)
    SELECT COUNT(*)
    INTO I
    FROM TRON_TRAIS TT
             JOIN PN_LAI_LICHS LL ON LL.ID = TT.PHAM_NHAN_ID AND TT.IS_DELETED = 0 AND LL.IS_DELETED = 0
             JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
    WHERE TT.NGAY_BAT_LAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND TT.NGAY_TRON >= THA.THA_NGAY_DEN_TRAI
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(11) := I;
    L_RESULT(11) := O_PT80(11, u'Tr\1ed1n b\1ecb b\1eaft l\1ea1i', I);

    -- C12: T?m ?ình ch? tr? l?i (= PT80.C5)
    SELECT COUNT(*)
    INTO I
    FROM TAM_DINH_CHIS TDC
             JOIN PN_LAI_LICHS LL
                  ON LL.ID = TDC.PHAM_NHAN_ID AND TDC.IS_DELETED = 0 AND LL.IS_DELETED = 0
             JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
             LEFT JOIN QLPN.DM_LOAI_QUYET_DINH_TAM_DINH_CHIES ldtdc ON LDTDC.ID = TDC.LOAI_QUYET_DINH_ID
    WHERE TDC.NGAY_LAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND TDC.NGAY_TDC > THA.THA_NGAY_DEN_TRAI
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(12) := I;
    L_RESULT(12) := O_PT80(12, u'T\1ea1m \0111\00ecnh ch\1ec9 tr\1edf l\1ea1i tr\1ea1i', I);

    -- C13: Trích xu?t tr? l?i (= PT80.C6)
    SELECT COUNT(*)
    INTO I
    FROM TRICH_XUATS TX
             JOIN PN_LAI_LICHS LL ON LL.ID = TX.PHAM_NHAN_ID AND LL.IS_DELETED = 0
             JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
             LEFT JOIN QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS ldtx
                       ON ldtx.ID = TX.TX_LOAI_LENH_ID AND ldtx.IS_DELETED = 0
    WHERE TX.TX_NGAY_TRA BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND TX.IS_DELETED = 0
      AND TX.TX_NGAY_TRICH_XUAT > THA.THA_NGAY_DEN_TRAI
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(13) := I;
    L_RESULT(13) := O_PT80(13, u'Tr\00edch xu\1ea5t tr\1ea3 l\1ea1i', I);

    -- C14: C?ng t?ng
    COLV(14) := COLV(10) + COLV(11) + COLV(12) + COLV(13);
    L_RESULT(14) := O_PT80(14, u'C\1ed9ng', COLV(14));

    -- ============================ GI?M (C15..C21) ============================

    -- C15: Tha (= PT80.C9)
    SELECT COUNT(DISTINCT ll.ID)
    INTO I
    FROM PN_LAI_LICHS ll
             JOIN PN_THI_HANH_AN tha
                  ON tha.THA_PNLAI_LICH_ID = ll.ID
                      AND tha.IS_DELETED = 0
    WHERE tha.THA_NGAY_HET_HAN BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND ll.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
      AND NOT EXISTS (SELECT 1
                      FROM MIEN_HINH_PHATS mhp
                      WHERE mhp.PN_LAI_LICH_ID = ll.ID
                        AND mhp.IS_DELETED = 0
                        AND mhp.MHP_NGAY_TU_DO BETWEEN P_TU_NGAY AND V_DEN_NGAY
                        AND (V_TRAI_GIAM_ID IS NULL OR ll.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID))
      AND NOT EXISTS (SELECT 1
                      FROM CHUA_BENH_BAT_BUOCS cb
                      WHERE cb.PHAM_NHAN_ID = ll.ID
                        AND (cb.NGAY_KET_THUC IS NULL
                          OR cb.NGAY_KET_THUC > V_DEN_NGAY)
                        AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID))
      AND NOT EXISTS (SELECT 1
                      FROM TRICH_XUATS tx
                               JOIN QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS ldtx
                                    ON ldtx.ID = tx.TX_LOAI_LENH_ID
                                        AND ldtx.IS_DELETED = 0
                      WHERE tx.PHAM_NHAN_ID = ll.ID
                        AND tx.IS_DELETED = 0
                        AND ldtx.LQDTX_MA = '1'
                        AND (tx.TX_NGAY_TRA IS NULL
                          OR tx.TX_NGAY_TRA > V_DEN_NGAY)
                        AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID))
      AND NOT EXISTS (SELECT 1
                      FROM HUY_ANS ha
                      WHERE ha.PHAM_NHAN_ID = ll.ID
                        AND ha.IS_DELETED = 0
                        AND ha.NGAY_TRA_TU_DO BETWEEN P_TU_NGAY AND V_DEN_NGAY);
    COLV(15) := I;
    L_RESULT(15) := O_PT80(15, u'Tha', I);

    -- C16: Tr?n trong tháng (= PT80.C10)
    SELECT COUNT(*)
    INTO I
    FROM TRON_TRAIS TT
             JOIN PN_LAI_LICHS LL ON LL.ID = TT.PHAM_NHAN_ID AND LL.IS_DELETED = 0
             JOIN PN_THI_HANH_AN THA ON tha.THA_PNLAI_LICH_ID = ll.ID AND THA.IS_DELETED = 0
    WHERE TT.NGAY_TRON >= P_TU_NGAY AND TT.NGAY_TRON < V_DEN_NGAY_EXCL
      AND TT.IS_DELETED = 0
      AND TT.NGAY_TRON >= THA.THA_NGAY_DEN_TRAI
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(16) := I;
    L_RESULT(16) := O_PT80(16, u'Tr\1ed1n trong th\00e1ng', I);

    -- C17: Ch?t (= PT80.C11)
    SELECT COUNT(*)
    INTO I
    FROM PN_KET_THUC_CHETS KC
             JOIN PN_LAI_LICHS LL ON LL.ID = KC.KTC_PN_LAI_LICH_ID
             JOIN PN_THI_HANH_AN THA ON tha.THA_PNLAI_LICH_ID = LL.ID AND THA.IS_DELETED = 0
             LEFT JOIN DM_TRUONG_HOP_CHETS THC ON THC.ID = KC.KTC_DM_TRUONG_HOP_CHET_ID
    WHERE KC.KTC_NGAY_CHET >= P_TU_NGAY
      AND KC.KTC_NGAY_CHET < (V_DEN_NGAY + 1)
      AND KC.KTC_NGAY_CHET > THA.THA_NGAY_DEN_TRAI
      AND NVL(THC.THC_MA, '10') NOT IN ('30', '40', '50')
      AND KC.IS_DELETED = 0
      AND LL.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(17) := I;
    L_RESULT(17) := O_PT80(17, u'Ch\1ebft', I);

    -- C18: Trích xu?t (= PT80.C12)
    SELECT COUNT(*)
    INTO I
    FROM TRICH_XUATS TX
             JOIN PN_LAI_LICHS LL ON LL.ID = TX.PHAM_NHAN_ID AND LL.IS_DELETED = 0
             JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
             LEFT JOIN QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS ldtx
                       ON ldtx.ID = TX.TX_LOAI_LENH_ID AND ldtx.IS_DELETED = 0
    WHERE TX.TX_NGAY_TRICH_XUAT BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND ldtx.LQDTX_MA = '1'
      AND TX.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(18) := I;
    L_RESULT(18) := O_PT80(18, u'Tr\00edch xu\1ea5t', I);

    -- C19: T?m ?ình ch? CHA (= PT80.C13)
    SELECT COUNT(*)
    INTO I
    FROM TAM_DINH_CHIS TDC
             JOIN PN_LAI_LICHS LL ON LL.ID = TDC.PHAM_NHAN_ID AND LL.IS_DELETED = 0
             JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
             LEFT JOIN QLPN.DM_LOAI_QUYET_DINH_TAM_DINH_CHIES lqdtdc ON LQDTDC.ID = TDC.LOAI_QUYET_DINH_ID
    WHERE TDC.NGAY_TDC BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND LQDTDC.LQDTDC_MA = '1'
      AND TDC.IS_DELETED = 0
      AND TDC.NGAY_TDC > THA.THA_NGAY_DEN_TRAI
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(19) := I;
    L_RESULT(19) := O_PT80(19, u'T\1ea1m \0111\00ecnh ch\1ec9 CHA', I);

    -- C20: S? chuy?n tr?i khác (= PT80.C14)
    SELECT COUNT(*)
    INTO I
    FROM PHAM_NHAN_CHUYEN_TRAI CT
             JOIN PN_LAI_LICHS LL ON LL.ID = CT.PNCT_LAI_LICH_ID AND LL.IS_DELETED = 0
             JOIN PN_THI_HANH_AN THA ON LL.ID = THA.THA_PNLAI_LICH_ID AND THA.IS_DELETED = 0
             LEFT JOIN DM_TRUONG_HOP_CHUYEN_TRAIS THCT
                       ON THCT.ID = CT.PNCT_TRUONG_HOP_CHUYEN_ID
    WHERE CT.PNCT_NGAY_CHUYEN BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND NVL(THCT.THCT_MA, '10') IN ('10', '20', '90')
      AND CT.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(20) := I;
    L_RESULT(20) := O_PT80(20, u'S\1ed1 chuy\1ec3n tr\1ea1i kh\00e1c', I);

    -- C21: C?ng gi?m
    COLV(21) := COLV(15) + COLV(16) + COLV(17) + COLV(18) + COLV(19) + COLV(20);
    L_RESULT(21) := O_PT80(21, u'C\1ed9ng', COLV(21));

    -- ==================== S? PH?M NHÂN HI?N CÓ (C22..C26) ====================
    -- M?t l?n quét TK_PT80 (?ã ?? b?i SP_POPULATE_TK_PT80_ALT).
    -- L?c m?c án theo cùng h?ng s? n*12*30 nh? SP_GET_PT80.
    SELECT
        COUNT(CASE WHEN LL.MUC_AN_NGAY BETWEEN 1 AND 5*12*30 THEN 1 END),               -- 22
        COUNT(CASE WHEN LL.MUC_AN_NGAY > 5*12*30
                     OR LL.MUC_AN_NGAY IS NULL THEN 1 END),                             -- 23
        COUNT(CASE WHEN LL.MA_GIOI_TINH = '1' THEN 1 END),                              -- 24
        COUNT(CASE WHEN LL.MA_GIOI_TINH = '2' THEN 1 END),                              -- 25
        COUNT(*)                                                                        -- 26
    INTO COLV(22), COLV(23), COLV(24), COLV(25), COLV(26)
    FROM TK_PT80 LL;

    L_RESULT(22) := O_PT80(22, u'\00c1n t\1eeb 5 n\0103m tr\1edf xu\1ed1ng', COLV(22));
    L_RESULT(23) := O_PT80(23, u'\00c1n tr\00ean 5 n\0103m', COLV(23));
    L_RESULT(24) := O_PT80(24, u'Nam', COLV(24));
    L_RESULT(25) := O_PT80(25, u'N\1eef', COLV(25));
    L_RESULT(26) := O_PT80(26, u'T\1ed5ng s\1ed1', COLV(26));

    -- ==================== C9: ??u k? = C26 - C14 + C21 ====================
    COLV(9) := COLV(26) - COLV(14) + COLV(21);
    L_RESULT(9) := O_PT80(9, u'S\1ed1 th\00e1ng tr\01b0\1edbc chuy\1ec3n sang', COLV(9));

    OPEN L_CUR FOR
        SELECT *
        FROM (SELECT STT, SL
              FROM TABLE (L_RESULT))
            PIVOT (
            MAX(SL) FOR STT IN (
                1 AS "1", 2 AS "2", 3 AS "3", 4 AS "4", 5 AS "5",
                6 AS "6", 7 AS "7", 8 AS "8", 9 AS "9", 10 AS "10",
                11 AS "11", 12 AS "12", 13 AS "13", 14 AS "14", 15 AS "15",
                16 AS "16", 17 AS "17", 18 AS "18", 19 AS "19", 20 AS "20",
                21 AS "21", 22 AS "22", 23 AS "23", 24 AS "24", 25 AS "25",
                26 AS "26"
                )
            ) WHERE 1=0;

    DBMS_SQL.RETURN_RESULT(L_CUR);

    COMMIT;
END SP_GET_PT80_B;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PT80_LIVE_UNION
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PT80_LIVE_UNION" (
    P_TU_NGAY IN DATE,
    P_DEN_NGAY IN DATE,
    P_TRAI_GIAM_ID IN NVARCHAR2 DEFAULT NULL
) IS
    V_TRAI_GIAM_ID NUMBER;
    V_DEN_NGAY     DATE;
    L_CUR          SYS_REFCURSOR;
BEGIN
    IF P_TRAI_GIAM_ID IS NOT NULL THEN
        BEGIN
            SELECT ID
            INTO V_TRAI_GIAM_ID
            FROM DM_TRAI_GIAMS
            WHERE TG_MA = P_TRAI_GIAM_ID
              AND IS_DELETED = 0
              AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_TRAI_GIAM_ID := -1;
        END;
    END IF;

    V_DEN_NGAY := LEAST(
        CAST(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh' AS DATE),
        P_DEN_NGAY
    );

    OPEN L_CUR FOR
        WITH base_tha AS (
            SELECT LL.ID                 AS PN_LAI_LICH_ID,
                   LL.LL_TRAI_GIAM_ID,
                   THA.THA_NGAY_DEN_TRAI AS NGAY_VAO_TRAI,
                   THA.THA_NGAY_HET_HAN  AS NGAY_HET_HAN,
                   THA.THA_DOI_TUONG
            FROM PN_THI_HANH_AN THA
                     JOIN PN_LAI_LICHS LL
                          ON LL.ID = THA.THA_PNLAI_LICH_ID
                         AND LL.IS_DELETED = 0
                         AND THA.IS_DELETED = 0
            WHERE V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID
        ),
        c2 AS (
            SELECT 2 AS STT,
                   u'Tr?i t?m giam chuy?n ??n' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   B.NGAY_VAO_TRAI AS NGAY_QUYET_DINH,
                   u'PN_THI_HANH_AN' AS BANG,
                   u'PN_THI_HANH_AN + DM_LOAI_DOI_TUONGS' AS NGUON
            FROM base_tha B
                     LEFT JOIN DM_LOAI_DOI_TUONGS LDT
                               ON LDT.ID = B.THA_DOI_TUONG
                              AND LDT.IS_DELETED = 0
            WHERE B.NGAY_VAO_TRAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND LDT.LDT_MA IN (u'20211', u'110', u'120')
        ),
        c3 AS (
            SELECT 3 AS STT,
                   u'Tr?i giam khác chuy?n ??n' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   B.NGAY_VAO_TRAI AS NGAY_QUYET_DINH,
                   u'PN_THI_HANH_AN' AS BANG,
                   u'PN_THI_HANH_AN + DM_LOAI_DOI_TUONGS' AS NGUON
            FROM base_tha B
                     LEFT JOIN DM_LOAI_DOI_TUONGS LDT
                               ON LDT.ID = B.THA_DOI_TUONG
                              AND LDT.IS_DELETED = 0
            WHERE B.NGAY_VAO_TRAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND LDT.LDT_MA = u'20221'
        ),
        c4 AS (
            SELECT 4 AS STT,
                   u'Tr?n b?t l?i' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   TT.NGAY_BAT_LAI AS NGAY_QUYET_DINH,
                   u'TRON_TRAIS' AS BANG,
                   u'TRON_TRAIS' AS NGUON
            FROM TRON_TRAIS TT
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = TT.PHAM_NHAN_ID
            WHERE TT.NGAY_BAT_LAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND TT.NGAY_TRON >= B.NGAY_VAO_TRAI
              AND TT.IS_DELETED = 0
        ),
        c5 AS (
            SELECT 5 AS STT,
                   u'T?m ?ình ch? tr? l?i' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   TDC.NGAY_LAI AS NGAY_QUYET_DINH,
                   u'TAM_DINH_CHIS' AS BANG,
                   u'TAM_DINH_CHIS' AS NGUON
            FROM TAM_DINH_CHIS TDC
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = TDC.PHAM_NHAN_ID
            WHERE TDC.NGAY_LAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND TDC.NGAY_TDC > B.NGAY_VAO_TRAI
              AND TDC.IS_DELETED = 0
        ),
        c6 AS (
            SELECT 6 AS STT,
                   u'Trích xu?t tr? l?i' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   TX.TX_NGAY_TRA AS NGAY_QUYET_DINH,
                   u'TRICH_XUATS' AS BANG,
                   u'TRICH_XUATS' AS NGUON
            FROM TRICH_XUATS TX
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = TX.PHAM_NHAN_ID
            WHERE TX.TX_NGAY_TRA BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND TX.TX_NGAY_TRICH_XUAT > B.NGAY_VAO_TRAI
              AND TX.IS_DELETED = 0
        ),
        c7 AS (
            SELECT 7 AS STT,
                   u'T?ng khác t? PN_THI_HANH_AN' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   B.NGAY_VAO_TRAI AS NGAY_QUYET_DINH,
                   u'PN_THI_HANH_AN' AS BANG,
                   u'PN_THI_HANH_AN khác lo?i ??i t??ng' AS NGUON
            FROM base_tha B
                     LEFT JOIN DM_LOAI_DOI_TUONGS LDT
                               ON LDT.ID = B.THA_DOI_TUONG
                              AND LDT.IS_DELETED = 0
            WHERE B.NGAY_VAO_TRAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND LDT.LDT_MA NOT IN (u'20211', u'110', u'120', u'20221')

            UNION ALL

            SELECT 7 AS STT,
                   u'H?y Án Quay L?i' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   HA.NGAY_TRO_LAI AS NGAY_QUYET_DINH,
                   u'HUY_ANS' AS BANG,
                   u'HUY_ANS' AS NGUON
            FROM HUY_ANS HA
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = HA.PHAM_NHAN_ID
            WHERE HA.NGAY_TRO_LAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND HA.NGAY_TRA_TU_DO > B.NGAY_VAO_TRAI
              AND HA.IS_DELETED = 0

            UNION ALL

            SELECT 7 AS STT,
                   u'Tha có ?i?u ki?n tr? l?i' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   TCK.NGAY_BAT_LAI AS NGAY_QUYET_DINH,
                   u'THA_CO_DIEU_KIENS' AS BANG,
                   u'THA_CO_DIEU_KIENS' AS NGUON
            FROM THA_CO_DIEU_KIENS TCK
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = TCK.PHAM_NHAN_ID
            WHERE TCK.NGAY_BAT_LAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND TCK.IS_DELETED = 0

            UNION ALL

            SELECT 7 AS STT,
                   u'CBBB quay l?i' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   CB.NGAY_KET_THUC AS NGAY_QUYET_DINH,
                   u'CHUA_BENH_BAT_BUOCS' AS BANG,
                   u'CHUA_BENH_BAT_BUOCS' AS NGUON
            FROM CHUA_BENH_BAT_BUOCS CB
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = CB.PHAM_NHAN_ID
            WHERE CB.NGAY_KET_THUC BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND CB.IS_DELETED = 0

            UNION ALL

            SELECT 7 AS STT,
                   u'HOAN_THI_HANH_AN Quay l?i' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   HOAN.NGAY_THI_HANH_AN AS NGAY_QUYET_DINH,
                   u'HOAN_THI_HANH_ANS' AS BANG,
                   u'HOAN_THI_HANH_ANS' AS NGUON
            FROM HOAN_THI_HANH_ANS HOAN
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = HOAN.PHAM_NHAN_ID
            WHERE HOAN.NGAY_THI_HANH_AN BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND HOAN.IS_DELETED = 0
        ),
        c9 AS (
            SELECT DISTINCT
                   9 AS STT,
                   u'Tha' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   B.NGAY_HET_HAN AS NGAY_QUYET_DINH,
                   u'PN_THI_HANH_AN' AS BANG,
                   u'PN_THI_HANH_AN h?t h?n, qua các ?i?u ki?n lo?i tr?' AS NGUON
            FROM base_tha B
            WHERE B.NGAY_HET_HAN BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND NOT EXISTS (
                SELECT 1
                FROM MIEN_HINH_PHATS MHP
                WHERE MHP.PN_LAI_LICH_ID = B.PN_LAI_LICH_ID
                  AND MHP.IS_DELETED = 0
                  AND MHP.MHP_NGAY_TU_DO BETWEEN P_TU_NGAY AND V_DEN_NGAY
              )
              AND NOT EXISTS (
                SELECT 1
                FROM CHUA_BENH_BAT_BUOCS CB
                WHERE CB.PHAM_NHAN_ID = B.PN_LAI_LICH_ID
                  AND (CB.NGAY_KET_THUC IS NULL OR CB.NGAY_KET_THUC > V_DEN_NGAY)
              )
              AND NOT EXISTS (
                SELECT 1
                FROM TRICH_XUATS TX
                         JOIN QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS LDTX
                              ON LDTX.ID = TX.TX_LOAI_LENH_ID
                             AND LDTX.IS_DELETED = 0
                WHERE TX.PHAM_NHAN_ID = B.PN_LAI_LICH_ID
                  AND TX.IS_DELETED = 0
                  AND LDTX.LQDTX_MA = '1'
                  AND (TX.TX_NGAY_TRA IS NULL OR TX.TX_NGAY_TRA > V_DEN_NGAY)
              )
              AND NOT EXISTS (
                SELECT 1
                FROM HUY_ANS HA
                WHERE HA.PHAM_NHAN_ID = B.PN_LAI_LICH_ID
                  AND HA.IS_DELETED = 0
                  AND HA.NGAY_TRA_TU_DO BETWEEN P_TU_NGAY AND V_DEN_NGAY
              )
        ),
        c10 AS (
            SELECT 10 AS STT,
                   u'Tr?n' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   TT.NGAY_TRON AS NGAY_QUYET_DINH,
                   u'TRON_TRAIS' AS BANG,
                   u'TRON_TRAIS' AS NGUON
            FROM TRON_TRAIS TT
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = TT.PHAM_NHAN_ID
            WHERE TT.NGAY_TRON >= P_TU_NGAY
              AND TT.NGAY_TRON < V_DEN_NGAY + 1
              AND TT.NGAY_TRON >= B.NGAY_VAO_TRAI
              AND TT.IS_DELETED = 0
        ),
        c11 AS (
            SELECT 11 AS STT,
                   u'Ch?t' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   KC.KTC_NGAY_CHET AS NGAY_QUYET_DINH,
                   u'PN_KET_THUC_CHETS' AS BANG,
                   u'PN_KET_THUC_CHETS' AS NGUON
            FROM PN_KET_THUC_CHETS KC
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = KC.KTC_PN_LAI_LICH_ID
                     LEFT JOIN DM_TRUONG_HOP_CHETS THC
                               ON THC.ID = KC.KTC_DM_TRUONG_HOP_CHET_ID
            WHERE KC.KTC_NGAY_CHET >= P_TU_NGAY
              AND KC.KTC_NGAY_CHET < V_DEN_NGAY + 1
              AND KC.KTC_NGAY_CHET > B.NGAY_VAO_TRAI
              AND NVL(THC.THC_MA, '10') NOT IN ('30', '40', '50')
              AND KC.IS_DELETED = 0
        ),
        c12 AS (
            SELECT 12 AS STT,
                   u'Trích xu?t' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   TX.TX_NGAY_TRICH_XUAT AS NGAY_QUYET_DINH,
                   u'TRICH_XUATS' AS BANG,
                   u'TRICH_XUATS + DM_LOAI_QUYET_DINH_TRICH_XUATS' AS NGUON
            FROM TRICH_XUATS TX
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = TX.PHAM_NHAN_ID
                     LEFT JOIN QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS LDTX
                               ON LDTX.ID = TX.TX_LOAI_LENH_ID
                              AND LDTX.IS_DELETED = 0
            WHERE TX.TX_NGAY_TRICH_XUAT BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND LDTX.LQDTX_MA = '1'
              AND TX.IS_DELETED = 0
        ),
        c13 AS (
            SELECT 13 AS STT,
                   u'T?m ?ình ch?' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   TDC.NGAY_TDC AS NGAY_QUYET_DINH,
                   u'TAM_DINH_CHIS' AS BANG,
                   u'TAM_DINH_CHIS + DM_LOAI_QUYET_DINH_TAM_DINH_CHIES' AS NGUON
            FROM TAM_DINH_CHIS TDC
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = TDC.PHAM_NHAN_ID
                     LEFT JOIN QLPN.DM_LOAI_QUYET_DINH_TAM_DINH_CHIES LQDTDC
                               ON LQDTDC.ID = TDC.LOAI_QUYET_DINH_ID
            WHERE TDC.NGAY_TDC BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND LQDTDC.LQDTDC_MA = '1'
              AND TDC.IS_DELETED = 0
              AND TDC.NGAY_TDC > B.NGAY_VAO_TRAI
        ),
        c14 AS (
            SELECT 14 AS STT,
                   u'Chuy?n tr?i' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   CT.PNCT_NGAY_CHUYEN AS NGAY_QUYET_DINH,
                   u'PHAM_NHAN_CHUYEN_TRAI' AS BANG,
                   u'PHAM_NHAN_CHUYEN_TRAI + DM_TRUONG_HOP_CHUYEN_TRAIS' AS NGUON
            FROM PHAM_NHAN_CHUYEN_TRAI CT
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = CT.PNCT_LAI_LICH_ID
                     LEFT JOIN DM_TRUONG_HOP_CHUYEN_TRAIS THCT
                               ON THCT.ID = CT.PNCT_TRUONG_HOP_CHUYEN_ID
            WHERE CT.PNCT_NGAY_CHUYEN BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND NVL(THCT.THCT_MA, '10') IN ('10', '20', '90')
              AND CT.IS_DELETED = 0
        ),
        c15 AS (
            SELECT 15 AS STT,
                   u'H?y Án' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   HA.NGAY_TRA_TU_DO AS NGAY_QUYET_DINH,
                   u'HUY_ANS' AS BANG,
                   u'HUY_ANS' AS NGUON
            FROM HUY_ANS HA
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = HA.PHAM_NHAN_ID
            WHERE HA.NGAY_TRA_TU_DO BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND HA.IS_DELETED = 0

            UNION ALL

            SELECT 15 AS STT,
                   u'Hoãn Thi Hành Án' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   HTHA.NGAY_HOAN AS NGAY_QUYET_DINH,
                   u'HOAN_THI_HANH_ANS' AS BANG,
                   u'HOAN_THI_HANH_ANS' AS NGUON
            FROM HOAN_THI_HANH_ANS HTHA
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = HTHA.PHAM_NHAN_ID
            WHERE HTHA.NGAY_HOAN BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND HTHA.IS_DELETED = 0
              AND NOT EXISTS (
                SELECT 1
                FROM TRICH_XUATS TX
                         JOIN QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS LDTX
                              ON LDTX.ID = TX.TX_LOAI_LENH_ID
                             AND LDTX.IS_DELETED = 0
                WHERE TX.PHAM_NHAN_ID = HTHA.PHAM_NHAN_ID
                  AND TX.IS_DELETED = 0
                  AND LDTX.LQDTX_MA = '1'
                  AND (TX.TX_NGAY_TRA IS NULL OR TX.TX_NGAY_TRA >= V_DEN_NGAY + 1)
                  AND TX.TX_NGAY_TRICH_XUAT >= B.NGAY_VAO_TRAI
              )

            UNION ALL

            SELECT 15 AS STT,
                   u'Mi?n Hình Ph?t' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   MHP.MHP_NGAY_TU_DO AS NGAY_QUYET_DINH,
                   u'MIEN_HINH_PHATS' AS BANG,
                   u'MIEN_HINH_PHATS' AS NGUON
            FROM MIEN_HINH_PHATS MHP
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = MHP.PN_LAI_LICH_ID
            WHERE MHP.MHP_NGAY_TU_DO BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND MHP.IS_DELETED = 0

            UNION ALL

            SELECT 15 AS STT,
                   u'Ch?a b?nh b?t bu?c' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   CB.NGAY_BAT_DAU AS NGAY_QUYET_DINH,
                   u'CHUA_BENH_BAT_BUOCS' AS BANG,
                   u'CHUA_BENH_BAT_BUOCS' AS NGUON
            FROM CHUA_BENH_BAT_BUOCS CB
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = CB.PHAM_NHAN_ID
            WHERE CB.NGAY_BAT_DAU BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND CB.IS_DELETED = 0

            UNION ALL

            SELECT 15 AS STT,
                   u'Chuy?n Giao N??c ngoài' AS TEN_COT,
                   B.PN_LAI_LICH_ID,
                   B.NGAY_VAO_TRAI,
                   B.NGAY_HET_HAN,
                   CG.PNCG_NGAY_CHUYEN_GIAO AS NGAY_QUYET_DINH,
                   u'PN_CHUYEN_GIAO' AS BANG,
                   u'PN_CHUYEN_GIAO + DM_QUOC_TICHS' AS NGUON
            FROM PN_CHUYEN_GIAO CG
                     JOIN base_tha B
                          ON B.PN_LAI_LICH_ID = CG.PNCG_LAI_LICH_ID
                     LEFT JOIN DM_QUOC_TICHS QT
                               ON QT.ID = CG.PNCG_NUOC_CHUYEN_GIAO_ID
            WHERE CG.PNCG_NGAY_CHUYEN_GIAO BETWEEN P_TU_NGAY AND V_DEN_NGAY
              AND NVL(QT.QT_MA, '000') <> '250'
              AND CG.IS_DELETED = 0
        )
        SELECT STT,
              TEN_COT,
              PN_LAI_LICH_ID,
              NGAY_VAO_TRAI,
              NGAY_HET_HAN,
              NGAY_QUYET_DINH,
              BANG,
              NGUON
        FROM (
            SELECT * FROM c2
            UNION ALL
            SELECT * FROM c3
            UNION ALL
            SELECT * FROM c4
            UNION ALL
            SELECT * FROM c5
            UNION ALL
            SELECT * FROM c6
            UNION ALL
            SELECT * FROM c7
            UNION ALL
            SELECT * FROM c9
            UNION ALL
            SELECT * FROM c10
            UNION ALL
            SELECT * FROM c11
            UNION ALL
            SELECT * FROM c12
            UNION ALL
            SELECT * FROM c13
            UNION ALL
            SELECT * FROM c14
            UNION ALL
            SELECT * FROM c15
        )
        ORDER BY STT, NGAY_QUYET_DINH, BANG, PN_LAI_LICH_ID, NGAY_VAO_TRAI, NGAY_HET_HAN, NGUON;

    DBMS_SQL.RETURN_RESULT(L_CUR);
END SP_GET_PT80_live_union;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PT80_NU
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_PT80_NU" (
    P_TU_NGAY IN DATE,
    P_DEN_NGAY IN DATE,
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL
) IS
    I                NUMBER;
    TS_TMP           NUMBER;
    L_TMP_CH16       NUMBER;
    L_TMP_CH21       NUMBER;
    TYPE COLVAL IS TABLE OF NUMBER(10) INDEX BY BINARY_INTEGER;
    COLV             COLVAL;
    V_TRAI_GIAM_ID   NUMBER;
    V_GIOI_TINH_NU_ID NUMBER;
    V_DEN_NGAY       DATE;
    V_NAM_HIEN_TAI   NUMBER;
    V_DEN_NGAY_EXCL  DATE;
    L_RESULT         QLPN.T_PT80;
    L_CUR            SYS_REFCURSOR;
BEGIN
    IF p_ma_trai_giam IS NOT NULL THEN
        BEGIN
            SELECT ID
            INTO V_TRAI_GIAM_ID
            FROM QLPN.DM_TRAI_GIAMS
            WHERE TG_MA = p_ma_trai_giam
              AND IS_DELETED = 0
              AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN V_TRAI_GIAM_ID := -1;
        END;
    END IF;

    BEGIN
        SELECT ID
        INTO V_GIOI_TINH_NU_ID
        FROM QLPN.DM_GIOI_TINHS
        WHERE GT_MA = '2'
          AND IS_DELETED = 0
          AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN V_GIOI_TINH_NU_ID := -1;
    END;

    V_DEN_NGAY := LEAST(
        CAST(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh' AS DATE),
        P_DEN_NGAY
    );
    V_DEN_NGAY_EXCL := V_DEN_NGAY + 1;
    V_NAM_HIEN_TAI := EXTRACT(YEAR FROM V_DEN_NGAY);

    QLPN.SP_POPULATE_TK_PT80_NU_ALT(V_DEN_NGAY, V_TRAI_GIAM_ID);

    L_RESULT := QLPN.T_PT80();

    L_RESULT.EXTEND;
    COLV(1) := 0;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(1, u'S\1ed1 th\00e1ng tr\01b0\1edbc chuy\1ec3n sang', 0);

    L_RESULT.EXTEND;
    SELECT COUNT(*)
    INTO I
    FROM QLPN.PN_THI_HANH_AN THA
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND LL.IS_DELETED = 0
       AND THA.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    LEFT JOIN QLPN.DM_LOAI_DOI_TUONGS LDT
        ON LDT.ID = THA.THA_DOI_TUONG
       AND LDT.IS_DELETED = 0
    WHERE THA.THA_NGAY_DEN_TRAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
      AND LDT.LDT_MA IN (u'20211', u'110', u'120');
    COLV(2) := I;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(2, u'Tr\1ea1i t\1ea1m giam chuy\1ec3n \0111\1ebfn', I);

    L_RESULT.EXTEND;
    SELECT COUNT(*)
    INTO I
    FROM QLPN.PN_THI_HANH_AN THA
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    LEFT JOIN QLPN.DM_LOAI_DOI_TUONGS LDT
        ON LDT.ID = THA.THA_DOI_TUONG
       AND LDT.IS_DELETED = 0
    WHERE THA.THA_NGAY_DEN_TRAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND THA.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
      AND LDT.LDT_MA = u'20221';
    COLV(3) := I;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(3, u'Tr\1ea1i giam kh\00e1c chuy\1ec3n \0111\1ebfn', I);

    L_RESULT.EXTEND;
    SELECT COUNT(*)
    INTO I
    FROM QLPN.TRON_TRAIS TT
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = TT.PHAM_NHAN_ID
       AND TT.IS_DELETED = 0
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    JOIN QLPN.PN_THI_HANH_AN THA
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND THA.IS_DELETED = 0
    WHERE TT.NGAY_BAT_LAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND TT.NGAY_TRON >= THA.THA_NGAY_DEN_TRAI
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(4) := I;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(4, u'Tr\1ed1n b\1eaft l\1ea1i', I);

    L_RESULT.EXTEND;
    SELECT COUNT(*)
    INTO I
    FROM QLPN.TAM_DINH_CHIS TDC
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = TDC.PHAM_NHAN_ID
       AND TDC.IS_DELETED = 0
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    JOIN QLPN.PN_THI_HANH_AN THA
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND THA.IS_DELETED = 0
    LEFT JOIN QLPN.DM_LOAI_QUYET_DINH_TAM_DINH_CHIES LDTDC
        ON LDTDC.ID = TDC.LOAI_QUYET_DINH_ID
    WHERE TDC.NGAY_LAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND TDC.NGAY_TDC > THA.THA_NGAY_DEN_TRAI
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(5) := I;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(5, u'T\1ea1m \0111\00ecnh ch\1ec9 tr\1ea3 l\1ea1i', I);

    L_RESULT.EXTEND;
    SELECT COUNT(*)
    INTO I
    FROM QLPN.TRICH_XUATS TX
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = TX.PHAM_NHAN_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    JOIN QLPN.PN_THI_HANH_AN THA
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND THA.IS_DELETED = 0
    LEFT JOIN QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS LDTX
        ON LDTX.ID = TX.TX_LOAI_LENH_ID
       AND LDTX.IS_DELETED = 0
    WHERE TX.TX_NGAY_TRA BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND TX.IS_DELETED = 0
      AND TX.TX_NGAY_TRICH_XUAT > THA.THA_NGAY_DEN_TRAI
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(6) := I;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(6, u'Tr\00edch xu\1ea5t tr\1ea3 l\1ea1i', I);

    L_RESULT.EXTEND;

    SELECT COUNT(*)
    INTO TS_TMP
    FROM QLPN.PN_THI_HANH_AN THA
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND LL.IS_DELETED = 0
       AND THA.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    LEFT JOIN QLPN.DM_LOAI_DOI_TUONGS LDT
        ON LDT.ID = THA.THA_DOI_TUONG
       AND LDT.IS_DELETED = 0
    WHERE THA.THA_NGAY_DEN_TRAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND LDT.LDT_MA NOT IN (u'20211', u'110', u'120', u'20221')
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    I := TS_TMP;

    SELECT COUNT(*)
    INTO TS_TMP
    FROM QLPN.HUY_ANS HA
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = HA.PHAM_NHAN_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    JOIN QLPN.PN_THI_HANH_AN THA
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND THA.IS_DELETED = 0
    WHERE HA.NGAY_TRO_LAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND HA.NGAY_TRA_TU_DO > THA.THA_NGAY_DEN_TRAI
      AND HA.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    I := I + TS_TMP;

    SELECT COUNT(*)
    INTO TS_TMP
    FROM QLPN.THA_CO_DIEU_KIENS TCK
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = TCK.PHAM_NHAN_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    WHERE TCK.NGAY_BAT_LAI BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND TCK.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    I := I + TS_TMP;

    SELECT COUNT(*)
    INTO TS_TMP
    FROM QLPN.CHUA_BENH_BAT_BUOCS CB
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = CB.PHAM_NHAN_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    WHERE CB.NGAY_KET_THUC BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND CB.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    I := I + TS_TMP;

    COLV(7) := I;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(7, u'T\0103ng kh\00e1c', I);

    L_RESULT.EXTEND;
    COLV(8) := COLV(2) + COLV(3) + COLV(4) + COLV(5) + COLV(6) + COLV(7);
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(8, u'C\1ed9ng', COLV(8));

    L_RESULT.EXTEND;
    SELECT COUNT(DISTINCT LL.ID)
    INTO I
    FROM QLPN.PN_LAI_LICHS LL
    JOIN QLPN.PN_THI_HANH_AN THA
        ON THA.THA_PNLAI_LICH_ID = LL.ID
       AND THA.IS_DELETED = 0
    WHERE THA.THA_NGAY_HET_HAN BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND LL.IS_DELETED = 0
      AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
      AND NOT EXISTS (
          SELECT 1
          FROM QLPN.MIEN_HINH_PHATS MHP
          WHERE MHP.PN_LAI_LICH_ID = LL.ID
            AND MHP.IS_DELETED = 0
            AND MHP.MHP_NGAY_TU_DO BETWEEN P_TU_NGAY AND V_DEN_NGAY
      )
      AND NOT EXISTS (
          SELECT 1
          FROM QLPN.CHUA_BENH_BAT_BUOCS CB
          WHERE CB.PHAM_NHAN_ID = LL.ID
            AND (CB.NGAY_KET_THUC IS NULL OR CB.NGAY_KET_THUC > V_DEN_NGAY)
      )
      AND NOT EXISTS (
          SELECT 1
          FROM QLPN.TRICH_XUATS TX
          JOIN QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS LDTX
              ON LDTX.ID = TX.TX_LOAI_LENH_ID
             AND LDTX.IS_DELETED = 0
          WHERE TX.PHAM_NHAN_ID = LL.ID
            AND TX.IS_DELETED = 0
            AND LDTX.LQDTX_MA = '1'
            AND (TX.TX_NGAY_TRA IS NULL OR TX.TX_NGAY_TRA > V_DEN_NGAY)
      );
    COLV(9) := I;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(9, u'Tha', I);

    L_RESULT.EXTEND;
    SELECT COUNT(*)
    INTO I
    FROM QLPN.TRON_TRAIS TT
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = TT.PHAM_NHAN_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    JOIN QLPN.PN_THI_HANH_AN THA
        ON THA.THA_PNLAI_LICH_ID = LL.ID
       AND THA.IS_DELETED = 0
    WHERE TT.NGAY_TRON BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND TT.IS_DELETED = 0
      AND TT.NGAY_TRON >= THA.THA_NGAY_DEN_TRAI
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(10) := I;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(10, u'Tr\1ed1n', I);

    L_RESULT.EXTEND;
    SELECT COUNT(*)
    INTO I
    FROM QLPN.PN_KET_THUC_CHETS KC
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = KC.KTC_PN_LAI_LICH_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    JOIN QLPN.PN_THI_HANH_AN THA
        ON THA.THA_PNLAI_LICH_ID = LL.ID
       AND THA.IS_DELETED = 0
    LEFT JOIN QLPN.DM_TRUONG_HOP_CHETS THC
        ON THC.ID = KC.KTC_DM_TRUONG_HOP_CHET_ID
    WHERE KC.KTC_NGAY_CHET >= P_TU_NGAY
      AND KC.KTC_NGAY_CHET < V_DEN_NGAY_EXCL
      AND KC.KTC_NGAY_CHET > THA.THA_NGAY_DEN_TRAI
      AND NVL(THC.THC_MA, '10') NOT IN ('30', '40', '50')
      AND KC.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(11) := I;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(11, u'Ch\1ebft', I);

    L_RESULT.EXTEND;
    SELECT COUNT(*)
    INTO I
    FROM QLPN.TRICH_XUATS TX
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = TX.PHAM_NHAN_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    JOIN QLPN.PN_THI_HANH_AN THA
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND THA.IS_DELETED = 0
    LEFT JOIN QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS LDTX
        ON LDTX.ID = TX.TX_LOAI_LENH_ID
       AND LDTX.IS_DELETED = 0
    WHERE TX.TX_NGAY_TRICH_XUAT BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND LDTX.LQDTX_MA = '1'
      AND TX.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(12) := I;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(12, u'Tr\00edch xu\1ea5t', I);

    L_RESULT.EXTEND;
    SELECT COUNT(*)
    INTO I
    FROM QLPN.TAM_DINH_CHIS TDC
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = TDC.PHAM_NHAN_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    JOIN QLPN.PN_THI_HANH_AN THA
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND THA.IS_DELETED = 0
    LEFT JOIN QLPN.DM_LOAI_QUYET_DINH_TAM_DINH_CHIES LQDTDC
        ON LQDTDC.ID = TDC.LOAI_QUYET_DINH_ID
    WHERE TDC.NGAY_TDC BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND LQDTDC.LQDTDC_MA = '1'
      AND TDC.IS_DELETED = 0
      AND TDC.NGAY_TDC > THA.THA_NGAY_DEN_TRAI
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(13) := I;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(13, u'T\1ea1m \0111\00ecnh ch\1ec9', I);

    L_RESULT.EXTEND;
    SELECT COUNT(*)
    INTO I
    FROM QLPN.PHAM_NHAN_CHUYEN_TRAI CT
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = CT.PNCT_LAI_LICH_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    JOIN QLPN.PN_THI_HANH_AN THA
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND THA.IS_DELETED = 0
    LEFT JOIN QLPN.DM_TRUONG_HOP_CHUYEN_TRAIS THCT
        ON THCT.ID = CT.PNCT_TRUONG_HOP_CHUYEN_ID
    WHERE CT.PNCT_NGAY_CHUYEN BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND NVL(THCT.THCT_MA, '10') IN ('10', '20', '90')
      AND CT.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    COLV(14) := I;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(14, u'Chuy\1ec3n tr\1ea1i', I);

    L_RESULT.EXTEND;

    SELECT COUNT(*)
    INTO TS_TMP
    FROM QLPN.HUY_ANS HA
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = HA.PHAM_NHAN_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    JOIN QLPN.PN_THI_HANH_AN THA
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND THA.IS_DELETED = 0
    WHERE HA.NGAY_TRA_TU_DO BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND HA.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    I := TS_TMP;

    SELECT COUNT(*)
    INTO TS_TMP
    FROM QLPN.HOAN_THI_HANH_ANS HTHA
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = HTHA.PHAM_NHAN_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    JOIN QLPN.PN_THI_HANH_AN THA
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND THA.IS_DELETED = 0
    WHERE HTHA.NGAY_HOAN BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND HTHA.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
      AND NOT EXISTS (
          SELECT 1
          FROM QLPN.TRICH_XUATS TX
          JOIN QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS LDTX
              ON LDTX.ID = TX.TX_LOAI_LENH_ID
             AND LDTX.IS_DELETED = 0
          JOIN QLPN.PN_THI_HANH_AN THA2
              ON LL.ID = THA2.THA_PNLAI_LICH_ID
             AND THA2.IS_DELETED = 0
          WHERE TX.PHAM_NHAN_ID = HTHA.PHAM_NHAN_ID
            AND TX.IS_DELETED = 0
            AND LDTX.LQDTX_MA = '1'
            AND (TX.TX_NGAY_TRA IS NULL OR TX.TX_NGAY_TRA >= V_DEN_NGAY_EXCL)
            AND TX.TX_NGAY_TRICH_XUAT >= THA2.THA_NGAY_DEN_TRAI
      );
    I := I + TS_TMP;

    SELECT COUNT(*)
    INTO TS_TMP
    FROM QLPN.MIEN_HINH_PHATS MHP
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = MHP.PN_LAI_LICH_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    JOIN QLPN.PN_THI_HANH_AN THA
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND THA.IS_DELETED = 0
    WHERE MHP.MHP_NGAY_TU_DO BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND MHP.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    I := I + TS_TMP;

    SELECT COUNT(*)
    INTO TS_TMP
    FROM QLPN.CHUA_BENH_BAT_BUOCS CB
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = CB.PHAM_NHAN_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    JOIN QLPN.PN_THI_HANH_AN THA
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND THA.IS_DELETED = 0
    WHERE CB.NGAY_BAT_DAU BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND CB.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    I := I + TS_TMP;

    SELECT COUNT(*)
    INTO TS_TMP
    FROM QLPN.PN_CHUYEN_GIAO CG
    JOIN QLPN.PN_LAI_LICHS LL
        ON LL.ID = CG.PNCG_LAI_LICH_ID
       AND LL.IS_DELETED = 0
       AND LL.LL_DM_GIOI_TINH_ID = V_GIOI_TINH_NU_ID
    JOIN QLPN.PN_THI_HANH_AN THA
        ON LL.ID = THA.THA_PNLAI_LICH_ID
       AND THA.IS_DELETED = 0
    LEFT JOIN QLPN.DM_QUOC_TICHS QT
        ON QT.ID = CG.PNCG_NUOC_CHUYEN_GIAO_ID
    WHERE CG.PNCG_NGAY_CHUYEN_GIAO BETWEEN P_TU_NGAY AND V_DEN_NGAY
      AND NVL(QT.QT_MA, '000') <> '250'
      AND CG.IS_DELETED = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);
    I := I + TS_TMP;

    COLV(15) := I;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(15, u'Gi\1ea3m kh\00e1c', I);

    L_RESULT.EXTEND;
    COLV(16) := COLV(9) + COLV(10) + COLV(11) + COLV(12) + COLV(13) + COLV(14) + COLV(15);
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(16, u'C\1ed9ng', COLV(16));

    FOR K IN 17..61 LOOP
        L_RESULT.EXTEND;
    END LOOP;

    SELECT
        COUNT(CASE WHEN LL.MA_GIOI_TINH = '1' THEN 1 END),                              -- 17
        COUNT(CASE WHEN LL.MA_GIOI_TINH = '2' THEN 1 END),                              -- 18
        COUNT(CASE WHEN LL.MA_GIOI_TINH = '3' THEN 1 END),                              -- 19
        COUNT(*),                                                                       -- 20
        COUNT(CASE WHEN LL.CHUONG_TD = '13' THEN 1 END),                                -- 21
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1123', '093')  THEN 1 END),                             -- 22 Giet nguoi
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('104a', '1134a') THEN 1 END),                             -- 23 Co y gay thuong tich
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('111', '1141')  THEN 1 END),                            -- 24 Hiep dam
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('112a', '1142a', '1142') THEN 1 END),                            -- 25 Hiep dam nguoi duoi 16 tuoi
        COUNT(CASE WHEN LL.MA_TOI_DANH = '1151' THEN 1 END),                            -- 26 Mua ban nguoi duoi 16 tuoi
        COUNT(CASE WHEN LL.MA_TOI_DANH = '1168' OR LL.MA_TOI_DANH = '1171' THEN 1 END), -- 28 Cuop, Cuop giat
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1173', '138') THEN 1 END),                            -- 29 Trom cap
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1175', '140') THEN 1 END),                            -- 30 Lam dung tin nhiem chiem doat tai san
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1174', '139') THEN 1 END),                            -- 31 Lua dao chiem doat tai san
        COUNT(CASE WHEN LL.CHUONG_TD = '14' THEN 1 END),                                -- n?n cho 27
        COUNT(CASE WHEN LL.CHUONG_TD = '16' THEN 1 END),                                -- n?n cho 32
        COUNT(CASE WHEN LL.CHUONG_TD = '18' THEN 1 END),                                -- 33 cac toi xp trat tu qlkt
        COUNT(CASE WHEN LL.CHUONG_TD = '20' THEN 1 END),                                -- 34 cac toi ma tuy
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1285','1286','1287','1288','1289',
                                           '1290','1291','1292','1293','1294')
                   THEN 1 END),                                                         -- 35 cac toi ve cntt, mvt
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1321','1322') THEN 1 END),                  -- 36 cac toi danh bac
        COUNT(CASE WHEN LL.MA_TOI_DANH IN ('1327','1328','1329') THEN 1 END),           -- 37 cac toi mai dam
        COUNT(CASE WHEN LL.CHUONG_TD = '21' THEN 1 END),                                -- n?n cho 38
        COUNT(CASE WHEN LL.CHUONG_TD = '22' THEN 1 END),                                -- 39 cac toi xam pham trat tu qlhc
        COUNT(CASE WHEN LL.CHUONG_TD = '23' THEN 1 END),                                -- 40 cac toi chuc vu
        COUNT(CASE WHEN LL.CHUONG_TD = '24' THEN 1 END),                                -- 41 cac toi xam pham hoat dong tu phap
        COUNT(CASE WHEN LL.MUC_AN_NGAY IS NULL THEN 1 END),                             -- 43 chung than
        COUNT(CASE WHEN LL.MUC_AN_NGAY BETWEEN 15*12*30+1 AND 30*12*30 THEN 1 END),     -- 44 (15 - 30] nam
        COUNT(CASE WHEN LL.MUC_AN_NGAY BETWEEN 7*12*30+1  AND 15*12*30 THEN 1 END),     -- 45 (7-15] nam
        COUNT(CASE WHEN LL.MUC_AN_NGAY BETWEEN 3*12*30+1  AND 7*12*30  THEN 1 END),     -- 46 (3-7] nam
        COUNT(CASE WHEN LL.MUC_AN_NGAY BETWEEN 1          AND 3*12*30  THEN 1 END),     -- 47 (0, 3] nam
        COUNT(CASE WHEN NAM_PHAM_TOI - NAM_SINH
                        BETWEEN 14 AND 16 - 0.01 THEN 1 END),                     -- 48 14-16tuoi luc pham toi
        COUNT(CASE WHEN NAM_PHAM_TOI - NAM_SINH
                        BETWEEN 16 AND 18 - 0.01 THEN 1 END),                     -- 49 16-18 tuoi luc pham toi
        COUNT(CASE WHEN V_NAM_HIEN_TAI - NAM_SINH
                        < 18 THEN 1 END),                                            -- 50 duoi 18 tuoi
        COUNT(CASE WHEN V_NAM_HIEN_TAI - NAM_SINH
                        BETWEEN 18 AND 30 - 0.01 THEN 1 END),                     -- 51 18-30 tuoi
        COUNT(CASE WHEN V_NAM_HIEN_TAI - NAM_SINH
                        BETWEEN 30 AND 45 - 0.01 THEN 1 END),                     -- 52 30-45 tuoi
        COUNT(CASE WHEN V_NAM_HIEN_TAI - NAM_SINH
                        BETWEEN 45 AND 60 - 0.01 THEN 1 END),                     -- 53 45-60 tuoi
        COUNT(CASE WHEN V_NAM_HIEN_TAI - NAM_SINH BETWEEN 60 AND 69 THEN 1 END),  -- 60-69 tuoi
        COUNT(CASE WHEN V_NAM_HIEN_TAI - NAM_SINH >= 70 THEN 1 END),              -- 70 tuoi
        COUNT(CASE WHEN NVL(LL.MA_TAI_PHAM,'0') = '1' THEN 1 END),                      -- 56 tai pham
        COUNT(CASE WHEN NVL(LL.MA_TAI_PHAM,'0') = '2' THEN 1 END),                      -- 57 tai pham nguy hiem
        COUNT(CASE WHEN LL.MA_QUOC_TICH <> '250' THEN 1 END),                           -- 58 quoc tich vn
        COUNT(CASE WHEN LL.MA_TON_GIAO  <> '9999' OR LL.MA_TON_GIAO IS NULL THEN 1 END),                           -- 59 co ton giao
        COUNT(CASE WHEN LL.MA_DAN_TOC NOT IN ('01', '55') THEN 1 END),               -- 60 dan toc thieu so
        COUNT(CASE WHEN LL.MA_HOC_VAN = '100' THEN 1 END)                               -- 61
    INTO
        COLV(17), COLV(18), COLV(19), COLV(20), COLV(21),
        COLV(22), COLV(23), COLV(24), COLV(25), COLV(26),
        COLV(28), COLV(29), COLV(30), COLV(31),
        TS_TMP,
        L_TMP_CH16,
        COLV(33), COLV(34), COLV(35), COLV(36), COLV(37),
        L_TMP_CH21,
        COLV(39), COLV(40), COLV(41),
        COLV(43), COLV(44), COLV(45), COLV(46), COLV(47),
        COLV(48), COLV(49), COLV(50), COLV(51), COLV(52),
        COLV(53), COLV(54), COLV(55), COLV(56), COLV(57),
        COLV(58), COLV(59), COLV(60), COLV(61)
    FROM QLPN.TK_PT80 LL
    LEFT JOIN QLPN.DM_TOI_DANHS TD
        ON TD.TD_MA = LL.MA_TOI_DANH;

    COLV(27) := TS_TMP - (COLV(24) + COLV(23) + COLV(22) + COLV(25) + COLV(26));
    COLV(32) := L_TMP_CH16 - (COLV(30) + COLV(29) + COLV(28) + COLV(31));
    COLV(38) := L_TMP_CH21 - (COLV(35) + COLV(36) + COLV(37));
    COLV(42) := COLV(20) - (COLV(21) + COLV(22) + COLV(23) + COLV(24) + COLV(25)
        + COLV(26) + COLV(27) + COLV(28) + COLV(29) + COLV(30)
        + COLV(31) + COLV(32) + COLV(33) + COLV(34) + COLV(35)
        + COLV(36) + COLV(37) + COLV(38) + COLV(39) + COLV(40) + COLV(41));

    L_RESULT(17) := QLPN.O_PT80(17, u'Nam', COLV(17));
    L_RESULT(18) := QLPN.O_PT80(18, u'N\1eef', COLV(18));
    L_RESULT(19) := QLPN.O_PT80(19, u'Gi\1edbi t\00ednh kh\00e1c', COLV(19));
    L_RESULT(20) := QLPN.O_PT80(20, u'C\1ed9ng', COLV(20));
    L_RESULT(21) := QLPN.O_PT80(21, u'T\1ed5ng c\00e1c t\1ed9i XP ANQG', COLV(21));
    L_RESULT(22) := QLPN.O_PT80(22, u'C\00e1c t\1ed9i gi\1ebft ng\01b0\1eddi', COLV(22));
    L_RESULT(23) := QLPN.O_PT80(23, u'C\00e1c t\1ed9i c\1ed1 \00fd g\00e2y th\01b0\01a1ng t\00edch', COLV(23));
    L_RESULT(24) := QLPN.O_PT80(24, u'Hi\1ebfp d\00e2m', COLV(24));
    L_RESULT(25) := QLPN.O_PT80(25, u'Hi\1ebfp d\00e2m ng\01b0\1eddi d\01b0\1edbi 16 tu\1ed5i', COLV(25));
    L_RESULT(26) := QLPN.O_PT80(26, u'Mua b\00e1n ng\01b0\1eddi d\01b0\1edbi 16 tu\1ed5i', COLV(26));
    L_RESULT(27) := QLPN.O_PT80(27, u'C\00e1c t\1ed9i kh\00e1c c\00f2n l\1ea1i v\1ec1 XP TM,SK con ng\01b0\1eddi', COLV(27));
    L_RESULT(28) := QLPN.O_PT80(28, u'C\01b0\1edbp, c\01b0\1edbp gi\1eadt', COLV(28));
    L_RESULT(29) := QLPN.O_PT80(29, u'Tr\1ed9m c\1eafp t\00e0i s\1ea3n', COLV(29));
    L_RESULT(30) := QLPN.O_PT80(30, u'L\1ea1m d\1ee5ng t\00edn nhi\1ec7m chi\1ebfm \0111o\1ea1t t\00e0i s\1ea3n', COLV(30));
    L_RESULT(31) := QLPN.O_PT80(31, u'L\1eeba \0111\1ea3o chi\1ebfm \0111o\1ea1t t\00e0i s\1ea3n', COLV(31));
    L_RESULT(32) := QLPN.O_PT80(32, u'C\00e1c t\1ed9i kh\00e1c c\00f2n l\1ea1i v\1ec1 XPSH', COLV(32));
    L_RESULT(33) := QLPN.O_PT80(33, u'C\00e1c t\1ed9i x\00e2m ph\1ea1m TTQL KT', COLV(33));
    L_RESULT(34) := QLPN.O_PT80(34, u'C\00e1c t\1ed9i v\1ec1 ma t\00fay', COLV(34));
    L_RESULT(35) := QLPN.O_PT80(35, u'C\00e1c t\1ed9i CNTT, m\1ea1ng vi\1ec5n th\00f4ng', COLV(35));
    L_RESULT(36) := QLPN.O_PT80(36, u'C\00e1c t\1ed9i v\1ec1 \0111\00e1nh b\1ea1c', COLV(36));
    L_RESULT(37) := QLPN.O_PT80(37, u'C\00e1c t\1ed9i v\1ec1 m\1ea1i d\00e2m', COLV(37));
    L_RESULT(38) := QLPN.O_PT80(38, u'C\00e1c t\1ed9i kh\00e1c c\00f2n l\1ea1i An to\00e0n c\00f4ng c\1ed9ng, tr\1eadt t\1ef1 c\00f4ng c\1ed9ng', COLV(38));
    L_RESULT(39) := QLPN.O_PT80(39, u'C\00e1c t\1ed9i qu\1ea3n l\00fd h\00e0nh ch\00ednh', COLV(39));
    L_RESULT(40) := QLPN.O_PT80(40, u'C\00e1c t\1ed9i v\1ec1 ch\1ee9c v\1ee5', COLV(40));
    L_RESULT(41) := QLPN.O_PT80(41, u'C\00e1c t\1ed9i v\1ec1 t\01b0 ph\00e1p', COLV(41));
    L_RESULT(42) := QLPN.O_PT80(42, u'C\00e1c t\1ed9i \1edf c\00e1c ch\01b0\01a1ng kh\00e1c c\00f2n l\1ea1i', COLV(42));
    L_RESULT(43) := QLPN.O_PT80(43, u'Chung th\00e2n', COLV(43));
    L_RESULT(44) := QLPN.O_PT80(44, u'T\1eeb tr\00ean 15 n\0103m \0111\1ebfn 30 n\0103m', COLV(44));
    L_RESULT(45) := QLPN.O_PT80(45, u'T\1eeb tr\00ean 7 n\0103m \0111\1ebfn 15 n\0103m', COLV(45));
    L_RESULT(46) := QLPN.O_PT80(46, u'T\1eeb tr\00ean 3 n\0103m \0111\1ebfn 7 n\0103m', COLV(46));
    L_RESULT(47) := QLPN.O_PT80(47, u'T\1eeb 3 tr\1edf n\0103m xu\1ed1ng', COLV(47));
    L_RESULT(48) := QLPN.O_PT80(48, u'T\1eeb 14t \0111\1ebfn d\01b0\1edbi 16 tu\1ed5i', COLV(48));
    L_RESULT(49) := QLPN.O_PT80(49, u'T\1eeb 16t \0111\1ebfn d\01b0\1edbi 18 tu\1ed5i', COLV(49));
    L_RESULT(50) := QLPN.O_PT80(50, u'D\01b0\1edbi 18 tu\1ed5i', COLV(50));
    L_RESULT(51) := QLPN.O_PT80(51, u'T\1eeb 18t \0111\1ebfn d\01b0\1edbi 30 tu\1ed5i', COLV(51));
    L_RESULT(52) := QLPN.O_PT80(52, u'T\1eeb 30t \0111\1ebfn d\01b0\1edbi 45 tu\1ed5i', COLV(52));
    L_RESULT(53) := QLPN.O_PT80(53, u'T\1eeb 45t \0111\1ebfn d\01b0\1edbi 60 tu\1ed5i', COLV(53));
    L_RESULT(54) := QLPN.O_PT80(54, u'T\1eeb 60t \0111\1ebfn d\01b0\1edbi 70 tu\1ed5i', COLV(54));
    L_RESULT(55) := QLPN.O_PT80(55, u'Tr\00ean 70 tu\1ed5i', COLV(55));
    L_RESULT(56) := QLPN.O_PT80(56, u'T\00e1i ph\1ea1m', COLV(56));
    L_RESULT(57) := QLPN.O_PT80(57, u'T\00e1i ph\1ea1m nguy hi\1ec3m', COLV(57));
    L_RESULT(58) := QLPN.O_PT80(58, u'N\01b0\1edbc ngo\00e0i', COLV(58));
    L_RESULT(59) := QLPN.O_PT80(59, u'T\00f4n gi\00e1o', COLV(59));
    L_RESULT(60) := QLPN.O_PT80(60, u'D\00e2n t\1ed9c \00edt ng\01b0\1eddi', COLV(60));
    L_RESULT(61) := QLPN.O_PT80(61, u'Kh\00f4ng bi\1ebft ch\1eef', COLV(61));

    SELECT
        COUNT(CASE WHEN (CP.NGAY_DEN IS NULL OR CP.NGAY_DEN <= V_DEN_NGAY)
                        AND (V_NAM_HIEN_TAI - TO_NUMBER(SUBSTR(CP.NGAY_SINH, -4))) < 2 THEN 1 END),
        COUNT(CASE WHEN CP.NGAY_DEN <= V_DEN_NGAY
                        AND (V_NAM_HIEN_TAI - TO_NUMBER(SUBSTR(CP.NGAY_SINH, -4))) = 2 THEN 1 END),
        COUNT(CASE WHEN CP.NGAY_DEN <= V_DEN_NGAY
                        AND (V_NAM_HIEN_TAI - TO_NUMBER(SUBSTR(CP.NGAY_SINH, -4))) >= 3 THEN 1 END)
    INTO COLV(62), COLV(63), COLV(64)
    FROM QLPN.TK_PT80 LL
    JOIN QLPN.THAN_NHAN_CON_CAIS CP
        ON CP.PHAM_NHAN_ID = LL.PN_LAI_LICH_ID
       AND CP.IS_DELETED = 0
    WHERE NVL(CP.NGAY_RA, V_DEN_NGAY_EXCL) > V_DEN_NGAY
      AND CP.NGAY_SINH IS NOT NULL
      AND CP.IS_DELETED = 0;

    L_RESULT.EXTEND;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(62, u'Con PN d\01b0\1edbi 24 th\00e1ng', COLV(61));
    L_RESULT.EXTEND;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(63, u'Con PN d\01b0\1edbi t\1eeb 24 \0111\1ebfn d\01b0\1edbi 36 th\00e1ng', COLV(62));
    L_RESULT.EXTEND;
    L_RESULT(L_RESULT.COUNT) := QLPN.O_PT80(64, u'T\1eeb 36 th\00e1ng tr\1edf l\00ean', COLV(63));

    COLV(1) := COLV(20) - COLV(8) + COLV(16);
    L_RESULT(1) := QLPN.O_PT80(1, u'S\1ed1 th\00e1ng tr\01b0\1edbc chuy\1ec3n sang', COLV(1));

    OPEN L_CUR FOR
        SELECT *
        FROM (
            SELECT STT, SL
            FROM TABLE(L_RESULT)
        )
        PIVOT (
            MAX(SL) FOR STT IN (
                1 AS "1", 2 AS "2", 3 AS "3", 4 AS "4", 5 AS "5",
                6 AS "6", 7 AS "7", 8 AS "8", 9 AS "9", 10 AS "10",
                11 AS "11", 12 AS "12", 13 AS "13", 14 AS "14", 15 AS "15",
                16 AS "16", 17 AS "17", 18 AS "18", 19 AS "19", 20 AS "20",
                21 AS "21", 22 AS "22", 23 AS "23", 24 AS "24", 25 AS "25",
                26 AS "26", 27 AS "27", 28 AS "28", 29 AS "29", 30 AS "30",
                31 AS "31", 32 AS "32", 33 AS "33", 34 AS "34", 35 AS "35",
                36 AS "36", 37 AS "37", 38 AS "38", 39 AS "39", 40 AS "40",
                41 AS "41", 42 AS "42", 43 AS "43", 44 AS "44", 45 AS "45",
                46 AS "46", 47 AS "47", 48 AS "48", 49 AS "49", 50 AS "50",
                51 AS "51", 52 AS "52", 53 AS "53", 54 AS "54", 56 AS "55",
                57 AS "56", 58 AS "57", 59 AS "58", 60 AS "59", 61 AS "60",
                62 AS "61", 63 AS "62", 64 AS "63", 54 AS "64", 55 AS "65"
            )
        );

    DBMS_SQL.RETURN_RESULT(L_CUR);
    COMMIT;
END SP_GET_PT80_NU;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_QLPN_B2_IN_BIEU_MAU_KET_THUC_HO_SO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_QLPN_B2_IN_BIEU_MAU_KET_THUC_HO_SO" (
    p_pham_nhan_ids IN VARCHAR2
)
AS
    p_cursor SYS_REFCURSOR;
BEGIN
    OPEN p_cursor FOR
    SELECT *
    FROM (
        SELECT
            hs.NGAY_DK             				 AS "NgayLapHoSo",
            NULL                                 AS "CanCuQuyetDinh",

            --BÊN GIAO (BG)
            hs.HO_TEN_BG                         AS "HoTenBenGiao",
            cvbg.CV_TEN                          AS "ChucVuBenGiao",
            cbg.CB_TEN                           AS "CapBacBenGiao",
            cqg.CQ_TEN                           AS "DonViBenGiao",

            --BÊN NH?N (BN)
            hs.HO_TEN_BN                         AS "HoTenBenNhan",
            cvbn.CV_TEN                          AS "ChucVuBenNhan",
            cbn.CB_TEN                           AS "CapBacBenNhan",
            cqn.CQ_TEN                           AS "DonViBenNhan",


            --CÁN B? ??NG KÝ (DK)
            hs.HO_TEN_DK                         AS "TenCanBoDangKy",
            cvcb.CV_TEN                          AS "ChucVuCanBoDangKy",
            cbc.CB_TEN                           AS "CapBacCanBoDangKy",
            cqc.CQ_TEN                           AS "DonViCanBoDangKy",

            --PH?M NHÂN
            vpllct.SO_HO_SO                      AS "SoHSLD",
            vpllct.HO_TEN                        AS "HoTen",
            vpllct.NAM_SINH                      AS "NamSinh",
            vpllct.GIOI_TINH                     AS "GioiTinh",
            vpllct.NOI_THUONG_TRU_DAY_DU         AS "DiaChiThuongTru",
            vpllct.TOI_DANH                      AS "ToiDanh",
            vpllct.NGAY_BAT_AN_PHAT              AS "NgayBat",
            vpllct.AN_PHAT                       AS "AnPhat",

			ROW_NUMBER() OVER (
			    PARTITION BY pll.ID
			    ORDER BY hspn.CREATION_TIME DESC,   -- ? ?u tiên theo th?i gian t?o
			             hspn.PN_HSNV_KT_ID DESC    -- D? phòng n?u CREATION_TIME b?ng nhau
			) rn

        FROM PN_LAI_LICHS pll
        JOIN VW_PN_LAI_LICH_CHI_TIET vpllct
            ON pll.ID = vpllct.PHAM_NHAN_ID
		LEFT JOIN PN_HSNV_KT_PHAM_NHANS hspn
		    ON hspn.PN_LAI_LICH_ID = pll.ID
		    AND hspn.IS_DELETED = 0
		LEFT JOIN PN_HSNV_KTS hs
		    ON hs.ID = hspn.PN_HSNV_KT_ID
        LEFT JOIN DM_CHUC_VUS cvbg
	        ON hs.CHUC_VU_BG = TO_CHAR(cvbg.ID) 
	    LEFT JOIN DM_CHUC_VUS cvbn
	        ON hs.CHUC_VU_BN = TO_CHAR(cvbn.ID)
	    LEFT JOIN DM_CHUC_VUS cvcb
	        ON hs.CHUC_VU_DK = TO_CHAR(cvcb.ID)
	    LEFT JOIN DM_CO_QUANS cqg
        	ON hs.MA_CQ_BG = TO_CHAR(cqg.ID)
        LEFT JOIN DM_CO_QUANS cqn
        	ON hs.MA_CQ_BN = TO_CHAR(cqn.ID)
        LEFT JOIN DM_CO_QUANS cqc
        	ON hs.MA_CQ_DK = TO_CHAR(cqc.ID)
        LEFT JOIN DM_CAP_BACS cbg
        	ON hs.CAP_BAC_BG = TO_CHAR(cbg.ID)
        LEFT JOIN DM_CAP_BACS cbn
        	ON hs.CAP_BAC_BN = TO_CHAR(cbn.ID)
        LEFT JOIN DM_CAP_BACS cbc
        	ON hs.CAP_BAC_DK = TO_CHAR(cbc.ID)

        -- x? lý multiple ID
        WHERE pll.ID IN (
            SELECT TO_NUMBER(REGEXP_SUBSTR(p_pham_nhan_ids, '[^,]+', 1, LEVEL))
            FROM dual
            CONNECT BY REGEXP_SUBSTR(p_pham_nhan_ids, '[^,]+', 1, LEVEL) IS NOT NULL
        )
    ) rs
    WHERE rn = 1

    ORDER BY FN_SWAP_FIRST_LAST_SORT(rs."HoTen");

    DBMS_SQL.RETURN_RESULT(p_cursor); 
END;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_QLPN_DS_DU_DK_GTH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_QLPN_DS_DU_DK_GTH" 
(
    p_PHAM_NHAN_ID  IN  NVARCHAR2   DEFAULT NULL,
    p_ma_trai_giam  IN  NVARCHAR2   DEFAULT NULL,
    p_ngay_xet      IN  NVARCHAR2   DEFAULT NULL
)
AS p_cursor SYS_REFCURSOR;

BEGIN OPEN p_cursor FOR
WITH
	pn_csv AS (
		SELECT
			REPLACE(
				REPLACE(
					TRIM(CAST(p_PHAM_NHAN_ID AS VARCHAR2 (4000))),
					'[',
					''
				),
				']',
				''
			) AS csv
		FROM
			DUAL
		WHERE
			p_PHAM_NHAN_ID IS NOT NULL
			AND LENGTH(TRIM(CAST(p_PHAM_NHAN_ID AS VARCHAR2 (4000)))) > 0
	),
	pn_ids AS (
		SELECT
			/*+ MATERIALIZE */ DISTINCT TO_NUMBER (REGEXP_SUBSTR (c.csv, '[0-9]+', 1, LEVEL)) AS pn_id
		FROM
			pn_csv c
		WHERE
			REGEXP_LIKE(
				REGEXP_SUBSTR (c.csv, '[0-9]+', 1, LEVEL),
				'^[0-9]+$'
			) CONNECT BY LEVEL <= REGEXP_COUNT (c.csv, '[0-9]+')
			AND PRIOR c.csv = c.csv
			AND PRIOR SYS_GUID () IS NOT NULL
	),
	gth_src AS (
		SELECT
			/*+ MATERIALIZE */ g.*
		FROM
			QLPN.GIAM_THOI_HANS g
		WHERE
			NVL(g.IS_DELETED, 0) = 0
			AND (p_ngay_xet IS NULL OR (g.NGAY_XET >= TRUNC(TO_DATE(p_ngay_xet, 'DD/MM/YYYY')) AND g.NGAY_XET < TRUNC(TO_DATE(p_ngay_xet, 'DD/MM/YYYY')) + 1))
			AND (
				p_PHAM_NHAN_ID IS NULL
				OR LENGTH(TRIM(CAST(p_PHAM_NHAN_ID AS VARCHAR2 (4000)))) = 0
				OR g.PHAM_NHAN_ID IN (
					SELECT
						i.pn_id
					FROM
						pn_ids i
				)
			)
	),
	gth_pn AS (
		SELECT
			/*+ MATERIALIZE */
			DISTINCT PHAM_NHAN_ID
		FROM
			gth_src
	),
	pn_calc AS (
		SELECT
			gp.PHAM_NHAN_ID,
			QLPN.PKG_TINH_AN.FN_TINH_SO_LAN_GIAM_AN(gp.PHAM_NHAN_ID) AS LAN_GIAM_AN,
			QLPN.PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(gp.PHAM_NHAN_ID) AS GIAM_AN,
			QLPN.FN_GET_LIET_KE_HPBS_CHI_TIET(gp.PHAM_NHAN_ID) AS HINH_PHAT_BO_SUNG
		FROM
			gth_pn gp
	),
	giam_agg AS (
		SELECT
			gth.PHAM_NHAN_ID,
			NVL(
				SUBSTR(
					LISTAGG(NVL(dm.MTG_TITLE, gth.DA_GIAM), CHR(10)) WITHIN GROUP (
						ORDER BY
							gth.NGAY_QUYET_DINH NULLS LAST,
							gth.NGAY_XET NULLS LAST,
							gth.ID
					),
					1,
					4000
				),
				u'Kh\00f4ng'
			) AS CAC_LAN_GIAM
		FROM
			QLPN.GIAM_THOI_HANS gth
			INNER JOIN gth_pn gp ON gp.PHAM_NHAN_ID = gth.PHAM_NHAN_ID
			LEFT JOIN QLPN.DM_MA_THOI_GIANS dm ON dm.ID = gth.MUC_GIAM_ID
			AND NVL(dm.IS_DELETED, 0) = 0
		WHERE
			NVL(gth.IS_DELETED, 0) = 0
			AND gth.MUC_GIAM_ID IS NOT NULL
		GROUP BY
			gth.PHAM_NHAN_ID
	),
	core AS (
		SELECT
			g.PHAM_NHAN_ID,
			v.HO_TEN,
			NVL(v.TEN_KHAC, u'') AS TEN_KHAC,
			v.NAM_SINH,
			v.NGAY_SINH,
			v.GIOI_TINH,
			v.NOI_THUONG_TRU_DAY_DU,
			v.DIA_CHI_THUONG_TRU,
			v.PHUONG_XA_THUONG_TRU,
			v.TINH_THANH_THUONG_TRU,
			v.TOI_DANH_ID,
			v.TOI_DANH,
			v.NGAY_BAT_AN_PHAT AS NGAY_BAT,
			v.AN_PHAT,
			v.SO_TIEN_AN,
			g.NGAY_XET,
			NVL(TRIM(CAST(dm_mg.MTG_TITLE AS NVARCHAR2(4000))), NVL(g.DA_GIAM, u'')) AS MUC_GIAM,
			NVL(TRIM(CAST(dm_dn.MTG_TITLE AS NVARCHAR2(4000))), u'') AS MUC_GIAM_DE_NGHI,
			NVL(TRIM(CAST(dm_ctd.MTG_TITLE AS NVARCHAR2(4000))), u'') AS MUC_GIAM_CAP_TREN_DUYET,
			NVL(
				QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(g.PHAM_NHAN_ID, CAST(g.NGAY_XET AS DATE)),
				u''
			) AS DA_CHAP_HANH,
			NVL(
				QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(g.PHAM_NHAN_ID, CAST(g.NGAY_XET AS DATE)),
				u''
			) AS THOI_GIAN_CON_LAI,
			v.THA_NGAY_DEN_TRAI AS NGAY_DEN,
			CASE
				WHEN xep.XEP_LOAI_NAM IS NULL THEN NULL
				ELSE TO_NCHAR(xep.XEP_LOAI_NAM) || u': Q1: ' || NVL(dm_q1.XLCT_TEN, u'') || u', Q2: ' || NVL(dm_q2.XLCT_TEN, u'') || u', Q3: ' || NVL(dm_q3.XLCT_TEN, u'') || u', Q4: ' || NVL(dm_q4.XLCT_TEN, u'')
			END AS KET_QUA_CAI_TAO,
			xep.XEP_LOAI_NAM AS NAM,
			NVL(dm_ca.XLCT_TEN, u'') AS KQ_CAI_TAO_NAM,
			NVL(dm_q1.XLCT_TEN, u'') AS KQ_CAI_TAO_QUY_1,
			NVL(dm_q2.XLCT_TEN, u'') AS KQ_CAI_TAO_QUY_2,
			NVL(dm_q3.XLCT_TEN, u'') AS KQ_CAI_TAO_QUY_3,
			NVL(dm_q4.XLCT_TEN, u'') AS KQ_CAI_TAO_QUY_4,
			v.phan_doi,
			v.phan_trai,
			CAST(SUBSTR(g.NHAN_XET, 1, 4000) AS NVARCHAR2(4000)) AS GHI_CHU,
			v.HO_TEN_ORDER
		FROM
			gth_src g
			LEFT JOIN (
				SELECT
					v2.*,
					ROW_NUMBER() OVER (
						PARTITION BY v2.PHAM_NHAN_ID
						ORDER BY
							NVL(v2.NGAY_HET_AN, v2.CREATION_TIME) DESC NULLS LAST,
							v2.CREATION_TIME DESC NULLS LAST
					) AS rn
				FROM
					QLPN.VW_PN_LAI_LICH_CHI_TIET v2
				WHERE
					NVL(v2.IS_DELETED, 0) = 0
					AND (p_ma_trai_giam IS NULL OR v2.TRAI_GIAM_MA = p_ma_trai_giam)
			) v ON v.PHAM_NHAN_ID = g.PHAM_NHAN_ID AND v.rn = 1
			LEFT JOIN QLPN.XEP_LOAIS xep ON xep.PHAM_NHAN_ID = g.PHAM_NHAN_ID
			AND NVL(xep.IS_DELETED, 0) = 0
			AND xep.XEP_LOAI_NAM = EXTRACT(
				YEAR
				FROM
					g.NGAY_XET
			)
			LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm_ca ON dm_ca.ID = xep.XEP_LOAI_CA_NAM
			AND NVL(dm_ca.IS_DELETED, 0) = 0
			LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm_q1 ON dm_q1.ID = xep.XEP_LOAI_QUY_I
			AND NVL(dm_q1.IS_DELETED, 0) = 0
			LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm_q2 ON dm_q2.ID = xep.XEP_LOAI_QUY_II
			AND NVL(dm_q2.IS_DELETED, 0) = 0
			LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm_q3 ON dm_q3.ID = xep.XEP_LOAI_QUY_III
			AND NVL(dm_q3.IS_DELETED, 0) = 0
			LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm_q4 ON dm_q4.ID = xep.XEP_LOAI_QUY_IV
			AND NVL(dm_q4.IS_DELETED, 0) = 0
			LEFT JOIN QLPN.DM_MA_THOI_GIANS dm_mg ON dm_mg.ID = g.MUC_GIAM_ID
			AND NVL(dm_mg.IS_DELETED, 0) = 0
			LEFT JOIN QLPN.DM_MA_THOI_GIANS dm_dn ON dm_dn.ID = g.MUC_DE_NGHI_ID
			AND NVL(dm_dn.IS_DELETED, 0) = 0
			LEFT JOIN QLPN.DM_MA_THOI_GIANS dm_ctd ON dm_ctd.ID = g.CAP_TREN_DUYET_ID
			AND NVL(dm_ctd.IS_DELETED, 0) = 0
	)
SELECT
	r.PHAM_NHAN_ID,
	r.HO_TEN,
	r.TEN_KHAC,
	r.NAM_SINH,
	r.NGAY_SINH,
	r.GIOI_TINH,
	r.NOI_THUONG_TRU_DAY_DU,
	r.DIA_CHI_THUONG_TRU,
	r.PHUONG_XA_THUONG_TRU,
	r.TINH_THANH_THUONG_TRU,
	r.TOI_DANH_ID,
	r.TOI_DANH,
	TO_CHAR(r.NGAY_BAT, 'DD/MM/YYYY') AS NGAY_BAT,
	r.AN_PHAT,
	r.SO_TIEN_AN,
	r.NGAY_XET,
	pc.LAN_GIAM_AN,
	pc.GIAM_AN,
	pc.GIAM_AN AS TONG_GIAM_AN,
	r.MUC_GIAM,
	r.MUC_GIAM_DE_NGHI,
	r.MUC_GIAM_CAP_TREN_DUYET,
	NVL(ga.CAC_LAN_GIAM, u'Kh\00f4ng') AS CAC_LAN_GIAM,
	r.DA_CHAP_HANH,
	r.THOI_GIAN_CON_LAI,
	r.NGAY_DEN,
	r.KET_QUA_CAI_TAO AS TONG_HOP_KET_QUA_CAI_TAO,
	r.KET_QUA_CAI_TAO,
	r.GHI_CHU,
	pc.HINH_PHAT_BO_SUNG,
	r.NAM,
	r.KQ_CAI_TAO_NAM,
	r.KQ_CAI_TAO_QUY_1,
	r.KQ_CAI_TAO_QUY_2,
	r.KQ_CAI_TAO_QUY_3,
	r.KQ_CAI_TAO_QUY_4,
	r.phan_doi,
	r.phan_trai,
	r.HO_TEN_ORDER
FROM
	core r
	LEFT JOIN pn_calc pc ON pc.PHAM_NHAN_ID = r.PHAM_NHAN_ID
	LEFT JOIN giam_agg ga ON ga.PHAM_NHAN_ID = r.PHAM_NHAN_ID
ORDER BY
	r.HO_TEN_ORDER,
	r.PHAM_NHAN_ID;

DBMS_SQL.RETURN_RESULT (p_cursor);

END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_QLPN_PHIEU_GIAM
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_QLPN_PHIEU_GIAM" (
    --p_PHAM_NHAN_ID IN VARCHAR2 DEFAULT NULL,
    p_ma_trai_giam            IN  NVARCHAR2 DEFAULT NULL
) AS
    p_cursor SYS_REFCURSOR;
BEGIN
    OPEN p_cursor FOR
    WITH
    ID_LIST AS (
    SELECT PN_ID FROM QLPN.GTT_PN_IDS
    ),
    LL_one AS (
        SELECT * FROM (
            SELECT v.*
            FROM VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
            and (p_ma_trai_giam is null or v.TRAI_GIAM_MA = p_ma_trai_giam)
            -- L?c s?m theo p_PHAM_NHAN_ID ?? gcr_raw/gcr_ids ch? x? lý ph?m nhân ???c yêu c?u
            and (NOT EXISTS (SELECT 1 FROM QLPN.GTT_PN_IDS)
                or v.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
        ) x
    ),
    gcr_raw AS (
        SELECT
            ll.PHAM_NHAN_ID,
            REPLACE(REPLACE(TRIM(NVL(ll.GHI_CHU_RIENG, '[]')), '[', ''), ']', '') AS csv
        FROM LL_one ll
    ),
    gcr_ids AS (
        SELECT
            r.PHAM_NHAN_ID,
            CASE
                WHEN REGEXP_LIKE(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
                THEN TO_NUMBER(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)))
            END AS gcr_id
        FROM gcr_raw r
        WHERE TRIM(r.csv) IS NOT NULL
          AND LENGTH(TRIM(r.csv)) > 0
        CONNECT BY LEVEL <= REGEXP_COUNT(r.csv, ',') + 1
          AND PRIOR r.PHAM_NHAN_ID = r.PHAM_NHAN_ID
          AND PRIOR SYS_GUID() IS NOT NULL
          AND REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL) IS NOT NULL
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
    ),
    gcr_agg AS (
        SELECT
            x.PHAM_NHAN_ID,
            LISTAGG(TRIM(CAST(g.GCR_TEN AS VARCHAR2(500))), ', ')
                WITHIN GROUP (ORDER BY x.gcr_id) AS ghi_chu_rieng_text
        FROM gcr_ids x
        INNER JOIN DM_GHI_CHU_RIENGS g
            ON g.ID = x.gcr_id
           AND NVL(g.IS_DELETED, 0) = 0
        WHERE x.gcr_id IS NOT NULL
        GROUP BY x.PHAM_NHAN_ID
    ),
    THA_one AS (
        SELECT * FROM (
            SELECT t.*
            FROM PN_THI_HANH_AN t
            WHERE NVL(t.IS_DELETED, 0) = 0
        ) x 
    ),
    GTH_one AS (
        SELECT * FROM (
            SELECT g.*, ROW_NUMBER() OVER (PARTITION BY g.PHAM_NHAN_ID
                ORDER BY g.NGAY_XET DESC NULLS LAST,
                         g.CREATION_TIME DESC NULLS LAST,
                         g.ID DESC) AS rn
            FROM GIAM_THOI_HANS g
            WHERE NVL(g.IS_DELETED, 0) = 0
        ) x WHERE rn = 1
    ),
    -- M?i ph?m nhân ch? l?y 1 b? (121), 1 m? (122), 1 v?/ch?ng (131/132 g?p chung nhóm)
    TN_one AS (
        SELECT * FROM (
            SELECT t.*, ROW_NUMBER() OVER (PARTITION BY t.PHAM_NHAN_ID,
                    CASE WHEN t.MA_QUAN_HE IN ('131','132') THEN u'VC' ELSE t.MA_QUAN_HE END
                ORDER BY t.CREATION_TIME DESC NULLS LAST,
                         t.ID DESC) AS rn
            FROM VW_THAN_NHAN t
            WHERE t.MA_QUAN_HE IN ('121','122','131','132')
        ) x WHERE rn = 1
    )
    SELECT
            GTH.PHAM_NHAN_ID AS PHAM_NHAN_ID,
            'C?C C10' AS CQ_CHU_QUAN,
            UPPER(LL.TRAI_GIAM) AS TEN_TRAI_HOA,
            GTH.SO_QUYET_DINH AS SO_DE_NGHI,
            GTH.NGAY_XET AS NGAY_BC,
            UPPER(LL.HO_TEN) AS HO_TEN_HOA,
            NVL(LL.TEN_KHAC, '') AS TEN_KHAC,
            LL.GIOI_TINH AS GIOI_TINH,
            LL.NAM_SINH AS NAM_SINH,
            LL.NGUYEN_QUAN AS NGUYEN_QUAN,
            LL.NOI_THUONG_TRU_DAY_DU AS DIA_CHI_TT,
            LL.NOI_O_KHAC AS CHO_O_KHAC,
            LL.DAN_TOC AS DAN_TOC,
            LL.QUOC_TICH AS QUOC_TICH,
            LL.HOC_VAN AS HOC_VAN,
            LL.NGHE_NGHIEP AS NGHE_NGHIEP,
            LL.TOI_DANH AS TOI_DANH,
            TO_CHAR(THA.THA_NGAY_BAT, 'DD/MM/YYYY') AS NGAY_BAT,
            THA.THA_AN_PHAT AS AN_PHAT,
            NVL(THA.THA_THOI_GIAN_TAM_GIAM, u'Kh\00f4ng') AS TG_TAM_GIAM,
            NVL(THA.THA_THOI_GIAN_TAM_GIU, u'Kh\00f4ng') AS TG_TAM_GIU,
            CTX.CTX_TEN AS BA_QD,
            THA.THA_SO_BAN_AN AS BAN_AN_SO,
            TO_CHAR(THA.THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS NGAY_XU,
            --LL.TOA_XU_TEN AS TOA_XU,
            LL.toa_xu_ten || ', ' || NVL(LL.toa_xu_dia_phuong, '') AS TOA_XU,
            THA.THA_SO_QD_THA AS SO_QD_THAN,
            TO_CHAR(THA.THA_NGAY_QD_THA, 'DD/MM/YYYY') AS NGAY_QD_THAN,
            LL.CO_QUAN_QD_THA || ', ' || NVL(LL.TOA_QD_THA_DIA_PHUONG, '') AS TOA_QD_THAN,
            NVL(LL.TOA_QD_THA_DIA_PHUONG, '') AS TOA_QD_THAN_DIA_PHUONG,
            TO_CHAR(LL.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
            TO_CHAR(GTH.NGAY_XET, 'DD/MM/YYYY') AS NGAY_XET,
            --GTH.DA_CHAP_HANH AS TG_CHAP_HANH,
            QLPN.FN_GET_DA_CHAP_HANH_TEXT(GTH.PHAM_NHAN_ID, GTH.NGAY_XET) AS TG_CHAP_HANH,
            FN_GET_TONG_SO_NGAY_TRON(GTH.PHAM_NHAN_ID) AS TG_TRON,
            FN_SO_NGAY_TAM_DINH_CHI(GTH.PHAM_NHAN_ID) AS TAM_DINH_CHI,
            QLPN.PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(GTH.PHAM_NHAN_ID) AS GIAM_AN,
            QLPN.FN_TINH_AN_DA_GIAM_CHI_TIET_GTH(GTH.PHAM_NHAN_ID,NGAY_XET) AS GIAM_AN_CHI_TIET,
            NVL(
                (
                    SELECT SUBSTR(
                        LISTAGG(
                            TRIM(
                                CASE
                                    WHEN NVL(x.MHP_THM_YEAR, 0) > 0
                                    THEN TO_NCHAR(x.MHP_THM_YEAR) || u' n\0103m '
                                    ELSE u''
                                END
                                || CASE
                                       WHEN NVL(x.MHP_THM_MONTH, 0) > 0
                                       THEN TO_NCHAR(x.MHP_THM_MONTH) || u' th\00e1ng '
                                       ELSE u''
                                   END
                                || CASE
                                       WHEN NVL(x.MHP_THM_DAY, 0) > 0
                                       THEN TO_NCHAR(x.MHP_THM_DAY) || u' ng\00e0y'
                                       ELSE u''
                                   END
                            ),
                            NCHR(10) ON OVERFLOW TRUNCATE u'...' WITH COUNT
                        ) WITHIN GROUP (ORDER BY x.MHP_NGAY_QUYET_DINH NULLS LAST, x.ID),
                        1,
                        4000
                    )
                    FROM QLPN.MIEN_HINH_PHATS x
                    WHERE x.PN_LAI_LICH_ID = GTH.PHAM_NHAN_ID
                      AND NVL(x.IS_DELETED, 0) = 0
                      AND NVL(x.MHP_THM_YEAR, 0) + NVL(x.MHP_THM_MONTH, 0) + NVL(x.MHP_THM_DAY, 0) > 0
                ),
                u'Kh\00f4ng'
            ) AS MIEN_GIAM_HP,
            --dmtg_cl.MTG_TITLE AS TG_CON_LAI,
            QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(GTH.PHAM_NHAN_ID, GTH.NGAY_XET) AS TG_CON_LAI,
            NVL(FN_GET_LIET_KE_HPBS(GTH.PHAM_NHAN_ID), u'Kh\00f4ng') AS HINH_PHAT_BO_SUNG,
            LL.SO_TIEN_AN AS SO_TA,
            FN_GET_TIEN_AN_TONG_HOP(GTH.PHAM_NHAN_ID).CHI_TIET_TIEN_AN AS TIEN_AN,
            CASE WHEN FN_TONG_HOP_TIEN_SU(GTH.PHAM_NHAN_ID).SO_TIEN_SU = 0 THEN u'Kh\00f4ng'
            ELSE TO_NCHAR(FN_TONG_HOP_TIEN_SU(GTH.PHAM_NHAN_ID).SO_TIEN_SU)
            END AS SO_TS, 
            FN_TONG_HOP_TIEN_SU(GTH.PHAM_NHAN_ID).HANH_VI_TIEN_SU AS TIEN_SU,
            LL.TINH_TRANG_SUC_KHOE AS SUC_KHOE,
            NVL(
                CAST(ga.ghi_chu_rieng_text AS NVARCHAR2(2000)),
                NVL(TRIM(CAST(LL.GHI_CHU_RIENG AS NVARCHAR2(2000))), u'Không')
            ) AS GHI_CHU_RIENG,
            LL.TOM_TAT_HANH_VI AS TOM_TAT_HANH_VI_PHAM_TOI,
            NVL(
                NULLIF(TRIM(CAST(NVL(TO_NCHAR(BO.HO_TEN_THAN_NHAN), u'') AS NVARCHAR2(2000))), u''),
                u'Kh\00f4ng c\00f3'
            ) AS HO_TEN_BO,
            BO.NOI_O AS NOI_O_BO,
            NVL(
                NULLIF(TRIM(CAST(NVL(TO_NCHAR(ME.HO_TEN_THAN_NHAN), u'') AS NVARCHAR2(2000))), u''),
                u'Kh\00f4ng c\00f3'
            ) AS HO_TEN_ME,
            ME.NOI_O AS NOI_O_ME,
--            NVL(
--                NULLIF(TRIM(CAST(NVL(TO_NCHAR(VC.QUAN_HE), u'') AS NVARCHAR2(2000))), u''),
--                u'Kh\00f4ng c\00f3'
--            ) AS VO_CHONG,
            CASE WHEN LL.GIOI_TINH = 'Nam' THEN 'v?' ELSE 'ch?ng' END as VO_CHONG,
            NVL(
                NULLIF(TRIM(CAST(NVL(TO_NCHAR(VC.HO_TEN_THAN_NHAN), u'') AS NVARCHAR2(2000))), u''),
                u'Kh\00f4ng c\00f3'
            ) AS HO_TEN_VO_CHONG,
            VC.NOI_O AS NOI_O_VC,
            FN_GET_TEN_CON_CAI(GTH.PHAM_NHAN_ID) AS CAC_CONS,
			gdk.DDKCT_GHI_CHU AS XEP_LOAI_CAI_TAO,
            GTH.NHAN_XET AS NHAN_XET_TG,
            MTG.MTG_TITLE AS MUC_DE_NGHI,
            NVL(TRIM(CAST(dttp.TTP_TEN AS NVARCHAR2(2000))), u'') AS DIA_DANH
        FROM GTH_one GTH
        LEFT JOIN LL_one LL ON LL.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID
        LEFT JOIN GTH_KY_GIAM_THOI_HANS gk ON GTH.NGAY_XET = gk.KGTH_NGAY_XET_GIAM
            AND NVL(gk.IS_DELETED, 0) = 0
            AND gk.KGTH_TRAI_GIAM_MA = LL.TRAI_GIAM_MA
        LEFT JOIN GTH_DU_DIEU_KIEN_CHI_TIETS gdk ON LL.PHAM_NHAN_ID = gdk.DDKCT_PN_ID
        AND  gdk.DDKCT_KY_ID = gk.ID
        LEFT JOIN gcr_agg ga ON ga.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID
        LEFT JOIN THA_one THA ON THA.THA_PNLAI_LICH_ID = GTH.PHAM_NHAN_ID
        LEFT JOIN DM_CAP_TOA_XUS CTX ON CTX.ID = THA.THA_LOAI_BAN_AN_ID AND NVL(CTX.IS_DELETED, 0) = 0
        LEFT JOIN DM_CO_QUANS CQBA ON CQBA.ID = THA.THA_CAP_TOA_ID AND CQBA.IS_DELETED = 0
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg_cl on DMTG_CL.MTG_MA = tha.THA_THOI_GIAN_CON_LAI
        LEFT JOIN DM_MA_THOI_GIANS MTG ON MTG.ID = GTH.MUC_DE_NGHI_ID AND MTG.IS_DELETED = 0
        LEFT JOIN DM_TINH_THANH_PHO dttp ON dttp.ID = GTH.DIA_PHUONG_ID AND NVL(dttp.IS_DELETED, 0) = 0
        LEFT JOIN TN_one BO
        ON BO.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID
        AND BO.MA_QUAN_HE = '121'
        LEFT JOIN TN_one ME
        ON ME.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID
        AND ME.MA_QUAN_HE = '122'
        LEFT JOIN TN_one VC
        ON VC.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID
        AND VC.MA_QUAN_HE IN ('131', '132')
        WHERE (NOT EXISTS (SELECT 1 FROM QLPN.GTT_PN_IDS)
                OR GTH.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
		ORDER BY HO_TEN_ORDER;
    DBMS_SQL.RETURN_RESULT(p_cursor);

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('L?i: ' || SQLERRM);
        RAISE;
END SP_GET_QLPN_PHIEU_GIAM;

