                THEN TO_NUMBER(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)))
            END AS gcr_id
        FROM gcr_raw r
        WHERE TRIM(r.csv) IS NOT NULL
          AND LENGTH(TRIM(r.csv)) > 0
        CONNECT BY LEVEL <= REGEXP_COUNT(r.csv, ',') + 1
          AND PRIOR r.PHAM_NHAN_ID = r.PHAM_NHAN_ID
          AND PRIOR SYS_GUID() IS NOT NULL
          AND REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL) IS NOT NULL
          AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(r.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
    ),
    gcr_agg AS (
        SELECT
            x.PHAM_NHAN_ID,
            LISTAGG(TRIM(CAST(g.GCR_TEN AS VARCHAR2(500))), ', ')
                WITHIN GROUP (ORDER BY x.gcr_id) AS ghi_chu_rieng_text
        FROM gcr_ids x
        INNER JOIN DM_GHI_CHU_RIENGS g
            ON g.ID = x.gcr_id
           AND NVL(g.IS_DELETED, 0) = 0
        WHERE x.gcr_id IS NOT NULL
        GROUP BY x.PHAM_NHAN_ID
    ),
    THA_one AS (
        SELECT * FROM (
            SELECT t.*
            FROM PN_THI_HANH_AN t
            WHERE NVL(t.IS_DELETED, 0) = 0
        ) x 
    ),
    GTH_one AS (
        SELECT * FROM (
            SELECT g.*, ROW_NUMBER() OVER (PARTITION BY g.PHAM_NHAN_ID
                ORDER BY g.NGAY_XET DESC NULLS LAST,
                         g.CREATION_TIME DESC NULLS LAST,
                         g.ID DESC) AS rn
