            CTX.CTX_TEN AS BA_QD,
            THA.THA_SO_BAN_AN AS BAN_AN_SO,
            TO_CHAR(THA.THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS NGAY_XU,
            --LL.TOA_XU_TEN AS TOA_XU,
            LL.toa_xu_ten || ', ' || NVL(LL.toa_xu_dia_phuong, '') AS TOA_XU,
            THA.THA_SO_QD_THA AS SO_QD_THAN,
            TO_CHAR(THA.THA_NGAY_QD_THA, 'DD/MM/YYYY') AS NGAY_QD_THAN,
            LL.CO_QUAN_QD_THA || ', ' || NVL(LL.TOA_QD_THA_DIA_PHUONG, '') AS TOA_QD_THAN,
            NVL(LL.TOA_QD_THA_DIA_PHUONG, '') AS TOA_QD_THAN_DIA_PHUONG,
            TO_CHAR(LL.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
            TO_CHAR(GTH.NGAY_XET, 'DD/MM/YYYY') AS NGAY_XET,
            --GTH.DA_CHAP_HANH AS TG_CHAP_HANH,
            QLPN.FN_GET_DA_CHAP_HANH_TEXT(GTH.PHAM_NHAN_ID, GTH.NGAY_XET) AS TG_CHAP_HANH,
            FN_GET_TONG_SO_NGAY_TRON(GTH.PHAM_NHAN_ID) AS TG_TRON,
            FN_SO_NGAY_TAM_DINH_CHI(GTH.PHAM_NHAN_ID) AS TAM_DINH_CHI,
            QLPN.PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(GTH.PHAM_NHAN_ID) AS GIAM_AN,
            QLPN.FN_TINH_AN_DA_GIAM_CHI_TIET_GTH(GTH.PHAM_NHAN_ID,NGAY_XET) AS GIAM_AN_CHI_TIET,
            NVL(
                (
                    SELECT SUBSTR(
                        LISTAGG(
                            TRIM(
                                CASE
                                    WHEN NVL(x.MHP_THM_YEAR, 0) > 0
                                    THEN TO_NCHAR(x.MHP_THM_YEAR) || u' n\0103m '
                                    ELSE u''
                                END
                                || CASE
