                        ) WITHIN GROUP (ORDER BY x.MHP_NGAY_QUYET_DINH NULLS LAST, x.ID),
                        1,
                        4000
                    )
                    FROM QLPN.MIEN_HINH_PHATS x
                    WHERE x.PN_LAI_LICH_ID = GTH.PHAM_NHAN_ID
                      AND NVL(x.IS_DELETED, 0) = 0
                      AND NVL(x.MHP_THM_YEAR, 0) + NVL(x.MHP_THM_MONTH, 0) + NVL(x.MHP_THM_DAY, 0) > 0
                ),
                u'Kh\00f4ng'
            ) AS MIEN_GIAM_HP,
            --dmtg_cl.MTG_TITLE AS TG_CON_LAI,
            QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(GTH.PHAM_NHAN_ID, GTH.NGAY_XET) AS TG_CON_LAI,

            NVL(FN_GET_THONG_TIN_HPBS_PT(GTH.PHAM_NHAN_ID), u'Kh\00f4ng') AS HINH_PHAT_BO_SUNG,
            FN_GET_LIET_KE_HPBS_KHAC(GTH.PHAM_NHAN_ID) AS HINH_PHAT_BO_SUNG_KHAC,
            LL.SO_TIEN_AN AS SO_TA,
            FN_GET_TIEN_AN_TONG_HOP(GTH.PHAM_NHAN_ID).CHI_TIET_TIEN_AN AS TIEN_AN,
            CASE WHEN FN_TONG_HOP_TIEN_SU(GTH.PHAM_NHAN_ID).SO_TIEN_SU = 0 THEN u'Kh\00f4ng'
            ELSE TO_NCHAR(FN_TONG_HOP_TIEN_SU(GTH.PHAM_NHAN_ID).SO_TIEN_SU)
            END AS SO_TS, 
            FN_TONG_HOP_TIEN_SU(GTH.PHAM_NHAN_ID).HANH_VI_TIEN_SU AS TIEN_SU,
            LL.TINH_TRANG_SUC_KHOE AS SUC_KHOE,
            NVL(
                CAST(ga.ghi_chu_rieng_text AS NVARCHAR2(2000)),
                NVL(TRIM(CAST(LL.GHI_CHU_RIENG AS NVARCHAR2(2000))), u'Không')
            ) AS GHI_CHU_RIENG,
            LL.TOM_TAT_HANH_VI AS TOM_TAT_HANH_VI_PHAM_TOI,
            NVL(
                NULLIF(TRIM(CAST(NVL(TO_NCHAR(BO.HO_TEN_THAN_NHAN), u'') AS NVARCHAR2(2000))), u''),
                u'Kh\00f4ng c\00f3'
            ) AS HO_TEN_BO,
            BO.NOI_O AS NOI_O_BO,
            NVL(
                NULLIF(TRIM(CAST(NVL(TO_NCHAR(ME.HO_TEN_THAN_NHAN), u'') AS NVARCHAR2(2000))), u''),
                u'Kh\00f4ng c\00f3'
            ) AS HO_TEN_ME,
            ME.NOI_O AS NOI_O_ME,
--            NVL(
--                NULLIF(TRIM(CAST(NVL(TO_NCHAR(VC.QUAN_HE), u'') AS NVARCHAR2(2000))), u''),
--                u'Kh\00f4ng c\00f3'
--            ) AS VO_CHONG,
            CASE WHEN LL.GIOI_TINH = 'Nam' THEN 'v?' ELSE 'ch?ng' END as VO_CHONG,
            NVL(
