            VC.NOI_O AS NOI_O_VC,
            FN_GET_TEN_CON_CAI(GTH.PHAM_NHAN_ID) AS CAC_CONS,
			gdk.DDKCT_GHI_CHU AS XEP_LOAI_CAI_TAO,
            GTH.NHAN_XET AS NHAN_XET_TG,
            MTG.MTG_TITLE AS MUC_DE_NGHI,
            NVL(TRIM(CAST(dttp.TTP_TEN AS NVARCHAR2(2000))), u'') AS DIA_DANH
        FROM GTH_one GTH
        LEFT JOIN LL_one LL ON LL.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID
        LEFT JOIN GTH_KY_GIAM_THOI_HANS gk ON GTH.NGAY_XET = gk.KGTH_NGAY_XET_GIAM
        LEFT JOIN GTH_DU_DIEU_KIEN_CHI_TIETS gdk ON LL.PHAM_NHAN_ID = gdk.DDKCT_PN_ID
        AND  gdk.DDKCT_KY_ID = gk.ID
        LEFT JOIN gcr_agg ga ON ga.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID
        LEFT JOIN THA_one THA ON THA.THA_PNLAI_LICH_ID = GTH.PHAM_NHAN_ID
        LEFT JOIN DM_CAP_TOA_XUS CTX ON CTX.ID = THA.THA_LOAI_BAN_AN_ID AND NVL(CTX.IS_DELETED, 0) = 0
        LEFT JOIN DM_CO_QUANS CQBA ON CQBA.ID = THA.THA_CAP_TOA_ID AND CQBA.IS_DELETED = 0
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg_cl on DMTG_CL.MTG_MA = tha.THA_THOI_GIAN_CON_LAI
        LEFT JOIN DM_MA_THOI_GIANS MTG ON MTG.ID = GTH.MUC_DE_NGHI_ID AND MTG.IS_DELETED = 0
        LEFT JOIN DM_TINH_THANH_PHO dttp ON dttp.ID = GTH.DIA_PHUONG_ID AND NVL(dttp.IS_DELETED, 0) = 0
        LEFT JOIN VW_THAN_NHAN BO
        ON BO.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID
        AND BO.MA_QUAN_HE = '121'
        LEFT JOIN VW_THAN_NHAN ME
        ON ME.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID
        AND ME.MA_QUAN_HE = '122'
        LEFT JOIN VW_THAN_NHAN VC
        ON VC.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID
        AND (ME.MA_QUAN_HE = '131' OR ME.MA_QUAN_HE = '132')
        JOIN PN_ID_LIST pil ON GTH.PHAM_NHAN_ID = pil.PN_ID
        WHERE  gdk.DDKCT_KY_ID = TO_NUMBER(p_ky_id)
		ORDER BY HO_TEN_ORDER;
    DBMS_SQL.RETURN_RESULT(p_cursor);

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('L?i: ' || SQLERRM);
        RAISE;
END SP_GET_QLPN_PHIEU_GIAM_PT33;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_QLPN_PHIEU_GIAM_V2
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_QLPN_PHIEU_GIAM_V2" (
    p_PHAM_NHAN_ID IN VARCHAR2 DEFAULT NULL,
    p_cursor OUT SYS_REFCURSOR
) AS
BEGIN
    OPEN p_cursor FOR
    WITH
    LL_one AS (
        SELECT * FROM (
            SELECT v.*, ROW_NUMBER() OVER (PARTITION BY v.PHAM_NHAN_ID
                ORDER BY NVL(v.NGAY_HET_AN, v.CREATION_TIME) DESC NULLS LAST,
                         v.CREATION_TIME DESC NULLS LAST) AS rn
            FROM VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
        ) x WHERE rn = 1
    ),
    THA_one AS (
        SELECT * FROM (
            SELECT t.*, ROW_NUMBER() OVER (PARTITION BY t.THA_PNLAI_LICH_ID
                ORDER BY NVL(t.THA_NGAY_HET_HAN, t.THA_NGAY_BAT) DESC NULLS LAST,
                         NVL(t.THA_NGAY_DEN_TRAI, t.THA_NGAY_BAT) DESC NULLS LAST,
                         t.ID DESC) AS rn
            FROM PN_THI_HANH_AN t
            WHERE NVL(t.IS_DELETED, 0) = 0
        ) x WHERE rn = 1
    )
    SELECT
            GTH.PHAM_NHAN_ID AS PHAM_NHAN_ID,
            'C?C C10' AS CQ_CHU_QUAN,
            UPPER(LL.TRAI_GIAM) AS TEN_TRAI_HOA,
            GTH.SO_QUYET_DINH AS SO_DE_NGHI,
            NULL AS NGAY_BC,
            UPPER(LL.HO_TEN) AS HO_TEN_HOA,
            LL.GIOI_TINH AS GIOI_TINH,
            LL.NAM_SINH AS NAM_SINH,
            LL.NGUYEN_QUAN AS NGUYEN_QUAN,
            LL.DIA_CHI_THUONG_TRU AS DIA_CHI_TT,
            LL.NOI_O_KHAC AS CHO_O_KHAC,
            LL.DAN_TOC AS DAN_TOC,
            LL.QUOC_TICH AS QUOC_TICH,
            LL.HOC_VAN AS HOC_VAN,
            LL.NGHE_NGHIEP AS NGHE_NGHIEP,
            LL.TOI_DANH AS TOI_DANH,
            THA.THA_NGAY_BAT AS NGAY_BAT,
            THA.THA_AN_PHAT AS AN_PHAT,
            THA.THA_THOI_GIAN_TAM_GIAM AS TG_TAM_GIAM,
            THA.THA_THOI_GIAN_TAM_GIU AS TG_TAM_GIU,
            NULL AS BA_QD,
            THA.THA_SO_BAN_AN AS BAN_AN_SO,
            LL.SO_BAN_AN AS NGAY_XU,
            LL.TOA_XU_TEN AS TOA_XU,
            THA.THA_SO_QD_THA AS SO_QD_THAN,
            THA.THA_NGAY_QD_THA AS NGAY_QD_THAN,
            LL.CO_QUAN_QD_THA AS TOA_QD_THAN,
            LL.NGAY_DEN_TRAI AS NGAY_DEN_TRAI,
            GTH.NGAY_XET AS NGAY_XET,
            GTH.DA_CHAP_HANH AS TG_CHAP_HANH,
            FN_GET_TONG_SO_NGAY_TRON(GTH.PHAM_NHAN_ID) AS TG_TRON,
            FN_SO_NGAY_TAM_DINH_CHI(GTH.PHAM_NHAN_ID) AS TAM_DINH_CHI,
            GTH.DA_GIAM AS GIAM_AN,
            FN_TINH_AN_DA_GIAM(GTH.PHAM_NHAN_ID).CAC_LAN_GIAM AS GIAM_AN_CHI_TIET,
            FN_GET_TONG_MIEN_HINH_PHAT(GTH.PHAM_NHAN_ID) AS MIEN_GIAM_HP,
            FN_GET_CON_LAI(GTH.PHAM_NHAN_ID) AS TG_CON_LAI,
            FN_GET_LIET_KE_HPBS(GTH.PHAM_NHAN_ID) AS HINH_PHAT_BO_SUNG,
            LL.SO_TIEN_AN AS SO_TA,
            FN_GET_TIEN_AN_TONG_HOP(GTH.PHAM_NHAN_ID).CHI_TIET_TIEN_AN AS TIEN_AN,
            FN_TONG_HOP_TIEN_SU(GTH.PHAM_NHAN_ID).SO_TIEN_SU AS SO_TS,
            FN_TONG_HOP_TIEN_SU(GTH.PHAM_NHAN_ID).HANH_VI_TIEN_SU AS TIEN_SU,
            LL.TINH_TRANG_SUC_KHOE AS SUC_KHOE,
            LL.GHI_CHU_RIENG AS GHI_CHU_RIENG,
            LL.TOM_TAT_HANH_VI AS TOM_TAT_HANH_VI_PHAM_TOI,
            BO.HO_TEN_THAN_NHAN AS HO_TEN_BO,
            ME.HO_TEN_THAN_NHAN AS HO_TEN_ME,
            VC.QUAN_HE AS VO_CHONG,
            VC.HO_TEN_THAN_NHAN AS HO_TEN_VO_CHONG,
            FN_GET_TEN_CON_CAI(GTH.PHAM_NHAN_ID) AS CAC_CONS,
            FN_TONG_HOP_KET_QUA_CAI_TAO(GTH.PHAM_NHAN_ID, EXTRACT(YEAR FROM NVL(GTH.NGAY_XET, SYSDATE))) AS XEP_LOAI_CAI_TAO,
            GTH.NHAN_XET AS NHAN_XET_TG,
            MTG.MTG_TITLE AS MUC_DE_NGHI,
            GTH.DIA_PHUONG_ID AS DIA_DANH
        FROM GIAM_THOI_HANS GTH
        LEFT JOIN LL_one LL ON LL.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID
        LEFT JOIN THA_one THA ON THA.THA_PNLAI_LICH_ID = GTH.PHAM_NHAN_ID
        LEFT JOIN DM_CO_QUANS CQBA ON CQBA.ID = THA.THA_CAP_TOA_ID AND CQBA.IS_DELETED = 0
        LEFT JOIN DM_MA_THOI_GIANS MTG ON MTG.ID = GTH.MUC_GIAM_ID AND MTG.IS_DELETED = 0
        LEFT JOIN VW_THAN_NHAN BO ON BO.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID AND UPPER(BO.QUAN_HE) = 'B?'
        LEFT JOIN VW_THAN_NHAN ME ON ME.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID AND UPPER(ME.QUAN_HE) = 'M?'
        LEFT JOIN VW_THAN_NHAN VC ON VC.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID AND (UPPER(VC.QUAN_HE) = 'V?' OR UPPER(VC.QUAN_HE) = 'CH?NG')
        WHERE GTH.IS_DELETED = 0
          AND (p_PHAM_NHAN_ID IS NULL OR TRIM(NVL(p_PHAM_NHAN_ID, '')) = ''
               OR (',' || REPLACE(REPLACE(REPLACE(TRIM(NVL(p_PHAM_NHAN_ID, '')), ' ', ''), '[', ''), ']', '') || ',')
                   LIKE '%,' || TO_CHAR(GTH.PHAM_NHAN_ID) || ',%');

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('L?i: ' || SQLERRM);
        RAISE;
END SP_GET_QLPN_PHIEU_GIAM;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_QLPN_QUYET_DINH_GIAM_NK_TOA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_QLPN_QUYET_DINH_GIAM_NK_TOA" (
    p_pn_ids IN VARCHAR2 DEFAULT NULL,
    p_ngay_xet IN DATE DEFAULT NULL,
    p_ma_trai_giam in VARCHAR2 DEFAULT NULL
)
AS
    -- Local cursor declaration
    P_cursor SYS_REFCURSOR;
    v_dp_trai_giam NVARCHAR2(500);
    v_dia_danh_bc NVARCHAR2(500);
    v_trai_giam NVARCHAR2(500);
BEGIN
    SELECT TSHT_GIA_TRI
    into v_dp_trai_giam
    from QLPN.THAM_SO_HE_THONGS
    where TSHT_THAM_SO = 'DP_TRAI_GIAM';

    SELECT TSHT_GIA_TRI
    into v_dia_danh_bc
    from QLPN.THAM_SO_HE_THONGS
    where TSHT_THAM_SO = 'DIA_DANH_BC';

    SELECT tsht_gia_tri
    INTO v_trai_giam
    FROM QLPN.THAM_SO_HE_THONGS
    WHERE tsht_tham_so = 'DON_VI';

    -- Open cursor with query
    OPEN P_cursor FOR
        WITH ID_LIST AS (
            SELECT DISTINCT TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
            FROM DUAL
            CONNECT BY LEVEL <= CASE
                    WHEN p_pn_ids IS NULL THEN 0
                    WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                    ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                END
              AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
        )
        SELECT
            GTH.SO_QUYET_DINH AS SO_QD_GIAM,
            TO_NCHAR(GTH.NGAY_QUYET_DINH, 'dd/mm/yyyy') AS NGAY_QD_GIAM,

            UPPER(v_dp_trai_giam) AS DP_TRAI_HOA,
            v_dp_trai_giam AS DP_TRAI,
            v_trai_giam AS TRAI_THUONG,

            LL.HO_TEN AS HO_TEN_THUONG,

            THA.THA_SO_BAN_AN AS SO_BAN_AN_THA, -- Tr? ?úng s? b?n án
            TO_NCHAR(THA.THA_NGAY_BAN_AN, 'dd/mm/yyyy') AS NGAY_BA,
            LL.TOA_XU_TEN || u' ' || LL.TOA_XU_DIA_PHUONG AS TOA_AN, -- c? quan ban án

            THA.THA_SO_QD_THA AS SO_QD, -- s? quy?t ??nh thi hành án
            TO_NCHAR(THA.THA_NGAY_QD_THA, 'dd/mm/yyyy') AS NGAY_QD,
            LL.CO_QUAN_QD_THA || u' ' || LL.TOA_QD_THA_DIA_PHUONG AS TOA_QD, -- quy?t ??nh thi hành án

            GTH.DA_CHAP_HANH AS TH_CH,
            QLPN.FN_TINH_THOI_GIAN_CON_LAI(LL.PHAM_NHAN_ID, GTH.NGAY_QUYET_DINH) AS TG_CL_TOA,

            CASE
                WHEN GTH.MUC_GIAM_ID IS NOT NULL AND GTH.MUC_DE_NGHI_ID IS NOT NULL AND GTH.MUC_DE_NGHI_ID = GTH.MUC_GIAM_ID THEN u'to\00e0n b\1ed9'
                ELSE u'm\1ed9t ph\1ea7n'
            END AS MOT_PHAN,

            LL.HO_TEN AS HO_TEN,
            LL.NAM_SINH AS NAM_SINH,
            LL.DIA_CHI_THUONG_TRU AS DC_TT, -- ??a ch? th??ng trú

            NVL(TRIM(DMTHG.MTG_TITLE), u'Kh\00f4ng') AS MUC_GIAM,
            GTH.CON_LAI AS TG_CL_CUOI

        FROM QLPN.GIAM_THOI_HANS GTH
        LEFT JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET LL
        ON LL.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID
        LEFT JOIN QLPN.PN_THI_HANH_AN THA
        ON THA.THA_PNLAI_LICH_ID = LL.PHAM_NHAN_ID
        LEFT JOIN QLPN.DM_TINH_THANH_PHO dttp_THA
        ON dttp_THA.ID = THA.THA_DIA_PHUONG_TOA_QD_THA_ID
        LEFT JOIN QLPN.DM_CO_QUANS cq_toa_THA
        ON cq_toa_THA.ID = THA.THA_TOA_QD_ID
        LEFT JOIN QLPN.DM_MA_THOI_GIANS DMTHG
        ON DMTHG.ID = GTH.MUC_GIAM_ID
        WHERE GTH.IS_DELETED = 0
        AND (p_pn_ids IS NULL OR LL.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
        AND (
            (p_ngay_xet IS NULL AND GTH.NGAY_XET = (SELECT KGTH_NGAY_XET_GIAM from qlpn.gth_ky_giam_thoi_hans where IS_DELETED = 0 and KGTH_TRANG_THAI = 1))
            OR TRUNC(GTH.NGAY_XET) = p_ngay_xet
        );
    -- Return cursor result
    DBMS_SQL.RETURN_RESULT(P_cursor);

EXCEPTION
    WHEN OTHERS THEN
        RAISE;
END SP_GET_QLPN_QUYET_DINH_GIAM_NK_TOA;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_QLPN_QUYET_DINH_GIAM_NK_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_QLPN_QUYET_DINH_GIAM_NK_TRAI" (
    p_pn_ids IN VARCHAR2 DEFAULT NULL,
    p_ngay_xet IN DATE DEFAULT NULL,
    p_ma_trai_giam in VARCHAR2 DEFAULT NULL
) AS
    P_cursor SYS_REFCURSOR;
    v_dp_trai_giam NVARCHAR2(500);
    v_dia_danh_bc NVARCHAR2(500);
    v_trai_giam NVARCHAR2(500);

BEGIN
    SELECT TSHT_GIA_TRI
    into v_dp_trai_giam
    from QLPN.THAM_SO_HE_THONGS
    where TSHT_THAM_SO = 'DP_TRAI_GIAM';

    SELECT TSHT_GIA_TRI
    into v_dia_danh_bc
    from QLPN.THAM_SO_HE_THONGS
    where TSHT_THAM_SO = 'DIA_DANH_BC';

    SELECT tsht_gia_tri
    INTO v_trai_giam
    FROM QLPN.THAM_SO_HE_THONGS
    WHERE tsht_tham_so = 'DON_VI';

    OPEN P_cursor FOR
    WITH
    ID_LIST AS (
        SELECT DISTINCT TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS PN_ID
        FROM DUAL
        CONNECT BY LEVEL <= CASE
                WHEN p_pn_ids IS NULL THEN 0
                WHEN LENGTH(TRIM(p_pn_ids)) = 0 THEN 0
                ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
            END
            AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
            AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
    ),
    THA_one AS (
        SELECT *
        FROM (
            SELECT t.*,
                   ROW_NUMBER() OVER (
                       PARTITION BY t.THA_PNLAI_LICH_ID
                       ORDER BY NVL(t.THA_NGAY_HET_HAN, t.THA_NGAY_BAT) DESC NULLS LAST,
                                NVL(t.THA_NGAY_DEN_TRAI, t.THA_NGAY_BAT) DESC NULLS LAST,
                                t.ID DESC
                   ) AS rn
            FROM QLPN.PN_THI_HANH_AN t
            WHERE
                NVL(t.IS_DELETED, 0) = 0
                AND (p_pn_ids IS NULL OR t.THA_PNLAI_LICH_ID IN (SELECT PN_ID FROM ID_LIST))
        ) x
        WHERE x.rn = 1
    )
    SELECT
        GTH.ID AS GTH_ID,
        GTH.PHAM_NHAN_ID,
        GTH.SO_QUYET_DINH AS SO_QD_GIAM,


        NVL(v_dp_trai_giam, TRIM(CAST(dttp.TTP_TEN AS NVARCHAR2(500)))) AS DP_TRAI,
        upper(NVL(v_dp_trai_giam, TRIM(CAST(dttp.TTP_TEN AS NVARCHAR2(500))))) AS DP_TRAI_HOA,
        NVL(v_trai_giam, NVL(TRIM(LL.TRAI_GIAM), u'')) AS TRAI_THUONG,


        TO_NCHAR(GTH.NGAY_QUYET_DINH, 'DD/MM/YYYY') AS NGAY_QD_GIAM,
        TO_NCHAR(GTH.NGAY_XET, 'DD/MM/YYYY') AS NGAY_XET,
        TO_NCHAR(GTH.NGAY_THA_GIAM_HET_AN, 'DD/MM/YYYY') AS NGAY_THA_GIAM_HET_AN,

        NVL(TRIM(dttp.TTP_MA), u'') AS DP_TRAI_MA_TINH,
        NVL(TRIM(cq_toa.CQ_TEN), u'') AS TOA_QUYET_DINH_TEN,
        NVL(TRIM(mtg_mdn.MTG_TITLE), u'') AS MUC_DE_NGHI,
        NVL(TRIM(mtg_cap.MTG_TITLE), u'') AS CAP_TREN_DUYET,
        NVL(TRIM(DMTHG.MTG_TITLE), u'') AS MUC_GIAM,
        LL.HO_TEN AS HO_TEN_THUONG,
        TO_NCHAR(THA.THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS NGAY_BA,
        LL.TOA_XU_TEN || u' ' || LL.TOA_XU_DIA_PHUONG  AS TOA_AN,
        THA.THA_SO_QD_THA AS SO_QD,
        TO_NCHAR(THA.THA_NGAY_QD_THA, 'DD/MM/YYYY') AS NGAY_QD,
        LL.CO_QUAN_QD_THA || u' ' || LL.TOA_QD_THA_DIA_PHUONG AS TOA_QD,
        THA.THA_SO_BAN_AN AS SO_BAN_AN_THA,
        THA.THA_AN_PHAT AS AN_PHAT_THA,
        GTH.DA_CHAP_HANH AS TH_CH,
        QLPN.FN_TINH_THOI_GIAN_CON_LAI(LL.PHAM_NHAN_ID, GTH.NGAY_QUYET_DINH) AS TG_CL,
        CASE
            WHEN GTH.MUC_GIAM_ID IS NOT NULL AND GTH.MUC_DE_NGHI_ID IS NOT NULL AND GTH.MUC_DE_NGHI_ID = GTH.MUC_GIAM_ID THEN u'to\00e0n b\1ed9'
            ELSE u'm\1ed9t ph\1ea7n'
        END AS MOT_PHAN,
        LL.HO_TEN AS HO_TEN,
        LL.NAM_SINH AS NAM_SINH,
        LL.NGAY_SINH AS NGAY_SINH,
        LL.GIOI_TINH AS GIOI_TINH,
        LL.CCCD AS CCCD,
        NVL(TRIM(LL.NOI_THUONG_TRU_DAY_DU), u'') AS DC_TT,
        LL.TOI_DANH AS TOI_DANH,
        LL.SO_HO_SO AS SO_HO_SO,
        GTH.CON_LAI AS TG_CL_CUOI,
        GTH.NHAN_XET AS NHAN_XET,
        GTH.KQCT_PHIEU AS KQCT_PHIEU_RG,
        GTH.KQCT_DANHSACH AS KQCT_DANHSACH_RG,
        GTH.MUC_DE_NGHI_ID,
        GTH.CAP_TREN_DUYET_ID,
        GTH.TOA_QUYET_DINH_ID,
        GTH.DIA_PHUONG_ID,
        GTH.MUC_GIAM_ID
    FROM QLPN.GIAM_THOI_HANS GTH
    LEFT JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET LL
        ON LL.PHAM_NHAN_ID = GTH.PHAM_NHAN_ID
       AND NVL(LL.IS_DELETED, 0) = 0
    LEFT JOIN THA_one THA
        ON THA.THA_PNLAI_LICH_ID = GTH.PHAM_NHAN_ID
    LEFT JOIN QLPN.DM_MA_THOI_GIANS DMTHG
        ON DMTHG.ID = GTH.MUC_GIAM_ID
       AND NVL(DMTHG.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_MA_THOI_GIANS mtg_mdn
        ON mtg_mdn.ID = GTH.MUC_DE_NGHI_ID
       AND NVL(mtg_mdn.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_MA_THOI_GIANS mtg_cap
        ON mtg_cap.ID = GTH.CAP_TREN_DUYET_ID
       AND NVL(mtg_cap.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_TINH_THANH_PHO dttp
        ON dttp.ID = GTH.DIA_PHUONG_ID
       AND NVL(dttp.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_CO_QUANS cq_toa
        ON cq_toa.ID = GTH.TOA_QUYET_DINH_ID
       AND NVL(cq_toa.IS_DELETED, 0) = 0
    WHERE NVL(GTH.IS_DELETED, 0) = 0
      AND (
          p_pn_ids IS NULL
          OR GTH.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST)
      )
      AND (
          p_ngay_xet IS NULL
          OR GTH.NGAY_XET = p_ngay_xet
      )
    ORDER BY GTH.NGAY_QUYET_DINH DESC NULLS LAST, GTH.ID DESC;

    DBMS_SQL.RETURN_RESULT(P_cursor);

EXCEPTION
    WHEN OTHERS THEN
        RAISE;
END SP_GET_QLPN_QUYET_DINH_GIAM_NK_TRAI;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_QLPN_TRICH_SAO_BAN_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_QLPN_TRICH_SAO_BAN_AN" (
    p_PHAM_NHAN_ID IN VARCHAR2 DEFAULT NULL,
    p_ma_trai_giam IN VARCHAR2 DEFAULT NULL
) AS
    p_cursor SYS_REFCURSOR;
BEGIN
    OPEN p_cursor FOR
    WITH
    LL_one AS (
        SELECT * FROM (
            SELECT
                v.*
            FROM VW_PN_LAI_LICH_CHI_TIET v
            WHERE NVL(v.IS_DELETED, 0) = 0
            and (p_ma_trai_giam is null or v.TRAI_GIAM_MA = p_ma_trai_giam)
        ) x

    ),
    THA_one AS (
        SELECT * FROM (
            SELECT
                t.*
            FROM PN_THI_HANH_AN t
            WHERE NVL(t.IS_DELETED, 0) = 0
        ) x
    ),
    TN_raw AS (
        SELECT
            t.PHAM_NHAN_ID,
            TRIM(CAST(NVL(TO_NCHAR(t.HO_TEN_THAN_NHAN), u'') AS NVARCHAR2(2000))) AS HO_TEN_GOC,
            UPPER(TRIM(CAST(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(t.QUAN_HE), u'')) AS NVARCHAR2(500)))) AS QUAN_HE_NORM
        FROM VW_THAN_NHAN t
    ),
    TN_agg AS (
        SELECT
            t.PHAM_NHAN_ID,
            LISTAGG(
                DISTINCT CASE
                    WHEN t.QUAN_HE_NORM LIKE 'BO%'
                    THEN t.HO_TEN_GOC
                END,
                u', '
            ) WITHIN GROUP (ORDER BY t.HO_TEN_GOC) AS HO_TEN_BO,
            LISTAGG(
                DISTINCT CASE
                    WHEN t.QUAN_HE_NORM LIKE 'ME%'
                    THEN t.HO_TEN_GOC
                END,
                u', '
            ) WITHIN GROUP (ORDER BY t.HO_TEN_GOC) AS HO_TEN_ME,
            LISTAGG(
                DISTINCT CASE
                    WHEN t.QUAN_HE_NORM IN ('VO', 'CHONG')
                    THEN t.HO_TEN_GOC
                END,
                u', '
            ) WITHIN GROUP (ORDER BY t.HO_TEN_GOC) AS VO_CHONG
        FROM TN_raw t
        GROUP BY t.PHAM_NHAN_ID
    )
    SELECT
        ll.PHAM_NHAN_ID AS PHAM_NHAN_ID,
        NVL(TRIM(CAST(tha.THA_SO_BAN_AN AS VARCHAR2(500))), '') AS SO_BAN_AN,
        CASE
            WHEN tha.THA_NGAY_BAN_AN IS NOT NULL THEN TO_CHAR(tha.THA_NGAY_BAN_AN, 'DD/MM/YYYY')
            ELSE NULL
        END AS NGAY_BAN_AN,
        SUBSTR(
            TRIM(
                NVL(TRIM(CAST(ll.CO_QUAN_QD_THA AS VARCHAR2(1000))), '')
                || CASE
                    WHEN ll.TOA_QD_THA_DIA_PHUONG IS NOT NULL
                    THEN ', ' || TRIM(CAST(ll.TOA_QD_THA_DIA_PHUONG AS VARCHAR2(1000)))
                    ELSE ''
                   END
            ),
            1, 2000
        ) AS TOA_QD,
        NVL(TRIM(CAST(ll.HO_TEN AS VARCHAR2(2000))), '') AS HO_TEN,
        NVL(TRIM(CAST(ll.GIOI_TINH AS VARCHAR2(100))), '') AS GIOI_TINH,
        ll.NAM_SINH  AS NAM_SINH,
        NVL(
            TRIM(
                COALESCE(
                    CAST(ll.NOI_THUONG_TRU_DAY_DU AS VARCHAR2(2000)),
                    CAST(ll.DIA_CHI_THUONG_TRU AS VARCHAR2(2000))
                )
            ),
            ''
        ) AS DIA_CHI,
        NVL(TRIM(CAST(ll.NGHE_NGHIEP AS VARCHAR2(500))), '') AS NGHE_NGHIEP,
        NVL(TRIM(CAST(tn.HO_TEN_BO AS NVARCHAR2(2000))), u'') AS HO_TEN_BO,
        NVL(TRIM(CAST(tn.HO_TEN_ME AS NVARCHAR2(2000))), u'') AS HO_TEN_ME,
        NVL(TRIM(CAST(tn.VO_CHONG AS NVARCHAR2(2000))), u'') AS VO_CHONG,
        CASE
            WHEN tha.THA_NGAY_BAT IS NOT NULL THEN TO_CHAR(tha.THA_NGAY_BAT, 'DD/MM/YYYY')
            ELSE NULL
        END AS NGAY_BAT,
        NVL(TRIM(CAST(tha.THA_AN_PHAT AS VARCHAR2(2000))), '') AS AN_PHAT,
        SUBSTR(
            CASE
                WHEN (
                    NULLIF(TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIAM AS VARCHAR2(500))), '') IS NULL
                    OR UPPER(CAST(QLPN.FN_NORMALIZE_VN(TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIAM AS VARCHAR2(500)))) AS VARCHAR2(500))) = 'KHONG'
                )
                AND (
                    NULLIF(TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIU AS VARCHAR2(500))), '') IS NULL
                    OR UPPER(CAST(QLPN.FN_NORMALIZE_VN(TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIU AS VARCHAR2(500)))) AS VARCHAR2(500))) = 'KHONG'
                )
                THEN 'Không'
                WHEN (
                    NULLIF(TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIAM AS VARCHAR2(500))), '') IS NOT NULL
                    AND UPPER(CAST(QLPN.FN_NORMALIZE_VN(TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIAM AS VARCHAR2(500)))) AS VARCHAR2(500))) <> 'KHONG'
                )
                AND (
                    NULLIF(TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIU AS VARCHAR2(500))), '') IS NOT NULL
                    AND UPPER(CAST(QLPN.FN_NORMALIZE_VN(TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIU AS VARCHAR2(500)))) AS VARCHAR2(500))) <> 'KHONG'
                )
                THEN CASE
                    WHEN REGEXP_LIKE(
                        UPPER(CAST(QLPN.FN_NORMALIZE_VN(TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIAM AS VARCHAR2(500)))) AS VARCHAR2(500))),
                        '^[0-9]+([.,][0-9]+)?\s*NGAY$'
                    )
                    AND REGEXP_LIKE(
                        UPPER(CAST(QLPN.FN_NORMALIZE_VN(TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIU AS VARCHAR2(500)))) AS VARCHAR2(500))),
                        '^[0-9]+([.,][0-9]+)?\s*NGAY$'
                    )
                    THEN TO_CHAR(
                        TO_NUMBER(
                            REPLACE(
                                REGEXP_SUBSTR(
                                    TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIAM AS VARCHAR2(500))),
                                    '[0-9]+([.,][0-9]+)?'
                                ),
                                ',',
                                '.'
                            )
                        )
                        + TO_NUMBER(
                            REPLACE(
                                REGEXP_SUBSTR(
                                    TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIU AS VARCHAR2(500))),
                                    '[0-9]+([.,][0-9]+)?'
                                ),
                                ',',
                                '.'
                            )
                        )
                    ) || ' ngày'
                    ELSE TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIAM AS VARCHAR2(500))) || ', '
                         || TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIU AS VARCHAR2(500)))
                END
                WHEN (
                    NULLIF(TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIAM AS VARCHAR2(500))), '') IS NOT NULL
                    AND UPPER(CAST(QLPN.FN_NORMALIZE_VN(TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIAM AS VARCHAR2(500)))) AS VARCHAR2(500))) <> 'KHONG'
                )
                THEN TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIAM AS VARCHAR2(500)))
                WHEN (
                    NULLIF(TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIU AS VARCHAR2(500))), '') IS NOT NULL
                    AND UPPER(CAST(QLPN.FN_NORMALIZE_VN(TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIU AS VARCHAR2(500)))) AS VARCHAR2(500))) <> 'KHONG'
                )
                THEN TRIM(CAST(tha.THA_THOI_GIAN_TAM_GIU AS VARCHAR2(500)))
                ELSE 'Không'
            END,
            1,
            2000
        ) AS KHAU_TRU,
        NVL(TRIM(CAST(ll.TOI_DANH AS VARCHAR2(4000))), '') AS TOI_DANH,
        NVL(TRIM(CAST(tha.THA_SO_DANH_BAN AS VARCHAR2(500))), '') AS SO_DANH_CHI,
        CASE
            WHEN tha.THA_NGAY_LAP_DANH_BAN IS NOT NULL THEN TO_CHAR(tha.THA_NGAY_LAP_DANH_BAN, 'DD/MM/YYYY')
            ELSE NULL
        END AS NGAY_DANH_CHI,
        NVL(TRIM(CAST(ll.TOA_QD_THA_DIA_PHUONG AS VARCHAR2(1000))), '') AS TINH_TP_LAP,
--        SUBSTR(
--            TRIM(
--                NVL(TRIM(CAST(tha.THA_CONG_THUC_VAN_TAY AS VARCHAR2(200))), '')
--                || CASE
--                    WHEN tha.THA_CONG_THUC_VAN_TAY IS NOT NULL
--                         AND tha.THA_CONG_THUC_VAN_TAY_2 IS NOT NULL
--                    THEN ', '
--                    ELSE ''
--                   END
--                || NVL(TRIM(CAST(tha.THA_CONG_THUC_VAN_TAY_2 AS VARCHAR2(200))), '')
--            ),
--            1, 500
--        )
        tha.THA_CONG_THUC_VAN_TAY AS CONG_THUC_VAN_TAY_1,
        tha.THA_CONG_THUC_VAN_TAY_2 AS CONG_THUC_VAN_TAY_2
    FROM LL_one ll
    LEFT JOIN THA_one tha
        ON tha.THA_PNLAI_LICH_ID = ll.PHAM_NHAN_ID
    LEFT JOIN TN_agg tn
        ON tn.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
    WHERE (
        p_PHAM_NHAN_ID IS NULL
        OR TRIM(NVL(p_PHAM_NHAN_ID, '')) = ''
        OR (',' || REPLACE(REPLACE(REPLACE(TRIM(NVL(p_PHAM_NHAN_ID, '')), ' ', ''), '[', ''), ']', '') || ',')
            LIKE '%,' || TO_CHAR(ll.PHAM_NHAN_ID) || ',%'
    ) ORDER BY ho_ten_order ;

    DBMS_SQL.RETURN_RESULT(p_cursor);
EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('L?i: ' || SQLERRM);
        RAISE;


/*
BEGIN
    SP_GET_QLPN_TRICH_SAO_BAN_AN(
        p_PHAM_NHAN_ID => NULL
        -- Ví d? l?c 1 ph?m nhân:
        -- p_PHAM_NHAN_ID => '12345'
        -- Ví d? l?c nhi?u ph?m nhân:
        -- p_PHAM_NHAN_ID => '12345,67890'
    );
END;
*/
END SP_GET_QLPN_TRICH_SAO_BAN_AN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_QUAN_HE_GIA_DINH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_QUAN_HE_GIA_DINH" (
    p_PHAM_NHAN_ID IN NUMBER
    
)
AS
c1 SYS_REFCURSOR;
BEGIN

    OPEN c1 FOR
    SELECT 
        tnnt.PHAM_NHAN_ID,
        tnnt.HO_TEN_THAN_NHAN  AS "HoTen",
        dqhvpn.QHVPN_TEN       AS "QuanHe",
        dgt.GT_TEN             AS "GioiTinh",
        tnnt.NGAY_SINH         AS "NgaySinh",
        tnnt.NOI_O             AS "NoiO"
    FROM THAN_NHAN_NGUOI_THANS tnnt 
    LEFT JOIN DM_QUAN_HE_VOI_PHAM_NHANS dqhvpn
        ON tnnt.QUAN_HE_ID = dqhvpn.ID
    LEFT JOIN DM_GIOI_TINHS dgt
        ON tnnt.GIOI_TINH_ID = dgt.ID
    WHERE tnnt.PHAM_NHAN_ID = p_PHAM_NHAN_ID;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_QUAN_HE_GIA_DINH;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_QUYET_DINH_THI_HANH_AN_KHAC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_QUYET_DINH_THI_HANH_AN_KHAC" (
    p_LAI_LICH_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        pqdbak.QDBAK_PN_LAI_LICH_ID,
        pqdbak.QDBAK_SO_QUYET_DINH  AS "SoQD",
        pqdbak.QDBAK_NGAY_QUYET_DINH  AS "NgayQD",
        dcq.CQ_TEN  AS "ToaQD",
        pqdbak.QDBAK_SO_BAN_AN  AS "SoBanAn",
        TO_CHAR(pqdbak.QDBAK_NGAY_BAN_AN, 'DD/MM/YYYY' ) AS "Ngay",
        dcq2.CQ_TEN AS "ToaXu"
    FROM PN_QUYET_DINH_BAN_AN_KHACS pqdbak  
    LEFT JOIN DM_CO_QUANS dcq ON pqdbak.QDBAK_TOA_QUYET_DINH_ID = dcq.ID 
    LEFT JOIN DM_CO_QUANS dcq2 ON pqdbak.QDBAK_TOA_XU_ID = dcq2.ID
    WHERE pqdbak.QDBAK_PN_LAI_LICH_ID = p_LAI_LICH_ID;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_QUYET_DINH_THI_HANH_AN_KHAC;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_QUYET_DINH_XEP_LOAI_CAI_TAO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_QUYET_DINH_XEP_LOAI_CAI_TAO" (
    P_PHAN_DOI_ID            IN  NVARCHAR2     DEFAULT NULL,
    P_XEP_LOAI_ID            IN  NVARCHAR2     DEFAULT NULL,
    P_HO_TEN_FILTER          IN  NVARCHAR2     DEFAULT NULL,
    P_SKIP_COUNT             IN  NUMBER        DEFAULT 0,
    P_MAX_RESULT_COUNT       IN  NUMBER        DEFAULT NULL,
    P_SORTING                IN  NVARCHAR2     DEFAULT NULL,
    P_TOTAL_COUNT            OUT NUMBER,
    P_MO_KY_NOT_FOUND        OUT NUMBER,
    P_CURSOR                 OUT SYS_REFCURSOR
) AS
    V_MO_KY_ID               NUMBER;
    V_NAM_XL                 NUMBER;
    V_NGAY_DEN_TRAI_TU       DATE;
    V_KY_XEP_LOAI            NVARCHAR2(100);
    V_SORT_ASC               NUMBER(1) := 1;
    V_SORT_NGAYSINH          NUMBER(1) := 0;
    V_SORT_DIACHI            NUMBER(1) := 0;
    V_SORT_HOTEN             NUMBER(1) := 0;
    V_SORT_DEFAULT           NUMBER(1) := 0;
    V_SORT_FIELD             NVARCHAR2(100);
    V_SORTING_LOWER          NVARCHAR2(200);
BEGIN
    P_MO_KY_NOT_FOUND := 0;
    P_TOTAL_COUNT := 0;

    BEGIN
        SELECT ID, NAM_XEP_LOAI, NGAY_DEN_TRAI_TU, KY_XEP_LOAI
          INTO V_MO_KY_ID, V_NAM_XL, V_NGAY_DEN_TRAI_TU, V_KY_XEP_LOAI
          FROM (
                SELECT ID, NAM_XEP_LOAI, NGAY_DEN_TRAI_TU, KY_XEP_LOAI
                  FROM QLPN.MO_KY_XEP_LOAI_CAI_TAOS
                 WHERE NVL(IS_DELETED, 0) = 0 AND TRANG_THAI = 1
                 ORDER BY ID DESC
               )
         WHERE ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN NULL;
    END;

    IF V_MO_KY_ID IS NULL THEN
        BEGIN
            SELECT ID, NAM_XEP_LOAI, NGAY_DEN_TRAI_TU, KY_XEP_LOAI
              INTO V_MO_KY_ID, V_NAM_XL, V_NGAY_DEN_TRAI_TU, V_KY_XEP_LOAI
              FROM (
                    SELECT ID, NAM_XEP_LOAI, NGAY_DEN_TRAI_TU, KY_XEP_LOAI
                      FROM QLPN.MO_KY_XEP_LOAI_CAI_TAOS
                     WHERE NVL(IS_DELETED, 0) = 0
                     ORDER BY TU_NGAY DESC
                   )
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                P_MO_KY_NOT_FOUND := 1;
                OPEN P_CURSOR FOR
                    SELECT CAST(NULL AS NUMBER) AS PHAM_NHAN_ID FROM DUAL WHERE 1 = 0;
                RETURN;
        END;
    END IF;

    V_SORTING_LOWER := LOWER(NVL(P_SORTING, ''));
    V_SORT_FIELD    := LOWER(TRIM(REGEXP_SUBSTR(V_SORTING_LOWER, '^\S+')));
    IF V_SORTING_LOWER LIKE '%desc%' THEN V_SORT_ASC := 0; END IF;

    IF V_SORT_FIELD = 'ngaysinh'        THEN V_SORT_NGAYSINH := 1;
    ELSIF V_SORT_FIELD = 'diachithuongtru' THEN V_SORT_DIACHI := 1;
    ELSIF V_SORT_FIELD = 'hoten'        THEN V_SORT_HOTEN    := 1;
    ELSIF LENGTH(TRIM(V_SORTING_LOWER)) > 0 THEN V_SORT_DEFAULT := 1;
    END IF;

    OPEN P_CURSOR FOR
        WITH
        dang_o_trai AS (
            SELECT ID FROM QLPN.DM_TINH_TRANG_PHAM_NHANS
             WHERE TTPN_MA IN ('111', '112', '113', '114')
        ),
        tha_ranked AS (
            SELECT t.THA_PNLAI_LICH_ID AS PN_ID,
                   t.THA_TOI_DANH,
                   t.THA_AN_PHAT,
                   t.THA_NGAY_DEN_TRAI,
                   t.THA_NGAY_HET_HAN,
                   ROW_NUMBER() OVER (
                       PARTITION BY t.THA_PNLAI_LICH_ID
                       ORDER BY t.CREATION_TIME DESC NULLS LAST, t.ID DESC
                   ) AS RN
              FROM QLPN.PN_THI_HANH_AN t
             WHERE NVL(t.IS_DELETED, 0) = 0
        ),
        tha_latest AS (
            SELECT PN_ID, THA_TOI_DANH, THA_AN_PHAT, THA_NGAY_DEN_TRAI, THA_NGAY_HET_HAN
              FROM tha_ranked
             WHERE RN = 1
        ),
        xl_ranked AS (
            SELECT x.PHAM_NHAN_ID AS PN_ID,
                   x.XEP_LOAI_QUY_I,
                   x.XEP_LOAI_QUY_II,
                   x.XEP_LOAI_QUY_III,
                   x.XEP_LOAI_QUY_IV,
                   x.XEP_LOAI_6_THANG_DAU_NAM,
                   x.XEP_LOAI_6_THANG_CUOI_NAM,
                   x.XEP_LOAI_CA_NAM,
                   ROW_NUMBER() OVER (
                       PARTITION BY x.PHAM_NHAN_ID
                       ORDER BY x.CREATION_TIME DESC NULLS LAST, x.ID DESC
                   ) AS RN
              FROM QLPN.XEP_LOAIS x
             WHERE NVL(x.IS_DELETED, 0) = 0
               AND x.XEP_LOAI_NAM = V_NAM_XL
        ),
        xl_latest AS (
            SELECT PN_ID,
                   XEP_LOAI_QUY_I, XEP_LOAI_QUY_II, XEP_LOAI_QUY_III, XEP_LOAI_QUY_IV,
                   XEP_LOAI_6_THANG_DAU_NAM, XEP_LOAI_6_THANG_CUOI_NAM, XEP_LOAI_CA_NAM
              FROM xl_ranked
             WHERE RN = 1
        ),
        filtered AS (
            SELECT
                pll.ID                                              AS PHAM_NHAN_ID,
                pll.LL_SO_HO_SO_LAN_DAU,
                pll.LL_CCCD,
                pll.LL_HO_TEN,
                QLPN.FN_FORMAT_SORT_TEN_PN(pll.LL_HO_TEN)          AS SORT_THEO_TEN,
                pll.LL_NGAY_SINH,
                gt.GT_TEN                                           AS TEN_GIOI_TINH,
                NVL(TO_CHAR(pll.LL_DIA_CHI_THUONG_TRU), '')
                    || CASE WHEN xp.XP_TEN IS NOT NULL
                            THEN CASE WHEN pll.LL_DIA_CHI_THUONG_TRU IS NOT NULL THEN ', ' END || TO_CHAR(xp.XP_TEN) END
                    || CASE WHEN ttp.TTP_TEN IS NOT NULL THEN
                        CASE WHEN pll.LL_DIA_CHI_THUONG_TRU IS NOT NULL OR xp.XP_TEN IS NOT NULL THEN ', ' END
                             || TO_CHAR(ttp.TTP_TEN) END
                    AS DIA_CHI_THUONG_TRU,
                CASE
                    WHEN tha.THA_TOI_DANH IS NULL THEN NULL
                    ELSE (
                        SELECT LISTAGG(TRIM(TO_CHAR(td.TD_TEN)), '; ') WITHIN GROUP (ORDER BY TRIM(TO_CHAR(td.TD_TEN)))
                          FROM QLPN.DM_TOI_DANHS td
                         WHERE INSTR(
                                   ',' || REPLACE(REPLACE(REPLACE(TO_CHAR(tha.THA_TOI_DANH), '[', ''), ']', ''), ' ', '') || ',',
                                   ',' || TO_CHAR(td.ID) || ','
                               ) > 0
                    )
                END AS TOI_DANH,
                tha.THA_AN_PHAT                                     AS AN_PHAT,
                tha.THA_NGAY_DEN_TRAI                               AS NGAY_DEN_TRAI,
                tha.THA_NGAY_HET_HAN                                AS NGAY_HET_HAN,
                TO_CHAR(xl.XEP_LOAI_QUY_I)                          AS XEP_LOAI_QUY_I,
                TO_CHAR(xl.XEP_LOAI_QUY_II)                         AS XEP_LOAI_QUY_II,
                TO_CHAR(xl.XEP_LOAI_QUY_III)                        AS XEP_LOAI_QUY_III,
                TO_CHAR(xl.XEP_LOAI_QUY_IV)                         AS XEP_LOAI_QUY_IV,
                TO_CHAR(xl.XEP_LOAI_6_THANG_DAU_NAM)                AS XEP_LOAI_6_THANG_DAU_NAM,
                TO_CHAR(xl.XEP_LOAI_6_THANG_CUOI_NAM)               AS XEP_LOAI_6_THANG_CUOI_NAM,
                TO_CHAR(xl.XEP_LOAI_CA_NAM)                         AS XEP_LOAI_CA_NAM,
                CASE
                    WHEN pll.LL_NGAY_SINH IS NULL THEN '0000'
                    WHEN LENGTH(TO_CHAR(pll.LL_NGAY_SINH)) = 4 THEN TO_CHAR(pll.LL_NGAY_SINH)
                    WHEN LENGTH(TO_CHAR(pll.LL_NGAY_SINH)) = 10 THEN SUBSTR(TO_CHAR(pll.LL_NGAY_SINH), 7, 4)
                    ELSE '0000'
                END AS SORT_NS_NAM,
                CASE
                    WHEN pll.LL_NGAY_SINH IS NULL THEN '00'
                    WHEN LENGTH(TO_CHAR(pll.LL_NGAY_SINH)) = 4 THEN '00'
                    WHEN LENGTH(TO_CHAR(pll.LL_NGAY_SINH)) = 10 THEN SUBSTR(TO_CHAR(pll.LL_NGAY_SINH), 4, 2)
                    ELSE '00'
                END AS SORT_NS_THANG,
                CASE
                    WHEN pll.LL_NGAY_SINH IS NULL THEN '00'
                    WHEN LENGTH(TO_CHAR(pll.LL_NGAY_SINH)) = 4 THEN '00'
                    WHEN LENGTH(TO_CHAR(pll.LL_NGAY_SINH)) = 10 THEN SUBSTR(TO_CHAR(pll.LL_NGAY_SINH), 1, 2)
                    ELSE '00'
                END AS SORT_NS_NGAY
            FROM QLPN.PN_LAI_LICHS pll
            INNER JOIN dang_o_trai tt ON tt.ID = pll.LL_TINH_TRANG_ID
            LEFT JOIN tha_latest tha ON tha.PN_ID = pll.ID
            LEFT JOIN xl_latest xl ON xl.PN_ID = pll.ID
            LEFT JOIN QLPN.DM_GIOI_TINHS gt ON gt.ID = pll.LL_DM_GIOI_TINH_ID
            LEFT JOIN QLPN.DM_XA_PHUONG xp ON xp.ID = pll.LL_DIA_CHI_THUONG_TRU_WARD
            LEFT JOIN QLPN.DM_TINH_THANH_PHO ttp ON ttp.ID = pll.LL_DIA_CHI_THUONG_TRU_PROVICE
            WHERE NVL(pll.IS_DELETED, 0) = 0
              AND EXISTS (
                    SELECT 1
                      FROM QLPN.PN_THI_HANH_AN t2
                     WHERE NVL(t2.IS_DELETED, 0) = 0
                       AND t2.THA_PNLAI_LICH_ID = pll.ID
                       AND t2.THA_NGAY_DEN_TRAI IS NOT NULL
                       AND TRUNC(t2.THA_NGAY_DEN_TRAI) <= TRUNC(V_NGAY_DEN_TRAI_TU)
                  )
              AND (P_PHAN_DOI_ID IS NULL OR LENGTH(TRIM(P_PHAN_DOI_ID)) = 0
                   OR TO_CHAR(pll.LL_PHAN_DOI_ID) = TRIM(P_PHAN_DOI_ID))
              AND (P_HO_TEN_FILTER IS NULL OR LENGTH(TRIM(P_HO_TEN_FILTER)) = 0 OR
                   INSTR(
                       QLPN.BO_DAU(NVL(TO_CHAR(pll.LL_HO_TEN), '')),
                       QLPN.BO_DAU(TRIM(P_HO_TEN_FILTER))
                   ) > 0)
              AND (P_XEP_LOAI_ID IS NULL OR LENGTH(TRIM(P_XEP_LOAI_ID)) = 0 OR
                   (V_KY_XEP_LOAI = 'MA_XEP_LOAI_Q1'  AND TO_CHAR(xl.XEP_LOAI_QUY_I) = TRIM(P_XEP_LOAI_ID)) OR
                   (V_KY_XEP_LOAI = 'MA_XEP_LOAI_Q2'  AND TO_CHAR(xl.XEP_LOAI_QUY_II) = TRIM(P_XEP_LOAI_ID)) OR
                   (V_KY_XEP_LOAI = 'MA_XEP_LOAI_Q3'  AND TO_CHAR(xl.XEP_LOAI_QUY_III) = TRIM(P_XEP_LOAI_ID)) OR
                   (V_KY_XEP_LOAI = 'MA_XEP_LOAI_Q4'  AND TO_CHAR(xl.XEP_LOAI_QUY_IV) = TRIM(P_XEP_LOAI_ID)) OR
                   (V_KY_XEP_LOAI = 'MA_XEP_LOAI_DAU'  AND TO_CHAR(xl.XEP_LOAI_6_THANG_DAU_NAM) = TRIM(P_XEP_LOAI_ID)) OR
                   (V_KY_XEP_LOAI = 'MA_XEP_LOAI_CUOI' AND TO_CHAR(xl.XEP_LOAI_6_THANG_CUOI_NAM) = TRIM(P_XEP_LOAI_ID)) OR
                   (V_KY_XEP_LOAI = 'MA_XEP_LOAI_CA'   AND TO_CHAR(xl.XEP_LOAI_CA_NAM) = TRIM(P_XEP_LOAI_ID)))
        ),
        numbered AS (
            SELECT f.*,
                   V_MO_KY_ID   AS MO_KY_XEP_LOAI_ID,
                   V_KY_XEP_LOAI AS KY_XEP_LOAI,
                   COUNT(*) OVER() AS TOTAL_COUNT,
                   ROW_NUMBER() OVER (
                       ORDER BY
                           CASE WHEN V_SORT_NGAYSINH = 1 AND V_SORT_ASC = 1 THEN f.SORT_NS_NAM END ASC,
                           CASE WHEN V_SORT_NGAYSINH = 1 AND V_SORT_ASC = 0 THEN f.SORT_NS_NAM END DESC NULLS LAST,
                           CASE WHEN V_SORT_NGAYSINH = 1 AND V_SORT_ASC = 1 THEN f.SORT_NS_THANG END ASC,
                           CASE WHEN V_SORT_NGAYSINH = 1 AND V_SORT_ASC = 0 THEN f.SORT_NS_THANG END DESC NULLS LAST,
                           CASE WHEN V_SORT_NGAYSINH = 1 AND V_SORT_ASC = 1 THEN f.SORT_NS_NGAY END ASC,
                           CASE WHEN V_SORT_NGAYSINH = 1 AND V_SORT_ASC = 0 THEN f.SORT_NS_NGAY END DESC NULLS LAST,
                           CASE WHEN V_SORT_DIACHI = 1 AND V_SORT_ASC = 1 THEN LOWER(f.DIA_CHI_THUONG_TRU) END ASC,
                           CASE WHEN V_SORT_DIACHI = 1 AND V_SORT_ASC = 0 THEN LOWER(f.DIA_CHI_THUONG_TRU) END DESC NULLS LAST,
                           CASE WHEN V_SORT_HOTEN = 1 AND V_SORT_ASC = 1 THEN f.SORT_THEO_TEN END ASC,
                           CASE WHEN V_SORT_HOTEN = 1 AND V_SORT_ASC = 0 THEN f.SORT_THEO_TEN END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND V_SORT_FIELD = 'sohosolandau' THEN f.LL_SO_HO_SO_LAN_DAU END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND V_SORT_FIELD = 'sohosolandau' THEN f.LL_SO_HO_SO_LAN_DAU END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND V_SORT_FIELD = 'cccd' THEN f.LL_CCCD END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND V_SORT_FIELD = 'cccd' THEN f.LL_CCCD END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND V_SORT_FIELD = 'gioitinh' THEN f.TEN_GIOI_TINH END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND V_SORT_FIELD = 'gioitinh' THEN f.TEN_GIOI_TINH END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND V_SORT_FIELD = 'anphat' THEN f.AN_PHAT END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND V_SORT_FIELD = 'anphat' THEN f.AN_PHAT END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND V_SORT_FIELD = 'ngaydentrai' THEN f.NGAY_DEN_TRAI END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND V_SORT_FIELD = 'ngaydentrai' THEN f.NGAY_DEN_TRAI END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND V_SORT_FIELD = 'ngayhethan' THEN f.NGAY_HET_HAN END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND V_SORT_FIELD = 'ngayhethan' THEN f.NGAY_HET_HAN END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND V_SORT_FIELD = 'xep_loai_quy_iv' THEN f.XEP_LOAI_QUY_IV END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND V_SORT_FIELD = 'xep_loai_quy_iv' THEN f.XEP_LOAI_QUY_IV END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND V_SORT_FIELD = 'xep_loai_quy_iii' THEN f.XEP_LOAI_QUY_III END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND V_SORT_FIELD = 'xep_loai_quy_iii' THEN f.XEP_LOAI_QUY_III END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND V_SORT_FIELD = 'xep_loai_quy_ii' THEN f.XEP_LOAI_QUY_II END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND V_SORT_FIELD = 'xep_loai_quy_ii' THEN f.XEP_LOAI_QUY_II END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 AND V_SORT_FIELD = 'xep_loai_quy_i' THEN f.XEP_LOAI_QUY_I END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 AND V_SORT_FIELD = 'xep_loai_quy_i' THEN f.XEP_LOAI_QUY_I END DESC NULLS LAST,
                           CASE WHEN V_SORT_NGAYSINH = 0 AND V_SORT_DIACHI = 0 AND V_SORT_HOTEN = 0 AND V_SORT_DEFAULT = 0
                                THEN f.PHAM_NHAN_ID END DESC NULLS LAST,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 1 THEN f.PHAM_NHAN_ID END ASC,
                           CASE WHEN V_SORT_DEFAULT = 1 AND V_SORT_ASC = 0 THEN f.PHAM_NHAN_ID END DESC NULLS LAST,
                           f.PHAM_NHAN_ID DESC
                   ) AS RN
              FROM filtered f
        )
        SELECT PHAM_NHAN_ID,
               LL_SO_HO_SO_LAN_DAU AS SO_HO_SO_LAN_DAU,
               LL_CCCD AS CCCD,
               LL_HO_TEN AS HO_TEN,
               LL_NGAY_SINH AS NGAY_SINH,
               TEN_GIOI_TINH AS GIOI_TINH,
               DIA_CHI_THUONG_TRU,
               TOI_DANH,
               AN_PHAT,
               NGAY_DEN_TRAI,
               NGAY_HET_HAN,
               XEP_LOAI_QUY_I,
               XEP_LOAI_QUY_II,
               XEP_LOAI_QUY_III,
               XEP_LOAI_QUY_IV,
               XEP_LOAI_6_THANG_DAU_NAM,
               XEP_LOAI_6_THANG_CUOI_NAM,
               XEP_LOAI_CA_NAM,
               MO_KY_XEP_LOAI_ID,
               KY_XEP_LOAI,
               TOTAL_COUNT
          FROM numbered
         WHERE P_MAX_RESULT_COUNT IS NULL
            OR (RN > NVL(P_SKIP_COUNT, 0) AND RN <= NVL(P_SKIP_COUNT, 0) + P_MAX_RESULT_COUNT);

END SP_GET_QUYET_DINH_XEP_LOAI_CAI_TAO;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_RA_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_RA_TRAI" (
    p_LAI_LICH_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        pktrt.KTRT_PN_LAI_LICH_ID,
        pktrt.KTRT_NGAY_THA  AS "NgayTha",
        dtht.THT_TEN  AS "TruongHopTha",
        pktrt.KTRT_NGAY_TRINH_DIEN  AS "NgayTrinhDien",
        NULL AS "NoiVe"
    FROM PN_KET_THUC_RA_TRAIS pktrt 
    LEFT JOIN DM_TRUONG_HOP_THAS dtht ON pktrt.KTRT_TRUONG_HOP_THA_ID = dtht.ID
    WHERE pktrt.KTRT_PN_LAI_LICH_ID = p_LAI_LICH_ID;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_RA_TRAI;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_RA_TRAI_CHUNG_NHAN_CHXAPT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_RA_TRAI_CHUNG_NHAN_CHXAPT" (
    p_trai_giam_id       IN  NUMBER      DEFAULT NULL,
    p_ra_tu_ngay         IN  DATE        DEFAULT NULL,
    p_ra_den_ngay        IN  DATE        DEFAULT NULL,
    p_tinh_trang_id      IN  NUMBER      DEFAULT NULL,
    p_doi_tuong          IN  NUMBER      DEFAULT NULL,
    p_phan_doi_id        IN  NUMBER      DEFAULT NULL,
    p_quoc_tich_id       IN  NUMBER      DEFAULT NULL,
    p_truong_hop_tha_id  IN  NUMBER      DEFAULT NULL,
    p_so_gcn_tu          IN  VARCHAR2    DEFAULT NULL,
    p_tim_kiem           IN  NVARCHAR2   DEFAULT NULL,
    p_maxresultcount     IN  NUMBER      DEFAULT 0,
    p_skipcount          IN  NUMBER      DEFAULT 0
) AS
    v_skip   NUMBER;
    v_limit  NUMBER;
    v_tk_like VARCHAR2(4000);
    c1       SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    IF p_tim_kiem IS NOT NULL AND LENGTH(TRIM(p_tim_kiem)) > 0 THEN
        v_tk_like := '%' || UPPER(TRIM(p_tim_kiem)) || '%';
    ELSE
        v_tk_like := NULL;
    END IF;

    OPEN c1 FOR
    WITH
    tsht AS (
        SELECT
            MAX(CASE WHEN tsht.tsht_tham_so = 'CHUC_VU_KY' THEN TRIM(CAST(tsht.tsht_gia_tri AS VARCHAR2(500))) END) AS chuc_vu_ky,
            MAX(CASE WHEN tsht.tsht_tham_so = 'DIA_DANH_BC' THEN TRIM(CAST(tsht.tsht_gia_tri AS VARCHAR2(500))) END) AS dia_danh_bc,
            MAX(CASE WHEN tsht.tsht_tham_so = 'CO_QUAN_CHU_QUAN' THEN TRIM(CAST(tsht.tsht_gia_tri AS VARCHAR2(500))) END) AS co_quan_chu_quan,
            MAX(CASE WHEN tsht.tsht_tham_so = 'HO_TEN_NGUOI_KY' THEN TRIM(CAST(tsht.tsht_gia_tri AS VARCHAR2(500))) END) AS ho_ten_nguoi_ky,
            MAX(CASE WHEN tsht.tsht_tham_so = 'CAN_CU_TT_THI_HANH_AN' THEN TRIM(CAST(tsht.tsht_gia_tri AS VARCHAR2(4000))) END) AS can_cu_tt_thi_hanh_an
        FROM QLPN.THAM_SO_HE_THONGS tsht
        WHERE NVL(tsht.IS_DELETED, 0) = 0
          AND tsht.tsht_tham_so IN (
              'CHUC_VU_KY', 'DIA_DANH_BC', 'CO_QUAN_CHU_QUAN', 'HO_TEN_NGUOI_KY', 'CAN_CU_TT_THI_HANH_AN'
          )
    ),
    THA_raw AS (
        SELECT
            THA.THA_PNLAI_LICH_ID,
            THA.THA_SO_BAN_AN,
            THA.THA_NGAY_BAN_AN,
            THA.THA_SO_QD_THA,
            THA.THA_NGAY_QD_THA,
            DV_TOA.TTP_TEN AS THA_DIA_PHUONG_TOA_QD_THA,
            DV_LAP.TTP_TEN AS THA_DIA_PHUONG_CO_QUAN_LAP,
            ROW_NUMBER() OVER (
                PARTITION BY THA.THA_PNLAI_LICH_ID
                ORDER BY NVL(THA.THA_NGAY_HET_HAN, THA.THA_NGAY_BAT) DESC NULLS LAST,
                         NVL(THA.THA_NGAY_DEN_TRAI, THA.THA_NGAY_BAT) DESC NULLS LAST,
                         THA.ID DESC
            ) AS rn
        FROM QLPN.PN_THI_HANH_AN THA
        LEFT JOIN QLPN.DM_TINH_THANH_PHO DV_TOA
            ON THA.THA_DIA_PHUONG_TOA_QD_THA_ID = DV_TOA.ID

        LEFT JOIN QLPN.DM_TINH_THANH_PHO DV_LAP
            ON THA.THA_DIA_PHUONG_DON_CO_QUAN_LAP_ID = DV_LAP.ID

        WHERE NVL(THA.IS_DELETED, 0) = 0
    ),
    THA AS (SELECT * FROM THA_raw WHERE rn = 1),
    TNB_one AS (
        SELECT t.PHAM_NHAN_ID, t.HO_TEN_THAN_NHAN
        FROM (
            SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN,
                   ROW_NUMBER() OVER (PARTITION BY PHAM_NHAN_ID ORDER BY ID) AS rn
            FROM QLPN.THAN_NHAN_NGUOI_THANS
            WHERE QUAN_HE_ID = 19 AND NVL(IS_DELETED, 0) = 0
        ) t
        WHERE t.rn = 1
    ),
    TNM_one AS (
        SELECT t.PHAM_NHAN_ID, t.HO_TEN_THAN_NHAN
        FROM (
            SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN,
                   ROW_NUMBER() OVER (PARTITION BY PHAM_NHAN_ID ORDER BY ID) AS rn
            FROM QLPN.THAN_NHAN_NGUOI_THANS
            WHERE QUAN_HE_ID = 18 AND NVL(IS_DELETED, 0) = 0
        ) t
        WHERE t.rn = 1
    ),
    KT_in_range AS (
        SELECT k.*
        FROM (
            SELECT k0.*,
                   ROW_NUMBER() OVER (
                       PARTITION BY k0.KTRT_PN_LAI_LICH_ID
                       ORDER BY NVL(k0.KTRT_NGAY_THA, k0.CREATION_TIME) DESC NULLS LAST
                   ) AS rn
            FROM QLPN.PN_KET_THUC_RA_TRAIS k0
            WHERE NVL(k0.IS_DELETED, 0) = 0
              AND (p_ra_tu_ngay IS NULL OR TRUNC(k0.KTRT_NGAY_THA) >= TRUNC(p_ra_tu_ngay))
              AND (p_ra_den_ngay IS NULL OR TRUNC(k0.KTRT_NGAY_THA) <= TRUNC(p_ra_den_ngay))
        ) k
        WHERE k.rn = 1
    ),
    ds_inner AS (
        SELECT
            t.KTRT_NGAY_THA,
            t.KTRT_NGAY_TRINH_DIEN,
            t.KTRT_SO_GCN,
            t.KTRT_TRUONG_HOP_THA_ID,
            v.PHAM_NHAN_ID,
            v.HO_TEN,
            V.HO_TEN_ORDER,
            v.CCCD,
            v.GIOI_TINH,
            v.NGAY_SINH,
            v.NAM_SINH,
            v.TEN_KHAC,
            v.NGUYEN_QUAN,
            v.DAN_TOC,
            v.QUOC_TICH,
            v.NOI_THUONG_TRU_DAY_DU,
            v.DIA_CHI_THUONG_TRU,
            v.NOI_THA_VE_CU_TRU,
            v.NOI_THA_VE_CU_TRU_XA,
            v.NOI_THA_VE_CU_TRU_TINH,
            v.TOI_DANH,
            v.TOI_DANH_ID,
            v.AN_PHAT,
            v.NGAY_HET_AN,
            v.NGAY_BAT_AN_PHAT,
            v.SO_BAN_AN,
            v.NGAY_BAN_AN,
            v.TOA_XU_TEN,
            v.TOA_XU_DIA_PHUONG,
            v.SO_QD_THA,
            v.NGAY_QD_THA,
            v.CO_QUAN_QD_THA,
            v.LL_TINH_TRANG_ID,
            v.PHAN_DOI,
            v.PHAN_TRAI,
            v.QUOC_TICH_ID,
            v.SO_HO_SO,
            v.TRAI_GIAM,
            v.TRAI_GIAM_ID,
            REPLACE(REPLACE(TRIM(CAST(COALESCE(v.TOI_DANH_ID, v.TOI_DANH) AS VARCHAR2(4000))), '[', ''), ']', '') AS toi_csv
        FROM KT_in_range t
        INNER JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = t.KTRT_PN_LAI_LICH_ID
           AND NVL(v.IS_DELETED, 0) = 0
        WHERE (p_trai_giam_id IS NULL OR v.TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)
          AND (p_tinh_trang_id IS NULL OR v.LL_TINH_TRANG_ID = p_tinh_trang_id)
          AND (p_truong_hop_tha_id IS NULL OR t.KTRT_TRUONG_HOP_THA_ID = p_truong_hop_tha_id)
          AND (p_quoc_tich_id IS NULL OR v.QUOC_TICH_ID = p_quoc_tich_id)
          AND (
              p_so_gcn_tu IS NULL
              OR TRIM(p_so_gcn_tu) = ''
              OR UPPER(NVL(TRIM(t.KTRT_SO_GCN), '')) LIKE UPPER(TRIM(p_so_gcn_tu)) || '%'
          )
          AND (
              v_tk_like IS NULL
              OR UPPER(NVL(v.HO_TEN, '')) LIKE v_tk_like
              OR UPPER(NVL(v.CCCD, '')) LIKE v_tk_like
              OR UPPER(NVL(TO_CHAR(v.SO_HO_SO), '')) LIKE v_tk_like
          )
    ),
    ds AS (
        SELECT
            di.*,
            dm.TD_CHUONG AS td_chuong
        FROM ds_inner di
        LEFT JOIN QLPN.DM_TOI_DANHS dm
            ON dm.ID = CASE
                WHEN REGEXP_LIKE(REGEXP_SUBSTR(di.toi_csv, '[0-9]+', 1, 1), '^[0-9]+$')
                THEN TO_NUMBER(REGEXP_SUBSTR(di.toi_csv, '[0-9]+', 1, 1))
            END
           AND NVL(dm.IS_DELETED, 0) = 0
        WHERE (p_doi_tuong IS NULL
               OR (p_doi_tuong = 1 AND TRIM(TO_CHAR(dm.TD_CHUONG)) = '13')
               OR (p_doi_tuong = 2 AND (dm.TD_CHUONG IS NULL OR TRIM(TO_CHAR(dm.TD_CHUONG)) <> '13')))
    ),
    toi_ten_agg AS (
        SELECT ids.pham_nhan_id,
               LISTAGG(NVL(TRIM(CAST(dm.TD_TEN AS VARCHAR2(4000))), TO_CHAR(ids.td_id)), ', ')
                   WITHIN GROUP (ORDER BY ids.ord) AS toi_danh_ten
        FROM (
            SELECT z.pham_nhan_id,
                   CASE
                       WHEN REGEXP_LIKE(TRIM(REGEXP_SUBSTR(z.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
                       THEN TO_NUMBER(TRIM(REGEXP_SUBSTR(z.csv, '[^,]+', 1, LEVEL)))
                   END AS td_id,
                   LEVEL AS ord
            FROM (
                SELECT pham_nhan_id,
                       toi_csv AS csv
                FROM ds
            ) z
            WHERE TRIM(z.csv) IS NOT NULL
            CONNECT BY LEVEL <= REGEXP_COUNT(z.csv, ',') + 1
              AND PRIOR z.pham_nhan_id = z.pham_nhan_id
              AND PRIOR SYS_GUID() IS NOT NULL
              AND REGEXP_SUBSTR(z.csv, '[^,]+', 1, LEVEL) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(z.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
        ) ids
        LEFT JOIN QLPN.DM_TOI_DANHS dm
            ON dm.ID = ids.td_id
           AND NVL(dm.IS_DELETED, 0) = 0
        WHERE ids.td_id IS NOT NULL
        GROUP BY ids.pham_nhan_id
    )
    SELECT
        d.PHAM_NHAN_ID,
        NVL(TRIM(CAST(ts.co_quan_chu_quan AS VARCHAR2(500))), '') AS CO_QUAN_CHU_QUAN,
        NVL(TRIM(CAST(d.TRAI_GIAM AS VARCHAR2(500))), '') AS TEN_TRAI_GIAM,
        NVL(TRIM(CAST(ts.chuc_vu_ky AS VARCHAR2(500))), '') AS TSHT_CHUC_VU_KY,
        NVL(TRIM(CAST(ts.ho_ten_nguoi_ky AS VARCHAR2(500))), '') AS TSHT_HO_TEN_NGUOI_KY,
        NVL(TRIM(CAST(ts.dia_danh_bc AS VARCHAR2(500))), '') AS TSHT_DIA_DANH_BC,
        NVL(TRIM(CAST(ts.can_cu_tt_thi_hanh_an AS VARCHAR2(4000))), '') AS TSHT_CAN_CU_TT_THI_HANH_AN,
        NVL(TRIM(CAST(d.KTRT_SO_GCN AS VARCHAR2(500))), '') AS SO_GCN,
        NVL(TRIM(TO_CHAR(d.SO_HO_SO)), '') AS SO_HO_SO,
        UPPER(NVL(TRIM(CAST(d.HO_TEN AS VARCHAR2(500))), '')) AS HO_TEN_HOA,
        NVL(TRIM(CAST(d.HO_TEN AS VARCHAR2(500))), '') AS HO_TEN,
        NVL(TRIM(CAST(d.CCCD AS VARCHAR2(100))), '') AS CCCD,
        NVL(TRIM(CAST(d.GIOI_TINH AS VARCHAR2(100))), '') AS GIOI_TINH,
        CASE
            WHEN d.NGAY_SINH IS NOT NULL
                 AND REGEXP_LIKE(TRIM(CAST(d.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(CAST(d.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN d.NAM_SINH IS NOT NULL AND d.NAM_SINH > 0 THEN TO_CHAR(d.NAM_SINH)
            WHEN d.NGAY_SINH IS NOT NULL THEN TRIM(CAST(d.NGAY_SINH AS VARCHAR2(400)))
            ELSE NULL
        END AS NGAY_SINH,
        CASE
            WHEN d.NAM_SINH IS NOT NULL AND d.NAM_SINH > 0 THEN TO_CHAR(d.NAM_SINH)
            WHEN d.NGAY_SINH IS NOT NULL
                 AND REGEXP_LIKE(TRIM(CAST(d.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(EXTRACT(YEAR FROM TO_DATE(TRIM(CAST(d.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY')))
            WHEN d.NGAY_SINH IS NOT NULL AND REGEXP_LIKE(TRIM(CAST(d.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{4}$')
            THEN TRIM(CAST(d.NGAY_SINH AS VARCHAR2(100)))
            ELSE NULL
        END AS NAM_SINH_HIEN_THI,
        NVL(TRIM(CAST(d.TEN_KHAC AS VARCHAR2(500))), '') AS TEN_KHAC,
        NVL(TRIM(CAST(d.NGUYEN_QUAN AS VARCHAR2(4000))), '') AS NGUYEN_QUAN,
        NVL(TRIM(CAST(d.DAN_TOC AS VARCHAR2(200))), '') AS DAN_TOC,
        NVL(TRIM(CAST(d.QUOC_TICH AS VARCHAR2(200))), '') AS QUOC_TICH,
        NVL(TRIM(CAST(NVL(d.NOI_THUONG_TRU_DAY_DU, d.DIA_CHI_THUONG_TRU) AS VARCHAR2(4000))), '') AS NOI_DKTT,
        NVL(TRIM(CAST(d.NOI_THA_VE_CU_TRU AS VARCHAR2(4000))), '') AS DIA_CHI_VE_CU_TRU,
        NVL(TRIM(CAST(tnb.HO_TEN_THAN_NHAN AS VARCHAR2(500))), '') AS HO_TEN_BO,
        NVL(TRIM(CAST(tnm.HO_TEN_THAN_NHAN AS VARCHAR2(500))), '') AS HO_TEN_ME,
        u'UBND ' || NVL(TRIM(CAST(d.NOI_THA_VE_CU_TRU_XA AS NVARCHAR2(500))), u'')
            || u', ' || NVL(TRIM(CAST(d.NOI_THA_VE_CU_TRU_TINH AS NVARCHAR2(500))), u'') AS KINH_GUI_UBND,
        u'C\00f4ng an ' || NVL(TRIM(CAST(d.NOI_THA_VE_CU_TRU_TINH AS NVARCHAR2(500))), u'') AS KINH_GUI_CONG_AN,
        u'Trung t\00e2m Y t\1ebf d\1ef1 ph\00f2ng ' || NVL(TRIM(CAST(d.NOI_THA_VE_CU_TRU_TINH AS NVARCHAR2(500))), u'') AS KINH_GUI_Y_TE_DP,
        COALESCE(
            NULLIF(TRIM(tt.toi_danh_ten), ''),
            NULLIF(TRIM(CAST(d.TOI_DANH AS VARCHAR2(4000))), ''),
            CAST(u'Ch\01b0a x\00e1c \0111\1ecbnh' AS VARCHAR2(200))
        ) AS TOI_DANH,
        TO_CHAR(TRUNC(d.NGAY_BAT_AN_PHAT), 'DD/MM/YYYY') AS NGAY_BAT,
        NVL(TRIM(CAST(d.AN_PHAT AS VARCHAR2(4000))), '') AS AN_PHAT,
        CASE
            WHEN QLPN.PKG_TINH_AN.FN_TINH_SO_LAN_GIAM_AN(d.PHAM_NHAN_ID) > 0
            THEN TRIM(CAST(QLPN.PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(d.PHAM_NHAN_ID) AS VARCHAR2(500)))
            ELSE NULL
        END AS DA_GIAM_FORMAT,
        NVL(
            NULLIF(TRIM(CAST(QLPN.FN_GET_LIET_KE_HPBS(d.PHAM_NHAN_ID) AS VARCHAR2(4000))), ''),
            CAST(u'Kh\00f4ng' AS VARCHAR2(50))
        ) AS HPBS_HIEN_THI,
        NVL(TRIM(CAST(d.SO_BAN_AN AS VARCHAR2(500))), '') AS SO_BAN_AN,
        TO_CHAR(TRUNC(d.NGAY_BAN_AN), 'DD/MM/YYYY') AS NGAY_BAN_AN,
        TRIM(NVL(TRIM(CAST(d.TOA_XU_TEN AS VARCHAR2(500))), '')
            || NVL2(d.TOA_XU_DIA_PHUONG, ', ' || TRIM(CAST(d.TOA_XU_DIA_PHUONG AS VARCHAR2(500))), '')) AS TOA_XU,
        CASE
            WHEN th.THA_PNLAI_LICH_ID IS NOT NULL AND th.THA_SO_BAN_AN IS NOT NULL
            THEN u'B\1ea3n \00e1n s\1ed1 ' || TRIM(CAST(th.THA_SO_BAN_AN AS NVARCHAR2(200)))
                || u' ng\00e0y ' || TO_CHAR(th.THA_NGAY_BAN_AN, 'DD/MM/YYYY')
                || u' c\1ee7a To\00e0 \00e1n nh\00e2n d\00e2n ' || NVL(TRIM(CAST(th.THA_DIA_PHUONG_TOA_QD_THA AS NVARCHAR2(500))), u'')
            ELSE NULL
        END AS CAN_CU_BAN_AN,
        CASE
            WHEN th.THA_PNLAI_LICH_ID IS NOT NULL AND th.THA_SO_QD_THA IS NOT NULL
            THEN u'Quy\1ebft \0111\1ecbnh thi h\00e0nh \00e1n s\1ed1 ' || TRIM(CAST(th.THA_SO_QD_THA AS NVARCHAR2(200)))
                || u' ng\00e0y ' || TO_CHAR(th.THA_NGAY_QD_THA, 'DD/MM/YYYY')
                || u' c\1ee7a TAND ' || NVL(TRIM(CAST(th.THA_DIA_PHUONG_CO_QUAN_LAP AS NVARCHAR2(500))), u'')
            ELSE NULL
        END AS CAN_CU_QD_THA,
        TO_CHAR(TRUNC(d.NGAY_HET_AN), 'DD/MM/YYYY') AS NGAY_HET_HAN,
        TO_CHAR(TRUNC(d.KTRT_NGAY_THA), 'DD/MM/YYYY') AS NGAY_RA_TRAI,
        TO_CHAR(TRUNC(d.KTRT_NGAY_TRINH_DIEN), 'DD/MM/YYYY') AS NGAY_TRINH_DIEN,
        NVL(TRIM(CAST(dmttpn.TTPN_TEN AS VARCHAR2(500))), '') AS TINH_TRANG,
        NVL(TRIM(CAST(d.PHAN_DOI AS VARCHAR2(500))), '') AS PHAN_DOI,
        NVL(TRIM(CAST(d.PHAN_TRAI AS VARCHAR2(500))), '') AS PHAN_TRAI,
        NVL(TRIM(CAST(ts.dia_danh_bc AS NVARCHAR2(500))), u'')
            || u', ng\00e0y ' || TO_CHAR(SYSDATE, 'DD')
            || u' th\00e1ng ' || TO_CHAR(SYSDATE, 'MM')
            || u' n\0103m ' || TO_CHAR(SYSDATE, 'YYYY') AS DIA_DIEM_NGAY_BAN_HANH_STR
    FROM ds d
    LEFT JOIN toi_ten_agg tt
        ON tt.pham_nhan_id = d.PHAM_NHAN_ID
    LEFT JOIN THA th
        ON th.THA_PNLAI_LICH_ID = d.PHAM_NHAN_ID
    LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS dmttpn
        ON d.LL_TINH_TRANG_ID = dmttpn.ID
       AND NVL(dmttpn.IS_DELETED, 0) = 0
    LEFT JOIN TNB_one tnb
        ON tnb.PHAM_NHAN_ID = d.PHAM_NHAN_ID
    LEFT JOIN TNM_one tnm
        ON tnm.PHAM_NHAN_ID = d.PHAM_NHAN_ID
    CROSS JOIN tsht ts
    ORDER BY d.KTRT_NGAY_THA, d.HO_TEN_ORDER NULLS LAST
    OFFSET v_skip ROWS
    FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_RA_TRAI_CHUNG_NHAN_CHXAPT: ' || SQLERRM);
END SP_GET_RA_TRAI_CHUNG_NHAN_CHXAPT;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_RA_TRAI_THONG_BAO_NGAY_CHXAPT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_RA_TRAI_THONG_BAO_NGAY_CHXAPT" AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    pn_id_list AS (
        SELECT /*+ MATERIALIZE DYNAMIC_SAMPLING(g 4) */
            g.PN_ID AS pn_lai_lich_id
        FROM QLPN.GTT_PN_IDS g
    ),
    vw_core AS (
        SELECT /*+ LEADING(b) USE_NL(v) USE_NL(rt) USE_NL(dttp_lap) */
            b.pn_lai_lich_id AS PHAM_NHAN_ID,
            v.HO_TEN,
            v.HO_TEN_ORDER,
            v.CCCD,
            v.GIOI_TINH,
            v.NGAY_SINH,
            v.NAM_SINH,
            v.TEN_KHAC,
            v.NGUYEN_QUAN,
            v.DAN_TOC,
            v.QUOC_TICH,
            v.NGHE_NGHIEP,
            v.SO_TIEN_AN,
            v.SO_TIEN_SU,
            v.NOI_THUONG_TRU_DAY_DU,
            v.DIA_CHI_THUONG_TRU,
            v.NOI_THA_VE_CU_TRU,
            v.NOI_THA_VE_CU_TRU_XA,
            v.NOI_THA_VE_CU_TRU_TINH,
            v.TOI_DANH,
            v.AN_PHAT,
            v.NGAY_HET_AN,
            v.NGAY_BAT_AN_PHAT,
            v.NGAY_DEN_TRAI,
            v.SO_BAN_AN,
            v.NGAY_BAN_AN,
            v.TOA_XU_TEN,
            v.TOA_XU_DIA_PHUONG,
            v.SO_QD_THA,
            v.NGAY_QD_THA,
            v.CO_QUAN_QD_THA,
            v.TOA_QD_THA_DIA_PHUONG AS THA_DIA_PHUONG_TOA_QD_THA,
            dttp_lap.TTP_TEN AS THA_DIA_PHUONG_CO_QUAN_LAP,
            v.LL_TINH_TRANG_ID,
            v.PHAN_DOI,
            v.PHAN_TRAI,
            v.TRAI_GIAM,
            NULL AS LL_NGAY_CAP_CCCD,
            NULL AS LL_NOI_CAP_CCCD
        FROM pn_id_list b
        LEFT JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = b.pn_lai_lich_id
           AND NVL(v.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt
            ON rt.PHAM_NHAN_ID = b.pn_lai_lich_id
           AND NVL(rt.IS_DELETED, 0) = 0
           AND NVL(rt.LL_IS_DELETED, 0) = 0
           AND NVL(rt.THA_IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO dttp_lap
            ON rt.THA_DIA_PHUONG_DON_CO_QUAN_LAP_ID = dttp_lap.ID
           AND NVL(dttp_lap.IS_DELETED, 0) = 0
    ),
    kt_one AS (
        SELECT
            k.KTRT_PN_LAI_LICH_ID,
            k.KTRT_NGAY_THA,
            k.KTRT_NGAY_TRINH_DIEN,
            k.KTRT_SO_GCN
        FROM (
            SELECT /*+ LEADING(pid) USE_NL(k0) */
                k0.KTRT_PN_LAI_LICH_ID,
                k0.KTRT_NGAY_THA,
                k0.KTRT_NGAY_TRINH_DIEN,
                k0.KTRT_SO_GCN,
                ROW_NUMBER() OVER (
                    PARTITION BY k0.KTRT_PN_LAI_LICH_ID
                    ORDER BY NVL(k0.KTRT_NGAY_THA, k0.CREATION_TIME) DESC NULLS LAST
                ) AS rn
            FROM QLPN.PN_KET_THUC_RA_TRAIS k0
            INNER JOIN pn_id_list pid
                ON pid.pn_lai_lich_id = k0.KTRT_PN_LAI_LICH_ID
            WHERE NVL(k0.IS_DELETED, 0) = 0
        ) k
        WHERE k.rn = 1
    ),
    base AS (
        SELECT /*+ MATERIALIZE */
            d.*,
            kt.KTRT_NGAY_THA,
            kt.KTRT_NGAY_TRINH_DIEN,
            kt.KTRT_SO_GCN,
            COALESCE(TRUNC(kt.KTRT_NGAY_THA), TRUNC(d.NGAY_HET_AN), TRUNC(SYSDATE)) AS ngay_thong_bao
        FROM vw_core d
        LEFT JOIN kt_one kt
            ON kt.KTRT_PN_LAI_LICH_ID = d.PHAM_NHAN_ID
    ),
    -- Hàm ch? ph? thu?c (PHAM_NHAN_ID, ngay_thong_bao). Tính m?t l?n r?i tr?i l?i ?úng s? dòng c?a base
    -- ?? join cu?i theo PHAM_NHAN_ID v?n ra cùng s? dòng nh? b?n c?.
    fn_vals AS (
        SELECT /*+ MATERIALIZE */
            k.PHAM_NHAN_ID,
            k.ngay_thong_bao,
            QLPN.PKG_TINH_AN.FN_TINH_SO_LAN_GIAM_AN(k.PHAM_NHAN_ID) AS so_lan_giam,
            QLPN.PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(k.PHAM_NHAN_ID) AS giam_an_hien_thi,
            QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(
                k.PHAM_NHAN_ID, k.ngay_thong_bao
            ) AS thoi_gian_da_chap_hanh,
            QLPN.FN_GET_DA_CHAP_HANH_TRU_2_THANG_TEXT(k.PHAM_NHAN_ID, k.ngay_thong_bao) AS thoi_gian_da_chap_hanh_truoc_2_thang,
            QLPN.FN_GET_LIET_KE_HPBST_TNDST(k.PHAM_NHAN_ID) AS hpbs_hien_thi,
            QLPN.FN_GET_LIET_KE_HPBS_KHAC(k.PHAM_NHAN_ID) AS hpbs_khac,
            FN_GET_THONG_TIN_HPBS_PT(k.PHAM_NHAN_ID) AS hpbs_pt
        FROM (
            SELECT DISTINCT
                b.PHAM_NHAN_ID,
                b.ngay_thong_bao
            FROM base b
        ) k
    ),
    scalar_fns AS (
        SELECT /*+ MATERIALIZE */
            b.PHAM_NHAN_ID,
            f.so_lan_giam,
            f.giam_an_hien_thi,
            f.thoi_gian_da_chap_hanh,
            f.thoi_gian_da_chap_hanh_truoc_2_thang,
            f.hpbs_hien_thi,
            f.hpbs_khac,
            f.hpbs_pt
        FROM base b
        LEFT JOIN fn_vals f
            ON f.PHAM_NHAN_ID = b.PHAM_NHAN_ID
           AND f.ngay_thong_bao = b.ngay_thong_bao
    ),
    xep_loai_by_year AS (
        SELECT /*+ MATERIALIZE LEADING(pid) USE_NL(x) */
            x.PHAM_NHAN_ID,
            x.XEP_LOAI_NAM AS nam,
            MAX(d1.XLCT_TEN) AS q1_ten,
            MAX(d2.XLCT_TEN) AS q2_ten,
            MAX(d3.XLCT_TEN) AS q3_ten,
            MAX(d4.XLCT_TEN) AS q4_ten
        FROM QLPN.XEP_LOAIS x
        INNER JOIN pn_id_list pid
            ON pid.pn_lai_lich_id = x.PHAM_NHAN_ID
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS d1
            ON d1.ID = x.XEP_LOAI_QUY_I
           AND NVL(d1.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS d2
            ON d2.ID = x.XEP_LOAI_QUY_II
           AND NVL(d2.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS d3
            ON d3.ID = x.XEP_LOAI_QUY_III
           AND NVL(d3.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS d4
            ON d4.ID = x.XEP_LOAI_QUY_IV
           AND NVL(d4.IS_DELETED, 0) = 0
        WHERE NVL(x.IS_DELETED, 0) = 0
          AND x.XEP_LOAI_NAM IS NOT NULL
        GROUP BY x.PHAM_NHAN_ID, x.XEP_LOAI_NAM
    ),
    xep_loai_recent AS (
        SELECT
            PHAM_NHAN_ID,
            nam,
            q1_ten,
            q2_ten,
            q3_ten,
            q4_ten
        FROM (
            SELECT
                y.*,
                ROW_NUMBER() OVER (
                    PARTITION BY y.PHAM_NHAN_ID
                    ORDER BY y.nam DESC
                ) AS rn
            FROM xep_loai_by_year y
        )
        WHERE rn <= 2
    ),
    xep_loai_agg AS (
        SELECT /*+ MATERIALIZE */
            y.PHAM_NHAN_ID,
            LISTAGG(
                u'N\0103m ' || TO_NCHAR(y.nam) || u': '
                || NVL(
                       LTRIM(
                           CAST(
                               NVL2(TRIM(y.q1_ten), u'; Qu\00fd I: ' || TO_NCHAR(TRIM(y.q1_ten)), NULL)
                               || NVL2(TRIM(y.q2_ten), u'; Qu\00fd II: ' || TO_NCHAR(TRIM(y.q2_ten)), NULL)
                               || NVL2(TRIM(y.q3_ten), u'; Qu\00fd III: ' || TO_NCHAR(TRIM(y.q3_ten)), NULL)
                               || NVL2(TRIM(y.q4_ten), u'; Qu\00fd IV: ' || TO_NCHAR(TRIM(y.q4_ten)), NULL)
                               AS VARCHAR2(2000)
                           ),
                           '; '
                       ),
                       u''
                   ),
                CHR(10) ON OVERFLOW TRUNCATE '...' WITH COUNT
            ) WITHIN GROUP (ORDER BY y.nam) AS XEP_LOAI
        FROM xep_loai_recent y
        GROUP BY y.PHAM_NHAN_ID
    ),
    khen_thuong_agg AS (
        SELECT /*+ MATERIALIZE LEADING(pid) USE_NL(kt) */
            kt.PHAM_NHAN_ID,
            LISTAGG(
                TO_CHAR(kt.NGAY_KHEN, 'DD/MM/YYYY') || ' | '
                || NVL(TRIM(CAST(kt.HINH_THUC_KHEN AS VARCHAR2(500))), '')
                || ' | '
                || NVL(TRIM(CAST(kt.LY_DO AS VARCHAR2(1000))), ''),
                CHR(10) ON OVERFLOW TRUNCATE '...' WITH COUNT
            ) WITHIN GROUP (ORDER BY kt.NGAY_KHEN NULLS LAST, kt.ID) AS KHEN_THUONG
        FROM QLPN.KHEN_THUONGS kt
        INNER JOIN pn_id_list pid
            ON pid.pn_lai_lich_id = kt.PHAM_NHAN_ID
        WHERE NVL(kt.IS_DELETED, 0) = 0
        GROUP BY kt.PHAM_NHAN_ID
    ),
    ky_luat_agg AS (
        SELECT /*+ MATERIALIZE LEADING(pid) USE_NL(kl) */
            kl.PHAM_NHAN_ID,
            LISTAGG(
                TO_CHAR(kl.NGAY_QUYET_DINH, 'DD/MM/YYYY') || ' | '
                || NVL(TRIM(CAST(kl.HINH_THUC_KY_LUAT_CU_THE AS VARCHAR2(1000))), '')
                || ' | '
                || NVL(TRIM(CAST(kl.LY_DO_KY_LUAT_CU_THE AS VARCHAR2(1000))), ''),
                CHR(10) ON OVERFLOW TRUNCATE '...' WITH COUNT
            ) WITHIN GROUP (ORDER BY kl.NGAY_QUYET_DINH NULLS LAST, kl.ID) AS KY_LUAT
        FROM QLPN.KY_LUATS kl
        INNER JOIN pn_id_list pid
            ON pid.pn_lai_lich_id = kl.PHAM_NHAN_ID
        GROUP BY kl.PHAM_NHAN_ID
    ),
    pham_toi_moi_agg AS (
        SELECT /*+ MATERIALIZE LEADING(pid) USE_NL(ptm) */
            ptm.PHAM_NHAN_ID,
            LISTAGG(
                TO_CHAR(ptm.NGAY_PHAM_TOI, 'DD/MM/YYYY') || ' | '
                || NVL(ptm_td.toi_danh_ten, '')
                || ' | '
                || NVL(TRIM(CAST(ptm.HINH_THUC_XU_LY AS VARCHAR2(500))), ''),
                CHR(10) ON OVERFLOW TRUNCATE '...' WITH COUNT
            ) WITHIN GROUP (ORDER BY ptm.NGAY_PHAM_TOI NULLS LAST, ptm.ID) AS PHAM_TOI_MOI
        FROM QLPN.PHAM_TOI_MOIS ptm
        INNER JOIN pn_id_list pid
            ON pid.pn_lai_lich_id = ptm.PHAM_NHAN_ID
        CROSS APPLY (
            SELECT LISTAGG(
                       NVL(TRIM(CAST(td.TD_TEN AS VARCHAR2(500))), TRIM(CAST(ids.toi_id AS VARCHAR2(500)))),
                       ', '
                   ) WITHIN GROUP (ORDER BY ids.ord) AS toi_danh_ten
            FROM (
                SELECT LEVEL AS ord,
                       TRIM(REGEXP_SUBSTR(ptm.DM_TOI_DANH, '[^,]+', 1, LEVEL)) AS toi_id
                FROM DUAL
                CONNECT BY LEVEL <= REGEXP_COUNT(ptm.DM_TOI_DANH, ',') + 1
            ) ids
            LEFT JOIN QLPN.DM_TOI_DANHS td
                ON td.ID = TO_NUMBER(ids.toi_id)
               AND NVL(td.IS_DELETED, 0) = 0
        ) ptm_td
        WHERE NVL(ptm.IS_DELETED, 0) = 0
        GROUP BY ptm.PHAM_NHAN_ID
    ),
    nguoi_giam_ho_one AS (
        SELECT
            t.PHAM_NHAN_ID,
            t.HO_TEN_THAN_NHAN,
            t.QUAN_HE,
            t.NOI_O
        FROM (
            SELECT /*+ LEADING(pid) USE_NL(tn) */
                tn.PHAM_NHAN_ID,
                tn.HO_TEN_THAN_NHAN,
                qh.QHVPN_TEN AS QUAN_HE,
                tn.NOI_O,
                ROW_NUMBER() OVER (
                    PARTITION BY tn.PHAM_NHAN_ID
                    ORDER BY tn.ID
                ) AS rn
            FROM QLPN.THAN_NHAN_NGUOI_THANS tn
            INNER JOIN pn_id_list pid
                ON pid.pn_lai_lich_id = tn.PHAM_NHAN_ID
            LEFT JOIN QLPN.DM_QUAN_HE_VOI_PHAM_NHANS qh
                ON qh.ID = tn.QUAN_HE_ID
               AND NVL(qh.IS_DELETED, 0) = 0
            WHERE NVL(tn.IS_DELETED, 0) = 0
              AND tn.THONG_BAO = 1
        ) t
        WHERE t.rn = 1
    )
    SELECT
        b.PHAM_NHAN_ID,
        NULL AS CO_QUAN_CHU_QUAN,
        NVL(TRIM(CAST(b.TRAI_GIAM AS VARCHAR2(500))), '') AS TEN_TRAI_GIAM,
        NULL AS TSHT_CHUC_VU_KY,
        NULL AS TSHT_HO_TEN_NGUOI_KY,
        NULL AS TSHT_DIA_DANH_BC,
        NULL AS TSHT_CAN_CU_TT_THI_HANH_AN,
        NVL(TRIM(CAST(b.KTRT_SO_GCN AS VARCHAR2(500))), '') AS SO_CONG_VAN,
        UPPER(NVL(TRIM(CAST(b.HO_TEN AS VARCHAR2(500))), '')) AS HO_TEN_HOA,
        NVL(TRIM(CAST(b.HO_TEN AS VARCHAR2(500))), '') AS HO_TEN,
        NVL(TRIM(CAST(b.CCCD AS VARCHAR2(100))), '') AS CCCD,
        CASE
            WHEN b.LL_NGAY_CAP_CCCD IS NOT NULL
            THEN TO_CHAR(TRUNC(b.LL_NGAY_CAP_CCCD), 'DD/MM/YYYY')
            ELSE NULL
        END AS NGAY_CAP_CCCD,
        NVL(TRIM(CAST(b.LL_NOI_CAP_CCCD AS VARCHAR2(500))), '') AS NOI_CAP_CCCD,
        NVL(TRIM(CAST(b.GIOI_TINH AS VARCHAR2(100))), '') AS GIOI_TINH,
        CASE
            WHEN b.NGAY_SINH IS NOT NULL
                 AND REGEXP_LIKE(TRIM(CAST(b.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(CAST(b.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN b.NAM_SINH IS NOT NULL AND b.NAM_SINH > 0 THEN TO_CHAR(b.NAM_SINH)
            WHEN b.NGAY_SINH IS NOT NULL THEN TRIM(CAST(b.NGAY_SINH AS VARCHAR2(400)))
            ELSE NULL
        END AS NGAY_SINH,
        NVL(TRIM(CAST(b.TEN_KHAC AS VARCHAR2(500))), '') AS TEN_KHAC,
        NVL(TRIM(CAST(b.NGUYEN_QUAN AS VARCHAR2(4000))), '') AS NGUYEN_QUAN,
        NVL(TRIM(CAST(b.DAN_TOC AS VARCHAR2(200))), '') AS DAN_TOC,
        NVL(TRIM(CAST(b.QUOC_TICH AS VARCHAR2(200))), '') AS QUOC_TICH,
        NVL(TRIM(CAST(b.NGHE_NGHIEP AS VARCHAR2(4000))), '') AS NGHE_NGHIEP,
        NVL(TRIM(CAST(b.SO_TIEN_AN AS VARCHAR2(4000))), '0') AS SO_TIEN_AN,
        NVL(TRIM(CAST(b.SO_TIEN_SU AS VARCHAR2(4000))), '') AS SO_TIEN_SU,
        NVL(
            TRIM(
                CAST(gh.HO_TEN_THAN_NHAN AS VARCHAR2(500))
                || NVL2(NULLIF(TRIM(CAST(gh.QUAN_HE AS VARCHAR2(200))), ''), ', ' || TRIM(CAST(gh.QUAN_HE AS VARCHAR2(200))), '')
                || NVL2(NULLIF(TRIM(CAST(gh.NOI_O AS VARCHAR2(1000))), ''), ', ' || TRIM(CAST(gh.NOI_O AS VARCHAR2(1000))), '')
            ),
            ''
        ) AS NGUOI_GIAM_HO,
        NVL(TRIM(CAST(NVL(b.NOI_THUONG_TRU_DAY_DU, b.DIA_CHI_THUONG_TRU) AS VARCHAR2(4000))), '') AS NOI_DKTT,
        b.NOI_THA_VE_CU_TRU AS DIA_CHI_VE_CU_TRU,
        NVL(TRIM(CAST(b.NOI_THA_VE_CU_TRU_XA AS NVARCHAR2(500))), u'') || u', ' || NVL(TRIM(CAST(b.NOI_THA_VE_CU_TRU_TINH AS NVARCHAR2(500))), u'') AS KINH_GUI_UBND,
        NVL(TRIM(CAST(b.NOI_THA_VE_CU_TRU_TINH AS NVARCHAR2(500))), u'') AS KINH_GUI_CONG_AN,
        NVL(TRIM(CAST(b.NOI_THA_VE_CU_TRU_XA AS NVARCHAR2(500))), u'') AS KINH_GUI_CONG_AN_XA,
        u'Trung t\00e2m Y t\1ebf d\1ef1 ph\00f2ng ' || NVL(TRIM(CAST(b.NOI_THA_VE_CU_TRU_TINH AS NVARCHAR2(500))), u'') AS KINH_GUI_Y_TE_DP,
        COALESCE(
            NULLIF(TRIM(CAST(b.TOI_DANH AS VARCHAR2(4000))), ''),
            CAST(u'Ch\01b0a x\00e1c \0111\1ecbnh' AS VARCHAR2(200))
        ) AS TOI_DANH,
        TO_CHAR(TRUNC(b.NGAY_BAT_AN_PHAT), 'DD/MM/YYYY') AS NGAY_BAT,
        NVL(TRIM(CAST(b.AN_PHAT AS VARCHAR2(4000))), '') AS AN_PHAT,
        NVL(TRIM(CAST(b.SO_BAN_AN AS VARCHAR2(500))), '') AS SO_BAN_AN,
        TO_CHAR(TRUNC(b.NGAY_BAN_AN), 'DD/MM/YYYY') AS NGAY_BAN_AN,
        NVL(TRIM(CAST(b.THA_DIA_PHUONG_TOA_QD_THA AS VARCHAR2(1000))), '') AS THA_DIA_PHUONG_TOA_QD_THA,
        NVL(TRIM(CAST(b.CO_QUAN_QD_THA AS VARCHAR2(1000))), '') AS TOA_QD_THA,
        TRIM(NVL(TRIM(CAST(b.TOA_XU_TEN AS VARCHAR2(500))), '')
            || NVL2(b.TOA_XU_DIA_PHUONG, ', ' || TRIM(CAST(b.TOA_XU_DIA_PHUONG AS VARCHAR2(500))), '')) AS TOA_XU,
        CASE
            WHEN b.SO_BAN_AN IS NOT NULL
            THEN u'B\1ea3n \00e1n s\1ed1 ' || TRIM(CAST(b.SO_BAN_AN AS NVARCHAR2(200)))
                || u' ng\00e0y ' || TO_CHAR(b.NGAY_BAN_AN, 'DD/MM/YYYY')
                || u' c\1ee7a To\00e0 \00e1n nh\00e2n d\00e2n ' || NVL(TRIM(CAST(b.THA_DIA_PHUONG_TOA_QD_THA AS NVARCHAR2(500))), u'')
            ELSE NULL
        END AS CAN_CU_BAN_AN,
        CASE
            WHEN b.SO_QD_THA IS NOT NULL
            THEN u'Quy\1ebft \0111\1ecbnh thi h\00e0nh \00e1n s\1ed1 ' || TRIM(CAST(b.SO_QD_THA AS NVARCHAR2(200)))
                || u' ng\00e0y ' || TO_CHAR(b.NGAY_QD_THA, 'DD/MM/YYYY')
                || u' c\1ee7a TAND ' || NVL(TRIM(CAST(b.THA_DIA_PHUONG_CO_QUAN_LAP AS NVARCHAR2(500))), u'')
            ELSE NULL
        END AS CAN_CU_QD_THA,
        NVL(TRIM(CAST(b.SO_QD_THA AS VARCHAR2(500))), '') AS SO_QD_THA,
        CASE WHEN b.NGAY_QD_THA IS NOT NULL THEN TO_CHAR(TRUNC(b.NGAY_QD_THA), 'DD/MM/YYYY') ELSE NULL END AS NGAY_QD_THA,
        CASE WHEN b.NGAY_DEN_TRAI IS NOT NULL THEN TO_CHAR(TRUNC(b.NGAY_DEN_TRAI), 'DD/MM/YYYY') ELSE NULL END AS NGAY_DEN_TRAI,
        CASE
            WHEN fn.so_lan_giam > 0
            THEN TRIM(CAST(fn.giam_an_hien_thi AS VARCHAR2(500)))
            ELSE NULL
        END AS DA_GIAM_FORMAT,
        NVL(CAST(fn.thoi_gian_da_chap_hanh AS VARCHAR2(500)), u'') AS THOI_GIAN_DA_CHAP_HANH,
        NVL(CAST(xla.XEP_LOAI AS VARCHAR2(4000)), u'') AS XEP_LOAI,
        NVL(CAST(kth.KHEN_THUONG AS VARCHAR2(4000)), u'') AS KHEN_THUONG,
        NVL(CAST(kl.KY_LUAT AS VARCHAR2(4000)), u'') AS KY_LUAT,
        NVL(CAST(ptm.PHAM_TOI_MOI AS VARCHAR2(4000)), u'') AS PHAM_TOI_MOI,
        NVL(
            NULLIF(TRIM(CAST(fn.hpbs_hien_thi AS VARCHAR2(4000))), ''),
            CAST(u'Kh\00f4ng' AS VARCHAR2(50))
        ) AS HPBS_HIEN_THI,
        NVL(
            NULLIF(TRIM(CAST(fn.hpbs_khac AS VARCHAR2(4000))), ''),
            CAST(u'Kh\00f4ng' AS VARCHAR2(50))
        ) AS HPBS_KHAC,
        NVL(fn.hpbs_pt, '') AS HPBS_PT,
        TO_CHAR(TRUNC(b.NGAY_HET_AN), 'DD/MM/YYYY') AS NGAY_HET_HAN,
        CASE WHEN b.KTRT_NGAY_THA IS NOT NULL THEN TO_CHAR(TRUNC(b.KTRT_NGAY_THA), 'DD/MM/YYYY') ELSE NULL END AS NGAY_RA_TRAI,
        CASE WHEN b.KTRT_NGAY_TRINH_DIEN IS NOT NULL THEN TO_CHAR(TRUNC(b.KTRT_NGAY_TRINH_DIEN), 'DD/MM/YYYY') ELSE NULL END AS NGAY_TRINH_DIEN,
        NVL(TRIM(CAST(dmttpn.TTPN_TEN AS VARCHAR2(500))), '') AS TINH_TRANG,
        NVL(TRIM(CAST(b.PHAN_DOI AS VARCHAR2(500))), '') AS PHAN_DOI,
        NVL(TRIM(CAST(b.PHAN_TRAI AS VARCHAR2(500))), '') AS PHAN_TRAI,
        TO_CHAR(ADD_MONTHS(TRUNC(b.NGAY_HET_AN), -2), 'DD/MM/YYYY') AS NGAY_XUAT,
        NVL(CAST(fn.thoi_gian_da_chap_hanh_truoc_2_thang AS VARCHAR2(500)), u'') AS THOI_GIAN_DA_CHAP_HANH_2_THANG
    FROM base b
    LEFT JOIN scalar_fns fn
        ON fn.PHAM_NHAN_ID = b.PHAM_NHAN_ID
    LEFT JOIN xep_loai_agg xla
        ON xla.PHAM_NHAN_ID = b.PHAM_NHAN_ID
    LEFT JOIN nguoi_giam_ho_one gh
        ON gh.PHAM_NHAN_ID = b.PHAM_NHAN_ID
    LEFT JOIN khen_thuong_agg kth
        ON kth.PHAM_NHAN_ID = b.PHAM_NHAN_ID
    LEFT JOIN ky_luat_agg kl
        ON kl.PHAM_NHAN_ID = b.PHAM_NHAN_ID
    LEFT JOIN pham_toi_moi_agg ptm
        ON ptm.PHAM_NHAN_ID = b.PHAM_NHAN_ID
    LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS dmttpn
        ON b.LL_TINH_TRANG_ID = dmttpn.ID
       AND NVL(dmttpn.IS_DELETED, 0) = 0
    ORDER BY b.NGAY_HET_AN, b.HO_TEN_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_RA_TRAI_THONG_BAO_NGAY_CHXAPT: ' || SQLERRM);
END SP_GET_RA_TRAI_THONG_BAO_NGAY_CHXAPT;


-- N?p QLPN.GTT_PN_IDS trên cùng session, r?i g?i không tham s?:
-- BEGIN QLPN.SP_GET_RA_TRAI_THONG_BAO_NGAY_CHXAPT; END;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_RA_TRAI_THONG_BAO_NGAY_CHXAPT_FULL_FILTER
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_RA_TRAI_THONG_BAO_NGAY_CHXAPT_FULL_FILTER" (
    p_trai_giam_id       IN  NUMBER      DEFAULT NULL,
    p_ra_tu_ngay         IN  DATE        DEFAULT NULL,
    p_ra_den_ngay        IN  DATE        DEFAULT NULL,
    p_tinh_trang_id      IN  NUMBER      DEFAULT NULL,
    p_doi_tuong          IN  NUMBER      DEFAULT NULL,
    p_phan_doi_id        IN  NUMBER      DEFAULT NULL,
    p_truong_hop_tha_id  IN  NUMBER      DEFAULT NULL,
    p_quoc_tich_id       IN  NUMBER      DEFAULT NULL,
    p_cadp_ve_tinh_id    IN  NUMBER      DEFAULT NULL,
    p_so_cong_van_tu     IN  VARCHAR2    DEFAULT NULL,
    p_tim_kiem           IN  NVARCHAR2   DEFAULT NULL,
    p_maxresultcount     IN  NUMBER      DEFAULT 0,
    p_skipcount          IN  NUMBER      DEFAULT 0
) AS
    v_skip   NUMBER;
    v_limit  NUMBER;
    v_tk_like VARCHAR2(4000);
    c1       SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    IF p_tim_kiem IS NOT NULL AND LENGTH(TRIM(p_tim_kiem)) > 0 THEN
        v_tk_like := '%' || UPPER(TRIM(p_tim_kiem)) || '%';
    ELSE
        v_tk_like := NULL;
    END IF;

    OPEN c1 FOR
    WITH
    tsht AS (
        SELECT
            MAX(CASE WHEN tsht.tsht_tham_so = 'CHUC_VU_KY' THEN TRIM(CAST(tsht.tsht_gia_tri AS VARCHAR2(500))) END) AS chuc_vu_ky,
            MAX(CASE WHEN tsht.tsht_tham_so = 'DIA_DANH_BC' THEN TRIM(CAST(tsht.tsht_gia_tri AS VARCHAR2(500))) END) AS dia_danh_bc,
            MAX(CASE WHEN tsht.tsht_tham_so = 'CO_QUAN_CHU_QUAN' THEN TRIM(CAST(tsht.tsht_gia_tri AS VARCHAR2(500))) END) AS co_quan_chu_quan,
            MAX(CASE WHEN tsht.tsht_tham_so = 'HO_TEN_NGUOI_KY' THEN TRIM(CAST(tsht.tsht_gia_tri AS VARCHAR2(500))) END) AS ho_ten_nguoi_ky,
            MAX(CASE WHEN tsht.tsht_tham_so = 'CAN_CU_TT_THI_HANH_AN' THEN TRIM(CAST(tsht.tsht_gia_tri AS VARCHAR2(4000))) END) AS can_cu_tt_thi_hanh_an
        FROM QLPN.THAM_SO_HE_THONGS tsht
        WHERE NVL(tsht.IS_DELETED, 0) = 0
          AND tsht.tsht_tham_so IN (
              'CHUC_VU_KY', 'DIA_DANH_BC', 'CO_QUAN_CHU_QUAN', 'HO_TEN_NGUOI_KY', 'CAN_CU_TT_THI_HANH_AN'
          )
    ),
    THA_raw AS (
        SELECT
            THA.THA_PNLAI_LICH_ID,
            THA.THA_SO_BAN_AN,
            THA.THA_NGAY_BAN_AN,
            THA.THA_SO_QD_THA,
            THA.THA_NGAY_QD_THA,
            DV_TOA.TTP_TEN AS THA_DIA_PHUONG_TOA_QD_THA,
            DV_LAP.TTP_TEN AS THA_DIA_PHUONG_CO_QUAN_LAP,
            ROW_NUMBER() OVER (
                PARTITION BY THA.THA_PNLAI_LICH_ID
                ORDER BY NVL(THA.THA_NGAY_HET_HAN, THA.THA_NGAY_BAT) DESC NULLS LAST,
                         NVL(THA.THA_NGAY_DEN_TRAI, THA.THA_NGAY_BAT) DESC NULLS LAST,
                         THA.ID DESC
            ) AS rn
        FROM QLPN.PN_THI_HANH_AN THA
        LEFT JOIN QLPN.DM_TINH_THANH_PHO DV_TOA
            ON THA.THA_DIA_PHUONG_TOA_QD_THA_ID = DV_TOA.ID

        LEFT JOIN QLPN.DM_TINH_THANH_PHO DV_LAP
            ON THA.THA_DIA_PHUONG_DON_CO_QUAN_LAP_ID = DV_LAP.ID

        WHERE NVL(THA.IS_DELETED, 0) = 0
    ),
    THA AS (SELECT * FROM THA_raw WHERE rn = 1),
    KT_in_range AS (
        SELECT k.*
        FROM (
            SELECT k0.*,
                   ROW_NUMBER() OVER (
                       PARTITION BY k0.KTRT_PN_LAI_LICH_ID
                       ORDER BY NVL(k0.KTRT_NGAY_THA, k0.CREATION_TIME) DESC NULLS LAST
                   ) AS rn
            FROM QLPN.PN_KET_THUC_RA_TRAIS k0
            WHERE NVL(k0.IS_DELETED, 0) = 0
              AND (p_ra_tu_ngay IS NULL OR TRUNC(k0.KTRT_NGAY_THA) >= TRUNC(p_ra_tu_ngay))
              AND (p_ra_den_ngay IS NULL OR TRUNC(k0.KTRT_NGAY_THA) <= TRUNC(p_ra_den_ngay))
        ) k
        WHERE k.rn = 1
    ),
    ds_inner AS (
        SELECT
            t.KTRT_NGAY_THA,
            t.KTRT_NGAY_TRINH_DIEN,
            t.KTRT_SO_GCN,
            t.KTRT_TRUONG_HOP_THA_ID,
            v.PHAM_NHAN_ID,
            v.HO_TEN,
            v.CCCD,
            v.GIOI_TINH,
            v.NGAY_SINH,
            v.NAM_SINH,
            v.TEN_KHAC,
            v.NGUYEN_QUAN,
            v.DAN_TOC,
            v.QUOC_TICH,
            v.NOI_THUONG_TRU_DAY_DU,
            v.DIA_CHI_THUONG_TRU,
            v.NOI_THA_VE_CU_TRU,
            v.NOI_THA_VE_CU_TRU_XA,
            v.NOI_THA_VE_CU_TRU_TINH,
            v.TOI_DANH,
            v.TOI_DANH_ID,
            v.AN_PHAT,
            v.NGAY_HET_AN,
            v.NGAY_BAT_AN_PHAT,
            v.SO_BAN_AN,
            v.NGAY_BAN_AN,
            v.TOA_XU_TEN,
            v.TOA_XU_DIA_PHUONG,
            v.SO_QD_THA,
            v.NGAY_QD_THA,
            v.CO_QUAN_QD_THA,
            v.LL_TINH_TRANG_ID,
            v.PHAN_DOI,
            v.PHAN_TRAI,
            v.QUOC_TICH_ID,
            v.NOI_THA_VE_CU_TRU_TINH_ID,
            v.SO_HO_SO,
            v.TRAI_GIAM,
            v.TRAI_GIAM_ID,
            REPLACE(REPLACE(TRIM(CAST(COALESCE(v.TOI_DANH_ID, v.TOI_DANH) AS VARCHAR2(4000))), '[', ''), ']', '') AS toi_csv
        FROM KT_in_range t
        INNER JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = t.KTRT_PN_LAI_LICH_ID
           AND NVL(v.IS_DELETED, 0) = 0
        WHERE (p_trai_giam_id IS NULL OR v.TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)
          AND (p_tinh_trang_id IS NULL OR v.LL_TINH_TRANG_ID = p_tinh_trang_id)
          AND (p_truong_hop_tha_id IS NULL OR t.KTRT_TRUONG_HOP_THA_ID = p_truong_hop_tha_id)
          AND (p_quoc_tich_id IS NULL OR v.QUOC_TICH_ID = p_quoc_tich_id)
          AND (p_cadp_ve_tinh_id IS NULL OR v.NOI_THA_VE_CU_TRU_TINH_ID = p_cadp_ve_tinh_id)
          AND (
              p_so_cong_van_tu IS NULL
              OR TRIM(p_so_cong_van_tu) = ''
              OR UPPER(NVL(TRIM(t.KTRT_SO_GCN), '')) LIKE UPPER(TRIM(p_so_cong_van_tu)) || '%'
          )
          AND (
              v_tk_like IS NULL
              OR UPPER(NVL(v.HO_TEN, '')) LIKE v_tk_like
              OR UPPER(NVL(v.CCCD, '')) LIKE v_tk_like
              OR UPPER(NVL(TO_CHAR(v.SO_HO_SO), '')) LIKE v_tk_like
          )
    ),
    ds AS (
        SELECT
            di.*,
            dm.TD_CHUONG AS td_chuong
        FROM ds_inner di
        LEFT JOIN QLPN.DM_TOI_DANHS dm
            ON dm.ID = CASE
                WHEN REGEXP_LIKE(REGEXP_SUBSTR(di.toi_csv, '[0-9]+', 1, 1), '^[0-9]+$')
                THEN TO_NUMBER(REGEXP_SUBSTR(di.toi_csv, '[0-9]+', 1, 1))
            END
           AND NVL(dm.IS_DELETED, 0) = 0
        WHERE (p_doi_tuong IS NULL
               OR (p_doi_tuong = 1 AND TRIM(TO_CHAR(dm.TD_CHUONG)) = '13')
               OR (p_doi_tuong = 2 AND (dm.TD_CHUONG IS NULL OR TRIM(TO_CHAR(dm.TD_CHUONG)) <> '13')))
    ),
    toi_ten_agg AS (
        SELECT ids.pham_nhan_id,
               LISTAGG(NVL(TRIM(CAST(dm.TD_TEN AS VARCHAR2(4000))), TO_CHAR(ids.td_id)), ', ')
                   WITHIN GROUP (ORDER BY ids.ord) AS toi_danh_ten
        FROM (
            SELECT z.pham_nhan_id,
                   CASE
                       WHEN REGEXP_LIKE(TRIM(REGEXP_SUBSTR(z.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
                       THEN TO_NUMBER(TRIM(REGEXP_SUBSTR(z.csv, '[^,]+', 1, LEVEL)))
                   END AS td_id,
                   LEVEL AS ord
            FROM (
                SELECT pham_nhan_id,
                       toi_csv AS csv
                FROM ds
            ) z
            WHERE TRIM(z.csv) IS NOT NULL
            CONNECT BY LEVEL <= REGEXP_COUNT(z.csv, ',') + 1
              AND PRIOR z.pham_nhan_id = z.pham_nhan_id
              AND PRIOR SYS_GUID() IS NOT NULL
              AND REGEXP_SUBSTR(z.csv, '[^,]+', 1, LEVEL) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(z.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
        ) ids
        LEFT JOIN QLPN.DM_TOI_DANHS dm
            ON dm.ID = ids.td_id
           AND NVL(dm.IS_DELETED, 0) = 0
        WHERE ids.td_id IS NOT NULL
        GROUP BY ids.pham_nhan_id
    )
    SELECT
        d.PHAM_NHAN_ID,
        NVL(TRIM(CAST(ts.co_quan_chu_quan AS VARCHAR2(500))), '') AS CO_QUAN_CHU_QUAN,
        NVL(TRIM(CAST(d.TRAI_GIAM AS VARCHAR2(500))), '') AS TEN_TRAI_GIAM,
        NVL(TRIM(CAST(ts.chuc_vu_ky AS VARCHAR2(500))), '') AS TSHT_CHUC_VU_KY,
        NVL(TRIM(CAST(ts.ho_ten_nguoi_ky AS VARCHAR2(500))), '') AS TSHT_HO_TEN_NGUOI_KY,
        NVL(TRIM(CAST(ts.dia_danh_bc AS VARCHAR2(500))), '') AS TSHT_DIA_DANH_BC,
        NVL(TRIM(CAST(ts.can_cu_tt_thi_hanh_an AS VARCHAR2(4000))), '') AS TSHT_CAN_CU_TT_THI_HANH_AN,
        NVL(TRIM(CAST(d.KTRT_SO_GCN AS VARCHAR2(500))), '') AS SO_CONG_VAN,
        UPPER(NVL(TRIM(CAST(d.HO_TEN AS VARCHAR2(500))), '')) AS HO_TEN_HOA,
        NVL(TRIM(CAST(d.HO_TEN AS VARCHAR2(500))), '') AS HO_TEN,
        NVL(TRIM(CAST(d.CCCD AS VARCHAR2(100))), '') AS CCCD,
        NVL(TRIM(CAST(d.GIOI_TINH AS VARCHAR2(100))), '') AS GIOI_TINH,
        CASE
            WHEN d.NGAY_SINH IS NOT NULL
                 AND REGEXP_LIKE(TRIM(CAST(d.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(CAST(d.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN d.NAM_SINH IS NOT NULL AND d.NAM_SINH > 0 THEN TO_CHAR(d.NAM_SINH)
            WHEN d.NGAY_SINH IS NOT NULL THEN TRIM(CAST(d.NGAY_SINH AS VARCHAR2(400)))
            ELSE NULL
        END AS NGAY_SINH,
        NVL(TRIM(CAST(d.TEN_KHAC AS VARCHAR2(500))), '') AS TEN_KHAC,
        NVL(TRIM(CAST(d.NGUYEN_QUAN AS VARCHAR2(4000))), '') AS NGUYEN_QUAN,
        NVL(TRIM(CAST(d.DAN_TOC AS VARCHAR2(200))), '') AS DAN_TOC,
        NVL(TRIM(CAST(d.QUOC_TICH AS VARCHAR2(200))), '') AS QUOC_TICH,
        NVL(TRIM(CAST(NVL(d.NOI_THUONG_TRU_DAY_DU, d.DIA_CHI_THUONG_TRU) AS VARCHAR2(4000))), '') AS NOI_DKTT,
        NVL(TRIM(CAST(d.NOI_THA_VE_CU_TRU AS VARCHAR2(4000))), '') AS DIA_CHI_VE_CU_TRU,
        u'UBND ' || NVL(TRIM(CAST(d.NOI_THA_VE_CU_TRU_XA AS NVARCHAR2(500))), u'')
            || u', ' || NVL(TRIM(CAST(d.NOI_THA_VE_CU_TRU_TINH AS NVARCHAR2(500))), u'') AS KINH_GUI_UBND,
        u'C\00f4ng an ' || NVL(TRIM(CAST(d.NOI_THA_VE_CU_TRU_TINH AS NVARCHAR2(500))), u'') AS KINH_GUI_CONG_AN,
        u'Trung t\00e2m Y t\1ebf d\1ef1 ph\00f2ng ' || NVL(TRIM(CAST(d.NOI_THA_VE_CU_TRU_TINH AS NVARCHAR2(500))), u'') AS KINH_GUI_Y_TE_DP,
        COALESCE(
            NULLIF(TRIM(tt.toi_danh_ten), ''),
            NULLIF(TRIM(CAST(d.TOI_DANH AS VARCHAR2(4000))), ''),
            CAST(u'Ch\01b0a x\00e1c \0111\1ecbnh' AS VARCHAR2(200))
        ) AS TOI_DANH,
        TO_CHAR(TRUNC(d.NGAY_BAT_AN_PHAT), 'DD/MM/YYYY') AS NGAY_BAT,
        NVL(TRIM(CAST(d.AN_PHAT AS VARCHAR2(4000))), '') AS AN_PHAT,
        NVL(TRIM(CAST(d.SO_BAN_AN AS VARCHAR2(500))), '') AS SO_BAN_AN,
        TO_CHAR(TRUNC(d.NGAY_BAN_AN), 'DD/MM/YYYY') AS NGAY_BAN_AN,
        TRIM(NVL(TRIM(CAST(d.TOA_XU_TEN AS VARCHAR2(500))), '')
            || NVL2(d.TOA_XU_DIA_PHUONG, ', ' || TRIM(CAST(d.TOA_XU_DIA_PHUONG AS VARCHAR2(500))), '')) AS TOA_XU,
        CASE
            WHEN th.THA_PNLAI_LICH_ID IS NOT NULL AND th.THA_SO_BAN_AN IS NOT NULL
            THEN u'B\1ea3n \00e1n s\1ed1 ' || TRIM(CAST(th.THA_SO_BAN_AN AS NVARCHAR2(200)))
                || u' ng\00e0y ' || TO_CHAR(th.THA_NGAY_BAN_AN, 'DD/MM/YYYY')
                || u' c\1ee7a To\00e0 \00e1n nh\00e2n d\00e2n ' || NVL(TRIM(CAST(th.THA_DIA_PHUONG_TOA_QD_THA AS NVARCHAR2(500))), u'')
            ELSE NULL
        END AS CAN_CU_BAN_AN,
        CASE
            WHEN th.THA_PNLAI_LICH_ID IS NOT NULL AND th.THA_SO_QD_THA IS NOT NULL
            THEN u'Quy\1ebft \0111\1ecbnh thi h\00e0nh \00e1n s\1ed1 ' || TRIM(CAST(th.THA_SO_QD_THA AS NVARCHAR2(200)))
                || u' ng\00e0y ' || TO_CHAR(th.THA_NGAY_QD_THA, 'DD/MM/YYYY')
                || u' c\1ee7a TAND ' || NVL(TRIM(CAST(th.THA_DIA_PHUONG_CO_QUAN_LAP AS NVARCHAR2(500))), u'')
            ELSE NULL
        END AS CAN_CU_QD_THA,
        CASE
            WHEN QLPN.PKG_TINH_AN.FN_TINH_SO_LAN_GIAM_AN(d.PHAM_NHAN_ID) > 0
            THEN TRIM(CAST(QLPN.PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(d.PHAM_NHAN_ID) AS VARCHAR2(500)))
            ELSE NULL
        END AS DA_GIAM_FORMAT,
        NVL(
            NULLIF(TRIM(CAST(QLPN.FN_GET_LIET_KE_HPBS(d.PHAM_NHAN_ID) AS VARCHAR2(4000))), ''),
            CAST(u'Kh\00f4ng' AS VARCHAR2(50))
        ) AS HPBS_HIEN_THI,
        TO_CHAR(TRUNC(d.NGAY_HET_AN), 'DD/MM/YYYY') AS NGAY_HET_HAN,
        TO_CHAR(TRUNC(d.KTRT_NGAY_THA), 'DD/MM/YYYY') AS NGAY_RA_TRAI,
        TO_CHAR(TRUNC(d.KTRT_NGAY_TRINH_DIEN), 'DD/MM/YYYY') AS NGAY_TRINH_DIEN,
        NVL(TRIM(CAST(dmttpn.TTPN_TEN AS VARCHAR2(500))), '') AS TINH_TRANG,
        NVL(TRIM(CAST(d.PHAN_DOI AS VARCHAR2(500))), '') AS PHAN_DOI,
        NVL(TRIM(CAST(d.PHAN_TRAI AS VARCHAR2(500))), '') AS PHAN_TRAI
    FROM ds d
    LEFT JOIN toi_ten_agg tt
        ON tt.pham_nhan_id = d.PHAM_NHAN_ID
    LEFT JOIN THA th
        ON th.THA_PNLAI_LICH_ID = d.PHAM_NHAN_ID
    LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS dmttpn
        ON d.LL_TINH_TRANG_ID = dmttpn.ID
       AND NVL(dmttpn.IS_DELETED, 0) = 0
    CROSS JOIN tsht ts
    ORDER BY d.HO_TEN NULLS LAST, d.PHAM_NHAN_ID
    OFFSET v_skip ROWS
    FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_RA_TRAI_THONG_BAO_NGAY_CHXAPT: ' || SQLERRM);
END ;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TABLE_COLUMNS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TABLE_COLUMNS" (
    p_TABLE_NAME IN VARCHAR2,
    p_CURSOR OUT SYS_REFCURSOR
) AS
BEGIN
    OPEN p_CURSOR FOR
    SELECT 
        ROWNUM AS STT,
        a.COLUMN_NAME AS MA_TRUONG,
        a.DATA_TYPE || 
        CASE 
            WHEN a.DATA_TYPE = 'NUMBER' AND a.DATA_PRECISION IS NOT NULL THEN 
                '(' || a.DATA_PRECISION || CASE WHEN a.DATA_SCALE > 0 THEN ',' || a.DATA_SCALE ELSE '' END || ')'
            WHEN a.DATA_TYPE IN ('VARCHAR2', 'NVARCHAR2', 'CHAR', 'NCHAR') THEN 
                '(' || a.DATA_LENGTH || ')'
            WHEN a.DATA_TYPE = 'TIMESTAMP' THEN 
                '(' || a.DATA_SCALE || ')'
            ELSE ''
        END AS KIEU_DU_LIEU,
        CASE WHEN a.NULLABLE = 'Y' THEN 'Y' ELSE 'N' END AS NULLABLE,
        NVL(b.COMMENTS, '') AS MO_TA_TRUONG
    FROM ALL_TAB_COLUMNS a
    LEFT JOIN ALL_COL_COMMENTS b 
        ON a.OWNER = b.OWNER 
        AND a.TABLE_NAME = b.TABLE_NAME 
        AND a.COLUMN_NAME = b.COLUMN_NAME
    WHERE a.OWNER = 'QLPN' 
      AND a.TABLE_NAME = p_TABLE_NAME
    ORDER BY a.COLUMN_ID;
END;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TABLE_RELATIONSHIPS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TABLE_RELATIONSHIPS" (
    p_TABLE_NAME IN VARCHAR2 DEFAULT NULL,
    p_CURSOR OUT SYS_REFCURSOR
) AS
BEGIN
    OPEN p_CURSOR FOR
    SELECT 
        a.TABLE_NAME AS BANG_CHA,
        LISTAGG(b.COLUMN_NAME, ', ') WITHIN GROUP (ORDER BY b.POSITION) AS COT_CHA,
        a.CONSTRAINT_NAME AS TEN_RANG_BUOC,
        c.TABLE_NAME AS BANG_CON,
        LISTAGG(d.COLUMN_NAME, ', ') WITHIN GROUP (ORDER BY d.POSITION) AS COT_CON
    FROM ALL_CONSTRAINTS a
    JOIN ALL_CONS_COLUMNS b 
        ON a.OWNER = b.OWNER 
        AND a.CONSTRAINT_NAME = b.CONSTRAINT_NAME
    JOIN ALL_CONSTRAINTS c 
        ON a.R_OWNER = c.OWNER 
        AND a.R_CONSTRAINT_NAME = c.CONSTRAINT_NAME
    JOIN ALL_CONS_COLUMNS d 
        ON c.OWNER = d.OWNER 
        AND c.CONSTRAINT_NAME = d.CONSTRAINT_NAME
    WHERE a.OWNER = 'QLPN'
      AND a.CONSTRAINT_TYPE = 'R'
      AND (p_TABLE_NAME IS NULL OR a.TABLE_NAME = p_TABLE_NAME)
    GROUP BY a.TABLE_NAME, a.CONSTRAINT_NAME, c.TABLE_NAME
    ORDER BY a.TABLE_NAME, a.CONSTRAINT_NAME;
END;








