    JOIN DM_CO_QUANS dcq ON tghp.DON_VI_QUYET_DINH_ID = dcq.ID
    JOIN DM_LOAI_TANG_GIAM_HINH_PHATS d ON tghp.LOAI_TANG_GIAM_ID = d.ID
    WHERE tghp.PHAM_NHAN_ID = p_PHAM_NHAN_ID
    AND tghp.IS_DELETED = 0;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_TANG_GIAM_HINH_PHAT;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TB_RA_TRAI_CAI_TAO_KEM
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TB_RA_TRAI_CAI_TAO_KEM" (
    p_pham_nhan_id   IN  NUMBER
) AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    SELECT
			pktrt.KTRT_PN_LAI_LICH_ID,
			vpllct.TRAI_GIAM_ID,
			vpllct.TRAI_GIAM ,
			NULL AS THONG_TU_SO, 
			NULL AS NGAY_SUU_TRA,
			vpllct.HO_TEN,
			vpllct.GIOI_TINH ,
			vpllct.NAM_SINH ,
			vpllct.NGUYEN_QUAN ,
			vpllct.NOI_THUONG_TRU_DAY_DU ,
			vpllct.DAN_TOC ,
			vpllct.QUOC_TICH ,
			vpllct.TOI_DANH ,
			vpllct.NGAY_BAT_AN_PHAT AS NGAY_BAT,
			vpllct.AN_PHAT ,
			FN_GET_DA_CHAP_HANH(vpllct.PHAM_NHAN_ID) AS THOI_GIAN_DA_CHAP_HANH,
			NULL AS THOI_GIAN_DA_GIAM,
			vpllct.NOI_THA_VE_CU_TRU,
			vpllct.PHAN_DOI ,
			vpllct.PHAN_TRAI,
		 	vpllct.NGAY_DEN_TRAI,
		 	vpllct.NGAY_HET_AN,
		 	pktrt.KTRT_MUC_CAN_CU_THONG_TU_ID ,
		 	pktrt.KTRT_THOI_GIAN_CAI_TAO_KEM ,
		 	pktrt.KTRT_NHAN_XET_CAI_TAO_KEM ,
		 	 pktrt.KTRT_KET_QUA_CAI_TAO_KEM
FROM VW_PN_LAI_LICH_CHI_TIET vpllct
JOIN PN_KET_THUC_RA_TRAIS pktrt ON pktrt.KTRT_PN_LAI_LICH_ID = vpllct.PHAM_NHAN_ID AND pktrt.KTRT_KET_QUA_CAI_TAO_KEM IS NOT NULL
WHERE pktrt.IS_DELETED = 0 AND vpllct.IS_DELETED = 0
AND pktrt.KTRT_PN_LAI_LICH_ID = p_pham_nhan_id
;
    DBMS_SQL.RETURN_RESULT(C1);

    -- EXEC SP_GET_TB_RA_TRAI_CAI_TAO_KEM(179);
END SP_GET_TB_RA_TRAI_CAI_TAO_KEM;




/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TB_THI_HANH_AN_DAN_SU_DEN_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TB_THI_HANH_AN_DAN_SU_DEN_TRAI" (
	p_trai_giam_id IN NVARCHAR2 DEFAULT NULL,
    p_quyet_dinh_dieu_chuyen IN NVARCHAR2 DEFAULT NULL,
    p_dia_phuong_qd_tha IN NVARCHAR2 DEFAULT NULL,
    p_tim_kiem IN NVARCHAR2 DEFAULT NULL,
	p_tu_ngay IN NVARCHAR2 DEFAULT NULL,
    p_den_ngay IN NVARCHAR2 DEFAULT NULL
)
AS
    v_tu_ngay NVARCHAR2(10);
    v_den_ngay NVARCHAR2(10);
    C1 SYS_REFCURSOR;  
BEGIN 
     IF p_tu_ngay IS NULL OR p_tu_ngay = '' THEN
        v_tu_ngay := to_char(sysdate - 1, 'DD/MM/YYYY');
        ELSE v_tu_ngay := p_tu_ngay;
    END IF;

    IF p_den_ngay IS NULL OR p_den_ngay = '' THEN
        v_den_ngay := to_char(sysdate - 1, 'DD/MM/YYYY');
        ELSE v_den_ngay := p_den_ngay;
    END IF;

      OPEN C1 FOR
        WITH hpbs_tien_phat AS (
			    SELECT 
			        p.HPBS_MA_PHAM_NHAN,
			        SUM(COALESCE(p.HPBS_TONG_TIEN_PHAT, 0)) AS TONG_TIEN_PHAT
			    FROM PN_HINH_PHAT_BO_SUNGS p
			    WHERE p.IS_DELETED = 0
			      AND p.HPBS_TONG_TIEN_PHAT IS NOT NULL
			    GROUP BY p.HPBS_MA_PHAM_NHAN
			    HAVING SUM(COALESCE(p.HPBS_TONG_TIEN_PHAT, 0)) > 0
			),
			hpbs AS (
			    SELECT 
			        s.HPBS_MA_PHAM_NHAN,
			        s.TONG_TIEN_PHAT,
				    FN_GET_LIET_KE_HPBS_CHI_TIET (s.HPBS_MA_PHAM_NHAN) AS HINH_PHAT_BO_SUNG
			    FROM hpbs_tien_phat s
			)
				SELECT
						vpllct.PHAM_NHAN_ID,
						vpllct.TRAI_GIAM_ID,
						vpllct.TRAI_GIAM ,
						vpllct.CO_QUAN_QD_THA,
						vpllct.TOA_QD_THA_DIA_PHUONG,
						vpllct.HO_TEN,
						vpllct.GIOI_TINH ,
						vpllct.NAM_SINH ,
						vpllct.NOI_THUONG_TRU_DAY_DU ,
						vpllct.TOI_DANH ,
						vpllct.NGAY_BAT_AN_PHAT AS NGAY_BAT,
						vpllct.AN_PHAT ,
						vpllct.SO_BAN_AN ,
						vpllct.NGAY_BAN_AN ,
						vpllct.TOA_XU_TEN,
						vpllct.TOA_XU_DIA_PHUONG,
						hpbs.HINH_PHAT_BO_SUNG,
						vpllct.NGAY_DEN_TRAI ,
						NULL AS TRAI_GIAM_DIA_PHUONG
			FROM
				VW_PN_LAI_LICH_CHI_TIET vpllct
			INNER JOIN hpbs ON hpbs.HPBS_MA_PHAM_NHAN = vpllct.PHAM_NHAN_ID
			WHERE vpllct.IS_DELETED = 0
        	AND (p_trai_giam_id IS NULL OR vpllct.TRAI_GIAM_ID = p_trai_giam_id)
        	AND (p_quyet_dinh_dieu_chuyen IS NULL OR vpllct.SO_QD_DIEU_CHUYEN = p_quyet_dinh_dieu_chuyen)
			AND (p_dia_phuong_qd_tha IS NULL)
            AND (p_tim_kiem IS NULL OR vpllct.HO_TEN LIKE '%' || p_tim_kiem || '%') 
        	AND (vpllct.NGAY_DEN_TRAI BETWEEN TO_TIMESTAMP(v_tu_ngay, 'DD/MM/YYYY') AND  TO_TIMESTAMP(v_den_ngay, 'DD/MM/YYYY'))
        ORDER BY PHAM_NHAN_ID ;

      DBMS_SQL.RETURN_RESULT(C1);
       -- EXEC SP_GET_TT_THI_HANH_AN_DAN_SU ('1', 'Q?', NULL, 'Hòa', '2011-10-11','2011-12-11');

END SP_GET_TB_THI_HANH_AN_DAN_SU_DEN_TRAI;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TB_THI_HANH_AN_DAN_SU_RA_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TB_THI_HANH_AN_DAN_SU_RA_TRAI" (
    p_trai_giam_id IN NVARCHAR2 DEFAULT NULL,
