    p_doi_tuong IN NVARCHAR2 DEFAULT NULL,
    p_tinh_trang IN NVARCHAR2 DEFAULT NULL,
    p_truong_hop_tha IN NVARCHAR2 DEFAULT NULL,
    p_so_thong_bao IN NVARCHAR2 DEFAULT NULL,
    p_tim_kiem IN NVARCHAR2 DEFAULT NULL,
    p_tu_ngay IN NVARCHAR2 DEFAULT NULL,
    p_den_ngay IN NVARCHAR2 DEFAULT NULL
)
AS
    v_tu_ngay NVARCHAR2(10);
    v_den_ngay NVARCHAR2(10);
    C1 SYS_REFCURSOR;  
BEGIN 
     IF p_tu_ngay IS NULL OR p_tu_ngay = '' THEN
        v_tu_ngay := to_char(sysdate - 1, 'DD/MM/YYYY');
        ELSE v_tu_ngay := p_tu_ngay;
    END IF;

    IF p_den_ngay IS NULL OR p_den_ngay = '' THEN
        v_den_ngay := to_char(sysdate - 1, 'DD/MM/YYYY');
        ELSE v_den_ngay := p_den_ngay;
    END IF;

      OPEN C1 FOR
 		WITH hpbs_tien_phat AS (
			    SELECT 
			        p.HPBS_MA_PHAM_NHAN,
			        SUM(COALESCE(p.HPBS_TONG_TIEN_PHAT, 0)) AS TONG_TIEN_PHAT
			    FROM PN_HINH_PHAT_BO_SUNGS p
			    WHERE p.IS_DELETED = 0
			      AND p.HPBS_TONG_TIEN_PHAT IS NOT NULL
			    GROUP BY p.HPBS_MA_PHAM_NHAN
			    HAVING SUM(COALESCE(p.HPBS_TONG_TIEN_PHAT, 0)) > 0
			),
			hpbs AS (
			    SELECT 
			        s.HPBS_MA_PHAM_NHAN,
			        s.TONG_TIEN_PHAT,
				    FN_GET_LIET_KE_HPBS_CHI_TIET (s.HPBS_MA_PHAM_NHAN) AS NGHIA_VU_DAN_SU
			    FROM hpbs_tien_phat s
			)
		SELECT
			ktrt.KTRT_PN_LAI_LICH_ID,
			vpllct.TRAI_GIAM ,
			vpllct.SO_QD_THA,
			vpllct.NGAY_QD_THA,
			vpllct.CO_QUAN_QD_THA,
			vpllct.TOA_QD_THA_DIA_PHUONG,
			vpllct.HO_TEN,
			vpllct.GIOI_TINH ,
			vpllct.NAM_SINH ,
			vpllct.TEN_KHAC AS HO_TEN_KHAC,
			vpllct.NGUYEN_QUAN ,
			vpllct.NOI_THUONG_TRU_DAY_DU ,
			vpllct.DAN_TOC ,
			vpllct.QUOC_TICH ,
			vpllct.TOI_DANH ,
			vpllct.NGAY_BAT_AN_PHAT AS NGAY_BAT,
			vpllct.AN_PHAT ,
			vpllct.SO_BAN_AN ,
			vpllct.NGAY_BAN_AN ,
			vpllct.TOA_XU_TEN,
			vpllct.TOA_XU_DIA_PHUONG ,
			NULL AS THOI_GIAN_DA_GIAM,
			vpllct.PHAN_DOI ,
			vpllct.PHAN_TRAI ,
		 	vpllct.NGAY_HET_AN ,
		 	vpllct.NOI_THA_VE_CU_TRU ,
		 	NULL AS XEP_LOAI_CAI_TAO,
		 	hpbs.NGHIA_VU_DAN_SU,
		 	vpllct.NGAY_DEN_TRAI
		FROM VW_PN_LAI_LICH_CHI_TIET vpllct
		INNER JOIN hpbs ON hpbs.HPBS_MA_PHAM_NHAN = vpllct.PHAM_NHAN_ID
		INNER JOIN PN_KET_THUC_RA_TRAIS ktrt ON ktrt.KTRT_PN_LAI_LICH_ID = vpllct.PHAM_NHAN_ID
		WHERE vpllct.IS_DELETED = 0 AND ktrt.IS_DELETED = 0
        AND (p_trai_giam_id IS NULL OR vpllct.TRAI_GIAM_ID = p_trai_giam_id)
        AND (p_tim_kiem IS NULL OR vpllct.HO_TEN LIKE '%' || p_tim_kiem || '%') 
        AND (p_phan_doi IS NULL OR vpllct.PHAN_DOI_ID = p_phan_doi) 
	    AND (p_quoc_tich IS NULL OR vpllct.QUOC_TICH_ID = p_quoc_tich) 
	    AND (p_doi_tuong IS NULL OR vpllct.DOI_TUONG = p_doi_tuong) 
	    AND (p_tinh_trang IS NULL OR vpllct.LL_TINH_TRANG_ID = p_tinh_trang) 
	    AND (p_truong_hop_tha IS NULL OR ktrt.KTRT_TRUONG_HOP_THA_ID = p_truong_hop_tha) 
		AND (p_so_thong_bao IS NULL) 
        AND (vpllct.NGAY_HET_AN BETWEEN TO_TIMESTAMP(v_tu_ngay, 'DD/MM/YYYY') AND  TO_TIMESTAMP(v_den_ngay, 'DD/MM/YYYY'))
        ORDER BY vpllct.NGAY_HET_AN ;

      DBMS_SQL.RETURN_RESULT(C1);
      -- EXEC SP_GET_TT_THI_HANH_AN_DAN_SU('1', NULL, '87', '29', 'Hòa', '2011-10-11','2011-12-11');

END SP_GET_TB_THI_HANH_AN_DAN_SU_RA_TRAI;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THA_CDK_BAN_GIAO_PN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THA_CDK_BAN_GIAO_PN" (
    p_dot_tha_id           IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id          IN  NUMBER    DEFAULT NULL,
    p_doi_tuong            IN  NUMBER    DEFAULT NULL,
    p_dia_phuong_cu_tru_id IN  NUMBER    DEFAULT NULL,
    p_tim_kiem             IN  NVARCHAR2 DEFAULT NULL,
    p_ma_trai_giam IN VARCHAR2 DEFAULT NULL,
    p_maxresultcount       IN  NUMBER    DEFAULT 0,
    p_skipcount            IN  NUMBER    DEFAULT 0
) AS
    v_skip   NUMBER;
    v_limit  NUMBER;
    v_tk_like VARCHAR2(4000);
    c1       SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    IF p_tim_kiem IS NOT NULL AND LENGTH(TRIM(p_tim_kiem)) > 0 THEN
        v_tk_like := '%' || UPPER(TRIM(p_tim_kiem)) || '%';
    ELSE
        v_tk_like := NULL;
    END IF;
    OPEN c1 FOR
    WITH
    tha_one AS (
        SELECT t.ID AS tha_co_dieu_kien_id,
               dot.ID AS dot_tha_co_dieu_kien_id,
               t.PHAM_NHAN_ID,
               t.SO_QUYET_DINH_THA AS so_quyet_dinh_tha,
               t.NGAY_XET,
               t.NGAY_THA,
               t.NGAY_QUYET_DINH_THA,
               t.NGAY_TRINH_DIEN,
               t.TOA_QUYET_DINH_THA_ID,
               t.DIA_PHUONG_QUYET_DINH_THA_ID
        FROM QLPN.THA_CO_DIEU_KIENS t
        LEFT JOIN QLPN.PN_DOT_THA_CO_DIEU_KIENS dot
            ON TRUNC(t.NGAY_XET) = TRUNC(dot.DTCDK_NGAY_XET)
           AND NVL(dot.IS_DELETED, 0) = 0
        WHERE NVL(t.IS_DELETED, 0) = 0
          AND (p_dot_tha_id IS NULL OR dot.ID = p_dot_tha_id)
          AND (SO_QUYET_DINH_THA IS NOT NULL OR  NGAY_QUYET_DINH_THA IS NOT NULL)
    ),
    thha_loai AS (
        SELECT pham_nhan_id,
               tha_loai_ban_an_id
        FROM (
            SELECT tha.tha_pnlai_lich_id AS pham_nhan_id,
                   tha.tha_loai_ban_an_id,
                   ROW_NUMBER() OVER (
                       PARTITION BY tha.tha_pnlai_lich_id
                       ORDER BY NVL(tha.tha_ngay_bat_dau_o_tu, tha.tha_ngay_bat) DESC NULLS LAST, tha.ID DESC
                   ) AS rn
            FROM QLPN.PN_THI_HANH_AN tha
            WHERE NVL(tha.IS_DELETED, 0) = 0
              AND EXISTS (SELECT 1 FROM tha_one o WHERE o.PHAM_NHAN_ID = tha.tha_pnlai_lich_id)
        ) x
        WHERE x.rn = 1
    ),
    ds_inner AS (
        SELECT
            t.tha_co_dieu_kien_id,
            t.dot_tha_co_dieu_kien_id,
            t.PHAM_NHAN_ID,
            t.NGAY_XET,
            t.NGAY_THA,
            t.NGAY_QUYET_DINH_THA,
            t.NGAY_TRINH_DIEN,
            t.TOA_QUYET_DINH_THA_ID,
            t.DIA_PHUONG_QUYET_DINH_THA_ID,
            t.so_quyet_dinh_tha,
            v.HO_TEN,
            v.TEN_KHAC,
            v.NGUYEN_QUAN,
            v.NGAY_SINH,
            v.NAM_SINH,
            v.GIOI_TINH,
            v.DIA_CHI_THUONG_TRU,
            v.TINH_THANH_THUONG_TRU,
            v.PHUONG_XA_THUONG_TRU,
            v.NOI_THUONG_TRU_DAY_DU,
            v.SO_TIEN_AN,
            v.TOI_DANH,
            v.TOI_DANH_ID,
            v.NGAY_BAT_AN_PHAT,
            v.AN_PHAT,
            v.NGAY_HET_AN,
            v.PHAN_DOI_ID,
            v.PHAN_DOI,
            v.PHAN_TRAI,
            v.NOI_THA_VE_CU_TRU,
            v.NOI_THA_VE_CU_TRU_XA,
            v.NOI_THA_VE_CU_TRU_TINH,
            v.DAN_TOC,
            v.TON_GIAO,
            v.QUOC_TICH,
            v.SO_BAN_AN,
            v.NGAY_BAN_AN,
            v.TOA_XU_TEN,
            v.TOA_XU_DIA_PHUONG,
            v.TRAI_GIAM,
            v.NGAY_DEN_TRAI,
            v.THOI_GIAN_TAM_GIAM,
            v.THOI_GIAN_TAM_GIU,
            ll.LL_SO_HO_SO_LAN_DAU AS so_ho_so_lan_dau,
            v.CCCD,
            v.MUC_AN_ID,
            v.CO_QUAN_QD_THA,
            v.TOA_QD_THA_DIA_PHUONG,
            v_tha.THA_NGAY_LAP_DANH_BAN AS tha_ngay_lap_danh_ban,
            REPLACE(REPLACE(TRIM(CAST(COALESCE(v.TOI_DANH_ID, v.TOI_DANH) AS VARCHAR2(4000))), '[', ''), ']', '') AS toi_csv
        FROM tha_one t
        INNER JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = t.PHAM_NHAN_ID
           AND NVL(v.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.V_PN_THI_HANH_AN_TOI_DANH v_tha
            ON v_tha.THA_PNLAI_LICH_ID = t.PHAM_NHAN_ID
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.ID = t.PHAM_NHAN_ID
           AND NVL(ll.IS_DELETED, 0) = 0
        WHERE (p_phan_doi_id IS NULL OR v.PHAN_DOI_ID = p_phan_doi_id)
          and (p_ma_trai_giam is null or v.TRAI_GIAM_MA = p_ma_trai_giam)
          AND (p_dia_phuong_cu_tru_id IS NULL
               OR ll.LL_NOI_THA_VE_CU_TRU_PROVICE = p_dia_phuong_cu_tru_id)
          AND (v_tk_like IS NULL OR UPPER(NVL(v.HO_TEN, '')) LIKE v_tk_like)
    ),
    ds AS (
        SELECT
            di.*,
            dm.TD_CHUONG AS td_chuong
        FROM ds_inner di
        LEFT JOIN QLPN.DM_TOI_DANHS dm
            ON dm.ID = CASE
                WHEN REGEXP_LIKE(REGEXP_SUBSTR(di.toi_csv, '[0-9]+', 1, 1), '^[0-9]+$')
                THEN TO_NUMBER(REGEXP_SUBSTR(di.toi_csv, '[0-9]+', 1, 1))
            END
           AND NVL(dm.IS_DELETED, 0) = 0
        WHERE (p_doi_tuong IS NULL
               OR (p_doi_tuong = 1 AND TRIM(TO_CHAR(dm.TD_CHUONG)) = '13')
               OR (p_doi_tuong = 2 AND (dm.TD_CHUONG IS NULL OR TRIM(TO_CHAR(dm.TD_CHUONG)) <> '13')))
    )
    SELECT
        d.PHAM_NHAN_ID AS pham_nhan_id,
        d.tha_co_dieu_kien_id,
        d.dot_tha_co_dieu_kien_id,
        NVL(TRIM(d.TRAI_GIAM), '') AS trai_giam,
        NVL(TRIM(d.HO_TEN), '') AS ho_ten,
        NVL(TRIM(d.TEN_KHAC), '') AS ten_khac,
        NVL(TRIM(d.NGUYEN_QUAN), '') AS nguyen_quan,
        CASE
            WHEN d.NGAY_SINH IS NOT NULL AND REGEXP_LIKE(TRIM(CAST(d.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(CAST(d.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN d.NAM_SINH IS NOT NULL AND d.NAM_SINH > 0 THEN TO_CHAR(d.NAM_SINH)
            WHEN d.NGAY_SINH IS NOT NULL THEN TRIM(CAST(d.NGAY_SINH AS VARCHAR2(100)))
            ELSE NULL
        END AS ngay_sinh,
        CASE
            WHEN d.NAM_SINH IS NOT NULL AND d.NAM_SINH > 0 THEN TO_CHAR(d.NAM_SINH)
            WHEN d.NGAY_SINH IS NOT NULL AND REGEXP_LIKE(TRIM(TO_CHAR(d.NGAY_SINH)), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(EXTRACT(YEAR FROM TO_DATE(TRIM(TO_CHAR(d.NGAY_SINH)), 'DD/MM/YYYY')))
            WHEN d.NGAY_SINH IS NOT NULL THEN TRIM(TO_CHAR(d.NGAY_SINH))
            ELSE NULL
        END AS nam_sinh,
        NVL(TRIM(d.GIOI_TINH), '') AS gioi_tinh,
        NVL(TRIM(d.DIA_CHI_THUONG_TRU), '') AS dia_chi_thuong_tru_so_nha,
        NVL(TRIM(d.TINH_THANH_THUONG_TRU), '') AS tinh_thanh_thuong_tru,
        NVL(TRIM(d.PHUONG_XA_THUONG_TRU), '') AS phuong_xa_thuong_tru,
        NVL(TRIM(d.NOI_THUONG_TRU_DAY_DU), '') AS dia_chi_thuong_tru,
        NVL(TRIM(d.NOI_THA_VE_CU_TRU), '') AS noi_tha_ve_cu_tru,
        NVL(TRIM(d.NOI_THA_VE_CU_TRU_XA), '') AS noi_tha_ve_cu_tru_xa,
        NVL(TRIM(d.NOI_THA_VE_CU_TRU_TINH), '') AS noi_tha_ve_cu_tru_tinh,
        NVL(TRIM(d.DAN_TOC), '') AS dan_toc,
        NVL(TRIM(d.TON_GIAO), '') AS ton_giao,
        NVL(TRIM(d.QUOC_TICH), '') AS quoc_tich,
        NVL(TRIM(TO_CHAR(d.SO_TIEN_AN)), '') AS tien_an,
        COALESCE(
            NULLIF(TRIM(d.TOI_DANH), u''),
            u'Ch\01b0a x\00e1c \0111\1ecbnh' 
        ) AS toi_danh,
        TO_CHAR(TRUNC(d.NGAY_BAT_AN_PHAT), 'DD/MM/YYYY') AS ngay_bat,
        NVL(NULLIF(TRIM(d.AN_PHAT), u''), NVL(CAST(mta_phat.MTG_TITLE AS NVARCHAR2(500)), u'')) AS an_phat,
        NVL(TRIM(d.SO_BAN_AN), '') AS so_ban_an,
        TO_CHAR(TRUNC(d.NGAY_BAN_AN), 'DD/MM/YYYY') AS ngay_ban_an,
        NVL(TRIM(d.TOA_XU_TEN), '') AS toa_xu_ten,
        NVL(TRIM(d.TOA_XU_DIA_PHUONG), '') AS toa_xu_dia_phuong,
        NVL(TRIM(cap_toa_xu.CTX_TEN), '') AS cap_toa_xu_ten,
        TO_CHAR(TRUNC(d.NGAY_THA), 'DD/MM/YYYY') AS ngay_tha,
        NVL(TRIM(d.so_quyet_dinh_tha), '') AS so_quyet_dinh_tha,
        TO_CHAR(TRUNC(d.NGAY_QUYET_DINH_THA), 'DD/MM/YYYY') AS ngay_quyet_dinh_tha,
        NVL(TRIM(d.CO_QUAN_QD_THA), '') AS toa_quyet_dinh_tha_ten,
        NVL(TRIM(d.TOA_QD_THA_DIA_PHUONG), '') AS toa_quyet_dinh_tha_dia_phuong,
        TO_CHAR(TRUNC(d.NGAY_DEN_TRAI), 'DD/MM/YYYY') AS ngay_vao_trai,
        TO_CHAR(TRUNC(d.NGAY_TRINH_DIEN), 'DD/MM/YYYY') AS ngay_trinh_dien,
        NVL(TRIM(TO_CHAR(d.so_ho_so_lan_dau)), '') AS so_ho_so_lan_dau,
        TO_CHAR(TRUNC(d.tha_ngay_lap_danh_ban), 'DD/MM/YYYY') AS ngay_lap_ho_so,
        CAST(NULL AS VARCHAR2(50)) AS so_to_trong_ho_so,
        NVL(TRIM(d.CCCD), '') AS cccd,
        NVL(TRIM(d.TRAI_GIAM), '') AS noi_lap_ho_so,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(d.PHAM_NHAN_ID), u'Kh\00f4ng') AS giam_an,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(d.PHAM_NHAN_ID, TRUNC(d.NGAY_XET)), u'') AS tg_chap_hanh,
        NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(d.PHAM_NHAN_ID, TRUNC(d.NGAY_XET)), u'') AS tg_con_lai,
        TO_CHAR(TRUNC(d.NGAY_HET_AN), 'DD/MM/YYYY') AS ngay_het_han,
        d.PHAN_DOI AS phan_doi,
        d.PHAN_TRAI AS phan_trai,
        NVL(TRIM(d.THOI_GIAN_TAM_GIAM), '') AS thoi_gian_tam_giam,
        NVL(TRIM(d.THOI_GIAN_TAM_GIU), '') AS thoi_gian_tam_giu,
        TO_CHAR(TRUNC(d.NGAY_BAN_AN), 'DD/MM/YYYY') AS ngay_xu
    FROM ds d
    LEFT JOIN thha_loai tha_lb
        ON tha_lb.pham_nhan_id = d.PHAM_NHAN_ID
    LEFT JOIN QLPN.DM_CAP_TOA_XUS cap_toa_xu
        ON cap_toa_xu.ID = tha_lb.tha_loai_ban_an_id
       AND NVL(cap_toa_xu.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_MA_THOI_GIANS mta_phat
        ON mta_phat.ID = d.MUC_AN_ID
       AND NVL(mta_phat.IS_DELETED, 0) = 0
    ORDER BY d.HO_TEN, d.NGAY_XET DESC NULLS LAST
    OFFSET v_skip ROWS
    FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, u'L\1ed7i khi l\1ea5y danh s\00e1ch b\00e0n giao h\1ed3 s\01a1 tha c\00f3 \0111i\1ec1u ki\1ec7n: ' || SQLERRM);
END SP_GET_THA_CDK_BAN_GIAO_PN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THA_CDK_DS_DUOC_THA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THA_CDK_DS_DUOC_THA" (
    p_ngay_xet_tu          IN  DATE      DEFAULT NULL,
    p_ngay_xet_den         IN  DATE      DEFAULT NULL,
    p_tu_ngay_tha          IN  DATE      DEFAULT NULL,
    p_den_ngay_tha         IN  DATE      DEFAULT NULL,
    p_phan_doi_id          IN  NUMBER    DEFAULT NULL,
    p_phan_trai_id          IN  NUMBER    DEFAULT NULL,
    p_tinh_trang_pn_id     IN  NUMBER    DEFAULT NULL,
    p_dia_phuong_cu_tru_id IN  NUMBER    DEFAULT NULL,
    p_tinh_trang_tha_id    IN  NUMBER    DEFAULT NULL,
    p_ma_trai_giam         IN  VARCHAR2  DEFAULT NULL,
    p_maxresultcount       IN  NUMBER    DEFAULT 50,
    p_skipcount            IN  NUMBER    DEFAULT 0
) AS
    v_skip          NUMBER;
    v_limit         NUMBER;
    v_trai_giam_id  NUMBER;
    v_ma_trai_giam  NVARCHAR2(20);
    c1              SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    v_trai_giam_id := NULL;
    v_ma_trai_giam := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        v_ma_trai_giam := TRIM(p_ma_trai_giam);
        BEGIN
            SELECT ID INTO v_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = v_ma_trai_giam
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                v_trai_giam_id := NULL;
        END;
    END IF;

    OPEN c1 FOR
    WITH
    active_tinh_trang_ids AS (
        SELECT /*+ MATERIALIZE */ ID
        FROM QLPN.DM_TINH_TRANG_PHAM_NHANS
        WHERE NVL(IS_DELETED, 0) = 0
          AND (
              p_tinh_trang_pn_id IS NULL
              OR (p_tinh_trang_pn_id = 1 AND TTPN_MA IN ('111', '112', '113', '114'))
              OR (p_tinh_trang_pn_id = 2 AND TTPN_MA = '126')
          )
    ),
    tha_one AS (
        SELECT /*+ MATERIALIZE */
               t.ID AS THA_CO_DIEU_KIEN_ID,
               t.PHAM_NHAN_ID,
               t.NGAY_XET,
               t.NGAY_THA,
               t.DANH_GIA_CAI_TAO_ID,
               t.TINH_TRANG_ID AS TINH_TRANG_THA_ID
        FROM QLPN.THA_CO_DIEU_KIENS t
        WHERE NVL(t.IS_DELETED, 0) = 0
          AND (p_tinh_trang_tha_id IS NULL OR t.TINH_TRANG_ID = p_tinh_trang_tha_id)
          AND (p_ngay_xet_tu IS NULL OR t.NGAY_XET >= TRUNC(p_ngay_xet_tu))
          AND (p_ngay_xet_den IS NULL OR t.NGAY_XET < TRUNC(p_ngay_xet_den) + 1)
          AND (p_tu_ngay_tha IS NULL OR t.NGAY_THA >= TRUNC(p_tu_ngay_tha))
          AND (p_den_ngay_tha IS NULL OR t.NGAY_THA < TRUNC(p_den_ngay_tha) + 1)
    ),
    ds AS (
        SELECT /*+ LEADING(t rt) USE_NL(rt) */
            t.THA_CO_DIEU_KIEN_ID,
            t.PHAM_NHAN_ID,
            t.NGAY_XET,
            t.NGAY_THA,
            t.DANH_GIA_CAI_TAO_ID,
            t.TINH_TRANG_THA_ID,
            rt.LL_HO_TEN AS HO_TEN,
            rt.HO_TEN_ORDER,
            rt.LL_NGAY_SINH AS NGAY_SINH,
            rt.NAM_SINH,
            gt.GT_TEN AS GIOI_TINH,
            CASE
                WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                  OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                  OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
                THEN TRIM(
                    NVL(NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u''), u'')
                    || CASE
                        WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                            CASE
                                WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || dxp_thuong_tru.XP_TEN
                                ELSE dxp_thuong_tru.XP_TEN
                            END
                        ELSE u''
                       END
                    || CASE
                        WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                            CASE
                                WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                  OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || dttp_thuong_tru.TTP_TEN
                                ELSE dttp_thuong_tru.TTP_TEN
                            END
                        ELSE u''
                       END
                )
                ELSE NULL
            END AS NOI_THUONG_TRU_DAY_DU,
            CASE
                WHEN NULLIF(TRIM(rt.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
                  OR NULLIF(TRIM(ntvct_xp.XP_TEN), u'') IS NOT NULL
                  OR NULLIF(TRIM(ntvct_ttp.TTP_TEN), u'') IS NOT NULL
                THEN TRIM(
                    NVL(NULLIF(TRIM(rt.LL_NOI_THA_VE_CU_TRU), u''), u'')
                    || CASE
                        WHEN NULLIF(TRIM(ntvct_xp.XP_TEN), u'') IS NOT NULL THEN
                            CASE
                                WHEN NULLIF(TRIM(rt.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
                                THEN u', ' || ntvct_xp.XP_TEN
                                ELSE ntvct_xp.XP_TEN
                            END
                        ELSE u''
                       END
                    || CASE
                        WHEN NULLIF(TRIM(ntvct_ttp.TTP_TEN), u'') IS NOT NULL THEN
                            CASE
                                WHEN NULLIF(TRIM(rt.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
                                  OR NULLIF(TRIM(ntvct_xp.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || ntvct_ttp.TTP_TEN
                                ELSE ntvct_ttp.TTP_TEN
                            END
                        ELSE u''
                       END
                )
                ELSE NULL
            END AS NOI_THA_VE_CU_TRU,
            dttp_thuong_tru.TTP_TEN AS TINH_THANH_THUONG_TRU,
            rt.LL_SO_TIEN_AN AS SO_TIEN_AN,
            rt.THA_TOI_DANH_NAMES AS TOI_DANH,
            rt.THA_NGAY_BAT AS NGAY_BAT_AN_PHAT,
            rt.THA_AN_PHAT AS AN_PHAT,
            rt.THA_THOI_GIAN_TAM_GIAM AS THOI_GIAN_TAM_GIAM,
            rt.SO_LAN_GIAM,
            rt.THOI_GIAN_DA_GIAM,
            rt.THA_NGAY_DEN_TRAI AS NGAY_DEN_TRAI,
            pd.PD_TEN AS PHAN_DOI,
            pt.PT_TEN AS PHAN_TRAI,
            rt.LL_PHAN_DOI_ID AS PHAN_DOI_ID,
            rt.LL_TINH_TRANG_ID,
            rt.GHI_CHU AS GHI_CHU_LAI_LICH,
            COALESCE(rt.THA_NGAY_BAT_DAU_O_TU, rt.THA_NGAY_BAT) AS THA_NGAY_BAT
        FROM tha_one t
        INNER JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt
            ON rt.PHAM_NHAN_ID = t.PHAM_NHAN_ID
           AND NVL(rt.IS_DELETED, 0) = 0
           AND NVL(rt.LL_IS_DELETED, 0) = 0
           AND NVL(rt.THA_IS_DELETED, 0) = 0
           AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
        INNER JOIN active_tinh_trang_ids tt
            ON tt.ID = rt.LL_TINH_TRANG_ID
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = rt.LL_DM_GIOI_TINH_ID
           AND NVL(gt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_DOIS pd
            ON pd.ID = rt.LL_PHAN_DOI_ID
           AND NVL(pd.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_TRAIS pt
            ON pt.ID = rt.LL_PHAN_TRAI_ID
           AND NVL(pt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XA_PHUONG dxp_thuong_tru
            ON dxp_thuong_tru.ID = rt.LL_DIA_CHI_THUONG_TRU_WARD
           AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO dttp_thuong_tru
            ON dttp_thuong_tru.ID = rt.LL_DIA_CHI_THUONG_TRU_PROVICE
           AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XA_PHUONG ntvct_xp
            ON ntvct_xp.ID = rt.LL_NOI_THA_VE_CU_TRU_WARD
           AND NVL(ntvct_xp.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO ntvct_ttp
            ON ntvct_ttp.ID = rt.LL_NOI_THA_VE_CU_TRU_PROVICE
           AND NVL(ntvct_ttp.IS_DELETED, 0) = 0
        WHERE (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = p_phan_doi_id)
         AND (p_phan_trai_id IS NULL OR rt.LL_PHAN_TRAI_ID = p_phan_trai_id)
          AND (p_dia_phuong_cu_tru_id IS NULL
               OR rt.LL_NOI_THA_VE_CU_TRU_PROVICE = p_dia_phuong_cu_tru_id)
    ),
    filtered_core AS (
        SELECT d.*,
               COUNT(*) OVER() AS TOTAL_COUNT
        FROM ds d
    ),
    paged AS (
        SELECT *
        FROM filtered_core fc
        ORDER BY fc.HO_TEN_ORDER ASC NULLS LAST,
                 fc.NGAY_XET DESC NULLS LAST
        OFFSET v_skip ROWS
        FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY
    )
    SELECT
        p.PHAM_NHAN_ID,
        NVL(TRIM(p.HO_TEN), '') AS HO_TEN,
        CASE
            WHEN p.NGAY_SINH IS NOT NULL
                 AND REGEXP_LIKE(TRIM(TO_CHAR(p.NGAY_SINH)), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(TO_CHAR(p.NGAY_SINH)), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN p.NAM_SINH IS NOT NULL AND p.NAM_SINH > 0 THEN TO_CHAR(p.NAM_SINH)
            WHEN p.NGAY_SINH IS NOT NULL THEN TRIM(TO_CHAR(p.NGAY_SINH))
            ELSE NULL
        END AS NGAY_SINH,
        NVL(TRIM(p.GIOI_TINH), '') AS GIOI_TINH,
        NVL(TRIM(p.NOI_THUONG_TRU_DAY_DU), '') AS DIA_CHI_THUONG_TRU,
        NVL(TRIM(p.NOI_THUONG_TRU_DAY_DU), '') AS NOI_THUONG_TRU_DAY_DU,
        NVL(TRIM(p.NOI_THA_VE_CU_TRU), '') AS NOI_THA_VE_CU_TRU,
        COALESCE(
            NULLIF(TRIM(p.TOI_DANH), u''),
            u'Ch\01b0a x\00e1c \0111\1ecbnh'
        ) AS TOI_DANH,
        NVL(TRIM(TO_CHAR(p.SO_TIEN_AN)), '') AS SO_TIEN_AN,
        CASE WHEN p.NGAY_BAT_AN_PHAT IS NOT NULL
             THEN TO_CHAR(p.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') ELSE NULL END AS NGAY_BAT_AN_PHAT,
        NVL(TRIM(p.AN_PHAT), '') AS AN_PHAT,
        NVL(TRIM(p.THOI_GIAN_TAM_GIAM), '') AS THOI_GIAN_TAM_GIAM,
        CASE
            WHEN NVL(p.SO_LAN_GIAM, 0) = 0 THEN u'Kh\00f4ng'
            WHEN NVL(TO_NCHAR(p.THOI_GIAN_DA_GIAM), u'0') = u'0' OR p.THOI_GIAN_DA_GIAM IS NULL
            THEN TO_NCHAR(p.SO_LAN_GIAM) || u' l\1ea7n'
            ELSE TO_NCHAR(p.SO_LAN_GIAM) || u' l\1ea7n = ' || TO_NCHAR(p.THOI_GIAN_DA_GIAM)
        END AS DA_GIAM,
        CASE WHEN p.NGAY_DEN_TRAI IS NOT NULL
             THEN TO_CHAR(p.NGAY_DEN_TRAI, 'DD/MM/YYYY') ELSE NULL END AS NGAY_DEN_TRAI,
        p.PHAN_DOI,
        p.PHAN_TRAI,
        CASE
            WHEN memo.NGAY_HET IS NOT NULL
            THEN TO_CHAR(memo.NGAY_HET, 'DD/MM/YYYY')
            ELSE TO_CHAR(QLPN.PKG_TINH_AN.FN_TINH_NGAY_THA(p.PHAM_NHAN_ID, p.NGAY_XET), 'DD/MM/YYYY')
        END AS NGAY_HET_AN,
        CASE
            WHEN memo.PN_ID IS NULL THEN
                NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(p.PHAM_NHAN_ID, p.NGAY_XET), u'')
            WHEN memo.NGAY_BAT IS NOT NULL AND TRUNC(memo.NGAY_BAT) > TRUNC(p.NGAY_XET) THEN u'Kh\00f4ng'
            WHEN memo.TG_DA IS NULL OR memo.NGAY_XET_TL IS NULL THEN u'Kh\00f4ng'
            WHEN memo.TG_DA = '000000' THEN u'Kh\00f4ng'
            ELSE NVL(dmtg_da.MTG_TITLE, u'Kh\00f4ng')
        END AS THOI_GIAN_CHAP_HANH,
        CASE
            WHEN memo.PN_ID IS NULL THEN
                NVL(QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(p.PHAM_NHAN_ID, p.NGAY_XET), u'')
            WHEN memo.NGAY_BAT IS NULL OR memo.TG_CON IS NULL OR memo.NGAY_XET_TL IS NULL THEN u''
            WHEN memo.TG_CON = '000000' THEN u'Kh\00f4ng'
            ELSE NVL(dmtg_cl.MTG_TITLE, u'Kh\00f4ng')
        END AS THOI_GIAN_CON_LAI,
        NVL(TRIM(p.TINH_THANH_THUONG_TRU), '') AS TINH_THANH_THUONG_TRU,
        CASE WHEN p.NGAY_THA IS NOT NULL
             THEN TO_CHAR(p.NGAY_THA, 'DD/MM/YYYY') ELSE NULL END AS NGAY_THA,
        CASE WHEN p.NGAY_XET IS NOT NULL
             THEN TO_CHAR(p.NGAY_XET, 'DD/MM/YYYY') ELSE NULL END AS NGAY_XET,
        NVL(TRIM(TO_CHAR(p.SO_LAN_GIAM)), '') AS LAN_GIAM_AN,
        NVL(CAST(p.THOI_GIAN_DA_GIAM AS VARCHAR2(500)), '') AS TONG_GIAM_AN,
        NVL(CAST(QLPN.FN_GET_LIET_KE_HPBST_TNDST(p.PHAM_NHAN_ID) AS VARCHAR2(4000)), '') AS HPBS_TIEN,
        NVL(CAST(QLPN.FN_GET_LIET_KE_HPBS_KHAC(p.PHAM_NHAN_ID) AS VARCHAR2(4000)), '') AS HPBS_KHAC,
        NVL(TRIM(xlct.XLCT_TEN), '') AS KET_QUA_CAI_TAO,
        p.TINH_TRANG_THA_ID,
        p.LL_TINH_TRANG_ID AS TINH_TRANG_PN_ID,
        NVL(TRIM(p.GHI_CHU_LAI_LICH), '') AS GHI_CHU_CHUNG,
        NVL(CAST(QLPN.FN_GHI_CHU_PHAM_NHAN(p.PHAM_NHAN_ID) AS VARCHAR2(2000)), '') AS GHI_CHU,
        CASE
            WHEN NVL(p.SO_LAN_GIAM, 0) = 0 THEN u'Kh\00f4ng'
            WHEN NVL(TO_NCHAR(p.THOI_GIAN_DA_GIAM), u'0') = u'0' OR p.THOI_GIAN_DA_GIAM IS NULL
            THEN TO_NCHAR(p.SO_LAN_GIAM) || u' l\1ea7n'
            ELSE TO_NCHAR(p.SO_LAN_GIAM) || u' l\1ea7n = ' || TO_NCHAR(p.THOI_GIAN_DA_GIAM)
        END AS giam_an,
        CAST(u'200,000 VN\0110' AS NVARCHAR2(200)) AS TIEN_AN_DUONG,
        CAST(u'200,000 VN\0110' AS NVARCHAR2(200)) AS TIEN_TAU_XE,
        CAST(u'200,000 VN\0110' AS NVARCHAR2(200)) AS TIEN_TAI_HOA_NHAP_CONG_DONG,
        CASE WHEN p.THA_NGAY_BAT IS NOT NULL
             THEN TO_CHAR(p.THA_NGAY_BAT, 'DD/MM/YYYY') ELSE NULL END AS NGAY_CHAP_HANH_AN_PHAT_TU,
        p.TOTAL_COUNT
    FROM paged p
    LEFT JOIN QLPN.DM_XEP_LOAI_CAI_TAOS xlct
        ON xlct.ID = p.DANH_GIA_CAI_TAO_ID
       AND NVL(xlct.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.TCDK_CORE_MEMO memo
        ON memo.PN_ID = p.PHAM_NHAN_ID
       AND TRUNC(memo.NGAY_XET_KEY) = TRUNC(p.NGAY_XET)
    LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg_da
        ON dmtg_da.MTG_MA = memo.TG_DA AND NVL(dmtg_da.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg_cl
        ON dmtg_cl.MTG_MA = memo.TG_CON AND NVL(dmtg_cl.IS_DELETED, 0) = 0
    ORDER BY p.HO_TEN_ORDER ASC NULLS LAST,
             p.NGAY_XET DESC NULLS LAST;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, u'L\1ed7i khi l\1ea5y danh s\00e1ch \0111\01b0\1ee3c tha c\00f3 \0111i\1ec1u ki\1ec7n: ' || SQLERRM);
END SP_GET_THA_CDK_DS_DUOC_THA;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THA_CDK_TK_SO_LIEU_THA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THA_CDK_TK_SO_LIEU_THA" (
    p_tu_ngay     IN DATE DEFAULT NULL,
    p_den_ngay    IN DATE DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_ma_trai_giam IN VARCHAR2 default null
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    pn_dot AS (
        SELECT
            TRUNC(t.NGAY_XET) AS dot_ngay,
            t.PHAM_NHAN_ID,
            MAX(CASE WHEN t.NGAY_THA IS NOT NULL THEN 1 ELSE 0 END) AS da_co_ngay_tha
        FROM QLPN.THA_CO_DIEU_KIENS t
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.ID = t.PHAM_NHAN_ID
           AND NVL(ll.IS_DELETED, 0) = 0
        WHERE NVL(t.IS_DELETED, 0) = 0
          AND t.NGAY_XET IS NOT NULL
          AND (p_tu_ngay IS NULL OR TRUNC(t.NGAY_XET) >= TRUNC(p_tu_ngay))
          AND (p_den_ngay IS NULL OR TRUNC(t.NGAY_XET) <= TRUNC(p_den_ngay))
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
        GROUP BY TRUNC(t.NGAY_XET), t.PHAM_NHAN_ID
    ),
    dot_gt AS (
        SELECT
            pd.dot_ngay,
            pd.PHAM_NHAN_ID,
            pd.da_co_ngay_tha,
            CASE
                WHEN NVL(TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))), '') = '1' THEN 1
                WHEN NVL(TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))), '') = '2' THEN 0
                WHEN REGEXP_LIKE(TRIM(NVL(CAST(gt.GT_TEN AS NVARCHAR2(200)), u'')), u'^nam$', 'i') THEN 1
                ELSE 0
            END AS flg_nam,
            CASE
                WHEN NVL(TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))), '') = '2' THEN 1
                WHEN NVL(TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))), '') = '1' THEN 0
                WHEN REGEXP_LIKE(TRIM(NVL(CAST(gt.GT_TEN AS NVARCHAR2(200)), u'')), u'^[Nn](?|?|[uU])$') THEN 1
                ELSE 0
            END AS flg_nu,
            TRIM(NVL(CAST(gt.GT_TEN AS NVARCHAR2(200)), u'')) AS gt_ten_trim
        FROM pn_dot pd
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.ID = pd.PHAM_NHAN_ID
           AND NVL(ll.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = ll.LL_DM_GIOI_TINH_ID
           AND NVL(gt.IS_DELETED, 0) = 0
        where (p_ma_trai_giam is null or ll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA =p_ma_trai_giam))
    ),
    agg AS (
        SELECT
            dg.dot_ngay,
            SUM(CASE WHEN dg.flg_nam = 1 THEN 1 ELSE 0 END) AS dv_de_nghi_nam,
            SUM(CASE WHEN dg.flg_nu = 1 THEN 1 ELSE 0 END) AS dv_de_nghi_nu,
            SUM(
                CASE
                    WHEN dg.flg_nam = 0
                         AND dg.flg_nu = 0
                         AND dg.gt_ten_trim IS NOT NULL
                         AND dg.gt_ten_trim <> u''
                    THEN 1
                    ELSE 0
                END
            ) AS dv_de_nghi_khac,
            COUNT(*) AS dv_de_nghi_tong,
            SUM(CASE WHEN dg.da_co_ngay_tha = 1 AND dg.flg_nam = 1 THEN 1 ELSE 0 END) AS toa_qd_tha_nam,
            SUM(CASE WHEN dg.da_co_ngay_tha = 1 AND dg.flg_nu = 1 THEN 1 ELSE 0 END) AS toa_qd_tha_nu,
            SUM(
                CASE
                    WHEN dg.da_co_ngay_tha = 1
                         AND dg.flg_nam = 0
                         AND dg.flg_nu = 0
                         AND dg.gt_ten_trim IS NOT NULL
                         AND dg.gt_ten_trim <> u''
                    THEN 1
                    ELSE 0
                END
            ) AS toa_qd_tha_khac,
            SUM(CASE WHEN dg.da_co_ngay_tha = 1 THEN 1 ELSE 0 END) AS toa_qd_tha_tong
        FROM dot_gt dg
        GROUP BY dg.dot_ngay
    )
    SELECT
        ROW_NUMBER() OVER (ORDER BY a.dot_ngay DESC NULLS LAST) AS stt,
        TO_CHAR(a.dot_ngay, 'DD/MM/YYYY') AS dot_xet_tha,
        NVL(a.dv_de_nghi_nam, 0) AS dv_de_nghi_nam,
        NVL(a.dv_de_nghi_nu, 0) AS dv_de_nghi_nu,
        NVL(a.dv_de_nghi_khac, 0) AS dv_de_nghi_khac,
        NVL(a.dv_de_nghi_tong, 0) AS dv_de_nghi_tong,
        NVL(a.toa_qd_tha_nam, 0) AS toa_qd_tha_nam,
        NVL(a.toa_qd_tha_nu, 0) AS toa_qd_tha_nu,
        NVL(a.toa_qd_tha_khac, 0) AS toa_qd_tha_khac,
        NVL(a.toa_qd_tha_tong, 0) AS toa_qd_tha_tong
    FROM agg a
    ORDER BY a.dot_ngay DESC NULLS LAST;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i khi th\1ed1ng k\00ea s\1ed1 li\1ec7u tha c\00f3 \0111i\1ec1u ki\1ec7n theo \0111\1ee3t: ' || SQLERRM
        );
END SP_GET_THA_CDK_TK_SO_LIEU_THA;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THA_CDK_TK_SO_LIEU_THA_CO_DK_PT109
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THA_CDK_TK_SO_LIEU_THA_CO_DK_PT109" (
    p_tu_ngay     IN DATE DEFAULT NULL,
    p_den_ngay    IN DATE DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_ma_trai_giam IN VARCHAR2 DEFAULT NULL
) AS
    c1 SYS_REFCURSOR;
    v_ngay_tinh DATE;
BEGIN
    v_ngay_tinh := TRUNC(NVL(p_den_ngay, SYSDATE));

    OPEN c1 FOR
    WITH
    trai_filter AS (
        SELECT dtg.ID AS trai_giam_id
        FROM QLPN.DM_TRAI_GIAMS dtg
        WHERE p_ma_trai_giam IS NOT NULL
          AND TRIM(p_ma_trai_giam) IS NOT NULL
          AND dtg.TG_MA = p_ma_trai_giam
          AND NVL(dtg.IS_DELETED, 0) = 0
          AND ROWNUM = 1
    ),
    tha_filtered AS (
        SELECT ID, PHAM_NHAN_ID, NGAY_XET, TINH_TRANG_ID, NGAY_THA, TG_CON_LAI_TT
        FROM (
            SELECT
                t.ID,
                t.PHAM_NHAN_ID,
                t.NGAY_XET,
                t.TINH_TRANG_ID,
                t.NGAY_THA,
                t.TG_CON_LAI_TT,
                -- 1 PN có th? có nhi?u b?n ghi xét (xét l?i) trong cùng kho?ng ngày; ch? l?y b?n ghi
                -- xét g?n nh?t/m?i nh?t ?? kh?p v?i "s? ph?m nhân" hi?n th? trên danh sách (không ph?i
                -- s? dòng xét), tránh ??m trùng ? tong_so_hdx.
                ROW_NUMBER() OVER (
                    PARTITION BY t.PHAM_NHAN_ID
                    ORDER BY t.NGAY_XET DESC, t.ID DESC
                ) AS rn
            FROM QLPN.THA_CO_DIEU_KIENS t
            INNER JOIN QLPN.PN_LAI_LICHS ll
                ON ll.ID = t.PHAM_NHAN_ID
               AND NVL(ll.IS_DELETED, 0) = 0
            WHERE NVL(t.IS_DELETED, 0) = 0
              AND t.NGAY_XET IS NOT NULL
              AND t.NGAY_XET < v_ngay_tinh + 1
              AND (p_tu_ngay IS NULL OR t.NGAY_XET >= TRUNC(p_tu_ngay))
              AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
              AND (
                    p_ma_trai_giam IS NULL
                 OR ll.LL_TRAI_GIAM_ID IN (SELECT trai_giam_id FROM trai_filter)
              )
        )
        WHERE rn = 1
    ),
    pn_base AS (
        SELECT
            t.PHAM_NHAN_ID,
            t.NGAY_XET,
            dm.TCDK_MA,
            CASE WHEN dm.TCDK_MA IN ('10', '11') THEN 1 ELSE 0 END AS flg_nhat_tri,
            CASE
                WHEN NVL(TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))), '') = '1' THEN 1
                WHEN REGEXP_LIKE(TRIM(NVL(CAST(gt.GT_TEN AS NVARCHAR2(200)), u'')), u'^nam$', 'i') THEN 1
                ELSE 0
            END AS flg_nam,
            CASE
                WHEN NVL(TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))), '') = '2' THEN 1
                WHEN REGEXP_LIKE(TRIM(NVL(CAST(gt.GT_TEN AS NVARCHAR2(200)), u'')), u'^[Nn](?|?|[uU])$') THEN 1
                ELSE 0
            END AS flg_nu,
            ll.LL_NGAY_SINH,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS ngay_sinh_date,
            ll.LL_TRAI_GIAM_ID,
            dtg.TG_TEN AS trai_ten,
            tha.THA_AN_PHAT_GOC,
            tha.THA_AN_PHAT,
            -- TG_CON_LAI_TT ch? ?áng tin khi ?ã có NGAY_THA (?óng b?ng snapshot t?i th?i ?i?m ra
            -- quy?t ??nh tha, theo ?úng quy ??c t?i SP_GET_DS_PN_DE_NGHI_THA_CO_DK). Khi còn ?ang ch?
            -- xét (NGAY_THA NULL) thì c?t này có th? là s? c?/không ??ng b? -> ph?i tính t??i qua
            -- PKG_TINH_AN, n?u không "Th?i h?n còn l?i" s? b? l?ch nhóm (vd r?i vào "T? 3 n?m tr? xu?ng"
            -- thay vì ?úng nhóm th?c t?).
            CASE
                WHEN t.NGAY_THA IS NOT NULL THEN t.TG_CON_LAI_TT
                ELSE QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(t.PHAM_NHAN_ID, t.NGAY_XET)
            END AS con_lai_text
        FROM tha_filtered t
        INNER JOIN QLPN.PN_LAI_LICHS ll
            ON ll.ID = t.PHAM_NHAN_ID
           AND NVL(ll.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_THA_CO_DIEU_KIENS dm
            ON dm.ID = t.TINH_TRANG_ID
           AND NVL(dm.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = ll.LL_DM_GIOI_TINH_ID
           AND NVL(gt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
           AND NVL(dtg.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.PN_THI_HANH_AN tha
            ON tha.THA_PNLAI_LICH_ID = t.PHAM_NHAN_ID
           AND NVL(tha.IS_DELETED, 0) = 0
    ),
    pn_calc AS (
        SELECT
            b.*,
            -- So kh?p không d?u/không kho?ng tr?ng: "Chung thân" có ký t? "â" (không ph?i "a" ASCII)
            -- nên regex 'chung\s*than' (so kh?p ch? "than" ASCII) không bao gi? kh?p -> luôn ra 0.
            CASE
                WHEN LOWER(QLPN.FN_NORMALIZE_VN(NVL(b.THA_AN_PHAT_GOC, b.THA_AN_PHAT))) LIKE '%chungthan%' THEN 1
                ELSE 0
            END AS flg_chung_than,
            (NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(NVL(b.THA_AN_PHAT_GOC, b.THA_AN_PHAT), 'NAM'), 0) * 12)
          +  NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(NVL(b.THA_AN_PHAT_GOC, b.THA_AN_PHAT), 'THANG'), 0)
          +  CASE
                WHEN NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(NVL(b.THA_AN_PHAT_GOC, b.THA_AN_PHAT), 'NGAY'), 0) > 0 THEN 1
                ELSE 0
             END AS an_phat_thang,
            (NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(b.con_lai_text, 'NAM'), 0) * 12)
          +  NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(b.con_lai_text, 'THANG'), 0)
          +  CASE
                WHEN NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(b.con_lai_text, 'NGAY'), 0) > 0 THEN 1
                ELSE 0
             END AS con_lai_thang,
            CASE
                WHEN b.ngay_sinh_date IS NOT NULL
                 AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, b.ngay_sinh_date) / 12) < 18
                THEN 1
                ELSE 0
            END AS flg_duoi_18,
            CASE
                WHEN b.trai_ten IS NOT NULL
                 AND (b.trai_ten LIKE u'%t\1ea1m gi\1eef%' OR b.trai_ten LIKE u'%t\1ea1m giam%')
                THEN 1
                ELSE 0
            END AS flg_trai_tam_giam
        FROM pn_base b
    ),
    agg AS (
        SELECT
            /* T?ng s? PN h?i ??ng xét */
            COUNT(*) AS tong_so_hdx,

            /* H?i ??ng không nh?t trí */
            SUM(CASE WHEN c.flg_nhat_tri = 0 AND c.flg_nam = 1 THEN 1 ELSE 0 END) AS khong_nhat_tri_nam,
            SUM(CASE WHEN c.flg_nhat_tri = 0 AND c.flg_nu  = 1 THEN 1 ELSE 0 END) AS khong_nhat_tri_nu,
            SUM(CASE WHEN c.flg_nhat_tri = 0 THEN 1 ELSE 0 END)                  AS khong_nhat_tri_cong,

            /* H?i ??ng nh?t trí */
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.flg_nam = 1 THEN 1 ELSE 0 END) AS nhat_tri_nam,
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.flg_nu  = 1 THEN 1 ELSE 0 END) AS nhat_tri_nu,
            SUM(CASE WHEN c.flg_nhat_tri = 1 THEN 1 ELSE 0 END)                  AS nhat_tri_cong,

            /* M?c án ph?t (trong nhóm NH?T TRÍ) */
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.flg_chung_than = 0 AND c.an_phat_thang <= 36  THEN 1 ELSE 0 END) AS map_tu_3_nam_xuong,
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.flg_chung_than = 0 AND c.an_phat_thang > 36  AND c.an_phat_thang <= 84  THEN 1 ELSE 0 END) AS map_tren_3_den_7,
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.flg_chung_than = 0 AND c.an_phat_thang > 84  AND c.an_phat_thang <= 120 THEN 1 ELSE 0 END) AS map_tren_7_den_10,
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.flg_chung_than = 0 AND c.an_phat_thang > 120 AND c.an_phat_thang <= 180 THEN 1 ELSE 0 END) AS map_tren_10_den_15,
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.flg_chung_than = 0 AND c.an_phat_thang > 180 AND c.an_phat_thang <= 360 THEN 1 ELSE 0 END) AS map_tren_15_den_30,
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.flg_chung_than = 1 THEN 1 ELSE 0 END) AS map_chung_than,

            /* Th?i h?n còn l?i (trong nhóm NH?T TRÍ) */
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.con_lai_thang <= 36  THEN 1 ELSE 0 END) AS cl_tu_3_nam_xuong,
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.con_lai_thang > 36  AND c.con_lai_thang <= 60  THEN 1 ELSE 0 END) AS cl_tren_3_den_5,
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.con_lai_thang > 60  AND c.con_lai_thang <= 84  THEN 1 ELSE 0 END) AS cl_tren_5_den_7,
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.con_lai_thang > 84  AND c.con_lai_thang <= 120 THEN 1 ELSE 0 END) AS cl_tren_7_den_10,
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.con_lai_thang > 120 THEN 1 ELSE 0 END) AS cl_tren_10,

            /* Ng??i d??i 18 tu?i (trong nhóm NH?T TRÍ) */
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.flg_duoi_18 = 1 THEN 1 ELSE 0 END) AS nguoi_duoi_18,

            /* N?i ch?p hành án ph?t tù (trong nhóm NH?T TRÍ) */
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.flg_trai_tam_giam = 0 THEN 1 ELSE 0 END) AS trai_giam,
            SUM(CASE WHEN c.flg_nhat_tri = 1 AND c.flg_trai_tam_giam = 1 THEN 1 ELSE 0 END) AS trai_tam_giam
        FROM pn_calc c
    )
    SELECT
        TO_CHAR(v_ngay_tinh, 'DD/MM/YYYY') AS ngay_tinh_den,

        NVL(a.tong_so_hdx, 0) AS tong_so_hdx,

        NVL(a.khong_nhat_tri_nam, 0)  AS khong_nhat_tri_nam,
        NVL(a.khong_nhat_tri_nu, 0)   AS khong_nhat_tri_nu,
        NVL(a.khong_nhat_tri_cong, 0) AS khong_nhat_tri_cong,

        NVL(a.nhat_tri_nam, 0)  AS nhat_tri_nam,
        NVL(a.nhat_tri_nu, 0)   AS nhat_tri_nu,
        NVL(a.nhat_tri_cong, 0) AS nhat_tri_cong,

        NVL(a.map_tu_3_nam_xuong, 0) AS map_tu_3_nam_xuong,
        NVL(a.map_tren_3_den_7, 0)   AS map_tren_3_den_7,
        NVL(a.map_tren_7_den_10, 0)  AS map_tren_7_den_10,
        NVL(a.map_tren_10_den_15, 0) AS map_tren_10_den_15,
        NVL(a.map_tren_15_den_30, 0) AS map_tren_15_den_30,
        NVL(a.map_chung_than, 0)     AS map_chung_than,

        NVL(a.cl_tu_3_nam_xuong, 0) AS cl_tu_3_nam_xuong,
        NVL(a.cl_tren_3_den_5, 0)   AS cl_tren_3_den_5,
        NVL(a.cl_tren_5_den_7, 0)   AS cl_tren_5_den_7,
        NVL(a.cl_tren_7_den_10, 0)  AS cl_tren_7_den_10,
        NVL(a.cl_tren_10, 0)        AS cl_tren_10,

        NVL(a.nguoi_duoi_18, 0) AS nguoi_duoi_18,

        NVL(a.trai_giam, 0)     AS trai_giam,
        NVL(a.trai_tam_giam, 0) AS trai_tam_giam
    FROM agg a;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L?i khi th?ng kê s? li?u tha có ?i?u ki?n (PT109): ' || SQLERRM
        );
END SP_GET_THA_CDK_TK_SO_LIEU_THA_CO_DK_PT109;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THA_IN_QUYET_DINH_CUA_TOA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THA_IN_QUYET_DINH_CUA_TOA" (
    p_dot_xet_id     IN  NUMBER    DEFAULT NULL,
    p_phan_doi_id    IN  NUMBER    DEFAULT NULL,
    p_doi_tuong_id   IN  NUMBER    DEFAULT NULL,
    p_quoc_tich_id   IN  NUMBER    DEFAULT NULL,
    p_tim_kiem       IN  NVARCHAR2 DEFAULT NULL,
    p_ma_trai_giam   IN  NVARCHAR2 DEFAULT NULL,  -- DM_TRAI_GIAMS.TG_MA; NULL = t?t c? tr?i
    -- NULL (không truy?n): không gi?i h?n s? b?n ghi; s? d??ng: t?i ?a p_maxresultcount sau p_skipcount
    p_maxresultcount IN  NUMBER    DEFAULT NULL,
    p_skipcount      IN  NUMBER    DEFAULT 0
) AS
    v_skip  NUMBER;
    v_limit NUMBER;
    v_tim_like VARCHAR2(2000);
    v_ll_trai_giam_id NUMBER;  -- resolve TG_MA ? ID ?? partition prune PN_LAI_LICH_CHI_TIET_RT (qua VW)
    c1      SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL
       AND TRIM(p_ma_trai_giam) IS NOT NULL
    THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                v_ll_trai_giam_id := NULL;
        END;
    END IF;

    IF p_tim_kiem IS NOT NULL AND LENGTH(TRIM(p_tim_kiem)) > 0 THEN
        v_tim_like := '%' || UPPER(TRIM(TO_CHAR(p_tim_kiem))) || '%';
    ELSE
        v_tim_like := NULL;
    END IF;

    OPEN c1 FOR
    WITH
       tha_one AS (
        SELECT t.ID AS tha_co_dieu_kien_id,
               t.PHAM_NHAN_ID,
               t.NGAY_XET,
               t.SO_QUYET_DINH_THA,
               t.NGAY_QUYET_DINH_THA,
               t.TOA_QUYET_DINH_THA_ID,
               t.DIA_PHUONG_QUYET_DINH_THA_ID,
               t.QQCT_PHIEU,
               t.NGAY_THA,
               t.NGAY_TRINH_DIEN,
               t.NHAN_XET,
               t.DANH_GIA_CAI_TAO_ID
        FROM THA_CO_DIEU_KIENS t
        LEFT JOIN PN_DOT_THA_CO_DIEU_KIENS dot
            ON TRUNC(t.NGAY_XET) = TRUNC(dot.DTCDK_NGAY_XET)
           AND NVL(dot.IS_DELETED, 0) = 0
        LEFT JOIN DM_THA_CO_DIEU_KIENS dm_tt
            ON dm_tt.ID = t.TINH_TRANG_ID
           AND NVL(dm_tt.IS_DELETED, 0) = 0
        WHERE NVL(t.IS_DELETED, 0) = 0
          AND (p_dot_xet_id IS NULL OR dot.ID = p_dot_xet_id)
          -- Ch? l?y PN ???c ??ng ý tha (TCDK_MA '10' = ???c tha bình th??ng, '11' = Tha tr??ng h?p ??c bi?t);
          -- các mã còn l?i (20-24) là b? lo?i/không ?? ?i?u ki?n. Có SO_QUYET_DINH_THA coi nh? ?ã ra Q? tha, c?ng tính là ??ng ý.
           AND dm_tt.TCDK_MA IN ('10', '11') 
        AND  t.SO_QUYET_DINH_THA IS NOT NULL

    ),
    tha_pn AS (
        SELECT DISTINCT PHAM_NHAN_ID FROM tha_one
    ),
    base_v AS (
        SELECT v.PHAM_NHAN_ID,
               v.HO_TEN,
               v.TEN_KHAC,
               v.NGUYEN_QUAN,
               v.NGAY_SINH,
               v.NAM_SINH,
               v.GIOI_TINH,
               v.DIA_CHI_THUONG_TRU,
               v.NOI_THUONG_TRU_DAY_DU,
               v.SO_TIEN_AN,
               v.TOI_DANH,
               v.NGAY_HET_AN,
               v.NGAY_BAT_AN_PHAT,
               v.AN_PHAT,
               v.MUC_AN_ID,
               v.PHAN_DOI_ID,
               v.CCCD,
               v.SO_TIEN_SU,
               v.TOI_DANH_ID,
               v.QUOC_TICH_ID,
               v.TOM_TAT_HANH_VI,
               v.CHI_TIET_HANH_VI,
               v.SO_QD_DIEU_CHUYEN,
               v.TRAI_GIAM,
               v.HOC_VAN,
               v.NGHE_NGHIEP,
               v.DAN_TOC,
               v.TON_GIAO,
               v.NOI_THA_VE_CU_TRU,
               v.NOI_THA_VE_CU_TRU_XA,
               v.NOI_THA_VE_CU_TRU_TINH,
               v.QUOC_TICH,
               v.SO_QD_THA,
               v.NGAY_QD_THA,
               v.CO_QUAN_QD_THA,
               v.TOA_QD_THA_DIA_PHUONG,
               v.NGAY_DEN_TRAI,
               v.PHAN_DOI,
               v.PHAN_TRAI,
               v.SO_DANH_BAN,
               v.CAN_CU_TUYEN_PHAT,
               v.DIEU,
               v.KHOAN,
               v.TT_SUC_KHOE_HIEN_TAI,
               v.TINH_TRANG_SUC_KHOE,
               v.THOI_GIAN_TAM_GIAM,
               v.THOI_GIAN_TAM_GIU,
               v.SO_HO_SO,
               v.TAI_PHAM,
               v.GHI_CHU,
               v.THA_GHI_CHU_DAC_BIET,
               v.SO_BAN_AN,
               v.NGAY_BAN_AN,
               v.TOA_XU_TEN,
               v.TOA_XU_DIA_PHUONG,
               v.LL_SO_GCN,
               v.NGAY_CAP_CCCD,
               v.NOI_CAP_CCCD,
               REPLACE(REPLACE(TRIM(CAST(COALESCE(v.TOI_DANH_ID, v.TOI_DANH) AS VARCHAR2(4000))), '[', ''), ']', '') AS toi_csv,
               -- Tính 1 l?n/PN (thay vì g?i l?i 2 l?n ? SELECT cu?i cho hinh_phat_bo_sung + hpbs_trang_thai)
               SUBSTR(NVL(FN_GET_LIET_KE_HPBS_CHI_TIET(v.PHAM_NHAN_ID), ''), 1, 2000) AS hpbs_chi_tiet_tt
        FROM tha_pn t
        INNER JOIN VW_PN_LAI_LICH_CHI_TIET v
            ON v.PHAM_NHAN_ID = t.PHAM_NHAN_ID
           AND NVL(v.IS_DELETED, 0) = 0
           AND (v_ll_trai_giam_id IS NULL OR v.TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    base_toi AS (
        SELECT bv.*,
               dm.TD_CHUONG AS td_chuong
        FROM base_v bv
        LEFT JOIN DM_TOI_DANHS dm
            -- REGEXP_SUBSTR(..., '[0-9]+', ...) ch? có th? tr? v? NULL ho?c chu?i toàn ch? s?,
            -- nên REGEXP_LIKE '^[0-9]+$' ki?m tra l?i là th?a — TO_NUMBER(NULL) ?ã t? tr? NULL.
            ON dm.ID = TO_NUMBER(REGEXP_SUBSTR(bv.toi_csv, '[0-9]+', 1, 1))
           AND NVL(dm.IS_DELETED, 0) = 0
    ),
    ds AS (
        SELECT
            t.PHAM_NHAN_ID,
            t.tha_co_dieu_kien_id,
            t.NGAY_XET,
            t.SO_QUYET_DINH_THA,
            t.NGAY_QUYET_DINH_THA,
            t.TOA_QUYET_DINH_THA_ID,
            t.DIA_PHUONG_QUYET_DINH_THA_ID,
            t.QQCT_PHIEU,
            t.NGAY_THA,
            t.NGAY_TRINH_DIEN,
            t.NHAN_XET,
            t.DANH_GIA_CAI_TAO_ID,
            -- Tính 1 l?n/tha_co_dieu_kien_id (thay vì g?i l?i 2 l?n ? SELECT cu?i cho
            -- thoi_gian_thu_thach + thoi_gian_thu_thach_chapt).
            -- NGAY_THA có th? ch?a c?p nh?t (ch?a ra Q? tha th?c t?) -> fallback NGAY_HET_AN
            -- (= VW_PN_LAI_LICH_CHI_TIET.NGAY_HET_AN, t?c rt.tha_ngay_het_han) ?? v?n tính ???c th?i gian th? thách.
            PKG_TINH_AN.FN_TINH_THOI_GIAN_THU_THACH_NAM_THANG_NGAY(t.PHAM_NHAN_ID, COALESCE(t.NGAY_THA, bt.NGAY_HET_AN)) AS thu_thach_tt,
            bt.HO_TEN,
            bt.TEN_KHAC,
            bt.NGUYEN_QUAN,
            bt.NGAY_SINH,
            bt.NAM_SINH,
            bt.GIOI_TINH,
            bt.DIA_CHI_THUONG_TRU,
            bt.NOI_THUONG_TRU_DAY_DU,
            bt.SO_TIEN_AN,
            bt.TOI_DANH,
            bt.NGAY_HET_AN,
            bt.NGAY_BAT_AN_PHAT,
            bt.AN_PHAT,
            bt.MUC_AN_ID,
            bt.PHAN_DOI_ID,
            bt.CCCD,
            bt.SO_TIEN_SU,
            bt.TOM_TAT_HANH_VI,
            bt.CHI_TIET_HANH_VI,
            bt.SO_QD_DIEU_CHUYEN,
            bt.TRAI_GIAM,
            bt.HOC_VAN,
            bt.NGHE_NGHIEP,
            bt.DAN_TOC,
            bt.TON_GIAO,
            bt.NOI_THA_VE_CU_TRU,
            bt.NOI_THA_VE_CU_TRU_XA,
            bt.NOI_THA_VE_CU_TRU_TINH,
            bt.QUOC_TICH,
            bt.SO_QD_THA,
            bt.NGAY_QD_THA,
            bt.CO_QUAN_QD_THA,
            bt.TOA_QD_THA_DIA_PHUONG,
            bt.NGAY_DEN_TRAI,
            bt.PHAN_DOI,
            bt.PHAN_TRAI,
            bt.SO_DANH_BAN,
            bt.CAN_CU_TUYEN_PHAT,
            bt.LL_SO_GCN,
            bt.NGAY_CAP_CCCD,
            bt.NOI_CAP_CCCD,
            bt.DIEU,
            bt.KHOAN,
            bt.TT_SUC_KHOE_HIEN_TAI,
            bt.TINH_TRANG_SUC_KHOE,
            bt.THOI_GIAN_TAM_GIAM,
            bt.THOI_GIAN_TAM_GIU,
            bt.SO_HO_SO,
            bt.TAI_PHAM,
            bt.GHI_CHU,
            bt.THA_GHI_CHU_DAC_BIET,
            bt.SO_BAN_AN,
            bt.NGAY_BAN_AN,
            bt.TOA_XU_TEN,
            bt.TOA_XU_DIA_PHUONG,
            bt.td_chuong,
            bt.toi_csv,
            bt.hpbs_chi_tiet_tt
        FROM tha_one t
        INNER JOIN base_toi bt ON bt.PHAM_NHAN_ID = t.PHAM_NHAN_ID
        WHERE (p_phan_doi_id IS NULL OR bt.PHAN_DOI_ID = p_phan_doi_id)
          AND (p_doi_tuong_id IS NULL
               OR (p_doi_tuong_id = 1 AND TRIM(CAST(NVL(bt.td_chuong, '') AS VARCHAR2(10))) = '13')
               OR (p_doi_tuong_id = 2 AND (bt.td_chuong IS NULL OR TRIM(CAST(NVL(bt.td_chuong, '') AS VARCHAR2(10))) <> '13')))
          AND (p_quoc_tich_id IS NULL
               OR (p_quoc_tich_id = 250 AND bt.quoc_tich = u'Vi\1ec7t Nam')
               OR (p_quoc_tich_id <> 250 AND (bt.quoc_tich IS NULL OR bt.quoc_tich <> u'Vi\1ec7t Nam' )))

          AND (p_tim_kiem IS NULL OR TRIM(CAST(p_tim_kiem AS VARCHAR2(2000))) = ''
               OR UPPER(NVL(CAST(bt.HO_TEN AS VARCHAR2(2000)), '')) LIKE v_tim_like
               OR UPPER(NVL(CAST(bt.CCCD AS VARCHAR2(200)), '')) LIKE v_tim_like)
    ),
    tien_an_agg AS (
        SELECT ids.pham_nhan_id,
               LISTAGG(NVL(TRIM(CAST(dm.TD_TEN AS VARCHAR2(500))), TO_CHAR(ids.td_id)), ', ')
                   WITHIN GROUP (ORDER BY ids.ord) AS toi_danh_ten
        FROM (
            SELECT z.pham_nhan_id,
                   CASE
                       WHEN REGEXP_LIKE(TRIM(REGEXP_SUBSTR(z.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
                       THEN TO_NUMBER(TRIM(REGEXP_SUBSTR(z.csv, '[^,]+', 1, LEVEL)))
                   END AS td_id,
                   LEVEL AS ord
            FROM (
                SELECT ta.PNTA_LAI_LICH_ID AS pham_nhan_id,
                       REPLACE(REPLACE(TRIM(CAST(ta.PNTA_TOI_DANH_ID AS VARCHAR2(4000))), '[', ''), ']', '') AS csv
                FROM PN_TIEN_AN ta
                WHERE NVL(ta.IS_DELETED, 0) = 0
                  AND ta.PNTA_LAI_LICH_ID IN (SELECT PHAM_NHAN_ID FROM tha_pn)
            ) z
            WHERE TRIM(z.csv) IS NOT NULL
            CONNECT BY LEVEL <= REGEXP_COUNT(z.csv, ',') + 1
              AND PRIOR z.pham_nhan_id = z.pham_nhan_id
              AND PRIOR SYS_GUID() IS NOT NULL
              AND REGEXP_SUBSTR(z.csv, '[^,]+', 1, LEVEL) IS NOT NULL
              AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(z.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
        ) ids
        LEFT JOIN DM_TOI_DANHS dm
            ON dm.ID = ids.td_id
           AND NVL(dm.IS_DELETED, 0) = 0
        WHERE ids.td_id IS NOT NULL
        GROUP BY ids.pham_nhan_id
    ),
    tien_su_agg AS (
        SELECT ts.TS_PN_LAI_LICH_ID AS pham_nhan_id,
               LISTAGG(TRIM(CAST(ts.TS_HANH_VI_VI_PHAM AS VARCHAR2(1000))), ', ')
                   WITHIN GROUP (ORDER BY ts.TS_THOI_GIAN) AS hanh_vi_ten
        FROM PN_TIEN_SUS ts
        WHERE NVL(ts.IS_DELETED, 0) = 0
          AND ts.TS_HANH_VI_VI_PHAM IS NOT NULL
          AND ts.TS_PN_LAI_LICH_ID IN (SELECT PHAM_NHAN_ID FROM tha_pn)
        GROUP BY ts.TS_PN_LAI_LICH_ID
    ),
    tinh_tiet_dac_biet_agg AS (
        SELECT ids.pham_nhan_id,
               LISTAGG(DISTINCT dm.GCDB_TEN, ', ')
                   WITHIN GROUP (ORDER BY dm.GCDB_TEN) AS tinh_tiet_dac_biet
        FROM (
            SELECT d.pham_nhan_id,
                   TO_NUMBER(REGEXP_SUBSTR(
                       REPLACE(REPLACE(d.THA_GHI_CHU_DAC_BIET, '[', ''), ']', ''),
                       '[0-9]+', 1, LEVEL
                   )) AS gcdb_id
            FROM ds d
            WHERE d.THA_GHI_CHU_DAC_BIET IS NOT NULL
            CONNECT BY LEVEL <= REGEXP_COUNT(
                           REPLACE(REPLACE(d.THA_GHI_CHU_DAC_BIET, '[', ''), ']', ''), ','
                       ) + 1
                   AND PRIOR d.pham_nhan_id = d.pham_nhan_id
                   AND PRIOR SYS_GUID() IS NOT NULL
        ) ids
        INNER JOIN DM_GHI_CHU_DAC_BIETS dm
            ON dm.ID = ids.gcdb_id
           AND NVL(dm.IS_DELETED, 0) = 0
        GROUP BY ids.pham_nhan_id
    ),
    ranked AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY d.HO_TEN, d.NGAY_XET DESC NULLS LAST) AS rn_all,
            COUNT(*) OVER () AS total_count,
            d.PHAM_NHAN_ID,
            d.tha_co_dieu_kien_id,
            d.NGAY_XET,
            d.SO_QUYET_DINH_THA,
            d.NGAY_QUYET_DINH_THA,
            d.TOA_QUYET_DINH_THA_ID,
            d.DIA_PHUONG_QUYET_DINH_THA_ID,
            d.QQCT_PHIEU,
            d.NGAY_THA,
            d.NGAY_TRINH_DIEN,
            d.NHAN_XET,
            d.DANH_GIA_CAI_TAO_ID,
            d.thu_thach_tt,
            d.HO_TEN,
            d.TEN_KHAC,
            d.NGUYEN_QUAN,
            d.NGAY_SINH,
            d.NAM_SINH,
            d.GIOI_TINH,
            d.DIA_CHI_THUONG_TRU,
            d.NOI_THUONG_TRU_DAY_DU,
            d.SO_TIEN_AN,
            d.SO_TIEN_SU,
            d.CCCD,
            d.TOI_DANH,
            d.NGAY_HET_AN,
            d.NGAY_BAT_AN_PHAT,
            d.AN_PHAT,
            d.MUC_AN_ID,
            d.TOM_TAT_HANH_VI,
            d.CHI_TIET_HANH_VI,
            d.SO_QD_DIEU_CHUYEN,
            d.TRAI_GIAM,
            d.HOC_VAN,
            d.NGHE_NGHIEP,
            d.DAN_TOC,
            d.TON_GIAO,
            d.NOI_THA_VE_CU_TRU,
            d.NOI_THA_VE_CU_TRU_XA,
            d.NOI_THA_VE_CU_TRU_TINH,
            d.QUOC_TICH,
            d.SO_QD_THA,
            d.NGAY_QD_THA,
            d.CO_QUAN_QD_THA,
            d.TOA_QD_THA_DIA_PHUONG,
            d.NGAY_DEN_TRAI,
            d.PHAN_DOI,
            d.PHAN_TRAI,
            d.SO_DANH_BAN,
            d.CAN_CU_TUYEN_PHAT,
            d.DIEU,
            d.KHOAN,
            d.LL_SO_GCN,
            d.NGAY_CAP_CCCD,
            d.NOI_CAP_CCCD,
            d.TT_SUC_KHOE_HIEN_TAI,
            d.TINH_TRANG_SUC_KHOE,
            d.THOI_GIAN_TAM_GIAM,
            d.THOI_GIAN_TAM_GIU,
            d.SO_HO_SO,
            d.TAI_PHAM,
            d.GHI_CHU,
            d.THA_GHI_CHU_DAC_BIET,
            d.SO_BAN_AN,
            d.NGAY_BAN_AN,
            d.TOA_XU_TEN,
            d.TOA_XU_DIA_PHUONG,
            d.toi_csv,
            d.hpbs_chi_tiet_tt
        FROM ds d
    )
    SELECT
        z.rn_all AS stt,
        z.PHAM_NHAN_ID AS pham_nhan_id,
        z.tha_co_dieu_kien_id AS tha_co_dieu_kien_id,
        NVL(TRIM(cq.CQ_TEN), '') AS ten_toa_an,
        NVL(TRIM(z.SO_QUYET_DINH_THA), '') AS so_quyet_dinh,
        CASE WHEN z.NGAY_QUYET_DINH_THA IS NOT NULL THEN TO_CHAR(TRUNC(CAST(z.NGAY_QUYET_DINH_THA AS DATE)), 'DD/MM/YYYY') ELSE NULL END AS ngay_quyet_dinh,
        NULLIF(TRIM(dp.TTP_TEN), u'') AS dia_phuong_quyet_dinh_tha,
        NVL(TRIM(z.SO_QUYET_DINH_THA), '') AS SO_QD_THA_CO_DK,
        CASE WHEN z.NGAY_QUYET_DINH_THA IS NOT NULL THEN TO_CHAR(TRUNC(CAST(z.NGAY_QUYET_DINH_THA AS DATE)), 'DD/MM/YYYY') ELSE NULL END AS NGAY_TOA_QD_THA_CO_DK,
        NVL(TRIM(cq.CQ_TEN), '') AS TOA_QD_THA_CO_DK,
        NULLIF(TRIM(dp.TTP_TEN), u'') AS DIA_PHUONG_TOA_QD_THA_CO_DK,
        SUBSTR(TRIM('S? ' || NVL(TRIM(z.SO_QUYET_DINH_THA), '')
            || CASE WHEN z.NGAY_QUYET_DINH_THA IS NOT NULL THEN ' ngày ' || TO_CHAR(TRUNC(CAST(z.NGAY_QUYET_DINH_THA AS DATE)), 'DD/MM/YYYY') ELSE '' END
            || CASE WHEN cq.CQ_TEN IS NOT NULL THEN ' — ' || TRIM(cq.CQ_TEN) ELSE u'' END), 1, 4000) AS thong_tin_qd_tha_tu,
        TO_CHAR(TRUNC(SYSDATE), 'DD/MM/YYYY') AS ngay_lap_bao_cao,
        CAST(NULL AS VARCHAR2(4000)) AS chu_tich_hoi_dong,
        CAST(NULL AS VARCHAR2(4000)) AS cac_tham_phan,
        CAST(NULL AS VARCHAR2(4000)) AS thu_ky_phien_hop,
        CAST(NULL AS VARCHAR2(4000)) AS dai_dien_vks,
        CAST(NULL AS VARCHAR2(4000)) AS dai_dien_trai_giam,
        NULLIF(TRIM(CAST(z.SO_QD_DIEU_CHUYEN AS VARCHAR2(500))), '') so_van_ban_de_nghi,
        NVL(TRIM(z.TOM_TAT_HANH_VI), '') AS tom_tat_hanh_vi,
        NVL(TRIM(z.CHI_TIET_HANH_VI), '') AS chi_tiet_hanh_vi,
        COALESCE(
            NULLIF(TRIM(ma.MA_TEN_CHI_TIEU), u''),
            NULLIF(TRIM(z.AN_PHAT), u'')
        ) AS muc_an_phat,
        NVL(TRIM(z.HO_TEN), '') AS ho_ten,
        NVL(TRIM(z.TEN_KHAC), '') AS ho_ten_khac,
        CASE
            WHEN z.NGAY_SINH IS NOT NULL AND REGEXP_LIKE(TRIM(z.NGAY_SINH), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(z.NGAY_SINH), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN z.NAM_SINH IS NOT NULL AND z.NAM_SINH > 0 THEN TO_CHAR(z.NAM_SINH)
            WHEN z.NGAY_SINH IS NOT NULL THEN TRIM(CAST(z.NGAY_SINH AS VARCHAR2(100)))
            ELSE NULL
        END AS nam_sinh,
        NVL(TRIM(z.GIOI_TINH), '') AS gioi_tinh,
        NVL(TRIM(z.NGUYEN_QUAN), '') AS nguyen_quan,
        NVL(TRIM(COALESCE(z.NOI_THUONG_TRU_DAY_DU, z.DIA_CHI_THUONG_TRU)), '') AS noi_dktt,
        NVL(TRIM(z.NGHE_NGHIEP), '') AS nghe_nghiep,
        NVL(TRIM(z.HOC_VAN), '') AS trinh_do_van_hoa,
        NVL(TRIM(z.DAN_TOC), '') AS dan_toc,
        NVL(TRIM(z.TON_GIAO), '') AS ton_giao,
        NVL(TRIM(z.thu_thach_tt), '') AS thoi_gian_thu_thach,
        CASE
            WHEN z.NOI_THA_VE_CU_TRU_XA IS NOT NULL OR z.NOI_THA_VE_CU_TRU_TINH IS NOT NULL THEN
                TRIM('UBND ' || NVL(TRIM(z.NOI_THA_VE_CU_TRU_XA), '')
                     || CASE WHEN z.NOI_THA_VE_CU_TRU_TINH IS NOT NULL THEN ', ' || TRIM(z.NOI_THA_VE_CU_TRU_TINH) ELSE u'' END)
            ELSE u''
        END AS ubnd_giam_sat,
        CAST(NULL AS VARCHAR2(500)) AS nguoi_ky_ten,
        CAST(NULL AS VARCHAR2(500)) AS chuc_vu_nguoi_ky,
        CASE
            WHEN COALESCE(z.NGAY_THA, v_tha.THA_NGAY_HET_HAN) IS NOT NULL
            THEN TO_CHAR(TRUNC(CAST(COALESCE(z.NGAY_THA, v_tha.THA_NGAY_HET_HAN) AS DATE)), 'DD/MM/YYYY')
            ELSE NULL
        END AS ngay_tha,
        CASE WHEN z.NGAY_TRINH_DIEN IS NOT NULL THEN TO_CHAR(TRUNC(CAST(z.NGAY_TRINH_DIEN AS DATE)), 'DD/MM/YYYY') ELSE NULL END AS ngay_trinh_dien,
         CASE
            WHEN z.NOI_THA_VE_CU_TRU_XA IS NOT NULL OR z.NOI_THA_VE_CU_TRU_TINH IS NOT NULL THEN
                TRIM('UBND ' || NVL(TRIM(z.NOI_THA_VE_CU_TRU_XA), '')
                     || CASE WHEN z.NOI_THA_VE_CU_TRU_TINH IS NOT NULL THEN ', ' || TRIM(z.NOI_THA_VE_CU_TRU_TINH) ELSE u'' END)
            ELSE u''
        END AS noi_trinh_dien,
        NVL(TRIM(z.QUOC_TICH), '') AS quoc_tich,
        SUBSTR(TRIM(NVL(z.NOI_THA_VE_CU_TRU, '')
            || CASE WHEN z.NOI_THA_VE_CU_TRU_XA IS NOT NULL THEN ', ' || TRIM(z.NOI_THA_VE_CU_TRU_XA) ELSE u'' END
            || CASE WHEN z.NOI_THA_VE_CU_TRU_TINH IS NOT NULL THEN ', ' || TRIM(z.NOI_THA_VE_CU_TRU_TINH) ELSE u'' END), 1, 2000) AS noi_tha_ve_cu_tru,
         z.NOI_THA_VE_CU_TRU_XA AS NOI_THA_VE_CU_TRU_XA ,
         z.NOI_THA_VE_CU_TRU_TINH AS NOI_THA_VE_CU_TRU_TINH,
        COALESCE(
            NULLIF(TRIM(z.NOI_THUONG_TRU_DAY_DU), u''),
            SUBSTR(TRIM(NVL(z.NOI_THA_VE_CU_TRU, '')
                || CASE WHEN z.NOI_THA_VE_CU_TRU_XA IS NOT NULL THEN ', ' || TRIM(z.NOI_THA_VE_CU_TRU_XA) ELSE u'' END
                || CASE WHEN z.NOI_THA_VE_CU_TRU_TINH IS NOT NULL THEN ', ' || TRIM(z.NOI_THA_VE_CU_TRU_TINH) ELSE u'' END), 1, 2000)
        ) AS noi_chap_hanh_thu_thach,
        NVL(TRIM(z.SO_QD_THA), '') AS so_qd_tha,
        CASE WHEN z.NGAY_QD_THA IS NOT NULL THEN TO_CHAR(z.NGAY_QD_THA, 'DD/MM/YYYY') ELSE NULL END AS ngay_qd_tha,
        NVL(TRIM(z.CO_QUAN_QD_THA), '') AS co_quan_qd_tha,
        NVL(TRIM(z.TOA_QD_THA_DIA_PHUONG), '') AS toa_qd_tha_dia_phuong,
        SUBSTR(TRIM('S? ' || NVL(TRIM(z.SO_QD_THA), '')
            || CASE WHEN z.NGAY_QD_THA IS NOT NULL THEN ' ngày ' || TO_CHAR(z.NGAY_QD_THA, 'DD/MM/YYYY') ELSE '' END
            || CASE WHEN z.CO_QUAN_QD_THA IS NOT NULL OR z.TOA_QD_THA_DIA_PHUONG IS NOT NULL THEN ' — ' || TRIM(NVL(z.CO_QUAN_QD_THA, '')
                || CASE WHEN z.TOA_QD_THA_DIA_PHUONG IS NOT NULL THEN ', ' || TRIM(z.TOA_QD_THA_DIA_PHUONG) ELSE u'' END) ELSE u'' END), 1, 4000) AS thong_tin_qd_thi_hanh,
        CASE WHEN z.NGAY_DEN_TRAI IS NOT NULL THEN TO_CHAR(z.NGAY_DEN_TRAI, 'DD/MM/YYYY') ELSE NULL END AS ngay_den_trai,
		SUBSTR( TRIM( NVL(z.PHAN_DOI, '') || CASE   WHEN z.PHAN_DOI IS NOT NULL AND z.PHAN_TRAI IS NOT NULL    THEN ', '   ELSE NULL  END || NVL(z.PHAN_TRAI, '')),1, 2000) AS phan_doi_phan_trai,
        NVL(TRIM(z.SO_DANH_BAN), '') AS so_danh_ban,
        CASE WHEN v_tha.THA_NGAY_LAP_DANH_BAN IS NOT NULL THEN TO_CHAR(v_tha.THA_NGAY_LAP_DANH_BAN, 'DD/MM/YYYY') ELSE NULL END AS ngay_lap_danh_ban,
        NVL(TRIM(z.SO_HO_SO), '') AS so_ho_so,
        NVL(TRIM(z.THOI_GIAN_TAM_GIAM), '') AS thoi_gian_tam_giam,
        NVL(TRIM(z.THOI_GIAN_TAM_GIU), '') AS thoi_gian_tam_giu,
        NVL(TRIM(z.SO_TIEN_AN), '') AS so_tien_an,
        NVL(TRIM(z.CAN_CU_TUYEN_PHAT), '') AS can_cu_tuyen_phat,
        NVL(TRIM(z.DIEU), '') AS dieu,
        NVL(TRIM(z.KHOAN), '') AS khoan,
        NVL(TRIM(CAST(z.NHAN_XET AS VARCHAR2(4000))), '') AS nhan_xet_tha,
        SUBSTR(TRIM(NVL(TRIM(CAST(z.NHAN_XET AS VARCHAR2(4000))), '')
            || CHR(10) || NVL(SUBSTR(NVL(FN_TONG_HOP_KET_QUA_CAI_TAO(z.PHAM_NHAN_ID, EXTRACT(YEAR FROM NVL(z.NGAY_XET, SYSDATE))), ''), 1, 2000), '')
            || CHR(10) || NVL(TRIM(xlct.XLCT_TEN), '')), 1, 4000) AS noi_dung_nhan_xet_bao_cao,
        NVL(FN_GHI_CHU_PHAM_NHAN(z.PHAM_NHAN_ID), '') AS ghi_chu_rieng_dm,
        z.hpbs_chi_tiet_tt AS hinh_phat_bo_sung,
        CASE
            WHEN NULLIF(TRIM(z.hpbs_chi_tiet_tt), '') IS NULL THEN 'Không'
            ELSE 'Có'
        END AS hpbs_trang_thai,
        NULLIF(TRIM(CAST(z.QQCT_PHIEU AS VARCHAR2(500))), '') AS xep_loai_chap_hanh,
        NVL(TRIM(xlct.XLCT_TEN), '') AS danh_gia_xlct_ten,
        NVL(TRIM(z.TT_SUC_KHOE_HIEN_TAI), '') AS tt_suc_khoe_hien_tai,
        NVL(TRIM(z.TINH_TRANG_SUC_KHOE), '') AS tinh_trang_suc_khoe,
        NVL(ttdb.tinh_tiet_dac_biet, '') AS tinh_tiet_dac_biet,
        NVL(TRIM(z.TAI_PHAM), '') AS tai_pham,
        NVL(TRIM(z.GHI_CHU), '') AS ghi_chu_lai_lich,
        CAST(NULL AS VARCHAR2(500)) AS tai_san_ban_giao,
        CAST(NULL AS VARCHAR2(50)) AS ngay_han_chot_bao_cao,
        NVL(TRIM(PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(z.PHAM_NHAN_ID, z.NGAY_XET)), '') AS thoi_gian_da_chap_hanh,
        NVL(TRIM(z.TRAI_GIAM), '') AS ten_trai_giam,
        CAST(NULL AS VARCHAR2(500)) AS dia_diem_lap_bao_cao,
        NVL(TRIM(PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(z.PHAM_NHAN_ID, z.NGAY_XET)), '') AS thoi_gian_con_lai,
        NVL(TRIM(z.SO_BAN_AN), '') AS so_ban_an,
        CASE WHEN z.NGAY_BAN_AN IS NOT NULL THEN TO_CHAR(z.NGAY_BAN_AN, 'DD/MM/YYYY') ELSE NULL END AS ngay_ban_an,
        z.TOA_XU_TEN  AS toa_xu,
        z.TOA_XU_DIA_PHUONG    AS toa_xu_dia_phuong,
        SUBSTR(TRIM('S? ' || NVL(TRIM(z.SO_BAN_AN), '')
            || CASE WHEN z.NGAY_BAN_AN IS NOT NULL THEN ' ngày ' || TO_CHAR(z.NGAY_BAN_AN, 'DD/MM/YYYY') ELSE '' END
            || CASE WHEN z.TOA_XU_TEN IS NOT NULL OR z.TOA_XU_DIA_PHUONG IS NOT NULL THEN ' — ' || TRIM(NVL(z.TOA_XU_TEN, '')
                || CASE WHEN z.TOA_XU_DIA_PHUONG IS NOT NULL THEN ', ' || TRIM(z.TOA_XU_DIA_PHUONG) ELSE u'' END) ELSE u'' END), 1, 4000) AS thong_tin_ban_an,
        NVL(TRIM(COALESCE(z.NOI_THUONG_TRU_DAY_DU, z.DIA_CHI_THUONG_TRU)), '') AS dia_chi_thuong_tru,
        NVL(TRIM(z.SO_TIEN_SU), '') AS so_tien_su,
        NVL(z.TOI_DANH, u'Ch\01b0a x\00e1c \0111\1ecbnh') AS toi_danh,
        CASE WHEN z.NGAY_BAT_AN_PHAT IS NOT NULL THEN TO_CHAR(z.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') ELSE NULL END AS ngay_bat,
        NVL(TRIM(z.AN_PHAT), '') AS an_phat,
        PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(z.PHAM_NHAN_ID)  AS giam_an,
        NVL(TRIM(z.thu_thach_tt), u'') AS thoi_gian_thu_thach_chapt,
        CAST(NULL AS VARCHAR2(4000)) AS nhan_xet_qua_trinh_chap_hanh_an,
        z.LL_SO_GCN AS SO_GCN,
        z.total_count AS total_count,
        NVL(z.CCCD, '') AS SO_CCCD,
        NVL(TRIM( TO_CHAR(z.NGAY_CAP_CCCD, 'DD/MM/YYYY') ), '') AS NGAY_CAP_CCCD,
        NVL(TRIM(z.NOI_CAP_CCCD), '') AS NOI_CAP_CCCD,
        FN_CONG_TAM_GIAM_TAM_GIU(z.THOI_GIAN_TAM_GIAM, z.THOI_GIAN_TAM_GIU) AS THOI_GIAN_TAM_GIAM_GIU,
        NVL(z.SO_TIEN_AN, '') || CASE WHEN taa.toi_danh_ten IS NOT NULL THEN ': ' || taa.toi_danh_ten ELSE '' END AS TIEN_AN,
        NVL(z.SO_TIEN_SU, '') || CASE WHEN tsa.hanh_vi_ten IS NOT NULL THEN ': ' || tsa.hanh_vi_ten ELSE '' END AS TIEN_SU
    FROM ranked z
    LEFT JOIN tien_an_agg taa ON taa.pham_nhan_id = z.PHAM_NHAN_ID
    LEFT JOIN tien_su_agg tsa ON tsa.pham_nhan_id = z.PHAM_NHAN_ID
    LEFT JOIN tinh_tiet_dac_biet_agg ttdb ON ttdb.pham_nhan_id = z.PHAM_NHAN_ID
    LEFT JOIN DM_CO_QUANS cq
        ON cq.ID = z.TOA_QUYET_DINH_THA_ID
       AND NVL(cq.IS_DELETED, 0) = 0
    LEFT JOIN dm_tinh_thanh_pho dp
        ON dp.ID = z.DIA_PHUONG_QUYET_DINH_THA_ID
       AND NVL(dp.IS_DELETED, 0) = 0
    LEFT JOIN DM_MUC_ANS ma
        ON ma.ID = z.MUC_AN_ID
       AND NVL(ma.IS_DELETED, 0) = 0
    LEFT JOIN V_PN_THI_HANH_AN_TOI_DANH v_tha
        ON v_tha.THA_PNLAI_LICH_ID = z.PHAM_NHAN_ID
    LEFT JOIN DM_XEP_LOAI_CAI_TAOS xlct
        ON xlct.ID = z.DANH_GIA_CAI_TAO_ID
       AND NVL(xlct.IS_DELETED, 0) = 0
    WHERE z.rn_all > v_skip
      AND (v_limit = 0 OR z.rn_all <= v_skip + v_limit)
    ORDER BY z.rn_all;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y danh sách in quy?t ??nh c?a Tòa: ' || SQLERRM);

