BEGIN
    SP_GET_THA_IN_QUYET_DINH_CUA_TOA(
        p_dot_xet_id     => NULL,
        p_phan_doi_id    => NULL,
        p_doi_tuong_id   => NULL,
        p_quoc_tich_id   => NULL,
        p_tim_kiem       => NULL,
        p_ma_trai_giam   => NULL,
        p_maxresultcount => 25,
        p_skipcount      => 0
    );
END;
*/
