--------------------------------------------------------
--  DDL for Procedure SP_GET_THE_BUONG_GIAM
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THE_BUONG_GIAM" (
    p_pham_nhan_ids IN VARCHAR2
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        WITH id_list AS (
            SELECT 
                TO_NUMBER(REGEXP_SUBSTR(p_pham_nhan_ids, '[^,]+', 1, LEVEL)) AS val,
                LEVEL AS pos
            FROM DUAL
            CONNECT BY REGEXP_SUBSTR(p_pham_nhan_ids, '[^,]+', 1, LEVEL) IS NOT NULL
        )
        SELECT
            ll.LL_HO_TEN AS "HoTen",
            SUBSTR(ll.LL_NGAY_SINH, -4) AS "NamSinh",
            -- S? d?ng LTRIM ?? xóa d?u ph?y ? ??u chu?i n?u có
            LTRIM(
                (TO_NCHAR(NVL(ll.LL_DIA_CHI_THUONG_TRU, '')) || 
                 CASE WHEN xp.XP_TEN IS NOT NULL THEN TO_NCHAR(',') || TO_NCHAR(xp.XP_TEN) ELSE TO_NCHAR('') END || 
                 CASE WHEN ttp.TTP_TEN IS NOT NULL THEN TO_NCHAR(',') || TO_NCHAR(ttp.TTP_TEN) ELSE TO_NCHAR('') END),
                ','
            ) AS "DiaChiThuongTru",
            td_agg.TOI_DANH AS "ToiDanh",
            ptha.THA_NGAY_BAT AS "NgayBat",
            ptha.THA_AN_PHAT AS "AnPhat",
            TO_CHAR(ptha.THA_NGAY_HET_HAN, 'DD/MM/YYYY') AS "NgayRaTrai"
        FROM id_list i
        JOIN PN_LAI_LICHS ll ON i.val = ll.ID
        LEFT JOIN DM_XA_PHUONG xp ON ll.LL_DIA_CHI_THUONG_TRU_WARD = xp.ID
        LEFT JOIN DM_TINH_THANH_PHO ttp ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = ttp.ID
        LEFT JOIN PN_THI_HANH_AN ptha
            ON ll.ID = ptha.THA_PNLAI_LICH_ID
        LEFT JOIN (
            SELECT
                tha.THA_PNLAI_LICH_ID AS LAI_LICH_ID,
                LISTAGG(td.TD_TEN, ', ') WITHIN GROUP (ORDER BY td.TD_TEN) AS TOI_DANH
            FROM PN_THI_HANH_AN tha
            CROSS APPLY JSON_TABLE(
                tha.THA_TOI_DANH,
                '$[*]' COLUMNS (
                    TOI_DANH_ID NUMBER PATH '$'
                )
            ) jt
            JOIN DM_TOI_DANHS td
                ON td.ID = jt.TOI_DANH_ID
            GROUP BY tha.THA_PNLAI_LICH_ID
        ) td_agg
            ON ll.ID = td_agg.LAI_LICH_ID
        ORDER BY i.pos;

    DBMS_SQL.RETURN_RESULT(c1);
END;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_BAO_HET_THOI_HAN_TDC_PT88
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_BAO_HET_THOI_HAN_TDC_PT88" (
    p_tdc_id      IN NUMBER DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        WITH td_one AS (
            SELECT td.*
            FROM qlpn.tam_dinh_chis td
            WHERE NVL(td.is_deleted, 0) = 0
              AND (p_tdc_id IS NULL OR td.id = p_tdc_id)
        ),
        vw_one AS (
            SELECT v.*
            FROM qlpn.vw_pn_lai_lich_chi_tiet v
            WHERE NVL(v.is_deleted, 0) = 0
              AND v.pham_nhan_id IN (SELECT t.pham_nhan_id FROM td_one t)
        )
        SELECT
            NVL(td.so_quyet_dinh, '') AS SO_QD_TDC,
            TO_CHAR(td.ngay_quyet_dinh, 'DD/MM/YYYY') AS NGAY_QD_TDC,
            NVL(cq_tdc.cq_ten, '') AS TOA_AN_RA_QD_TDC,
--            v.trai_giam AS CO_QUAN_RA_THONG_BAO,
            v.ho_ten AS HO_TEN,
            v.gioi_tinh AS GIOI_TINH,
            v.ngay_sinh AS NGAY_SINH,
            v.ten_khac AS HO_TEN_KHAC,
            v.nguyen_quan AS QUE_QUAN,
            NVL(v.noi_thuong_tru_day_du, v.dia_chi_thuong_tru) AS NOI_THUONG_TRU,
            NVL(v.cccd, v.ho_chieu) AS SO_CCCD_CC_HO_CHIEU,
            TO_CHAR(ngay_cap_cccd, 'DD/MM/YYYY')  AS NGAY_CAP,
            noi_cap_cccd AS NOI_CAP,
            v.toi_danh AS TOI_DANH,
            TO_CHAR(v.ngay_bat_an_phat, 'DD/MM/YYYY') AS NGAY_BAT,
            v.an_phat AS AN_PHAT,
            v.so_ban_an AS SO_BAN_AN,
            TO_CHAR(v.ngay_ban_an, 'DD/MM/YYYY') AS NGAY_BAN_AN,
            v.toa_xu_ten AS TOA_XU,
            v.toa_xu_dia_phuong AS DIA_PHUONG_XU,
            v.so_qd_tha AS SO_QD_THA,
            TO_CHAR(v.ngay_qd_tha, 'DD/MM/YYYY') AS NGAY_QD_THA,
            v.co_quan_qd_tha AS TOA_QD_THA,
            v.toa_qd_tha_dia_phuong AS DIA_PHUONG_QD_THA,
            NVL(mtg.mtg_title, '') AS THOI_HAN_TAM_DINH_CHI,
            TO_CHAR(td.tu_ngay, 'DD/MM/YYYY') AS TU_NGAY_TDC,
            TO_CHAR(
                CASE
                    WHEN td.tu_ngay IS NULL THEN NULL
                    ELSE ADD_MONTHS(
                             CAST(td.tu_ngay AS DATE),
                             NVL(mtg.mtg_nam, 0) * 12 + NVL(mtg.mtg_thang, 0)
                         ) + NVL(mtg.mtg_ngay, 0)
                END,
                'DD/MM/YYYY'
            ) AS DEN_NGAY_TDC,
            NVL(ttp_qd_tdc.ttp_ten, '') AS DIA_PHUONG_QD_TDC,
            NVL(ldtdc.ldtdc_ten, NVL(td.ly_do_chi_tiet, '')) AS LY_DO_TDC,
            NVL(td.noi_ve_xa, '') AS NOI_VE_CU_TRU_CHI_TIET,
            NVL(ttp_noi_ve.ttp_ten, '') AS VE_CU_TRU_TAI,
            TO_CHAR(
                CASE
                    WHEN td.tu_ngay IS NULL THEN NULL
                    ELSE ADD_MONTHS(
                             CAST(td.tu_ngay AS DATE),
                             NVL(mtg.mtg_nam, 0) * 12 + NVL(mtg.mtg_thang, 0)
                         ) + NVL(mtg.mtg_ngay, 0)
                END,
                'DD/MM/YYYY'
            ) AS NGAY_HET_HAN_TDC
        FROM td_one td
        INNER JOIN vw_one v
                ON v.pham_nhan_id = td.pham_nhan_id
        LEFT JOIN qlpn.dm_ma_thoi_gians mtg
               ON mtg.id = td.thoi_han_id
              AND NVL(mtg.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_ly_do_tam_dinh_chies ldtdc
               ON ldtdc.id = td.ly_do_suc_khoe_id
              AND NVL(ldtdc.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_tinh_thanh_pho ttp_noi_ve
               ON ttp_noi_ve.id = td.noi_ve_dia_phuong_id
              AND NVL(ttp_noi_ve.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_co_quans cq_tdc
               ON cq_tdc.id = td.toa_quyet_dinh_id
              AND NVL(cq_tdc.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_tinh_thanh_pho ttp_qd_tdc
               ON ttp_qd_tdc.id = td.dia_phuong_id
              AND NVL(ttp_qd_tdc.is_deleted, 0) = 0;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_THONG_BAO_HET_THOI_HAN_TDC_PT88: ' || SQLERRM);
END SP_GET_THONG_BAO_HET_THOI_HAN_TDC_PT88;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_BAO_TDC_PT87
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_BAO_TDC_PT87" (
    p_tdc_id   IN NUMBER DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        WITH td_one AS (
            SELECT td.*
            FROM qlpn.tam_dinh_chis td
            WHERE NVL(td.is_deleted, 0) = 0
              AND (p_tdc_id IS NULL OR td.id = p_tdc_id)
        ),
        vw_one AS (
            SELECT v.*
            FROM qlpn.vw_pn_lai_lich_chi_tiet v
            WHERE NVL(v.is_deleted, 0) = 0
              AND v.pham_nhan_id IN (SELECT t.pham_nhan_id FROM td_one t)
        ),
        than_nhan_one AS (
            SELECT *
            FROM (
                SELECT
                    tn.pham_nhan_id,
                    tn.ho_ten_than_nhan,
                    tn.cccd,
                    qh.qhvpn_ten AS quan_he,
                    tn.noi_o,
                    tn.dien_thoai,
                    ROW_NUMBER() OVER (
                        PARTITION BY tn.pham_nhan_id
                        ORDER BY CASE
                                     WHEN NVL(tn.thong_bao, 0) = 1 THEN 0
                                     ELSE 1
                                 END,
                                 tn.creation_time DESC NULLS LAST,
                                 tn.id DESC
                    ) AS rn
                FROM qlpn.than_nhan_nguoi_thans tn
                LEFT JOIN qlpn.dm_quan_he_voi_pham_nhans qh
                       ON qh.id = tn.quan_he_id
                      AND NVL(qh.is_deleted, 0) = 0
                WHERE tn.pham_nhan_id IN (SELECT t.pham_nhan_id FROM td_one t)
                  AND NVL(tn.is_deleted, 0) = 0
            )
            WHERE rn = 1
        )
        SELECT
            v.ho_ten AS HO_TEN,
            v.gioi_tinh AS GIOI_TINH,
            v.ngay_sinh AS NGAY_SINH,
            v.ten_khac AS HO_TEN_KHAC,
            v.nguyen_quan AS QUE_QUAN,
            NVL(v.noi_thuong_tru_day_du, v.dia_chi_thuong_tru) AS NOI_THUONG_TRU,
            NVL(v.cccd, v.ho_chieu) AS SO_CCCD_CC_HO_CHIEU,
            TO_CHAR(ngay_cap_cccd, 'DD/MM/YYYY')  AS NGAY_CAP,
            noi_cap_cccd AS NOI_CAP,
            v.toi_danh AS TOI_DANH,
            TO_CHAR(v.ngay_bat_an_phat, 'DD/MM/YYYY') AS NGAY_BAT,
            v.an_phat AS AN_PHAT,
            v.so_ban_an AS SO_BAN_AN,
            TO_CHAR(v.ngay_ban_an, 'DD/MM/YYYY') AS NGAY_BAN_AN,
            v.toa_xu_ten AS TOA_XU,
            v.toa_xu_dia_phuong AS DIA_PHUONG_XU,
            v.so_qd_tha AS SO_QD_THA,
            TO_CHAR(v.ngay_qd_tha, 'DD/MM/YYYY') AS NGAY_QD_THA,
            v.co_quan_qd_tha AS TOA_QD_THA,
            v.toa_qd_tha_dia_phuong AS DIA_PHUONG_QD_THA,
            NVL(mtg.mtg_title, '') AS THOI_HAN_TAM_DINH_CHI,
            TO_CHAR(td.tu_ngay, 'DD/MM/YYYY') AS TU_NGAY_TAM_DINH_CHI,
            TO_CHAR(td.ngay_lai, 'DD/MM/YYYY') AS DEN_NGAY_TAM_DINH_CHI,
            NVL(td.so_quyet_dinh, '') AS SO_QD_TDC,
            TO_CHAR(td.ngay_quyet_dinh, 'DD/MM/YYYY') AS NGAY_QD_TDC,
            NVL(cq_tdc.cq_ten, '') AS TOA_QD_TDC,
            NVL(ttp_qd_tdc.ttp_ten, '') AS DIA_PHUONG_QD_TDC,
            NVL(ldtdc.ldtdc_ten, NVL(td.ly_do_chi_tiet, '')) AS LY_DO_TAM_DINH_CHI,
            NVL(td.noi_ve_xa, '') AS NOI_VE_CU_TRU_CHI_TIET,
            NVL(ttp_noi_ve.ttp_ten, '') AS VE_CU_TRU_TAI,
            tn.ho_ten_than_nhan AS HO_TEN_GIA_DINH,
            tn.noi_o AS NOI_THUONG_TRU_DAI_DIEN,
            tn.noi_o AS NOI_O_HIEN_NAY_DAI_DIEN,
            tn.quan_he AS QUAN_HE_VOI_PHAM_NHAN,
            tn.dien_thoai AS SO_DIEN_THOAI_LIEN_LAC
        FROM td_one td
        INNER JOIN vw_one v
                ON v.pham_nhan_id = td.pham_nhan_id
        LEFT JOIN than_nhan_one tn
               ON tn.pham_nhan_id = td.pham_nhan_id
        LEFT JOIN qlpn.dm_ma_thoi_gians mtg
               ON mtg.id = td.thoi_han_id
              AND NVL(mtg.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_ly_do_tam_dinh_chies ldtdc
               ON ldtdc.id = td.ly_do_suc_khoe_id
              AND NVL(ldtdc.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_tinh_thanh_pho ttp_noi_ve
               ON ttp_noi_ve.id = td.noi_ve_dia_phuong_id
              AND NVL(ttp_noi_ve.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_co_quans cq_tdc
               ON cq_tdc.id = td.toa_quyet_dinh_id
              AND NVL(cq_tdc.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_tinh_thanh_pho ttp_qd_tdc
               ON ttp_qd_tdc.id = td.dia_phuong_id
              AND NVL(ttp_qd_tdc.is_deleted, 0) = 0;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_THONG_BAO_TDC_PT87: ' || SQLERRM);
END SP_GET_THONG_BAO_TDC_PT87;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_AN_GIAM
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_AN_GIAM" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

        selected_toi_danh_filter AS (
            SELECT TRIM(REGEXP_SUBSTR(
                            REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                            '[^,]+', 1, LEVEL)) AS ma_loc
            FROM DUAL
            CONNECT BY LEVEL <= REGEXP_COUNT(
                                    REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                    ',') + 1),

        chung_than_ids AS (
            SELECT dmtg.ID
            FROM DM_MA_THOI_GIANS dmtg
            WHERE dmtg.MTG_MA IN ('911000', '912000')
              AND dmtg.IS_DELETED = 0
        ),

        pn_base AS (
            SELECT
                ll.*,
                CASE
                    WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                    WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                        THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                    ELSE NULL
                END AS SO_TIEN_AN_NUM,
                QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
            INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
               AND tt.NGAY_XET = v_ngay_tinh
               AND tt.TTPN_MA IN ('111', '112', '113', '114',
                                  '121', '122', '123', '124', '125', '126', '127')
            WHERE ll.IS_DELETED = 0
              AND NVL(ll.LL_IS_DELETED, 0) = 0
              AND NVL(ll.THA_IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        ),

        pham_nhan_filtered AS (
            SELECT
                ll.PHAM_NHAN_ID                AS pham_nhan_id,
                ll.LL_DM_GIOI_TINH_ID
            FROM pn_base ll
            LEFT JOIN DM_QUOC_TICHS dqt
                ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                   AND dqt.IS_DELETED = 0
            LEFT JOIN DM_TRAI_GIAMS dtg
                ON dtg.ID = ll.LL_TRAI_GIAM_ID
                   AND dtg.IS_DELETED = 0
-- FILTER START
            WHERE ll.IS_DELETED = 0
              AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

              -- NHÓM 1: Kho?ng ngày
              AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
              AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
              AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
              AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
              AND (
                (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                    OR EXISTS (SELECT 1
                               FROM PN_DAC_XAS dxa
                               WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                                 AND dxa.IS_DELETED = 0
                                 AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                 AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
              )
              AND (
                (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                    OR EXISTS (SELECT 1
                               FROM GIAM_THOI_HANS gaan
                               WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                 AND gaan.IS_DELETED = 0
                                 AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                 AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
              )

              -- NHÓM 2: Kho?ng s?
              AND (
                p_so_tien_an_tu IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
              )
              AND (
                p_so_tien_an_den IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
              )
              AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
              AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
              AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
              AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
              AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
              AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
              AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
              AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

              -- NHÓM 3: Danh m?c
              AND (p_gioi_tinh_id   IS NULL OR ll.LL_DM_GIOI_TINH_ID     = p_gioi_tinh_id)
              AND (p_dan_toc_id     IS NULL OR ll.LL_DM_DAN_TOC_ID       = p_dan_toc_id)
              AND (p_quoc_tich_id   IS NULL OR ll.LL_DM_QUOC_TICH_ID     = p_quoc_tich_id)
              AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID   = p_nghe_nghiep_id)
              AND (p_hoc_van_id     IS NULL OR ll.LL_DM_HOC_VAN_ID       = p_hoc_van_id)
              AND (p_ton_giao_id    IS NULL OR ll.LL_DM_TON_GIAO_ID      = p_ton_giao_id)

              -- [T?i danh] input d?ng [123,453] ho?c 123,453
              AND (
                p_toi_danh_ids IS NULL
                    OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                    OR EXISTS (SELECT 1
                               FROM selected_toi_danh_filter loc
                               WHERE INSTR(
                                             ',' || REPLACE(
                                                     REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                     ' ', '') || ',',
                                             ',' || TRIM(loc.ma_loc) || ','
                                     ) > 0)
              )

              AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
              AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

              -- [Ghi chú riêng] input d?ng 123
              AND (
                p_ghi_chu_rieng_id IS NULL
                    OR INSTR(
                               ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                               ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                       ) > 0
              )

              AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

              -- NHÓM 4: Checkbox

              -- [N??c ngoài]
              AND (p_nuoc_ngoai IS NULL OR (
                CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
              ))

              -- [Có b?nh t?t]
              AND (p_co_benh_tat IS NULL OR (
                CASE
                    WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                        THEN 1
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_BENH_TATS dbt
                        WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                          AND dbt.IS_DELETED = 0
                          AND dbt.BT_MA = '1'
                    )
                        THEN 0
                    ELSE 1
                END = p_co_benh_tat
              ))

              -- [Giam riêng]
              AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                      AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
              ))

              -- [Dân t?c thi?u s?]
              AND (
                p_dan_toc_thieu_so IS NULL
                OR (
                    CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_DAN_TOCS dt
                            WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                              AND dt.IS_DELETED = 0
                              AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                        )
                        THEN 1
                        ELSE 0
                    END = p_dan_toc_thieu_so
                )
              )

              -- [VTN t?i th?i ?i?m ph?m t?i]
              AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                CASE
                    WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                    END = p_vtn_thoi_diem_pham_toi
              ))

              -- [Ph?m t?i m?i]
              AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                      AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
              ))

              -- [Theo tôn giáo]
              AND (p_theo_ton_giao IS NULL OR (
                CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_TON_GIAOS tg
                        WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                          AND tg.IS_DELETED = 0
                    )
                    THEN 1
                    ELSE 0
                END = p_theo_ton_giao
              ))

              -- [VTN t?i th?i ?i?m hi?n t?i]
              AND (p_vtn_hien_tai IS NULL OR (
                CASE
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                    END = p_vtn_hien_tai
              ))

              -- [Không ph?m t?i m?i]
              AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                      AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
              ))

              -- [Có ngh? nghi?p]
              AND (
                p_co_nghe_nghiep IS NULL
                OR (
                    CASE
                        WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                             AND EXISTS (
                                    SELECT 1
                                    FROM DM_NGHE_NGHIEPS dnn
                                    WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                      AND dnn.IS_DELETED = 0
                                      AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                             )
                        THEN 1
                        ELSE 0
                    END = p_co_nghe_nghiep
                )
              )

              -- [Chung thân]
              AND (p_chung_than IS NULL OR (
                CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                     THEN 1 ELSE 0 END = p_chung_than
              ))

              -- [?ã b? k? lu?t]
              AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
              ))

              -- [Có ghi chú ??c bi?t]
              AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
              ))

              -- [T?i ph?m ANQG]
              AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
              ))

              -- [?ã ???c khen th??ng]
              AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                      AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
              ))

              -- [Có ti?n án]
              AND (p_co_tien_an IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_an
              ))

              -- [Có ti?n s?]
              AND (p_co_tien_su IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_su
              ))

              -- [Con theo m? vào tr?i]
              AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                      AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
              ))

              -- [Hình ph?t b? sung là ti?n]
              AND (p_hp_bo_sung_la_tien IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                          LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                    ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                        AND dhpbs.IS_DELETED = 0
                                 WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                   AND hpbs.IS_DELETED = 0
                                   AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                    ELSE 0 END = p_hp_bo_sung_la_tien
              ))

              -- [B?t bu?c ch?a b?nh]
              AND (p_bat_buoc_chua_benh IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM CHUA_BENH_BAT_BUOCS cb
                                 WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                   AND cb.IS_DELETED = 0
                                   -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                   -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                 ) THEN 1
                    ELSE 0 END = p_bat_buoc_chua_benh
              ))

              -- [Hoàn xong HPBS là ti?n]
              AND (
                p_hoan_xong_hpbs_la_tien IS NULL OR
                (CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                        LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                          ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                         AND dhpbs.IS_DELETED = 0
                        WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                          AND hpbs.IS_DELETED = 0
                          AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                        GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                        HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                    ) THEN 1
                    ELSE 0
                END = p_hoan_xong_hpbs_la_tien)
              )

              -- [Ch?a hoàn xong HPBS là ti?n]
              AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                ( CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                        LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                          ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                         AND dhpbs.IS_DELETED = 0
                        WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                          AND hpbs.IS_DELETED = 0
                          AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                        GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                        HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                    ) THEN 1
                    ELSE 0
                END = p_chua_hoan_hpbs_la_tien))
        ),
-- FILTER DONE

        chi_tiet AS (
            SELECT
                ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) AS SORT_ORDER,
                TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC))) AS "TT",
                ag.AG_LY_DO_AN_GIAM AS "LyDoAnGiam",
                COUNT(CASE WHEN gt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
                COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END) AS "Nu",
                COUNT(CASE WHEN gt.GT_TEN IS NULL
                            OR gt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN 1 END) AS "Khac",
                COUNT(*) AS "TongSo"
            FROM AN_GIAMS ag
            INNER JOIN pham_nhan_filtered pnf
                ON pnf.pham_nhan_id = ag.PHAM_NHAN_ID
            LEFT JOIN QLPN.DM_GIOI_TINHS gt
                ON gt.ID = pnf.LL_DM_GIOI_TINH_ID
               AND gt.IS_DELETED = 0
            WHERE (v_ngay_tinh IS NULL OR TRUNC(ag.AG_NGAY_QD_CHU_TICH_NUOC) < TRUNC(v_ngay_tinh) + 1)
            GROUP BY ag.AG_LY_DO_AN_GIAM
        )

    SELECT
        "TT",
        "LyDoAnGiam",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
            "LyDoAnGiam",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_AN_GIAM;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_CHUA_BENH_BAT_BUOC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_CHUA_BENH_BAT_BUOC" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    c1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN c1 FOR
        WITH

             selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),

             chung_than_ids AS (
                 SELECT dmtg.ID
                 FROM DM_MA_THOI_GIANS dmtg
                 WHERE dmtg.MTG_MA IN ('911000', '912000')
                   AND dmtg.IS_DELETED = 0
             ),

             pn_base AS (
                 SELECT
                     ll.*,
                     CASE
                         WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                         WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                             THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                         ELSE NULL
                     END AS SO_TIEN_AN_NUM,
                     QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                 FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                 INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                     ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND tt.NGAY_XET = v_ngay_tinh
                    AND tt.TTPN_MA IN ('111', '112', '113', '114')
                 WHERE ll.IS_DELETED = 0
                   AND NVL(ll.LL_IS_DELETED, 0) = 0
                   AND NVL(ll.THA_IS_DELETED, 0) = 0
                   AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
             ),

             pham_nhan_filtered AS (
                 SELECT
                     ll.PHAM_NHAN_ID AS pham_nhan_id,
                     ll.LL_DM_GIOI_TINH_ID
                 FROM pn_base ll
                 LEFT JOIN DM_QUOC_TICHS dqt
                     ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                    AND dqt.IS_DELETED = 0
                 LEFT JOIN DM_TRAI_GIAMS dtg
                     ON dtg.ID = ll.LL_TRAI_GIAM_ID
                    AND dtg.IS_DELETED = 0
-- FILTER START
                 WHERE ll.IS_DELETED = 0
                   AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

                   -- NHÓM 1: Kho?ng ngày
                   AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                   AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                   AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                   AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                   AND (
                       (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                       OR EXISTS (SELECT 1
                                  FROM PN_DAC_XAS dxa
                                  WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                                    AND dxa.IS_DELETED = 0
                                    AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                    AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
                   )
                   AND (
                       (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                       OR EXISTS (SELECT 1
                                  FROM GIAM_THOI_HANS gaan
                                  WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                    AND gaan.IS_DELETED = 0
                                    AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                    AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                   )

                   -- NHÓM 2: Kho?ng s?
                   AND (
                       p_so_tien_an_tu IS NULL
                       OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                   )
                   AND (
                       p_so_tien_an_den IS NULL
                       OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                   )
                   AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
                   AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                   AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                   AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                   AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                   AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                   AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                   AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                   -- NHÓM 3: Danh m?c
                   AND (p_gioi_tinh_id   IS NULL OR ll.LL_DM_GIOI_TINH_ID   = p_gioi_tinh_id)
                   AND (p_dan_toc_id     IS NULL OR ll.LL_DM_DAN_TOC_ID     = p_dan_toc_id)
                   AND (p_quoc_tich_id   IS NULL OR ll.LL_DM_QUOC_TICH_ID   = p_quoc_tich_id)
                   AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                   AND (p_hoc_van_id     IS NULL OR ll.LL_DM_HOC_VAN_ID     = p_hoc_van_id)
                   AND (p_ton_giao_id    IS NULL OR ll.LL_DM_TON_GIAO_ID    = p_ton_giao_id)

                   -- [T?i danh]
                   AND (
                       p_toi_danh_ids IS NULL
                       OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                       OR EXISTS (SELECT 1
                                  FROM selected_toi_danh_filter loc
                                  WHERE INSTR(
                                                ',' || REPLACE(
                                                        REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                        ' ', '') || ',',
                                                ',' || TRIM(loc.ma_loc) || ','
                                        ) > 0)
                   )
                   AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                   AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG              = p_loai_doi_tuong_id)

                   -- [Ghi chú riêng]
                   AND (
                       p_ghi_chu_rieng_id IS NULL
                       OR INSTR(
                                  ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                                  ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                          ) > 0
                   )
                   AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                   -- NHÓM 4: Checkbox

                   -- [N??c ngoài]
                   AND (p_nuoc_ngoai IS NULL OR (
                       CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                   ))

                   -- [Có b?nh t?t]
                   AND (p_co_benh_tat IS NULL OR (
                       CASE
                           WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                               THEN 1
                           WHEN EXISTS (
                               SELECT 1
                               FROM DM_BENH_TATS dbt
                               WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                 AND dbt.IS_DELETED = 0
                                 AND dbt.BT_MA = '1'
                           )
                               THEN 0
                           ELSE 1
                       END = p_co_benh_tat
                   ))

                   -- [Giam riêng]
                   AND (p_giam_rieng IS NULL OR (
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM PN_GIAM_RIENGS gr
                                        WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                                          AND gr.IS_DELETED = 0) THEN 1
                           ELSE 0 END = p_giam_rieng
                   ))

                   -- [Dân t?c thi?u s?]
                   AND (
                       p_dan_toc_thieu_so IS NULL
                       OR (
                           CASE
                               WHEN EXISTS (
                                   SELECT 1
                                   FROM DM_DAN_TOCS dt
                                   WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                                     AND dt.IS_DELETED = 0
                                     AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                               )
                               THEN 1
                               ELSE 0
                           END = p_dan_toc_thieu_so
                       )
                   )

                   -- [VTN t?i th?i ?i?m ph?m t?i]
                   AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                       CASE
                           WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                           WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                           WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                           ELSE 0
           END = p_vtn_thoi_diem_pham_toi
                   ))

                   -- [Ph?m t?i m?i]
                   AND (p_pham_toi_moi IS NULL OR (
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM PHAM_TOI_MOIS ptm
                                        WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                          AND ptm.IS_DELETED = 0) THEN 1
                           ELSE 0 END = p_pham_toi_moi
                   ))

                   -- [Theo tôn giáo]
                   AND (p_theo_ton_giao IS NULL OR (
                       CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM DM_TON_GIAOS tg
                               WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                                 AND tg.IS_DELETED = 0
                           )
                           THEN 1
                           ELSE 0
                       END = p_theo_ton_giao
                   ))

                   -- [VTN t?i th?i ?i?m hi?n t?i]
                   AND (p_vtn_hien_tai IS NULL OR (
                       CASE
                           WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                           WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                           ELSE 0
           END = p_vtn_hien_tai
                   ))

                   -- [Không ph?m t?i m?i]
                   AND (p_khong_pham_toi_moi IS NULL OR (
                       CASE
                           WHEN NOT EXISTS (SELECT 1
                                            FROM PHAM_TOI_MOIS ptm
                                            WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                              AND ptm.IS_DELETED = 0) THEN 1
                           ELSE 0 END = p_khong_pham_toi_moi
                   ))

                   -- [Có ngh? nghi?p]
                   AND (
                       p_co_nghe_nghiep IS NULL
                       OR (
                           CASE
                               WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                                    AND EXISTS (
                                           SELECT 1
                                           FROM DM_NGHE_NGHIEPS dnn
                                           WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                             AND dnn.IS_DELETED = 0
                                             AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                                    )
                               THEN 1
                               ELSE 0
                           END = p_co_nghe_nghiep
                       )
                   )

                   -- [Chung thân]
                   AND (p_chung_than IS NULL OR (
                       CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                            THEN 1 ELSE 0 END = p_chung_than
                   ))

                   -- [?ã b? k? lu?t]
                   AND (p_da_bi_ky_luat IS NULL OR (
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM KY_LUATS kl
                                        WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID) THEN 1
                           ELSE 0 END = p_da_bi_ky_luat
                   ))

                   -- [Có ghi chú ??c bi?t]
                   AND (p_co_ghi_chu_dac_biet IS NULL OR (
                       CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                             AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                            THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
                   ))

                   -- [T?i ph?m ANQG]
                   AND (p_toi_pham_anqg IS NULL OR (
                       CASE WHEN EXISTS (
                           SELECT 1 FROM DM_TOI_DANHS td
                           WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                             AND td.IS_DELETED = 0
                             AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                       ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                   ))

                   -- [?ã ???c khen th??ng]
                   AND (p_da_duoc_khen_thuong IS NULL OR (
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM KHEN_THUONGS kt
                                        WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                          AND kt.IS_DELETED = 0) THEN 1
                           ELSE 0 END = p_da_duoc_khen_thuong
                   ))

                   -- [Có ti?n án]
                   AND (p_co_tien_an IS NULL OR (
                       CASE
                           WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                               THEN 1
                           ELSE 0 END = p_co_tien_an
                   ))

                   -- [Có ti?n s?]
                   AND (p_co_tien_su IS NULL OR (
                       CASE
                           WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                               THEN 1
                           ELSE 0 END = p_co_tien_su
                   ))

                   -- [Con theo m? vào tr?i]
                   AND (p_con_theo_me_vao_trai IS NULL OR (
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM THAN_NHAN_CON_CAIS tncc
                                        WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                          AND tncc.IS_DELETED = 0) THEN 1
                           ELSE 0 END = p_con_theo_me_vao_trai
                   ))

                   -- [Hình ph?t b? sung là ti?n]
                   AND (p_hp_bo_sung_la_tien IS NULL OR (
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                             LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                       ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                          AND dhpbs.IS_DELETED = 0
                                        WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                          AND hpbs.IS_DELETED = 0
                                          AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                           ELSE 0 END = p_hp_bo_sung_la_tien
                   ))

                   -- [B?t bu?c ch?a b?nh]
                   AND (p_bat_buoc_chua_benh IS NULL OR (
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM CHUA_BENH_BAT_BUOCS cb
                                        WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                          AND cb.IS_DELETED = 0
                                          -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                          -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                        ) THEN 1
                           ELSE 0 END = p_bat_buoc_chua_benh
                   ))

                   -- [Hoàn xong HPBS là ti?n]
                   AND (
                       p_hoan_xong_hpbs_la_tien IS NULL OR
                       (CASE
                            WHEN EXISTS (
                                SELECT 1
                                FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                  ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                 AND dhpbs.IS_DELETED = 0
                                WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                  AND hpbs.IS_DELETED = 0
                                  AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                            ) THEN 1
                            ELSE 0
                        END = p_hoan_xong_hpbs_la_tien)
                   )

                   -- [Ch?a hoàn xong HPBS là ti?n]
                   AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                       (CASE
                            WHEN EXISTS (
                                SELECT 1
                                FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                  ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                 AND dhpbs.IS_DELETED = 0
                                WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                  AND hpbs.IS_DELETED = 0
                                  AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                            ) THEN 1
                            ELSE 0
                        END = p_chua_hoan_hpbs_la_tien))
-- FILTER DONE
             ),

             chi_tiet AS (
                 SELECT
                     ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) AS SORT_ORDER,
                     TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC))) AS "TT",
                     dnnc.NNC_TEN                                                  AS "BenhTat",
                     COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END)               AS "Nam",
                     COUNT(CASE WHEN gt.GT_TEN = u'N\1eef'  THEN 1 END)               AS "Nu",
                     COUNT(CASE WHEN gt.GT_TEN IS NULL
                                  OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
                     COUNT(*)                                                      AS "TongSo"
                 FROM CHUA_BENH_BAT_BUOCS cbbb
                 INNER JOIN pham_nhan_filtered pnf
                     ON pnf.pham_nhan_id = cbbb.PHAM_NHAN_ID
                 LEFT JOIN QLPN.DM_GIOI_TINHS gt
                     ON gt.ID = pnf.LL_DM_GIOI_TINH_ID
                    AND gt.IS_DELETED = 0
                 LEFT JOIN DM_NGUYEN_NHAN_CHETS dnnc
                     ON cbbb.BENH_TAT_ID = dnnc.ID
                    AND dnnc.IS_DELETED = 0
                 WHERE cbbb.IS_DELETED = 0
                   AND (v_ngay_tinh IS NULL OR TRUNC(cbbb.TU_NGAY) < TRUNC(v_ngay_tinh) + 1)
                 GROUP BY dnnc.ID, dnnc.NNC_TEN
             )

        SELECT
            "TT",
            "BenhTat",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM (
            SELECT
                SORT_ORDER,
                "TT",
                "BenhTat",
                "Nam",
                "Nu",
                "Khac",
                "TongSo"
            FROM chi_tiet

            UNION ALL

            SELECT
                999,
                TO_NCHAR(''),
                TO_NCHAR(u'T\1ed5ng s\1ed1'),
                SUM("Nam"),
                SUM("Nu"),
                SUM("Khac"),
                SUM("TongSo")
            FROM chi_tiet
        )
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_THONG_KE_CHUA_BENH_BAT_BUOC;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_CON_THEO_ME_VAO_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_CON_THEO_ME_VAO_TRAI" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

         selected_toi_danh_filter AS (
             SELECT TRIM(REGEXP_SUBSTR(
                             REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                             '[^,]+', 1, LEVEL)) AS ma_loc
             FROM DUAL
             CONNECT BY LEVEL <= REGEXP_COUNT(
                                     REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                     ',') + 1),

    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),

         pn_base AS (
                SELECT
                    ll.*,
                    CASE
                        WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                        WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                            THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                        ELSE NULL
                    END AS SO_TIEN_AN_NUM,
                    QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                    ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                   AND tt.NGAY_XET = v_ngay_tinh
                   AND tt.TTPN_MA IN ('111', '112', '113', '114')
                WHERE ll.IS_DELETED = 0
                  AND NVL(ll.LL_IS_DELETED, 0) = 0
                  AND NVL(ll.THA_IS_DELETED, 0) = 0
                  AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
            ),

         pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID                AS pham_nhan_id,
            ll.LL_DM_GIOI_TINH_ID
        FROM pn_base ll
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                AND dqt.IS_DELETED = 0
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED = 0
-- FILTER START
        WHERE ll.IS_DELETED = 0
            AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

            -- NHÓM 1: Kho?ng ngày
            AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
            AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
            AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
            AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
            AND (
                    (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                    OR EXISTS (
                        SELECT 1
                        FROM PN_DAC_XAS dxa
                        WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                          AND dxa.IS_DELETED = 0
                          AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                          AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                    )
                )
            AND (
                    (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                    OR EXISTS (
                        SELECT 1
                        FROM GIAM_THOI_HANS gaan
                        WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                          AND gaan.IS_DELETED   = 0
                          AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                          AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                    )
                )

            -- NHÓM 2: Kho?ng s?
            AND (
                p_so_tien_an_tu IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
            )
            AND (
                p_so_tien_an_den IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
            )
            AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
            AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
            AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
            AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
            AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
            AND (p_tg_con_lai_tu  IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
            AND (p_tg_con_lai_den IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

            -- NHÓM 3: Danh m?c
            AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
            AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
            AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
            AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
            AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
            AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

            -- [T?i danh] input d?ng [123,453] ho?c 123,453
            AND (
                p_toi_danh_ids IS NULL
                    OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                    OR EXISTS (SELECT 1
                               FROM selected_toi_danh_filter loc
                               WHERE INSTR(
                                             ',' || REPLACE(
                                                     REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                     ' ', '') || ',',
                                             ',' || TRIM(loc.ma_loc) || ','
                                     ) > 0)
                )

            AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
            AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

            -- [Ghi chú riêng] input d?ng 123
            AND (
                p_ghi_chu_rieng_id IS NULL
                    OR INSTR(
                               ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                               ',',
                               ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                       ) > 0
                )

            AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

            -- NHÓM 4: Checkbox

            -- [N??c ngoài]
            AND (p_nuoc_ngoai IS NULL OR (
                CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                ))

            -- [Có b?nh t?t]
            AND (p_co_benh_tat IS NULL OR (
                CASE
                    WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                        THEN 1
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_BENH_TATS dbt
                        WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                    )
                        THEN 0
                    ELSE 1
                END = p_co_benh_tat
            ))

            -- [Giam riêng]
            AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
            ))

            -- [Dân t?c thi?u s?]
            AND (
                p_dan_toc_thieu_so IS NULL
                OR (
                    CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_DAN_TOCS dt
                            WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                              AND dt.IS_DELETED = 0
                              AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                        )
                        THEN 1
                        ELSE 0
                    END = p_dan_toc_thieu_so
                )
            )

            -- [VTN t?i th?i ?i?m ph?m t?i]
            AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                CASE
                    WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                    END = p_vtn_thoi_diem_pham_toi
                ))

            -- [Ph?m t?i m?i]
            AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
            ))

            -- [Theo tôn giáo]
            AND (p_theo_ton_giao IS NULL OR (
                CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_TON_GIAOS tg
                        WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                          AND tg.IS_DELETED = 0
                    )
                    THEN 1
                    ELSE 0
                END = p_theo_ton_giao ))

            -- [VTN t?i th?i ?i?m hi?n t?i]
            AND (p_vtn_hien_tai IS NULL OR (
                CASE
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                    END = p_vtn_hien_tai
                ))

            -- [Không ph?m t?i m?i]
            AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
            ))

            -- [Có ngh? nghi?p]
            AND (
                p_co_nghe_nghiep IS NULL
                OR (
                    CASE
                        WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                             AND EXISTS (
                                    SELECT 1
                                    FROM DM_NGHE_NGHIEPS dnn
                                    WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                      AND dnn.IS_DELETED = 0
                                      AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                             )
                        THEN 1
                        ELSE 0
                    END = p_co_nghe_nghiep
                )
            )

            -- [Chung thân]
            AND (p_chung_than IS NULL OR (
                CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                     THEN 1 ELSE 0 END = p_chung_than
            ))

            -- [?ã b? k? lu?t]
            AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
            ))

            -- [Có ghi chú ??c bi?t]
            AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
            ))

            -- [T?i ph?m ANQG]
            AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))

            -- [?ã ???c khen th??ng]
            AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
            ))

            -- [Có ti?n án]
            AND (p_co_tien_an IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_an
                ))

            -- [Có ti?n s?]
            AND (p_co_tien_su IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_su
                ))

            -- [Con theo m? vào tr?i]
            AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
            ))

            -- [Hình ph?t b? sung là ti?n]
            AND (p_hp_bo_sung_la_tien IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                          LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                    ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                        AND dhpbs.IS_DELETED = 0
                                 WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                   AND hpbs.IS_DELETED = 0
                                   AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                    ELSE 0 END = p_hp_bo_sung_la_tien
                ))

            -- [B?t bu?c ch?a b?nh]
            AND (p_bat_buoc_chua_benh IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM CHUA_BENH_BAT_BUOCS cb
                                 WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                   	AND cb.IS_DELETED = 0
                                   	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                          			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                   ) THEN 1
                    ELSE 0 END = p_bat_buoc_chua_benh
                ))

            -- [Hoàn xong HPBS là ti?n]
            AND (
                p_hoan_xong_hpbs_la_tien IS NULL OR
                (CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                            LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                             AND dhpbs.IS_DELETED = 0
                            WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                              AND hpbs.IS_DELETED = 0
                              AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                            HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                        ) THEN 1
                        ELSE 0
                    END = p_hoan_xong_hpbs_la_tien))

            -- [Ch?a hoàn xong HPBS là ti?n]
            AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                ( CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                            LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                             AND dhpbs.IS_DELETED = 0
                            WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                              AND hpbs.IS_DELETED = 0
                              AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                            HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                        ) THEN 1
                        ELSE 0
                    END = p_chua_hoan_hpbs_la_tien))
    ),
-- FILTER DONE

   chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ))) AS "TT",
            dtt.TTCTMVT_TEN AS "TinhTrang",
            COUNT(DISTINCT CASE
                WHEN gt.GT_TEN = 'Nam'
                THEN tncc.PHAM_NHAN_ID END)                             AS "Nam",
            COUNT(DISTINCT CASE
                WHEN gt.GT_TEN = u'N\1eef'
                THEN tncc.PHAM_NHAN_ID END)                             AS "Nu",
            COUNT(DISTINCT CASE
                WHEN gt.GT_TEN IS NULL
                  OR gt.GT_TEN NOT IN ('Nam', u'N\1eef')
                THEN tncc.PHAM_NHAN_ID END)                             AS "Khac",
            COUNT(DISTINCT tncc.PHAM_NHAN_ID)                           AS "TongSo"
        FROM THAN_NHAN_CON_CAIS tncc
        INNER JOIN pham_nhan_filtered pnf ON  pnf.pham_nhan_id = tncc.PHAM_NHAN_ID
        LEFT JOIN DM_GIOI_TINHS gt ON tncc.GIOI_TINH_ID = gt.ID
        LEFT JOIN DM_TINH_TRANG_CON_THEO_ME_VAO_TRAIES dtt ON tncc.TINH_TRANG_ID = dtt.ID
        WHERE tncc.IS_DELETED = 0
              AND (v_ngay_tinh IS NULL OR tncc.NGAY_DEN IS NULL OR TRUNC(tncc.NGAY_DEN) < TRUNC(v_ngay_tinh) + 1)
        GROUP BY dtt.ID, dtt.TTCTMVT_TEN
    )

    SELECT
        "TT",
        "TinhTrang",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
            "TinhTrang",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
            FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_CON_THEO_ME_VAO_TRAI;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_DAN_TOC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_DAN_TOC" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
        WITH

             selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),

             chung_than_ids AS (
                 SELECT dmtg.ID
                 FROM DM_MA_THOI_GIANS dmtg
                 WHERE dmtg.MTG_MA IN ('911000', '912000')
                   AND dmtg.IS_DELETED = 0
             ),

             pn_base AS (
                 SELECT
                     ll.*,
                     CASE
                         WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                         WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                             THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                         ELSE NULL
                     END AS SO_TIEN_AN_NUM,
                     QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                 FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                 INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                     ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND tt.NGAY_XET = v_ngay_tinh
                    AND tt.TTPN_MA IN ('111', '112', '113', '114')
                 WHERE ll.IS_DELETED = 0
                   AND NVL(ll.LL_IS_DELETED, 0) = 0
                   AND NVL(ll.THA_IS_DELETED, 0) = 0
                   AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
             ),

             pham_nhan_filtered AS (
                 SELECT ll.PHAM_NHAN_ID AS pham_nhan_id,
                        ll.LL_DM_GIOI_TINH_ID,
                        ll.LL_DM_QUOC_TICH_ID,
                        ll.LL_DM_DAN_TOC_ID,
                        ll.THA_MUC_AN_ID,
                        ll.LL_GHI_CHU_RIENG,
                        ll.NGAY_SINH_DATE,
                        ll.SO_TIEN_AN_NUM,
                        ll.LL_DM_NGHE_NGHIEP_ID,
                        ll.LL_BENH_HIEN_TAI_ID,
                        ll.LL_DM_TON_GIAO_ID,
                        ll.LL_SO_TIEN_AN,
                        ll.LL_SO_TIEN_SU,
                        ll.LL_DM_HOC_VAN_ID,
                        ll.LL_DIA_CHI_THUONG_TRU_WARD,
                        ll.LL_PHAN_DOI_ID,
                        ll.THA_THOI_GIAN_DA_CHAP_HANH,
                        ll.THA_THOI_GIAN_CON_LAI,
                        ll.THA_MA_AN_PHAT,
                        ll.THA_NGAY_DEN_TRAI,
                        ll.THA_NGAY_HET_HAN,
                        ll.THA_DOI_TUONG,
                        ll.THA_NGAY_PHAM_TOI,
                        ll.THA_GHI_CHU_DAC_BIET,
                        ll.THA_TOI_DANH,
                        ll.TOI_DANH_DAU_TIEN
                 FROM pn_base ll
                 LEFT JOIN DM_QUOC_TICHS dqt
                     ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                         AND dqt.IS_DELETED = 0
                 LEFT JOIN DM_TRAI_GIAMS dtg
                     ON dtg.ID = ll.LL_TRAI_GIAM_ID
                         AND dtg.IS_DELETED = 0
-- FILTER START
                 WHERE ll.IS_DELETED = 0
                   AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

                   -- NHOM 1: Khoang ngay
                   AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                   AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                   AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                   AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                   AND (
                       (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                       OR EXISTS (
                           SELECT 1
                           FROM PN_DAC_XAS dxa
                           WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                             AND dxa.IS_DELETED = 0
                             AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                             AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                       )
                   )
                   AND (
                       (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                       OR EXISTS (SELECT 1
                                  FROM GIAM_THOI_HANS gaan
                                  WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                    AND gaan.IS_DELETED = 0
                                    AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                    AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                   )

                   -- NHOM 2: Khoang so
                   AND (
                       p_so_tien_an_tu IS NULL
                       OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                   )
                   AND (
                       p_so_tien_an_den IS NULL
                       OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                   )
                   AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
                   AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                   AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                   AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                   AND (p_tg_chap_hanh_tu IS NULL OR
                        ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                   AND (p_tg_chap_hanh_den IS NULL OR
                        ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                   AND (p_tg_con_lai_tu IS NULL OR
                        ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                   AND (p_tg_con_lai_den IS NULL OR
                        ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                   -- NHOM 3: Danh muc
                   AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
                   AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
                   AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
                   AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                   AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
                   AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

                   -- [Toi danh]
                   AND (
                       p_toi_danh_ids IS NULL
                       OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                       OR EXISTS (SELECT 1
                                  FROM selected_toi_danh_filter loc
                                  WHERE INSTR(
                                                ',' || REPLACE(
                                                        REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                        ' ', '') || ',',
                                                ',' || TRIM(loc.ma_loc) || ','
                                        ) > 0)
                   )
                   AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                   AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG = p_loai_doi_tuong_id)

                   -- [Ghi chu rieng]
                   AND (
                       p_ghi_chu_rieng_id IS NULL
                       OR INSTR(
                                  ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                  ',',
                                  ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                          ) > 0
                   )

                   AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                   -- NHOM 4: Checkbox
                   AND (p_nuoc_ngoai IS NULL OR (
                       CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                   ))
                   AND (p_co_benh_tat IS NULL OR (
                       CASE
                           WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                               THEN 1
                           WHEN EXISTS (
                               SELECT 1
                               FROM DM_BENH_TATS dbt
                               WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                               AND dbt.IS_DELETED = 0
                               AND dbt.BT_MA = '1'
                           )
                               THEN 0
                           ELSE 1
                       END = p_co_benh_tat
                   ))
                   AND (p_giam_rieng IS NULL OR (
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM PN_GIAM_RIENGS gr
                                        WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                                          AND gr.IS_DELETED = 0) THEN 1
                           ELSE 0 END = p_giam_rieng
                   ))
                   AND (
                       p_dan_toc_thieu_so IS NULL
                       OR (
                           CASE
                               WHEN EXISTS (
                                   SELECT 1
                                   FROM DM_DAN_TOCS dt
                                   WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                                     AND dt.IS_DELETED = 0
                                     AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                               )
                               THEN 1
                               ELSE 0
                           END = p_dan_toc_thieu_so
                       )
                   )
                   AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                       CASE
                           WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                           WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                           WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                           ELSE 0
                           END = p_vtn_thoi_diem_pham_toi
                   ))
                   AND (p_pham_toi_moi IS NULL OR (
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM PHAM_TOI_MOIS ptm
                                        WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                          AND ptm.IS_DELETED = 0) THEN 1
                           ELSE 0 END = p_pham_toi_moi
                   ))
                   AND (p_theo_ton_giao IS NULL OR (
                       CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM DM_TON_GIAOS tg
                               WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                                 AND tg.IS_DELETED = 0
                           )
                           THEN 1
                           ELSE 0
                       END = p_theo_ton_giao ))
                   AND (p_vtn_hien_tai IS NULL OR (
                       CASE
                           WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                           WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                           ELSE 0
                           END = p_vtn_hien_tai
                   ))
                   AND (p_khong_pham_toi_moi IS NULL OR (
                       CASE
                           WHEN NOT EXISTS (SELECT 1
                                            FROM PHAM_TOI_MOIS ptm
                                            WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                              AND ptm.IS_DELETED = 0) THEN 1
                           ELSE 0 END = p_khong_pham_toi_moi
                   ))
                   AND (
                       p_co_nghe_nghiep IS NULL
                       OR (
                           CASE
                               WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                                    AND EXISTS (
                                           SELECT 1
                                           FROM DM_NGHE_NGHIEPS dnn
                                           WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                             AND dnn.IS_DELETED = 0
                                             AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Kh%ng%')
                                    )
                               THEN 1
                               ELSE 0
                           END = p_co_nghe_nghiep
                       )
                   )
                   AND (p_chung_than IS NULL OR (
                       CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                            THEN 1 ELSE 0 END = p_chung_than
                   ))
                   AND (p_da_bi_ky_luat IS NULL OR (
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM KY_LUATS kl
                                        WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID) THEN 1
                           ELSE 0 END = p_da_bi_ky_luat
                   ))
                   AND (p_co_ghi_chu_dac_biet IS NULL OR (
                       CASE
                           WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                               AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                               THEN 1
                           ELSE 0 END = p_co_ghi_chu_dac_biet
                   ))
                   AND (p_toi_pham_anqg IS NULL OR (
                       CASE WHEN EXISTS (
                           SELECT 1 FROM DM_TOI_DANHS td
                           WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                             AND td.IS_DELETED = 0
                             AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                       ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                   ))
                   AND (p_da_duoc_khen_thuong IS NULL OR (
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM KHEN_THUONGS kt
                                        WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                          AND kt.IS_DELETED = 0) THEN 1
                           ELSE 0 END = p_da_duoc_khen_thuong
                   ))
                   AND (p_co_tien_an IS NULL OR (
                       CASE
                           WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                               THEN 1
                           ELSE 0 END = p_co_tien_an
                   ))
                   AND (p_co_tien_su IS NULL OR (
                       CASE
                           WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                               THEN 1
                           ELSE 0 END = p_co_tien_su
                   ))
                   AND (p_con_theo_me_vao_trai IS NULL OR (
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM THAN_NHAN_CON_CAIS tncc
                                        WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                          AND tncc.IS_DELETED = 0) THEN 1
                           ELSE 0 END = p_con_theo_me_vao_trai
                   ))
                   AND (p_hp_bo_sung_la_tien IS NULL OR (
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                 LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                           ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                               AND dhpbs.IS_DELETED = 0
                                        WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                          AND hpbs.IS_DELETED = 0
                                          AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                           ELSE 0 END = p_hp_bo_sung_la_tien
                   ))
                   AND (p_bat_buoc_chua_benh IS NULL OR (
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM CHUA_BENH_BAT_BUOCS cb
                                        WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                          AND cb.IS_DELETED = 0
                                          -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                          -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                        ) THEN 1
                           ELSE 0 END = p_bat_buoc_chua_benh
                   ))
                   AND (
                       p_hoan_xong_hpbs_la_tien IS NULL OR
                       (CASE
                               WHEN EXISTS (
                                   SELECT 1
                                   FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                   LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                     ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                    AND dhpbs.IS_DELETED = 0
                                   WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                     AND hpbs.IS_DELETED = 0
                                     AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                   GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                   HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                               ) THEN 1
                               ELSE 0
                           END = p_hoan_xong_hpbs_la_tien))
                   AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                       ( CASE
                               WHEN EXISTS (
                                   SELECT 1
                                   FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                   LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                     ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                    AND dhpbs.IS_DELETED = 0
                                   WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                     AND hpbs.IS_DELETED = 0
                                     AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                   GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                   HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                               ) THEN 1
                               ELSE 0
                           END = p_chua_hoan_hpbs_la_tien))
             ),
-- FILTER DONE

    pnf_detail AS (
        SELECT
            pnf.pham_nhan_id,
            dgt.GT_TEN as GT_TEN,
            ddt.DT_TEN as DT_TEN,
            ddt.DT_MA AS DT_MA,
            COUNT(*) OVER () AS TOTAL_COUNT
        FROM pham_nhan_filtered pnf
        LEFT JOIN DM_GIOI_TINHS dgt
            ON  dgt.ID         = pnf.LL_DM_GIOI_TINH_ID
            AND dgt.IS_DELETED = 0
        LEFT JOIN DM_DAN_TOCS ddt
            ON  ddt.ID         = pnf.LL_DM_DAN_TOC_ID
            AND ddt.IS_DELETED = 0
    ),

    base_dan_toc AS (
        -- Nhom I: Kinh
        SELECT
            1 AS SORT_ORDER,
            TO_NCHAR('I')     AS "TT",
            TO_NCHAR('Kinh')  AS "DanToc",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'Nam' THEN pham_nhan_id END)                              AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef' THEN pham_nhan_id END)                            AS "Nu",
            COUNT(DISTINCT CASE WHEN GT_TEN NOT IN (u'Nam', u'N\1eef') THEN pham_nhan_id END) AS "Khac",
            COUNT(DISTINCT pham_nhan_id)                                                                  AS "TongSo",
            MAX(TOTAL_COUNT) AS TOTAL_COUNT
        FROM pnf_detail
        WHERE DT_MA = u'01'

        UNION ALL

        -- Nhom II: Nguoi nuoc ngoai
        SELECT
            2 AS SORT_ORDER,
            TO_NCHAR('II')                  AS "TT",
            TO_NCHAR(u'Ng\01b0\1eddi n\01b0\1edbc ngo\00e0i')   AS "DanToc",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'Nam' THEN pham_nhan_id END)                              AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef' THEN pham_nhan_id END)                            AS "Nu",
            COUNT(DISTINCT CASE WHEN GT_TEN NOT IN (u'Nam', u'N\1eef') THEN pham_nhan_id END) AS "Khac",
            COUNT(DISTINCT pham_nhan_id)                                                                  AS "TongSo",
            MAX(TOTAL_COUNT) AS TOTAL_COUNT
        FROM pnf_detail
        WHERE DT_MA = u'55'

        UNION ALL

        -- Nhom III: Dan toc thieu so (header)
        SELECT
            3 AS SORT_ORDER,
            TO_NCHAR('III')                   AS "TT",
            TO_NCHAR(u'D\00e2n t\1ed9c thi\1ec3u s\1ed1')     AS "DanToc",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'Nam' THEN pham_nhan_id END)                              AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef' THEN pham_nhan_id END)                            AS "Nu",
            COUNT(DISTINCT CASE WHEN GT_TEN NOT IN (u'Nam', u'N\1eef') THEN pham_nhan_id END) AS "Khac",
            COUNT(DISTINCT pham_nhan_id)                                                                  AS "TongSo",
            MAX(TOTAL_COUNT) AS TOTAL_COUNT
        FROM pnf_detail
        WHERE DT_MA != u'01'
          AND DT_MA != u'55'
    )

    SELECT "TT", "DanToc", "Nam", "Nu", "Khac", "TongSo"
    FROM (
        SELECT *
        FROM base_dan_toc

        UNION ALL

        -- Chi tiet tung dan toc thieu so
        SELECT
            3 + (ROW_NUMBER() OVER (ORDER BY DT_TEN)) * 0.01  AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY DT_TEN))) AS "TT",
            DT_TEN AS "DanToc",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'Nam' THEN pham_nhan_id END)                              AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef' THEN pham_nhan_id END)                            AS "Nu",
            COUNT(DISTINCT CASE WHEN GT_TEN NOT IN (u'Nam', u'N\1eef') THEN pham_nhan_id END) AS "Khac",
            COUNT(DISTINCT pham_nhan_id)                                                                  AS "TongSo",
            MAX(TOTAL_COUNT) AS TOTAL_COUNT
        FROM pnf_detail
        WHERE DT_MA != u'01'
          AND DT_MA != u'55'
        GROUP BY DT_TEN, TOTAL_COUNT

        UNION ALL

        -- Tong so
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('')              AS "TT",
            TO_NCHAR(u'T\1ed5ng s\1ed1')     AS "DanToc",
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo"),
            MAX(TOTAL_COUNT) AS TOTAL_COUNT
        FROM base_dan_toc
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_DAN_TOC;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_DIA_PHUONG_VE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_DIA_PHUONG_VE" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
        WITH

             selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),

             chung_than_ids AS (
                 SELECT dmtg.ID
                 FROM DM_MA_THOI_GIANS dmtg
                 WHERE dmtg.MTG_MA IN ('911000', '912000')
                   AND dmtg.IS_DELETED = 0
             ),

             pn_base AS (
                 SELECT
                     ll.*,
                     CASE
                         WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                         WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                             THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                         ELSE NULL
                     END AS SO_TIEN_AN_NUM,
                     QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                 FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                 INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                     ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND tt.NGAY_XET = v_ngay_tinh
                    AND tt.TTPN_MA IN ('111', '112', '113', '114')
                 WHERE ll.IS_DELETED = 0
                   AND NVL(ll.LL_IS_DELETED, 0) = 0
                   AND NVL(ll.THA_IS_DELETED, 0) = 0
                   AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
             ),

             pham_nhan_filtered AS (
                 SELECT
                     ll.PHAM_NHAN_ID                  AS pham_nhan_id,
                     ll.LL_DM_GIOI_TINH_ID,
                     ll.LL_NOI_THA_VE_CU_TRU_PROVICE
                 FROM pn_base ll
                 LEFT JOIN DM_QUOC_TICHS dqt
                     ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                    AND dqt.IS_DELETED = 0
                 LEFT JOIN DM_TRAI_GIAMS dtg
                     ON dtg.ID = ll.LL_TRAI_GIAM_ID
                    AND dtg.IS_DELETED = 0
-- FILTER START
                 WHERE ll.IS_DELETED = 0
                   AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

                   -- NHÓM 1: Kho?ng ngày
                   AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                   AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                   AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                   AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                   AND (
                       (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                       OR EXISTS (
                           SELECT 1
                           FROM PN_DAC_XAS dxa
                           WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                             AND dxa.IS_DELETED = 0
                             AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                             AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                       )
                   )
                   AND (
                       (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                       OR EXISTS (
                           SELECT 1
                           FROM GIAM_THOI_HANS gaan
                           WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                             AND gaan.IS_DELETED   = 0
                             AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                             AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                       )
                   )

                   -- NHÓM 2: Kho?ng s?
                   AND (
                       p_so_tien_an_tu IS NULL
                       OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                   )
                   AND (
                       p_so_tien_an_den IS NULL
                       OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                   )
                   AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
                   AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                   AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                   AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                   AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                   AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                   AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                   AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                   -- NHÓM 3: Danh m?c
                   AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
                   AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
                   AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
                   AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
                   AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
                   AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

                   -- [T?i danh] input d?ng [123,453] ho?c 123,453
                   AND (
                       p_toi_danh_ids IS NULL
                       OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                       OR EXISTS (
                           SELECT 1
                           FROM selected_toi_danh_filter loc
                           WHERE INSTR(
                                     ',' || REPLACE(
                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                             ' ', '') || ',',
                                     ',' || TRIM(loc.ma_loc) || ','
                                 ) > 0
                       )
                   )

                   AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                   AND (p_loai_doi_tuong_id  IS NULL OR ll.THA_DOI_TUONG              = p_loai_doi_tuong_id)

                   -- [Ghi chú riêng] input d?ng 123
                   AND (
                       p_ghi_chu_rieng_id IS NULL
                       OR INSTR(
                                  ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                                  ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                              ) > 0
                   )

                   AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                   -- NHÓM 4: Checkbox

                   -- [N??c ngoài]
                   AND (p_nuoc_ngoai IS NULL OR (
                       CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                   ))

                   -- [Có b?nh t?t]
                   AND (p_co_benh_tat IS NULL OR (
                       CASE
                           WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                               THEN 1
                           WHEN EXISTS (
                               SELECT 1
                               FROM DM_BENH_TATS dbt
                               WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                 AND dbt.IS_DELETED = 0
                                 AND dbt.BT_MA = '1'
                           )
                               THEN 0
                           ELSE 1
                       END = p_co_benh_tat
                   ))

                   -- [Giam riêng]
                   AND (p_giam_rieng IS NULL OR (
                       CASE WHEN EXISTS (
                           SELECT 1 FROM PN_GIAM_RIENGS gr
                           WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                             AND gr.IS_DELETED = 0
                       ) THEN 1 ELSE 0 END = p_giam_rieng
                   ))

                   -- [Dân t?c thi?u s?]
                   AND (
                       p_dan_toc_thieu_so IS NULL
                       OR (
                           CASE
                               WHEN EXISTS (
                                   SELECT 1
                                   FROM DM_DAN_TOCS dt
                                   WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                                     AND dt.IS_DELETED = 0
                                     AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                               )
                               THEN 1
                               ELSE 0
                           END = p_dan_toc_thieu_so
                       )
                   )

                   -- [VTN t?i th?i ?i?m ph?m t?i]
                   AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                       CASE
                           WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                           WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                           WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                           ELSE 0
                       END = p_vtn_thoi_diem_pham_toi
                   ))

                   -- [Ph?m t?i m?i]
                   AND (p_pham_toi_moi IS NULL OR (
                       CASE WHEN EXISTS (
                           SELECT 1 FROM PHAM_TOI_MOIS ptm
                           WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                             AND ptm.IS_DELETED = 0
                       ) THEN 1 ELSE 0 END = p_pham_toi_moi
                   ))

                   -- [Theo tôn giáo]
                   AND (p_theo_ton_giao IS NULL OR (
                       CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM DM_TON_GIAOS tg
                               WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                                 AND tg.IS_DELETED = 0
                           )
                           THEN 1
                           ELSE 0
                       END = p_theo_ton_giao
                   ))

                   -- [VTN t?i th?i ?i?m hi?n t?i]
                   AND (p_vtn_hien_tai IS NULL OR (
                       CASE
                           WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                           WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                           ELSE 0
                       END = p_vtn_hien_tai
                   ))

                   -- [Không ph?m t?i m?i]
                   AND (p_khong_pham_toi_moi IS NULL OR (
                       CASE WHEN NOT EXISTS (
                           SELECT 1 FROM PHAM_TOI_MOIS ptm
                           WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                             AND ptm.IS_DELETED = 0
                       ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
                   ))

                   -- [Có ngh? nghi?p]
                   AND (
                       p_co_nghe_nghiep IS NULL
                       OR (
                           CASE
                               WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                                    AND EXISTS (
                                           SELECT 1
                                           FROM DM_NGHE_NGHIEPS dnn
                                           WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                             AND dnn.IS_DELETED = 0
                                             AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                                    )
                               THEN 1
                               ELSE 0
                           END = p_co_nghe_nghiep
                       )
                   )

                   -- [Chung thân]
                   AND (p_chung_than IS NULL OR (
                       CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                            THEN 1 ELSE 0 END = p_chung_than
                   ))

                   -- [?ã b? k? lu?t]
                   AND (p_da_bi_ky_luat IS NULL OR (
                       CASE WHEN EXISTS (
                           SELECT 1 FROM KY_LUATS kl
                           WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                       ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
                   ))

                   -- [Có ghi chú ??c bi?t]
                   AND (p_co_ghi_chu_dac_biet IS NULL OR (
                       CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                             AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                            THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
                   ))

                   -- [T?i ph?m ANQG]
                   AND (p_toi_pham_anqg IS NULL OR (
                       CASE WHEN EXISTS (
                           SELECT 1 FROM DM_TOI_DANHS td
                           WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                             AND td.IS_DELETED = 0
                             AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                       ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                   ))

                   -- [?ã ???c khen th??ng]
                   AND (p_da_duoc_khen_thuong IS NULL OR (
                       CASE WHEN EXISTS (
                           SELECT 1 FROM KHEN_THUONGS kt
                           WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                             AND kt.IS_DELETED = 0
                       ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
                   ))

                   -- [Có ti?n án]
                   AND (p_co_tien_an IS NULL OR (
                       CASE
                           WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                               THEN 1
                           ELSE 0 END = p_co_tien_an
                   ))

                   -- [Có ti?n s?]
                   AND (p_co_tien_su IS NULL OR (
                       CASE
                           WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                               THEN 1
                           ELSE 0 END = p_co_tien_su
                   ))

                   -- [Con theo m? vào tr?i]
                   AND (p_con_theo_me_vao_trai IS NULL OR (
                       CASE WHEN EXISTS (
                           SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                           WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                             AND tncc.IS_DELETED = 0
                       ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
                   ))

                   -- [Hình ph?t b? sung là ti?n]
                   AND (p_hp_bo_sung_la_tien IS NULL OR (
                       CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                   ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                  AND dhpbs.IS_DELETED = 0
                               WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                 AND hpbs.IS_DELETED = 0
                                 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                           ) THEN 1
                           ELSE 0 END = p_hp_bo_sung_la_tien
                   ))

                   -- [B?t bu?c ch?a b?nh]
                   AND (p_bat_buoc_chua_benh IS NULL OR (
                       CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM CHUA_BENH_BAT_BUOCS cb
                               WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                 AND cb.IS_DELETED = 0
                                 -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                 -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                           ) THEN 1
                           ELSE 0 END = p_bat_buoc_chua_benh
                   ))

                   -- [Hoàn xong HPBS là ti?n]
                   AND (
                       p_hoan_xong_hpbs_la_tien IS NULL OR
                       (CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                   ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                  AND dhpbs.IS_DELETED = 0
                               WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                 AND hpbs.IS_DELETED = 0
                                 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                               GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                               HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                           ) THEN 1
                           ELSE 0
                       END = p_hoan_xong_hpbs_la_tien)
                   )

                   -- [Ch?a hoàn xong HPBS là ti?n]
                   AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                       (CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                   ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                  AND dhpbs.IS_DELETED = 0
                               WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                 AND hpbs.IS_DELETED = 0
                                 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                               GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                               HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                           ) THEN 1
                           ELSE 0
                       END = p_chua_hoan_hpbs_la_tien))
             ),
-- FILTER DONE

             chi_tiet AS (
                 SELECT
                     ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) AS SORT_ORDER,
                     TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC))) AS "TT",
                     ttp.TTP_TEN                                                   AS "DiaPhuong",
                     COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam' THEN pnf.pham_nhan_id END) AS "Nam",
                     COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\01EF' THEN pnf.pham_nhan_id END) AS "Nu",
                     COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, u'Kh\00E1c') NOT IN ('Nam', u'N\01EF') THEN pnf.pham_nhan_id END) AS "Khac",
                     COUNT(DISTINCT pnf.pham_nhan_id)                                AS "TongSo"
                 FROM pham_nhan_filtered pnf
                 LEFT JOIN DM_GIOI_TINHS dgt
                     ON pnf.LL_DM_GIOI_TINH_ID = dgt.ID
                 LEFT JOIN DM_TINH_THANH_PHO ttp
                     ON pnf.LL_NOI_THA_VE_CU_TRU_PROVICE = ttp.ID
                 GROUP BY ttp.ID, ttp.TTP_TEN
             )

        SELECT
            "TT",
            "DiaPhuong",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM (
            SELECT
                SORT_ORDER,
                "TT",
                "DiaPhuong",
                "Nam",
                "Nu",
                "Khac",
                "TongSo"
            FROM chi_tiet

            UNION ALL

            SELECT
                999,
                TO_NCHAR(''),
                TO_NCHAR(u'T\1ed5ng s\1ed1'),
                SUM("Nam"),
                SUM("Nu"),
                SUM("Khac"),
                SUM("TongSo")
            FROM chi_tiet
        )
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_DIA_PHUONG_VE;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_DKTT_DEN_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_DKTT_DEN_TRAI" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

         selected_toi_danh_filter AS (
             SELECT TRIM(REGEXP_SUBSTR(
                             REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                             '[^,]+', 1, LEVEL)) AS ma_loc
             FROM DUAL
             CONNECT BY LEVEL <= REGEXP_COUNT(
                                     REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                     ',') + 1),
         chung_than_ids AS (
             SELECT dmtg.ID
             FROM DM_MA_THOI_GIANS dmtg
             WHERE dmtg.MTG_MA IN ('911000', '912000')
               AND dmtg.IS_DELETED = 0
         ),
         pn_base AS (
             SELECT
                 ll.*,
                 CASE
                     WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                     WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                         THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                     ELSE NULL
                 END AS SO_TIEN_AN_NUM,
                 QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
             FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
             INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                 ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                AND tt.NGAY_XET = v_ngay_tinh
                AND tt.TTPN_MA IN ('111', '112', '113', '114')
             WHERE ll.IS_DELETED = 0
               AND NVL(ll.LL_IS_DELETED, 0) = 0
               AND NVL(ll.THA_IS_DELETED, 0) = 0
               AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
         ),
         pham_nhan_filtered AS (
             SELECT
                 ll.PHAM_NHAN_ID          AS pham_nhan_id,
                 ll.LL_DM_GIOI_TINH_ID,
                 ll.LL_DIA_CHI_THUONG_TRU_PROVICE
             FROM pn_base ll
             LEFT JOIN DM_QUOC_TICHS dqt
                 ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                    AND dqt.IS_DELETED = 0
             LEFT JOIN DM_TRAI_GIAMS dtg
                 ON  dtg.ID = ll.LL_TRAI_GIAM_ID
                 AND dtg.IS_DELETED = 0
-- FILTER START
             WHERE ll.IS_DELETED = 0
               AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

               -- NHOM 1: Khoang ngay
               AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
               AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
               AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
               AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
               AND (
                       (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                       OR EXISTS (
                           SELECT 1
                           FROM PN_DAC_XAS dxa
                           WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                             AND dxa.IS_DELETED = 0
                             AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                             AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                       )
                   )
               AND (
                       (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                       OR EXISTS (
                           SELECT 1
                           FROM GIAM_THOI_HANS gaan
                           WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                             AND gaan.IS_DELETED   = 0
                             AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                             AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                       )
                   )

               -- NHOM 2: Khoang so
               AND (
                       p_so_tien_an_tu IS NULL
                       OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                   )
               AND (
                       p_so_tien_an_den IS NULL
                       OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                   )
               AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
               AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
               AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
               AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
               AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
               AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
               AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
               AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

               -- NHOM 3: Danh muc
               AND (p_gioi_tinh_id   IS NULL OR ll.LL_DM_GIOI_TINH_ID   = p_gioi_tinh_id)
               AND (p_dan_toc_id     IS NULL OR ll.LL_DM_DAN_TOC_ID     = p_dan_toc_id)
               AND (p_quoc_tich_id   IS NULL OR ll.LL_DM_QUOC_TICH_ID   = p_quoc_tich_id)
               AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
               AND (p_hoc_van_id     IS NULL OR ll.LL_DM_HOC_VAN_ID     = p_hoc_van_id)
               AND (p_ton_giao_id    IS NULL OR ll.LL_DM_TON_GIAO_ID    = p_ton_giao_id)

               -- [Toi danh] input dang [123,453] hoac 123,453
               AND (
                       p_toi_danh_ids IS NULL
                       OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                       OR EXISTS (
                           SELECT 1
                           FROM selected_toi_danh_filter loc
                           WHERE INSTR(
                                         ',' || REPLACE(
                                                 REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                 ' ', '') || ',',
                                         ',' || TRIM(loc.ma_loc) || ','
                                 ) > 0)
                   )

               AND (p_dp_dktt_id       IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
               AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG             = p_loai_doi_tuong_id)

               -- [Ghi chu rieng] input dang 123
               AND (
                       p_ghi_chu_rieng_id IS NULL
                       OR INSTR(
                                  ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                                  ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                          ) > 0
                   )

               AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

               -- NHOM 4: Checkbox

               -- [Nuoc ngoai]
               AND (p_nuoc_ngoai IS NULL OR (
                   CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
               ))

               -- [Co benh tat]
               AND (p_co_benh_tat IS NULL OR (
                   CASE
                       WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                           THEN 1
                       WHEN EXISTS (
                           SELECT 1
                           FROM DM_BENH_TATS dbt
                           WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                             AND dbt.IS_DELETED = 0
                             AND dbt.BT_MA = '1'
                       )
                           THEN 0
                       ELSE 1
                   END = p_co_benh_tat
               ))

               -- [Giam rieng]
               AND (p_giam_rieng IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM PN_GIAM_RIENGS gr
                       WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_giam_rieng
               ))

               -- [Dan toc thieu so]
               AND (
                       p_dan_toc_thieu_so IS NULL
                       OR (
                           CASE
                               WHEN EXISTS (
                                   SELECT 1
                                   FROM DM_DAN_TOCS dt
                                   WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                                     AND dt.IS_DELETED = 0
                                     AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                               )
                               THEN 1
                               ELSE 0
                           END = p_dan_toc_thieu_so
                       )
                   )

               -- [VTN tai thoi diem pham toi]
               AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                   CASE
                       WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                       WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                       WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                       ELSE 0
                   END = p_vtn_thoi_diem_pham_toi
               ))

               -- [Pham toi moi]
               AND (p_pham_toi_moi IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM PHAM_TOI_MOIS ptm
                       WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_pham_toi_moi
               ))

               -- [Theo ton giao]
               AND (p_theo_ton_giao IS NULL OR (
                   CASE
                       WHEN EXISTS (
                           SELECT 1
                           FROM DM_TON_GIAOS tg
                           WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                             AND tg.IS_DELETED = 0
                       )
                       THEN 1
                       ELSE 0
                   END = p_theo_ton_giao
               ))

               -- [VTN tai thoi diem hien tai]
               AND (p_vtn_hien_tai IS NULL OR (
                   CASE
                       WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                       WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                       ELSE 0
                   END = p_vtn_hien_tai
               ))

               -- [Khong pham toi moi]
               AND (p_khong_pham_toi_moi IS NULL OR (
                   CASE WHEN NOT EXISTS (
                       SELECT 1 FROM PHAM_TOI_MOIS ptm
                       WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
               ))

               -- [Co nghe nghiep]
               AND (
                       p_co_nghe_nghiep IS NULL
                       OR (
                           CASE
                               WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                                    AND EXISTS (
                                           SELECT 1
                                           FROM DM_NGHE_NGHIEPS dnn
                                           WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                             AND dnn.IS_DELETED = 0
                                             AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                                    )
                               THEN 1
                               ELSE 0
                           END = p_co_nghe_nghiep
                       )
                   )

               -- [Chung than]
               AND (p_chung_than IS NULL OR (
                   CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                        THEN 1 ELSE 0 END = p_chung_than
               ))

               -- [Da bi ky luat]
               AND (p_da_bi_ky_luat IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM KY_LUATS kl
                       WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                   ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
               ))

               -- [Co ghi chu dac biet]
               AND (p_co_ghi_chu_dac_biet IS NULL OR (
                   CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                         AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                        THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
               ))

               -- [Toi pham ANQG]
               AND (p_toi_pham_anqg IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM DM_TOI_DANHS td
                       WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                         AND td.IS_DELETED = 0
                         AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                   ) THEN 1 ELSE 0 END = p_toi_pham_anqg
               ))

               -- [Da duoc khen thuong]
               AND (p_da_duoc_khen_thuong IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM KHEN_THUONGS kt
                       WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
               ))

               -- [Co tien an]
               AND (p_co_tien_an IS NULL OR (
                   CASE
                       WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                           THEN 1
                       ELSE 0 END = p_co_tien_an
               ))

               -- [Co tien su]
               AND (p_co_tien_su IS NULL OR (
                   CASE
                       WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                           THEN 1
                       ELSE 0 END = p_co_tien_su
               ))

               -- [Con theo me vao trai]
               AND (p_con_theo_me_vao_trai IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                       WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
               ))

               -- [Hinh phat bo sung la tien]
               AND (p_hp_bo_sung_la_tien IS NULL OR (
                   CASE
                       WHEN EXISTS (SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                             LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                       ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                           AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                       ELSE 0 END = p_hp_bo_sung_la_tien
               ))

               -- [Bat buoc chua benh]
               AND (p_bat_buoc_chua_benh IS NULL OR (
                   CASE
                       WHEN EXISTS (SELECT 1
                                    FROM CHUA_BENH_BAT_BUOCS cb
                                    WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                          AND cb.IS_DELETED = 0
                                          -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                          -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                    ) THEN 1
                       ELSE 0 END = p_bat_buoc_chua_benh
               ))

               -- [Hoan xong HPBS la tien]
               AND (
                       p_hoan_xong_hpbs_la_tien IS NULL OR
                       (CASE
                            WHEN EXISTS (
                                SELECT 1
                                FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                  ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                 AND dhpbs.IS_DELETED = 0
                                WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                  AND hpbs.IS_DELETED = 0
                                  AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                            ) THEN 1
                            ELSE 0
                        END = p_hoan_xong_hpbs_la_tien))

               -- [Chua hoan xong HPBS la tien]
               AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                       (CASE
                            WHEN EXISTS (
                                SELECT 1
                                FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                  ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                 AND dhpbs.IS_DELETED = 0
                                WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                  AND hpbs.IS_DELETED = 0
                                  AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                            ) THEN 1
                            ELSE 0
                        END = p_chua_hoan_hpbs_la_tien))
         ),
-- FILTER DONE

    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC))) AS "TT",
            ttp.TTP_TEN AS "DiaPhuong",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam' THEN pnf.pham_nhan_id END) AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN pnf.pham_nhan_id END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, u'Kh\00e1c') NOT IN ('Nam', u'N\1eef') THEN pnf.pham_nhan_id END) AS "Khac",
            COUNT(DISTINCT pnf.pham_nhan_id) AS "TongSo"
        FROM pham_nhan_filtered pnf
        LEFT JOIN DM_GIOI_TINHS dgt ON pnf.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_TINH_THANH_PHO ttp
            ON pnf.LL_DIA_CHI_THUONG_TRU_PROVICE = ttp.ID
        GROUP BY ttp.ID, ttp.TTP_TEN
    )

    SELECT
        "TT",
        "DiaPhuong",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
            "DiaPhuong",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_DKTT_DEN_TRAI;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_DO_TUOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_DO_TUOI" (

    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,

    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,

    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,

    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,

    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,

    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,

    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,

    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,

    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,

    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,

    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,

    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,

    p_muc_an_tu               IN NUMBER    DEFAULT NULL,

    p_muc_an_den              IN NUMBER    DEFAULT NULL,

    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,

    p_tuoi_den                IN NUMBER    DEFAULT NULL,

    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,

    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,

    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,

    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,

    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,

    p_dan_toc_id              IN NUMBER    DEFAULT NULL,

    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,

    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,

    p_hoc_van_id              IN NUMBER    DEFAULT NULL,

    p_ton_giao_id             IN NUMBER    DEFAULT NULL,

    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,

    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,

    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,

    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,

    p_phan_doi_id             IN NUMBER    DEFAULT NULL,

    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,

    p_co_benh_tat             IN NUMBER    DEFAULT NULL,

    p_giam_rieng              IN NUMBER    DEFAULT NULL,

    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,

    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,

    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,

    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,

    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,

    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,

    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,

    p_chung_than              IN NUMBER    DEFAULT NULL,

    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,

    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,

    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,

    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,

    p_co_tien_an              IN NUMBER    DEFAULT NULL,

    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,

    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,

    p_co_tien_su              IN NUMBER    DEFAULT NULL,

    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,

    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,

    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL

)

AS

    c1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;

BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN c1 FOR

    WITH

         selected_toi_danh_filter AS (
             SELECT TRIM(REGEXP_SUBSTR(
                             REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                             '[^,]+', 1, LEVEL)) AS ma_loc
             FROM DUAL
             CONNECT BY LEVEL <= REGEXP_COUNT(
                                     REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                     ',') + 1),

         chung_than_ids AS (
             SELECT dmtg.ID
             FROM DM_MA_THOI_GIANS dmtg
             WHERE dmtg.MTG_MA IN ('911000', '912000')
               AND dmtg.IS_DELETED = 0
         ),

         pn_base AS (
             SELECT
                 ll.*,
                 CASE
                     WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                     WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                         THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                     ELSE NULL
                 END AS SO_TIEN_AN_NUM,
                 QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
             FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
             INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                 ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                AND tt.NGAY_XET = v_ngay_tinh
                AND tt.TTPN_MA IN ('111', '112', '113', '114')
             WHERE ll.IS_DELETED = 0
               AND NVL(ll.LL_IS_DELETED, 0) = 0
               AND NVL(ll.THA_IS_DELETED, 0) = 0
               AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
         ),

         pham_nhan_filtered AS (

             SELECT
                 ll.PHAM_NHAN_ID       AS pham_nhan_id,
                 ll.LL_DM_GIOI_TINH_ID,
                 ll.NGAY_SINH_DATE

             FROM pn_base ll

             LEFT JOIN DM_TRAI_GIAMS dtg
                 ON  dtg.ID = ll.LL_TRAI_GIAM_ID
                 AND dtg.IS_DELETED = 0

             LEFT JOIN DM_QUOC_TICHS dqt
                 ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                 AND dqt.IS_DELETED = 0

-- FILTER START
             WHERE
                 ll.IS_DELETED = 0

                 AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

                 -- NHÓM 1: Kho?ng ngày
                 AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                 AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                 AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                 AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)

                 AND (
                     (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                     OR EXISTS (
                         SELECT 1
                         FROM PN_DAC_XAS dxa
                         WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                           AND dxa.IS_DELETED = 0
                           AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                           AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                     )
                 )

                 AND (
                     (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                     OR EXISTS (
                         SELECT 1
                         FROM GIAM_THOI_HANS gaan
                         WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                           AND gaan.IS_DELETED   = 0
                           AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                           AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                     )
                 )

                 -- NHÓM 2: Kho?ng s?
                 AND (
                     p_so_tien_an_tu IS NULL
                     OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                 )
                 AND (
                     p_so_tien_an_den IS NULL
                     OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                 )
                 AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
                 AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                 AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                 AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                 AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                 AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                 AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                 AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                 -- NHÓM 3: Danh m?c
                 AND (p_gioi_tinh_id   IS NULL OR ll.LL_DM_GIOI_TINH_ID   = p_gioi_tinh_id)
                 AND (p_dan_toc_id     IS NULL OR ll.LL_DM_DAN_TOC_ID     = p_dan_toc_id)
                 AND (p_quoc_tich_id   IS NULL OR ll.LL_DM_QUOC_TICH_ID   = p_quoc_tich_id)
                 AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                 AND (p_hoc_van_id     IS NULL OR ll.LL_DM_HOC_VAN_ID     = p_hoc_van_id)
                 AND (p_ton_giao_id    IS NULL OR ll.LL_DM_TON_GIAO_ID    = p_ton_giao_id)

                 -- [T?i danh]
                 AND (
                     p_toi_danh_ids IS NULL
                         OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                         OR EXISTS (SELECT 1
                                    FROM selected_toi_danh_filter loc
                                    WHERE INSTR(
                                                  ',' || REPLACE(
                                                          REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                          ' ', '') || ',',
                                                  ',' || TRIM(loc.ma_loc) || ','
                                          ) > 0)
                 )

                 AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                 AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG             = p_loai_doi_tuong_id)

                 -- [Ghi chú riêng]
                 AND (
                     p_ghi_chu_rieng_id IS NULL
                         OR INSTR(
                                    ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                    ',',
                                    ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                            ) > 0
                 )

                 AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                 -- NHÓM 4: Checkbox
                 AND (p_nuoc_ngoai IS NULL OR (
                     CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                 ))
                 AND (p_co_benh_tat IS NULL OR (
                     CASE
                         WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                             THEN 1
                         WHEN EXISTS (
                             SELECT 1
                             FROM DM_BENH_TATS dbt
                             WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                             AND dbt.IS_DELETED = 0
                             AND dbt.BT_MA = '1'
                         )
                             THEN 0
                         ELSE 1
                     END = p_co_benh_tat
                 ))
                 AND (p_giam_rieng IS NULL OR (
                     CASE WHEN EXISTS (
                         SELECT 1 FROM PN_GIAM_RIENGS gr
                         WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                     ) THEN 1 ELSE 0 END = p_giam_rieng
                 ))
                 AND (
                     p_dan_toc_thieu_so IS NULL
                     OR (
                         CASE
                             WHEN EXISTS (
                                 SELECT 1
                                 FROM DM_DAN_TOCS dt
                                 WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                                   AND dt.IS_DELETED = 0
                                   AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                             )
                             THEN 1
                             ELSE 0
                         END = p_dan_toc_thieu_so
                     )
                 )
                 AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                     CASE
                         WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                         WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                         WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                         ELSE 0
                         END = p_vtn_thoi_diem_pham_toi
                     ))
                 AND (p_pham_toi_moi IS NULL OR (
                     CASE WHEN EXISTS (
                         SELECT 1 FROM PHAM_TOI_MOIS ptm
                         WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                     ) THEN 1 ELSE 0 END = p_pham_toi_moi
                 ))
                 AND (p_theo_ton_giao IS NULL OR (
                     CASE
                         WHEN EXISTS (
                             SELECT 1
                             FROM DM_TON_GIAOS tg
                             WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                               AND tg.IS_DELETED = 0
                         )
                         THEN 1
                         ELSE 0
                     END = p_theo_ton_giao
                 ))
                 AND (p_vtn_hien_tai IS NULL OR (
                     CASE
                         WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                         WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                         ELSE 0
                         END = p_vtn_hien_tai
                     ))
                 AND (p_khong_pham_toi_moi IS NULL OR (
                     CASE WHEN NOT EXISTS (
                         SELECT 1 FROM PHAM_TOI_MOIS ptm
                         WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                     ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
                 ))
                 AND (
                     p_co_nghe_nghiep IS NULL
                     OR (
                         CASE
                             WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                                  AND EXISTS (
                                         SELECT 1
                                         FROM DM_NGHE_NGHIEPS dnn
                                         WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                           AND dnn.IS_DELETED = 0
                                           AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                                  )
                             THEN 1
                             ELSE 0
                         END = p_co_nghe_nghiep
                     )
                 )
                 AND (p_chung_than IS NULL OR (
                     CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                          THEN 1 ELSE 0 END = p_chung_than
                 ))
                 AND (p_da_bi_ky_luat IS NULL OR (
                     CASE WHEN EXISTS (
                         SELECT 1 FROM KY_LUATS kl
                         WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                     ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
                 ))
                 AND (p_co_ghi_chu_dac_biet IS NULL OR (
                     CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                           AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                          THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
                 ))
                 AND (p_toi_pham_anqg IS NULL OR (
                     CASE WHEN EXISTS (
                         SELECT 1 FROM DM_TOI_DANHS td
                         WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                           AND td.IS_DELETED = 0
                           AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                     ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                 ))
                 AND (p_da_duoc_khen_thuong IS NULL OR (
                     CASE WHEN EXISTS (
                         SELECT 1 FROM KHEN_THUONGS kt
                         WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                     ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
                 ))
                 AND (p_co_tien_an IS NULL OR (
                     CASE
                         WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                             THEN 1
                         ELSE 0 END = p_co_tien_an
                 ))
                 AND (p_co_tien_su IS NULL OR (
                     CASE
                         WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                             THEN 1
                         ELSE 0 END = p_co_tien_su
                 ))
                 AND (p_con_theo_me_vao_trai IS NULL OR (
                     CASE WHEN EXISTS (
                         SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                         WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                     ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
                 ))
                 AND (p_hp_bo_sung_la_tien IS NULL OR (
                     CASE
                         WHEN EXISTS (SELECT 1
                                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                         ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                             AND dhpbs.IS_DELETED = 0
                                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                        AND hpbs.IS_DELETED = 0
                                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                         ELSE 0 END = p_hp_bo_sung_la_tien
                 ))
                 AND (p_bat_buoc_chua_benh IS NULL OR (
                     CASE
                         WHEN EXISTS (SELECT 1
                                      FROM CHUA_BENH_BAT_BUOCS cb
                                      WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                          AND cb.IS_DELETED = 0
                                          -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                          -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                         ) THEN 1
                         ELSE 0 END = p_bat_buoc_chua_benh
                 ))
                 AND (
                     p_hoan_xong_hpbs_la_tien IS NULL OR
                     (CASE
                             WHEN EXISTS (
                                 SELECT 1
                                 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                 LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                   ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                  AND dhpbs.IS_DELETED = 0
                                 WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                   AND hpbs.IS_DELETED = 0
                                   AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                 GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                 HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                             ) THEN 1
                             ELSE 0
                         END = p_hoan_xong_hpbs_la_tien))
                 AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                     ( CASE
                             WHEN EXISTS (
                                 SELECT 1
                                 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                 LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                   ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                  AND dhpbs.IS_DELETED = 0
                                 WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                   AND hpbs.IS_DELETED = 0
                                   AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                 GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                 HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                             ) THEN 1
                             ELSE 0
                         END = p_chua_hoan_hpbs_la_tien))
         ),
-- FILTER DONE

        pnf_detail AS (
            SELECT
                pnf.pham_nhan_id,
                dgt.GT_TEN,
                FLOOR(MONTHS_BETWEEN(v_ngay_tinh, pnf.NGAY_SINH_DATE) / 12) AS tuoi
            FROM pham_nhan_filtered pnf
            LEFT JOIN DM_GIOI_TINHS dgt
                ON  dgt.ID         = pnf.LL_DM_GIOI_TINH_ID
                AND dgt.IS_DELETED = 0
            WHERE pnf.NGAY_SINH_DATE IS NOT NULL
        )

    SELECT "TT", "DoTuoi", "Nam", "Nu", "Khac", "TongSo"
    FROM (

        -- 1. D??i 14 tu?i
        SELECT
            1 AS SORT_ORDER,
            TO_NCHAR('1')                  AS "TT",
            TO_NCHAR(u'D\01b0\1edbi 14 tu\1ed5i')      AS "DoTuoi",
            COUNT(DISTINCT CASE WHEN GT_TEN = 'Nam'                                        THEN PHAM_NHAN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef'                                        THEN PHAM_NHAN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(GT_TEN, u'Kh\00e1c') NOT IN ('Nam', u'N\1eef')           THEN PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT PHAM_NHAN_ID) AS "TongSo"
        FROM pnf_detail
        WHERE tuoi < 14

        UNION ALL

        -- 2. T? 14 ??n d??i 16 tu?i
        SELECT
            2 AS SORT_ORDER,
            TO_NCHAR('2')                            AS "TT",
            TO_NCHAR(u'T\1eeb 14 \0111\1ebfn d\01b0\1edbi 16 tu\1ed5i')     AS "DoTuoi",
            COUNT(DISTINCT CASE WHEN GT_TEN = 'Nam'                                        THEN PHAM_NHAN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef'                                        THEN PHAM_NHAN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(GT_TEN, u'Kh\00e1c') NOT IN ('Nam', u'N\1eef')           THEN PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT PHAM_NHAN_ID) AS "TongSo"
        FROM pnf_detail
        WHERE tuoi >= 14 AND tuoi < 16

        UNION ALL

        -- 3. T? 16 ??n d??i 18 tu?i
        SELECT
            3 AS SORT_ORDER,
            TO_NCHAR('3')                            AS "TT",
            TO_NCHAR(u'T\1eeb 16 \0111\1ebfn d\01b0\1edbi 18 tu\1ed5i')     AS "DoTuoi",
            COUNT(DISTINCT CASE WHEN GT_TEN = 'Nam'                                        THEN PHAM_NHAN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef'                                        THEN PHAM_NHAN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(GT_TEN, u'Kh\00e1c') NOT IN ('Nam', u'N\1eef')           THEN PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT PHAM_NHAN_ID) AS "TongSo"
        FROM pnf_detail
        WHERE tuoi >= 16 AND tuoi < 18

        UNION ALL

        -- 4. T? 18 ??n d??i 30 tu?i
        SELECT
            4 AS SORT_ORDER,
            TO_NCHAR('4')                            AS "TT",
            TO_NCHAR(u'T\1eeb 18 \0111\1ebfn d\01b0\1edbi 30 tu\1ed5i')     AS "DoTuoi",
            COUNT(DISTINCT CASE WHEN GT_TEN = 'Nam'                                        THEN PHAM_NHAN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef'                                        THEN PHAM_NHAN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(GT_TEN, u'Kh\00e1c') NOT IN ('Nam', u'N\1eef')           THEN PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT PHAM_NHAN_ID) AS "TongSo"
        FROM pnf_detail
        WHERE tuoi >= 18 AND tuoi < 30

        UNION ALL

        -- 5. T? 30 ??n d??i 45 tu?i
        SELECT
            5 AS SORT_ORDER,
            TO_NCHAR('5')                            AS "TT",
            TO_NCHAR(u'T\1eeb 30 \0111\1ebfn d\01b0\1edbi 45 tu\1ed5i')     AS "DoTuoi",
            COUNT(DISTINCT CASE WHEN GT_TEN = 'Nam'                                        THEN PHAM_NHAN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef'                                        THEN PHAM_NHAN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(GT_TEN, u'Kh\00e1c') NOT IN ('Nam', u'N\1eef')           THEN PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT PHAM_NHAN_ID) AS "TongSo"
        FROM pnf_detail
        WHERE tuoi >= 30 AND tuoi < 45

        UNION ALL

        -- 6. T? 45 ??n d??i 55 tu?i
        SELECT
            6 AS SORT_ORDER,
            TO_NCHAR('6')                            AS "TT",
            TO_NCHAR(u'T\1eeb 45 \0111\1ebfn d\01b0\1edbi 55 tu\1ed5i')     AS "DoTuoi",
            COUNT(DISTINCT CASE WHEN GT_TEN = 'Nam'                                        THEN PHAM_NHAN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef'                                        THEN PHAM_NHAN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(GT_TEN, u'Kh\00e1c') NOT IN ('Nam', u'N\1eef')           THEN PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT PHAM_NHAN_ID) AS "TongSo"
        FROM pnf_detail
        WHERE tuoi >= 45 AND tuoi < 55

        UNION ALL

        -- 7. T? 55 ??n d??i 60 tu?i
        SELECT
            7 AS SORT_ORDER,
            TO_NCHAR('7')                            AS "TT",
            TO_NCHAR(u'T\1eeb 55 \0111\1ebfn d\01b0\1edbi 60 tu\1ed5i')     AS "DoTuoi",
            COUNT(DISTINCT CASE WHEN GT_TEN = 'Nam'                                        THEN PHAM_NHAN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef'                                        THEN PHAM_NHAN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(GT_TEN, u'Kh\00e1c') NOT IN ('Nam', u'N\1eef')           THEN PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT PHAM_NHAN_ID) AS "TongSo"
        FROM pnf_detail
        WHERE tuoi >= 55 AND tuoi < 60

        UNION ALL

        -- 8. T? 60 ??n d??i 70 tu?i
        SELECT
            8 AS SORT_ORDER,
            TO_NCHAR('8')                            AS "TT",
            TO_NCHAR(u'T\1eeb 60 \0111\1ebfn d\01b0\1edbi 70 tu\1ed5i')     AS "DoTuoi",
            COUNT(DISTINCT CASE WHEN GT_TEN = 'Nam'                                        THEN PHAM_NHAN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef'                                        THEN PHAM_NHAN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(GT_TEN, u'Kh\00e1c') NOT IN ('Nam', u'N\1eef')           THEN PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT PHAM_NHAN_ID) AS "TongSo"
        FROM pnf_detail
        WHERE tuoi >= 60 AND tuoi < 70

        UNION ALL

        -- 9. T? 70 tu?i tr? lên
        SELECT
            9 AS SORT_ORDER,
            TO_NCHAR('9')                       AS "TT",
            TO_NCHAR(u'T\1eeb 70 tu\1ed5i tr\1edf l\00ean')    AS "DoTuoi",
            COUNT(DISTINCT CASE WHEN GT_TEN = 'Nam'                                        THEN PHAM_NHAN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef'                                        THEN PHAM_NHAN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(GT_TEN, u'Kh\00e1c') NOT IN ('Nam', u'N\1eef')           THEN PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT PHAM_NHAN_ID) AS "TongSo"
        FROM pnf_detail
        WHERE tuoi >= 70

        UNION ALL

        -- T?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('')             AS "TT",
            TO_NCHAR(u'T\1ed5ng s\1ed1')    AS "DoTuoi",
            COUNT(DISTINCT CASE WHEN GT_TEN = 'Nam'                                        THEN PHAM_NHAN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef'                                        THEN PHAM_NHAN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(GT_TEN, u'Kh\00e1c') NOT IN ('Nam', u'N\1eef')           THEN PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT PHAM_NHAN_ID) AS "TongSo"
        FROM pnf_detail

    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);

END SP_GET_THONG_KE_DO_TUOI;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_GHI_CHU_RIENG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_GHI_CHU_RIENG" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

        selected_toi_danh_filter AS (
            SELECT TRIM(REGEXP_SUBSTR(
                            REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                            '[^,]+', 1, LEVEL)) AS ma_loc
            FROM DUAL
            CONNECT BY LEVEL <= REGEXP_COUNT(
                                    REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                    ',') + 1),

        chung_than_ids AS (
            SELECT dmtg.ID
            FROM DM_MA_THOI_GIANS dmtg
            WHERE dmtg.MTG_MA IN ('911000', '912000')
              AND dmtg.IS_DELETED = 0
        ),

        pn_base AS (
            SELECT
                ll.*,
                CASE
                    WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                    WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                        THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                    ELSE NULL
                END AS SO_TIEN_AN_NUM,
                QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
            INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
               AND tt.NGAY_XET = v_ngay_tinh
               AND tt.TTPN_MA IN ('111', '112', '113', '114')
            WHERE ll.IS_DELETED = 0
              AND NVL(ll.LL_IS_DELETED, 0) = 0
              AND NVL(ll.THA_IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        ),

        pham_nhan_filtered AS (
            SELECT
                ll.PHAM_NHAN_ID                    AS pham_nhan_id,
                ll.LL_DM_GIOI_TINH_ID,
                ll.LL_DM_QUOC_TICH_ID,
                ll.LL_GHI_CHU_RIENG
            FROM pn_base ll
            LEFT JOIN DM_QUOC_TICHS dqt
                ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
               AND dqt.IS_DELETED = 0
            LEFT JOIN DM_TRAI_GIAMS dtg
                ON dtg.ID = ll.LL_TRAI_GIAM_ID
               AND dtg.IS_DELETED = 0
-- FILTER START
            WHERE ll.IS_DELETED = 0
              AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

              -- NHÓM 1: Kho?ng ngày
              AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
              AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
              AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
              AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
              AND (
                    (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                    OR EXISTS (
                        SELECT 1
                        FROM PN_DAC_XAS dxa
                        WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                          AND dxa.IS_DELETED = 0
                          AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                          AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                    )
                )
              AND (
                    (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                    OR EXISTS (
                        SELECT 1
                        FROM GIAM_THOI_HANS gaan
                        WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                          AND gaan.IS_DELETED   = 0
                          AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                          AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                    )
                )

              -- NHÓM 2: Kho?ng s?
              AND (
                    p_so_tien_an_tu IS NULL
                    OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                )
              AND (
                    p_so_tien_an_den IS NULL
                    OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                )
              AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
              AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
              AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
              AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
              AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
              AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
              AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
              AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

              -- NHÓM 3: Danh m?c
              AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
              AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
              AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
              AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
              AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
              AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

              -- [T?i danh] input d?ng [123,453] ho?c 123,453
              AND (
                    p_toi_danh_ids IS NULL
                        OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                        OR EXISTS (SELECT 1
                                   FROM selected_toi_danh_filter loc
                                   WHERE INSTR(
                                                 ',' || REPLACE(
                                                         REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                         ' ', '') || ',',
                                                 ',' || TRIM(loc.ma_loc) || ','
                                         ) > 0)
                )

              AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
              AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

              -- [Ghi chú riêng] input d?ng 123
              AND (
                    p_ghi_chu_rieng_id IS NULL
                        OR INSTR(
                                   ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                   ',',
                                   ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                           ) > 0
                )

              AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)

              -- NHÓM 4: Checkbox

              -- [N??c ngoài]
              AND (p_nuoc_ngoai IS NULL OR (
                    CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                ))

              -- [Có b?nh t?t]
              AND (p_co_benh_tat IS NULL OR (
                    CASE
                        WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                            THEN 1
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_BENH_TATS dbt
                            WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                            AND dbt.IS_DELETED = 0
                            AND dbt.BT_MA = '1'
                        )
                            THEN 0
                        ELSE 1
                    END = p_co_benh_tat
                ))

              -- [Giam riêng]
              AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
              ))

              -- [Dân t?c thi?u s?]
              AND (
                    p_dan_toc_thieu_so IS NULL
                    OR (
                        CASE
                            WHEN EXISTS (
                                SELECT 1
                                FROM DM_DAN_TOCS dt
                                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                                  AND dt.IS_DELETED = 0
                                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                            )
                            THEN 1
                            ELSE 0
                        END = p_dan_toc_thieu_so
                    )
                )

              -- [VTN t?i th?i ?i?m ph?m t?i]
              AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                    CASE
                        WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                        WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                        ELSE 0
                        END = p_vtn_thoi_diem_pham_toi
                ))

              -- [Ph?m t?i m?i]
              AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
              ))

              -- [Theo tôn giáo]
              AND (p_theo_ton_giao IS NULL OR (
                    CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_TON_GIAOS tg
                            WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                              AND tg.IS_DELETED = 0
                        )
                        THEN 1
                        ELSE 0
                    END = p_theo_ton_giao ))

              -- [VTN t?i th?i ?i?m hi?n t?i]
              AND (p_vtn_hien_tai IS NULL OR (
                    CASE
                        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                        WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                        ELSE 0
                        END = p_vtn_hien_tai
                ))

              -- [Không ph?m t?i m?i]
              AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
              ))

              -- [Có ngh? nghi?p]
              AND (
                    p_co_nghe_nghiep IS NULL
                    OR (
                        CASE
                            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                                 AND EXISTS (
                                        SELECT 1
                                        FROM DM_NGHE_NGHIEPS dnn
                                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                          AND dnn.IS_DELETED = 0
                                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                                 )
                            THEN 1
                            ELSE 0
                        END = p_co_nghe_nghiep
                    )
                )

              -- [Chung thân]
              AND (p_chung_than IS NULL OR (
                CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                     THEN 1 ELSE 0 END = p_chung_than
              ))

              -- [?ã b? k? lu?t]
              AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
              ))

              -- [Có ghi chú ??c bi?t]
              AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
              ))

              -- [T?i ph?m ANQG]
              AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
              ))

              -- [?ã ???c khen th??ng]
              AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
              ))

              -- [Có ti?n án]
              AND (p_co_tien_an IS NULL OR (
                    CASE
                        WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                            THEN 1
                        ELSE 0 END = p_co_tien_an
                ))

              -- [Có ti?n s?]
              AND (p_co_tien_su IS NULL OR (
                    CASE
                        WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                            THEN 1
                        ELSE 0 END = p_co_tien_su
                ))

              -- [Con theo m? vào tr?i]
              AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
              ))

              -- [Hình ph?t b? sung là ti?n]
              AND (p_hp_bo_sung_la_tien IS NULL OR (
                    CASE
                        WHEN EXISTS (SELECT 1
                                     FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                              LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                            AND dhpbs.IS_DELETED = 0
                                     WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                       AND hpbs.IS_DELETED = 0
                                       AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                        ELSE 0 END = p_hp_bo_sung_la_tien
                ))

              -- [B?t bu?c ch?a b?nh]
              AND (p_bat_buoc_chua_benh IS NULL OR (
                    CASE
                        WHEN EXISTS (SELECT 1
                                     FROM CHUA_BENH_BAT_BUOCS cb
                                     WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                       AND cb.IS_DELETED = 0
                                       -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                       -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                     ) THEN 1
                        ELSE 0 END = p_bat_buoc_chua_benh
                ))

              -- [Hoàn xong HPBS là ti?n]
              AND (
                    p_hoan_xong_hpbs_la_tien IS NULL OR
                    (CASE
                            WHEN EXISTS (
                                SELECT 1
                                FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                  ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                 AND dhpbs.IS_DELETED = 0
                                WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                  AND hpbs.IS_DELETED = 0
                                  AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                            ) THEN 1
                            ELSE 0
                        END = p_hoan_xong_hpbs_la_tien))

              -- [Ch?a hoàn xong HPBS là ti?n]
              AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                    ( CASE
                            WHEN EXISTS (
                                SELECT 1
                                FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                  ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                 AND dhpbs.IS_DELETED = 0
                                WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                  AND hpbs.IS_DELETED = 0
                                  AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                            ) THEN 1
                            ELSE 0
                        END = p_chua_hoan_hpbs_la_tien))
        ),
-- FILTER DONE

        -- ----------------------------------------------------------------
        -- Tách t?ng ID ghi chú riêng, join v?i danh m?c
        -- Ph?m nhân không có GCR ho?c ID không t?n t?i trong DM
        -- ? gcr.GCR_ID = NULL, gcr.GHI_CHU_TEXT = NULL
        -- ----------------------------------------------------------------
        selected_ghi_chu_rieng_filter AS (
            SELECT TRIM(REGEXP_SUBSTR(
                           REGEXP_REPLACE(TO_NCHAR(p_ghi_chu_rieng_id), '[\[\]\s]', ''),
                           '[^,]+', 1, LEVEL)) AS GCR_ID_STR
            FROM DUAL
            CONNECT BY LEVEL <= REGEXP_COUNT(
                REGEXP_REPLACE(TO_NCHAR(p_ghi_chu_rieng_id), '[\[\]\s]', ''), ',') + 1
        ),

        ghi_chu_rieng AS (
            SELECT
                pnf.pham_nhan_id          AS PHAM_NHAN_ID,
                pnf.LL_DM_GIOI_TINH_ID,
                dgcr.ID                   AS GCR_ID,
                dgcr.GCR_TEN              AS GHI_CHU_TEXT
            FROM pham_nhan_filtered pnf
            LEFT JOIN LATERAL (
                SELECT TRIM(REGEXP_SUBSTR(
                               REGEXP_REPLACE(pnf.LL_GHI_CHU_RIENG, '[\[\]\s]', ''),
                               '[^,]+', 1, LEVEL)) AS GCR_ID_STR
                FROM DUAL
                WHERE pnf.LL_GHI_CHU_RIENG IS NOT NULL
                  AND LENGTH(TRIM(REGEXP_REPLACE(pnf.LL_GHI_CHU_RIENG, '[\[\]\s]', ''))) > 0
                CONNECT BY LEVEL <= REGEXP_COUNT(
                    REGEXP_REPLACE(pnf.LL_GHI_CHU_RIENG, '[\[\]\s]', ''), ',') + 1
            ) ids ON 1 = 1
            LEFT JOIN DM_GHI_CHU_RIENGS dgcr
                ON  TO_CHAR(dgcr.ID) = ids.GCR_ID_STR
                AND dgcr.IS_DELETED  = 0
        ),

        chi_tiet AS (
                SELECT
                    1                                                               AS SORT_ORDER,
                    TO_NCHAR('1')                                                   AS "TT",
                    TO_NCHAR(u'Kh\00f4ng c\00f3 ghi ch\00fa ri\00eang')            AS "GhiChuRieng",
                    COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam'   THEN gcr.PHAM_NHAN_ID END) AS "Nam",
                    COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN gcr.PHAM_NHAN_ID END) AS "Nu",
                    COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, u'Kh\00e1c')
                                              NOT IN (u'Nam', u'N\1eef')
                                         THEN gcr.PHAM_NHAN_ID END)                AS "Khac",
                    COUNT(DISTINCT gcr.PHAM_NHAN_ID)                               AS "TongSo"
                FROM ghi_chu_rieng gcr
                LEFT JOIN DM_GIOI_TINHS dgt
                    ON  gcr.LL_DM_GIOI_TINH_ID = dgt.ID
                    AND dgt.IS_DELETED          = 0
                WHERE gcr.GHI_CHU_TEXT IS NULL   -- không có ghi chú h?p l?
                  AND p_ghi_chu_rieng_id IS NULL

                UNION ALL

                SELECT
                    1 + DENSE_RANK() OVER (
                        ORDER BY NLSSORT(gcr.GHI_CHU_TEXT, 'NLS_SORT=BINARY_AI')
                    )                                                               AS SORT_ORDER,
                    TO_NCHAR(TO_CHAR(
                        1 + DENSE_RANK() OVER (
                            ORDER BY NLSSORT(gcr.GHI_CHU_TEXT, 'NLS_SORT=BINARY_AI')
                        )
                    ))                                                              AS "TT",
                    TO_NCHAR(gcr.GHI_CHU_TEXT)                                     AS "GhiChuRieng",
                    COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam'    THEN gcr.PHAM_NHAN_ID END) AS "Nam",
                    COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN gcr.PHAM_NHAN_ID END) AS "Nu",
                    COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, u'Kh\00e1c')
                                              NOT IN (u'Nam', u'N\1eef')
                                         THEN gcr.PHAM_NHAN_ID END)                AS "Khac",
                    COUNT(DISTINCT gcr.PHAM_NHAN_ID)                               AS "TongSo"
                FROM ghi_chu_rieng gcr
                LEFT JOIN DM_GIOI_TINHS dgt
                    ON  gcr.LL_DM_GIOI_TINH_ID = dgt.ID
                    AND dgt.IS_DELETED          = 0
                WHERE gcr.GHI_CHU_TEXT IS NOT NULL   -- ch? l?y ghi chú h?p l?
                  AND (p_ghi_chu_rieng_id IS NULL
                       OR EXISTS (
                           SELECT 1
                           FROM selected_ghi_chu_rieng_filter sgcr
                           WHERE sgcr.GCR_ID_STR = TO_CHAR(gcr.GCR_ID)
                       ))
                GROUP BY gcr.GCR_ID, gcr.GHI_CHU_TEXT)

    SELECT
        "TT",
        "GhiChuRieng",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT SORT_ORDER, "TT", "GhiChuRieng", "Nam", "Nu", "Khac", "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_GHI_CHU_RIENG;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_HINH_PHAT_BO_SUNG_KHAC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_HINH_PHAT_BO_SUNG_KHAC" (
    p_ma_trai_giam             IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH
         selected_toi_danh_filter AS (
             SELECT TRIM(REGEXP_SUBSTR(
                             REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                             '[^,]+', 1, LEVEL)) AS ma_loc
             FROM DUAL
             CONNECT BY LEVEL <= REGEXP_COUNT(
                                     REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                     ',') + 1),
         chung_than_ids AS (
             SELECT dmtg.ID
             FROM DM_MA_THOI_GIANS dmtg
             WHERE dmtg.MTG_MA IN ('911000', '912000')
               AND dmtg.IS_DELETED = 0
         ),
         pn_base AS (
             SELECT
                 ll.*,
                 CASE
                     WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                     WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                         THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                     ELSE NULL
                 END AS SO_TIEN_AN_NUM,
                 QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
             FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
             INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                 ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                AND tt.NGAY_XET = v_ngay_tinh
                AND tt.TTPN_MA IN ('111', '112', '113', '114')
             WHERE ll.IS_DELETED = 0
               AND NVL(ll.LL_IS_DELETED, 0) = 0
               AND NVL(ll.THA_IS_DELETED, 0) = 0
               AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
         ),
         pham_nhan_filtered AS (
             SELECT
                 ll.PHAM_NHAN_ID                AS pham_nhan_id,
                 ll.LL_DM_GIOI_TINH_ID,
                 ll.LL_DM_QUOC_TICH_ID,
                 ll.THA_NGAY_HET_HAN,
                 ll.THA_NGAY_DEN_TRAI,
                 ll.THA_DOI_TUONG,
                 ll.THA_MUC_AN_ID,
                 ll.LL_GHI_CHU_RIENG
             FROM pn_base ll
             LEFT JOIN DM_TRAI_GIAMS dtg
                 ON  dtg.ID = ll.LL_TRAI_GIAM_ID
                 AND dtg.IS_DELETED = 0
             LEFT JOIN DM_QUOC_TICHS dqt
                 ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                 AND dqt.IS_DELETED = 0
-- FILTER START
             WHERE ll.IS_DELETED = 0
               AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

               -- NHÓM 1: Kho?ng ngày
               AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
               AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
               AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
               AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
               AND (
                    (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                    OR EXISTS (
                        SELECT 1
                        FROM PN_DAC_XAS dxa
                        WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                          AND dxa.IS_DELETED = 0
                          AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                          AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                    )
               )
               AND (
                    (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                    OR EXISTS (
                        SELECT 1
                        FROM GIAM_THOI_HANS gaan
                        WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                          AND gaan.IS_DELETED   = 0
                          AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                          AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                    )
               )

               -- NHÓM 2: Kho?ng s?
               AND (
                    p_so_tien_an_tu IS NULL
                    OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
               )
               AND (
                    p_so_tien_an_den IS NULL
                    OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
               )
               AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
               AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
               AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
               AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
               AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
               AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
               AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
               AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

               -- NHÓM 3: Danh m?c
               AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
               AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
               AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
               AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
               AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
               AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

               -- [T?i danh]
               AND (
                    p_toi_danh_ids IS NULL
                    OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                    OR EXISTS (SELECT 1
                               FROM selected_toi_danh_filter loc
                               WHERE INSTR(
                                         ',' || REPLACE(
                                                 REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                 ' ', '') || ',',
                                         ',' || TRIM(loc.ma_loc) || ','
                                     ) > 0)
               )
               AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
               AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

               -- [Ghi chú riêng]
               AND (
                    p_ghi_chu_rieng_id IS NULL
                    OR INSTR(
                               ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                               ',',
                               ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                           ) > 0
               )

               AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

               -- NHÓM 4: Checkbox
               AND (p_nuoc_ngoai IS NULL OR (
                    CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
               ))
               AND (p_co_benh_tat IS NULL OR (
                    CASE
                        WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                            THEN 1
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_BENH_TATS dbt
                            WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                            AND dbt.IS_DELETED = 0
                            AND dbt.BT_MA = '1'
                        )
                            THEN 0
                        ELSE 1
                    END = p_co_benh_tat
               ))
               AND (p_giam_rieng IS NULL OR (
                    CASE WHEN EXISTS (
                        SELECT 1 FROM PN_GIAM_RIENGS gr
                        WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                    ) THEN 1 ELSE 0 END = p_giam_rieng
               ))
               AND (
                    p_dan_toc_thieu_so IS NULL
                    OR (
                        CASE
                            WHEN EXISTS (
                                SELECT 1
                                FROM DM_DAN_TOCS dt
                                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                                  AND dt.IS_DELETED = 0
                                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                            )
                            THEN 1
                            ELSE 0
                        END = p_dan_toc_thieu_so
                    )
               )
               AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                    CASE
                        WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                        WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                        ELSE 0
                        END = p_vtn_thoi_diem_pham_toi
               ))
               AND (p_pham_toi_moi IS NULL OR (
                    CASE WHEN EXISTS (
                        SELECT 1 FROM PHAM_TOI_MOIS ptm
                        WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                    ) THEN 1 ELSE 0 END = p_pham_toi_moi
               ))
               AND (p_theo_ton_giao IS NULL OR (
                    CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_TON_GIAOS tg
                            WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                              AND tg.IS_DELETED = 0
                        )
                        THEN 1
                        ELSE 0
                    END = p_theo_ton_giao
               ))
               AND (p_vtn_hien_tai IS NULL OR (
                    CASE
                        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                        WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                        ELSE 0
                        END = p_vtn_hien_tai
               ))
               AND (p_khong_pham_toi_moi IS NULL OR (
                    CASE WHEN NOT EXISTS (
                        SELECT 1 FROM PHAM_TOI_MOIS ptm
                        WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                    ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
               ))
               AND (
                    p_co_nghe_nghiep IS NULL
                    OR (
                        CASE
                            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                                 AND EXISTS (
                                        SELECT 1
                                        FROM DM_NGHE_NGHIEPS dnn
                                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                          AND dnn.IS_DELETED = 0
                                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                                 )
                            THEN 1
                            ELSE 0
                        END = p_co_nghe_nghiep
                    )
               )
               AND (p_chung_than IS NULL OR (
                    CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                         THEN 1 ELSE 0 END = p_chung_than
               ))
               AND (p_da_bi_ky_luat IS NULL OR (
                    CASE WHEN EXISTS (
                        SELECT 1 FROM KY_LUATS kl
                        WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
               ))
               AND (p_co_ghi_chu_dac_biet IS NULL OR (
                    CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                              AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                         THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
               ))
               AND (p_toi_pham_anqg IS NULL OR (
                    CASE WHEN EXISTS (
                        SELECT 1 FROM DM_TOI_DANHS td
                        WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                          AND td.IS_DELETED = 0
                          AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                    ) THEN 1 ELSE 0 END = p_toi_pham_anqg
               ))
               AND (p_da_duoc_khen_thuong IS NULL OR (
                    CASE WHEN EXISTS (
                        SELECT 1 FROM KHEN_THUONGS kt
                        WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                    ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
               ))
               AND (p_co_tien_an IS NULL OR (
                    CASE
                        WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                            THEN 1
                        ELSE 0 END = p_co_tien_an
               ))
               AND (p_co_tien_su IS NULL OR (
                    CASE
                        WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                            THEN 1
                        ELSE 0 END = p_co_tien_su
               ))
               AND (p_con_theo_me_vao_trai IS NULL OR (
                    CASE WHEN EXISTS (
                        SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                        WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                    ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
               ))
               AND (p_hp_bo_sung_la_tien IS NULL OR (
                    CASE
                        WHEN EXISTS (SELECT 1
                                     FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                              LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                            AND dhpbs.IS_DELETED = 0
                                     WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                       AND hpbs.IS_DELETED = 0
                                       AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                        ELSE 0 END = p_hp_bo_sung_la_tien
               ))
               AND (p_bat_buoc_chua_benh IS NULL OR (
                    CASE
                        WHEN EXISTS (SELECT 1
                                     FROM CHUA_BENH_BAT_BUOCS cb
                                     WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                       	AND cb.IS_DELETED = 0
                                       	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                              			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                           ) THEN 1
                        ELSE 0 END = p_bat_buoc_chua_benh
               ))
               AND (
                    p_hoan_xong_hpbs_la_tien IS NULL OR
                    (CASE
                            WHEN EXISTS (
                                SELECT 1
                                FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                  ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                 AND dhpbs.IS_DELETED = 0
                                WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                  AND hpbs.IS_DELETED = 0
                                  AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                            ) THEN 1
                            ELSE 0
                        END = p_hoan_xong_hpbs_la_tien))
               AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                    ( CASE
                            WHEN EXISTS (
                                SELECT 1
                                FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                  ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                 AND dhpbs.IS_DELETED = 0
                                WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                  AND hpbs.IS_DELETED = 0
                                  AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                            ) THEN 1
                            ELSE 0
                        END = p_chua_hoan_hpbs_la_tien))
-- FILTER DONE
         ),

chi_tiet AS (
    SELECT
        ROW_NUMBER() OVER (ORDER BY dhpbs.ID) AS SORT_ORDER,
        TO_NCHAR(ROW_NUMBER() OVER (ORDER BY dhpbs.ID)) AS "TT",
        NVL(dhpbs.HPBS_TEN, TO_NCHAR(u'Ch\01B0a x\00E1c \0111\1ECBnh')) AS "HPBSKhac",
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam'
            THEN pnf.PHAM_NHAN_ID END) AS "Nam",
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1EEF'
            THEN pnf.PHAM_NHAN_ID END) AS "Nu",
        COUNT(DISTINCT CASE
            WHEN NVL(dgt.GT_TEN, u'Kh\00E1c') NOT IN (u'Nam', u'N\1EEF')
            THEN pnf.PHAM_NHAN_ID END) AS "Khac",
        COUNT(DISTINCT pnf.PHAM_NHAN_ID) AS "TongSo"
    FROM PN_HINH_PHAT_BO_SUNGS phpbs
    INNER JOIN (
        SELECT PHAM_NHAN_ID, LL_DM_GIOI_TINH_ID
        FROM pham_nhan_filtered pnf
    ) pnf
        ON phpbs.HPBS_MA_PHAM_NHAN = pnf.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt
        ON pnf.LL_DM_GIOI_TINH_ID = dgt.ID
        AND dgt.IS_DELETED = 0
    LEFT JOIN DM_HINH_PHAT_BO_SUNGS dhpbs
        ON phpbs.HPBS_HINH_PHAT = dhpbs.ID
        AND dhpbs.IS_DELETED = 0
    WHERE phpbs.IS_DELETED = 0
      AND dhpbs.HPBS_LOAI_HPBS = 'HPBS'
    GROUP BY dhpbs.ID, dhpbs.HPBS_TEN
)

    SELECT
        "TT",
        "HPBSKhac",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
            "HPBSKhac",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ED5ng s\1ED1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_HINH_PHAT_BO_SUNG_KHAC;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_HINH_PHAT_BO_SUNG_TIEN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_HINH_PHAT_BO_SUNG_TIEN" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH
         selected_toi_danh_filter AS (
             SELECT TRIM(REGEXP_SUBSTR(
                             REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                             '[^,]+', 1, LEVEL)) AS ma_loc
             FROM DUAL
             CONNECT BY LEVEL <= REGEXP_COUNT(
                                     REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                     ',') + 1),

    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),

         pn_base AS (
                SELECT
                    ll.*,
                    CASE
                        WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                        WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                            THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                        ELSE NULL
                    END AS SO_TIEN_AN_NUM,
                    QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                    ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                   AND tt.NGAY_XET = v_ngay_tinh
                   AND tt.TTPN_MA IN ('111', '112', '113', '114')
                WHERE ll.IS_DELETED = 0
                  AND NVL(ll.LL_IS_DELETED, 0) = 0
                  AND NVL(ll.THA_IS_DELETED, 0) = 0
                  AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
            ),

         pham_nhan_filtered AS (
            SELECT
                ll.PHAM_NHAN_ID                   AS PHAM_NHAN_ID,
                ll.LL_DM_GIOI_TINH_ID,
                ll.LL_DM_QUOC_TICH_ID,
                ll.LL_TRAI_GIAM_ID,
                ll.THA_NGAY_HET_HAN,
                ll.THA_NGAY_DEN_TRAI,
                ll.THA_NGAY_BAN_AN,
                ll.THA_DOI_TUONG,
                ll.THA_MA_AN_PHAT,
                ll.LL_GHI_CHU_RIENG,
                ll.NGAY_SINH_DATE,
                ll.SO_TIEN_AN_NUM
            FROM pn_base ll
            LEFT JOIN DM_QUOC_TICHS dqt
                ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                    AND dqt.IS_DELETED = 0
            LEFT JOIN DM_TRAI_GIAMS dtg
                ON  dtg.ID = ll.LL_TRAI_GIAM_ID
                AND dtg.IS_DELETED = 0
-- FILTER START
            WHERE ll.IS_DELETED = 0
              AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

              -- NHÓM 1: Kho?ng ngày
              AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
              AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
              AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
              AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
              AND (
                (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                    OR EXISTS (SELECT 1
                               FROM PN_DAC_XAS dxa
                               WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                                 AND dxa.IS_DELETED = 0
                                 AND (p_dac_xa_tu_ngay IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                 AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
                )
              AND (
                (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                    OR EXISTS (SELECT 1
                               FROM GIAM_THOI_HANS gaan
                               WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                 AND gaan.IS_DELETED = 0
                                 AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                 AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                )

              -- NHÓM 2: Kho?ng s?
              AND (
                p_so_tien_an_tu IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
              )
              AND (
                p_so_tien_an_den IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
              )
              AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
              AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
              AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
              AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
              AND (p_tg_chap_hanh_tu IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
              AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
              AND (p_tg_con_lai_tu IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
              AND (p_tg_con_lai_den IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

              -- NHÓM 3: Danh m?c
              AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
              AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
              AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
              AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
              AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
              AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

              -- [T?i danh] input d?ng [123,453] ho?c 123,453
              AND (
                p_toi_danh_ids IS NULL
                    OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                    OR EXISTS (SELECT 1
                               FROM selected_toi_danh_filter loc
                               WHERE INSTR(
                                             ',' || REPLACE(
                                                     REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                     ' ', '') || ',',
                                             ',' || TRIM(loc.ma_loc) || ','
                                     ) > 0)
                )
              AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
              AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG = p_loai_doi_tuong_id)

              -- [Ghi chú riêng]
              AND (
                p_ghi_chu_rieng_id IS NULL
                    OR INSTR(
                               ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                               ',',
                               ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                       ) > 0
                )

              AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

              -- NHÓM 4: Checkbox

              -- [N??c ngoài]
              AND (p_nuoc_ngoai IS NULL OR (
                CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                ))

              -- [Có b?nh t?t]
              AND (p_co_benh_tat IS NULL OR (
                CASE
                    WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                        THEN 1
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_BENH_TATS dbt
                        WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                    )
                        THEN 0
                    ELSE 1
                END = p_co_benh_tat
              ))

              -- [Giam riêng]
              AND (p_giam_rieng IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM PN_GIAM_RIENGS gr
                                 WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                                   AND gr.IS_DELETED = 0) THEN 1
                    ELSE 0 END = p_giam_rieng
                ))

              -- [Dân t?c thi?u s?]
              AND (
                p_dan_toc_thieu_so IS NULL
                OR (
                    CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_DAN_TOCS dt
                            WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                              AND dt.IS_DELETED = 0
                              AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                        )
                        THEN 1
                        ELSE 0
                    END = p_dan_toc_thieu_so
                )
              )

              -- [VTN t?i th?i ?i?m ph?m t?i]
              AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                CASE
                    WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                    END = p_vtn_thoi_diem_pham_toi
                ))

              -- [Ph?m t?i m?i]
              AND (p_pham_toi_moi IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM PHAM_TOI_MOIS ptm
                                 WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                   AND ptm.IS_DELETED = 0) THEN 1
                    ELSE 0 END = p_pham_toi_moi
                ))

              -- [Theo tôn giáo]
              AND (p_theo_ton_giao IS NULL OR (
                CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_TON_GIAOS tg
                        WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                          AND tg.IS_DELETED = 0
                    )
                    THEN 1
                    ELSE 0
                END = p_theo_ton_giao ))

              -- [VTN t?i th?i ?i?m hi?n t?i]
              AND (p_vtn_hien_tai IS NULL OR (
                CASE
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                    END = p_vtn_hien_tai
                ))

              -- [Không ph?m t?i m?i]
              AND (p_khong_pham_toi_moi IS NULL OR (
                CASE
                    WHEN NOT EXISTS (SELECT 1
                                     FROM PHAM_TOI_MOIS ptm
                                     WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                       AND ptm.IS_DELETED = 0) THEN 1
                    ELSE 0 END = p_khong_pham_toi_moi
                ))

              -- [Có ngh? nghi?p]
              AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)

              -- [Chung thân]
              AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))

              -- [?ã b? k? lu?t]
              AND (p_da_bi_ky_luat IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM KY_LUATS kl
                                 WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID) THEN 1
                    ELSE 0 END = p_da_bi_ky_luat
                ))

              -- [Có ghi chú ??c bi?t]
              AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE
                    WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                        AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                        THEN 1
                    ELSE 0 END = p_co_ghi_chu_dac_biet
                ))

              -- [T?i ph?m ANQG]
              AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))

              -- [?ã ???c khen th??ng]
              AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM KHEN_THUONGS kt
                                 WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                   AND kt.IS_DELETED = 0) THEN 1
                    ELSE 0 END = p_da_duoc_khen_thuong
                ))

              -- [Có ti?n án]
              AND (p_co_tien_an IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_an
                ))

              -- [Có ti?n s?]
              AND (p_co_tien_su IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_su
                ))

              -- [Con theo m? vào tr?i]
              AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM THAN_NHAN_CON_CAIS tncc
                                 WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                   AND tncc.IS_DELETED = 0) THEN 1
                    ELSE 0 END = p_con_theo_me_vao_trai
                ))

              -- [Hình ph?t b? sung là ti?n]
              AND (p_hp_bo_sung_la_tien IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                          LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                    ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                        AND dhpbs.IS_DELETED = 0
                                 WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                   AND hpbs.IS_DELETED = 0
                                   AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                    ELSE 0 END = p_hp_bo_sung_la_tien
                ))

              -- [B?t bu?c ch?a b?nh]
              AND (p_bat_buoc_chua_benh IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM CHUA_BENH_BAT_BUOCS cb
                                 WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                   	AND cb.IS_DELETED = 0
                                   	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                          			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                   ) THEN 1
                    ELSE 0 END = p_bat_buoc_chua_benh
                ))

              -- [Hoàn xong HPBS là ti?n]
              AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))

              -- [Ch?a hoàn xong HPBS là ti?n]
              AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                        ( CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                                ) THEN 1
                                ELSE 0
                            END = p_chua_hoan_hpbs_la_tien))
        )
-- FILTER DONE

    SELECT
        "TT",
        "HinhPhatBoSung",
        "SoPN",
        "TongTienPhat",
        "ThucHienTruocKhiXu",
        "ThucHienSauKhiXu",
        "ThucHienKhiCHAPT",
        "TongThucHien",
        "NopTaiTrai",
        "ChuaThucHien"
    FROM (
        SELECT
            ROW_NUMBER() OVER (ORDER BY dhpbs.ID) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY dhpbs.ID))) AS "TT",
            NVL(dhpbs.HPBS_TEN, TO_NCHAR(u'Ch\01b0a x\00e1c \0111\1ecbnh')) AS "HinhPhatBoSung",
            COUNT(DISTINCT hpbs.HPBS_MA_PHAM_NHAN) AS "SoPN",
            SUM(NVL(hpbs.HPBS_TONG_TIEN_PHAT, 0)) AS "TongTienPhat",
            SUM(bl_agg.TIEN_TRUOC_KHI_XU) AS "ThucHienTruocKhiXu",
            SUM(bl_agg.TIEN_SAU_KHI_XU) AS "ThucHienSauKhiXu",
            SUM(bl_agg.TIEN_KHI_CHAPT) AS "ThucHienKhiCHAPT",
            SUM(NVL(hpbs.HPBS_TONG_TIEN_PHAT, 0)) - SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) AS "TongThucHien",
            SUM(bl_agg.TIEN_NOP_TAI_TRAI) AS "NopTaiTrai",
            SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) AS "ChuaThucHien"
        FROM PN_HINH_PHAT_BO_SUNGS hpbs
        INNER JOIN pham_nhan_filtered pnf
            ON pnf.PHAM_NHAN_ID = hpbs.HPBS_MA_PHAM_NHAN
        LEFT JOIN DM_HINH_PHAT_BO_SUNGS dhpbs
            ON  dhpbs.ID = hpbs.HPBS_HINH_PHAT
            AND dhpbs.IS_DELETED = 0
        LEFT JOIN (
            SELECT
                pb.HPBS_ID,
                SUM(CASE WHEN pb.BL_NGAY_NOP < hpbs2.THA_NGAY_BAN_AN THEN pb.BL_SO_TIEN END) AS TIEN_TRUOC_KHI_XU,
                SUM(CASE
                        WHEN pb.BL_NGAY_NOP >= hpbs2.THA_NGAY_BAN_AN
                         AND pb.BL_NGAY_NOP < hpbs2.THA_NGAY_DEN_TRAI
                        THEN pb.BL_SO_TIEN
                    END) AS TIEN_SAU_KHI_XU,
                SUM(CASE
                        WHEN pb.BL_NGAY_NOP IS NULL
                          OR pb.BL_NGAY_NOP >= hpbs2.THA_NGAY_DEN_TRAI
                        THEN pb.BL_SO_TIEN
                    END) AS TIEN_KHI_CHAPT,
                SUM(CASE
                        WHEN pb.BL_NOP_TAI_CO_QUAN IS NOT NULL
                         AND (pb.BL_NGAY_NOP IS NULL OR pb.BL_NGAY_NOP >= hpbs2.THA_NGAY_DEN_TRAI)
                        THEN pb.BL_SO_TIEN
                    END) AS TIEN_NOP_TAI_TRAI
            FROM PN_BIENLAIES pb
            INNER JOIN (
                SELECT
                    hpbs_in.ID,
                    rt_in.THA_NGAY_BAN_AN,
                    rt_in.THA_NGAY_DEN_TRAI
                FROM PN_HINH_PHAT_BO_SUNGS hpbs_in
                INNER JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt_in
                    ON rt_in.PHAM_NHAN_ID = hpbs_in.HPBS_MA_PHAM_NHAN
                   AND rt_in.IS_DELETED = 0
                   AND NVL(rt_in.THA_IS_DELETED, 0) = 0
                WHERE hpbs_in.IS_DELETED = 0
            ) hpbs2 ON hpbs2.ID = pb.HPBS_ID
            WHERE pb.IS_DELETED = 0
            GROUP BY pb.HPBS_ID
        ) bl_agg ON bl_agg.HPBS_ID = hpbs.ID
        WHERE hpbs.IS_DELETED = 0
          AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
          AND (
                p_hoan_xong_hpbs_la_tien IS NULL
                OR p_hoan_xong_hpbs_la_tien = 0
                OR (p_hoan_xong_hpbs_la_tien = 1
                AND NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0) <= 0
)
          )
          AND (
                p_chua_hoan_hpbs_la_tien IS NULL
                OR p_chua_hoan_hpbs_la_tien = 0
                OR (p_chua_hoan_hpbs_la_tien = 1
                AND NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0) > 0
)
          )
        GROUP BY dhpbs.ID, dhpbs.HPBS_TEN
        ORDER BY dhpbs.ID
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_HINH_PHAT_BO_SUNG_TIEN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_HOAN_THI_HANH_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_HOAN_THI_HANH_AN" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
    WITH

         selected_toi_danh_filter AS (
             SELECT TRIM(REGEXP_SUBSTR(
                             REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                             '[^,]+', 1, LEVEL)) AS ma_loc
             FROM DUAL
             CONNECT BY LEVEL <= REGEXP_COUNT(
                                     REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                     ',') + 1),

         chung_than_ids AS (
             SELECT dmtg.ID
             FROM DM_MA_THOI_GIANS dmtg
             WHERE dmtg.MTG_MA IN ('911000', '912000')
               AND dmtg.IS_DELETED = 0
         ),

         pn_base AS (
             SELECT
                 ll.*,
                 CASE
                     WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                     WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                         THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                     ELSE NULL
                 END AS SO_TIEN_AN_NUM,
                 QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
             FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
             INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                 ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                AND tt.NGAY_XET = v_ngay_tinh
                AND tt.TTPN_MA IN ('111', '112', '113', '114', '191')
             WHERE ll.IS_DELETED = 0
               AND NVL(ll.LL_IS_DELETED, 0) = 0
               AND NVL(ll.THA_IS_DELETED, 0) = 0
               AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
         ),

         pham_nhan_filtered AS (
             SELECT
                 ll.PHAM_NHAN_ID AS pham_nhan_id,
                 ll.LL_DM_GIOI_TINH_ID
             FROM pn_base ll
             LEFT JOIN DM_QUOC_TICHS dqt
                 ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                    AND dqt.IS_DELETED = 0
             LEFT JOIN DM_TRAI_GIAMS dtg
                 ON dtg.ID = ll.LL_TRAI_GIAM_ID
                    AND dtg.IS_DELETED = 0
-- FILTER START
             WHERE ll.IS_DELETED = 0
               AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

               -- NHÓM 1: Kho?ng ngày
               AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
               AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
               AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
               AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
               AND (
                   (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                   OR EXISTS (
                       SELECT 1
                       FROM PN_DAC_XAS dxa
                       WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                         AND dxa.IS_DELETED = 0
                         AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                         AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                   )
               )
               AND (
                   (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                   OR EXISTS (
                       SELECT 1
                       FROM GIAM_THOI_HANS gaan
                       WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                         AND gaan.IS_DELETED   = 0
                         AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                   )
               )

               -- NHÓM 2: Kho?ng s?
               AND (
                   p_so_tien_an_tu IS NULL
                   OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
               )
               AND (
                   p_so_tien_an_den IS NULL
                   OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
               )
               AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
               AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
               AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
               AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
               AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
               AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
               AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
               AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

               -- NHÓM 3: Danh m?c
               AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
               AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
               AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
               AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
               AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
               AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

               -- [T?i danh] input d?ng [123,453] ho?c 123,453
               AND (
                   p_toi_danh_ids IS NULL
                   OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                   OR EXISTS (
                       SELECT 1
                       FROM selected_toi_danh_filter loc
                       WHERE INSTR(
                                   ',' || REPLACE(
                                           REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                           ' ', '') || ',',
                                   ',' || TRIM(loc.ma_loc) || ','
                           ) > 0
                   )
               )

               AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
               AND (p_loai_doi_tuong_id  IS NULL OR ll.THA_DOI_TUONG              = p_loai_doi_tuong_id)

               -- [Ghi chú riêng]
               AND (
                   p_ghi_chu_rieng_id IS NULL
                   OR INSTR(
                              ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                              ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                          ) > 0
               )

               AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

               -- NHÓM 4: Checkbox

               -- [N??c ngoài]
               AND (p_nuoc_ngoai IS NULL OR (
                   CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
               ))

               -- [Có b?nh t?t]
               AND (p_co_benh_tat IS NULL OR (
                   CASE
                       WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                           THEN 1
                       WHEN EXISTS (
                           SELECT 1
                           FROM DM_BENH_TATS dbt
                           WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                             AND dbt.IS_DELETED = 0
                             AND dbt.BT_MA = '1'
                       )
                           THEN 0
                       ELSE 1
                   END = p_co_benh_tat
               ))

               -- [Giam riêng]
               AND (p_giam_rieng IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM PN_GIAM_RIENGS gr
                       WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                         AND gr.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_giam_rieng
               ))

               -- [Dân t?c thi?u s?]
               AND (
                   p_dan_toc_thieu_so IS NULL
                   OR (
                       CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM DM_DAN_TOCS dt
                               WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                                 AND dt.IS_DELETED = 0
                                 AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                           )
                           THEN 1
                           ELSE 0
                       END = p_dan_toc_thieu_so
                   )
               )

               -- [VTN t?i th?i ?i?m ph?m t?i]
               AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                   CASE
                       WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                       WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                       WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                       ELSE 0
                   END = p_vtn_thoi_diem_pham_toi
               ))

               -- [Ph?m t?i m?i]
               AND (p_pham_toi_moi IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM PHAM_TOI_MOIS ptm
                       WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                         AND ptm.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_pham_toi_moi
               ))

               -- [Theo tôn giáo]
               AND (p_theo_ton_giao IS NULL OR (
                   CASE
                       WHEN EXISTS (
                           SELECT 1
                           FROM DM_TON_GIAOS tg
                           WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                             AND tg.IS_DELETED = 0
                       )
                       THEN 1
                       ELSE 0
                   END = p_theo_ton_giao
               ))

               -- [VTN t?i th?i ?i?m hi?n t?i]
               AND (p_vtn_hien_tai IS NULL OR (
                   CASE
                       WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                       WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                       ELSE 0
                   END = p_vtn_hien_tai
               ))

               -- [Không ph?m t?i m?i]
               AND (p_khong_pham_toi_moi IS NULL OR (
                   CASE WHEN NOT EXISTS (
                       SELECT 1 FROM PHAM_TOI_MOIS ptm
                       WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                         AND ptm.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
               ))

               -- [Có ngh? nghi?p]
               AND (
                   p_co_nghe_nghiep IS NULL
                   OR (
                       CASE
                           WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                                AND EXISTS (
                                       SELECT 1
                                       FROM DM_NGHE_NGHIEPS dnn
                                       WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                         AND dnn.IS_DELETED = 0
                                         AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                                )
                           THEN 1
                           ELSE 0
                       END = p_co_nghe_nghiep
                   )
               )

               -- [Chung thân]
               AND (p_chung_than IS NULL OR (
                   CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                        THEN 1 ELSE 0 END = p_chung_than
               ))

               -- [?ã b? k? lu?t]
               AND (p_da_bi_ky_luat IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM KY_LUATS kl
                       WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                   ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
               ))

               -- [Có ghi chú ??c bi?t]
               AND (p_co_ghi_chu_dac_biet IS NULL OR (
                   CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                         AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                        THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
               ))

               -- [T?i ph?m ANQG]
               AND (p_toi_pham_anqg IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM DM_TOI_DANHS td
                       WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                         AND td.IS_DELETED = 0
                         AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                   ) THEN 1 ELSE 0 END = p_toi_pham_anqg
               ))

               -- [?ã ???c khen th??ng]
               AND (p_da_duoc_khen_thuong IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM KHEN_THUONGS kt
                       WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                         AND kt.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
               ))

               -- [Có ti?n án]
               AND (p_co_tien_an IS NULL OR (
                   CASE
                       WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                           THEN 1
                       ELSE 0 END = p_co_tien_an
               ))

               -- [Có ti?n s?]
               AND (p_co_tien_su IS NULL OR (
                   CASE
                       WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                           THEN 1
                       ELSE 0 END = p_co_tien_su
               ))

               -- [Con theo m? vào tr?i]
               AND (p_con_theo_me_vao_trai IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                       WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                         AND tncc.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
               ))

               -- [Hình ph?t b? sung là ti?n]
               AND (p_hp_bo_sung_la_tien IS NULL OR (
                   CASE
                       WHEN EXISTS (
                           SELECT 1
                           FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                           LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                               ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                  AND dhpbs.IS_DELETED = 0
                           WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                             AND hpbs.IS_DELETED = 0
                             AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                       ) THEN 1
                       ELSE 0 END = p_hp_bo_sung_la_tien
               ))

               -- [B?t bu?c ch?a b?nh]
               AND (p_bat_buoc_chua_benh IS NULL OR (
                   CASE
                       WHEN EXISTS (
                           SELECT 1
                           FROM CHUA_BENH_BAT_BUOCS cb
                           WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                             AND cb.IS_DELETED = 0
                             -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                             -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                       ) THEN 1
                       ELSE 0 END = p_bat_buoc_chua_benh
               ))

               -- [Hoàn xong HPBS là ti?n]
               AND (
                   p_hoan_xong_hpbs_la_tien IS NULL OR
                   (CASE
                       WHEN EXISTS (
                           SELECT 1
                           FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                           LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                               ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                              AND dhpbs.IS_DELETED = 0
                           WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                             AND hpbs.IS_DELETED = 0
                             AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                           GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                           HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                       ) THEN 1
                       ELSE 0
                   END = p_hoan_xong_hpbs_la_tien)
               )

               -- [Ch?a hoàn xong HPBS là ti?n]
               AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                   (CASE
                       WHEN EXISTS (
                           SELECT 1
                           FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                           LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                               ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                              AND dhpbs.IS_DELETED = 0
                           WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                             AND hpbs.IS_DELETED = 0
                             AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                           GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                           HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                       ) THEN 1
                       ELSE 0
                   END = p_chua_hoan_hpbs_la_tien))
         ),
-- FILTER DONE

         chi_tiet AS (
             SELECT
                 ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ) AS SORT_ORDER,
                 TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ))) AS "TT",
                 htha.LY_DO_HOAN        AS "LyDoHoanThiHanhAn",
                 COUNT(DISTINCT CASE
                     WHEN gt.GT_TEN = u'Nam'
                     THEN htha.PHAM_NHAN_ID END)                     AS "Nam",
                 COUNT(DISTINCT CASE
                     WHEN gt.GT_TEN = u'N\1eef'
                     THEN htha.PHAM_NHAN_ID END)                     AS "Nu",
                 COUNT(DISTINCT CASE
                     WHEN gt.GT_TEN IS NULL
                       OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                     THEN htha.PHAM_NHAN_ID END)                     AS "Khac",
                 COUNT(DISTINCT htha.PHAM_NHAN_ID)                   AS "TongSo"
             FROM HOAN_THI_HANH_ANS htha
             INNER JOIN pham_nhan_filtered pnf
                 ON pnf.pham_nhan_id = htha.PHAM_NHAN_ID
             LEFT JOIN DM_GIOI_TINHS gt
                 ON gt.ID         = pnf.LL_DM_GIOI_TINH_ID
                AND gt.IS_DELETED = 0
             WHERE
                 htha.IS_DELETED = 0
                 AND (v_ngay_tinh IS NULL OR TRUNC(htha.NGAY_HOAN) < TRUNC(v_ngay_tinh) + 1)
             GROUP BY
                 htha.LY_DO_HOAN
         )

    SELECT
        "TT",
        "LyDoHoanThiHanhAn",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
            "LyDoHoanThiHanhAn",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_HOAN_THI_HANH_AN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_HOC_VAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_HOC_VAN" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
    WITH

         selected_toi_danh_filter AS (
             SELECT TRIM(REGEXP_SUBSTR(
                             REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                             '[^,]+', 1, LEVEL)) AS ma_loc
             FROM DUAL
             CONNECT BY LEVEL <= REGEXP_COUNT(
                                     REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                     ',') + 1),

         chung_than_ids AS (
             SELECT dmtg.ID
             FROM DM_MA_THOI_GIANS dmtg
             WHERE dmtg.MTG_MA IN ('911000', '912000')
               AND dmtg.IS_DELETED = 0
         ),

         pn_base AS (
             SELECT
                 ll.*,
                 CASE
                     WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                     WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                         THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                     ELSE NULL
                 END AS SO_TIEN_AN_NUM,
                 QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
             FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
             INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                 ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                AND tt.NGAY_XET = v_ngay_tinh
                AND tt.TTPN_MA IN ('111', '112', '113', '114')
             WHERE ll.IS_DELETED = 0
               AND NVL(ll.LL_IS_DELETED, 0) = 0
               AND NVL(ll.THA_IS_DELETED, 0) = 0
               AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
         ),

         pham_nhan_filtered AS (
             SELECT
                 ll.PHAM_NHAN_ID                AS pham_nhan_id,
                 ll.LL_DM_GIOI_TINH_ID,
                 ll.LL_DM_HOC_VAN_ID,
                 ll.LL_DM_NGHE_NGHIEP_ID,
                 ll.LL_SO_TIEN_AN,
                 ll.LL_SO_TIEN_SU,
                 ll.LL_DM_TON_GIAO_ID,
                 ll.THA_THOI_GIAN_DA_CHAP_HANH,
                 ll.THA_THOI_GIAN_CON_LAI
             FROM pn_base ll
             LEFT JOIN DM_QUOC_TICHS dqt
                 ON  dqt.ID = ll.LL_DM_QUOC_TICH_ID
                 AND dqt.IS_DELETED = 0
             LEFT JOIN DM_TRAI_GIAMS dtg
                 ON  dtg.ID = ll.LL_TRAI_GIAM_ID
                 AND dtg.IS_DELETED = 0
-- FILTER START
             WHERE ll.IS_DELETED = 0
               AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

               -- NHÓM 1: Kho?ng ngày
               AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
               AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
               AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
               AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
               AND (
                     (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                     OR EXISTS (
                         SELECT 1
                         FROM PN_DAC_XAS dxa
                         WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                           AND dxa.IS_DELETED = 0
                           AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                           AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                     )
                   )
               AND (
                     (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                     OR EXISTS (
                         SELECT 1
                         FROM GIAM_THOI_HANS gaan
                         WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                           AND gaan.IS_DELETED   = 0
                           AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                           AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                     )
                   )

               -- NHÓM 2: Kho?ng s?
               AND (
                   p_so_tien_an_tu IS NULL
                   OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
               )
               AND (
                   p_so_tien_an_den IS NULL
                   OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
               )
               AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
               AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
               AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
               AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
               AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
               AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
               AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
               AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

               -- NHÓM 3: Danh m?c
               AND (p_gioi_tinh_id   IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
               AND (p_dan_toc_id     IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
               AND (p_quoc_tich_id   IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
               AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
               AND (p_hoc_van_id     IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
               AND (p_ton_giao_id    IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

               -- [T?i danh] input d?ng [123,453] ho?c 123,453
               AND (
                   p_toi_danh_ids IS NULL
                       OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                       OR EXISTS (SELECT 1
                                  FROM selected_toi_danh_filter loc
                                  WHERE INSTR(
                                                ',' || REPLACE(
                                                        REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                        ' ', '') || ',',
                                                ',' || TRIM(loc.ma_loc) || ','
                                        ) > 0)
               )

               AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
               AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

               -- [Ghi chú riêng] input d?ng 123
               AND (
                   p_ghi_chu_rieng_id IS NULL
                       OR INSTR(
                                  ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                                  ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                          ) > 0
               )

               AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

               -- NHÓM 4: Checkbox

               -- [N??c ngoài]
               AND (p_nuoc_ngoai IS NULL OR (
                   CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
               ))

               -- [Có b?nh t?t]
               AND (p_co_benh_tat IS NULL OR (
                   CASE
                       WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                           THEN 1
                       WHEN EXISTS (
                           SELECT 1
                           FROM DM_BENH_TATS dbt
                           WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                             AND dbt.IS_DELETED = 0
                             AND dbt.BT_MA = '1'
                       )
                           THEN 0
                       ELSE 1
                   END = p_co_benh_tat
               ))

               -- [Giam riêng]
               AND (p_giam_rieng IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM PN_GIAM_RIENGS gr
                       WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_giam_rieng
               ))

               -- [Dân t?c thi?u s?]
               AND (
                   p_dan_toc_thieu_so IS NULL
                   OR (
                       CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM DM_DAN_TOCS dt
                               WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                                 AND dt.IS_DELETED = 0
                                 AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                           )
                           THEN 1
                           ELSE 0
                       END = p_dan_toc_thieu_so
                   )
               )

               -- [VTN t?i th?i ?i?m ph?m t?i]
               AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                   CASE
                       WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                       WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                       WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                       ELSE 0
                   END = p_vtn_thoi_diem_pham_toi
               ))

               -- [Ph?m t?i m?i]
               AND (p_pham_toi_moi IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM PHAM_TOI_MOIS ptm
                       WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_pham_toi_moi
               ))

               -- [Theo tôn giáo]
               AND (p_theo_ton_giao IS NULL OR (
                   CASE
                       WHEN EXISTS (
                           SELECT 1
                           FROM DM_TON_GIAOS tg
                           WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                             AND tg.IS_DELETED = 0
                       )
                       THEN 1
                       ELSE 0
                   END = p_theo_ton_giao
               ))

               -- [VTN t?i th?i ?i?m hi?n t?i]
               AND (p_vtn_hien_tai IS NULL OR (
                   CASE
                       WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                       WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                       ELSE 0
                   END = p_vtn_hien_tai
               ))

               -- [Không ph?m t?i m?i]
               AND (p_khong_pham_toi_moi IS NULL OR (
                   CASE WHEN NOT EXISTS (
                       SELECT 1 FROM PHAM_TOI_MOIS ptm
                       WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
               ))

               -- [Có ngh? nghi?p]
               AND (
                   p_co_nghe_nghiep IS NULL
                   OR (
                       CASE
                           WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                                AND EXISTS (
                                       SELECT 1
                                       FROM DM_NGHE_NGHIEPS dnn
                                       WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                         AND dnn.IS_DELETED = 0
                                         AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                                )
                           THEN 1
                           ELSE 0
                       END = p_co_nghe_nghiep
                   )
               )

               -- [Chung thân]
               AND (p_chung_than IS NULL OR (
                   CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                        THEN 1 ELSE 0 END = p_chung_than
               ))

               -- [?ã b? k? lu?t]
               AND (p_da_bi_ky_luat IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM KY_LUATS kl
                       WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                   ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
               ))

               -- [Có ghi chú ??c bi?t]
               AND (p_co_ghi_chu_dac_biet IS NULL OR (
                   CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                             AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                        THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
               ))

               -- [T?i ph?m ANQG]
               AND (p_toi_pham_anqg IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM DM_TOI_DANHS td
                       WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                         AND td.IS_DELETED = 0
                         AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                   ) THEN 1 ELSE 0 END = p_toi_pham_anqg
               ))

               -- [?ã ???c khen th??ng]
               AND (p_da_duoc_khen_thuong IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM KHEN_THUONGS kt
                       WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
               ))

               -- [Có ti?n án]
               AND (p_co_tien_an IS NULL OR (
                   CASE
                       WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                           THEN 1
                       ELSE 0 END = p_co_tien_an
               ))

               -- [Có ti?n s?]
               AND (p_co_tien_su IS NULL OR (
                   CASE
                       WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                           THEN 1
                       ELSE 0 END = p_co_tien_su
               ))

               -- [Con theo m? vào tr?i]
               AND (p_con_theo_me_vao_trai IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                       WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
               ))

               -- [Hình ph?t b? sung là ti?n]
               AND (p_hp_bo_sung_la_tien IS NULL OR (
                   CASE
                       WHEN EXISTS (SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                             LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                       ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                           AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                       ELSE 0 END = p_hp_bo_sung_la_tien
               ))

               -- [B?t bu?c ch?a b?nh]
               AND (p_bat_buoc_chua_benh IS NULL OR (
                   CASE
                       WHEN EXISTS (SELECT 1
                                    FROM CHUA_BENH_BAT_BUOCS cb
                                    WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                      AND cb.IS_DELETED = 0
                                      -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                      -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                    ) THEN 1
                       ELSE 0 END = p_bat_buoc_chua_benh
               ))

               -- [Hoàn xong HPBS là ti?n]
               AND (
                   p_hoan_xong_hpbs_la_tien IS NULL OR
                   (CASE
                       WHEN EXISTS (
                           SELECT 1
                           FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                           LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                             ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                            AND dhpbs.IS_DELETED = 0
                           WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                             AND hpbs.IS_DELETED = 0
                             AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                           GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                           HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                       ) THEN 1
                       ELSE 0
                   END = p_hoan_xong_hpbs_la_tien)
               )

               -- [Ch?a hoàn xong HPBS là ti?n]
               AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                   (CASE
                       WHEN EXISTS (
                           SELECT 1
                           FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                           LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                             ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                            AND dhpbs.IS_DELETED = 0
                           WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                             AND hpbs.IS_DELETED = 0
                             AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                           GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                           HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                       ) THEN 1
                       ELSE 0
                   END = p_chua_hoan_hpbs_la_tien))
         ),
-- FILTER DONE

         chi_tiet_raw AS (
             SELECT
                 NVL(TO_NCHAR(dhv.HV_TEN), u'Kh\00f4ng r\00f5')                                          AS "HocVan",
                 COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN pnf.pham_nhan_id END)          AS "Nam",
                 COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'  THEN pnf.pham_nhan_id END)          AS "Nu",
                 COUNT(DISTINCT CASE
                                    WHEN dgt.GT_TEN IS NULL OR dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                        THEN pnf.pham_nhan_id
                               END)                                                               AS "Khac",
                 COUNT(DISTINCT pnf.pham_nhan_id)                                                 AS "TongSo"
             FROM pham_nhan_filtered pnf
             LEFT JOIN DM_GIOI_TINHS dgt
                 ON pnf.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
             LEFT JOIN DM_HOC_VANS dhv
                 ON pnf.LL_DM_HOC_VAN_ID = dhv.ID AND dhv.IS_DELETED = 0
             GROUP BY NVL(TO_NCHAR(dhv.HV_TEN), u'Kh\00f4ng r\00f5')
         ),

         chi_tiet AS (
             SELECT
                 ROW_NUMBER() OVER (ORDER BY "TongSo" DESC, "HocVan") AS SORT_ORDER,
                 TO_NCHAR(TO_CHAR(
                     ROW_NUMBER() OVER (ORDER BY "TongSo" DESC, "HocVan")
                 ))          AS "TT",
                 "HocVan",
                 "Nam",
                 "Nu",
                 "Khac",
                 "TongSo"
             FROM chi_tiet_raw
         )

    SELECT "TT",
           "HocVan",
           "Nam",
           "Nu",
           "Khac",
           "TongSo"
    FROM (
        SELECT SORT_ORDER,
               "TT",
               "HocVan",
               "Nam",
               "Nu",
               "Khac",
               "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT 999,
               TO_NCHAR(''),
               TO_NCHAR(u'T\1ed5ng s\1ed1'),
               SUM("Nam"),
               SUM("Nu"),
               SUM("Khac"),
               SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_HOC_VAN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_HUY_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_HUY_AN" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
        WITH

             selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),

             chung_than_ids AS (
                 SELECT dmtg.ID
                 FROM DM_MA_THOI_GIANS dmtg
                 WHERE dmtg.MTG_MA IN ('911000', '912000')
                   AND dmtg.IS_DELETED = 0
             ),

             pn_base AS (
                 SELECT
                     ll.*,
                     CASE
                         WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                         WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                             THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                         ELSE NULL
                     END AS SO_TIEN_AN_NUM,
                     QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                 FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                 INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                     ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND tt.NGAY_XET = v_ngay_tinh
                    AND tt.TTPN_MA IN ('111', '112', '113', '114', '181')
                 WHERE ll.IS_DELETED = 0
                   AND NVL(ll.LL_IS_DELETED, 0) = 0
                   AND NVL(ll.THA_IS_DELETED, 0) = 0
                   AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
             ),

             pham_nhan_filtered AS (
                 SELECT
                     ll.PHAM_NHAN_ID                AS pham_nhan_id,
                     ll.LL_DM_GIOI_TINH_ID,
                     ll.LL_DM_QUOC_TICH_ID,
                     ll.THA_NGAY_HET_HAN,
                     ll.THA_NGAY_DEN_TRAI,
                     ll.THA_DOI_TUONG,
                     ll.LL_GHI_CHU_RIENG
                 FROM pn_base ll
                 LEFT JOIN DM_TRAI_GIAMS dtg
                     ON  dtg.ID = ll.LL_TRAI_GIAM_ID
                     AND dtg.IS_DELETED = 0
                 LEFT JOIN DM_QUOC_TICHS dqt
                     ON  dqt.ID = ll.LL_DM_QUOC_TICH_ID
                     AND dqt.IS_DELETED = 0
-- FILTER START
                 WHERE ll.IS_DELETED = 0
                   AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

                   -- NHÓM 1: Kho?ng ngày
                   AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                   AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                   AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                   AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                   AND (
                       (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                       OR EXISTS (
                           SELECT 1
                           FROM PN_DAC_XAS dxa
                           WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                             AND dxa.IS_DELETED = 0
                             AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                             AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                       )
                   )
                   AND (
                       (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                       OR EXISTS (
                           SELECT 1
                           FROM GIAM_THOI_HANS gaan
                           WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                             AND gaan.IS_DELETED   = 0
                             AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                             AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                       )
                   )

                   -- NHÓM 2: Kho?ng s?
                   AND (
                       p_so_tien_an_tu IS NULL
                       OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                   )
                   AND (
                       p_so_tien_an_den IS NULL
                       OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                   )
                   AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
                   AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                   AND (p_tuoi_tu    IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                   AND (p_tuoi_den   IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                   AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                   AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                   AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                   AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                   -- NHÓM 3: Danh m?c
                   AND (p_gioi_tinh_id   IS NULL OR ll.LL_DM_GIOI_TINH_ID        = p_gioi_tinh_id)
                   AND (p_dan_toc_id     IS NULL OR ll.LL_DM_DAN_TOC_ID          = p_dan_toc_id)
                   AND (p_quoc_tich_id   IS NULL OR ll.LL_DM_QUOC_TICH_ID        = p_quoc_tich_id)
                   AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID      = p_nghe_nghiep_id)
                   AND (p_hoc_van_id     IS NULL OR ll.LL_DM_HOC_VAN_ID          = p_hoc_van_id)
                   AND (p_ton_giao_id    IS NULL OR ll.LL_DM_TON_GIAO_ID         = p_ton_giao_id)

                   -- [T?i danh]
                   AND (
                       p_toi_danh_ids IS NULL
                       OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                       OR EXISTS (
                           SELECT 1
                           FROM selected_toi_danh_filter loc
                           WHERE INSTR(
                                   ',' || REPLACE(
                                           REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                           ' ', '') || ',',
                                   ',' || TRIM(loc.ma_loc) || ','
                               ) > 0
                       )
                   )
                   AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                   AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

                   -- [Ghi chú riêng]
                   AND (
                       p_ghi_chu_rieng_id IS NULL
                       OR INSTR(
                                  ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                                  ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                              ) > 0
                   )

                   AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                   -- NHÓM 4: Checkbox
                   AND (p_nuoc_ngoai IS NULL OR (
                       CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                   ))
                   AND (p_co_benh_tat IS NULL OR (
                       CASE
                           WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                               THEN 1
                           WHEN EXISTS (
                               SELECT 1
                               FROM DM_BENH_TATS dbt
                               WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                 AND dbt.IS_DELETED = 0
                                 AND dbt.BT_MA = '1'
                           )
                               THEN 0
                           ELSE 1
                       END = p_co_benh_tat
                   ))
                   AND (p_giam_rieng IS NULL OR (
                       CASE WHEN EXISTS (
                           SELECT 1 FROM PN_GIAM_RIENGS gr
                           WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                             AND gr.IS_DELETED = 0
                       ) THEN 1 ELSE 0 END = p_giam_rieng
                   ))
                   AND (
                       p_dan_toc_thieu_so IS NULL
                       OR (
                           CASE
                               WHEN EXISTS (
                                   SELECT 1
                                   FROM DM_DAN_TOCS dt
                                   WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                                     AND dt.IS_DELETED = 0
                                     AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                               )
                               THEN 1
                               ELSE 0
                           END = p_dan_toc_thieu_so
                       )
                   )
                   AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                       CASE
                           WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                           WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                           WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                           ELSE 0
                       END = p_vtn_thoi_diem_pham_toi
                   ))
                   AND (p_pham_toi_moi IS NULL OR (
                       CASE WHEN EXISTS (
                           SELECT 1 FROM PHAM_TOI_MOIS ptm
                           WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                             AND ptm.IS_DELETED = 0
                       ) THEN 1 ELSE 0 END = p_pham_toi_moi
                   ))
                   AND (p_theo_ton_giao IS NULL OR (
                       CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM DM_TON_GIAOS tg
                               WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                                 AND tg.IS_DELETED = 0
                           )
                           THEN 1
                           ELSE 0
                       END = p_theo_ton_giao
                   ))
                   AND (p_vtn_hien_tai IS NULL OR (
                       CASE
                           WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                           WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                           ELSE 0
                       END = p_vtn_hien_tai
                   ))
                   AND (p_khong_pham_toi_moi IS NULL OR (
                       CASE WHEN NOT EXISTS (
                           SELECT 1 FROM PHAM_TOI_MOIS ptm
                           WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                             AND ptm.IS_DELETED = 0
                       ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
                   ))
                   AND (
                       p_co_nghe_nghiep IS NULL
                       OR (
                           CASE
                               WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                                    AND EXISTS (
                                           SELECT 1
                                           FROM DM_NGHE_NGHIEPS dnn
                                           WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                             AND dnn.IS_DELETED = 0
                                             AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                                    )
                               THEN 1
                               ELSE 0
                           END = p_co_nghe_nghiep
                       )
                   )
                   AND (p_chung_than IS NULL OR (
                       CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                            THEN 1 ELSE 0 END = p_chung_than
                   ))
                   AND (p_da_bi_ky_luat IS NULL OR (
                       CASE WHEN EXISTS (
                           SELECT 1 FROM KY_LUATS kl
                           WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                       ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
                   ))
                   AND (p_co_ghi_chu_dac_biet IS NULL OR (
                       CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                                 AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                            THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
                   ))
                   AND (p_toi_pham_anqg IS NULL OR (
                       CASE WHEN EXISTS (
                           SELECT 1 FROM DM_TOI_DANHS td
                           WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                             AND td.IS_DELETED = 0
                             AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                       ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                   ))
                   AND (p_da_duoc_khen_thuong IS NULL OR (
                       CASE WHEN EXISTS (
                           SELECT 1 FROM KHEN_THUONGS kt
                           WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                             AND kt.IS_DELETED = 0
                       ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
                   ))
                   AND (p_co_tien_an IS NULL OR (
                       CASE
                           WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                               THEN 1
                           ELSE 0 END = p_co_tien_an
                   ))
                   AND (p_co_tien_su IS NULL OR (
                       CASE
                           WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                               THEN 1
                           ELSE 0 END = p_co_tien_su
                   ))
                   AND (p_con_theo_me_vao_trai IS NULL OR (
                       CASE WHEN EXISTS (
                           SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                           WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                             AND tncc.IS_DELETED = 0
                       ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
                   ))
                   AND (p_hp_bo_sung_la_tien IS NULL OR (
                       CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                         ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                             AND dhpbs.IS_DELETED = 0
                               WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                 AND hpbs.IS_DELETED = 0
                                 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                           ) THEN 1
                           ELSE 0 END = p_hp_bo_sung_la_tien
                   ))
                   AND (p_bat_buoc_chua_benh IS NULL OR (
                       CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM CHUA_BENH_BAT_BUOCS cb
                               WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                 AND cb.IS_DELETED = 0
                                 -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                 -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                           ) THEN 1
                           ELSE 0 END = p_bat_buoc_chua_benh
                   ))
                   AND (
                       p_hoan_xong_hpbs_la_tien IS NULL OR
                       (CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                 ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                AND dhpbs.IS_DELETED = 0
                               WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                 AND hpbs.IS_DELETED = 0
                                 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                               GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                               HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                           ) THEN 1
                           ELSE 0
                       END = p_hoan_xong_hpbs_la_tien)
                   )
                   AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                       (CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                 ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                AND dhpbs.IS_DELETED = 0
                               WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                 AND hpbs.IS_DELETED = 0
                                 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                               GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                               HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                           ) THEN 1
                           ELSE 0
                       END = p_chua_hoan_hpbs_la_tien))
             ),
-- FILTER DONE

LY_DO_CONVERTED AS (
    SELECT
        ha.ID,
        ha.PHAM_NHAN_ID,
        DBMS_LOB.SUBSTR(ha.LY_DO_HUY, 4000, 1) AS LY_DO_HUY,
        ha.NGAY_QUYET_DINH
    FROM HUY_ANS ha
    WHERE ha.IS_DELETED = 0
),

chi_tiet AS (
    SELECT
        ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) AS SORT_ORDER,
        TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC))) AS "TT",
        TO_NCHAR(ldc.LY_DO_HUY) AS "LyDoHuy",
        COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END) AS "Nam",
        COUNT(CASE WHEN gt.GT_TEN = u'N\1EEF' THEN 1 END) AS "Nu",
        COUNT(CASE WHEN gt.GT_TEN IS NULL
                        OR gt.GT_TEN NOT IN (u'Nam', u'N\1EEF') THEN 1 END) AS "Khac",
        COUNT(*) AS "TongSo"
    FROM LY_DO_CONVERTED ldc
    INNER JOIN pham_nhan_filtered pnf ON ldc.PHAM_NHAN_ID = pnf.pham_nhan_id
    LEFT JOIN DM_GIOI_TINHS gt ON pnf.LL_DM_GIOI_TINH_ID = gt.ID
    WHERE (v_ngay_tinh IS NULL OR ldc.NGAY_QUYET_DINH IS NULL
       OR TRUNC(ldc.NGAY_QUYET_DINH) < TRUNC(v_ngay_tinh) + 1)
    GROUP BY ldc.LY_DO_HUY
)

SELECT
    "TT",
    "LyDoHuy",
    "Nam",
    "Nu",
    "Khac",
    "TongSo"
FROM (
    SELECT
        SORT_ORDER,
        "TT",
        "LyDoHuy",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM chi_tiet

    UNION ALL

    SELECT
        999,
        TO_NCHAR(''),
        TO_NCHAR(u'T\1ED5ng s\1ED1'),
        SUM("Nam"),
        SUM("Nu"),
        SUM("Khac"),
        SUM("TongSo")
    FROM chi_tiet
)
ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_HUY_AN;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_KY_LUAT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_KY_LUAT" (
    p_ma_trai_giam             IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay    IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay          IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay         IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay           IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay          IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay          IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay         IN DATE      DEFAULT NULL,
    p_so_tien_an_tu            IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den           IN NUMBER    DEFAULT NULL,
    p_muc_an_tu                IN NUMBER    DEFAULT NULL,
    p_muc_an_den               IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                  IN NUMBER    DEFAULT NULL,
    p_tuoi_den                 IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu          IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den         IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu            IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den           IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id             IN NUMBER    DEFAULT NULL,
    p_dan_toc_id               IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id             IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id           IN NUMBER    DEFAULT NULL,
    p_hoc_van_id               IN NUMBER    DEFAULT NULL,
    p_ton_giao_id              IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids             IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id               IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id        IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id         IN NUMBER    DEFAULT NULL,
    p_phan_doi_id              IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai               IN NUMBER    DEFAULT NULL,
    p_co_benh_tat              IN NUMBER    DEFAULT NULL,
    p_giam_rieng               IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so         IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi   IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi             IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao            IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai             IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi       IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep           IN NUMBER    DEFAULT NULL,
    p_chung_than               IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat            IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet      IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg            IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong      IN NUMBER    DEFAULT NULL,
    p_co_tien_an               IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai     IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien       IN NUMBER    DEFAULT NULL,
    p_co_tien_su               IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh       IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien   IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien   IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

         selected_toi_danh_filter AS (
             SELECT TRIM(REGEXP_SUBSTR(
                             REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                             '[^,]+', 1, LEVEL)) AS ma_loc
             FROM DUAL
             CONNECT BY LEVEL <= REGEXP_COUNT(
                                     REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                     ',') + 1),

         chung_than_ids AS (
             SELECT dmtg.ID
             FROM DM_MA_THOI_GIANS dmtg
             WHERE dmtg.MTG_MA IN ('911000', '912000')
               AND dmtg.IS_DELETED = 0
         ),

         pn_base AS (
             SELECT
                 ll.*,
                 CASE
                     WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                     WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                         THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                     ELSE NULL
                 END AS SO_TIEN_AN_NUM,
                 QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
             FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
             INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                 ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                AND tt.NGAY_XET = v_ngay_tinh
                AND tt.TTPN_MA IN ('111', '112', '113', '114')
             WHERE ll.IS_DELETED = 0
               AND NVL(ll.LL_IS_DELETED, 0) = 0
               AND NVL(ll.THA_IS_DELETED, 0) = 0
               AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
         ),

         pham_nhan_filtered AS (
             SELECT
                 ll.PHAM_NHAN_ID                AS pham_nhan_id,
                 ll.LL_DM_GIOI_TINH_ID
             FROM pn_base ll
             LEFT JOIN DM_QUOC_TICHS dqt
                 ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                AND dqt.IS_DELETED = 0
             LEFT JOIN DM_TRAI_GIAMS dtg
                 ON dtg.ID = ll.LL_TRAI_GIAM_ID
                AND dtg.IS_DELETED = 0
-- FILTER START
             WHERE ll.IS_DELETED = 0
               AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

               -- NHOM 1: Khoang ngay
               AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
               AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
               AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
               AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
               AND (
                   (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                   OR EXISTS (
                       SELECT 1
                       FROM PN_DAC_XAS dxa
                       WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                         AND dxa.IS_DELETED = 0
                         AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                         AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                   )
               )
               AND (
                   (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                   OR EXISTS (
                       SELECT 1
                       FROM GIAM_THOI_HANS gaan
                       WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                         AND gaan.IS_DELETED = 0
                         AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                   )
               )

               -- NHOM 2: Khoang so
               AND (
                   p_so_tien_an_tu IS NULL
                   OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
               )
               AND (
                   p_so_tien_an_den IS NULL
                   OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
               )
               AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
               AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
               AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
               AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
               AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
               AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
               AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
               AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)

               -- NHOM 3: Danh muc
               AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
               AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
               AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
               AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
               AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
               AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

               -- [Toi danh]
               AND (
                   p_toi_danh_ids IS NULL
                   OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                   OR EXISTS (SELECT 1
                              FROM selected_toi_danh_filter loc
                              WHERE INSTR(
                                        ',' || REPLACE(
                                                REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                ' ', '') || ',',
                                        ',' || TRIM(loc.ma_loc) || ','
                                    ) > 0)
               )
               AND (p_dp_dktt_id       IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
               AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG              = p_loai_doi_tuong_id)

               -- [Ghi chu rieng]
               AND (
                   p_ghi_chu_rieng_id IS NULL
                   OR INSTR(
                              ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                              ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                          ) > 0
               )

               AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

               -- NHOM 4: Checkbox

               -- [Nuoc ngoai]
               AND (p_nuoc_ngoai IS NULL OR (
                   CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
               ))

               -- [Co benh tat]
               AND (p_co_benh_tat IS NULL OR (
                   CASE
                       WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                           THEN 1
                       WHEN EXISTS (
                           SELECT 1
                           FROM DM_BENH_TATS dbt
                           WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                             AND dbt.IS_DELETED = 0
                             AND dbt.BT_MA = '1'
                       )
                           THEN 0
                       ELSE 1
                   END = p_co_benh_tat
               ))

               -- [Giam rieng]
               AND (p_giam_rieng IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM PN_GIAM_RIENGS gr
                       WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                         AND gr.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_giam_rieng
               ))

               -- [Dan toc thieu so]
               AND (
                   p_dan_toc_thieu_so IS NULL
                   OR (
                       CASE
                           WHEN EXISTS (
                               SELECT 1
                               FROM DM_DAN_TOCS dt
                               WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                                 AND dt.IS_DELETED = 0
                                 AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                           )
                           THEN 1
                           ELSE 0
                       END = p_dan_toc_thieu_so
                   )
               )

               -- [VTN tai thoi diem pham toi]
               AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                   CASE
                       WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                       WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                       WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                       ELSE 0
                   END = p_vtn_thoi_diem_pham_toi
               ))

               -- [Pham toi moi]
               AND (p_pham_toi_moi IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM PHAM_TOI_MOIS ptm
                       WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                         AND ptm.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_pham_toi_moi
               ))

               -- [Theo ton giao]
               AND (p_theo_ton_giao IS NULL OR (
                   CASE
                       WHEN EXISTS (
                           SELECT 1
                           FROM DM_TON_GIAOS tg
                           WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                             AND tg.IS_DELETED = 0
                       )
                       THEN 1
                       ELSE 0
                   END = p_theo_ton_giao
               ))

               -- [VTN tai thoi diem hien tai]
               AND (p_vtn_hien_tai IS NULL OR (
                   CASE
                       WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                       WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                       ELSE 0
                   END = p_vtn_hien_tai
               ))

               -- [Khong pham toi moi]
               AND (p_khong_pham_toi_moi IS NULL OR (
                   CASE WHEN NOT EXISTS (
                       SELECT 1 FROM PHAM_TOI_MOIS ptm
                       WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                         AND ptm.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
               ))

               -- [Co nghe nghiep]
               AND (
                   p_co_nghe_nghiep IS NULL
                   OR (
                       CASE
                           WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                                AND EXISTS (
                                    SELECT 1
                                    FROM DM_NGHE_NGHIEPS dnn
                                    WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                      AND dnn.IS_DELETED = 0
                                      AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                                )
                           THEN 1
                           ELSE 0
                       END = p_co_nghe_nghiep
                   )
               )

               -- [Chung than]
               AND (p_chung_than IS NULL OR (
                   CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                        THEN 1 ELSE 0 END = p_chung_than
               ))

               -- [Da bi ky luat]
               AND (p_da_bi_ky_luat IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM KY_LUATS kl
                       WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                   ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
               ))

               -- [Co ghi chu dac biet]
               AND (p_co_ghi_chu_dac_biet IS NULL OR (
                   CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                         AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                        THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
               ))

               -- [Toi pham ANQG]
               AND (p_toi_pham_anqg IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM DM_TOI_DANHS td
                       WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                         AND td.IS_DELETED = 0
                         AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                   ) THEN 1 ELSE 0 END = p_toi_pham_anqg
               ))

               -- [Da duoc khen thuong]
               AND (p_da_duoc_khen_thuong IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM KHEN_THUONGS kt
                       WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                         AND kt.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
               ))

               -- [Co tien an]
               AND (p_co_tien_an IS NULL OR (
                   CASE
                       WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                           THEN 1
                       ELSE 0 END = p_co_tien_an
               ))

               -- [Co tien su]
               AND (p_co_tien_su IS NULL OR (
                   CASE
                       WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                           THEN 1
                       ELSE 0 END = p_co_tien_su
               ))

               -- [Con theo me vao trai]
               AND (p_con_theo_me_vao_trai IS NULL OR (
                   CASE WHEN EXISTS (
                       SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                       WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                         AND tncc.IS_DELETED = 0
                   ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
               ))

               -- [Hinh phat bo sung la tien]
               AND (p_hp_bo_sung_la_tien IS NULL OR (
                   CASE
                       WHEN EXISTS (SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                             AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                       ELSE 0 END = p_hp_bo_sung_la_tien
               ))

               -- [Bat buoc chua benh]
               AND (p_bat_buoc_chua_benh IS NULL OR (
                   CASE
                       WHEN EXISTS (SELECT 1
                                    FROM CHUA_BENH_BAT_BUOCS cb
                                    WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                      AND cb.IS_DELETED = 0
                                      -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                      -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                    ) THEN 1
                       ELSE 0 END = p_bat_buoc_chua_benh
               ))

               -- [Hoan xong HPBS la tien]
               AND (
                   p_hoan_xong_hpbs_la_tien IS NULL OR
                   (CASE
                       WHEN EXISTS (
                           SELECT 1
                           FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                           LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                             ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                            AND dhpbs.IS_DELETED = 0
                           WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                             AND hpbs.IS_DELETED = 0
                             AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                           GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                           HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                       ) THEN 1
                       ELSE 0
                   END = p_hoan_xong_hpbs_la_tien)
               )

               -- [Chua hoan xong HPBS la tien]
               AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                   (CASE
                       WHEN EXISTS (
                           SELECT 1
                           FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                           LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                             ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                            AND dhpbs.IS_DELETED = 0
                           WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                             AND hpbs.IS_DELETED = 0
                             AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                           GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                           HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                       ) THEN 1
                       ELSE 0
                   END = p_chua_hoan_hpbs_la_tien))
         ),
-- FILTER DONE

    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC))) AS "TT",
            ldkl.LDKL_TEN AS "NguyenNhanKyLuat",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END) AS "Nam",
            COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END) AS "Nu",
            COUNT(CASE WHEN gt.GT_TEN IS NULL
                            OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*) AS "TongSo"
        FROM QLPN.KY_LUATS kl
        INNER JOIN pham_nhan_filtered pnf
            ON pnf.pham_nhan_id = kl.PHAM_NHAN_ID
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = pnf.LL_DM_GIOI_TINH_ID
           AND gt.IS_DELETED = 0
        OUTER APPLY (
            SELECT d.LDKL_TEN
              FROM JSON_TABLE(
                       CASE WHEN kl.MA_LY_DO_KY_LUAT_IDS IS JSON
                            THEN kl.MA_LY_DO_KY_LUAT_IDS
                            ELSE u'[' || TO_CHAR(kl.MA_LY_DO_KY_LUAT_ID) || u']'
                       END,
                       '$[*]' COLUMNS (ly_do_id NUMBER PATH '$')) jt
              JOIN QLPN.DM_LY_DO_KY_LUATS d
                ON d.ID = jt.ly_do_id
               AND d.IS_DELETED = 0
        ) ldkl
        WHERE (v_ngay_tinh IS NULL OR TRUNC(NVL(kl.NGAY_DE_NGHI_KY_LUAT,kl.NGAY_QUYET_DINH)) < TRUNC(v_ngay_tinh) + 1)
        GROUP BY ldkl.LDKL_TEN
    )

    SELECT
        "TT",
        "NguyenNhanKyLuat",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
            "NguyenNhanKyLuat",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_KY_LUAT;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_LOAI_DOI_TUONG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_LOAI_DOI_TUONG" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID,
            ll.THA_DOI_TUONG
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
           AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
           AND dqt.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)
          -- NHOM 1: Khoang ngay
          AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
          AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
          AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
          AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
          AND (
              (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM PN_DAC_XAS dxa
                  WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND dxa.IS_DELETED = 0
                    AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                    AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
              )
          )
          AND (
              (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM GIAM_THOI_HANS gaan
                  WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND gaan.IS_DELETED   = 0
                    AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                    AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
              )
          )
          -- NHOM 2: Khoang so
          AND (
              p_so_tien_an_tu IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
          )
          AND (
              p_so_tien_an_den IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
          )
          AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
          AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
          AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
          AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
          AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
          AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
          AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
          AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
          -- NHOM 3: Danh muc
          AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
          AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
          AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
          AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
          AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
          AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
          -- [Toi danh] input dang [123,453] hoac 123,453
          AND (
              p_toi_danh_ids IS NULL
              OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
              OR EXISTS (SELECT 1
                         FROM selected_toi_danh_filter loc
                         WHERE INSTR(
                                     ',' || REPLACE(
                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                             ' ', '') || ',',
                                     ',' || TRIM(loc.ma_loc) || ','
                             ) > 0)
          )
          AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
          AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)
          -- [Ghi chu rieng] input dang 123
          AND (
              p_ghi_chu_rieng_id IS NULL
              OR INSTR(
                         ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                         ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                     ) > 0
          )
          AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)
          -- NHOM 4: Checkbox
          -- [Nuoc ngoai]
          AND (p_nuoc_ngoai IS NULL OR (
              CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
          ))
          -- [Co benh tat]
          AND (p_co_benh_tat IS NULL OR (
              CASE
                  WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                      THEN 1
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_BENH_TATS dbt
                      WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                  )
                      THEN 0
                  ELSE 1
              END = p_co_benh_tat
          ))
          -- [Giam rieng]
          AND (p_giam_rieng IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PN_GIAM_RIENGS gr
                  WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND gr.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_giam_rieng
          ))
          -- [Dan toc thieu so]
          AND (
              p_dan_toc_thieu_so IS NULL
              OR (
                  CASE
                      WHEN EXISTS (
                          SELECT 1
                          FROM DM_DAN_TOCS dt
                          WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                            AND dt.IS_DELETED = 0
                            AND NVL(dt.DT_MA, 'NULL') NOT IN ('1', '55')
                      )
                      THEN 1
                      ELSE 0
                  END = p_dan_toc_thieu_so
              )
          )
          -- [VTN tai thoi diem pham toi]
          AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
              CASE
                  WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_thoi_diem_pham_toi
          ))
          -- [Pham toi moi]
          AND (p_pham_toi_moi IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_pham_toi_moi
          ))
          -- [Theo ton giao]
          AND (p_theo_ton_giao IS NULL OR (
              CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_TON_GIAOS tg
                      WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                        AND tg.IS_DELETED = 0
                  )
                  THEN 1
                  ELSE 0
              END = p_theo_ton_giao
          ))
          -- [VTN hien tai]
          AND (p_vtn_hien_tai IS NULL OR (
              CASE
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_hien_tai
          ))
          -- [Khong pham toi moi]
          AND (p_khong_pham_toi_moi IS NULL OR (
              CASE WHEN NOT EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
          ))
          -- [Co nghe nghiep]
          AND (
              p_co_nghe_nghiep IS NULL
              OR (
                  CASE
                      WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                           AND EXISTS (
                               SELECT 1
                               FROM DM_NGHE_NGHIEPS dnn
                               WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                 AND dnn.IS_DELETED = 0
                                 AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                           )
                      THEN 1
                      ELSE 0
                  END = p_co_nghe_nghiep
              )
          )
          -- [Chung than]
          AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
          -- [Da bi ky luat]
          AND (p_da_bi_ky_luat IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KY_LUATS kl
                  WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
              ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
          ))
          -- [Co ghi chu dac biet]
          AND (p_co_ghi_chu_dac_biet IS NULL OR (
              CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                    AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                   THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
          ))
          -- [Toi pham ANQG]
          AND (p_toi_pham_anqg IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM DM_TOI_DANHS td
                  WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                    AND td.IS_DELETED = 0
                    AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
              ) THEN 1 ELSE 0 END = p_toi_pham_anqg
          ))
          -- [Da duoc khen thuong]
          AND (p_da_duoc_khen_thuong IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KHEN_THUONGS kt
                  WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND kt.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
          ))
          -- [Co tien an]
          AND (p_co_tien_an IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_an
          ))
          -- [Co tien su]
          AND (p_co_tien_su IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_su
          ))
          -- [Con theo me vao trai]
          AND (p_con_theo_me_vao_trai IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                  WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND tncc.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
          ))
          -- [Hinh phat bo sung la tien]
          AND (p_hp_bo_sung_la_tien IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                         ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                        AND dhpbs.IS_DELETED = 0
                               WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                 AND hpbs.IS_DELETED = 0
                                 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                  ELSE 0 END = p_hp_bo_sung_la_tien
          ))
          -- [Bat buoc chua benh]
          AND (p_bat_buoc_chua_benh IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM CHUA_BENH_BAT_BUOCS cb
                               WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                 AND cb.IS_DELETED = 0
                                 ) THEN 1
                  ELSE 0 END = p_bat_buoc_chua_benh
          ))
          -- [Hoan xong HPBS la tien]
          AND (
              p_hoan_xong_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                  ) THEN 1
                  ELSE 0
              END = p_hoan_xong_hpbs_la_tien)
          )
          -- [Chua hoan xong HPBS la tien]
          AND (p_chua_hoan_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                  ) THEN 1
                  ELSE 0
              END = p_chua_hoan_hpbs_la_tien))
    ),

    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC))) AS "TT",
            dldt.LDT_TEN AS "LoaiDoiTuong",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END)                                     AS "Nam",
            COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END)                                  AS "Nu",
            COUNT(CASE WHEN gt.GT_TEN IS NULL
                            OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN 1 END)                AS "Khac",
            COUNT(*)                                                                             AS "TongSo"
        FROM pham_nhan_filtered ll
        LEFT JOIN DM_LOAI_DOI_TUONGS dldt
            ON dldt.ID = ll.THA_DOI_TUONG
           AND dldt.IS_DELETED = 0
        LEFT JOIN DM_GIOI_TINHS gt
            ON gt.ID = ll.LL_DM_GIOI_TINH_ID
           AND gt.IS_DELETED = 0
        GROUP BY dldt.ID, dldt.LDT_TEN
    )

    SELECT
        "TT",
        "LoaiDoiTuong",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
            "LoaiDoiTuong",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_LOAI_DOI_TUONG;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_LOAI_PHAM_NHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_LOAI_PHAM_NHAN" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH
             selected_toi_danh_filter AS (SELECT TRIM(REGEXP_SUBSTR(
                                                     REPLACE(
                                                             REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''),
                                                             ' ', ''),
                                                     '[^,]+', 1, LEVEL)) AS ma_loc
                                          FROM DUAL
                                          CONNECT BY LEVEL <= REGEXP_COUNT(
                                                                      REPLACE(
                                                                              REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''),
                                                                              ' ', ''),
                                                                      ',') + 1),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ),
             pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID,
            ll.THA_NGAY_HET_HAN,
            ll.THA_NGAY_DEN_TRAI,
            ll.THA_DOI_TUONG
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON  dtg.ID = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED         = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
            AND dqt.IS_DELETED = 0
        WHERE
            ll.IS_DELETED = 0
            AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)

            -- NHÓM 1: Kho?ng ngày
            AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
            AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
            AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
            AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
            AND (
				    (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM PN_DAC_XAS dxa
				        WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
				          AND dxa.IS_DELETED = 0
				          AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
				          AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
				    )
				)
			AND (
				    (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM GIAM_THOI_HANS gaan
				        WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
				          AND gaan.IS_DELETED   = 0
				          AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
				          AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
				    )
				)

            -- NHÓM 2: Kho?ng s?
            AND (
                p_so_tien_an_tu IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
            )
            AND (
                p_so_tien_an_den IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
            )
            AND (p_muc_an_tu      IS NULL OR ll.THA_MA_AN_PHAT       >= p_muc_an_tu)
            AND (p_muc_an_den     IS NULL OR ll.THA_MA_AN_PHAT       <= p_muc_an_den)
            AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
            AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
            AND (p_tg_chap_hanh_tu  IS NULL OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
			AND (p_tg_chap_hanh_den IS NULL OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
            AND (p_tg_con_lai_tu  IS NULL OR
                    ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
            AND (p_tg_con_lai_den IS NULL OR
                    ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

            -- NHÓM 3: Danh m?c
            AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
            AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
            AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
            AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
            AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
            AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

            -- [T?i danh]
			AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
            AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id  )
            AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

            -- [Ghi chú riêng]
            AND (
                p_ghi_chu_rieng_id IS NULL
                OR INSTR(
                    ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                    ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                ) > 0
            )

            AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

            -- NHÓM 4: Checkbox
            AND (p_nuoc_ngoai IS NULL OR (
                CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
            ))
            AND (p_co_benh_tat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM CHUA_BENH_BAT_BUOCS cb
                    WHERE  cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND cb.IS_DELETED = 0
                ) OR EXISTS (
                    SELECT 1 FROM PN_SUC_KHOES sk
                    WHERE  sk.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND sk.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_co_benh_tat
            ))
            AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
            ))
            AND (p_dan_toc_thieu_so IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_DAN_TOCS dt
                    WHERE  dt.ID         = ll.LL_DM_DAN_TOC_ID
                    AND    dt.IS_DELETED = 0
                    AND    UPPER(dt.DT_TEN) <> u'KINH'
                ) THEN 1 ELSE 0 END = p_dan_toc_thieu_so
            ))
            AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                CASE
                    WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_thoi_diem_pham_toi
            ))
            AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
            ))
            AND (p_theo_ton_giao IS NULL OR (
                    CASE WHEN ll.LL_DM_TON_GIAO_ID <> 9 THEN 1 ELSE 0 END = p_theo_ton_giao))
            AND (p_vtn_hien_tai IS NULL OR (
                CASE
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_hien_tai
            ))
            AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
            ))
            AND (p_co_nghe_nghiep IS NULL OR (
                CASE WHEN  EXISTS (
                    SELECT 1 FROM DM_NGHE_NGHIEPS dnn
                    WHERE  dnn.ID         = ll.LL_DM_NGHE_NGHIEP_ID
                    AND    dnn.IS_DELETED = 0
                    AND    dnn.NN_TEN NOT LIKE '%Không%'
                ) THEN 1 ELSE 0 END = p_co_nghe_nghiep
            ))
            AND (p_chung_than IS NULL OR (
    CASE WHEN ll.THA_MA_AN_PHAT IN (
        SELECT dmtg.ID FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000') AND dmtg.IS_DELETED = 0
    ) THEN 1 ELSE 0 END = p_chung_than
))
            AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
            ))
            AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
            ))
            AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))
            AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
            ))
            AND (p_co_tien_an IS NULL OR (
			    CASE WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
			         THEN 1 ELSE 0 END = p_co_tien_an
			))
            AND (p_co_tien_su IS NULL OR (
			    CASE WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
			         THEN 1 ELSE 0 END = p_co_tien_su
			))
            AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
            ))
            AND (p_hp_bo_sung_la_tien IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON  dhpbs.ID         = hpbs.HPBS_HINH_PHAT
                        AND dhpbs.IS_DELETED = 0
                    WHERE  hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                    AND    hpbs.IS_DELETED         = 0
                    AND    dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                ) THEN 1 ELSE 0 END = p_hp_bo_sung_la_tien
            ))
            AND (p_bat_buoc_chua_benh IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM CHUA_BENH_BAT_BUOCS cb
                    WHERE  cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND cb.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_bat_buoc_chua_benh
            ))
            AND (p_hoan_xong_hpbs_la_tien IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON  dhpbs.ID         = hpbs.HPBS_HINH_PHAT
                        AND dhpbs.IS_DELETED = 0
                    WHERE  hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                    AND    hpbs.IS_DELETED         = 0
                    AND    dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                    AND    hpbs.HPBS_TONG_TIEN_CON_LAI <= 0
                ) THEN 1 ELSE 0 END = p_hoan_xong_hpbs_la_tien
            ))
            AND (p_chua_hoan_hpbs_la_tien IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON  dhpbs.ID         = hpbs.HPBS_HINH_PHAT
                        AND dhpbs.IS_DELETED = 0
                    WHERE  hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                    AND    hpbs.IS_DELETED         = 0
                    AND    dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                    AND    hpbs.HPBS_TONG_TIEN_CON_LAI > 0
                ) THEN 1 ELSE 0 END = p_chua_hoan_hpbs_la_tien
            ))
    ),

    chi_tiet AS (		    
		 SELECT
            ROW_NUMBER() OVER (ORDER BY NVL(plgg.PLGG_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY NVL(plgg.PLGG_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')))) AS "TT",
            NVL(plgg.PLGG_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh') AS "PhanLoaiGiamGiu",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'Nam' THEN ll.PHAM_NHAN_ID END)                                      AS "Nam",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'N\1eef' THEN ll.PHAM_NHAN_ID END)                                   AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(gt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN ll.PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT ll.PHAM_NHAN_ID)                                                                              AS "TongSo"
        FROM PHAN_LOAIS pl
        INNER JOIN pham_nhan_filtered ll
            ON ll.PHAM_NHAN_ID = pl.PHAM_NHAN_ID
        LEFT JOIN DM_GIOI_TINHS gt
            ON gt.ID = ll.LL_DM_GIOI_TINH_ID
           AND gt.IS_DELETED = 0
        LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS plgg
            ON plgg.ID = pl.DEN_LOAI_ID
           AND plgg.IS_DELETED = 0
        WHERE pl.IS_DELETED = 0
        GROUP BY NVL(plgg.PLGG_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')
		)

    SELECT
        	"TT",
	        "PhanLoaiGiamGiu",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
			"TT",
	        "PhanLoaiGiamGiu",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_LOAI_PHAM_NHAN;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_LY_DO_GIAM_RIENG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_LY_DO_GIAM_RIENG" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH
    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID,
            ll.LL_DM_QUOC_TICH_ID,
            ll.THA_NGAY_HET_HAN,
            ll.THA_NGAY_DEN_TRAI,
            ll.THA_DOI_TUONG,
            ll.LL_GHI_CHU_RIENG
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON  dtg.ID = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
            AND dqt.IS_DELETED = 0
        WHERE
            (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)

            AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
            AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
            AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
            AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
            AND (
                (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                OR EXISTS (
                    SELECT 1
                    FROM PN_DAC_XAS dxa
                    WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                      AND dxa.IS_DELETED = 0
                      AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                      AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                )
            )
            AND (
                (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                OR EXISTS (
                    SELECT 1
                    FROM GIAM_THOI_HANS gaan
                    WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                      AND gaan.IS_DELETED   = 0
                      AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                      AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                )
            )

            AND (
                p_so_tien_an_tu IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
            )
            AND (
                p_so_tien_an_den IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
            )
            AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
            AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
            AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
            AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
            AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
            AND (p_tg_con_lai_tu  IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
            AND (p_tg_con_lai_den IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

            AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
            AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
            AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
            AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
            AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
            AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

            AND (
                p_toi_danh_ids IS NULL
                    OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                    OR EXISTS (SELECT 1
                               FROM selected_toi_danh_filter loc
                               WHERE INSTR(
                                             ',' || REPLACE(
                                                     REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                     ' ', '') || ',',
                                             ',' || TRIM(loc.ma_loc) || ','
                                     ) > 0)
            )
            AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
            AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

            AND (
                p_ghi_chu_rieng_id IS NULL
                    OR INSTR(
                               ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                               ',',
                               ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                       ) > 0
            )

            AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

            AND (p_nuoc_ngoai IS NULL OR (
                CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
            ))
            AND (p_co_benh_tat IS NULL OR (
                CASE
                    WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                        THEN 1
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_BENH_TATS dbt
                        WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                    )
                        THEN 0
                    ELSE 1
                END = p_co_benh_tat
            ))
            AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
            ))
            AND (
                p_dan_toc_thieu_so IS NULL
                OR (
                    CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_DAN_TOCS dt
                            WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                              AND dt.IS_DELETED = 0
                              AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                        )
                        THEN 1
                        ELSE 0
                    END = p_dan_toc_thieu_so
                )
            )
            AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                CASE
                    WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_thoi_diem_pham_toi
            ))
            AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
            ))
            AND (p_theo_ton_giao IS NULL OR (
                CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_TON_GIAOS tg
                        WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                          AND tg.IS_DELETED = 0
                    )
                    THEN 1
                    ELSE 0
                END = p_theo_ton_giao ))
            AND (p_vtn_hien_tai IS NULL OR (
                CASE
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_hien_tai
            ))
            AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
            ))
            AND (
                p_co_nghe_nghiep IS NULL
                OR (
                    CASE
                        WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                             AND EXISTS (
                                    SELECT 1
                                    FROM DM_NGHE_NGHIEPS dnn
                                    WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                      AND dnn.IS_DELETED = 0
                                      AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                             )
                        THEN 1
                        ELSE 0
                    END = p_co_nghe_nghiep
                )
            )
            AND (p_chung_than IS NULL OR (
                CASE
                    WHEN ll.THA_MA_AN_PHAT IN (
                        SELECT dmtg.ID
                        FROM DM_MA_THOI_GIANS dmtg
                        WHERE dmtg.MTG_MA IN ('911000', '912000')
                          AND dmtg.IS_DELETED = 0
                    ) THEN 1
                    ELSE 0
                END = p_chung_than
            ))
            AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
            ))
            AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
            ))
            AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))
            AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
            ))
            AND (p_co_tien_an IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_an
            ))
            AND (p_co_tien_su IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_su
            ))
            AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
            ))
            AND (p_hp_bo_sung_la_tien IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                          LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                    ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                        AND dhpbs.IS_DELETED = 0
                                 WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                   AND hpbs.IS_DELETED = 0
                                   AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                    ELSE 0 END = p_hp_bo_sung_la_tien
            ))
            AND (p_bat_buoc_chua_benh IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM CHUA_BENH_BAT_BUOCS cb
                                 WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                   	AND cb.IS_DELETED = 0
                                       ) THEN 1
                    ELSE 0 END = p_bat_buoc_chua_benh
            ))
            AND (
                p_hoan_xong_hpbs_la_tien IS NULL OR
                (CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                            LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                             AND dhpbs.IS_DELETED = 0
                            WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                              AND hpbs.IS_DELETED = 0
                              AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                            HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                        ) THEN 1
                        ELSE 0
                    END = p_hoan_xong_hpbs_la_tien))
            AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                ( CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                            LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                             AND dhpbs.IS_DELETED = 0
                            WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                              AND hpbs.IS_DELETED = 0
                              AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                            HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                        ) THEN 1
                        ELSE 0
                    END = p_chua_hoan_hpbs_la_tien))),

    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ))) AS "TT",
            dldgrpn.LDGRPN_TEN AS "LyDoGiamRieng",
           COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END) AS "Nam",
           COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END) AS "Nu",
           COUNT(CASE WHEN gt.GT_TEN IS NULL
                      OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
           COUNT(*)                   AS "TongSo"
        FROM PN_GIAM_RIENGS pgr 
        INNER JOIN pham_nhan_filtered pnf ON pgr.GR_PN_LAI_LICH_ID  = pnf.PHAM_NHAN_ID
        LEFT JOIN DM_GIOI_TINHS gt ON pnf.LL_DM_GIOI_TINH_ID = gt.ID
        LEFT JOIN DM_LY_DO_GIAM_RIENG_PHAM_NHANS dldgrpn ON pgr.GR_LY_DO = TO_NCHAR (dldgrpn.ID) AND dldgrpn.IS_DELETED = 0
        WHERE pgr.IS_DELETED = 0
          AND (v_ngay_tinh IS NULL OR pgr.GR_NGAY_QUYET_DINH_GIAM_RIENG IS NULL 
               OR (TRUNC(pgr.GR_NGAY_QUYET_DINH_GIAM_RIENG) < TRUNC(v_ngay_tinh) + 1) )
        GROUP BY dldgrpn.ID, dldgrpn.LDGRPN_TEN 
    )

    SELECT
        	"TT",
	        "LyDoGiamRieng",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"

    FROM (
        SELECT
            SORT_ORDER,
            "TT",
	        "LyDoGiamRieng",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_LY_DO_GIAM_RIENG;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_LY_DO_KHEN_THUONG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_LY_DO_KHEN_THUONG" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH
    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID,
            ll.THA_NGAY_HET_HAN,
            ll.THA_NGAY_DEN_TRAI,
            ll.THA_DOI_TUONG
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON  dtg.ID = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
            AND dqt.IS_DELETED = 0
        WHERE
            (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)

            AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
            AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
            AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
            AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
            AND (
                (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                OR EXISTS (
                    SELECT 1
                    FROM PN_DAC_XAS dxa
                    WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                      AND dxa.IS_DELETED = 0
                      AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                      AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                )
            )
            AND (
                (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                OR EXISTS (
                    SELECT 1
                    FROM GIAM_THOI_HANS gaan
                    WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                      AND gaan.IS_DELETED   = 0
                      AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                      AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                )
            )

            AND (
                p_so_tien_an_tu IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
            )
            AND (
                p_so_tien_an_den IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
            )
            AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
            AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
            AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
            AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
            AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
            AND (p_tg_con_lai_tu  IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
            AND (p_tg_con_lai_den IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

            AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
            AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
            AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
            AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
            AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
            AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

            AND (
                p_toi_danh_ids IS NULL
                    OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                    OR EXISTS (SELECT 1
                               FROM selected_toi_danh_filter loc
                               WHERE INSTR(
                                             ',' || REPLACE(
                                                     REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                     ' ', '') || ',',
                                             ',' || TRIM(loc.ma_loc) || ','
                                     ) > 0)
            )
            AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
            AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

            AND (
                p_ghi_chu_rieng_id IS NULL
                    OR INSTR(
                               ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                               ',',
                               ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                       ) > 0
            )

            AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

            AND (p_nuoc_ngoai IS NULL OR (
                CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
            ))
            AND (p_co_benh_tat IS NULL OR (
                CASE
                    WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                        THEN 1
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_BENH_TATS dbt
                        WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                    )
                        THEN 0
                    ELSE 1
                END = p_co_benh_tat
            ))
            AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
            ))
            AND (
                p_dan_toc_thieu_so IS NULL
                OR (
                    CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_DAN_TOCS dt
                            WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                              AND dt.IS_DELETED = 0
                              AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                        )
                        THEN 1
                        ELSE 0
                    END = p_dan_toc_thieu_so
                )
            )
            AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                CASE
                    WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_thoi_diem_pham_toi
            ))
            AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
            ))
            AND (p_theo_ton_giao IS NULL OR (
                CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_TON_GIAOS tg
                        WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                          AND tg.IS_DELETED = 0
                    )
                    THEN 1
                    ELSE 0
                END = p_theo_ton_giao ))

            AND (p_vtn_hien_tai IS NULL OR (
                CASE
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_hien_tai
            ))

            AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
            ))
            AND (
                p_co_nghe_nghiep IS NULL
                OR (
                    CASE
                        WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                             AND EXISTS (
                                    SELECT 1
                                    FROM DM_NGHE_NGHIEPS dnn
                                    WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                      AND dnn.IS_DELETED = 0
                                      AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                             )
                        THEN 1
                        ELSE 0
                    END = p_co_nghe_nghiep
                )
            )
            AND (p_chung_than IS NULL OR (
                CASE
                    WHEN ll.THA_MA_AN_PHAT IN (
                        SELECT dmtg.ID
                        FROM DM_MA_THOI_GIANS dmtg
                        WHERE dmtg.MTG_MA IN ('911000', '912000')
                          AND dmtg.IS_DELETED = 0
                    ) THEN 1
                    ELSE 0
                END = p_chung_than
            ))
            AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
            ))
            AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
            ))
            AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))
            AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
            ))
            AND (p_co_tien_an IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_an
            ))
            AND (p_co_tien_su IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_su
            ))
            AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
            ))
            AND (p_hp_bo_sung_la_tien IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                          LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                    ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                        AND dhpbs.IS_DELETED = 0
                                 WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                   AND hpbs.IS_DELETED = 0
                                   AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                    ELSE 0 END = p_hp_bo_sung_la_tien
            ))
            AND (p_bat_buoc_chua_benh IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM CHUA_BENH_BAT_BUOCS cb
                                 WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                   	AND cb.IS_DELETED = 0
                                       ) THEN 1
                    ELSE 0 END = p_bat_buoc_chua_benh
            ))
            AND (
                p_hoan_xong_hpbs_la_tien IS NULL OR
                (CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                            LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                             AND dhpbs.IS_DELETED = 0
                            WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                              AND hpbs.IS_DELETED = 0
                              AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                            HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                        ) THEN 1
                        ELSE 0
                    END = p_hoan_xong_hpbs_la_tien))
            AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                ( CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                            LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                             AND dhpbs.IS_DELETED = 0
                            WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                              AND hpbs.IS_DELETED = 0
                              AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                            HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                        ) THEN 1
                        ELSE 0
                    END = p_chua_hoan_hpbs_la_tien))
    ),

    chi_tiet AS (
    SELECT
        SORT_ORDER,
        TO_NCHAR(TO_CHAR(SORT_ORDER)) AS "TT",
        "LyDoKhenThuong",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            ROW_NUMBER() OVER ( ORDER BY COUNT(*) DESC ) AS SORT_ORDER,
            TO_NCHAR(ldk.LDK_TEN) AS "LyDoKhenThuong",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END) AS "Nam",
            COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END) AS "Nu",
            COUNT(CASE WHEN gt.GT_TEN IS NULL
                              OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*) AS "TongSo"
        FROM pham_nhan_filtered ll
        INNER JOIN KHEN_THUONGS kt
            ON  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
            AND kt.IS_DELETED   = 0
        CROSS JOIN LATERAL (
            SELECT TRIM(REGEXP_SUBSTR(
                           REPLACE(REPLACE(REPLACE(TO_CHAR(kt.MA_LY_DO_KHEN_ID), '[', ''), ']', ''), ' ', ''),
                           '[^,]+', 1, LEVEL
                       )) AS ldk_id_str
            FROM DUAL
            WHERE LENGTH(REPLACE(REPLACE(REPLACE(TO_CHAR(kt.MA_LY_DO_KHEN_ID), '[', ''), ']', ''), ' ', '')) > 0
            CONNECT BY LEVEL <= REGEXP_COUNT(
                           REPLACE(REPLACE(REPLACE(TO_CHAR(kt.MA_LY_DO_KHEN_ID), '[', ''), ']', ''), ' ', ''),
                           '[^,]+'
                       )
        ) kt_split
        LEFT JOIN DM_LY_DO_KHENS ldk
            ON  ldk.ID         = TO_NUMBER(kt_split.ldk_id_str)
            AND ldk.IS_DELETED = 0
        LEFT JOIN DM_GIOI_TINHS gt
            ON  gt.ID         = ll.LL_DM_GIOI_TINH_ID
            AND gt.IS_DELETED = 0
        WHERE
            (v_ngay_tinh IS NULL OR TRUNC(kt.NGAY_KHEN) < TRUNC(v_ngay_tinh) + 1)
        GROUP BY ldk.ID, ldk.LDK_TEN
    )
)

    SELECT
        	"TT",
            "LyDoKhenThuong",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
            "LyDoKhenThuong",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_LY_DO_KHEN_THUONG;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_MUC_AN_PHAT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_MUC_AN_PHAT" (
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
        WITH selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ),
             pham_nhan_filtered AS (SELECT ll.PHAM_NHAN_ID,
                                           ll.LL_DM_GIOI_TINH_ID,
                                           ll.LL_DM_QUOC_TICH_ID,
                                           ll.THA_NGAY_HET_HAN,
                                           ll.THA_NGAY_DEN_TRAI,
                                           ll.THA_DOI_TUONG,
                                           ll.THA_MUC_AN_ID,
                                           ll.LL_GHI_CHU_RIENG
                                    FROM pn_base ll
                                             LEFT JOIN DM_TRAI_GIAMS dtg
                                                       ON dtg.ID = ll.LL_TRAI_GIAM_ID
                                                           AND dtg.IS_DELETED = 0
                                             LEFT JOIN DM_QUOC_TICHS dqt
                                                       ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                                                           AND dqt.IS_DELETED = 0
                                    WHERE ll.IS_DELETED = 0
                                      AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)
                                      -- NHÓM 1: Kho?ng ngày
                                    AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                    AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                    AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                    AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                                      AND (
                                                (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                                                OR EXISTS (
                                                    SELECT 1
                                                    FROM PN_DAC_XAS dxa
                                                    WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                                                    AND dxa.IS_DELETED = 0
                                                    AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                                    AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                                                )
                                            )
                                      AND (
                                        (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM GIAM_THOI_HANS gaan
                                                       WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                         AND gaan.IS_DELETED = 0
                                                         AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                                        )

                                      -- NHÓM 2: Kho?ng s?
                                      AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
                                      AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                                      AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                                      AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                                      AND (p_tg_chap_hanh_tu IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                                      AND (p_tg_chap_hanh_den IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                                      AND (p_tg_con_lai_tu IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                                      AND (p_tg_con_lai_den IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                                      -- NHÓM 3: Danh m?c
                                      AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
                                      AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
                                      AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
                                      AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                                      AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
                                      AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

                                      -- [T?i danh]
                                      AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
                                      AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                                      AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG = p_loai_doi_tuong_id)

                                      -- [Ghi chú riêng]
                                      AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

                                      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                                      -- NHÓM 4: Checkbox
                                      AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
                                      AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
                                      AND (p_giam_rieng IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PN_GIAM_RIENGS gr
                                                         WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                                                           AND gr.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_giam_rieng
                                        ))
                                      AND (
									    p_dan_toc_thieu_so IS NULL
									    OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_DAN_TOCS dt
									                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
									                  AND dt.IS_DELETED = 0
									                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
									            )
									            THEN 1
									            ELSE 0
									        END = p_dan_toc_thieu_so
									    )
									)
                                      AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                                        CASE
                                            WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_thoi_diem_pham_toi
                                        ))
                                      AND (p_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PHAM_TOI_MOIS ptm
                                                         WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_pham_toi_moi
                                        ))
                                      AND (p_theo_ton_giao IS NULL OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_TON_GIAOS tg
									                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
									                  AND tg.IS_DELETED = 0

									            )
									            THEN 1
									            ELSE 0
									        END = p_theo_ton_giao ))
                                      AND (p_vtn_hien_tai IS NULL OR (
                                        CASE
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_hien_tai
                                        ))
                                      AND (p_khong_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN NOT EXISTS (SELECT 1
                                                             FROM PHAM_TOI_MOIS ptm
                                                             WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                               AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_khong_pham_toi_moi
                                        ))
                                      AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
                                      AND (p_chung_than IS NULL OR (
    CASE WHEN ll.THA_MA_AN_PHAT IN (
        SELECT dmtg.ID FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000') AND dmtg.IS_DELETED = 0
    ) THEN 1 ELSE 0 END = p_chung_than
))
                                      AND (p_da_bi_ky_luat IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KY_LUATS kl
                                                         WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID) THEN 1
                                            ELSE 0 END = p_da_bi_ky_luat
                                        ))
                                      AND (p_co_ghi_chu_dac_biet IS NULL OR (
                                        CASE
                                            WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                                                AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                                                THEN 1
                                            ELSE 0 END = p_co_ghi_chu_dac_biet
                                        ))
                                      AND (p_toi_pham_anqg IS NULL OR (
                                        CASE WHEN EXISTS (
                                            SELECT 1 FROM DM_TOI_DANHS td
                                            WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                                              AND td.IS_DELETED = 0
                                              AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                                        ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                                      ))
                                      AND (p_da_duoc_khen_thuong IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KHEN_THUONGS kt
                                                         WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND kt.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_da_duoc_khen_thuong
                                        ))
                                      AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
                                      AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
                                      AND (p_con_theo_me_vao_trai IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM THAN_NHAN_CON_CAIS tncc
                                                         WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND tncc.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_con_theo_me_vao_trai
                                        ))
                                      AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
                                      AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
                                      AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
                                      AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))),

             chi_tiet AS (SELECT ROW_NUMBER() OVER (ORDER BY dma.MA_TU DESC)                            AS SORT_ORDER,
                                 TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY dma.MA_TU DESC)))         AS "TT",
                                 dma.MA_TEN_CHI_TIEU                                                    AS "MucAnPhat",
                                 COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam' THEN pnf.PHAM_NHAN_ID END) AS "Nam",
                                 COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?' THEN pnf.PHAM_NHAN_ID END)  AS "Nu",
                                 COUNT(DISTINCT CASE
                                                    WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?')
                                                        THEN pnf.PHAM_NHAN_ID END)                      AS "Khac",
                                 COUNT(DISTINCT pnf.PHAM_NHAN_ID)                                       AS "TongSo"
                          FROM pham_nhan_filtered pnf
                                   LEFT JOIN DM_GIOI_TINHS dgt ON pnf.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
                                   LEFT JOIN DM_MUC_ANS dma ON pnf.THA_MUC_AN_ID = dma.ID AND dma.IS_DELETED = 0
                          WHERE dma.MA_TEN_CHI_TIEU IS NOT NULL
                          GROUP BY dma.ID, dma.MA_TU, dma.MA_TEN_CHI_TIEU)

        SELECT "TT",
               "MucAnPhat",
               "Nam",
               "Nu",
               "Khac",
               "TongSo"

        FROM (SELECT SORT_ORDER,
                     "TT",
                     "MucAnPhat",
                     "Nam",
                     "Nu",
                     "Khac",
                     "TongSo"
              FROM chi_tiet

              UNION ALL

              SELECT 999,
                     TO_NCHAR(''),
                     TO_NCHAR(u'T\1ed5ng s\1ed1'),
                     SUM("Nam"),
                     SUM("Nu"),
                     SUM("Khac"),
                     SUM("TongSo")
              FROM chi_tiet)
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_MUC_AN_PHAT;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_NGAY_DEN_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_NGAY_DEN_TRAI" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID,
            ll.THA_NGAY_HET_HAN,
            ll.THA_NGAY_DEN_TRAI
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON  dtg.ID = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
            AND dqt.IS_DELETED = 0
        WHERE
            (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)

            AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
            AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
            AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
            AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
            AND (
                (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                OR EXISTS (
                    SELECT 1
                    FROM PN_DAC_XAS dxa
                    WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                      AND dxa.IS_DELETED = 0
                      AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                      AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                )
            )
            AND (
                (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                OR EXISTS (
                    SELECT 1
                    FROM GIAM_THOI_HANS gaan
                    WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                      AND gaan.IS_DELETED   = 0
                      AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                      AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                )
            )

            AND (
                p_so_tien_an_tu IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
            )
            AND (
                p_so_tien_an_den IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
            )
            AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
            AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
            AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
            AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
            AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
            AND (p_tg_con_lai_tu  IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
            AND (p_tg_con_lai_den IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

            AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
            AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
            AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
            AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
            AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
            AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

            AND (
                p_toi_danh_ids IS NULL
                    OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                    OR EXISTS (SELECT 1
                               FROM selected_toi_danh_filter loc
                               WHERE INSTR(
                                             ',' || REPLACE(
                                                     REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                     ' ', '') || ',',
                                             ',' || TRIM(loc.ma_loc) || ','
                                     ) > 0)
            )
            AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
            AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

            AND (
                p_ghi_chu_rieng_id IS NULL
                    OR INSTR(
                               ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                               ',',
                               ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                       ) > 0
            )

            AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

            AND (p_nuoc_ngoai IS NULL OR (
                CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
            ))
            AND (p_co_benh_tat IS NULL OR (
                CASE
                    WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                        THEN 1
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_BENH_TATS dbt
                        WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                    )
                        THEN 0
                    ELSE 1
                END = p_co_benh_tat
            ))
            AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
            ))
            AND (
                p_dan_toc_thieu_so IS NULL
                OR (
                    CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_DAN_TOCS dt
                            WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                              AND dt.IS_DELETED = 0
                              AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                        )
                        THEN 1
                        ELSE 0
                    END = p_dan_toc_thieu_so
                )
            )
            AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                CASE
                    WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_thoi_diem_pham_toi
            ))
            AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
            ))
            AND (p_theo_ton_giao IS NULL OR (
                CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_TON_GIAOS tg
                        WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                          AND tg.IS_DELETED = 0
                    )
                    THEN 1
                    ELSE 0
                END = p_theo_ton_giao ))
            AND (p_vtn_hien_tai IS NULL OR (
                CASE
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_hien_tai
            ))
            AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
            ))
            AND (
                p_co_nghe_nghiep IS NULL
                OR (
                    CASE
                        WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                             AND EXISTS (
                                    SELECT 1
                                    FROM DM_NGHE_NGHIEPS dnn
                                    WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                      AND dnn.IS_DELETED = 0
                                      AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                             )
                        THEN 1
                        ELSE 0
                    END = p_co_nghe_nghiep
                )
            )
            AND (p_chung_than IS NULL OR (
                CASE
                    WHEN ll.THA_MA_AN_PHAT IN (
                        SELECT dmtg.ID
                        FROM DM_MA_THOI_GIANS dmtg
                        WHERE dmtg.MTG_MA IN ('911000', '912000')
                          AND dmtg.IS_DELETED = 0
                    ) THEN 1
                    ELSE 0
                END = p_chung_than
            ))
            AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
            ))
            AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
            ))
            AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))
            AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
            ))
            AND (p_co_tien_an IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_an
            ))
            AND (p_co_tien_su IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_su
            ))
            AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
            ))
            AND (p_hp_bo_sung_la_tien IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                          LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                    ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                        AND dhpbs.IS_DELETED = 0
                                 WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                   AND hpbs.IS_DELETED = 0
                                   AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                    ELSE 0 END = p_hp_bo_sung_la_tien
            ))
            AND (p_bat_buoc_chua_benh IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM CHUA_BENH_BAT_BUOCS cb
                                 WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                   	AND cb.IS_DELETED = 0
                                       ) THEN 1
                    ELSE 0 END = p_bat_buoc_chua_benh
            ))
            AND (
                p_hoan_xong_hpbs_la_tien IS NULL OR
                (CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                            LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                             AND dhpbs.IS_DELETED = 0
                            WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                              AND hpbs.IS_DELETED = 0
                              AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                            HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                        ) THEN 1
                        ELSE 0
                    END = p_hoan_xong_hpbs_la_tien))
            AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                ( CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                            LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                             AND dhpbs.IS_DELETED = 0
                            WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                              AND hpbs.IS_DELETED = 0
                              AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                            HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                        ) THEN 1
                        ELSE 0
                    END = p_chua_hoan_hpbs_la_tien))
    ),

    base AS (
        SELECT
            pnf.PHAM_NHAN_ID                            AS PN_ID,
            EXTRACT(YEAR  FROM pnf.THA_NGAY_DEN_TRAI)   AS NAM,
            EXTRACT(MONTH FROM pnf.THA_NGAY_DEN_TRAI)   AS THANG,
            dgt.GT_TEN
        FROM pham_nhan_filtered pnf
        LEFT JOIN DM_GIOI_TINHS dgt
            ON  dgt.ID         = pnf.LL_DM_GIOI_TINH_ID
            AND dgt.IS_DELETED = 0

    ),

    nam_rank AS (
        SELECT DISTINCT
            NAM,
            DENSE_RANK() OVER (ORDER BY NAM DESC) AS NAM_STT
        FROM base
    )

   SELECT
        "TT",
        "NamThang",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (

        SELECT
            nr.NAM_STT AS SORT_ORDER,
            TO_NCHAR(CASE nr.NAM_STT
				    WHEN 1  THEN 'I'
				    WHEN 2  THEN 'II'
				    WHEN 3  THEN 'III'
				    WHEN 4  THEN 'IV'
				    WHEN 5  THEN 'V'
				    WHEN 6  THEN 'VI'
				    WHEN 7  THEN 'VII'
				    WHEN 8  THEN 'VIII'
				    WHEN 9  THEN 'IX'
				    WHEN 10 THEN 'X'
				    WHEN 11 THEN 'XI'
				    WHEN 12 THEN 'XII'
				    WHEN 13 THEN 'XIII'
				    WHEN 14 THEN 'XIV'
				    WHEN 15 THEN 'XV'
				    WHEN 16 THEN 'XVI'
				    WHEN 17 THEN 'XVII'
				    WHEN 18 THEN 'XVIII'
				    WHEN 19 THEN 'XIX'
				    WHEN 20 THEN 'XX'
				    WHEN 21 THEN 'XXI'
				    WHEN 22 THEN 'XXII'
				    WHEN 23 THEN 'XXIII'
				    WHEN 24 THEN 'XXIV'
				    WHEN 25 THEN 'XXV'
				    WHEN 26 THEN 'XXVI'
				    WHEN 27 THEN 'XXVII'
				    WHEN 28 THEN 'XXVIII'
				    WHEN 29 THEN 'XXIX'
				    WHEN 30 THEN 'XXX'
				    WHEN 31 THEN 'XXXI'
				    WHEN 32 THEN 'XXXII'
				    WHEN 33 THEN 'XXXIII'
				    WHEN 34 THEN 'XXXIV'
				    WHEN 35 THEN 'XXXV'
				    WHEN 36 THEN 'XXXVI'
				    WHEN 37 THEN 'XXXVII'
				    WHEN 38 THEN 'XXXVIII'
				    WHEN 39 THEN 'XXXIX'
				    WHEN 40 THEN 'XL'
				    WHEN 41 THEN 'XLI'
				    WHEN 42 THEN 'XLII'
				    WHEN 43 THEN 'XLIII'
				    WHEN 44 THEN 'XLIV'
				    WHEN 45 THEN 'XLV'
				    WHEN 46 THEN 'XLVI'
				    WHEN 47 THEN 'XLVII'
				    WHEN 48 THEN 'XLVIII'
				    WHEN 49 THEN 'XLIX'
				    WHEN 50 THEN 'L'
				END) AS "TT",
            TO_NCHAR(u'N\0102M ') || TO_NCHAR(nr.NAM)                          AS "NamThang",
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'Nam'   THEN b.PN_ID END)     AS "Nam",
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'N\1eef' THEN b.PN_ID END)    AS "Nu",
            COUNT(DISTINCT CASE
                WHEN b.GT_TEN IS NULL
                  OR b.GT_TEN NOT IN (u'Nam', u'N\1eef')
                THEN b.PN_ID END)                                               AS "Khac",
            COUNT(DISTINCT b.PN_ID)                                             AS "TongSo"
        FROM base b
        LEFT JOIN nam_rank nr ON b.NAM = nr.NAM
        GROUP BY nr.NAM_STT, nr.NAM

        UNION ALL

        SELECT
            nr.NAM_STT + (ROW_NUMBER() OVER (PARTITION BY b.NAM ORDER BY b.THANG)) * 0.001,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (PARTITION BY b.NAM ORDER BY b.THANG))),
            TO_NCHAR(u'Th\00e1ng ') || TO_NCHAR(LPAD(b.THANG, 2, '0')),
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'Nam'   THEN b.PN_ID END),
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'N\1eef' THEN b.PN_ID END),
            COUNT(DISTINCT CASE
                WHEN b.GT_TEN IS NULL
                  OR b.GT_TEN NOT IN (u'Nam', u'N\1eef')
                THEN b.PN_ID END),
            COUNT(DISTINCT b.PN_ID)
        FROM base b
        LEFT JOIN nam_rank nr ON b.NAM = nr.NAM
        GROUP BY nr.NAM_STT, b.NAM, b.THANG

    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_NGAY_DEN_TRAI;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_NGAY_RA_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_NGAY_RA_TRAI" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID,
            ll.THA_NGAY_HET_HAN,
            ll.THA_NGAY_DEN_TRAI
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON  dtg.ID = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
            AND dqt.IS_DELETED = 0
        WHERE
            (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)
            AND ll.THA_NGAY_HET_HAN IS NOT NULL

            AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
            AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
            AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
            AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
            AND (
                (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                OR EXISTS (
                    SELECT 1
                    FROM PN_DAC_XAS dxa
                    WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                      AND dxa.IS_DELETED = 0
                      AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                      AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                )
            )
            AND (
                (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                OR EXISTS (
                    SELECT 1
                    FROM GIAM_THOI_HANS gaan
                    WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                      AND gaan.IS_DELETED   = 0
                      AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                      AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                )
            )

            AND (
                p_so_tien_an_tu IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
            )
            AND (
                p_so_tien_an_den IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
            )
            AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
            AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
            AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
            AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
            AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
            AND (p_tg_con_lai_tu  IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
            AND (p_tg_con_lai_den IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

            AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
            AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
            AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
            AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
            AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
            AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

            AND (
                p_toi_danh_ids IS NULL
                    OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                    OR EXISTS (SELECT 1
                               FROM selected_toi_danh_filter loc
                               WHERE INSTR(
                                             ',' || REPLACE(
                                                     REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                     ' ', '') || ',',
                                             ',' || TRIM(loc.ma_loc) || ','
                                     ) > 0)
            )
            AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
            AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

            AND (
                p_ghi_chu_rieng_id IS NULL
                    OR INSTR(
                               ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                               ',',
                               ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                       ) > 0
            )

            AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

            AND (p_nuoc_ngoai IS NULL OR (
                CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
            ))
            AND (p_co_benh_tat IS NULL OR (
                CASE
                    WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                        THEN 1
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_BENH_TATS dbt
                        WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                    )
                        THEN 0
                    ELSE 1
                END = p_co_benh_tat
            ))
            AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
            ))
            AND (
                p_dan_toc_thieu_so IS NULL
                OR (
                    CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_DAN_TOCS dt
                            WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                              AND dt.IS_DELETED = 0
                              AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                        )
                        THEN 1
                        ELSE 0
                    END = p_dan_toc_thieu_so
                )
            )
            AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                CASE
                    WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_thoi_diem_pham_toi
            ))
            AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
            ))
            AND (p_theo_ton_giao IS NULL OR (
                CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_TON_GIAOS tg
                        WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                          AND tg.IS_DELETED = 0
                    )
                    THEN 1
                    ELSE 0
                END = p_theo_ton_giao ))
            AND (p_vtn_hien_tai IS NULL OR (
                CASE
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_hien_tai
            ))
            AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
            ))
            AND (
                p_co_nghe_nghiep IS NULL
                OR (
                    CASE
                        WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                             AND EXISTS (
                                    SELECT 1
                                    FROM DM_NGHE_NGHIEPS dnn
                                    WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                      AND dnn.IS_DELETED = 0
                                      AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                             )
                        THEN 1
                        ELSE 0
                    END = p_co_nghe_nghiep
                )
            )
            AND (p_chung_than IS NULL OR (
                CASE
                    WHEN ll.THA_MA_AN_PHAT IN (
                        SELECT dmtg.ID
                        FROM DM_MA_THOI_GIANS dmtg
                        WHERE dmtg.MTG_MA IN ('911000', '912000')
                          AND dmtg.IS_DELETED = 0
                    ) THEN 1
                    ELSE 0
                END = p_chung_than
            ))
            AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
            ))
            AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
            ))
            AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))
            AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
            ))
            AND (p_co_tien_an IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_an
            ))
            AND (p_co_tien_su IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_su
            ))
            AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
            ))
            AND (p_hp_bo_sung_la_tien IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                          LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                    ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                        AND dhpbs.IS_DELETED = 0
                                 WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                   AND hpbs.IS_DELETED = 0
                                   AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                    ELSE 0 END = p_hp_bo_sung_la_tien
            ))
            AND (p_bat_buoc_chua_benh IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM CHUA_BENH_BAT_BUOCS cb
                                 WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                   	AND cb.IS_DELETED = 0
                                       ) THEN 1
                    ELSE 0 END = p_bat_buoc_chua_benh
            ))
            AND (
                p_hoan_xong_hpbs_la_tien IS NULL OR
                (CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                            LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                             AND dhpbs.IS_DELETED = 0
                            WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                              AND hpbs.IS_DELETED = 0
                              AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                            HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                        ) THEN 1
                        ELSE 0
                    END = p_hoan_xong_hpbs_la_tien))
            AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                ( CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                            LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                             AND dhpbs.IS_DELETED = 0
                            WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                              AND hpbs.IS_DELETED = 0
                              AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                            HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                        ) THEN 1
                        ELSE 0
                    END = p_chua_hoan_hpbs_la_tien))
    ),

    base AS (
        SELECT
            pnf.PHAM_NHAN_ID                            AS PN_ID,
            EXTRACT(YEAR  FROM pnf.THA_NGAY_HET_HAN)   AS NAM,
            EXTRACT(MONTH FROM pnf.THA_NGAY_HET_HAN)   AS THANG,
            dgt.GT_TEN
        FROM pham_nhan_filtered pnf
        LEFT JOIN DM_GIOI_TINHS dgt
            ON  dgt.ID         = pnf.LL_DM_GIOI_TINH_ID
            AND dgt.IS_DELETED = 0
    ),

    nam_rank AS (
        SELECT DISTINCT
            NAM,
            DENSE_RANK() OVER (ORDER BY NAM DESC) AS NAM_STT
        FROM base
    )

   SELECT
        "TT",
        "NamThang",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (

        SELECT
            nr.NAM_STT AS SORT_ORDER,
            TO_NCHAR(CASE nr.NAM_STT
				    WHEN 1  THEN 'I'
				    WHEN 2  THEN 'II'
				    WHEN 3  THEN 'III'
				    WHEN 4  THEN 'IV'
				    WHEN 5  THEN 'V'
				    WHEN 6  THEN 'VI'
				    WHEN 7  THEN 'VII'
				    WHEN 8  THEN 'VIII'
				    WHEN 9  THEN 'IX'
				    WHEN 10 THEN 'X'
				    WHEN 11 THEN 'XI'
				    WHEN 12 THEN 'XII'
				    WHEN 13 THEN 'XIII'
				    WHEN 14 THEN 'XIV'
				    WHEN 15 THEN 'XV'
				    WHEN 16 THEN 'XVI'
				    WHEN 17 THEN 'XVII'
				    WHEN 18 THEN 'XVIII'
				    WHEN 19 THEN 'XIX'
				    WHEN 20 THEN 'XX'
				    WHEN 21 THEN 'XXI'
				    WHEN 22 THEN 'XXII'
				    WHEN 23 THEN 'XXIII'
				    WHEN 24 THEN 'XXIV'
				    WHEN 25 THEN 'XXV'
				    WHEN 26 THEN 'XXVI'
				    WHEN 27 THEN 'XXVII'
				    WHEN 28 THEN 'XXVIII'
				    WHEN 29 THEN 'XXIX'
				    WHEN 30 THEN 'XXX'
				    WHEN 31 THEN 'XXXI'
				    WHEN 32 THEN 'XXXII'
				    WHEN 33 THEN 'XXXIII'
				    WHEN 34 THEN 'XXXIV'
				    WHEN 35 THEN 'XXXV'
				    WHEN 36 THEN 'XXXVI'
				    WHEN 37 THEN 'XXXVII'
				    WHEN 38 THEN 'XXXVIII'
				    WHEN 39 THEN 'XXXIX'
				    WHEN 40 THEN 'XL'
				    WHEN 41 THEN 'XLI'
				    WHEN 42 THEN 'XLII'
				    WHEN 43 THEN 'XLIII'
				    WHEN 44 THEN 'XLIV'
				    WHEN 45 THEN 'XLV'
				    WHEN 46 THEN 'XLVI'
				    WHEN 47 THEN 'XLVII'
				    WHEN 48 THEN 'XLVIII'
				    WHEN 49 THEN 'XLIX'
				    WHEN 50 THEN 'L'
				END) AS "TT",
            TO_NCHAR(u'N\0102M ') || TO_NCHAR(nr.NAM)                          AS "NamThang",
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'Nam'   THEN b.PN_ID END)     AS "Nam",
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'N\1eef' THEN b.PN_ID END)    AS "Nu",
            COUNT(DISTINCT CASE
                WHEN b.GT_TEN IS NULL
                  OR b.GT_TEN NOT IN (u'Nam', u'N\1eef')
                THEN b.PN_ID END)                                               AS "Khac",
            COUNT(DISTINCT b.PN_ID)                                             AS "TongSo"
        FROM base b
        JOIN nam_rank nr ON b.NAM = nr.NAM
        GROUP BY nr.NAM_STT, nr.NAM

        UNION ALL

        SELECT
            nr.NAM_STT + (ROW_NUMBER() OVER (PARTITION BY b.NAM ORDER BY b.THANG)) * 0.001,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (PARTITION BY b.NAM ORDER BY b.THANG))),
            TO_NCHAR(u'Th\00e1ng ') || TO_NCHAR(LPAD(b.THANG, 2, '0')),
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'Nam'   THEN b.PN_ID END),
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'N\1eef' THEN b.PN_ID END),
            COUNT(DISTINCT CASE
                WHEN b.GT_TEN IS NULL
                  OR b.GT_TEN NOT IN (u'Nam', u'N\1eef')
                THEN b.PN_ID END),
            COUNT(DISTINCT b.PN_ID)
        FROM base b
        JOIN nam_rank nr ON b.NAM = nr.NAM
        GROUP BY nr.NAM_STT, b.NAM, b.THANG

    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_NGAY_RA_TRAI;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_NGHE_NGHIEP
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_NGHE_NGHIEP" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID,
            ll.LL_DM_NGHE_NGHIEP_ID
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
           AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
           AND dqt.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)
          -- NHOM 1: Khoang ngay
          AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
          AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
          AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
          AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
          AND (
              (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM PN_DAC_XAS dxa
                  WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND dxa.IS_DELETED = 0
                    AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                    AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
              )
          )
          AND (
              (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM GIAM_THOI_HANS gaan
                  WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND gaan.IS_DELETED   = 0
                    AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                    AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
              )
          )
          -- NHOM 2: Khoang so
          AND (
              p_so_tien_an_tu IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
          )
          AND (
              p_so_tien_an_den IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
          )
          AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
          AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
          AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
          AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
          AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
          AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
          AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
          AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
          -- NHOM 3: Danh muc
          AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
          AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
          AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
          AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
          AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
          AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
          -- [Toi danh] input dang [123,453] hoac 123,453
          AND (
              p_toi_danh_ids IS NULL
              OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
              OR EXISTS (SELECT 1
                         FROM selected_toi_danh_filter loc
                         WHERE INSTR(
                                     ',' || REPLACE(
                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                             ' ', '') || ',',
                                     ',' || TRIM(loc.ma_loc) || ','
                             ) > 0)
          )
          AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
          AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)
          -- [Ghi chu rieng] input dang 123
          AND (
              p_ghi_chu_rieng_id IS NULL
              OR INSTR(
                         ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                         ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                     ) > 0
          )
          AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)
          -- NHOM 4: Checkbox
          -- [Nuoc ngoai]
          AND (p_nuoc_ngoai IS NULL OR (
              CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
          ))
          -- [Co benh tat]
          AND (p_co_benh_tat IS NULL OR (
              CASE
                  WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                      THEN 1
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_BENH_TATS dbt
                      WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                  )
                      THEN 0
                  ELSE 1
              END = p_co_benh_tat
          ))
          -- [Giam rieng]
          AND (p_giam_rieng IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PN_GIAM_RIENGS gr
                  WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND gr.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_giam_rieng
          ))
          -- [Dan toc thieu so]
          AND (
              p_dan_toc_thieu_so IS NULL
              OR (
                  CASE
                      WHEN EXISTS (
                          SELECT 1
                          FROM DM_DAN_TOCS dt
                          WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                            AND dt.IS_DELETED = 0
                            AND NVL(dt.DT_MA, 'NULL') NOT IN ('1', '55')
                      )
                      THEN 1
                      ELSE 0
                  END = p_dan_toc_thieu_so
              )
          )
          -- [VTN tai thoi diem pham toi]
          AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
              CASE
                  WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_thoi_diem_pham_toi
          ))
          -- [Pham toi moi]
          AND (p_pham_toi_moi IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_pham_toi_moi
          ))
          -- [Theo ton giao]
          AND (p_theo_ton_giao IS NULL OR (
              CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_TON_GIAOS tg
                      WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                        AND tg.IS_DELETED = 0
                  )
                  THEN 1
                  ELSE 0
              END = p_theo_ton_giao
          ))
          -- [VTN hien tai]
          AND (p_vtn_hien_tai IS NULL OR (
              CASE
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_hien_tai
          ))
          -- [Khong pham toi moi]
          AND (p_khong_pham_toi_moi IS NULL OR (
              CASE WHEN NOT EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
          ))
          -- [Co nghe nghiep]
          AND (
              p_co_nghe_nghiep IS NULL
              OR (
                  CASE
                      WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                           AND EXISTS (
                               SELECT 1
                               FROM DM_NGHE_NGHIEPS dnn
                               WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                 AND dnn.IS_DELETED = 0
                                 AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                           )
                      THEN 1
                      ELSE 0
                  END = p_co_nghe_nghiep
              )
          )
          -- [Chung than]
          AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
          -- [Da bi ky luat]
          AND (p_da_bi_ky_luat IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KY_LUATS kl
                  WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
              ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
          ))
          -- [Co ghi chu dac biet]
          AND (p_co_ghi_chu_dac_biet IS NULL OR (
              CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                    AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                   THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
          ))
          -- [Toi pham ANQG]
          AND (p_toi_pham_anqg IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM DM_TOI_DANHS td
                  WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                    AND td.IS_DELETED = 0
                    AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
              ) THEN 1 ELSE 0 END = p_toi_pham_anqg
          ))
          -- [Da duoc khen thuong]
          AND (p_da_duoc_khen_thuong IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KHEN_THUONGS kt
                  WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND kt.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
          ))
          -- [Co tien an]
          AND (p_co_tien_an IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_an
          ))
          -- [Co tien su]
          AND (p_co_tien_su IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_su
          ))
          -- [Con theo me vao trai]
          AND (p_con_theo_me_vao_trai IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                  WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND tncc.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
          ))
          -- [Hinh phat bo sung la tien]
          AND (p_hp_bo_sung_la_tien IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                         ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                        AND dhpbs.IS_DELETED = 0
                               WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                 AND hpbs.IS_DELETED = 0
                                 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                  ELSE 0 END = p_hp_bo_sung_la_tien
          ))
          -- [Bat buoc chua benh]
          AND (p_bat_buoc_chua_benh IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM CHUA_BENH_BAT_BUOCS cb
                               WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                 AND cb.IS_DELETED = 0
                                 ) THEN 1
                  ELSE 0 END = p_bat_buoc_chua_benh
          ))
          -- [Hoan xong HPBS la tien]
          AND (
              p_hoan_xong_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                  ) THEN 1
                  ELSE 0
              END = p_hoan_xong_hpbs_la_tien)
          )
          -- [Chua hoan xong HPBS la tien]
          AND (p_chua_hoan_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                  ) THEN 1
                  ELSE 0
              END = p_chua_hoan_hpbs_la_tien))
    ),

    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC))) AS "TT",
            dnn.NN_TEN AS "NgheNghiep",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END)                                     AS "Nam",
            COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END)                                  AS "Nu",
            COUNT(CASE WHEN gt.GT_TEN IS NULL
                            OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN 1 END)                AS "Khac",
            COUNT(*)                                                                             AS "TongSo"
        FROM pham_nhan_filtered ll
        LEFT JOIN DM_NGHE_NGHIEPS dnn
            ON dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
           AND dnn.IS_DELETED = 0
        LEFT JOIN DM_GIOI_TINHS gt
            ON gt.ID = ll.LL_DM_GIOI_TINH_ID
           AND gt.IS_DELETED = 0
        GROUP BY dnn.ID, dnn.NN_TEN
    )

    SELECT
        "TT",
        "NgheNghiep",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
            "NgheNghiep",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_NGHE_NGHIEP;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_NGUYEN_NHAN_CHET
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_NGUYEN_NHAN_CHET" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114', '171')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
           AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
           AND dqt.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)
          -- NHOM 1: Khoang ngay
          AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
          AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
          AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
          AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
          AND (
              (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM PN_DAC_XAS dxa
                  WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND dxa.IS_DELETED = 0
                    AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                    AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
              )
          )
          AND (
              (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM GIAM_THOI_HANS gaan
                  WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND gaan.IS_DELETED   = 0
                    AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                    AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
              )
          )
          -- NHOM 2: Khoang so
          AND (
              p_so_tien_an_tu IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
          )
          AND (
              p_so_tien_an_den IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
          )
          AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
          AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
          AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
          AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
          AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
          AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
          AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
          AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
          -- NHOM 3: Danh muc
          AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
          AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
          AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
          AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
          AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
          AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
          -- [Toi danh] input dang [123,453] hoac 123,453
          AND (
              p_toi_danh_ids IS NULL
              OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
              OR EXISTS (SELECT 1
                         FROM selected_toi_danh_filter loc
                         WHERE INSTR(
                                     ',' || REPLACE(
                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                             ' ', '') || ',',
                                     ',' || TRIM(loc.ma_loc) || ','
                             ) > 0)
          )
          AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
          AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)
          -- [Ghi chu rieng] input dang 123
          AND (
              p_ghi_chu_rieng_id IS NULL
              OR INSTR(
                         ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                         ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                     ) > 0
          )
          AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)
          -- NHOM 4: Checkbox
          -- [Nuoc ngoai]
          AND (p_nuoc_ngoai IS NULL OR (
              CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
          ))
          -- [Co benh tat]
          AND (p_co_benh_tat IS NULL OR (
              CASE
                  WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                      THEN 1
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_BENH_TATS dbt
                      WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                  )
                      THEN 0
                  ELSE 1
              END = p_co_benh_tat
          ))
          -- [Giam rieng]
          AND (p_giam_rieng IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PN_GIAM_RIENGS gr
                  WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND gr.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_giam_rieng
          ))
          -- [Dan toc thieu so]
          AND (
              p_dan_toc_thieu_so IS NULL
              OR (
                  CASE
                      WHEN EXISTS (
                          SELECT 1
                          FROM DM_DAN_TOCS dt
                          WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                            AND dt.IS_DELETED = 0
                            AND NVL(dt.DT_MA, 'NULL') NOT IN ('1', '55')
                      )
                      THEN 1
                      ELSE 0
                  END = p_dan_toc_thieu_so
              )
          )
          -- [VTN tai thoi diem pham toi]
          AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
              CASE
                  WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_thoi_diem_pham_toi
          ))
          -- [Pham toi moi]
          AND (p_pham_toi_moi IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_pham_toi_moi
          ))
          -- [Theo ton giao]
          AND (p_theo_ton_giao IS NULL OR (
              CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_TON_GIAOS tg
                      WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                        AND tg.IS_DELETED = 0
                  )
                  THEN 1
                  ELSE 0
              END = p_theo_ton_giao
          ))
          -- [VTN hien tai]
          AND (p_vtn_hien_tai IS NULL OR (
              CASE
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_hien_tai
          ))
          -- [Khong pham toi moi]
          AND (p_khong_pham_toi_moi IS NULL OR (
              CASE WHEN NOT EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
          ))
          -- [Co nghe nghiep]
          AND (
              p_co_nghe_nghiep IS NULL
              OR (
                  CASE
                      WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                           AND EXISTS (
                               SELECT 1
                               FROM DM_NGHE_NGHIEPS dnn
                               WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                 AND dnn.IS_DELETED = 0
                                 AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                           )
                      THEN 1
                      ELSE 0
                  END = p_co_nghe_nghiep
              )
          )
          -- [Chung than]
          AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
          -- [Da bi ky luat]
          AND (p_da_bi_ky_luat IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KY_LUATS kl
                  WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
              ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
          ))
          -- [Co ghi chu dac biet]
          AND (p_co_ghi_chu_dac_biet IS NULL OR (
              CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                    AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                   THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
          ))
          -- [Toi pham ANQG]
          AND (p_toi_pham_anqg IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM DM_TOI_DANHS td
                  WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                    AND td.IS_DELETED = 0
                    AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
              ) THEN 1 ELSE 0 END = p_toi_pham_anqg
          ))
          -- [Da duoc khen thuong]
          AND (p_da_duoc_khen_thuong IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KHEN_THUONGS kt
                  WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND kt.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
          ))
          -- [Co tien an]
          AND (p_co_tien_an IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_an
          ))
          -- [Co tien su]
          AND (p_co_tien_su IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_su
          ))
          -- [Con theo me vao trai]
          AND (p_con_theo_me_vao_trai IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                  WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND tncc.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
          ))
          -- [Hinh phat bo sung la tien]
          AND (p_hp_bo_sung_la_tien IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                         ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                        AND dhpbs.IS_DELETED = 0
                               WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                 AND hpbs.IS_DELETED = 0
                                 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                  ELSE 0 END = p_hp_bo_sung_la_tien
          ))
          -- [Bat buoc chua benh]
          AND (p_bat_buoc_chua_benh IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM CHUA_BENH_BAT_BUOCS cb
                               WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                 AND cb.IS_DELETED = 0
                                 ) THEN 1
                  ELSE 0 END = p_bat_buoc_chua_benh
          ))
          -- [Hoan xong HPBS la tien]
          AND (
              p_hoan_xong_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                  ) THEN 1
                  ELSE 0
              END = p_hoan_xong_hpbs_la_tien)
          )
          -- [Chua hoan xong HPBS la tien]
          AND (p_chua_hoan_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                  ) THEN 1
                  ELSE 0
              END = p_chua_hoan_hpbs_la_tien))
    ),

    ket_thuc_chet_split AS (
        SELECT
            ktc.KTC_PN_LAI_LICH_ID,
            TRIM(
                REGEXP_SUBSTR(ktc.KTC_DANH_SACH_NGUYEN_NHAN_CHET_IDS, '[^;]+', 1, LEVEL)
            ) AS nnc_id_str
        FROM PN_KET_THUC_CHETS ktc
        INNER JOIN pham_nhan_filtered pnf ON pnf.PHAM_NHAN_ID = ktc.KTC_PN_LAI_LICH_ID
        WHERE ktc.IS_DELETED = 0
          AND (v_ngay_tinh IS NULL OR TRUNC(ktc.KTC_NGAY_CHET) < TRUNC(v_ngay_tinh) + 1)
        CONNECT BY
            LEVEL <= REGEXP_COUNT(ktc.KTC_DANH_SACH_NGUYEN_NHAN_CHET_IDS, ';') + 1
            AND PRIOR ktc.KTC_PN_LAI_LICH_ID = ktc.KTC_PN_LAI_LICH_ID
            AND PRIOR DBMS_RANDOM.VALUE IS NOT NULL
    ),
    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC)                    AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC))) AS "TT",
            NVL(dnnc.NNC_TEN, TO_NCHAR(u'Kh\00f4ng r\00f5'))             AS "NguyenNhanChet",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam'    THEN 1 END)             AS "Nam",
            COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END)             AS "Nu",
            COUNT(CASE WHEN gt.GT_TEN IS NULL
                            OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                       THEN 1 END)                                         AS "Khac",
            COUNT(*)                                                        AS "TongSo"
        FROM ket_thuc_chet_split kts
        INNER JOIN pham_nhan_filtered pnf ON pnf.PHAM_NHAN_ID = kts.KTC_PN_LAI_LICH_ID
        LEFT  JOIN DM_GIOI_TINHS gt
            ON gt.ID = pnf.LL_DM_GIOI_TINH_ID
           AND gt.IS_DELETED = 0
        LEFT  JOIN DM_NGUYEN_NHAN_CHETS dnnc
            ON dnnc.ID = TO_NUMBER(kts.nnc_id_str)
           AND NVL(dnnc.IS_DELETED, 0) = 0
        GROUP BY dnnc.ID, dnnc.NNC_TEN
    )

    SELECT
        "TT",
        "NguyenNhanChet",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
            "NguyenNhanChet",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_NGUYEN_NHAN_CHET;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_PHAM_NHAN_CHET_HO_SO_PT83
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_PHAM_NHAN_CHET_HO_SO_PT83" (
    p_tu_ngay      IN VARCHAR2,
    p_den_ngay     IN VARCHAR2,
    p_ma_trai_giam IN VARCHAR2 DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
    v_tu_ngay DATE;
    v_den_ngay DATE;
    v_den_ngay_excl DATE;
BEGIN
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := DATE '1900-01-01';
    ELSE
        v_tu_ngay := TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY');
    END IF;

    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := DATE '9999-12-30';
        v_den_ngay_excl := DATE '9999-12-31';
    ELSE
        v_den_ngay := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY');
        v_den_ngay_excl := TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY') + 1;
    END IF;

    OPEN c1 FOR
        WITH base_pn AS (
            SELECT
                v.pham_nhan_id,
                v.gioi_tinh_id,
                v.ll_tinh_trang_id,
                v.trai_giam_ma,
                v.trai_giam_id,
                v.ngay_den_trai,
                v.ngay_het_an,
                v.muc_an_id
            FROM qlpn.vw_pn_lai_lich_chi_tiet v
            WHERE NVL(v.is_deleted, 0) = 0
              AND (p_ma_trai_giam IS NULL OR v.trai_giam_ma = p_ma_trai_giam)
        ),
        base_pn_detail AS (
            SELECT
                b.*,
                tt.ttpn_ma,
                ma.ma_tu,
                ma.ma_den
            FROM base_pn b
            LEFT JOIN qlpn.dm_tinh_trang_pham_nhans tt
                   ON tt.id = b.ll_tinh_trang_id
                  AND NVL(tt.is_deleted, 0) = 0
            LEFT JOIN qlpn.dm_muc_ans ma
                   ON ma.id = b.muc_an_id
                  AND NVL(ma.is_deleted, 0) = 0
        ),
        death_all AS (
            SELECT
                ktc.id,
                ktc.ktc_pn_lai_lich_id AS pham_nhan_id,
                TRUNC(CAST(ktc.ktc_ngay_chet AS DATE)) AS ngay_chet,
                ktc.ktc_so_mo,
                TRUNC(CAST(ktc.ktc_ngay_boc_mo AS DATE)) AS ngay_boc_mo,
                htc.thc_ma,
                b.gioi_tinh_id,
                b.ma_tu,
                b.ma_den,
                htc_chon.htc_ma AS hinh_thuc_chon_ma
            FROM qlpn.pn_ket_thuc_chets ktc
            JOIN base_pn_detail b
              ON b.pham_nhan_id = ktc.ktc_pn_lai_lich_id
            LEFT JOIN qlpn.dm_truong_hop_chets htc
                   ON htc.id = ktc.ktc_dm_truong_hop_chet_id
                  AND NVL(htc.is_deleted, 0) = 0
            LEFT JOIN qlpn.dm_hinh_thuc_chons htc_chon
                   ON htc_chon.id = ktc.ktc_dm_hinh_thuc_chon_id
                  AND NVL(htc_chon.is_deleted, 0) = 0
            WHERE NVL(ktc.is_deleted, 0) = 0
              AND ktc.ktc_ngay_chet IS NOT NULL
              AND CAST(ktc.ktc_ngay_chet AS DATE) >= v_tu_ngay
              AND CAST(ktc.ktc_ngay_chet AS DATE) < v_den_ngay_excl
        ),
        nnc_split AS (
            SELECT
                ktc.id AS ktc_id,
                TRIM(REGEXP_SUBSTR(ktc.ktc_danh_sach_nguyen_nhan_chet_ids, '[^;]+', 1, LEVEL)) AS nnc_id_str
            FROM qlpn.pn_ket_thuc_chets ktc
            WHERE NVL(ktc.is_deleted, 0) = 0
              AND ktc.ktc_danh_sach_nguyen_nhan_chet_ids IS NOT NULL
            CONNECT BY PRIOR ktc.id = ktc.id
               AND PRIOR SYS_GUID() IS NOT NULL
               AND LEVEL <= REGEXP_COUNT(ktc.ktc_danh_sach_nguyen_nhan_chet_ids, ';') + 1
        ),
        nnc_all AS (
            SELECT DISTINCT
                s.ktc_id,
                nnc.nnc_ma
            FROM nnc_split s
            JOIN qlpn.dm_nguyen_nhan_chets nnc
              ON nnc.id = TO_NUMBER(s.nnc_id_str DEFAULT NULL ON CONVERSION ERROR)
             AND NVL(nnc.is_deleted, 0) = 0
            WHERE REGEXP_LIKE(s.nnc_id_str, '^\d+$')

            UNION

            SELECT DISTINCT
                ktc.id AS ktc_id,
                nnc.nnc_ma
            FROM qlpn.pn_ket_thuc_chets ktc
            JOIN qlpn.dm_nguyen_nhan_chets nnc
              ON nnc.id = ktc.ktc_nguyen_nhan_chet_id
             AND NVL(nnc.is_deleted, 0) = 0
            WHERE NVL(ktc.is_deleted, 0) = 0
              AND ktc.ktc_nguyen_nhan_chet_id IS NOT NULL
        ),
        death_period AS (
            SELECT d.*
            FROM death_all d
        ),
        death_flags AS (
            SELECT
                d.*,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND n.nnc_ma IN ('5701')) THEN 1 ELSE 0 END AS f_danh_nhau,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND n.nnc_ma IN ('5900','5901','5905','5909','5913','5917','5921','5999')) THEN 1 ELSE 0 END AS f_tu_tu,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND n.nnc_ma IN ('8701')) THEN 1 ELSE 0 END AS f_dot_tu,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND n.nnc_ma IN ('5505')) THEN 1 ELSE 0 END AS f_dien_giat,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND n.nnc_ma IN ('5100')) THEN 1 ELSE 0 END AS f_tai_nan_ld,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND n.nnc_ma IN ('6100','6101','6105','6199')) THEN 1 ELSE 0 END AS f_ngo_doc,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND TO_NUMBER(n.nnc_ma DEFAULT NULL ON CONVERSION ERROR) >= 5100)
                      AND NOT EXISTS (
                          SELECT 1
                          FROM nnc_all n
                          WHERE n.ktc_id = d.id
                            AND n.nnc_ma IN ('5701','5900','5901','5905','5909','5913','5917','5921','5999','8701','5505','5100','6100','6101','6105','6199')
                      )
                     THEN 1 ELSE 0 END AS f_ly_do_khac,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND n.nnc_ma IN ('2900','2901')) THEN 1 ELSE 0 END AS f_hiv,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND n.nnc_ma IN ('2700','2701','2705','2709','2713','2717','2799')) THEN 1 ELSE 0 END AS f_lao,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND n.nnc_ma IN ('2105','2113','2117','2125','2137','2141','2145','2149')) THEN 1 ELSE 0 END AS f_phoi,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND n.nnc_ma IN ('1500','1501','1505','1513','1517','1533','1537','1541','1545','1549','1553','1599')) THEN 1 ELSE 0 END AS f_tim_mach,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND n.nnc_ma IN ('1100','1101','1105','1109','1113','1117','1121','1125','1119')) THEN 1 ELSE 0 END AS f_nao,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND n.nnc_ma IN ('1700','1701','1705','1709','1713','1717','1725','1729','1733','1737')) THEN 1 ELSE 0 END AS f_gan,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND n.nnc_ma IN ('1300','1301','1313')) THEN 1 ELSE 0 END AS f_than_kinh,
                CASE WHEN EXISTS (SELECT 1 FROM nnc_all n WHERE n.ktc_id = d.id AND TO_NUMBER(n.nnc_ma DEFAULT NULL ON CONVERSION ERROR) < 5100)
                      AND NOT EXISTS (
                          SELECT 1
                          FROM nnc_all n
                          WHERE n.ktc_id = d.id
                            AND n.nnc_ma IN (
                                '2900','2901',
                                '2700','2701','2705','2709','2713','2717','2799',
                                '2105','2113','2117','2125','2137','2141','2145','2149',
                                '1500','1501','1505','1513','1517','1533','1537','1541','1545','1549','1553','1599',
                                '1100','1101','1105','1109','1113','1117','1121','1125','1119',
                                '1700','1701','1705','1709','1713','1717','1725','1729','1733','1737',
                                '1300','1301','1313'
                            )
                      )
                     THEN 1 ELSE 0 END AS f_benh_khac
            FROM death_period d
        ),
        nop_luu AS (
            SELECT DISTINCT hp.pn_lai_lich_id AS pham_nhan_id
            FROM qlpn.pn_hsnv_pham_nhans hp
            JOIN qlpn.pn_hsnvs hs
              ON hs.id = hp.pn_hsnv_id
             AND NVL(hs.is_deleted, 0) = 0
            JOIN base_pn b
              ON b.pham_nhan_id = hp.pn_lai_lich_id
            WHERE NVL(hp.is_deleted, 0) = 0
              AND CAST(hs.ngay_dk AS DATE) >= v_tu_ngay
              AND CAST(hs.ngay_dk AS DATE) < v_den_ngay_excl

            UNION

            SELECT DISTINCT hkp.pn_lai_lich_id AS pham_nhan_id
            FROM qlpn.pn_hsnv_kt_pham_nhans hkp
            JOIN qlpn.pn_hsnv_kts hks
              ON hks.id = hkp.pn_hsnv_kt_id
             AND NVL(hks.is_deleted, 0) = 0
            JOIN base_pn b
              ON b.pham_nhan_id = hkp.pn_lai_lich_id
            WHERE NVL(hkp.is_deleted, 0) = 0
              AND CAST(hks.ngay_dk AS DATE) >= v_tu_ngay
              AND CAST(hks.ngay_dk AS DATE) < v_den_ngay_excl
        ),
        hs_base AS (
            SELECT b.*
            FROM base_pn_detail b
            WHERE NVL(b.ngay_den_trai, DATE '1900-01-01') >= v_tu_ngay
              AND NVL(b.ngay_den_trai, DATE '1900-01-01') < v_den_ngay_excl
        ),
        hs_agg AS (
            SELECT
                COUNT(DISTINCT CASE WHEN ttpn_ma IN ('111','112','113','114') THEN pham_nhan_id END) AS hs_dang_chap_hanh_an,
                COUNT(DISTINCT CASE WHEN ttpn_ma = '121' THEN pham_nhan_id END) AS hs_chap_hanh_xong,
                COUNT(DISTINCT CASE WHEN ttpn_ma NOT IN ('111','112','113','114','121') OR ttpn_ma IS NULL THEN pham_nhan_id END) AS hs_cac_loai_khac
            FROM hs_base
        ),
        hs_death AS (
            SELECT
                COUNT(DISTINCT CASE WHEN NVL(ma_den, ma_tu) < 5 THEN pham_nhan_id END) AS hs_chet_duoi_5_nam,
                COUNT(DISTINCT CASE WHEN NVL(ma_den, ma_tu) >= 5 OR ma_tu IS NULL THEN pham_nhan_id END) AS hs_chet_tren_5_nam
            FROM death_period
        ),
        hs_tdc AS (
            SELECT
                COUNT(
                    DISTINCT CASE
                        WHEN tdc.tu_ngay IS NOT NULL
                         AND (
                             ADD_MONTHS(
                                 CAST(tdc.tu_ngay AS DATE),
                                 NVL(mtg.mtg_nam, 0) * 12 + NVL(mtg.mtg_thang, 0)
                             ) + NVL(mtg.mtg_ngay, 0)
                         ) < v_den_ngay
                        THEN tdc.pham_nhan_id
                    END
                ) AS hs_tdc_con_thoi_han,
                COUNT(
                    DISTINCT CASE
                        WHEN tdc.tu_ngay IS NOT NULL
                         AND tdc.ngay_lai IS NULL
                         AND (
                             ADD_MONTHS(
                                 CAST(tdc.tu_ngay AS DATE),
                                 NVL(mtg.mtg_nam, 0) * 12 + NVL(mtg.mtg_thang, 0)
                             ) + NVL(mtg.mtg_ngay, 0)
                         ) > v_den_ngay
                        THEN tdc.pham_nhan_id
                    END
                ) AS hs_tdc_het_thoi_han,
                COUNT(DISTINCT CASE WHEN tt.ttpn_ma = '30' THEN tdc.pham_nhan_id END) AS hs_tdc_chet,
                COUNT(DISTINCT CASE WHEN tt.ttpn_ma = '98' THEN tdc.pham_nhan_id END) AS hs_tdc_pham_toi_moi
            FROM qlpn.tam_dinh_chis tdc
            JOIN base_pn b
              ON b.pham_nhan_id = tdc.pham_nhan_id
            LEFT JOIN qlpn.dm_tinh_trang_pham_nhans tt
                   ON tt.id = tdc.tinh_trang_id
                  AND NVL(tt.is_deleted, 0) = 0
            LEFT JOIN qlpn.dm_ma_thoi_gians mtg
                   ON mtg.id = tdc.thoi_han_id
                  AND NVL(mtg.is_deleted, 0) = 0
            WHERE NVL(tdc.is_deleted, 0) = 0
              AND CAST(tdc.ngay_tdc AS DATE) >= v_tu_ngay
              AND CAST(tdc.ngay_tdc AS DATE) < v_den_ngay_excl
        ),
        hs_tron AS (
            SELECT COUNT(DISTINCT tt.pham_nhan_id) AS hs_tron_chua_bat_lai
            FROM qlpn.tron_trais tt
            JOIN base_pn b
              ON b.pham_nhan_id = tt.pham_nhan_id
            WHERE NVL(tt.is_deleted, 0) = 0
              AND CAST(tt.ngay_tron AS DATE) >= v_tu_ngay
              AND CAST(tt.ngay_tron AS DATE) < v_den_ngay_excl
              AND tt.ngay_bat_lai IS NULL
        ),
        hs_tx AS (
            SELECT COUNT(DISTINCT tx.pham_nhan_id) AS hs_trich_xuat
            FROM qlpn.trich_xuats tx
            JOIN base_pn b
              ON b.pham_nhan_id = tx.pham_nhan_id
            WHERE NVL(tx.is_deleted, 0) = 0
              AND CAST(tx.tx_ngay_trich_xuat AS DATE) >= v_tu_ngay
              AND CAST(tx.tx_ngay_trich_xuat AS DATE) < v_den_ngay_excl
        ),
        final_data AS (
            SELECT
                COUNT(*) AS p1_tong_so_pham_nhan_chet,
                COUNT(CASE WHEN gioi_tinh_id = 1 THEN 1 END) AS p1_nam,
                COUNT(CASE WHEN gioi_tinh_id = 2 THEN 1 END) AS p1_nu,
                SUM(f_danh_nhau) AS p1_danh_nhau,
                SUM(f_tu_tu) AS p1_tu_tu,
                SUM(f_dot_tu) AS p1_dot_tu,
                SUM(f_dien_giat) AS p1_dien_giat,
                SUM(f_tai_nan_ld) AS p1_tai_nan_ld,
                SUM(f_ngo_doc) AS p1_ngo_doc,
                SUM(f_ly_do_khac) AS p1_ly_do_khac,
                SUM(f_hiv) AS p1_hiv,
                SUM(f_lao) AS p1_lao,
                SUM(f_phoi) AS p1_phoi,
                SUM(f_tim_mach) AS p1_tim_mach,
                SUM(f_nao) AS p1_nao,
                SUM(f_gan) AS p1_gan,
                SUM(f_than_kinh) AS p1_than_kinh,
                SUM(f_benh_khac) AS p1_benh_khac,
                COUNT(CASE WHEN hinh_thuc_chon_ma = '30' THEN 1 END) AS p1_ban_giao_thi_the,
                COUNT(CASE WHEN hinh_thuc_chon_ma = '40' THEN 1 END) AS p1_ban_giao_tro_cot,
                COUNT(CASE WHEN hinh_thuc_chon_ma = '10' THEN 1 END) AS p1_dia_tang,
                COUNT(CASE WHEN hinh_thuc_chon_ma = '20' THEN 1 END) AS p1_hoa_tang,
                COUNT(CASE WHEN ktc_so_mo IS NOT NULL AND ngay_boc_mo IS NOT NULL THEN 1 END) AS p1_mo_boc_trong_thang_pn,
                CAST(0 AS NUMBER) AS p1_mo_boc_trong_thang_z6,
                COUNT(CASE WHEN ktc_so_mo IS NOT NULL AND ngay_boc_mo IS NULL THEN 1 END) AS p1_mo_dang_quan_ly_pn,
                CAST(0 AS NUMBER) AS p1_mo_dang_quan_ly_z6
            FROM death_flags
        )
        SELECT
            NVL(fd.p1_tong_so_pham_nhan_chet, 0) AS TONG_SO_PHAM_NHAN_CHET,
            NVL(fd.p1_nam, 0) AS NAM,
            NVL(fd.p1_nu, 0) AS NU,
            NVL(fd.p1_danh_nhau, 0) AS DANH_NHAU,
            NVL(fd.p1_tu_tu, 0) AS TU_TU,
            NVL(fd.p1_dot_tu, 0) AS DOT_TU,
            NVL(fd.p1_dien_giat, 0) AS DIEN_GIAT,
            NVL(fd.p1_tai_nan_ld, 0) AS TAI_NAN_LAO_DONG,
            NVL(fd.p1_ngo_doc, 0) AS NGO_DOC,
            NVL(fd.p1_ly_do_khac, 0) AS LY_DO_KHAC,
            NVL(fd.p1_hiv, 0) AS HIV,
            NVL(fd.p1_lao, 0) AS LAO,
            NVL(fd.p1_phoi, 0) AS PHOI,
            NVL(fd.p1_tim_mach, 0) AS TIM_MACH,
            NVL(fd.p1_nao, 0) AS NAO,
            NVL(fd.p1_gan, 0) AS GAN,
            NVL(fd.p1_than_kinh, 0) AS THAN_KINH,
            NVL(fd.p1_benh_khac, 0) AS BENH_KHAC,
            NVL(fd.p1_ban_giao_thi_the, 0) AS BAN_GIAO_THI_THE,
            NVL(fd.p1_ban_giao_tro_cot, 0) AS BAN_GIAO_TRO_COT,
            NVL(fd.p1_dia_tang, 0) AS DIA_TANG,
            NVL(fd.p1_hoa_tang, 0) AS HOA_TANG,
            NVL(fd.p1_mo_boc_trong_thang_pn, 0) AS MO_BOC_TRONG_THANG_PN,
            NVL(fd.p1_mo_boc_trong_thang_z6, 0) AS MO_BOC_TRONG_THANG_Z6,
            NVL(fd.p1_mo_dang_quan_ly_pn, 0) AS MO_DANG_QUAN_LY_PN,
            NVL(fd.p1_mo_dang_quan_ly_z6, 0) AS MO_DANG_QUAN_LY_Z6,
            NVL(ha.hs_dang_chap_hanh_an, 0) AS DANG_CHAP_HANH_AN,
            NVL(ha.hs_chap_hanh_xong, 0) AS CHAP_HANH_XONG_AN_PHAT_TU,
            NVL(hd.hs_chet_duoi_5_nam, 0) AS CHET_DUOI_5_NAM,
            NVL(hd.hs_chet_tren_5_nam, 0) AS CHET_TREN_5_NAM,
            NVL(ht.hs_tdc_con_thoi_han, 0) AS TDC_CON_THOI_HAN,
            NVL(ht.hs_tdc_het_thoi_han, 0) AS TDC_HET_THOI_HAN,
            NVL(ht.hs_tdc_chet, 0) AS TDC_CHET,
            NVL(ht.hs_tdc_pham_toi_moi, 0) AS TDC_PHAM_TOI_MOI,
            NVL(htr.hs_tron_chua_bat_lai, 0) AS TRON_CHUA_BAT_LAI,
            NVL(htx.hs_trich_xuat, 0) AS TRICH_XUAT,
            NVL(ha.hs_cac_loai_khac, 0) AS CAC_LOAI_KHAC,
            NVL(ha.hs_dang_chap_hanh_an, 0)
                + NVL(ha.hs_chap_hanh_xong, 0)
                + NVL(hd.hs_chet_duoi_5_nam, 0)
                + NVL(hd.hs_chet_tren_5_nam, 0)
                + NVL(ht.hs_tdc_con_thoi_han, 0)
                + NVL(ht.hs_tdc_het_thoi_han, 0)
                + NVL(ht.hs_tdc_chet, 0)
                + NVL(ht.hs_tdc_pham_toi_moi, 0)
                + NVL(htr.hs_tron_chua_bat_lai, 0)
                + NVL(htx.hs_trich_xuat, 0)
                + NVL(ha.hs_cac_loai_khac, 0) AS TONG_SO,
            (SELECT COUNT(*) FROM nop_luu) AS HO_SO_NOP_LUU_TRONG_THANG
        FROM final_data fd
        CROSS JOIN hs_agg ha
        CROSS JOIN hs_death hd
        CROSS JOIN hs_tdc ht
        CROSS JOIN hs_tron htr
        CROSS JOIN hs_tx htx;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_THONG_KE_PHAM_NHAN_CHET_HO_SO_PT83: ' || SQLERRM);
END SP_GET_THONG_KE_PHAM_NHAN_CHET_HO_SO_PT83;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_PHAM_NHAN_RA_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_PHAM_NHAN_RA_TRAI" (
    p_tu_ngay  IN DATE,
    p_den_ngay IN DATE
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
        SELECT pll.LL_HO_TEN                                              AS HO_TEN,
               TO_CHAR(TRUNC(pktrt.KTRT_NGAY_THA), 'DD/MM/YYYY')          AS NGAY_THA,
               dtg.TG_TEN                                                 AS TEN_TRAI_GIAM
          FROM PN_KET_THUC_RA_TRAIS pktrt
          JOIN PN_LAI_LICHS pll
            ON pll.ID = pktrt.KTRT_PN_LAI_LICH_ID
           AND NVL(pll.IS_DELETED, 0) = 0
          -- INNER JOIN: pham nhan khong co trai / trai da xoa khong con len luoi,
          -- de tap trai cua luoi bang dung tap trai cua bao cao in (M-002/F-005).
          JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = pll.LL_TRAI_GIAM_ID
           AND NVL(dtg.IS_DELETED, 0) = 0
         WHERE NVL(pktrt.IS_DELETED, 0) = 0
           -- Cung bo loc trai nhu SP_TK_PHAM_NHAN_RA_TRAI_THEO_TRAI: chi trai dang hoat dong
           -- va ten co chua 'Trai giam'.
           AND dtg.TG_TRANG_THAI = 1
           AND dtg.TG_TEN LIKE u'%Tr\1ea1i giam%'
           -- D1: CLOSED interval, day-normalised on BOTH bounds. Deliberate deviation from the
           -- half-open form on this same column in Stored/stored_tk.sql:426-427 and
           -- Stored/SP_THONG_KE_TONG_HOP_BIEN_DONG.sql:258-259, which drop the end day.
           -- Do NOT ""normalise"" this back to `< p_den_ngay`: M-002/AC-2 requires a row at <to>
           -- with a non-midnight time-of-day to be returned, and the caller binds the picker
           -- date verbatim (no +1 day compensation). TRUNC is on the PARAMETERS only, never on
           -- the column, so an index on KTRT_NGAY_THA stays usable.
           AND pktrt.KTRT_NGAY_THA >= TRUNC(p_tu_ngay)
           AND pktrt.KTRT_NGAY_THA <  TRUNC(p_den_ngay) + 1
         ORDER BY FN_SWAP_FIRST_LAST_SORT(pll.LL_HO_TEN);

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_PHAM_NHAN_RA_TRAI;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_PHAM_TOI_MOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_PHAM_TOI_MOI" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH
        selected_toi_danh_filter AS (
            SELECT TRIM(REGEXP_SUBSTR(
                            REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                            '[^,]+', 1, LEVEL)) AS ma_loc
            FROM DUAL
            CONNECT BY LEVEL <= REGEXP_COUNT(
                                    REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                    ',') + 1),
        chung_than_ids AS (
            SELECT dmtg.ID
            FROM DM_MA_THOI_GIANS dmtg
            WHERE dmtg.MTG_MA IN ('911000', '912000')
              AND dmtg.IS_DELETED = 0
        ),
        pn_base AS (
            SELECT
                ll.*,
                CASE
                    WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                    WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                        THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                    ELSE NULL
                END AS SO_TIEN_AN_NUM,
                QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
            INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
               AND tt.NGAY_XET = v_ngay_tinh
               AND tt.TTPN_MA IN ('111', '112', '113', '114')
            WHERE ll.IS_DELETED = 0
              AND NVL(ll.LL_IS_DELETED, 0) = 0
              AND NVL(ll.THA_IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        ),
        pham_nhan_filtered AS (
            SELECT
                ll.PHAM_NHAN_ID,
                ll.LL_DM_GIOI_TINH_ID
            FROM pn_base ll
            LEFT JOIN DM_TRAI_GIAMS dtg
                ON dtg.ID = ll.LL_TRAI_GIAM_ID
               AND dtg.IS_DELETED = 0
            LEFT JOIN DM_QUOC_TICHS dqt
                ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
               AND dqt.IS_DELETED = 0
            WHERE ll.IS_DELETED = 0
              AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)
              -- NHÓM 1: Kho?ng ngày
              AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
              AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
              AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
              AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
              AND (
                  (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                  OR EXISTS (
                      SELECT 1
                      FROM PN_DAC_XAS dxa
                      WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                        AND dxa.IS_DELETED = 0
                        AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                        AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                  )
              )
              AND (
                  (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                  OR EXISTS (
                      SELECT 1
                      FROM GIAM_THOI_HANS gaan
                      WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                        AND gaan.IS_DELETED = 0
                        AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                        AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                  )
              )
              -- NHÓM 2: Kho?ng s?
              AND (
                  p_so_tien_an_tu IS NULL
                  OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
              )
              AND (
                  p_so_tien_an_den IS NULL
                  OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
              )
              AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
              AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
              AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
              AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
              AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
              AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
              AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
              AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
              -- NHÓM 3: Danh m?c
              AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
              AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
              AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
              AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
              AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
              AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
              -- [T?i danh]
              AND (
                  p_toi_danh_ids IS NULL
                  OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                  OR EXISTS (SELECT 1
                             FROM selected_toi_danh_filter loc
                             WHERE INSTR(
                                         ',' || REPLACE(
                                                 REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                 ' ', '') || ',',
                                         ',' || TRIM(loc.ma_loc) || ','
                                 ) > 0)
              )
              AND (p_dp_dktt_id       IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
              AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG              = p_loai_doi_tuong_id)
              -- [Ghi chú riêng]
              AND (
                  p_ghi_chu_rieng_id IS NULL
                  OR INSTR(
                             ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                             ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                         ) > 0
              )
              AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
              -- NHÓM 4: Checkbox
              AND (p_nuoc_ngoai IS NULL OR (
                  CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
              ))
              AND (p_co_benh_tat IS NULL OR (
                  CASE
                      WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                          THEN 1
                      WHEN EXISTS (
                          SELECT 1
                          FROM DM_BENH_TATS dbt
                          WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                            AND dbt.IS_DELETED = 0
                            AND dbt.BT_MA = '1'
                      )
                          THEN 0
                      ELSE 1
                  END = p_co_benh_tat
              ))
              AND (p_giam_rieng IS NULL OR (
                  CASE WHEN EXISTS (
                      SELECT 1 FROM PN_GIAM_RIENGS gr
                      WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                        AND gr.IS_DELETED = 0
                  ) THEN 1 ELSE 0 END = p_giam_rieng
              ))
              AND (
                  p_dan_toc_thieu_so IS NULL
                  OR (
                      CASE
                          WHEN EXISTS (
                              SELECT 1
                              FROM DM_DAN_TOCS dt
                              WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                                AND dt.IS_DELETED = 0
                                AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                          )
                          THEN 1
                          ELSE 0
                      END = p_dan_toc_thieu_so
                  )
              )
              AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                  CASE
                      WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                      WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                      WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                      ELSE 0
                  END = p_vtn_thoi_diem_pham_toi
              ))
              AND (p_pham_toi_moi IS NULL OR (
                  CASE WHEN EXISTS (
                      SELECT 1 FROM PHAM_TOI_MOIS ptm
                      WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                        AND ptm.IS_DELETED = 0
                  ) THEN 1 ELSE 0 END = p_pham_toi_moi
              ))
              AND (p_theo_ton_giao IS NULL OR (
                  CASE
                      WHEN EXISTS (
                          SELECT 1
                          FROM DM_TON_GIAOS tg
                          WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                            AND tg.IS_DELETED = 0
                      )
                      THEN 1
                      ELSE 0
                  END = p_theo_ton_giao
              ))
              AND (p_vtn_hien_tai IS NULL OR (
                  CASE
                      WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                      WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                      ELSE 0
                  END = p_vtn_hien_tai
              ))
              AND (p_khong_pham_toi_moi IS NULL OR (
                  CASE WHEN NOT EXISTS (
                      SELECT 1 FROM PHAM_TOI_MOIS ptm
                      WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                        AND ptm.IS_DELETED = 0
                  ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
              ))
              AND (
                  p_co_nghe_nghiep IS NULL
                  OR (
                      CASE
                          WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                               AND EXISTS (
                                   SELECT 1
                                   FROM DM_NGHE_NGHIEPS dnn
                                   WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                     AND dnn.IS_DELETED = 0
                                     AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                               )
                          THEN 1
                          ELSE 0
                      END = p_co_nghe_nghiep
                  )
              )
              AND (p_chung_than IS NULL OR (
                  CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                       THEN 1 ELSE 0 END = p_chung_than
              ))
              AND (p_da_bi_ky_luat IS NULL OR (
                  CASE WHEN EXISTS (
                      SELECT 1 FROM KY_LUATS kl
                      WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                  ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
              ))
              AND (p_co_ghi_chu_dac_biet IS NULL OR (
                  CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                        AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                       THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
              ))
              AND (p_toi_pham_anqg IS NULL OR (
                  CASE WHEN EXISTS (
                      SELECT 1 FROM DM_TOI_DANHS td
                      WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                        AND td.IS_DELETED = 0
                        AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                  ) THEN 1 ELSE 0 END = p_toi_pham_anqg
              ))
              AND (p_da_duoc_khen_thuong IS NULL OR (
                  CASE WHEN EXISTS (
                      SELECT 1 FROM KHEN_THUONGS kt
                      WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                        AND kt.IS_DELETED = 0
                  ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
              ))
              AND (p_co_tien_an IS NULL OR (
                  CASE
                      WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                          THEN 1
                      ELSE 0 END = p_co_tien_an
              ))
              AND (p_co_tien_su IS NULL OR (
                  CASE
                      WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                          THEN 1
                      ELSE 0 END = p_co_tien_su
              ))
              AND (p_con_theo_me_vao_trai IS NULL OR (
                  CASE WHEN EXISTS (
                      SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                      WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                        AND tncc.IS_DELETED = 0
                  ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
              ))
              AND (p_hp_bo_sung_la_tien IS NULL OR (
                  CASE
                      WHEN EXISTS (SELECT 1
                                   FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                   LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                             ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                            AND dhpbs.IS_DELETED = 0
                                   WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                     AND hpbs.IS_DELETED = 0
                                     AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                      ELSE 0 END = p_hp_bo_sung_la_tien
              ))
              AND (p_bat_buoc_chua_benh IS NULL OR (
                  CASE
                      WHEN EXISTS (SELECT 1
                                   FROM CHUA_BENH_BAT_BUOCS cb
                                   WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                     AND cb.IS_DELETED = 0
                                     -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                     -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                     ) THEN 1
                      ELSE 0 END = p_bat_buoc_chua_benh
              ))
              AND (
                  p_hoan_xong_hpbs_la_tien IS NULL OR
                  (CASE
                      WHEN EXISTS (
                          SELECT 1
                          FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                          LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                           AND dhpbs.IS_DELETED = 0
                          WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                            AND hpbs.IS_DELETED = 0
                            AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                          GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                          HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                      ) THEN 1
                      ELSE 0
                  END = p_hoan_xong_hpbs_la_tien)
              )
              AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                  (CASE
                      WHEN EXISTS (
                          SELECT 1
                          FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                          LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                           AND dhpbs.IS_DELETED = 0
                          WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                            AND hpbs.IS_DELETED = 0
                            AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                          GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                          HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                      ) THEN 1
                      ELSE 0
                  END = p_chua_hoan_hpbs_la_tien))
        ),

toi_danh_list AS (
    SELECT DISTINCT
        ptm.PHAM_NHAN_ID,
        dtd.ID      AS TOI_DANH_ID,
        dtd.TD_TEN  AS TOI_DANH_TEN,
        ptm.NGAY_PHAM_TOI
    FROM PHAM_TOI_MOIS ptm
    INNER JOIN LATERAL (
        SELECT
            TO_NUMBER(TRIM(REGEXP_SUBSTR(
                REGEXP_REPLACE(ptm.DM_TOI_DANH, '[\[\]\s]', ''),
                '[^,]+', 1, LEVEL
            ))) AS TOI_DANH_ID_NUM
        FROM DUAL
        WHERE ptm.DM_TOI_DANH IS NOT NULL
          AND LENGTH(TRIM(REGEXP_REPLACE(ptm.DM_TOI_DANH, '[\[\]\s]', ''))) > 0
        CONNECT BY LEVEL <= REGEXP_COUNT(
            REGEXP_REPLACE(ptm.DM_TOI_DANH, '[\[\]\s]', ''),
            '[^,]+'
        )
    ) ids ON 1 = 1
    INNER JOIN DM_TOI_DANHS dtd
        ON dtd.ID         = ids.TOI_DANH_ID_NUM
       AND dtd.IS_DELETED = 0
    WHERE ptm.IS_DELETED = 0
),

chi_tiet AS (
    SELECT
        DENSE_RANK() OVER (
            ORDER BY NLSSORT(tdl.TOI_DANH_TEN, 'NLS_SORT=BINARY_AI')
        ) AS SORT_ORDER,

        TO_NCHAR(TO_CHAR(
            DENSE_RANK() OVER (
                ORDER BY NLSSORT(tdl.TOI_DANH_TEN, 'NLS_SORT=BINARY_AI')
            )
        )) AS "TT",

        TO_NCHAR(tdl.TOI_DANH_TEN) AS "PhamToiMoi",

        COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END) AS "Nam",
	    COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END) AS "Nu",
	    COUNT(CASE WHEN gt.GT_TEN IS NULL
              	  OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
        COUNT(*)                   AS "TongSo"

    FROM pham_nhan_filtered pnf
    INNER JOIN toi_danh_list tdl
        ON pnf.PHAM_NHAN_ID = tdl.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS gt
        ON pnf.LL_DM_GIOI_TINH_ID = gt.ID AND gt.IS_DELETED = 0

    WHERE (v_ngay_tinh IS NULL OR TRUNC(tdl.NGAY_PHAM_TOI) < TRUNC(v_ngay_tinh) + 1)
    GROUP BY tdl.TOI_DANH_ID, tdl.TOI_DANH_TEN
)

    SELECT
        	"TT",
	        "PhamToiMoi",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"

    FROM (
        SELECT
            SORT_ORDER,
			"TT",
	        "PhamToiMoi",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_PHAM_TOI_MOI;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_PHAN_LOAI_GIAM_GIU
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_PHAN_LOAI_GIAM_GIU" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
    WITH
    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                     REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                     '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 ',') + 1
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$') THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT ll.PHAM_NHAN_ID,
               ll.LL_DM_GIOI_TINH_ID,
               ll.LL_DM_QUOC_TICH_ID
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
            AND dqt.IS_DELETED = 0
        WHERE (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)
          AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
          AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
          AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
          AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
          AND (
                (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                OR EXISTS (
                    SELECT 1
                    FROM PN_DAC_XAS dxa
                    WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                      AND dxa.IS_DELETED = 0
                      AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                      AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                )
            )
          AND (
                (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                OR EXISTS (
                    SELECT 1
                    FROM GIAM_THOI_HANS gaan
                    WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                      AND gaan.IS_DELETED   = 0
                      AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                      AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                )
            )
          AND (p_so_tien_an_tu IS NULL OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu))
          AND (p_so_tien_an_den IS NULL OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den))
          AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
          AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
          AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
          AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
          AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
          AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
          AND (p_tg_con_lai_tu  IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
          AND (p_tg_con_lai_den IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)
          AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
          AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
          AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
          AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
          AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
          AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
          AND (
                p_toi_danh_ids IS NULL
                OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                OR EXISTS (
                    SELECT 1
                    FROM selected_toi_danh_filter loc
                    WHERE INSTR(
                            ',' || REPLACE(REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''), ' ', '') || ',',
                            ',' || TRIM(loc.ma_loc) || ','
                          ) > 0
                )
            )
          AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
          AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)
          AND (
                p_ghi_chu_rieng_id IS NULL
                OR INSTR(
                     ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                     ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                   ) > 0
            )
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (p_nuoc_ngoai IS NULL OR (CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai))
          AND (p_co_benh_tat IS NULL OR (
                CASE
                    WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL THEN 1
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_BENH_TATS dbt
                        WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                          AND dbt.IS_DELETED = 0
                          AND dbt.BT_MA = '1'
                    ) THEN 0
                    ELSE 1
                END = p_co_benh_tat
            ))
          AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
            ))
          AND (
                p_dan_toc_thieu_so IS NULL
                OR (
                    CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_DAN_TOCS dt
                            WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                              AND dt.IS_DELETED = 0
                              AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                        ) THEN 1
                        ELSE 0
                    END = p_dan_toc_thieu_so
                )
            )
          AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                CASE
                    WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_thoi_diem_pham_toi
            ))
          AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
            ))
          AND (p_theo_ton_giao IS NULL OR (
                CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_TON_GIAOS tg
                        WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                          AND tg.IS_DELETED = 0
                    ) THEN 1
                    ELSE 0
                END = p_theo_ton_giao
            ))
          AND (p_vtn_hien_tai IS NULL OR (
                CASE
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_hien_tai
            ))
          AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
            ))
          AND (
                p_co_nghe_nghiep IS NULL
                OR (
                    CASE
                        WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                             AND EXISTS (
                                    SELECT 1
                                    FROM DM_NGHE_NGHIEPS dnn
                                    WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                      AND dnn.IS_DELETED = 0
                                      AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                             ) THEN 1
                        ELSE 0
                    END = p_co_nghe_nghiep
                )
            )
          AND (p_chung_than IS NULL OR (
                CASE
                    WHEN ll.THA_MA_AN_PHAT IN (
                        SELECT dmtg.ID
                        FROM DM_MA_THOI_GIANS dmtg
                        WHERE dmtg.MTG_MA IN ('911000', '912000')
                          AND dmtg.IS_DELETED = 0
                    ) THEN 1
                    ELSE 0
                END = p_chung_than
            ))
          AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
            ))
          AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
            ))
          AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))
          AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
            ))
          AND (p_co_tien_an IS NULL OR (
                CASE WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0' THEN 1 ELSE 0 END = p_co_tien_an
            ))
          AND (p_co_tien_su IS NULL OR (
                CASE WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0' THEN 1 ELSE 0 END = p_co_tien_su
            ))
          AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
            ))
          AND (p_hp_bo_sung_la_tien IS NULL OR (
                CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                        LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                            AND dhpbs.IS_DELETED = 0
                        WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                          AND hpbs.IS_DELETED = 0
                          AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                    ) THEN 1
                    ELSE 0
                END = p_hp_bo_sung_la_tien
            ))
          AND (p_bat_buoc_chua_benh IS NULL OR (
                CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM CHUA_BENH_BAT_BUOCS cb
                        WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                          AND cb.IS_DELETED = 0
                    ) THEN 1
                    ELSE 0
                END = p_bat_buoc_chua_benh
            ))
          AND (
                p_hoan_xong_hpbs_la_tien IS NULL
                OR (
                    CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                            LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                             AND dhpbs.IS_DELETED = 0
                            WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                              AND hpbs.IS_DELETED = 0
                              AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                            HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                        ) THEN 1
                        ELSE 0
                    END = p_hoan_xong_hpbs_la_tien
                )
            )
          AND (
                p_chua_hoan_hpbs_la_tien IS NULL
                OR (
                    CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                            LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                             AND dhpbs.IS_DELETED = 0
                            WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                              AND hpbs.IS_DELETED = 0
                              AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                            HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                        ) THEN 1
                        ELSE 0
                    END = p_chua_hoan_hpbs_la_tien
                )
            )
    ),
    pl_moi_nhat AS (
        SELECT pl2.PHAM_NHAN_ID, pl2.DEN_LOAI_ID, pl2.NGAY_PHAN_LOAI
        FROM (
            SELECT
                pl.PHAM_NHAN_ID,
                pl.DEN_LOAI_ID,
                pl.NGAY_PHAN_LOAI,
                ROW_NUMBER() OVER (
                    PARTITION BY pl.PHAM_NHAN_ID
                    ORDER BY pl.NGAY_PHAN_LOAI DESC NULLS LAST, pl.ID DESC
                ) AS rn
            FROM PHAN_LOAIS pl
            WHERE pl.IS_DELETED = 0 
              AND (v_ngay_tinh IS NULL OR pl.NGAY_PHAN_LOAI < v_ngay_tinh + 1)
        ) pl2
        WHERE pl2.rn = 1
    ),
    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY dplgg.ID) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(
                ROW_NUMBER() OVER (ORDER BY dplgg.ID)
            )) AS "TT",
            dplgg.PLGG_TEN AS "PhanLoai",
            COUNT(DISTINCT CASE
                WHEN dgt.GT_TEN = u'Nam'
                THEN pl.PHAM_NHAN_ID
            END) AS "Nam",
            COUNT(DISTINCT CASE
                WHEN dgt.GT_TEN = u'N\1eef'
                THEN pl.PHAM_NHAN_ID
            END) AS "Nu",
            COUNT(DISTINCT CASE
                WHEN NVL(dgt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef')
                THEN pl.PHAM_NHAN_ID
            END) AS "Khac",
            COUNT(DISTINCT pl.PHAM_NHAN_ID) AS "TongSo"
        FROM pl_moi_nhat pl
        INNER JOIN pham_nhan_filtered ll
            ON pl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
        LEFT JOIN DM_GIOI_TINHS dgt
            ON ll.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
        LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg
            ON pl.DEN_LOAI_ID = dplgg.ID AND dplgg.IS_DELETED = 0  
        GROUP BY dplgg.ID, dplgg.PLGG_TEN
    )
    SELECT
        "TT",
        "PhanLoai",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
            "PhanLoai",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_PHAN_LOAI_GIAM_GIU;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_QUOC_TICH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_QUOC_TICH" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH
	    selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ),
             pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID,
            ll.LL_DM_QUOC_TICH_ID,
            ll.THA_NGAY_HET_HAN,
            ll.THA_NGAY_DEN_TRAI,
            ll.THA_DOI_TUONG
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON  dtg.ID = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED         = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                AND dqt.IS_DELETED = 0
        WHERE
            ll.IS_DELETED = 0
            AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)

            -- NHÓM 1: Kho?ng ngày
            AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                      AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                      AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                      AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
            AND (
				    (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM PN_DAC_XAS dxa
				        WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
				          AND dxa.IS_DELETED = 0
				          AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
				          AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
				    )
				)
			AND (
				    (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM GIAM_THOI_HANS gaan
				        WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
				          AND gaan.IS_DELETED   = 0
				          AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
				          AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
				    )
				)

            -- NHÓM 2: Kho?ng s?
                AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
            AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
            AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
            AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
            AND (p_tg_chap_hanh_tu  IS NULL OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
			AND (p_tg_chap_hanh_den IS NULL OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
            AND (p_tg_con_lai_tu  IS NULL OR
                    ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
            AND (p_tg_con_lai_den IS NULL OR
                    ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

            -- NHÓM 3: Danh m?c
            AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
            AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
            AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
            AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
            AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
            AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

            -- [T?i danh]
			AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
            AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id  )
            AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

            -- [Ghi chú riêng]
            AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

            AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

            -- NHÓM 4: Checkbox
            AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
            AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
            AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
            ))
            AND (
									    p_dan_toc_thieu_so IS NULL
									    OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_DAN_TOCS dt
									                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
									                  AND dt.IS_DELETED = 0
									                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
									            )
									            THEN 1
									            ELSE 0
									        END = p_dan_toc_thieu_so
									    )
									)
            AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                CASE
                    WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_thoi_diem_pham_toi
            ))
            AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
            ))
            AND (p_theo_ton_giao IS NULL OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_TON_GIAOS tg
									                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
									                  AND tg.IS_DELETED = 0

									            )
									            THEN 1
									            ELSE 0
									        END = p_theo_ton_giao ))
            AND (p_vtn_hien_tai IS NULL OR (
                CASE
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_hien_tai
            ))
            AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
            ))
            AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
            AND (p_chung_than IS NULL OR (
    CASE WHEN ll.THA_MA_AN_PHAT IN (
        SELECT dmtg.ID FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000') AND dmtg.IS_DELETED = 0
    ) THEN 1 ELSE 0 END = p_chung_than
))
            AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
            ))
            AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
            ))
            AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))
            AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
            ))
            AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
            AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
            AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
            ))
            AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
            AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
            AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
            AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))
    ),

    chi_tiet AS (
        -- Nhóm I: Vi?t Nam
        SELECT
            1 AS SORT_ORDER,
            TO_NCHAR('I') AS "TT",
            TO_NCHAR('Vi?t Nam') AS "QuocTich",
		COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam' THEN ll.PHAM_NHAN_ID  END) AS "Nam",
		COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?' THEN ll.PHAM_NHAN_ID   END) AS "Nu",
		COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN ll.PHAM_NHAN_ID   END) AS "Khac",
		COUNT(DISTINCT ll.PHAM_NHAN_ID ) AS "TongSo"
        FROM pham_nhan_filtered ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_QUOC_TICHS dqt ON ll.LL_DM_QUOC_TICH_ID = dqt.ID
        WHERE (dqt.QT_MA = 250 OR dqt.QT_TEN IS NULL)

        UNION ALL

        -- Nhóm II: N??c ngoài
        SELECT
            2 AS SORT_ORDER,
            TO_NCHAR('II') AS "TT",
            TO_NCHAR('N??c ngoài') AS "QuocTich",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM pham_nhan_filtered ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_QUOC_TICHS dqt ON ll.LL_DM_QUOC_TICH_ID = dqt.ID
        WHERE dqt.QT_MA <> 250
		)

    SELECT
        	"TT",
	        "QuocTich",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
			"TT",
	        "QuocTich",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_QUOC_TICH;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_SO_TIEN_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_SO_TIEN_AN" (
    p_trai_giam_id IN NVARCHAR2 DEFAULT NULL,
    p_tu_ngay IN NVARCHAR2 DEFAULT NULL,
    p_den_ngay IN NVARCHAR2 DEFAULT NULL
)
AS
    v_tu_ngay NVARCHAR2(10);
    v_den_ngay NVARCHAR2(10);
    C1 SYS_REFCURSOR;  
BEGIN 
     IF p_tu_ngay IS NULL OR p_tu_ngay = '' THEN
        v_tu_ngay := to_char(sysdate - 1, 'DD/MM/YYYY');
        ELSE v_tu_ngay := p_tu_ngay;
    END IF;

    IF p_den_ngay IS NULL OR p_den_ngay = '' THEN
        v_den_ngay := to_char(sysdate - 1, 'DD/MM/YYYY');
        ELSE v_den_ngay := p_den_ngay;
    END IF;

      OPEN C1 FOR
		SELECT CASE WHEN ll.LL_SO_TIEN_AN IS NULL OR ll.LL_SO_TIEN_AN = 0 THEN 'Ch?a có ti?n án'
		            WHEN ll.LL_SO_TIEN_AN = 1 THEN 'Có 1 ti?n án'
		            WHEN ll.LL_SO_TIEN_AN = 2 THEN 'Có 2 ti?n án'
		            WHEN ll.LL_SO_TIEN_AN >= 3 THEN 'Có 3 ti?n án tr? lên'
		        END SO_TIEN_AN,
			 COUNT(DISTINCT ll.PHAM_NHAN_ID) AS TONG_SO
		FROM (
		     SELECT ID AS PHAM_NHAN_ID, LL_DM_GIOI_TINH_ID, LL_TRAI_GIAM_ID, LL_SO_TIEN_AN 
			 FROM PN_LAI_LICHS
			 WHERE IS_DELETED=0
		     ) ll 
		LEFT JOIN (
				  SELECT THA_PNLAI_LICH_ID, THA_NGAY_DEN_TRAI AS NGAY_DEN_TRAI
				  FROM PN_THI_HANH_AN
				  WHERE IS_DELETED = 0
				) ptha ON ptha.THA_PNLAI_LICH_ID = ll.PHAM_NHAN_ID
--		LEFT JOIN DM_GIOI_TINHS dgt
--		    ON ll.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0 
		WHERE (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
			AND (p_tu_ngay IS NULL 
            	OR p_den_ngay IS NULL 
            	OR ptha.NGAY_DEN_TRAI BETWEEN TO_TIMESTAMP(v_tu_ngay, 'DD/MM/YYYY') AND  TO_TIMESTAMP(v_den_ngay, 'DD/MM/YYYY'))
		GROUP BY CASE WHEN ll.LL_SO_TIEN_AN IS NULL OR ll.LL_SO_TIEN_AN = 0 THEN 'Ch?a có ti?n án'
		            WHEN ll.LL_SO_TIEN_AN = 1 THEN 'Có 1 ti?n án'
		            WHEN ll.LL_SO_TIEN_AN = 2 THEN 'Có 2 ti?n án'
		            WHEN ll.LL_SO_TIEN_AN >= 3 THEN 'Có 3 ti?n án tr? lên'
		        END
		ORDER BY TONG_SO DESC, SO_TIEN_AN
		;

      DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_SO_TIEN_AN;







/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_TAI_PHAM
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_TAI_PHAM" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH
        selected_toi_danh_filter AS (
            SELECT TRIM(REGEXP_SUBSTR(
                            REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                            '[^,]+', 1, LEVEL)) AS ma_loc
            FROM DUAL
            CONNECT BY LEVEL <= REGEXP_COUNT(
                                    REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                    ',') + 1),
        pn_base AS (
            SELECT
                ll.*,
                CASE
                    WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                    WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$') THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                    ELSE NULL
                END AS SO_TIEN_AN_NUM,
                QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
            INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
               AND tt.NGAY_XET = v_ngay_tinh
               AND tt.TTPN_MA IN ('111', '112', '113', '114')
            WHERE ll.IS_DELETED = 0
              AND NVL(ll.LL_IS_DELETED, 0) = 0
              AND NVL(ll.THA_IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        ),
        pham_nhan_filtered AS (
            SELECT
                ll.PHAM_NHAN_ID,
                ll.LL_DM_GIOI_TINH_ID,
                ll.LL_DM_QUOC_TICH_ID,
                ll.LL_TAI_PHAM,
                ll.THA_NGAY_HET_HAN,
                ll.THA_NGAY_DEN_TRAI,
                ll.THA_DOI_TUONG,
                ll.THA_MUC_AN_ID,
                ll.LL_GHI_CHU_RIENG
            FROM pn_base ll
            LEFT JOIN DM_TRAI_GIAMS dtg
                ON dtg.ID = ll.LL_TRAI_GIAM_ID
                AND dtg.IS_DELETED = 0
            LEFT JOIN DM_QUOC_TICHS dqt
                ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                AND dqt.IS_DELETED = 0
            WHERE ll.IS_DELETED = 0
                AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)
                -- NHÓM 1: Kho?ng ngày
                AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                AND (
                    (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                    OR EXISTS (
                        SELECT 1
                        FROM PN_DAC_XAS dxa
                        WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                          AND dxa.IS_DELETED = 0
                          AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                          AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                    )
                )
                AND (
                    (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                    OR EXISTS (
                        SELECT 1
                        FROM GIAM_THOI_HANS gaan
                        WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                          AND gaan.IS_DELETED   = 0
                          AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                          AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                    )
                )

                -- NHÓM 2: Kho?ng s?
                AND (
                    p_so_tien_an_tu IS NULL
                    OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                )
                AND (
                    p_so_tien_an_den IS NULL
                    OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                )
                AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
                AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                AND (p_tg_con_lai_tu  IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                AND (p_tg_con_lai_den IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                -- NHÓM 3: Danh m?c
                AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
                AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
                AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
                AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
                AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
                AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

                -- [T?i danh]
                AND (
                    p_toi_danh_ids IS NULL
                        OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                        OR EXISTS (SELECT 1
                                   FROM selected_toi_danh_filter loc
                                   WHERE INSTR(
                                                 ',' || REPLACE(
                                                         REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                         ' ', '') || ',',
                                                 ',' || TRIM(loc.ma_loc) || ','
                                         ) > 0)
                    )
                AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

                -- [Ghi chú riêng]
                AND (
                    p_ghi_chu_rieng_id IS NULL
                        OR INSTR(
                                   ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                   ',',
                                   ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                           ) > 0
                    )

                AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                -- NHÓM 4: Checkbox
                AND (p_nuoc_ngoai IS NULL OR (
                    CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                    ))
                AND (p_co_benh_tat IS NULL OR (
                    CASE
                        WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                            THEN 1
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_BENH_TATS dbt
                            WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                            AND dbt.IS_DELETED = 0
                            AND dbt.BT_MA = '1'
                        )
                            THEN 0
                        ELSE 1
                    END = p_co_benh_tat
                ))
                AND (p_giam_rieng IS NULL OR (
                    CASE WHEN EXISTS (
                        SELECT 1 FROM PN_GIAM_RIENGS gr
                        WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                    ) THEN 1 ELSE 0 END = p_giam_rieng
                ))
                AND (
                    p_dan_toc_thieu_so IS NULL
                    OR (
                        CASE
                            WHEN EXISTS (
                                SELECT 1
                                FROM DM_DAN_TOCS dt
                                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                                  AND dt.IS_DELETED = 0
                                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                            )
                            THEN 1
                            ELSE 0
                        END = p_dan_toc_thieu_so
                    )
                )
                AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                    CASE
                        WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                        WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                        ELSE 0
                        END = p_vtn_thoi_diem_pham_toi
                    ))
                AND (p_pham_toi_moi IS NULL OR (
                    CASE WHEN EXISTS (
                        SELECT 1 FROM PHAM_TOI_MOIS ptm
                        WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                    ) THEN 1 ELSE 0 END = p_pham_toi_moi
                ))
                AND (p_theo_ton_giao IS NULL OR (
                    CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_TON_GIAOS tg
                            WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                              AND tg.IS_DELETED = 0
                        )
                        THEN 1
                        ELSE 0
                    END = p_theo_ton_giao ))
                AND (p_vtn_hien_tai IS NULL OR (
                    CASE
                        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                        WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                        ELSE 0
                        END = p_vtn_hien_tai
                    ))
                AND (p_khong_pham_toi_moi IS NULL OR (
                    CASE WHEN NOT EXISTS (
                        SELECT 1 FROM PHAM_TOI_MOIS ptm
                        WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                    ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
                ))
                AND (
                    p_co_nghe_nghiep IS NULL
                    OR (
                        CASE
                            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                                 AND EXISTS (
                                        SELECT 1
                                        FROM DM_NGHE_NGHIEPS dnn
                                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                          AND dnn.IS_DELETED = 0
                                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                                 )
                            THEN 1
                            ELSE 0
                        END = p_co_nghe_nghiep
                    )
                )
                AND (p_chung_than IS NULL OR (
                    CASE WHEN ll.THA_MA_AN_PHAT IN (
                        SELECT dmtg.ID FROM DM_MA_THOI_GIANS dmtg
                        WHERE dmtg.MTG_MA IN ('911000', '912000') AND dmtg.IS_DELETED = 0
                    ) THEN 1 ELSE 0 END = p_chung_than
                ))
                AND (p_da_bi_ky_luat IS NULL OR (
                    CASE WHEN EXISTS (
                        SELECT 1 FROM KY_LUATS kl
                        WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
                ))
                AND (p_co_ghi_chu_dac_biet IS NULL OR (
                    CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                          AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                         THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
                ))
                AND (p_toi_pham_anqg IS NULL OR (
                    CASE WHEN EXISTS (
                        SELECT 1 FROM DM_TOI_DANHS td
                        WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                          AND td.IS_DELETED = 0
                          AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                    ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                ))
                AND (p_da_duoc_khen_thuong IS NULL OR (
                    CASE WHEN EXISTS (
                        SELECT 1 FROM KHEN_THUONGS kt
                        WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                    ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
                ))
                AND (p_co_tien_an IS NULL OR (
                    CASE
                        WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                            THEN 1
                        ELSE 0 END = p_co_tien_an
                    ))
                AND (p_co_tien_su IS NULL OR (
                    CASE
                        WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                            THEN 1
                        ELSE 0 END = p_co_tien_su
                    ))
                AND (p_con_theo_me_vao_trai IS NULL OR (
                    CASE WHEN EXISTS (
                        SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                        WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                    ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
                ))
                AND (p_hp_bo_sung_la_tien IS NULL OR (
                    CASE
                        WHEN EXISTS (SELECT 1
                                     FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                              LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                            AND dhpbs.IS_DELETED = 0
                                     WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                       AND hpbs.IS_DELETED = 0
                                       AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                        ELSE 0 END = p_hp_bo_sung_la_tien
                    ))
                AND (p_bat_buoc_chua_benh IS NULL OR (
                    CASE
                        WHEN EXISTS (SELECT 1
                                     FROM CHUA_BENH_BAT_BUOCS cb
                                     WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                       	AND cb.IS_DELETED = 0
                                       	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                              			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                       ) THEN 1
                        ELSE 0 END = p_bat_buoc_chua_benh
                    ))
                AND (
                    p_hoan_xong_hpbs_la_tien IS NULL OR
                    (CASE
                            WHEN EXISTS (
                                SELECT 1
                                FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                  ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                 AND dhpbs.IS_DELETED = 0
                                WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                  AND hpbs.IS_DELETED = 0
                                  AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                            ) THEN 1
                            ELSE 0
                        END = p_hoan_xong_hpbs_la_tien))
                AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                    ( CASE
                            WHEN EXISTS (
                                SELECT 1
                                FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                  ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                 AND dhpbs.IS_DELETED = 0
                                WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                  AND hpbs.IS_DELETED = 0
                                  AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                            ) THEN 1
                            ELSE 0
                        END = p_chua_hoan_hpbs_la_tien))
        ),

chi_tiet AS (
    	SELECT
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ))) AS "TT",
            dtp.TP_TEN AS "TinhChatToiPham",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'Nam' THEN pn.PHAM_NHAN_ID END)                                      AS "Nam",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'N\1eef' THEN pn.PHAM_NHAN_ID END)                                   AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(gt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN pn.PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT pn.PHAM_NHAN_ID)                                                                              AS "TongSo"
        FROM pham_nhan_filtered pn
        LEFT JOIN DM_TAI_PHAMS dtp
            ON dtp.ID = pn.LL_TAI_PHAM
           AND dtp.IS_DELETED = 0
        LEFT JOIN DM_GIOI_TINHS gt
            ON gt.ID = pn.LL_DM_GIOI_TINH_ID
           AND gt.IS_DELETED = 0
        WHERE LL_TAI_PHAM IS NOT NULL
        GROUP BY dtp.TP_TEN)

    SELECT
			"TT",
	        "TinhChatToiPham",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
			"TT",
	        "TinhChatToiPham",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_TAI_PHAM;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_TAM_DINH_CHI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_TAM_DINH_CHI" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH
        selected_toi_danh_filter AS (
            SELECT TRIM(REGEXP_SUBSTR(
                            REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                            '[^,]+', 1, LEVEL)) AS ma_loc
            FROM DUAL
            CONNECT BY LEVEL <= REGEXP_COUNT(
                                    REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                    ',') + 1),
        chung_than_ids AS (
            SELECT dmtg.ID
            FROM DM_MA_THOI_GIANS dmtg
            WHERE dmtg.MTG_MA IN ('911000', '912000')
              AND dmtg.IS_DELETED = 0
        ),
        pn_base AS (
            SELECT
                ll.*,
                CASE
                    WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                    WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                        THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                    ELSE NULL
                END AS SO_TIEN_AN_NUM,
                QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
            INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
               AND tt.NGAY_XET = v_ngay_tinh
               AND tt.TTPN_MA IN ('111', '112', '113', '114',
                                  '151', '152', '153', '154', '155',
                                  '156', '157', '158', '159')
            WHERE ll.IS_DELETED = 0
              AND NVL(ll.LL_IS_DELETED, 0) = 0
              AND NVL(ll.THA_IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        ),
        pham_nhan_filtered AS (
            SELECT
                ll.PHAM_NHAN_ID,
                ll.LL_DM_GIOI_TINH_ID
            FROM pn_base ll
            LEFT JOIN DM_TRAI_GIAMS dtg
                ON dtg.ID = ll.LL_TRAI_GIAM_ID
               AND dtg.IS_DELETED = 0
            LEFT JOIN DM_QUOC_TICHS dqt
                ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
               AND dqt.IS_DELETED = 0
            WHERE ll.IS_DELETED = 0
              AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)
              -- NHÓM 1: Kho?ng ngày
              AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
              AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
              AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
              AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
              AND (
                  (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                  OR EXISTS (
                      SELECT 1
                      FROM PN_DAC_XAS dxa
                      WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                        AND dxa.IS_DELETED = 0
                        AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                        AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                  )
              )
              AND (
                  (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                  OR EXISTS (
                      SELECT 1
                      FROM GIAM_THOI_HANS gaan
                      WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                        AND gaan.IS_DELETED = 0
                        AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                        AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                  )
              )
              -- NHÓM 2: Kho?ng s?
              AND (
                  p_so_tien_an_tu IS NULL
                  OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
              )
              AND (
                  p_so_tien_an_den IS NULL
                  OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
              )
              AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
              AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
              AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
              AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
              AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
              AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
              AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
              AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
              -- NHÓM 3: Danh m?c
              AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
              AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
              AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
              AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
              AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
              AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
              -- [T?i danh]
              AND (
                  p_toi_danh_ids IS NULL
                  OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                  OR EXISTS (SELECT 1
                             FROM selected_toi_danh_filter loc
                             WHERE INSTR(
                                         ',' || REPLACE(
                                                 REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                 ' ', '') || ',',
                                         ',' || TRIM(loc.ma_loc) || ','
                                 ) > 0)
              )
              AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
              AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG              = p_loai_doi_tuong_id)
              -- [Ghi chú riêng]
              AND (
                  p_ghi_chu_rieng_id IS NULL
                  OR INSTR(
                             ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                             ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                         ) > 0
              )
              AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
              -- NHÓM 4: Checkbox
              AND (p_nuoc_ngoai IS NULL OR (
                  CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
              ))
              AND (p_co_benh_tat IS NULL OR (
                  CASE
                      WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                          THEN 1
                      WHEN EXISTS (
                          SELECT 1
                          FROM DM_BENH_TATS dbt
                          WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                            AND dbt.IS_DELETED = 0
                            AND dbt.BT_MA = '1'
                      )
                          THEN 0
                      ELSE 1
                  END = p_co_benh_tat
              ))
              AND (p_giam_rieng IS NULL OR (
                  CASE WHEN EXISTS (
                      SELECT 1 FROM PN_GIAM_RIENGS gr
                      WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                        AND gr.IS_DELETED = 0
                  ) THEN 1 ELSE 0 END = p_giam_rieng
              ))
              AND (
                  p_dan_toc_thieu_so IS NULL
                  OR (
                      CASE
                          WHEN EXISTS (
                              SELECT 1
                              FROM DM_DAN_TOCS dt
                              WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                                AND dt.IS_DELETED = 0
                                AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                          )
                          THEN 1
                          ELSE 0
                      END = p_dan_toc_thieu_so
                  )
              )
              AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                  CASE
                      WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                      WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                      WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                      ELSE 0
                  END = p_vtn_thoi_diem_pham_toi
              ))
              AND (p_pham_toi_moi IS NULL OR (
                  CASE WHEN EXISTS (
                      SELECT 1 FROM PHAM_TOI_MOIS ptm
                      WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                        AND ptm.IS_DELETED = 0
                  ) THEN 1 ELSE 0 END = p_pham_toi_moi
              ))
              AND (p_theo_ton_giao IS NULL OR (
                  CASE
                      WHEN EXISTS (
                          SELECT 1
                          FROM DM_TON_GIAOS tg
                          WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                            AND tg.IS_DELETED = 0
                      )
                      THEN 1
                      ELSE 0
                  END = p_theo_ton_giao
              ))
              AND (p_vtn_hien_tai IS NULL OR (
                  CASE
                      WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                      WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                      ELSE 0
                  END = p_vtn_hien_tai
              ))
              AND (p_khong_pham_toi_moi IS NULL OR (
                  CASE WHEN NOT EXISTS (
                      SELECT 1 FROM PHAM_TOI_MOIS ptm
                      WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                        AND ptm.IS_DELETED = 0
                  ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
              ))
              AND (
                  p_co_nghe_nghiep IS NULL
                  OR (
                      CASE
                          WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                               AND EXISTS (
                                   SELECT 1
                                   FROM DM_NGHE_NGHIEPS dnn
                                   WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                     AND dnn.IS_DELETED = 0
                                     AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                               )
                          THEN 1
                          ELSE 0
                      END = p_co_nghe_nghiep
                  )
              )
              AND (p_chung_than IS NULL OR (
                  CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                       THEN 1 ELSE 0 END = p_chung_than
              ))
              AND (p_da_bi_ky_luat IS NULL OR (
                  CASE WHEN EXISTS (
                      SELECT 1 FROM KY_LUATS kl
                      WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                  ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
              ))
              AND (p_co_ghi_chu_dac_biet IS NULL OR (
                  CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                        AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                       THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
              ))
              AND (p_toi_pham_anqg IS NULL OR (
                  CASE WHEN EXISTS (
                      SELECT 1 FROM DM_TOI_DANHS td
                      WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                        AND td.IS_DELETED = 0
                        AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                  ) THEN 1 ELSE 0 END = p_toi_pham_anqg
              ))
              AND (p_da_duoc_khen_thuong IS NULL OR (
                  CASE WHEN EXISTS (
                      SELECT 1 FROM KHEN_THUONGS kt
                      WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                        AND kt.IS_DELETED = 0
                  ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
              ))
              AND (p_co_tien_an IS NULL OR (
                  CASE
                      WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                          THEN 1
                      ELSE 0 END = p_co_tien_an
              ))
              AND (p_co_tien_su IS NULL OR (
                  CASE
                      WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                          THEN 1
                      ELSE 0 END = p_co_tien_su
              ))
              AND (p_con_theo_me_vao_trai IS NULL OR (
                  CASE WHEN EXISTS (
                      SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                      WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                        AND tncc.IS_DELETED = 0
                  ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
              ))
              AND (p_hp_bo_sung_la_tien IS NULL OR (
                  CASE
                      WHEN EXISTS (SELECT 1
                                   FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                   LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                             ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                            AND dhpbs.IS_DELETED = 0
                                   WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                     AND hpbs.IS_DELETED = 0
                                     AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                      ELSE 0 END = p_hp_bo_sung_la_tien
              ))
              AND (p_bat_buoc_chua_benh IS NULL OR (
                  CASE
                      WHEN EXISTS (SELECT 1
                                   FROM CHUA_BENH_BAT_BUOCS cb
                                   WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                     AND cb.IS_DELETED = 0
                                     -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                     -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                     ) THEN 1
                      ELSE 0 END = p_bat_buoc_chua_benh
              ))
              AND (
                  p_hoan_xong_hpbs_la_tien IS NULL OR
                  (CASE
                      WHEN EXISTS (
                          SELECT 1
                          FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                          LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                           AND dhpbs.IS_DELETED = 0
                          WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                            AND hpbs.IS_DELETED = 0
                            AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                          GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                          HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                      ) THEN 1
                      ELSE 0
                  END = p_hoan_xong_hpbs_la_tien)
              )
              AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                  (CASE
                      WHEN EXISTS (
                          SELECT 1
                          FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                          LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                           AND dhpbs.IS_DELETED = 0
                          WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                            AND hpbs.IS_DELETED = 0
                            AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                          GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                          HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                      ) THEN 1
                      ELSE 0
                  END = p_chua_hoan_hpbs_la_tien))
        ),

chi_tiet AS (
        SELECT
           	ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ))) AS "TT",
            dldtdc.LDTDC_TEN AS "LyDoTamDinhChi",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END) AS "Nam",
		   	COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END) AS "Nu",
		   	COUNT(CASE WHEN gt.GT_TEN IS NULL
                  	  OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
           	COUNT(*)                   AS "TongSo"
        FROM TAM_DINH_CHIS tdc
        INNER JOIN pham_nhan_filtered pn
            ON pn.PHAM_NHAN_ID = tdc.PHAM_NHAN_ID
        LEFT JOIN DM_LY_DO_TAM_DINH_CHIES dldtdc
            ON dldtdc.ID = tdc.LY_DO_SUC_KHOE_ID
           AND dldtdc.IS_DELETED = 0
        LEFT JOIN DM_GIOI_TINHS gt
            ON gt.ID = pn.LL_DM_GIOI_TINH_ID
           AND gt.IS_DELETED = 0
        WHERE tdc.IS_DELETED = 0
          AND (v_ngay_tinh IS NULL OR TRUNC(tdc.NGAY_TDC) < TRUNC(v_ngay_tinh) + 1)
        GROUP BY dldtdc.LDTDC_TEN
)

    SELECT
			"TT",
	        "LyDoTamDinhChi",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
			"TT",
	        "LyDoTamDinhChi",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_TAM_DINH_CHI;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_TIEN_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_TIEN_AN" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$') THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID,
            ll.LL_DM_HOC_VAN_ID,
            ll.LL_DM_NGHE_NGHIEP_ID,
            ll.LL_SO_TIEN_AN,
            ll.LL_SO_TIEN_SU,
            ll.THA_THOI_GIAN_DA_CHAP_HANH,
            ll.THA_THOI_GIAN_CON_LAI
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON  dtg.ID = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
            AND dqt.IS_DELETED = 0
        WHERE
            ll.IS_DELETED = 0
            AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)

            -- NHÓM 1: Kho?ng ngày
            AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                              AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                              AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                              AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
            AND (
				    (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM PN_DAC_XAS dxa
				        WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
				          AND dxa.IS_DELETED = 0
				          AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
				          AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
				    )
				)
		AND (
				    (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM GIAM_THOI_HANS gaan
				        WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
				          AND gaan.IS_DELETED   = 0
				          AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
				          AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
				    )
				)

            -- NHÓM 2: Kho?ng s?
                AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
            AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
            AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
            AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))

            AND (p_tg_chap_hanh_tu  IS NULL OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
		AND (p_tg_chap_hanh_den IS NULL OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
            AND (p_tg_con_lai_tu  IS NULL OR
                    ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
            AND (p_tg_con_lai_den IS NULL OR
                    ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

            -- NHÓM 3: Danh m?c
            AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
            AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
            AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
            AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
            AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
            AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

            -- [T?i danh] input d?ng [123,453] ho?c 123,453
            AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )

            AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id  )
            AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

            -- [Ghi chú riêng] input d?ng 123 
            AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )


            AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)

            -- NHÓM 4: Checkbox

            -- [N??c ngoài]
            AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))

            -- [Có b?nh t?t]
            AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))

            -- [Giam riêng]
            AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
            ))

            -- [Dân t?c thi?u s?]
            AND (
									    p_dan_toc_thieu_so IS NULL
									    OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_DAN_TOCS dt
									                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
									                  AND dt.IS_DELETED = 0
									                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
									            )
									            THEN 1
									            ELSE 0
									        END = p_dan_toc_thieu_so
									    )
									)

            -- [VTN t?i th?i ?i?m ph?m t?i]
            AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
			    CASE
			        WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
			        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
			        WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
			        ELSE 0
			    END = p_vtn_thoi_diem_pham_toi
			))

            -- [Ph?m t?i m?i]
            AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
            ))

            -- [Theo tôn giáo]
            AND (p_theo_ton_giao IS NULL OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_TON_GIAOS tg
									                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
									                  AND tg.IS_DELETED = 0

									            )
									            THEN 1
									            ELSE 0
									        END = p_theo_ton_giao ))

            -- [VTN t?i th?i ?i?m hi?n t?i]
            AND (p_vtn_hien_tai IS NULL OR (
			    CASE
			        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
			        WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
			        ELSE 0
			    END = p_vtn_hien_tai
			))

            -- [Không ph?m t?i m?i]
            AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
            ))

            -- [Có ngh? nghi?p]
            AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)

            -- [Chung thân]
            AND (p_chung_than IS NULL OR (
    CASE WHEN ll.THA_MA_AN_PHAT IN (
        SELECT dmtg.ID FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000') AND dmtg.IS_DELETED = 0
    ) THEN 1 ELSE 0 END = p_chung_than
))

            -- [?ã b? k? lu?t]
            AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
            ))

            -- [Có ghi chú ??c bi?t]
            AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
            ))

            -- [T?i ph?m ANQG]
            AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))

            -- [?ã ???c khen th??ng]
            AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
            ))

            -- [Có ti?n án]
            AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))

            -- [Có ti?n s?]
            AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))

            -- [Con theo m? vào tr?i]
            AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
            ))

            -- [Hình ph?t b? sung là ti?n]
            AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))

            -- [B?t bu?c ch?a b?nh]
            AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))

            -- [Hoàn xong HPBS là ti?n]
            AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))

            -- [Ch?a hoàn xong HPBS là ti?n]
            AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))
    ),

    chi_tiet AS (                
        SELECT
            ROW_NUMBER() OVER (ORDER BY NVL(pn.LL_SO_TIEN_AN, 0)) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY NVL(pn.LL_SO_TIEN_AN, 0)))) AS "TT",
            TO_NCHAR(TO_CHAR(NVL(pn.LL_SO_TIEN_AN, 0)) || u' ti\1ec1n \00e1n') AS "TienAn",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'Nam' THEN pn.PHAM_NHAN_ID END)                                      AS "Nam",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'N\1eef' THEN pn.PHAM_NHAN_ID END)                                   AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(gt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN pn.PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT pn.PHAM_NHAN_ID)                                                                              AS "TongSo"
        FROM pham_nhan_filtered pn
        LEFT JOIN DM_GIOI_TINHS gt
            ON gt.ID = pn.LL_DM_GIOI_TINH_ID
           AND NVL(gt.IS_DELETED, 0) = 0
        GROUP BY NVL(pn.LL_SO_TIEN_AN, 0)
	    )

    SELECT
        "TT",
        "TienAn",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
	        "TienAn",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_TIEN_AN;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_TIEN_SU
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_TIEN_SU" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$') THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID,
            ll.LL_DM_HOC_VAN_ID,
            ll.LL_DM_NGHE_NGHIEP_ID,
            ll.LL_SO_TIEN_AN,
            ll.LL_SO_TIEN_SU,
            ll.THA_THOI_GIAN_DA_CHAP_HANH,
            ll.THA_THOI_GIAN_CON_LAI
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON  dtg.ID = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
            AND dqt.IS_DELETED = 0
        WHERE
            ll.IS_DELETED = 0
            AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)

            -- NHÓM 1: Kho?ng ngày
            AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                              AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                              AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                              AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
            AND (
				    (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM PN_DAC_XAS dxa
				        WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
				          AND dxa.IS_DELETED = 0
				          AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
				          AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
				    )
				)
		AND (
				    (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM GIAM_THOI_HANS gaan
				        WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
				          AND gaan.IS_DELETED   = 0
				          AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
				          AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
				    )
				)

            -- NHÓM 2: Kho?ng s?
                AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
            AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
            AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
            AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
		    AND (p_tg_chap_hanh_tu  IS NULL OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
		AND (p_tg_chap_hanh_den IS NULL OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
            AND (p_tg_con_lai_tu  IS NULL OR
                    ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
            AND (p_tg_con_lai_den IS NULL OR
                    ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

            -- NHÓM 3: Danh m?c
            AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
            AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
            AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
            AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
            AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
            AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

            -- [T?i danh] input d?ng [123,453] ho?c 123,453
            AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )

            AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id  )
            AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

            -- [Ghi chú riêng] input d?ng 123 
            AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )


            AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)

            -- NHÓM 4: Checkbox

            -- [N??c ngoài]
            AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))

            -- [Có b?nh t?t]
            AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))

            -- [Giam riêng]
            AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
            ))

            -- [Dân t?c thi?u s?]
            AND (
									    p_dan_toc_thieu_so IS NULL
									    OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_DAN_TOCS dt
									                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
									                  AND dt.IS_DELETED = 0
									                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
									            )
									            THEN 1
									            ELSE 0
									        END = p_dan_toc_thieu_so
									    )
									)

            -- [VTN t?i th?i ?i?m ph?m t?i]
            AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
			    CASE
			        WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
			        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
			        WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
			        ELSE 0
			    END = p_vtn_thoi_diem_pham_toi
			))

            -- [Ph?m t?i m?i]
            AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
            ))

            -- [Theo tôn giáo]
            AND (p_theo_ton_giao IS NULL OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_TON_GIAOS tg
									                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
									                  AND tg.IS_DELETED = 0

									            )
									            THEN 1
									            ELSE 0
									        END = p_theo_ton_giao ))

            -- [VTN t?i th?i ?i?m hi?n t?i]
            AND (p_vtn_hien_tai IS NULL OR (
			    CASE
			        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
			        WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
			        ELSE 0
			    END = p_vtn_hien_tai
			))

            -- [Không ph?m t?i m?i]
            AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
            ))

            -- [Có ngh? nghi?p]
            AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)

            -- [Chung thân]
            AND (p_chung_than IS NULL OR (
    CASE WHEN ll.THA_MA_AN_PHAT IN (
        SELECT dmtg.ID FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000') AND dmtg.IS_DELETED = 0
    ) THEN 1 ELSE 0 END = p_chung_than
))

            -- [?ã b? k? lu?t]
            AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
            ))

            -- [Có ghi chú ??c bi?t]
            AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
            ))

            -- [T?i ph?m ANQG]
            AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))

            -- [?ã ???c khen th??ng]
            AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
            ))

            -- [Có ti?n án]
            AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))

            -- [Có ti?n s?]
            AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))

            -- [Con theo m? vào tr?i]
            AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
            ))

            -- [Hình ph?t b? sung là ti?n]
            AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))

            -- [B?t bu?c ch?a b?nh]
            AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))

            -- [Hoàn xong HPBS là ti?n]
            AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))

            -- [Ch?a hoàn xong HPBS là ti?n]
            AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))
    ),

    chi_tiet AS (                
         SELECT
            ROW_NUMBER() OVER (ORDER BY NVL(pn.LL_SO_TIEN_SU, 0)) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY NVL(pn.LL_SO_TIEN_SU, 0)))) AS "TT",
            TO_NCHAR(TO_CHAR(NVL(pn.LL_SO_TIEN_SU, 0)) || u' ti\1ec1n s\1ef1') AS "TienSu",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'Nam' THEN pn.PHAM_NHAN_ID END)                                      AS "Nam",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'N\1eef' THEN pn.PHAM_NHAN_ID END)                                   AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(gt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN pn.PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT pn.PHAM_NHAN_ID)                                                                              AS "TongSo"
        FROM pham_nhan_filtered pn
        LEFT JOIN DM_GIOI_TINHS gt
            ON gt.ID = pn.LL_DM_GIOI_TINH_ID
           AND NVL(gt.IS_DELETED, 0) = 0
        GROUP BY NVL(pn.LL_SO_TIEN_SU, 0)
	    )

    SELECT
        "TT",
        "TienSu",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
	        "TienSu",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_TIEN_SU;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_TINH_TRANG_SUC_KHOE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_TINH_TRANG_SUC_KHOE" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

                 selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ), 
             pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID AS pham_nhan_id,
            ll.LL_DM_GIOI_TINH_ID,
            ll.LL_DM_HOC_VAN_ID,
            ll.LL_DM_NGHE_NGHIEP_ID,
            ll.LL_SO_TIEN_AN,
            ll.LL_SO_TIEN_SU,
            dmbt.BT_TEN,
            ll.THA_THOI_GIAN_DA_CHAP_HANH,
            ll.THA_THOI_GIAN_CON_LAI
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON  dtg.ID = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED         = 0
        LEFT JOIN DM_BENH_TATS dmbt 
        	ON dmbt.ID = ll.LL_BENH_HIEN_TAI_ID
        	AND dmbt.IS_DELETED         = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                AND dqt.IS_DELETED = 0
        --LEFT JOIN PN_DAC_XAS dxa ON  dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID AND dxa.IS_DELETED    = 0
        --LEFT JOIN GIAM_THOI_HANS gaan ON  gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND gaan.IS_DELETED   = 0
        WHERE
            ll.IS_DELETED = 0
            AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)

            -- NHÓM 1: Kho?ng ngày
            AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                      AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                      AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                      AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
            AND (
				    (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM PN_DAC_XAS dxa
				        WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
				          AND dxa.IS_DELETED = 0
				          AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
				          AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
				    )
				)
			AND (
				    (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM GIAM_THOI_HANS gaan
				        WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
				          AND gaan.IS_DELETED   = 0
				          AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
				          AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
				    )
				)

            -- NHÓM 2: Kho?ng s?
                AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
            AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
            AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
            AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
		    AND (p_tg_chap_hanh_tu  IS NULL OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
			AND (p_tg_chap_hanh_den IS NULL OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
            AND (p_tg_con_lai_tu  IS NULL OR
                    ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
            AND (p_tg_con_lai_den IS NULL OR
                    ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

            -- NHÓM 3: Danh m?c
            AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
            AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
            AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
            AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
            AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
            AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

            -- [T?i danh] input d?ng [123,453] ho?c 123,453
            AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )

            AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id  )
            AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG             = p_loai_doi_tuong_id)

            -- [Ghi chú riêng] input d?ng 123 
            AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )


            AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)

            -- NHÓM 4: Checkbox

            -- [N??c ngoài]
            AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))

            -- [Có b?nh t?t] FIX: khôi ph?c check c? PN_SUC_KHOES
            AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))

            -- [Giam riêng]
            AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
            ))

            -- [Dân t?c thi?u s?]
            AND (
									    p_dan_toc_thieu_so IS NULL
									    OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_DAN_TOCS dt
									                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
									                  AND dt.IS_DELETED = 0
									                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
									            )
									            THEN 1
									            ELSE 0
									        END = p_dan_toc_thieu_so
									    )
									)

            -- [VTN t?i th?i ?i?m ph?m t?i]
            AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
			    CASE
			        WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
			        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
			        WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
			        ELSE 0
			    END = p_vtn_thoi_diem_pham_toi
			))

            -- [Ph?m t?i m?i]
            AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
            ))

            -- [Theo tôn giáo]
            AND (p_theo_ton_giao IS NULL OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_TON_GIAOS tg
									                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
									                  AND tg.IS_DELETED = 0
									            )
									            THEN 1
									            ELSE 0
									        END = p_theo_ton_giao ))

            -- [VTN t?i th?i ?i?m hi?n t?i]
            AND (p_vtn_hien_tai IS NULL OR (
			    CASE
			        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
			        WHEN FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
			        ELSE 0
			    END = p_vtn_hien_tai
			))

            -- [Không ph?m t?i m?i]
            AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
            ))

            -- [Có ngh? nghi?p]
            AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)

            -- [Chung thân]
            AND (p_chung_than IS NULL OR (
    CASE
        WHEN ll.THA_MA_AN_PHAT IN (
            SELECT dmtg.ID
            FROM DM_MA_THOI_GIANS dmtg
            WHERE dmtg.MTG_MA IN ('911000', '912000')
              AND dmtg.IS_DELETED = 0
        ) THEN 1
        ELSE 0
    END = p_chung_than
))

            -- [?ã b? k? lu?t]
            AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
            ))

            -- [Có ghi chú ??c bi?t] FIX: OR ? AND
            AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
            ))

            -- [T?i ph?m ANQG] FIX: guard THA_TOI_DANH không r?ng
            AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))

            -- [?ã ???c khen th??ng]
            AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
            ))

            -- [Có ti?n án]
            AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))

            -- [Có ti?n s?]
            AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))

            -- [Con theo m? vào tr?i]
            AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
            ))

            -- [Hình ph?t b? sung là ti?n]
            AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))

            -- [B?t bu?c ch?a b?nh]
            AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))

            -- [Hoàn xong HPBS là ti?n]
            AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))

            -- [Ch?a hoàn xong HPBS là ti?n]
            AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))
    ),

    chi_tiet AS (                

        SELECT
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ))) AS "TT",
            pn.BT_TEN AS "TinhTrangSucKhoe",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'Nam' THEN pn.PHAM_NHAN_ID END)                                      AS "Nam",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'N\1eef' THEN pn.PHAM_NHAN_ID END)                                   AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(gt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN pn.PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT  pn.PHAM_NHAN_ID)                                                                              AS "TongSo"
        FROM pham_nhan_filtered pn
        LEFT JOIN DM_GIOI_TINHS gt
            ON gt.ID = pn.LL_DM_GIOI_TINH_ID
           AND NVL(gt.IS_DELETED, 0) = 0
        GROUP BY  pn.BT_TEN
	    )

    SELECT
        "TT",
        "TinhTrangSucKhoe",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
	        "TinhTrangSucKhoe",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_TINH_TRANG_SUC_KHOE;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_TOI_DANH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_TOI_DANH" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
        WITH 
             selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ), 
             pham_nhan_filtered AS ( SELECT ll.PHAM_NHAN_ID,
                                           ll.LL_DM_GIOI_TINH_ID,
                                           ll.LL_DM_QUOC_TICH_ID,
                                           ll.THA_MUC_AN_ID,
                                           ll.LL_GHI_CHU_RIENG
                                	 FROM pn_base ll
	                                 LEFT JOIN DM_TRAI_GIAMS dtg
	                                           ON dtg.ID = ll.LL_TRAI_GIAM_ID
	                                               AND dtg.IS_DELETED = 0
	                                 LEFT JOIN DM_QUOC_TICHS dqt
	                                           ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
	                                               AND dqt.IS_DELETED = 0
                                    WHERE ll.IS_DELETED = 0
                                      AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)
                                      -- NHÓM 1: Kho?ng ngày
                                      AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                      AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                      AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                      AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                                      AND (
				    (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM PN_DAC_XAS dxa
				        WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
				          AND dxa.IS_DELETED = 0
				          AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
				          AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
				    )
				)
                                      AND (
                                        (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM GIAM_THOI_HANS gaan
                                                       WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                         AND gaan.IS_DELETED = 0
                                                         AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                                        )

                                      -- NHÓM 2: Kho?ng s?
                                      AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
                                      AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                                      AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                                      AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                                      AND (p_tg_chap_hanh_tu IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                                      AND (p_tg_chap_hanh_den IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                                      AND (p_tg_con_lai_tu IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                                      AND (p_tg_con_lai_den IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                                      -- NHÓM 3: Danh m?c
                                      AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
                                      AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
                                      AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
                                      AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                                      AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
                                      AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

                                      -- [T?i danh]
                                      AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
                                      AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                                      AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG = p_loai_doi_tuong_id)

                                      -- [Ghi chú riêng]
                                      AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

                                      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                                      -- NHÓM 4: Checkbox
                                      AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
                                      AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
                                      AND (p_giam_rieng IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PN_GIAM_RIENGS gr
                                                         WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                                                           AND gr.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_giam_rieng
                                        ))
                                      AND (
									    p_dan_toc_thieu_so IS NULL
									    OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_DAN_TOCS dt
									                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
									                  AND dt.IS_DELETED = 0
									                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
									            )
									            THEN 1
									            ELSE 0
									        END = p_dan_toc_thieu_so
									    )
									)
                                      AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                                        CASE
                                            WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_thoi_diem_pham_toi
                                        ))
                                      AND (p_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PHAM_TOI_MOIS ptm
                                                         WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_pham_toi_moi
                                        ))
                                      AND (p_theo_ton_giao IS NULL OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_TON_GIAOS tg
									                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
									                  AND tg.IS_DELETED = 0
									            )
									            THEN 1
									            ELSE 0
									        END = p_theo_ton_giao ))
                                      AND (p_vtn_hien_tai IS NULL OR (
                                        CASE
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_hien_tai
                                        ))
                                      AND (p_khong_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN NOT EXISTS (SELECT 1
                                                             FROM PHAM_TOI_MOIS ptm
                                                             WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                               AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_khong_pham_toi_moi
                                        ))
                                      AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
                                      AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
                                      AND (p_da_bi_ky_luat IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KY_LUATS kl
                                                         WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID) THEN 1
                                            ELSE 0 END = p_da_bi_ky_luat
                                        ))
                                      AND (p_co_ghi_chu_dac_biet IS NULL OR (
                                        CASE
                                            WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                                                AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                                                THEN 1
                                            ELSE 0 END = p_co_ghi_chu_dac_biet
                                        ))
                                      AND (p_toi_pham_anqg IS NULL OR (
                                          CASE WHEN EXISTS (
                                              SELECT 1 FROM DM_TOI_DANHS td
                                              WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                                                AND td.IS_DELETED = 0
                                                AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                                          ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                                      ))
                                      AND (p_da_duoc_khen_thuong IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KHEN_THUONGS kt
                                                         WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND kt.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_da_duoc_khen_thuong
                                        ))
                                      AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
                                      AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
                                      AND (p_con_theo_me_vao_trai IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM THAN_NHAN_CON_CAIS tncc
                                                         WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND tncc.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_con_theo_me_vao_trai
                                        ))
                                      AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
                                      AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
                                      AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
	                  AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))
	                    ),
             td_split AS (
                    SELECT /*+ MATERIALIZE */
                           ll.PHAM_NHAN_ID AS THA_PNLAI_LICH_ID,
                           TO_NUMBER(TRIM(
                               REGEXP_SUBSTR(
                                   REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                   '[^,]+', 1, 1
                               )
                           )) AS TOI_DANH_ID
                    FROM pham_nhan_filtered pnf
                    INNER JOIN pn_base ll ON ll.PHAM_NHAN_ID = pnf.PHAM_NHAN_ID
                    WHERE ll.THA_TOI_DANH IS NOT NULL
                ),
             split_toi_danh AS (
                    SELECT /*+ MATERIALIZE */
                           td.THA_PNLAI_LICH_ID,
                           td.TOI_DANH_ID,
                           TO_NCHAR(DTD.TD_CHUONG) AS TOI_DANH_CHUONG,
                           TO_NCHAR(DTD.TD_TEN)    AS TOI_DANH
                    FROM td_split td
                    LEFT JOIN DM_TOI_DANHS DTD
                        ON  DTD.ID = td.TOI_DANH_ID
                        AND DTD.TD_CHUONG IS NOT NULL
                ),
              chi_tiet_chuong_agg AS (
                SELECT std.TOI_DANH_CHUONG,
                       cr.CTD_TEN,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam' THEN pnf.PHAM_NHAN_ID END) AS "Nam",
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN pnf.PHAM_NHAN_ID END) AS "Nu",
                       COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, u'Kh\00e1c') NOT IN ('Nam', u'N\1eef')
                                           THEN pnf.PHAM_NHAN_ID END) AS "Khac",
                       COUNT(DISTINCT pnf.PHAM_NHAN_ID) AS "TongSo"
                FROM pham_nhan_filtered pnf
                INNER JOIN split_toi_danh std
                    ON std.THA_PNLAI_LICH_ID = pnf.PHAM_NHAN_ID
                INNER JOIN QLPN.DM_CHUONG_TOI_DANHS cr
                    ON cr.CTD_MA = std.TOI_DANH_CHUONG
                LEFT JOIN DM_GIOI_TINHS dgt
                    ON dgt.ID = pnf.LL_DM_GIOI_TINH_ID
                   AND dgt.IS_DELETED = 0
                WHERE (
                        p_toi_danh_ids IS NULL
                        OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                        OR EXISTS (
                            SELECT 1
                            FROM selected_toi_danh_filter loc
                            WHERE TRIM(loc.ma_loc) = TO_CHAR(std.TOI_DANH_ID)
                        )
                  )
                GROUP BY std.TOI_DANH_CHUONG, cr.CTD_TEN
            ),
            chi_tiet_chuong AS (
                SELECT TO_NUMBER(TOI_DANH_CHUONG) AS SORT_ORDER,
                       TO_NCHAR(ROW_NUMBER() OVER (ORDER BY TO_NUMBER(TOI_DANH_CHUONG))) AS "TT",
                       TO_NCHAR(u'Ch??ng ' || TOI_DANH_CHUONG || ': ' || CTD_TEN) AS "ToiDanh",
                       "Nam",
                       "Nu",
                       "Khac",
                       "TongSo"
                FROM chi_tiet_chuong_agg
            ),
            chi_tiet_toi_danh_base AS (
                SELECT std.TOI_DANH_CHUONG,
                       std.TOI_DANH,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam' THEN pnf.PHAM_NHAN_ID END) AS "Nam",
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN pnf.PHAM_NHAN_ID END) AS "Nu",
                       COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, u'Kh\00e1c') NOT IN ('Nam', u'N\1eef')
                                           THEN pnf.PHAM_NHAN_ID END) AS "Khac",
                       COUNT(DISTINCT pnf.PHAM_NHAN_ID) AS "TongSo"
                FROM pham_nhan_filtered pnf
                INNER JOIN split_toi_danh std
                    ON std.THA_PNLAI_LICH_ID = pnf.PHAM_NHAN_ID
                INNER JOIN QLPN.DM_CHUONG_TOI_DANHS cr
                    ON cr.CTD_MA = std.TOI_DANH_CHUONG
                LEFT JOIN DM_GIOI_TINHS dgt
                    ON dgt.ID = pnf.LL_DM_GIOI_TINH_ID
                   AND dgt.IS_DELETED = 0
                WHERE std.TOI_DANH IS NOT NULL
                  AND (
                        p_toi_danh_ids IS NULL
                        OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                        OR EXISTS (
                            SELECT 1
                            FROM selected_toi_danh_filter loc
                            WHERE TRIM(loc.ma_loc) = TO_CHAR(std.TOI_DANH_ID)
                        )
                  )
                GROUP BY std.TOI_DANH_CHUONG, std.TOI_DANH
            ),
            chi_tiet_toi_danh AS (
                SELECT TO_NUMBER(TOI_DANH_CHUONG)
                       + ROW_NUMBER() OVER (PARTITION BY TOI_DANH_CHUONG ORDER BY TOI_DANH) * 0.001 AS SORT_ORDER,
                       u'+' AS "TT",
                       TO_NCHAR(TOI_DANH) AS "ToiDanh",
                       "Nam",
                       "Nu",
                       "Khac",
                       "TongSo"
                FROM chi_tiet_toi_danh_base
            )
        SELECT "TT", "ToiDanh", "Nam", "Nu", "Khac", "TongSo"
        FROM (
            SELECT SORT_ORDER, "TT", "ToiDanh", "Nam", "Nu", "Khac", "TongSo"
            FROM chi_tiet_chuong
            UNION ALL
            SELECT SORT_ORDER, "TT", "ToiDanh", "Nam", "Nu", "Khac", "TongSo"
            FROM chi_tiet_toi_danh
            UNION ALL
            SELECT 999,
                   TO_NCHAR(''),
                   TO_NCHAR(u'T?ng s?'),
                   SUM("Nam"),
                   SUM("Nu"),
                   SUM("Khac"),
                   SUM("TongSo")
            FROM chi_tiet_chuong
        )
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);

END SP_GET_THONG_KE_TOI_DANH;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_TON_GIAO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_TON_GIAO" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$') THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID,
            ll.LL_DM_HOC_VAN_ID,
            ll.LL_DM_NGHE_NGHIEP_ID,
            ll.LL_SO_TIEN_AN,
            ll.LL_SO_TIEN_SU,
            ll.LL_DM_TON_GIAO_ID,
            ll.THA_THOI_GIAN_DA_CHAP_HANH,
            ll.THA_THOI_GIAN_CON_LAI
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON  dtg.ID = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
            AND dqt.IS_DELETED = 0
        WHERE
            ll.IS_DELETED = 0
            AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)

            -- NHÓM 1: Kho?ng ngày
            AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                              AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                              AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                              AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
            AND (
				    (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM PN_DAC_XAS dxa
				        WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
				          AND dxa.IS_DELETED = 0
				          AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
				          AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
				    )
				)
		AND (
				    (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM GIAM_THOI_HANS gaan
				        WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
				          AND gaan.IS_DELETED   = 0
				          AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
				          AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
				    )
				)

            -- NHÓM 2: Kho?ng s?
                AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
            AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
            AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
            AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
		    AND (p_tg_chap_hanh_tu  IS NULL OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
		AND (p_tg_chap_hanh_den IS NULL OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
            AND (p_tg_con_lai_tu  IS NULL OR
                    ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
            AND (p_tg_con_lai_den IS NULL OR
                    ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

            -- NHÓM 3: Danh m?c
            AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
            AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
            AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
            AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
            AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
            AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

            -- [T?i danh] input d?ng [123,453] ho?c 123,453
            AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )

            AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id  )
            AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

            -- [Ghi chú riêng] input d?ng 123 
            AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )


            AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)

            -- NHÓM 4: Checkbox

            -- [N??c ngoài]
            AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))

            -- [Có b?nh t?t]
            AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))

            -- [Giam riêng]
            AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
            ))

            -- [Dân t?c thi?u s?]
            AND (
									    p_dan_toc_thieu_so IS NULL
									    OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_DAN_TOCS dt
									                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
									                  AND dt.IS_DELETED = 0
									                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
									            )
									            THEN 1
									            ELSE 0
									        END = p_dan_toc_thieu_so
									    )
									)

            -- [VTN t?i th?i ?i?m ph?m t?i]
            AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
			    CASE
			        WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
			        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
			        WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
			        ELSE 0
			    END = p_vtn_thoi_diem_pham_toi
			))

            -- [Ph?m t?i m?i]
            AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
            ))

            -- [Theo tôn giáo]
            AND (p_theo_ton_giao IS NULL OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_TON_GIAOS tg
									                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
									                  AND tg.IS_DELETED = 0

									            )
									            THEN 1
									            ELSE 0
									        END = p_theo_ton_giao ))

            -- [VTN t?i th?i ?i?m hi?n t?i]
            AND (p_vtn_hien_tai IS NULL OR (
			    CASE
			        WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
			        WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
			        ELSE 0
			    END = p_vtn_hien_tai
			))

            -- [Không ph?m t?i m?i]
            AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
            ))

            -- [Có ngh? nghi?p]
            AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)

            -- [Chung thân]
            AND (p_chung_than IS NULL OR (
    CASE WHEN ll.THA_MA_AN_PHAT IN (
        SELECT dmtg.ID FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000') AND dmtg.IS_DELETED = 0
    ) THEN 1 ELSE 0 END = p_chung_than
))

            -- [?ã b? k? lu?t]
            AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
            ))

            -- [Có ghi chú ??c bi?t]
            AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
            ))

            -- [T?i ph?m ANQG]
            AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))

            -- [?ã ???c khen th??ng]
            AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
            ))

            -- [Có ti?n án]
            AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))

            -- [Có ti?n s?]
            AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))

            -- [Con theo m? vào tr?i]
            AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
            ))

            -- [Hình ph?t b? sung là ti?n]
            AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))

            -- [B?t bu?c ch?a b?nh]
            AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))

            -- [Hoàn xong HPBS là ti?n]
            AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))

            -- [Ch?a hoàn xong HPBS là ti?n]
            AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))
    ),

    chi_tiet AS (                
            SELECT
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ))) AS "TT",
            NVL(dtg.TG_TEN, u'Kh\00f4ng') AS "TonGiao",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN ll.PHAM_NHAN_ID END)                                      AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN ll.PHAM_NHAN_ID END)                                   AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN ll.PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT ll.PHAM_NHAN_ID)                                                                               AS "TongSo"
        FROM pham_nhan_filtered ll
        LEFT JOIN DM_GIOI_TINHS dgt
            ON dgt.ID = ll.LL_DM_GIOI_TINH_ID
           AND dgt.IS_DELETED = 0
        LEFT JOIN DM_TON_GIAOS dtg
            ON dtg.ID = ll.LL_DM_TON_GIAO_ID
           AND dtg.IS_DELETED = 0
        GROUP BY
          NVL(dtg.TG_TEN, u'Kh\00f4ng')
	    )

    SELECT
        "TT",
        "TonGiao",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
	        "TT",
	        "TonGiao",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_TON_GIAO;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_TRAI_CHUYEN_DEN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_TRAI_CHUYEN_DEN" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID,
            ll.THA_CHUYEN_DEN_TU_ID,
            ll.THA_NGAY_DEN_TRAI
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON  dtg.ID = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
            AND dqt.IS_DELETED = 0
        WHERE
            (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)

            AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
            AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
            AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
            AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
            AND (
                (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                OR EXISTS (
                    SELECT 1
                    FROM PN_DAC_XAS dxa
                    WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                      AND dxa.IS_DELETED = 0
                      AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                      AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
                )
            )
            AND (
                (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                OR EXISTS (
                    SELECT 1
                    FROM GIAM_THOI_HANS gaan
                    WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                      AND gaan.IS_DELETED   = 0
                      AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                      AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
                )
            )

            AND (
                p_so_tien_an_tu IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
            )
            AND (
                p_so_tien_an_den IS NULL
                OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
            )
            AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
            AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
            AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
            AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
            AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
            AND (p_tg_con_lai_tu  IS NULL OR ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
            AND (p_tg_con_lai_den IS NULL OR ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

            AND (p_gioi_tinh_id      IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
            AND (p_dan_toc_id        IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
            AND (p_quoc_tich_id      IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
            AND (p_nghe_nghiep_id    IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
            AND (p_hoc_van_id        IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
            AND (p_ton_giao_id       IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)

            AND (
                p_toi_danh_ids IS NULL
                    OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                    OR EXISTS (SELECT 1
                               FROM selected_toi_danh_filter loc
                               WHERE INSTR(
                                             ',' || REPLACE(
                                                     REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                     ' ', '') || ',',
                                             ',' || TRIM(loc.ma_loc) || ','
                                     ) > 0)
            )
            AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
            AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)

            AND (
                p_ghi_chu_rieng_id IS NULL
                    OR INSTR(
                               ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                               ',',
                               ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                       ) > 0
            )

            AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)

            AND (p_nuoc_ngoai IS NULL OR (
                CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
            ))

            AND (p_co_benh_tat IS NULL OR (
                CASE
                    WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                        THEN 1
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_BENH_TATS dbt
                        WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                    )
                        THEN 0
                    ELSE 1
                END = p_co_benh_tat
            ))

            AND (p_giam_rieng IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PN_GIAM_RIENGS gr
                    WHERE  gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_giam_rieng
            ))

            AND (
                p_dan_toc_thieu_so IS NULL
                OR (
                    CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM DM_DAN_TOCS dt
                            WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                              AND dt.IS_DELETED = 0
                              AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                        )
                        THEN 1
                        ELSE 0
                    END = p_dan_toc_thieu_so
                )
            )

            AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                CASE
                    WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_thoi_diem_pham_toi
            ))

            AND (p_pham_toi_moi IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_pham_toi_moi
            ))

            AND (p_theo_ton_giao IS NULL OR (
                CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM DM_TON_GIAOS tg
                        WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                          AND tg.IS_DELETED = 0
                    )
                    THEN 1
                    ELSE 0
                END = p_theo_ton_giao ))

            AND (p_vtn_hien_tai IS NULL OR (
                CASE
                    WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                    WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                    ELSE 0
                END = p_vtn_hien_tai
            ))

            AND (p_khong_pham_toi_moi IS NULL OR (
                CASE WHEN NOT EXISTS (
                    SELECT 1 FROM PHAM_TOI_MOIS ptm
                    WHERE  ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
            ))

            AND (
                p_co_nghe_nghiep IS NULL
                OR (
                    CASE
                        WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                             AND EXISTS (
                                    SELECT 1
                                    FROM DM_NGHE_NGHIEPS dnn
                                    WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                      AND dnn.IS_DELETED = 0
                                      AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                             )
                        THEN 1
                        ELSE 0
                    END = p_co_nghe_nghiep
                )
            )

            AND (p_chung_than IS NULL OR (
                CASE
                    WHEN ll.THA_MA_AN_PHAT IN (
                        SELECT dmtg.ID
                        FROM DM_MA_THOI_GIANS dmtg
                        WHERE dmtg.MTG_MA IN ('911000', '912000')
                          AND dmtg.IS_DELETED = 0
                    ) THEN 1
                    ELSE 0
                END = p_chung_than
            ))

            AND (p_da_bi_ky_luat IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KY_LUATS kl
                    WHERE  kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
            ))

            AND (p_co_ghi_chu_dac_biet IS NULL OR (
                CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                      AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
            ))

            AND (p_toi_pham_anqg IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM DM_TOI_DANHS td
                    WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                      AND td.IS_DELETED = 0
                      AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                ) THEN 1 ELSE 0 END = p_toi_pham_anqg
            ))

            AND (p_da_duoc_khen_thuong IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM KHEN_THUONGS kt
                    WHERE  kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
            ))

            AND (p_co_tien_an IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_an
            ))

            AND (p_co_tien_su IS NULL OR (
                CASE
                    WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                        THEN 1
                    ELSE 0 END = p_co_tien_su
            ))

            AND (p_con_theo_me_vao_trai IS NULL OR (
                CASE WHEN EXISTS (
                    SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                    WHERE  tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
                ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
            ))

            AND (p_hp_bo_sung_la_tien IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                          LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                    ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                        AND dhpbs.IS_DELETED = 0
                                 WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                   AND hpbs.IS_DELETED = 0
                                   AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                    ELSE 0 END = p_hp_bo_sung_la_tien
            ))

            AND (p_bat_buoc_chua_benh IS NULL OR (
                CASE
                    WHEN EXISTS (SELECT 1
                                 FROM CHUA_BENH_BAT_BUOCS cb
                                 WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                   	AND cb.IS_DELETED = 0
                                       ) THEN 1
                    ELSE 0 END = p_bat_buoc_chua_benh
            ))

            AND (
                p_hoan_xong_hpbs_la_tien IS NULL OR
                (CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                            LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                             AND dhpbs.IS_DELETED = 0
                            WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                              AND hpbs.IS_DELETED = 0
                              AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                            HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                        ) THEN 1
                        ELSE 0
                    END = p_hoan_xong_hpbs_la_tien))

            AND (p_chua_hoan_hpbs_la_tien IS NULL OR
                ( CASE
                        WHEN EXISTS (
                            SELECT 1
                            FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                            LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                              ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                             AND dhpbs.IS_DELETED = 0
                            WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                              AND hpbs.IS_DELETED = 0
                              AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                            HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                        ) THEN 1
                        ELSE 0
                    END = p_chua_hoan_hpbs_la_tien))
    ),

    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (
            ORDER BY COUNT(*) DESC ) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ))) AS "TT",
            cq.CQ_TEN AS "CacTraiChuyenDen",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'Nam' THEN pnf.PHAM_NHAN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'N\1eef' THEN pnf.PHAM_NHAN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN IS NULL OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN pnf.PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT pnf.PHAM_NHAN_ID) AS "TongSo"
        FROM pham_nhan_filtered pnf
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
                ON gt.ID = pnf.LL_DM_GIOI_TINH_ID
                AND gt.IS_DELETED = 0
        LEFT JOIN QLPN.DM_CO_QUANS cq
                ON cq.ID = pnf.THA_CHUYEN_DEN_TU_ID
                AND cq.IS_DELETED = 0
        WHERE (v_ngay_tinh IS NULL OR TRUNC(pnf.THA_NGAY_DEN_TRAI) < TRUNC(v_ngay_tinh) + 1)
        GROUP BY cq.CQ_TEN
    )

    SELECT
        "TT",
        "CacTraiChuyenDen",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
	        "CacTraiChuyenDen",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_TRAI_CHUYEN_DEN;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_TRICH_XUAT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_TRICH_XUAT" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114',
                              '141', '142', '143', '144', '145',
                              '146', '147', '148', '149', '150')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
           AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
           AND dqt.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)
          -- NHÓM 1: Kho?ng ngày
          AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
          AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
          AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
          AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
          AND (
              (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM PN_DAC_XAS dxa
                  WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND dxa.IS_DELETED = 0
                    AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                    AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
              )
          )
          AND (
              (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM GIAM_THOI_HANS gaan
                  WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND gaan.IS_DELETED   = 0
                    AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                    AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
              )
          )
          -- NHÓM 2: Kho?ng s?
          AND (
              p_so_tien_an_tu IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
          )
          AND (
              p_so_tien_an_den IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
          )
          AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
          AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
          AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
          AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
          AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
          AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
          AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
          AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
          -- NHÓM 3: Danh m?c
          AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
          AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
          AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
          AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
          AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
          AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
          -- [T?i danh] input d?ng [123,453] ho?c 123,453
          AND (
              p_toi_danh_ids IS NULL
              OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
              OR EXISTS (SELECT 1
                         FROM selected_toi_danh_filter loc
                         WHERE INSTR(
                                     ',' || REPLACE(
                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                             ' ', '') || ',',
                                     ',' || TRIM(loc.ma_loc) || ','
                             ) > 0)
          )
          AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
          AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)
          -- [Ghi chú riêng] input d?ng 123
          AND (
              p_ghi_chu_rieng_id IS NULL
              OR INSTR(
                         ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                         ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                     ) > 0
          )
          AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)
          -- NHÓM 4: Checkbox
          -- [N??c ngoài]
          AND (p_nuoc_ngoai IS NULL OR (
              CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
          ))
          -- [Có b?nh t?t]
          AND (p_co_benh_tat IS NULL OR (
              CASE
                  WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                      THEN 1
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_BENH_TATS dbt
                      WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                  )
                      THEN 0
                  ELSE 1
              END = p_co_benh_tat
          ))
          -- [Giam riêng]
          AND (p_giam_rieng IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PN_GIAM_RIENGS gr
                  WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND gr.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_giam_rieng
          ))
          -- [Dân t?c thi?u s?]
          AND (
              p_dan_toc_thieu_so IS NULL
              OR (
                  CASE
                      WHEN EXISTS (
                          SELECT 1
                          FROM DM_DAN_TOCS dt
                          WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                            AND dt.IS_DELETED = 0
                            AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                      )
                      THEN 1
                      ELSE 0
                  END = p_dan_toc_thieu_so
              )
          )
          -- [VTN t?i th?i ?i?m ph?m t?i]
          AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
              CASE
                  WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_thoi_diem_pham_toi
          ))
          -- [Ph?m t?i m?i]
          AND (p_pham_toi_moi IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_pham_toi_moi
          ))
          -- [Theo tôn giáo]
          AND (p_theo_ton_giao IS NULL OR (
              CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_TON_GIAOS tg
                      WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                        AND tg.IS_DELETED = 0
                  )
                  THEN 1
                  ELSE 0
              END = p_theo_ton_giao
          ))
          -- [VTN t?i th?i ?i?m hi?n t?i]
          AND (p_vtn_hien_tai IS NULL OR (
              CASE
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_hien_tai
          ))
          -- [Không ph?m t?i m?i]
          AND (p_khong_pham_toi_moi IS NULL OR (
              CASE WHEN NOT EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
          ))
          -- [Có ngh? nghi?p]
          AND (
              p_co_nghe_nghiep IS NULL
              OR (
                  CASE
                      WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                           AND EXISTS (
                               SELECT 1
                               FROM DM_NGHE_NGHIEPS dnn
                               WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                 AND dnn.IS_DELETED = 0
                                 AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                           )
                      THEN 1
                      ELSE 0
                  END = p_co_nghe_nghiep
              )
          )
          -- [Chung thân]
          AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
          -- [?ã b? k? lu?t]
          AND (p_da_bi_ky_luat IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KY_LUATS kl
                  WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
              ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
          ))
          -- [Có ghi chú ??c bi?t]
          AND (p_co_ghi_chu_dac_biet IS NULL OR (
              CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                    AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                   THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
          ))
          -- [T?i ph?m ANQG]
          AND (p_toi_pham_anqg IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM DM_TOI_DANHS td
                  WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                    AND td.IS_DELETED = 0
                    AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
              ) THEN 1 ELSE 0 END = p_toi_pham_anqg
          ))
          -- [?ã ???c khen th??ng]
          AND (p_da_duoc_khen_thuong IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KHEN_THUONGS kt
                  WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND kt.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
          ))
          -- [Có ti?n án]
          AND (p_co_tien_an IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_an
          ))
          -- [Có ti?n s?]
          AND (p_co_tien_su IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_su
          ))
          -- [Con theo m? vào tr?i]
          AND (p_con_theo_me_vao_trai IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                  WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND tncc.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
          ))
          -- [Hình ph?t b? sung là ti?n]
          AND (p_hp_bo_sung_la_tien IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                         ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                        AND dhpbs.IS_DELETED = 0
                               WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                 AND hpbs.IS_DELETED = 0
                                 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                  ELSE 0 END = p_hp_bo_sung_la_tien
          ))
          -- [B?t bu?c ch?a b?nh]
          AND (p_bat_buoc_chua_benh IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM CHUA_BENH_BAT_BUOCS cb
                               WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                 AND cb.IS_DELETED = 0
                                 -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                 -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                 ) THEN 1
                  ELSE 0 END = p_bat_buoc_chua_benh
          ))
          -- [Hoàn xong HPBS là ti?n]
          AND (
              p_hoan_xong_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                  ) THEN 1
                  ELSE 0
              END = p_hoan_xong_hpbs_la_tien)
          )
          -- [Ch?a hoàn xong HPBS là ti?n]
          AND (p_chua_hoan_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                  ) THEN 1
                  ELSE 0
              END = p_chua_hoan_hpbs_la_tien))
    ),

    chi_tiet AS (
    SELECT
        ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ) AS SORT_ORDER,
        TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ))) AS "TT",
        ld.LDTX_TEN AS "LyDoTrichXuat",
	   COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END) AS "Nam",
	   COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END) AS "Nu",
	   COUNT(CASE WHEN gt.GT_TEN IS NULL
              	  OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
       COUNT(*)                   AS "TongSo"
    FROM pham_nhan_filtered ll
    INNER JOIN TRICH_XUATS tx
    	ON tx.PHAM_NHAN_ID = ll.PHAM_NHAN_ID

    LEFT JOIN DM_LY_DO_TRICH_XUATS ld
        ON ld.ID = tx.TX_LY_DO_ID
       AND ld.IS_DELETED = 0

    LEFT JOIN DM_GIOI_TINHS gt
        ON gt.ID = ll.LL_DM_GIOI_TINH_ID
       AND gt.IS_DELETED = 0

    WHERE tx.IS_DELETED = 0
      AND (v_ngay_tinh IS NULL OR TRUNC(tx.TX_NGAY_TRICH_XUAT) < TRUNC(v_ngay_tinh) + 1)
    GROUP BY ld.LDTX_TEN
)

SELECT
    "TT",
    "LyDoTrichXuat",
    "Nam",
    "Nu",
    "Khac",
    "TongSo"
FROM (

    SELECT
        SORT_ORDER,
        "TT",
        "LyDoTrichXuat",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM chi_tiet

    UNION ALL

    SELECT
        999,
        NULL,
        u'T\1ed5ng s\1ed1',

        SUM("Nam"),
        SUM("Nu"),
        SUM("Khac"),
        SUM("TongSo")

    FROM chi_tiet

	)

	ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_TRICH_XUAT;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_TRUONG_HOP_CHET
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_TRUONG_HOP_CHET" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114', '132', '144', '153', '171')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
           AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
           AND dqt.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)
          -- NHÓM 1: Kho?ng ngày
          AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
          AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
          AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
          AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
          AND (
              (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM PN_DAC_XAS dxa
                  WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND dxa.IS_DELETED = 0
                    AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                    AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
              )
          )
          AND (
              (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM GIAM_THOI_HANS gaan
                  WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND gaan.IS_DELETED   = 0
                    AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                    AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
              )
          )
          -- NHÓM 2: Kho?ng s?
          AND (
              p_so_tien_an_tu IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
          )
          AND (
              p_so_tien_an_den IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
          )
          AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
          AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
          AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
          AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
          AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
          AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
          AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
          AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
          -- NHÓM 3: Danh m?c
          AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
          AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
          AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
          AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
          AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
          AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
          -- [T?i danh] input d?ng [123,453] ho?c 123,453
          AND (
              p_toi_danh_ids IS NULL
              OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
              OR EXISTS (SELECT 1
                         FROM selected_toi_danh_filter loc
                         WHERE INSTR(
                                     ',' || REPLACE(
                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                             ' ', '') || ',',
                                     ',' || TRIM(loc.ma_loc) || ','
                             ) > 0)
          )
          AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
          AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)
          -- [Ghi chú riêng] input d?ng 123
          AND (
              p_ghi_chu_rieng_id IS NULL
              OR INSTR(
                         ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                         ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                     ) > 0
          )
          AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)
          -- NHÓM 4: Checkbox
          -- [N??c ngoài]
          AND (p_nuoc_ngoai IS NULL OR (
              CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
          ))
          -- [Có b?nh t?t]
          AND (p_co_benh_tat IS NULL OR (
              CASE
                  WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                      THEN 1
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_BENH_TATS dbt
                      WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                  )
                      THEN 0
                  ELSE 1
              END = p_co_benh_tat
          ))
          -- [Giam riêng]
          AND (p_giam_rieng IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PN_GIAM_RIENGS gr
                  WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND gr.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_giam_rieng
          ))
          -- [Dân t?c thi?u s?]
          AND (
              p_dan_toc_thieu_so IS NULL
              OR (
                  CASE
                      WHEN EXISTS (
                          SELECT 1
                          FROM DM_DAN_TOCS dt
                          WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                            AND dt.IS_DELETED = 0
                            AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                      )
                      THEN 1
                      ELSE 0
                  END = p_dan_toc_thieu_so
              )
          )
          -- [VTN t?i th?i ?i?m ph?m t?i]
          AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
              CASE
                  WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_thoi_diem_pham_toi
          ))
          -- [Ph?m t?i m?i]
          AND (p_pham_toi_moi IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_pham_toi_moi
          ))
          -- [Theo tôn giáo]
          AND (p_theo_ton_giao IS NULL OR (
              CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_TON_GIAOS tg
                      WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                        AND tg.IS_DELETED = 0
                  )
                  THEN 1
                  ELSE 0
              END = p_theo_ton_giao
          ))
          -- [VTN t?i th?i ?i?m hi?n t?i]
          AND (p_vtn_hien_tai IS NULL OR (
              CASE
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_hien_tai
          ))
          -- [Không ph?m t?i m?i]
          AND (p_khong_pham_toi_moi IS NULL OR (
              CASE WHEN NOT EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
          ))
          -- [Có ngh? nghi?p]
          AND (
              p_co_nghe_nghiep IS NULL
              OR (
                  CASE
                      WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                           AND EXISTS (
                               SELECT 1
                               FROM DM_NGHE_NGHIEPS dnn
                               WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                 AND dnn.IS_DELETED = 0
                                 AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                           )
                      THEN 1
                      ELSE 0
                  END = p_co_nghe_nghiep
              )
          )
          -- [Chung thân]
          AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
          -- [?ã b? k? lu?t]
          AND (p_da_bi_ky_luat IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KY_LUATS kl
                  WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
              ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
          ))
          -- [Có ghi chú ??c bi?t]
          AND (p_co_ghi_chu_dac_biet IS NULL OR (
              CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                    AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                   THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
          ))
          -- [T?i ph?m ANQG]
          AND (p_toi_pham_anqg IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM DM_TOI_DANHS td
                  WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                    AND td.IS_DELETED = 0
                    AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
              ) THEN 1 ELSE 0 END = p_toi_pham_anqg
          ))
          -- [?ã ???c khen th??ng]
          AND (p_da_duoc_khen_thuong IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KHEN_THUONGS kt
                  WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND kt.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
          ))
          -- [Có ti?n án]
          AND (p_co_tien_an IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_an
          ))
          -- [Có ti?n s?]
          AND (p_co_tien_su IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_su
          ))
          -- [Con theo m? vào tr?i]
          AND (p_con_theo_me_vao_trai IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                  WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND tncc.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
          ))
          -- [Hình ph?t b? sung là ti?n]
          AND (p_hp_bo_sung_la_tien IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                         ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                        AND dhpbs.IS_DELETED = 0
                               WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                 AND hpbs.IS_DELETED = 0
                                 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                  ELSE 0 END = p_hp_bo_sung_la_tien
          ))
          -- [B?t bu?c ch?a b?nh]
          AND (p_bat_buoc_chua_benh IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM CHUA_BENH_BAT_BUOCS cb
                               WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                 AND cb.IS_DELETED = 0
                                 -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                 -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                 ) THEN 1
                  ELSE 0 END = p_bat_buoc_chua_benh
          ))
          -- [Hoàn xong HPBS là ti?n]
          AND (
              p_hoan_xong_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                  ) THEN 1
                  ELSE 0
              END = p_hoan_xong_hpbs_la_tien)
          )
          -- [Ch?a hoàn xong HPBS là ti?n]
          AND (p_chua_hoan_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                  ) THEN 1
                  ELSE 0
              END = p_chua_hoan_hpbs_la_tien))
    ),

    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ))) AS "TT",
            dthc.THC_TEN AS "TruongHopChet",
           COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END) AS "Nam",
		   COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END) AS "Nu",
		   COUNT(CASE WHEN gt.GT_TEN IS NULL
                  	  OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
           COUNT(*)                   AS "TongSo"
        FROM PN_KET_THUC_CHETS ktc
        INNER JOIN pham_nhan_filtered pnf ON pnf.PHAM_NHAN_ID = ktc.KTC_PN_LAI_LICH_ID
        LEFT JOIN DM_TRUONG_HOP_CHETS dthc ON dthc.ID = ktc.KTC_DM_TRUONG_HOP_CHET_ID AND dthc.IS_DELETED = 0
        LEFT JOIN DM_GIOI_TINHS gt ON pnf.LL_DM_GIOI_TINH_ID = gt.ID AND gt.IS_DELETED = 0
        WHERE ktc.IS_DELETED = 0
              AND (v_ngay_tinh IS NULL OR TRUNC(ktc.KTC_NGAY_CHET) < TRUNC(v_ngay_tinh) + 1)
        GROUP BY dthc.ID, dthc.THC_TEN
    )

    SELECT
        "TT",
        "TruongHopChet",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
            "TruongHopChet",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_TRUONG_HOP_CHET;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_TRUONG_HOP_CHUYEN_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_TRUONG_HOP_CHUYEN_TRAI" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114', '161', '162')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
           AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
           AND dqt.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)
          -- NHÓM 1: Kho?ng ngày
          AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
          AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
          AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
          AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
          AND (
              (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM PN_DAC_XAS dxa
                  WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND dxa.IS_DELETED = 0
                    AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                    AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
              )
          )
          AND (
              (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM GIAM_THOI_HANS gaan
                  WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND gaan.IS_DELETED   = 0
                    AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                    AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
              )
          )
          -- NHÓM 2: Kho?ng s?
          AND (
              p_so_tien_an_tu IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
          )
          AND (
              p_so_tien_an_den IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
          )
          AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
          AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
          AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
          AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
          AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
          AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
          AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
          AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
          -- NHÓM 3: Danh m?c
          AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
          AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
          AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
          AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
          AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
          AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
          -- [T?i danh] input d?ng [123,453] ho?c 123,453
          AND (
              p_toi_danh_ids IS NULL
              OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
              OR EXISTS (SELECT 1
                         FROM selected_toi_danh_filter loc
                         WHERE INSTR(
                                     ',' || REPLACE(
                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                             ' ', '') || ',',
                                     ',' || TRIM(loc.ma_loc) || ','
                             ) > 0)
          )
          AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
          AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)
          -- [Ghi chú riêng] input d?ng 123
          AND (
              p_ghi_chu_rieng_id IS NULL
              OR INSTR(
                         ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                         ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                     ) > 0
          )
          AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)
          -- NHÓM 4: Checkbox
          -- [N??c ngoài]
          AND (p_nuoc_ngoai IS NULL OR (
              CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
          ))
          -- [Có b?nh t?t]
          AND (p_co_benh_tat IS NULL OR (
              CASE
                  WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                      THEN 1
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_BENH_TATS dbt
                      WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                  )
                      THEN 0
                  ELSE 1
              END = p_co_benh_tat
          ))
          -- [Giam riêng]
          AND (p_giam_rieng IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PN_GIAM_RIENGS gr
                  WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND gr.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_giam_rieng
          ))
          -- [Dân t?c thi?u s?]
          AND (
              p_dan_toc_thieu_so IS NULL
              OR (
                  CASE
                      WHEN EXISTS (
                          SELECT 1
                          FROM DM_DAN_TOCS dt
                          WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                            AND dt.IS_DELETED = 0
                            AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                      )
                      THEN 1
                      ELSE 0
                  END = p_dan_toc_thieu_so
              )
          )
          -- [VTN t?i th?i ?i?m ph?m t?i]
          AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
              CASE
                  WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_thoi_diem_pham_toi
          ))
          -- [Ph?m t?i m?i]
          AND (p_pham_toi_moi IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_pham_toi_moi
          ))
          -- [Theo tôn giáo]
          AND (p_theo_ton_giao IS NULL OR (
              CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_TON_GIAOS tg
                      WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                        AND tg.IS_DELETED = 0
                  )
                  THEN 1
                  ELSE 0
              END = p_theo_ton_giao
          ))
          -- [VTN t?i th?i ?i?m hi?n t?i]
          AND (p_vtn_hien_tai IS NULL OR (
              CASE
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_hien_tai
          ))
          -- [Không ph?m t?i m?i]
          AND (p_khong_pham_toi_moi IS NULL OR (
              CASE WHEN NOT EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
          ))
          -- [Có ngh? nghi?p]
          AND (
              p_co_nghe_nghiep IS NULL
              OR (
                  CASE
                      WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                           AND EXISTS (
                               SELECT 1
                               FROM DM_NGHE_NGHIEPS dnn
                               WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                 AND dnn.IS_DELETED = 0
                                 AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                           )
                      THEN 1
                      ELSE 0
                  END = p_co_nghe_nghiep
              )
          )
          -- [Chung thân]
          AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
          -- [?ã b? k? lu?t]
          AND (p_da_bi_ky_luat IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KY_LUATS kl
                  WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
              ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
          ))
          -- [Có ghi chú ??c bi?t]
          AND (p_co_ghi_chu_dac_biet IS NULL OR (
              CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                    AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                   THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
          ))
          -- [T?i ph?m ANQG]
          AND (p_toi_pham_anqg IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM DM_TOI_DANHS td
                  WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                    AND td.IS_DELETED = 0
                    AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
              ) THEN 1 ELSE 0 END = p_toi_pham_anqg
          ))
          -- [?ã ???c khen th??ng]
          AND (p_da_duoc_khen_thuong IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KHEN_THUONGS kt
                  WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND kt.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
          ))
          -- [Có ti?n án]
          AND (p_co_tien_an IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_an
          ))
          -- [Có ti?n s?]
          AND (p_co_tien_su IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_su
          ))
          -- [Con theo m? vào tr?i]
          AND (p_con_theo_me_vao_trai IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                  WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND tncc.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
          ))
          -- [Hình ph?t b? sung là ti?n]
          AND (p_hp_bo_sung_la_tien IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                         ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                        AND dhpbs.IS_DELETED = 0
                               WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                 AND hpbs.IS_DELETED = 0
                                 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                  ELSE 0 END = p_hp_bo_sung_la_tien
          ))
          -- [B?t bu?c ch?a b?nh]
          AND (p_bat_buoc_chua_benh IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM CHUA_BENH_BAT_BUOCS cb
                               WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                 AND cb.IS_DELETED = 0
                                 -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                 -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                 ) THEN 1
                  ELSE 0 END = p_bat_buoc_chua_benh
          ))
          -- [Hoàn xong HPBS là ti?n]
          AND (
              p_hoan_xong_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                  ) THEN 1
                  ELSE 0
              END = p_hoan_xong_hpbs_la_tien)
          )
          -- [Ch?a hoàn xong HPBS là ti?n]
          AND (p_chua_hoan_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                  ) THEN 1
                  ELSE 0
              END = p_chua_hoan_hpbs_la_tien))
    ),

   chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ))) AS "TT",
            dthct.THCT_TEN AS "TruongHopChuyenTrai",
           COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END) AS "Nam",
		   COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END) AS "Nu",
		   COUNT(CASE WHEN gt.GT_TEN IS NULL
                  	  OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
           COUNT(*)                   AS "TongSo"
        FROM PHAM_NHAN_CHUYEN_TRAI pnct
        INNER JOIN pham_nhan_filtered pnf ON  pnf.pham_nhan_id =  pnct.PNCT_LAI_LICH_ID
        LEFT JOIN DM_GIOI_TINHS gt ON pnf.LL_DM_GIOI_TINH_ID = gt.ID AND gt.IS_DELETED = 0
        LEFT JOIN DM_TRUONG_HOP_CHUYEN_TRAIS dthct ON pnct.PNCT_TRUONG_HOP_CHUYEN_ID = dthct.ID
        WHERE pnct.IS_DELETED = 0
              AND (v_ngay_tinh IS NULL OR TRUNC(pnct.PNCT_NGAY_CHUYEN) < TRUNC(v_ngay_tinh) + 1)
        GROUP BY dthct.ID, dthct.THCT_TEN
    )

    SELECT
        "TT",
        "TruongHopChuyenTrai",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
             "TT",
	        "TruongHopChuyenTrai",
	        "Nam",
	        "Nu",
	        "Khac",
	        "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_TRUONG_HOP_CHUYEN_TRAI;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_TRUONG_HOP_MIEN_HINH_PHAT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_TRUONG_HOP_MIEN_HINH_PHAT" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114', '124', '159')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
           AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
           AND dqt.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)
          -- NHÓM 1: Kho?ng ngày
          AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
          AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
          AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
          AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
          AND (
              (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM PN_DAC_XAS dxa
                  WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND dxa.IS_DELETED = 0
                    AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                    AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
              )
          )
          AND (
              (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM GIAM_THOI_HANS gaan
                  WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND gaan.IS_DELETED   = 0
                    AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                    AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
              )
          )
          -- NHÓM 2: Kho?ng s?
          AND (
              p_so_tien_an_tu IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
          )
          AND (
              p_so_tien_an_den IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
          )
          AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
          AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
          AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
          AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
          AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
          AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
          AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
          AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
          -- NHÓM 3: Danh m?c
          AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
          AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
          AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
          AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
          AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
          AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
          -- [T?i danh] input d?ng [123,453] ho?c 123,453
          AND (
              p_toi_danh_ids IS NULL
              OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
              OR EXISTS (SELECT 1
                         FROM selected_toi_danh_filter loc
                         WHERE INSTR(
                                     ',' || REPLACE(
                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                             ' ', '') || ',',
                                     ',' || TRIM(loc.ma_loc) || ','
                             ) > 0)
          )
          AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
          AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)
          -- [Ghi chú riêng] input d?ng 123
          AND (
              p_ghi_chu_rieng_id IS NULL
              OR INSTR(
                         ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                         ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                     ) > 0
          )
          AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)
          -- NHÓM 4: Checkbox
          -- [N??c ngoài]
          AND (p_nuoc_ngoai IS NULL OR (
              CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
          ))
          -- [Có b?nh t?t]
          AND (p_co_benh_tat IS NULL OR (
              CASE
                  WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                      THEN 1
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_BENH_TATS dbt
                      WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                  )
                      THEN 0
                  ELSE 1
              END = p_co_benh_tat
          ))
          -- [Giam riêng]
          AND (p_giam_rieng IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PN_GIAM_RIENGS gr
                  WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND gr.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_giam_rieng
          ))
          -- [Dân t?c thi?u s?]
          AND (
              p_dan_toc_thieu_so IS NULL
              OR (
                  CASE
                      WHEN EXISTS (
                          SELECT 1
                          FROM DM_DAN_TOCS dt
                          WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                            AND dt.IS_DELETED = 0
                            AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                      )
                      THEN 1
                      ELSE 0
                  END = p_dan_toc_thieu_so
              )
          )
          -- [VTN t?i th?i ?i?m ph?m t?i]
          AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
              CASE
                  WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_thoi_diem_pham_toi
          ))
          -- [Ph?m t?i m?i]
          AND (p_pham_toi_moi IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_pham_toi_moi
          ))
          -- [Theo tôn giáo]
          AND (p_theo_ton_giao IS NULL OR (
              CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_TON_GIAOS tg
                      WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                        AND tg.IS_DELETED = 0
                  )
                  THEN 1
                  ELSE 0
              END = p_theo_ton_giao
          ))
          -- [VTN t?i th?i ?i?m hi?n t?i]
          AND (p_vtn_hien_tai IS NULL OR (
              CASE
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_hien_tai
          ))
          -- [Không ph?m t?i m?i]
          AND (p_khong_pham_toi_moi IS NULL OR (
              CASE WHEN NOT EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
          ))
          -- [Có ngh? nghi?p]
          AND (
              p_co_nghe_nghiep IS NULL
              OR (
                  CASE
                      WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                           AND EXISTS (
                               SELECT 1
                               FROM DM_NGHE_NGHIEPS dnn
                               WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                 AND dnn.IS_DELETED = 0
                                 AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                           )
                      THEN 1
                      ELSE 0
                  END = p_co_nghe_nghiep
              )
          )
          -- [Chung thân]
          AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
          -- [?ã b? k? lu?t]
          AND (p_da_bi_ky_luat IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KY_LUATS kl
                  WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
              ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
          ))
          -- [Có ghi chú ??c bi?t]
          AND (p_co_ghi_chu_dac_biet IS NULL OR (
              CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                    AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                   THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
          ))
          -- [T?i ph?m ANQG]
          AND (p_toi_pham_anqg IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM DM_TOI_DANHS td
                  WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                    AND td.IS_DELETED = 0
                    AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
              ) THEN 1 ELSE 0 END = p_toi_pham_anqg
          ))
          -- [?ã ???c khen th??ng]
          AND (p_da_duoc_khen_thuong IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KHEN_THUONGS kt
                  WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND kt.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
          ))
          -- [Có ti?n án]
          AND (p_co_tien_an IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_an
          ))
          -- [Có ti?n s?]
          AND (p_co_tien_su IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_su
          ))
          -- [Con theo m? vào tr?i]
          AND (p_con_theo_me_vao_trai IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                  WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND tncc.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
          ))
          -- [Hình ph?t b? sung là ti?n]
          AND (p_hp_bo_sung_la_tien IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                         ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                        AND dhpbs.IS_DELETED = 0
                               WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                 AND hpbs.IS_DELETED = 0
                                 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                  ELSE 0 END = p_hp_bo_sung_la_tien
          ))
          -- [B?t bu?c ch?a b?nh]
          AND (p_bat_buoc_chua_benh IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM CHUA_BENH_BAT_BUOCS cb
                               WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                 AND cb.IS_DELETED = 0
                                 -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                 -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                 ) THEN 1
                  ELSE 0 END = p_bat_buoc_chua_benh
          ))
          -- [Hoàn xong HPBS là ti?n]
          AND (
              p_hoan_xong_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                  ) THEN 1
                  ELSE 0
              END = p_hoan_xong_hpbs_la_tien)
          )
          -- [Ch?a hoàn xong HPBS là ti?n]
          AND (p_chua_hoan_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                  ) THEN 1
                  ELSE 0
              END = p_chua_hoan_hpbs_la_tien))
    ),

    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ))) AS "TT",
            dmhp.MHP_TEN AS "LyDoMienHinhPhat",
           COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END) AS "Nam",
		   COUNT(CASE WHEN gt.GT_TEN = u'N?' THEN 1 END) AS "Nu",
		   COUNT(CASE WHEN gt.GT_TEN IS NULL
                  	  OR gt.GT_TEN NOT IN (u'Nam', u'N?') THEN 1 END) AS "Khac",
           COUNT(*)                   AS "TongSo"
        FROM MIEN_HINH_PHATS mhp
        INNER JOIN pham_nhan_filtered pnf ON pnf.PHAM_NHAN_ID = mhp.PN_LAI_LICH_ID
        LEFT JOIN DM_TRUONG_HOP_MIEN_HINH_PHATS dmhp ON dmhp.ID = mhp.MHP_TRUONG_HOP_MIEN AND dmhp.IS_DELETED = 0
        LEFT JOIN DM_GIOI_TINHS gt ON pnf.LL_DM_GIOI_TINH_ID = gt.ID AND gt.IS_DELETED = 0
        WHERE mhp.IS_DELETED = 0
              AND (v_ngay_tinh IS NULL OR TRUNC(mhp.MHP_NGAY_QUYET_DINH) < TRUNC(v_ngay_tinh) + 1)
        GROUP BY mhp.MHP_TRUONG_HOP_MIEN, dmhp.MHP_TEN
    )

    SELECT
        "TT",
        "LyDoMienHinhPhat",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
            "LyDoMienHinhPhat",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_TRUONG_HOP_MIEN_HINH_PHAT;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_KE_TRUONG_HOP_TRON
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_KE_TRUONG_HOP_TRON" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114', '131', '132', '133')
        WHERE ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
           AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
           AND dqt.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)
          -- NHÓM 1: Kho?ng ngày
          AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
          AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
          AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
          AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
          AND (
              (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM PN_DAC_XAS dxa
                  WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND dxa.IS_DELETED = 0
                    AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                    AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
              )
          )
          AND (
              (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1
                  FROM GIAM_THOI_HANS gaan
                  WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND gaan.IS_DELETED   = 0
                    AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                    AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
              )
          )
          -- NHÓM 2: Kho?ng s?
          AND (
              p_so_tien_an_tu IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
          )
          AND (
              p_so_tien_an_den IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
          )
          AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
          AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
          AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
          AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
          AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
          AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
          AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
          AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
          -- NHÓM 3: Danh m?c
          AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
          AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
          AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
          AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
          AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
          AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
          -- [T?i danh] input d?ng [123,453] ho?c 123,453
          AND (
              p_toi_danh_ids IS NULL
              OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
              OR EXISTS (SELECT 1
                         FROM selected_toi_danh_filter loc
                         WHERE INSTR(
                                     ',' || REPLACE(
                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                             ' ', '') || ',',
                                     ',' || TRIM(loc.ma_loc) || ','
                             ) > 0)
          )
          AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
          AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)
          -- [Ghi chú riêng] input d?ng 123
          AND (
              p_ghi_chu_rieng_id IS NULL
              OR INSTR(
                         ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                         ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                     ) > 0
          )
          AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)
          -- NHÓM 4: Checkbox
          -- [N??c ngoài]
          AND (p_nuoc_ngoai IS NULL OR (
              CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
          ))
          -- [Có b?nh t?t]
          AND (p_co_benh_tat IS NULL OR (
              CASE
                  WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                      THEN 1
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_BENH_TATS dbt
                      WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0
                        AND dbt.BT_MA = '1'
                  )
                      THEN 0
                  ELSE 1
              END = p_co_benh_tat
          ))
          -- [Giam riêng]
          AND (p_giam_rieng IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PN_GIAM_RIENGS gr
                  WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND gr.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_giam_rieng
          ))
          -- [Dân t?c thi?u s?]
          AND (
              p_dan_toc_thieu_so IS NULL
              OR (
                  CASE
                      WHEN EXISTS (
                          SELECT 1
                          FROM DM_DAN_TOCS dt
                          WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                            AND dt.IS_DELETED = 0
                            AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                      )
                      THEN 1
                      ELSE 0
                  END = p_dan_toc_thieu_so
              )
          )
          -- [VTN t?i th?i ?i?m ph?m t?i]
          AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
              CASE
                  WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_thoi_diem_pham_toi
          ))
          -- [Ph?m t?i m?i]
          AND (p_pham_toi_moi IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_pham_toi_moi
          ))
          -- [Theo tôn giáo]
          AND (p_theo_ton_giao IS NULL OR (
              CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM DM_TON_GIAOS tg
                      WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
                        AND tg.IS_DELETED = 0
                  )
                  THEN 1
                  ELSE 0
              END = p_theo_ton_giao
          ))
          -- [VTN t?i th?i ?i?m hi?n t?i]
          AND (p_vtn_hien_tai IS NULL OR (
              CASE
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_hien_tai
          ))
          -- [Không ph?m t?i m?i]
          AND (p_khong_pham_toi_moi IS NULL OR (
              CASE WHEN NOT EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
          ))
          -- [Có ngh? nghi?p]
          AND (
              p_co_nghe_nghiep IS NULL
              OR (
                  CASE
                      WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                           AND EXISTS (
                               SELECT 1
                               FROM DM_NGHE_NGHIEPS dnn
                               WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                 AND dnn.IS_DELETED = 0
                                 AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                           )
                      THEN 1
                      ELSE 0
                  END = p_co_nghe_nghiep
              )
          )
          -- [Chung thân]
          AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
          -- [?ã b? k? lu?t]
          AND (p_da_bi_ky_luat IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KY_LUATS kl
                  WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
              ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
          ))
          -- [Có ghi chú ??c bi?t]
          AND (p_co_ghi_chu_dac_biet IS NULL OR (
              CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                    AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                   THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
          ))
          -- [T?i ph?m ANQG]
          AND (p_toi_pham_anqg IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM DM_TOI_DANHS td
                  WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                    AND td.IS_DELETED = 0
                    AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
              ) THEN 1 ELSE 0 END = p_toi_pham_anqg
          ))
          -- [?ã ???c khen th??ng]
          AND (p_da_duoc_khen_thuong IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KHEN_THUONGS kt
                  WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND kt.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
          ))
          -- [Có ti?n án]
          AND (p_co_tien_an IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_an
          ))
          -- [Có ti?n s?]
          AND (p_co_tien_su IS NULL OR (
              CASE
                  WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                      THEN 1
                  ELSE 0 END = p_co_tien_su
          ))
          -- [Con theo m? vào tr?i]
          AND (p_con_theo_me_vao_trai IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                  WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND tncc.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
          ))
          -- [Hình ph?t b? sung là ti?n]
          AND (p_hp_bo_sung_la_tien IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                               LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                         ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                        AND dhpbs.IS_DELETED = 0
                               WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                 AND hpbs.IS_DELETED = 0
                                 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                  ELSE 0 END = p_hp_bo_sung_la_tien
          ))
          -- [B?t bu?c ch?a b?nh]
          AND (p_bat_buoc_chua_benh IS NULL OR (
              CASE
                  WHEN EXISTS (SELECT 1
                               FROM CHUA_BENH_BAT_BUOCS cb
                               WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                 AND cb.IS_DELETED = 0
                                 -- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                 -- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                 ) THEN 1
                  ELSE 0 END = p_bat_buoc_chua_benh
          ))
          -- [Hoàn xong HPBS là ti?n]
          AND (
              p_hoan_xong_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                  ) THEN 1
                  ELSE 0
              END = p_hoan_xong_hpbs_la_tien)
          )
          -- [Ch?a hoàn xong HPBS là ti?n]
          AND (p_chua_hoan_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1
                      FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                       AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0
                        AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                  ) THEN 1
                  ELSE 0
              END = p_chua_hoan_hpbs_la_tien))
    ),

    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC ))) AS "TT",
            dthtt.THT_TEN AS "TruongHopTron",
           COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END) AS "Nam",
		   COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END) AS "Nu",
		   COUNT(CASE WHEN gt.GT_TEN IS NULL
                  	  OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
           COUNT(*)                   AS "TongSo"
        FROM TRON_TRAIS tron
        INNER JOIN pham_nhan_filtered pnf ON pnf.PHAM_NHAN_ID = tron.PHAM_NHAN_ID
        LEFT JOIN DM_GIOI_TINHS gt ON pnf.LL_DM_GIOI_TINH_ID = gt.ID AND gt.IS_DELETED = 0
        LEFT JOIN DM_TRUONG_HOP_TRONS dthtt ON tron.TRUONG_HOP_TRON_ID = dthtt.ID
        WHERE tron.IS_DELETED = 0
              AND (v_ngay_tinh IS NULL OR TRUNC(tron.NGAY_TRON) < TRUNC(v_ngay_tinh) + 1)
        GROUP BY dthtt.ID, dthtt.THT_TEN
    )

    SELECT
        "TT",
        "TruongHopTron",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            SORT_ORDER,
            "TT",
            "TruongHopTron",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ed5ng s\1ed1'),
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_TRUONG_HOP_TRON;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_TIN_
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_TIN_" SP_GET_THONG_TIN_PHAM_NHAN_QDTHAPT (
    p_pn_ids IN VARCHAR2 DEFAULT NULL  -- Danh sách ID phân cách b?i d?u ph?y, VD: '1,2,3,4'
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        WITH PN_ID_LIST AS (
            -- Tách chu?i ID thành các dòng riêng bi?t
            SELECT TO_NUMBER(
                REGEXP_SUBSTR(p_pn_ids, '[^,]+', 1, LEVEL)
            ) AS PN_ID
            FROM DUAL
            WHERE p_pn_ids IS NOT NULL
            CONNECT BY LEVEL <= REGEXP_COUNT(p_pn_ids, ',') + 1
        )
        SELECT
            ptha.THA_KHOAN AS "Khoan", -- không bi?t có dùng không
        	ptha.THA_DIEU AS "Dieu",-- không bi?t có dùng không
			ptha.THA_CAN_CU_TUYEN_PHAT AS "CanCuTuyenPhat", -- không bi?t có dùng không
			ptha.THA_SO_QD_DIEU_CHUYEN AS "SoQDDieuChuyen", -- so_qd_dc
			ptha.THA_NGAY_QD_DIEU_CHUYEN AS "NgayQDDieuChuyen", -- ngay_qd_dc
			dcq.CQ_TEN AS "DonViDeNghi", --«dv_dn_dc»
            vpllct.HO_TEN AS "HoTen",
            vpllct.GIOI_TINH AS "GioiTinh",
            vpllct.NAM_SINH AS "NamSinh",
            vpllct.TEN_KHAC AS "TenKhac",
            vpllct.DIA_CHI_THUONG_TRU AS "DiaChiThuongTru",
            vpllct.TOI_DANH AS "ToiDanh",
            vpllct.NGAY_BAT_AN_PHAT AS "NgayBatAnPhat",
            vpllct.AN_PHAT AS "AnPhat",
            vpllct.SO_BAN_AN AS "SoBanAn", -- so_ba
            vpllct.NGAY_BAN_AN AS "NgayBanAn", -- ngay_xu
            vpllct.TOA_XU_TEN AS "ToaXuTen", -- toa_xu
            ptha.THA_SO_QD_THA AS "SoQDTha" -- so_qd_tha
            ptha.THA_NGAY_QD_THA AS "NgayQDTha" -- ngay_qd_tha
            vpllct.TRAI_GIAM AS "TraiGiam", --tam_giam
            dtg.TG_DIA_CHI AS "DiaChiTG"
        FROM VW_PN_LAI_LICH_CHI_TIET vpllct
        LEFT JOIN PN_LAI_LICHS ll 
        	ON vpllct.PHAM_NHAN_ID = ll.ID
       	LEFT JOIN PN_THI_HANH_AN ptha
       		ON ll.ID = ptha.ID
       	LEFT JOIN DM_CO_QUANS dcq
       		ON ptha.THA_DON_VI_DE_NGHI_ID = dcq.ID
        LEFT JOIN DM_TRAI_GIAMS dtg 
            ON vpllct.TRAI_GIAM_ID = dtg.ID
        WHERE p_pn_ids IS NULL 
           OR vpllct.PHAM_NHAN_ID IN (SELECT PN_ID FROM PN_ID_LIST);

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_THONG_TIN_PHAM_NHAN_QDTHAPT;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_TIN_CHET
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_TIN_CHET" (
    p_LAI_LICH_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        pktc.KTC_PN_LAI_LICH_ID,
        pktc.KTC_NGAY_CHET  AS "NgayChet",
        dthc.THC_TEN  AS "TruongHopChet",
        pktc.KTC_NGUYEN_NHAN_CHET_CHI_TIET  AS "NguyenNhanChet",
        pktc.KTC_NOI_CHET  AS "NoiChet"
    FROM PN_KET_THUC_CHETS pktc 
    LEFT JOIN DM_TRUONG_HOP_CHETS dthc ON pktc.KTC_DM_TRUONG_HOP_CHET_ID = dthc.ID
    WHERE pktc.KTC_PN_LAI_LICH_ID = p_LAI_LICH_ID;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_THONG_TIN_CHET;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_TIN_HINH_PHAT_BO_SUNG_KHAC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_TIN_HINH_PHAT_BO_SUNG_KHAC" (
    p_pham_nhan_id IN NUMBER
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        SELECT
            CAST(NVL(dm.HPBS_TEN, u'') AS NVARCHAR2(2000)) AS HINH_PHAT,
            CAST(NVL(dmtg.MTG_TITLE, u'') AS NVARCHAR2(500)) AS THOI_HAN,
            CAST(NVL(gch.GCHPBS_TEN, u'') AS NVARCHAR2(2000)) AS GHI_CHU
        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
        INNER JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
            ON dm.ID = hp.HPBS_HINH_PHAT
           AND NVL(dm.IS_DELETED, 0) = 0
           AND dm.HPBS_MA IN ('110', '120', '130', '140', '150', '160', '170', '310')
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg
            ON NVL(dmtg.IS_DELETED, 0) = 0
           AND dmtg.ID = hp.HPBS_THOI_HAN
        LEFT JOIN QLPN.DM_GHI_CHU_HINH_PHAT_BO_SUNGS gch
            ON gch.ID = hp.HPBS_GHI_CHU
           AND NVL(gch.IS_DELETED, 0) = 0
        WHERE NVL(hp.IS_DELETED, 0) = 0
          AND p_pham_nhan_id IS NOT NULL
          AND hp.HPBS_MA_PHAM_NHAN = p_pham_nhan_id
        ORDER BY dm.HPBS_MA;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i SP_GET_THONG_TIN_HINH_PHAT_BO_SUNG_KHAC: ' || SQLERRM
        );
END SP_GET_THONG_TIN_HINH_PHAT_BO_SUNG_KHAC;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_TIN_HINH_PHAT_BO_SUNG_TIEN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_TIN_HINH_PHAT_BO_SUNG_TIEN" (
    p_pham_nhan_id IN NUMBER
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
		SELECT
		    CAST(NVL(dm.HPBS_TEN, u'') AS NVARCHAR2(2000)) AS HINH_PHAT,
		    CAST(NVL(dmtg.MTG_TITLE, u'') AS NVARCHAR2(500)) AS THOI_HAN,
		    TO_CHAR(NVL(hp.HPBS_TONG_TIEN_PHAT, 0), 'FM999,999,999,999,999') AS TONG_TIEN,
		    TO_CHAR(
		        GREATEST(
		            0,
		            NVL(hp.HPBS_TONG_TIEN_PHAT, 0) - NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0)
		        ), 'FM999,999,999,999,999'
		    ) AS DA_HOAN,
		    TO_CHAR(NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0), 'FM999,999,999,999,999') AS CHUA_HOAN,
		    CAST(NVL(gch.GCHPBS_TEN, u'') AS NVARCHAR2(2000)) AS GHI_CHU
        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
        INNER JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
            ON dm.ID = hp.HPBS_HINH_PHAT
           AND NVL(dm.IS_DELETED, 0) = 0
           AND dm.HPBS_MA IN ('210', '211', '220')
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg
            ON NVL(dmtg.IS_DELETED, 0) = 0
           AND dmtg.ID = hp.HPBS_THOI_HAN
        LEFT JOIN QLPN.DM_GHI_CHU_HINH_PHAT_BO_SUNGS gch
            ON gch.ID = hp.HPBS_GHI_CHU
           AND NVL(gch.IS_DELETED, 0) = 0
        WHERE NVL(hp.IS_DELETED, 0) = 0
          AND p_pham_nhan_id IS NOT NULL
          AND hp.HPBS_MA_PHAM_NHAN = p_pham_nhan_id
        ORDER BY dm.HPBS_MA;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i SP_GET_THONG_TIN_HINH_PHAT_BO_SUNG_TIEN: ' || SQLERRM
        );
END SP_GET_THONG_TIN_HINH_PHAT_BO_SUNG_TIEN;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_TIN_LAI_LICH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_TIN_LAI_LICH" (
    p_pll_id IN NUMBER
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    -- ?? 1. THA m?i nh?t c?a ph?m nhân ????????????????????????????????
    LATEST_THA AS (
        SELECT
            THA_PNLAI_LICH_ID,
            THA_NGAY_BAT,
            THA_AN_PHAT,
            THA_SO_BAN_AN,
            THA_CAP_TOA_ID,
            TO_CHAR(THA_NGAY_BAN_AN,         'DD/MM/YYYY') AS THA_NGAY_BAN_AN,
            d2.TTP_TEN                                      AS DIA_PHUONG_TOA,
            THA_SO_QD_THA,
            TO_CHAR(THA_NGAY_QD_THA,         'DD/MM/YYYY') AS THA_NGAY_QD_THA,
            THA_TOA_QD_ID,
            d.TTP_TEN                                       AS DIA_PHUONG_THA,
            THA_SO_QD_DIEU_CHUYEN,
            TO_CHAR(THA_NGAY_QD_DIEU_CHUYEN, 'DD/MM/YYYY') AS THA_NGAY_QD_DIEU_CHUYEN,
            THA_DON_VI_DE_NGHI_ID,
            THA_CHUYEN_DEN_TU_ID,
            THA_THOI_GIAN_TAM_GIAM,
            THA_THOI_GIAN_TAM_GIU,
            THA_NGAY_DEN_TRAI,
            THA_NGAY_HET_HAN,
            ROW_NUMBER() OVER (
                PARTITION BY THA_PNLAI_LICH_ID
                ORDER BY NVL(THA_NGAY_BAN_AN, TO_DATE('01-JAN-1900','DD-MON-YYYY')) DESC,
                         PN_THI_HANH_AN.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN
        LEFT JOIN DM_TINH_THANH_PHO d  ON PN_THI_HANH_AN.THA_DIA_PHUONG_TOA_QD_THA_ID = d.ID
        LEFT JOIN DM_TINH_THANH_PHO d2 ON PN_THI_HANH_AN.THA_DIA_PHUONG_CAP_TOA_ID    = d2.ID
        WHERE THA_PNLAI_LICH_ID = p_pll_id
    ),

    -- ?? 2. T?ng ngày tr?n (?ã b?t l?i) ??????????????????????????????
    TONG_TRON AS (
        SELECT tt.PHAM_NHAN_ID,
               SUM(FLOOR(CAST(tt.NGAY_BAT_LAI AS DATE) - CAST(tt.NGAY_TRON AS DATE)) + 1) AS TONG_NGAY_TRON
        FROM TRON_TRAIS tt
        WHERE tt.PHAM_NHAN_ID = p_pll_id
          AND NVL(tt.IS_DELETED, 0) = 0
          AND tt.NGAY_TRON    IS NOT NULL
          AND tt.NGAY_BAT_LAI IS NOT NULL
        GROUP BY tt.PHAM_NHAN_ID
    ),

    -- ?? 3. T?ng ngày t?m ?ình ch? (?ã có ngày l?i) ???????????????????
    TONG_TDC AS (
        SELECT tdc.PHAM_NHAN_ID,
               SUM(FLOOR(CAST(tdc.NGAY_LAI AS DATE) - CAST(tdc.TU_NGAY AS DATE)) + 1) AS TONG_NGAY_TDC
        FROM TAM_DINH_CHIS tdc
        WHERE tdc.PHAM_NHAN_ID = p_pll_id
          AND NVL(tdc.IS_DELETED, 0) = 0
          AND tdc.TU_NGAY  IS NOT NULL
          AND tdc.NGAY_LAI IS NOT NULL
        GROUP BY tdc.PHAM_NHAN_ID
    )

    SELECT
        rt.LL_SO_HO_SO_LAN_DAU                                      AS SoHSLD,
        dttpn.TTPN_TEN                                               AS TinhTrang,
        rt.LL_HO_TEN                                                 AS HoTen,
        dgt.GT_TEN                                                   AS GioiTinh,
        rt.LL_NGAY_SINH                                              AS NamSinh,
        rt.LL_TEN_KHAC                                               AS HoTenKhac,
        rt.LL_NGUYEN_QUAN                                            AS NguyenQuan,
        CASE
            WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), U'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), U'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U''), U'')
                || CASE
                       WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), U'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                THEN U', ' || dxp_thuong_tru.XP_TEN
                                ELSE dxp_thuong_tru.XP_TEN END
                       ELSE U'' END
                || CASE
                       WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), U'') IS NOT NULL THEN
                           CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), U'') IS NOT NULL
                                  OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), U'') IS NOT NULL
                                THEN U', ' || dttp_thuong_tru.TTP_TEN
                                ELSE dttp_thuong_tru.TTP_TEN END
                       ELSE U'' END
            )
            ELSE NULL
        END                                                          AS DiaChiThuongTru,
        ddt.DT_TEN                                                   AS DanToc,
        dqt.QT_TEN                                                   AS QuocTich,
        dtg2.TG_TEN                                                  AS TonGiao,
        CASE WHEN dnn.NN_TEN IS NULL THEN U'Không' ELSE dnn.NN_TEN  END AS NgheNghiep,
        CASE WHEN dhv.HV_TEN IS NULL THEN U'Không' ELSE dhv.HV_TEN  END AS TrinhDoHocVan,
        dskpn.TTSKPN_TEN                                             AS TinhTrangSucKhoeKhiVao,
        dbt.BT_TEN                                                   AS TinhTrangSucKhoeHienTai,
        gcr_agg.GHI_CHU_RIENG                                        AS GhiChuRieng,
        CASE WHEN NVL(con_count.SO_CON, 0) = 0 THEN U'Không'
             ELSE TO_NCHAR(NVL(con_count.SO_CON, 0)) END             AS SoCon,
        CASE WHEN rt.LL_SO_TIEN_AN IS NULL THEN U'Không'
             ELSE rt.LL_SO_TIEN_AN END                               AS SoTienAn,
        CASE WHEN rt.LL_SO_TIEN_SU IS NULL THEN U'Không'
             ELSE rt.LL_SO_TIEN_SU END                               AS SoTienSu,
        rt.LL_NHAN_THAN                                              AS NhanThan,
        TRIM(rt.THA_TOI_DANH_NAMES)                                  AS ToiDanh,
        TO_CHAR(TRUNC(ptha.THA_NGAY_BAT),      'DD/MM/YYYY')         AS NgayBat,
        ptha.THA_AN_PHAT                                             AS AnPhat,
        ptha.THA_SO_BAN_AN                                           AS BanAnSo,
        ptha.THA_NGAY_BAN_AN                                         AS NgayBanAn,
        dcq.CQ_TEN  || U', ' || ptha.DIA_PHUONG_TOA                  AS ToaQuyetDinh,
        ptha.THA_SO_QD_THA                                           AS SoQuyetDinh,
        ptha.THA_NGAY_QD_THA                                         AS NgayQuyetDinhTHA,
        dcq5.CQ_TEN || U', ' || ptha.DIA_PHUONG_THA                  AS DiaPhuongTha,
        ptha.THA_SO_QD_DIEU_CHUYEN                                   AS SoQuyetDinhDieuChuyen,
        ptha.THA_NGAY_QD_DIEU_CHUYEN                                 AS NgayQuyetDinhDieuChuyen,
        dcq2.CQ_TEN                                                  AS ToaQuyetDinhDieuChuyen,
        dcq1.CQ_TEN                                                  AS ChuyenDenTu,
        CASE WHEN ptha.THA_THOI_GIAN_TAM_GIAM IS NULL THEN U'Không'
             ELSE ptha.THA_THOI_GIAN_TAM_GIAM END                    AS ThoiGianTamGiam,
        CASE WHEN ptha.THA_THOI_GIAN_TAM_GIU  IS NULL THEN U'Không'
             ELSE ptha.THA_THOI_GIAN_TAM_GIU  END                    AS ThoiGianTamGiu,
        TO_CHAR(TRUNC(ptha.THA_NGAY_DEN_TRAI), 'DD/MM/YYYY')         AS NgayDenTrai,
        dpd.PD_TEN || U', ' || dpt.PT_TEN                             AS PhanDoi,
        dpt.PT_TEN                                                   AS PhanTrai,
        dtg.TG_TEN                                                   AS TraiGiam,
        CASE WHEN NVL(tron_agg.TONG_NGAY_TRON, 0) = 0 THEN U'Không'
             ELSE TO_CHAR(tron_agg.TONG_NGAY_TRON) || U' ngày' END   AS ThoiGianTron,
        CASE WHEN NVL(tdc_agg.TONG_NGAY_TDC,  0) = 0 THEN U'Không'
             ELSE TO_CHAR(tdc_agg.TONG_NGAY_TDC)  || U' ngày' END   AS ThoiGianTamDinhChi,
        QLPN.FN_TINH_AN_DA_GIAM_CHI_TIET(rt.PHAM_NHAN_ID)           AS ThoiGianDuocGiam,
        QLPN.FN_FORMAT_YMD(mhp.MHP_THM_YEAR, mhp.MHP_THM_MONTH, mhp.MHP_THM_DAY) AS MienHinhPhat,
        QLPN.FN_GET_DA_CHAP_HANH_TEXT(rt.PHAM_NHAN_ID, SYSDATE)
            || U' (Tính ??n ngày: ' || TO_CHAR(SYSDATE,'DD/MM/YYYY') || U')' AS DaChapHanh,
        QLPN.FN_TINH_THOI_GIAN_CON_LAI(rt.PHAM_NHAN_ID, SYSDATE)    AS ThoiGianConLai,
        TO_CHAR(TRUNC(ptha.THA_NGAY_HET_HAN),  'DD/MM/YYYY')         AS NgayTha,
        rt.LL_TOM_TAT_HV                                             AS HanhViPhamToi
    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
    LEFT JOIN DM_NGHE_NGHIEPS dnn       ON rt.LL_DM_NGHE_NGHIEP_ID  = dnn.ID
    LEFT JOIN LATEST_THA ptha
           ON rt.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID AND ptha.rn = 1
    LEFT JOIN MIEN_HINH_PHATS mhp
           ON rt.PHAM_NHAN_ID = mhp.PN_LAI_LICH_ID AND mhp.IS_DELETED = 0
    LEFT JOIN DM_CO_QUANS dcq           ON ptha.THA_TOA_QD_ID         = dcq.ID
    LEFT JOIN DM_CO_QUANS dcq1          ON ptha.THA_CHUYEN_DEN_TU_ID  = dcq1.ID
    LEFT JOIN DM_CO_QUANS dcq5          ON ptha.THA_CAP_TOA_ID        = dcq5.ID
    LEFT JOIN DM_CO_QUANS dcq2          ON ptha.THA_DON_VI_DE_NGHI_ID = dcq2.ID
    LEFT JOIN DM_TINH_TRANG_SUC_KHOE_PHAM_NHANS dskpn
                                         ON rt.LL_SUC_KHOE_KHI_VAO_ID = dskpn.ID
    LEFT JOIN DM_BENH_TATS dbt          ON rt.LL_BENH_HIEN_TAI_ID    = dbt.ID
    LEFT JOIN TONG_TRON tron_agg        ON rt.PHAM_NHAN_ID = tron_agg.PHAM_NHAN_ID
    LEFT JOIN TONG_TDC  tdc_agg         ON rt.PHAM_NHAN_ID = tdc_agg.PHAM_NHAN_ID
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dttpn ON rt.LL_TINH_TRANG_ID  = dttpn.ID
    LEFT JOIN DM_GIOI_TINHS dgt         ON rt.LL_DM_GIOI_TINH_ID     = dgt.ID
    LEFT JOIN DM_DAN_TOCS ddt           ON rt.LL_DM_DAN_TOC_ID       = ddt.ID
    LEFT JOIN DM_TON_GIAOS dtg2         ON rt.LL_DM_TON_GIAO_ID      = dtg2.ID
    LEFT JOIN DM_QUOC_TICHS dqt         ON rt.LL_DM_QUOC_TICH_ID     = dqt.ID
    LEFT JOIN DM_PHAN_DOIS dpd          ON rt.LL_PHAN_DOI_ID          = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt         ON rt.LL_PHAN_TRAI_ID         = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg         ON rt.LL_TRAI_GIAM_ID         = dtg.ID
    LEFT JOIN DM_HOC_VANS dhv           ON rt.LL_DM_HOC_VAN_ID        = dhv.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
           ON rt.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
          AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
           ON rt.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
          AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN (
        SELECT rt2.PHAM_NHAN_ID,
               RTRIM(
                   XMLAGG(
                       XMLELEMENT(e, dgcr.GCR_TEN || ', ')
                       ORDER BY dgcr.GCR_TEN
                   ).extract('//text()').GETCLOBVAL(), ', '
               ) AS GHI_CHU_RIENG
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt2
        LEFT JOIN LATERAL (
            SELECT TRIM(REGEXP_SUBSTR(rt2.LL_GHI_CHU_RIENG, '[^,]+', 1, LEVEL)) AS GHI_CHU_RIENG_MA
            FROM DUAL
            WHERE rt2.LL_GHI_CHU_RIENG IS NOT NULL
            CONNECT BY LEVEL <= REGEXP_COUNT(rt2.LL_GHI_CHU_RIENG, ',') + 1
        ) gcr ON 1 = 1
        LEFT JOIN DM_GHI_CHU_RIENGS dgcr ON gcr.GHI_CHU_RIENG_MA = TRIM(dgcr.ID)
        WHERE rt2.PHAM_NHAN_ID = p_pll_id AND rt2.IS_DELETED = 0
        GROUP BY rt2.PHAM_NHAN_ID, rt2.LL_GHI_CHU_RIENG
    ) gcr_agg ON rt.PHAM_NHAN_ID = gcr_agg.PHAM_NHAN_ID
    LEFT JOIN (
        SELECT PHAM_NHAN_ID, COUNT(DISTINCT ID) AS SO_CON
        FROM THAN_NHAN_CON_CAIS
        WHERE PHAM_NHAN_ID = p_pll_id
        GROUP BY PHAM_NHAN_ID
    ) con_count ON rt.PHAM_NHAN_ID = con_count.PHAM_NHAN_ID
    WHERE rt.PHAM_NHAN_ID = p_pll_id
      AND rt.IS_DELETED = 0;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        NULL;
    WHEN TOO_MANY_ROWS THEN
        RAISE_APPLICATION_ERROR(-20001, U'Có nhi?u h?n 1 b?n ghi cho ph?m nhân ID: ' || p_pll_id);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: '      || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: '   || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END;




/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_TIN_PHAM_NHAN_QDTHAPT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_TIN_PHAM_NHAN_QDTHAPT" (
    p_pn_ids IN VARCHAR2 DEFAULT NULL  -- Danh sách ID phân cách b?i d?u ph?y, VD: '1,2,3,4'
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        WITH PN_ID_LIST AS (
                -- FIX: B? DISTINCT, thêm LEVEL AS stt ?? gi? th? t? truy?n vào
                SELECT
                    TO_NUMBER(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL))) AS pn_id,
                    LEVEL AS stt
                FROM dual
                CONNECT BY LEVEL <= CASE
                                        WHEN LENGTH(TRIM(NVL(p_pn_ids, ''))) = 0 THEN 0
                                        ELSE REGEXP_COUNT(TRIM(p_pn_ids), ',') + 1
                                    END
                AND REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL) IS NOT NULL
                AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(TRIM(p_pn_ids), '[^,]+', 1, LEVEL)), '^[0-9]+$')
            )
        SELECT
            ptha.THA_KHOAN AS "Khoan", -- không bi?t có dùng không
        	ptha.THA_DIEU AS "Dieu",-- không bi?t có dùng không
			ptha.THA_CAN_CU_TUYEN_PHAT AS "CanCuTuyenPhat", -- không bi?t có dùng không
			ptha.THA_SO_QD_DIEU_CHUYEN AS "SoQDDieuChuyen", -- so_qd_dc
			TO_CHAR(ptha.THA_NGAY_QD_DIEU_CHUYEN,'DD/MM/YYYY') AS "NgayQDDieuChuyen", -- ngay_qd_dc
			dcq.CQ_TEN AS "DonViDeNghi", --«dv_dn_dc»
			dttp.TTP_TEN AS "DiaPhuongDeNghi",  --dv_dn_dc_noi_nhan
			ptha.THA_SO_DE_NGHI AS "SoDeNghi", -- so dn
			TO_CHAR(ptha.THA_NGAY_DE_NGHI,'DD/MM/YYYY') AS "NgayDeNghi", -- ngay dn
			TO_CHAR(ptha.THA_NGAY_DEN_TRAI + 5, 'DD/MM/YYYY') AS "NgayDenTrai",
            vpllct.HO_TEN AS "HoTen",
            vpllct.GIOI_TINH AS "GioiTinh",
            vpllct.NAM_SINH AS "NamSinh",
            vpllct.TEN_KHAC AS "TenKhac",
            vpllct.NOI_THUONG_TRU_DAY_DU AS "DiaChiThuongTru",
            vpllct.TOI_DANH AS "ToiDanh",
            TO_CHAR(vpllct.NGAY_BAT_AN_PHAT,'DD/MM/YYYY') AS "NgayBatAnPhat",
            vpllct.AN_PHAT AS "AnPhat",
        -- T?m giam + T?m gi? c?ng g?p
			QLPN.FN_CONG_TAM_GIAM_TAM_GIU(
            ptha.THA_THOI_GIAN_TAM_GIAM,
            ptha.THA_THOI_GIAN_TAM_GIU) AS "TamGiamTamGiu",
--            CASE WHEN ptha.THA_THOI_GIAN_TAM_GIAM IS NULL THEN u'KH\00f4ng'
--            ELSE ptha.THA_THOI_GIAN_TAM_GIAM
--            END AS "TamGiam",
--            CASE WHEN ptha.THA_THOI_GIAN_TAM_GIU IS NULL THEN u'KH\00f4ng'
--            ELSE ptha.THA_THOI_GIAN_TAM_GIU
--            END AS "TamGiu",
            vpllct.SO_BAN_AN AS "SoBanAn", -- so_ba
            TO_CHAR(vpllct.NGAY_BAN_AN ,'DD/MM/YYYY') AS "NgayBanAn", -- ngay_xu
            vpllct.TOA_XU_TEN AS "ToaXuTen", -- toa_xu
            ptha.THA_SO_QD_THA AS "SoQDTha",-- so_qd_tha
        	dcq2.CQ_TEN AS "ToaQuyetDinh", -- toa qd
        	d.TTP_TEN AS "DiaPhuongToa",-- dia phuong toa
            TO_CHAR(ptha.THA_NGAY_QD_THA ,'DD/MM/YYYY')AS "NgayQDTha", -- ngay_qd_tha
            dcq3.CQ_TEN AS "TraiChuyenDen", -- trai_chuyen_den
            dcq3.CQ_TEN AS "TraiGiam", --tam_giam
            dtg.TG_DIA_CHI AS "DiaChiTG",
			t1.TSHT_GIA_TRI AS "DiaDanhTc8", --dia_danh_tc8
            t2.TSHT_GIA_TRI AS "TraiThuong", --trai_thuong
            t3.TSHT_GIA_TRI AS "DcTrai", --dc_trai
            t4.TSHT_GIA_TRI AS "LanhDaoTC8", -- lanh_dao_tc8
            t5.TSHT_GIA_TRI AS "DiaDanhBC", -- dia_danh_trai
            t6.TSHT_GIA_TRI AS "ChucDanhKy"
        FROM VW_PN_LAI_LICH_CHI_TIET vpllct
		JOIN PN_ID_LIST pil
		    ON vpllct.PHAM_NHAN_ID = pil.pn_id
        LEFT JOIN PN_LAI_LICHS ll 
        	ON vpllct.PHAM_NHAN_ID = ll.ID
       	LEFT JOIN PN_THI_HANH_AN ptha
       		ON ll.ID = ptha.THA_PNLAI_LICH_ID
       LEFT JOIN DM_TINH_THANH_PHO dttp 
       	ON ptha.THA_DIA_PHUONG_DON_VI_DE_NGHI_ID = dttp.ID
       	LEFT JOIN DM_CO_QUANS dcq
       		ON ptha.THA_DON_VI_DE_NGHI_ID = dcq.ID
        LEFT JOIN DM_TINH_THANH_PHO d ON ptha.THA_DIA_PHUONG_TOA_QD_THA_ID = d.ID
        LEFT JOIN DM_CO_QUANS dcq2 ON ptha.THA_TOA_QD_ID = dcq2.ID
        LEFT JOIN DM_TRAI_GIAMS dtg 
            ON vpllct.TRAI_GIAM_ID = dtg.ID
        LEFT JOIN DM_CO_QUANS dcq3 ON ptha.THA_CHUYEN_DEN_TU_ID = dcq3.ID
        LEFT JOIN DM_TRAI_GIAMS dtg2 ON ptha.THA_CHUYEN_DEN_TU_ID = dtg2.ID
        LEFT JOIN THAM_SO_HE_THONGS t1 ON 1=1 
        AND t1.TSHT_THAM_SO = u'DIA_DANH_TRICH_SAO'
        LEFT JOIN THAM_SO_HE_THONGS t2 ON 1=1 
        AND t2.TSHT_THAM_SO = u'DON_VI' 
        LEFT JOIN THAM_SO_HE_THONGS t3 ON 1=1 
        AND t3.TSHT_THAM_SO = u'DP_TRAI_GIAM'
        LEFT JOIN THAM_SO_HE_THONGS t4 ON 1=1 
        AND t4.TSHT_THAM_SO = u'LANH_DAO_TC8'
        LEFT JOIN THAM_SO_HE_THONGS t5 ON 1=1 
        AND t5.TSHT_THAM_SO = u'DIA_DANH_BC'
        LEFT JOIN THAM_SO_HE_THONGS t6 ON 1=1
        AND t6.TSHT_THAM_SO = u'CHUC_DANH_KY'
        WHERE p_pn_ids IS NULL 
           OR vpllct.PHAM_NHAN_ID IN (SELECT PN_ID FROM PN_ID_LIST)
		ORDER BY pil.stt;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_THONG_TIN_PHAM_NHAN_QDTHAPT;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_TIN_PHAM_NHAN_THONG_BAO_TIEP_NHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_TIN_PHAM_NHAN_THONG_BAO_TIEP_NHAN" (
    p_pn_ids IN VARCHAR2 DEFAULT NULL  -- Danh sách ID phân cách b?i d?u ph?y, VD: '1,2,3,4'
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        WITH PN_ID_LIST AS (
            SELECT TO_NUMBER(
                REGEXP_SUBSTR(p_pn_ids, '[^,]+', 1, LEVEL)
            ) AS PN_ID
            FROM DUAL
            WHERE p_pn_ids IS NOT NULL
            CONNECT BY LEVEL <= REGEXP_COUNT(p_pn_ids, ',') + 1
        ),
        PN_IDS AS (
            SELECT /*+ MATERIALIZE */
                DISTINCT PN_ID
            FROM PN_ID_LIST
        ),
        HPBS_AGG AS (
            SELECT
                phpbs.HPBS_MA_PHAM_NHAN,
                LISTAGG(
                    dhpbs.HPBS_TEN || ': ' ||
                    TO_CHAR(phpbs.HPBS_TONG_TIEN_PHAT, 'FM999,999,999,999') || ' ??ng',
                    '; '
                ) WITHIN GROUP (ORDER BY phpbs.ID) AS HINH_PHAT_BO_SUNG
            FROM PN_HINH_PHAT_BO_SUNGS phpbs
            JOIN DM_HINH_PHAT_BO_SUNGS dhpbs
                ON phpbs.HPBS_HINH_PHAT = dhpbs.ID
            WHERE phpbs.IS_DELETED = 0
              AND p_pn_ids IS NULL
            GROUP BY phpbs.HPBS_MA_PHAM_NHAN
            UNION ALL
            SELECT /*+ LEADING(pid) USE_NL(phpbs) */
                phpbs.HPBS_MA_PHAM_NHAN,
                LISTAGG(
                    dhpbs.HPBS_TEN || ': ' ||
                    TO_CHAR(phpbs.HPBS_TONG_TIEN_PHAT, 'FM999,999,999,999') || ' ??ng',
                    '; '
                ) WITHIN GROUP (ORDER BY phpbs.ID) AS HINH_PHAT_BO_SUNG
            FROM PN_IDS pid
            JOIN PN_HINH_PHAT_BO_SUNGS phpbs
                ON phpbs.HPBS_MA_PHAM_NHAN = pid.PN_ID
               AND phpbs.IS_DELETED = 0
            JOIN DM_HINH_PHAT_BO_SUNGS dhpbs
                ON phpbs.HPBS_HINH_PHAT = dhpbs.ID
            WHERE p_pn_ids IS NOT NULL
            GROUP BY phpbs.HPBS_MA_PHAM_NHAN
        ),
        NGUOI_THAN_SRC AS (
            SELECT
                tnnt.PHAM_NHAN_ID,
                tnnt.HO_TEN_THAN_NHAN,
                tnnt.NOI_O,
                tnnt.THONG_BAO,
                tnnt.QUAN_HE_ID,
                tnnt.ID
            FROM THAN_NHAN_NGUOI_THANS tnnt
            LEFT JOIN DM_GIOI_TINHS dgt
                ON tnnt.GIOI_TINH_ID = dgt.ID
            WHERE tnnt.IS_DELETED = 0
              AND p_pn_ids IS NULL
            UNION ALL
            SELECT /*+ LEADING(pid) USE_NL(tnnt) */
                tnnt.PHAM_NHAN_ID,
                tnnt.HO_TEN_THAN_NHAN,
                tnnt.NOI_O,
                tnnt.THONG_BAO,
                tnnt.QUAN_HE_ID,
                tnnt.ID
            FROM PN_IDS pid
            JOIN THAN_NHAN_NGUOI_THANS tnnt
                ON tnnt.PHAM_NHAN_ID = pid.PN_ID
               AND tnnt.IS_DELETED = 0
            LEFT JOIN DM_GIOI_TINHS dgt
                ON tnnt.GIOI_TINH_ID = dgt.ID
            WHERE p_pn_ids IS NOT NULL
        ),
        NGUOI_THAN AS (
            SELECT
                s.PHAM_NHAN_ID,
                s.HO_TEN_THAN_NHAN,
                s.NOI_O,
                s.THONG_BAO,
                COUNT(CASE WHEN s.THONG_BAO = 1 THEN 1 END)
                    OVER (PARTITION BY s.PHAM_NHAN_ID) AS CNT_TB,
                ROW_NUMBER() OVER (
                    PARTITION BY s.PHAM_NHAN_ID
                    ORDER BY
                        CASE s.QUAN_HE_ID
                            WHEN 19 THEN 1 WHEN 18 THEN 2
                            WHEN 17 THEN 3 WHEN 44 THEN 4
                            ELSE 99
                        END,
                        s.ID
                ) AS RN
            FROM NGUOI_THAN_SRC s
        ),
        VW_SRC AS (
            SELECT *
            FROM (
                SELECT v.*
                FROM VW_PN_LAI_LICH_CHI_TIET v
                WHERE p_pn_ids IS NULL
                UNION ALL
                SELECT /*+ LEADING(pil) USE_NL(v) */
                    v.*
                FROM PN_IDS pil
                JOIN VW_PN_LAI_LICH_CHI_TIET v
                    ON v.PHAM_NHAN_ID = pil.PN_ID
                WHERE p_pn_ids IS NOT NULL
            )
        )
        SELECT /*+ LEADING(vpllct) USE_NL(ll) USE_NL(ptha) */
            ntut.HO_TEN_THAN_NHAN AS "NguoiThan",
            ntut.NOI_O AS "DiaChiNguoiThan",
            ptha.THA_KHOAN AS "Khoan",
            ptha.THA_DIEU AS "Dieu",
            ptha.THA_SO_DE_NGHI AS "SoDeNghi",
            ptha.THA_CAN_CU_TUYEN_PHAT AS "CanCuTuyenPhat",
            ptha.THA_SO_QD_DIEU_CHUYEN AS "SoQDDieuChuyen",
            ptha.THA_NGAY_QD_DIEU_CHUYEN AS "NgayQDDieuChuyen",
            ptha.THA_NGAY_DEN_TRAI AS "NgayDenTrai",
            dcq.CQ_TEN AS "DonViDeNghi",
            vpllct.HO_TEN AS "HoTen",
            vpllct.GIOI_TINH AS "GioiTinh",
            vpllct.NAM_SINH AS "NamSinh",
            vpllct.TEN_KHAC AS "TenKhac",
            vpllct.DAN_TOC AS "DanToc",
            vpllct.NGUYEN_QUAN AS "NguyenQuan",
            vpllct.NOI_THUONG_TRU_DAY_DU AS "DiaChiThuongTru",
            vpllct.TOI_DANH AS "ToiDanh",
            vpllct.NGAY_BAT_AN_PHAT AS "NgayBatAnPhat",
            vpllct.AN_PHAT AS "AnPhat",
            vpllct.SO_BAN_AN AS "SoBanAn",
            vpllct.NGAY_BAN_AN AS "NgayBanAn",
            vpllct.TOA_XU_TEN AS "ToaXuTen",
            vpllct.CO_QUAN_QD_THA AS "ToaQDTha",
            d.TTP_TEN AS "DiaPhuongToaQDTHA",
            ptha.THA_SO_QD_THA AS "SoQDTha",
            ptha.THA_NGAY_QD_THA AS "NgayQDTha",
            vpllct.TRAI_GIAM AS "TraiGiam",
            dtg.TG_DIA_CHI AS "DiaChiTG",
            vpllct.QUOC_TICH AS "QuocTich",
            vpllct.NOI_O_KHAC AS "ChoOKhac",
            (
                NVL(TO_NCHAR(vpllct.SO_BAN_AN), TO_NCHAR(ptha.THA_SO_BAN_AN))
                || CASE
                    WHEN vpllct.NGAY_BAN_AN IS NOT NULL THEN u' ng\00e0y ' || TO_NCHAR(TO_CHAR(vpllct.NGAY_BAN_AN, 'DD/MM/YYYY'))
                    ELSE u''
                   END
                || CASE
                    WHEN NVL(TO_NCHAR(vpllct.TOA_XU_TEN), u'') <> u'' THEN u' c\1ee7a ' || TO_NCHAR(vpllct.TOA_XU_TEN)
                    ELSE u''
                   END
            ) AS "BA_QDTHHP",
            hpbs_agg.HINH_PHAT_BO_SUNG AS "HinhPhatBoSung"
        FROM VW_SRC vpllct
        LEFT JOIN PN_LAI_LICHS ll
            ON vpllct.PHAM_NHAN_ID = ll.ID
        LEFT JOIN PN_THI_HANH_AN ptha
            ON ll.ID = ptha.THA_PNLAI_LICH_ID
        LEFT JOIN DM_CO_QUANS dcq
            ON ptha.THA_DON_VI_DE_NGHI_ID = dcq.ID
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON vpllct.TRAI_GIAM_ID = dtg.ID
        LEFT JOIN HPBS_AGG hpbs_agg
            ON vpllct.PHAM_NHAN_ID = hpbs_agg.HPBS_MA_PHAM_NHAN
        LEFT JOIN DM_TINH_THANH_PHO d
            ON ptha.THA_DIA_PHUONG_TOA_QD_THA_ID = d.ID
        LEFT JOIN NGUOI_THAN ntut
            ON vpllct.PHAM_NHAN_ID = ntut.PHAM_NHAN_ID
        WHERE ntut.PHAM_NHAN_ID IS NULL
           OR (ntut.CNT_TB > 0 AND ntut.THONG_BAO = 1)
           OR (ntut.CNT_TB = 0 AND ntut.RN = 1);

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_THONG_TIN_PHAM_NHAN_THONG_BAO_TIEP_NHAN;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_TIN_PHAM_NHAN_THONG_BAO_TIEP_NHAN_PT77
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_TIN_PHAM_NHAN_THONG_BAO_TIEP_NHAN_PT77" 
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
        WITH
        PN_ID_LIST AS (
            SELECT /*+ MATERIALIZE DYNAMIC_SAMPLING(g 4) */
                g.PN_ID
            FROM QLPN.GTT_PN_IDS g
        ),
        THI_HANH_AN_LATEST AS (
            SELECT
                X.THA_PNLAI_LICH_ID,
                X.THA_CHUYEN_DEN_TU_ID
            FROM (
                SELECT /*+ LEADING(pid) USE_NL(PTHA) */
                    PTHA.THA_PNLAI_LICH_ID,
                    PTHA.THA_CHUYEN_DEN_TU_ID,
                    ROW_NUMBER() OVER (
                        PARTITION BY PTHA.THA_PNLAI_LICH_ID
                        ORDER BY PTHA.ID DESC
                    ) AS RN
                FROM QLPN.PN_THI_HANH_AN PTHA
                INNER JOIN PN_ID_LIST pid
                    ON pid.PN_ID = PTHA.THA_PNLAI_LICH_ID
                WHERE NVL(PTHA.IS_DELETED, 0) = 0
            ) X
            WHERE X.RN = 1
        )
        SELECT /*+ LEADING(PIL) USE_NL(VPLLCT) USE_NL(PTHA) USE_NL(CQ_CHUYEN_DEN_TU) */
            VPLLCT.HO_TEN AS HO_TEN,
            VPLLCT.GIOI_TINH AS GIOI_TINH,
            VPLLCT.NGAY_SINH AS NGAY_SINH,
            VPLLCT.TEN_KHAC AS TEN_KHAC,
            VPLLCT.NOI_THUONG_TRU_DAY_DU AS NOI_THUONG_TRU,
            VPLLCT.HO_CHIEU AS SO_HO_CHIEU,
            CAST(NULL AS VARCHAR2(10)) AS NGAY_CAP,
            CAST(NULL AS NVARCHAR2(500)) AS NOI_CAP,
            QUOC_TICH,
            VPLLCT.TOI_DANH AS TOI_DANH,
            TO_CHAR(VPLLCT.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT,
            VPLLCT.AN_PHAT AS AN_PHAT,
            VPLLCT.SO_BAN_AN AS SO_BAN_AN,
            TO_CHAR(VPLLCT.NGAY_BAN_AN, 'DD/MM/YYYY') AS NGAY_BAN_AN,
            VPLLCT.TOA_XU_TEN AS TOA_AN_XU,
            VPLLCT.TOA_XU_DIA_PHUONG AS DIA_PHUONG_XU,
            VPLLCT.SO_QD_THA AS SO_QD_THA,
            TO_CHAR(VPLLCT.NGAY_QD_THA, 'DD/MM/YYYY') AS NGAY_QD_THA,
            VPLLCT.CO_QUAN_QD_THA AS CO_QUAN_QD_THA,
            VPLLCT.TOA_QD_THA_DIA_PHUONG AS DIA_PHUONG_QD_THA,
            CQ_CHUYEN_DEN_TU.CQ_TEN AS CQ_CHUYEN_DEN_TU
        FROM PN_ID_LIST PIL
        JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET VPLLCT
            ON VPLLCT.PHAM_NHAN_ID = PIL.PN_ID
        LEFT JOIN THI_HANH_AN_LATEST PTHA
            ON PTHA.THA_PNLAI_LICH_ID = VPLLCT.PHAM_NHAN_ID
        LEFT JOIN QLPN.DM_CO_QUANS CQ_CHUYEN_DEN_TU
            ON CQ_CHUYEN_DEN_TU.ID = PTHA.THA_CHUYEN_DEN_TU_ID
           AND NVL(CQ_CHUYEN_DEN_TU.IS_DELETED, 0) = 0;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_TIN_PHAM_NHAN_THONG_BAO_TIEP_NHAN_PT77;

-- N?p QLPN.GTT_PN_IDS trên cùng session, r?i g?i không tham s?:
