--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_TIN_PHAM_NHAN_THONG_BAO_TIEP_NHAN_PT8
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_TIN_PHAM_NHAN_THONG_BAO_TIEP_NHAN_PT8" 
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        WITH PN_ID_LIST AS (
            -- Tách chu?i ID thành các dòng riêng bi?t
        SELECT PN_ID 
    	FROM QLPN.GTT_PN_IDS
        ),
        HPBS_AGG AS (
            -- N?i chu?i hình ph?t b? sung: tên + ti?n
            SELECT
                phpbs.HPBS_MA_PHAM_NHAN,
                SUM(phpbs.HPBS_TONG_TIEN_CON_LAI) AS TONG_TIEN_CON_LAI,
                LISTAGG(
                    dhpbs.HPBS_TEN || ': ' ||
                    TO_CHAR(phpbs.HPBS_TONG_TIEN_PHAT, 'FM999,999,999,999') || ' ??ng',
                    '; '
                ) WITHIN GROUP (ORDER BY phpbs.ID) AS HINH_PHAT_BO_SUNG
            FROM PN_HINH_PHAT_BO_SUNGS phpbs
            LEFT JOIN DM_HINH_PHAT_BO_SUNGS dhpbs
                ON phpbs.HPBS_HINH_PHAT = dhpbs.ID
            WHERE phpbs.IS_DELETED = 0
            GROUP BY phpbs.HPBS_MA_PHAM_NHAN
        ),
        NGUOI_THAN AS (
    SELECT
        tnnt.PHAM_NHAN_ID,
        tnnt.HO_TEN_THAN_NHAN,
        tnnt.NOI_O,
        tnnt.THONG_BAO,
        dgt.GT_TEN AS GIOI_TINH_NGUOI_THAN,
        COUNT(CASE WHEN tnnt.THONG_BAO = 1 THEN 1 END)
            OVER (PARTITION BY tnnt.PHAM_NHAN_ID) AS CNT_TB,
        ROW_NUMBER() OVER (
            PARTITION BY tnnt.PHAM_NHAN_ID
            ORDER BY
                CASE tnnt.QUAN_HE_ID
                    WHEN 19 THEN 1 WHEN 18 THEN 2
                    WHEN 17 THEN 3 WHEN 44 THEN 4
                    ELSE 99
                END,
                tnnt.ID
        ) AS RN
    FROM THAN_NHAN_NGUOI_THANS tnnt
    LEFT JOIN DM_GIOI_TINHS dgt ON tnnt.GIOI_TINH_ID = dgt.ID
    WHERE tnnt.IS_DELETED = 0
      AND (tnnt.PHAM_NHAN_ID IN (SELECT PN_ID FROM PN_ID_LIST))
),
        BIEN_BAN_CQ_GIAO AS (
            -- C? quan giao (CO_QUAN_GIAO) t? biên b?n ph?m nhân m?i nh?t:
            -- PN_BIEN_BAN_PHAM_NHANS -> PN_BIEN_BANS -> DM_CO_QUANS theo MA_CQ_BG.
            SELECT PN_LAI_LICH_ID, "CoQuanGiao" FROM (
                SELECT
                    bbpnn.PN_LAI_LICH_ID,
                    cqg.CQ_TEN AS "CoQuanGiao",
                    ROW_NUMBER() OVER (PARTITION BY bbpnn.PN_LAI_LICH_ID ORDER BY bb.ID DESC) AS RN
                FROM PN_BIEN_BAN_PHAM_NHANS bbpnn
                LEFT JOIN PN_BIEN_BANS bb ON bbpnn.PN_BIEN_BAN_ID = bb.ID
                LEFT JOIN DM_CO_QUANS cqg ON bb.MA_CQ_BG = TO_CHAR(cqg.ID)
                WHERE bbpnn.IS_DELETED = 0
                  AND bb.IS_DELETED = 0
                  AND bbpnn.PN_LAI_LICH_ID IN (SELECT PN_ID FROM PN_ID_LIST)
            ) WHERE RN = 1
        )
        SELECT
            ntut.HO_TEN_THAN_NHAN AS "NguoiThan", -- nguoi_bao_tin
            ntut.NOI_O AS "DiaChiNguoiThan", -- dc_bao_tin
            ntut.GIOI_TINH_NGUOI_THAN AS "GioiTinhNguoiThan",
        ptha.THA_KHOAN AS "Khoan",
        ptha.THA_DIEU AS "Dieu",
        ptha.THA_SO_DE_NGHI AS "SoDeNghi", -- so_cv
		ptha.THA_CAN_CU_TUYEN_PHAT AS "CanCuTuyenPhat",
		ptha.THA_SO_QD_DIEU_CHUYEN AS "SoQDDieuChuyen", --so_qd_dc
		ptha.THA_NGAY_QD_DIEU_CHUYEN AS "NgayQDDieuChuyen", --ngay_qd_dc
		ptha.THA_NGAY_DEN_TRAI AS "NgayDenTrai", --ngay_den_trai
		dcq.CQ_TEN AS "DonViDeNghi", -- don vi giao
            vpllct.HO_TEN AS "HoTen",
            vpllct.GIOI_TINH AS "GioiTinh",
            vpllct.NAM_SINH AS "NamSinh",
            vpllct.TEN_KHAC AS "TenKhac",
            NVL(vpllct.cccd, vpllct.ho_chieu) AS "SoCCCD",
            TO_CHAR(vpllct.ngay_cap_cccd, 'DD/MM/YYYY')  AS "NgayCapCCCD",
            vpllct.noi_cap_cccd AS "NoiCapCCCD",
            vpllct.DAN_TOC AS "DanToc",
            vpllct.NGUYEN_QUAN AS "NguyenQuan",
            vpllct.NOI_THUONG_TRU_DAY_DU AS "DiaChiThuongTru",
            vpllct.TOI_DANH AS "ToiDanh",
            vpllct.NGAY_BAT_AN_PHAT AS "NgayBatAnPhat",
            vpllct.AN_PHAT AS "AnPhat",
            vpllct.SO_BAN_AN AS "SoBanAn", -- so_ba
            vpllct.NGAY_BAN_AN AS "NgayBanAn", -- ngay_xu
            vpllct.TOA_XU_TEN AS "ToaXuTen", -- toa_xu
            vpllct.TOA_XU_DIA_PHUONG  AS "DiaPhuongToaXu",
            vpllct.CO_QUAN_QD_THA "ToaQDTha", -- toa_qd_tha
            d.TTP_TEN AS "DiaPhuongToaQDTHA",
            ptha.THA_SO_QD_THA AS "SoQDTha" ,-- so_qd_tha
            ptha.THA_NGAY_QD_THA AS "NgayQDTha", -- ngay_qd_tha
            vpllct.TRAI_GIAM AS "TraiGiam", -- trai_giam
            dcq_cdt.CQ_TEN AS "ChuyenDenTu",
            vpllct.QUOC_TICH AS "QuocTich", -- quoc_tich
            vpllct.NOI_O_KHAC AS "ChoOKhac", -- cho_o_khac
            (
                NVL(TO_NCHAR(vpllct.SO_BAN_AN), TO_NCHAR(ptha.THA_SO_BAN_AN))
                || CASE
                    WHEN vpllct.NGAY_BAN_AN IS NOT NULL THEN u' ng\00e0y ' || TO_NCHAR(TO_CHAR(vpllct.NGAY_BAN_AN, 'DD/MM/YYYY'))
                    ELSE u''
                   END
                || CASE
                    WHEN NVL(TO_NCHAR(vpllct.TOA_XU_TEN), u'') <> u'' THEN u' c\1ee7a ' || TO_NCHAR(vpllct.TOA_XU_TEN)
                    ELSE u''
                   END
            ) AS "BA_QDTHHP",
            -- Hình ph?t b? sung (?ã n?i chu?i)
            FN_GET_THONG_TIN_HPBS_PT(ll.ID) AS "HinhPhatBoSung",
            hpbs_agg.TONG_TIEN_CON_LAI AS "TongTienConLai",
            FN_GET_LIET_KE_HPBS_CHI_TIET_GHI_CHU(ll.ID) AS "HinhPhatBoSungRutGon",
            SUBSTR(TO_CHAR(ll.LL_SO_HO_SO_LAN_DAU), 7, 4) AS "SoTB",
            bbq."CoQuanGiao" AS "CoQuanGiao"
        FROM VW_PN_LAI_LICH_CHI_TIET vpllct
        LEFT JOIN PN_LAI_LICHS ll
        ON vpllct.PHAM_NHAN_ID = ll.ID
       LEFT JOIN PN_THI_HANH_AN ptha
       ON ll.ID = ptha.THA_PNLAI_LICH_ID
       LEFT JOIN DM_CO_QUANS dcq
       ON ptha.THA_DON_VI_DE_NGHI_ID = dcq.ID
        LEFT JOIN DM_CO_QUANS dcq_cdt
            ON ptha.THA_CHUYEN_DEN_TU_ID = dcq_cdt.ID
        LEFT JOIN HPBS_AGG hpbs_agg
            ON vpllct.PHAM_NHAN_ID = hpbs_agg.HPBS_MA_PHAM_NHAN
        LEFT JOIN DM_TINH_THANH_PHO d
        ON ptha.THA_DIA_PHUONG_TOA_QD_THA_ID  = d.ID
        LEFT JOIN BIEN_BAN_CQ_GIAO bbq
            ON ll.ID = bbq.PN_LAI_LICH_ID
        LEFT JOIN NGUOI_THAN ntut
            ON vpllct.PHAM_NHAN_ID = ntut.PHAM_NHAN_ID
        WHERE ( vpllct.PHAM_NHAN_ID IN (SELECT PN_ID FROM PN_ID_LIST))
       AND (
    ntut.PHAM_NHAN_ID IS NULL  -- không có ng??i thân
    OR (
        ntut.CNT_TB > 0 AND ntut.THONG_BAO = 1   -- có thông báo -> l?y t?t c? THONG_BAO=1
    )
    OR (
        ntut.CNT_TB = 0 AND ntut.RN = 1          -- không có thông báo -> l?y 1 ng??i ?u tiên
    )
);
    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_THONG_TIN_PHAM_NHAN_THONG_BAO_TIEP_NHAN_PT8;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_TIN_THE_THEO_DOI_PHAM_NHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_TIN_THE_THEO_DOI_PHAM_NHAN" (
    p_pham_nhan_id IN NUMBER
) AS
    C1 SYS_REFCURSOR;
BEGIN
    IF p_pham_nhan_id IS NULL THEN
        RAISE_APPLICATION_ERROR(-20002, 'Tham s? p_pham_nhan_id không ???c ?? tr?ng.');
    END IF;

    OPEN C1 FOR
        WITH
        -- Thân nhân: b?, m?, v?/ch?ng
        TNB AS (
            SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN
            FROM (SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN, ROW_NUMBER() OVER (PARTITION BY PHAM_NHAN_ID ORDER BY ID) rn
                  FROM THAN_NHAN_NGUOI_THANS
                  WHERE QUAN_HE_ID = 19 AND NVL(IS_DELETED, 0) = 0)
            WHERE rn = 1
        ),
        TNM AS (
            SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN
            FROM (SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN, ROW_NUMBER() OVER (PARTITION BY PHAM_NHAN_ID ORDER BY ID) rn
                  FROM THAN_NHAN_NGUOI_THANS
                  WHERE QUAN_HE_ID = 18 AND NVL(IS_DELETED, 0) = 0)
            WHERE rn = 1
        ),
        VC AS (
            SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN, NOI_O
            FROM (SELECT PHAM_NHAN_ID, HO_TEN_THAN_NHAN, NOI_O, ROW_NUMBER() OVER (PARTITION BY PHAM_NHAN_ID ORDER BY ID) rn
                  FROM THAN_NHAN_NGUOI_THANS
                  WHERE QUAN_HE_ID = 20 AND NVL(IS_DELETED, 0) = 0)
            WHERE rn = 1
        ),
        -- M?c 28: ??n tr?i
        DEN_TRAI_BASE AS (
            SELECT NGAY_DEN_TRAI, ROW_NUMBER() OVER (ORDER BY NGAY_DEN_TRAI NULLS LAST) AS SO_TT_NHAP_TRAI, TEN_TRAI
            FROM (
                SELECT gn.GNPN_NGAY_GIAO_NHAN AS NGAY_DEN_TRAI,
                       NVL(gn.GNPN_TEN_CO_QUAN_BEN_NHAN, '') AS TEN_TRAI
                FROM PN_LAI_LICHS ll
                INNER JOIN PN_GIAO_NHAN_PHAN_NHANS gn ON ll.LL_PN_GIAO_NHAN_PHAN_NHAN_ID = gn.ID 
                WHERE ll.ID = p_pham_nhan_id
                UNION ALL
                SELECT pct.PNCT_NGAY_CHUYEN, NVL(dvhc.TTP_TEN, '')
                FROM PHAM_NHAN_CHUYEN_TRAI pct
                LEFT JOIN DM_TINH_THANH_PHO dvhc ON pct.PNCT_TRAI_DEN_DIA_PHUONG_ID = dvhc.ID AND NVL(dvhc.IS_DELETED, 0) = 0
                WHERE pct.PNCT_LAI_LICH_ID = p_pham_nhan_id AND NVL(pct.IS_DELETED, 0) = 0
            ) u
        ),
        DEN_TRAI_AGG AS (
            SELECT p_pham_nhan_id AS PN_ID,
                   LISTAGG(TO_CHAR(NGAY_DEN_TRAI, 'DD/MM/YYYY') || ' | ' || SO_TT_NHAP_TRAI || ' | ' || NVL(TEN_TRAI, ''),
                           CHR(10)) WITHIN GROUP (ORDER BY NGAY_DEN_TRAI NULLS LAST) AS DEN_TRAI
            FROM DEN_TRAI_BASE
        ),
        -- M?c 29: Ti?n án
        TIEN_AN_AGG AS (
            SELECT PNTA_LAI_LICH_ID AS PN_ID,
                   LISTAGG(TO_CHAR(pta.PNTA_NAM_XU) || ' | ' || NVL(ma.MA_TEN_CHI_TIEU, TO_CHAR(pta.PNTA_MUC_AN_ID)) || ' | ' || NVL(pta.PNTA_TOI_DANH_ID, NVL(td.TD_TEN, '')),
                           CHR(10)) WITHIN GROUP (ORDER BY pta.PNTA_NAM_XU) AS TIEN_AN
            FROM PN_TIEN_AN pta
            LEFT JOIN DM_MUC_ANS ma ON pta.PNTA_MUC_AN_ID = ma.ID AND NVL(ma.IS_DELETED, 0) = 0
            LEFT JOIN DM_TOI_DANHS td ON TO_NUMBER(REGEXP_SUBSTR(NVL(TRIM(pta.PNTA_TOI_DANH_ID), ''), '[0-9]+', 1, 1)) = td.ID AND NVL(td.IS_DELETED, 0) = 0
            WHERE pta.PNTA_LAI_LICH_ID = p_pham_nhan_id AND NVL(pta.IS_DELETED, 0) = 0
            GROUP BY PNTA_LAI_LICH_ID
        ),
        -- M?c 30: Gi?m th?i h?n
        GIAM_AN_AGG AS (
            SELECT PHAM_NHAN_ID AS PN_ID,
                   LISTAGG(TO_CHAR(EXTRACT(YEAR FROM NVL(NGAY_QUYET_DINH, NGAY_XET))) || ' | ' || NVL(DA_GIAM, ''),
                           CHR(10)) WITHIN GROUP (ORDER BY NVL(NGAY_QUYET_DINH, NGAY_XET) NULLS LAST) AS GIAM_AN
            FROM GIAM_THOI_HANS
            WHERE PHAM_NHAN_ID = p_pham_nhan_id AND NVL(IS_DELETED, 0) = 0
              AND DA_GIAM IS NOT NULL AND TRIM(DA_GIAM) <> 'Không'
            GROUP BY PHAM_NHAN_ID
        ),
        -- M?c 31: K?t qu? CH án hàng n?m
        XEP_LOAI_AGG AS (
            SELECT PHAM_NHAN_ID AS PN_ID,
                   LISTAGG(TO_CHAR(x.XEP_LOAI_NAM) || ' | ' || NVL(d.XLCT_TEN, d2.XL_TEN),
                           CHR(10)) WITHIN GROUP (ORDER BY x.XEP_LOAI_NAM) AS XEP_LOAI
            FROM XEP_LOAIS x
            LEFT JOIN DM_XEP_LOAI_CAI_TAOS d ON x.XEP_LOAI_CA_NAM = d.ID AND NVL(d.IS_DELETED, 0) = 0
            LEFT JOIN DM_XEP_LOAIES d2 ON x.XEP_LOAI_CA_NAM = d2.ID AND NVL(d2.IS_DELETED, 0) = 0
            WHERE x.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(x.IS_DELETED, 0) = 0
              AND (x.XEP_LOAI_CA_NAM IS NOT NULL OR x.XEP_LOAI_NAM IS NOT NULL)
            GROUP BY PHAM_NHAN_ID
        ),
        -- M?c 32: Tr?n / B?t l?i
        TRON_AGG AS (
            SELECT PHAM_NHAN_ID AS PN_ID,
                   LISTAGG(TO_CHAR(tt.NGAY_TRON, 'DD/MM/YYYY') || ' | ' || TO_CHAR(tt.NGAY_BAT_LAI, 'DD/MM/YYYY'),
                           CHR(10)) WITHIN GROUP (ORDER BY tt.NGAY_TRON NULLS LAST) AS TRON_TRAI
            FROM TRON_TRAIS tt
            WHERE tt.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(tt.IS_DELETED, 0) = 0
            GROUP BY PHAM_NHAN_ID
        ),
        -- M?c 33: Trích xu?t
        TRICH_AGG AS (
            SELECT tx.PHAM_NHAN_ID AS PN_ID,
                   LISTAGG(NVL(TO_CHAR(tx.TX_NGAY_TRICH_XUAT, 'DD/MM/YYYY'), '') || NVL2(tx.TX_NGAY_TRA, ' - ' || TO_CHAR(tx.TX_NGAY_TRA, 'DD/MM/YYYY'), '') || ' | ' || NVL(dvhc.TTP_TEN, ''),
                           CHR(10)) WITHIN GROUP (ORDER BY tx.TX_NGAY_TRICH_XUAT NULLS LAST) AS TRICH_XUAT
            FROM TRICH_XUATS tx
            LEFT JOIN DM_TINH_THANH_PHO dvhc ON tx.TX_DIA_PHUONG_VE_ID = dvhc.ID AND NVL(dvhc.IS_DELETED, 0) = 0
            WHERE tx.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(tx.IS_DELETED, 0) = 0
            GROUP BY tx.PHAM_NHAN_ID
        ),
        -- M?c 34: T?m ?ình ch?
        TAM_DINH_AGG AS (
            SELECT td.PHAM_NHAN_ID AS PN_ID,
                   LISTAGG(NVL(TO_CHAR(td.TU_NGAY, 'DD/MM/YYYY'), '') || NVL2(td.NGAY_LAI, ' - ' || TO_CHAR(td.NGAY_LAI, 'DD/MM/YYYY'), '') || ' | ' || NVL(dvhc.TTP_TEN, ''),
                           CHR(10)) WITHIN GROUP (ORDER BY td.TU_NGAY NULLS LAST) AS TAM_DINH_CHI
            FROM TAM_DINH_CHIS td
            LEFT JOIN DM_TINH_THANH_PHO dvhc ON td.NOI_VE_DIA_PHUONG_ID = dvhc.ID AND NVL(dvhc.IS_DELETED, 0) = 0
            WHERE td.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(td.IS_DELETED, 0) = 0
            GROUP BY td.PHAM_NHAN_ID
        ),
        -- M?c 35: Ngày ch?t (0 ho?c 1 dòng)
        CHET_ONE AS (
            SELECT KTC_PN_LAI_LICH_ID AS PN_ID, KTC_NGAY_CHET AS NGAY_CHET,
                   NVL(KTC_NGUYEN_NHAN_CHET_CHI_TIET, KTC_DIEN_BIEN_CHET) AS LY_DO_CHET,
                   NVL(KTC_NOI_CHON, '') AS NOI_CHON
            FROM PN_KET_THUC_CHETS
            WHERE KTC_PN_LAI_LICH_ID = p_pham_nhan_id AND NVL(IS_DELETED, 0) = 0
            FETCH FIRST 1 ROW ONLY
        ),
        -- M?c 36: Ch?p hành xong án (0 ho?c 1 dòng)
        RA_TRAI_ONE AS (
            SELECT kt.KTRT_PN_LAI_LICH_ID AS PN_ID, kt.KTRT_NGAY_THA AS NGAY_CHXAPT,
                   NVL(v.NOI_THA_VE_CU_TRU, '') AS NOI_VE_CU_TRU_RA
            FROM PN_KET_THUC_RA_TRAIS kt
            LEFT JOIN VW_PN_LAI_LICH_CHI_TIET v ON v.PHAM_NHAN_ID = kt.KTRT_PN_LAI_LICH_ID
            WHERE kt.KTRT_PN_LAI_LICH_ID = p_pham_nhan_id AND NVL(kt.IS_DELETED, 0) = 0
            ORDER BY kt.KTRT_NGAY_THA DESC NULLS LAST
            FETCH FIRST 1 ROW ONLY
        )
        SELECT
            v.PHAM_NHAN_ID,
            v.SO_HO_SO AS DANH_BAN_SO,
            v.HO_TEN,
            v.GIOI_TINH,
            v.NAM_SINH,
            v.NGAY_SINH,
            v.TEN_KHAC AS HO_TEN_KHAC,
            v.NGUYEN_QUAN,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_DKTT,
            v.NOI_THUONG_TRU_DAY_DU AS NOI_CU_TRU_TRUOC_BAT,
            v.DAN_TOC,
            v.TON_GIAO,
            v.QUOC_TICH,
            v.HOC_VAN AS TRINH_DO_HOC_VAN,
            v.NGHE_NGHIEP,
            NVL(TNB.HO_TEN_THAN_NHAN, '') AS HO_TEN_BO,
            NVL(TNM.HO_TEN_THAN_NHAN, '') AS HO_TEN_ME,
            NVL(VC.HO_TEN_THAN_NHAN, '') AS HO_TEN_VC,
            NVL(VC.NOI_O, '') AS DIA_CHI_VC,
            v.GHI_CHU_RIENG,
            v.TOI_DANH,
            v.NGAY_BAT_AN_PHAT AS NGAY_BAT,
            v.AN_PHAT,
            v.THOI_GIAN_TAM_GIAM,
            v.SO_BAN_AN,
            v.NGAY_BAN_AN,
            v.TOA_XU_TEN || NVL2(v.TOA_XU_DIA_PHUONG, u', ' || v.TOA_XU_DIA_PHUONG, '') AS TOA_XU,
            v.SO_QD_THA,
            v.NGAY_QD_THA,
            v.CO_QUAN_QD_THA || NVL2(v.TOA_QD_THA_DIA_PHUONG, u', ' || v.TOA_QD_THA_DIA_PHUONG, '') AS CO_QUAN_QD_THA,
            v.TOM_TAT_HANH_VI AS TOM_TAT_QUA_TRINH_PHAM_TOI,
            v.TRAI_GIAM,
            v.PHAN_DOI,
            v.PHAN_TRAI,
            -- M?c 28-34: LISTAGG
            dt.DEN_TRAI,
            ta.TIEN_AN,
            ga.GIAM_AN,
            xl.XEP_LOAI,
            tr.TRON_TRAI,
            tch.TRICH_XUAT,
            tdc.TAM_DINH_CHI,
            -- M?c 35-36: scalar
            ch.NGAY_CHET,
            ch.LY_DO_CHET,
            ch.NOI_CHON,
            rt.NGAY_CHXAPT,
            rt.NOI_VE_CU_TRU_RA
        FROM VW_PN_LAI_LICH_CHI_TIET v
        LEFT JOIN TNB ON TNB.PHAM_NHAN_ID = v.PHAM_NHAN_ID
        LEFT JOIN TNM ON TNM.PHAM_NHAN_ID = v.PHAM_NHAN_ID
        LEFT JOIN VC ON VC.PHAM_NHAN_ID = v.PHAM_NHAN_ID
        LEFT JOIN DEN_TRAI_AGG dt ON dt.PN_ID = v.PHAM_NHAN_ID
        LEFT JOIN TIEN_AN_AGG ta ON ta.PN_ID = v.PHAM_NHAN_ID
        LEFT JOIN GIAM_AN_AGG ga ON ga.PN_ID = v.PHAM_NHAN_ID
        LEFT JOIN XEP_LOAI_AGG xl ON xl.PN_ID = v.PHAM_NHAN_ID
        LEFT JOIN TRON_AGG tr ON tr.PN_ID = v.PHAM_NHAN_ID
        LEFT JOIN TRICH_AGG tch ON tch.PN_ID = v.PHAM_NHAN_ID
        LEFT JOIN TAM_DINH_AGG tdc ON tdc.PN_ID = v.PHAM_NHAN_ID
        LEFT JOIN CHET_ONE ch ON ch.PN_ID = v.PHAM_NHAN_ID
        LEFT JOIN RA_TRAI_ONE rt ON rt.PN_ID = v.PHAM_NHAN_ID
        WHERE v.PHAM_NHAN_ID = p_pham_nhan_id;

    DBMS_SQL.RETURN_RESULT(C1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'SP_GET_THONG_TIN_THE_THEO_DOI_PHAM_NHAN: ' || SQLERRM);
END SP_GET_THONG_TIN_THE_THEO_DOI_PHAM_NHAN;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THONG_TIN_TRACH_NHIEM_DAN_SU_TIEN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THONG_TIN_TRACH_NHIEM_DAN_SU_TIEN" (
    p_pham_nhan_id IN NUMBER
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        SELECT
	    CAST(NVL(dm.HPBS_TEN, u'') AS NVARCHAR2(2000)) AS HINH_PHAT,
	    TO_CHAR(NVL(hp.HPBS_TONG_TIEN_PHAT, 0), 'FM999,999,999,999,999') AS TONG_TIEN,
	    TO_CHAR(
	        GREATEST(
	            0,
	            NVL(hp.HPBS_TONG_TIEN_PHAT, 0) - NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0)
	        ), 'FM999,999,999,999,999'
	    ) AS DA_HOAN,
	    TO_CHAR(NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0), 'FM999,999,999,999,999') AS CHUA_HOAN,
	    CAST(NVL(gch.GCHPBS_TEN, u'') AS NVARCHAR2(2000)) AS GHI_CHU
        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
        INNER JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
            ON dm.ID = hp.HPBS_HINH_PHAT
           AND NVL(dm.IS_DELETED, 0) = 0
           AND dm.HPBS_MA IN (
               '250', '251', '252', '260', '261', '262', '263',
               '212', '213', '214',
               '231', '232', '233', '234',
               '240', '999'
           )
        LEFT JOIN QLPN.DM_GHI_CHU_HINH_PHAT_BO_SUNGS gch
            ON gch.ID = hp.HPBS_GHI_CHU
           AND NVL(gch.IS_DELETED, 0) = 0
        WHERE NVL(hp.IS_DELETED, 0) = 0
          AND p_pham_nhan_id IS NOT NULL
          AND hp.HPBS_MA_PHAM_NHAN = p_pham_nhan_id
        ORDER BY dm.HPBS_MA;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i SP_GET_THONG_TIN_TRACH_NHIEM_DAN_SU_TIEN: ' || SQLERRM
        );
END SP_GET_THONG_TIN_TRACH_NHIEM_DAN_SU_TIEN;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_THU_GIU_DO_VAT_PT93
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_THU_GIU_DO_VAT_PT93" (
    p_pham_nhan_id IN NUMBER
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        WITH vw_one AS (
            SELECT v.*
            FROM qlpn.vw_pn_lai_lich_chi_tiet v
            WHERE NVL(v.is_deleted, 0) = 0
              AND v.pham_nhan_id = p_pham_nhan_id
        ),
        kl_one AS (
            SELECT *
            FROM (
                SELECT k.*,
                       ROW_NUMBER() OVER (
                           ORDER BY k.ngay_quyet_dinh DESC NULLS LAST, k.id DESC
                       ) AS rn
                FROM qlpn.ky_luats k
                WHERE k.pham_nhan_id = p_pham_nhan_id
            )
            WHERE rn = 1
        )
        SELECT
            v.ho_ten AS HO_TEN,
            v.ngay_sinh AS NGAY_SINH,
            NVL(v.noi_thuong_tru_day_du, v.dia_chi_thuong_tru) AS NOI_THUONG_TRU,
            v.toi_danh AS TOI_DANH,
            TO_CHAR(v.ngay_bat_an_phat, 'DD/MM/YYYY') AS NGAY_BAT,
            v.an_phat AS AN_PHAT,
            TO_CHAR(v.ngay_den_trai, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
            v.so_ban_an AS SO_BAN_AN,
            TO_CHAR(v.ngay_ban_an, 'DD/MM/YYYY') AS NGAY_BAN_AN,
            v.toa_xu_ten AS TOA_AN_XU,
            v.toa_xu_dia_phuong AS DIA_PHUONG_TOA_XU,
            v.so_qd_tha AS SO_QD_THA,
            TO_CHAR(v.ngay_qd_tha, 'DD/MM/YYYY') AS NGAY_QD_THA,
            v.co_quan_qd_tha AS TOA_AN_QD_THA,
            v.toa_qd_tha_dia_phuong AS DIA_PHUONG_TOA_QD_THA,
            CAST(NULL AS NVARCHAR2(4000)) AS DO_VAT_CAM,
            TRIM(NVL(v.phan_doi, '') ||
                 CASE
                     WHEN v.phan_doi IS NOT NULL AND v.phan_trai IS NOT NULL THEN ', '
                     ELSE ''
                 END ||
                 NVL(v.phan_trai, '')) AS PHAN_DOI
        FROM kl_one kl
        INNER JOIN vw_one v
                ON v.pham_nhan_id = kl.pham_nhan_id
        LEFT JOIN qlpn.dm_trai_giams tg
               ON tg.id = v.trai_giam_id
              AND NVL(tg.is_deleted, 0) = 0;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_THU_GIU_DO_VAT_PT93: ' || SQLERRM);
END SP_GET_THU_GIU_DO_VAT_PT93;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TIEN_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TIEN_AN" (
    p_LAI_LICH_ID IN NUMBER
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH tien_an_base AS (
        SELECT 
            pta.PNTA_LAI_LICH_ID,
            dcq.CQ_TEN AS "ToaXu",
            pta.PNTA_NAM_XU AS "NamXu",
            pta.PNTA_NAM_THA AS "NamTha",
            dmtg.MTG_TITLE AS "MucAn",
            -- Làm s?ch chu?i t?i danh: b? d?u [] và kho?ng tr?ng th?a
            TRIM(BOTH ',' FROM 
                REPLACE(REPLACE(pta.PNTA_TOI_DANH_ID, '[', ''), ']', '')
            ) AS cleaned_toi_danh
        FROM PN_TIEN_AN pta
        LEFT JOIN DM_CO_QUANS dcq ON pta.PNTA_TOA_XU_ID = dcq.ID
        LEFT JOIN DM_MA_THOI_GIANS dmtg ON pta.PNTA_MUC_AN_ID = dmtg.ID
        WHERE pta.PNTA_LAI_LICH_ID = p_LAI_LICH_ID
          AND pta.IS_DELETED = 0
    ),
    toi_danh_split AS (
        SELECT 
            b.*,
            TRIM(REGEXP_SUBSTR(b.cleaned_toi_danh, '[^,]+', 1, LEVEL)) AS TOI_DANH_ID
        FROM tien_an_base b
        CONNECT BY LEVEL <= REGEXP_COUNT(b.cleaned_toi_danh, ',') + 1
           AND PRIOR b.PNTA_LAI_LICH_ID = b.PNTA_LAI_LICH_ID
           AND PRIOR SYS_GUID() IS NOT NULL
    )
    SELECT 
        s.PNTA_LAI_LICH_ID,
        s."ToaXu",
        s."NamXu",
        dtd.TD_TEN AS "ToiDanh",           -- Tên t?i danh (m?i dòng m?t t?i)
        s."MucAn",
        s."NamTha"
    FROM toi_danh_split s
    LEFT JOIN DM_TOI_DANHS dtd ON TO_NUMBER(s.TOI_DANH_ID) = dtd.ID
    WHERE s.TOI_DANH_ID IS NOT NULL
    ORDER BY s.PNTA_LAI_LICH_ID, dtd.TD_TEN;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_TIEN_AN;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TIEN_SU
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TIEN_SU" (
    p_LAI_LICH_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        pts.TS_PN_LAI_LICH_ID,
        pts.TS_THOI_GIAN  AS "ThoiGian",
        pts.TS_HANH_VI_VI_PHAM  AS "HanhViViPham",
        pts.TS_DON_VI_XU_LY  AS "DonViXuLy",
        pts.TS_HINH_THUC_XU_LY  AS "HinhThuc",
        TO_CHAR(pts.TS_NGAY_BAT_DAU,'DD/MM/YYYY')  AS "TuNgay",
        TO_CHAR(pts.TS_NGAY_KET_THUC,'DD/MM/YYYY')  AS "DenNgay"
    FROM PN_TIEN_SUS pts
    WHERE pts.TS_PN_LAI_LICH_ID = p_LAI_LICH_ID
	AND pts.IS_DELETED = 0;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_TIEN_SU;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TIM_KIEM_PN_LAI_LICH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TIM_KIEM_PN_LAI_LICH" (
    p_ma_trai_giam          IN NVARCHAR2 DEFAULT NULL,
        -- DM_TRAI_GIAMS.TG_MA — l?c theo tr?i; NULL ho?c N'C10' = toàn C10
    p_so_hsld               IN NVARCHAR2 DEFAULT NULL,
    p_cccd                  IN NVARCHAR2 DEFAULT NULL,
    p_ho_ten                IN NVARCHAR2 DEFAULT NULL,
    p_ngay_sinh             IN VARCHAR2  DEFAULT NULL,
    p_gioi_tinh_id          IN NUMBER    DEFAULT NULL,
    p_ho_ten_bo             IN NVARCHAR2 DEFAULT NULL,
    p_ho_ten_me             IN NVARCHAR2 DEFAULT NULL,
    p_ho_ten_vo_chong       IN NVARCHAR2 DEFAULT NULL,
    p_tinh_trang_id         IN NUMBER    DEFAULT NULL,
    p_dan_toc_id            IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id          IN NUMBER    DEFAULT NULL,
    p_ton_giao_id           IN NUMBER    DEFAULT NULL,
    p_toi_danh              IN NUMBER    DEFAULT NULL,  -- ID t?i danh (DM_TOI_DANHS.ID)
    p_ngay_bat              IN VARCHAR2  DEFAULT NULL,
    p_noi_dang_ky_tt        IN NVARCHAR2 DEFAULT NULL,
    p_ve_cu_tru             IN NVARCHAR2 DEFAULT NULL,
    p_den_trai_tu_ngay      IN VARCHAR2  DEFAULT NULL,
    p_den_trai_den_ngay     IN VARCHAR2  DEFAULT NULL,
    p_phan_doi_id           IN NUMBER    DEFAULT NULL,  -- DM_PHAN_DOIS.ID
    p_phan_trai_id          IN NUMBER    DEFAULT NULL,  -- DM_PHAN_TRAIS.ID
    p_ra_trai_tu_ngay       IN VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY — THA_NGAY_HET_HAN >=
    p_ra_trai_den_ngay      IN VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY — THA_NGAY_HET_HAN <=
    p_so_ban_an             IN NVARCHAR2 DEFAULT NULL,  -- PN_THI_HANH_AN.THA_SO_BAN_AN
    p_so_qd_tha             IN NVARCHAR2 DEFAULT NULL,  -- PN_THI_HANH_AN.THA_SO_QD_THA
    p_ma_an_phat            IN NVARCHAR2 DEFAULT NULL,  -- PN_LAI_LICH_CHI_TIET_RT.THA_MA_AN_PHAT, kh?p ?úng (=)
    p_trinh_do_hoc_van_id   IN NUMBER    DEFAULT NULL,  -- PN_LAI_LICH_CHI_TIET_RT.LL_DM_HOC_VAN_ID
    p_like_dash             IN NVARCHAR2 DEFAULT NULL,
    p_dash_loai_tk          IN NUMBER    DEFAULT NULL,
        -- 1: S? ph?m nhân tháng tr??c chuy?n sang (??u k?)
        -- 2: S? t?ng trong tháng
        -- 3: S? gi?m trong tháng
        -- 4: ?ang ch?p hành án (Cu?i k?)
    p_stt_tong_hop          IN NUMBER    DEFAULT NULL,
        -- 1 ??n 16 t??ng ?ng v?i STT trong V_TK_TONG_HOP_TINH_TRANG_DASHBOARD

    p_maxresultcount        IN NUMBER    DEFAULT 25,
    p_skipcount             IN NUMBER    DEFAULT 0,
    p_sort                  IN NVARCHAR2 DEFAULT NULL,
        -- 'HOTEN'|'NGAYSINH'|'NGAYBAT'|'NGAYHETHAN'|'ANPHAT'|'SOHSLD'|'TOIDANH'|'NGAYDENTRAI' + ' ASC'|' DESC' (vd N'NGAYSINH DESC').
        -- NULL ho?c giá tr? không h?p l? = m?c ??nh HO_TEN_ORDER ASC, PHAM_NHAN_ID DESC.
        -- C? tình KHÔNG dùng dynamic SQL: SQL text luôn c? ??nh (whitelist qua CASE WHEN)
        -- ?? không phá v? FIRST_ROWS(100) plan / gây hard parse theo t?ng giá tr? sort (xem comment filtered_prep).
    p_include_deleted       IN NUMBER    DEFAULT 0

) AS
    v_skip        NUMBER;
    v_limit       NUMBER;
    v_ngay_xet    DATE;
    v_like_ngaysinh VARCHAR2(4000);
    v_ngay_bat    DATE;
    v_den_trai_tu_ngay    DATE;
    v_den_trai_den_ngay   DATE;
    v_het_an_tu_ngay      DATE;
    v_het_an_den_ngay     DATE;
    v_like_so_ban_an      VARCHAR2(4000);
    v_like_so_qd_tha      VARCHAR2(4000);
    v_like_hoten  VARCHAR2(4000);
    v_like_cccd   VARCHAR2(4000);
    v_like_hs     VARCHAR2(4000);
    v_toi_danh_id NUMBER;
    v_like_dktt   VARCHAR2(4000);
    v_like_cu_tru VARCHAR2(4000);
    v_like_bo     VARCHAR2(4000);
    v_like_me     VARCHAR2(4000);
    v_like_vc     VARCHAR2(4000);
    v_like_dash   VARCHAR2(4000);
    v_dash_tu_ngay TIMESTAMP;
    v_dash_den_ngay TIMESTAMP;
    v_dash_ngay_xet DATE;              -- LEAST(DEN_NGAY, SYSDATE) — ??ng b? NGAY_XET SP_TK_THANG
    v_dash_ngay_xet_exclusive DATE;    -- NGAY_XET + 1 giây — kh?p biên k? dashboard
    v_text_filter_cnt    NUMBER;
    v_address_filter_cnt NUMBER;
    v_tha_filter_cnt     NUMBER;
    v_tn_filter_cnt      NUMBER;  -- filter thân nhân (b?/m?/v? ch?ng) — tham gia scope-count nh? text/??a ch?/THA
    v_ll_trai_giam_id    NUMBER;  -- resolve TG_MA ? ID ?? partition prune PN_LAI_LICH_CHI_TIET_RT
    v_sort_upper  VARCHAR2(100);  -- p_sort chu?n hoá 'FIELD ASC'/'FIELD DESC', ??i chi?u whitelist b?ng CASE WHEN (static SQL)
    v_sort_toi_danh NUMBER;       -- 1 khi p_sort là TOIDANH ASC/DESC; ch? khi ?ó m?i resolve tên t?i danh
    v_sort_ngaysinh NUMBER;       -- 1 khi sort NGAYSINH — m?i parse LL_NGAY_SINH (REGEXP) trên t?p ?ã l?c
    v_sort_anphat   NUMBER;       -- 1 khi sort ANPHAT — m?i mang THA_AN_PHAT vào temp sort
    v_sort_sohsld   NUMBER;       -- 1 khi sort SOHSLD — m?i mang s? h? s? vào temp sort
    c1            SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    v_sort_upper := UPPER(TRIM(NVL(p_sort, '')));
    v_sort_toi_danh := CASE
        WHEN v_sort_upper IN ('TOIDANH ASC', 'TOIDANH DESC') THEN 1
        ELSE 0
    END;
    v_sort_ngaysinh := CASE
        WHEN v_sort_upper IN ('NGAYSINH ASC', 'NGAYSINH DESC') THEN 1
        ELSE 0
    END;
    v_sort_anphat := CASE
        WHEN v_sort_upper IN ('ANPHAT ASC', 'ANPHAT DESC') THEN 1
        ELSE 0
    END;
    v_sort_sohsld := CASE
        WHEN v_sort_upper IN ('SOHSLD ASC', 'SOHSLD DESC') THEN 1
        ELSE 0
    END;

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL
       AND TRIM(p_ma_trai_giam) IS NOT NULL
    THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                v_ll_trai_giam_id := NULL;
        END;
    END IF;

    v_ngay_xet := TRUNC(SYSDATE);

    IF p_ngay_sinh IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ngay_sinh))) > 0 THEN
        v_like_ngaysinh := '%' || TRIM(TO_CHAR(p_ngay_sinh)) || '%';
    ELSE
        v_like_ngaysinh := NULL;
    END IF;

    IF p_ngay_bat IS NULL OR TRIM(p_ngay_bat) = '' THEN
        v_ngay_bat := NULL;
    ELSE
        -- DEFAULT NULL ON CONVERSION ERROR: input sai ??nh d?ng/ngày không h?p l? (vd tháng 13) thì b? qua filter thay vì ORA-01843 s?p c? tìm ki?m
        v_ngay_bat := TRUNC(TO_DATE(TRIM(p_ngay_bat) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY'));
    END IF;

    IF TO_NUMBER(TO_CHAR(SYSDATE, 'DD')) < 15 THEN
        v_dash_tu_ngay  := ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1) + 14;
        v_dash_den_ngay := TRUNC(SYSDATE, 'MM') + 13;
    ELSE
        v_dash_tu_ngay  := TRUNC(SYSDATE, 'MM') + 14;
        v_dash_den_ngay := ADD_MONTHS(TRUNC(SYSDATE, 'MM'), 1) + 13;
    END IF;
    v_dash_ngay_xet := LEAST(TRUNC(CAST(v_dash_den_ngay AS DATE)), TRUNC(SYSDATE));
    v_dash_ngay_xet_exclusive := v_dash_ngay_xet + (1 / 86400);

    -- Cache T1 (ngày tr??c v_dash_tu_ngay) ch? ???c ??c b?i guard giam_ids khi p_dash_loai_tk = 3.
    -- SP_ENSURE idempotent theo NGAY_XET; g?i m?i l?n tìm ki?m ch? t?n công mà không ??i cursor.
    IF p_dash_loai_tk = 3 THEN
        QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(TRUNC(CAST(v_dash_tu_ngay AS DATE)) - 1);
    END IF;

     IF p_den_trai_tu_ngay IS NULL OR TRIM(p_den_trai_tu_ngay) = '' THEN
        v_den_trai_tu_ngay := NULL;
    ELSE
        v_den_trai_tu_ngay := TRUNC(TO_DATE(TRIM(p_den_trai_tu_ngay) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY'));
    END IF;

     IF p_den_trai_den_ngay IS NULL OR TRIM(p_den_trai_den_ngay) = '' THEN
        v_den_trai_den_ngay := NULL;
    ELSE
        v_den_trai_den_ngay := TRUNC(TO_DATE(TRIM(p_den_trai_den_ngay) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY'));
    END IF;

    IF p_ra_trai_tu_ngay IS NULL OR TRIM(p_ra_trai_tu_ngay) = '' THEN
        v_het_an_tu_ngay := NULL;
    ELSE
        v_het_an_tu_ngay := TRUNC(TO_DATE(TRIM(p_ra_trai_tu_ngay) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY'));
    END IF;

    IF p_ra_trai_den_ngay IS NULL OR TRIM(p_ra_trai_den_ngay) = '' THEN
        v_het_an_den_ngay := NULL;
    ELSE
        v_het_an_den_ngay := TRUNC(TO_DATE(TRIM(p_ra_trai_den_ngay) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY'));
    END IF;

    IF p_so_ban_an IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_so_ban_an))) > 0 THEN
        v_like_so_ban_an := '%' || UPPER(TRIM(TO_CHAR(NVL(p_so_ban_an, u'')))) || '%';
    ELSE
        v_like_so_ban_an := NULL;
    END IF;

    IF p_so_qd_tha IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_so_qd_tha))) > 0 THEN
        v_like_so_qd_tha := '%' || UPPER(TRIM(TO_CHAR(NVL(p_so_qd_tha, u'')))) || '%';
    ELSE
        v_like_so_qd_tha := NULL;
    END IF;

    IF p_ho_ten IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ho_ten))) > 0 THEN
        v_like_hoten := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ho_ten, u''))))) ;
    ELSE
        v_like_hoten := NULL;
    END IF;

    -- LL_CCCD / LL_SO_HO_SO_LAN_DAU là chu?i s? ? LIKE th?ng trên c?t,
    -- không qua FN_NORMALIZE_VN (kh?p composite index IX_PN_LLCT_RT_CCCD / _SOHS)
    IF p_cccd IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_cccd))) > 0 THEN
        v_like_cccd := '%' || TRIM(TO_CHAR(NVL(p_cccd, u''))) || '%';
    ELSE
        v_like_cccd := NULL;
    END IF;

    IF p_so_hsld IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_so_hsld))) > 0 THEN
        v_like_hs := '%' || TRIM(TO_CHAR(NVL(p_so_hsld, u''))) || '%';
    ELSE
        v_like_hs := NULL;
    END IF;

    IF p_like_dash IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_like_dash))) > 0 THEN
        v_like_dash := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_like_dash, u''))))) || '%';
    ELSE
        v_like_dash := NULL;
    END IF;

    v_toi_danh_id := p_toi_danh;

    IF p_noi_dang_ky_tt IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_noi_dang_ky_tt))) > 0 THEN
        v_like_dktt := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_noi_dang_ky_tt, u''))))) || '%';
    ELSE
        v_like_dktt := NULL;
    END IF;

    IF p_ve_cu_tru IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ve_cu_tru))) > 0 THEN
        v_like_cu_tru := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ve_cu_tru, u''))))) || '%';
    ELSE
        v_like_cu_tru := NULL;
    END IF;

    IF p_ho_ten_bo IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ho_ten_bo))) > 0 THEN
        v_like_bo := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ho_ten_bo, u'')))));
    ELSE
        v_like_bo := NULL;
    END IF;

    IF p_ho_ten_me IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ho_ten_me))) > 0 THEN
        v_like_me := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ho_ten_me, u'')))));
    ELSE
        v_like_me := NULL;
    END IF;

    IF p_ho_ten_vo_chong IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ho_ten_vo_chong))) > 0 THEN
        v_like_vc := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ho_ten_vo_chong, u''))))) ;
    ELSE
        v_like_vc := NULL;
    END IF;

    v_text_filter_cnt :=
          CASE WHEN v_like_hoten IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_cccd IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_hs IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_dash IS NOT NULL THEN 1 ELSE 0 END;

    v_address_filter_cnt :=
          CASE WHEN v_like_dktt IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_cu_tru IS NOT NULL THEN 1 ELSE 0 END;

    v_tha_filter_cnt :=
          CASE
              WHEN v_toi_danh_id IS NOT NULL
                OR v_ngay_bat IS NOT NULL
                OR v_den_trai_tu_ngay IS NOT NULL
                OR v_den_trai_den_ngay IS NOT NULL
                OR v_het_an_tu_ngay IS NOT NULL
                OR v_het_an_den_ngay IS NOT NULL
                OR v_like_so_ban_an IS NOT NULL
                OR v_like_so_qd_tha IS NOT NULL
              THEN 1
              ELSE 0
          END;

    v_tn_filter_cnt :=
          CASE WHEN v_like_bo IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_me IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_vc IS NOT NULL THEN 1 ELSE 0 END;

    OPEN c1 FOR
    WITH
    -- ===== Priority 1/2: Pre-compute ID sets cho p_dash_loai_tk — thay correlated EXISTS/FN per-row =====

    -- Pre-compute valid trai IDs — thay 3 EXISTS correlated trên DM_TRAI_GIAMS b?ng 1 hash lookup
    -- FIX 2026-08-22: thêm TG_MA_DD_DT IS NOT NULL — lo?i các "tr?i" gi?/gán nh?m trong
    -- DM_TRAI_GIAMS (tr?i t?m giam t?nh khác..., vd ID 90680/95360/98409), kh?p ?úng ?i?u ki?n
    -- DS_TRAI c?a SP_QLPN_GET_TK_THANG_DASHBOARD và dm_tg c?a V_TK_TONG_HOP_TINH_TRANG_DASHBOARD
    -- — n?u không, danh sách drill-down t? dashboard s? có nhi?u h?n s? t?ng ?ã hi?n th?.
    valid_trai_ids AS (
        SELECT /*+ MATERIALIZE */ ID
        FROM QLPN.DM_TRAI_GIAMS
        WHERE NVL(IS_DELETED, 0) = 0
--          AND TG_MA_DD_DT IS NOT NULL 
    ),
    -- TOI_DANH_DAU_TIEN trên RT là ID t?i danh (vd '878'), KHÔNG ph?i tên — resolve tên qua DM nh? (1747 dòng)
    -- ?? p_sort=TOIDANH s?p x?p theo tên (alphabet), không ph?i theo chu?i ID
    dm_toi_danh_ten AS (
        -- TRIM: ~40% DM_TOI_DANHS.TD_TEN có kho?ng tr?ng/tab ??u chu?i không ??ng nh?t,
        -- ?? nguyên s? làm sai th? t? alphabet khi sort theo tên
        SELECT /*+ MATERIALIZE */ ID, TRIM(TD_TEN) AS TD_TEN
        FROM QLPN.DM_TOI_DANHS
        WHERE v_sort_toi_danh = 1
          AND NVL(IS_DELETED, 0) = 0
    ),
    -- Tr?ng thái hôm nay t? cache — thay toàn b? DM_TINH_TRANG_PHAM_NHANS join per-row
    -- cho loai_tk=4, p_stt_tong_hop 1-10 và driver_rows (hash join O(1) thay scalar FN)
    cache_today AS (
        SELECT /*+ MATERIALIZE */ PN_LAI_LICH_ID, TTPN_MA
          FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE
         -- v_dash_ngay_xet (= LEAST(k? hi?n hành.den_ngay, SYSDATE)) là "ngày xét" ?úng c?a k? —
         -- s?a 2026-08-13 t? TRUNC(SYSDATE): 2 giá tr? LUÔN trùng nhau v?i logic k? hi?n t?i (k?
         -- luôn tính t? SYSDATE nên den_ngay luôn >= hôm nay), nh?ng ph?i tham chi?u ?úng bi?n k?
         -- ?? không âm th?m sai n?u sau này b? sung tham s? hoá k? (p_thang/p_nam) cho SP này —
         -- xem "Not in scope" trong k? ho?ch h?p nh?t TANG/GIAM.
         WHERE NGAY_XET = v_dash_ngay_xet
           -- TTPN_MA ch? ???c ??c khi loai_tk=4 ho?c stt_tong_hop 1-10 (11-16 dùng EXISTS riêng,
           -- 7 ch? dùng ngày) — path khác ?? CTE r?ng, kh?i materialize 1.5M dòng vô ích
           AND (p_dash_loai_tk = 4 OR (p_stt_tong_hop IS NOT NULL AND p_stt_tong_hop <= 10))
    ),
    -- Ch? c?t c?n dùng — tránh materialize RT.* (THA_TOI_DANH_NAMES 16KB × 1.5M ? temp kh?ng l?)
    rt_trai AS (
        SELECT /*+ MATERIALIZE */
            RT.PHAM_NHAN_ID,
            RT.IS_DELETED,
            RT.LL_TRAI_GIAM_ID,
            RT.HO_TEN_ORDER,
            RT.LL_PHAN_DOI_ID,
            RT.LL_PHAN_TRAI_ID,
            -- C?t text/??a ch? (LL_CCCD, LL_DIA_CHI_*, LL_NOI_THA_VE_*) ?ã b?:
            -- các candidate CTE ??c RT g?c tr?c ti?p, gi? ? ?ây ch? t?n temp write khi materialize.
            -- LL_SO_HO_SO_LAN_DAU (VARCHAR2 50) gi? làm sort key SOHSLD.
            -- TOI_DANH_DAU_TIEN là ID (vd '878'), không ph?i tên. Tên ch? resolve ? driver_rows
            -- khi v_sort_toi_danh = 1 — tránh TO_NUMBER + join DM trên toàn b? rt_trai.
            RT.LL_SO_HO_SO_LAN_DAU,
            RT.LL_NGAY_SINH,
            RT.LL_TINH_TRANG_ID,
            RT.LL_DM_GIOI_TINH_ID,
            RT.LL_DM_DAN_TOC_ID,
            RT.LL_DM_QUOC_TICH_ID,
            RT.LL_DM_TON_GIAO_ID,
            RT.LL_DM_HOC_VAN_ID,
            RT.THA_ID,
            RT.THA_DOI_TUONG,
            RT.THA_NGAY_BAT,
            RT.THA_NGAY_DEN_TRAI,
            RT.THA_NGAY_HET_HAN,
            RT.THA_AN_PHAT,
            RT.THA_MA_AN_PHAT,
            RT.TOI_DANH_DAU_TIEN
          FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
         WHERE (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
           AND RT.LL_TRAI_GIAM_ID IS NOT NULL
           AND RT.LL_TRAI_GIAM_ID IN (SELECT ID FROM valid_trai_ids)
           AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
           -- PERF: rt_trai ch? ph?c v? tang/giam (loai 2, 3) và ?ang ch?p hành (loai 4).
           -- ??u k? (loai 1) ??c PN_TK_THANG_DAU_KY_IDS r?i PK-join RT.
           -- Li?t kê th??ng ??c RT g?c m?t l?n ? driver_rows nhánh (c) — không copy thêm 3.15M dòng vào temp.
           AND p_dash_loai_tk IN (2, 3, 4)
    ),
    -- KHÔNG dùng QLPN.FN_PN_TANG_GIAM_TRONG_KY (ngu?n dùng chung c?a 2 SP dashboard — xem
    -- docs/reports/QLPN/Dashboard/FN_PN_TANG_GIAM_TRONG_KY.sql) ? ?ây: ?ã ki?m ch?ng b?ng th?c
    -- nghi?m là TABLE(FN_PN_TANG_GIAM_TRONG_KY(...)) gây ORA-43907 ("This argument must be a
    -- literal or bind variable") khi CTE d?a trên nó ???c UNION cùng các nhánh có hint
    -- CARDINALITY(...) khác bên trong dash_eligible_ids, trong ng? c?nh OPEN c1 FOR — không tái
    -- hi?n ???c khi tách riêng t?ng ph?n, ch? x?y ra v?i ?úng t? h?p này trên Oracle instance
    -- hi?n t?i. Do ?ó gi? nguyên cách vi?t tr?c ti?p (UNION) nh? tr??c, nh?ng ÁP D?NG ?ÚNG fix
    -- nghi?p v? ?ã ??a vào FN_PN_TANG_GIAM_TRONG_KY: b? 2 nhánh CHUA_BENH_BAT_BUOCS (b?t bu?c
    -- ch?a b?nh, mã 113, cùng nhóm "?ang ch?p hành" v?i 111/112/114) kh?i c? t?ng l?n gi?m —
    -- theo tài li?u quy ??nh m?c 10, chuy?n ??i n?i b? nhóm không ???c tính là t?ng/gi?m.
    tang_ids AS (
        SELECT /*+ MATERIALIZE CARDINALITY(tang_union 5000) */ ID FROM (
        SELECT RT.PHAM_NHAN_ID AS ID
        FROM rt_trai RT
        JOIN QLPN.DM_LOAI_DOI_TUONGS LDT ON LDT.ID = RT.THA_DOI_TUONG AND NVL(LDT.IS_DELETED, 0) = 0
        WHERE p_dash_loai_tk = 2
          AND RT.THA_NGAY_DEN_TRAI >= v_dash_tu_ngay
          AND RT.THA_NGAY_DEN_TRAI < v_dash_ngay_xet_exclusive
          AND LDT.LDT_MA IN ('20211', '20212', '110', '120', '20221', '20324')
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.TRON_TRAIS TT
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TT.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND TT.NGAY_BAT_LAI >= v_dash_tu_ngay
          AND TT.NGAY_BAT_LAI < v_dash_ngay_xet_exclusive
          AND CAST(TT.NGAY_BAT_LAI AS DATE) >= CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND NVL(TT.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.TAM_DINH_CHIS TDC
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TDC.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND TDC.NGAY_LAI >= v_dash_tu_ngay
          AND TDC.NGAY_LAI < v_dash_ngay_xet_exclusive
          AND CAST(TDC.NGAY_TDC AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND TDC.LOAI_QUYET_DINH_ID = 1
          AND NVL(TDC.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.TRICH_XUATS TX
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TX.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND TX.TX_NGAY_TRA >= v_dash_tu_ngay
          AND TX.TX_NGAY_TRA < v_dash_ngay_xet_exclusive
          AND CAST(TX.TX_NGAY_TRICH_XUAT AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND TX.TX_LOAI_LENH_ID = 1
          AND NVL(TX.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.HUY_ANS HA
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = HA.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND HA.NGAY_TRO_LAI >= v_dash_tu_ngay
          AND HA.NGAY_TRO_LAI < v_dash_ngay_xet_exclusive
          AND CAST(HA.NGAY_TRA_TU_DO AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND NVL(HA.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.THA_CO_DIEU_KIENS TCK
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TCK.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND TCK.NGAY_BAT_LAI >= v_dash_tu_ngay
          AND TCK.NGAY_BAT_LAI < v_dash_ngay_xet_exclusive
          AND NVL(TCK.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
        ) tang_union
    ),
    -- 0 dòng khi không ph?i dashboard gi?m. LEADING + USE_NL: nested loop không probe b?ng
    -- s? ki?n khi c?ng r?ng (cursor dùng chung m?i p_dash_loai_tk, không ???c full scan ? path tìm ki?m).
    giam_gate AS (
        SELECT /*+ MATERIALIZE */ 1 AS ok
          FROM dual
         WHERE p_dash_loai_tk = 3
    ),
    -- Cùng v? t? v?i OR EXISTS (6 nhánh UNION ALL) t?ng g?n trên t?ng dòng giam.
    -- Tính 1 l?n khi loai_tk = 3. ANY_DEN = 1: nhánh không ph? thu?c THA_NGAY_DEN_TRAI
    -- (??n tr?i m?i / b?t l?i tha có ?i?u ki?n). ANY_DEN = 0: ch? kh?p ?úng dòng rt_trai
    -- có THA_NGAY_DEN_TRAI ?ã th?a so sánh ngày c?a nhánh ?ó.
    -- Nhánh ??n-tr?i quét RT g?c (không rt_trai) vì EXISTS c? kh?p m?i dòng cùng PHAM_NHAN_ID.
    tang_guard_ids AS (
        SELECT /*+ MATERIALIZE */ ID, DEN_TRAI, ANY_DEN
          FROM (
            SELECT /*+ LEADING(g) USE_NL(TT2) USE_NL(RT) */ TT2.PHAM_NHAN_ID AS ID,
                   RT.THA_NGAY_DEN_TRAI AS DEN_TRAI,
                   0 AS ANY_DEN
              FROM giam_gate g
              JOIN QLPN.TRON_TRAIS TT2 ON g.ok = 1
              JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TT2.PHAM_NHAN_ID
             WHERE TT2.NGAY_BAT_LAI >= v_dash_tu_ngay
               AND TT2.NGAY_BAT_LAI < v_dash_ngay_xet_exclusive
               AND CAST(TT2.NGAY_BAT_LAI AS DATE) >= CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
               AND NVL(TT2.IS_DELETED, 0) = 0
            UNION
            SELECT /*+ LEADING(g) USE_NL(TDC2) USE_NL(RT) */ TDC2.PHAM_NHAN_ID,
                   RT.THA_NGAY_DEN_TRAI,
                   0
              FROM giam_gate g
              JOIN QLPN.TAM_DINH_CHIS TDC2 ON g.ok = 1
              JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TDC2.PHAM_NHAN_ID
             WHERE TDC2.NGAY_LAI >= v_dash_tu_ngay
               AND TDC2.NGAY_LAI < v_dash_ngay_xet_exclusive
               AND CAST(TDC2.NGAY_TDC AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
               AND TDC2.LOAI_QUYET_DINH_ID = 1
               AND NVL(TDC2.IS_DELETED, 0) = 0
            UNION
            SELECT /*+ LEADING(g) USE_NL(TX2) USE_NL(RT) */ TX2.PHAM_NHAN_ID,
                   RT.THA_NGAY_DEN_TRAI,
                   0
              FROM giam_gate g
              JOIN QLPN.TRICH_XUATS TX2 ON g.ok = 1
              JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TX2.PHAM_NHAN_ID
             WHERE TX2.TX_NGAY_TRA >= v_dash_tu_ngay
               AND TX2.TX_NGAY_TRA < v_dash_ngay_xet_exclusive
               AND CAST(TX2.TX_NGAY_TRICH_XUAT AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
               AND TX2.TX_LOAI_LENH_ID = 1
               AND NVL(TX2.IS_DELETED, 0) = 0
            UNION
            SELECT /*+ LEADING(g) USE_NL(HA2) USE_NL(RT) */ HA2.PHAM_NHAN_ID,
                   RT.THA_NGAY_DEN_TRAI,
                   0
              FROM giam_gate g
              JOIN QLPN.HUY_ANS HA2 ON g.ok = 1
              JOIN rt_trai RT ON RT.PHAM_NHAN_ID = HA2.PHAM_NHAN_ID
             WHERE HA2.NGAY_TRO_LAI >= v_dash_tu_ngay
               AND HA2.NGAY_TRO_LAI < v_dash_ngay_xet_exclusive
               AND CAST(HA2.NGAY_TRA_TU_DO AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
               AND NVL(HA2.IS_DELETED, 0) = 0
            UNION
            SELECT /*+ LEADING(g) USE_NL(RT2) USE_NL(LDT2) */ RT2.PHAM_NHAN_ID,
                   NULL,
                   1
              FROM giam_gate g
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT2 ON g.ok = 1
              JOIN QLPN.DM_LOAI_DOI_TUONGS LDT2
                ON LDT2.ID = RT2.THA_DOI_TUONG
               AND NVL(LDT2.IS_DELETED, 0) = 0
             WHERE RT2.THA_NGAY_DEN_TRAI >= v_dash_tu_ngay
               AND RT2.THA_NGAY_DEN_TRAI < v_dash_ngay_xet_exclusive
               AND LDT2.LDT_MA IN ('20211', '20212', '110', '120', '20221', '20324')
               AND NVL(RT2.IS_DELETED, 0) = 0
               AND RT2.THA_ID IS NOT NULL
            UNION
            SELECT /*+ LEADING(g) USE_NL(TCK2) */ TCK2.PHAM_NHAN_ID,
                   NULL,
                   1
              FROM giam_gate g
              JOIN QLPN.THA_CO_DIEU_KIENS TCK2 ON g.ok = 1
             WHERE TCK2.NGAY_BAT_LAI >= v_dash_tu_ngay
               AND TCK2.NGAY_BAT_LAI < v_dash_ngay_xet_exclusive
               AND NVL(TCK2.IS_DELETED, 0) = 0
          )
    ),
    giam_ids AS (
        SELECT /*+ MATERIALIZE CARDINALITY(giam_union 5000) */ ID FROM (
        SELECT TT.PHAM_NHAN_ID AS ID
        FROM QLPN.TRON_TRAIS TT
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TT.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND TT.NGAY_TRON >= v_dash_tu_ngay
          AND TT.NGAY_TRON < v_dash_ngay_xet_exclusive
          AND CAST(TT.NGAY_TRON AS DATE) >= CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND NVL(TT.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT KC.KTC_PN_LAI_LICH_ID
        FROM QLPN.PN_KET_THUC_CHETS KC
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = KC.KTC_PN_LAI_LICH_ID
        LEFT JOIN QLPN.DM_TRUONG_HOP_CHETS THC ON THC.ID = KC.KTC_DM_TRUONG_HOP_CHET_ID
        WHERE p_dash_loai_tk = 3
          AND KC.KTC_NGAY_CHET >= v_dash_tu_ngay
          AND KC.KTC_NGAY_CHET < v_dash_ngay_xet_exclusive
          AND CAST(KC.KTC_NGAY_CHET AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND NVL(THC.THC_MA, '10') NOT IN ('30', '40', '50')
          AND NVL(KC.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT TX.PHAM_NHAN_ID
        FROM QLPN.TRICH_XUATS TX
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TX.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND TX.TX_NGAY_TRICH_XUAT >= v_dash_tu_ngay
          AND TX.TX_NGAY_TRICH_XUAT < v_dash_ngay_xet_exclusive
          AND TX.TX_LOAI_LENH_ID = 1
          AND NVL(TX.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
        UNION
        SELECT TDC.PHAM_NHAN_ID
        FROM QLPN.TAM_DINH_CHIS TDC
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TDC.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND TDC.NGAY_TDC >= v_dash_tu_ngay
          AND TDC.NGAY_TDC < v_dash_ngay_xet_exclusive
          AND CAST(TDC.NGAY_TDC AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND TDC.LOAI_QUYET_DINH_ID = 1
          AND NVL(TDC.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
          AND RT.THA_ID IS NOT NULL
        -- Chuy?n tr?i n?i b? C10 (PHAM_NHAN_CHUYEN_TRAI) KHÔNG ??a vào giam_ids: ??ng b? v?i
        -- 2 SP dashboard ?ã b? GIAM_14 kh?i GIAM_TRONG_THANG/GIAM_TRONG_NAM.
        -- Tr?i NGU?N cho s? ki?n "tr?i giam khác chuy?n ??n" (LDT_MA=20221, tang_ids nhánh ??u) —
        -- ??ng b? GIAM_17_NOI_BO_IDS trong FN_PN_TANG_GIAM_TRONG_KY (thêm 2026-08-20). KHÔNG dùng
        -- rt_trai (?ã l?c theo tr?i HI?N T?I = ?ích, không ph?i ngu?n) — join l?i RT tr?c ti?p và
        -- l?c tr?i ngu?n qua p_ma_trai_giam. TG_MA_DD_DT IS NOT NULL: ch? nh?n tr?i C10 th?t.
        UNION
        SELECT RT3.PHAM_NHAN_ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT3
        JOIN QLPN.DM_LOAI_DOI_TUONGS LDT3 ON LDT3.ID = RT3.THA_DOI_TUONG AND NVL(LDT3.IS_DELETED, 0) = 0
        JOIN QLPN.DM_TRAI_GIAMS TG_NGUON ON TG_NGUON.ID = RT3.THA_CHUYEN_DEN_TU_ID
                                         AND NVL(TG_NGUON.IS_DELETED, 0) = 0
                                         AND TG_NGUON.TG_MA_DD_DT IS NOT NULL
        WHERE p_dash_loai_tk = 3
          AND RT3.THA_NGAY_DEN_TRAI >= v_dash_tu_ngay
          AND RT3.THA_NGAY_DEN_TRAI < v_dash_ngay_xet_exclusive
          AND LDT3.LDT_MA = '20221'
          AND NVL(RT3.IS_DELETED, 0) = 0
          AND RT3.THA_ID IS NOT NULL
          AND (v_ll_trai_giam_id IS NULL OR TG_NGUON.ID = v_ll_trai_giam_id)
        UNION
        SELECT HA.PHAM_NHAN_ID
        FROM QLPN.HUY_ANS HA
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = HA.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND HA.NGAY_TRA_TU_DO >= v_dash_tu_ngay
          AND HA.NGAY_TRA_TU_DO < v_dash_ngay_xet_exclusive
          AND NVL(HA.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
          AND HA.PHAM_NHAN_ID NOT IN (
                SELECT TX.PHAM_NHAN_ID
                FROM QLPN.TRICH_XUATS TX
                WHERE TX.TX_LOAI_LENH_ID = 1
                  AND (TX.TX_NGAY_TRA IS NULL
                       OR TX.TX_NGAY_TRA >= v_dash_ngay_xet_exclusive))
        UNION
        SELECT HTHA.PHAM_NHAN_ID
        FROM QLPN.HOAN_THI_HANH_ANS HTHA
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = HTHA.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND HTHA.NGAY_HOAN >= v_dash_tu_ngay
          AND HTHA.NGAY_HOAN < v_dash_ngay_xet_exclusive
          AND NVL(HTHA.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
        UNION
        SELECT MHP.PN_LAI_LICH_ID
        FROM QLPN.MIEN_HINH_PHATS MHP
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = MHP.PN_LAI_LICH_ID
        WHERE p_dash_loai_tk = 3
          AND MHP.MHP_NGAY_TU_DO >= v_dash_tu_ngay
          AND MHP.MHP_NGAY_TU_DO < v_dash_ngay_xet_exclusive
          AND NVL(MHP.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
        UNION
        SELECT CG.PNCG_LAI_LICH_ID
        FROM QLPN.PN_CHUYEN_GIAO CG
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = CG.PNCG_LAI_LICH_ID
        LEFT JOIN QLPN.DM_QUOC_TICHS QT ON QT.ID = CG.PNCG_NUOC_CHUYEN_GIAO_ID
        WHERE p_dash_loai_tk = 3
          AND CG.PNCG_NGAY_CHUYEN_GIAO >= v_dash_tu_ngay
          AND CG.PNCG_NGAY_CHUYEN_GIAO < v_dash_ngay_xet_exclusive
          AND NVL(QT.QT_MA, '000') <> '250'
          AND NVL(CG.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
        -- Ra tr?i (không rõ lý do c? th?): dùng THA_NGAY_HET_HAN (?ã có s?n trên rt_trai)
        -- thay vì PN_KET_THUC_RA_TRAIS — ??ng b? SP_QLPN_GET_TK_THANG_DASHBOARD.GIAM_RA_TRAI_IDS
        -- và SP_CALC_TINH_TRANG_PHAM_NHAN.het_han_calc.
        -- GUARD (2026-08-13, ??ng b? FN_PN_TANG_GIAM_TRONG_KY.GIAM_RA_TRAI_IDS): PN ph?i ?ang/?ã
        -- ? nhóm 111-114 trong k? m?i tính là gi?m — tránh ??m th?a PN v?n ?ã ? ngoài nhóm t?
        -- tr??c (vd trích xu?t 141->146, không ph?i r?i "?ang ch?p hành"). ?i?u ki?n là T1 (ngày
        -- tr??c k?) HO?C có s? ki?n TANG trong CHÍNH k? này (PN vào gi?a k?, T1 không b?t ???c —
        -- b?n ??u ch? guard b?ng T1 làm m?t luôn các tr??ng h?p vào-r?i-ra h?p l? trong cùng k?).
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM rt_trai RT
        WHERE p_dash_loai_tk = 3
          AND RT.THA_NGAY_HET_HAN >= v_dash_tu_ngay
          AND RT.THA_NGAY_HET_HAN < v_dash_ngay_xet_exclusive
          AND RT.THA_ID IS NOT NULL
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
          AND (
              EXISTS (
                  SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                   WHERE ctt.PN_LAI_LICH_ID = RT.PHAM_NHAN_ID
                     AND ctt.NGAY_XET = TRUNC(CAST(v_dash_tu_ngay AS DATE)) - 1
                     AND ctt.TTPN_MA IN ('111', '112', '113', '114')
              )
              OR EXISTS (
                  SELECT 1 FROM tang_guard_ids g
                   WHERE g.ID = RT.PHAM_NHAN_ID
                     AND (g.ANY_DEN = 1 OR g.DEN_TRAI = RT.THA_NGAY_DEN_TRAI)
              )
          )
        -- Chuy?n tr?i khác (mã TTPN 161) — ??ng b?
        -- FN_PN_TANG_GIAM_TRONG_KY.GIAM_16_CHUYEN_TRAI_KHAC_IDS. Tr??c ?ây không nhánh GIAM nào
        -- b?t tr??ng h?p này (khác GIAM_14 chuy?n tr?i N?I B? C10 ?ã b? lo?i b? theo fix sáng
        -- 2026-08-13 — ?i?u ki?n ? ?ây ??ng nh?t 1-1 v?i logic gán mã 161 trong
        -- FN_TINH_TRANG_PN_TAI_NGAY.cand nên không có r?i ro double-count v?i tang_ids). Guard T1
        -- HO?C TANG trong k? gi?ng h?t nhánh GIAM_RA_TRAI ? trên.
        UNION
        SELECT CT.PNCT_LAI_LICH_ID
        FROM QLPN.PHAM_NHAN_CHUYEN_TRAI CT
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = CT.PNCT_LAI_LICH_ID
        LEFT JOIN QLPN.DM_TRUONG_HOP_CHUYEN_TRAIS THCT ON THCT.ID = CT.PNCT_TRUONG_HOP_CHUYEN_ID
        WHERE p_dash_loai_tk = 3
          AND CT.PNCT_NGAY_CHUYEN >= v_dash_tu_ngay
          AND CT.PNCT_NGAY_CHUYEN < v_dash_ngay_xet_exclusive
          AND (THCT.THCT_MA <> '50' OR THCT.THCT_MA IS NULL)
          AND NVL(CT.IS_DELETED, 0) = 0
          AND (
              EXISTS (
                  SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                   WHERE ctt.PN_LAI_LICH_ID = CT.PNCT_LAI_LICH_ID
                     AND ctt.NGAY_XET = TRUNC(CAST(v_dash_tu_ngay AS DATE)) - 1
                     AND ctt.TTPN_MA IN ('111', '112', '113', '114')
              )
              OR EXISTS (
                  SELECT 1 FROM tang_guard_ids g
                   WHERE g.ID = CT.PNCT_LAI_LICH_ID
                     AND (g.ANY_DEN = 1 OR g.DEN_TRAI = RT.THA_NGAY_DEN_TRAI)
              )
          )
        UNION
        SELECT DX.PNLAI_LICH_ID
        FROM QLPN.PN_DAC_XAS DX
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = DX.PNLAI_LICH_ID
        WHERE p_dash_loai_tk = 3
          AND DX.DX_NGAY_THA >= v_dash_tu_ngay
          AND DX.DX_NGAY_THA < v_dash_ngay_xet_exclusive
          AND DX.DX_TINH_TRANG_DAC_XA IN ('1', '2', '7')
          AND NVL(DX.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
        UNION
        SELECT TCK.PHAM_NHAN_ID
        FROM QLPN.THA_CO_DIEU_KIENS TCK
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TCK.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND TCK.NGAY_THA >= v_dash_tu_ngay
          AND TCK.NGAY_THA < v_dash_ngay_xet_exclusive
          AND (TCK.NGAY_BAT_LAI IS NULL OR TCK.NGAY_BAT_LAI >= v_dash_ngay_xet_exclusive)
          AND NVL(TCK.IS_DELETED, 0) = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
        ) giam_union
    ),
    -- ??u k? (loai_tk=1) — ??c PN_TK_THANG_DAU_KY_IDS (pre-compute b?i SP_TK_THANG)
    dau_ky_ids AS (
        SELECT /*+ MATERIALIZE CARDINALITY(dau_ky_ids 500000) */ PHAM_NHAN_ID AS ID
        FROM QLPN.PN_TK_THANG_DAU_KY_IDS
        WHERE p_dash_loai_tk = 1
          AND TU_NGAY = TO_CHAR(CAST(v_dash_tu_ngay AS DATE), 'DD/MM/YYYY')
          AND DEN_NGAY = TO_CHAR(CAST(v_dash_den_ngay AS DATE), 'DD/MM/YYYY')
          AND (v_ll_trai_giam_id IS NULL OR MA_TRAI_GIAM = TRIM(p_ma_trai_giam))
    ),
    -- P0-1: Gom ID dashboard — drive hash join thay OR + full scan PN_LAI_LICHS
    dash_eligible_ids AS (
        SELECT /*+ MATERIALIZE CARDINALITY(dau_ky_ids 500000) */ ID FROM dau_ky_ids WHERE p_dash_loai_tk = 1
        UNION
        SELECT /*+ CARDINALITY(tang_ids 5000) */ ID FROM tang_ids WHERE p_dash_loai_tk = 2
        UNION
        SELECT /*+ CARDINALITY(giam_ids 5000) */ ID FROM giam_ids WHERE p_dash_loai_tk = 3
        UNION
        SELECT /*+ CARDINALITY(RT 500000) */ RT.PHAM_NHAN_ID AS ID
        FROM rt_trai RT
        JOIN cache_today c ON c.PN_LAI_LICH_ID = RT.PHAM_NHAN_ID
                          AND c.TTPN_MA IN ('111', '112', '113', '114')
        WHERE p_dash_loai_tk = 4
    ),
    -- FBI drive: ?u tiên INDEX_FFS trên composite FBI IX_PN_LLCT_RT_NORMHOTEN
    --   (norm_hoten, IS_DELETED, LL_TRAI_GIAM_ID, PHAM_NHAN_ID — DDL_COMPOSITE_FBI_TIM_KIEM_RT.sql):
    --   index-only, multiblock I/O, không g?i l?i FN_NORMALIZE_VN (function avalanche ~35s trên 3.15M).
    --   Hint INDEX trên FBI 1 c?t gi? làm fallback cho môi tr??ng ch?a ch?y DDL (hint index
    --   không t?n t?i s? t? b? b? qua) ? INDEX FULL SCAN + TABLE ACCESS BY ROWID, v?n tránh g?i UDF.
    hoten_candidate_ids AS (
        SELECT /*+ MATERIALIZE INDEX_FFS(RT IX_PN_LLCT_RT_NORMHOTEN) INDEX(RT IX_PN_LLCT_RT_FBI_HO_TEN) */ RT.PHAM_NHAN_ID AS ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
        WHERE v_like_hoten IS NOT NULL
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
          AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(RT.LL_HO_TEN)), 1, 400) LIKE v_like_hoten
    ),
    -- CCCD/s? HS: chu?i s? — LIKE th?ng trên c?t, composite index th??ng (không FBI, không UDF)
    cccd_candidate_ids AS (
        SELECT /*+ MATERIALIZE INDEX_FFS(RT IX_PN_LLCT_RT_CCCD) */ RT.PHAM_NHAN_ID AS ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
        WHERE v_like_cccd IS NOT NULL
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
          AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
          AND RT.LL_CCCD LIKE v_like_cccd
    ),
    so_hs_candidate_ids AS (
        SELECT /*+ MATERIALIZE INDEX_FFS(RT IX_PN_LLCT_RT_SOHS) */ RT.PHAM_NHAN_ID AS ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
        WHERE v_like_hs IS NOT NULL
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
          AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
          AND RT.LL_SO_HO_SO_LAN_DAU LIKE v_like_hs
    ),
    dash_text_candidate_ids AS (
        SELECT /*+ MATERIALIZE */ ID FROM (
            SELECT /*+ INDEX_FFS(RT IX_PN_LLCT_RT_SOHS) */ RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_dash IS NOT NULL
              AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              -- v_like_dash ?ã normalize; s? HS là chu?i s? nên normalize(input s?) = input s?
              AND RT.LL_SO_HO_SO_LAN_DAU LIKE v_like_dash
            UNION
            SELECT /*+ INDEX_FFS(RT IX_PN_LLCT_RT_CCCD) */ RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_dash IS NOT NULL
              AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              AND RT.LL_CCCD LIKE v_like_dash
            UNION
            SELECT /*+ INDEX_FFS(RT IX_PN_LLCT_RT_NORMHOTEN) INDEX(RT IX_PN_LLCT_RT_FBI_HO_TEN) */ RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_dash IS NOT NULL
              AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(RT.LL_HO_TEN)), 1, 400) LIKE v_like_dash
        )
    ),
    -- Giao các filter text (AND gi?a ho ten / cccd / so hs / dash)
    text_scope_ids AS (
        SELECT /*+ MATERIALIZE */ u.ID
        FROM (
            SELECT ID, 1 AS f FROM hoten_candidate_ids WHERE v_like_hoten IS NOT NULL
            UNION ALL
            SELECT ID, 2 AS f FROM cccd_candidate_ids WHERE v_like_cccd IS NOT NULL
            UNION ALL
            SELECT ID, 3 AS f FROM so_hs_candidate_ids WHERE v_like_hs IS NOT NULL
            UNION ALL
            SELECT ID, 4 AS f FROM dash_text_candidate_ids WHERE v_like_dash IS NOT NULL
        ) u
        GROUP BY u.ID
        HAVING COUNT(DISTINCT u.f) = v_text_filter_cnt
           AND v_text_filter_cnt > 0
    ),
    -- === ??a ch?: pre-compute DM ward/province tr??c khi drive scope ===
    matching_ward_ids AS (
        SELECT /*+ MATERIALIZE */ dxp.ID
        FROM QLPN.DM_XA_PHUONG dxp
        WHERE v_like_dktt IS NOT NULL
          AND NVL(dxp.IS_DELETED, 0) = 0
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(dxp.XP_TEN)), 1, 400) LIKE v_like_dktt
    ),
    matching_province_ids AS (
        SELECT /*+ MATERIALIZE */ dttp.ID
        FROM QLPN.DM_TINH_THANH_PHO dttp
        WHERE v_like_dktt IS NOT NULL
          AND NVL(dttp.IS_DELETED, 0) = 0
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(dttp.TTP_TEN)), 1, 400) LIKE v_like_dktt
    ),
    matching_cu_tru_ward_ids AS (
        SELECT /*+ MATERIALIZE */ dxp.ID
        FROM QLPN.DM_XA_PHUONG dxp
        WHERE v_like_cu_tru IS NOT NULL
          AND NVL(dxp.IS_DELETED, 0) = 0
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(dxp.XP_TEN)), 1, 400) LIKE v_like_cu_tru
    ),
    matching_cu_tru_province_ids AS (
        SELECT /*+ MATERIALIZE */ dttp.ID
        FROM QLPN.DM_TINH_THANH_PHO dttp
        WHERE v_like_cu_tru IS NOT NULL
          AND NVL(dttp.IS_DELETED, 0) = 0
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(dttp.TTP_TEN)), 1, 400) LIKE v_like_cu_tru
    ),
    -- FBI text + FK ward/province (OR trong t?ng nhóm ??a ch?) — drive RT g?c cho FBI ??a ch?
    dktt_scope_ids AS (
        SELECT /*+ MATERIALIZE */ ID FROM (
            SELECT /*+ INDEX_FFS(RT IX_PN_LLCT_RT_NORMDCHT) INDEX(RT IX_PN_LLCT_RT_FBI_DCHT) */ RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_dktt IS NOT NULL
              AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(RT.LL_DIA_CHI_THUONG_TRU)), 1, 400) LIKE v_like_dktt
            UNION
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            INNER JOIN matching_ward_ids mw ON mw.ID = RT.LL_DIA_CHI_THUONG_TRU_WARD
            WHERE v_like_dktt IS NOT NULL
              AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
            UNION
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            INNER JOIN matching_province_ids mp ON mp.ID = RT.LL_DIA_CHI_THUONG_TRU_PROVICE
            WHERE v_like_dktt IS NOT NULL
              AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        )
    ),
    cu_tru_scope_ids AS (
        SELECT /*+ MATERIALIZE */ ID FROM (
            SELECT /*+ INDEX_FFS(RT IX_PN_LLCT_RT_NORMCUTRU) INDEX(RT IX_PN_LLCT_RT_FBI_CU_TRU) */ RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_cu_tru IS NOT NULL
              AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(RT.LL_NOI_THA_VE_CU_TRU)), 1, 400) LIKE v_like_cu_tru
            UNION
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            INNER JOIN matching_cu_tru_ward_ids mw ON mw.ID = RT.LL_NOI_THA_VE_CU_TRU_WARD
            WHERE v_like_cu_tru IS NOT NULL
              AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
            UNION
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            INNER JOIN matching_cu_tru_province_ids mp ON mp.ID = RT.LL_NOI_THA_VE_CU_TRU_PROVICE
            WHERE v_like_cu_tru IS NOT NULL
              AND (NVL(p_include_deleted, 0) = 1 OR NVL(RT.IS_DELETED, 0) = 0)
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        )
    ),
    -- AND gi?a ??ng ký TT và v? c? trú khi c? hai có filter
    address_scope_ids AS (
        SELECT /*+ MATERIALIZE */ u.ID
        FROM (
            SELECT ID, 1 AS f FROM dktt_scope_ids WHERE v_like_dktt IS NOT NULL
            UNION ALL
            SELECT ID, 2 AS f FROM cu_tru_scope_ids WHERE v_like_cu_tru IS NOT NULL
        ) u
        GROUP BY u.ID
        HAVING COUNT(DISTINCT u.f) = v_address_filter_cnt
           AND v_address_filter_cnt > 0
    ),
    -- === Quan h? thân nhân — pre-compute 1 l?n t? b?ng DM nh? ===
    qh_bo_ids AS (
        SELECT /*+ MATERIALIZE */ qh.ID
        FROM QLPN.DM_QUAN_HE_VOI_PHAM_NHANS qh
        WHERE v_like_bo IS NOT NULL
          AND UPPER(QLPN.FN_NORMALIZE_VN(qh.QHVPN_TEN)) LIKE 'BO%'
    ),
    qh_me_ids AS (
        SELECT /*+ MATERIALIZE */ qh.ID
        FROM QLPN.DM_QUAN_HE_VOI_PHAM_NHANS qh
        WHERE v_like_me IS NOT NULL
          AND UPPER(QLPN.FN_NORMALIZE_VN(qh.QHVPN_TEN)) LIKE 'ME%'
    ),
    qh_vc_ids AS (
        SELECT /*+ MATERIALIZE */ qh.ID
        FROM QLPN.DM_QUAN_HE_VOI_PHAM_NHANS qh
        WHERE v_like_vc IS NOT NULL
          AND (UPPER(QLPN.FN_NORMALIZE_VN(qh.QHVPN_TEN)) LIKE 'VO%'
            OR UPPER(QLPN.FN_NORMALIZE_VN(qh.QHVPN_TEN)) LIKE 'CHONG%')
    ),
    -- Candidate thân nhân theo tên. IS_DELETED = 0 ngay t?i ?ây (?úng v? t? EXISTS c? ?
    -- filtered_prep) ?? không g?i l?i FN_NORMALIZE_VN l?n hai trên t?ng dòng driver.
    -- IDX_TN_PN_QH_TEN_NORM không ch?a IS_DELETED: hint INDEX_FFS v?n ?úng n?u optimizer
    -- gi? index; n?u ph?i table lookup thì v?n m?t l?n, không hai.
    tn_bo_candidate_ids AS (
        SELECT /*+ MATERIALIZE INDEX_FFS(tn IDX_TN_PN_QH_TEN_NORM) */ tn.PHAM_NHAN_ID AS ID
        FROM QLPN.THAN_NHAN_NGUOI_THANS tn
        WHERE v_like_bo IS NOT NULL
          AND tn.IS_DELETED = 0
          AND tn.QUAN_HE_ID IN (SELECT ID FROM qh_bo_ids)
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(tn.HO_TEN_THAN_NHAN)), 1, 400) LIKE v_like_bo
        GROUP BY tn.PHAM_NHAN_ID
    ),
    tn_me_candidate_ids AS (
        SELECT /*+ MATERIALIZE INDEX_FFS(tn IDX_TN_PN_QH_TEN_NORM) */ tn.PHAM_NHAN_ID AS ID
        FROM QLPN.THAN_NHAN_NGUOI_THANS tn
        WHERE v_like_me IS NOT NULL
          AND tn.IS_DELETED = 0
          AND tn.QUAN_HE_ID IN (SELECT ID FROM qh_me_ids)
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(tn.HO_TEN_THAN_NHAN)), 1, 400) LIKE v_like_me
        GROUP BY tn.PHAM_NHAN_ID
    ),
    tn_vc_candidate_ids AS (
        SELECT /*+ MATERIALIZE INDEX_FFS(tn IDX_TN_PN_QH_TEN_NORM) */ tn.PHAM_NHAN_ID AS ID
        FROM QLPN.THAN_NHAN_NGUOI_THANS tn
        WHERE v_like_vc IS NOT NULL
          AND tn.IS_DELETED = 0
          AND tn.QUAN_HE_ID IN (SELECT ID FROM qh_vc_ids)
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(tn.HO_TEN_THAN_NHAN)), 1, 400) LIKE v_like_vc
        GROUP BY tn.PHAM_NHAN_ID
    ),
    -- PN_THI_HANH_AN drive: t?i danh + ngày b?t/??n tr?i — 1 l?n thay EXISTS × 1.5M
    toi_danh_scope_ids AS (
        SELECT /*+ MATERIALIZE */ tha.THA_PNLAI_LICH_ID AS ID
        FROM QLPN.PN_THI_HANH_AN tha
        WHERE v_tha_filter_cnt > 0
          AND NVL(tha.IS_DELETED, 0) = 0
          AND (v_toi_danh_id IS NULL OR INSTR(
                  ',' || REPLACE(REPLACE(TRIM(CAST(tha.THA_TOI_DANH AS VARCHAR2(4000))), '[', ''), ']', '') || ',',
                  ',' || TO_CHAR(v_toi_danh_id) || ','
              ) > 0)
          AND (v_ngay_bat IS NULL OR (CAST(tha.THA_NGAY_BAT AS DATE) >= v_ngay_bat AND CAST(tha.THA_NGAY_BAT AS DATE) < v_ngay_bat + 1))
          AND (v_den_trai_tu_ngay IS NULL OR CAST(tha.THA_NGAY_DEN_TRAI AS DATE) >= v_den_trai_tu_ngay)
          AND (v_den_trai_den_ngay IS NULL OR CAST(tha.THA_NGAY_DEN_TRAI AS DATE) < v_den_trai_den_ngay + 1)
          AND (v_het_an_tu_ngay IS NULL OR CAST(tha.THA_NGAY_HET_HAN AS DATE) >= v_het_an_tu_ngay)
          AND (v_het_an_den_ngay IS NULL OR CAST(tha.THA_NGAY_HET_HAN AS DATE) < v_het_an_den_ngay + 1)
          AND (v_like_so_ban_an IS NULL OR UPPER(TRIM(CAST(tha.THA_SO_BAN_AN AS NVARCHAR2(1000)))) LIKE v_like_so_ban_an)
          AND (v_like_so_qd_tha IS NULL OR UPPER(TRIM(CAST(tha.THA_SO_QD_THA AS NVARCHAR2(1000)))) LIKE v_like_so_qd_tha)
        GROUP BY tha.THA_PNLAI_LICH_ID
    ),
    -- Giao text + ??a ch? + THA + thân nhân (AND gi?a các nhóm; m?i filter b?/m?/VC là 1 dim riêng)
    free_scope_ids AS (
        SELECT /*+ MATERIALIZE */ u.ID
        FROM (
            SELECT ID, 1 AS dim FROM text_scope_ids WHERE v_text_filter_cnt > 0
            UNION ALL
            SELECT ID, 2 AS dim FROM address_scope_ids WHERE v_address_filter_cnt > 0
            UNION ALL
            SELECT ID, 3 AS dim FROM toi_danh_scope_ids WHERE v_tha_filter_cnt > 0
            UNION ALL
            SELECT ID, 4 AS dim FROM tn_bo_candidate_ids WHERE v_like_bo IS NOT NULL
            UNION ALL
            SELECT ID, 5 AS dim FROM tn_me_candidate_ids WHERE v_like_me IS NOT NULL
            UNION ALL
            SELECT ID, 6 AS dim FROM tn_vc_candidate_ids WHERE v_like_vc IS NOT NULL
        ) u
        GROUP BY u.ID
        HAVING COUNT(DISTINCT u.dim) =
              (CASE WHEN v_text_filter_cnt > 0 THEN 1 ELSE 0 END
             + CASE WHEN v_address_filter_cnt > 0 THEN 1 ELSE 0 END
             + CASE WHEN v_tha_filter_cnt > 0 THEN 1 ELSE 0 END
             + v_tn_filter_cnt)
           AND (v_text_filter_cnt > 0 OR v_address_filter_cnt > 0 OR v_tha_filter_cnt > 0 OR v_tn_filter_cnt > 0)
    ),
    -- PERF driver_rows: lái t? id-set nh? ho?c RT g?c, không copy dân s? vào rt_trai khi không c?n.
    --   (a) có free-filter -> free_scope_ids, PK-join RT (dashboard thì EXISTS dash_eligible)
    --   (b) ??u k?, không free-filter -> dash_eligible_ids, PK-join RT
    --   (b2) loai 2/3/4, không free-filter -> dash_eligible_ids join rt_trai (c?t ?ã materialize)
    --   (c) không dashboard, không free-filter -> quét RT g?c m?t l?n
    --   Filter per-row (gi?i tính/tình tr?ng/.../stt_tong_hop) áp 1 l?n ? filtered_prep.
    driver_rows AS (
        -- (a) có ít nh?t 1 free-filter
        SELECT rt.PHAM_NHAN_ID, rt.HO_TEN_ORDER, rt.LL_TINH_TRANG_ID,
               rt.LL_DM_GIOI_TINH_ID, rt.LL_DM_DAN_TOC_ID, rt.LL_DM_QUOC_TICH_ID, rt.LL_DM_TON_GIAO_ID,
               rt.LL_DM_HOC_VAN_ID,
               rt.LL_PHAN_DOI_ID, rt.LL_PHAN_TRAI_ID,
               rt.LL_SO_HO_SO_LAN_DAU, dtd_a.TD_TEN AS TOI_DANH_DAU_TIEN_NAME,
               rt.LL_NGAY_SINH, rt.THA_NGAY_BAT, rt.THA_NGAY_DEN_TRAI, rt.THA_NGAY_HET_HAN, rt.THA_AN_PHAT, rt.THA_MA_AN_PHAT,
               c.TTPN_MA
        FROM free_scope_ids s
        JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt ON rt.PHAM_NHAN_ID = s.ID
        LEFT JOIN cache_today c ON c.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN dm_toi_danh_ten dtd_a
          ON dtd_a.ID = CASE
                WHEN v_sort_toi_danh = 1
                THEN TO_NUMBER(rt.TOI_DANH_DAU_TIEN DEFAULT NULL ON CONVERSION ERROR)
             END
        WHERE (v_text_filter_cnt > 0 OR v_address_filter_cnt > 0 OR v_tha_filter_cnt > 0 OR v_tn_filter_cnt > 0)
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(rt.IS_DELETED, 0) = 0)
          AND rt.LL_TRAI_GIAM_ID IS NOT NULL
          AND rt.LL_TRAI_GIAM_ID IN (SELECT ID FROM valid_trai_ids)
          AND (v_ll_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
          AND (
                p_dash_loai_tk IS NULL
             OR EXISTS (SELECT 1 FROM dash_eligible_ids d WHERE d.ID = rt.PHAM_NHAN_ID)
          )
        UNION ALL
        -- (b) dashboard, KHÔNG có free-filter
        SELECT rt.PHAM_NHAN_ID, rt.HO_TEN_ORDER, rt.LL_TINH_TRANG_ID,
               rt.LL_DM_GIOI_TINH_ID, rt.LL_DM_DAN_TOC_ID, rt.LL_DM_QUOC_TICH_ID, rt.LL_DM_TON_GIAO_ID,
               rt.LL_DM_HOC_VAN_ID,
               rt.LL_PHAN_DOI_ID, rt.LL_PHAN_TRAI_ID,
               rt.LL_SO_HO_SO_LAN_DAU, dtd_b.TD_TEN AS TOI_DANH_DAU_TIEN_NAME,
               rt.LL_NGAY_SINH, rt.THA_NGAY_BAT, rt.THA_NGAY_DEN_TRAI, rt.THA_NGAY_HET_HAN, rt.THA_AN_PHAT, rt.THA_MA_AN_PHAT,
               c.TTPN_MA
        FROM dash_eligible_ids d
        JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt ON rt.PHAM_NHAN_ID = d.ID
        LEFT JOIN cache_today c ON c.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN dm_toi_danh_ten dtd_b
          ON dtd_b.ID = CASE
                WHEN v_sort_toi_danh = 1
                THEN TO_NUMBER(rt.TOI_DANH_DAU_TIEN DEFAULT NULL ON CONVERSION ERROR)
             END
        WHERE p_dash_loai_tk = 1
          AND v_text_filter_cnt = 0 AND v_address_filter_cnt = 0 AND v_tha_filter_cnt = 0 AND v_tn_filter_cnt = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(rt.IS_DELETED, 0) = 0)
          AND rt.LL_TRAI_GIAM_ID IS NOT NULL
          AND rt.LL_TRAI_GIAM_ID IN (SELECT ID FROM valid_trai_ids)
          AND (v_ll_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        UNION ALL
        -- (b2) loai 2/3/4: c?t ?ã n?m trên rt_trai — không PK-lookup l?i RT
        SELECT rt.PHAM_NHAN_ID, rt.HO_TEN_ORDER, rt.LL_TINH_TRANG_ID,
               rt.LL_DM_GIOI_TINH_ID, rt.LL_DM_DAN_TOC_ID, rt.LL_DM_QUOC_TICH_ID, rt.LL_DM_TON_GIAO_ID,
               rt.LL_DM_HOC_VAN_ID,
               rt.LL_PHAN_DOI_ID, rt.LL_PHAN_TRAI_ID,
               rt.LL_SO_HO_SO_LAN_DAU, dtd_b2.TD_TEN AS TOI_DANH_DAU_TIEN_NAME,
               rt.LL_NGAY_SINH, rt.THA_NGAY_BAT, rt.THA_NGAY_DEN_TRAI, rt.THA_NGAY_HET_HAN, rt.THA_AN_PHAT, rt.THA_MA_AN_PHAT,
               c.TTPN_MA
        FROM dash_eligible_ids d
        JOIN rt_trai rt ON rt.PHAM_NHAN_ID = d.ID
        LEFT JOIN cache_today c ON c.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN dm_toi_danh_ten dtd_b2
          ON dtd_b2.ID = CASE
                WHEN v_sort_toi_danh = 1
                THEN TO_NUMBER(rt.TOI_DANH_DAU_TIEN DEFAULT NULL ON CONVERSION ERROR)
             END
        WHERE p_dash_loai_tk IN (2, 3, 4)
          AND v_text_filter_cnt = 0 AND v_address_filter_cnt = 0 AND v_tha_filter_cnt = 0 AND v_tn_filter_cnt = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(rt.IS_DELETED, 0) = 0)
          AND rt.LL_TRAI_GIAM_ID IS NOT NULL
          AND rt.LL_TRAI_GIAM_ID IN (SELECT ID FROM valid_trai_ids)
          AND (v_ll_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        UNION ALL
        -- (c) non-dashboard, KHÔNG có free-filter -> quét RT g?c m?t l?n
        SELECT rt.PHAM_NHAN_ID, rt.HO_TEN_ORDER, rt.LL_TINH_TRANG_ID,
               rt.LL_DM_GIOI_TINH_ID, rt.LL_DM_DAN_TOC_ID, rt.LL_DM_QUOC_TICH_ID, rt.LL_DM_TON_GIAO_ID,
               rt.LL_DM_HOC_VAN_ID,
               rt.LL_PHAN_DOI_ID, rt.LL_PHAN_TRAI_ID,
               rt.LL_SO_HO_SO_LAN_DAU, dtd_c.TD_TEN AS TOI_DANH_DAU_TIEN_NAME,
               rt.LL_NGAY_SINH, rt.THA_NGAY_BAT, rt.THA_NGAY_DEN_TRAI, rt.THA_NGAY_HET_HAN, rt.THA_AN_PHAT, rt.THA_MA_AN_PHAT,
               c.TTPN_MA
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        LEFT JOIN cache_today c ON c.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN dm_toi_danh_ten dtd_c
          ON dtd_c.ID = CASE
                WHEN v_sort_toi_danh = 1
                THEN TO_NUMBER(rt.TOI_DANH_DAU_TIEN DEFAULT NULL ON CONVERSION ERROR)
             END
        WHERE p_dash_loai_tk IS NULL
          AND v_text_filter_cnt = 0 AND v_address_filter_cnt = 0 AND v_tha_filter_cnt = 0 AND v_tn_filter_cnt = 0
          AND (NVL(p_include_deleted, 0) = 1 OR NVL(rt.IS_DELETED, 0) = 0)
          AND rt.LL_TRAI_GIAM_ID IS NOT NULL
          AND rt.LL_TRAI_GIAM_ID IN (SELECT ID FROM valid_trai_ids)
          AND (v_ll_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    -- 1. L?c per-row trên driver_rows (eligibility ?ã thu h?p ? trên)
    -- MATERIALIZE: filtered_count + paged_ids cùng ??c 1 temp, tránh ch?y filter per-row 2 l?n.
    -- FIRST_ROWS(100) là hint C?P CÂU L?NH — B?T BU?C GI?: nó chuy?n c? statement sang optimizer mode
    -- first_rows, c?t t?a m?nh không gian cost-based transformation. B? hint này ? hard parse bùng n?
    -- ~4-5 PHÚT thu?n CPU (?o ASH 07/2026: 501 m?u IN_HARD_PARSE='Y' ON CPU, ch?y th?t ch? 0.2-2s).
    filtered_prep AS (
        SELECT /*+ MATERIALIZE FIRST_ROWS(100) */
            rt.PHAM_NHAN_ID AS PHAM_NHAN_ID,
            rt.HO_TEN_ORDER AS HO_TEN_ORDER,
            rt.THA_NGAY_BAT AS THA_NGAY_BAT,
            rt.THA_NGAY_HET_HAN AS THA_NGAY_HET_HAN,
            -- C?t r?ng ch? khi ?úng sort ?ó ??c: temp c?a t?p l?n không mang h? tên / án ph?t / s? HS th?a.
            CASE WHEN v_sort_anphat = 1 THEN rt.THA_AN_PHAT END AS THA_AN_PHAT,
            rt.THA_NGAY_DEN_TRAI AS THA_NGAY_DEN_TRAI,
            -- Sort key SOHSLD/TOIDANH: LL_SO_HO_SO_LAN_DAU có s?n trên RT; TOI_DANH_SORT là TÊN t?i danh
            -- (driver_rows resolve qua dm_toi_danh_ten ch? khi v_sort_toi_danh = 1 — TOI_DANH_DAU_TIEN
            -- g?c trên RT là ID, sort theo ID s? sai th? t? alphabet). Sort khác thì c?t này NULL
            -- và CASE ORDER BY không ??c nó.
            CASE WHEN v_sort_sohsld = 1 THEN rt.LL_SO_HO_SO_LAN_DAU END AS SO_HSLD,
            CASE WHEN v_sort_toi_danh = 1 THEN rt.TOI_DANH_DAU_TIEN_NAME END AS TOI_DANH_SORT,
            -- Sort key ngày sinh: LL_NGAY_SINH là text (DD/MM/YYYY ho?c ch? n?m) — parse an toàn,
            -- không match ??nh d?ng thì ?? NULL (gi?ng logic hi?n th? "ngaySinh" ? SELECT cu?i).
            -- REGEXP ch? ch?y khi sort NGAYSINH; sort m?c ??nh không parse t?ng dòng.
            CASE
                WHEN v_sort_ngaysinh = 1
                     AND rt.LL_NGAY_SINH IS NOT NULL
                     AND REGEXP_LIKE(TRIM(CAST(rt.LL_NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
                THEN TO_DATE(TRIM(CAST(rt.LL_NGAY_SINH AS VARCHAR2(100))) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY')
                ELSE NULL
            END AS NGAY_SINH_DATE
        FROM driver_rows rt
        WHERE (
            p_stt_tong_hop IS NULL
            OR (p_stt_tong_hop = 1  AND rt.TTPN_MA IN ('111', '112', '113', '114'))
            OR (p_stt_tong_hop = 2
                AND rt.TTPN_MA LIKE '112%'
                AND EXISTS (SELECT 1 FROM QLPN.PN_GIAM_RIENGS g
                    WHERE g.GR_PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
                      AND NVL(g.IS_DELETED, 0) = 0
                      AND (g.GR_NGAY_KETTHUC IS NULL OR g.GR_NGAY_KETTHUC >= v_ngay_xet)))
            OR (p_stt_tong_hop = 3
                AND rt.TTPN_MA LIKE '113%'
                AND EXISTS (SELECT 1 FROM QLPN.CHUA_BENH_BAT_BUOCS c
                    WHERE c.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                      AND NVL(c.IS_DELETED, 0) = 0))
            OR (p_stt_tong_hop = 4
                AND rt.TTPN_MA IN ('141', '142')
                AND EXISTS (SELECT 1 FROM QLPN.TRICH_XUATS tx
                    WHERE tx.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                      AND NVL(tx.IS_DELETED, 0) = 0
                      AND tx.TX_NGAY_TRA IS NULL
                      AND EXISTS (SELECT 1 FROM QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS lqd
                          WHERE lqd.ID = tx.TX_LOAI_LENH_ID
                            AND NVL(lqd.IS_DELETED, 0) = 0
                            AND lqd.LQDTX_MA = '1')))
            OR (p_stt_tong_hop = 5
                AND rt.TTPN_MA IN ('151', '152', '157')
                AND EXISTS (SELECT 1 FROM QLPN.TAM_DINH_CHIS tdc
                    WHERE tdc.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                      AND NVL(tdc.IS_DELETED, 0) = 0
                      AND tdc.NGAY_LAI IS NULL
                      AND EXISTS (SELECT 1 FROM QLPN.DM_LOAI_QUYET_DINH_TAM_DINH_CHIES lq
                          WHERE lq.ID = tdc.LOAI_QUYET_DINH_ID
                            AND NVL(lq.IS_DELETED, 0) = 0
                            AND lq.LQDTDC_MA = '1')))
            OR (p_stt_tong_hop = 6  AND rt.TTPN_MA = '126')
            OR (p_stt_tong_hop = 7  AND rt.THA_NGAY_DEN_TRAI IS NOT NULL AND rt.THA_NGAY_HET_HAN >= v_ngay_xet AND rt.THA_NGAY_HET_HAN < v_ngay_xet + 1)
            OR (p_stt_tong_hop = 8  AND rt.TTPN_MA IN ('111', '112', '113', '114') AND rt.THA_NGAY_DEN_TRAI IS NOT NULL AND rt.THA_NGAY_HET_HAN >= v_ngay_xet + 1 AND rt.THA_NGAY_HET_HAN < v_ngay_xet + 2)
            OR (p_stt_tong_hop = 9  AND rt.TTPN_MA IN ('111', '112', '113', '114') AND rt.THA_NGAY_DEN_TRAI IS NOT NULL AND rt.THA_NGAY_HET_HAN >= v_ngay_xet + 1 AND rt.THA_NGAY_HET_HAN < ADD_MONTHS(v_ngay_xet + 1, 2) + 1)
            OR (p_stt_tong_hop = 10 AND rt.TTPN_MA = '123')
            OR (p_stt_tong_hop = 11 AND v_ll_trai_giam_id IS NOT NULL AND EXISTS (SELECT 1 FROM QLPN.PHAM_NHAN_CHUYEN_TRAI ct WHERE ct.PNCT_LAI_LICH_ID = rt.PHAM_NHAN_ID AND NVL(ct.IS_DELETED, 0) = 0))
            OR (p_stt_tong_hop = 12 AND EXISTS (SELECT 1 FROM QLPN.PN_KET_THUC_CHETS k WHERE k.KTC_PN_LAI_LICH_ID = rt.PHAM_NHAN_ID AND NVL(k.IS_DELETED, 0) = 0 AND k.KTC_NGAY_CHET >= TRUNC(SYSDATE, 'YEAR')))
            OR (p_stt_tong_hop = 13 AND EXISTS (SELECT 1 FROM QLPN.TRON_TRAIS tt WHERE tt.PHAM_NHAN_ID = rt.PHAM_NHAN_ID AND NVL(tt.IS_DELETED, 0) = 0 AND tt.NGAY_BAT_LAI IS NULL))
            OR (p_stt_tong_hop = 14 AND EXISTS (SELECT 1 FROM QLPN.HUY_ANS h WHERE h.PHAM_NHAN_ID = rt.PHAM_NHAN_ID AND NVL(h.IS_DELETED, 0) = 0 AND h.NGAY_TRA_TU_DO IS NOT NULL))
            OR (p_stt_tong_hop = 15 AND EXISTS (SELECT 1 FROM QLPN.MIEN_HINH_PHATS m WHERE m.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID AND NVL(m.IS_DELETED, 0) = 0 AND m.MHP_NGAY_TU_DO IS NOT NULL))
            OR (p_stt_tong_hop = 16 AND EXISTS (SELECT 1 FROM QLPN.HOAN_THI_HANH_ANS h WHERE h.PHAM_NHAN_ID = rt.PHAM_NHAN_ID AND NVL(h.IS_DELETED, 0) = 0))
        )
        AND (p_gioi_tinh_id IS NULL OR rt.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
        AND (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = p_phan_doi_id)
        AND (p_phan_trai_id IS NULL OR rt.LL_PHAN_TRAI_ID = p_phan_trai_id)
        AND (p_tinh_trang_id IS NULL OR rt.LL_TINH_TRANG_ID = p_tinh_trang_id)
        AND (p_dan_toc_id IS NULL OR rt.LL_DM_DAN_TOC_ID = p_dan_toc_id)
        AND (p_quoc_tich_id IS NULL OR rt.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
        AND (p_ton_giao_id IS NULL OR rt.LL_DM_TON_GIAO_ID = p_ton_giao_id)
        AND (p_trinh_do_hoc_van_id IS NULL OR rt.LL_DM_HOC_VAN_ID = p_trinh_do_hoc_van_id)
        AND (p_ma_an_phat IS NULL OR rt.THA_MA_AN_PHAT = p_ma_an_phat)
        AND (v_like_ngaysinh IS NULL OR rt.LL_NGAY_SINH LIKE v_like_ngaysinh)
        -- ??a ch? ?ã l?c trong free_scope_ids.
        -- Thân nhân (b?/m?/v? ch?ng): cùng v? t? IS_DELETED = 0 + quan h? + LIKE tên
        -- ?ã áp trong tn_*_candidate_ids và AND qua free_scope_ids. Không EXISTS l?i.
        -- THA ?ã l?c trong toi_danh_scope_ids / free_scope_ids khi v_tha_filter_cnt > 0
    ),
    -- P0-2: total_count tách kh?i paginate — tránh WINDOW SORT toàn b? filtered_prep
    filtered_count AS (
        SELECT COUNT(*) AS total_count
        FROM filtered_prep
    ),
    -- 2. Phân trang nhanh (Pagination) — không COUNT(*) OVER ()
    paged_ids AS (
        SELECT /*+ MATERIALIZE */
            f.PHAM_NHAN_ID
        FROM filtered_prep f
        -- p_sort whitelist qua CASE WHEN (static SQL, không dynamic) — v_sort_upper ?ã UPPER/TRIM ? trên.
        -- NULL/giá tr? l? r?i vào nhánh m?c ??nh cu?i (HO_TEN_ORDER ASC), gi? nguyên hành vi c?.
        ORDER BY
            CASE WHEN v_sort_upper = 'NGAYSINH ASC'  THEN f.NGAY_SINH_DATE   END ASC  NULLS LAST,
            CASE WHEN v_sort_upper = 'NGAYSINH DESC' THEN f.NGAY_SINH_DATE   END DESC NULLS LAST,
            CASE WHEN v_sort_upper = 'NGAYBAT ASC'    THEN f.THA_NGAY_BAT     END ASC  NULLS LAST,
            CASE WHEN v_sort_upper = 'NGAYBAT DESC'   THEN f.THA_NGAY_BAT     END DESC NULLS LAST,
            CASE WHEN v_sort_upper = 'NGAYHETHAN ASC'  THEN f.THA_NGAY_HET_HAN END ASC  NULLS LAST,
            CASE WHEN v_sort_upper = 'NGAYHETHAN DESC' THEN f.THA_NGAY_HET_HAN END DESC NULLS LAST,
            CASE WHEN v_sort_upper = 'ANPHAT ASC'     THEN f.THA_AN_PHAT      END ASC  NULLS LAST,
            CASE WHEN v_sort_upper = 'ANPHAT DESC'    THEN f.THA_AN_PHAT      END DESC NULLS LAST,
            CASE WHEN v_sort_upper = 'HOTEN DESC'     THEN f.HO_TEN_ORDER     END DESC NULLS LAST,
            CASE WHEN v_sort_upper = 'SOHSLD ASC'        THEN f.SO_HSLD           END ASC  NULLS LAST,
            CASE WHEN v_sort_upper = 'SOHSLD DESC'       THEN f.SO_HSLD           END DESC NULLS LAST,
            CASE WHEN v_sort_upper = 'TOIDANH ASC'       THEN f.TOI_DANH_SORT     END ASC  NULLS LAST,
            CASE WHEN v_sort_upper = 'TOIDANH DESC'      THEN f.TOI_DANH_SORT     END DESC NULLS LAST,
            CASE WHEN v_sort_upper = 'NGAYDENTRAI ASC'  THEN f.THA_NGAY_DEN_TRAI END ASC  NULLS LAST,
            CASE WHEN v_sort_upper = 'NGAYDENTRAI DESC' THEN f.THA_NGAY_DEN_TRAI END DESC NULLS LAST,
            CASE WHEN v_sort_upper NOT IN (
                'NGAYSINH ASC', 'NGAYSINH DESC', 'NGAYBAT ASC', 'NGAYBAT DESC',
                'NGAYHETHAN ASC', 'NGAYHETHAN DESC', 'ANPHAT ASC', 'ANPHAT DESC', 'HOTEN DESC',
                'SOHSLD ASC', 'SOHSLD DESC', 'TOIDANH ASC', 'TOIDANH DESC',
                'NGAYDENTRAI ASC', 'NGAYDENTRAI DESC'
            ) THEN f.HO_TEN_ORDER END ASC NULLS LAST,
            f.PHAM_NHAN_ID DESC
        OFFSET v_skip ROWS
        FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY
    ),
    -- Drive NL ~25 PHAM_NHAN_ID ? view (tránh merge full scan VW trên toàn RT)
    page_detail AS (
        SELECT /*+ MATERIALIZE LEADING(p) USE_NL(v) */
            v.*
        FROM paged_ids p
        LEFT JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET v ON v.PHAM_NHAN_ID = p.PHAM_NHAN_ID
    ),
    -- 3. Join chi ti?t trang và mapping alias
    rows_page AS (
        SELECT
            fc.total_count,
            v.*,
            -- Ánh x? l?i các tên c?t có ti?n t? LL_ ?? kh?p v?i SELECT cu?i cùng
            v.NOI_OTRUOC_KHI_BAT      AS LL_NOI_OTRUOC_KHI_BAT,
            v.SO_HO_PHU               AS LL_SO_HO_PHU,
            v.HO_CHIEU                AS LL_HO_CHIEU,
            v.LL_DM_DAN_TOC_ID        AS ID_DAN_TOC,
            v.LL_DM_TON_GIAO_ID       AS ID_TON_GIAO,
            v.LL_DM_HOC_VAN_ID        AS ID_TRINH_DO_HOC_VAN,
            v.LL_DM_NGHE_NGHIEP_ID    AS ID_NGHE_NGHIEP,
            v.LL_SUC_KHOE_KHI_VAO_ID  AS ID_SUC_KHOE_KHI_VAO,
            dmttpn.TTPN_TEN AS TEN_TINH_TRANG,
           v.NOI_THA_VE_CU_TRU AS NOI_THA_VE_DAY_DU,
            CASE
                WHEN NVL(v.SO_LAN_GIAM, 0) = 0
                  OR v.THOI_GIAN_DA_GIAM IS NULL
                  OR NULLIF(TRIM(CAST(v.THOI_GIAN_DA_GIAM AS NVARCHAR2(2000))), u'0') IS NULL
                THEN u'Kh\00f4ng'
                ELSE TO_NCHAR(v.SO_LAN_GIAM) || u' l\1ea7n = '
                     || CAST(v.THOI_GIAN_DA_GIAM AS NVARCHAR2(2000))
            END AS calc_da_giam,
            CAST(v.THOI_GIAN_DA_CHAP_HANH AS NVARCHAR2(2000)) AS calc_da_chap_hanh,
            CAST(v.THOI_GIAN_CON_LAI AS NVARCHAR2(2000)) AS calc_con_lai,
            -- Sort key ngày sinh cho ORDER BY cu?i — cùng công th?c parse v?i filtered_prep.NGAY_SINH_DATE
            CASE
                WHEN v.NGAY_SINH IS NOT NULL
                     AND REGEXP_LIKE(TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
                THEN TO_DATE(TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY')
                ELSE NULL
            END AS SORT_NGAY_SINH_DATE,
            -- Sort key TOI_DANH cho ORDER BY cu?i: v.TOI_DANH_DAU_TIEN (t? v.*) là ID t?i danh, không ph?i
            -- tên — resolve tên qua DM_TOI_DANHS, ch? áp d?ng cho ?25 dòng c?a trang nên r?
            TRIM(td_first.TD_TEN) AS TOI_DANH_DAU_TIEN_NAME
        FROM paged_ids p
        CROSS JOIN filtered_count fc
        LEFT JOIN page_detail v ON v.PHAM_NHAN_ID = p.PHAM_NHAN_ID
        LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS dmttpn
            ON dmttpn.ID = v.LL_TINH_TRANG_ID
           AND NVL(dmttpn.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TOI_DANHS td_first
            ON td_first.ID = TO_NUMBER(v.TOI_DANH_DAU_TIEN DEFAULT NULL ON CONVERSION ERROR)
           AND NVL(td_first.IS_DELETED, 0) = 0
    )
    SELECT
        p.total_count     AS "totalCount",
        p.LL_ANH          AS "anh",
        p.SO_HO_SO        AS "soHoSoLanDau",
        p.LL_SO_HO_PHU    AS "soHoPhu",
        p.CCCD            AS "cccd",
        p.LL_HO_CHIEU     AS "hoChieu",
        p.HO_TEN          AS "hoTen",
        p.GIOI_TINH_ID    AS "gioiTinhId",
        p.GIOI_TINH       AS "gioiTinhName",
        CASE
            WHEN p.NGAY_SINH IS NOT NULL
                 AND REGEXP_LIKE(TRIM(CAST(p.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(CAST(p.NGAY_SINH AS VARCHAR2(100))) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN p.NAM_SINH IS NOT NULL AND p.NAM_SINH > 0 THEN TO_CHAR(p.NAM_SINH)
            WHEN p.NGAY_SINH IS NOT NULL THEN TRIM(CAST(p.NGAY_SINH AS VARCHAR2(100)))
            ELSE NULL
        END AS "ngaySinh",
        p.LL_PHAN_TRAI_ID AS "phanTraiId",
        p.PHAN_TRAI       AS "phanTraiName",
        p.PHAN_DOI_ID     AS "phanDoiId",
        p.PHAN_DOI        AS "phanDoiName",
        p.LL_TINH_TRANG_ID AS "tinhTrangId",
        CAST(p.TEN_TINH_TRANG AS NVARCHAR2(500)) AS "tinhTrangName",
        p.TEN_KHAC        AS "tenKhac",
        p.NOI_THUONG_TRU_DAY_DU AS "diaChiThuongTru",
        p.DIA_CHI_THUONG_TRU AS "diaChiThuongTruShort",
        p.LL_NOI_OTRUOC_KHI_BAT AS "noiOTruocKhiBat",
        p.NOI_O_KHAC      AS "noiOKhac",
        p.NGUYEN_QUAN     AS "nguyenQuan",
        p.NOI_THA_VE_DAY_DU AS "noiThaVeCuTru",
        p.ID_DAN_TOC      AS "danTocId",
        p.DAN_TOC         AS "danTocName",
        p.ID_TON_GIAO     AS "tonGiaoId",
        p.TON_GIAO        AS "tonGiaoName",
        p.QUOC_TICH_ID    AS "quocTichId",
        p.QUOC_TICH       AS "quocTichName",
        p.ID_TRINH_DO_HOC_VAN AS "trinhDoHocVanId",
        p.HOC_VAN         AS "trinhDoHocVanName",
        p.ID_NGHE_NGHIEP  AS "ngheNghiepId",
        p.NGHE_NGHIEP     AS "ngheNghiepName",
        p.ID_SUC_KHOE_KHI_VAO AS "sucKhoeKhiVaoId",
        p.TINH_TRANG_SUC_KHOE AS "sucKhoeKhiVaoName",
        p.TOI_DANH        AS "toiDanh",
        p.TOI_DANH_ID     AS "toiDanhIds",
        p.NGAY_BAT_AN_PHAT AS "ngayBat",
        p.NGAY_DEN_TRAI   AS "ngayDenTrai",
        p.AN_PHAT         AS "anPhat",
        p.THA_MA_AN_PHAT  AS "maAnPhat",
        p.SO_BAN_AN       AS "soBanAn",
        p.SO_QD_THA       AS "soQdTha",
        p.NGAY_HET_AN     AS "ngayHetHan",
        p.calc_con_lai    AS "thoiGianConLai",
        p.SO_TIEN_AN      AS "tienAn",
        p.calc_da_giam    AS "daGiam",
        p.calc_da_chap_hanh AS "daChapHanh",
        p.LL_DIA_CHI_THUONG_TRU_PROVICE AS "diaChiThuongTruProvice",
        p.TINH_THANH_THUONG_TRU AS "diaChiThuongTruProviceName",
        p.LL_DIA_CHI_THUONG_TRU_WARD AS "diaChiThuongTruWard",
        p.PHUONG_XA_THUONG_TRU AS "diaChiThuongTruWardName",
        p.SO_QD_DIEU_CHUYEN AS "soQuyetDinhDieuChuyen",
        QLPN.FN_GET_LIET_KE_HPBS_CHI_TIET(p.PHAM_NHAN_ID) AS "hinhPhatBoSung",
        p.PHAM_NHAN_ID    AS "id"
    FROM rows_page p
    -- ??ng b? ?úng key sort ?ã dùng ?? phân trang ? paged_ids (khác key thì trang s? "xáo" th? t? hi?n th?)
    ORDER BY
        CASE WHEN v_sort_upper = 'NGAYSINH ASC'  THEN p.SORT_NGAY_SINH_DATE END ASC  NULLS LAST,
        CASE WHEN v_sort_upper = 'NGAYSINH DESC' THEN p.SORT_NGAY_SINH_DATE END DESC NULLS LAST,
        CASE WHEN v_sort_upper = 'NGAYBAT ASC'    THEN p.NGAY_BAT_AN_PHAT   END ASC  NULLS LAST,
        CASE WHEN v_sort_upper = 'NGAYBAT DESC'   THEN p.NGAY_BAT_AN_PHAT   END DESC NULLS LAST,
        CASE WHEN v_sort_upper = 'NGAYHETHAN ASC'  THEN p.NGAY_HET_AN        END ASC  NULLS LAST,
        CASE WHEN v_sort_upper = 'NGAYHETHAN DESC' THEN p.NGAY_HET_AN        END DESC NULLS LAST,
        CASE WHEN v_sort_upper = 'ANPHAT ASC'     THEN p.AN_PHAT            END ASC  NULLS LAST,
        CASE WHEN v_sort_upper = 'ANPHAT DESC'    THEN p.AN_PHAT            END DESC NULLS LAST,
        CASE WHEN v_sort_upper = 'HOTEN DESC'     THEN p.HO_TEN_ORDER       END DESC NULLS LAST,
        CASE WHEN v_sort_upper = 'SOHSLD ASC'        THEN p.SO_HO_SO          END ASC  NULLS LAST,
        CASE WHEN v_sort_upper = 'SOHSLD DESC'       THEN p.SO_HO_SO          END DESC NULLS LAST,
        CASE WHEN v_sort_upper = 'TOIDANH ASC'       THEN p.TOI_DANH_DAU_TIEN_NAME END ASC  NULLS LAST,
        CASE WHEN v_sort_upper = 'TOIDANH DESC'      THEN p.TOI_DANH_DAU_TIEN_NAME END DESC NULLS LAST,
        CASE WHEN v_sort_upper = 'NGAYDENTRAI ASC'  THEN p.NGAY_DEN_TRAI     END ASC  NULLS LAST,
        CASE WHEN v_sort_upper = 'NGAYDENTRAI DESC' THEN p.NGAY_DEN_TRAI     END DESC NULLS LAST,
        CASE WHEN v_sort_upper NOT IN (
            'NGAYSINH ASC', 'NGAYSINH DESC', 'NGAYBAT ASC', 'NGAYBAT DESC',
            'NGAYHETHAN ASC', 'NGAYHETHAN DESC', 'ANPHAT ASC', 'ANPHAT DESC', 'HOTEN DESC',
            'SOHSLD ASC', 'SOHSLD DESC', 'TOIDANH ASC', 'TOIDANH DESC',
            'NGAYDENTRAI ASC', 'NGAYDENTRAI DESC'
        ) THEN p.HO_TEN_ORDER END ASC NULLS LAST,
        p.PHAM_NHAN_ID DESC,
        p.CCCD;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i t\00ecm ki\1ebfm l\00e1i l\1ecbch: ' || SQLERRM
        );



-- BEGIN
--     QLPN.SP_GET_TIM_KIEM_PN_LAI_LICH(
--         p_like_dash       => N'Nguy?n V?n',
--         p_sort            => N'NGAYSINH DESC',
--         p_maxresultcount  => 25,
--         p_skipcount       => 0
--     );
-- END;
END ;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TIM_KIEM_PN_LAI_LICH_130826
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TIM_KIEM_PN_LAI_LICH_130826" (
    p_ma_trai_giam          IN NVARCHAR2 DEFAULT NULL,
        -- DM_TRAI_GIAMS.TG_MA — l?c theo tr?i; NULL ho?c N'C10' = toàn C10
    p_so_hsld               IN NVARCHAR2 DEFAULT NULL,
    p_cccd                  IN NVARCHAR2 DEFAULT NULL,
    p_ho_ten                IN NVARCHAR2 DEFAULT NULL,
    p_ngay_sinh             IN VARCHAR2  DEFAULT NULL,
    p_gioi_tinh_id          IN NUMBER    DEFAULT NULL,
    p_ho_ten_bo             IN NVARCHAR2 DEFAULT NULL,
    p_ho_ten_me             IN NVARCHAR2 DEFAULT NULL,
    p_ho_ten_vo_chong       IN NVARCHAR2 DEFAULT NULL,
    p_tinh_trang_id         IN NUMBER    DEFAULT NULL,
    p_dan_toc_id            IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id          IN NUMBER    DEFAULT NULL,
    p_ton_giao_id           IN NUMBER    DEFAULT NULL,
    p_toi_danh              IN NUMBER    DEFAULT NULL,  -- ID t?i danh (DM_TOI_DANHS.ID)
    p_ngay_bat              IN VARCHAR2  DEFAULT NULL,
    p_noi_dang_ky_tt        IN NVARCHAR2 DEFAULT NULL,
    p_ve_cu_tru             IN NVARCHAR2 DEFAULT NULL,
    p_den_trai_tu_ngay      IN VARCHAR2  DEFAULT NULL,
    p_den_trai_den_ngay     IN VARCHAR2  DEFAULT NULL,
    p_phan_doi              IN NUMBER    DEFAULT NULL,  -- DM_PHAN_DOIS.ID
    p_phan_trai             IN NUMBER    DEFAULT NULL,  -- DM_PHAN_TRAIS.ID
    p_het_an_tu_ngay        IN VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY — THA_NGAY_HET_HAN >=
    p_het_an_den_ngay       IN VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY — THA_NGAY_HET_HAN <=
    p_so_ban_an             IN NVARCHAR2 DEFAULT NULL,  -- PN_THI_HANH_AN.THA_SO_BAN_AN
    p_so_qd_tha             IN NVARCHAR2 DEFAULT NULL,  -- PN_THI_HANH_AN.THA_SO_QD_THA
    p_ma_an_phat            IN NVARCHAR2 DEFAULT NULL,  -- PN_LAI_LICH_CHI_TIET_RT.THA_MA_AN_PHAT, kh?p ?úng (=)
    p_trinh_do_hoc_van_id   IN NUMBER    DEFAULT NULL,  -- PN_LAI_LICH_CHI_TIET_RT.LL_DM_HOC_VAN_ID
    p_like_dash             IN NVARCHAR2 DEFAULT NULL,
    p_dash_loai_tk          IN NUMBER    DEFAULT NULL,
        -- 1: S? ph?m nhân tháng tr??c chuy?n sang (??u k?)
        -- 2: S? t?ng trong tháng
        -- 3: S? gi?m trong tháng
        -- 4: ?ang ch?p hành án (Cu?i k?)
    p_stt_tong_hop          IN NUMBER    DEFAULT NULL,
        -- 1 ??n 16 t??ng ?ng v?i STT trong V_TK_TONG_HOP_TINH_TRANG_DASHBOARD

    p_maxresultcount        IN NUMBER    DEFAULT 25,
    p_skipcount             IN NUMBER    DEFAULT 0,
    p_sort                  IN NVARCHAR2 DEFAULT NULL
        -- 'HOTEN'|'NGAYSINH'|'NGAYBAT'|'NGAYHETHAN'|'ANPHAT'|'SOHSLD'|'TOIDANH'|'NGAYDENTRAI' + ' ASC'|' DESC' (vd N'NGAYSINH DESC').
        -- NULL ho?c giá tr? không h?p l? = m?c ??nh HO_TEN_ORDER ASC, PHAM_NHAN_ID DESC.
        -- C? tình KHÔNG dùng dynamic SQL: SQL text luôn c? ??nh (whitelist qua CASE WHEN)
        -- ?? không phá v? FIRST_ROWS(100) plan / gây hard parse theo t?ng giá tr? sort (xem comment filtered_prep).

) AS
    v_skip        NUMBER;
    v_limit       NUMBER;
    v_ngay_xet    DATE;
    v_like_ngaysinh VARCHAR2(4000);
    v_ngay_bat    DATE;
    v_den_trai_tu_ngay    DATE;
    v_den_trai_den_ngay   DATE;
    v_het_an_tu_ngay      DATE;
    v_het_an_den_ngay     DATE;
    v_like_so_ban_an      VARCHAR2(4000);
    v_like_so_qd_tha      VARCHAR2(4000);
    v_like_hoten  VARCHAR2(4000);
    v_like_cccd   VARCHAR2(4000);
    v_like_hs     VARCHAR2(4000);
    v_toi_danh_id NUMBER;
    v_like_dktt   VARCHAR2(4000);
    v_like_cu_tru VARCHAR2(4000);
    v_like_bo     VARCHAR2(4000);
    v_like_me     VARCHAR2(4000);
    v_like_vc     VARCHAR2(4000);
    v_like_dash   VARCHAR2(4000);
    v_dash_tu_ngay TIMESTAMP;
    v_dash_den_ngay TIMESTAMP;
    v_dash_ngay_xet DATE;              -- LEAST(DEN_NGAY, SYSDATE) — ??ng b? NGAY_XET SP_TK_THANG
    v_dash_ngay_xet_exclusive DATE;    -- NGAY_XET + 1 giây — kh?p biên k? dashboard
    v_text_filter_cnt    NUMBER;
    v_address_filter_cnt NUMBER;
    v_tha_filter_cnt     NUMBER;
    v_tn_filter_cnt      NUMBER;  -- filter thân nhân (b?/m?/v? ch?ng) — tham gia scope-count nh? text/??a ch?/THA
    v_ll_trai_giam_id    NUMBER;  -- resolve TG_MA ? ID ?? partition prune PN_LAI_LICH_CHI_TIET_RT
    v_sort_upper  VARCHAR2(100);  -- p_sort chu?n hoá 'FIELD ASC'/'FIELD DESC', ??i chi?u whitelist b?ng CASE WHEN (static SQL)
    c1            SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);
    v_sort_upper := UPPER(TRIM(NVL(p_sort, '')));

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL
       AND TRIM(p_ma_trai_giam) IS NOT NULL
    THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                v_ll_trai_giam_id := NULL;
        END;
    END IF;

    v_ngay_xet := TRUNC(SYSDATE);

    IF p_ngay_sinh IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ngay_sinh))) > 0 THEN
        v_like_ngaysinh := '%' || TRIM(TO_CHAR(p_ngay_sinh)) || '%';
    ELSE
        v_like_ngaysinh := NULL;
    END IF;

    IF p_ngay_bat IS NULL OR TRIM(p_ngay_bat) = '' THEN
        v_ngay_bat := NULL;
    ELSE
        -- DEFAULT NULL ON CONVERSION ERROR: input sai ??nh d?ng/ngày không h?p l? (vd tháng 13) thì b? qua filter thay vì ORA-01843 s?p c? tìm ki?m
        v_ngay_bat := TRUNC(TO_DATE(TRIM(p_ngay_bat) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY'));
    END IF;

    IF TO_NUMBER(TO_CHAR(SYSDATE, 'DD')) < 15 THEN
        v_dash_tu_ngay  := ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1) + 14;
        v_dash_den_ngay := TRUNC(SYSDATE, 'MM') + 13;
    ELSE
        v_dash_tu_ngay  := TRUNC(SYSDATE, 'MM') + 14;
        v_dash_den_ngay := ADD_MONTHS(TRUNC(SYSDATE, 'MM'), 1) + 13;
    END IF;
    v_dash_ngay_xet := LEAST(TRUNC(CAST(v_dash_den_ngay AS DATE)), TRUNC(SYSDATE));
    v_dash_ngay_xet_exclusive := v_dash_ngay_xet + (1 / 86400);

     IF p_den_trai_tu_ngay IS NULL OR TRIM(p_den_trai_tu_ngay) = '' THEN
        v_den_trai_tu_ngay := NULL;
    ELSE
        v_den_trai_tu_ngay := TRUNC(TO_DATE(TRIM(p_den_trai_tu_ngay) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY'));
    END IF;

     IF p_den_trai_den_ngay IS NULL OR TRIM(p_den_trai_den_ngay) = '' THEN
        v_den_trai_den_ngay := NULL;
    ELSE
        v_den_trai_den_ngay := TRUNC(TO_DATE(TRIM(p_den_trai_den_ngay) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY'));
    END IF;

    IF p_het_an_tu_ngay IS NULL OR TRIM(p_het_an_tu_ngay) = '' THEN
        v_het_an_tu_ngay := NULL;
    ELSE
        v_het_an_tu_ngay := TRUNC(TO_DATE(TRIM(p_het_an_tu_ngay) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY'));
    END IF;

    IF p_het_an_den_ngay IS NULL OR TRIM(p_het_an_den_ngay) = '' THEN
        v_het_an_den_ngay := NULL;
    ELSE
        v_het_an_den_ngay := TRUNC(TO_DATE(TRIM(p_het_an_den_ngay) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY'));
    END IF;

    IF p_so_ban_an IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_so_ban_an))) > 0 THEN
        v_like_so_ban_an := '%' || UPPER(TRIM(TO_CHAR(NVL(p_so_ban_an, u'')))) || '%';
    ELSE
        v_like_so_ban_an := NULL;
    END IF;

    IF p_so_qd_tha IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_so_qd_tha))) > 0 THEN
        v_like_so_qd_tha := '%' || UPPER(TRIM(TO_CHAR(NVL(p_so_qd_tha, u'')))) || '%';
    ELSE
        v_like_so_qd_tha := NULL;
    END IF;

    IF p_ho_ten IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ho_ten))) > 0 THEN
        v_like_hoten := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ho_ten, u''))))) ;
    ELSE
        v_like_hoten := NULL;
    END IF;

    -- LL_CCCD / LL_SO_HO_SO_LAN_DAU là chu?i s? ? LIKE th?ng trên c?t,
    -- không qua FN_NORMALIZE_VN (kh?p composite index IX_PN_LLCT_RT_CCCD / _SOHS)
    IF p_cccd IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_cccd))) > 0 THEN
        v_like_cccd := '%' || TRIM(TO_CHAR(NVL(p_cccd, u''))) || '%';
    ELSE
        v_like_cccd := NULL;
    END IF;

    IF p_so_hsld IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_so_hsld))) > 0 THEN
        v_like_hs := '%' || TRIM(TO_CHAR(NVL(p_so_hsld, u''))) || '%';
    ELSE
        v_like_hs := NULL;
    END IF;

    IF p_like_dash IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_like_dash))) > 0 THEN
        v_like_dash := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_like_dash, u''))))) || '%';
    ELSE
        v_like_dash := NULL;
    END IF;

    v_toi_danh_id := p_toi_danh;

    IF p_noi_dang_ky_tt IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_noi_dang_ky_tt))) > 0 THEN
        v_like_dktt := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_noi_dang_ky_tt, u''))))) || '%';
    ELSE
        v_like_dktt := NULL;
    END IF;

    IF p_ve_cu_tru IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ve_cu_tru))) > 0 THEN
        v_like_cu_tru := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ve_cu_tru, u''))))) || '%';
    ELSE
        v_like_cu_tru := NULL;
    END IF;

    IF p_ho_ten_bo IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ho_ten_bo))) > 0 THEN
        v_like_bo := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ho_ten_bo, u'')))));
    ELSE
        v_like_bo := NULL;
    END IF;

    IF p_ho_ten_me IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ho_ten_me))) > 0 THEN
        v_like_me := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ho_ten_me, u'')))));
    ELSE
        v_like_me := NULL;
    END IF;

    IF p_ho_ten_vo_chong IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ho_ten_vo_chong))) > 0 THEN
        v_like_vc := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ho_ten_vo_chong, u''))))) ;
    ELSE
        v_like_vc := NULL;
    END IF;

    v_text_filter_cnt :=
          CASE WHEN v_like_hoten IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_cccd IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_hs IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_dash IS NOT NULL THEN 1 ELSE 0 END;

    v_address_filter_cnt :=
          CASE WHEN v_like_dktt IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_cu_tru IS NOT NULL THEN 1 ELSE 0 END;

    v_tha_filter_cnt :=
          CASE
              WHEN v_toi_danh_id IS NOT NULL
                OR v_ngay_bat IS NOT NULL
                OR v_den_trai_tu_ngay IS NOT NULL
                OR v_den_trai_den_ngay IS NOT NULL
                OR v_het_an_tu_ngay IS NOT NULL
                OR v_het_an_den_ngay IS NOT NULL
                OR v_like_so_ban_an IS NOT NULL
                OR v_like_so_qd_tha IS NOT NULL
              THEN 1
              ELSE 0
          END;

    v_tn_filter_cnt :=
          CASE WHEN v_like_bo IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_me IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_vc IS NOT NULL THEN 1 ELSE 0 END;

    OPEN c1 FOR
    WITH
    -- ===== Priority 1/2: Pre-compute ID sets cho p_dash_loai_tk — thay correlated EXISTS/FN per-row =====

    -- Pre-compute valid trai IDs — thay 3 EXISTS correlated trên DM_TRAI_GIAMS b?ng 1 hash lookup
    valid_trai_ids AS (
        SELECT /*+ MATERIALIZE */ ID
        FROM QLPN.DM_TRAI_GIAMS
        WHERE NVL(IS_DELETED, 0) = 0
    ),
    -- TOI_DANH_DAU_TIEN trên RT là ID t?i danh (vd '878'), KHÔNG ph?i tên — resolve tên qua DM nh? (1747 dòng)
    -- ?? p_sort=TOIDANH s?p x?p theo tên (alphabet), không ph?i theo chu?i ID
    dm_toi_danh_ten AS (
        -- TRIM: ~40% DM_TOI_DANHS.TD_TEN có kho?ng tr?ng/tab ??u chu?i không ??ng nh?t,
        -- ?? nguyên s? làm sai th? t? alphabet khi sort theo tên
        SELECT /*+ MATERIALIZE */ ID, TRIM(TD_TEN) AS TD_TEN
        FROM QLPN.DM_TOI_DANHS
        WHERE NVL(IS_DELETED, 0) = 0
    ),
    -- Tr?ng thái hôm nay t? cache — thay toàn b? DM_TINH_TRANG_PHAM_NHANS join per-row
    -- cho loai_tk=4, p_stt_tong_hop 1-10 và driver_rows (hash join O(1) thay scalar FN)
    cache_today AS (
        SELECT /*+ MATERIALIZE */ PN_LAI_LICH_ID, TTPN_MA
          FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE
         WHERE NGAY_XET = TRUNC(SYSDATE)
           -- TTPN_MA ch? ???c ??c khi loai_tk=4 ho?c stt_tong_hop 1-10 (11-16 dùng EXISTS riêng,
           -- 7 ch? dùng ngày) — path khác ?? CTE r?ng, kh?i materialize 1.5M dòng vô ích
           AND (p_dash_loai_tk = 4 OR (p_stt_tong_hop IS NOT NULL AND p_stt_tong_hop <= 10))
    ),
    -- Ch? c?t c?n dùng — tránh materialize RT.* (THA_TOI_DANH_NAMES 16KB × 1.5M ? temp kh?ng l?)
    rt_trai AS (
        SELECT /*+ MATERIALIZE */
            RT.PHAM_NHAN_ID,
            RT.IS_DELETED,
            RT.LL_TRAI_GIAM_ID,
            RT.LL_HO_TEN,
            RT.HO_TEN_ORDER,
            RT.LL_PHAN_DOI_ID,
            RT.LL_PHAN_TRAI_ID,
            -- C?t text/??a ch? (LL_CCCD, LL_DIA_CHI_*, LL_NOI_THA_VE_*) ?ã b?:
            -- các candidate CTE ??c RT g?c tr?c ti?p, gi? ? ?ây ch? t?n temp write khi materialize.
            -- LL_SO_HO_SO_LAN_DAU (VARCHAR2 50) và TOI_DANH_DAU_TIEN_NAME (tên t?i danh, ?ã resolve qua
            -- dm_toi_danh_ten — không ph?i THA_TOI_DANH_NAMES 32KB) ???c gi? l?i làm sort key cho
            -- p_sort SOHSLD/TOIDANH.
            RT.LL_SO_HO_SO_LAN_DAU,
            RT.LL_NGAY_SINH,
            RT.LL_TINH_TRANG_ID,
            RT.LL_DM_GIOI_TINH_ID,
            RT.LL_DM_DAN_TOC_ID,
            RT.LL_DM_QUOC_TICH_ID,
            RT.LL_DM_TON_GIAO_ID,
            RT.LL_DM_HOC_VAN_ID,
            RT.THA_ID,
            RT.THA_DOI_TUONG,
            RT.THA_NGAY_BAT,
            RT.THA_NGAY_DEN_TRAI,
            RT.THA_NGAY_HET_HAN,
            RT.THA_AN_PHAT,
            RT.THA_MA_AN_PHAT,
            dtd.TD_TEN AS TOI_DANH_DAU_TIEN_NAME
          FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
          LEFT JOIN dm_toi_danh_ten dtd
            ON dtd.ID = TO_NUMBER(RT.TOI_DANH_DAU_TIEN DEFAULT NULL ON CONVERSION ERROR)
         WHERE NVL(RT.IS_DELETED, 0) = 0
           AND RT.LL_TRAI_GIAM_ID IS NOT NULL
           AND RT.LL_TRAI_GIAM_ID IN (SELECT ID FROM valid_trai_ids)
           AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
           -- PERF: ch? materialize toàn b? RT khi TH?C S? c?n (dashboard c?n rt_trai cho tang/giam/??u k?,
           --       ho?c path li?t kê KHÔNG có filter text/??a ch?/t?i danh/thân nhân). Khi có filter free + non-dashboard,
           --       driver_rows lái t? candidate ids + PK-join RT g?c nên rt_trai ?? R?NG (FILTER h?ng s? ? b? scan 3.15M).
           AND (
                p_dash_loai_tk IS NOT NULL
             OR (v_text_filter_cnt = 0 AND v_address_filter_cnt = 0 AND v_tha_filter_cnt = 0 AND v_tn_filter_cnt = 0)
           )
    ),
    -- Priority 1: T?ng trong k? (loai_tk=2) — ??ng b? SP_QLPN_GET_TK_THANG_DASHBOARD (rt_trai)
    tang_ids AS (
        SELECT /*+ MATERIALIZE CARDINALITY(tang_union 5000) */ ID FROM (
        SELECT RT.PHAM_NHAN_ID AS ID
        FROM rt_trai RT
        JOIN QLPN.DM_LOAI_DOI_TUONGS LDT ON LDT.ID = RT.THA_DOI_TUONG AND NVL(LDT.IS_DELETED, 0) = 0
        WHERE p_dash_loai_tk = 2
          AND CASE WHEN v_ll_trai_giam_id IS NULL THEN RT.THA_NGAY_BAT ELSE RT.THA_NGAY_DEN_TRAI END >= v_dash_tu_ngay
          AND CASE WHEN v_ll_trai_giam_id IS NULL THEN RT.THA_NGAY_BAT ELSE RT.THA_NGAY_DEN_TRAI END < v_dash_ngay_xet_exclusive
          AND LDT.LDT_MA IN ('20211', '20212', '110', '120', '20221', '20324')
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.TRON_TRAIS TT
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TT.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND TT.NGAY_BAT_LAI >= v_dash_tu_ngay
          AND TT.NGAY_BAT_LAI < v_dash_ngay_xet_exclusive
          AND CAST(TT.NGAY_BAT_LAI AS DATE) >= CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND NVL(TT.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.TAM_DINH_CHIS TDC
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TDC.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND TDC.NGAY_LAI >= v_dash_tu_ngay
          AND TDC.NGAY_LAI < v_dash_ngay_xet_exclusive
          AND CAST(TDC.NGAY_TDC AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND TDC.LOAI_QUYET_DINH_ID = 1
          AND NVL(TDC.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.TRICH_XUATS TX
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TX.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND TX.TX_NGAY_TRA >= v_dash_tu_ngay
          AND TX.TX_NGAY_TRA < v_dash_ngay_xet_exclusive
          AND CAST(TX.TX_NGAY_TRICH_XUAT AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND TX.TX_LOAI_LENH_ID = 1
          AND NVL(TX.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.HUY_ANS HA
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = HA.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND HA.NGAY_TRO_LAI >= v_dash_tu_ngay
          AND HA.NGAY_TRO_LAI < v_dash_ngay_xet_exclusive
          AND CAST(HA.NGAY_TRA_TU_DO AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND NVL(HA.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.THA_CO_DIEU_KIENS TCK
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TCK.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND TCK.NGAY_BAT_LAI >= v_dash_tu_ngay
          AND TCK.NGAY_BAT_LAI < v_dash_ngay_xet_exclusive
          AND NVL(TCK.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.CHUA_BENH_BAT_BUOCS CB
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = CB.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND CB.NGAY_KET_THUC >= v_dash_tu_ngay
          AND CB.NGAY_KET_THUC < v_dash_ngay_xet_exclusive
          AND NVL(CB.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        ) tang_union
    ),
    -- Priority 1: Gi?m trong k? (loai_tk=3) — ??ng b? SP_QLPN_GET_TK_THANG_DASHBOARD (PN_LAI_LICH_CHI_TIET_RT)
    giam_ids AS (
        SELECT /*+ MATERIALIZE CARDINALITY(giam_union 5000) */ ID FROM (
        SELECT TT.PHAM_NHAN_ID AS ID
        FROM QLPN.TRON_TRAIS TT
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TT.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND TT.NGAY_TRON >= v_dash_tu_ngay
          AND TT.NGAY_TRON < v_dash_ngay_xet_exclusive
          AND CAST(TT.NGAY_TRON AS DATE) >= CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND NVL(TT.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT KC.KTC_PN_LAI_LICH_ID
        FROM QLPN.PN_KET_THUC_CHETS KC
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = KC.KTC_PN_LAI_LICH_ID
        LEFT JOIN QLPN.DM_TRUONG_HOP_CHETS THC ON THC.ID = KC.KTC_DM_TRUONG_HOP_CHET_ID
        WHERE p_dash_loai_tk = 3
          AND KC.KTC_NGAY_CHET >= v_dash_tu_ngay
          AND KC.KTC_NGAY_CHET < v_dash_ngay_xet_exclusive
          AND CAST(KC.KTC_NGAY_CHET AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND NVL(THC.THC_MA, '10') NOT IN ('30', '40', '50')
          AND NVL(KC.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT TX.PHAM_NHAN_ID
        FROM QLPN.TRICH_XUATS TX
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TX.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND TX.TX_NGAY_TRICH_XUAT >= v_dash_tu_ngay
          AND TX.TX_NGAY_TRICH_XUAT < v_dash_ngay_xet_exclusive
          AND TX.TX_LOAI_LENH_ID = 1
          AND NVL(TX.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT TDC.PHAM_NHAN_ID
        FROM QLPN.TAM_DINH_CHIS TDC
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TDC.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND TDC.NGAY_TDC >= v_dash_tu_ngay
          AND TDC.NGAY_TDC < v_dash_ngay_xet_exclusive
          AND CAST(TDC.NGAY_TDC AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND TDC.LOAI_QUYET_DINH_ID = 1
          AND NVL(TDC.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT CT.PNCT_LAI_LICH_ID
        FROM QLPN.PHAM_NHAN_CHUYEN_TRAI CT
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = CT.PNCT_LAI_LICH_ID
        LEFT JOIN QLPN.DM_TRUONG_HOP_CHUYEN_TRAIS THCT ON THCT.ID = CT.PNCT_TRUONG_HOP_CHUYEN_ID
        WHERE p_dash_loai_tk = 3
          AND v_ll_trai_giam_id IS NOT NULL
          AND CT.PNCT_NGAY_CHUYEN >= v_dash_tu_ngay
          AND CT.PNCT_NGAY_CHUYEN < v_dash_ngay_xet_exclusive
          AND NVL(THCT.THCT_MA, '10') IN ('10', '20', '90')
          AND NVL(CT.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT HA.PHAM_NHAN_ID
        FROM QLPN.HUY_ANS HA
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = HA.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND HA.NGAY_TRA_TU_DO >= v_dash_tu_ngay
          AND HA.NGAY_TRA_TU_DO < v_dash_ngay_xet_exclusive
          AND NVL(HA.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND HA.PHAM_NHAN_ID NOT IN (
                SELECT TX.PHAM_NHAN_ID
                FROM QLPN.TRICH_XUATS TX
                WHERE TX.TX_LOAI_LENH_ID = 1
                  AND (TX.TX_NGAY_TRA IS NULL
                       OR TX.TX_NGAY_TRA >= v_dash_ngay_xet_exclusive))
        UNION
        SELECT HTHA.PHAM_NHAN_ID
        FROM QLPN.HOAN_THI_HANH_ANS HTHA
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = HTHA.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND HTHA.NGAY_HOAN >= v_dash_tu_ngay
          AND HTHA.NGAY_HOAN < v_dash_ngay_xet_exclusive
          AND NVL(HTHA.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT MHP.PN_LAI_LICH_ID
        FROM QLPN.MIEN_HINH_PHATS MHP
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = MHP.PN_LAI_LICH_ID
        WHERE p_dash_loai_tk = 3
          AND MHP.MHP_NGAY_TU_DO >= v_dash_tu_ngay
          AND MHP.MHP_NGAY_TU_DO < v_dash_ngay_xet_exclusive
          AND NVL(MHP.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT CB.PHAM_NHAN_ID
        FROM QLPN.CHUA_BENH_BAT_BUOCS CB
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = CB.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND CB.NGAY_BAT_DAU >= v_dash_tu_ngay
          AND CB.NGAY_BAT_DAU < v_dash_ngay_xet_exclusive
          AND NVL(CB.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT CG.PNCG_LAI_LICH_ID
        FROM QLPN.PN_CHUYEN_GIAO CG
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = CG.PNCG_LAI_LICH_ID
        LEFT JOIN QLPN.DM_QUOC_TICHS QT ON QT.ID = CG.PNCG_NUOC_CHUYEN_GIAO_ID
        WHERE p_dash_loai_tk = 3
          AND CG.PNCG_NGAY_CHUYEN_GIAO >= v_dash_tu_ngay
          AND CG.PNCG_NGAY_CHUYEN_GIAO < v_dash_ngay_xet_exclusive
          AND NVL(QT.QT_MA, '000') <> '250'
          AND NVL(CG.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT KT.KTRT_PN_LAI_LICH_ID
        FROM QLPN.PN_KET_THUC_RA_TRAIS KT
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = KT.KTRT_PN_LAI_LICH_ID
        WHERE p_dash_loai_tk = 3
          AND KT.KTRT_NGAY_THA >= v_dash_tu_ngay
          AND KT.KTRT_NGAY_THA < v_dash_ngay_xet_exclusive
          AND NVL(KT.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT DX.PNLAI_LICH_ID
        FROM QLPN.PN_DAC_XAS DX
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = DX.PNLAI_LICH_ID
        WHERE p_dash_loai_tk = 3
          AND DX.DX_NGAY_THA >= v_dash_tu_ngay
          AND DX.DX_NGAY_THA < v_dash_ngay_xet_exclusive
          AND DX.DX_TINH_TRANG_DAC_XA IN ('1', '2', '7')
          AND NVL(DX.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT TCK.PHAM_NHAN_ID
        FROM QLPN.THA_CO_DIEU_KIENS TCK
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TCK.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND TCK.NGAY_THA >= v_dash_tu_ngay
          AND TCK.NGAY_THA < v_dash_ngay_xet_exclusive
          AND (TCK.NGAY_BAT_LAI IS NULL OR TCK.NGAY_BAT_LAI >= v_dash_ngay_xet_exclusive)
          AND NVL(TCK.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        ) giam_union
    ),
    -- ??u k? (loai_tk=1) — ??c PN_TK_THANG_DAU_KY_IDS (pre-compute b?i SP_TK_THANG)
    dau_ky_ids AS (
        SELECT /*+ MATERIALIZE CARDINALITY(dau_ky_ids 500000) */ PHAM_NHAN_ID AS ID
        FROM QLPN.PN_TK_THANG_DAU_KY_IDS
        WHERE p_dash_loai_tk = 1
          AND TU_NGAY = TO_CHAR(CAST(v_dash_tu_ngay AS DATE), 'DD/MM/YYYY')
          AND DEN_NGAY = TO_CHAR(CAST(v_dash_den_ngay AS DATE), 'DD/MM/YYYY')
          AND (v_ll_trai_giam_id IS NULL OR MA_TRAI_GIAM = TRIM(p_ma_trai_giam))
    ),
    -- P0-1: Gom ID dashboard — drive hash join thay OR + full scan PN_LAI_LICHS
    dash_eligible_ids AS (
        SELECT /*+ MATERIALIZE CARDINALITY(dau_ky_ids 500000) */ ID FROM dau_ky_ids WHERE p_dash_loai_tk = 1
        UNION
        SELECT /*+ CARDINALITY(tang_ids 5000) */ ID FROM tang_ids WHERE p_dash_loai_tk = 2
        UNION
        SELECT /*+ CARDINALITY(giam_ids 5000) */ ID FROM giam_ids WHERE p_dash_loai_tk = 3
        UNION
        SELECT /*+ CARDINALITY(RT 500000) */ RT.PHAM_NHAN_ID AS ID
        FROM rt_trai RT
        JOIN cache_today c ON c.PN_LAI_LICH_ID = RT.PHAM_NHAN_ID
                          AND c.TTPN_MA IN ('111', '112', '113', '114')
        WHERE p_dash_loai_tk = 4
    ),
    -- FBI drive: ?u tiên INDEX_FFS trên composite FBI IX_PN_LLCT_RT_NORMHOTEN
    --   (norm_hoten, IS_DELETED, LL_TRAI_GIAM_ID, PHAM_NHAN_ID — DDL_COMPOSITE_FBI_TIM_KIEM_RT.sql):
    --   index-only, multiblock I/O, không g?i l?i FN_NORMALIZE_VN (function avalanche ~35s trên 3.15M).
    --   Hint INDEX trên FBI 1 c?t gi? làm fallback cho môi tr??ng ch?a ch?y DDL (hint index
    --   không t?n t?i s? t? b? b? qua) ? INDEX FULL SCAN + TABLE ACCESS BY ROWID, v?n tránh g?i UDF.
    hoten_candidate_ids AS (
        SELECT /*+ MATERIALIZE INDEX_FFS(RT IX_PN_LLCT_RT_NORMHOTEN) INDEX(RT IX_PN_LLCT_RT_FBI_HO_TEN) */ RT.PHAM_NHAN_ID AS ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
        WHERE v_like_hoten IS NOT NULL
          AND NVL(RT.IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(RT.LL_HO_TEN)), 1, 400) LIKE v_like_hoten
    ),
    -- CCCD/s? HS: chu?i s? — LIKE th?ng trên c?t, composite index th??ng (không FBI, không UDF)
    cccd_candidate_ids AS (
        SELECT /*+ MATERIALIZE INDEX_FFS(RT IX_PN_LLCT_RT_CCCD) */ RT.PHAM_NHAN_ID AS ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
        WHERE v_like_cccd IS NOT NULL
          AND NVL(RT.IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
          AND RT.LL_CCCD LIKE v_like_cccd
    ),
    so_hs_candidate_ids AS (
        SELECT /*+ MATERIALIZE INDEX_FFS(RT IX_PN_LLCT_RT_SOHS) */ RT.PHAM_NHAN_ID AS ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
        WHERE v_like_hs IS NOT NULL
          AND NVL(RT.IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
          AND RT.LL_SO_HO_SO_LAN_DAU LIKE v_like_hs
    ),
    dash_text_candidate_ids AS (
        SELECT /*+ MATERIALIZE */ ID FROM (
            SELECT /*+ INDEX_FFS(RT IX_PN_LLCT_RT_SOHS) */ RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_dash IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              -- v_like_dash ?ã normalize; s? HS là chu?i s? nên normalize(input s?) = input s?
              AND RT.LL_SO_HO_SO_LAN_DAU LIKE v_like_dash
            UNION
            SELECT /*+ INDEX_FFS(RT IX_PN_LLCT_RT_CCCD) */ RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_dash IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              AND RT.LL_CCCD LIKE v_like_dash
            UNION
            SELECT /*+ INDEX_FFS(RT IX_PN_LLCT_RT_NORMHOTEN) INDEX(RT IX_PN_LLCT_RT_FBI_HO_TEN) */ RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_dash IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(RT.LL_HO_TEN)), 1, 400) LIKE v_like_dash
        )
    ),
    -- Giao các filter text (AND gi?a ho ten / cccd / so hs / dash)
    text_scope_ids AS (
        SELECT /*+ MATERIALIZE */ u.ID
        FROM (
            SELECT ID, 1 AS f FROM hoten_candidate_ids WHERE v_like_hoten IS NOT NULL
            UNION ALL
            SELECT ID, 2 AS f FROM cccd_candidate_ids WHERE v_like_cccd IS NOT NULL
            UNION ALL
            SELECT ID, 3 AS f FROM so_hs_candidate_ids WHERE v_like_hs IS NOT NULL
            UNION ALL
            SELECT ID, 4 AS f FROM dash_text_candidate_ids WHERE v_like_dash IS NOT NULL
        ) u
        GROUP BY u.ID
        HAVING COUNT(DISTINCT u.f) = v_text_filter_cnt
           AND v_text_filter_cnt > 0
    ),
    -- === ??a ch?: pre-compute DM ward/province tr??c khi drive scope ===
    matching_ward_ids AS (
        SELECT /*+ MATERIALIZE */ dxp.ID
        FROM QLPN.DM_XA_PHUONG dxp
        WHERE v_like_dktt IS NOT NULL
          AND NVL(dxp.IS_DELETED, 0) = 0
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(dxp.XP_TEN)), 1, 400) LIKE v_like_dktt
    ),
    matching_province_ids AS (
        SELECT /*+ MATERIALIZE */ dttp.ID
        FROM QLPN.DM_TINH_THANH_PHO dttp
        WHERE v_like_dktt IS NOT NULL
          AND NVL(dttp.IS_DELETED, 0) = 0
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(dttp.TTP_TEN)), 1, 400) LIKE v_like_dktt
    ),
    matching_cu_tru_ward_ids AS (
        SELECT /*+ MATERIALIZE */ dxp.ID
        FROM QLPN.DM_XA_PHUONG dxp
        WHERE v_like_cu_tru IS NOT NULL
          AND NVL(dxp.IS_DELETED, 0) = 0
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(dxp.XP_TEN)), 1, 400) LIKE v_like_cu_tru
    ),
    matching_cu_tru_province_ids AS (
        SELECT /*+ MATERIALIZE */ dttp.ID
        FROM QLPN.DM_TINH_THANH_PHO dttp
        WHERE v_like_cu_tru IS NOT NULL
          AND NVL(dttp.IS_DELETED, 0) = 0
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(dttp.TTP_TEN)), 1, 400) LIKE v_like_cu_tru
    ),
    -- FBI text + FK ward/province (OR trong t?ng nhóm ??a ch?) — drive RT g?c cho FBI ??a ch?
    dktt_scope_ids AS (
        SELECT /*+ MATERIALIZE */ ID FROM (
            SELECT /*+ INDEX_FFS(RT IX_PN_LLCT_RT_NORMDCHT) INDEX(RT IX_PN_LLCT_RT_FBI_DCHT) */ RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_dktt IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(RT.LL_DIA_CHI_THUONG_TRU)), 1, 400) LIKE v_like_dktt
            UNION
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            INNER JOIN matching_ward_ids mw ON mw.ID = RT.LL_DIA_CHI_THUONG_TRU_WARD
            WHERE v_like_dktt IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
            UNION
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            INNER JOIN matching_province_ids mp ON mp.ID = RT.LL_DIA_CHI_THUONG_TRU_PROVICE
            WHERE v_like_dktt IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        )
    ),
    cu_tru_scope_ids AS (
        SELECT /*+ MATERIALIZE */ ID FROM (
            SELECT /*+ INDEX_FFS(RT IX_PN_LLCT_RT_NORMCUTRU) INDEX(RT IX_PN_LLCT_RT_FBI_CU_TRU) */ RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_cu_tru IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(RT.LL_NOI_THA_VE_CU_TRU)), 1, 400) LIKE v_like_cu_tru
            UNION
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            INNER JOIN matching_cu_tru_ward_ids mw ON mw.ID = RT.LL_NOI_THA_VE_CU_TRU_WARD
            WHERE v_like_cu_tru IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
            UNION
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            INNER JOIN matching_cu_tru_province_ids mp ON mp.ID = RT.LL_NOI_THA_VE_CU_TRU_PROVICE
            WHERE v_like_cu_tru IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        )
    ),
    -- AND gi?a ??ng ký TT và v? c? trú khi c? hai có filter
    address_scope_ids AS (
        SELECT /*+ MATERIALIZE */ u.ID
        FROM (
            SELECT ID, 1 AS f FROM dktt_scope_ids WHERE v_like_dktt IS NOT NULL
            UNION ALL
            SELECT ID, 2 AS f FROM cu_tru_scope_ids WHERE v_like_cu_tru IS NOT NULL
        ) u
        GROUP BY u.ID
        HAVING COUNT(DISTINCT u.f) = v_address_filter_cnt
           AND v_address_filter_cnt > 0
    ),
    -- === Quan h? thân nhân — pre-compute 1 l?n t? b?ng DM nh? ===
    qh_bo_ids AS (
        SELECT /*+ MATERIALIZE */ qh.ID
        FROM QLPN.DM_QUAN_HE_VOI_PHAM_NHANS qh
        WHERE v_like_bo IS NOT NULL
          AND UPPER(QLPN.FN_NORMALIZE_VN(qh.QHVPN_TEN)) LIKE 'BO%'
    ),
    qh_me_ids AS (
        SELECT /*+ MATERIALIZE */ qh.ID
        FROM QLPN.DM_QUAN_HE_VOI_PHAM_NHANS qh
        WHERE v_like_me IS NOT NULL
          AND UPPER(QLPN.FN_NORMALIZE_VN(qh.QHVPN_TEN)) LIKE 'ME%'
    ),
    qh_vc_ids AS (
        SELECT /*+ MATERIALIZE */ qh.ID
        FROM QLPN.DM_QUAN_HE_VOI_PHAM_NHANS qh
        WHERE v_like_vc IS NOT NULL
          AND (UPPER(QLPN.FN_NORMALIZE_VN(qh.QHVPN_TEN)) LIKE 'VO%'
            OR UPPER(QLPN.FN_NORMALIZE_VN(qh.QHVPN_TEN)) LIKE 'CHONG%')
    ),
    -- Candidate thân nhân theo tên (superset — ch?a l?c IS_DELETED vì FBI không ch?a c?t này;
    -- re-check chính xác b?ng EXISTS trong filtered_prep). INDEX_FFS index-only trên
    -- IDX_TN_PN_QH_TEN_NORM (PHAM_NHAN_ID, QUAN_HE_ID, norm(HO_TEN_THAN_NHAN)) — quét 1 l?n
    -- thay vì EXISTS t?ng dòng trên toàn b? dân s? khi CH? l?c theo thân nhân.
    tn_bo_candidate_ids AS (
        SELECT /*+ MATERIALIZE INDEX_FFS(tn IDX_TN_PN_QH_TEN_NORM) */ tn.PHAM_NHAN_ID AS ID
        FROM QLPN.THAN_NHAN_NGUOI_THANS tn
        WHERE v_like_bo IS NOT NULL
          AND tn.QUAN_HE_ID IN (SELECT ID FROM qh_bo_ids)
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(tn.HO_TEN_THAN_NHAN)), 1, 400) LIKE v_like_bo
        GROUP BY tn.PHAM_NHAN_ID
    ),
    tn_me_candidate_ids AS (
        SELECT /*+ MATERIALIZE INDEX_FFS(tn IDX_TN_PN_QH_TEN_NORM) */ tn.PHAM_NHAN_ID AS ID
        FROM QLPN.THAN_NHAN_NGUOI_THANS tn
        WHERE v_like_me IS NOT NULL
          AND tn.QUAN_HE_ID IN (SELECT ID FROM qh_me_ids)
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(tn.HO_TEN_THAN_NHAN)), 1, 400) LIKE v_like_me
        GROUP BY tn.PHAM_NHAN_ID
    ),
    tn_vc_candidate_ids AS (
        SELECT /*+ MATERIALIZE INDEX_FFS(tn IDX_TN_PN_QH_TEN_NORM) */ tn.PHAM_NHAN_ID AS ID
        FROM QLPN.THAN_NHAN_NGUOI_THANS tn
        WHERE v_like_vc IS NOT NULL
          AND tn.QUAN_HE_ID IN (SELECT ID FROM qh_vc_ids)
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(tn.HO_TEN_THAN_NHAN)), 1, 400) LIKE v_like_vc
        GROUP BY tn.PHAM_NHAN_ID
    ),
    -- PN_THI_HANH_AN drive: t?i danh + ngày b?t/??n tr?i — 1 l?n thay EXISTS × 1.5M
    toi_danh_scope_ids AS (
        SELECT /*+ MATERIALIZE */ tha.THA_PNLAI_LICH_ID AS ID
        FROM QLPN.PN_THI_HANH_AN tha
        WHERE v_tha_filter_cnt > 0
          AND NVL(tha.IS_DELETED, 0) = 0
          AND (v_toi_danh_id IS NULL OR INSTR(
                  ',' || REPLACE(REPLACE(TRIM(CAST(tha.THA_TOI_DANH AS VARCHAR2(4000))), '[', ''), ']', '') || ',',
                  ',' || TO_CHAR(v_toi_danh_id) || ','
              ) > 0)
          AND (v_ngay_bat IS NULL OR (CAST(tha.THA_NGAY_BAT AS DATE) >= v_ngay_bat AND CAST(tha.THA_NGAY_BAT AS DATE) < v_ngay_bat + 1))
          AND (v_den_trai_tu_ngay IS NULL OR CAST(tha.THA_NGAY_DEN_TRAI AS DATE) >= v_den_trai_tu_ngay)
          AND (v_den_trai_den_ngay IS NULL OR CAST(tha.THA_NGAY_DEN_TRAI AS DATE) < v_den_trai_den_ngay + 1)
          AND (v_het_an_tu_ngay IS NULL OR CAST(tha.THA_NGAY_HET_HAN AS DATE) >= v_het_an_tu_ngay)
          AND (v_het_an_den_ngay IS NULL OR CAST(tha.THA_NGAY_HET_HAN AS DATE) < v_het_an_den_ngay + 1)
          AND (v_like_so_ban_an IS NULL OR UPPER(TRIM(CAST(tha.THA_SO_BAN_AN AS NVARCHAR2(1000)))) LIKE v_like_so_ban_an)
          AND (v_like_so_qd_tha IS NULL OR UPPER(TRIM(CAST(tha.THA_SO_QD_THA AS NVARCHAR2(1000)))) LIKE v_like_so_qd_tha)
        GROUP BY tha.THA_PNLAI_LICH_ID
    ),
    -- Giao text + ??a ch? + THA + thân nhân (AND gi?a các nhóm; m?i filter b?/m?/VC là 1 dim riêng)
    free_scope_ids AS (
        SELECT /*+ MATERIALIZE */ u.ID
        FROM (
            SELECT ID, 1 AS dim FROM text_scope_ids WHERE v_text_filter_cnt > 0
            UNION ALL
            SELECT ID, 2 AS dim FROM address_scope_ids WHERE v_address_filter_cnt > 0
            UNION ALL
            SELECT ID, 3 AS dim FROM toi_danh_scope_ids WHERE v_tha_filter_cnt > 0
            UNION ALL
            SELECT ID, 4 AS dim FROM tn_bo_candidate_ids WHERE v_like_bo IS NOT NULL
            UNION ALL
            SELECT ID, 5 AS dim FROM tn_me_candidate_ids WHERE v_like_me IS NOT NULL
            UNION ALL
            SELECT ID, 6 AS dim FROM tn_vc_candidate_ids WHERE v_like_vc IS NOT NULL
        ) u
        GROUP BY u.ID
        HAVING COUNT(DISTINCT u.dim) =
              (CASE WHEN v_text_filter_cnt > 0 THEN 1 ELSE 0 END
             + CASE WHEN v_address_filter_cnt > 0 THEN 1 ELSE 0 END
             + CASE WHEN v_tha_filter_cnt > 0 THEN 1 ELSE 0 END
             + v_tn_filter_cnt)
           AND (v_text_filter_cnt > 0 OR v_address_filter_cnt > 0 OR v_tha_filter_cnt > 0 OR v_tn_filter_cnt > 0)
    ),
    -- PERF driver_rows: thay "FROM rt_trai + (OR 4 nhánh eligibility)" b?ng lái t? id-set NH? r?i PK-join RT g?c.
    --   Tránh quét/materialize toàn b? 3.15M rt_trai cho path có filter. 4 nhánh (dashboard × có-filter) lo?i tr? & ??:
    --     (a) có free-filter (text/??a ch?/t?i danh/thân nhân) -> lái free_scope_ids, PK-join RT (dashboard thì thêm EXISTS dash_eligible)
    --     (b) dashboard, KHÔNG filter -> lái dash_eligible_ids, PK-join RT
    --     (c) non-dashboard, KHÔNG filter -> toàn b? dân s? -> gi? rt_trai (full)
    --   Các filter per-row (gi?i tính/tình tr?ng/.../stt_tong_hop/thân nhân/THA) áp 1 L?N ? filtered_prep bên d??i.
    driver_rows AS (
        -- (a) có ít nh?t 1 free-filter
        SELECT rt.PHAM_NHAN_ID, rt.LL_HO_TEN, rt.HO_TEN_ORDER, rt.LL_TINH_TRANG_ID,
               rt.LL_DM_GIOI_TINH_ID, rt.LL_DM_DAN_TOC_ID, rt.LL_DM_QUOC_TICH_ID, rt.LL_DM_TON_GIAO_ID,
               rt.LL_DM_HOC_VAN_ID,
               rt.LL_PHAN_DOI_ID, rt.LL_PHAN_TRAI_ID,
               rt.LL_SO_HO_SO_LAN_DAU, dtd_a.TD_TEN AS TOI_DANH_DAU_TIEN_NAME,
               rt.LL_NGAY_SINH, rt.THA_NGAY_BAT, rt.THA_NGAY_DEN_TRAI, rt.THA_NGAY_HET_HAN, rt.THA_AN_PHAT, rt.THA_MA_AN_PHAT,
               c.TTPN_MA
        FROM free_scope_ids s
        JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt ON rt.PHAM_NHAN_ID = s.ID
        LEFT JOIN cache_today c ON c.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN dm_toi_danh_ten dtd_a ON dtd_a.ID = TO_NUMBER(rt.TOI_DANH_DAU_TIEN DEFAULT NULL ON CONVERSION ERROR)
        WHERE (v_text_filter_cnt > 0 OR v_address_filter_cnt > 0 OR v_tha_filter_cnt > 0 OR v_tn_filter_cnt > 0)
          AND NVL(rt.IS_DELETED, 0) = 0
          AND rt.LL_TRAI_GIAM_ID IS NOT NULL
          AND rt.LL_TRAI_GIAM_ID IN (SELECT ID FROM valid_trai_ids)
          AND (v_ll_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
          AND (
                p_dash_loai_tk IS NULL
             OR EXISTS (SELECT 1 FROM dash_eligible_ids d WHERE d.ID = rt.PHAM_NHAN_ID)
          )
        UNION ALL
        -- (b) dashboard, KHÔNG có free-filter
        SELECT rt.PHAM_NHAN_ID, rt.LL_HO_TEN, rt.HO_TEN_ORDER, rt.LL_TINH_TRANG_ID,
               rt.LL_DM_GIOI_TINH_ID, rt.LL_DM_DAN_TOC_ID, rt.LL_DM_QUOC_TICH_ID, rt.LL_DM_TON_GIAO_ID,
               rt.LL_DM_HOC_VAN_ID,
               rt.LL_PHAN_DOI_ID, rt.LL_PHAN_TRAI_ID,
               rt.LL_SO_HO_SO_LAN_DAU, dtd_b.TD_TEN AS TOI_DANH_DAU_TIEN_NAME,
               rt.LL_NGAY_SINH, rt.THA_NGAY_BAT, rt.THA_NGAY_DEN_TRAI, rt.THA_NGAY_HET_HAN, rt.THA_AN_PHAT, rt.THA_MA_AN_PHAT,
               c.TTPN_MA
        FROM dash_eligible_ids d
        JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt ON rt.PHAM_NHAN_ID = d.ID
        LEFT JOIN cache_today c ON c.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN dm_toi_danh_ten dtd_b ON dtd_b.ID = TO_NUMBER(rt.TOI_DANH_DAU_TIEN DEFAULT NULL ON CONVERSION ERROR)
        WHERE p_dash_loai_tk IS NOT NULL
          AND v_text_filter_cnt = 0 AND v_address_filter_cnt = 0 AND v_tha_filter_cnt = 0 AND v_tn_filter_cnt = 0
          AND NVL(rt.IS_DELETED, 0) = 0
          AND rt.LL_TRAI_GIAM_ID IS NOT NULL
          AND rt.LL_TRAI_GIAM_ID IN (SELECT ID FROM valid_trai_ids)
          AND (v_ll_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        UNION ALL
        -- (c) non-dashboard, KHÔNG có free-filter -> toàn b? (rt_trai materialize ??y ?? ?úng ? nhánh này)
        SELECT rt.PHAM_NHAN_ID, rt.LL_HO_TEN, rt.HO_TEN_ORDER, rt.LL_TINH_TRANG_ID,
               rt.LL_DM_GIOI_TINH_ID, rt.LL_DM_DAN_TOC_ID, rt.LL_DM_QUOC_TICH_ID, rt.LL_DM_TON_GIAO_ID,
               rt.LL_DM_HOC_VAN_ID,
               rt.LL_PHAN_DOI_ID, rt.LL_PHAN_TRAI_ID,
               rt.LL_SO_HO_SO_LAN_DAU, rt.TOI_DANH_DAU_TIEN_NAME,
               rt.LL_NGAY_SINH, rt.THA_NGAY_BAT, rt.THA_NGAY_DEN_TRAI, rt.THA_NGAY_HET_HAN, rt.THA_AN_PHAT, rt.THA_MA_AN_PHAT,
               c.TTPN_MA
        FROM rt_trai rt
        LEFT JOIN cache_today c ON c.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        WHERE p_dash_loai_tk IS NULL
          AND v_text_filter_cnt = 0 AND v_address_filter_cnt = 0 AND v_tha_filter_cnt = 0 AND v_tn_filter_cnt = 0
    ),
    -- 1. L?c per-row trên driver_rows (eligibility ?ã thu h?p ? trên)
    -- MATERIALIZE: filtered_count + paged_ids cùng ??c 1 temp 3 c?t, tránh ch?y toàn b? filter per-row 2 l?n.
    -- FIRST_ROWS(100) là hint C?P CÂU L?NH — B?T BU?C GI?: nó chuy?n c? statement sang optimizer mode
    -- first_rows, c?t t?a m?nh không gian cost-based transformation. B? hint này ? hard parse bùng n?
    -- ~4-5 PHÚT thu?n CPU (?o ASH 07/2026: 501 m?u IN_HARD_PARSE='Y' ON CPU, ch?y th?t ch? 0.2-2s).
    filtered_prep AS (
        SELECT /*+ MATERIALIZE FIRST_ROWS(100) */
            rt.PHAM_NHAN_ID AS PHAM_NHAN_ID,
            rt.LL_HO_TEN AS HO_TEN,
            rt.HO_TEN_ORDER AS HO_TEN_ORDER,
            rt.THA_NGAY_BAT AS THA_NGAY_BAT,
            rt.THA_NGAY_HET_HAN AS THA_NGAY_HET_HAN,
            rt.THA_AN_PHAT AS THA_AN_PHAT,
            rt.THA_NGAY_DEN_TRAI AS THA_NGAY_DEN_TRAI,
            -- Sort key SOHSLD/TOIDANH: LL_SO_HO_SO_LAN_DAU có s?n trên RT; TOI_DANH_SORT là TÊN t?i danh
            -- (?ã resolve qua dm_toi_danh_ten trong rt_trai — TOI_DANH_DAU_TIEN g?c trên RT là ID, không
            -- ph?i tên, sort theo ID s? sai th? t? alphabet)
            rt.LL_SO_HO_SO_LAN_DAU AS SO_HSLD,
            rt.TOI_DANH_DAU_TIEN_NAME AS TOI_DANH_SORT,
            -- Sort key ngày sinh: LL_NGAY_SINH là text (DD/MM/YYYY ho?c ch? n?m) — parse an toàn,
            -- không match ??nh d?ng thì ?? NULL (gi?ng logic hi?n th? "ngaySinh" ? SELECT cu?i)
            CASE
                WHEN rt.LL_NGAY_SINH IS NOT NULL
                     AND REGEXP_LIKE(TRIM(CAST(rt.LL_NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
                THEN TO_DATE(TRIM(CAST(rt.LL_NGAY_SINH AS VARCHAR2(100))) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY')
                ELSE NULL
            END AS NGAY_SINH_DATE
        FROM driver_rows rt
        WHERE (
            p_stt_tong_hop IS NULL
            OR (p_stt_tong_hop = 1  AND rt.TTPN_MA IN ('111', '112', '113', '114'))
            OR (p_stt_tong_hop = 2
                AND rt.TTPN_MA LIKE '112%'
                AND EXISTS (SELECT 1 FROM QLPN.PN_GIAM_RIENGS g
                    WHERE g.GR_PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
                      AND NVL(g.IS_DELETED, 0) = 0
                      AND (g.GR_NGAY_KETTHUC IS NULL OR g.GR_NGAY_KETTHUC >= v_ngay_xet)))
            OR (p_stt_tong_hop = 3
                AND rt.TTPN_MA LIKE '113%'
                AND EXISTS (SELECT 1 FROM QLPN.CHUA_BENH_BAT_BUOCS c
                    WHERE c.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                      AND NVL(c.IS_DELETED, 0) = 0))
            OR (p_stt_tong_hop = 4
                AND rt.TTPN_MA IN ('141', '142')
                AND EXISTS (SELECT 1 FROM QLPN.TRICH_XUATS tx
                    WHERE tx.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                      AND NVL(tx.IS_DELETED, 0) = 0
                      AND tx.TX_NGAY_TRA IS NULL
                      AND EXISTS (SELECT 1 FROM QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS lqd
                          WHERE lqd.ID = tx.TX_LOAI_LENH_ID
                            AND NVL(lqd.IS_DELETED, 0) = 0
                            AND lqd.LQDTX_MA = '1')))
            OR (p_stt_tong_hop = 5
                AND rt.TTPN_MA IN ('151', '152', '157')
                AND EXISTS (SELECT 1 FROM QLPN.TAM_DINH_CHIS tdc
                    WHERE tdc.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                      AND NVL(tdc.IS_DELETED, 0) = 0
                      AND tdc.NGAY_LAI IS NULL
                      AND EXISTS (SELECT 1 FROM QLPN.DM_LOAI_QUYET_DINH_TAM_DINH_CHIES lq
                          WHERE lq.ID = tdc.LOAI_QUYET_DINH_ID
                            AND NVL(lq.IS_DELETED, 0) = 0
                            AND lq.LQDTDC_MA = '1')))
            OR (p_stt_tong_hop = 6  AND rt.TTPN_MA = '126')
            OR (p_stt_tong_hop = 7  AND rt.THA_NGAY_DEN_TRAI IS NOT NULL AND rt.THA_NGAY_HET_HAN >= v_ngay_xet AND rt.THA_NGAY_HET_HAN < v_ngay_xet + 1)
            OR (p_stt_tong_hop = 8  AND rt.TTPN_MA IN ('111', '112', '113', '114') AND rt.THA_NGAY_DEN_TRAI IS NOT NULL AND rt.THA_NGAY_HET_HAN >= v_ngay_xet + 1 AND rt.THA_NGAY_HET_HAN < v_ngay_xet + 2)
            OR (p_stt_tong_hop = 9  AND rt.TTPN_MA IN ('111', '112', '113', '114') AND rt.THA_NGAY_DEN_TRAI IS NOT NULL AND rt.THA_NGAY_HET_HAN >= v_ngay_xet + 1 AND rt.THA_NGAY_HET_HAN < ADD_MONTHS(v_ngay_xet + 1, 2) + 1)
            OR (p_stt_tong_hop = 10 AND rt.TTPN_MA = '123')
            OR (p_stt_tong_hop = 11 AND v_ll_trai_giam_id IS NOT NULL AND EXISTS (SELECT 1 FROM QLPN.PHAM_NHAN_CHUYEN_TRAI ct WHERE ct.PNCT_LAI_LICH_ID = rt.PHAM_NHAN_ID AND NVL(ct.IS_DELETED, 0) = 0))
            OR (p_stt_tong_hop = 12 AND EXISTS (SELECT 1 FROM QLPN.PN_KET_THUC_CHETS k WHERE k.KTC_PN_LAI_LICH_ID = rt.PHAM_NHAN_ID AND NVL(k.IS_DELETED, 0) = 0 AND k.KTC_NGAY_CHET >= TRUNC(SYSDATE, 'YEAR')))
            OR (p_stt_tong_hop = 13 AND EXISTS (SELECT 1 FROM QLPN.TRON_TRAIS tt WHERE tt.PHAM_NHAN_ID = rt.PHAM_NHAN_ID AND NVL(tt.IS_DELETED, 0) = 0 AND tt.NGAY_BAT_LAI IS NULL))
            OR (p_stt_tong_hop = 14 AND EXISTS (SELECT 1 FROM QLPN.HUY_ANS h WHERE h.PHAM_NHAN_ID = rt.PHAM_NHAN_ID AND NVL(h.IS_DELETED, 0) = 0 AND h.NGAY_TRA_TU_DO IS NOT NULL))
            OR (p_stt_tong_hop = 15 AND EXISTS (SELECT 1 FROM QLPN.MIEN_HINH_PHATS m WHERE m.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID AND NVL(m.IS_DELETED, 0) = 0 AND m.MHP_NGAY_TU_DO IS NOT NULL))
            OR (p_stt_tong_hop = 16 AND EXISTS (SELECT 1 FROM QLPN.HOAN_THI_HANH_ANS h WHERE h.PHAM_NHAN_ID = rt.PHAM_NHAN_ID AND NVL(h.IS_DELETED, 0) = 0))
        )
        AND (p_gioi_tinh_id IS NULL OR rt.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
        AND (p_phan_doi IS NULL OR rt.LL_PHAN_DOI_ID = p_phan_doi)
        AND (p_phan_trai IS NULL OR rt.LL_PHAN_TRAI_ID = p_phan_trai)
        AND (p_tinh_trang_id IS NULL OR rt.LL_TINH_TRANG_ID = p_tinh_trang_id)
        AND (p_dan_toc_id IS NULL OR rt.LL_DM_DAN_TOC_ID = p_dan_toc_id)
        AND (p_quoc_tich_id IS NULL OR rt.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
        AND (p_ton_giao_id IS NULL OR rt.LL_DM_TON_GIAO_ID = p_ton_giao_id)
        AND (p_trinh_do_hoc_van_id IS NULL OR rt.LL_DM_HOC_VAN_ID = p_trinh_do_hoc_van_id)
        AND (p_ma_an_phat IS NULL OR rt.THA_MA_AN_PHAT = p_ma_an_phat)
        AND (v_like_ngaysinh IS NULL OR rt.LL_NGAY_SINH LIKE v_like_ngaysinh)
        -- ??a ch? ?ã l?c trong free_scope_ids
        -- Filter thân nhân: QH_ID ???c pre-compute 1 l?n t? b?ng DM nh?, lo?i b? correlated JOIN per row
        AND (
            v_like_bo IS NULL
            OR EXISTS (
                SELECT 1 FROM QLPN.THAN_NHAN_NGUOI_THANS tn
                WHERE tn.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                  AND tn.IS_DELETED = 0
                  AND tn.QUAN_HE_ID IN (SELECT ID FROM qh_bo_ids)
                  AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(tn.HO_TEN_THAN_NHAN)), 1, 400) LIKE v_like_bo
            )
        )
        AND (
            v_like_me IS NULL
            OR EXISTS (
                SELECT 1 FROM QLPN.THAN_NHAN_NGUOI_THANS tn
                WHERE tn.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                  AND tn.IS_DELETED = 0
                  AND tn.QUAN_HE_ID IN (SELECT ID FROM qh_me_ids)
                  AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(tn.HO_TEN_THAN_NHAN)), 1, 400) LIKE v_like_me
            )
        )
        AND (
            v_like_vc IS NULL
            OR EXISTS (
                SELECT 1 FROM QLPN.THAN_NHAN_NGUOI_THANS tn
                WHERE tn.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                  AND tn.IS_DELETED = 0
                  AND tn.QUAN_HE_ID IN (SELECT ID FROM qh_vc_ids)
                  AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(tn.HO_TEN_THAN_NHAN)), 1, 400) LIKE v_like_vc
            )
        )
        -- THA ?ã l?c trong toi_danh_scope_ids / free_scope_ids khi v_tha_filter_cnt > 0
    ),
    -- P0-2: total_count tách kh?i paginate — tránh WINDOW SORT toàn b? filtered_prep
    filtered_count AS (
        SELECT COUNT(*) AS total_count
        FROM filtered_prep
    ),
    -- 2. Phân trang nhanh (Pagination) — không COUNT(*) OVER ()
    paged_ids AS (
        SELECT /*+ MATERIALIZE */
            f.PHAM_NHAN_ID,
            f.HO_TEN,
            f.HO_TEN_ORDER
        FROM filtered_prep f
        -- p_sort whitelist qua CASE WHEN (static SQL, không dynamic) — v_sort_upper ?ã UPPER/TRIM ? trên.
        -- NULL/giá tr? l? r?i vào nhánh m?c ??nh cu?i (HO_TEN_ORDER ASC), gi? nguyên hành vi c?.
        ORDER BY
            CASE WHEN v_sort_upper = 'NGAYSINH ASC'  THEN f.NGAY_SINH_DATE   END ASC  NULLS LAST,
            CASE WHEN v_sort_upper = 'NGAYSINH DESC' THEN f.NGAY_SINH_DATE   END DESC NULLS LAST,
            CASE WHEN v_sort_upper = 'NGAYBAT ASC'    THEN f.THA_NGAY_BAT     END ASC  NULLS LAST,
            CASE WHEN v_sort_upper = 'NGAYBAT DESC'   THEN f.THA_NGAY_BAT     END DESC NULLS LAST,
            CASE WHEN v_sort_upper = 'NGAYHETHAN ASC'  THEN f.THA_NGAY_HET_HAN END ASC  NULLS LAST,
            CASE WHEN v_sort_upper = 'NGAYHETHAN DESC' THEN f.THA_NGAY_HET_HAN END DESC NULLS LAST,
            CASE WHEN v_sort_upper = 'ANPHAT ASC'     THEN f.THA_AN_PHAT      END ASC  NULLS LAST,
            CASE WHEN v_sort_upper = 'ANPHAT DESC'    THEN f.THA_AN_PHAT      END DESC NULLS LAST,
            CASE WHEN v_sort_upper = 'HOTEN DESC'     THEN f.HO_TEN_ORDER     END DESC NULLS LAST,
            CASE WHEN v_sort_upper = 'SOHSLD ASC'        THEN f.SO_HSLD           END ASC  NULLS LAST,
            CASE WHEN v_sort_upper = 'SOHSLD DESC'       THEN f.SO_HSLD           END DESC NULLS LAST,
            CASE WHEN v_sort_upper = 'TOIDANH ASC'       THEN f.TOI_DANH_SORT     END ASC  NULLS LAST,
            CASE WHEN v_sort_upper = 'TOIDANH DESC'      THEN f.TOI_DANH_SORT     END DESC NULLS LAST,
            CASE WHEN v_sort_upper = 'NGAYDENTRAI ASC'  THEN f.THA_NGAY_DEN_TRAI END ASC  NULLS LAST,
            CASE WHEN v_sort_upper = 'NGAYDENTRAI DESC' THEN f.THA_NGAY_DEN_TRAI END DESC NULLS LAST,
            CASE WHEN v_sort_upper NOT IN (
                'NGAYSINH ASC', 'NGAYSINH DESC', 'NGAYBAT ASC', 'NGAYBAT DESC',
                'NGAYHETHAN ASC', 'NGAYHETHAN DESC', 'ANPHAT ASC', 'ANPHAT DESC', 'HOTEN DESC',
                'SOHSLD ASC', 'SOHSLD DESC', 'TOIDANH ASC', 'TOIDANH DESC',
                'NGAYDENTRAI ASC', 'NGAYDENTRAI DESC'
            ) THEN f.HO_TEN_ORDER END ASC NULLS LAST,
            f.PHAM_NHAN_ID DESC
        OFFSET v_skip ROWS
        FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY
    ),
    -- Drive NL ~25 PHAM_NHAN_ID ? view (tránh merge full scan VW trên toàn RT)
    page_detail AS (
        SELECT /*+ MATERIALIZE LEADING(p) USE_NL(v) */
            v.*
        FROM paged_ids p
        LEFT JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET v ON v.PHAM_NHAN_ID = p.PHAM_NHAN_ID
    ),
    -- 3. Join chi ti?t trang và mapping alias
    rows_page AS (
        SELECT
            fc.total_count,
            v.*,
            -- Ánh x? l?i các tên c?t có ti?n t? LL_ ?? kh?p v?i SELECT cu?i cùng
            v.NOI_OTRUOC_KHI_BAT      AS LL_NOI_OTRUOC_KHI_BAT,
            v.SO_HO_PHU               AS LL_SO_HO_PHU,
            v.HO_CHIEU                AS LL_HO_CHIEU,
            v.LL_DM_DAN_TOC_ID        AS ID_DAN_TOC,
            v.LL_DM_TON_GIAO_ID       AS ID_TON_GIAO,
            v.LL_DM_HOC_VAN_ID        AS ID_TRINH_DO_HOC_VAN,
            v.LL_DM_NGHE_NGHIEP_ID    AS ID_NGHE_NGHIEP,
            v.LL_SUC_KHOE_KHI_VAO_ID  AS ID_SUC_KHOE_KHI_VAO,
            dmttpn.TTPN_TEN AS TEN_TINH_TRANG,
           v.NOI_THA_VE_CU_TRU AS NOI_THA_VE_DAY_DU,
            CASE
                WHEN NVL(v.SO_LAN_GIAM, 0) = 0
                  OR v.THOI_GIAN_DA_GIAM IS NULL
                  OR NULLIF(TRIM(CAST(v.THOI_GIAN_DA_GIAM AS NVARCHAR2(2000))), u'0') IS NULL
                THEN u'Kh\00f4ng'
                ELSE TO_NCHAR(v.SO_LAN_GIAM) || u' l\1ea7n = '
                     || CAST(v.THOI_GIAN_DA_GIAM AS NVARCHAR2(2000))
            END AS calc_da_giam,
            CAST(v.THOI_GIAN_DA_CHAP_HANH AS NVARCHAR2(2000)) AS calc_da_chap_hanh,
            CAST(v.THOI_GIAN_CON_LAI AS NVARCHAR2(2000)) AS calc_con_lai,
            -- Sort key ngày sinh cho ORDER BY cu?i — cùng công th?c parse v?i filtered_prep.NGAY_SINH_DATE
            CASE
                WHEN v.NGAY_SINH IS NOT NULL
                     AND REGEXP_LIKE(TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
                THEN TO_DATE(TRIM(CAST(v.NGAY_SINH AS VARCHAR2(100))) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY')
                ELSE NULL
            END AS SORT_NGAY_SINH_DATE,
            -- Sort key TOI_DANH cho ORDER BY cu?i: v.TOI_DANH_DAU_TIEN (t? v.*) là ID t?i danh, không ph?i
            -- tên — resolve tên qua DM_TOI_DANHS, ch? áp d?ng cho ?25 dòng c?a trang nên r?
            TRIM(td_first.TD_TEN) AS TOI_DANH_DAU_TIEN_NAME
        FROM paged_ids p
        CROSS JOIN filtered_count fc
        LEFT JOIN page_detail v ON v.PHAM_NHAN_ID = p.PHAM_NHAN_ID
        LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS dmttpn
            ON dmttpn.ID = v.LL_TINH_TRANG_ID
           AND NVL(dmttpn.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TOI_DANHS td_first
            ON td_first.ID = TO_NUMBER(v.TOI_DANH_DAU_TIEN DEFAULT NULL ON CONVERSION ERROR)
           AND NVL(td_first.IS_DELETED, 0) = 0
    )
    SELECT
        p.total_count     AS "totalCount",
        p.LL_ANH          AS "anh",
        p.SO_HO_SO        AS "soHoSoLanDau",
        p.LL_SO_HO_PHU    AS "soHoPhu",
        p.CCCD            AS "cccd",
        p.LL_HO_CHIEU     AS "hoChieu",
        p.HO_TEN          AS "hoTen",
        p.GIOI_TINH_ID    AS "gioiTinhId",
        p.GIOI_TINH       AS "gioiTinhName",
        CASE
            WHEN p.NGAY_SINH IS NOT NULL
                 AND REGEXP_LIKE(TRIM(CAST(p.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(CAST(p.NGAY_SINH AS VARCHAR2(100))) DEFAULT NULL ON CONVERSION ERROR, 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN p.NAM_SINH IS NOT NULL AND p.NAM_SINH > 0 THEN TO_CHAR(p.NAM_SINH)
            WHEN p.NGAY_SINH IS NOT NULL THEN TRIM(CAST(p.NGAY_SINH AS VARCHAR2(100)))
            ELSE NULL
        END AS "ngaySinh",
        p.LL_PHAN_TRAI_ID AS "phanTraiId",
        p.PHAN_TRAI       AS "phanTraiName",
        p.PHAN_DOI_ID     AS "phanDoiId",
        p.PHAN_DOI        AS "phanDoiName",
        p.LL_TINH_TRANG_ID AS "tinhTrangId",
        CAST(p.TEN_TINH_TRANG AS NVARCHAR2(500)) AS "tinhTrangName",
        p.TEN_KHAC        AS "tenKhac",
        p.NOI_THUONG_TRU_DAY_DU AS "diaChiThuongTru",
        p.DIA_CHI_THUONG_TRU AS "diaChiThuongTruShort",
        p.LL_NOI_OTRUOC_KHI_BAT AS "noiOTruocKhiBat",
        p.NOI_O_KHAC      AS "noiOKhac",
        p.NGUYEN_QUAN     AS "nguyenQuan",
        p.NOI_THA_VE_DAY_DU AS "noiThaVeCuTru",
        p.ID_DAN_TOC      AS "danTocId",
        p.DAN_TOC         AS "danTocName",
        p.ID_TON_GIAO     AS "tonGiaoId",
        p.TON_GIAO        AS "tonGiaoName",
        p.QUOC_TICH_ID    AS "quocTichId",
        p.QUOC_TICH       AS "quocTichName",
        p.ID_TRINH_DO_HOC_VAN AS "trinhDoHocVanId",
        p.HOC_VAN         AS "trinhDoHocVanName",
        p.ID_NGHE_NGHIEP  AS "ngheNghiepId",
        p.NGHE_NGHIEP     AS "ngheNghiepName",
        p.ID_SUC_KHOE_KHI_VAO AS "sucKhoeKhiVaoId",
        p.TINH_TRANG_SUC_KHOE AS "sucKhoeKhiVaoName",
        p.TOI_DANH        AS "toiDanh",
        p.TOI_DANH_ID     AS "toiDanhIds",
        p.NGAY_BAT_AN_PHAT AS "ngayBat",
        p.NGAY_DEN_TRAI   AS "ngayDenTrai",
        p.AN_PHAT         AS "anPhat",
        p.THA_MA_AN_PHAT  AS "maAnPhat",
        p.SO_BAN_AN       AS "soBanAn",
        p.SO_QD_THA       AS "soQdTha",
        p.NGAY_HET_AN     AS "ngayHetHan",
        p.calc_con_lai    AS "thoiGianConLai",
        p.SO_TIEN_AN      AS "tienAn",
        p.calc_da_giam    AS "daGiam",
        p.calc_da_chap_hanh AS "daChapHanh",
        p.LL_DIA_CHI_THUONG_TRU_PROVICE AS "diaChiThuongTruProvice",
        p.TINH_THANH_THUONG_TRU AS "diaChiThuongTruProviceName",
        p.LL_DIA_CHI_THUONG_TRU_WARD AS "diaChiThuongTruWard",
        p.PHUONG_XA_THUONG_TRU AS "diaChiThuongTruWardName",
        p.SO_QD_DIEU_CHUYEN AS "soQuyetDinhDieuChuyen",
        QLPN.FN_GET_LIET_KE_HPBS_CHI_TIET(p.PHAM_NHAN_ID) AS "hinhPhatBoSung",
        p.PHAM_NHAN_ID    AS "id"
    FROM rows_page p
    -- ??ng b? ?úng key sort ?ã dùng ?? phân trang ? paged_ids (khác key thì trang s? "xáo" th? t? hi?n th?)
    ORDER BY
        CASE WHEN v_sort_upper = 'NGAYSINH ASC'  THEN p.SORT_NGAY_SINH_DATE END ASC  NULLS LAST,
        CASE WHEN v_sort_upper = 'NGAYSINH DESC' THEN p.SORT_NGAY_SINH_DATE END DESC NULLS LAST,
        CASE WHEN v_sort_upper = 'NGAYBAT ASC'    THEN p.NGAY_BAT_AN_PHAT   END ASC  NULLS LAST,
        CASE WHEN v_sort_upper = 'NGAYBAT DESC'   THEN p.NGAY_BAT_AN_PHAT   END DESC NULLS LAST,
        CASE WHEN v_sort_upper = 'NGAYHETHAN ASC'  THEN p.NGAY_HET_AN        END ASC  NULLS LAST,
        CASE WHEN v_sort_upper = 'NGAYHETHAN DESC' THEN p.NGAY_HET_AN        END DESC NULLS LAST,
        CASE WHEN v_sort_upper = 'ANPHAT ASC'     THEN p.AN_PHAT            END ASC  NULLS LAST,
        CASE WHEN v_sort_upper = 'ANPHAT DESC'    THEN p.AN_PHAT            END DESC NULLS LAST,
        CASE WHEN v_sort_upper = 'HOTEN DESC'     THEN p.HO_TEN_ORDER       END DESC NULLS LAST,
        CASE WHEN v_sort_upper = 'SOHSLD ASC'        THEN p.SO_HO_SO          END ASC  NULLS LAST,
        CASE WHEN v_sort_upper = 'SOHSLD DESC'       THEN p.SO_HO_SO          END DESC NULLS LAST,
        CASE WHEN v_sort_upper = 'TOIDANH ASC'       THEN p.TOI_DANH_DAU_TIEN_NAME END ASC  NULLS LAST,
        CASE WHEN v_sort_upper = 'TOIDANH DESC'      THEN p.TOI_DANH_DAU_TIEN_NAME END DESC NULLS LAST,
        CASE WHEN v_sort_upper = 'NGAYDENTRAI ASC'  THEN p.NGAY_DEN_TRAI     END ASC  NULLS LAST,
        CASE WHEN v_sort_upper = 'NGAYDENTRAI DESC' THEN p.NGAY_DEN_TRAI     END DESC NULLS LAST,
        CASE WHEN v_sort_upper NOT IN (
            'NGAYSINH ASC', 'NGAYSINH DESC', 'NGAYBAT ASC', 'NGAYBAT DESC',
            'NGAYHETHAN ASC', 'NGAYHETHAN DESC', 'ANPHAT ASC', 'ANPHAT DESC', 'HOTEN DESC',
            'SOHSLD ASC', 'SOHSLD DESC', 'TOIDANH ASC', 'TOIDANH DESC',
            'NGAYDENTRAI ASC', 'NGAYDENTRAI DESC'
        ) THEN p.HO_TEN_ORDER END ASC NULLS LAST,
        p.PHAM_NHAN_ID DESC,
        p.CCCD;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i t\00ecm ki\1ebfm l\00e1i l\1ecbch: ' || SQLERRM
        );



-- BEGIN
--     QLPN.SP_GET_TIM_KIEM_PN_LAI_LICH_130826(
--         p_like_dash       => N'Nguy?n V?n',
--         p_sort            => N'NGAYSINH DESC',
--         p_maxresultcount  => 25,
--         p_skipcount       => 0
--     );
-- END;
END ;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TIM_KIEM_PN_LAI_LICH_1807
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TIM_KIEM_PN_LAI_LICH_1807" (
    p_ma_trai_giam          IN NVARCHAR2 DEFAULT NULL,
        -- DM_TRAI_GIAMS.TG_MA — l?c theo tr?i; NULL ho?c N'C10' = toàn C10
    p_so_hsld               IN NVARCHAR2 DEFAULT NULL,
    p_cccd                  IN NVARCHAR2 DEFAULT NULL,
    p_ho_ten                IN NVARCHAR2 DEFAULT NULL,
    p_ngay_sinh             IN VARCHAR2  DEFAULT NULL,
    p_gioi_tinh_id          IN NUMBER    DEFAULT NULL,
    p_ho_ten_bo             IN NVARCHAR2 DEFAULT NULL,
    p_ho_ten_me             IN NVARCHAR2 DEFAULT NULL,
    p_ho_ten_vo_chong       IN NVARCHAR2 DEFAULT NULL,
    p_tinh_trang_id         IN NUMBER    DEFAULT NULL,
    p_dan_toc_id            IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id          IN NUMBER    DEFAULT NULL,
    p_ton_giao_id           IN NUMBER    DEFAULT NULL,
    p_toi_danh              IN NUMBER    DEFAULT NULL,  -- ID t?i danh (DM_TOI_DANHS.ID)
    p_ngay_bat              IN VARCHAR2  DEFAULT NULL,
    p_noi_dang_ky_tt        IN NVARCHAR2 DEFAULT NULL,
    p_ve_cu_tru             IN NVARCHAR2 DEFAULT NULL,
    p_den_trai_tu_ngay      IN VARCHAR2  DEFAULT NULL,
    p_den_trai_den_ngay     IN VARCHAR2  DEFAULT NULL,
    p_phan_doi              IN NUMBER    DEFAULT NULL,  -- DM_PHAN_DOIS.ID
    p_phan_trai             IN NUMBER    DEFAULT NULL,  -- DM_PHAN_TRAIS.ID
    p_het_an_tu_ngay        IN VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY — THA_NGAY_HET_HAN >=
    p_het_an_den_ngay       IN VARCHAR2  DEFAULT NULL,  -- DD/MM/YYYY — THA_NGAY_HET_HAN <=
    p_so_ban_an             IN NVARCHAR2 DEFAULT NULL,  -- PN_THI_HANH_AN.THA_SO_BAN_AN
    p_so_qd_tha             IN NVARCHAR2 DEFAULT NULL,  -- PN_THI_HANH_AN.THA_SO_QD_THA
    p_like_dash             IN NVARCHAR2 DEFAULT NULL,
    p_dash_loai_tk          IN NUMBER    DEFAULT NULL,
        -- 1: S? ph?m nhân tháng tr??c chuy?n sang (??u k?)
        -- 2: S? t?ng trong tháng
        -- 3: S? gi?m trong tháng
        -- 4: ?ang ch?p hành án (Cu?i k?)
    p_stt_tong_hop          IN NUMBER    DEFAULT NULL,
        -- 1 ??n 16 t??ng ?ng v?i STT trong V_TK_TONG_HOP_TINH_TRANG_DASHBOARD

    p_maxresultcount        IN NUMBER    DEFAULT 25,
    p_skipcount             IN NUMBER    DEFAULT 0
) AS
    v_skip        NUMBER;
    v_limit       NUMBER;
    v_ngay_xet    DATE;
    v_like_ngaysinh VARCHAR2(4000);
    v_ngay_bat    DATE;
    v_den_trai_tu_ngay    DATE;
    v_den_trai_den_ngay   DATE;
    v_het_an_tu_ngay      DATE;
    v_het_an_den_ngay     DATE;
    v_like_so_ban_an      VARCHAR2(4000);
    v_like_so_qd_tha      VARCHAR2(4000);
    v_like_hoten  VARCHAR2(4000);
    v_like_cccd   VARCHAR2(4000);
    v_like_hs     VARCHAR2(4000);
    v_toi_danh_id NUMBER;
    v_like_dktt   VARCHAR2(4000);
    v_like_cu_tru VARCHAR2(4000);
    v_like_bo     VARCHAR2(4000);
    v_like_me     VARCHAR2(4000);
    v_like_vc     VARCHAR2(4000);
    v_like_dash   VARCHAR2(4000);
    v_dash_tu_ngay TIMESTAMP;
    v_dash_den_ngay TIMESTAMP;
    v_dash_ngay_xet DATE;              -- LEAST(DEN_NGAY, SYSDATE) — ??ng b? NGAY_XET SP_TK_THANG
    v_dash_ngay_xet_exclusive DATE;    -- NGAY_XET + 1 giây — kh?p biên k? dashboard
    v_text_filter_cnt    NUMBER;
    v_address_filter_cnt NUMBER;
    v_tha_filter_cnt     NUMBER;
    v_ll_trai_giam_id    NUMBER;  -- resolve TG_MA ? ID ?? partition prune PN_LAI_LICH_CHI_TIET_RT
    c1            SYS_REFCURSOR;
BEGIN
    v_skip  := NVL(p_skipcount, 0);
    v_limit := NVL(p_maxresultcount, 0);

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL
       AND TRIM(p_ma_trai_giam) IS NOT NULL
    THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                v_ll_trai_giam_id := NULL;
        END;
    END IF;

    v_ngay_xet := TRUNC(SYSDATE);

    IF p_ngay_sinh IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ngay_sinh))) > 0 THEN
        v_like_ngaysinh := '%' || TRIM(TO_CHAR(p_ngay_sinh)) || '%';
    ELSE
        v_like_ngaysinh := NULL;
    END IF;

    IF p_ngay_bat IS NULL OR TRIM(p_ngay_bat) = '' THEN
        v_ngay_bat := NULL;
    ELSE
        v_ngay_bat := TRUNC(TO_DATE(TRIM(p_ngay_bat), 'DD/MM/YYYY'));
    END IF;

    IF TO_NUMBER(TO_CHAR(SYSDATE, 'DD')) < 15 THEN
        v_dash_tu_ngay  := ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1) + 14;
        v_dash_den_ngay := TRUNC(SYSDATE, 'MM') + 13;
    ELSE
        v_dash_tu_ngay  := TRUNC(SYSDATE, 'MM') + 14;
        v_dash_den_ngay := ADD_MONTHS(TRUNC(SYSDATE, 'MM'), 1) + 13;
    END IF;
    v_dash_ngay_xet := LEAST(TRUNC(CAST(v_dash_den_ngay AS DATE)), TRUNC(SYSDATE));
    v_dash_ngay_xet_exclusive := v_dash_ngay_xet + (1 / 86400);

     IF p_den_trai_tu_ngay IS NULL OR TRIM(p_den_trai_tu_ngay) = '' THEN
        v_den_trai_tu_ngay := NULL;
    ELSE
        v_den_trai_tu_ngay := TRUNC(TO_DATE(TRIM(p_den_trai_tu_ngay), 'DD/MM/YYYY'));
    END IF;

     IF p_den_trai_den_ngay IS NULL OR TRIM(p_den_trai_den_ngay) = '' THEN
        v_den_trai_den_ngay := NULL;
    ELSE
        v_den_trai_den_ngay := TRUNC(TO_DATE(TRIM(p_den_trai_den_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_het_an_tu_ngay IS NULL OR TRIM(p_het_an_tu_ngay) = '' THEN
        v_het_an_tu_ngay := NULL;
    ELSE
        v_het_an_tu_ngay := TRUNC(TO_DATE(TRIM(p_het_an_tu_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_het_an_den_ngay IS NULL OR TRIM(p_het_an_den_ngay) = '' THEN
        v_het_an_den_ngay := NULL;
    ELSE
        v_het_an_den_ngay := TRUNC(TO_DATE(TRIM(p_het_an_den_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_so_ban_an IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_so_ban_an))) > 0 THEN
        v_like_so_ban_an := '%' || UPPER(TRIM(TO_CHAR(NVL(p_so_ban_an, u'')))) || '%';
    ELSE
        v_like_so_ban_an := NULL;
    END IF;

    IF p_so_qd_tha IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_so_qd_tha))) > 0 THEN
        v_like_so_qd_tha := '%' || UPPER(TRIM(TO_CHAR(NVL(p_so_qd_tha, u'')))) || '%';
    ELSE
        v_like_so_qd_tha := NULL;
    END IF;

    IF p_ho_ten IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ho_ten))) > 0 THEN
        v_like_hoten := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ho_ten, u''))))) ;
    ELSE
        v_like_hoten := NULL;
    END IF;

    IF p_cccd IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_cccd))) > 0 THEN
        v_like_cccd := '%' || UPPER(TRIM(TO_CHAR(NVL(p_cccd, u'')))) || '%';
    ELSE
        v_like_cccd := NULL;
    END IF;

    IF p_so_hsld IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_so_hsld))) > 0 THEN
        v_like_hs := '%' || UPPER(TRIM(TO_CHAR(NVL(p_so_hsld, u'')))) || '%';
    ELSE
        v_like_hs := NULL;
    END IF;

    IF p_like_dash IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_like_dash))) > 0 THEN
        v_like_dash := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_like_dash, u''))))) || '%';
    ELSE
        v_like_dash := NULL;
    END IF;

    v_toi_danh_id := p_toi_danh;

    IF p_noi_dang_ky_tt IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_noi_dang_ky_tt))) > 0 THEN
        v_like_dktt := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_noi_dang_ky_tt, u''))))) || '%';
    ELSE
        v_like_dktt := NULL;
    END IF;

    IF p_ve_cu_tru IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ve_cu_tru))) > 0 THEN
        v_like_cu_tru := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ve_cu_tru, u''))))) || '%';
    ELSE
        v_like_cu_tru := NULL;
    END IF;

    IF p_ho_ten_bo IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ho_ten_bo))) > 0 THEN
        v_like_bo := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ho_ten_bo, u'')))));
    ELSE
        v_like_bo := NULL;
    END IF;

    IF p_ho_ten_me IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ho_ten_me))) > 0 THEN
        v_like_me := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ho_ten_me, u'')))));
    ELSE
        v_like_me := NULL;
    END IF;

    IF p_ho_ten_vo_chong IS NOT NULL AND LENGTH(TRIM(TO_CHAR(p_ho_ten_vo_chong))) > 0 THEN
        v_like_vc := '%' || UPPER(TRIM(TO_CHAR(QLPN.FN_NORMALIZE_VN(NVL(p_ho_ten_vo_chong, u''))))) ;
    ELSE
        v_like_vc := NULL;
    END IF;

    v_text_filter_cnt :=
          CASE WHEN v_like_hoten IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_cccd IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_hs IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_dash IS NOT NULL THEN 1 ELSE 0 END;

    v_address_filter_cnt :=
          CASE WHEN v_like_dktt IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN v_like_cu_tru IS NOT NULL THEN 1 ELSE 0 END;

    v_tha_filter_cnt :=
          CASE
              WHEN v_toi_danh_id IS NOT NULL
                OR v_ngay_bat IS NOT NULL
                OR v_den_trai_tu_ngay IS NOT NULL
                OR v_den_trai_den_ngay IS NOT NULL
                OR v_het_an_tu_ngay IS NOT NULL
                OR v_het_an_den_ngay IS NOT NULL
                OR v_like_so_ban_an IS NOT NULL
                OR v_like_so_qd_tha IS NOT NULL
              THEN 1
              ELSE 0
          END;

    OPEN c1 FOR
    WITH
    -- ===== Priority 1/2: Pre-compute ID sets cho p_dash_loai_tk — thay correlated EXISTS/FN per-row =====

    -- Pre-compute valid trai IDs — thay 3 EXISTS correlated trên DM_TRAI_GIAMS b?ng 1 hash lookup
    valid_trai_ids AS (
        SELECT /*+ MATERIALIZE */ ID
        FROM QLPN.DM_TRAI_GIAMS
        WHERE NVL(IS_DELETED, 0) = 0
    ),
    -- Tr?ng thái hôm nay t? cache — thay toàn b? DM_TINH_TRANG_PHAM_NHANS join per-row
    -- cho loai_tk=4, p_stt_tong_hop 1-10 và driver_rows (hash join O(1) thay scalar FN)
    cache_today AS (
        SELECT /*+ MATERIALIZE */ PN_LAI_LICH_ID, TTPN_MA
          FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE
         WHERE NGAY_XET = TRUNC(SYSDATE)
    ),
    -- Ch? c?t c?n dùng — tránh materialize RT.* (THA_TOI_DANH_NAMES 16KB × 1.5M ? temp kh?ng l?)
    rt_trai AS (
        SELECT /*+ MATERIALIZE */
            RT.PHAM_NHAN_ID,
            RT.IS_DELETED,
            RT.LL_TRAI_GIAM_ID,
            RT.LL_HO_TEN,
            RT.HO_TEN_ORDER,
            RT.LL_PHAN_DOI_ID,
            RT.LL_PHAN_TRAI_ID,
            RT.LL_CCCD,
            RT.LL_SO_HO_SO_LAN_DAU,
            RT.LL_NGAY_SINH,
            RT.LL_TINH_TRANG_ID,
            RT.LL_DM_GIOI_TINH_ID,
            RT.LL_DM_DAN_TOC_ID,
            RT.LL_DM_QUOC_TICH_ID,
            RT.LL_DM_TON_GIAO_ID,
            RT.LL_DIA_CHI_THUONG_TRU,
            RT.LL_DIA_CHI_THUONG_TRU_WARD,
            RT.LL_DIA_CHI_THUONG_TRU_PROVICE,
            RT.LL_NOI_THA_VE_CU_TRU,
            RT.LL_NOI_THA_VE_CU_TRU_WARD,
            RT.LL_NOI_THA_VE_CU_TRU_PROVICE,
            RT.THA_ID,
            RT.THA_DOI_TUONG,
            RT.THA_NGAY_BAT,
            RT.THA_NGAY_DEN_TRAI,
            RT.THA_NGAY_HET_HAN
          FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
         WHERE NVL(RT.IS_DELETED, 0) = 0
           AND RT.LL_TRAI_GIAM_ID IS NOT NULL
           AND RT.LL_TRAI_GIAM_ID IN (SELECT ID FROM valid_trai_ids)
           AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
           -- PERF: ch? materialize toàn b? RT khi TH?C S? c?n (dashboard c?n rt_trai cho tang/giam/??u k?,
           --       ho?c path li?t kê KHÔNG có filter text/??a ch?/t?i danh). Khi có filter free + non-dashboard,
           --       driver_rows lái t? candidate ids + PK-join RT g?c nên rt_trai ?? R?NG (FILTER h?ng s? ? b? scan 3.15M).
           AND (
                p_dash_loai_tk IS NOT NULL
             OR (v_text_filter_cnt = 0 AND v_address_filter_cnt = 0 AND v_tha_filter_cnt = 0)
           )
    ),
    -- Priority 1: T?ng trong k? (loai_tk=2) — ??ng b? SP_QLPN_GET_TK_THANG_DASHBOARD (rt_trai)
    tang_ids AS (
        SELECT /*+ MATERIALIZE CARDINALITY(tang_union 5000) */ ID FROM (
        SELECT RT.PHAM_NHAN_ID AS ID
        FROM rt_trai RT
        JOIN QLPN.DM_LOAI_DOI_TUONGS LDT ON LDT.ID = RT.THA_DOI_TUONG AND NVL(LDT.IS_DELETED, 0) = 0
        WHERE p_dash_loai_tk = 2
          AND CASE WHEN v_ll_trai_giam_id IS NULL THEN RT.THA_NGAY_BAT ELSE RT.THA_NGAY_DEN_TRAI END >= v_dash_tu_ngay
          AND CASE WHEN v_ll_trai_giam_id IS NULL THEN RT.THA_NGAY_BAT ELSE RT.THA_NGAY_DEN_TRAI END < v_dash_ngay_xet_exclusive
          AND LDT.LDT_MA IN ('20211', '20212', '110', '120', '20221', '20324')
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.TRON_TRAIS TT
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TT.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND TT.NGAY_BAT_LAI >= v_dash_tu_ngay
          AND TT.NGAY_BAT_LAI < v_dash_ngay_xet_exclusive
          AND CAST(TT.NGAY_BAT_LAI AS DATE) >= CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND NVL(TT.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.TAM_DINH_CHIS TDC
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TDC.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND TDC.NGAY_LAI >= v_dash_tu_ngay
          AND TDC.NGAY_LAI < v_dash_ngay_xet_exclusive
          AND CAST(TDC.NGAY_TDC AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND TDC.LOAI_QUYET_DINH_ID = 1
          AND NVL(TDC.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.TRICH_XUATS TX
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TX.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND TX.TX_NGAY_TRA >= v_dash_tu_ngay
          AND TX.TX_NGAY_TRA < v_dash_ngay_xet_exclusive
          AND CAST(TX.TX_NGAY_TRICH_XUAT AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND TX.TX_LOAI_LENH_ID = 1
          AND NVL(TX.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.HUY_ANS HA
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = HA.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND HA.NGAY_TRO_LAI >= v_dash_tu_ngay
          AND HA.NGAY_TRO_LAI < v_dash_ngay_xet_exclusive
          AND CAST(HA.NGAY_TRA_TU_DO AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND NVL(HA.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.THA_CO_DIEU_KIENS TCK
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TCK.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND TCK.NGAY_BAT_LAI >= v_dash_tu_ngay
          AND TCK.NGAY_BAT_LAI < v_dash_ngay_xet_exclusive
          AND NVL(TCK.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT RT.PHAM_NHAN_ID
        FROM QLPN.CHUA_BENH_BAT_BUOCS CB
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = CB.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 2
          AND CB.NGAY_KET_THUC >= v_dash_tu_ngay
          AND CB.NGAY_KET_THUC < v_dash_ngay_xet_exclusive
          AND NVL(CB.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        ) tang_union
    ),
    -- Priority 1: Gi?m trong k? (loai_tk=3) — ??ng b? SP_QLPN_GET_TK_THANG_DASHBOARD (PN_LAI_LICH_CHI_TIET_RT)
    giam_ids AS (
        SELECT /*+ MATERIALIZE CARDINALITY(giam_union 5000) */ ID FROM (
        SELECT TT.PHAM_NHAN_ID AS ID
        FROM QLPN.TRON_TRAIS TT
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TT.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND TT.NGAY_TRON >= v_dash_tu_ngay
          AND TT.NGAY_TRON < v_dash_ngay_xet_exclusive
          AND CAST(TT.NGAY_TRON AS DATE) >= CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND NVL(TT.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT KC.KTC_PN_LAI_LICH_ID
        FROM QLPN.PN_KET_THUC_CHETS KC
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = KC.KTC_PN_LAI_LICH_ID
        LEFT JOIN QLPN.DM_TRUONG_HOP_CHETS THC ON THC.ID = KC.KTC_DM_TRUONG_HOP_CHET_ID
        WHERE p_dash_loai_tk = 3
          AND KC.KTC_NGAY_CHET >= v_dash_tu_ngay
          AND KC.KTC_NGAY_CHET < v_dash_ngay_xet_exclusive
          AND CAST(KC.KTC_NGAY_CHET AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND NVL(THC.THC_MA, '10') NOT IN ('30', '40', '50')
          AND NVL(KC.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT TX.PHAM_NHAN_ID
        FROM QLPN.TRICH_XUATS TX
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TX.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND TX.TX_NGAY_TRICH_XUAT >= v_dash_tu_ngay
          AND TX.TX_NGAY_TRICH_XUAT < v_dash_ngay_xet_exclusive
          AND TX.TX_LOAI_LENH_ID = 1
          AND NVL(TX.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT TDC.PHAM_NHAN_ID
        FROM QLPN.TAM_DINH_CHIS TDC
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TDC.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND TDC.NGAY_TDC >= v_dash_tu_ngay
          AND TDC.NGAY_TDC < v_dash_ngay_xet_exclusive
          AND CAST(TDC.NGAY_TDC AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
          AND TDC.LOAI_QUYET_DINH_ID = 1
          AND NVL(TDC.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND RT.THA_ID IS NOT NULL
        UNION
        SELECT CT.PNCT_LAI_LICH_ID
        FROM QLPN.PHAM_NHAN_CHUYEN_TRAI CT
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = CT.PNCT_LAI_LICH_ID
        LEFT JOIN QLPN.DM_TRUONG_HOP_CHUYEN_TRAIS THCT ON THCT.ID = CT.PNCT_TRUONG_HOP_CHUYEN_ID
        WHERE p_dash_loai_tk = 3
          AND v_ll_trai_giam_id IS NOT NULL
          AND CT.PNCT_NGAY_CHUYEN >= v_dash_tu_ngay
          AND CT.PNCT_NGAY_CHUYEN < v_dash_ngay_xet_exclusive
          AND NVL(THCT.THCT_MA, '10') IN ('10', '20', '90')
          AND NVL(CT.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT HA.PHAM_NHAN_ID
        FROM QLPN.HUY_ANS HA
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = HA.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND HA.NGAY_TRA_TU_DO >= v_dash_tu_ngay
          AND HA.NGAY_TRA_TU_DO < v_dash_ngay_xet_exclusive
          AND NVL(HA.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
          AND HA.PHAM_NHAN_ID NOT IN (
                SELECT TX.PHAM_NHAN_ID
                FROM QLPN.TRICH_XUATS TX
                WHERE TX.TX_LOAI_LENH_ID = 1
                  AND (TX.TX_NGAY_TRA IS NULL
                       OR TX.TX_NGAY_TRA >= v_dash_ngay_xet_exclusive))
        UNION
        SELECT HTHA.PHAM_NHAN_ID
        FROM QLPN.HOAN_THI_HANH_ANS HTHA
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = HTHA.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND HTHA.NGAY_HOAN >= v_dash_tu_ngay
          AND HTHA.NGAY_HOAN < v_dash_ngay_xet_exclusive
          AND NVL(HTHA.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT MHP.PN_LAI_LICH_ID
        FROM QLPN.MIEN_HINH_PHATS MHP
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = MHP.PN_LAI_LICH_ID
        WHERE p_dash_loai_tk = 3
          AND MHP.MHP_NGAY_TU_DO >= v_dash_tu_ngay
          AND MHP.MHP_NGAY_TU_DO < v_dash_ngay_xet_exclusive
          AND NVL(MHP.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT CB.PHAM_NHAN_ID
        FROM QLPN.CHUA_BENH_BAT_BUOCS CB
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = CB.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND CB.NGAY_BAT_DAU >= v_dash_tu_ngay
          AND CB.NGAY_BAT_DAU < v_dash_ngay_xet_exclusive
          AND NVL(CB.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT CG.PNCG_LAI_LICH_ID
        FROM QLPN.PN_CHUYEN_GIAO CG
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = CG.PNCG_LAI_LICH_ID
        LEFT JOIN QLPN.DM_QUOC_TICHS QT ON QT.ID = CG.PNCG_NUOC_CHUYEN_GIAO_ID
        WHERE p_dash_loai_tk = 3
          AND CG.PNCG_NGAY_CHUYEN_GIAO >= v_dash_tu_ngay
          AND CG.PNCG_NGAY_CHUYEN_GIAO < v_dash_ngay_xet_exclusive
          AND NVL(QT.QT_MA, '000') <> '250'
          AND NVL(CG.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT KT.KTRT_PN_LAI_LICH_ID
        FROM QLPN.PN_KET_THUC_RA_TRAIS KT
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = KT.KTRT_PN_LAI_LICH_ID
        WHERE p_dash_loai_tk = 3
          AND KT.KTRT_NGAY_THA >= v_dash_tu_ngay
          AND KT.KTRT_NGAY_THA < v_dash_ngay_xet_exclusive
          AND NVL(KT.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT DX.PNLAI_LICH_ID
        FROM QLPN.PN_DAC_XAS DX
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = DX.PNLAI_LICH_ID
        WHERE p_dash_loai_tk = 3
          AND DX.DX_NGAY_THA >= v_dash_tu_ngay
          AND DX.DX_NGAY_THA < v_dash_ngay_xet_exclusive
          AND DX.DX_TINH_TRANG_DAC_XA IN ('1', '2', '7')
          AND NVL(DX.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        UNION
        SELECT TCK.PHAM_NHAN_ID
        FROM QLPN.THA_CO_DIEU_KIENS TCK
        JOIN rt_trai RT ON RT.PHAM_NHAN_ID = TCK.PHAM_NHAN_ID
        WHERE p_dash_loai_tk = 3
          AND TCK.NGAY_THA >= v_dash_tu_ngay
          AND TCK.NGAY_THA < v_dash_ngay_xet_exclusive
          AND (TCK.NGAY_BAT_LAI IS NULL OR TCK.NGAY_BAT_LAI >= v_dash_ngay_xet_exclusive)
          AND NVL(TCK.IS_DELETED, 0) = 0
          AND NVL(RT.IS_DELETED, 0) = 0
        ) giam_union
    ),
    -- ??u k? (loai_tk=1) — ??c PN_TK_THANG_DAU_KY_IDS (pre-compute b?i SP_TK_THANG)
    dau_ky_ids AS (
        SELECT /*+ MATERIALIZE CARDINALITY(dau_ky_ids 500000) */ PHAM_NHAN_ID AS ID
        FROM QLPN.PN_TK_THANG_DAU_KY_IDS
        WHERE p_dash_loai_tk = 1
          AND TU_NGAY = TO_CHAR(CAST(v_dash_tu_ngay AS DATE), 'DD/MM/YYYY')
          AND DEN_NGAY = TO_CHAR(CAST(v_dash_den_ngay AS DATE), 'DD/MM/YYYY')
          AND (v_ll_trai_giam_id IS NULL OR MA_TRAI_GIAM = TRIM(p_ma_trai_giam))
    ),
    -- P0-1: Gom ID dashboard — drive hash join thay OR + full scan PN_LAI_LICHS
    dash_eligible_ids AS (
        SELECT /*+ MATERIALIZE CARDINALITY(dau_ky_ids 500000) */ ID FROM dau_ky_ids WHERE p_dash_loai_tk = 1
        UNION
        SELECT /*+ CARDINALITY(tang_ids 5000) */ ID FROM tang_ids WHERE p_dash_loai_tk = 2
        UNION
        SELECT /*+ CARDINALITY(giam_ids 5000) */ ID FROM giam_ids WHERE p_dash_loai_tk = 3
        UNION
        SELECT /*+ CARDINALITY(RT 500000) */ RT.PHAM_NHAN_ID AS ID
        FROM rt_trai RT
        JOIN cache_today c ON c.PN_LAI_LICH_ID = RT.PHAM_NHAN_ID
                          AND c.TTPN_MA IN ('111', '112', '113', '114')
        WHERE p_dash_loai_tk = 4
    ),
    -- FBI drive: quét index normalize trên RT g?c (FBI IX_PN_LLCT_RT_NORMHOTEN trên
    --   SUBSTR(UPPER(FN_NORMALIZE_VN(LL_HO_TEN)),1,400), IS_DELETED, LL_TRAI_GIAM_ID, PHAM_NHAN_ID).
    --   INDEX_FFS b?t bu?c dùng FBI (??c giá tr? normalize ?ã tính s?n, index-only) thay vì optimizer
    --   ch?n IX_..._TRAI_GIAM_ID r?i g?i FN_NORMALIZE_VN t?ng dòng trên 3.15M (function avalanche ~35s).
    hoten_candidate_ids AS (
        SELECT /*+ MATERIALIZE INDEX_FFS(RT IX_PN_LLCT_RT_NORMHOTEN) */ RT.PHAM_NHAN_ID AS ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
        WHERE v_like_hoten IS NOT NULL
          AND NVL(RT.IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(RT.LL_HO_TEN)), 1, 400) LIKE v_like_hoten
    ),
    cccd_candidate_ids AS (
        SELECT /*+ MATERIALIZE */ RT.PHAM_NHAN_ID AS ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
        WHERE v_like_cccd IS NOT NULL
          AND NVL(RT.IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
          AND SUBSTR(UPPER(TRIM(RT.LL_CCCD)), 1, 400) LIKE v_like_cccd
    ),
    so_hs_candidate_ids AS (
        SELECT /*+ MATERIALIZE */ RT.PHAM_NHAN_ID AS ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
        WHERE v_like_hs IS NOT NULL
          AND NVL(RT.IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
          AND SUBSTR(UPPER(TRIM(RT.LL_SO_HO_SO_LAN_DAU)), 1, 400) LIKE v_like_hs
    ),
    dash_text_candidate_ids AS (
        SELECT /*+ MATERIALIZE */ ID FROM (
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_dash IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              AND SUBSTR(UPPER(TRIM(RT.LL_SO_HO_SO_LAN_DAU)), 1, 400) LIKE v_like_dash
            UNION
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_dash IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              AND SUBSTR(UPPER(TRIM(RT.LL_CCCD)), 1, 400) LIKE v_like_dash
            UNION
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_dash IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(RT.LL_HO_TEN)), 1, 400) LIKE v_like_dash
        )
    ),
    -- Giao các filter text (AND gi?a ho ten / cccd / so hs / dash)
    text_scope_ids AS (
        SELECT /*+ MATERIALIZE */ u.ID
        FROM (
            SELECT ID, 1 AS f FROM hoten_candidate_ids WHERE v_like_hoten IS NOT NULL
            UNION ALL
            SELECT ID, 2 AS f FROM cccd_candidate_ids WHERE v_like_cccd IS NOT NULL
            UNION ALL
            SELECT ID, 3 AS f FROM so_hs_candidate_ids WHERE v_like_hs IS NOT NULL
            UNION ALL
            SELECT ID, 4 AS f FROM dash_text_candidate_ids WHERE v_like_dash IS NOT NULL
        ) u
        GROUP BY u.ID
        HAVING COUNT(DISTINCT u.f) = v_text_filter_cnt
           AND v_text_filter_cnt > 0
    ),
    -- === ??a ch?: pre-compute DM ward/province tr??c khi drive scope ===
    matching_ward_ids AS (
        SELECT /*+ MATERIALIZE */ dxp.ID
        FROM QLPN.DM_XA_PHUONG dxp
        WHERE v_like_dktt IS NOT NULL
          AND NVL(dxp.IS_DELETED, 0) = 0
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(dxp.XP_TEN)), 1, 400) LIKE v_like_dktt
    ),
    matching_province_ids AS (
        SELECT /*+ MATERIALIZE */ dttp.ID
        FROM QLPN.DM_TINH_THANH_PHO dttp
        WHERE v_like_dktt IS NOT NULL
          AND NVL(dttp.IS_DELETED, 0) = 0
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(dttp.TTP_TEN)), 1, 400) LIKE v_like_dktt
    ),
    matching_cu_tru_ward_ids AS (
        SELECT /*+ MATERIALIZE */ dxp.ID
        FROM QLPN.DM_XA_PHUONG dxp
        WHERE v_like_cu_tru IS NOT NULL
          AND NVL(dxp.IS_DELETED, 0) = 0
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(dxp.XP_TEN)), 1, 400) LIKE v_like_cu_tru
    ),
    matching_cu_tru_province_ids AS (
        SELECT /*+ MATERIALIZE */ dttp.ID
        FROM QLPN.DM_TINH_THANH_PHO dttp
        WHERE v_like_cu_tru IS NOT NULL
          AND NVL(dttp.IS_DELETED, 0) = 0
          AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(dttp.TTP_TEN)), 1, 400) LIKE v_like_cu_tru
    ),
    -- FBI text + FK ward/province (OR trong t?ng nhóm ??a ch?) — drive RT g?c cho FBI ??a ch?
    dktt_scope_ids AS (
        SELECT /*+ MATERIALIZE */ ID FROM (
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_dktt IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(RT.LL_DIA_CHI_THUONG_TRU)), 1, 400) LIKE v_like_dktt
            UNION
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            INNER JOIN matching_ward_ids mw ON mw.ID = RT.LL_DIA_CHI_THUONG_TRU_WARD
            WHERE v_like_dktt IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
            UNION
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            INNER JOIN matching_province_ids mp ON mp.ID = RT.LL_DIA_CHI_THUONG_TRU_PROVICE
            WHERE v_like_dktt IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        )
    ),
    cu_tru_scope_ids AS (
        SELECT /*+ MATERIALIZE */ ID FROM (
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            WHERE v_like_cu_tru IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
              AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(RT.LL_NOI_THA_VE_CU_TRU)), 1, 400) LIKE v_like_cu_tru
            UNION
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            INNER JOIN matching_cu_tru_ward_ids mw ON mw.ID = RT.LL_NOI_THA_VE_CU_TRU_WARD
            WHERE v_like_cu_tru IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
            UNION
            SELECT RT.PHAM_NHAN_ID AS ID
            FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
            INNER JOIN matching_cu_tru_province_ids mp ON mp.ID = RT.LL_NOI_THA_VE_CU_TRU_PROVICE
            WHERE v_like_cu_tru IS NOT NULL
              AND NVL(RT.IS_DELETED, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR RT.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        )
    ),
    -- AND gi?a ??ng ký TT và v? c? trú khi c? hai có filter
    address_scope_ids AS (
        SELECT /*+ MATERIALIZE */ u.ID
        FROM (
            SELECT ID, 1 AS f FROM dktt_scope_ids WHERE v_like_dktt IS NOT NULL
            UNION ALL
            SELECT ID, 2 AS f FROM cu_tru_scope_ids WHERE v_like_cu_tru IS NOT NULL
        ) u
        GROUP BY u.ID
        HAVING COUNT(DISTINCT u.f) = v_address_filter_cnt
           AND v_address_filter_cnt > 0
    ),
    -- PN_THI_HANH_AN drive: t?i danh + ngày b?t/??n tr?i — 1 l?n thay EXISTS × 1.5M
    toi_danh_scope_ids AS (
        SELECT /*+ MATERIALIZE */ tha.THA_PNLAI_LICH_ID AS ID
        FROM QLPN.PN_THI_HANH_AN tha
        WHERE v_tha_filter_cnt > 0
          AND NVL(tha.IS_DELETED, 0) = 0
          AND (v_toi_danh_id IS NULL OR INSTR(
                  ',' || REPLACE(REPLACE(TRIM(CAST(tha.THA_TOI_DANH AS VARCHAR2(4000))), '[', ''), ']', '') || ',',
                  ',' || TO_CHAR(v_toi_danh_id) || ','
              ) > 0)
          AND (v_ngay_bat IS NULL OR (CAST(tha.THA_NGAY_BAT AS DATE) >= v_ngay_bat AND CAST(tha.THA_NGAY_BAT AS DATE) < v_ngay_bat + 1))
          AND (v_den_trai_tu_ngay IS NULL OR CAST(tha.THA_NGAY_DEN_TRAI AS DATE) >= v_den_trai_tu_ngay)
          AND (v_den_trai_den_ngay IS NULL OR CAST(tha.THA_NGAY_DEN_TRAI AS DATE) < v_den_trai_den_ngay + 1)
          AND (v_het_an_tu_ngay IS NULL OR CAST(tha.THA_NGAY_HET_HAN AS DATE) >= v_het_an_tu_ngay)
          AND (v_het_an_den_ngay IS NULL OR CAST(tha.THA_NGAY_HET_HAN AS DATE) < v_het_an_den_ngay + 1)
          AND (v_like_so_ban_an IS NULL OR UPPER(TRIM(CAST(tha.THA_SO_BAN_AN AS NVARCHAR2(1000)))) LIKE v_like_so_ban_an)
          AND (v_like_so_qd_tha IS NULL OR UPPER(TRIM(CAST(tha.THA_SO_QD_THA AS NVARCHAR2(1000)))) LIKE v_like_so_qd_tha)
        GROUP BY tha.THA_PNLAI_LICH_ID
    ),
    -- Giao text + ??a ch? + THA (AND gi?a các nhóm)
    free_scope_ids AS (
        SELECT /*+ MATERIALIZE */ u.ID
        FROM (
            SELECT ID, 1 AS dim FROM text_scope_ids WHERE v_text_filter_cnt > 0
            UNION ALL
            SELECT ID, 2 AS dim FROM address_scope_ids WHERE v_address_filter_cnt > 0
            UNION ALL
            SELECT ID, 3 AS dim FROM toi_danh_scope_ids WHERE v_tha_filter_cnt > 0
        ) u
        GROUP BY u.ID
        HAVING COUNT(DISTINCT u.dim) =
              (CASE WHEN v_text_filter_cnt > 0 THEN 1 ELSE 0 END
             + CASE WHEN v_address_filter_cnt > 0 THEN 1 ELSE 0 END
             + CASE WHEN v_tha_filter_cnt > 0 THEN 1 ELSE 0 END)
           AND (v_text_filter_cnt > 0 OR v_address_filter_cnt > 0 OR v_tha_filter_cnt > 0)
    ),
    -- === Quan h? thân nhân — pre-compute 1 l?n t? b?ng DM nh? ===
    qh_bo_ids AS (
        SELECT /*+ MATERIALIZE */ qh.ID
        FROM QLPN.DM_QUAN_HE_VOI_PHAM_NHANS qh
        WHERE v_like_bo IS NOT NULL
          AND UPPER(QLPN.FN_NORMALIZE_VN(qh.QHVPN_TEN)) LIKE 'BO%'
    ),
    qh_me_ids AS (
        SELECT /*+ MATERIALIZE */ qh.ID
        FROM QLPN.DM_QUAN_HE_VOI_PHAM_NHANS qh
        WHERE v_like_me IS NOT NULL
          AND UPPER(QLPN.FN_NORMALIZE_VN(qh.QHVPN_TEN)) LIKE 'ME%'
    ),
    qh_vc_ids AS (
        SELECT /*+ MATERIALIZE */ qh.ID
        FROM QLPN.DM_QUAN_HE_VOI_PHAM_NHANS qh
        WHERE v_like_vc IS NOT NULL
          AND (UPPER(QLPN.FN_NORMALIZE_VN(qh.QHVPN_TEN)) LIKE 'VO%'
            OR UPPER(QLPN.FN_NORMALIZE_VN(qh.QHVPN_TEN)) LIKE 'CHONG%')
    ),
    -- PERF driver_rows: thay "FROM rt_trai + (OR 4 nhánh eligibility)" b?ng lái t? id-set NH? r?i PK-join RT g?c.
    --   Tránh quét/materialize toàn b? 3.15M rt_trai cho path có filter. 4 nhánh (dashboard × có-filter) lo?i tr? & ??:
    --     (a) có free-filter (text/??a ch?/t?i danh) -> lái free_scope_ids, PK-join RT (dashboard thì thêm EXISTS dash_eligible)
    --     (b) dashboard, KHÔNG filter -> lái dash_eligible_ids, PK-join RT
    --     (c) non-dashboard, KHÔNG filter -> toàn b? dân s? -> gi? rt_trai (full)
    --   Các filter per-row (gi?i tính/tình tr?ng/.../stt_tong_hop/thân nhân/THA) áp 1 L?N ? filtered_prep bên d??i.
    driver_rows AS (
        -- (a) có ít nh?t 1 free-filter
        SELECT rt.PHAM_NHAN_ID, rt.LL_HO_TEN, rt.HO_TEN_ORDER, rt.LL_TINH_TRANG_ID,
               rt.LL_DM_GIOI_TINH_ID, rt.LL_DM_DAN_TOC_ID, rt.LL_DM_QUOC_TICH_ID, rt.LL_DM_TON_GIAO_ID,
               rt.LL_PHAN_DOI_ID, rt.LL_PHAN_TRAI_ID,
               rt.LL_NGAY_SINH, rt.THA_NGAY_DEN_TRAI, rt.THA_NGAY_HET_HAN,
               c.TTPN_MA
        FROM free_scope_ids s
        JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt ON rt.PHAM_NHAN_ID = s.ID
        LEFT JOIN cache_today c ON c.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        WHERE (v_text_filter_cnt > 0 OR v_address_filter_cnt > 0 OR v_tha_filter_cnt > 0)
          AND NVL(rt.IS_DELETED, 0) = 0
          AND rt.LL_TRAI_GIAM_ID IS NOT NULL
          AND rt.LL_TRAI_GIAM_ID IN (SELECT ID FROM valid_trai_ids)
          AND (v_ll_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
          AND (
                p_dash_loai_tk IS NULL
             OR EXISTS (SELECT 1 FROM dash_eligible_ids d WHERE d.ID = rt.PHAM_NHAN_ID)
          )
        UNION ALL
        -- (b) dashboard, KHÔNG có free-filter
        SELECT rt.PHAM_NHAN_ID, rt.LL_HO_TEN, rt.HO_TEN_ORDER, rt.LL_TINH_TRANG_ID,
               rt.LL_DM_GIOI_TINH_ID, rt.LL_DM_DAN_TOC_ID, rt.LL_DM_QUOC_TICH_ID, rt.LL_DM_TON_GIAO_ID,
               rt.LL_PHAN_DOI_ID, rt.LL_PHAN_TRAI_ID,
               rt.LL_NGAY_SINH, rt.THA_NGAY_DEN_TRAI, rt.THA_NGAY_HET_HAN,
               c.TTPN_MA
        FROM dash_eligible_ids d
        JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt ON rt.PHAM_NHAN_ID = d.ID
        LEFT JOIN cache_today c ON c.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        WHERE p_dash_loai_tk IS NOT NULL
          AND v_text_filter_cnt = 0 AND v_address_filter_cnt = 0 AND v_tha_filter_cnt = 0
          AND NVL(rt.IS_DELETED, 0) = 0
          AND rt.LL_TRAI_GIAM_ID IS NOT NULL
          AND rt.LL_TRAI_GIAM_ID IN (SELECT ID FROM valid_trai_ids)
          AND (v_ll_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
        UNION ALL
        -- (c) non-dashboard, KHÔNG có free-filter -> toàn b? (rt_trai materialize ??y ?? ?úng ? nhánh này)
        SELECT rt.PHAM_NHAN_ID, rt.LL_HO_TEN, rt.HO_TEN_ORDER, rt.LL_TINH_TRANG_ID,
               rt.LL_DM_GIOI_TINH_ID, rt.LL_DM_DAN_TOC_ID, rt.LL_DM_QUOC_TICH_ID, rt.LL_DM_TON_GIAO_ID,
               rt.LL_PHAN_DOI_ID, rt.LL_PHAN_TRAI_ID,
               rt.LL_NGAY_SINH, rt.THA_NGAY_DEN_TRAI, rt.THA_NGAY_HET_HAN,
               c.TTPN_MA
        FROM rt_trai rt
        LEFT JOIN cache_today c ON c.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        WHERE p_dash_loai_tk IS NULL
          AND v_text_filter_cnt = 0 AND v_address_filter_cnt = 0 AND v_tha_filter_cnt = 0
    ),
    -- 1. L?c per-row trên driver_rows (eligibility ?ã thu h?p ? trên)
    filtered_prep AS (
        SELECT /*+ FIRST_ROWS(100) */
            rt.PHAM_NHAN_ID AS PHAM_NHAN_ID,
            rt.LL_HO_TEN AS HO_TEN,
            rt.HO_TEN_ORDER AS HO_TEN_ORDER
        FROM driver_rows rt
        WHERE (
            p_stt_tong_hop IS NULL
            OR (p_stt_tong_hop = 1  AND rt.TTPN_MA IN ('111', '112', '113', '114'))
            OR (p_stt_tong_hop = 2
                AND rt.TTPN_MA LIKE '112%'
                AND EXISTS (SELECT 1 FROM QLPN.PN_GIAM_RIENGS g
                    WHERE g.GR_PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
                      AND NVL(g.IS_DELETED, 0) = 0
                      AND (g.GR_NGAY_KETTHUC IS NULL OR g.GR_NGAY_KETTHUC >= v_ngay_xet)))
            OR (p_stt_tong_hop = 3
                AND rt.TTPN_MA LIKE '113%'
                AND EXISTS (SELECT 1 FROM QLPN.CHUA_BENH_BAT_BUOCS c
                    WHERE c.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                      AND NVL(c.IS_DELETED, 0) = 0))
            OR (p_stt_tong_hop = 4
                AND rt.TTPN_MA IN ('141', '142')
                AND EXISTS (SELECT 1 FROM QLPN.TRICH_XUATS tx
                    WHERE tx.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                      AND NVL(tx.IS_DELETED, 0) = 0
                      AND tx.TX_NGAY_TRA IS NULL
                      AND EXISTS (SELECT 1 FROM QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS lqd
                          WHERE lqd.ID = tx.TX_LOAI_LENH_ID
                            AND NVL(lqd.IS_DELETED, 0) = 0
                            AND lqd.LQDTX_MA = '1')))
            OR (p_stt_tong_hop = 5
                AND rt.TTPN_MA IN ('151', '152', '157')
                AND EXISTS (SELECT 1 FROM QLPN.TAM_DINH_CHIS tdc
                    WHERE tdc.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                      AND NVL(tdc.IS_DELETED, 0) = 0
                      AND tdc.NGAY_LAI IS NULL
                      AND EXISTS (SELECT 1 FROM QLPN.DM_LOAI_QUYET_DINH_TAM_DINH_CHIES lq
                          WHERE lq.ID = tdc.LOAI_QUYET_DINH_ID
                            AND NVL(lq.IS_DELETED, 0) = 0
                            AND lq.LQDTDC_MA = '1')))
            OR (p_stt_tong_hop = 6  AND rt.TTPN_MA = '126')
            OR (p_stt_tong_hop = 7  AND rt.THA_NGAY_DEN_TRAI IS NOT NULL AND rt.THA_NGAY_HET_HAN >= v_ngay_xet AND rt.THA_NGAY_HET_HAN < v_ngay_xet + 1)
            OR (p_stt_tong_hop = 8  AND rt.TTPN_MA IN ('111', '112', '113', '114') AND rt.THA_NGAY_DEN_TRAI IS NOT NULL AND rt.THA_NGAY_HET_HAN >= v_ngay_xet + 1 AND rt.THA_NGAY_HET_HAN < v_ngay_xet + 2)
            OR (p_stt_tong_hop = 9  AND rt.TTPN_MA IN ('111', '112', '113', '114') AND rt.THA_NGAY_DEN_TRAI IS NOT NULL AND rt.THA_NGAY_HET_HAN >= v_ngay_xet + 1 AND rt.THA_NGAY_HET_HAN < ADD_MONTHS(v_ngay_xet + 1, 2) + 1)
            OR (p_stt_tong_hop = 10 AND rt.TTPN_MA = '123')
            OR (p_stt_tong_hop = 11 AND v_ll_trai_giam_id IS NOT NULL AND EXISTS (SELECT 1 FROM QLPN.PHAM_NHAN_CHUYEN_TRAI ct WHERE ct.PNCT_LAI_LICH_ID = rt.PHAM_NHAN_ID AND NVL(ct.IS_DELETED, 0) = 0))
            OR (p_stt_tong_hop = 12 AND EXISTS (SELECT 1 FROM QLPN.PN_KET_THUC_CHETS k WHERE k.KTC_PN_LAI_LICH_ID = rt.PHAM_NHAN_ID AND NVL(k.IS_DELETED, 0) = 0 AND k.KTC_NGAY_CHET >= TRUNC(SYSDATE, 'YEAR')))
            OR (p_stt_tong_hop = 13 AND EXISTS (SELECT 1 FROM QLPN.TRON_TRAIS tt WHERE tt.PHAM_NHAN_ID = rt.PHAM_NHAN_ID AND NVL(tt.IS_DELETED, 0) = 0 AND tt.NGAY_BAT_LAI IS NULL))
            OR (p_stt_tong_hop = 14 AND EXISTS (SELECT 1 FROM QLPN.HUY_ANS h WHERE h.PHAM_NHAN_ID = rt.PHAM_NHAN_ID AND NVL(h.IS_DELETED, 0) = 0 AND h.NGAY_TRA_TU_DO IS NOT NULL))
            OR (p_stt_tong_hop = 15 AND EXISTS (SELECT 1 FROM QLPN.MIEN_HINH_PHATS m WHERE m.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID AND NVL(m.IS_DELETED, 0) = 0 AND m.MHP_NGAY_TU_DO IS NOT NULL))
            OR (p_stt_tong_hop = 16 AND EXISTS (SELECT 1 FROM QLPN.HOAN_THI_HANH_ANS h WHERE h.PHAM_NHAN_ID = rt.PHAM_NHAN_ID AND NVL(h.IS_DELETED, 0) = 0))
        )
        AND (p_gioi_tinh_id IS NULL OR rt.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
        AND (p_phan_doi IS NULL OR rt.LL_PHAN_DOI_ID = p_phan_doi)
        AND (p_phan_trai IS NULL OR rt.LL_PHAN_TRAI_ID = p_phan_trai)
        AND (p_tinh_trang_id IS NULL OR rt.LL_TINH_TRANG_ID = p_tinh_trang_id)
        AND (p_dan_toc_id IS NULL OR rt.LL_DM_DAN_TOC_ID = p_dan_toc_id)
        AND (p_quoc_tich_id IS NULL OR rt.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
        AND (p_ton_giao_id IS NULL OR rt.LL_DM_TON_GIAO_ID = p_ton_giao_id)
        AND (v_like_ngaysinh IS NULL OR rt.LL_NGAY_SINH LIKE v_like_ngaysinh)
        -- ??a ch? ?ã l?c trong free_scope_ids
        -- Filter thân nhân: QH_ID ???c pre-compute 1 l?n t? b?ng DM nh?, lo?i b? correlated JOIN per row
        AND (
            v_like_bo IS NULL
            OR EXISTS (
                SELECT 1 FROM QLPN.THAN_NHAN_NGUOI_THANS tn
                WHERE tn.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                  AND tn.IS_DELETED = 0
                  AND tn.QUAN_HE_ID IN (SELECT ID FROM qh_bo_ids)
                  AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(tn.HO_TEN_THAN_NHAN)), 1, 400) LIKE v_like_bo
            )
        )
        AND (
            v_like_me IS NULL
            OR EXISTS (
                SELECT 1 FROM QLPN.THAN_NHAN_NGUOI_THANS tn
                WHERE tn.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                  AND tn.IS_DELETED = 0
                  AND tn.QUAN_HE_ID IN (SELECT ID FROM qh_me_ids)
                  AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(tn.HO_TEN_THAN_NHAN)), 1, 400) LIKE v_like_me
            )
        )
        AND (
            v_like_vc IS NULL
            OR EXISTS (
                SELECT 1 FROM QLPN.THAN_NHAN_NGUOI_THANS tn
                WHERE tn.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
                  AND tn.IS_DELETED = 0
                  AND tn.QUAN_HE_ID IN (SELECT ID FROM qh_vc_ids)
                  AND SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(tn.HO_TEN_THAN_NHAN)), 1, 400) LIKE v_like_vc
            )
        )
        AND (
            -- THA ?ã l?c trong toi_danh_scope_ids / free_scope_ids khi v_tha_filter_cnt > 0
            v_tha_filter_cnt > 0
            OR (p_stt_tong_hop IS NOT NULL AND v_toi_danh_id IS NULL)
            OR v_tha_filter_cnt = 0
        )
    ),
    -- P0-2: total_count tách kh?i paginate — tránh WINDOW SORT toàn b? filtered_prep
    filtered_count AS (
        SELECT COUNT(*) AS total_count
        FROM filtered_prep
    ),
    -- 2. Phân trang nhanh (Pagination) — không COUNT(*) OVER ()
    paged_ids AS (
        SELECT /*+ MATERIALIZE */
            f.PHAM_NHAN_ID,
            f.HO_TEN,
            f.HO_TEN_ORDER
        FROM filtered_prep f
        ORDER BY f.HO_TEN_ORDER, f.PHAM_NHAN_ID DESC
        OFFSET v_skip ROWS
        FETCH NEXT CASE WHEN v_limit > 0 THEN v_limit ELSE 999999999 END ROWS ONLY
    ),
    -- Drive NL ~25 PHAM_NHAN_ID ? view (tránh merge full scan VW trên toàn RT)
    page_detail AS (
        SELECT /*+ MATERIALIZE LEADING(p) USE_NL(v) */
            v.*
        FROM paged_ids p
        LEFT JOIN QLPN.VW_PN_LAI_LICH_CHI_TIET v ON v.PHAM_NHAN_ID = p.PHAM_NHAN_ID
    ),
    -- 3. Join chi ti?t trang và mapping alias
    rows_page AS (
        SELECT
            fc.total_count,
            v.*,
            -- Ánh x? l?i các tên c?t có ti?n t? LL_ ?? kh?p v?i SELECT cu?i cùng
            v.NOI_OTRUOC_KHI_BAT      AS LL_NOI_OTRUOC_KHI_BAT,
            v.SO_HO_PHU               AS LL_SO_HO_PHU,
            v.HO_CHIEU                AS LL_HO_CHIEU,
            v.LL_DM_DAN_TOC_ID        AS ID_DAN_TOC,
            v.LL_DM_TON_GIAO_ID       AS ID_TON_GIAO,
            v.LL_DM_HOC_VAN_ID        AS ID_TRINH_DO_HOC_VAN,
            v.LL_DM_NGHE_NGHIEP_ID    AS ID_NGHE_NGHIEP,
            v.LL_SUC_KHOE_KHI_VAO_ID  AS ID_SUC_KHOE_KHI_VAO,
            dmttpn.TTPN_TEN AS TEN_TINH_TRANG,
--            CASE
--                WHEN NULLIF(TRIM(CAST(v.NOI_THA_VE_CU_TRU AS VARCHAR2(4000))), '') IS NOT NULL
--                  OR NULLIF(TRIM(CAST(v.NOI_THA_VE_CU_TRU_XA AS VARCHAR2(4000))), '') IS NOT NULL
--                  OR NULLIF(TRIM(CAST(v.NOI_THA_VE_CU_TRU_TINH AS VARCHAR2(4000))), '') IS NOT NULL
--                THEN TRIM(
--                    NVL(NULLIF(TRIM(CAST(v.NOI_THA_VE_CU_TRU AS VARCHAR2(4000))), ''), '')
--                    || CASE
--                        WHEN NULLIF(TRIM(CAST(v.NOI_THA_VE_CU_TRU_XA AS VARCHAR2(4000))), '') IS NOT NULL THEN
--                            CASE
--                                WHEN NULLIF(TRIM(CAST(v.NOI_THA_VE_CU_TRU AS VARCHAR2(4000))), '') IS NOT NULL
--                                    THEN ', ' || TRIM(CAST(v.NOI_THA_VE_CU_TRU_XA AS VARCHAR2(4000)))
--                                ELSE TRIM(CAST(v.NOI_THA_VE_CU_TRU_XA AS VARCHAR2(4000)))
--                            END
--                        ELSE ''
--                       END
--                    || CASE
--                        WHEN NULLIF(TRIM(CAST(v.NOI_THA_VE_CU_TRU_TINH AS VARCHAR2(4000))), '') IS NOT NULL THEN
--                            CASE
--                                WHEN NULLIF(TRIM(CAST(v.NOI_THA_VE_CU_TRU AS VARCHAR2(4000))), '') IS NOT NULL
--                                  OR NULLIF(TRIM(CAST(v.NOI_THA_VE_CU_TRU_XA AS VARCHAR2(4000))), '') IS NOT NULL
--                                    THEN ', ' || TRIM(CAST(v.NOI_THA_VE_CU_TRU_TINH AS VARCHAR2(4000)))
--                                ELSE TRIM(CAST(v.NOI_THA_VE_CU_TRU_TINH AS VARCHAR2(4000)))
--                            END
--                        ELSE ''
--                       END
--                )
--                ELSE NULL
--            END AS NOI_THA_VE_DAY_DU,
            v.NOI_THA_VE_CU_TRU AS NOI_THA_VE_DAY_DU,
            CASE
                WHEN NVL(v.SO_LAN_GIAM, 0) = 0
                  OR v.THOI_GIAN_DA_GIAM IS NULL
                  OR NULLIF(TRIM(CAST(v.THOI_GIAN_DA_GIAM AS NVARCHAR2(2000))), u'0') IS NULL
                THEN u'Kh\00f4ng'
                ELSE TO_NCHAR(v.SO_LAN_GIAM) || u' l\1ea7n = '
                     || CAST(v.THOI_GIAN_DA_GIAM AS NVARCHAR2(2000))
            END AS calc_da_giam,
            CAST(v.THOI_GIAN_DA_CHAP_HANH AS NVARCHAR2(2000)) AS calc_da_chap_hanh,
            CAST(v.THOI_GIAN_CON_LAI AS NVARCHAR2(2000)) AS calc_con_lai
        FROM paged_ids p
        CROSS JOIN filtered_count fc
        LEFT JOIN page_detail v ON v.PHAM_NHAN_ID = p.PHAM_NHAN_ID
        LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS dmttpn
            ON dmttpn.ID = v.LL_TINH_TRANG_ID
           AND NVL(dmttpn.IS_DELETED, 0) = 0
    )
    SELECT
        p.total_count     AS "totalCount",
        p.LL_ANH          AS "anh",
        p.SO_HO_SO        AS "soHoSoLanDau",
        p.LL_SO_HO_PHU    AS "soHoPhu",
        p.CCCD            AS "cccd",
        p.LL_HO_CHIEU     AS "hoChieu",
        p.HO_TEN          AS "hoTen",
        p.GIOI_TINH_ID    AS "gioiTinhId",
        p.GIOI_TINH       AS "gioiTinhName",
        CASE
            WHEN p.NGAY_SINH IS NOT NULL
                 AND REGEXP_LIKE(TRIM(CAST(p.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
            THEN TO_CHAR(TO_DATE(TRIM(CAST(p.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY'), 'DD/MM/YYYY')
            WHEN p.NAM_SINH IS NOT NULL AND p.NAM_SINH > 0 THEN TO_CHAR(p.NAM_SINH)
            WHEN p.NGAY_SINH IS NOT NULL THEN TRIM(CAST(p.NGAY_SINH AS VARCHAR2(100)))
            ELSE NULL
        END AS "ngaySinh",
        p.LL_PHAN_TRAI_ID AS "phanTraiId",
        p.PHAN_TRAI       AS "phanTraiName",
        p.PHAN_DOI_ID     AS "phanDoiId",
        p.PHAN_DOI        AS "phanDoiName",
        p.LL_TINH_TRANG_ID AS "tinhTrangId",
        CAST(p.TEN_TINH_TRANG AS NVARCHAR2(500)) AS "tinhTrangName",
        p.TEN_KHAC        AS "tenKhac",
        p.NOI_THUONG_TRU_DAY_DU AS "diaChiThuongTru",
        p.DIA_CHI_THUONG_TRU AS "diaChiThuongTruShort",
        p.LL_NOI_OTRUOC_KHI_BAT AS "noiOTruocKhiBat",
        p.NOI_O_KHAC      AS "noiOKhac",
        p.NGUYEN_QUAN     AS "nguyenQuan",
        p.NOI_THA_VE_DAY_DU AS "noiThaVeCuTru",
        p.ID_DAN_TOC      AS "danTocId",
        p.DAN_TOC         AS "danTocName",
        p.ID_TON_GIAO     AS "tonGiaoId",
        p.TON_GIAO        AS "tonGiaoName",
        p.QUOC_TICH_ID    AS "quocTichId",
        p.QUOC_TICH       AS "quocTichName",
        p.ID_TRINH_DO_HOC_VAN AS "trinhDoHocVanId",
        p.HOC_VAN         AS "trinhDoHocVanName",
        p.ID_NGHE_NGHIEP  AS "ngheNghiepId",
        p.NGHE_NGHIEP     AS "ngheNghiepName",
        p.ID_SUC_KHOE_KHI_VAO AS "sucKhoeKhiVaoId",
        p.TINH_TRANG_SUC_KHOE AS "sucKhoeKhiVaoName",
        p.TOI_DANH        AS "toiDanh",
        p.TOI_DANH_ID     AS "toiDanhIds",
        p.NGAY_BAT_AN_PHAT AS "ngayBat",
        p.NGAY_DEN_TRAI   AS "ngayDenTrai",
        p.AN_PHAT         AS "anPhat",
        p.THA_MA_AN_PHAT  AS "maAnPhat",
        p.SO_BAN_AN       AS "soBanAn",
        p.SO_QD_THA       AS "soQdTha",
        p.NGAY_HET_AN     AS "ngayHetHan",
        p.calc_con_lai    AS "thoiGianConLai",
        p.SO_TIEN_AN      AS "tienAn",
        p.calc_da_giam    AS "daGiam",
        p.calc_da_chap_hanh AS "daChapHanh",
        p.LL_DIA_CHI_THUONG_TRU_PROVICE AS "diaChiThuongTruProvice",
        p.TINH_THANH_THUONG_TRU AS "diaChiThuongTruProviceName",
        p.LL_DIA_CHI_THUONG_TRU_WARD AS "diaChiThuongTruWard",
        p.PHUONG_XA_THUONG_TRU AS "diaChiThuongTruWardName",
        p.SO_QD_DIEU_CHUYEN AS "soQuyetDinhDieuChuyen",
        p.PHAM_NHAN_ID    AS "id"
    FROM rows_page p
    ORDER BY p.HO_TEN_ORDER, p.PHAM_NHAN_ID DESC, p.CCCD;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(
            -20001,
            u'L\1ed7i t\00ecm ki\1ebfm l\00e1i l\1ecbch: ' || SQLERRM
        );



-- BEGIN 
--     QLPN.SP_GET_TIM_KIEM_PN_LAI_LICH(
--         p_like_dash       => N'Nguy?n V?n', 
--         p_maxresultcount  => 25, 
--         p_skipcount       => 0
--     ); 
-- END;
END ;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TINH_HINH_CHAPT_PHAM_NHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TINH_HINH_CHAPT_PHAM_NHAN" (
--    p_pn_ids   IN VARCHAR2 DEFAULT NULL,
    p_tu_ngay  IN DATE     DEFAULT NULL,
    p_den_ngay IN DATE     DEFAULT NULL,
    p_quy_id   IN NUMBER   DEFAULT NULL,
    p_nam_id   IN NUMBER   DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        WITH
        /* 1. Parse ID */
        NUM_GEN AS (
            SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL <= 100
        ),
        ID_LIST AS (
        SELECT PN_ID 
    	FROM QLPN.GTT_PN_IDS
        ),

        /* 2. B?n án m?i nh?t — FIX: tránh bung dòng ? query chính */
        LATEST_THA AS (
            SELECT
                THA_PNLAI_LICH_ID,
                THA_AN_PHAT,
                THA_NGAY_BAT,
                THA_NGAY_HET_HAN,
                THA_TOI_DANH,
                ROW_NUMBER() OVER (
                    PARTITION BY THA_PNLAI_LICH_ID
                    ORDER BY NVL(THA_NGAY_BAN_AN, DATE '1900-01-01') DESC, ID DESC
                ) AS rn
            FROM PN_THI_HANH_AN
            WHERE NVL(IS_DELETED, 0) = 0
              AND (THA_PNLAI_LICH_ID IN (SELECT PN_ID FROM ID_LIST))
        ),

        /* 3. Tách t?i danh t? b?n án m?i nh?t */
        THA_LATEST AS (SELECT * FROM LATEST_THA WHERE rn = 1),
        SPLIT_TOI_DANH AS (
            SELECT
                ltha.THA_PNLAI_LICH_ID,
                TO_NUMBER(TRIM(REGEXP_SUBSTR(
                    REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''),
                    '[^,]+', 1, ng.N
                ))) AS TOI_DANH_ID
            FROM THA_LATEST ltha
            JOIN NUM_GEN ng
                ON ng.N <= REGEXP_COUNT(
                       REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
            WHERE ltha.THA_TOI_DANH IS NOT NULL
              AND REGEXP_SUBSTR(
                      REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''),
                      '[^,]+', 1, ng.N) IS NOT NULL
        ),
        SPLIT_TOI_DANH_DEDUP AS (
            SELECT DISTINCT THA_PNLAI_LICH_ID, TOI_DANH_ID FROM SPLIT_TOI_DANH
        ),
        TOI_DANH_AGG AS (
            SELECT
                s.THA_PNLAI_LICH_ID,
                LISTAGG(dtd.TD_TEN, ', ')
                    WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH
            FROM SPLIT_TOI_DANH_DEDUP s
            LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
            GROUP BY s.THA_PNLAI_LICH_ID
        ),

        /* 4. Hình ph?t b? sung */
        TIEN_DA_NOP AS (
            SELECT bl.HPBS_ID, SUM(bl.BL_SO_TIEN) AS TONG_TIEN_DA_NOP
            FROM PN_BIENLAIES bl
            JOIN PN_HINH_PHAT_BO_SUNGS hpbs_f
                ON hpbs_f.ID = bl.HPBS_ID AND hpbs_f.IS_DELETED = 0
               AND ( hpbs_f.HPBS_MA_PHAM_NHAN IN (SELECT PN_ID FROM ID_LIST))
            WHERE bl.IS_DELETED = 0
            GROUP BY bl.HPBS_ID
        ),
        HPBS_AGG AS (
            SELECT
                hpbs.HPBS_MA_PHAM_NHAN,
                LISTAGG(
                    dm_hpbs.HPBS_TEN || ' ' ||
                    TO_CHAR(hpbs.HPBS_TONG_TIEN_PHAT, 'FM999,999,999,999') || ' ??ng, ?ã n?p ' ||
                    TO_CHAR(NVL(tdn.TONG_TIEN_DA_NOP, 0), 'FM999,999,999,999') || ' ??ng',
                    '; '
                ) WITHIN GROUP (ORDER BY hpbs.ID) AS HINH_PHAT_BO_SUNG
            FROM PN_HINH_PHAT_BO_SUNGS hpbs
            LEFT JOIN DM_HINH_PHAT_BO_SUNGS dm_hpbs ON hpbs.HPBS_HINH_PHAT = dm_hpbs.ID
            LEFT JOIN TIEN_DA_NOP tdn ON hpbs.ID = tdn.HPBS_ID
            WHERE hpbs.IS_DELETED = 0
              AND ( hpbs.HPBS_MA_PHAM_NHAN IN (SELECT PN_ID FROM ID_LIST))
            GROUP BY hpbs.HPBS_MA_PHAM_NHAN
        ),
/* 5. Ng??i thân — gi? nhi?u dòng theo yêu c?u nghi?p v? */
		NGUOI_THAN AS (
		    SELECT
		        tnnt.PHAM_NHAN_ID,
		        tnnt.HO_TEN_THAN_NHAN,
		        tnnt.NOI_O,
		        dgt.GT_TEN AS GIOI_TINH_NGUOI_THAN
		    FROM THAN_NHAN_NGUOI_THANS tnnt
		    LEFT JOIN DM_GIOI_TINHS dgt ON tnnt.GIOI_TINH_ID = dgt.ID
		    WHERE tnnt.IS_DELETED = 0
		      AND tnnt.THONG_BAO  = 1
		      AND ( tnnt.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
		)

        SELECT
            pll.ID,
            pll.LL_HO_TEN                                     AS "HoTen",
            dgt.GT_TEN                                         AS "GioiTinh",
            pll.LL_NGAY_SINH                                   AS "NamSinh",
            pll.LL_TEN_KHAC                                    AS "TenKhac",
            pll.LL_NGUYEN_QUAN                                 AS "NguyenQuan",
			-- THAY TH? toàn b? ph?n CASE DiaChiThuongTru trong SELECT:
			CASE
			    WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
			      OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'')     IS NOT NULL
			      OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'')    IS NOT NULL
			    THEN TRIM(
			            NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
			            || CASE WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
			                    CASE WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
			                         THEN u', ' || dxp_thuong_tru.XP_TEN
			                         ELSE dxp_thuong_tru.XP_TEN END
			               ELSE u'' END
			            || CASE WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
			                    CASE WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
			                           OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
			                         THEN u', ' || dttp_thuong_tru.TTP_TEN
			                         ELSE dttp_thuong_tru.TTP_TEN END
			               ELSE u'' END
			        )
			    ELSE NULL
			END AS "DiaChiThuongTru",
            tda.TOI_DANH                                       AS "ToiDanh",
            TO_CHAR(ptha.THA_NGAY_BAT, 'DD/MM/YYYY')          AS "NgayBat",
            ptha.THA_AN_PHAT                                   AS "AnPhat",
            hpbs_agg.HINH_PHAT_BO_SUNG                        AS "HinhPhatBoSung",
            dpd.PD_TEN                                         AS "PhanDoi",
            dpt.PT_TEN                                         AS "PhanTrai",
            CASE p_quy_id
                WHEN 1 THEN xl_q1.XLCT_TEN
                WHEN 2 THEN xl_q2.XLCT_TEN
                WHEN 3 THEN xl_q3.XLCT_TEN
                WHEN 4 THEN xl_q4.XLCT_TEN
                ELSE        xl_ca.XLCT_TEN
            END                                                AS "XepLoai",
            CASE
                WHEN ptha.THA_NGAY_HET_HAN IS NULL           THEN '?ang ch?p hành án ph?t tù'
                WHEN ptha.THA_NGAY_HET_HAN > SYSDATE          THEN '?ang ch?p hành án ph?t tù'
                ELSE                                               '?ã ra tù'
            END                                                AS "TinhTrang",
            ntut.HO_TEN_THAN_NHAN                             AS "NguoiThan",
            ntut.NOI_O                                         AS "DiaChiNguoiThan",
            ntut.GIOI_TINH_NGUOI_THAN                         AS "GioiTinhNguoiThan",
            TO_CHAR(p_tu_ngay,  'DD/MM/YYYY')                 AS "TuNgay",
            TO_CHAR(p_den_ngay, 'DD/MM/YYYY')                 AS "DenNgay",
            NULL                                               AS "NhanXet",
            NULL                                               AS "ThongBao"

        FROM PN_LAI_LICHS pll
        LEFT JOIN ID_LIST il               ON il.PN_ID = pll.ID
        LEFT JOIN DM_GIOI_TINHS dgt        ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
            ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
           AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
        LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
            ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
           AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
        -- FIX: dùng LATEST_THA thay join tr?c ti?p b?ng
        LEFT JOIN THA_LATEST ptha          ON ptha.THA_PNLAI_LICH_ID = pll.ID
        LEFT JOIN DM_PHAN_DOIS dpd         ON pll.LL_PHAN_DOI_ID = dpd.ID
        LEFT JOIN DM_PHAN_TRAIS dpt        ON pll.LL_PHAN_TRAI_ID = dpt.ID
        LEFT JOIN TOI_DANH_AGG tda         ON tda.THA_PNLAI_LICH_ID = pll.ID
        LEFT JOIN HPBS_AGG hpbs_agg        ON hpbs_agg.HPBS_MA_PHAM_NHAN = pll.ID
        LEFT JOIN NGUOI_THAN ntut          ON ntut.PHAM_NHAN_ID = pll.ID
        LEFT JOIN XEP_LOAIS xl
            ON xl.PHAM_NHAN_ID = pll.ID
           AND xl.XEP_LOAI_NAM = p_nam_id
           AND xl.IS_DELETED   = 0
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q1 ON xl.XEP_LOAI_QUY_I   = xl_q1.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q2 ON xl.XEP_LOAI_QUY_II  = xl_q2.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q3 ON xl.XEP_LOAI_QUY_III = xl_q3.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q4 ON xl.XEP_LOAI_QUY_IV  = xl_q4.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_ca ON xl.XEP_LOAI_CA_NAM  = xl_ca.ID

        WHERE ( pll.ID IN (SELECT PN_ID FROM ID_LIST))
        ORDER BY 
        --il.ORD NULLS LAST, 
        pll.ID;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_TINH_HINH_CHAPT_PHAM_NHAN;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TINH_HINH_CHAPT_PHAM_NHAN_PT23
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TINH_HINH_CHAPT_PHAM_NHAN_PT23" (
    --p_pn_ids   IN VARCHAR2 DEFAULT NULL,
    p_tu_ngay  IN DATE     DEFAULT NULL,
    p_den_ngay IN DATE     DEFAULT NULL,
    p_quy_id   IN NUMBER   DEFAULT NULL,
    p_nam_id   IN NUMBER   DEFAULT NULL
)
AS
    c1     SYS_REFCURSOR;
    c_fmt  CONSTANT VARCHAR2(200) := 'FM999G999G999G999G999G999G999G999G999';
    c_dots CONSTANT VARCHAR2(50)  := '……………………';
BEGIN
    OPEN c1 FOR
        WITH
        /* 1. Parse ID */
        NUM_GEN AS (
            SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL <= 100
        ),
        /* ID_LIST gi? ??c tr?c ti?p t? QLPN.GTT_PN_IDS (n?p tr??c b?ng
           InsertIdsToGttAsync/array binding) thay vì t? parse chu?i p_pn_ids
           b?ng REGEXP_SUBSTR — cách c? b? gi?i h?n c?ng t?i ?a 100 ID do
           NUM_GEN CONNECT BY LEVEL <= 100 ? trên, âm th?m c?t b?t ID khi
           danh sách ph?m nhân dài h?n 100. Cùng khuôn m?u v?i
           SP_GET_DS_PN_DE_NGHI_THA_CO_DK_NEW. */
        ID_LIST AS (
            SELECT PN_ID FROM QLPN.GTT_PN_IDS
        ),

        /* 2. B?n án m?i nh?t — FIX: tránh bung dòng ? query chính */
        LATEST_THA AS (
            SELECT
                THA_PNLAI_LICH_ID,
                THA_AN_PHAT,
                THA_NGAY_BAT,
                THA_NGAY_HET_HAN,
                THA_TOI_DANH,
                ROW_NUMBER() OVER (
                    PARTITION BY THA_PNLAI_LICH_ID
                    ORDER BY NVL(THA_NGAY_BAN_AN, DATE '1900-01-01') DESC, ID DESC
                ) AS rn
            FROM PN_THI_HANH_AN
            WHERE NVL(IS_DELETED, 0) = 0
              AND (NOT EXISTS (SELECT 1 FROM QLPN.GTT_PN_IDS) OR THA_PNLAI_LICH_ID IN (SELECT PN_ID FROM ID_LIST))
        ),

        /* 3. Tách t?i danh t? b?n án m?i nh?t */
        THA_LATEST AS (SELECT * FROM LATEST_THA WHERE rn = 1),
        SPLIT_TOI_DANH AS (
            SELECT
                ltha.THA_PNLAI_LICH_ID,
                TO_NUMBER(TRIM(REGEXP_SUBSTR(
                    REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''),
                    '[^,]+', 1, ng.N
                ))) AS TOI_DANH_ID
            FROM THA_LATEST ltha
            JOIN NUM_GEN ng
                ON ng.N <= REGEXP_COUNT(
                       REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
            WHERE ltha.THA_TOI_DANH IS NOT NULL
              AND REGEXP_SUBSTR(
                      REPLACE(REPLACE(ltha.THA_TOI_DANH, '[', ''), ']', ''),
                      '[^,]+', 1, ng.N) IS NOT NULL
        ),
        SPLIT_TOI_DANH_DEDUP AS (
            SELECT DISTINCT THA_PNLAI_LICH_ID, TOI_DANH_ID FROM SPLIT_TOI_DANH
        ),
        TOI_DANH_AGG AS (
            SELECT
                s.THA_PNLAI_LICH_ID,
                LISTAGG(dtd.TD_TEN, ', ')
                    WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH
            FROM SPLIT_TOI_DANH_DEDUP s
            LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = s.TOI_DANH_ID
            GROUP BY s.THA_PNLAI_LICH_ID
        ),

        /* 4. Hình ph?t b? sung */
        TIEN_DA_NOP AS (
            SELECT bl.HPBS_ID, SUM(bl.BL_SO_TIEN) AS TONG_TIEN_DA_NOP
            FROM PN_BIENLAIES bl
            JOIN PN_HINH_PHAT_BO_SUNGS hpbs_f
                ON hpbs_f.ID = bl.HPBS_ID AND hpbs_f.IS_DELETED = 0
               AND (NOT EXISTS (SELECT 1 FROM QLPN.GTT_PN_IDS) OR hpbs_f.HPBS_MA_PHAM_NHAN IN (SELECT PN_ID FROM ID_LIST))
            WHERE bl.IS_DELETED = 0
            GROUP BY bl.HPBS_ID
        ),
/* 5. Ng??i thân — gi? nhi?u dòng theo yêu c?u nghi?p v? */
		NGUOI_THAN AS (
		    SELECT
		        tnnt.PHAM_NHAN_ID,
		        tnnt.HO_TEN_THAN_NHAN,
		        tnnt.NOI_O,
		        dgt.GT_TEN AS GIOI_TINH_NGUOI_THAN
		    FROM THAN_NHAN_NGUOI_THANS tnnt
		    LEFT JOIN DM_GIOI_TINHS dgt ON tnnt.GIOI_TINH_ID = dgt.ID
		    WHERE tnnt.IS_DELETED = 0
		      AND tnnt.THONG_BAO  = 1
		      AND (NOT EXISTS (SELECT 1 FROM QLPN.GTT_PN_IDS) OR tnnt.PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
		),

        /* 6. X?p lo?i cu?i — dùng khi p_nam_id không ???c truy?n:
              duy?t t?t c? quý c?a t?t c? n?m, l?y quý g?n nh?t còn giá tr? */
        XEP_LOAI_PIVOT AS (
            SELECT PHAM_NHAN_ID, XEP_LOAI_NAM AS NAM, 1 AS QUY, XEP_LOAI_QUY_I   AS XLCT_ID FROM XEP_LOAIS WHERE IS_DELETED = 0
            UNION ALL
            SELECT PHAM_NHAN_ID, XEP_LOAI_NAM AS NAM, 2 AS QUY, XEP_LOAI_QUY_II  AS XLCT_ID FROM XEP_LOAIS WHERE IS_DELETED = 0
            UNION ALL
            SELECT PHAM_NHAN_ID, XEP_LOAI_NAM AS NAM, 3 AS QUY, XEP_LOAI_QUY_III AS XLCT_ID FROM XEP_LOAIS WHERE IS_DELETED = 0
            UNION ALL
            SELECT PHAM_NHAN_ID, XEP_LOAI_NAM AS NAM, 4 AS QUY, XEP_LOAI_QUY_IV  AS XLCT_ID FROM XEP_LOAIS WHERE IS_DELETED = 0
        ),
        XEP_LOAI_CUOI AS (
            SELECT
                PHAM_NHAN_ID, XLCT_ID,
                ROW_NUMBER() OVER (PARTITION BY PHAM_NHAN_ID ORDER BY NAM DESC, QUY DESC) AS rn
            FROM XEP_LOAI_PIVOT
            WHERE XLCT_ID IS NOT NULL
              AND (NOT EXISTS (SELECT 1 FROM QLPN.GTT_PN_IDS) OR PHAM_NHAN_ID IN (SELECT PN_ID FROM ID_LIST))
        ),

        /* 7. Hình ph?t b? sung — tính tr?c ti?p trong SP này (không g?i
              FN_GET_THONG_TIN_HPBS_PT dùng chung), cùng format 1 chu?i g?p nhi?u dòng
              nh? hàm g?c, ch? khác: "Ngh?a v? dân s? khác" ch? l?y mã 237, b? Truy thu (212).
              Mã HPBS: 220 Ph?t ti?n, 236 B?i th??ng thi?t h?i, 235 Ngh?a v? tr? l?i tài s?n,
              237 Ngh?a v? dân s? khác, 250 Án phí hình s?, 260 Án phí dân s? */
        HPBS_AGG AS (
            SELECT
                hp.HPBS_MA_PHAM_NHAN AS PHAM_NHAN_ID,
                dm.HPBS_MA,
                SUM(NVL(hp.HPBS_TONG_TIEN_PHAT, 0))    AS TONG,
                SUM(NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0)) AS CON_LAI
            FROM PN_HINH_PHAT_BO_SUNGS hp
            JOIN DM_HINH_PHAT_BO_SUNGS dm
                ON dm.ID = hp.HPBS_HINH_PHAT
               AND NVL(dm.IS_DELETED, 0) = 0
               AND dm.HPBS_MA IN (220, 236, 235, 237, 250, 260)
            WHERE NVL(hp.IS_DELETED, 0) = 0
              AND (NOT EXISTS (SELECT 1 FROM QLPN.GTT_PN_IDS) OR hp.HPBS_MA_PHAM_NHAN IN (SELECT PN_ID FROM ID_LIST))
            GROUP BY hp.HPBS_MA_PHAM_NHAN, dm.HPBS_MA
        ),
        HPBS_PIVOT AS (
            SELECT
                PHAM_NHAN_ID,
                MAX(CASE WHEN HPBS_MA = 220 THEN TONG    END) AS PT_TONG,
                MAX(CASE WHEN HPBS_MA = 220 THEN CON_LAI END) AS PT_CONLAI,
                MAX(CASE WHEN HPBS_MA = 236 THEN TONG    END) AS BT_TONG,
                MAX(CASE WHEN HPBS_MA = 236 THEN CON_LAI END) AS BT_CONLAI,
                MAX(CASE WHEN HPBS_MA = 235 THEN TONG    END) AS TLTS_TONG,
                MAX(CASE WHEN HPBS_MA = 235 THEN CON_LAI END) AS TLTS_CONLAI,
                MAX(CASE WHEN HPBS_MA = 237 THEN TONG    END) AS NVK_TONG,
                MAX(CASE WHEN HPBS_MA = 250 THEN TONG    END) AS APHS_TONG,
                MAX(CASE WHEN HPBS_MA = 250 THEN CON_LAI END) AS APHS_CONLAI,
                MAX(CASE WHEN HPBS_MA = 260 THEN TONG    END) AS APDS_TONG,
                MAX(CASE WHEN HPBS_MA = 260 THEN CON_LAI END) AS APDS_CONLAI
            FROM HPBS_AGG
            GROUP BY PHAM_NHAN_ID
        )

        SELECT
            pll.ID,
            pll.LL_HO_TEN                                     AS "HoTen",
            dgt.GT_TEN                                         AS "GioiTinh",
            pll.LL_NGAY_SINH                                   AS "NamSinh",
            pll.LL_TEN_KHAC                                    AS "TenKhac",
            pll.LL_NGUYEN_QUAN                                 AS "NguyenQuan",
			-- THAY TH? toàn b? ph?n CASE DiaChiThuongTru trong SELECT:
			CASE
			    WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
			      OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'')     IS NOT NULL
			      OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'')    IS NOT NULL
			    THEN TRIM(
			            NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
			            || CASE WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
			                    CASE WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
			                         THEN u', ' || dxp_thuong_tru.XP_TEN
			                         ELSE dxp_thuong_tru.XP_TEN END
			               ELSE u'' END
			            || CASE WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
			                    CASE WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
			                           OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
			                         THEN u', ' || dttp_thuong_tru.TTP_TEN
			                         ELSE dttp_thuong_tru.TTP_TEN END
			               ELSE u'' END
			        )
			    ELSE NULL
			END AS "DiaChiThuongTru",
            tda.TOI_DANH                                       AS "ToiDanh",
            TO_CHAR(ptha.THA_NGAY_BAT, 'DD/MM/YYYY')          AS "NgayBat",
            ptha.THA_AN_PHAT                                   AS "AnPhat",
            (   'Ph?t ti?n: '
                || CASE WHEN hp.PT_TONG IS NULL OR hp.PT_TONG = 0 THEN c_dots ELSE TO_CHAR(hp.PT_TONG, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng; ?ã th?c hi?n: '
                || CASE WHEN hp.PT_TONG IS NULL OR hp.PT_TONG = 0 THEN c_dots ELSE TO_CHAR(hp.PT_TONG - NVL(hp.PT_CONLAI, 0), c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng; ch?a th?c hi?n: '
                || CASE WHEN hp.PT_TONG IS NULL OR hp.PT_TONG = 0 THEN c_dots ELSE TO_CHAR(NVL(hp.PT_CONLAI, 0), c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng;' || CHR(10)

                || 'B?i th??ng thi?t h?i: '
                || CASE WHEN hp.BT_TONG IS NULL OR hp.BT_TONG = 0 THEN c_dots ELSE TO_CHAR(hp.BT_TONG, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng; ?ã th?c hi?n: '
                || CASE WHEN hp.BT_TONG IS NULL OR hp.BT_TONG = 0 THEN c_dots ELSE TO_CHAR(hp.BT_TONG - NVL(hp.BT_CONLAI, 0), c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng; ch?a th?c hi?n: '
                || CASE WHEN hp.BT_TONG IS NULL OR hp.BT_TONG = 0 THEN c_dots ELSE TO_CHAR(NVL(hp.BT_CONLAI, 0), c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng;' || CHR(10)

                || 'Ngh?a v? tr? l?i tài s?n: '
                || CASE WHEN hp.TLTS_TONG IS NULL OR hp.TLTS_TONG = 0 THEN c_dots ELSE TO_CHAR(hp.TLTS_TONG, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng; ?ã th?c hi?n: '
                || CASE WHEN hp.TLTS_TONG IS NULL OR hp.TLTS_TONG = 0 THEN c_dots ELSE TO_CHAR(hp.TLTS_TONG - NVL(hp.TLTS_CONLAI, 0), c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng; ch?a th?c hi?n: '
                || CASE WHEN hp.TLTS_TONG IS NULL OR hp.TLTS_TONG = 0 THEN c_dots ELSE TO_CHAR(NVL(hp.TLTS_CONLAI, 0), c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng;' || CHR(10)

                -- Ngh?a v? dân s? khác: ch? mã 237, KHÔNG g?p Truy thu (212) nh? hàm dùng chung
                || 'Ngh?a v? dân s? khác: '
                || CASE WHEN hp.NVK_TONG IS NULL OR hp.NVK_TONG = 0 THEN c_dots ELSE TO_CHAR(hp.NVK_TONG, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ;' || CHR(10)

                || 'Án phí hình s?: '
                || CASE WHEN hp.APHS_TONG IS NULL OR hp.APHS_TONG = 0 THEN c_dots ELSE TO_CHAR(hp.APHS_TONG, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng; ?ã th?c hi?n: '
                || CASE WHEN hp.APHS_TONG IS NULL OR hp.APHS_TONG = 0 THEN c_dots ELSE TO_CHAR(hp.APHS_TONG - NVL(hp.APHS_CONLAI, 0), c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng; ch?a th?c hi?n: '
                || CASE WHEN hp.APHS_TONG IS NULL OR hp.APHS_TONG = 0 THEN c_dots ELSE TO_CHAR(NVL(hp.APHS_CONLAI, 0), c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng;' || CHR(10)

                || 'Án phí dân s?: '
                || CASE WHEN hp.APDS_TONG IS NULL OR hp.APDS_TONG = 0 THEN c_dots ELSE TO_CHAR(hp.APDS_TONG, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng; ?ã th?c hi?n: '
                || CASE WHEN hp.APDS_TONG IS NULL OR hp.APDS_TONG = 0 THEN c_dots ELSE TO_CHAR(hp.APDS_TONG - NVL(hp.APDS_CONLAI, 0), c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng; ch?a th?c hi?n: '
                || CASE WHEN hp.APDS_TONG IS NULL OR hp.APDS_TONG = 0 THEN c_dots ELSE TO_CHAR(NVL(hp.APDS_CONLAI, 0), c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') END
                || ' ??ng;'
            )                                                  AS "HinhPhatBoSung",
            dpd.PD_TEN                                         AS "PhanDoi",
            dpt.PT_TEN                                         AS "PhanTrai",
            pll.LL_CCCD                                        AS "SoCCCD",
            TO_CHAR(pll.LL_NGAY_CAP_CCCD,  'DD/MM/YYYY')                              AS "NgayCapCCCD",
            pll.LL_NOI_CAP_CCCD                                AS "NoiCapCCCD",
            dtg.TG_TEN                                         AS "TraiGiam",
            CASE
                WHEN p_nam_id IS NOT NULL THEN
                    CASE p_quy_id
                        WHEN 1 THEN xl_q1.XLCT_TEN
                        WHEN 2 THEN xl_q2.XLCT_TEN
                        WHEN 3 THEN xl_q3.XLCT_TEN
                        WHEN 4 THEN xl_q4.XLCT_TEN
                        ELSE        xl_ca.XLCT_TEN
                    END
                ELSE xl_cuoi.XLCT_TEN
            END                                                AS "XepLoai",
            dttpn.TTPN_TEN                                     AS "TinhTrang",
            ntut.HO_TEN_THAN_NHAN                             AS "NguoiThan",
            ntut.NOI_O                                         AS "DiaChiNguoiThan",
            ntut.GIOI_TINH_NGUOI_THAN                         AS "GioiTinhNguoiThan",
            TO_CHAR(p_tu_ngay,  'DD/MM/YYYY')                 AS "TuNgay",
            TO_CHAR(p_den_ngay, 'DD/MM/YYYY')                 AS "DenNgay",
            NULL                                               AS "NhanXet",
            NULL                                               AS "ThongBao"

        FROM PN_LAI_LICHS pll
        LEFT JOIN DM_GIOI_TINHS dgt        ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
            ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
           AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
        LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
            ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
           AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
        -- FIX: dùng LATEST_THA thay join tr?c ti?p b?ng
        LEFT JOIN THA_LATEST ptha          ON ptha.THA_PNLAI_LICH_ID = pll.ID
        LEFT JOIN DM_PHAN_DOIS dpd         ON pll.LL_PHAN_DOI_ID = dpd.ID
        LEFT JOIN DM_PHAN_TRAIS dpt        ON pll.LL_PHAN_TRAI_ID = dpt.ID
        LEFT JOIN DM_TRAI_GIAMS dtg        ON pll.LL_TRAI_GIAM_ID = dtg.ID
        LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dttpn ON pll.LL_TINH_TRANG_ID = dttpn.ID
        LEFT JOIN TOI_DANH_AGG tda         ON tda.THA_PNLAI_LICH_ID = pll.ID
        LEFT JOIN NGUOI_THAN ntut          ON ntut.PHAM_NHAN_ID = pll.ID
        LEFT JOIN XEP_LOAIS xl
            ON xl.PHAM_NHAN_ID = pll.ID
           AND xl.XEP_LOAI_NAM = p_nam_id
           AND xl.IS_DELETED   = 0
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q1 ON xl.XEP_LOAI_QUY_I   = xl_q1.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q2 ON xl.XEP_LOAI_QUY_II  = xl_q2.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q3 ON xl.XEP_LOAI_QUY_III = xl_q3.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_q4 ON xl.XEP_LOAI_QUY_IV  = xl_q4.ID
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_ca ON xl.XEP_LOAI_CA_NAM  = xl_ca.ID
        LEFT JOIN XEP_LOAI_CUOI xlc        ON xlc.PHAM_NHAN_ID = pll.ID AND xlc.rn = 1
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS xl_cuoi ON xlc.XLCT_ID = xl_cuoi.ID
        LEFT JOIN HPBS_PIVOT hp             ON hp.PHAM_NHAN_ID = pll.ID

        WHERE (NOT EXISTS (SELECT 1 FROM QLPN.GTT_PN_IDS) OR pll.ID IN (SELECT PN_ID FROM ID_LIST))
        ORDER BY pll.ID;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_TINH_HINH_CHAPT_PHAM_NHAN_PT23;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TKTH_QLPN_PHAN_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TKTH_QLPN_PHAN_TRAI" (
    p_ngay_tu IN DATE,
    p_ngay_den IN DATE,
    p_trai_giam_id IN NUMBER
) AS
    v_tu_ngay  DATE;
    v_den_ngay DATE;
    p_result   SYS_REFCURSOR;
BEGIN
    -- ===== Normalize ngày =====
    -- Ngày t?
    IF EXTRACT(DAY FROM p_ngay_tu) < 15 THEN
        v_tu_ngay := TRUNC(ADD_MONTHS(p_ngay_tu, -1), 'MM') + 14; -- ngày 15 tháng tr??c
    ELSE
        v_tu_ngay := TRUNC(p_ngay_tu, 'MM') + 14; -- ngày 15 tháng hi?n t?i
    END IF;

    -- Ngày ??n
    IF EXTRACT(DAY FROM p_ngay_den) > 14 THEN
        v_den_ngay := TRUNC(ADD_MONTHS(p_ngay_den, 1), 'MM') + 13; -- ngày 14 tháng sau
    ELSE
        v_den_ngay := TRUNC(p_ngay_den, 'MM') + 13; -- ngày 14 tháng hi?n t?i
    END IF;

    -- Build and return result cursor (placeholder)
    OPEN p_result FOR
        SELECT PT.PT_TEN AS PHAN_DOI,
               COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'Nam' THEN pll.ID END) OVER () AS NAM,
               COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'N\1eef' THEN pll.ID END) OVER () AS NU,
               COUNT(DISTINCT CASE WHEN gt.GT_TEN NOT IN ( u'Nam', u'N\1eef') THEN pll.ID END) OVER () AS KHAC,
               COUNT(DISTINCT pll.ID) OVER () AS TONG_CONG
        FROM PN_LAI_LICHS pll
                 LEFT JOIN PN_THI_HANH_AN ptha
                           ON ptha.THA_PNLAI_LICH_ID = pll.ID
                               AND ptha.IS_DELETED = 0
                 LEFT JOIN DM_PHAN_TRAIS pt ON pll.LL_PHAN_TRAI_ID = pt.ID AND pt.IS_DELETED = 0
                LEFT JOIN DM_GIOI_TINHS gt on gt.ID = pll.LL_DM_GIOI_TINH_ID
        WHERE (ptha.THA_NGAY_HET_HAN >= v_tu_ngay OR v_tu_ngay IS NULL)
          AND (v_den_ngay IS NULL OR TRUNC(ptha.THA_NGAY_DEN_TRAI) < v_den_ngay)
          AND (p_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam_id)
        GROUP BY pt.PT_TEN;
    DBMS_SQL.RETURN_RESULT(p_result);
END SP_GET_TKTH_QLPN_PHAN_TRAI;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_CAC_DOT_DAC_XA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_CAC_DOT_DAC_XA" (
    p_ma_trai_giam    IN  NVARCHAR2 DEFAULT NULL,  -- DM_TRAI_GIAMS.TG_MA; NULL = t?t c? tr?i
    p_tu_ngay         IN  NVARCHAR2 DEFAULT NULL,
    p_den_ngay        IN  NVARCHAR2 DEFAULT NULL
) AS
    v_tu_date       DATE;
    v_den_date      DATE;
    v_trai_giam_id  NUMBER;
    c1              SYS_REFCURSOR;
BEGIN
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_date := DATE '1900-01-01';
    ELSE
        v_tu_date := TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY'));
    END IF;

    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_date := DATE '9999-12-31';
    ELSE
        v_den_date := TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY'));
    END IF;

    v_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                v_trai_giam_id := NULL;
        END;
    END IF;

    OPEN c1 FOR
    WITH
    dot_list AS (
        SELECT /*+ MATERIALIZE */
            dot.ID AS pn_dot_dac_xa_id,
            NVL(dot.DDX_TEN_DOT, u'\0110\1ee3t ' || TO_CHAR(dot.DDX_NAM_DAC_XA)) AS ten_dot,
            dot.DDX_NAM_DAC_XA,
            dot.DDX_NGAY_XET AS ngay_xet
        FROM QLPN.PN_DOT_DAC_XAS dot
        WHERE NVL(dot.IS_DELETED, 0) = 0
          AND dot.DDX_NGAY_XET >= v_tu_date
          AND dot.DDX_NGAY_XET < v_den_date + 1
    ),
    cnt AS (
        SELECT
            dl.pn_dot_dac_xa_id,
            SUM(CASE WHEN gt.GT_MA = '1' THEN 1 ELSE 0 END) AS so_nam,
            SUM(CASE WHEN gt.GT_MA = '2' THEN 1 ELSE 0 END) AS so_nu,
            SUM(CASE WHEN NVL(gt.GT_MA, ' ') NOT IN ('1', '2') THEN 1 ELSE 0 END) AS so_khac,
            COUNT(*) AS tong_so
        FROM dot_list dl
        INNER JOIN QLPN.PN_DAC_XAS pdx
                ON NVL(pdx.IS_DELETED, 0) = 0
               AND pdx.DX_NGAY_XET = dl.ngay_xet
        INNER JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt
                ON rt.PHAM_NHAN_ID = pdx.PNLAI_LICH_ID
               AND NVL(rt.IS_DELETED, 0) = 0
               AND NVL(rt.LL_IS_DELETED, 0) = 0
               AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
               ON gt.ID = rt.LL_DM_GIOI_TINH_ID
              AND NVL(gt.IS_DELETED, 0) = 0
        GROUP BY dl.pn_dot_dac_xa_id
    )
    SELECT
        dl.ten_dot AS cac_dot_dac_xa,
        NVL(c.so_nam, 0) AS nam,
        NVL(c.so_nu, 0) AS nu,
        NVL(c.so_khac, 0) AS khac,
        NVL(c.tong_so, 0) AS tong_so
    FROM dot_list dl
    LEFT JOIN cnt c ON c.pn_dot_dac_xa_id = dl.pn_dot_dac_xa_id
    ORDER BY dl.ngay_xet NULLS LAST, dl.DDX_NAM_DAC_XA, dl.ten_dot;

    DBMS_SQL.RETURN_RESULT(c1);

-- EXEC QLPN.SP_GET_TK_CAC_DOT_DAC_XA(NULL, NULL, NULL);
-- EXEC QLPN.SP_GET_TK_CAC_DOT_DAC_XA('94280', '01/01/2025', '01/01/2027');

END SP_GET_TK_CAC_DOT_DAC_XA;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_CAC_TRUONG_HOP_RA_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_CAC_TRUONG_HOP_RA_TRAI" (
    p_ma_trai_giam       IN  VARCHAR2  DEFAULT NULL,
    p_ngay_tha_tu_ngay   IN  DATE      DEFAULT NULL,
    p_ngay_tha_den_ngay  IN  DATE      DEFAULT NULL,
    p_phan_doi           IN  NUMBER    DEFAULT NULL,
    p_loai_ra_trai       IN  VARCHAR2  DEFAULT NULL
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    -- 1. B?ng ánh x? 12 tr??ng h?p báo cáo sang MÃ (TTPN_MA) trong DM_TINH_TRANG_PHAM_NHANS
    loai_mapping_raw AS (
        SELECT 1 AS TT, '121' AS tinh_trang_ma FROM DUAL UNION ALL -- Tha h?t án
        SELECT 2, '122' FROM DUAL UNION ALL                        -- Gi?m h?t th?i h?n
        SELECT 3, '123' FROM DUAL UNION ALL                        -- ???c ??c xá
        SELECT 4, '131' FROM DUAL UNION ALL SELECT 4, '132' FROM DUAL UNION ALL SELECT 4, '133' FROM DUAL UNION ALL -- Tr?n
        SELECT 5, '144' FROM DUAL UNION ALL SELECT 5, '145' FROM DUAL UNION ALL SELECT 5, '146' FROM DUAL UNION ALL -- Trích xu?t
        SELECT 5, '147' FROM DUAL UNION ALL SELECT 5, '148' FROM DUAL UNION ALL SELECT 5, '149' FROM DUAL UNION ALL SELECT 5, '150' FROM DUAL UNION ALL
        SELECT 6, '151' FROM DUAL UNION ALL SELECT 6, '152' FROM DUAL UNION ALL SELECT 6, '153' FROM DUAL UNION ALL -- T?m ?ình ch?
        SELECT 6, '154' FROM DUAL UNION ALL SELECT 6, '155' FROM DUAL UNION ALL SELECT 6, '156' FROM DUAL UNION ALL
        SELECT 6, '157' FROM DUAL UNION ALL SELECT 6, '158' FROM DUAL UNION ALL SELECT 6, '159' FROM DUAL UNION ALL
        SELECT 7, '161' FROM DUAL UNION ALL                        -- Chuy?n tr?i
        SELECT 8, '113' FROM DUAL UNION ALL                        -- Ch?a b?nh b?t bu?c
        SELECT 9, '181' FROM DUAL UNION ALL                        -- H?y án
        SELECT 10, '191' FROM DUAL UNION ALL                       -- Hoãn
        SELECT 11, '124' FROM DUAL UNION ALL                       -- Mi?n
        SELECT 12, '127' FROM DUAL                                  -- Chuy?n giao
    ),
    -- 2. Tên hi?n th? c? ??nh theo form báo cáo (??m b?o hi?n th? ?? khi không có d? li?u)
    report_headers AS (
        SELECT 1 AS TT, u'Tha h\1ebft \00e1n' AS TEN FROM DUAL UNION ALL
        SELECT 2, u'Gi\1ea3m h\1ebft th\1eddi h\1ea1n' FROM DUAL UNION ALL
        SELECT 3, u'\0110\01b0\1ee3c \0111\1eb7c x\00e1' FROM DUAL UNION ALL
        SELECT 4, u'Tr\1ed1n' FROM DUAL UNION ALL
        SELECT 5, u'Tr\00edch xu\1ea5t' FROM DUAL UNION ALL
        SELECT 6, u'T\1ea1m \0111\00ecnh ch\1ec9' FROM DUAL UNION ALL
        SELECT 7, u'Chuy\1ec3n tr\1ea1i' FROM DUAL UNION ALL
        SELECT 8, u'Ch\1eefa b\1ec7nh b\1eaft bu\1ed9c' FROM DUAL UNION ALL
        SELECT 9, u'H\1ee7y \00e1n' FROM DUAL UNION ALL
        SELECT 10, u'Ho\00e3n' FROM DUAL UNION ALL
        SELECT 11, u'Mi\1ec5n' FROM DUAL UNION ALL
        SELECT 12, u'Chuy\1ec3n giao' FROM DUAL
    ),
    -- 3. X? lý tham s? p_loai_ra_trai (csv '1,2,3' ho?c '[1,2,3]')
    p_loai_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(REPLACE(REPLACE(p_loai_ra_trai, '[', ''), ']', ''), '[^,]+', 1, LEVEL)) AS loai_tt
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(REPLACE(REPLACE(p_loai_ra_trai, '[', ''), ']', ''), ',') + 1
    ),
    -- 4. L?c danh sách lo?i c?n hi?n th?
    selected_headers AS (
        SELECT h.*
        FROM report_headers h
        WHERE p_loai_ra_trai IS NULL
           OR h.TT IN (SELECT TO_NUMBER(loai_tt) FROM p_loai_filter WHERE REGEXP_LIKE(loai_tt, '^[0-9]+$'))
    ),
    -- 5. L?y danh sách ph?m nhân t? View (không dùng b?ng Ra tr?i theo yêu c?u)
    kt_data AS (
        SELECT
            v.LL_TINH_TRANG_ID,
            CASE WHEN UPPER(NVL(TRIM(v.GIOI_TINH), '')) = u'NAM' OR v.GIOI_TINH_ID = 1 THEN 1 ELSE 0 END AS IS_NAM,
            CASE WHEN UPPER(NVL(TRIM(v.GIOI_TINH), '')) = u'N\1eee'  OR v.GIOI_TINH_ID = 2 THEN 1 ELSE 0 END AS IS_NU,
            CASE WHEN (UPPER(NVL(TRIM(v.GIOI_TINH), '')) NOT IN (u'NAM', u'N\1eee'))
                  AND (v.GIOI_TINH_ID NOT IN (1, 2))
                  AND v.GIOI_TINH_ID IS NOT NULL THEN 1 ELSE 0 END AS IS_KHAC
        FROM QLPN.VW_PN_LAI_LICH_CHI_TIET v
        WHERE NVL(v.IS_DELETED, 0) = 0
          AND (p_ma_trai_giam IS NULL OR v.TRAI_GIAM_MA = p_ma_trai_giam)
          AND (p_phan_doi IS NULL OR v.PHAN_DOI_ID = p_phan_doi)
          AND (p_ngay_tha_tu_ngay IS NULL OR TRUNC(v.NGAY_HET_AN) >= TRUNC(p_ngay_tha_tu_ngay))
          AND (p_ngay_tha_den_ngay IS NULL OR TRUNC(v.NGAY_HET_AN) <= TRUNC(p_ngay_tha_den_ngay))
    ),
    -- 6. Th?ng kê theo TT (join ID lý l?ch v?i DM ?? l?y mã TTPN_MA)
    aggregated_data AS (
        SELECT
            m.TT,
            SUM(kt.IS_NAM) AS NAM,
            SUM(kt.IS_NU) AS NU,
            SUM(kt.IS_KHAC) AS KHAC,
            COUNT(*) AS TONG_SO
        FROM kt_data kt
        INNER JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS dm ON dm.ID = kt.LL_TINH_TRANG_ID
        INNER JOIN loai_mapping_raw m ON m.tinh_trang_ma = dm.TTPN_MA
        WHERE NVL(dm.IS_DELETED, 0) = 0
        GROUP BY m.TT
    )
    -- 7. K?t qu? cu?i cùng: LEFT JOIN ?? gi? ?? các dòng tr??ng h?p
    SELECT
        h.TT,
        h.TEN AS TRUONG_HOP_RA_TRAI,
        NVL(a.NAM, 0) AS NAM,
        NVL(a.NU, 0) AS NU,
        NVL(a.KHAC, 0) AS KHAC,
        NVL(a.TONG_SO, 0) AS TONG_SO
    FROM selected_headers h
    LEFT JOIN aggregated_data a ON a.TT = h.TT
    ORDER BY h.TT;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, u'L\1ed7i SP_GET_TK_CAC_TRUONG_HOP_RA_TRAI: ' || SQLERRM);
END SP_GET_TK_CAC_TRUONG_HOP_RA_TRAI;





