--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_DAC_XA_QLPN" (
    p_dot_dac_xa_id IN  NUMBER DEFAULT NULL,
    p_ma_trai_giam IN  VARCHAR2 DEFAULT NULL,
    p_phan_doi_id IN  VARCHAR2 DEFAULT NULL
) AS
     v_trai_giam_id NVARCHAR2(2000);
    C1 SYS_REFCURSOR;  
BEGIN

    IF p_ma_trai_giam IS NULL OR p_ma_trai_giam = '' THEN
        v_trai_giam_id := NULL;
    ELSE
        v_trai_giam_id := p_ma_trai_giam;
    END IF;

    OPEN c1 FOR
    SELECT
        v.pn_dot_dac_xa_id,
        MAX(v.ddx_nam_dac_xa) AS ddx_nam_dac_xa,
        MAX(v.ddx_ten_dot) AS ddx_ten_dot,
         NULL AS ten_trai_giam,
        SUM(v.flg_nam) AS so_nam,
        SUM(v.flg_nu) AS so_nu,
        0 so_khac,
        SUM(v.flg_tong) AS tong,
        SUM(v.flg_toi_anqg) AS so_toi_anqg,
        SUM(v.flg_giet_nguoi) AS so_giet_nguoi,
        SUM(v.flg_hiep_dam) AS so_hiep_dam,
        SUM(v.flg_hiep_dam_tre_em) AS so_hiep_dam_tre_em,
        SUM(v.flg_mua_ban_nguoi) AS so_mua_ban_nguoi,
        SUM(v.flg_gay_thuong_tich) AS so_gay_thuong_tich,
        SUM(v.flg_toi_khac_tm_sk_dd_np) AS so_toi_khac_tm_sk_dd_np,
        SUM(v.flg_cuop_tai_san) AS so_cuop_tai_san,
        SUM(v.flg_cuop_giat) AS so_cuop_giat,
        SUM(v.flg_trom_cap) AS so_trom_cap,
        SUM(v.flg_bat_coc) AS so_bat_coc,
        SUM(v.flg_lua_dao) AS so_lua_dao,
        SUM(v.flg_toi_khac_so_huu) AS so_toi_khac_so_huu,
        SUM(v.flg_mua_ban_ma_tuy) AS so_mua_ban_ma_tuy,
        SUM(v.flg_san_xuat_ma_tuy) AS so_san_xuat_ma_tuy,
        SUM(v.flg_to_chuc_sd_ma_tuy) AS so_to_chuc_sd_ma_tuy,
        SUM(v.flg_chiem_doat_ma_tuy) AS so_chiem_doat_ma_tuy,
        SUM(v.flg_ma_tuy_khac) AS so_ma_tuy_khac,
        SUM(v.flg_toi_qlkt) AS so_toi_qlkt,
        SUM(v.flg_nhung_chuc_vu) AS so_nhung_chuc_vu,
        SUM(v.flg_toi_khac) AS so_toi_khac,
        SUM(v.flg_chung_than) AS so_chung_than,
        SUM(v.flg_tren_15_30_nam) AS so_tren_15_30_nam,
        SUM(v.flg_tren_7_15_nam) AS so_tren_7_15_nam,
        SUM(v.flg_tren_3_7_nam) AS so_tren_3_7_nam,
        SUM(v.flg_tu_3_nam_tro_xuong) AS so_tu_3_nam_tro_xuong,
        SUM(v.flg_khong_tien_an) AS so_khong_tien_an,
        SUM(v.flg_co_tien_an) AS so_co_tien_an,
        SUM(v.flg_duoi_18_tuoi) AS so_duoi_18_tuoi,
        SUM(v.flg_tu_18_duoi_30) AS so_tu_18_duoi_30,
        SUM(v.flg_tu_30_duoi_70) AS so_tu_30_duoi_70,
        SUM(v.flg_tu_70_tro_len) AS so_tu_70_tro_len,
        SUM(v.flg_huan_chuong_khang_chien) AS so_huan_chuong,
        SUM(v.flg_thuong_binh) AS so_thuong_binh,
        SUM(v.flg_lap_cong) AS so_lap_cong,
        SUM(v.flg_tu_70_uu_tien) AS so_tu_70_uu_tien,
        SUM(v.flg_duoi_18_pham_toi) AS so_duoi_18_pham_toi,
        SUM(v.flg_duoi_18_chap_hanh) AS so_duoi_18_chap_hanh,
        SUM(v.flg_gia_dinh_liet_sy) AS so_gia_dinh_liet_sy,
        SUM(v.flg_om_dau) AS so_om_dau,
        SUM(v.flg_benh_hiem_ngheo) AS so_benh_hiem_ngheo,
        SUM(v.flg_con_me_vnah) AS so_con_me_vnah,
        SUM(v.flg_gia_dinh_cong) AS so_gia_dinh_cong,
        SUM(v.flg_hoan_canh_kho_khan) AS so_hoan_canh_kho_khan,
        SUM(v.flg_tinh_tiet_khac) AS so_tinh_tiet_khac,
        SUM(v.flg_quoc_tich_ngoai) AS so_quoc_tich_ngoai,
        SUM(v.flg_ton_giao) AS so_ton_giao,
        SUM(v.flg_dan_toc_it_nguoi) AS so_dan_toc_it_nguoi
    FROM VW_BAO_CAO_DX_CHI_TIET v
    WHERE (p_dot_dac_xa_id IS NULL  OR  v.pn_dot_dac_xa_id = p_dot_dac_xa_id)
      AND (p_ma_trai_giam IS NULL  OR v.trai_giam_id = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
      AND (p_phan_doi_id IS NULL  OR v.phan_doi_id = p_phan_doi_id)
    GROUP BY v.pn_dot_dac_xa_id;


    DBMS_SQL.RETURN_RESULT(C1);

--      BEGIN   SP_GET_TK_DAC_XA_QLPN (108, NULL, NULL); END;
END;





/
