--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_DAC_XA_THEO_DIA_PHUONG_VE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_DAC_XA_THEO_DIA_PHUONG_VE" (
    p_dot_dac_xa_id   IN  NUMBER,
    p_ma_trai_giam    IN  NUMBER DEFAULT NULL,
    p_phan_doi_id     IN  NUMBER DEFAULT NULL
) AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    WITH
    pn_dac_xa_dot AS (
        SELECT pdx.PNLAI_LICH_ID AS pn_lai_lich_id
        FROM PN_DAC_XAS pdx
        INNER JOIN PN_DOT_DAC_XAS dot ON dot.id = p_dot_dac_xa_id
          AND NVL(dot.IS_DELETED,0)=0
          AND TRUNC(dot.DDX_NGAY_XET) = TRUNC(pdx.DX_NGAY_XET)
        WHERE NVL(pdx.IS_DELETED,0)=0
    ),
    src AS (
        SELECT
            p.pn_lai_lich_id,
            ll.ll_noi_tha_ve_cu_tru_provice AS dia_phuong_id,
            NVL(dvh.TTP_TEN, 'Ch?a xÃ¡c ??nh') AS dia_phuong_ten,
            CASE
                WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) = '1'
                THEN 1
                ELSE 0
            END AS is_nam,
            CASE
                WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) = '2'
                THEN 1
                ELSE 0
            END AS is_nu,
            CASE
                WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) NOT IN ('1', '2')
                THEN 1
                ELSE 0
            END AS is_khac
        FROM pn_dac_xa_dot p
        INNER JOIN PN_LAI_LICHS ll ON ll.id = p.pn_lai_lich_id AND ll.is_deleted = 0
        LEFT JOIN dm_tinh_thanh_pho dvh ON dvh.id = ll.ll_noi_tha_ve_cu_tru_provice AND dvh.is_deleted = 0
        LEFT JOIN DM_GIOI_TINHS gt ON gt.ID = ll.ll_dm_gioi_tinh_id AND NVL(gt.IS_DELETED, 0) = 0
        WHERE (p_ma_trai_giam IS NULL  OR ll.ll_trai_giam_id = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
          AND (p_phan_doi_id IS NULL OR ll.ll_phan_doi_id = p_phan_doi_id)
    ),
    agg AS (
        SELECT
            NVL(s.dia_phuong_ten, 'Ch?a xÃ¡c ??nh') AS dia_phuong,
            SUM(s.is_nam) AS so_nam,
            SUM(s.is_nu)  AS so_nu,
            SUM(s.is_khac) AS so_khac,
            SUM(1)        AS tong_so
        FROM src s
        GROUP BY NVL(s.dia_phuong_ten, 'Ch?a xÃ¡c ??nh')
    ),
    with_rows AS (
        SELECT
            a.dia_phuong AS dia_phuong,
            a.so_nam AS nam,
            a.so_nu AS nu,
            a.so_khac AS so_khac,
            a.tong_so AS tong_so
        FROM agg a
    )
    SELECT dia_phuong, nam, nu, so_khac, tong_so
    FROM with_rows
    ORDER BY dia_phuong;

    DBMS_SQL.RETURN_RESULT(C1);

-- EXEC SP_GET_TK_DAC_XA_THEO_DIA_PHUONG_VE(1, NULL, NULL);
-- EXEC SP_GET_TK_DAC_XA_THEO_DIA_PHUONG_VE(1, 5, NULL);
-- EXEC SP_GET_TK_DAC_XA_THEO_DIA_PHUONG_VE(1, 5, 10);

END SP_GET_TK_DAC_XA_THEO_DIA_PHUONG_VE;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_DAC_XA_THEO_HPBS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_DAC_XA_THEO_HPBS" (
    p_dot_dac_xa_id   IN  NUMBER,
    p_ma_trai_giam    IN  NUMBER DEFAULT NULL,
    p_phan_doi_id     IN  NUMBER DEFAULT NULL
) AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    WITH HPBS AS (
        SELECT
            phpbs.ID,
            phpbs.HPBS_MA_PHAM_NHAN,
            phpbs.HPBS_HINH_PHAT,
            NVL(phpbs.HPBS_TONG_TIEN_PHAT, 0) AS TONG_TIEN_PHAT,
            NVL(phpbs.HPBS_TONG_TIEN_CON_LAI, 0) AS TONG_TIEN_CON_LAI,
            NVL(dm.HPBS_TEN, u'Ch\01b0a x\00e1c \0111\1ecbnh') AS HPBS_TEN
        FROM PN_HINH_PHAT_BO_SUNGS phpbs
        LEFT JOIN DM_HINH_PHAT_BO_SUNGS dm ON dm.ID = phpbs.HPBS_HINH_PHAT AND NVL(dm.IS_DELETED, 0) = 0
        WHERE phpbs.IS_DELETED = 0
    ),
    BIEN_LAI_RAW AS (
        SELECT
            pb.HPBS_ID,
            SUM(CASE
                    WHEN pb.BL_NGAY_NOP < ptha.THA_NGAY_BAN_AN
                    THEN NVL(pb.BL_SO_TIEN, 0)
                    ELSE 0
                END) AS THUC_HIEN_TRUOC_KHI_XU,
            SUM(CASE
                    WHEN ptha.THA_NGAY_BAN_AN <= pb.BL_NGAY_NOP
                     AND pb.BL_NGAY_NOP < ptha.THA_NGAY_DEN_TRAI
                    THEN NVL(pb.BL_SO_TIEN, 0)
                    ELSE 0
                END) AS THUC_HIEN_SAU_KHI_XU,
            SUM(CASE
                    WHEN (pb.BL_NGAY_NOP IS NULL
                          OR pb.BL_NGAY_NOP >= ptha.THA_NGAY_DEN_TRAI)
                     AND (pb.BL_NGAY_NOP IS NULL
                          OR ptha.THA_NGAY_BAN_AN IS NULL
                          OR ptha.THA_NGAY_BAN_AN <= pb.BL_NGAY_NOP)
                    THEN NVL(pb.BL_SO_TIEN, 0)
                    ELSE 0
                END) AS THUC_HIEN_KHI_CHAPT,
            SUM(CASE
                    WHEN pb.BL_NOP_TAI_CO_QUAN IS NOT NULL
                     AND (pb.BL_NGAY_NOP IS NULL OR pb.BL_NGAY_NOP >= ptha.THA_NGAY_DEN_TRAI)
                     AND (pb.BL_NGAY_NOP IS NULL
                          OR ptha.THA_NGAY_BAN_AN IS NULL
                          OR ptha.THA_NGAY_BAN_AN <= pb.BL_NGAY_NOP)
                    THEN NVL(pb.BL_SO_TIEN, 0)
                    ELSE 0
                END) AS NOP_TAI_TRAI
        FROM PN_BIENLAIES pb
        JOIN PN_HINH_PHAT_BO_SUNGS phpbs ON phpbs.ID = pb.HPBS_ID
        JOIN (
            SELECT THA_PNLAI_LICH_ID, THA_NGAY_DEN_TRAI, THA_NGAY_BAN_AN
            FROM QLPN.PN_THI_HANH_AN
            WHERE NVL(IS_DELETED, 0) = 0
        ) ptha ON ptha.THA_PNLAI_LICH_ID = phpbs.HPBS_MA_PHAM_NHAN
        where pb.IS_DELETED = 0
        GROUP BY pb.HPBS_ID
    ),
    BIEN_LAI AS (
        SELECT
            HPBS_ID,
            THUC_HIEN_TRUOC_KHI_XU,
            THUC_HIEN_SAU_KHI_XU,
            THUC_HIEN_KHI_CHAPT,
            (THUC_HIEN_TRUOC_KHI_XU + THUC_HIEN_SAU_KHI_XU + THUC_HIEN_KHI_CHAPT) AS TONG_THUC_HIEN,
            NOP_TAI_TRAI
        FROM BIEN_LAI_RAW
    )
    SELECT
        h.HPBS_TEN AS HINH_PHAT_BO_SUNG,
        COUNT(DISTINCT pn_dx.pn_lai_lich_id) AS SO_PN,
        SUM(h.TONG_TIEN_PHAT) AS TONG_TIEN_PHAT,
        SUM(NVL(b.THUC_HIEN_TRUOC_KHI_XU, 0)) AS THUC_HIEN_TRUOC_KHI_XU,
        SUM(NVL(b.THUC_HIEN_SAU_KHI_XU, 0))   AS THUC_HIEN_SAU_KHI_XU,
        SUM(NVL(b.THUC_HIEN_KHI_CHAPT, 0))    AS THUC_HIEN_KHI_CHAPT,
        SUM(NVL(b.TONG_THUC_HIEN, 0))         AS TONG_THUC_HIEN,
        SUM(NVL(b.NOP_TAI_TRAI, 0))           AS NOP_TAI_TRAI,
        SUM(h.TONG_TIEN_CON_LAI)              AS CHUA_THUC_HIEN
    FROM (
        SELECT pdx.PNLAI_LICH_ID AS pn_lai_lich_id
        FROM PN_DAC_XAS pdx
        INNER JOIN PN_DOT_DAC_XAS dot ON dot.id = p_dot_dac_xa_id
          AND NVL(dot.IS_DELETED,0)=0
          AND TRUNC(dot.DDX_NGAY_XET) = TRUNC(pdx.DX_NGAY_XET)
        WHERE NVL(pdx.IS_DELETED,0)=0
    ) pn_dx
    JOIN VW_PN_LAI_LICH_CHI_TIET vpllct ON vpllct.PHAM_NHAN_ID = pn_dx.pn_lai_lich_id
    JOIN HPBS h ON h.HPBS_MA_PHAM_NHAN = pn_dx.pn_lai_lich_id
    LEFT JOIN BIEN_LAI b ON b.HPBS_ID = h.ID
    WHERE (p_ma_trai_giam IS NULL OR vpllct.TRAI_GIAM_MA = p_ma_trai_giam)
      AND (p_phan_doi_id IS NULL OR vpllct.PHAN_DOI_ID = p_phan_doi_id)
    GROUP BY h.HPBS_TEN
    ORDER BY h.HPBS_TEN;

    DBMS_SQL.RETURN_RESULT(C1);

-- EXEC SP_GET_TK_DAC_XA_THEO_HPBS(1, NULL, NULL);
