/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_DAC_XA_THEO_MUC_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_DAC_XA_THEO_MUC_AN" (
    p_dot_dac_xa_id   IN  NUMBER,
    p_ma_trai_giam    IN  NUMBER DEFAULT NULL,
    p_phan_doi_id     IN  NUMBER DEFAULT NULL
) AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    WITH
    pn_dac_xa_dot AS (
        SELECT pdx.PNLAI_LICH_ID AS pn_lai_lich_id
        FROM PN_DAC_XAS pdx
        INNER JOIN PN_DOT_DAC_XAS dot ON dot.id = p_dot_dac_xa_id
          AND NVL(dot.IS_DELETED,0)=0
          AND TRUNC(dot.DDX_NGAY_XET) = TRUNC(pdx.DX_NGAY_XET)
        WHERE NVL(pdx.IS_DELETED,0)=0
    ),
    muc_an_pn AS (
        SELECT
            p.pn_lai_lich_id AS PN_LAI_LICH_ID,
            vpllct.PHAN_TRAI,
            vpllct.GIOI_TINH,
            vpllct.AN_PHAT,
            UPPER(NVL("FN_NORMALIZE_VN"(vpllct.AN_PHAT), '')) AS an_phat_norm,
            ( NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(vpllct.AN_PHAT AS NVARCHAR2(2000)), 'NAM'), 0) * 12
            + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(vpllct.AN_PHAT AS NVARCHAR2(2000)), 'THANG'), 0)
            + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(vpllct.AN_PHAT AS NVARCHAR2(2000)), 'NGAY'), 0) / 30.0
            ) AS thang_tong,
            CASE
                -- Chung thÃ¢n gi?m cÃ³ th?i h?n: AN_PHAT cÃ³ "chung thÃ¢n" nh?ng cÃ³ s? n?m/thÃ¡ng/ngÃ y -> th?ng kÃª theo th?i h?n.
                WHEN (
                    NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(vpllct.AN_PHAT AS NVARCHAR2(2000)), 'NAM'), 0) * 12
                  + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(vpllct.AN_PHAT AS NVARCHAR2(2000)), 'THANG'), 0)
                  + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(vpllct.AN_PHAT AS NVARCHAR2(2000)), 'NGAY'), 0) / 30.0
                ) > 0
                THEN (
                    ( NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(vpllct.AN_PHAT AS NVARCHAR2(2000)), 'NAM'), 0) * 12
                    + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(vpllct.AN_PHAT AS NVARCHAR2(2000)), 'THANG'), 0)
                    + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(vpllct.AN_PHAT AS NVARCHAR2(2000)), 'NGAY'), 0) / 30.0
                    ) / 12.0
                )
                ELSE FN_AN_PHAT_TO_NAM(vpllct.AN_PHAT)
            END AS SO_NAM,
            CASE
                -- Chung thÃ¢n (g?m c? "t? hÃ¬nh gi?m xu?ng chung thÃ¢n"): cÃ³ text CHUNGTHAN vÃ  khÃ´ng cÃ³ th?i h?n kÃ¨m theo.
                WHEN INSTR(UPPER(NVL("FN_NORMALIZE_VN"(vpllct.AN_PHAT), '')), 'CHUNGTHAN') > 0
                 AND (
                    NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(vpllct.AN_PHAT AS NVARCHAR2(2000)), 'NAM'), 0) * 12
                  + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(vpllct.AN_PHAT AS NVARCHAR2(2000)), 'THANG'), 0)
                  + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(vpllct.AN_PHAT AS NVARCHAR2(2000)), 'NGAY'), 0) / 30.0
                 ) = 0
                THEN 1
                ELSE 0
            END AS is_chung_than,
            vpllct.GHI_CHU
        FROM pn_dac_xa_dot p
        JOIN VW_PN_LAI_LICH_CHI_TIET vpllct
            ON vpllct.PHAM_NHAN_ID = p.pn_lai_lich_id
           AND NVL(vpllct.IS_DELETED, 0) = 0
        WHERE (p_ma_trai_giam IS NULL OR vpllct.TRAI_GIAM_MA = p_ma_trai_giam)
          AND (p_phan_doi_id IS NULL OR vpllct.PHAN_DOI_ID = p_phan_doi_id)
    )
    SELECT
        PHAN_TRAI,
        SUM(CASE WHEN GIOI_TINH = 'Nam' THEN 1 ELSE 0 END) AS NAM,
        SUM(CASE WHEN GIOI_TINH = u'N\1eef' THEN 1 ELSE 0 END) AS NU,
        COUNT(*) AS TONG_SO,
        SUM(CASE WHEN is_chung_than = 1 THEN 1 ELSE 0 END) AS CHUNG_THAN,
        SUM(CASE WHEN SO_NAM IS NOT NULL AND SO_NAM <= 1 THEN 1 ELSE 0 END)      AS TU_1_NAM_TRO_XUONG,
        SUM(CASE WHEN SO_NAM > 1  AND SO_NAM <= 3  THEN 1 ELSE 0 END)            AS TREN_1N_DEN_3N,
        SUM(CASE WHEN SO_NAM > 3  AND SO_NAM <= 5  THEN 1 ELSE 0 END)            AS TREN_3N_DEN_5N,
        SUM(CASE WHEN SO_NAM > 5  AND SO_NAM <= 7  THEN 1 ELSE 0 END)            AS TREN_5N_DEN_7N,
        SUM(CASE WHEN SO_NAM > 7  AND SO_NAM <= 10 THEN 1 ELSE 0 END)            AS TREN_7N_DEN_10N,
        SUM(CASE WHEN SO_NAM > 10 AND SO_NAM <= 15 THEN 1 ELSE 0 END)            AS TREN_10N_DEN_15N,
        SUM(CASE WHEN SO_NAM > 15 AND SO_NAM < 20  THEN 1 ELSE 0 END)            AS TREN_15N_DEN_20N,
        SUM(CASE WHEN SO_NAM = 20 THEN 1 ELSE 0 END)                              AS AN_20N,
        SUM(CASE WHEN SO_NAM > 20 AND SO_NAM <= 30 THEN 1 ELSE 0 END)            AS TREN_20N_DEN_30N,
        SUM(CASE WHEN is_chung_than = 0 AND SO_NAM IS NOT NULL THEN 1 ELSE 0 END) AS CONG_AN_CO_THOI_HAN,
        CAST(NULL AS NVARCHAR2(2000)) AS GHI_CHU
    FROM muc_an_pn
    GROUP BY PHAN_TRAI
    ORDER BY PHAN_TRAI;

    DBMS_SQL.RETURN_RESULT(C1);

-- EXEC SP_GET_TK_DAC_XA_THEO_MUC_AN(108, NULL, NULL);
-- EXEC SP_GET_TK_DAC_XA_THEO_MUC_AN(108, 5, NULL);
-- EXEC SP_GET_TK_DAC_XA_THEO_MUC_AN(108, 5, 10);

END SP_GET_TK_DAC_XA_THEO_MUC_AN;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_DAC_XA_THEO_PHAN_DOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_DAC_XA_THEO_PHAN_DOI" (
    p_dot_dac_xa_id   IN  NUMBER,
    p_ma_trai_giam    IN  NUMBER DEFAULT NULL,
    p_phan_doi_id     IN  NUMBER DEFAULT NULL
) AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    WITH
    pn_dac_xa_dot AS (
        SELECT pdx.PNLAI_LICH_ID AS pn_lai_lich_id
        FROM PN_DAC_XAS pdx
        INNER JOIN PN_DOT_DAC_XAS dot ON dot.id = p_dot_dac_xa_id
          AND NVL(dot.IS_DELETED,0)=0
          AND TRUNC(dot.DDX_NGAY_XET) = TRUNC(pdx.DX_NGAY_XET)
        WHERE NVL(pdx.IS_DELETED,0)=0
    ),
    src AS (
        SELECT
            p.pn_lai_lich_id,
            ll.ll_phan_trai_id,
            ll.ll_phan_doi_id,
            CASE WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) = '1' THEN 1 ELSE 0 END AS is_nam,
            CASE WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) = '2' THEN 1 ELSE 0 END AS is_nu,
            CASE WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) NOT IN ('1', '2') THEN 1 ELSE 0 END AS is_khac
        FROM pn_dac_xa_dot p
        INNER JOIN PN_LAI_LICHS ll ON ll.id = p.pn_lai_lich_id AND ll.is_deleted = 0
        LEFT JOIN DM_GIOI_TINHS gt ON gt.ID = ll.ll_dm_gioi_tinh_id AND NVL(gt.IS_DELETED, 0) = 0
        WHERE (p_ma_trai_giam IS NULL  OR ll.ll_trai_giam_id = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
          AND (p_phan_doi_id IS NULL OR ll.ll_phan_doi_id = p_phan_doi_id)
    ),
    detail AS (
        SELECT
            NVL(pt.PT_TEN, 'Ch?a xÃ¡c ??nh') AS phan_trai_ten,
            NVL(pd.PD_TEN, 'Ch?a xÃ¡c ??nh') AS phan_doi_ten,
            SUM(s.is_nam) AS nam,
            SUM(s.is_nu)  AS nu,
            SUM(s.is_khac) AS so_khac,
            SUM(1)       AS tong_so
        FROM src s
        LEFT JOIN DM_PHAN_TRAIS pt ON pt.id = s.ll_phan_trai_id AND NVL(pt.is_deleted,0)=0
        LEFT JOIN DM_PHAN_DOIS pd ON pd.id = s.ll_phan_doi_id AND NVL(pd.is_deleted,0)=0
        GROUP BY NVL(pt.PT_TEN, 'Ch?a xÃ¡c ??nh'), NVL(pd.PD_TEN, 'Ch?a xÃ¡c ??nh')
    ),
    summary_trai AS (
        SELECT
            phan_trai_ten,
            SUM(nam) AS nam,
            SUM(nu)  AS nu,
            SUM(so_khac) AS so_khac,
            SUM(tong_so) AS tong_so
        FROM detail
        GROUP BY phan_trai_ten
    ),
    summary_all AS (
        SELECT
            SUM(nam) AS nam,
            SUM(nu)  AS nu,
            SUM(so_khac) AS so_khac,
            SUM(tong_so) AS tong_so
        FROM detail
    ),
    trai_rank AS (
        SELECT phan_trai_ten,
               ROW_NUMBER() OVER (ORDER BY phan_trai_ten) AS TRAI_SO
        FROM summary_trai
    ),
    doi_rank AS (
        SELECT phan_trai_ten, phan_doi_ten,
               ROW_NUMBER() OVER (PARTITION BY phan_trai_ten ORDER BY phan_doi_ten) AS DOI_SO
        FROM detail
    )
    SELECT STT, PHAN_DOI, NAM, NU, so_khac, TONG_SO
    FROM (
        -- Header camp
        SELECT 
            tr.TRAI_SO AS SORT_KEY1, 1 AS SORT_TYPE, 0 AS SORT_KEY2,
            TO_CHAR(tr.TRAI_SO, 'FMRN') AS STT,
            st.phan_trai_ten AS PHAN_DOI,
            st.nam AS NAM, st.nu AS NU, st.so_khac AS so_khac, st.tong_so AS TONG_SO
        FROM summary_trai st
        JOIN trai_rank tr ON st.phan_trai_ten = tr.phan_trai_ten

        UNION ALL

        -- Detail teams
        SELECT 
            tr.TRAI_SO AS SORT_KEY1, 2 AS SORT_TYPE, dr.DOI_SO AS SORT_KEY2,
            TO_CHAR(dr.DOI_SO) AS STT,
            d.phan_doi_ten || ', ' || d.phan_trai_ten AS PHAN_DOI,
            d.nam AS NAM, d.nu AS NU, d.so_khac AS so_khac, d.tong_so AS TONG_SO
        FROM detail d
        JOIN trai_rank tr ON d.phan_trai_ten = tr.phan_trai_ten
        JOIN doi_rank dr ON d.phan_trai_ten = dr.phan_trai_ten AND d.phan_doi_ten = dr.phan_doi_ten

        UNION ALL

        -- Grand total
        SELECT 
            999999 AS SORT_KEY1, 3 AS SORT_TYPE, 999999 AS SORT_KEY2,
            TO_CHAR((SELECT COUNT(*) + 1 FROM detail)) AS STT,
            CAST('T?NG S?' AS NVARCHAR2(100)) AS PHAN_DOI,
            sa.nam AS NAM, sa.nu AS NU, sa.so_khac AS so_khac, sa.tong_so AS TONG_SO
        FROM summary_all sa
    )
    ORDER BY SORT_KEY1, SORT_TYPE, SORT_KEY2;

    DBMS_SQL.RETURN_RESULT(C1);
END ;





