        FROM agg a
    )
    SELECT quoc_tich, nam, nu, so_khac, tong_so
    FROM with_rows
    ORDER BY quoc_tich;

    DBMS_SQL.RETURN_RESULT(C1);

-- EXEC SP_GET_TK_DAC_XA_THEO_QUOC_TICH(1, NULL, NULL);
-- EXEC SP_GET_TK_DAC_XA_THEO_QUOC_TICH(1, 5, NULL);
