END SP_GET_TK_DAC_XA_THEO_QUOC_TICH;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_DAC_XA_THEO_TINH_TIET_UU_TIEN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_DAC_XA_THEO_TINH_TIET_UU_TIEN" (
    p_dot_dac_xa_id   IN  NUMBER,
    p_ma_trai_giam    IN  NUMBER DEFAULT NULL,
    p_phan_doi_id     IN  NUMBER DEFAULT NULL
) AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    WITH
    pn_dac_xa_dot AS (
        SELECT pdx.PNLAI_LICH_ID AS pn_lai_lich_id
        FROM PN_DAC_XAS pdx
        INNER JOIN PN_DOT_DAC_XAS dot ON dot.id = p_dot_dac_xa_id
          AND NVL(dot.IS_DELETED,0)=0
          AND TRUNC(dot.DDX_NGAY_XET) = TRUNC(pdx.DX_NGAY_XET)
        WHERE NVL(pdx.IS_DELETED,0)=0
    ),
    gcr_raw AS (
        SELECT
            ll.id AS pn_lai_lich_id,
            ll.ll_ghi_chu_rieng,
            REGEXP_REPLACE(NVL(TRIM(ll.ll_ghi_chu_rieng), ''), '[[:space:]\[\]]', '') AS gcr_clean,
            ROW_NUMBER() OVER (ORDER BY ll.id) AS row_id
        FROM pn_dac_xa_dot p
        INNER JOIN PN_LAI_LICHS ll ON ll.id = p.pn_lai_lich_id AND ll.is_deleted = 0
        WHERE (p_ma_trai_giam IS NULL  OR ll.ll_trai_giam_id = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
          AND (p_phan_doi_id IS NULL OR ll.ll_phan_doi_id = p_phan_doi_id)
    ),
    gcr_ids AS (
        SELECT
            r.pn_lai_lich_id,
            TO_NUMBER(REGEXP_SUBSTR(r.gcr_clean, '[0-9]+', 1, LEVEL)) AS gcr_id,
            LEVEL AS ord_col
        FROM gcr_raw r
        WHERE r.gcr_clean IS NOT NULL
          AND REGEXP_COUNT(r.gcr_clean, '[0-9]+') > 0
        CONNECT BY
            PRIOR r.pn_lai_lich_id = r.pn_lai_lich_id
            AND PRIOR r.row_id = r.row_id
            AND PRIOR SYS_GUID() IS NOT NULL
            AND LEVEL <= REGEXP_COUNT(r.gcr_clean, '[0-9]+')

        UNION ALL
        SELECT
            r.pn_lai_lich_id,
            CAST(NULL AS NUMBER) AS gcr_id,
            1 AS ord_col
        FROM gcr_raw r
        WHERE r.gcr_clean IS NULL
           OR REGEXP_COUNT(r.gcr_clean, '[0-9]+') = 0
    ),
    gcr_map AS (
        SELECT
            i.pn_lai_lich_id,
            i.gcr_id,
            TO_CHAR(g.GCR_TEN) AS tinh_tiet_ten
        FROM (
            SELECT DISTINCT pn_lai_lich_id, gcr_id
            FROM gcr_ids
        ) i
        LEFT JOIN DM_GHI_CHU_RIENGS g
            ON g.ID = i.gcr_id
           AND NVL(g.IS_DELETED, 0) = 0
    ),
    gcr_rows AS (
        SELECT
            m.pn_lai_lich_id,
            CASE
                WHEN m.gcr_id IS NULL THEN 'Ch?a xÃ¡c ??nh'
                WHEN m.tinh_tiet_ten IS NULL THEN 'Ch?a xÃ¡c ??nh'
                ELSE m.tinh_tiet_ten
            END AS tinh_tiet
        FROM gcr_map m
    ),
    src AS (
        SELECT
            p.pn_lai_lich_id,
            t.tinh_tiet AS tinh_tiet_uu_tien,
            CASE WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) = '1' THEN 1 ELSE 0 END AS is_nam,
            CASE WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) = '2' THEN 1 ELSE 0 END AS is_nu,
            CASE WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) NOT IN ('1', '2') THEN 1 ELSE 0 END AS is_khac
        FROM pn_dac_xa_dot p
        INNER JOIN PN_LAI_LICHS ll ON ll.id = p.pn_lai_lich_id AND ll.is_deleted = 0
        LEFT JOIN gcr_rows t ON t.pn_lai_lich_id = ll.id
        LEFT JOIN DM_GIOI_TINHS gt ON gt.ID = ll.ll_dm_gioi_tinh_id AND NVL(gt.IS_DELETED, 0) = 0
        WHERE (p_ma_trai_giam IS NULL  OR ll.ll_trai_giam_id = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
          AND (p_phan_doi_id IS NULL OR ll.ll_phan_doi_id = p_phan_doi_id)
    ),
    agg AS (
        SELECT
            NVL(s.tinh_tiet_uu_tien, 'Ch?a xÃ¡c ??nh') AS tinh_tiet_uu_tien,
            SUM(s.is_nam) AS so_nam,
            SUM(s.is_nu)  AS so_nu,
            SUM(s.is_khac) AS so_khac,
            SUM(1)        AS tong_so
        FROM src s
        GROUP BY NVL(s.tinh_tiet_uu_tien, 'Ch?a xÃ¡c ??nh')
    ),
    with_rows AS (
        SELECT a.tinh_tiet_uu_tien, a.so_nam AS nam, a.so_nu AS nu, a.so_khac AS so_khac, a.tong_so AS tong_so
        FROM agg a
    )
    SELECT tinh_tiet_uu_tien, nam, nu, so_khac, tong_so
    FROM with_rows
    ORDER BY tinh_tiet_uu_tien;

    DBMS_SQL.RETURN_RESULT(C1);

-- EXEC SP_GET_TK_DAC_XA_THEO_TINH_TIET_UU_TIEN(1, NULL, NULL);
-- EXEC SP_GET_TK_DAC_XA_THEO_TINH_TIET_UU_TIEN(1, 5, NULL);
-- EXEC SP_GET_TK_DAC_XA_THEO_TINH_TIET_UU_TIEN(1, 5, 10);

END SP_GET_TK_DAC_XA_THEO_TINH_TIET_UU_TIEN;





