--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_DAC_XA_THEO_TOI_DANH" (
    p_dot_dac_xa_id   IN  NUMBER,
    p_ma_trai_giam    IN  NUMBER DEFAULT NULL,
    p_phan_doi_id     IN  NUMBER DEFAULT NULL
) AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    WITH
    tha_one AS (
        SELECT tha_pnlai_lich_id,
               tha_toi_danh,
               ROW_NUMBER() OVER (PARTITION BY tha_pnlai_lich_id ORDER BY tha_ngay_den_trai DESC NULLS LAST) AS rn
        FROM PN_THI_HANH_AN
        WHERE is_deleted = 0
    ),
    toi_raw AS (
        SELECT
            t.tha_pnlai_lich_id AS pn_lai_lich_id,
            t.tha_toi_danh,
            REGEXP_REPLACE(NVL(TO_CHAR(t.tha_toi_danh), ''), '[[:space:]\[\]]', '') AS toi_danh_clean,
            ROW_NUMBER() OVER (ORDER BY t.tha_pnlai_lich_id) AS row_id
        FROM tha_one t
        WHERE t.rn = 1
    ),
    toi_ids AS (
        SELECT
            r.pn_lai_lich_id,
            TO_NUMBER(REGEXP_SUBSTR(r.toi_danh_clean, '[0-9]+', 1, LEVEL)) AS toi_danh_id,
            LEVEL AS ord_col
        FROM toi_raw r
        WHERE r.toi_danh_clean IS NOT NULL
          AND REGEXP_COUNT(r.toi_danh_clean, '[0-9]+') > 0
        CONNECT BY
            PRIOR r.pn_lai_lich_id = r.pn_lai_lich_id
            AND PRIOR r.row_id = r.row_id
            AND PRIOR SYS_GUID() IS NOT NULL
            AND LEVEL <= REGEXP_COUNT(r.toi_danh_clean, '[0-9]+')

        UNION ALL
        SELECT
            r.pn_lai_lich_id,
            CAST(NULL AS NUMBER) AS toi_danh_id,
            1 AS ord_col
        FROM toi_raw r
        WHERE r.toi_danh_clean IS NULL
           OR REGEXP_COUNT(r.toi_danh_clean, '[0-9]+') = 0
    ),
    toi_map AS (
        SELECT
            i.pn_lai_lich_id,
            i.toi_danh_id,
            TO_CHAR(d.TD_TEN) AS toi_danh_ten
        FROM toi_ids i
        LEFT JOIN DM_TOI_DANHS d
            ON d.ID = i.toi_danh_id
           AND NVL(d.IS_DELETED, 0) = 0
    ),
    toi_rows AS (
        SELECT DISTINCT
            m.pn_lai_lich_id,
            m.toi_danh_id,
            CASE
                WHEN m.toi_danh_id IS NULL THEN 'Ch?a xÃ¡c ??nh'
                WHEN m.toi_danh_ten IS NULL THEN 'Ch?a xÃ¡c ??nh'
                ELSE m.toi_danh_ten
            END AS toi_danh
        FROM toi_map m
    ),
    pn_dac_xa_dot AS (
        SELECT pdx.PNLAI_LICH_ID AS pn_lai_lich_id
        FROM PN_DAC_XAS pdx
        INNER JOIN PN_DOT_DAC_XAS dot ON dot.id = p_dot_dac_xa_id
          AND NVL(dot.IS_DELETED,0)=0
          AND TRUNC(dot.DDX_NGAY_XET) = TRUNC(pdx.DX_NGAY_XET)
        WHERE NVL(pdx.IS_DELETED,0)=0
    ),
    src AS (
        SELECT
            p.pn_lai_lich_id,
            t.toi_danh AS toi_danh_ten,
            CASE WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) = '1' THEN 1 ELSE 0 END AS is_nam,
            CASE WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) = '2' THEN 1 ELSE 0 END AS is_nu,
            CASE WHEN TRIM(CAST(NVL(gt.GT_MA, '') AS VARCHAR2(50))) NOT IN ('1', '2') THEN 1 ELSE 0 END AS is_khac
        FROM pn_dac_xa_dot p
        INNER JOIN PN_LAI_LICHS ll ON ll.id = p.pn_lai_lich_id AND ll.is_deleted = 0
        LEFT JOIN toi_rows t ON t.pn_lai_lich_id = ll.id
        LEFT JOIN DM_GIOI_TINHS gt ON gt.ID = ll.ll_dm_gioi_tinh_id AND NVL(gt.IS_DELETED, 0) = 0
        WHERE (p_ma_trai_giam IS NULL  OR ll.ll_trai_giam_id = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
          AND (p_phan_doi_id IS NULL OR ll.ll_phan_doi_id = p_phan_doi_id)
    ),
    agg AS (
        SELECT
            NVL(s.toi_danh_ten, 'Ch?a xÃ¡c ??nh') AS toi_danh,
            SUM(s.is_nam) AS so_nam,
            SUM(s.is_nu)  AS so_nu,
            SUM(s.is_khac) AS so_khac,
            SUM(1)        AS tong_so
        FROM src s
        GROUP BY NVL(s.toi_danh_ten, 'Ch?a xÃ¡c ??nh')
    ),
    with_rows AS (
        SELECT a.toi_danh AS toi_danh, a.so_nam AS nam, a.so_nu AS nu, a.so_khac AS so_khac, a.tong_so AS tong_so
        FROM agg a
    )
    SELECT toi_danh, nam, nu, so_khac, tong_so
    FROM with_rows
    ORDER BY toi_danh;

    DBMS_SQL.RETURN_RESULT(C1);


-- EXEC SP_GET_TK_DAC_XA_THEO_TOI_DANH(155, 5, NULL);
-- EXEC SP_GET_TK_DAC_XA_THEO_TOI_DANH(155, NULL, NULL);
-- EXEC SP_GET_TK_DAC_XA_THEO_TOI_DANH(155, 5, 10);


END SP_GET_TK_DAC_XA_THEO_TOI_DANH;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_DAC_XA_THEO_TON_GIAO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_DAC_XA_THEO_TON_GIAO" (
    p_dot_dac_xa_id   IN  NUMBER,
    p_ma_trai_giam    IN  NUMBER DEFAULT NULL,
