/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_GIAM_THOI_HAN_PHAN_DOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_GIAM_THOI_HAN_PHAN_DOI" (
    p_dot_giam_id  IN DATE,
    p_phan_doi_id  IN NUMBER DEFAULT NULL,
    p_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ma_trai_giam in varchar2 default null
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    GTH_BASE AS (
        SELECT
            pll.ID                  AS PHAM_NHAN_ID,
            pll.LL_PHAN_DOI_ID,
            pll.LL_PHAN_TRAI_ID,
            dgt.GT_TEN              AS GIOI_TINH,
            MAX(CASE WHEN NVL(gth_dn.IS_DELETED,0)=0
                      AND gth_dn.MUC_DE_NGHI_ID IS NOT NULL
                      AND TRUNC(CAST(gth_dn.NGAY_XET AS DATE))=TRUNC(p_dot_giam_id)
                     THEN gth_dn.PHAM_NHAN_ID END)  AS DN_ID,
            MAX(CASE WHEN NVL(gth_bca.IS_DELETED,0)=0
                      AND gth_bca.CAP_TREN_DUYET_ID IS NOT NULL
                      AND TRUNC(CAST(gth_bca.NGAY_XET AS DATE))=TRUNC(p_dot_giam_id)
                     THEN gth_bca.PHAM_NHAN_ID END) AS BCA_ID,
            MAX(CASE WHEN NVL(gth_tqd.IS_DELETED,0)=0
                      AND gth_tqd.MUC_GIAM_ID IS NOT NULL
                      AND TRUNC(CAST(gth_tqd.NGAY_XET AS DATE))=TRUNC(p_dot_giam_id)
                     THEN gth_tqd.PHAM_NHAN_ID END) AS TQD_ID
        FROM PN_LAI_LICHS pll
        LEFT JOIN DM_GIOI_TINHS dgt
            ON dgt.ID = pll.LL_DM_GIOI_TINH_ID
        LEFT JOIN GIAM_THOI_HANS gth_dn  ON gth_dn.PHAM_NHAN_ID  = pll.ID
        LEFT JOIN GIAM_THOI_HANS gth_bca ON gth_bca.PHAM_NHAN_ID = pll.ID
        LEFT JOIN GIAM_THOI_HANS gth_tqd ON gth_tqd.PHAM_NHAN_ID = pll.ID
        LEFT JOIN (
            SELECT ptha.THA_PNLAI_LICH_ID,
                   CASE WHEN COUNT(CASE WHEN td.TD_CHUONG = '13' THEN 1 END) > 0
                        THEN 1 ELSE 2
                   END AS DOI_TUONG_ID
              FROM PN_THI_HANH_AN ptha
              JOIN (
                  SELECT ptha2.THA_PNLAI_LICH_ID,
                         TO_NUMBER(TRIM(REGEXP_SUBSTR(
                             REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''),
                             '[^,]+', 1, n.N
                         ))) AS TOI_DANH_ID
                    FROM PN_THI_HANH_AN ptha2
                    JOIN (SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL <= 20) n
                      ON n.N <= REGEXP_COUNT(
                             REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''), ','
                         ) + 1
                   WHERE ptha2.THA_TOI_DANH IS NOT NULL
                     AND NVL(ptha2.IS_DELETED, 0) = 0
              ) td_split ON td_split.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
              JOIN DM_TOI_DANHS td ON td.ID = td_split.TOI_DANH_ID
             WHERE NVL(ptha.IS_DELETED, 0) = 0
             GROUP BY ptha.THA_PNLAI_LICH_ID
        ) doi_tuong ON doi_tuong.THA_PNLAI_LICH_ID = pll.ID
        WHERE pll.IS_DELETED = 0
        AND( p_ma_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
          AND (p_phan_doi_id  IS NULL OR pll.LL_PHAN_DOI_ID  = p_phan_doi_id)
          AND (p_doi_tuong_id IS NULL OR doi_tuong.DOI_TUONG_ID = p_doi_tuong_id)
        GROUP BY pll.ID, pll.LL_PHAN_DOI_ID, pll.LL_PHAN_TRAI_ID, dgt.GT_TEN
        HAVING
            MAX(CASE WHEN NVL(gth_dn.IS_DELETED,0)=0
                      AND gth_dn.MUC_DE_NGHI_ID IS NOT NULL
                      AND TRUNC(CAST(gth_dn.NGAY_XET AS DATE))=TRUNC(p_dot_giam_id)
                     THEN 1 END) = 1
            OR MAX(CASE WHEN NVL(gth_bca.IS_DELETED,0)=0
                         AND gth_bca.CAP_TREN_DUYET_ID IS NOT NULL
                         AND TRUNC(CAST(gth_bca.NGAY_XET AS DATE))=TRUNC(p_dot_giam_id)
                        THEN 1 END) = 1
            OR MAX(CASE WHEN NVL(gth_tqd.IS_DELETED,0)=0
                         AND gth_tqd.MUC_GIAM_ID IS NOT NULL
                         AND TRUNC(CAST(gth_tqd.NGAY_XET AS DATE))=TRUNC(p_dot_giam_id)
                        THEN 1 END) = 1
    ),
PHAN_TRAI_RANKED AS (
    -- "Ch?a phân tr?i" luôn = 1
    SELECT PHAN_TRAI_ID, PHAN_TRAI_TEN, PT_MA, 1 AS PT_RN
    FROM (
        SELECT DISTINCT
            gb.LL_PHAN_TRAI_ID                             AS PHAN_TRAI_ID,
            NVL(dpt.PT_TEN, u'Ch\01b0a ph\00e2n tr\1ea1i') AS PHAN_TRAI_TEN,
            NVL(dpt.PT_MA, '99999')                        AS PT_MA
        FROM GTH_BASE gb
        LEFT JOIN DM_PHAN_TRAIS dpt ON dpt.ID = gb.LL_PHAN_TRAI_ID
        WHERE NVL(dpt.PT_MA, '99999') = '99999'
    )

    UNION ALL

    -- Phân tr?i th?t: ROW_NUMBER ch? ?ánh trên t?p này, +1 ?? b?t ??u t? 2
    SELECT PHAN_TRAI_ID, PHAN_TRAI_TEN, PT_MA,
           ROW_NUMBER() OVER (ORDER BY PHAN_TRAI_TEN) + 1 AS PT_RN
    FROM (
        SELECT DISTINCT
            gb.LL_PHAN_TRAI_ID                             AS PHAN_TRAI_ID,
            NVL(dpt.PT_TEN, u'Ch\01b0a ph\00e2n tr\1ea1i') AS PHAN_TRAI_TEN,
            NVL(dpt.PT_MA, '99999')                        AS PT_MA
        FROM GTH_BASE gb
        LEFT JOIN DM_PHAN_TRAIS dpt ON dpt.ID = gb.LL_PHAN_TRAI_ID
        WHERE NVL(dpt.PT_MA, '99999') <> '99999'   -- ch? phân tr?i th?t
    )
),
PHAN_DOI_RANKED AS (
    SELECT
        LL_PHAN_TRAI_ID,
        PHAN_DOI_ID,
        PHAN_DOI_TEN,
        ROW_NUMBER() OVER (
            PARTITION BY LL_PHAN_TRAI_ID
            ORDER BY PHAN_DOI_TEN
        ) AS PD_RN
    FROM (
        SELECT DISTINCT
            gb.LL_PHAN_TRAI_ID,
            gb.LL_PHAN_DOI_ID                                        AS PHAN_DOI_ID,
            NVL(dpd.PD_TEN, u'Ch\01b0a ph\00e2n \0111\1ed9i')        AS PHAN_DOI_TEN
        FROM GTH_BASE gb
        LEFT JOIN DM_PHAN_DOIS  dpd ON dpd.ID = gb.LL_PHAN_DOI_ID
        LEFT JOIN DM_PHAN_TRAIS dpt ON dpt.ID = gb.LL_PHAN_TRAI_ID
        WHERE NVL(dpt.PT_MA, '') <> '99999'
    )
)
SELECT "TT", "DonVi",
       "TraiDeNghiNam", "TraiDeNghiNu", "TraiDeNghiKhac", "TraiDeNghiTong",
       "BoCongAnNam",   "BoCongAnNu",   "BoCongAnKhac",   "BoCongAnTong",
       "ToaQuyetDinhNam","ToaQuyetDinhNu","ToaQuyetDinhKhac","ToaQuyetDinhTong"
FROM (
    -- ?? Dòng I: LUÔN LUÔN là "Ch?a phân tr?i" ??????????????????????
    SELECT
        0                                                              AS SORT_ORDER,
        TO_NCHAR('I')                                                  AS "TT",
        TO_NCHAR(u'Ch\01b0a ph\00e2n tr\1ea1i')                       AS "DonVi",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = 'Nam'                            THEN gb.DN_ID  END) AS "TraiDeNghiNam",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = u'N\1eef'                        THEN gb.DN_ID  END) AS "TraiDeNghiNu",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR gb.GIOI_TINH IS NULL THEN gb.DN_ID  END) AS "TraiDeNghiKhac",
        COUNT(DISTINCT gb.DN_ID)                                                 AS "TraiDeNghiTong",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = 'Nam'                            THEN gb.BCA_ID END) AS "BoCongAnNam",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = u'N\1eef'                        THEN gb.BCA_ID END) AS "BoCongAnNu",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR gb.GIOI_TINH IS NULL THEN gb.BCA_ID END) AS "BoCongAnKhac",
        COUNT(DISTINCT gb.BCA_ID)                                                AS "BoCongAnTong",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = 'Nam'                            THEN gb.TQD_ID END) AS "ToaQuyetDinhNam",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = u'N\1eef'                        THEN gb.TQD_ID END) AS "ToaQuyetDinhNu",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR gb.GIOI_TINH IS NULL THEN gb.TQD_ID END) AS "ToaQuyetDinhKhac",
        COUNT(DISTINCT gb.TQD_ID)                                                AS "ToaQuyetDinhTong"
    FROM GTH_BASE gb
    JOIN PHAN_TRAI_RANKED ptr ON ptr.PHAN_TRAI_ID = gb.LL_PHAN_TRAI_ID
    WHERE ptr.PT_MA = '99999'   -- ch? l?y "Ch?a phân tr?i"

    UNION ALL

    -- ?? Dòng PHÂN TR?I th?t (b?t ??u t? II) ????????????????????????
    SELECT
        ptr.PT_RN * 1.0                                                AS SORT_ORDER,
        TO_NCHAR(QLPN.FN_TO_ROMAN(ptr.PT_RN))                         AS "TT",
        TO_NCHAR(ptr.PHAN_TRAI_TEN)                                    AS "DonVi",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = 'Nam'                            THEN gb.DN_ID  END) AS "TraiDeNghiNam",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = u'N\1eef'                        THEN gb.DN_ID  END) AS "TraiDeNghiNu",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR gb.GIOI_TINH IS NULL THEN gb.DN_ID  END) AS "TraiDeNghiKhac",
        COUNT(DISTINCT gb.DN_ID)                                                 AS "TraiDeNghiTong",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = 'Nam'                            THEN gb.BCA_ID END) AS "BoCongAnNam",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = u'N\1eef'                        THEN gb.BCA_ID END) AS "BoCongAnNu",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR gb.GIOI_TINH IS NULL THEN gb.BCA_ID END) AS "BoCongAnKhac",
        COUNT(DISTINCT gb.BCA_ID)                                                AS "BoCongAnTong",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = 'Nam'                            THEN gb.TQD_ID END) AS "ToaQuyetDinhNam",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = u'N\1eef'                        THEN gb.TQD_ID END) AS "ToaQuyetDinhNu",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR gb.GIOI_TINH IS NULL THEN gb.TQD_ID END) AS "ToaQuyetDinhKhac",
        COUNT(DISTINCT gb.TQD_ID)                                                AS "ToaQuyetDinhTong"
    FROM GTH_BASE gb
    JOIN PHAN_TRAI_RANKED ptr ON ptr.PHAN_TRAI_ID = gb.LL_PHAN_TRAI_ID
    WHERE ptr.PT_MA <> '99999'  -- b? "Ch?a phân tr?i"
    GROUP BY ptr.PT_RN, ptr.PHAN_TRAI_TEN

    UNION ALL

    -- ?? Dòng PHÂN ??I ???????????????????????????????????????????????
    SELECT
        ptr.PT_RN * 1.0 + pdr.PD_RN * 0.01                            AS SORT_ORDER,
        TO_NCHAR(TO_CHAR(pdr.PD_RN))                                   AS "TT",
        TO_NCHAR(pdr.PHAN_DOI_TEN)                                     AS "DonVi",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = 'Nam'                            THEN gb.DN_ID  END) AS "TraiDeNghiNam",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = u'N\1eef'                        THEN gb.DN_ID  END) AS "TraiDeNghiNu",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR gb.GIOI_TINH IS NULL THEN gb.DN_ID  END) AS "TraiDeNghiKhac",
        COUNT(DISTINCT gb.DN_ID)                                                 AS "TraiDeNghiTong",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = 'Nam'                            THEN gb.BCA_ID END) AS "BoCongAnNam",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = u'N\1eef'                        THEN gb.BCA_ID END) AS "BoCongAnNu",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR gb.GIOI_TINH IS NULL THEN gb.BCA_ID END) AS "BoCongAnKhac",
        COUNT(DISTINCT gb.BCA_ID)                                                AS "BoCongAnTong",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = 'Nam'                            THEN gb.TQD_ID END) AS "ToaQuyetDinhNam",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = u'N\1eef'                        THEN gb.TQD_ID END) AS "ToaQuyetDinhNu",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR gb.GIOI_TINH IS NULL THEN gb.TQD_ID END) AS "ToaQuyetDinhKhac",
        COUNT(DISTINCT gb.TQD_ID)                                                AS "ToaQuyetDinhTong"
    FROM GTH_BASE gb
    JOIN PHAN_TRAI_RANKED ptr ON ptr.PHAN_TRAI_ID = gb.LL_PHAN_TRAI_ID
    JOIN PHAN_DOI_RANKED  pdr ON pdr.PHAN_DOI_ID  = gb.LL_PHAN_DOI_ID
                             AND pdr.LL_PHAN_TRAI_ID = gb.LL_PHAN_TRAI_ID
    WHERE ptr.PT_MA <> '99999'  -- phân ??i ch? thu?c phân tr?i th?t
    GROUP BY ptr.PT_RN, pdr.PD_RN, pdr.PHAN_DOI_TEN

    UNION ALL

    -- ?? Dòng T?NG S? ????????????????????????????????????????????????
    SELECT
        999                                                             AS SORT_ORDER,
        TO_NCHAR('')                                                    AS "TT",
        TO_NCHAR(u'T\1ed4NG S\1ed0')                                   AS "DonVi",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = 'Nam'                            THEN gb.DN_ID  END) AS "TraiDeNghiNam",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = u'N\1eef'                        THEN gb.DN_ID  END) AS "TraiDeNghiNu",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR gb.GIOI_TINH IS NULL THEN gb.DN_ID  END) AS "TraiDeNghiKhac",
        COUNT(DISTINCT gb.DN_ID)                                                 AS "TraiDeNghiTong",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = 'Nam'                            THEN gb.BCA_ID END) AS "BoCongAnNam",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = u'N\1eef'                        THEN gb.BCA_ID END) AS "BoCongAnNu",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR gb.GIOI_TINH IS NULL THEN gb.BCA_ID END) AS "BoCongAnKhac",
        COUNT(DISTINCT gb.BCA_ID)                                                AS "BoCongAnTong",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = 'Nam'                            THEN gb.TQD_ID END) AS "ToaQuyetDinhNam",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH = u'N\1eef'                        THEN gb.TQD_ID END) AS "ToaQuyetDinhNu",
        COUNT(DISTINCT CASE WHEN gb.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR gb.GIOI_TINH IS NULL THEN gb.TQD_ID END) AS "ToaQuyetDinhKhac",
        COUNT(DISTINCT gb.TQD_ID)                                                AS "ToaQuyetDinhTong"
    FROM GTH_BASE gb
)
ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            u'L?i SP_GET_TK_GIAM_THOI_HAN_PHAN_DOI: ' || SQLERRM);
END SP_GET_TK_GIAM_THOI_HAN_PHAN_DOI;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_GIAM_THOI_HAN_THEO_GHI_CHU_RIENG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_GIAM_THOI_HAN_THEO_GHI_CHU_RIENG" (
    p_dot_giam_id  IN DATE,
    p_phan_doi_id  IN NUMBER DEFAULT NULL,
    p_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ma_trai_giam IN VARCHAR2 DEFAULT null
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    pn_gcr AS (
        SELECT DISTINCT
            pll2.ID                                          AS PHAM_NHAN_ID,
            TO_NUMBER(TRIM(REGEXP_SUBSTR(
                pll2.LL_GHI_CHU_RIENG,
                '[^,]+', 1, LEVEL
            )))                                              AS GCR_ID
        FROM PN_LAI_LICHS pll2
        WHERE pll2.LL_GHI_CHU_RIENG IS NOT NULL
          AND TRIM(pll2.LL_GHI_CHU_RIENG) IS NOT NULL
          AND (p_phan_doi_id IS NULL OR pll2.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND pll2.IS_DELETED = 0
        CONNECT BY LEVEL <= REGEXP_COUNT(pll2.LL_GHI_CHU_RIENG, ',') + 1
            AND PRIOR pll2.ID = pll2.ID
            AND PRIOR SYS_GUID() IS NOT NULL
    ),
    pn_gcr_ten AS (
        SELECT
            pg.PHAM_NHAN_ID,
            gcr.ID   AS GCR_ID,
            gcr.GCR_TEN
        FROM pn_gcr pg
        JOIN DM_GHI_CHU_RIENGS gcr ON gcr.ID = pg.GCR_ID
        WHERE pg.GCR_ID IS NOT NULL
    ),
    pn_trong_dot AS (
        SELECT
            pll.ID                  AS PHAM_NHAN_ID,
            dgt.GT_TEN              AS GIOI_TINH,
            MAX(CASE WHEN NVL(gth_dn.IS_DELETED,0)  = 0
                      AND gth_dn.MUC_DE_NGHI_ID IS NOT NULL
                      AND TRUNC(CAST(gth_dn.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
                     THEN gth_dn.PHAM_NHAN_ID END)  AS DN_ID,
            MAX(CASE WHEN NVL(gth_bca.IS_DELETED,0) = 0
                      AND gth_bca.CAP_TREN_DUYET_ID IS NOT NULL
                      AND TRUNC(CAST(gth_bca.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
                     THEN gth_bca.PHAM_NHAN_ID END) AS BCA_ID,
            MAX(CASE WHEN NVL(gth_tqd.IS_DELETED,0) = 0
                      AND gth_tqd.MUC_GIAM_ID IS NOT NULL
                      AND TRUNC(CAST(gth_tqd.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
                     THEN gth_tqd.PHAM_NHAN_ID END) AS TQD_ID
        FROM PN_LAI_LICHS pll
        LEFT JOIN DM_GIOI_TINHS dgt
            ON dgt.ID = pll.LL_DM_GIOI_TINH_ID
        LEFT JOIN GIAM_THOI_HANS gth_dn
            ON gth_dn.PHAM_NHAN_ID = pll.ID
        LEFT JOIN GIAM_THOI_HANS gth_bca
            ON gth_bca.PHAM_NHAN_ID = pll.ID
        LEFT JOIN GIAM_THOI_HANS gth_tqd
            ON gth_tqd.PHAM_NHAN_ID = pll.ID
        LEFT JOIN (
            SELECT ptha.THA_PNLAI_LICH_ID,
                   CASE WHEN COUNT(CASE WHEN td.TD_CHUONG = '13' THEN 1 END) > 0
                        THEN 1 ELSE 2
                   END AS DOI_TUONG_ID
              FROM PN_THI_HANH_AN ptha
              JOIN (
                  SELECT ptha2.THA_PNLAI_LICH_ID,
                         TO_NUMBER(TRIM(REGEXP_SUBSTR(
                             REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''),
                             '[^,]+', 1, n.N
                         ))) AS TOI_DANH_ID
                    FROM PN_THI_HANH_AN ptha2
                    JOIN (SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL <= 20) n
                      ON n.N <= REGEXP_COUNT(
                             REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''), ','
                         ) + 1
                   WHERE ptha2.THA_TOI_DANH IS NOT NULL
                     AND NVL(ptha2.IS_DELETED, 0) = 0
              ) td_split ON td_split.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
              JOIN DM_TOI_DANHS td ON td.ID = td_split.TOI_DANH_ID
             WHERE NVL(ptha.IS_DELETED, 0) = 0
             GROUP BY ptha.THA_PNLAI_LICH_ID
        ) doi_tuong ON doi_tuong.THA_PNLAI_LICH_ID = pll.ID
        WHERE (p_phan_doi_id  IS NULL OR pll.LL_PHAN_DOI_ID  = p_phan_doi_id)
           AND( p_ma_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
          AND (p_doi_tuong_id IS NULL OR doi_tuong.DOI_TUONG_ID = p_doi_tuong_id)
          AND pll.IS_DELETED = 0
        GROUP BY pll.ID, dgt.GT_TEN
        HAVING
            MAX(CASE WHEN NVL(gth_dn.IS_DELETED,0)  = 0
                      AND gth_dn.MUC_DE_NGHI_ID IS NOT NULL
                      AND TRUNC(CAST(gth_dn.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
                     THEN 1 END) = 1
            OR MAX(CASE WHEN NVL(gth_bca.IS_DELETED,0) = 0
                         AND gth_bca.CAP_TREN_DUYET_ID IS NOT NULL
                         AND TRUNC(CAST(gth_bca.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
                        THEN 1 END) = 1
            OR MAX(CASE WHEN NVL(gth_tqd.IS_DELETED,0) = 0
                         AND gth_tqd.MUC_GIAM_ID IS NOT NULL
                         AND TRUNC(CAST(gth_tqd.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
                        THEN 1 END) = 1
    ),
    -- ?? CTE t?ng h?p theo t?ng ghi chú (tr??c khi ?ánh s? TT) ??????
    GCR_AGG AS (
        SELECT
            gt.GCR_ID,
            gt.GCR_TEN,
            COUNT(DISTINCT CASE WHEN pd.GIOI_TINH = 'Nam'                                           THEN pd.DN_ID  END) AS "TraiDeNghiNam",
            COUNT(DISTINCT CASE WHEN pd.GIOI_TINH = u'N\1eef'                                       THEN pd.DN_ID  END) AS "TraiDeNghiNu",
            COUNT(DISTINCT CASE WHEN pd.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR pd.GIOI_TINH IS NULL THEN pd.DN_ID  END) AS "TraiDeNghiKhac",
            COUNT(DISTINCT pd.DN_ID)                                                                 AS "TraiDeNghiTong",
            COUNT(DISTINCT CASE WHEN pd.GIOI_TINH = 'Nam'                                           THEN pd.BCA_ID END) AS "BoCongAnNam",
            COUNT(DISTINCT CASE WHEN pd.GIOI_TINH = u'N\1eef'                                       THEN pd.BCA_ID END) AS "BoCongAnNu",
            COUNT(DISTINCT CASE WHEN pd.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR pd.GIOI_TINH IS NULL THEN pd.BCA_ID END) AS "BoCongAnKhac",
            COUNT(DISTINCT pd.BCA_ID)                                                                AS "BoCongAnTong",
            COUNT(DISTINCT CASE WHEN pd.GIOI_TINH = 'Nam'                                           THEN pd.TQD_ID END) AS "ToaQuyetDinhNam",
            COUNT(DISTINCT CASE WHEN pd.GIOI_TINH = u'N\1eef'                                       THEN pd.TQD_ID END) AS "ToaQuyetDinhNu",
            COUNT(DISTINCT CASE WHEN pd.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR pd.GIOI_TINH IS NULL THEN pd.TQD_ID END) AS "ToaQuyetDinhKhac",
            COUNT(DISTINCT pd.TQD_ID)                                                                AS "ToaQuyetDinhTong"
        FROM pn_gcr_ten gt
        JOIN pn_trong_dot pd ON pd.PHAM_NHAN_ID = gt.PHAM_NHAN_ID
        GROUP BY gt.GCR_ID, gt.GCR_TEN
    )
    -- ?? Các dòng ghi chú: ?ánh TT b?ng ROW_NUMBER theo GCR_TEN ?????
    SELECT
        TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY GCR_TEN))) AS "TT",
        TO_NCHAR(GCR_TEN)       AS "GhiChuRieng",
        "TraiDeNghiNam",
        "TraiDeNghiNu",
        "TraiDeNghiKhac",
        "TraiDeNghiTong",
        "BoCongAnNam",
        "BoCongAnNu",
        "BoCongAnKhac",
        "BoCongAnTong",
        "ToaQuyetDinhNam",
        "ToaQuyetDinhNu",
        "ToaQuyetDinhKhac",
        "ToaQuyetDinhTong",
        0 AS SORT_ORDER
    FROM GCR_AGG

    UNION ALL

    -- ?? Dòng T?NG S?: TT ?? tr?ng ???????????????????????????????????
    SELECT
        TO_NCHAR('')                                                             AS "TT",
        TO_NCHAR(u'T\1ed4NG S\1ed0')                                            AS "GhiChuRieng",
        COUNT(DISTINCT CASE WHEN pd.GIOI_TINH = 'Nam'                                           THEN pd.DN_ID  END) AS "TraiDeNghiNam",
        COUNT(DISTINCT CASE WHEN pd.GIOI_TINH = u'N\1eef'                                       THEN pd.DN_ID  END) AS "TraiDeNghiNu",
        COUNT(DISTINCT CASE WHEN pd.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR pd.GIOI_TINH IS NULL THEN pd.DN_ID  END) AS "TraiDeNghiKhac",
        COUNT(DISTINCT pd.DN_ID)                                                                 AS "TraiDeNghiTong",
        COUNT(DISTINCT CASE WHEN pd.GIOI_TINH = 'Nam'                                           THEN pd.BCA_ID END) AS "BoCongAnNam",
        COUNT(DISTINCT CASE WHEN pd.GIOI_TINH = u'N\1eef'                                       THEN pd.BCA_ID END) AS "BoCongAnNu",
        COUNT(DISTINCT CASE WHEN pd.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR pd.GIOI_TINH IS NULL THEN pd.BCA_ID END) AS "BoCongAnKhac",
        COUNT(DISTINCT pd.BCA_ID)                                                                AS "BoCongAnTong",
        COUNT(DISTINCT CASE WHEN pd.GIOI_TINH = 'Nam'                                           THEN pd.TQD_ID END) AS "ToaQuyetDinhNam",
        COUNT(DISTINCT CASE WHEN pd.GIOI_TINH = u'N\1eef'                                       THEN pd.TQD_ID END) AS "ToaQuyetDinhNu",
        COUNT(DISTINCT CASE WHEN pd.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR pd.GIOI_TINH IS NULL THEN pd.TQD_ID END) AS "ToaQuyetDinhKhac",
        COUNT(DISTINCT pd.TQD_ID)                                                                AS "ToaQuyetDinhTong",
        1 AS SORT_ORDER
    FROM pn_trong_dot pd

    ORDER BY SORT_ORDER, "GhiChuRieng" NULLS LAST;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            u'L\1ed7i SP_GET_TK_GIAM_THOI_HAN_THEO_GHI_CHU_RIENG: ' || SQLERRM);
END SP_GET_TK_GIAM_THOI_HAN_THEO_GHI_CHU_RIENG;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_GIAM_THOI_HAN_THEO_HPBS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_GIAM_THOI_HAN_THEO_HPBS" (
    p_dot_giam_id  IN DATE,
    p_phan_doi_id  IN NUMBER DEFAULT NULL,
    p_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ma_trai_giam IN VARCHAR2 DEFAULT null
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH valid_pn AS (
        SELECT DISTINCT pll.ID AS PHAM_NHAN_ID
        FROM PN_LAI_LICHS pll
        LEFT JOIN GIAM_THOI_HANS gth
            ON gth.PHAM_NHAN_ID = pll.ID
           AND NVL(gth.IS_DELETED, 0) = 0
           AND pll.IS_DELETED = 0
           AND TRUNC(gth.NGAY_XET) = TRUNC(p_dot_giam_id)
        LEFT JOIN (
            SELECT ptha.THA_PNLAI_LICH_ID,
                   CASE WHEN COUNT(CASE WHEN td.TD_CHUONG = '13' THEN 1 END) > 0 THEN 1 ELSE 2 END AS DOI_TUONG_ID
            FROM PN_THI_HANH_AN ptha
            JOIN (
                SELECT ptha2.THA_PNLAI_LICH_ID,
                       TO_NUMBER(TRIM(REGEXP_SUBSTR(
                           REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''),
                           '[^,]+', 1, LEVEL))) AS TOI_DANH_ID
                FROM PN_THI_HANH_AN ptha2
                CONNECT BY LEVEL <= REGEXP_COUNT(REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''), ',') + 1
                AND PRIOR ptha2.THA_PNLAI_LICH_ID = ptha2.THA_PNLAI_LICH_ID
                AND PRIOR SYS_GUID() IS NOT NULL
            ) td_split ON td_split.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
            JOIN DM_TOI_DANHS td ON td.ID = td_split.TOI_DANH_ID
            WHERE NVL(ptha.IS_DELETED, 0) = 0
            GROUP BY ptha.THA_PNLAI_LICH_ID
        ) doi_tuong ON doi_tuong.THA_PNLAI_LICH_ID = pll.ID
        WHERE (p_phan_doi_id IS NULL OR pll.LL_PHAN_DOI_ID = p_phan_doi_id)
        AND( p_ma_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
          AND (p_doi_tuong_id IS NULL OR doi_tuong.DOI_TUONG_ID = p_doi_tuong_id)
          AND gth.ID IS NOT NULL
    ),
    BIEN_LAI_RAW AS (
        SELECT
            pb.HPBS_ID,
            SUM(NVL(pb.BL_SO_TIEN, 0)) AS TONG_THUC_HIEN,
            SUM(CASE WHEN pb.BL_NGAY_NOP < ptha.THA_NGAY_BAN_AN
                     THEN NVL(pb.BL_SO_TIEN, 0) ELSE 0 END) AS THUC_HIEN_TRUOC_KHI_XU,
            SUM(CASE WHEN ptha.THA_NGAY_BAN_AN <= pb.BL_NGAY_NOP
                      AND pb.BL_NGAY_NOP < ptha.THA_NGAY_DEN_TRAI
                     THEN NVL(pb.BL_SO_TIEN, 0) ELSE 0 END) AS THUC_HIEN_SAU_KHI_XU,
            SUM(CASE WHEN (pb.BL_NGAY_NOP IS NULL OR pb.BL_NGAY_NOP >= ptha.THA_NGAY_DEN_TRAI)
                     THEN NVL(pb.BL_SO_TIEN, 0) ELSE 0 END) AS THUC_HIEN_KHI_CHAPT,
            SUM(CASE WHEN pb.BL_NOP_TAI_CO_QUAN IS NOT NULL
                      AND (pb.BL_NGAY_NOP IS NULL OR pb.BL_NGAY_NOP >= ptha.THA_NGAY_DEN_TRAI)
                     THEN NVL(pb.BL_SO_TIEN, 0) ELSE 0 END) AS NOP_TAI_TRAI
        FROM PN_BIENLAIES pb
        JOIN PN_HINH_PHAT_BO_SUNGS phpbs ON phpbs.ID = pb.HPBS_ID AND NVL(phpbs.IS_DELETED, 0) = 0
        LEFT JOIN (
            SELECT * FROM (
                SELECT ptha.*,
                       ROW_NUMBER() OVER (PARTITION BY THA_PNLAI_LICH_ID ORDER BY THA_NGAY_BAN_AN DESC) rn
                FROM PN_THI_HANH_AN ptha
                WHERE NVL(ptha.IS_DELETED, 0) = 0
            ) WHERE rn = 1
        ) ptha ON ptha.THA_PNLAI_LICH_ID = phpbs.HPBS_MA_PHAM_NHAN
        WHERE NVL(pb.IS_DELETED, 0) = 0
        GROUP BY pb.HPBS_ID
    ),
    HPBS_AGG AS (
        SELECT
            dhpbs.HPBS_TEN,
            COUNT(DISTINCT phpbs.HPBS_MA_PHAM_NHAN)  AS SO_PHAM_NHAN,
            SUM(phpbs.HPBS_TONG_TIEN_PHAT)           AS TONG_TIEN_PHAT,
            SUM(NVL(pb.TONG_THUC_HIEN, 0))          AS TONG_THUC_HIEN,
            SUM(NVL(pb.THUC_HIEN_TRUOC_KHI_XU, 0))  AS THUC_HIEN_TRUOC_KHI_XU,
            SUM(NVL(pb.THUC_HIEN_SAU_KHI_XU,  0))  AS THUC_HIEN_SAU_KHI_XU,
            SUM(NVL(pb.THUC_HIEN_KHI_CHAPT,   0))  AS THUC_HIEN_KHI_CHAPT,
            SUM(NVL(pb.NOP_TAI_TRAI,           0))  AS NOP_TAI_TRAI,
            SUM(phpbs.HPBS_TONG_TIEN_CON_LAI)       AS CON_LAI
        FROM valid_pn vp
        JOIN PN_HINH_PHAT_BO_SUNGS phpbs ON phpbs.HPBS_MA_PHAM_NHAN = vp.PHAM_NHAN_ID AND NVL(phpbs.IS_DELETED, 0) = 0
        LEFT JOIN BIEN_LAI_RAW pb ON pb.HPBS_ID = phpbs.ID
        JOIN DM_HINH_PHAT_BO_SUNGS dhpbs ON dhpbs.ID = phpbs.HPBS_HINH_PHAT
        WHERE dhpbs.HPBS_MA IN ('210','211','220')
        GROUP BY dhpbs.HPBS_TEN
    )
    SELECT
        TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY HPBS_TEN))) AS "TT",
        HPBS_TEN,
        SO_PHAM_NHAN,
        TONG_TIEN_PHAT,
        TONG_THUC_HIEN,
        THUC_HIEN_TRUOC_KHI_XU,
        THUC_HIEN_SAU_KHI_XU,
        THUC_HIEN_KHI_CHAPT,
        NOP_TAI_TRAI,
        CON_LAI
    FROM HPBS_AGG
    ORDER BY HPBS_TEN;

    DBMS_SQL.RETURN_RESULT(c1);

END SP_GET_TK_GIAM_THOI_HAN_THEO_HPBS;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_GIAM_THOI_HAN_THEO_MUC_GIAM
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_GIAM_THOI_HAN_THEO_MUC_GIAM" (
    p_dot_giam_id  IN DATE,
    p_phan_doi_id  IN NUMBER DEFAULT NULL,
    p_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ma_trai_giam IN VARCHAR2 DEFAULT null
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH DOI_TUONG_CTE AS (
        SELECT ptha.THA_PNLAI_LICH_ID,
               CASE WHEN COUNT(CASE WHEN td.TD_CHUONG = '13' THEN 1 END) > 0 THEN 1 ELSE 2 END AS DOI_TUONG_ID
          FROM PN_THI_HANH_AN ptha
          JOIN (
              SELECT ptha2.THA_PNLAI_LICH_ID,
                     TO_NUMBER(TRIM(REGEXP_SUBSTR(
                         REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''),
                         '[^,]+', 1, n.N))) AS TOI_DANH_ID
                FROM PN_THI_HANH_AN ptha2
                JOIN (SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL <= 20) n
                  ON n.N <= REGEXP_COUNT(REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''), ',') + 1
               WHERE ptha2.THA_TOI_DANH IS NOT NULL
                 AND NVL(ptha2.IS_DELETED, 0) = 0
          ) td_split ON td_split.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
          JOIN DM_TOI_DANHS td ON td.ID = td_split.TOI_DANH_ID
         WHERE NVL(ptha.IS_DELETED, 0) = 0
         GROUP BY ptha.THA_PNLAI_LICH_ID
    ),
    GTH_UNION AS (
        -- Lu?ng 1: Tr?i ?? ngh?
        SELECT
            pll.ID              AS PHAM_NHAN_ID,
            dgt.GT_TEN          AS GIOI_TINH,
            mtg.ID              AS MTG_ID,
            mtg.MTG_TITLE,
            gth_dn.PHAM_NHAN_ID AS DN_ID,
            NULL                AS BCA_ID,
            NULL                AS TQD_ID
        FROM DM_MA_THOI_GIANS mtg
        JOIN GIAM_THOI_HANS gth_dn
            ON gth_dn.MUC_DE_NGHI_ID = mtg.ID
           AND NVL(gth_dn.IS_DELETED, 0) = 0
           AND TRUNC(CAST(gth_dn.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
        JOIN PN_LAI_LICHS pll
            ON pll.ID = gth_dn.PHAM_NHAN_ID
           AND pll.IS_DELETED = 0
           AND (p_phan_doi_id IS NULL OR pll.LL_PHAN_DOI_ID = p_phan_doi_id)
        LEFT JOIN DM_GIOI_TINHS dgt ON dgt.ID = pll.LL_DM_GIOI_TINH_ID
        LEFT JOIN DOI_TUONG_CTE dt  ON dt.THA_PNLAI_LICH_ID = pll.ID
        WHERE (p_doi_tuong_id IS NULL OR dt.DOI_TUONG_ID = p_doi_tuong_id)
        AND( p_ma_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
        UNION ALL

        -- Lu?ng 2: BCA duy?t
        SELECT
            pll.ID,
            dgt.GT_TEN,
            mtg.ID,
            mtg.MTG_TITLE,
            NULL,
            gth_bca.PHAM_NHAN_ID,
            NULL
        FROM DM_MA_THOI_GIANS mtg
        JOIN GIAM_THOI_HANS gth_bca
            ON gth_bca.CAP_TREN_DUYET_ID = mtg.ID
           AND NVL(gth_bca.IS_DELETED, 0) = 0
           AND TRUNC(CAST(gth_bca.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
        JOIN PN_LAI_LICHS pll
            ON pll.ID = gth_bca.PHAM_NHAN_ID
           AND pll.IS_DELETED = 0
           AND (p_phan_doi_id IS NULL OR pll.LL_PHAN_DOI_ID = p_phan_doi_id)
        LEFT JOIN DM_GIOI_TINHS dgt ON dgt.ID = pll.LL_DM_GIOI_TINH_ID
        LEFT JOIN DOI_TUONG_CTE dt  ON dt.THA_PNLAI_LICH_ID = pll.ID
        WHERE (p_doi_tuong_id IS NULL OR dt.DOI_TUONG_ID = p_doi_tuong_id)
       AND( p_ma_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
        UNION ALL

        -- Lu?ng 3: Tòa quy?t ??nh
        SELECT
            pll.ID,
            dgt.GT_TEN,
            mtg.ID,
            mtg.MTG_TITLE,
            NULL,
            NULL,
            gth_tqd.PHAM_NHAN_ID
        FROM DM_MA_THOI_GIANS mtg
        JOIN GIAM_THOI_HANS gth_tqd
            ON gth_tqd.MUC_GIAM_ID = mtg.ID
           AND NVL(gth_tqd.IS_DELETED, 0) = 0
           AND TRUNC(CAST(gth_tqd.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
        JOIN PN_LAI_LICHS pll
            ON pll.ID = gth_tqd.PHAM_NHAN_ID
           AND pll.IS_DELETED = 0
           AND (p_phan_doi_id IS NULL OR pll.LL_PHAN_DOI_ID = p_phan_doi_id)
        LEFT JOIN DM_GIOI_TINHS dgt ON dgt.ID = pll.LL_DM_GIOI_TINH_ID
        LEFT JOIN DOI_TUONG_CTE dt  ON dt.THA_PNLAI_LICH_ID = pll.ID
        WHERE (p_doi_tuong_id IS NULL OR dt.DOI_TUONG_ID = p_doi_tuong_id)
       AND( p_ma_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
    )
    SELECT
        TO_NCHAR(
            CASE WHEN IS_TOTAL = 1 THEN ''
                 ELSE TO_CHAR(ROW_NUMBER() OVER (
                          PARTITION BY IS_TOTAL
                          ORDER BY "MucGiam"
                      ))
            END
        ) AS "TT",
        "MucGiam",
        "TraiDeNghiNam",  "TraiDeNghiNu",  "TraiDeNghiKhac",  "TraiDeNghiTong",
        "BoCongAnNam",    "BoCongAnNu",    "BoCongAnKhac",    "BoCongAnTong",
        "ToaQuyetDinhNam","ToaQuyetDinhNu","ToaQuyetDinhKhac","ToaQuyetDinhTong"
    FROM (
        SELECT
            COALESCE(TO_NCHAR(MTG_TITLE), TO_NCHAR(u'T\1ed4NG S\1ed0'))                AS "MucGiam",
            COUNT(DISTINCT CASE WHEN GIOI_TINH = 'Nam'                              THEN DN_ID  END) AS "TraiDeNghiNam",
            COUNT(DISTINCT CASE WHEN GIOI_TINH = u'N\1eef'                          THEN DN_ID  END) AS "TraiDeNghiNu",
            COUNT(DISTINCT CASE WHEN GIOI_TINH NOT IN ('Nam',u'N\1eef') OR GIOI_TINH IS NULL THEN DN_ID  END) AS "TraiDeNghiKhac",
            COUNT(DISTINCT DN_ID)                                                                    AS "TraiDeNghiTong",
            COUNT(DISTINCT CASE WHEN GIOI_TINH = 'Nam'                              THEN BCA_ID END) AS "BoCongAnNam",
            COUNT(DISTINCT CASE WHEN GIOI_TINH = u'N\1eef'                          THEN BCA_ID END) AS "BoCongAnNu",
            COUNT(DISTINCT CASE WHEN GIOI_TINH NOT IN ('Nam',u'N\1eef') OR GIOI_TINH IS NULL THEN BCA_ID END) AS "BoCongAnKhac",
            COUNT(DISTINCT BCA_ID)                                                                   AS "BoCongAnTong",
            COUNT(DISTINCT CASE WHEN GIOI_TINH = 'Nam'                              THEN TQD_ID END) AS "ToaQuyetDinhNam",
            COUNT(DISTINCT CASE WHEN GIOI_TINH = u'N\1eef'                          THEN TQD_ID END) AS "ToaQuyetDinhNu",
            COUNT(DISTINCT CASE WHEN GIOI_TINH NOT IN ('Nam',u'N\1eef') OR GIOI_TINH IS NULL THEN TQD_ID END) AS "ToaQuyetDinhKhac",
            COUNT(DISTINCT TQD_ID)                                                                   AS "ToaQuyetDinhTong",
            GROUPING(MTG_TITLE)                                                                      AS IS_TOTAL
        FROM GTH_UNION
        GROUP BY ROLLUP(MTG_TITLE)
    )
    ORDER BY IS_TOTAL, "MucGiam" NULLS LAST;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            u'L\1ed7i SP_GET_TK_GIAM_THOI_HAN_THEO_MUC_GIAM: ' || SQLERRM);
END SP_GET_TK_GIAM_THOI_HAN_THEO_MUC_GIAM;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_GIAM_THOI_HAN_THEO_PHAN_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_GIAM_THOI_HAN_THEO_PHAN_TRAI" (
    p_dot_giam_id  IN DATE,
    p_phan_doi_id  IN NUMBER DEFAULT NULL,
    p_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ma_trai_giam IN VARCHAR2 DEFAULT null
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT
        TO_NCHAR(
            CASE WHEN IS_TOTAL = 1 THEN ''
                 ELSE TO_CHAR(ROW_NUMBER() OVER (
                          PARTITION BY IS_TOTAL
                          ORDER BY "PhanTrai"
                      ))
            END
        ) AS "TT",
        "PhanTrai",
        "TraiDeNghiNam","TraiDeNghiNu","TraiDeNghiKhac","TraiDeNghiTong",
        "BoCongAnNam",  "BoCongAnNu",  "BoCongAnKhac",  "BoCongAnTong",
        "ToaQuyetDinhNam","ToaQuyetDinhNu","ToaQuyetDinhKhac","ToaQuyetDinhTong"
    FROM (
        SELECT
            COALESCE(TO_NCHAR(dpt.PT_TEN), TO_NCHAR('T?NG S?'))                              AS "PhanTrai",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'                           THEN gth_dn.PHAM_NHAN_ID  END) AS "TraiDeNghiNam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'                            THEN gth_dn.PHAM_NHAN_ID  END) AS "TraiDeNghiNu",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam','N?') OR dgt.GT_TEN IS NULL THEN gth_dn.PHAM_NHAN_ID  END) AS "TraiDeNghiKhac",
            COUNT(DISTINCT gth_dn.PHAM_NHAN_ID)                                               AS "TraiDeNghiTong",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'                           THEN gth_bca.PHAM_NHAN_ID END) AS "BoCongAnNam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'                            THEN gth_bca.PHAM_NHAN_ID END) AS "BoCongAnNu",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam','N?') OR dgt.GT_TEN IS NULL THEN gth_bca.PHAM_NHAN_ID END) AS "BoCongAnKhac",
            COUNT(DISTINCT gth_bca.PHAM_NHAN_ID)                                              AS "BoCongAnTong",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'                           THEN gth_tqd.PHAM_NHAN_ID END) AS "ToaQuyetDinhNam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'                            THEN gth_tqd.PHAM_NHAN_ID END) AS "ToaQuyetDinhNu",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam','N?') OR dgt.GT_TEN IS NULL THEN gth_tqd.PHAM_NHAN_ID END) AS "ToaQuyetDinhKhac",
            COUNT(DISTINCT gth_tqd.PHAM_NHAN_ID)                                              AS "ToaQuyetDinhTong",
            GROUPING(dpt.PT_TEN)                                                              AS IS_TOTAL
        FROM DM_PHAN_TRAIS dpt
        LEFT JOIN PN_LAI_LICHS pll
            ON pll.LL_PHAN_TRAI_ID = dpt.ID
           AND (p_phan_doi_id IS NULL OR pll.LL_PHAN_DOI_ID = p_phan_doi_id)
           AND pll.IS_DELETED = 0
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN GIAM_THOI_HANS gth_dn
            ON gth_dn.PHAM_NHAN_ID = pll.ID
           AND NVL(gth_dn.IS_DELETED, 0) = 0
           AND gth_dn.MUC_DE_NGHI_ID IS NOT NULL
           AND TRUNC(CAST(gth_dn.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
        LEFT JOIN GIAM_THOI_HANS gth_bca
            ON gth_bca.PHAM_NHAN_ID = pll.ID
           AND NVL(gth_bca.IS_DELETED, 0) = 0
           AND gth_bca.CAP_TREN_DUYET_ID IS NOT NULL
           AND TRUNC(CAST(gth_bca.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
        LEFT JOIN GIAM_THOI_HANS gth_tqd
            ON gth_tqd.PHAM_NHAN_ID = pll.ID
           AND NVL(gth_tqd.IS_DELETED, 0) = 0
           AND gth_tqd.MUC_GIAM_ID IS NOT NULL
           AND TRUNC(CAST(gth_tqd.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
        LEFT JOIN (
            SELECT ptha.THA_PNLAI_LICH_ID,
                   CASE WHEN COUNT(CASE WHEN td.TD_CHUONG = '13' THEN 1 END) > 0 THEN 1 ELSE 2 END AS DOI_TUONG_ID
              FROM PN_THI_HANH_AN ptha
              JOIN (
                  SELECT ptha2.THA_PNLAI_LICH_ID,
                         TO_NUMBER(TRIM(REGEXP_SUBSTR(
                             REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''),
                             '[^,]+', 1, n.N))) AS TOI_DANH_ID
                    FROM PN_THI_HANH_AN ptha2
                    JOIN (SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL <= 20) n
                      ON n.N <= REGEXP_COUNT(REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''), ',') + 1
                   WHERE ptha2.THA_TOI_DANH IS NOT NULL AND NVL(ptha2.IS_DELETED, 0) = 0
              ) td_split ON td_split.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
              JOIN DM_TOI_DANHS td ON td.ID = td_split.TOI_DANH_ID
             WHERE NVL(ptha.IS_DELETED, 0) = 0
             GROUP BY ptha.THA_PNLAI_LICH_ID
        ) doi_tuong ON doi_tuong.THA_PNLAI_LICH_ID = pll.ID
        WHERE (gth_dn.ID IS NOT NULL OR gth_bca.ID IS NOT NULL OR gth_tqd.ID IS NOT NULL)
          AND (p_doi_tuong_id IS NULL OR doi_tuong.DOI_TUONG_ID = p_doi_tuong_id)
          AND( p_ma_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
        GROUP BY ROLLUP(dpt.PT_TEN)
    )
    ORDER BY IS_TOTAL, "PhanTrai" NULLS LAST;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            u'L?i SP_GET_TK_GIAM_THOI_HAN_THEO_PHAN_TRAI: ' || SQLERRM);
END SP_GET_TK_GIAM_THOI_HAN_THEO_PHAN_TRAI;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_GIAM_THOI_HAN_THEO_QUOC_TICH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_GIAM_THOI_HAN_THEO_QUOC_TICH" (
    p_dot_giam_id  IN DATE,
    p_phan_doi_id  IN NUMBER DEFAULT NULL,
    p_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ma_trai_giam IN VARCHAR2 DEFAULT null
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT
        TO_NCHAR(
            CASE WHEN IS_TOTAL = 1 THEN ''
                 ELSE TO_CHAR(ROW_NUMBER() OVER (
                          PARTITION BY IS_TOTAL
                          ORDER BY "QuocTich"
                      ))
            END
        ) AS "TT",
        "QuocTich",
        "TraiDeNghiNam","TraiDeNghiNu","TraiDeNghiKhac","TraiDeNghiTong",
        "BoCongAnNam",  "BoCongAnNu",  "BoCongAnKhac",  "BoCongAnTong",
        "ToaQuyetDinhNam","ToaQuyetDinhNu","ToaQuyetDinhKhac","ToaQuyetDinhTong"
    FROM (
        SELECT
            COALESCE(TO_NCHAR(dqt.QT_TEN), TO_NCHAR('T?NG S?'))                               AS "QuocTich",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'                           THEN gth_dn.PHAM_NHAN_ID  END) AS "TraiDeNghiNam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'                            THEN gth_dn.PHAM_NHAN_ID  END) AS "TraiDeNghiNu",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam','N?') OR dgt.GT_TEN IS NULL THEN gth_dn.PHAM_NHAN_ID  END) AS "TraiDeNghiKhac",
            COUNT(DISTINCT gth_dn.PHAM_NHAN_ID)                                                AS "TraiDeNghiTong",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'                           THEN gth_bca.PHAM_NHAN_ID END) AS "BoCongAnNam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'                            THEN gth_bca.PHAM_NHAN_ID END) AS "BoCongAnNu",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam','N?') OR dgt.GT_TEN IS NULL THEN gth_bca.PHAM_NHAN_ID END) AS "BoCongAnKhac",
            COUNT(DISTINCT gth_bca.PHAM_NHAN_ID)                                               AS "BoCongAnTong",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'                           THEN gth_tqd.PHAM_NHAN_ID END) AS "ToaQuyetDinhNam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'                            THEN gth_tqd.PHAM_NHAN_ID END) AS "ToaQuyetDinhNu",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam','N?') OR dgt.GT_TEN IS NULL THEN gth_tqd.PHAM_NHAN_ID END) AS "ToaQuyetDinhKhac",
            COUNT(DISTINCT gth_tqd.PHAM_NHAN_ID)                                               AS "ToaQuyetDinhTong",
            GROUPING(dqt.QT_TEN)                                                               AS IS_TOTAL
        FROM DM_QUOC_TICHS dqt
        JOIN PN_LAI_LICHS pll
            ON pll.LL_DM_QUOC_TICH_ID = dqt.ID
           AND (p_phan_doi_id IS NULL OR pll.LL_PHAN_DOI_ID = p_phan_doi_id)
           AND pll.IS_DELETED = 0
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN GIAM_THOI_HANS gth_dn
            ON gth_dn.PHAM_NHAN_ID = pll.ID
           AND NVL(gth_dn.IS_DELETED, 0) = 0
           AND gth_dn.MUC_DE_NGHI_ID IS NOT NULL
           AND TRUNC(CAST(gth_dn.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
        LEFT JOIN GIAM_THOI_HANS gth_bca
            ON gth_bca.PHAM_NHAN_ID = pll.ID
           AND NVL(gth_bca.IS_DELETED, 0) = 0
           AND gth_bca.CAP_TREN_DUYET_ID IS NOT NULL
           AND TRUNC(CAST(gth_bca.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
        LEFT JOIN GIAM_THOI_HANS gth_tqd
            ON gth_tqd.PHAM_NHAN_ID = pll.ID
           AND NVL(gth_tqd.IS_DELETED, 0) = 0
           AND gth_tqd.MUC_GIAM_ID IS NOT NULL
           AND TRUNC(CAST(gth_tqd.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
        LEFT JOIN (
            SELECT ptha.THA_PNLAI_LICH_ID,
                   CASE WHEN COUNT(CASE WHEN td.TD_CHUONG = '13' THEN 1 END) > 0 THEN 1 ELSE 2 END AS DOI_TUONG_ID
              FROM PN_THI_HANH_AN ptha
              JOIN (
                  SELECT ptha2.THA_PNLAI_LICH_ID,
                         TO_NUMBER(TRIM(REGEXP_SUBSTR(
                             REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''),
                             '[^,]+', 1, n.N))) AS TOI_DANH_ID
                    FROM PN_THI_HANH_AN ptha2
                    JOIN (SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL <= 20) n
                      ON n.N <= REGEXP_COUNT(REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''), ',') + 1
                   WHERE ptha2.THA_TOI_DANH IS NOT NULL AND NVL(ptha2.IS_DELETED, 0) = 0
              ) td_split ON td_split.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
              JOIN DM_TOI_DANHS td ON td.ID = td_split.TOI_DANH_ID
             WHERE NVL(ptha.IS_DELETED, 0) = 0
             GROUP BY ptha.THA_PNLAI_LICH_ID
        ) doi_tuong ON doi_tuong.THA_PNLAI_LICH_ID = pll.ID
        WHERE (gth_dn.ID IS NOT NULL OR gth_bca.ID IS NOT NULL OR gth_tqd.ID IS NOT NULL)
          AND (p_doi_tuong_id IS NULL OR doi_tuong.DOI_TUONG_ID = p_doi_tuong_id)
          AND( p_ma_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
        GROUP BY ROLLUP(dqt.QT_TEN)
    )
    ORDER BY IS_TOTAL, "QuocTich" NULLS LAST;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            u'L?i SP_GET_TK_GIAM_THOI_HAN_THEO_QUOC_TICH: ' || SQLERRM);
END SP_GET_TK_GIAM_THOI_HAN_THEO_QUOC_TICH;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_GIAM_THOI_HAN_THEO_TOI_DANH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_GIAM_THOI_HAN_THEO_TOI_DANH" (
    p_dot_giam_id  IN DATE,
    p_phan_doi_id  IN NUMBER DEFAULT NULL,
    p_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ma_trai_giam IN VARCHAR2 DEFAULT null
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT
        TO_NCHAR(
            CASE WHEN IS_TOTAL = 1 THEN ''
                 ELSE TO_CHAR(ROW_NUMBER() OVER (
                          PARTITION BY IS_TOTAL
                          ORDER BY "ToiDanh"
                      ))
            END
        ) AS "TT",
        "ToiDanh",
        "TraiDeNghiNam","TraiDeNghiNu","TraiDeNghiKhac","TraiDeNghiTong",
        "BoCongAnNam",  "BoCongAnNu",  "BoCongAnKhac",  "BoCongAnTong",
        "ToaQuyetDinhNam","ToaQuyetDinhNu","ToaQuyetDinhKhac","ToaQuyetDinhTong"
    FROM (
        SELECT
            COALESCE(TO_NCHAR(dtd.TD_TEN), TO_NCHAR('T?NG S?'))                               AS "ToiDanh",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'                           THEN gth_dn.PHAM_NHAN_ID  END) AS "TraiDeNghiNam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'                            THEN gth_dn.PHAM_NHAN_ID  END) AS "TraiDeNghiNu",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam','N?') OR dgt.GT_TEN IS NULL THEN gth_dn.PHAM_NHAN_ID  END) AS "TraiDeNghiKhac",
            COUNT(DISTINCT gth_dn.PHAM_NHAN_ID)                                                AS "TraiDeNghiTong",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'                           THEN gth_bca.PHAM_NHAN_ID END) AS "BoCongAnNam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'                            THEN gth_bca.PHAM_NHAN_ID END) AS "BoCongAnNu",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam','N?') OR dgt.GT_TEN IS NULL THEN gth_bca.PHAM_NHAN_ID END) AS "BoCongAnKhac",
            COUNT(DISTINCT gth_bca.PHAM_NHAN_ID)                                               AS "BoCongAnTong",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'                           THEN gth_tqd.PHAM_NHAN_ID END) AS "ToaQuyetDinhNam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'                            THEN gth_tqd.PHAM_NHAN_ID END) AS "ToaQuyetDinhNu",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam','N?') OR dgt.GT_TEN IS NULL THEN gth_tqd.PHAM_NHAN_ID END) AS "ToaQuyetDinhKhac",
            COUNT(DISTINCT gth_tqd.PHAM_NHAN_ID)                                               AS "ToaQuyetDinhTong",
            GROUPING(dtd.TD_TEN)                                                               AS IS_TOTAL
        FROM DM_TOI_DANHS dtd
        LEFT JOIN VW_PN_TOI_DANH_CHUONG vptdc ON vptdc.TOI_DANH_ID = dtd.ID
        LEFT JOIN GIAM_THOI_HANS gth_dn
            ON gth_dn.PHAM_NHAN_ID = vptdc.PN_ID
           AND NVL(gth_dn.IS_DELETED, 0) = 0
           AND gth_dn.MUC_DE_NGHI_ID IS NOT NULL
           AND TRUNC(CAST(gth_dn.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
        LEFT JOIN GIAM_THOI_HANS gth_bca
            ON gth_bca.PHAM_NHAN_ID = vptdc.PN_ID
           AND NVL(gth_bca.IS_DELETED, 0) = 0
           AND gth_bca.CAP_TREN_DUYET_ID IS NOT NULL
           AND TRUNC(CAST(gth_bca.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
        LEFT JOIN GIAM_THOI_HANS gth_tqd
            ON gth_tqd.PHAM_NHAN_ID = vptdc.PN_ID
           AND NVL(gth_tqd.IS_DELETED, 0) = 0
           AND gth_tqd.MUC_GIAM_ID IS NOT NULL
           AND TRUNC(CAST(gth_tqd.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
        JOIN PN_LAI_LICHS pll
            ON pll.ID = COALESCE(gth_dn.PHAM_NHAN_ID, gth_bca.PHAM_NHAN_ID, gth_tqd.PHAM_NHAN_ID)
           AND (p_phan_doi_id IS NULL OR pll.LL_PHAN_DOI_ID = p_phan_doi_id)
           AND pll.IS_DELETED = 0
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN (
            SELECT ptha.THA_PNLAI_LICH_ID,
                   CASE WHEN COUNT(CASE WHEN td.TD_CHUONG = '13' THEN 1 END) > 0 THEN 1 ELSE 2 END AS DOI_TUONG_ID
              FROM PN_THI_HANH_AN ptha
              JOIN (
                  SELECT ptha2.THA_PNLAI_LICH_ID,
                         TO_NUMBER(TRIM(REGEXP_SUBSTR(
                             REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''),
                             '[^,]+', 1, n.N))) AS TOI_DANH_ID
                    FROM PN_THI_HANH_AN ptha2
                    JOIN (SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL <= 20) n
                      ON n.N <= REGEXP_COUNT(REPLACE(REPLACE(ptha2.THA_TOI_DANH,'[',''),']',''), ',') + 1
                   WHERE ptha2.THA_TOI_DANH IS NOT NULL AND NVL(ptha2.IS_DELETED, 0) = 0
              ) td_split ON td_split.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
              JOIN DM_TOI_DANHS td ON td.ID = td_split.TOI_DANH_ID
             WHERE NVL(ptha.IS_DELETED, 0) = 0
             GROUP BY ptha.THA_PNLAI_LICH_ID
        ) doi_tuong ON doi_tuong.THA_PNLAI_LICH_ID = pll.ID
        WHERE (gth_dn.ID IS NOT NULL OR gth_bca.ID IS NOT NULL OR gth_tqd.ID IS NOT NULL)
          AND (p_doi_tuong_id IS NULL OR doi_tuong.DOI_TUONG_ID = p_doi_tuong_id)
          AND( p_ma_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
        GROUP BY ROLLUP(dtd.TD_TEN)
    )
    ORDER BY IS_TOTAL, "ToiDanh" NULLS LAST;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            u'L?i SP_GET_TK_GIAM_THOI_HAN_THEO_TOI_DANH: ' || SQLERRM);
END SP_GET_TK_GIAM_THOI_HAN_THEO_TOI_DANH;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_GTH_THEO_CHUONG_TOI_DANH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_GTH_THEO_CHUONG_TOI_DANH" (
    p_dot_giam_id  IN DATE,
    p_phan_doi_id  IN NUMBER DEFAULT NULL,
    p_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ma_trai_giam IN VARCHAR2 DEFAULT null
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    GTH_NGAY AS (
        SELECT /*+ MATERIALIZE */
            gth.PHAM_NHAN_ID,
            gth.MUC_DE_NGHI_ID,
            gth.CAP_TREN_DUYET_ID,
            gth.MUC_GIAM_ID
        FROM GIAM_THOI_HANS gth
        WHERE NVL(gth.IS_DELETED, 0) = 0
          AND TRUNC(CAST(gth.NGAY_XET AS DATE)) = TRUNC(p_dot_giam_id)
    ),
    TOI_DANH_SPLIT AS (
        SELECT
            ptha.THA_PNLAI_LICH_ID AS PHAM_NHAN_ID,
            TO_NUMBER(TRIM(REGEXP_SUBSTR(
                REPLACE(REPLACE(ptha.THA_TOI_DANH,'[',''),']',''),
                '[^,]+', 1, n.N
            ))) AS TOI_DANH_ID
        FROM PN_THI_HANH_AN ptha
        JOIN GTH_NGAY gn ON gn.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID
        JOIN (SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL <= 20) n
          ON n.N <= REGEXP_COUNT(REPLACE(REPLACE(ptha.THA_TOI_DANH,'[',''),']',''), ',') + 1
        WHERE ptha.THA_TOI_DANH IS NOT NULL
          AND NVL(ptha.IS_DELETED, 0) = 0
          AND REGEXP_SUBSTR(REPLACE(REPLACE(ptha.THA_TOI_DANH,'[',''),']',''), '[^,]+', 1, n.N) IS NOT NULL
    ),
    DOI_TUONG_DATA AS (
        SELECT
            tds.PHAM_NHAN_ID,
            CASE WHEN COUNT(CASE WHEN td.TD_CHUONG = '13' THEN 1 END) > 0
                 THEN 1 ELSE 2
            END AS DOI_TUONG_ID
        FROM TOI_DANH_SPLIT tds
        JOIN DM_TOI_DANHS td ON td.ID = tds.TOI_DANH_ID
        GROUP BY tds.PHAM_NHAN_ID
    ),
    BASE AS (
        SELECT
            gn.PHAM_NHAN_ID,
            gn.MUC_DE_NGHI_ID,
            gn.CAP_TREN_DUYET_ID,
            gn.MUC_GIAM_ID,
            td.TD_CHUONG,
            dgt.GT_TEN  AS GIOI_TINH,
            dt.DOI_TUONG_ID
        FROM GTH_NGAY gn
        JOIN PN_LAI_LICHS pll
            ON pll.ID = gn.PHAM_NHAN_ID
           AND pll.IS_DELETED = 0
           AND (p_phan_doi_id IS NULL OR pll.LL_PHAN_DOI_ID = p_phan_doi_id)
        LEFT JOIN DM_GIOI_TINHS dgt ON dgt.ID = pll.LL_DM_GIOI_TINH_ID
        LEFT JOIN TOI_DANH_SPLIT tds ON tds.PHAM_NHAN_ID = gn.PHAM_NHAN_ID
        LEFT JOIN DM_TOI_DANHS td ON td.ID = tds.TOI_DANH_ID
        LEFT JOIN DOI_TUONG_DATA dt ON dt.PHAM_NHAN_ID = gn.PHAM_NHAN_ID
        WHERE (p_doi_tuong_id IS NULL OR dt.DOI_TUONG_ID = p_doi_tuong_id)
        AND( p_ma_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = (select dtg.ID from DM_TRAI_GIAMS dtg where dtg.TG_MA = p_ma_trai_giam))
    ),
    -- T?ng h?p theo t?ng ch??ng (ch? l?y dòng có TD_CHUONG th?t)
    CHUONG_AGG AS (
        SELECT
            b.TD_CHUONG,
            COUNT(DISTINCT CASE WHEN b.MUC_DE_NGHI_ID    IS NOT NULL AND b.GIOI_TINH = 'Nam'                                    THEN b.PHAM_NHAN_ID END) AS "TraiDeNghiNam",
            COUNT(DISTINCT CASE WHEN b.MUC_DE_NGHI_ID    IS NOT NULL AND b.GIOI_TINH = u'N\1eef'                                THEN b.PHAM_NHAN_ID END) AS "TraiDeNghiNu",
            COUNT(DISTINCT CASE WHEN b.MUC_DE_NGHI_ID    IS NOT NULL AND (b.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR b.GIOI_TINH IS NULL) THEN b.PHAM_NHAN_ID END) AS "TraiDeNghiKhac",
            COUNT(DISTINCT CASE WHEN b.MUC_DE_NGHI_ID    IS NOT NULL                                                            THEN b.PHAM_NHAN_ID END) AS "TraiDeNghiTong",
            COUNT(DISTINCT CASE WHEN b.CAP_TREN_DUYET_ID IS NOT NULL AND b.GIOI_TINH = 'Nam'                                    THEN b.PHAM_NHAN_ID END) AS "BoCongAnNam",
            COUNT(DISTINCT CASE WHEN b.CAP_TREN_DUYET_ID IS NOT NULL AND b.GIOI_TINH = u'N\1eef'                                THEN b.PHAM_NHAN_ID END) AS "BoCongAnNu",
            COUNT(DISTINCT CASE WHEN b.CAP_TREN_DUYET_ID IS NOT NULL AND (b.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR b.GIOI_TINH IS NULL) THEN b.PHAM_NHAN_ID END) AS "BoCongAnKhac",
            COUNT(DISTINCT CASE WHEN b.CAP_TREN_DUYET_ID IS NOT NULL                                                            THEN b.PHAM_NHAN_ID END) AS "BoCongAnTong",
            COUNT(DISTINCT CASE WHEN b.MUC_GIAM_ID       IS NOT NULL AND b.GIOI_TINH = 'Nam'                                    THEN b.PHAM_NHAN_ID END) AS "ToaQuyetDinhNam",
            COUNT(DISTINCT CASE WHEN b.MUC_GIAM_ID       IS NOT NULL AND b.GIOI_TINH = u'N\1eef'                                THEN b.PHAM_NHAN_ID END) AS "ToaQuyetDinhNu",
            COUNT(DISTINCT CASE WHEN b.MUC_GIAM_ID       IS NOT NULL AND (b.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR b.GIOI_TINH IS NULL) THEN b.PHAM_NHAN_ID END) AS "ToaQuyetDinhKhac",
            COUNT(DISTINCT CASE WHEN b.MUC_GIAM_ID       IS NOT NULL                                                            THEN b.PHAM_NHAN_ID END) AS "ToaQuyetDinhTong"
        FROM BASE b
        WHERE b.TD_CHUONG IS NOT NULL   -- ? ch? l?y ch??ng th?t, lo?i NULL do LEFT JOIN
        GROUP BY b.TD_CHUONG
    )
    -- Các dòng ch??ng: ?ánh TT b?ng ROW_NUMBER
    SELECT
        TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY TD_CHUONG))) AS "TT",
        TO_NCHAR(TD_CHUONG)    AS "ChuongToiDanh",
        "TraiDeNghiNam","TraiDeNghiNu","TraiDeNghiKhac","TraiDeNghiTong",
        "BoCongAnNam",  "BoCongAnNu",  "BoCongAnKhac",  "BoCongAnTong",
        "ToaQuyetDinhNam","ToaQuyetDinhNu","ToaQuyetDinhKhac","ToaQuyetDinhTong",
        0 AS SORT_ORDER
    FROM CHUONG_AGG

    UNION ALL

    -- Dòng T?NG S?: tính l?i t? BASE (không gi?i h?n TD_CHUONG)
    -- dùng DISTINCT trên PHAM_NHAN_ID ?? không double-count ph?m nhân có nhi?u ch??ng
    SELECT
        TO_NCHAR('')                  AS "TT",
        TO_NCHAR(u'T\1ed4NG S\1ed0') AS "ChuongToiDanh",
        COUNT(DISTINCT CASE WHEN b.MUC_DE_NGHI_ID    IS NOT NULL AND b.GIOI_TINH = 'Nam'                                    THEN b.PHAM_NHAN_ID END) AS "TraiDeNghiNam",
        COUNT(DISTINCT CASE WHEN b.MUC_DE_NGHI_ID    IS NOT NULL AND b.GIOI_TINH = u'N\1eef'                                THEN b.PHAM_NHAN_ID END) AS "TraiDeNghiNu",
        COUNT(DISTINCT CASE WHEN b.MUC_DE_NGHI_ID    IS NOT NULL AND (b.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR b.GIOI_TINH IS NULL) THEN b.PHAM_NHAN_ID END) AS "TraiDeNghiKhac",
        COUNT(DISTINCT CASE WHEN b.MUC_DE_NGHI_ID    IS NOT NULL                                                            THEN b.PHAM_NHAN_ID END) AS "TraiDeNghiTong",
        COUNT(DISTINCT CASE WHEN b.CAP_TREN_DUYET_ID IS NOT NULL AND b.GIOI_TINH = 'Nam'                                    THEN b.PHAM_NHAN_ID END) AS "BoCongAnNam",
        COUNT(DISTINCT CASE WHEN b.CAP_TREN_DUYET_ID IS NOT NULL AND b.GIOI_TINH = u'N\1eef'                                THEN b.PHAM_NHAN_ID END) AS "BoCongAnNu",
        COUNT(DISTINCT CASE WHEN b.CAP_TREN_DUYET_ID IS NOT NULL AND (b.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR b.GIOI_TINH IS NULL) THEN b.PHAM_NHAN_ID END) AS "BoCongAnKhac",
        COUNT(DISTINCT CASE WHEN b.CAP_TREN_DUYET_ID IS NOT NULL                                                            THEN b.PHAM_NHAN_ID END) AS "BoCongAnTong",
        COUNT(DISTINCT CASE WHEN b.MUC_GIAM_ID       IS NOT NULL AND b.GIOI_TINH = 'Nam'                                    THEN b.PHAM_NHAN_ID END) AS "ToaQuyetDinhNam",
        COUNT(DISTINCT CASE WHEN b.MUC_GIAM_ID       IS NOT NULL AND b.GIOI_TINH = u'N\1eef'                                THEN b.PHAM_NHAN_ID END) AS "ToaQuyetDinhNu",
        COUNT(DISTINCT CASE WHEN b.MUC_GIAM_ID       IS NOT NULL AND (b.GIOI_TINH NOT IN ('Nam', u'N\1eef') OR b.GIOI_TINH IS NULL) THEN b.PHAM_NHAN_ID END) AS "ToaQuyetDinhKhac",
        COUNT(DISTINCT CASE WHEN b.MUC_GIAM_ID       IS NOT NULL                                                            THEN b.PHAM_NHAN_ID END) AS "ToaQuyetDinhTong",
        1 AS SORT_ORDER
    FROM BASE b

    ORDER BY SORT_ORDER, "ChuongToiDanh" NULLS LAST;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001,
            u'L\1ed7i SP_GET_TK_GTH_THEO_CHUONG_TOI_DANH: ' || SQLERRM);
END SP_GET_TK_GTH_THEO_CHUONG_TOI_DANH;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_PHAM_NHAN_CHAP_HANH_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_PHAM_NHAN_CHAP_HANH_AN" (
   p_ten_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_tu_ngay IN NVARCHAR2 DEFAULT NULL,
    p_den_ngay IN NVARCHAR2 DEFAULT NULL
)
AS
    v_ten_trai_giam NVARCHAR2(2000);
    v_tu_ngay NVARCHAR2(10);
    v_den_ngay NVARCHAR2(10);
    C1 SYS_REFCURSOR;  
BEGIN
    --exec SP_GET_TK_PHAM_NHAN_CHAP_HANH_AN(NULL, '01/01/2020', '01/01/2027')
    IF p_ten_trai_giam IS NULL OR p_ten_trai_giam = '' THEN
        v_ten_trai_giam := NULL;
    ELSE
        v_ten_trai_giam := p_ten_trai_giam;
    END IF;

     IF p_tu_ngay IS NULL OR p_tu_ngay = '' THEN
        v_tu_ngay := to_char(sysdate - 1, 'DD/MM/YYYY');
        ELSE v_tu_ngay := p_tu_ngay;
    END IF;


    IF p_den_ngay IS NULL OR p_den_ngay = '' THEN
        v_den_ngay := to_char(sysdate - 1, 'DD/MM/YYYY');
        ELSE v_den_ngay := p_den_ngay;
    END IF;

      OPEN C1 FOR
        SELECT
            PHAN_TRAI,

            SUM(CASE WHEN LL.GIOI_TINH = u'Nam' THEN 1 ELSE 0 END) AS NAM,
            SUM(CASE WHEN LL.GIOI_TINH = u'N\1eef' THEN 1 ELSE 0 END) AS NU, 
            COUNT(*) AS TONG_SO

        FROM "VW_PN_LAI_LICH_CHI_TIET" LL
        WHERE LL_TINH_TRANG_ID = 19 
             AND (v_ten_trai_giam IS NULL 
                 OR UPPER(LL.TRAI_GIAM) = UPPER(v_ten_trai_giam))

            AND ((LL.LAST_MODIFICATION_TIME IS NOT NULL AND LL.LAST_MODIFICATION_TIME BETWEEN TO_TIMESTAMP(v_tu_ngay, 'DD/MM/YYYY') AND  TO_TIMESTAMP(v_den_ngay, 'DD/MM/YYYY'))
                OR  ( LL.CREATION_TIME BETWEEN TO_TIMESTAMP(v_tu_ngay, 'DD/MM/YYYY') AND  TO_TIMESTAMP(v_den_ngay, 'DD/MM/YYYY')))

        GROUP BY PHAN_TRAI
        ORDER BY PHAN_TRAI;

      DBMS_SQL.RETURN_RESULT(C1);
END;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_PHAM_NHAN_CHAP_HANH_AN_THEO_PHAN_DOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_PHAM_NHAN_CHAP_HANH_AN_THEO_PHAN_DOI" (
	p_trai_giam_id	  IN NUMBER  DEFAULT NULL,
    p_phan_doi_id 	  IN NUMBER  DEFAULT NULL,
    p_tu_ngay      	  IN DATE    DEFAULT NULL,
    p_den_ngay     	  IN DATE    DEFAULT NULL,
    p_gioi_tinh_id    IN NUMBER DEFAULT NULL,
    p_quoc_tich_id    IN NUMBER DEFAULT NULL,
    is_ket_thuc 	  IN NUMBER DEFAULT NULL
)
AS
    v_tu_ngay  DATE := NVL(p_tu_ngay,  SYSDATE - 1);
    v_den_ngay DATE := NVL(p_den_ngay, SYSDATE - 1);
    C1 SYS_REFCURSOR;

BEGIN
    OPEN C1 FOR
    SELECT
      ROW_NUMBER() OVER (ORDER BY dpt.PT_TEN,dpd.PD_TEN) AS "STT",
        dpd.PD_TEN                                                             AS "PhanDoi",
        dpt.PT_TEN AS "PhanTrai",
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam' THEN pll.ID END)           AS "Nam",
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'  THEN pll.ID END)           AS "Nu",
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'GT khác'  THEN pll.ID END)           AS "Khac",
        COUNT(DISTINCT pll.ID)                                                  AS "TongSo"
    FROM PN_LAI_LICHS pll
    LEFT JOIN DM_GIOI_TINHS dgt  ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_PHAN_DOIS dpd   ON pll.LL_PHAN_DOI_ID = dpd.ID
    LEFT JOIN PN_THI_HANH_AN ptha ON pll.ID = ptha.THA_PNLAI_LICH_ID
    LEFT JOIN DM_PHAN_TRAIS dpt  ON pll.LL_PHAN_TRAI_ID     = dpt.ID
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS tt ON pll.LL_TINH_TRANG_ID = tt.ID
    WHERE tt.TTPN_MA = 111 AND pll.IS_DELETED = 0
      AND (p_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam_id)
      AND (p_phan_doi_id IS NULL OR pll.LL_PHAN_DOI_ID = p_phan_doi_id)
      -- Ngày ??n tr?i < ??n ngày (?ã vào tr?i tr??c ho?c trong kho?ng th?i gian)
      AND (p_tu_ngay IS NULL OR (CASE WHEN is_ket_thuc = 1 THEN ptha.THA_NGAY_HET_HAN ELSE ptha.THA_NGAY_DEN_TRAI END >= v_tu_ngay))
      AND (p_den_ngay IS NULL OR (CASE WHEN is_ket_thuc = 1 THEN ptha.THA_NGAY_HET_HAN ELSE ptha.THA_NGAY_DEN_TRAI END <= v_den_ngay))
      AND (p_gioi_tinh_id IS NULL OR pll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
      -- Filter theo qu?c t?ch
      AND (p_quoc_tich_id IS NULL OR pll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
    GROUP BY
        pll.LL_PHAN_DOI_ID,
        dpd.PD_TEN,
        dpt.ID,           -- ? fix: thêm dòng này
        dpt.PT_TEN,
        pll.LL_PHAN_TRAI_ID
    ORDER BY dpt.PT_TEN,dpd.PD_TEN;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_TK_PHAM_NHAN_CHAP_HANH_AN_THEO_PHAN_DOI;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_PHAM_NHAN_CHAP_HANH_AN_THEO_PHAN_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_PHAM_NHAN_CHAP_HANH_AN_THEO_PHAN_TRAI" (
	p_trai_giam_id IN NUMBER  DEFAULT NULL,
    p_phan_doi_id IN NUMBER  DEFAULT NULL,
    p_tu_ngay      IN DATE    DEFAULT NULL,
    p_den_ngay     IN DATE    DEFAULT NULL,
    p_gioi_tinh_id     IN NUMBER DEFAULT NULL,
    p_quoc_tich_id     IN NUMBER DEFAULT NULL,
    is_ket_thuc 	  IN NUMBER DEFAULT NULL
)
AS
    v_tu_ngay  DATE := NVL(p_tu_ngay,  SYSDATE - 1);
    v_den_ngay DATE := NVL(p_den_ngay, SYSDATE - 1);
    C1 SYS_REFCURSOR;

BEGIN
    OPEN C1 FOR
        SELECT
            dpt.PT_TEN AS PHAN_TRAI,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'     THEN pll.ID END) AS NAM,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'      THEN pll.ID END) AS NU,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'GT khác' THEN pll.ID END) AS "Khac",
            COUNT(DISTINCT pll.ID)                                            AS TONG_SO
        FROM PN_LAI_LICHS pll
        LEFT JOIN DM_GIOI_TINHS dgt
            ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
            AND NVL(dgt.IS_DELETED, 0) = 0
        LEFT JOIN DM_PHAN_TRAIS dpt
            ON pll.LL_PHAN_TRAI_ID = dpt.ID
            AND NVL(dpt.IS_DELETED, 0) = 0
        LEFT JOIN DM_PHAN_DOIS dpd
            ON pll.LL_PHAN_DOI_ID = dpd.ID
            AND NVL(dpd.IS_DELETED, 0) = 0
        LEFT JOIN PN_THI_HANH_AN ptha
            ON pll.ID = ptha.THA_PNLAI_LICH_ID
            AND NVL(ptha.IS_DELETED, 0) = 0
        LEFT JOIN DM_TINH_TRANG_PHAM_NHANS tt
            ON pll.LL_TINH_TRANG_ID = tt.ID
            AND NVL(tt.IS_DELETED, 0) = 0
        WHERE tt.TTPN_MA = 111
          AND pll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_phan_doi_id IS NULL OR pll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (p_tu_ngay IS NULL OR (CASE WHEN is_ket_thuc = 1 THEN ptha.THA_NGAY_HET_HAN ELSE ptha.THA_NGAY_DEN_TRAI END >= v_tu_ngay))
          AND (p_den_ngay IS NULL OR (CASE WHEN is_ket_thuc = 1 THEN ptha.THA_NGAY_HET_HAN ELSE ptha.THA_NGAY_DEN_TRAI END <= v_den_ngay))
          AND (p_gioi_tinh_id IS NULL OR pll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
          AND (p_quoc_tich_id IS NULL OR pll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
        GROUP BY pll.LL_PHAN_TRAI_ID, dpt.PT_TEN
        ORDER BY dpt.PT_TEN;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_TK_PHAM_NHAN_CHAP_HANH_AN_THEO_PHAN_TRAI;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_PHAN_LOAI_QLPN_AN_PHAT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_PHAN_LOAI_QLPN_AN_PHAT" (
    p_trai_giam_id IN NVARCHAR2 DEFAULT NULL,
    p_tu_ngay      IN NVARCHAR2 DEFAULT NULL,
    p_den_ngay     IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi_id  IN NVARCHAR2 DEFAULT NULL
)
AS
    C1         SYS_REFCURSOR;
    v_tu_ngay  DATE;
    v_den_ngay DATE;
    v_trai_giam_id NUMBER;
BEGIN
    v_tu_ngay := CASE WHEN p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN NULL
                      ELSE TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY')) END;
    v_den_ngay := CASE WHEN p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN NULL
                       ELSE TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY')) END;

    IF p_trai_giam_id IS NULL OR TRIM(p_trai_giam_id) = '' THEN
        v_trai_giam_id := NULL;
    ELSE
        BEGIN
            SELECT tg.ID
            INTO v_trai_giam_id
            FROM QLPN.DM_TRAI_GIAMS tg
            WHERE NVL(tg.IS_DELETED, 0) = 0
              AND (tg.TG_MA = TRIM(p_trai_giam_id)
                   OR (REGEXP_LIKE(TRIM(p_trai_giam_id), '^[0-9]+$')
                       AND tg.ID = TO_NUMBER(TRIM(p_trai_giam_id))))
            FETCH FIRST 1 ROW ONLY;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20002,
                    'Không tìm th?y tr?i giam (mã/ID): ' || TRIM(p_trai_giam_id)
                );
        END;
    END IF;

    OPEN c1 FOR
    WITH
    ll_scope AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            rt.PHAM_NHAN_ID AS pn_id,
            rt.THA_AN_PHAT
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        WHERE NVL(rt.IS_DELETED, 0) = 0
          AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
          AND (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = TO_NUMBER(p_phan_doi_id))
    ),
    pl_moi_nhat AS (
        SELECT x.pham_nhan_id, x.den_loai_id, x.THA_AN_PHAT
        FROM (
            SELECT /*+ LEADING(ls pl) USE_NL(ls pl) INDEX(pl IX_PHANLOAI_DEL_PN_NGAY) */
                pl.pham_nhan_id,
                pl.den_loai_id,
                ls.THA_AN_PHAT,
                ROW_NUMBER() OVER (
                    PARTITION BY pl.pham_nhan_id
                    ORDER BY NVL(pl.NGAY_PHAN_LOAI, pl.CREATION_TIME) DESC NULLS LAST,
                             pl.ID DESC
                ) AS rn
            FROM ll_scope ls
            INNER JOIN QLPN.PHAN_LOAIS pl
                ON pl.PHAM_NHAN_ID = ls.pn_id
               AND NVL(pl.IS_DELETED, 0) = 0
               AND (v_tu_ngay IS NULL OR pl.NGAY_PHAN_LOAI >= v_tu_ngay)
               AND (v_den_ngay IS NULL OR pl.NGAY_PHAN_LOAI < v_den_ngay + 1)
        ) x
        WHERE x.rn = 1
    )
    SELECT
        ma.MA_TEN_CHI_TIEU AS MUC_AN_PHAT,
        SUM(CASE WHEN plgg.PLGG_TEN = u'A?B' THEN 1 ELSE 0 END) AS ADB,
        SUM(CASE WHEN plgg.PLGG_TEN = u'A1'  THEN 1 ELSE 0 END) AS A1,
        SUM(CASE WHEN plgg.PLGG_TEN = u'A2'  THEN 1 ELSE 0 END) AS A2,
        SUM(CASE WHEN plgg.PLGG_TEN = u'A3'  THEN 1 ELSE 0 END) AS A3,
        SUM(CASE WHEN plgg.PLGG_TEN = u'B?B' THEN 1 ELSE 0 END) AS BDB,
        SUM(CASE WHEN plgg.PLGG_TEN = u'B1'  THEN 1 ELSE 0 END) AS B1,
        SUM(CASE WHEN plgg.PLGG_TEN = u'B2'  THEN 1 ELSE 0 END) AS B2,
        SUM(CASE WHEN plgg.PLGG_TEN = u'B3'  THEN 1 ELSE 0 END) AS B3,
        SUM(CASE WHEN plgg.PLGG_TEN = u'C?B' THEN 1 ELSE 0 END) AS CDB,
        SUM(CASE WHEN plgg.PLGG_TEN = u'C1'  THEN 1 ELSE 0 END) AS C1,
        SUM(CASE WHEN plgg.PLGG_TEN = u'C2'  THEN 1 ELSE 0 END) AS C2,
        SUM(CASE WHEN plgg.PLGG_TEN = u'C3'  THEN 1 ELSE 0 END) AS C3
    FROM pl_moi_nhat pl
    LEFT JOIN QLPN.DM_MUC_ANS ma
        ON ma.ID = QLPN.PKG_TINH_AN.FN_GET_MUC_AN_ID_TU_AN_PHAT(TO_NCHAR(pl.THA_AN_PHAT))
       AND NVL(ma.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_PHAN_LOAI_GIAM_GIUS plgg
        ON pl.den_loai_id = plgg.ID
       AND NVL(plgg.IS_DELETED, 0) = 0
    GROUP BY ma.MA_TEN_CHI_TIEU;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i trong SP_GET_TK_PHAN_LOAI_QLPN_AN_PHAT: ' || SQLERRM);
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_PHAN_LOAI_QLPN_NANG_HA_LOAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_PHAN_LOAI_QLPN_NANG_HA_LOAI" (
    p_trai_giam_id IN NVARCHAR2 DEFAULT NULL,
    p_tu_ngay      IN NVARCHAR2 DEFAULT NULL,
    p_den_ngay     IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi_id  IN NVARCHAR2 DEFAULT NULL
)
AS
    v_tu_ngay  DATE;
    v_den_ngay DATE;
    v_trai_giam_id NUMBER;
    c1         SYS_REFCURSOR;
BEGIN
    v_tu_ngay := CASE WHEN p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN NULL
                      ELSE TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY')) END;
    v_den_ngay := CASE WHEN p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN NULL
                       ELSE TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY')) END;

    IF p_trai_giam_id IS NULL OR TRIM(p_trai_giam_id) = '' THEN
        v_trai_giam_id := NULL;
    ELSE
        BEGIN
            SELECT tg.ID
            INTO v_trai_giam_id
            FROM QLPN.DM_TRAI_GIAMS tg
            WHERE NVL(tg.IS_DELETED, 0) = 0
              AND (tg.TG_MA = TRIM(p_trai_giam_id)
                   OR (REGEXP_LIKE(TRIM(p_trai_giam_id), '^[0-9]+$')
                       AND tg.ID = TO_NUMBER(TRIM(p_trai_giam_id))))
            FETCH FIRST 1 ROW ONLY;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20002,
                    'Không tìm th?y tr?i giam (mã/ID): ' || TRIM(p_trai_giam_id)
                );
        END;
    END IF;

    OPEN c1 FOR
    WITH
    ll_scope AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            rt.PHAM_NHAN_ID AS pn_id,
            rt.LL_DM_GIOI_TINH_ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        WHERE NVL(rt.IS_DELETED, 0) = 0
          AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
          AND (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = TO_NUMBER(p_phan_doi_id))
    ),
    pl_moi_nhat AS (
        SELECT x.pham_nhan_id, x.mpl_ten, x.LL_DM_GIOI_TINH_ID
        FROM (
            SELECT /*+ LEADING(ls pl) USE_NL(ls pl) INDEX(pl IX_PHANLOAI_DEL_PN_NGAY) */
                pl.pham_nhan_id,
                mpl.MPL_TEN AS mpl_ten,
                ls.LL_DM_GIOI_TINH_ID,
                ROW_NUMBER() OVER (
                    PARTITION BY pl.pham_nhan_id
                    ORDER BY NVL(pl.NGAY_PHAN_LOAI, pl.CREATION_TIME) DESC NULLS LAST,
                             pl.ID DESC
                ) AS rn
            FROM ll_scope ls
            INNER JOIN QLPN.PHAN_LOAIS pl
                ON pl.PHAM_NHAN_ID = ls.pn_id
               AND NVL(pl.IS_DELETED, 0) = 0
               AND (v_tu_ngay IS NULL OR pl.NGAY_PHAN_LOAI >= v_tu_ngay)
               AND (v_den_ngay IS NULL OR pl.NGAY_PHAN_LOAI < v_den_ngay + 1)
            INNER JOIN QLPN.DM_MA_PHAN_LOAIES mpl
                ON mpl.ID = pl.LOAI_PHAN_LOAI_ID
               AND NVL(mpl.IS_DELETED, 0) = 0
               AND mpl.MPL_TEN IN (u'Nâng lo?i', u'H? lo?i')
        ) x
        WHERE x.rn = 1
    )
    SELECT
        pl.mpl_ten AS PHAN_LOAI,
        COUNT(DISTINCT CASE WHEN gt.GT_MA = 1 THEN pl.pham_nhan_id END) AS "NAM",
        COUNT(DISTINCT CASE WHEN gt.GT_MA = 2 THEN pl.pham_nhan_id END) AS "NU",
        COUNT(DISTINCT CASE WHEN gt.GT_MA IN (1, 2) THEN pl.pham_nhan_id END) AS "TONG_CONG"
    FROM pl_moi_nhat pl
    LEFT JOIN QLPN.DM_GIOI_TINHS gt
        ON gt.ID = pl.LL_DM_GIOI_TINH_ID
       AND NVL(gt.IS_DELETED, 0) = 0
    GROUP BY pl.mpl_ten;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i SP_GET_TK_PHAN_LOAI_QLPN_NANG_HA_LOAI: ' || SQLERRM);
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_PHAN_LOAI_QLPN_PHAN_DOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_PHAN_LOAI_QLPN_PHAN_DOI" (
    p_trai_giam_id IN NVARCHAR2 DEFAULT NULL,
    p_tu_ngay      IN NVARCHAR2 DEFAULT NULL,
    p_den_ngay     IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi_id  IN NVARCHAR2 DEFAULT NULL
)
AS
    C1         SYS_REFCURSOR;
    v_tu_ngay  DATE;
    v_den_ngay DATE;
    v_trai_giam_id NUMBER;
BEGIN
    v_tu_ngay := CASE WHEN p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN NULL
                      ELSE TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY')) END;
    v_den_ngay := CASE WHEN p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN NULL
                       ELSE TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY')) END;

    IF p_trai_giam_id IS NULL OR TRIM(p_trai_giam_id) = '' THEN
        v_trai_giam_id := NULL;
    ELSE
        BEGIN
            SELECT tg.ID
            INTO v_trai_giam_id
            FROM QLPN.DM_TRAI_GIAMS tg
            WHERE NVL(tg.IS_DELETED, 0) = 0
              AND (tg.TG_MA = TRIM(p_trai_giam_id)
                   OR (REGEXP_LIKE(TRIM(p_trai_giam_id), '^[0-9]+$')
                       AND tg.ID = TO_NUMBER(TRIM(p_trai_giam_id))))
            FETCH FIRST 1 ROW ONLY;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20002,
                    'Không tìm th?y tr?i giam (mã/ID): ' || TRIM(p_trai_giam_id)
                );
        END;
    END IF;

    OPEN C1 FOR
    WITH
    ll_scope AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            rt.PHAM_NHAN_ID AS pn_id,
            rt.LL_PHAN_DOI_ID,
            rt.LL_PHAN_TRAI_ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        WHERE NVL(rt.IS_DELETED, 0) = 0
          AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
          AND (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = TO_NUMBER(p_phan_doi_id))
    ),
    pl_moi_nhat AS (
        SELECT
            x.pham_nhan_id,
            x.den_loai_id,
            x.LL_PHAN_DOI_ID,
            x.LL_PHAN_TRAI_ID
        FROM (
            SELECT /*+ LEADING(ls pl) USE_NL(ls pl) INDEX(pl IX_PHANLOAI_DEL_PN_NGAY) */
                pl.pham_nhan_id,
                pl.den_loai_id,
                ls.LL_PHAN_DOI_ID,
                ls.LL_PHAN_TRAI_ID,
                ROW_NUMBER() OVER (
                    PARTITION BY pl.pham_nhan_id
                    ORDER BY NVL(pl.NGAY_PHAN_LOAI, pl.CREATION_TIME) DESC NULLS LAST,
                             pl.ID DESC
                ) AS rn
            FROM ll_scope ls
            INNER JOIN QLPN.PHAN_LOAIS pl
                ON pl.PHAM_NHAN_ID = ls.pn_id
               AND NVL(pl.IS_DELETED, 0) = 0
               AND (v_tu_ngay IS NULL OR pl.NGAY_PHAN_LOAI >= v_tu_ngay)
               AND (v_den_ngay IS NULL OR pl.NGAY_PHAN_LOAI < v_den_ngay + 1)
        ) x
        WHERE x.rn = 1
    )
    SELECT
        TRIM(
            NVL(pd.PD_TEN, u'') ||
            CASE WHEN pd.PD_TEN IS NOT NULL AND pt.PT_TEN IS NOT NULL THEN u', ' ELSE u'' END ||
            NVL(pt.PT_TEN, u'')
        ) AS PHAN_DOI,
        SUM(CASE WHEN plgg.PLGG_TEN = u'A?B' THEN 1 ELSE 0 END) AS ADB,
        SUM(CASE WHEN plgg.PLGG_TEN = u'A1'  THEN 1 ELSE 0 END) AS A1,
        SUM(CASE WHEN plgg.PLGG_TEN = u'A2'  THEN 1 ELSE 0 END) AS A2,
        SUM(CASE WHEN plgg.PLGG_TEN = u'A3'  THEN 1 ELSE 0 END) AS A3,
        SUM(CASE WHEN plgg.PLGG_TEN = u'B?B' THEN 1 ELSE 0 END) AS BDB,
        SUM(CASE WHEN plgg.PLGG_TEN = u'B1'  THEN 1 ELSE 0 END) AS B1,
        SUM(CASE WHEN plgg.PLGG_TEN = u'B2'  THEN 1 ELSE 0 END) AS B2,
        SUM(CASE WHEN plgg.PLGG_TEN = u'B3'  THEN 1 ELSE 0 END) AS B3,
        SUM(CASE WHEN plgg.PLGG_TEN = u'C?B' THEN 1 ELSE 0 END) AS CDB,
        SUM(CASE WHEN plgg.PLGG_TEN = u'C1'  THEN 1 ELSE 0 END) AS C1,
        SUM(CASE WHEN plgg.PLGG_TEN = u'C2'  THEN 1 ELSE 0 END) AS C2,
        SUM(CASE WHEN plgg.PLGG_TEN = u'C3'  THEN 1 ELSE 0 END) AS C3
    FROM pl_moi_nhat pl
    LEFT JOIN QLPN.DM_PHAN_LOAI_GIAM_GIUS plgg
        ON pl.den_loai_id = plgg.ID
       AND NVL(plgg.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_PHAN_DOIS pd
        ON pd.ID = pl.LL_PHAN_DOI_ID
       AND NVL(pd.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_PHAN_TRAIS pt
        ON pt.ID = pl.LL_PHAN_TRAI_ID
       AND NVL(pt.IS_DELETED, 0) = 0
    GROUP BY pd.PD_TEN, pt.PT_TEN
    ORDER BY pd.PD_TEN, pt.PT_TEN;

    DBMS_SQL.RETURN_RESULT(C1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i SP_GET_TK_PHAN_LOAI_QLPN_PHAN_DOI: ' || SQLERRM);
END;



