                    ORDER BY NVL(pl.NGAY_PHAN_LOAI, pl.CREATION_TIME) DESC NULLS LAST,
                             pl.ID DESC
                ) AS rn
            FROM ll_scope ls
            INNER JOIN QLPN.PHAN_LOAIS pl
                ON pl.PHAM_NHAN_ID = ls.pn_id
               AND NVL(pl.IS_DELETED, 0) = 0
               AND (v_tu_ngay IS NULL OR pl.NGAY_PHAN_LOAI >= v_tu_ngay)
               AND (v_den_ngay IS NULL OR pl.NGAY_PHAN_LOAI < v_den_ngay + 1)
        ) x
        WHERE x.rn = 1
    )
    SELECT
        plgg.PLGG_TEN AS PHAN_LOAI_GIAM_GIU,
        COUNT(DISTINCT CASE WHEN UPPER(gt.GT_TEN) = u'NAM' THEN pl.pham_nhan_id END) AS "NAM",
        COUNT(DISTINCT CASE WHEN UPPER(gt.GT_TEN) = u'N?' THEN pl.pham_nhan_id END) AS "NU",
        COUNT(DISTINCT CASE WHEN UPPER(gt.GT_TEN) NOT IN (u'NAM', u'N?') OR gt.GT_TEN IS NULL THEN pl.pham_nhan_id END) AS "KHAC",
        COUNT(DISTINCT pl.pham_nhan_id) AS "TONG_CONG"
    FROM pl_moi_nhat pl
    LEFT JOIN QLPN.DM_PHAN_LOAI_GIAM_GIUS plgg
        ON pl.den_loai_id = plgg.ID
       AND NVL(plgg.IS_DELETED, 0) = 0
    LEFT JOIN QLPN.DM_GIOI_TINHS gt
        ON pl.LL_DM_GIOI_TINH_ID = gt.ID
       AND NVL(gt.IS_DELETED, 0) = 0
    GROUP BY plgg.PLGG_TEN
    ORDER BY plgg.PLGG_TEN;

    DBMS_SQL.RETURN_RESULT(C1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i SP_GET_TK_PHAN_LOAI_QLPN_PHAN_LOAI: ' || SQLERRM);
END;



