               AND (v_den_ngay IS NULL OR pl.NGAY_PHAN_LOAI < v_den_ngay + 1)
        ) x
        WHERE x.rn = 1
    )
    SELECT
        UPPER(pt.PT_TEN) AS PHAN_TRAI,
        SUM(CASE WHEN plgg.PLGG_TEN = u'A?B' THEN 1 ELSE 0 END) AS ADB,
        SUM(CASE WHEN plgg.PLGG_TEN = u'A1'  THEN 1 ELSE 0 END) AS A1,
        SUM(CASE WHEN plgg.PLGG_TEN = u'A2'  THEN 1 ELSE 0 END) AS A2,
