--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_PHAN_LOAI_QLPN_TINH_TIET_UU_TIEN" (
    p_trai_giam_id IN NVARCHAR2 DEFAULT NULL,
