    v_den_ngay := CASE WHEN p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN NULL
                       ELSE TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY')) END;

    IF p_trai_giam_id IS NULL OR TRIM(p_trai_giam_id) = '' THEN
        v_trai_giam_id := NULL;
    ELSE
        BEGIN
            SELECT tg.ID
            INTO v_trai_giam_id
            FROM QLPN.DM_TRAI_GIAMS tg
            WHERE NVL(tg.IS_DELETED, 0) = 0
              AND (tg.TG_MA = TRIM(p_trai_giam_id)
                   OR (REGEXP_LIKE(TRIM(p_trai_giam_id), '^[0-9]+$')
                       AND tg.ID = TO_NUMBER(TRIM(p_trai_giam_id))))
            FETCH FIRST 1 ROW ONLY;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20002,
                    'Không tìm th?y tr?i giam (mã/ID): ' || TRIM(p_trai_giam_id)
                );
        END;
    END IF;

    OPEN C1 FOR
    WITH
    ll_scope AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            rt.PHAM_NHAN_ID AS pn_id,
            rt.LL_GHI_CHU_RIENG
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        WHERE NVL(rt.IS_DELETED, 0) = 0
          AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
          AND (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = TO_NUMBER(p_phan_doi_id))
    ),
    pl_moi_nhat AS (
        SELECT x.pham_nhan_id, x.den_loai_id, x.LL_GHI_CHU_RIENG
        FROM (
            SELECT /*+ LEADING(ls pl) USE_NL(ls pl) INDEX(pl IX_PHANLOAI_DEL_PN_NGAY) */
                pl.pham_nhan_id,
                pl.den_loai_id,
                ls.LL_GHI_CHU_RIENG,
                ROW_NUMBER() OVER (
                    PARTITION BY pl.pham_nhan_id
                    ORDER BY NVL(pl.NGAY_PHAN_LOAI, pl.CREATION_TIME) DESC NULLS LAST,
                             pl.ID DESC
                ) AS rn
