               AND NVL(pl.IS_DELETED, 0) = 0
               AND (v_tu_ngay IS NULL OR pl.NGAY_PHAN_LOAI >= v_tu_ngay)
               AND (v_den_ngay IS NULL OR pl.NGAY_PHAN_LOAI < v_den_ngay + 1)
        ) x
        WHERE x.rn = 1
    ),
    base_tt AS (
        SELECT
            pl.LL_GHI_CHU_RIENG AS ghi_chu_rieng,
