            ON gcr.ID = i.ghi_chu_rieng_id
           AND NVL(gcr.IS_DELETED, 0) = 0
    )
    SELECT
        tinh_tiet_uu_tien,
        SUM(CASE WHEN phan_loai_giam_giu = u'A?B' THEN 1 ELSE 0 END) AS ADB,
