        SUM(CASE WHEN phan_loai_giam_giu = u'B?B' THEN 1 ELSE 0 END) AS BDB,
        SUM(CASE WHEN phan_loai_giam_giu = u'B1'  THEN 1 ELSE 0 END) AS B1,
        SUM(CASE WHEN phan_loai_giam_giu = u'B2'  THEN 1 ELSE 0 END) AS B2,
        SUM(CASE WHEN phan_loai_giam_giu = u'B3'  THEN 1 ELSE 0 END) AS B3,
        SUM(CASE WHEN phan_loai_giam_giu = u'C?B' THEN 1 ELSE 0 END) AS CDB,
        SUM(CASE WHEN phan_loai_giam_giu = u'C1'  THEN 1 ELSE 0 END) AS C1,
        SUM(CASE WHEN phan_loai_giam_giu = u'C2'  THEN 1 ELSE 0 END) AS C2,
        SUM(CASE WHEN phan_loai_giam_giu = u'C3'  THEN 1 ELSE 0 END) AS C3
    FROM tt
    GROUP BY tinh_tiet_uu_tien
    ORDER BY tinh_tiet_uu_tien;

    DBMS_SQL.RETURN_RESULT(C1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i SP_GET_TK_PHAN_LOAI_QLPN_TINH_TIET_UU_TIEN: ' || SQLERRM);
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_PHAN_LOAI_QLPN_TOI_DANH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_PHAN_LOAI_QLPN_TOI_DANH" (
    p_trai_giam_id IN NVARCHAR2 DEFAULT NULL,
    p_tu_ngay      IN NVARCHAR2 DEFAULT NULL,
    p_den_ngay     IN NVARCHAR2 DEFAULT NULL,
    p_phan_doi_id  IN NVARCHAR2 DEFAULT NULL
)
AS
    C1         SYS_REFCURSOR;
    v_tu_ngay  DATE;
    v_den_ngay DATE;
    v_trai_giam_id NUMBER;
BEGIN
    v_tu_ngay := CASE WHEN p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN NULL
                      ELSE TRUNC(TO_DATE(TRIM(p_tu_ngay), 'DD/MM/YYYY')) END;
    v_den_ngay := CASE WHEN p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN NULL
                       ELSE TRUNC(TO_DATE(TRIM(p_den_ngay), 'DD/MM/YYYY')) END;

    IF p_trai_giam_id IS NULL OR TRIM(p_trai_giam_id) = '' THEN
        v_trai_giam_id := NULL;
    ELSE
        BEGIN
            SELECT tg.ID
            INTO v_trai_giam_id
            FROM QLPN.DM_TRAI_GIAMS tg
            WHERE NVL(tg.IS_DELETED, 0) = 0
              AND (tg.TG_MA = TRIM(p_trai_giam_id)
                   OR (REGEXP_LIKE(TRIM(p_trai_giam_id), '^[0-9]+$')
                       AND tg.ID = TO_NUMBER(TRIM(p_trai_giam_id))))
            FETCH FIRST 1 ROW ONLY;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20002,
                    'Không tìm th?y tr?i giam (mã/ID): ' || TRIM(p_trai_giam_id)
                );
        END;
    END IF;

    OPEN C1 FOR
    WITH
    ll_scope AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            rt.PHAM_NHAN_ID AS pn_id,
            rt.THA_TOI_DANH
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        WHERE NVL(rt.IS_DELETED, 0) = 0
          AND rt.THA_TOI_DANH IS NOT NULL
          AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
          AND (p_phan_doi_id IS NULL OR rt.LL_PHAN_DOI_ID = TO_NUMBER(p_phan_doi_id))
    ),
    pl_moi_nhat AS (
        SELECT x.pham_nhan_id, x.den_loai_id, x.THA_TOI_DANH
        FROM (
            SELECT /*+ LEADING(ls pl) USE_NL(ls pl) INDEX(pl IX_PHANLOAI_DEL_PN_NGAY) */
                pl.pham_nhan_id,
                pl.den_loai_id,
                ls.THA_TOI_DANH,
                ROW_NUMBER() OVER (
                    PARTITION BY pl.pham_nhan_id
                    ORDER BY NVL(pl.NGAY_PHAN_LOAI, pl.CREATION_TIME) DESC NULLS LAST,
                             pl.ID DESC
                ) AS rn
            FROM ll_scope ls
            INNER JOIN QLPN.PHAN_LOAIS pl
                ON pl.PHAM_NHAN_ID = ls.pn_id
               AND NVL(pl.IS_DELETED, 0) = 0
               AND (v_tu_ngay IS NULL OR pl.NGAY_PHAN_LOAI >= v_tu_ngay)
               AND (v_den_ngay IS NULL OR pl.NGAY_PHAN_LOAI < v_den_ngay + 1)
        ) x
        WHERE x.rn = 1
    ),
    data_detail AS (
        SELECT
            TO_NUMBER(REGEXP_SUBSTR(pl.THA_TOI_DANH, '[0-9]+')) AS TOI_DANH_ID,
            plgg.PLGG_TEN AS PHAN_LOAI_GIAM_GIU
        FROM pl_moi_nhat pl
        LEFT JOIN QLPN.DM_PHAN_LOAI_GIAM_GIUS plgg
            ON pl.den_loai_id = plgg.ID
           AND NVL(plgg.IS_DELETED, 0) = 0
    )
    SELECT
        td.TD_TEN AS TOI_DANH,
        SUM(CASE WHEN d.PHAN_LOAI_GIAM_GIU = u'A?B' THEN 1 ELSE 0 END) AS ADB,
        SUM(CASE WHEN d.PHAN_LOAI_GIAM_GIU = u'A1'  THEN 1 ELSE 0 END) AS A1,
        SUM(CASE WHEN d.PHAN_LOAI_GIAM_GIU = u'A2'  THEN 1 ELSE 0 END) AS A2,
        SUM(CASE WHEN d.PHAN_LOAI_GIAM_GIU = u'A3'  THEN 1 ELSE 0 END) AS A3,
        SUM(CASE WHEN d.PHAN_LOAI_GIAM_GIU = u'B?B' THEN 1 ELSE 0 END) AS BDB,
        SUM(CASE WHEN d.PHAN_LOAI_GIAM_GIU = u'B1'  THEN 1 ELSE 0 END) AS B1,
        SUM(CASE WHEN d.PHAN_LOAI_GIAM_GIU = u'B2'  THEN 1 ELSE 0 END) AS B2,
        SUM(CASE WHEN d.PHAN_LOAI_GIAM_GIU = u'B3'  THEN 1 ELSE 0 END) AS B3,
        SUM(CASE WHEN d.PHAN_LOAI_GIAM_GIU = u'C?B' THEN 1 ELSE 0 END) AS CDB,
        SUM(CASE WHEN d.PHAN_LOAI_GIAM_GIU = u'C1'  THEN 1 ELSE 0 END) AS C1,
        SUM(CASE WHEN d.PHAN_LOAI_GIAM_GIU = u'C2'  THEN 1 ELSE 0 END) AS C2,
        SUM(CASE WHEN d.PHAN_LOAI_GIAM_GIU = u'C3'  THEN 1 ELSE 0 END) AS C3
    FROM data_detail d
    LEFT JOIN QLPN.DM_TOI_DANHS td
        ON d.TOI_DANH_ID = td.ID
    GROUP BY td.TD_TEN
    ORDER BY td.TD_TEN;

    DBMS_SQL.RETURN_RESULT(C1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i SP_GET_TK_PHAN_LOAI_QLPN_TOI_DANH: ' || SQLERRM);
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_QLPN_DAN_TOC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_QLPN_DAN_TOC" (
    p_tu_ngay       IN NVARCHAR2 DEFAULT NULL,
    p_den_ngay      IN NVARCHAR2 DEFAULT NULL,
    p_ten_trai_giam IN NVARCHAR2 DEFAULT NULL
) AS
    v_tu_ngay       DATE;
    v_den_ngay      DATE;
    v_ten_trai_giam NVARCHAR2(2000);
	p_cursor        SYS_REFCURSOR;

BEGIN

    IF p_ten_trai_giam IS NULL OR TRIM(p_ten_trai_giam) = '' THEN
        v_ten_trai_giam := NULL;
    ELSE
        v_ten_trai_giam := p_ten_trai_giam;
    END IF;

    -- X? lý t? ngày
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(p_tu_ngay, 'DD/MM/YYYY');
    END IF;

    -- X? lý ??n ngày
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(p_den_ngay, 'DD/MM/YYYY');
    END IF;

	OPEN p_cursor FOR
		SELECT 
			vpllct.DAN_TOC,
			vpllct.GIOI_TINH,
			COUNT(DISTINCT pktrt.KTRT_PN_LAI_LICH_ID) AS SO_LUONG
		FROM PN_KET_THUC_RA_TRAIS pktrt
		LEFT JOIN VW_PN_LAI_LICH_CHI_TIET vpllct 
		ON vpllct.PHAM_NHAN_ID = pktrt.KTRT_PN_LAI_LICH_ID
		WHERE 1=1
		-- L?c ngày l?c các ph?m nhân ra tr?i t? ngày A - B
			AND (v_tu_ngay IS NULL OR CAST(pktrt.KTRT_NGAY_THA AS DATE) >= v_tu_ngay)
			AND (v_den_ngay IS NULL OR CAST(pktrt.KTRT_NGAY_THA AS DATE) <= v_den_ngay)
			AND (v_ten_trai_giam IS NULL OR vpllct.TRAI_GIAM = v_ten_trai_giam)
		GROUP BY 
			vpllct.DAN_TOC,
			vpllct.GIOI_TINH;

    	DBMS_SQL.RETURN_RESULT(p_cursor);

	EXCEPTION
	    WHEN OTHERS THEN
	        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y d? li?u ph?m nhân ra tr?i: ' || SQLERRM);
END SP_GET_TK_QLPN_DAN_TOC;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_QLPN_DOT_THA_CO_DK
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_QLPN_DOT_THA_CO_DK" (
-- TH?NG KÊ THEO CÁC ??T THA TÙ TR??C TH?I H?N CÓ ?I?U KI?N
	p_tu_ngay NVARCHAR2 DEFAULT NULL,
	p_den_ngay NVARCHAR2 DEFAULT NULL,
    p_ma_trai_giam IN varchar2 default null
)
AS 
	p_cursor SYS_REFCURSOR;
BEGIN
	OPEN p_cursor FOR 
		SELECT
		TO_CHAR(tcdk.NGAY_XET, 'DD/MM/YYYY') AS DOT_XET,
		COUNT(CASE WHEN tcdk.DIA_PHUONG_QUYET_DINH_THA_ID IS NOT NULL AND UPPER(LL.GIOI_TINH) = 'NAM' THEN LL.PHAM_NHAN_ID END) AS DV_NAM,
		COUNT(CASE WHEN tcdk.DIA_PHUONG_QUYET_DINH_THA_ID IS NOT NULL AND UPPER(LL.GIOI_TINH) = 'NU'  THEN LL.PHAM_NHAN_ID END) AS DV_NU,
		COUNT(CASE WHEN tcdk.TOA_QUYET_DINH_LAI_ID IS NOT NULL THEN LL.PHAM_NHAN_ID END) AS DV_TONG,
		COUNT(CASE WHEN tcdk.TOA_QUYET_DINH_LAI_ID IS NOT NULL AND UPPER(LL.GIOI_TINH) = 'NAM'  THEN LL.PHAM_NHAN_ID END) AS TQD_NAM,
		COUNT(CASE WHEN tcdk.TOA_QUYET_DINH_LAI_ID IS NOT NULL AND UPPER(LL.GIOI_TINH) = 'NU'  THEN LL.PHAM_NHAN_ID END) AS TQD_NU,
		COUNT(CASE WHEN tcdk.TOA_QUYET_DINH_LAI_ID IS NOT NULL THEN LL.PHAM_NHAN_ID END) AS TQD_TONG
		FROM THA_CO_DIEU_KIENS tcdk
		LEFT JOIN VW_PN_LAI_LICH_CHI_TIET LL
		ON tcdk.PHAM_NHAN_ID = LL.PHAM_NHAN_ID
		WHERE tcdk.IS_DELETED = 0
		AND (p_tu_ngay IS NULL OR tcdk.NGAY_XET >= TO_TIMESTAMP(p_tu_ngay, 'DD/MM/YYYY'))
        AND  (p_den_ngay IS NULL OR tcdk.NGAY_XET <= TO_TIMESTAMP(p_den_ngay, 'DD/MM/YYYY'))
        and (p_ma_trai_giam is null or ll.TRAI_GIAM_MA = p_ma_trai_giam)
		GROUP BY TO_CHAR(tcdk.NGAY_XET, 'DD/MM/YYYY');

	DBMS_SQL.RETURN_RESULT(p_cursor);
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_QLPN_QUOC_TICH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_QLPN_QUOC_TICH" (
    p_quoc_tich_id  IN NUMBER   DEFAULT NULL,
    p_tu_ngay       IN DATE     DEFAULT NULL,
    p_den_ngay      IN DATE     DEFAULT NULL,
    p_phan_doi_id   IN NUMBER   DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        SELECT
            vpllct.QUOC_TICH,
            vpllct.GIOI_TINH,
            COUNT(DISTINCT pktrt.KTRT_PN_LAI_LICH_ID) AS "SoLuong"
        FROM PN_KET_THUC_RA_TRAIS pktrt
        LEFT JOIN VW_PN_LAI_LICH_CHI_TIET vpllct
            ON vpllct.PHAM_NHAN_ID = pktrt.KTRT_PN_LAI_LICH_ID
        LEFT JOIN PN_LAI_LICHS ll
            ON pktrt.KTRT_PN_LAI_LICH_ID = ll.ID
        WHERE pktrt.IS_DELETED = 0
          AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID      = p_quoc_tich_id)
          AND (p_phan_doi_id  IS NULL OR ll.LL_PHAN_DOI_ID           = p_phan_doi_id)
          AND (p_tu_ngay      IS NULL OR CAST(pktrt.KTRT_NGAY_THA AS DATE) >= p_tu_ngay)
          AND (p_den_ngay     IS NULL OR CAST(pktrt.KTRT_NGAY_THA AS DATE) <= p_den_ngay)
        GROUP BY
            vpllct.QUOC_TICH,
            vpllct.GIOI_TINH;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i khi l?y d? li?u ph?m nhân ra tr?i: ' || SQLERRM);
END SP_GET_TK_QLPN_QUOC_TICH;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_QLPN_THEO_PHAN_LOAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_QLPN_THEO_PHAN_LOAI" (
    p_ten_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_tu_ngay       IN NVARCHAR2 DEFAULT NULL,
    p_den_ngay      IN NVARCHAR2 DEFAULT NULL
) AS
    v_ten_trai_giam NVARCHAR2(2000);
    v_tu_ngay       DATE;
    v_den_ngay      DATE;
    p_cursor        SYS_REFCURSOR;
BEGIN
    -- X? lý tên tr?i giam
    IF p_ten_trai_giam IS NULL OR TRIM(p_ten_trai_giam) = '' THEN
        v_ten_trai_giam := NULL;
    ELSE
        v_ten_trai_giam := p_ten_trai_giam;
    END IF;

    -- X? lý t? ngày
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := NULL;
    ELSE
        v_tu_ngay := TO_DATE(p_tu_ngay, 'DD/MM/YYYY');
    END IF;

    -- X? lý ??n ngày
    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := NULL;
    ELSE
        v_den_ngay := TO_DATE(p_den_ngay, 'DD/MM/YYYY');
    END IF;

    -- Debug 	
    DBMS_OUTPUT.PUT_LINE('Tên tr?i giam: ' || NVL(v_ten_trai_giam, 'T?t c?'));
    DBMS_OUTPUT.PUT_LINE('T? ngày: ' || NVL(TO_CHAR(v_tu_ngay, 'DD/MM/YYYY'), 'Không gi?i h?n'));
    DBMS_OUTPUT.PUT_LINE('??n ngày: ' || NVL(TO_CHAR(v_den_ngay, 'DD/MM/YYYY'), 'Không gi?i h?n'));

    -- Ch?y câu query chính
    OPEN p_cursor FOR
        WITH pl_moi_nhat AS (
            SELECT pl2.pham_nhan_id, pl2.den_loai_id
            FROM (
                SELECT
                    pl.pham_nhan_id,
                    pl.den_loai_id,
                    ROW_NUMBER() OVER (
                        PARTITION BY pl.pham_nhan_id
                        ORDER BY NVL(pl.NGAY_PHAN_LOAI, pl.CREATION_TIME) DESC NULLS LAST, pl.ID DESC
                    ) AS rn
                FROM PHAN_LOAIS pl
                WHERE NVL(pl.IS_DELETED, 0) = 0
                  -- Performance: pre-filter by index subset when jail name parameter is present
                  AND (
                      v_ten_trai_giam IS NULL
                      OR pl.pham_nhan_id IN (
                          SELECT ll.id FROM QLPN.PN_LAI_LICHS ll
                          JOIN DM_TRAI_GIAMS tg ON ll.LL_TRAI_GIAM_ID = tg.ID AND NVL(tg.IS_DELETED, 0) = 0
                          WHERE NVL(ll.IS_DELETED, 0) = 0
                            AND tg.TG_TEN = v_ten_trai_giam
                      )
                  )
            ) pl2
            WHERE pl2.rn = 1
        ),
        ptha_one AS (
            SELECT x.THA_PNLAI_LICH_ID, x.THA_NGAY_HET_HAN
            FROM (
                SELECT t.THA_PNLAI_LICH_ID, t.THA_NGAY_HET_HAN,
                       ROW_NUMBER() OVER (
                           PARTITION BY t.THA_PNLAI_LICH_ID
                           ORDER BY NVL(t.THA_NGAY_HET_HAN, t.CREATION_TIME) DESC NULLS LAST, t.ID DESC
                       ) AS rn
                FROM QLPN.PN_THI_HANH_AN t
                WHERE NVL(t.IS_DELETED, 0) = 0
                  -- Performance: pre-filter by index subset when jail name parameter is present
                  AND (
                      v_ten_trai_giam IS NULL
                      OR t.THA_PNLAI_LICH_ID IN (
                          SELECT ll.id FROM QLPN.PN_LAI_LICHS ll
                          JOIN DM_TRAI_GIAMS tg ON ll.LL_TRAI_GIAM_ID = tg.ID AND NVL(tg.IS_DELETED, 0) = 0
                          WHERE NVL(ll.IS_DELETED, 0) = 0
                            AND tg.TG_TEN = v_ten_trai_giam
                      )
                  )
            ) x
            WHERE x.rn = 1
        )
        SELECT
            plgg.PLGG_TEN AS PHAN_LOAI_GIAM_GIU,
            COUNT(DISTINCT CASE WHEN UPPER(gt.GT_TEN) = 'NAM' THEN LL.ID END) AS "NAM",
            COUNT(DISTINCT CASE WHEN UPPER(gt.GT_TEN) = u'N\1eef' THEN LL.ID END) AS "NU",
            COUNT(DISTINCT CASE WHEN UPPER(gt.GT_TEN) IN ('NAM', u'N\1eef') THEN LL.ID END) AS "TONG_CONG"
        FROM QLPN.PN_LAI_LICHS LL
        INNER JOIN pl_moi_nhat pl ON LL.ID = pl.pham_nhan_id
        LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS plgg ON pl.den_loai_id = plgg.ID AND NVL(plgg.IS_DELETED, 0) = 0
        LEFT JOIN DM_GIOI_TINHS gt ON LL.LL_DM_GIOI_TINH_ID = gt.ID AND NVL(gt.IS_DELETED, 0) = 0
        LEFT JOIN DM_TRAI_GIAMS tg ON LL.LL_TRAI_GIAM_ID = tg.ID AND NVL(tg.IS_DELETED, 0) = 0
        LEFT JOIN ptha_one ptha ON LL.ID = ptha.THA_PNLAI_LICH_ID
        WHERE NVL(LL.IS_DELETED, 0) = 0
          AND (v_ten_trai_giam IS NULL OR tg.TG_TEN = v_ten_trai_giam)
          -- L?c các tr??ng h?p t? ngày b?t ??u v?n ?ang ? tù
          AND (v_tu_ngay IS NULL OR ptha.THA_NGAY_HET_HAN >= v_tu_ngay)
        GROUP BY plgg.PLGG_TEN
        ORDER BY plgg.PLGG_TEN;

    DBMS_SQL.RETURN_RESULT(p_cursor);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i SP_GET_TK_QLPN_THEO_PHAN_LOAI: ' || SQLERRM);
END SP_GET_TK_QLPN_THEO_PHAN_LOAI;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_XEP_LOAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_XEP_LOAI" (
    p_TRAI_GIAM_ID IN  NUMBER DEFAULT NULL,
    p_XEP_LOAI_NAM IN  NUMBER DEFAULT NULL,
    p_KY_XEP_LOAI  IN  VARCHAR2 DEFAULT NULL,
    p_PHAN_DOI  IN  VARCHAR2 DEFAULT NULL
    
) AS
    v_TRAI_GIAM_ID   NUMBER;
    v_XEP_LOAI_NAM   NUMBER ;
    v_KY_XEP_LOAI   VARCHAR2(200) ;
    v_PHAN_TRAI     VARCHAR2(200) ;
    v_PHAN_DOI     VARCHAR2(200);
    C1 SYS_REFCURSOR;  
BEGIN
    IF p_TRAI_GIAM_ID IS NULL OR p_TRAI_GIAM_ID = '' THEN v_TRAI_GIAM_ID := NULL; ELSE v_TRAI_GIAM_ID := p_TRAI_GIAM_ID; END IF;
    IF p_XEP_LOAI_NAM IS NULL OR p_XEP_LOAI_NAM = '' THEN v_XEP_LOAI_NAM := NULL; ELSE v_XEP_LOAI_NAM := p_XEP_LOAI_NAM; END IF;
    IF p_KY_XEP_LOAI IS NULL OR p_KY_XEP_LOAI = '' THEN v_KY_XEP_LOAI := NULL; ELSE v_KY_XEP_LOAI := p_KY_XEP_LOAI; END IF;
    IF p_PHAN_DOI IS NULL OR p_PHAN_DOI = '' THEN v_PHAN_DOI := NULL; ELSE v_PHAN_DOI := p_PHAN_DOI; END IF;

    OPEN c1 FOR
    -- Chi ti?t theo PHAN_TRAI, KY_XEP_LOAI + 1 dòng T?NG S?
       WITH detail AS (
                SELECT
                TRAI_GIAM_ID, XEP_LOAI_NAM,PHAN_DOI,KY_XEP_LOAI,
                XLCT_TEN AS XEP_LOAI,
				NVL(NAM,  0) AS NAM,
				NVL(NU,   0) AS NU,
				NVL(KHAC, 0) AS KHAC,
				NVL(NAM, 0) + NVL(NU, 0) + NVL(KHAC, 0) AS TONG_SO
            FROM (
                SELECT 
                    TRAI_GIAM_ID, XEP_LOAI_NAM,
                    GIOI_TINH,
                    PHAN_DOI,
                    KY_XEP_LOAI,
                    XLCT_TEN,
                    SUM(GIATRI) AS GIATRI
                FROM (
                    SELECT
                        A.XEP_LOAI_NAM,
                        A.TRAI_GIAM_ID,
                        A.GIOI_TINH,
                        A.PHAN_DOI,
                        A.KY_XEP_LOAI,
                        B.XLCT_TEN,
                        1 AS GIATRI
                    FROM (
                        SELECT
                            XEP_LOAI_NAM,
                            TRAI_GIAM_ID,
                            PHAN_DOI,
                            PHAM_NHAN_ID,
                            GIOI_TINH,
                            KY_XEP_LOAI,
                            TO_NUMBER(XLCT_ID) XLCT_ID
                        FROM (
                            SELECT 
                                B.XEP_LOAI_NAM,
                                A.PHAN_DOI,
                                A.TRAI_GIAM_ID,
                                A.PHAM_NHAN_ID,
                                A.GIOI_TINH,
                                B.xep_loai_quy_i, B.xep_loai_quy_ii,
                                B.xep_loai_quy_iii, B.xep_loai_quy_iv,
                                B.xep_loai_6_thang_dau_nam, B.xep_loai_6_thang_cuoi_nam,
                                B.xep_loai_ca_nam
                            FROM vw_pn_lai_lich_chi_tiet A
                            INNER JOIN XEP_LOAIS B
                                ON A.PHAM_NHAN_ID = B.PHAM_NHAN_ID
                        )
                        UNPIVOT (
                            XLCT_ID FOR KY_XEP_LOAI IN (
                                xep_loai_quy_i            AS 'MA_XEP_LOAI_Q1',
                                xep_loai_quy_ii           AS 'MA_XEP_LOAI_Q2',
                                xep_loai_quy_iii          AS 'MA_XEP_LOAI_Q3',
                                xep_loai_quy_iv           AS 'MA_XEP_LOAI_Q4',
                                xep_loai_6_thang_dau_nam  AS '6_THANG_DAU_NAM',
                                xep_loai_6_thang_cuoi_nam AS '6_THANG_CUOI_NAM',
                                xep_loai_ca_nam           AS 'MA_XEP_LOAI_CA'
                            )
                        )
                        WHERE 
                          (v_TRAI_GIAM_ID IS NULL  OR TRAI_GIAM_ID =  v_TRAI_GIAM_ID) AND
                          (v_XEP_LOAI_NAM IS NULL  OR XEP_LOAI_NAM =  v_XEP_LOAI_NAM) AND
                          (v_KY_XEP_LOAI IS NULL  OR KY_XEP_LOAI =  v_KY_XEP_LOAI) AND
                          (v_PHAN_DOI IS NULL  OR PHAN_DOI =  v_PHAN_DOI)
                          AND EXISTS (
                              SELECT 1
                              FROM MO_KY_XEP_LOAI_CAI_TAO_PN_LAI_LICH mkp
                              JOIN MO_KY_XEP_LOAI_CAI_TAOS mk
                                ON mk.ID = mkp.MO_KY_XEP_LOAI_CAI_TAOS_ID
                               AND mk.IS_DELETED = 0
                              WHERE mkp.PN_LAI_LICHS_ID = PHAM_NHAN_ID
                                AND mk.NAM_XEP_LOAI = XEP_LOAI_NAM
                                AND mk.KY_XEP_LOAI  = KY_XEP_LOAI
                          )
                    ) A
                    INNER JOIN dm_xep_loai_cai_taos B
                    ON A.XLCT_ID = B.ID
                    WHERE B.XLCT_TEN IS NOT NULL
                )
                GROUP BY XEP_LOAI_NAM, GIOI_TINH, KY_XEP_LOAI, XLCT_TEN, TRAI_GIAM_ID, PHAN_DOI
            )
			PIVOT (
			    SUM(GIATRI)
			    FOR GIOI_TINH IN (
			        'Nam'     AS NAM,
			        'N?'      AS NU,
			        'GT khác' AS KHAC
			    )
			))
			SELECT TRAI_GIAM_ID, XEP_LOAI_NAM, PHAN_DOI, KY_XEP_LOAI, XEP_LOAI,
			       NAM, NU, KHAC, TONG_SO
			FROM detail

			UNION ALL

			SELECT TRAI_GIAM_ID, XEP_LOAI_NAM,
			       CAST('T?NG S?' AS NVARCHAR2(100)) AS PHAN_DOI,
			       CAST('T?NG'    AS VARCHAR2(100))  AS KY_XEP_LOAI,
			       CAST('T?NG'    AS NVARCHAR2(100)) AS XEP_LOAI,
			       SUM(NAM), SUM(NU), SUM(KHAC), SUM(TONG_SO)
			FROM detail
			GROUP BY TRAI_GIAM_ID, XEP_LOAI_NAM;


    DBMS_SQL.RETURN_RESULT(C1);


END;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_XEP_LOAI_CHUNG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_XEP_LOAI_CHUNG" (
    p_TRAI_GIAM_ID IN  NUMBER DEFAULT NULL,
    p_XEP_LOAI_NAM IN  NUMBER DEFAULT NULL,
    p_KY_XEP_LOAI  IN  VARCHAR2 DEFAULT NULL,
    p_PHAN_TRAI  IN  VARCHAR2 DEFAULT NULL,
    p_PHAN_DOI  IN  VARCHAR2 DEFAULT NULL
    
) AS
     v_TRAI_GIAM_ID   NUMBER;
    v_XEP_LOAI_NAM   NUMBER ;
    v_KY_XEP_LOAI   VARCHAR2(200) ;
    v_PHAN_TRAI     VARCHAR2(200) ;
    v_PHAN_DOI     VARCHAR2(200);
    C1 SYS_REFCURSOR;  
BEGIN
    IF p_TRAI_GIAM_ID IS NULL OR p_TRAI_GIAM_ID = '' THEN v_TRAI_GIAM_ID := NULL; ELSE v_TRAI_GIAM_ID := p_TRAI_GIAM_ID; END IF;
    IF p_XEP_LOAI_NAM IS NULL OR p_XEP_LOAI_NAM = '' THEN v_XEP_LOAI_NAM := NULL; ELSE v_XEP_LOAI_NAM := p_XEP_LOAI_NAM; END IF;
    IF p_KY_XEP_LOAI IS NULL OR p_KY_XEP_LOAI = '' THEN v_KY_XEP_LOAI := NULL; ELSE v_KY_XEP_LOAI := p_KY_XEP_LOAI; END IF;
    IF p_PHAN_DOI IS NULL OR p_PHAN_DOI = '' THEN v_PHAN_DOI := NULL; ELSE v_PHAN_DOI := p_PHAN_DOI; END IF;
    IF p_PHAN_TRAI IS NULL OR p_PHAN_TRAI = '' THEN v_PHAN_TRAI := NULL; ELSE v_PHAN_TRAI := p_PHAN_TRAI; END IF;

    OPEN c1 FOR
    -- Chi ti?t theo PHAN_TRAI, KY_XEP_LOAI + 1 dòng T?NG S?
        WITH detail AS (
            SELECT
                TRAI_GIAM_ID,XEP_LOAI_NAM,
                PHAN_TRAI,PHAN_DOI,
                KY_XEP_LOAI,
                SUM(TOT)         AS TOT,
                SUM(KHA)         AS KHA,
                SUM(TRUNG_BINH)  AS TRUNG_BINH,
                SUM(KEM)         AS KEM,
                SUM(TOT + KHA + TRUNG_BINH + KEM) AS TONG
            FROM (
                SELECT
                    TRAI_GIAM_ID,XEP_LOAI_NAM,
                    PHAN_TRAI,PHAN_DOI,
                    KY_XEP_LOAI,
                    NVL("T?t", 0)         AS TOT,
                    NVL("Khá", 0)         AS KHA,
                    NVL("Trung bình", 0)  AS TRUNG_BINH,
                    NVL("Kém", 0)         AS KEM
                FROM (
                    SELECT 
                        TRAI_GIAM_ID,XEP_LOAI_NAM,
                        PHAN_TRAI,
                        PHAN_DOI,
                        KY_XEP_LOAI,
                        XLCT_TEN,
                        SUM(GIATRI) AS GIATRI
                    FROM (
                        SELECT
                            A.XEP_LOAI_NAM,
                            A.TRAI_GIAM_ID,
                            A.PHAN_TRAI,
                            A.PHAN_DOI,
                            A.KY_XEP_LOAI,
                            B.XLCT_TEN,
                            1 AS GIATRI
                        FROM (
                            SELECT
                                XEP_LOAI_NAM,
                                TRAI_GIAM_ID,
                                PHAN_DOI,
                                PHAN_TRAI,
                                KY_XEP_LOAI,
                                TO_NUMBER(XLCT_ID) XLCT_ID
                            FROM (
                                SELECT 
                                    A.PHAM_NHAN_ID,
                                    B.XEP_LOAI_NAM,
                                    A.PHAN_DOI,
                                    A.PHAN_TRAI,
                                    A.TRAI_GIAM_ID,
                                    B.xep_loai_quy_i,
                                    B.xep_loai_quy_ii,
                                    B.xep_loai_quy_iii,
                                    B.xep_loai_quy_iv,
                                    B.xep_loai_6_thang_dau_nam,
                                    B.xep_loai_6_thang_cuoi_nam,
                                    B.xep_loai_ca_nam
                                FROM vw_pn_lai_lich_chi_tiet A
                                INNER JOIN XEP_LOAIS B
                                ON A.PHAM_NHAN_ID = B.PHAM_NHAN_ID
                            )
                            UNPIVOT (
                                XLCT_ID FOR KY_XEP_LOAI IN (
                                    xep_loai_quy_i            AS 'MA_XEP_LOAI_Q1',
                                    xep_loai_quy_ii           AS 'MA_XEP_LOAI_Q2',
                                    xep_loai_quy_iii          AS 'MA_XEP_LOAI_Q3',
                                    xep_loai_quy_iv           AS 'MA_XEP_LOAI_Q4',
                                    xep_loai_6_thang_dau_nam  AS '6_THANG_DAU_NAM',
                                    xep_loai_6_thang_cuoi_nam AS '6_THANG_CUOI_NAM',
                                    xep_loai_ca_nam           AS 'MA_XEP_LOAI_CA'
                                )
                            )
                            WHERE
                                (v_TRAI_GIAM_ID IS NULL  OR TRAI_GIAM_ID =  v_TRAI_GIAM_ID) AND
                                (v_XEP_LOAI_NAM IS NULL  OR XEP_LOAI_NAM =  v_XEP_LOAI_NAM) AND
                                (v_KY_XEP_LOAI IS NULL  OR KY_XEP_LOAI =  v_KY_XEP_LOAI) AND
                                (v_PHAN_TRAI IS NULL  OR PHAN_TRAI =  v_PHAN_TRAI) AND
                                (v_PHAN_DOI IS NULL  OR PHAN_DOI =  v_PHAN_DOI)
                                AND EXISTS (
                              SELECT 1
                              FROM MO_KY_XEP_LOAI_CAI_TAO_PN_LAI_LICH mkp
                              JOIN MO_KY_XEP_LOAI_CAI_TAOS mk
                                ON mk.ID = mkp.MO_KY_XEP_LOAI_CAI_TAOS_ID
                               AND mk.IS_DELETED = 0
                              WHERE mkp.PN_LAI_LICHS_ID = PHAM_NHAN_ID
                                AND mk.NAM_XEP_LOAI = XEP_LOAI_NAM
                                AND mk.KY_XEP_LOAI  = KY_XEP_LOAI
                          )
                        ) A
                        INNER JOIN dm_xep_loai_cai_taos B
                        ON A.XLCT_ID = B.ID
                        WHERE B.XLCT_TEN IS NOT NULL
                    )
                    GROUP BY XEP_LOAI_NAM, PHAN_TRAI, KY_XEP_LOAI, XLCT_TEN,TRAI_GIAM_ID,PHAN_DOI
                )
                PIVOT (
                    SUM(GIATRI)
                    FOR XLCT_TEN IN (
                        'T?t'         AS "T?t",
                        'Khá'         AS "Khá",
                        'Trung bình'  AS "Trung bình",
                        'Kém'         AS "Kém"
                    )
                )
            ) a
            GROUP BY PHAN_TRAI, XEP_LOAI_NAM, KY_XEP_LOAI,TRAI_GIAM_ID,PHAN_DOI
        )
        SELECT TRAI_GIAM_ID, XEP_LOAI_NAM, PHAN_TRAI, PHAN_DOI, KY_XEP_LOAI, TOT, KHA, TRUNG_BINH, KEM, TONG
        FROM detail;


    DBMS_SQL.RETURN_RESULT(C1);


END;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_XEP_LOAI_NGHE_NGHIEP
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_XEP_LOAI_NGHE_NGHIEP" (
    p_TRAI_GIAM_ID IN  NUMBER DEFAULT NULL,
    p_XEP_LOAI_NAM IN  NUMBER DEFAULT NULL,
    p_KY_XEP_LOAI  IN  VARCHAR2 DEFAULT NULL,
    p_PHAN_DOI  IN  VARCHAR2 DEFAULT NULL
    
) AS
    v_TRAI_GIAM_ID   NUMBER;
    v_XEP_LOAI_NAM   NUMBER ;
    v_KY_XEP_LOAI   VARCHAR2(200) ;
    v_PHAN_TRAI     VARCHAR2(200) ;
    v_PHAN_DOI     VARCHAR2(200);
    C1 SYS_REFCURSOR;  
BEGIN

    IF p_TRAI_GIAM_ID IS NULL OR p_TRAI_GIAM_ID = '' THEN v_TRAI_GIAM_ID := NULL; ELSE v_TRAI_GIAM_ID := p_TRAI_GIAM_ID; END IF;
    IF p_XEP_LOAI_NAM IS NULL OR p_XEP_LOAI_NAM = '' THEN v_XEP_LOAI_NAM := NULL; ELSE v_XEP_LOAI_NAM := p_XEP_LOAI_NAM; END IF;
    IF p_KY_XEP_LOAI IS NULL OR p_KY_XEP_LOAI = '' THEN v_KY_XEP_LOAI := NULL; ELSE v_KY_XEP_LOAI := p_KY_XEP_LOAI; END IF;
    IF p_PHAN_DOI IS NULL OR p_PHAN_DOI = '' THEN v_PHAN_DOI := NULL; ELSE v_PHAN_DOI := p_PHAN_DOI; END IF;
    OPEN c1 FOR
    -- Chi ti?t theo PHAN_TRAI, KY_XEP_LOAI + 1 dòng T?NG S?


        WITH detail AS (
                    SELECT
                    TRAI_GIAM_ID, XEP_LOAI_NAM,PHAN_DOI,KY_XEP_LOAI,NGHE_NGHIEP,
					NVL(NAM,  0) AS NAM,
					NVL(NU,   0) AS NU,
					NVL(KHAC, 0) AS KHAC,
					NVL(NAM, 0) + NVL(NU, 0) + NVL(KHAC, 0) AS TONG_SO
                FROM (
                    SELECT 
                        TRAI_GIAM_ID, XEP_LOAI_NAM,
                        GIOI_TINH,NGHE_NGHIEP,
                        PHAN_DOI,
                        KY_XEP_LOAI,
                        SUM(GIATRI) AS GIATRI
                    FROM (
                            SELECT
                                XEP_LOAI_NAM,
                                TRAI_GIAM_ID,NGHE_NGHIEP,
                                PHAN_DOI,
                                GIOI_TINH,
                                KY_XEP_LOAI,
                               1 AS GIATRI
                            FROM (
                                SELECT 
                                	DISTINCT A.PHAM_NHAN_ID,
                                    B.XEP_LOAI_NAM,
                                    A.PHAN_DOI,
                                    A.TRAI_GIAM_ID,A.NGHE_NGHIEP,
                                    A.GIOI_TINH,
                                    B.xep_loai_quy_i, B.xep_loai_quy_ii,
                                    B.xep_loai_quy_iii, B.xep_loai_quy_iv,
                                    B.xep_loai_6_thang_dau_nam, B.xep_loai_6_thang_cuoi_nam,
                                    B.xep_loai_ca_nam
                                FROM vw_pn_lai_lich_chi_tiet A
                                INNER JOIN XEP_LOAIS B
                                ON A.PHAM_NHAN_ID = B.PHAM_NHAN_ID
                            )
                            UNPIVOT (
                                XLCT_ID FOR KY_XEP_LOAI IN (
                                    xep_loai_quy_i            AS 'MA_XEP_LOAI_Q1',
                                    xep_loai_quy_ii           AS 'MA_XEP_LOAI_Q2',
                                    xep_loai_quy_iii          AS 'MA_XEP_LOAI_Q3',
                                    xep_loai_quy_iv           AS 'MA_XEP_LOAI_Q4',
                                    xep_loai_6_thang_dau_nam  AS '6_THANG_DAU_NAM',
                                    xep_loai_6_thang_cuoi_nam AS '6_THANG_CUOI_NAM',
                                    xep_loai_ca_nam           AS 'MA_XEP_LOAI_CA'
                                )
                            )
                            WHERE 
                             (v_TRAI_GIAM_ID IS NULL  OR TRAI_GIAM_ID =  v_TRAI_GIAM_ID) AND
                          (v_XEP_LOAI_NAM IS NULL  OR XEP_LOAI_NAM =  v_XEP_LOAI_NAM) AND
                          (v_KY_XEP_LOAI IS NULL  OR KY_XEP_LOAI =  v_KY_XEP_LOAI) AND
                          (v_PHAN_DOI IS NULL  OR PHAN_DOI =  v_PHAN_DOI)
                          AND EXISTS (
                              SELECT 1
                              FROM MO_KY_XEP_LOAI_CAI_TAO_PN_LAI_LICH mkp
                              JOIN MO_KY_XEP_LOAI_CAI_TAOS mk
                                ON mk.ID = mkp.MO_KY_XEP_LOAI_CAI_TAOS_ID
                               AND mk.IS_DELETED = 0
                              WHERE mkp.PN_LAI_LICHS_ID = PHAM_NHAN_ID
                                AND mk.NAM_XEP_LOAI = XEP_LOAI_NAM
                                AND mk.KY_XEP_LOAI  = KY_XEP_LOAI
                          )

                    )
                    GROUP BY XEP_LOAI_NAM, GIOI_TINH, KY_XEP_LOAI, TRAI_GIAM_ID, PHAN_DOI,NGHE_NGHIEP
                )
				PIVOT (
				    SUM(GIATRI)
				    FOR GIOI_TINH IN (
				        'Nam'     AS NAM,
				        'N?'      AS NU,
				        'GT khác' AS KHAC
				    )
				)
        )
			SELECT TRAI_GIAM_ID, XEP_LOAI_NAM, PHAN_DOI, KY_XEP_LOAI, NGHE_NGHIEP,
			       NAM, NU, KHAC, TONG_SO
			FROM detail

			UNION ALL

			SELECT TRAI_GIAM_ID, XEP_LOAI_NAM,
			       CAST('T?NG S?' AS NVARCHAR2(100)) AS PHAN_DOI,
			       CAST('T?NG'    AS VARCHAR2(100))  AS KY_XEP_LOAI,
			       CAST('T?NG'    AS NVARCHAR2(100)) AS NGHE_NGHIEP,
			       SUM(NAM), SUM(NU), SUM(KHAC), SUM(TONG_SO)
			FROM detail
			GROUP BY TRAI_GIAM_ID, XEP_LOAI_NAM;




    DBMS_SQL.RETURN_RESULT(C1);


END;





/
