                    PHAN_TRAI,
                    KY_XEP_LOAI,
                    NVL("T?t", 0)         AS TOT,
                    NVL("Khá", 0)         AS KHA,
                    NVL("Trung bình", 0)  AS TRUNG_BINH,
                    NVL("Kém", 0)         AS KEM
                FROM (
                    SELECT 
                        TRAI_GIAM_ID,XEP_LOAI_NAM,
                        PHAN_TRAI,
                        KY_XEP_LOAI,
                        XLCT_TEN,
                        SUM(GIATRI) AS GIATRI
                    FROM (
                        SELECT
                            A.XEP_LOAI_NAM,
                            A.TRAI_GIAM_ID,
                            A.PHAN_TRAI,
                            A.KY_XEP_LOAI,
                            B.XLCT_TEN,
                            1 AS GIATRI
                        FROM (
                            SELECT
                                XEP_LOAI_NAM,
                                TRAI_GIAM_ID,
                                PHAN_TRAI,
                                KY_XEP_LOAI,
                                TO_NUMBER(XLCT_ID) XLCT_ID
                            FROM (
                                SELECT 
                                A.PHAM_NHAN_ID,
                                    B.XEP_LOAI_NAM,
                                    A.PHAN_TRAI,
                                    A.TRAI_GIAM_ID,
                                    B.xep_loai_quy_i,
                                    B.xep_loai_quy_ii,
                                    B.xep_loai_quy_iii,
                                    B.xep_loai_quy_iv,
                                    B.xep_loai_6_thang_dau_nam,
                                    B.xep_loai_6_thang_cuoi_nam,
                                    B.xep_loai_ca_nam
                                FROM vw_pn_lai_lich_chi_tiet A
                                INNER JOIN XEP_LOAIS B
                                ON A.PHAM_NHAN_ID = B.PHAM_NHAN_ID     
                            )
                            UNPIVOT (
                                XLCT_ID FOR KY_XEP_LOAI IN (
                                    xep_loai_quy_i            AS 'MA_XEP_LOAI_Q1',
                                    xep_loai_quy_ii           AS 'MA_XEP_LOAI_Q2',
                                    xep_loai_quy_iii          AS 'MA_XEP_LOAI_Q3',
                                    xep_loai_quy_iv           AS 'MA_XEP_LOAI_Q4'
                                )
                            )
                         WHERE 
                                (v_TRAI_GIAM_ID IS NULL  OR TRAI_GIAM_ID =  v_TRAI_GIAM_ID) AND
                                (v_XEP_LOAI_NAM IS NULL  OR XEP_LOAI_NAM =  v_XEP_LOAI_NAM) AND
                                (v_KY_XEP_LOAI IS NULL  OR KY_XEP_LOAI =  v_KY_XEP_LOAI) AND
                                (v_PHAN_TRAI IS NULL  OR PHAN_TRAI =  v_PHAN_TRAI)
                                AND EXISTS (
                              SELECT 1
                              FROM MO_KY_XEP_LOAI_CAI_TAO_PN_LAI_LICH mkp
                              JOIN MO_KY_XEP_LOAI_CAI_TAOS mk
                                ON mk.ID = mkp.MO_KY_XEP_LOAI_CAI_TAOS_ID
                               AND mk.IS_DELETED = 0
                              WHERE mkp.PN_LAI_LICHS_ID = PHAM_NHAN_ID
                                AND mk.NAM_XEP_LOAI = XEP_LOAI_NAM
                                AND mk.KY_XEP_LOAI  = KY_XEP_LOAI
                          )
                        ) A
                        INNER JOIN dm_xep_loai_cai_taos B
                        ON A.XLCT_ID = B.ID
                        WHERE B.XLCT_TEN IS NOT NULL
                    )
                    GROUP BY XEP_LOAI_NAM, PHAN_TRAI, KY_XEP_LOAI, XLCT_TEN,TRAI_GIAM_ID
                )
                PIVOT (
                    SUM(GIATRI)
                    FOR XLCT_TEN IN (
                        'T?t'         AS "T?t",
                        'Khá'         AS "Khá",
                        'Trung bình'  AS "Trung bình",
                        'Kém'         AS "Kém"
                    )
                )
            ) a
            GROUP BY PHAN_TRAI, XEP_LOAI_NAM, KY_XEP_LOAI,TRAI_GIAM_ID
        )
        SELECT TRAI_GIAM_ID,XEP_LOAI_NAM, PHAN_TRAI AS PHAN_DOI, KY_XEP_LOAI, TOT, KHA, TRUNG_BINH, KEM, TONG
        FROM detail
		UNION ALL
		SELECT
		    NULL                                    AS TRAI_GIAM_ID,
		    NULL                                    AS XEP_LOAI_NAM,
		    CAST(u'T\1ed4NG S\1ed0' AS NVARCHAR2(100))     AS PHAN_DOI,
		    CAST(u'T\1ed4NG' AS VARCHAR2(100))          AS KY_XEP_LOAI,
		    SUM(TOT)                                AS TOT,
		    SUM(KHA)                                AS KHA,
		    SUM(TRUNG_BINH)                         AS TRUNG_BINH,
		    SUM(KEM)                                AS KEM,
		    SUM(TONG)                               AS TONG
		FROM detail;


    DBMS_SQL.RETURN_RESULT(C1);


END;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_XEP_LOAI_THEO_PHAN_TRAI_PHAN_DOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_XEP_LOAI_THEO_PHAN_TRAI_PHAN_DOI" (
    p_TRAI_GIAM_ID IN NUMBER  DEFAULT NULL,
    p_XEP_LOAI_NAM IN NUMBER  DEFAULT NULL,
    p_KY_XEP_LOAI  IN VARCHAR2 DEFAULT NULL,
    p_PHAN_TRAI    IN VARCHAR2 DEFAULT NULL,
    p_PHAN_DOI     IN VARCHAR2 DEFAULT NULL
)
AS
    v_TRAI_GIAM_ID NUMBER;
    v_XEP_LOAI_NAM NUMBER;
    v_KY_XEP_LOAI  VARCHAR2(200);
    v_PHAN_TRAI    VARCHAR2(200);
    v_PHAN_DOI     VARCHAR2(200);
    C1 SYS_REFCURSOR;
BEGIN
    IF p_TRAI_GIAM_ID IS NULL OR p_TRAI_GIAM_ID = '' THEN v_TRAI_GIAM_ID := NULL; ELSE v_TRAI_GIAM_ID := p_TRAI_GIAM_ID; END IF;
    IF p_XEP_LOAI_NAM IS NULL OR p_XEP_LOAI_NAM = '' THEN v_XEP_LOAI_NAM := NULL; ELSE v_XEP_LOAI_NAM := p_XEP_LOAI_NAM; END IF;
    IF p_KY_XEP_LOAI  IS NULL OR p_KY_XEP_LOAI  = '' THEN v_KY_XEP_LOAI  := 'MA_XEP_LOAI_CA'; ELSE v_KY_XEP_LOAI  := p_KY_XEP_LOAI;  END IF;
    IF p_PHAN_TRAI    IS NULL OR p_PHAN_TRAI    = '' THEN v_PHAN_TRAI    := NULL; ELSE v_PHAN_TRAI    := p_PHAN_TRAI;    END IF;
    IF p_PHAN_DOI     IS NULL OR p_PHAN_DOI     = '' THEN v_PHAN_DOI     := NULL; ELSE v_PHAN_DOI     := p_PHAN_DOI;     END IF;

    OPEN C1 FOR
    WITH base AS (
        SELECT
        	A.PHAM_NHAN_ID,
            A.TRAI_GIAM_ID,
            B.XEP_LOAI_NAM,
            A.PHAN_TRAI,
            A.PHAN_DOI,
            B.xep_loai_quy_i,
            B.xep_loai_quy_ii,
            B.xep_loai_quy_iii,
            B.xep_loai_quy_iv,
            B.xep_loai_6_thang_dau_nam,
            B.xep_loai_6_thang_cuoi_nam,
            B.xep_loai_ca_nam
        FROM vw_pn_lai_lich_chi_tiet A
        INNER JOIN XEP_LOAIS B ON A.PHAM_NHAN_ID = B.PHAM_NHAN_ID
        WHERE (v_TRAI_GIAM_ID IS NULL OR A.TRAI_GIAM_ID  = v_TRAI_GIAM_ID)
          AND (v_XEP_LOAI_NAM IS NULL OR B.XEP_LOAI_NAM  = v_XEP_LOAI_NAM)
          AND (v_PHAN_TRAI    IS NULL OR A.PHAN_TRAI      = v_PHAN_TRAI)
          AND (v_PHAN_DOI     IS NULL OR A.PHAN_DOI       = v_PHAN_DOI)
          AND EXISTS (
                              SELECT 1
                              FROM MO_KY_XEP_LOAI_CAI_TAO_PN_LAI_LICH mkp
                              JOIN MO_KY_XEP_LOAI_CAI_TAOS mk
                                ON mk.ID = mkp.MO_KY_XEP_LOAI_CAI_TAOS_ID
                               AND mk.IS_DELETED = 0
                              WHERE mkp.PN_LAI_LICHS_ID = A.PHAM_NHAN_ID
                                AND mk.NAM_XEP_LOAI = XEP_LOAI_NAM
                                AND mk.KY_XEP_LOAI  = KY_XEP_LOAI
                          )
    ),
    unpivoted AS (
        SELECT
            TRAI_GIAM_ID, XEP_LOAI_NAM, PHAN_TRAI, PHAN_DOI,
            KY_XEP_LOAI,
            TO_NUMBER(XLCT_ID) AS XLCT_ID
        FROM base
        UNPIVOT (
            XLCT_ID FOR KY_XEP_LOAI IN (
                xep_loai_quy_i            AS 'MA_XEP_LOAI_Q1',
                xep_loai_quy_ii           AS 'MA_XEP_LOAI_Q2',
                xep_loai_quy_iii          AS 'MA_XEP_LOAI_Q3',
                xep_loai_quy_iv           AS 'MA_XEP_LOAI_Q4',
                xep_loai_6_thang_dau_nam  AS '6_THANG_DAU_NAM',
                xep_loai_6_thang_cuoi_nam AS '6_THANG_CUOI_NAM',
                xep_loai_ca_nam           AS 'MA_XEP_LOAI_CA'
            )
        )
        WHERE (v_KY_XEP_LOAI IS NULL OR KY_XEP_LOAI = v_KY_XEP_LOAI)
    ),
    joined AS (
        SELECT
            u.TRAI_GIAM_ID, u.XEP_LOAI_NAM,
            u.PHAN_TRAI, u.PHAN_DOI,
            u.KY_XEP_LOAI,
            xl.XLCT_TEN
        FROM unpivoted u
        INNER JOIN dm_xep_loai_cai_taos xl ON u.XLCT_ID = xl.ID
        WHERE xl.XLCT_TEN IS NOT NULL
    ),
    -- ??m theo t?ng phân ??i
    detail AS (
        SELECT
            TRAI_GIAM_ID, XEP_LOAI_NAM, PHAN_TRAI, PHAN_DOI, KY_XEP_LOAI,
            SUM(CASE WHEN XLCT_TEN = 'T?t'        THEN 1 ELSE 0 END) AS TOT,
            SUM(CASE WHEN XLCT_TEN = 'Khá'        THEN 1 ELSE 0 END) AS KHA,
            SUM(CASE WHEN XLCT_TEN = 'Trung bình' THEN 1 ELSE 0 END) AS TRUNG_BINH,
            SUM(CASE WHEN XLCT_TEN = 'Kém'        THEN 1 ELSE 0 END) AS KEM,
            COUNT(*)                                                   AS TONG
        FROM joined
        GROUP BY TRAI_GIAM_ID, XEP_LOAI_NAM, PHAN_TRAI, PHAN_DOI, KY_XEP_LOAI
    ),
    -- T?ng theo phân tr?i
    summary_trai AS (
        SELECT
            TRAI_GIAM_ID, XEP_LOAI_NAM, PHAN_TRAI, KY_XEP_LOAI,
            SUM(TOT)        AS TOT,
            SUM(KHA)        AS KHA,
            SUM(TRUNG_BINH) AS TRUNG_BINH,
            SUM(KEM)        AS KEM,
            SUM(TONG)       AS TONG
        FROM detail
        GROUP BY TRAI_GIAM_ID, XEP_LOAI_NAM, PHAN_TRAI, KY_XEP_LOAI
    ),
    -- T?ng toàn b?
    summary_all AS (
        SELECT
            TRAI_GIAM_ID, XEP_LOAI_NAM, KY_XEP_LOAI,
            SUM(TOT)        AS TOT,
            SUM(KHA)        AS KHA,
            SUM(TRUNG_BINH) AS TRUNG_BINH,
            SUM(KEM)        AS KEM,
            SUM(TONG)       AS TONG
        FROM detail
        GROUP BY TRAI_GIAM_ID, XEP_LOAI_NAM, KY_XEP_LOAI
    ),
    -- ?ánh s? th? t? La Mã cho phân tr?i
    trai_rank AS (
        SELECT PHAN_TRAI,
               DENSE_RANK() OVER (ORDER BY PHAN_TRAI) AS TRAI_SO
        FROM detail
        GROUP BY PHAN_TRAI
    ),
    doi_rank AS (
        SELECT PHAN_TRAI, PHAN_DOI,
               ROW_NUMBER() OVER (PARTITION BY PHAN_TRAI ORDER BY PHAN_DOI) AS DOI_SO
        FROM detail
        GROUP BY PHAN_TRAI, PHAN_DOI
    )
    -- Dòng phân tr?i (header)
    SELECT
        1                               AS SORT_TYPE,  -- ?? sort: 1=trai, 2=doi, 3=total
        tr.TRAI_SO                      AS SORT_KEY,
        0                               AS SORT_KEY2,
        CASE tr.TRAI_SO
            WHEN 1  THEN 'I'
            WHEN 2  THEN 'II'
            WHEN 3  THEN 'III'
            WHEN 4  THEN 'IV'
            WHEN 5  THEN 'V'
            WHEN 6  THEN 'VI'
            WHEN 7  THEN 'VII'
            WHEN 8  THEN 'VIII'
            WHEN 9  THEN 'IX'
            WHEN 10 THEN 'X'
            ELSE TO_CHAR(tr.TRAI_SO)
        END                             AS "Stt",
        st.PHAN_TRAI                    AS "PhanDoi",
        st.TOT                          AS "Tot",
        st.KHA                          AS "Kha",
        st.TRUNG_BINH                   AS "TrungBinh",
        st.KEM                          AS "Kem",
        st.TONG                         AS "Tong"
    FROM summary_trai st
    JOIN trai_rank tr ON st.PHAN_TRAI = tr.PHAN_TRAI

    UNION ALL

    -- Dòng phân ??i (chi ti?t)
    SELECT
        2                               AS SORT_TYPE,
        tr.TRAI_SO                      AS SORT_KEY,
        dr.DOI_SO                       AS SORT_KEY2,
        TO_CHAR(dr.DOI_SO)              AS "Stt",
        d.PHAN_DOI || ', ' || d.PHAN_TRAI AS "PhanDoi",
        d.TOT                           AS "Tot",
        d.KHA                           AS "Kha",
        d.TRUNG_BINH                    AS "TrungBinh",
        d.KEM                           AS "Kem",
        d.TONG                          AS "Tong"
    FROM detail d
    JOIN trai_rank tr ON d.PHAN_TRAI = tr.PHAN_TRAI
    JOIN doi_rank  dr ON d.PHAN_TRAI = dr.PHAN_TRAI AND d.PHAN_DOI = dr.PHAN_DOI

    UNION ALL

    -- Dòng t?ng s?
    SELECT 
        3                               AS SORT_TYPE,
        9999                            AS SORT_KEY,
        9999                            AS SORT_KEY2,
        ''                              AS "Stt",

        CAST('T?NG S?' AS NVARCHAR2(100)) AS "PhanDoi",
        SUM(TOT)                        AS "Tot",
        SUM(KHA)                        AS "Kha",
        SUM(TRUNG_BINH)                 AS "TrungBinh",
        SUM(KEM)                        AS "Kem",
        SUM(TONG)                       AS "Tong"
    FROM summary_all

    ORDER BY SORT_KEY, SORT_TYPE, SORT_KEY2;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_TK_XEP_LOAI_THEO_PHAN_TRAI_PHAN_DOI;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TK_XEP_LOAI_TOI_DANH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TK_XEP_LOAI_TOI_DANH" (
    p_TRAI_GIAM_ID IN  NUMBER DEFAULT NULL,
    p_XEP_LOAI_NAM IN  NUMBER DEFAULT NULL,
    p_KY_XEP_LOAI  IN  VARCHAR2 DEFAULT NULL,
    p_PHAN_DOI  IN  VARCHAR2 DEFAULT NULL
    
) AS
    v_TRAI_GIAM_ID   NUMBER;
    v_XEP_LOAI_NAM   NUMBER ;
    v_KY_XEP_LOAI   VARCHAR2(200) ;
    v_PHAN_TRAI     VARCHAR2(200) ;
    v_PHAN_DOI     VARCHAR2(200);
    C1 SYS_REFCURSOR;  
BEGIN

    IF p_TRAI_GIAM_ID IS NULL OR p_TRAI_GIAM_ID = '' THEN v_TRAI_GIAM_ID := NULL; ELSE v_TRAI_GIAM_ID := p_TRAI_GIAM_ID; END IF;
    IF p_XEP_LOAI_NAM IS NULL OR p_XEP_LOAI_NAM = '' THEN v_XEP_LOAI_NAM := NULL; ELSE v_XEP_LOAI_NAM := p_XEP_LOAI_NAM; END IF;
    IF p_KY_XEP_LOAI IS NULL OR p_KY_XEP_LOAI = '' THEN v_KY_XEP_LOAI := NULL; ELSE v_KY_XEP_LOAI := p_KY_XEP_LOAI; END IF;
    IF p_PHAN_DOI IS NULL OR p_PHAN_DOI = '' THEN v_PHAN_DOI := NULL; ELSE v_PHAN_DOI := p_PHAN_DOI; END IF;
    OPEN c1 FOR
    -- Chi ti?t theo PHAN_TRAI, KY_XEP_LOAI + 1 dòng T?NG S?


            WITH detail AS (
                        SELECT
                        TRAI_GIAM_ID, XEP_LOAI_NAM,PHAN_DOI,KY_XEP_LOAI,TOI_DANH,
						NVL(NAM,  0) AS NAM,
						NVL(NU,   0) AS NU,
						NVL(KHAC, 0) AS KHAC,
						NVL(NAM, 0) + NVL(NU, 0) + NVL(KHAC, 0) AS TONG_SO
                    FROM (
                        SELECT 
                            TRAI_GIAM_ID, XEP_LOAI_NAM,
                            GIOI_TINH,TOI_DANH,
                            PHAN_DOI,
                            KY_XEP_LOAI,
                            SUM(GIATRI) AS GIATRI
                        FROM (
                                SELECT
                                    XEP_LOAI_NAM,
                                    TRAI_GIAM_ID,TOI_DANH,
                                    PHAN_DOI,
                                    GIOI_TINH,
                                    KY_XEP_LOAI,
                                   1 AS GIATRI
                                 FROM (
                                    SELECT 
                                        A.PHAM_NHAN_ID,
                                        B.XEP_LOAI_NAM,
                                        A.PHAN_DOI,
                                        A.TRAI_GIAM_ID,A.TOI_DANH,
                                        A.GIOI_TINH,
                                        B.xep_loai_quy_i, B.xep_loai_quy_ii,
                                        B.xep_loai_quy_iii, B.xep_loai_quy_iv,
                                        B.xep_loai_6_thang_dau_nam, B.xep_loai_6_thang_cuoi_nam,
                                        B.xep_loai_ca_nam
                                    FROM vw_pn_lai_lich_chi_tiet A
                                    INNER JOIN XEP_LOAIS B
                                    ON A.PHAM_NHAN_ID = B.PHAM_NHAN_ID
                                )
                                UNPIVOT (
                                    XLCT_ID FOR KY_XEP_LOAI IN (
                                        xep_loai_quy_i            AS 'MA_XEP_LOAI_Q1',
                                        xep_loai_quy_ii           AS 'MA_XEP_LOAI_Q2',
                                        xep_loai_quy_iii          AS 'MA_XEP_LOAI_Q3',
                                        xep_loai_quy_iv           AS 'MA_XEP_LOAI_Q4',
                                        xep_loai_6_thang_dau_nam  AS '6_THANG_DAU_NAM',
                                        xep_loai_6_thang_cuoi_nam AS '6_THANG_CUOI_NAM',
                                        xep_loai_ca_nam           AS 'MA_XEP_LOAI_CA'
                                    )
                                )
                                WHERE 
                                (v_TRAI_GIAM_ID IS NULL  OR TRAI_GIAM_ID =  v_TRAI_GIAM_ID) AND
                                (v_XEP_LOAI_NAM IS NULL  OR XEP_LOAI_NAM =  v_XEP_LOAI_NAM) AND
                                (v_KY_XEP_LOAI IS NULL  OR KY_XEP_LOAI =  v_KY_XEP_LOAI) AND
                                (v_PHAN_DOI IS NULL  OR PHAN_DOI =  v_PHAN_DOI)
                                 AND EXISTS (
                              SELECT 1
                              FROM MO_KY_XEP_LOAI_CAI_TAO_PN_LAI_LICH mkp
                              JOIN MO_KY_XEP_LOAI_CAI_TAOS mk
                                ON mk.ID = mkp.MO_KY_XEP_LOAI_CAI_TAOS_ID
                               AND mk.IS_DELETED = 0
                              WHERE mkp.PN_LAI_LICHS_ID = PHAM_NHAN_ID
                                AND mk.NAM_XEP_LOAI = XEP_LOAI_NAM
                                AND mk.KY_XEP_LOAI  = KY_XEP_LOAI
                          )

                        )
                        GROUP BY XEP_LOAI_NAM, GIOI_TINH, KY_XEP_LOAI, TRAI_GIAM_ID, PHAN_DOI,TOI_DANH
                    )
					PIVOT (
					    SUM(GIATRI)
					    FOR GIOI_TINH IN (
					        'Nam'     AS NAM,
					        'N?'      AS NU,
					        'GT khác' AS KHAC
					    )
					)
            )
				-- SELECT detail
				SELECT TRAI_GIAM_ID, XEP_LOAI_NAM, PHAN_DOI, KY_XEP_LOAI, TOI_DANH,
				       NAM, NU, KHAC, TONG_SO
				FROM detail

				UNION ALL

				SELECT TRAI_GIAM_ID, XEP_LOAI_NAM,
				       CAST('T?NG S?' AS NVARCHAR2(1000)) AS PHAN_DOI,
				       CAST('T?NG'    AS VARCHAR2(1000))  AS KY_XEP_LOAI,
				       CAST('T?NG' AS NVARCHAR2(1000)) AS TOI_DANH,
				       SUM(NAM), SUM(NU), SUM(KHAC), SUM(TONG_SO)
				FROM detail
				GROUP BY TRAI_GIAM_ID, XEP_LOAI_NAM;



    DBMS_SQL.RETURN_RESULT(C1);


END;





/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TRICH_XUAT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TRICH_XUAT" (
    p_PHAM_NHAN_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        tx.PHAM_NHAN_ID,
        tx.TX_SO_LENH  AS "SoLenh",
        tx.TX_NGAY_RA_LENH  AS "NgayRaLenh",
        dmtg.MTG_TITLE   AS "ThoiHan",
        tx.TX_TU_NGAY  AS "TuNgay",
        dldtx.LDTX_TEN   AS "LyDo",
        tx.TX_NGAY_TRA  AS "NgayVe"
    FROM TRICH_XUATS tx 
    LEFT JOIN DM_LY_DO_TRICH_XUATS dldtx ON tx.TX_LY_DO_ID = dldtx.ID 
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON tx.TX_THOI_HAN_ID = dmtg.ID
    WHERE tx.PHAM_NHAN_ID = p_PHAM_NHAN_ID
	AND tx.IS_DELETED = 0;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_TRICH_XUAT;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TRICH_XUAT_IN_PHIEU
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TRICH_XUAT_IN_PHIEU" (
    p_PHAM_NHAN_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH 
     TRICH_AGG AS (
            SELECT tx.PHAM_NHAN_ID AS PN_ID,
                   LISTAGG(NVL(TO_CHAR(tx.TX_NGAY_TRICH_XUAT, 'DD/MM/YYYY'), '') || NVL2(tx.TX_NGAY_TRA, ' - ' || TO_CHAR(tx.TX_NGAY_TRA, 'DD/MM/YYYY'), '') || ' | ' || NVL(dvhc.TTP_TEN, ''),
                           CHR(10)) WITHIN GROUP (ORDER BY tx.TX_NGAY_TRICH_XUAT NULLS LAST) AS TRICH_XUAT
            FROM TRICH_XUATS tx
            LEFT JOIN DM_TINH_THANH_PHO dvhc ON tx.TX_DIA_PHUONG_VE_ID = dvhc.ID AND NVL(dvhc.IS_DELETED, 0) = 0
            WHERE tx.PHAM_NHAN_ID = p_PHAM_NHAN_ID AND NVL(tx.IS_DELETED, 0) = 0
            GROUP BY tx.PHAM_NHAN_ID
        )
    SELECT 
        tx.PHAM_NHAN_ID,
        tx.TX_SO_LENH  AS "SoLenh",
        tx.TX_NGAY_RA_LENH  AS "NgayRaLenh",
        dmtg.MTG_TITLE   AS "ThoiHan",
        tx.TX_TU_NGAY  AS "TuNgay",
        dldtx.LDTX_TEN   AS "LyDo",
        tx.TX_NGAY_TRA  AS "NgayVe",
        tch.TRICH_XUAT AS "TrichXuat"
    FROM TRICH_XUATS tx 
    LEFT JOIN DM_LY_DO_TRICH_XUATS dldtx ON tx.TX_LY_DO_ID = dldtx.ID 
    LEFT JOIN DM_MA_THOI_GIANS dmtg ON tx.TX_THOI_HAN_ID = dmtg.ID
    LEFT JOIN TRICH_AGG tch ON tch.PN_ID = tx.PHAM_NHAN_ID
    WHERE tx.PHAM_NHAN_ID = p_PHAM_NHAN_ID;
 DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_TRICH_XUAT_IN_PHIEU;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TRICH_XUAT_PT47
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TRICH_XUAT_PT47" (
--    p_pham_nhan_id    IN NUMBER,
--    p_ngay_trich_xuat IN VARCHAR2
    p_trich_xuat_id IN NVARCHAR2
)
AS
    c1 SYS_REFCURSOR;
--    v_ngay_trich_xuat DATE;
BEGIN
--    IF p_ngay_trich_xuat IS NULL OR TRIM(p_ngay_trich_xuat) = '' THEN
--        RAISE_APPLICATION_ERROR(-20001, 'p_ngay_trich_xuat khong duoc de trong');
--    END IF;
--
--    v_ngay_trich_xuat := TO_DATE(TRIM(p_ngay_trich_xuat), 'DD/MM/YYYY');

    OPEN c1 FOR
        WITH vw_one AS (
            SELECT v.*
            FROM qlpn.vw_pn_lai_lich_chi_tiet v
            WHERE NVL(v.is_deleted, 0) = 0
--              AND v.pham_nhan_id = p_pham_nhan_id
        )
        SELECT
            v.HO_TEN AS HO_TEN,
            v.GIOI_TINH AS GIOI_TINH,
            v.NGAY_SINH AS NGAY_SINH,
            v.TEN_KHAC AS TEN_KHAC,
            v.NGUYEN_QUAN AS QUE_QUAN,
            v.DAN_TOC AS DAN_TOC,
            v.QUOC_TICH AS QUOC_TICH,
            NVL(v.NOI_THUONG_TRU_DAY_DU, v.DIA_CHI_THUONG_TRU) AS NOI_THUONG_TRU,
            v.TOI_DANH AS TOI_DANH,
            TO_NCHAR(v.NGAY_BAT_AN_PHAT, 'DD/MM/YYYY') AS NGAY_BAT,
            v.AN_PHAT AS AN_PHAT,
            TO_NCHAR(v.NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
            dx.XEP_LOAI_TEXT AS XEP_LOAI_CHA,
            v.NHAN_THAN AS NHAN_THAN,
            v.PHAN_LOAI_GIAM_GIU AS PHAN_LOAI_PHAM_NHAN,
            dv_dn.cq_ten AS DON_VI_DE_NGHI,
            dp_dn.ttp_ten AS DIA_PHUONG_DE_NGHI,
            dv_ve.ttp_ten AS DEN,
            ldtx.ldtx_ten AS DE
        FROM qlpn.trich_xuats tx
        INNER JOIN vw_one v
                ON v.pham_nhan_id = tx.pham_nhan_id
        LEFT JOIN qlpn.dm_co_quans dv_dn
               ON dv_dn.id = tx.tx_don_vi_de_nghi_id
              AND NVL(dv_dn.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_tinh_thanh_pho dp_dn
               ON dp_dn.id = tx.tx_dia_phuong_de_nghi_id
              AND NVL(dp_dn.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_ly_do_trich_xuats ldtx
               ON ldtx.id = tx.tx_ly_do_id
              AND NVL(ldtx.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_tinh_thanh_pho dv_ve
               ON dv_ve.id = tx.tx_dia_phuong_ve_id
              AND NVL(dv_ve.is_deleted, 0) = 0
        LEFT JOIN qlpn.dx_display dx
               ON dx.pn_lai_lich_id = tx.pham_nhan_id
        WHERE NVL(tx.is_deleted, 0) = 0
--          AND tx.pham_nhan_id = p_pham_nhan_id
          AND tx.tx_loai_lenh_id = 1
          AND tx.id = p_trich_xuat_id
--          AND TRUNC(tx.tx_ngay_trich_xuat) = TRUNC(v_ngay_trich_xuat)
--        ORDER BY tx.tx_ngay_ra_lenh, tx.id
--        FETCH FIRST 1 ROW ONLY
        ;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_TRICH_XUAT_PT47: ' || SQLERRM);
END SP_GET_TRICH_XUAT_PT47;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TRICH_XUAT_PT73
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TRICH_XUAT_PT73" (
--    p_pham_nhan_id  IN NUMBER,
    p_trich_xuat_id IN NVARCHAR2   -- ID b?ng TRICH_XUATS, nh?n chu?i và convert 1 l?n sang NUMBER
)
AS
    c1 SYS_REFCURSOR;
    v_trich_xuat_id NUMBER;
BEGIN
--    IF p_pham_nhan_id IS NULL THEN
--        RAISE_APPLICATION_ERROR(-20001, 'p_pham_nhan_id khong duoc de trong');
--    END IF;

    v_trich_xuat_id := TO_NUMBER(TRIM(p_trich_xuat_id) DEFAULT NULL ON CONVERSION ERROR);
    IF v_trich_xuat_id IS NULL THEN
        RAISE_APPLICATION_ERROR(-20001, 'p_trich_xuat_id khong duoc de trong hoac khong phai so hop le');
    END IF;

    OPEN c1 FOR
        -- Tra c?u th?ng theo PK; gi? ?i?u ki?n loai_lenh = 1 + pham_nhan_id
        -- ?? ID sai lo?i l?nh/sai ph?m nhân tr? r?ng thay vì in nh?m phi?u
        WITH tx_one AS (
            SELECT tx.*
            FROM qlpn.trich_xuats tx
            WHERE NVL(tx.is_deleted, 0) = 0
              AND tx.tx_loai_lenh_id = 1
--              AND tx.pham_nhan_id = p_pham_nhan_id
              AND tx.id = v_trich_xuat_id
        )
        SELECT
            v.ho_ten AS HO_TEN,
            v.gioi_tinh AS GIOI_TINH,
            v.ngay_sinh AS NGAY_SINH,
            v.ten_khac AS HO_TEN_KHAC,
            NVL(v.noi_thuong_tru_day_du, v.dia_chi_thuong_tru) AS NOI_THUONG_TRU,
            v.toi_danh AS TOI_DANH,
            TO_CHAR(CAST(v.ngay_bat_an_phat AS DATE), 'DD/MM/YYYY') AS NGAY_BAT,
            v.an_phat AS AN_PHAT,
            v.so_ban_an AS SO_BAN_AN,
            TO_CHAR(CAST(v.ngay_ban_an AS DATE), 'DD/MM/YYYY') AS NGAY_BAN_AN,
            v.toa_xu_ten AS TOA_XU,
            v.toa_xu_dia_phuong AS DIA_PHUONG_XU,
            v.so_qd_tha AS SO_QD_THA,
            TO_CHAR(CAST(v.ngay_qd_tha AS DATE), 'DD/MM/YYYY') AS NGAY_QD_THA,
            v.co_quan_qd_tha AS TOA_QD_THA,
            v.toa_qd_tha_dia_phuong AS DIA_PHUONG_QD_THA,
            v.trai_giam AS TU,
            TRIM(NVL(CAST(cq_nhan.cq_ten AS NVARCHAR2(500)), u'') ||
                 CASE
                     WHEN ttp_ve.ttp_ten IS NOT NULL
                     THEN u' ' || CAST(ttp_ve.ttp_ten AS NVARCHAR2(500))
                     ELSE u''
                 END) AS DEN,
            cq_dn.cq_ten AS CO_QUAN_DE_NGHI_TX,
            cq_nhan.cq_ten AS CO_QUAN_NHAN_PHAM_NHAN,
            ttp_ve.ttp_ten AS DIA_PHUONG_TRICH_XUAT_DEN,
            mtg.mtg_title AS THOI_HAN,
            TO_CHAR(CAST(tx.tx_ngay_trich_xuat AS DATE), 'DD/MM/YYYY') AS TU_NGAY,
            TO_CHAR(CAST(tx.tx_ngay_tra AS DATE), 'DD/MM/YYYY') AS DEN_NGAY,
            ldtx.ldtx_ten AS MUC_DICH_TRICH_XUAT
        FROM tx_one tx
        -- Join theo h?ng s? p_pham_nhan_id ?? optimizer ??y predicate vào view lai l?ch
        INNER JOIN qlpn.vw_pn_lai_lich_chi_tiet v
                ON v.pham_nhan_id = tx.pham_nhan_id
               AND NVL(v.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_co_quans cq_dn
               ON cq_dn.id = tx.tx_don_vi_de_nghi_id
              AND NVL(cq_dn.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_co_quans cq_nhan
               ON cq_nhan.id = tx.tx_don_vi_ve_id
              AND NVL(cq_nhan.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_tinh_thanh_pho ttp_ve
               ON ttp_ve.id = tx.tx_dia_phuong_ve_id
              AND NVL(ttp_ve.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_ma_thoi_gians mtg
               ON mtg.id = tx.tx_thoi_han_id
              AND NVL(mtg.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_ly_do_trich_xuats ldtx
               ON ldtx.id = tx.tx_ly_do_id
              AND NVL(ldtx.is_deleted, 0) = 0
        ;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_TRICH_XUAT_PT73: ' || SQLERRM);
END SP_GET_TRICH_XUAT_PT73;


/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TRICH_XUAT_TX
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TRICH_XUAT_TX" (
    p_PHAM_NHAN_ID IN NUMBER DEFAULT NULL 
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
	SELECT tx.TX_NGAY_TRICH_XUAT AS "NgayTrichXuat",
	tx.TX_NGAY_RA_LENH AS "NgayTra",
	dmtg.MTG_TITLE AS "ThoiHan",
	ddvhc.TTP_TEN AS "NoiTrichXuat"
	FROM TRICH_XUATS tx
	JOIN DM_MA_THOI_GIANS dmtg ON tx.TX_THOI_HAN_ID = dmtg.ID 
	JOIN DM_TINH_THANH_PHO ddvhc 
	ON tx.TX_DIA_PHUONG_DE_NGHI_ID  = ddvhc.ID 
    WHERE (tx.PHAM_NHAN_ID = p_PHAM_NHAN_ID OR p_PHAM_NHAN_ID IS NULL);
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_TRICH_XUAT_TX;








/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TRON_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TRON_TRAI" (
    p_PHAM_NHAN_ID IN NUMBER
)
AS
c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT 
        tt.PHAM_NHAN_ID,
        tt.NGAY_TRON AS "NgayTron",
        dtht.THT_TEN   AS "TruongHopTron",
        tt.NGAY_BAT_LAI AS "NgayBat",
        dhtkl.HTKLPN_TEN AS "HinhThucXuLy"
    FROM TRON_TRAIS tt 
    LEFT JOIN DM_TRUONG_HOP_TRONS dtht ON tt.TRUONG_HOP_TRON_ID = dtht.ID
    LEFT JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dhtkl ON  tt.HINH_THUC_XU_LY_ID = dhtkl.ID
    WHERE tt.PHAM_NHAN_ID = p_PHAM_NHAN_ID
	AND tt.IS_DELETED = 0;
	DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_TRON_TRAI;






/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TRON_TRAI_PT59
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TRON_TRAI_PT59" (
--    p_pham_nhan_id IN NUMBER,
--    p_ngay_tron    IN VARCHAR2
    p_tron_trai_id IN VARCHAR2
)
AS
    c1 SYS_REFCURSOR;
    --v_ngay_tron DATE;
	p_pham_nhan_id NUMBER;
BEGIN
--    IF p_ngay_tron IS NULL OR TRIM(p_ngay_tron) = '' THEN
--        RAISE_APPLICATION_ERROR(-20001, 'p_ngay_tron khong duoc de trong');
--    END IF;
--
--    v_ngay_tron := TO_DATE(TRIM(p_ngay_tron), 'DD/MM/YYYY');

	SELECT PHAM_NHAN_ID INTO p_pham_nhan_id FROM tron_trais WHERE id = p_tron_trai_id;

    OPEN c1 FOR
        WITH vw_one AS (
            SELECT v.*
            FROM qlpn.vw_pn_lai_lich_chi_tiet v
            WHERE NVL(v.is_deleted, 0) = 0
              AND v.pham_nhan_id = p_pham_nhan_id
        ),
        latest_tron AS (
            SELECT *
            FROM (
                SELECT tt.*,
                       ROW_NUMBER() OVER (
                           ORDER BY tt.ngay_tron DESC NULLS LAST, tt.id DESC
                       ) AS rn
                FROM qlpn.tron_trais tt
                WHERE NVL(tt.is_deleted, 0) = 0
                  AND tt.pham_nhan_id = p_pham_nhan_id
                  AND tt.ID = p_tron_trai_id
                  --AND TRUNC(CAST(tt.ngay_tron AS DATE)) = TRUNC(v_ngay_tron)
            )
            WHERE rn = 1
        ),
        nhan_dang_one AS (
            SELECT *
            FROM (
                SELECT nd.*,
                       ROW_NUMBER() OVER (
                           ORDER BY nd.id DESC
                       ) AS rn
                FROM qlpn.pn_nhan_dangs nd
                WHERE NVL(nd.is_deleted, 0) = 0
                  AND nd.nd_pn_lai_lich_id = p_pham_nhan_id
            )
            WHERE rn = 1
        ),
        than_nhan_agg AS (
            SELECT
                tn.pham_nhan_id,
                MAX(CASE WHEN UPPER(TRIM(tn.quan_he)) LIKE 'B?%' THEN tn.ho_ten_than_nhan END) AS HO_TEN_BO,
                MAX(CASE WHEN UPPER(TRIM(tn.quan_he)) LIKE 'M?%' THEN tn.ho_ten_than_nhan END) AS HO_TEN_ME,
                MAX(CASE WHEN UPPER(TRIM(tn.quan_he)) IN ('V?', 'CH?NG') THEN tn.ho_ten_than_nhan END) AS HO_TEN_VO_CHONG,
                LISTAGG(CASE WHEN UPPER(TRIM(tn.quan_he)) = 'CON' THEN tn.ho_ten_than_nhan END, ', ')
                    WITHIN GROUP (ORDER BY tn.id) AS CON
            FROM qlpn.vw_than_nhan tn
            WHERE tn.pham_nhan_id = p_pham_nhan_id
            GROUP BY tn.pham_nhan_id
        ),
        so_lan_tron AS (
            SELECT COUNT(*) AS SO_LAN_TRON
            FROM qlpn.tron_trais tt
            WHERE NVL(tt.is_deleted, 0) = 0
              AND tt.pham_nhan_id = p_pham_nhan_id
        )
        SELECT
            v.so_ho_so AS SO_HSLD,
            v.ho_ten AS HO_TEN,
            v.gioi_tinh AS GIOI_TINH,
            v.ngay_sinh AS NGAY_SINH,
            v.ten_khac AS TEN_KHAC,
            v.nguyen_quan AS QUE_QUAN,
            NVL(v.noi_thuong_tru_day_du, v.dia_chi_thuong_tru) AS NOI_THUONG_TRU,
            v.noi_o_khac AS CHO_O_KHAC,
            NVL(v.cccd, v.ho_chieu) AS SO_CCCD_CC_HO_CHIEU,
            TO_CHAR(ngay_cap_cccd, 'DD/MM/YYYY')  AS NGAY_CAP,
            noi_cap_cccd AS NOI_CAP,
            v.dan_toc AS DAN_TOC,
            v.ton_giao AS TON_GIAO,
            v.quoc_tich AS QUOC_TICH,
            v.toi_danh AS TOI_DANH,
            TO_CHAR(v.ngay_bat_an_phat, 'DD/MM/YYYY') AS NGAY_BAT,
            v.an_phat AS AN_PHAT,
            v.so_ban_an AS SO_BAN_AN,
            TO_CHAR(v.ngay_ban_an, 'DD/MM/YYYY') AS NGAY_BAN_AN,
            v.toa_xu_ten AS TOA_XU,
            v.toa_xu_dia_phuong AS DIA_PHUONG_XU,
            v.so_qd_tha AS SO_QD_THA,
            TO_CHAR(v.ngay_qd_tha, 'DD/MM/YYYY') AS NGAY_QD_THA,
            v.co_quan_qd_tha AS TOA_QD_THA,
            v.toa_qd_tha_dia_phuong AS DIA_PHUONG_QD_THA,
            v.so_danh_ban AS SO_DANH_BAN,
            TO_CHAR(v.NGAY_LAP_DANH_BAN, 'DD/MM/YYYY') AS NGAY_LAP_DANH_BAN,
            CO_QUAN_LAP AS NOI_LAP_DANH_BAN,
            TO_CHAR(v.ngay_den_trai, 'DD/MM/YYYY') AS NGAY_DEN_TRAI,
            v.phan_doi AS TO_DOI,
            v.phan_trai AS PHAN_TRAI,
            TO_NCHAR(v.so_tien_an) AS TIEN_AN,
            TO_NCHAR(v.so_tien_su) AS TIEN_SU,
            tn.HO_TEN_BO AS HO_TEN_BO,
            tn.HO_TEN_ME AS HO_TEN_ME,
            tn.HO_TEN_VO_CHONG AS HO_TEN_VO_CHONG,
            tn.CON AS CON,
            TO_NCHAR(sl.SO_LAN_TRON) AS DA_TRON_LAN_THU,
            TO_CHAR(CAST(tt.ngay_tron AS DATE), 'HH24') AS GIO_TRON,
            TO_CHAR(CAST(tt.ngay_tron AS DATE), 'MI') AS PHUT_TRON,
            TO_CHAR(CAST(tt.ngay_tron AS DATE), 'DD/MM/YYYY') AS NGAY_TRON,
            tt.noi_tron AS NOI_TRON,
            dtht.tht_ten AS TRUONG_HOP_TRON,
            CAST(NULL AS NVARCHAR2(4000)) AS NOI_DUNG_VU_TRON,
            TO_CHAR(CAST(tt.ngay_bat_lai AS DATE), 'HH24') AS GIO_BAT_LAI,
            TO_CHAR(CAST(tt.ngay_bat_lai AS DATE), 'MI') AS PHUT_BAT_LAI,
            TO_CHAR(CAST(tt.ngay_bat_lai AS DATE), 'DD/MM/YYYY') AS NGAY_BAT_LAI,
            tt.noi_bat_lai AS NOI_BAT_LAI,
            dthb.thb_ten AS TRONG_TRUONG_HOP_BAT,
            tt.donvi_bat_lai AS DON_VI_BAT,
            dhtxlb.htxlb_ten AS HINH_THUC_XU_LY_SAU_KHI_BAT,
            nd.nd_chieu_cao AS CHIEU_CAO,
            nd.nd_song_mui AS SONG_MUI,
            nd.nd_nep_tai_duoi AS NEP_TAI_DUOI,
            nd.nd_dai_tai AS DAI_TAI,
            nd.nd_tam_voc AS TAM_VOC,
            nd.nd_mau_da AS MAU_DA,
            nd.nd_dau_vet AS DAU_VET_RIENG
--            CAST(NULL AS NVARCHAR2(2000)) AS MOI_QUAN_HE_VA_THONG_TIN_KHAC,
--            v.trai_giam AS DON_VI_BAO_CAO,
--            CAST(NULL AS NVARCHAR2(4000)) AS BIEN_PHAP_CU_THE,
--            CAST(NULL AS NVARCHAR2(4000)) AS DE_NGHI
        FROM latest_tron tt
        INNER JOIN vw_one v
                ON v.pham_nhan_id = tt.pham_nhan_id
        LEFT JOIN nhan_dang_one nd
               ON 1 = 1
        LEFT JOIN than_nhan_agg tn
               ON tn.pham_nhan_id = v.pham_nhan_id
        LEFT JOIN so_lan_tron sl
               ON 1 = 1
        LEFT JOIN qlpn.dm_truong_hop_trons dtht
               ON dtht.id = tt.truong_hop_tron_id
              AND NVL(dtht.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_truong_hop_bats dthb
               ON dthb.id = tt.truong_hop_bat_lai_id
              AND NVL(dthb.is_deleted, 0) = 0
        LEFT JOIN qlpn.dm_hinh_thuc_xu_ly_bats dhtxlb
               ON dhtxlb.id = tt.hinh_thuc_xu_ly_id
              AND NVL(dhtxlb.is_deleted, 0) = 0;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Loi SP_GET_TRON_TRAI_PT59: ' || SQLERRM);
END SP_GET_TRON_TRAI_PT59;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TT_THI_HANH_AN_DAN_SU
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_TT_THI_HANH_AN_DAN_SU" (
    p_pn_ids IN VARCHAR2 DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    pn_filter AS (
        SELECT /*+ MATERIALIZE */
            TO_NUMBER(TRIM(REGEXP_SUBSTR(p_pn_ids, '[^,]+', 1, LEVEL))) AS pn_id
        FROM dual
        WHERE p_pn_ids IS NOT NULL
        CONNECT BY NOCYCLE LEVEL <= REGEXP_COUNT(p_pn_ids, ',') + 1
    ),

    base_pn AS (
        SELECT /*+ MATERIALIZE */
            rt.PHAM_NHAN_ID                          AS pham_nhan_id,
            rt.LL_SO_HO_SO_LAN_DAU                  AS so_ho_so,
            xa_tve.XP_TEN                            AS noi_tha_ve_cu_tru_xa,
            tinh_tve.TTP_TEN                         AS noi_tha_ve_cu_tru_tinh,
            rt.LL_NOI_THA_VE_CU_TRU                  AS noi_tha_ve_cu_tru,
            rt.THA_SO_QD_DIEU_CHUYEN                 AS so_qd_dieu_chuyen,
            rt.THA_NGAY_QD_DIEU_CHUYEN               AS ngay_qd_dieu_chuyen,
            cq_bat.CQ_TEN                            AS co_quan_bat,
            tinh_cq_bat.TTP_TEN                      AS co_quan_bat_dia_phuong,
            rt.THA_SO_QD_THA                         AS so_qd_tha,
            rt.THA_NGAY_QD_THA                       AS ngay_qd_tha,
            cq_qd_tha.CQ_TEN                         AS co_quan_qd_tha,
            tinh_qd_tha.TTP_TEN                      AS toa_qd_tha_dia_phuong,
            rt.THA_NGAY_DEN_TRAI                     AS ngay_den_trai,
            rt.THA_NGAY_HET_HAN                      AS ngay_het_an,
            pd.PD_TEN                                AS phan_doi,
            pt.PT_TEN                                AS phan_trai,
            rt.LL_HO_TEN                             AS ho_ten,
            gt.GT_TEN                                AS gioi_tinh,
            TO_CHAR(rt.LL_NGAY_SINH)                 AS ngay_sinh,
            rt.LL_TEN_KHAC                           AS ten_khac,
            rt.LL_NGUYEN_QUAN                        AS nguyen_quan,
            CASE
                WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                  OR NULLIF(TRIM(xa_tt.XP_TEN),              u'') IS NOT NULL
                  OR NULLIF(TRIM(tinh_tt.TTP_TEN),           u'') IS NOT NULL
                THEN TRIM(
                    NVL(NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u''), u'')
                    || CASE
                         WHEN NULLIF(TRIM(xa_tt.XP_TEN), u'') IS NOT NULL THEN
                             CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                  THEN u', ' || xa_tt.XP_TEN
                                  ELSE xa_tt.XP_TEN END
                         ELSE u'' END
                    || CASE
                         WHEN NULLIF(TRIM(tinh_tt.TTP_TEN), u'') IS NOT NULL THEN
                             CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                    OR NULLIF(TRIM(xa_tt.XP_TEN),              u'') IS NOT NULL
                                  THEN u', ' || tinh_tt.TTP_TEN
                                  ELSE tinh_tt.TTP_TEN END
                         ELSE u'' END
                )
                ELSE NULL
            END                                      AS noi_thuong_tru_day_du,
            rt.LL_NOI_OKHAC                          AS noi_o_khac,
            dt.DT_TEN                                AS dan_toc,
            dqt.QT_TEN                               AS quoc_tich,
            rt.LL_SO_TIEN_AN                         AS so_tien_an,
            rt.THA_TOI_DANH_NAMES                    AS toi_danh,
            rt.THA_NGAY_BAT                          AS ngay_bat_an_phat,
            rt.THA_AN_PHAT                           AS an_phat,
            rt.THA_SO_BAN_AN                         AS so_ban_an,
            rt.THA_NGAY_BAN_AN                       AS ngay_ban_an,
            toa_xu.CQ_TEN                            AS toa_xu_ten,
            tinh_toa_xu.TTP_TEN                      AS toa_xu_dia_phuong,
            rt.LL_TINH_TRANG_ID
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        LEFT JOIN QLPN.DM_XA_PHUONG xa_tve
            ON xa_tve.ID = rt.LL_NOI_THA_VE_CU_TRU_WARD
           AND NVL(xa_tve.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO tinh_tve
            ON tinh_tve.ID = rt.LL_NOI_THA_VE_CU_TRU_PROVICE
           AND NVL(tinh_tve.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_CO_QUANS cq_bat
            ON cq_bat.ID = rt.THA_CO_QUAN_BAT_ID
           AND NVL(cq_bat.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO tinh_cq_bat
            ON tinh_cq_bat.ID = rt.THA_DIA_PHUONG_CO_QUAN_BAT_ID
           AND NVL(tinh_cq_bat.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_CO_QUANS cq_qd_tha
            ON cq_qd_tha.ID = rt.THA_TOA_QD_ID
           AND NVL(cq_qd_tha.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO tinh_qd_tha
            ON tinh_qd_tha.ID = rt.THA_DIA_PHUONG_TOA_QD_THA_ID
           AND NVL(tinh_qd_tha.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_DOIS pd
            ON pd.ID = rt.LL_PHAN_DOI_ID
           AND NVL(pd.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_TRAIS pt
            ON pt.ID = rt.LL_PHAN_TRAI_ID
           AND NVL(pt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = rt.LL_DM_GIOI_TINH_ID
           AND NVL(gt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_XA_PHUONG xa_tt
            ON xa_tt.ID = rt.LL_DIA_CHI_THUONG_TRU_WARD
           AND NVL(xa_tt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO tinh_tt
            ON tinh_tt.ID = rt.LL_DIA_CHI_THUONG_TRU_PROVICE
           AND NVL(tinh_tt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_DAN_TOCS dt
            ON dt.ID = rt.LL_DM_DAN_TOC_ID
           AND NVL(dt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_QUOC_TICHS dqt
            ON dqt.ID = rt.LL_DM_QUOC_TICH_ID
           AND NVL(dqt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_CO_QUANS toa_xu
            ON toa_xu.ID = rt.THA_CAP_TOA_ID
           AND NVL(toa_xu.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_TINH_THANH_PHO tinh_toa_xu
            ON tinh_toa_xu.ID = rt.THA_DIA_PHUONG_CAP_TOA_ID
           AND NVL(tinh_toa_xu.IS_DELETED, 0) = 0
        WHERE NVL(rt.IS_DELETED, 0) = 0
          AND (p_pn_ids IS NULL
               OR EXISTS (SELECT 1 FROM pn_filter f WHERE f.pn_id = rt.PHAM_NHAN_ID))
    ),

    hpbs_sum AS (
        SELECT /*+ MATERIALIZE NO_MERGE USE_HASH(p b) */
            p.HPBS_MA_PHAM_NHAN,
            REPLACE(
                TO_CHAR(SUM(COALESCE(p.HPBS_TONG_TIEN_PHAT,   0)), 'FM999G999G999G999G999G990'),
                ',', '.'
            ) AS tong_tien_phat,
            REPLACE(
                TO_CHAR(SUM(COALESCE(p.HPBS_TONG_TIEN_CON_LAI, 0)), 'FM999G999G999G999G999G990'),
                ',', '.'
            ) AS tong_tien_con_lai
        FROM QLPN.PN_HINH_PHAT_BO_SUNGS p
        INNER JOIN base_pn b
            ON b.pham_nhan_id = p.HPBS_MA_PHAM_NHAN
        WHERE p.IS_DELETED = 0
        GROUP BY p.HPBS_MA_PHAM_NHAN
    ),

    hpbs_coquan AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            hpbs_ma_pham_nhan,
            co_quan_nop,
            tinh_thanh_pho
        FROM (
            SELECT
                p.HPBS_MA_PHAM_NHAN,
                dcq.CQ_TEN     AS co_quan_nop,
                dttp.TTP_TEN   AS tinh_thanh_pho,
                ROW_NUMBER() OVER (
                    PARTITION BY p.HPBS_MA_PHAM_NHAN
                    ORDER BY
                        CASE WHEN dttp.TTP_TEN IS NOT NULL THEN 0 ELSE 1 END,
                        pb.ID DESC,
                        p.ID  DESC
                ) AS rn
            FROM QLPN.PN_HINH_PHAT_BO_SUNGS p
            INNER JOIN base_pn b
                ON b.pham_nhan_id = p.HPBS_MA_PHAM_NHAN
            INNER JOIN QLPN.PN_BIENLAIES pb
                ON pb.HPBS_ID = p.ID
               AND pb.IS_DELETED = 0
            LEFT JOIN QLPN.DM_CO_QUANS dcq
                ON dcq.ID = pb.BL_NOP_TAI_CO_QUAN
               AND dcq.IS_DELETED = 0
            LEFT JOIN QLPN.DM_TINH_THANH_PHO dttp
                ON dttp.ID = pb.BL_DIA_PHUONG
               AND dttp.IS_DELETED = 0
            WHERE p.IS_DELETED = 0
        )
        WHERE rn = 1
    ),

    than_nhan AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            pham_nhan_id,
            ho_ten_than_nhan,
            noi_o
        FROM (
            SELECT
                tn.PHAM_NHAN_ID,
                tn.HO_TEN_THAN_NHAN,
                tn.NOI_O,
                ROW_NUMBER() OVER (
                    PARTITION BY tn.PHAM_NHAN_ID
                    ORDER BY tn.ID DESC
                ) AS rn
            FROM QLPN.THAN_NHAN_NGUOI_THANS tn
            INNER JOIN base_pn b
                ON b.pham_nhan_id = tn.PHAM_NHAN_ID
            WHERE tn.IS_DELETED = 0
              AND tn.THONG_BAO = 1
        )
        WHERE rn = 1
    ),

    scalar_fns AS (
        SELECT /*+ MATERIALIZE */
            b.pham_nhan_id,
            PKG_TINH_AN.FN_TINH_GIAM_AN_HIEN_THI(b.pham_nhan_id)        AS thoi_gian_da_giam,
            FN_GET_LIET_KE_HPBS_HPBST(b.pham_nhan_id)                   AS hinh_phat_bo_sung,
            FN_GET_LIET_KE_TRACH_NHIEM_DAN_SU_TIEN(b.pham_nhan_id)      AS nghia_vu_dan_su,
            FN_TONG_HOP_KET_QUA_CAI_TAO(b.pham_nhan_id)                 AS xep_loai_cai_tao
        FROM base_pn b
    )
    SELECT
        b.pham_nhan_id,
        b.so_ho_so                                                        AS so_hsld,
        u'- UBND '   || b.noi_tha_ve_cu_tru_xa
            || u', ' || b.noi_tha_ve_cu_tru_tinh
            || TO_NCHAR(CHR(13) || CHR(10))
            || u'- C\01a1 quan THAHS C\00f4ng An '
            || b.noi_tha_ve_cu_tru_tinh                                   AS thads,
        b.so_qd_dieu_chuyen,
        TO_CHAR(b.ngay_qd_dieu_chuyen,  'DD/MM/YYYY')                    AS ngay_qd_dieu_chuyen,
        b.co_quan_bat,
        b.co_quan_bat_dia_phuong,
        b.so_qd_tha,
        TO_CHAR(b.ngay_qd_tha,          'DD/MM/YYYY')                    AS ngay_qd_tha,
        b.co_quan_qd_tha,
        b.toa_qd_tha_dia_phuong,
        TO_CHAR(b.ngay_den_trai,        'DD/MM/YYYY')                    AS ngay_den_trai,
        TO_CHAR(b.ngay_het_an,          'DD/MM/YYYY')                    AS ngay_het_an,
        NULLIF(TRIM(
            NVL(b.phan_doi, u'')
            || CASE WHEN b.phan_doi IS NOT NULL AND b.phan_trai IS NOT NULL THEN u',' ELSE u'' END
            || NVL(b.phan_trai, u'')
        ), u'')                                                           AS phan_doi,
        b.phan_trai,
        b.ho_ten,
        b.gioi_tinh,
        b.ngay_sinh,
        b.ten_khac                                                        AS ho_ten_khac,
        b.nguyen_quan,
        b.noi_thuong_tru_day_du                                           AS noi_dktt,
        CASE
            WHEN NULLIF(TRIM(b.noi_tha_ve_cu_tru),      u'') IS NOT NULL
              OR NULLIF(TRIM(b.noi_tha_ve_cu_tru_xa),   u'') IS NOT NULL
              OR NULLIF(TRIM(b.noi_tha_ve_cu_tru_tinh), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(b.noi_tha_ve_cu_tru), u''), u'')
                || CASE
                     WHEN NULLIF(TRIM(b.noi_tha_ve_cu_tru_xa), u'') IS NOT NULL THEN
                         CASE WHEN NULLIF(TRIM(b.noi_tha_ve_cu_tru), u'') IS NOT NULL
                              THEN u', ' || b.noi_tha_ve_cu_tru_xa
                              ELSE b.noi_tha_ve_cu_tru_xa END
                     ELSE u'' END
                || CASE
                     WHEN NULLIF(TRIM(b.noi_tha_ve_cu_tru_tinh), u'') IS NOT NULL THEN
                         CASE WHEN NULLIF(TRIM(b.noi_tha_ve_cu_tru),    u'') IS NOT NULL
                                OR NULLIF(TRIM(b.noi_tha_ve_cu_tru_xa), u'') IS NOT NULL
                              THEN u', ' || b.noi_tha_ve_cu_tru_tinh
                              ELSE b.noi_tha_ve_cu_tru_tinh END
                     ELSE u'' END
            )
            ELSE NULL
        END                                                               AS dia_chi_tha_ve_cu_tru,
        b.noi_o_khac,
        b.dan_toc,
        b.quoc_tich,
        NVL(b.so_tien_an, '0')                                           AS so_tien_an,
        b.toi_danh,
        TO_CHAR(b.ngay_bat_an_phat,     'DD/MM/YYYY')                    AS ngay_bat,
        b.an_phat,
        b.so_ban_an,
        TO_CHAR(b.ngay_ban_an,          'DD/MM/YYYY')                    AS ngay_ban_an,
        b.toa_xu_ten,
        b.toa_xu_dia_phuong,
        u'C\1ee5c l\00e3nh s\1ef1 qu\00e1n ' || b.quoc_tich             AS cuc_lanh_su,
        NVL(hpbs_cq.co_quan_nop, u'')                                   AS cq_thads,
        tt.TTPN_TEN                                                      AS tinh_trang,
        hpbs.tong_tien_phat,
        hpbs.tong_tien_con_lai,
        sf.thoi_gian_da_giam,
        tn.ho_ten_than_nhan,
        tn.noi_o                                                          AS dia_chi_nhan_than,
        sf.hinh_phat_bo_sung,
        sf.nghia_vu_dan_su,
        sf.xep_loai_cai_tao
    FROM base_pn b
    LEFT JOIN hpbs_sum hpbs
        ON hpbs.HPBS_MA_PHAM_NHAN = b.pham_nhan_id
    LEFT JOIN hpbs_coquan hpbs_cq
        ON hpbs_cq.HPBS_MA_PHAM_NHAN = b.pham_nhan_id
    LEFT JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS tt
        ON tt.ID = b.LL_TINH_TRANG_ID
       AND NVL(tt.IS_DELETED, 0) = 0
    LEFT JOIN than_nhan tn
        ON tn.PHAM_NHAN_ID = b.pham_nhan_id
    LEFT JOIN scalar_fns sf
        ON sf.pham_nhan_id = b.pham_nhan_id
    ORDER BY b.pham_nhan_id;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, u'L\1ed7i SP_GET_TT_THI_HANH_AN_DAN_SU: ' || SQLERRM);
END SP_GET_TT_THI_HANH_AN_DAN_SU;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_XAC_NHAN_TT_SUC_KHOE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_XAC_NHAN_TT_SUC_KHOE" (
    p_pham_nhan_id IN PN_LAI_LICHS.ID%TYPE
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    -- ======================================================
    -- B1: L?y b?n án m?i nh?t
    -- ======================================================
    latest_tha AS (
        SELECT THA_PNLAI_LICH_ID, THA_TOI_DANH,
               THA_NGAY_BAT, THA_AN_PHAT, THA_NGAY_DEN_TRAI
          FROM PN_THI_HANH_AN
         WHERE THA_PNLAI_LICH_ID = p_pham_nhan_id
           AND NVL(IS_DELETED, 0) = 0
         ORDER BY NVL(THA_NGAY_BAN_AN, DATE '1900-01-01') DESC, ID DESC
         FETCH FIRST 1 ROW ONLY
    ),

    -- ======================================================
    -- B2: Aggregate t?i danh - join th?ng qua INSTR/LIKE
    --     Tránh split, ??c d? h?n
    -- ======================================================
    toi_danh_agg AS (
        SELECT RTRIM(
        		LISTAGG(dtd.TD_TEN, ';') WITHIN GROUP (ORDER BY dtd.ID),
                   '; '
               ) AS TOI_DANH_TEXT
          FROM latest_tha tha
          JOIN DM_TOI_DANHS dtd
            ON INSTR(',' || REPLACE(REPLACE(tha.THA_TOI_DANH, '[', ''), ']', '') || ',',
                     ',' || dtd.ID || ',') > 0
           AND NVL(dtd.IS_DELETED, 0) = 0
    )

    -- ======================================================
    -- B3: Main query
    -- ======================================================
    SELECT
        pll.LL_HO_TEN                                               AS "HoTen",
        dgt.GT_TEN                                                  AS "GioiTinh",
        pll.LL_NGAY_SINH                                            AS "NamSinh",
        pll.LL_TEN_KHAC                                             AS "HoTenKhac",
        TRIM(
            NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
            || CASE WHEN NULLIF(TRIM(xa.XP_TEN),    u'') IS NOT NULL
                    THEN CASE WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              THEN ', ' || xa.XP_TEN ELSE xa.XP_TEN END
                    ELSE u'' END
            || CASE WHEN NULLIF(TRIM(tinh.TTP_TEN), u'') IS NOT NULL
                    THEN CASE WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                OR NULLIF(TRIM(xa.XP_TEN), u'') IS NOT NULL
                              THEN ', ' || tinh.TTP_TEN ELSE tinh.TTP_TEN END
                    ELSE u'' END
        )                                                           AS "NoiThuongTru",
        tda.TOI_DANH_TEXT                                           AS "ToiDanh",
        TO_CHAR(tha.THA_NGAY_BAT,      'DD/MM/YYYY')               AS "NgayBat",
        tha.THA_AN_PHAT                                             AS "AnPhat",
        TO_CHAR(tha.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY')               AS "NgayDenTrai",
        dpd.PD_TEN                                                  AS "PhanDoi",
        dpt.PT_TEN                                                  AS "PhanTrai",
        NVL(dbt.BT_TEN, u'Kh\00f4ng b\1ec7nh t\1eadt')             AS "BenhTat",
        dbt2.BT_TEN AS "SucKhoe",
        dtg.TG_TEN                                                  AS "TraiGiam"
      FROM PN_LAI_LICHS         pll
      LEFT JOIN latest_tha      tha  ON tha.THA_PNLAI_LICH_ID = pll.ID
      CROSS JOIN toi_danh_agg   tda
      LEFT JOIN DM_TINH_THANH_PHO tinh ON tinh.ID = pll.LL_DIA_CHI_THUONG_TRU_PROVICE
      LEFT JOIN DM_XA_PHUONG    xa   ON xa.ID   = pll.LL_DIA_CHI_THUONG_TRU_WARD
      LEFT JOIN DM_GIOI_TINHS   dgt  ON dgt.ID  = pll.LL_DM_GIOI_TINH_ID
      LEFT JOIN DM_TRAI_GIAMS   dtg  ON dtg.ID  = pll.LL_TRAI_GIAM_ID
      LEFT JOIN DM_PHAN_TRAIS   dpt  ON dpt.ID  = pll.LL_PHAN_TRAI_ID
      LEFT JOIN DM_PHAN_DOIS    dpd  ON dpd.ID  = pll.LL_PHAN_DOI_ID
      LEFT JOIN DM_BENH_TATS    dbt  ON dbt.ID  = pll.LL_BENH_HIEN_TAI_ID
      LEFT JOIN DM_BENH_TATS dbt2 ON dbt2.ID = pll.LL_SUC_KHOE_KHI_VAO_ID
     WHERE pll.ID = p_pham_nhan_id
       AND NVL(pll.IS_DELETED, 0) = 0;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_XAC_NHAN_TT_SUC_KHOE;



/
--------------------------------------------------------
--  DDL for Procedure SP_GET_XEP_LOAI_PT25
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_GET_XEP_LOAI_PT25" (
    p_pll_id IN NUMBER
) AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH LATEST_THA AS (
        SELECT
            THA_PNLAI_LICH_ID,
            THA_NGAY_BAT,
            THA_AN_PHAT,
            THA_SO_BAN_AN,
            TO_CHAR(THA_NGAY_BAN_AN, 'DD/MM/YYYY') AS THA_NGAY_BAN_AN,
            THA_TOA_QD_ID,
            d2.TTP_TEN AS DIA_PHUONG_TOA,
            THA_SO_QD_THA,
            TO_CHAR(THA_NGAY_QD_THA, 'DD/MM/YYYY') AS THA_NGAY_QD_THA,
            THA_CAP_TOA_ID,
            d.TTP_TEN AS DIA_PHUONG_THA,
            ROW_NUMBER() OVER (
                PARTITION BY THA_PNLAI_LICH_ID
                ORDER BY NVL(THA_NGAY_BAN_AN, TO_DATE('01-JAN-1900', 'DD-MON-YYYY')) DESC, PN_THI_HANH_AN.ID DESC
            ) AS rn
        FROM PN_THI_HANH_AN
        LEFT JOIN DM_TINH_THANH_PHO d  ON PN_THI_HANH_AN.THA_DIA_PHUONG_TOA_QD_THA_ID = d.ID
        LEFT JOIN DM_TINH_THANH_PHO d2 ON PN_THI_HANH_AN.THA_DIA_PHUONG_CAP_TOA_ID    = d2.ID
        WHERE THA_PNLAI_LICH_ID = p_pll_id
    )
    SELECT
        dmml.MPL_TEN            AS LoaiPhanLoai,
        dplgg.PLGG_TEN            AS TuLoai,
        dplgg2.PLGG_TEN            AS DenLoai,
        pll.LL_HO_TEN          AS HoTen,
        pll.LL_TEN_KHAC        AS TenKhac,
        dgt.GT_TEN             AS GioiTinh,
        pll.LL_NGAY_SINH       AS NgaySinh,

        CASE
            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
              OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
            THEN TRIM(
                NVL(NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                || CASE
                    WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                THEN u', ' || dxp_thuong_tru.XP_TEN
                            ELSE dxp_thuong_tru.XP_TEN
                        END
                    ELSE u''
                   END
                || CASE
                    WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                        CASE
                            WHEN NULLIF(TRIM(pll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                              OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                                THEN u', ' || dttp_thuong_tru.TTP_TEN
                            ELSE dttp_thuong_tru.TTP_TEN
                        END
                    ELSE u''
                   END
            )
            ELSE NULL
        END AS DiaChiThuongTru,
        TO_CHAR(TRUNC(ptha.THA_NGAY_BAT), 'DD/MM/YYYY') AS NgayBat,
        ptha.THA_AN_PHAT          AS AnPhat,

        dpd.PD_TEN                AS PhanDoi,
        dpt.PT_TEN                 AS PhanTrai,
        dtg.TG_TEN                 AS TraiGiam

    FROM PN_LAI_LICHS pll
    LEFT JOIN LATEST_THA ptha
           ON pll.ID = ptha.THA_PNLAI_LICH_ID
          AND ptha.rn = 1
    left join PHAN_LOAIS pl ON pll.ID = pl.PHAM_NHAN_ID
    left join DM_MA_PHAN_LOAIES dmml ON pl.LOAI_PHAN_LOAI_ID = dmml.ID
    left join DM_PHAN_LOAI_GIAM_GIUS dplgg ON pl.TU_LOAI_ID = dplgg.ID
    left join DM_PHAN_LOAI_GIAM_GIUS dplgg2 ON pl.DEN_LOAI_ID = dplgg2.ID
    LEFT JOIN DM_GIOI_TINHS dgt   ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
          AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
           ON pll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
          AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    LEFT JOIN DM_PHAN_DOIS dpd    ON pll.LL_PHAN_DOI_ID  = dpd.ID
    LEFT JOIN DM_PHAN_TRAIS dpt   ON pll.LL_PHAN_TRAI_ID = dpt.ID
    LEFT JOIN DM_TRAI_GIAMS dtg   ON pll.LL_TRAI_GIAM_ID = dtg.ID
    WHERE pll.ID = p_pll_id;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        NULL;
    WHEN TOO_MANY_ROWS THEN
        RAISE_APPLICATION_ERROR(-20001, 'Có nhi?u h?n 1 b?n ghi cho ph?m nhân ID: ' || p_pll_id);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error Code: ' || SQLCODE);
        DBMS_OUTPUT.PUT_LINE('Error Message: ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE('Error Backtrace: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE;
END;



/
--------------------------------------------------------
--  DDL for Procedure SP_HS_GET_MBB5_TRON
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_HS_GET_MBB5_TRON" (
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_hs_ids IN VARCHAR2
) AS
    p_cursor SYS_REFCURSOR;
BEGIN
    OPEN p_cursor FOR
    WITH
    id_tokens AS (
        SELECT TRIM(REGEXP_SUBSTR(TRIM(p_hs_ids), '[^,]+', 1, LEVEL)) AS tok
        FROM dual
        WHERE p_hs_ids IS NOT NULL
          AND LENGTH(TRIM(p_hs_ids)) > 0
        CONNECT BY LEVEL <= REGEXP_COUNT(TRIM(p_hs_ids), ',') + 1
           AND PRIOR SYS_GUID() IS NOT NULL
    ),
    hs_ids AS (
        SELECT DISTINCT TO_NUMBER(tok) AS hoc_sinh_id
        FROM id_tokens
        WHERE tok IS NOT NULL
          AND REGEXP_LIKE(tok, '^[0-9]+$')
    ),
    hvvp_rn AS (
        SELECT
            h.*,
            ROW_NUMBER() OVER (
                PARTITION BY h.HVVP_HSLAI_LICH_ID
                ORDER BY h.HVVP_NGAY_VAO DESC NULLS LAST, h.ID DESC
            ) AS rn
        FROM HOCSINH.HS_HANH_VI_VI_PHAMS h
        WHERE NVL(h.IS_DELETED, 0) = 0
    ),
    hvvp_latest AS (
        SELECT * FROM hvvp_rn WHERE rn = 1
    ),
    /* Chu?n hóa HVVP_HANH_VI: ph?y fullwidth ? ph?y ASCII, b? ngo?c [] và kho?ng (gi?ng MQD08). */
    hvvp_hv_clean AS (
        SELECT
            h.*,
            TRIM(
                REGEXP_REPLACE(
                    REGEXP_REPLACE(
                        NVL(TO_NCHAR(h.HVVP_HANH_VI), u''),
                        UNISTR('\FF0C'),
                        u','
                    ),
                    q'|[\[\]\s]+|',
                    u''
                )
            ) AS hv_hv_clean
        FROM hvvp_latest h
    ),
    /* Ch? b?n HV m?i nh?t: HVVP_HANH_VI ? token ID ? DM_TOI_DANHS */
    hvvp_hanh_vi_tokens AS (
        SELECT
            h.HVVP_HSLAI_LICH_ID,
            TRIM(
                REPLACE(
                    REPLACE(
                        REGEXP_SUBSTR(h.hv_hv_clean, '[^,]+', 1, LEVEL),
                        '[',
                        ''
                    ),
                    ']',
                    ''
                )
            ) AS toi_danh_tok
        FROM hvvp_hv_clean h
        WHERE h.hv_hv_clean IS NOT NULL
          AND LENGTH(h.hv_hv_clean) > 0
          AND REGEXP_LIKE(h.hv_hv_clean, '[0-9]')
        CONNECT BY PRIOR h.ID = h.ID
           AND PRIOR SYS_GUID() IS NOT NULL
           AND LEVEL <= REGEXP_COUNT(h.hv_hv_clean, ',') + 1
    ),
    hvvp_all AS (
        SELECT
            x.HVVP_HSLAI_LICH_ID,
            LISTAGG(TO_NCHAR(td.TD_TEN), u'; ') WITHIN GROUP (ORDER BY td.TD_TEN) AS HANH_VI_ALL
        FROM (
            SELECT DISTINCT
                t.HVVP_HSLAI_LICH_ID,
                TO_NUMBER(t.toi_danh_tok) AS toi_danh_id
            FROM hvvp_hanh_vi_tokens t
            WHERE REGEXP_LIKE(t.toi_danh_tok, '^[0-9]+$')
        ) x
        INNER JOIN HOCSINH.DM_TOI_DANHS td
            ON td.ID = x.toi_danh_id
           AND NVL(td.IS_DELETED, 0) = 0
        GROUP BY x.HVVP_HSLAI_LICH_ID
    ),
    tron_rn AS (
        SELECT
            t.*,
            ROW_NUMBER() OVER (
                PARTITION BY t.TT_HS_LAI_LICH_ID
                ORDER BY t.TT_NGAY_TRON DESC NULLS LAST, t.ID DESC
            ) AS rn
        FROM HOCSINH.HS_TRON_TRUONGS t
        WHERE NVL(t.IS_DELETED, 0) = 0
    ),
    tron_pick AS (
        SELECT * FROM tron_rn WHERE rn = 1
    )
    SELECT
        ll.ID AS hoc_sinh_id,
        CASE WHEN TRUNC(SYSDATE) IS NOT NULL THEN TO_CHAR(TRUNC(SYSDATE), q'|DD/MM/YYYY|') END AS ngay,
        TO_CHAR(TRUNC(SYSDATE), q'|MM|') AS thang,
        TO_CHAR(TRUNC(SYSDATE), q'|YYYY|') AS nam,
        TRIM(
            NVL(dtg.TG_TEN, u'')
            || CASE WHEN NVL(dtg.TG_DIA_CHI, u'') <> u'' THEN u' - ' || dtg.TG_DIA_CHI ELSE u'' END
        ) AS don_vi,
        TO_NCHAR(ll.LL_HO_TEN) AS ho_ten,
        NVL(gt.GT_TEN, u'') AS gt,
        NVL(ll.LL_TEN_KHAC, u'') AS ten_khac,
        CASE
            WHEN ll.LL_NGAY_SINH IS NOT NULL
                 AND REGEXP_LIKE(TRIM(TO_CHAR(ll.LL_NGAY_SINH)), q'|^\d{1,2}/\d{1,2}/\d{4}$|')
            THEN TO_NCHAR(TO_DATE(TRIM(TO_CHAR(ll.LL_NGAY_SINH)), q'|DD/MM/YYYY|'), q'|DD/MM/YYYY|')
            WHEN ll.LL_NGAY_SINH IS NOT NULL
                 AND REGEXP_LIKE(TRIM(TO_CHAR(ll.LL_NGAY_SINH)), q'|^[0-9]{4}$|')
            THEN TO_NCHAR(TRIM(TO_CHAR(ll.LL_NGAY_SINH)))
            ELSE TO_NCHAR(TRIM(TO_CHAR(ll.LL_NGAY_SINH)))
        END AS ngay_sinh,
        NVL(ll.LL_CCCD, u'') AS so_cmnd,
        CASE
            WHEN ll.LL_NGAY_CAP_CCCD IS NOT NULL THEN TO_CHAR(TRUNC(ll.LL_NGAY_CAP_CCCD), q'|DD/MM/YYYY|')
        END AS ngay_cap,
        NVL(ll.LL_NOI_CAP_CCCD, u'') AS noi_cap,
        TRIM(
            NVL(TO_NCHAR(ll.LL_DIA_CHI_THUONG_TRU), u'')
            || CASE
                   WHEN TRIM(NVL(TO_NCHAR(xp.XP_TEN), u'')) IS NOT NULL
                   THEN u', ' || TO_NCHAR(xp.XP_TEN)
                   ELSE u''
               END
            || CASE
                   WHEN TRIM(NVL(TO_NCHAR(dttp.TTP_TEN), u'')) IS NOT NULL
                   THEN u', ' || TO_NCHAR(dttp.TTP_TEN)
                   ELSE u''
               END
        ) AS dctt,
        TRIM(
            NVL(TO_NCHAR(ll.LL_NOI_OTRUOC_KHI_BAT), u'')
            || CASE
                   WHEN TRIM(NVL(TO_NCHAR(xp_ot.XP_TEN), u'')) IS NOT NULL
                   THEN u', ' || TO_NCHAR(xp_ot.XP_TEN)
                   ELSE u''
               END
            || CASE
                   WHEN TRIM(NVL(TO_NCHAR(dttp_ot.TTP_TEN), u'')) IS NOT NULL
                   THEN u', ' || TO_NCHAR(dttp_ot.TTP_TEN)
                   ELSE u''
               END
        ) AS noi_o_ht,
        NVL(dtoc.DT_TEN, u'') AS dan_toc,
        NVL(dton.TG_TEN, u'') AS ton_giao,
        NVL(hv_dm.HV_ND, u'') AS hoc_van,
        NVL(nn.NN_TEN, u'') AS nghe_nghiep,
        NVL(ll.LL_NOI_LAM_VIEC, u'') AS noi_lam_viec,
        NVL(ha.HANH_VI_ALL, NVL(ll.LL_TOM_TAT_HV, NVL(ll.LL_CHI_TIET_HV, u''))) AS hanh_vi,
        CASE
            WHEN hv.HVVP_NGAY_DUA_DI IS NOT NULL THEN TO_CHAR(TRUNC(hv.HVVP_NGAY_DUA_DI), q'|DD/MM/YYYY|')
        END AS ngay_dua_di,
        NVL(TO_NCHAR(hv.HVVP_THOI_HAN), NVL(TO_NCHAR(ll.LL_SO_TIEN_AN), u'')) AS thoi_han,
        CASE
            WHEN tr.TT_NGAY_TRON IS NOT NULL THEN TO_CHAR(TRUNC(tr.TT_NGAY_TRON), q'|DD/MM/YYYY|')
        END AS ngay_tron,
        CASE WHEN tr.TT_NGAY_TRON IS NOT NULL THEN TO_CHAR(tr.TT_NGAY_TRON, 'MI') END AS p_tron,
        CASE WHEN tr.TT_NGAY_TRON IS NOT NULL THEN TO_CHAR(tr.TT_NGAY_TRON, 'HH24') END AS h_tron,
        CASE WHEN tr.TT_NGAY_TRON IS NOT NULL THEN TO_CHAR(TRUNC(tr.TT_NGAY_TRON), q'|DD|') END AS d_tron,
        CASE WHEN tr.TT_NGAY_TRON IS NOT NULL THEN TO_CHAR(TRUNC(tr.TT_NGAY_TRON), q'|MM|') END AS m_tron,
        CASE WHEN tr.TT_NGAY_TRON IS NOT NULL THEN TO_CHAR(TRUNC(tr.TT_NGAY_TRON), q'|YYYY|') END AS y_tron,
        NVL(tht.THT_ND, u'') AS th_tron,
        NVL(TO_NCHAR(dttp_truy_tim.TTP_TEN), u'') AS noi_chon
    FROM hs_ids f
    INNER JOIN HOCSINH.HS_LAI_LICHS ll
        ON ll.ID = f.hoc_sinh_id
       AND NVL(ll.IS_DELETED, 0) = 0
    LEFT JOIN tron_pick tr
        ON tr.TT_HS_LAI_LICH_ID = ll.ID
    LEFT JOIN hvvp_latest hv
        ON hv.HVVP_HSLAI_LICH_ID = ll.ID
    LEFT JOIN hvvp_all ha
        ON ha.HVVP_HSLAI_LICH_ID = ll.ID
    LEFT JOIN HOCSINH.DM_TRUONG_HOP_TRON tht
        ON tht.ID = tr.TRUONG_HOP_TRON_ID
       AND NVL(tht.IS_DELETED, 0) = 0
    LEFT JOIN HOCSINH.DM_TINH_THANH_PHO dttp_truy_tim
        ON dttp_truy_tim.ID = tr.TT_DPRL_TRUY_TIM_ID
       AND NVL(dttp_truy_tim.IS_DELETED, 0) = 0
    LEFT JOIN HOCSINH.DM_GIOI_TINHS gt
        ON gt.ID = ll.LL_DM_GIOI_TINH_ID
       AND NVL(gt.IS_DELETED, 0) = 0
    LEFT JOIN HOCSINH.DM_TINH_THANH_PHO dttp
        ON dttp.ID = ll.LL_DIA_CHI_THUONG_TRU_PROVICE
       AND NVL(dttp.IS_DELETED, 0) = 0
    LEFT JOIN HOCSINH.DM_XA_PHUONG xp
        ON xp.ID = ll.LL_DIA_CHI_THUONG_TRU_WARD
       AND NVL(xp.IS_DELETED, 0) = 0
    LEFT JOIN HOCSINH.DM_TINH_THANH_PHO dttp_ot
        ON dttp_ot.ID = ll.LL_NOI_OTRUOC_KHI_BAT_PROVICE
       AND NVL(dttp_ot.IS_DELETED, 0) = 0
    LEFT JOIN HOCSINH.DM_XA_PHUONG xp_ot
        ON xp_ot.ID = ll.LL_NOI_OTRUOC_KHI_BAT_WARD
       AND NVL(xp_ot.IS_DELETED, 0) = 0
    LEFT JOIN HOCSINH.DM_DAN_TOCS dtoc
        ON dtoc.ID = ll.LL_DM_DAN_TOC_ID
       AND NVL(dtoc.IS_DELETED, 0) = 0
    LEFT JOIN HOCSINH.DM_TON_GIAOS dton
        ON dton.ID = ll.LL_DM_TON_GIAO_ID
       AND NVL(dton.IS_DELETED, 0) = 0
    LEFT JOIN HOCSINH.DM_HOCVAN hv_dm
        ON hv_dm.ID = ll.LL_VAN_HOA
       AND NVL(hv_dm.IS_DELETED, 0) = 0
    LEFT JOIN HOCSINH.DM_NGHE_NGHIEPS nn
        ON nn.ID = ll.LL_DM_NGHE_NGHIEP_ID
       AND NVL(nn.IS_DELETED, 0) = 0
    LEFT JOIN HOCSINH.DM_TRAI_GIAMS dtg
        ON dtg.TG_MA = ll.LL_MA_TRAI_GIAM AND NVL(dtg.IS_DELETED, 0) = 0
       AND NVL(dtg.IS_DELETED, 0) = 0
     WHERE (p_ma_trai_giam IS NULL OR ll.LL_MA_TRAI_GIAM = p_ma_trai_giam)
    ORDER BY ll.ID;

    DBMS_SQL.RETURN_RESULT(p_cursor);
END SP_HS_GET_MBB5_TRON;


/
--------------------------------------------------------
--  DDL for Procedure SP_HS_THONG_KE_THANG_1
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_HS_THONG_KE_THANG_1" (
    p_tu_ngay NVARCHAR2 DEFAULT NULL,
    p_den_ngay NVARCHAR2 DEFAULT NULL,
    p_truong_giao_duong NVARCHAR2 DEFAULT NULL,
    p_can_bo_thong_ke NVARCHAR2 DEFAULT NULL
)
AS 
    p_cursor SYS_REFCURSOR;

    v_tu_ngay  DATE;
    v_den_ngay DATE;

    -- Q1
    v_q1_nam   NUMBER := 0; v_q1_nu   NUMBER := 0; v_q1_khac  NUMBER := 0;
    -- Q2~Q7
    v_q2_nam   NUMBER := 0; v_q2_nu   NUMBER := 0; v_q2_khac  NUMBER := 0;
    v_q3_nam   NUMBER := 0; v_q3_nu   NUMBER := 0; v_q3_khac  NUMBER := 0;
    v_q4_nam   NUMBER := 0; v_q4_nu   NUMBER := 0; v_q4_khac  NUMBER := 0;
    v_q5_nam   NUMBER := 0; v_q5_nu   NUMBER := 0; v_q5_khac  NUMBER := 0;
    v_q6_nam   NUMBER := 0; v_q6_nu   NUMBER := 0; v_q6_khac  NUMBER := 0;
    v_q7_nam   NUMBER := 0; v_q7_nu   NUMBER := 0; v_q7_khac  NUMBER := 0;

    -- Q8
    v_q8_nam   NUMBER := 0; v_q8_nu   NUMBER := 0; v_q8_khac  NUMBER := 0;

    -- Q9~Q15
    v_q9_nam   NUMBER := 0; v_q9_nu   NUMBER := 0; v_q9_khac  NUMBER := 0;
    v_q10_nam  NUMBER := 0; v_q10_nu  NUMBER := 0; v_q10_khac NUMBER := 0;
    v_q11_nam  NUMBER := 0; v_q11_nu  NUMBER := 0; v_q11_khac NUMBER := 0;
    v_q12_nam  NUMBER := 0; v_q12_nu  NUMBER := 0; v_q12_khac NUMBER := 0;
    v_q13_nam  NUMBER := 0; v_q13_nu  NUMBER := 0; v_q13_khac NUMBER := 0;
    v_q14_nam  NUMBER := 0; v_q14_nu  NUMBER := 0; v_q14_khac NUMBER := 0;
    v_q15_nam  NUMBER := 0; v_q15_nu  NUMBER := 0; v_q15_khac NUMBER := 0;

    -- Q16~
    v_q16_nam  NUMBER := 0; v_q16_nu  NUMBER := 0; v_q16_khac NUMBER := 0;

BEGIN
    -- Convert date
    IF p_tu_ngay IS NULL OR TRIM(p_tu_ngay) = '' THEN
        v_tu_ngay := TO_DATE('01/01/1900', 'DD/MM/YYYY');
    ELSE
        v_tu_ngay := TO_DATE(p_tu_ngay, 'DD/MM/YYYY');
    END IF;

    IF p_den_ngay IS NULL OR TRIM(p_den_ngay) = '' THEN
        v_den_ngay := TO_DATE('31/12/2100', 'DD/MM/YYYY');
    ELSE
        v_den_ngay := TO_DATE(p_den_ngay, 'DD/MM/YYYY');
    END IF;

    OPEN p_cursor FOR
        SELECT
            v_q1_nam + v_q1_nu + v_q1_khac AS "1",
            v_q2_nam + v_q2_nu + v_q2_khac AS "2",
            v_q3_nam + v_q3_nu + v_q3_khac AS "3",
            v_q4_nam + v_q4_nu + v_q4_khac AS "4",
            v_q5_nam + v_q5_nu + v_q5_khac AS "5",
            v_q6_nam + v_q6_nu + v_q6_khac AS "6",
            v_q7_nam + v_q7_nu + v_q7_khac AS "7",
            v_q8_nam + v_q8_nu + v_q8_khac AS "8",
            v_q9_nam + v_q9_nu + v_q9_khac AS "9",
            v_q10_nam + v_q10_nu + v_q10_khac AS "10",
            v_q11_nam + v_q11_nu + v_q11_khac AS "11",
            v_q12_nam + v_q12_nu + v_q12_khac AS "12",
            v_q13_nam + v_q13_nu + v_q13_khac AS "13",
            v_q14_nam + v_q14_nu + v_q14_khac AS "14",
            v_q15_nam + v_q15_nu + v_q15_khac AS "15",
            v_q16_nam + v_q16_nu + v_q16_khac AS "16"
        FROM DUAL;

    DBMS_SQL.RETURN_RESULT(p_cursor);

END SP_HS_THONG_KE_THANG_1;






/
--------------------------------------------------------
--  DDL for Procedure SP_MATERIALIZE_DISPLAY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_MATERIALIZE_DISPLAY" (
    p_dot_dac_xa_id IN NUMBER,
    p_ma_trai_giam  IN NVARCHAR2 DEFAULT NULL
) AS
    v_ngay_xet     DATE;
    v_trai_giam_id NUMBER;
BEGIN
    IF p_ma_trai_giam IS NOT NULL THEN
        BEGIN
            SELECT id INTO v_trai_giam_id
            FROM DM_TRAI_GIAMS
            WHERE TG_MA = p_ma_trai_giam
              AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                v_trai_giam_id := NULL;
        END;
    END IF;

    SELECT TRUNC(NVL(d.DDX_NGAY_XET, SYSDATE)) INTO v_ngay_xet
      FROM PN_DOT_DAC_XAS d WHERE d.ID = p_dot_dac_xa_id;
    DELETE FROM DX_DISPLAY
     WHERE PN_DOT_DAC_XA_ID = p_dot_dac_xa_id
       AND (p_ma_trai_giam IS NULL OR MA_TRAI_GIAM = p_ma_trai_giam);
    INSERT INTO DX_DISPLAY (
        PN_LAI_LICH_ID, IN_DU_DIEU_KIEN, IN_KHONG_DU_DIEU_KIEN,
        LL_HO_TEN, LL_NGAY_SINH, LL_PHAN_DOI_ID,
        LL_DM_DAN_TOC_ID, LL_DM_QUOC_TICH_ID, LL_DM_TON_GIAO_ID, LL_DM_NGHE_NGHIEP_ID,
        LL_DIA_CHI_THUONG_TRU, LL_NOI_THA_VE_CU_TRU, LL_GHI_CHU_RIENG, LL_GHI_CHU_CHI_TIET,
        LL_NHAN_THAN, LL_SO_TIEN_AN, LL_SO_TIEN_SU, LL_DM_GIOI_TINH_ID, LL_BENH_TAT_VAO_ID,
        MA_TRAI_GIAM,
        THA_NGAY_BAT, THA_NGAY_HET_HAN, THA_AN_PHAT, THA_TOI_DANH, THA_MUC_AN_ID,
        THA_NGAY_DEN_TRAI, THA_MUC_DO_NGHIEM_TRONG_ID, THA_GHI_CHU_DAC_BIET,
        DT_MA, DT_TEN, QT_TEN, GIOI_TINH_NAME,
        IS_ANQG, IS_MA_TUY, HAS_GIET_NGUOI, HAS_TROM_CAP, HAS_CUOP, HAS_CUOP_GIAT,
        HAS_HIEP_DAM, HAS_HIEP_DAM_TRE_EM, HAS_CUONG_DOAT, HAS_LUA_DAO,
        HAS_BAT_COC_CHIEM_DOAT, HAS_CHONG_THI_HANH_CONG_VU, HAS_MUA_BAN_NGUOI,
        HAS_TRE_EM, HAS_GAY_ROI_TTCC, HAS_TIEU_THU_TAI_SAN, HAS_CO_Y_GAY_THUONG_TICH_CON_DO,
        TOI_DANH_COUNT, TIEN_AN_CUOP_TROM_COUNT,
        IS_TO_CHUC, IS_SU_DUNG_VU_KHI, HAS_GHI_CHU_DAC_BIET, IS_CON_DO,
        HAS_GHI_CHU_RIENG, IS_MANG_THAI, IS_CON_NHO_36, IS_CON_THEO_ME,
        IS_HIV_AIDS, IS_GHI_CHU_MA_TUY, IS_VI_THANH_NIEN,
        DANG_TO_TUNG, DA_GIAM_AN, DA_SU_DUNG_MA_TUY_DB, CO_CAN_CU_MA_TUY,
        DA_DAC_XA, DA_DAC_XA_TRUOC_DO, CHUA_CAP_NHAT_NGAY_XET, CO_NGAY_XET_DOT_HIEN_TAI,
        MATCH_TOI_DANH, MATCH_GHI_CHU_RIENG, MATCH_HPBS,
        TONG_KY_XEP_LOAI, BAD_LAST_9, BAD_LAST_7, BAD_LAST_5, BAD_LAST_4,
        BAD_LAST_3, BAD_LAST_2, BAD_LAST_1, CO_KY_XAU, CO_QUY_3_2016_XAU, CO_QUY_XAU_KY_XET,
        XEP_LOAI_TEXT, TOI_DANH_TEXT,
        SO_TIEN_AN_NUM, SO_TIEN_SU_NUM, THA_AN_PHAT_NUM, TUOI,
        IS_CHUA_HOAN_XONG_HPBS, IS_CHUNG_THAN, IS_CT_CHUA_GIAM, IS_CT_DA_GIAM, IS_AN_CO_THOI_HAN,
        THOI_GIAN_GIAM, THOI_GIAN_DA_CHAP_HANH, THOI_GIAN_DA_CHAP_HANH_TEXT,
        THOI_GIAN_CON_LAI, THOI_GIAN_CON_LAI_TEXT, DA_CH_TONG_THANG, CON_LAI_TONG_THANG,
        RULE_2111, RULE_2112, RULE_2121, RULE_2122,
        SO_NGAY_THIEU_TOI_THIEU, IS_DU_KQCT_THEO_SRS, IS_DA_SU_DUNG_MA_TUY,
        IS_ANQG_NGHIEM_TRONG, HAS_HIEP_DAM_ANY,
        PN_DOT_DAC_XA_ID, LL_HO_TEN_NORM
    )
    WITH SOURCE_SCOPE AS (
        SELECT ddk.PN_LAI_LICH_ID, 1 AS IN_DU_DIEU_KIEN, 0 AS IN_KHONG_DU_DIEU_KIEN
        FROM DX_DU_DIEU_KIEN_DAC_XAS ddk
        WHERE ddk.IS_DELETED = 0
          AND ddk.PN_DOT_DAC_XA_ID = p_dot_dac_xa_id
          AND ddk.PN_LAI_LICH_ID IS NOT NULL
        UNION ALL
        SELECT kdk.PN_LAI_LICH_ID, 0 AS IN_DU_DIEU_KIEN, 1 AS IN_KHONG_DU_DIEU_KIEN
        FROM DX_KHONG_DU_DIEU_KIEN_DAC_XAS kdk
        WHERE kdk.IS_DELETED = 0
          AND kdk.PN_DOT_DAC_XA_ID = p_dot_dac_xa_id
          AND kdk.PN_LAI_LICH_ID IS NOT NULL
    ),
    PRISONER_SCOPE AS (
        SELECT ss.PN_LAI_LICH_ID,
               MAX(ss.IN_DU_DIEU_KIEN) AS IN_DU_DIEU_KIEN,
               MAX(ss.IN_KHONG_DU_DIEU_KIEN) AS IN_KHONG_DU_DIEU_KIEN
        FROM SOURCE_SCOPE ss
        INNER JOIN PN_LAI_LICH_CHI_TIET_RT rt
                ON rt.PHAM_NHAN_ID = ss.PN_LAI_LICH_ID
               AND NVL(rt.IS_DELETED, 0) = 0
               AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
        GROUP BY ss.PN_LAI_LICH_ID
    ),
    SPLIT_TOI_DANH AS (
        SELECT rt.PHAM_NHAN_ID AS THA_PNLAI_LICH_ID,
               TO_NUMBER(
                   REGEXP_SUBSTR(
                       REPLACE(REPLACE(NVL(rt.THA_TOI_DANH, ''), '[', ''), ']', ''),
                       '[0-9]+',
                       1,
                       LEVEL
                   )
               ) AS TOI_DANH_ID
        FROM PN_LAI_LICH_CHI_TIET_RT rt
        INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        WHERE rt.IS_DELETED = 0
          AND rt.THA_TOI_DANH IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(REPLACE(REPLACE(NVL(rt.THA_TOI_DANH, ''), '[', ''), ']', ''), '[0-9]+')
               AND PRIOR rt.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    TOI_DANH_MATCH_SOURCE AS (
        SELECT DISTINCT
               s.THA_PNLAI_LICH_ID,
               s.TOI_DANH_ID,
               td.TD_TEN,
               RAWTOHEX(NLSSORT(UPPER(NVL(td.TD_TEN, '')), 'NLS_SORT=BINARY_AI')) AS TD_TEN_AI,
               UPPER(TRIM(NVL(td.TD_CHUONG, ''))) AS TD_CHUONG
        FROM SPLIT_TOI_DANH s
        LEFT JOIN DM_TOI_DANHS td
               ON td.ID = s.TOI_DANH_ID
              AND td.IS_DELETED = 0
    ),
    TOI_DANH_AGG AS (
        SELECT t.THA_PNLAI_LICH_ID,
               LISTAGG(t.TD_TEN, ', ') WITHIN GROUP (ORDER BY t.TD_TEN) AS TOI_DANH_TEXT
        FROM (
            SELECT DISTINCT ms.THA_PNLAI_LICH_ID, ms.TD_TEN
            FROM TOI_DANH_MATCH_SOURCE ms
            WHERE ms.TD_TEN IS NOT NULL
        ) t
        GROUP BY t.THA_PNLAI_LICH_ID
    ),
    TOI_DANH_FLAGS AS (
        SELECT ms.THA_PNLAI_LICH_ID,
               MAX(CASE WHEN ms.TD_CHUONG = '13' THEN 1 ELSE 0 END) AS IS_ANQG,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('MA TUY', 'NLS_SORT=BINARY_AI')) || '%' THEN 1 ELSE 0 END) AS IS_MA_TUY,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('GIET NGUOI', 'NLS_SORT=BINARY_AI')) || '%'
                             OR ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('GIET CON', 'NLS_SORT=BINARY_AI')) || '%'
                             OR ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('VUT BO CON MOI DE', 'NLS_SORT=BINARY_AI')) || '%'
                        THEN 1 ELSE 0 END) AS HAS_GIET_NGUOI,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('TROM CAP', 'NLS_SORT=BINARY_AI')) || '%' THEN 1 ELSE 0 END) AS HAS_TROM_CAP,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('CUOP GIAT', 'NLS_SORT=BINARY_AI')) || '%' THEN 1 ELSE 0 END) AS HAS_CUOP_GIAT,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('CUOP', 'NLS_SORT=BINARY_AI')) || '%'
                             AND ms.TD_TEN_AI NOT LIKE '%' || RAWTOHEX(NLSSORT('CUOP GIAT', 'NLS_SORT=BINARY_AI')) || '%'
                        THEN 1 ELSE 0 END) AS HAS_CUOP,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('HIEP DAM', 'NLS_SORT=BINARY_AI')) || '%' THEN 1 ELSE 0 END) AS HAS_HIEP_DAM,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('HIEP DAM TRE EM', 'NLS_SORT=BINARY_AI')) || '%'
                             OR ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('HIEP DAM NGUOI DUOI 16 TUOI', 'NLS_SORT=BINARY_AI')) || '%'
                        THEN 1 ELSE 0 END) AS HAS_HIEP_DAM_TRE_EM,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('CUONG DOAT TAI SAN', 'NLS_SORT=BINARY_AI')) || '%' THEN 1 ELSE 0 END) AS HAS_CUONG_DOAT,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('LUA DAO CHIEM DOAT TAI SAN', 'NLS_SORT=BINARY_AI')) || '%' THEN 1 ELSE 0 END) AS HAS_LUA_DAO,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('BAT COC NHAM CHIEM DOAT TAI SAN', 'NLS_SORT=BINARY_AI')) || '%' THEN 1 ELSE 0 END) AS HAS_BAT_COC_CHIEM_DOAT,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('CHONG NGUOI THI HANH CONG VU', 'NLS_SORT=BINARY_AI')) || '%' THEN 1 ELSE 0 END) AS HAS_CHONG_THI_HANH_CONG_VU,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('MUA BAN NGUOI', 'NLS_SORT=BINARY_AI')) || '%'
                             OR ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('MUA BAN PHU NU', 'NLS_SORT=BINARY_AI')) || '%'
                        THEN 1 ELSE 0 END) AS HAS_MUA_BAN_NGUOI,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('MUA BAN TRE EM', 'NLS_SORT=BINARY_AI')) || '%'
                             OR ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('DANH TRAO TRE EM', 'NLS_SORT=BINARY_AI')) || '%'
                             OR ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('CHIEM DOAT TRE EM', 'NLS_SORT=BINARY_AI')) || '%'
                        THEN 1 ELSE 0 END) AS HAS_TRE_EM,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('GAY ROI TRAT TU CONG CONG', 'NLS_SORT=BINARY_AI')) || '%'
                        THEN 1 ELSE 0 END) AS HAS_GAY_ROI_TTCC,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('TIEU THU TAI SAN DO NGUOI KHAC PHAM TOI MA CO', 'NLS_SORT=BINARY_AI')) || '%'
                        THEN 1 ELSE 0 END) AS HAS_TIEU_THU_TAI_SAN,
               MAX(CASE WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('CO Y GAY THUONG TICH', 'NLS_SORT=BINARY_AI')) || '%'
                             AND (
                                 ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('CON DO', 'NLS_SORT=BINARY_AI')) || '%'
                                 OR ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('BANG O NHOM', 'NLS_SORT=BINARY_AI')) || '%'
                             )
                        THEN 1 ELSE 0 END) AS HAS_CO_Y_GAY_THUONG_TICH_CON_DO,
               COUNT(DISTINCT ms.TOI_DANH_ID) AS TOI_DANH_COUNT
        FROM TOI_DANH_MATCH_SOURCE ms
        GROUP BY ms.THA_PNLAI_LICH_ID
    ),
    TIEN_AN_RAW AS (
        SELECT ta.PNTA_LAI_LICH_ID,
               REPLACE(REPLACE(NVL(ta.PNTA_TOI_DANH_ID, ''), '[', ''), ']', '') AS TOI_DANH_CSV
        FROM PN_TIEN_AN ta
        INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = ta.PNTA_LAI_LICH_ID
        WHERE ta.IS_DELETED = 0
          AND ta.PNTA_LAI_LICH_ID IS NOT NULL
          AND ta.PNTA_TOI_DANH_ID IS NOT NULL
    ),
    SPLIT_TIEN_AN AS (
        SELECT tar.PNTA_LAI_LICH_ID,
               TO_NUMBER(REGEXP_SUBSTR(tar.TOI_DANH_CSV, '[0-9]+', 1, LEVEL)) AS TOI_DANH_ID
        FROM TIEN_AN_RAW tar
        CONNECT BY LEVEL <= REGEXP_COUNT(tar.TOI_DANH_CSV, '[0-9]+')
               AND PRIOR tar.PNTA_LAI_LICH_ID = tar.PNTA_LAI_LICH_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    TIEN_AN_MATCH_SOURCE AS (
        SELECT st.PNTA_LAI_LICH_ID,
               td.TD_TEN,
               RAWTOHEX(NLSSORT(UPPER(NVL(td.TD_TEN, '')), 'NLS_SORT=BINARY_AI')) AS TD_TEN_AI
        FROM SPLIT_TIEN_AN st
        LEFT JOIN DM_TOI_DANHS td
               ON td.ID = st.TOI_DANH_ID
              AND td.IS_DELETED = 0
    ),
    TIEN_AN_FLAGS AS (
        SELECT ms.PNTA_LAI_LICH_ID,
               SUM(
                   CASE
                       WHEN ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('CUOP', 'NLS_SORT=BINARY_AI')) || '%'
                            OR ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('TROM CAP', 'NLS_SORT=BINARY_AI')) || '%'
                            OR ms.TD_TEN_AI LIKE '%' || RAWTOHEX(NLSSORT('CUOP GIAT', 'NLS_SORT=BINARY_AI')) || '%'
                       THEN 1
                       ELSE 0
                   END
               ) AS TIEN_AN_CUOP_TROM_COUNT
        FROM TIEN_AN_MATCH_SOURCE ms
        GROUP BY ms.PNTA_LAI_LICH_ID
    ),
    THA_GHI_CHU_RAW AS (
        SELECT rt.PHAM_NHAN_ID AS THA_PNLAI_LICH_ID,
               REPLACE(REPLACE(NVL(rt.THA_GHI_CHU_DAC_BIET, ''), '[', ''), ']', '') AS GHI_CHU_CSV
        FROM PN_LAI_LICH_CHI_TIET_RT rt
        INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        WHERE rt.IS_DELETED = 0
          AND rt.THA_GHI_CHU_DAC_BIET IS NOT NULL
    ),
    THA_GHI_CHU_IDS AS (
        SELECT tgr.THA_PNLAI_LICH_ID,
               TO_NUMBER(REGEXP_SUBSTR(tgr.GHI_CHU_CSV, '[0-9]+', 1, LEVEL)) AS GHI_CHU_ID
        FROM THA_GHI_CHU_RAW tgr
        CONNECT BY LEVEL <= REGEXP_COUNT(tgr.GHI_CHU_CSV, '[0-9]+')
               AND PRIOR tgr.THA_PNLAI_LICH_ID = tgr.THA_PNLAI_LICH_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    THA_GHI_CHU_FLAGS AS (
        SELECT ids.THA_PNLAI_LICH_ID,
               MAX(CASE WHEN RAWTOHEX(NLSSORT(UPPER(NVL(dm.GCDB_TEN, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('PHAM TOI CO TO CHUC', 'NLS_SORT=BINARY_AI')) || '%' THEN 1 ELSE 0 END) AS IS_TO_CHUC,
               MAX(CASE WHEN RAWTOHEX(NLSSORT(UPPER(NVL(dm.GCDB_TEN, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('SU DUNG VU KHI', 'NLS_SORT=BINARY_AI')) || '%' THEN 1 ELSE 0 END) AS IS_SU_DUNG_VU_KHI,
               MAX(CASE WHEN ids.GHI_CHU_ID IS NOT NULL THEN 1 ELSE 0 END) AS HAS_GHI_CHU_DAC_BIET,
               MAX(CASE WHEN RAWTOHEX(NLSSORT(UPPER(NVL(dm.GCDB_TEN, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('CON DO', 'NLS_SORT=BINARY_AI')) || '%' THEN 1 ELSE 0 END) AS IS_CON_DO,
               MAX(CASE WHEN RAWTOHEX(NLSSORT(UPPER(NVL(dm.GCDB_TEN, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('HIV', 'NLS_SORT=BINARY_AI')) || '%'
                             OR RAWTOHEX(NLSSORT(UPPER(NVL(dm.GCDB_TEN, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('AIDS', 'NLS_SORT=BINARY_AI')) || '%'
                        THEN 1 ELSE 0 END) AS IS_HIV_AIDS_FROM_GCDB
        FROM THA_GHI_CHU_IDS ids
        LEFT JOIN DM_GHI_CHU_DAC_BIETS dm
               ON dm.ID = ids.GHI_CHU_ID
              AND dm.IS_DELETED = 0
        GROUP BY ids.THA_PNLAI_LICH_ID
    ),
    LL_GHI_CHU_RIENG_RAW AS (
        SELECT rt.PHAM_NHAN_ID AS PN_LAI_LICH_ID,
               REPLACE(REPLACE(NVL(rt.LL_GHI_CHU_RIENG, ''), '[', ''), ']', '') AS GHI_CHU_CSV
        FROM PN_LAI_LICH_CHI_TIET_RT rt
        INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        WHERE rt.IS_DELETED = 0
          AND rt.LL_GHI_CHU_RIENG IS NOT NULL
    ),
    LL_GHI_CHU_RIENG_IDS AS (
        SELECT lgr.PN_LAI_LICH_ID,
               TO_NUMBER(REGEXP_SUBSTR(lgr.GHI_CHU_CSV, '[0-9]+', 1, LEVEL)) AS GHI_CHU_RIENG_ID
        FROM LL_GHI_CHU_RIENG_RAW lgr
        CONNECT BY LEVEL <= REGEXP_COUNT(lgr.GHI_CHU_CSV, '[0-9]+')
               AND PRIOR lgr.PN_LAI_LICH_ID = lgr.PN_LAI_LICH_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    LL_GHI_CHU_RIENG_FLAGS AS (
        SELECT ids.PN_LAI_LICH_ID,
               MAX(CASE WHEN ids.GHI_CHU_RIENG_ID IS NOT NULL THEN 1 ELSE 0 END) AS HAS_GHI_CHU_RIENG,
               MAX(CASE WHEN RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_TEN, '') || ' ' || NVL(gcr.GCR_MA, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('MANG THAI', 'NLS_SORT=BINARY_AI')) || '%'
                             OR RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_TEN, '') || ' ' || NVL(gcr.GCR_MA, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('CO THAI', 'NLS_SORT=BINARY_AI')) || '%'
                        THEN 1 ELSE 0 END) AS IS_MANG_THAI,
               MAX(CASE WHEN RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_TEN, '') || ' ' || NVL(gcr.GCR_MA, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('CON NHO', 'NLS_SORT=BINARY_AI')) || '%'
                             OR RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_TEN, '') || ' ' || NVL(gcr.GCR_MA, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('36 THANG', 'NLS_SORT=BINARY_AI')) || '%'
                        THEN 1 ELSE 0 END) AS IS_CON_NHO_36,
               MAX(CASE WHEN RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_TEN, '') || ' ' || NVL(gcr.GCR_MA, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('CON THEO ME', 'NLS_SORT=BINARY_AI')) || '%' THEN 1 ELSE 0 END) AS IS_CON_THEO_ME,
               MAX(CASE WHEN RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_TEN, '') || ' ' || NVL(gcr.GCR_MA, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('HIV', 'NLS_SORT=BINARY_AI')) || '%'
                             OR RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_TEN, '') || ' ' || NVL(gcr.GCR_MA, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('AIDS', 'NLS_SORT=BINARY_AI')) || '%'
                        THEN 1 ELSE 0 END) AS IS_HIV_AIDS,
               MAX(CASE WHEN RAWTOHEX(NLSSORT(UPPER(NVL(gcr.GCR_TEN, '') || ' ' || NVL(gcr.GCR_MA, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('MA TUY', 'NLS_SORT=BINARY_AI')) || '%'
                        THEN 1 ELSE 0 END) AS IS_GHI_CHU_MA_TUY,
								MAX(CASE WHEN gcr.GCR_MA IN ('1900', '1920', '1930') THEN 1 ELSE 0 END) AS IS_VI_THANH_NIEN
        FROM LL_GHI_CHU_RIENG_IDS ids
        LEFT JOIN DM_GHI_CHU_RIENGS gcr
               ON gcr.ID = ids.GHI_CHU_RIENG_ID
              AND gcr.IS_DELETED = 0
        GROUP BY ids.PN_LAI_LICH_ID
    ),
    -- (FILTER_TOI_DANH / FILTER_GHI_CHU_RIENG / FILTER_HPBS da bo: dieu kien "NULL IS NOT NULL"
    --  luon rong nen MATCH_* luon = 0 — thay bang hang 0 o select list)
    TO_TUNG_FLAGS AS (
        SELECT tt.PHAM_NHAN_ID AS PN_LAI_LICH_ID,
               1 AS DANG_TO_TUNG
        FROM TRICH_XUATS tt
        INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = tt.PHAM_NHAN_ID
        LEFT JOIN DM_LY_DO_TRICH_XUATS ldtx
               ON ldtx.ID = tt.TX_LY_DO_ID
        WHERE tt.IS_DELETED = 0
          AND ldtx.LDTX_MA IN ('10', '11', '12', '13', '14', '15', '16', '20')
        GROUP BY tt.PHAM_NHAN_ID
    ),
    GIAM_AN_FLAGS AS (
        SELECT ga.PHAM_NHAN_ID AS PN_LAI_LICH_ID, 1 AS DA_GIAM_AN
        FROM GIAM_THOI_HANS ga
        INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = ga.PHAM_NHAN_ID
        WHERE ga.IS_DELETED = 0
        GROUP BY ga.PHAM_NHAN_ID
    ),
    NGHIEN_MT_FLAGS AS (
        SELECT nmt.NMT_PN_LAI_LICH_ID AS PN_LAI_LICH_ID,
               MAX(CASE WHEN nmt.NMT_PN_LAI_LICH_ID IS NOT NULL THEN 1 ELSE 0 END) AS DA_SU_DUNG_MA_TUY,
               MAX(CASE WHEN nmt.NMT_CAN_CU_XAC_DINH IS NOT NULL THEN 1 ELSE 0 END) AS CO_CAN_CU_MA_TUY
        FROM PN_NGHIEN_MT nmt
        INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = nmt.NMT_PN_LAI_LICH_ID
        WHERE nmt.IS_DELETED = 0
        GROUP BY nmt.NMT_PN_LAI_LICH_ID
    ),
    DAC_XA_STATUS_RAW AS (
        SELECT dx.PNLAI_LICH_ID,
               REPLACE(REPLACE(REPLACE(REPLACE(NVL(dx.DX_TINH_TRANG_DAC_XA, ''), '[', ''), ']', ''), '"', ''), '''', '') AS TINH_TRANG_CSV
        FROM PN_DAC_XAS dx
        INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = dx.PNLAI_LICH_ID
        WHERE dx.IS_DELETED = 0
          AND dx.PNLAI_LICH_ID IS NOT NULL
          AND dx.DX_TINH_TRANG_DAC_XA IS NOT NULL
    ),
    DAC_XA_STATUS_IDS AS (
        SELECT dsr.PNLAI_LICH_ID,
               TO_NUMBER(REGEXP_SUBSTR(dsr.TINH_TRANG_CSV, '[0-9]+', 1, LEVEL)) AS TINH_TRANG_ID
        FROM DAC_XA_STATUS_RAW dsr
        CONNECT BY LEVEL <= REGEXP_COUNT(dsr.TINH_TRANG_CSV, '[0-9]+')
               AND PRIOR dsr.PNLAI_LICH_ID = dsr.PNLAI_LICH_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    DAC_XA_FLAGS AS (
        SELECT ids.PNLAI_LICH_ID AS PN_LAI_LICH_ID,
               MAX(CASE WHEN ttpn.DDX_MA IN ('10','11','12') THEN 1 ELSE 0 END) AS DA_DAC_XA,
               MAX(CASE WHEN ttpn.DDX_MA IN ('10','11','12') THEN 1 ELSE 0 END) AS DA_DAC_XA_TRUOC_DO
        FROM DAC_XA_STATUS_IDS ids
        LEFT JOIN DM_DUOC_DAC_XAS ttpn
               ON ttpn.ID = ids.TINH_TRANG_ID
              AND ttpn.IS_DELETED = 0
        GROUP BY ids.PNLAI_LICH_ID
    ),
			CHUA_CAP_NHAT_NGAY_XET AS (
				 SELECT rt.PHAM_NHAN_ID AS PN_LAI_LICH_ID,
				 1 AS CHUA_CAP_NHAT_NGAY_XET
				 FROM PN_LAI_LICH_CHI_TIET_RT rt
				 INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
				 WHERE rt.IS_DELETED = 0
				 AND NOT EXISTS (
				 -- ?ã có b?n ghi trong PN_DAC_XAS VÀ có DX_NGAY_XET ? ?ã c?p nh?t ? KHÔNG tính
				 SELECT 1 FROM PN_DAC_XAS dx
				 WHERE dx.IS_DELETED = 0
				 AND dx.PNLAI_LICH_ID = rt.PHAM_NHAN_ID
				 AND dx.DX_NGAY_XET IS NOT NULL
				 )
				),
		CO_NGAY_XET_DOT_HIEN_TAI AS (
			 SELECT dx.PNLAI_LICH_ID AS PN_LAI_LICH_ID,
			 1 AS CO_NGAY_XET_DOT_HIEN_TAI
			 FROM PN_DAC_XAS dx
			 INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = dx.PNLAI_LICH_ID
			 WHERE dx.IS_DELETED = 0
			 AND dx.PNLAI_LICH_ID IS NOT NULL
			 AND dx.DX_NGAY_XET = v_ngay_xet
			 GROUP BY dx.PNLAI_LICH_ID
		),
    THI_HANH_TIME AS (
        SELECT ps.PN_LAI_LICH_ID,
               NVL(ddk.SNAP_TONG_THOI_GIAN_GIAM, NVL(kdk.SNAP_TONG_THOI_GIAN_GIAM, 0)) AS THOI_GIAN_GIAM,
               NVL(ddk.SNAP_DA_CHAP_HANH,        NVL(kdk.SNAP_DA_CHAP_HANH, 0))        AS THOI_GIAN_DA_CHAP_HANH,
               NVL(ddk.SNAP_DA_CHAP_HANH_TEXT,   NVL(kdk.SNAP_DA_CHAP_HANH_TEXT, ''))  AS THOI_GIAN_DA_CHAP_HANH_TEXT,
               NVL(ddk.SNAP_CON_LAI,             NVL(kdk.SNAP_CON_LAI, 0))             AS THOI_GIAN_CON_LAI,
               NVL(ddk.SNAP_CON_LAI_TEXT,        NVL(kdk.SNAP_CON_LAI_TEXT, ''))       AS THOI_GIAN_CON_LAI_TEXT,
               NVL(ddk.SNAP_DA_CHAP_HANH_THANG,  kdk.SNAP_DA_CHAP_HANH_THANG)          AS DA_CH_TONG_THANG_SNAP,
               NVL(ddk.SNAP_CON_LAI_THANG,       kdk.SNAP_CON_LAI_THANG)               AS CON_LAI_TONG_THANG_SNAP,
               NVL(ddk.SNAP_NGAY_BAT,            kdk.SNAP_NGAY_BAT)                   AS SNAP_NGAY_BAT
        FROM PRISONER_SCOPE ps
        LEFT JOIN DX_DU_DIEU_KIEN_DAC_XAS ddk
               ON ddk.PN_LAI_LICH_ID = ps.PN_LAI_LICH_ID
              AND ddk.PN_DOT_DAC_XA_ID = p_dot_dac_xa_id
              AND ddk.IS_DELETED = 0
        LEFT JOIN DX_KHONG_DU_DIEU_KIEN_DAC_XAS kdk
               ON kdk.PN_LAI_LICH_ID = ps.PN_LAI_LICH_ID
              AND kdk.PN_DOT_DAC_XA_ID = p_dot_dac_xa_id
              AND kdk.IS_DELETED = 0
    ),
    HPBS_BASE AS (
        SELECT h.ID,
               h.HPBS_MA_PHAM_NHAN,
               h.HPBS_HINH_PHAT,
               NVL(h.HPBS_TONG_TIEN_PHAT, 0) AS HPBS_TONG_TIEN_PHAT
        FROM PN_HINH_PHAT_BO_SUNGS h
        INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = h.HPBS_MA_PHAM_NHAN
        WHERE h.IS_DELETED = 0
    ),
    BIEN_LAI_SUM AS (
        SELECT bl.HPBS_ID,
               SUM(NVL(bl.BL_SO_TIEN, 0)) AS TONG_BIEN_LAI
        FROM PN_BIENLAIES bl
        WHERE bl.IS_DELETED = 0
          AND EXISTS (
              SELECT 1
              FROM HPBS_BASE hb
              WHERE hb.ID = bl.HPBS_ID
          )
        GROUP BY bl.HPBS_ID
    ),
    HPBS_FLAGS AS (
        SELECT hb.HPBS_MA_PHAM_NHAN AS PN_LAI_LICH_ID,
               MAX(
                   CASE
                       WHEN hb.HPBS_TONG_TIEN_PHAT - NVL(bls.TONG_BIEN_LAI, 0) > 0 THEN 1
                       ELSE 0
                   END
               ) AS IS_CHUA_HOAN_XONG_HPBS
        FROM HPBS_BASE hb
        LEFT JOIN BIEN_LAI_SUM bls
               ON bls.HPBS_ID = hb.ID
        GROUP BY hb.HPBS_MA_PHAM_NHAN
    ),
    XEP_LOAI_PERIODS AS (
        SELECT xl.PHAM_NHAN_ID,
               xl.XEP_LOAI_NAM * 10 + 2 AS PERIOD_KEY,
               CASE WHEN xl.XEP_LOAI_QUY_III IS NOT NULL OR xl.XEP_LOAI_QUY_IV IS NOT NULL THEN 1 ELSE 0 END AS HAS_PERIOD,
               CASE WHEN NVL(xl.XEP_LOAI_QUY_III, 0) IN (3, 4) OR NVL(xl.XEP_LOAI_QUY_IV, 0) IN (3, 4) THEN 1 ELSE 0 END AS IS_BAD,
               CASE WHEN xl.XEP_LOAI_NAM = 2016 AND NVL(xl.XEP_LOAI_QUY_III, 0) IN (3, 4) THEN 1 ELSE 0 END AS BAD_Q3_2016
        FROM XEP_LOAIS xl
        INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = xl.PHAM_NHAN_ID
        WHERE xl.IS_DELETED = 0
        UNION ALL
        SELECT xl.PHAM_NHAN_ID,
               xl.XEP_LOAI_NAM * 10 + 1 AS PERIOD_KEY,
               CASE WHEN xl.XEP_LOAI_QUY_I IS NOT NULL OR xl.XEP_LOAI_QUY_II IS NOT NULL THEN 1 ELSE 0 END AS HAS_PERIOD,
               CASE WHEN NVL(xl.XEP_LOAI_QUY_I, 0) IN (3, 4) OR NVL(xl.XEP_LOAI_QUY_II, 0) IN (3, 4) THEN 1 ELSE 0 END AS IS_BAD,
               0 AS BAD_Q3_2016
        FROM XEP_LOAIS xl
        INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = xl.PHAM_NHAN_ID
        WHERE xl.IS_DELETED = 0
    ),
    XEP_LOAI_PERIODS_RANKED AS (
        SELECT xp.PHAM_NHAN_ID,
               xp.PERIOD_KEY,
               xp.IS_BAD,
               xp.BAD_Q3_2016,
               ROW_NUMBER() OVER (PARTITION BY xp.PHAM_NHAN_ID ORDER BY xp.PERIOD_KEY DESC) AS RN
        FROM XEP_LOAI_PERIODS xp
        WHERE xp.HAS_PERIOD = 1
    ),
    XEP_LOAI_STATS AS (
        SELECT xr.PHAM_NHAN_ID,
               COUNT(*) AS TONG_KY,
               MAX(CASE WHEN xr.IS_BAD = 1 THEN 1 ELSE 0 END) AS CO_KY_XAU,
               MAX(CASE WHEN xr.BAD_Q3_2016 = 1 THEN 1 ELSE 0 END) AS CO_QUY_3_2016_XAU,
               SUM(CASE WHEN xr.RN <= 9 AND xr.IS_BAD = 1 THEN 1 ELSE 0 END) AS BAD_LAST_9,
               SUM(CASE WHEN xr.RN <= 7 AND xr.IS_BAD = 1 THEN 1 ELSE 0 END) AS BAD_LAST_7,
               SUM(CASE WHEN xr.RN <= 5 AND xr.IS_BAD = 1 THEN 1 ELSE 0 END) AS BAD_LAST_5,
               SUM(CASE WHEN xr.RN <= 4 AND xr.IS_BAD = 1 THEN 1 ELSE 0 END) AS BAD_LAST_4,
               SUM(CASE WHEN xr.RN <= 3 AND xr.IS_BAD = 1 THEN 1 ELSE 0 END) AS BAD_LAST_3,
               SUM(CASE WHEN xr.RN <= 2 AND xr.IS_BAD = 1 THEN 1 ELSE 0 END) AS BAD_LAST_2,
               SUM(CASE WHEN xr.RN <= 1 AND xr.IS_BAD = 1 THEN 1 ELSE 0 END) AS BAD_LAST_1
        FROM XEP_LOAI_PERIODS_RANKED xr
        GROUP BY xr.PHAM_NHAN_ID
    ),
    XEP_LOAI_KY_XET AS (
        SELECT xl.PHAM_NHAN_ID,
               MAX(
                   CASE
                       WHEN xl.XEP_LOAI_NAM = EXTRACT(YEAR FROM v_ngay_xet) THEN
                           CASE CEIL(EXTRACT(MONTH FROM v_ngay_xet) / 3)
                               WHEN 1 THEN CASE WHEN NVL(xl.XEP_LOAI_QUY_I, 0) IN (3, 4) THEN 1 ELSE 0 END
                               WHEN 2 THEN CASE WHEN NVL(xl.XEP_LOAI_QUY_II, 0) IN (3, 4) THEN 1 ELSE 0 END
                               WHEN 3 THEN CASE WHEN NVL(xl.XEP_LOAI_QUY_III, 0) IN (3, 4) THEN 1 ELSE 0 END
                               ELSE CASE WHEN NVL(xl.XEP_LOAI_QUY_IV, 0) IN (3, 4) THEN 1 ELSE 0 END
                           END
                       ELSE 0
                   END
               ) AS CO_QUY_XAU_KY_XET
        FROM XEP_LOAIS xl
        INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = xl.PHAM_NHAN_ID
        WHERE xl.IS_DELETED = 0
        GROUP BY xl.PHAM_NHAN_ID
    ),
    LATEST_XEP_LOAI_TEXT AS (
        SELECT x2.PHAM_NHAN_ID,
               dm.XLCT_TEN
        FROM (
            SELECT xl.PHAM_NHAN_ID,
                   xl.XEP_LOAI_CA_NAM,
                   ROW_NUMBER() OVER (
                       PARTITION BY xl.PHAM_NHAN_ID
                       ORDER BY NVL(xl.XEP_LOAI_NAM, 0) DESC, xl.ID DESC
                   ) AS RN
            FROM XEP_LOAIS xl
            INNER JOIN PRISONER_SCOPE ps ON ps.PN_LAI_LICH_ID = xl.PHAM_NHAN_ID
            WHERE xl.IS_DELETED = 0
        ) x2
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS dm
               ON dm.ID = x2.XEP_LOAI_CA_NAM
              AND dm.IS_DELETED = 0
        WHERE x2.RN = 1
    ),
    -- ID muc do "rat nghiem trong" / "dac biet nghiem trong": tinh 1 lan tren danh muc
    -- (truoc day la correlated EXISTS + NLSSORT chay lai cho tung dong ENRICHED)
    MDNT_NGHIEM_TRONG AS (
        SELECT mdnt.ID
        FROM DM_MUC_DO_NGHIEM_TRONGS mdnt
        WHERE mdnt.IS_DELETED = 0
          AND (
              RAWTOHEX(NLSSORT(UPPER(NVL(mdnt.MDNT_TEN, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('RAT NGHIEM TRONG', 'NLS_SORT=BINARY_AI')) || '%'
              OR RAWTOHEX(NLSSORT(UPPER(NVL(mdnt.MDNT_TEN, '')), 'NLS_SORT=BINARY_AI')) LIKE '%' || RAWTOHEX(NLSSORT('DAC BIET NGHIEM TRONG', 'NLS_SORT=BINARY_AI')) || '%'
          )
    ),
    BASE_DATA AS (
        SELECT rt.PHAM_NHAN_ID AS PN_LAI_LICH_ID,
               sc.IN_DU_DIEU_KIEN,
               sc.IN_KHONG_DU_DIEU_KIEN,
               rt.LL_HO_TEN,
               rt.LL_NGAY_SINH,
               rt.LL_PHAN_DOI_ID,
               rt.LL_DM_DAN_TOC_ID,
               rt.LL_DM_QUOC_TICH_ID,
               rt.LL_DM_TON_GIAO_ID,
               rt.LL_DM_NGHE_NGHIEP_ID,
               CASE
                   WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                     OR NULLIF(TRIM(dktt_xp.XP_TEN), u'') IS NOT NULL
                     OR NULLIF(TRIM(dktt_ttp.TTP_TEN), u'') IS NOT NULL
                   THEN TRIM(
                       NVL(NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u''), u'')
                       || CASE WHEN NULLIF(TRIM(dktt_xp.XP_TEN), u'') IS NOT NULL THEN
                                   CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                        THEN u', ' || dktt_xp.XP_TEN ELSE dktt_xp.XP_TEN END
                              ELSE u'' END
                       || CASE WHEN NULLIF(TRIM(dktt_ttp.TTP_TEN), u'') IS NOT NULL THEN
                                   CASE WHEN NULLIF(TRIM(rt.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                          OR NULLIF(TRIM(dktt_xp.XP_TEN), u'') IS NOT NULL
                                        THEN u', ' || dktt_ttp.TTP_TEN ELSE dktt_ttp.TTP_TEN END
                              ELSE u'' END
                   )
                   ELSE NULL
               END AS LL_DIA_CHI_THUONG_TRU,
               CASE
                   WHEN NULLIF(TRIM(rt.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
                     OR NULLIF(TRIM(ve_xp.XP_TEN), u'') IS NOT NULL
                     OR NULLIF(TRIM(ve_ttp.TTP_TEN), u'') IS NOT NULL
                   THEN TRIM(
                       NVL(NULLIF(TRIM(rt.LL_NOI_THA_VE_CU_TRU), u''), u'')
                       || CASE WHEN NULLIF(TRIM(ve_xp.XP_TEN), u'') IS NOT NULL THEN
                                   CASE WHEN NULLIF(TRIM(rt.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
                                        THEN u', ' || ve_xp.XP_TEN ELSE ve_xp.XP_TEN END
                              ELSE u'' END
                       || CASE WHEN NULLIF(TRIM(ve_ttp.TTP_TEN), u'') IS NOT NULL THEN
                                   CASE WHEN NULLIF(TRIM(rt.LL_NOI_THA_VE_CU_TRU), u'') IS NOT NULL
                                          OR NULLIF(TRIM(ve_xp.XP_TEN), u'') IS NOT NULL
                                        THEN u', ' || ve_ttp.TTP_TEN ELSE ve_ttp.TTP_TEN END
                              ELSE u'' END
                   )
                   ELSE NULL
               END AS LL_NOI_THA_VE_CU_TRU,
               rt.LL_GHI_CHU_RIENG,
               rt.LL_GHI_CHU_CHI_TIET,
               rt.LL_NHAN_THAN,
               rt.LL_SO_TIEN_AN,
               rt.LL_SO_TIEN_SU,
               rt.LL_DM_GIOI_TINH_ID,
               rt.LL_BENH_TAT_VAO_ID,
               dtg.TG_MA AS MA_TRAI_GIAM,
               rt.THA_NGAY_BAT,
               rt.THA_NGAY_HET_HAN,
               rt.THA_AN_PHAT,
               rt.THA_TOI_DANH,
               rt.THA_MUC_AN_ID,
               rt.THA_NGAY_DEN_TRAI,
               rt.THA_MUC_DO_NGHIEM_TRONG_ID,
               rt.THA_GHI_CHU_DAC_BIET,
               dt.DT_MA,
               dt.DT_TEN,
               qt.QT_TEN,
               gt.GT_TEN AS GIOI_TINH_NAME,
               NVL(tf.IS_ANQG, 0) AS IS_ANQG,
               NVL(tf.IS_MA_TUY, 0) AS IS_MA_TUY,
               NVL(tf.HAS_GIET_NGUOI, 0) AS HAS_GIET_NGUOI,
               NVL(tf.HAS_TROM_CAP, 0) AS HAS_TROM_CAP,
               NVL(tf.HAS_CUOP, 0) AS HAS_CUOP,
               NVL(tf.HAS_CUOP_GIAT, 0) AS HAS_CUOP_GIAT,
               NVL(tf.HAS_HIEP_DAM, 0) AS HAS_HIEP_DAM,
               NVL(tf.HAS_HIEP_DAM_TRE_EM, 0) AS HAS_HIEP_DAM_TRE_EM,
               NVL(tf.HAS_CUONG_DOAT, 0) AS HAS_CUONG_DOAT,
               NVL(tf.HAS_LUA_DAO, 0) AS HAS_LUA_DAO,
               NVL(tf.HAS_BAT_COC_CHIEM_DOAT, 0) AS HAS_BAT_COC_CHIEM_DOAT,
               NVL(tf.HAS_CHONG_THI_HANH_CONG_VU, 0) AS HAS_CHONG_THI_HANH_CONG_VU,
               NVL(tf.HAS_MUA_BAN_NGUOI, 0) AS HAS_MUA_BAN_NGUOI,
               NVL(tf.HAS_TRE_EM, 0) AS HAS_TRE_EM,
               NVL(tf.HAS_GAY_ROI_TTCC, 0) AS HAS_GAY_ROI_TTCC,
               NVL(tf.HAS_TIEU_THU_TAI_SAN, 0) AS HAS_TIEU_THU_TAI_SAN,
               NVL(tf.HAS_CO_Y_GAY_THUONG_TICH_CON_DO, 0) AS HAS_CO_Y_GAY_THUONG_TICH_CON_DO,
               NVL(tf.TOI_DANH_COUNT, 0) AS TOI_DANH_COUNT,
               NVL(taf.TIEN_AN_CUOP_TROM_COUNT, 0) AS TIEN_AN_CUOP_TROM_COUNT,
               NVL(tgcf.IS_TO_CHUC, 0) AS IS_TO_CHUC,
               NVL(tgcf.IS_SU_DUNG_VU_KHI, 0) AS IS_SU_DUNG_VU_KHI,
               NVL(tgcf.HAS_GHI_CHU_DAC_BIET, 0) AS HAS_GHI_CHU_DAC_BIET,
               NVL(tgcf.IS_CON_DO, 0) AS IS_CON_DO,
               NVL(lgrf.HAS_GHI_CHU_RIENG, 0) AS HAS_GHI_CHU_RIENG,
               NVL(lgrf.IS_MANG_THAI, 0) AS IS_MANG_THAI,
               NVL(lgrf.IS_CON_NHO_36, 0) AS IS_CON_NHO_36,
               NVL(lgrf.IS_CON_THEO_ME, 0) AS IS_CON_THEO_ME,
               GREATEST(NVL(lgrf.IS_HIV_AIDS, 0), NVL(tgcf.IS_HIV_AIDS_FROM_GCDB, 0)) AS IS_HIV_AIDS,
               NVL(lgrf.IS_GHI_CHU_MA_TUY, 0) AS IS_GHI_CHU_MA_TUY,
							 NVL(lgrf.IS_VI_THANH_NIEN, 0) AS IS_VI_THANH_NIEN,
               NVL(ttf.DANG_TO_TUNG, 0) AS DANG_TO_TUNG,
               NVL(gaf.DA_GIAM_AN, 0) AS DA_GIAM_AN,
               NVL(nmf.DA_SU_DUNG_MA_TUY, 0) AS DA_SU_DUNG_MA_TUY_DB,
               NVL(nmf.CO_CAN_CU_MA_TUY, 0) AS CO_CAN_CU_MA_TUY,
               NVL(dxf.DA_DAC_XA, 0) AS DA_DAC_XA,
               NVL(dxf.DA_DAC_XA_TRUOC_DO, 0) AS DA_DAC_XA_TRUOC_DO,
							 NVL(cn.CHUA_CAP_NHAT_NGAY_XET, 0) AS CHUA_CAP_NHAT_NGAY_XET,
							 NVL(xn.CO_NGAY_XET_DOT_HIEN_TAI, 0) AS CO_NGAY_XET_DOT_HIEN_TAI,
               0 AS MATCH_TOI_DANH,
               0 AS MATCH_GHI_CHU_RIENG,
               0 AS MATCH_HPBS,
               NVL(xs.TONG_KY, 0) AS TONG_KY_XEP_LOAI,
               NVL(xs.BAD_LAST_9, 0) AS BAD_LAST_9,
               NVL(xs.BAD_LAST_7, 0) AS BAD_LAST_7,
               NVL(xs.BAD_LAST_5, 0) AS BAD_LAST_5,
               NVL(xs.BAD_LAST_4, 0) AS BAD_LAST_4,
               NVL(xs.BAD_LAST_3, 0) AS BAD_LAST_3,
               NVL(xs.BAD_LAST_2, 0) AS BAD_LAST_2,
               NVL(xs.BAD_LAST_1, 0) AS BAD_LAST_1,
               NVL(xs.CO_KY_XAU, 0) AS CO_KY_XAU,
               NVL(xs.CO_QUY_3_2016_XAU, 0) AS CO_QUY_3_2016_XAU,
               NVL(xlk.CO_QUY_XAU_KY_XET, 0) AS CO_QUY_XAU_KY_XET,
               lxt.XLCT_TEN AS XEP_LOAI_TEXT,
               NVL(taa.TOI_DANH_TEXT, rt.THA_TOI_DANH) AS TOI_DANH_TEXT,
               CASE WHEN REGEXP_LIKE(TRIM(NVL(rt.LL_SO_TIEN_AN, '')), '^[0-9]+$') THEN TO_NUMBER(TRIM(rt.LL_SO_TIEN_AN)) ELSE 0 END AS SO_TIEN_AN_NUM,
               CASE WHEN REGEXP_LIKE(TRIM(NVL(rt.LL_SO_TIEN_SU, '')), '^[0-9]+$') THEN TO_NUMBER(TRIM(rt.LL_SO_TIEN_SU)) ELSE 0 END AS SO_TIEN_SU_NUM,
               CASE
                   WHEN mtg.MTG_MA = '921000' THEN 30
                   WHEN mtg.MTG_MA = '922000' THEN 20
                   -- Chung thân ch?a "gi?m xu?ng" ? NULL; các tr??ng h?p còn l?i (k? c? chung thân gi?m xu?ng) ? parse n?m/tháng
                   WHEN nrm.AN_PHAT_NORM LIKE '%CHUNGTHAN%'
                    AND nrm.AN_PHAT_NORM NOT LIKE '%GIAMXUONG%'
                   THEN NULL
                   ELSE QLPN.PKG_TINH_AN.FN_TONG_THANG_TU_AN_PHAT_TEXT(rt.THA_AN_PHAT) / 12
               END AS THA_AN_PHAT_NUM,
               CASE
                   WHEN rt.LL_NGAY_SINH IS NULL THEN NULL
                   WHEN REGEXP_LIKE(TRIM(rt.LL_NGAY_SINH), '^[0-9]{4}$') THEN EXTRACT(YEAR FROM v_ngay_xet) - TO_NUMBER(TRIM(rt.LL_NGAY_SINH))
                   WHEN REGEXP_LIKE(TRIM(rt.LL_NGAY_SINH), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$') THEN EXTRACT(YEAR FROM v_ngay_xet) - TO_NUMBER(SUBSTR(TRIM(rt.LL_NGAY_SINH), -4))
                   WHEN REGEXP_LIKE(REGEXP_REPLACE(TRIM(rt.LL_NGAY_SINH), '[^0-9]', ''), '^[0-9]{4,}$') THEN EXTRACT(YEAR FROM v_ngay_xet) - TO_NUMBER(SUBSTR(REGEXP_REPLACE(TRIM(rt.LL_NGAY_SINH), '[^0-9]', ''), -4))
                   ELSE NULL
               END AS TUOI,
               NVL(hpf.IS_CHUA_HOAN_XONG_HPBS, 0) AS IS_CHUA_HOAN_XONG_HPBS,
               CASE
                   WHEN mtg.MTG_MA IN ('921000', '922000') THEN 1
                   WHEN nrm.AN_PHAT_NORM LIKE '%CHUNGTHAN%'
                    AND nrm.AN_PHAT_NORM LIKE '%GIAMXUONG%'
                   THEN 1
                   ELSE 0
               END AS IS_CHUNG_THAN,
               CASE
                   WHEN (
                       mtg.MTG_MA IN ('921000', '922000')
                       OR nrm.AN_PHAT_NORM LIKE '%CHUNGTHAN%'
                   ) AND rt.THA_NGAY_HET_HAN IS NULL THEN 1
                   ELSE 0
               END AS IS_CT_CHUA_GIAM,
               CASE
                   WHEN rt.THA_NGAY_HET_HAN IS NOT NULL
                    AND (
                       mtg.MTG_MA IN ('921000', '922000')
                       OR nrm.AN_PHAT_NORM LIKE '%CHUNGTHAN%'
                   ) THEN 1
                   ELSE 0
               END AS IS_CT_DA_GIAM,
               CASE
                   WHEN (
                       mtg.MTG_MA IN ('921000', '922000')
                       OR nrm.AN_PHAT_NORM LIKE '%CHUNGTHAN%'
                   ) AND rt.THA_NGAY_HET_HAN IS NULL THEN 0
                   ELSE 1
               END AS IS_AN_CO_THOI_HAN,
               NVL(tht.THOI_GIAN_GIAM, 0) AS THOI_GIAN_GIAM,
               NVL(tht.THOI_GIAN_DA_CHAP_HANH, 0) AS THOI_GIAN_DA_CHAP_HANH,
							 NVL(tht.THOI_GIAN_DA_CHAP_HANH_TEXT, '') AS THOI_GIAN_DA_CHAP_HANH_TEXT,
               NVL(tht.THOI_GIAN_CON_LAI, 0) AS THOI_GIAN_CON_LAI,
							 NVL(tht.THOI_GIAN_CON_LAI_TEXT, '') AS THOI_GIAN_CON_LAI_TEXT,
               NVL(tht.DA_CH_TONG_THANG_SNAP, 0)  AS DA_CH_TONG_THANG,
               NVL(tht.CON_LAI_TONG_THANG_SNAP, 0) AS CON_LAI_TONG_THANG

        FROM PRISONER_SCOPE sc
        INNER JOIN PN_LAI_LICH_CHI_TIET_RT rt
                ON rt.PHAM_NHAN_ID = sc.PN_LAI_LICH_ID
               AND rt.IS_DELETED = 0
        LEFT JOIN DM_MA_THOI_GIANS mtg
               ON mtg.ID = rt.THA_MUC_AN_ID
              AND mtg.IS_DELETED = 0
        LEFT JOIN DM_TRAI_GIAMS dtg
               ON dtg.ID = rt.LL_TRAI_GIAM_ID
              AND NVL(dtg.IS_DELETED, 0) = 0
        LEFT JOIN DM_DAN_TOCS dt
               ON dt.ID = rt.LL_DM_DAN_TOC_ID
              AND dt.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS qt
               ON qt.ID = rt.LL_DM_QUOC_TICH_ID
              AND qt.IS_DELETED = 0
        LEFT JOIN DM_GIOI_TINHS gt
               ON gt.ID = rt.LL_DM_GIOI_TINH_ID
              AND gt.IS_DELETED = 0
        LEFT JOIN DM_XA_PHUONG dktt_xp
               ON dktt_xp.ID = rt.LL_DIA_CHI_THUONG_TRU_WARD
              AND dktt_xp.IS_DELETED = 0
        LEFT JOIN DM_TINH_THANH_PHO dktt_ttp
               ON dktt_ttp.ID = rt.LL_DIA_CHI_THUONG_TRU_PROVICE
              AND dktt_ttp.IS_DELETED = 0
        LEFT JOIN DM_XA_PHUONG ve_xp
               ON ve_xp.ID = rt.LL_NOI_THA_VE_CU_TRU_WARD
              AND ve_xp.IS_DELETED = 0
        LEFT JOIN DM_TINH_THANH_PHO ve_ttp
               ON ve_ttp.ID = rt.LL_NOI_THA_VE_CU_TRU_PROVICE
              AND ve_ttp.IS_DELETED = 0
        LEFT JOIN TOI_DANH_FLAGS tf
               ON tf.THA_PNLAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN TOI_DANH_AGG taa
               ON taa.THA_PNLAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN TIEN_AN_FLAGS taf
               ON taf.PNTA_LAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN THA_GHI_CHU_FLAGS tgcf
               ON tgcf.THA_PNLAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN LL_GHI_CHU_RIENG_FLAGS lgrf
               ON lgrf.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN TO_TUNG_FLAGS ttf
               ON ttf.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN GIAM_AN_FLAGS gaf
               ON gaf.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN NGHIEN_MT_FLAGS nmf
               ON nmf.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN DAC_XA_FLAGS dxf
               ON dxf.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
			  LEFT JOIN CHUA_CAP_NHAT_NGAY_XET cn
							 ON cn.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
			  LEFT JOIN CO_NGAY_XET_DOT_HIEN_TAI xn
							ON xn.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN THI_HANH_TIME tht
               ON tht.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN HPBS_FLAGS hpf
               ON hpf.PN_LAI_LICH_ID = rt.PHAM_NHAN_ID
        LEFT JOIN XEP_LOAI_STATS xs
               ON xs.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
        LEFT JOIN XEP_LOAI_KY_XET xlk
               ON xlk.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
        LEFT JOIN LATEST_XEP_LOAI_TEXT lxt
               ON lxt.PHAM_NHAN_ID = rt.PHAM_NHAN_ID
        -- Chuan hoa 1 lan/dong (truoc day FN_NORMALIZE_VN bi goi ~15 lan/dong trong cac CASE)
        CROSS APPLY (
            SELECT UPPER(QLPN.FN_NORMALIZE_VN(NVL(rt.THA_AN_PHAT, ''))) AS AN_PHAT_NORM
            FROM DUAL
        ) nrm
    ),
    ENRICHED AS (
        SELECT b.*,
               CASE WHEN b.IS_CT_CHUA_GIAM = 1 AND b.DA_CH_TONG_THANG < 144 THEN 1 ELSE 0 END AS RULE_2111,
               CASE WHEN b.IS_CT_CHUA_GIAM = 1 AND b.DA_CH_TONG_THANG >= 144 AND b.DA_CH_TONG_THANG < 168 AND b.HAS_GHI_CHU_RIENG = 0 THEN 1 ELSE 0 END AS RULE_2112,
               CASE WHEN b.IS_AN_CO_THOI_HAN = 1 AND b.THA_AN_PHAT_NUM IS NOT NULL AND (b.DA_CH_TONG_THANG / (b.THA_AN_PHAT_NUM * 12)) < 0.25 THEN 1 ELSE 0 END AS RULE_2121,
               CASE WHEN b.IS_AN_CO_THOI_HAN = 1 AND b.THA_AN_PHAT_NUM IS NOT NULL AND (b.DA_CH_TONG_THANG / (b.THA_AN_PHAT_NUM * 12)) >= 0.25 AND (b.DA_CH_TONG_THANG / (b.THA_AN_PHAT_NUM * 12)) < 0.3333333333 AND b.HAS_GHI_CHU_RIENG = 0 THEN 1 ELSE 0 END AS RULE_2122,
               CASE
                   WHEN b.IS_CT_CHUA_GIAM = 1 AND b.DA_CH_TONG_THANG < 144 THEN
                       NVL(GREATEST(TRUNC(QLPN.PKG_TINH_AN.FN_NGAY_NGUONG_TU_TONG_THANG(
                           tht.SNAP_NGAY_BAT, 144, 1)) - TRUNC(v_ngay_xet), 0), 0)
                   WHEN b.IS_CT_CHUA_GIAM = 1 AND b.DA_CH_TONG_THANG >= 144 AND b.DA_CH_TONG_THANG < 168 AND b.HAS_GHI_CHU_RIENG = 0 THEN
                       NVL(GREATEST(TRUNC(QLPN.PKG_TINH_AN.FN_NGAY_NGUONG_TU_TONG_THANG(
                           tht.SNAP_NGAY_BAT, 168, 1)) - TRUNC(v_ngay_xet), 0), 0)
                   WHEN b.IS_AN_CO_THOI_HAN = 1 AND b.THA_AN_PHAT_NUM IS NOT NULL AND (b.DA_CH_TONG_THANG / (b.THA_AN_PHAT_NUM * 12)) < 0.25 THEN
                       NVL(GREATEST(TRUNC(QLPN.PKG_TINH_AN.FN_NGAY_NGUONG_TU_TONG_THANG(
                           tht.SNAP_NGAY_BAT, b.THA_AN_PHAT_NUM * 12, 0.25)) - TRUNC(v_ngay_xet), 0), 0)
                   WHEN b.IS_AN_CO_THOI_HAN = 1 AND b.THA_AN_PHAT_NUM IS NOT NULL AND (b.DA_CH_TONG_THANG / (b.THA_AN_PHAT_NUM * 12)) >= 0.25 AND (b.DA_CH_TONG_THANG / (b.THA_AN_PHAT_NUM * 12)) < 0.3333333333 AND b.HAS_GHI_CHU_RIENG = 0 THEN
                       NVL(GREATEST(TRUNC(QLPN.PKG_TINH_AN.FN_NGAY_NGUONG_TU_TONG_THANG(
                           tht.SNAP_NGAY_BAT, b.THA_AN_PHAT_NUM * 12, 0.3333333333)) - TRUNC(v_ngay_xet), 0), 0)
                   ELSE 0
               END AS SO_NGAY_THIEU_TOI_THIEU,
               CASE
                   WHEN b.IS_CT_CHUA_GIAM = 1 THEN CASE WHEN b.TONG_KY_XEP_LOAI >= 9 AND b.BAD_LAST_9 = 0 THEN 1 ELSE 0 END
                   WHEN b.THA_AN_PHAT_NUM > 15 THEN CASE WHEN b.TONG_KY_XEP_LOAI >= 7 AND b.BAD_LAST_7 = 0 THEN 1 ELSE 0 END
                   WHEN b.THA_AN_PHAT_NUM > 10 THEN CASE WHEN b.TONG_KY_XEP_LOAI >= 5 AND b.BAD_LAST_5 = 0 THEN 1 ELSE 0 END
                   WHEN b.THA_AN_PHAT_NUM > 7 THEN CASE WHEN b.TONG_KY_XEP_LOAI >= 4 AND b.BAD_LAST_4 = 0 THEN 1 ELSE 0 END
                   WHEN b.THA_AN_PHAT_NUM > 5 THEN CASE WHEN b.TONG_KY_XEP_LOAI >= 3 AND b.BAD_LAST_3 = 0 THEN 1 ELSE 0 END
                   WHEN b.THA_AN_PHAT_NUM > 3 THEN CASE WHEN b.TONG_KY_XEP_LOAI >= 2 AND b.BAD_LAST_2 = 0 THEN 1 ELSE 0 END
                   WHEN b.THA_AN_PHAT_NUM IS NOT NULL THEN CASE WHEN b.TONG_KY_XEP_LOAI >= 1 AND b.BAD_LAST_1 = 0 THEN 1 ELSE 0 END
                   ELSE 0
               END AS IS_DU_KQCT_THEO_SRS,
               CASE WHEN NVL(b.DA_SU_DUNG_MA_TUY_DB, 0) = 1 OR b.IS_GHI_CHU_MA_TUY = 1 OR b.IS_MA_TUY = 1 THEN 1 ELSE 0 END AS IS_DA_SU_DUNG_MA_TUY,
               CASE WHEN mnt.ID IS NOT NULL THEN 1 ELSE 0 END AS IS_ANQG_NGHIEM_TRONG,
               CASE WHEN b.HAS_HIEP_DAM = 1 OR b.HAS_HIEP_DAM_TRE_EM = 1 THEN 1 ELSE 0 END AS HAS_HIEP_DAM_ANY
        FROM BASE_DATA b
        LEFT JOIN MDNT_NGHIEM_TRONG mnt
               ON mnt.ID = b.THA_MUC_DO_NGHIEM_TRONG_ID
        LEFT JOIN THI_HANH_TIME tht
               ON tht.PN_LAI_LICH_ID = b.PN_LAI_LICH_ID
    )
    SELECT b.*, p_dot_dac_xa_id AS PN_DOT_DAC_XA_ID,
           SUBSTR(UPPER(QLPN.FN_NORMALIZE_VN(b.LL_HO_TEN)),1,400) AS LL_HO_TEN_NORM
    FROM ENRICHED b;
    COMMIT;
END SP_MATERIALIZE_DISPLAY;

/
--------------------------------------------------------
--  DDL for Procedure SP_POPULATE_TK_PT80
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_POPULATE_TK_PT80" (
    V_DATE DATE,
    V_TRAI_GIAM_ID NUMBER DEFAULT NULL
) IS
BEGIN
    DELETE FROM TK_PT80;

    INSERT INTO TK_PT80 (PN_LAI_LICH_ID, MA_GIOI_TINH, MA_TOI_DANH, MA_MUC_AN_PHAT,
                         SO_TIEN_AN, GHI_CHU_RIENG, NGAY_SINH_PN, MA_QUOC_TICH,
                         MA_DAN_TOC, MA_TON_GIAO, MA_HOC_VAN, MA_PHAN_DOI, NGAY_PHAM_TOI,
                         MA_BENH_TAT_VAO, MA_TAI_PHAM, MA_NGHE_NGHIEP, ORDER_HO_TEN,
                         TRAI_GIAM_ID, TRAI_GIAM_MA)
    SELECT LL.ID,
           GT.GT_MA,
           (TO_NUMBER(SUBSTR(THA.THA_TOI_DANH, 2,
                                    NVL(NULLIF(INSTR(THA.THA_TOI_DANH, ','), 0), INSTR(THA.THA_TOI_DANH, ']')) - 2))
           ) AS MA_TOI_DANH,
           (SELECT MIN(THA.THA_MA_AN_PHAT) KEEP (DENSE_RANK FIRST ORDER BY THA.THA_NGAY_DEN_TRAI)
            FROM PN_THI_HANH_AN THA
            WHERE THA.THA_PNLAI_LICH_ID = LL.ID
              AND NVL(THA.IS_DELETED, 0) = 0) AS MA_MUC_AN_PHAT,
           LL.LL_SO_TIEN_AN,
           LL.LL_GHI_CHU_RIENG,
           LL.LL_NGAY_SINH                    AS NGAY_SINH_PN,
           QT.QT_MA,
           DT.DT_MA,
           TG_RELIGION.TG_MA,
           HV.HV_MA,
           PD.PD_MA,
           (SELECT MIN(CAST(THA.THA_NGAY_PHAM_TOI AS DATE))
            FROM PN_THI_HANH_AN THA
            WHERE THA.THA_PNLAI_LICH_ID = LL.ID
              AND NVL(THA.IS_DELETED, 0) = 0) AS NGAY_PHAM_TOI,
           BT.BT_MA,
           TO_NCHAR(NVL(dmtp.TP_MA, 0)),
           NN.NN_MA,
           LL.LL_HO_TEN,
           LL.LL_TRAI_GIAM_ID,
           TG_PRISON.TG_MA
    FROM PN_LAI_LICHS LL
             JOIN PN_THI_HANH_AN THA ON THA.THA_PNLAI_LICH_ID = LL.ID AND NVL(THA.IS_DELETED, 0) = 0
             LEFT JOIN DM_GIOI_TINHS GT ON GT.ID = LL.LL_DM_GIOI_TINH_ID AND NVL(GT.IS_DELETED, 0) = 0
             LEFT JOIN DM_QUOC_TICHS QT ON QT.ID = LL.LL_DM_QUOC_TICH_ID AND NVL(QT.IS_DELETED, 0) = 0
             LEFT JOIN DM_DAN_TOCS DT ON DT.ID = LL.LL_DM_DAN_TOC_ID AND NVL(DT.IS_DELETED, 0) = 0
             LEFT JOIN DM_TON_GIAOS TG_RELIGION ON TG_RELIGION.ID = LL.LL_DM_TON_GIAO_ID AND NVL(TG_RELIGION.IS_DELETED, 0) = 0
             LEFT JOIN DM_HOC_VANS HV ON HV.ID = LL.LL_DM_HOC_VAN_ID AND NVL(HV.IS_DELETED, 0) = 0
             LEFT JOIN DM_NGHE_NGHIEPS NN ON NN.ID = LL.LL_DM_NGHE_NGHIEP_ID AND NVL(NN.IS_DELETED, 0) = 0
             LEFT JOIN DM_PHAN_DOIS PD ON PD.ID = LL.LL_PHAN_DOI_ID AND NVL(PD.IS_DELETED, 0) = 0
             LEFT JOIN DM_BENH_TATS BT ON BT.ID = LL.LL_BENH_TAT_VAO_ID AND NVL(BT.IS_DELETED, 0) = 0
             LEFT JOIN DM_TRAI_GIAMS TG_PRISON ON TG_PRISON.ID = LL.LL_TRAI_GIAM_ID AND NVL(TG_PRISON.IS_DELETED, 0) = 0
             LEFT JOIN DM_TAI_PHAMS dmtp ON LL.LL_TAI_PHAM = dmtp.ID AND NVL(dmtp.IS_DELETED, 0) = 0
    WHERE NVL(LL.IS_DELETED, 0) = 0
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
      AND FN_GET_TINH_TRANG_TAI_NGAY_XET(LL.ID, V_DATE) IN ('111', '112', '113', '114');

--     COMMIT;
END SP_POPULATE_TK_PT80;





