  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_POPULATE_TK_PT80_ALT" (
    V_DATE DATE,
    V_TRAI_GIAM_ID NUMBER DEFAULT NULL
) IS
BEGIN

--     DELETE FROM QLPN.TK_PT80;

    INSERT INTO QLPN.TK_PT80 (PN_LAI_LICH_ID, MA_GIOI_TINH, MA_TOI_DANH, CHUONG_TD,
                              SO_TIEN_AN, GHI_CHU_RIENG, NAM_SINH, MA_QUOC_TICH,
                              MA_DAN_TOC, MA_TON_GIAO, MA_HOC_VAN, MA_PHAN_DOI, NAM_PHAM_TOI,
                              MA_BENH_TAT_VAO, MA_TAI_PHAM, MA_NGHE_NGHIEP, ORDER_HO_TEN,
                              TRAI_GIAM_ID, TRAI_GIAM_MA, MUC_AN_NGAY)
    WITH
        /*==============================================================
         * STEP 0 — SCOPE
         * T?p ph?m nhân thu?c ph?m vi báo cáo, l?c theo tr?i giam ngay t? ??u.
         * ??y ?i?u ki?n V_TRAI_GIAM_ID lên s?m nh?t ?? toàn b? pipeline phía sau
         * (ARRIVED, các EX_*, ACTIVE_*) ch? x? lý ph?m nhân c?a tr?i ???c ch?n.
         * Khi V_TRAI_GIAM_ID IS NULL: SCOPE = toàn b? dân s? (báo cáo toàn qu?c).
         *============================================================*/
        SCOPE AS (SELECT LL.ID AS LLID
                  FROM QLPN.PN_LAI_LICHS LL
                  WHERE LL.IS_DELETED = 0
                    AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)),
        /*==============================================================
         * STEP 1 — ARRIVED
         * Ph?m nhân có ít nh?t m?t THA v?i THA_NGAY_DEN_TRAI <= V_DATE.
         * Equivalent v?i "MIN(NGAY_DEN_TRAI) <= V_DATE" c?a hàm g?c.
         *============================================================*/
        ARRIVED AS (SELECT DISTINCT THA.THA_PNLAI_LICH_ID AS LLID
                    FROM QLPN.PN_THI_HANH_AN THA
                             JOIN SCOPE S ON S.LLID = THA.THA_PNLAI_LICH_ID
                    WHERE THA.THA_NGAY_DEN_TRAI IS NOT NULL
                      AND THA.THA_NGAY_DEN_TRAI < V_DATE + 1
                      AND THA.IS_DELETED = 0),

        /*==============================================================
         * EXCLUSION CTEs — m?i CTE = m?t t?p KHÔNG thu?c '111'/'112'.
         *============================================================*/

        -- E1 ? K?t thúc h? s? (return 9999)
        EX_TERMINAL AS (SELECT LL.ID AS LLID
                        FROM QLPN.PN_LAI_LICHS LL
                                 JOIN PN_THI_HANH_AN ptha ON ptha.THA_PNLAI_LICH_ID = LL.ID AND ptha.IS_DELETED = 0
                                 JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS TTPN
                                      ON TTPN.ID = LL.LL_TINH_TRANG_ID
                        WHERE TTPN.TTPN_MA = '9999'
                          AND (LL.IS_DELETED = 0 OR LL.IS_DELETED IS NULL)),

        -- E2 ? Ch?t thông th??ng (return 171)
        --      THC_MA IN ('30','40','50') là ch?t-khi-?ang-tr?n / -TX / -TDC,
        --      ???c lo?i b?i EX_TRON / EX_TRICH_XUAT / EX_TAM_DINH_CHI.
        EX_CHET AS (SELECT KC.KTC_PN_LAI_LICH_ID AS LLID
                    FROM QLPN.PN_KET_THUC_CHETS KC
                             LEFT JOIN QLPN.DM_TRUONG_HOP_CHETS THC
                                       ON THC.ID = KC.KTC_DM_TRUONG_HOP_CHET_ID
                    WHERE KC.KTC_NGAY_CHET < V_DATE + 1 -- ??m c? nh?ng ph?m nhân ch?t ngày 14/xx/yyyy
--                       AND (THC.THC_MA NOT IN ('30', '40', '50') OR THC.THC_MA IS NULL)
                      AND (KC.IS_DELETED = 0 OR KC.IS_DELETED IS NULL)),

        -- E3 ? Tr?n tr?i, ch?a b?t l?i (return 131/132).
        --      Không l?c TTT_MA: tr?n-ch?t (TTT_MA='20') hay tr?n-th??ng ??u EXCLUDE.
        --      TRUNC kh?p v?i check 131 generic c?a hàm g?c (line 143).
        EX_TRON AS (SELECT TT.PHAM_NHAN_ID AS LLID
                    FROM QLPN.TRON_TRAIS TT
                    WHERE TT.NGAY_TRON < V_DATE + 1
                      AND (TT.NGAY_BAT_LAI IS NULL
                        OR TT.NGAY_BAT_LAI >= V_DATE + 1)
                      AND (TT.IS_DELETED = 0 OR TT.IS_DELETED IS NULL)),

        -- E4 ? Hu? án ?ang t? do (return 181). NGAY_TRO_LAI NULL ho?c > V_DATE.
        EX_HUY_AN AS (SELECT HA.PHAM_NHAN_ID AS LLID
                      FROM QLPN.HUY_ANS HA
                      WHERE HA.NGAY_TRA_TU_DO < V_DATE + 1
                        AND (HA.NGAY_TRO_LAI IS NULL
                          OR HA.NGAY_TRO_LAI >= V_DATE + 1)
                        AND (HA.IS_DELETED = 0 OR HA.IS_DELETED IS NULL)),

        -- E5 ? Chuy?n giao qu?c t? (return 127). V?nh vi?n lo?i.
        EX_CHUYEN_GIAO AS (SELECT CG.PNCG_LAI_LICH_ID AS LLID
                           FROM QLPN.PN_CHUYEN_GIAO CG
                           WHERE CG.PNCG_NGAY_CHUYEN_GIAO < V_DATE + 1
                             AND (CG.IS_DELETED = 0 OR CG.IS_DELETED IS NULL)),

        -- E6 ? Mi?n hình ph?t (return 124). V?nh vi?n lo?i.
        EX_MIEN_HP AS (SELECT MHP.PN_LAI_LICH_ID AS LLID
                       FROM QLPN.MIEN_HINH_PHATS MHP
                       WHERE MHP.MHP_NGAY_TU_DO < V_DATE + 1
                         AND (MHP.IS_DELETED = 0 OR MHP.IS_DELETED IS NULL)),

        -- E7 ? Chuy?n tr?i ?i, ch?a tr? l?i (return 161).
        --      THCT_MA = '50' là "chuy?n v?" n?i b? — không lo?i.
        EX_CHUYEN_TRAI AS (SELECT CT.PNCT_LAI_LICH_ID AS LLID
                           FROM QLPN.PHAM_NHAN_CHUYEN_TRAI CT
                                    LEFT JOIN QLPN.DM_TRUONG_HOP_CHUYEN_TRAIS THCT
                                              ON THCT.ID = CT.PNCT_TRUONG_HOP_CHUYEN_ID
                           WHERE CT.PNCT_NGAY_CHUYEN <= V_DATE
                             AND (CT.PNCT_NGAY_TRO_LAI IS NULL
                               OR CT.PNCT_NGAY_TRO_LAI > V_DATE)
                             AND (THCT.THCT_MA <> '50' OR THCT.THCT_MA IS NULL)
                             AND (CT.IS_DELETED = 0 OR CT.IS_DELETED IS NULL)),

        -- E8 ? Trích xu?t ?ang hi?u l?c (return 141-150, 126(TX)).
        --      [BUG FIX #1] Ch? lo?i khi:
        --        • TX_LOAI_LENH_ID = 1  ? m?i TTTX_MA (compound block 141/142/146
        --          + các status specific 143/144/145/150/126 trong hàm g?c)
        --        • HO?C TTTX_MA IN ('70','80','98') không có lenh filter
