        EX_DAC_XA AS (SELECT DX.PNLAI_LICH_ID AS LLID
                      FROM QLPN.PN_DAC_XAS DX
                      WHERE DX.DX_NGAY_THA <= V_DATE
                        AND (DX.IS_DELETED = 0 OR DX.IS_DELETED IS NULL)),

        -- E10 ? Tha tr??c có ?i?u ki?n, ch?a b? b?t l?i (return 126/TCK).
        EX_THA_CO_DK AS (SELECT TCK.PHAM_NHAN_ID AS LLID
                         FROM QLPN.THA_CO_DIEU_KIENS TCK
                         WHERE TCK.NGAY_THA < V_DATE
                           AND (TCK.NGAY_BAT_LAI IS NULL OR TCK.NGAY_BAT_LAI >= V_DATE + 1)
