--                                              AND (GR.GR_NGAY_KETTHUC IS NULL
--                                                OR GR.GR_NGAY_KETTHUC  > V_DATE)
--                                              AND (GR.IS_DELETED = 0 OR GR.IS_DELETED IS NULL))),

        -- E15 ? V_NGAY_RA_TRAI ?ã set <= V_DATE (return 121/125 — ??u EXCLUDE).
        --       [BUG FIX #2] Ph?i g?p ?? 7 b?ng nh? hàm g?c; b?n c? thi?u
        --       PN_KET_THUC_RA_TRAIS. Dùng UNION ALL — NOT EXISTS không c?n dedup.
        --       M?t s? b?ng ?ã có ? các EX_* khác (E5/E6/E9/E11); ? ?ây b? sung
        --       các tr??ng h?p prisoner ?ã quay l?i (NGAY_TRO_LAI/NGAY_BAT_LAI
        --       <= V_DATE) mà E4/E10 không b?t ???c — vì hàm g?c v?n coi ?ã
        --       ra tr?i do MIN(NGAY_RA) <= V_DATE.
        EX_NGAY_RA_TRAI AS (
            -- Theo hàm ALT hi?n t?i, V_NGAY_RA_TRAI ???c l?y t? THA_NGAY_HET_HAN.
            -- N?u THA_NGAY_HET_HAN <= V_DATE thì prisoner không còn thu?c 111/112/113
            -- (s? r?i vào 121 ho?c 125), nên ph?i EXCLUDE.
--            SELECT ptha.THA_PNLAI_LICH_ID AS LLID
--            FROM PN_THI_HANH_AN ptha
--            WHERE ptha.THA_NGAY_HET_HAN <= V_DATE
--              AND ptha.IS_DELETED = 0
              
                SELECT tl.pn_id AS LLID
                  FROM (
                        SELECT tha.THA_PNLAI_LICH_ID AS pn_id,
                               tha.THA_NGAY_HET_HAN,
                               ROW_NUMBER() OVER (
                                   PARTITION BY tha.THA_PNLAI_LICH_ID
                                   ORDER BY NVL(tha.THA_NGAY_BAN_AN, tha.CREATION_TIME) DESC, tha.ID DESC
                               ) rn
                          FROM QLPN.PN_THI_HANH_AN tha
                         WHERE tha.THA_NGAY_HET_HAN IS NOT NULL and tha.THA_NGAY_HET_HAN <= V_DATE
                           AND NVL(tha.IS_DELETED, 0) = 0
                       ) tl
                 WHERE tl.rn = 1              
--             SELECT HA.PHAM_NHAN_ID AS LLID
--             FROM QLPN.HUY_ANS HA
--             WHERE HA.NGAY_TRA_TU_DO IS NOT NULL
--               AND HA.NGAY_TRA_TU_DO  <= V_DATE
--               AND (HA.IS_DELETED = 0 OR HA.IS_DELETED IS NULL)
--             UNION ALL
--             -- 2. MIEN_HINH_PHATS
--             SELECT MHP.PN_LAI_LICH_ID
--             FROM QLPN.MIEN_HINH_PHATS MHP
--             WHERE MHP.MHP_NGAY_TU_DO IS NOT NULL
--               AND MHP.MHP_NGAY_TU_DO  <= V_DATE
--               AND (MHP.IS_DELETED = 0 OR MHP.IS_DELETED IS NULL)
--             UNION ALL
--             -- 3. GIAM_THOI_HANS
--             SELECT GTH.PHAM_NHAN_ID
--             FROM QLPN.GIAM_THOI_HANS GTH
--             WHERE GTH.NGAY_THA_GIAM_HET_AN IS NOT NULL
--               AND GTH.NGAY_THA_GIAM_HET_AN  <= V_DATE
--               AND (GTH.IS_DELETED = 0 OR GTH.IS_DELETED IS NULL)
--             UNION ALL
--             -- 4. PN_DAC_XAS
--             SELECT DX.PNLAI_LICH_ID
--             FROM QLPN.PN_DAC_XAS DX
--             WHERE DX.DX_NGAY_THA IS NOT NULL
--               AND DX.DX_NGAY_THA  <= V_DATE
--               AND (DX.IS_DELETED = 0 OR DX.IS_DELETED IS NULL)
--             UNION ALL
--             -- 5. THA_CO_DIEU_KIENS: m?i NGAY_THA <= V_DATE (k? c? ?ã NGAY_BAT_LAI)
--             SELECT TCK.PHAM_NHAN_ID
--             FROM QLPN.THA_CO_DIEU_KIENS TCK
--             WHERE TCK.NGAY_THA IS NOT NULL
--               AND TCK.NGAY_THA  <= V_DATE
--               AND (TCK.IS_DELETED = 0 OR TCK.IS_DELETED IS NULL)
--             UNION ALL
--             -- 6. PN_CHUYEN_GIAO
--             SELECT CG.PNCG_LAI_LICH_ID
--             FROM QLPN.PN_CHUYEN_GIAO CG
--             WHERE CG.PNCG_NGAY_CHUYEN_GIAO IS NOT NULL
--               AND CG.PNCG_NGAY_CHUYEN_GIAO  <= V_DATE
--               AND (CG.IS_DELETED = 0 OR CG.IS_DELETED IS NULL)
--             UNION ALL
--             -- 7. PN_KET_THUC_RA_TRAIS  ? b?ng b? thi?u ? b?n ALT c?
--             SELECT KT.KTRT_PN_LAI_LICH_ID
--             FROM QLPN.PN_KET_THUC_RA_TRAIS KT
--             WHERE KT.KTRT_NGAY_THA IS NOT NULL
--               AND KT.KTRT_NGAY_THA  <= V_DATE
--               AND (KT.IS_DELETED = 0 OR KT.IS_DELETED IS NULL)
        ),

        /*==============================================================
         * STEP 2 — UNION ALL EXCLUSIONS
         * UNION ALL (không UNION) — NOT EXISTS ? STEP 3 t? dedup.
         *============================================================*/
        ALL_EXCLUDED AS (SELECT LLID
                         FROM EX_TERMINAL
                         UNION ALL
                         SELECT LLID
                         FROM EX_CHET
                         UNION ALL
                         SELECT LLID
                         FROM EX_TRON
                         UNION ALL
                         SELECT LLID
                         FROM EX_HUY_AN
                         UNION ALL
                         SELECT LLID
                         FROM EX_CHUYEN_GIAO
                         UNION ALL
                         SELECT LLID
                         FROM EX_MIEN_HP
                         UNION ALL
                         SELECT LLID
                         FROM EX_CHUYEN_TRAI
                         UNION ALL
                         SELECT LLID
                         FROM EX_TRICH_XUAT
                         UNION ALL
                         SELECT LLID
                         FROM EX_DAC_XA
                         UNION ALL
                         SELECT LLID
                         FROM EX_THA_CO_DK
                         UNION ALL
                         SELECT LLID
                         FROM EX_GIAM_HET_AN
                         UNION ALL
                         SELECT LLID
                         FROM EX_HOAN_THA
                         UNION ALL
                         SELECT LLID
                         FROM EX_TAM_DINH_CHI
                         UNION ALL
                         SELECT LLID
                         FROM EX_NGAY_RA_TRAI),

        /*==============================================================
         * STEP 3 — ACTIVE PRISONERS
         * = ?ã ??n tr?i (ARRIVED) VÀ không trong b?t k? t?p exclude nào.
         * T??ng ???ng: FN_GET_TINH_TRANG tr? '111' ho?c '112'.
         *============================================================*/
        ACTIVE_PN AS (SELECT A.LLID
                      FROM ARRIVED A
                      WHERE NOT EXISTS (SELECT 1
                                        FROM ALL_EXCLUDED E
                                        WHERE E.LLID = A.LLID)),

        /*==============================================================
         * STEP 3.1 — ACTIVE STATUS BUCKETS
         * Phân lo?i t?p active theo precedence c?a hàm:
         *   112 -> gi?m riêng active
         *   113 -> ch?a b?nh active, nh?ng không gi?m riêng
         *   111 -> active còn l?i
         *============================================================*/
        ACTIVE_GR AS (SELECT DISTINCT GR.GR_PN_LAI_LICH_ID AS LLID
                      FROM QLPN.PN_GIAM_RIENGS GR
                      WHERE (GR.GR_NGAY_KETTHUC IS NULL
                          OR GR.GR_NGAY_KETTHUC > V_DATE)
                        AND (GR.IS_DELETED = 0 OR GR.IS_DELETED IS NULL)),

        ACTIVE_CB AS (SELECT DISTINCT CB.PHAM_NHAN_ID AS LLID
                      FROM QLPN.CHUA_BENH_BAT_BUOCS CB
                      WHERE (CB.NGAY_KET_THUC IS NULL
                          OR CB.NGAY_KET_THUC > V_DATE)
                        AND (CB.IS_DELETED = 0 OR CB.IS_DELETED IS NULL)),

        ACTIVE_STATUS AS (SELECT AP.LLID,
                                 CASE
                                     WHEN EXISTS (SELECT 1
                                                  FROM ACTIVE_GR AGR
                                                  WHERE AGR.LLID = AP.LLID) THEN '112'
                                     WHEN EXISTS (SELECT 1
                                                  FROM ACTIVE_CB ACB
                                                  WHERE ACB.LLID = AP.LLID) THEN '113'
                                     ELSE '111'
                                     END AS LOGIC_STATUS
                          FROM ACTIVE_PN AP)

    /*==============================================================
     * STEP 4 — FINAL SELECT (gi?ng SELECT c?a SP_POPULATE_TK_PT80 g?c)
     *============================================================*/
    SELECT LL.ID,
           GT.GT_MA,

           -- MA_TOI_DANH: ';'-separated list of TD_MA t? PN_BAN_AN_KHACS
           TD_FIRST.TD_MA                                     AS MA_TOI_DANH,
           TD_FIRST.TD_CHUONG,

           LL.LL_SO_TIEN_AN,
           LL.LL_GHI_CHU_RIENG,
           TO_NUMBER(NVL(SUBSTR(LL.LL_NGAY_SINH, -4), 1970))  AS NAM_SINH, -- raw text, parse qua FN_PARSE_NGAY_SINH
           QT.QT_MA,
           DT.DT_MA,
           TG_RELIGION.TG_MA,
           HV.HV_MA,
           PD.PD_MA,

           -- NGAY_PHAM_TOI: earliest THA_NGAY_PHAM_TOI
           EXTRACT(YEAR FROM NVL(ptha.THA_NGAY_PHAM_TOI, SYSDATE))          AS NAM_PHAM_TOI,

           BT.BT_MA,
           TO_NCHAR(NVL(TP.TP_MA, 0)),
           NN.NN_MA,
           LL.LL_HO_TEN,
           LL.LL_TRAI_GIAM_ID,
           TG_PRISON.TG_MA,
           CASE
               WHEN MTG_THANG IS NOT NULL AND MTG_NGAY IS NOT NULL
                   THEN MTG.MTG_THANG * 30 + MTG.MTG_NGAY END AS MUC_AN_NGAY

    FROM ACTIVE_STATUS AP
             JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = AP.LLID AND LL.IS_DELETED = 0
             JOIN QLPN.PN_THI_HANH_AN ptha ON LL.ID = ptha.THA_PNLAI_LICH_ID AND ptha.IS_DELETED = 0
             LEFT JOIN QLPN.DM_GIOI_TINHS GT ON GT.ID = LL.LL_DM_GIOI_TINH_ID AND GT.IS_DELETED = 0
             LEFT JOIN QLPN.DM_TOI_DANHS TD_FIRST
                       ON TD_FIRST.ID = TO_NUMBER(
                               SUBSTR(
                                       ptha.THA_TOI_DANH,
                                       2,
                                       INSTR(TRANSLATE(ptha.THA_TOI_DANH, ']', ','), ',', 1) - 2
                               ))
                           AND (TD_FIRST.IS_DELETED = 0 OR TD_FIRST.IS_DELETED IS NULL)
             LEFT JOIN DM_MA_THOI_GIANS MTG ON ptha.THA_MA_AN_PHAT = MTG.MTG_MA AND MTG.IS_DELETED = 0
             LEFT JOIN QLPN.DM_QUOC_TICHS QT ON QT.ID = LL.LL_DM_QUOC_TICH_ID AND QT.IS_DELETED = 0
             LEFT JOIN QLPN.DM_DAN_TOCS DT ON DT.ID = LL.LL_DM_DAN_TOC_ID AND DT.IS_DELETED = 0
             LEFT JOIN QLPN.DM_TON_GIAOS TG_RELIGION
                       ON TG_RELIGION.ID = LL.LL_DM_TON_GIAO_ID AND TG_RELIGION.IS_DELETED = 0
             LEFT JOIN QLPN.DM_HOC_VANS HV ON HV.ID = LL.LL_DM_HOC_VAN_ID AND HV.IS_DELETED = 0
             LEFT JOIN QLPN.DM_NGHE_NGHIEPS NN ON NN.ID = LL.LL_DM_NGHE_NGHIEP_ID AND NN.IS_DELETED = 0
             LEFT JOIN QLPN.DM_PHAN_DOIS PD ON PD.ID = LL.LL_PHAN_DOI_ID AND PD.IS_DELETED = 0
             LEFT JOIN QLPN.DM_BENH_TATS BT ON BT.ID = LL.LL_BENH_TAT_VAO_ID AND BT.IS_DELETED = 0
             LEFT JOIN QLPN.DM_TRAI_GIAMS TG_PRISON ON TG_PRISON.ID = LL.LL_TRAI_GIAM_ID AND TG_PRISON.IS_DELETED = 0
             LEFT JOIN QLPN.DM_TAI_PHAMS TP ON TP.ID = LL.LL_TAI_PHAM AND TP.IS_DELETED = 0

    WHERE (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);

    -- ----------------------------------------------------------------
    -- KHÔNG COMMIT — caller (SP_GET_PT80) qu?n lý transaction.
    -- ----------------------------------------------------------------

END SP_POPULATE_TK_PT80_ALT;

/
--------------------------------------------------------
--  DDL for Procedure SP_POPULATE_TK_PT80_NU
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_POPULATE_TK_PT80_NU" (
    V_DATE DATE,
    V_TRAI_GIAM_ID NUMBER DEFAULT NULL
) IS
BEGIN
    DELETE FROM QLPN.TK_PT80;

    INSERT INTO QLPN.TK_PT80 (PN_LAI_LICH_ID, MA_GIOI_TINH, MA_TOI_DANH, MA_MUC_AN_PHAT,
                              SO_TIEN_AN, GHI_CHU_RIENG, NGAY_SINH_PN, MA_QUOC_TICH,
                              MA_DAN_TOC, MA_TON_GIAO, MA_HOC_VAN, MA_PHAN_DOI, NGAY_PHAM_TOI,
                              MA_BENH_TAT_VAO, MA_TAI_PHAM, MA_NGHE_NGHIEP, ORDER_HO_TEN,
                              TRAI_GIAM_ID, TRAI_GIAM_MA)
    SELECT LL.ID,
           GT.GT_MA,
           (SELECT TO_NUMBER(SUBSTR(THA.THA_TOI_DANH, 2,
                                    NVL(NULLIF(INSTR(THA.THA_TOI_DANH, ','), 0), INSTR(THA.THA_TOI_DANH, ']')) - 2))
            FROM QLPN.PN_THI_HANH_AN THA
            WHERE THA.THA_PNLAI_LICH_ID = LL.ID
              AND NVL(THA.IS_DELETED, 0) = 0) AS MA_TOI_DANH,
           (SELECT MIN(THA.THA_MA_AN_PHAT) KEEP (DENSE_RANK FIRST ORDER BY THA.THA_NGAY_DEN_TRAI)
            FROM QLPN.PN_THI_HANH_AN THA
            WHERE THA.THA_PNLAI_LICH_ID = LL.ID
              AND NVL(THA.IS_DELETED, 0) = 0) AS MA_MUC_AN_PHAT,
           LL.LL_SO_TIEN_AN,
           LL.LL_GHI_CHU_RIENG,
           LL.LL_NGAY_SINH                    AS NGAY_SINH_PN,
           QT.QT_MA,
           DT.DT_MA,
           TG_RELIGION.TG_MA,
           HV.HV_MA,
           PD.PD_MA,
           (SELECT MIN(CAST(THA.THA_NGAY_PHAM_TOI AS DATE))
            FROM QLPN.PN_THI_HANH_AN THA
            WHERE THA.THA_PNLAI_LICH_ID = LL.ID
              AND NVL(THA.IS_DELETED, 0) = 0) AS NGAY_PHAM_TOI,
           BT.BT_MA,
           TO_NCHAR(NVL(dmtp.TP_MA, 0)),
           NN.NN_MA,
           LL.LL_HO_TEN,
           LL.LL_TRAI_GIAM_ID,
           TG_PRISON.TG_MA
    FROM QLPN.PN_LAI_LICHS LL
             JOIN PN_THI_HANH_AN ptha ON LL.ID = ptha.THA_PNLAI_LICH_ID AND ptha.IS_DELETED = 0

             JOIN QLPN.DM_GIOI_TINHS GT ON GT.ID = LL.LL_DM_GIOI_TINH_ID
             LEFT JOIN QLPN.DM_QUOC_TICHS QT ON QT.ID = LL.LL_DM_QUOC_TICH_ID
             LEFT JOIN QLPN.DM_DAN_TOCS DT ON DT.ID = LL.LL_DM_DAN_TOC_ID
             LEFT JOIN QLPN.DM_TON_GIAOS TG_RELIGION ON TG_RELIGION.ID = LL.LL_DM_TON_GIAO_ID
             LEFT JOIN QLPN.DM_HOC_VANS HV ON HV.ID = LL.LL_DM_HOC_VAN_ID
             LEFT JOIN QLPN.DM_NGHE_NGHIEPS NN ON NN.ID = LL.LL_DM_NGHE_NGHIEP_ID
             LEFT JOIN QLPN.DM_PHAN_DOIS PD ON PD.ID = LL.LL_PHAN_DOI_ID
             LEFT JOIN QLPN.DM_BENH_TATS BT ON BT.ID = LL.LL_BENH_TAT_VAO_ID
             LEFT JOIN QLPN.DM_TRAI_GIAMS TG_PRISON ON TG_PRISON.ID = LL.LL_TRAI_GIAM_ID
             LEFT JOIN QLPN.DM_TAI_PHAMS dmtp ON LL.LL_TAI_PHAM = dmtp.ID
    WHERE NVL(LL.IS_DELETED, 0) = 0
      AND GT.GT_MA = '2'
      AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)
      AND QLPN.FN_GET_TINH_TRANG_TAI_NGAY_XET(LL.ID, V_DATE) IN ('111', '112');

--     COMMIT;
END SP_POPULATE_TK_PT80_NU;





/
--------------------------------------------------------
--  DDL for Procedure SP_POPULATE_TK_PT80_NU_ALT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_POPULATE_TK_PT80_NU_ALT" (
    V_DATE DATE,
    V_TRAI_GIAM_ID NUMBER DEFAULT NULL
) IS
BEGIN

--     DELETE FROM QLPN.TK_PT80;

    INSERT INTO QLPN.TK_PT80 (PN_LAI_LICH_ID, MA_GIOI_TINH, MA_TOI_DANH, CHUONG_TD,
                              SO_TIEN_AN, GHI_CHU_RIENG, NAM_SINH, MA_QUOC_TICH,
                              MA_DAN_TOC, MA_TON_GIAO, MA_HOC_VAN, MA_PHAN_DOI, NAM_PHAM_TOI,
                              MA_BENH_TAT_VAO, MA_TAI_PHAM, MA_NGHE_NGHIEP, ORDER_HO_TEN,
                              TRAI_GIAM_ID, TRAI_GIAM_MA, MUC_AN_NGAY)
    WITH
        /*==============================================================
         * STEP 0 - SCOPE
         * Tap pham nhan thuoc pham vi bao cao, loc theo trai giam ngay tu dau.
         * Day dieu kien V_TRAI_GIAM_ID len som nhat de toan bo pipeline phia sau
         * (ARRIVED, cac EX_*, ACTIVE_*) chi xu ly pham nhan cua trai duoc chon.
         * Khi V_TRAI_GIAM_ID IS NULL: SCOPE = toan bo dan so (bao cao toan quoc).
         *============================================================*/
        SCOPE AS (SELECT LL.ID AS LLID
                  FROM QLPN.PN_LAI_LICHS LL
                  WHERE LL.IS_DELETED = 0
                    AND (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID)),
        /*==============================================================
         * STEP 1 - ARRIVED
         * Pham nhan co it nhat mot THA voi THA_NGAY_DEN_TRAI <= V_DATE.
         * Equivalent voi "MIN(NGAY_DEN_TRAI) <= V_DATE" cua ham goc.
         *============================================================*/
        ARRIVED AS (SELECT DISTINCT THA.THA_PNLAI_LICH_ID AS LLID
                    FROM QLPN.PN_THI_HANH_AN THA
                             JOIN SCOPE S ON S.LLID = THA.THA_PNLAI_LICH_ID
                    WHERE THA.THA_NGAY_DEN_TRAI IS NOT NULL
                      AND THA.THA_NGAY_DEN_TRAI < V_DATE + 1
                      AND THA.IS_DELETED = 0),

        /*==============================================================
         * EXCLUSION CTEs - moi CTE = mot tap KHONG thuoc '111'/'112'.
         *============================================================*/

        -- E1 - Ket thuc ho so (return 9999)
        EX_TERMINAL AS (SELECT LL.ID AS LLID
                        FROM QLPN.PN_LAI_LICHS LL
                                 JOIN PN_THI_HANH_AN ptha ON ptha.THA_PNLAI_LICH_ID = LL.ID AND ptha.IS_DELETED = 0
                                 JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS TTPN
                                      ON TTPN.ID = LL.LL_TINH_TRANG_ID
                        WHERE TTPN.TTPN_MA = '9999'
                          AND (LL.IS_DELETED = 0 OR LL.IS_DELETED IS NULL)),

        -- E2 - Chet thong thuong (return 171)
        --      THC_MA IN ('30','40','50') la chet-khi-dang-tron / -TX / -TDC,
        --      duoc loai bo boi EX_TRON / EX_TRICH_XUAT / EX_TAM_DINH_CHI.
        EX_CHET AS (SELECT KC.KTC_PN_LAI_LICH_ID AS LLID
                    FROM QLPN.PN_KET_THUC_CHETS KC
                             LEFT JOIN QLPN.DM_TRUONG_HOP_CHETS THC
                                       ON THC.ID = KC.KTC_DM_TRUONG_HOP_CHET_ID
                    WHERE KC.KTC_NGAY_CHET < V_DATE + 1
                      AND (KC.IS_DELETED = 0 OR KC.IS_DELETED IS NULL)),

        -- E3 - Tron trai, chua bat lai (return 131/132).
        --      Khong loc TTT_MA: tron-chet (TTT_MA='20') hay tron-thuong deu EXCLUDE.
        --      TRUNC khop voi check 131 generic cua ham goc.
        EX_TRON AS (SELECT TT.PHAM_NHAN_ID AS LLID
                    FROM QLPN.TRON_TRAIS TT
                    WHERE TT.NGAY_TRON < V_DATE + 1
                      AND (TT.NGAY_BAT_LAI IS NULL
                        OR TT.NGAY_BAT_LAI >= V_DATE + 1)
                      AND (TT.IS_DELETED = 0 OR TT.IS_DELETED IS NULL)),

        -- E4 - Huy an dang tu do (return 181). NGAY_TRO_LAI NULL hoac > V_DATE.
        EX_HUY_AN AS (SELECT HA.PHAM_NHAN_ID AS LLID
                      FROM QLPN.HUY_ANS HA
                      WHERE HA.NGAY_TRA_TU_DO < V_DATE + 1
                        AND (HA.NGAY_TRO_LAI IS NULL
                          OR HA.NGAY_TRO_LAI >= V_DATE + 1)
                        AND (HA.IS_DELETED = 0 OR HA.IS_DELETED IS NULL)),

        -- E5 - Chuyen giao quoc te (return 127). Vinh vien loai.
        EX_CHUYEN_GIAO AS (SELECT CG.PNCG_LAI_LICH_ID AS LLID
                           FROM QLPN.PN_CHUYEN_GIAO CG
                           WHERE CG.PNCG_NGAY_CHUYEN_GIAO < V_DATE + 1
                             AND (CG.IS_DELETED = 0 OR CG.IS_DELETED IS NULL)),

        -- E6 - Mien hinh phat (return 124). Vinh vien loai.
        EX_MIEN_HP AS (SELECT MHP.PN_LAI_LICH_ID AS LLID
                       FROM QLPN.MIEN_HINH_PHATS MHP
                       WHERE MHP.MHP_NGAY_TU_DO < V_DATE + 1
                         AND (MHP.IS_DELETED = 0 OR MHP.IS_DELETED IS NULL)),

        -- E7 - Chuyen trai di, chua tro lai (return 161).
        --      THCT_MA = '50' la "chuyen ve" noi bo - khong loai.
        EX_CHUYEN_TRAI AS (SELECT CT.PNCT_LAI_LICH_ID AS LLID
                           FROM QLPN.PHAM_NHAN_CHUYEN_TRAI CT
                                    LEFT JOIN QLPN.DM_TRUONG_HOP_CHUYEN_TRAIS THCT
                                              ON THCT.ID = CT.PNCT_TRUONG_HOP_CHUYEN_ID
                           WHERE CT.PNCT_NGAY_CHUYEN <= V_DATE
                             AND (CT.PNCT_NGAY_TRO_LAI IS NULL
                               OR CT.PNCT_NGAY_TRO_LAI > V_DATE)
                             AND (CT.IS_DELETED = 0 OR CT.IS_DELETED IS NULL)),

        -- E8 - Trich xuat dang hieu luc (return 141-150, 126(TX)).
        EX_TRICH_XUAT AS (SELECT TX.PHAM_NHAN_ID AS LLID
                          FROM QLPN.TRICH_XUATS TX
                                   LEFT JOIN QLPN.DM_TINH_TRANG_TRICH_XUATS TTTX
                                             ON TTTX.ID = TX.TX_TINH_TRANG_ID
                          WHERE TX.TX_NGAY_TRICH_XUAT <= V_DATE
                            AND (TX.TX_NGAY_TRA IS NULL OR TX.TX_NGAY_TRA > V_DATE)
                            AND (TX.IS_DELETED = 0 OR TX.IS_DELETED IS NULL)),

        -- E9 - Dac xa (return 123). DX_NGAY_THA NOT NULL -> vinh vien loai.
        EX_DAC_XA AS (SELECT DX.PNLAI_LICH_ID AS LLID
                      FROM QLPN.PN_DAC_XAS DX
                      WHERE DX.DX_NGAY_THA <= V_DATE
                        AND (DX.IS_DELETED = 0 OR DX.IS_DELETED IS NULL)),

        -- E10 - Tha truoc co dieu kien, chua bi bat lai (return 126/TCK).
        EX_THA_CO_DK AS (SELECT TCK.PHAM_NHAN_ID AS LLID
                         FROM QLPN.THA_CO_DIEU_KIENS TCK
                         WHERE TCK.NGAY_THA < V_DATE
                           AND (TCK.NGAY_BAT_LAI IS NULL OR TCK.NGAY_BAT_LAI >= V_DATE + 1)
                           AND (TCK.IS_DELETED = 0 OR TCK.IS_DELETED IS NULL)),

        -- E11 - Giam het an (return 122). Vinh vien loai.
        EX_GIAM_HET_AN AS (SELECT GTH.PHAM_NHAN_ID AS LLID
                           FROM QLPN.GIAM_THOI_HANS GTH
                           WHERE GTH.NGAY_THA_GIAM_HET_AN <= V_DATE
                             AND (GTH.IS_DELETED = 0 OR GTH.IS_DELETED IS NULL)),

        -- E12 - Hoan thi hanh an dang hieu luc (return 191).
        --       Ham goc dung strict <, khong <= - giu y nguyen.
        EX_HOAN_THA AS (SELECT HTHA.PHAM_NHAN_ID AS LLID
                        FROM QLPN.HOAN_THI_HANH_ANS HTHA
                        WHERE HTHA.NGAY_HOAN < V_DATE
                          AND (HTHA.NGAY_THI_HANH_AN IS NULL OR
                               HTHA.NGAY_THI_HANH_AN > V_DATE)
                          AND (HTHA.IS_DELETED = 0 OR HTHA.IS_DELETED IS NULL)),

        -- E13 - Tam dinh chi dang hieu luc (return 151-159).
        EX_TAM_DINH_CHI AS (SELECT TDC.PHAM_NHAN_ID AS LLID
                            FROM QLPN.TAM_DINH_CHIS TDC
                                     LEFT JOIN QLPN.DM_TINH_TRANG_TAM_DINH_CHIES TTTDC
                                               ON TTTDC.ID = TDC.TINH_TRANG_ID
                            WHERE TDC.NGAY_TDC <= V_DATE
                              AND (TDC.NGAY_LAI IS NULL OR TDC.NGAY_LAI > V_DATE)
                              AND (TDC.LOAI_QUYET_DINH_ID = 1
                                OR (TTTDC.TTTDC_MA = '50' OR TTTDC.TTTDC_MA IS NULL))
                              AND (TDC.IS_DELETED = 0 OR TDC.IS_DELETED IS NULL)),

        -- E15 - V_NGAY_RA_TRAI da set <= V_DATE (return 121/125 - deu EXCLUDE).
        EX_NGAY_RA_TRAI AS (
            SELECT ptha.THA_PNLAI_LICH_ID AS LLID
            FROM PN_THI_HANH_AN ptha
            WHERE ptha.THA_NGAY_HET_HAN <= V_DATE
              AND ptha.IS_DELETED = 0
        ),

        /*==============================================================
         * STEP 2 - UNION ALL EXCLUSIONS
         * UNION ALL (khong UNION) - NOT EXISTS o STEP 3 tu dedup.
         *============================================================*/
        ALL_EXCLUDED AS (SELECT LLID
                         FROM EX_TERMINAL
                         UNION ALL
                         SELECT LLID
                         FROM EX_CHET
                         UNION ALL
                         SELECT LLID
                         FROM EX_TRON
                         UNION ALL
                         SELECT LLID
                         FROM EX_HUY_AN
                         UNION ALL
                         SELECT LLID
                         FROM EX_CHUYEN_GIAO
                         UNION ALL
                         SELECT LLID
                         FROM EX_MIEN_HP
                         UNION ALL
                         SELECT LLID
                         FROM EX_CHUYEN_TRAI
                         UNION ALL
                         SELECT LLID
                         FROM EX_TRICH_XUAT
                         UNION ALL
                         SELECT LLID
                         FROM EX_DAC_XA
                         UNION ALL
                         SELECT LLID
                         FROM EX_THA_CO_DK
                         UNION ALL
                         SELECT LLID
                         FROM EX_GIAM_HET_AN
                         UNION ALL
                         SELECT LLID
                         FROM EX_HOAN_THA
                         UNION ALL
                         SELECT LLID
                         FROM EX_TAM_DINH_CHI
                         UNION ALL
                         SELECT LLID
                         FROM EX_NGAY_RA_TRAI),

        /*==============================================================
         * STEP 3 - ACTIVE PRISONERS
         * = da den trai (ARRIVED) VA khong trong bat ky tap exclude nao.
         * Tuong duong: FN_GET_TINH_TRANG tra '111' hoac '112'.
         *============================================================*/
        ACTIVE_PN AS (SELECT A.LLID
                      FROM ARRIVED A
                      WHERE NOT EXISTS (SELECT 1
                                        FROM ALL_EXCLUDED E
                                        WHERE E.LLID = A.LLID)),

        /*==============================================================
         * STEP 3.1 - ACTIVE STATUS BUCKETS
         * Phan loai tap active theo precedence cua ham:
         *   112 -> giam rieng active
         *   113 -> chua benh active, nhung khong giam rieng
         *   111 -> active con lai
         *============================================================*/
        ACTIVE_GR AS (SELECT DISTINCT GR.GR_PN_LAI_LICH_ID AS LLID
                      FROM QLPN.PN_GIAM_RIENGS GR
                      WHERE (GR.GR_NGAY_KETTHUC IS NULL
                          OR GR.GR_NGAY_KETTHUC > V_DATE)
                        AND (GR.IS_DELETED = 0 OR GR.IS_DELETED IS NULL)),

        ACTIVE_CB AS (SELECT DISTINCT CB.PHAM_NHAN_ID AS LLID
                      FROM QLPN.CHUA_BENH_BAT_BUOCS CB
                      WHERE (CB.NGAY_KET_THUC IS NULL
                          OR CB.NGAY_KET_THUC > V_DATE)
                        AND (CB.IS_DELETED = 0 OR CB.IS_DELETED IS NULL)),

        ACTIVE_STATUS AS (SELECT AP.LLID,
                                 CASE
                                     WHEN EXISTS (SELECT 1
                                                  FROM ACTIVE_GR AGR
                                                  WHERE AGR.LLID = AP.LLID) THEN '112'
                                     WHEN EXISTS (SELECT 1
                                                  FROM ACTIVE_CB ACB
                                                  WHERE ACB.LLID = AP.LLID) THEN '113'
                                     ELSE '111'
                                     END AS LOGIC_STATUS
                          FROM ACTIVE_PN AP)

    /*==============================================================
     * STEP 4 - FINAL SELECT
     * Giong SELECT cua SP_POPULATE_TK_PT80_ALT, bo sung filter gioi tinh nu.
     *============================================================*/
    SELECT LL.ID,
           GT.GT_MA,
           TD_FIRST.TD_MA                                     AS MA_TOI_DANH,
           TD_FIRST.TD_CHUONG,
           LL.LL_SO_TIEN_AN,
           LL.LL_GHI_CHU_RIENG,
           TO_NUMBER(NVL(SUBSTR(LL.LL_NGAY_SINH, -4), 1970))  AS NAM_SINH,
           QT.QT_MA,
           DT.DT_MA,
           TG_RELIGION.TG_MA,
           HV.HV_MA,
           PD.PD_MA,
           EXTRACT(YEAR FROM NVL(ptha.THA_NGAY_PHAM_TOI, SYSDATE))          AS NAM_PHAM_TOI,
           BT.BT_MA,
           TO_NCHAR(NVL(TP.TP_MA, 0)),
           NN.NN_MA,
           LL.LL_HO_TEN,
           LL.LL_TRAI_GIAM_ID,
           TG_PRISON.TG_MA,
           CASE
               WHEN MTG_THANG IS NOT NULL AND MTG_NGAY IS NOT NULL
                   THEN MTG.MTG_THANG * 30 + MTG.MTG_NGAY END AS MUC_AN_NGAY

    FROM ACTIVE_STATUS AP
             JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = AP.LLID AND LL.IS_DELETED = 0
             JOIN QLPN.PN_THI_HANH_AN ptha ON LL.ID = ptha.THA_PNLAI_LICH_ID AND ptha.IS_DELETED = 0
             JOIN QLPN.DM_GIOI_TINHS GT
                  ON GT.ID = LL.LL_DM_GIOI_TINH_ID AND GT.IS_DELETED = 0 AND GT.GT_MA = '2'
             LEFT JOIN QLPN.DM_TOI_DANHS TD_FIRST
                       ON TD_FIRST.ID = TO_NUMBER(
                               SUBSTR(
                                       ptha.THA_TOI_DANH,
                                       2,
                                       INSTR(TRANSLATE(ptha.THA_TOI_DANH, ']', ','), ',', 1) - 2
                               ))
                           AND (TD_FIRST.IS_DELETED = 0 OR TD_FIRST.IS_DELETED IS NULL)
             LEFT JOIN DM_MA_THOI_GIANS MTG ON ptha.THA_MA_AN_PHAT = MTG.MTG_MA AND MTG.IS_DELETED = 0
             LEFT JOIN QLPN.DM_QUOC_TICHS QT ON QT.ID = LL.LL_DM_QUOC_TICH_ID AND QT.IS_DELETED = 0
             LEFT JOIN QLPN.DM_DAN_TOCS DT ON DT.ID = LL.LL_DM_DAN_TOC_ID AND DT.IS_DELETED = 0
             LEFT JOIN QLPN.DM_TON_GIAOS TG_RELIGION
                       ON TG_RELIGION.ID = LL.LL_DM_TON_GIAO_ID AND TG_RELIGION.IS_DELETED = 0
             LEFT JOIN QLPN.DM_HOC_VANS HV ON HV.ID = LL.LL_DM_HOC_VAN_ID AND HV.IS_DELETED = 0
             LEFT JOIN QLPN.DM_NGHE_NGHIEPS NN ON NN.ID = LL.LL_DM_NGHE_NGHIEP_ID AND NN.IS_DELETED = 0
             LEFT JOIN QLPN.DM_PHAN_DOIS PD ON PD.ID = LL.LL_PHAN_DOI_ID AND PD.IS_DELETED = 0
             LEFT JOIN QLPN.DM_BENH_TATS BT ON BT.ID = LL.LL_BENH_TAT_VAO_ID AND BT.IS_DELETED = 0
             LEFT JOIN QLPN.DM_TRAI_GIAMS TG_PRISON ON TG_PRISON.ID = LL.LL_TRAI_GIAM_ID AND TG_PRISON.IS_DELETED = 0
             LEFT JOIN QLPN.DM_TAI_PHAMS TP ON TP.ID = LL.LL_TAI_PHAM AND TP.IS_DELETED = 0

    WHERE (V_TRAI_GIAM_ID IS NULL OR LL.LL_TRAI_GIAM_ID = V_TRAI_GIAM_ID);

END SP_POPULATE_TK_PT80_NU_ALT;



/
--------------------------------------------------------
--  DDL for Procedure SP_QLPN_GET_TK_DAC_XA_THA_CDK_DASHBOARD
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_QLPN_GET_TK_DAC_XA_THA_CDK_DASHBOARD" (
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL
) AS
BEGIN
    DELETE FROM QLPN.PN_TK_DAC_XA_THA_CDK_DASHBOARD
     WHERE (p_ma_trai_giam IS NULL OR MA_TRAI_GIAM = p_ma_trai_giam);

    INSERT INTO QLPN.PN_TK_DAC_XA_THA_CDK_DASHBOARD (
        NAM,
        LOAI_THA,
        DOT_THA,
        MA_TRAI_GIAM,
        SO_LUONG,
        CREATION_TIME
    )
    WITH
    trai_map AS (
        SELECT /*+ MATERIALIZE */ ID, TG_MA
        FROM QLPN.DM_TRAI_GIAMS
        WHERE NVL(IS_DELETED, 0) = 0
          AND (p_ma_trai_giam IS NULL OR TG_MA = p_ma_trai_giam)
    ),
    duoc_dac_xa_ids AS (
        -- DM_DUOC_DAC_XAS.ID -> tinh trang thuc su "duoc dac xa" (DDX_MA 10/11/12)
        SELECT /*+ MATERIALIZE */ ID
        FROM QLPN.DM_DUOC_DAC_XAS
        WHERE NVL(IS_DELETED, 0) = 0
          AND DDX_MA IN ('10', '11', '12')
    ),
    dx_status_raw AS (
        SELECT dx.ID                                                                                     AS DX_ID,
               dx.PNLAI_LICH_ID,
               REPLACE(REPLACE(REPLACE(REPLACE(dx.DX_TINH_TRANG_DAC_XA, '[', ''), ']', ''), '"', ''), '''', '') AS TINH_TRANG_CSV
        FROM QLPN.PN_DAC_XAS dx
        WHERE NVL(dx.IS_DELETED, 0) = 0
--          AND dx.DX_NGAY_THA IS NOT NULL
          AND dx.DX_TINH_TRANG_DAC_XA IS NOT NULL
    ),
    dx_status_ids AS (
        -- DX_TINH_TRANG_DAC_XA la list dang '[id1,id2,...]' -> tach tung id
        SELECT r.PNLAI_LICH_ID,
               TO_NUMBER(REGEXP_SUBSTR(r.TINH_TRANG_CSV, '[0-9]+', 1, LEVEL)) AS TINH_TRANG_ID
        FROM dx_status_raw r
        CONNECT BY LEVEL <= REGEXP_COUNT(r.TINH_TRANG_CSV, '[0-9]+')
               AND PRIOR r.DX_ID = r.DX_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    dx_duoc_dac_xa AS (
        SELECT DISTINCT s.PNLAI_LICH_ID
        FROM dx_status_ids s
        INNER JOIN duoc_dac_xa_ids ids
                ON ids.ID = s.TINH_TRANG_ID
    ),
    dot_ddx AS (
        SELECT
            TRUNC(d.DDX_NGAY_XET)                                          AS NGAY_XET,
            MIN(d.DDX_NAM_DAC_XA) KEEP (DENSE_RANK FIRST ORDER BY d.ID)     AS DDX_NAM_DAC_XA,
            MIN(d.DDX_TEN_DOT)    KEEP (DENSE_RANK FIRST ORDER BY d.ID)     AS DDX_TEN_DOT
        FROM QLPN.PN_DOT_DAC_XAS d
        WHERE NVL(d.IS_DELETED, 0) = 0
          AND d.DDX_NGAY_XET IS NOT NULL
        GROUP BY TRUNC(d.DDX_NGAY_XET)
    ),
    dx_pn AS (
        SELECT DISTINCT
            db.DDX_NAM_DAC_XA                     AS NAM,
            NVL(db.DDX_TEN_DOT, u'Kh\00e1c')          AS DOT_THA,
            tg.TG_MA                              AS MA_TRAI_GIAM,
            dx.PNLAI_LICH_ID                      AS PHAM_NHAN_ID
        FROM QLPN.PN_DAC_XAS dx
        INNER JOIN dx_duoc_dac_xa dda
                ON dda.PNLAI_LICH_ID = dx.PNLAI_LICH_ID
        INNER JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt
                ON rt.PHAM_NHAN_ID = dx.PNLAI_LICH_ID
               AND NVL(rt.IS_DELETED, 0) = 0
        INNER JOIN trai_map tg
                ON tg.ID = rt.LL_TRAI_GIAM_ID
        LEFT JOIN dot_ddx db
          ON dx.DX_NGAY_XET >= db.NGAY_XET
         AND dx.DX_NGAY_XET <  db.NGAY_XET + 1
        WHERE dx.DX_NGAY_THA IS NOT NULL
          AND NVL(dx.IS_DELETED, 0) = 0
    ),
    dot_tcdk AS (
        SELECT
            TRUNC(d.DTCDK_NGAY_XET)                                         AS NGAY_XET,
            MIN(d.DTCDK_NGAY_XET) KEEP (DENSE_RANK FIRST ORDER BY d.ID)      AS DTCDK_NGAY_XET
        FROM QLPN.PN_DOT_THA_CO_DIEU_KIENS d
        WHERE NVL(d.IS_DELETED, 0) = 0
          AND d.DTCDK_NGAY_XET IS NOT NULL
        GROUP BY TRUNC(d.DTCDK_NGAY_XET)
    ),
    tcdk_pn AS (
        SELECT DISTINCT
            CAST(EXTRACT(YEAR FROM tck.NGAY_XET) AS NVARCHAR2(4)) AS NAM,
            NVL(TO_NCHAR(tck.NGAY_XET, 'DD/MM/YYYY'), u'Kh\00e1c') AS DOT_THA,
            tg.TG_MA AS MA_TRAI_GIAM,
            tck.PHAM_NHAN_ID
        FROM QLPN.THA_CO_DIEU_KIENS tck
        INNER JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT rt
                ON rt.PHAM_NHAN_ID = tck.PHAM_NHAN_ID
               AND NVL(rt.IS_DELETED, 0) = 0
        INNER JOIN DM_THA_CO_DIEU_KIENS DM ON DM.ID = TCK.TINH_TRANG_ID
    INNER JOIN trai_map tg
            ON tg.ID = rt.LL_TRAI_GIAM_ID
--    LEFT JOIN dot_tcdk db
--      ON tck.NGAY_XET >= db.NGAY_XET
--     AND tck.NGAY_XET <  db.NGAY_XET + 1
    WHERE tck.NGAY_THA IS NOT NULL
    AND DM.TCDK_MA IN ('10', '11')
    AND NVL(tck.IS_DELETED, 0) = 0
    ),
    chi_tiet AS (
        SELECT
            NAM,
            u'\0110\1eb7c x\00e1' AS LOAI_THA,
            DOT_THA,
            MA_TRAI_GIAM,
            COUNT(*) AS SO_LUONG
        FROM dx_pn
        GROUP BY NAM, DOT_THA, MA_TRAI_GIAM

        UNION ALL

        SELECT
            NAM,
            u'Tha c\00f3 \0111i\1ec1u ki\1ec7n' AS LOAI_THA,
            DOT_THA,
            MA_TRAI_GIAM,
            COUNT(*) AS SO_LUONG
        FROM tcdk_pn
        GROUP BY NAM, DOT_THA, MA_TRAI_GIAM
    )
    SELECT NAM, LOAI_THA, DOT_THA, MA_TRAI_GIAM, SO_LUONG, SYSDATE AS CREATION_TIME
    FROM chi_tiet

    UNION ALL

    -- Dong tong C10: chi ghi khi refresh toan bo (p_ma_trai_giam IS NULL); khi refresh
    -- rieng 1 trai thi khong dung vi chi_tiet luc do da bi trai_map loc chi con 1 trai.
    SELECT
        NAM,
        LOAI_THA,
        DOT_THA,
        u'C10' AS MA_TRAI_GIAM,
        SUM(SO_LUONG) AS SO_LUONG,
        SYSDATE AS CREATION_TIME
    FROM chi_tiet
    WHERE p_ma_trai_giam IS NULL
    GROUP BY NAM, LOAI_THA, DOT_THA;

    COMMIT;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END SP_QLPN_GET_TK_DAC_XA_THA_CDK_DASHBOARD;

-- Goi thu (chay rieng block nay):
-- EXEC QLPN.SP_QLPN_GET_TK_DAC_XA_THA_CDK_DASHBOARD(p_ma_trai_giam => NULL);
-- EXEC QLPN.SP_QLPN_GET_TK_DAC_XA_THA_CDK_DASHBOARD(p_ma_trai_giam => '94280');

/
--------------------------------------------------------
--  DDL for Procedure SP_QLPN_GET_TK_NAM_DASHBOARD
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_QLPN_GET_TK_NAM_DASHBOARD" (
    p_nam          IN NUMBER DEFAULT NULL,
    p_tu_ngay      IN DATE DEFAULT NULL,
    p_den_ngay     IN DATE DEFAULT NULL,
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL
)
AS
    v_nam      NUMBER := NVL(p_nam, EXTRACT(YEAR FROM SYSDATE));
    v_tu_ngay  DATE;
    v_den_ngay DATE;
    v_ngay_xet DATE;
BEGIN
    v_tu_ngay := TRUNC(NVL(p_tu_ngay, TO_DATE('01/01/' || TO_CHAR(v_nam), 'DD/MM/YYYY')));
    v_den_ngay := TRUNC(NVL(
        p_den_ngay,
        TO_DATE('31/12/' || TO_CHAR(v_nam), 'DD/MM/YYYY')
    ));
    v_ngay_xet := LEAST(v_den_ngay, TRUNC(SYSDATE));

    IF v_tu_ngay > v_den_ngay THEN
        RAISE_APPLICATION_ERROR(-20001, 'Tu ngay phai nho hon hoac bang den ngay');
    END IF;

    -- Cache tinh trang dau ky va tinh trang tai ngay xet cho toan bo pham nhan (set-based, 1 lan)
    -- thay vi goi FN_GET_TINH_TRANG_TAI_NGAY_XET per-row — cung co che voi SP thang.
    -- L?U Ý: ph?i ensure v_ngay_xet TR??C r?i m?i ensure v_tu_ngay-1 — SP_REFRESH_PN_TINH_TRANG_NGAY_CACHE
    -- xoá retention (NGAY_XET < SYSDATE - 3 tháng) ? ??U m?i l?n g?i; n?u ensure v_tu_ngay-1 tr??c
    -- (th??ng là 01/01, g?n nh? luôn > 3 tháng so v?i hôm nay khi ch?y sau tháng 4) thì cache
    -- v?a tính s? b? chính retention c?a l?nh ensure(v_ngay_xet) sau ?ó xoá s?ch ? T1 ra 0.
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_xet);
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_tu_ngay - 1);

    EXECUTE IMMEDIATE 'ALTER SESSION FORCE PARALLEL QUERY PARALLEL 4';
    EXECUTE IMMEDIATE 'ALTER SESSION ENABLE PARALLEL DML';

    DELETE FROM QLPN.PN_TK_NAM_DASHBOARD
     WHERE NAM = TO_CHAR(v_nam)
       AND TU_NGAY = TO_CHAR(v_tu_ngay, 'DD/MM/YYYY')
       AND (p_ma_trai_giam IS NULL OR MA_TRAI_GIAM = p_ma_trai_giam);
    -- COMMIT tr??c INSERT APPEND PARALLEL — tránh ORA-12838 (??c/ghi b?ng v?a s?a parallel).
    -- SP tháng dùng TRUNCATE (DDL t? commit) cho b??c t??ng ???ng.
    COMMIT;

    INSERT /*+ APPEND PARALLEL(4) */ INTO QLPN.PN_TK_NAM_DASHBOARD (
        NAM,
        TU_NGAY,
        DEN_NGAY,
        MA_TRAI_GIAM,
        SO_PN_NAM_TRUOC_CHUYEN_SANG,
        SO_TANG_TRONG_NAM,
        SO_GIAM_TRONG_NAM,
        DANG_CHAP_HANH_AN,
        CREATION_TIME
    )
    WITH
    KY AS (
        SELECT v_tu_ngay      AS TU_NGAY,
               v_den_ngay     AS DEN_NGAY,
               v_ngay_xet     AS NGAY_XET,
               v_ngay_xet + 1 AS NGAY_XET_EXCLUSIVE
          FROM DUAL
    ),

    -- TG_MA_DD_DT IS NOT NULL: ch? nh?n tr?i giam th?t thu?c C10 (có mã ??nh danh ?i?n t?) —
    -- lo?i các "tr?i" khác l?u chung DM_TRAI_GIAMS (tr?i t?m giam t?nh khác...) mà vài PN b? gán
    -- nh?m/t?m LL_TRAI_GIAM_ID vào ?ó (vd 90680, 95360, 98409 — xác nh?n qua ??i soát 2026-08-20).
    DS_TRAI AS (
        SELECT DISTINCT TG.TG_MA AS MA_TRAI_GIAM
          FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
          INNER JOIN QLPN.DM_TRAI_GIAMS TG
                  ON TG.ID = RT.LL_TRAI_GIAM_ID
                 AND NVL(TG.IS_DELETED, 0) = 0
                 AND TG.TG_MA_DD_DT IS NOT NULL
         WHERE NVL(RT.IS_DELETED, 0) = 0
           AND RT.LL_TRAI_GIAM_ID IS NOT NULL
           AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
    ),

    TANG_1 AS (
        SELECT TG.TG_MA AS MA_TRAI_GIAM, COUNT(*) AS V
          FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
          JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
          JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE CACHE_TT
                  ON CACHE_TT.PN_LAI_LICH_ID = RT.PHAM_NHAN_ID
                 AND CACHE_TT.NGAY_XET = v_tu_ngay - 1
                 AND CACHE_TT.TTPN_MA IN ('111', '112', '113', '114')
         WHERE NVL(RT.IS_DELETED, 0) = 0
           AND RT.LL_TRAI_GIAM_ID IS NOT NULL
           AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
         GROUP BY TG.TG_MA
    ),

    -- So dang chap hanh an tai dung NGAY_XET (nguon su that duy nhat) — dam bao khop voi
    -- SP thang khi ca 2 cung xet toi cung 1 ngay (vi du ky hien tai, NGAY_XET = hom nay).
    DCHA_TAI_NGAY_XET AS (
        SELECT TG.TG_MA AS MA_TRAI_GIAM, COUNT(*) AS V
          FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
          JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
          JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE CACHE_TT
                  ON CACHE_TT.PN_LAI_LICH_ID = RT.PHAM_NHAN_ID
                 AND CACHE_TT.NGAY_XET = v_ngay_xet
                 AND CACHE_TT.TTPN_MA IN ('111', '112', '113', '114')
         WHERE NVL(RT.IS_DELETED, 0) = 0
           AND RT.LL_TRAI_GIAM_ID IS NOT NULL
           AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
         GROUP BY TG.TG_MA
    ),

    -- Ngu?n dùng chung cho toàn b? TANG_x/GIAM_x (tr??c ?ây b? copy-paste ??c l?p ? ?ây,
    -- SP_QLPN_GET_TK_THANG_DASHBOARD và SP_GET_TIM_KIEM_PN_LAI_LICH — xem
    -- docs/reports/QLPN/Dashboard/FN_PN_TANG_GIAM_TRONG_KY.sql ?? bi?t chi ti?t t?ng nhánh và
    -- lý do lo?i CB (b?t bu?c ch?a b?nh, cùng nhóm "?ang ch?p hành") kh?i t?ng/gi?m).
    TANG_GIAM AS (
        SELECT * FROM TABLE(QLPN.FN_PN_TANG_GIAM_TRONG_KY(v_tu_ngay, v_ngay_xet + 1, p_ma_trai_giam))
    ),

    -- C?p nh?t 2026-08-21: ??m theo (PHAM_NHAN_ID, EVENT_DATE) ch? KHÔNG ch? PHAM_NHAN_ID —
    -- 1 PN có th? có ?2 s? ki?n TANG (ho?c GIAM) TH?T ? 2 ngày khác nhau trong cùng k? (vd
    -- vào ??u n?m r?i ?i trích xu?t r?i v? l?i cu?i n?m: TANG_2 + TANG_6, 2 s? ki?n t?ng th?t).
    -- COUNT(DISTINCT PHAM_NHAN_ID) ??n thu?n g?p nh?m 2 s? ki?n th?t thành 1, phá v? ??ng th?c
    -- T1+TANG-GIAM=DCHA (?ã ki?m ch?ng b?ng d? li?u th?t: 12 PN d?ng này gây ?úng LECH -12 ?
    -- tr?i 94280/2022 — xem FN_PN_TANG_GIAM_TRONG_KY.sql).
    TANG_TRONG_NAM AS (
        SELECT MA_TRAI_GIAM, COUNT(*) AS V
          FROM (SELECT DISTINCT PHAM_NHAN_ID, EVENT_DATE, MA_TRAI_GIAM FROM TANG_GIAM WHERE LOAI = 'TANG')
         GROUP BY MA_TRAI_GIAM
    ),

    -- LDT_MA 20221 ("Tr?i giam khác chuy?n ??n") — tr? kh?i dòng t?ng C10 (không ?nh h??ng
    -- per-tr?i) ?? không th?i ph?ng "t?ng" c?a c? h? th?ng b?ng kh? n?ng chuy?n tr?i n?i b?.
    -- C?p nh?t 2026-08-20: KHÔNG tr? (lo?i kh?i ib.V) các PN ?ã có c?p GIAM_17_NOI_BO ? ?úng
    -- tr?i NGU?N — t?ng (?ích) và gi?m (ngu?n) c?a c?p ?ó t? tri?t tiêu trong SUM c?p C10, tr?
    -- thêm qua ib.V s? tr? 2 l?n. Ch? áp d?ng khi tr?i ngu?n n?m trong DS_TRAI (?ang có PN hi?n
    -- t?i) — n?u tr?i ngu?n không còn PN nào hi?n t?i, GIAM_17 ?ó s? không ???c c?ng vào
    -- SUM(gt.V) (b? DS_TRAI l?c m?t), nên v?n ph?i gi? ib.V ?? không ??m th?a TANG.
    -- C?p nh?t 2026-08-21: ghép c?p theo (PHAM_NHAN_ID, EVENT_DATE) thay vì ch? PHAM_NHAN_ID —
    -- n?u 1 PN có ?2 l?n chuy?n n?i b? khác ngày trong cùng k?, ch? lo?i ?úng l?n ?ã ghép ???c
    -- GIAM_17, không lo?i nh?m c? 2.
    TANG_2_3B_INTRA_C10_IDS AS (
        SELECT DISTINCT PHAM_NHAN_ID AS ID, EVENT_DATE, MA_TRAI_GIAM
          FROM TANG_GIAM
         WHERE NHOM = 'TANG_3'
           AND (PHAM_NHAN_ID, EVENT_DATE) NOT IN (
               SELECT PHAM_NHAN_ID, EVENT_DATE FROM TANG_GIAM tg17
                WHERE tg17.NHOM = 'GIAM_17_NOI_BO'
                  AND tg17.MA_TRAI_GIAM IN (SELECT MA_TRAI_GIAM FROM DS_TRAI)
           )
    ),

    GIAM_TRONG_NAM AS (
        SELECT MA_TRAI_GIAM, COUNT(*) AS V
          FROM (SELECT DISTINCT PHAM_NHAN_ID, EVENT_DATE, MA_TRAI_GIAM FROM TANG_GIAM WHERE LOAI = 'GIAM')
         GROUP BY MA_TRAI_GIAM
    )

    SELECT
        TO_CHAR(v_nam) AS NAM,
        TO_CHAR(v_tu_ngay, 'DD/MM/YYYY') AS TU_NGAY,
        TO_CHAR(v_ngay_xet, 'DD/MM/YYYY') AS DEN_NGAY,
        ds.MA_TRAI_GIAM,
        NVL(t1.V, 0) AS SO_PN_NAM_TRUOC_CHUYEN_SANG,
        NVL(tt.V, 0) AS SO_TANG_TRONG_NAM,
        NVL(gt.V, 0) AS SO_GIAM_TRONG_NAM,
        NVL(dc.V, 0) AS DANG_CHAP_HANH_AN,
        SYSDATE AS CREATION_TIME
      FROM DS_TRAI ds
      LEFT JOIN TANG_1 t1 ON t1.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
      LEFT JOIN TANG_TRONG_NAM tt ON tt.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
      LEFT JOIN GIAM_TRONG_NAM gt ON gt.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
      LEFT JOIN DCHA_TAI_NGAY_XET dc ON dc.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
    UNION ALL
    -- Dòng t?ng C10: GIAM_TRONG_NAM ?ã không còn ch?a chuy?n tr?i n?i b? (GIAM_14) nên SUM
    -- tr?c ti?p. Riêng SO_TANG_TRONG_NAM: tr? nhóm TANG_2_3B (LDT_MA=20221, "tr?i giam khác
    -- chuy?n ??n") — per-tr?i v?n gi? nguyên, ch? tr? ? t?ng C10 ?? tránh th?i ph?ng "t?ng"
    -- c?a c? h? th?ng b?ng kh? n?ng chuy?n tr?i n?i b?.
    SELECT
        TO_CHAR(v_nam),
        TO_CHAR(v_tu_ngay, 'DD/MM/YYYY'),
        TO_CHAR(v_ngay_xet, 'DD/MM/YYYY'),
        u'C10',
        SUM(NVL(t1.V, 0)),
        SUM(NVL(tt.V, 0)) - MAX(ib.V),
        SUM(NVL(gt.V, 0)),
        SUM(NVL(dc.V, 0)),
        SYSDATE
      FROM DS_TRAI ds
      LEFT JOIN TANG_1 t1 ON t1.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
      LEFT JOIN TANG_TRONG_NAM tt ON tt.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
      LEFT JOIN GIAM_TRONG_NAM gt ON gt.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
      LEFT JOIN DCHA_TAI_NGAY_XET dc ON dc.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
      CROSS JOIN (SELECT COUNT(*) AS V FROM TANG_2_3B_INTRA_C10_IDS) ib
     WHERE p_ma_trai_giam IS NULL;

    COMMIT;

    EXECUTE IMMEDIATE 'ALTER SESSION DISABLE PARALLEL QUERY';
    EXECUTE IMMEDIATE 'ALTER SESSION DISABLE PARALLEL DML';
EXCEPTION
    WHEN OTHERS THEN
        BEGIN EXECUTE IMMEDIATE 'ALTER SESSION DISABLE PARALLEL QUERY'; EXCEPTION WHEN OTHERS THEN NULL; END;
        BEGIN EXECUTE IMMEDIATE 'ALTER SESSION DISABLE PARALLEL DML';   EXCEPTION WHEN OTHERS THEN NULL; END;
        RAISE;
END SP_QLPN_GET_TK_NAM_DASHBOARD;

/
--------------------------------------------------------
--  DDL for Procedure SP_QLPN_GET_TK_THANG_DASHBOARD
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_QLPN_GET_TK_THANG_DASHBOARD" (
    p_tu_ngay      IN DATE DEFAULT NULL,
    p_den_ngay     IN DATE DEFAULT NULL,
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL
)
AS
    v_tu_ngay  DATE := TRUNC(NVL(p_tu_ngay, 
                       CASE WHEN EXTRACT(DAY FROM SYSDATE) < 15 
                            THEN ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1) + 14 
                            ELSE TRUNC(SYSDATE, 'MM') + 14 
                       END));
    v_den_ngay DATE := TRUNC(NVL(p_den_ngay, 
                       CASE WHEN EXTRACT(DAY FROM SYSDATE) < 15 
                            THEN TRUNC(SYSDATE, 'MM') + 13 
                            ELSE ADD_MONTHS(TRUNC(SYSDATE, 'MM'), 1) + 13 
                       END));
    v_ngay_xet DATE := LEAST(v_den_ngay, TRUNC(SYSDATE));
    v_thang    VARCHAR2(20) := TO_CHAR(v_tu_ngay, 'MM/YYYY');
BEGIN
    IF v_tu_ngay > v_den_ngay THEN
        RAISE_APPLICATION_ERROR(-20001, 'Tu ngay phai nho hon hoac bang den ngay');
    END IF;

    -- Xóa d? li?u c? (theo k?; có th? gi?i h?n m?t tr?i)
    DELETE FROM QLPN.PN_TK_THANG_DASHBOARD
     WHERE TU_NGAY = TO_CHAR(v_tu_ngay, 'DD/MM/YYYY')
       AND DEN_NGAY = TO_CHAR(v_den_ngay, 'DD/MM/YYYY')
       AND (p_ma_trai_giam IS NULL OR MA_TRAI_GIAM = p_ma_trai_giam);

    IF p_ma_trai_giam IS NULL THEN
        EXECUTE IMMEDIATE 'TRUNCATE TABLE QLPN.PN_TK_THANG_DAU_KY_IDS';
    ELSE
        DELETE FROM QLPN.PN_TK_THANG_DAU_KY_IDS
         WHERE TU_NGAY = TO_CHAR(v_tu_ngay, 'DD/MM/YYYY')
           AND DEN_NGAY = TO_CHAR(v_den_ngay, 'DD/MM/YYYY')
           AND MA_TRAI_GIAM = p_ma_trai_giam;
    END IF;
    -- TRUNCATE là DDL: t? commit khi refresh toàn b?

    -- Cache tinh trang tai NGAY_XET — dung lam nguon su that cho DANG_CHAP_HANH_AN,
    -- cung co che voi SP nam de 2 SP luon khop nhau khi xet toi cung 1 ngay.
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_xet);
    -- Tính và l?u danh sách PN ??u k? (tình tr?ng t?i TU_NGAY - 1)
    -- Dùng PN_TINH_TRANG_TAI_NGAY_CACHE thay FN_GET per-row (tránh ORA-01422 khi parallel).
    -- L?U Ý: ph?i ensure SAU v_ngay_xet — SP_REFRESH_PN_TINH_TRANG_NGAY_CACHE xoá retention
    -- (NGAY_XET < SYSDATE - 3 tháng) ? ??U m?i l?n g?i; n?u ensure TU_NGAY-1 tr??c r?i m?i
    -- ensure NGAY_XET, và TU_NGAY-1 ?ã quá 3 tháng so v?i hôm nay, cache TU_NGAY-1 v?a tính
    -- s? b? chính retention c?a l?nh ensure th? hai xoá s?ch ? T1 (??u k?) ra 0.
    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_tu_ngay - 1);

    INSERT INTO QLPN.PN_TK_THANG_DAU_KY_IDS (TU_NGAY, DEN_NGAY, MA_TRAI_GIAM, PHAM_NHAN_ID, CREATION_TIME)
    SELECT /*+ NO_PARALLEL */
        TO_CHAR(v_tu_ngay, 'DD/MM/YYYY'),
        TO_CHAR(v_den_ngay, 'DD/MM/YYYY'),
        TG.TG_MA,
        RT.PHAM_NHAN_ID,
        SYSDATE
    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
    INNER JOIN QLPN.DM_TRAI_GIAMS TG
            ON TG.ID = RT.LL_TRAI_GIAM_ID
           AND NVL(TG.IS_DELETED, 0) = 0
    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE CACHE_TT
            ON CACHE_TT.PN_LAI_LICH_ID = RT.PHAM_NHAN_ID
           AND CACHE_TT.NGAY_XET = v_tu_ngay - 1
           AND CACHE_TT.TTPN_MA IN ('111', '112', '113', '114')
    WHERE NVL(RT.IS_DELETED, 0) = 0
      AND RT.LL_TRAI_GIAM_ID IS NOT NULL
      AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam);
    COMMIT;

    -- B?t parallel ch? cho bulk INSERT dashboard (sau b??c ??u k?)
    EXECUTE IMMEDIATE 'ALTER SESSION FORCE PARALLEL QUERY PARALLEL 4';
    EXECUTE IMMEDIATE 'ALTER SESSION ENABLE PARALLEL DML';

    -- Insert d? li?u m?i — 1 dòng / tr?i / k?
    INSERT /*+ APPEND PARALLEL(4) */ INTO QLPN.PN_TK_THANG_DASHBOARD (
        THANG,
        TU_NGAY,
        DEN_NGAY,
        MA_TRAI_GIAM,
        SO_PN_THANG_TRUOC_CHUYEN_SANG,
        SO_TANG_TRONG_THANG,
        SO_GIAM_TRONG_THANG,
        DANG_CHAP_HANH_AN,
        CREATION_TIME
    )
    WITH
    -- ----------------------------------------------------------------
    -- Date boundaries
    -- ----------------------------------------------------------------
    THANG AS (
        SELECT v_tu_ngay      AS TU_NGAY,
               v_den_ngay     AS DEN_NGAY,
               v_ngay_xet     AS NGAY_XET,
               v_ngay_xet + 1 AS NGAY_XET_EXCLUSIVE
          FROM DUAL
    ),

    -- TG_MA_DD_DT IS NOT NULL: ch? nh?n tr?i giam th?t thu?c C10 (có mã ??nh danh ?i?n t?) —
    -- lo?i các "tr?i" khác l?u chung DM_TRAI_GIAMS (tr?i t?m giam t?nh khác...) mà vài PN b? gán
    -- nh?m/t?m LL_TRAI_GIAM_ID vào ?ó (vd 90680, 95360, 98409 — xác nh?n qua ??i soát 2026-08-20).
    DS_TRAI AS (
        SELECT DISTINCT TG.TG_MA AS MA_TRAI_GIAM
          FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
          INNER JOIN QLPN.DM_TRAI_GIAMS TG
                  ON TG.ID = RT.LL_TRAI_GIAM_ID
                 AND NVL(TG.IS_DELETED, 0) = 0
--                 AND TG.TG_MA_DD_DT IS NOT NULL
         WHERE NVL(RT.IS_DELETED, 0) = 0
           AND RT.LL_TRAI_GIAM_ID IS NOT NULL
           AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
    ),

    -- ================================================================
    -- T?NG sub-components (gom theo MA_TRAI_GIAM)
    -- ================================================================

    TANG_1 AS (
        SELECT MA_TRAI_GIAM, COUNT(*) AS V
          FROM QLPN.PN_TK_THANG_DAU_KY_IDS
         WHERE TU_NGAY = TO_CHAR(v_tu_ngay, 'DD/MM/YYYY')
           AND DEN_NGAY = TO_CHAR(v_den_ngay, 'DD/MM/YYYY')
           AND (p_ma_trai_giam IS NULL OR MA_TRAI_GIAM = p_ma_trai_giam)
         GROUP BY MA_TRAI_GIAM
    ),

    -- So dang chap hanh an tai dung NGAY_XET (nguon su that duy nhat) — dam bao khop voi
    -- SP nam khi ca 2 cung xet toi cung 1 ngay (vi du ky hien tai, NGAY_XET = hom nay).
    DCHA_TAI_NGAY_XET AS (
        SELECT TG.TG_MA AS MA_TRAI_GIAM, COUNT(*) AS V
          FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
          JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
          JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE CACHE_TT
                  ON CACHE_TT.PN_LAI_LICH_ID = RT.PHAM_NHAN_ID
                 AND CACHE_TT.NGAY_XET = v_ngay_xet
                 AND CACHE_TT.TTPN_MA IN ('111', '112', '113', '114')
         WHERE NVL(RT.IS_DELETED, 0) = 0
           AND RT.LL_TRAI_GIAM_ID IS NOT NULL
           AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
         GROUP BY TG.TG_MA
    ),

    -- Ngu?n dùng chung cho toàn b? TANG_x/GIAM_x (tr??c ?ây b? copy-paste ??c l?p ? ?ây,
    -- SP_QLPN_GET_TK_NAM_DASHBOARD và SP_GET_TIM_KIEM_PN_LAI_LICH — xem
    -- docs/reports/QLPN/Dashboard/FN_PN_TANG_GIAM_TRONG_KY.sql ?? bi?t chi ti?t t?ng nhánh và
    -- lý do lo?i CB (b?t bu?c ch?a b?nh, cùng nhóm "?ang ch?p hành") kh?i t?ng/gi?m).
    TANG_GIAM AS (
        SELECT * FROM TABLE(QLPN.FN_PN_TANG_GIAM_TRONG_KY(v_tu_ngay, v_ngay_xet + 1, p_ma_trai_giam))
    ),

    -- C?p nh?t 2026-08-21: ??m theo (PHAM_NHAN_ID, EVENT_DATE) ch? KHÔNG ch? PHAM_NHAN_ID —
    -- 1 PN có th? có ?2 s? ki?n TANG (ho?c GIAM) TH?T ? 2 ngày khác nhau trong cùng k? (vd
    -- vào ??u n?m r?i ?i trích xu?t r?i v? l?i cu?i n?m: TANG_2 + TANG_6, 2 s? ki?n t?ng th?t).
    -- COUNT(DISTINCT PHAM_NHAN_ID) ??n thu?n g?p nh?m 2 s? ki?n th?t thành 1, phá v? ??ng th?c
    -- T1+TANG-GIAM=DCHA (?ã ki?m ch?ng b?ng d? li?u th?t: 12 PN d?ng này gây ?úng LECH -12 ?
    -- tr?i 94280/2022 — xem FN_PN_TANG_GIAM_TRONG_KY.sql).
    TANG_TRONG_THANG AS (
        SELECT MA_TRAI_GIAM, COUNT(*) AS V
          FROM (SELECT DISTINCT PHAM_NHAN_ID, EVENT_DATE, MA_TRAI_GIAM FROM TANG_GIAM WHERE LOAI = 'TANG')
         GROUP BY MA_TRAI_GIAM
    ),

    -- LDT_MA 20221 ("Tr?i giam khác chuy?n ??n") — tr? kh?i dòng t?ng C10 (không ?nh h??ng
    -- per-tr?i) ?? không th?i ph?ng "t?ng" c?a c? h? th?ng b?ng kh? n?ng chuy?n tr?i n?i b?.
    -- C?p nh?t 2026-08-20: KHÔNG tr? (lo?i kh?i ib.V) các PN ?ã có c?p GIAM_17_NOI_BO ? ?úng
    -- tr?i NGU?N — t?ng (?ích) và gi?m (ngu?n) c?a c?p ?ó t? tri?t tiêu trong SUM c?p C10, tr?
    -- thêm qua ib.V s? tr? 2 l?n. Ch? áp d?ng khi tr?i ngu?n n?m trong DS_TRAI (?ang có PN hi?n
    -- t?i) — n?u tr?i ngu?n không còn PN nào hi?n t?i, GIAM_17 ?ó s? không ???c c?ng vào
    -- SUM(gt.V) (b? DS_TRAI l?c m?t), nên v?n ph?i gi? ib.V ?? không ??m th?a TANG.
    -- C?p nh?t 2026-08-21: ghép c?p theo (PHAM_NHAN_ID, EVENT_DATE) thay vì ch? PHAM_NHAN_ID —
    -- n?u 1 PN có ?2 l?n chuy?n n?i b? khác ngày trong cùng k?, ch? lo?i ?úng l?n ?ã ghép ???c
    -- GIAM_17, không lo?i nh?m c? 2.
    TANG_2_3B_INTRA_C10_IDS AS (
        SELECT DISTINCT PHAM_NHAN_ID AS ID, EVENT_DATE, MA_TRAI_GIAM
          FROM TANG_GIAM
         WHERE NHOM = 'TANG_3'
           AND (PHAM_NHAN_ID, EVENT_DATE) NOT IN (
               SELECT PHAM_NHAN_ID, EVENT_DATE FROM TANG_GIAM tg17
                WHERE tg17.NHOM = 'GIAM_17_NOI_BO'
                  AND tg17.MA_TRAI_GIAM IN (SELECT MA_TRAI_GIAM FROM DS_TRAI)
           )
    ),

    GIAM_TRONG_THANG AS (
        SELECT MA_TRAI_GIAM, COUNT(*) AS V
          FROM (SELECT DISTINCT PHAM_NHAN_ID, EVENT_DATE, MA_TRAI_GIAM FROM TANG_GIAM WHERE LOAI = 'GIAM')
         GROUP BY MA_TRAI_GIAM
    )

    SELECT
        v_thang AS THANG,
        TO_CHAR(v_tu_ngay, 'DD/MM/YYYY') AS TU_NGAY,
        TO_CHAR(v_den_ngay, 'DD/MM/YYYY') AS DEN_NGAY,
        ds.MA_TRAI_GIAM,
        NVL(t1.V, 0)  AS SO_PN_THANG_TRUOC_CHUYEN_SANG,
        NVL(tt.V, 0)  AS SO_TANG_TRONG_THANG,
        NVL(gt.V, 0)  AS SO_GIAM_TRONG_THANG,
        NVL(dc.V, 0)  AS DANG_CHAP_HANH_AN,
        SYSDATE AS CREATION_TIME
      FROM DS_TRAI ds
      LEFT JOIN TANG_1 t1 ON t1.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
      LEFT JOIN TANG_TRONG_THANG tt ON tt.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
      LEFT JOIN GIAM_TRONG_THANG gt ON gt.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
      LEFT JOIN DCHA_TAI_NGAY_XET dc ON dc.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
    UNION ALL
    -- Dòng t?ng C10: GIAM_TRONG_THANG ?ã không còn ch?a chuy?n tr?i n?i b? (GIAM_14) nên SUM
    -- tr?c ti?p. Riêng SO_TANG_TRONG_THANG: tr? nhóm TANG_2_3B (LDT_MA=20221, "tr?i giam khác
    -- chuy?n ??n") — per-tr?i v?n gi? nguyên (ib không ?nh h??ng tt.V), ch? tr? ? t?ng C10 ??
    -- tránh th?i ph?ng "t?ng" c?a c? h? th?ng b?ng kh? n?ng chuy?n tr?i n?i b?.
    SELECT
        v_thang,
        TO_CHAR(v_tu_ngay, 'DD/MM/YYYY'),
        TO_CHAR(v_den_ngay, 'DD/MM/YYYY'),
        u'C10',
        SUM(NVL(t1.V, 0)),
        SUM(NVL(tt.V, 0)) - MAX(ib.V),
        SUM(NVL(gt.V, 0)),
        SUM(NVL(dc.V, 0)),
        SYSDATE
      FROM DS_TRAI ds
      LEFT JOIN TANG_1 t1 ON t1.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
      LEFT JOIN TANG_TRONG_THANG tt ON tt.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
      LEFT JOIN GIAM_TRONG_THANG gt ON gt.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
      LEFT JOIN DCHA_TAI_NGAY_XET dc ON dc.MA_TRAI_GIAM = ds.MA_TRAI_GIAM
      CROSS JOIN (SELECT COUNT(*) AS V FROM TANG_2_3B_INTRA_C10_IDS) ib
     WHERE p_ma_trai_giam IS NULL;

    COMMIT;

    -- Khôi ph?c session v? m?c ??nh
    EXECUTE IMMEDIATE 'ALTER SESSION DISABLE PARALLEL QUERY';
    EXECUTE IMMEDIATE 'ALTER SESSION DISABLE PARALLEL DML';

EXCEPTION
    WHEN OTHERS THEN
        -- ??m b?o cleanup dù có l?i
        BEGIN EXECUTE IMMEDIATE 'ALTER SESSION DISABLE PARALLEL QUERY'; EXCEPTION WHEN OTHERS THEN NULL; END;
        BEGIN EXECUTE IMMEDIATE 'ALTER SESSION DISABLE PARALLEL DML';   EXCEPTION WHEN OTHERS THEN NULL; END;
        RAISE;
END SP_QLPN_GET_TK_THANG_DASHBOARD;

/
--------------------------------------------------------
--  DDL for Procedure SP_REFRESH_PN_TCDK_CACHE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_REFRESH_PN_TCDK_CACHE" (
    p_ma_trai_giam IN  NVARCHAR2 DEFAULT NULL,
    p_message      OUT NVARCHAR2
) AS

    v_den_ngay     DATE;
    v_trai_giam_id NUMBER;

    -- ?? Ki?u d? li?u ??????????????????????????????????????????????????????????
    TYPE t_num_list   IS TABLE OF NUMBER         INDEX BY PLS_INTEGER;
    TYPE t_num1_list  IS TABLE OF NUMBER(1)      INDEX BY PLS_INTEGER;
    TYPE t_nvc_list   IS TABLE OF NVARCHAR2(200) INDEX BY PLS_INTEGER;

    v_num_tbl        QLPN.NUM_TBL;
    v_ct_giam_tbl    QLPN.NUM_TBL;
    v_ct_ctg_tbl     QLPN.NUM_TBL;
    v_dt_db_tbl      QLPN.NUM_TBL;

    -- Arrays cho DK_THOI_GIAN bulk
    v_ids            t_num_list;
    v_ma_trai        t_nvc_list;
    v_ct_giam        t_num1_list;
    v_ct_ctg         t_num1_list;
    v_dt_db          t_num1_list;
    v_dk_tg_result   t_num_list;

    -- Arrays cho TG_HIEN_THI bulk
    v_tg_da_giam     t_nvc_list;
    v_tg_chap_hanh   t_nvc_list;
    v_tg_con_lai     t_nvc_list;

    v_t0             NUMBER;
    v_xl_cnt         NUMBER := 0;

    FUNCTION elapsed_sec RETURN NUMBER IS
    BEGIN
        RETURN ROUND((DBMS_UTILITY.GET_TIME - v_t0) / 100, 2);
    END elapsed_sec;

    PROCEDURE set_message(
        p_status IN NVARCHAR2,
        p_dk_cnt IN NUMBER,
        p_xl_cnt IN NUMBER,
        p_tg_cnt IN NUMBER
    ) IS
        v_trai NVARCHAR2(50);
    BEGIN
        v_trai := CASE WHEN p_ma_trai_giam IS NULL THEN u'TAT_CA' ELSE TRIM(p_ma_trai_giam) END;
        p_message :=
              p_status
            || u' | TRAI=' || v_trai
            || u' | NGAY_XET=' || TO_CHAR(v_den_ngay, 'DD/MM/YYYY')
            || u' | SO_BAN_GHI_CACHE: '
            || u'\0111i\1ec1u_ki\1ec7n_tg=' || NVL(p_dk_cnt, 0)
            || u', x\1ebfp_lo\1ea1i=' || NVL(p_xl_cnt, 0)
            || u', tg_hi\1ec3n_th\1ecb=' || NVL(p_tg_cnt, 0)
            || u' | THOI_GIAN=' || TO_NCHAR(elapsed_sec) || u's';
    END set_message;

BEGIN

    v_t0 := DBMS_UTILITY.GET_TIME;

    -- ?? 0. L?y ngày xét t? ??t tha ?ang m? ???????????????????????????????????
    BEGIN
        SELECT TRUNC(dt.DTCDK_NGAY_XET)
        INTO   v_den_ngay
        FROM   PN_DOT_THA_CO_DIEU_KIENS dt
        WHERE  NVL(dt.IS_DELETED, 0) = 0
          AND  dt.DTCDK_TRANG_THAI   = 1
          AND  dt.DTCDK_NGAY_XET     IS NOT NULL
          AND  ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_den_ngay := TRUNC(SYSDATE);
    END;

    IF p_ma_trai_giam IS NOT NULL THEN
        BEGIN
            SELECT id INTO v_trai_giam_id
            FROM DM_TRAI_GIAMS
            WHERE TG_MA = p_ma_trai_giam AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                v_trai_giam_id := NULL;
        END;
    END IF;

    -- Ch? gi? cache k? hi?n t?i (NGAY_XET = ??t ?ang m?); xóa d? li?u k? c?
    DELETE FROM QLPN.PN_XL_CONSEC_CACHE
     WHERE TRUNC(NGAY_XET) != TRUNC(v_den_ngay);
    DELETE FROM QLPN.PN_DK_THOI_GIAN_CACHE
     WHERE TRUNC(NGAY_XET) != TRUNC(v_den_ngay);
    DELETE FROM QLPN.PN_TG_HIEN_THI_CACHE
     WHERE TRUNC(NGAY_XET) != TRUNC(v_den_ngay);

    -- Refresh m?t tr?i: xóa cache k? hi?n t?i c?a tr?i tr??c khi MERGE/INSERT
    IF p_ma_trai_giam IS NOT NULL THEN
        DELETE FROM QLPN.PN_XL_CONSEC_CACHE c
        WHERE c.MA_TRAI_GIAM = p_ma_trai_giam;
    END IF;

    -- ???????????????????????????????????????????????????????????????????????????
    -- B??C 1: PN_XL_CONSEC_CACHE — t?p h?p, không c?n g?i PL/SQL per-row
    -- ???????????????????????????????????????????????????????????????????????????
    MERGE INTO QLPN.PN_XL_CONSEC_CACHE t
    USING (
        WITH
        tha_hieu_luc AS (
            SELECT /*+ MATERIALIZE */ DISTINCT tha.tha_pnlai_lich_id AS pn_id
            FROM   PN_THI_HANH_AN tha
            WHERE  NVL(tha.is_deleted, 0) = 0
              AND  tha.tha_pnlai_lich_id  IS NOT NULL
              AND  tha.tha_ngay_bat       IS NOT NULL
              AND  tha.tha_ngay_bat       <= v_den_ngay
              AND  (tha.tha_ngay_het_han  IS NULL OR tha.tha_ngay_het_han >= v_den_ngay)
        ),
        active_ids AS (
            SELECT /*+ MATERIALIZE */ DISTINCT
                   rt.PHAM_NHAN_ID,
                   tg.TG_MA AS ma_trai_giam
            FROM   tha_hieu_luc th
            INNER JOIN PN_LAI_LICH_CHI_TIET_RT rt
                    ON rt.PHAM_NHAN_ID = th.pn_id
                   AND NVL(rt.IS_DELETED, 0) = 0
                   AND NVL(rt.LL_IS_DELETED, 0) = 0
                   AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
            INNER JOIN DM_TINH_TRANG_PHAM_NHANS tt
                    ON tt.ID = rt.LL_TINH_TRANG_ID
                   AND NVL(tt.IS_DELETED, 0) = 0
                   AND tt.TTPN_MA IN ('111','112','113','114','141','142')
            LEFT JOIN DM_TRAI_GIAMS tg
                   ON tg.ID = rt.LL_TRAI_GIAM_ID
                  AND NVL(tg.IS_DELETED, 0) = 0
        ),
        dm_kha_tot AS (
            SELECT /*+ MATERIALIZE */ ID
            FROM   DM_XEP_LOAI_CAI_TAOS
            WHERE  XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t')
              AND  NVL(IS_DELETED, 0) = 0
        ),
        quy_grid AS (
            SELECT y.nam, qrv.q AS quy
            FROM   (SELECT EXTRACT(YEAR FROM v_den_ngay) - 20 + LEVEL AS nam
                    FROM DUAL CONNECT BY LEVEL <= 20) y
            CROSS  JOIN (SELECT 1 q FROM DUAL UNION ALL SELECT 2 FROM DUAL
                         UNION ALL SELECT 3 FROM DUAL UNION ALL SELECT 4 FROM DUAL) qrv
            WHERE  y.nam <= EXTRACT(YEAR FROM v_den_ngay)
              AND  (y.nam < EXTRACT(YEAR FROM v_den_ngay)
                   OR (y.nam = EXTRACT(YEAR FROM v_den_ngay) AND (
                          (qrv.q = 1 AND EXTRACT(MONTH FROM v_den_ngay) >= 3)
                       OR (qrv.q = 2 AND EXTRACT(MONTH FROM v_den_ngay) >= 6)
                       OR (qrv.q = 3 AND EXTRACT(MONTH FROM v_den_ngay) >= 9)
                       OR (qrv.q = 4 AND EXTRACT(MONTH FROM v_den_ngay) >= 12)
                   )))
        ),
        xl_raw AS (
            SELECT /*+ MATERIALIZE */
                xl.PHAM_NHAN_ID,
                xl.XEP_LOAI_NAM,
                xl.XEP_LOAI_QUY_I, xl.XEP_LOAI_QUY_II,
                xl.XEP_LOAI_QUY_III, xl.XEP_LOAI_QUY_IV
            FROM   XEP_LOAIS xl
            WHERE  NVL(xl.IS_DELETED, 0) = 0
              AND  EXISTS (SELECT 1 FROM active_ids a WHERE a.PHAM_NHAN_ID = xl.PHAM_NHAN_ID)
        ),
        xl_quy_vals AS (
            SELECT xl.PHAM_NHAN_ID, xl.XEP_LOAI_NAM AS nam, 1 AS quy, xl.XEP_LOAI_QUY_I   AS xl_id FROM xl_raw xl WHERE xl.XEP_LOAI_QUY_I   IS NOT NULL
            UNION ALL
            SELECT xl.PHAM_NHAN_ID, xl.XEP_LOAI_NAM,     2,     xl.XEP_LOAI_QUY_II          FROM xl_raw xl WHERE xl.XEP_LOAI_QUY_II  IS NOT NULL
            UNION ALL
            SELECT xl.PHAM_NHAN_ID, xl.XEP_LOAI_NAM,     3,     xl.XEP_LOAI_QUY_III         FROM xl_raw xl WHERE xl.XEP_LOAI_QUY_III IS NOT NULL
            UNION ALL
            SELECT xl.PHAM_NHAN_ID, xl.XEP_LOAI_NAM,     4,     xl.XEP_LOAI_QUY_IV          FROM xl_raw xl WHERE xl.XEP_LOAI_QUY_IV  IS NOT NULL
        ),
        xl_quy_flat AS (
            SELECT s.PHAM_NHAN_ID, g.nam, g.quy,
                   CASE WHEN k.ID IS NOT NULL THEN 1 ELSE 0 END AS is_kha_tot
            FROM   active_ids s
            CROSS  JOIN quy_grid g
            LEFT   JOIN xl_quy_vals v
                   ON v.PHAM_NHAN_ID = s.PHAM_NHAN_ID
                  AND v.nam = g.nam
                  AND v.quy = g.quy
            LEFT   JOIN dm_kha_tot k ON k.ID = v.xl_id
        ),
        xl_ranked AS (
            SELECT /*+ MATERIALIZE */
                   PHAM_NHAN_ID, is_kha_tot,
                   ROW_NUMBER() OVER (PARTITION BY PHAM_NHAN_ID ORDER BY nam DESC, quy DESC) AS rn,
                   ROW_NUMBER() OVER (PARTITION BY PHAM_NHAN_ID ORDER BY nam DESC, quy DESC)
                     - SUM(is_kha_tot) OVER (PARTITION BY PHAM_NHAN_ID ORDER BY nam DESC, quy DESC) AS grp
            FROM   xl_quy_flat
        ),
        xl_first_kha_tot AS (
            SELECT PHAM_NHAN_ID, grp AS first_grp
            FROM   xl_ranked
            WHERE  rn = 1 AND is_kha_tot = 1
        ),
        xl_consec AS (
            SELECT r.PHAM_NHAN_ID, COUNT(*) AS quy_lien_ke
            FROM   xl_ranked r
            INNER  JOIN xl_first_kha_tot fk
                ON fk.PHAM_NHAN_ID = r.PHAM_NHAN_ID AND r.grp = fk.first_grp
            WHERE  r.is_kha_tot = 1
            GROUP  BY r.PHAM_NHAN_ID
        )
        SELECT a.PHAM_NHAN_ID,
               v_den_ngay                    AS ngay_xet,
               a.ma_trai_giam,
               NVL(xlc.quy_lien_ke, 0)       AS quy_lien_ke
        FROM   active_ids a
        LEFT   JOIN xl_consec xlc ON xlc.PHAM_NHAN_ID = a.PHAM_NHAN_ID
    ) src
    ON (t.PHAM_NHAN_ID = src.PHAM_NHAN_ID)
    WHEN MATCHED THEN
        UPDATE SET t.NGAY_XET       = src.ngay_xet,
                   t.MA_TRAI_GIAM  = src.ma_trai_giam,
                   t.QUY_LIEN_KE   = src.quy_lien_ke,
                   t.LAST_REFRESHED = SYSDATE
    WHEN NOT MATCHED THEN
        INSERT (PHAM_NHAN_ID, NGAY_XET, MA_TRAI_GIAM, QUY_LIEN_KE, LAST_REFRESHED)
        VALUES (src.PHAM_NHAN_ID, src.ngay_xet, src.ma_trai_giam, src.quy_lien_ke, SYSDATE);

    SELECT COUNT(*)
      INTO v_xl_cnt
      FROM QLPN.PN_XL_CONSEC_CACHE c
     WHERE TRUNC(c.NGAY_XET) = TRUNC(v_den_ngay)
       AND (p_ma_trai_giam IS NULL OR c.MA_TRAI_GIAM = p_ma_trai_giam);

    -- ???????????????????????????????????????????????????????????????????????????
    -- B??C 2+3: PN_DK_THOI_GIAN_CACHE + PN_TG_HIEN_THI_CACHE
    --   Phase A: warm TCDK_CORE_MEMO ? FN_SNAPSHOT_TCDK_BATCH (1 pass pipelined)
    -- ???????????????????????????????????????????????????????????????????????????
    SELECT a.PHAM_NHAN_ID,
           a.is_chung_than_giam,
           a.is_chung_than_ctg,
           a.is_doi_tuong_db,
           a.ma_trai_giam
    BULK COLLECT INTO v_ids, v_ct_giam, v_ct_ctg, v_dt_db, v_ma_trai
    FROM (
        WITH
        tha_hieu_luc AS (
            SELECT DISTINCT tha.tha_pnlai_lich_id AS pn_id
            FROM PN_THI_HANH_AN tha
            WHERE NVL(tha.is_deleted, 0) = 0
              AND tha.tha_pnlai_lich_id IS NOT NULL
              AND tha.tha_ngay_bat IS NOT NULL
              AND tha.tha_ngay_bat <= v_den_ngay
              AND (tha.tha_ngay_het_han IS NULL OR tha.tha_ngay_het_han >= v_den_ngay)
        ),
        gcr_db AS (
            SELECT g.ID
            FROM DM_GHI_CHU_RIENGS g
            WHERE NVL(g.IS_DELETED, 0) = 0
              AND (
                  UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(g.GCR_TEN), u''))) LIKE '%CONG%'
               OR UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(g.GCR_TEN), u''))) LIKE '%70%'
               OR UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(g.GCR_TEN), u''))) LIKE '%KHUYETTAT%'
               OR UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(g.GCR_TEN), u''))) LIKE '%TANTAT%'
               OR (UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(g.GCR_TEN), u''))) LIKE '%PHUNU%'
                   AND UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(g.GCR_TEN), u''))) LIKE '%CON%')
               OR (UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(g.GCR_TEN), u''))) LIKE '%CON%'
                   AND (UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(g.GCR_TEN), u''))) LIKE '%36%'
                        OR UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(g.GCR_TEN), u''))) LIKE '%24%'))
               OR UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(g.GCR_TEN), u''))) LIKE '%LIETSY%'
               OR UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(g.GCR_TEN), u''))) LIKE '%CACHMANG%'
               OR (UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(g.GCR_TEN), u''))) LIKE '%THANNHAN%'
                   AND UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(g.GCR_TEN), u''))) LIKE '%CONG%')
              )
        ),
        active_pn AS (
            SELECT rt.PHAM_NHAN_ID,
                   rt.THA_AN_PHAT AS AN_PHAT,
                   rt.LL_GHI_CHU_RIENG AS GHI_CHU_RIENG,
                   rt.LL_NGAY_SINH AS NGAY_SINH,
                   rt.NAM_SINH,
                   tg.TG_MA AS ma_trai_giam
            FROM tha_hieu_luc th
            INNER JOIN PN_LAI_LICH_CHI_TIET_RT rt
                    ON rt.PHAM_NHAN_ID = th.pn_id
                   AND NVL(rt.IS_DELETED, 0) = 0
                   AND NVL(rt.LL_IS_DELETED, 0) = 0
                   AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
            INNER JOIN DM_TINH_TRANG_PHAM_NHANS tt
                    ON tt.ID = rt.LL_TINH_TRANG_ID
                   AND NVL(tt.IS_DELETED, 0) = 0
                   AND tt.TTPN_MA IN ('111','112','113','114','141','142')
            LEFT JOIN DM_TRAI_GIAMS tg
                   ON tg.ID = rt.LL_TRAI_GIAM_ID
                  AND NVL(tg.IS_DELETED, 0) = 0
        )
        SELECT ap.PHAM_NHAN_ID,
               CASE WHEN (UPPER(NVL(ap.AN_PHAT,'')) LIKE u'%CHUNG TH\00c2N%' OR UPPER(NVL(ap.AN_PHAT,'')) LIKE u'%CHUNG THAN%')
                         AND UPPER(NVL(ap.AN_PHAT,'')) LIKE u'%GI\1ea2M XU\1ed0NG%'
                    THEN 1 ELSE 0 END AS is_chung_than_giam,
               CASE WHEN (UPPER(NVL(ap.AN_PHAT,'')) LIKE u'%CHUNG TH\00c2N%' OR UPPER(NVL(ap.AN_PHAT,'')) LIKE u'%CHUNG THAN%')
                         AND NOT (UPPER(NVL(ap.AN_PHAT,'')) LIKE u'%GI\1ea2M XU\1ed0NG%')
                    THEN 1 ELSE 0 END AS is_chung_than_ctg,
               CASE WHEN (
                   EXISTS (
                       SELECT 1 FROM gcr_db g
                       WHERE g.ID = TO_NUMBER(TRIM(REGEXP_SUBSTR(
                               REPLACE(REPLACE(TRIM(NVL(ap.GHI_CHU_RIENG,'[]')),'[',''),']',''),
                               '[0-9]+', 1, 1)))
                   )
                   OR (
                       ap.NGAY_SINH IS NOT NULL
                       AND REGEXP_LIKE(TRIM(CAST(ap.NGAY_SINH AS VARCHAR2(100))), '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$')
                       AND MONTHS_BETWEEN(v_den_ngay,
                             TO_DATE(TRIM(CAST(ap.NGAY_SINH AS VARCHAR2(100))), 'DD/MM/YYYY')) / 12 < 18
                   )
                   OR (
                       ap.NAM_SINH IS NOT NULL AND ap.NAM_SINH > 0
                       AND (EXTRACT(YEAR FROM v_den_ngay) - ap.NAM_SINH) < 18
                   )
               ) THEN 1 ELSE 0 END AS is_doi_tuong_db,
               ap.ma_trai_giam
        FROM active_pn ap
    ) a;

    IF v_ids.COUNT = 0 THEN
        IF p_ma_trai_giam IS NOT NULL THEN
            DELETE FROM QLPN.PN_DK_THOI_GIAN_CACHE c
             WHERE c.MA_TRAI_GIAM = p_ma_trai_giam
               AND TRUNC(c.NGAY_XET) = TRUNC(v_den_ngay);
            DELETE FROM QLPN.PN_TG_HIEN_THI_CACHE c
             WHERE c.MA_TRAI_GIAM = p_ma_trai_giam
               AND TRUNC(c.NGAY_XET) = TRUNC(v_den_ngay);
        ELSE
            DELETE FROM QLPN.PN_DK_THOI_GIAN_CACHE
             WHERE TRUNC(NGAY_XET) = TRUNC(v_den_ngay);
            DELETE FROM QLPN.PN_TG_HIEN_THI_CACHE
             WHERE TRUNC(NGAY_XET) = TRUNC(v_den_ngay);
        END IF;
        COMMIT;
        set_message(u'OK', 0, v_xl_cnt, 0);
        DBMS_OUTPUT.PUT_LINE(p_message);
        RETURN;
    END IF;

    v_num_tbl := QLPN.NUM_TBL();
    v_ct_giam_tbl := QLPN.NUM_TBL();
    v_ct_ctg_tbl  := QLPN.NUM_TBL();
    v_dt_db_tbl   := QLPN.NUM_TBL();
    v_num_tbl.EXTEND(v_ids.COUNT);
    v_ct_giam_tbl.EXTEND(v_ids.COUNT);
    v_ct_ctg_tbl.EXTEND(v_ids.COUNT);
    v_dt_db_tbl.EXTEND(v_ids.COUNT);
    FOR i IN 1 .. v_ids.COUNT LOOP
        v_num_tbl(i)     := v_ids(i);
        v_ct_giam_tbl(i) := v_ct_giam(i);
        v_ct_ctg_tbl(i)  := v_ct_ctg(i);
        v_dt_db_tbl(i)   := v_dt_db(i);
    END LOOP;

    QLPN.PKG_TINH_AN.SP_SNAPSHOT_TCDK_BATCH(
        v_num_tbl,
        v_den_ngay,
        CASE WHEN p_ma_trai_giam IS NULL THEN 1 ELSE 0 END
    );

    SELECT s.pn_id,
           s.dieu_kien_thoi_gian,
           NVL(s.tg_da_giam, u''),
           NVL(s.tg_chap_hanh, u''),
           NVL(s.tg_con_lai, u'')
    BULK COLLECT INTO v_ids, v_dk_tg_result, v_tg_da_giam, v_tg_chap_hanh, v_tg_con_lai
    FROM TABLE(QLPN.PKG_TINH_AN.FN_SNAPSHOT_TCDK_BATCH(
        v_num_tbl, v_den_ngay, v_ct_giam_tbl, v_ct_ctg_tbl, v_dt_db_tbl
    )) s;

    -- DELETE + INSERT thay vì MERGE (tránh lock conflict); ch? k? hi?n t?i
    IF p_ma_trai_giam IS NOT NULL THEN
        DELETE FROM QLPN.PN_DK_THOI_GIAN_CACHE c
         WHERE c.MA_TRAI_GIAM = p_ma_trai_giam
           AND TRUNC(c.NGAY_XET) = TRUNC(v_den_ngay);
    ELSE
        DELETE FROM QLPN.PN_DK_THOI_GIAN_CACHE
         WHERE TRUNC(NGAY_XET) = TRUNC(v_den_ngay);
    END IF;

    FORALL i IN 1 .. v_ids.COUNT
        INSERT INTO QLPN.PN_DK_THOI_GIAN_CACHE
            (PHAM_NHAN_ID, NGAY_XET, MA_TRAI_GIAM, IS_CHUNG_THAN_GIAM, IS_CHUNG_THAN_CTG, IS_DOI_TUONG_DB,
             DIEU_KIEN_THOI_GIAN, LAST_REFRESHED)
        VALUES
            (v_ids(i), v_den_ngay, v_ma_trai(i), v_ct_giam(i), v_ct_ctg(i), v_dt_db(i),
             v_dk_tg_result(i), SYSDATE);

    IF p_ma_trai_giam IS NOT NULL THEN
        DELETE FROM QLPN.PN_TG_HIEN_THI_CACHE c
         WHERE c.MA_TRAI_GIAM = p_ma_trai_giam
           AND TRUNC(c.NGAY_XET) = TRUNC(v_den_ngay);
    ELSE
        DELETE FROM QLPN.PN_TG_HIEN_THI_CACHE
         WHERE TRUNC(NGAY_XET) = TRUNC(v_den_ngay);
    END IF;

    FORALL i IN 1 .. v_ids.COUNT
        INSERT INTO QLPN.PN_TG_HIEN_THI_CACHE
            (PHAM_NHAN_ID, NGAY_XET, MA_TRAI_GIAM, TG_DA_GIAM, TG_CHAP_HANH, TG_CON_LAI, LAST_REFRESHED)
        VALUES
            (v_ids(i), v_den_ngay, v_ma_trai(i), v_tg_da_giam(i), v_tg_chap_hanh(i), v_tg_con_lai(i), SYSDATE);

    COMMIT;

    set_message(u'OK', v_ids.COUNT, v_xl_cnt, v_ids.COUNT);
    DBMS_OUTPUT.PUT_LINE(p_message);

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        set_message(u'ERROR', NVL(v_ids.COUNT, 0), NVL(v_xl_cnt, 0), NVL(v_ids.COUNT, 0));
        p_message := p_message || u' | CHI_TIET=' || TO_NCHAR(SQLERRM);
        RAISE;
END SP_REFRESH_PN_TCDK_CACHE;



/
--------------------------------------------------------
--  DDL for Procedure SP_REFRESH_PN_TINH_TRANG_NGAY_CACHE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_REFRESH_PN_TINH_TRANG_NGAY_CACHE" (
    p_ngay_xet IN DATE DEFAULT NULL,
    p_force    IN NUMBER DEFAULT 0
) AS
    v_ngay_xet DATE := TRUNC(NVL(p_ngay_xet, SYSDATE));
    v_cnt      NUMBER;
    c_retention_months CONSTANT PLS_INTEGER := 3;
BEGIN
--    DELETE FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE
--     WHERE NGAY_XET < ADD_MONTHS(TRUNC(SYSDATE), -c_retention_months);
--    COMMIT;

    IF NVL(p_force, 0) = 0 THEN
        SELECT COUNT(*)
          INTO v_cnt
          FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE c
         WHERE c.NGAY_XET = v_ngay_xet
           AND ROWNUM = 1;
        IF v_cnt > 0 THEN
            RETURN;
        END IF;
    END IF;

    DELETE FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE
     WHERE NGAY_XET = v_ngay_xet;

    -- Ngu?n dùng chung v?i SP_CALC_TINH_TRANG_PHAM_NHAN — xem
    -- docs/reports/QLPN/Dashboard/FN_TINH_TRANG_PN_TAI_NGAY.sql. N?i dung logic ?u tiên
    -- (base/rel/txact/tx20/cb/gr/cand) ?ã ???c di chuy?n nguyên v?n vào hàm dùng chung ?ó.
    INSERT /*+ NO_PARALLEL */ INTO QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE (
        NGAY_XET,
        PN_LAI_LICH_ID,
        TTPN_MA,
        REFRESH_TIME
    )
    SELECT v_ngay_xet, f.PN_ID, f.TTPN_MA, SYSDATE
      FROM TABLE(QLPN.FN_TINH_TRANG_PN_TAI_NGAY(v_ngay_xet, NULL)) f;

    COMMIT;

    BEGIN
        DBMS_MVIEW.REFRESH('QLPN.MV_PN_DANG_CHAP_HANH_AN_NGAY', 'C');
    EXCEPTION
        WHEN OTHERS THEN
            IF SQLCODE != -12003 THEN
                RAISE;
            END IF;
    END;
END SP_REFRESH_PN_TINH_TRANG_NGAY_CACHE;

/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_BENH_TAT_HIEN_TAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_BENH_TAT_HIEN_TAI" (
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
        WITH

    selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ),
             pham_nhan_filtered AS ( SELECT ll.PHAM_NHAN_ID,
                                           ll.LL_DM_GIOI_TINH_ID,
                                           ll.LL_BENH_HIEN_TAI_ID
                                    FROM pn_base ll
                                             LEFT JOIN DM_TRAI_GIAMS dtg
                                                       ON dtg.ID = ll.LL_TRAI_GIAM_ID
                                                           AND dtg.IS_DELETED = 0
                                             LEFT JOIN DM_QUOC_TICHS dqt
                                                       ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                                                           AND dqt.IS_DELETED = 0
-- FILTER START
                                    WHERE ll.IS_DELETED = 0
                                      AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

                                      -- NHÓM 1: Kho?ng ngày
                                      AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                      AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                      AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                      AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                                      AND (
                                        (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM PN_DAC_XAS dxa
                                                       WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                                                         AND dxa.IS_DELETED = 0
                                                         AND (p_dac_xa_tu_ngay IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                                         AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
                                        )
                                      AND (
                                        (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM GIAM_THOI_HANS gaan
                                                       WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                         AND gaan.IS_DELETED = 0
                                                         AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                                        )

                                      -- NHÓM 2: Kho?ng s?
                                      AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
                                      AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                                      AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                                      AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                                      AND (p_tg_chap_hanh_tu IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                                      AND (p_tg_chap_hanh_den IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                                      AND (p_tg_con_lai_tu IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                                      AND (p_tg_con_lai_den IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                                      -- NHÓM 3: Danh m?c
                                      AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
                                      AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
                                      AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
                                      AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                                      AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
                                      AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

                                      -- [T?i danh]
                                      AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
                                      AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                                      AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG = p_loai_doi_tuong_id)

                                      -- [Ghi chú riêng]
                                      AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

                                      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                                      -- NHÓM 4: Checkbox
                                      AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
                                      AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
                                      AND (p_giam_rieng IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PN_GIAM_RIENGS gr
                                                         WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                                                           AND gr.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_giam_rieng
                                        ))
                                      AND (
								    p_dan_toc_thieu_so IS NULL
								    OR (
								        CASE
								            WHEN EXISTS (
								                SELECT 1
								                FROM DM_DAN_TOCS dt
								                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
								                  AND dt.IS_DELETED = 0
								                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
								            )
								            THEN 1
								            ELSE 0
								        END = p_dan_toc_thieu_so
								    )
								)
                                      AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                                        CASE
                                            WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_thoi_diem_pham_toi
                                        ))
                                      AND (p_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PHAM_TOI_MOIS ptm
                                                         WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_pham_toi_moi
                                        ))
                                      AND (p_theo_ton_giao IS NULL OR (
								        CASE
								            WHEN EXISTS (
								                SELECT 1
								                FROM DM_TON_GIAOS tg
								                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
								                  AND tg.IS_DELETED = 0

								            )
								            THEN 1
								            ELSE 0
								        END = p_theo_ton_giao ))
                                      AND (p_vtn_hien_tai IS NULL OR (
                                        CASE
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_hien_tai
                                        ))
                                      AND (p_khong_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN NOT EXISTS (SELECT 1
                                                             FROM PHAM_TOI_MOIS ptm
                                                             WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                               AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_khong_pham_toi_moi
                                        ))
                                      AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
                                      AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
                                      AND (p_da_bi_ky_luat IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KY_LUATS kl
                                                         WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID) THEN 1
                                            ELSE 0 END = p_da_bi_ky_luat
                                        ))
                                      AND (p_co_ghi_chu_dac_biet IS NULL OR (
                                        CASE
                                            WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                                                AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                                                THEN 1
                                            ELSE 0 END = p_co_ghi_chu_dac_biet
                                        ))
                                      AND (p_toi_pham_anqg IS NULL OR (
                                          CASE WHEN EXISTS (
                                              SELECT 1 FROM DM_TOI_DANHS td
                                              WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                                                AND td.IS_DELETED = 0
                                                AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                                          ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                                      ))
                                      AND (p_da_duoc_khen_thuong IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KHEN_THUONGS kt
                                                         WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND kt.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_da_duoc_khen_thuong
                                        ))
                                      AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
                                      AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
                                      AND (p_con_theo_me_vao_trai IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM THAN_NHAN_CON_CAIS tncc
                                                         WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND tncc.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_con_theo_me_vao_trai
                                        ))
                                      AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
                                      AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
                                      AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
                                      AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))),
-- FILTER DONE

    pham_nhan_labeled AS (
        SELECT
            pnf.PHAM_NHAN_ID,
            pnf.LL_DM_GIOI_TINH_ID,
            CASE
                WHEN pnf.LL_BENH_HIEN_TAI_ID IS NULL THEN u'Kh\00f4ng b\1ec7nh t\1eadt'
                WHEN EXISTS (
                    SELECT 1 FROM DM_BENH_TATS dbt
                    WHERE dbt.ID = pnf.LL_BENH_HIEN_TAI_ID
                      AND dbt.IS_DELETED = 0
                      AND dbt.BT_MA = '1'
                ) THEN u'Kh\00f4ng b\1ec7nh t\1eadt'
                ELSE u'C\00f3 b\1ec7nh t\1eadt'
            END AS BENH_LABEL
        FROM pham_nhan_filtered pnf
    ),
    chi_tiet_raw AS (
        SELECT
            lbl.BENH_LABEL                                                                   AS "BenhHienTai",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam'    THEN lbl.PHAM_NHAN_ID END)      AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN lbl.PHAM_NHAN_ID END)      AS "Nu",
            COUNT(DISTINCT CASE
                               WHEN dgt.GT_TEN IS NULL OR dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                   THEN lbl.PHAM_NHAN_ID
                  END)                                                                       AS "Khac",
            COUNT(DISTINCT lbl.PHAM_NHAN_ID)                                                AS "TongSo"
        FROM pham_nhan_labeled lbl
            LEFT JOIN DM_GIOI_TINHS dgt
                ON lbl.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
        GROUP BY lbl.BENH_LABEL
    ),

					chi_tiet AS (
					    SELECT
					        ROW_NUMBER() OVER (ORDER BY "BenhHienTai")          AS SORT_ORDER,
					        TO_NCHAR(TO_CHAR(
					            ROW_NUMBER() OVER (ORDER BY "BenhHienTai")
					        ))                                                   AS "TT",
					        "BenhHienTai",
					        "Nam",
					        "Nu",
					        "Khac",
					        "TongSo"
					    FROM chi_tiet_raw
					)
        SELECT "TT",
               "BenhHienTai",
               "Nam",
               "Nu",
               "Khac",
               "TongSo"
        FROM (SELECT SORT_ORDER,
                     "TT",
                     "BenhHienTai",
                     "Nam",
                     "Nu",
                     "Khac",
                     "TongSo"
              FROM chi_tiet

              UNION ALL

              SELECT 999,
                     TO_NCHAR(''),
                     TO_NCHAR(u'T\1ed5ng s\1ed1'),
                     SUM("Nam"),
                     SUM("Nu"),
                     SUM("Khac"),
                     SUM("TongSo")
              FROM chi_tiet)
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_BENH_TAT_HIEN_TAI;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_BENH_TAT_KHI_VAO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_BENH_TAT_KHI_VAO" (
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
        WITH

    selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ),
             pham_nhan_filtered AS ( SELECT ll.PHAM_NHAN_ID,
                                           ll.LL_DM_GIOI_TINH_ID,
                                           ll.LL_BENH_TAT_VAO_ID
                                    FROM pn_base ll
                                             LEFT JOIN DM_TRAI_GIAMS dtg
                                                       ON dtg.ID = ll.LL_TRAI_GIAM_ID
                                                           AND dtg.IS_DELETED = 0
                                             LEFT JOIN DM_QUOC_TICHS dqt
                                                       ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                                                           AND dqt.IS_DELETED = 0
-- FILTER START
                                    WHERE ll.IS_DELETED = 0
                                      AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

                                      -- NHÓM 1: Kho?ng ngày
                                    AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                    AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                    AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                    AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                                      AND (
                                        (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM PN_DAC_XAS dxa
                                                       WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                                                         AND dxa.IS_DELETED = 0
                                                         AND (p_dac_xa_tu_ngay IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                                         AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
                                        )
                                      AND (
                                        (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM GIAM_THOI_HANS gaan
                                                       WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                         AND gaan.IS_DELETED = 0
                                                         AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                                        )

                                      -- NHÓM 2: Kho?ng s?
                                      AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
                                      AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                                      AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                                      AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                                      AND (p_tg_chap_hanh_tu IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                                      AND (p_tg_chap_hanh_den IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                                      AND (p_tg_con_lai_tu IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                                      AND (p_tg_con_lai_den IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                                      -- NHÓM 3: Danh m?c
                                      AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
                                      AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
                                      AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
                                      AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                                      AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
                                      AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

                                      -- [T?i danh]
                                      AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
                                      AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                                      AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG = p_loai_doi_tuong_id)

                                      -- [Ghi chú riêng]
                                      AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

                                      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                                      -- NHÓM 4: Checkbox
                                      AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
                                      AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
                                      AND (p_giam_rieng IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PN_GIAM_RIENGS gr
                                                         WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                                                           AND gr.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_giam_rieng
                                        ))
                                      AND (
								    p_dan_toc_thieu_so IS NULL
								    OR (
								        CASE
								            WHEN EXISTS (
								                SELECT 1
								                FROM DM_DAN_TOCS dt
								                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
								                  AND dt.IS_DELETED = 0
								                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
								            )
								            THEN 1
								            ELSE 0
								        END = p_dan_toc_thieu_so
								    )
								)
                                      AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                                        CASE
                                            WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_thoi_diem_pham_toi
                                        ))
                                      AND (p_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PHAM_TOI_MOIS ptm
                                                         WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_pham_toi_moi
                                        ))
                                      AND (p_theo_ton_giao IS NULL OR (
								        CASE
								            WHEN EXISTS (
								                SELECT 1
								                FROM DM_TON_GIAOS tg
								                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
								                  AND tg.IS_DELETED = 0

								            )
								            THEN 1
								            ELSE 0
								        END = p_theo_ton_giao ))
                                      AND (p_vtn_hien_tai IS NULL OR (
                                        CASE
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_hien_tai
                                        ))
                                      AND (p_khong_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN NOT EXISTS (SELECT 1
                                                             FROM PHAM_TOI_MOIS ptm
                                                             WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                               AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_khong_pham_toi_moi
                                        ))
                                      AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
                                      AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
                                      AND (p_da_bi_ky_luat IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KY_LUATS kl
                                                         WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID) THEN 1
                                            ELSE 0 END = p_da_bi_ky_luat
                                        ))
                                      AND (p_co_ghi_chu_dac_biet IS NULL OR (
                                        CASE
                                            WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                                                AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                                                THEN 1
                                            ELSE 0 END = p_co_ghi_chu_dac_biet
                                        ))
                                      AND (p_toi_pham_anqg IS NULL OR (
                                          CASE WHEN EXISTS (
                                              SELECT 1 FROM DM_TOI_DANHS td
                                              WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                                                AND td.IS_DELETED = 0
                                                AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                                          ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                                      ))
                                      AND (p_da_duoc_khen_thuong IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KHEN_THUONGS kt
                                                         WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND kt.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_da_duoc_khen_thuong
                                        ))
                                      AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
                                      AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
                                      AND (p_con_theo_me_vao_trai IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM THAN_NHAN_CON_CAIS tncc
                                                         WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND tncc.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_con_theo_me_vao_trai
                                        ))
                                      AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
                                      AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
                                      AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
                                      AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))),
-- FILTER DONE

    pham_nhan_labeled AS (
        SELECT
            pnf.PHAM_NHAN_ID,
            pnf.LL_DM_GIOI_TINH_ID,
            CASE
                WHEN pnf.LL_BENH_TAT_VAO_ID IS NULL THEN u'Kh\00f4ng b\1ec7nh t\1eadt'
                WHEN EXISTS (
                    SELECT 1 FROM DM_NGUYEN_NHAN_CHETS dbt
                    WHERE dbt.ID = pnf.LL_BENH_TAT_VAO_ID
                      AND dbt.IS_DELETED = 0
                      AND dbt.NNC_MA = '4999'
                ) THEN u'Kh\00f4ng b\1ec7nh t\1eadt'
                ELSE u'C\00f3 b\1ec7nh t\1eadt'
            END AS BENH_LABEL
        FROM pham_nhan_filtered pnf
    ),
    chi_tiet_raw AS (
        SELECT
            lbl.BENH_LABEL                                                                   AS "BenhTatKhiVao",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam'    THEN lbl.PHAM_NHAN_ID END)      AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN lbl.PHAM_NHAN_ID END)      AS "Nu",
            COUNT(DISTINCT CASE
                               WHEN dgt.GT_TEN IS NULL OR dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                   THEN lbl.PHAM_NHAN_ID
                  END)                                                                       AS "Khac",
            COUNT(DISTINCT lbl.PHAM_NHAN_ID)                                                AS "TongSo"
        FROM pham_nhan_labeled lbl
            LEFT JOIN DM_GIOI_TINHS dgt
                ON lbl.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
        GROUP BY lbl.BENH_LABEL
    ),

					chi_tiet AS (
					    SELECT
					        ROW_NUMBER() OVER (ORDER BY "BenhTatKhiVao")          AS SORT_ORDER,
					        TO_NCHAR(TO_CHAR(
					            ROW_NUMBER() OVER (ORDER BY "BenhTatKhiVao")
					        ))                                                   AS "TT",
					        "BenhTatKhiVao",
					        "Nam",
					        "Nu",
					        "Khac",
					        "TongSo"
					    FROM chi_tiet_raw
					)
        SELECT "TT",
               "BenhTatKhiVao",
               "Nam",
               "Nu",
               "Khac",
               "TongSo"
        FROM (SELECT SORT_ORDER,
                     "TT",
                     "BenhTatKhiVao",
                     "Nam",
                     "Nu",
                     "Khac",
                     "TongSo"
              FROM chi_tiet

              UNION ALL

              SELECT 999,
                     TO_NCHAR(''),
                     TO_NCHAR(u'T\1ed5ng s\1ed1'),
                     SUM("Nam"),
                     SUM("Nu"),
                     SUM("Khac"),
                     SUM("TongSo")
              FROM chi_tiet)
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_BENH_TAT_KHI_VAO;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_CHUONG_TOI_DANH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_CHUONG_TOI_DANH" (
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
        WITH

             selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ),
             pham_nhan_filtered AS ( SELECT ll.PHAM_NHAN_ID,
                                           ll.LL_DM_GIOI_TINH_ID
                                    FROM pn_base ll
                                             LEFT JOIN DM_TRAI_GIAMS dtg
                                                       ON dtg.ID = ll.LL_TRAI_GIAM_ID
                                                           AND dtg.IS_DELETED = 0
                                             LEFT JOIN DM_QUOC_TICHS dqt
                                                       ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                                                           AND dqt.IS_DELETED = 0
-- FILTER START
                                    WHERE ll.IS_DELETED = 0
                                      AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

                                      -- NHÓM 1: Kho?ng ngày
                                        AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                        AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                        AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                        AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                                      AND (
                                        (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM PN_DAC_XAS dxa
                                                       WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                                                         AND dxa.IS_DELETED = 0
                                                         AND (p_dac_xa_tu_ngay IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                                         AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
                                        )
                                      AND (
                                        (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM GIAM_THOI_HANS gaan
                                                       WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                         AND gaan.IS_DELETED = 0
                                                         AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                                        )

                                      -- NHÓM 2: Kho?ng s?
                                    AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
                                      AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                                      AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                                      AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                                      AND (p_tg_chap_hanh_tu IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                                      AND (p_tg_chap_hanh_den IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                                      AND (p_tg_con_lai_tu IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                                      AND (p_tg_con_lai_den IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                                      -- NHÓM 3: Danh m?c
                                      AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
                                      AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
                                      AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
                                      AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                                      AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
                                      AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

                                      -- [T?i danh]
                                      AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
                                      AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                                      AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG = p_loai_doi_tuong_id)

                                      -- [Ghi chú riêng]
                                      AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

                                      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                                      -- NHÓM 4: Checkbox
                                      AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
                                      AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
                                      AND (p_giam_rieng IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PN_GIAM_RIENGS gr
                                                         WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                                                           AND gr.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_giam_rieng
                                        ))
                                      AND (
								    p_dan_toc_thieu_so IS NULL
								    OR (
								        CASE
								            WHEN EXISTS (
								                SELECT 1
								                FROM DM_DAN_TOCS dt
								                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
								                  AND dt.IS_DELETED = 0
								                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
								            )
								            THEN 1
								            ELSE 0
								        END = p_dan_toc_thieu_so
								    )
								)
                                      AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                                        CASE
                                            WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_thoi_diem_pham_toi
                                        ))
                                      AND (p_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PHAM_TOI_MOIS ptm
                                                         WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_pham_toi_moi
                                        ))
                                      AND (p_theo_ton_giao IS NULL OR (
								        CASE
								            WHEN EXISTS (
								                SELECT 1
								                FROM DM_TON_GIAOS tg
								                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
								                  AND tg.IS_DELETED = 0

								            )
								            THEN 1
								            ELSE 0
								        END = p_theo_ton_giao ))
                                      AND (p_vtn_hien_tai IS NULL OR (
                                        CASE
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_hien_tai
                                        ))
                                      AND (p_khong_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN NOT EXISTS (SELECT 1
                                                             FROM PHAM_TOI_MOIS ptm
                                                             WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                               AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_khong_pham_toi_moi
                                        ))
                                      AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
                                      AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
                                      AND (p_da_bi_ky_luat IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KY_LUATS kl
                                                         WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID) THEN 1
                                            ELSE 0 END = p_da_bi_ky_luat
                                        ))
                                      AND (p_co_ghi_chu_dac_biet IS NULL OR (
                                        CASE
                                            WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                                                AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                                                THEN 1
                                            ELSE 0 END = p_co_ghi_chu_dac_biet
                                        ))
                                      AND (p_toi_pham_anqg IS NULL OR (
                                          CASE WHEN EXISTS (
                                              SELECT 1 FROM DM_TOI_DANHS td
                                              WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                                                AND td.IS_DELETED = 0
                                                AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                                          ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                                      ))
                                      AND (p_da_duoc_khen_thuong IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KHEN_THUONGS kt
                                                         WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND kt.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_da_duoc_khen_thuong
                                        ))
                                      AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
                                      AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
                                      AND (p_con_theo_me_vao_trai IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM THAN_NHAN_CON_CAIS tncc
                                                         WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND tncc.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_con_theo_me_vao_trai
                                        ))
                                      AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
                                      AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
                                      AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
                                      AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))),

        split_toi_danh AS (
            SELECT
                ll.PHAM_NHAN_ID  AS THA_PNLAI_LICH_ID,
                TO_NUMBER(TRIM(
                    REGEXP_SUBSTR(
                        REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                        '[^,]+', 1, 1
                    )
                )) AS TOI_DANH_ID,
                TO_NCHAR(DTD.TD_CHUONG) AS TOI_DANH_CHUONG,
                TO_NCHAR(DTD.TD_TEN)    AS TOI_DANH
            FROM pham_nhan_filtered pnf
            INNER JOIN pn_base ll ON ll.PHAM_NHAN_ID = pnf.PHAM_NHAN_ID
            LEFT JOIN DM_TOI_DANHS DTD
                ON DTD.ID = TO_NUMBER(TRIM(
                    REGEXP_SUBSTR(
                        REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                        '[^,]+', 1, 1
                    )
                ))
                AND DTD.TD_CHUONG IS NOT NULL
            WHERE ll.THA_TOI_DANH IS NOT NULL
        ),

        chi_tiet_agg AS (
            SELECT
                std.TOI_DANH_CHUONG                                                              AS CHUONG_MA,
                TO_NCHAR(
                    u'Ch\01b0\01a1ng ' || std.TOI_DANH_CHUONG || u': ' ||
                    NVL(cr.CTD_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')
                )                                                                                AS "ChuongToiDanh",
                COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam'    THEN pnf.PHAM_NHAN_ID END)      AS "Nam",
                COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN pnf.PHAM_NHAN_ID END)      AS "Nu",
                COUNT(DISTINCT CASE
                                   WHEN dgt.GT_TEN IS NULL
                                     OR dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                   THEN pnf.PHAM_NHAN_ID
                               END)                                                              AS "Khac",
                COUNT(DISTINCT pnf.PHAM_NHAN_ID)                                                 AS "TongSo"
            FROM pham_nhan_filtered pnf
            INNER JOIN split_toi_danh std
                ON std.THA_PNLAI_LICH_ID = pnf.PHAM_NHAN_ID
            LEFT JOIN QLPN.DM_CHUONG_TOI_DANHS cr
                ON cr.CTD_MA = std.TOI_DANH_CHUONG
            LEFT JOIN DM_GIOI_TINHS dgt
                ON dgt.ID = pnf.LL_DM_GIOI_TINH_ID AND dgt.IS_DELETED = 0
            GROUP BY
                std.TOI_DANH_CHUONG,
                TO_NCHAR(
                    u'Ch\01b0\01a1ng ' || std.TOI_DANH_CHUONG || u': ' ||
                    NVL(cr.CTD_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')
                )
        ),
        chi_tiet AS (
            SELECT
                TO_NUMBER(CHUONG_MA)                                         AS SORT_ORDER,
                TO_NCHAR(TO_CHAR(
                    ROW_NUMBER() OVER (ORDER BY TO_NUMBER(CHUONG_MA))
                ))                                                           AS "TT",
                "ChuongToiDanh",
                "Nam",
                "Nu",
                "Khac",
                "TongSo"
            FROM chi_tiet_agg
        )
        SELECT "TT",
               "ChuongToiDanh",
               "Nam",
               "Nu",
               "Khac",
               "TongSo"
        FROM (
            SELECT SORT_ORDER, "TT", "ChuongToiDanh", "Nam", "Nu", "Khac", "TongSo"
            FROM chi_tiet

            UNION ALL

            SELECT
                999,
                TO_NCHAR(''),
                TO_NCHAR(u'T\1ed5ng s\1ed1'),
                SUM("Nam"),
                SUM("Nu"),
                SUM("Khac"),
                SUM("TongSo")
            FROM chi_tiet
        )
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_CHUONG_TOI_DANH;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_DAN_TOC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_DAN_TOC" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
    WITH
    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1
    ),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$') THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID            AS pham_nhan_id,
            ll.LL_DM_GIOI_TINH_ID,
            ll.LL_DM_HOC_VAN_ID,
            ll.LL_DM_NGHE_NGHIEP_ID,
            ll.LL_SO_TIEN_AN,
            ll.LL_SO_TIEN_SU,
            ll.LL_DM_DAN_TOC_ID,
            ll.LL_DM_QUOC_TICH_ID,
            ll.LL_DM_TON_GIAO_ID,
            ll.THA_THOI_GIAN_DA_CHAP_HANH,
            ll.THA_THOI_GIAN_CON_LAI
        FROM pn_base ll
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
           AND dqt.IS_DELETED = 0
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
           AND dtg.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)
          -- NHÓM 1: Kho?ng ngày
          AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
          AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
          AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
          AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
          AND (
              (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
              OR EXISTS (SELECT 1 FROM PN_DAC_XAS dxa
                         WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID AND dxa.IS_DELETED = 0
                           AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                           AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
          )
          AND (
              (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
              OR EXISTS (SELECT 1 FROM GIAM_THOI_HANS gaan
                         WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND gaan.IS_DELETED = 0
                           AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                           AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
          )
          -- NHÓM 2: Kho?ng s?
          AND (p_so_tien_an_tu IS NULL OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu))
          AND (p_so_tien_an_den IS NULL OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den))
          AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
          AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
          AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
          AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
          AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
          AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
          AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
          AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
          -- NHÓM 3: Danh m?c
          AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
          AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
          AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
          AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
          AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
          AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
          AND (
              p_toi_danh_ids IS NULL
              OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
              OR EXISTS (SELECT 1 FROM selected_toi_danh_filter loc
                         WHERE INSTR(
                             ',' || REPLACE(REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''), ' ', '') || ',',
                             ',' || TRIM(loc.ma_loc) || ','
                         ) > 0)
          )
          AND (p_dp_dktt_id       IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
          AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG            = p_loai_doi_tuong_id)
          AND (
              p_ghi_chu_rieng_id IS NULL
              OR INSTR(',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ',') > 0
          )
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          -- NHÓM 4: Checkbox
          AND (p_nuoc_ngoai IS NULL OR (
              CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
          ))
          AND (p_co_benh_tat IS NULL OR (
              CASE
                  WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL THEN 1
                  WHEN EXISTS (SELECT 1 FROM DM_BENH_TATS dbt
                               WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                 AND dbt.IS_DELETED = 0 AND dbt.BT_MA = '1') THEN 0
                  ELSE 1
              END = p_co_benh_tat
          ))
          AND (p_giam_rieng IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM PN_GIAM_RIENGS gr
                                WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_giam_rieng
          ))
          AND (
              p_dan_toc_thieu_so IS NULL
              OR (CASE WHEN EXISTS (
                      SELECT 1 FROM DM_DAN_TOCS dt
                      WHERE dt.ID = ll.LL_DM_DAN_TOC_ID AND dt.IS_DELETED = 0
                        AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                  ) THEN 1 ELSE 0 END = p_dan_toc_thieu_so)
          )
          AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
              CASE
                  WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_thoi_diem_pham_toi
          ))
          AND (p_pham_toi_moi IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM PHAM_TOI_MOIS ptm
                                WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_pham_toi_moi
          ))
          AND (p_theo_ton_giao IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM DM_TON_GIAOS tg
                                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID AND tg.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_theo_ton_giao
          ))
          AND (p_vtn_hien_tai IS NULL OR (
              CASE
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_hien_tai
          ))
          AND (p_khong_pham_toi_moi IS NULL OR (
              CASE WHEN NOT EXISTS (SELECT 1 FROM PHAM_TOI_MOIS ptm
                                    WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_khong_pham_toi_moi
          ))
          AND (
              p_co_nghe_nghiep IS NULL
              OR (CASE WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                            AND EXISTS (SELECT 1 FROM DM_NGHE_NGHIEPS dnn
                                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID AND dnn.IS_DELETED = 0
                                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%'))
                       THEN 1 ELSE 0 END = p_co_nghe_nghiep)
          )
          AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
          AND (p_da_bi_ky_luat IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM KY_LUATS kl WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID)
                   THEN 1 ELSE 0 END = p_da_bi_ky_luat
          ))
          AND (p_co_ghi_chu_dac_biet IS NULL OR (
              CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                        AND ll.THA_GHI_CHU_DAC_BIET <> '[]' THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
          ))
          AND (p_toi_pham_anqg IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM DM_TOI_DANHS td
                  WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                    AND td.IS_DELETED = 0
                    AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
              ) THEN 1 ELSE 0 END = p_toi_pham_anqg
          ))
          AND (p_da_duoc_khen_thuong IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM KHEN_THUONGS kt
                                WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
          ))
          AND (p_co_tien_an IS NULL OR (
              CASE WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0' THEN 1 ELSE 0 END = p_co_tien_an
          ))
          AND (p_co_tien_su IS NULL OR (
              CASE WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0' THEN 1 ELSE 0 END = p_co_tien_su
          ))
          AND (p_con_theo_me_vao_trai IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                                WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
          ))
          AND (p_hp_bo_sung_la_tien IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                  WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                    AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
              ) THEN 1 ELSE 0 END = p_hp_bo_sung_la_tien
          ))
          AND (p_bat_buoc_chua_benh IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM CHUA_BENH_BAT_BUOCS cb
                                WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND cb.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_bat_buoc_chua_benh
          ))
          AND (
              p_hoan_xong_hpbs_la_tien IS NULL OR
              (CASE WHEN EXISTS (
                  SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                  WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                    AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                  GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                  HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
              ) THEN 1 ELSE 0 END = p_hoan_xong_hpbs_la_tien)
          )
          AND (
              p_chua_hoan_hpbs_la_tien IS NULL OR
              (CASE WHEN EXISTS (
                  SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                  WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                    AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                  GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                  HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
              ) THEN 1 ELSE 0 END = p_chua_hoan_hpbs_la_tien)
          )
    ),
    pnf_detail AS (
        SELECT
            pnf.pham_nhan_id,
            dgt.GT_TEN,
            ddt.DT_TEN,
            ddt.DT_MA,
            COUNT(*) OVER () AS TOTAL_COUNT
        FROM pham_nhan_filtered pnf
        LEFT JOIN DM_GIOI_TINHS dgt ON dgt.ID = pnf.LL_DM_GIOI_TINH_ID AND dgt.IS_DELETED = 0
        LEFT JOIN DM_DAN_TOCS  ddt  ON ddt.ID = pnf.LL_DM_DAN_TOC_ID   AND ddt.IS_DELETED = 0
    ),
    chi_tiet AS (
        -- Nhóm I: Kinh
        SELECT
            1 AS SORT_ORDER,
            TO_NCHAR('I')    AS "TT",
            TO_NCHAR('Kinh') AS "DanToc",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'Nam'                              THEN pham_nhan_id END) AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef'                           THEN pham_nhan_id END) AS "Nu",
            COUNT(DISTINCT CASE WHEN GT_TEN NOT IN (u'Nam', u'N\1eef')            THEN pham_nhan_id END) AS "Khac",
            COUNT(DISTINCT pham_nhan_id)                                                                 AS "TongSo",
            MAX(TOTAL_COUNT) AS TOTAL_COUNT
        FROM pnf_detail
        WHERE DT_MA = u'01'

        UNION ALL

        -- Nhóm II: Ng??i n??c ngoài
        SELECT
            2 AS SORT_ORDER,
            TO_NCHAR('II')                                   AS "TT",
            TO_NCHAR(u'Ng\01b0\1eddi n\01b0\1edbc ngo\00e0i') AS "DanToc",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'Nam'                   THEN pham_nhan_id END) AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef'                THEN pham_nhan_id END) AS "Nu",
            COUNT(DISTINCT CASE WHEN GT_TEN NOT IN (u'Nam', u'N\1eef') THEN pham_nhan_id END) AS "Khac",
            COUNT(DISTINCT pham_nhan_id)                                                      AS "TongSo",
            MAX(TOTAL_COUNT) AS TOTAL_COUNT
        FROM pnf_detail
        WHERE DT_MA = u'55'

        UNION ALL

        -- Nhóm III: Dân t?c thi?u s?
        SELECT
            3 AS SORT_ORDER,
            TO_NCHAR('III')                              AS "TT",
            TO_NCHAR(u'D\00e2n t\1ed9c thi\1ec3u s\1ed1') AS "DanToc",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'Nam'                   THEN pham_nhan_id END) AS "Nam",
            COUNT(DISTINCT CASE WHEN GT_TEN = u'N\1eef'                THEN pham_nhan_id END) AS "Nu",
            COUNT(DISTINCT CASE WHEN GT_TEN NOT IN (u'Nam', u'N\1eef') THEN pham_nhan_id END) AS "Khac",
            COUNT(DISTINCT pham_nhan_id)                                                      AS "TongSo",
            MAX(TOTAL_COUNT) AS TOTAL_COUNT
        FROM pnf_detail
        WHERE DT_MA != u'01'
          AND DT_MA != u'55'
    )
    SELECT "TT", "DanToc", "Nam", "Nu", "Khac", "TongSo"
    FROM (
        SELECT SORT_ORDER, "TT", "DanToc", "Nam", "Nu", "Khac", "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT 999,
               TO_NCHAR(''),
               TO_NCHAR(u'T\1ed5ng s\1ed1'),
               SUM("Nam"), SUM("Nu"), SUM("Khac"), SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_THONG_KE_DAN_TOC;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_DKTT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_DKTT" (
    p_trai_giam_id IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1          SYS_REFCURSOR;
    v_ngay_tinh DATE := NVL(p_so_lieu_tinh_den_ngay, SYSDATE);
BEGIN

    OPEN C1 FOR
        WITH

    td_split AS (
                    SELECT ptha.THA_PNLAI_LICH_ID,
                           TO_NUMBER(TRIM(
                               REGEXP_SUBSTR(
                                   REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
                                   '[^,]+', 1, 1   -- Luôn l?y ph?n t? ??u tiên
                               )
                           )) AS TOI_DANH_ID,
                           ptha.THA_MUC_AN_ID
                    FROM QLPN.PN_THI_HANH_AN ptha
                    WHERE ptha.IS_DELETED = 0
                      AND ptha.THA_TOI_DANH IS NOT NULL
                ),
             split_toi_danh AS (
                    SELECT td.THA_PNLAI_LICH_ID,
                           td.TOI_DANH_ID,
                           TO_NCHAR(DTD.TD_CHUONG) AS TOI_DANH_CHUONG,
                           TO_NCHAR(DTD.TD_TEN)    AS TOI_DANH
                    FROM td_split td
                    LEFT JOIN DM_TOI_DANHS DTD
                        ON  DTD.ID = td.TOI_DANH_ID
                        AND DTD.TD_CHUONG IS NOT NULL
                ),
             selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM
                    FROM PN_LAI_LICHS ll
                    WHERE ll.IS_DELETED = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
                ), 
             pham_nhan_filtered AS ( SELECT ll.ID AS PHAM_NHAN_ID,
                                           ll.LL_GHI_CHU_RIENG,
                                           ll.LL_DM_GIOI_TINH_ID,
                                           ll.CREATION_TIME,
                                           ll.LL_DIA_CHI_THUONG_TRU_WARD,
                                           ll.LL_DIA_CHI_THUONG_TRU_PROVICE,
                                           ll.LL_DM_QUOC_TICH_ID

                                    FROM pn_base ll

                                             INNER JOIN PN_THI_HANH_AN ptha
            ON ptha.THA_PNLAI_LICH_ID = ll.ID
                AND ptha.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                AND dqt.IS_DELETED = 0

                                             LEFT JOIN PN_DAC_XAS dxa
                                                       ON dxa.PNLAI_LICH_ID = ll.ID
                                                           AND dxa.IS_DELETED = 0

                                             LEFT JOIN GIAM_THOI_HANS gaan
                                                       ON gaan.PHAM_NHAN_ID = ll.ID
                                                           AND gaan.IS_DELETED = 0

                                             LEFT JOIN DM_TRAI_GIAMS dtg
                                                       ON dtg.ID = ll.LL_TRAI_GIAM_ID
                                                           AND dtg.IS_DELETED = 0
-- FILTER START
                                    WHERE ll.IS_DELETED = 0
                                      AND (p_trai_giam_id IS NULL OR dtg.TG_MA = p_trai_giam_id)

                                      -- NHÓM 1: Kho?ng ngày
                                      AND (p_den_trai_tu_ngay  IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                      AND (p_den_trai_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                      AND (p_ra_trai_tu_ngay   IS NULL OR ptha.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                      AND (p_ra_trai_den_ngay  IS NULL OR ptha.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                                      AND (
                                        (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM PN_DAC_XAS dxa
                                                       WHERE dxa.PNLAI_LICH_ID = ll.ID
                                                         AND dxa.IS_DELETED = 0
                                                         AND (p_dac_xa_tu_ngay IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                                         AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
                                        )
                                      AND (
                                        (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM GIAM_THOI_HANS gaan
                                                       WHERE gaan.PHAM_NHAN_ID = ll.ID
                                                         AND gaan.IS_DELETED = 0
                                                         AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                                        )

                                      -- NHÓM 2: Kho?ng s?
                                      AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
                                      AND (p_muc_an_tu IS NULL OR TO_NUMBER(ptha.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ptha.THA_MA_AN_PHAT) <= p_muc_an_den)
                                      AND (p_tuoi_tu IS NULL OR
                                            FLOOR(
                                                MONTHS_BETWEEN(
                                                    TRUNC(v_ngay_tinh),
                                                    CASE
                                                        WHEN ll.LL_NGAY_SINH IS NULL THEN NULL
                                                        -- D?ng ??y ??: DD/MM/YYYY
                                                        WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{2}/\d{4}$')
                                                            THEN TO_DATE(ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                        -- D?ng tháng n?m: MM/YYYY ? l?y ngày 01
                                                        WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{4}$')
                                                            THEN TO_DATE('01/' || ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                        -- D?ng ch? n?m: YYYY ? l?y ngày 01/01
                                                        WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{4}$')
                                                            THEN TO_DATE('01/01/' || ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                        ELSE NULL
                                                    END
                                                ) / 12
                                            ) >= p_tuoi_tu
                                        )
                                        AND (p_tuoi_den IS NULL OR
                                                FLOOR(
                                                    MONTHS_BETWEEN(
                                                        TRUNC(v_ngay_tinh),
                                                        CASE
                                                            WHEN ll.LL_NGAY_SINH IS NULL THEN NULL
                                                            -- D?ng ??y ??: DD/MM/YYYY
                                                            WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{2}/\d{4}$')
                                                                THEN TO_DATE(ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                            -- D?ng tháng n?m: MM/YYYY ? l?y ngày 01
                                                            WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{4}$')
                                                                THEN TO_DATE('01/' || ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                            -- D?ng ch? n?m: YYYY ? l?y ngày 01/01
                                                            WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{4}$')
                                                                THEN TO_DATE('01/01/' || ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                            ELSE NULL
                                                        END
                                                    ) / 12
                                                ) <= p_tuoi_den
                                            )
                                      AND (p_tg_chap_hanh_tu IS NULL OR
                                           ptha.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                                      AND (p_tg_chap_hanh_den IS NULL OR
                                           ptha.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                                      AND (p_tg_con_lai_tu IS NULL OR
                                           ptha.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                                      AND (p_tg_con_lai_den IS NULL OR
                                           ptha.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                                      -- NHÓM 3: Danh m?c
                                      AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
                                      AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
                                      AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
                                      AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                                      AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
                                      AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

                                      -- [T?i danh]
                                      AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
                                      AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                                      AND (p_loai_doi_tuong_id IS NULL OR ptha.THA_DOI_TUONG = p_loai_doi_tuong_id)

                                      -- [Ghi chú riêng]
                                      AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

                                      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                                      -- NHÓM 4: Checkbox
                                      AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
                                      AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
                                      AND (p_giam_rieng IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PN_GIAM_RIENGS gr
                                                         WHERE gr.GR_PN_LAI_LICH_ID = ll.ID
                                                           AND gr.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_giam_rieng
                                        ))
                                      AND (
									    p_dan_toc_thieu_so IS NULL
									    OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_DAN_TOCS dt
									                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
									                  AND dt.IS_DELETED = 0
									                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('1100', '6500')
									            )
									            THEN 1
									            ELSE 0
									        END = p_dan_toc_thieu_so
									    )
									)
                                      AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                                        CASE
                                            WHEN ptha.THA_NGAY_PHAM_TOI IS NULL THEN 0
                                            WHEN ll.LL_NGAY_SINH IS NULL THEN 0
                                            -- D?ng ??y ??: DD/MM/YYYY
                                            WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{2}/\d{4}$')
                                                AND FLOOR(MONTHS_BETWEEN(
                                                                  TRUNC(ptha.THA_NGAY_PHAM_TOI),
                                                                  TO_DATE(ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                          ) / 12) < 18 THEN 1
                                            -- D?ng tháng n?m: MM/YYYY ? l?y ngày 01 c?a tháng ?ó
                                            WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{4}$')
                                                AND FLOOR(MONTHS_BETWEEN(
                                                                  TRUNC(ptha.THA_NGAY_PHAM_TOI),
                                                                  TO_DATE('01/' || ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                          ) / 12) < 18 THEN 1
                                            -- D?ng ch? n?m: YYYY ? l?y ngày 01/01 c?a n?m ?ó
                                            WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{4}$')
                                                AND (EXTRACT(YEAR FROM TRUNC(ptha.THA_NGAY_PHAM_TOI))
                                                    - TO_NUMBER(ll.LL_NGAY_SINH)) < 18 THEN 1

                                            ELSE 0
                                            END = p_vtn_thoi_diem_pham_toi
                                        ))
                                      AND (p_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PHAM_TOI_MOIS ptm
                                                         WHERE ptm.PHAM_NHAN_ID = ll.ID
                                                           AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_pham_toi_moi
                                        ))
                                      AND (p_theo_ton_giao IS NULL OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_TON_GIAOS tg
									                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
									                  AND tg.IS_DELETED = 0
									                  AND tg.TG_MA <>'8'
									            )
									            THEN 1
									            ELSE 0
									        END = p_theo_ton_giao ))
                                      AND (p_vtn_hien_tai IS NULL OR (
                                        CASE
                                            WHEN ll.LL_NGAY_SINH IS NULL THEN 0
                                            -- D?ng ??y ??: DD/MM/YYYY
                                            WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{2}/\d{4}$')
                                                AND FLOOR(MONTHS_BETWEEN(
                                                                  TRUNC(v_ngay_tinh),
                                                                  TO_DATE(ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                          ) / 12) < 18 THEN 1
                                            -- D?ng tháng n?m: MM/YYYY
                                            WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{4}$')
                                                AND FLOOR(MONTHS_BETWEEN(
                                                                  TRUNC(v_ngay_tinh),
                                                                  TO_DATE('01/' || ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                          ) / 12) < 18 THEN 1
                                            -- D?ng ch? n?m: YYYY
                                            WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{4}$')
                                                AND (EXTRACT(YEAR FROM TRUNC(v_ngay_tinh))
                                                    - TO_NUMBER(ll.LL_NGAY_SINH)) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_hien_tai
                                        ))
                                      AND (p_khong_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN NOT EXISTS (SELECT 1
                                                             FROM PHAM_TOI_MOIS ptm
                                                             WHERE ptm.PHAM_NHAN_ID = ll.ID
                                                               AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_khong_pham_toi_moi
                                        ))
                                      AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
                                      AND (p_chung_than IS NULL OR (
    CASE
        WHEN ptha.THA_MA_AN_PHAT IN (
            SELECT dmtg.ID
            FROM DM_MA_THOI_GIANS dmtg
            WHERE dmtg.MTG_MA IN ('911000', '912000')
              AND dmtg.IS_DELETED = 0
        ) THEN 1
        ELSE 0
    END = p_chung_than
))
                                      AND (p_da_bi_ky_luat IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KY_LUATS kl
                                                         WHERE kl.PHAM_NHAN_ID = ll.ID) THEN 1
                                            ELSE 0 END = p_da_bi_ky_luat
                                        ))
                                      AND (p_co_ghi_chu_dac_biet IS NULL OR (
                                        CASE
                                            WHEN ptha.THA_GHI_CHU_DAC_BIET IS NOT NULL
                                                AND ptha.THA_GHI_CHU_DAC_BIET <> '[]'
                                                THEN 1
                                            ELSE 0 END = p_co_ghi_chu_dac_biet
                                        ))
                                      AND (p_toi_pham_anqg IS NULL OR (
					                       CASE
					                           WHEN EXISTS (
					                               SELECT 1
					                               FROM PN_THI_HANH_AN ptha2
					                               JOIN DM_TOI_DANHS td
					                                   ON td.ID = TO_NUMBER(TRIM(
					                                                  REGEXP_SUBSTR(
					                                                      REPLACE(REPLACE(ptha2.THA_TOI_DANH, '[', ''), ']', ''),
					                                                      '[^,]+', 1, 1  -- Ch? l?y t?i danh ??u tiên
					                                                  )
					                                              ))
					                                   AND td.IS_DELETED = 0
					                                   AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'  -- Thu?c ch??ng 13
					                               WHERE ptha2.THA_PNLAI_LICH_ID = ll.ID
					                                 AND ptha2.IS_DELETED = 0
					                                 AND ptha2.THA_TOI_DANH IS NOT NULL
					                                 AND LENGTH(REPLACE(REPLACE(REPLACE(ptha2.THA_TOI_DANH, '[', ''), ']', ''), ' ', '')) > 0
					                           ) THEN 1
					                           ELSE 0
					                       END = p_toi_pham_anqg
					                   ))
                                      AND (p_da_duoc_khen_thuong IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KHEN_THUONGS kt
                                                         WHERE kt.PHAM_NHAN_ID = ll.ID
                                                           AND kt.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_da_duoc_khen_thuong
                                        ))
                                      AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
                                      AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
                                      AND (p_con_theo_me_vao_trai IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM THAN_NHAN_CON_CAIS tncc
                                                         WHERE tncc.PHAM_NHAN_ID = ll.ID
                                                           AND tncc.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_con_theo_me_vao_trai
                                        ))
                                      AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
                                      AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
                                      AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
                                      AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))),
-- FILTER DONE

-- =========================
-- MAP GI?I TÍNH
-- =========================
             base AS (SELECT ll.*,
                             CASE
                                 WHEN QT_MA = '250' THEN 'VN'
                                 ELSE 'NN'
                                 END                      AS LOAI,
                             dmtt.TTP_TEN                 AS TEN_TINH,
                             dmxp.XP_TEN                  AS TEN_PHUONG_XA,
                             NVL(dgt.GT_TEN, u'Kh\00e1c') AS GIOI_TINH
                      FROM pham_nhan_filtered ll
                               LEFT JOIN DM_GIOI_TINHS dgt
                                         ON dgt.ID = ll.LL_DM_GIOI_TINH_ID
                                             AND dgt.IS_DELETED = 0
                               LEFT JOIN DM_QUOC_TICHS dqt
                                         ON ll.LL_DM_QUOC_TICH_ID = dqt.ID AND dqt.IS_DELETED = 0
                               LEFT JOIN DM_TINH_THANH_PHO dmtt
                                         ON dmtt.ID = ll.LL_DIA_CHI_THUONG_TRU_PROVICE
                               LEFT JOIN DM_XA_PHUONG dmxp
                                         ON dmxp.ID = ll.LL_DIA_CHI_THUONG_TRU_WARD
                      WHERE (v_ngay_tinh IS NULL OR TRUNC(ll.CREATION_TIME) < TRUNC(v_ngay_tinh) + 1)),

-- =========================
-- RANK LO?I (VN / NN)
-- =========================
             loai_rank AS (SELECT DISTINCT LOAI,
                                           DENSE_RANK() OVER (ORDER BY LOAI) AS STT
                           FROM base),

-- =========================
-- T?NG THEO LO?I
-- =========================
             tong_loai AS (SELECT lr.STT                                                                  AS SORT_ORDER,
                                  TO_NCHAR('-')                                                           AS "TT",
                                  CASE
                                      WHEN lr.LOAI = 'NN' THEN u'\0110KTT \1edf n\01b0\1edbc ngo\00e0i'
                                      ELSE u'\0110KTT t\1ea1i Vi\1ec7t Nam'
                                      END                                                                 AS "DiaChiThuongTru",

                                  COUNT(DISTINCT CASE WHEN GIOI_TINH = u'Nam' THEN b.PHAM_NHAN_ID END)    AS "Nam",
                                  COUNT(DISTINCT CASE WHEN GIOI_TINH = u'N\1eef' THEN b.PHAM_NHAN_ID END) AS "Nu",
                                  COUNT(DISTINCT CASE
                                                     WHEN GIOI_TINH NOT IN (u'Nam', u'N\1eef')
                                                         THEN b.PHAM_NHAN_ID END)                         AS "Khac",
                                  COUNT(DISTINCT b.PHAM_NHAN_ID)                                          AS "TongSo"

                           FROM base b
                                    JOIN loai_rank lr ON lr.LOAI = b.LOAI
                           GROUP BY lr.STT, lr.LOAI),

-- =========================
-- CHI TI?T T?NH (CH? VN)
-- =========================
             chi_tiet AS (SELECT lr.STT
                                     + ROW_NUMBER() OVER (
                     PARTITION BY lr.LOAI
                     ORDER BY b.TEN_TINH
                     ) * 0.001                                                                           AS SORT_ORDER,
                                 TO_NCHAR('+')                                                           AS "TT",
                                 NVL(b.TEN_TINH, TO_NCHAR(u'Không rõ'))                                  AS "DiaChiThuongTru",
                                 COUNT(DISTINCT CASE WHEN GIOI_TINH = u'Nam' THEN b.pham_nhan_id END)    AS "Nam",
                                 COUNT(DISTINCT CASE WHEN GIOI_TINH = u'N\1eef' THEN b.pham_nhan_id END) AS "Nu",
                                 COUNT(DISTINCT CASE
                                                    WHEN GIOI_TINH NOT IN (u'Nam', u'N\1eef')
                                                        THEN b.pham_nhan_id END)                         AS "Khac",
                                 COUNT(DISTINCT b.pham_nhan_id)                                          AS "TongSo"

                          FROM base b
                                   JOIN loai_rank lr ON lr.LOAI = b.LOAI
                          WHERE lr.LOAI = 'VN'
                          GROUP BY lr.STT, lr.LOAI, b.TEN_TINH),

-- =========================
-- UNION ALL + TOTAL
-- =========================
            final_data AS (SELECT *
                            FROM tong_loai
                            UNION ALL
                            SELECT *
                            FROM chi_tiet)

        SELECT
            "TT",
            "DiaChiThuongTru",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM (
            -- Các dòng chi ti?t (tong_loai + chi_tiet)
            SELECT SORT_ORDER, "TT", "DiaChiThuongTru", "Nam", "Nu", "Khac", "TongSo"
            FROM final_data

            UNION ALL

            -- ? FIX: Ch? SUM t? tong_loai, KHÔNG l?y t? chi_tiet
            SELECT 999,
                   TO_NCHAR(''),
                   TO_NCHAR(u'T?ng s?'),
                   SUM("Nam"),
                   SUM("Nu"),
                   SUM("Khac"),
                   SUM("TongSo")
            FROM tong_loai   -- ? thay final_data thành tong_loai
        )
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_DKTT;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_DO_TUOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_DO_TUOI" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE,
            FLOOR(MONTHS_BETWEEN(v_ngay_tinh,
                QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH)) / 12) AS TUOI_HIEN_TAI
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID,
            ll.TUOI_HIEN_TAI
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
           AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
           AND dqt.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)
          -- NHOM 1: Khoang ngay
          AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
          AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
          AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
          AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
          AND (
              (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1 FROM PN_DAC_XAS dxa
                  WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND dxa.IS_DELETED = 0
                    AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                    AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
              )
          )
          AND (
              (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1 FROM GIAM_THOI_HANS gaan
                  WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND gaan.IS_DELETED   = 0
                    AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                    AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
              )
          )
          -- NHOM 2: Khoang so
          AND (
              p_so_tien_an_tu IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
          )
          AND (
              p_so_tien_an_den IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
          )
          AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
          AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
          AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
          AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
          AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
          AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
          AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
          AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
          -- NHOM 3: Danh muc
          AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
          AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
          AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
          AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
          AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
          AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
          -- [Toi danh]
          AND (
              p_toi_danh_ids IS NULL
              OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
              OR EXISTS (SELECT 1
                         FROM selected_toi_danh_filter loc
                         WHERE INSTR(
                                     ',' || REPLACE(
                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                             ' ', '') || ',',
                                     ',' || TRIM(loc.ma_loc) || ','
                             ) > 0)
          )
          AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
          AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)
          -- [Ghi chu rieng]
          AND (
              p_ghi_chu_rieng_id IS NULL
              OR INSTR(
                         ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                         ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                     ) > 0
          )
          AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)
          -- NHOM 4: Checkbox
          -- [Nuoc ngoai]
          AND (p_nuoc_ngoai IS NULL OR (
              CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
          ))
          -- [Co benh tat]
          AND (p_co_benh_tat IS NULL OR (
              CASE
                  WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL THEN 1
                  WHEN EXISTS (
                      SELECT 1 FROM DM_BENH_TATS dbt
                      WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0 AND dbt.BT_MA = '1'
                  ) THEN 0
                  ELSE 1
              END = p_co_benh_tat
          ))
          -- [Giam rieng]
          AND (p_giam_rieng IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PN_GIAM_RIENGS gr
                  WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_giam_rieng
          ))
          -- [Dan toc thieu so]
          AND (
              p_dan_toc_thieu_so IS NULL
              OR (
                  CASE
                      WHEN EXISTS (
                          SELECT 1 FROM DM_DAN_TOCS dt
                          WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                            AND dt.IS_DELETED = 0
                            AND NVL(dt.DT_MA, 'NULL') NOT IN ('1', '55')
                      ) THEN 1
                      ELSE 0
                  END = p_dan_toc_thieu_so
              )
          )
          -- [VTN tai thoi diem pham toi]
          AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
              CASE
                  WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_thoi_diem_pham_toi
          ))
          -- [Pham toi moi]
          AND (p_pham_toi_moi IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_pham_toi_moi
          ))
          -- [Theo ton giao]
          AND (p_theo_ton_giao IS NULL OR (
              CASE
                  WHEN EXISTS (
                      SELECT 1 FROM DM_TON_GIAOS tg
                      WHERE tg.ID = ll.LL_DM_TON_GIAO_ID AND tg.IS_DELETED = 0
                  ) THEN 1
                  ELSE 0
              END = p_theo_ton_giao
          ))
          -- [VTN hien tai]
          AND (p_vtn_hien_tai IS NULL OR (
              CASE
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_hien_tai
          ))
          -- [Khong pham toi moi]
          AND (p_khong_pham_toi_moi IS NULL OR (
              CASE WHEN NOT EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
          ))
          -- [Co nghe nghiep]
          AND (
              p_co_nghe_nghiep IS NULL
              OR (
                  CASE
                      WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                           AND EXISTS (
                               SELECT 1 FROM DM_NGHE_NGHIEPS dnn
                               WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                 AND dnn.IS_DELETED = 0
                                 AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                           )
                      THEN 1
                      ELSE 0
                  END = p_co_nghe_nghiep
              )
          )
          -- [Chung than]
          AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
          -- [Da bi ky luat]
          AND (p_da_bi_ky_luat IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KY_LUATS kl WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
              ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
          ))
          -- [Co ghi chu dac biet]
          AND (p_co_ghi_chu_dac_biet IS NULL OR (
              CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                    AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                   THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
          ))
          -- [Toi pham ANQG]
          AND (p_toi_pham_anqg IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM DM_TOI_DANHS td
                  WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                    AND td.IS_DELETED = 0
                    AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
              ) THEN 1 ELSE 0 END = p_toi_pham_anqg
          ))
          -- [Da duoc khen thuong]
          AND (p_da_duoc_khen_thuong IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KHEN_THUONGS kt
                  WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
          ))
          -- [Co tien an]
          AND (p_co_tien_an IS NULL OR (
              CASE WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0' THEN 1 ELSE 0 END = p_co_tien_an
          ))
          -- [Co tien su]
          AND (p_co_tien_su IS NULL OR (
              CASE WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0' THEN 1 ELSE 0 END = p_co_tien_su
          ))
          -- [Con theo me vao trai]
          AND (p_con_theo_me_vao_trai IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                  WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
          ))
          -- [Hinh phat bo sung la tien]
          AND (p_hp_bo_sung_la_tien IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                    ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                  WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                    AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
              ) THEN 1 ELSE 0 END = p_hp_bo_sung_la_tien
          ))
          -- [Bat buoc chua benh]
          AND (p_bat_buoc_chua_benh IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM CHUA_BENH_BAT_BUOCS cb
                  WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND cb.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_bat_buoc_chua_benh
          ))
          -- [Hoan xong HPBS la tien]
          AND (
              p_hoan_xong_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                  ) THEN 1 ELSE 0
              END = p_hoan_xong_hpbs_la_tien)
          )
          -- [Chua hoan xong HPBS la tien]
          AND (p_chua_hoan_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                  ) THEN 1 ELSE 0
              END = p_chua_hoan_hpbs_la_tien))
    ),

    ranges AS (
        SELECT 1 ID, u'D\01b0\1edbi 18 tu\1ed5i'          ten, 0  tu, 17  den FROM dual UNION ALL
        SELECT 2,    u'T\1eeb 18 - d\01b0\1edbi 30 tu\1ed5i', 18, 29  FROM dual UNION ALL
        SELECT 3,    u'T\1eeb 30 - d\01b0\1edbi 45 tu\1ed5i', 30, 44  FROM dual UNION ALL
        SELECT 4,    u'T\1eeb 45 - d\01b0\1edbi 55 tu\1ed5i', 45, 54  FROM dual UNION ALL
        SELECT 5,    u'T\1eeb 55 - d\01b0\1edbi 60 tu\1ed5i', 55, 59  FROM dual UNION ALL
        SELECT 6,    u'T\1eeb 60 - d\01b0\1edbi 70 tu\1ed5i', 60, 69  FROM dual UNION ALL
        SELECT 7,    u'T\1eeb 70 tu\1ed5i tr\1edf l\00ean',   70, 200 FROM dual
    ),

    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY r.ID)                    AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY r.ID))) AS "TT",
            NVL(TO_NCHAR(r.ten), u'Kh\00f4ng r\00f5')           AS "DoTuoi",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam'    THEN 1 END)   AS "Nam",
            COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END)   AS "Nu",
            COUNT(CASE WHEN gt.GT_TEN IS NULL
                            OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*)                                             AS "TongSo"
        FROM pham_nhan_filtered ll
        LEFT JOIN ranges r
            ON ll.TUOI_HIEN_TAI BETWEEN r.tu AND r.den
        LEFT JOIN DM_GIOI_TINHS gt
            ON gt.ID = ll.LL_DM_GIOI_TINH_ID AND gt.IS_DELETED = 0
        GROUP BY r.ID, NVL(TO_NCHAR(r.ten), u'Kh\00f4ng r\00f5')
    )

    SELECT "TT", "DoTuoi", "Nam", "Nu", "Khac", "TongSo"
    FROM (
        SELECT SORT_ORDER, "TT", "DoTuoi", "Nam", "Nu", "Khac", "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT 999,
               TO_NCHAR(''),
               TO_NCHAR(u'T\1ed5ng s\1ed1'),
               SUM("Nam"),
               SUM("Nu"),
               SUM("Khac"),
               SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_DO_TUOI;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_DO_TUOI_PHAM_TOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_DO_TUOI_PHAM_TOI" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR

    WITH

    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                    THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE,
            FLOOR(MONTHS_BETWEEN(TRUNC(NVL(ll.THA_NGAY_BAT, ll.THA_NGAY_DEN_TRAI)),
                QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH)) / 12) AS TUOI_PHAM_TOI
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID,
            ll.TUOI_PHAM_TOI
        FROM pn_base ll
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
           AND dtg.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
           AND dqt.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_ma_trai_giam  IS NULL OR dtg.TG_MA = p_ma_trai_giam)
          -- NHOM 1: Khoang ngay
          AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
          AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
          AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
          AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
          AND (
              (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1 FROM PN_DAC_XAS dxa
                  WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                    AND dxa.IS_DELETED = 0
                    AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                    AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
              )
          )
          AND (
              (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
              OR EXISTS (
                  SELECT 1 FROM GIAM_THOI_HANS gaan
                  WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                    AND gaan.IS_DELETED   = 0
                    AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                    AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay)
              )
          )
          -- NHOM 2: Khoang so
          AND (
              p_so_tien_an_tu IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
          )
          AND (
              p_so_tien_an_den IS NULL
              OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
          )
          AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
          AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
          AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
          AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
          AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
          AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
          AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
          AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
          -- NHOM 3: Danh muc
          AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
          AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
          AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
          AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
          AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
          AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
          -- [Toi danh]
          AND (
              p_toi_danh_ids IS NULL
              OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
              OR EXISTS (SELECT 1
                         FROM selected_toi_danh_filter loc
                         WHERE INSTR(
                                     ',' || REPLACE(
                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                             ' ', '') || ',',
                                     ',' || TRIM(loc.ma_loc) || ','
                             ) > 0)
          )
          AND (p_dp_dktt_id        IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
          AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG               = p_loai_doi_tuong_id)
          -- [Ghi chu rieng]
          AND (
              p_ghi_chu_rieng_id IS NULL
              OR INSTR(
                         ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                         ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                     ) > 0
          )
          AND (p_phan_doi_id       IS NULL OR ll.LL_PHAN_DOI_ID             = p_phan_doi_id)
          -- NHOM 4: Checkbox
          -- [Nuoc ngoai]
          AND (p_nuoc_ngoai IS NULL OR (
              CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
          ))
          -- [Co benh tat]
          AND (p_co_benh_tat IS NULL OR (
              CASE
                  WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL THEN 1
                  WHEN EXISTS (
                      SELECT 1 FROM DM_BENH_TATS dbt
                      WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                        AND dbt.IS_DELETED = 0 AND dbt.BT_MA = '1'
                  ) THEN 0
                  ELSE 1
              END = p_co_benh_tat
          ))
          -- [Giam rieng]
          AND (p_giam_rieng IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PN_GIAM_RIENGS gr
                  WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_giam_rieng
          ))
          -- [Dan toc thieu so]
          AND (
              p_dan_toc_thieu_so IS NULL
              OR (
                  CASE
                      WHEN EXISTS (
                          SELECT 1 FROM DM_DAN_TOCS dt
                          WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
                            AND dt.IS_DELETED = 0
                            AND NVL(dt.DT_MA, 'NULL') NOT IN ('1', '55')
                      ) THEN 1
                      ELSE 0
                  END = p_dan_toc_thieu_so
              )
          )
          -- [VTN tai thoi diem pham toi]
          AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
              CASE
                  WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_thoi_diem_pham_toi
          ))
          -- [Pham toi moi]
          AND (p_pham_toi_moi IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_pham_toi_moi
          ))
          -- [Theo ton giao]
          AND (p_theo_ton_giao IS NULL OR (
              CASE
                  WHEN EXISTS (
                      SELECT 1 FROM DM_TON_GIAOS tg
                      WHERE tg.ID = ll.LL_DM_TON_GIAO_ID AND tg.IS_DELETED = 0
                  ) THEN 1
                  ELSE 0
              END = p_theo_ton_giao
          ))
          -- [VTN hien tai]
          AND (p_vtn_hien_tai IS NULL OR (
              CASE
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_hien_tai
          ))
          -- [Khong pham toi moi]
          AND (p_khong_pham_toi_moi IS NULL OR (
              CASE WHEN NOT EXISTS (
                  SELECT 1 FROM PHAM_TOI_MOIS ptm
                  WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_khong_pham_toi_moi
          ))
          -- [Co nghe nghiep]
          AND (
              p_co_nghe_nghiep IS NULL
              OR (
                  CASE
                      WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                           AND EXISTS (
                               SELECT 1 FROM DM_NGHE_NGHIEPS dnn
                               WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                                 AND dnn.IS_DELETED = 0
                                 AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                           )
                      THEN 1
                      ELSE 0
                  END = p_co_nghe_nghiep
              )
          )
          -- [Chung than]
          AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
          -- [Da bi ky luat]
          AND (p_da_bi_ky_luat IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KY_LUATS kl WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
              ) THEN 1 ELSE 0 END = p_da_bi_ky_luat
          ))
          -- [Co ghi chu dac biet]
          AND (p_co_ghi_chu_dac_biet IS NULL OR (
              CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                    AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                   THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
          ))
          -- [Toi pham ANQG]
          AND (p_toi_pham_anqg IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM DM_TOI_DANHS td
                  WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                    AND td.IS_DELETED = 0
                    AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
              ) THEN 1 ELSE 0 END = p_toi_pham_anqg
          ))
          -- [Da duoc khen thuong]
          AND (p_da_duoc_khen_thuong IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM KHEN_THUONGS kt
                  WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
          ))
          -- [Co tien an]
          AND (p_co_tien_an IS NULL OR (
              CASE WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0' THEN 1 ELSE 0 END = p_co_tien_an
          ))
          -- [Co tien su]
          AND (p_co_tien_su IS NULL OR (
              CASE WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0' THEN 1 ELSE 0 END = p_co_tien_su
          ))
          -- [Con theo me vao trai]
          AND (p_con_theo_me_vao_trai IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                  WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
          ))
          -- [Hinh phat bo sung la tien]
          AND (p_hp_bo_sung_la_tien IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                    ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                  WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                    AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
              ) THEN 1 ELSE 0 END = p_hp_bo_sung_la_tien
          ))
          -- [Bat buoc chua benh]
          AND (p_bat_buoc_chua_benh IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM CHUA_BENH_BAT_BUOCS cb
                  WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND cb.IS_DELETED = 0
              ) THEN 1 ELSE 0 END = p_bat_buoc_chua_benh
          ))
          -- [Hoan xong HPBS la tien]
          AND (
              p_hoan_xong_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                  ) THEN 1 ELSE 0
              END = p_hoan_xong_hpbs_la_tien)
          )
          -- [Chua hoan xong HPBS la tien]
          AND (p_chua_hoan_hpbs_la_tien IS NULL OR
              (CASE
                  WHEN EXISTS (
                      SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                      LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                        ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                      WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                        AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                      GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                      HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
                  ) THEN 1 ELSE 0
              END = p_chua_hoan_hpbs_la_tien))
    ),

    ranges AS (
        SELECT 1 ID, u'D\01b0\1edbi 18 tu\1ed5i'          ten, 0  tu, 17  den FROM dual UNION ALL
        SELECT 2,    u'T\1eeb 18 - d\01b0\1edbi 30 tu\1ed5i', 18, 29  FROM dual UNION ALL
        SELECT 3,    u'T\1eeb 30 - d\01b0\1edbi 45 tu\1ed5i', 30, 44  FROM dual UNION ALL
        SELECT 4,    u'T\1eeb 45 - d\01b0\1edbi 55 tu\1ed5i', 45, 54  FROM dual UNION ALL
        SELECT 5,    u'T\1eeb 55 - d\01b0\1edbi 60 tu\1ed5i', 55, 59  FROM dual UNION ALL
        SELECT 6,    u'T\1eeb 60 - d\01b0\1edbi 70 tu\1ed5i', 60, 69  FROM dual UNION ALL
        SELECT 7,    u'T\1eeb 70 tu\1ed5i tr\1edf l\00ean',   70, 200 FROM dual
    ),

    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY r.ID)                    AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY r.ID))) AS "TT",
            NVL(TO_NCHAR(r.ten), u'Kh\00f4ng r\00f5')           AS "DoTuoi",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam'    THEN 1 END)   AS "Nam",
            COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END)   AS "Nu",
            COUNT(CASE WHEN gt.GT_TEN IS NULL
                            OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*)                                             AS "TongSo"
        FROM pham_nhan_filtered ll
        LEFT JOIN ranges r
            ON ll.TUOI_PHAM_TOI BETWEEN r.tu AND r.den
        LEFT JOIN DM_GIOI_TINHS gt
            ON gt.ID = ll.LL_DM_GIOI_TINH_ID AND gt.IS_DELETED = 0
        GROUP BY r.ID, NVL(TO_NCHAR(r.ten), u'Kh\00f4ng r\00f5')
    )

    SELECT "TT", "DoTuoi", "Nam", "Nu", "Khac", "TongSo"
    FROM (
        SELECT SORT_ORDER, "TT", "DoTuoi", "Nam", "Nu", "Khac", "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT 999,
               TO_NCHAR(''),
               TO_NCHAR(u'T\1ed5ng s\1ed1'),
               SUM("Nam"),
               SUM("Nu"),
               SUM("Khac"),
               SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_DO_TUOI_PHAM_TOI;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_GHI_CHU_RIENG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_GHI_CHU_RIENG" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
        WITH

                 selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ), 
             pham_nhan_filtered AS ( SELECT ll.PHAM_NHAN_ID AS ID,
                                           ll.LL_GHI_CHU_RIENG,
                                           ll.LL_DM_GIOI_TINH_ID
                                    FROM pn_base ll

        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                AND dqt.IS_DELETED = 0

                                             LEFT JOIN DM_TRAI_GIAMS dtg
                                                       ON dtg.ID = ll.LL_TRAI_GIAM_ID
                                                           AND dtg.IS_DELETED = 0
-- FILTER START
                                    WHERE ll.IS_DELETED = 0
                                      AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

                                      -- NHÓM 1: Kho?ng ngày
                                      AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                      AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                      AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                      AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                                      AND (
                                        (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM PN_DAC_XAS dxa
                                                       WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                                                         AND dxa.IS_DELETED = 0
                                                         AND (p_dac_xa_tu_ngay IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                                         AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
                                        )
                                      AND (
                                        (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM GIAM_THOI_HANS gaan
                                                       WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                         AND gaan.IS_DELETED = 0
                                                         AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                                        )

                                      -- NHÓM 2: Kho?ng s?
                                      AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
                                      AND (p_muc_an_tu IS NULL OR ll.THA_MA_AN_PHAT >= p_muc_an_tu)
                                      AND (p_muc_an_den IS NULL OR ll.THA_MA_AN_PHAT <= p_muc_an_den)
                                      AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                                      AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                                      AND (p_tg_chap_hanh_tu IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                                      AND (p_tg_chap_hanh_den IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                                      AND (p_tg_con_lai_tu IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                                      AND (p_tg_con_lai_den IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                                      -- NHÓM 3: Danh m?c
                                      AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
                                      AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
                                      AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
                                      AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                                      AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
                                      AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

                                      -- [T?i danh]
                                      AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
                                      AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                                      AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG = p_loai_doi_tuong_id)

                                      -- [Ghi chú riêng]
                                      AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

                                      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                                      -- NHÓM 4: Checkbox
                                      AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
                                      AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
                                      AND (p_giam_rieng IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PN_GIAM_RIENGS gr
                                                         WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                                                           AND gr.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_giam_rieng
                                        ))
                                      AND (
									    p_dan_toc_thieu_so IS NULL
									    OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_DAN_TOCS dt
									                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
									                  AND dt.IS_DELETED = 0
									                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
									            )
									            THEN 1
									            ELSE 0
									        END = p_dan_toc_thieu_so
									    )
									)
                                      AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                                        CASE
                                            WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_thoi_diem_pham_toi
                                        ))
                                      AND (p_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PHAM_TOI_MOIS ptm
                                                         WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_pham_toi_moi
                                        ))
                                      AND (p_theo_ton_giao IS NULL OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_TON_GIAOS tg
									                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
									                  AND tg.IS_DELETED = 0
									            )
									            THEN 1
									            ELSE 0
									        END = p_theo_ton_giao ))
                                      AND (p_vtn_hien_tai IS NULL OR (
                                        CASE
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_hien_tai
                                        ))
                                      AND (p_khong_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN NOT EXISTS (SELECT 1
                                                             FROM PHAM_TOI_MOIS ptm
                                                             WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                               AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_khong_pham_toi_moi
                                        ))
                                      AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
                                      AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
                                      AND (p_da_bi_ky_luat IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KY_LUATS kl
                                                         WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID) THEN 1
                                            ELSE 0 END = p_da_bi_ky_luat
                                        ))
                                      AND (p_co_ghi_chu_dac_biet IS NULL OR (
                                        CASE
                                            WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                                                AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                                                THEN 1
                                            ELSE 0 END = p_co_ghi_chu_dac_biet
                                        ))
                                      AND (p_toi_pham_anqg IS NULL OR (
                                          CASE WHEN EXISTS (
                                              SELECT 1 FROM DM_TOI_DANHS td
                                              WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                                                AND td.IS_DELETED = 0
                                                AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                                          ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                                      ))
                                      AND (p_da_duoc_khen_thuong IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KHEN_THUONGS kt
                                                         WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND kt.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_da_duoc_khen_thuong
                                        ))
                                      AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
                                      AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
                                      AND (p_con_theo_me_vao_trai IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM THAN_NHAN_CON_CAIS tncc
                                                         WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND tncc.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_con_theo_me_vao_trai
                                        ))
                                      AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
                                      AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
                                      AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
                                      AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))),
-- FILTER DONE

-- Split ghi chú riêng (SAFE)
             split_gc AS (
					    SELECT pn.ID AS PHAM_NHAN_ID,
					           CASE
					               WHEN REGEXP_LIKE(
					                       REGEXP_SUBSTR(pn.LL_GHI_CHU_RIENG, '[^,]+', 1, LEVEL),
					                       '^\d+$'
					                    )
					                   THEN TO_NUMBER(REGEXP_SUBSTR(pn.LL_GHI_CHU_RIENG, '[^,]+', 1, LEVEL))
					               END AS GC_ID
					    FROM pham_nhan_filtered pn
					    WHERE pn.LL_GHI_CHU_RIENG IS NOT NULL
					    CONNECT BY REGEXP_SUBSTR(pn.LL_GHI_CHU_RIENG, '[^,]+', 1, LEVEL) IS NOT NULL
					           AND PRIOR pn.ID = pn.ID
					           AND PRIOR SYS_GUID() IS NOT NULL
					),

             data_full AS (
					    SELECT s.PHAM_NHAN_ID,
					           NVL(d.GCR_TEN, 'Không xác ??nh') TEN_GHI_CHU,
					           dgt.GT_TEN
					    FROM split_gc s
					             LEFT JOIN DM_GHI_CHU_RIENGS d ON d.ID = s.GC_ID
					             LEFT JOIN pham_nhan_filtered pn ON pn.ID = s.PHAM_NHAN_ID
					             LEFT JOIN DM_GIOI_TINHS dgt ON pn.LL_DM_GIOI_TINH_ID = dgt.ID
					    WHERE (
					        p_ghi_chu_rieng_id IS NULL 
					        OR s.GC_ID = p_ghi_chu_rieng_id 
					    )
					),

             flag_data AS (SELECT pn.ID AS PHAM_NHAN_ID,
                                  pn.LL_DM_GIOI_TINH_ID,
                                  CASE WHEN pn.LL_GHI_CHU_RIENG IS NOT NULL THEN 1 ELSE 0 END AS CO_GHI_CHU
                           FROM pham_nhan_filtered pn),

             base_agg AS (
					    -- Không ghi chú
					    SELECT u'Kh\00f4ng ghi ch\00fa ri\00eang' AS TEN,
					           COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN f.PHAM_NHAN_ID END) AS Nam,
					           COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'  THEN f.PHAM_NHAN_ID END) AS Nu,
					           COUNT(DISTINCT CASE
					                              WHEN dgt.GT_TEN IS NULL OR dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
					                                  THEN f.PHAM_NHAN_ID
					                 END) AS Khac
					    FROM flag_data f
					             LEFT JOIN DM_GIOI_TINHS dgt ON f.LL_DM_GIOI_TINH_ID = dgt.ID
					    WHERE CO_GHI_CHU = 0

					    UNION ALL

					    -- Có ghi chú
					    SELECT u'C\00f3 ghi ch\00fa ri\00eang',
						       COUNT( CASE WHEN df.GT_TEN = u'Nam' THEN df.PHAM_NHAN_ID END),
						       COUNT( CASE WHEN df.GT_TEN = u'N\1eef'  THEN df.PHAM_NHAN_ID END),
						       COUNT( CASE
						                          WHEN df.GT_TEN IS NULL OR df.GT_TEN NOT IN (u'Nam', u'N\1eef')
						                              THEN df.PHAM_NHAN_ID
						             END)
						FROM data_full df

					    UNION ALL

					    -- ? FIX: dùng alias df t? data_full, không dùng f/dgt
					    SELECT df.TEN_GHI_CHU,
					           COUNT( CASE WHEN df.GT_TEN = u'Nam' THEN df.PHAM_NHAN_ID END),
					           COUNT( CASE WHEN df.GT_TEN = u'N\1eef'  THEN df.PHAM_NHAN_ID END),
					           COUNT( CASE
					                              WHEN df.GT_TEN IS NULL OR df.GT_TEN NOT IN (u'Nam', u'N\1eef')
					                                  THEN df.PHAM_NHAN_ID
					                 END)
					    FROM data_full df
					    GROUP BY df.TEN_GHI_CHU
					),

             base_with_order AS (SELECT CASE
                                            WHEN TEN = u'Kh\00f4ng ghi ch\00fa ri\00eang' THEN 1
                                            WHEN TEN = u'C\00f3 ghi ch\00fa ri\00eang' THEN 2
                                            ELSE 2 + ROW_NUMBER() OVER (ORDER BY TEN) * 0.001
                                            END AS SORT_ORDER,
                                        TEN,
                                        Nam,
                                        Nu,
                                        Khac
                                 FROM base_agg),

             final_data AS (SELECT SORT_ORDER,
                                   CASE
                                       WHEN SORT_ORDER IN (1, 2) THEN u'-'
                                       ELSE u'+'
                                       END           AS "TT",
                                   TEN               AS "Ten",
                                   Nam               AS "Nam",
                                   Nu                AS "Nu",
                                   Khac              AS "Khac",
                                   (Nam + Nu + Khac) AS "TongSo"
                            FROM base_with_order)

        SELECT *
        FROM (SELECT *
              FROM final_data

              UNION ALL

              SELECT 999,
                     NULL,
                     u'T\1ed5ng c\1ed9ng',
                     SUM("Nam"),
                     SUM("Nu"),
                     SUM("Khac"),
                     SUM("TongSo")
              FROM final_data
              WHERE SORT_ORDER IN (1, 2) 
             )
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_GHI_CHU_RIENG;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_HINH_PHAT_BO_SUNG_KHAC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_HINH_PHAT_BO_SUNG_KHAC" (
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN

OPEN c1 FOR

WITH chi_tiet AS (

    SELECT
        ROW_NUMBER() OVER (ORDER BY dhpbs.ID) AS SORT_ORDER,

        TO_NCHAR(ROW_NUMBER() OVER (ORDER BY dhpbs.ID)) AS "TT",

        NVL(dhpbs.HPBS_TEN, TO_NCHAR('Ch?a xác ??nh')) AS "HPBSKhac",

        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'
            THEN ll.ID END) AS "Nam",

        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'
            THEN ll.ID END) AS "Nu",

        COUNT(DISTINCT CASE
            WHEN NVL(dgt.GT_TEN,'Khác') NOT IN ('Nam','N?')
            THEN ll.ID END) AS "Khac",

        COUNT(DISTINCT ll.ID) AS "TongSo"

    FROM PN_HINH_PHAT_BO_SUNGS phpbs

    LEFT JOIN (
        SELECT ID, LL_DM_GIOI_TINH_ID, LL_TRAI_GIAM_ID
        FROM PN_LAI_LICHS
        WHERE IS_DELETED = 0
    ) ll
        ON phpbs.HPBS_MA_PHAM_NHAN = ll.ID

    LEFT JOIN (
        SELECT THA_PNLAI_LICH_ID, THA_NGAY_DEN_TRAI
        FROM PN_THI_HANH_AN
        WHERE
              NVL(WHERE.LL_LA_BAN_DONG_BANG, 0) = 0 AND IS_DELETED = 0
    ) ptha
        ON ptha.THA_PNLAI_LICH_ID = ll.ID

    LEFT JOIN DM_GIOI_TINHS dgt
        ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        AND dgt.IS_DELETED = 0

    LEFT JOIN DM_HINH_PHAT_BO_SUNGS dhpbs
        ON phpbs.HPBS_HINH_PHAT = dhpbs.HPBS_MA
        AND dhpbs.IS_DELETED = 0

    WHERE phpbs.IS_DELETED = 0
      AND dhpbs.HPBS_MA NOT LIKE '2%'
      AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
      AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
      AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

    GROUP BY dhpbs.ID, dhpbs.HPBS_TEN
)

SELECT "TT",
        "HPBSKhac",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
FROM (

    SELECT
        SORT_ORDER,
        "TT",
        "HPBSKhac",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM chi_tiet  

    UNION ALL

    SELECT
        999,
        TO_NCHAR(NULL),          
        TO_NCHAR('T?ng s?'), 
        SUM("Nam"),
        SUM("Nu"),
        SUM("Khac"),
        SUM("TongSo")
    FROM chi_tiet

)

ORDER BY SORT_ORDER;

DBMS_SQL.RETURN_RESULT(c1);

END SP_THONG_KE_HINH_PHAT_BO_SUNG_KHAC;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_HINH_PHAT_BO_SUNG_TIEN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_HINH_PHAT_BO_SUNG_TIEN" (
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT
        "TT",
        "HinhPhatBoSung",
        "SoPN",
        "TongTienPhat",
        "ThucHienTruocKhiXu",
        "ThucHienSauKhiXu",
        "ThucHienKhiCHAPT",
        "TongThucHien",
        "NopTaiTrai",
        "ChuaThucHien"
    FROM (
        -- Chi ti?t t?ng lo?i hình ph?t b? sung
        SELECT
            ROW_NUMBER() OVER (ORDER BY dhpbs.ID) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY dhpbs.ID))) AS "TT",
            NVL(dhpbs.HPBS_TEN, TO_NCHAR('Ch?a xác ??nh')) AS "HinhPhatBoSung",
            COUNT(DISTINCT hpbs.HPBS_MA_PHAM_NHAN) AS "SoPN",
            SUM(NVL(hpbs.HPBS_TONG_TIEN_PHAT, NULL)) AS "TongTienPhat"
            ,SUM( CASE
		            WHEN pb.BL_NGAY_NOP < ptha.THA_NGAY_BAN_AN
		            THEN pb.BL_SO_TIEN
		            ELSE NULL
       			 END ) AS "ThucHienTruocKhiXu"
            ,SUM( CASE
		            WHEN ptha.THA_NGAY_BAN_AN <= pb.BL_NGAY_NOP
		             AND pb.BL_NGAY_NOP < ptha.THA_NGAY_DEN_TRAI
		            THEN pb.BL_SO_TIEN
		            ELSE NULL
		        END ) AS "ThucHienSauKhiXu"
    		,SUM(CASE
		            WHEN pb.BL_NGAY_NOP IS NULL
		              OR pb.BL_NGAY_NOP >= ptha.THA_NGAY_DEN_TRAI
		            THEN pb.BL_SO_TIEN
		            ELSE NULL
                END ) AS "ThucHienKhiCHAPT"
		    ,SUM(CASE
		            WHEN pb.BL_NGAY_NOP < ptha.THA_NGAY_BAN_AN
		              OR ( ptha.THA_NGAY_BAN_AN <= pb.BL_NGAY_NOP
		                AND pb.BL_NGAY_NOP < ptha.THA_NGAY_DEN_TRAI)
		              OR (  pb.BL_NGAY_NOP IS NULL
		                 OR pb.BL_NGAY_NOP >= ptha.THA_NGAY_DEN_TRAI)
		            THEN pb.BL_SO_TIEN
		            ELSE NULL
		        END ) AS "TongThucHien"
		    ,SUM(CASE
		            WHEN pb.BL_NOP_TAI_CO_QUAN IS NOT NULL 
		            	AND ( pb.BL_NGAY_NOP IS NULL OR pb.BL_NGAY_NOP >= ptha.THA_NGAY_DEN_TRAI)
		            THEN pb.BL_SO_TIEN
		            ELSE NULL
		        END ) AS "NopTaiTrai"
            ,SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, NULL)) AS "ChuaThucHien"
        FROM PN_HINH_PHAT_BO_SUNGS hpbs
        LEFT JOIN PN_BIENLAIES pb ON pb.HPBS_ID = hpbs.ID AND pb.IS_DELETED = 0
        LEFT JOIN (SELECT  ID, LL_DM_GIOI_TINH_ID, LL_TRAI_GIAM_ID
        		   FROM PN_LAI_LICHS
        		   WHERE IS_DELETED = 0) ll ON hpbs.HPBS_MA_PHAM_NHAN = ll.ID
		LEFT JOIN (
			  SELECT THA_PNLAI_LICH_ID, THA_NGAY_DEN_TRAI, THA_NGAY_BAN_AN
			  FROM PN_THI_HANH_AN
			  WHERE
              NVL(WHERE.LL_LA_BAN_DONG_BANG, 0) = 0 AND IS_DELETED = 0
			) ptha ON ptha.THA_PNLAI_LICH_ID = ll.ID
        LEFT JOIN DM_HINH_PHAT_BO_SUNGS dhpbs ON hpbs.HPBS_HINH_PHAT = dhpbs.HPBS_MA 
        									  AND dhpbs.IS_DELETED = 0
        WHERE hpbs.IS_DELETED = 0 
          AND dhpbs.HPBS_MA LIKE '2%'
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY dhpbs.ID, dhpbs.HPBS_TEN
     )
	ORDER BY SORT_ORDER;
    DBMS_SQL.RETURN_RESULT(c1);
END SP_THONG_KE_HINH_PHAT_BO_SUNG_TIEN;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_HOC_VAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_HOC_VAN" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
        WITH

             selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ), 
             pham_nhan_filtered AS ( SELECT ll.PHAM_NHAN_ID AS pham_nhan_id,
                                           ll.LL_DM_GIOI_TINH_ID,
                                           ll.LL_DM_HOC_VAN_ID,
                                           ll.LL_DM_NGHE_NGHIEP_ID,
                                           ll.LL_SO_TIEN_AN,
                                           ll.LL_SO_TIEN_SU,
                                           ll.LL_DM_TON_GIAO_ID,
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH,
                                           ll.THA_THOI_GIAN_CON_LAI
                                    FROM pn_base ll
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                AND dqt.IS_DELETED = 0
                                             LEFT JOIN DM_TRAI_GIAMS dtg
                                                       ON dtg.ID = ll.LL_TRAI_GIAM_ID
                                                           AND dtg.IS_DELETED = 0
-- FILTER START
                                    WHERE ll.IS_DELETED = 0
                                      AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

                                      -- NHÓM 1: Kho?ng ngày
                                      AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                      AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                      AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                      AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                                      AND (
                                        (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM PN_DAC_XAS dxa
                                                       WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                                                         AND dxa.IS_DELETED = 0
                                                         AND (p_dac_xa_tu_ngay IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                                         AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
                                        )
                                      AND (
                                        (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM GIAM_THOI_HANS gaan
                                                       WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                         AND gaan.IS_DELETED = 0
                                                         AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                                        )

                                      -- NHÓM 2: Kho?ng s?
                                      AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
                                      AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                                      AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                                      AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                                      AND (p_tg_chap_hanh_tu IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                                      AND (p_tg_chap_hanh_den IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                                      AND (p_tg_con_lai_tu IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                                      AND (p_tg_con_lai_den IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                                      -- NHÓM 3: Danh m?c
                                      AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
                                      AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
                                      AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
                                      AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                                      AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
                                      AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

                                      -- [T?i danh]
                                      AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
                                      AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                                      AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG = p_loai_doi_tuong_id)

                                      -- [Ghi chú riêng]
                                      AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

                                      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                                      -- NHÓM 4: Checkbox
                                      AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
                                      AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
                                      AND (p_giam_rieng IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PN_GIAM_RIENGS gr
                                                         WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                                                           AND gr.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_giam_rieng
                                        ))
                                      AND (
									    p_dan_toc_thieu_so IS NULL
									    OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_DAN_TOCS dt
									                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
									                  AND dt.IS_DELETED = 0
									                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
									            )
									            THEN 1
									            ELSE 0
									        END = p_dan_toc_thieu_so
									    )
									)
                                      AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                                        CASE
                                            WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_thoi_diem_pham_toi
                                        ))
                                      AND (p_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PHAM_TOI_MOIS ptm
                                                         WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_pham_toi_moi
                                        ))
                                      AND (p_theo_ton_giao IS NULL OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_TON_GIAOS tg
									                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
									                  AND tg.IS_DELETED = 0
									            )
									            THEN 1
									            ELSE 0
									        END = p_theo_ton_giao ))
                                      AND (p_vtn_hien_tai IS NULL OR (
                                        CASE
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_hien_tai
                                        ))
                                      AND (p_khong_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN NOT EXISTS (SELECT 1
                                                             FROM PHAM_TOI_MOIS ptm
                                                             WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                               AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_khong_pham_toi_moi
                                        ))
                                      AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
                                      AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
                                      AND (p_da_bi_ky_luat IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KY_LUATS kl
                                                         WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID) THEN 1
                                            ELSE 0 END = p_da_bi_ky_luat
                                        ))
                                      AND (p_co_ghi_chu_dac_biet IS NULL OR (
                                        CASE
                                            WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                                                AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                                                THEN 1
                                            ELSE 0 END = p_co_ghi_chu_dac_biet
                                        ))
                                      AND (p_toi_pham_anqg IS NULL OR (
                                    CASE WHEN EXISTS (
                                        SELECT 1 FROM DM_TOI_DANHS td
                                        WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                                          AND td.IS_DELETED = 0
                                          AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                                    ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                                ))
                                      AND (p_da_duoc_khen_thuong IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KHEN_THUONGS kt
                                                         WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND kt.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_da_duoc_khen_thuong
                                        ))
                                      AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
                                      AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
                                      AND (p_con_theo_me_vao_trai IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM THAN_NHAN_CON_CAIS tncc
                                                         WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND tncc.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_con_theo_me_vao_trai
                                        ))
                                      AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
                                      AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
                                      AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
                                      AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))),
-- FILTER DONE

            chi_tiet_raw AS (
					    SELECT
					        NVL(TO_NCHAR(dhv.HV_TEN), u'Kh\00f4ng r\00f5')           AS "HocVan",
					        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam'  THEN ll.PHAM_NHAN_ID END) AS "Nam",
					        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'   THEN ll.PHAM_NHAN_ID END) AS "Nu",
					        COUNT(DISTINCT CASE
					                           WHEN dgt.GT_TEN IS NULL OR dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
					                               THEN ll.PHAM_NHAN_ID
					              END)                                               AS "Khac",
					        COUNT(DISTINCT ll.PHAM_NHAN_ID)                         AS "TongSo"
					    FROM pham_nhan_filtered ll
					        LEFT JOIN DM_GIOI_TINHS dgt
					            ON ll.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
					        LEFT JOIN DM_HOC_VANS dhv
					            ON ll.LL_DM_HOC_VAN_ID = dhv.ID AND dhv.IS_DELETED = 0
					    GROUP BY NVL(TO_NCHAR(dhv.HV_TEN), u'Kh\00f4ng r\00f5')
					),

					chi_tiet AS (
					    SELECT
					        ROW_NUMBER() OVER (ORDER BY "TongSo" DESC, "HocVan") AS SORT_ORDER,
					        TO_NCHAR(TO_CHAR(
					            ROW_NUMBER() OVER (ORDER BY "TongSo" DESC, "HocVan")
					        ))          AS "TT",
					        "HocVan",
					        "Nam",
					        "Nu",
					        "Khac",
					        "TongSo"
					    FROM chi_tiet_raw
					)
        SELECT "TT",
               "HocVan",
               "Nam",
               "Nu",
               "Khac",
               "TongSo"
        FROM (SELECT SORT_ORDER,
                     "TT",
                     "HocVan",
                     "Nam",
                     "Nu",
                     "Khac",
                     "TongSo"
              FROM chi_tiet

              UNION ALL

              SELECT 999,
                     TO_NCHAR(''),
                     TO_NCHAR(u'T\1ed5ng s\1ed1'),
                     SUM("Nam"),
                     SUM("Nu"),
                     SUM("Khac"),
                     SUM("TongSo")
              FROM chi_tiet)
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_HOC_VAN;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_KY_GIAM_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_KY_GIAM_AN" (
    p_tu_ngay      IN DATE,
    p_den_ngay     IN DATE,
    p_trai_giam_id IN NVARCHAR2 DEFAULT NULL
) AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR

    WITH
    -- ===== K? gi?m th?i h?n trong kho?ng báo cáo =====
    ky_giam_filtered AS (
        SELECT
            k.ID,
            k.KGTH_NGAY_XET_GIAM
        FROM GTH_KY_GIAM_THOI_HANS k
        WHERE k.IS_DELETED = 0
          AND TRUNC(k.KGTH_NGAY_XET_GIAM) BETWEEN TRUNC(p_tu_ngay) AND TRUNC(p_den_ngay)
    ),

    -- ===== Ph?m nhân ???c gi?m h?p l? trong t?ng k? =====
    -- DISTINCT (KY_ID, PHAM_NHAN_ID) ?? tránh duplicate khi 1 PN có nhi?u GTH cùng k?
    pham_nhan_giam AS (
        SELECT DISTINCT
            kgth.ID                  AS KY_ID,
            ll.ID                    AS PHAM_NHAN_ID,
            ll.LL_DM_GIOI_TINH_ID
        FROM PN_LAI_LICHS ll
        JOIN DM_TRAI_GIAMS dtg
            ON  dtg.ID         = ll.LL_TRAI_GIAM_ID
            AND dtg.IS_DELETED = 0
        JOIN PN_THI_HANH_AN ptha
            ON  ptha.THA_PNLAI_LICH_ID = ll.ID
            AND ptha.IS_DELETED         = 0
        JOIN GIAM_THOI_HANS gth
            ON  gth.PHAM_NHAN_ID = ll.ID
            AND gth.IS_DELETED   = 0
            AND gth.MUC_GIAM_ID  IS NOT NULL
        JOIN DM_TINH_TRANG_PHAM_NHANS tt
            ON  tt.ID = ll.LL_TINH_TRANG_ID
        JOIN DM_MA_THOI_GIANS dmtg
            ON  dmtg.ID         = gth.MUC_GIAM_ID
            AND dmtg.IS_DELETED = 0
            AND dmtg.MTG_MA     NOT IN ('927000', '926000', '000000')
        JOIN GTH_KY_GIAM_THOI_HANS kgth
            ON  TRUNC(gth.NGAY_XET)            = TRUNC(kgth.KGTH_NGAY_XET_GIAM)
            AND kgth.IS_DELETED                 = 0
            AND TRUNC(kgth.KGTH_NGAY_XET_GIAM) BETWEEN TRUNC(p_tu_ngay) AND TRUNC(p_den_ngay)
        WHERE
            ll.IS_DELETED = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
            -- Filter tr?i giam
            AND (p_trai_giam_id IS NULL OR dtg.TG_MA = p_trai_giam_id)
            -- Ngày vào tr?i ph?i tr??c ngày cu?i báo cáo
            AND TRUNC(ptha.THA_NGAY_DEN_TRAI) < TRUNC(p_den_ngay)
            -- Còn trong tr?i: h?t h?n NULL ho?c sau ngày ??u báo cáo
            AND (ptha.THA_NGAY_HET_HAN IS NULL
                 OR TRUNC(ptha.THA_NGAY_HET_HAN) > TRUNC(p_tu_ngay))
                    -- L?c tình tr?ng
                AND tt.TTPN_TEN NOT IN (
                    u'Ch\1EBFt', u'Tha tr\01B0\1EDBc th\1EDDi h\1EA1n c\00F3 \0111i\1EC1u ki\1EC7n',
                    u'Tr\00EDch xu\1EA5t tr\1ED1n', u'Tr\00EDch xu\1EA5t h\1EE7y \00E1n',
                    u'Ho\00E3n thi h\00E0nh \00E1n', u'Tr\00EDch xu\1EA5t gi\1EA3m tha',
                    u'T\1EA1m \0111\00ECnh ch\1EC9 tr\1ED1n', u'Chuy\1EC3n giao thi h\00E0nh \00E1n',
                    u'Gi\1EA3m h\1EBFt \00E1n', u'\0110\01B0\1EE3c \0111\1EB7c x\00E1',
                    u'T\1EA1m \0111\00ECnh ch\1EC9 \0111\1EB7c x\00E1', u'Hu\1EF7 \00E1n',
                    u'T\1EA1m \0111\00ECnh ch\1EC9 chuy\1EC3n tr\1EA1i',
                    u'B\1EAFt bu\1ED9c ch\1EEFa b\1EC7nh h\1EBFt \00E1n',
                    u'Tr\1ED1n tr\1EA1i truy n\00E3', u'T\1EA1m \0111\00ECnh ch\1EC9 \0111\01B0\1EE3c mi\1EC5n',
                    u'T\1EA1m \0111\00ECnh ch\1EC9 ch\1EBFt', u'Tr\00EDch xu\1EA5t h\1EBFt \00E1n',
                    u'Tr\1ED1n tr\1EA1i', u'Chuy\1EC3n tr\1EA1i kh\00E1c', u'Tr\1ED1n tr\1EA1i ch\1EBFt',
                    u'Tr\00EDch xu\1EA5t ch\1EBFt', u'K\1EBFt th\00FAc h\1ED3 s\01A1',
                    u'Tr\00EDch xu\1EA5t chuy\1EC3n tr\1EA1i',
                    u'Ch\1EA5p h\00E0nh xong h\00ECnh ph\1EA1t t\00F9',
                    u'Tr\00EDch xu\1EA5t \0111\1EB7c x\00E1', u'Mi\1EC5n h\00ECnh ph\1EA1t'
                )
    ),

    -- ===== Th?ng kê theo k? =====
    -- Drive t? ky_giam_filtered (LEFT JOIN) ?? luôn có ?? các k? dù 0 ph?m nhân
    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY k.KGTH_NGAY_XET_GIAM)             AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(
                ROW_NUMBER() OVER (ORDER BY k.KGTH_NGAY_XET_GIAM)
            ))                                                              AS "TT",
            TO_NCHAR(TO_CHAR(TRUNC(k.KGTH_NGAY_XET_GIAM), 'DD/MM/YYYY')) AS "NGAY_XET_GIAM",

            COUNT(DISTINCT CASE
                WHEN dgt.GT_TEN = u'Nam'
                THEN p.PHAM_NHAN_ID
            END)                                                            AS "Nam",

            COUNT(DISTINCT CASE
                WHEN dgt.GT_TEN = u'N\1EEF'
                THEN p.PHAM_NHAN_ID
            END)                                                            AS "Nu",

            COUNT(DISTINCT CASE
                WHEN NVL(dgt.GT_TEN, u'Kh\00E1c') NOT IN (u'Nam', u'N\1EEF')
                THEN p.PHAM_NHAN_ID
            END)                                                            AS "Khac",

            COUNT(DISTINCT p.PHAM_NHAN_ID)                                 AS "TongSo"

        FROM ky_giam_filtered k
        LEFT JOIN pham_nhan_giam p
            ON p.KY_ID = k.ID
        LEFT JOIN DM_GIOI_TINHS dgt
            ON  dgt.ID         = p.LL_DM_GIOI_TINH_ID
            AND dgt.IS_DELETED = 0
        GROUP BY k.ID, k.KGTH_NGAY_XET_GIAM
    )

    -- ===== Output: chi ti?t + t?ng =====
    SELECT "TT", "NGAY_XET_GIAM", "Nam", "Nu", "Khac", "TongSo"
    FROM (
        SELECT SORT_ORDER, "TT", "NGAY_XET_GIAM", "Nam", "Nu", "Khac", "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(''),
            TO_NCHAR(u'T\1ED5ng s\1ED1'),
            NVL(SUM("Nam"),    0),
            NVL(SUM("Nu"),     0),
            NVL(SUM("Khac"),   0),
            NVL(SUM("TongSo"), 0)
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

EXCEPTION
    WHEN OTHERS THEN
        IF C1%ISOPEN THEN
            CLOSE C1;
        END IF;
        RAISE;

END SP_THONG_KE_KY_GIAM_AN;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_MUC_AN_PHAT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_MUC_AN_PHAT" (
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
        WITH
             selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ),
             pham_nhan_filtered AS ( SELECT ll.PHAM_NHAN_ID,
                                           ll.LL_DM_GIOI_TINH_ID,
                                           ll.THA_MUC_AN_ID
                                	 FROM pn_base ll
	                                 LEFT JOIN DM_TRAI_GIAMS dtg
	                                           ON dtg.ID = ll.LL_TRAI_GIAM_ID
	                                               AND dtg.IS_DELETED = 0
	                                 LEFT JOIN DM_QUOC_TICHS dqt
	                                           ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
	                                               AND dqt.IS_DELETED = 0
                                    WHERE ll.IS_DELETED = 0
                                      AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)
                                      -- NHÓM 1: Kho?ng ngày
                                      AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                      AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                      AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                      AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                                      AND (
				    (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
				    OR EXISTS (
				        SELECT 1
				        FROM PN_DAC_XAS dxa
				        WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
				          AND dxa.IS_DELETED = 0
				          AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
				          AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay)
				    )
				)
                                      AND (
                                        (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM GIAM_THOI_HANS gaan
                                                       WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                         AND gaan.IS_DELETED = 0
                                                         AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                                        )

                                      -- NHÓM 2: Kho?ng s?
                                      AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
                                      AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                                      AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                                      AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                                      AND (p_tg_chap_hanh_tu IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                                      AND (p_tg_chap_hanh_den IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                                      AND (p_tg_con_lai_tu IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                                      AND (p_tg_con_lai_den IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                                      -- NHÓM 3: Danh m?c
                                      AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
                                      AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
                                      AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
                                      AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                                      AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
                                      AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

                                      -- [T?i danh]
                                      AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
                                      AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                                      AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG = p_loai_doi_tuong_id)

                                      -- [Ghi chú riêng]
                                      AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

                                      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                                      -- NHÓM 4: Checkbox
                                      AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
                                      AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
                                      AND (p_giam_rieng IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PN_GIAM_RIENGS gr
                                                         WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                                                           AND gr.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_giam_rieng
                                        ))
                                      AND (
								    p_dan_toc_thieu_so IS NULL
								    OR (
								        CASE
								            WHEN EXISTS (
								                SELECT 1
								                FROM DM_DAN_TOCS dt
								                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
								                  AND dt.IS_DELETED = 0
								                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
								            )
								            THEN 1
								            ELSE 0
								        END = p_dan_toc_thieu_so
								    )
								)
                                      AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                                        CASE
                                            WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_thoi_diem_pham_toi
                                        ))
                                      AND (p_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PHAM_TOI_MOIS ptm
                                                         WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_pham_toi_moi
                                        ))
                                      AND (p_theo_ton_giao IS NULL OR (
								        CASE
								            WHEN EXISTS (
								                SELECT 1
								                FROM DM_TON_GIAOS tg
								                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
								                  AND tg.IS_DELETED = 0
								            )
								            THEN 1
								            ELSE 0
								        END = p_theo_ton_giao ))
                                      AND (p_vtn_hien_tai IS NULL OR (
                                        CASE
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_hien_tai
                                        ))
                                      AND (p_khong_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN NOT EXISTS (SELECT 1
                                                             FROM PHAM_TOI_MOIS ptm
                                                             WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                               AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_khong_pham_toi_moi
                                        ))
                                      AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
                                      AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
                                      AND (p_da_bi_ky_luat IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KY_LUATS kl
                                                         WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID) THEN 1
                                            ELSE 0 END = p_da_bi_ky_luat
                                        ))
                                      AND (p_co_ghi_chu_dac_biet IS NULL OR (
                                        CASE
                                            WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                                                AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                                                THEN 1
                                            ELSE 0 END = p_co_ghi_chu_dac_biet
                                        ))
                                      AND (p_toi_pham_anqg IS NULL OR (
                                          CASE WHEN EXISTS (
                                              SELECT 1 FROM DM_TOI_DANHS td
                                              WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                                                AND td.IS_DELETED = 0
                                                AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                                          ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                                      ))
                                      AND (p_da_duoc_khen_thuong IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KHEN_THUONGS kt
                                                         WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND kt.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_da_duoc_khen_thuong
                                        ))
                                      AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
                                      AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
                                      AND (p_con_theo_me_vao_trai IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM THAN_NHAN_CON_CAIS tncc
                                                         WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND tncc.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_con_theo_me_vao_trai
                                        ))
                                      AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
                                      AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
                                      AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
	                  AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))),
             chi_tiet AS (SELECT ROW_NUMBER() OVER (
                 ORDER BY
                     CASE
                         WHEN damu.MA_TEN_CHI_TIEU IS NOT NULL
                             THEN damu.MA_TEN_CHI_TIEU
                         ELSE u'Kh\00f4ng x\00e1c \0111\1ecbnh'
                         END
                 )                                                                                         AS SORT_ORDER,
                                 TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY
                                     CASE
                                         WHEN damu.MA_TEN_CHI_TIEU IS NOT NULL
                                             THEN damu.MA_TEN_CHI_TIEU
                                         ELSE u'Kh\00f4ng x\00e1c \0111\1ecbnh'
                                         END
                                     )))                                                                   AS "TT",
                                 CASE
                                     WHEN damu.MA_TEN_CHI_TIEU IS NOT NULL
                                         THEN damu.MA_TEN_CHI_TIEU
                                     ELSE u'Kh\00f4ng x\00e1c \0111\1ecbnh'
                                     END                                                                   AS "MucAn",
                                 COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN ll.PHAM_NHAN_ID END)    AS "Nam",
                                 COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN ll.PHAM_NHAN_ID END) AS "Nu",
                                 COUNT(DISTINCT CASE
                                                    WHEN dgt.GT_TEN IS NULL OR dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                        THEN ll.PHAM_NHAN_ID
                                     END)                                                                  AS "Khac",
                                 COUNT(DISTINCT ll.PHAM_NHAN_ID)                                           AS "TongSo"
                          FROM pham_nhan_filtered ll
                                   LEFT JOIN DM_MUC_ANS damu ON
                              damu.ID = ll.THA_MUC_AN_ID
                                   LEFT JOIN DM_GIOI_TINHS dgt
                                             ON
                                                 ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                                     AND dgt.IS_DELETED = 0
                          GROUP BY damu.MA_TEN_CHI_TIEU
                          ORDER BY "TongSo" DESC,
                                   "MucAn")

        SELECT "TT",
               "MucAn",
               "Nam",
               "Nu",
               "Khac",
               "TongSo"
        FROM (SELECT SORT_ORDER,
                     "TT",
                     "MucAn",
                     "Nam",
                     "Nu",
                     "Khac",
                     "TongSo"
              FROM chi_tiet
              UNION ALL
              SELECT 999,
                     TO_NCHAR(''),
                     TO_NCHAR(u'T\1ed5ng s\1ed1'),
                     SUM("Nam"),
                     SUM("Nu"),
                     SUM("Khac"),
                     SUM("TongSo")
              FROM chi_tiet)
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_THONG_KE_MUC_AN_PHAT;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_NGHE_NGHIEP
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_NGHE_NGHIEP" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
        WITH

             selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ), 
             pham_nhan_filtered AS ( SELECT ll.PHAM_NHAN_ID AS pham_nhan_id,
                                           ll.LL_DM_GIOI_TINH_ID,
                                           ll.LL_DM_HOC_VAN_ID,
                                           ll.LL_DM_NGHE_NGHIEP_ID,
                                           ll.LL_SO_TIEN_AN,
                                           ll.LL_SO_TIEN_SU,
                                           ll.LL_DM_TON_GIAO_ID,
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH,
                                           ll.THA_THOI_GIAN_CON_LAI
                                    FROM pn_base ll
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                AND dqt.IS_DELETED = 0
                                             LEFT JOIN DM_TRAI_GIAMS dtg
                                                       ON dtg.ID = ll.LL_TRAI_GIAM_ID
                                                           AND dtg.IS_DELETED = 0
-- FILTER START
                                    WHERE ll.IS_DELETED = 0
                                      AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

                                      -- NHÓM 1: Kho?ng ngày
                                      AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                      AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                      AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                      AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                                      AND (
                                        (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM PN_DAC_XAS dxa
                                                       WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                                                         AND dxa.IS_DELETED = 0
                                                         AND (p_dac_xa_tu_ngay IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                                         AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
                                        )
                                      AND (
                                        (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM GIAM_THOI_HANS gaan
                                                       WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                         AND gaan.IS_DELETED = 0
                                                         AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                                        )

                                      -- NHÓM 2: Kho?ng s?
                                      AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
                                      AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                                      AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                                      AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                                      AND (p_tg_chap_hanh_tu IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                                      AND (p_tg_chap_hanh_den IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                                      AND (p_tg_con_lai_tu IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                                      AND (p_tg_con_lai_den IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                                      -- NHÓM 3: Danh m?c
                                      AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
                                      AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
                                      AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
                                      AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                                      AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
                                      AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

                                      -- [T?i danh]
                                      AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
                                      AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                                      AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG = p_loai_doi_tuong_id)

                                      -- [Ghi chú riêng]
                                      AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

                                      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                                      -- NHÓM 4: Checkbox
                                      AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
                                      AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
                                      AND (p_giam_rieng IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PN_GIAM_RIENGS gr
                                                         WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                                                           AND gr.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_giam_rieng
                                        ))
                                      AND (
									    p_dan_toc_thieu_so IS NULL
									    OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_DAN_TOCS dt
									                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
									                  AND dt.IS_DELETED = 0
									                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
									            )
									            THEN 1
									            ELSE 0
									        END = p_dan_toc_thieu_so
									    )
									)
                                      AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                                        CASE
                                            WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_thoi_diem_pham_toi
                                        ))
                                      AND (p_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PHAM_TOI_MOIS ptm
                                                         WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_pham_toi_moi
                                        ))
                                      AND (p_theo_ton_giao IS NULL OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_TON_GIAOS tg
									                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
									                  AND tg.IS_DELETED = 0
									            )
									            THEN 1
									            ELSE 0
									        END = p_theo_ton_giao ))
                                      AND (p_vtn_hien_tai IS NULL OR (
                                        CASE
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_hien_tai
                                        ))
                                      AND (p_khong_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN NOT EXISTS (SELECT 1
                                                             FROM PHAM_TOI_MOIS ptm
                                                             WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                               AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_khong_pham_toi_moi
                                        ))
                                      AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
                                      AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
                                      AND (p_da_bi_ky_luat IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KY_LUATS kl
                                                         WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID) THEN 1
                                            ELSE 0 END = p_da_bi_ky_luat
                                        ))
                                      AND (p_co_ghi_chu_dac_biet IS NULL OR (
                                        CASE
                                            WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                                                AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                                                THEN 1
                                            ELSE 0 END = p_co_ghi_chu_dac_biet
                                        ))
                                      AND (p_toi_pham_anqg IS NULL OR (
                                    CASE WHEN EXISTS (
                                        SELECT 1 FROM DM_TOI_DANHS td
                                        WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                                          AND td.IS_DELETED = 0
                                          AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                                    ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                                ))
                                      AND (p_da_duoc_khen_thuong IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KHEN_THUONGS kt
                                                         WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND kt.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_da_duoc_khen_thuong
                                        ))
                                      AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
                                      AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
                                      AND (p_con_theo_me_vao_trai IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM THAN_NHAN_CON_CAIS tncc
                                                         WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND tncc.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_con_theo_me_vao_trai
                                        ))
                                      AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
                                      AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
                                      AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
                                      AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))),
-- FILTER DONE

             chi_tiet_raw AS (
				    SELECT
				        NVL(TO_NCHAR(dnn.NN_TEN), u'Kh\00f4ng r\00f5')                                     AS "NgheNghiep",
				        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN ll.PHAM_NHAN_ID END)      AS "Nam",
				        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'  THEN ll.PHAM_NHAN_ID END)      AS "Nu",
				        COUNT(DISTINCT CASE
				                           WHEN dgt.GT_TEN IS NULL OR dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
				                               THEN ll.PHAM_NHAN_ID
				              END)                                                                   AS "Khac",
				        COUNT(DISTINCT ll.PHAM_NHAN_ID)                                              AS "TongSo"
				    FROM pham_nhan_filtered ll
				        LEFT JOIN DM_GIOI_TINHS dgt
				            ON ll.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
				        LEFT JOIN DM_NGHE_NGHIEPS dnn
				            ON ll.LL_DM_NGHE_NGHIEP_ID = dnn.ID AND dnn.IS_DELETED = 0
				    GROUP BY NVL(TO_NCHAR(dnn.NN_TEN), u'Kh\00f4ng r\00f5')
				),

				chi_tiet AS (
				    SELECT
				        ROW_NUMBER() OVER (ORDER BY "NgheNghiep")           AS SORT_ORDER,
				        TO_NCHAR(TO_CHAR(
				            ROW_NUMBER() OVER (ORDER BY "NgheNghiep")
				        ))                                                   AS "TT",
				        "NgheNghiep",
				        "Nam",
				        "Nu",
				        "Khac",
				        "TongSo"
				    FROM chi_tiet_raw
				)
        SELECT "TT",
               "NgheNghiep",
               "Nam",
               "Nu",
               "Khac",
               "TongSo"
        FROM (SELECT SORT_ORDER,
                     "TT",
                     "NgheNghiep",
                     "Nam",
                     "Nu",
                     "Khac",
                     "TongSo"
              FROM chi_tiet

              UNION ALL

              SELECT 999,
                     TO_NCHAR(''),
                     TO_NCHAR(u'T\1ed5ng s\1ed1'),
                     SUM("Nam"),
                     SUM("Nu"),
                     SUM("Khac"),
                     SUM("TongSo")
              FROM chi_tiet)
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_NGHE_NGHIEP;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_NOI_CU_TRU
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_NOI_CU_TRU" (
    p_trai_giam_id IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1          SYS_REFCURSOR;
    v_ngay_tinh DATE := NVL(p_so_lieu_tinh_den_ngay, SYSDATE);
BEGIN
    OPEN C1 FOR
        WITH

    td_split AS (
                    SELECT ptha.THA_PNLAI_LICH_ID,
                           TO_NUMBER(TRIM(
                               REGEXP_SUBSTR(
                                   REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
                                   '[^,]+', 1, 1   -- Luôn l?y ph?n t? ??u tiên
                               )
                           )) AS TOI_DANH_ID,
                           ptha.THA_MUC_AN_ID
                    FROM QLPN.PN_THI_HANH_AN ptha
                    WHERE ptha.IS_DELETED = 0
                      AND ptha.THA_TOI_DANH IS NOT NULL
                ),
             split_toi_danh AS (
                    SELECT td.THA_PNLAI_LICH_ID,
                           td.TOI_DANH_ID,
                           TO_NCHAR(DTD.TD_CHUONG) AS TOI_DANH_CHUONG,
                           TO_NCHAR(DTD.TD_TEN)    AS TOI_DANH
                    FROM td_split td
                    LEFT JOIN DM_TOI_DANHS DTD
                        ON  DTD.ID = td.TOI_DANH_ID
                        AND DTD.TD_CHUONG IS NOT NULL
                ),
             selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM
                    FROM PN_LAI_LICHS ll
                    WHERE ll.IS_DELETED = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
                ), 
             pham_nhan_filtered AS (
						    SELECT
						        ll.ID AS pham_nhan_id,
						        ll.LL_DM_GIOI_TINH_ID,
						        ll.LL_DM_QUOC_TICH_ID,
						        ll.LL_NOI_THA_VE_CU_TRU_PROVICE,
						        ll.CREATION_TIME,
						        dqt.QT_MA                          -- ? thêm dòng này
						    FROM pn_base ll
						        INNER JOIN PN_THI_HANH_AN ptha
						            ON ptha.THA_PNLAI_LICH_ID = ll.ID AND ptha.IS_DELETED = 0
						        LEFT JOIN DM_QUOC_TICHS dqt
						            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID AND dqt.IS_DELETED = 0
--						        LEFT JOIN PN_DAC_XAS dxa
--						            ON dxa.PNLAI_LICH_ID = ll.ID AND dxa.IS_DELETED = 0
--						        LEFT JOIN GIAM_THOI_HANS gaan
--						            ON gaan.PHAM_NHAN_ID = ll.ID AND gaan.IS_DELETED = 0
						        LEFT JOIN DM_TRAI_GIAMS dtg
						            ON dtg.ID = ll.LL_TRAI_GIAM_ID AND dtg.IS_DELETED = 0
-- FILTER START
                                   WHERE ll.IS_DELETED = 0
                                     AND (p_trai_giam_id IS NULL OR dtg.TG_MA = p_trai_giam_id)

                                     -- NHÓM 1: Kho?ng ngày
                                     AND (p_den_trai_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                     AND (p_den_trai_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                     AND (p_ra_trai_tu_ngay IS NULL OR ptha.THA_NGAY_HET_HAN >= p_ra_trai_tu_ngay)
                                     AND (p_ra_trai_den_ngay IS NULL OR ptha.THA_NGAY_HET_HAN <= p_ra_trai_den_ngay)
                                     AND (
                                       (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                                           OR EXISTS (SELECT 1
                                                      FROM PN_DAC_XAS dxa
                                                      WHERE dxa.PNLAI_LICH_ID = ll.ID
                                                        AND dxa.IS_DELETED = 0
                                                        AND (p_dac_xa_tu_ngay IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                                        AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
                                       )
                                     AND (
                                       (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                                           OR EXISTS (SELECT 1
                                                      FROM GIAM_THOI_HANS gaan
                                                      WHERE gaan.PHAM_NHAN_ID = ll.ID
                                                        AND gaan.IS_DELETED = 0
                                                        AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                                        AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                                       )

                                     -- NHÓM 2: Kho?ng s?
                                     AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
                                     AND (p_muc_an_tu IS NULL OR TO_NUMBER(ptha.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ptha.THA_MA_AN_PHAT) <= p_muc_an_den)
                                     AND (p_tuoi_tu IS NULL OR
                                            FLOOR(
                                                MONTHS_BETWEEN(
                                                    TRUNC(v_ngay_tinh),
                                                    CASE
                                                        WHEN ll.LL_NGAY_SINH IS NULL THEN NULL
                                                        -- D?ng ??y ??: DD/MM/YYYY
                                                        WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{2}/\d{4}$')
                                                            THEN TO_DATE(ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                        -- D?ng tháng n?m: MM/YYYY ? l?y ngày 01
                                                        WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{4}$')
                                                            THEN TO_DATE('01/' || ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                        -- D?ng ch? n?m: YYYY ? l?y ngày 01/01
                                                        WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{4}$')
                                                            THEN TO_DATE('01/01/' || ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                        ELSE NULL
                                                    END
                                                ) / 12
                                            ) >= p_tuoi_tu
                                        )
                                        AND (p_tuoi_den IS NULL OR
                                                FLOOR(
                                                    MONTHS_BETWEEN(
                                                        TRUNC(v_ngay_tinh),
                                                        CASE
                                                            WHEN ll.LL_NGAY_SINH IS NULL THEN NULL
                                                            -- D?ng ??y ??: DD/MM/YYYY
                                                            WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{2}/\d{4}$')
                                                                THEN TO_DATE(ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                            -- D?ng tháng n?m: MM/YYYY ? l?y ngày 01
                                                            WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{4}$')
                                                                THEN TO_DATE('01/' || ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                            -- D?ng ch? n?m: YYYY ? l?y ngày 01/01
                                                            WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{4}$')
                                                                THEN TO_DATE('01/01/' || ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                            ELSE NULL
                                                        END
                                                    ) / 12
                                                ) <= p_tuoi_den
                                            )
                                     AND (p_tg_chap_hanh_tu IS NULL OR
                                          ptha.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                                     AND (p_tg_chap_hanh_den IS NULL OR
                                          ptha.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                                     AND (p_tg_con_lai_tu IS NULL OR
                                          ptha.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                                     AND (p_tg_con_lai_den IS NULL OR
                                          ptha.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                                     -- NHÓM 3: Danh m?c
                                     AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
                                     AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
                                     AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
                                     AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                                     AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
                                     AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

                                     -- [T?i danh]
                                     AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
                                     AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                                     AND (p_loai_doi_tuong_id IS NULL OR ptha.THA_DOI_TUONG = p_loai_doi_tuong_id)

                                     -- [Ghi chú riêng]
                                     AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

                                     AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                                     -- NHÓM 4: Checkbox
                                     AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
                                     AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
                                     AND (p_giam_rieng IS NULL OR (
                                       CASE
                                           WHEN EXISTS (SELECT 1
                                                        FROM PN_GIAM_RIENGS gr
                                                        WHERE gr.GR_PN_LAI_LICH_ID = ll.ID
                                                          AND gr.IS_DELETED = 0) THEN 1
                                           ELSE 0 END = p_giam_rieng
                                       ))
                                     AND (
									    p_dan_toc_thieu_so IS NULL
									    OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_DAN_TOCS dt
									                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
									                  AND dt.IS_DELETED = 0
									                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('1100', '6500')
									            )
									            THEN 1
									            ELSE 0
									        END = p_dan_toc_thieu_so
									    )
									)
                                     AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                                       CASE
                                           WHEN ptha.THA_NGAY_PHAM_TOI IS NULL THEN 0
                                           WHEN ll.LL_NGAY_SINH IS NULL THEN 0
                                           -- D?ng ??y ??: DD/MM/YYYY
                                           WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{2}/\d{4}$')
                                               AND FLOOR(MONTHS_BETWEEN(
                                                                 TRUNC(ptha.THA_NGAY_PHAM_TOI),
                                                                 TO_DATE(ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                         ) / 12) < 18 THEN 1
                                           -- D?ng tháng n?m: MM/YYYY ? l?y ngày 01 c?a tháng ?ó
                                           WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{4}$')
                                               AND FLOOR(MONTHS_BETWEEN(
                                                                 TRUNC(ptha.THA_NGAY_PHAM_TOI),
                                                                 TO_DATE('01/' || ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                         ) / 12) < 18 THEN 1
                                           -- D?ng ch? n?m: YYYY ? l?y ngày 01/01 c?a n?m ?ó
                                           WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{4}$')
                                               AND (EXTRACT(YEAR FROM TRUNC(ptha.THA_NGAY_PHAM_TOI))
                                                   - TO_NUMBER(ll.LL_NGAY_SINH)) < 18 THEN 1

                                           ELSE 0
                                           END = p_vtn_thoi_diem_pham_toi
                                       ))
                                     AND (p_pham_toi_moi IS NULL OR (
                                       CASE
                                           WHEN EXISTS (SELECT 1
                                                        FROM PHAM_TOI_MOIS ptm
                                                        WHERE ptm.PHAM_NHAN_ID = ll.ID
                                                          AND ptm.IS_DELETED = 0) THEN 1
                                           ELSE 0 END = p_pham_toi_moi
                                       ))
                                     AND (p_theo_ton_giao IS NULL OR (
									        CASE
									            WHEN EXISTS (
									                SELECT 1
									                FROM DM_TON_GIAOS tg
									                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
									                  AND tg.IS_DELETED = 0
									                  AND tg.TG_MA <>'8'
									            )
									            THEN 1
									            ELSE 0
									        END = p_theo_ton_giao ))
                                     AND (p_vtn_hien_tai IS NULL OR (
                                       CASE
                                           WHEN ll.LL_NGAY_SINH IS NULL THEN 0
                                           -- D?ng ??y ??: DD/MM/YYYY
                                           WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{2}/\d{4}$')
                                               AND FLOOR(MONTHS_BETWEEN(
                                                                 TRUNC(v_ngay_tinh),
                                                                 TO_DATE(ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                         ) / 12) < 18 THEN 1
                                           -- D?ng tháng n?m: MM/YYYY
                                           WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{2}/\d{4}$')
                                               AND FLOOR(MONTHS_BETWEEN(
                                                                 TRUNC(v_ngay_tinh),
                                                                 TO_DATE('01/' || ll.LL_NGAY_SINH, 'DD/MM/YYYY')
                                                         ) / 12) < 18 THEN 1
                                           -- D?ng ch? n?m: YYYY
                                           WHEN REGEXP_LIKE(ll.LL_NGAY_SINH, '^\d{4}$')
                                               AND (EXTRACT(YEAR FROM TRUNC(v_ngay_tinh))
                                                   - TO_NUMBER(ll.LL_NGAY_SINH)) < 18 THEN 1
                                           ELSE 0
                                           END = p_vtn_hien_tai
                                       ))
                                     AND (p_khong_pham_toi_moi IS NULL OR (
                                       CASE
                                           WHEN NOT EXISTS (SELECT 1
                                                            FROM PHAM_TOI_MOIS ptm
                                                            WHERE ptm.PHAM_NHAN_ID = ll.ID
                                                              AND ptm.IS_DELETED = 0) THEN 1
                                           ELSE 0 END = p_khong_pham_toi_moi
                                       ))
                                     AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
                                     AND (p_chung_than IS NULL OR (
    CASE
        WHEN ptha.THA_MA_AN_PHAT IN (
            SELECT dmtg.ID
            FROM DM_MA_THOI_GIANS dmtg
            WHERE dmtg.MTG_MA IN ('911000', '912000')
              AND dmtg.IS_DELETED = 0
        ) THEN 1
        ELSE 0
    END = p_chung_than
))
                                     AND (p_da_bi_ky_luat IS NULL OR (
                                       CASE
                                           WHEN EXISTS (SELECT 1
                                                        FROM KY_LUATS kl
                                                        WHERE kl.PHAM_NHAN_ID = ll.ID) THEN 1
                                           ELSE 0 END = p_da_bi_ky_luat
                                       ))
                                     AND (p_co_ghi_chu_dac_biet IS NULL OR (
                                       CASE
                                           WHEN ptha.THA_GHI_CHU_DAC_BIET IS NOT NULL
                                               AND ptha.THA_GHI_CHU_DAC_BIET <> '[]'
                                               THEN 1
                                           ELSE 0 END = p_co_ghi_chu_dac_biet
                                       ))
                                     AND (p_toi_pham_anqg IS NULL OR (
					                       CASE
					                           WHEN EXISTS (
					                               SELECT 1
					                               FROM PN_THI_HANH_AN ptha2
					                               JOIN DM_TOI_DANHS td
					                                   ON td.ID = TO_NUMBER(TRIM(
					                                                  REGEXP_SUBSTR(
					                                                      REPLACE(REPLACE(ptha2.THA_TOI_DANH, '[', ''), ']', ''),
					                                                      '[^,]+', 1, 1  -- Ch? l?y t?i danh ??u tiên
					                                                  )
					                                              ))
					                                   AND td.IS_DELETED = 0
					                                   AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'  -- Thu?c ch??ng 13
					                               WHERE ptha2.THA_PNLAI_LICH_ID = ll.ID
					                                 AND ptha2.IS_DELETED = 0
					                                 AND ptha2.THA_TOI_DANH IS NOT NULL
					                                 AND LENGTH(REPLACE(REPLACE(REPLACE(ptha2.THA_TOI_DANH, '[', ''), ']', ''), ' ', '')) > 0
					                           ) THEN 1
					                           ELSE 0
					                       END = p_toi_pham_anqg
					                   ))
                                     AND (p_da_duoc_khen_thuong IS NULL OR (
                                       CASE
                                           WHEN EXISTS (SELECT 1
                                                        FROM KHEN_THUONGS kt
                                                        WHERE kt.PHAM_NHAN_ID = ll.ID
                                                          AND kt.IS_DELETED = 0) THEN 1
                                           ELSE 0 END = p_da_duoc_khen_thuong
                                       ))
                                     AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
                                      AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
                                     AND (p_con_theo_me_vao_trai IS NULL OR (
                                       CASE
                                           WHEN EXISTS (SELECT 1
                                                        FROM THAN_NHAN_CON_CAIS tncc
                                                        WHERE tncc.PHAM_NHAN_ID = ll.ID
                                                          AND tncc.IS_DELETED = 0) THEN 1
                                           ELSE 0 END = p_con_theo_me_vao_trai
                                       ))
                                     AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
                                     AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
                                     AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
                                     AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))),
-- FILTER DONE
            -- =========================
            -- BASE
            -- =========================
            base AS (
				    SELECT
				        ll.pham_nhan_id,
				        dgt.GT_TEN,
				        dvtt.TTP_TEN AS TEN_TINH,
				        CASE
				            WHEN NVL(ll.QT_MA, '250') = '250' THEN 'VN'
				            ELSE 'NN'
				        END          AS LOAI
				    FROM pham_nhan_filtered ll
				        LEFT JOIN DM_GIOI_TINHS dgt
				            ON ll.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
				        LEFT JOIN DM_TINH_THANH_PHO dvtt
				            ON dvtt.ID = ll.LL_NOI_THA_VE_CU_TRU_PROVICE AND dvtt.IS_DELETED = 0
				    WHERE (v_ngay_tinh IS NULL OR TRUNC(ll.CREATION_TIME) < TRUNC(v_ngay_tinh) + 1)
				),
			            -- =========================
            -- RANK CHA
            -- =========================
            loai_rank AS (SELECT DISTINCT LOAI,
                                          DENSE_RANK() OVER (
                                              ORDER BY LOAI) STT
                          FROM base),
            -- =========================
            -- T?NG THEO LO?I (CHA)
            -- =========================
            tong_loai AS (
                SELECT lr.STT                                                                          AS SORT_ORDER,
                       TO_NCHAR('-')                                                                   AS "TT",
                       CASE
                           WHEN lr.LOAI = 'VN' THEN u'V? c? trú t?i Vi?t Nam'
                           ELSE u'V? c? trú n??c ngoài'
                           END                                                                         AS "NoiCuTru",
                       COUNT(DISTINCT CASE WHEN b.GT_TEN = u'Nam' THEN b.PHAM_NHAN_ID END)            AS "Nam",
                       COUNT(DISTINCT CASE WHEN b.GT_TEN = u'N?'  THEN b.PHAM_NHAN_ID END)            AS "Nu",
                       COUNT(DISTINCT CASE
                                WHEN b.GT_TEN IS NULL OR b.GT_TEN NOT IN (u'Nam', u'N?')
                                    THEN b.PHAM_NHAN_ID
                             END)                                                                      AS "Khac",
                       COUNT(DISTINCT b.PHAM_NHAN_ID)                                                 AS "TongSo"
                FROM base b
                         JOIN loai_rank lr ON lr.LOAI = b.LOAI
                GROUP BY lr.STT, lr.LOAI
            ),

            -- =========================
            -- CHI TI?T T?NH (CON, CH? VN)
            -- =========================
            chi_tiet_tinh_raw AS (
    SELECT
        lr.STT,
        lr.LOAI,
        NVL(b.TEN_TINH, 'Không rõ')                                                AS TEN_TINH,
        COUNT(DISTINCT CASE WHEN b.GT_TEN = u'Nam' THEN b.PHAM_NHAN_ID END)        AS "Nam",
        COUNT(DISTINCT CASE WHEN b.GT_TEN = u'N?'  THEN b.PHAM_NHAN_ID END)        AS "Nu",
        COUNT(DISTINCT CASE
                 WHEN b.GT_TEN IS NULL OR b.GT_TEN NOT IN (u'Nam', u'N?')
                     THEN b.PHAM_NHAN_ID
              END)                                                                  AS "Khac",
        COUNT(DISTINCT b.PHAM_NHAN_ID)                                             AS "TongSo"
    FROM base b
        JOIN loai_rank lr ON lr.LOAI = b.LOAI
    WHERE lr.LOAI = 'VN'
    GROUP BY lr.STT, lr.LOAI, NVL(b.TEN_TINH, 'Không rõ')
),

chi_tiet_tinh AS (
    SELECT
        STT + ROW_NUMBER() OVER (
                  PARTITION BY LOAI
                  ORDER BY TEN_TINH
              ) * 0.001                    AS SORT_ORDER,
        TO_NCHAR('+')                      AS "TT",
        TEN_TINH                           AS "NoiCuTru",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM chi_tiet_tinh_raw
)

        -- =========================
        -- OUTPUT
        -- =========================
        SELECT TO_CHAR(SORT_ORDER, 'FM9999990.000') AS SORT_ORDER,
               "TT",
               "NoiCuTru",
               "Nam",
               "Nu",
               "Khac",
               "TongSo"
        FROM (
            SELECT * FROM tong_loai
            UNION ALL
            SELECT * FROM chi_tiet_tinh

            UNION ALL

            SELECT 999,
                   TO_NCHAR(''),
                   TO_NCHAR(u'T?ng s?'),
                   SUM("Nam"),
                   SUM("Nu"),
                   SUM("Khac"),
                   SUM("TongSo")
            FROM tong_loai  
        )
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_THONG_KE_NOI_CU_TRU;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_PHAM_NHAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_PHAM_NHAN" (
    p_ngay      IN DATE,
    p_trai_giam IN NUMBER
)
AS 
	p_result    SYS_REFCURSOR;
    v_tu_ngay  DATE := TRUNC(p_ngay, 'MM');
    v_den_ngay DATE := ADD_MONTHS(TRUNC(p_ngay, 'MM'), 1);

    -- Q1
    v_q1_nam   NUMBER := 0; v_q1_nu   NUMBER := 0; v_q1_khac  NUMBER := 0;
    -- Q2~Q7
    v_q2_nam   NUMBER := 0; v_q2_nu   NUMBER := 0; v_q2_khac  NUMBER := 0;
    v_q3_nam   NUMBER := 0; v_q3_nu   NUMBER := 0; v_q3_khac  NUMBER := 0;
    v_q4_nam   NUMBER := 0; v_q4_nu   NUMBER := 0; v_q4_khac  NUMBER := 0;
    v_q5_nam   NUMBER := 0; v_q5_nu   NUMBER := 0; v_q5_khac  NUMBER := 0;
    v_q6_nam   NUMBER := 0; v_q6_nu   NUMBER := 0; v_q6_khac  NUMBER := 0;
    v_q7_nam   NUMBER := 0; v_q7_nu   NUMBER := 0; v_q7_khac  NUMBER := 0;
    -- Q8 t?ng nh?p
    v_q8_nam   NUMBER := 0; v_q8_nu   NUMBER := 0; v_q8_khac  NUMBER := 0;
    -- Q9~Q15
    v_q9_nam   NUMBER := 0; v_q9_nu   NUMBER := 0; v_q9_khac  NUMBER := 0;
    v_q10_nam  NUMBER := 0; v_q10_nu  NUMBER := 0; v_q10_khac NUMBER := 0;
    v_q11_nam  NUMBER := 0; v_q11_nu  NUMBER := 0; v_q11_khac NUMBER := 0;
    v_q12_nam  NUMBER := 0; v_q12_nu  NUMBER := 0; v_q12_khac NUMBER := 0;
    v_q13_nam  NUMBER := 0; v_q13_nu  NUMBER := 0; v_q13_khac NUMBER := 0;
    v_q14_nam  NUMBER := 0; v_q14_nu  NUMBER := 0; v_q14_khac NUMBER := 0;
    v_q15_nam  NUMBER := 0; v_q15_nu  NUMBER := 0; v_q15_khac NUMBER := 0;
    -- Q16 t?ng xu?t
    v_q16_nam  NUMBER := 0; v_q16_nu  NUMBER := 0; v_q16_khac NUMBER := 0;
BEGIN
    -- ===== Q1 =====
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN pll.ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN pll.ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN pll.ID END)
    INTO v_q1_nam, v_q1_nu, v_q1_khac
    FROM PN_LAI_LICHS pll
    JOIN DM_TINH_TRANG_PHAM_NHANS tt ON pll.LL_TINH_TRANG_ID = tt.ID
    LEFT JOIN DM_GIOI_TINHS dgt       ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE
              NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0 AND tt.TTPN_TEN NOT IN (
        'Ch?t','Tha tr??c th?i h?n có ?i?u ki?n','Trích xu?t tr?n',
        'Trích xu?t h?y án','Hoãn thi hành án','Trích xu?t gi?m tha',
        'T?m ?ình ch? tr?n','Chuy?n giao thi hành án','Gi?m h?t án',
        '???c ??c xá','T?m ?ình ch? ??c xá','Hu? án',
        'T?m ?ình ch? chuy?n tr?i','B?t bu?c ch?a b?nh h?t án',
        'Tr?n tr?i truy nã','T?m ?ình ch? ???c mi?n','T?m ?ình ch? ch?t',
        'Trích xu?t h?t án','Tr?n tr?i','Chuy?n tr?i khác','Tr?n tr?i ch?t',
        'Trích xu?t ch?t','K?t thúc h? s?','Trích xu?t chuy?n tr?i',
        'Ch?p hành xong hình ph?t tù','Trích xu?t ??c xá','Mi?n hình ph?t'
    )
    AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- ===== Q2 =====
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN pnct.PNCT_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN pnct.PNCT_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN pnct.PNCT_LAI_LICH_ID END)
    INTO v_q2_nam, v_q2_nu, v_q2_khac
    FROM PHAM_NHAN_CHUYEN_TRAI pnct
    JOIN PN_LAI_LICHS pll   ON pll.ID = pnct.PNCT_LAI_LICH_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    JOIN DM_TRAI_GIAMS dtg  ON pnct.PNCT_TRAI_DEN_ID = dtg.ID
    WHERE pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay
      AND pnct.PNCT_NGAY_CHUYEN <  v_den_ngay
      AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI > SYSDATE)
      AND UPPER(dtg.TG_TEN) LIKE '%T?M%'
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- ===== Q3 =====
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN pnct.PNCT_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN pnct.PNCT_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN pnct.PNCT_LAI_LICH_ID END)
    INTO v_q3_nam, v_q3_nu, v_q3_khac
    FROM PHAM_NHAN_CHUYEN_TRAI pnct
    JOIN PN_LAI_LICHS pll   ON pll.ID = pnct.PNCT_LAI_LICH_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    JOIN DM_TRAI_GIAMS dtg  ON pnct.PNCT_TRAI_DEN_ID = dtg.ID
    WHERE pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay
      AND pnct.PNCT_NGAY_CHUYEN <  v_den_ngay
      AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI > SYSDATE)
      AND UPPER(dtg.TG_TEN) LIKE '%TR?I GIAM%'
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- ===== Q4 =====
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN tt.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN tt.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN tt.PHAM_NHAN_ID END)
    INTO v_q4_nam, v_q4_nu, v_q4_khac
    FROM TRON_TRAIS tt
    JOIN PN_LAI_LICHS pll   ON pll.ID = tt.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE tt.NGAY_BAT_LAI >= v_tu_ngay
      AND tt.NGAY_BAT_LAI <  v_den_ngay
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- ===== Q5 =====
    SELECT
        COUNT(CASE WHEN dgt.GT_TEN = 'Nam'               THEN tdc.PHAM_NHAN_ID END),
        COUNT(CASE WHEN dgt.GT_TEN = 'N?'               THEN tdc.PHAM_NHAN_ID END),
        COUNT(CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN tdc.PHAM_NHAN_ID END)
    INTO v_q5_nam, v_q5_nu, v_q5_khac
    FROM TAM_DINH_CHIS tdc
    JOIN PN_LAI_LICHS pll   ON pll.ID = tdc.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE tdc.NGAY_LAI >= v_tu_ngay
      AND tdc.NGAY_LAI <  v_den_ngay
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- ===== Q6 =====
    SELECT
        COUNT(CASE WHEN dgt.GT_TEN = 'Nam'               THEN tx.PHAM_NHAN_ID END),
        COUNT(CASE WHEN dgt.GT_TEN = 'N?'               THEN tx.PHAM_NHAN_ID END),
        COUNT(CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN tx.PHAM_NHAN_ID END)
    INTO v_q6_nam, v_q6_nu, v_q6_khac
    FROM TRICH_XUATS tx
    JOIN PN_LAI_LICHS pll   ON pll.ID = tx.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE tx.TX_NGAY_TRA >= v_tu_ngay
      AND tx.TX_NGAY_TRA <  v_den_ngay
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- ===== Q7 =====
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN tcdk.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN tcdk.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN tcdk.PHAM_NHAN_ID END)
    INTO v_q7_nam, v_q7_nu, v_q7_khac
    FROM THA_CO_DIEU_KIENS tcdk
    JOIN PN_LAI_LICHS pll   ON pll.ID = tcdk.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE tcdk.NGAY_BAT_LAI >= v_tu_ngay
      AND tcdk.NGAY_BAT_LAI <  v_den_ngay
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- ===== Q8: T?ng nh?p (UNION 2-7) =====
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN u.PN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN u.PN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN u.PN_ID END)
    INTO v_q8_nam, v_q8_nu, v_q8_khac
    FROM (
        SELECT pnct.PNCT_LAI_LICH_ID AS PN_ID FROM PHAM_NHAN_CHUYEN_TRAI pnct JOIN DM_TRAI_GIAMS dtg ON pnct.PNCT_TRAI_DEN_ID = dtg.ID JOIN PN_LAI_LICHS pll2 ON pll2.ID = pnct.PNCT_LAI_LICH_ID
        WHERE pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay AND pnct.PNCT_NGAY_CHUYEN < v_den_ngay AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI > SYSDATE) AND UPPER(dtg.TG_TEN) LIKE '%T?M%' AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT pnct.PNCT_LAI_LICH_ID FROM PHAM_NHAN_CHUYEN_TRAI pnct JOIN DM_TRAI_GIAMS dtg ON pnct.PNCT_TRAI_DEN_ID = dtg.ID JOIN PN_LAI_LICHS pll2 ON pll2.ID = pnct.PNCT_LAI_LICH_ID
        WHERE pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay AND pnct.PNCT_NGAY_CHUYEN < v_den_ngay AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI > SYSDATE) AND UPPER(dtg.TG_TEN) LIKE '%TR?I GIAM%' AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT tt.PHAM_NHAN_ID FROM TRON_TRAIS tt JOIN PN_LAI_LICHS pll2 ON pll2.ID = tt.PHAM_NHAN_ID
        WHERE tt.NGAY_BAT_LAI >= v_tu_ngay AND tt.NGAY_BAT_LAI < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT tdc.PHAM_NHAN_ID FROM TAM_DINH_CHIS tdc JOIN PN_LAI_LICHS pll2 ON pll2.ID = tdc.PHAM_NHAN_ID
        WHERE tdc.NGAY_LAI >= v_tu_ngay AND tdc.NGAY_LAI < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT tx.PHAM_NHAN_ID FROM TRICH_XUATS tx JOIN PN_LAI_LICHS pll2 ON pll2.ID = tx.PHAM_NHAN_ID
        WHERE tx.TX_NGAY_TRA >= v_tu_ngay AND tx.TX_NGAY_TRA < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT tcdk.PHAM_NHAN_ID FROM THA_CO_DIEU_KIENS tcdk JOIN PN_LAI_LICHS pll2 ON pll2.ID = tcdk.PHAM_NHAN_ID
        WHERE tcdk.NGAY_BAT_LAI >= v_tu_ngay AND tcdk.NGAY_BAT_LAI < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
    ) u
    JOIN PN_LAI_LICHS pll ON pll.ID = u.PN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID;

    -- ===== Q9 =====
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN u.PN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN u.PN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN u.PN_ID END)
    INTO v_q9_nam, v_q9_nu, v_q9_khac
    FROM (
        SELECT pdx.PNLAI_LICH_ID AS PN_ID FROM PN_DAC_XAS pdx JOIN PN_LAI_LICHS pll2 ON pll2.ID = pdx.PNLAI_LICH_ID
        WHERE pdx.DX_NGAY_THA >= v_tu_ngay AND pdx.DX_NGAY_THA < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT gth.PHAM_NHAN_ID FROM GIAM_THOI_HANS gth JOIN PN_LAI_LICHS pll2 ON pll2.ID = gth.PHAM_NHAN_ID
        WHERE gth.NGAY_THA_GIAM_HET_AN >= v_tu_ngay AND gth.NGAY_THA_GIAM_HET_AN < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT pktrt.KTRT_PN_LAI_LICH_ID FROM PN_KET_THUC_RA_TRAIS pktrt JOIN PN_LAI_LICHS pll2 ON pll2.ID = pktrt.KTRT_PN_LAI_LICH_ID
        WHERE pktrt.KTRT_NGAY_THA >= v_tu_ngay AND pktrt.KTRT_NGAY_THA < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT tcdk.PHAM_NHAN_ID FROM THA_CO_DIEU_KIENS tcdk JOIN PN_LAI_LICHS pll2 ON pll2.ID = tcdk.PHAM_NHAN_ID
        WHERE tcdk.NGAY_THA >= v_tu_ngay AND tcdk.NGAY_THA < v_den_ngay AND (tcdk.NGAY_BAT_LAI IS NULL OR tcdk.NGAY_BAT_LAI >= v_den_ngay) AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
    ) u
    JOIN PN_LAI_LICHS pll ON pll.ID = u.PN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID;

    -- ===== Q10 =====
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN tt.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN tt.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN tt.PHAM_NHAN_ID END)
    INTO v_q10_nam, v_q10_nu, v_q10_khac
    FROM TRON_TRAIS tt
    JOIN PN_LAI_LICHS pll   ON pll.ID = tt.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE tt.NGAY_TRON >= v_tu_ngay
      AND tt.NGAY_TRON <  v_den_ngay
      AND (tt.NGAY_BAT_LAI IS NULL OR tt.NGAY_BAT_LAI >= v_den_ngay)
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- ===== Q11 =====
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN pktc.KTC_PN_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN pktc.KTC_PN_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN pktc.KTC_PN_LAI_LICH_ID END)
    INTO v_q11_nam, v_q11_nu, v_q11_khac
    FROM PN_KET_THUC_CHETS pktc
    JOIN PN_LAI_LICHS pll   ON pll.ID = pktc.KTC_PN_LAI_LICH_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE pktc.KTC_NGAY_CHET >= v_tu_ngay
      AND pktc.KTC_NGAY_CHET <  v_den_ngay
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- ===== Q12 =====
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN tx.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN tx.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN tx.PHAM_NHAN_ID END)
    INTO v_q12_nam, v_q12_nu, v_q12_khac
    FROM TRICH_XUATS tx
    JOIN PN_LAI_LICHS pll   ON pll.ID = tx.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE tx.TX_TU_NGAY >= v_tu_ngay
      AND tx.TX_TU_NGAY <  v_den_ngay
      AND (tx.TX_NGAY_TRA IS NULL OR tx.TX_NGAY_TRA > SYSDATE)
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- ===== Q13 =====
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN tdc.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN tdc.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN tdc.PHAM_NHAN_ID END)
    INTO v_q13_nam, v_q13_nu, v_q13_khac
    FROM TAM_DINH_CHIS tdc
    JOIN PN_LAI_LICHS pll   ON pll.ID = tdc.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE tdc.TU_NGAY >= v_tu_ngay
      AND tdc.TU_NGAY <  v_den_ngay
      AND (tdc.NGAY_LAI IS NULL OR tdc.NGAY_LAI > SYSDATE)
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- ===== Q14 =====
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN pnct.PNCT_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN pnct.PNCT_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN pnct.PNCT_LAI_LICH_ID END)
    INTO v_q14_nam, v_q14_nu, v_q14_khac
    FROM PHAM_NHAN_CHUYEN_TRAI pnct
    JOIN VW_PN_LAI_LICH_CHI_TIET vw ON pnct.PNCT_LAI_LICH_ID = vw.PHAM_NHAN_ID
    JOIN PN_LAI_LICHS pll            ON pll.ID = pnct.PNCT_LAI_LICH_ID
    LEFT JOIN DM_GIOI_TINHS dgt      ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE pnct.PNCT_TRAI_DEN_ID <> vw.TRAI_GIAM
      AND pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay
      AND pnct.PNCT_NGAY_CHUYEN <  v_den_ngay
      AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI >= v_den_ngay)
      AND (p_trai_giam IS NULL OR vw.TRAI_GIAM_ID = p_trai_giam);

    -- ===== Q15 =====
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN u.PN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN u.PN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN u.PN_ID END)
    INTO v_q15_nam, v_q15_nu, v_q15_khac
    FROM (
        SELECT ha.PHAM_NHAN_ID AS PN_ID FROM HUY_ANS ha JOIN PN_LAI_LICHS pll2 ON pll2.ID = ha.PHAM_NHAN_ID
        WHERE ha.NGAY_TRO_LAI >= v_tu_ngay AND ha.NGAY_TRO_LAI < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT htha.PHAM_NHAN_ID FROM HOAN_THI_HANH_ANS htha JOIN PN_LAI_LICHS pll2 ON pll2.ID = htha.PHAM_NHAN_ID
        WHERE htha.NGAY_HOAN >= v_tu_ngay AND htha.NGAY_HOAN < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT pcg.PNCG_LAI_LICH_ID FROM PN_CHUYEN_GIAO pcg JOIN DM_QUOC_TICHS dqt ON dqt.ID = pcg.PNCG_NUOC_CHUYEN_GIAO_ID JOIN PN_LAI_LICHS pll2 ON pll2.ID = pcg.PNCG_LAI_LICH_ID
        WHERE pcg.PNCG_NGAY_CHUYEN_GIAO >= v_tu_ngay AND pcg.PNCG_NGAY_CHUYEN_GIAO < v_den_ngay AND dqt.QT_TEN = 'Vi?t Nam' AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
    ) u
    JOIN PN_LAI_LICHS pll ON pll.ID = u.PN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID;

    -- ===== Q16: T?ng xu?t (UNION 9-15) =====
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN u.PN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN u.PN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN u.PN_ID END)
    INTO v_q16_nam, v_q16_nu, v_q16_khac
    FROM (
        SELECT pdx.PNLAI_LICH_ID AS PN_ID FROM PN_DAC_XAS pdx JOIN PN_LAI_LICHS pll2 ON pll2.ID = pdx.PNLAI_LICH_ID
        WHERE pdx.DX_NGAY_THA >= v_tu_ngay AND pdx.DX_NGAY_THA < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT gth.PHAM_NHAN_ID FROM GIAM_THOI_HANS gth JOIN PN_LAI_LICHS pll2 ON pll2.ID = gth.PHAM_NHAN_ID
        WHERE gth.NGAY_THA_GIAM_HET_AN >= v_tu_ngay AND gth.NGAY_THA_GIAM_HET_AN < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT pktrt.KTRT_PN_LAI_LICH_ID FROM PN_KET_THUC_RA_TRAIS pktrt JOIN PN_LAI_LICHS pll2 ON pll2.ID = pktrt.KTRT_PN_LAI_LICH_ID
        WHERE pktrt.KTRT_NGAY_THA >= v_tu_ngay AND pktrt.KTRT_NGAY_THA < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT tcdk.PHAM_NHAN_ID FROM THA_CO_DIEU_KIENS tcdk JOIN PN_LAI_LICHS pll2 ON pll2.ID = tcdk.PHAM_NHAN_ID
        WHERE tcdk.NGAY_THA >= v_tu_ngay AND tcdk.NGAY_THA < v_den_ngay AND (tcdk.NGAY_BAT_LAI IS NULL OR tcdk.NGAY_BAT_LAI >= v_den_ngay) AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT tt.PHAM_NHAN_ID FROM TRON_TRAIS tt JOIN PN_LAI_LICHS pll2 ON pll2.ID = tt.PHAM_NHAN_ID
        WHERE tt.NGAY_TRON >= v_tu_ngay AND tt.NGAY_TRON < v_den_ngay AND (tt.NGAY_BAT_LAI IS NULL OR tt.NGAY_BAT_LAI >= v_den_ngay) AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT pktc.KTC_PN_LAI_LICH_ID FROM PN_KET_THUC_CHETS pktc JOIN PN_LAI_LICHS pll2 ON pll2.ID = pktc.KTC_PN_LAI_LICH_ID
        WHERE pktc.KTC_NGAY_CHET >= v_tu_ngay AND pktc.KTC_NGAY_CHET < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT tx.PHAM_NHAN_ID FROM TRICH_XUATS tx JOIN PN_LAI_LICHS pll2 ON pll2.ID = tx.PHAM_NHAN_ID
        WHERE tx.TX_TU_NGAY >= v_tu_ngay AND tx.TX_TU_NGAY < v_den_ngay AND (tx.TX_NGAY_TRA IS NULL OR tx.TX_NGAY_TRA > SYSDATE) AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT tdc.PHAM_NHAN_ID FROM TAM_DINH_CHIS tdc JOIN PN_LAI_LICHS pll2 ON pll2.ID = tdc.PHAM_NHAN_ID
        WHERE tdc.TU_NGAY >= v_tu_ngay AND tdc.TU_NGAY < v_den_ngay AND (tdc.NGAY_LAI IS NULL OR tdc.NGAY_LAI > SYSDATE) AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT pnct.PNCT_LAI_LICH_ID FROM PHAM_NHAN_CHUYEN_TRAI pnct JOIN VW_PN_LAI_LICH_CHI_TIET vw ON pnct.PNCT_LAI_LICH_ID = vw.PHAM_NHAN_ID
        WHERE pnct.PNCT_TRAI_DEN_ID <> vw.TRAI_GIAM AND pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay AND pnct.PNCT_NGAY_CHUYEN < v_den_ngay AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI >= v_den_ngay) AND (p_trai_giam IS NULL OR vw.TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT ha.PHAM_NHAN_ID FROM HUY_ANS ha JOIN PN_LAI_LICHS pll2 ON pll2.ID = ha.PHAM_NHAN_ID
        WHERE ha.NGAY_TRO_LAI >= v_tu_ngay AND ha.NGAY_TRO_LAI < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT htha.PHAM_NHAN_ID FROM HOAN_THI_HANH_ANS htha JOIN PN_LAI_LICHS pll2 ON pll2.ID = htha.PHAM_NHAN_ID
        WHERE htha.NGAY_HOAN >= v_tu_ngay AND htha.NGAY_HOAN < v_den_ngay AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT pcg.PNCG_LAI_LICH_ID FROM PN_CHUYEN_GIAO pcg JOIN DM_QUOC_TICHS dqt ON dqt.ID = pcg.PNCG_NUOC_CHUYEN_GIAO_ID JOIN PN_LAI_LICHS pll2 ON pll2.ID = pcg.PNCG_LAI_LICH_ID
        WHERE pcg.PNCG_NGAY_CHUYEN_GIAO >= v_tu_ngay AND pcg.PNCG_NGAY_CHUYEN_GIAO < v_den_ngay AND dqt.QT_TEN = 'Vi?t Nam' AND (p_trai_giam IS NULL OR pll2.LL_TRAI_GIAM_ID = p_trai_giam)
    ) u
    JOIN PN_LAI_LICHS pll ON pll.ID = u.PN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID;

    -- ===== M? CURSOR TR? K?T QU? =====
    OPEN p_result FOR
    SELECT
        v_q1_nam + v_q1_nu + v_q1_khac                                         AS "1",
        v_q2_nam + v_q2_nu + v_q2_khac                                         AS "2",
        v_q3_nam + v_q3_nu + v_q3_khac                                         AS "3",
        v_q4_nam + v_q4_nu + v_q4_khac                                         AS "4",
        v_q5_nam + v_q5_nu + v_q5_khac                                         AS "5",
        v_q6_nam + v_q6_nu + v_q6_khac                                         AS "6",
        v_q7_nam + v_q7_nu + v_q7_khac                                         AS "7",
        v_q8_nam + v_q8_nu + v_q8_khac                                         AS "8",
        v_q9_nam + v_q9_nu + v_q9_khac                                         AS "9",
        v_q10_nam + v_q10_nu + v_q10_khac                                      AS "10",
        v_q11_nam + v_q11_nu + v_q11_khac                                      AS "11",
        v_q12_nam + v_q12_nu + v_q12_khac                                      AS "12",
        v_q13_nam + v_q13_nu + v_q13_khac                                      AS "13",
        v_q14_nam + v_q14_nu + v_q14_khac                                      AS "14",
        v_q15_nam + v_q15_nu + v_q15_khac                                      AS "15",
        v_q16_nam + v_q16_nu + v_q16_khac                                      AS "16",
        (v_q1_nam  - v_q16_nam  + v_q8_nam)                                    AS "17",
        (v_q1_nu   - v_q16_nu   + v_q8_nu)                                     AS "18",
        (v_q1_khac - v_q16_khac + v_q8_khac)                                   AS "19",
        (v_q1_nam  - v_q16_nam  + v_q8_nam)
      + (v_q1_nu   - v_q16_nu   + v_q8_nu)
      + (v_q1_khac - v_q16_khac + v_q8_khac)                                   AS "20"
    FROM DUAL;
	DBMS_SQL.RETURN_RESULT(p_result);
END SP_THONG_KE_PHAM_NHAN;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_PHAM_NHAN_THANG_PT80
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_PHAM_NHAN_THANG_PT80" (
    p_ngay_tu   IN DATE,
    p_ngay_den  IN DATE,
    p_trai_giam IN NUMBER DEFAULT NULL 
)
AS
    p_result    SYS_REFCURSOR;
    v_tu_ngay   DATE;
    v_den_ngay  DATE;

    v_q1_nam  NUMBER := 0; v_q1_nu  NUMBER := 0; v_q1_khac  NUMBER := 0;
    v_q2_nam  NUMBER := 0; v_q2_nu  NUMBER := 0; v_q2_khac  NUMBER := 0;
    v_q3_nam  NUMBER := 0; v_q3_nu  NUMBER := 0; v_q3_khac  NUMBER := 0;
    v_q4_nam  NUMBER := 0; v_q4_nu  NUMBER := 0; v_q4_khac  NUMBER := 0;
    v_q5_nam  NUMBER := 0; v_q5_nu  NUMBER := 0; v_q5_khac  NUMBER := 0;
    v_q6_nam  NUMBER := 0; v_q6_nu  NUMBER := 0; v_q6_khac  NUMBER := 0;
    v_q7_nam  NUMBER := 0; v_q7_nu  NUMBER := 0; v_q7_khac  NUMBER := 0;
    v_q8_nam  NUMBER := 0; v_q8_nu  NUMBER := 0; v_q8_khac  NUMBER := 0;
    v_q9_nam  NUMBER := 0; v_q9_nu  NUMBER := 0; v_q9_khac  NUMBER := 0;
    v_q10_nam NUMBER := 0; v_q10_nu NUMBER := 0; v_q10_khac NUMBER := 0;
    v_q11_nam NUMBER := 0; v_q11_nu NUMBER := 0; v_q11_khac NUMBER := 0;
    v_q12_nam NUMBER := 0; v_q12_nu NUMBER := 0; v_q12_khac NUMBER := 0;
    v_q13_nam NUMBER := 0; v_q13_nu NUMBER := 0; v_q13_khac NUMBER := 0;
    v_q14_nam NUMBER := 0; v_q14_nu NUMBER := 0; v_q14_khac NUMBER := 0;
    v_q15_nam NUMBER := 0; v_q15_nu NUMBER := 0; v_q15_khac NUMBER := 0;
    v_q16_nam NUMBER := 0; v_q16_nu NUMBER := 0; v_q16_khac NUMBER := 0;

    v21 NUMBER := 0; v22 NUMBER := 0; v23 NUMBER := 0; v24 NUMBER := 0;
    v25 NUMBER := 0; v26 NUMBER := 0; v27 NUMBER := 0; v28 NUMBER := 0;
    v29 NUMBER := 0; v30 NUMBER := 0; v31 NUMBER := 0; v32 NUMBER := 0;
    v33 NUMBER := 0; v34 NUMBER := 0; v35 NUMBER := 0; v36 NUMBER := 0;
    v37 NUMBER := 0; v38 NUMBER := 0; v39 NUMBER := 0; v40 NUMBER := 0;
    v41 NUMBER := 0; v42 NUMBER := 0;

    v43 NUMBER := 0; v44 NUMBER := 0; v45 NUMBER := 0; v46 NUMBER := 0;
    v47 NUMBER := 0; v48 NUMBER := 0; v49 NUMBER := 0; v50 NUMBER := 0;
    v51 NUMBER := 0; v52 NUMBER := 0; v53 NUMBER := 0; v54 NUMBER := 0;
    v55 NUMBER := 0; v56 NUMBER := 0; v57 NUMBER := 0; v58 NUMBER := 0;
    v59 NUMBER := 0; v60 NUMBER := 0; v61 NUMBER := 0; v62 NUMBER := 0;
    v63 NUMBER := 0;
BEGIN
    -- ===== Normalize ngày =====
    IF EXTRACT(DAY FROM p_ngay_tu) < 15 THEN
        v_tu_ngay := TRUNC(ADD_MONTHS(p_ngay_tu, -1), 'MM') + 14;
    ELSE
        v_tu_ngay := TRUNC(p_ngay_tu, 'MM') + 14;
    END IF;
    IF EXTRACT(DAY FROM p_ngay_den) > 14 THEN
        v_den_ngay := TRUNC(ADD_MONTHS(p_ngay_den, 1), 'MM') + 13;
    ELSE
        v_den_ngay := TRUNC(p_ngay_den, 'MM') + 13;
    END IF;

    -- ========== PH?N 1: C?T 1-20 (Nh?p/Xu?t/Cu?i k?) ==========

    -- Q1: S? ??u k?
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN pll.ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'               THEN pll.ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN pll.ID END)
    INTO v_q1_nam, v_q1_nu, v_q1_khac
    FROM PN_LAI_LICHS pll
    JOIN DM_TINH_TRANG_PHAM_NHANS tt ON pll.LL_TINH_TRANG_ID = tt.ID
    LEFT JOIN DM_GIOI_TINHS dgt       ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE
              NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0 AND tt.TTPN_TEN NOT IN (
        u'Ch\1ebft', u'Tha tr\01b0\1edbc th\1eddi h\1ea1n c\00f3 \0111i\1ec1u ki\1ec7n', u'Tr\00edch xu\1ea5t tr\1ed1n',
        u'Tr\00edch xu\1ea5t h\1ee7y \00e1n', u'Ho\00e3n thi h\00e0nh \00e1n', u'Tr\00edch xu\1ea5t gi\1ea3m tha',
        u'T\1ea1m \0111\00ecnh ch\1ec9 tr\1ed1n', u'Chuy\1ec3n giao thi h\00e0nh \00e1n', u'Gi\1ea3m h\1ebft \00e1n',
        u'\0110\01b0\1ee3c \0111\1eb7c x\00e1', u'T\1ea1m \0111\00ecnh ch\1ec9 \0111\1eb7c x\00e1', u'Hu\1ef7 \00e1n',
        u'T\1ea1m \0111\00ecnh ch\1ec9 chuy\1ec3n tr\1ea1i', u'B\1eaft bu\1ed9c ch\1eefa b\1ec7nh h\1ebft \00e1n',
        u'Tr\1ed1n tr\1ea1i truy n\00e3', u'T\1ea1m \0111\00ecnh ch\1ec9 \0111\01b0\1ee3c mi\1ec5n', u'T\1ea1m \0111\00ecnh ch\1ec9 ch\1ebft',
        u'Tr\00edch xu\1ea5t h\1ebft \00e1n', u'Tr\1ed1n tr\1ea1i', u'Chuy\1ec3n tr\1ea1i kh\00e1c', u'Tr\1ed1n tr\1ea1i ch\1ebft',
        u'Tr\00edch xu\1ea5t ch\1ebft', u'K\1ebft th\00fac h\1ed3 s\01a1', u'Tr\00edch xu\1ea5t chuy\1ec3n tr\1ea1i',
        u'Ch\1ea5p h\00e0nh xong h\00ecnh ph\1ea1t t\00f9', u'Tr\00edch xu\1ea5t \0111\1eb7c x\00e1', u'Mi\1ec5n h\00ecnh ph\1ea1t'
    )
    AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- Q2: Tr?i t?m giam chuy?n ??n
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN pnct.PNCT_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'               THEN pnct.PNCT_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN pnct.PNCT_LAI_LICH_ID END)
    INTO v_q2_nam, v_q2_nu, v_q2_khac
    FROM PHAM_NHAN_CHUYEN_TRAI pnct
    JOIN PN_LAI_LICHS pll    ON pll.ID = pnct.PNCT_LAI_LICH_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    JOIN DM_TRAI_GIAMS dtg   ON pnct.PNCT_TRAI_DEN_ID = dtg.ID
    WHERE pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay
      AND pnct.PNCT_NGAY_CHUYEN <  v_den_ngay
      AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI > v_den_ngay)
      AND UPPER(dtg.TG_TEN) LIKE u'%T\1ea0M%'
      AND UPPER(dtg.TG_TEN) NOT LIKE u'%TR\1ea0I GIAM%'
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- Q3: Tr?i giam khác chuy?n ??n
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN pnct.PNCT_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'               THEN pnct.PNCT_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN pnct.PNCT_LAI_LICH_ID END)
    INTO v_q3_nam, v_q3_nu, v_q3_khac
    FROM PHAM_NHAN_CHUYEN_TRAI pnct
    JOIN PN_LAI_LICHS pll    ON pll.ID = pnct.PNCT_LAI_LICH_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID 
    JOIN DM_TRAI_GIAMS dtg   ON pnct.PNCT_TRAI_DEN_ID = dtg.ID
    WHERE pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay
      AND pnct.PNCT_NGAY_CHUYEN <  v_den_ngay
      AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI > v_den_ngay)
      AND UPPER(dtg.TG_TEN) LIKE u'%TR\1ea0I GIAM%'
      AND UPPER(dtg.TG_TEN) NOT LIKE u'%T\1ea0M%'
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- Q4: Tr?n b?t l?i
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN tt.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'               THEN tt.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN tt.PHAM_NHAN_ID END)
    INTO v_q4_nam, v_q4_nu, v_q4_khac
    FROM TRON_TRAIS tt
    JOIN PN_LAI_LICHS pll    ON pll.ID = tt.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE tt.NGAY_BAT_LAI >= v_tu_ngay AND tt.NGAY_BAT_LAI < v_den_ngay
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- Q5: T?m ?ình ch? tr? l?i
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN tdc.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'               THEN tdc.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN tdc.PHAM_NHAN_ID END)
    INTO v_q5_nam, v_q5_nu, v_q5_khac
    FROM TAM_DINH_CHIS tdc
    JOIN PN_LAI_LICHS pll    ON pll.ID = tdc.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE tdc.NGAY_LAI >= v_tu_ngay AND tdc.NGAY_LAI < v_den_ngay
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- Q6: Trích xu?t tr? l?i
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN tx.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'               THEN tx.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN tx.PHAM_NHAN_ID END)
    INTO v_q6_nam, v_q6_nu, v_q6_khac
    FROM TRICH_XUATS tx
    JOIN PN_LAI_LICHS pll    ON pll.ID = tx.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE tx.TX_NGAY_TRA >= v_tu_ngay AND tx.TX_NGAY_TRA < v_den_ngay
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- Q7: Tha có ?i?u ki?n b?t l?i
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN tcdk.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'               THEN tcdk.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN tcdk.PHAM_NHAN_ID END)
    INTO v_q7_nam, v_q7_nu, v_q7_khac
    FROM THA_CO_DIEU_KIENS tcdk
    JOIN PN_LAI_LICHS pll    ON pll.ID = tcdk.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE tcdk.NGAY_BAT_LAI >= v_tu_ngay AND tcdk.NGAY_BAT_LAI < v_den_ngay
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- Q8: T?ng nh?p
    v_q8_nam  := v_q2_nam  + v_q3_nam  + v_q4_nam  + v_q5_nam  + v_q6_nam  + v_q7_nam;
    v_q8_nu   := v_q2_nu   + v_q3_nu   + v_q4_nu   + v_q5_nu   + v_q6_nu   + v_q7_nu;
    v_q8_khac := v_q2_khac + v_q3_khac + v_q4_khac + v_q5_khac + v_q6_khac + v_q7_khac;

    -- Q9: Tha
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN u.PN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'               THEN u.PN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN u.PN_ID END)
    INTO v_q9_nam, v_q9_nu, v_q9_khac
    FROM (
        SELECT pdx.PNLAI_LICH_ID AS PN_ID FROM PN_DAC_XAS pdx
          JOIN PN_LAI_LICHS p2 ON p2.ID = pdx.PNLAI_LICH_ID
         WHERE pdx.DX_NGAY_THA >= v_tu_ngay AND pdx.DX_NGAY_THA < v_den_ngay
           AND (p_trai_giam IS NULL OR p2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT gth.PHAM_NHAN_ID FROM GIAM_THOI_HANS gth
          JOIN PN_LAI_LICHS p2 ON p2.ID = gth.PHAM_NHAN_ID
         WHERE gth.NGAY_THA_GIAM_HET_AN >= v_tu_ngay AND gth.NGAY_THA_GIAM_HET_AN < v_den_ngay
           AND (p_trai_giam IS NULL OR p2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT pktrt.KTRT_PN_LAI_LICH_ID FROM PN_KET_THUC_RA_TRAIS pktrt
          JOIN PN_LAI_LICHS p2 ON p2.ID = pktrt.KTRT_PN_LAI_LICH_ID
         WHERE pktrt.KTRT_NGAY_THA >= v_tu_ngay AND pktrt.KTRT_NGAY_THA < v_den_ngay
           AND (p_trai_giam IS NULL OR p2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT tcdk.PHAM_NHAN_ID FROM THA_CO_DIEU_KIENS tcdk
          JOIN PN_LAI_LICHS p2 ON p2.ID = tcdk.PHAM_NHAN_ID
         WHERE tcdk.NGAY_THA >= v_tu_ngay AND tcdk.NGAY_THA < v_den_ngay
           AND (tcdk.NGAY_BAT_LAI IS NULL OR tcdk.NGAY_BAT_LAI >= v_den_ngay)
           AND (p_trai_giam IS NULL OR p2.LL_TRAI_GIAM_ID = p_trai_giam)
    ) u
    JOIN PN_LAI_LICHS pll ON pll.ID = u.PN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID;

    -- Q10: Tr?n
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN tt.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'               THEN tt.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN tt.PHAM_NHAN_ID END)
    INTO v_q10_nam, v_q10_nu, v_q10_khac
    FROM TRON_TRAIS tt
    JOIN PN_LAI_LICHS pll ON pll.ID = tt.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE tt.NGAY_TRON >= v_tu_ngay AND tt.NGAY_TRON < v_den_ngay
      AND (tt.NGAY_BAT_LAI IS NULL OR tt.NGAY_BAT_LAI >= v_den_ngay)
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- Q11: Ch?t
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN pktc.KTC_PN_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'               THEN pktc.KTC_PN_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN pktc.KTC_PN_LAI_LICH_ID END)
    INTO v_q11_nam, v_q11_nu, v_q11_khac
    FROM PN_KET_THUC_CHETS pktc
    JOIN PN_LAI_LICHS pll ON pll.ID = pktc.KTC_PN_LAI_LICH_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE pktc.KTC_NGAY_CHET >= v_tu_ngay AND pktc.KTC_NGAY_CHET < v_den_ngay
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- Q12: Trích xu?t
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN tx.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'               THEN tx.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN tx.PHAM_NHAN_ID END)
    INTO v_q12_nam, v_q12_nu, v_q12_khac
    FROM TRICH_XUATS tx
    JOIN PN_LAI_LICHS pll ON pll.ID = tx.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE tx.TX_TU_NGAY >= v_tu_ngay AND tx.TX_TU_NGAY < v_den_ngay
      AND (tx.TX_NGAY_TRA IS NULL OR tx.TX_NGAY_TRA > v_den_ngay)
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- Q13: T?m ?ình ch?
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN tdc.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'               THEN tdc.PHAM_NHAN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN tdc.PHAM_NHAN_ID END)
    INTO v_q13_nam, v_q13_nu, v_q13_khac
    FROM TAM_DINH_CHIS tdc
    JOIN PN_LAI_LICHS pll ON pll.ID = tdc.PHAM_NHAN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE tdc.TU_NGAY >= v_tu_ngay AND tdc.TU_NGAY < v_den_ngay
      AND (tdc.NGAY_LAI IS NULL OR tdc.NGAY_LAI > v_den_ngay)
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam);

    -- Q14: Chuy?n tr?i
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN pnct.PNCT_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'               THEN pnct.PNCT_LAI_LICH_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN pnct.PNCT_LAI_LICH_ID END)
    INTO v_q14_nam, v_q14_nu, v_q14_khac
    FROM PHAM_NHAN_CHUYEN_TRAI pnct
    JOIN VW_PN_LAI_LICH_CHI_TIET vw ON pnct.PNCT_LAI_LICH_ID = vw.PHAM_NHAN_ID
    JOIN PN_LAI_LICHS pll            ON pll.ID = pnct.PNCT_LAI_LICH_ID
    LEFT JOIN DM_GIOI_TINHS dgt      ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    WHERE pnct.PNCT_TRAI_DEN_ID <> vw.TRAI_GIAM
      AND pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay AND pnct.PNCT_NGAY_CHUYEN < v_den_ngay
      AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI >= v_den_ngay)
      AND (p_trai_giam IS NULL OR vw.TRAI_GIAM_ID = p_trai_giam);

    -- Q15: Gi?m khác
    SELECT
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN u.PN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'               THEN u.PN_ID END),
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', u'N\1eef') THEN u.PN_ID END)
    INTO v_q15_nam, v_q15_nu, v_q15_khac
    FROM (
        SELECT ha.PHAM_NHAN_ID AS PN_ID FROM HUY_ANS ha
          JOIN PN_LAI_LICHS p2 ON p2.ID = ha.PHAM_NHAN_ID
         WHERE ha.NGAY_TRO_LAI >= v_tu_ngay AND ha.NGAY_TRO_LAI < v_den_ngay
           AND (p_trai_giam IS NULL OR p2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT htha.PHAM_NHAN_ID FROM HOAN_THI_HANH_ANS htha
          JOIN PN_LAI_LICHS p2 ON p2.ID = htha.PHAM_NHAN_ID
         WHERE htha.NGAY_HOAN >= v_tu_ngay AND htha.NGAY_HOAN < v_den_ngay
           AND (p_trai_giam IS NULL OR p2.LL_TRAI_GIAM_ID = p_trai_giam)
        UNION ALL
        SELECT pcg.PNCG_LAI_LICH_ID FROM PN_CHUYEN_GIAO pcg
          JOIN DM_QUOC_TICHS dqt ON dqt.ID = pcg.PNCG_NUOC_CHUYEN_GIAO_ID
          JOIN PN_LAI_LICHS p2 ON p2.ID = pcg.PNCG_LAI_LICH_ID
         WHERE pcg.PNCG_NGAY_CHUYEN_GIAO >= v_tu_ngay AND pcg.PNCG_NGAY_CHUYEN_GIAO < v_den_ngay
           AND dqt.QT_TEN = u'Vi\1ec7t Nam'
           AND (p_trai_giam IS NULL OR p2.LL_TRAI_GIAM_ID = p_trai_giam)
    ) u
    JOIN PN_LAI_LICHS pll ON pll.ID = u.PN_ID
    LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID;

    -- Q16: T?ng xu?t
    v_q16_nam  := v_q9_nam  + v_q10_nam  + v_q11_nam  + v_q12_nam  + v_q13_nam  + v_q14_nam  + v_q15_nam;
