      AND (EXTRACT(YEAR FROM v_den_ngay) - TO_NUMBER(SUBSTR(pll.LL_NGAY_SINH, -4))) < 60
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
      AND ptha.THA_NGAY_DEN_TRAI < v_den_ngay AND ptha.THA_NGAY_HET_HAN >= v_tu_ngay;

    -- 54: >=60 (g?p old 54[60-70] + old 55[>=70] theo format pt80)
    SELECT COUNT(DISTINCT pll.ID) INTO v54
    FROM PN_LAI_LICHS pll
    JOIN PN_THI_HANH_AN ptha ON pll.ID = ptha.THA_PNLAI_LICH_ID
    WHERE (EXTRACT(YEAR FROM v_den_ngay) - TO_NUMBER(SUBSTR(pll.LL_NGAY_SINH, -4))) >= 60
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
      AND ptha.THA_NGAY_DEN_TRAI < v_den_ngay AND ptha.THA_NGAY_HET_HAN >= v_tu_ngay;

    -- 55: Tái ph?m
    SELECT COUNT(DISTINCT pll.ID) INTO v55
    FROM PN_LAI_LICHS pll
    JOIN PN_THI_HANH_AN ptha ON pll.ID = ptha.THA_PNLAI_LICH_ID
    JOIN DM_TAI_PHAMS dtp ON pll.LL_TAI_PHAM  = dtp.ID
    WHERE NVL(dtp.TP_MA, '0') = '1'
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
      AND ptha.THA_NGAY_DEN_TRAI < v_den_ngay AND ptha.THA_NGAY_HET_HAN >= v_tu_ngay;

    -- 56: Tái ph?m nguy hi?m
    SELECT COUNT(DISTINCT pll.ID) INTO v56
    FROM PN_LAI_LICHS pll
    JOIN PN_THI_HANH_AN ptha ON pll.ID = ptha.THA_PNLAI_LICH_ID
    JOIN DM_TAI_PHAMS dtp ON pll.LL_TAI_PHAM  = dtp.ID
    WHERE NVL(dtp.TP_MA, '0') = '2'
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
      AND ptha.THA_NGAY_DEN_TRAI < v_den_ngay AND ptha.THA_NGAY_HET_HAN >= v_tu_ngay;

    -- 57: N??c ngoài
    SELECT COUNT(DISTINCT pll.ID) INTO v57
    FROM PN_LAI_LICHS pll
    JOIN PN_THI_HANH_AN ptha ON pll.ID = ptha.THA_PNLAI_LICH_ID
    JOIN DM_QUOC_TICHS qt ON pll.LL_DM_QUOC_TICH_ID = qt.ID
    WHERE qt.QT_TEN <> u'Vi\1ec7t Nam'
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
      AND ptha.THA_NGAY_DEN_TRAI < v_den_ngay AND ptha.THA_NGAY_HET_HAN >= v_tu_ngay;

    -- 58: Tôn giáo
    SELECT COUNT(DISTINCT pll.ID) INTO v58
    FROM PN_LAI_LICHS pll
    JOIN PN_THI_HANH_AN ptha ON pll.ID = ptha.THA_PNLAI_LICH_ID
    JOIN DM_TON_GIAOS tg ON pll.LL_DM_TON_GIAO_ID = tg.ID
    WHERE LOWER(tg.TG_TEN) != u'kh\00f4ng'
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
      AND ptha.THA_NGAY_DEN_TRAI < v_den_ngay AND ptha.THA_NGAY_HET_HAN >= v_tu_ngay;

    -- 59: Dân t?c ít ng??i
    SELECT COUNT(DISTINCT pll.ID) INTO v59
    FROM PN_LAI_LICHS pll
    JOIN PN_THI_HANH_AN ptha ON pll.ID = ptha.THA_PNLAI_LICH_ID
    JOIN DM_DAN_TOCS dt ON pll.LL_DM_DAN_TOC_ID = dt.ID
    WHERE dt.DT_TEN <> u'Kinh'
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
      AND ptha.THA_NGAY_DEN_TRAI < v_den_ngay AND ptha.THA_NGAY_HET_HAN >= v_tu_ngay;

    -- 60: Không bi?t ch?
    SELECT COUNT(DISTINCT pll.ID) INTO v60
    FROM PN_LAI_LICHS pll
    JOIN PN_THI_HANH_AN ptha ON pll.ID = ptha.THA_PNLAI_LICH_ID
    JOIN DM_HOC_VANS hv ON pll.LL_DM_HOC_VAN_ID = hv.ID
    WHERE hv.HV_TEN LIKE u'%Kh\00f4ng'
      AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
      AND ptha.THA_NGAY_DEN_TRAI < v_den_ngay AND ptha.THA_NGAY_HET_HAN >= v_tu_ngay;

    -- 61: Con PN d??i 24 tháng
    SELECT COUNT(DISTINCT tncc.ID) INTO v61
    FROM THAN_NHAN_CON_CAIS tncc
    JOIN PN_LAI_LICHS pll ON tncc.PHAM_NHAN_ID = pll.ID
    WHERE (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
      AND (EXTRACT(YEAR FROM v_den_ngay) - TO_NUMBER(SUBSTR(tncc.NGAY_SINH, -4))) < 2
      AND tncc.NGAY_DEN >= v_tu_ngay AND tncc.NGAY_DEN < v_den_ngay;

    -- 62: Con PN 24-36 tháng
    SELECT COUNT(DISTINCT tncc.ID) INTO v62
    FROM THAN_NHAN_CON_CAIS tncc
    JOIN PN_LAI_LICHS pll ON tncc.PHAM_NHAN_ID = pll.ID
    WHERE (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
      AND (EXTRACT(YEAR FROM v_den_ngay) - TO_NUMBER(SUBSTR(tncc.NGAY_SINH, -4))) = 2
      AND tncc.NGAY_DEN >= v_tu_ngay AND tncc.NGAY_DEN < v_den_ngay;

    -- 63: Con PN >=36 tháng
    SELECT COUNT(DISTINCT tncc.ID) INTO v63
    FROM THAN_NHAN_CON_CAIS tncc
    JOIN PN_LAI_LICHS pll ON tncc.PHAM_NHAN_ID = pll.ID
    WHERE (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
      AND (EXTRACT(YEAR FROM v_den_ngay) - TO_NUMBER(SUBSTR(tncc.NGAY_SINH, -4))) >= 3
      AND tncc.NGAY_DEN >= v_tu_ngay AND tncc.NGAY_DEN < v_den_ngay;

    -- ========== TR? K?T QU? (63 c?t, gi?ng SP_GET_PT80) ==========
    OPEN p_result FOR
    SELECT
        v_q1_nam + v_q1_nu + v_q1_khac     AS "1",
        v_q2_nam + v_q2_nu + v_q2_khac     AS "2",
        v_q3_nam + v_q3_nu + v_q3_khac     AS "3",
        v_q4_nam + v_q4_nu + v_q4_khac     AS "4",
        v_q5_nam + v_q5_nu + v_q5_khac     AS "5",
        v_q6_nam + v_q6_nu + v_q6_khac     AS "6",
        v_q7_nam + v_q7_nu + v_q7_khac     AS "7",
        v_q8_nam + v_q8_nu + v_q8_khac     AS "8",
        v_q9_nam + v_q9_nu + v_q9_khac     AS "9",
        v_q10_nam + v_q10_nu + v_q10_khac  AS "10",
        v_q11_nam + v_q11_nu + v_q11_khac  AS "11",
        v_q12_nam + v_q12_nu + v_q12_khac  AS "12",
        v_q13_nam + v_q13_nu + v_q13_khac  AS "13",
        v_q14_nam + v_q14_nu + v_q14_khac  AS "14",
        v_q15_nam + v_q15_nu + v_q15_khac  AS "15",
        v_q16_nam + v_q16_nu + v_q16_khac  AS "16",
        (v_q1_nam  + v_q8_nam  - v_q16_nam)                                        AS "17",
        (v_q1_nu   + v_q8_nu   - v_q16_nu)                                         AS "18",
        (v_q1_khac + v_q8_khac - v_q16_khac)                                       AS "19",
        (v_q1_nam + v_q8_nam - v_q16_nam) + (v_q1_nu + v_q8_nu - v_q16_nu)
            + (v_q1_khac + v_q8_khac - v_q16_khac)                                 AS "20",
        v21 AS "21", v22 AS "22", v23 AS "23", v24 AS "24",
        v25 AS "25", v26 AS "26", v27 AS "27", v28 AS "28",
        v29 AS "29", v30 AS "30", v31 AS "31", v32 AS "32",
        v33 AS "33", v34 AS "34", v35 AS "35", v36 AS "36",
        v37 AS "37", v38 AS "38", v39 AS "39", v40 AS "40",
        v41 AS "41", v42 AS "42",
        v43 AS "43", v44 AS "44", v45 AS "45", v46 AS "46",
        v47 AS "47", v48 AS "48", v49 AS "49", v50 AS "50",
        v51 AS "51", v52 AS "52", v53 AS "53", v54 AS "54",
        v55 AS "55", v56 AS "56", v57 AS "57", v58 AS "58",
        v59 AS "59", v60 AS "60", v61 AS "61", v62 AS "62",
        v63 AS "63"
    FROM DUAL;

    DBMS_SQL.RETURN_RESULT(p_result);
END SP_THONG_KE_PHAM_NHAN_THANG_PT80;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_PHAM_NHAN_THEO_THANG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_PHAM_NHAN_THEO_THANG" (
    p_ngay      IN DATE DEFAULT NULL,
    p_trai_giam IN NUMBER DEFAULT NULL
)
AS
    v_tu_ngay   DATE := TRUNC(p_ngay, 'MM');
    v_den_ngay  DATE := ADD_MONTHS(TRUNC(p_ngay, 'MM'), 1);
    p_result    SYS_REFCURSOR;
BEGIN
    OPEN p_result FOR
    WITH
    -- ========================================================
    -- BASE: l?c ph?m nhân theo tr?i giam + tháng nh?p tr?i
    -- ========================================================
    base_pn AS (
        SELECT DISTINCT pll.ID          AS PN_ID,
                        dgt.GT_TEN      AS GIOI_TINH
        FROM PN_LAI_LICHS pll
        JOIN PN_THI_HANH_AN tha
             ON tha.THA_PNLAI_LICH_ID = pll.ID
        LEFT JOIN DM_GIOI_TINHS dgt
             ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        WHERE
              NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0 AND tha.THA_NGAY_DEN_TRAI >= v_tu_ngay
          AND tha.THA_NGAY_DEN_TRAI <  v_den_ngay
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q1: Ph?m nhân ?ang hi?n di?n (không thu?c tình tr?ng k?t thúc)
    -- ========================================================
    q1 AS (
        SELECT pll.ID AS PN_ID, dgt.GT_TEN AS GIOI_TINH
        FROM PN_LAI_LICHS pll
        JOIN DM_TINH_TRANG_PHAM_NHANS tt ON pll.LL_TINH_TRANG_ID = tt.ID
        LEFT JOIN DM_GIOI_TINHS dgt       ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        WHERE tt.TTPN_TEN NOT IN (
            'Ch?t','Tha tr??c th?i h?n có ?i?u ki?n','Trích xu?t tr?n',
            'Trích xu?t h?y án','Hoãn thi hành án','Trích xu?t gi?m tha',
            'T?m ?ình ch? tr?n','Chuy?n giao thi hành án','Gi?m h?t án',
            '???c ??c xá','T?m ?ình ch? ??c xá','Hu? án',
            'T?m ?ình ch? chuy?n tr?i','B?t bu?c ch?a b?nh h?t án',
            'Tr?n tr?i truy nã','T?m ?ình ch? ???c mi?n','T?m ?ình ch? ch?t',
            'Trích xu?t h?t án','Tr?n tr?i','Chuy?n tr?i khác','Tr?n tr?i ch?t',
            'Trích xu?t ch?t','K?t thúc h? s?','Trích xu?t chuy?n tr?i',
            'Ch?p hành xong hình ph?t tù','Trích xu?t ??c xá','Mi?n hình ph?t'
        )
        AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q2: Chuy?n ??n tr?i T?M trong tháng
    -- ========================================================
    q2 AS (
        SELECT DISTINCT pnct.PNCT_LAI_LICH_ID AS PN_ID, dgt.GT_TEN AS GIOI_TINH
        FROM PHAM_NHAN_CHUYEN_TRAI pnct
        JOIN PN_LAI_LICHS pll  ON pll.ID = pnct.PNCT_LAI_LICH_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        JOIN DM_TRAI_GIAMS dtg ON pnct.PNCT_TRAI_DEN_ID = dtg.ID
        WHERE pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay
          AND pnct.PNCT_NGAY_CHUYEN <  v_den_ngay
          AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI > SYSDATE)
          AND UPPER(dtg.TG_TEN) LIKE '%T?M%'
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q3: Chuy?n ??n TR?I GIAM trong tháng
    -- ========================================================
    q3 AS (
        SELECT DISTINCT pnct.PNCT_LAI_LICH_ID AS PN_ID, dgt.GT_TEN AS GIOI_TINH
        FROM PHAM_NHAN_CHUYEN_TRAI pnct
        JOIN PN_LAI_LICHS pll  ON pll.ID = pnct.PNCT_LAI_LICH_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        JOIN DM_TRAI_GIAMS dtg ON pnct.PNCT_TRAI_DEN_ID = dtg.ID
        WHERE pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay
          AND pnct.PNCT_NGAY_CHUYEN <  v_den_ngay
          AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI > SYSDATE)
          AND UPPER(dtg.TG_TEN) LIKE '%TR?I GIAM%'
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q4: B?t l?i tr?n tr?i trong tháng
    -- ========================================================
    q4 AS (
        SELECT DISTINCT tt.PHAM_NHAN_ID AS PN_ID, dgt.GT_TEN AS GIOI_TINH
        FROM TRON_TRAIS tt
        JOIN PN_LAI_LICHS pll  ON pll.ID = tt.PHAM_NHAN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        WHERE tt.NGAY_BAT_LAI >= v_tu_ngay
          AND tt.NGAY_BAT_LAI <  v_den_ngay
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q5: T?m ?ình ch? có ngày lai trong tháng
    -- ========================================================
    q5 AS (
        SELECT tdc.PHAM_NHAN_ID AS PN_ID, dgt.GT_TEN AS GIOI_TINH
        FROM TAM_DINH_CHIS tdc
        JOIN PN_LAI_LICHS pll  ON pll.ID = tdc.PHAM_NHAN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        WHERE tdc.NGAY_LAI >= v_tu_ngay
          AND tdc.NGAY_LAI <  v_den_ngay
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q6: Trích xu?t tr? trong tháng
    -- ========================================================
    q6 AS (
        SELECT tx.PHAM_NHAN_ID AS PN_ID, dgt.GT_TEN AS GIOI_TINH
        FROM TRICH_XUATS tx
        JOIN PN_LAI_LICHS pll  ON pll.ID = tx.PHAM_NHAN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        WHERE tx.TX_NGAY_TRA >= v_tu_ngay
          AND tx.TX_NGAY_TRA <  v_den_ngay
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q7: B?t l?i tha có ?i?u ki?n trong tháng
    -- ========================================================
    q7 AS (
        SELECT DISTINCT tcdk.PHAM_NHAN_ID AS PN_ID, dgt.GT_TEN AS GIOI_TINH
        FROM THA_CO_DIEU_KIENS tcdk
        JOIN PN_LAI_LICHS pll  ON pll.ID = tcdk.PHAM_NHAN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
        WHERE tcdk.NGAY_BAT_LAI >= v_tu_ngay
          AND tcdk.NGAY_BAT_LAI <  v_den_ngay
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q8: T?ng nh?p tr?i trong tháng (UNION 2-7, không phân gi?i tính)
    -- ========================================================
    q8_base AS (
        SELECT PN_ID FROM q2 UNION ALL
        SELECT PN_ID FROM q3 UNION ALL
        SELECT PN_ID FROM q4 UNION ALL
        SELECT PN_ID FROM q5 UNION ALL
        SELECT PN_ID FROM q6 UNION ALL
        SELECT PN_ID FROM q7
    ),

    -- ========================================================
    -- Q9: Ra tr?i trong tháng (??c xá / gi?m án / k?t thúc / tha C?K)
    -- ========================================================
    q9_base AS (
        SELECT pdx.PNLAI_LICH_ID AS PN_ID
        FROM PN_DAC_XAS pdx
        JOIN PN_LAI_LICHS pll ON pll.ID = pdx.PNLAI_LICH_ID
        WHERE pdx.DX_NGAY_THA >= v_tu_ngay
          AND pdx.DX_NGAY_THA <  v_den_ngay
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)

        UNION ALL

        SELECT gth.PHAM_NHAN_ID
        FROM GIAM_THOI_HANS gth
        JOIN PN_LAI_LICHS pll ON pll.ID = gth.PHAM_NHAN_ID
        WHERE gth.NGAY_THA_GIAM_HET_AN >= v_tu_ngay
          AND gth.NGAY_THA_GIAM_HET_AN <  v_den_ngay
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)

        UNION ALL

        SELECT pktrt.KTRT_PN_LAI_LICH_ID
        FROM PN_KET_THUC_RA_TRAIS pktrt
        JOIN PN_LAI_LICHS pll ON pll.ID = pktrt.KTRT_PN_LAI_LICH_ID
        WHERE pktrt.KTRT_NGAY_THA >= v_tu_ngay
          AND pktrt.KTRT_NGAY_THA <  v_den_ngay
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)

        UNION ALL

        SELECT tcdk.PHAM_NHAN_ID
        FROM THA_CO_DIEU_KIENS tcdk
        JOIN PN_LAI_LICHS pll ON pll.ID = tcdk.PHAM_NHAN_ID
        WHERE tcdk.NGAY_THA >= v_tu_ngay
          AND tcdk.NGAY_THA <  v_den_ngay
          AND (tcdk.NGAY_BAT_LAI IS NULL OR tcdk.NGAY_BAT_LAI >= v_den_ngay)
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q10: Tr?n tr?i trong tháng ch?a b?t l?i
    -- ========================================================
    q10_base AS (
        SELECT tt.PHAM_NHAN_ID AS PN_ID
        FROM TRON_TRAIS tt
        JOIN PN_LAI_LICHS pll ON pll.ID = tt.PHAM_NHAN_ID
        WHERE tt.NGAY_TRON >= v_tu_ngay
          AND tt.NGAY_TRON <  v_den_ngay
          AND (tt.NGAY_BAT_LAI IS NULL OR tt.NGAY_BAT_LAI >= v_den_ngay)
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q11: Ch?t trong tháng
    -- ========================================================
    q11_base AS (
        SELECT pktc.KTC_PN_LAI_LICH_ID AS PN_ID
        FROM PN_KET_THUC_CHETS pktc
        JOIN PN_LAI_LICHS pll ON pll.ID = pktc.KTC_PN_LAI_LICH_ID
        WHERE pktc.KTC_NGAY_CHET >= v_tu_ngay
          AND pktc.KTC_NGAY_CHET <  v_den_ngay
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q12: Trích xu?t trong tháng ch?a tr?
    -- ========================================================
    q12_base AS (
        SELECT tx.PHAM_NHAN_ID AS PN_ID
        FROM TRICH_XUATS tx
        JOIN PN_LAI_LICHS pll ON pll.ID = tx.PHAM_NHAN_ID
        WHERE tx.TX_TU_NGAY >= v_tu_ngay
          AND tx.TX_TU_NGAY <  v_den_ngay
          AND (tx.TX_NGAY_TRA IS NULL OR tx.TX_NGAY_TRA > SYSDATE)
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q13: T?m ?ình ch? trong tháng ch?a lai
    -- ========================================================
    q13_base AS (
        SELECT tdc.PHAM_NHAN_ID AS PN_ID
        FROM TAM_DINH_CHIS tdc
        JOIN PN_LAI_LICHS pll ON pll.ID = tdc.PHAM_NHAN_ID
        WHERE tdc.TU_NGAY >= v_tu_ngay
          AND tdc.TU_NGAY <  v_den_ngay
          AND (tdc.NGAY_LAI IS NULL OR tdc.NGAY_LAI > SYSDATE)
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q14: Chuy?n tr?i khác trong tháng
    -- ========================================================
    q14_base AS (
        SELECT pnct.PNCT_LAI_LICH_ID AS PN_ID
        FROM PHAM_NHAN_CHUYEN_TRAI pnct
        JOIN VW_PN_LAI_LICH_CHI_TIET vw ON pnct.PNCT_LAI_LICH_ID = vw.PHAM_NHAN_ID
        JOIN PN_LAI_LICHS pll ON pll.ID = pnct.PNCT_LAI_LICH_ID
        WHERE pnct.PNCT_TRAI_DEN_ID <> vw.TRAI_GIAM
          AND pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay
          AND pnct.PNCT_NGAY_CHUYEN <  v_den_ngay
          AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI >= v_den_ngay)
          AND (p_trai_giam IS NULL OR vw.TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q15: Hu? án / hoãn thi hành án / chuy?n giao v? VN
    -- ========================================================
    q15_base AS (
        SELECT ha.PHAM_NHAN_ID AS PN_ID
        FROM HUY_ANS ha
        JOIN PN_LAI_LICHS pll ON pll.ID = ha.PHAM_NHAN_ID
        WHERE ha.NGAY_TRO_LAI >= v_tu_ngay
          AND ha.NGAY_TRO_LAI <  v_den_ngay
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)

        UNION ALL

        SELECT htha.PHAM_NHAN_ID
        FROM HOAN_THI_HANH_ANS htha
        JOIN PN_LAI_LICHS pll ON pll.ID = htha.PHAM_NHAN_ID
        WHERE htha.NGAY_HOAN >= v_tu_ngay
          AND htha.NGAY_HOAN <  v_den_ngay
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)

        UNION ALL

        SELECT pcg.PNCG_LAI_LICH_ID
        FROM PN_CHUYEN_GIAO pcg
        JOIN DM_QUOC_TICHS dqt ON dqt.ID = pcg.PNCG_NUOC_CHUYEN_GIAO_ID
        JOIN PN_LAI_LICHS pll  ON pll.ID = pcg.PNCG_LAI_LICH_ID
        WHERE pcg.PNCG_NGAY_CHUYEN_GIAO >= v_tu_ngay
          AND pcg.PNCG_NGAY_CHUYEN_GIAO <  v_den_ngay
          AND dqt.QT_TEN = 'Vi?t Nam'
          AND (p_trai_giam IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam)
    ),

    -- ========================================================
    -- Q16: T?ng xu?t tr?i trong tháng (UNION 9-15)
    -- ========================================================
    q16_base AS (
        SELECT PN_ID FROM q9_base  UNION ALL
        SELECT PN_ID FROM q10_base UNION ALL
        SELECT PN_ID FROM q11_base UNION ALL
        SELECT PN_ID FROM q12_base UNION ALL
        SELECT PN_ID FROM q13_base UNION ALL
        SELECT PN_ID FROM q14_base UNION ALL
        SELECT PN_ID FROM q15_base
    ),

    -- ========================================================
    -- T?ng h?p ??m theo gi?i tính cho Q1, Q8, Q16
    -- ========================================================
    cnt_q1 AS (
        SELECT
            COUNT(DISTINCT CASE WHEN GIOI_TINH = 'Nam'               THEN PN_ID END) AS nam,
            COUNT(DISTINCT CASE WHEN GIOI_TINH = 'N?'               THEN PN_ID END) AS nu,
            COUNT(DISTINCT CASE WHEN GIOI_TINH NOT IN ('Nam', 'N?') THEN PN_ID END) AS khac,
            COUNT(DISTINCT PN_ID) AS tong
        FROM q1
    ),
    cnt_q8 AS (
        SELECT
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN q.PN_ID END) AS nam,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN q.PN_ID END) AS nu,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN q.PN_ID END) AS khac,
            COUNT(DISTINCT q.PN_ID) AS tong
        FROM q8_base q
        JOIN PN_LAI_LICHS pll ON pll.ID = q.PN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    ),
    cnt_q16 AS (
        SELECT
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'               THEN q.PN_ID END) AS nam,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'               THEN q.PN_ID END) AS nu,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN ('Nam', 'N?') THEN q.PN_ID END) AS khac,
            COUNT(DISTINCT q.PN_ID) AS tong
        FROM q16_base q
        JOIN PN_LAI_LICHS pll ON pll.ID = q.PN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    ),

    -- ??m Q2-Q7 và Q9-Q15 theo gi?i tính
    cnt_q2  AS (SELECT COUNT(DISTINCT CASE WHEN GIOI_TINH='Nam' THEN PN_ID END) nam, COUNT(DISTINCT CASE WHEN GIOI_TINH='N?' THEN PN_ID END) nu, COUNT(DISTINCT CASE WHEN GIOI_TINH NOT IN('Nam','N?') THEN PN_ID END) khac FROM q2),
    cnt_q3  AS (SELECT COUNT(DISTINCT CASE WHEN GIOI_TINH='Nam' THEN PN_ID END) nam, COUNT(DISTINCT CASE WHEN GIOI_TINH='N?' THEN PN_ID END) nu, COUNT(DISTINCT CASE WHEN GIOI_TINH NOT IN('Nam','N?') THEN PN_ID END) khac FROM q3),
    cnt_q4  AS (SELECT COUNT(DISTINCT CASE WHEN GIOI_TINH='Nam' THEN PN_ID END) nam, COUNT(DISTINCT CASE WHEN GIOI_TINH='N?' THEN PN_ID END) nu, COUNT(DISTINCT CASE WHEN GIOI_TINH NOT IN('Nam','N?') THEN PN_ID END) khac FROM q4),
    cnt_q5  AS (SELECT COUNT(CASE WHEN GIOI_TINH='Nam' THEN PN_ID END) nam,          COUNT(CASE WHEN GIOI_TINH='N?' THEN PN_ID END) nu,          COUNT(CASE WHEN GIOI_TINH NOT IN('Nam','N?') THEN PN_ID END) khac          FROM q5),
    cnt_q6  AS (SELECT COUNT(CASE WHEN GIOI_TINH='Nam' THEN PN_ID END) nam,          COUNT(CASE WHEN GIOI_TINH='N?' THEN PN_ID END) nu,          COUNT(CASE WHEN GIOI_TINH NOT IN('Nam','N?') THEN PN_ID END) khac          FROM q6),
    cnt_q7  AS (SELECT COUNT(DISTINCT CASE WHEN GIOI_TINH='Nam' THEN PN_ID END) nam, COUNT(DISTINCT CASE WHEN GIOI_TINH='N?' THEN PN_ID END) nu, COUNT(DISTINCT CASE WHEN GIOI_TINH NOT IN('Nam','N?') THEN PN_ID END) khac FROM q7),

    cnt_q9 AS (
        SELECT
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN='Nam'               THEN q.PN_ID END) nam,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN='N?'               THEN q.PN_ID END) nu,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN('Nam','N?') THEN q.PN_ID END) khac
        FROM q9_base q
        JOIN PN_LAI_LICHS pll ON pll.ID = q.PN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    ),
    cnt_q10 AS (
        SELECT
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN='Nam'               THEN q.PN_ID END) nam,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN='N?'               THEN q.PN_ID END) nu,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN('Nam','N?') THEN q.PN_ID END) khac
        FROM q10_base q
        JOIN PN_LAI_LICHS pll ON pll.ID = q.PN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    ),
    cnt_q11 AS (
        SELECT
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN='Nam'               THEN q.PN_ID END) nam,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN='N?'               THEN q.PN_ID END) nu,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN('Nam','N?') THEN q.PN_ID END) khac
        FROM q11_base q
        JOIN PN_LAI_LICHS pll ON pll.ID = q.PN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    ),
    cnt_q12 AS (
        SELECT
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN='Nam'               THEN q.PN_ID END) nam,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN='N?'               THEN q.PN_ID END) nu,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN('Nam','N?') THEN q.PN_ID END) khac
        FROM q12_base q
        JOIN PN_LAI_LICHS pll ON pll.ID = q.PN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    ),
    cnt_q13 AS (
        SELECT
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN='Nam'               THEN q.PN_ID END) nam,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN='N?'               THEN q.PN_ID END) nu,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN('Nam','N?') THEN q.PN_ID END) khac
        FROM q13_base q
        JOIN PN_LAI_LICHS pll ON pll.ID = q.PN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    ),
    cnt_q14 AS (
        SELECT
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN='Nam'               THEN q.PN_ID END) nam,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN='N?'               THEN q.PN_ID END) nu,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN('Nam','N?') THEN q.PN_ID END) khac
        FROM q14_base q
        JOIN PN_LAI_LICHS pll ON pll.ID = q.PN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    ),
    cnt_q15 AS (
        SELECT
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN='Nam'               THEN q.PN_ID END) nam,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN='N?'               THEN q.PN_ID END) nu,
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN('Nam','N?') THEN q.PN_ID END) khac
        FROM q15_base q
        JOIN PN_LAI_LICHS pll ON pll.ID = q.PN_ID
        LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
    )

    -- ========================================================
    -- K?T QU? CU?I: 1 ROW, 20 C?T
    -- ========================================================
    SELECT
        -- Q1: T?ng hi?n di?n
        q1.tong                                                                 AS "1",
        -- Q2-Q7: Nh?p tr?i chi ti?t (Nam + N? + Khác g?p)
        q2.nam + q2.nu + q2.khac                                                AS "2",
        q3.nam + q3.nu + q3.khac                                                AS "3",
        q4.nam + q4.nu + q4.khac                                                AS "4",
        q5.nam + q5.nu + q5.khac                                                AS "5",
        q6.nam + q6.nu + q6.khac                                                AS "6",
        q7.nam + q7.nu + q7.khac                                                AS "7",
        -- Q8: T?ng nh?p tr?i
        q8.tong                                                                 AS "8",
        -- Q9-Q15: Xu?t tr?i chi ti?t
        q9.nam  + q9.nu  + q9.khac                                              AS "9",
        q10.nam + q10.nu + q10.khac                                             AS "10",
        q11.nam + q11.nu + q11.khac                                             AS "11",
        q12.nam + q12.nu + q12.khac                                             AS "12",
        q13.nam + q13.nu + q13.khac                                             AS "13",
        q14.nam + q14.nu + q14.khac                                             AS "14",
        q15.nam + q15.nu + q15.khac                                             AS "15",
        -- Q16: T?ng xu?t tr?i
        q16.tong                                                                AS "16",
        -- Q17-Q19: T?n cu?i tháng theo gi?i tính (công th?c: Q1 - Q16 + Q8)
        (q1.nam   - q16.nam   + q8.nam)                                         AS "17",
        (q1.nu    - q16.nu    + q8.nu)                                          AS "18",
        (q1.khac  - q16.khac  + q8.khac)                                        AS "19",
        -- Q20: T?ng t?n cu?i tháng
        (q1.nam - q16.nam + q8.nam)
      + (q1.nu  - q16.nu  + q8.nu)
      + (q1.khac- q16.khac+ q8.khac)                                            AS "20"
    FROM
        cnt_q1  q1,  cnt_q2  q2,  cnt_q3  q3,
        cnt_q4  q4,  cnt_q5  q5,  cnt_q6  q6,
        cnt_q7  q7,  cnt_q8  q8,  cnt_q9  q9,
        cnt_q10 q10, cnt_q11 q11, cnt_q12 q12,
        cnt_q13 q13, cnt_q14 q14, cnt_q15 q15,
        cnt_q16 q16;
    DBMS_SQL.RETURN_RESULT(p_result);
END SP_THONG_KE_PHAM_NHAN_THEO_THANG;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_PHAM_NHAN_THEO_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_PHAM_NHAN_THEO_TRAI" (
    p_trai_giam_ten IN NVARCHAR2,
    p_from_month    IN DATE,
    p_to_month      IN DATE,
    p_result        OUT SYS_REFCURSOR
) AS
BEGIN
    OPEN p_result FOR
        WITH pn_cha AS (
            SELECT
                pll.ID,
                dtg.TG_TEN,
                dpt.PT_TEN,
                dgt.GT_TEN,
                pll.LL_TINH_TRANG_ID,
                pll.CREATION_TIME,
                pll.LAST_MODIFICATION_TIME
            FROM PN_LAI_LICHS pll
            LEFT JOIN DM_TRAI_GIAMS dtg
                   ON dtg.ID = pll.LL_TRAI_GIAM_ID
            LEFT JOIN DM_PHAN_TRAIS dpt
                   ON dpt.ID = pll.LL_PHAN_TRAI_ID
            LEFT JOIN DM_GIOI_TINHS dgt
                   ON dgt.ID = pll.LL_DM_GIOI_TINH_ID
            WHERE
              NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0 AND pll.LL_TINH_TRANG_ID = 19
              AND NVL(pll.LAST_MODIFICATION_TIME, pll.CREATION_TIME)
                    BETWEEN p_from_month AND p_to_month
        )
        SELECT
            ROW_NUMBER() OVER (ORDER BY PT_TEN)                AS TT,
            PT_TEN                                             AS DON_VI,
            SUM(CASE WHEN GT_TEN = 'Nam' THEN 1 ELSE 0 END)    AS NAM,
            SUM(CASE WHEN GT_TEN = 'N?' THEN 1 ELSE 0 END)     AS NU,
            COUNT(*)                                           AS TONG_SO
        FROM pn_cha
        WHERE TG_TEN = p_trai_giam_ten
        GROUP BY PT_TEN
        ORDER BY PT_TEN;
END;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_PHAN_LOAI_GIAM_GIU
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_PHAN_LOAI_GIAM_GIU" (
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay      IN DATE   DEFAULT NULL,
    p_den_ngay     IN DATE   DEFAULT NULL
)
AS
    c1               SYS_REFCURSOR;
    v_trai_giam_id   NUMBER;  -- LL_TRAI_GIAM_ID th?c (partition key RT); map t? TG_MA ho?c ID
BEGIN
    IF p_trai_giam_id IS NULL THEN
        v_trai_giam_id := NULL;
    ELSE
        BEGIN
            SELECT tg.ID
            INTO v_trai_giam_id
            FROM QLPN.DM_TRAI_GIAMS tg
            WHERE NVL(tg.IS_DELETED, 0) = 0
              AND (tg.ID = p_trai_giam_id
                   OR tg.TG_MA = TRIM(TO_CHAR(p_trai_giam_id)))
            FETCH FIRST 1 ROW ONLY;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(
                    -20002,
                    'Không tìm th?y tr?i giam (mã/ID): ' || p_trai_giam_id
                );
        END;
    END IF;

    OPEN c1 FOR
    WITH
    ll_scope AS (
        SELECT /*+ MATERIALIZE NO_MERGE */
            rt.PHAM_NHAN_ID AS pn_id,
            rt.LL_DM_GIOI_TINH_ID,
            rt.THA_NGAY_DEN_TRAI
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT rt
        WHERE NVL(rt.IS_DELETED, 0) = 0
              AND EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = rt.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0)
          AND (v_trai_giam_id IS NULL OR rt.LL_TRAI_GIAM_ID = v_trai_giam_id)
          AND (p_tu_ngay IS NULL OR rt.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR rt.THA_NGAY_DEN_TRAI <= p_den_ngay)
    ),
    pl_moi_nhat AS (
        SELECT x.pham_nhan_id, x.den_loai_id, x.LL_DM_GIOI_TINH_ID
        FROM (
            SELECT /*+ LEADING(ls pl) USE_NL(ls pl) INDEX(pl IX_PHANLOAI_DEL_PN_NGAY) */
                pl.pham_nhan_id,
                pl.den_loai_id,
                ls.LL_DM_GIOI_TINH_ID,
                ROW_NUMBER() OVER (
                    PARTITION BY pl.pham_nhan_id
                    ORDER BY NVL(pl.NGAY_PHAN_LOAI, pl.CREATION_TIME) DESC NULLS LAST,
                             pl.ID DESC
                ) AS rn
            FROM ll_scope ls
            INNER JOIN QLPN.PHAN_LOAIS pl
                ON pl.PHAM_NHAN_ID = ls.pn_id
               AND NVL(pl.IS_DELETED, 0) = 0
        ) x
        WHERE x.rn = 1
    ),
    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY dplgg.ID) AS sort_order,
            TO_CHAR(ROW_NUMBER() OVER (ORDER BY dplgg.ID)) AS "TT",
            NVL(dplgg.PLGG_TEN, u'Ch?a xác ??nh') AS "PhanLoai",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN pl.pham_nhan_id END) AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N?' THEN pl.pham_nhan_id END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, u'Khác') NOT IN (u'Nam', u'N?') THEN pl.pham_nhan_id END) AS "Khac",
            COUNT(DISTINCT pl.pham_nhan_id) AS "TongSo"
        FROM pl_moi_nhat pl
        LEFT JOIN QLPN.DM_GIOI_TINHS dgt
            ON pl.LL_DM_GIOI_TINH_ID = dgt.ID
           AND NVL(dgt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_PHAN_LOAI_GIAM_GIUS dplgg
            ON pl.den_loai_id = dplgg.ID
           AND NVL(dplgg.IS_DELETED, 0) = 0
        GROUP BY dplgg.ID, dplgg.PLGG_TEN
    )
    SELECT
        "TT",
        "PhanLoai",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            sort_order,
            "TT",
            "PhanLoai",
            "Nam",
            "Nu",
            "Khac",
            "TongSo"
        FROM chi_tiet
        UNION ALL
        SELECT
            999,
            NULL,
            u'T?ng s?',
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY sort_order;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i SP_THONG_KE_PHAN_LOAI_GIAM_GIU: ' || SQLERRM);
END SP_THONG_KE_PHAN_LOAI_GIAM_GIU;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_PN_THEO_PHAN_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_PN_THEO_PHAN_TRAI" (
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
        WITH

    selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ),
             pham_nhan_filtered AS ( SELECT ll.PHAM_NHAN_ID,
                                           ll.LL_DM_GIOI_TINH_ID,
                                           ll.LL_PHAN_TRAI_ID
                                    FROM pn_base ll
                                             LEFT JOIN DM_TRAI_GIAMS dtg
                                                       ON dtg.ID = ll.LL_TRAI_GIAM_ID
                                                           AND dtg.IS_DELETED = 0
                                             LEFT JOIN DM_QUOC_TICHS dqt
                                                       ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
                                                           AND dqt.IS_DELETED = 0
-- FILTER START
                                    WHERE ll.IS_DELETED = 0
                                      AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

                                      -- NHÓM 1: Kho?ng ngày
                                      AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                      AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                      AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                      AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                                      AND (
                                        (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM PN_DAC_XAS dxa
                                                       WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                                                         AND dxa.IS_DELETED = 0
                                                         AND (p_dac_xa_tu_ngay IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                                         AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
                                        )
                                      AND (
                                        (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM GIAM_THOI_HANS gaan
                                                       WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                         AND gaan.IS_DELETED = 0
                                                         AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                                        )

                                      -- NHÓM 2: Kho?ng s?
                                      AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
                                      AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                                      AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                                      AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                                      AND (p_tg_chap_hanh_tu IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                                      AND (p_tg_chap_hanh_den IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                                      AND (p_tg_con_lai_tu IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                                      AND (p_tg_con_lai_den IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                                      -- NHÓM 3: Danh m?c
                                      AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
                                      AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
                                      AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
                                      AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                                      AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
                                      AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

                                      -- [T?i danh]
                                      AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
                                      AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                                      AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG = p_loai_doi_tuong_id)

                                      -- [Ghi chú riêng]
                                      AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

                                      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                                      -- NHÓM 4: Checkbox
                                      AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
                                      AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
                                      AND (p_giam_rieng IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PN_GIAM_RIENGS gr
                                                         WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                                                           AND gr.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_giam_rieng
                                        ))
                                      AND (
								    p_dan_toc_thieu_so IS NULL
								    OR (
								        CASE
								            WHEN EXISTS (
								                SELECT 1
								                FROM DM_DAN_TOCS dt
								                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
								                  AND dt.IS_DELETED = 0
								                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
								            )
								            THEN 1
								            ELSE 0
								        END = p_dan_toc_thieu_so
								    )
								)
                                      AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                                        CASE
                                            WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_thoi_diem_pham_toi
                                        ))
                                      AND (p_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PHAM_TOI_MOIS ptm
                                                         WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_pham_toi_moi
                                        ))
                                      AND (p_theo_ton_giao IS NULL OR (
								        CASE
								            WHEN EXISTS (
								                SELECT 1
								                FROM DM_TON_GIAOS tg
								                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
								                  AND tg.IS_DELETED = 0

								            )
								            THEN 1
								            ELSE 0
								        END = p_theo_ton_giao ))
                                      AND (p_vtn_hien_tai IS NULL OR (
                                        CASE
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_hien_tai
                                        ))
                                      AND (p_khong_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN NOT EXISTS (SELECT 1
                                                             FROM PHAM_TOI_MOIS ptm
                                                             WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                               AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_khong_pham_toi_moi
                                        ))
                                      AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
                                      AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
                                      AND (p_da_bi_ky_luat IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KY_LUATS kl
                                                         WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID) THEN 1
                                            ELSE 0 END = p_da_bi_ky_luat
                                        ))
                                      AND (p_co_ghi_chu_dac_biet IS NULL OR (
                                        CASE
                                            WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                                                AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                                                THEN 1
                                            ELSE 0 END = p_co_ghi_chu_dac_biet
                                        ))
                                      AND (p_toi_pham_anqg IS NULL OR (
                                          CASE WHEN EXISTS (
                                              SELECT 1 FROM DM_TOI_DANHS td
                                              WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                                                AND td.IS_DELETED = 0
                                                AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                                          ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                                      ))
                                      AND (p_da_duoc_khen_thuong IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KHEN_THUONGS kt
                                                         WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND kt.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_da_duoc_khen_thuong
                                        ))
                                      AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
                                      AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
                                      AND (p_con_theo_me_vao_trai IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM THAN_NHAN_CON_CAIS tncc
                                                         WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND tncc.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_con_theo_me_vao_trai
                                        ))
                                      AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
                                      AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
                                      AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
                                      AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))),
-- FILTER DONE

             chi_tiet AS (SELECT ROW_NUMBER() OVER (ORDER BY
                 CASE
                     WHEN dpt.PT_TEN IS NOT NULL
                         THEN dpt.PT_TEN
                     ELSE u'Kh\00f4ng x\00e1c \0111\1ecbnh'
                     END
                 )                                                                   AS SORT_ORDER,
                                 TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY
                                     CASE
                                         WHEN dpt.PT_TEN IS NOT NULL
                                             THEN dpt.PT_TEN
                                         ELSE u'Kh\00f4ng x\00e1c \0111\1ecbnh'
                                         END
                                     )))                                             AS "TT",
                                 NVL(dpt.PT_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')  AS "PhanTrai",
                                 COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'Nam' THEN pn.PHAM_NHAN_ID END)    AS "Nam",
                                 COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'N\1eef' THEN pn.PHAM_NHAN_ID END) AS "Nu",
                                 COUNT(DISTINCT CASE
                                                    WHEN gt.GT_TEN IS NULL OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                        THEN pn.PHAM_NHAN_ID
                                     END)                                                                  AS "Khac",
                                 COUNT(DISTINCT pn.PHAM_NHAN_ID)                                           AS "TongSo"
                          FROM pham_nhan_filtered pn
                                   LEFT JOIN DM_PHAN_TRAIS dpt
                                             ON dpt.ID = pn.LL_PHAN_TRAI_ID
                                                 AND NVL(dpt.IS_DELETED, 0) = 0
                                   LEFT JOIN DM_GIOI_TINHS gt
                                             ON gt.ID = pn.LL_DM_GIOI_TINH_ID
                                                 AND NVL(gt.IS_DELETED, 0) = 0
                          GROUP BY dpt.PT_TEN)

        SELECT "TT",
               "PhanTrai",
               "Nam",
               "Nu",
               "Khac",
               "TongSo"
        FROM (SELECT SORT_ORDER,
                     "PhanTrai",
                     "TT",
                     "Nam",
                     "Nu",
                     "Khac",
                     "TongSo"
              FROM chi_tiet

              UNION ALL

              SELECT 999,
                     TO_NCHAR(''),
                     TO_NCHAR(u'T\1ed5ng s\1ed1'),
                     SUM("Nam"),
                     SUM("Nu"),
                     SUM("Khac"),
                     SUM("TongSo")
              FROM chi_tiet)
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_PN_THEO_PHAN_TRAI;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_QUOC_TICH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_QUOC_TICH" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
    WITH
    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1
    ),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$') THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID         AS pham_nhan_id,
            ll.LL_DM_GIOI_TINH_ID,
            ll.LL_DM_HOC_VAN_ID,
            ll.LL_DM_NGHE_NGHIEP_ID,
            ll.LL_SO_TIEN_AN,
            ll.LL_SO_TIEN_SU,
            ll.LL_DM_DAN_TOC_ID,
            ll.LL_DM_QUOC_TICH_ID,
            ll.LL_DM_TON_GIAO_ID,
            ll.THA_THOI_GIAN_DA_CHAP_HANH,
            ll.THA_THOI_GIAN_CON_LAI
        FROM pn_base ll
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
           AND dqt.IS_DELETED = 0
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
           AND dtg.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)
          -- NHÓM 1: Kho?ng ngày
          AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
          AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
          AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
          AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
          AND (
              (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
              OR EXISTS (SELECT 1 FROM PN_DAC_XAS dxa
                         WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID AND dxa.IS_DELETED = 0
                           AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                           AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
          )
          AND (
              (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
              OR EXISTS (SELECT 1 FROM GIAM_THOI_HANS gaan
                         WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND gaan.IS_DELETED = 0
                           AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                           AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
          )
          -- NHÓM 2: Kho?ng s?
          AND (p_so_tien_an_tu IS NULL OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu))
          AND (p_so_tien_an_den IS NULL OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den))
          AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
          AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
          AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
          AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
          AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
          AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
          AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
          AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
          -- NHÓM 3: Danh m?c
          AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
          AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
          AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
          AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
          AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
          AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
          AND (
              p_toi_danh_ids IS NULL
              OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
              OR EXISTS (SELECT 1 FROM selected_toi_danh_filter loc
                         WHERE INSTR(
                             ',' || REPLACE(REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''), ' ', '') || ',',
                             ',' || TRIM(loc.ma_loc) || ','
                         ) > 0)
          )
          AND (p_dp_dktt_id       IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
          AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG            = p_loai_doi_tuong_id)
          AND (
              p_ghi_chu_rieng_id IS NULL
              OR INSTR(',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ',') > 0
          )
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          -- NHÓM 4: Checkbox
          AND (p_nuoc_ngoai IS NULL OR (
              CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
          ))
          AND (p_co_benh_tat IS NULL OR (
              CASE
                  WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL THEN 1
                  WHEN EXISTS (SELECT 1 FROM DM_BENH_TATS dbt
                               WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                 AND dbt.IS_DELETED = 0 AND dbt.BT_MA = '1') THEN 0
                  ELSE 1
              END = p_co_benh_tat
          ))
          AND (p_giam_rieng IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM PN_GIAM_RIENGS gr
                                WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_giam_rieng
          ))
          AND (
              p_dan_toc_thieu_so IS NULL
              OR (CASE WHEN EXISTS (
                      SELECT 1 FROM DM_DAN_TOCS dt
                      WHERE dt.ID = ll.LL_DM_DAN_TOC_ID AND dt.IS_DELETED = 0
                        AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                  ) THEN 1 ELSE 0 END = p_dan_toc_thieu_so)
          )
          AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
              CASE
                  WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_thoi_diem_pham_toi
          ))
          AND (p_pham_toi_moi IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM PHAM_TOI_MOIS ptm
                                WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_pham_toi_moi
          ))
          AND (p_theo_ton_giao IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM DM_TON_GIAOS tg
                                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID AND tg.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_theo_ton_giao
          ))
          AND (p_vtn_hien_tai IS NULL OR (
              CASE
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_hien_tai
          ))
          AND (p_khong_pham_toi_moi IS NULL OR (
              CASE WHEN NOT EXISTS (SELECT 1 FROM PHAM_TOI_MOIS ptm
                                    WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_khong_pham_toi_moi
          ))
          AND (
              p_co_nghe_nghiep IS NULL
              OR (CASE WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                            AND EXISTS (SELECT 1 FROM DM_NGHE_NGHIEPS dnn
                                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID AND dnn.IS_DELETED = 0
                                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%'))
                       THEN 1 ELSE 0 END = p_co_nghe_nghiep)
          )
          AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
          AND (p_da_bi_ky_luat IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM KY_LUATS kl WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID)
                   THEN 1 ELSE 0 END = p_da_bi_ky_luat
          ))
          AND (p_co_ghi_chu_dac_biet IS NULL OR (
              CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                        AND ll.THA_GHI_CHU_DAC_BIET <> '[]' THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
          ))
          AND (p_toi_pham_anqg IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM DM_TOI_DANHS td
                  WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                    AND td.IS_DELETED = 0
                    AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
              ) THEN 1 ELSE 0 END = p_toi_pham_anqg
          ))
          AND (p_da_duoc_khen_thuong IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM KHEN_THUONGS kt
                                WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
          ))
          AND (p_co_tien_an IS NULL OR (
              CASE WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0' THEN 1 ELSE 0 END = p_co_tien_an
          ))
          AND (p_co_tien_su IS NULL OR (
              CASE WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0' THEN 1 ELSE 0 END = p_co_tien_su
          ))
          AND (p_con_theo_me_vao_trai IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                                WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
          ))
          AND (p_hp_bo_sung_la_tien IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                  WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                    AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
              ) THEN 1 ELSE 0 END = p_hp_bo_sung_la_tien
          ))
          AND (p_bat_buoc_chua_benh IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM CHUA_BENH_BAT_BUOCS cb
                                WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND cb.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_bat_buoc_chua_benh
          ))
          AND (
              p_hoan_xong_hpbs_la_tien IS NULL OR
              (CASE WHEN EXISTS (
                  SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                  WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                    AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                  GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                  HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
              ) THEN 1 ELSE 0 END = p_hoan_xong_hpbs_la_tien)
          )
          AND (
              p_chua_hoan_hpbs_la_tien IS NULL OR
              (CASE WHEN EXISTS (
                  SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                  WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                    AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                  GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                  HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
              ) THEN 1 ELSE 0 END = p_chua_hoan_hpbs_la_tien)
          )
    ),
    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY
                CASE WHEN dqt.QT_TEN = u'Vi\1ec7t Nam' THEN u'Qu\1ed1c t\1ecbch Vi\1ec7t Nam'
                     ELSE u'Qu\1ed1c t\1ecbch n\01b0\1edbc ngo\00e0i' END
            ) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY
                CASE WHEN dqt.QT_TEN = u'Vi\1ec7t Nam' THEN u'Qu\1ed1c t\1ecbch Vi\1ec7t Nam'
                     ELSE u'Qu\1ed1c t\1ecbch n\01b0\1edbc ngo\00e0i' END
            ))) AS "TT",
            CASE WHEN dqt.QT_TEN = u'Vi\1ec7t Nam' THEN u'Qu\1ed1c t\1ecbch Vi\1ec7t Nam'
                 ELSE u'Qu\1ed1c t\1ecbch n\01b0\1edbc ngo\00e0i' END AS "QuocTich",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam'  THEN ll.pham_nhan_id END) AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN ll.pham_nhan_id END) AS "Nu",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN IS NULL OR dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                THEN ll.pham_nhan_id END) AS "Khac",
            COUNT(DISTINCT ll.pham_nhan_id) AS "TongSo"
        FROM pham_nhan_filtered ll
        LEFT JOIN DM_GIOI_TINHS dgt ON dgt.ID = ll.LL_DM_GIOI_TINH_ID AND dgt.IS_DELETED = 0
        LEFT JOIN DM_QUOC_TICHS dqt ON dqt.ID = ll.LL_DM_QUOC_TICH_ID AND dqt.IS_DELETED = 0
        GROUP BY
            CASE WHEN dqt.QT_TEN = u'Vi\1ec7t Nam' THEN u'Qu\1ed1c t\1ecbch Vi\1ec7t Nam'
                 ELSE u'Qu\1ed1c t\1ecbch n\01b0\1edbc ngo\00e0i' END
    )
    SELECT "TT", "QuocTich", "Nam", "Nu", "Khac", "TongSo"
    FROM (
        SELECT SORT_ORDER, "TT", "QuocTich", "Nam", "Nu", "Khac", "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT 999,
               TO_NCHAR(''),
               TO_NCHAR(u'T\1ed5ng s\1ed1'),
               SUM("Nam"), SUM("Nu"), SUM("Khac"), SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_THONG_KE_QUOC_TICH;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_RA_TRAI_DAN_TOC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_RA_TRAI_DAN_TOC" (
    p_ma_trai_giam  IN VARCHAR2  DEFAULT NULL,
    p_phan_doi_id   IN NUMBER    DEFAULT NULL,
    p_tu_ngay       IN DATE      DEFAULT NULL,
    p_den_ngay      IN DATE      DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        SELECT
            ROW_NUMBER() OVER (ORDER BY ddt.DT_TEN)    AS "Stt",
            ddt.DT_TEN                                  AS "DanToc",
            COUNT(DISTINCT CASE
                WHEN ll.LL_DM_GIOI_TINH_ID = 1 THEN ll.ID
            END)                                        AS "Nam",
            COUNT(DISTINCT CASE
                WHEN ll.LL_DM_GIOI_TINH_ID = 2 THEN ll.ID
            END)                                        AS "Nu",
            COUNT(DISTINCT CASE
                WHEN ll.LL_DM_GIOI_TINH_ID NOT IN (1, 2) THEN ll.ID
            END)                                        AS "Khac",
            COUNT(DISTINCT CASE
                WHEN ll.LL_DM_GIOI_TINH_ID IS NOT NULL THEN ll.ID
            END)                                        AS "TongSo"
        FROM PN_KET_THUC_RA_TRAIS ktrt
        LEFT JOIN PN_LAI_LICHS ll
            ON ktrt.KTRT_PN_LAI_LICH_ID = ll.ID
        LEFT JOIN DM_DAN_TOCS ddt
            ON ll.LL_DM_DAN_TOC_ID = ddt.ID
        LEFT JOIN DM_TRAI_GIAMS tg
            ON ll.LL_TRAI_GIAM_ID = tg.ID AND NVL(tg.IS_DELETED, 0) = 0
        WHERE ktrt.IS_DELETED = 0
          AND ll.IS_DELETED   = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
          AND (p_ma_trai_giam IS NULL OR tg.TG_MA        = p_ma_trai_giam)
          AND (p_phan_doi_id  IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (p_tu_ngay      IS NULL OR ktrt.KTRT_NGAY_THA >= p_tu_ngay)
          AND (p_den_ngay     IS NULL OR ktrt.KTRT_NGAY_THA <  p_den_ngay + 1)
        GROUP BY ddt.DT_TEN
        ORDER BY ddt.DT_TEN;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, u'L\1ed7i SP_THONG_KE_RA_TRAI_DAN_TOC: ' || SQLERRM);
END SP_THONG_KE_RA_TRAI_DAN_TOC;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_RA_TRAI_DP_THEO_THANG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_RA_TRAI_DP_THEO_THANG" (
	p_ma_trai_giam   IN VARCHAR2   DEFAULT NULL, --Hai them
    p_phan_doi_id   IN NUMBER   DEFAULT NULL,
    p_tu_ngay       IN DATE     DEFAULT NULL,
    p_den_ngay      IN DATE     DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
--    BEGIN
--    SP_THONG_KE_RA_TRAI_DP_THEO_THANG(
--        p_phan_doi_id   => NULL,
--        p_tu_ngay       => DATE '2025-01-01',
--        p_den_ngay      => DATE '2026-03-31'
--    );
--	END;
        SELECT
            ROW_NUMBER() OVER (ORDER BY dvhc.TTP_TEN)  AS "Stt",
            dvhc.TTP_TEN                                AS "DiaPhuongVe",
            COUNT(DISTINCT CASE
                WHEN ll.LL_DM_GIOI_TINH_ID = 1 THEN ll.ID
            END)                                                AS "Nam",
            COUNT(DISTINCT CASE
                WHEN ll.LL_DM_GIOI_TINH_ID = 2 THEN ll.ID
            END)                                                AS "Nu",
            COUNT(DISTINCT CASE
                WHEN ll.LL_DM_GIOI_TINH_ID NOT IN (1, 2)  THEN ll.ID
            END)                                                AS "Khac",
            COUNT(DISTINCT
            CASE 
            WHEN ll.LL_DM_GIOI_TINH_ID IS NOT NULL THEN ll.ID
            END )    AS "TongSo"
        FROM PN_KET_THUC_RA_TRAIS ktrt
        LEFT JOIN PN_LAI_LICHS ll
            ON ktrt.KTRT_PN_LAI_LICH_ID = ll.ID
        LEFT JOIN DM_TINH_THANH_PHO dvhc
            ON ll.LL_NOI_THA_VE_CU_TRU_PROVICE = dvhc.ID
        WHERE ktrt.IS_DELETED = 0
          AND ll.IS_DELETED   = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
          AND (p_phan_doi_id   IS NULL OR ll.LL_PHAN_DOI_ID              = p_phan_doi_id)
          AND (p_tu_ngay       IS NULL OR ktrt.KTRT_NGAY_THA             >= p_tu_ngay)
          AND (p_den_ngay      IS NULL OR ktrt.KTRT_NGAY_THA             <  p_den_ngay + 1)
        GROUP BY dvhc.TTP_TEN
        ORDER BY dvhc.TTP_TEN;
    DBMS_SQL.RETURN_RESULT(c1);
END SP_THONG_KE_RA_TRAI_DP_THEO_THANG;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_RA_TRAI_QUOC_TICH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_RA_TRAI_QUOC_TICH" (
    p_ma_trai_giam  IN VARCHAR2  DEFAULT NULL,
    p_phan_doi_id   IN NUMBER    DEFAULT NULL,
    p_tu_ngay       IN DATE      DEFAULT NULL,
    p_den_ngay      IN DATE      DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
        SELECT
            ROW_NUMBER() OVER (ORDER BY dqt.QT_TEN)    AS "Stt",
            dqt.QT_TEN                                  AS "QuocTich",
            COUNT(DISTINCT CASE
                WHEN ll.LL_DM_GIOI_TINH_ID = 1 THEN ll.ID
            END)                                        AS "Nam",
            COUNT(DISTINCT CASE
                WHEN ll.LL_DM_GIOI_TINH_ID = 2 THEN ll.ID
            END)                                        AS "Nu",
            COUNT(DISTINCT CASE
                WHEN ll.LL_DM_GIOI_TINH_ID NOT IN (1, 2) THEN ll.ID
            END)                                        AS "Khac",
            COUNT(DISTINCT CASE
                WHEN ll.LL_DM_GIOI_TINH_ID IS NOT NULL THEN ll.ID
            END)                                        AS "TongSo"
        FROM PN_KET_THUC_RA_TRAIS ktrt
        LEFT JOIN PN_LAI_LICHS ll
            ON ktrt.KTRT_PN_LAI_LICH_ID = ll.ID
        LEFT JOIN DM_QUOC_TICHS dqt
            ON ll.LL_DM_QUOC_TICH_ID = dqt.ID
        LEFT JOIN DM_TRAI_GIAMS tg
            ON ll.LL_TRAI_GIAM_ID = tg.ID AND NVL(tg.IS_DELETED, 0) = 0
        WHERE ktrt.IS_DELETED = 0
          AND ll.IS_DELETED   = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
          AND (p_ma_trai_giam IS NULL OR tg.TG_MA        = p_ma_trai_giam)
          AND (p_phan_doi_id  IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (p_tu_ngay      IS NULL OR ktrt.KTRT_NGAY_THA >= p_tu_ngay)
          AND (p_den_ngay     IS NULL OR ktrt.KTRT_NGAY_THA <  p_den_ngay + 1)
        GROUP BY dqt.QT_TEN
        ORDER BY dqt.QT_TEN;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, u'L\1ed7i SP_THONG_KE_RA_TRAI_QUOC_TICH: ' || SQLERRM);
END SP_THONG_KE_RA_TRAI_QUOC_TICH;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_RA_TRAI_THEO_THANG_THEO_TRUONG_HOP
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_RA_TRAI_THEO_THANG_THEO_TRUONG_HOP" (
    p_ma_trai_giam IN VARCHAR2  DEFAULT NULL,
    p_phan_doi_id  IN NUMBER    DEFAULT NULL,
    p_tu_ngay      IN DATE      DEFAULT NULL,
    p_den_ngay     IN DATE      DEFAULT NULL,
    p_loai_ra_trai IN VARCHAR2  DEFAULT NULL   -- VD: '[1,2,3]' ho?c '1,2,3'
) AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    WITH
    -- Map STT lo?i sang TTPN_MA
    loai_map AS (
        SELECT 1 AS loai, '20' AS ttpn_ma, u'Ra tr\1ea1i' AS ten_loai FROM DUAL UNION ALL
        SELECT 2, '21', u'Ch\1ea5p h\00e0nh xong h\00ecnh ph\1ea1t t\00f9' FROM DUAL UNION ALL
        SELECT 3, '22', u'Gi\1ea3m h\1ebft th\1eddi h\1ea1n' FROM DUAL UNION ALL
        SELECT 4, '23', u'\0110\1eb7c x\00e1' FROM DUAL UNION ALL
        SELECT 5, '24', u'Tr\00edch xu\1ea5t h\1ebft \00e1n' FROM DUAL UNION ALL
        SELECT 6, '25', u'Tr\1ea3 t\1ef1 do' FROM DUAL UNION ALL
        SELECT 7, '26', u'Tha tr\01b0\1edbc th\1eddi h\1ea1n c\00f3 \0111i\1ec1u ki\1ec7n' FROM DUAL
    ),
    -- Làm s?ch tham s? p_loai_ra_trai
    p_loai_clean AS (
        SELECT REPLACE(REPLACE(TRIM(NVL(p_loai_ra_trai, '')), '[', ''), ']', '') AS csv
        FROM DUAL
    ),
    -- Các lo?i ???c phép hi?n th? (n?u không truy?n thì hi?n th? t?t c?)
    loai_display AS (
        SELECT lm.loai, lm.ttpn_ma, lm.ten_loai
        FROM loai_map lm
        CROSS JOIN p_loai_clean r
        WHERE (r.csv IS NULL OR TRIM(r.csv) = '')
           OR (',' || r.csv || ',' LIKE '%,' || lm.loai || ',%')
    ),
    -- B?n ghi ra tr?i m?i nh?t theo ph?m nhân trong kho?ng ngày
    KT_in_range AS (
        SELECT
            k0.KTRT_PN_LAI_LICH_ID,
            k0.KTRT_TRUONG_HOP_THA_ID,
            k0.KTRT_NGAY_THA
        FROM (
            SELECT
                k.KTRT_PN_LAI_LICH_ID,
                k.KTRT_TRUONG_HOP_THA_ID,
                k.KTRT_NGAY_THA,
                ROW_NUMBER() OVER (PARTITION BY k.KTRT_PN_LAI_LICH_ID
                                   ORDER BY NVL(k.KTRT_NGAY_THA, k.CREATION_TIME) DESC NULLS LAST) AS rn
            FROM PN_KET_THUC_RA_TRAIS k
            WHERE NVL(k.IS_DELETED, 0) = 0
              AND (p_tu_ngay IS NULL OR TRUNC(k.KTRT_NGAY_THA) >= TRUNC(p_tu_ngay))
              AND (p_den_ngay IS NULL OR TRUNC(k.KTRT_NGAY_THA) <= TRUNC(p_den_ngay))
        ) k0
        WHERE k0.rn = 1
    )
    -- Main query: b?t bu?c hi?n th? t?t c? lo?i trong loai_display, dù không có data
    SELECT
        ROW_NUMBER() OVER (ORDER BY ld.ten_loai) AS "Stt",
        ld.ten_loai AS "TruongHopRaTrai",
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN ll.ID END) AS "Nam",
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'  THEN ll.ID END) AS "Nu",
        COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') OR dgt.GT_TEN IS NULL
                            THEN ll.ID END) AS "Khac",
        COUNT(DISTINCT ll.ID) AS "TongSo"
    FROM loai_display ld
    LEFT JOIN DM_TRUONG_HOP_THAS dtht
           ON dtht.THT_TEN = ld.ten_loai
    LEFT JOIN KT_in_range kt
           ON kt.KTRT_TRUONG_HOP_THA_ID = dtht.ID
    LEFT JOIN PN_LAI_LICHS ll
           ON ll.ID = kt.KTRT_PN_LAI_LICH_ID
          AND NVL(ll.IS_DELETED, 0) = 0
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          AND (p_ma_trai_giam IS NULL OR ll.LL_TRAI_GIAM_ID IN (
                  SELECT tg.ID FROM DM_TRAI_GIAMS tg
                  WHERE tg.TG_MA = p_ma_trai_giam AND NVL(tg.IS_DELETED, 0) = 0))
    LEFT JOIN DM_GIOI_TINHS dgt
           ON dgt.ID = ll.LL_DM_GIOI_TINH_ID
    LEFT JOIN DM_TINH_TRANG_PHAM_NHANS dttph
           ON dttph.ID = ll.LL_TINH_TRANG_ID
    LEFT JOIN loai_display ld2
           ON ld2.ttpn_ma = dttph.TTPN_MA     -- ??m b?o filter lo?i
    GROUP BY ld.ten_loai, ld.loai
    ORDER BY ld.loai;                          -- s?p x?p theo STT lo?i g?c

    DBMS_SQL.RETURN_RESULT(C1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, u'L\1ed7i SP_THONG_KE_RA_TRAI_THEO_THANG_THEO_TRUONG_HOP: ' || SQLERRM);
END SP_THONG_KE_RA_TRAI_THEO_THANG_THEO_TRUONG_HOP;







/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_SO_TIEN_AN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_SO_TIEN_AN" (
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
        WITH
             selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ),
             pham_nhan_filtered AS ( SELECT ll.PHAM_NHAN_ID,
                                           ll.LL_DM_GIOI_TINH_ID,
                                           ll.LL_SO_TIEN_AN
                                	 FROM pn_base ll
	                                 LEFT JOIN DM_TRAI_GIAMS dtg
	                                           ON dtg.ID = ll.LL_TRAI_GIAM_ID
	                                               AND dtg.IS_DELETED = 0
	                                 LEFT JOIN DM_QUOC_TICHS dqt
	                                           ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
	                                               AND dqt.IS_DELETED = 0
                                    WHERE ll.IS_DELETED = 0
                                      AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

                                      -- NHÓM 1: Kho?ng ngày
                                    AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
                                    AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
                                    AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
                                    AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
                                      AND (
                                        (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM PN_DAC_XAS dxa
                                                       WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                                                         AND dxa.IS_DELETED = 0
                                                         AND (p_dac_xa_tu_ngay IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                                         AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
                                        )
                                      AND (
                                        (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM GIAM_THOI_HANS gaan
                                                       WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                         AND gaan.IS_DELETED = 0
                                                         AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                                        )

                                      -- NHÓM 2: Kho?ng s?
                                      AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
                                      AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
                                      AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
                                      AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
                                      AND (p_tg_chap_hanh_tu IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
                                      AND (p_tg_chap_hanh_den IS NULL OR
                                           ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
                                      AND (p_tg_con_lai_tu IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
                                      AND (p_tg_con_lai_den IS NULL OR
                                           ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)

                                      -- NHÓM 3: Danh m?c
                                      AND (p_gioi_tinh_id IS NULL OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
                                      AND (p_dan_toc_id IS NULL OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
                                      AND (p_quoc_tich_id IS NULL OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
                                      AND (p_nghe_nghiep_id IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
                                      AND (p_hoc_van_id IS NULL OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
                                      AND (p_ton_giao_id IS NULL OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)

                                      -- [T?i danh]
                                      AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
                                      AND (p_dp_dktt_id IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
                                      AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG = p_loai_doi_tuong_id)

                                      -- [Ghi chú riêng]
                                      AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )

                                      AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)

                                      -- NHÓM 4: Checkbox
                                      AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
                                      AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
                                      AND (p_giam_rieng IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PN_GIAM_RIENGS gr
                                                         WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                                                           AND gr.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_giam_rieng
                                        ))
                                      AND (
								    p_dan_toc_thieu_so IS NULL
								    OR (
								        CASE
								            WHEN EXISTS (
								                SELECT 1
								                FROM DM_DAN_TOCS dt
								                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
								                  AND dt.IS_DELETED = 0
								                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
								            )
								            THEN 1
								            ELSE 0
								        END = p_dan_toc_thieu_so
								    )
								)
                                      AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                                        CASE
                                            WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_thoi_diem_pham_toi
                                        ))
                                      AND (p_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM PHAM_TOI_MOIS ptm
                                                         WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_pham_toi_moi
                                        ))
                                      AND (p_theo_ton_giao IS NULL OR (
								        CASE
								            WHEN EXISTS (
								                SELECT 1
								                FROM DM_TON_GIAOS tg
								                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
								                  AND tg.IS_DELETED = 0
								            )
								            THEN 1
								            ELSE 0
								        END = p_theo_ton_giao ))
                                      AND (p_vtn_hien_tai IS NULL OR (
                                        CASE
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_hien_tai
                                        ))
                                      AND (p_khong_pham_toi_moi IS NULL OR (
                                        CASE
                                            WHEN NOT EXISTS (SELECT 1
                                                             FROM PHAM_TOI_MOIS ptm
                                                             WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                               AND ptm.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_khong_pham_toi_moi
                                        ))
                                      AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
                                      AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
                                      AND (p_da_bi_ky_luat IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KY_LUATS kl
                                                         WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID) THEN 1
                                            ELSE 0 END = p_da_bi_ky_luat
                                        ))
                                      AND (p_co_ghi_chu_dac_biet IS NULL OR (
                                        CASE
                                            WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                                                AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                                                THEN 1
                                            ELSE 0 END = p_co_ghi_chu_dac_biet
                                        ))
                                      AND (p_toi_pham_anqg IS NULL OR (
                                          CASE WHEN EXISTS (
                                              SELECT 1 FROM DM_TOI_DANHS td
                                              WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                                                AND td.IS_DELETED = 0
                                                AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                                          ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                                      ))
                                      AND (p_da_duoc_khen_thuong IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM KHEN_THUONGS kt
                                                         WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND kt.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_da_duoc_khen_thuong
                                        ))
                                      AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
                                      AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
                                      AND (p_con_theo_me_vao_trai IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM THAN_NHAN_CON_CAIS tncc
                                                         WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           AND tncc.IS_DELETED = 0) THEN 1
                                            ELSE 0 END = p_con_theo_me_vao_trai
                                        ))
                                      AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
                                      AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
                                      AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
                                      AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))),
             chi_tiet AS (SELECT ROW_NUMBER() OVER (
                 ORDER BY
                     CASE
                         WHEN ll.LL_SO_TIEN_AN IS NULL OR ll.LL_SO_TIEN_AN = 0 THEN u'Ch\01b0a c\00f3 ti\1ec1n \00e1n'
                         WHEN ll.LL_SO_TIEN_AN = 1 THEN u'C\00f3 1 ti\1ec1n \00e1n'
                         WHEN ll.LL_SO_TIEN_AN = 2 THEN u'C\00f3 2 ti\1ec1n \00e1n'
                         WHEN ll.LL_SO_TIEN_AN >= 3 THEN u'C\00f3 3 ti\1ec1n \00e1n tr\1edf l\00ean'
                         END
                 )                                                                                         AS SORT_ORDER,
                                 TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY
                                     CASE
                                         WHEN ll.LL_SO_TIEN_AN IS NULL OR ll.LL_SO_TIEN_AN = 0
                                             THEN u'Ch\01b0a c\00f3 ti\1ec1n \00e1n'
                                         WHEN ll.LL_SO_TIEN_AN = 1 THEN u'C\00f3 1 ti\1ec1n \00e1n'
                                         WHEN ll.LL_SO_TIEN_AN = 2 THEN u'C\00f3 2 ti\1ec1n \00e1n'
                                         WHEN ll.LL_SO_TIEN_AN >= 3 THEN u'C\00f3 3 ti\1ec1n \00e1n tr\1edf l\00ean'
                                         END
                                     )))                                                                   AS "TT",
                                 CASE
                                     WHEN ll.LL_SO_TIEN_AN IS NULL OR ll.LL_SO_TIEN_AN = 0
                                         THEN u'Ch\01b0a c\00f3 ti\1ec1n \00e1n'
                                     WHEN ll.LL_SO_TIEN_AN = 1 THEN u'C\00f3 1 ti\1ec1n \00e1n'
                                     WHEN ll.LL_SO_TIEN_AN = 2 THEN u'C\00f3 2 ti\1ec1n \00e1n'
                                     WHEN ll.LL_SO_TIEN_AN >= 3 THEN u'C\00f3 3 ti\1ec1n \00e1n tr\1edf l\00ean'
                                     END                                                                      "SoTienAn",
                                 COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN ll.PHAM_NHAN_ID END)    AS "Nam",
                                 COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN ll.PHAM_NHAN_ID END) AS "Nu",
                                 COUNT(DISTINCT CASE
                                                    WHEN dgt.GT_TEN IS NULL OR dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                        THEN ll.PHAM_NHAN_ID
                                     END)                                                                  AS "Khac",
                                 COUNT(DISTINCT ll.PHAM_NHAN_ID)                                           AS "TongSo"

                          FROM pham_nhan_filtered ll
                                   LEFT JOIN DM_GIOI_TINHS dgt
                                             ON ll.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
                          GROUP BY CASE
                                       WHEN ll.LL_SO_TIEN_AN IS NULL OR ll.LL_SO_TIEN_AN = 0
                                           THEN u'Ch\01b0a c\00f3 ti\1ec1n \00e1n'
                                       WHEN ll.LL_SO_TIEN_AN = 1 THEN u'C\00f3 1 ti\1ec1n \00e1n'
                                       WHEN ll.LL_SO_TIEN_AN = 2 THEN u'C\00f3 2 ti\1ec1n \00e1n'
                                       WHEN ll.LL_SO_TIEN_AN >= 3 THEN u'C\00f3 3 ti\1ec1n \00e1n tr\1edf l\00ean'
                                       END)

        SELECT "TT",
               "SoTienAn",
               "Nam",
               "Nu",
               "Khac",
               "TongSo"
        FROM (SELECT SORT_ORDER,
                     "TT",
                     "SoTienAn",
                     "Nam",
                     "Nu",
                     "Khac",
                     "TongSo"
              FROM chi_tiet
              UNION ALL
              SELECT 999,
                     TO_NCHAR(''),
                     TO_NCHAR(u'T\1ed5ng s\1ed1'),
                     SUM("Nam"),
                     SUM("Nu"),
                     SUM("Khac"),
                     SUM("TongSo")
              FROM chi_tiet)
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_THONG_KE_SO_TIEN_AN;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_TINH_CHAT_PHAM_TOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_TINH_CHAT_PHAM_TOI" (
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE DEFAULT NULL,
    p_den_trai_tu_ngay IN DATE DEFAULT NULL,
    p_den_trai_den_ngay IN DATE DEFAULT NULL,
    p_ra_trai_tu_ngay IN DATE DEFAULT NULL,
    p_ra_trai_den_ngay IN DATE DEFAULT NULL,
    p_dac_xa_tu_ngay IN DATE DEFAULT NULL,
    p_dac_xa_den_ngay IN DATE DEFAULT NULL,
    p_giam_an_tu_ngay IN DATE DEFAULT NULL,
    p_giam_an_den_ngay IN DATE DEFAULT NULL,
    p_so_tien_an_tu IN NUMBER DEFAULT NULL,
    p_so_tien_an_den IN NUMBER DEFAULT NULL,
    p_muc_an_tu IN NUMBER DEFAULT NULL,
    p_muc_an_den IN NUMBER DEFAULT NULL,
    p_tuoi_tu IN NUMBER DEFAULT NULL,
    p_tuoi_den IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_tu IN NUMBER DEFAULT NULL,
    p_tg_chap_hanh_den IN NUMBER DEFAULT NULL,
    p_tg_con_lai_tu IN NUMBER DEFAULT NULL,
    p_tg_con_lai_den IN NUMBER DEFAULT NULL,
    p_gioi_tinh_id IN NUMBER DEFAULT NULL,
    p_dan_toc_id IN NUMBER DEFAULT NULL,
    p_quoc_tich_id IN NUMBER DEFAULT NULL,
    p_nghe_nghiep_id IN NUMBER DEFAULT NULL,
    p_hoc_van_id IN NUMBER DEFAULT NULL,
    p_ton_giao_id IN NUMBER DEFAULT NULL,
    p_toi_danh_ids IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id IN NUMBER DEFAULT NULL,
    p_loai_doi_tuong_id IN NUMBER DEFAULT NULL,
    p_ghi_chu_rieng_id IN NUMBER DEFAULT NULL,
    p_phan_doi_id IN NUMBER DEFAULT NULL,
    p_nuoc_ngoai IN NUMBER DEFAULT NULL,
    p_co_benh_tat IN NUMBER DEFAULT NULL,
    p_giam_rieng IN NUMBER DEFAULT NULL,
    p_dan_toc_thieu_so IN NUMBER DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi IN NUMBER DEFAULT NULL,
    p_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_theo_ton_giao IN NUMBER DEFAULT NULL,
    p_vtn_hien_tai IN NUMBER DEFAULT NULL,
    p_khong_pham_toi_moi IN NUMBER DEFAULT NULL,
    p_co_nghe_nghiep IN NUMBER DEFAULT NULL,
    p_chung_than IN NUMBER DEFAULT NULL,
    p_da_bi_ky_luat IN NUMBER DEFAULT NULL,
    p_co_ghi_chu_dac_biet IN NUMBER DEFAULT NULL,
    p_toi_pham_anqg IN NUMBER DEFAULT NULL,
    p_da_duoc_khen_thuong IN NUMBER DEFAULT NULL,
    p_co_tien_an IN NUMBER DEFAULT NULL,
    p_con_theo_me_vao_trai IN NUMBER DEFAULT NULL,
    p_hp_bo_sung_la_tien IN NUMBER DEFAULT NULL,
    p_co_tien_su IN NUMBER DEFAULT NULL,
    p_bat_buoc_chua_benh IN NUMBER DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien IN NUMBER DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien IN NUMBER DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

	OPEN C1 FOR

    WITH
             selected_toi_danh_filter AS (
                 SELECT TRIM(REGEXP_SUBSTR(
                                 REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                 '[^,]+', 1, LEVEL)) AS ma_loc
                 FROM DUAL
                 CONNECT BY LEVEL <= REGEXP_COUNT(
                                         REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                         ',') + 1),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
             pn_base AS (
                    SELECT
                        ll.*,
                        CASE
                            WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                            WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$')
                                THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                            ELSE NULL
                        END AS SO_TIEN_AN_NUM,
                        QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
                    FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
                    INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                        ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
                       AND tt.NGAY_XET = v_ngay_tinh
                       AND tt.TTPN_MA IN ('111', '112', '113', '114')
                    WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
                      AND NVL(ll.LL_IS_DELETED, 0) = 0
                      AND NVL(ll.THA_IS_DELETED, 0) = 0
                      AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
                ),
             pham_nhan_filtered AS (
	SELECT
		ll.PHAM_NHAN_ID,
		ll.LL_DM_GIOI_TINH_ID,
		ll.LL_TAI_PHAM
	FROM
		pn_base ll
    LEFT JOIN DM_TRAI_GIAMS dtg
         ON dtg.ID = ll.LL_TRAI_GIAM_ID
         AND dtg.IS_DELETED = 0
    LEFT JOIN DM_QUOC_TICHS dqt
        ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
            AND dqt.IS_DELETED = 0
	WHERE
		ll.IS_DELETED = 0
		AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)

		-- NHÓM 1: Kho?ng ngày
		AND (p_den_trai_tu_ngay IS NULL
			OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
		AND (p_den_trai_den_ngay IS NULL
			OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
		AND (p_ra_trai_tu_ngay IS NULL
			OR ll.THA_NGAY_HET_HAN >= p_ra_trai_tu_ngay)
		AND (p_ra_trai_den_ngay IS NULL
			OR ll.THA_NGAY_HET_HAN <= p_ra_trai_den_ngay)
		AND (
                                        (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM PN_DAC_XAS dxa
                                                       WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID
                                                         AND dxa.IS_DELETED = 0
                                                         AND (p_dac_xa_tu_ngay IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                                                         AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
                                        )
		AND (
                                        (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
                                            OR EXISTS (SELECT 1
                                                       FROM GIAM_THOI_HANS gaan
                                                       WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                         AND gaan.IS_DELETED = 0
                                                         AND (p_giam_an_tu_ngay IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                                                         AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
                                        )
		-- NHÓM 2: Kho?ng s?
		AND (
                                        p_so_tien_an_tu IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu)
                                    )
                                    AND (
                                        p_so_tien_an_den IS NULL
                                        OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den)
                                    )
		AND (p_muc_an_tu IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
            AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
		AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
		AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
		AND (p_tg_chap_hanh_tu IS NULL
			OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
		AND (p_tg_chap_hanh_den IS NULL
			OR
                    ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
		AND (p_tg_con_lai_tu IS NULL
			OR
                    ll.THA_THOI_GIAN_CON_LAI >= p_tg_con_lai_tu)
		AND (p_tg_con_lai_den IS NULL
			OR
                    ll.THA_THOI_GIAN_CON_LAI <= p_tg_con_lai_den)
		-- NHÓM 3: Danh m?c
		AND (p_gioi_tinh_id IS NULL
			OR ll.LL_DM_GIOI_TINH_ID = p_gioi_tinh_id)
		AND (p_dan_toc_id IS NULL
			OR ll.LL_DM_DAN_TOC_ID = p_dan_toc_id)
		AND (p_quoc_tich_id IS NULL
			OR ll.LL_DM_QUOC_TICH_ID = p_quoc_tich_id)
		AND (p_nghe_nghiep_id IS NULL
			OR ll.LL_DM_NGHE_NGHIEP_ID = p_nghe_nghiep_id)
		AND (p_hoc_van_id IS NULL
			OR ll.LL_DM_HOC_VAN_ID = p_hoc_van_id)
		AND (p_ton_giao_id IS NULL
			OR ll.LL_DM_TON_GIAO_ID = p_ton_giao_id)
		-- [T?i danh]
		AND (
                                        p_toi_danh_ids IS NULL
                                            OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
                                            OR EXISTS (SELECT 1
                                                       FROM selected_toi_danh_filter loc
                                                       WHERE INSTR(
                                                                     ',' || REPLACE(
                                                                             REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''),
                                                                             ' ', '') || ',',
                                                                     ',' || TRIM(loc.ma_loc) || ','
                                                             ) > 0)
                                        )
		AND (p_dp_dktt_id IS NULL
			OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
		AND (p_loai_doi_tuong_id IS NULL
			OR ll.THA_DOI_TUONG = p_loai_doi_tuong_id)
		-- [Ghi chú riêng] input d?ng [123] ho?c 123 — FIX: strip [] gi?ng toi_danh
		AND (
                                        p_ghi_chu_rieng_id IS NULL
                                            OR INSTR(
                                                       ',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') ||
                                                       ',',
                                                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ','
                                               ) > 0
                                        )
		AND (p_phan_doi_id IS NULL
			OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
		-- NHÓM 4: Checkbox
		-- [N??c ngoài]
		AND (p_nuoc_ngoai IS NULL OR (
                                        CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
                                        ))
		-- [Có b?nh t?t] FIX: khôi ph?c check c? PN_SUC_KHOES
		AND (p_co_benh_tat IS NULL OR (
                                        CASE
                                            WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                                THEN 1
                                            WHEN EXISTS (
                                                SELECT 1
                                                FROM DM_BENH_TATS dbt
                                                WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                                AND dbt.IS_DELETED = 0
                                                AND dbt.BT_MA = '1'
                                            )
                                                THEN 0
                                            ELSE 1
                                        END = p_co_benh_tat
                                    ))
		-- [Giam riêng]
		AND (p_giam_rieng IS NULL
			OR (
                CASE
			WHEN EXISTS (
			SELECT
				1
			FROM
				PN_GIAM_RIENGS gr
			WHERE
				gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
				AND gr.IS_DELETED = 0
                ) THEN 1
			ELSE 0
		END = p_giam_rieng
            ))
		-- [Dân t?c thi?u s?]
		AND (
								    p_dan_toc_thieu_so IS NULL
								    OR (
								        CASE
								            WHEN EXISTS (
								                SELECT 1
								                FROM DM_DAN_TOCS dt
								                WHERE dt.ID = ll.LL_DM_DAN_TOC_ID
								                  AND dt.IS_DELETED = 0
								                  AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
								            )
								            THEN 1
								            ELSE 0
								        END = p_dan_toc_thieu_so
								    )
								)
		-- [VTN t?i th?i ?i?m ph?m t?i]
		AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
                                        CASE
                                            WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_thoi_diem_pham_toi
                                        ))
		-- [Ph?m t?i m?i]
		AND (p_pham_toi_moi IS NULL
			OR (
                CASE
			WHEN EXISTS (
			SELECT
				1
			FROM
				PHAM_TOI_MOIS ptm
			WHERE
				ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
				AND ptm.IS_DELETED = 0
                ) THEN 1
			ELSE 0
		END = p_pham_toi_moi
            ))
		-- [Theo tôn giáo]
		AND (p_theo_ton_giao IS NULL OR (
								        CASE
								            WHEN EXISTS (
								                SELECT 1
								                FROM DM_TON_GIAOS tg
								                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID
								                  AND tg.IS_DELETED = 0

								            )
								            THEN 1
								            ELSE 0
								        END = p_theo_ton_giao ))
		-- [VTN t?i th?i ?i?m hi?n t?i]
		AND (p_vtn_hien_tai IS NULL OR (
                                        CASE
                                            WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                                            WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                                            ELSE 0
                                            END = p_vtn_hien_tai
                                        ))
		-- [Không ph?m t?i m?i]
		AND (p_khong_pham_toi_moi IS NULL
			OR (
                CASE
			WHEN NOT EXISTS (
			SELECT
				1
			FROM
				PHAM_TOI_MOIS ptm
			WHERE
				ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
				AND ptm.IS_DELETED = 0
                ) THEN 1
			ELSE 0
		END = p_khong_pham_toi_moi
            ))
		-- [Có ngh? nghi?p]
		AND (
    p_co_nghe_nghiep IS NULL
    OR (
        CASE
            WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                 AND EXISTS (
                        SELECT 1
                        FROM DM_NGHE_NGHIEPS dnn
                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID
                          AND dnn.IS_DELETED = 0
                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%')
                 )
            THEN 1
            ELSE 0
        END = p_co_nghe_nghiep
    )
)
		-- [Chung thân]
		AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
		-- [?ã b? k? lu?t]
		AND (p_da_bi_ky_luat IS NULL
			OR (
                CASE
			WHEN EXISTS (
			SELECT
				1
			FROM
				KY_LUATS kl
			WHERE
				kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                ) THEN 1
			ELSE 0
		END = p_da_bi_ky_luat
            ))
		-- [Có ghi chú ??c bi?t] FIX: OR ? AND
		AND (p_co_ghi_chu_dac_biet IS NULL
			OR (
                CASE
			WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
				AND ll.THA_GHI_CHU_DAC_BIET <> '[]'
                     THEN 1
				ELSE 0
			END = p_co_ghi_chu_dac_biet
            ))
		-- [T?i ph?m ANQG] FIX: guard THA_TOI_DANH không r?ng
		AND (p_toi_pham_anqg IS NULL OR (
                                          CASE WHEN EXISTS (
                                              SELECT 1 FROM DM_TOI_DANHS td
                                              WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                                                AND td.IS_DELETED = 0
                                                AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
                                          ) THEN 1 ELSE 0 END = p_toi_pham_anqg
                                      ))
		-- [?ã ???c khen th??ng]
		AND (p_da_duoc_khen_thuong IS NULL
			OR (
                CASE
			WHEN EXISTS (
			SELECT
				1
			FROM
				KHEN_THUONGS kt
			WHERE
				kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
				AND kt.IS_DELETED = 0
                ) THEN 1
			ELSE 0
		END = p_da_duoc_khen_thuong
            ))
		-- [Có ti?n án]
		AND (p_co_tien_an IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_an
                                        ))
                                      AND (p_co_tien_su IS NULL OR (
                                        CASE
                                            WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0'
                                                THEN 1
                                            ELSE 0 END = p_co_tien_su
                                        ))
		-- [Con theo m? vào tr?i]
		AND (p_con_theo_me_vao_trai IS NULL
			OR (
                CASE
			WHEN EXISTS (
			SELECT
				1
			FROM
				THAN_NHAN_CON_CAIS tncc
			WHERE
				tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
				AND tncc.IS_DELETED = 0
                ) THEN 1
			ELSE 0
		END = p_con_theo_me_vao_trai
            ))
		-- [Hình ph?t b? sung là ti?n]
		AND (p_hp_bo_sung_la_tien IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                                                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                                                            ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                                                                AND dhpbs.IS_DELETED = 0
                                                         WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                                           AND hpbs.IS_DELETED = 0
                                                           AND dhpbs.HPBS_LOAI_HPBS = 'HPBST') THEN 1
                                            ELSE 0 END = p_hp_bo_sung_la_tien
                                        ))
		-- [B?t bu?c ch?a b?nh]
		AND (p_bat_buoc_chua_benh IS NULL OR (
                                        CASE
                                            WHEN EXISTS (SELECT 1
                                                         FROM CHUA_BENH_BAT_BUOCS cb
                                                         WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID
                                                           	AND cb.IS_DELETED = 0
                                                           	-- AND TRUNC(cb.TU_NGAY) <= TRUNC(v_ngay_tinh)
                                                  			-- AND (cb.NGAY_KET_THUC IS NULL OR TRUNC(cb.NGAY_KET_THUC) >= TRUNC(v_ngay_tinh))
                                                           ) THEN 1
                                            ELSE 0 END = p_bat_buoc_chua_benh
                                        ))
		-- [Hoàn xong HPBS là ti?n]
		AND (
                        p_hoan_xong_hpbs_la_tien IS NULL OR
                        (CASE
                                WHEN EXISTS (
                                    SELECT 1
                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
                                     AND dhpbs.IS_DELETED = 0
                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                                      AND hpbs.IS_DELETED = 0
                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
                                ) THEN 1
                                ELSE 0
                            END = p_hoan_xong_hpbs_la_tien))
		-- [Ch?a hoàn xong HPBS là ti?n]
		AND (p_chua_hoan_hpbs_la_tien IS NULL OR
	                        ( CASE
	                                WHEN EXISTS (
	                                    SELECT 1
	                                    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
	                                    LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
	                                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT
	                                     AND dhpbs.IS_DELETED = 0
	                                    WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
	                                      AND hpbs.IS_DELETED = 0
	                                      AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
	                                    GROUP BY hpbs.HPBS_MA_PHAM_NHAN
	                                    HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
	                                ) THEN 1
	                                ELSE 0
	                            END = p_chua_hoan_hpbs_la_tien))
    ),
	chi_tiet AS (
	SELECT
				ROW_NUMBER() OVER (
				ORDER BY NVL(dtp.TP_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')
	            ) AS SORT_ORDER,
					TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY
	                 NVL(dtp.TP_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')
	            ))) AS "TT",
					 NVL(dtp.TP_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh') AS "TinhChatToiPham",
					 COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN ll.PHAM_NHAN_ID END) AS "Nam",
					COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN ll.PHAM_NHAN_ID END) AS "Nu",
					 COUNT(DISTINCT CASE
									  WHEN dgt.GT_TEN IS NULL OR dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
									  THEN ll.PHAM_NHAN_ID
									END) AS "Khac",
					 COUNT(DISTINCT ll.PHAM_NHAN_ID) AS "TongSo"
	FROM
					pham_nhan_filtered ll
	LEFT JOIN DM_GIOI_TINHS dgt
				    ON
					ll.LL_DM_GIOI_TINH_ID = dgt.ID
		AND dgt.IS_DELETED = 0
	LEFT JOIN DM_TAI_PHAMS dtp
				    ON
					ll.LL_TAI_PHAM = dtp.ID
		AND dtp.IS_DELETED = 0
	GROUP BY
					NVL(dtp.TP_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')
	    )

    SELECT
	"TT",
	"TinhChatToiPham",
	"Nam",
	"Nu",
	"Khac",
	"TongSo"
FROM
	(
	SELECT
		SORT_ORDER,
		"TT",
		"TinhChatToiPham",
		"Nam",
		"Nu",
		"Khac",
		"TongSo"
	FROM
		chi_tiet
UNION ALL
	SELECT
		999,
		TO_NCHAR(''),
		TO_NCHAR(u'T\1ed5ng s\1ed1'),
		SUM("Nam"),
		SUM("Nu"),
		SUM("Khac"),
		SUM("TongSo")
	FROM
		chi_tiet
    )
ORDER BY
	SORT_ORDER;

DBMS_SQL.RETURN_RESULT(C1);
END SP_THONG_KE_TINH_CHAT_PHAM_TOI;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_TONG_HOP_BENH_HIEM_NGHEO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_TONG_HOP_BENH_HIEM_NGHEO" (
    p_tu_ngay IN DATE,
    p_den_ngay IN DATE,
    p_trai_giam_id IN NVARCHAR2
)
AS
    C1         SYS_REFCURSOR;
    v_tu_ngay  DATE;
    v_den_ngay DATE;
BEGIN
    -- ===== Normalize params =====
    -- Ngày t?
    IF EXTRACT(DAY FROM p_tu_ngay) < 15 THEN
        v_tu_ngay := TRUNC(ADD_MONTHS(p_tu_ngay, -1), 'MM') + 14; -- ngày 15 tháng tr??c
    ELSE
        v_tu_ngay := TRUNC(p_tu_ngay, 'MM') + 14; -- ngày 15 tháng hi?n t?i
    END IF;

    -- Ngày ??n
    IF EXTRACT(DAY FROM p_den_ngay) > 14 THEN
        v_den_ngay := TRUNC(ADD_MONTHS(p_den_ngay, 1), 'MM') + 13; -- ngày 14 tháng sau
    ELSE
        v_den_ngay := TRUNC(p_den_ngay, 'MM') + 13; -- ngày 14 tháng hi?n t?i
    END IF;

    OPEN C1 FOR
        WITH pham_nhan_filtered AS (SELECT ll.ID AS pham_nhan_id,
                                           ll.LL_DM_GIOI_TINH_ID,
                                           ll.LL_DM_HOC_VAN_ID,
                                           ll.LL_DM_NGHE_NGHIEP_ID,
                                           ll.LL_SO_TIEN_AN,
                                           ll.LL_SO_TIEN_SU,
                                           ll.LL_BENH_HIEN_TAI,
                                           ll.CREATION_TIME,
                                           ptha.THA_THOI_GIAN_DA_CHAP_HANH,
                                           ptha.THA_THOI_GIAN_CON_LAI
                                    FROM PN_LAI_LICHS ll
                                             LEFT JOIN DM_TRAI_GIAMS dtg
                                                       ON dtg.ID = ll.LL_TRAI_GIAM_ID
                                                           AND dtg.IS_DELETED = 0

                                             LEFT JOIN PN_THI_HANH_AN ptha
                                                       ON ptha.THA_PNLAI_LICH_ID = ll.ID
                                                           AND ptha.IS_DELETED = 0
                                    --LEFT JOIN PN_DAC_XAS dxa ON  dxa.PNLAI_LICH_ID = ll.ID AND dxa.IS_DELETED    = 0
                                    --LEFT JOIN GIAM_THOI_HANS gaan ON  gaan.PHAM_NHAN_ID = ll.ID AND gaan.IS_DELETED   = 0
                                    WHERE ll.IS_DELETED = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
                                      AND (p_trai_giam_id IS NULL OR dtg.TG_MA = p_trai_giam_id)
                                      AND (ptha.THA_NGAY_DEN_TRAI >= v_tu_ngay OR v_tu_ngay IS NULL)
                                      AND (ptha.THA_NGAY_DEN_TRAI <= v_den_ngay OR v_den_ngay IS NULL)),

             chi_tiet AS (SELECT ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC )                              AS SORT_ORDER,
                                 TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY COUNT(*) DESC )))           AS "TT",
                                 pn.LL_BENH_HIEN_TAI                                                      AS BENH,
                                 COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'Nam' THEN pn.PHAM_NHAN_ID END)    AS Nam,
                                 COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'N\1eef' THEN pn.PHAM_NHAN_ID END) AS Nu,
                                 COUNT(DISTINCT CASE
                                                    WHEN NVL(gt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef')
                                                        THEN pn.PHAM_NHAN_ID END)                         AS Khac,
                                 COUNT(DISTINCT pn.PHAM_NHAN_ID)                                          AS TONG_CONG
                          FROM pham_nhan_filtered pn
                                   LEFT JOIN DM_TRUONG_HOP_CHETS dbt
                                             ON dbt.ID = pn.LL_BENH_HIEN_TAI
                                                 AND NVL(dbt.IS_DELETED, 0) = 0
                                   LEFT JOIN DM_GIOI_TINHS gt
                                             ON gt.ID = pn.LL_DM_GIOI_TINH_ID
                                                 AND NVL(gt.IS_DELETED, 0) = 0
                          GROUP BY pn.LL_BENH_HIEN_TAI)

        SELECT "TT",
               BENH,
               Nam,
               Nu,
               Khac,
               TONG_CONG
        FROM (SELECT SORT_ORDER,
                     "TT",
                     BENH,
                     NAM,
                     NU,
                     KHAC,
                     TONG_CONG
              FROM chi_tiet

              UNION ALL

              SELECT 999,
                     TO_NCHAR(''),
                     TO_NCHAR(u'T\1ed5ng s\1ed1'),
                     SUM(Nam),
                     SUM(Nu),
                     SUM(Khac),
                     SUM(TONG_CONG)
              FROM chi_tiet)
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_TONG_HOP_BENH_HIEM_NGHEO;
/

/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_TONG_HOP_BIEN_DONG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_TONG_HOP_BIEN_DONG" (
    p_tu_ngay IN DATE,
    p_den_ngay IN DATE,
    p_trai_giam_id IN NVARCHAR2
)
AS
    p_result       SYS_REFCURSOR;
    v_tu_ngay      DATE;
    v_den_ngay     DATE;
    v_trai_giam_id NUMBER;
BEGIN
    -- ===== Normalize =====
    -- Tr?i giam
    IF p_trai_giam_id IS NOT NULL THEN
        SELECT MIN(ID)
        INTO v_trai_giam_id
        FROM DM_TRAI_GIAMS
        WHERE TG_MA = p_trai_giam_id;
    ELSE
        v_trai_giam_id := NULL;
    END IF;

    IF EXTRACT(DAY FROM p_tu_ngay) < 15 THEN
        v_tu_ngay := TRUNC(ADD_MONTHS(p_tu_ngay, -1), 'MM') + 14; -- ngày 15 tháng tr??c
    ELSE
        v_tu_ngay := TRUNC(p_tu_ngay, 'MM') + 14; -- ngày 15 tháng hi?n t?i
    END IF;

    -- Ngày ??n
    IF EXTRACT(DAY FROM p_den_ngay) > 14 THEN
        v_den_ngay := TRUNC(ADD_MONTHS(p_den_ngay, 1), 'MM') + 13; -- ngày 14 tháng sau
    ELSE
        v_den_ngay := TRUNC(p_den_ngay, 'MM') + 13; -- ngày 14 tháng hi?n t?i
    END IF;
    -- ===== M? CURSOR TR? K?T QU? =====
    OPEN p_result FOR
        WITH q1 AS (SELECT u'S\1ed1 k\1ef3 tr\01b0\1edbc chuy\1ec3n sang'                                  AS TITLE,
                           COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN pll.ID END)                   AS NAM,
                           COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN pll.ID END)                AS NU,
                           COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN pll.ID END) AS KHAC,
                           COUNT(DISTINCT pll.ID)                                                          AS TONG_CONG
                    FROM PN_LAI_LICHS pll
                             JOIN DM_TINH_TRANG_PHAM_NHANS tt ON pll.LL_TINH_TRANG_ID = tt.ID
                             LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                    WHERE tt.TTPN_TEN NOT IN (
                                              'Ch?t', 'Tha tr??c th?i h?n có ?i?u ki?n', 'Trích xu?t tr?n',
                                              'Trích xu?t h?y án', 'Hoãn thi hành án', 'Trích xu?t gi?m tha',
                                              'T?m ?ình ch? tr?n', 'Chuy?n giao thi hành án', 'Gi?m h?t án',
                                              '???c ??c xá', 'T?m ?ình ch? ??c xá', 'Hu? án',
                                              'T?m ?ình ch? chuy?n tr?i', 'B?t bu?c ch?a b?nh h?t án',
                                              'Tr?n tr?i truy nã', 'T?m ?ình ch? ???c mi?n', 'T?m ?ình ch? ch?t',
                                              'Trích xu?t h?t án', 'Tr?n tr?i', 'Chuy?n tr?i khác', 'Tr?n tr?i ch?t',
                                              'Trích xu?t ch?t', 'K?t thúc h? s?', 'Trích xu?t chuy?n tr?i',
                                              'Ch?p hành xong hình ph?t tù', 'Trích xu?t ??c xá', 'Mi?n hình ph?t'
                        )
                      AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                      AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q2_1 AS (SELECT u'Tr\1ea1i t\1ea1m giam kh\00e1c chuy\1ec3n \0111\1ebfn'                     AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN pnct.PNCT_LAI_LICH_ID END) AS NAM,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN = u'N\1eef'
                                                    THEN pnct.PNCT_LAI_LICH_ID END)                       AS NU,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                    THEN pnct.PNCT_LAI_LICH_ID END)                       AS KHAC,
                             COUNT(DISTINCT pnct.PNCT_LAI_LICH_ID)                                        AS TONG_CONG
                      FROM PHAM_NHAN_CHUYEN_TRAI pnct
                               JOIN PN_LAI_LICHS pll ON pll.ID = pnct.PNCT_LAI_LICH_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                               JOIN DM_TRAI_GIAMS dtg ON pnct.PNCT_TRAI_DEN_ID = dtg.ID
                      WHERE pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay
                        AND pnct.IS_DELETED = 0
                        AND pnct.PNCT_NGAY_CHUYEN < v_den_ngay
                        AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI > v_den_ngay)
                        AND UPPER(dtg.TG_TEN) LIKE '%T?M%'
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q2_2 AS (SELECT u'Tr\1ea1i giam kh\00e1c chuy\1ec3n \0111\1ebfn'                             AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN pnct.PNCT_LAI_LICH_ID END) AS NAM,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN = u'N\1eef'
                                                    THEN pnct.PNCT_LAI_LICH_ID END)                       AS NU,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                    THEN pnct.PNCT_LAI_LICH_ID END)                       AS KHAC,
                             COUNT(DISTINCT pnct.PNCT_LAI_LICH_ID)                                        AS TONG_CONG
                      FROM PHAM_NHAN_CHUYEN_TRAI pnct
                               JOIN PN_LAI_LICHS pll ON pll.ID = pnct.PNCT_LAI_LICH_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                               JOIN DM_TRAI_GIAMS dtg ON pnct.PNCT_TRAI_DEN_ID = dtg.ID
                      WHERE pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay
                        AND pnct.PNCT_NGAY_CHUYEN < v_den_ngay
                        AND pnct.IS_DELETED = 0
                        AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI > v_den_ngay)
                        AND UPPER(dtg.TG_TEN) LIKE '%TR?I GIAM%'
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q2_3 AS (SELECT u'Tr\1ed1n b\1eaft l\1ea1'                                                AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tt.PHAM_NHAN_ID END)    AS NAM,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tt.PHAM_NHAN_ID END) AS NU,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                    THEN tt.PHAM_NHAN_ID END)                          AS KHAC,
                             COUNT(DISTINCT tt.PHAM_NHAN_ID)                                           AS TONG_CONG
                      FROM TRON_TRAIS tt
                               JOIN PN_LAI_LICHS pll ON pll.ID = tt.PHAM_NHAN_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                      WHERE tt.NGAY_BAT_LAI >= v_tu_ngay
                        AND tt.NGAY_BAT_LAI < v_den_ngay
                        AND tt.IS_DELETED = 0
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q2_4 AS (SELECT u'T\1ea1m \0111\00ecnh ch\1ec9 tr\1edf l\1ea1i'                            AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tdc.PHAM_NHAN_ID END)    AS NAM,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tdc.PHAM_NHAN_ID END) AS NU,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                    THEN tdc.PHAM_NHAN_ID END)                          AS KHAC,
                             COUNT(DISTINCT tdc.PHAM_NHAN_ID)                                           AS TONG_CONG
                      FROM TAM_DINH_CHIS tdc
                               JOIN PN_LAI_LICHS pll ON pll.ID = tdc.PHAM_NHAN_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                      WHERE tdc.NGAY_LAI >= v_tu_ngay
                        AND tdc.NGAY_LAI < v_den_ngay
                        AND tdc.IS_DELETED = 0
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q2_5 AS (SELECT u'Tr\00edch xu\1ea5t tr\1ea3 l\1ea1i'                                     AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tx.PHAM_NHAN_ID END)    AS NAM,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tx.PHAM_NHAN_ID END) AS NU,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                    THEN tx.PHAM_NHAN_ID END)                          AS KHAC,
                             COUNT(DISTINCT tx.PHAM_NHAN_ID)                                           AS TONG_CONG
                      FROM TRICH_XUATS tx
                               JOIN PN_LAI_LICHS pll ON pll.ID = tx.PHAM_NHAN_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                      WHERE tx.TX_NGAY_TRA >= v_tu_ngay
                        AND tx.TX_NGAY_TRA < v_den_ngay
                        AND tx.IS_DELETED = 0
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q2_6
                 AS (SELECT u'Tha tr\01b0\1edbc th\1eddi h\1ea1n c\00f3 \0111i\1ec1u ki\1ec7n tr\1edf l\1ea1i' AS TITLE,
                            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tcdk.PHAM_NHAN_ID END)           AS NAM,
                            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tcdk.PHAM_NHAN_ID END)        AS NU,
                            COUNT(DISTINCT CASE
                                               WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                   THEN tcdk.PHAM_NHAN_ID END)                                 AS KHAC,
                            COUNT(DISTINCT tcdk.PHAM_NHAN_ID)                                                  AS TONG_CONG
                     FROM THA_CO_DIEU_KIENS tcdk
                              JOIN PN_LAI_LICHS pll ON pll.ID = tcdk.PHAM_NHAN_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                              LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                     WHERE tcdk.NGAY_BAT_LAI >= v_tu_ngay
                       AND tcdk.NGAY_BAT_LAI < v_den_ngay
                       AND tcdk.IS_DELETED = 0
                       AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q2_7 AS (SELECT u'Chuy\1ec3n giao t\1eeb n\01b0\1edbc ngo\00e0i v\1ec1 thi h\00e0nh \00e1n'   AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN cg.PNCG_LAI_LICH_ID END)    AS NAM,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN cg.PNCG_LAI_LICH_ID END) AS NU,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                    THEN cg.PNCG_LAI_LICH_ID END)                          AS KHAC,
                             COUNT(DISTINCT cg.PNCG_LAI_LICH_ID)                                           AS TONG_CONG
                      FROM PN_CHUYEN_GIAO cg
                               JOIN PN_LAI_LICHS pll ON pll.ID = cg.PNCG_LAI_LICH_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                      WHERE cg.PNCG_NGAY_QDTHQDCG >= v_tu_ngay
                        AND cg.PNCG_NGAY_QDTHQDCG < v_den_ngay
                        AND cg.IS_DELETED = 0
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q2_8 AS (SELECT u'B\1eaft bu\1ed9c ch\1eefa b\1ec7nh tr\1edf l\1ea1i tr\1ea1i'              AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN cbbb.PHAM_NHAN_ID END)    AS NAM,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN cbbb.PHAM_NHAN_ID END) AS NU,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                    THEN cbbb.PHAM_NHAN_ID END)                          AS KHAC,
                             COUNT(DISTINCT cbbb.PHAM_NHAN_ID)                                           AS TONG_CONG
                      FROM CHUA_BENH_BAT_BUOCS cbbb
                               JOIN PN_LAI_LICHS pll ON pll.ID = cbbb.PHAM_NHAN_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                      WHERE CBBB.NGAY_KET_THUC >= v_tu_ngay
                        AND CBBB.NGAY_KET_THUC < v_den_ngay
                        AND CBBB.IS_DELETED = 0
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q2_all AS (SELECT u'T\1ed5ng t\0103ng'                                                             AS TITLE,
                               COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN u.PN_ID END)                   AS NAM,
                               COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN u.PN_ID END)                AS NU,
                               COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN u.PN_ID END) AS KHAC,
                               COUNT(DISTINCT u.PN_ID)                                                          AS TONG_CONG
                        FROM (SELECT pnct.PNCT_LAI_LICH_ID AS PN_ID
                              FROM PHAM_NHAN_CHUYEN_TRAI pnct
                                       JOIN DM_TRAI_GIAMS dtg ON pnct.PNCT_TRAI_DEN_ID = dtg.ID
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = pnct.PNCT_LAI_LICH_ID
                              WHERE pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay
                                AND pnct.PNCT_NGAY_CHUYEN < v_den_ngay
                                AND pnct.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI > v_den_ngay)
                                AND UPPER(dtg.TG_TEN) LIKE '%T?M%'
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT pnct.PNCT_LAI_LICH_ID
                              FROM PHAM_NHAN_CHUYEN_TRAI pnct
                                       JOIN DM_TRAI_GIAMS dtg ON pnct.PNCT_TRAI_DEN_ID = dtg.ID
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = pnct.PNCT_LAI_LICH_ID
                              WHERE pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay
                                AND pnct.PNCT_NGAY_CHUYEN < v_den_ngay
                                AND pnct.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI > v_den_ngay)
                                AND UPPER(dtg.TG_TEN) LIKE '%TR?I GIAM%'
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT tt.PHAM_NHAN_ID
                              FROM TRON_TRAIS tt
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = tt.PHAM_NHAN_ID
                              WHERE tt.NGAY_BAT_LAI >= v_tu_ngay
                                AND tt.NGAY_BAT_LAI < v_den_ngay
                                AND tt.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT tdc.PHAM_NHAN_ID
                              FROM TAM_DINH_CHIS tdc
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = tdc.PHAM_NHAN_ID
                              WHERE tdc.NGAY_LAI >= v_tu_ngay
                                AND tdc.NGAY_LAI < v_den_ngay
                                AND tdc.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT tx.PHAM_NHAN_ID
                              FROM TRICH_XUATS tx
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = tx.PHAM_NHAN_ID
                              WHERE tx.TX_NGAY_TRA >= v_tu_ngay
                                AND tx.TX_NGAY_TRA < v_den_ngay
                                AND tx.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT tcdk.PHAM_NHAN_ID
                              FROM THA_CO_DIEU_KIENS tcdk
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = tcdk.PHAM_NHAN_ID
                              WHERE tcdk.NGAY_BAT_LAI >= v_tu_ngay
                                AND tcdk.NGAY_BAT_LAI < v_den_ngay
                                AND tcdk.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)) u
                                 JOIN PN_LAI_LICHS pll ON pll.ID = u.PN_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                                 LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID),
             q3_1 AS (SELECT u'H\1ebft th\1eddi h\1ea1n CHHPT, tr\1ea3 t\1ef1 do'                                AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN pktrt.KTRT_PN_LAI_LICH_ID END)    AS NAM,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN pktrt.KTRT_PN_LAI_LICH_ID END) AS NU,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                    THEN PKTRT.KTRT_PN_LAI_LICH_ID END)                          AS KHAC,
                             COUNT(DISTINCT pktrt.KTRT_PN_LAI_LICH_ID)                                           AS TONG_CONG
                      FROM PN_KET_THUC_RA_TRAIS pktrt
                               JOIN PN_LAI_LICHS pll ON pll.ID = pktrt.KTRT_PN_LAI_LICH_ID
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
                      WHERE pktrt.IS_DELETED = 0
                        AND pktrt.KTRT_NGAY_THA >= v_tu_ngay
                        AND pktrt.KTRT_NGAY_THA < v_den_ngay
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q3_2 AS (SELECT u'\0110\01b0\1ee3c gi\1ea3m th\1eddi h\1ea1n CHHPT, tr\1ea3 t\1ef1 do'     AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN gth.PHAM_NHAN_ID END)    AS NAM,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN gth.PHAM_NHAN_ID END) AS NU,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                    THEN gth.PHAM_NHAN_ID END)                          AS KHAC,
                             COUNT(DISTINCT gth.PHAM_NHAN_ID)                                           AS TONG_CONG
                      FROM GIAM_THOI_HANS gth
                               JOIN PN_LAI_LICHS pll ON pll.ID = gth.PHAM_NHAN_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
                               JOIN PN_THI_HANH_AN ptha ON pll.ID = ptha.THA_PNLAI_LICH_ID AND ptha.IS_DELETED = 0
                               JOIN PN_KET_THUC_RA_TRAIS pktrt
                                    ON PKTRT.KTRT_PN_LAI_LICH_ID = pll.ID AND PKTRT.IS_DELETED = 0
                      WHERE gth.MUC_GIAM_ID NOT IN (SELECT ID
                                                    FROM DM_MA_THOI_GIANS
                                                    WHERE MTG_MA IN ('924000', '923000', '926000', '000000', '927000'))
                        AND gth.IS_DELETED = 0
                        AND pktrt.KTRT_NGAY_THA >= v_tu_ngay
                        AND pktrt.KTRT_NGAY_THA < v_den_ngay
                        AND MUC_GIAM_ID IS NOT NULL
                        AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q3_3 AS (SELECT u'\0110\01b0\1ee3c gi\1ea3m h\1ebft th\1eddi h\1ea1n CHHPT, tr\1ea3 t\1ef1 do' AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN gth.PHAM_NHAN_ID END)        AS NAM,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN gth.PHAM_NHAN_ID END)     AS NU,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                    THEN gth.PHAM_NHAN_ID END)                              AS KHAC,
                             COUNT(DISTINCT gth.PHAM_NHAN_ID)                                               AS TONG_CONG
                      FROM GIAM_THOI_HANS gth
                               JOIN PN_LAI_LICHS pll ON pll.ID = gth.PHAM_NHAN_ID
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
                      WHERE gth.NGAY_THA_GIAM_HET_AN >= v_tu_ngay
                        AND gth.NGAY_THA_GIAM_HET_AN < v_den_ngay
                        AND gth.IS_DELETED = 0
                        AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q3_4 AS (SELECT u'Tha t\00f9 tr\01b0\1edbc th\1eddi h\1ea1n c\00f3 \0111i\1ec1u ki\1ec7n'   AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tcdk.PHAM_NHAN_ID END)    AS NAM,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tcdk.PHAM_NHAN_ID END) AS NU,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                    THEN tcdk.PHAM_NHAN_ID END)                          AS KHAC,
                             COUNT(DISTINCT tcdk.PHAM_NHAN_ID)                                           AS TONG_CONG
                      FROM THA_CO_DIEU_KIENS tcdk
                               JOIN PN_LAI_LICHS pll ON pll.ID = tcdk.PHAM_NHAN_ID
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
                      WHERE tcdk.NGAY_THA >= v_tu_ngay
                        AND tcdk.NGAY_THA < v_den_ngay
                        AND tcdk.IS_DELETED = 0
                        AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                        AND (tcdk.NGAY_BAT_LAI IS NULL OR tcdk.NGAY_BAT_LAI >= v_den_ngay)
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q3_5 AS (SELECT u'\0110\01b0\1ee3c \0111\1eb7c x\00e1'                                           AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN u.PN_ID END)                   AS NAM,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN u.PN_ID END)                AS NU,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN u.PN_ID END) AS KHAC,
                             COUNT(DISTINCT u.PN_ID)                                                          AS TONG_CONG
                      FROM (SELECT pdx.PNLAI_LICH_ID AS PN_ID
                            FROM PN_DAC_XAS pdx
                                     JOIN PN_LAI_LICHS pll2 ON pll2.ID = pdx.PNLAI_LICH_ID
                            WHERE pdx.DX_NGAY_THA >= v_tu_ngay
                              AND pdx.DX_NGAY_THA < v_den_ngay
                              AND pdx.IS_DELETED = 0
                              AND pll2.IS_DELETED = 0
                              AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)) u
                               JOIN PN_LAI_LICHS pll ON pll.ID = u.PN_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID),
             q3_6 AS (SELECT u'Tr\1ed1n'                                                               AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tt.PHAM_NHAN_ID END)    AS NAM,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tt.PHAM_NHAN_ID END) AS NU,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                    THEN tt.PHAM_NHAN_ID END)                          AS KHAC,
                             COUNT(DISTINCT tt.PHAM_NHAN_ID)                                           AS TONG_CONG
                      FROM TRON_TRAIS tt
                               JOIN PN_LAI_LICHS pll ON pll.ID = tt.PHAM_NHAN_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                      WHERE tt.NGAY_TRON >= v_tu_ngay
                        AND tt.NGAY_TRON < v_den_ngay
                        AND tt.IS_DELETED = 0
                        AND (tt.NGAY_BAT_LAI IS NULL OR tt.NGAY_BAT_LAI >= v_den_ngay)
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q3_7 AS (SELECT u'Ch\1ebft'                                                                       AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN pktc.KTC_PN_LAI_LICH_ID END)    AS NAM,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN pktc.KTC_PN_LAI_LICH_ID END) AS NU,
                             COUNT(DISTINCT
                                   CASE
                                       WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                           THEN pktc.KTC_PN_LAI_LICH_ID END)                                   AS KHAC,
                             COUNT(DISTINCT pktc.KTC_PN_LAI_LICH_ID)                                           AS TONG_CONG
                      FROM PN_KET_THUC_CHETS pktc
                               JOIN PN_LAI_LICHS pll ON pll.ID = pktc.KTC_PN_LAI_LICH_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                      WHERE pktc.KTC_NGAY_CHET >= v_tu_ngay
                        AND pktc.KTC_NGAY_CHET < v_den_ngay
                        AND pktc.IS_DELETED = 0
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q3_8 AS (SELECT u'Tr\00edch xu\1ea5t'                                                     AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tx.PHAM_NHAN_ID END)    AS NAM,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tx.PHAM_NHAN_ID END) AS NU,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                    THEN tx.PHAM_NHAN_ID END)                          AS KHAC,
                             COUNT(DISTINCT tx.PHAM_NHAN_ID)                                           AS TONG_CONG
                      FROM TRICH_XUATS tx
                               JOIN PN_LAI_LICHS pll ON pll.ID = tx.PHAM_NHAN_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                      WHERE tx.TX_TU_NGAY >= v_tu_ngay
                        AND tx.TX_TU_NGAY < v_den_ngay
                        AND tx.IS_DELETED = 0
                        AND (tx.TX_NGAY_TRA IS NULL OR tx.TX_NGAY_TRA > v_den_ngay)
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id))
                ,
             q3_9 AS (SELECT u'T\1ea1m \0111\00ecnh ch\1ec9'                                            AS TITLE,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tdc.PHAM_NHAN_ID END)    AS NAM,
                             COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tdc.PHAM_NHAN_ID END) AS NU,
                             COUNT(DISTINCT CASE
                                                WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                    THEN tdc.PHAM_NHAN_ID END)                          AS KHAC,
                             COUNT(DISTINCT tdc.PHAM_NHAN_ID)                                           AS TONG_CONG
                      FROM TAM_DINH_CHIS tdc
                               JOIN PN_LAI_LICHS pll ON pll.ID = tdc.PHAM_NHAN_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                               LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                      WHERE tdc.TU_NGAY >= v_tu_ngay
                        AND tdc.TU_NGAY < v_den_ngay
                        AND tdc.IS_DELETED = 0
                        AND (tdc.NGAY_LAI IS NULL OR tdc.NGAY_LAI > v_den_ngay)
                        AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q3_10 AS (SELECT u'Chuy\1ec3n tr\1ea1i kh\00e1c'                                              AS TITLE,
                              COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN pnct.PNCT_LAI_LICH_ID END) AS NAM,
                              COUNT(DISTINCT CASE
                                                 WHEN dgt.GT_TEN = u'N\1eef'
                                                     THEN pnct.PNCT_LAI_LICH_ID END)                       AS NU,
                              COUNT(DISTINCT CASE
                                                 WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                     THEN pnct.PNCT_LAI_LICH_ID END)                       AS KHAC,
                              COUNT(DISTINCT pnct.PNCT_LAI_LICH_ID)                                        AS TONG_CONG
                       FROM PHAM_NHAN_CHUYEN_TRAI pnct
                                JOIN VW_PN_LAI_LICH_CHI_TIET vw ON pnct.PNCT_LAI_LICH_ID = vw.PHAM_NHAN_ID
                                JOIN PN_LAI_LICHS pll ON pll.ID = pnct.PNCT_LAI_LICH_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                                LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                       WHERE pnct.PNCT_TRAI_DEN_ID <> vw.TRAI_GIAM_ID
                         AND pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay
                         AND pnct.PNCT_NGAY_CHUYEN < v_den_ngay
                         AND pnct.IS_DELETED = 0
                         AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI >= v_den_ngay)
                         AND (v_trai_giam_id IS NULL OR vw.TRAI_GIAM_ID = v_trai_giam_id)),
             q3_11 AS (SELECT u'H\1ee7y \00e1n'                                                               AS TITLE,
                              COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN ha.PHAM_NHAN_ID END)          AS NAM,
                              COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN ha.PHAM_NHAN_ID END)       AS NU,
                              COUNT(DISTINCT
                                    CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN ha.PHAM_NHAN_ID END) AS KHAC,
                              COUNT(DISTINCT ha.PHAM_NHAN_ID)                                                 AS TONG_CONG
                       FROM HUY_ANS ha
                                JOIN PN_LAI_LICHS pll ON pll.ID = ha.PHAM_NHAN_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                                LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                       WHERE (ha.NGAY_TRO_LAI IS NOT NULL AND ha.NGAY_TRO_LAI >= v_tu_ngay AND
                              ha.NGAY_TRO_LAI < v_den_ngay)
                         AND ha.IS_DELETED = 0
                         AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q3_12 AS (SELECT u'Ho\00e3n thi h\00e0nh \00e1n'                                             AS TITLE,
                              COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN htha.PHAM_NHAN_ID END)    AS NAM,
                              COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN htha.PHAM_NHAN_ID END) AS NU,
                              COUNT(DISTINCT CASE
                                                 WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                     THEN htha.PHAM_NHAN_ID END)                          AS KHAC,
                              COUNT(DISTINCT htha.PHAM_NHAN_ID)                                           AS TONG_CONG
                       FROM HOAN_THI_HANH_ANS htha
                                JOIN PN_LAI_LICHS pll ON pll.ID = htha.PHAM_NHAN_ID
                                LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                       WHERE htha.NGAY_HOAN >= v_tu_ngay
                         AND htha.NGAY_HOAN < v_den_ngay
                         AND htha.IS_DELETED = 0
                         AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q3_13 AS (SELECT u'Mi\1ec5n ch\1ea5p h\00e0nh \00e1n'                                         AS TITLE,
                              COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN mhp.PN_LAI_LICH_ID END)    AS NAM,
                              COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN mhp.PN_LAI_LICH_ID END) AS NU,
                              COUNT(DISTINCT CASE
                                                 WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                     THEN mhp.PN_LAI_LICH_ID END)                          AS KHAC,
                              COUNT(DISTINCT mhp.PN_LAI_LICH_ID)                                           AS TONG_CONG
                       FROM MIEN_HINH_PHATS mhp
                                JOIN PN_LAI_LICHS pll ON pll.ID = mhp.PN_LAI_LICH_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                                LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
                       WHERE mhp.MHP_NGAY_TU_DO BETWEEN v_tu_ngay AND v_den_ngay
                         AND mhp.IS_DELETED = 0),
             q3_14 AS (SELECT u'Chuy\1ec3n giao cho n\01b0\1edbc ngo\00e0i'         AS TITLE,
                              COUNT(DISTINCT CASE
                                                 WHEN dgt.GT_TEN = u'Nam'
                                                     THEN pcg.PNCG_LAI_LICH_ID END) AS NAM,
                              COUNT(DISTINCT CASE
                                                 WHEN dgt.GT_TEN = u'N\1eef'
                                                     THEN pcg.PNCG_LAI_LICH_ID END) AS NU,
                              COUNT(DISTINCT
                                    CASE
                                        WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                            THEN pcg.PNCG_LAI_LICH_ID END)          AS KHAC,
                              COUNT(DISTINCT pcg.PNCG_LAI_LICH_ID)                  AS TONG_CONG
                       FROM PN_CHUYEN_GIAO pcg
                                JOIN DM_QUOC_TICHS dqt ON dqt.ID = pcg.PNCG_NUOC_CHUYEN_GIAO_ID
                                JOIN PN_LAI_LICHS pll ON pll.ID = pcg.PNCG_LAI_LICH_ID
                                LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                       WHERE pcg.PNCG_NGAY_CHUYEN_GIAO >= v_tu_ngay
                         AND pcg.PNCG_NGAY_CHUYEN_GIAO < v_den_ngay
                         AND pcg.IS_DELETED = 0
                         AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         AND dqt.QT_TEN = 'Vi?t Nam'
                         AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q3_15 AS (SELECT u'B\1eaft bu\1ed9c ch\1eefa b\1ec7nh'                                       AS TITLE,
                              COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN cbbb.PHAM_NHAN_ID END)    AS NAM,
                              COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN cbbb.PHAM_NHAN_ID END) AS NU,
                              COUNT(DISTINCT CASE
                                                 WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                     THEN cbbb.PHAM_NHAN_ID END)                          AS KHAC,
                              COUNT(DISTINCT cbbb.PHAM_NHAN_ID)                                           AS TONG_CONG
                       FROM CHUA_BENH_BAT_BUOCS cbbb
                                JOIN PN_LAI_LICHS pll ON pll.ID = cbbb.PHAM_NHAN_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                                LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                       WHERE CBBB.NGAY_BAT_DAU BETWEEN v_tu_ngay AND v_den_ngay
                         AND CBBB.NGAY_KET_THUC >= v_den_ngay
                         AND CBBB.IS_DELETED = 0
                         AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
             q3_all AS (SELECT u'T\1ed5ng gi\1ea3m'                                                             AS TITLE,
                               COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN u.PN_ID END)                   AS NAM,
                               COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN u.PN_ID END)                AS NU,
                               COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN u.PN_ID END) AS KHAC,
                               COUNT(DISTINCT u.PN_ID)                                                          AS TONG_CONG
                        FROM (SELECT pdx.PNLAI_LICH_ID AS PN_ID
                              FROM PN_DAC_XAS pdx
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = pdx.PNLAI_LICH_ID
                              WHERE pdx.DX_NGAY_THA >= v_tu_ngay
                                AND pdx.DX_NGAY_THA < v_den_ngay
                                AND pdx.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT gth.PHAM_NHAN_ID
                              FROM GIAM_THOI_HANS gth
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = gth.PHAM_NHAN_ID
                              WHERE gth.NGAY_THA_GIAM_HET_AN >= v_tu_ngay
                                AND gth.NGAY_THA_GIAM_HET_AN < v_den_ngay
                                AND gth.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT pktrt.KTRT_PN_LAI_LICH_ID
                              FROM PN_KET_THUC_RA_TRAIS pktrt
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = pktrt.KTRT_PN_LAI_LICH_ID
                              WHERE pktrt.KTRT_NGAY_THA >= v_tu_ngay
                                AND pktrt.KTRT_NGAY_THA < v_den_ngay
                                AND pktrt.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT tcdk.PHAM_NHAN_ID
                              FROM THA_CO_DIEU_KIENS tcdk
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = tcdk.PHAM_NHAN_ID
                              WHERE tcdk.NGAY_THA >= v_tu_ngay
                                AND tcdk.NGAY_THA < v_den_ngay
                                AND tcdk.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (tcdk.NGAY_BAT_LAI IS NULL OR tcdk.NGAY_BAT_LAI >= v_den_ngay)
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT tt.PHAM_NHAN_ID
                              FROM TRON_TRAIS tt
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = tt.PHAM_NHAN_ID
                              WHERE tt.NGAY_TRON >= v_tu_ngay
                                AND tt.NGAY_TRON < v_den_ngay
                                AND tt.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (tt.NGAY_BAT_LAI IS NULL OR tt.NGAY_BAT_LAI >= v_den_ngay)
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT pktc.KTC_PN_LAI_LICH_ID
                              FROM PN_KET_THUC_CHETS pktc
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = pktc.KTC_PN_LAI_LICH_ID
                              WHERE pktc.KTC_NGAY_CHET >= v_tu_ngay
                                AND pktc.KTC_NGAY_CHET < v_den_ngay
                                AND pktc.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT tx.PHAM_NHAN_ID
                              FROM TRICH_XUATS tx
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = tx.PHAM_NHAN_ID
                              WHERE tx.TX_TU_NGAY >= v_tu_ngay
                                AND tx.TX_TU_NGAY < v_den_ngay
                                AND tx.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (tx.TX_NGAY_TRA IS NULL OR tx.TX_NGAY_TRA > v_den_ngay)
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT tdc.PHAM_NHAN_ID
                              FROM TAM_DINH_CHIS tdc
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = tdc.PHAM_NHAN_ID
                              WHERE tdc.TU_NGAY >= v_tu_ngay
                                AND tdc.TU_NGAY < v_den_ngay
                                AND tdc.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (tdc.NGAY_LAI IS NULL OR tdc.NGAY_LAI > v_den_ngay)
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT pnct.PNCT_LAI_LICH_ID
                              FROM PHAM_NHAN_CHUYEN_TRAI pnct
                                       JOIN VW_PN_LAI_LICH_CHI_TIET vw ON pnct.PNCT_LAI_LICH_ID = vw.PHAM_NHAN_ID
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = pnct.PNCT_LAI_LICH_ID
                              WHERE pnct.PNCT_TRAI_DEN_ID <> vw.TRAI_GIAM_ID
                                AND pnct.PNCT_NGAY_CHUYEN >= v_tu_ngay
                                AND pnct.PNCT_NGAY_CHUYEN < v_den_ngay
                                AND pnct.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (pnct.PNCT_NGAY_TRO_LAI IS NULL OR pnct.PNCT_NGAY_TRO_LAI >= v_den_ngay)
                                AND (v_trai_giam_id IS NULL OR vw.TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT ha.PHAM_NHAN_ID
                              FROM HUY_ANS ha
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = ha.PHAM_NHAN_ID
                              WHERE ha.NGAY_TRO_LAI >= v_tu_ngay
                                AND ha.NGAY_TRO_LAI < v_den_ngay
                                AND ha.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT htha.PHAM_NHAN_ID
                              FROM HOAN_THI_HANH_ANS htha
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = htha.PHAM_NHAN_ID
                              WHERE htha.NGAY_HOAN >= v_tu_ngay
                                AND htha.NGAY_HOAN < v_den_ngay
                                AND htha.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)
                              UNION ALL
                              SELECT pcg.PNCG_LAI_LICH_ID
                              FROM PN_CHUYEN_GIAO pcg
                                       JOIN DM_QUOC_TICHS dqt ON dqt.ID = pcg.PNCG_NUOC_CHUYEN_GIAO_ID
                                       JOIN PN_LAI_LICHS pll2 ON pll2.ID = pcg.PNCG_LAI_LICH_ID
                              WHERE pcg.PNCG_NGAY_CHUYEN_GIAO >= v_tu_ngay
                                AND pcg.PNCG_NGAY_CHUYEN_GIAO < v_den_ngay
                                AND pcg.IS_DELETED = 0
                                AND pll2.IS_DELETED = 0
                                AND dqt.QT_TEN = 'Vi?t Nam'
                                AND (v_trai_giam_id IS NULL OR pll2.LL_TRAI_GIAM_ID = v_trai_giam_id)) u
                                 JOIN PN_LAI_LICHS pll ON pll.ID = u.PN_ID AND pll.IS_DELETED = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                                 LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID)
        SELECT *
        FROM (SELECT *
              FROM q1
              UNION ALL
              SELECT *
              FROM q2_1
              UNION ALL
              SELECT *
              FROM q2_2
              UNION ALL
              SELECT *
              FROM q2_3
              UNION ALL
              SELECT *
              FROM q2_4
              UNION ALL
              SELECT *
              FROM q2_5
              UNION ALL
              SELECT *
              FROM q2_6
              UNION ALL
              SELECT *
              FROM Q2_7
              UNION ALL
              SELECT *
              FROM Q2_8
              UNION ALL
              SELECT *
              FROM q2_ALL
              UNION ALL
              SELECT *
              FROM q3_1
              UNION ALL
              SELECT *
              FROM q3_2
              UNION ALL
              SELECT *
              FROM q3_3
              UNION ALL
              SELECT *
              FROM q3_4
              UNION ALL
              SELECT *
              FROM q3_5
              UNION ALL
              SELECT *
              FROM q3_6
              UNION ALL
              SELECT *
              FROM q3_7
              UNION ALL
              SELECT *
              FROM q3_8
              UNION ALL
              SELECT *
              FROM q3_9
              UNION ALL
              SELECT *
              FROM q3_10
              UNION ALL
              SELECT *
              FROM q3_11
              UNION ALL
              SELECT *
              FROM q3_12
              UNION ALL
              SELECT *
              FROM q3_13
              UNION ALL
              SELECT *
              FROM q3_14
              UNION ALL
              SELECT *
              FROM q3_15
              UNION ALL
              SELECT *
              FROM q3_all);
    DBMS_SQL.RETURN_RESULT(p_result);
END SP_THONG_KE_TONG_HOP_BIEN_DONG
    ;
/

/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_TONG_HOP_CHUNG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_TONG_HOP_CHUNG" (
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL,
    p_ma_trai_giam IN NVARCHAR2 DEFAULT NULL
) AS
    v_tu_ngay      DATE;
    v_den_ngay     DATE;
    v_ll_trai_giam_id NUMBER;
    C1             SYS_REFCURSOR;

BEGIN
    -- K? 15 -> 14 (??ng b? SP_QLPN_GET_TK_THANG_DASHBOARD)
    IF p_tu_ngay IS NULL AND p_den_ngay IS NULL THEN
        IF EXTRACT(DAY FROM SYSDATE) < 15 THEN
            v_tu_ngay  := ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1) + 14;
            v_den_ngay := TRUNC(SYSDATE, 'MM') + 13;
        ELSE
            v_tu_ngay  := TRUNC(SYSDATE, 'MM') + 14;
            v_den_ngay := ADD_MONTHS(TRUNC(SYSDATE, 'MM'), 1) + 13;
        END IF;
    ELSIF p_tu_ngay IS NOT NULL AND p_den_ngay IS NOT NULL THEN
        IF EXTRACT(DAY FROM p_tu_ngay) < 15 THEN
            v_tu_ngay := TRUNC(ADD_MONTHS(p_tu_ngay, -1), 'MM') + 14;
        ELSE
            v_tu_ngay := TRUNC(p_tu_ngay, 'MM') + 14;
        END IF;
        IF EXTRACT(DAY FROM p_den_ngay) > 14 THEN
            v_den_ngay := TRUNC(ADD_MONTHS(p_den_ngay, 1), 'MM') + 13;
        ELSE
            v_den_ngay := TRUNC(p_den_ngay, 'MM') + 13;
        END IF;
    ELSE
        v_tu_ngay  := TRUNC(NVL(p_tu_ngay, SYSDATE));
        v_den_ngay := TRUNC(NVL(p_den_ngay, SYSDATE));
    END IF;

    IF v_tu_ngay > v_den_ngay THEN
        RAISE_APPLICATION_ERROR(-20001, 'Tu ngay phai nho hon hoac bang den ngay');
    END IF;

    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL
       AND TRIM(p_ma_trai_giam) IS NOT NULL
       AND TRIM(p_ma_trai_giam) <> u'C10'
    THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_den_ngay);

    OPEN C1 FOR
        WITH pham_nhan_filtered AS (
            SELECT /*+ MATERIALIZE */
                   pll.ID,
                   pll.LL_DM_GIOI_TINH_ID,
                   pll.LL_PHAN_TRAI_ID,
                   pll.LL_NGAY_SINH,
                   pll.LL_SO_TIEN_AN,
                   pll.LL_TAI_PHAM,
                   pll.LL_DM_HOC_VAN_ID,
                   pll.LL_DM_NGHE_NGHIEP_ID,
                   pll.LL_DM_DAN_TOC_ID,
                   pll.LL_DM_TON_GIAO_ID,
                   pll.LL_DM_QUOC_TICH_ID,
                   pll.LL_BENH_TAT_VAO_ID,
                   pll.LL_BENH_HIEN_TAI_ID,
                   pll.LL_GHI_CHU_RIENG,
                   pll.LL_DIA_CHI_THUONG_TRU_PROVICE,
                   pll.LL_NOI_THA_VE_CU_TRU_PROVICE
            FROM PN_LAI_LICHS pll
            INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
                    ON tt.PN_LAI_LICH_ID = pll.ID
                   AND tt.NGAY_XET = TRUNC(v_den_ngay)
                   AND tt.TTPN_MA IN ('111', '112', '113', '114')
            WHERE NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
              AND (v_ll_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)),
             ptha_one AS (
                 SELECT p.THA_PNLAI_LICH_ID,
                        p.THA_TOI_DANH,
                        p.THA_AN_PHAT,
                        p.THA_NGAY_BAT,
                        p.THA_NGAY_PHAM_TOI
                 FROM (SELECT t.*,
                              ROW_NUMBER() OVER (PARTITION BY t.THA_PNLAI_LICH_ID ORDER BY t.ID DESC) AS rn
                       FROM PN_THI_HANH_AN t
                       WHERE NVL(t.IS_DELETED, 0) = 0
                         AND t.THA_PNLAI_LICH_ID IN (SELECT f.ID FROM pham_nhan_filtered f)) p
                 WHERE p.rn = 1),
             sec_i1 AS (
                 SELECT 1000000 AS sort_thu_tu,
                        TO_NCHAR(u'I.1') AS ma_loai_thong_ke,
                        TO_NCHAR(u'S\1ed1 li\1ec7u chung - T\1ed5ng s\1ed1') AS loai_thong_ke,
                        TO_NCHAR(u'T\1ed5ng') AS thong_ke_theo,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN pll.ID END) AS nam,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN pll.ID END) AS nu,
                        COUNT(DISTINCT CASE WHEN LOWER(NVL(dgt.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN pll.ID END) AS khac,
                        COUNT(DISTINCT pll.ID) AS tong_so
                 FROM pham_nhan_filtered pll
                          LEFT JOIN DM_GIOI_TINHS dgt
                                    ON pll.LL_DM_GIOI_TINH_ID = dgt.ID
                                        AND NVL(dgt.IS_DELETED, 0) = 0),
             sec_i2 AS (
                 SELECT 2000000 + ROW_NUMBER() OVER (ORDER BY NVL(dpt.PT_TEN, u' '), dpt.ID) AS sort_thu_tu,
                        TO_NCHAR(u'I.2') AS ma_loai_thong_ke,
                        TO_NCHAR(u'S\1ed1 li\1ec7u chung - T\1eebng ph\00e2n tr\1ea1i') AS loai_thong_ke,
                        NVL(TO_NCHAR(dpt.PT_TEN), u'Kh\00f4ng x\00e1c \0111\1ecbnh') AS thong_ke_theo,
                        COUNT(DISTINCT CASE WHEN LOWER(gt.GT_TEN) = u'nam' THEN pn.ID END) AS nam,
                        COUNT(DISTINCT CASE WHEN LOWER(gt.GT_TEN) = u'n\1eef' THEN pn.ID END) AS nu,
                        COUNT(DISTINCT CASE WHEN LOWER(gt.GT_TEN) NOT IN (u'nam', u'n\1eef') THEN pn.ID END) AS khac,
                        COUNT(DISTINCT pn.ID) AS tong_so
                 FROM pham_nhan_filtered pn
                          LEFT JOIN DM_PHAN_TRAIS dpt
                                    ON dpt.ID = pn.LL_PHAN_TRAI_ID
                                        AND NVL(dpt.IS_DELETED, 0) = 0
                          LEFT JOIN DM_GIOI_TINHS gt
                                    ON gt.ID = pn.LL_DM_GIOI_TINH_ID
                                        AND NVL(gt.IS_DELETED, 0) = 0
                 GROUP BY dpt.PT_TEN, dpt.ID),
             pn_chuong AS (
                 SELECT pll.ID AS pham_nhan_id,
                        pll.LL_DM_GIOI_TINH_ID,
                        CASE
                            WHEN ptha.THA_TOI_DANH IS NOT NULL
                                 AND TRIM(ptha.THA_TOI_DANH) IS NOT NULL
                                 AND REGEXP_LIKE(
                                     TRIM(REGEXP_SUBSTR(
                                         REPLACE(REPLACE(TRIM(ptha.THA_TOI_DANH), '[', ''), ']', ''),
                                         '[^,]+', 1, 1)),
                                     '^[0-9]+$')
                                THEN TO_NUMBER(TRIM(REGEXP_SUBSTR(
                                    REPLACE(REPLACE(TRIM(ptha.THA_TOI_DANH), '[', ''), ']', ''),
                                    '[^,]+', 1, 1)))
                            END AS toi_danh_id_dau
                 FROM pham_nhan_filtered pll
                          INNER JOIN ptha_one ptha
                                     ON ptha.THA_PNLAI_LICH_ID = pll.ID),
             all_chuong AS (
                 SELECT dctd.ID AS chuong_id, dctd.CTD_TEN AS chuong_ten
                 FROM DM_CHUONG_TOI_DANHS dctd
                 WHERE NVL(dctd.IS_DELETED, 0) = 0),
             stats_theo_chuong AS (
                 SELECT dctd.ID AS chuong_id,
                        dctd.CTD_TEN AS chuong_ten,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN ll.pham_nhan_id END) AS nam,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN ll.pham_nhan_id END) AS nu,
                        COUNT(DISTINCT CASE
                                  WHEN LOWER(NVL(dgt.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN ll.pham_nhan_id END) AS khac,
                        COUNT(DISTINCT ll.pham_nhan_id) AS tong
                 FROM pn_chuong ll
                          LEFT JOIN DM_TOI_DANHS dtd
                                    ON dtd.ID = ll.toi_danh_id_dau
                                        AND NVL(dtd.IS_DELETED, 0) = 0
                          INNER JOIN DM_CHUONG_TOI_DANHS dctd
                                     ON TRIM(TO_CHAR(dctd.CTD_MA)) = TRIM(TO_CHAR(dtd.TD_CHUONG))
                                         AND NVL(dctd.IS_DELETED, 0) = 0
                          LEFT JOIN DM_GIOI_TINHS dgt
                                    ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                        AND NVL(dgt.IS_DELETED, 0) = 0
                 GROUP BY dctd.ID, dctd.CTD_TEN),
             stats_chuong_kxd AS (
                 SELECT COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN ll.pham_nhan_id END) AS nam,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN ll.pham_nhan_id END) AS nu,
                        COUNT(DISTINCT CASE
                                  WHEN LOWER(NVL(dgt.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN ll.pham_nhan_id END) AS khac,
                        COUNT(DISTINCT ll.pham_nhan_id) AS tong
                 FROM pn_chuong ll
                          LEFT JOIN DM_TOI_DANHS dtd
                                    ON dtd.ID = ll.toi_danh_id_dau
                                        AND NVL(dtd.IS_DELETED, 0) = 0
                          LEFT JOIN DM_CHUONG_TOI_DANHS dctd
                                    ON TRIM(TO_CHAR(dctd.CTD_MA)) = TRIM(TO_CHAR(dtd.TD_CHUONG))
                                        AND NVL(dctd.IS_DELETED, 0) = 0
                          LEFT JOIN DM_GIOI_TINHS dgt
                                    ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                        AND NVL(dgt.IS_DELETED, 0) = 0
                 WHERE dctd.ID IS NULL),
             dong_chuong AS (
                 SELECT NVL(st.tong, 0) AS tong_ord,
                        ac.chuong_ten AS chuong_sort,
                        NVL(st.nam, 0) AS nam,
                        NVL(st.nu, 0) AS nu,
                        NVL(st.khac, 0) AS khac,
                        NVL(st.tong, 0) AS tong_so
                 FROM all_chuong ac
                          LEFT JOIN stats_theo_chuong st ON st.chuong_id = ac.chuong_id
                 UNION ALL
                 SELECT NVL(kx.tong, 0),
                        u'Kh\00f4ng x\00e1c \0111\1ecbnh',
                        kx.nam,
                        kx.nu,
                        kx.khac,
                        kx.tong
                 FROM stats_chuong_kxd kx
                 WHERE NVL(kx.tong, 0) > 0),
             sec_ii1 AS (
                 SELECT 3000000 + ROW_NUMBER() OVER (ORDER BY dc.tong_ord DESC, dc.chuong_sort) AS sort_thu_tu,
                        TO_NCHAR(u'II.1') AS ma_loai_thong_ke,
                        TO_NCHAR(u'Chi ti\1ebft - Theo c\00e1c ch\01b0\01a1ng t\1ed9i danh') AS loai_thong_ke,
                        TO_NCHAR(dc.chuong_sort) AS thong_ke_theo,
                        dc.nam,
                        dc.nu,
                        dc.khac,
                        dc.tong_so
                 FROM dong_chuong dc),
             pn_muc AS (
                 SELECT pll.ID AS pham_nhan_id,
                        pll.LL_DM_GIOI_TINH_ID,
                        ptha.THA_AN_PHAT
                 FROM pham_nhan_filtered pll
                          INNER JOIN ptha_one ptha
                                     ON ptha.THA_PNLAI_LICH_ID = pll.ID),
             co_thang_muc AS (
                 SELECT ll.pham_nhan_id,
                        ll.LL_DM_GIOI_TINH_ID,
                        ll.THA_AN_PHAT,
                        (NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(ll.THA_AN_PHAT AS NVARCHAR2(2000)), 'NAM'), 0) * 12
                         + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(ll.THA_AN_PHAT AS NVARCHAR2(2000)), 'THANG'), 0)
                         + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(ll.THA_AN_PHAT AS NVARCHAR2(2000)), 'NGAY'), 0) / 30.0) AS tha_thang_tong
                 FROM pn_muc ll),
             phan_loai_muc AS (
                 SELECT c.*,
                        CASE
                            WHEN UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) LIKE '%CHUNGTHAN%'
                                 AND UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) NOT LIKE '%GIAMXUONG%'
                                THEN 1
                            WHEN LOWER(TRIM(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) = u'chung th\00e2n gi\1ea3m xu\1ed1ng 30 n\0103m'
                                 OR (UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) LIKE '%CHUNGTHAN%'
                                     AND UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) LIKE '%GIAMXUONG%'
                                     AND REGEXP_LIKE(
                                         UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))),
                                         '30.*NAM|NAM.*30'))
                                THEN 2
                            WHEN LOWER(TRIM(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) = u'chung th\00e2n gi\1ea3m xu\1ed1ng 20 n\0103m'
                                 OR (UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) LIKE '%CHUNGTHAN%'
                                     AND UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) LIKE '%GIAMXUONG%'
                                     AND REGEXP_LIKE(
                                         UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))),
                                         '20.*NAM|NAM.*20'))
                                THEN 3
                            WHEN c.tha_thang_tong > 240 AND c.tha_thang_tong <= 360 THEN 2
                            WHEN c.tha_thang_tong > 180 AND c.tha_thang_tong <= 240 THEN 3
                            WHEN c.tha_thang_tong > 84 AND c.tha_thang_tong <= 180 THEN 4
                            WHEN c.tha_thang_tong > 36 AND c.tha_thang_tong <= 84 THEN 5
                            WHEN c.tha_thang_tong > 0 AND c.tha_thang_tong <= 36 THEN 6
                            ELSE NULL
                            END AS muc_id
                 FROM co_thang_muc c),
             all_muc AS (
                 SELECT 1 AS muc_id, u'Chung th\00e2n' AS muc_ten FROM dual
                 UNION ALL SELECT 2, u'Tr\00ean 20 - 30 n\0103m' FROM dual
                 UNION ALL SELECT 3, u'Tr\00ean 15 - 20 n\0103m' FROM dual
                 UNION ALL SELECT 4, u'Tr\00ean 7 - 15 n\0103m' FROM dual
                 UNION ALL SELECT 5, u'Tr\00ean 3 - 7 n\0103m' FROM dual
                 UNION ALL SELECT 6, u'T\1eeb 3 n\0103m tr\1edf xu\1ed1ng' FROM dual),
             stats_muc AS (
                 SELECT pl.muc_id,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN pl.pham_nhan_id END) AS nam,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN pl.pham_nhan_id END) AS nu,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) NOT IN (u'nam', u'n\1eef') THEN pl.pham_nhan_id END) AS khac,
                        COUNT(DISTINCT pl.pham_nhan_id) AS tong
                 FROM phan_loai_muc pl
                          LEFT JOIN DM_GIOI_TINHS dgt
                                    ON dgt.ID = pl.LL_DM_GIOI_TINH_ID
                                        AND NVL(dgt.IS_DELETED, 0) = 0
                 WHERE pl.muc_id IS NOT NULL
                 GROUP BY pl.muc_id),
             stats_muc_kxd AS (
                 SELECT COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN pl.pham_nhan_id END) AS nam,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN pl.pham_nhan_id END) AS nu,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) NOT IN (u'nam', u'n\1eef') THEN pl.pham_nhan_id END) AS khac,
                        COUNT(DISTINCT pl.pham_nhan_id) AS tong
                 FROM phan_loai_muc pl
                          LEFT JOIN DM_GIOI_TINHS dgt
                                    ON dgt.ID = pl.LL_DM_GIOI_TINH_ID
                                        AND NVL(dgt.IS_DELETED, 0) = 0
                 WHERE pl.muc_id IS NULL),
             dong_muc AS (
                 SELECT am.muc_id AS sort_key,
                        am.muc_ten AS muc_ten,
                        NVL(sm.nam, 0) AS nam,
                        NVL(sm.nu, 0) AS nu,
                        NVL(sm.khac, 0) AS khac,
                        NVL(sm.tong, 0) AS tong
                 FROM all_muc am
                          LEFT JOIN stats_muc sm ON sm.muc_id = am.muc_id
                 UNION ALL
                 SELECT 998,
                        u'Kh\00f4ng x\00e1c \0111\1ecbnh',
                        kx.nam,
                        kx.nu,
                        kx.khac,
                        kx.tong
                 FROM stats_muc_kxd kx
                 WHERE NVL(kx.tong, 0) > 0),
             sec_ii2 AS (
                 SELECT 4000000 + ROW_NUMBER() OVER (ORDER BY dm.sort_key) AS sort_thu_tu,
                        TO_NCHAR(u'II.2') AS ma_loai_thong_ke,
                        TO_NCHAR(u'Chi ti\1ebft - Theo m\1ee9c \00e1n ph\1ea1t') AS loai_thong_ke,
                        TO_NCHAR(dm.muc_ten) AS thong_ke_theo,
                        dm.nam,
                        dm.nu,
                        dm.khac,
                        dm.tong AS tong_so
                 FROM dong_muc dm),
             sec_ii3 AS (
                 SELECT 5000000 + ROW_NUMBER() OVER (ORDER BY g.sort_ord) AS sort_thu_tu,
                        TO_NCHAR(u'II.3') AS ma_loai_thong_ke,
                        TO_NCHAR(u'Chi ti\1ebft - Theo s\1ed1 ti\1ec1n \00e1n') AS loai_thong_ke,
                        g.grp_label AS thong_ke_theo,
                        g.nam,
                        g.nu,
                        g.khac,
                        g.tong_so
                 FROM (SELECT CASE
                                   WHEN ll.LL_SO_TIEN_AN IS NULL OR ll.LL_SO_TIEN_AN = 0 THEN u'Ch\01b0a c\00f3 ti\1ec1n \00e1n'
                                   WHEN ll.LL_SO_TIEN_AN = 1 THEN u'C\00f3 1 ti\1ec1n \00e1n'
                                   WHEN ll.LL_SO_TIEN_AN = 2 THEN u'C\00f3 2 ti\1ec1n \00e1n'
                                   WHEN ll.LL_SO_TIEN_AN >= 3 THEN u'C\00f3 3 ti\1ec1n \00e1n tr\1edf l\00ean'
                                   END AS grp_label,
                              CASE
                                  WHEN ll.LL_SO_TIEN_AN IS NULL OR ll.LL_SO_TIEN_AN = 0 THEN 1
                                  WHEN ll.LL_SO_TIEN_AN = 1 THEN 2
                                  WHEN ll.LL_SO_TIEN_AN = 2 THEN 3
                                  WHEN ll.LL_SO_TIEN_AN >= 3 THEN 4
                                  END AS sort_ord,
                              COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN ll.ID END) AS nam,
                              COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN ll.ID END) AS nu,
                              COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) NOT IN (u'nam', u'n\1eef') THEN ll.ID END) AS khac,
                              COUNT(DISTINCT ll.ID) AS tong_so
                       FROM pham_nhan_filtered ll
                                LEFT JOIN DM_GIOI_TINHS dgt
                                          ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                              AND NVL(dgt.IS_DELETED, 0) = 0
                       GROUP BY CASE
                                    WHEN ll.LL_SO_TIEN_AN IS NULL OR ll.LL_SO_TIEN_AN = 0 THEN u'Ch\01b0a c\00f3 ti\1ec1n \00e1n'
                                    WHEN ll.LL_SO_TIEN_AN = 1 THEN u'C\00f3 1 ti\1ec1n \00e1n'
                                    WHEN ll.LL_SO_TIEN_AN = 2 THEN u'C\00f3 2 ti\1ec1n \00e1n'
                                    WHEN ll.LL_SO_TIEN_AN >= 3 THEN u'C\00f3 3 ti\1ec1n \00e1n tr\1edf l\00ean'
                                    END,
                                CASE
                                    WHEN ll.LL_SO_TIEN_AN IS NULL OR ll.LL_SO_TIEN_AN = 0 THEN 1
                                    WHEN ll.LL_SO_TIEN_AN = 1 THEN 2
                                    WHEN ll.LL_SO_TIEN_AN = 2 THEN 3
                                    WHEN ll.LL_SO_TIEN_AN >= 3 THEN 4
                                    END) g),
             sec_ii4 AS (
                 SELECT 6000000 + ROW_NUMBER() OVER (ORDER BY g.tong_so DESC, g.tp_ten_lbl) AS sort_thu_tu,
                        TO_NCHAR(u'II.4') AS ma_loai_thong_ke,
                        TO_NCHAR(u'Chi ti\1ebft - Theo t\00ednh ch\1ea5t t\1ed9i ph\1ea1m') AS loai_thong_ke,
                        TO_NCHAR(g.tp_ten_lbl) AS thong_ke_theo,
                        g.nam,
                        g.nu,
                        g.khac,
                        g.tong_so
                 FROM (SELECT NVL(dtp.TP_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh') AS tp_ten_lbl,
                              COUNT(DISTINCT CASE WHEN LOWER(gt.GT_TEN) = u'nam' THEN pn.ID END) AS nam,
                              COUNT(DISTINCT CASE WHEN LOWER(gt.GT_TEN) = u'n\1eef' THEN pn.ID END) AS nu,
                              COUNT(DISTINCT CASE WHEN LOWER(gt.GT_TEN) NOT IN (u'nam', u'n\1eef') THEN pn.ID END) AS khac,
                              COUNT(DISTINCT pn.ID) AS tong_so
                       FROM pham_nhan_filtered pn
                                LEFT JOIN DM_TAI_PHAMS dtp
                                          ON dtp.ID = pn.LL_TAI_PHAM
                                              AND NVL(dtp.IS_DELETED, 0) = 0
                                LEFT JOIN DM_GIOI_TINHS gt
                                          ON gt.ID = pn.LL_DM_GIOI_TINH_ID
                                              AND NVL(gt.IS_DELETED, 0) = 0
                       GROUP BY dtp.TP_TEN) g),
             pn_do_tuoi AS (
                 SELECT x.pham_nhan_id,
                        x.LL_DM_GIOI_TINH_ID,
                        TRUNC(MONTHS_BETWEEN(v_den_ngay, x.ngay_sinh) / 12) AS tuoi_hien_tai,
                        x.ngay_sinh,
                        x.ngay_pham_toi,
                        x.duoi_18_khi_pham_toi
                 FROM (SELECT base.pham_nhan_id,
                              base.LL_DM_GIOI_TINH_ID,
                              base.ngay_sinh,
                              base.ngay_pham_toi,
                              CASE
                                  WHEN EXISTS (
                                      SELECT 1
                                      FROM PN_THI_HANH_AN tha
                                      WHERE tha.THA_PNLAI_LICH_ID = base.pham_nhan_id
                                        AND NVL(tha.IS_DELETED, 0) = 0
                                        AND tha.THA_NGAY_PHAM_TOI IS NOT NULL
                                        AND base.ngay_sinh IS NOT NULL
                                        AND TRUNC(tha.THA_NGAY_PHAM_TOI) <
                                            ADD_MONTHS(base.ngay_sinh, 18 * 12)
                                  ) THEN 1
                                  ELSE 0
                              END AS duoi_18_khi_pham_toi
                       FROM (SELECT pll.ID AS pham_nhan_id,
                                    pll.LL_DM_GIOI_TINH_ID,
                                    QLPN.FN_PARSE_LL_NGAY_SINH(pll.LL_NGAY_SINH) AS ngay_sinh,
                                    ptha.THA_NGAY_PHAM_TOI AS ngay_pham_toi
                             FROM pham_nhan_filtered pll
                                      INNER JOIN ptha_one ptha
                                                 ON ptha.THA_PNLAI_LICH_ID = pll.ID) base) x),
             ranges_dt AS (
                 SELECT 1 id, u'D\01b0\1edbi 18 tu\1ed5i' ten, 0 tu, 17 den, NULL tu_thang, NULL den_thang FROM dual
                 UNION ALL SELECT 2, u'T\1eeb 18 - d\01b0\1edbi 30 tu\1ed5i', 18, 29, 216, 360 FROM dual
                 UNION ALL SELECT 3, u'T\1eeb 30 - d\01b0\1edbi 45 tu\1ed5i', 30, 44, 360, 540 FROM dual
                 UNION ALL SELECT 4, u'T\1eeb 45 - d\01b0\1edbi 55 tu\1ed5i', 45, 54, 540, 660 FROM dual
                 UNION ALL SELECT 5, u'T\1eeb 55 - d\01b0\1edbi 60 tu\1ed5i', 55, 59, 660, 720 FROM dual
                 UNION ALL SELECT 6, u'T\1eeb 60 - d\01b0\1edbi 70 tu\1ed5i', 60, 69, 720, 840 FROM dual
                 UNION ALL SELECT 7, u'T\1eeb 70 tu\1ed5i tr\1edf l\00ean', 70, 200, 840, NULL FROM dual),
             sec_ii5a AS (
                 SELECT 7000000 + r.id AS sort_thu_tu,
                        TO_NCHAR(u'II.5.a') AS ma_loai_thong_ke,
                        TO_NCHAR(u'Chi ti\1ebft - Theo \0111\1ed9 tu\1ed5i hi\1ec7n t\1ea1i') AS loai_thong_ke,
                        TO_NCHAR(r.ten) AS thong_ke_theo,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN ll.pham_nhan_id END) AS nam,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN ll.pham_nhan_id END) AS nu,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) NOT IN (u'nam', u'n\1eef') THEN ll.pham_nhan_id END) AS khac,
                        COUNT(DISTINCT ll.pham_nhan_id) AS tong_so
                 FROM pn_do_tuoi ll
                          INNER JOIN ranges_dt r ON ll.tuoi_hien_tai BETWEEN r.tu AND r.den
                          LEFT JOIN DM_GIOI_TINHS dgt
                                    ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                        AND NVL(dgt.IS_DELETED, 0) = 0
                 GROUP BY r.id, r.ten),
             sec_ii5b AS (
                 SELECT 7500000 + r.id AS sort_thu_tu,
                        TO_NCHAR(u'II.5.b') AS ma_loai_thong_ke,
                        TO_NCHAR(u'Chi ti\1ebft - Theo \0111\1ed9 tu\1ed5i l\00fac ph\1ea1m t\1ed9i') AS loai_thong_ke,
                        TO_NCHAR(r.ten) AS thong_ke_theo,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN ll.pham_nhan_id END) AS nam,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN ll.pham_nhan_id END) AS nu,
                        COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) NOT IN (u'nam', u'n\1eef') THEN ll.pham_nhan_id END) AS khac,
                        COUNT(DISTINCT ll.pham_nhan_id) AS tong_so
                 FROM pn_do_tuoi ll
                          INNER JOIN ranges_dt r
                                    ON (r.id = 1 AND ll.duoi_18_khi_pham_toi = 1)
                                        OR (r.id > 1
                                            AND ll.duoi_18_khi_pham_toi = 0
                                            AND ll.ngay_sinh IS NOT NULL
                                            AND ll.ngay_pham_toi IS NOT NULL
                                            AND TRUNC(ll.ngay_pham_toi) >= ADD_MONTHS(ll.ngay_sinh, r.tu_thang)
                                            AND (r.den_thang IS NULL
                                                 OR TRUNC(ll.ngay_pham_toi) < ADD_MONTHS(ll.ngay_sinh, r.den_thang)))
                          LEFT JOIN DM_GIOI_TINHS dgt
                                    ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                        AND NVL(dgt.IS_DELETED, 0) = 0
                 GROUP BY r.id, r.ten),
             sec_ii6 AS (
                 SELECT 8000000 + ROW_NUMBER() OVER (ORDER BY g.tong_so DESC, g.hoc_van_lbl) AS sort_thu_tu,
                        TO_NCHAR(u'II.6') AS ma_loai_thong_ke,
                        TO_NCHAR(u'Chi ti\1ebft - Theo h\1ecdc v\1ea5n') AS loai_thong_ke,
                        g.hoc_van_lbl AS thong_ke_theo,
                        g.nam,
                        g.nu,
                        g.khac,
                        g.tong_so
                 FROM (SELECT NVL(TO_NCHAR(dhv.HV_TEN), u'Kh\00f4ng bi\1ebft ch\1eef') AS hoc_van_lbl,
                              COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN ll.ID END) AS nam,
                              COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN ll.ID END) AS nu,
                              COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) NOT IN (u'nam', u'n\1eef') THEN ll.ID END) AS khac,
                              COUNT(DISTINCT ll.ID) AS tong_so
                       FROM pham_nhan_filtered ll
                                LEFT JOIN DM_GIOI_TINHS dgt
                                          ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                              AND NVL(dgt.IS_DELETED, 0) = 0
                                LEFT JOIN DM_HOC_VANS dhv
                                          ON ll.LL_DM_HOC_VAN_ID = dhv.ID
                                              AND NVL(dhv.IS_DELETED, 0) = 0
                       GROUP BY dhv.HV_TEN) g),
             sec_ii7 AS (
                 SELECT 9000000 + ROW_NUMBER() OVER (ORDER BY g.nn_ma_sort, g.nghe_nghiep_lbl) AS sort_thu_tu,
                        TO_NCHAR(u'II.7') AS ma_loai_thong_ke,
                        TO_NCHAR(u'Chi ti\1ebft - Theo ngh\1ec1 nghi\1ec7p') AS loai_thong_ke,
                        g.nghe_nghiep_lbl AS thong_ke_theo,
                        g.nam,
                        g.nu,
                        g.khac,
                        g.tong_so
                 FROM (SELECT NVL(dnn.NN_MA, u'999') AS nn_ma_sort,
                              NVL(MAX(TO_NCHAR(dnn.NN_TEN)), u'Kh\00f4ng r\00f5 ngh\1ec1 nghi\1ec7p') AS nghe_nghiep_lbl,
                              COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN ll.ID END) AS nam,
                              COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN ll.ID END) AS nu,
                              COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) NOT IN (u'nam', u'n\1eef') THEN ll.ID END) AS khac,
                              COUNT(DISTINCT ll.ID) AS tong_so
                       FROM pham_nhan_filtered ll
                                LEFT JOIN DM_GIOI_TINHS dgt
                                          ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                              AND NVL(dgt.IS_DELETED, 0) = 0
                                LEFT JOIN DM_NGHE_NGHIEPS dnn
                                          ON ll.LL_DM_NGHE_NGHIEP_ID = dnn.ID
                                              AND NVL(dnn.IS_DELETED, 0) = 0
                       GROUP BY NVL(dnn.NN_MA, u'999')) g),
             dt_labeled AS (SELECT ll.ID AS pham_nhan_id,
                                   dgt.GT_TEN,
                                   ddt.ID AS dt_id,
                                   ddt.DT_TEN,
                                   CASE
                                       WHEN TRIM(TO_CHAR(ddt.DT_MA)) = '6500' THEN 'NN'
                                       WHEN (TRIM(TO_CHAR(ddt.DT_MA)) IS NULL OR TRIM(TO_CHAR(ddt.DT_MA)) <> '6500')
                                            AND LOWER(TRIM(NVL(ddt.DT_TEN, u' '))) = u'kinh' THEN 'KINH'
                                       ELSE 'IT'
                                       END AS pl
                            FROM pham_nhan_filtered ll
                                     LEFT JOIN DM_GIOI_TINHS dgt
                                               ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                                   AND NVL(dgt.IS_DELETED, 0) = 0
                                     LEFT JOIN DM_DAN_TOCS ddt
                                               ON ll.LL_DM_DAN_TOC_ID = ddt.ID
                                                   AND NVL(ddt.IS_DELETED, 0) = 0),
             dt_agg_kinh AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                    COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                    COUNT(DISTINCT CASE
                                              WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                    COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                             FROM dt_labeled lb
                             WHERE lb.pl = 'KINH'),
             dt_agg_nn AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                  COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                  COUNT(DISTINCT CASE
                                            WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                  COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                           FROM dt_labeled lb
                           WHERE lb.pl = 'NN'),
             dt_agg_it_tong AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                       COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                       COUNT(DISTINCT CASE
                                                 WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                       COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                                FROM dt_labeled lb
                                WHERE lb.pl = 'IT'),
             dt_agg_it_chi_tiet AS (SELECT NVL(lb.dt_id, -1) AS dt_id_bucket,
                                            NVL(lb.DT_TEN, u'Kh\00f4ng r\00f5 d\00e2n t\1ed9c') AS dt_ten_bucket,
                                            COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                            COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                            COUNT(DISTINCT CASE
                                                      WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                            COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                                     FROM dt_labeled lb
                                     WHERE lb.pl = 'IT'
                                     GROUP BY NVL(lb.dt_id, -1), NVL(lb.DT_TEN, u'Kh\00f4ng r\00f5 d\00e2n t\1ed9c')),
             dt_it_chi_ordered AS (SELECT ac.*,
                                          ROW_NUMBER() OVER (ORDER BY QLPN.ORDER_HOTEN(TO_CHAR(ac.dt_ten_bucket)), ac.dt_id_bucket) AS it_ord
                                   FROM dt_agg_it_chi_tiet ac),
             dt_stacked AS (SELECT 10 AS sort_key,
                                   u'D\00e2n t\1ed9c Kinh' AS lbl,
                                   k.nam,
                                   k.nu,
                                   k.khac,
                                   k.tong_so
                            FROM dt_agg_kinh k
                            UNION ALL
                            SELECT 20,
                                   u'Ng\01b0\1eddi n\01b0\1edbc ngo\00e0i',
                                   n.nam,
                                   n.nu,
                                   n.khac,
                                   n.tong_so
                            FROM dt_agg_nn n
                            UNION ALL
                            SELECT 30,
                                   u'D\00e2n t\1ed9c \00edt ng\01b0\1eddi',
                                   t.nam,
                                   t.nu,
                                   t.khac,
                                   t.tong_so
                            FROM dt_agg_it_tong t
                            UNION ALL
                            SELECT 40 + io.it_ord,
                                   TO_NCHAR(u'+ ') || TO_NCHAR(io.dt_ten_bucket),
                                   io.nam,
                                   io.nu,
                                   io.khac,
                                   io.tong_so
                            FROM dt_it_chi_ordered io),
             sec_ii8 AS (SELECT 10000000 + s.sort_key AS sort_thu_tu,
                                TO_NCHAR(u'II.8') AS ma_loai_thong_ke,
                                TO_NCHAR(u'Chi ti\1ebft - Theo d\00e2n t\1ed9c') AS loai_thong_ke,
                                TO_NCHAR(s.lbl) AS thong_ke_theo,
                                s.nam,
                                s.nu,
                                s.khac,
                                s.tong_so
                         FROM dt_stacked s),
             tg_labeled AS (SELECT ll.ID AS pham_nhan_id,
                                   dgt.GT_TEN,
                                   dmtg.ID AS tg_id,
                                   dmtg.TG_TEN,
                                   CASE
                                       WHEN dmtg.TG_MA IS NOT NULL
                                            AND NOT EXISTS (SELECT 1
                                                            FROM DM_TON_GIAOS tg0
                                                            WHERE NVL(tg0.IS_DELETED, 0) = 0
                                                              AND TRIM(tg0.TG_TEN) = u'Kh\00f4ng'
                                                              AND TRIM(TO_CHAR(tg0.TG_MA)) = TRIM(TO_CHAR(dmtg.TG_MA)))
                                           THEN 'CO'
                                       ELSE 'KHONG'
                                       END AS pl
                            FROM pham_nhan_filtered ll
                                     LEFT JOIN DM_GIOI_TINHS dgt
                                               ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                                   AND NVL(dgt.IS_DELETED, 0) = 0
                                     LEFT JOIN DM_TON_GIAOS dmtg
                                               ON ll.LL_DM_TON_GIAO_ID = dmtg.ID
                                                   AND NVL(dmtg.IS_DELETED, 0) = 0),
             tg_agg_khong AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                     COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                     COUNT(DISTINCT CASE
                                               WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                     COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                              FROM tg_labeled lb
                              WHERE lb.pl = 'KHONG'),
             tg_agg_co_tong AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                       COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                       COUNT(DISTINCT CASE
                                                 WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                       COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                                FROM tg_labeled lb
                                WHERE lb.pl = 'CO'),
             tg_agg_co_chi_tiet AS (SELECT NVL(lb.tg_id, -1) AS tg_id_bucket,
                                           NVL(lb.TG_TEN, u'Kh\00f4ng r\00f5 t\00f4n gi\00e1o') AS tg_ten_bucket,
                                           COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                           COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                           COUNT(DISTINCT CASE
                                                     WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                           COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                                    FROM tg_labeled lb
                                    WHERE lb.pl = 'CO'
                                    GROUP BY NVL(lb.tg_id, -1), NVL(lb.TG_TEN, u'Kh\00f4ng r\00f5 t\00f4n gi\00e1o')),
             tg_co_chi_ordered AS (SELECT ac.*,
                                            ROW_NUMBER() OVER (ORDER BY QLPN.ORDER_HOTEN(TO_CHAR(ac.tg_ten_bucket)), ac.tg_id_bucket) AS co_ord
                                     FROM tg_agg_co_chi_tiet ac),
             tg_stacked AS (SELECT 10 AS sort_key,
                                   u'Kh\00f4ng c\00f3 t\00f4n gi\00e1o' AS lbl,
                                   k.nam,
                                   k.nu,
                                   k.khac,
                                   k.tong_so
                            FROM tg_agg_khong k
                            UNION ALL
                            SELECT 20,
                                   u'C\00f3 t\00f4n gi\00e1o',
                                   t.nam,
                                   t.nu,
                                   t.khac,
                                   t.tong_so
                            FROM tg_agg_co_tong t
                            UNION ALL
                            SELECT 30 + c.co_ord,
                                   TO_NCHAR(u'+ ') || TO_NCHAR(c.tg_ten_bucket),
                                   c.nam,
                                   c.nu,
                                   c.khac,
                                   c.tong_so
                            FROM tg_co_chi_ordered c),
             sec_ii9 AS (SELECT 11000000 + s.sort_key AS sort_thu_tu,
                                TO_NCHAR(u'II.9') AS ma_loai_thong_ke,
                                TO_NCHAR(u'Chi ti\1ebft - Theo t\00f4n gi\00e1o') AS loai_thong_ke,
                                TO_NCHAR(s.lbl) AS thong_ke_theo,
                                s.nam,
                                s.nu,
                                s.khac,
                                s.tong_so
                         FROM tg_stacked s),
             qt_labeled AS (SELECT ll.ID AS pham_nhan_id,
                                   dgt.GT_TEN,
                                   CASE
                                       WHEN dqt.QT_MA IS NOT NULL AND TRIM(dqt.QT_MA) <> '250' THEN 'NN'
                                       ELSE 'VN'
                                       END AS pl
                            FROM pham_nhan_filtered ll
                                     LEFT JOIN DM_GIOI_TINHS dgt
                                               ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                                   AND NVL(dgt.IS_DELETED, 0) = 0
                                     LEFT JOIN DM_QUOC_TICHS dqt
                                               ON ll.LL_DM_QUOC_TICH_ID = dqt.ID
                                                   AND NVL(dqt.IS_DELETED, 0) = 0),
             qt_agg_vn AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                  COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                  COUNT(DISTINCT CASE
                                            WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                  COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                           FROM qt_labeled lb
                           WHERE lb.pl = 'VN'),
             qt_agg_nn AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                  COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                  COUNT(DISTINCT CASE
                                            WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                  COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                           FROM qt_labeled lb
                           WHERE lb.pl = 'NN'),
             qt_stacked AS (SELECT 10 AS sort_key,
                                   u'Qu\1ed1c t\1ecbch Vi\1ec7t Nam' AS lbl,
                                   v.nam,
                                   v.nu,
                                   v.khac,
                                   v.tong_so
                            FROM qt_agg_vn v
                            UNION ALL
                            SELECT 20,
                                   u'Qu\1ed1c t\1ecbch n\01b0\1edbc ngo\00e0i',
                                   n.nam,
                                   n.nu,
                                   n.khac,
                                   n.tong_so
                            FROM qt_agg_nn n),
             sec_ii10 AS (SELECT 12000000 + s.sort_key AS sort_thu_tu,
                                 TO_NCHAR(u'II.10') AS ma_loai_thong_ke,
                                 TO_NCHAR(u'Chi ti\1ebft - Theo qu\1ed1c t\1ecbch') AS loai_thong_ke,
                                 TO_NCHAR(s.lbl) AS thong_ke_theo,
                                 s.nam,
                                 s.nu,
                                 s.khac,
                                 s.tong_so
                          FROM qt_stacked s),
             btv_labeled AS (SELECT ll.ID AS pham_nhan_id,
                                    dgt.GT_TEN,
                                    dbt.ID AS bt_id,
                                    dbt.NNC_TEN AS BT_TEN,
                                    CASE
                                        WHEN ll.LL_BENH_TAT_VAO_ID IS NULL
                                             OR (dbt.ID IS NOT NULL AND TRIM(TO_CHAR(dbt.NNC_MA)) = '4999')
                                            THEN 'KHONG'
                                        ELSE 'CO'
                                        END AS pl
                             FROM pham_nhan_filtered ll
                                      LEFT JOIN DM_GIOI_TINHS dgt
                                                ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                                    AND NVL(dgt.IS_DELETED, 0) = 0
                                      LEFT JOIN QLPN.DM_NGUYEN_NHAN_CHETS dbt
                                                ON ll.LL_BENH_TAT_VAO_ID = dbt.ID
                                                    AND NVL(dbt.IS_DELETED, 0) = 0),
             btv_agg_khong AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                      COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                      COUNT(DISTINCT CASE
                                                WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                      COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                               FROM btv_labeled lb
                               WHERE lb.pl = 'KHONG'),
             btv_agg_co_tong AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                        COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                        COUNT(DISTINCT CASE
                                                  WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                        COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                                 FROM btv_labeled lb
                                 WHERE lb.pl = 'CO'),
             btv_agg_co_chi_tiet AS (SELECT NVL(lb.bt_id, -1) AS bt_id_bucket,
                                            NVL(lb.BT_TEN, u'Kh\00f4ng r\00f5 b\1ec7nh') AS bt_ten_bucket,
                                            COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                            COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                            COUNT(DISTINCT CASE
                                                      WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                            COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                                     FROM btv_labeled lb
                                     WHERE lb.pl = 'CO'
                                     GROUP BY NVL(lb.bt_id, -1), NVL(lb.BT_TEN, u'Kh\00f4ng r\00f5 b\1ec7nh')),
             btv_co_chi_ordered AS (SELECT ac.*,
                                           ROW_NUMBER() OVER (ORDER BY QLPN.ORDER_HOTEN(TO_CHAR(ac.bt_ten_bucket)), ac.bt_id_bucket) AS co_ord
                                    FROM btv_agg_co_chi_tiet ac),
             btv_stacked AS (SELECT 10 AS sort_key,
                                    u'Kh\00f4ng b\1ec7nh t\1eadt' AS lbl,
                                    k.nam,
                                    k.nu,
                                    k.khac,
                                    k.tong_so
                             FROM btv_agg_khong k
                             UNION ALL
                             SELECT 20,
                                    u'C\00f3 b\1ec7nh t\1eadt',
                                    t.nam,
                                    t.nu,
                                    t.khac,
                                    t.tong_so
                             FROM btv_agg_co_tong t
                             UNION ALL
                             SELECT 30 + c.co_ord,
                                    TO_NCHAR(u'+ ') || TO_NCHAR(c.bt_ten_bucket),
                                    c.nam,
                                    c.nu,
                                    c.khac,
                                    c.tong_so
                             FROM btv_co_chi_ordered c),
             sec_ii11 AS (SELECT 13000000 + s.sort_key AS sort_thu_tu,
                                 TO_NCHAR(u'II.11') AS ma_loai_thong_ke,
                                 TO_NCHAR(u'Chi ti\1ebft - Theo b\1ec7nh t\1eadt khi v\00e0o') AS loai_thong_ke,
                                 TO_NCHAR(s.lbl) AS thong_ke_theo,
                                 s.nam,
                                 s.nu,
                                 s.khac,
                                 s.tong_so
                          FROM btv_stacked s),
             bht_labeled AS (SELECT ll.ID AS pham_nhan_id,
                                    dgt.GT_TEN,
                                    dbt.ID AS bt_id,
                                    dbt.BT_TEN,
                                    CASE
                                        WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL
                                             OR (dbt.ID IS NOT NULL AND TRIM(TO_CHAR(dbt.BT_MA)) = '1')
                                            THEN 'KHONG'
                                        ELSE 'CO'
                                        END AS pl
                             FROM pham_nhan_filtered ll
                                      LEFT JOIN DM_GIOI_TINHS dgt
                                                ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                                    AND NVL(dgt.IS_DELETED, 0) = 0
                                      LEFT JOIN DM_BENH_TATS dbt
                                                ON ll.LL_BENH_HIEN_TAI_ID = dbt.ID
                                                    AND NVL(dbt.IS_DELETED, 0) = 0),
             bht_agg_khong AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                      COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                      COUNT(DISTINCT CASE
                                                WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                      COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                               FROM bht_labeled lb
                               WHERE lb.pl = 'KHONG'),
             bht_agg_co_tong AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                        COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                        COUNT(DISTINCT CASE
                                                  WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                        COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                                 FROM bht_labeled lb
                                 WHERE lb.pl = 'CO'),
             bht_agg_co_chi_tiet AS (SELECT NVL(lb.bt_id, -1) AS bt_id_bucket,
                                            NVL(lb.BT_TEN, u'Kh\00f4ng r\00f5 b\1ec7nh') AS bt_ten_bucket,
                                            COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                            COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                            COUNT(DISTINCT CASE
                                                      WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                            COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                                     FROM bht_labeled lb
                                     WHERE lb.pl = 'CO'
                                     GROUP BY NVL(lb.bt_id, -1), NVL(lb.BT_TEN, u'Kh\00f4ng r\00f5 b\1ec7nh')),
             bht_co_chi_ordered AS (SELECT ac.*,
                                           ROW_NUMBER() OVER (ORDER BY QLPN.ORDER_HOTEN(TO_CHAR(ac.bt_ten_bucket)), ac.bt_id_bucket) AS co_ord
                                    FROM bht_agg_co_chi_tiet ac),
             bht_stacked AS (SELECT 10 AS sort_key,
                                    u'Kh\00f4ng b\1ec7nh t\1eadt' AS lbl,
                                    k.nam,
                                    k.nu,
                                    k.khac,
                                    k.tong_so
                             FROM bht_agg_khong k
                             UNION ALL
                             SELECT 20,
                                    u'C\00f3 b\1ec7nh t\1eadt',
                                    t.nam,
                                    t.nu,
                                    t.khac,
                                    t.tong_so
                             FROM bht_agg_co_tong t
                             UNION ALL
                             SELECT 30 + c.co_ord,
                                    TO_NCHAR(u'+ ') || TO_NCHAR(c.bt_ten_bucket),
                                    c.nam,
                                    c.nu,
                                    c.khac,
                                    c.tong_so
                             FROM bht_co_chi_ordered c),
             sec_ii12 AS (SELECT 14000000 + s.sort_key AS sort_thu_tu,
                                 TO_NCHAR(u'II.12') AS ma_loai_thong_ke,
                                 TO_NCHAR(u'Chi ti\1ebft - Theo b\1ec7nh t\1eadt hi\1ec7n t\1ea1i') AS loai_thong_ke,
                                 TO_NCHAR(s.lbl) AS thong_ke_theo,
                                 s.nam,
                                 s.nu,
                                 s.khac,
                                 s.tong_so
                          FROM bht_stacked s),
             gcr_raw AS (SELECT pn.ID AS pham_nhan_id,
                                REGEXP_REPLACE(NVL(TRIM(pn.LL_GHI_CHU_RIENG), ''), '[[:space:]\[\]]', '') AS gcr_clean,
                                ROW_NUMBER() OVER (ORDER BY pn.ID) AS row_id
                         FROM pham_nhan_filtered pn),
             gcr_ids AS (SELECT r.pham_nhan_id,
                                TO_NUMBER(REGEXP_SUBSTR(r.gcr_clean, '[0-9]+', 1, LEVEL)) AS gcr_id
                         FROM gcr_raw r
                         WHERE r.gcr_clean IS NOT NULL
                           AND REGEXP_COUNT(r.gcr_clean, '[0-9]+') > 0
                         CONNECT BY PRIOR r.pham_nhan_id = r.pham_nhan_id
                                AND PRIOR r.row_id = r.row_id
                                AND PRIOR SYS_GUID() IS NOT NULL
                                AND LEVEL <= REGEXP_COUNT(r.gcr_clean, '[0-9]+')),
             gcr_distinct AS (SELECT DISTINCT gi.pham_nhan_id,
                                              gi.gcr_id
                               FROM gcr_ids gi),
             gcr_named AS (SELECT gd.pham_nhan_id,
                                  gd.gcr_id,
                                  NVL(TO_NCHAR(g.GCR_TEN), u'Kh\00f4ng x\00e1c \0111\1ecbnh') AS gcr_ten
                           FROM gcr_distinct gd
                                    LEFT JOIN DM_GHI_CHU_RIENGS g
                                              ON g.ID = gd.gcr_id
                                                  AND NVL(g.IS_DELETED, 0) = 0),
             gcr_pn_combo AS (SELECT gn.pham_nhan_id,
                                     LISTAGG(gn.gcr_ten, u';' ON OVERFLOW TRUNCATE WITHOUT COUNT)
                                         WITHIN GROUP (ORDER BY gn.gcr_id) AS combo_lbl
                              FROM gcr_named gn
                              GROUP BY gn.pham_nhan_id),
             gcr_labeled AS (SELECT ll.ID AS pham_nhan_id,
                                    dgt.GT_TEN,
                                    CASE WHEN pc.pham_nhan_id IS NOT NULL THEN 'CO' ELSE 'KHONG' END AS pl,
                                    pc.combo_lbl
                             FROM pham_nhan_filtered ll
                                      LEFT JOIN DM_GIOI_TINHS dgt
                                                ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                                    AND NVL(dgt.IS_DELETED, 0) = 0
                                      LEFT JOIN gcr_pn_combo pc
                                                ON pc.pham_nhan_id = ll.ID),
             gcr_agg_khong AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                      COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                      COUNT(DISTINCT CASE
                                                WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                      COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                               FROM gcr_labeled lb
                               WHERE lb.pl = 'KHONG'),
             gcr_agg_co_tong AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                        COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                        COUNT(DISTINCT CASE
                                                  WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                        COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                                 FROM gcr_labeled lb
                                 WHERE lb.pl = 'CO'),
             gcr_agg_co_chi_tiet AS (SELECT NVL(lb.combo_lbl, u'Kh\00f4ng x\00e1c \0111\1ecbnh') AS ten_bucket,
                                            COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                            COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                            COUNT(DISTINCT CASE
                                                      WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                            COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                                     FROM gcr_labeled lb
                                     WHERE lb.pl = 'CO'
                                     GROUP BY NVL(lb.combo_lbl, u'Kh\00f4ng x\00e1c \0111\1ecbnh')),
             gcr_co_chi_ordered AS (SELECT ac.*,
                                            ROW_NUMBER() OVER (
                                                ORDER BY NLSSORT(SUBSTR(TO_CHAR(ac.ten_bucket), 1, 4000), 'NLS_SORT=BINARY_AI'),
                                                         ac.ten_bucket
                                                ) AS co_ord
                                     FROM gcr_agg_co_chi_tiet ac),
             gcr_stacked AS (SELECT 10 AS sort_key,
                                    u'Kh\00f4ng ghi ch\00fa ri\00eang' AS lbl,
                                    k.nam,
                                    k.nu,
                                    k.khac,
                                    k.tong_so
                             FROM gcr_agg_khong k
                             UNION ALL
                             SELECT 20,
                                    u'C\00f3 ghi ch\00fa ri\00eang',
                                    t.nam,
                                    t.nu,
                                    t.khac,
                                    t.tong_so
                             FROM gcr_agg_co_tong t
                             UNION ALL
                             SELECT 30 + c.co_ord,
                                    TO_NCHAR(u'+ ') || TO_NCHAR(c.ten_bucket),
                                    c.nam,
                                    c.nu,
                                    c.khac,
                                    c.tong_so
                             FROM gcr_co_chi_ordered c),
             sec_ii13 AS (SELECT 15000000 + s.sort_key AS sort_thu_tu,
                                 TO_NCHAR(u'II.13') AS ma_loai_thong_ke,
                                 TO_NCHAR(u'Chi ti\1ebft - Theo ghi ch\00fa ri\00eang') AS loai_thong_ke,
                                 TO_NCHAR(s.lbl) AS thong_ke_theo,
                                 s.nam,
                                 s.nu,
                                 s.khac,
                                 s.tong_so
                          FROM gcr_stacked s),
             dktt_labeled AS (SELECT ll.ID AS pham_nhan_id,
                                     dgt.GT_TEN,
                                     CASE
                                         WHEN dqt.QT_MA IS NOT NULL AND TRIM(dqt.QT_MA) <> '250' THEN 'NN'
                                         ELSE 'VN'
                                         END AS loai,
                                     dmtt.ID AS tinh_id,
                                     dmtt.TTP_TEN AS tinh_ten
                              FROM pham_nhan_filtered ll
                                       LEFT JOIN DM_GIOI_TINHS dgt
                                                 ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                                     AND NVL(dgt.IS_DELETED, 0) = 0
                                       LEFT JOIN DM_QUOC_TICHS dqt
                                                 ON ll.LL_DM_QUOC_TICH_ID = dqt.ID
                                                     AND NVL(dqt.IS_DELETED, 0) = 0
                                       LEFT JOIN DM_TINH_THANH_PHO dmtt
                                                 ON dmtt.ID = ll.LL_DIA_CHI_THUONG_TRU_PROVICE
                                                     AND NVL(dmtt.IS_DELETED, 0) = 0),
             dktt_agg_nn AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                    COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                    COUNT(DISTINCT CASE
                                              WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                    COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                             FROM dktt_labeled lb
                             WHERE lb.loai = 'NN'),
             dktt_agg_vn AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                    COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                    COUNT(DISTINCT CASE
                                              WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                    COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                             FROM dktt_labeled lb
                             WHERE lb.loai = 'VN'),
             dktt_agg_vn_chi_tiet AS (SELECT NVL(lb.tinh_id, -1) AS tinh_id_bucket,
                                             NVL(TO_NCHAR(lb.tinh_ten), TO_NCHAR('')) AS tinh_ten_bucket,
                                             COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                             COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                             COUNT(DISTINCT CASE
                                                       WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                             COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                                      FROM dktt_labeled lb
                                      WHERE lb.loai = 'VN'
                                      GROUP BY NVL(lb.tinh_id, -1), NVL(TO_NCHAR(lb.tinh_ten), TO_NCHAR(''))),
             dktt_vn_chi_ordered AS (SELECT ac.*,
                                             ROW_NUMBER() OVER (
                                                 ORDER BY NLSSORT(SUBSTR(TO_CHAR(ac.tinh_ten_bucket), 1, 4000), 'NLS_SORT=BINARY_AI'),
                                                          ac.tinh_id_bucket
                                                 ) AS vn_ord
                                      FROM dktt_agg_vn_chi_tiet ac),
             dktt_stacked AS (SELECT 10 AS sort_key,
                                     u'\0110KTT \1edf n\01b0\1edbc ngo\00e0i' AS lbl,
                                     n.nam,
                                     n.nu,
                                     n.khac,
                                     n.tong_so
                              FROM dktt_agg_nn n
                              UNION ALL
                              SELECT 20,
                                     u'\0110KTT t\1ea1i Vi\1ec7t Nam',
                                     v.nam,
                                     v.nu,
                                     v.khac,
                                     v.tong_so
                              FROM dktt_agg_vn v
                              UNION ALL
                              SELECT 30 + x.vn_ord,
                                     x.tinh_ten_bucket,
                                     x.nam,
                                     x.nu,
                                     x.khac,
                                     x.tong_so
                              FROM dktt_vn_chi_ordered x),
             sec_ii14 AS (SELECT 16000000 + s.sort_key AS sort_thu_tu,
                                 TO_NCHAR(u'II.14') AS ma_loai_thong_ke,
                                 TO_NCHAR(u'Chi ti\1ebft - Theo n\01a1i \0110KTT') AS loai_thong_ke,
                                 TO_NCHAR(s.lbl) AS thong_ke_theo,
                                 s.nam,
                                 s.nu,
                                 s.khac,
                                 s.tong_so
                          FROM dktt_stacked s),
             nct_labeled AS (SELECT ll.ID AS pham_nhan_id,
                                    dgt.GT_TEN,
                                    CASE
                                        WHEN dqt.QT_MA IS NOT NULL AND TRIM(dqt.QT_MA) <> '250' THEN 'NN'
                                        ELSE 'VN'
                                        END AS loai,
                                    dttp.ID AS tinh_id,
                                    dttp.TTP_TEN AS tinh_ten
                             FROM pham_nhan_filtered ll
                                      LEFT JOIN DM_GIOI_TINHS dgt
                                                ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                                                    AND NVL(dgt.IS_DELETED, 0) = 0
                                      LEFT JOIN DM_QUOC_TICHS dqt
                                                ON ll.LL_DM_QUOC_TICH_ID = dqt.ID
                                                    AND NVL(dqt.IS_DELETED, 0) = 0
                                      LEFT JOIN DM_TINH_THANH_PHO dttp
                                                ON dttp.ID = ll.LL_NOI_THA_VE_CU_TRU_PROVICE
                                                    AND NVL(dttp.IS_DELETED, 0) = 0),
             nct_agg_nn AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                   COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                   COUNT(DISTINCT CASE
                                             WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                   COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                            FROM nct_labeled lb
                            WHERE lb.loai = 'NN'),
             nct_agg_vn AS (SELECT COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                   COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                   COUNT(DISTINCT CASE
                                             WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                   COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                            FROM nct_labeled lb
                            WHERE lb.loai = 'VN'),
             nct_agg_vn_chi_tiet AS (SELECT NVL(lb.tinh_id, -1) AS tinh_id_bucket,
                                            NVL(TO_NCHAR(lb.tinh_ten), TO_NCHAR('')) AS tinh_ten_bucket,
                                            COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                                            COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                                            COUNT(DISTINCT CASE
                                                      WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                                            COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                                     FROM nct_labeled lb
                                     WHERE lb.loai = 'VN'
                                     GROUP BY NVL(lb.tinh_id, -1), NVL(TO_NCHAR(lb.tinh_ten), TO_NCHAR(''))),
             nct_vn_chi_ordered AS (SELECT ac.*,
                                           ROW_NUMBER() OVER (
                                               ORDER BY NLSSORT(SUBSTR(TO_CHAR(ac.tinh_ten_bucket), 1, 4000), 'NLS_SORT=BINARY_AI'),
                                                        ac.tinh_id_bucket
                                               ) AS vn_ord
                                    FROM nct_agg_vn_chi_tiet ac),
             nct_stacked AS (SELECT 10 AS sort_key,
                                    u'V\1ec1 c\01b0 tr\00fa n\01b0\1edbc ngo\00e0i' AS lbl,
                                    n.nam,
                                    n.nu,
                                    n.khac,
                                    n.tong_so
                             FROM nct_agg_nn n
                             UNION ALL
                             SELECT 20,
                                    u'V\1ec1 c\01b0 tr\00fa t\1ea1i Vi\1ec7t Nam',
                                    v.nam,
                                    v.nu,
                                    v.khac,
                                    v.tong_so
                             FROM nct_agg_vn v
                             UNION ALL
                             SELECT 30 + x.vn_ord,
                                    x.tinh_ten_bucket,
                                    x.nam,
                                    x.nu,
                                    x.khac,
                                    x.tong_so
                             FROM nct_vn_chi_ordered x),
             sec_ii15 AS (SELECT 17000000 + s.sort_key AS sort_thu_tu,
                                 TO_NCHAR(u'II.15') AS ma_loai_thong_ke,
                                 TO_NCHAR(u'Chi ti\1ebft - Theo n\01a1i v\1ec1 c\01b0 tr\00fa') AS loai_thong_ke,
                                 TO_NCHAR(s.lbl) AS thong_ke_theo,
                                 s.nam,
                                 s.nu,
                                 s.khac,
                                 s.tong_so
                          FROM nct_stacked s)

        SELECT z.sort_thu_tu,
               z.ma_loai_thong_ke,
               z.loai_thong_ke,
               z.thong_ke_theo,
               z.nam,
               z.nu,
               z.khac,
               z.tong_so
        FROM (
                 SELECT * FROM sec_i1
                 UNION ALL
                 SELECT * FROM sec_i2
                 UNION ALL
                 SELECT * FROM sec_ii1
                 UNION ALL
                 SELECT * FROM sec_ii2
                 UNION ALL
                 SELECT * FROM sec_ii3
                 UNION ALL
                 SELECT * FROM sec_ii4
                 UNION ALL
                 SELECT * FROM sec_ii5a
                 UNION ALL
                 SELECT * FROM sec_ii5b
                 UNION ALL
                 SELECT * FROM sec_ii6
                 UNION ALL
                 SELECT * FROM sec_ii7
                 UNION ALL
                 SELECT * FROM sec_ii8
                 UNION ALL
                 SELECT * FROM sec_ii9
                 UNION ALL
                 SELECT * FROM sec_ii10
                 UNION ALL
                 SELECT * FROM sec_ii11
                 UNION ALL
                 SELECT * FROM sec_ii12
                 UNION ALL
                 SELECT * FROM sec_ii13
                 UNION ALL
                 SELECT * FROM sec_ii14
                 UNION ALL
                 SELECT * FROM sec_ii15
             ) z
        ORDER BY z.sort_thu_tu;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_TONG_HOP_CHUNG;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_TONG_HOP_CHUONG_TOI_DANH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_TONG_HOP_CHUONG_TOI_DANH" (
    p_tu_ngay IN DATE,
    p_den_ngay IN DATE,
    p_trai_giam_id IN NVARCHAR2
) AS
    v_tu_ngay      DATE;
    v_den_ngay     DATE;
    v_trai_giam_id NUMBER;
    C1             SYS_REFCURSOR;
BEGIN
    -- ===== Normalize ngày =====
    -- Tr?i giam
    IF p_trai_giam_id IS NOT NULL THEN
        SELECT MIN(ID)
        INTO v_trai_giam_id
        FROM DM_TRAI_GIAMS
        WHERE TG_MA = p_trai_giam_id;
    ELSE
        v_trai_giam_id := NULL;
    END IF;
    -- Ngày t?
    IF EXTRACT(DAY FROM p_tu_ngay) < 15 THEN
        v_tu_ngay := TRUNC(ADD_MONTHS(p_tu_ngay, -1), 'MM') + 14; -- ngày 15 tháng tr??c
    ELSE
        v_tu_ngay := TRUNC(p_tu_ngay, 'MM') + 14; -- ngày 15 tháng hi?n t?i
    END IF;

    -- Ngày ??n
    IF EXTRACT(DAY FROM p_den_ngay) > 14 THEN
        v_den_ngay := TRUNC(ADD_MONTHS(p_den_ngay, 1), 'MM') + 13; -- ngày 14 tháng sau
    ELSE
        v_den_ngay := TRUNC(p_den_ngay, 'MM') + 13; -- ngày 14 tháng hi?n t?i
    END IF;

    OPEN C1 FOR
        WITH pham_nhan_filtered AS (SELECT pll.ID AS pham_nhan_id,
                                           pll.LL_DM_GIOI_TINH_ID,
                                           pll.LL_DM_HOC_VAN_ID,
                                           pll.LL_DM_NGHE_NGHIEP_ID,
                                           pll.LL_SO_TIEN_AN,
                                           pll.LL_SO_TIEN_SU,
                                           pll.CREATION_TIME,
                                           ptha.THA_THOI_GIAN_DA_CHAP_HANH,
                                           ptha.THA_THOI_GIAN_CON_LAI,
                                           ptha.THA_TOI_DANH
                                    FROM PN_LAI_LICHS pll
                                             INNER JOIN PN_THI_HANH_AN ptha
                                                        ON ptha.THA_PNLAI_LICH_ID = pll.ID
                                                            AND ptha.IS_DELETED = 0
                                             LEFT JOIN PN_DAC_XAS dxa
                                                       ON dxa.PNLAI_LICH_ID = pll.ID
                                                           AND dxa.IS_DELETED = 0
                                             LEFT JOIN GIAM_THOI_HANS gaan
                                                       ON gaan.PHAM_NHAN_ID = pll.ID
                                                           AND gaan.IS_DELETED = 0
                                             LEFT JOIN DM_TRAI_GIAMS dtg
                                                       ON dtg.ID = pll.LL_TRAI_GIAM_ID
                                                           AND dtg.IS_DELETED = 0
-- FILTER START
                                    WHERE
              NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0 AND (ptha.THA_NGAY_HET_HAN >= v_tu_ngay OR v_tu_ngay IS NULL)
                                      AND (v_den_ngay IS NULL OR TRUNC(ptha.THA_NGAY_DEN_TRAI) < v_den_ngay)
                                      AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
-- FILTER FINISH

             chi_tiet AS (SELECT ROW_NUMBER() OVER (ORDER BY
                 CASE
                     WHEN dctd.CTD_TEN IS NOT NULL
                         THEN dctd.CTD_TEN
                     ELSE u'Kh\00f4ng x\00e1c \0111\1ecbnh'
                     END
                 )                                                                                         AS SORT_ORDER,
                                 TO_CHAR(DENSE_RANK() OVER (ORDER BY NVL(dctd.CTD_TEN, 'Không xác ??nh')))       AS "TT",
                                 NVL(dctd.CTD_TEN, 'Không xác ??nh')                                       AS "ChuongToiDanh",
                                 COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN ll.PHAM_NHAN_ID END)    AS "Nam",
                                 COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN ll.PHAM_NHAN_ID END) AS "Nu",
                                 COUNT(DISTINCT CASE
                                                    WHEN dgt.GT_TEN IS NULL OR dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                                        THEN ll.PHAM_NHAN_ID
                                     END)                                                                  AS "Khac",
                                 COUNT(DISTINCT ll.PHAM_NHAN_ID)                                           AS "TongSo"
                          FROM pham_nhan_filtered ll
                                   LEFT JOIN DM_TOI_DANHS dtd
                                             ON dtd.ID = TO_NUMBER(REGEXP_SUBSTR(ll.THA_TOI_DANH, '[0-9]+', 1, 1))
                                   LEFT JOIN DM_CHUONG_TOI_DANHS dctd ON dctd.ID = dtd.TD_CHUONG
                                   LEFT JOIN DM_GIOI_TINHS dgt
                                             ON ll.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0

                          GROUP BY NVL(dctd.CTD_TEN, 'Không xác ??nh')
                          ORDER BY "TongSo" DESC, "ChuongToiDanh")

        SELECT "TT",
               "ChuongToiDanh",
               "Nam",
               "Nu",
               "Khac",
               "TongSo"
        FROM (SELECT SORT_ORDER,
                     "TT",
                     "ChuongToiDanh",
                     "Nam",
                     "Nu",
                     "Khac",
                     "TongSo"
              FROM chi_tiet

              UNION ALL

              SELECT 999,
                     TO_NCHAR(''),
                     TO_NCHAR(u'T\1ed5ng s\1ed1'),
                     SUM("Nam"),
                     SUM("Nu"),
                     SUM("Khac"),
                     SUM("TongSo")
              FROM chi_tiet)
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_TONG_HOP_CHUONG_TOI_DANH;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_TONG_HOP_DO_TUOI_PHAM_TOI_CHI_TIET
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_TONG_HOP_DO_TUOI_PHAM_TOI_CHI_TIET" (
    p_tu_ngay    IN DATE,
    p_den_ngay   IN DATE,
    p_trai_giam_id IN NUMBER
) AS
    v_tu_ngay  DATE;
    v_den_ngay DATE;
    C1         SYS_REFCURSOR;
BEGIN
    -- Normalize ngày t?
    IF EXTRACT(DAY FROM p_tu_ngay) < 15 THEN
        v_tu_ngay := TRUNC(ADD_MONTHS(p_tu_ngay, -1), 'MM') + 14;
    ELSE
        v_tu_ngay := TRUNC(p_tu_ngay, 'MM') + 14;
    END IF;

    -- Normalize ngày ??n
    IF EXTRACT(DAY FROM p_den_ngay) > 14 THEN
        v_den_ngay := TRUNC(ADD_MONTHS(p_den_ngay, 1), 'MM') + 13;
    ELSE
        v_den_ngay := TRUNC(p_den_ngay, 'MM') + 13;
    END IF;

    OPEN C1 FOR
        WITH pham_nhan_filtered AS (
            SELECT pll.ID  AS pham_nhan_id,
                   pll.LL_DM_GIOI_TINH_ID,
                   pll.LL_DM_HOC_VAN_ID,
                   pll.LL_DM_NGHE_NGHIEP_ID,
                   pll.LL_SO_TIEN_AN,
                   pll.LL_SO_TIEN_SU,
                   pll.CREATION_TIME,
                   ptha.THA_THOI_GIAN_DA_CHAP_HANH,
                   ptha.THA_THOI_GIAN_CON_LAI,
                   ptha.THA_TOI_DANH,
                   ptha.THA_NGAY_BAT,
                   ptha.THA_NGAY_DEN_TRAI,
                   CASE
                       WHEN REGEXP_LIKE(pll.LL_NGAY_SINH, '^\d{2}/\d{2}/\d{4}$')
                           THEN TO_DATE(pll.LL_NGAY_SINH, 'DD/MM/YYYY')
                       WHEN REGEXP_LIKE(pll.LL_NGAY_SINH, '^\d{4}$')
                           THEN TO_DATE('01/01/' || pll.LL_NGAY_SINH, 'DD/MM/YYYY')
                   END AS NGAY_SINH,
                   TRUNC(
                       MONTHS_BETWEEN(
                           SYSDATE,
                           CASE
                               WHEN REGEXP_LIKE(pll.LL_NGAY_SINH, '^\d{2}/\d{2}/\d{4}$')
                                   THEN TO_DATE(pll.LL_NGAY_SINH, 'DD/MM/YYYY')
                               WHEN REGEXP_LIKE(pll.LL_NGAY_SINH, '^\d{4}$')
                                   THEN TO_DATE('01/01/' || pll.LL_NGAY_SINH, 'DD/MM/YYYY')
                           END
                       ) / 12
                   ) AS TUOI_HIEN_TAI,
                   TRUNC(
                       MONTHS_BETWEEN(
                           ptha.THA_NGAY_BAT,
                           CASE
                               WHEN REGEXP_LIKE(pll.LL_NGAY_SINH, '^\d{2}/\d{2}/\d{4}$')
                                   THEN TO_DATE(pll.LL_NGAY_SINH, 'DD/MM/YYYY')
                               WHEN REGEXP_LIKE(pll.LL_NGAY_SINH, '^\d{4}$')
                                   THEN TO_DATE('01/01/' || pll.LL_NGAY_SINH, 'DD/MM/YYYY')
                           END
                       ) / 12
                   ) AS TUOI_PHAM_TOI
            FROM PN_LAI_LICHS pll
                INNER JOIN PN_THI_HANH_AN ptha
                    ON ptha.THA_PNLAI_LICH_ID = pll.ID
                    AND ptha.IS_DELETED = 0
                LEFT JOIN PN_DAC_XAS dxa
                    ON dxa.PNLAI_LICH_ID = pll.ID
                    AND dxa.IS_DELETED = 0
                LEFT JOIN GIAM_THOI_HANS gaan
                    ON gaan.PHAM_NHAN_ID = pll.ID
                    AND gaan.IS_DELETED = 0
                LEFT JOIN DM_TRAI_GIAMS dtg
                    ON dtg.ID = pll.LL_TRAI_GIAM_ID
                    AND dtg.IS_DELETED = 0
            WHERE
              NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0 AND (ptha.THA_NGAY_HET_HAN >= v_tu_ngay OR v_tu_ngay IS NULL)
              AND (v_den_ngay IS NULL OR TRUNC(ptha.THA_NGAY_DEN_TRAI) < v_den_ngay)
              AND (p_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam_id)
        ),

        ranges AS (
            SELECT 1 id, u'D\01b0\1edbi 14 tu\1ed5i' ten, 0 tu, 13 den FROM dual
            UNION ALL SELECT 2, u'T\1eeb 14 - d\01b0\1edbi 16 tu\1ed5i', 14, 15 FROM dual
            UNION ALL SELECT 3, u'T\1eeb 16 - d\01b0\1edbi 18 tu\1ed5i', 16, 17 FROM dual
            UNION ALL SELECT 4, u'T\1eeb 18 - d\01b0\1edbi 30 tu\1ed5i', 18, 29 FROM dual
            UNION ALL SELECT 5, u'T\1eeb 30 - d\01b0\1edbi 45 tu\1ed5i', 30, 44 FROM dual
            UNION ALL SELECT 6, u'T\1eeb 45 - d\01b0\1edbi 55 tu\1ed5i', 45, 54 FROM dual
            UNION ALL SELECT 7, u'T\1eeb 55 - d\01b0\1edbi 60 tu\1ed5i', 55, 59 FROM dual
            UNION ALL SELECT 8, u'T\1eeb 60 - d\01b0\1edbi 70 tu\1ed5i', 60, 69 FROM dual
            UNION ALL SELECT 9, u'T\1eeb 70 tu\1ed5i tr\1edf l\00ean', 70, 200 FROM dual
        ),

        chi_tiet AS (
            SELECT ROW_NUMBER() OVER (ORDER BY r.id)                    AS SORT_ORDER,
                   TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY r.id))) AS "TT",
                   TO_NCHAR(r.ten)                                      AS "DoTuoi",
                   COUNT(DISTINCT CASE
                       WHEN dgt.GT_TEN = u'Nam' THEN ll.PHAM_NHAN_ID
                   END)                                                 AS "Nam",
                   COUNT(DISTINCT CASE
                       WHEN dgt.GT_TEN = u'N\1eef' THEN ll.PHAM_NHAN_ID
                   END)                                                 AS "Nu",
                   COUNT(DISTINCT CASE
                       WHEN dgt.GT_TEN IS NULL
                           OR dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                           THEN ll.PHAM_NHAN_ID
                   END)                                                 AS "Khac",
                   COUNT(DISTINCT ll.PHAM_NHAN_ID)                      AS "TongSo"
            FROM pham_nhan_filtered ll
                LEFT JOIN ranges r
                    ON ll.TUOI_PHAM_TOI BETWEEN r.tu AND r.den
                LEFT JOIN DM_GIOI_TINHS dgt
                    ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
                    AND dgt.IS_DELETED = 0
            GROUP BY r.id, r.ten
        )

        SELECT "TT", "DoTuoi", "Nam", "Nu", "Khac", "TongSo"
        FROM (
            SELECT SORT_ORDER, "TT", "DoTuoi", "Nam", "Nu", "Khac", "TongSo"
            FROM chi_tiet
            UNION ALL
            SELECT 999,
                   TO_NCHAR(''),
                   TO_NCHAR(u'T\1ed5ng s\1ed1'),
                   SUM("Nam"),
                   SUM("Nu"),
                   SUM("Khac"),
                   SUM("TongSo")
            FROM chi_tiet
        )
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_THONG_KE_TONG_HOP_DO_TUOI_PHAM_TOI_CHI_TIET;

/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_TONG_HOP_PN_THEO_PHAN_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_TONG_HOP_PN_THEO_PHAN_TRAI" (
    p_tu_ngay IN DATE,
    p_den_ngay IN DATE,
    p_trai_giam_id IN NVARCHAR2
) AS
    v_tu_ngay      DATE;
    v_den_ngay     DATE;
    v_trai_giam_id NUMBER;
    C1             SYS_REFCURSOR;
BEGIN
    -- ===== Normalize =====
    -- Tr?i giam
    IF p_trai_giam_id IS NOT NULL THEN
        SELECT MIN(ID)
        INTO v_trai_giam_id
        FROM DM_TRAI_GIAMS
        WHERE TG_MA = p_trai_giam_id;
    ELSE
        v_trai_giam_id := NULL;
    END IF;

    IF EXTRACT(DAY FROM p_tu_ngay) < 15 THEN
        v_tu_ngay := TRUNC(ADD_MONTHS(p_tu_ngay, -1), 'MM') + 14; -- ngày 15 tháng tr??c
    ELSE
        v_tu_ngay := TRUNC(p_tu_ngay, 'MM') + 14; -- ngày 15 tháng hi?n t?i
    END IF;

    -- Ngày ??n
    IF EXTRACT(DAY FROM p_den_ngay) > 14 THEN
        v_den_ngay := TRUNC(ADD_MONTHS(p_den_ngay, 1), 'MM') + 13; -- ngày 14 tháng sau
    ELSE
        v_den_ngay := TRUNC(p_den_ngay, 'MM') + 13; -- ngày 14 tháng hi?n t?i
    END IF;

    OPEN C1 FOR
        WITH pham_nhan_filtered AS (SELECT pll.ID AS pham_nhan_id,
                                           pll.LL_DM_GIOI_TINH_ID,
                                           pll.LL_DM_HOC_VAN_ID,
                                           pll.LL_DM_NGHE_NGHIEP_ID,
                                           pll.LL_SO_TIEN_AN,
                                           pll.LL_SO_TIEN_SU,
                                           pll.CREATION_TIME,
                                           pll.LL_PHAN_TRAI_ID,
                                           ptha.THA_THOI_GIAN_DA_CHAP_HANH,
                                           ptha.THA_THOI_GIAN_CON_LAI
                                    FROM PN_LAI_LICHS pll
                                             INNER JOIN PN_THI_HANH_AN ptha
                                                        ON ptha.THA_PNLAI_LICH_ID = pll.ID
                                                            AND ptha.IS_DELETED = 0
                                             LEFT JOIN PN_DAC_XAS dxa
                                                       ON dxa.PNLAI_LICH_ID = pll.ID
                                                           AND dxa.IS_DELETED = 0
                                             LEFT JOIN GIAM_THOI_HANS gaan
                                                       ON gaan.PHAM_NHAN_ID = pll.ID
                                                           AND gaan.IS_DELETED = 0
                                             LEFT JOIN DM_TRAI_GIAMS dtg
                                                       ON dtg.ID = pll.LL_TRAI_GIAM_ID
                                                           AND dtg.IS_DELETED = 0
-- FILTER START
                                    WHERE
              NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0 AND (ptha.THA_NGAY_HET_HAN >= v_tu_ngay OR v_tu_ngay IS NULL)
                                      AND (v_den_ngay IS NULL OR TRUNC(ptha.THA_NGAY_DEN_TRAI) < v_den_ngay)
                                      AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
-- FILTER FINISH

             chi_tiet AS (SELECT ROW_NUMBER() OVER (ORDER BY
                 CASE
                     WHEN dpt.PT_TEN IS NOT NULL
                         THEN dpt.PT_TEN
                     ELSE u'Kh\00f4ng x\00e1c \0111\1ecbnh'
                     END
                 )                                                                   AS SORT_ORDER,
                                 TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY
                                     CASE
                                         WHEN dpt.PT_TEN IS NOT NULL
                                             THEN dpt.PT_TEN
                                         ELSE u'Kh\00f4ng x\00e1c \0111\1ecbnh'
                                         END
                                     )))                                             AS "TT",
                                 NVL(dpt.PT_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')  AS "PhanTrai",
                                 SUM(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 ELSE 0 END) AS "Nam",
                                 SUM(CASE WHEN gt.GT_TEN = u'N?' THEN 1 ELSE 0 END)  AS "Nu",
                                 SUM(CASE
                                         WHEN gt.GT_TEN IS NULL OR gt.GT_TEN NOT IN (u'Nam', u'N?') THEN 1
                                         ELSE 0 END)                                 AS "Khac",
                                 COUNT(*)                                            AS "TongSo"
                          FROM pham_nhan_filtered pn
                                   LEFT JOIN DM_PHAN_TRAIS dpt
                                             ON dpt.ID = pn.LL_PHAN_TRAI_ID
                                                 AND NVL(dpt.IS_DELETED, 0) = 0
                                   LEFT JOIN DM_GIOI_TINHS gt
                                             ON gt.ID = pn.LL_DM_GIOI_TINH_ID
                                                 AND NVL(gt.IS_DELETED, 0) = 0

                          GROUP BY dpt.PT_TEN)

        SELECT "TT",
               "PhanTrai",
               "Nam",
               "Nu",
               "Khac",
               "TongSo"
        FROM (SELECT SORT_ORDER,
                     "PhanTrai",
                     "TT",
                     "Nam",
                     "Nu",
                     "Khac",
                     "TongSo"
              FROM chi_tiet

              UNION ALL

              SELECT 999,
                     TO_NCHAR(''),
                     TO_NCHAR(u'T\1ed5ng s\1ed1'),
                     SUM("Nam"),
                     SUM("Nu"),
                     SUM("Khac"),
                     SUM("TongSo")
              FROM chi_tiet)
        ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_TONG_HOP_PN_THEO_PHAN_TRAI;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_TONG_HOP_VKS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_TONG_HOP_VKS" (
    p_tu_ngay      IN DATE DEFAULT NULL,
    p_den_ngay     IN DATE DEFAULT NULL,
    p_trai_giam_id IN NVARCHAR2 DEFAULT NULL
) AS
    v_tu_ngay      DATE;
    v_den_ngay     DATE;
    v_trai_giam_id NUMBER;
    C1             SYS_REFCURSOR;
BEGIN
    IF p_tu_ngay IS NULL AND p_den_ngay IS NULL THEN
        v_tu_ngay  := TRUNC(ADD_MONTHS(SYSDATE, -1), 'MM') + 14;
        v_den_ngay := TRUNC(SYSDATE, 'MM') + 13;
    ELSE
        v_tu_ngay  := NVL(p_tu_ngay, SYSDATE);
        v_den_ngay := NVL(p_den_ngay, SYSDATE);
    END IF;

    IF p_trai_giam_id IS NOT NULL THEN
        v_trai_giam_id := TO_NUMBER(p_trai_giam_id);
    ELSE
        v_trai_giam_id := NULL;
    END IF;

    OPEN C1 FOR
        WITH
            /* ===== Snapshot tr?ng thái FN (g?i 2 l?n/PN) r?i m?i bi?n ??ng / CHH ===== */
            pn_trang_thai AS (
                SELECT /*+ MATERIALIZE */
                       pll.ID AS pn_id,
                       QLPN.FN_GET_TINH_TRANG_TAI_NGAY_XET(pll.ID, v_tu_ngay - 1) AS tt_dau,
                       QLPN.FN_GET_TINH_TRANG_TAI_NGAY_XET(pll.ID, v_den_ngay) AS tt_cuoi
                FROM PN_LAI_LICHS pll
                WHERE NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                  AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
            pn_dau_ky AS (
                SELECT /*+ MATERIALIZE */ ts.pn_id AS ID
                FROM pn_trang_thai ts
                WHERE ts.tt_dau IN ('111', '112', '113', '114')),
            pham_nhan_filtered AS (
                SELECT /*+ MATERIALIZE */ pll.*
                FROM PN_LAI_LICHS pll
                         INNER JOIN pn_trang_thai ts ON ts.pn_id = pll.ID
                WHERE NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                  AND ts.tt_cuoi IN ('111', '112', '113', '114')),
            pn_ra_trong_ky AS (
                SELECT /*+ MATERIALIZE */ ts.pn_id AS ID
                FROM pn_trang_thai ts
                WHERE ts.tt_dau IN ('111', '112', '113', '114')
                  AND ts.tt_cuoi NOT IN ('111', '112', '113', '114')),
            pn_tang_trong_ky AS (
                SELECT /*+ MATERIALIZE */ ts.pn_id AS ID
                FROM pn_trang_thai ts
                WHERE ts.tt_cuoi IN ('111', '112', '113', '114')
                  AND ts.tt_dau NOT IN ('111', '112', '113', '114')),
            pn_giam_q3_2 AS (
                SELECT /*+ MATERIALIZE */ DISTINCT gth.PHAM_NHAN_ID AS pn_id
                FROM GIAM_THOI_HANS gth
                         INNER JOIN pn_ra_trong_ky r ON r.ID = gth.PHAM_NHAN_ID
                         JOIN PN_LAI_LICHS pll ON pll.ID = gth.PHAM_NHAN_ID AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                WHERE gth.NGAY_THA_GIAM_HET_AN >= v_tu_ngay
                  AND gth.NGAY_THA_GIAM_HET_AN < v_den_ngay
                  AND NVL(gth.IS_DELETED, 0) = 0
                  AND gth.MUC_GIAM_ID IS NOT NULL
                  AND gth.MUC_GIAM_ID NOT IN (SELECT ID
                                              FROM DM_MA_THOI_GIANS
                                              WHERE MTG_MA IN ('924000', '923000', '926000', '000000', '927000'))),
            pn_giam_q3_3 AS (
                SELECT /*+ MATERIALIZE */ DISTINCT gth.PHAM_NHAN_ID AS pn_id
                FROM GIAM_THOI_HANS gth
                         INNER JOIN pn_ra_trong_ky r ON r.ID = gth.PHAM_NHAN_ID
                         JOIN PN_LAI_LICHS pll ON pll.ID = gth.PHAM_NHAN_ID AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                WHERE gth.NGAY_THA_GIAM_HET_AN >= v_tu_ngay
                  AND gth.NGAY_THA_GIAM_HET_AN < v_den_ngay
                  AND NVL(gth.IS_DELETED, 0) = 0
                  AND gth.MUC_GIAM_ID IS NOT NULL
                  AND gth.MUC_GIAM_ID NOT IN (SELECT ID FROM DM_MA_THOI_GIANS WHERE MTG_MA = '923000')
                  AND NOT EXISTS (SELECT 1 FROM pn_giam_q3_2 g2 WHERE g2.pn_id = gth.PHAM_NHAN_ID)),
            pn_set_q3_1 AS (
                SELECT /*+ MATERIALIZE */ DISTINCT pktrt.KTRT_PN_LAI_LICH_ID AS pn_id
                FROM PN_KET_THUC_RA_TRAIS pktrt
                         INNER JOIN pn_ra_trong_ky r ON r.ID = pktrt.KTRT_PN_LAI_LICH_ID
                WHERE NVL(pktrt.IS_DELETED, 0) = 0
                  AND pktrt.KTRT_NGAY_THA >= v_tu_ngay
                  AND pktrt.KTRT_NGAY_THA < v_den_ngay
                  AND NOT EXISTS (SELECT 1 FROM pn_giam_q3_2 g2 WHERE g2.pn_id = r.ID)
                  AND NOT EXISTS (SELECT 1 FROM pn_giam_q3_3 g3 WHERE g3.pn_id = r.ID)),
            pn_tt_cuoi_ra AS (
                SELECT /*+ MATERIALIZE */ r.ID AS pn_id, ts.tt_cuoi AS tt_ma
                FROM pn_ra_trong_ky r
                         INNER JOIN pn_trang_thai ts ON ts.pn_id = r.ID
                WHERE NOT EXISTS (SELECT 1 FROM pn_giam_q3_2 g2 WHERE g2.pn_id = r.ID)
                  AND NOT EXISTS (SELECT 1 FROM pn_giam_q3_3 g3 WHERE g3.pn_id = r.ID)
                  AND NOT EXISTS (SELECT 1 FROM pn_set_q3_1 s1 WHERE s1.pn_id = r.ID)),
            pn_giam_uu_tien AS (
                SELECT pn_id, loai_giam
                FROM (SELECT t.pn_id,
                             CASE
                                 WHEN t.tt_ma IN ('171', '153', '144', '132') THEN 'q3_7'
                                 WHEN t.tt_ma IN ('131', '145', '154') THEN 'q3_6'
                                 WHEN t.tt_ma = '181' THEN 'q3_11'
                                 WHEN t.tt_ma = '127' THEN 'q3_14'
                                 WHEN t.tt_ma = '124' THEN 'q3_13'
                                 WHEN t.tt_ma IN ('161', '143', '156') THEN 'q3_10'
                                 WHEN t.tt_ma = '123' THEN 'q3_5'
                                 WHEN t.tt_ma = '126' THEN 'q3_4'
                                 WHEN t.tt_ma = '191' THEN 'q3_12'
                                 WHEN t.tt_ma IN ('141', '142', '145', '146', '147', '148', '149') THEN 'q3_8'
                                 WHEN t.tt_ma IN ('151', '152', '154', '155', '156', '157', '158', '159') THEN 'q3_9'
                                 WHEN t.tt_ma = '125' THEN 'q3_15'
                             END AS loai_giam
                      FROM pn_tt_cuoi_ra t) x
                WHERE x.loai_giam IS NOT NULL),
            pn_tang_phan_loai AS (
                SELECT t.ID AS pn_id,
                       CASE
                           WHEN EXISTS (SELECT 1
                                        FROM PN_CHUYEN_GIAO cg
                                        WHERE cg.PNCG_LAI_LICH_ID = t.ID
                                          AND cg.PNCG_NGAY_QDTHQDCG >= v_tu_ngay
                                          AND cg.PNCG_NGAY_QDTHQDCG < v_den_ngay
                                          AND NVL(cg.IS_DELETED, 0) = 0
                                          AND EXISTS (SELECT 1
                                                      FROM PN_THI_HANH_AN ptha
                                                               JOIN DM_TRAI_GIAMS dtg_nn
                                                                    ON dtg_nn.ID = ptha.THA_CHUYEN_DEN_TU_ID
                                                                        AND NVL(dtg_nn.IS_DELETED, 0) = 0
                                                      WHERE ptha.THA_PNLAI_LICH_ID = cg.PNCG_LAI_LICH_ID
                                                        AND NVL(ptha.IS_DELETED, 0) = 0
                                                        AND CAST(dtg_nn.TG_TEN AS NVARCHAR2(500)) =
                                                            u'Tr\1ea1i giam n\01b0\1edbc ngo\00e0i')) THEN 'q2_7'
                           WHEN EXISTS (SELECT 1
                                        FROM PN_THI_HANH_AN ptha
                                                 JOIN DM_TRAI_GIAMS dtg_ch ON dtg_ch.ID = ptha.THA_CHUYEN_DEN_TU_ID
                                            AND NVL(dtg_ch.IS_DELETED, 0) = 0
                                        WHERE ptha.THA_PNLAI_LICH_ID = t.ID
                                          AND NVL(ptha.IS_DELETED, 0) = 0
                                          AND ptha.THA_NGAY_DEN_TRAI >= v_tu_ngay
                                          AND ptha.THA_NGAY_DEN_TRAI < v_den_ngay
                                          AND CAST(dtg_ch.TG_TEN AS NVARCHAR2(4000)) LIKE u'%t\1ea1m%') THEN 'q2_1'
                           WHEN EXISTS (SELECT 1
                                        FROM PN_THI_HANH_AN ptha
                                                 JOIN DM_TRAI_GIAMS dtg_ch ON dtg_ch.ID = ptha.THA_CHUYEN_DEN_TU_ID
                                            AND NVL(dtg_ch.IS_DELETED, 0) = 0
                                        WHERE ptha.THA_PNLAI_LICH_ID = t.ID
                                          AND NVL(ptha.IS_DELETED, 0) = 0
                                          AND ptha.THA_NGAY_DEN_TRAI >= v_tu_ngay
                                          AND ptha.THA_NGAY_DEN_TRAI < v_den_ngay
                                          AND CAST(dtg_ch.TG_TEN AS NVARCHAR2(4000)) NOT LIKE u'%t\1ea1m%'
                                          AND CAST(dtg_ch.TG_TEN AS NVARCHAR2(4000)) NOT LIKE u'%n\01b0\1edbc%') THEN 'q2_2'
                           WHEN EXISTS (SELECT 1
                                        FROM TRON_TRAIS tt
                                        WHERE tt.PHAM_NHAN_ID = t.ID
                                          AND tt.NGAY_BAT_LAI >= v_tu_ngay
                                          AND tt.NGAY_BAT_LAI < v_den_ngay
                                          AND NVL(tt.IS_DELETED, 0) = 0) THEN 'q2_3'
                           WHEN EXISTS (SELECT 1
                                        FROM TAM_DINH_CHIS tdc
                                        WHERE tdc.PHAM_NHAN_ID = t.ID
                                          AND tdc.NGAY_LAI >= v_tu_ngay
                                          AND tdc.NGAY_LAI < v_den_ngay
                                          AND NVL(tdc.IS_DELETED, 0) = 0) THEN 'q2_4'
                           WHEN EXISTS (SELECT 1
                                        FROM TRICH_XUATS tx
                                        WHERE tx.PHAM_NHAN_ID = t.ID
                                          AND tx.TX_NGAY_TRA >= v_tu_ngay
                                          AND tx.TX_NGAY_TRA < v_den_ngay
                                          AND NVL(tx.IS_DELETED, 0) = 0) THEN 'q2_5'
                           WHEN EXISTS (SELECT 1
                                        FROM THA_CO_DIEU_KIENS tcdk
                                        WHERE tcdk.PHAM_NHAN_ID = t.ID
                                          AND tcdk.NGAY_BAT_LAI >= v_tu_ngay
                                          AND tcdk.NGAY_BAT_LAI < v_den_ngay
                                          AND NVL(tcdk.IS_DELETED, 0) = 0) THEN 'q2_6'
                           WHEN EXISTS (SELECT 1
                                        FROM CHUA_BENH_BAT_BUOCS cbbb
                                        WHERE cbbb.PHAM_NHAN_ID = t.ID
                                          AND cbbb.NGAY_KET_THUC >= v_tu_ngay
                                          AND cbbb.NGAY_KET_THUC < v_den_ngay
                                          AND NVL(cbbb.IS_DELETED, 0) = 0) THEN 'q2_8'
                       END AS loai_tang
                FROM pn_tang_trong_ky t),
            ptha_one AS (
                SELECT p.THA_PNLAI_LICH_ID,
                       p.THA_TOI_DANH,
                       p.THA_AN_PHAT,
                       p.THA_NGAY_BAT,
                       p.THA_NGAY_DEN_TRAI
                FROM (SELECT t.*,
                             ROW_NUMBER() OVER (PARTITION BY t.THA_PNLAI_LICH_ID ORDER BY t.ID DESC) AS rn
                      FROM PN_THI_HANH_AN t
                      WHERE NVL(t.IS_DELETED, 0) = 0
                        AND t.THA_PNLAI_LICH_ID IN (SELECT f.ID FROM pham_nhan_filtered f)) p
                WHERE p.rn = 1),
            q1 AS (
                SELECT u'CHUYEN' AS loai_thong_ke,
                       u'S\1ed1 k\1ef3 tr\01b0\1edbc chuy\1ec3n sang' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN pll.ID END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN pll.ID END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN pll.ID END) AS khac,
                       COUNT(DISTINCT pll.ID) AS tong_cong
                FROM pn_dau_ky pk
                         JOIN PN_LAI_LICHS pll ON pll.ID = pk.ID AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0),
            q2_1 AS (
                SELECT u'TANG' AS loai_thong_ke,
                       u'Tr\1ea1i t\1ea1m giam chuy\1ec3n \0111\1ebfn' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tp.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tp.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN tp.pn_id END) AS khac,
                       COUNT(DISTINCT tp.pn_id) AS tong_cong
                FROM pn_tang_phan_loai tp
                         JOIN PN_LAI_LICHS pll ON pll.ID = tp.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE tp.loai_tang = 'q2_1'),
            q2_2 AS (
                SELECT u'TANG' AS loai_thong_ke,
                       u'Tr\1ea1i giam kh\00e1c chuy\1ec3n \0111\1ebfn' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tp.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tp.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN tp.pn_id END) AS khac,
                       COUNT(DISTINCT tp.pn_id) AS tong_cong
                FROM pn_tang_phan_loai tp
                         JOIN PN_LAI_LICHS pll ON pll.ID = tp.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE tp.loai_tang = 'q2_2'),
            q2_3 AS (
                SELECT u'TANG' AS loai_thong_ke, u'Tr\1ed1n b\1eaft l\1ea1i' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tp.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tp.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN tp.pn_id END) AS khac,
                       COUNT(DISTINCT tp.pn_id) AS tong_cong
                FROM pn_tang_phan_loai tp
                         JOIN PN_LAI_LICHS pll ON pll.ID = tp.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE tp.loai_tang = 'q2_3'),
            q2_4 AS (
                SELECT u'TANG' AS loai_thong_ke, u'T\1ea1m \0111\00ecnh ch\1ec9 tr\1edf l\1ea1i' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tp.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tp.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN tp.pn_id END) AS khac,
                       COUNT(DISTINCT tp.pn_id) AS tong_cong
                FROM pn_tang_phan_loai tp
                         JOIN PN_LAI_LICHS pll ON pll.ID = tp.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE tp.loai_tang = 'q2_4'),
            q2_5 AS (
                SELECT u'TANG' AS loai_thong_ke, u'Tr\00edch xu\1ea5t tr\1ea3 l\1ea1i' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tp.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tp.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN tp.pn_id END) AS khac,
                       COUNT(DISTINCT tp.pn_id) AS tong_cong
                FROM pn_tang_phan_loai tp
                         JOIN PN_LAI_LICHS pll ON pll.ID = tp.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE tp.loai_tang = 'q2_5'),
            q2_6 AS (
                SELECT u'TANG' AS loai_thong_ke,
                       u'Tha tr\01b0\1edbc th\1eddi h\1ea1n c\00f3 \0111i\1ec1u ki\1ec7n tr\1edf l\1ea1i' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tp.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tp.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN tp.pn_id END) AS khac,
                       COUNT(DISTINCT tp.pn_id) AS tong_cong
                FROM pn_tang_phan_loai tp
                         JOIN PN_LAI_LICHS pll ON pll.ID = tp.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE tp.loai_tang = 'q2_6'),
            q2_7 AS (
                SELECT u'TANG' AS loai_thong_ke,
                       u'Chuy\1ec3n giao t\1eeb n\01b0\1edbc ngo\00e0i v\1ec1 thi h\00e0nh \00e1n' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tp.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tp.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN tp.pn_id END) AS khac,
                       COUNT(DISTINCT tp.pn_id) AS tong_cong
                FROM pn_tang_phan_loai tp
                         JOIN PN_LAI_LICHS pll ON pll.ID = tp.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE tp.loai_tang = 'q2_7'),
            q2_8 AS (
                SELECT u'TANG' AS loai_thong_ke, u'B\1eaft bu\1ed9c ch\1eefa b\1ec7nh tr\1edf l\1ea1i tr\1ea1i' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN tp.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN tp.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN tp.pn_id END) AS khac,
                       COUNT(DISTINCT tp.pn_id) AS tong_cong
                FROM pn_tang_phan_loai tp
                         JOIN PN_LAI_LICHS pll ON pll.ID = tp.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE tp.loai_tang = 'q2_8'),
            q2_all AS (
                SELECT u'TANG' AS loai_thong_ke, u'T\1ed5ng t\0103ng' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN t.ID END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN t.ID END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN t.ID END) AS khac,
                       COUNT(DISTINCT t.ID) AS tong_cong
                FROM pn_tang_trong_ky t
                         JOIN PN_LAI_LICHS pll ON pll.ID = t.ID AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0),
            q3_1 AS (
                SELECT u'GIAM' AS loai_thong_ke, u'H\1ebft th\1eddi h\1ea1n CHHPT, tr\1ea3 t\1ef1 do' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN s1.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN s1.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN s1.pn_id END) AS khac,
                       COUNT(DISTINCT s1.pn_id) AS tong_cong
                FROM pn_set_q3_1 s1
                         JOIN PN_LAI_LICHS pll ON pll.ID = s1.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0),
            q3_2 AS (
                SELECT u'GIAM' AS loai_thong_ke, u'\0110\01b0\1ee3c gi\1ea3m th\1eddi h\1ea1n CHHPT, tr\1ea3 t\1ef1 do' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN g2.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN g2.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN g2.pn_id END) AS khac,
                       COUNT(DISTINCT g2.pn_id) AS tong_cong
                FROM pn_giam_q3_2 g2
                         JOIN PN_LAI_LICHS pll ON pll.ID = g2.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0),
            q3_3 AS (
                SELECT u'GIAM' AS loai_thong_ke, u'\0110\01b0\1ee3c gi\1ea3m h\1ebft th\1eddi h\1ea1n CHHPT, tr\1ea3 t\1ef1 do' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN g3.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN g3.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN g3.pn_id END) AS khac,
                       COUNT(DISTINCT g3.pn_id) AS tong_cong
                FROM pn_giam_q3_3 g3
                         JOIN PN_LAI_LICHS pll ON pll.ID = g3.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0),
            q3_4 AS (
                SELECT u'GIAM' AS loai_thong_ke, u'Tha t\00f9 tr\01b0\1edbc th\1eddi h\1ea1n c\00f3 \0111i\1ec1u ki\1ec7n' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN gu.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN gu.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN gu.pn_id END) AS khac,
                       COUNT(DISTINCT gu.pn_id) AS tong_cong
                FROM pn_giam_uu_tien gu
                         JOIN PN_LAI_LICHS pll ON pll.ID = gu.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE gu.loai_giam = 'q3_4'),
            q3_5 AS (
