                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN gu.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN gu.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN gu.pn_id END) AS khac,
                       COUNT(DISTINCT gu.pn_id) AS tong_cong
                FROM pn_giam_uu_tien gu
                         JOIN PN_LAI_LICHS pll ON pll.ID = gu.pn_id AND NVL(pll.IS_DELETED, 0) = 0
