                WHERE gu.loai_giam = 'q3_7'),
            q3_8 AS (
                SELECT u'GIAM' AS loai_thong_ke, u'Tr\00edch xu\1ea5t' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN gu.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN gu.pn_id END) AS nu,
