                       COUNT(DISTINCT gu.pn_id) AS tong_cong
                FROM pn_giam_uu_tien gu
                         JOIN PN_LAI_LICHS pll ON pll.ID = gu.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE gu.loai_giam = 'q3_8'),
            q3_9 AS (
                SELECT u'GIAM' AS loai_thong_ke, u'T\1ea1m \0111\00ecnh ch\1ec9' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN gu.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN gu.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN gu.pn_id END) AS khac,
                       COUNT(DISTINCT gu.pn_id) AS tong_cong
                FROM pn_giam_uu_tien gu
                         JOIN PN_LAI_LICHS pll ON pll.ID = gu.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE gu.loai_giam = 'q3_9'),
            q3_10 AS (
                SELECT u'GIAM' AS loai_thong_ke, u'Chuy\1ec3n tr\1ea1i kh\00e1c' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN gu.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN gu.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN gu.pn_id END) AS khac,
                       COUNT(DISTINCT gu.pn_id) AS tong_cong
                FROM pn_giam_uu_tien gu
                         JOIN PN_LAI_LICHS pll ON pll.ID = gu.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE gu.loai_giam = 'q3_10'),
            q3_11 AS (
                SELECT u'GIAM' AS loai_thong_ke, u'H\1ee7y \00e1n' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN gu.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN gu.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN gu.pn_id END) AS khac,
                       COUNT(DISTINCT gu.pn_id) AS tong_cong
                FROM pn_giam_uu_tien gu
                         JOIN PN_LAI_LICHS pll ON pll.ID = gu.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE gu.loai_giam = 'q3_11'),
            q3_12 AS (
                SELECT u'GIAM' AS loai_thong_ke, u'Ho\00e3n thi h\00e0nh \00e1n' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN gu.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN gu.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN gu.pn_id END) AS khac,
                       COUNT(DISTINCT gu.pn_id) AS tong_cong
                FROM pn_giam_uu_tien gu
                         JOIN PN_LAI_LICHS pll ON pll.ID = gu.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE gu.loai_giam = 'q3_12'),
            q3_13 AS (
                SELECT u'GIAM' AS loai_thong_ke, u'Mi\1ec5n ch\1ea5p h\00e0nh \00e1n' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN gu.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN gu.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN gu.pn_id END) AS khac,
                       COUNT(DISTINCT gu.pn_id) AS tong_cong
                FROM pn_giam_uu_tien gu
                         JOIN PN_LAI_LICHS pll ON pll.ID = gu.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE gu.loai_giam = 'q3_13'),
            q3_14 AS (
                SELECT u'GIAM' AS loai_thong_ke, u'Chuy\1ec3n giao cho n\01b0\1edbc ngo\00e0i' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN gu.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN gu.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN gu.pn_id END) AS khac,
                       COUNT(DISTINCT gu.pn_id) AS tong_cong
                FROM pn_giam_uu_tien gu
                         JOIN PN_LAI_LICHS pll ON pll.ID = gu.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE gu.loai_giam = 'q3_14'),
            q3_15 AS (
                SELECT u'GIAM' AS loai_thong_ke, u'B\1eaft bu\1ed9c ch\1eefa b\1ec7nh' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN gu.pn_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN gu.pn_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN gu.pn_id END) AS khac,
                       COUNT(DISTINCT gu.pn_id) AS tong_cong
                FROM pn_giam_uu_tien gu
                         JOIN PN_LAI_LICHS pll ON pll.ID = gu.pn_id AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE gu.loai_giam = 'q3_15'),
            q3_all AS (
                SELECT u'GIAM' AS loai_thong_ke, u'T\1ed5ng gi\1ea3m' AS title,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN r.ID END) AS nam,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN r.ID END) AS nu,
                       COUNT(DISTINCT CASE WHEN dgt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN r.ID END) AS khac,
                       COUNT(DISTINCT r.ID) AS tong_cong
                FROM pn_ra_trong_ky r
                         JOIN PN_LAI_LICHS pll ON pll.ID = r.ID AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0),
            bd_tang AS (
                SELECT 1 AS ord, title, nam, nu, khac, tong_cong FROM q2_1
                UNION ALL SELECT 2, title, nam, nu, khac, tong_cong FROM q2_2
                UNION ALL SELECT 3, title, nam, nu, khac, tong_cong FROM q2_3
                UNION ALL SELECT 4, title, nam, nu, khac, tong_cong FROM q2_4
                UNION ALL SELECT 5, title, nam, nu, khac, tong_cong FROM q2_5
                UNION ALL SELECT 6, title, nam, nu, khac, tong_cong FROM q2_6
                UNION ALL SELECT 7, title, nam, nu, khac, tong_cong FROM q2_7
                UNION ALL SELECT 8, title, nam, nu, khac, tong_cong FROM q2_8
                UNION ALL SELECT 9, title, nam, nu, khac, tong_cong FROM q2_all),
            bd_giam AS (
                SELECT 1 AS ord, title, nam, nu, khac, tong_cong FROM q3_1
                UNION ALL SELECT 2, title, nam, nu, khac, tong_cong FROM q3_2
                UNION ALL SELECT 3, title, nam, nu, khac, tong_cong FROM q3_3
                UNION ALL SELECT 4, title, nam, nu, khac, tong_cong FROM q3_4
                UNION ALL SELECT 5, title, nam, nu, khac, tong_cong FROM q3_5
                UNION ALL SELECT 6, title, nam, nu, khac, tong_cong FROM q3_6
                UNION ALL SELECT 7, title, nam, nu, khac, tong_cong FROM q3_7
                UNION ALL SELECT 8, title, nam, nu, khac, tong_cong FROM q3_8
                UNION ALL SELECT 9, title, nam, nu, khac, tong_cong FROM q3_9
                UNION ALL SELECT 10, title, nam, nu, khac, tong_cong FROM q3_10
                UNION ALL SELECT 11, title, nam, nu, khac, tong_cong FROM q3_11
                UNION ALL SELECT 12, title, nam, nu, khac, tong_cong FROM q3_12
                UNION ALL SELECT 13, title, nam, nu, khac, tong_cong FROM q3_13
                UNION ALL SELECT 14, title, nam, nu, khac, tong_cong FROM q3_14
                UNION ALL SELECT 15, title, nam, nu, khac, tong_cong FROM q3_15
                UNION ALL SELECT 16, title, nam, nu, khac, tong_cong FROM q3_all),
            sec_i1 AS (
                SELECT 1000001 AS sort_thu_tu,
                       TO_NCHAR(u'I.1') AS ma_loai_thong_ke,
                       TO_NCHAR(u'Bi\1ebfn \0111\1ed9ng - th\00e1ng tr\01b0\1edbc chuy\1ec3n sang') AS loai_thong_ke,
                       TO_NCHAR(u'T\1ed5ng') AS thong_ke_theo,
                       NVL(q1.nam, 0) AS nam, NVL(q1.nu, 0) AS nu, NVL(q1.khac, 0) AS khac, NVL(q1.tong_cong, 0) AS tong_so
                FROM q1),
            sec_i2 AS (
                SELECT 2000000 + bt.ord AS sort_thu_tu,
                       TO_NCHAR(u'I.2') AS ma_loai_thong_ke,
                       TO_NCHAR(u'Bi\1ebfn \0111\1ed9ng - t\0103ng trong k\1ef3') AS loai_thong_ke,
                       TO_NCHAR(bt.title) AS thong_ke_theo,
                       NVL(bt.nam, 0) AS nam, NVL(bt.nu, 0) AS nu, NVL(bt.khac, 0) AS khac, NVL(bt.tong_cong, 0) AS tong_so
                FROM bd_tang bt),
            sec_i3 AS (
                SELECT 3000000 + bg.ord AS sort_thu_tu,
                       TO_NCHAR(u'I.3') AS ma_loai_thong_ke,
                       TO_NCHAR(u'Bi\1ebfn \0111\1ed9ng - gi\1ea3m trong k\1ef3') AS loai_thong_ke,
                       TO_NCHAR(bg.title) AS thong_ke_theo,
                       NVL(bg.nam, 0) AS nam, NVL(bg.nu, 0) AS nu, NVL(bg.khac, 0) AS khac, NVL(bg.tong_cong, 0) AS tong_so
                FROM bd_giam bg),

            /* ===== II. ?ang ch?p hành (dùng pham_nhan_filtered + ptha_one ? ??u WITH) ===== */
            sec_ii1 AS (
                SELECT 4000001 AS sort_thu_tu, TO_NCHAR(u'II.1') AS ma_loai_thong_ke,
                       TO_NCHAR(u'\0110ang ch\1ea5p h\00e0nh - T\1ed5ng') AS loai_thong_ke,
                       TO_NCHAR(u'T\1ed5ng') AS thong_ke_theo,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN pll.ID END) AS nam,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN pll.ID END) AS nu,
                       COUNT(DISTINCT CASE WHEN LOWER(NVL(dgt.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN pll.ID END) AS khac,
                       COUNT(DISTINCT pll.ID) AS tong_so
                FROM pham_nhan_filtered pll
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                UNION ALL
                SELECT 4000002, TO_NCHAR(u'II.1'),
                       TO_NCHAR(u'\0110ang ch\1ea5p h\00e0nh - T\1ed5ng'),
                       TO_NCHAR(u'Trong \0111\00f3 giam ri\00eang'),
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN pll.ID END),
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN pll.ID END),
                       COUNT(DISTINCT CASE WHEN LOWER(NVL(dgt.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN pll.ID END),
                       COUNT(DISTINCT pll.ID)
                FROM pham_nhan_filtered pll
                         LEFT JOIN DM_GIOI_TINHS dgt ON pll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE EXISTS (SELECT 1
                              FROM PN_GIAM_RIENGS g
                                       INNER JOIN DM_TINH_TRANG_PHAM_NHANS ttn
                                                  ON ttn.ID = pll.LL_TINH_TRANG_ID
                                                      AND NVL(ttn.IS_DELETED, 0) = 0
                              WHERE g.GR_PN_LAI_LICH_ID = pll.ID
                                AND NVL(g.IS_DELETED, 0) = 0
                                AND ttn.TTPN_MA LIKE '112%'
                                AND (g.GR_NGAY_KETTHUC IS NULL OR TRUNC(g.GR_NGAY_KETTHUC) >= v_den_ngay))),
            sec_ii2 AS (
                SELECT 5000000 + ROW_NUMBER() OVER (ORDER BY NVL(dpt.PT_TEN, u' '), dpt.ID) AS sort_thu_tu,
                       TO_NCHAR(u'II.2') AS ma_loai_thong_ke,
                       TO_NCHAR(u'\0110ang ch\1ea5p h\00e0nh - Theo ph\00e2n tr\1ea1i') AS loai_thong_ke,
                       CASE WHEN dpt.PT_TEN IS NULL THEN TO_NCHAR(u'Ch\01b0a ph\00e2n tr\1ea1i')
                            ELSE TO_NCHAR(dpt.PT_TEN) END AS thong_ke_theo,
                       COUNT(DISTINCT CASE WHEN LOWER(gt.GT_TEN) = u'nam' THEN pn.ID END) AS nam,
                       COUNT(DISTINCT CASE WHEN LOWER(gt.GT_TEN) = u'n\1eef' THEN pn.ID END) AS nu,
                       COUNT(DISTINCT CASE WHEN LOWER(NVL(gt.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN pn.ID END) AS khac,
                       COUNT(DISTINCT pn.ID) AS tong_so
                FROM pham_nhan_filtered pn
                         LEFT JOIN DM_PHAN_TRAIS dpt ON dpt.ID = pn.LL_PHAN_TRAI_ID AND NVL(dpt.IS_DELETED, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS gt ON gt.ID = pn.LL_DM_GIOI_TINH_ID AND NVL(gt.IS_DELETED, 0) = 0
                GROUP BY dpt.PT_TEN, dpt.ID),
            pn_ptha_labeled AS (
                SELECT pll.ID AS pham_nhan_id,
                       pll.LL_DM_GIOI_TINH_ID,
                       ptha.THA_NGAY_BAT,
                       ptha.THA_AN_PHAT,
                       ptha.THA_TOI_DANH,
                       CASE
                           WHEN ptha.THA_TOI_DANH IS NOT NULL
                                AND TRIM(ptha.THA_TOI_DANH) IS NOT NULL
                                AND REGEXP_LIKE(
                                    TRIM(REGEXP_SUBSTR(
                                        REPLACE(REPLACE(TRIM(ptha.THA_TOI_DANH), '[', ''), ']', ''),
                                        '[^,]+', 1, 1)),
                                    '^[0-9]+$')
                               THEN TO_NUMBER(TRIM(REGEXP_SUBSTR(
                                   REPLACE(REPLACE(TRIM(ptha.THA_TOI_DANH), '[', ''), ']', ''),
                                   '[^,]+', 1, 1)))
                           END AS toi_danh_id_dau,
                       CASE
                           WHEN pll.LL_NGAY_SINH IS NULL OR TRIM(pll.LL_NGAY_SINH) IS NULL THEN NULL
                           WHEN REGEXP_LIKE(TRIM(pll.LL_NGAY_SINH), '^\d{1,2}/\d{1,2}/\d{4}$')
                               THEN TO_DATE(TRIM(pll.LL_NGAY_SINH), 'DD/MM/YYYY')
                           WHEN REGEXP_LIKE(TRIM(pll.LL_NGAY_SINH), '^\d{1,2}/\d{4}$')
                               THEN TO_DATE('01/' || TRIM(pll.LL_NGAY_SINH), 'DD/MM/YYYY')
                           WHEN REGEXP_LIKE(TRIM(pll.LL_NGAY_SINH), '^\d{4}$')
                               THEN TO_DATE('01/01/' || TRIM(pll.LL_NGAY_SINH), 'DD/MM/YYYY')
                           ELSE NULL
                           END AS ngay_sinh
                FROM pham_nhan_filtered pll
                         INNER JOIN ptha_one ptha ON ptha.THA_PNLAI_LICH_ID = pll.ID),
            pn_muc AS (
                SELECT pl.pham_nhan_id, pl.LL_DM_GIOI_TINH_ID, pl.THA_AN_PHAT
                FROM pn_ptha_labeled pl),
            co_thang_muc AS (
                SELECT ll.pham_nhan_id, ll.LL_DM_GIOI_TINH_ID, ll.THA_AN_PHAT,
                       (NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(ll.THA_AN_PHAT AS NVARCHAR2(2000)), 'NAM'), 0) * 12
                        + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(ll.THA_AN_PHAT AS NVARCHAR2(2000)), 'THANG'), 0)
                        + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(CAST(ll.THA_AN_PHAT AS NVARCHAR2(2000)), 'NGAY'), 0) / 30.0) AS tha_thang_tong
                FROM pn_muc ll),
            phan_loai_muc AS (
                SELECT c.*,
                       CASE
                           WHEN UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) LIKE '%CHUNGTHAN%'
                                AND UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) NOT LIKE '%GIAMXUONG%'
                               THEN 1
                           WHEN LOWER(TRIM(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) = u'chung th\00e2n gi\1ea3m xu\1ed1ng 30 n\0103m'
                                OR (UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) LIKE '%CHUNGTHAN%'
                                    AND UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) LIKE '%GIAMXUONG%'
                                    AND REGEXP_LIKE(UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))), '30.*NAM|NAM.*30'))
                               THEN 2
                           WHEN LOWER(TRIM(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) = u'chung th\00e2n gi\1ea3m xu\1ed1ng 20 n\0103m'
                                OR (UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) LIKE '%CHUNGTHAN%'
                                    AND UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))) LIKE '%GIAMXUONG%'
                                    AND REGEXP_LIKE(UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(c.THA_AN_PHAT), u''))), '20.*NAM|NAM.*20'))
                               THEN 3
                           WHEN c.tha_thang_tong > 360 THEN 2
                           WHEN c.tha_thang_tong > 240 AND c.tha_thang_tong <= 360 THEN 2
                           WHEN c.tha_thang_tong > 180 AND c.tha_thang_tong <= 240 THEN 3
                           WHEN c.tha_thang_tong > 84 AND c.tha_thang_tong <= 180 THEN 4
                           WHEN c.tha_thang_tong > 36 AND c.tha_thang_tong <= 84 THEN 5
                           WHEN c.tha_thang_tong > 0 AND c.tha_thang_tong <= 36 THEN 6
                           ELSE NULL END AS muc_id
                FROM co_thang_muc c),
            all_muc AS (
                SELECT 1 AS muc_id, u'Chung th\00e2n' AS muc_ten FROM dual
                UNION ALL SELECT 2, u'Tr\00ean 20 - \0111\1ebfn 30 n\0103m' FROM dual
                UNION ALL SELECT 3, u'Tr\00ean 15 - \0111\1ebfn 20 n\0103m' FROM dual
                UNION ALL SELECT 4, u'Tr\00ean 7 - \0111\1ebfn 15 n\0103m' FROM dual
                UNION ALL SELECT 5, u'Tr\00ean 3 - \0111\1ebfn 7 n\0103m' FROM dual
                UNION ALL SELECT 6, u'T\1eeb 3 n\0103m tr\1edf xu\1ed1ng' FROM dual),
            stats_muc AS (
                SELECT pl.muc_id,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN pl.pham_nhan_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN pl.pham_nhan_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) NOT IN (u'nam', u'n\1eef') THEN pl.pham_nhan_id END) AS khac,
                       COUNT(DISTINCT pl.pham_nhan_id) AS tong
                FROM phan_loai_muc pl
                         LEFT JOIN DM_GIOI_TINHS dgt ON dgt.ID = pl.LL_DM_GIOI_TINH_ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE pl.muc_id IS NOT NULL
                GROUP BY pl.muc_id),
            sec_ii3 AS (
                SELECT 6000000 + am.muc_id AS sort_thu_tu,
                       TO_NCHAR(u'II.3') AS ma_loai_thong_ke,
                       TO_NCHAR(u'\0110ang ch\1ea5p h\00e0nh - Theo m\1ee9c \00e1n') AS loai_thong_ke,
                       TO_NCHAR(am.muc_ten) AS thong_ke_theo,
                       NVL(sm.nam, 0) AS nam, NVL(sm.nu, 0) AS nu, NVL(sm.khac, 0) AS khac, NVL(sm.tong, 0) AS tong_so
                FROM all_muc am
                         LEFT JOIN stats_muc sm ON sm.muc_id = am.muc_id),
            pn_do_tuoi AS (
                SELECT x.pham_nhan_id,
                       x.LL_DM_GIOI_TINH_ID,
                       TRUNC(MONTHS_BETWEEN(v_den_ngay, x.ngay_sinh) / 12) AS tuoi_hien_tai,
                       TRUNC(MONTHS_BETWEEN(x.THA_NGAY_BAT, x.ngay_sinh) / 12) AS tuoi_pham_toi
                FROM pn_ptha_labeled x),
            ranges_tuoi_ht AS (
                SELECT 1 id, u'D\01b0\1edbi 18 tu\1ed5i' ten, 0 tu, 17 den FROM dual
                UNION ALL SELECT 2, u'T\1eeb 18 - d\01b0\1edbi 30 tu\1ed5i', 18, 29 FROM dual
                UNION ALL SELECT 3, u'T\1eeb 30 - d\01b0\1edbi 45 tu\1ed5i', 30, 44 FROM dual
                UNION ALL SELECT 4, u'T\1eeb 45 - 55 tu\1ed5i', 45, 55 FROM dual
                UNION ALL SELECT 5, u'Tr\00ean 55 - 60 tu\1ed5i', 56, 60 FROM dual
                UNION ALL SELECT 6, u'Tr\00ean 60 - d\01b0\1edbi 70 tu\1ed5i', 61, 69 FROM dual
                UNION ALL SELECT 7, u'T\1eeb 70 tu\1ed5i tr\1edf l\00ean', 70, 200 FROM dual),
            ranges_tuoi_pt AS (
                SELECT 1 id, u'D\01b0\1edbi 14 tu\1ed5i' ten, 0 tu, 13 den FROM dual
                UNION ALL SELECT 2, u'T\1eeb 14 - d\01b0\1edbi 16 tu\1ed5i', 14, 15 FROM dual
                UNION ALL SELECT 3, u'T\1eeb 16 - d\01b0\1edbi 18 tu\1ed5i', 16, 17 FROM dual
                UNION ALL SELECT 4, u'T\1eeb 18 - d\01b0\1edbi 30 tu\1ed5i', 18, 29 FROM dual
                UNION ALL SELECT 5, u'T\1eeb 30 - d\01b0\1edbi 45 tu\1ed5i', 30, 44 FROM dual
                UNION ALL SELECT 6, u'T\1eeb 45 - d\01b0\1edbi 55 tu\1ed5i', 45, 54 FROM dual
                UNION ALL SELECT 7, u'T\1eeb 55 - d\01b0\1edbi 60 tu\1ed5i', 55, 59 FROM dual
                UNION ALL SELECT 8, u'T\1eeb 60 - d\01b0\1edbi 70 tu\1ed5i', 60, 69 FROM dual
                UNION ALL SELECT 9, u'T\1eeb 70 tu\1ed5i tr\1edf l\00ean', 70, 200 FROM dual),
            sec_ii4 AS (
                SELECT 7000000 + r.id AS sort_thu_tu, TO_NCHAR(u'II.4') AS ma_loai_thong_ke,
                       TO_NCHAR(u'\0110ang ch\1ea5p h\00e0nh - theo \0111\1ed9 tu\1ed5i hi\1ec7n t\1ea1i') AS loai_thong_ke,
                       TO_NCHAR(r.ten) AS thong_ke_theo,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN ll.pham_nhan_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN ll.pham_nhan_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) NOT IN (u'nam', u'n\1eef') THEN ll.pham_nhan_id END) AS khac,
                       COUNT(DISTINCT ll.pham_nhan_id) AS tong_so
                FROM pn_do_tuoi ll
                         INNER JOIN ranges_tuoi_ht r ON ll.tuoi_hien_tai BETWEEN r.tu AND r.den
                         LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                GROUP BY r.id, r.ten),
            sec_ii5 AS (
                SELECT 8000000 + r.id AS sort_thu_tu, TO_NCHAR(u'II.5') AS ma_loai_thong_ke,
                       TO_NCHAR(u'\0110ang ch\1ea5p h\00e0nh - theo \0111\1ed9 tu\1ed5i l\00fac ph\1ea1m t\1ed9i') AS loai_thong_ke,
                       TO_NCHAR(r.ten) AS thong_ke_theo,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN ll.pham_nhan_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN ll.pham_nhan_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) NOT IN (u'nam', u'n\1eef') THEN ll.pham_nhan_id END) AS khac,
                       COUNT(DISTINCT ll.pham_nhan_id) AS tong_so
                FROM pn_do_tuoi ll
                         INNER JOIN ranges_tuoi_pt r ON ll.tuoi_pham_toi BETWEEN r.tu AND r.den
                         LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                GROUP BY r.id, r.ten),
            con_trong_trai AS (
                SELECT tncc.ID AS con_id, tncc.GIOI_TINH_ID,
                       TRUNC(MONTHS_BETWEEN(NVL(v_den_ngay, SYSDATE),
                           CASE
                               WHEN tncc.NGAY_SINH IS NULL THEN NULL
                               WHEN REGEXP_LIKE(tncc.NGAY_SINH, '^\d{2}/\d{2}/\d{4}$') THEN TO_DATE(tncc.NGAY_SINH, 'DD/MM/YYYY')
                               WHEN REGEXP_LIKE(tncc.NGAY_SINH, '^\d{2}/\d{4}$') THEN TO_DATE('01/' || tncc.NGAY_SINH, 'DD/MM/YYYY')
                               WHEN REGEXP_LIKE(tncc.NGAY_SINH, '^\d{4}$') THEN TO_DATE('01/01/' || tncc.NGAY_SINH, 'DD/MM/YYYY')
                               ELSE NULL END)) AS tuoi_thang
                FROM THAN_NHAN_CON_CAIS tncc
                         INNER JOIN pham_nhan_filtered ll ON ll.ID = tncc.PHAM_NHAN_ID
                WHERE NVL(tncc.IS_DELETED, 0) = 0
                  AND TRUNC(tncc.NGAY_DEN) < v_den_ngay
                  AND (tncc.NGAY_RA IS NULL OR TRUNC(tncc.NGAY_RA) > v_den_ngay)),
            ranges_con AS (
                SELECT 1 id, u'D\01b0\1edbi 24 th\00e1ng tu\1ed5i' ten, 0 thang_tu, 23 thang_den FROM dual
                UNION ALL SELECT 2, u'T\1eeb 24 - d\01b0\1edbi 36 th\00e1ng tu\1ed5i', 24, 35 FROM dual
                UNION ALL SELECT 3, u'T\1eeb 36 th\00e1ng tu\1ed5i tr\1edf l\00ean', 36, 999999 FROM dual),
            sec_ii6 AS (
                SELECT 9000000 + r.id AS sort_thu_tu, TO_NCHAR(u'II.6') AS ma_loai_thong_ke,
                       TO_NCHAR(u'Con ph\1ea1m nh\00e2n \0111ang trong tr\1ea1i') AS loai_thong_ke,
                       TO_NCHAR(r.ten) AS thong_ke_theo,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN c.con_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN c.con_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN LOWER(NVL(dgt.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN c.con_id END) AS khac,
                       COUNT(DISTINCT c.con_id) AS tong_so
                FROM ranges_con r
                         LEFT JOIN con_trong_trai c ON c.tuoi_thang IS NOT NULL AND c.tuoi_thang BETWEEN r.thang_tu AND r.thang_den
                         LEFT JOIN DM_GIOI_TINHS dgt ON dgt.ID = c.GIOI_TINH_ID AND NVL(dgt.IS_DELETED, 0) = 0
                GROUP BY r.id, r.ten),
            pn_chuong AS (
                SELECT pl.pham_nhan_id, pl.LL_DM_GIOI_TINH_ID, pl.toi_danh_id_dau
                FROM pn_ptha_labeled pl),
            stats_theo_chuong AS (
                SELECT dctd.ID AS chuong_id,
                       dctd.CTD_TEN AS chuong_ten,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN ll.pham_nhan_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN ll.pham_nhan_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN LOWER(NVL(dgt.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN ll.pham_nhan_id END) AS khac,
                       COUNT(DISTINCT ll.pham_nhan_id) AS tong
                FROM pn_chuong ll
                         LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = ll.toi_danh_id_dau AND NVL(dtd.IS_DELETED, 0) = 0
                         INNER JOIN DM_CHUONG_TOI_DANHS dctd
                                    ON TRIM(TO_CHAR(dctd.CTD_MA)) = TRIM(TO_CHAR(dtd.TD_CHUONG))
                                        AND NVL(dctd.IS_DELETED, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                GROUP BY dctd.ID, dctd.CTD_TEN),
            stats_chuong_kxd AS (
                SELECT COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN ll.pham_nhan_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN ll.pham_nhan_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN LOWER(NVL(dgt.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN ll.pham_nhan_id END) AS khac,
                       COUNT(DISTINCT ll.pham_nhan_id) AS tong
                FROM pn_chuong ll
                         LEFT JOIN DM_TOI_DANHS dtd ON dtd.ID = ll.toi_danh_id_dau AND NVL(dtd.IS_DELETED, 0) = 0
                         LEFT JOIN DM_CHUONG_TOI_DANHS dctd
                                   ON TRIM(TO_CHAR(dctd.CTD_MA)) = TRIM(TO_CHAR(dtd.TD_CHUONG))
                                       AND NVL(dctd.IS_DELETED, 0) = 0
                         LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE dctd.ID IS NULL),
            dong_chuong_ii7 AS (
                SELECT st.chuong_ten, st.nam, st.nu, st.khac, st.tong
                FROM stats_theo_chuong st
                WHERE NVL(st.tong, 0) > 0
                UNION ALL
                SELECT u'Kh\00f4ng x\00e1c \0111\1ecbnh', kx.nam, kx.nu, kx.khac, kx.tong
                FROM stats_chuong_kxd kx
                WHERE NVL(kx.tong, 0) > 0),
            sec_ii7 AS (
                SELECT 10000000 + ROW_NUMBER() OVER (ORDER BY dc.tong DESC, dc.chuong_ten) AS sort_thu_tu,
                       TO_NCHAR(u'II.7') AS ma_loai_thong_ke,
                       TO_NCHAR(u'Ph\00e2n t\00edch t\1ed9i danh theo ch\01b0\01a1ng') AS loai_thong_ke,
                       TO_NCHAR(dc.chuong_ten) AS thong_ke_theo,
                       dc.nam, dc.nu, dc.khac, dc.tong AS tong_so
                FROM dong_chuong_ii7 dc),
            /* II.8 — logic SP_GET_THONG_KE_TONG_HOP_BENH_HIEM_NGHEO (nhóm theo BT_TEN + T?ng s?) */
            ptha_den_trai_ky AS (
                SELECT p.THA_PNLAI_LICH_ID
                FROM (SELECT t.THA_PNLAI_LICH_ID,
                             ROW_NUMBER() OVER (PARTITION BY t.THA_PNLAI_LICH_ID ORDER BY t.ID DESC) AS rn
                      FROM PN_THI_HANH_AN t
                      WHERE NVL(t.IS_DELETED, 0) = 0
                        AND (t.THA_NGAY_DEN_TRAI >= v_tu_ngay OR v_tu_ngay IS NULL)
                        AND (t.THA_NGAY_DEN_TRAI <= v_den_ngay OR v_den_ngay IS NULL)) p
                WHERE p.rn = 1),
            pn_benh_hiem AS (
                SELECT ll.ID AS pham_nhan_id,
                       ll.LL_DM_GIOI_TINH_ID,
                       ll.LL_BENH_HIEN_TAI_ID
                FROM PN_LAI_LICHS ll
                         INNER JOIN ptha_den_trai_ky pt ON pt.THA_PNLAI_LICH_ID = ll.ID
                WHERE NVL(ll.IS_DELETED, 0) = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
                  AND (v_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
            benh_hiem_chi_tiet AS (
                SELECT dmbt.BT_TEN AS benh_ten,
                       COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'Nam' THEN pn.pham_nhan_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'N\1eef' THEN pn.pham_nhan_id END) AS nu,
                       COUNT(DISTINCT CASE
                                  WHEN NVL(gt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef')
                                      THEN pn.pham_nhan_id END) AS khac,
                       COUNT(DISTINCT pn.pham_nhan_id) AS tong_so
                FROM pn_benh_hiem pn
                         INNER JOIN DM_BENH_TATS dmbt
                                    ON dmbt.ID = pn.LL_BENH_HIEN_TAI_ID
                                        AND NVL(dmbt.IS_DELETED, 0) = 0
                                        AND TRIM(TO_CHAR(dmbt.BT_MA)) <> u'1'
                         LEFT JOIN DM_GIOI_TINHS gt
                                   ON gt.ID = pn.LL_DM_GIOI_TINH_ID
                                       AND NVL(gt.IS_DELETED, 0) = 0
                GROUP BY dmbt.BT_TEN),
            sec_ii8 AS (
                SELECT 11000000 + ROW_NUMBER() OVER (ORDER BY bh.tong_so DESC, bh.benh_ten) AS sort_thu_tu,
                       TO_NCHAR(u'II.8') AS ma_loai_thong_ke,
                       TO_NCHAR(u'Ph\1ea1m nh\00e2n m\1eafc b\1ec7nh hi\1ec3m ngh\00e8o') AS loai_thong_ke,
                       TO_NCHAR(bh.benh_ten) AS thong_ke_theo,
                       bh.nam, bh.nu, bh.khac, bh.tong_so
                FROM benh_hiem_chi_tiet bh
                WHERE bh.benh_ten IS NOT NULL
                UNION ALL
                SELECT 11999999,
                       TO_NCHAR(u'II.8'),
                       TO_NCHAR(u'Ph\1ea1m nh\00e2n m\1eafc b\1ec7nh hi\1ec3m ngh\00e8o'),
                       TO_NCHAR(u'T\1ed5ng s\1ed1'),
                       SUM(bh.nam), SUM(bh.nu), SUM(bh.khac), SUM(bh.tong_so)
                FROM benh_hiem_chi_tiet bh
                WHERE bh.benh_ten IS NOT NULL),
            phan_loai_latest AS (
                SELECT z.PHAM_NHAN_ID, z.DEN_LOAI_ID
                FROM (SELECT pl.PHAM_NHAN_ID, pl.DEN_LOAI_ID,
                             ROW_NUMBER() OVER (PARTITION BY pl.PHAM_NHAN_ID ORDER BY CAST(pl.NGAY_PHAN_LOAI AS DATE) DESC, pl.ID DESC) AS rn
                      FROM PHAN_LOAIS pl
                      WHERE NVL(pl.IS_DELETED, 0) = 0
                        AND pl.NGAY_PHAN_LOAI IS NOT NULL
                        AND CAST(pl.NGAY_PHAN_LOAI AS DATE) <= v_den_ngay
                        AND pl.PHAM_NHAN_ID IN (SELECT f.ID FROM pham_nhan_filtered f)) z
                WHERE z.rn = 1),
            sec_ii9 AS (
                SELECT 12000000 + ROW_NUMBER() OVER (ORDER BY dplgg.ID) AS sort_thu_tu,
                       TO_NCHAR(u'II.9') AS ma_loai_thong_ke,
                       TO_NCHAR(u'Ph\00e2n t\00edch theo ph\00e2n lo\1ea1i qu\1ea3n ch\1ebf') AS loai_thong_ke,
                       TO_NCHAR(NVL(dplgg.PLGG_TEN, u'Ch\01b0a x\00e1c \0111\1ecbnh')) AS thong_ke_theo,
                       NVL(COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN pnt.ID END), 0) AS nam,
                       NVL(COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN pnt.ID END), 0) AS nu,
                       NVL(COUNT(DISTINCT CASE WHEN LOWER(NVL(dgt.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN pnt.ID END), 0) AS khac,
                       NVL(COUNT(DISTINCT pnt.ID), 0) AS tong_so
                FROM DM_PHAN_LOAI_GIAM_GIUS dplgg
                         LEFT JOIN phan_loai_latest pll ON pll.DEN_LOAI_ID = dplgg.ID
                         LEFT JOIN pham_nhan_filtered pnt ON pnt.ID = pll.PHAM_NHAN_ID
                         LEFT JOIN DM_GIOI_TINHS dgt ON dgt.ID = pnt.LL_DM_GIOI_TINH_ID AND NVL(dgt.IS_DELETED, 0) = 0
                WHERE NVL(dplgg.IS_DELETED, 0) = 0
                GROUP BY dplgg.ID, dplgg.PLGG_TEN
                HAVING NVL(COUNT(DISTINCT pnt.ID), 0) > 0),
            nghien_truoc_trai AS (
                SELECT DISTINCT pnt.ID AS pham_nhan_id, pnt.LL_DM_GIOI_TINH_ID
                FROM pham_nhan_filtered pnt
                         INNER JOIN PN_NGHIEN_MT nmt ON nmt.NMT_PN_LAI_LICH_ID = pnt.ID AND NVL(nmt.IS_DELETED, 0) = 0
                         INNER JOIN DM_MT_TRUONG_HOP_NGHIEN_MA_TUIES thn ON thn.ID = nmt.NMT_TRUONG_HOP_NGHIEN AND NVL(thn.IS_DELETED, 0) = 0
                WHERE TRIM(TO_CHAR(thn.THNMT_MA)) = '11'),
            sec_ii10 AS (
                SELECT 13000001 AS sort_thu_tu, TO_NCHAR(u'II.10') AS ma_loai_thong_ke,
                       TO_NCHAR(u'\0110\1ed1i t\01b0\1ee3ng nghi\1ec7n ma t\00fay tr\01b0\1edbc khi v\00e0o tr\1ea1i') AS loai_thong_ke,
                       TO_NCHAR(u'T\1ed5ng s\1ed1') AS thong_ke_theo,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'nam' THEN n.pham_nhan_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN LOWER(dgt.GT_TEN) = u'n\1eef' THEN n.pham_nhan_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN LOWER(NVL(dgt.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN n.pham_nhan_id END) AS khac,
                       COUNT(DISTINCT n.pham_nhan_id) AS tong_so
                FROM nghien_truoc_trai n
                         LEFT JOIN DM_GIOI_TINHS dgt ON dgt.ID = n.LL_DM_GIOI_TINH_ID AND NVL(dgt.IS_DELETED, 0) = 0),

            /* ===== III. Gi?m án trong k? ===== */
            gth_filtered AS (
                SELECT gth.PHAM_NHAN_ID,
                       TRUNC(gth.NGAY_XET) AS ngay_xet,
                       pll.LL_DM_GIOI_TINH_ID
                FROM GIAM_THOI_HANS gth
                         JOIN PN_LAI_LICHS pll ON pll.ID = gth.PHAM_NHAN_ID AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
                         LEFT JOIN DM_MA_THOI_GIANS dm ON dm.ID = gth.MUC_GIAM_ID AND NVL(dm.IS_DELETED, 0) = 0
                WHERE NVL(gth.IS_DELETED, 0) = 0
                  AND gth.NGAY_XET IS NOT NULL
                  AND gth.MUC_GIAM_ID IS NOT NULL
                  AND NVL(dm.MTG_MA, '000000') <> '000000'
                  AND TRUNC(gth.NGAY_XET) >= v_tu_ngay
                  AND TRUNC(gth.NGAY_XET) < v_den_ngay
                  AND (v_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = v_trai_giam_id)),
            gth_labeled AS (
                SELECT gf.pham_nhan_id, gf.ngay_xet, dgt.GT_TEN
                FROM gth_filtered gf
                         LEFT JOIN DM_GIOI_TINHS dgt ON dgt.ID = gf.LL_DM_GIOI_TINH_ID AND NVL(dgt.IS_DELETED, 0) = 0),
            gth_agg AS (
                SELECT lb.ngay_xet,
                       COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'nam' THEN lb.pham_nhan_id END) AS nam,
                       COUNT(DISTINCT CASE WHEN LOWER(lb.GT_TEN) = u'n\1eef' THEN lb.pham_nhan_id END) AS nu,
                       COUNT(DISTINCT CASE WHEN LOWER(NVL(lb.GT_TEN, u' ')) NOT IN (u'nam', u'n\1eef') THEN lb.pham_nhan_id END) AS khac,
                       COUNT(DISTINCT lb.pham_nhan_id) AS tong_so
                FROM gth_labeled lb
                GROUP BY lb.ngay_xet),
            gth_tong AS (
                SELECT SUM(nam) AS nam, SUM(nu) AS nu, SUM(khac) AS khac, SUM(tong_so) AS tong_so FROM gth_agg),
            sec_iii1 AS (
                SELECT 14000000 + ROW_NUMBER() OVER (ORDER BY a.ngay_xet) AS sort_thu_tu,
                       TO_NCHAR(u'III.1') AS ma_loai_thong_ke,
                       TO_NCHAR(u'Gi\1ea3m \00e1n trong k\1ef3') AS loai_thong_ke,
                       TO_NCHAR(TO_CHAR(a.ngay_xet, 'DD/MM/YYYY')) AS thong_ke_theo,
                       a.nam, a.nu, a.khac, a.tong_so
                FROM gth_agg a
                UNION ALL
                SELECT 14999999, TO_NCHAR(u'III.1'), TO_NCHAR(u'Gi\1ea3m \00e1n trong k\1ef3'), TO_NCHAR(u'C\1ed9ng'),
                       tg.nam, tg.nu, tg.khac, tg.tong_so
                FROM gth_tong tg)

        SELECT z.sort_thu_tu, z.ma_loai_thong_ke, z.loai_thong_ke, z.thong_ke_theo,
               z.nam, z.nu, z.khac, z.tong_so
        FROM (
                 SELECT * FROM sec_i1
                 UNION ALL SELECT * FROM sec_i2
                 UNION ALL SELECT * FROM sec_i3
                 UNION ALL SELECT * FROM sec_ii1
                 UNION ALL SELECT * FROM sec_ii2
                 UNION ALL SELECT * FROM sec_ii3
                 UNION ALL SELECT * FROM sec_ii4
                 UNION ALL SELECT * FROM sec_ii5
                 UNION ALL SELECT * FROM sec_ii6
                 UNION ALL SELECT * FROM sec_ii7
                 UNION ALL SELECT * FROM sec_ii8
                 UNION ALL SELECT * FROM sec_ii9
                 UNION ALL SELECT * FROM sec_ii10
                 UNION ALL SELECT * FROM sec_iii1
             ) z
        ORDER BY z.sort_thu_tu;

    DBMS_SQL.RETURN_RESULT(C1);

END SP_THONG_KE_TONG_HOP_VKS;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_TON_GIAO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_TON_GIAO" (
    p_ma_trai_giam            IN NVARCHAR2 DEFAULT NULL,
    p_so_lieu_tinh_den_ngay   IN DATE      DEFAULT NULL,
    p_den_trai_tu_ngay        IN DATE      DEFAULT NULL,
    p_den_trai_den_ngay       IN DATE      DEFAULT NULL,
    p_ra_trai_tu_ngay         IN DATE      DEFAULT NULL,
    p_ra_trai_den_ngay        IN DATE      DEFAULT NULL,
    p_dac_xa_tu_ngay          IN DATE      DEFAULT NULL,
    p_dac_xa_den_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_tu_ngay         IN DATE      DEFAULT NULL,
    p_giam_an_den_ngay        IN DATE      DEFAULT NULL,
    p_so_tien_an_tu           IN NUMBER    DEFAULT NULL,
    p_so_tien_an_den          IN NUMBER    DEFAULT NULL,
    p_muc_an_tu               IN NUMBER    DEFAULT NULL,
    p_muc_an_den              IN NUMBER    DEFAULT NULL,
    p_tuoi_tu                 IN NUMBER    DEFAULT NULL,
    p_tuoi_den                IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_tu         IN NUMBER    DEFAULT NULL,
    p_tg_chap_hanh_den        IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_tu           IN NUMBER    DEFAULT NULL,
    p_tg_con_lai_den          IN NUMBER    DEFAULT NULL,
    p_gioi_tinh_id            IN NUMBER    DEFAULT NULL,
    p_dan_toc_id              IN NUMBER    DEFAULT NULL,
    p_quoc_tich_id            IN NUMBER    DEFAULT NULL,
    p_nghe_nghiep_id          IN NUMBER    DEFAULT NULL,
    p_hoc_van_id              IN NUMBER    DEFAULT NULL,
    p_ton_giao_id             IN NUMBER    DEFAULT NULL,
    p_toi_danh_ids            IN NVARCHAR2 DEFAULT NULL,
    p_dp_dktt_id              IN NUMBER    DEFAULT NULL,
    p_loai_doi_tuong_id       IN NUMBER    DEFAULT NULL,
    p_ghi_chu_rieng_id        IN NUMBER    DEFAULT NULL,
    p_phan_doi_id             IN NUMBER    DEFAULT NULL,
    p_nuoc_ngoai              IN NUMBER    DEFAULT NULL,
    p_co_benh_tat             IN NUMBER    DEFAULT NULL,
    p_giam_rieng              IN NUMBER    DEFAULT NULL,
    p_dan_toc_thieu_so        IN NUMBER    DEFAULT NULL,
    p_vtn_thoi_diem_pham_toi  IN NUMBER    DEFAULT NULL,
    p_pham_toi_moi            IN NUMBER    DEFAULT NULL,
    p_theo_ton_giao           IN NUMBER    DEFAULT NULL,
    p_vtn_hien_tai            IN NUMBER    DEFAULT NULL,
    p_khong_pham_toi_moi      IN NUMBER    DEFAULT NULL,
    p_co_nghe_nghiep          IN NUMBER    DEFAULT NULL,
    p_chung_than              IN NUMBER    DEFAULT NULL,
    p_da_bi_ky_luat           IN NUMBER    DEFAULT NULL,
    p_co_ghi_chu_dac_biet     IN NUMBER    DEFAULT NULL,
    p_toi_pham_anqg           IN NUMBER    DEFAULT NULL,
    p_da_duoc_khen_thuong     IN NUMBER    DEFAULT NULL,
    p_co_tien_an              IN NUMBER    DEFAULT NULL,
    p_con_theo_me_vao_trai    IN NUMBER    DEFAULT NULL,
    p_hp_bo_sung_la_tien      IN NUMBER    DEFAULT NULL,
    p_co_tien_su              IN NUMBER    DEFAULT NULL,
    p_bat_buoc_chua_benh      IN NUMBER    DEFAULT NULL,
    p_hoan_xong_hpbs_la_tien  IN NUMBER    DEFAULT NULL,
    p_chua_hoan_hpbs_la_tien  IN NUMBER    DEFAULT NULL
)
AS
    C1                SYS_REFCURSOR;
    v_ngay_tinh       DATE := TRUNC(NVL(p_so_lieu_tinh_den_ngay, SYSDATE));
    v_ll_trai_giam_id NUMBER;
BEGIN
    v_ll_trai_giam_id := NULL;
    IF p_ma_trai_giam IS NOT NULL AND TRIM(p_ma_trai_giam) IS NOT NULL THEN
        BEGIN
            SELECT ID INTO v_ll_trai_giam_id
              FROM QLPN.DM_TRAI_GIAMS
             WHERE TG_MA = TRIM(p_ma_trai_giam)
               AND NVL(IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_ll_trai_giam_id := NULL;
        END;
    END IF;

    QLPN.SP_ENSURE_PN_TINH_TRANG_NGAY_CACHE(v_ngay_tinh);

    OPEN C1 FOR
    WITH
    selected_toi_danh_filter AS (
        SELECT TRIM(REGEXP_SUBSTR(
                        REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                        '[^,]+', 1, LEVEL)) AS ma_loc
        FROM DUAL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                                REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', ''),
                                ',') + 1
    ),
    chung_than_ids AS (
        SELECT dmtg.ID
        FROM DM_MA_THOI_GIANS dmtg
        WHERE dmtg.MTG_MA IN ('911000', '912000')
          AND dmtg.IS_DELETED = 0
    ),
    pn_base AS (
        SELECT
            ll.*,
            CASE
                WHEN ll.LL_SO_TIEN_AN IS NULL THEN NULL
                WHEN REGEXP_LIKE(TRIM(ll.LL_SO_TIEN_AN), '^\d+$') THEN TO_NUMBER(TRIM(ll.LL_SO_TIEN_AN))
                ELSE NULL
            END AS SO_TIEN_AN_NUM,
            QLPN.FN_PARSE_LL_NGAY_SINH(ll.LL_NGAY_SINH) AS NGAY_SINH_DATE
        FROM QLPN.PN_LAI_LICH_CHI_TIET_RT ll
        INNER JOIN QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE tt
            ON tt.PN_LAI_LICH_ID = ll.PHAM_NHAN_ID
           AND tt.NGAY_XET = v_ngay_tinh
           AND tt.TTPN_MA IN ('111', '112', '113', '114')
        WHERE
              EXISTS (SELECT 1 FROM PN_LAI_LICHS ll_song WHERE ll_song.ID = ll.PHAM_NHAN_ID AND NVL(ll_song.LL_LA_BAN_DONG_BANG, 0) = 0 AND NVL(ll_song.IS_DELETED, 0) = 0) AND ll.IS_DELETED = 0
          AND NVL(ll.LL_IS_DELETED, 0) = 0
          AND NVL(ll.THA_IS_DELETED, 0) = 0
          AND (v_ll_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = v_ll_trai_giam_id)
    ),
    pham_nhan_filtered AS (
        SELECT
            ll.PHAM_NHAN_ID         AS pham_nhan_id,
            ll.LL_DM_GIOI_TINH_ID,
            ll.LL_DM_HOC_VAN_ID,
            ll.LL_DM_NGHE_NGHIEP_ID,
            ll.LL_SO_TIEN_AN,
            ll.LL_SO_TIEN_SU,
            ll.LL_DM_TON_GIAO_ID,
            ll.THA_THOI_GIAN_DA_CHAP_HANH,
            ll.THA_THOI_GIAN_CON_LAI
        FROM pn_base ll
        LEFT JOIN DM_QUOC_TICHS dqt
            ON dqt.ID = ll.LL_DM_QUOC_TICH_ID
           AND dqt.IS_DELETED = 0
        LEFT JOIN DM_TRAI_GIAMS dtg
            ON dtg.ID = ll.LL_TRAI_GIAM_ID
           AND dtg.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_ma_trai_giam IS NULL OR dtg.TG_MA = p_ma_trai_giam)
          -- NHÓM 1: Kho?ng ngày
          AND (p_den_trai_tu_ngay  IS NULL OR ll.THA_NGAY_DEN_TRAI >= p_den_trai_tu_ngay)
          AND (p_den_trai_den_ngay IS NULL OR ll.THA_NGAY_DEN_TRAI <= p_den_trai_den_ngay)
          AND (p_ra_trai_tu_ngay   IS NULL OR ll.THA_NGAY_HET_HAN  >= p_ra_trai_tu_ngay)
          AND (p_ra_trai_den_ngay  IS NULL OR ll.THA_NGAY_HET_HAN  <= p_ra_trai_den_ngay)
          AND (
              (p_dac_xa_tu_ngay IS NULL AND p_dac_xa_den_ngay IS NULL)
              OR EXISTS (SELECT 1 FROM PN_DAC_XAS dxa
                         WHERE dxa.PNLAI_LICH_ID = ll.PHAM_NHAN_ID AND dxa.IS_DELETED = 0
                           AND (p_dac_xa_tu_ngay  IS NULL OR dxa.DX_NGAY_XET >= p_dac_xa_tu_ngay)
                           AND (p_dac_xa_den_ngay IS NULL OR dxa.DX_NGAY_XET <= p_dac_xa_den_ngay))
          )
          AND (
              (p_giam_an_tu_ngay IS NULL AND p_giam_an_den_ngay IS NULL)
              OR EXISTS (SELECT 1 FROM GIAM_THOI_HANS gaan
                         WHERE gaan.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND gaan.IS_DELETED = 0
                           AND (p_giam_an_tu_ngay  IS NULL OR gaan.NGAY_XET >= p_giam_an_tu_ngay)
                           AND (p_giam_an_den_ngay IS NULL OR gaan.NGAY_XET <= p_giam_an_den_ngay))
          )
          -- NHÓM 2: Kho?ng s?
          AND (p_so_tien_an_tu IS NULL OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM >= p_so_tien_an_tu))
          AND (p_so_tien_an_den IS NULL OR (ll.SO_TIEN_AN_NUM IS NOT NULL AND ll.SO_TIEN_AN_NUM <= p_so_tien_an_den))
          AND (p_muc_an_tu  IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) >= p_muc_an_tu)
          AND (p_muc_an_den IS NULL OR TO_NUMBER(ll.THA_MA_AN_PHAT) <= p_muc_an_den)
          AND (p_tuoi_tu  IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) >= p_tuoi_tu))
          AND (p_tuoi_den IS NULL OR (ll.NGAY_SINH_DATE IS NOT NULL AND FLOOR(MONTHS_BETWEEN(v_ngay_tinh, ll.NGAY_SINH_DATE) / 12) <= p_tuoi_den))
          AND (p_tg_chap_hanh_tu  IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH >= p_tg_chap_hanh_tu)
          AND (p_tg_chap_hanh_den IS NULL OR ll.THA_THOI_GIAN_DA_CHAP_HANH <= p_tg_chap_hanh_den)
          AND (p_tg_con_lai_tu    IS NULL OR ll.THA_THOI_GIAN_CON_LAI       >= p_tg_con_lai_tu)
          AND (p_tg_con_lai_den   IS NULL OR ll.THA_THOI_GIAN_CON_LAI       <= p_tg_con_lai_den)
          -- NHÓM 3: Danh m?c
          AND (p_gioi_tinh_id     IS NULL OR ll.LL_DM_GIOI_TINH_ID         = p_gioi_tinh_id)
          AND (p_dan_toc_id       IS NULL OR ll.LL_DM_DAN_TOC_ID           = p_dan_toc_id)
          AND (p_quoc_tich_id     IS NULL OR ll.LL_DM_QUOC_TICH_ID         = p_quoc_tich_id)
          AND (p_nghe_nghiep_id   IS NULL OR ll.LL_DM_NGHE_NGHIEP_ID       = p_nghe_nghiep_id)
          AND (p_hoc_van_id       IS NULL OR ll.LL_DM_HOC_VAN_ID           = p_hoc_van_id)
          AND (p_ton_giao_id      IS NULL OR ll.LL_DM_TON_GIAO_ID          = p_ton_giao_id)
          AND (
              p_toi_danh_ids IS NULL
              OR LENGTH(REPLACE(REPLACE(REPLACE(p_toi_danh_ids, '[', ''), ']', ''), ' ', '')) = 0
              OR EXISTS (SELECT 1 FROM selected_toi_danh_filter loc
                         WHERE INSTR(
                             ',' || REPLACE(REPLACE(REPLACE(ll.THA_TOI_DANH, '[', ''), ']', ''), ' ', '') || ',',
                             ',' || TRIM(loc.ma_loc) || ','
                         ) > 0)
          )
          AND (p_dp_dktt_id       IS NULL OR ll.LL_DIA_CHI_THUONG_TRU_WARD = p_dp_dktt_id)
          AND (p_loai_doi_tuong_id IS NULL OR ll.THA_DOI_TUONG            = p_loai_doi_tuong_id)
          AND (
              p_ghi_chu_rieng_id IS NULL
              OR INSTR(',' || REGEXP_REPLACE(ll.LL_GHI_CHU_RIENG, '[\[\]\s]', '') || ',',
                       ',' || TO_NCHAR(p_ghi_chu_rieng_id) || ',') > 0
          )
          AND (p_phan_doi_id IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
          -- NHÓM 4: Checkbox
          AND (p_nuoc_ngoai IS NULL OR (
              CASE WHEN dqt.QT_MA <> '250' THEN 1 ELSE 0 END = p_nuoc_ngoai
          ))
          AND (p_co_benh_tat IS NULL OR (
              CASE
                  WHEN ll.LL_BENH_HIEN_TAI_ID IS NULL THEN 1
                  WHEN EXISTS (SELECT 1 FROM DM_BENH_TATS dbt
                               WHERE dbt.ID = ll.LL_BENH_HIEN_TAI_ID
                                 AND dbt.IS_DELETED = 0 AND dbt.BT_MA = '1') THEN 0
                  ELSE 1
              END = p_co_benh_tat
          ))
          AND (p_giam_rieng IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM PN_GIAM_RIENGS gr
                                WHERE gr.GR_PN_LAI_LICH_ID = ll.PHAM_NHAN_ID AND gr.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_giam_rieng
          ))
          AND (
              p_dan_toc_thieu_so IS NULL
              OR (CASE WHEN EXISTS (
                      SELECT 1 FROM DM_DAN_TOCS dt
                      WHERE dt.ID = ll.LL_DM_DAN_TOC_ID AND dt.IS_DELETED = 0
                        AND NVL(dt.DT_MA, 'NULL') NOT IN ('01', '55')
                  ) THEN 1 ELSE 0 END = p_dan_toc_thieu_so)
          )
          AND (p_vtn_thoi_diem_pham_toi IS NULL OR (
              CASE
                  WHEN ll.THA_NGAY_PHAM_TOI IS NULL THEN 0
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(ll.THA_NGAY_PHAM_TOI), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_thoi_diem_pham_toi
          ))
          AND (p_pham_toi_moi IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM PHAM_TOI_MOIS ptm
                                WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_pham_toi_moi
          ))
          AND (p_theo_ton_giao IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM DM_TON_GIAOS tg
                                WHERE tg.ID = ll.LL_DM_TON_GIAO_ID AND tg.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_theo_ton_giao
          ))
          AND (p_vtn_hien_tai IS NULL OR (
              CASE
                  WHEN ll.NGAY_SINH_DATE IS NULL THEN 0
                  WHEN FLOOR(MONTHS_BETWEEN(TRUNC(v_ngay_tinh), ll.NGAY_SINH_DATE) / 12) < 18 THEN 1
                  ELSE 0
              END = p_vtn_hien_tai
          ))
          AND (p_khong_pham_toi_moi IS NULL OR (
              CASE WHEN NOT EXISTS (SELECT 1 FROM PHAM_TOI_MOIS ptm
                                    WHERE ptm.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND ptm.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_khong_pham_toi_moi
          ))
          AND (
              p_co_nghe_nghiep IS NULL
              OR (CASE WHEN ll.LL_DM_NGHE_NGHIEP_ID IS NOT NULL
                            AND EXISTS (SELECT 1 FROM DM_NGHE_NGHIEPS dnn
                                        WHERE dnn.ID = ll.LL_DM_NGHE_NGHIEP_ID AND dnn.IS_DELETED = 0
                                          AND UPPER(dnn.NN_TEN) NOT LIKE UPPER('%Không%'))
                       THEN 1 ELSE 0 END = p_co_nghe_nghiep)
          )
          AND (p_chung_than IS NULL OR (
              CASE WHEN ll.THA_MA_AN_PHAT IN (SELECT ID FROM chung_than_ids)
                   THEN 1 ELSE 0 END = p_chung_than
          ))
          AND (p_da_bi_ky_luat IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM KY_LUATS kl WHERE kl.PHAM_NHAN_ID = ll.PHAM_NHAN_ID)
                   THEN 1 ELSE 0 END = p_da_bi_ky_luat
          ))
          AND (p_co_ghi_chu_dac_biet IS NULL OR (
              CASE WHEN ll.THA_GHI_CHU_DAC_BIET IS NOT NULL
                        AND ll.THA_GHI_CHU_DAC_BIET <> '[]' THEN 1 ELSE 0 END = p_co_ghi_chu_dac_biet
          ))
          AND (p_toi_pham_anqg IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM DM_TOI_DANHS td
                  WHERE td.ID = ll.TOI_DANH_DAU_TIEN
                    AND td.IS_DELETED = 0
                    AND TRIM(TO_CHAR(td.TD_CHUONG)) = '13'
              ) THEN 1 ELSE 0 END = p_toi_pham_anqg
          ))
          AND (p_da_duoc_khen_thuong IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM KHEN_THUONGS kt
                                WHERE kt.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND kt.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_da_duoc_khen_thuong
          ))
          AND (p_co_tien_an IS NULL OR (
              CASE WHEN NVL(ll.LL_SO_TIEN_AN, u'0') <> u'0' THEN 1 ELSE 0 END = p_co_tien_an
          ))
          AND (p_co_tien_su IS NULL OR (
              CASE WHEN NVL(ll.LL_SO_TIEN_SU, u'0') <> u'0' THEN 1 ELSE 0 END = p_co_tien_su
          ))
          AND (p_con_theo_me_vao_trai IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM THAN_NHAN_CON_CAIS tncc
                                WHERE tncc.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND tncc.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_con_theo_me_vao_trai
          ))
          AND (p_hp_bo_sung_la_tien IS NULL OR (
              CASE WHEN EXISTS (
                  SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                  WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                    AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
              ) THEN 1 ELSE 0 END = p_hp_bo_sung_la_tien
          ))
          AND (p_bat_buoc_chua_benh IS NULL OR (
              CASE WHEN EXISTS (SELECT 1 FROM CHUA_BENH_BAT_BUOCS cb
                                WHERE cb.PHAM_NHAN_ID = ll.PHAM_NHAN_ID AND cb.IS_DELETED = 0)
                   THEN 1 ELSE 0 END = p_bat_buoc_chua_benh
          ))
          AND (
              p_hoan_xong_hpbs_la_tien IS NULL OR
              (CASE WHEN EXISTS (
                  SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                  WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                    AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                  GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                  HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) <= 0
              ) THEN 1 ELSE 0 END = p_hoan_xong_hpbs_la_tien)
          )
          AND (
              p_chua_hoan_hpbs_la_tien IS NULL OR
              (CASE WHEN EXISTS (
                  SELECT 1 FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
                  LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dhpbs
                      ON dhpbs.ID = hpbs.HPBS_HINH_PHAT AND dhpbs.IS_DELETED = 0
                  WHERE hpbs.HPBS_MA_PHAM_NHAN = ll.PHAM_NHAN_ID
                    AND hpbs.IS_DELETED = 0 AND dhpbs.HPBS_LOAI_HPBS = 'HPBST'
                  GROUP BY hpbs.HPBS_MA_PHAM_NHAN
                  HAVING SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, 0)) > 0
              ) THEN 1 ELSE 0 END = p_chua_hoan_hpbs_la_tien)
          )
    ),
    chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY
                CASE WHEN dmtg.TG_TEN IS NOT NULL AND LOWER(dmtg.TG_TEN) != u'kh\00f4ng'
                     THEN u'C\00f3 t\00f4n gi\00e1o' ELSE u'Kh\00f4ng c\00f3 t\00f4n gi\00e1o' END
            ) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY
                CASE WHEN dmtg.TG_TEN IS NOT NULL AND LOWER(dmtg.TG_TEN) != u'kh\00f4ng'
                     THEN u'C\00f3 t\00f4n gi\00e1o' ELSE u'Kh\00f4ng c\00f3 t\00f4n gi\00e1o' END
            ))) AS "TT",
            TO_NCHAR(CASE WHEN dmtg.TG_TEN IS NOT NULL AND LOWER(dmtg.TG_TEN) != u'kh\00f4ng'
                          THEN u'C\00f3 t\00f4n gi\00e1o' ELSE u'Kh\00f4ng c\00f3 t\00f4n gi\00e1o' END) AS "TonGiao",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam'  THEN ll.pham_nhan_id END) AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN ll.pham_nhan_id END) AS "Nu",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN IS NULL OR dgt.GT_TEN NOT IN (u'Nam', u'N\1eef')
                                THEN ll.pham_nhan_id END) AS "Khac",
            COUNT(DISTINCT ll.pham_nhan_id) AS "TongSo"
        FROM pham_nhan_filtered ll
        LEFT JOIN DM_GIOI_TINHS dgt ON dgt.ID = ll.LL_DM_GIOI_TINH_ID AND dgt.IS_DELETED = 0
        LEFT JOIN DM_TON_GIAOS dmtg ON dmtg.ID = ll.LL_DM_TON_GIAO_ID AND dmtg.IS_DELETED = 0
        GROUP BY
            CASE WHEN dmtg.TG_TEN IS NOT NULL AND LOWER(dmtg.TG_TEN) != u'kh\00f4ng'
                 THEN u'C\00f3 t\00f4n gi\00e1o' ELSE u'Kh\00f4ng c\00f3 t\00f4n gi\00e1o' END
    )
    SELECT "TT", "TonGiao", "Nam", "Nu", "Khac", "TongSo"
    FROM (
        SELECT SORT_ORDER, "TT", "TonGiao", "Nam", "Nu", "Khac", "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT 999,
               TO_NCHAR(''),
               TO_NCHAR(u'T\1ed5ng s\1ed1'),
               SUM("Nam"), SUM("Nu"), SUM("Khac"), SUM("TongSo")
        FROM chi_tiet
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_THONG_KE_TON_GIAO;


/
--------------------------------------------------------
--  DDL for Procedure SP_THONG_KE_TRUONG_HOP_MIEN_HINH_PHAT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_THONG_KE_TRUONG_HOP_MIEN_HINH_PHAT" (
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay     IN DATE   DEFAULT NULL,
    p_den_ngay    IN DATE   DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR

    WITH chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY dthmhp.ID)                    AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY dthmhp.ID))) AS "TT",
            NVL(dthmhp.MHP_TEN, TO_NCHAR('Ch?a xác ??nh'))           AS "TruongHopMien",

            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam'
                THEN ll.ID END)                                        AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'
                THEN ll.ID END)                                        AS "Nu",
            COUNT(DISTINCT CASE
                WHEN NVL(dgt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef')
                THEN ll.ID END)                                        AS "Khac",
            COUNT(DISTINCT ll.ID)                                      AS "TongSo"

        FROM MIEN_HINH_PHATS mhp
        LEFT JOIN PN_LAI_LICHS ll
            ON mhp.PN_LAI_LICH_ID = ll.ID
            AND ll.IS_DELETED = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
        LEFT JOIN DM_GIOI_TINHS dgt
            ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
            AND dgt.IS_DELETED = 0
        LEFT JOIN DM_TRUONG_HOP_MIEN_HINH_PHATS dthmhp
            ON mhp.MHP_TRUONG_HOP_MIEN = dthmhp.ID
            AND dthmhp.IS_DELETED = 0
        LEFT JOIN PN_THI_HANH_AN ptha
            ON ll.ID = ptha.THA_PNLAI_LICH_ID
            AND ptha.IS_DELETED = 0

        WHERE mhp.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay      IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay     IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        GROUP BY dthmhp.ID, dthmhp.MHP_TEN
    )

    SELECT "TT", "TruongHopMien", "Nam", "Nu", "Khac", "TongSo"
    FROM (

        SELECT SORT_ORDER, "TT", "TruongHopMien", "Nam", "Nu", "Khac", "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(NULL),  
            TO_NCHAR('T?ng s?'), 
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet

    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);

END SP_THONG_KE_TRUONG_HOP_MIEN_HINH_PHAT;


/
--------------------------------------------------------
--  DDL for Procedure SP_TINH_DA_VA_CON
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_TINH_DA_VA_CON" (
    p_PHAM_NHAN_ID IN NUMBER,
    p_AN_PHAT      IN NVARCHAR2, -- ví d?: N'10 n?m 8 tháng 30 ngày'
    p_NGAY_XET     IN DATE,      -- m?c xét duy?t
    p_THA_NGAY_BAT IN DATE,      -- ngày b?t ??u tính án
    p_DA_CHAP_HANH OUT NVARCHAR2,
    p_CON_LAI      OUT NVARCHAR2
) IS
    -- Án (n?m, tháng, ngày)
    v_an_n NUMBER := 0;
    v_an_t NUMBER := 0;
    v_an_g NUMBER := 0;

    v_ngay_xet   DATE := NVL(p_NGAY_XET, SYSDATE);
    v_end        DATE;  -- ngày h?t án (b?t + án)
    v_served_end DATE;  -- m?c k?t thúc ph?n ?ã ch?p hành (<= v_end)

    -- K?t qu? ?ã ch?p hành
    v_da_n NUMBER := 0;
    v_da_t NUMBER := 0;
    v_da_g NUMBER := 0;

    -- K?t qu? còn l?i
    v_con_n NUMBER := 0;
    v_con_t NUMBER := 0;
    v_con_g NUMBER := 0;

    -- ??nh d?ng "x n?m y tháng z ngày"
    FUNCTION format_ymd(n IN NUMBER, t IN NUMBER, g IN NUMBER) RETURN NVARCHAR2 IS
    BEGIN
        RETURN TO_NCHAR(NVL(n, 0)) || u' n\0103m '
             || TO_NCHAR(NVL(t, 0)) || u' th\00e1ng '
             || TO_NCHAR(NVL(g, 0)) || u' ng\00e0y';
    END;

    -- Tính chênh l?ch (n?m, tháng, ngày) theo l?ch chu?n gi?a d1 -> d2 (d2 >= d1)
    PROCEDURE diff_ymd(d1 IN DATE, d2 IN DATE,
                       y OUT NUMBER, m OUT NUMBER, d OUT NUMBER) IS
        v_months NUMBER;
        v_tmp    DATE;
    BEGIN
        IF d2 <= d1 THEN
            y := 0; m := 0; d := 0;
            RETURN;
        END IF;

        -- T?ng tháng chênh l?ch (làm tròn xu?ng)
        v_months := TRUNC(MONTHS_BETWEEN(d2, d1));

        -- Tách n?m / tháng
        y := TRUNC(v_months / 12);
        m := MOD(v_months, 12);

        -- Ngày còn l?i sau khi tr? s? n?m + tháng
        v_tmp := ADD_MONTHS(d1, y * 12 + m);

        -- N?u do ngày trong tháng khác nhau gây v??t, lùi l?i 1 tháng
        IF v_tmp > d2 THEN
            v_months := v_months - 1;
            y := TRUNC(v_months / 12);
            m := MOD(v_months, 12);
            v_tmp := ADD_MONTHS(d1, y * 12 + m);
        END IF;

        d := TRUNC(d2 - v_tmp);
        IF d < 0 THEN
            -- Tr??ng h?p hi?m, m??n 1 tháng r?i tính l?i ngày
            m := m - 1;
            IF m < 0 THEN
                y := y - 1;
                m := m + 12;
            END IF;
            v_tmp := ADD_MONTHS(d1, y * 12 + m);
            d := TRUNC(d2 - v_tmp);
            IF d < 0 THEN
                d := 0;
            END IF;
        END IF;
    END;
BEGIN
    -- Validate
    IF p_THA_NGAY_BAT IS NULL THEN
        p_DA_CHAP_HANH := NULL;
        p_CON_LAI      := NULL;
        RETURN;
    END IF;

    -- Parse án ph?t: d?a vào hàm parse c?a b?n
    v_an_n := NVL(FN_PARSE_THOI_GIAN_TEXT(p_AN_PHAT, 'NAM'),   0);
    v_an_t := NVL(FN_PARSE_THOI_GIAN_TEXT(p_AN_PHAT, 'THANG'), 0);
    v_an_g := NVL(FN_PARSE_THOI_GIAN_TEXT(p_AN_PHAT, 'NGAY'),  0);

    -- Tính ngày h?t án: c?ng s? tháng + s? ngày
    v_end := ADD_MONTHS(p_THA_NGAY_BAT, v_an_n * 12 + v_an_t) + v_an_g;

    -- M?c ?ã ch?p hành
    IF v_ngay_xet <= p_THA_NGAY_BAT THEN
        v_served_end := p_THA_NGAY_BAT;        -- ch?a ch?p hành
    ELSIF v_ngay_xet >= v_end THEN
        v_served_end := v_end;                 -- ?ã h?t án
    ELSE
        v_served_end := v_ngay_xet;            -- ?ang ch?p hành
    END IF;

    -- ?ã ch?p hành
    diff_ymd(p_THA_NGAY_BAT, v_served_end, v_da_n, v_da_t, v_da_g);

    -- Còn l?i
    IF v_ngay_xet >= v_end THEN
        v_con_n := 0; v_con_t := 0; v_con_g := 0;
    ELSE
        diff_ymd(v_ngay_xet, v_end, v_con_n, v_con_t, v_con_g);
    END IF;

    p_DA_CHAP_HANH := format_ymd(v_da_n, v_da_t, v_da_g);
    p_CON_LAI      := format_ymd(v_con_n, v_con_t, v_con_g);

EXCEPTION
    WHEN OTHERS THEN
        -- An toàn: tr? NULL ?? caller t? x? lý
        p_DA_CHAP_HANH := NULL;
        p_CON_LAI      := NULL;
END;







/
--------------------------------------------------------
--  DDL for Procedure SP_TINH_NGAY_HET_AN_DEMO_FINAL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_TINH_NGAY_HET_AN_DEMO_FINAL" (
    p_PN_ID              IN NUMBER   DEFAULT NULL,
    p_NGAY_BAT           IN DATE     DEFAULT NULL,
    p_NGAY_YC_TINH       IN NUMBER   DEFAULT NULL,
    p_THA_AN_PHAT_TEXT   IN NVARCHAR2 DEFAULT NULL,
    p_THA_TAM_GIAM_TEXT  IN NVARCHAR2 DEFAULT NULL,
    p_THA_TAM_GIU_TEXT   IN NVARCHAR2 DEFAULT NULL,
    p_THA_O_TRUOC_TEXT   IN NVARCHAR2 DEFAULT NULL,  
    p_DUNG_PARAM         IN NUMBER   DEFAULT NULL,
    p_NGAY_HET_HAN       OUT DATE,
        p_THONG_BAO          OUT NVARCHAR2
)
IS
    v_NGAY_BAT     NUMBER;
    v_NGAY_YC_TINH NUMBER;

    v_AN_PHAT_GOC_NAM   NUMBER := 0;
    v_AN_PHAT_GOC_THANG NUMBER := 0;
    v_AN_PHAT_GOC_NGAY  NUMBER := 0;

    -- >>> "Án th?c" gi? CH? còn: án ph?t g?c - t?m giam - t?m gi? - ? tr??c
    v_AN_THUC_TONG_NAM   NUMBER := 0;
    v_AN_THUC_TONG_THANG NUMBER := 0;
    v_AN_THUC_TONG_NGAY  NUMBER := 0;

    -- >>> TÁCH RIÊNG: bó "?i?u ch?nh" = mi?n + t?ng/gi?m hình ph?t + gi?m án (gi?m th?i h?n)
    v_DIEU_CHINH_TONG_NAM   NUMBER := 0;
    v_DIEU_CHINH_TONG_THANG NUMBER := 0;
    v_DIEU_CHINH_TONG_NGAY  NUMBER := 0;

    v_TONG_QUY_DOI_NGAY NUMBER := 0;

    v_NAM_TAM_GIAM   NUMBER := 0; v_THANG_TAM_GIAM NUMBER := 0; v_NGAY_TAM_GIAM NUMBER := 0;
    v_NAM_TAM_GIU    NUMBER := 0; v_THANG_TAM_GIU  NUMBER := 0; v_NGAY_TAM_GIU  NUMBER := 0;
    v_NAM_O_TRUOC    NUMBER := 0; v_THANG_O_TRUOC  NUMBER := 0; v_NGAY_O_TRUOC  NUMBER := 0;

    v_TONG_GIAM_NAM   NUMBER := 0; v_TONG_GIAM_THANG NUMBER := 0; v_TONG_GIAM_NGAY NUMBER := 0;

    v_TONG_NGAY_TRON NUMBER := 0;
    v_TONG_NGAY_TDC  NUMBER := 0;
    v_TONG_NGAY_HOAN NUMBER := 0;
    v_TONG_NGAY_THA_CO_DK NUMBER := 0;   -- >>> RULE 7: s? ngày "tha có ?i?u ki?n" ?ã quay l?i

    -- >>> Tr?n tr?i tính theo cách c?a tr?i (m?c 7): có b?n ghi tr?n ?ã b?t l?i thì tính án còn
    --     l?i tu?n t? t?ng l?n tr?n r?i neo vào ngày b?t l?i c?a l?n cu?i.
    v_CO_TRON      BOOLEAN := FALSE;
    v_MOC_BAT      DATE;
    v_CL_NAM       NUMBER := 0; v_CL_THANG NUMBER := 0; v_CL_NGAY NUMBER := 0;   -- án còn l?i
    v_DA_NAM       NUMBER := 0; v_DA_THANG NUMBER := 0; v_DA_NGAY NUMBER := 0;   -- ?ã ch?p hành tr??c khi tr?n

    v_MIEN_NAM   NUMBER := 0; v_MIEN_THANG NUMBER := 0; v_MIEN_NGAY NUMBER := 0;
    v_TANG_NAM   NUMBER := 0; v_TANG_THANG NUMBER := 0; v_TANG_NGAY NUMBER := 0;
    v_GIAM_NAM   NUMBER := 0; v_GIAM_THANG NUMBER := 0; v_GIAM_NGAY NUMBER := 0;

    v_AN_PHAT_TEXT            NVARCHAR2(500);
    v_THOI_GIAN_TAM_GIAM_TEXT NVARCHAR2(500);
    v_THOI_GIAN_TAM_GIU_TEXT  NVARCHAR2(500);
    v_THOI_GIAN_O_TRUOC_TEXT  NVARCHAR2(500);

    v_CHUNG_THAN         BOOLEAN := FALSE;
    v_TU_HINH            BOOLEAN := FALSE;
    v_DATA_FOUND         BOOLEAN := FALSE;
    v_IS_CHUNG_THAN_GIAM BOOLEAN := FALSE;
    v_CT_GIAM_MA         NVARCHAR2(20);   -- >>> 921000 (chung thân gi?m xu?ng 30 n?m) / 922000 (xu?ng 20 n?m)

    v_NGAY_THA     DATE;
    v_NGAY_THA_112 NUMBER;

    v_NGAY_BAT_YEAR  NUMBER; v_NGAY_BAT_MONTH  NUMBER; v_NGAY_BAT_DAY  NUMBER;
    v_NGAY_YC_YEAR       NUMBER; v_NGAY_YC_MONTH NUMBER; v_NGAY_YC_DAY NUMBER;

    -- >>> Các bi?n DATE dùng cho quy trình c?ng d?n 3 b??c ? m?c 7
    v_NGAY_BAT_DATE         DATE;
    v_NGAY_TRUNG_GIAN       DATE;  -- sau khi c?ng "án th?c"
    v_NGAY_SAU_DIEU_CHINH   DATE;  -- sau khi c?ng ti?p ph?n "?i?u ch?nh"

    -- >>> RULE 1-6: bi?n cho các tr?ng thái ??c bi?t (return s?m)
    v_NGAY_THA_GIAM_HET_AN   DATE;   -- rule 1
    v_DX_NGAY_THA            DATE;   -- rule 2
    v_TCDK_NGAY_THA          DATE;   -- rule 3 (ch?a quay l?i)
    v_HUY_NGAY_TRA_TU_DO     DATE;   -- rule 4
    v_MIEN_HET_AN_NGAY_TU_DO DATE;   -- rule 5
    v_MIEN_HET_AN_FLAG       BOOLEAN := FALSE;
    v_CNT_TRON_MO  NUMBER := 0;      -- rule 6
    v_CNT_TDC_MO   NUMBER := 0;
    v_CNT_HOAN_MO  NUMBER := 0;

    -- ==========================================
    PROCEDURE NORMALIZE_YMD(
        p_nam   IN OUT NUMBER,
        p_thang IN OUT NUMBER,
        p_ngay  IN OUT NUMBER
    ) IS
    BEGIN
        WHILE p_ngay < 0 LOOP
            p_ngay  := p_ngay + 30;
            p_thang := p_thang - 1;
        END LOOP;
        WHILE p_thang < 0 LOOP
            p_thang := p_thang + 12;
            p_nam   := p_nam - 1;
        END LOOP;
        p_thang := p_thang + TRUNC(p_ngay  / 30);
        p_ngay  := MOD(p_ngay, 30);
        p_nam   := p_nam + TRUNC(p_thang / 12);
        p_thang := MOD(p_thang, 12);
    END;

    PROCEDURE NORMALIZE_YM(
        p_nam   IN OUT NUMBER,
        p_thang IN OUT NUMBER,
        p_ngay  IN OUT NUMBER
    ) IS
    BEGIN
        WHILE p_thang < 0 LOOP
            p_thang := p_thang + 12;
            p_nam   := p_nam - 1;
        END LOOP;
        p_nam   := p_nam + TRUNC(p_thang / 12);
        p_thang := MOD(p_thang, 12);
    END;
    
    PROCEDURE PARSE_AN_PHAT(p_text IN NVARCHAR2) IS
    BEGIN
        IF p_text IS NULL THEN RETURN; END IF;

        -- >>> Ch? nh?n "30 n?m" / "20 n?m", không nh?n "30"/"20" n?m trong s? quy?t ??nh (vd 230/Q?)
        IF INSTR(UPPER(p_text), 'CHUNG') > 0 AND REGEXP_LIKE(p_text, '(^|[^0-9])30[[:space:]]*n', 'i') THEN
            v_AN_PHAT_GOC_NAM    := 30;
            v_IS_CHUNG_THAN_GIAM := TRUE;
        ELSIF INSTR(UPPER(p_text), 'CHUNG') > 0 AND REGEXP_LIKE(p_text, '(^|[^0-9])20[[:space:]]*n', 'i') THEN
            v_AN_PHAT_GOC_NAM    := 20;
            v_IS_CHUNG_THAN_GIAM := TRUE;
        ELSIF INSTR(UPPER(p_text), 'CHUNG') > 0 THEN
            v_CHUNG_THAN := TRUE;
            RETURN;
        ELSIF REGEXP_LIKE(UPPER(p_text), 'T.{1,3}H.NH') THEN
            v_TU_HINH := TRUE;
            RETURN;
        END IF;

        IF NOT v_IS_CHUNG_THAN_GIAM THEN
            v_AN_PHAT_GOC_NAM   := NVL(FN_PARSE_THOI_GIAN_TEXT(p_text, 'NAM'),   0);
            v_AN_PHAT_GOC_THANG := NVL(FN_PARSE_THOI_GIAN_TEXT(p_text, 'THANG'), 0);
            v_AN_PHAT_GOC_NGAY  := NVL(FN_PARSE_THOI_GIAN_TEXT(p_text, 'NGAY'),  0);
        END IF;
    END;

    -- ==========================================
    -- >>> HÀM M?I 1: Tr? v? s? ngày TH?C c?a 1 tháng/n?m c? th? (l?ch d??ng, có xét
    --     n?m nhu?n). KHÔNG tra DIM_DATETIME: các c?t DATE c?a b?ng này l?ch 100/200
    --     n?m t? n?m 2046 tr? ?i (vd YEAR_ID 2046 nh?ng DATETIME = 1946).
    -- ==========================================
    FUNCTION FN_SO_NGAY_TRONG_THANG(p_nam IN NUMBER, p_thang IN NUMBER) RETURN NUMBER IS
    BEGIN
        RETURN EXTRACT(DAY FROM LAST_DAY(
            TO_DATE(LPAD(TO_CHAR(p_nam), 4, '0') || LPAD(TO_CHAR(p_thang), 2, '0') || '01', 'YYYYMMDD')));
    END;

    -- ==========================================
    -- >>> Quy ??i 30 ngày = 1 tháng, GI? D?U, KHÔNG m??n tháng ?? bù ngày âm.
    --     Vd: 45 ngày -> 1 tháng 15 ngày; -45 ngày -> -1 tháng -15 ngày; -9 ngày gi? nguyên -9.
    --     (Khác NORMALIZE_YMD: không ??i ngày âm thành "tháng - 1 + 30 ngày".)
    -- ==========================================
    PROCEDURE QUY_DOI_30_NGAY(
        p_thang IN OUT NUMBER,
        p_ngay  IN OUT NUMBER
    ) IS
        v_q NUMBER := TRUNC(p_ngay / 30);
    BEGIN
        p_thang := p_thang + v_q;
        p_ngay  := p_ngay  - v_q * 30;
    END;

    --====================================================================================
    -- HÀM: FN_CONG_YMD_VAO_NGAY — c?ng (n?m, tháng, ngày) vào 1 ngày m?c (DATE).
    --
    --     QUY T?C: 1 tháng = 30 ngày (không theo ?? dài th?c 28/29/31 c?a tháng).
    --       B??c 1: c?ng N?M + THÁNG vào ngày m?c, gi? nguyên S? NGÀY c?a m?c.
    --       B??c 2: n?u có ph?n NGÀY: s? ngày ?o = s? ngày c?a m?c + p_ngay;
    --               > 30 thì tr? 30 và sang tháng sau, < 1 thì c?ng 30 và lùi tháng tr??c.
    --               Vd: ngày ?o 45 tháng 1  -> 15/02 (l?ch th?c s? ra 14/02 — sai quy t?c).
    --                   31/01 + 14 ngày      -> 45/01 -> 15/02.
    --                   01/04 - 1 ngày       -> 0/04  -> 30/03.
    --       B??c 3: n?u ngày không t?n t?i trong tháng ?ích (31/4, 29-30/2 ...) thì CH?T v?
    --               ngày cu?i tháng — cùng quy t?c v?i c?ng tháng thu?n (31/1 + 1 tháng = 28/2).
    --
    --     Tính ch?t: k?t qu? KHÔNG ph? thu?c vi?c có "m??n 30 ngày" hay không
    --       ("1 n?m - 9 ngày" và "11 tháng 21 ngày" ra cùng ngày), kh?p cách c?ng tay
    --       "ngày v?i ngày, tháng v?i tháng, n?m v?i n?m; ngày > 30 thì tr? 30, c?ng 1 tháng".
    --     D?ng ngày tr?c ti?p t? (n?m, tháng, ngày), KHÔNG tra DIM_DATETIME (c?t DATE c?a
    --     b?ng này l?ch 100/200 n?m t? n?m 2046 tr? ?i), KHÔNG c?ng DATE + N.
    --====================================================================================
    FUNCTION FN_CONG_YMD_VAO_NGAY(
        p_ngay_bat IN DATE,
        p_nam      IN NUMBER,
        p_thang    IN NUMBER,
        p_ngay     IN NUMBER
    ) RETURN DATE IS
        v_dich_nam   NUMBER := EXTRACT(YEAR  FROM p_ngay_bat) + NVL(p_nam,0);
        v_dich_thang NUMBER := EXTRACT(MONTH FROM p_ngay_bat) + NVL(p_thang,0);
        v_ngay_ao    NUMBER := EXTRACT(DAY   FROM p_ngay_bat);   -- s? ngày "?o" trong tháng ?ích
        v_q          NUMBER;
    BEGIN
        -- B??c 2: c?ng/tr? ph?n NGÀY theo h? 30 ngày/tháng
        IF NVL(p_ngay,0) <> 0 THEN
            v_ngay_ao    := v_ngay_ao + p_ngay;
            v_q          := FLOOR((v_ngay_ao - 1) / 30);   -- s? tháng tràn (âm n?u h?t)
            v_dich_thang := v_dich_thang + v_q;
            v_ngay_ao    := v_ngay_ao - 30 * v_q;           -- luôn trong 1..30
        END IF;

        WHILE v_dich_thang > 12 LOOP v_dich_thang := v_dich_thang - 12; v_dich_nam := v_dich_nam + 1; END LOOP;
        WHILE v_dich_thang < 1  LOOP v_dich_thang := v_dich_thang + 12; v_dich_nam := v_dich_nam - 1; END LOOP;

        -- B??c 3: ch?t v? ngày cu?i tháng n?u ngày không t?n t?i (không tràn sang tháng sau)
        v_ngay_ao := LEAST(v_ngay_ao, FN_SO_NGAY_TRONG_THANG(v_dich_nam, v_dich_thang));

        RETURN TO_DATE(LPAD(TO_CHAR(v_dich_nam), 4, '0')
                    || LPAD(TO_CHAR(v_dich_thang), 2, '0')
                    || LPAD(TO_CHAR(v_ngay_ao), 2, '0'), 'YYYYMMDD');
    END FN_CONG_YMD_VAO_NGAY;
BEGIN
    p_NGAY_HET_HAN := NULL;
    p_THONG_BAO    := '';

    BEGIN
        -- ==========================================
        -- 0. KI?M TRA NGÀY THA (?ã ra tr?i)
        -- ==========================================
        IF p_PN_ID IS NOT NULL THEN
            BEGIN
                SELECT KTRT_NGAY_THA INTO v_NGAY_THA
                  FROM PN_KET_THUC_RA_TRAIS
                 WHERE KTRT_PN_LAI_LICH_ID = p_PN_ID
                   AND IS_DELETED = 0
                   AND KTRT_NGAY_THA IS NOT NULL
                 ORDER BY CREATION_TIME DESC
                 FETCH FIRST 1 ROW ONLY;

                IF v_NGAY_THA IS NOT NULL THEN
                    v_NGAY_THA_112 := TO_NUMBER(TO_CHAR(v_NGAY_THA, 'YYYYMMDD'));
                    BEGIN
                        SELECT TO_NUMBER(TO_CHAR(THA_NGAY_BAT, 'YYYYMMDD'))
                          INTO v_NGAY_BAT
                          FROM PN_THI_HANH_AN
                         WHERE THA_PNLAI_LICH_ID = p_PN_ID AND ROWNUM = 1;
                    EXCEPTION WHEN NO_DATA_FOUND THEN v_NGAY_BAT := NULL;
                    END;

                    p_NGAY_HET_HAN := v_NGAY_THA;

                    IF v_NGAY_BAT IS NOT NULL THEN
                        SELECT YEAR_ID, MONTH_ID, EXTRACT(DAY FROM DATETIME)
                          INTO v_NGAY_BAT_YEAR, v_NGAY_BAT_MONTH, v_NGAY_BAT_DAY
                          FROM DIM_DATETIME WHERE DATE_112 = v_NGAY_BAT AND ROWNUM = 1;

                        SELECT YEAR_ID, MONTH_ID, EXTRACT(DAY FROM DATETIME)
                          INTO v_NGAY_YC_YEAR, v_NGAY_YC_MONTH, v_NGAY_YC_DAY
                          FROM DIM_DATETIME WHERE DATE_112 = v_NGAY_THA_112 AND ROWNUM = 1;
                        END IF;
                    p_THONG_BAO :=
                        u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c tha v\00e0o ng\00e0y '
                        || TO_CHAR(v_NGAY_THA, 'DD/MM/YYYY') || u'. ';
                    RETURN;
                END IF;
            EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
            END;
        END IF;

        -- ==========================================
        -- >>> RULE 1-6: CÁC TR?NG THÁI ??C BI?T (ch? khi có p_PN_ID)
        --     Th? t? ?u tiên: gi?m h?t án ? ??c xá ? tha có ?K (ch?a quay l?i)
        --                     ? h?y án ? mi?n h?t án 92300 ? ch?n n?u còn b?n ghi m?
        -- ==========================================
        IF p_PN_ID IS NOT NULL THEN

            -- RULE 1: Gi?m h?t án (có ngày c? th? t? GIAM_THOI_HANS)
            BEGIN
                SELECT NGAY_THA_GIAM_HET_AN
                  INTO v_NGAY_THA_GIAM_HET_AN
                  FROM GIAM_THOI_HANS gth
                  JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
                 WHERE gth.PHAM_NHAN_ID = p_PN_ID
                   AND NVL(gth.IS_DELETED, 0) = 0
                   AND gth.NGAY_THA_GIAM_HET_AN IS NOT NULL
                   AND dmtg.MTG_MA NOT IN ('921000', '922000')
                   AND ROWNUM = 1
                 ORDER BY NGAY_XET;
            EXCEPTION WHEN NO_DATA_FOUND THEN v_NGAY_THA_GIAM_HET_AN := NULL;
            END;

            IF v_NGAY_THA_GIAM_HET_AN IS NULL THEN
                BEGIN
                    SELECT gth.NGAY_QUYET_DINH
                      INTO v_NGAY_THA_GIAM_HET_AN
                      FROM GIAM_THOI_HANS gth
                      JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
                     WHERE gth.PHAM_NHAN_ID = p_PN_ID
                       AND NVL(gth.IS_DELETED, 0) = 0
                       AND dmtg.MTG_MA = '923000'
                       AND gth.NGAY_QUYET_DINH IS NOT NULL
                       AND ROWNUM = 1;
                EXCEPTION WHEN NO_DATA_FOUND THEN v_NGAY_THA_GIAM_HET_AN := NULL;
                END;
            END IF;

            IF v_NGAY_THA_GIAM_HET_AN IS NOT NULL THEN
                p_NGAY_HET_HAN := v_NGAY_THA_GIAM_HET_AN;
                p_THONG_BAO := u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c gi\1ea3m h\1ebft \00e1n v\00e0o ng\00e0y '
                    || TO_CHAR(v_NGAY_THA_GIAM_HET_AN, 'DD/MM/YYYY') || u'.';
                RETURN;
            END IF;

            -- RULE 2: ??c xá
            BEGIN
                SELECT DX_NGAY_THA INTO v_DX_NGAY_THA
                  FROM PN_DAC_XAS
                 WHERE PNLAI_LICH_ID = p_PN_ID
                   AND NVL(IS_DELETED, 0) = 0
                   AND DX_NGAY_THA IS NOT NULL
                 ORDER BY CREATION_TIME DESC
                 FETCH FIRST 1 ROW ONLY;
            EXCEPTION WHEN NO_DATA_FOUND THEN v_DX_NGAY_THA := NULL;
            END;

            IF v_DX_NGAY_THA IS NOT NULL THEN
                p_NGAY_HET_HAN := v_DX_NGAY_THA;
                p_THONG_BAO := u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c tha v\00e0o ng\00e0y '
                    || TO_CHAR(v_DX_NGAY_THA, 'DD/MM/YYYY') || u'. \0110\01b0\1ee3c \0111\1eb7c x\00e1.';
                RETURN;
            END IF;

            -- RULE 3: Tha có ?i?u ki?n (ch?a quay l?i)
            BEGIN
                SELECT NGAY_THA INTO v_TCDK_NGAY_THA
                  FROM THA_CO_DIEU_KIENS
                 WHERE PHAM_NHAN_ID = p_PN_ID
                   AND NVL(IS_DELETED, 0) = 0
                   AND NGAY_THA IS NOT NULL
                   AND NGAY_BAT_LAI IS NULL
                 ORDER BY CREATION_TIME DESC
                 FETCH FIRST 1 ROW ONLY;
            EXCEPTION WHEN NO_DATA_FOUND THEN v_TCDK_NGAY_THA := NULL;
            END;

            IF v_TCDK_NGAY_THA IS NOT NULL THEN
                p_NGAY_HET_HAN := v_TCDK_NGAY_THA;
                p_THONG_BAO := u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c tha v\00e0o ng\00e0y '
                    || TO_CHAR(v_TCDK_NGAY_THA, 'DD/MM/YYYY') || u'. \0110\01b0\1ee3c tha c\00f3 \0111i\1ec1u ki\1ec7n.';
                RETURN;
            END IF;

            -- RULE 4: H?y án
            BEGIN
                SELECT NGAY_TRA_TU_DO INTO v_HUY_NGAY_TRA_TU_DO
                  FROM HUY_ANS
                 WHERE PHAM_NHAN_ID = p_PN_ID
                   AND NVL(IS_DELETED, 0) = 0
                   AND NGAY_TRA_TU_DO IS NOT NULL
                   AND NGAY_TRO_LAI IS NULL
                 ORDER BY CREATION_TIME DESC
                 FETCH FIRST 1 ROW ONLY;
            EXCEPTION WHEN NO_DATA_FOUND THEN v_HUY_NGAY_TRA_TU_DO := NULL;
            END;

            IF v_HUY_NGAY_TRA_TU_DO IS NOT NULL THEN
                p_NGAY_HET_HAN := v_HUY_NGAY_TRA_TU_DO;
                p_THONG_BAO := u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c tha v\00e0o ng\00e0y '
                    || TO_CHAR(v_HUY_NGAY_TRA_TU_DO, 'DD/MM/YYYY') || u'. \0110\01b0\1ee3c h\1ee7y \00e1n.';
                RETURN;
            END IF;

            -- RULE 5: Mi?n h?t án (c? ??c bi?t 92300)
            BEGIN
                SELECT MHP_NGAY_TU_DO INTO v_MIEN_HET_AN_NGAY_TU_DO
                  FROM MIEN_HINH_PHATS
                 WHERE PN_LAI_LICH_ID = p_PN_ID
                   AND IS_DELETED = 0
                   AND NVL(MHP_THM_YEAR, 0) = 9
                   AND NVL(MHP_THM_MONTH, 0) = 23
                   AND NVL(MHP_THM_DAY, 0) = 0
                 ORDER BY CREATION_TIME DESC
                 FETCH FIRST 1 ROW ONLY;
                v_MIEN_HET_AN_FLAG := TRUE;
            EXCEPTION WHEN NO_DATA_FOUND THEN
                v_MIEN_HET_AN_FLAG := FALSE;
                v_MIEN_HET_AN_NGAY_TU_DO := NULL;
            END;

            IF v_MIEN_HET_AN_FLAG AND v_MIEN_HET_AN_NGAY_TU_DO IS NOT NULL THEN
                p_NGAY_HET_HAN := v_MIEN_HET_AN_NGAY_TU_DO;
                p_THONG_BAO := u'Ph\1ea1m nh\00e2n \0111\01b0\1ee3c mi\1ec5n h\1ebft \00e1n (92300). Ng\00e0y t\1ef1 do: '
                    || TO_CHAR(v_MIEN_HET_AN_NGAY_TU_DO, 'DD/MM/YYYY');
                RETURN;
            END IF;

            -- RULE 6: Ch?n n?u còn b?n ghi tr?n/T?C/hoãn CH?A k?t thúc
            SELECT COUNT(*) INTO v_CNT_TRON_MO
              FROM TRON_TRAIS
             WHERE PHAM_NHAN_ID = p_PN_ID
               AND NVL(IS_DELETED, 0) = 0
               AND NGAY_TRON IS NOT NULL
               AND NGAY_BAT_LAI IS NULL;

            SELECT COUNT(*) INTO v_CNT_TDC_MO
              FROM TAM_DINH_CHIS
             WHERE PHAM_NHAN_ID = p_PN_ID
               AND NVL(IS_DELETED, 0) = 0
               AND TU_NGAY IS NOT NULL
               AND NGAY_LAI IS NULL;

            SELECT COUNT(*) INTO v_CNT_HOAN_MO
              FROM HOAN_THI_HANH_ANS
             WHERE PHAM_NHAN_ID = p_PN_ID
               AND NVL(IS_DELETED, 0) = 0
               AND NGAY_HOAN IS NOT NULL
               AND NGAY_THI_HANH_AN IS NULL;

            IF v_CNT_TRON_MO > 0 OR v_CNT_TDC_MO > 0 OR v_CNT_HOAN_MO > 0 THEN
                p_NGAY_HET_HAN := NULL;
                p_THONG_BAO :=
                    CASE WHEN v_CNT_TRON_MO > 0
                         THEN u'Ch\01b0a x\00e1c \0111\1ecbnh: c\00f2n ' || v_CNT_TRON_MO || u' l\1ea7n tr\1ed1n ch\01b0a b\1eaft l\1ea1i. ' ELSE '' END ||
                    CASE WHEN v_CNT_TDC_MO > 0
                         THEN u'Ch\01b0a x\00e1c \0111\1ecbnh: c\00f2n ' || v_CNT_TDC_MO || u' l\1ea7n T\0110C ch\01b0a quay l\1ea1i. ' ELSE '' END ||
                    CASE WHEN v_CNT_HOAN_MO > 0
                         THEN u'Ch\01b0a x\00e1c \0111\1ecbnh: c\00f2n ' || v_CNT_HOAN_MO || u' l\1ea7n ho\00e3n ch\01b0a thi h\00e0nh. ' ELSE '' END;
                RETURN;
            END IF;
        END IF;

        -- ==========================================
        -- 1. L?Y D? LI?U
        -- ==========================================
        IF p_PN_ID IS NOT NULL AND NVL(p_DUNG_PARAM, 0) <> 1 THEN
            BEGIN
                SELECT
                    TO_NUMBER(TO_CHAR(THA_NGAY_BAT, 'YYYYMMDD')),
                    THA_AN_PHAT_GOC,
                    THA_THOI_GIAN_TAM_GIAM,
                    THA_THOI_GIAN_TAM_GIU,
                    THA_THOI_GIAN_O_TRUOC
                INTO
                    v_NGAY_BAT, v_AN_PHAT_TEXT,
                    v_THOI_GIAN_TAM_GIAM_TEXT, v_THOI_GIAN_TAM_GIU_TEXT, v_THOI_GIAN_O_TRUOC_TEXT
                  FROM PN_THI_HANH_AN
                 WHERE THA_PNLAI_LICH_ID = p_PN_ID AND ROWNUM = 1;

                v_DATA_FOUND := TRUE;
            EXCEPTION WHEN NO_DATA_FOUND THEN v_DATA_FOUND := FALSE;
            END;
        END IF;

        IF NVL(p_DUNG_PARAM, 0) = 1 OR NOT v_DATA_FOUND THEN
            IF p_NGAY_BAT IS NULL AND v_NGAY_BAT IS NULL THEN
                p_THONG_BAO := CASE WHEN p_PN_ID IS NOT NULL
                    THEN u'L\1ed7i: Ch\01b0a c\00f3 d\1eef li\1ec7u trong b\1ea3ng PN_THI_HANH_AN cho PN_ID: ' || p_PN_ID
                    ELSE u'L\1ed7i: p_NGAY_BAT l\00e0 b\1eaft bu\1ed9c khi kh\00f4ng truy\1ec1n PN_ID'
                END;
                RETURN;
            END IF;

            IF p_NGAY_BAT IS NOT NULL THEN
                v_NGAY_BAT := TO_NUMBER(TO_CHAR(p_NGAY_BAT, 'YYYYMMDD'));
            END IF;

            v_AN_PHAT_TEXT            := p_THA_AN_PHAT_TEXT;
            v_THOI_GIAN_TAM_GIAM_TEXT := p_THA_TAM_GIAM_TEXT;
            v_THOI_GIAN_TAM_GIU_TEXT  := p_THA_TAM_GIU_TEXT;
            v_THOI_GIAN_O_TRUOC_TEXT  := p_THA_O_TRUOC_TEXT;

            v_DATA_FOUND := TRUE;
        END IF;

        -- ==========================================
        -- 2. PARSE ÁN PH?T
        -- ==========================================
        PARSE_AN_PHAT(v_AN_PHAT_TEXT);

        IF v_THOI_GIAN_TAM_GIAM_TEXT IS NOT NULL THEN
            v_NAM_TAM_GIAM   := NVL(FN_PARSE_THOI_GIAN_TEXT(v_THOI_GIAN_TAM_GIAM_TEXT, 'NAM'),   0);
            v_THANG_TAM_GIAM := NVL(FN_PARSE_THOI_GIAN_TEXT(v_THOI_GIAN_TAM_GIAM_TEXT, 'THANG'), 0);
            v_NGAY_TAM_GIAM  := NVL(FN_PARSE_THOI_GIAN_TEXT(v_THOI_GIAN_TAM_GIAM_TEXT, 'NGAY'),  0);
        END IF;
        IF v_THOI_GIAN_TAM_GIU_TEXT IS NOT NULL THEN
            v_NAM_TAM_GIU   := NVL(FN_PARSE_THOI_GIAN_TEXT(v_THOI_GIAN_TAM_GIU_TEXT, 'NAM'),   0);
            v_THANG_TAM_GIU := NVL(FN_PARSE_THOI_GIAN_TEXT(v_THOI_GIAN_TAM_GIU_TEXT, 'THANG'), 0);
            v_NGAY_TAM_GIU  := NVL(FN_PARSE_THOI_GIAN_TEXT(v_THOI_GIAN_TAM_GIU_TEXT, 'NGAY'),  0);
        END IF;
        IF v_THOI_GIAN_O_TRUOC_TEXT IS NOT NULL THEN
            v_NAM_O_TRUOC   := NVL(FN_PARSE_THOI_GIAN_TEXT(v_THOI_GIAN_O_TRUOC_TEXT, 'NAM'),   0);
            v_THANG_O_TRUOC := NVL(FN_PARSE_THOI_GIAN_TEXT(v_THOI_GIAN_O_TRUOC_TEXT, 'THANG'), 0);
            v_NGAY_O_TRUOC  := NVL(FN_PARSE_THOI_GIAN_TEXT(v_THOI_GIAN_O_TRUOC_TEXT, 'NGAY'),  0);
        END IF;

        -- ==========================================
        -- 3. L?Y CÁC D? LI?U T? DB (tr?n/T?C/hoãn/gi?m TH/mi?n/t?ng gi?m/tha có ?K)
        -- ==========================================
        IF p_PN_ID IS NOT NULL THEN
            -- >>> Quy?t ??nh gi?m chung thân xu?ng 30 n?m (921000) / 20 n?m (922000), l?y b?n ghi m?i nh?t
            BEGIN
                SELECT dmtg.MTG_MA INTO v_CT_GIAM_MA
                  FROM GIAM_THOI_HANS gth
                  JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID AND NVL(dmtg.IS_DELETED,0) = 0
                 WHERE gth.PHAM_NHAN_ID = p_PN_ID AND gth.IS_DELETED = 0
                   AND dmtg.MTG_MA IN ('921000', '922000')
                 ORDER BY gth.NGAY_QUYET_DINH DESC NULLS LAST, gth.ID DESC
                 FETCH FIRST 1 ROW ONLY;
            EXCEPTION WHEN NO_DATA_FOUND THEN v_CT_GIAM_MA := NULL;
            END;

            FOR rec IN (
                SELECT dmtg.MTG_TITLE
                  FROM GIAM_THOI_HANS gth
                  JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID AND NVL(dmtg.IS_DELETED,0) = 0
                 WHERE gth.PHAM_NHAN_ID = p_PN_ID AND gth.IS_DELETED = 0 AND gth.MUC_GIAM_ID IS NOT NULL
                   -- >>> 921000/922000 là m?c án m?i (m?c 4), không ph?i m?c gi?m
                   AND dmtg.MTG_MA NOT IN ('921000', '922000')
            ) LOOP
                v_TONG_GIAM_NAM   := v_TONG_GIAM_NAM   + NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE,'NAM'),  0);
                v_TONG_GIAM_THANG := v_TONG_GIAM_THANG + NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE,'THANG'),0);
                v_TONG_GIAM_NGAY  := v_TONG_GIAM_NGAY  + NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE,'NGAY'), 0);
            END LOOP;
            NORMALIZE_YM(v_TONG_GIAM_NAM, v_TONG_GIAM_THANG, v_TONG_GIAM_NGAY);

            FOR rec IN (
                SELECT CAST(tt.NGAY_TRON AS DATE) AS NGAY_TRON, CAST(tt.NGAY_BAT_LAI AS DATE) AS NGAY_BAT_LAI
                  FROM TRON_TRAIS tt
                 WHERE tt.PHAM_NHAN_ID = p_PN_ID AND NVL(tt.IS_DELETED,0) = 0
                   AND tt.NGAY_TRON IS NOT NULL AND tt.NGAY_BAT_LAI IS NOT NULL
            ) LOOP
                -- >>> Tr?n tr?i KHÔNG còn c?ng bù s? ngày vào cu?i: m?c 7 tính án còn l?i tu?n t?
                --     theo cách c?a tr?i. v_TONG_NGAY_TRON ch? còn dùng ?? hi?n th? thông báo.
                v_CO_TRON := TRUE;
                DECLARE v_d NUMBER := FLOOR(rec.NGAY_BAT_LAI - rec.NGAY_TRON) + 1;
                BEGIN IF v_d > 0 THEN v_TONG_NGAY_TRON := v_TONG_NGAY_TRON + v_d; END IF; END;
            END LOOP;

            FOR rec IN (
                SELECT TRUNC(tdc.TU_NGAY) AS TU_NGAY, TRUNC(tdc.NGAY_LAI) AS NGAY_LAI
                  FROM TAM_DINH_CHIS tdc
                 WHERE tdc.PHAM_NHAN_ID = p_PN_ID AND NVL(tdc.IS_DELETED,0) = 0
                   AND tdc.TU_NGAY IS NOT NULL AND tdc.NGAY_LAI IS NOT NULL
            ) LOOP
                DECLARE v_d NUMBER := rec.NGAY_LAI - rec.TU_NGAY + 1;
                BEGIN IF v_d > 0 THEN v_TONG_NGAY_TDC := v_TONG_NGAY_TDC + v_d; END IF; END;
            END LOOP;

            FOR rec IN (
                SELECT CAST(htha.NGAY_HOAN AS DATE) AS NGAY_HOAN, CAST(htha.NGAY_THI_HANH_AN AS DATE) AS NGAY_THA
                  FROM HOAN_THI_HANH_ANS htha
                 WHERE htha.PHAM_NHAN_ID = p_PN_ID AND NVL(htha.IS_DELETED,0) = 0
                   AND htha.NGAY_HOAN IS NOT NULL AND htha.NGAY_THI_HANH_AN IS NOT NULL
            ) LOOP
                DECLARE v_d NUMBER := FLOOR(rec.NGAY_THA - rec.NGAY_HOAN) + 1;
                BEGIN IF v_d > 0 THEN v_TONG_NGAY_HOAN := v_TONG_NGAY_HOAN + v_d; END IF; END;
            END LOOP;

            -- >>> RULE 7: Tha có ?i?u ki?n ?Ã quay l?i ? c?ng s? ngày t? do vào th?i gian h?t án
            FOR rec IN (
                SELECT CAST(tcdk.NGAY_THA AS DATE) AS NGAY_THA, CAST(tcdk.NGAY_BAT_LAI AS DATE) AS NGAY_BAT_LAI
                  FROM THA_CO_DIEU_KIENS tcdk
                 WHERE tcdk.PHAM_NHAN_ID = p_PN_ID AND NVL(tcdk.IS_DELETED,0) = 0
                   AND tcdk.NGAY_THA IS NOT NULL AND tcdk.NGAY_BAT_LAI IS NOT NULL
            ) LOOP
                DECLARE v_d NUMBER := FLOOR(rec.NGAY_BAT_LAI - rec.NGAY_THA);  -- không +1, theo ?úng DEMO_FINAL2
                BEGIN IF v_d > 0 THEN v_TONG_NGAY_THA_CO_DK := v_TONG_NGAY_THA_CO_DK + v_d; END IF; END;
            END LOOP;

            SELECT NVL(SUM(NVL(MHP_THM_YEAR,0)),0),
                   NVL(SUM(NVL(MHP_THM_MONTH,0)),0),
                   NVL(SUM(NVL(MHP_THM_DAY,0)),0)
              INTO v_MIEN_NAM, v_MIEN_THANG, v_MIEN_NGAY
              FROM MIEN_HINH_PHATS
             WHERE PN_LAI_LICH_ID = p_PN_ID AND IS_DELETED = 0
               -- >>> RULE 5: lo?i b? b?n ghi c? "mi?n h?t án 92300" kh?i t?ng Y/M/D thông th??ng
               AND NOT (NVL(MHP_THM_YEAR,0) = 9 AND NVL(MHP_THM_MONTH,0) = 23 AND NVL(MHP_THM_DAY,0) = 0);
            NORMALIZE_YM(v_MIEN_NAM, v_MIEN_THANG, v_MIEN_NGAY);

            FOR rec IN (
                SELECT dmtg.MTG_TITLE, ltg.LTGHP_MA
                  FROM TANG_GIAM_HINH_PHATS tghp
                  JOIN DM_LOAI_TANG_GIAM_HINH_PHATS ltg ON tghp.LOAI_TANG_GIAM_ID = ltg.ID AND NVL(ltg.IS_DELETED,0) = 0
                  JOIN DM_MA_THOI_GIANS dmtg ON tghp.THOI_HAN_ID = dmtg.ID AND NVL(dmtg.IS_DELETED,0) = 0
                 WHERE tghp.PHAM_NHAN_ID = p_PN_ID AND tghp.IS_DELETED = 0 AND tghp.THOI_HAN_ID IS NOT NULL
            ) LOOP
                DECLARE
                    v_t_nam   NUMBER := NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE,'NAM'),  0);
                    v_t_thang NUMBER := NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE,'THANG'),0);
                    v_t_ngay  NUMBER := NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE,'NGAY'), 0);
                BEGIN
                    IF rec.LTGHP_MA = '10' THEN
                        v_TANG_NAM := v_TANG_NAM + v_t_nam; v_TANG_THANG := v_TANG_THANG + v_t_thang; v_TANG_NGAY := v_TANG_NGAY + v_t_ngay;
                    ELSIF rec.LTGHP_MA = '20' THEN
                        v_GIAM_NAM := v_GIAM_NAM + v_t_nam; v_GIAM_THANG := v_GIAM_THANG + v_t_thang; v_GIAM_NGAY := v_GIAM_NGAY + v_t_ngay;
                    END IF;
                END;
            END LOOP;
            NORMALIZE_YM(v_TANG_NAM, v_TANG_THANG, v_TANG_NGAY);
            NORMALIZE_YM(v_GIAM_NAM, v_GIAM_THANG, v_GIAM_NGAY);
        END IF;

        IF v_NGAY_BAT IS NULL THEN
            p_THONG_BAO := u'L\1ed7i: Ng\00e0y b\1eaft l\00e0 b\1eaft bu\1ed9c';
            RETURN;
        END IF;

        -- ==========================================
        -- 4. CHUNG THÂN ?Ã GI?M XU?NG 30/20 N?M (921000 / 922000)
        --    Án ph?t g?c gi? nguyên "chung thân" (ngày h?t h?n = NULL) cho t?i khi
        --    có quy?t ??nh gi?m th?i h?n mã 921000/922000; khi ?ó tính nh? án
        --    30/20 n?m k? t? ngày b?t, nh? án có th?i h?n: v?n tr? t?m giam / t?m gi? /
        --    ? tr??c (t?ng th?i gian ?ã ch?p hành tr??c ngày b?t), và các kho?n khác
        --    (gi?m th?i h?n các l?n sau, t?ng/gi?m HP, mi?n, tr?n/T?C/hoãn/tha có ?K)
        --    c?ng/tr? nh? bình th??ng — kh?p PKG_TINH_AN / SP_TINH_NGAY_HET_AN_GENERAL.
        -- ==========================================
        IF v_CT_GIAM_MA IS NOT NULL AND (v_CHUNG_THAN OR v_IS_CHUNG_THAN_GIAM) THEN
            v_CHUNG_THAN         := FALSE;
            v_IS_CHUNG_THAN_GIAM := TRUE;
            v_AN_PHAT_GOC_NAM    := CASE v_CT_GIAM_MA WHEN '921000' THEN 30 ELSE 20 END;
            v_AN_PHAT_GOC_THANG  := 0;
            v_AN_PHAT_GOC_NGAY   := 0;
        END IF;

        -- ==========================================
        -- 5. T? HÌNH / CHUNG THÂN
        -- ==========================================
        IF v_TU_HINH THEN
            p_NGAY_HET_HAN := NULL;
            p_THONG_BAO    := u'B\1ea3n \00e1n: T\1eed h\00ecnh (v\00f4 th\1eddi h\1ea1n)';
            RETURN;
        END IF;
        IF v_CHUNG_THAN THEN
            p_NGAY_HET_HAN := NULL;
            p_THONG_BAO    := u'B\1ea3n \00e1n: Chung th\00e2n (v\00f4 th\1eddi h\1ea1n)';
            RETURN;
        END IF;

        -- ==========================================
        -- 6. TÍNH ÁN TH?C (ch? án ph?t g?c - t?m giam - t?m gi? - ? tr??c)
        --    >>> TÁCH RIÊNG: mi?n + t?ng/gi?m hình ph?t + gi?m án (gi?m th?i h?n)
        --        ???c c?ng d?n thành 1 bó riêng, KHÔNG g?p chung vào án th?c n?a.
        --        Bó này s? ???c c?ng vào ngày h?t h?n ? b??c sau (m?c 7, b??c 2).
        -- ==========================================
        v_AN_THUC_TONG_NAM   := v_AN_PHAT_GOC_NAM   - v_NAM_TAM_GIAM   - v_NAM_TAM_GIU   - v_NAM_O_TRUOC;
        v_AN_THUC_TONG_THANG := v_AN_PHAT_GOC_THANG - v_THANG_TAM_GIAM - v_THANG_TAM_GIU - v_THANG_O_TRUOC;
        v_AN_THUC_TONG_NGAY  := v_AN_PHAT_GOC_NGAY  - v_NGAY_TAM_GIAM  - v_NGAY_TAM_GIU  - v_NGAY_O_TRUOC;
        -- >>> KHÔNG g?i NORMALIZE_YMD ? ?ây (không m??n tháng ?? bù ngày âm): vd 1 n?m - 9 ngày
        --     gi? (1, 0, -9), ?? FN_CONG_YMD_VAO_NGAY c?ng N?M/THÁNG tr??c r?i m?i tr? NGÀY.
        --     (T? b?n s?a 04/11/2026, FN dùng 1 tháng = 30 ngày nên m??n hay không m??n
        --     ??u ra cùng k?t qu?; gi? nguyên ?? không ??i lu?ng.)
        --     Ch? quy ??i m?i 30 ngày = 1 tháng (gi? d?u): án 45 ngày -> 1 tháng 15 ngày,
        --     80 ngày -> 2 tháng 20 ngày. Phép so sánh "?ã h?t án" bên d??i là tuy?n tính
        --     (n?m*360 + tháng*30 + ngày) nên không b? ?nh h??ng.
        QUY_DOI_30_NGAY(v_AN_THUC_TONG_THANG, v_AN_THUC_TONG_NGAY);

        v_DIEU_CHINH_TONG_NAM   := v_TANG_NAM   - v_GIAM_NAM   - v_MIEN_NAM   - v_TONG_GIAM_NAM;
        v_DIEU_CHINH_TONG_THANG := v_TANG_THANG - v_GIAM_THANG - v_MIEN_THANG - v_TONG_GIAM_THANG;
        v_DIEU_CHINH_TONG_NGAY  := v_TANG_NGAY  - v_GIAM_NGAY  - v_MIEN_NGAY  - v_TONG_GIAM_NGAY;
        -- >>> Gói ?i?u ch?nh c?ng quy ??i 30 ngày = 1 tháng (gi? d?u, không m??n) nh? án th?c,
        --     ?? hai b??c nh?t quán: gi?m 45 ngày = -1 tháng -15 ngày.
        QUY_DOI_30_NGAY(v_DIEU_CHINH_TONG_THANG, v_DIEU_CHINH_TONG_NGAY);
        NORMALIZE_YM(v_DIEU_CHINH_TONG_NAM, v_DIEU_CHINH_TONG_THANG, v_DIEU_CHINH_TONG_NGAY);

        -- Ki?m tra ?ã ch?p hành h?t án ch?a: quy ??i c? 2 bó ra t?ng s? ngày (30 ngày/tháng,
        -- 12 tháng/n?m) r?i c?ng l?i ?? so sánh — tránh bug c? (ch? ?úng khi NAM<=0 VÀ
        -- THANG<=0 VÀ NGAY<=0 t?ng ph?n m?t, s? b? sót tr??ng h?p NAM âm nh?ng THANG/NGAY d??ng).
        v_TONG_QUY_DOI_NGAY :=
              (v_AN_THUC_TONG_NAM   + v_DIEU_CHINH_TONG_NAM)   * 360
            + (v_AN_THUC_TONG_THANG + v_DIEU_CHINH_TONG_THANG) * 30
            + (v_AN_THUC_TONG_NGAY  + v_DIEU_CHINH_TONG_NGAY);

        IF v_TONG_QUY_DOI_NGAY <= 0 THEN
            p_NGAY_HET_HAN := TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');
            p_THONG_BAO := u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c gi\1ea3m h\1ebft \00e1n';
            RETURN;
        END IF;

        -- ==========================================
        -- 7. TÍNH NGÀY H?T H?N — th?c hi?n theo 3 b??c. M?i b??c quy ??i 30 ngày = 1 tháng
        --    (gi? d?u, không m??n tháng bù ngày âm), c?ng N?M/THÁNG tr??c r?i m?i c?ng NGÀY
        --    theo h? 30 ngày/tháng (FN_CONG_YMD_VAO_NGAY); ch? dùng s? ngày TH?C c?a tháng
        --    ?? ch?t cu?i tháng khi ngày không t?n t?i (31/4, 29-30/2).
        --
        --    B??c 1: Ngày b?t + "án th?c" (án ph?t - t?m giam - t?m gi? - ? tr??c)
        --             => ngày trung gian.
        --             N?u có TR?N TR?I: tính theo cách c?a tr?i (án còn l?i tu?n t? t?ng l?n
        --             tr?n, neo vào ngày b?t l?i l?n cu?i) thay cho "ngày b?t + án th?c".
        --    B??c 2: Ngày trung gian + "?i?u ch?nh" (mi?n + t?ng/gi?m HP + gi?m án)
        --             => ngày sau ?i?u ch?nh.
        --    B??c 3: C?ng s? ngày thô (T?C + hoãn + tha có ?K ?ã quay l?i), quy ??i
        --             30 ngày = 1 tháng nh? hai b??c trên.
        -- ==========================================
        v_NGAY_BAT_DATE := TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');

        IF NOT v_CO_TRON THEN
            v_NGAY_TRUNG_GIAN := FN_CONG_YMD_VAO_NGAY(
                v_NGAY_BAT_DATE, v_AN_THUC_TONG_NAM, v_AN_THUC_TONG_THANG, v_AN_THUC_TONG_NGAY
            );
        ELSE
            -- >>> CÁCH C?A TR?I khi có tr?n tr?i: duy?t t?ng l?n tr?n theo th? t? th?i gian.
            --     M?i l?n: (1) th?i gian ?ã ch?p hành = t? m?c hi?n t?i ??n ngày tr?n (n?m/tháng/ngày,
            --     m??n 30 ngày), tr? vào án còn l?i; (2) m?c m?i = ngày b?t l?i. Cu?i cùng ngày h?t án
            --     = ngày b?t l?i c?a l?n cu?i + án còn l?i.
            --     Vd b?t 11/08/1990, án 9 n?m, t?m giam 3 tháng 2 ngày, tr?n 11/10/1992 - 25/07/2024:
            --       ?ã ch?p hành 2 n?m 2 tháng; còn l?i 9n - (2n2t + 3t2ng) = 6 n?m 6 tháng 28 ngày;
            --       25/07/2024 + 6 n?m 6 tháng 28 ngày = 23/02/2031.
            --     Tr?n b?t ??u tr??c/?úng m?c hi?n t?i (tr?n g?i nhau, tr?n tr??c ngày b?t) thì
            --     th?i gian ?ã ch?p hành = 0 và m?c không lùi.
            v_MOC_BAT := v_NGAY_BAT_DATE;
            v_CL_NAM   := v_AN_THUC_TONG_NAM;
            v_CL_THANG := v_AN_THUC_TONG_THANG;
            v_CL_NGAY  := v_AN_THUC_TONG_NGAY;

            FOR rec IN (
                SELECT TRUNC(CAST(tt.NGAY_TRON AS DATE)) AS NGAY_TRON, TRUNC(CAST(tt.NGAY_BAT_LAI AS DATE)) AS NGAY_BAT_LAI
                  FROM TRON_TRAIS tt
                 WHERE tt.PHAM_NHAN_ID = p_PN_ID AND NVL(tt.IS_DELETED,0) = 0
                   AND tt.NGAY_TRON IS NOT NULL AND tt.NGAY_BAT_LAI IS NOT NULL
                 ORDER BY tt.NGAY_TRON, tt.NGAY_BAT_LAI
            ) LOOP
                IF rec.NGAY_TRON > v_MOC_BAT THEN
                    v_DA_NAM   := EXTRACT(YEAR  FROM rec.NGAY_TRON) - EXTRACT(YEAR  FROM v_MOC_BAT);
                    v_DA_THANG := EXTRACT(MONTH FROM rec.NGAY_TRON) - EXTRACT(MONTH FROM v_MOC_BAT);
                    v_DA_NGAY  := EXTRACT(DAY   FROM rec.NGAY_TRON) - EXTRACT(DAY   FROM v_MOC_BAT);
                    NORMALIZE_YMD(v_DA_NAM, v_DA_THANG, v_DA_NGAY);

                    v_CL_NAM   := v_CL_NAM   - v_DA_NAM;
                    v_CL_THANG := v_CL_THANG - v_DA_THANG;
                    v_CL_NGAY  := v_CL_NGAY  - v_DA_NGAY;
                    NORMALIZE_YMD(v_CL_NAM, v_CL_THANG, v_CL_NGAY);
                END IF;

                IF rec.NGAY_BAT_LAI > v_MOC_BAT THEN
                    v_MOC_BAT := rec.NGAY_BAT_LAI;
                END IF;
            END LOOP;

            v_NGAY_TRUNG_GIAN := FN_CONG_YMD_VAO_NGAY(v_MOC_BAT, v_CL_NAM, v_CL_THANG, v_CL_NGAY);
        END IF;

        -- >>> ?Ã B? nhánh ch?n "tháng/ngày trái d?u" (c?: ngày b?t + N ngày theo l?ch th?c).
        --     V?i quy t?c 30 ngày/tháng trong FN_CONG_YMD_VAO_NGAY, tr??ng h?p ?ó t? ?úng:
        --     b?t 31/1, án 1 tháng - t?m giam 29 ngày -> ngày ?o 31 - 29 = 2 tháng 2 -> 02/02
        --     (b?ng cách tính tay: 1 tháng - 29 ngày = 1 ngày; 31 + 1 = 32 -> 02/02).
        --     Án còn d??ng thì k?t qu? luôn sau ngày b?t, không c?n nhánh c?ng DATE + N n?a.

        v_NGAY_SAU_DIEU_CHINH := FN_CONG_YMD_VAO_NGAY(
            v_NGAY_TRUNG_GIAN, v_DIEU_CHINH_TONG_NAM, v_DIEU_CHINH_TONG_THANG, v_DIEU_CHINH_TONG_NGAY
        );

        -- >>> B??c 3: T?C + hoãn + tha có ?K quy ??i 30 ngày = 1 tháng (40 ngày = 1 tháng 10 ngày,
        --     c?ng tháng tr??c, ngày sau). TR?N TR?I không n?m ? ?ây: ?ã x? lý theo cách c?a tr?i
        --     ? b??c 1 (tính án còn l?i tu?n t? r?i neo vào ngày b?t l?i).
        DECLARE
            v_ct_thang NUMBER := 0;
            v_ct_ngay  NUMBER := v_TONG_NGAY_TDC + v_TONG_NGAY_HOAN + v_TONG_NGAY_THA_CO_DK;
        BEGIN
            QUY_DOI_30_NGAY(v_ct_thang, v_ct_ngay);
            p_NGAY_HET_HAN := FN_CONG_YMD_VAO_NGAY(v_NGAY_SAU_DIEU_CHINH, 0, v_ct_thang, v_ct_ngay);
        END;

        -- ==========================================
        -- 8. NGÀY YÊU C?U TÍNH (?ã b?, không còn OUT param t??ng ?ng)
        -- ==========================================
        v_NGAY_YC_TINH := NVL(p_NGAY_YC_TINH, TO_NUMBER(TO_CHAR(SYSDATE,'YYYYMMDD')));

        -- ==========================================
        -- 9. OUTPUT
        -- ==========================================
        p_THONG_BAO :=
            u'Ng\00e0y h\1ebft h\1ea1n: '  || TO_CHAR(p_NGAY_HET_HAN,'DD/MM/YYYY')
            || CASE WHEN v_TONG_GIAM_NAM+v_TONG_GIAM_THANG+v_TONG_GIAM_NGAY > 0
                    THEN u'. (Gi\1ea3m TH: '||v_TONG_GIAM_NAM||u'n '||v_TONG_GIAM_THANG||u't '||v_TONG_GIAM_NGAY||u'ng)' ELSE '' END
            || CASE WHEN v_TONG_NGAY_TRON > 0
                    THEN u'. (Tr\1ed1n: +'||v_TONG_NGAY_TRON||u' ng\00e0y)' ELSE '' END
            || CASE WHEN v_TONG_NGAY_TDC  > 0
                    THEN u'. (T\0110C: +'||v_TONG_NGAY_TDC||u' ng\00e0y)' ELSE '' END
            || CASE WHEN v_TONG_NGAY_HOAN > 0
                    THEN u'. (Ho\00e3n: +'||v_TONG_NGAY_HOAN||u' ng\00e0y)' ELSE '' END
            -- >>> RULE 7
            || CASE WHEN v_TONG_NGAY_THA_CO_DK > 0
                    THEN u'. (Tha c\00f3 \0111i\1ec1u ki\1ec7n \0111\00e3 quay l\1ea1i: +'||v_TONG_NGAY_THA_CO_DK||u' ng\00e0y)' ELSE '' END
            || CASE WHEN v_MIEN_NAM+v_MIEN_THANG+v_MIEN_NGAY > 0
                    THEN u'. (Mi\1ec5n: -'||v_MIEN_NAM||u'n '||v_MIEN_THANG||u't '||v_MIEN_NGAY||u'ng)' ELSE '' END
            || CASE WHEN v_TANG_NAM+v_TANG_THANG+v_TANG_NGAY > 0
                    THEN u'. (T\0103ng HP: +'||v_TANG_NAM||u'n '||v_TANG_THANG||u't '||v_TANG_NGAY||u'ng)' ELSE '' END
            || CASE WHEN v_GIAM_NAM+v_GIAM_THANG+v_GIAM_NGAY > 0
                    THEN u'. (Gi\1ea3m HP: -'||v_GIAM_NAM||u'n '||v_GIAM_THANG||u't '||v_GIAM_NGAY||u'ng)' ELSE '' END
            || u'.';

    EXCEPTION
        WHEN OTHERS THEN
            p_THONG_BAO          := u'L\1ed7i: ' || SQLERRM;
            p_NGAY_HET_HAN := NULL;
    END;
END SP_TINH_NGAY_HET_AN_DEMO_FINAL;

/
--------------------------------------------------------
--  DDL for Procedure SP_TINH_NGAY_HET_AN_DEMO_FINAL2
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_TINH_NGAY_HET_AN_DEMO_FINAL2" (
    p_PN_ID             IN NUMBER    DEFAULT NULL,
    p_NGAY_BAT          IN DATE      DEFAULT NULL,
    p_NGAY_YC_TINH      IN NUMBER    DEFAULT NULL,
    p_THA_AN_PHAT_TEXT  IN NVARCHAR2 DEFAULT NULL,
    p_THA_TAM_GIAM_TEXT IN NVARCHAR2 DEFAULT NULL,
    p_THA_TAM_GIU_TEXT  IN NVARCHAR2 DEFAULT NULL,
    p_THA_O_TRUOC_TEXT  IN NVARCHAR2 DEFAULT NULL,
--    p_MIEN_HP_TEXT      IN NVARCHAR2 DEFAULT NULL,
    p_DUNG_PARAM        IN NUMBER    DEFAULT NULL,
    p_NGAY_HET_HAN      OUT DATE,
    p_THONG_BAO         OUT NVARCHAR2
)
IS
    -- Bi?n l?u params t? DB (PN_THI_HANH_AN)
    v_THA_NGAY_BAT           DATE;
    v_THA_AN_PHAT_GOC       NVARCHAR2(500);
    v_THA_TAM_GIAM_DB       NVARCHAR2(500);
    v_THA_TAM_GIU_DB        NVARCHAR2(500);
    v_THA_O_TRUOC_DB        NVARCHAR2(500);

    -- Params ?ã xác ??nh (t? param truy?n vào ho?c query t? DB)
    v_NGAY_BAT              DATE;
    v_AN_PHAT_TEXT          NVARCHAR2(500);
    v_TAM_GIAM_TEXT         NVARCHAR2(500);
    v_TAM_GIU_TEXT          NVARCHAR2(500);
    v_O_TRUOC_TEXT          NVARCHAR2(500);

    -- 4 text params t?ng h?p t? 4 b?ng (GIAM, TRON, TDC, HOAN)
    v_GIAM_AN_TEXT          NVARCHAR2(4000);
    v_TRON_TEXT             NVARCHAR2(4000);
    v_TDC_TEXT              NVARCHAR2(4000);
    v_HOAN_TEXT             NVARCHAR2(4000);

    -- 3 text params HP (t? MIEN_HINH_PHATS, TANG_GIAM_HINH_PHATS)
    v_GIAM_HP_TEXT          NVARCHAR2(500);
    v_MIEN_HP_TEXT          NVARCHAR2(500);
    v_TANG_HP_TEXT          NVARCHAR2(500);

    v_MUC_GIAM_DACBIET_MA NVARCHAR2(50);
    -- Bi?n t?m cho output t? SP g?c
    v_nb DATE;
    v_an_n NUMBER; v_an_t NUMBER; v_an_g NUMBER;
    v_da_n NUMBER; v_da_t NUMBER; v_da_g NUMBER;
    v_nhh DATE;
    v_cl_n NUMBER; v_cl_t NUMBER; v_cl_g NUMBER;
    v_tb NVARCHAR2(4000);
    -- Bi?n query t? DB
    v_THA_NGAY_BAT_DB       DATE;
    v_NGAY_THA              DATE;
    v_NGAY_THA_CO_DK        DATE;       -- Ngày tha (c?a b?n ghi có quay l?i)
    v_NGAY_QUAY_LAI_CO_DK   DATE;       -- Ngày quay l?i (NGAY_BAT_LAI)
    v_SO_NGAY_THA_CO_DK     NUMBER;     -- S? ngày gi?a ngày tha ? ngày quay l?i
-- === BI?N M?I CHO TR??NG H?P MI?N H?T ÁN ===
    v_NGAY_TU_DO DATE;         
    v_MIEM_HET_AN BOOLEAN := FALSE;
    v_ngay_tha_giam DATE;

BEGIN
    -- Kh?i t?o output m?c ??nh
    p_NGAY_HET_HAN := NULL;
    p_THONG_BAO := '';

    --====================================================================================
    -- B??C 1: Ki?m tra PN ?ã ra tr?i (PN_KET_THUC_RA_TRAIS)
    --====================================================================================
	IF p_PN_ID IS NOT NULL THEN
	    -- Case 1: K?t thúc ra tr?i
	    BEGIN
	        SELECT KTRT_NGAY_THA INTO v_NGAY_THA
	          FROM PN_KET_THUC_RA_TRAIS
	         WHERE KTRT_PN_LAI_LICH_ID = p_PN_ID
	           AND NVL(IS_DELETED, 0) = 0
	           AND KTRT_NGAY_THA IS NOT NULL
	         ORDER BY CREATION_TIME DESC
	         FETCH FIRST 1 ROW ONLY;
	    EXCEPTION WHEN NO_DATA_FOUND THEN v_NGAY_THA := NULL; END;

	    IF v_NGAY_THA IS NOT NULL THEN
	        p_NGAY_HET_HAN := v_NGAY_THA;
	        p_THONG_BAO := u'Ph?m nhân ?ã ???c th? vào ngày '
	            || TO_CHAR(v_NGAY_THA, 'DD/MM/YYYY') || u'. '
	            || u'?ã ch?p hành ??y ?? án ph?t.';
	        RETURN;
	    END IF;

		BEGIN
		    SELECT NGAY_THA_GIAM_HET_AN
		      INTO v_ngay_tha_giam
		      FROM GIAM_THOI_HANS gth
		      JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
		     WHERE PHAM_NHAN_ID = p_PN_ID
		       AND NVL(gth.IS_DELETED, 0) = 0
		       AND gth.NGAY_THA_GIAM_HET_AN IS NOT NULL;
		EXCEPTION
		    WHEN NO_DATA_FOUND THEN
		        v_ngay_tha_giam := NULL;
		END;

		-- N?u NGAY_THA_GIAM_HET_AN null, xét thêm NGAY_QUYET_DINH v?i mã '923000'
		IF v_ngay_tha_giam IS NULL THEN
		    BEGIN
		        SELECT gth.NGAY_QUYET_DINH
		          INTO v_ngay_tha_giam
		          FROM GIAM_THOI_HANS gth
		          JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
		         WHERE gth.PHAM_NHAN_ID = p_PN_ID
		           AND NVL(gth.IS_DELETED, 0) = 0
		           AND dmtg.MTG_MA = '923000'
		           AND gth.NGAY_QUYET_DINH IS NOT NULL
		           AND ROWNUM = 1;
		    EXCEPTION
		        WHEN NO_DATA_FOUND THEN
		            v_ngay_tha_giam := NULL;
		    END;
		END IF;

		-- N?u có thì override ngày h?t án
		IF v_ngay_tha_giam IS NOT NULL THEN
		    p_NGAY_HET_HAN := v_ngay_tha_giam;
		    p_THONG_BAO := u'Ph?m nhân ?ã ???c gi?m h?t án vào ngày '
		        || TO_CHAR(v_ngay_tha_giam, 'DD/MM/YYYY') || u'. '
		        || u'???c gi?m h?t án';
		    RETURN;
		END IF;


	    -- Case 2: ??c xá
	    BEGIN
	        SELECT DX_NGAY_THA INTO v_NGAY_THA
	          FROM PN_DAC_XAS
	         WHERE PNLAI_LICH_ID = p_PN_ID
	           AND NVL(IS_DELETED, 0) = 0
	           AND DX_NGAY_THA IS NOT NULL
	         ORDER BY CREATION_TIME DESC
	         FETCH FIRST 1 ROW ONLY;
	    EXCEPTION WHEN NO_DATA_FOUND THEN v_NGAY_THA := NULL; END;

	    IF v_NGAY_THA IS NOT NULL THEN
	        p_NGAY_HET_HAN := v_NGAY_THA;
	        p_THONG_BAO := u'Ph?m nhân ?ã ???c th? vào ngày '
	            || TO_CHAR(v_NGAY_THA, 'DD/MM/YYYY') || u'. '
	            || u'???c ??c xá.';
	        RETURN;
	    END IF;

-- Case 3: Tha có ?i?u ki?n (ch?a quay l?i ? ?ã RETURN ? trên n?u có)
    BEGIN
        SELECT NGAY_THA INTO v_NGAY_THA
          FROM THA_CO_DIEU_KIENS
         WHERE PHAM_NHAN_ID = p_PN_ID
           AND NVL(IS_DELETED, 0) = 0
           AND NGAY_THA IS NOT NULL
           AND NGAY_BAT_LAI IS NULL
         ORDER BY CREATION_TIME DESC
         FETCH FIRST 1 ROW ONLY;
    EXCEPTION WHEN NO_DATA_FOUND THEN v_NGAY_THA := NULL; END;

    IF v_NGAY_THA IS NOT NULL THEN
        p_NGAY_HET_HAN := v_NGAY_THA;
        p_THONG_BAO := u'Ph?m nhân ?ã ???c th? vào ngày '
            || TO_CHAR(v_NGAY_THA, 'DD/MM/YYYY') || u'. '
            || u'???c tha có ?i?u ki?n.';
        RETURN;
    END IF;


       BEGIN
        SELECT NGAY_TRA_TU_DO INTO v_NGAY_THA
          FROM HUY_ANS
         WHERE PHAM_NHAN_ID = p_PN_ID
           AND NVL(IS_DELETED, 0) = 0
           AND NGAY_TRA_TU_DO IS NOT NULL
           AND NGAY_TRO_LAI IS NULL
         ORDER BY CREATION_TIME DESC
         FETCH FIRST 1 ROW ONLY;
    EXCEPTION WHEN NO_DATA_FOUND THEN v_NGAY_THA := NULL; END;

    IF v_NGAY_THA IS NOT NULL THEN
        p_NGAY_HET_HAN := v_NGAY_THA;
        p_THONG_BAO := u'Ph?m nhân ?ã ???c th? vào ngày '
            || TO_CHAR(v_NGAY_THA, 'DD/MM/YYYY') || u'. '
            || u'???c h?y án.';
        RETURN;
    END IF;

    -- Case 4: Tha có ?i?u ki?n CÓ ngày quay l?i ? tính s? ngày t? do th?c t?
    BEGIN
        SELECT NGAY_THA, NGAY_BAT_LAI
          INTO v_NGAY_THA_CO_DK, v_NGAY_QUAY_LAI_CO_DK
          FROM THA_CO_DIEU_KIENS
         WHERE PHAM_NHAN_ID = p_PN_ID
           AND NVL(IS_DELETED, 0) = 0
           AND NGAY_THA IS NOT NULL
           AND NGAY_BAT_LAI IS NOT NULL     -- ? ?ã có ngày quay l?i
         ORDER BY CREATION_TIME DESC
         FETCH FIRST 1 ROW ONLY;

        -- Tính s? ngày t? ngày tha ? ngày quay l?i (bao g?m c? 2 ??u)
        v_SO_NGAY_THA_CO_DK := FLOOR(v_NGAY_QUAY_LAI_CO_DK - v_NGAY_THA_CO_DK);

    EXCEPTION WHEN NO_DATA_FOUND THEN
        v_NGAY_THA_CO_DK      := NULL;
        v_NGAY_QUAY_LAI_CO_DK := NULL;
        v_SO_NGAY_THA_CO_DK   := NULL;
    END;
END IF;

    --====================================================================================
    -- B??C 2: Query params t? DB n?u có PN_ID (PN_THI_HANH_AN)
    --====================================================================================
    IF p_PN_ID IS NOT NULL THEN
        BEGIN
            SELECT THA_NGAY_BAT, THA_AN_PHAT_GOC, THA_THOI_GIAN_TAM_GIAM,
                   THA_THOI_GIAN_TAM_GIU, THA_THOI_GIAN_O_TRUOC
              INTO v_THA_NGAY_BAT, v_THA_AN_PHAT_GOC, v_THA_TAM_GIAM_DB,
                   v_THA_TAM_GIU_DB, v_THA_O_TRUOC_DB
              FROM PN_THI_HANH_AN
             WHERE THA_PNLAI_LICH_ID = p_PN_ID AND ROWNUM = 1;
        EXCEPTION WHEN NO_DATA_FOUND THEN
            v_THA_NGAY_BAT := NULL;
            v_THA_AN_PHAT_GOC := NULL;
            v_THA_TAM_GIAM_DB := NULL;
            v_THA_TAM_GIU_DB := NULL;
            v_THA_O_TRUOC_DB := NULL;
        END;
    END IF;

    --====================================================================================
    -- B??C 3: Query 6 b?ng ?? t?ng h?p text params
    --====================================================================================
    IF p_PN_ID IS NOT NULL THEN
        -- 3a. Query GIAM_THOI_HANS: t?ng h?p MTG_TITLE
        DECLARE
            v_giam_nam   NUMBER := 0;
            v_giam_thang NUMBER := 0;
            v_giam_ngay  NUMBER := 0;
        BEGIN
            FOR rec IN (
                SELECT dmtg.MTG_TITLE
                  FROM GIAM_THOI_HANS gth
                  JOIN DM_MA_THOI_GIANS dmtg
                    ON gth.MUC_GIAM_ID = dmtg.ID
                   AND NVL(dmtg.IS_DELETED, 0) = 0
                 WHERE gth.PHAM_NHAN_ID = p_PN_ID
                   AND NVL(gth.IS_DELETED, 0) = 0
                   AND gth.MUC_GIAM_ID IS NOT NULL
            ) LOOP
                v_giam_nam   := v_giam_nam   + NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NAM'),   0);
                v_giam_thang := v_giam_thang + NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'THANG'), 0);
                v_giam_ngay  := v_giam_ngay  + NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NGAY'),  0);
            END LOOP;

            IF v_giam_nam > 0 OR v_giam_thang > 0 OR v_giam_ngay > 0 THEN
                v_GIAM_AN_TEXT :=
                    CASE WHEN v_giam_nam   > 0 THEN v_giam_nam   || ' nam '   ELSE '' END ||
                    CASE WHEN v_giam_thang > 0 THEN v_giam_thang || ' thang ' ELSE '' END ||
                    CASE WHEN v_giam_ngay  > 0 THEN v_giam_ngay  || ' ngay'   ELSE '' END;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_GIAM_AN_TEXT := NULL;
        END;

        BEGIN
	        SELECT dmtg.MTG_MA INTO v_MUC_GIAM_DACBIET_MA 
	        FROM GIAM_THOI_HANS gth
	        JOIN DM_MA_THOI_GIANS dmtg
	        ON dmtg.ID = gth.MUC_GIAM_ID
	        WHERE gth.PHAM_NHAN_ID = p_PN_ID 
	        AND gth.IS_DELETED = 0
	        AND dmtg.MTG_MA IN ('921000','922000')
	        AND ROWNUM = 1;
        EXCEPTION WHEN NO_DATA_FOUND THEN 
            v_MUC_GIAM_DACBIET_MA := NULL ;
        END;
        -- 3b. Query TRON_TRAIS: t?ng ngày tr?n
        DECLARE
            v_tong_ngay_tron NUMBER := 0;
        BEGIN
            FOR rec IN (
                SELECT CAST(tt.NGAY_TRON AS DATE) AS NGAY_TRON,
                       CAST(tt.NGAY_BAT_LAI AS DATE) AS NGAY_BAT_LAI
                  FROM TRON_TRAIS tt
                 WHERE tt.PHAM_NHAN_ID = p_PN_ID
                   AND NVL(tt.IS_DELETED, 0) = 0
                   AND tt.NGAY_TRON IS NOT NULL
                   AND tt.NGAY_BAT_LAI IS NOT NULL
            ) LOOP
                v_tong_ngay_tron := v_tong_ngay_tron + (FLOOR(rec.NGAY_BAT_LAI - rec.NGAY_TRON) + 1);
            END LOOP;
            IF v_tong_ngay_tron > 0 THEN
                v_TRON_TEXT := v_tong_ngay_tron || ' ngay';
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_TRON_TEXT := NULL;
        END;

        -- 3c. Query TAM_DINH_CHIS: t?ng ngày T?C
        DECLARE
            v_tong_ngay_tdc NUMBER := 0;
        BEGIN
            FOR rec IN (
                SELECT TRUNC(tdc.NGAY_TDC) AS NGAY_TDC, TRUNC(tdc.NGAY_LAI) AS NGAY_LAI
                  FROM TAM_DINH_CHIS tdc
                 WHERE tdc.PHAM_NHAN_ID = p_PN_ID
                   AND tdc.IS_DELETED = 0
                   AND tdc.NGAY_TDC IS NOT NULL
                   AND tdc.NGAY_LAI IS NOT NULL
            ) LOOP
                v_tong_ngay_tdc := v_tong_ngay_tdc + (rec.NGAY_LAI - rec.NGAY_TDC + 1);
            END LOOP;
            IF v_tong_ngay_tdc > 0 THEN
                v_TDC_TEXT := v_tong_ngay_tdc || ' ngay';
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_TDC_TEXT := NULL;
        END;

        -- 3d. Query HOAN_THI_HANH_ANS: t?ng ngày hoãn
        DECLARE
            v_tong_ngay_hoan NUMBER := 0;
        BEGIN
            FOR rec IN (
                SELECT CAST(htha.NGAY_HOAN AS DATE) AS NGAY_HOAN,
                       CAST(htha.NGAY_THI_HANH_AN AS DATE) AS NGAY_THA
                  FROM HOAN_THI_HANH_ANS htha
                 WHERE htha.PHAM_NHAN_ID = p_PN_ID
                   AND NVL(htha.IS_DELETED, 0) = 0
                   AND htha.NGAY_HOAN IS NOT NULL
                   AND htha.NGAY_THI_HANH_AN IS NOT NULL
            ) LOOP
                v_tong_ngay_hoan := v_tong_ngay_hoan + (FLOOR(rec.NGAY_THA - rec.NGAY_HOAN) + 1);
            END LOOP;
            IF v_tong_ngay_hoan > 0 THEN
                v_HOAN_TEXT := v_tong_ngay_hoan || ' ngay';
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_HOAN_TEXT := NULL;
        END;
		IF p_PN_ID IS NOT NULL THEN


	        -- === THÊM LOGIC KI?M TRA MI?N H?T ÁN 92300 ===
	        BEGIN
	            SELECT MHP_NGAY_TU_DO                         
	              INTO v_NGAY_TU_DO
	              FROM MIEN_HINH_PHATS
	             WHERE PN_LAI_LICH_ID = p_PN_ID 
	               AND IS_DELETED = 0
	               AND NVL(MHP_THM_YEAR, 0) = 9
	               AND NVL(MHP_THM_MONTH, 0) = 23
	               AND NVL(MHP_THM_DAY, 0) = 0
	             ORDER BY CREATION_TIME DESC
	             FETCH FIRST 1 ROW ONLY;

	            v_MIEM_HET_AN := TRUE;
	        EXCEPTION 
	            WHEN NO_DATA_FOUND THEN 
	                v_MIEM_HET_AN := FALSE;
	                v_NGAY_TU_DO := NULL;
	        END;

	        -- N?u là mi?n h?t án ? x? lý ngay và RETURN
	        IF v_MIEM_HET_AN AND v_NGAY_TU_DO IS NOT NULL THEN
	            p_NGAY_HET_HAN := v_NGAY_TU_DO;
	            p_THONG_BAO := u'Ph?m nhân ???c mi?n h?t án (92300). '
	                        || u'Ngày t? do: ' || TO_CHAR(v_NGAY_TU_DO, 'DD/MM/YYYY');
	            RETURN;
		        END IF;
	    END IF;
        -- 3e. Query MIEN_HINH_PHATS: mi?n hình ph?t ? chuy?n thành text
        DECLARE
            v_mien_nam   NUMBER := 0;
            v_mien_thang NUMBER := 0;
            v_mien_ngay  NUMBER := 0;
        BEGIN
            SELECT NVL(SUM(NVL(MHP_THM_YEAR, 0)), 0),
                   NVL(SUM(NVL(MHP_THM_MONTH, 0)), 0),
                   NVL(SUM(NVL(MHP_THM_DAY, 0)), 0)
              INTO v_mien_nam, v_mien_thang, v_mien_ngay
              FROM MIEN_HINH_PHATS
             WHERE PN_LAI_LICH_ID = p_PN_ID AND IS_DELETED = 0;
            IF v_mien_nam > 0 OR v_mien_thang > 0 OR v_mien_ngay > 0 THEN
                v_MIEN_HP_TEXT := CASE WHEN v_mien_nam > 0 THEN v_mien_nam || ' nam ' ELSE '' END
                                || CASE WHEN v_mien_thang > 0 THEN v_mien_thang || ' thang ' ELSE '' END
                                || CASE WHEN v_mien_ngay > 0 THEN v_mien_ngay || ' ngay' ELSE '' END;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_MIEN_HP_TEXT := NULL;
        END;

        -- 3f. Query TANG_GIAM_HINH_PHATS: t?ng/gi?m hình ph?t ? chuy?n thành text
        DECLARE
            v_tang_nam   NUMBER := 0; v_tang_thang NUMBER := 0; v_tang_ngay NUMBER := 0;
            v_giam_nam   NUMBER := 0; v_giam_thang NUMBER := 0; v_giam_ngay NUMBER := 0;
        BEGIN
            FOR rec IN (
                SELECT dmtg.MTG_TITLE, ltg.LTGHP_MA
                  FROM TANG_GIAM_HINH_PHATS tghp
                  JOIN DM_LOAI_TANG_GIAM_HINH_PHATS ltg ON tghp.LOAI_TANG_GIAM_ID = ltg.ID
                  JOIN DM_MA_THOI_GIANS dmtg ON tghp.THOI_HAN_ID = dmtg.ID
                 WHERE tghp.PHAM_NHAN_ID = p_PN_ID
                   AND NVL(tghp.IS_DELETED, 0) = 0
                   AND tghp.THOI_HAN_ID IS NOT NULL
            ) LOOP
                DECLARE
                    v_t_nam   NUMBER := NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NAM'), 0);
                    v_t_thang NUMBER := NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'THANG'), 0);
                    v_t_ngay  NUMBER := NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NGAY'), 0);
                BEGIN
                    IF rec.LTGHP_MA = '10' THEN
                        v_tang_nam   := v_tang_nam   + v_t_nam;
                        v_tang_thang := v_tang_thang + v_t_thang;
                        v_tang_ngay  := v_tang_ngay  + v_t_ngay;
                    ELSIF rec.LTGHP_MA = '20' THEN
                        v_giam_nam   := v_giam_nam   + v_t_nam;
                        v_giam_thang := v_giam_thang + v_t_thang;
                        v_giam_ngay  := v_giam_ngay  + v_t_ngay;
                    END IF;
                END;
            END LOOP;
            IF v_tang_nam > 0 OR v_tang_thang > 0 OR v_tang_ngay > 0 THEN
                v_TANG_HP_TEXT := CASE WHEN v_tang_nam > 0 THEN v_tang_nam || ' nam ' ELSE '' END
                                || CASE WHEN v_tang_thang > 0 THEN v_tang_thang || ' thang ' ELSE '' END
                                || CASE WHEN v_tang_ngay > 0 THEN v_tang_ngay || ' ngay' ELSE '' END;
            END IF;
            IF v_giam_nam > 0 OR v_giam_thang > 0 OR v_giam_ngay > 0 THEN
                v_GIAM_HP_TEXT := CASE WHEN v_giam_nam > 0 THEN v_giam_nam || ' nam ' ELSE '' END
                                || CASE WHEN v_giam_thang > 0 THEN v_giam_thang || ' thang ' ELSE '' END
                                || CASE WHEN v_giam_ngay > 0 THEN v_giam_ngay || ' ngay' ELSE '' END;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_TANG_HP_TEXT := NULL;
            v_GIAM_HP_TEXT := NULL;
        END;
        -- B??C 3 b? sung: Ki?m tra b?n ghi ch?a k?t thúc
DECLARE
    v_cnt_tron_chua_ve  NUMBER := 0;
    v_cnt_tdc_chua_ve   NUMBER := 0;
    v_cnt_hoan_chua_ve  NUMBER := 0;
BEGIN
    -- Tr?n ch?a b?t l?i
    SELECT COUNT(*) INTO v_cnt_tron_chua_ve
      FROM TRON_TRAIS
     WHERE PHAM_NHAN_ID = p_PN_ID
       AND NVL(IS_DELETED, 0) = 0
       AND NGAY_TRON IS NOT NULL
       AND NGAY_BAT_LAI IS NULL;   -- ? ch?a có ngày b?t l?i

    -- T?C ch?a quay l?i
    SELECT COUNT(*) INTO v_cnt_tdc_chua_ve
      FROM TAM_DINH_CHIS
     WHERE PHAM_NHAN_ID = p_PN_ID
       AND NVL(IS_DELETED, 0) = 0
       AND TU_NGAY IS NOT NULL
       AND NGAY_LAI IS NULL;       -- ? ch?a có ngày l?i

    -- Hoãn ch?a thi hành
    SELECT COUNT(*) INTO v_cnt_hoan_chua_ve
      FROM HOAN_THI_HANH_ANS
     WHERE PHAM_NHAN_ID = p_PN_ID
       AND NVL(IS_DELETED, 0) = 0
       AND NGAY_HOAN IS NOT NULL
       AND NGAY_THI_HANH_AN IS NULL; -- ? ch?a có ngày thi hành án

    -- N?u b?t k? b?ng nào có record ch?a k?t thúc ? NULL ngay
    IF v_cnt_tron_chua_ve > 0 OR v_cnt_tdc_chua_ve > 0 OR v_cnt_hoan_chua_ve > 0 THEN
        p_NGAY_HET_HAN := NULL;
        p_THONG_BAO := 
            CASE WHEN v_cnt_tron_chua_ve > 0 
                 THEN u'Ch?a xác ??nh: còn ' || v_cnt_tron_chua_ve || u' l?n tr?n ch?a b?t l?i. ' 
                 ELSE '' END ||
            CASE WHEN v_cnt_tdc_chua_ve > 0 
                 THEN u'Ch?a xác ??nh: còn ' || v_cnt_tdc_chua_ve || u' l?n T?C ch?a quay l?i. ' 
                 ELSE '' END ||
            CASE WHEN v_cnt_hoan_chua_ve > 0 
                 THEN u'Ch?a xác ??nh: còn ' || v_cnt_hoan_chua_ve || u' l?n hoãn ch?a thi hành. ' 
                 ELSE '' END;
        RETURN;
    END IF;
	END;
    END IF;

    --====================================================================================
    --====================================================================================
    -- B??C 4: Xác ??nh params theo quy t?c ?u tiên - ?Ã S?A
    -- Khi p_DUNG_PARAM = 1:
    --   - Param truy?n vào KHÁC NULL ? ?u tiên dùng param
    --   - Param truy?n vào = NULL     ? không l?y t? DB (coi nh? không có)
    --====================================================================================
    IF NVL(p_DUNG_PARAM, 0) = 1 THEN
        -- Mode Test / Dùng param: NULL ngh?a là "không có"
        v_NGAY_BAT     := NVL(p_NGAY_BAT, v_THA_NGAY_BAT);

        v_AN_PHAT_TEXT := CASE WHEN p_THA_AN_PHAT_TEXT IS NOT NULL 
                               THEN p_THA_AN_PHAT_TEXT 
                               ELSE NULL END;

        v_TAM_GIAM_TEXT := CASE WHEN p_THA_TAM_GIAM_TEXT IS NOT NULL 
                                THEN p_THA_TAM_GIAM_TEXT 
                                ELSE NULL END;

        v_TAM_GIU_TEXT := CASE WHEN p_THA_TAM_GIU_TEXT IS NOT NULL 
                               THEN p_THA_TAM_GIU_TEXT 
                               ELSE NULL END;

        v_O_TRUOC_TEXT := CASE WHEN p_THA_O_TRUOC_TEXT IS NOT NULL 
                               THEN p_THA_O_TRUOC_TEXT 
                               ELSE NULL END;
--        v_MIEN_HP_TEXT := CASE WHEN p_MIEN_HP_TEXT IS NOT NULL 
--                               THEN p_MIEN_HP_TEXT 
--                               ELSE NULL END;
    ELSE
        -- Mode bình th??ng: v?n dùng NVL nh? c? (?u tiên param, NULL thì l?y DB)
        v_NGAY_BAT     := NVL(p_NGAY_BAT, v_THA_NGAY_BAT);
        v_AN_PHAT_TEXT := NVL(p_THA_AN_PHAT_TEXT, v_THA_AN_PHAT_GOC);
        v_TAM_GIAM_TEXT:= NVL(p_THA_TAM_GIAM_TEXT, v_THA_TAM_GIAM_DB);
        v_TAM_GIU_TEXT := NVL(p_THA_TAM_GIU_TEXT, v_THA_TAM_GIU_DB);
        v_O_TRUOC_TEXT := NVL(p_THA_O_TRUOC_TEXT, v_THA_O_TRUOC_DB);
        IF  v_MUC_GIAM_DACBIET_MA = '922000' THEN v_AN_PHAT_TEXT := '20 nam';
        ELSIF v_MUC_GIAM_DACBIET_MA = '921000' THEN v_AN_PHAT_TEXT := '30 nam';
        END IF ;
--		v_MIEN_HP_TEXT := NVL(p_MIEN_HP_TEXT, v_THA_O_TRUOC_DB);
    END IF;

    --====================================================================================
    -- B??C 5: Ki?m tra d? li?u b?t bu?c
    --====================================================================================
    IF v_NGAY_BAT IS NULL THEN
        p_THONG_BAO := u'L?i: Ngày b?t là b?t bu?c (p_NGAY_BAT ho?c t? DB).';
        RETURN;
    END IF;

    --====================================================================================
    -- B??C 6: G?i SP g?c
    --   - Truy?n p_PN_ID ?? SP g?c query thêm MI?N và T?NG/GI?M HP (n?u c?n)
    --   - Truy?n DUNG_PARAM = 1 ?? SP g?c dùng text params ?ã t?ng h?p
    --   - Truy?n ??y ?? params m?i: GIAM_HP_TEXT, MIEN_HP_TEXT, TANG_HP_TEXT
    --====================================================================================
    SP_TINH_NGAY_HET_AN_GENERAL(
        p_PN_ID                  => null,
        p_NGAY_BAT               => v_NGAY_BAT,
        p_NGAY_YC_TINH           => p_NGAY_YC_TINH,
        p_THA_AN_PHAT_TEXT       => v_AN_PHAT_TEXT,
        p_THA_TAM_GIAM_TEXT      => v_TAM_GIAM_TEXT,
        p_THA_TAM_GIU_TEXT       => v_TAM_GIU_TEXT,
        p_THA_O_TRUOC_TEXT       => v_O_TRUOC_TEXT,
        p_THA_GIAM_HP_TEXT       => v_GIAM_HP_TEXT,
        p_THA_MIEN_HP_TEXT       => v_MIEN_HP_TEXT,
        p_THA_TANG_HINH_PHAT_TEXT => v_TANG_HP_TEXT,
        p_DUNG_PARAM             => 1,
        p_GIAM_AN_TEXT           => v_GIAM_AN_TEXT,
        p_TRON_TEXT              => v_TRON_TEXT,
        p_TDC_TEXT               => v_TDC_TEXT,
        p_HOAN_TEXT              => v_HOAN_TEXT,
        p_NGAY_BAT_OUT           => v_nb,
        p_AN_THUC_NAM            => v_an_n,
        p_AN_THUC_THANG          => v_an_t,
        p_AN_THUC_NGAY           => v_an_g,
        p_DA_CHAP_HANH_NAM       => v_da_n,
        p_DA_CHAP_HANH_THANG     => v_da_t,
        p_DA_CHAP_HANH_NGAY      => v_da_g,
        p_NGAY_HET_HAN           => v_nhh,
        p_THOI_GIAN_CON_LAI_NAM   => v_cl_n,
        p_THOI_GIAN_CON_LAI_THANG => v_cl_t,
        p_THOI_GIAN_CON_LAI_NGAY  => v_cl_g,
        p_THONG_BAO              => v_tb
    );

    p_NGAY_HET_HAN := v_nhh;
    p_THONG_BAO    := v_tb;

--==========================================================================================
-- EXCEPTION HANDLER
--========================================================================================--
EXCEPTION WHEN OTHERS THEN
    p_NGAY_HET_HAN := NULL;
    p_THONG_BAO := u'L?i: ' || SQLERRM;
END SP_TINH_NGAY_HET_AN_DEMO_FINAL2;


/
--------------------------------------------------------
--  DDL for Procedure SP_TINH_NGAY_HET_AN_DEMO_FINAL_TAS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_TINH_NGAY_HET_AN_DEMO_FINAL_TAS" (
    p_PN_ID             IN NUMBER    DEFAULT NULL,
    p_NGAY_BAT          IN DATE      DEFAULT NULL,
    p_NGAY_YC_TINH      IN NUMBER    DEFAULT NULL,
    p_THA_AN_PHAT_TEXT  IN NVARCHAR2 DEFAULT NULL,
    p_THA_TAM_GIAM_TEXT IN NVARCHAR2 DEFAULT NULL,
    p_THA_TAM_GIU_TEXT  IN NVARCHAR2 DEFAULT NULL,
    p_THA_O_TRUOC_TEXT  IN NVARCHAR2 DEFAULT NULL,
    p_MIEN_HP_TEXT      IN NVARCHAR2 DEFAULT NULL,
    p_DUNG_PARAM        IN NUMBER    DEFAULT NULL,
    p_MHP               IN NUMBER    DEFAULT NULL,
    p_NGAY_HET_HAN      OUT DATE,
    p_THONG_BAO         OUT NVARCHAR2
)
IS
    -- Bi?n l?u params t? DB (PN_THI_HANH_AN)
    v_THA_NGAY_BAT           DATE;
    v_THA_AN_PHAT_GOC       NVARCHAR2(500);
    v_THA_TAM_GIAM_DB       NVARCHAR2(500);
    v_THA_TAM_GIU_DB        NVARCHAR2(500);
    v_THA_O_TRUOC_DB        NVARCHAR2(500);

    -- Params ?ã xác ??nh (t? param truy?n vào ho?c query t? DB)
    v_NGAY_BAT              DATE;
    v_AN_PHAT_TEXT          NVARCHAR2(500);
    v_TAM_GIAM_TEXT         NVARCHAR2(500);
    v_TAM_GIU_TEXT          NVARCHAR2(500);
    v_O_TRUOC_TEXT          NVARCHAR2(500);

    -- 4 text params t?ng h?p t? 4 b?ng (GIAM, TRON, TDC, HOAN)
    v_GIAM_AN_TEXT          NVARCHAR2(4000);
    v_TRON_TEXT             NVARCHAR2(4000);
    v_TDC_TEXT              NVARCHAR2(4000);
    v_HOAN_TEXT             NVARCHAR2(4000);

    -- 3 text params HP (t? MIEN_HINH_PHATS, TANG_GIAM_HINH_PHATS)
    v_GIAM_HP_TEXT          NVARCHAR2(500);
    v_MIEN_HP_TEXT          NVARCHAR2(500);
    v_TANG_HP_TEXT          NVARCHAR2(500);

    -- Bi?n t?m cho output t? SP g?c
    v_nb DATE;
    v_an_n NUMBER; v_an_t NUMBER; v_an_g NUMBER;
    v_da_n NUMBER; v_da_t NUMBER; v_da_g NUMBER;
    v_nhh DATE;
    v_cl_n NUMBER; v_cl_t NUMBER; v_cl_g NUMBER;
    v_tb NVARCHAR2(4000);
    -- Bi?n query t? DB
    v_THA_NGAY_BAT_DB       DATE;
    v_NGAY_THA              DATE;
-- === BI?N M?I CHO TR??NG H?P MI?N H?T ÁN ===
    v_NGAY_TU_DO DATE;         
    v_MIEM_HET_AN BOOLEAN := FALSE;

BEGIN
    -- Kh?i t?o output m?c ??nh
    p_NGAY_HET_HAN := NULL;
    p_THONG_BAO := '';

    --====================================================================================
    -- B??C 1: Ki?m tra PN ?ã ra tr?i (PN_KET_THUC_RA_TRAIS)
    --====================================================================================
    IF p_PN_ID IS NOT NULL THEN
        BEGIN
            SELECT KTRT_NGAY_THA INTO v_NGAY_THA
              FROM PN_KET_THUC_RA_TRAIS
             WHERE KTRT_PN_LAI_LICH_ID = p_PN_ID
               AND NVL(IS_DELETED, 0) = 0
               AND KTRT_NGAY_THA IS NOT NULL
             ORDER BY CREATION_TIME DESC
             FETCH FIRST 1 ROW ONLY;
        EXCEPTION WHEN NO_DATA_FOUND THEN v_NGAY_THA := NULL; END;

        IF v_NGAY_THA IS NOT NULL THEN
            p_NGAY_HET_HAN := v_NGAY_THA;
            p_THONG_BAO := u'Ph?m nhân ?ã ???c th? vào ngày '
                || TO_CHAR(v_NGAY_THA, 'DD/MM/YYYY') || u'. '
                || u'?ã ch?p hành ??y ?? án ph?t.';
            RETURN;
        END IF;
    END IF;

    --====================================================================================
    -- B??C 2: Query params t? DB n?u có PN_ID (PN_THI_HANH_AN)
    --====================================================================================
    IF p_PN_ID IS NOT NULL THEN
        BEGIN
            SELECT THA_NGAY_BAT, THA_AN_PHAT_GOC, THA_THOI_GIAN_TAM_GIAM,
                   THA_THOI_GIAN_TAM_GIU, THA_THOI_GIAN_O_TRUOC
              INTO v_THA_NGAY_BAT, v_THA_AN_PHAT_GOC, v_THA_TAM_GIAM_DB,
                   v_THA_TAM_GIU_DB, v_THA_O_TRUOC_DB
              FROM PN_THI_HANH_AN
             WHERE THA_PNLAI_LICH_ID = p_PN_ID AND ROWNUM = 1;
        EXCEPTION WHEN NO_DATA_FOUND THEN
            v_THA_NGAY_BAT := NULL;
            v_THA_AN_PHAT_GOC := NULL;
            v_THA_TAM_GIAM_DB := NULL;
            v_THA_TAM_GIU_DB := NULL;
            v_THA_O_TRUOC_DB := NULL;
        END;
    END IF;

    --====================================================================================
    -- B??C 3: Query 6 b?ng ?? t?ng h?p text params
    --====================================================================================
    IF p_PN_ID IS NOT NULL THEN
        -- 3a. Query GIAM_THOI_HANS: t?ng h?p MTG_TITLE
        DECLARE
            v_giam_nam   NUMBER := 0;
            v_giam_thang NUMBER := 0;
            v_giam_ngay  NUMBER := 0;
        BEGIN
            FOR rec IN (
                SELECT dmtg.MTG_TITLE
                  FROM GIAM_THOI_HANS gth
                  JOIN DM_MA_THOI_GIANS dmtg
                    ON gth.MUC_GIAM_ID = dmtg.ID
                   AND NVL(dmtg.IS_DELETED, 0) = 0
                 WHERE gth.PHAM_NHAN_ID = p_PN_ID
                   AND NVL(gth.IS_DELETED, 0) = 0
                   AND gth.MUC_GIAM_ID IS NOT NULL
            ) LOOP
                v_giam_nam   := v_giam_nam   + NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NAM'),   0);
                v_giam_thang := v_giam_thang + NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'THANG'), 0);
                v_giam_ngay  := v_giam_ngay  + NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NGAY'),  0);
            END LOOP;

            IF v_giam_nam > 0 OR v_giam_thang > 0 OR v_giam_ngay > 0 THEN
                v_GIAM_AN_TEXT :=
                    CASE WHEN v_giam_nam   > 0 THEN v_giam_nam   || ' nam '   ELSE '' END ||
                    CASE WHEN v_giam_thang > 0 THEN v_giam_thang || ' thang ' ELSE '' END ||
                    CASE WHEN v_giam_ngay  > 0 THEN v_giam_ngay  || ' ngay'   ELSE '' END;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_GIAM_AN_TEXT := NULL;
        END;

        -- 3b. Query TRON_TRAIS: t?ng ngày tr?n
        DECLARE
            v_tong_ngay_tron NUMBER := 0;
        BEGIN
            FOR rec IN (
                SELECT CAST(tt.NGAY_TRON AS DATE) AS NGAY_TRON,
                       CAST(tt.NGAY_BAT_LAI AS DATE) AS NGAY_BAT_LAI
                  FROM TRON_TRAIS tt
                 WHERE tt.PHAM_NHAN_ID = p_PN_ID
                   AND NVL(tt.IS_DELETED, 0) = 0
                   AND tt.NGAY_TRON IS NOT NULL
                   AND tt.NGAY_BAT_LAI IS NOT NULL
            ) LOOP
                v_tong_ngay_tron := v_tong_ngay_tron + (FLOOR(rec.NGAY_BAT_LAI - rec.NGAY_TRON) + 1);
            END LOOP;
            IF v_tong_ngay_tron > 0 THEN
                v_TRON_TEXT := v_tong_ngay_tron || ' ngay';
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_TRON_TEXT := NULL;
        END;

        -- 3c. Query TAM_DINH_CHIS: t?ng ngày T?C
        DECLARE
            v_tong_ngay_tdc NUMBER := 0;
        BEGIN
            FOR rec IN (
                SELECT TRUNC(tdc.NGAY_TDC) AS NGAY_TDC, TRUNC(tdc.NGAY_LAI) AS NGAY_LAI
                  FROM TAM_DINH_CHIS tdc
                 WHERE tdc.PHAM_NHAN_ID = p_PN_ID
                   AND tdc.IS_DELETED = 0
                   AND tdc.NGAY_TDC IS NOT NULL
                   AND tdc.NGAY_LAI IS NOT NULL
            ) LOOP
                v_tong_ngay_tdc := v_tong_ngay_tdc + (rec.NGAY_LAI - rec.NGAY_TDC + 1);
            END LOOP;
            IF v_tong_ngay_tdc > 0 THEN
                v_TDC_TEXT := v_tong_ngay_tdc || ' ngay';
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_TDC_TEXT := NULL;
        END;

        -- 3d. Query HOAN_THI_HANH_ANS: t?ng ngày hoãn
        DECLARE
            v_tong_ngay_hoan NUMBER := 0;
        BEGIN
            FOR rec IN (
                SELECT CAST(htha.NGAY_HOAN AS DATE) AS NGAY_HOAN,
                       CAST(htha.NGAY_THI_HANH_AN AS DATE) AS NGAY_THA
                  FROM HOAN_THI_HANH_ANS htha
                 WHERE htha.PHAM_NHAN_ID = p_PN_ID
                   AND NVL(htha.IS_DELETED, 0) = 0
                   AND htha.NGAY_HOAN IS NOT NULL
                   AND htha.NGAY_THI_HANH_AN IS NOT NULL
            ) LOOP
                v_tong_ngay_hoan := v_tong_ngay_hoan + (FLOOR(rec.NGAY_THA - rec.NGAY_HOAN) + 1);
            END LOOP;
            IF v_tong_ngay_hoan > 0 THEN
                v_HOAN_TEXT := v_tong_ngay_hoan || ' ngay';
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_HOAN_TEXT := NULL;
        END;
		IF p_PN_ID IS NOT NULL THEN


	        -- === THÊM LOGIC KI?M TRA MI?N H?T ÁN 92300 ===
	        BEGIN
	            SELECT MHP_NGAY_TU_DO                         
	              INTO v_NGAY_TU_DO
	              FROM MIEN_HINH_PHATS
	             WHERE PN_LAI_LICH_ID = p_PN_ID 
	               AND IS_DELETED = 0
	               AND NVL(MHP_THM_YEAR, 0) = 9
	               AND NVL(MHP_THM_MONTH, 0) = 23
	               AND NVL(MHP_THM_DAY, 0) = 0
	             ORDER BY CREATION_TIME DESC
	             FETCH FIRST 1 ROW ONLY;

	            v_MIEM_HET_AN := TRUE;
	        EXCEPTION 
	            WHEN NO_DATA_FOUND THEN 
	                v_MIEM_HET_AN := FALSE;
	                v_NGAY_TU_DO := NULL;
	        END;

	        -- N?u là mi?n h?t án ? x? lý ngay và RETURN
	        IF v_MIEM_HET_AN AND v_NGAY_TU_DO IS NOT NULL THEN
	            p_NGAY_HET_HAN := v_NGAY_TU_DO;
	            p_THONG_BAO := u'Ph?m nhân ???c mi?n h?t án (92300). '
	                        || u'Ngày t? do: ' || TO_CHAR(v_NGAY_TU_DO, 'DD/MM/YYYY');
	            RETURN;
		        END IF;
	    END IF;
	-- 3e. MIEN_HINH_PHATS: n?u param truy?n vào thì dùng, không thì query DB
	IF p_MIEN_HP_TEXT IS NOT NULL THEN
	    v_MIEN_HP_TEXT := p_MIEN_HP_TEXT;
	ELSE
	    DECLARE
	        v_mien_nam   NUMBER := 0;
	        v_mien_thang NUMBER := 0;
	        v_mien_ngay  NUMBER := 0;
	    BEGIN
	        SELECT NVL(SUM(NVL(MHP_THM_YEAR,  0)), 0),
	               NVL(SUM(NVL(MHP_THM_MONTH, 0)), 0),
	               NVL(SUM(NVL(MHP_THM_DAY,   0)), 0)
	          INTO v_mien_nam, v_mien_thang, v_mien_ngay
	          FROM MIEN_HINH_PHATS
	         WHERE PN_LAI_LICH_ID = p_PN_ID
	           AND IS_DELETED = 0;

	        IF v_mien_nam > 0 OR v_mien_thang > 0 OR v_mien_ngay > 0 THEN
	            v_MIEN_HP_TEXT :=
	                CASE WHEN v_mien_nam   > 0 THEN v_mien_nam   || ' nam '   ELSE '' END ||
	                CASE WHEN v_mien_thang > 0 THEN v_mien_thang || ' thang ' ELSE '' END ||
	                CASE WHEN v_mien_ngay  > 0 THEN v_mien_ngay  || ' ngay'   ELSE '' END;
	        END IF;
	    EXCEPTION WHEN OTHERS THEN
	        v_MIEN_HP_TEXT := NULL;
	    END;
	END IF;

        -- 3f. Query TANG_GIAM_HINH_PHATS: t?ng/gi?m hình ph?t ? chuy?n thành text
        DECLARE
            v_tang_nam   NUMBER := 0; v_tang_thang NUMBER := 0; v_tang_ngay NUMBER := 0;
            v_giam_nam   NUMBER := 0; v_giam_thang NUMBER := 0; v_giam_ngay NUMBER := 0;
        BEGIN
            FOR rec IN (
                SELECT dmtg.MTG_TITLE, ltg.LTGHP_MA
                  FROM TANG_GIAM_HINH_PHATS tghp
                  JOIN DM_LOAI_TANG_GIAM_HINH_PHATS ltg ON tghp.LOAI_TANG_GIAM_ID = ltg.ID
                  JOIN DM_MA_THOI_GIANS dmtg ON tghp.THOI_HAN_ID = dmtg.ID
                 WHERE tghp.PHAM_NHAN_ID = p_PN_ID
                   AND NVL(tghp.IS_DELETED, 0) = 0
                   AND tghp.THOI_HAN_ID IS NOT NULL
            ) LOOP
                DECLARE
                    v_t_nam   NUMBER := NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NAM'), 0);
                    v_t_thang NUMBER := NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'THANG'), 0);
                    v_t_ngay  NUMBER := NVL(FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NGAY'), 0);
                BEGIN
                    IF rec.LTGHP_MA = '10' THEN
                        v_tang_nam   := v_tang_nam   + v_t_nam;
                        v_tang_thang := v_tang_thang + v_t_thang;
                        v_tang_ngay  := v_tang_ngay  + v_t_ngay;
                    ELSIF rec.LTGHP_MA = '20' THEN
                        v_giam_nam   := v_giam_nam   + v_t_nam;
                        v_giam_thang := v_giam_thang + v_t_thang;
                        v_giam_ngay  := v_giam_ngay  + v_t_ngay;
                    END IF;
                END;
            END LOOP;
            IF v_tang_nam > 0 OR v_tang_thang > 0 OR v_tang_ngay > 0 THEN
                v_TANG_HP_TEXT := CASE WHEN v_tang_nam > 0 THEN v_tang_nam || ' nam ' ELSE '' END
                                || CASE WHEN v_tang_thang > 0 THEN v_tang_thang || ' thang ' ELSE '' END
                                || CASE WHEN v_tang_ngay > 0 THEN v_tang_ngay || ' ngay' ELSE '' END;
            END IF;
            IF v_giam_nam > 0 OR v_giam_thang > 0 OR v_giam_ngay > 0 THEN
                v_GIAM_HP_TEXT := CASE WHEN v_giam_nam > 0 THEN v_giam_nam || ' nam ' ELSE '' END
                                || CASE WHEN v_giam_thang > 0 THEN v_giam_thang || ' thang ' ELSE '' END
                                || CASE WHEN v_giam_ngay > 0 THEN v_giam_ngay || ' ngay' ELSE '' END;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_TANG_HP_TEXT := NULL;
            v_GIAM_HP_TEXT := NULL;
        END;
    END IF;

    --====================================================================================
    --====================================================================================
    -- B??C 4: Xác ??nh params theo quy t?c ?u tiên - ?Ã S?A
    -- Khi p_DUNG_PARAM = 1:
    --   - Param truy?n vào KHÁC NULL ? ?u tiên dùng param
    --   - Param truy?n vào = NULL     ? không l?y t? DB (coi nh? không có)
    --====================================================================================
	v_NGAY_BAT      := NVL(p_NGAY_BAT, v_THA_NGAY_BAT);
	v_AN_PHAT_TEXT  := NVL(p_THA_AN_PHAT_TEXT, v_THA_AN_PHAT_GOC);
	v_TAM_GIAM_TEXT := NVL(p_THA_TAM_GIAM_TEXT, v_THA_TAM_GIAM_DB);
	v_TAM_GIU_TEXT  := NVL(p_THA_TAM_GIU_TEXT,  v_THA_TAM_GIU_DB);
	v_O_TRUOC_TEXT  := NVL(p_THA_O_TRUOC_TEXT,  v_THA_O_TRUOC_DB);
    -- v_MIEN_HP_TEXT gi? nguyên t? B??c 3e

    --====================================================================================
    -- B??C 5: Ki?m tra d? li?u b?t bu?c
    --====================================================================================
    IF v_NGAY_BAT IS NULL THEN
        p_THONG_BAO := u'L?i: Ngày b?t là b?t bu?c (p_NGAY_BAT ho?c t? DB).';
        RETURN;
    END IF;

    --====================================================================================
    -- B??C 6: G?i SP g?c
    --   - Truy?n p_PN_ID ?? SP g?c query thêm MI?N và T?NG/GI?M HP (n?u c?n)
    --   - Truy?n DUNG_PARAM = 1 ?? SP g?c dùng text params ?ã t?ng h?p
    --   - Truy?n ??y ?? params m?i: GIAM_HP_TEXT, MIEN_HP_TEXT, TANG_HP_TEXT
    --====================================================================================
    SP_TINH_NGAY_HET_AN_GENERAL(
        p_PN_ID                  => null,
        p_NGAY_BAT               => v_NGAY_BAT,
        p_NGAY_YC_TINH           => p_NGAY_YC_TINH,
        p_THA_AN_PHAT_TEXT       => v_AN_PHAT_TEXT,
        p_THA_TAM_GIAM_TEXT      => v_TAM_GIAM_TEXT,
        p_THA_TAM_GIU_TEXT       => v_TAM_GIU_TEXT,
        p_THA_O_TRUOC_TEXT       => v_O_TRUOC_TEXT,
        p_THA_GIAM_HP_TEXT       => v_GIAM_HP_TEXT,
        p_THA_MIEN_HP_TEXT       => v_MIEN_HP_TEXT,
        p_THA_TANG_HINH_PHAT_TEXT => v_TANG_HP_TEXT,
        p_DUNG_PARAM             => 1,
        p_GIAM_AN_TEXT           => v_GIAM_AN_TEXT,
        p_TRON_TEXT              => v_TRON_TEXT,
        p_TDC_TEXT               => v_TDC_TEXT,
        p_HOAN_TEXT              => v_HOAN_TEXT,
        p_NGAY_BAT_OUT           => v_nb,
        p_AN_THUC_NAM            => v_an_n,
        p_AN_THUC_THANG          => v_an_t,
        p_AN_THUC_NGAY           => v_an_g,
        p_DA_CHAP_HANH_NAM       => v_da_n,
        p_DA_CHAP_HANH_THANG     => v_da_t,
        p_DA_CHAP_HANH_NGAY      => v_da_g,
        p_NGAY_HET_HAN           => v_nhh,
        p_THOI_GIAN_CON_LAI_NAM   => v_cl_n,
        p_THOI_GIAN_CON_LAI_THANG => v_cl_t,
        p_THOI_GIAN_CON_LAI_NGAY  => v_cl_g,
        p_THONG_BAO              => v_tb
    );

    p_NGAY_HET_HAN := v_nhh;
    p_THONG_BAO    := v_tb;

--==========================================================================================
-- EXCEPTION HANDLER
--========================================================================================--
EXCEPTION WHEN OTHERS THEN
    p_NGAY_HET_HAN := NULL;
    p_THONG_BAO := u'L?i: ' || SQLERRM;
END SP_TINH_NGAY_HET_AN_DEMO_FINAL_TAS;






/
--------------------------------------------------------
--  DDL for Procedure SP_TINH_NGAY_HET_AN_GENERAL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_TINH_NGAY_HET_AN_GENERAL" (
    p_PN_ID                  IN NUMBER    DEFAULT NULL,
