    p_NGAY_YC_TINH           IN NUMBER    DEFAULT NULL,
    p_THA_AN_PHAT_TEXT       IN NVARCHAR2 DEFAULT NULL,
    p_THA_TAM_GIAM_TEXT      IN NVARCHAR2 DEFAULT NULL,
    p_THA_TAM_GIU_TEXT       IN NVARCHAR2 DEFAULT NULL,
    p_THA_O_TRUOC_TEXT       IN NVARCHAR2 DEFAULT NULL,  -- ? tr??c
    p_CHUA_BENH_TEXT         IN NVARCHAR2 DEFAULT NULL,  -- Ch?a b?nh b?t bu?c (tr??c ngày b?t)
    p_THA_GIAM_HP_TEXT       IN NVARCHAR2 DEFAULT NULL,  -- Gi?m hình ph?t
    p_THA_MIEN_HP_TEXT       IN NVARCHAR2 DEFAULT NULL,  -- Mi?n hình ph?t
    p_THA_TANG_HINH_PHAT_TEXT IN NVARCHAR2 DEFAULT NULL, -- T?ng hình ph?t
    p_DUNG_PARAM             IN NUMBER    DEFAULT NULL,
    p_GIAM_AN_TEXT           IN NVARCHAR2 DEFAULT NULL,
    p_TRON_TEXT              IN NVARCHAR2 DEFAULT NULL,
    p_TDC_TEXT               IN NVARCHAR2 DEFAULT NULL,
    p_HOAN_TEXT              IN NVARCHAR2 DEFAULT NULL,
    p_NGAY_BAT_OUT           OUT DATE,
    p_AN_THUC_NAM            OUT NUMBER,
    p_AN_THUC_THANG          OUT NUMBER,
    p_AN_THUC_NGAY           OUT NUMBER,
    p_DA_CHAP_HANH_NAM       OUT NUMBER,
    p_DA_CHAP_HANH_THANG     OUT NUMBER,
    p_DA_CHAP_HANH_NGAY      OUT NUMBER,
    p_NGAY_HET_HAN           OUT DATE,
    p_THOI_GIAN_CON_LAI_NAM   OUT NUMBER,
    p_THOI_GIAN_CON_LAI_THANG OUT NUMBER,
    p_THOI_GIAN_CON_LAI_NGAY  OUT NUMBER,
    p_THONG_BAO              OUT NVARCHAR2,
    -- 1 = b? qua RULE 3 (Tha có ?i?u ki?n ch?a quay l?i) — dùng b?i
    -- PKG_TINH_AN.FN_TINH_THOI_GIAN_THU_THACH ?? tính "gi? s? KHÔNG ???c THC?K" (ngày h?t án lý
    -- thuy?t t? án ph?t g?c), không ph?i ngày tha th?c t?. M?c ??nh 0: gi? nguyên hành vi c? cho
    -- m?i caller khác (RULE 3 v?n ?úng — PN ?ã tha thì coi nh? h?t ch?p hành k? t? ngày ?ó).
    p_BO_QUA_TCDK             IN  NUMBER DEFAULT 0,
    -- 1 = b? qua B??C 1 (short-circuit theo PN_KET_THUC_RA_TRAIS.KTRT_NGAY_THA — ngày ra tr?i
    -- th?c t?, tr??ng nh?p tay, có th? l?ch THA_CO_DIEU_KIENS.NGAY_THA) — dùng b?i
    -- PKG_TINH_AN.FN_TINH_THOI_GIAN_THU_THACH cùng lúc v?i p_BO_QUA_TCDK, vì c? 2 rule ??u ph?i
    -- b? b? qua ?? tính l?i "gi? s? KHÔNG ???c THC?K" hoàn toàn t? án ph?t g?c thay vì l?y m?t
    -- ngày ra tr?i ?ã b? ghi ?è/s?a tay. M?c ??nh 0: gi? nguyên hành vi c? (?u tiên KTRT_NGAY_THA
    -- n?u có) cho các caller khác c?a SP này.
    p_BO_QUA_KTRT             IN  NUMBER DEFAULT 0
)
IS
    --====================================================================================
    -- KHAI BÁO BI?N
    --====================================================================================
    v_NGAY_BAT      NUMBER;
    v_NGAY_YC_TINH  NUMBER;
    v_MOC_112       NUMBER;

    v_AN_PHAT_NAM   NUMBER := 0;
    v_AN_PHAT_THANG NUMBER := 0;
    v_AN_PHAT_NGAY  NUMBER := 0;

    -- GI?M án (TR??C ngày b?t): t?m giam, t?m gi?, ? tr??c, ch?a b?nh b?t bu?c
    v_NAM_TAM_GIAM    NUMBER := 0;   v_THANG_TAM_GIAM  NUMBER := 0;   v_NGAY_TAM_GIAM  NUMBER := 0;
    v_NAM_TAM_GIU     NUMBER := 0;   v_THANG_TAM_GIU   NUMBER := 0;   v_NGAY_TAM_GIU   NUMBER := 0;
    v_NAM_O_TRUOC     NUMBER := 0;   v_THANG_O_TRUOC   NUMBER := 0;   v_NGAY_O_TRUOC   NUMBER := 0;
    v_NAM_CHUA_BENH   NUMBER := 0;   v_THANG_CHUA_BENH NUMBER := 0;   v_NGAY_CHUA_BENH NUMBER := 0;

    -- GI?M HP: gi?m HP, mi?n HP
    v_NAM_GIAM_HP    NUMBER := 0;   v_THANG_GIAM_HP  NUMBER := 0;   v_NGAY_GIAM_HP  NUMBER := 0;
    v_NAM_MIEN_HP    NUMBER := 0;   v_THANG_MIEN_HP  NUMBER := 0;   v_NGAY_MIEN_HP  NUMBER := 0;
    -- MI?N HP t? DB (MIEN_HINH_PHATS)
    v_MIEN_NAM   NUMBER := 0;   v_MIEN_THANG  NUMBER := 0;   v_MIEN_NGAY  NUMBER := 0;

    v_AN_THUC_NAM   NUMBER := 0;
    v_AN_THUC_THANG NUMBER := 0;
    v_AN_THUC_NGAY  NUMBER := 0;

    -- GI?M án: t? b?ng GIAM_THOI_HANS
    v_TONG_GIAM_NAM   NUMBER := 0;
    v_TONG_GIAM_THANG NUMBER := 0;
    v_TONG_GIAM_NGAY  NUMBER := 0;

    -- T?NG án: tr?n, T?C, hoãn (m?i kho?n là n?m/tháng/ngày quy ??i theo t?ng kho?ng th?t,
    -- không ph?i s? ngày thô — xem B??C 7/11b/12)
    v_TONG_NGAY_TRON  NUMBER := 0;
    v_TONG_TRON_NAM   NUMBER := 0;
    v_TONG_TRON_THANG NUMBER := 0;
    v_TONG_NGAY_TDC   NUMBER := 0;
    v_TONG_TDC_NAM    NUMBER := 0;
    v_TONG_TDC_THANG  NUMBER := 0;
    v_TONG_NGAY_HOAN  NUMBER := 0;
    v_TONG_HOAN_NAM   NUMBER := 0;
    v_TONG_HOAN_THANG NUMBER := 0;

    -- Ch?a b?nh b?t bu?c (DB, n?u có PN_ID)
    v_TONG_NGAY_CHUA_BENH NUMBER := 0;

    -- T?NG HP: t?ng hình ph?t
    v_TANG_NAM   NUMBER := 0;   v_TANG_THANG  NUMBER := 0;   v_TANG_NGAY  NUMBER := 0;

    v_AN_PHAT_TEXT            NVARCHAR2(500);
    v_THOI_GIAN_TAM_GIAM_TEXT NVARCHAR2(500);
    v_THOI_GIAN_TAM_GIU_TEXT  NVARCHAR2(500);
    v_THOI_GIAN_O_TRUOC_TEXT  NVARCHAR2(500);
    v_CHUA_BENH_TEXT          NVARCHAR2(500);
    v_GIAM_HP_TEXT            NVARCHAR2(500);
    v_MIEN_HP_TEXT            NVARCHAR2(500);
    v_TANG_HINH_PHAT_TEXT     NVARCHAR2(500);
    v_GIAM_AN_TEXT            NVARCHAR2(500);
    v_TRON_TEXT_DB            NVARCHAR2(200);
    v_TDC_TEXT_DB             NVARCHAR2(200);
    v_HOAN_TEXT_DB            NVARCHAR2(200);
    v_CHUA_BENH_TEXT_DB       NVARCHAR2(200);

    v_NGAY_AN_THUC_112   NUMBER;

    v_CHUNG_THAN         BOOLEAN := FALSE;
    v_TU_HINH            BOOLEAN := FALSE;
    v_DATA_FOUND         BOOLEAN := FALSE;
    v_IS_CHUNG_THAN_GIAM BOOLEAN := FALSE;

    v_NGAY_THA     DATE;
    v_NGAY_THA_112 NUMBER;
    -- Ngày tha THA CÓ ?I?U KI?N g?n nh?t c?a PN (n?u có) — dùng ? B??C 1 ?? KHÔNG tin
    -- PN_KET_THUC_RA_TRAIS.KTRT_NGAY_THA làm ngày h?t án lý thuy?t khi nó th?c ra là ngày tha
    -- s?m do THC?K (cùng nguyên nhân/kh?c ph?c v?i PKG_TINH_AN.get_ngay_het_via_general —
    -- SP này b? g?i l?i t? ?ó v?i p_PN_ID th?t nên v?n dính bug dù caller ?ã c? bypass).
    v_THCDK_NGAY_THA DATE;
    v_TEMP_YEAR       NUMBER; v_TEMP_MONTH     NUMBER; v_TEMP_DAY     NUMBER;
    v_CURR_MONTH_DAYS NUMBER; v_PREV_MONTH_DAYS NUMBER;

    v_DA_CHAP_NAM   NUMBER := 0;
    v_DA_CHAP_THANG NUMBER := 0;
    v_DA_CHAP_NGAY  NUMBER := 0;

    v_CON_LAI_NAM   NUMBER := 0;
    v_CON_LAI_THANG NUMBER := 0;
    v_CON_LAI_NGAY  NUMBER := 0;

    -- RULE 1-7 (mirror SP_TINH_NGAY_HET_AN_DEMO_FINAL) — ch? dùng khi p_PN_ID IS NOT NULL
    v_NGAY_YC_TINH_DATE      DATE;
    v_NGAY_THA_GIAM_HET_AN   DATE;   -- rule 1
    v_DX_NGAY_THA            DATE;   -- rule 2
    v_TCDK_NGAY_THA          DATE;   -- rule 3
    v_HUY_NGAY_TRA_TU_DO     DATE;   -- rule 4
    v_MIEN_HET_AN_NGAY_TU_DO DATE;   -- rule 5
    v_MIEN_HET_AN_FLAG       BOOLEAN := FALSE;
    v_CNT_TRON_MO  NUMBER := 0;      -- rule 6
    v_CNT_TDC_MO   NUMBER := 0;
    v_CNT_HOAN_MO  NUMBER := 0;
    v_TONG_NGAY_THA_DK NUMBER := 0;  -- rule 7

    --====================================================================================
    -- HÀM: FN_SO_NGAY_TRONG_THANG — s? ngày TH?C c?a 1 tháng/n?m (l?ch d??ng, có xét n?m
    -- nhu?n). KHÔNG tra DIM_DATETIME: các c?t DATE c?a b?ng này l?ch 100/200 n?m t? n?m 2046
    -- tr? ?i (vd YEAR_ID 2046 nh?ng DATETIME = 1946).
    --====================================================================================
    FUNCTION FN_SO_NGAY_TRONG_THANG(p_nam IN NUMBER, p_thang IN NUMBER) RETURN NUMBER IS
    BEGIN
        RETURN EXTRACT(DAY FROM LAST_DAY(
            TO_DATE(LPAD(TO_CHAR(p_nam), 4, '0') || LPAD(TO_CHAR(p_thang), 2, '0') || '01', 'YYYYMMDD')));
    END FN_SO_NGAY_TRONG_THANG;

    --====================================================================================
    -- HÀM: SPLIT_DATE_112 (tách tr?c ti?p t? s? YYYYMMDD, không tra DIM_DATETIME)
    --====================================================================================
    PROCEDURE SPLIT_DATE_112(p_date_112 IN NUMBER) IS
    BEGIN
        IF p_date_112 IS NULL THEN RETURN; END IF;
        v_TEMP_YEAR  := TRUNC(p_date_112 / 10000);
        v_TEMP_MONTH := MOD(TRUNC(p_date_112 / 100), 100);
        v_TEMP_DAY   := MOD(p_date_112, 100);
    END SPLIT_DATE_112;

    --====================================================================================
    -- HÀM: CALC_DA_CHAP_HANH
    --====================================================================================
    PROCEDURE CALC_DA_CHAP_HANH(p_from_112 IN NUMBER, p_to_112 IN NUMBER) IS
        v_fy NUMBER; v_fm NUMBER; v_fd NUMBER;
        v_ty NUMBER; v_tm NUMBER; v_td NUMBER;
    BEGIN
        -- Tách tr?c ti?p t? s? YYYYMMDD (không tra DIM_DATETIME)
        v_fy := TRUNC(p_from_112 / 10000); v_fm := MOD(TRUNC(p_from_112 / 100), 100); v_fd := MOD(p_from_112, 100);
        v_ty := TRUNC(p_to_112   / 10000); v_tm := MOD(TRUNC(p_to_112   / 100), 100); v_td := MOD(p_to_112,   100);

        v_DA_CHAP_NAM   := v_ty - v_fy;
        v_DA_CHAP_THANG := v_tm - v_fm;
        v_DA_CHAP_NGAY  := v_td - v_fd;

        IF v_DA_CHAP_NGAY < 0 THEN
            v_TEMP_MONTH := v_tm - 1;
            v_TEMP_YEAR  := v_ty;
            IF v_TEMP_MONTH <= 0 THEN v_TEMP_MONTH := 12; v_TEMP_YEAR := v_TEMP_YEAR - 1; END IF;
            v_PREV_MONTH_DAYS := FN_SO_NGAY_TRONG_THANG(v_TEMP_YEAR, v_TEMP_MONTH);
            v_DA_CHAP_NGAY  := v_DA_CHAP_NGAY  + v_PREV_MONTH_DAYS;
            v_DA_CHAP_THANG := v_DA_CHAP_THANG - 1;
        END IF;

        IF v_DA_CHAP_THANG < 0 THEN
            v_DA_CHAP_THANG := v_DA_CHAP_THANG + 12;
            v_DA_CHAP_NAM   := v_DA_CHAP_NAM   - 1;
        END IF;
    END CALC_DA_CHAP_HANH;

    --====================================================================================
    -- HÀM: PARSE_AN_PHAT
    --====================================================================================
    PROCEDURE PARSE_AN_PHAT(p_text IN NVARCHAR2) IS
    BEGIN
        IF p_text IS NULL THEN RETURN; END IF;
        IF INSTR(UPPER(p_text), 'CHUNG') > 0 AND INSTR(p_text, '30') > 0 THEN
            v_AN_PHAT_NAM := 30; v_IS_CHUNG_THAN_GIAM := TRUE;
        ELSIF INSTR(UPPER(p_text), 'CHUNG') > 0 AND INSTR(p_text, '20') > 0 THEN
            v_AN_PHAT_NAM := 20; v_IS_CHUNG_THAN_GIAM := TRUE;
        ELSIF INSTR(UPPER(p_text), 'CHUNG') > 0 THEN
            v_CHUNG_THAN := TRUE; RETURN;
        ELSIF REGEXP_LIKE(UPPER(p_text), 'T.{1,3}H.NH') THEN
            v_TU_HINH := TRUE; RETURN;
        END IF;
        IF NOT v_IS_CHUNG_THAN_GIAM THEN
            v_AN_PHAT_NAM   := NVL(FN_PARSE_THOI_GIAN_TEXT(p_text, 'NAM'),   0);
            v_AN_PHAT_THANG := NVL(FN_PARSE_THOI_GIAN_TEXT(p_text, 'THANG'), 0);
            v_AN_PHAT_NGAY  := NVL(FN_PARSE_THOI_GIAN_TEXT(p_text, 'NGAY'),  0);
        END IF;
    END PARSE_AN_PHAT;

    --====================================================================================
    -- HÀM: PARSE_YMD
    --====================================================================================
    PROCEDURE PARSE_YMD(p_text IN NVARCHAR2, p_nam OUT NUMBER, p_thang OUT NUMBER, p_ngay OUT NUMBER) IS
    BEGIN
        IF p_text IS NULL THEN p_nam := 0; p_thang := 0; p_ngay := 0; RETURN; END IF;
        p_nam   := NVL(FN_PARSE_THOI_GIAN_TEXT(p_text, 'NAM'),   0);
        p_thang := NVL(FN_PARSE_THOI_GIAN_TEXT(p_text, 'THANG'), 0);
        p_ngay  := NVL(FN_PARSE_THOI_GIAN_TEXT(p_text, 'NGAY'),  0);
    END PARSE_YMD;

    --====================================================================================
    -- HÀM: FN_CONG_YMD_VAO_NGAY (port t? SP_TINH_NGAY_HET_AN_DEMO_FINAL, thay ADD_DURATION_LEGAL)
    --     C?ng (nam,thang,ngay) vào m?t ngày m?c (DATE), tr? v? ngày k?t qu?.
    --
    --     RULE A — n?u ngày m?c b?t ??u là ngày CU?I THÁNG c?a chính tháng nó: sau khi c?ng
    --     n?m/tháng, n?u ngày ?ích không t?n t?i th?t trong tháng ?ích NH?NG v?n ?31 (t?c
    --     ch? tràn 1 tháng, không ph?i nhi?u tháng) thì CH?T v? ngày cu?i cùng th?c t? c?a
    --     tháng ?ích, KHÔNG tràn sang tháng k? ti?p.
    --
    --     RULE B — n?u ngày m?c b?t ??u KHÔNG ph?i cu?i tháng, HO?C ngày ?ích tính ra > 31
    --     (tràn nhi?u h?n 1 tháng): TRÀN sang tháng k? ti?p theo ?úng l?ch d??ng th?c t?,
    --     l?p l?i n?u c?n cho ??n khi ra ngày h?p l?.
    --
    --     Ngày âm/b?ng 0 (do c?ng s? âm — tr??ng h?p ?i?u ch?nh gi?m) s? lùi qua các tháng
    --     tr??c ?ó, dùng ?úng s? ngày TH?C c?a t?ng tháng lùi qua.
    --====================================================================================
    FUNCTION FN_CONG_YMD_VAO_NGAY(
        p_ngay_bat IN DATE,
        p_nam      IN NUMBER,
        p_thang    IN NUMBER,
        p_ngay     IN NUMBER
    ) RETURN DATE IS
        v_bat_nam            NUMBER := EXTRACT(YEAR  FROM p_ngay_bat);
        v_bat_thang          NUMBER := EXTRACT(MONTH FROM p_ngay_bat);
        v_bat_ngay           NUMBER := EXTRACT(DAY   FROM p_ngay_bat);
        v_bat_so_ngay_thang  NUMBER;
        v_la_cuoi_thang      BOOLEAN;

        v_dich_nam           NUMBER;
        v_dich_thang         NUMBER;
        v_dich_ngay          NUMBER;
        v_so_ngay_thang_dich NUMBER;

        v_ap_dung_chot_cuoi_thang BOOLEAN;

        v_dau_thang_dich DATE;
        v_ket_qua DATE;
    BEGIN
        v_bat_so_ngay_thang := FN_SO_NGAY_TRONG_THANG(v_bat_nam, v_bat_thang);
        v_la_cuoi_thang     := (v_bat_ngay = v_bat_so_ngay_thang);

        v_dich_nam   := v_bat_nam   + NVL(p_nam,0);
        v_dich_thang := v_bat_thang + NVL(p_thang,0);
        v_dich_ngay  := v_bat_ngay  + NVL(p_ngay,0);

        WHILE v_dich_thang > 12 LOOP v_dich_thang := v_dich_thang - 12; v_dich_nam := v_dich_nam + 1; END LOOP;
        WHILE v_dich_thang < 1  LOOP v_dich_thang := v_dich_thang + 12; v_dich_nam := v_dich_nam - 1; END LOOP;

        IF v_dich_ngay <= 0 THEN
            WHILE v_dich_ngay <= 0 LOOP
                v_dich_thang := v_dich_thang - 1;
                IF v_dich_thang < 1 THEN
                    v_dich_thang := 12;
                    v_dich_nam   := v_dich_nam - 1;
                END IF;
                v_dich_ngay := v_dich_ngay + FN_SO_NGAY_TRONG_THANG(v_dich_nam, v_dich_thang);
            END LOOP;
        ELSE
            v_so_ngay_thang_dich := FN_SO_NGAY_TRONG_THANG(v_dich_nam, v_dich_thang);

            IF v_dich_ngay > v_so_ngay_thang_dich THEN

                v_ap_dung_chot_cuoi_thang := (v_la_cuoi_thang AND v_dich_ngay <= 31);

                IF v_ap_dung_chot_cuoi_thang THEN
                    -- RULE A: ngày b?t là cu?i tháng -> ch?t v? cu?i tháng ?ích
                    v_dich_ngay := v_so_ngay_thang_dich;
                ELSE
                    -- RULE B: tr??t theo ?úng l?ch v?n niên
                    WHILE v_dich_ngay > v_so_ngay_thang_dich LOOP
                        v_dich_ngay  := v_dich_ngay - v_so_ngay_thang_dich;
                        v_dich_thang := v_dich_thang + 1;
                        IF v_dich_thang > 12 THEN
                            v_dich_thang := 1;
                            v_dich_nam   := v_dich_nam + 1;
                        END IF;
                        v_so_ngay_thang_dich := FN_SO_NGAY_TRONG_THANG(v_dich_nam, v_dich_thang);
                    END LOOP;
                END IF;

            END IF;
        END IF;

        -- B??C CU?I: d?ng ngày tr?c ti?p t? (n?m, tháng, ngày) v?a tính. KHÔNG l?y c?t
        -- DATETIME / END_OF_MONTH c?a DIM_DATETIME vì d? li?u b?ng này l?ch t? n?m 2046 tr? ?i
        -- (2046 -> 1946), làm ngày ra 19xx ho?c l?i ORA-01403. Ngày v??t quá s? ngày c?a tháng
        -- ?ích (tr??ng h?p biên) -> ch?t v? ngày cu?i tháng, không ?? l?t ORA-01839.
        v_dau_thang_dich := TO_DATE(LPAD(TO_CHAR(v_dich_nam), 4, '0') || LPAD(TO_CHAR(v_dich_thang), 2, '0') || '01', 'YYYYMMDD');
        v_ket_qua        := LEAST(v_dau_thang_dich + v_dich_ngay - 1, LAST_DAY(v_dau_thang_dich));

        RETURN v_ket_qua;
    END FN_CONG_YMD_VAO_NGAY;

    --====================================================================================
    -- HÀM: DAYS_TO_TEXT - convert so ngay ? text "X ngay"
    --====================================================================================
    FUNCTION DAYS_TO_TEXT(p_days IN NUMBER) RETURN NVARCHAR2 IS
    BEGIN
        IF p_days IS NULL OR p_days <= 0 THEN RETURN NULL; END IF;
        RETURN p_days || ' ngay';
    END DAYS_TO_TEXT;

    --====================================================================================
    -- HÀM: NORMALIZE_YMD - chu?n hóa (nam,thang,ngay) v? d?ng canonical
    --      theo quy ??c 30 ngày = 1 tháng, 12 tháng = 1 n?m (m??n/mang 2 chi?u)
    --====================================================================================
    PROCEDURE NORMALIZE_YMD(p_nam IN OUT NUMBER, p_thang IN OUT NUMBER, p_ngay IN OUT NUMBER) IS
    BEGIN
        WHILE p_ngay < 0 LOOP
            p_ngay  := p_ngay + 30;
            p_thang := p_thang - 1;
        END LOOP;
        WHILE p_ngay >= 30 LOOP
            p_ngay  := p_ngay - 30;
            p_thang := p_thang + 1;
        END LOOP;
        WHILE p_thang < 0 LOOP
            p_thang := p_thang + 12;
            p_nam   := p_nam - 1;
        END LOOP;
        WHILE p_thang >= 12 LOOP
            p_thang := p_thang - 12;
            p_nam   := p_nam + 1;
        END LOOP;
    END NORMALIZE_YMD;

    --====================================================================================
    -- HÀM: TINH_DA_CHAP_HANH — th?i gian ?Ã CH?P HÀNH tính t?i m?c p_moc_112 (công th?c B??C 12):
    --     DA = GREATEST(0, (m?c ? ngày b?t) ? T?C ? Hoãn ? Tr?n ? Tha ?K ?ã quay l?i)
    --          + T?m giam + T?m gi? + ? tr??c + Ch?a b?nh b?t bu?c
    --     K?t qu? ghi vào v_DA_CHAP_NAM / v_DA_CHAP_THANG / v_DA_CHAP_NGAY.
    --     Dùng chung cho B??C 12 và nhánh CHUNG THÂN (B??C 9: không có ngày h?t h?n nh?ng v?n
    --     ph?i hi?n th? ?ã ch?p hành).
    --====================================================================================
    PROCEDURE TINH_DA_CHAP_HANH(p_moc_112 IN NUMBER) IS
        v_sub_nam   NUMBER := v_TONG_TDC_NAM   + v_TONG_HOAN_NAM   + v_TONG_TRON_NAM;
        v_sub_thang NUMBER := v_TONG_TDC_THANG + v_TONG_HOAN_THANG + v_TONG_TRON_THANG;
        v_sub_ngay  NUMBER := v_TONG_NGAY_TDC  + v_TONG_NGAY_HOAN  + v_TONG_NGAY_TRON + v_TONG_NGAY_THA_DK;
    BEGIN
        IF p_moc_112 <= v_NGAY_BAT THEN
            v_DA_CHAP_NAM := 0; v_DA_CHAP_THANG := 0; v_DA_CHAP_NGAY := 0;
        ELSE
            CALC_DA_CHAP_HANH(v_NGAY_BAT, p_moc_112);
        END IF;

        NORMALIZE_YMD(v_sub_nam, v_sub_thang, v_sub_ngay);
        v_DA_CHAP_NAM   := v_DA_CHAP_NAM   - v_sub_nam;
        v_DA_CHAP_THANG := v_DA_CHAP_THANG - v_sub_thang;
        v_DA_CHAP_NGAY  := v_DA_CHAP_NGAY  - v_sub_ngay;
        NORMALIZE_YMD(v_DA_CHAP_NAM, v_DA_CHAP_THANG, v_DA_CHAP_NGAY);

        IF (v_DA_CHAP_NAM * 360 + v_DA_CHAP_THANG * 30 + v_DA_CHAP_NGAY) < 0 THEN
            v_DA_CHAP_NAM := 0; v_DA_CHAP_THANG := 0; v_DA_CHAP_NGAY := 0;
        END IF;

        v_DA_CHAP_NAM   := v_DA_CHAP_NAM   + v_NAM_TAM_GIAM   + v_NAM_TAM_GIU   + v_NAM_O_TRUOC   + v_NAM_CHUA_BENH;
        v_DA_CHAP_THANG := v_DA_CHAP_THANG + v_THANG_TAM_GIAM + v_THANG_TAM_GIU + v_THANG_O_TRUOC + v_THANG_CHUA_BENH;
        v_DA_CHAP_NGAY  := v_DA_CHAP_NGAY  + v_NGAY_TAM_GIAM  + v_NGAY_TAM_GIU  + v_NGAY_O_TRUOC  + v_NGAY_CHUA_BENH;
        NORMALIZE_YMD(v_DA_CHAP_NAM, v_DA_CHAP_THANG, v_DA_CHAP_NGAY);

        v_DA_CHAP_NAM   := GREATEST(v_DA_CHAP_NAM,   0);
        v_DA_CHAP_THANG := GREATEST(v_DA_CHAP_THANG, 0);
        v_DA_CHAP_NGAY  := GREATEST(v_DA_CHAP_NGAY,  0);
    END TINH_DA_CHAP_HANH;

--==========================================================================================
-- THÂN CH??NG TRÌNH CHÍNH
--==========================================================================================
BEGIN
    --====================================================================================
    -- B??C 0: Kh?i t?o giá tr? m?c ??nh cho OUTPUT
    --====================================================================================
    p_AN_THUC_NAM := 0; p_AN_THUC_THANG := 0; p_AN_THUC_NGAY := 0;
    p_DA_CHAP_HANH_NAM := 0; p_DA_CHAP_HANH_THANG := 0; p_DA_CHAP_HANH_NGAY := 0;
    p_THOI_GIAN_CON_LAI_NAM := 0; p_THOI_GIAN_CON_LAI_THANG := 0; p_THOI_GIAN_CON_LAI_NGAY := 0;
    p_NGAY_BAT_OUT := NULL; p_NGAY_HET_HAN := NULL; p_THONG_BAO := '';

    --====================================================================================
    -- B??C 1: Ki?m tra ?ã ???c TH? ch?a (t? PN_KET_THUC_RA_TRAIS)
    --====================================================================================
    IF p_PN_ID IS NOT NULL AND NVL(p_BO_QUA_KTRT, 0) != 1 THEN
        BEGIN
            BEGIN
                SELECT TRUNC(NGAY_THA)
                  INTO v_THCDK_NGAY_THA
                  FROM THA_CO_DIEU_KIENS
                 WHERE PHAM_NHAN_ID = p_PN_ID
                   AND NVL(IS_DELETED, 0) = 0
                   AND NGAY_THA IS NOT NULL
                 ORDER BY CREATION_TIME DESC
                 FETCH FIRST 1 ROW ONLY;
            EXCEPTION WHEN NO_DATA_FOUND THEN v_THCDK_NGAY_THA := NULL; END;

            SELECT KTRT_NGAY_THA INTO v_NGAY_THA
              FROM PN_KET_THUC_RA_TRAIS
             WHERE KTRT_PN_LAI_LICH_ID = p_PN_ID
               AND IS_DELETED = 0
               AND KTRT_NGAY_THA IS NOT NULL
               AND (v_THCDK_NGAY_THA IS NULL OR TRUNC(KTRT_NGAY_THA) != v_THCDK_NGAY_THA)
             ORDER BY CREATION_TIME DESC
             FETCH FIRST 1 ROW ONLY;

            IF v_NGAY_THA IS NOT NULL THEN
                v_NGAY_THA_112 := TO_NUMBER(TO_CHAR(v_NGAY_THA, 'YYYYMMDD'));
                BEGIN
                    SELECT TO_NUMBER(TO_CHAR(THA_NGAY_BAT, 'YYYYMMDD'))
                      INTO v_NGAY_BAT FROM PN_THI_HANH_AN
                     WHERE THA_PNLAI_LICH_ID = p_PN_ID AND ROWNUM = 1;
                EXCEPTION WHEN NO_DATA_FOUND THEN v_NGAY_BAT := NULL; END;
                p_NGAY_BAT_OUT := TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');
                p_NGAY_HET_HAN := v_NGAY_THA;
                IF v_NGAY_BAT IS NOT NULL THEN
                    CALC_DA_CHAP_HANH(v_NGAY_BAT, v_NGAY_THA_112);
                    p_DA_CHAP_HANH_NAM := v_DA_CHAP_NAM;
                    p_DA_CHAP_HANH_THANG := v_DA_CHAP_THANG;
                    p_DA_CHAP_HANH_NGAY := v_DA_CHAP_NGAY;
                END IF;
                p_AN_THUC_NAM := p_DA_CHAP_HANH_NAM;
                p_AN_THUC_THANG := p_DA_CHAP_HANH_THANG;
                p_AN_THUC_NGAY := p_DA_CHAP_HANH_NGAY;
                p_THONG_BAO := u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c tha v\00e0o ng\00e0y '
                    || TO_CHAR(v_NGAY_THA, 'DD/MM/YYYY') || u'. '
                    || u'\0110\00e3 ch\1ea5p h\00e0nh: '
                    || p_DA_CHAP_HANH_NAM || u' n\0103m, '
                    || p_DA_CHAP_HANH_THANG || u' th\00e1ng, '
                    || p_DA_CHAP_HANH_NGAY || u' ng\00e0y.';
                RETURN;
            END IF;
        EXCEPTION WHEN NO_DATA_FOUND THEN NULL; END;
    END IF;

    --====================================================================================
    -- B??C 1b (RULE 1-7, mirror SP_TINH_NGAY_HET_AN_DEMO_FINAL): CÁC TR?NG THÁI ??C BI?T,
    -- ch? áp d?ng khi có p_PN_ID. Khác DEMO_FINAL: m?i rule (k? c? ?i?u ki?n "m?" c?a rule 6
    -- và b?n ghi c?ng thêm c?a rule 7) ???c so thêm m?c <= p_NGAY_YC_TINH — DEMO_FINAL không
    -- có khái ni?m m?c ?ánh giá (b? qua p_NGAY_YC_TINH hoàn toàn) nh?ng GENERAL h? tr? tính
    -- "t?i 1 m?c l?ch s?" (dùng cho snapshot batch DX_CORE_MEMO/TCDK_CORE_MEMO qua
    -- PKG_TINH_AN), nên không ???c ?? s? ki?n ? T??NG LAI so v?i m?c ?ang xét làm sai k?t
    -- qu? c?a 1 truy v?n l?ch s?.
    -- Th? t? ?u tiên: gi?m h?t án -> ??c xá -> tha có ?K (ch?a quay l?i) -> h?y án -> mi?n
    -- h?t án 92300 -> ch?n n?u còn b?n ghi m?. Rule 7 (THA ?K ?ã quay l?i) không early-return,
    -- ch? gom s? ngày c?ng thêm dùng ? B??C 11b.
    --====================================================================================
    v_NGAY_YC_TINH      := NVL(p_NGAY_YC_TINH, TO_NUMBER(TO_CHAR(SYSDATE, 'YYYYMMDD')));
    v_NGAY_YC_TINH_DATE := TO_DATE(TO_CHAR(v_NGAY_YC_TINH), 'YYYYMMDD');

    IF p_PN_ID IS NOT NULL THEN

        -- N?p tr??c ngày b?t (ch? ?? ph?c v? p_NGAY_BAT_OUT/p_DA_CHAP_HANH_* n?u 1 rule d??i
        -- ?ây return s?m) — B??C 2 phía d??i v?n s? t? n?p/ghi ?è l?i nh? bình th??ng.
        IF v_NGAY_BAT IS NULL THEN
            BEGIN
                SELECT TO_NUMBER(TO_CHAR(THA_NGAY_BAT, 'YYYYMMDD'))
                  INTO v_NGAY_BAT
                  FROM PN_THI_HANH_AN
                 WHERE THA_PNLAI_LICH_ID = p_PN_ID AND ROWNUM = 1;
            EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
            END;
        END IF;

        -- RULE 1: Gi?m h?t án (có ngày c? th? t? GIAM_THOI_HANS)
        BEGIN
            SELECT NGAY_THA_GIAM_HET_AN
              INTO v_NGAY_THA_GIAM_HET_AN
              FROM GIAM_THOI_HANS gth
              JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
             WHERE gth.PHAM_NHAN_ID = p_PN_ID
               AND NVL(gth.IS_DELETED, 0) = 0
               AND gth.NGAY_THA_GIAM_HET_AN IS NOT NULL
               AND gth.NGAY_THA_GIAM_HET_AN <= v_NGAY_YC_TINH_DATE
               AND dmtg.MTG_MA NOT IN ('921000', '922000')
               AND ROWNUM = 1
             ORDER BY NGAY_XET;
        EXCEPTION WHEN NO_DATA_FOUND THEN v_NGAY_THA_GIAM_HET_AN := NULL;
        END;

        IF v_NGAY_THA_GIAM_HET_AN IS NULL THEN
            BEGIN
                SELECT gth.NGAY_QUYET_DINH
                  INTO v_NGAY_THA_GIAM_HET_AN
                  FROM GIAM_THOI_HANS gth
                  JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
                 WHERE gth.PHAM_NHAN_ID = p_PN_ID
                   AND NVL(gth.IS_DELETED, 0) = 0
                   AND dmtg.MTG_MA = '923000'
                   AND gth.NGAY_QUYET_DINH IS NOT NULL
                   AND gth.NGAY_QUYET_DINH <= v_NGAY_YC_TINH_DATE
                   AND ROWNUM = 1;
            EXCEPTION WHEN NO_DATA_FOUND THEN v_NGAY_THA_GIAM_HET_AN := NULL;
            END;
        END IF;

        IF v_NGAY_THA_GIAM_HET_AN IS NOT NULL THEN
            p_NGAY_BAT_OUT := TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');
            p_NGAY_HET_HAN := v_NGAY_THA_GIAM_HET_AN;
            p_AN_THUC_NAM := 0; p_AN_THUC_THANG := 0; p_AN_THUC_NGAY := 0;
            p_THOI_GIAN_CON_LAI_NAM := 0; p_THOI_GIAN_CON_LAI_THANG := 0; p_THOI_GIAN_CON_LAI_NGAY := 0;
            IF v_NGAY_BAT IS NOT NULL THEN
                CALC_DA_CHAP_HANH(v_NGAY_BAT, TO_NUMBER(TO_CHAR(v_NGAY_THA_GIAM_HET_AN, 'YYYYMMDD')));
                p_DA_CHAP_HANH_NAM := v_DA_CHAP_NAM; p_DA_CHAP_HANH_THANG := v_DA_CHAP_THANG; p_DA_CHAP_HANH_NGAY := v_DA_CHAP_NGAY;
            END IF;
            p_THONG_BAO := u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c gi\1ea3m h\1ebft \00e1n v\00e0o ng\00e0y '
                || TO_CHAR(v_NGAY_THA_GIAM_HET_AN, 'DD/MM/YYYY') || u'.';
            RETURN;
        END IF;

        -- RULE 2: ??c xá
        BEGIN
            SELECT DX_NGAY_THA INTO v_DX_NGAY_THA
              FROM PN_DAC_XAS
             WHERE PNLAI_LICH_ID = p_PN_ID
               AND NVL(IS_DELETED, 0) = 0
               AND DX_NGAY_THA IS NOT NULL
               AND DX_NGAY_THA <= v_NGAY_YC_TINH_DATE
             ORDER BY CREATION_TIME DESC
             FETCH FIRST 1 ROW ONLY;
        EXCEPTION WHEN NO_DATA_FOUND THEN v_DX_NGAY_THA := NULL;
        END;

        IF v_DX_NGAY_THA IS NOT NULL THEN
            p_NGAY_BAT_OUT := TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');
            p_NGAY_HET_HAN := v_DX_NGAY_THA;
            p_AN_THUC_NAM := 0; p_AN_THUC_THANG := 0; p_AN_THUC_NGAY := 0;
            p_THOI_GIAN_CON_LAI_NAM := 0; p_THOI_GIAN_CON_LAI_THANG := 0; p_THOI_GIAN_CON_LAI_NGAY := 0;
            IF v_NGAY_BAT IS NOT NULL THEN
                CALC_DA_CHAP_HANH(v_NGAY_BAT, TO_NUMBER(TO_CHAR(v_DX_NGAY_THA, 'YYYYMMDD')));
                p_DA_CHAP_HANH_NAM := v_DA_CHAP_NAM; p_DA_CHAP_HANH_THANG := v_DA_CHAP_THANG; p_DA_CHAP_HANH_NGAY := v_DA_CHAP_NGAY;
            END IF;
            p_THONG_BAO := u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c tha v\00e0o ng\00e0y '
                || TO_CHAR(v_DX_NGAY_THA, 'DD/MM/YYYY') || u'. \0110\01b0\1ee3c \0111\1eb7c x\00e1.';
            RETURN;
        END IF;

        -- RULE 3: Tha có ?i?u ki?n (ch?a quay l?i) — b? qua khi p_BO_QUA_TCDK=1 (tính "gi? s?
        -- KHÔNG ???c THC?K" cho FN_TINH_THOI_GIAN_THU_THACH; xem gi?i thích ? khai báo tham s?).
        IF NVL(p_BO_QUA_TCDK, 0) != 1 THEN
        BEGIN
            SELECT NGAY_THA INTO v_TCDK_NGAY_THA
              FROM THA_CO_DIEU_KIENS
             WHERE PHAM_NHAN_ID = p_PN_ID
               AND NVL(IS_DELETED, 0) = 0
               AND NGAY_THA IS NOT NULL
               AND NGAY_BAT_LAI IS NULL
               AND NGAY_THA <= v_NGAY_YC_TINH_DATE
             ORDER BY CREATION_TIME DESC
             FETCH FIRST 1 ROW ONLY;
        EXCEPTION WHEN NO_DATA_FOUND THEN v_TCDK_NGAY_THA := NULL;
        END;
        END IF;

        IF v_TCDK_NGAY_THA IS NOT NULL THEN
            p_NGAY_BAT_OUT := TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');
            p_NGAY_HET_HAN := v_TCDK_NGAY_THA;
            p_AN_THUC_NAM := 0; p_AN_THUC_THANG := 0; p_AN_THUC_NGAY := 0;
            p_THOI_GIAN_CON_LAI_NAM := 0; p_THOI_GIAN_CON_LAI_THANG := 0; p_THOI_GIAN_CON_LAI_NGAY := 0;
            IF v_NGAY_BAT IS NOT NULL THEN
                CALC_DA_CHAP_HANH(v_NGAY_BAT, TO_NUMBER(TO_CHAR(v_TCDK_NGAY_THA, 'YYYYMMDD')));
                p_DA_CHAP_HANH_NAM := v_DA_CHAP_NAM; p_DA_CHAP_HANH_THANG := v_DA_CHAP_THANG; p_DA_CHAP_HANH_NGAY := v_DA_CHAP_NGAY;
            END IF;
            p_THONG_BAO := u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c tha v\00e0o ng\00e0y '
                || TO_CHAR(v_TCDK_NGAY_THA, 'DD/MM/YYYY') || u'. \0110\01b0\1ee3c tha c\00f3 \0111i\1ec1u ki\1ec7n.';
            RETURN;
        END IF;

        -- RULE 4: H?y án
        BEGIN
            SELECT NGAY_TRA_TU_DO INTO v_HUY_NGAY_TRA_TU_DO
              FROM HUY_ANS
             WHERE PHAM_NHAN_ID = p_PN_ID
               AND NVL(IS_DELETED, 0) = 0
               AND NGAY_TRA_TU_DO IS NOT NULL
               AND NGAY_TRO_LAI IS NULL
               AND NGAY_TRA_TU_DO <= v_NGAY_YC_TINH_DATE
             ORDER BY CREATION_TIME DESC
             FETCH FIRST 1 ROW ONLY;
        EXCEPTION WHEN NO_DATA_FOUND THEN v_HUY_NGAY_TRA_TU_DO := NULL;
        END;

        IF v_HUY_NGAY_TRA_TU_DO IS NOT NULL THEN
            p_NGAY_BAT_OUT := TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');
            p_NGAY_HET_HAN := v_HUY_NGAY_TRA_TU_DO;
            p_AN_THUC_NAM := 0; p_AN_THUC_THANG := 0; p_AN_THUC_NGAY := 0;
            p_THOI_GIAN_CON_LAI_NAM := 0; p_THOI_GIAN_CON_LAI_THANG := 0; p_THOI_GIAN_CON_LAI_NGAY := 0;
            IF v_NGAY_BAT IS NOT NULL THEN
                CALC_DA_CHAP_HANH(v_NGAY_BAT, TO_NUMBER(TO_CHAR(v_HUY_NGAY_TRA_TU_DO, 'YYYYMMDD')));
                p_DA_CHAP_HANH_NAM := v_DA_CHAP_NAM; p_DA_CHAP_HANH_THANG := v_DA_CHAP_THANG; p_DA_CHAP_HANH_NGAY := v_DA_CHAP_NGAY;
            END IF;
            p_THONG_BAO := u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c tha v\00e0o ng\00e0y '
                || TO_CHAR(v_HUY_NGAY_TRA_TU_DO, 'DD/MM/YYYY') || u'. \0110\01b0\1ee3c h\1ee7y \00e1n.';
            RETURN;
        END IF;

        -- RULE 5: Mi?n h?t án (c? ??c bi?t 92300)
        BEGIN
            SELECT MHP_NGAY_TU_DO INTO v_MIEN_HET_AN_NGAY_TU_DO
              FROM MIEN_HINH_PHATS
             WHERE PN_LAI_LICH_ID = p_PN_ID
               AND IS_DELETED = 0
               AND NVL(MHP_THM_YEAR, 0) = 9
               AND NVL(MHP_THM_MONTH, 0) = 23
               AND NVL(MHP_THM_DAY, 0) = 0
               AND MHP_NGAY_TU_DO <= v_NGAY_YC_TINH_DATE
             ORDER BY CREATION_TIME DESC
             FETCH FIRST 1 ROW ONLY;
            v_MIEN_HET_AN_FLAG := TRUE;
        EXCEPTION WHEN NO_DATA_FOUND THEN
            v_MIEN_HET_AN_FLAG := FALSE;
            v_MIEN_HET_AN_NGAY_TU_DO := NULL;
        END;

        IF v_MIEN_HET_AN_FLAG AND v_MIEN_HET_AN_NGAY_TU_DO IS NOT NULL THEN
            p_NGAY_BAT_OUT := TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');
            p_NGAY_HET_HAN := v_MIEN_HET_AN_NGAY_TU_DO;
            p_AN_THUC_NAM := 0; p_AN_THUC_THANG := 0; p_AN_THUC_NGAY := 0;
            p_THOI_GIAN_CON_LAI_NAM := 0; p_THOI_GIAN_CON_LAI_THANG := 0; p_THOI_GIAN_CON_LAI_NGAY := 0;
            IF v_NGAY_BAT IS NOT NULL THEN
                CALC_DA_CHAP_HANH(v_NGAY_BAT, TO_NUMBER(TO_CHAR(v_MIEN_HET_AN_NGAY_TU_DO, 'YYYYMMDD')));
                p_DA_CHAP_HANH_NAM := v_DA_CHAP_NAM; p_DA_CHAP_HANH_THANG := v_DA_CHAP_THANG; p_DA_CHAP_HANH_NGAY := v_DA_CHAP_NGAY;
            END IF;
            p_THONG_BAO := u'Ph\1ea1m nh\00e2n \0111\01b0\1ee3c mi\1ec5n h\1ebft \00e1n (92300). Ng\00e0y t\1ef1 do: '
                || TO_CHAR(v_MIEN_HET_AN_NGAY_TU_DO, 'DD/MM/YYYY');
            RETURN;
        END IF;

        -- RULE 6: Ch?n n?u còn b?n ghi tr?n/T?C/hoãn CH?A k?t thúc, ?ã m? tr??c/t?i m?c xét
        SELECT COUNT(*) INTO v_CNT_TRON_MO
          FROM TRON_TRAIS
         WHERE PHAM_NHAN_ID = p_PN_ID
           AND NVL(IS_DELETED, 0) = 0
           AND NGAY_TRON IS NOT NULL
           AND NGAY_BAT_LAI IS NULL
           AND NGAY_TRON <= v_NGAY_YC_TINH_DATE;

        SELECT COUNT(*) INTO v_CNT_TDC_MO
          FROM TAM_DINH_CHIS
         WHERE PHAM_NHAN_ID = p_PN_ID
           AND NVL(IS_DELETED, 0) = 0
           AND TU_NGAY IS NOT NULL
           AND NGAY_LAI IS NULL
           AND TU_NGAY <= v_NGAY_YC_TINH_DATE;

        SELECT COUNT(*) INTO v_CNT_HOAN_MO
          FROM HOAN_THI_HANH_ANS
         WHERE PHAM_NHAN_ID = p_PN_ID
           AND NVL(IS_DELETED, 0) = 0
           AND NGAY_HOAN IS NOT NULL
           AND NGAY_THI_HANH_AN IS NULL
           AND NGAY_HOAN <= v_NGAY_YC_TINH_DATE;

        IF v_CNT_TRON_MO > 0 OR v_CNT_TDC_MO > 0 OR v_CNT_HOAN_MO > 0 THEN
            p_NGAY_BAT_OUT := TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');
            p_NGAY_HET_HAN := NULL;
            p_THONG_BAO :=
                CASE WHEN v_CNT_TRON_MO > 0
                     THEN u'Ch\01b0a x\00e1c \0111\1ecbnh: c\00f2n ' || v_CNT_TRON_MO || u' l\1ea7n tr\1ed1n ch\01b0a b\1eaft l\1ea1i. ' ELSE '' END ||
                CASE WHEN v_CNT_TDC_MO > 0
                     THEN u'Ch\01b0a x\00e1c \0111\1ecbnh: c\00f2n ' || v_CNT_TDC_MO || u' l\1ea7n T\0110C ch\01b0a quay l\1ea1i. ' ELSE '' END ||
                CASE WHEN v_CNT_HOAN_MO > 0
                     THEN u'Ch\01b0a x\00e1c \0111\1ecbnh: c\00f2n ' || v_CNT_HOAN_MO || u' l\1ea7n ho\00e3n ch\01b0a thi h\00e0nh. ' ELSE '' END;
            RETURN;
        END IF;

        -- RULE 7: Tha có ?i?u ki?n ?Ã quay l?i -> KHÔNG early-return, ch? gom s? ngày t? do
        -- (dùng cùng b??c "c?ng th?ng" v?i tr?n/T?C/hoãn ? B??C 11b)
        FOR rec IN (
            SELECT CAST(tcdk.NGAY_THA AS DATE) AS NGAY_THA, CAST(tcdk.NGAY_BAT_LAI AS DATE) AS NGAY_BAT_LAI
              FROM THA_CO_DIEU_KIENS tcdk
             WHERE tcdk.PHAM_NHAN_ID = p_PN_ID AND NVL(tcdk.IS_DELETED,0) = 0
               AND tcdk.NGAY_THA IS NOT NULL AND tcdk.NGAY_BAT_LAI IS NOT NULL
               AND tcdk.NGAY_BAT_LAI <= v_NGAY_YC_TINH_DATE
        ) LOOP
            DECLARE v_d NUMBER := FLOOR(rec.NGAY_BAT_LAI - rec.NGAY_THA);
            BEGIN IF v_d > 0 THEN v_TONG_NGAY_THA_DK := v_TONG_NGAY_THA_DK + v_d; END IF; END;
        END LOOP;

    END IF;

    --====================================================================================
    -- B??C 2: Load d? li?u t? PN_THI_HANH_AN (n?u có PN_ID)
    --             NVL(param, db_value) - param ?u tiên tr??c, NULL thì l?y DB
    --====================================================================================
    IF p_PN_ID IS NOT NULL AND NVL(p_DUNG_PARAM, 0) <> 1 THEN
        -- Mode A: Không dùng p_DUNG_PARAM ? l?y h?t t? DB
        BEGIN
            SELECT TO_NUMBER(TO_CHAR(THA_NGAY_BAT, 'YYYYMMDD')),
                   THA_AN_PHAT_GOC,
                   THA_THOI_GIAN_TAM_GIAM,
                   THA_THOI_GIAN_TAM_GIU,
                   THA_THOI_GIAN_O_TRUOC
              INTO v_NGAY_BAT,
                   v_AN_PHAT_TEXT,
                   v_THOI_GIAN_TAM_GIAM_TEXT,
                   v_THOI_GIAN_TAM_GIU_TEXT,
                   v_THOI_GIAN_O_TRUOC_TEXT
              FROM PN_THI_HANH_AN
             WHERE THA_PNLAI_LICH_ID = p_PN_ID AND ROWNUM = 1;
            v_DATA_FOUND := TRUE;
        EXCEPTION WHEN NO_DATA_FOUND THEN v_DATA_FOUND := FALSE; END;
    ELSIF p_PN_ID IS NOT NULL AND NVL(p_DUNG_PARAM, 0) = 1 THEN
        -- Mode B: Hybrid - p_DUNG_PARAM=1 + PN_ID
        -- ?u tiên param truy?n vào, NULL thì l?y t? DB
        BEGIN
            SELECT TO_NUMBER(TO_CHAR(THA_NGAY_BAT, 'YYYYMMDD')),
                   NVL(p_THA_AN_PHAT_TEXT,      THA_AN_PHAT_GOC),
                   NVL(p_THA_TAM_GIAM_TEXT,     THA_THOI_GIAN_TAM_GIAM),
                   NVL(p_THA_TAM_GIU_TEXT,      THA_THOI_GIAN_TAM_GIU),
                   NVL(p_THA_O_TRUOC_TEXT,      THA_THOI_GIAN_O_TRUOC)
              INTO v_NGAY_BAT,
                   v_AN_PHAT_TEXT,
                   v_THOI_GIAN_TAM_GIAM_TEXT,
                   v_THOI_GIAN_TAM_GIU_TEXT,
                   v_THOI_GIAN_O_TRUOC_TEXT
              FROM PN_THI_HANH_AN
             WHERE THA_PNLAI_LICH_ID = p_PN_ID AND ROWNUM = 1;
            v_DATA_FOUND := TRUE;
        EXCEPTION WHEN NO_DATA_FOUND THEN v_DATA_FOUND := FALSE; END;
    END IF;

    --====================================================================================
    -- B??C 3: Load d? li?u TRON/TDC/HOAN/CHUA_BENH t? DB (n?u có PN_ID)
    --====================================================================================
    IF p_PN_ID IS NOT NULL THEN
        -- 3a. T?ng ngày TR?N
        SELECT NVL(SUM(FLOOR(CAST(NGAY_BAT_LAI AS DATE) - CAST(NGAY_TRON AS DATE)) + 1), 0)
          INTO v_TONG_NGAY_TRON
          FROM TRON_TRAIS
         WHERE PHAM_NHAN_ID = p_PN_ID
           AND NVL(IS_DELETED, 0) = 0
           AND NGAY_TRON IS NOT NULL
           AND NGAY_BAT_LAI IS NOT NULL;

        -- 3b. T?ng ngày T?C
        SELECT NVL(SUM(TRUNC(NGAY_LAI) - TRUNC(TU_NGAY) + 1), 0)
          INTO v_TONG_NGAY_TDC
          FROM TAM_DINH_CHIS
         WHERE PHAM_NHAN_ID = p_PN_ID
           AND NVL(IS_DELETED, 0) = 0
           AND TU_NGAY IS NOT NULL
           AND NGAY_LAI IS NOT NULL;

        -- 3c. T?ng ngày HOÃN
        SELECT NVL(SUM(FLOOR(CAST(NGAY_THI_HANH_AN AS DATE) - CAST(NGAY_HOAN AS DATE)) + 1), 0)
          INTO v_TONG_NGAY_HOAN
          FROM HOAN_THI_HANH_ANS
         WHERE PHAM_NHAN_ID = p_PN_ID
           AND NVL(IS_DELETED, 0) = 0
           AND NGAY_HOAN IS NOT NULL
           AND NGAY_THI_HANH_AN IS NOT NULL;

        -- 3d. T?ng ngày ch?a b?nh b?t bu?c (?óng, x?y ra TR??C ngày b?t)
        IF v_NGAY_BAT IS NOT NULL THEN
            SELECT NVL(SUM(TRUNC(NGAY_KET_THUC) - TRUNC(NGAY_BAT_DAU) + 1), 0)
              INTO v_TONG_NGAY_CHUA_BENH
              FROM CHUA_BENH_BAT_BUOCS
             WHERE PHAM_NHAN_ID = p_PN_ID
               AND NVL(IS_DELETED, 0) = 0
               AND NGAY_BAT_DAU IS NOT NULL
               AND NGAY_KET_THUC IS NOT NULL
               AND TRUNC(NGAY_KET_THUC) <= TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');
        END IF;
    END IF;

    --====================================================================================
    -- B??C 4: Áp d?ng NVL(param, db_value) cho các tr??ng còn l?i
    --====================================================================================

    -- 4a. NGÀY B?T: NVL(param, db_value)
    IF p_NGAY_BAT IS NOT NULL THEN
        v_NGAY_BAT := TO_NUMBER(TO_CHAR(p_NGAY_BAT, 'YYYYMMDD'));
    END IF;

    -- 4b. TRON_TEXT: NVL(param, db_text)
    v_TRON_TEXT_DB := NVL(p_TRON_TEXT, DAYS_TO_TEXT(v_TONG_NGAY_TRON));

    -- 4c. TDC_TEXT: NVL(param, db_text)
    v_TDC_TEXT_DB := NVL(p_TDC_TEXT, DAYS_TO_TEXT(v_TONG_NGAY_TDC));

    -- 4d. HOAN_TEXT: NVL(param, db_text)
    v_HOAN_TEXT_DB := NVL(p_HOAN_TEXT, DAYS_TO_TEXT(v_TONG_NGAY_HOAN));

    -- 4e. CHUA_BENH_TEXT: NVL(param, db_text)
    v_CHUA_BENH_TEXT_DB := NVL(p_CHUA_BENH_TEXT, DAYS_TO_TEXT(v_TONG_NGAY_CHUA_BENH));

    -- 4f. GIAM_AN_TEXT: param là override
    v_GIAM_AN_TEXT := p_GIAM_AN_TEXT;

    -- 4g. Các tr??ng HP m?i: NVL(param, NULL)
    v_GIAM_HP_TEXT        := p_THA_GIAM_HP_TEXT;
    v_MIEN_HP_TEXT        := p_THA_MIEN_HP_TEXT;
    v_TANG_HINH_PHAT_TEXT := p_THA_TANG_HINH_PHAT_TEXT;

    --====================================================================================
    -- B??C 5: N?u không load ???c t? DB ? dùng params tr?c ti?p
    --====================================================================================
    IF NOT v_DATA_FOUND THEN
        IF p_NGAY_BAT IS NULL AND v_NGAY_BAT IS NULL THEN
            p_THONG_BAO := u'L\1ed7i: p_NGAY_BAT l\00e0 b\1eaft bu\1ed9c khi kh\00f4ng truy\1ec1n PN_ID'; RETURN;
        END IF;
        v_NGAY_BAT := NVL(v_NGAY_BAT, TO_NUMBER(TO_CHAR(p_NGAY_BAT, 'YYYYMMDD')));
        v_AN_PHAT_TEXT            := NVL(p_THA_AN_PHAT_TEXT,   v_AN_PHAT_TEXT);
        v_THOI_GIAN_TAM_GIAM_TEXT := NVL(p_THA_TAM_GIAM_TEXT, v_THOI_GIAN_TAM_GIAM_TEXT);
        v_THOI_GIAN_TAM_GIU_TEXT  := NVL(p_THA_TAM_GIU_TEXT,  v_THOI_GIAN_TAM_GIU_TEXT);
        v_THOI_GIAN_O_TRUOC_TEXT  := NVL(p_THA_O_TRUOC_TEXT, v_THOI_GIAN_O_TRUOC_TEXT);
        v_CHUA_BENH_TEXT          := NVL(p_CHUA_BENH_TEXT,   v_CHUA_BENH_TEXT);
        v_GIAM_AN_TEXT            := p_GIAM_AN_TEXT;
        v_TRON_TEXT_DB            := NVL(p_TRON_TEXT, v_TRON_TEXT_DB);
        v_TDC_TEXT_DB             := NVL(p_TDC_TEXT,  v_TDC_TEXT_DB);
        v_HOAN_TEXT_DB            := NVL(p_HOAN_TEXT, v_HOAN_TEXT_DB);
        v_CHUA_BENH_TEXT_DB       := NVL(p_CHUA_BENH_TEXT, v_CHUA_BENH_TEXT_DB);
        v_GIAM_HP_TEXT            := p_THA_GIAM_HP_TEXT;
        v_MIEN_HP_TEXT            := p_THA_MIEN_HP_TEXT;
        v_TANG_HINH_PHAT_TEXT     := p_THA_TANG_HINH_PHAT_TEXT;
        v_DATA_FOUND := TRUE;
    END IF;

    --====================================================================================
    -- B??C 6: Parse các text thành n?m/tháng/ngày
    --====================================================================================
    PARSE_AN_PHAT(v_AN_PHAT_TEXT);
    PARSE_YMD(v_THOI_GIAN_TAM_GIAM_TEXT, v_NAM_TAM_GIAM,   v_THANG_TAM_GIAM,  v_NGAY_TAM_GIAM);
    PARSE_YMD(v_THOI_GIAN_TAM_GIU_TEXT,  v_NAM_TAM_GIU,   v_THANG_TAM_GIU,   v_NGAY_TAM_GIU);
    PARSE_YMD(v_THOI_GIAN_O_TRUOC_TEXT,  v_NAM_O_TRUOC,   v_THANG_O_TRUOC,   v_NGAY_O_TRUOC);
    PARSE_YMD(v_CHUA_BENH_TEXT_DB,       v_NAM_CHUA_BENH, v_THANG_CHUA_BENH, v_NGAY_CHUA_BENH);
    PARSE_YMD(v_GIAM_HP_TEXT,            v_NAM_GIAM_HP,   v_THANG_GIAM_HP,   v_NGAY_GIAM_HP);
    PARSE_YMD(v_MIEN_HP_TEXT,            v_NAM_MIEN_HP,   v_THANG_MIEN_HP,   v_NGAY_MIEN_HP);
    PARSE_YMD(v_TANG_HINH_PHAT_TEXT,     v_TANG_NAM,      v_TANG_THANG,      v_TANG_NGAY);

    --====================================================================================
    -- B??C 7: C?ng d?n t? text params và DB
    --====================================================================================
    -- GI?M án (t? text)
    v_TONG_GIAM_NAM   := v_TONG_GIAM_NAM   + NVL(FN_PARSE_THOI_GIAN_TEXT(v_GIAM_AN_TEXT, 'NAM'),   0);
    v_TONG_GIAM_THANG := v_TONG_GIAM_THANG + NVL(FN_PARSE_THOI_GIAN_TEXT(v_GIAM_AN_TEXT, 'THANG'), 0);
    v_TONG_GIAM_NGAY  := v_TONG_GIAM_NGAY  + NVL(FN_PARSE_THOI_GIAN_TEXT(v_GIAM_AN_TEXT, 'NGAY'),  0);

    -- T?NG án: tr?n, T?C, hoãn — m?i kho?n ?ã ???c caller (vd get_ngay_het_via_general) quy ??i
    -- ra n?m/tháng/ngày theo t?ng kho?ng th?t, nên parse ?? c? 3 thành ph?n (không ch? NGAY)
    v_TONG_NGAY_TRON  := v_TONG_NGAY_TRON  + NVL(FN_PARSE_THOI_GIAN_TEXT(v_TRON_TEXT_DB, 'NGAY'), 0);
    v_TONG_TRON_NAM   := v_TONG_TRON_NAM   + NVL(FN_PARSE_THOI_GIAN_TEXT(v_TRON_TEXT_DB, 'NAM'),   0);
    v_TONG_TRON_THANG := v_TONG_TRON_THANG + NVL(FN_PARSE_THOI_GIAN_TEXT(v_TRON_TEXT_DB, 'THANG'), 0);
    v_TONG_NGAY_TDC   := v_TONG_NGAY_TDC   + NVL(FN_PARSE_THOI_GIAN_TEXT(v_TDC_TEXT_DB,  'NGAY'), 0);
    v_TONG_TDC_NAM    := v_TONG_TDC_NAM    + NVL(FN_PARSE_THOI_GIAN_TEXT(v_TDC_TEXT_DB,  'NAM'),   0);
    v_TONG_TDC_THANG  := v_TONG_TDC_THANG  + NVL(FN_PARSE_THOI_GIAN_TEXT(v_TDC_TEXT_DB,  'THANG'), 0);
    v_TONG_NGAY_HOAN  := v_TONG_NGAY_HOAN  + NVL(FN_PARSE_THOI_GIAN_TEXT(v_HOAN_TEXT_DB, 'NGAY'),  0);
    v_TONG_HOAN_NAM   := v_TONG_HOAN_NAM   + NVL(FN_PARSE_THOI_GIAN_TEXT(v_HOAN_TEXT_DB, 'NAM'),   0);
    v_TONG_HOAN_THANG := v_TONG_HOAN_THANG + NVL(FN_PARSE_THOI_GIAN_TEXT(v_HOAN_TEXT_DB, 'THANG'), 0);

    --====================================================================================
    -- B??C 9: Ki?m tra d? li?u h?p l? và x? lý tr??ng h?p ??c bi?t
    --====================================================================================
    IF v_NGAY_BAT IS NULL THEN
        p_THONG_BAO := u'L\1ed7i: Ng\00e0y b\1eaft l\00e0 b\1eaft bu\1ed9c'; RETURN;
    END IF;

    IF v_TU_HINH THEN
        p_NGAY_BAT_OUT := TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');
        p_NGAY_HET_HAN := NULL;
        p_THONG_BAO := u'B\1ea3n \00e1n: T\1eed h\00eccnh (v\00f4 th\1eddi h\1ea1n)'; RETURN;
    END IF;

    IF v_CHUNG_THAN THEN
        -- Chung thân (ch?a có quy?t ??nh gi?m xu?ng 30/20 n?m): không có ngày h?t h?n / còn l?i,
        -- nh?ng v?n tính ?Ã CH?P HÀNH t?i m?c xét (cùng công th?c B??C 12, m?c = ngày yêu c?u tính)
        -- — tr??c ?ây RETURN ngay nên ?ã ch?p hành = 0, màn hình hi?n th? "Không".
        TINH_DA_CHAP_HANH(v_NGAY_YC_TINH);
        p_DA_CHAP_HANH_NAM   := v_DA_CHAP_NAM;
        p_DA_CHAP_HANH_THANG := v_DA_CHAP_THANG;
        p_DA_CHAP_HANH_NGAY  := v_DA_CHAP_NGAY;
        p_NGAY_BAT_OUT := TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');
        p_NGAY_HET_HAN := NULL;
        p_THONG_BAO := u'B\1ea3n \00e1n: Chung th\00e2n (v\00f4 th\1eddi h\1ea1n)'; RETURN;
    END IF;

    --====================================================================================
    -- B??C 10: Tính Án th?c = Án ph?t ? T?m giam ? T?m gi? ? ? tr??c ? Ch?a b?nh b?t bu?c
    --     G?P 4 kho?n tr? thành 1 t?ng Y/M/D theo quy ??c pháp lý (m??n 30 ngày = 1 tháng,
    --     12 tháng = 1 n?m, qua NORMALIZE_YMD) — án ph?t/t?m giam/t?m gi?/? tr??c/ch?a b?nh
    --     ??u là th?i h?n v?n b?n (duration-text), không có ngày neo riêng cho t?ng kho?n,
    --     nên tr? tr?c ti?p Y/M/D tr??c. "Án th?c" (Y/M/D) = k?t qu? g?p này, dùng tr?c ti?p
    --     làm giá tr? hi?n th? (p_AN_THUC_NAM/THANG/NGAY) — KHÔNG di?n gi?i l?i t? ngày.
    --     Ch? sau ?ó m?i NEO 1 L?N k?t qu? lên ngày b?t b?ng l?ch th?t (FN_CONG_YMD_VAO_NGAY)
    --     ?? ra ngày k?t thúc án th?c (v_NGAY_AN_THUC_112).
    --     Vd: Án ph?t 2 n?m, T?m giam 9 tháng 23 ngày, ngày b?t 19/12/2025:
    --     Án th?c = (2,0,0) ? (0,9,23) ? m??n 30/12 ? 1 n?m 2 tháng 7 ngày; neo lên
    --     19/12/2025 (+1 n?m 2 tháng = 19/02/2027, +7 ngày th?t) = 26/02/2027.
    --====================================================================================
    v_AN_THUC_NAM   := v_AN_PHAT_NAM   - v_NAM_TAM_GIAM   - v_NAM_TAM_GIU   - v_NAM_O_TRUOC   - v_NAM_CHUA_BENH;
    v_AN_THUC_THANG := v_AN_PHAT_THANG - v_THANG_TAM_GIAM - v_THANG_TAM_GIU - v_THANG_O_TRUOC - v_THANG_CHUA_BENH;
    v_AN_THUC_NGAY  := v_AN_PHAT_NGAY  - v_NGAY_TAM_GIAM  - v_NGAY_TAM_GIU  - v_NGAY_O_TRUOC  - v_NGAY_CHUA_BENH;
    NORMALIZE_YMD(v_AN_THUC_NAM, v_AN_THUC_THANG, v_AN_THUC_NGAY);

    v_NGAY_AN_THUC_112 := TO_NUMBER(TO_CHAR(
        FN_CONG_YMD_VAO_NGAY(TO_DATE(TO_CHAR(v_NGAY_BAT),'YYYYMMDD'), v_AN_THUC_NAM, v_AN_THUC_THANG, v_AN_THUC_NGAY),
        'YYYYMMDD'));

    --====================================================================================
    -- B??C 11: T?m giam/t?m gi?/? tr??c/ch?a b?nh b?t bu?c ?ã ?? bù án ph?t TR??C ngày b?t
    --     (thi hành án) ? ph?m nhân ???c tuyên t? do NGAY T?I TÒA, không vào tr?i ch?p hành.
    --     ?ã ch?p hành = án ph?t g?c (toàn b? án coi nh? ?ã ch?p hành xong qua t?m giam/t?m
    --     gi?/? tr??c/ch?a b?nh); Án th?c (th?i gian còn ph?i ch?p hành trong tr?i) = 0;
    --     Ngày h?t án = ngày b?t (t? do k? t? th?i ?i?m tuyên án, không ph?i m?t ngày trong
    --     t??ng lai ???c suy ra b?ng cách c?ng d?n th?i gian t?m giam t? ngày b?t); Còn l?i = 0.
    --====================================================================================
    -- So sánh ngày tr?c ti?p (chính xác tuy?t ??i) thay vì t?ng quy ??i *360+*30.
    IF v_NGAY_AN_THUC_112 <= v_NGAY_BAT THEN
        p_NGAY_BAT_OUT := TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');
        p_NGAY_HET_HAN := TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');
        p_AN_THUC_NAM := 0; p_AN_THUC_THANG := 0; p_AN_THUC_NGAY := 0;
        p_DA_CHAP_HANH_NAM := v_AN_PHAT_NAM; p_DA_CHAP_HANH_THANG := v_AN_PHAT_THANG; p_DA_CHAP_HANH_NGAY := v_AN_PHAT_NGAY;
        p_THOI_GIAN_CON_LAI_NAM := 0; p_THOI_GIAN_CON_LAI_THANG := 0; p_THOI_GIAN_CON_LAI_NGAY := 0;
        p_THONG_BAO := u'Ph\1ea1m nh\00e2n \0111\00e3 ch\1ea5p h\00e0nh \0111\1ee7 \00e1n qua t\1ea1m giam/t\1ea1m gi\1eef/\1edf tr\01b0\1edbc/ch\1eefa b\1ec7nh b\1eaft bu\1ed9c - \0111\01b0\1ee3c tuy\00ean t\1ef1 do t\1ea1i t\00f2a'; RETURN;
    END IF;

    --====================================================================================
    -- B??C 11b: Tính NGÀY H?T ÁN = ngày k?t thúc án th?c (B??C 10) + ?i?u ch?nh SAU ngày b?t
    --     Theo cách SP_TINH_NGAY_HET_AN_DEMO_FINAL làm (3 b??c neo riêng, KHÔNG g?p chung 1
    --     bucket): bó "?i?u ch?nh" (mi?n/t?ng-gi?m HP/gi?m án) neo TR??C; bó "c?ng th?ng"
    --     (tr?n + T?C + hoãn + tha ?K ?ã quay l?i — RULE 7) neo SAU, tách riêng kh?i bó ?i?u
    --     ch?nh. Khi tr?n/T?C/hoãn ch? có thành ph?n NGAY thu?n (case DB m?c ??nh, không có
    --     override Y/M/D t? PKG_TINH_AN) b??c này suy gi?m ?úng thành "c?ng th?ng N ngày th?t".
    --====================================================================================
    -- B??C 11b-1: bó "?i?u ch?nh" = ? T?ng gi?m án ? Gi?m HP ? Mi?n HP + T?ng HP
    DECLARE
        v_dc_nam   NUMBER := - v_TONG_GIAM_NAM   - v_NAM_GIAM_HP   - v_NAM_MIEN_HP   + v_TANG_NAM;
        v_dc_thang NUMBER := - v_TONG_GIAM_THANG - v_THANG_GIAM_HP - v_THANG_MIEN_HP + v_TANG_THANG;
        v_dc_ngay  NUMBER := - v_TONG_GIAM_NGAY  - v_NGAY_GIAM_HP  - v_NGAY_MIEN_HP  + v_TANG_NGAY;
    BEGIN
        NORMALIZE_YMD(v_dc_nam, v_dc_thang, v_dc_ngay);
        v_NGAY_AN_THUC_112 := TO_NUMBER(TO_CHAR(
            FN_CONG_YMD_VAO_NGAY(TO_DATE(TO_CHAR(v_NGAY_AN_THUC_112),'YYYYMMDD'), v_dc_nam, v_dc_thang, v_dc_ngay),
            'YYYYMMDD'));
    END;

    -- B??C 11b-2: bó "c?ng th?ng" = Tr?n + T?C + Hoãn + Tha ?K ?ã quay l?i (RULE 7) — neo
    -- RIÊNG trên k?t qu? c?a 11b-1, không tr?n chung
    DECLARE
        v_ct_nam   NUMBER := v_TONG_HOAN_NAM   + v_TONG_TDC_NAM   + v_TONG_TRON_NAM;
        v_ct_thang NUMBER := v_TONG_HOAN_THANG + v_TONG_TDC_THANG + v_TONG_TRON_THANG;
        v_ct_ngay  NUMBER := v_TONG_NGAY_TRON + v_TONG_NGAY_TDC + v_TONG_NGAY_HOAN + v_TONG_NGAY_THA_DK;
    BEGIN
        NORMALIZE_YMD(v_ct_nam, v_ct_thang, v_ct_ngay);
        v_NGAY_AN_THUC_112 := TO_NUMBER(TO_CHAR(
            FN_CONG_YMD_VAO_NGAY(TO_DATE(TO_CHAR(v_NGAY_AN_THUC_112),'YYYYMMDD'), v_ct_nam, v_ct_thang, v_ct_ngay),
            'YYYYMMDD'));
    END;

    --====================================================================================
    -- B??C 12: Tính DA = Th?i gian ?ã ch?p hành
    --     m?c = min(ngày YC, ngày h?t án)
    --     diff = (m?c ? ngày b?t) tính TR?C TI?P theo Y/M/D qua CALC_DA_CHAP_HANH (l?ch
    --     th?t — m??n ngày dùng ?úng s? ngày th?t c?a tháng tr??c, m??n tháng = 12).
    --     sub = T?C(?óng) + Hoãn(?óng) + Tr?n(?óng) — m?i kho?n là n?m/tháng/ngày ?ã ???c quy
    --           ??i theo T?NG kho?ng th?t (không ph?i t?ng s? ngày r?i chia 30 — xem B??C 7 và
    --           get_ngay_het_via_general phía caller) — c?ng d?n r?i tr? tr?c ti?p kh?i diff
    --           (sub t? nó v?n c?ng d?n qua NORMALIZE_YMD — m??n 30/12 — vì ?ây là t?ng nhi?u
    --           kho?ng ??c l?p không có 1 ngày neo chung, xem NORMALIZE_YMD).
    --     DA = GREATEST(0, diff ? sub) + T?m giam + T?m gi? + ? tr??c + Ch?a b?nh b?t bu?c
    --====================================================================================
    v_MOC_112 := LEAST(v_NGAY_YC_TINH, v_NGAY_AN_THUC_112);

    TINH_DA_CHAP_HANH(v_MOC_112);

    --====================================================================================
    -- B??C 13: Tính CON_LAI = Án ph?t (g?c) ? ?ã ch?p hành ? Gi?m
    --     Gi?m = T?ng gi?m án + Gi?m HP + Mi?n HP ? T?ng HP
    --====================================================================================
    v_CON_LAI_NAM   := v_AN_PHAT_NAM   - v_DA_CHAP_NAM   - (v_TONG_GIAM_NAM   + v_NAM_GIAM_HP   + v_NAM_MIEN_HP   - v_TANG_NAM);
    v_CON_LAI_THANG := v_AN_PHAT_THANG - v_DA_CHAP_THANG - (v_TONG_GIAM_THANG + v_THANG_GIAM_HP + v_THANG_MIEN_HP - v_TANG_THANG);
    v_CON_LAI_NGAY  := v_AN_PHAT_NGAY  - v_DA_CHAP_NGAY  - (v_TONG_GIAM_NGAY  + v_NGAY_GIAM_HP  + v_NGAY_MIEN_HP  - v_TANG_NGAY);

    NORMALIZE_YMD(v_CON_LAI_NAM, v_CON_LAI_THANG, v_CON_LAI_NGAY);

    IF (v_CON_LAI_NAM * 360 + v_CON_LAI_THANG * 30 + v_CON_LAI_NGAY) < 0 THEN
        v_CON_LAI_NAM := 0; v_CON_LAI_THANG := 0; v_CON_LAI_NGAY := 0;
    END IF;

    --====================================================================================
    -- B??C 15: Gán k?t qu? cho OUTPUT
    --====================================================================================
    p_NGAY_BAT_OUT := TO_DATE(TO_CHAR(v_NGAY_BAT), 'YYYYMMDD');
    p_NGAY_HET_HAN := TO_DATE(TO_CHAR(v_NGAY_AN_THUC_112), 'YYYYMMDD');
    p_AN_THUC_NAM := v_AN_THUC_NAM; p_AN_THUC_THANG := v_AN_THUC_THANG; p_AN_THUC_NGAY := v_AN_THUC_NGAY;
    p_DA_CHAP_HANH_NAM := GREATEST(v_DA_CHAP_NAM, 0);
    p_DA_CHAP_HANH_THANG := GREATEST(v_DA_CHAP_THANG, 0);
    p_DA_CHAP_HANH_NGAY := GREATEST(v_DA_CHAP_NGAY, 0);
    p_THOI_GIAN_CON_LAI_NAM := GREATEST(v_CON_LAI_NAM, 0);
    p_THOI_GIAN_CON_LAI_THANG := GREATEST(v_CON_LAI_THANG, 0);
    p_THOI_GIAN_CON_LAI_NGAY := GREATEST(v_CON_LAI_NGAY, 0);

    --====================================================================================
    -- B??C 16: T?o thông báo
    --====================================================================================
    p_THONG_BAO := u'Ng\00e0y b\1eaft: ' || TO_CHAR(p_NGAY_BAT_OUT, 'DD/MM/YYYY') || u'. '
        || u'\00c1n th\1ef1c: ' || p_AN_THUC_NAM || u' n\0103m, ' || p_AN_THUC_THANG || u' th\00e1ng, ' || p_AN_THUC_NGAY || u' ng\00e0y. '
--        || u'\0110\00e3 ch\1ea5p h\00e0nh: ' || p_DA_CHAP_HANH_NAM || u' n\0103m, ' || p_DA_CHAP_HANH_THANG || u' th\00e1ng, ' || p_DA_CHAP_HANH_NGAY || u' ng\00e0y. '
--        || u'C\00f2n l\1ea1i: ' || p_THOI_GIAN_CON_LAI_NAM || u' n\0103m, ' || p_THOI_GIAN_CON_LAI_THANG || u' th\00e1ng, ' || p_THOI_GIAN_CON_LAI_NGAY || u' ng\00e0y. '
        || u'Ng\00e0y h\1ebft h\1ea1n: ' || TO_CHAR(p_NGAY_HET_HAN, 'DD/MM/YYYY')
        || CASE WHEN v_TONG_GIAM_NAM + v_TONG_GIAM_THANG + v_TONG_GIAM_NGAY > 0
                THEN u'. (Gi\1ea3m TH: ' || v_TONG_GIAM_NAM || u'n ' || v_TONG_GIAM_THANG || u't ' || v_TONG_GIAM_NGAY || u'ng)' ELSE '' END
        || CASE WHEN v_TONG_TRON_NAM + v_TONG_TRON_THANG + v_TONG_NGAY_TRON > 0
                THEN u'. (Tr\1ed1n: +' || v_TONG_TRON_NAM || u'n ' || v_TONG_TRON_THANG || u't ' || v_TONG_NGAY_TRON || u'ng)' ELSE '' END
        || CASE WHEN v_TONG_TDC_NAM + v_TONG_TDC_THANG + v_TONG_NGAY_TDC > 0
                THEN u'. (T\0110C: +' || v_TONG_TDC_NAM || u'n ' || v_TONG_TDC_THANG || u't ' || v_TONG_NGAY_TDC || u'ng)' ELSE '' END
        || CASE WHEN v_TONG_HOAN_NAM + v_TONG_HOAN_THANG + v_TONG_NGAY_HOAN > 0
                THEN u'. (Ho\00e3n: +' || v_TONG_HOAN_NAM || u'n ' || v_TONG_HOAN_THANG || u't ' || v_TONG_NGAY_HOAN || u'ng)' ELSE '' END
        || CASE WHEN v_TONG_NGAY_THA_DK > 0
                THEN u'. (Tha c\00f3 \0111i\1ec1u ki\1ec7n \0111\00e3 quay l\1ea1i: +' || v_TONG_NGAY_THA_DK || u' ng\00e0y)' ELSE '' END
        || CASE WHEN v_NAM_GIAM_HP + v_THANG_GIAM_HP + v_NGAY_GIAM_HP > 0
                THEN u'. (Gi\1ea3m HP: -' || v_NAM_GIAM_HP || u'n ' || v_THANG_GIAM_HP || u't ' || v_NGAY_GIAM_HP || u'ng)' ELSE '' END
        || CASE WHEN v_NAM_MIEN_HP + v_THANG_MIEN_HP + v_NGAY_MIEN_HP > 0
                THEN u'. (Mi\1ec5n HP: -' || v_NAM_MIEN_HP || u'n ' || v_THANG_MIEN_HP || u't ' || v_NGAY_MIEN_HP || u'ng)' ELSE '' END
        || CASE WHEN v_TANG_NAM + v_TANG_THANG + v_TANG_NGAY > 0
                THEN u'. (T\0103ng HP: +' || v_TANG_NAM || u'n ' || v_TANG_THANG || u't ' || v_TANG_NGAY || u'ng)' ELSE '' END
        || CASE WHEN v_NAM_CHUA_BENH + v_THANG_CHUA_BENH + v_NGAY_CHUA_BENH > 0
                THEN u'. (Ch\1eefa b\1ec7nh b\1eaft bu\1ed9c: ' || v_NAM_CHUA_BENH || u'n ' || v_THANG_CHUA_BENH || u't ' || v_NGAY_CHUA_BENH || u'ng)' ELSE '' END;

--==========================================================================================
-- EXCEPTION HANDLER
--==========================================================================================
EXCEPTION WHEN OTHERS THEN
    p_THONG_BAO := u'L\1ed7i: ' || SQLERRM;
    p_AN_THUC_NAM := 0; p_AN_THUC_THANG := 0; p_AN_THUC_NGAY := 0;
    p_DA_CHAP_HANH_NAM := 0; p_DA_CHAP_HANH_THANG := 0; p_DA_CHAP_HANH_NGAY := 0;
    p_THOI_GIAN_CON_LAI_NAM := 0; p_THOI_GIAN_CON_LAI_THANG := 0; p_THOI_GIAN_CON_LAI_NGAY := 0;
    p_NGAY_BAT_OUT := NULL; p_NGAY_HET_HAN := NULL;
END SP_TINH_NGAY_HET_AN_GENERAL;

/
--------------------------------------------------------
--  DDL for Procedure SP_TINH_NGAY_HET_AN_GENERAL_TEST
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_TINH_NGAY_HET_AN_GENERAL_TEST" (
    p_PN_ID                   IN NUMBER    DEFAULT NULL,
    p_NGAY_BAT                IN DATE      DEFAULT NULL,
    p_NGAY_YC_TINH            IN NUMBER    DEFAULT NULL,   -- YYYYMMDD; NULL = hôm nay
    p_THA_AN_PHAT_TEXT        IN NVARCHAR2 DEFAULT NULL,
    p_THA_TAM_GIAM_TEXT       IN NVARCHAR2 DEFAULT NULL,
    p_THA_TAM_GIU_TEXT        IN NVARCHAR2 DEFAULT NULL,
    p_THA_O_TRUOC_TEXT        IN NVARCHAR2 DEFAULT NULL,
    p_CHUA_BENH_TEXT          IN NVARCHAR2 DEFAULT NULL,
    p_THA_GIAM_HP_TEXT        IN NVARCHAR2 DEFAULT NULL,
    p_THA_MIEN_HP_TEXT        IN NVARCHAR2 DEFAULT NULL,
    p_THA_TANG_HINH_PHAT_TEXT IN NVARCHAR2 DEFAULT NULL,
    p_DUNG_PARAM              IN NUMBER    DEFAULT NULL,
    p_GIAM_AN_TEXT            IN NVARCHAR2 DEFAULT NULL,
    p_TRON_TEXT               IN NVARCHAR2 DEFAULT NULL,
    p_TDC_TEXT                IN NVARCHAR2 DEFAULT NULL,
    p_HOAN_TEXT               IN NVARCHAR2 DEFAULT NULL,
    p_NGAY_BAT_OUT            OUT DATE,
    p_AN_THUC_NAM             OUT NUMBER,
    p_AN_THUC_THANG           OUT NUMBER,
    p_AN_THUC_NGAY            OUT NUMBER,
    p_DA_CHAP_HANH_NAM        OUT NUMBER,
    p_DA_CHAP_HANH_THANG      OUT NUMBER,
    p_DA_CHAP_HANH_NGAY       OUT NUMBER,
    p_NGAY_HET_HAN            OUT DATE,
    p_THOI_GIAN_CON_LAI_NAM   OUT NUMBER,
    p_THOI_GIAN_CON_LAI_THANG OUT NUMBER,
    p_THOI_GIAN_CON_LAI_NGAY  OUT NUMBER,
    p_THONG_BAO               OUT NVARCHAR2,
    p_BO_QUA_TCDK             IN  NUMBER DEFAULT 0,   -- 1 = b? qua THC?K ch?a quay l?i (tính "gi? s? không THC?K")
    p_BO_QUA_KTRT             IN  NUMBER DEFAULT 0    -- 1 = b? qua ngày ra tr?i nh?p tay (PN_KET_THUC_RA_TRAIS)
)
IS
    --==========================================================================================
    -- SP LÕI TÍNH NGÀY H?T ÁN (b?n vi?t l?i). DEMO_FINAL và DEMO_FINAL2 ch? còn là wrapper g?i SP này.
    --
    -- CÔNG TH?C
    --   B   = ngày b?t (THA_NGAY_BAT, ho?c p_NGAY_BAT)
    --   T   = th?i gian tr? tr??c ngày b?t = t?m giam + t?m gi? + ? tr??c + ch?a b?nh b?t bu?c
    --   S   = ngày b?t ??u ch?p hành th?c t? = B lùi l?i T
    --         (lùi ph?n NGÀY tr??c, r?i lùi ph?n THÁNG — ?úng chi?u ng??c c?a phép c?ng, ?? S + T = B)
    --   P   = án ph?t (chung thân ?ã gi?m -> 30/20 n?m; chung thân ch?a gi?m, t? hình -> vô th?i h?n)
    --   Net = P + t?ng HP ? gi?m HP ? mi?n HP ? gi?m th?i h?n ch?p hành án (t?ng các l?n)
    --   E0  = S + Net        (neo l?ch M?T l?n)
    --   K   = th?i gian không tính vào ch?p hành án = tr?n + T?C + hoãn + THC?K ?ã b? b?t l?i
    --   E   = E0 + K
    --   N?u E s?m h?n ngày quy?t ??nh gi?m g?n nh?t -> E = ngày quy?t ??nh ?ó (không th? tha tr??c Q?).
    --
    -- QUY T?C C?NG TH?I H?N (?i?u 134 BLTTHS 2015)
    --   Th?i h?n tháng/n?m h?t vào ngày trùng c?a tháng ?ích; tháng ?ích không có ngày trùng
    --   -> h?t vào ngày cu?i cùng c?a tháng ?ó. Sau ?ó m?i c?ng ph?n ngày theo l?ch th?t.
    --   Th?i h?n ???c gi? ? d?ng (t?ng s? tháng, s? ngày); KHÔNG quy ??i 30 ngày = 1 tháng.
    --
    -- NGU?N D? LI?U: tham s? text khác NULL -> THAY TH? d? li?u DB t??ng ?ng (không c?ng d?n).
    --   Án ph?t/t?m giam/t?m gi?/? tr??c: nh? b?n c? — khi có p_PN_ID và p_DUNG_PARAM <> 1 thì ch? l?y DB.
    --==========================================================================================

    ------------------------------------------------------------------------------------------
    -- C?U HÌNH NGHI?P V? — C?N CH?T
    ------------------------------------------------------------------------------------------
    -- Có tính c? 2 ??u khi ??m s? ngày m?t kho?ng (1) hay không (0). Gi? nguyên hành vi b?n c?.
    c_TRON_CONG_1   CONSTANT NUMBER := 1;   -- tr?n: NGAY_TRON -> NGAY_BAT_LAI
    c_TDC_CONG_1    CONSTANT NUMBER := 1;   -- T?C: TU_NGAY -> NGAY_LAI
    c_HOAN_CONG_1   CONSTANT NUMBER := 1;   -- hoãn: NGAY_HOAN -> NGAY_THI_HANH_AN
    c_TCDK_CONG_1   CONSTANT NUMBER := 0;   -- THC?K: NGAY_THA -> NGAY_BAT_LAI
    c_CB_CONG_1     CONSTANT NUMBER := 1;   -- ch?a b?nh b?t bu?c: NGAY_BAT_DAU -> NGAY_KET_THUC

    -- Mã gi?m ??c bi?t (DM_MA_THOI_GIANS.MTG_MA) — theo mapping trong DEMO_FINAL2
    c_MA_CT_30      CONSTANT VARCHAR2(10) := '921000';   -- chung thân -> 30 n?m
    c_MA_CT_20      CONSTANT VARCHAR2(10) := '922000';   -- chung thân -> 20 n?m
    c_MA_GIAM_HET   CONSTANT VARCHAR2(10) := '923000';   -- gi?m h?t án

    ------------------------------------------------------------------------------------------
    -- KI?U & BI?N
    ------------------------------------------------------------------------------------------
    TYPE t_tg IS RECORD (thang NUMBER := 0, ngay NUMBER := 0);   -- 1 th?i h?n = t?ng tháng + ngày

    v_moc            DATE;
    v_B              DATE;
    v_S              DATE;
    v_end_goc        DATE;
    v_end0           DATE;
    v_end            DATE;
    v_m              DATE;
    v_m_eff          DATE;
    v_tmp            DATE;
    v_qd_giam_max    DATE;
    v_dung_param     BOOLEAN;

    v_txt_an_phat    NVARCHAR2(500);
    v_txt_tam_giam   NVARCHAR2(500);
    v_txt_tam_giu    NVARCHAR2(500);
    v_txt_o_truoc    NVARCHAR2(500);
    v_upper          NVARCHAR2(500);

    v_an_phat   t_tg;  v_tam_giam t_tg;  v_tam_giu t_tg;  v_o_truoc t_tg;  v_chua_benh t_tg;
    v_truoc     t_tg;  v_gth      t_tg;  v_giam_hp t_tg;  v_mien    t_tg;  v_tang      t_tg;
    v_net       t_tg;  v_tron     t_tg;  v_tdc     t_tg;  v_hoan    t_tg;  v_kt        t_tg;
    v_db_tang   t_tg;  v_db_giam  t_tg;
    v_ngay_tcdk NUMBER := 0;
    v_so_ngay   NUMBER;

    v_ct_so_nam      NUMBER;
    v_ct_nguon       NVARCHAR2(200);
    v_ma_dac_biet    VARCHAR2(20);
    v_canh_bao       NVARCHAR2(1000);
    v_giam_het_qd    BOOLEAN := FALSE;
    v_cnt1 NUMBER := 0; v_cnt2 NUMBER := 0; v_cnt3 NUMBER := 0;

    ------------------------------------------------------------------------------------------
    -- HÀM TI?N ÍCH
    ------------------------------------------------------------------------------------------
    FUNCTION TG(p_thang IN NUMBER, p_ngay IN NUMBER) RETURN t_tg IS
        r t_tg;
    BEGIN
        r.thang := NVL(p_thang, 0); r.ngay := NVL(p_ngay, 0);
        RETURN r;
    END;

    FUNCTION CONG(a IN t_tg, b IN t_tg) RETURN t_tg IS
    BEGIN RETURN TG(a.thang + b.thang, a.ngay + b.ngay); END;

    FUNCTION TRU(a IN t_tg, b IN t_tg) RETURN t_tg IS
    BEGIN RETURN TG(a.thang - b.thang, a.ngay - b.ngay); END;

    FUNCTION LA_RONG(a IN t_tg) RETURN BOOLEAN IS
    BEGIN RETURN NVL(a.thang, 0) = 0 AND NVL(a.ngay, 0) = 0; END;

    -- "3 n?m 9 tháng 10 ngày" -> (45 tháng, 10 ngày)
    FUNCTION PARSE_TG(p_text IN NVARCHAR2) RETURN t_tg IS
    BEGIN
        IF p_text IS NULL THEN RETURN TG(0, 0); END IF;
        RETURN TG(NVL(FN_PARSE_THOI_GIAN_TEXT(p_text, 'NAM'), 0) * 12
                    + NVL(FN_PARSE_THOI_GIAN_TEXT(p_text, 'THANG'), 0),
                  NVL(FN_PARSE_THOI_GIAN_TEXT(p_text, 'NGAY'), 0));
    END;

    -- C?ng N tháng theo ?i?u 134: ngày trùng, không có thì ngày cu?i tháng ?ích. N có th? âm.
    -- (Không dùng ADD_MONTHS tr?c ti?p vì Oracle ??y ngày cu?i tháng -> cu?i tháng ?ích,
    --  vd ADD_MONTHS(30/04, 1) = 31/05 thay vì 30/05.)
    FUNCTION CONG_THANG(p_d IN DATE, p_thang IN NUMBER) RETURN DATE IS
        v_goc DATE := TRUNC(p_d);
        v_dau DATE := ADD_MONTHS(TRUNC(p_d, 'MM'), NVL(p_thang, 0));
    BEGIN
        RETURN v_dau + LEAST(EXTRACT(DAY FROM v_goc), EXTRACT(DAY FROM LAST_DAY(v_dau))) - 1;
    END;

    FUNCTION CONG_TG(p_d IN DATE, p IN t_tg) RETURN DATE IS
    BEGIN RETURN CONG_THANG(p_d, p.thang) + p.ngay; END;

    -- Phép ng??c c?a CONG_TG: lùi ngày tr??c, r?i lùi tháng
    FUNCTION TRU_TG(p_d IN DATE, p IN t_tg) RETURN DATE IS
    BEGIN RETURN CONG_THANG(TRUNC(p_d) - p.ngay, -p.thang); END;

    -- Kho?ng cách l?ch (n?m, tháng, ngày) t? p_tu ??n p_den, nh?t quán v?i CONG_THANG:
    -- CONG_TG(p_tu, k?t qu?) = p_den.
    PROCEDURE KHOANG_CACH(p_tu IN DATE, p_den IN DATE,
                          o_nam OUT NUMBER, o_thang OUT NUMBER, o_ngay OUT NUMBER) IS
        v_th NUMBER;
    BEGIN
        o_nam := 0; o_thang := 0; o_ngay := 0;
        IF p_tu IS NULL OR p_den IS NULL OR TRUNC(p_den) <= TRUNC(p_tu) THEN RETURN; END IF;
        v_th := (EXTRACT(YEAR FROM p_den) - EXTRACT(YEAR FROM p_tu)) * 12
              + (EXTRACT(MONTH FROM p_den) - EXTRACT(MONTH FROM p_tu));
        IF CONG_THANG(p_tu, v_th) > TRUNC(p_den) THEN v_th := v_th - 1; END IF;
        o_ngay  := TRUNC(p_den) - CONG_THANG(p_tu, v_th);
        o_nam   := TRUNC(v_th / 12);
        o_thang := MOD(v_th, 12);
    END;

    FUNCTION TG_CHU(p IN t_tg) RETURN NVARCHAR2 IS
    BEGIN
        RETURN TRUNC(p.thang / 12) || u' n\0103m ' || MOD(p.thang, 12) || u' th\00e1ng ' || p.ngay || u' ng\00e0y';
    END;

    -- K?t thúc s?m (?ã tha / ??c xá / ...): ngày h?t h?n = ngày th?c t?, ?ã ch?p hành tính t? ngày b?t
    PROCEDURE KET_THUC_SOM(p_ngay IN DATE, p_tb IN NVARCHAR2, p_an_thuc_bang_da IN BOOLEAN DEFAULT FALSE) IS
    BEGIN
        p_NGAY_BAT_OUT := v_B;
        p_NGAY_HET_HAN := TRUNC(p_ngay);
        IF v_B IS NOT NULL AND p_ngay IS NOT NULL THEN
            KHOANG_CACH(v_B, p_ngay, p_DA_CHAP_HANH_NAM, p_DA_CHAP_HANH_THANG, p_DA_CHAP_HANH_NGAY);
        END IF;
        IF p_an_thuc_bang_da THEN
            p_AN_THUC_NAM := p_DA_CHAP_HANH_NAM; p_AN_THUC_THANG := p_DA_CHAP_HANH_THANG; p_AN_THUC_NGAY := p_DA_CHAP_HANH_NGAY;
        END IF;
        p_THONG_BAO := p_tb;
    END;

--==========================================================================================
BEGIN
    p_AN_THUC_NAM := 0; p_AN_THUC_THANG := 0; p_AN_THUC_NGAY := 0;
    p_DA_CHAP_HANH_NAM := 0; p_DA_CHAP_HANH_THANG := 0; p_DA_CHAP_HANH_NGAY := 0;
    p_THOI_GIAN_CON_LAI_NAM := 0; p_THOI_GIAN_CON_LAI_THANG := 0; p_THOI_GIAN_CON_LAI_NGAY := 0;
    p_NGAY_BAT_OUT := NULL; p_NGAY_HET_HAN := NULL; p_THONG_BAO := '';

    v_moc := CASE WHEN p_NGAY_YC_TINH IS NULL THEN TRUNC(SYSDATE)
                  ELSE TO_DATE(TO_CHAR(p_NGAY_YC_TINH), 'YYYYMMDD') END;
    v_dung_param := (p_PN_ID IS NULL OR NVL(p_DUNG_PARAM, 0) = 1);

    --======================================================================================
    -- B??C 1: D? li?u b?n án
    --======================================================================================
    IF p_PN_ID IS NOT NULL THEN
        BEGIN
            -- TODO: n?u 1 PN có nhi?u dòng PN_THI_HANH_AN, c?n ORDER BY theo b?n án hi?u l?c
            SELECT TRUNC(CAST(THA_NGAY_BAT AS DATE)), THA_AN_PHAT_GOC,
                   THA_THOI_GIAN_TAM_GIAM, THA_THOI_GIAN_TAM_GIU, THA_THOI_GIAN_O_TRUOC
              INTO v_B, v_txt_an_phat, v_txt_tam_giam, v_txt_tam_giu, v_txt_o_truoc
              FROM PN_THI_HANH_AN
             WHERE THA_PNLAI_LICH_ID = p_PN_ID AND ROWNUM = 1;
        EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
        END;
    END IF;

    IF p_NGAY_BAT IS NOT NULL THEN v_B := TRUNC(p_NGAY_BAT); END IF;
    IF v_dung_param THEN
        v_txt_an_phat  := NVL(p_THA_AN_PHAT_TEXT,  v_txt_an_phat);
        v_txt_tam_giam := NVL(p_THA_TAM_GIAM_TEXT, v_txt_tam_giam);
        v_txt_tam_giu  := NVL(p_THA_TAM_GIU_TEXT,  v_txt_tam_giu);
        v_txt_o_truoc  := NVL(p_THA_O_TRUOC_TEXT,  v_txt_o_truoc);
    END IF;

    --======================================================================================
    -- B??C 2: Tr?ng thái ?ã k?t thúc / ch?a xác ??nh (ch? khi có PN_ID, l?c theo m?c tính)
    --======================================================================================
    IF p_PN_ID IS NOT NULL THEN

        -- 2.1 Ngày ra tr?i nh?p tay (b? qua n?u trùng ngày THC?K — ?ó là ngày tha s?m, không ph?i h?t án)
        IF NVL(p_BO_QUA_KTRT, 0) != 1 THEN
            BEGIN
                SELECT TRUNC(CAST(k.KTRT_NGAY_THA AS DATE)) INTO v_tmp
                  FROM PN_KET_THUC_RA_TRAIS k
                 WHERE k.KTRT_PN_LAI_LICH_ID = p_PN_ID
                   AND NVL(k.IS_DELETED, 0) = 0
                   AND k.KTRT_NGAY_THA IS NOT NULL
                   AND TRUNC(CAST(k.KTRT_NGAY_THA AS DATE)) <= v_moc
                   AND NOT EXISTS (SELECT 1 FROM THA_CO_DIEU_KIENS t
                                    WHERE t.PHAM_NHAN_ID = p_PN_ID
                                      AND NVL(t.IS_DELETED, 0) = 0
                                      AND TRUNC(CAST(t.NGAY_THA AS DATE)) = TRUNC(CAST(k.KTRT_NGAY_THA AS DATE)))
                 ORDER BY k.CREATION_TIME DESC
                 FETCH FIRST 1 ROW ONLY;
                KET_THUC_SOM(v_tmp, u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c tha v\00e0o ng\00e0y ' || TO_CHAR(v_tmp, 'DD/MM/YYYY') || u'.', TRUE);
                RETURN;
            EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
            END;
        END IF;

        -- 2.2 Gi?m h?t án
        BEGIN
            SELECT TRUNC(CAST(gth.NGAY_THA_GIAM_HET_AN AS DATE)) INTO v_tmp
              FROM GIAM_THOI_HANS gth
             WHERE gth.PHAM_NHAN_ID = p_PN_ID
               AND NVL(gth.IS_DELETED, 0) = 0
               AND gth.NGAY_THA_GIAM_HET_AN IS NOT NULL
               AND TRUNC(CAST(gth.NGAY_THA_GIAM_HET_AN AS DATE)) <= v_moc
             ORDER BY gth.NGAY_THA_GIAM_HET_AN
             FETCH FIRST 1 ROW ONLY;
        EXCEPTION WHEN NO_DATA_FOUND THEN v_tmp := NULL;
        END;
        IF v_tmp IS NULL THEN
            BEGIN
                SELECT TRUNC(CAST(gth.NGAY_QUYET_DINH AS DATE)) INTO v_tmp
                  FROM GIAM_THOI_HANS gth
                  JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
                 WHERE gth.PHAM_NHAN_ID = p_PN_ID
                   AND NVL(gth.IS_DELETED, 0) = 0
                   AND dmtg.MTG_MA = c_MA_GIAM_HET
                   AND gth.NGAY_QUYET_DINH IS NOT NULL
                   AND TRUNC(CAST(gth.NGAY_QUYET_DINH AS DATE)) <= v_moc
                 ORDER BY gth.NGAY_QUYET_DINH
                 FETCH FIRST 1 ROW ONLY;
            EXCEPTION WHEN NO_DATA_FOUND THEN v_tmp := NULL;
            END;
        END IF;
        IF v_tmp IS NOT NULL THEN
            KET_THUC_SOM(v_tmp, u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c gi\1ea3m h\1ebft \00e1n v\00e0o ng\00e0y ' || TO_CHAR(v_tmp, 'DD/MM/YYYY') || u'.');
            RETURN;
        END IF;

        -- 2.3 ??c xá
        BEGIN
            SELECT TRUNC(CAST(DX_NGAY_THA AS DATE)) INTO v_tmp
              FROM PN_DAC_XAS
             WHERE PNLAI_LICH_ID = p_PN_ID AND NVL(IS_DELETED, 0) = 0
               AND DX_NGAY_THA IS NOT NULL AND TRUNC(CAST(DX_NGAY_THA AS DATE)) <= v_moc
             ORDER BY CREATION_TIME DESC FETCH FIRST 1 ROW ONLY;
            KET_THUC_SOM(v_tmp, u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c tha v\00e0o ng\00e0y ' || TO_CHAR(v_tmp, 'DD/MM/YYYY') || u'. \0110\01b0\1ee3c \0111\1eb7c x\00e1.');
            RETURN;
        EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
        END;

        -- 2.4 Tha có ?i?u ki?n, ch?a b? b?t l?i
        IF NVL(p_BO_QUA_TCDK, 0) != 1 THEN
            BEGIN
                SELECT TRUNC(CAST(NGAY_THA AS DATE)) INTO v_tmp
                  FROM THA_CO_DIEU_KIENS
                 WHERE PHAM_NHAN_ID = p_PN_ID AND NVL(IS_DELETED, 0) = 0
                   AND NGAY_THA IS NOT NULL AND TRUNC(CAST(NGAY_THA AS DATE)) <= v_moc
                   AND (NGAY_BAT_LAI IS NULL OR TRUNC(CAST(NGAY_BAT_LAI AS DATE)) > v_moc)
                 ORDER BY CREATION_TIME DESC FETCH FIRST 1 ROW ONLY;
                KET_THUC_SOM(v_tmp, u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c tha v\00e0o ng\00e0y ' || TO_CHAR(v_tmp, 'DD/MM/YYYY') || u'. \0110\01b0\1ee3c tha c\00f3 \0111i\1ec1u ki\1ec7n.');
                RETURN;
            EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
            END;
        END IF;

        -- 2.5 H?y án, ch?a tr? l?i
        BEGIN
            SELECT TRUNC(CAST(NGAY_TRA_TU_DO AS DATE)) INTO v_tmp
              FROM HUY_ANS
             WHERE PHAM_NHAN_ID = p_PN_ID AND NVL(IS_DELETED, 0) = 0
               AND NGAY_TRA_TU_DO IS NOT NULL AND TRUNC(CAST(NGAY_TRA_TU_DO AS DATE)) <= v_moc
               AND (NGAY_TRO_LAI IS NULL OR TRUNC(CAST(NGAY_TRO_LAI AS DATE)) > v_moc)
             ORDER BY CREATION_TIME DESC FETCH FIRST 1 ROW ONLY;
            KET_THUC_SOM(v_tmp, u'Ph\1ea1m nh\00e2n \0111\00e3 \0111\01b0\1ee3c tha v\00e0o ng\00e0y ' || TO_CHAR(v_tmp, 'DD/MM/YYYY') || u'. \0110\01b0\1ee3c h\1ee7y \00e1n.');
            RETURN;
        EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
        END;

        -- 2.6 Mi?n h?t án (b?n ghi c? 9/23/0)
        BEGIN
            SELECT TRUNC(CAST(MHP_NGAY_TU_DO AS DATE)) INTO v_tmp
              FROM MIEN_HINH_PHATS
             WHERE PN_LAI_LICH_ID = p_PN_ID AND NVL(IS_DELETED, 0) = 0
               AND NVL(MHP_THM_YEAR, 0) = 9 AND NVL(MHP_THM_MONTH, 0) = 23 AND NVL(MHP_THM_DAY, 0) = 0
               AND MHP_NGAY_TU_DO IS NOT NULL AND TRUNC(CAST(MHP_NGAY_TU_DO AS DATE)) <= v_moc
             ORDER BY CREATION_TIME DESC FETCH FIRST 1 ROW ONLY;
            KET_THUC_SOM(v_tmp, u'Ph\1ea1m nh\00e2n \0111\01b0\1ee3c mi\1ec5n h\1ebft \00e1n (92300). Ng\00e0y t\1ef1 do: ' || TO_CHAR(v_tmp, 'DD/MM/YYYY'));
            RETURN;
        EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
        END;

        -- 2.7 Còn tr?n / T?C / hoãn ch?a k?t thúc t?i m?c tính -> ch?a xác ??nh ???c
        SELECT COUNT(*) INTO v_cnt1 FROM TRON_TRAIS
         WHERE PHAM_NHAN_ID = p_PN_ID AND NVL(IS_DELETED, 0) = 0
           AND NGAY_TRON IS NOT NULL AND TRUNC(CAST(NGAY_TRON AS DATE)) <= v_moc
           AND (NGAY_BAT_LAI IS NULL OR TRUNC(CAST(NGAY_BAT_LAI AS DATE)) > v_moc);
        SELECT COUNT(*) INTO v_cnt2 FROM TAM_DINH_CHIS
         WHERE PHAM_NHAN_ID = p_PN_ID AND NVL(IS_DELETED, 0) = 0
           AND TU_NGAY IS NOT NULL AND TRUNC(CAST(TU_NGAY AS DATE)) <= v_moc
           AND (NGAY_LAI IS NULL OR TRUNC(CAST(NGAY_LAI AS DATE)) > v_moc);
        SELECT COUNT(*) INTO v_cnt3 FROM HOAN_THI_HANH_ANS
         WHERE PHAM_NHAN_ID = p_PN_ID AND NVL(IS_DELETED, 0) = 0
           AND NGAY_HOAN IS NOT NULL AND TRUNC(CAST(NGAY_HOAN AS DATE)) <= v_moc
           AND (NGAY_THI_HANH_AN IS NULL OR TRUNC(CAST(NGAY_THI_HANH_AN AS DATE)) > v_moc);
        IF v_cnt1 + v_cnt2 + v_cnt3 > 0 THEN
            p_NGAY_BAT_OUT := v_B;
            p_THONG_BAO :=
                   CASE WHEN v_cnt1 > 0 THEN u'Ch\01b0a x\00e1c \0111\1ecbnh: c\00f2n ' || v_cnt1 || u' l\1ea7n tr\1ed1n ch\01b0a b\1eaft l\1ea1i. ' END
                || CASE WHEN v_cnt2 > 0 THEN u'Ch\01b0a x\00e1c \0111\1ecbnh: c\00f2n ' || v_cnt2 || u' l\1ea7n T\0110C ch\01b0a quay l\1ea1i. ' END
                || CASE WHEN v_cnt3 > 0 THEN u'Ch\01b0a x\00e1c \0111\1ecbnh: c\00f2n ' || v_cnt3 || u' l\1ea7n ho\00e3n ch\01b0a thi h\00e0nh. ' END;
            RETURN;
        END IF;
    END IF;

    --======================================================================================
    -- B??C 3: Ki?m tra d? li?u b?t bu?c
    --======================================================================================
    IF v_B IS NULL THEN
        p_THONG_BAO := u'L\1ed7i: thi\1ebfu ng\00e0y b\1eaft (p_NGAY_BAT ho\1eb7c PN_THI_HANH_AN.THA_NGAY_BAT).';
        RETURN;
    END IF;
    IF v_txt_an_phat IS NULL THEN
        p_NGAY_BAT_OUT := v_B;
        p_THONG_BAO := u'L\1ed7i: thi\1ebfu \00e1n ph\1ea1t.';
        RETURN;
    END IF;

    --======================================================================================
    -- B??C 4: Xác ??nh lo?i án & án ph?t P
    --   Chung thân: ch? tính khi có c?n c? gi?m xu?ng 30/20 n?m
    --     (?u tiên Q? gi?m mã 921000/922000; n?u không có thì ??c "30 n?m"/"20 n?m" trong text án ph?t).
    --   Nh?n di?n b?ng c?m "CHUNG THÂN" (không ph?i ch? "CHUNG" ??n l? — tránh "hình ph?t chung").
    --   T? hình: nh?n di?n b?ng c?m "T? HÌNH" (regex c? kh?p nh?m "THI HÀNH").
    --======================================================================================
    v_upper := UPPER(v_txt_an_phat);

    IF REGEXP_LIKE(v_upper, u'CHUNG[[:space:]]*TH(\00c2|A)N') THEN
        IF p_PN_ID IS NOT NULL THEN
            BEGIN
                SELECT dmtg.MTG_MA INTO v_ma_dac_biet
                  FROM GIAM_THOI_HANS gth
                  JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
                 WHERE gth.PHAM_NHAN_ID = p_PN_ID
                   AND NVL(gth.IS_DELETED, 0) = 0
                   AND dmtg.MTG_MA IN (c_MA_CT_30, c_MA_CT_20)
                   AND (gth.NGAY_QUYET_DINH IS NULL OR TRUNC(CAST(gth.NGAY_QUYET_DINH AS DATE)) <= v_moc)
                 ORDER BY gth.NGAY_QUYET_DINH DESC NULLS LAST
                 FETCH FIRST 1 ROW ONLY;
            EXCEPTION WHEN NO_DATA_FOUND THEN v_ma_dac_biet := NULL;
            END;
        END IF;

        IF v_ma_dac_biet = c_MA_CT_30 THEN
            v_ct_so_nam := 30; v_ct_nguon := u'Q\0110 gi\1ea3m m\00e3 ' || c_MA_CT_30;
        ELSIF v_ma_dac_biet = c_MA_CT_20 THEN
            v_ct_so_nam := 20; v_ct_nguon := u'Q\0110 gi\1ea3m m\00e3 ' || c_MA_CT_20;
        ELSE
            v_ct_so_nam := TO_NUMBER(REGEXP_SUBSTR(v_upper, u'(^|[^0-9])(20|30)[[:space:]]*N(\0102|A)M', 1, 1, NULL, 2));
            IF v_ct_so_nam IS NOT NULL THEN v_ct_nguon := u'text \00e1n ph\1ea1t'; END IF;
        END IF;

        IF v_ct_so_nam IS NULL THEN
            p_NGAY_BAT_OUT := v_B;
            p_THONG_BAO := u'B\1ea3n \00e1n: Chung th\00e2n (v\00f4 th\1eddi h\1ea1n).';
            RETURN;
        END IF;
        v_an_phat := TG(v_ct_so_nam * 12, 0);

    ELSIF REGEXP_LIKE(v_upper, u'T(\1eec|U)[[:space:]]*H(\00cc|I)NH') THEN
        p_NGAY_BAT_OUT := v_B;
        p_THONG_BAO := u'B\1ea3n \00e1n: T\1eed h\00ecnh (v\00f4 th\1eddi h\1ea1n).';
        RETURN;

    ELSE
        v_an_phat := PARSE_TG(v_txt_an_phat);
        IF LA_RONG(v_an_phat) THEN
            p_NGAY_BAT_OUT := v_B;
            p_THONG_BAO := u'L\1ed7i: kh\00f4ng \0111\1ecdc \0111\01b0\1ee3c th\1eddi h\1ea1n \00e1n ph\1ea1t "' || v_txt_an_phat || u'".';
            RETURN;
        END IF;
        -- Có mã gi?m chung thân nh?ng án ph?t không ph?i chung thân -> d? li?u l?ch, ch? c?nh báo
        IF p_PN_ID IS NOT NULL THEN
            SELECT COUNT(*) INTO v_cnt1
              FROM GIAM_THOI_HANS gth JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
             WHERE gth.PHAM_NHAN_ID = p_PN_ID AND NVL(gth.IS_DELETED, 0) = 0
               AND dmtg.MTG_MA IN (c_MA_CT_30, c_MA_CT_20);
            IF v_cnt1 > 0 THEN
                v_canh_bao := v_canh_bao || u' C\1ea3nh b\00e1o: c\00f3 Q\0110 gi\1ea3m chung th\00e2n nh\01b0ng \00e1n ph\1ea1t kh\00f4ng ph\1ea3i chung th\00e2n \2014 \0111\00e3 b\1ecf qua Q\0110 n\00e0y.';
            END IF;
        END IF;
    END IF;

    --======================================================================================
    -- B??C 5: Thành ph?n
    --======================================================================================
    -- 5.1 Tr? tr??c ngày b?t
    v_tam_giam := PARSE_TG(v_txt_tam_giam);
    v_tam_giu  := PARSE_TG(v_txt_tam_giu);
    v_o_truoc  := PARSE_TG(v_txt_o_truoc);
    IF p_CHUA_BENH_TEXT IS NOT NULL THEN
        v_chua_benh := PARSE_TG(p_CHUA_BENH_TEXT);
    ELSIF p_PN_ID IS NOT NULL THEN
        SELECT NVL(SUM(TRUNC(CAST(NGAY_KET_THUC AS DATE)) - TRUNC(CAST(NGAY_BAT_DAU AS DATE)) + c_CB_CONG_1), 0)
          INTO v_so_ngay
          FROM CHUA_BENH_BAT_BUOCS
         WHERE PHAM_NHAN_ID = p_PN_ID AND NVL(IS_DELETED, 0) = 0
           AND NGAY_BAT_DAU IS NOT NULL AND NGAY_KET_THUC IS NOT NULL
           AND TRUNC(CAST(NGAY_KET_THUC AS DATE)) <= v_B;
        v_chua_benh := TG(0, v_so_ngay);
    END IF;
    v_truoc := CONG(CONG(v_tam_giam, v_tam_giu), CONG(v_o_truoc, v_chua_benh));

    -- 5.2 Gi?m th?i h?n ch?p hành án (lo?i các mã ??c bi?t 921000/922000/923000)
    IF p_PN_ID IS NOT NULL THEN
        SELECT MAX(TRUNC(CAST(gth.NGAY_QUYET_DINH AS DATE))) INTO v_qd_giam_max
          FROM GIAM_THOI_HANS gth JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
         WHERE gth.PHAM_NHAN_ID = p_PN_ID AND NVL(gth.IS_DELETED, 0) = 0
           AND dmtg.MTG_MA NOT IN (c_MA_CT_30, c_MA_CT_20, c_MA_GIAM_HET)
           AND TRUNC(CAST(gth.NGAY_QUYET_DINH AS DATE)) <= v_moc;
    END IF;
    IF p_GIAM_AN_TEXT IS NOT NULL THEN
        v_gth := PARSE_TG(p_GIAM_AN_TEXT);
    ELSIF p_PN_ID IS NOT NULL THEN
        FOR rec IN (
            SELECT dmtg.MTG_TITLE
              FROM GIAM_THOI_HANS gth
              JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID AND NVL(dmtg.IS_DELETED, 0) = 0
             WHERE gth.PHAM_NHAN_ID = p_PN_ID AND NVL(gth.IS_DELETED, 0) = 0
               AND dmtg.MTG_MA NOT IN (c_MA_CT_30, c_MA_CT_20, c_MA_GIAM_HET)
               AND (gth.NGAY_QUYET_DINH IS NULL OR TRUNC(CAST(gth.NGAY_QUYET_DINH AS DATE)) <= v_moc)
        ) LOOP
            v_gth := CONG(v_gth, PARSE_TG(rec.MTG_TITLE));
        END LOOP;
    END IF;

    -- 5.3 T?ng / gi?m hình ph?t (LTGHP_MA 10 = t?ng, 20 = gi?m)
    IF p_PN_ID IS NOT NULL AND (p_THA_TANG_HINH_PHAT_TEXT IS NULL OR p_THA_GIAM_HP_TEXT IS NULL) THEN
        FOR rec IN (
            SELECT dmtg.MTG_TITLE, ltg.LTGHP_MA
              FROM TANG_GIAM_HINH_PHATS tghp
              JOIN DM_LOAI_TANG_GIAM_HINH_PHATS ltg ON tghp.LOAI_TANG_GIAM_ID = ltg.ID AND NVL(ltg.IS_DELETED, 0) = 0
              JOIN DM_MA_THOI_GIANS dmtg ON tghp.THOI_HAN_ID = dmtg.ID AND NVL(dmtg.IS_DELETED, 0) = 0
             WHERE tghp.PHAM_NHAN_ID = p_PN_ID AND NVL(tghp.IS_DELETED, 0) = 0
        ) LOOP
            IF rec.LTGHP_MA = '10' THEN v_db_tang := CONG(v_db_tang, PARSE_TG(rec.MTG_TITLE));
            ELSIF rec.LTGHP_MA = '20' THEN v_db_giam := CONG(v_db_giam, PARSE_TG(rec.MTG_TITLE));
            END IF;
        END LOOP;
    END IF;
    IF p_THA_TANG_HINH_PHAT_TEXT IS NOT NULL THEN v_tang := PARSE_TG(p_THA_TANG_HINH_PHAT_TEXT); ELSE v_tang := v_db_tang; END IF;
    IF p_THA_GIAM_HP_TEXT IS NOT NULL THEN v_giam_hp := PARSE_TG(p_THA_GIAM_HP_TEXT); ELSE v_giam_hp := v_db_giam; END IF;

    -- 5.4 Mi?n hình ph?t (lo?i b?n ghi c? mi?n h?t án 9/23/0)
    IF p_THA_MIEN_HP_TEXT IS NOT NULL THEN
        v_mien := PARSE_TG(p_THA_MIEN_HP_TEXT);
    ELSIF p_PN_ID IS NOT NULL THEN
        SELECT NVL(SUM(NVL(MHP_THM_YEAR, 0) * 12 + NVL(MHP_THM_MONTH, 0)), 0), NVL(SUM(NVL(MHP_THM_DAY, 0)), 0)
          INTO v_mien.thang, v_mien.ngay
          FROM MIEN_HINH_PHATS
         WHERE PN_LAI_LICH_ID = p_PN_ID AND NVL(IS_DELETED, 0) = 0
           AND NOT (NVL(MHP_THM_YEAR, 0) = 9 AND NVL(MHP_THM_MONTH, 0) = 23 AND NVL(MHP_THM_DAY, 0) = 0);
    END IF;

    -- 5.5 Th?i gian không tính vào ch?p hành án (ch? các kho?ng ?ã ?óng tr??c/t?i m?c tính)
    IF p_TRON_TEXT IS NOT NULL THEN
        v_tron := PARSE_TG(p_TRON_TEXT);
    ELSIF p_PN_ID IS NOT NULL THEN
        SELECT NVL(SUM(GREATEST(TRUNC(CAST(NGAY_BAT_LAI AS DATE)) - TRUNC(CAST(NGAY_TRON AS DATE)) + c_TRON_CONG_1, 0)), 0)
          INTO v_so_ngay FROM TRON_TRAIS
         WHERE PHAM_NHAN_ID = p_PN_ID AND NVL(IS_DELETED, 0) = 0
           AND NGAY_TRON IS NOT NULL AND NGAY_BAT_LAI IS NOT NULL
           AND TRUNC(CAST(NGAY_BAT_LAI AS DATE)) <= v_moc;
        v_tron := TG(0, v_so_ngay);
    END IF;

    IF p_TDC_TEXT IS NOT NULL THEN
        v_tdc := PARSE_TG(p_TDC_TEXT);
    ELSIF p_PN_ID IS NOT NULL THEN
        SELECT NVL(SUM(GREATEST(TRUNC(CAST(NGAY_LAI AS DATE)) - TRUNC(CAST(TU_NGAY AS DATE)) + c_TDC_CONG_1, 0)), 0)
          INTO v_so_ngay FROM TAM_DINH_CHIS
         WHERE PHAM_NHAN_ID = p_PN_ID AND NVL(IS_DELETED, 0) = 0
           AND TU_NGAY IS NOT NULL AND NGAY_LAI IS NOT NULL
           AND TRUNC(CAST(NGAY_LAI AS DATE)) <= v_moc;
        v_tdc := TG(0, v_so_ngay);
    END IF;

    IF p_HOAN_TEXT IS NOT NULL THEN
        v_hoan := PARSE_TG(p_HOAN_TEXT);
    ELSIF p_PN_ID IS NOT NULL THEN
        SELECT NVL(SUM(GREATEST(TRUNC(CAST(NGAY_THI_HANH_AN AS DATE)) - TRUNC(CAST(NGAY_HOAN AS DATE)) + c_HOAN_CONG_1, 0)), 0)
          INTO v_so_ngay FROM HOAN_THI_HANH_ANS
         WHERE PHAM_NHAN_ID = p_PN_ID AND NVL(IS_DELETED, 0) = 0
           AND NGAY_HOAN IS NOT NULL AND NGAY_THI_HANH_AN IS NOT NULL
           AND TRUNC(CAST(NGAY_THI_HANH_AN AS DATE)) <= v_moc;
        v_hoan := TG(0, v_so_ngay);
    END IF;

    IF p_PN_ID IS NOT NULL THEN
        SELECT NVL(SUM(GREATEST(TRUNC(CAST(NGAY_BAT_LAI AS DATE)) - TRUNC(CAST(NGAY_THA AS DATE)) + c_TCDK_CONG_1, 0)), 0)
          INTO v_ngay_tcdk FROM THA_CO_DIEU_KIENS
         WHERE PHAM_NHAN_ID = p_PN_ID AND NVL(IS_DELETED, 0) = 0
           AND NGAY_THA IS NOT NULL AND NGAY_BAT_LAI IS NOT NULL
           AND TRUNC(CAST(NGAY_BAT_LAI AS DATE)) <= v_moc;
    END IF;

    v_kt := CONG(CONG(v_tron, v_tdc), CONG(v_hoan, TG(0, v_ngay_tcdk)));

    --======================================================================================
    -- B??C 6: Tính ngày
    --======================================================================================
    v_S       := TRU_TG(v_B, v_truoc);
    v_end_goc := CONG_TG(v_S, v_an_phat);

    -- 6.1 T?m giam/t?m gi?/? tr??c/ch?a b?nh ?ã bù ?? án ph?t -> t? do t?i tòa
    IF v_end_goc <= v_B THEN
        p_NGAY_BAT_OUT := v_B;
        p_NGAY_HET_HAN := v_B;
        p_DA_CHAP_HANH_NAM := TRUNC(v_an_phat.thang / 12);
        p_DA_CHAP_HANH_THANG := MOD(v_an_phat.thang, 12);
        p_DA_CHAP_HANH_NGAY := v_an_phat.ngay;
        p_THONG_BAO := u'Ph\1ea1m nh\00e2n \0111\00e3 ch\1ea5p h\00e0nh \0111\1ee7 \00e1n qua t\1ea1m giam/t\1ea1m gi\1eef/\1edf tr\01b0\1edbc/ch\1eefa b\1ec7nh b\1eaft bu\1ed9c - \0111\01b0\1ee3c tuy\00ean t\1ef1 do t\1ea1i t\00f2a.'
                       || v_canh_bao;
        RETURN;
    END IF;

    -- 6.2 Net = P + t?ng ? gi?m HP ? mi?n ? gi?m th?i h?n; neo l?ch M?T l?n t? S
    v_net  := TRU(TRU(TRU(CONG(v_an_phat, v_tang), v_giam_hp), v_mien), v_gth);
    v_end0 := CONG_TG(v_S, v_net);

    -- 6.3 C?ng th?i gian không tính vào ch?p hành án
    v_end  := CONG_TG(v_end0, v_kt);

    -- 6.4 Không th? h?t án tr??c ngày quy?t ??nh gi?m g?n nh?t, và không tr??c ngày b?t
    IF v_qd_giam_max IS NOT NULL AND v_end < v_qd_giam_max
       AND NOT (LA_RONG(v_gth) AND LA_RONG(v_giam_hp) AND LA_RONG(v_mien)) THEN
        v_end := v_qd_giam_max;
        v_giam_het_qd := TRUE;
    END IF;
    IF v_end < v_B THEN v_end := v_B; END IF;

    --======================================================================================
    -- B??C 7: Output
    --   Án th?c     = t? ngày b?t ??n ngày h?t án ch?a ?i?u ch?nh (P ? T)
    --   ?ã ch?p hành = t? S ??n m?c (min(ngày YC, ngày h?t án)), tr? th?i gian không tính
    --   Còn l?i     = t? m?c ??n ngày h?t án — luôn kh?p v?i p_NGAY_HET_HAN
    --======================================================================================
    p_NGAY_BAT_OUT := v_B;
    p_NGAY_HET_HAN := v_end;
    KHOANG_CACH(v_B, v_end_goc, p_AN_THUC_NAM, p_AN_THUC_THANG, p_AN_THUC_NGAY);

    v_m     := LEAST(v_moc, v_end);
    v_m_eff := TRU_TG(v_m, v_kt);
    KHOANG_CACH(v_S, v_m_eff, p_DA_CHAP_HANH_NAM, p_DA_CHAP_HANH_THANG, p_DA_CHAP_HANH_NGAY);
    KHOANG_CACH(v_m, v_end, p_THOI_GIAN_CON_LAI_NAM, p_THOI_GIAN_CON_LAI_THANG, p_THOI_GIAN_CON_LAI_NGAY);

    p_THONG_BAO := u'Ng\00e0y b\1eaft: ' || TO_CHAR(v_B, 'DD/MM/YYYY') || u'. '
        || CASE WHEN v_ct_so_nam IS NOT NULL
                THEN u'Chung th\00e2n gi\1ea3m xu\1ed1ng ' || v_ct_so_nam || u' n\0103m (' || v_ct_nguon || u'). ' END
        || u'\00c1n th\1ef1c: ' || p_AN_THUC_NAM || u' n\0103m, ' || p_AN_THUC_THANG || u' th\00e1ng, ' || p_AN_THUC_NGAY || u' ng\00e0y. '
        || u'Ng\00e0y h\1ebft h\1ea1n: ' || TO_CHAR(v_end, 'DD/MM/YYYY')
        || CASE WHEN v_giam_het_qd THEN u' (gi\1ea3m h\1ebft \00e1n theo Q\0110 ng\00e0y ' || TO_CHAR(v_qd_giam_max, 'DD/MM/YYYY') || u')' END
        || CASE WHEN NOT LA_RONG(v_truoc)   THEN u'. (Tr\1eeb tr\01b0\1edbc ng\00e0y b\1eaft: ' || TG_CHU(v_truoc) || u')' END
        || CASE WHEN NOT LA_RONG(v_gth)     THEN u'. (Gi\1ea3m TH: -' || TG_CHU(v_gth) || u')' END
        || CASE WHEN NOT LA_RONG(v_giam_hp) THEN u'. (Gi\1ea3m HP: -' || TG_CHU(v_giam_hp) || u')' END
        || CASE WHEN NOT LA_RONG(v_mien)    THEN u'. (Mi\1ec5n HP: -' || TG_CHU(v_mien) || u')' END
        || CASE WHEN NOT LA_RONG(v_tang)    THEN u'. (T\0103ng HP: +' || TG_CHU(v_tang) || u')' END
        || CASE WHEN NOT LA_RONG(v_tron)    THEN u'. (Tr\1ed1n: +' || TG_CHU(v_tron) || u')' END
        || CASE WHEN NOT LA_RONG(v_tdc)     THEN u'. (T\0110C: +' || TG_CHU(v_tdc) || u')' END
        || CASE WHEN NOT LA_RONG(v_hoan)    THEN u'. (Ho\00e3n: +' || TG_CHU(v_hoan) || u')' END
        || CASE WHEN v_ngay_tcdk > 0        THEN u'. (Tha c\00f3 \0111i\1ec1u ki\1ec7n \0111\00e3 b\1ecb b\1eaft l\1ea1i: +' || v_ngay_tcdk || u' ng\00e0y)' END
        || u'.' || v_canh_bao;

EXCEPTION WHEN OTHERS THEN
    p_THONG_BAO := u'L\1ed7i: ' || SQLERRM;
    p_AN_THUC_NAM := 0; p_AN_THUC_THANG := 0; p_AN_THUC_NGAY := 0;
    p_DA_CHAP_HANH_NAM := 0; p_DA_CHAP_HANH_THANG := 0; p_DA_CHAP_HANH_NGAY := 0;
    p_THOI_GIAN_CON_LAI_NAM := 0; p_THOI_GIAN_CON_LAI_THANG := 0; p_THOI_GIAN_CON_LAI_NGAY := 0;
    p_NGAY_BAT_OUT := NULL; p_NGAY_HET_HAN := NULL;
END SP_TINH_NGAY_HET_AN_GENERAL_TEST;

/
--------------------------------------------------------
--  DDL for Procedure SP_TK_C10_MUC_XET_GIAM
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_TK_C10_MUC_XET_GIAM" AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH
    PNS AS (
        SELECT ll.ID, ll.LL_DM_GIOI_TINH_ID, ll.LL_TRAI_GIAM_ID
        FROM QLPN.PN_LAI_LICHS ll
        JOIN QLPN.GTT_PN_IDS g ON g.PN_ID = ll.ID
        WHERE NVL(ll.IS_DELETED, 0) = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
    ),
    KY AS (
        SELECT MAX(k.KGTH_NGAY_XET_GIAM) AS NGAY_XET
        FROM QLPN.GTH_KY_GIAM_THOI_HANS k
        WHERE NVL(k.IS_DELETED, 0) = 0
          AND k.KGTH_TRANG_THAI = 1
          AND k.KGTH_NGAY_XET_GIAM IS NOT NULL
          AND k.KGTH_TRAI_GIAM_MA IN (
                SELECT DISTINCT tg.TG_MA
                FROM PNS p JOIN QLPN.DM_TRAI_GIAMS tg ON tg.ID = p.LL_TRAI_GIAM_ID)
    ),
    MUC AS (
        SELECT gth.PHAM_NHAN_ID,
               dmtg.MTG_MA, dmtg.MTG_TITLE, dmtg.MTG_THANG, dmtg.MTG_NGAY,
               CASE WHEN UPPER(dgt.GT_TEN) LIKE u'NAM%' THEN 1 ELSE 0 END AS LA_NAM
        FROM QLPN.GIAM_THOI_HANS gth
        JOIN KY ON TRUNC(gth.NGAY_XET) = TRUNC(KY.NGAY_XET)
        JOIN PNS p ON p.ID = gth.PHAM_NHAN_ID
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg ON dmtg.ID = gth.MUC_DE_NGHI_ID AND NVL(dmtg.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS  dgt  ON dgt.ID = p.LL_DM_GIOI_TINH_ID
        WHERE NVL(gth.IS_DELETED, 0) = 0
          AND gth.MUC_DE_NGHI_ID IS NOT NULL
    ),
    LOAI_HOA AS (
        SELECT PHAM_NHAN_ID, LA_NAM, MTG_MA, MTG_TITLE, MTG_THANG, MTG_NGAY,
               CASE
                   WHEN MTG_NGAY IS NULL THEN 'S'
                   -- [S?A 1] Thêm nhánh NGÀY: m?c "27 ngày" (THANG = 0, NGAY = 27) tr??c ?ây r?i vào
                   -- 'X' nên generator b? qua, m?t c? dòng l?n s? trong III/T?NG. Nay nó thu?c kh?i
                   -- "GI?M CÓ TH?I H?N" và in b?ng chính MTG_TITLE c?a danh m?c.
                   WHEN NVL(MTG_THANG, 0) > 0 OR NVL(MTG_NGAY, 0) > 0 THEN 'M'
                   ELSE 'X'
               END AS LOAI
        FROM MUC
    ),
    S_ROWS AS (
        SELECT MTG_MA, MTG_TITLE,
               COUNT(DISTINCT PHAM_NHAN_ID) AS TONG,
               COUNT(DISTINCT CASE WHEN LA_NAM = 1 THEN PHAM_NHAN_ID END) AS NAM,
               COUNT(DISTINCT CASE WHEN LA_NAM = 0 THEN PHAM_NHAN_ID END) AS NU,
               ROW_NUMBER() OVER (ORDER BY MTG_MA) AS RN
        FROM LOAI_HOA
        WHERE LOAI = 'S'
        GROUP BY MTG_MA, MTG_TITLE
    ),
    -- [S?A 2] G?p theo CHÍNH DÒNG DANH M?C (MA, TITLE, THANG), không g?p theo MTG_THANG — n?u không
    -- m?c "1 n?m" (THANG = 12) b? in "12 tháng" và c?ng d?n v?i m?i m?c cùng 12 tháng.
    THANG AS (
        SELECT MTG_MA, MTG_TITLE, MTG_THANG,
               COUNT(DISTINCT PHAM_NHAN_ID) AS TONG,
               COUNT(DISTINCT CASE WHEN LA_NAM = 1 THEN PHAM_NHAN_ID END) AS NAM,
               COUNT(DISTINCT CASE WHEN LA_NAM = 0 THEN PHAM_NHAN_ID END) AS NU
        FROM LOAI_HOA
        WHERE LOAI = 'M'
        GROUP BY MTG_MA, MTG_TITLE, MTG_THANG
    ),
    X_ROWS AS (
        SELECT MTG_TITLE AS TEN,
               COUNT(DISTINCT PHAM_NHAN_ID) AS TONG,
               COUNT(DISTINCT CASE WHEN LA_NAM = 1 THEN PHAM_NHAN_ID END) AS NAM,
               COUNT(DISTINCT CASE WHEN LA_NAM = 0 THEN PHAM_NHAN_ID END) AS NU
        FROM LOAI_HOA
        WHERE LOAI = 'X'
        GROUP BY MTG_TITLE
    ),
    III_TOT AS (
        SELECT NVL(SUM(TONG), 0) AS TONG, NVL(SUM(NAM), 0) AS NAM, NVL(SUM(NU), 0) AS NU FROM THANG
    ),
    S_TOT AS (
        SELECT NVL(SUM(TONG), 0) AS TONG, NVL(SUM(NAM), 0) AS NAM, NVL(SUM(NU), 0) AS NU FROM S_ROWS
    )
    SELECT *
    FROM (
        SELECT 10 + s.RN AS THU_TU, 'S' AS LOAI, s.MTG_TITLE AS TEN_MUC,
               s.NAM AS TRAI_NAM, s.NU AS TRAI_NU, s.TONG AS TRAI_TONG,
               CAST(NULL AS NVARCHAR2(200)) AS GHI_CHU
        FROM S_ROWS s
        UNION ALL
        SELECT 100, 'III', u'GI\1ea2M C\00d3 TH\1edcI H\1ea0N', i.NAM, i.NU, i.TONG,
               CAST(NULL AS NVARCHAR2(200))
        FROM III_TOT i
        UNION ALL
        -- [S?A 3] Nhãn = MTG_TITLE (b?n c?: TO_CHAR(MTG_THANG) || ' tháng').
        --         NVL(MTG_THANG, 0) ?? dòng theo NGÀY (THANG = NULL) nh?n THU_TU = 224 n?m ngay sau
        --         các dòng tháng, KHÔNG b? NULL ??y xu?ng cu?i b?ng sau c? dòng T?NG S?.
        SELECT 200 + (24 - NVL(t.MTG_THANG, 0)), 'M', t.MTG_TITLE, t.NAM, t.NU, t.TONG,
               CAST(NULL AS NVARCHAR2(200))
        FROM THANG t
        UNION ALL
        SELECT 900, 'X', u'CH\01afA PH\00c2N LO\1ea0I: ' || TEN, NAM, NU, TONG,
               CAST(NULL AS NVARCHAR2(200))
        FROM X_ROWS
        UNION ALL
        SELECT 999, 'T', u'T\1ed4NG S\1ed0',
               s.NAM + i.NAM, s.NU + i.NU, s.TONG + i.TONG,
               CAST(NULL AS NVARCHAR2(200))
        FROM S_TOT s CROSS JOIN III_TOT i
    )
    ORDER BY THU_TU, TEN_MUC;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i SP_TK_C10_MUC_XET_GIAM: ' || SQLERRM);
END;


/
--------------------------------------------------------
--  DDL for Procedure SP_TK_PHAM_NHAN_RA_TRAI_THEO_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_TK_PHAM_NHAN_RA_TRAI_THEO_TRAI" (
    p_tu_ngay  IN DATE,
    p_den_ngay IN DATE
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
        SELECT dtg.TG_TEN AS TG_TEN,
               COUNT(DISTINCT CASE WHEN TRIM(dgt.GT_TEN) = u'Nam' THEN pktrt.KTRT_PN_LAI_LICH_ID END) AS NAM,
               COUNT(DISTINCT CASE WHEN TRIM(dgt.GT_TEN) = u'N\1eef'  THEN pktrt.KTRT_PN_LAI_LICH_ID END) AS NU,
               COUNT(DISTINCT CASE WHEN TRIM(dgt.GT_TEN) = u'Nam' THEN pktrt.KTRT_PN_LAI_LICH_ID END)
             + COUNT(DISTINCT CASE WHEN TRIM(dgt.GT_TEN) = u'N\1eef'  THEN pktrt.KTRT_PN_LAI_LICH_ID END) AS TONG_SO
          FROM DM_TRAI_GIAMS dtg
          JOIN PN_LAI_LICHS pll
            ON pll.LL_TRAI_GIAM_ID = dtg.ID
           AND NVL(pll.IS_DELETED, 0) = 0
              AND NVL(pll.LL_LA_BAN_DONG_BANG, 0) = 0
          JOIN PN_KET_THUC_RA_TRAIS pktrt
            ON pktrt.KTRT_PN_LAI_LICH_ID = pll.ID
           AND NVL(pktrt.IS_DELETED, 0) = 0
          LEFT JOIN DM_GIOI_TINHS dgt
            ON dgt.ID = pll.LL_DM_GIOI_TINH_ID
           AND NVL(dgt.IS_DELETED, 0) = 0
         WHERE dtg.TG_TRANG_THAI = 1                                   -- bool ? NUMBER(1), DmTraiGiam.cs:33
           AND dtg.TG_TEN LIKE u'%Tr\1ea1i giam%'
           -- Biên ?óng c? hai ??u; TRUNC ??t trên THAM S?, không trên c?t (index v?n dùng ???c).
           -- KHÔNG "chu?n hoá" thành < p_den_ngay: b?n ghi 23:30 ngày cu?i ph?i ???c tính (AC-03).
           AND pktrt.KTRT_NGAY_THA >= TRUNC(p_tu_ngay)
           AND pktrt.KTRT_NGAY_THA <  TRUNC(p_den_ngay) + 1
         GROUP BY dtg.ID, dtg.TG_TEN
         ORDER BY dtg.TG_TEN ASC, dtg.ID ASC;                          -- AC-11: tie-break xác ??nh

    DBMS_SQL.RETURN_RESULT(C1);
END SP_TK_PHAM_NHAN_RA_TRAI_THEO_TRAI;


/
--------------------------------------------------------
--  DDL for Procedure SP_TK_RA_TRAI_THEO_PHAN_DOI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_TK_RA_TRAI_THEO_PHAN_DOI" (
    p_ma_trai_giam  IN VARCHAR2  DEFAULT NULL,
    p_phan_doi_id   IN NUMBER    DEFAULT NULL,
    p_tu_ngay       IN DATE      DEFAULT NULL,
    p_den_ngay      IN DATE      DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    /* DM_TRUONG_HOP_THAS.THT_MA (d? li?u QLPN):
       20 Ra tr?i; 21 Ch?p hành xong hình ph?t tù; 22 Gi?m h?t th?i h?n; 23 ??c xá;
       24 Trích xu?t h?t án; 25 Tr? t? do; 26 Tha tr??c th?i h?n có ?i?u ki?n.
       Th?ng kê ba c?t bi?u m?u: 21 / 22 / 23.
       Gi?i tính: DM_GIOI_TINHS.GT_MA — 1 = Nam, 2 = N?, còn l?i = Khác. */
    OPEN c1 FOR
        SELECT
            ROW_NUMBER() OVER (ORDER BY x.don_vi) AS "Stt",
            x.don_vi AS "DonVi",

            -- THT_MA = 21 — Ch?p hành xong hình ph?t tù
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '21'
                 AND x.gt_ma = '1' THEN x.ll_id
            END) AS "ChxhptNam",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '21'
                 AND x.gt_ma = '2' THEN x.ll_id
            END) AS "ChxhptNu",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '21'
                 AND (x.gt_ma IS NULL OR x.gt_ma NOT IN ('1', '2')) THEN x.ll_id
            END) AS "ChxhptKhac",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '21' THEN x.ll_id
            END) AS "ChxhptTong",

            -- THT_MA = 22 — Gi?m h?t th?i h?n
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '22'
                 AND x.gt_ma = '1' THEN x.ll_id
            END) AS "GhthNam",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '22'
                 AND x.gt_ma = '2' THEN x.ll_id
            END) AS "GhthNu",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '22'
                 AND (x.gt_ma IS NULL OR x.gt_ma NOT IN ('1', '2')) THEN x.ll_id
            END) AS "GhthKhac",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '22' THEN x.ll_id
            END) AS "GhthTong",

            -- THT_MA = 23 — ??c xá
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '23'
                 AND x.gt_ma = '1' THEN x.ll_id
            END) AS "DacXaNam",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '23'
                 AND x.gt_ma = '2' THEN x.ll_id
            END) AS "DacXaNu",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '23'
                 AND (x.gt_ma IS NULL OR x.gt_ma NOT IN ('1', '2')) THEN x.ll_id
            END) AS "DacXaKhac",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '23' THEN x.ll_id
            END) AS "DacXaTong"

        FROM (
            SELECT
                ll.ID AS ll_id,
                NVL(TRIM(CAST(dpd.PD_TEN AS NVARCHAR2(500))), u'')
                    || CASE
                        WHEN TRIM(NVL(CAST(dpd.PD_TEN AS NVARCHAR2(500)), u'')) IS NOT NULL
                         AND LENGTH(TRIM(NVL(CAST(dpd.PD_TEN AS NVARCHAR2(500)), u''))) > 0
                         AND TRIM(NVL(CAST(dpt.PT_TEN AS NVARCHAR2(500)), u'')) IS NOT NULL
                         AND LENGTH(TRIM(NVL(CAST(dpt.PT_TEN AS NVARCHAR2(500)), u''))) > 0
                        THEN u', '
                        ELSE u''
                       END
                    || NVL(TRIM(CAST(dpt.PT_TEN AS NVARCHAR2(500))), u'') AS don_vi,
                TRIM(UPPER(NVL(TO_CHAR(dtht.THT_MA), ''))) AS tht_ma_u,
                NULLIF(TRIM(CAST(NVL(dgt.GT_MA, '') AS VARCHAR2(50))), '') AS gt_ma
            FROM PN_KET_THUC_RA_TRAIS ktrt
            LEFT JOIN PN_LAI_LICHS ll
                ON ktrt.KTRT_PN_LAI_LICH_ID = ll.ID
            LEFT JOIN DM_GIOI_TINHS dgt
                ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
               AND NVL(dgt.IS_DELETED, 0) = 0
            LEFT JOIN DM_TRUONG_HOP_THAS dtht
                ON ktrt.KTRT_TRUONG_HOP_THA_ID = dtht.ID
               AND NVL(dtht.IS_DELETED, 0) = 0
            LEFT JOIN DM_PHAN_DOIS dpd
                ON ll.LL_PHAN_DOI_ID = dpd.ID
               AND NVL(dpd.IS_DELETED, 0) = 0
            LEFT JOIN DM_PHAN_TRAIS dpt
                ON ll.LL_PHAN_TRAI_ID = dpt.ID
               AND NVL(dpt.IS_DELETED, 0) = 0
            LEFT JOIN DM_TRAI_GIAMS tg
                ON ll.LL_TRAI_GIAM_ID = tg.ID
               AND NVL(tg.IS_DELETED, 0) = 0
            WHERE NVL(ktrt.IS_DELETED, 0) = 0
              AND NVL(ll.IS_DELETED, 0) = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
              AND (p_ma_trai_giam IS NULL OR tg.TG_MA = p_ma_trai_giam)
              AND (p_phan_doi_id  IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
              AND (p_tu_ngay      IS NULL OR ktrt.KTRT_NGAY_THA >= p_tu_ngay)
              AND (p_den_ngay     IS NULL OR ktrt.KTRT_NGAY_THA <= p_den_ngay)
              AND TRIM(UPPER(NVL(TO_CHAR(dtht.THT_MA), ''))) IN ('21', '22', '23')
        ) x
        GROUP BY x.don_vi
        ORDER BY x.don_vi;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, u'L\1ed7i SP_TK_RA_TRAI_THEO_PHAN_DOI: ' || SQLERRM);
END SP_TK_RA_TRAI_THEO_PHAN_DOI;


/
--------------------------------------------------------
--  DDL for Procedure SP_TK_RA_TRAI_THEO_PHAN_TRAI
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_TK_RA_TRAI_THEO_PHAN_TRAI" (
    p_ma_trai_giam  IN VARCHAR2  DEFAULT NULL,
    p_phan_doi_id   IN NUMBER    DEFAULT NULL,
    p_tu_ngay       IN DATE      DEFAULT NULL,
    p_den_ngay      IN DATE      DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    /* DM_TRUONG_HOP_THAS.THT_MA (gi?ng SP_TK_RA_TRAI_THEO_PHAN_DOI):
       20 Ra tr?i; 21 Ch?p hành xong hình ph?t tù; 22 Gi?m h?t th?i h?n; 23 ??c xá;
       24 Trích xu?t h?t án; 25 Tr? t? do; 26 Tha tr??c th?i h?n có ?i?u ki?n.
       Th?ng kê ba c?t bi?u m?u: 21 / 22 / 23.
       Gi?i tính: DM_GIOI_TINHS.GT_MA — 1 = Nam, 2 = N?, còn l?i = Khác.
       DonVi: ch? DM_PHAN_TRAIS.PT_TEN (phân tr?i). */
    OPEN c1 FOR
        SELECT
            ROW_NUMBER() OVER (ORDER BY x.don_vi) AS "Stt",
            x.don_vi AS "DonVi",

            -- THT_MA = 21 — Ch?p hành xong hình ph?t tù
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '21'
                 AND x.gt_ma = '1' THEN x.ll_id
            END) AS "ChxhptNam",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '21'
                 AND x.gt_ma = '2' THEN x.ll_id
            END) AS "ChxhptNu",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '21'
                 AND (x.gt_ma IS NULL OR x.gt_ma NOT IN ('1', '2')) THEN x.ll_id
            END) AS "ChxhptKhac",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '21' THEN x.ll_id
            END) AS "ChxhptTong",

            -- THT_MA = 22 — Gi?m h?t th?i h?n
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '22'
                 AND x.gt_ma = '1' THEN x.ll_id
            END) AS "GhthNam",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '22'
                 AND x.gt_ma = '2' THEN x.ll_id
            END) AS "GhthNu",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '22'
                 AND (x.gt_ma IS NULL OR x.gt_ma NOT IN ('1', '2')) THEN x.ll_id
            END) AS "GhthKhac",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '22' THEN x.ll_id
            END) AS "GhthTong",

            -- THT_MA = 23 — ??c xá
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '23'
                 AND x.gt_ma = '1' THEN x.ll_id
            END) AS "DacXaNam",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '23'
                 AND x.gt_ma = '2' THEN x.ll_id
            END) AS "DacXaNu",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '23'
                 AND (x.gt_ma IS NULL OR x.gt_ma NOT IN ('1', '2')) THEN x.ll_id
            END) AS "DacXaKhac",
            COUNT(DISTINCT CASE
                WHEN x.tht_ma_u = '23' THEN x.ll_id
            END) AS "DacXaTong"

        FROM (
            SELECT
                ll.ID AS ll_id,
                NVL(TRIM(CAST(dpt.PT_TEN AS NVARCHAR2(500))), u'') AS don_vi,
                TRIM(UPPER(NVL(TO_CHAR(dtht.THT_MA), ''))) AS tht_ma_u,
                NULLIF(TRIM(CAST(NVL(dgt.GT_MA, '') AS VARCHAR2(50))), '') AS gt_ma
            FROM PN_KET_THUC_RA_TRAIS ktrt
            LEFT JOIN PN_LAI_LICHS ll
                ON ktrt.KTRT_PN_LAI_LICH_ID = ll.ID
            LEFT JOIN DM_GIOI_TINHS dgt
                ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
               AND NVL(dgt.IS_DELETED, 0) = 0
            LEFT JOIN DM_TRUONG_HOP_THAS dtht
                ON ktrt.KTRT_TRUONG_HOP_THA_ID = dtht.ID
               AND NVL(dtht.IS_DELETED, 0) = 0
            LEFT JOIN DM_PHAN_TRAIS dpt
                ON ll.LL_PHAN_TRAI_ID = dpt.ID
               AND NVL(dpt.IS_DELETED, 0) = 0
            LEFT JOIN DM_TRAI_GIAMS tg
                ON ll.LL_TRAI_GIAM_ID = tg.ID
               AND NVL(tg.IS_DELETED, 0) = 0
            WHERE NVL(ktrt.IS_DELETED, 0) = 0
              AND NVL(ll.IS_DELETED, 0) = 0
              AND NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
              AND (p_ma_trai_giam IS NULL OR tg.TG_MA = p_ma_trai_giam)
              AND (p_phan_doi_id  IS NULL OR ll.LL_PHAN_DOI_ID = p_phan_doi_id)
              AND (p_tu_ngay      IS NULL OR ktrt.KTRT_NGAY_THA >= p_tu_ngay)
              AND (p_den_ngay     IS NULL OR ktrt.KTRT_NGAY_THA <  p_den_ngay + 1)
              AND TRIM(UPPER(NVL(TO_CHAR(dtht.THT_MA), ''))) IN ('21', '22', '23')
        ) x
        GROUP BY x.don_vi
        ORDER BY x.don_vi;

    DBMS_SQL.RETURN_RESULT(c1);
EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, u'L\1ed7i SP_TK_RA_TRAI_THEO_PHAN_TRAI: ' || SQLERRM);
END SP_TK_RA_TRAI_THEO_PHAN_TRAI;


/
--------------------------------------------------------
--  DDL for Procedure SP_TONG_HOP_TIEN_HOA_NHAP_CONG_DONG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_TONG_HOP_TIEN_HOA_NHAP_CONG_DONG" (
    p_tu_nam IN NVARCHAR2 DEFAULT '',
    p_den_nam IN NVARCHAR2 DEFAULT '',
    p_pham_nhan_id IN NVARCHAR2 DEFAULT ''
) AS
    v_tu_nam NUMBER;
    v_den_nam NUMBER;
    v_pham_nhan_id NUMBER;
    c1 SYS_REFCURSOR;
BEGIN

--    begin
--        SP_TONG_HOP_TIEN_HOA_NHAP_CONG_DONG('', '', '');
--    end;

    -- X? lý default value cho t? n?m
    IF p_tu_nam IS NULL OR TRIM(p_tu_nam) = '' THEN
        v_tu_nam := NULL;
    ELSE
        v_tu_nam := TO_NUMBER(TRIM(p_tu_nam));
    END IF;

    -- X? lý default value cho ??n n?m
    IF p_den_nam IS NULL OR TRIM(p_den_nam) = '' THEN
        v_den_nam := NULL;
    ELSE
        v_den_nam := TO_NUMBER(TRIM(p_den_nam));
    END IF;

    -- X? lý default value cho ph?m nhân ID
    IF p_pham_nhan_id IS NULL OR TRIM(p_pham_nhan_id) = '' THEN
        v_pham_nhan_id := NULL;
    ELSE
        v_pham_nhan_id := TO_NUMBER(TRIM(p_pham_nhan_id));
    END IF;

    -- Debug output
    DBMS_OUTPUT.PUT_LINE('T?ng h?p ti?n hòa nh?p c?ng ??ng theo quý/n?m');
    DBMS_OUTPUT.PUT_LINE('T? n?m: ' || NVL(TO_CHAR(v_tu_nam), 'Không gi?i h?n'));
    DBMS_OUTPUT.PUT_LINE('??n n?m: ' || NVL(TO_CHAR(v_den_nam), 'Không gi?i h?n'));
    DBMS_OUTPUT.PUT_LINE('Ph?m nhân ID: ' || NVL(TO_CHAR(v_pham_nhan_id), 'T?t c?'));

    -- M? cursor: t?ng h?p theo ID ph?m nhân và n?m, ROLLUP thêm 1 dòng t?ng ti?n m?i PHAM_NHAN_ID
    OPEN c1 FOR
        SELECT
            t.PHAM_NHAN_ID,
            t.NAM AS NAM,
--            CASE
--                WHEN GROUPING(t.PHAM_NHAN_ID) = 1 THEN N'T?ng c?ng'
--                WHEN GROUPING(t.NAM) = 1 THEN N'T?ng theo PN'
--                ELSE N'Chi ti?t'
--            END AS LOAI_DONG,
            -- Quý 1
            NULL AS QUY1_XEP_LOAI,
            SUM(NVL(t.TIEN_Q1, 0)) AS QUY1_TIEN,
            -- Quý 2
            NULL AS QUY2_XEP_LOAI,
            SUM(NVL(t.TIEN_Q2, 0)) AS QUY2_TIEN,
            -- Quý 3
            NULL AS QUY3_XEP_LOAI,
            SUM(NVL(t.TIEN_Q3, 0)) AS QUY3_TIEN,
            -- Quý 4
            NULL AS QUY4_XEP_LOAI,
            SUM(NVL(t.TIEN_Q4, 0)) AS QUY4_TIEN,
            -- T?ng s? ti?n/n?m ho?c t?ng theo PN (?)
            SUM(NVL(t.TIEN_Q1, 0) + NVL(t.TIEN_Q2, 0) + NVL(t.TIEN_Q3, 0) + NVL(t.TIEN_Q4, 0)) AS TONG_TIEN_NAM
        FROM TIEN_LAO_DONG_SAN_XUATS t
        WHERE t.IS_DELETED = 0
          AND t.NAM IS NOT NULL
          AND (v_tu_nam IS NULL OR t.NAM >= v_tu_nam)
          AND (v_den_nam IS NULL OR t.NAM <= v_den_nam)
          AND (v_pham_nhan_id IS NULL OR t.PHAM_NHAN_ID = v_pham_nhan_id)
        GROUP BY ROLLUP(t.PHAM_NHAN_ID, t.NAM)
        ORDER BY t.PHAM_NHAN_ID NULLS LAST, t.NAM NULLS LAST;

    DBMS_SQL.RETURN_RESULT(c1);

EXCEPTION
    WHEN OTHERS THEN
        RAISE_APPLICATION_ERROR(-20001, 'L?i t?ng h?p ti?n hòa nh?p c?ng ??ng: ' || SQLERRM);
END SP_TONG_HOP_TIEN_HOA_NHAP_CONG_DONG;








/
--------------------------------------------------------
--  DDL for Procedure SP_XET_DU_DIEU_KIEN_GTH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_XET_DU_DIEU_KIEN_GTH" (
    p_ky_giam_id   IN NUMBER,
    p_ma_trai_giam IN VARCHAR2,
    p_thong_bao    OUT VARCHAR2
)
AS
    v_dieu_kien_id      NUMBER;
    v_ngay_xet          DATE;
    v_trai_giam_id      NUMBER;
    v_count_deleted     NUMBER := 0;
    v_count_inserted    NUMBER := 0;
    v_count_ct          NUMBER := 0;
    v_error_msg         VARCHAR2(4000);

BEGIN
    -- B??c 0: Resolve mã tr?i giam ? ID
    BEGIN
        SELECT ID
          INTO v_trai_giam_id
          FROM DM_TRAI_GIAMS
         WHERE TG_MA = p_ma_trai_giam
           AND NVL(IS_DELETED, 0) = 0
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            p_thong_bao := '[L?I - B??c 0] Không tìm th?y tr?i giam mã: ' || p_ma_trai_giam;
            RETURN;
    END;

    -- B??c 1: L?y ?i?u ki?n ID + ngày xét
    BEGIN
        SELECT dk.ID, CAST(kg.KGTH_NGAY_XET_GIAM AS DATE)
          INTO v_dieu_kien_id, v_ngay_xet
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS dk
          JOIN GTH_KY_GIAM_THOI_HANS kg ON kg.ID = p_ky_giam_id
         WHERE dk.GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
           AND dk.IS_DELETED = 0
           AND kg.IS_DELETED = 0
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            p_thong_bao := '[L?I - B??c 1] Không tìm th?y k? gi?m ID: ' || p_ky_giam_id;
            RETURN;
    END;

    -- B??c 2: Xóa b?n ghi c? (c? 2 b?ng)
    DELETE FROM GTH_DU_DIEU_KIEN_GIAM_THOI_HANS
     WHERE GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
       AND IS_DELETED = 0;
    v_count_deleted := SQL%ROWCOUNT;

    DELETE FROM GTH_DU_DIEU_KIEN_CHI_TIETS
     WHERE DDKCT_KY_ID = p_ky_giam_id;

    -- B??c 3: Insert vào b?ng chính (dùng function _OPT)
    INSERT INTO GTH_DU_DIEU_KIEN_GIAM_THOI_HANS (
        PHAM_NHAN_ID,
        GTH_KY_GIAM_THOI_HAN_ID,
        DIEU_KIEN_THOI_GIAN,
        DIEU_KIEN_XLCT,
        IS_NOP_DU,
        CREATION_TIME,
        IS_DELETED,
        IS_DU_DIEU_KIEN
    )
    WITH cau_hinh AS (
        SELECT
            TGCH_LOAI_DOI_TUONG,
            TGCH_TRUONG_HOP_DAC_BIET,
            TGCH_DOI_TUONG_THONG_THUONG
          FROM GTH_THOI_GIAN_CHAP_HANHS
         WHERE GTH_DIEU_KIEN_GIAM_THOI_HAN_ID = v_dieu_kien_id
           AND IS_DELETED = 0
    ),
    pham_nhan_base AS (
        SELECT
            ll.ID                                                         AS PHAM_NHAN_ID,
            ptha.THA_AN_PHAT                                              AS AN_PHAT_TEXT,
            FN_PARSE_AN_PHAT_TO_NGAY(ptha.THA_AN_PHAT)                   AS TONG_NGAY_AN,
            FN_GET_DA_CHAP_HANH_THEO_NGAY(ll.ID, v_ngay_xet)            AS DA_CHAP_HANH,
            -- DÙNG _OPT: truy?n thêm v_trai_giam_id
            FN_IS_TRUONG_HOP_DAC_BIET_OPT(ll.ID, p_ky_giam_id, v_trai_giam_id) AS IS_DAC_BIET
          FROM PN_LAI_LICHS ll
          JOIN (
              SELECT THA_PNLAI_LICH_ID, THA_AN_PHAT, THA_NGAY_BAT, THA_NGAY_HET_HAN,
                     ROW_NUMBER() OVER (
                         PARTITION BY THA_PNLAI_LICH_ID
                         ORDER BY NVL(THA_NGAY_BAN_AN, DATE '1900-01-01') DESC, ID DESC
                     ) AS rn
                FROM PN_THI_HANH_AN
               WHERE NVL(IS_DELETED, 0) = 0
                 AND THA_NGAY_BAT IS NOT NULL
          ) ptha ON ptha.THA_PNLAI_LICH_ID = ll.ID AND ptha.rn = 1
          JOIN DM_TINH_TRANG_PHAM_NHANS dttph
            ON ll.LL_TINH_TRANG_ID = dttph.ID
         WHERE ll.IS_DELETED = 0
           AND ll.LL_TRAI_GIAM_ID = v_trai_giam_id
           AND (ptha.THA_NGAY_HET_HAN IS NULL
                OR CAST(ptha.THA_NGAY_HET_HAN AS DATE) >= v_ngay_xet)
           AND (
               dttph.TTPN_MA IN ('111','112','113','114')
               OR
               (
                   dttph.TTPN_MA IN ('141','142')
                   AND EXISTS (
                       SELECT 1
                         FROM TRICH_XUATS tx
                         JOIN DM_LY_DO_TRICH_XUATS ldtx
                           ON ldtx.ID = tx.TX_LY_DO_ID
                          AND NVL(ldtx.IS_DELETED, 0) = 0
                        WHERE tx.PHAM_NHAN_ID = ll.ID
                          AND NVL(tx.IS_DELETED, 0) = 0
                          AND ldtx.LDTX_MA IN ('50', '51', '93')
                          AND (tx.TX_NGAY_TRA IS NULL
                               OR CAST(tx.TX_NGAY_TRA AS DATE) > v_ngay_xet)
                   )
               )
           )
    ),
    pham_nhan_voi_nguong AS (
        SELECT
            pb.PHAM_NHAN_ID, pb.AN_PHAT_TEXT, pb.TONG_NGAY_AN,
            pb.DA_CHAP_HANH, pb.IS_DAC_BIET,
            FN_PARSE_NGUONG(pb.AN_PHAT_TEXT,
                FN_GET_NGUONG_TGCH(pb.PHAM_NHAN_ID, p_ky_giam_id,
                                   pb.IS_DAC_BIET, pb.AN_PHAT_TEXT)) AS NGUONG_TGCH,
            -- DÙNG _OPT: truy?n thêm v_trai_giam_id
            FN_XET_DU_DIEU_KIEN_QUY_OPT(pb.PHAM_NHAN_ID, p_ky_giam_id, v_trai_giam_id).DU_DIEU_KIEN AS IS_DU_QUY,
            FN_TINH_TONG_AN_GIAM(pb.PHAM_NHAN_ID)                    AS DA_GIAM
          FROM pham_nhan_base pb
          JOIN cau_hinh ch ON (
              (ch.TGCH_LOAI_DOI_TUONG LIKE '%th?i h?n%' AND pb.TONG_NGAY_AN >  0)
              OR (ch.TGCH_LOAI_DOI_TUONG LIKE '%Chung th%' AND pb.TONG_NGAY_AN = -1)
          )
    ),
    pham_nhan_voi_co_tgch AS (
        SELECT pn.*,
               FN_YMD_GTE(pn.DA_CHAP_HANH, pn.NGUONG_TGCH) AS IS_DU_TGCH,
               FN_TINH_CON_LAI(pn.AN_PHAT_TEXT, pn.DA_GIAM,
                                pn.DA_CHAP_HANH)             AS CON_LAI_YMD
          FROM pham_nhan_voi_nguong pn
    ),
    pham_nhan_voi_trang_thai AS (
        SELECT
            pn.PHAM_NHAN_ID, pn.IS_DU_TGCH, pn.IS_DU_QUY, pn.IS_DAC_BIET,
            CASE
                WHEN pn.IS_DU_TGCH = 0 THEN TO_NCHAR('Không ?? ?K v? th?i gian')
                -- DÙNG _OPT: truy?n thêm v_trai_giam_id
                ELSE FN_DIEU_KIEN_THOI_GIAN_OPT(pn.PHAM_NHAN_ID, v_ngay_xet, pn.IS_DAC_BIET, v_trai_giam_id)
            END                                                          AS TRANG_THAI_TG,
            -- DÙNG _OPT: truy?n thêm v_trai_giam_id
            FN_DIEU_KIEN_XLCT(pn.PHAM_NHAN_ID, p_ky_giam_id,
                               pn.IS_DAC_BIET)                          AS TRANG_THAI_XLCT,
            FN_XET_DU_DIEU_KIEN_HPBS(pn.PHAM_NHAN_ID,
                                      v_dieu_kien_id)                  AS IS_NOP_DU
          FROM pham_nhan_voi_co_tgch pn
    ),
    pham_nhan_final AS (
        SELECT /*+ MATERIALIZE */
            PHAM_NHAN_ID, IS_DU_TGCH, IS_DU_QUY,
            TRANG_THAI_TG, TRANG_THAI_XLCT, IS_NOP_DU
          FROM pham_nhan_voi_trang_thai
    )
    SELECT
        pf.PHAM_NHAN_ID,
        p_ky_giam_id,
        pf.TRANG_THAI_TG,
        pf.TRANG_THAI_XLCT,
        pf.IS_NOP_DU,
        SYSTIMESTAMP,
        0,
        CASE
            WHEN pf.TRANG_THAI_TG   <> TO_NCHAR('Không ?? ?K v? th?i gian')
             AND pf.TRANG_THAI_XLCT <> TO_NCHAR('Không ?? ?K x?p lo?i')
             AND pf.IS_NOP_DU        = 1 THEN 1
            ELSE 0
        END
      FROM pham_nhan_final pf;

    v_count_inserted := SQL%ROWCOUNT;

    -- B??c 4: Insert vào b?ng chi ti?t (logic y h?t b?n g?c)
    INSERT INTO GTH_DU_DIEU_KIEN_CHI_TIETS (
        DDKCT_KY_ID,
        DDKCT_PN_ID,
        DDKCT_HO_TEN,
        DDKCT_GIOI_TINH,
        DDKCT_NGAY_SINH, 
        DDKCT_NOI_DKTT,
        DDKCT_SO_TIEN_AN,
        DDKCT_TOI_DANH,
        DDKCT_AN_PHAT,
        DDKCT_THOI_GIAN_DA_GIAM,
        DDKCT_THOI_GIAN_DA_CHAP_HANH,
        DDKCT_THOI_GIAN_CON_LAI,
        DDKCT_PHAN_DOI,
        DDKCT_PHAN_DOI_ID,
        DDKCT_HET_HAN,
        DDKCT_DIEU_KIEN_THOI_GIAN,
        DDKCT_DIEUKIEN_THOI_GIAN_ID,
        DDKCT_DIEU_KIEN_XLCT,
        DDKCT_DIEU_KIEN_XLCT_ID,
        DDKCT_DOI_TUONG_ID,
        DDKCT_MUC_AN_PHAT_ID,
        DDKCT_TINH_TRANG_ID,
        DDKCT_QUOC_TICH_ID,
        DDKCT_IS_DU_DIEU_KIEN,
        DDKCT_IS_NOP_DU,
        CREATION_TIME,
        IS_DELETED,
        DDKCT_GHI_CHU,
        MA_TRAI_GIAM,
        DDKCT_NGAY_BAT,
        DDKCT_NGAY_DEN_TRAI,
        DDKCT_LL_GHI_CHU
    )
    WITH
    dk_data AS (
        SELECT /*+ MATERIALIZE */
            gdd.PHAM_NHAN_ID,
            gdd.DIEU_KIEN_THOI_GIAN,
            gdd.DIEU_KIEN_XLCT,
            gdd.IS_DU_DIEU_KIEN,
            gdd.IS_NOP_DU
          FROM GTH_DU_DIEU_KIEN_GIAM_THOI_HANS gdd
         WHERE gdd.GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
           AND gdd.IS_DELETED = 0
    ),
    da_giam_chi_tiet_data AS (
        SELECT /*+ MATERIALIZE */
            dk.PHAM_NHAN_ID,
            QLPN.FN_TINH_AN_DA_GIAM_CHI_TIET_GTH(dk.PHAM_NHAN_ID,v_ngay_xet) AS DA_GIAM_TEXT
          FROM dk_data dk
    ),
    dk_quy_obj_data AS (
        SELECT /*+ MATERIALIZE */
            dk.PHAM_NHAN_ID,
            -- DÙNG _OPT
            QLPN.FN_XET_DU_DIEU_KIEN_QUY_OPT(dk.PHAM_NHAN_ID, p_ky_giam_id, v_trai_giam_id) AS DK_OBJ
          FROM dk_data dk
    ),
    da_chap_hanh_data AS (
        SELECT /*+ MATERIALIZE */
            dk.PHAM_NHAN_ID,
            QLPN.FN_GET_DA_CHAP_HANH_THEO_NGAY(dk.PHAM_NHAN_ID, v_ngay_xet) AS DA_CH_OBJ
          FROM dk_data dk
    ),
    con_lai_data AS (
        SELECT /*+ MATERIALIZE */
            dk.PHAM_NHAN_ID,
            QLPN.FN_TINH_THOI_GIAN_CON_LAI(dk.PHAM_NHAN_ID, v_ngay_xet) AS CON_LAI_TEXT
          FROM dk_data dk
    ),
    toi_danh_split AS (
        SELECT /*+ MATERIALIZE */
            ptha.THA_PNLAI_LICH_ID AS PHAM_NHAN_ID,
            TO_NUMBER(TRIM(REGEXP_SUBSTR(
                REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
                '[^,]+', 1, LEVEL
            ))) AS TOI_DANH_ID
          FROM PN_THI_HANH_AN ptha
          JOIN dk_data dk ON dk.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID
         WHERE NVL(ptha.IS_DELETED, 0) = 0
           AND ptha.THA_TOI_DANH IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                       REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
               AND PRIOR ptha.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    toi_danh_agg AS (
        SELECT /*+ MATERIALIZE */
            s.PHAM_NHAN_ID,
            LISTAGG(td.TD_TEN, '; ')
                WITHIN GROUP (ORDER BY td.TD_TEN) AS TOI_DANH_TEXT
          FROM toi_danh_split s
          JOIN DM_TOI_DANHS td
            ON td.ID = s.TOI_DANH_ID
           AND NVL(td.IS_DELETED, 0) = 0
         GROUP BY s.PHAM_NHAN_ID
    ),
    tong_an_giam AS (
        SELECT /*+ MATERIALIZE */
            raw1.PHAM_NHAN_ID,
            FLOOR(SUM(raw1.tong_ngay) / 365)          AS TONG_NAM,
            FLOOR(MOD(SUM(raw1.tong_ngay), 365) / 30) AS TONG_THANG,
            MOD(MOD(SUM(raw1.tong_ngay), 365), 30)    AS TONG_NGAY
          FROM (
              SELECT gth.PHAM_NHAN_ID,
                     NVL(QLPN.FN_PARSE_AN_PHAT_TO_YMD(dmtg.MTG_TITLE).nam,   0) * 365 +
                     NVL(QLPN.FN_PARSE_AN_PHAT_TO_YMD(dmtg.MTG_TITLE).thang, 0) * 30  +
                     NVL(QLPN.FN_PARSE_AN_PHAT_TO_YMD(dmtg.MTG_TITLE).ngay,  0)       AS tong_ngay
                FROM GIAM_THOI_HANS gth
                JOIN DM_MA_THOI_GIANS dmtg
                  ON dmtg.ID = gth.MUC_GIAM_ID
                 AND NVL(dmtg.IS_DELETED, 0) = 0
                 AND dmtg.MTG_MA NOT IN ('921000','912000','911000','922000')
                JOIN dk_data dk ON dk.PHAM_NHAN_ID = gth.PHAM_NHAN_ID
               WHERE gth.IS_DELETED = 0
          ) raw1
         GROUP BY raw1.PHAM_NHAN_ID
    ),
    doi_tuong_data AS (
        SELECT /*+ MATERIALIZE */
            s.PHAM_NHAN_ID,
            CASE WHEN COUNT(CASE WHEN td.TD_CHUONG = '13' THEN 1 END) > 0
                 THEN 1 ELSE 2
            END AS DOI_TUONG_ID
          FROM toi_danh_split s
          JOIN DM_TOI_DANHS td
            ON td.ID = s.TOI_DANH_ID
           AND NVL(td.IS_DELETED, 0) = 0
         GROUP BY s.PHAM_NHAN_ID
    ),
    latest_tha AS (
        SELECT /*+ MATERIALIZE */
            THA_PNLAI_LICH_ID,
            THA_AN_PHAT,
            THA_NGAY_HET_HAN,
            THA_NGAY_BAT,
            THA_NGAY_DEN_TRAI,
            ROW_NUMBER() OVER (
                PARTITION BY THA_PNLAI_LICH_ID
                ORDER BY NVL(THA_NGAY_BAN_AN, DATE '1900-01-01') DESC, ID DESC
            ) AS rn
          FROM PN_THI_HANH_AN
         WHERE NVL(IS_DELETED, 0) = 0
           AND THA_PNLAI_LICH_ID IN (SELECT PHAM_NHAN_ID FROM dk_data)
    ),
    chi_tiet AS (
        SELECT /*+ MATERIALIZE */
            dk.PHAM_NHAN_ID,
            ll.LL_HO_TEN,
            dgt.GT_TEN                                            AS GIOI_TINH,
            ll.LL_NGAY_SINH,
            CASE
                WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                  OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                  OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
                THEN TRIM(
                    NVL(NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u''), u'')
                    || CASE
                        WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
                            CASE
                                WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                    THEN u', ' || dxp_thuong_tru.XP_TEN
                                ELSE dxp_thuong_tru.XP_TEN
                            END
                        ELSE u''
                       END
                    || CASE
                        WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
                            CASE
                                WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
                                  OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
                                    THEN u', ' || dttp_thuong_tru.TTP_TEN
                                ELSE dttp_thuong_tru.TTP_TEN
                            END
                        ELSE u''
                       END
                )
                ELSE NULL
            END                                                   AS LL_DIA_CHI_THUONG_TRU,
            ll.LL_SO_TIEN_AN,
            td_agg.TOI_DANH_TEXT,
            ptha.THA_AN_PHAT,
            tag.TONG_NAM                                          AS DA_GIAM_NAM,
            tag.TONG_THANG                                        AS DA_GIAM_THANG,
            tag.TONG_NGAY                                         AS DA_GIAM_NGAY,
            dch.DA_CH_OBJ,
            cl.CON_LAI_TEXT,
            dgct.DA_GIAM_TEXT,
            dpd.PD_TEN || ', ' || dpt.PT_TEN                     AS PHAN_DOI,
            ll.LL_PHAN_DOI_ID,
            ptha.THA_NGAY_HET_HAN                                 AS HET_HAN,
            dk.DIEU_KIEN_THOI_GIAN,
            dk.DIEU_KIEN_XLCT,
            NVL(dt.DOI_TUONG_ID, 0)                              AS DOI_TUONG_ID,
            NVL(QLPN.FN_GET_MUC_AN_ID_GTH(ptha.THA_AN_PHAT), 0) AS MUC_AN_PHAT_ID,
            ll.LL_TINH_TRANG_ID,
            ll.LL_DM_QUOC_TICH_ID,
            dk.IS_DU_DIEU_KIEN,
            dk.IS_NOP_DU,
            QLPN.FN_GET_GHI_CHU_DIEU_KIEN_QUY(dk.PHAM_NHAN_ID, dko.DK_OBJ) AS GHI_CHU,
            p_ma_trai_giam as MA_TRAI_GIAM,
            ll.LL_GHI_CHU_CHI_TIET AS LL_GHI_CHU,
            TO_CHAR(ptha.THA_NGAY_BAT, 'DD/MM/YYYY') AS NGAY_BAT,
            TO_CHAR(ptha.THA_NGAY_DEN_TRAI, 'DD/MM/YYYY') AS NGAY_DEN_TRAI
          FROM dk_data dk
          JOIN PN_LAI_LICHS ll
            ON ll.ID = dk.PHAM_NHAN_ID
           AND NVL(ll.IS_DELETED, 0) = 0
          LEFT JOIN tong_an_giam tag           ON tag.PHAM_NHAN_ID   = dk.PHAM_NHAN_ID
          LEFT JOIN da_giam_chi_tiet_data dgct  ON dgct.PHAM_NHAN_ID  = dk.PHAM_NHAN_ID
          LEFT JOIN DM_PHAN_TRAIS dpt           ON ll.LL_PHAN_TRAI_ID = dpt.ID
          LEFT JOIN latest_tha ptha
            ON ptha.THA_PNLAI_LICH_ID = dk.PHAM_NHAN_ID
           AND ptha.rn = 1
          LEFT JOIN dk_quy_obj_data dko         ON dko.PHAM_NHAN_ID   = dk.PHAM_NHAN_ID
          LEFT JOIN toi_danh_agg td_agg         ON td_agg.PHAM_NHAN_ID = dk.PHAM_NHAN_ID
          LEFT JOIN doi_tuong_data dt            ON dt.PHAM_NHAN_ID    = dk.PHAM_NHAN_ID
          LEFT JOIN DM_GIOI_TINHS dgt            ON dgt.ID = ll.LL_DM_GIOI_TINH_ID
          LEFT JOIN DM_PHAN_DOIS dpd             ON dpd.ID = ll.LL_PHAN_DOI_ID
          LEFT JOIN da_chap_hanh_data dch        ON dch.PHAM_NHAN_ID   = dk.PHAM_NHAN_ID
          LEFT JOIN con_lai_data cl              ON cl.PHAM_NHAN_ID    = dk.PHAM_NHAN_ID
          LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru
            ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID
           AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0
          LEFT JOIN DM_XA_PHUONG dxp_thuong_tru
            ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID
           AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    )
    SELECT
        p_ky_giam_id,
        ct.PHAM_NHAN_ID,
        ct.LL_HO_TEN,
        ct.GIOI_TINH,
        ct.LL_NGAY_SINH,
        ct.LL_DIA_CHI_THUONG_TRU,
        ct.LL_SO_TIEN_AN,
        ct.TOI_DANH_TEXT,
        ct.THA_AN_PHAT,
        ct.DA_GIAM_TEXT,
        CASE
            WHEN NVL(ct.DA_CH_OBJ.nam,   0) = 0
             AND NVL(ct.DA_CH_OBJ.thang, 0) = 0
             AND NVL(ct.DA_CH_OBJ.ngay,  0) = 0
            THEN TO_NCHAR('Không')
            ELSE TRIM(
                CASE WHEN NVL(ct.DA_CH_OBJ.nam,   0) > 0 THEN TO_CHAR(ct.DA_CH_OBJ.nam)   || u' n\0103m '   ELSE u'' END ||
                CASE WHEN NVL(ct.DA_CH_OBJ.thang, 0) > 0 THEN TO_CHAR(ct.DA_CH_OBJ.thang) || u' th\00e1ng ' ELSE u'' END ||
                CASE WHEN NVL(ct.DA_CH_OBJ.ngay,  0) > 0 THEN TO_CHAR(ct.DA_CH_OBJ.ngay)  || u' ng\00e0y'   ELSE u'' END
            )
        END,
        ct.CON_LAI_TEXT,
        ct.PHAN_DOI,
        ct.LL_PHAN_DOI_ID,
        ct.HET_HAN,
        ct.DIEU_KIEN_THOI_GIAN,
        CASE ct.DIEU_KIEN_THOI_GIAN
            WHEN TO_NCHAR('?? ?K - ?ã gi?m án - ?úng ??t')      THEN 1
            WHEN TO_NCHAR('?? ?K - ?ã gi?m án - ???c ??y ??t')  THEN 2
            WHEN TO_NCHAR('?? ?K - Xét l?n ??u - Thông th??ng') THEN 3
            WHEN TO_NCHAR('?? ?K - Xét l?n ??u - ??c bi?t')     THEN 4
            WHEN TO_NCHAR('Không ?? ?K v? th?i gian')            THEN 5
            ELSE 0
        END,
        ct.DIEU_KIEN_XLCT,
        CASE ct.DIEU_KIEN_XLCT
            WHEN TO_NCHAR('?? ?K - Gi?m l?n ??u (th??ng)')      THEN 1
            WHEN TO_NCHAR('?? ?K - Gi?m l?n ??u (??c bi?t)')    THEN 2
            WHEN TO_NCHAR('?? ?K - Gi?m l?n sau')                THEN 3
            WHEN TO_NCHAR('Không ?? ?K x?p lo?i')                THEN 4
            ELSE 0
        END,
        ct.DOI_TUONG_ID,
        ct.MUC_AN_PHAT_ID,
        ct.LL_TINH_TRANG_ID,
        ct.LL_DM_QUOC_TICH_ID,
        ct.IS_DU_DIEU_KIEN,
        ct.IS_NOP_DU,
        SYSTIMESTAMP,
        0,
        ct.GHI_CHU,
        ct.MA_TRAI_GIAM,
        ct.NGAY_BAT,
        ct.NGAY_DEN_TRAI,
        ct.LL_GHI_CHU
      FROM chi_tiet ct;

    v_count_ct := SQL%ROWCOUNT;

    COMMIT;

    p_thong_bao :=
           '  - THÀNH CÔNG'                                                                        || CHR(10)
        || '  - Tr?i giam    : ' || p_ma_trai_giam || ' (ID: ' || v_trai_giam_id || ')'           || CHR(10)
        || '  - ?i?u ki?n ID : ' || v_dieu_kien_id                                                || CHR(10)
        || '  - Ngày xét     : ' || TO_CHAR(v_ngay_xet, 'DD/MM/YYYY')                            || CHR(10)
        || '  - Xóa          : ' || v_count_deleted  || ' b?n ghi'                               || CHR(10)
        || '  - B?ng chính   : ' || v_count_inserted || ' ph?m nhân'                             || CHR(10)
        || '  - B?ng chi ti?t: ' || v_count_ct       || ' b?n ghi';

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        v_error_msg := SQLERRM;
        p_thong_bao :=
               '  - L?I'                                                                                          || CHR(10)
            || '  - Mã l?i    : ' || SQLCODE                                                                      || CHR(10)
            || '  - Thông báo : ' || v_error_msg                                                                  || CHR(10)
            || '  - Tr?i giam : ' || p_ma_trai_giam || ' (ID: ' || NVL(TO_CHAR(v_trai_giam_id), 'NULL') || ')'   || CHR(10)
            || '  - K? gi?m  : ' || p_ky_giam_id                                                                 || CHR(10)
            || '  - ?i?u ki?n : ' || NVL(TO_CHAR(v_dieu_kien_id), 'NULL')                                        || CHR(10)
            || '  - ?ã xóa   : ' || v_count_deleted  || ' b?n ghi'                                               || CHR(10)
            || '  - ?ã thêm  : ' || v_count_inserted || ' b?n ghi';
        RAISE;
END SP_XET_DU_DIEU_KIEN_GTH;


/
--------------------------------------------------------
--  DDL for Procedure SP_XET_DU_DIEU_KIEN_GTH_OPT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "QLPN"."SP_XET_DU_DIEU_KIEN_GTH_OPT" (
    p_ky_giam_id IN NUMBER,
    p_ma_trai_giam IN VARCHAR2 DEFAULT '90031',
    p_thong_bao  OUT VARCHAR2
)
AS
    v_dieu_kien_id      NUMBER;
    v_ngay_xet          DATE;
    v_count_deleted     NUMBER := 0;
    v_count_inserted    NUMBER := 0;
    v_count_ct          NUMBER := 0;  -- ? thêm
    v_trai_giam_id      NUMBER;
    v_error_msg         VARCHAR2(4000);
	v_dk_quy_obj        QLPN.DIEU_KIEN_QUY_OBJ; 

BEGIN
    BEGIN 
        SELECT ID 
        INTO v_trai_giam_id
        FROM DM_TRAI_GIAMS
        WHERE TG_MA = p_ma_trai_giam;
    END;
    -- B??c 1: L?y ?i?u ki?n ID + ngày xét 
    BEGIN 
        SELECT dk.ID, CAST(kg.KGTH_NGAY_XET_GIAM AS DATE)
          INTO v_dieu_kien_id, v_ngay_xet
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS dk
          JOIN GTH_KY_GIAM_THOI_HANS kg ON kg.ID = p_ky_giam_id
         WHERE dk.GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
           AND dk.IS_DELETED = 0
           AND kg.IS_DELETED = 0
           AND ROWNUM = 1;
        p_thong_bao := '[B??c 1] Tìm th?y ?i?u ki?n ID: ' || v_dieu_kien_id
                    || ' | Ngày xét: ' || TO_CHAR(v_ngay_xet, 'DD/MM/YYYY');
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            p_thong_bao := '[L?I - B??c 1] Không tìm th?y k? gi?m ID: ' || p_ky_giam_id;
            RETURN;
    END;

    -- B??c 2: Xóa b?n ghi c? (c? 2 b?ng)
    DELETE FROM GTH_DU_DIEU_KIEN_GIAM_THOI_HANS
     WHERE GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
       AND IS_DELETED = 0;
    v_count_deleted := SQL%ROWCOUNT;

    DELETE FROM GTH_DU_DIEU_KIEN_CHI_TIETS
    WHERE DDKCT_KY_ID = p_ky_giam_id;

    p_thong_bao := p_thong_bao || CHR(10)
               || '[B??c 2] ?ã xóa ' || v_count_deleted || ' b?n ghi c?';

    -- B??c 3: Insert vào b?ng chính (gi? nguyên)
    INSERT INTO GTH_DU_DIEU_KIEN_GIAM_THOI_HANS (
        PHAM_NHAN_ID,
        GTH_KY_GIAM_THOI_HAN_ID,
        DIEU_KIEN_THOI_GIAN,
        DIEU_KIEN_XLCT,
        IS_NOP_DU,
        CREATION_TIME,
        IS_DELETED,
        IS_DU_DIEU_KIEN
    )
    WITH cau_hinh AS (
        SELECT
            TGCH_LOAI_DOI_TUONG,
            TGCH_TRUONG_HOP_DAC_BIET,
            TGCH_DOI_TUONG_THONG_THUONG
          FROM GTH_THOI_GIAN_CHAP_HANHS
         WHERE GTH_DIEU_KIEN_GIAM_THOI_HAN_ID = v_dieu_kien_id
           AND IS_DELETED = 0
    ),
	pham_nhan_base AS (
    SELECT
        ll.ID                                                         AS PHAM_NHAN_ID,
        ptha.THA_AN_PHAT                                              AS AN_PHAT_TEXT,
        FN_PARSE_AN_PHAT_TO_NGAY(ptha.THA_AN_PHAT)                   AS TONG_NGAY_AN,
        FN_GET_DA_CHAP_HANH_THEO_NGAY(ll.ID, v_ngay_xet)             AS DA_CHAP_HANH,
        FN_IS_TRUONG_HOP_DAC_BIET(ll.ID, p_ky_giam_id)               AS IS_DAC_BIET
      FROM PN_LAI_LICHS ll
      JOIN (
          SELECT THA_PNLAI_LICH_ID, THA_AN_PHAT, THA_NGAY_BAT, THA_NGAY_HET_HAN,
                 ROW_NUMBER() OVER (
                     PARTITION BY THA_PNLAI_LICH_ID
                     ORDER BY NVL(THA_NGAY_BAN_AN, DATE '1900-01-01') DESC, ID DESC
                 ) AS rn
            FROM PN_THI_HANH_AN
           WHERE NVL(IS_DELETED, 0) = 0
             AND THA_NGAY_BAT IS NOT NULL
      ) ptha ON ptha.THA_PNLAI_LICH_ID = ll.ID AND ptha.rn = 1
      JOIN DM_TINH_TRANG_PHAM_NHANS dttph
        ON ll.LL_TINH_TRANG_ID = dttph.ID
     WHERE ll.IS_DELETED = 0
       AND ll.LL_TRAI_GIAM_ID = v_trai_giam_id
       AND (ptha.THA_NGAY_HET_HAN IS NULL
            OR CAST(ptha.THA_NGAY_HET_HAN AS DATE) >= v_ngay_xet)
       AND (
           -- Tình tr?ng thông th??ng: ?ang ch?p hành
           dttph.TTPN_MA IN ('111','112','113','114')
           OR
           -- Tình tr?ng trích xu?t: ch? pass n?u lý do h?p l?
           (
               dttph.TTPN_MA IN ('141','142')
               AND EXISTS (
                   SELECT 1
                     FROM TRICH_XUATS tx
                     JOIN DM_LY_DO_TRICH_XUATS ldtx
                       ON ldtx.ID = tx.TX_LY_DO_ID
                      AND NVL(ldtx.IS_DELETED, 0) = 0
                    WHERE tx.PHAM_NHAN_ID = ll.ID
                      AND NVL(tx.IS_DELETED, 0) = 0
                      AND ldtx.LDTX_MA IN ('50', '51', '93')  -- Th?m g?p, G?p thân nhân, ?i vi?n
                	  AND (tx.TX_NGAY_TRA IS NULL                            -- ? Ch?a tr?
                	  OR CAST(tx.TX_NGAY_TRA AS DATE) > v_ngay_xet)    -- ? Tr? sau ngày xét
                      )
           )
       )
	),
    pham_nhan_voi_nguong AS (
        SELECT
            pb.PHAM_NHAN_ID, pb.AN_PHAT_TEXT, pb.TONG_NGAY_AN,
            pb.DA_CHAP_HANH, pb.IS_DAC_BIET,
            FN_PARSE_NGUONG(pb.AN_PHAT_TEXT,
            FN_GET_NGUONG_TGCH(pb.PHAM_NHAN_ID, p_ky_giam_id,
                                   pb.IS_DAC_BIET, pb.AN_PHAT_TEXT)) AS NGUONG_TGCH,
            FN_XET_DU_DIEU_KIEN_QUY(pb.PHAM_NHAN_ID, p_ky_giam_id).DU_DIEU_KIEN  AS IS_DU_QUY,
            FN_TINH_TONG_AN_GIAM(pb.PHAM_NHAN_ID)                    AS DA_GIAM
          FROM pham_nhan_base pb
          JOIN cau_hinh ch ON (
              (ch.TGCH_LOAI_DOI_TUONG LIKE '%th?i h?n%' AND pb.TONG_NGAY_AN >  0)
              OR (ch.TGCH_LOAI_DOI_TUONG LIKE '%Chung th%' AND pb.TONG_NGAY_AN = -1)
          )
    ),
    pham_nhan_voi_co_tgch AS (
        SELECT pn.*,
               FN_YMD_GTE(pn.DA_CHAP_HANH, pn.NGUONG_TGCH) AS IS_DU_TGCH,
               FN_TINH_CON_LAI(pn.AN_PHAT_TEXT, pn.DA_GIAM,
                                pn.DA_CHAP_HANH)             AS CON_LAI_YMD
          FROM pham_nhan_voi_nguong pn
    ),
    pham_nhan_voi_trang_thai AS (
        SELECT
            pn.PHAM_NHAN_ID, pn.IS_DU_TGCH, pn.IS_DU_QUY, pn.IS_DAC_BIET,
            CASE
                WHEN pn.IS_DU_TGCH = 0 THEN TO_NCHAR('Không ?? ?K v? th?i gian')
                ELSE FN_DIEU_KIEN_THOI_GIAN(pn.PHAM_NHAN_ID, v_ngay_xet, pn.IS_DAC_BIET)
            END                                                          AS TRANG_THAI_TG,
            FN_DIEU_KIEN_XLCT(pn.PHAM_NHAN_ID, p_ky_giam_id,
                               pn.IS_DAC_BIET)                          AS TRANG_THAI_XLCT,
            FN_XET_DU_DIEU_KIEN_HPBS(pn.PHAM_NHAN_ID,
                                      v_dieu_kien_id)                   AS IS_NOP_DU
          FROM pham_nhan_voi_co_tgch pn
    ), 
    pham_nhan_final AS (
        SELECT /*+ MATERIALIZE */
            PHAM_NHAN_ID, IS_DU_TGCH, IS_DU_QUY,
            TRANG_THAI_TG, TRANG_THAI_XLCT, IS_NOP_DU
          FROM pham_nhan_voi_trang_thai
    )
    SELECT
        pf.PHAM_NHAN_ID,
        p_ky_giam_id,
        pf.TRANG_THAI_TG,
        pf.TRANG_THAI_XLCT,
        pf.IS_NOP_DU,
        SYSTIMESTAMP,
        0,
        CASE
            WHEN pf.TRANG_THAI_TG   <> TO_NCHAR('Không ?? ?K v? th?i gian')
             AND pf.TRANG_THAI_XLCT <> TO_NCHAR('Không ?? ?K x?p lo?i')
             AND pf.IS_NOP_DU        = 1 THEN 1
            ELSE 0
        END
      FROM pham_nhan_final pf;

    v_count_inserted := SQL%ROWCOUNT;
    p_thong_bao := p_thong_bao || CHR(10)
               || '[B??c 3] ?ã thêm ' || v_count_inserted || ' ph?m nhân vào b?ng chính';

    -- ==========================================
    -- B??c 4: Insert vào b?ng chi ti?t
    -- ==========================================
-- B??c 4: Insert vào b?ng chi ti?t
    INSERT INTO GTH_DU_DIEU_KIEN_CHI_TIETS (
        DDKCT_KY_ID,
        DDKCT_PN_ID,
        DDKCT_HO_TEN,
        DDKCT_GIOI_TINH,
        DDKCT_NGAY_SINH,
        DDKCT_NOI_DKTT,
        DDKCT_SO_TIEN_AN,
        DDKCT_TOI_DANH,
        DDKCT_AN_PHAT,
        DDKCT_THOI_GIAN_DA_GIAM,
        DDKCT_THOI_GIAN_DA_CHAP_HANH,
        DDKCT_THOI_GIAN_CON_LAI,
        DDKCT_PHAN_DOI,
        DDKCT_PHAN_DOI_ID,
        DDKCT_HET_HAN,
        DDKCT_DIEU_KIEN_THOI_GIAN,
        DDKCT_DIEUKIEN_THOI_GIAN_ID,  
        DDKCT_DIEU_KIEN_XLCT,
        DDKCT_DIEU_KIEN_XLCT_ID,
        DDKCT_DOI_TUONG_ID,
        DDKCT_MUC_AN_PHAT_ID,
        DDKCT_TINH_TRANG_ID,
        DDKCT_QUOC_TICH_ID,
        DDKCT_IS_DU_DIEU_KIEN,
        DDKCT_IS_NOP_DU,
        CREATION_TIME,
        IS_DELETED,
        DDKCT_GHI_CHU
    )
    WITH
	dk_data AS (
	    SELECT /*+ MATERIALIZE */
	        gdd.PHAM_NHAN_ID,
	        gdd.DIEU_KIEN_THOI_GIAN,
	        gdd.DIEU_KIEN_XLCT,
	        gdd.IS_DU_DIEU_KIEN,
	        gdd.IS_NOP_DU
	      FROM GTH_DU_DIEU_KIEN_GIAM_THOI_HANS gdd
	     WHERE gdd.GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
	       AND gdd.IS_DELETED = 0
	       -- B? qua ph?m nhân ?ã có chi ti?t VÀ ?ã có b?n ghi gi?m án v?i ngày xét này
	       AND NOT EXISTS (
	           SELECT 1
	             FROM GTH_DU_DIEU_KIEN_CHI_TIETS ex
	            WHERE ex.DDKCT_KY_ID = p_ky_giam_id
	              AND ex.DDKCT_PN_ID  = gdd.PHAM_NHAN_ID
	              AND ex.IS_DELETED   = 0
	              AND EXISTS (
	                  SELECT 1
	                    FROM GIAM_THOI_HANS gth
	                   WHERE gth.PHAM_NHAN_ID = gdd.PHAM_NHAN_ID
	                     AND CAST(gth.NGAY_XET AS DATE) = v_ngay_xet
	                     AND gth.IS_DELETED   = 0
	              )
	       )
	),
	dk_quy_obj_data AS (
	    SELECT /*+ MATERIALIZE */
	        dk.PHAM_NHAN_ID,
	        QLPN.FN_XET_DU_DIEU_KIEN_QUY(dk.PHAM_NHAN_ID, p_ky_giam_id) AS DK_OBJ
	      FROM dk_data dk
	),
    da_chap_hanh_data AS (
    SELECT /*+ MATERIALIZE */
        dk.PHAM_NHAN_ID,
        QLPN.FN_GET_DA_CHAP_HANH_THEO_NGAY(dk.PHAM_NHAN_ID,v_ngay_xet) AS DA_CH_OBJ
      FROM dk_data dk
	),
	con_lai_data AS (
	    SELECT /*+ MATERIALIZE */
	        dk.PHAM_NHAN_ID,
	        QLPN.FN_TINH_THOI_GIAN_CON_LAI(dk.PHAM_NHAN_ID, v_ngay_xet) AS CON_LAI_TEXT
	      FROM dk_data dk
	),
	    toi_danh_split AS (
        SELECT /*+ MATERIALIZE */
            ptha.THA_PNLAI_LICH_ID AS PHAM_NHAN_ID,
            TO_NUMBER(TRIM(REGEXP_SUBSTR(
                REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
                '[^,]+', 1, LEVEL
            ))) AS TOI_DANH_ID
          FROM PN_THI_HANH_AN ptha
          JOIN dk_data dk ON dk.PHAM_NHAN_ID = ptha.THA_PNLAI_LICH_ID
         WHERE NVL(ptha.IS_DELETED, 0) = 0
           AND ptha.THA_TOI_DANH IS NOT NULL
        CONNECT BY LEVEL <= REGEXP_COUNT(
                       REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
               AND PRIOR ptha.THA_PNLAI_LICH_ID = ptha.THA_PNLAI_LICH_ID
               AND PRIOR SYS_GUID() IS NOT NULL
    ),
    toi_danh_agg AS (
        SELECT /*+ MATERIALIZE */
            s.PHAM_NHAN_ID,
            LISTAGG(td.TD_TEN, '; ')
                WITHIN GROUP (ORDER BY td.TD_TEN) AS TOI_DANH_TEXT
          FROM toi_danh_split s
          JOIN DM_TOI_DANHS td
            ON td.ID = s.TOI_DANH_ID
           AND NVL(td.IS_DELETED, 0) = 0
         GROUP BY s.PHAM_NHAN_ID
    ),
    -- Thêm CTE này vào b??c 4, sau toi_danh_agg
	tong_an_giam AS (
    SELECT /*+ MATERIALIZE */
        gth.PHAM_NHAN_ID,
        -- Quy v? t?ng ngày r?i normalize
        FLOOR(
            SUM(
                NVL(QLPN.FN_PARSE_AN_PHAT_TO_YMD(dmtg.MTG_TITLE).nam,   0) * 365 +
                NVL(QLPN.FN_PARSE_AN_PHAT_TO_YMD(dmtg.MTG_TITLE).thang, 0) * 30  +
                NVL(QLPN.FN_PARSE_AN_PHAT_TO_YMD(dmtg.MTG_TITLE).ngay,  0)
            ) / 365
        ) AS TONG_NAM,
        FLOOR(
            MOD(
                SUM(
                    NVL(QLPN.FN_PARSE_AN_PHAT_TO_YMD(dmtg.MTG_TITLE).nam,   0) * 365 +
                    NVL(QLPN.FN_PARSE_AN_PHAT_TO_YMD(dmtg.MTG_TITLE).thang, 0) * 30  +
                    NVL(QLPN.FN_PARSE_AN_PHAT_TO_YMD(dmtg.MTG_TITLE).ngay,  0)
                ), 365
            ) / 30
        ) AS TONG_THANG,
        MOD(
            MOD(
                SUM(
                    NVL(QLPN.FN_PARSE_AN_PHAT_TO_YMD(dmtg.MTG_TITLE).nam,   0) * 365 +
                    NVL(QLPN.FN_PARSE_AN_PHAT_TO_YMD(dmtg.MTG_TITLE).thang, 0) * 30  +
                    NVL(QLPN.FN_PARSE_AN_PHAT_TO_YMD(dmtg.MTG_TITLE).ngay,  0)
                ), 365
            ), 30
        ) AS TONG_NGAY
    FROM GIAM_THOI_HANS gth
    JOIN DM_MA_THOI_GIANS dmtg
        ON dmtg.ID = gth.MUC_GIAM_ID
       AND NVL(dmtg.IS_DELETED, 0) = 0
       AND dmtg.MTG_MA NOT IN ('921000','912000','911000','922000')  -- ? gi? ?úng filter g?c
    -- Ch? tính ph?m nhân trong k?
    JOIN dk_data dk ON dk.PHAM_NHAN_ID = gth.PHAM_NHAN_ID
    WHERE gth.IS_DELETED = 0
    GROUP BY gth.PHAM_NHAN_ID
	),
    doi_tuong_data AS (
        SELECT /*+ MATERIALIZE */
            s.PHAM_NHAN_ID,
            CASE WHEN COUNT(CASE WHEN td.TD_CHUONG = '13' THEN 1 END) > 0
                 THEN 1 ELSE 2
            END AS DOI_TUONG_ID
          FROM toi_danh_split s
          JOIN DM_TOI_DANHS td
            ON td.ID = s.TOI_DANH_ID
           AND NVL(td.IS_DELETED, 0) = 0
         GROUP BY s.PHAM_NHAN_ID
    ),
	latest_tha AS (
    SELECT /*+ MATERIALIZE */
        THA_PNLAI_LICH_ID,
        THA_AN_PHAT,
        THA_NGAY_HET_HAN,
        ROW_NUMBER() OVER (
            PARTITION BY THA_PNLAI_LICH_ID
            ORDER BY NVL(THA_NGAY_BAN_AN, DATE '1900-01-01') DESC, ID DESC
        ) AS rn
      FROM PN_THI_HANH_AN
     WHERE NVL(IS_DELETED, 0) = 0
       AND THA_PNLAI_LICH_ID IN (SELECT PHAM_NHAN_ID FROM dk_data)
    ),
    chi_tiet AS (
        SELECT /*+ MATERIALIZE */
            dk.PHAM_NHAN_ID,
            ll.LL_HO_TEN,
            dgt.GT_TEN                                            AS GIOI_TINH,
            ll.LL_NGAY_SINH,
		    CASE
		        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
		          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
		          OR NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL
		        THEN TRIM(
		            NVL(NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u''), u'')
		            || CASE
		                WHEN NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL THEN
		                    CASE
		                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
		                            THEN u', ' || dxp_thuong_tru.XP_TEN
		                        ELSE dxp_thuong_tru.XP_TEN
		                    END
		                ELSE u''
		               END
		            || CASE
		                WHEN NULLIF(TRIM(dttp_thuong_tru.TTP_TEN), u'') IS NOT NULL THEN
		                    CASE
		                        WHEN NULLIF(TRIM(ll.LL_DIA_CHI_THUONG_TRU), u'') IS NOT NULL
		                          OR NULLIF(TRIM(dxp_thuong_tru.XP_TEN), u'') IS NOT NULL
		                            THEN u', ' || dttp_thuong_tru.TTP_TEN
		                        ELSE dttp_thuong_tru.TTP_TEN
		                    END
		                ELSE u''
		               END
		        )
		        ELSE NULL
		    END AS LL_DIA_CHI_THUONG_TRU,
			ll.LL_SO_TIEN_AN,
            td_agg.TOI_DANH_TEXT,
            ptha.THA_AN_PHAT,
	        tag.TONG_NAM    AS DA_GIAM_NAM,
	        tag.TONG_THANG  AS DA_GIAM_THANG,
	        tag.TONG_NGAY   AS DA_GIAM_NGAY,
			dch.DA_CH_OBJ,
			cl.CON_LAI_TEXT,
            dpd.PD_TEN || ', ' || dpt.PT_TEN                                            AS PHAN_DOI,
            ll.LL_PHAN_DOI_ID,
            ptha.THA_NGAY_HET_HAN                                AS HET_HAN,
            dk.DIEU_KIEN_THOI_GIAN,
            dk.DIEU_KIEN_XLCT,
            QLPN.FN_GET_GHI_CHU_DIEU_KIEN_QUY(dk.PHAM_NHAN_ID, dko.DK_OBJ) AS GHI_CHU,
            NVL(dt.DOI_TUONG_ID, 0)                             AS DOI_TUONG_ID,
            NVL(QLPN.FN_GET_MUC_AN_ID_GTH(ptha.THA_AN_PHAT), 0) AS MUC_AN_PHAT_ID,
            ll.LL_TINH_TRANG_ID,
            ll.LL_DM_QUOC_TICH_ID,
            dk.IS_DU_DIEU_KIEN,
            dk.IS_NOP_DU
          FROM dk_data dk
          JOIN PN_LAI_LICHS ll
            ON ll.ID = dk.PHAM_NHAN_ID
           AND NVL(ll.IS_DELETED, 0) = 0
          LEFT JOIN tong_an_giam tag ON tag.PHAM_NHAN_ID = dk.PHAM_NHAN_ID
          LEFT JOIN DM_PHAN_TRAIS dpt ON ll.LL_PHAN_TRAI_ID = dpt.ID
          LEFT JOIN latest_tha ptha
            ON ptha.THA_PNLAI_LICH_ID = dk.PHAM_NHAN_ID
           AND ptha.rn = 1
          LEFT JOIN dk_quy_obj_data dko ON dko.PHAM_NHAN_ID = dk.PHAM_NHAN_ID
          LEFT JOIN toi_danh_agg td_agg
            ON td_agg.PHAM_NHAN_ID = dk.PHAM_NHAN_ID
          LEFT JOIN doi_tuong_data dt
            ON dt.PHAM_NHAN_ID = dk.PHAM_NHAN_ID
          LEFT JOIN DM_GIOI_TINHS dgt
            ON dgt.ID = ll.LL_DM_GIOI_TINH_ID
          LEFT JOIN DM_PHAN_DOIS dpd
            ON dpd.ID = ll.LL_PHAN_DOI_ID
		  LEFT JOIN da_chap_hanh_data dch ON dch.PHAM_NHAN_ID = dk.PHAM_NHAN_ID
		  LEFT JOIN con_lai_data cl       ON cl.PHAM_NHAN_ID  = dk.PHAM_NHAN_ID
			-- Join danh m?c t?nh/thành — th??ng trú
		  LEFT JOIN DM_TINH_THANH_PHO dttp_thuong_tru 
		    ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dttp_thuong_tru.ID 
		    AND NVL(dttp_thuong_tru.IS_DELETED, 0) = 0

		-- Join danh m?c ph??ng/xã — th??ng trú
		  LEFT JOIN DM_XA_PHUONG dxp_thuong_tru 
		    ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dxp_thuong_tru.ID 
		    AND NVL(dxp_thuong_tru.IS_DELETED, 0) = 0
    )
    SELECT
        p_ky_giam_id,
        ct.PHAM_NHAN_ID,
        ct.LL_HO_TEN,
        ct.GIOI_TINH,
        ct.LL_NGAY_SINH,
        ct.LL_DIA_CHI_THUONG_TRU,
        ct.LL_SO_TIEN_AN,
        ct.TOI_DANH_TEXT,
        ct.THA_AN_PHAT,

        -- T?ng án gi?m
        QLPN.FN_TINH_AN_DA_GIAM_CHI_TIET(ct.PHAM_NHAN_ID),
--        CASE
--            WHEN NVL(ct.DA_GIAM_NAM,   0) = 0
--             AND NVL(ct.DA_GIAM_THANG, 0) = 0
--             AND NVL(ct.DA_GIAM_NGAY,  0) = 0
--            THEN u'Kh\00f4ng'
--            ELSE TRIM(
--                CASE WHEN NVL(ct.DA_GIAM_NAM,   0) > 0 THEN TO_CHAR(ct.DA_GIAM_NAM)   || u' n\0103m '   ELSE u'' END ||
--                CASE WHEN NVL(ct.DA_GIAM_THANG, 0) > 0 THEN TO_CHAR(ct.DA_GIAM_THANG) || u' th\00e1ng ' ELSE u'' END ||
--                CASE WHEN NVL(ct.DA_GIAM_NGAY,  0) > 0 THEN TO_CHAR(ct.DA_GIAM_NGAY)  || u' ng\00e0y'   ELSE u'' END
--            )
--        END,

        -- ?ã ch?p hành
        CASE
            WHEN NVL(ct.DA_CH_OBJ.nam,   0) = 0
             AND NVL(ct.DA_CH_OBJ.thang, 0) = 0
             AND NVL(ct.DA_CH_OBJ.ngay,  0) = 0 
            THEN TO_NCHAR('Không')
            ELSE TRIM(
                CASE WHEN NVL(ct.DA_CH_OBJ.nam,   0) > 0 THEN TO_CHAR(ct.DA_CH_OBJ.nam)   || u' n\0103m '   ELSE u'' END ||
                CASE WHEN NVL(ct.DA_CH_OBJ.thang, 0) > 0 THEN TO_CHAR(ct.DA_CH_OBJ.thang) || u' th\00e1ng ' ELSE u'' END ||
                CASE WHEN NVL(ct.DA_CH_OBJ.ngay,  0) > 0 THEN TO_CHAR(ct.DA_CH_OBJ.ngay)  || u' ng\00e0y'   ELSE u'' END
            )
        END,
        ct.CON_LAI_TEXT,
        ct.PHAN_DOI,
        ct.LL_PHAN_DOI_ID,
        ct.HET_HAN,
        ct.DIEU_KIEN_THOI_GIAN,
        CASE ct.DIEU_KIEN_THOI_GIAN
            WHEN TO_NCHAR('?? ?K - ?ã gi?m án - ?úng ??t')      THEN 1
            WHEN TO_NCHAR('?? ?K - ?ã gi?m án - ???c ??y ??t')  THEN 2
            WHEN TO_NCHAR('?? ?K - Xét l?n ??u - Thông th??ng') THEN 3
            WHEN TO_NCHAR('?? ?K - Xét l?n ??u - ??c bi?t')     THEN 4
            WHEN TO_NCHAR('Không ?? ?K v? th?i gian')            THEN 5
            ELSE 0
        END,
        ct.DIEU_KIEN_XLCT,
        CASE ct.DIEU_KIEN_XLCT
            WHEN TO_NCHAR('?? ?K - Gi?m l?n ??u (th??ng)')      THEN 1
            WHEN TO_NCHAR('?? ?K - Gi?m l?n ??u (??c bi?t)')    THEN 2
            WHEN TO_NCHAR('?? ?K - Gi?m l?n sau')                THEN 3
            WHEN TO_NCHAR('Không ?? ?K x?p lo?i')                THEN 4
            ELSE 0
        END,
        ct.DOI_TUONG_ID,
        ct.MUC_AN_PHAT_ID,
        ct.LL_TINH_TRANG_ID,
        ct.LL_DM_QUOC_TICH_ID,
        ct.IS_DU_DIEU_KIEN,
        ct.IS_NOP_DU,
        SYSTIMESTAMP,
        0,-- IS_DELETED
        ct.GHI_CHU
      FROM chi_tiet ct;

    v_count_ct := SQL%ROWCOUNT; 
    p_thong_bao := p_thong_bao || CHR(10)
               || '[B??c 4] ?ã thêm ' || v_count_ct || ' b?n ghi vào b?ng chi ti?t';

    COMMIT; 
    p_thong_bao := p_thong_bao || CHR(10) || CHR(10)
               || '  - THÀNH CÔNG'                                            || CHR(10)
               || '  - ?i?u ki?n ID : ' || v_dieu_kien_id                     || CHR(10)
               || '  - Ngày xét     : ' || TO_CHAR(v_ngay_xet, 'DD/MM/YYYY') || CHR(10)
               || '  - Xóa          : ' || v_count_deleted  || ' b?n ghi'     || CHR(10)
               || '  - B?ng chính   : ' || v_count_inserted || ' ph?m nhân'   || CHR(10)
               || '  - B?ng chi ti?t: ' || v_count_ct       || ' b?n ghi';

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        v_error_msg := SQLERRM;
        p_thong_bao := p_thong_bao || CHR(10) || CHR(10)
                    || '  - L?I'                                                   || CHR(10)
                    || '  - Mã l?i    : ' || SQLCODE                               || CHR(10)
                    || '  - Thông báo : ' || v_error_msg                           || CHR(10)
                    || '  - K? gi?m  : ' || p_ky_giam_id                          || CHR(10)
                    || '  - ?i?u ki?n : ' || NVL(TO_CHAR(v_dieu_kien_id), 'NULL') || CHR(10)
                    || '  - ?ã xóa   : ' || v_count_deleted  || ' b?n ghi'        || CHR(10)
                    || '  - ?ã thêm  : ' || v_count_inserted || ' b?n ghi';
        RAISE;
END SP_XET_DU_DIEU_KIEN_GTH_OPT;


