  ) RETURN NVARCHAR2;

  /**
   * Tính th?i gian còn l?i (s? ngày).
   * Công th?c: max(0, TRUNC(ngày h?t án l?ch) - TRUNC(ngày xét)); ngày h?t = m?c t? THA_AN_PHAT + gi?m/t?ng gi?m HP/mi?n trên DATE. T? hình / chung thân thu?n ? NULL.
   */
  FUNCTION FN_TINH_THOI_GIAN_CON_LAI(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NUMBER;

  /**
   * Tính th?i gian còn l?i, ??nh d?ng "X Tháng Y ngày".
   */
  FUNCTION FN_TINH_THOI_GIAN_CON_LAI_THANG_NGAY(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2;

  /**
   * Tính th?i gian còn l?i, ??nh d?ng "A n?m B tháng C ngày".
   */
  FUNCTION FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2;

  /**
   * Tính mã th?i gian (DM_MA_THOI_GIANS.MTG_MA) c?a th?i gian còn l?i,
   * d?a trên chu?i ??nh d?ng "A n?m B tháng C ngày".
   * Tra DM: cùng quy t?c v?i FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY_MA_TG (kh?p ??y ?? r?i rút g?n 0 tháng / 0 ngày).
   */
  FUNCTION FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY_MA_TG(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2;

  /**
   * Tính ngày tha (ngày h?t h?n ch?p hành án).
   * Tr? v? NULL n?u: tr?n ch?a b?t l?i; ho?c hoãn ch?a NGAY_THI_HANH_AN; T?C ch?a NGAY_LAI; trích xu?t ch?a TX_NGAY_TRA; ho?c chung thân thu?n (không gi?m xu?ng tù có th?i h?n).
   */
  FUNCTION FN_TINH_NGAY_THA(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN DATE;

  /**
   * Ki?m tra th?i gian ?ã ch?p hành có ??t t? l? t?i thi?u hay không.
   * So sánh theo l?ch th?c (n?m, tháng, ngày th?c t?): tháng 2 có 28 ngày, tháng 3 có 31 ngày...
   * Ng??ng = ngày_b?t + (t?ng_ngày * t?_l?), so sánh theo ngày th?c t? (TRUNC).
   * Ví d?: 2 n?m 6 tháng / 5 n?m = 1/2 ? ngày 13/03/2026 ??t (không dùng CEIL vì làm thi?u 1 ngày).
   * @param p_id_pham_nhan ID ph?m nhân
   * @param p_ratio T? l? (vd 1/3 = 0.333...)
   * @param p_ngay_xet Ngày xét; NULL = SYSDATE
   * @return 1 n?u ??t, 0 n?u không ??t, NULL n?u không xác ??nh ???c
   */
  FUNCTION FN_DA_CHAP_HANH_DAT_TY_LE(
    p_id_pham_nhan IN NUMBER,
    p_ratio        IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NUMBER;

  /**
   * Tính t?ng th?i gian gi?m án, tr? v? chu?i ?ã format theo quy ??c:
   * - >= 12 tháng: "X n?m Y tháng Z ngày"
   * - >= 1 tháng và < 12 tháng: "X Tháng Y ngày"
   * - < 1 tháng (s? ngày): "Z ngày"
   * L?y t?ng t? GIAM_THOI_HANS, MUC_GIAM_ID map DM_MA_THOI_GIANS (MTG_TITLE).
   * @param p_id_pham_nhan ID ph?m nhân
   * @return Chu?i hi?n th? (vd "1 n?m 2 tháng 3 ngày", "5 Tháng 10 ngày", "25 ngày", "0")
   */
  FUNCTION FN_TINH_TONG_THOI_GIAN_GIAM(
    p_id_pham_nhan IN NUMBER
  ) RETURN NVARCHAR2;

  /**
   * Tính s? l?n gi?m án (COUNT t? GIAM_THOI_HANS khi MUC_GIAM_ID IS NOT NULL).
   * @param p_id_pham_nhan ID ph?m nhân
   * @return S? l?n gi?m án (0 n?u không có)
   */
  FUNCTION FN_TINH_SO_LAN_GIAM_AN(
    p_id_pham_nhan IN NUMBER
  ) RETURN NUMBER;

  /**
   * Hi?n th? gi?m án d?ng "X l?n = Y n?m Z tháng W ngày" ho?c "Không".
   * Dùng FN_TINH_SO_LAN_GIAM_AN + FN_TINH_TONG_THOI_GIAN_GIAM.
   * @param p_id_pham_nhan ID ph?m nhân
   * @return Chu?i hi?n th? (vd "2 l?n = 48 n?m 9 tháng 27 ngày", "Không")
   */
  FUNCTION FN_TINH_GIAM_AN_HIEN_THI(
    p_id_pham_nhan IN NUMBER
  ) RETURN NVARCHAR2;

  /**
   * Chu?i mi?n hình ph?t t? MIEN_HINH_PHATS (MHP_THM_YEAR/MONTH/DAY), m?i Q? m?t dòng (xu?ng dòng).
   * ??nh d?ng t?ng dòng gi?ng SP_GET_BAO_CAO_DS_MIEN_HINH_PHAT (THOI_GIAN_MIEN).
   * @param p_id_pham_nhan ID lý l?ch (PN_LAI_LICHS.ID = PN_LAI_LICH_ID trên MIEN_HINH_PHATS)
   * @return Chu?i hi?n th? ho?c "Không" khi không có b?n ghi / không có th?i h?n mi?n
   */
  FUNCTION FN_TINH_TONG_MIEN_HINH_PHAT_HIEN_THI(
    p_id_pham_nhan IN NUMBER
  ) RETURN NVARCHAR2;

  /**
   * Ki?m tra th?i gian ?ã ch?p hành có ??t s? n?m t?i thi?u hay không.
   * So sánh theo l?ch th?c: ng??ng = s? ngày th?c t? c?a p_so_nam n?m t? ngày b?t (ADD_MONTHS, n?m nhu?n...).
   * @param p_id_pham_nhan ID ph?m nhân
   * @param p_so_nam S? n?m t?i thi?u (vd 14, 15)
   * @param p_ngay_xet Ngày xét; NULL = SYSDATE
   * @return 1 n?u ??t, 0 n?u không ??t, NULL n?u không xác ??nh ???c
   */
  FUNCTION FN_DA_CHAP_HANH_DAT_SO_NAM(
    p_id_pham_nhan IN NUMBER,
    p_so_nam       IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NUMBER;

  /**
   * Tr? v? ngày b?t và các kho?ng th?i gian b? tr? (t?m ?ình ch?, hoãn, tr?n) d??i d?ng b?ng chi ti?t.
   * Dùng: SELECT * FROM TABLE(QLPN.PKG_TINH_AN_V1.FN_GET_CHI_TIET_THOI_GIAN_THI_HANH(151, SYSDATE));
   * @param p_id_pham_nhan ID ph?m nhân
   * @param p_ngay_xet Ngày xét; NULL = SYSDATE
   * @return TYP_TINH_AN_CHI_TIET_TBL (LOAI, TU_NGAY, DEN_NGAY, SO_NGAY, THU_TU)
   */
  FUNCTION FN_GET_CHI_TIET_THOI_GIAN_THI_HANH(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN QLPN.TYP_TINH_AN_CHI_TIET_TBL PIPELINED;

  /**
   * Xác ??nh ID m?c án (DM_MUC_ANS) t? chu?i án ph?t (vd THA_AN_PHAT, DM_MA_THOI_GIANS.MTG_TITLE).
   * Quy ??i: t?ng tháng = n?m*12 + tháng + ngày/30 (30 ngày = 1 tháng, ??ng b? quy ??c gói).
   * So kh?p kho?ng MA_TU .. MA_DEN (tháng). Ví d? 3 n?m 6 tháng = 42 tháng -> kho?ng (36.01, 60] -> ID = 2.
   * Hai chu?i c? ??nh (so kh?p không phân bi?t hoa th??ng, chu?n hóa kho?ng tr?ng): "Chung thân gi?m xu?ng 20 n?m" / "Chung thân Gi?m xu?ng 30 n?m"
   *   -> quy ??i 240 / 360 tháng -> kho?ng MA_TU..MA_DEN (m?c Trên 15-20 n?m / Trên 20-30 n?m).
   * Chung thân khác: dòng DM_MUC_ANS có MA_TU >= 900000.
   */
  FUNCTION FN_GET_MUC_AN_ID_TU_AN_PHAT(
    p_tha_an_phat IN NVARCHAR2
  ) RETURN NUMBER;

  /**
   * C?p nh?t PN_THI_HANH_AN.THA_THOI_GIAN_DA_CHAP_HANH, THA_THOI_GIAN_CON_LAI b?ng MTG_MA (DM_MA_THOI_GIANS).
   * G?i FN trong PL/SQL r?i UPDATE (tránh g?i FN tr?c ti?p trong SET khi FN ??c l?i PN_THI_HANH_AN).
   * Ch? áp d?ng cho lý l?ch có LL_TINH_TRANG_ID thu?c DM_TINH_TRANG_PHAM_NHANS v?i TTPN_MA IN ('111','112','113','114').
   * @param p_tha_pnlai_lich_id ID lý l?ch (PN_LAI_LICHS.ID); NULL = m?i b?n ghi th?a ?i?u ki?n tình tr?ng
   * @param p_ngay_xet Ngày xét; NULL = SYSDATE (theo PKG_TINH_AN_V1)
   */
  PROCEDURE SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI(
    p_tha_pnlai_lich_id IN NUMBER DEFAULT NULL,
    p_ngay_xet          IN DATE   DEFAULT NULL
  );

END PKG_TINH_AN_V1;






/
--------------------------------------------------------
--  DDL for Package Body PKG_BAO_CAO_THONG_KE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "QLPN"."PKG_BAO_CAO_THONG_KE" AS

-- =====================================================
-- Báo cáo: Danh sách ph?m nhân
-- =====================================================
PROCEDURE SP_GET_DS_PHAM_NHAN(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR 
    SELECT
        ll.LL_HO_TEN AS "HoTen",
        SUBSTR(ll.LL_NGAY_SINH, -4) AS "NamSinh",
        dgt.GT_TEN AS "GioiTinh",
        RTRIM(
        NVL(ll.LL_DIA_CHI_THUONG_TRU, '') || ', ' ||
        NVL(dvhcx.XP_TEN, '') || ', ' ||
        NVL(dvhct.TTP_TEN, '')
    , ', ') AS "DiaChi",
        td_agg.TOI_DANH AS "ToiDanh",
        ll.LL_SO_TIEN_AN AS "SoTienAn",
		TO_CHAR(TRUNC(ptha.THA_NGAY_BAT),'DD/MM/YYYY') AS "NgayBat",
		ptha.THA_AN_PHAT AS "AnPhat",
        '1' AS "DaGiam",
        QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(ll.ID) AS "DaChapHanh",
        QLPN.PKG_TINH_AN.FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(ll.ID) AS "ConLai",
		TO_CHAR(TRUNC(ptha.THA_NGAY_DEN_TRAI),'DD/MM/YYYY') AS "NgayDenTrai",
		TO_CHAR(TRUNC(ptha.THA_NGAY_HET_HAN),'DD/MM/YYYY') AS "NgayHetHan",
		hpbs_agg.HINH_PHAT_BO_SUNG AS "HinhPhatBoSung",
        gcr_agg.GHI_CHU_RIENG AS "GhiChu"
    FROM PN_LAI_LICHS ll
    LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
    -- T?i danh
    LEFT JOIN (
        SELECT
            ptha.THA_PNLAI_LICH_ID,
            RTRIM(XMLAGG(XMLELEMENT(e, dtd.TD_TEN || ', ') ORDER BY dtd.TD_TEN).extract('//text()').GETCLOBVAL(), ', ') AS TOI_DANH
        FROM PN_THI_HANH_AN ptha
        LEFT JOIN (
            SELECT DISTINCT
                ptha2.THA_PNLAI_LICH_ID,
                TO_NUMBER(REGEXP_SUBSTR(REPLACE(REPLACE(ptha2.THA_TOI_DANH, '[', ''), ']', ''), '[^,]+', 1, LEVEL)) AS TOI_DANH_ID
            FROM PN_THI_HANH_AN ptha2
            CONNECT BY LEVEL <= REGEXP_COUNT(REPLACE(REPLACE(ptha2.THA_TOI_DANH, '[', ''), ']', ''), ',') + 1
            AND PRIOR ptha2.THA_PNLAI_LICH_ID = ptha2.THA_PNLAI_LICH_ID
            AND PRIOR SYS_GUID() IS NOT NULL
        ) td ON ptha.THA_PNLAI_LICH_ID = td.THA_PNLAI_LICH_ID
        LEFT JOIN DM_TOI_DANHS dtd ON td.TOI_DANH_ID = dtd.ID
        GROUP BY ptha.THA_PNLAI_LICH_ID
    ) td_agg ON ll.ID = td_agg.THA_PNLAI_LICH_ID
    -- Hình ph?t b? sung
    LEFT JOIN (
        SELECT
            hpbs.HPBS_MA_PHAM_NHAN,
            RTRIM(XMLAGG(XMLELEMENT(e, dmhpbs.HPBS_TEN || ', ') ORDER BY dmhpbs.HPBS_TEN).extract('//text()').GETCLOBVAL(), ', ') AS HINH_PHAT_BO_SUNG
        FROM QLPN.PN_HINH_PHAT_BO_SUNGS hpbs
        LEFT JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dmhpbs ON hpbs.HPBS_HINH_PHAT = dmhpbs.ID
        WHERE hpbs.IS_DELETED = 0
        GROUP BY hpbs.HPBS_MA_PHAM_NHAN
    ) hpbs_agg ON ll.ID = hpbs_agg.HPBS_MA_PHAM_NHAN
    -- Ghi chú riêng
    LEFT JOIN (SELECT
			    ll2.ID AS PHAM_NHAN_ID,
			    RTRIM(
			        XMLAGG(
			            XMLELEMENT(e, dgcr.GCR_TEN || ', ')
			            ORDER BY dgcr.GCR_TEN
			        ).extract('//text()').GETCLOBVAL(),
			        ', '
			    ) AS GHI_CHU_RIENG
			FROM PN_LAI_LICHS ll2
			LEFT JOIN LATERAL (
			    SELECT
			        TRIM(REGEXP_SUBSTR(ll2.LL_GHI_CHU_RIENG, '[^,]+', 1, LEVEL)) AS GHI_CHU_RIENG_MA
			    FROM DUAL
			    WHERE ll2.LL_GHI_CHU_RIENG IS NOT NULL
			    CONNECT BY LEVEL <= REGEXP_COUNT(ll2.LL_GHI_CHU_RIENG, ',') + 1
			) gcr ON 1 = 1
			LEFT JOIN DM_GHI_CHU_RIENGS dgcr
			    ON gcr.GHI_CHU_RIENG_MA = TRIM(dgcr.ID)
			GROUP BY ll2.ID, ll2.LL_GHI_CHU_RIENG
			) gcr_agg ON ll.ID = gcr_agg.PHAM_NHAN_ID
	LEFT JOIN DM_XA_PHUONG dvhcx
    	ON ll.LL_DIA_CHI_THUONG_TRU_WARD = dvhcx.ID
	LEFT JOIN DM_TINH_THANH_PHO dvhct
    	ON ll.LL_DIA_CHI_THUONG_TRU_PROVICE = dvhct.ID

    WHERE 1=1
      -- Filter tr?i giam
      AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
      -- Filter ngày ??n tr?i
      AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
      AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay);

    DBMS_SQL.RETURN_RESULT(c1);
END SP_GET_DS_PHAM_NHAN;

-- =====================================================
-- Báo cáo: Th?ng kê theo dân t?c
-- =====================================================
PROCEDURE SP_THONG_KE_DAN_TOC(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR 
    SELECT 
        "TT",
        "DanToc",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Nhóm I: Kinh
        SELECT
            1 AS SORT_ORDER,
            TO_NCHAR('I') AS "TT",
            TO_NCHAR('Kinh') AS "DanToc",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        JOIN DM_DAN_TOCS ddt ON ll.LL_DM_DAN_TOC_ID = ddt.ID
        JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND UPPER(TRIM(NVL(ddt.DT_TEN, ''))) = 'KINH'
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        UNION ALL

        -- Nhóm II: Ng??i n??c ngoài
        SELECT
            2 AS SORT_ORDER,
            TO_NCHAR('II') AS "TT",
            TO_NCHAR('Ng??i n??c ngoài') AS "DanToc",
			COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
			COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
			COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
			COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        JOIN DM_DAN_TOCS ddt ON ll.LL_DM_DAN_TOC_ID = ddt.ID
        JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND UPPER(TRIM(NVL(ddt.DT_MA, ''))) IN ('Ng??i n??c ngoài')
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        UNION ALL

        -- Nhóm III: Dân t?c thi?u s? (header)
        SELECT
            3 AS SORT_ORDER,
            TO_NCHAR('III') AS "TT",
            TO_NCHAR('Dân t?c thi?u s?') AS "DanToc",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        JOIN DM_DAN_TOCS ddt ON ll.LL_DM_DAN_TOC_ID = ddt.ID
--        LEFT JOIN DM_QUOC_TICHS dqt ON ll.LL_DM_QUOC_TICH_ID = dqt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (TRIM(NVL(ddt.DT_MA, ''))) NOT IN ('Ng??i n??c ngoài','Kinh')
--          AND UPPER(TRIM(NVL(dqt.QT_TEN, ''))) IN ('VI?T NAM', 'VIET NAM', '')
          AND ddt.DT_TEN IS NOT NULL
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        UNION ALL

        -- Chi ti?t t?ng dân t?c thi?u s?
        SELECT
            3 + (ROW_NUMBER() OVER (ORDER BY ddt.DT_TEN)) * 0.01 AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY ddt.DT_TEN))) AS "TT",
            ddt.DT_TEN AS "DanToc",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        JOIN DM_DAN_TOCS ddt ON ll.LL_DM_DAN_TOC_ID = ddt.ID
        JOIN DM_QUOC_TICHS dqt ON ll.LL_DM_QUOC_TICH_ID = dqt.ID
        JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND UPPER(TRIM(NVL(ddt.DT_TEN, ''))) != 'KINH'
          AND UPPER(TRIM(NVL(dqt.QT_TEN, ''))) IN ('VI?T NAM', 'VIET NAM', '')
          AND ddt.DT_TEN IS NOT NULL
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY ddt.DT_TEN

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            TO_NCHAR('T?ng s?') AS "DanToc",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_THONG_KE_DAN_TOC;
-- =====================================================
-- Báo cáo: Th?ng kê theo qu?c t?ch
-- =====================================================
PROCEDURE SP_THONG_KE_QUOC_TICH(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR 
    SELECT 
        "TT",
        "QuocTich",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Nhóm I: Vi?t Nam
        SELECT
            1 AS SORT_ORDER,
            TO_NCHAR('I') AS "TT",
            TO_NCHAR('Vi?t Nam') AS "QuocTich",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_QUOC_TICHS dqt ON ll.LL_DM_QUOC_TICH_ID = dqt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (UPPER(TRIM(NVL(dqt.QT_TEN, ''))) IN ('VI?T NAM', 'VIET NAM') OR dqt.QT_TEN IS NULL)
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        UNION ALL

        -- Nhóm II: N??c ngoài
        SELECT
            2 AS SORT_ORDER,
            TO_NCHAR('II') AS "TT",
            TO_NCHAR('N??c ngoài') AS "QuocTich",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_QUOC_TICHS dqt ON ll.LL_DM_QUOC_TICH_ID = dqt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND UPPER(TRIM(NVL(dqt.QT_TEN, ''))) NOT IN ('VI?T NAM', 'VIET NAM', '')
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            TO_NCHAR('T?ng s?') AS "QuocTich",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_THONG_KE_QUOC_TICH;

-- =====================================================
-- Báo cáo: Th?ng kê theo h?c v?n
-- =====================================================
PROCEDURE SP_THONG_KE_HOC_VAN(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR 
    SELECT 
        "TT",
        "HocVan",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Chi ti?t t?ng trình ?? h?c v?n
        SELECT
            ROW_NUMBER() OVER (ORDER BY dhv.ID) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY dhv.ID))) AS "TT",
            NVL(dhv.HV_TEN, TO_NCHAR('Ch?a xác ??nh')) AS "HocVan",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_HOC_VANS dhv ON ll.LL_DM_HOC_VAN_ID = dhv.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY dhv.ID, dhv.HV_TEN

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            TO_NCHAR('T?ng s?') AS "HocVan",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_THONG_KE_HOC_VAN;

-- =====================================================
-- Báo cáo: Th?ng kê theo ngh? nghi?p
-- =====================================================
PROCEDURE SP_THONG_KE_NGHE_NGHIEP(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR 
    SELECT 
        "TT",
        "NgheNghiep",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Chi ti?t t?ng ngh? nghi?p
        SELECT
            ROW_NUMBER() OVER (ORDER BY dnn.ID) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY dnn.ID))) AS "TT",
            NVL(dnn.NN_TEN, TO_NCHAR('Ch?a xác ??nh')) AS "NgheNghiep",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_NGHE_NGHIEPS dnn ON ll.LL_DM_NGHE_NGHIEP_ID = dnn.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY dnn.ID, dnn.NN_TEN

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            TO_NCHAR('T?ng s?') AS "NgheNghiep",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_THONG_KE_NGHE_NGHIEP;
-- =====================================================
-- Báo cáo: Th?ng kê theo ch??ng t?i danh
-- =====================================================
PROCEDURE SP_THONG_KE_TOI_DANH(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR 
    WITH chuong_rank AS (
        SELECT DISTINCT
            TEN_CHUONG,
            TEN_CHUONG_TOI_DANH,
            DENSE_RANK() OVER (ORDER BY TEN_CHUONG) AS CHUONG_SO
        FROM VW_PN_TOI_DANH_CHUONG
    )
    SELECT 
        "TT",
        "ToiDanh",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Header ch??ng
        SELECT
            cr.CHUONG_SO AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(cr.CHUONG_SO)) AS "TT",
            cr.TEN_CHUONG || ': ' || cr.TEN_CHUONG_TOI_DANH AS "ToiDanh",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM VW_PN_TOI_DANH_CHUONG vtd
        JOIN chuong_rank cr ON vtd.TEN_CHUONG = cr.TEN_CHUONG
        LEFT JOIN PN_LAI_LICHS ll ON vtd.PN_ID = ll.ID
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY cr.CHUONG_SO, cr.TEN_CHUONG, cr.TEN_CHUONG_TOI_DANH

        UNION ALL

        -- Chi ti?t t?i danh
        SELECT
            cr.CHUONG_SO + (ROW_NUMBER() OVER (PARTITION BY cr.TEN_CHUONG ORDER BY vtd.TEN_TOI_DANH)) * 0.001 AS SORT_ORDER,
            TO_NCHAR('+') AS "TT",
            vtd.TEN_TOI_DANH AS "ToiDanh",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM VW_PN_TOI_DANH_CHUONG vtd
        JOIN chuong_rank cr ON vtd.TEN_CHUONG = cr.TEN_CHUONG
        LEFT JOIN PN_LAI_LICHS ll ON vtd.PN_ID = ll.ID
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY cr.CHUONG_SO, cr.TEN_CHUONG, vtd.TEN_TOI_DANH

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            99999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            TO_NCHAR('T?NG S?') AS "ToiDanh",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM VW_PN_TOI_DANH_CHUONG vtd
        LEFT JOIN PN_LAI_LICHS ll ON vtd.PN_ID = ll.ID
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_THONG_KE_TOI_DANH;

-- =====================================================
-- Báo cáo: Th?ng kê theo lý do ân gi?m
-- =====================================================
PROCEDURE SP_THONG_KE_AN_GIAM(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR 
    SELECT 
        "TT",
        "LyDoAnGiam",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Chi ti?t t?ng lý do ân gi?m
        SELECT
        -- order by dld.ID
            ROW_NUMBER() OVER (ORDER BY ag.AG_LY_DO_AN_GIAM) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY ag.AG_LY_DO_AN_GIAM))) AS "TT",
            NVL(ag.AG_LY_DO_AN_GIAM, TO_NCHAR('Ch?a xác ??nh')) AS "LyDoAnGiam",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM AN_GIAMS ag
        LEFT JOIN PN_LAI_LICHS ll ON ag.PHAM_NHAN_ID = ll.ID
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
--        LEFT JOIN DM_LY_DO_AN_GIAMS dld ON ag.AG_LY_DO_AN_GIAM = dld.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ag.IS_DELETED = 0
          AND ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY ag.AG_LY_DO_AN_GIAM
--        GROUP BY dld.ID, dld.LDAG_TEN

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            TO_NCHAR('T?ng s?') AS "LyDoAnGiam",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM AN_GIAMS ag
        LEFT JOIN PN_LAI_LICHS ll ON ag.PHAM_NHAN_ID = ll.ID
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ag.IS_DELETED = 0
          AND ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_THONG_KE_AN_GIAM;
-- =====================================================
-- Báo cáo: Th?ng kê theo ch?a b?nh b?t bu?c
