-- =====================================================
-- Báo cáo: Th?ng kê theo nguyên nhân ch?t
-- =====================================================
PROCEDURE SP_THONG_KE_NGUYEN_NHAN_CHET(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR 
    SELECT 
        "TT",
        "NguyenNhanChet",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Chi ti?t t?ng nguyên nhân ch?t
        SELECT
            ROW_NUMBER() OVER (ORDER BY dnnc.ID) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY dnnc.ID))) AS "TT",
            NVL(dnnc.NNC_TEN, TO_NCHAR('Ch?a xác ??nh')) AS "NguyenNhanChet",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_KET_THUC_CHETS ktc
        LEFT JOIN PN_LAI_LICHS ll ON ktc.KTC_PN_LAI_LICH_ID = ll.ID
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_NGUYEN_NHAN_CHETS dnnc ON ktc.KTC_NGUYEN_NHAN_CHET_ID = dnnc.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ktc.IS_DELETED = 0
          AND ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY dnnc.ID, dnnc.NNC_TEN

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            TO_NCHAR('T?ng s?') AS "NguyenNhanChet",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_KET_THUC_CHETS ktc
        LEFT JOIN PN_LAI_LICHS ll ON ktc.KTC_PN_LAI_LICH_ID = ll.ID
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ktc.IS_DELETED = 0
          AND ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_THONG_KE_NGUYEN_NHAN_CHET;

