-- =====================================================
-- Báo cáo: Th?ng kê theo ?? tu?i
-- =====================================================
PROCEDURE SP_THONG_KE_DO_TUOI(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT
        "TT",
        "DoTuoi",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- D??i 14 tu?i
        SELECT
            1 AS SORT_ORDER,
            TO_NCHAR('1') AS "TT",
            TO_NCHAR('D??i 14 tu?i') AS "DoTuoi",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND ll.LL_NGAY_SINH IS NOT NULL
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) < 14
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        UNION ALL

        -- T? 14 ??n d??i 16 tu?i
        SELECT
            2 AS SORT_ORDER,
            TO_NCHAR('2') AS "TT",
            TO_NCHAR('T? 14 ??n d??i 16 tu?i') AS "DoTuoi",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND ll.LL_NGAY_SINH IS NOT NULL
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) >= 14
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) < 16
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        UNION ALL

        -- T? 16 ??n d??i 18 tu?i
        SELECT
            3 AS SORT_ORDER,
            TO_NCHAR('3') AS "TT",
            TO_NCHAR('T? 16 ??n d??i 18 tu?i') AS "DoTuoi",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND ll.LL_NGAY_SINH IS NOT NULL
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) >= 16
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) < 18
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        UNION ALL

        -- T? 18 ??n d??i 30 tu?i
        SELECT
            4 AS SORT_ORDER,
            TO_NCHAR('4') AS "TT",
            TO_NCHAR('T? 18 ??n d??i 30 tu?i') AS "DoTuoi",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND ll.LL_NGAY_SINH IS NOT NULL
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) >= 18
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) < 30
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        UNION ALL

        -- T? 30 ??n d??i 45 tu?i
        SELECT
            5 AS SORT_ORDER,
            TO_NCHAR('5') AS "TT",
            TO_NCHAR('T? 30 ??n d??i 45 tu?i') AS "DoTuoi",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND ll.LL_NGAY_SINH IS NOT NULL
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) >= 30
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) < 45
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        UNION ALL

        -- T? 45 ??n d??i 55 tu?i
        SELECT
            6 AS SORT_ORDER,
            TO_NCHAR('6') AS "TT",
            TO_NCHAR('T? 45 ??n d??i 55 tu?i') AS "DoTuoi",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND ll.LL_NGAY_SINH IS NOT NULL
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) >= 45
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) < 55
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        UNION ALL

        -- T? 55 ??n d??i 60 tu?i
        SELECT
            7 AS SORT_ORDER,
            TO_NCHAR('7') AS "TT",
            TO_NCHAR('T? 55 ??n d??i 60 tu?i') AS "DoTuoi",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND ll.LL_NGAY_SINH IS NOT NULL
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) >= 55
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) < 60
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        UNION ALL

        -- T? 60 ??n d??i 70 tu?i
        SELECT
            8 AS SORT_ORDER,
            TO_NCHAR('8') AS "TT",
            TO_NCHAR('T? 60 ??n d??i 70 tu?i') AS "DoTuoi",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND ll.LL_NGAY_SINH IS NOT NULL
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) >= 60
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) < 70
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        UNION ALL

        -- T? 70 tu?i tr? lên
        SELECT
            9 AS SORT_ORDER,
            TO_NCHAR('9') AS "TT",
            TO_NCHAR('T? 70 tu?i tr? lên') AS "DoTuoi",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND ll.LL_NGAY_SINH IS NOT NULL
          AND (EXTRACT(YEAR FROM SYSDATE) - TO_NUMBER(SUBSTR(ll.LL_NGAY_SINH, -4))) >= 70
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            TO_NCHAR('T?ng s?') AS "DoTuoi",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_THONG_KE_DO_TUOI;
-- =====================================================
-- Báo cáo: Th?ng kê theo ghi chú riêng
-- =====================================================
	PROCEDURE SP_THONG_KE_GHI_CHU_RIENG(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
	WITH GHI_CHU_MAPPED AS (
	    SELECT
	        ll.ID AS PHAM_NHAN_ID,
	        TO_NCHAR(LISTAGG(dgcr.GCR_TEN, ';') WITHIN GROUP (ORDER BY dgcr.GCR_TEN)) AS GHI_CHU_TEXT
	    FROM PN_LAI_LICHS ll
	    INNER JOIN DM_GHI_CHU_RIENGS dgcr
	        ON TO_NCHAR(',' || ll.LL_GHI_CHU_RIENG || ',')
	           LIKE TO_NCHAR('%,' || TO_CHAR(dgcr.ID) || ',%')
	    WHERE ll.IS_DELETED = 0
	      AND ll.LL_GHI_CHU_RIENG IS NOT NULL
	      AND LENGTH(TRIM(ll.LL_GHI_CHU_RIENG)) > 0
	    GROUP BY ll.ID
	)
    SELECT
        "TT",
        "GhiChuRieng",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Nhóm 1: Không có ghi chú riêng
        SELECT
            1 AS SORT_ORDER,
            TO_NCHAR('1') AS "TT",
            TO_NCHAR('Không có ghi chú riêng') AS "GhiChuRieng",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN ll.ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN ll.ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN ll.ID END) AS "Khac",
            COUNT(DISTINCT ll.ID) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN GHI_CHU_MAPPED gcm ON ll.ID = gcm.PHAM_NHAN_ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND gcm.GHI_CHU_TEXT IS NULL
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        UNION ALL

        -- Nhóm 2: Có ghi chú riêng
        SELECT
            1 + ROW_NUMBER() OVER (ORDER BY NLSSORT(gcm.GHI_CHU_TEXT, 'NLS_SORT=BINARY_AI')) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(1 + ROW_NUMBER() OVER (ORDER BY NLSSORT(gcm.GHI_CHU_TEXT, 'NLS_SORT=BINARY_AI')))) AS "TT",
            gcm.GHI_CHU_TEXT AS "GhiChuRieng",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN ll.ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN ll.ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN ll.ID END) AS "Khac",
            COUNT(DISTINCT ll.ID) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        INNER JOIN GHI_CHU_MAPPED gcm ON ll.ID = gcm.PHAM_NHAN_ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND gcm.GHI_CHU_TEXT IS NOT NULL
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY gcm.GHI_CHU_TEXT

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            TO_NCHAR('T?ng s?') AS "GhiChuRieng",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam' THEN ll.ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef' THEN ll.ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN ll.ID END) AS "Khac",
            COUNT(DISTINCT ll.ID) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
END SP_THONG_KE_GHI_CHU_RIENG;

--==================================--
-- Th?ng kê lý do giam riêng
--==================================--

	PROCEDURE SP_THONG_KE_LY_DO_GIAM_RIENG(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
	)
	AS
	    c1 SYS_REFCURSOR;
	BEGIN
    OPEN c1 FOR 
    SELECT 
        "TT",
        "LyDoGiamRieng",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (

 			SELECT
            ROW_NUMBER() OVER (ORDER BY dldgrpn.ID) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY dldgrpn.ID))) AS "TT",
            NVL(dldgrpn.LDGRPN_TEN, TO_NCHAR('Ch?a xác ??nh')) AS "LyDoGiamRieng",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_GIAM_RIENGS pgr 
        LEFT JOIN PN_LAI_LICHS ll ON pgr.GR_PN_LAI_LICH_ID  = ll.ID
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_LY_DO_GIAM_RIENG_PHAM_NHANS dldgrpn ON pgr.GR_LY_DO  = dldgrpn.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE pgr.IS_DELETED = 0
          AND ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY dldgrpn.ID, dldgrpn.LDGRPN_TEN 


        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            TO_NCHAR('T?ng s?') AS "LyDoGiamRieng",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM PN_GIAM_RIENGS pgr 
        LEFT JOIN PN_LAI_LICHS ll ON pgr.GR_PN_LAI_LICH_ID  = ll.ID
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_LY_DO_GIAM_RIENG_PHAM_NHANS dldgrpn ON pgr.GR_LY_DO  = dldgrpn.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE pgr.IS_DELETED = 0
          AND ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        )
    	ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
	END SP_THONG_KE_LY_DO_GIAM_RIENG;

--==================================--
-- Th?ng kê HPBS khác 
--==================================--

PROCEDURE SP_THONG_KE_HINH_PHAT_BO_SUNG_KHAC(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN

OPEN c1 FOR

WITH chi_tiet AS (

    SELECT
        ROW_NUMBER() OVER (ORDER BY dhpbs.ID) AS SORT_ORDER,

        TO_NCHAR(ROW_NUMBER() OVER (ORDER BY dhpbs.ID)) AS "TT",

        NVL(dhpbs.HPBS_TEN, TO_NCHAR('Ch?a xác ??nh')) AS "HPBSKhac",

        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam'
            THEN ll.ID END) AS "Nam",

        COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?'
            THEN ll.ID END) AS "Nu",

        COUNT(DISTINCT CASE
            WHEN NVL(dgt.GT_TEN,'Khác') NOT IN ('Nam','N?')
            THEN ll.ID END) AS "Khac",

        COUNT(DISTINCT ll.ID) AS "TongSo"

    FROM PN_HINH_PHAT_BO_SUNGS phpbs

    LEFT JOIN (
        SELECT ID, LL_DM_GIOI_TINH_ID, LL_TRAI_GIAM_ID
        FROM PN_LAI_LICHS
        WHERE IS_DELETED = 0
    ) ll
        ON phpbs.HPBS_MA_PHAM_NHAN = ll.ID

    LEFT JOIN (
        SELECT THA_PNLAI_LICH_ID, THA_NGAY_DEN_TRAI
        FROM QLPN.PN_THI_HANH_AN
        WHERE IS_DELETED = 0
    ) ptha
        ON ptha.THA_PNLAI_LICH_ID = ll.ID

    LEFT JOIN DM_GIOI_TINHS dgt
        ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        AND dgt.IS_DELETED = 0

    LEFT JOIN DM_HINH_PHAT_BO_SUNGS dhpbs
        ON phpbs.HPBS_HINH_PHAT = dhpbs.HPBS_MA
        AND dhpbs.IS_DELETED = 0

    WHERE phpbs.IS_DELETED = 0
      AND dhpbs.HPBS_MA NOT LIKE '2%'
      AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
      AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
      AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

    GROUP BY dhpbs.ID, dhpbs.HPBS_TEN
)

SELECT "TT",
        "HPBSKhac",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
FROM (
    SELECT
        SORT_ORDER,
        "TT",
        "HPBSKhac",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM chi_tiet  

    UNION ALL

    SELECT
        999,
        TO_NCHAR(NULL),          
        TO_NCHAR('T?ng s?'), 
        SUM("Nam"),
        SUM("Nu"),
        SUM("Khac"),
        SUM("TongSo")
    FROM chi_tiet
)

ORDER BY SORT_ORDER;

DBMS_SQL.RETURN_RESULT(c1);

END SP_THONG_KE_HINH_PHAT_BO_SUNG_KHAC;

 --==================================--
-- Th?ng kê h?y án
--==================================--   
	PROCEDURE SP_THONG_KE_HUY_AN(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH LY_DO_CONVERTED AS (
        SELECT
            ha.ID,
            ha.PHAM_NHAN_ID,
            DBMS_LOB.SUBSTR(ha.LY_DO_HUY, 4000, 1) AS LY_DO_HUY_TEXT
        FROM HUY_ANS ha
        WHERE ha.IS_DELETED = 0
    )
    SELECT
        "TT",
        "LyDoHuy",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Chi ti?t t?ng lý do h?y án
        SELECT
            ROW_NUMBER() OVER (ORDER BY ldc.LY_DO_HUY_TEXT) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY ldc.LY_DO_HUY_TEXT))) AS "TT",
            NVL(TO_NCHAR(ldc.LY_DO_HUY_TEXT), TO_NCHAR('Ch?a xác ??nh')) AS "LyDoHuy",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam' THEN ldc.ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?' THEN ldc.ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN ldc.ID END) AS "Khac",
            COUNT(DISTINCT ldc.ID) AS "TongSo"
        FROM LY_DO_CONVERTED ldc
        LEFT JOIN PN_LAI_LICHS ll ON ldc.PHAM_NHAN_ID = ll.ID
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY ldc.LY_DO_HUY_TEXT

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            TO_NCHAR('T?ng s?') AS "LyDoHuy",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam' THEN ldc.ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?' THEN ldc.ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN ldc.ID END) AS "Khac",
            COUNT(DISTINCT ldc.ID) AS "TongSo"
        FROM LY_DO_CONVERTED ldc
        LEFT JOIN PN_LAI_LICHS ll ON ldc.PHAM_NHAN_ID = ll.ID
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
	END SP_THONG_KE_HUY_AN;


--==================================--
-- Th?ng kê mi?n hình ph?t
--==================================--

	PROCEDURE SP_THONG_KE_TRUONG_HOP_MIEN_HINH_PHAT(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay     IN DATE   DEFAULT NULL,
    p_den_ngay    IN DATE   DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR

    WITH chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (ORDER BY dthmhp.ID)                    AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY dthmhp.ID))) AS "TT",
            NVL(dthmhp.MHP_TEN, TO_NCHAR('Ch?a xác ??nh'))           AS "TruongHopMien",

            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'Nam'
                THEN ll.ID END)                                        AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = u'N\1eef'
                THEN ll.ID END)                                        AS "Nu",
            COUNT(DISTINCT CASE
                WHEN NVL(dgt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef')
                THEN ll.ID END)                                        AS "Khac",
            COUNT(DISTINCT ll.ID)                                      AS "TongSo"

        FROM MIEN_HINH_PHATS mhp
        LEFT JOIN PN_LAI_LICHS ll
            ON mhp.PN_LAI_LICH_ID = ll.ID
            AND ll.IS_DELETED = 0
        LEFT JOIN DM_GIOI_TINHS dgt
            ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
            AND dgt.IS_DELETED = 0
        LEFT JOIN DM_TRUONG_HOP_MIEN_HINH_PHATS dthmhp
            ON mhp.MHP_TRUONG_HOP_MIEN = dthmhp.ID
            AND dthmhp.IS_DELETED = 0
        LEFT JOIN PN_THI_HANH_AN ptha
            ON ll.ID = ptha.THA_PNLAI_LICH_ID
            AND ptha.IS_DELETED = 0

        WHERE mhp.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay      IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay     IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

        GROUP BY dthmhp.ID, dthmhp.MHP_TEN
    )

    SELECT "TT", "TruongHopMien", "Nam", "Nu", "Khac", "TongSo"
    FROM (

        SELECT SORT_ORDER, "TT", "TruongHopMien", "Nam", "Nu", "Khac", "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999,
            TO_NCHAR(NULL),  
            TO_NCHAR('T?ng s?'), 
            SUM("Nam"),
            SUM("Nu"),
            SUM("Khac"),
            SUM("TongSo")
        FROM chi_tiet

    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);

END SP_THONG_KE_TRUONG_HOP_MIEN_HINH_PHAT;

--==================================--
-- Th?ng kê m?c án ph?t
--==================================--	   

PROCEDURE SP_THONG_KE_MUC_AN_PHAT(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR 
    SELECT 
        "TT",
        "MucAnPhat",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        SELECT
            ROW_NUMBER() OVER (ORDER BY dma.ID) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY dma.ID))) AS "TT",
            NVL(dma.MA_TEN_CHI_TIEU  , TO_NCHAR('Ch?a xác ??nh')) AS "MucAnPhat",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
		FROM PN_LAI_LICHS ll 
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        LEFT JOIN DM_MUC_ANS dma ON ptha.THA_MUC_AN_ID  = dma.ID 
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY dma.ID, dma.MA_TEN_CHI_TIEU 
 UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            TO_NCHAR('T?ng s?') AS "MucAnPhat",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
		FROM PN_LAI_LICHS ll 
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        LEFT JOIN DM_MUC_ANS dma ON ptha.THA_MUC_AN_ID  = dma.ID 
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
	END SP_THONG_KE_MUC_AN_PHAT;

--==================================--
-- Th?ng kê tr??ng h?p tr?n
--==================================--
	PROCEDURE SP_THONG_KE_TRUONG_HOP_TRON(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR 
    SELECT 
        "TT",
        "TruongHopTron",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (

         SELECT
            ROW_NUMBER() OVER (ORDER BY dtht.ID) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY dtht.ID))) AS "TT",
            NVL(dtht.THT_TEN, TO_NCHAR('Ch?a xác ??nh')) AS "TruongHopTron",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM TRON_TRAIS tt  
        LEFT JOIN PN_LAI_LICHS ll ON tt.PHAM_NHAN_ID    = ll.ID
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_TRUONG_HOP_TRONS dtht ON tt.TRUONG_HOP_TRON_ID    = dtht.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE tt.IS_DELETED = 0
          AND ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY dtht.ID, dtht.THT_TEN   


        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            TO_NCHAR('T?ng s?') AS "TruongHopTron",
		COUNT(CASE WHEN dgt.GT_TEN = 'Nam' THEN 1 END) AS "Nam",
		COUNT(CASE WHEN dgt.GT_TEN = 'N?' THEN 1 END) AS "Nu",
		COUNT(CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN 1 END) AS "Khac",
		COUNT(*) AS "TongSo"
        FROM TRON_TRAIS tt  
        LEFT JOIN PN_LAI_LICHS ll ON tt.PHAM_NHAN_ID    = ll.ID
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN DM_TRUONG_HOP_TRONS dtht ON tt.TRUONG_HOP_TRON_ID    = dtht.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE tt.IS_DELETED = 0
          AND ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
	END SP_THONG_KE_TRUONG_HOP_TRON;

--==================================--
-- Th?ng kê phân lo?i giam gi?
--==================================--

PROCEDURE SP_THONG_KE_PHAN_LOAI_GIAM_GIU(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN

OPEN c1 FOR
WITH chi_tiet AS (
    SELECT
        ROW_NUMBER() OVER (ORDER BY dplgg.ID) AS SORT_ORDER,

        TO_CHAR(
            ROW_NUMBER() OVER (ORDER BY dplgg.ID)
        ) AS "TT",
        NVL(dplgg.PLGG_TEN, u'Ch\01b0a x\00e1c \0111\1ecbnh') AS "PhanLoai",
        COUNT(DISTINCT CASE
            WHEN dgt.GT_TEN = 'Nam'
            THEN pl.PHAM_NHAN_ID
        END) AS "Nam",
        COUNT(DISTINCT CASE
            WHEN dgt.GT_TEN = 'N?'
            THEN pl.PHAM_NHAN_ID
        END) AS "Nu",
        COUNT(DISTINCT CASE
            WHEN NVL(dgt.GT_TEN,'Khác')
                 NOT IN ('Nam','N?')
            THEN pl.PHAM_NHAN_ID
        END) AS "Khac",
        COUNT(DISTINCT pl.PHAM_NHAN_ID) AS "TongSo"
    FROM PHAN_LOAIS pl
    LEFT JOIN PN_LAI_LICHS ll
        ON pl.PHAM_NHAN_ID = ll.ID
    LEFT JOIN DM_GIOI_TINHS dgt
        ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
    LEFT JOIN DM_PHAN_LOAI_GIAM_GIUS dplgg
        ON pl.DEN_LOAI_ID = dplgg.ID
    LEFT JOIN PN_THI_HANH_AN ptha
        ON ll.ID = ptha.THA_PNLAI_LICH_ID
    WHERE pl.IS_DELETED = 0
      AND ll.IS_DELETED = 0
      AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
      AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
      AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    GROUP BY dplgg.ID, dplgg.PLGG_TEN
)
SELECT
    "TT",
    "PhanLoai",
    "Nam",
    "Nu",
    "Khac",
    "TongSo"
FROM (

    SELECT
        SORT_ORDER,
        "TT",
        "PhanLoai",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM chi_tiet
    UNION ALL
    SELECT
        999,
        NULL,
        u'T\1ed5ng s\1ed1',

        SUM("Nam"),
        SUM("Nu"),
        SUM("Khac"),
        SUM("TongSo")

    FROM chi_tiet
)
ORDER BY SORT_ORDER;

DBMS_SQL.RETURN_RESULT(c1);

END SP_THONG_KE_PHAN_LOAI_GIAM_GIU;

--==================================--
-- Th?ng kê ph?m t?i m?i
--==================================--

PROCEDURE SP_THONG_KE_PHAM_TOI_MOI(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    WITH TOI_DANH_LIST AS (
        -- Tách danh sách t?i danh (gi?ng nh? t?i danh ? thi hành án)
        SELECT
            ptm.PHAM_NHAN_ID,
            LISTAGG(dtd.TD_TEN, ';') WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH_TEXT
        FROM PHAM_TOI_MOIS ptm
        LEFT JOIN (
            SELECT DISTINCT
                ptm2.ID AS PHAM_TOI_MOI_ID,
                TO_NUMBER(REGEXP_SUBSTR(ptm2.TOI_DANH_ID, '[^,]+', 1, LEVEL)) AS TOI_DANH_SINGLE_ID
            FROM PHAM_TOI_MOIS ptm2
            WHERE ptm2.TOI_DANH_ID IS NOT NULL
              AND TRIM(ptm2.TOI_DANH_ID) != ''
            CONNECT BY LEVEL <= LENGTH(ptm2.TOI_DANH_ID) - LENGTH(REPLACE(ptm2.TOI_DANH_ID, ',', '')) + 1
                   AND ID = PRIOR ID
                   AND PRIOR DBMS_RANDOM.VALUE IS NOT NULL
        ) td_split ON ptm.ID = td_split.PHAM_TOI_MOI_ID
        LEFT JOIN DM_TOI_DANHS dtd ON td_split.TOI_DANH_SINGLE_ID = dtd.ID
        WHERE ptm.IS_DELETED = 0
          AND ptm.TOI_DANH_ID IS NOT NULL
          AND TRIM(ptm.TOI_DANH_ID) != ''
        GROUP BY ptm.PHAM_NHAN_ID
    )
    SELECT
        "TT",
        "PhamToiMoi",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Nhóm 1: Không có ph?m t?i m?i
--        SELECT
--            1 AS SORT_ORDER,
--            TO_NCHAR('1') AS "TT",
--            TO_NCHAR('Không có ph?m t?i m?i') AS "PhamToiMoi",
--            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam' THEN ll.ID END) AS "Nam",
--            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?' THEN ll.ID END) AS "Nu",
--            COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN ll.ID END) AS "Khac",
--            COUNT(DISTINCT ll.ID) AS "TongSo"
--        FROM PN_LAI_LICHS ll
--        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
--        LEFT JOIN TOI_DANH_LIST tdl ON ll.ID = tdl.PHAM_NHAN_ID
--        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
--        WHERE ll.IS_DELETED = 0
--          AND tdl.TOI_DANH_TEXT IS NULL
--          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
--          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
--          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

--        UNION ALL

        -- Nhóm 2: Có ph?m t?i m?i - group theo t? h?p t?i danh
        SELECT
            1 + ROW_NUMBER() OVER (ORDER BY tdl.TOI_DANH_TEXT) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(1 + ROW_NUMBER() OVER (ORDER BY tdl.TOI_DANH_TEXT))) AS "TT",
            TO_NCHAR(tdl.TOI_DANH_TEXT) AS "PhamToiMoi",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam' THEN ll.ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?' THEN ll.ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN ll.ID END) AS "Khac",
            COUNT(DISTINCT ll.ID) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        INNER JOIN TOI_DANH_LIST tdl ON ll.ID = tdl.PHAM_NHAN_ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND tdl.TOI_DANH_TEXT IS NOT NULL
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY tdl.TOI_DANH_TEXT

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            TO_NCHAR('T?ng s?') AS "PhamToiMoi",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'Nam' THEN ll.ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN dgt.GT_TEN = 'N?' THEN ll.ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(dgt.GT_TEN, 'Khác') NOT IN ('Nam', 'N?') THEN ll.ID END) AS "Khac",
            COUNT(DISTINCT ll.ID) AS "TongSo"
        FROM PN_LAI_LICHS ll
        LEFT JOIN DM_GIOI_TINHS dgt ON ll.LL_DM_GIOI_TINH_ID = dgt.ID
        LEFT JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(c1);
	END SP_THONG_KE_PHAM_TOI_MOI;
-- =============================================
-- 1. Th?ng kê hoãn thi hành án
-- =============================================
PROCEDURE  SP_GET_THONG_KE_HOAN_THI_HANH_AN (
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay      IN DATE   DEFAULT NULL,
    p_den_ngay     IN DATE   DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    SELECT
        "TT",
        "LyDoHoanThiHanhAn",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Các dòng chi ti?t
        SELECT
