    FROM (
        -- Các dòng chi ti?t
        SELECT
            ROW_NUMBER() OVER (ORDER BY NVL(ldkl.LDKL_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')) AS SORT_ORDER,
