-- =============================================
-- 3. Th?ng kê tái ph?m
-- =============================================
PROCEDURE SP_GET_THONG_KE_TAI_PHAM (
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay      IN DATE   DEFAULT NULL,
    p_den_ngay     IN DATE   DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    SELECT
        "TT",
        "TinhChatToiPham",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Các dòng chi ti?t
        SELECT
            ROW_NUMBER() OVER (ORDER BY NVL(dtp.TP_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY NVL(dtp.TP_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')))) AS "TT",
            NVL(dtp.TP_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh') AS "TinhChatToiPham",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END)                                      AS "Nam",
            COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END)                                   AS "Nu",
            COUNT(CASE WHEN NVL(gt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*)                                                                              AS "TongSo"
        FROM QLPN.PN_LAI_LICHS pn
        LEFT JOIN QLPN.PN_THI_HANH_AN ptha
            ON ptha.THA_PNLAI_LICH_ID = pn.ID
           AND ptha.IS_DELETED = 0
        LEFT JOIN QLPN.DM_TAI_PHAMS dtp
            ON dtp.ID = pn.LL_TAI_PHAM
           AND NVL(dtp.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = pn.LL_DM_GIOI_TINH_ID
           AND NVL(gt.IS_DELETED, 0) = 0
        WHERE NVL(pn.IS_DELETED, 0) = 0
