-- =============================================
-- 4. Th?ng kê lý do t?m ?ình ch?
-- =============================================
PROCEDURE SP_GET_THONG_KE_TAM_DINH_CHI (
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay      IN DATE   DEFAULT NULL,
    p_den_ngay     IN DATE   DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    SELECT
        "TT",
        "LyDoTamDinhChi",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Các dòng chi ti?t
        SELECT
            ROW_NUMBER() OVER (ORDER BY NVL(dldtdc.LDTDC_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY NVL(dldtdc.LDTDC_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')))) AS "TT",
            NVL(dldtdc.LDTDC_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh') AS "LyDoTamDinhChi",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'Nam' THEN tdc.PHAM_NHAN_ID END)                                      AS "Nam",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'N\1eef' THEN tdc.PHAM_NHAN_ID END)                                   AS "Nu",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN IS NULL OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN tdc.PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT tdc.PHAM_NHAN_ID)                                                                               AS "TongSo"
        FROM QLPN.TAM_DINH_CHIS tdc
        LEFT JOIN QLPN.DM_LY_DO_TAM_DINH_CHIES dldtdc
            ON dldtdc.ID = tdc.LY_DO_SUC_KHOE_ID
           AND NVL(dldtdc.IS_DELETED, 0) = 0
        INNER JOIN QLPN.PN_LAI_LICHS pn
            ON pn.ID = tdc.PHAM_NHAN_ID
           AND pn.IS_DELETED = 0
        INNER JOIN QLPN.PN_THI_HANH_AN ptha
            ON ptha.THA_PNLAI_LICH_ID = tdc.PHAM_NHAN_ID
           AND ptha.IS_DELETED = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = pn.LL_DM_GIOI_TINH_ID
           AND gt.IS_DELETED = 0
        WHERE tdc.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR pn.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY NVL(dldtdc.LDTDC_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            u'T\1ed5ng s\1ed1'                   AS "LyDoTamDinhChi",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'Nam' THEN tdc.PHAM_NHAN_ID END)                                      AS "Nam",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'N\1eef' THEN tdc.PHAM_NHAN_ID END)                                   AS "Nu",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN IS NULL OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef') THEN tdc.PHAM_NHAN_ID END) AS "Khac",
            COUNT(DISTINCT tdc.PHAM_NHAN_ID)                                                                               AS "TongSo"
        FROM QLPN.TAM_DINH_CHIS tdc
        INNER JOIN QLPN.PN_LAI_LICHS pn
            ON pn.ID = tdc.PHAM_NHAN_ID
           AND pn.IS_DELETED = 0
        INNER JOIN QLPN.PN_THI_HANH_AN ptha
            ON ptha.THA_PNLAI_LICH_ID = tdc.PHAM_NHAN_ID
           AND ptha.IS_DELETED = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = pn.LL_DM_GIOI_TINH_ID
           AND gt.IS_DELETED = 0
        WHERE tdc.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR pn.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_TAM_DINH_CHI;


