          AND (p_trai_giam_id IS NULL OR pn.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_TIEN_SU;


-- =============================================
-- 7. Th?ng kê tình tr?ng s?c kh?e
-- =============================================
PROCEDURE SP_GET_THONG_KE_TINH_TRANG_SUC_KHOE (
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay      IN DATE   DEFAULT NULL,
    p_den_ngay     IN DATE   DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    SELECT
        "TT",
        "TinhTrangSucKhoe",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Các dòng chi ti?t
        SELECT
            ROW_NUMBER() OVER (ORDER BY NVL(dbt.BT_TEN, u'Kh\00f4ng b\1ec7nh t\1eadt')) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY NVL(dbt.BT_TEN, u'Kh\00f4ng b\1ec7nh t\1eadt')))) AS "TT",
            NVL(dbt.BT_TEN, u'Kh\00f4ng b\1ec7nh t\1eadt') AS "TinhTrangSucKhoe",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END)                                      AS "Nam",
            COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END)                                   AS "Nu",
            COUNT(CASE WHEN NVL(gt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*)                                                                              AS "TongSo"
        FROM QLPN.PN_LAI_LICHS pn
        LEFT JOIN QLPN.PN_THI_HANH_AN ptha
            ON ptha.THA_PNLAI_LICH_ID = pn.ID
           AND ptha.IS_DELETED = 0
        LEFT JOIN QLPN.DM_BENH_TATS dbt
            ON TO_NCHAR(dbt.ID) = pn.LL_BENH_HIEN_TAI
           AND NVL(dbt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = pn.LL_DM_GIOI_TINH_ID
           AND NVL(gt.IS_DELETED, 0) = 0
        WHERE NVL(pn.IS_DELETED, 0) = 0
          AND (p_trai_giam_id IS NULL OR pn.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY NVL(dbt.BT_TEN, u'Kh\00f4ng b\1ec7nh t\1eadt')

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            u'T\1ed5ng s\1ed1'                   AS "TinhTrangSucKhoe",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END)                                      AS "Nam",
            COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END)                                   AS "Nu",
            COUNT(CASE WHEN NVL(gt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*)                                                                              AS "TongSo"
        FROM QLPN.PN_LAI_LICHS pn
        LEFT JOIN QLPN.PN_THI_HANH_AN ptha
            ON ptha.THA_PNLAI_LICH_ID = pn.ID
           AND ptha.IS_DELETED = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = pn.LL_DM_GIOI_TINH_ID
           AND NVL(gt.IS_DELETED, 0) = 0
        WHERE NVL(pn.IS_DELETED, 0) = 0
          AND (p_trai_giam_id IS NULL OR pn.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_TINH_TRANG_SUC_KHOE;


-- =============================================
-- 8. Th?ng kê tr?i chuy?n ??n
-- =============================================
PROCEDURE SP_GET_THONG_KE_TRAI_CHUYEN_DEN (
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay      IN DATE   DEFAULT NULL,
    p_den_ngay     IN DATE   DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    SELECT
        "TT",
        "CacTraiChuyenDen",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Các dòng chi ti?t
        SELECT
            ROW_NUMBER() OVER (ORDER BY NVL(cq.CQ_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY NVL(cq.CQ_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')))) AS "TT",
            NVL(cq.CQ_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh') AS "CacTraiChuyenDen",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END)                                      AS "Nam",
            COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END)                                   AS "Nu",
            COUNT(CASE WHEN NVL(gt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*)                                                                              AS "TongSo"
        FROM QLPN.PN_THI_HANH_AN tha
        LEFT JOIN QLPN.PN_LAI_LICHS pn
            ON pn.ID = tha.THA_PNLAI_LICH_ID
           AND pn.IS_DELETED = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = pn.LL_DM_GIOI_TINH_ID
           AND gt.IS_DELETED = 0
        LEFT JOIN QLPN.DM_CO_QUANS cq
            ON cq.ID = tha.THA_CHUYEN_DEN_TU_ID
           AND cq.IS_DELETED = 0
        WHERE tha.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR pn.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR tha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR tha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY NVL(cq.CQ_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            u'T\1ed5ng s\1ed1'                   AS "CacTraiChuyenDen",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END)                                      AS "Nam",
            COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END)                                   AS "Nu",
            COUNT(CASE WHEN NVL(gt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*)                                                                              AS "TongSo"
        FROM QLPN.PN_THI_HANH_AN tha
        LEFT JOIN QLPN.PN_LAI_LICHS pn
            ON pn.ID = tha.THA_PNLAI_LICH_ID
           AND pn.IS_DELETED = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = pn.LL_DM_GIOI_TINH_ID
           AND gt.IS_DELETED = 0
        LEFT JOIN QLPN.DM_TRAI_GIAMS trg
            ON trg.ID = tha.THA_CHUYEN_DEN_TU_ID
           AND trg.IS_DELETED = 0
        WHERE tha.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR pn.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR tha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR tha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_TRAI_CHUYEN_DEN;


-- =============================================
-- 9. Th?ng kê trích xu?t
-- =============================================
PROCEDURE SP_GET_THONG_KE_TRICH_XUAT (
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay      IN DATE   DEFAULT NULL,
    p_den_ngay     IN DATE   DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;
BEGIN

OPEN C1 FOR
WITH chi_tiet AS (
    SELECT
        ROW_NUMBER() OVER (
            ORDER BY NVL(ld.LDTX_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')
        ) AS SORT_ORDER,
        TO_CHAR(
            ROW_NUMBER() OVER (
                ORDER BY NVL(ld.LDTX_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')
            )
        ) AS "TT",

        NVL(ld.LDTX_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh') AS "LyDoTrichXuat",

        COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'Nam'
            THEN tx.PHAM_NHAN_ID END) AS "Nam",

        COUNT(DISTINCT CASE WHEN gt.GT_TEN = u'N\1eef'
            THEN tx.PHAM_NHAN_ID END) AS "Nu",

        COUNT(DISTINCT CASE
            WHEN gt.GT_TEN IS NULL
              OR gt.GT_TEN NOT IN (u'Nam', u'N\1eef')
            THEN tx.PHAM_NHAN_ID
        END) AS "Khac",

        COUNT(DISTINCT tx.PHAM_NHAN_ID) AS "TongSo"

    FROM QLPN.TRICH_XUATS tx

    LEFT JOIN QLPN.DM_LY_DO_TRICH_XUATS ld
        ON ld.ID = tx.TX_LY_DO_ID
       AND ld.IS_DELETED = 0

    JOIN QLPN.PN_LAI_LICHS pn
        ON pn.ID = tx.PHAM_NHAN_ID
       AND pn.IS_DELETED = 0

    JOIN QLPN.PN_THI_HANH_AN ptha
        ON ptha.THA_PNLAI_LICH_ID = tx.PHAM_NHAN_ID
       AND ptha.IS_DELETED = 0

    LEFT JOIN QLPN.DM_GIOI_TINHS gt
        ON gt.ID = pn.LL_DM_GIOI_TINH_ID
       AND gt.IS_DELETED = 0

    WHERE tx.IS_DELETED = 0
      AND (p_trai_giam_id IS NULL OR pn.LL_TRAI_GIAM_ID = p_trai_giam_id)
      AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
      AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)

    GROUP BY NVL(ld.LDTX_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')
)

SELECT
    "TT",
    "LyDoTrichXuat",
    "Nam",
    "Nu",
    "Khac",
    "TongSo"
FROM (

    SELECT
        SORT_ORDER,
        "TT",
        "LyDoTrichXuat",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM chi_tiet

    UNION ALL

    SELECT
        999,
        NULL,
        u'T\1ed5ng s\1ed1',

        SUM("Nam"),
        SUM("Nu"),
        SUM("Khac"),
        SUM("TongSo")

    FROM chi_tiet

)

ORDER BY SORT_ORDER;

DBMS_SQL.RETURN_RESULT(C1);

END SP_GET_THONG_KE_TRICH_XUAT;

-- =============================================
-- 10. Th?ng kê lo?i ph?m nhân
-- =============================================
PROCEDURE SP_GET_THONG_KE_LOAI_PHAM_NHAN (
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay      IN DATE   DEFAULT NULL,
    p_den_ngay     IN DATE   DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    SELECT
        "TT",
        "PhanLoaiGiamGiu",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Các dòng chi ti?t
        SELECT
            ROW_NUMBER() OVER (ORDER BY NVL(plgg.PLGG_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY NVL(plgg.PLGG_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')))) AS "TT",
            NVL(plgg.PLGG_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh') AS "PhanLoaiGiamGiu",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END)                                      AS "Nam",
            COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END)                                   AS "Nu",
            COUNT(CASE WHEN NVL(gt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*)                                                                              AS "TongSo"
        FROM QLPN.PHAN_LOAIS pl
        LEFT JOIN QLPN.PN_LAI_LICHS pll
            ON pll.ID = pl.PHAM_NHAN_ID
           AND pll.IS_DELETED = 0
        LEFT JOIN QLPN.PN_THI_HANH_AN ptha
            ON ptha.THA_PNLAI_LICH_ID = pl.PHAM_NHAN_ID
           AND ptha.IS_DELETED = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = pll.LL_DM_GIOI_TINH_ID
           AND gt.IS_DELETED = 0
        LEFT JOIN QLPN.DM_PHAN_LOAI_GIAM_GIUS plgg
            ON plgg.ID = pl.DEN_LOAI_ID
           AND plgg.IS_DELETED = 0
        WHERE pl.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY NVL(plgg.PLGG_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')

        UNION ALL

        -- Dòng t?ng s?: CROSS JOIN ?? l?y t?ng s? nhóm + 1
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            u'T\1ed5ng s\1ed1'                   AS "PhanLoaiGiamGiu",
            COUNT(CASE WHEN gt.GT_TEN = u'Nam' THEN 1 END)                                      AS "Nam",
            COUNT(CASE WHEN gt.GT_TEN = u'N\1eef' THEN 1 END)                                   AS "Nu",
            COUNT(CASE WHEN NVL(gt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*)                                                                              AS "TongSo"
        FROM QLPN.PHAN_LOAIS pl
        LEFT JOIN QLPN.PN_LAI_LICHS pll
            ON pll.ID = pl.PHAM_NHAN_ID
           AND pll.IS_DELETED = 0
        LEFT JOIN QLPN.PN_THI_HANH_AN ptha
            ON ptha.THA_PNLAI_LICH_ID = pl.PHAM_NHAN_ID
           AND ptha.IS_DELETED = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = pll.LL_DM_GIOI_TINH_ID
           AND gt.IS_DELETED = 0
        LEFT JOIN QLPN.DM_PHAN_LOAI_GIAM_GIUS plgg
            ON plgg.ID = pl.DEN_LOAI_ID
           AND plgg.IS_DELETED = 0
        WHERE pl.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_LOAI_PHAM_NHAN;

-- =============================================
-- 11. Th?ng kê lý do khen th??ng
-- =============================================
PROCEDURE SP_GET_THONG_KE_LY_DO_KHEN_THUONG (
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay      IN DATE   DEFAULT NULL,
    p_den_ngay     IN DATE   DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    WITH chi_tiet AS (
        SELECT
            ROW_NUMBER() OVER (
                ORDER BY NVL(ldk.LDK_TEN, TO_NCHAR('Không xác ??nh'))
            ) AS SORT_ORDER,
            TO_CHAR(ROW_NUMBER() OVER (
                ORDER BY NVL(ldk.LDK_TEN, TO_NCHAR('Không xác ??nh'))
            )) AS "TT",
            NVL(ldk.LDK_TEN, TO_NCHAR('Không xác ??nh'))                         AS "LyDoKhenThuong",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = TO_NCHAR('Nam') THEN pll.ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN gt.GT_TEN = TO_NCHAR('N?')  THEN pll.ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(gt.GT_TEN, TO_NCHAR('Khác'))
                                      NOT IN (TO_NCHAR('Nam'), TO_NCHAR('N?'))
                                 THEN pll.ID END)                                 AS "Khac",
            COUNT(DISTINCT pll.ID)                                                AS "TongSo"
        FROM QLPN.KHEN_THUONGS kt
        LEFT JOIN JSON_TABLE(
            kt.MA_LY_DO_KHEN_ID, '$[*]'
            COLUMNS (LDK_ID NUMBER PATH '$')
        ) jt ON 1 = 1
        JOIN QLPN.DM_LY_DO_KHENS ldk
            ON ldk.ID = jt.LDK_ID
           AND ldk.IS_DELETED = 0
        LEFT JOIN QLPN.PN_LAI_LICHS pll
            ON pll.ID = kt.PHAM_NHAN_ID
           AND pll.IS_DELETED = 0
        LEFT JOIN QLPN.PN_THI_HANH_AN ptha
            ON ptha.THA_PNLAI_LICH_ID = kt.PHAM_NHAN_ID
           AND ptha.IS_DELETED = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS gt
            ON gt.ID = pll.LL_DM_GIOI_TINH_ID
           AND gt.IS_DELETED = 0
        WHERE kt.IS_DELETED = 0 
          AND (p_trai_giam_id IS NULL OR pll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay  IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY NVL(ldk.LDK_TEN, TO_NCHAR('Không xác ??nh'))
    )
    SELECT "TT", "LyDoKhenThuong", "Nam", "Nu", "Khac", "TongSo"
    FROM (
        SELECT SORT_ORDER, "TT", "LyDoKhenThuong", "Nam", "Nu", "Khac", "TongSo"
        FROM chi_tiet

        UNION ALL

        SELECT
            999                                             AS SORT_ORDER,
            NULL									AS "TT",
            TO_NCHAR('T?ng s?')                             AS "LyDoKhenThuong",
            (SELECT SUM("Nam")    FROM chi_tiet)            AS "Nam",
            (SELECT SUM("Nu")     FROM chi_tiet)            AS "Nu",
            (SELECT SUM("Khac")   FROM chi_tiet)            AS "Khac",
            (SELECT SUM("TongSo") FROM chi_tiet)            AS "TongSo"
        FROM DUAL
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_LY_DO_KHEN_THUONG;

-- =============================================
-- 12. Th?ng kê theo ngày ??n tr?i
-- =============================================

PROCEDURE SP_GET_THONG_KE_NGAY_DEN_TRAI(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;  
BEGIN 
    OPEN C1 FOR
    WITH base AS (
        SELECT
            pn.ID AS PN_ID,
            EXTRACT(YEAR FROM tha.THA_NGAY_DEN_TRAI) AS NAM,
            EXTRACT(MONTH FROM tha.THA_NGAY_DEN_TRAI) AS THANG,
            dgt.GT_TEN
        FROM PN_THI_HANH_AN tha
        LEFT JOIN (
            SELECT ID, LL_DM_GIOI_TINH_ID, LL_TRAI_GIAM_ID
            FROM PN_LAI_LICHS
            WHERE IS_DELETED = 0
        ) pn ON pn.ID = tha.THA_PNLAI_LICH_ID
        LEFT JOIN DM_GIOI_TINHS dgt
            ON pn.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
        WHERE tha.IS_DELETED = 0
            AND (p_trai_giam_id IS NULL OR pn.LL_TRAI_GIAM_ID = p_trai_giam_id)
            AND (p_tu_ngay IS NULL OR tha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
            AND (p_den_ngay IS NULL OR tha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    ),

    nam_rank AS (
        SELECT DISTINCT
            NAM,
            DENSE_RANK() OVER (ORDER BY NAM DESC) AS NAM_STT
        FROM base
    )

    SELECT
        "TT",
        "NamThang",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Header n?m
        SELECT
            nr.NAM_STT AS SORT_ORDER,
            CASE nr.NAM_STT
                WHEN 1 THEN TO_NCHAR('I')
                WHEN 2 THEN TO_NCHAR('II')
                WHEN 3 THEN TO_NCHAR('III')
                WHEN 4 THEN TO_NCHAR('IV')
                WHEN 5 THEN TO_NCHAR('V')
                WHEN 6 THEN TO_NCHAR('VI')
                WHEN 7 THEN TO_NCHAR('VII')
                WHEN 8 THEN TO_NCHAR('VIII')
                WHEN 9 THEN TO_NCHAR('IX')
                WHEN 10 THEN TO_NCHAR('X')
                WHEN 11 THEN TO_NCHAR('XI')
                WHEN 12 THEN TO_NCHAR('XII')
                WHEN 13 THEN TO_NCHAR('XIII')
                WHEN 14 THEN TO_NCHAR('XIV')
                WHEN 15 THEN TO_NCHAR('XV')
                WHEN 16 THEN TO_NCHAR('XVI')
                WHEN 17 THEN TO_NCHAR('XVII')
                WHEN 18 THEN TO_NCHAR('XVIII')
                WHEN 19 THEN TO_NCHAR('XIX')
                WHEN 20 THEN TO_NCHAR('XX')
            END AS "TT",
            TO_NCHAR('N?M ' || nr.NAM) AS "NamThang",
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'Nam' THEN b.PN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'N\1eef' THEN b.PN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(b.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN b.PN_ID END) AS "Khac",
            COUNT(DISTINCT b.PN_ID) AS "TongSo"
        FROM base b
        JOIN nam_rank nr ON b.NAM = nr.NAM
        GROUP BY nr.NAM_STT, nr.NAM

        UNION ALL

        -- Chi ti?t tháng
        SELECT
            nr.NAM_STT + (ROW_NUMBER() OVER (PARTITION BY b.NAM ORDER BY b.THANG)) * 0.001 AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (PARTITION BY b.NAM ORDER BY b.THANG))) AS "TT",
            TO_NCHAR('Tháng ' || LPAD(b.THANG, 2, '0')) AS "NamThang",
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'Nam' THEN b.PN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'N\1eef' THEN b.PN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(b.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN b.PN_ID END) AS "Khac",
            COUNT(DISTINCT b.PN_ID) AS "TongSo"
        FROM base b
        JOIN nam_rank nr ON b.NAM = nr.NAM
        GROUP BY nr.NAM_STT, b.NAM, b.THANG
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_NGAY_DEN_TRAI;

-- =============================================
-- Th?ng kê theo ngày ra tr?i
-- =============================================
PROCEDURE SP_GET_THONG_KE_NGAY_RA_TRAI(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;  
BEGIN 
    OPEN C1 FOR
    WITH base AS (
        SELECT
            ll.ID AS PN_ID,
            EXTRACT(YEAR FROM tha.THA_NGAY_HET_HAN) AS NAM,
            EXTRACT(MONTH FROM tha.THA_NGAY_HET_HAN) AS THANG,
            dgt.GT_TEN
        FROM PN_THI_HANH_AN tha
        LEFT JOIN (
            SELECT ID, LL_DM_GIOI_TINH_ID, LL_TRAI_GIAM_ID
            FROM PN_LAI_LICHS
            WHERE IS_DELETED = 0
        ) ll ON ll.ID = tha.THA_PNLAI_LICH_ID
        LEFT JOIN DM_GIOI_TINHS dgt
            ON ll.LL_DM_GIOI_TINH_ID = dgt.ID AND dgt.IS_DELETED = 0
        WHERE tha.IS_DELETED = 0
            AND tha.THA_NGAY_HET_HAN IS NOT NULL
            AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
            AND (p_tu_ngay IS NULL OR tha.THA_NGAY_HET_HAN >= p_tu_ngay)
            AND (p_den_ngay IS NULL OR tha.THA_NGAY_HET_HAN <= p_den_ngay)
    ),

    nam_rank AS (
        SELECT DISTINCT
            NAM,
            DENSE_RANK() OVER (ORDER BY NAM DESC) AS NAM_STT
        FROM base
    )

    SELECT
        "TT",
        "NamThang",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Header n?m
        SELECT
            nr.NAM_STT AS SORT_ORDER,
            CASE nr.NAM_STT
                WHEN 1 THEN TO_NCHAR('I')
                WHEN 2 THEN TO_NCHAR('II')
                WHEN 3 THEN TO_NCHAR('III')
                WHEN 4 THEN TO_NCHAR('IV')
                WHEN 5 THEN TO_NCHAR('V')
                WHEN 6 THEN TO_NCHAR('VI')
                WHEN 7 THEN TO_NCHAR('VII')
                WHEN 8 THEN TO_NCHAR('VIII')
                WHEN 9 THEN TO_NCHAR('IX')
                WHEN 10 THEN TO_NCHAR('X')
                WHEN 11 THEN TO_NCHAR('XI')
                WHEN 12 THEN TO_NCHAR('XII')
                WHEN 13 THEN TO_NCHAR('XIII')
                WHEN 14 THEN TO_NCHAR('XIV')
                WHEN 15 THEN TO_NCHAR('XV')
                WHEN 16 THEN TO_NCHAR('XVI')
                WHEN 17 THEN TO_NCHAR('XVII')
                WHEN 18 THEN TO_NCHAR('XVIII')
                WHEN 19 THEN TO_NCHAR('XIX')
                WHEN 20 THEN TO_NCHAR('XX')
            END AS "TT",
            TO_NCHAR('N?M ' || nr.NAM) AS "NamThang",
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'Nam' THEN b.PN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'N\1eef' THEN b.PN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(b.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN b.PN_ID END) AS "Khac",
            COUNT(DISTINCT b.PN_ID) AS "TongSo"
        FROM base b
        JOIN nam_rank nr ON b.NAM = nr.NAM
        GROUP BY nr.NAM_STT, nr.NAM

        UNION ALL

        -- Chi ti?t tháng
        SELECT
            nr.NAM_STT + (ROW_NUMBER() OVER (PARTITION BY b.NAM ORDER BY b.THANG)) * 0.001 AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (PARTITION BY b.NAM ORDER BY b.THANG))) AS "TT",
            TO_NCHAR('Tháng ' || LPAD(b.THANG, 2, '0')) AS "NamThang",
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'Nam' THEN b.PN_ID END) AS "Nam",
            COUNT(DISTINCT CASE WHEN b.GT_TEN = u'N\1eef' THEN b.PN_ID END) AS "Nu",
            COUNT(DISTINCT CASE WHEN NVL(b.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN b.PN_ID END) AS "Khac",
            COUNT(DISTINCT b.PN_ID) AS "TongSo"
        FROM base b
        JOIN nam_rank nr ON b.NAM = nr.NAM
        GROUP BY nr.NAM_STT, b.NAM, b.THANG
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_NGAY_RA_TRAI;


-- =============================================
-- Th?ng kê hình ph?t b? sung là ti?n
-- =============================================
PROCEDURE SP_THONG_KE_HINH_PHAT_BO_SUNG_TIEN(
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
)
AS
    c1 SYS_REFCURSOR;
BEGIN
    OPEN c1 FOR
    SELECT
        "TT",
        "HinhPhatBoSung",
        "SoPN",
        "TongTienPhat",
        "ThucHienTruocKhiXu",
        "ThucHienSauKhiXu",
        "ThucHienKhiCHAPT",
        "TongThucHien",
        "NopTaiTrai",
        "ChuaThucHien"
    FROM (
        -- Chi ti?t t?ng lo?i hình ph?t b? sung
        SELECT
            ROW_NUMBER() OVER (ORDER BY dhpbs.ID) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY dhpbs.ID))) AS "TT",
            NVL(dhpbs.HPBS_TEN, TO_NCHAR('Ch?a xác ??nh')) AS "HinhPhatBoSung",
            COUNT(DISTINCT hpbs.HPBS_MA_PHAM_NHAN) AS "SoPN",
            SUM(NVL(hpbs.HPBS_TONG_TIEN_PHAT, NULL)) AS "TongTienPhat"
            ,SUM( CASE
		            WHEN pb.BL_NGAY_NOP < ptha.THA_NGAY_BAN_AN
		            THEN pb.BL_SO_TIEN
		            ELSE NULL
       			 END ) AS "ThucHienTruocKhiXu"
            ,SUM( CASE
		            WHEN ptha.THA_NGAY_BAN_AN <= pb.BL_NGAY_NOP
		             AND pb.BL_NGAY_NOP < ptha.THA_NGAY_DEN_TRAI
		            THEN pb.BL_SO_TIEN
		            ELSE NULL
		        END ) AS "ThucHienSauKhiXu"
    		,SUM(CASE
		            WHEN pb.BL_NGAY_NOP IS NULL
		              OR pb.BL_NGAY_NOP >= ptha.THA_NGAY_DEN_TRAI
		            THEN pb.BL_SO_TIEN
		            ELSE NULL
                END ) AS "ThucHienKhiCHAPT"
		    ,SUM(CASE
		            WHEN pb.BL_NGAY_NOP < ptha.THA_NGAY_BAN_AN
		              OR ( ptha.THA_NGAY_BAN_AN <= pb.BL_NGAY_NOP
		                AND pb.BL_NGAY_NOP < ptha.THA_NGAY_DEN_TRAI)
		              OR (  pb.BL_NGAY_NOP IS NULL
		                 OR pb.BL_NGAY_NOP >= ptha.THA_NGAY_DEN_TRAI)
		            THEN pb.BL_SO_TIEN
		            ELSE NULL
		        END ) AS "TongThucHien"
		    ,SUM(CASE
		            WHEN pb.BL_NOP_TAI_CO_QUAN IS NOT NULL 
		            	AND ( pb.BL_NGAY_NOP IS NULL OR pb.BL_NGAY_NOP >= ptha.THA_NGAY_DEN_TRAI)
		            THEN pb.BL_SO_TIEN
		            ELSE NULL
		        END ) AS "NopTaiTrai"
            ,SUM(NVL(hpbs.HPBS_TONG_TIEN_CON_LAI, NULL)) AS "ChuaThucHien"
        FROM PN_HINH_PHAT_BO_SUNGS hpbs
        LEFT JOIN PN_BIENLAIES pb ON pb.HPBS_ID = hpbs.ID AND pb.IS_DELETED = 0
        LEFT JOIN (SELECT  ID, LL_DM_GIOI_TINH_ID, LL_TRAI_GIAM_ID
        		   FROM PN_LAI_LICHS
        		   WHERE IS_DELETED = 0) ll ON hpbs.HPBS_MA_PHAM_NHAN = ll.ID
		LEFT JOIN (
			  SELECT THA_PNLAI_LICH_ID, THA_NGAY_DEN_TRAI, THA_NGAY_BAN_AN
			  FROM QLPN.PN_THI_HANH_AN
			  WHERE IS_DELETED = 0
			) ptha ON ptha.THA_PNLAI_LICH_ID = ll.ID
        LEFT JOIN DM_HINH_PHAT_BO_SUNGS dhpbs ON hpbs.HPBS_HINH_PHAT = dhpbs.HPBS_MA 
        									  AND dhpbs.IS_DELETED = 0
        WHERE hpbs.IS_DELETED = 0 
          AND dhpbs.HPBS_MA LIKE '2%'
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY dhpbs.ID, dhpbs.HPBS_TEN
     )
	ORDER BY SORT_ORDER;
    DBMS_SQL.RETURN_RESULT(c1);
END SP_THONG_KE_HINH_PHAT_BO_SUNG_TIEN;

-- =============================================
-- 14. Th?ng kê tôn giáo
-- =============================================

	PROCEDURE SP_GET_THONG_KE_TON_GIAO (
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay      IN DATE   DEFAULT NULL,
    p_den_ngay     IN DATE   DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    SELECT
        "TT",
        "TonGiao",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Các dòng chi ti?t
        SELECT
            ROW_NUMBER() OVER (ORDER BY
                CASE WHEN dtg.TG_TEN IS NOT NULL
                     THEN u'C\00f3 t\00f4n gi\00e1o'
                     ELSE u'Kh\00f4ng c\00f3 t\00f4n gi\00e1o'
                END
            ) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY
                CASE WHEN dtg.TG_TEN IS NOT NULL
                     THEN u'C\00f3 t\00f4n gi\00e1o'
                     ELSE u'Kh\00f4ng c\00f3 t\00f4n gi\00e1o'
                END
            ))) AS "TT",
            CASE WHEN dtg.TG_TEN IS NOT NULL
                 THEN u'C\00f3 t\00f4n gi\00e1o'
                 ELSE u'Kh\00f4ng c\00f3 t\00f4n gi\00e1o'
            END AS "TonGiao",
            COUNT(CASE WHEN dgt.GT_TEN = u'Nam' THEN 1 END)                                      AS "Nam",
            COUNT(CASE WHEN dgt.GT_TEN = u'N\1eef' THEN 1 END)                                   AS "Nu",
            COUNT(CASE WHEN NVL(dgt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*)                                                                               AS "TongSo"
        FROM QLPN.PN_LAI_LICHS ll
        LEFT JOIN QLPN.PN_THI_HANH_AN ptha
            ON ptha.THA_PNLAI_LICH_ID = ll.ID
           AND ptha.IS_DELETED = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS dgt
            ON dgt.ID = ll.LL_DM_GIOI_TINH_ID
           AND dgt.IS_DELETED = 0
        LEFT JOIN QLPN.DM_TON_GIAOS dtg
            ON dtg.ID = ll.LL_DM_TON_GIAO_ID
           AND dtg.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY
            CASE WHEN dtg.TG_TEN IS NOT NULL
                 THEN u'C\00f3 t\00f4n gi\00e1o'
                 ELSE u'Kh\00f4ng c\00f3 t\00f4n gi\00e1o'
            END

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            u'T\1ed5ng s\1ed1'                   AS "TonGiao",
            COUNT(CASE WHEN dgt.GT_TEN = u'Nam' THEN 1 END)                                      AS "Nam",
            COUNT(CASE WHEN dgt.GT_TEN = u'N\1eef' THEN 1 END)                                   AS "Nu",
            COUNT(CASE WHEN NVL(dgt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*)                                                                               AS "TongSo"
        FROM QLPN.PN_LAI_LICHS ll
        LEFT JOIN QLPN.PN_THI_HANH_AN ptha
            ON ptha.THA_PNLAI_LICH_ID = ll.ID
           AND ptha.IS_DELETED = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS dgt
            ON dgt.ID = ll.LL_DM_GIOI_TINH_ID
           AND dgt.IS_DELETED = 0
        LEFT JOIN QLPN.DM_TON_GIAOS dtg
            ON dtg.ID = ll.LL_DM_TON_GIAO_ID
           AND dtg.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
END SP_GET_THONG_KE_TON_GIAO;

-- =============================================
-- 15. Th?ng kê lo?i ??i t??ng:
-- =============================================
PROCEDURE SP_GET_THONG_KE_LOAI_DOI_TUONG (
    p_trai_giam_id IN NUMBER DEFAULT NULL,
    p_tu_ngay      IN DATE   DEFAULT NULL,
    p_den_ngay     IN DATE   DEFAULT NULL
)
AS
    C1 SYS_REFCURSOR;
BEGIN
    OPEN C1 FOR
    SELECT
        "TT",
        "LoaiDoiTuong",
        "Nam",
        "Nu",
        "Khac",
        "TongSo"
    FROM (
        -- Các dòng chi ti?t
        SELECT
            ROW_NUMBER() OVER (ORDER BY NVL(dldt.LDT_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')) AS SORT_ORDER,
            TO_NCHAR(TO_CHAR(ROW_NUMBER() OVER (ORDER BY NVL(dldt.LDT_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')))) AS "TT",
            NVL(dldt.LDT_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh') AS "LoaiDoiTuong",
            COUNT(CASE WHEN dgt.GT_TEN = u'Nam' THEN 1 END)                                      AS "Nam",
            COUNT(CASE WHEN dgt.GT_TEN = u'N\1eef' THEN 1 END)                                   AS "Nu",
            COUNT(CASE WHEN NVL(dgt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*)                                                                               AS "TongSo"
        FROM QLPN.PN_LAI_LICHS ll
        LEFT JOIN QLPN.PN_THI_HANH_AN ptha
            ON ptha.THA_PNLAI_LICH_ID = ll.ID
           AND ptha.IS_DELETED = 0
        LEFT JOIN QLPN.DM_LOAI_DOI_TUONGS dldt
            ON dldt.ID = ptha.THA_DOI_TUONG
           AND dldt.IS_DELETED = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS dgt
            ON dgt.ID = ll.LL_DM_GIOI_TINH_ID
           AND dgt.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
        GROUP BY NVL(dldt.LDT_TEN, u'Kh\00f4ng x\00e1c \0111\1ecbnh')

        UNION ALL

        -- Dòng t?ng s?
        SELECT
            999 AS SORT_ORDER,
            TO_NCHAR('') AS "TT",
            u'T\1ed5ng s\1ed1'                   AS "LoaiDoiTuong",
            COUNT(CASE WHEN dgt.GT_TEN = u'Nam' THEN 1 END)                                      AS "Nam",
            COUNT(CASE WHEN dgt.GT_TEN = u'N\1eef' THEN 1 END)                                   AS "Nu",
            COUNT(CASE WHEN NVL(dgt.GT_TEN, u'Kh\00e1c') NOT IN (u'Nam', u'N\1eef') THEN 1 END) AS "Khac",
            COUNT(*)                                                                               AS "TongSo"
        FROM QLPN.PN_LAI_LICHS ll
        LEFT JOIN QLPN.PN_THI_HANH_AN ptha
            ON ptha.THA_PNLAI_LICH_ID = ll.ID
           AND ptha.IS_DELETED = 0
        LEFT JOIN QLPN.DM_LOAI_DOI_TUONGS dldt
            ON dldt.ID = ptha.THA_DOI_TUONG
           AND dldt.IS_DELETED = 0
        LEFT JOIN QLPN.DM_GIOI_TINHS dgt
            ON dgt.ID = ll.LL_DM_GIOI_TINH_ID
           AND dgt.IS_DELETED = 0
        WHERE ll.IS_DELETED = 0
          AND (p_trai_giam_id IS NULL OR ll.LL_TRAI_GIAM_ID = p_trai_giam_id)
          AND (p_tu_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI >= p_tu_ngay)
          AND (p_den_ngay IS NULL OR ptha.THA_NGAY_DEN_TRAI <= p_den_ngay)
    )
    ORDER BY SORT_ORDER;

    DBMS_SQL.RETURN_RESULT(C1);
	END SP_GET_THONG_KE_LOAI_DOI_TUONG;

END PKG_BAO_CAO_THONG_KE;





