    PROCEDURE CAC_DOT(
        p_ten_trai_giam   IN  NVARCHAR2 DEFAULT NULL,
        p_tu_ngay         IN  NVARCHAR2 DEFAULT NULL,
        p_den_ngay        IN  NVARCHAR2 DEFAULT NULL
    ) AS
    BEGIN
        QLPN.SP_GET_TK_CAC_DOT_DAC_XA(p_ten_trai_giam, p_tu_ngay, p_den_ngay);
    END CAC_DOT;

END PKG_DAC_XA_THONG_KE;




/
--------------------------------------------------------
--  DDL for Package Body PKG_GTH_BATCH_V6
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "QLPN"."PKG_GTH_BATCH_V6" 
AS
    C_LAN_DAU_TT    CONSTANT NVARCHAR2(100) := TO_NCHAR('Ä?á»§ Ä?K - XÃ©t láº§n Ä‘áº§u - ThÃ´ng thÆ°á»?ng');
    C_LAN_DAU_DB    CONSTANT NVARCHAR2(100) := TO_NCHAR('Ä?á»§ Ä?K - XÃ©t láº§n Ä‘áº§u - Ä?áº·c biá»‡t');
    C_DUNG_DOT      CONSTANT NVARCHAR2(100) := TO_NCHAR('Ä?á»§ Ä?K - Ä?Ã£ giáº£m Ã¡n - Ä?Ãºng Ä‘á»£t');
    C_DAY_DOT       CONSTANT NVARCHAR2(100) := TO_NCHAR('Ä?á»§ Ä?K - Ä?Ã£ giáº£m Ã¡n - Ä?Æ°á»£c Ä‘áº©y Ä‘á»£t');
    C_KHONG_DU      CONSTANT NVARCHAR2(100) := TO_NCHAR('KhÃ´ng Ä‘á»§ Ä?K vá»? thá»?i gian');
    C_KHONG_DU_XLCT CONSTANT NVARCHAR2(100) := TO_NCHAR('KhÃ´ng Ä‘á»§ Ä?K xáº¿p loáº¡i');

    FUNCTION GET_DOT(p_ngay IN DATE) RETURN NUMBER DETERMINISTIC IS
        v_thang NUMBER;
        v_ngay_in NUMBER;
    BEGIN
        v_thang := EXTRACT(MONTH FROM p_ngay);
        v_ngay_in := EXTRACT(DAY FROM p_ngay);
        IF v_thang < 4 OR (v_thang = 4 AND v_ngay_in < 30) THEN RETURN 1;
        ELSIF v_thang < 9 OR (v_thang = 9 AND v_ngay_in < 2) THEN RETURN 2;
        ELSE RETURN 3;
        END IF;
    END GET_DOT;

    FUNCTION GET_NGAY_DOT(p_nam IN NUMBER, p_dot IN NUMBER) RETURN DATE DETERMINISTIC IS
    BEGIN
        CASE p_dot
            WHEN 1 THEN RETURN TO_DATE('01/01/' || p_nam, 'DD/MM/YYYY');
            WHEN 2 THEN RETURN TO_DATE('30/04/' || p_nam, 'DD/MM/YYYY');
            WHEN 3 THEN RETURN TO_DATE('02/09/' || p_nam, 'DD/MM/YYYY');
            ELSE RETURN NULL;
        END CASE;
    END GET_NGAY_DOT;

    FUNCTION GET_NGAY_DAY_DOT(p_ngay_giam IN DATE) RETURN DATE DETERMINISTIC IS
        v_dot NUMBER;
        v_nam NUMBER;
    BEGIN
        v_dot := GET_DOT(p_ngay_giam);
        v_nam := EXTRACT(YEAR FROM p_ngay_giam);
        CASE v_dot
            WHEN 1 THEN RETURN GET_NGAY_DOT(v_nam, 3);
            WHEN 2 THEN RETURN GET_NGAY_DOT(v_nam + 1, 1);
            WHEN 3 THEN RETURN GET_NGAY_DOT(v_nam + 1, 2);
            ELSE RETURN NULL;
        END CASE;
    END GET_NGAY_DAY_DOT;

    PROCEDURE PARSE_AN_PHAT_TO_YMD(
        p_an_phat IN NVARCHAR2,
        p_nam OUT NUMBER,
        p_thang OUT NUMBER,
        p_ngay OUT NUMBER
    ) IS
        v_text  NVARCHAR2(500);
        v_lower NVARCHAR2(1000);
        v_pos   NUMBER;
        v_num   NVARCHAR2(20);
    BEGIN
        p_nam := 0; p_thang := 0; p_ngay := 0;
        v_text := TRIM(p_an_phat);
        v_lower := LOWER(v_text);

        IF v_lower LIKE '%chung th%n%gi%m%30%' THEN p_nam := 30; RETURN; END IF;
        IF v_lower LIKE '%chung th%n%gi%m%20%' THEN p_nam := 20; RETURN; END IF;
        IF v_lower LIKE '%chung th%n%' OR v_lower LIKE '%t%h%nh%' THEN RETURN; END IF;

        v_pos := INSTR(v_text, TO_NCHAR('nÄƒm'));
        IF v_pos > 0 THEN
            v_num := TRIM(REGEXP_SUBSTR(SUBSTR(v_text, 1, v_pos - 1), '\d+', 1, 1, NULL, 0));
            p_nam := NVL(TO_NUMBER(v_num), 0);
            v_text := TRIM(SUBSTR(v_text, v_pos + LENGTH(TO_NCHAR('nÄƒm'))));
        END IF;

        v_pos := INSTR(v_text, TO_NCHAR('thÃ¡ng'));
        IF v_pos > 0 THEN
            v_num := TRIM(REGEXP_SUBSTR(SUBSTR(v_text, 1, v_pos - 1), '\d+', 1, 1, NULL, 0));
            p_thang := NVL(TO_NUMBER(v_num), 0);
            v_text := TRIM(SUBSTR(v_text, v_pos + LENGTH(TO_NCHAR('thÃ¡ng'))));
        END IF;

        v_pos := INSTR(v_text, TO_NCHAR('ngÃ y'));
        IF v_pos > 0 THEN
            v_num := TRIM(REGEXP_SUBSTR(SUBSTR(v_text, 1, v_pos - 1), '\d+', 1, 1, NULL, 0));
            p_ngay := NVL(TO_NUMBER(v_num), 0);
        END IF;
    EXCEPTION WHEN OTHERS THEN p_nam := 0; p_thang := 0; p_ngay := 0;
    END PARSE_AN_PHAT_TO_YMD;

    FUNCTION TINH_CON_LAI(
        p_ap_nam IN NUMBER, p_ap_thang IN NUMBER, p_ap_ngay IN NUMBER,
        p_dg_nam IN NUMBER, p_dg_thang IN NUMBER, p_dg_ngay IN NUMBER,
        p_dch_nam IN NUMBER, p_dch_thang IN NUMBER, p_dch_ngay IN NUMBER
    ) RETURN NUMBER IS
    BEGIN
        DECLARE
            v_tong_ap  NUMBER := NVL(p_ap_nam,0)*365  + NVL(p_ap_thang,0)*30  + NVL(p_ap_ngay,0);
            v_tong_dg  NUMBER := NVL(p_dg_nam,0)*365  + NVL(p_dg_thang,0)*30  + NVL(p_dg_ngay,0);
            v_tong_dch NUMBER := NVL(p_dch_nam,0)*365 + NVL(p_dch_thang,0)*30 + NVL(p_dch_ngay,0);
        BEGIN
            IF v_tong_ap - v_tong_dg - v_tong_dch <= 0 THEN RETURN 0; END IF;
            RETURN v_tong_ap - v_tong_dg - v_tong_dch;
        END;
    END TINH_CON_LAI;

    FUNCTION PROCESS_ALL(
        p_ky_giam_id IN NUMBER,
        p_ngay_xet IN DATE
    ) RETURN QLPN.TBL_KET_QUA_BATCH
    IS
        v_result QLPN.TBL_KET_QUA_BATCH := QLPN.TBL_KET_QUA_BATCH();
        v_start TIMESTAMP := SYSTIMESTAMP;
        v_nam_xet NUMBER := EXTRACT(YEAR FROM p_ngay_xet);
        v_count NUMBER := 0;

        TYPE t_num_list IS TABLE OF NUMBER INDEX BY PLS_INTEGER;
        TYPE t_date_list IS TABLE OF DATE INDEX BY PLS_INTEGER;
        TYPE t_str_list IS TABLE OF NVARCHAR2(4000) INDEX BY PLS_INTEGER;

        v_pn_ids       t_num_list;
        v_is_dac_biet  t_num_list;
        v_so_lan_giam  t_num_list;
        v_ngay_xet_gan t_date_list;
        v_an_phat_text t_str_list;
        v_ngay_bat     t_date_list;

        v_tong_giam_nam   t_num_list;
        v_tong_giam_thang t_num_list;
        v_tong_giam_ngay  t_num_list;
        v_da_ch_nam       t_num_list;
        v_da_ch_thang     t_num_list;
        v_da_ch_ngay      t_num_list;
        v_sl_nam_giam     t_num_list;

        v_fetch_pn_ids  t_num_list;
        v_fetch_vals    t_num_list;
        v_fetch_vals2   t_num_list;
        v_fetch_vals3   t_num_list;
        v_fetch_dates   t_date_list;
        v_fetch_text    t_str_list;

        TYPE t_idx_map IS TABLE OF PLS_INTEGER INDEX BY PLS_INTEGER;
        v_pn_index_map t_idx_map;

        v_con_lai_ngay NUMBER;
        v_dieu_kien_tg NVARCHAR2(500);
        v_dieu_kien_xlct NVARCHAR2(500);

        TYPE t_ref_cursor IS REF CURSOR;
        v_cursor t_ref_cursor;
    BEGIN
        DBMS_OUTPUT.PUT_LINE('=== V6 PROCESS START ===');
        DBMS_OUTPUT.PUT_LINE('Ky giam: ' || p_ky_giam_id || ' | Ngay xet: ' || TO_CHAR(p_ngay_xet,'DD/MM/YYYY'));

        -- BÆ¯á»šC 1: Danh sÃ¡ch pháº¡m nhÃ¢n + Ä‘áº·c biá»‡t
        OPEN v_cursor FOR
            SELECT ll.ID, FN_IS_TRUONG_HOP_DAC_BIET(ll.ID, p_ky_giam_id)
            FROM PN_LAI_LICHS ll
            JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
            JOIN DM_TINH_TRANG_PHAM_NHANS dttph ON ll.LL_TINH_TRANG_ID = dttph.ID
            JOIN GTH_KY_GIAM_THOI_HANS kgth ON kgth.ID = p_ky_giam_id
            WHERE ll.IS_DELETED = 0
              AND ptha.THA_NGAY_BAT IS NOT NULL
              AND dttph.TTPN_MA IN ('111','112','113','114')
              AND ptha.IS_DELETED = 0
              AND (ptha.THA_NGAY_HET_HAN IS NULL OR ptha.THA_NGAY_HET_HAN >= kgth.KGTH_NGAY_XET_GIAM);

        FETCH v_cursor BULK COLLECT INTO v_pn_ids, v_is_dac_biet;
        CLOSE v_cursor;
        DBMS_OUTPUT.PUT_LINE('Buoc 1 - Danh sach PN: ' || v_pn_ids.COUNT);

        IF v_pn_ids.COUNT = 0 THEN RETURN v_result; END IF;

        FOR i IN 1..v_pn_ids.COUNT LOOP
            v_pn_index_map(v_pn_ids(i)) := i;
        END LOOP;

        DELETE FROM QLPN.PKG_GTH_PN_LIST;
        FORALL i IN 1..v_pn_ids.COUNT
            INSERT INTO QLPN.PKG_GTH_PN_LIST (PN_ID) VALUES (v_pn_ids(i));

        -- BÆ¯á»šC 2: ThÃ´ng tin giáº£m gáº§n nháº¥t
        OPEN v_cursor FOR
            SELECT PHAM_NHAN_ID, cnt, NGAY_XET
            FROM (
                SELECT PHAM_NHAN_ID,
                       COUNT(*) OVER (PARTITION BY PHAM_NHAN_ID) AS cnt,
                       NGAY_XET,
                       ROW_NUMBER() OVER (PARTITION BY PHAM_NHAN_ID ORDER BY NGAY_XET DESC) AS RN
                FROM GIAM_THOI_HANS
                WHERE IS_DELETED = 0
                  AND PHAM_NHAN_ID IN (SELECT PN_ID FROM QLPN.PKG_GTH_PN_LIST)
            )
            WHERE RN = 1;

        FETCH v_cursor BULK COLLECT INTO v_fetch_pn_ids, v_fetch_vals, v_fetch_dates;
        CLOSE v_cursor;

        FOR i IN 1..v_fetch_pn_ids.COUNT LOOP
            IF v_pn_index_map.EXISTS(v_fetch_pn_ids(i)) THEN
                v_so_lan_giam(v_pn_index_map(v_fetch_pn_ids(i))) := v_fetch_vals(i);
                v_ngay_xet_gan(v_pn_index_map(v_fetch_pn_ids(i))) := v_fetch_dates(i);
            END IF;
        END LOOP;
        DBMS_OUTPUT.PUT_LINE('Buoc 2 - Thong tin giam: ' || v_fetch_pn_ids.COUNT);

        -- BÆ¯á»šC 3: Ã?n pháº¡t + ngÃ y báº¯t
        OPEN v_cursor FOR
            SELECT g.PN_ID, CAST(t.THA_NGAY_BAT AS DATE), t.THA_AN_PHAT
            FROM QLPN.PKG_GTH_PN_LIST g
            JOIN PN_THI_HANH_AN t ON g.PN_ID = t.THA_PNLAI_LICH_ID AND NVL(t.IS_DELETED,0) = 0;

        FETCH v_cursor BULK COLLECT INTO v_fetch_pn_ids, v_fetch_dates, v_fetch_text;
        CLOSE v_cursor;

        FOR i IN 1..v_fetch_pn_ids.COUNT LOOP
            IF v_pn_index_map.EXISTS(v_fetch_pn_ids(i)) THEN
                v_ngay_bat(v_pn_index_map(v_fetch_pn_ids(i))) := v_fetch_dates(i);
                v_an_phat_text(v_pn_index_map(v_fetch_pn_ids(i))) := v_fetch_text(i);
            END IF;
        END LOOP;
        DBMS_OUTPUT.PUT_LINE('Buoc 3 - An phat: ' || v_fetch_pn_ids.COUNT);

        -- BÆ¯á»šC 4: Tá»•ng giáº£m tá»« GIAM_THOI_HANS + DM_MA_THOI_GIANS
        OPEN v_cursor FOR
            SELECT g.PN_ID,
                   SUM(NVL(TO_NUMBER(REGEXP_SUBSTR(dmtg.MTG_TITLE,'(\d+) nÄƒm',1,1,NULL,1)),0)) AS nam,
                   SUM(NVL(TO_NUMBER(REGEXP_SUBSTR(dmtg.MTG_TITLE,'(\d+) thÃ¡ng',1,1,NULL,1)),0)) AS thang,
                   SUM(NVL(TO_NUMBER(REGEXP_SUBSTR(dmtg.MTG_TITLE,'(\d+) ngÃ y',1,1,NULL,1)),0)) AS ngay
            FROM QLPN.PKG_GTH_PN_LIST g
            LEFT JOIN GIAM_THOI_HANS t ON g.PN_ID = t.PHAM_NHAN_ID AND t.IS_DELETED = 0
            LEFT JOIN DM_MA_THOI_GIANS dmtg ON dmtg.ID = t.MUC_GIAM_ID AND NVL(dmtg.IS_DELETED,0) = 0
                AND dmtg.MTG_MA NOT IN ('921000','912000','911000','922000')
            GROUP BY g.PN_ID;

        FETCH v_cursor BULK COLLECT INTO v_fetch_pn_ids, v_fetch_vals, v_fetch_vals2, v_fetch_vals3;
        CLOSE v_cursor;

        FOR i IN 1..v_fetch_pn_ids.COUNT LOOP
            IF v_pn_index_map.EXISTS(v_fetch_pn_ids(i)) THEN
                v_tong_giam_nam(v_pn_index_map(v_fetch_pn_ids(i))) := v_fetch_vals(i);
                v_tong_giam_thang(v_pn_index_map(v_fetch_pn_ids(i))) := v_fetch_vals2(i);
                v_tong_giam_ngay(v_pn_index_map(v_fetch_pn_ids(i))) := v_fetch_vals3(i);
            END IF;
        END LOOP;
        DBMS_OUTPUT.PUT_LINE('Buoc 4 - Tong giam: ' || v_fetch_pn_ids.COUNT);

        -- BÆ¯á»šC 5: TDC + Trá»‘n + HoÃ£n - Ä‘Ã£ káº¿t thÃºc
        OPEN v_cursor FOR
            SELECT t.PHAM_NHAN_ID,
                   FLOOR(CAST(t.NGAY_LAI AS DATE) - CAST(t.TU_NGAY AS DATE)) + 1 AS ngay_tdc
            FROM QLPN.PKG_GTH_PN_LIST g
            JOIN TAM_DINH_CHIS t ON g.PN_ID = t.PHAM_NHAN_ID AND NVL(t.IS_DELETED,0) = 0
            WHERE t.TU_NGAY IS NOT NULL AND t.NGAY_LAI IS NOT NULL
            UNION ALL
            SELECT t.PHAM_NHAN_ID,
                   FLOOR(CAST(t.NGAY_BAT_LAI AS DATE) - CAST(t.NGAY_TRON AS DATE)) AS ngay_tron
            FROM QLPN.PKG_GTH_PN_LIST g
            JOIN TRON_TRAIS t ON g.PN_ID = t.PHAM_NHAN_ID AND NVL(t.IS_DELETED,0) = 0
            WHERE t.NGAY_TRON IS NOT NULL AND t.NGAY_BAT_LAI IS NOT NULL
            UNION ALL
            SELECT t.PHAM_NHAN_ID,
                   FLOOR(CAST(t.NGAY_THI_HANH_AN AS DATE) - CAST(t.NGAY_HOAN AS DATE)) + 1 AS ngay_hoan
            FROM QLPN.PKG_GTH_PN_LIST g
            JOIN HOAN_THI_HANH_ANS t ON g.PN_ID = t.PHAM_NHAN_ID AND NVL(t.IS_DELETED,0) = 0
            WHERE t.NGAY_HOAN IS NOT NULL AND t.NGAY_THI_HANH_AN IS NOT NULL;

        FETCH v_cursor BULK COLLECT INTO v_fetch_pn_ids, v_fetch_vals;
        CLOSE v_cursor;

        FOR i IN 1..v_fetch_pn_ids.COUNT LOOP
            IF v_pn_index_map.EXISTS(v_fetch_pn_ids(i)) THEN
                v_da_ch_ngay(v_pn_index_map(v_fetch_pn_ids(i))) :=
                    NVL(v_da_ch_ngay(v_pn_index_map(v_fetch_pn_ids(i))),0) + v_fetch_vals(i);
            END IF;
        END LOOP;
        DBMS_OUTPUT.PUT_LINE('Buoc 5 - Da chap hanh loaded');

        -- BÆ¯á»šC 6: Sá»‘ láº§n giáº£m trong nÄƒm
        OPEN v_cursor FOR
            SELECT g.PN_ID, COUNT(t.ID) AS cnt
            FROM QLPN.PKG_GTH_PN_LIST g
            LEFT JOIN GIAM_THOI_HANS t ON g.PN_ID = t.PHAM_NHAN_ID
                AND EXTRACT(YEAR FROM t.NGAY_XET) = v_nam_xet
                AND NVL(t.IS_DELETED,0) = 0
            GROUP BY g.PN_ID;

        FETCH v_cursor BULK COLLECT INTO v_fetch_pn_ids, v_fetch_vals;
        CLOSE v_cursor;

        FOR i IN 1..v_fetch_pn_ids.COUNT LOOP
            IF v_pn_index_map.EXISTS(v_fetch_pn_ids(i)) THEN
                v_sl_nam_giam(v_pn_index_map(v_fetch_pn_ids(i))) := v_fetch_vals(i);
            END IF;
        END LOOP;
        DBMS_OUTPUT.PUT_LINE('Buoc 6 - SL nam: ' || v_fetch_pn_ids.COUNT);

        DELETE FROM QLPN.PKG_GTH_PN_LIST;
        DBMS_OUTPUT.PUT_LINE('DEBUG: After DELETE GTT');

        -- ================================================================
        -- BÆ¯á»šC 7: TÃ­nh toÃ¡n logic - KHÃ”NG cÃ³ query DB
        -- ================================================================
        FOR i IN 1..v_pn_ids.COUNT LOOP
            DBMS_OUTPUT.PUT_LINE('DEBUG i=' || i || ' PN=' || v_pn_ids(i));

                BEGIN
                -- GÃ¡n máº·c Ä‘á»‹nh
                IF NOT v_so_lan_giam.EXISTS(i) THEN v_so_lan_giam(i) := 0; END IF;
                IF NOT v_sl_nam_giam.EXISTS(i) THEN v_sl_nam_giam(i) := 0; END IF;
                IF NOT v_tong_giam_nam.EXISTS(i) THEN v_tong_giam_nam(i) := 0; END IF;
                IF NOT v_tong_giam_thang.EXISTS(i) THEN v_tong_giam_thang(i) := 0; END IF;
                IF NOT v_tong_giam_ngay.EXISTS(i) THEN v_tong_giam_ngay(i) := 0; END IF;
                IF NOT v_da_ch_nam.EXISTS(i) THEN v_da_ch_nam(i) := 0; END IF;
                IF NOT v_da_ch_thang.EXISTS(i) THEN v_da_ch_thang(i) := 0; END IF;
                IF NOT v_da_ch_ngay.EXISTS(i) THEN v_da_ch_ngay(i) := 0; END IF;

                -- Normalize tá»•ng giáº£m
                v_tong_giam_thang(i) := v_tong_giam_thang(i) + FLOOR(v_tong_giam_ngay(i)/30);
                v_tong_giam_ngay(i) := MOD(v_tong_giam_ngay(i), 30);
                v_tong_giam_nam(i) := v_tong_giam_nam(i) + FLOOR(v_tong_giam_thang(i)/12);
                v_tong_giam_thang(i) := MOD(v_tong_giam_thang(i), 12);

                -- Normalize Ä‘Ã£ cháº¥p hÃ nh
                v_da_ch_thang(i) := v_da_ch_thang(i) + FLOOR(v_da_ch_ngay(i)/30);
                v_da_ch_ngay(i) := MOD(v_da_ch_ngay(i), 30);
                v_da_ch_nam(i) := v_da_ch_nam(i) + FLOOR(v_da_ch_thang(i)/12);
                v_da_ch_thang(i) := MOD(v_da_ch_thang(i), 12);

                -- Ä?Iá»€U KIá»†N 1: Láº§n Ä‘áº§u
                IF v_so_lan_giam(i) = 0 THEN
                    v_dieu_kien_tg := CASE WHEN NVL(v_is_dac_biet(i),0) = 1 THEN C_LAN_DAU_DB ELSE C_LAN_DAU_TT END;
                    v_con_lai_ngay := 0;

                -- Ä?Iá»€U KIá»†N 2: Ä?á»§ 12 thÃ¡ng
                ELSIF v_ngay_xet_gan.EXISTS(i) AND v_ngay_xet_gan(i) IS NOT NULL
                      AND MONTHS_BETWEEN(p_ngay_xet, v_ngay_xet_gan(i)) >= 12 THEN
                    v_dieu_kien_tg := C_DUNG_DOT;
                    v_con_lai_ngay := 0;

                -- Ä?Iá»€U KIá»†N 3: Ä?áº·c biá»‡t
                ELSIF NVL(v_is_dac_biet(i),0) = 1 THEN
                    v_dieu_kien_tg := CASE WHEN v_sl_nam_giam(i) < 2 THEN C_DAY_DOT ELSE C_KHONG_DU END;
                    v_con_lai_ngay := 0;

                -- Ä?Iá»€U KIá»†N 4: TÃ­nh thá»?i gian cÃ²n láº¡i
                ELSE
                    DECLARE
                        v_ap_nam NUMBER := 0; v_ap_thang NUMBER := 0; v_ap_ngay NUMBER := 0;
                    BEGIN
                        IF v_an_phat_text.EXISTS(i) AND v_an_phat_text(i) IS NOT NULL THEN
                            PARSE_AN_PHAT_TO_YMD(v_an_phat_text(i), v_ap_nam, v_ap_thang, v_ap_ngay);
                        END IF;

                        v_con_lai_ngay := TINH_CON_LAI(
                            v_ap_nam, v_ap_thang, v_ap_ngay,
                            v_tong_giam_nam(i), v_tong_giam_thang(i), v_tong_giam_ngay(i),
                            v_da_ch_nam(i), v_da_ch_thang(i), v_da_ch_ngay(i)
                        );

                        IF v_con_lai_ngay > 0 AND v_con_lai_ngay < 365
                           AND v_ngay_xet_gan.EXISTS(i) AND v_ngay_xet_gan(i) IS NOT NULL THEN
                            DECLARE v_ngay_day_dot DATE;
                            BEGIN
                                v_ngay_day_dot := GET_NGAY_DAY_DOT(v_ngay_xet_gan(i));
                                IF v_ngay_day_dot IS NOT NULL AND ABS(p_ngay_xet - v_ngay_day_dot) <= 15 THEN
                                    v_dieu_kien_tg := C_DAY_DOT;
                                ELSE
                                    v_dieu_kien_tg := C_KHONG_DU;
                                END IF;
                            END;
                        ELSE
                            v_dieu_kien_tg := C_KHONG_DU;
                        END IF;
                    END;
                END IF;

                DBMS_OUTPUT.PUT_LINE('DEBUG i=' || i || ' AFTER CONDITIONS');

                -- Xá»­ lÃ½ Ä‘iá»?u kiá»‡n XLCT
                BEGIN
                    v_dieu_kien_xlct := FN_DIEU_KIEN_XLCT(v_pn_ids(i), p_ky_giam_id, NVL(v_is_dac_biet(i),0));
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        v_dieu_kien_xlct := C_KHONG_DU_XLCT;
                        DBMS_OUTPUT.PUT_LINE('XLCT NO_DATA_FOUND: PN=' || v_pn_ids(i));
                    WHEN OTHERS THEN
                        v_dieu_kien_xlct := C_KHONG_DU_XLCT;
                        DBMS_OUTPUT.PUT_LINE('XLCT ERROR PN=' || v_pn_ids(i) || ' ERR=' || SQLERRM);
                END;

                DBMS_OUTPUT.PUT_LINE('DEBUG i=' || i || ' BEFORE RESULT');

                v_count := v_count + 1;
                v_result.EXTEND;
                v_result(v_result.COUNT) := QLPN.TYP_KET_QUA_BATCH(
                    v_pn_ids(i), v_dieu_kien_tg, v_dieu_kien_xlct,
                    CASE WHEN v_dieu_kien_tg <> C_KHONG_DU THEN 1 ELSE 0 END,
                    0, 0
                );
                DBMS_OUTPUT.PUT_LINE('DEBUG i=' || i || ' OK');
            EXCEPTION WHEN OTHERS THEN
                v_count := v_count + 1;
                v_result.EXTEND;
                v_result(v_result.COUNT) := QLPN.TYP_KET_QUA_BATCH(
                    v_pn_ids(i), C_KHONG_DU, C_KHONG_DU_XLCT, 0, 0, 0
                );
                DBMS_OUTPUT.PUT_LINE('LOOP OTHERS at i=' || i || ': ' || SQLERRM);
                DBMS_OUTPUT.PUT_LINE('  Stack: ' || DBMS_UTILITY.FORMAT_ERROR_STACK);
            END;
        END LOOP;

        DBMS_OUTPUT.PUT_LINE('Tong pham nhan: ' || v_count);
        DBMS_OUTPUT.PUT_LINE('Thoi gian: ' || ROUND(EXTRACT(SECOND FROM (SYSTIMESTAMP - v_start)), 4) || ' seconds');
        DBMS_OUTPUT.PUT_LINE('=== V6 PROCESS END ===');

        RETURN v_result;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            BEGIN DELETE FROM QLPN.PKG_GTH_PN_LIST; EXCEPTION WHEN OTHERS THEN NULL; END;
            DBMS_OUTPUT.PUT_LINE('NO_DATA_FOUND in PROCESS_ALL at PN index: ' || v_count);
            DBMS_OUTPUT.PUT_LINE('NO_DATA_FOUND at line: ' || DBMS_UTILITY.FORMAT_ERROR_STACK);
            RETURN v_result;
        WHEN OTHERS THEN
            BEGIN DELETE FROM QLPN.PKG_GTH_PN_LIST; EXCEPTION WHEN OTHERS THEN NULL; END;
            DBMS_OUTPUT.PUT_LINE('Error PROCESS_ALL: ' || SQLERRM);
            RAISE;
    END PROCESS_ALL;

    PROCEDURE TEST_COMPARE(p_ky_giam_id IN NUMBER, p_limit IN NUMBER DEFAULT 10)
    IS
        v_match NUMBER := 0;
        v_mismatch NUMBER := 0;
        v_func_result NVARCHAR2(500);
        v_pkg_result NVARCHAR2(500);
        v_ngay_xet DATE;
        v_dieu_kien_id NUMBER;
        v_pkg_total NUMBER := 0;
        v_results QLPN.TBL_KET_QUA_BATCH;

        TYPE t_map IS TABLE OF QLPN.TYP_KET_QUA_BATCH INDEX BY PLS_INTEGER;
        v_result_map t_map;
    BEGIN
        SELECT dk.ID, CAST(kg.KGTH_NGAY_XET_GIAM AS DATE)
        INTO v_dieu_kien_id, v_ngay_xet
        FROM GTH_DIEU_KIEN_GIAM_THOI_HANS dk
        JOIN GTH_KY_GIAM_THOI_HANS kg ON kg.ID = p_ky_giam_id
        WHERE dk.GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id AND dk.IS_DELETED = 0 AND ROWNUM=1;

        DBMS_OUTPUT.PUT_LINE('===========================================');
        DBMS_OUTPUT.PUT_LINE('SO SANH KET QUA: V3 vs V6');
        DBMS_OUTPUT.PUT_LINE('===========================================');
        DBMS_OUTPUT.PUT_LINE('Ky giam ID: ' || p_ky_giam_id);
        DBMS_OUTPUT.PUT_LINE('Ngay xet: ' || TO_CHAR(v_ngay_xet,'DD/MM/YYYY'));
        DBMS_OUTPUT.PUT_LINE('-------------------------------------------');

        v_pkg_total := DBMS_UTILITY.GET_TIME;
        v_results := PROCESS_ALL(p_ky_giam_id, v_ngay_xet);
        v_pkg_total := (DBMS_UTILITY.GET_TIME - v_pkg_total) / 100;

        FOR i IN 1..v_results.COUNT LOOP
            v_result_map(v_results(i).PHAM_NHAN_ID) := v_results(i);
        END LOOP;

        DBMS_OUTPUT.PUT_LINE('Process ALL thoi gian: ' || ROUND(v_pkg_total, 2) || ' seconds');
        DBMS_OUTPUT.PUT_LINE('So ket qua: ' || v_results.COUNT);
        DBMS_OUTPUT.PUT_LINE('-------------------------------------------');

        FOR rec IN (
            SELECT ll.ID AS PN_ID,
                   FN_DIEU_KIEN_THOI_GIAN(ll.ID, v_ngay_xet, FN_IS_TRUONG_HOP_DAC_BIET(ll.ID, p_ky_giam_id)) AS V3_RESULT
            FROM PN_LAI_LICHS ll
            JOIN PN_THI_HANH_AN ptha ON ll.ID = ptha.THA_PNLAI_LICH_ID
            JOIN DM_TINH_TRANG_PHAM_NHANS dttph ON ll.LL_TINH_TRANG_ID = dttph.ID
            JOIN GTH_KY_GIAM_THOI_HANS kgth ON kgth.ID = p_ky_giam_id
            WHERE ll.IS_DELETED = 0
              AND ptha.THA_NGAY_BAT IS NOT NULL
              AND dttph.TTPN_MA IN ('111','112','113','114')
              AND ptha.IS_DELETED = 0
              AND (ptha.THA_NGAY_HET_HAN IS NULL OR ptha.THA_NGAY_HET_HAN >= kgth.KGTH_NGAY_XET_GIAM)
              AND ROWNUM <= p_limit
        ) LOOP
            v_func_result := rec.V3_RESULT;
            v_pkg_result := v_result_map(rec.PN_ID).DIEU_KIEN_TG;

            IF v_func_result = v_pkg_result THEN
                v_match := v_match + 1;
                DBMS_OUTPUT.PUT_LINE('MATCH: PN=' || rec.PN_ID || ' | ' || v_func_result);
            ELSE
                v_mismatch := v_mismatch + 1;
                DBMS_OUTPUT.PUT_LINE('MISMATCH: PN=' || rec.PN_ID);
                DBMS_OUTPUT.PUT_LINE('  V3: ' || v_func_result);
                DBMS_OUTPUT.PUT_LINE('  V6: ' || NVL(v_pkg_result, 'NULL'));
            END IF;
        END LOOP;

        DBMS_OUTPUT.PUT_LINE('-------------------------------------------');
        DBMS_OUTPUT.PUT_LINE('Tong: ' || (v_match + v_mismatch) || ' | Match: ' || v_match || ' | Mismatch: ' || v_mismatch);
        IF v_match + v_mismatch > 0 THEN
            DBMS_OUTPUT.PUT_LINE('Ty le match: ' || ROUND(v_match*100/(v_match+v_mismatch), 2) || '%');
        END IF;
        DBMS_OUTPUT.PUT_LINE('===========================================');
    END TEST_COMPARE;

END PKG_GTH_BATCH_V6;






/
--------------------------------------------------------
--  DDL for Package Body PKG_GTH_CHUNG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "QLPN"."PKG_GTH_CHUNG" 
AS
    C_LAN_DAU_TT CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - Xét l?n ??u - Thông th??ng');
    C_LAN_DAU_DB CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - Xét l?n ??u - ??c bi?t');
    C_DUNG_DOT    CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - ?ã gi?m án - ?úng ??t');
    C_DAY_DOT     CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - ?ã gi?m án - ???c ??y ??t');
    C_KHONG_DU    CONSTANT NVARCHAR2(100) := TO_NCHAR('Không ?? ?K v? th?i gian');

    FUNCTION PARSE_AN_PHAT_TO_YMD(p_an_phat IN NVARCHAR2) RETURN YMD_OBJ
    IS
        v_nam NUMBER := 0;
        v_thang NUMBER := 0;
        v_ngay NUMBER := 0;
        v_text NVARCHAR2(500);
    BEGIN
        IF p_an_phat IS NULL THEN RETURN YMD_OBJ(0,0,0); END IF;
        v_text := TRIM(p_an_phat);

        IF LOWER(v_text) LIKE '%chung th%n%gi%m%30%' THEN RETURN YMD_OBJ(30,0,0); END IF;
        IF LOWER(v_text) LIKE '%chung th%n%gi%m%20%' THEN RETURN YMD_OBJ(20,0,0); END IF;
        IF LOWER(v_text) LIKE '%chung th%n%' OR LOWER(v_text) LIKE '%t%h%nh%' THEN RETURN YMD_OBJ(0,0,0); END IF;

        DECLARE v_pos NUMBER; v_num VARCHAR2(20);
        BEGIN
            v_pos := INSTR(v_text, 'n?m');
            IF v_pos > 0 THEN
                v_num := TRIM(REGEXP_SUBSTR(SUBSTR(v_text,1,v_pos-1), '\d+', 1, 1, 'i', 0));
                v_nam := NVL(TO_NUMBER(v_num),0);
            END IF;
        EXCEPTION WHEN OTHERS THEN NULL; END;

        DECLARE v_pos2 NUMBER; v_num2 VARCHAR2(20);
        BEGIN
            v_pos2 := INSTR(v_text, 'tháng');
            IF v_pos2 > 0 THEN
                v_num2 := TRIM(REGEXP_SUBSTR(SUBSTR(v_text,1,v_pos2-1), '\d+', 1, 1, 'i', 0));
                v_thang := NVL(TO_NUMBER(v_num2),0);
            END IF;
        EXCEPTION WHEN OTHERS THEN NULL; END;

        RETURN YMD_OBJ(v_nam, v_thang, v_ngay);
    EXCEPTION WHEN OTHERS THEN RETURN YMD_OBJ(0,0,0); END PARSE_AN_PHAT_TO_YMD;

    FUNCTION TINH_CON_LAI_BATCH(p_an_phat IN NVARCHAR2, p_da_giam_ymd IN YMD_OBJ, p_da_ch_ymd IN YMD_OBJ) RETURN YMD_OBJ
    IS
        v_ap YMD_OBJ;
        v_tong_ap NUMBER;
        v_tong_dg NUMBER;
        v_tong_dch NUMBER;
        v_cl NUMBER;
        v_n NUMBER; v_t NUMBER; v_ng NUMBER;
    BEGIN
        v_ap := PARSE_AN_PHAT_TO_YMD(p_an_phat);
        v_tong_ap := NVL(v_ap.nam,0)*365 + NVL(v_ap.thang,0)*30 + NVL(v_ap.ngay,0);
        v_tong_dg := NVL(p_da_giam_ymd.nam,0)*365 + NVL(p_da_giam_ymd.thang,0)*30 + NVL(p_da_giam_ymd.ngay,0);
        v_tong_dch := NVL(p_da_ch_ymd.nam,0)*365 + NVL(p_da_ch_ymd.thang,0)*30 + NVL(p_da_ch_ymd.ngay,0);
        v_cl := v_tong_ap - v_tong_dg - v_tong_dch;
        IF v_cl <= 0 THEN RETURN YMD_OBJ(0,0,0); END IF;
        v_n := FLOOR(v_cl/365);
        v_t := FLOOR(MOD(v_cl,365)/30);
        v_ng := MOD(MOD(v_cl,365),30);
        RETURN YMD_OBJ(v_n, v_t, v_ng);
    EXCEPTION WHEN OTHERS THEN RETURN YMD_OBJ(0,0,0); END TINH_CON_LAI_BATCH;

    FUNCTION PROCESS_ONE_PN(p_pn_id IN NUMBER, p_ngay_xet IN DATE, p_is_dac_biet IN NUMBER DEFAULT 0) RETURN QLPN.TYP_GTH_KET_QUA_XL
    IS
        v_an_phat NVARCHAR2(500);
        v_ngay_bat DATE;
        v_tg_tam_giam NVARCHAR2(500);
        v_tg_tam_giu NVARCHAR2(500);
        v_tg_o_truoc NVARCHAR2(500);
        v_so_lan_giam NUMBER := 0;
        v_ngay_xet_gan_nhat DATE;
        v_tong_giam_ymd YMD_OBJ := YMD_OBJ(0,0,0);
        v_ngay_gioi_han DATE := NULL;
        v_tong_ngay_tdc NUMBER := 0;
        v_tong_ngay_tron NUMBER := 0;
        v_tong_ngay_hoan NUMBER := 0;
        v_da_chap_hanh_ymd YMD_OBJ := YMD_OBJ(0,0,0);
        v_con_lai_ymd YMD_OBJ := YMD_OBJ(0,0,0);
        v_is_du_tgch NUMBER := 0;
        v_trang_thai_tg NVARCHAR2(500);
        v_nam_xet NUMBER;
        v_khoang_cach_thang NUMBER;
        v_so_lan_giam_trong_nam NUMBER;
        v_con_lai_ngay NUMBER;
        v_ngay_day_dot DATE;
        v_temp_date DATE;
    BEGIN
        v_nam_xet := EXTRACT(YEAR FROM p_ngay_xet);

        BEGIN
            SELECT THA_AN_PHAT, CAST(THA_NGAY_BAT AS DATE), THA_THOI_GIAN_TAM_GIAM, THA_THOI_GIAN_TAM_GIU, THA_THOI_GIAN_O_TRUOC
              INTO v_an_phat, v_ngay_bat, v_tg_tam_giam, v_tg_tam_giu, v_tg_o_truoc
              FROM PN_THI_HANH_AN
             WHERE THA_PNLAI_LICH_ID = p_pn_id
               AND NVL(IS_DELETED,0)=0
               AND ROWNUM=1;
        EXCEPTION WHEN NO_DATA_FOUND THEN
            RETURN QLPN.TYP_GTH_KET_QUA_XL(NULL,0,C_KHONG_DU,YMD_OBJ(0,0,0),YMD_OBJ(0,0,0),YMD_OBJ(0,0,0),YMD_OBJ(0,0,0),NULL,NULL,0,NULL,NULL);
        END;

        BEGIN
            SELECT COUNT(*), MAX(CASE WHEN RN=1 THEN NGAY_XET END)
              INTO v_so_lan_giam, v_ngay_xet_gan_nhat
              FROM (SELECT NGAY_XET, ROW_NUMBER() OVER (ORDER BY NGAY_XET DESC) AS RN
                      FROM GIAM_THOI_HANS
                     WHERE PHAM_NHAN_ID = p_pn_id AND IS_DELETED=0);
        EXCEPTION WHEN OTHERS THEN NULL; END;

        BEGIN
            SELECT YMD_OBJ(
                       COALESCE(SUM(TO_NUMBER(REGEXP_SUBSTR(dmtg.MTG_TITLE,'(\d+) n?m',1,1,NULL,1))),0),
                       COALESCE(SUM(TO_NUMBER(REGEXP_SUBSTR(dmtg.MTG_TITLE,'(\d+) tháng',1,1,NULL,1))),0),
                       COALESCE(SUM(TO_NUMBER(REGEXP_SUBSTR(dmtg.MTG_TITLE,'(\d+) ngày',1,1,NULL,1))),0)
                   )
              INTO v_tong_giam_ymd
              FROM GIAM_THOI_HANS gth
              JOIN DM_MA_THOI_GIANS dmtg ON dmtg.ID=gth.MUC_GIAM_ID
             WHERE gth.PHAM_NHAN_ID = p_pn_id
               AND gth.IS_DELETED=0
               AND NVL(dmtg.IS_DELETED,0)=0
               AND dmtg.MTG_MA NOT IN ('921000','912000','911000','922000');
            v_tong_giam_ymd.thang := v_tong_giam_ymd.thang + FLOOR(NVL(v_tong_giam_ymd.ngay,0)/30);
            v_tong_giam_ymd.ngay := MOD(NVL(v_tong_giam_ymd.ngay,0),30);
            v_tong_giam_ymd.nam := v_tong_giam_ymd.nam + FLOOR(v_tong_giam_ymd.thang/12);
            v_tong_giam_ymd.thang := MOD(v_tong_giam_ymd.thang,12);
        EXCEPTION WHEN OTHERS THEN v_tong_giam_ymd := YMD_OBJ(0,0,0); END;

        BEGIN
            SELECT MIN(tdc.TU_NGAY) INTO v_ngay_gioi_han
              FROM TAM_DINH_CHIS tdc
             WHERE tdc.PHAM_NHAN_ID=p_pn_id
               AND NVL(tdc.IS_DELETED,0)=0
               AND tdc.TU_NGAY IS NOT NULL
               AND tdc.NGAY_LAI IS NULL;
        EXCEPTION WHEN NO_DATA_FOUND THEN NULL; END;

        IF v_ngay_gioi_han IS NULL THEN
            BEGIN
                SELECT MIN(tt.NGAY_TRON) INTO v_ngay_gioi_han
                  FROM TRON_TRAIS tt
                 WHERE tt.PHAM_NHAN_ID=p_pn_id
                   AND NVL(tt.IS_DELETED,0)=0
                   AND tt.NGAY_TRON IS NOT NULL
                   AND tt.NGAY_BAT_LAI IS NULL;
            EXCEPTION WHEN NO_DATA_FOUND THEN NULL; END;
        END IF;

        IF v_ngay_gioi_han IS NULL THEN
            BEGIN
                SELECT MIN(htha.NGAY_HOAN) INTO v_ngay_gioi_han
                  FROM HOAN_THI_HANH_ANS htha
                 WHERE htha.PHAM_NHAN_ID=p_pn_id
                   AND NVL(htha.IS_DELETED,0)=0
                   AND htha.NGAY_HOAN IS NOT NULL
                   AND htha.NGAY_THI_HANH_AN IS NULL;
            EXCEPTION WHEN NO_DATA_FOUND THEN NULL; END;
        END IF;

        IF v_ngay_bat IS NULL OR p_ngay_xet <= v_ngay_bat THEN
            v_da_chap_hanh_ymd := YMD_OBJ(0,0,0);
        ELSE
            DECLARE v_ngay_tinh DATE;
            BEGIN
                IF v_ngay_gioi_han IS NOT NULL AND p_ngay_xet > v_ngay_gioi_han THEN
                    v_ngay_tinh := v_ngay_gioi_han;
                ELSE
                    v_ngay_tinh := p_ngay_xet;
                END IF;

                v_da_chap_hanh_ymd.nam := FLOOR(MONTHS_BETWEEN(v_ngay_tinh, v_ngay_bat)/12);
                v_temp_date := ADD_MONTHS(v_ngay_bat, v_da_chap_hanh_ymd.nam*12);
                v_da_chap_hanh_ymd.thang := FLOOR(MONTHS_BETWEEN(v_ngay_tinh, v_temp_date));
                v_temp_date := ADD_MONTHS(v_temp_date, v_da_chap_hanh_ymd.thang);
                v_da_chap_hanh_ymd.ngay := FLOOR(v_ngay_tinh - v_temp_date);
            END;

            DECLARE v_ymd_tg YMD_OBJ;
            BEGIN
                v_ymd_tg := PARSE_AN_PHAT_TO_YMD(v_tg_tam_giam);
                v_da_chap_hanh_ymd.nam := v_da_chap_hanh_ymd.nam + NVL(v_ymd_tg.nam,0);
                v_da_chap_hanh_ymd.thang := v_da_chap_hanh_ymd.thang + NVL(v_ymd_tg.thang,0);
                v_da_chap_hanh_ymd.ngay := v_da_chap_hanh_ymd.ngay + NVL(v_ymd_tg.ngay,0);
                v_da_chap_hanh_ymd.thang := v_da_chap_hanh_ymd.thang + FLOOR(v_da_chap_hanh_ymd.ngay/30);
                v_da_chap_hanh_ymd.ngay := MOD(v_da_chap_hanh_ymd.ngay,30);
                v_da_chap_hanh_ymd.nam := v_da_chap_hanh_ymd.nam + FLOOR(v_da_chap_hanh_ymd.thang/12);
                v_da_chap_hanh_ymd.thang := MOD(v_da_chap_hanh_ymd.thang,12);
            EXCEPTION WHEN OTHERS THEN NULL; END;

            DECLARE v_ymd_tg2 YMD_OBJ;
            BEGIN
                v_ymd_tg2 := PARSE_AN_PHAT_TO_YMD(v_tg_tam_giu);
                v_da_chap_hanh_ymd.nam := v_da_chap_hanh_ymd.nam + NVL(v_ymd_tg2.nam,0);
                v_da_chap_hanh_ymd.thang := v_da_chap_hanh_ymd.thang + NVL(v_ymd_tg2.thang,0);
                v_da_chap_hanh_ymd.ngay := v_da_chap_hanh_ymd.ngay + NVL(v_ymd_tg2.ngay,0);
                v_da_chap_hanh_ymd.thang := v_da_chap_hanh_ymd.thang + FLOOR(v_da_chap_hanh_ymd.ngay/30);
                v_da_chap_hanh_ymd.ngay := MOD(v_da_chap_hanh_ymd.ngay,30);
                v_da_chap_hanh_ymd.nam := v_da_chap_hanh_ymd.nam + FLOOR(v_da_chap_hanh_ymd.thang/12);
                v_da_chap_hanh_ymd.thang := MOD(v_da_chap_hanh_ymd.thang,12);
            EXCEPTION WHEN OTHERS THEN NULL; END;

            DECLARE v_ymd_tg3 YMD_OBJ;
            BEGIN
                v_ymd_tg3 := PARSE_AN_PHAT_TO_YMD(v_tg_o_truoc);
                v_da_chap_hanh_ymd.nam := v_da_chap_hanh_ymd.nam + NVL(v_ymd_tg3.nam,0);
                v_da_chap_hanh_ymd.thang := v_da_chap_hanh_ymd.thang + NVL(v_ymd_tg3.thang,0);
                v_da_chap_hanh_ymd.ngay := v_da_chap_hanh_ymd.ngay + NVL(v_ymd_tg3.ngay,0);
                v_da_chap_hanh_ymd.thang := v_da_chap_hanh_ymd.thang + FLOOR(v_da_chap_hanh_ymd.ngay/30);
                v_da_chap_hanh_ymd.ngay := MOD(v_da_chap_hanh_ymd.ngay,30);
                v_da_chap_hanh_ymd.nam := v_da_chap_hanh_ymd.nam + FLOOR(v_da_chap_hanh_ymd.thang/12);
                v_da_chap_hanh_ymd.thang := MOD(v_da_chap_hanh_ymd.thang,12);
            EXCEPTION WHEN OTHERS THEN NULL; END;

            FOR rec IN (
                SELECT FLOOR(CAST(NGAY_LAI AS DATE)-CAST(TU_NGAY AS DATE))+1 AS so_ngay
                  FROM TAM_DINH_CHIS
                 WHERE PHAM_NHAN_ID=p_pn_id
                   AND NVL(IS_DELETED,0)=0
                   AND TU_NGAY IS NOT NULL
                   AND NGAY_LAI IS NOT NULL
            ) LOOP
                IF rec.so_ngay > 0 THEN v_tong_ngay_tdc := v_tong_ngay_tdc + rec.so_ngay; END IF;
            END LOOP;

            FOR rec IN (
                SELECT FLOOR(CAST(NGAY_THI_HANH_AN AS DATE)-CAST(NGAY_HOAN AS DATE))+1 AS so_ngay
                  FROM HOAN_THI_HANH_ANS
                 WHERE PHAM_NHAN_ID=p_pn_id
                   AND NVL(IS_DELETED,0)=0
                   AND NGAY_THI_HANH_AN IS NOT NULL
                   AND NGAY_HOAN IS NOT NULL
            ) LOOP
                IF rec.so_ngay > 0 THEN v_tong_ngay_hoan := v_tong_ngay_hoan + rec.so_ngay; END IF;
            END LOOP;

            FOR rec IN (
                SELECT FLOOR(CAST(NGAY_BAT_LAI AS DATE)-CAST(NGAY_TRON AS DATE)) AS so_ngay
                  FROM TRON_TRAIS
                 WHERE PHAM_NHAN_ID=p_pn_id
                   AND NVL(IS_DELETED,0)=0
                   AND NGAY_TRON IS NOT NULL
                   AND NGAY_BAT_LAI IS NOT NULL
            ) LOOP
                IF rec.so_ngay > 0 THEN v_tong_ngay_tron := v_tong_ngay_tron + rec.so_ngay; END IF;
            END LOOP;

            DECLARE
                v_tong_kh NUMBER := v_tong_ngay_tdc + v_tong_ngay_tron + v_tong_ngay_hoan;
            BEGIN
                IF v_tong_kh > 0 THEN
                    DECLARE
                        v_tong_hientai NUMBER := v_da_chap_hanh_ymd.nam*365 + v_da_chap_hanh_ymd.thang*30 + v_da_chap_hanh_ymd.ngay - v_tong_kh;
                    BEGIN
                        IF v_tong_hientai < 0 THEN v_tong_hientai := 0; END IF;
                        v_da_chap_hanh_ymd.nam := FLOOR(v_tong_hientai/365);
                        v_da_chap_hanh_ymd.thang := FLOOR(MOD(v_tong_hientai,365)/30);
                        v_da_chap_hanh_ymd.ngay := MOD(MOD(v_tong_hientai,365),30);
                    END;
                END IF;
            END;
        END IF;

        IF v_so_lan_giam = 0 THEN
            v_trang_thai_tg := CASE WHEN p_is_dac_biet=1 THEN C_LAN_DAU_DB ELSE C_LAN_DAU_TT END;
            v_is_du_tgch := 1;
        ELSIF MONTHS_BETWEEN(p_ngay_xet, v_ngay_xet_gan_nhat) >= 12 THEN
            v_trang_thai_tg := C_DUNG_DOT;
            v_is_du_tgch := 1;
        ELSIF p_is_dac_biet = 1 THEN
            SELECT COUNT(*) INTO v_so_lan_giam_trong_nam
              FROM GIAM_THOI_HANS
             WHERE PHAM_NHAN_ID = p_pn_id
               AND EXTRACT(YEAR FROM NGAY_XET) = v_nam_xet
               AND IS_DELETED = 0;
            IF v_so_lan_giam_trong_nam < 2 THEN
                v_trang_thai_tg := C_DAY_DOT;
                v_is_du_tgch := 1;
            ELSE
                v_trang_thai_tg := C_KHONG_DU;
                v_is_du_tgch := 0;
            END IF;
        ELSE
            v_con_lai_ymd := TINH_CON_LAI_BATCH(v_an_phat, v_tong_giam_ymd, v_da_chap_hanh_ymd);
            v_con_lai_ngay := v_con_lai_ymd.nam*365 + v_con_lai_ymd.thang*30 + v_con_lai_ymd.ngay;
            IF v_con_lai_ngay > 0 AND v_con_lai_ngay < 365 THEN
                DECLARE
                    v_dot NUMBER;
                    v_nam_g NUMBER;
                BEGIN
                    v_dot := CASE
                        WHEN EXTRACT(MONTH FROM v_ngay_xet_gan_nhat) < 4
                             OR (EXTRACT(MONTH FROM v_ngay_xet_gan_nhat)=4 AND EXTRACT(DAY FROM v_ngay_xet_gan_nhat)<30) THEN 1
                        WHEN EXTRACT(MONTH FROM v_ngay_xet_gan_nhat) < 9
                             OR (EXTRACT(MONTH FROM v_ngay_xet_gan_nhat)=9 AND EXTRACT(DAY FROM v_ngay_xet_gan_nhat)<2) THEN 2
                        ELSE 3
                    END;
                    v_nam_g := EXTRACT(YEAR FROM v_ngay_xet_gan_nhat);
                    -- Logic dung: ??t 1->??t 3 cùng n?m, ??t 2->??t 1 n?m sau, ??t 3->??t 2 n?m sau
                    v_ngay_day_dot := CASE v_dot
                        WHEN 1 THEN TO_DATE('02/09/'||v_nam_g,'DD/MM/YYYY')
                        WHEN 2 THEN TO_DATE('01/01/'||(v_nam_g+1),'DD/MM/YYYY')
                        WHEN 3 THEN TO_DATE('30/04/'||(v_nam_g+1),'DD/MM/YYYY')
                    END;
                    IF v_ngay_day_dot IS NOT NULL AND ABS(p_ngay_xet - v_ngay_day_dot) <= 15 THEN
                        v_trang_thai_tg := C_DAY_DOT;
                        v_is_du_tgch := 1;
                    ELSE
                        v_trang_thai_tg := C_KHONG_DU;
                        v_is_du_tgch := 0;
                    END IF;
                END;
            ELSE
                v_trang_thai_tg := C_KHONG_DU;
                v_is_du_tgch := 0;
            END IF;
        END IF;

        RETURN QLPN.TYP_GTH_KET_QUA_XL(
            p_pn_id, v_is_du_tgch, v_trang_thai_tg,
            v_da_chap_hanh_ymd, v_tong_giam_ymd, v_con_lai_ymd,
            YMD_OBJ(0,0,0), v_an_phat, v_ngay_bat, v_so_lan_giam,
            v_ngay_xet_gan_nhat, v_ngay_gioi_han
        );
    EXCEPTION WHEN OTHERS THEN
        RETURN QLPN.TYP_GTH_KET_QUA_XL(p_pn_id,0,C_KHONG_DU,YMD_OBJ(0,0,0),YMD_OBJ(0,0,0),YMD_OBJ(0,0,0),YMD_OBJ(0,0,0),NULL,NULL,0,NULL,NULL);
    END PROCESS_ONE_PN;

    FUNCTION PROCESS_BATCH(p_list_pn IN QLPN.TBL_PN_INPUT) RETURN QLPN.TBL_GTH_KET_QUA_XL PIPELINED
    IS
    BEGIN
        FOR i IN 1..p_list_pn.COUNT LOOP
            PIPE ROW (PROCESS_ONE_PN(p_list_pn(i).PHAM_NHAN_ID, p_list_pn(i).NGAY_XET, p_list_pn(i).IS_DAC_BIET));
        END LOOP;
        RETURN;
    END PROCESS_BATCH;

    PROCEDURE TEST_COMPARE(p_limit IN NUMBER DEFAULT 10)
    IS
        v_cnt NUMBER := 0;
        v_match NUMBER := 0;
        v_mismatch NUMBER := 0;
        v_func NVARCHAR2(500);
        v_pkg NVARCHAR2(500);
        v_pn_id NUMBER;
        v_ngay_xet DATE;
    BEGIN
        SELECT MAX(CREATION_TIME) INTO v_ngay_xet FROM GTH_KY_GIAM_THOI_HANS WHERE IS_DELETED=0;
        DBMS_OUTPUT.PUT_LINE('===========================================');
        DBMS_OUTPUT.PUT_LINE('SO SANH KET QUA');
        DBMS_OUTPUT.PUT_LINE('===========================================');
        DBMS_OUTPUT.PUT_LINE('So ban ghi test: ' || p_limit);
        DBMS_OUTPUT.PUT_LINE('Ngay xet: ' || TO_CHAR(v_ngay_xet,'DD/MM/YYYY'));
        DBMS_OUTPUT.PUT_LINE('-------------------------------------------');

        FOR rec IN (
            SELECT ll.ID
              FROM PN_LAI_LICHS ll
              JOIN PN_THI_HANH_AN ptha ON ptha.THA_PNLAI_LICH_ID = ll.ID
              JOIN DM_TINH_TRANG_PHAM_NHANS dttph ON ll.LL_TINH_TRANG_ID = dttph.ID
             WHERE ll.IS_DELETED = 0
               AND ptha.THA_NGAY_BAT IS NOT NULL
               AND dttph.TTPN_MA IN ('111','112','113','114')
               AND ptha.IS_DELETED = 0
               AND ROWNUM <= p_limit
        ) LOOP
            v_pn_id := rec.ID;
            v_cnt := v_cnt + 1;
            BEGIN
                v_func := FN_DIEU_KIEN_THOI_GIAN(v_pn_id, v_ngay_xet, 0);
                FOR r IN (
                    SELECT TRANG_THAI_TG
                      FROM TABLE(QLPN.PKG_GTH_CHUNG.PROCESS_BATCH(
                          QLPN.TBL_PN_INPUT(QLPN.TYP_PN_INPUT(v_pn_id, 1, 0, v_ngay_xet))
                      ))
                ) LOOP
                    v_pkg := r.TRANG_THAI_TG;
                END LOOP;

                IF v_pkg = v_func THEN
                    v_match := v_match + 1;
                    DBMS_OUTPUT.PUT_LINE('MATCH: PN=' || v_pn_id || ' | ' || v_func);
                ELSE
                    v_mismatch := v_mismatch + 1;
                    DBMS_OUTPUT.PUT_LINE('MISMATCH: PN=' || v_pn_id);
                    DBMS_OUTPUT.PUT_LINE('    FUNC: ' || v_func);
                    DBMS_OUTPUT.PUT_LINE('    PKG:   ' || v_pkg);
                END IF;
            EXCEPTION WHEN OTHERS THEN
                v_mismatch := v_mismatch + 1;
                DBMS_OUTPUT.PUT_LINE('ERROR PN=' || v_pn_id || ': ' || SQLERRM);
            END;
        END LOOP;

        DBMS_OUTPUT.PUT_LINE('-------------------------------------------');
        DBMS_OUTPUT.PUT_LINE('Tong: ' || v_cnt || ' | Match: ' || v_match || ' | Mismatch: ' || v_mismatch);
        IF v_cnt > 0 THEN
            DBMS_OUTPUT.PUT_LINE('Ty le match: ' || ROUND(v_match*100/v_cnt, 2) || '%');
        END IF;
        DBMS_OUTPUT.PUT_LINE('===========================================');
    END TEST_COMPARE;

END PKG_GTH_CHUNG;






