        tha.THA_DOI_TUONG,
        tha.THA_CAP_TOA_ID,
        tha.THA_DIA_PHUONG_DON_VI_DE_NGHI_ID,
        tha.THA_DIA_PHUONG_TOA_QD_THA_ID,
        tha.THA_DIA_PHUONG_DON_CO_QUAN_LAP_ID,
        tha.THA_DIA_PHUONG_CAP_TOA_ID,
        tha.THA_PNLAI_LICH_ID,
        tha.THA_DIA_PHUONG_CO_QUAN_BAT_ID,
        tha.CREATION_TIME AS THA_CREATION_TIME,
        tha.CREATOR_USER_ID AS THA_CREATOR_USER_ID,
        tha.DELETER_USER_ID AS THA_DELETER_USER_ID,
        tha.DELETION_TIME AS THA_DELETION_TIME,
        tha.IS_DELETED AS THA_IS_DELETED,
        tha.LAST_MODIFICATION_TIME AS THA_LAST_MODIFICATION_TIME,
        tha.LAST_MODIFIER_USER_ID AS THA_LAST_MODIFIER_USER_ID,
        tha.THA_TONG_AN_GIAM,
        tha.THA_NGAY_BAT_DAU_O_TU,
        tha.THA_MUC_AN_ID,
        tha.THA_THOI_GIAN_CON_LAI,
        tha.THA_THOI_GIAN_DA_CHAP_HANH,
        tha.THA_MA_AN_PHAT,
        tha.THA_BUONG_GIAM,
        tha.THA_AN_PHAT_GOC,
        tha.THA_MUC_DO_NGHIEM_TRONG_ID,
        tha.THA_TOI_DANH_NAMES,
        TO_NUMBER(
            TRIM(REGEXP_SUBSTR(
                REPLACE(REPLACE(tha.THA_TOI_DANH, '[', ''), ']', ''),
                '[^,]+', 1, 1))
            DEFAULT NULL ON CONVERSION ERROR) AS TOI_DANH_DAU_TIEN,
        CASE
          WHEN ll.LL_NGAY_SINH IS NOT NULL THEN
            CASE
              WHEN REGEXP_LIKE(TO_CHAR(ll.LL_NGAY_SINH), '^\d{4}$') THEN TO_NUMBER(TO_CHAR(ll.LL_NGAY_SINH))
              WHEN LENGTH(TO_CHAR(ll.LL_NGAY_SINH)) >= 4
                AND REGEXP_LIKE(SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), -4), '^\d{4}$')
              THEN TO_NUMBER(SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), -4))
              WHEN REGEXP_LIKE(TO_CHAR(ll.LL_NGAY_SINH), '\d{4}')
              THEN TO_NUMBER(REGEXP_SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), '\d{4}', 1, 1))
              ELSE NULL
            END
          ELSE NULL
        END AS NAM_SINH,
        CASE
          WHEN ll.LL_GHI_CHU_RIENG IS NOT NULL OR ll.LL_GHI_CHU_CHI_TIET IS NOT NULL
          THEN COALESCE(ll.LL_GHI_CHU_RIENG, u'')
             || CASE
                  WHEN ll.LL_GHI_CHU_RIENG IS NOT NULL AND ll.LL_GHI_CHU_CHI_TIET IS NOT NULL
                  THEN u' | '
                  ELSE u''
                END
             || COALESCE(ll.LL_GHI_CHU_CHI_TIET, u'')
          ELSE NULL
        END AS GHI_CHU,
        CASE
          WHEN ll.ID IS NOT NULL
          THEN PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(ll.ID)
          ELSE NULL
        END AS THOI_GIAN_DA_GIAM,
        NVL(PKG_TINH_AN.FN_TINH_SO_LAN_GIAM_AN(ll.ID), 0) AS SO_LAN_GIAM
      FROM "QLPN"."PN_LAI_LICHS" ll
      LEFT JOIN (
        SELECT y.*
        FROM (
          SELECT
            t.*,
            ROW_NUMBER() OVER (
              PARTITION BY t.THA_PNLAI_LICH_ID
