  PROCEDURE SAFE_REFRESH_ONE(
    p_pham_nhan_id IN NUMBER,
    p_source_table IN VARCHAR2 DEFAULT NULL,
    p_source_row_id IN NUMBER DEFAULT NULL,
    p_action_name IN VARCHAR2 DEFAULT NULL
  ) IS
  BEGIN
    REFRESH_ONE(p_pham_nhan_id, p_source_table, p_source_row_id, p_action_name);
  EXCEPTION
    WHEN OTHERS THEN
      LOG_ERROR(p_pham_nhan_id, p_source_table, p_source_row_id, p_action_name, SQLERRM);
  END SAFE_REFRESH_ONE;

  PROCEDURE REFRESH_REDUCTION_METRICS_ONE(
    p_pham_nhan_id IN NUMBER,
    p_source_table IN VARCHAR2 DEFAULT NULL,
    p_source_row_id IN NUMBER DEFAULT NULL,
    p_action_name IN VARCHAR2 DEFAULT NULL
  ) IS
  BEGIN
    UPDATE "QLPN"."PN_LAI_LICH_CHI_TIET_RT" d
    SET d.THOI_GIAN_DA_GIAM = PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(p_pham_nhan_id),
        d.SO_LAN_GIAM = NVL(PKG_TINH_AN.FN_TINH_SO_LAN_GIAM_AN(p_pham_nhan_id), 0),
        d.LAST_REFRESH_TIME = SYSTIMESTAMP
    WHERE d.PHAM_NHAN_ID = p_pham_nhan_id;
  END REFRESH_REDUCTION_METRICS_ONE;

  PROCEDURE SAFE_REFRESH_REDUCTION_METRICS_ONE(
    p_pham_nhan_id IN NUMBER,
    p_source_table IN VARCHAR2 DEFAULT NULL,
    p_source_row_id IN NUMBER DEFAULT NULL,
    p_action_name IN VARCHAR2 DEFAULT NULL
  ) IS
  BEGIN
    REFRESH_REDUCTION_METRICS_ONE(
      p_pham_nhan_id => p_pham_nhan_id,
      p_source_table => p_source_table,
      p_source_row_id => p_source_row_id,
      p_action_name => p_action_name
    );
  EXCEPTION
    WHEN OTHERS THEN
      LOG_ERROR(p_pham_nhan_id, p_source_table, p_source_row_id, p_action_name, SQLERRM);
  END SAFE_REFRESH_REDUCTION_METRICS_ONE;

