      "THA_AN_PHAT", "THA_CO_QUAN_BAT_ID", "THA_NGAY_PHAM_TOI", "THA_SO_BAN_AN", "THA_THOI_GIAN_TAM_GIAM",
      "THA_THOI_GIAN_TAM_GIU", "THA_THOI_GIAN_O_TRUOC", "THA_NGAY_QD_THA", "THA_NGAY_BAN_AN",
      "THA_LOAI_BAN_AN_ID", "THA_TOA_QD_ID", "THA_NGAY_DEN_TRAI", "THA_SO_QD_DIEU_CHUYEN",
      "THA_NGAY_QD_DIEU_CHUYEN", "THA_SO_DE_NGHI", "THA_NGAY_DE_NGHI", "THA_DON_VI_DE_NGHI_ID",
      "THA_CHUYEN_DEN_TU_ID", "THA_NGAY_HET_HAN", "THA_SO_GCN_CHXHPT", "THA_SO_DANH_BAN",
      "THA_NGAY_LAP_DANH_BAN", "THA_CO_QUAN_LAP_ID", "THA_CONG_THUC_VAN_TAY", "THA_CONG_THUC_VAN_TAY_2",
      "THA_GHI_CHU_DAC_BIET", "THA_CHI_MUC_TIEM_KIEM", "THA_SO_QD_THA", "THA_DOI_TUONG", "THA_CAP_TOA_ID",
      "THA_DIA_PHUONG_DON_VI_DE_NGHI_ID", "THA_DIA_PHUONG_TOA_QD_THA_ID", "THA_DIA_PHUONG_DON_CO_QUAN_LAP_ID",
      "THA_DIA_PHUONG_CAP_TOA_ID", "THA_PNLAI_LICH_ID", "THA_DIA_PHUONG_CO_QUAN_BAT_ID", "THA_CREATION_TIME",
      "THA_CREATOR_USER_ID", "THA_DELETER_USER_ID", "THA_DELETION_TIME", "THA_IS_DELETED",
      "THA_LAST_MODIFICATION_TIME", "THA_LAST_MODIFIER_USER_ID", "THA_TONG_AN_GIAM", "THA_NGAY_BAT_DAU_O_TU",
      "THA_MUC_AN_ID", "THA_THOI_GIAN_CON_LAI", "THA_THOI_GIAN_DA_CHAP_HANH", "THA_MA_AN_PHAT",
      "THA_BUONG_GIAM", "THA_AN_PHAT_GOC", "THA_MUC_DO_NGHIEM_TRONG_ID", "THA_TOI_DANH_NAMES",
      "TOI_DANH_DAU_TIEN", "NAM_SINH", "GHI_CHU", "THOI_GIAN_DA_GIAM", "SO_LAN_GIAM"
    )
    WITH tha_latest AS (
      SELECT y.*
      FROM (
        SELECT
          t.*,
          ROW_NUMBER() OVER (
            PARTITION BY t.THA_PNLAI_LICH_ID
            ORDER BY NVL(t.THA_NGAY_BAN_AN, t.CREATION_TIME) DESC NULLS LAST, t.ID DESC
          ) AS rn
        FROM "QLPN"."PN_THI_HANH_AN" t
      ) y
      WHERE y.rn = 1
    )
    SELECT
      ll.ID AS PHAM_NHAN_ID,
      tha.ID AS SRC_THA_ID,
      SYSTIMESTAMP AS LAST_REFRESH_TIME,
      CASE
        WHEN NVL(ll.IS_DELETED, 0) = 1 THEN 1
        WHEN tha.ID IS NOT NULL AND NVL(tha.IS_DELETED, 0) = 1 THEN 1
        ELSE 0
      END AS IS_DELETED,
      ll.LL_ANH,
      ll.LL_SO_HO_SO_LAN_DAU,
      ll.LL_SO_HO_PHU,
      ll.LL_CCCD,
      ll.LL_HO_CHIEU,
      ll.LL_HO_TEN,
      ll.LL_TEN_KHAC,
      ll.LL_DIA_CHI_THUONG_TRU_OLD,
      ll.LL_NOI_OTRUOC_KHI_BAT,
      ll.LL_NOI_OKHAC,
      ll.LL_NGUYEN_QUAN,
      ll.LL_NOI_THA_VE_CU_TRU,
      ll.LL_CHI_TIET_HV,
      ll.LL_TOM_TAT_HV,
      ll.LL_CHI_MUC_TIM_KIEM,
      ll.LL_TRINH_DO_CHUYEN_MON,
      ll.LL_NGHE_CU_THE,
      ll.LL_CHI_TIET_BENH_VAO,
      ll.LL_CHI_TIET_BENH_HIEN_TAI,
      ll.LL_GHI_CHU_RIENG,
      ll.LL_GHI_CHU_CHI_TIET,
      ll.LL_PHAN_DOI_ID,
      ll.LL_TINH_TRANG_ID,
      ll.LL_TRINH_DO_HOC_VAN_ID,
      ll.LL_TRAI_GIAM_ID,
      ll.LL_TINH_TRANG_HOC_TAP_ID,
      ll.LL_BIET_DOC_VIET_ID,
      ll.LL_BENH_TAT_VAO_ID,
      ll.LL_DM_GIOI_TINH_ID,
      ll.LL_DIA_CHI_THUONG_TRU_PROVICE,
      ll.LL_DIA_CHI_THUONG_TRU_WARD,
      ll.LL_NOI_OTRUOC_KHI_BAT_PROVICE,
      ll.LL_NOI_OTRUOC_KHI_BAT_WARD,
      ll.LL_NOI_OKHAC_PROVICE,
      ll.LL_NOI_OKHAC_WARD,
      ll.LL_NOI_THA_VE_CU_TRU_PROVICE,
      ll.LL_NOI_THA_VE_CU_TRU_WARD,
      ll.LL_DM_NGHE_NGHIEP_ID,
      ll.LL_DM_HOC_VAN_ID,
      ll.LL_DM_QUOC_TICH_ID,
      ll.LL_DM_TON_GIAO_ID,
      ll.LL_DM_DAN_TOC_ID,
      ll.LL_PN_GIAO_NHAN_PHAN_NHAN_ID,
      ll.LL_SUC_KHOE_KHI_VAO_ID,
      ll.LL_SO_TIEN_SU,
      ll.LL_GHI_CHU_TIEN_SU,
      ll.LL_SO_TIEN_AN,
      ll.LL_TAI_PHAM,
      ll.LL_NHAN_THAN,
      ll.CREATION_TIME AS LL_CREATION_TIME,
      ll.CREATOR_USER_ID AS LL_CREATOR_USER_ID,
      ll.LAST_MODIFICATION_TIME AS LL_LAST_MODIFICATION_TIME,
      ll.LAST_MODIFIER_USER_ID AS LL_LAST_MODIFIER_USER_ID,
      ll.IS_DELETED AS LL_IS_DELETED,
      ll.DELETER_USER_ID AS LL_DELETER_USER_ID,
      ll.DELETION_TIME AS LL_DELETION_TIME,
      ll.LL_PHAN_TRAI_ID,
      ll.LL_NGAY_SINH,
      ll.LL_SO_GCN,
      ll.LL_GHI_CHU_CHUNG_HPBS,
      ll.PN_MA_TINH_TRANG_TRICH_XUAT,
      ll.LL_DIA_CHI_THA_VE_CU_TRU_CU,
      ll.LL_DIA_CHI_THUONG_TRU_CU,
      ll.LL_DIA_CHI_TRUOC_KHI_BAT_CU,
      ll.LL_BENH_HIEN_TAI_ID,
      ll.LL_TINH_TRANG_OLD_ID,
      ll.LL_DIA_CHI_THUONG_TRU,
      ll.HO_TEN_ORDER,
      ll.LL_NGAY_CAP_CCCD,
      ll.LL_NOI_CAP_CCCD,
      tha.ID AS THA_ID,
      tha.THA_DIEU,
      tha.THA_KHOAN,
      tha.THA_TOI_DANH,
      tha.THA_CAN_CU_TUYEN_PHAT,
      tha.THA_NGAY_BAT,
      tha.THA_AN_PHAT,
      tha.THA_CO_QUAN_BAT_ID,
      tha.THA_NGAY_PHAM_TOI,
      tha.THA_SO_BAN_AN,
      tha.THA_THOI_GIAN_TAM_GIAM,
      tha.THA_THOI_GIAN_TAM_GIU,
      tha.THA_THOI_GIAN_O_TRUOC,
      tha.THA_NGAY_QD_THA,
      tha.THA_NGAY_BAN_AN,
      tha.THA_LOAI_BAN_AN_ID,
      tha.THA_TOA_QD_ID,
      tha.THA_NGAY_DEN_TRAI,
      tha.THA_SO_QD_DIEU_CHUYEN,
      tha.THA_NGAY_QD_DIEU_CHUYEN,
      tha.THA_SO_DE_NGHI,
      tha.THA_NGAY_DE_NGHI,
      tha.THA_DON_VI_DE_NGHI_ID,
      tha.THA_CHUYEN_DEN_TU_ID,
      tha.THA_NGAY_HET_HAN,
      tha.THA_SO_GCN_CHXHPT,
      tha.THA_SO_DANH_BAN,
      tha.THA_NGAY_LAP_DANH_BAN,
      tha.THA_CO_QUAN_LAP_ID,
      tha.THA_CONG_THUC_VAN_TAY,
      tha.THA_CONG_THUC_VAN_TAY_2,
      tha.THA_GHI_CHU_DAC_BIET,
      tha.THA_CHI_MUC_TIEM_KIEM,
      tha.THA_SO_QD_THA,
      tha.THA_DOI_TUONG,
      tha.THA_CAP_TOA_ID,
      tha.THA_DIA_PHUONG_DON_VI_DE_NGHI_ID,
      tha.THA_DIA_PHUONG_TOA_QD_THA_ID,
      tha.THA_DIA_PHUONG_DON_CO_QUAN_LAP_ID,
      tha.THA_DIA_PHUONG_CAP_TOA_ID,
      tha.THA_PNLAI_LICH_ID,
      tha.THA_DIA_PHUONG_CO_QUAN_BAT_ID,
      tha.CREATION_TIME AS THA_CREATION_TIME,
      tha.CREATOR_USER_ID AS THA_CREATOR_USER_ID,
      tha.DELETER_USER_ID AS THA_DELETER_USER_ID,
      tha.DELETION_TIME AS THA_DELETION_TIME,
      tha.IS_DELETED AS THA_IS_DELETED,
      tha.LAST_MODIFICATION_TIME AS THA_LAST_MODIFICATION_TIME,
      tha.LAST_MODIFIER_USER_ID AS THA_LAST_MODIFIER_USER_ID,
      tha.THA_TONG_AN_GIAM,
      tha.THA_NGAY_BAT_DAU_O_TU,
      tha.THA_MUC_AN_ID,
      tha.THA_THOI_GIAN_CON_LAI,
      tha.THA_THOI_GIAN_DA_CHAP_HANH,
      tha.THA_MA_AN_PHAT,
      tha.THA_BUONG_GIAM,
      tha.THA_AN_PHAT_GOC,
      tha.THA_MUC_DO_NGHIEM_TRONG_ID,
      tha.THA_TOI_DANH_NAMES,
      TO_NUMBER(
          TRIM(REGEXP_SUBSTR(
              REPLACE(REPLACE(tha.THA_TOI_DANH, '[', ''), ']', ''),
              '[^,]+', 1, 1))
          DEFAULT NULL ON CONVERSION ERROR) AS TOI_DANH_DAU_TIEN,
      CASE
        WHEN ll.LL_NGAY_SINH IS NOT NULL THEN
          CASE
            WHEN REGEXP_LIKE(TO_CHAR(ll.LL_NGAY_SINH), '^\d{4}$') THEN TO_NUMBER(TO_CHAR(ll.LL_NGAY_SINH))
            WHEN LENGTH(TO_CHAR(ll.LL_NGAY_SINH)) >= 4
              AND REGEXP_LIKE(SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), -4), '^\d{4}$')
            THEN TO_NUMBER(SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), -4))
            WHEN REGEXP_LIKE(TO_CHAR(ll.LL_NGAY_SINH), '\d{4}')
            THEN TO_NUMBER(REGEXP_SUBSTR(TO_CHAR(ll.LL_NGAY_SINH), '\d{4}', 1, 1))
            ELSE NULL
          END
        ELSE NULL
      END AS NAM_SINH,
      CASE
        WHEN ll.LL_GHI_CHU_RIENG IS NOT NULL OR ll.LL_GHI_CHU_CHI_TIET IS NOT NULL
        THEN COALESCE(ll.LL_GHI_CHU_RIENG, u'')
           || CASE
                WHEN ll.LL_GHI_CHU_RIENG IS NOT NULL AND ll.LL_GHI_CHU_CHI_TIET IS NOT NULL
                THEN u' | '
                ELSE u''
              END
           || COALESCE(ll.LL_GHI_CHU_CHI_TIET, u'')
        ELSE NULL
      END AS GHI_CHU,
      CASE
        WHEN ll.ID IS NOT NULL
        THEN PKG_TINH_AN.FN_TINH_TONG_THOI_GIAN_GIAM(ll.ID)
        ELSE NULL
      END AS THOI_GIAN_DA_GIAM,
      NVL(PKG_TINH_AN.FN_TINH_SO_LAN_GIAM_AN(ll.ID), 0) AS SO_LAN_GIAM
    FROM "QLPN"."PN_LAI_LICHS" ll
    LEFT JOIN tha_latest tha
      ON tha.THA_PNLAI_LICH_ID = ll.ID;

    COMMIT;
  END REBUILD_ALL_BULK;

  PROCEDURE REBUILD_ALL IS
  BEGIN
    FOR r IN (
      SELECT ll.ID
      FROM "QLPN"."PN_LAI_LICHS" ll
    ) LOOP
      SAFE_REFRESH_ONE(r.ID, 'REBUILD_ALL', r.ID, 'REBUILD');
    END LOOP;
  END REBUILD_ALL;
END;

