  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "QLPN"."PKG_QUAN_HE_GIA_DINH" AS
  FUNCTION FN_GET_HO_TEN_BO(p_pham_nhan_id IN NUMBER) RETURN NVARCHAR2 IS v_result NVARCHAR2(400);
  BEGIN IF p_pham_nhan_id IS NULL THEN RETURN NULL; END IF;
  SELECT t.HO_TEN_THAN_NHAN INTO v_result FROM (SELECT v.HO_TEN_THAN_NHAN,ROW_NUMBER()OVER(ORDER BY v.ID)rn FROM QLPN.VW_THAN_NHAN v WHERE v.PHAM_NHAN_ID=p_pham_nhan_id AND UPPER(TRIM(v.QUAN_HE)) LIKE 'B?%') t WHERE t.rn=1;
  RETURN v_result; EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL; END;
  FUNCTION FN_GET_NAM_SINH_BO(p_pham_nhan_id IN NUMBER) RETURN NVARCHAR2 IS v_result NVARCHAR2(4000);
  BEGIN IF p_pham_nhan_id IS NULL THEN RETURN NULL; END IF;
  SELECT t.NGAY_SINH INTO v_result FROM (SELECT v.NGAY_SINH,ROW_NUMBER()OVER(ORDER BY v.ID)rn FROM QLPN.VW_THAN_NHAN v WHERE v.PHAM_NHAN_ID=p_pham_nhan_id AND UPPER(TRIM(v.QUAN_HE)) LIKE 'B?%') t WHERE t.rn=1;
  RETURN v_result; EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL; END;
  FUNCTION FN_GET_NGHE_NGHIEP_BO(p_pham_nhan_id IN NUMBER) RETURN NVARCHAR2 IS v_result NVARCHAR2(400);
  BEGIN IF p_pham_nhan_id IS NULL THEN RETURN NULL; END IF;
  SELECT t.NGHE_NGHIEP INTO v_result FROM (SELECT v.NGHE_NGHIEP,ROW_NUMBER()OVER(ORDER BY v.ID)rn FROM QLPN.VW_THAN_NHAN v WHERE v.PHAM_NHAN_ID=p_pham_nhan_id AND UPPER(TRIM(v.QUAN_HE)) LIKE 'B?%') t WHERE t.rn=1;
  RETURN v_result; EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL; END;
  FUNCTION FN_GET_CHO_HIEN_NAY_BO(p_pham_nhan_id IN NUMBER) RETURN NVARCHAR2 IS v_result NVARCHAR2(4000);
  BEGIN IF p_pham_nhan_id IS NULL THEN RETURN NULL; END IF;
  SELECT t.NOI_O INTO v_result FROM (SELECT v.NOI_O,ROW_NUMBER()OVER(ORDER BY v.ID)rn FROM QLPN.VW_THAN_NHAN v WHERE v.PHAM_NHAN_ID=p_pham_nhan_id AND UPPER(TRIM(v.QUAN_HE)) LIKE 'B?%') t WHERE t.rn=1;
  RETURN v_result; EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL; END;
  FUNCTION FN_GET_HO_TEN_ME(p_pham_nhan_id IN NUMBER) RETURN NVARCHAR2 IS v_result NVARCHAR2(400);
  BEGIN IF p_pham_nhan_id IS NULL THEN RETURN NULL; END IF;
  SELECT t.HO_TEN_THAN_NHAN INTO v_result FROM (SELECT v.HO_TEN_THAN_NHAN,ROW_NUMBER()OVER(ORDER BY v.ID)rn FROM QLPN.VW_THAN_NHAN v WHERE v.PHAM_NHAN_ID=p_pham_nhan_id AND UPPER(TRIM(v.QUAN_HE)) LIKE 'M?%') t WHERE t.rn=1;
  RETURN v_result; EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL; END;
  FUNCTION FN_GET_NAM_SINH_ME(p_pham_nhan_id IN NUMBER) RETURN NVARCHAR2 IS v_result NVARCHAR2(4000);
  BEGIN IF p_pham_nhan_id IS NULL THEN RETURN NULL; END IF;
  SELECT t.NGAY_SINH INTO v_result FROM (SELECT v.NGAY_SINH,ROW_NUMBER()OVER(ORDER BY v.ID)rn FROM QLPN.VW_THAN_NHAN v WHERE v.PHAM_NHAN_ID=p_pham_nhan_id AND UPPER(TRIM(v.QUAN_HE)) LIKE 'M?%') t WHERE t.rn=1;
  RETURN v_result; EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL; END;
  FUNCTION FN_GET_NGHE_NGHIEP_ME(p_pham_nhan_id IN NUMBER) RETURN NVARCHAR2 IS v_result NVARCHAR2(400);
  BEGIN IF p_pham_nhan_id IS NULL THEN RETURN NULL; END IF;
  SELECT t.NGHE_NGHIEP INTO v_result FROM (SELECT v.NGHE_NGHIEP,ROW_NUMBER()OVER(ORDER BY v.ID)rn FROM QLPN.VW_THAN_NHAN v WHERE v.PHAM_NHAN_ID=p_pham_nhan_id AND UPPER(TRIM(v.QUAN_HE)) LIKE 'M?%') t WHERE t.rn=1;
  RETURN v_result; EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL; END;
  FUNCTION FN_GET_CHO_HIEN_NAY_ME(p_pham_nhan_id IN NUMBER) RETURN NVARCHAR2 IS v_result NVARCHAR2(4000);
  BEGIN IF p_pham_nhan_id IS NULL THEN RETURN NULL; END IF;
  SELECT t.NOI_O INTO v_result FROM (SELECT v.NOI_O,ROW_NUMBER()OVER(ORDER BY v.ID)rn FROM QLPN.VW_THAN_NHAN v WHERE v.PHAM_NHAN_ID=p_pham_nhan_id AND UPPER(TRIM(v.QUAN_HE)) LIKE 'M?%') t WHERE t.rn=1;
  RETURN v_result; EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL; END;
  FUNCTION FN_GET_HO_TEN_VC(p_pham_nhan_id IN NUMBER) RETURN NVARCHAR2 IS v_result NVARCHAR2(400);
  BEGIN IF p_pham_nhan_id IS NULL THEN RETURN u'Ch\01b0a c\00f3'; END IF;
  SELECT NVL(TRIM(t.HO_TEN_THAN_NHAN),u'Ch\01b0a c\00f3') INTO v_result FROM (SELECT v.HO_TEN_THAN_NHAN,ROW_NUMBER()OVER(ORDER BY v.ID)rn FROM QLPN.VW_THAN_NHAN v WHERE v.PHAM_NHAN_ID=p_pham_nhan_id AND (UPPER(TRIM(v.QUAN_HE))='V?' OR UPPER(TRIM(v.QUAN_HE))='CH?NG')) t WHERE t.rn=1;
  RETURN NVL(TRIM(v_result),u'Ch\01b0a c\00f3'); EXCEPTION WHEN NO_DATA_FOUND THEN RETURN u'Ch\01b0a c\00f3'; END;
  FUNCTION FN_GET_NAM_SINH_VC(p_pham_nhan_id IN NUMBER) RETURN NVARCHAR2 IS v_result NVARCHAR2(4000);
  BEGIN IF p_pham_nhan_id IS NULL THEN RETURN NULL; END IF;
  SELECT t.NGAY_SINH INTO v_result FROM (SELECT v.NGAY_SINH,ROW_NUMBER()OVER(ORDER BY v.ID)rn FROM QLPN.VW_THAN_NHAN v WHERE v.PHAM_NHAN_ID=p_pham_nhan_id AND (UPPER(TRIM(v.QUAN_HE))='V?' OR UPPER(TRIM(v.QUAN_HE))='CH?NG')) t WHERE t.rn=1;
  RETURN v_result; EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL; END;
  FUNCTION FN_GET_NGHE_NGHIEP_VC(p_pham_nhan_id IN NUMBER) RETURN NVARCHAR2 IS v_result NVARCHAR2(400);
  BEGIN IF p_pham_nhan_id IS NULL THEN RETURN NULL; END IF;
  SELECT t.NGHE_NGHIEP INTO v_result FROM (SELECT v.NGHE_NGHIEP,ROW_NUMBER()OVER(ORDER BY v.ID)rn FROM QLPN.VW_THAN_NHAN v WHERE v.PHAM_NHAN_ID=p_pham_nhan_id AND (UPPER(TRIM(v.QUAN_HE))='V?' OR UPPER(TRIM(v.QUAN_HE))='CH?NG')) t WHERE t.rn=1;
  RETURN v_result; EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL; END;
  FUNCTION FN_GET_CHO_HIEN_NAY_VC(p_pham_nhan_id IN NUMBER) RETURN NVARCHAR2 IS v_result NVARCHAR2(4000);
  BEGIN IF p_pham_nhan_id IS NULL THEN RETURN NULL; END IF;
  SELECT t.NOI_O INTO v_result FROM (SELECT v.NOI_O,ROW_NUMBER()OVER(ORDER BY v.ID)rn FROM QLPN.VW_THAN_NHAN v WHERE v.PHAM_NHAN_ID=p_pham_nhan_id AND (UPPER(TRIM(v.QUAN_HE))='V?' OR UPPER(TRIM(v.QUAN_HE))='CH?NG')) t WHERE t.rn=1;
  RETURN v_result; EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL; END;
  FUNCTION FN_GET_CAC_CON(p_pham_nhan_id IN NUMBER) RETURN NVARCHAR2 IS v_result NVARCHAR2(4000);
  BEGIN IF p_pham_nhan_id IS NULL THEN RETURN NULL; END IF;
  SELECT LISTAGG(NVL(TRIM(c.HO_TEN_CON),''),', ')WITHIN GROUP(ORDER BY c.ID) INTO v_result FROM QLPN.THAN_NHAN_CON_CAIS c WHERE c.PHAM_NHAN_ID=p_pham_nhan_id AND NVL(c.IS_DELETED,0)=0 AND LENGTH(TRIM(NVL(c.HO_TEN_CON,'')))>0;
  RETURN v_result; EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL; END;
END PKG_QUAN_HE_GIA_DINH;






