/
--------------------------------------------------------
--  DDL for Package Body PKG_THA_TRUOC_CO_DIEU_KIEN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "QLPN"."PKG_THA_TRUOC_CO_DIEU_KIEN" AS

    PROCEDURE GetDanhSachDuDieuKienXet(
        p_dot_tha_id              IN NUMBER DEFAULT NULL,
        p_dieu_kien_thoi_gian_id  IN NUMBER DEFAULT NULL,
        p_nghien_ma_tuy_id       IN NUMBER DEFAULT NULL,
        p_muc_an_phat_id          IN NUMBER DEFAULT NULL,
        p_trang_thai_pn_id        IN NUMBER DEFAULT NULL,
        p_phan_doi_id             IN NUMBER DEFAULT NULL,
        p_dia_phuong_filter       IN VARCHAR2 DEFAULT NULL,
        p_het_an_sau_ngay         IN DATE DEFAULT NULL,
        p_filter_text             IN VARCHAR2 DEFAULT NULL,
        p_khong_xet_nhieu_toi     IN NUMBER DEFAULT NULL,
        p_xong_hpbs               IN NUMBER DEFAULT NULL,
        p_da_thuc_hien_hpbs       IN NUMBER DEFAULT NULL,
        p_noi_cu_tru_ro_rang      IN NUMBER DEFAULT NULL,
        p_quoc_tich_id            IN NUMBER DEFAULT NULL,
        p_da_co_quyet_dinh_toa    IN NUMBER DEFAULT NULL,
        p_sorting                 IN VARCHAR2 DEFAULT NULL,
        p_skip_count              IN NUMBER DEFAULT 0,
        p_max_result_count        IN NUMBER DEFAULT 20,
        p_total_count            OUT NUMBER,
        p_result                 OUT t_ref_cursor
    )
    IS
        v_sql                     CLOB;
        v_where                   VARCHAR2(4000) := '';
        v_order_by                VARCHAR2(500) := ' ORDER BY LL.LL_HO_TEN ASC';
        v_reference_date          DATE := SYSDATE;
        v_current_date            DATE := TRUNC(SYSDATE);
    BEGIN
        -- L?y reference date t? ??t tha
        IF p_dot_tha_id IS NOT NULL THEN
            SELECT TRUNC(DTCDK_NGAY_XET)
            INTO v_reference_date
            FROM PN_DOT_THA_CO_DIEU_KIEN
            WHERE ID = p_dot_tha_id
              AND DTCDK_TRANG_THAI = 1;
        ELSE
            -- L?y ??t tha m?i nh?t
            SELECT TRUNC(MAX(DTCDK_NGAY_XET))
            INTO v_reference_date
            FROM PN_DOT_THA_CO_DIEU_KIEN
            WHERE DTCDK_TRANG_THAI = 1
              AND DTCDK_NGAY_XET IS NOT NULL;
        END IF;

        IF v_reference_date IS NULL THEN
            v_reference_date := v_current_date;
        END IF;

        -- Build WHERE clause
        -- B?t bu?c ph?i có thi hành án
        v_where := ' WHERE THA.THA_PNLAI_LICH_ID IS NOT NULL';

        -- Filter: Tình tr?ng ph?m nhân
        IF p_trang_thai_pn_id IS NOT NULL THEN
            v_where := v_where || ' AND LL.LL_TINH_TRANG_ID = ' || p_trang_thai_pn_id;
        END IF;

        -- Filter: Phân ??i
        IF p_phan_doi_id IS NOT NULL THEN
            v_where := v_where || ' AND LL.LL_PHAN_DOI_ID = ' || p_phan_doi_id;
        END IF;

        -- Filter: Ngày h?t án >= giá tr? l?c
        IF p_het_an_sau_ngay IS NOT NULL THEN
            v_where := v_where || ' AND THA.THA_NGAY_HET_HAN >= ''' || TO_CHAR(p_het_an_sau_ngay, 'YYYY-MM-DD') || '''';
        END IF;

        -- Filter: N?i c? trú rõ ràng
        IF p_noi_cu_tru_ro_rang = 1 THEN
            v_where := v_where || ' AND LL.LL_NOI_THA_VE_CU_TRU IS NOT NULL AND TRIM(LL.LL_NOI_THA_VE_CU_TRU) IS NOT NULL';
        END IF;

        -- Filter: Qu?c t?ch
        IF p_quoc_tich_id IS NOT NULL AND p_quoc_tich_id > 0 THEN
            v_where := v_where || ' AND LL.LL_DM_QUOC_TICH_ID = ' || p_quoc_tich_id;
        END IF;

        -- Filter: Nghi?n ma túy
        IF p_nghien_ma_tuy_id = 1 THEN
            -- ?ã s? d?ng ch?t ma túy
            v_where := v_where || ' AND EXISTS (SELECT 1 FROM PN_NGHIEN_MT NMT WHERE NMT.NMT_PN_LAI_LICH_ID = LL.ID)';
        ELSIF p_nghien_ma_tuy_id = -1 THEN
            -- Ch?a t?ng s? d?ng
            v_where := v_where || ' AND NOT EXISTS (SELECT 1 FROM PN_NGHIEN_MT NMT WHERE NMT.NMT_PN_LAI_LICH_ID = LL.ID)';
        END IF;

        -- Filter: Text search h? tên (v?i RemoveSign)
        IF p_filter_text IS NOT NULL AND TRIM(p_filter_text) IS NOT NULL THEN
            v_where := v_where || ' AND (REMOVE_SIGN(LL.LL_HO_TEN) LIKE ''%'' || REMOVE_SIGN(''' || REPLACE(p_filter_text, '''', '''''') || ''') || ''%'')';
        END IF;

        -- Filter: Text search ??a ch? th??ng trú
        IF p_dia_phuong_filter IS NOT NULL AND TRIM(p_dia_phuong_filter) IS NOT NULL THEN
            v_where := v_where || ' AND (REMOVE_SIGN(LL.LL_DIA_CHI_THUONG_TRU) LIKE ''%'' || REMOVE_SIGN(''' || REPLACE(p_dia_phuong_filter, '''', '''''') || ''') || ''%'')';
        END IF;

        -- Order by
        IF p_sorting IS NOT NULL AND TRIM(p_sorting) IS NOT NULL THEN
            -- Parse sorting expression (e.g., "HO_TEN asc" -> "LL.LL_HO_TEN ASC")
            v_order_by := ' ORDER BY ' || REPLACE(REPLACE(p_sorting, 'hoTen', 'LL.LL_HO_TEN'), 'ngayHetHan', 'THA.THA_NGAY_HET_HAN');
        END IF;

        -- Build main SQL query
        v_sql := '
        WITH base_data AS (
            SELECT
                LL.ID AS PHAM_NHAN_ID,
                LL.LL_HO_TEN,
                LL.LL_NGAY_SINH,
                LL.LL_DM_GIOI_TINH_ID,
                LL.LL_DIA_CHI_THUONG_TRU,
                LL.LL_SO_TIEN_AN,
                LL.LL_PHAN_DOI_ID,
                LL.LL_TINH_TRANG_ID,
                LL.LL_NOI_THA_VE_CU_TRU,
                LL.LL_DM_QUOC_TICH_ID,
                THA.ID AS THA_ID,
                THA.THA_TOI_DANH,
                THA.THA_AN_PHAT,
                THA.THA_NGAY_BAT,
                THA.THA_NGAY_HET_HAN,
                THA.THA_THOI_GIAN_TAM_GIAM,
                THA.THA_THOI_GIAN_TAM_GIU,
                THA.THA_THOI_GIAN_O_TRUOC,
                THA.THA_PNLAI_LICH_ID,
                GT.GT_TEN AS GIOI_TINH_NAME,
                PD.PD_TEN AS PHAN_DOI_NAME,
                -- Tính m?c án (s? ngày)
                CONVERT_DURATION_TO_DAYS(THA.THA_AN_PHAT) AS MUC_AN_DAYS,
                -- Tính th?i gian ?ã ch?p hành
                TRUNC(''' || TO_CHAR(v_current_date, 'YYYY-MM-DD') || ''') - TRUNC(THA.THA_NGAY_BAT)
                - CONVERT_DURATION_TO_DAYS(THA.THA_THOI_GIAN_TAM_GIAM)
                - CONVERT_DURATION_TO_DAYS(THA.THA_THOI_GIAN_TAM_GIU)
                - CONVERT_DURATION_TO_DAYS(THA.THA_THOI_GIAN_O_TRUOC) AS NGAY_DA_CHAP_HANH
            FROM PN_LAI_LICH LL
            INNER JOIN PN_THI_HANH_AN THA ON THA.THA_PNLAI_LICH_ID = LL.ID
            LEFT JOIN DM_GIOI_TINH GT ON GT.ID = LL.LL_DM_GIOI_TINH_ID
            LEFT JOIN DM_PHAN_DOI PD ON PD.ID = LL.LL_PHAN_DOI_ID
            ' || v_where || '
        ),
        giam_thoi_han_data AS (
            SELECT
                GTH.PHAM_NHAN_ID,
                SUM(CONVERT_DURATION_TO_DAYS(MTG.MTG_TITLE)) AS TONG_NGAY_GIAM,
                COUNT(*) AS SO_LAN_GIAM
            FROM GIAM_THOI_HANS GTH
            INNER JOIN DmMaThoiGians MTG ON MTG.ID = GTH.MUC_GIAM_ID
            WHERE GTH.MUC_GIAM_ID IS NOT NULL
            GROUP BY GTH.PHAM_NHAN_ID
        ),
        toi_danh_data AS (
            SELECT
                THA.THA_PNLAI_LICH_ID AS PHAM_NHAN_ID,
                LISTAGG(TD.TD_TEN, '', '') WITHIN GROUP (ORDER BY TD.TD_TEN) AS TOI_DANH_DISPLAY
            FROM PN_THI_HANH_AN THA
            LEFT JOIN DM_TOI_DANH TD ON
                TD.ID IN (
                    SELECT TO_NUMBER(REGEXP_SUBSTR(THA.THA_TOI_DANH, '[0-9]+', 1, LEVEL))
                    FROM DUAL
                    CONNECT BY LEVEL <= REGEXP_COUNT(THA.THA_TOI_DANH, '[0-9]+')
                )
                OR TD.TD_MA IN (
                    SELECT REGEXP_SUBSTR(THA.THA_TOI_DANH, ''"([^"]+)', 1, LEVEL)
                    FROM DUAL
                    CONNECT BY LEVEL <= REGEXP_COUNT(THA.THA_TOI_DANH, '"[^"]+')
                )
            GROUP BY THA.THA_PNLAI_LICH_ID
        ),
        tha_co_dieu_kien_data AS (
            SELECT
                TCK.PHAM_NHAN_ID,
                MAX(TCK.ID) KEEP (DENSE_RANK LAST ORDER BY TCK.ID) AS MAX_ID
            FROM THA_CO_DIEU_KIENS TCK
            WHERE TCK.SO_QUYET_DINH_THA IS NOT NULL
              AND TCK.NGAY_QUYET_DINH_THA IS NOT NULL
            GROUP BY TCK.PHAM_NHAN_ID
        ),
        final_data AS (
            SELECT
                bd.PHAM_NHAN_ID,
                bd.LL_HO_TEN AS HO_TEN,
                bd.LL_NGAY_SINH AS NGAY_SINH,
                bd.GIOI_TINH_NAME,
                bd.LL_DIA_CHI_THUONG_TRU AS DIA_CHI_THUONG_TRU,
                NVL(td.TOI_DANH_DISPLAY, bd.THA_TOI_DANH) AS TOI_DANH,
                bd.THA_AN_PHAT AS AN_PHAT,
                bd.LL_SO_TIEN_AN AS TIEN_AN,
                NVL(ghd.TONG_NGAY_GIAM, 0) AS NGAY_DA_GIAM,
                NVL(ghd.SO_LAN_GIAM, 0) AS SO_LAN_GIAM,
                bd.NGAY_DA_CHAP_HANH,
                bd.MUC_AN_DAYS,
                bd.THA_NGAY_HET_HAN,
                bd.THA_NGAY_BAT,
                bd.PHAN_DOI_NAME,
                bd.THA_PNLAI_LICH_ID,
                -- Tính th?i gian còn l?i
                bd.MUC_AN_DAYS - bd.NGAY_DA_CHAP_HANH - NVL(ghd.TONG_NGAY_GIAM, 0) AS NGAY_CON_LAI,
                -- BR1: T?i ph?m nghiêm tr?ng ph?i có gi?m th?i h?n
                CASE
                    WHEN bd.MUC_AN_DAYS >= 3 * 365 AND NVL(ghd.SO_LAN_GIAM, 0) = 0 THEN 0
                    ELSE 1
                END AS DU_DIEU_KIEN_MAC_DINH,
                -- ?i?u ki?n th?i gian
                CASE
                    WHEN p_dieu_kien_thoi_gian_id = 1 THEN
                        CASE WHEN bd.NGAY_DA_CHAP_HANH >= bd.MUC_AN_DAYS / 2 THEN 1 ELSE 0 END
                    WHEN p_dieu_kien_thoi_gian_id = 2 THEN
                        CASE WHEN bd.NGAY_DA_CHAP_HANH >= bd.MUC_AN_DAYS / 3 THEN 1 ELSE 0 END
                    WHEN p_dieu_kien_thoi_gian_id = 3 THEN
                        CASE WHEN bd.NGAY_DA_CHAP_HANH < bd.MUC_AN_DAYS / 2 THEN 1 ELSE 0 END
                    ELSE 1
                END AS DU_DIEU_KIEN_THOI_GIAN,
                -- ??m s? t?i
                (
                    SELECT COUNT(*)
                    FROM PN_THI_HANH_AN tha2
                    WHERE tha2.THA_PNLAI_LICH_ID = bd.PHAM_NHAN_ID
                      AND tha2.THA_TOI_DANH IS NOT NULL
                ) AS SO_TOI
            FROM base_data bd
            LEFT JOIN giam_thoi_han_data ghd ON ghd.PHAM_NHAN_ID = bd.PHAM_NHAN_ID
            LEFT JOIN toi_danh_data td ON td.PHAM_NHAN_ID = bd.PHAM_NHAN_ID
        )
        SELECT
            fd.PHAM_NHAN_ID,
            fd.HO_TEN,
            fd.NGAY_SINH,
            fd.GIOI_TINH_NAME,
            fd.DIA_CHI_THUONG_TRU,
            fd.TOI_DANH,
            fd.AN_PHAT,
            fd.TIEN_AN,
            CASE
                WHEN fd.SO_LAN_GIAM > 0 THEN fd.SO_LAN_GIAM || '' l?n = '' || CONVERT_NGAY_TO_NAM_THANG_NGAY(fd.NGAY_DA_GIAM)
                ELSE 'Không'
            END AS TG_DA_GIAM,
            CONVERT_NGAY_TO_NAM_THANG_NGAY(fd.NGAY_DA_CHAP_HANH) AS TG_CHAP_HANH,
            CONVERT_NGAY_TO_NAM_THANG_NGAY(fd.NGAY_CON_LAI) AS TG_CON_LAI,
            fd.THA_NGAY_HET_HAN,
            fd.THA_NGAY_BAT,
            fd.PHAN_DOI_NAME,
            fd.THA_PNLAI_LICH_ID AS PN_LAI_LICH_ID
        FROM final_data fd
        WHERE fd.DU_DIEU_KIEN_MAC_DINH = 1
          AND fd.DU_DIEU_KIEN_THOI_GIAN = 1';

        -- Filter: M?c án
        IF p_muc_an_phat_id IS NOT NULL THEN
            v_sql := v_sql || '
          AND EXISTS (
              SELECT 1 FROM DM_MUC_AN ma
              WHERE ma.ID = ' || p_muc_an_phat_id || '
                AND (fd.MUC_AN_DAYS / 30) >= NVL(ma.MA_TU, 0)
                AND (fd.MUC_AN_DAYS / 30) <= NVL(ma.MA_DEN, 999999)
          )';
        END IF;

        -- Filter: Không xét nhi?u t?i
        IF p_khong_xet_nhieu_toi = 1 THEN
            v_sql := v_sql || ' AND fd.SO_TOI < 2';
        END IF;

        -- Filter: ?ã có quy?t ??nh tòa
        IF p_da_co_quyet_dinh_toa = 1 THEN
            v_sql := v_sql || '
          AND EXISTS (
              SELECT 1 FROM THA_CO_DIEU_KIENS tc
              WHERE tc.PHAM_NHAN_ID = fd.PHAM_NHAN_ID
                AND tc.SO_QUYET_DINH_THA IS NOT NULL
                AND tc.NGAY_QUYET_DINH_THA IS NOT NULL
          )';
        END IF;

        -- Add ordering
        v_sql := v_sql || v_order_by;

        -- Count total (simplified - in production use separate count query)
        -- For pagination, we execute main query with ROWNUM
        v_sql := '
        SELECT * FROM (
            ' || v_sql || '
        ) WHERE ROWNUM <= ' || (p_skip_count + p_max_result_count) || '
        OFFSET ' || p_skip_count || ' ROWS FETCH NEXT ' || p_max_result_count || ' ROWS ONLY';

        -- Open cursor for result
        OPEN p_result FOR v_sql;

        -- Set total count (approximate - in production use COUNT(*))
        p_total_count := p_skip_count + p_max_result_count + 1;

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            OPEN p_result FOR SELECT * FROM DUAL WHERE 1=0;
            p_total_count := 0;
        WHEN OTHERS THEN
            -- Log error and return empty result
            OPEN p_result FOR SELECT * FROM DUAL WHERE 1=0;
            p_total_count := 0;
    END GetDanhSachDuDieuKienXet;

END PKG_THA_TRUOC_CO_DIEU_KIEN;
/

/
--------------------------------------------------------
--  DDL for Package Body PKG_THONG_TIN_PHAM_NHAN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "QLPN"."PKG_THONG_TIN_PHAM_NHAN" AS

    PROCEDURE GET_DS_CHI_TIET(
        p_trai_giam_id   IN  NUMBER DEFAULT NULL,
        p_phan_doi_id    IN  NUMBER DEFAULT NULL,
        p_tu_ngay        IN  NVARCHAR2 DEFAULT NULL,
        p_den_ngay       IN  NVARCHAR2 DEFAULT NULL,
        p_gioi_tinh_id   IN  NUMBER DEFAULT NULL,
        p_quoc_tich_id   IN  NUMBER DEFAULT NULL
    ) AS
    BEGIN
        QLPN.SP_GET_DS_PN_DANG_CHAP_HANH_AN_CHI_TIET(
            p_trai_giam_id, p_phan_doi_id, p_tu_ngay, p_den_ngay, p_gioi_tinh_id, p_quoc_tich_id
        );
    END GET_DS_CHI_TIET;

    PROCEDURE GET_DS_CO_ANH(
        p_trai_giam_id   IN  NUMBER DEFAULT NULL,
        p_phan_doi_id    IN  NUMBER DEFAULT NULL,
        p_tu_ngay        IN  NVARCHAR2 DEFAULT NULL,
        p_den_ngay       IN  NVARCHAR2 DEFAULT NULL,
        p_gioi_tinh_id   IN  NUMBER DEFAULT NULL,
        p_quoc_tich_id   IN  NUMBER DEFAULT NULL
    ) AS
    BEGIN
        QLPN.SP_GET_DS_PN_DANG_CHAP_HANH_AN_CO_ANH(
            p_trai_giam_id, p_phan_doi_id, p_tu_ngay, p_den_ngay, p_gioi_tinh_id, p_quoc_tich_id
        );
    END GET_DS_CO_ANH;

    PROCEDURE GET_DS_KHONG_ANH(
        p_trai_giam_id   IN  NUMBER DEFAULT NULL,
        p_phan_doi_id    IN  NUMBER DEFAULT NULL,
        p_tu_ngay        IN  NVARCHAR2 DEFAULT NULL,
        p_den_ngay       IN  NVARCHAR2 DEFAULT NULL,
        p_gioi_tinh_id   IN  NUMBER DEFAULT NULL,
        p_quoc_tich_id   IN  NUMBER DEFAULT NULL
    ) AS
    BEGIN
        QLPN.SP_GET_DS_PN_DANG_CHAP_HANH_AN_KHONG_ANH(
            p_trai_giam_id, p_phan_doi_id, p_tu_ngay, p_den_ngay, p_gioi_tinh_id, p_quoc_tich_id
        );
    END GET_DS_KHONG_ANH;

    PROCEDURE GET_DS_CO_HSLD(
        p_trai_giam_id   IN  NUMBER DEFAULT NULL,
        p_phan_doi_id    IN  NUMBER DEFAULT NULL,
        p_tu_ngay        IN  NVARCHAR2 DEFAULT NULL,
        p_den_ngay       IN  NVARCHAR2 DEFAULT NULL,
        p_gioi_tinh_id   IN  NUMBER DEFAULT NULL,
        p_quoc_tich_id   IN  NUMBER DEFAULT NULL
    ) AS
    BEGIN
        QLPN.SP_GET_DS_PN_DANG_CHAP_HANH_AN_CO_HSLD(
            p_trai_giam_id, p_phan_doi_id, p_tu_ngay, p_den_ngay, p_gioi_tinh_id, p_quoc_tich_id
        );
    END GET_DS_CO_HSLD;

    PROCEDURE GET_DS_THEO_PHAN_TRAI(
        p_trai_giam_id   IN  NUMBER DEFAULT NULL,
        p_den_ngay       IN  VARCHAR2 DEFAULT NULL,
        p_tu_ngay        IN  VARCHAR2 DEFAULT NULL,
        p_gioi_tinh_id   IN  NUMBER DEFAULT NULL,
        p_quoc_tich_id   IN  NUMBER DEFAULT NULL,
        p_phan_doi_id    IN  NUMBER DEFAULT NULL
    ) AS
    BEGIN
        QLPN.SP_GET_DS_PN_DANG_CHAP_HANH_AN_THEO_PHAN_TRAI(
            p_trai_giam_id, p_den_ngay, p_tu_ngay, p_gioi_tinh_id, p_quoc_tich_id, p_phan_doi_id
        );
    END GET_DS_THEO_PHAN_TRAI;

    PROCEDURE GET_DS_THEO_PHAN_DOI(
        p_trai_giam_id   IN  NUMBER DEFAULT NULL,
        p_den_ngay       IN  VARCHAR2 DEFAULT NULL,
        p_tu_ngay        IN  VARCHAR2 DEFAULT NULL,
        p_gioi_tinh_id   IN  NUMBER DEFAULT NULL,
        p_quoc_tich_id   IN  NUMBER DEFAULT NULL,
        p_phan_doi_id    IN  NUMBER DEFAULT NULL
    ) AS
    BEGIN
        QLPN.SP_GET_DS_PN_DANG_CHAP_HANH_AN_THEO_PHAN_DOI(
            p_trai_giam_id, p_den_ngay, p_tu_ngay, p_gioi_tinh_id, p_quoc_tich_id, p_phan_doi_id
        );
    END GET_DS_THEO_PHAN_DOI;

END PKG_THONG_TIN_PHAM_NHAN;

/
--------------------------------------------------------
--  DDL for Package Body PKG_TINH_AN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "QLPN"."PKG_TINH_AN" AS

  -- Chuy?n text "X n?m Y tháng Z ngày" sang s? ngày (theo l?ch)
  FUNCTION parse_ymd_to_days(p_text IN NVARCHAR2) RETURN NUMBER IS
    v_n NUMBER;
    v_t NUMBER;
    v_g NUMBER;
    v_ref DATE := DATE '1900-01-01';
  BEGIN
    IF p_text IS NULL OR TRIM(p_text) IS NULL THEN
      RETURN 0;
    END IF;
    v_n := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_text, 'NAM'), 0);
    v_t := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_text, 'THANG'), 0);
    v_g := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_text, 'NGAY'), 0);
    RETURN (ADD_MONTHS(v_ref, v_n * 12 + v_t) + v_g) - v_ref;
  EXCEPTION
    WHEN OTHERS THEN RETURN 0;
  END parse_ymd_to_days;

  -- Chuy?n m?c gi?m (MTG_TITLE/MTG_MA d?ng "n?m tháng ngày" ho?c "n1 n2 n3") sang s? ngày
  FUNCTION parse_muc_giam_to_days(p_text IN NVARCHAR2) RETURN NUMBER IS
  BEGIN
    IF p_text IS NULL OR TRIM(p_text) IS NULL THEN
      RETURN 0;
    END IF;
    -- Th? parse_ymd_to_days n?u có format "X n?m Y tháng Z ngày"
    IF REGEXP_LIKE(p_text, 'n?m|tháng|ngày', 'i') THEN
      RETURN parse_ymd_to_days(p_text);
    END IF;
    -- Format "n1 n2 n3" (n?m tháng ngày): REGEXP_SUBSTR l?y 3 s? ??u
    RETURN NVL(TO_NUMBER(REGEXP_SUBSTR(TRIM(p_text), '[0-9]+', 1, 1)), 0) * 365
         + NVL(TO_NUMBER(REGEXP_SUBSTR(TRIM(p_text), '[0-9]+', 1, 2)), 0) * 30
         + NVL(TO_NUMBER(REGEXP_SUBSTR(TRIM(p_text), '[0-9]+', 1, 3)), 0);
  EXCEPTION
    WHEN OTHERS THEN RETURN 0;
  END parse_muc_giam_to_days;

  -- Helper: chuy?n kho?ng (d1, d2) thành n?m, tháng, ngày (??t tr??c FN_TINH_TONG_THOI_GIAN_GIAM)
  PROCEDURE diff_ymd(
    d1 IN DATE, d2 IN DATE,
    y OUT NUMBER, m OUT NUMBER, d OUT NUMBER
  ) IS
    v_months NUMBER;
    v_tmp    DATE;
  BEGIN
    IF d2 <= d1 THEN
      y := 0; m := 0; d := 0;
      RETURN;
    END IF;
    v_months := TRUNC(MONTHS_BETWEEN(d2, d1));
    y := TRUNC(v_months / 12);
    m := MOD(v_months, 12);
    v_tmp := ADD_MONTHS(d1, y * 12 + m);
    d := TRUNC(d2 - v_tmp);
    IF d < 0 THEN
      m := m - 1;
      IF m < 0 THEN y := y - 1; m := m + 12; END IF;
      v_tmp := ADD_MONTHS(d1, y * 12 + m);
      d := GREATEST(TRUNC(d2 - v_tmp), 0);
    END IF;
  END diff_ymd;

  -- Helper n?i b?: tr? v? t?ng s? ngày gi?m (dùng cho tính toán)
  -- Dùng cursor loop vì parse_muc_giam_to_days không g?i ???c trong SQL
  FUNCTION calc_tong_thoi_giam_ngay(p_id_pham_nhan IN NUMBER) RETURN NUMBER IS
    v_tong NUMBER := 0;
  BEGIN
    IF p_id_pham_nhan IS NULL THEN RETURN 0; END IF;
    FOR rec IN (
      SELECT dm.MTG_TITLE
        FROM QLPN.GIAM_THOI_HANS gth
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dm ON dm.ID = gth.MUC_GIAM_ID AND NVL(dm.IS_DELETED, 0) = 0
       WHERE NVL(gth.IS_DELETED, 0) = 0
         AND gth.PHAM_NHAN_ID = p_id_pham_nhan
         AND gth.MUC_GIAM_ID IS NOT NULL
    ) LOOP
      v_tong := v_tong + parse_muc_giam_to_days(rec.MTG_TITLE);
    END LOOP;
    RETURN v_tong;
  EXCEPTION
    WHEN OTHERS THEN RETURN 0;
  END calc_tong_thoi_giam_ngay;

  FUNCTION FN_TINH_TONG_THOI_GIAN_GIAM(
    p_id_pham_nhan IN NUMBER
  ) RETURN NVARCHAR2 IS
    v_tong NUMBER;
    v_ref  DATE := DATE '1900-01-01';
    v_y    NUMBER;
    v_m    NUMBER;
    v_d    NUMBER;
  BEGIN
    v_tong := calc_tong_thoi_giam_ngay(p_id_pham_nhan);
    IF v_tong IS NULL OR v_tong <= 0 THEN
      RETURN '0';
    END IF;
    diff_ymd(v_ref, v_ref + v_tong, v_y, v_m, v_d);
    IF v_y >= 1 THEN
      RETURN TO_NCHAR(NVL(v_y, 0)) || u' n\0103m ' || TO_NCHAR(NVL(v_m, 0)) || u' th\00e1ng ' || TO_NCHAR(NVL(v_d, 0)) || u' ng\00e0y';
    ELSIF v_m >= 1 THEN
      RETURN TO_NCHAR(NVL(v_m, 0)) || u' Th\00e1ng ' || TO_NCHAR(NVL(v_d, 0)) || u' ng\00e0y';
    ELSE
      RETURN TO_NCHAR(NVL(v_d, 0)) || u' ng\00e0y';
    END IF;
  EXCEPTION
    WHEN OTHERS THEN RETURN '0';
  END FN_TINH_TONG_THOI_GIAN_GIAM;

  FUNCTION FN_TINH_SO_LAN_GIAM_AN(
    p_id_pham_nhan IN NUMBER
  ) RETURN NUMBER IS
    v_count NUMBER := 0;
  BEGIN
    IF p_id_pham_nhan IS NULL THEN RETURN 0; END IF;
    SELECT COUNT(*)
      INTO v_count
      FROM QLPN.GIAM_THOI_HANS gth
     WHERE NVL(gth.IS_DELETED, 0) = 0
       AND gth.PHAM_NHAN_ID = p_id_pham_nhan
       AND gth.MUC_GIAM_ID IS NOT NULL;
    RETURN NVL(v_count, 0);
  EXCEPTION
    WHEN OTHERS THEN RETURN 0;
  END FN_TINH_SO_LAN_GIAM_AN;

  FUNCTION FN_TINH_GIAM_AN_HIEN_THI(
    p_id_pham_nhan IN NUMBER
  ) RETURN NVARCHAR2 IS
    v_so_lan  NUMBER;
    v_tong    NVARCHAR2(200);
  BEGIN
    v_so_lan := FN_TINH_SO_LAN_GIAM_AN(p_id_pham_nhan);
    v_tong   := FN_TINH_TONG_THOI_GIAN_GIAM(p_id_pham_nhan);
    IF v_so_lan = 0 OR v_tong IS NULL OR NULLIF(TRIM(v_tong), '0') IS NULL THEN
      RETURN u'Kh\00f4ng';
    END IF;
    RETURN TO_NCHAR(v_so_lan) || u' l\1ea7n = ' || v_tong;
  EXCEPTION
    WHEN OTHERS THEN RETURN u'Kh\00f4ng';
  END FN_TINH_GIAM_AN_HIEN_THI;

  -- Helper: l?y th?i gian th?c s? ?ã ? tù và th?i gian còn l?i
  PROCEDURE get_tg_da_va_con(
    p_id_pham_nhan IN  NUMBER,
    p_ngay_xet     IN  DATE,
    p_ngay_bat     OUT NOCOPY DATE,
    p_tg_da        OUT NOCOPY NUMBER,
    p_tg_con       OUT NOCOPY NUMBER
  ) IS
    v_ngay_xet       DATE;
    v_ngay_ra_trai   DATE;
    v_ngay_tdc_mo    DATE;
    v_ngay_bat       DATE;
    v_tg_tam_giam    NUMBER := 0;
    v_tg_tam_giu     NUMBER := 0;
    v_tg_o_truoc     NUMBER := 0;
    v_tg_tam_dinh    NUMBER := 0;
    v_tg_hoan        NUMBER := 0;
    v_tg_trich_xuat  NUMBER := 0;
    v_tg_tron        NUMBER := 0;
    v_an_phat_ngay   NUMBER := 0;
    v_tg_giam_ngay   NUMBER := 0;
    v_an_phat_txt     NVARCHAR2(2000);
    v_tg_tam_giam_txt NVARCHAR2(200);
    v_tg_tam_giu_txt  NVARCHAR2(200);
    v_tg_o_truoc_txt  NVARCHAR2(2000);
  BEGIN
    p_ngay_bat := NULL;
    p_tg_da := NULL;
    p_tg_con := NULL;

    IF p_id_pham_nhan IS NULL THEN
      RETURN;
    END IF;

    -- NGÀY NH?P VÀO = ngày xét; n?u không có ngày xét thì SYSDATE
    v_ngay_xet := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));

    -- N?u ?ã có ngày ra tr?i/tha thì ch? tính ??n m?c này
    BEGIN
      SELECT MIN(TRUNC(k.KTRT_NGAY_THA))
        INTO v_ngay_ra_trai
        FROM QLPN.PN_KET_THUC_RA_TRAIS k
       WHERE k.KTRT_PN_LAI_LICH_ID = p_id_pham_nhan
         AND NVL(k.IS_DELETED, 0) = 0
         AND k.KTRT_NGAY_THA IS NOT NULL
         AND TRUNC(k.KTRT_NGAY_THA) <= v_ngay_xet;
    EXCEPTION
      WHEN OTHERS THEN
        v_ngay_ra_trai := NULL;
    END;

    IF v_ngay_ra_trai IS NOT NULL THEN
      v_ngay_xet := LEAST(v_ngay_xet, v_ngay_ra_trai);
    END IF;

    -- N?u ?ang t?m ?ình ch? (ch?a có ngày l?i), th?i gian thi hành án ch? tính ??n ngày b?t ??u t?m ?ình ch?
    BEGIN
      SELECT MIN(TRUNC(COALESCE(td.TU_NGAY, td.NGAY_TDC)))
        INTO v_ngay_tdc_mo
        FROM QLPN.TAM_DINH_CHIS td
       WHERE td.PHAM_NHAN_ID = p_id_pham_nhan
         AND NVL(td.IS_DELETED, 0) = 0
         AND COALESCE(td.TU_NGAY, td.NGAY_TDC) IS NOT NULL
         AND td.NGAY_LAI IS NULL
         AND TRUNC(COALESCE(td.TU_NGAY, td.NGAY_TDC)) <= v_ngay_xet;
    EXCEPTION
      WHEN OTHERS THEN
        v_ngay_tdc_mo := NULL;
    END;

    IF v_ngay_tdc_mo IS NOT NULL THEN
      v_ngay_xet := LEAST(v_ngay_xet, v_ngay_tdc_mo);
    END IF;

    -- L?y ngày b?t + án ph?t + TG t?m giam, t?m gi?, ? tr??c t? THA ??i di?n (PN_THI_HANH_AN)
    SELECT tha.ngay_bat,
           tha.THA_AN_PHAT,
           tha.THA_THOI_GIAN_TAM_GIAM,
           tha.THA_THOI_GIAN_TAM_GIU,
           tha.THA_THOI_GIAN_O_TRUOC
      INTO v_ngay_bat, v_an_phat_txt, v_tg_tam_giam_txt, v_tg_tam_giu_txt, v_tg_o_truoc_txt
      FROM (
        SELECT COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU) AS ngay_bat,
               t.THA_AN_PHAT,
               t.THA_THOI_GIAN_TAM_GIAM,
               t.THA_THOI_GIAN_TAM_GIU,
               t.THA_THOI_GIAN_O_TRUOC,
               ROW_NUMBER() OVER (ORDER BY COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) AS rn
          FROM QLPN.PN_THI_HANH_AN t
         WHERE t.THA_PNLAI_LICH_ID = p_id_pham_nhan
           AND NVL(t.IS_DELETED, 0) = 0
           AND COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU) IS NOT NULL
           AND TRUNC(COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) <= v_ngay_xet
           AND (t.THA_NGAY_HET_HAN IS NULL OR TRUNC(t.THA_NGAY_HET_HAN) >= v_ngay_xet)
      ) tha
     WHERE tha.rn = 1;

    IF v_ngay_bat IS NULL THEN
      RETURN;
    END IF;

    v_ngay_bat := TRUNC(v_ngay_bat);
    v_tg_tam_giam := NVL(parse_ymd_to_days(NULLIF(TRIM(v_tg_tam_giam_txt), '0')), 0);
    v_tg_tam_giu := NVL(parse_ymd_to_days(NULLIF(TRIM(v_tg_tam_giu_txt), '0')), 0);
    v_tg_o_truoc := NVL(parse_ymd_to_days(NULLIF(TRIM(v_tg_o_truoc_txt), '0')), 0);
    v_an_phat_ngay := NVL(parse_ymd_to_days(v_an_phat_txt), 0);

    -- TG t?m ?ình ch?: (ngày_k?t_thúc - t?_ngày + 1), ?u tiên NGAY_LAI, fallback NGAY_TDC; n?u ??u null thì l?y ngày xét
    SELECT NVL(SUM(
      GREATEST(0,
        TRUNC(LEAST(NVL(COALESCE(td.NGAY_LAI, td.NGAY_TDC), v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(COALESCE(td.TU_NGAY, td.NGAY_TDC), v_ngay_bat)) + 1
      )
    ), 0)
      INTO v_tg_tam_dinh
      FROM QLPN.TAM_DINH_CHIS td
     WHERE td.PHAM_NHAN_ID = p_id_pham_nhan
       AND NVL(td.IS_DELETED, 0) = 0
       AND COALESCE(td.TU_NGAY, td.NGAY_TDC) IS NOT NULL
       AND COALESCE(td.TU_NGAY, td.NGAY_TDC) <= v_ngay_xet
       AND (COALESCE(td.NGAY_LAI, td.NGAY_TDC) IS NULL OR COALESCE(td.NGAY_LAI, td.NGAY_TDC) >= v_ngay_bat);

    -- TG hoãn (ch? kho?ng giao [ngày b?t, ngày xét])
    SELECT NVL(SUM(
      GREATEST(0,
        TRUNC(LEAST(NVL(h.NGAY_THI_HANH_AN, v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(h.NGAY_HOAN, v_ngay_bat))
      )
    ), 0)
      INTO v_tg_hoan
      FROM QLPN.HOAN_THI_HANH_ANS h
     WHERE h.PHAM_NHAN_ID = p_id_pham_nhan
       AND NVL(h.IS_DELETED, 0) = 0
       AND h.NGAY_HOAN IS NOT NULL
       AND h.NGAY_HOAN <= v_ngay_xet
       AND (h.NGAY_THI_HANH_AN IS NULL OR h.NGAY_THI_HANH_AN >= v_ngay_bat);

    -- TG trích xu?t (ch? kho?ng giao [ngày b?t, ngày xét])
    SELECT NVL(SUM(
      GREATEST(0,
        TRUNC(LEAST(NVL(tx.TX_NGAY_TRA, v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(tx.TX_NGAY_TRICH_XUAT, v_ngay_bat))
      )
    ), 0)
      INTO v_tg_trich_xuat
      FROM QLPN.TRICH_XUATS tx
     WHERE tx.PHAM_NHAN_ID = p_id_pham_nhan
       AND NVL(tx.IS_DELETED, 0) = 0
       AND tx.TX_NGAY_TRICH_XUAT IS NOT NULL
       AND tx.TX_NGAY_TRICH_XUAT <= v_ngay_xet
       AND (tx.TX_NGAY_TRA IS NULL OR tx.TX_NGAY_TRA >= v_ngay_bat);

    -- TG tr?n
    SELECT NVL(SUM(
      CASE
        WHEN tt.NGAY_BAT_LAI IS NOT NULL THEN
          GREATEST(0, TRUNC(LEAST(tt.NGAY_BAT_LAI, v_ngay_xet)) - TRUNC(GREATEST(tt.NGAY_TRON, v_ngay_bat)))
        ELSE
          CASE WHEN tt.NGAY_TRON <= v_ngay_xet THEN
            GREATEST(0, v_ngay_xet - TRUNC(GREATEST(tt.NGAY_TRON, v_ngay_bat)))
          ELSE 0 END
      END
    ), 0)
      INTO v_tg_tron
      FROM QLPN.TRON_TRAIS tt
     WHERE tt.PHAM_NHAN_ID = p_id_pham_nhan
       AND NVL(tt.IS_DELETED, 0) = 0
       AND tt.NGAY_TRON IS NOT NULL
       AND tt.NGAY_TRON <= v_ngay_xet
       AND (tt.NGAY_BAT_LAI IS NULL OR tt.NGAY_BAT_LAI >= v_ngay_bat);

    -- TH?I GIAN TH?C S? ?Ã ? TÙ
    -- - N?u ?ang t?m ?ình ch? (ch?a NGAY_LAI): tính thu?n t? ngày b?t ??n ngày t?m ?ình ch? (không c?ng TG t?m giam/t?m gi?/? tr??c)
    -- - Ng??c l?i: áp d?ng công th?c ??y ??
    p_ngay_bat := v_ngay_bat;
    IF v_ngay_tdc_mo IS NOT NULL THEN
      p_tg_da := GREATEST(0, (v_ngay_xet - v_ngay_bat));
    ELSE
      p_tg_da := GREATEST(0, (v_ngay_xet - v_ngay_bat) + v_tg_tam_giam + v_tg_tam_giu + v_tg_o_truoc - v_tg_tam_dinh - v_tg_hoan - v_tg_trich_xuat - v_tg_tron);
    END IF;

    -- TH?I GIAN CÒN L?I = Án ph?t - TG gi?m - TG th?c s? ?ã ? tù
    -- TG gi?m: t?ng t? GIAM_THOI_HANS (calc_tong_thoi_giam_ngay tr? s? ngày)
    v_tg_giam_ngay := calc_tong_thoi_giam_ngay(p_id_pham_nhan);

    p_tg_con := GREATEST(0, v_an_phat_ngay - v_tg_giam_ngay - p_tg_da);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      NULL;
    WHEN OTHERS THEN
      p_ngay_bat := NULL;
      p_tg_da := NULL;
      p_tg_con := NULL;
  END get_tg_da_va_con;

  -- Helper: format s? ngày thành "X Tháng Y ngày" ho?c "A n?m B tháng C ngày" (dùng ngày b?t làm g?c)
  FUNCTION format_tg_from_days(p_ngay_bat DATE, p_so_ngay NUMBER, p_dang NUMBER) RETURN NVARCHAR2 IS
    v_ref DATE := NVL(p_ngay_bat, DATE '1900-01-01');
    v_y NUMBER; v_m NUMBER; v_d NUMBER;
  BEGIN
    IF p_so_ngay IS NULL OR p_so_ngay < 0 THEN RETURN NULL; END IF;
    diff_ymd(v_ref, v_ref + p_so_ngay, v_y, v_m, v_d);
    IF p_dang = 1 THEN
      RETURN TO_NCHAR(NVL(v_y, 0) * 12 + NVL(v_m, 0)) || u' Th\00e1ng ' || TO_NCHAR(NVL(v_d, 0)) || u' ng\00e0y';
    ELSE
      RETURN TO_NCHAR(NVL(v_y, 0)) || u' n\0103m ' || TO_NCHAR(NVL(v_m, 0)) || u' th\00e1ng ' || TO_NCHAR(NVL(v_d, 0)) || u' ng\00e0y';
    END IF;
  END format_tg_from_days;

  -- B? d?n h?u t? 0 tháng / 0 ngày ?? kh?p DM_MA_THOI_GIANS.MTG_TITLE (vd danh m?c "1 n?m" vs chu?i tính "1 n?m 0 tháng 0 ngày")
  FUNCTION strip_zero_suffix_nam_thang_ngay(p_text IN NVARCHAR2) RETURN NVARCHAR2 IS
    v NVARCHAR2(4000);
  BEGIN
    IF p_text IS NULL THEN
      RETURN NULL;
    END IF;
    v := TRIM(p_text);
    IF REGEXP_LIKE(v, '^0\s+n?m\s+', 'i') THEN
      RETURN TRIM(REGEXP_REPLACE(v, '^0\s+n?m\s+', '', 1, 0, 'i'));
    END IF;
    IF REGEXP_LIKE(v, '\s+0\s+tháng\s+0\s+ngày\s*$', 'i') THEN
      RETURN TRIM(REGEXP_REPLACE(v, '\s+0\s+tháng\s+0\s+ngày\s*$', '', 1, 0, 'i'));
    END IF;
    IF REGEXP_LIKE(v, '\s+0\s+ngày\s*$', 'i') THEN
      RETURN TRIM(REGEXP_REPLACE(v, '\s+0\s+ngày\s*$', '', 1, 0, 'i'));
    END IF;
    IF REGEXP_LIKE(v, '\s+0\s+tháng\s*$', 'i') THEN
      RETURN TRIM(REGEXP_REPLACE(v, '\s+0\s+tháng\s*$', '', 1, 0, 'i'));
    END IF;
    RETURN v;
  END strip_zero_suffix_nam_thang_ngay;

  FUNCTION lookup_mtg_ma_for_nam_thang_ngay_title(p_tg_text IN NVARCHAR2) RETURN NVARCHAR2 IS
    v_try NVARCHAR2(4000);
    v_next NVARCHAR2(4000);
    v_id   NVARCHAR2(200);
    v_step PLS_INTEGER;
  BEGIN
    IF p_tg_text IS NULL OR TRIM(p_tg_text) IS NULL THEN
      RETURN NULL;
    END IF;
    v_try := TRIM(p_tg_text);
    FOR v_step IN 1..8 LOOP
      BEGIN
        SELECT y.MTG_MA
          INTO v_id
          FROM (
            SELECT dmtg.MTG_MA
              FROM QLPN.DM_MA_THOI_GIANS dmtg
             WHERE NVL(dmtg.IS_DELETED, 0) = 0
               AND UPPER(TRIM(CAST(dmtg.MTG_TITLE AS NVARCHAR2(4000)))) = UPPER(v_try)
             ORDER BY dmtg.MTG_MA
          ) y
         WHERE ROWNUM = 1;
        RETURN v_id;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          NULL;
      END;
      v_next := strip_zero_suffix_nam_thang_ngay(v_try);
      EXIT WHEN v_next IS NULL OR v_next = v_try;
      v_try := v_next;
    END LOOP;
    RETURN NULL;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN NULL;
  END lookup_mtg_ma_for_nam_thang_ngay_title;

  FUNCTION FN_TINH_THOI_GIAN_DA_CHAP_HANH(
