  FUNCTION FN_TINH_NGAY_THA(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN DATE IS
    v_ngay_bat     DATE;
    v_tg_da        NUMBER;
    v_tg_con       NUMBER;
    v_an_phat      NVARCHAR2(2000);
    v_tg_phai_serve NUMBER;
    v_cnt          NUMBER;
  BEGIN
    IF p_id_pham_nhan IS NULL THEN
      RETURN NULL;
    END IF;

    -- Tr?n ch?a b?t l?i ? NULL
    SELECT COUNT(*) INTO v_cnt
      FROM QLPN.TRON_TRAIS tt
     WHERE tt.PHAM_NHAN_ID = p_id_pham_nhan
       AND NVL(tt.IS_DELETED, 0) = 0
       AND tt.NGAY_BAT_LAI IS NULL;
    IF v_cnt > 0 THEN
      RETURN NULL;
    END IF;

    -- L?y THA_AN_PHAT ?? ki?m tra chung thân
    SELECT tha.THA_AN_PHAT
      INTO v_an_phat
      FROM (
        SELECT t.THA_AN_PHAT,
               ROW_NUMBER() OVER (ORDER BY COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) AS rn
          FROM QLPN.PN_THI_HANH_AN t
         WHERE t.THA_PNLAI_LICH_ID = p_id_pham_nhan
           AND NVL(t.IS_DELETED, 0) = 0
           AND COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU) IS NOT NULL
           AND TRUNC(COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) <= NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE))
           AND (t.THA_NGAY_HET_HAN IS NULL OR TRUNC(t.THA_NGAY_HET_HAN) >= NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE)))
      ) tha
     WHERE tha.rn = 1;

    -- Chung thân thu?n (có "chung thân" nh?ng không có "gi?m xu?ng") ? NULL
    IF v_an_phat IS NOT NULL
       AND (UPPER(v_an_phat) LIKE '%CHUNG THAN%' OR UPPER(v_an_phat) LIKE '%CHUNG THÂN%')
       AND (UPPER(v_an_phat) NOT LIKE '%GIAM XUONG%' AND UPPER(v_an_phat) NOT LIKE '%GI?M XU?NG%')
    THEN
      RETURN NULL;
    END IF;

    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con);
    IF v_ngay_bat IS NULL THEN
      RETURN NULL;
    END IF;

    -- Ngày tha = ngày b?t + (án ph?t - tg gi?m) = ngày b?t + (tg_con + tg_da)
    v_tg_phai_serve := v_tg_con + v_tg_da;
    IF v_tg_phai_serve IS NULL OR v_tg_phai_serve < 0 THEN
      RETURN NULL;
    END IF;

    RETURN v_ngay_bat + v_tg_phai_serve;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN NULL;
    WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_NGAY_THA;

  FUNCTION FN_TINH_NGAY_THA_CAP_NHAT_BAN_AN_KHAC(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN DATE IS
    v_ngay_bat         DATE;
    v_tg_da            NUMBER;
    v_tg_con           NUMBER;
    v_an_phat          NVARCHAR2(2000);
    v_an_phat_goc      NVARCHAR2(2000);
    v_an_phat_goc_ngay NUMBER := 0;
    v_tg_phai_serve    NUMBER;
    v_tg_giam_ngay     NUMBER := 0;
    v_bak_ngay         NUMBER := 0;
    v_bak_nam          NUMBER := 0;
    v_bak_thang        NUMBER := 0;
    v_bak_ngay_raw     NUMBER := 0;
    v_cnt              NUMBER;
  BEGIN
    IF p_id_pham_nhan IS NULL THEN
      RETURN NULL;
    END IF;

    -- Tr?n ch?a b?t l?i ? NULL
    SELECT COUNT(*) INTO v_cnt
      FROM QLPN.TRON_TRAIS tt
     WHERE tt.PHAM_NHAN_ID = p_id_pham_nhan
       AND NVL(tt.IS_DELETED, 0) = 0
       AND tt.NGAY_BAT_LAI IS NULL;
    IF v_cnt > 0 THEN
      RETURN NULL;
    END IF;

    -- L?y THA_AN_PHAT_GOC và THA_AN_PHAT (?? ki?m tra chung thân)
    BEGIN
      SELECT tha.THA_AN_PHAT_GOC, tha.THA_AN_PHAT
        INTO v_an_phat_goc, v_an_phat
        FROM (
          SELECT t.THA_AN_PHAT_GOC, t.THA_AN_PHAT,
                 ROW_NUMBER() OVER (ORDER BY COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) AS rn
            FROM QLPN.PN_THI_HANH_AN t
           WHERE t.THA_PNLAI_LICH_ID = p_id_pham_nhan
             AND NVL(t.IS_DELETED, 0) = 0
             AND COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU) IS NOT NULL
             AND TRUNC(COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) <= NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE))
             AND (t.THA_NGAY_HET_HAN IS NULL OR TRUNC(t.THA_NGAY_HET_HAN) >= NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE)))
        ) tha
       WHERE tha.rn = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RETURN NULL;
    END;

    -- Chung thân thu?n ? NULL
    IF v_an_phat IS NOT NULL
       AND (UPPER(v_an_phat) LIKE '%CHUNG THAN%' OR UPPER(v_an_phat) LIKE '%CHUNG THÂN%')
       AND (UPPER(v_an_phat) NOT LIKE '%GIAM XUONG%' AND UPPER(v_an_phat) NOT LIKE '%GI?M XU?NG%')
    THEN
      RETURN NULL;
    END IF;

    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con);
    IF v_ngay_bat IS NULL THEN
      RETURN NULL;
    END IF;

    -- Án chính g?c (THA_AN_PHAT_GOC) ? s? ngày
    v_an_phat_goc_ngay := NVL(parse_ymd_to_days(v_an_phat_goc), 0);

    -- TG gi?m
    v_tg_giam_ngay := calc_tong_thoi_giam_ngay(p_id_pham_nhan);

    -- Án BAK (s? ngày) t? PN_BAN_AN_KHACS
    BEGIN
      SELECT NVL(SUM(NVL(dmtg.MTG_NAM, 0)), 0),
             NVL(SUM(NVL(dmtg.MTG_THANG, 0)), 0),
             NVL(SUM(NVL(dmtg.MTG_NGAY, 0)), 0)
        INTO v_bak_nam, v_bak_thang, v_bak_ngay_raw
        FROM QLPN.PN_BAN_AN_KHACS bak
        JOIN QLPN.DM_MA_THOI_GIANS dmtg ON bak.BAK_MUC_AN_ID = dmtg.ID AND NVL(dmtg.IS_DELETED, 0) = 0
       WHERE bak.BAK_PN_LAI_LICH_ID = p_id_pham_nhan
         AND bak.BAK_MUC_AN_ID IS NOT NULL;
      v_bak_ngay := parse_ymd_to_days(TO_NCHAR(v_bak_nam) || u' n\0103m ' || TO_NCHAR(v_bak_thang) || u' th\00e1ng ' || TO_NCHAR(v_bak_ngay_raw) || u' ng\00e0y');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_bak_ngay := 0;
    END;

    -- Ngày tha = ngày b?t + (án chính g?c + án BAK - tg gi?m)
    v_tg_phai_serve := v_an_phat_goc_ngay + v_bak_ngay - v_tg_giam_ngay;
    IF v_tg_phai_serve IS NULL OR v_tg_phai_serve < 0 THEN
      RETURN NULL;
    END IF;

    RETURN v_ngay_bat + v_tg_phai_serve;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN NULL;
    WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_NGAY_THA_CAP_NHAT_BAN_AN_KHAC;

  FUNCTION FN_DA_CHAP_HANH_DAT_TY_LE(
    p_id_pham_nhan IN NUMBER,
    p_ratio        IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NUMBER IS
    v_ngay_bat       DATE;
    v_tg_da          NUMBER;
    v_tg_con         NUMBER;
    v_tong_ngay      NUMBER;
    v_ngay_tha       DATE;
    v_tong_thang     NUMBER;
    v_thang_nguong   NUMBER;
    v_nguyen_thang   NUMBER;
    v_le_thang       NUMBER;
    v_ngay_trong_thang NUMBER;
    v_ngay_nguong    DATE;
  BEGIN
    IF p_id_pham_nhan IS NULL OR p_ratio IS NULL OR p_ratio <= 0 THEN
      RETURN NULL;
    END IF;

    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con);
    IF v_ngay_bat IS NULL OR v_tg_da IS NULL OR v_tg_con IS NULL THEN
      RETURN NULL;
    END IF;

    v_tong_ngay := v_tg_da + v_tg_con;
    IF v_tong_ngay IS NULL OR v_tong_ngay <= 0 THEN
      RETURN NULL;
    END IF;

    -- So sánh theo 1/2 s? tháng tr??c; n?u l? tháng thì m?i xét ??n ngày
    v_ngay_tha := v_ngay_bat + v_tong_ngay;
    -- ROUND ?? tránh MONTHS_BETWEEN l?ch khi v_ngay_tha = ngày_b?t + tong_ngay (c?ng ngày có th? l?ch 1 ngày)
    -- VD: 14/09+1825 ngày = 13/09/2028 ? MONTHS_BETWEEN = 59.97 ? FLOOR(29.97)=29 (sai, ph?i 30)
    v_tong_thang := ROUND(MONTHS_BETWEEN(TRUNC(v_ngay_tha), TRUNC(v_ngay_bat)), 0);
    v_thang_nguong := p_ratio * v_tong_thang;
    v_nguyen_thang := FLOOR(v_thang_nguong);
    v_le_thang := v_thang_nguong - v_nguyen_thang;

    v_ngay_nguong := ADD_MONTHS(v_ngay_bat, v_nguyen_thang);
    IF v_le_thang > 0.0001 THEN
      v_ngay_trong_thang := ADD_MONTHS(v_ngay_bat, v_nguyen_thang + 1) - ADD_MONTHS(v_ngay_bat, v_nguyen_thang);
      v_ngay_nguong := v_ngay_nguong + (v_le_thang * v_ngay_trong_thang);
    END IF;

    -- Ngày ?ã ??t >= ngày ng??ng (b?t 14/09, ng??ng 14/03 ? 13/03 ch?a ??t)
    IF TRUNC(v_ngay_bat + v_tg_da) >= TRUNC(v_ngay_nguong) THEN
      RETURN 1;
    ELSE
      RETURN 0;
    END IF;

  EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
  END FN_DA_CHAP_HANH_DAT_TY_LE;

  FUNCTION FN_TINH_AN_BAO_GOM_BAN_AN_KHAC(
    p_id_pham_nhan IN NUMBER
  ) RETURN NVARCHAR2 IS
    v_an_nam   NUMBER := 0;
    v_an_thang NUMBER := 0;
    v_an_ngay  NUMBER := 0;
    v_bak_nam  NUMBER := 0;
    v_bak_thang NUMBER := 0;
    v_bak_ngay  NUMBER := 0;
    v_tha_an_phat NVARCHAR2(2000);
  BEGIN
    IF p_id_pham_nhan IS NULL THEN
      RETURN NULL;
    END IF;

    -- Án chính t? PN_THI_HANH_AN (THA_AN_PHAT_GOC)
    BEGIN
      SELECT tha.THA_AN_PHAT_GOC
        INTO v_tha_an_phat
        FROM (
          SELECT t.THA_AN_PHAT_GOC,
                 ROW_NUMBER() OVER (ORDER BY COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) AS rn
            FROM QLPN.PN_THI_HANH_AN t
           WHERE t.THA_PNLAI_LICH_ID = p_id_pham_nhan
             AND NVL(t.IS_DELETED, 0) = 0
             AND COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU) IS NOT NULL
        ) tha
       WHERE tha.rn = 1;
      v_an_nam   := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(v_tha_an_phat, 'NAM'), 0);
      v_an_thang := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(v_tha_an_phat, 'THANG'), 0);
      v_an_ngay  := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(v_tha_an_phat, 'NGAY'), 0);
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_an_nam := 0; v_an_thang := 0; v_an_ngay := 0;
    END;

    -- Án BAK t? PN_BAN_AN_KHACS (BAK_MUC_AN_ID -> DM_MA_THOI_GIANS)
    BEGIN
      SELECT NVL(SUM(NVL(dmtg.MTG_NAM, 0)), 0),
             NVL(SUM(NVL(dmtg.MTG_THANG, 0)), 0),
             NVL(SUM(NVL(dmtg.MTG_NGAY, 0)), 0)
        INTO v_bak_nam, v_bak_thang, v_bak_ngay
        FROM QLPN.PN_BAN_AN_KHACS bak
        JOIN QLPN.DM_MA_THOI_GIANS dmtg ON bak.BAK_MUC_AN_ID = dmtg.ID AND NVL(dmtg.IS_DELETED, 0) = 0
       WHERE bak.BAK_PN_LAI_LICH_ID = p_id_pham_nhan
         AND bak.BAK_MUC_AN_ID IS NOT NULL;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_bak_nam := 0; v_bak_thang := 0; v_bak_ngay := 0;
    END;

    -- C?ng và chu?n hóa (30 ngày = 1 tháng, 12 tháng = 1 n?m)
    v_an_nam   := v_an_nam + v_bak_nam;
    v_an_thang := v_an_thang + v_bak_thang;
    v_an_ngay  := v_an_ngay + v_bak_ngay;

    WHILE v_an_ngay >= 30 LOOP
      v_an_ngay := v_an_ngay - 30;
      v_an_thang := v_an_thang + 1;
    END LOOP;
    WHILE v_an_thang >= 12 LOOP
      v_an_thang := v_an_thang - 12;
      v_an_nam := v_an_nam + 1;
    END LOOP;

    RETURN TO_NCHAR(NVL(v_an_nam, 0)) || u' n\0103m ' || TO_NCHAR(NVL(v_an_thang, 0)) || u' th\00e1ng ' || TO_NCHAR(NVL(v_an_ngay, 0)) || u' ng\00e0y';

  EXCEPTION
    WHEN OTHERS THEN
      RETURN NULL;
  END FN_TINH_AN_BAO_GOM_BAN_AN_KHAC;

  FUNCTION FN_DA_CHAP_HANH_DAT_SO_NAM(
    p_id_pham_nhan IN NUMBER,
    p_so_nam       IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NUMBER IS
    v_ngay_bat   DATE;
    v_tg_da      NUMBER;
    v_tg_con     NUMBER;
    v_nguong     NUMBER;
  BEGIN
    IF p_id_pham_nhan IS NULL OR p_so_nam IS NULL OR p_so_nam <= 0 THEN
      RETURN NULL;
    END IF;

    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con);
    IF v_ngay_bat IS NULL OR v_tg_da IS NULL THEN
      RETURN NULL;
    END IF;

    -- Ng??ng theo l?ch th?c: s? ngày th?c t? c?a p_so_nam n?m t? ngày b?t (ADD_MONTHS tính n?m nhu?n ?úng)
    v_nguong := TRUNC(ADD_MONTHS(v_ngay_bat, p_so_nam * 12)) - TRUNC(v_ngay_bat);

    IF v_tg_da >= v_nguong THEN
      RETURN 1;
    END IF;

    RETURN 0;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN NULL;
  END FN_DA_CHAP_HANH_DAT_SO_NAM;

  FUNCTION FN_GET_CHI_TIET_THOI_GIAN_THI_HANH(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN QLPN.TYP_TINH_AN_CHI_TIET_TBL PIPELINED IS
    v_ngay_xet DATE;
    v_ngay_ra_trai DATE;
    v_ngay_tdc_mo  DATE;
    v_ngay_bat DATE;
  BEGIN
    IF p_id_pham_nhan IS NULL THEN
      RETURN;
    END IF;

    v_ngay_xet := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));

    -- Clamp ngày xét theo m?c nghi?p v? ?? chi ti?t kh?p logic tính t?ng
    -- 1) Có ngày ra tr?i/tha thì không v??t qua m?c này
    BEGIN
      SELECT MIN(TRUNC(k.KTRT_NGAY_THA))
        INTO v_ngay_ra_trai
        FROM QLPN.PN_KET_THUC_RA_TRAIS k
       WHERE k.KTRT_PN_LAI_LICH_ID = p_id_pham_nhan
         AND NVL(k.IS_DELETED, 0) = 0
         AND k.KTRT_NGAY_THA IS NOT NULL
         AND TRUNC(k.KTRT_NGAY_THA) <= v_ngay_xet;
    EXCEPTION
      WHEN OTHERS THEN
        v_ngay_ra_trai := NULL;
    END;

    IF v_ngay_ra_trai IS NOT NULL THEN
      v_ngay_xet := LEAST(v_ngay_xet, v_ngay_ra_trai);
    END IF;

    -- 2) N?u ?ang t?m ?ình ch? m? (NGAY_LAI IS NULL) thì ch?n t?i ngày m? t?m ?ình ch?
    BEGIN
      SELECT MIN(TRUNC(COALESCE(td.TU_NGAY, td.NGAY_TDC)))
        INTO v_ngay_tdc_mo
        FROM QLPN.TAM_DINH_CHIS td
       WHERE td.PHAM_NHAN_ID = p_id_pham_nhan
         AND NVL(td.IS_DELETED, 0) = 0
         AND COALESCE(td.TU_NGAY, td.NGAY_TDC) IS NOT NULL
         AND td.NGAY_LAI IS NULL
         AND TRUNC(COALESCE(td.TU_NGAY, td.NGAY_TDC)) <= v_ngay_xet;
    EXCEPTION
      WHEN OTHERS THEN
        v_ngay_tdc_mo := NULL;
    END;

    IF v_ngay_tdc_mo IS NOT NULL THEN
      v_ngay_xet := LEAST(v_ngay_xet, v_ngay_tdc_mo);
    END IF;

    -- L?y ngày b?t t? THA ??i di?n (cùng logic get_tg_da_va_con)
    BEGIN
      SELECT TRUNC(tha.ngay_bat)
        INTO v_ngay_bat
        FROM (
          SELECT COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU) AS ngay_bat,
                 ROW_NUMBER() OVER (ORDER BY COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) AS rn
            FROM QLPN.PN_THI_HANH_AN t
           WHERE t.THA_PNLAI_LICH_ID = p_id_pham_nhan
             AND NVL(t.IS_DELETED, 0) = 0
             AND COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU) IS NOT NULL
             AND TRUNC(COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) <= v_ngay_xet
             AND (t.THA_NGAY_HET_HAN IS NULL OR TRUNC(t.THA_NGAY_HET_HAN) >= v_ngay_xet)
        ) tha
       WHERE tha.rn = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_ngay_bat := NULL;
    END;

    IF v_ngay_bat IS NULL THEN
      RETURN;
    END IF;

    FOR rec IN (
      SELECT LOAI, TU_NGAY, DEN_NGAY, SO_NGAY, THU_TU
        FROM (
          SELECT u'NG\00c0Y B\1eaeT' AS LOAI, v_ngay_bat AS TU_NGAY, v_ngay_bat AS DEN_NGAY, NULL AS SO_NGAY, 1 AS THU_TU FROM DUAL
          UNION ALL
          SELECT u'T\1ea0M \0110\00ccNH CH\1ec8',
                 TRUNC(GREATEST(COALESCE(td.TU_NGAY, td.NGAY_TDC), v_ngay_bat)),
                 TRUNC(LEAST(NVL(COALESCE(td.NGAY_LAI, td.NGAY_TDC), v_ngay_xet), v_ngay_xet)),
                 GREATEST(0, TRUNC(LEAST(NVL(COALESCE(td.NGAY_LAI, td.NGAY_TDC), v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(COALESCE(td.TU_NGAY, td.NGAY_TDC), v_ngay_bat)) + 1),
                 2
            FROM QLPN.TAM_DINH_CHIS td
           WHERE td.PHAM_NHAN_ID = p_id_pham_nhan AND NVL(td.IS_DELETED, 0) = 0 AND COALESCE(td.TU_NGAY, td.NGAY_TDC) IS NOT NULL
             AND COALESCE(td.TU_NGAY, td.NGAY_TDC) <= v_ngay_xet AND (COALESCE(td.NGAY_LAI, td.NGAY_TDC) IS NULL OR COALESCE(td.NGAY_LAI, td.NGAY_TDC) >= v_ngay_bat)
          UNION ALL
          SELECT u'HO\00c3N',
                 TRUNC(GREATEST(h.NGAY_HOAN, v_ngay_bat)),
                 TRUNC(LEAST(NVL(h.NGAY_THI_HANH_AN, v_ngay_xet), v_ngay_xet)),
                 GREATEST(0, TRUNC(LEAST(NVL(h.NGAY_THI_HANH_AN, v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(h.NGAY_HOAN, v_ngay_bat))),
                 3
            FROM QLPN.HOAN_THI_HANH_ANS h
           WHERE h.PHAM_NHAN_ID = p_id_pham_nhan AND NVL(h.IS_DELETED, 0) = 0 AND h.NGAY_HOAN IS NOT NULL
             AND h.NGAY_HOAN <= v_ngay_xet AND (h.NGAY_THI_HANH_AN IS NULL OR h.NGAY_THI_HANH_AN >= v_ngay_bat)
          UNION ALL
          SELECT u'TRICH XUAT',
                 TRUNC(GREATEST(tx.TX_NGAY_TRICH_XUAT, v_ngay_bat)),
                 TRUNC(LEAST(NVL(tx.TX_NGAY_TRA, v_ngay_xet), v_ngay_xet)),
                 GREATEST(0, TRUNC(LEAST(NVL(tx.TX_NGAY_TRA, v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(tx.TX_NGAY_TRICH_XUAT, v_ngay_bat))),
                 4
            FROM QLPN.TRICH_XUATS tx
           WHERE tx.PHAM_NHAN_ID = p_id_pham_nhan
             AND NVL(tx.IS_DELETED, 0) = 0
             AND tx.TX_NGAY_TRICH_XUAT IS NOT NULL
             AND tx.TX_NGAY_TRICH_XUAT <= v_ngay_xet
             AND (tx.TX_NGAY_TRA IS NULL OR tx.TX_NGAY_TRA >= v_ngay_bat)
          UNION ALL
          SELECT u'TR\1ed0N',
                 TRUNC(GREATEST(tt.NGAY_TRON, v_ngay_bat)),
                 TRUNC(LEAST(NVL(tt.NGAY_BAT_LAI, v_ngay_xet), v_ngay_xet)),
                 CASE
                   WHEN tt.NGAY_BAT_LAI IS NOT NULL THEN GREATEST(0, TRUNC(LEAST(tt.NGAY_BAT_LAI, v_ngay_xet)) - TRUNC(GREATEST(tt.NGAY_TRON, v_ngay_bat)))
                   ELSE CASE WHEN tt.NGAY_TRON <= v_ngay_xet THEN GREATEST(0, v_ngay_xet - TRUNC(GREATEST(tt.NGAY_TRON, v_ngay_bat))) ELSE 0 END
                 END,
                 5
            FROM QLPN.TRON_TRAIS tt
           WHERE tt.PHAM_NHAN_ID = p_id_pham_nhan AND NVL(tt.IS_DELETED, 0) = 0 AND tt.NGAY_TRON IS NOT NULL
             AND tt.NGAY_TRON <= v_ngay_xet AND (tt.NGAY_BAT_LAI IS NULL OR tt.NGAY_BAT_LAI >= v_ngay_bat)
        )
       ORDER BY THU_TU, TU_NGAY
    ) LOOP
      PIPE ROW (QLPN.TYP_TINH_AN_CHI_TIET(rec.LOAI, rec.TU_NGAY, rec.DEN_NGAY, rec.SO_NGAY, rec.THU_TU));
    END LOOP;
    RETURN;

  EXCEPTION
    WHEN OTHERS THEN
      RAISE;
  END FN_GET_CHI_TIET_THOI_GIAN_THI_HANH;

  FUNCTION FN_GET_MUC_AN_ID_TU_AN_PHAT(
    p_tha_an_phat IN NVARCHAR2
  ) RETURN NUMBER IS
    v_upper NVARCHAR2(4000);
    v_norm  NVARCHAR2(4000);
    v_n     NUMBER;
    v_t     NUMBER;
    v_g     NUMBER;
    v_thang NUMBER;
    v_id    NUMBER;
    v_is_ct BOOLEAN;
  BEGIN
    IF p_tha_an_phat IS NULL OR TRIM(p_tha_an_phat) IS NULL THEN
      RETURN NULL;
    END IF;

    -- Hai tr??ng h?p ??c bi?t: so kh?p sau LOWER+TRIM (không dùng REGEXP — tránh PLS-00103 trên m?t s? b?n Oracle)
    v_norm := LOWER(TRIM(p_tha_an_phat));
    IF v_norm = u'chung th\00e2n gi\1ea3m xu\1ed1ng 20 n\0103m' THEN
      v_thang := 240;
      SELECT MIN(ma.ID)
        INTO v_id
        FROM QLPN.DM_MUC_ANS ma
       WHERE NVL(ma.IS_DELETED, 0) = 0
         AND ma.MA_TU < 900000
         AND v_thang >= ma.MA_TU
         AND v_thang <= ma.MA_DEN;
      RETURN v_id;
    END IF;
    IF v_norm = u'chung th\00e2n gi\1ea3m xu\1ed1ng 30 n\0103m' THEN
      v_thang := 360;
      SELECT MIN(ma.ID)
        INTO v_id
        FROM QLPN.DM_MUC_ANS ma
       WHERE NVL(ma.IS_DELETED, 0) = 0
         AND ma.MA_TU < 900000
         AND v_thang >= ma.MA_TU
         AND v_thang <= ma.MA_DEN;
      RETURN v_id;
    END IF;

    v_upper := UPPER(NVL(p_tha_an_phat, ''));
    v_is_ct := (v_upper LIKE '%CHUNG THAN%' OR v_upper LIKE '%CHUNG THÂN%');

    IF v_is_ct THEN
      SELECT MIN(ma.ID)
        INTO v_id
        FROM QLPN.DM_MUC_ANS ma
       WHERE NVL(ma.IS_DELETED, 0) = 0
         AND ma.MA_TU >= 900000;
      RETURN v_id;
    END IF;

    v_n := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'NAM'), 0);
    v_t := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'THANG'), 0);
    v_g := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'NGAY'), 0);
    v_thang := v_n * 12 + v_t + v_g / 30;

    SELECT MIN(ma.ID)
      INTO v_id
      FROM QLPN.DM_MUC_ANS ma
     WHERE NVL(ma.IS_DELETED, 0) = 0
       AND ma.MA_TU < 900000
       AND v_thang >= ma.MA_TU
       AND v_thang <= ma.MA_DEN;

    RETURN v_id;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN NULL;
  END FN_GET_MUC_AN_ID_TU_AN_PHAT;

  PROCEDURE SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI(
    p_tha_pnlai_lich_id IN NUMBER DEFAULT NULL,
    p_ngay_xet          IN DATE   DEFAULT NULL
  ) IS
    v_da  NVARCHAR2(200);
    v_con NVARCHAR2(200);
    v_muc_an_id NVARCHAR2(2000);
  BEGIN
    -- Không g?i FN trong m?nh ?? SET c?a UPDATE cùng b?ng PN_THI_HANH_AN mà hàm c?ng ??c b?ng này:
    -- trong ng? c?nh SQL có th? gây l?i/NULL; tính MTG_MA trong PL/SQL r?i gán scalar.
    FOR r IN (
      SELECT t.ROWID AS rid,
             t.THA_PNLAI_LICH_ID AS pn_id,
             t.THA_AN_PHAT       AS tha_an_phat
        FROM QLPN.PN_THI_HANH_AN t
        INNER JOIN QLPN.PN_LAI_LICHS pll
                ON pll.ID = t.THA_PNLAI_LICH_ID
               AND NVL(pll.IS_DELETED, 0) = 0
        INNER JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
                ON ttpn.ID = pll.LL_TINH_TRANG_ID
               AND NVL(ttpn.IS_DELETED, 0) = 0
               AND ttpn.TTPN_MA IN ('111', '112', '113', '114')
       WHERE NVL(t.IS_DELETED, 0) = 0
         AND t.THA_PNLAI_LICH_ID IS NOT NULL
         AND (p_tha_pnlai_lich_id IS NULL OR t.THA_PNLAI_LICH_ID = p_tha_pnlai_lich_id)
    ) LOOP
      v_da := FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY_MA_TG(r.pn_id, p_ngay_xet);
      v_con := FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY_MA_TG(r.pn_id, p_ngay_xet);
      -- THA_AN_PHAT trong PN_THI_HANH_AN chính là MTG_TITLE (gi?ng quy ??c migrate),
      -- nên có th? tính THA_MUC_AN_ID tr?c ti?p t? THA_AN_PHAT.
      v_muc_an_id := FN_GET_MUC_AN_ID_TU_AN_PHAT(r.tha_an_phat);
      UPDATE QLPN.PN_THI_HANH_AN t
         SET t.THA_THOI_GIAN_DA_CHAP_HANH = v_da,
             t.THA_MUC_AN_ID            = v_muc_an_id,

             t.THA_THOI_GIAN_CON_LAI      = v_con,
             t.LAST_MODIFICATION_TIME     = SYSTIMESTAMP
       WHERE t.ROWID = r.rid;
    END LOOP;
  END SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI;

END PKG_TINH_AN;

/
--------------------------------------------------------
--  DDL for Function CONVERT_DURATION_TO_DAYS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."CONVERT_DURATION_TO_DAYS" (p_duration IN VARCHAR2)
RETURN NUMBER
IS
    v_days NUMBER := 0;
    v_text VARCHAR2(200);
    v_nam NUMBER;
    v_thang NUMBER;
    v_ngay NUMBER;
BEGIN
    IF p_duration IS NULL OR TRIM(p_duration) IS NULL THEN
        RETURN 0;
    END IF;

    v_text := LOWER(p_duration);

    -- Extract "X nam" or "X n?m"
    v_nam := REGEXP_SUBSTR(v_text, '(\d+)\s*n[?a]m', 1, 1, NULL, 1);
    IF v_nam IS NOT NULL THEN
        v_days := v_days + TO_NUMBER(v_nam) * 365;
    END IF;

    -- Extract "X thang" or "X tháng"
    v_thang := REGEXP_SUBSTR(v_text, '(\d+)\s*th[?a]ng', 1, 1, NULL, 1);
    IF v_thang IS NOT NULL THEN
        v_days := v_days + TO_NUMBER(v_thang) * 30;
    END IF;

    -- Extract "X ngay" or "X ngày"
    v_ngay := REGEXP_SUBSTR(v_text, '(\d+)\s*ng[àa]y', 1, 1, NULL, 1);
    IF v_ngay IS NOT NULL THEN
        v_days := v_days + TO_NUMBER(v_ngay);
    END IF;

    RETURN v_days;
END;

/
--------------------------------------------------------
--  DDL for Function CONVERT_NGAY_TO_NAM_THANG_NGAY
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."CONVERT_NGAY_TO_NAM_THANG_NGAY" (p_days IN NUMBER)
RETURN VARCHAR2
IS
    v_nam NUMBER;
    v_thang NUMBER;
    v_ngay NUMBER;
    v_result VARCHAR2(100);
BEGIN
    IF p_days IS NULL OR p_days <= 0 THEN
        RETURN '0 ngày';
    END IF;

    v_nam := TRUNC(p_days / 365);
    v_thang := TRUNC(MOD(p_days, 365) / 30);
    v_ngay := MOD(p_days, 30);

    v_result := '';
    IF v_nam > 0 THEN
        v_result := v_result || v_nam || ' n?m ';
    END IF;
    IF v_thang > 0 THEN
        v_result := v_result || v_thang || ' tháng ';
    END IF;
    IF v_ngay > 0 OR (v_nam = 0 AND v_thang = 0) THEN
        v_result := v_result || v_ngay || ' ngày';
    END IF;

    RETURN TRIM(v_result);
END;


/
--------------------------------------------------------
--  DDL for Function FN_AN_PHAT_TO_NAM
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_AN_PHAT_TO_NAM" (
    p_an_phat VARCHAR2
)
RETURN NUMBER IS
    v_nam   NUMBER := 0;
    v_thang NUMBER := 0;
    v_ngay  NUMBER := 0;
BEGIN
    -- Tù chung thân
    IF p_an_phat IS NULL
       OR p_an_phat LIKE '%Tù chung thân%' THEN
        RETURN NULL;
    END IF;

    -- L?y s? n?m
    v_nam := NVL(
        REGEXP_SUBSTR(p_an_phat, '([0-9]+)\s*n?m', 1, 1, NULL, 1),
        0
    );

    -- L?y s? tháng
    v_thang := NVL(
        REGEXP_SUBSTR(p_an_phat, '([0-9]+)\s*tháng', 1, 1, NULL, 1),
        0
    );

    -- L?y s? ngày
    v_ngay := NVL(
        REGEXP_SUBSTR(p_an_phat, '([0-9]+)\s*ngày', 1, 1, NULL, 1),
        0
    );

    RETURN v_nam
         + v_thang / 12
         + v_ngay  / 365;
END fn_an_phat_to_nam;


/
--------------------------------------------------------
--  DDL for Function FN_CALC_TONG_AN_GIAM
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_CALC_TONG_AN_GIAM" (
    p_tam_giam_text IN NVARCHAR2,
    p_tam_giu_text IN NVARCHAR2,
    p_o_truoc_text IN NVARCHAR2
) RETURN NVARCHAR2
IS
    v_nam_tam_giam NUMBER := 0;
    v_thang_tam_giam NUMBER := 0;
    v_ngay_tam_giam NUMBER := 0;

    v_nam_tam_giu NUMBER := 0;
    v_thang_tam_giu NUMBER := 0;
    v_ngay_tam_giu NUMBER := 0;

    v_nam_o_truoc NUMBER := 0;
    v_thang_o_truoc NUMBER := 0;
    v_ngay_o_truoc NUMBER := 0;

    v_tong_nam NUMBER := 0;
    v_tong_thang NUMBER := 0;
    v_tong_ngay NUMBER := 0;

    v_result NVARCHAR2(500);
BEGIN
    -- Parse t?m giam
    IF p_tam_giam_text IS NOT NULL THEN
        v_nam_tam_giam := NVL(FN_PARSE_THOI_GIAN_TEXT(p_tam_giam_text, 'NAM'), 0);
        v_thang_tam_giam := NVL(FN_PARSE_THOI_GIAN_TEXT(p_tam_giam_text, 'THANG'), 0);
        v_ngay_tam_giam := NVL(FN_PARSE_THOI_GIAN_TEXT(p_tam_giam_text, 'NGAY'), 0);
    END IF;

    -- Parse t?m gi? (tính 1:1, không quy ??i)
    IF p_tam_giu_text IS NOT NULL THEN
        v_nam_tam_giu := NVL(FN_PARSE_THOI_GIAN_TEXT(p_tam_giu_text, 'NAM'), 0);
        v_thang_tam_giu := NVL(FN_PARSE_THOI_GIAN_TEXT(p_tam_giu_text, 'THANG'), 0);
        v_ngay_tam_giu := NVL(FN_PARSE_THOI_GIAN_TEXT(p_tam_giu_text, 'NGAY'), 0);
    END IF;

    -- Parse ? tr??c
    IF p_o_truoc_text IS NOT NULL THEN
        v_nam_o_truoc := NVL(FN_PARSE_THOI_GIAN_TEXT(p_o_truoc_text, 'NAM'), 0);
        v_thang_o_truoc := NVL(FN_PARSE_THOI_GIAN_TEXT(p_o_truoc_text, 'THANG'), 0);
        v_ngay_o_truoc := NVL(FN_PARSE_THOI_GIAN_TEXT(p_o_truoc_text, 'NGAY'), 0);
    END IF;

    -- C?ng t?ng (t?m giam + t?m gi? + ? tr??c, ??u 1:1)
    v_tong_ngay := v_ngay_tam_giam + v_ngay_tam_giu + v_ngay_o_truoc;
    v_tong_thang := v_thang_tam_giam + v_thang_tam_giu + v_thang_o_truoc;
    v_tong_nam := v_nam_tam_giam + v_nam_tam_giu + v_nam_o_truoc;

    -- Quy ??i ngày -> tháng
    IF v_tong_ngay >= 30 THEN
        v_tong_thang := v_tong_thang + FLOOR(v_tong_ngay / 30);
        v_tong_ngay := MOD(v_tong_ngay, 30);
    END IF;

    -- Quy ??i tháng -> n?m
    IF v_tong_thang >= 12 THEN
        v_tong_nam := v_tong_nam + FLOOR(v_tong_thang / 12);
        v_tong_thang := MOD(v_tong_thang, 12);
    END IF;

    -- Format k?t qu?
    v_result := '';
    IF v_tong_nam > 0 THEN
        v_result := v_result || v_tong_nam || ' n?m ';
    END IF;
    IF v_tong_thang > 0 THEN
        v_result := v_result || v_tong_thang || ' tháng ';
    END IF;
    IF v_tong_ngay > 0 THEN
        v_result := v_result || v_tong_ngay || ' ngày';
    END IF;

    -- Trim kho?ng tr?ng th?a
    v_result := TRIM(v_result);

    -- N?u t?t c? ??u = 0
    IF v_result IS NULL OR v_result = '' THEN
        v_result := '0 ngày';
    END IF;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN NULL;
END;


/
--------------------------------------------------------
--  DDL for Function FN_DIEU_KIEN_THOI_GIAN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_DIEU_KIEN_THOI_GIAN" (
    p_pham_nhan_id IN NUMBER,
    p_ngay_xet     IN DATE,
    p_is_dac_biet  IN NUMBER
) RETURN NVARCHAR2 
IS
    v_so_lan_giam          NUMBER := 0;
    v_ngay_xet_gan_nhat    DATE;
    v_con_lai_gan_nhat     NVARCHAR2(500);
    v_con_lai_ngay         NUMBER := 0; 
    v_khoang_cach_thang    NUMBER := 0;
    v_so_lan_giam_trong_nam NUMBER := 0;
    v_nam_xet              NUMBER;
    v_ngay_day_dot         DATE;

    C_LAN_DAU_TT CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - Xét l?n ??u - Thông th??ng');
    C_LAN_DAU_DB CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - Xét l?n ??u - ??c bi?t');
    C_DUNG_DOT   CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - ?ã gi?m án - ?úng ??t');
    C_DAY_DOT    CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - ?ã gi?m án - ???c ??y ??t');
    C_KHONG_DU   CONSTANT NVARCHAR2(100) := TO_NCHAR('Không ?? ?K v? th?i gian');

    -- Các hàm n?i b? (gi? nguyên logic, thêm DETERMINISTIC ?? Oracle cache t?t h?n)
    FUNCTION GET_DOT(p_ngay IN DATE) RETURN NUMBER DETERMINISTIC IS
        v_thang NUMBER;
        v_ngay_in NUMBER;
    BEGIN
        v_thang   := EXTRACT(MONTH FROM p_ngay);
        v_ngay_in := EXTRACT(DAY   FROM p_ngay);
        IF v_thang < 4 OR (v_thang = 4 AND v_ngay_in < 30) THEN RETURN 1;
        ELSIF v_thang < 9 OR (v_thang = 9 AND v_ngay_in < 2) THEN RETURN 2;
        ELSE RETURN 3;
        END IF;
    END GET_DOT;

    FUNCTION GET_NGAY_DOT(p_nam IN NUMBER, p_dot IN NUMBER) RETURN DATE DETERMINISTIC IS
    BEGIN
        CASE p_dot
            WHEN 1 THEN RETURN TO_DATE('01/01/' || p_nam, 'DD/MM/YYYY');
            WHEN 2 THEN RETURN TO_DATE('30/04/' || p_nam, 'DD/MM/YYYY');
            WHEN 3 THEN RETURN TO_DATE('02/09/' || p_nam, 'DD/MM/YYYY');
            ELSE RETURN NULL;
        END CASE;
    END GET_NGAY_DOT;

    FUNCTION GET_NGAY_DAY_DOT(p_ngay_giam IN DATE) RETURN DATE DETERMINISTIC IS
        v_dot NUMBER;
        v_nam NUMBER;
    BEGIN
        v_dot := GET_DOT(p_ngay_giam);
        v_nam := EXTRACT(YEAR FROM p_ngay_giam);
        CASE v_dot
            WHEN 1 THEN RETURN GET_NGAY_DOT(v_nam, 3);
            WHEN 2 THEN RETURN GET_NGAY_DOT(v_nam + 1, 1);
            WHEN 3 THEN RETURN GET_NGAY_DOT(v_nam + 1, 2);
            ELSE RETURN NULL;
        END CASE;
    END GET_NGAY_DAY_DOT;

BEGIN
    v_nam_xet := EXTRACT(YEAR FROM p_ngay_xet);

    -- L?y s? l?n gi?m + thông tin gi?m g?n nh?t (ch? 1 query)
    SELECT COUNT(*),
           MAX(CASE WHEN RN = 1 THEN NGAY_XET END),
           MAX(CASE WHEN RN = 1 THEN CON_LAI END)
      INTO v_so_lan_giam, v_ngay_xet_gan_nhat, v_con_lai_gan_nhat
    FROM (
        SELECT NGAY_XET, CON_LAI,
               ROW_NUMBER() OVER (ORDER BY NGAY_XET DESC) AS RN
        FROM GIAM_THOI_HANS
        WHERE PHAM_NHAN_ID = p_pham_nhan_id
          AND IS_DELETED = 0
    );

    IF v_so_lan_giam = 0 THEN
        RETURN CASE WHEN p_is_dac_biet = 1 THEN C_LAN_DAU_DB ELSE C_LAN_DAU_TT END;
    END IF;

    v_khoang_cach_thang := MONTHS_BETWEEN(p_ngay_xet, v_ngay_xet_gan_nhat);

    IF v_khoang_cach_thang >= 12 THEN
        RETURN C_DUNG_DOT;
    END IF;

    -- Tr??ng h?p ??c bi?t: t?i ?a 2 l?n gi?m trong n?m
    IF p_is_dac_biet = 1 THEN
        SELECT COUNT(*) 
          INTO v_so_lan_giam_trong_nam
        FROM GIAM_THOI_HANS
        WHERE PHAM_NHAN_ID = p_pham_nhan_id
          AND EXTRACT(YEAR FROM NGAY_XET) = v_nam_xet
          AND IS_DELETED = 0;

        RETURN CASE WHEN v_so_lan_giam_trong_nam < 2 
                    THEN C_DAY_DOT 
                    ELSE C_KHONG_DU END;
    END IF;

    -- ==================== Tính th?i gian còn l?i (ch? ch?y khi c?n) ====================
    -- Ph?n tính th?i gian còn l?i (?ã s?a l?i)
    BEGIN
        SELECT NVL(cl.ymd.nam,  0) * 365 
             + NVL(cl.ymd.thang, 0) * 30 
             + NVL(cl.ymd.ngay,  0)
          INTO v_con_lai_ngay
        FROM (
            SELECT 
                (SELECT THA_AN_PHAT 
                   FROM PN_THI_HANH_AN 
                  WHERE THA_PNLAI_LICH_ID = p_pham_nhan_id 
                    AND NVL(IS_DELETED,0) = 0 
                    AND ROWNUM = 1) AS an_phat,

                FN_TINH_TONG_AN_GIAM(p_pham_nhan_id)      AS tong_giam,

                FN_GET_DA_CHAP_HANH_THEO_NGAY(p_pham_nhan_id, p_ngay_xet) AS da_chap_hanh
            FROM DUAL
        ) src,
        LATERAL (
            SELECT FN_TINH_CON_LAI(src.an_phat, src.tong_giam, src.da_chap_hanh) AS ymd
              FROM DUAL
        ) cl;

    EXCEPTION
        WHEN OTHERS THEN 
            v_con_lai_ngay := 0;
    END;
    -- Ki?m tra ?i?u ki?n "??y ??t" khi còn l?i d??i 1 n?m
    IF v_con_lai_ngay > 0 AND v_con_lai_ngay < 365 THEN
        v_ngay_day_dot := GET_NGAY_DAY_DOT(v_ngay_xet_gan_nhat);

        IF v_ngay_day_dot IS NOT NULL 
           AND ABS(p_ngay_xet - v_ngay_day_dot) <= 15 THEN
            RETURN C_DAY_DOT;
        END IF;
    END IF;

    RETURN C_KHONG_DU;

EXCEPTION
    WHEN OTHERS THEN 
        RETURN C_KHONG_DU;
END FN_DIEU_KIEN_THOI_GIAN;

/
--------------------------------------------------------
--  DDL for Function FN_DIEU_KIEN_THOI_GIAN_PHI_TEST
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_DIEU_KIEN_THOI_GIAN_PHI_TEST" (
    p_pham_nhan_id IN NUMBER,
    p_ngay_xet     IN DATE,
    p_is_dac_biet  IN NUMBER
) RETURN NVARCHAR2
IS
    v_so_lan_giam          NUMBER := 0;
