    v_con_lai_ngay         NUMBER := 0;
    v_khoang_cach_thang    NUMBER := 0;
    v_so_lan_giam_trong_nam NUMBER := 0;
    v_nam_xet              NUMBER;
    v_ngay_day_dot         DATE;

    C_LAN_DAU_TT CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - Xét l?n ??u - Thông th??ng');
    C_LAN_DAU_DB CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - Xét l?n ??u - ??c bi?t');
    C_DUNG_DOT   CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - ?ã gi?m án - ?úng ??t');
    C_DAY_DOT    CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - ?ã gi?m án - ???c ??y ??t');
    C_KHONG_DU   CONSTANT NVARCHAR2(100) := TO_NCHAR('Không ?? ?K v? th?i gian');

    -- Các hàm n?i b? (gi? nguyên logic, thêm DETERMINISTIC ?? Oracle cache t?t h?n)
    FUNCTION GET_DOT(p_ngay IN DATE) RETURN NUMBER DETERMINISTIC IS
        v_thang NUMBER;
        v_ngay_in NUMBER;
    BEGIN
        v_thang   := EXTRACT(MONTH FROM p_ngay);
        v_ngay_in := EXTRACT(DAY   FROM p_ngay);
        IF v_thang < 4 OR (v_thang = 4 AND v_ngay_in < 30) THEN RETURN 1;
        ELSIF v_thang < 9 OR (v_thang = 9 AND v_ngay_in < 2) THEN RETURN 2;
        ELSE RETURN 3;
        END IF;
    END GET_DOT;

    FUNCTION GET_NGAY_DOT(p_nam IN NUMBER, p_dot IN NUMBER) RETURN DATE DETERMINISTIC IS
    BEGIN
        CASE p_dot
            WHEN 1 THEN RETURN TO_DATE('01/01/' || p_nam, 'DD/MM/YYYY');
            WHEN 2 THEN RETURN TO_DATE('30/04/' || p_nam, 'DD/MM/YYYY');
            WHEN 3 THEN RETURN TO_DATE('02/09/' || p_nam, 'DD/MM/YYYY');
            ELSE RETURN NULL;
        END CASE;
    END GET_NGAY_DOT;

    FUNCTION GET_NGAY_DAY_DOT(p_ngay_giam IN DATE) RETURN DATE DETERMINISTIC IS
        v_dot NUMBER;
        v_nam NUMBER;
    BEGIN
        v_dot := GET_DOT(p_ngay_giam);
        v_nam := EXTRACT(YEAR FROM p_ngay_giam);
        CASE v_dot
            WHEN 1 THEN RETURN GET_NGAY_DOT(v_nam, 3);
            WHEN 2 THEN RETURN GET_NGAY_DOT(v_nam + 1, 1);
            WHEN 3 THEN RETURN GET_NGAY_DOT(v_nam + 1, 2);
            ELSE RETURN NULL;
        END CASE;
    END GET_NGAY_DAY_DOT;

BEGIN
    v_nam_xet := EXTRACT(YEAR FROM p_ngay_xet);

    -- L?y s? l?n gi?m + thông tin gi?m g?n nh?t (ch? 1 query)
    SELECT COUNT(*),
           MAX(CASE WHEN RN = 1 THEN NGAY_XET END),
           MAX(CASE WHEN RN = 1 THEN CON_LAI END)
      INTO v_so_lan_giam, v_ngay_xet_gan_nhat, v_con_lai_gan_nhat
    FROM (
        SELECT NGAY_XET, CON_LAI,
               ROW_NUMBER() OVER (ORDER BY NGAY_XET DESC) AS RN
        FROM GIAM_THOI_HANS
        WHERE PHAM_NHAN_ID = p_pham_nhan_id
          AND IS_DELETED = 0
    );

    IF v_so_lan_giam = 0 THEN
        RETURN CASE WHEN p_is_dac_biet = 1 THEN C_LAN_DAU_DB ELSE C_LAN_DAU_TT END;
    END IF;

    v_khoang_cach_thang := MONTHS_BETWEEN(p_ngay_xet, v_ngay_xet_gan_nhat);

    IF v_khoang_cach_thang >= 12 THEN
        RETURN C_DUNG_DOT;
    END IF;

    -- Tr??ng h?p ??c bi?t: t?i ?a 2 l?n gi?m trong n?m
    IF p_is_dac_biet = 1 THEN
        SELECT COUNT(*) 
          INTO v_so_lan_giam_trong_nam
        FROM GIAM_THOI_HANS
        WHERE PHAM_NHAN_ID = p_pham_nhan_id
          AND EXTRACT(YEAR FROM NGAY_XET) = v_nam_xet
          AND IS_DELETED = 0;

        RETURN CASE WHEN v_so_lan_giam_trong_nam < 2 
                    THEN C_DAY_DOT 
                    ELSE C_KHONG_DU END;
    END IF;

    -- ==================== Tính th?i gian còn l?i (ch? ch?y khi c?n) ====================
    -- Ph?n tính th?i gian còn l?i (?ã s?a l?i)
    BEGIN
        SELECT NVL(cl.ymd.nam,  0) * 365 
             + NVL(cl.ymd.thang, 0) * 30 
             + NVL(cl.ymd.ngay,  0)
          INTO v_con_lai_ngay
        FROM (
            SELECT 
                (SELECT THA_AN_PHAT 
                   FROM PN_THI_HANH_AN 
                  WHERE THA_PNLAI_LICH_ID = p_pham_nhan_id 
                    AND NVL(IS_DELETED,0) = 0 
                    AND ROWNUM = 1) AS an_phat,

                FN_TINH_TONG_AN_GIAM(p_pham_nhan_id)      AS tong_giam,

                FN_GET_DA_CHAP_HANH_THEO_NGAY(p_pham_nhan_id, p_ngay_xet) AS da_chap_hanh
            FROM DUAL
        ) src,
        LATERAL (
            SELECT FN_TINH_CON_LAI(src.an_phat, src.tong_giam, src.da_chap_hanh) AS ymd
              FROM DUAL
        ) cl;

    EXCEPTION
        WHEN OTHERS THEN 
            v_con_lai_ngay := 0;
    END;
    -- Ki?m tra ?i?u ki?n "??y ??t" khi còn l?i d??i 1 n?m
    IF v_con_lai_ngay > 0 AND v_con_lai_ngay < 365 THEN
        v_ngay_day_dot := GET_NGAY_DAY_DOT(v_ngay_xet_gan_nhat);

        IF v_ngay_day_dot IS NOT NULL 
           AND ABS(p_ngay_xet - v_ngay_day_dot) <= 15 THEN
            RETURN C_DAY_DOT;
        END IF;
    END IF;

    RETURN C_KHONG_DU;

EXCEPTION
    WHEN OTHERS THEN 
        RETURN C_KHONG_DU;
END FN_DIEU_KIEN_THOI_GIAN_PHI_TEST;

