  RETURN v_result;
EXCEPTION WHEN NO_DATA_FOUND THEN RETURN u'ch\01b0a c\00f3';
END FN_GET_HO_TEN_VC;


/
--------------------------------------------------------
--  DDL for Function FN_GET_KET_QUA_CAI_TAO_STR
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_KET_QUA_CAI_TAO_STR" (
    p_PHAM_NHAN_ID IN NUMBER
)
RETURN VARCHAR2
IS
    v_result VARCHAR2(4000);
BEGIN
    SELECT LISTAGG(
               'N?m ' || k.NAM ||
               ': Q1=' || k.QUY_1 ||
               ', Q2=' || k.QUY_2 ||
               ', 6T?N=' || k.DAU_NAM ||
               ', Q3=' || k.QUY_3 ||
               ', Q4=' || k.QUY_4 ||
               ', 6TCN=' || k.CUOI_NAM ||
               ', C? n?m=' || k.CA_NAM,
               ' | '
           ) WITHIN GROUP (ORDER BY k.NAM)
    INTO v_result
    FROM TABLE(FN_GET_KET_QUA_CAI_TAO(p_PHAM_NHAN_ID)) k;

    RETURN v_result;
END;


/
--------------------------------------------------------
--  DDL for Function FN_GET_LIET_KE_HPBS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_LIET_KE_HPBS" (
    v_PHAM_NHAN_ID NUMBER
)
RETURN VARCHAR2
IS
    v_result VARCHAR2(4000);
BEGIN
    SELECT LISTAGG(dm.HPBS_TEN, ', ')
           WITHIN GROUP (ORDER BY dm.HPBS_TEN)
    INTO v_result
    FROM PN_HINH_PHAT_BO_SUNGS hp
    JOIN DM_HINH_PHAT_BO_SUNGS dm
        ON dm.ID = hp.HPBS_HINH_PHAT
       AND dm.IS_DELETED = 0
    WHERE hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
      AND hp.IS_DELETED = 0;

    RETURN NVL(v_result, '');
END;


/
--------------------------------------------------------
--  DDL for Function FN_GET_LIET_KE_HPBS_CHI_TIET
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_LIET_KE_HPBS_CHI_TIET" (
    v_PHAM_NHAN_ID NUMBER
)
RETURN VARCHAR2
IS
    v_result VARCHAR2(4000);
BEGIN
    SELECT LISTAGG(
               dm.HPBS_TEN
               || ' ' || TO_CHAR(hp.HPBS_TONG_TIEN_PHAT, 'FM999G999G999')
               || ' ??ng, '
               || CASE
                    WHEN NVL(bl.TONG_DA_NOP, 0) > 0 THEN
                        '?ã n?p '
                        || TO_CHAR(bl.TONG_DA_NOP, 'FM999G999G999')
                        || ' ??ng'
                    ELSE
                        'ch?a ?óng'
                  END,
               '; '
           )
           WITHIN GROUP (ORDER BY dm.HPBS_TEN)
    INTO v_result
    FROM PN_HINH_PHAT_BO_SUNGS hp
    JOIN DM_HINH_PHAT_BO_SUNGS dm
        ON dm.ID = hp.HPBS_HINH_PHAT
       AND dm.IS_DELETED = 0
    LEFT JOIN (
        SELECT HPBS_ID,
               SUM(BL_SO_TIEN) AS TONG_DA_NOP
        FROM PN_BIENLAIES
        WHERE IS_DELETED = 0
        GROUP BY HPBS_ID
    ) bl
        ON bl.HPBS_ID = hp.ID
    WHERE hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
      AND hp.IS_DELETED = 0;

    RETURN NVL(v_result, '');
END;


/
--------------------------------------------------------
--  DDL for Function FN_GET_LIET_KE_HPBS_TIEN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_LIET_KE_HPBS_TIEN" (
    v_PHAM_NHAN_ID NUMBER
)
RETURN VARCHAR2
IS
    v_result VARCHAR2(4000);
BEGIN
    SELECT LISTAGG(
               dm.HPBS_TEN
               || ' ' || TO_CHAR(NVL(hp.HPBS_TONG_TIEN_PHAT, 0), 'FM999G999G999')
               || ' ??ng, '
               || CASE
                    WHEN NVL(bl.TONG_DA_NOP, 0) > 0 THEN
                        '?ã n?p '
                        || TO_CHAR(bl.TONG_DA_NOP, 'FM999G999G999')
                        || ' ??ng'
                    ELSE
                        'ch?a ?óng'
                  END,
               '; '
           )
           WITHIN GROUP (ORDER BY dm.HPBS_TEN)
    INTO v_result
    FROM PN_HINH_PHAT_BO_SUNGS hp
    JOIN DM_HINH_PHAT_BO_SUNGS dm
        ON dm.ID = hp.HPBS_HINH_PHAT
       AND NVL(dm.IS_DELETED, 0) = 0
    LEFT JOIN (
        SELECT HPBS_ID,
               SUM(BL_SO_TIEN) AS TONG_DA_NOP
        FROM PN_BIENLAIES
        WHERE NVL(IS_DELETED, 0) = 0
        GROUP BY HPBS_ID
    ) bl
        ON bl.HPBS_ID = hp.ID
    WHERE hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
      AND NVL(hp.IS_DELETED, 0) = 0
      AND (
            NVL(hp.HPBS_TONG_TIEN_PHAT, 0) > 0
         OR NVL(bl.TONG_DA_NOP, 0) > 0
      );

    RETURN NVL(v_result, '');
END FN_GET_LIET_KE_HPBS_TIEN;



/
--------------------------------------------------------
--  DDL for Function FN_GET_MUC_AN_ID_GTH
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_MUC_AN_ID_GTH" (
    p_an_phat IN NVARCHAR2
)
RETURN NUMBER
IS
    v_nam        NUMBER := 0;
    v_thang      NUMBER := 0;
    v_tong_thang NUMBER := 0;
    v_text       NVARCHAR2(1000);
BEGIN
    IF p_an_phat IS NULL THEN RETURN NULL; END IF;

    v_text := UPPER(TRIM(p_an_phat));

    -- Chung thân gi?m xu?ng 30 n?m ? ID m?c án 30 n?m
    IF v_text LIKE '%CHUNG TH%N%GI%M%30%' THEN
        RETURN 6;  -- Trên 20 n?m - 30 n?m
    END IF;

    -- Chung thân gi?m xu?ng 20 n?m ? ID m?c án 20 n?m
    IF v_text LIKE '%CHUNG TH%N%GI%M%20%' THEN
        RETURN 5;  -- 15 ??n 20 n?m
    END IF;

    -- Chung thân thông th??ng
    IF v_text LIKE '%CHUNG TH%N%' THEN
        RETURN 7;
    END IF;

    -- Trích xu?t s? n?m
    BEGIN
        v_nam := TO_NUMBER(REGEXP_SUBSTR(v_text, '\d+', 1, 1));
    EXCEPTION
        WHEN OTHERS THEN v_nam := 0;
    END;

    -- Trích xu?t s? tháng (s? th? 2 n?u có t? THÁNG)
    BEGIN
        IF REGEXP_INSTR(v_text, 'TH.NG') > 0 THEN
            v_thang := NVL(TO_NUMBER(REGEXP_SUBSTR(v_text, '\d+', 1, 2)), 0);
        END IF;
    EXCEPTION
        WHEN OTHERS THEN v_thang := 0;
    END;

    v_tong_thang := (NVL(v_nam, 0) * 12) + NVL(v_thang, 0);

    -- Phân lo?i m?c án
    IF    v_tong_thang <= 36  THEN RETURN 1;  -- T? 3 n?m tr? xu?ng
    ELSIF v_tong_thang <= 60  THEN RETURN 2;  -- Trên 3 n?m - 5 n?m
    ELSIF v_tong_thang <= 120 THEN RETURN 3;  -- Trên 5 n?m - 10 n?m
    ELSIF v_tong_thang <= 180 THEN RETURN 4;  -- Trên 10 n?m - 15 n?m
    ELSIF v_tong_thang <= 240 THEN RETURN 5;  -- 15 ??n 20 n?m
    ELSIF v_tong_thang <= 360 THEN RETURN 6;  -- Trên 20 n?m - 30 n?m
    ELSE                           RETURN 7;  -- Trên 30 n?m / Chung thân
    END IF;

EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
END FN_GET_MUC_AN_ID_GTH;

/
--------------------------------------------------------
--  DDL for Function FN_GET_MUC_AN_PHAT_DAC_XA
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_MUC_AN_PHAT_DAC_XA" (
    p_tha_an_phat IN NVARCHAR2
)
RETURN NVARCHAR2
DETERMINISTIC
IS
    v_upper      NVARCHAR2(4000);
    v_nam        NUMBER;
    v_thang      NUMBER;
    v_ngay       NUMBER;
    v_so_nam     NUMBER;  -- S? n?m t??ng ???ng (n?m + tháng/12 + ngày/365)
BEGIN
    IF p_tha_an_phat IS NULL OR TRIM(p_tha_an_phat) IS NULL THEN
        RETURN NULL;
    END IF;

    v_upper := UPPER(NVL(p_tha_an_phat, ''));

    -- 1. Chung thân gi?m xu?ng tù có th?i h?n
    -- Có "chung thân" và "gi?m xu?ng" (có d?u ho?c không)
    IF (v_upper LIKE '%CHUNG THAN%' OR v_upper LIKE '%CHUNG THÂN%')
       AND (v_upper LIKE '%GIAM XUONG%' OR v_upper LIKE '%GI?M XU?NG%')
    THEN
        RETURN u'Chung th\00e2n gi\1ea3m xu\1ed1ng t\00f9 c\00f3 th\1eddi h\1ea1n';
    END IF;

    -- Chung thân thu?n (không gi?m xu?ng): không thu?c m?c án x?p lo?i c?i t?o
    IF (v_upper LIKE '%CHUNG THAN%' OR v_upper LIKE '%CHUNG THÂN%') THEN
        RETURN NULL;
    END IF;

    -- 2. Án tù có th?i h?n: parse s? n?m t? text
    v_nam  := NVL(FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'NAM'), 0);
    v_thang := NVL(FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'THANG'), 0);
    v_ngay  := NVL(FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'NGAY'), 0);

    -- Quy ??i sang s? n?m (n?m + tháng/12 + ngày/365) ?? so sánh ng??ng
    v_so_nam := v_nam + (v_thang / 12) + (v_ngay / 365);

    -- 3. Phân lo?i theo ng??ng (theo th? t? t? cao xu?ng th?p)
    IF v_so_nam > 20 AND v_so_nam <= 30 THEN
        RETURN u'\00c1n t\00f9 20 - 30 n\0103m';
    ELSIF v_so_nam > 15 AND v_so_nam <= 20 THEN
        RETURN u'\00c1n t\00f9 15 - 20 n\0103m';
    ELSIF v_so_nam > 10 AND v_so_nam <= 15 THEN
        RETURN u'\00c1n t\00f9 10 - 15 n\0103m';
    ELSIF v_so_nam > 5 AND v_so_nam <= 10 THEN
        RETURN u'\00c1n t\00f9 5 - 10 n\0103m';
    ELSIF v_so_nam > 3 AND v_so_nam <= 5 THEN
        RETURN u'\00c1n t\00f9 3 - 5 n\0103m';
    ELSIF v_so_nam <= 3 THEN
        RETURN u'\00c1n d\01b0\1edbi 3 n\0103m';
    ELSE
        -- > 30 n?m: không n?m trong danh sách, tr? v? m?c cao nh?t ?? có c?u hình
        RETURN u'\00c1n t\00f9 20 - 30 n\0103m';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN NULL;
END FN_GET_MUC_AN_PHAT_DAC_XA;


/
--------------------------------------------------------
--  DDL for Function FN_GET_NGUONG_TGCH
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_NGUONG_TGCH" (
    p_pham_nhan_id IN NUMBER,
    p_ky_giam_id   IN NUMBER,
    p_is_dac_biet  IN NUMBER,
    p_an_phat      IN NVARCHAR2
)
RETURN NVARCHAR2  -- tr? v? text ng??ng ?? dùng v?i FN_PARSE_NGUONG
IS
    v_dieu_kien_id      NUMBER;
    v_tong_ngay_an      NUMBER;
    v_da_giam           NUMBER := 0;
    v_co_pham_toi_moi   NUMBER := 0;
    v_muc_do_nt         NVARCHAR2(100);  -- m?c ?? nghiêm tr?ng

    -- C?t ng??ng t? c?u hình
    v_nguong_tt         NVARCHAR2(100);
    v_nguong_db         NVARCHAR2(100);
    v_nguong_dgptm_it   NVARCHAR2(100);  -- ?ã gi?m + ph?m t?i m?i ít NT
    v_nguong_dgptm      NVARCHAR2(100);  -- ?ã gi?m + ph?m t?i m?i NT/RNT/?BN
    v_tgch_loai         NVARCHAR2(500);
BEGIN
    -- L?y ?i?u ki?n ID
    BEGIN
        SELECT dk.ID
          INTO v_dieu_kien_id
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS dk
         WHERE dk.GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
           AND dk.IS_DELETED = 0
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN RETURN NULL;
    END;

    v_tong_ngay_an := FN_PARSE_AN_PHAT_TO_NGAY(p_an_phat);

    -- Ki?m tra ?ã t?ng gi?m
    SELECT COUNT(*) INTO v_da_giam
      FROM GIAM_THOI_HANS
     WHERE PHAM_NHAN_ID = p_pham_nhan_id
       AND IS_DELETED = 0;

    -- Ki?m tra ph?m t?i m?i
	IF v_da_giam > 0 THEN
	    BEGIN
	        SELECT COUNT(*),
	               MAX(ptm.MUC_DO_NGHIEM_TRONG)
	          INTO v_co_pham_toi_moi, v_muc_do_nt
	          FROM PHAM_TOI_MOIS ptm
	         WHERE ptm.PHAM_NHAN_ID = p_pham_nhan_id
	           AND NVL(ptm.IS_DELETED, 0) = 0;

	        -- N?u có b?n ghi nh?ng MUC_DO_NGHIEM_TRONG toàn NULL ? coi nh? không có
	        IF v_muc_do_nt IS NULL THEN
	            v_co_pham_toi_moi := 0;
	        END IF;
	    EXCEPTION
	        WHEN NO_DATA_FOUND THEN
	            v_co_pham_toi_moi := 0;
	    END;
	END IF;

    -- L?y t?t c? c?t ng??ng t? c?u hình
    BEGIN
        SELECT
            TGCH_LOAI_DOI_TUONG,
            TGCH_TRUONG_HOP_DAC_BIET,
            TGCH_DOI_TUONG_THONG_THUONG,
            TGCH_DA_GIAM_PHAM_TOI_MOI_IT_NT,
            TGCH_DA_GIAM_PHAM_TOI_MOI
          INTO
            v_tgch_loai,
            v_nguong_db,
            v_nguong_tt,
            v_nguong_dgptm_it,
            v_nguong_dgptm
          FROM GTH_THOI_GIAN_CHAP_HANHS
         WHERE GTH_DIEU_KIEN_GIAM_THOI_HAN_ID = v_dieu_kien_id
           AND IS_DELETED = 0
           AND (   (TGCH_LOAI_DOI_TUONG LIKE '%th?i h?n%' AND v_tong_ngay_an >  0)
                OR (TGCH_LOAI_DOI_TUONG LIKE '%Chung th%'  AND v_tong_ngay_an = -1))
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN RETURN NULL;
    END; 

    -- ?? Xác ??nh ng??ng áp d?ng ??????????????????????????????
    -- ?u tiên: ph?m t?i m?i > ??c bi?t > thông th??ng
    IF v_da_giam > 0 AND v_co_pham_toi_moi > 0 THEN
        IF UPPER(NVL(v_muc_do_nt, '')) LIKE '%ÍT%'
        OR UPPER(NVL(v_muc_do_nt, '')) LIKE '%IT%'
        THEN
            -- Ít nghiêm tr?ng
            RETURN NVL(v_nguong_dgptm_it, v_nguong_tt);
        ELSE
            -- Nghiêm tr?ng / R?t nghiêm tr?ng / ??c bi?t nghiêm tr?ng
            RETURN NVL(v_nguong_dgptm, v_nguong_tt);
        END IF;
    ELSIF p_is_dac_biet = 1 THEN
        RETURN v_nguong_db;
    ELSE
        RETURN v_nguong_tt;
    END IF;

EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
END FN_GET_NGUONG_TGCH;


/
--------------------------------------------------------
--  DDL for Function FN_GET_SO_DU_HPBS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_SO_DU_HPBS" (
    v_PHAM_NHAN_ID NUMBER
)
RETURN NUMBER
IS
    v_total_fine NUMBER := 0;
    v_paid       NUMBER := 0;
    v_balance    NUMBER := 0;
BEGIN
    -- T?ng ti?n ph?t
    SELECT NVL(SUM(hp.HPBS_TONG_TIEN_PHAT), 0)
    INTO v_total_fine
    FROM PN_HINH_PHAT_BO_SUNGS hp
    WHERE hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
      AND hp.IS_DELETED = 0;

    -- T?ng ti?n ?ã n?p
    SELECT NVL(SUM(bl.BL_SO_TIEN), 0)
    INTO v_paid
    FROM PN_BIENLAIES bl
    WHERE bl.IS_DELETED = 0
      AND EXISTS (
          SELECT 1
          FROM PN_HINH_PHAT_BO_SUNGS hp
          WHERE hp.ID = bl.HPBS_ID
            AND hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
            AND hp.IS_DELETED = 0
      );

    v_balance := v_total_fine - v_paid;

    RETURN CASE
               WHEN v_balance < 0 THEN 0
               ELSE v_balance
           END;
END;


/
--------------------------------------------------------
--  DDL for Function FN_GET_TEN_CON_CAI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_TEN_CON_CAI" (
    P_PHAM_NHAN_ID NUMBER
) RETURN NVARCHAR2
IS
    V_TEN_CON NVARCHAR2(4000);
BEGIN

    SELECT LISTAGG(HO_TEN_CON, ', ') WITHIN GROUP (ORDER BY HO_TEN_CON)
    INTO V_TEN_CON
    FROM THAN_NHAN_CON_CAIS
    WHERE PHAM_NHAN_ID = P_PHAM_NHAN_ID
      AND IS_DELETED = 0;

    RETURN NVL(V_TEN_CON, 'Không có');

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Không có';
END;


/
--------------------------------------------------------
--  DDL for Function FN_GET_TIEN_AN_TONG_HOP
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_TIEN_AN_TONG_HOP" (
    P_LAI_LICH_ID IN NUMBER
)
RETURN OBJ_TIEN_AN_TONG_HOP
IS
    L_OBJ OBJ_TIEN_AN_TONG_HOP;
BEGIN

    SELECT OBJ_TIEN_AN_TONG_HOP(
        COUNT(*),

        RTRIM(
            XMLAGG(
                XMLELEMENT(e, formatted_item || ', ')
                ORDER BY sort_key
            ).EXTRACT('//text()').GETCLOBVAL(),
            ', '
        )
    )
    INTO L_OBJ
    FROM (
        SELECT
            pta.ID,

            dcq.CQ_TEN,

            LISTAGG(dtd.TD_TEN, ', ')
                WITHIN GROUP (ORDER BY dtd.TD_TEN) AS TOI_DANH_GOP,

            pta.PNTA_MUC_AN_ID,
            pta.PNTA_NAM_THA,

            (
              dcq.CQ_TEN
              || ' - '
              || NVL(
                   LISTAGG(dtd.TD_TEN, ', ')
                   WITHIN GROUP (ORDER BY dtd.TD_TEN),
                   'Không rõ t?i danh'
                 )
              || ' - M?c án: ' || NVL(TO_CHAR(pta.PNTA_MUC_AN_ID),'Không rõ')
              || ' - N?m tha: ' || NVL(TO_CHAR(pta.PNTA_NAM_THA),'Không rõ')
            ) AS formatted_item,

            NVL(pta.PNTA_NAM_THA,0) || ':' || dcq.CQ_TEN AS sort_key

        FROM PN_TIEN_AN pta

        JOIN JSON_TABLE(
            pta.PNTA_TOI_DANH_ID,
            '$[*]' COLUMNS (
                TOI_DANH_ID NUMBER PATH '$'
            )
        ) jt
            ON 1 = 1

        JOIN DM_TOI_DANHS dtd
            ON jt.TOI_DANH_ID = dtd.ID

        JOIN DM_CO_QUANS dcq
            ON pta.PNTA_TOA_XU_ID = dcq.ID

        WHERE pta.PNTA_LAI_LICH_ID = P_LAI_LICH_ID
        AND pta.IS_DELETED = 0

        GROUP BY
            pta.ID,
            dcq.CQ_TEN,
            pta.PNTA_MUC_AN_ID,
            pta.PNTA_NAM_THA
    );

    RETURN L_OBJ;

EXCEPTION
    WHEN OTHERS THEN
        RETURN OBJ_TIEN_AN_TONG_HOP(0,NULL);
END;


/
--------------------------------------------------------
--  DDL for Function FN_GET_TONG_MIEN_HINH_PHAT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_TONG_MIEN_HINH_PHAT" (
    P_PHAM_NHAN_ID NUMBER
) RETURN NVARCHAR2
IS
    V_YEAR  NUMBER := 0;
    V_MONTH NUMBER := 0;
    V_DAY   NUMBER := 0;

    V_RESULT NVARCHAR2(200);
BEGIN

    SELECT 
        NVL(SUM(M.MHP_THM_YEAR),0),
        NVL(SUM(M.MHP_THM_MONTH),0),
        NVL(SUM(M.MHP_THM_DAY),0)
    INTO 
        V_YEAR,
        V_MONTH,
        V_DAY
    FROM MIEN_HINH_PHATS M
    JOIN PN_LAI_LICHS LL
        ON LL.ID = M.PN_LAI_LICH_ID
    WHERE LL.ID = P_PHAM_NHAN_ID
      AND M.IS_DELETED = 0;

    -- Quy ??i ngày -> tháng
    V_MONTH := V_MONTH + TRUNC(V_DAY / 30);
    V_DAY := MOD(V_DAY,30);

    -- Quy ??i tháng -> n?m
    V_YEAR := V_YEAR + TRUNC(V_MONTH / 12);
    V_MONTH := MOD(V_MONTH,12);

    V_RESULT := '';

    IF V_YEAR > 0 THEN
        V_RESULT := V_RESULT || V_YEAR || ' n?m ';
    END IF;

    IF V_MONTH > 0 THEN
        V_RESULT := V_RESULT || V_MONTH || ' tháng ';
    END IF;

    IF V_DAY > 0 THEN
        V_RESULT := V_RESULT || V_DAY || ' ngày';
    END IF;

    RETURN TRIM(V_RESULT);

END;


/
--------------------------------------------------------
--  DDL for Function FN_GET_TONG_SO_NGAY_TRON
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_TONG_SO_NGAY_TRON" (
    P_PHAM_NHAN_ID NUMBER
) RETURN NVARCHAR2
IS
    V_SO_NGAY NUMBER := 0;
    V_NAM NUMBER;
    V_THANG NUMBER;
    V_NGAY NUMBER;
BEGIN

    SELECT NVL(SUM(CAST(NGAY_BAT_LAI AS DATE) - CAST(NGAY_TRON AS DATE)),0)
    INTO V_SO_NGAY
    FROM TRON_TRAIS
    WHERE PHAM_NHAN_ID = P_PHAM_NHAN_ID
      AND IS_DELETED = 0
      AND NGAY_TRON IS NOT NULL
      AND NGAY_BAT_LAI IS NOT NULL;

    IF V_SO_NGAY < 30 THEN
        RETURN V_SO_NGAY || ' ngày';
    END IF;

    V_NAM := TRUNC(V_SO_NGAY / 365);
    V_THANG := TRUNC(MOD(V_SO_NGAY,365) / 30);
    V_NGAY := MOD(MOD(V_SO_NGAY,365),30);

    IF V_NAM = 0 THEN
        RETURN V_THANG || ' tháng ' || V_NGAY || ' ngày';
    ELSE
        RETURN V_NAM || ' n?m ' || V_THANG || ' tháng ' || V_NGAY || ' ngày';
    END IF;

END;


/
--------------------------------------------------------
--  DDL for Function FN_GHI_CHU_PHAM_NHAN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GHI_CHU_PHAM_NHAN" (
    p_pn_id IN NUMBER
)
RETURN NVARCHAR2
DETERMINISTIC
IS
    v_result NVARCHAR2(2000) := u'';
    v_gcr_raw VARCHAR2(4000);
    v_cnt     NUMBER;
    v_i       NUMBER;
    v_ten     NVARCHAR2(500);
BEGIN
    IF p_pn_id IS NULL THEN
        RETURN u'';
    END IF;

    SELECT REPLACE(REPLACE(REPLACE(NVL(TRIM(ll.LL_GHI_CHU_RIENG), CHR(32)), CHR(32), ''), '[', ''), ']', '')
    INTO v_gcr_raw
    FROM PN_LAI_LICHS ll
    WHERE ll.ID = p_pn_id
      AND NVL(ll.IS_DELETED, 0) = 0
      AND ll.LL_GHI_CHU_RIENG IS NOT NULL
      AND REGEXP_COUNT(REPLACE(REPLACE(REPLACE(NVL(TRIM(ll.LL_GHI_CHU_RIENG), CHR(32)), CHR(32), ''), '[', ''), ']', ''), '[0-9]+') > 0;

    v_cnt := REGEXP_COUNT(v_gcr_raw, '[0-9]+');

    FOR v_i IN 1 .. v_cnt LOOP
        BEGIN
            SELECT g.GCR_TEN
            INTO v_ten
            FROM DM_GHI_CHU_RIENGS g
            WHERE g.ID = TO_NUMBER(REGEXP_SUBSTR(v_gcr_raw, '[0-9]+', 1, v_i))
              AND NVL(g.IS_DELETED, 0) = 0;
            v_result := v_result || CASE WHEN LENGTH(v_result) > 0 THEN u', ' ELSE u'' END || v_ten;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                NULL;
        END;
    END LOOP;

    RETURN SUBSTR(NVL(v_result, u''), 1, 2000);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN u'';
    WHEN OTHERS THEN
        RETURN u'';
END FN_GHI_CHU_PHAM_NHAN;


/
--------------------------------------------------------
--  DDL for Function FN_IS_TRUONG_HOP_DAC_BIET
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_IS_TRUONG_HOP_DAC_BIET" (
    p_pham_nhan_id IN NUMBER,
    p_ky_giam_id   IN NUMBER
)
RETURN NUMBER
IS
    v_count             NUMBER := 0;
    v_count_phu_nu_con  NUMBER := 0;
    v_nam_sinh          NUMBER;
    v_gioi_tinh         NUMBER;

    -- Cache c?u hình 1 l?n
    v_dieu_kien_db      NVARCHAR2(2000);
    v_dieu_kien_clean   VARCHAR2(2000);

    -- Cache GCR t? ph?m nhân 1 l?n
    v_gcr_ids           NVARCHAR2(2000);

    -- Flags các mã ??c bi?t
    v_co_ma_9999        NUMBER := 0;
    v_co_ma_9997        NUMBER := 0;
    v_co_ma_2402        NUMBER := 0;

    -- Helper: check mã có trong chu?i không (nhanh h?n REGEXP)
    FUNCTION HAS_MA(p_str IN VARCHAR2, p_ma IN VARCHAR2) RETURN BOOLEAN IS
    BEGIN
        RETURN INSTR(',' || p_str || ',', ',' || p_ma || ',') > 0;
    END;

BEGIN
    -- ?? B??c 1: L?y c?u hình 1 l?n duy nh?t ?????????????????
    BEGIN
        SELECT REPLACE(REPLACE(REPLACE(
                   NVL(DKGTH_DIEU_KIEN_DAC_BIET, ''),
                   '[', ''), ']', ''), '"', '')
          INTO v_dieu_kien_clean
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS
         WHERE GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
           AND IS_DELETED = 0
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN RETURN 0;
    END;

    -- Không có c?u hình ? không ??c bi?t
    IF v_dieu_kien_clean IS NULL OR LENGTH(TRIM(v_dieu_kien_clean)) = 0 THEN
        RETURN 0;
    END IF;

    -- ?? B??c 2: L?y GCR IDs c?a ph?m nhân 1 l?n ?????????????
    BEGIN
        SELECT NVL(LL_GHI_CHU_RIENG, '')
          INTO v_gcr_ids
          FROM PN_LAI_LICHS
         WHERE ID = p_pham_nhan_id
           AND NVL(IS_DELETED, 0) = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN v_gcr_ids := '';
    END;

    -- ?? B??c 3: Check match GCR_MA v?i c?u hình ?????????????
    -- Dùng JOIN + INSTR thay vì CONNECT BY
    IF LENGTH(TRIM(v_gcr_ids)) > 0 THEN
        SELECT COUNT(*) INTO v_count
          FROM DM_GHI_CHU_RIENGS dm
         WHERE NVL(dm.IS_DELETED, 0) = 0
           -- GCR_ID có trong danh sách ph?m nhân
           AND INSTR(',' || REPLACE(REPLACE(v_gcr_ids, '[',''), ']','') || ',',
                     ',' || TO_CHAR(dm.ID) || ',') > 0
           -- GCR_MA có trong danh sách c?u hình
           AND INSTR(',' || v_dieu_kien_clean || ',',
                     ',' || dm.GCR_MA || ',') > 0;

        IF v_count > 0 THEN RETURN 1; END IF;
    END IF;

    -- ?? B??c 4: ?ánh d?u các mã ??c bi?t c?n check ??????????
    v_co_ma_9999 := CASE WHEN HAS_MA(v_dieu_kien_clean, '9999') THEN 1 ELSE 0 END;
    v_co_ma_9997 := CASE WHEN HAS_MA(v_dieu_kien_clean, '9997') THEN 1 ELSE 0 END;
    v_co_ma_2402 := CASE WHEN HAS_MA(v_dieu_kien_clean, '2402') THEN 1 ELSE 0 END;

    -- Không có mã nào c?n check ? tr? v? luôn
    IF v_co_ma_9999 = 0 AND v_co_ma_9997 = 0 AND v_co_ma_2402 = 0 THEN
        RETURN 0;
    END IF;

    -- ?? B??c 5: Check 9999 - D??i 18 tu?i ???????????????????
    IF v_co_ma_9999 = 1 THEN
        BEGIN
            SELECT TO_NUMBER(SUBSTR(TRIM(ll.LL_NGAY_SINH), -4))
              INTO v_nam_sinh
              FROM PN_LAI_LICHS ll
             WHERE ll.ID = p_pham_nhan_id
               AND NVL(ll.IS_DELETED, 0) = 0;

            IF (EXTRACT(YEAR FROM SYSDATE) - v_nam_sinh) < 18 THEN
                RETURN 1;
            END IF;
        EXCEPTION
            WHEN OTHERS THEN NULL;
        END;
    END IF;

    -- ?? B??c 6: Check 9997 - ?m ?au th??ng xuyên ????????????
    IF v_co_ma_9997 = 1 THEN
        BEGIN
            SELECT COUNT(*) INTO v_count
              FROM (
                  SELECT EXTRACT(YEAR FROM CAST(cbbb.NGAY_BAT_DAU AS DATE)) AS NAM
                    FROM CHUA_BENH_BAT_BUOCS cbbb
                   WHERE cbbb.PHAM_NHAN_ID = p_pham_nhan_id
                     AND NVL(cbbb.IS_DELETED, 0) = 0
                     AND cbbb.NGAY_BAT_DAU IS NOT NULL
                   GROUP BY EXTRACT(YEAR FROM CAST(cbbb.NGAY_BAT_DAU AS DATE))
                  HAVING COUNT(*) >= 2
              );

            IF v_count > 0 THEN RETURN 1; END IF;
        EXCEPTION
            WHEN OTHERS THEN NULL;
        END;
    END IF;

    -- ?? B??c 7: Check 2402 - Ph? n? có con d??i 36 tháng ????
    IF v_co_ma_2402 = 1 THEN
        BEGIN
            SELECT ll.LL_DM_GIOI_TINH_ID
              INTO v_gioi_tinh
              FROM PN_LAI_LICHS ll
             WHERE ll.ID = p_pham_nhan_id
               AND NVL(ll.IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_gioi_tinh := NULL;
        END;

        IF v_gioi_tinh = 23 THEN
            SELECT COUNT(*) INTO v_count_phu_nu_con
              FROM THAN_NHAN_CON_CAIS tncc
             WHERE tncc.PHAM_NHAN_ID = p_pham_nhan_id
               AND NVL(tncc.IS_DELETED, 0) = 0
               AND tncc.NGAY_SINH IS NOT NULL
               AND LENGTH(TRIM(tncc.NGAY_SINH)) >= 4
               AND (EXTRACT(YEAR FROM SYSDATE)
                    - TO_NUMBER(SUBSTR(TRIM(tncc.NGAY_SINH), -4))) * 12 <= 36;

            IF v_count_phu_nu_con > 0 THEN RETURN 1; END IF;
        END IF;
    END IF;

    RETURN 0;

EXCEPTION
    WHEN OTHERS THEN RETURN 0;
END FN_IS_TRUONG_HOP_DAC_BIET;






