/
--------------------------------------------------------
--  DDL for Package Body PKG_TINH_AN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "QLPN"."PKG_TINH_AN" AS

  TYPE t_tinh_an_core_rec IS RECORD (
    ngay_bat     DATE,
    tg_da        NUMBER,
    tg_con       NUMBER,
    ngay_xet_tl  DATE
  );

  -- Helper: chuy?n kho?ng (d1, d2) thành n?m, tháng, ngày (??t tr??c FN_TINH_TONG_THOI_GIAN_GIAM)
  -- ?ã rà soát khi ??i SP_TINH_NGAY_HET_AN_GENERAL.ADD_DURATION_LEGAL sang l?ch th?t (m??n
  -- ngày dùng s? ngày th?t c?a tháng, không còn c? ??nh 30): diff_ymd ? ?ây v?n ?ã dùng
  -- MONTHS_BETWEEN/ADD_MONTHS (l?ch th?t thu?n túy) t? tr??c, c?ng nh? m?i n?i trong file này
  -- dùng ADD_MONTHS/diff_ymd/calc_nguong_date ?? c?ng/tr? vào m?t DATE c? th? — không có ch?
  -- nào m??n c? ??nh 30 ngày/tháng lên m?t DATE th?t, nên không c?n s?a gì ? PKG_TINH_AN.sql.
  PROCEDURE diff_ymd(
    d1 IN DATE, d2 IN DATE,
    y OUT NUMBER, m OUT NUMBER, d OUT NUMBER
  ) IS
    v_months NUMBER;
    v_tmp    DATE;
  BEGIN
    IF d2 <= d1 THEN
      y := 0; m := 0; d := 0;
      RETURN;
    END IF;
    v_months := TRUNC(MONTHS_BETWEEN(d2, d1));
    y := TRUNC(v_months / 12);
    m := MOD(v_months, 12);
    v_tmp := ADD_MONTHS(d1, y * 12 + m);
    d := TRUNC(d2 - v_tmp);
    IF d < 0 THEN
      m := m - 1;
      IF m < 0 THEN y := y - 1; m := m + 12; END IF;
      v_tmp := ADD_MONTHS(d1, y * 12 + m);
      d := GREATEST(TRUNC(d2 - v_tmp), 0);
    END IF;
  END diff_ymd;

  -- C?ng d?n n?m/tháng/ngày t? chu?i THA (Không / NULL ? 0)
  PROCEDURE sum_ymd_text(
    p_text IN NVARCHAR2,
    p_nam  IN OUT NUMBER,
    p_thang IN OUT NUMBER,
    p_ngay IN OUT NUMBER
  ) IS
  BEGIN
    IF p_text IS NULL OR UPPER(QLPN.FN_NORMALIZE_VN(TO_NCHAR(p_text))) IN (u'KHONG', u'0') THEN
      RETURN;
    END IF;
    p_nam   := p_nam   + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_text, 'NAM'),   0);
    p_thang := p_thang + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_text, 'THANG'), 0);
    p_ngay  := p_ngay  + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_text, 'NGAY'),  0);
  END sum_ymd_text;

  FUNCTION FN_TONG_THANG_TU_AN_PHAT_TEXT(
    p_an_phat_text IN NVARCHAR2
  ) RETURN NUMBER IS
    v_ap_n NUMBER := 0; v_ap_t NUMBER := 0; v_ap_g NUMBER := 0;
  BEGIN
    IF p_an_phat_text IS NULL THEN
      RETURN NULL;
    END IF;
    sum_ymd_text(p_an_phat_text, v_ap_n, v_ap_t, v_ap_g);
    RETURN NULLIF(NVL(v_ap_n, 0) * 12 + NVL(v_ap_t, 0), 0);
  EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
  END FN_TONG_THANG_TU_AN_PHAT_TEXT;

  -- N?i "A n?m B tháng C ngày", b? thành ph?n = 0; c? ba = 0 ? N'0'
  FUNCTION format_nam_thang_ngay_omit_zero(p_y NUMBER, p_m NUMBER, p_d NUMBER) RETURN NVARCHAR2 IS
    v_parts NVARCHAR2(4000);
  BEGIN
    IF NVL(p_y, 0) = 0 AND NVL(p_m, 0) = 0 AND NVL(p_d, 0) = 0 THEN
      RETURN TO_NCHAR(0);
    END IF;
    v_parts := NULL;
    IF NVL(p_y, 0) > 0 THEN
      v_parts := TO_NCHAR(p_y) || u' n\0103m';
    END IF;
    IF NVL(p_m, 0) > 0 THEN
      IF v_parts IS NOT NULL THEN
        v_parts := v_parts || u' ' || TO_NCHAR(p_m) || u' th\00e1ng';
      ELSE
        v_parts := TO_NCHAR(p_m) || u' th\00e1ng';
      END IF;
    END IF;
    IF NVL(p_d, 0) > 0 THEN
      IF v_parts IS NOT NULL THEN
        v_parts := v_parts || u' ' || TO_NCHAR(p_d) || u' ng\00e0y';
      ELSE
        v_parts := TO_NCHAR(p_d) || u' ng\00e0y';
      END IF;
    END IF;
    RETURN v_parts;
  END format_nam_thang_ngay_omit_zero;

  FUNCTION tinh_tong_thoi_gian_giam_core(
    p_id_pham_nhan IN NUMBER,
    p_den_ngay     IN DATE DEFAULT NULL,
    p_empty_text   IN NVARCHAR2 DEFAULT u'0'
  ) RETURN NVARCHAR2 IS
    v_y        NUMBER := 0;
    v_m        NUMBER := 0;
    v_d        NUMBER := 0;
    v_row_y    NUMBER := 0;
    v_row_m    NUMBER := 0;
    v_row_d    NUMBER := 0;
    v_n1       NUMBER := 0;
    v_n2       NUMBER := 0;
    v_n3       NUMBER := 0;
    v_parts    NVARCHAR2(4000);
    v_sep      NVARCHAR2(10) := '; ';
    v_mtg_ma   NUMBER;
    v_tg_txt   NVARCHAR2(500);
  BEGIN
    IF p_id_pham_nhan IS NULL THEN
      RETURN p_empty_text;
    END IF;

    FOR rec IN (
      SELECT dm.MTG_MA,
             dm.MTG_TITLE,
             NVL(dm.MTG_NAM, 0)   AS mtg_nam,
             NVL(dm.MTG_THANG, 0) AS mtg_thang,
             NVL(dm.MTG_NGAY, 0)  AS mtg_ngay
        FROM QLPN.GIAM_THOI_HANS gth
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dm
               ON dm.ID = gth.MUC_GIAM_ID
              AND NVL(dm.IS_DELETED, 0) = 0
       WHERE NVL(gth.IS_DELETED, 0) = 0
         AND gth.PHAM_NHAN_ID = p_id_pham_nhan
         AND gth.MUC_GIAM_ID IS NOT NULL
         AND (p_den_ngay IS NULL OR gth.NGAY_QUYET_DINH < p_den_ngay)
       ORDER BY gth.NGAY_QUYET_DINH NULLS LAST, gth.ID
    ) LOOP
      v_row_y := 0;
      v_row_m := 0;
      v_row_d := 0;
      v_mtg_ma := NVL(TO_NUMBER(rec.MTG_MA), 0);

      IF v_mtg_ma > 900000 THEN
        IF rec.MTG_TITLE IS NOT NULL AND TRIM(rec.MTG_TITLE) IS NOT NULL THEN
          v_parts := v_parts || v_sep || TRIM(rec.MTG_TITLE);
        END IF;
      ELSE
        -- ?u tiên c?t s? ?ã chu?n hóa; ch? parse text khi danh m?c ch?a có MTG_NAM/THANG/NGAY.
        IF NVL(rec.mtg_nam, 0) + NVL(rec.mtg_thang, 0) + NVL(rec.mtg_ngay, 0) > 0 THEN
          v_row_y := NVL(rec.mtg_nam, 0);
          v_row_m := NVL(rec.mtg_thang, 0);
          v_row_d := NVL(rec.mtg_ngay, 0);
        ELSIF rec.MTG_TITLE IS NOT NULL AND REGEXP_LIKE(rec.MTG_TITLE, 'n?m|tháng|ngày', 'i') THEN
          v_row_y := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NAM'), 0);
          v_row_m := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'THANG'), 0);
          v_row_d := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NGAY'), 0);
        ELSIF rec.MTG_TITLE IS NOT NULL AND TRIM(rec.MTG_TITLE) IS NOT NULL THEN
          v_n1 := NVL(TO_NUMBER(REGEXP_SUBSTR(TRIM(rec.MTG_TITLE), '[0-9]+', 1, 1)), 0);
          v_n2 := NVL(TO_NUMBER(REGEXP_SUBSTR(TRIM(rec.MTG_TITLE), '[0-9]+', 1, 2)), 0);
          v_n3 := NVL(TO_NUMBER(REGEXP_SUBSTR(TRIM(rec.MTG_TITLE), '[0-9]+', 1, 3)), 0);
          v_row_y := v_n1;
          v_row_m := v_n2;
          v_row_d := v_n3;
        END IF;

        v_y := v_y + NVL(v_row_y, 0);
        v_m := v_m + NVL(v_row_m, 0);
        v_d := v_d + NVL(v_row_d, 0);
      END IF;
    END LOOP;

    IF v_d >= 30 THEN
      v_m := v_m + TRUNC(v_d / 30);
      v_d := MOD(v_d, 30);
    END IF;
    IF v_m >= 12 THEN
      v_y := v_y + TRUNC(v_m / 12);
      v_m := MOD(v_m, 12);
    END IF;

    IF v_parts IS NOT NULL THEN
      v_parts := LTRIM(v_parts, v_sep);
    END IF;

    IF NVL(v_y, 0) = 0 AND NVL(v_m, 0) = 0 AND NVL(v_d, 0) = 0 THEN
      RETURN CASE WHEN v_parts IS NOT NULL THEN v_parts ELSE p_empty_text END;
    END IF;

    IF v_y >= 1 THEN
      v_tg_txt := format_nam_thang_ngay_omit_zero(v_y, v_m, v_d);
    ELSIF v_m >= 1 THEN
      IF NVL(v_d, 0) > 0 THEN
        v_tg_txt := TO_NCHAR(v_m) || u' Th\00e1ng ' || TO_NCHAR(v_d) || u' ng\00e0y';
      ELSE
        v_tg_txt := TO_NCHAR(v_m) || u' Th\00e1ng';
      END IF;
    ELSE
      v_tg_txt := TO_NCHAR(NVL(v_d, 0)) || u' ng\00e0y';
    END IF;

    IF v_parts IS NOT NULL THEN
      RETURN v_parts || v_sep || v_tg_txt;
    END IF;
    RETURN v_tg_txt;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN p_empty_text;
  END tinh_tong_thoi_gian_giam_core;

  FUNCTION FN_TINH_TONG_THOI_GIAN_GIAM(
    p_id_pham_nhan IN NUMBER
  ) RETURN NVARCHAR2 IS
  BEGIN
    RETURN tinh_tong_thoi_gian_giam_core(p_id_pham_nhan, NULL, u'0');
  EXCEPTION
    WHEN OTHERS THEN RETURN u'0';
  END FN_TINH_TONG_THOI_GIAN_GIAM;

  FUNCTION tinh_so_lan_giam_an_core(
    p_id       IN NUMBER,
    p_den_ngay IN DATE DEFAULT NULL
  ) RETURN NUMBER IS
    v_count NUMBER := 0;
  BEGIN
    IF p_id IS NULL THEN RETURN 0; END IF;
    SELECT COUNT(*)
      INTO v_count
      FROM QLPN.GIAM_THOI_HANS gth
      LEFT JOIN QLPN.DM_MA_THOI_GIANS dm ON dm.ID = gth.MUC_GIAM_ID AND NVL(dm.IS_DELETED, 0) = 0
     WHERE NVL(gth.IS_DELETED, 0) = 0
       AND gth.PHAM_NHAN_ID = p_id
       AND gth.MUC_GIAM_ID IS NOT NULL
       AND NVL(dm.MTG_MA, '000000') <> '000000'
       AND (p_den_ngay IS NULL OR gth.NGAY_QUYET_DINH < p_den_ngay);
    RETURN NVL(v_count, 0);
  EXCEPTION
    WHEN OTHERS THEN RETURN 0;
  END tinh_so_lan_giam_an_core;

  FUNCTION FN_TINH_SO_LAN_GIAM_AN(
    p_id_pham_nhan IN NUMBER
  ) RETURN NUMBER IS
  BEGIN
    RETURN tinh_so_lan_giam_an_core(p_id_pham_nhan);
  EXCEPTION
    WHEN OTHERS THEN RETURN 0;
  END FN_TINH_SO_LAN_GIAM_AN;

  FUNCTION FN_TINH_TONG_THOI_GIAN_GIAM_TINH_DEN_NGAY(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2 IS
  BEGIN
    RETURN tinh_tong_thoi_gian_giam_core(
      p_id_pham_nhan,
      NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE)),
      u'Kh\00f4ng'
    );
  EXCEPTION
    WHEN OTHERS THEN RETURN u'Kh\00f4ng';
  END FN_TINH_TONG_THOI_GIAN_GIAM_TINH_DEN_NGAY;

  FUNCTION FN_TINH_SO_LAN_GIAM_AN_TINH_DEN_NGAY(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NUMBER IS
  BEGIN
    RETURN tinh_so_lan_giam_an_core(p_id_pham_nhan, NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE)));
  EXCEPTION
    WHEN OTHERS THEN RETURN 0;
  END FN_TINH_SO_LAN_GIAM_AN_TINH_DEN_NGAY;

  FUNCTION FN_TINH_GIAM_AN_HIEN_THI(
    p_id_pham_nhan IN NUMBER
  ) RETURN NVARCHAR2 IS
    v_so_lan  NUMBER;
    v_tong    NVARCHAR2(200);
  BEGIN
    v_so_lan := FN_TINH_SO_LAN_GIAM_AN(p_id_pham_nhan);
    v_tong   := FN_TINH_TONG_THOI_GIAN_GIAM(p_id_pham_nhan);
    IF v_so_lan = 0 OR v_tong IS NULL OR NULLIF(TRIM(v_tong), '0') IS NULL THEN
      RETURN u'Kh\00f4ng';
    END IF;
    RETURN TO_NCHAR(v_so_lan) || u' l\1ea7n = ' || v_tong;
  EXCEPTION
    WHEN OTHERS THEN RETURN u'Kh\00f4ng';
  END FN_TINH_GIAM_AN_HIEN_THI;

  FUNCTION FN_TINH_TONG_MIEN_HINH_PHAT_HIEN_THI(
    p_id_pham_nhan IN NUMBER
  ) RETURN NVARCHAR2 IS
    v_agg    NVARCHAR2(4000);
    v_count  NUMBER := 0;
  BEGIN
    IF p_id_pham_nhan IS NULL THEN
      RETURN u'Kh\00f4ng';
    END IF;
    SELECT COUNT(*)
      INTO v_count
      FROM QLPN.MIEN_HINH_PHATS x
     WHERE x.PN_LAI_LICH_ID = p_id_pham_nhan
       AND NVL(x.IS_DELETED, 0) = 0
       AND NVL(x.MHP_THM_YEAR, 0) + NVL(x.MHP_THM_MONTH, 0) + NVL(x.MHP_THM_DAY, 0) > 0;
    IF v_count = 0 THEN
      RETURN u'Kh\00f4ng';
    END IF;

    SELECT SUBSTR(
        LISTAGG(
          TRIM(
            CASE
              WHEN NVL(x.MHP_THM_YEAR, 0) > 0
              THEN TO_NCHAR(x.MHP_THM_YEAR) || u' n\0103m '
              ELSE u''
            END
            || CASE
                 WHEN NVL(x.MHP_THM_MONTH, 0) > 0
                 THEN TO_NCHAR(x.MHP_THM_MONTH) || u' th\00e1ng '
                 ELSE u''
               END
            || CASE
                 WHEN NVL(x.MHP_THM_DAY, 0) > 0
                 THEN TO_NCHAR(x.MHP_THM_DAY) || u' ng\00e0y'
                 ELSE u''
               END
          ),
          CHR(10) ON OVERFLOW TRUNCATE u'...' WITH COUNT
        ) WITHIN GROUP (ORDER BY x.MHP_NGAY_QUYET_DINH NULLS LAST, x.ID),
        1,
        4000
      )
      INTO v_agg
      FROM QLPN.MIEN_HINH_PHATS x
     WHERE x.PN_LAI_LICH_ID = p_id_pham_nhan
       AND NVL(x.IS_DELETED, 0) = 0
       AND NVL(x.MHP_THM_YEAR, 0) + NVL(x.MHP_THM_MONTH, 0) + NVL(x.MHP_THM_DAY, 0) > 0;
    IF v_agg IS NULL OR TRIM(v_agg) IS NULL THEN
      RETURN u'Kh\00f4ng';
    END IF;
    RETURN TO_NCHAR(v_count) || u' l?n = ' || v_agg;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN u'Kh\00f4ng';
    WHEN OTHERS THEN
      RETURN u'Kh\00f4ng';
  END FN_TINH_TONG_MIEN_HINH_PHAT_HIEN_THI;

  -- C?ng d?n 1 kho?ng [p_tu, p_den] (inclusive) vào t?ng n?m/tháng/ngày qua diff_ymd — dùng b?i
  -- get_ngay_het_via_general cho các vòng l?p Tr?n/T?C+H?y án/Hoãn/Ch?a b?nh b?t bu?c.
  PROCEDURE accumulate_khoang(
    p_tu         IN     DATE,
    p_den        IN     DATE,
    p_tong_nam   IN OUT NUMBER,
    p_tong_thang IN OUT NUMBER,
    p_tong_ngay  IN OUT NUMBER
  ) IS
    v_py NUMBER; v_pm NUMBER; v_pd NUMBER;
  BEGIN
    IF p_den >= p_tu THEN
      diff_ymd(p_tu, p_den + 1, v_py, v_pm, v_pd);
      p_tong_nam := p_tong_nam + v_py;
      p_tong_thang := p_tong_thang + v_pm;
      p_tong_ngay := p_tong_ngay + v_pd;
    END IF;
  END accumulate_khoang;

  -- G?p (m??n 30 ngày = 1 tháng, 12 tháng = 1 n?m) r?i format "N nam T thang G ngay" — tr? v?
  -- NULL n?u t?ng v?n là 0/0/0 sau khi g?p, kh?p hành vi hi?n t?i n?i v_xxx_text ???c ?? nguyên
  -- giá tr? NULL tr??c vòng l?p.
  FUNCTION fold_and_format_khoang(
    p_tong_nam   IN OUT NUMBER,
    p_tong_thang IN OUT NUMBER,
    p_tong_ngay  IN OUT NUMBER
  ) RETURN NVARCHAR2 IS
    v_text NVARCHAR2(4000);
  BEGIN
    IF p_tong_ngay >= 30 THEN
      p_tong_thang := p_tong_thang + TRUNC(p_tong_ngay / 30);
      p_tong_ngay := MOD(p_tong_ngay, 30);
    END IF;
    IF p_tong_thang >= 12 THEN
      p_tong_nam := p_tong_nam + TRUNC(p_tong_thang / 12);
      p_tong_thang := MOD(p_tong_thang, 12);
    END IF;
    IF p_tong_nam > 0 OR p_tong_thang > 0 OR p_tong_ngay > 0 THEN
      v_text :=
          CASE WHEN p_tong_nam > 0 THEN p_tong_nam || ' nam ' ELSE '' END ||
          CASE WHEN p_tong_thang > 0 THEN p_tong_thang || ' thang ' ELSE '' END ||
          CASE WHEN p_tong_ngay > 0 THEN p_tong_ngay || ' ngay' ELSE '' END;
    END IF;
    RETURN v_text;
  END fold_and_format_khoang;

  -- Gom param DEMO_FINAL + g?i SP_TINH_NGAY_HET_AN_GENERAL (DUNG_PARAM=1, PN_ID null).
  -- p_blocked=1 khi tr?n/hoãn/T?C m? tr??c ngày xét; p_ngay_het NULL khi ch?n ho?c GENERAL không tính ???c.
  PROCEDURE get_ngay_het_via_general(
    p_id_pham_nhan   IN  NUMBER,
    p_ngay_xet       IN  DATE,
    p_ngay_het       OUT DATE,
    p_blocked        OUT PLS_INTEGER,
    p_ngay_het_raw   OUT DATE,
    -- ?ã ch?p hành / còn l?i THÔ (Y/M/D, tính t??i t? SP_TINH_NGAY_HET_AN_GENERAL, KHÔNG b?
    -- ghi ?è b?i THA_NGAY_HET_HAN ?ã l?u) — ?? get_core_impl tái s? d?ng thay vì t? query l?i
    -- T?C/hoãn/tr?n/h?y án và t? tính Y/M/D l?n n?a (PKG_TINH_AN_USAGE.md §6.3b).
    p_da_ch_raw_nam    OUT NUMBER,
    p_da_ch_raw_thang  OUT NUMBER,
    p_da_ch_raw_ngay   OUT NUMBER,
    p_tg_con_raw_nam   OUT NUMBER,
    p_tg_con_raw_thang OUT NUMBER,
    p_tg_con_raw_ngay  OUT NUMBER,
    -- 1 = b? qua PN_KET_THUC_RA_TRAIS và THA_NGAY_HET_HAN ?ã l?u, luôn tính t??i t? GENERAL b?ng
    -- THA_AN_PHAT_GOC — dùng khi 2 ngu?n ?ó có th? ?ã b? ghi ?è b?ng ngày tha (vd THC?K).
    p_bo_qua_da_tha  IN  PLS_INTEGER DEFAULT 0,
    -- 1 = CH? b? qua b??c "?u tiên THA_NGAY_HET_HAN ?ã l?u" (khác p_bo_qua_da_tha: KHÔNG b? qua
    -- PN_KET_THUC_RA_TRAIS — ph?m nhân ?ã ra tr?i th?t v?n ???c nh?n di?n ?úng). Dùng khi
    -- THA_NGAY_HET_HAN có th? ?ang l?ch d? li?u tính t??i (vd sau khi s?a logic GENERAL mà ch?a
    -- ch?y l?i SP_UPDATE_THA_TG_PARALLEL_ALL ?? ghi ?è c?t ?ã l?u).
    p_bo_qua_da_luu  IN  PLS_INTEGER DEFAULT 0
  ) IS
    v_cnt              NUMBER;
    v_ngay_xet_eff     DATE;
    v_nhh              DATE;
    v_tb               NVARCHAR2(4000);
    v_nb               DATE;
    v_an_n             NUMBER;
    v_an_t             NUMBER;
    v_an_g             NUMBER;
    v_da_n             NUMBER;
    v_da_t             NUMBER;
    v_da_g             NUMBER;
    v_cl_n             NUMBER;
    v_cl_t             NUMBER;
    v_cl_g             NUMBER;
    v_ktrt_ngay_tha    DATE;
    -- Ngày tha KTRT h?p l? (?ã lo?i tr? trùng THC?K, ?ã qua ki?m tra >= ngày b?t) — phát hi?n
    -- ? nhánh KTRT bên d??i nh?ng KHÔNG return s?m n?a. Dùng ??: (1) ch?t p_NGAY_YC_TINH khi
    -- g?i SP_TINH_NGAY_HET_AN_GENERAL không v??t quá ngày tha th?t, (2) t?t nhánh KTRT n?i b?
    -- c?a GENERAL (p_BO_QUA_KTRT=1) vì PKG_TINH_AN ?ã t? lo ph?n này, (3) override p_ngay_het/
    -- p_tg_con_raw_* sau l?i g?i GENERAL. NULL n?u không có KTRT h?p l? ho?c p_bo_qua_da_tha=1.
    v_ktrt_cap_ngay_tha DATE;
    -- Ngày tha THA CÓ ?I?U KI?N g?n nh?t c?a PN (n?u có) — dùng ?? nh?n di?n và KHÔNG tin
    -- KTRT_NGAY_THA/THA_NGAY_HET_HAN làm "ngày h?t án lý thuy?t" khi chúng th?c ra là ngày tha
    -- s?m do THC?K (xem 2 ?i?m dùng bên d??i).
    v_thcdk_ngay_tha   DATE;
    v_tha_ngay_bat     DATE;
    v_tha_ngay_het_han DATE;
    v_tha_an_phat_goc  NVARCHAR2(500);
    v_tha_tam_giam_db  NVARCHAR2(500);
    v_tha_tam_giu_db   NVARCHAR2(500);
    v_tha_o_truoc_db   NVARCHAR2(500);
    v_giam_an_text     NVARCHAR2(4000);
    v_tron_text        NVARCHAR2(4000);
    v_tdc_text         NVARCHAR2(4000);
    v_hoan_text        NVARCHAR2(4000);
    v_giam_hp_text     NVARCHAR2(500);
    v_mien_hp_text     NVARCHAR2(500);
    v_tang_hp_text     NVARCHAR2(500);
    v_gen_ngay_bat     DATE;
    v_gen_an_phat      NVARCHAR2(500);
    v_gen_tam_giam     NVARCHAR2(500);
    v_gen_tam_giu      NVARCHAR2(500);
    v_gen_o_truoc      NVARCHAR2(500);
    v_gen_chua_benh    NVARCHAR2(500);
  BEGIN
    p_ngay_het := NULL;
    p_blocked := 0;
    p_ngay_het_raw := NULL;
    p_da_ch_raw_nam := NULL; p_da_ch_raw_thang := NULL; p_da_ch_raw_ngay := NULL;
    p_tg_con_raw_nam := NULL; p_tg_con_raw_thang := NULL; p_tg_con_raw_ngay := NULL;

    IF p_id_pham_nhan IS NULL THEN
      RETURN;
    END IF;

    v_ngay_xet_eff := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));

    BEGIN
      SELECT t.THA_NGAY_BAT, t.THA_AN_PHAT_GOC,
             t.THA_THOI_GIAN_TAM_GIAM, t.THA_THOI_GIAN_TAM_GIU, t.THA_THOI_GIAN_O_TRUOC,
             t.THA_NGAY_HET_HAN
        INTO v_tha_ngay_bat, v_tha_an_phat_goc,
             v_tha_tam_giam_db, v_tha_tam_giu_db, v_tha_o_truoc_db,
             v_tha_ngay_het_han
        FROM QLPN.PN_THI_HANH_AN t
       WHERE t.THA_PNLAI_LICH_ID = p_id_pham_nhan
         AND NVL(t.IS_DELETED, 0) = 0
         AND t.THA_NGAY_BAT IS NOT NULL
         AND t.THA_NGAY_BAT < v_ngay_xet_eff + 1
       ORDER BY t.THA_NGAY_BAT DESC
       FETCH FIRST 1 ROW ONLY;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_tha_ngay_bat := NULL;
        v_tha_an_phat_goc := NULL;
        v_tha_tam_giam_db := NULL;
        v_tha_tam_giu_db := NULL;
        v_tha_o_truoc_db := NULL;
        v_tha_ngay_het_han := NULL;
    END;

    BEGIN
      SELECT TRUNC(tcdk.NGAY_THA)
        INTO v_thcdk_ngay_tha
        FROM QLPN.THA_CO_DIEU_KIENS tcdk
       WHERE tcdk.PHAM_NHAN_ID = p_id_pham_nhan
         AND NVL(tcdk.IS_DELETED, 0) = 0
         AND tcdk.NGAY_THA IS NOT NULL
       ORDER BY tcdk.CREATION_TIME DESC
       FETCH FIRST 1 ROW ONLY;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_thcdk_ngay_tha := NULL;
    END;

    BEGIN
      SELECT 1 INTO v_cnt
        FROM DUAL
       WHERE EXISTS (
               SELECT 1
                 FROM QLPN.TRON_TRAIS tt
                WHERE tt.PHAM_NHAN_ID = p_id_pham_nhan
                  AND NVL(tt.IS_DELETED, 0) = 0
                  AND tt.NGAY_TRON IS NOT NULL
                  AND tt.NGAY_BAT_LAI IS NULL
                  AND tt.NGAY_TRON < v_ngay_xet_eff + 1
                  AND (v_tha_ngay_bat IS NULL OR tt.NGAY_TRON >= TRUNC(v_tha_ngay_bat))
             )
          OR EXISTS (
               SELECT 1
                 FROM QLPN.HOAN_THI_HANH_ANS h
                WHERE h.PHAM_NHAN_ID = p_id_pham_nhan
                  AND NVL(h.IS_DELETED, 0) = 0
                  AND h.NGAY_HOAN IS NOT NULL
                  AND h.NGAY_THI_HANH_AN IS NULL
                  AND h.NGAY_HOAN < v_ngay_xet_eff + 1
                  AND (v_tha_ngay_bat IS NULL OR h.NGAY_HOAN >= TRUNC(v_tha_ngay_bat))
             )
          OR EXISTS (
               SELECT 1
                 FROM QLPN.TAM_DINH_CHIS td
                WHERE td.PHAM_NHAN_ID = p_id_pham_nhan
                  AND NVL(td.IS_DELETED, 0) = 0
                  AND td.TU_NGAY IS NOT NULL
                  AND td.NGAY_LAI IS NULL
                  AND NOT EXISTS (
                        SELECT 1
                          FROM QLPN.DM_TINH_TRANG_TAM_DINH_CHIES tt
                         WHERE tt.ID = td.TINH_TRANG_ID
                           AND TRIM(CAST(tt.TTTDC_TEN AS NVARCHAR2(4000))) = u'Gia h\1ea1n'
                      )
                  AND td.TU_NGAY < v_ngay_xet_eff + 1
                  AND (v_tha_ngay_bat IS NULL OR td.TU_NGAY >= TRUNC(v_tha_ngay_bat))
             );
      p_blocked := 1;
      RETURN;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        NULL;
    END;

    IF NVL(p_bo_qua_da_tha, 0) != 1 THEN
      BEGIN
        -- B? qua b?n ghi KTRT n?u ngày tha trùng v?i THA_CO_DIEU_KIENS.NGAY_THA c?a chính PN —
        -- t?c ?ây là ra tr?i do THA CÓ ?I?U KI?N (tha s?m), không ph?i h?t án th?t.
        -- DM_TRUONG_HOP_THAS không có mã riêng cho THC?K (ch? có Ra tr?i/Ch?p hành xong/Gi?m
        -- h?t th?i h?n/??c xá) nên KTRT v?n b? ghi, th??ng g?n nh?m "Ch?p hành xong hình ph?t
        -- tù" — n?u tin theo s? khi?n GENERAL coi ngày tha s?m là ngày h?t án lý thuy?t, làm
        -- sai l?ch tg_chap_hanh/tg_con_lai cho toàn b? PN ?ã qua THC?K (?ã ki?m ch?ng th?c t?
        -- qua SP_GET_THA_CDK_BAN_GIAO_PN, p_dot_tha_id=2: 20/20 PN ??u tg_chap_hanh=Không).
        SELECT k.KTRT_NGAY_THA
          INTO v_ktrt_ngay_tha
          FROM QLPN.PN_KET_THUC_RA_TRAIS k
         WHERE k.KTRT_PN_LAI_LICH_ID = p_id_pham_nhan
           AND NVL(k.IS_DELETED, 0) = 0
           AND k.KTRT_NGAY_THA IS NOT NULL
           AND (v_thcdk_ngay_tha IS NULL OR TRUNC(k.KTRT_NGAY_THA) != v_thcdk_ngay_tha)
         ORDER BY k.CREATION_TIME DESC
         FETCH FIRST 1 ROW ONLY;
        IF v_ktrt_ngay_tha IS NOT NULL THEN
          IF v_tha_ngay_bat IS NULL OR TRUNC(v_ktrt_ngay_tha) >= TRUNC(v_tha_ngay_bat) THEN
            -- KHÔNG return s?m n?a: l?u m?c r?i ?? lu?ng r?i ti?p xu?ng GENERAL (B??C 2-13) ??
            -- tính ?úng "?ã ch?p hành" tr? T?C/hoãn/tr?n per-interval — nhánh short-circuit c?
            -- ch? set p_ngay_het r?i RETURN, b? tr?ng p_ngay_het_raw/p_da_ch_raw_*/p_tg_con_raw_*
            -- (NULL do kh?i t?o ??u hàm), khi?n get_core_impl NVL(...,0) ra "?ã CH = 0" sai cho
            -- M?I PN ?ã có KTRT (?ã ki?m ch?ng: PN 40169, PN 4589). M?c th?t v?n override
            -- p_ngay_het l?n n?a sau l?i g?i GENERAL bên d??i — giá tr? cu?i cùng không ??i.
            v_ktrt_cap_ngay_tha := TRUNC(v_ktrt_ngay_tha);
          END IF;
        END IF;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          NULL;
      END;
    END IF;

    v_giam_an_text := NULL;
    v_tron_text := NULL;
    v_tdc_text := NULL;
    v_hoan_text := NULL;
    v_giam_hp_text := NULL;
    v_mien_hp_text := NULL;
    v_tang_hp_text := NULL;

    DECLARE
      v_gn NUMBER := 0;
      v_gt NUMBER := 0;
      v_gg NUMBER := 0;
    BEGIN
      FOR rec IN (
        SELECT dmtg.MTG_TITLE,
               dmtg.MTG_MA,
               NVL(dmtg.MTG_NAM, 0)   AS mtg_nam,
               NVL(dmtg.MTG_THANG, 0) AS mtg_thang,
               NVL(dmtg.MTG_NGAY, 0)  AS mtg_ngay
          FROM QLPN.GIAM_THOI_HANS gth
          JOIN QLPN.DM_MA_THOI_GIANS dmtg
            ON gth.MUC_GIAM_ID = dmtg.ID
           AND NVL(dmtg.IS_DELETED, 0) = 0
         WHERE gth.PHAM_NHAN_ID = p_id_pham_nhan
           AND NVL(gth.IS_DELETED, 0) = 0
           AND gth.MUC_GIAM_ID IS NOT NULL
           AND NVL(dmtg.MTG_MA, '000000') <> '000000'
      ) LOOP
        IF NVL(TO_NUMBER(rec.MTG_MA), 0) <= 900000 THEN
          IF NVL(rec.mtg_nam, 0) + NVL(rec.mtg_thang, 0) + NVL(rec.mtg_ngay, 0) > 0 THEN
            v_gn := v_gn + NVL(rec.mtg_nam, 0);
            v_gt := v_gt + NVL(rec.mtg_thang, 0);
            v_gg := v_gg + NVL(rec.mtg_ngay, 0);
          ELSE
            v_gn := v_gn + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NAM'), 0);
            v_gt := v_gt + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'THANG'), 0);
            v_gg := v_gg + NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NGAY'), 0);
          END IF;
        END IF;
      END LOOP;
      IF v_gn > 0 OR v_gt > 0 OR v_gg > 0 THEN
        v_giam_an_text :=
            CASE WHEN v_gn > 0 THEN v_gn || ' nam ' ELSE '' END ||
            CASE WHEN v_gt > 0 THEN v_gt || ' thang ' ELSE '' END ||
            CASE WHEN v_gg > 0 THEN v_gg || ' ngay' ELSE '' END;
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        v_giam_an_text := NULL;
    END;

    -- Tr?n: quy ??i T?NG kho?ng ?ã ?óng ra n?m/tháng/ngày (diff_ymd trên chính ngày th?t c?a
    -- kho?ng ?ó) r?i c?ng d?n — KHÔNG g?p thành 1 t?ng s? ngày r?i chia 30 (làm SP m?t ??
    -- chính xác l?ch th?t khi chuy?n ng??c l?i Y/M/D ? B??C 11b/12).
    DECLARE
      v_tong_nam   NUMBER := 0;
      v_tong_thang NUMBER := 0;
      v_tong_ngay  NUMBER := 0;
      v_tu         DATE;
      v_den        DATE;
    BEGIN
      FOR rec IN (
        SELECT CAST(tt.NGAY_TRON AS DATE) AS NGAY_TRON,
               CAST(tt.NGAY_BAT_LAI AS DATE) AS NGAY_BAT_LAI
          FROM QLPN.TRON_TRAIS tt
         WHERE tt.PHAM_NHAN_ID = p_id_pham_nhan
           AND NVL(tt.IS_DELETED, 0) = 0
           AND tt.NGAY_TRON IS NOT NULL
           AND tt.NGAY_BAT_LAI IS NOT NULL
           AND tt.NGAY_TRON < v_ngay_xet_eff + 1
           AND (v_tha_ngay_bat IS NULL OR tt.NGAY_TRON >= TRUNC(v_tha_ngay_bat))
      ) LOOP
        v_tu := GREATEST(TRUNC(rec.NGAY_TRON), TRUNC(NVL(v_tha_ngay_bat, rec.NGAY_TRON)));
        v_den := TRUNC(rec.NGAY_BAT_LAI);
        accumulate_khoang(v_tu, v_den, v_tong_nam, v_tong_thang, v_tong_ngay);
      END LOOP;
      v_tron_text := fold_and_format_khoang(v_tong_nam, v_tong_thang, v_tong_ngay);
    EXCEPTION
      WHEN OTHERS THEN
        v_tron_text := NULL;
    END;

    -- T?C + h?y án: cùng nguyên t?c quy ??i t?ng kho?ng ra n?m/tháng/ngày r?i c?ng d?n
    DECLARE
      v_tong_nam   NUMBER := 0;
      v_tong_thang NUMBER := 0;
      v_tong_ngay  NUMBER := 0;
      v_tu         DATE;
      v_den        DATE;
    BEGIN
      FOR rec IN (
        SELECT TRUNC(tdc.TU_NGAY) AS TU_NGAY, TRUNC(tdc.NGAY_LAI) AS NGAY_LAI
          FROM QLPN.TAM_DINH_CHIS tdc
         WHERE tdc.PHAM_NHAN_ID = p_id_pham_nhan
           AND NVL(tdc.IS_DELETED, 0) = 0
           AND tdc.TU_NGAY IS NOT NULL
           AND tdc.NGAY_LAI IS NOT NULL
           AND NOT EXISTS (
                 SELECT 1
                   FROM QLPN.DM_TINH_TRANG_TAM_DINH_CHIES tt
                  WHERE tt.ID = tdc.TINH_TRANG_ID
                    AND TRIM(CAST(tt.TTTDC_TEN AS NVARCHAR2(4000))) = u'Gia h\1ea1n'
               )
           AND tdc.TU_NGAY <= v_ngay_xet_eff
           AND (v_tha_ngay_bat IS NULL OR tdc.NGAY_LAI > TRUNC(v_tha_ngay_bat))
        UNION ALL
        -- H?y án ?ã ?óng (có NGAY_TRO_LAI): kho?ng ? ngoài tr? nh? T?C ? ??y lùi ngày h?t án
        SELECT TRUNC(hu.NGAY_TRA_TU_DO) AS TU_NGAY, TRUNC(hu.NGAY_TRO_LAI) AS NGAY_LAI
          FROM QLPN.HUY_ANS hu
         WHERE hu.PHAM_NHAN_ID = p_id_pham_nhan
           AND NVL(hu.IS_DELETED, 0) = 0
           AND hu.NGAY_TRA_TU_DO IS NOT NULL
           AND hu.NGAY_TRO_LAI IS NOT NULL
           AND hu.NGAY_TRA_TU_DO <= v_ngay_xet_eff
           AND (v_tha_ngay_bat IS NULL OR hu.NGAY_TRO_LAI > TRUNC(v_tha_ngay_bat))
      ) LOOP
        v_tu := GREATEST(rec.TU_NGAY, TRUNC(NVL(v_tha_ngay_bat, rec.TU_NGAY)));
        v_den := LEAST(rec.NGAY_LAI, v_ngay_xet_eff);
        accumulate_khoang(v_tu, v_den, v_tong_nam, v_tong_thang, v_tong_ngay);
      END LOOP;
      v_tdc_text := fold_and_format_khoang(v_tong_nam, v_tong_thang, v_tong_ngay);
    EXCEPTION
      WHEN OTHERS THEN
        v_tdc_text := NULL;
    END;

    -- Hoãn: cùng nguyên t?c quy ??i t?ng kho?ng ra n?m/tháng/ngày r?i c?ng d?n
    DECLARE
      v_tong_nam   NUMBER := 0;
      v_tong_thang NUMBER := 0;
      v_tong_ngay  NUMBER := 0;
      v_tu         DATE;
      v_den        DATE;
    BEGIN
      FOR rec IN (
        SELECT CAST(h.NGAY_HOAN AS DATE) AS NGAY_HOAN,
               CAST(h.NGAY_THI_HANH_AN AS DATE) AS NGAY_THA
          FROM QLPN.HOAN_THI_HANH_ANS h
         WHERE h.PHAM_NHAN_ID = p_id_pham_nhan
           AND NVL(h.IS_DELETED, 0) = 0
           AND h.NGAY_HOAN IS NOT NULL
           AND h.NGAY_THI_HANH_AN IS NOT NULL
           AND h.NGAY_HOAN < v_ngay_xet_eff + 1
           AND (v_tha_ngay_bat IS NULL OR h.NGAY_HOAN >= TRUNC(v_tha_ngay_bat))
      ) LOOP
        v_tu := GREATEST(TRUNC(rec.NGAY_HOAN), TRUNC(NVL(v_tha_ngay_bat, rec.NGAY_HOAN)));
        v_den := TRUNC(rec.NGAY_THA);
        accumulate_khoang(v_tu, v_den, v_tong_nam, v_tong_thang, v_tong_ngay);
      END LOOP;
      v_hoan_text := fold_and_format_khoang(v_tong_nam, v_tong_thang, v_tong_ngay);
    EXCEPTION
      WHEN OTHERS THEN
        v_hoan_text := NULL;
    END;

    DECLARE
      v_mn NUMBER := 0;
      v_mt NUMBER := 0;
      v_md NUMBER := 0;
    BEGIN
      SELECT NVL(SUM(NVL(m.MHP_THM_YEAR, 0)), 0),
             NVL(SUM(NVL(m.MHP_THM_MONTH, 0)), 0),
             NVL(SUM(NVL(m.MHP_THM_DAY, 0)), 0)
        INTO v_mn, v_mt, v_md
        FROM QLPN.MIEN_HINH_PHATS m
       WHERE m.PN_LAI_LICH_ID = p_id_pham_nhan
         AND NVL(m.IS_DELETED, 0) = 0
         -- Lo?i tr? c? "mi?n h?t án" ??c bi?t (9/23/0) — RULE 5 c?a SP_TINH_NGAY_HET_AN_GENERAL
         -- x? lý riêng b?n ghi này; ?? l?t vào t?ng Y/M/D th??ng s? c?ng nh?m "9 n?m 23 tháng"
         AND NOT (NVL(m.MHP_THM_YEAR,0) = 9 AND NVL(m.MHP_THM_MONTH,0) = 23 AND NVL(m.MHP_THM_DAY,0) = 0);
      IF v_mn > 0 OR v_mt > 0 OR v_md > 0 THEN
        v_mien_hp_text :=
            CASE WHEN v_mn > 0 THEN v_mn || ' nam ' ELSE '' END ||
            CASE WHEN v_mt > 0 THEN v_mt || ' thang ' ELSE '' END ||
            CASE WHEN v_md > 0 THEN v_md || ' ngay' ELSE '' END;
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        v_mien_hp_text := NULL;
    END;

    DECLARE
      v_tn  NUMBER := 0;
      v_tth NUMBER := 0;
      v_tg  NUMBER := 0;
      v_gn2 NUMBER := 0;
      v_gt2 NUMBER := 0;
      v_gg2 NUMBER := 0;
    BEGIN
      FOR rec IN (
        SELECT dmtg.MTG_TITLE,
               ltg.LTGHP_MA,
               NVL(dmtg.MTG_NAM, 0)   AS mtg_nam,
               NVL(dmtg.MTG_THANG, 0) AS mtg_thang,
               NVL(dmtg.MTG_NGAY, 0)  AS mtg_ngay
          FROM QLPN.TANG_GIAM_HINH_PHATS tghp
          JOIN QLPN.DM_LOAI_TANG_GIAM_HINH_PHATS ltg ON tghp.LOAI_TANG_GIAM_ID = ltg.ID
          JOIN QLPN.DM_MA_THOI_GIANS dmtg ON tghp.THOI_HAN_ID = dmtg.ID
         WHERE tghp.PHAM_NHAN_ID = p_id_pham_nhan
           AND NVL(tghp.IS_DELETED, 0) = 0
           AND tghp.THOI_HAN_ID IS NOT NULL
      ) LOOP
        DECLARE
          v_t_n  NUMBER := 0;
          v_t_t  NUMBER := 0;
          v_t_ng NUMBER := 0;
        BEGIN
          IF NVL(rec.mtg_nam, 0) + NVL(rec.mtg_thang, 0) + NVL(rec.mtg_ngay, 0) > 0 THEN
            v_t_n  := NVL(rec.mtg_nam, 0);
            v_t_t  := NVL(rec.mtg_thang, 0);
            v_t_ng := NVL(rec.mtg_ngay, 0);
          ELSE
            v_t_n  := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NAM'), 0);
            v_t_t  := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'THANG'), 0);
            v_t_ng := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NGAY'), 0);
          END IF;

          IF rec.LTGHP_MA = '10' THEN
            v_tn  := v_tn + v_t_n;
            v_tth := v_tth + v_t_t;
            v_tg  := v_tg + v_t_ng;
          ELSIF rec.LTGHP_MA = '20' THEN
            v_gn2 := v_gn2 + v_t_n;
            v_gt2 := v_gt2 + v_t_t;
            v_gg2 := v_gg2 + v_t_ng;
          END IF;
        END;
      END LOOP;
      IF v_tn > 0 OR v_tth > 0 OR v_tg > 0 THEN
        v_tang_hp_text :=
            CASE WHEN v_tn > 0 THEN v_tn || ' nam ' ELSE '' END ||
            CASE WHEN v_tth > 0 THEN v_tth || ' thang ' ELSE '' END ||
            CASE WHEN v_tg > 0 THEN v_tg || ' ngay' ELSE '' END;
      END IF;
      IF v_gn2 > 0 OR v_gt2 > 0 OR v_gg2 > 0 THEN
        v_giam_hp_text :=
            CASE WHEN v_gn2 > 0 THEN v_gn2 || ' nam ' ELSE '' END ||
            CASE WHEN v_gt2 > 0 THEN v_gt2 || ' thang ' ELSE '' END ||
            CASE WHEN v_gg2 > 0 THEN v_gg2 || ' ngay' ELSE '' END;
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        v_tang_hp_text := NULL;
        v_giam_hp_text := NULL;
    END;

    v_gen_ngay_bat := v_tha_ngay_bat;
    v_gen_an_phat := v_tha_an_phat_goc;
    v_gen_tam_giam := v_tha_tam_giam_db;
    v_gen_tam_giu := v_tha_tam_giu_db;
    v_gen_o_truoc := v_tha_o_truoc_db;

    -- Ch?a b?nh b?t bu?c (?óng, x?y ra TR??C ngày b?t) — c?ng vào ?ã CH nh? t?m giam/t?m gi?/? tr??c.
    -- Quy ??i T?NG kho?ng ra n?m/tháng/ngày th?t (diff_ymd trên chính ngày th?t c?a kho?ng ?ó) r?i
    -- c?ng d?n — CÙNG nguyên t?c Tr?n/T?C/Hoãn ? trên, KHÔNG g?p thành 1 t?ng s? ngày r?i ?? SP
    -- parse ng??c qua NORMALIZE_YMD (m??n 30 ngày = 1 tháng, sai l?ch v?i l?ch th?t khi tháng có
    -- 28/29/31 ngày).
    DECLARE
      v_tong_nam   NUMBER := 0;
      v_tong_thang NUMBER := 0;
      v_tong_ngay  NUMBER := 0;
      v_tu         DATE;
      v_den        DATE;
    BEGIN
      FOR rec IN (
        SELECT TRUNC(cb.NGAY_BAT_DAU) AS NGAY_BAT_DAU, TRUNC(cb.NGAY_KET_THUC) AS NGAY_KET_THUC
          FROM QLPN.CHUA_BENH_BAT_BUOCS cb
         WHERE cb.PHAM_NHAN_ID = p_id_pham_nhan
           AND NVL(cb.IS_DELETED, 0) = 0
           AND cb.NGAY_BAT_DAU IS NOT NULL
           AND cb.NGAY_KET_THUC IS NOT NULL
           AND (v_tha_ngay_bat IS NULL OR TRUNC(cb.NGAY_KET_THUC) <= TRUNC(v_tha_ngay_bat))
      ) LOOP
        v_tu := rec.NGAY_BAT_DAU;
        v_den := rec.NGAY_KET_THUC;
        accumulate_khoang(v_tu, v_den, v_tong_nam, v_tong_thang, v_tong_ngay);
      END LOOP;
      v_gen_chua_benh := fold_and_format_khoang(v_tong_nam, v_tong_thang, v_tong_ngay);
    EXCEPTION
      WHEN OTHERS THEN
        v_gen_chua_benh := NULL;
    END;

    -- Chung thân gi?m xu?ng 20/30 n?m (GIAM_THOI_HANS.MUC_GIAM_ID ?ã duy?t, MTG_MA 921000/922000):
    -- dùng MTG_TITLE làm án ph?t hi?u l?c TRONG B? NH? khi g?i GENERAL ?? tính ngày h?t án/còn l?i
    -- theo m?c 20/30 n?m xác ??nh; KHÔNG ghi ?è THA_AN_PHAT/THA_AN_PHAT_GOC nên THA_MUC_AN_ID
    -- (m?c án) không ??i.
    BEGIN
      SELECT TRIM(dm.MTG_TITLE)
        INTO v_gen_an_phat
        FROM QLPN.GIAM_THOI_HANS gth
        JOIN QLPN.DM_MA_THOI_GIANS dm
          ON dm.ID = gth.MUC_GIAM_ID
         AND NVL(dm.IS_DELETED, 0) = 0
       WHERE gth.PHAM_NHAN_ID = p_id_pham_nhan
         AND NVL(gth.IS_DELETED, 0) = 0
         AND gth.MUC_GIAM_ID IS NOT NULL
         AND dm.MTG_MA IN ('921000', '922000')
         AND (gth.NGAY_QUYET_DINH IS NULL OR gth.NGAY_QUYET_DINH < v_ngay_xet_eff + 1)
       ORDER BY gth.NGAY_QUYET_DINH DESC NULLS LAST, gth.ID DESC
       FETCH FIRST 1 ROW ONLY;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN NULL;
    END;

    IF v_gen_ngay_bat IS NULL THEN
      -- Không có THA_NGAY_BAT h?p l? nên KHÔNG th? g?i GENERAL (thi?u p_NGAY_BAT b?t bu?c) —
      -- nh?ng n?u ?ã phát hi?n KTRT h?p l? ? trên, v?n tr? v? ?úng ngày tha th?t thay vì NULL
      -- (kh?p hành vi RETURN s?m c?a code c? cho ?úng case hi?m này: có PN_KET_THUC_RA_TRAIS
      -- nh?ng không có/không kh?p PN_THI_HANH_AN.THA_NGAY_BAT nào tr??c v_ngay_xet_eff).
      IF v_ktrt_cap_ngay_tha IS NOT NULL THEN
        p_ngay_het := v_ktrt_cap_ngay_tha;
        p_ngay_het_raw := p_ngay_het;
      END IF;
      RETURN;
    END IF;

    SP_TINH_NGAY_HET_AN_GENERAL(
      p_PN_ID                   => p_id_pham_nhan,
      p_NGAY_BAT                => v_gen_ngay_bat,
      p_NGAY_YC_TINH            => TO_NUMBER(TO_CHAR(
                                      CASE WHEN v_ktrt_cap_ngay_tha IS NOT NULL
                                           THEN LEAST(v_ngay_xet_eff, v_ktrt_cap_ngay_tha)
                                           ELSE v_ngay_xet_eff
                                      END, 'YYYYMMDD')),
      p_THA_AN_PHAT_TEXT        => v_gen_an_phat,
      p_THA_TAM_GIAM_TEXT       => v_gen_tam_giam,
      p_THA_TAM_GIU_TEXT        => v_gen_tam_giu,
      p_THA_O_TRUOC_TEXT        => v_gen_o_truoc,
      p_CHUA_BENH_TEXT          => v_gen_chua_benh,
      p_THA_GIAM_HP_TEXT        => v_giam_hp_text,
      p_THA_MIEN_HP_TEXT        => v_mien_hp_text,
      p_THA_TANG_HINH_PHAT_TEXT => v_tang_hp_text,
      p_DUNG_PARAM              => 1,
      p_GIAM_AN_TEXT            => v_giam_an_text,
      p_TRON_TEXT               => v_tron_text,
      p_TDC_TEXT                => v_tdc_text,
      p_HOAN_TEXT               => v_hoan_text,
      p_NGAY_BAT_OUT            => v_nb,
      p_AN_THUC_NAM             => v_an_n,
      p_AN_THUC_THANG           => v_an_t,
      p_AN_THUC_NGAY            => v_an_g,
      p_DA_CHAP_HANH_NAM        => v_da_n,
      p_DA_CHAP_HANH_THANG      => v_da_t,
      p_DA_CHAP_HANH_NGAY       => v_da_g,
      p_NGAY_HET_HAN            => v_nhh,
      p_THOI_GIAN_CON_LAI_NAM   => v_cl_n,
      p_THOI_GIAN_CON_LAI_THANG => v_cl_t,
      p_THOI_GIAN_CON_LAI_NGAY  => v_cl_g,
      p_THONG_BAO               => v_tb,
      -- B? qua RULE 3 (Tha có ?i?u ki?n ch?a quay l?i) c?a SP_TINH_NGAY_HET_AN_GENERAL khi
      -- p_bo_qua_da_tha=1 — n?u không, RULE 3 luôn coi ngày ?ang tính (= chính ngày tha khi g?i
      -- t? FN_TINH_THOI_GIAN_THU_THACH) là "?ã tha, h?t ch?p hành", tr? v? 0 b?t k? án ph?t g?c
      -- (?ã ki?m ch?ng th?c t?: PN 12070, án 48 tháng, v?n ra "Không" dù ?ã s?a B??C 1/2 ?i?m
      -- khác — nguyên nhân là RULE 3 này, ??c l?p v?i KTRT_NGAY_THA).
      p_BO_QUA_TCDK             => p_bo_qua_da_tha,
      -- B? qua B??C 1 (short-circuit KTRT_NGAY_THA) cùng lúc v?i RULE 3 khi p_bo_qua_da_tha=1 —
      -- B??C 1 KHÔNG b? p_BO_QUA_TCDK chi ph?i (2 rule ??c l?p), nên n?u không b? qua riêng, PN
      -- có PN_KET_THUC_RA_TRAIS.KTRT_NGAY_THA l?ch THA_CO_DIEU_KIENS.NGAY_THA (vd s?a tay 1 trong
      -- 2 ngày) v?n b? tr? th?ng KTRT_NGAY_THA làm p_NGAY_HET_HAN, b? qua hoàn toàn tính toán án
      -- ph?t g?c, và không set p_THOI_GIAN_CON_LAI_* (gi? 0 m?c ??nh) — khi?n FN_TINH_THOI_GIAN_
      -- THU_THACH im l?ng tr? 0 sai.
      -- B? qua B??C 1 (short-circuit KTRT_NGAY_THA) khi p_bo_qua_da_tha=1 — cùng lý do ?ã ghi ?
      -- trên (gi? nguyên cho FN_TINH_THOI_GIAN_THU_THACH). NGOÀI RA: c?ng b? qua B??C 1 khi
      -- v_ktrt_cap_ngay_tha ?ã ???c PKG_TINH_AN t? phát hi?n + x? lý ? trên — GENERAL ch? còn
      -- vai trò "máy tính" thu?n trên Y/M/D/m?c ?ã ch?t (p_NGAY_YC_TINH ? trên), không ???c t? ý
      -- ch?y nhánh KTRT n?i b? c?a chính nó (naive, không tr? T?C/hoãn/tr?n per-interval — ?ã
      -- ki?m ch?ng PN 20508: B??C 1 t? ch?y cho ra "?ã CH"=1408 ngày SAI, ph?i ch?y ?? B??C 2-13
      -- m?i ra 1221 ngày ?ÚNG theo PKG_TINH_AN_USAGE.md §16).
      p_BO_QUA_KTRT             => CASE WHEN v_ktrt_cap_ngay_tha IS NOT NULL
                                        THEN 1 ELSE p_bo_qua_da_tha END
    );

    IF v_nhh IS NOT NULL THEN
      p_ngay_het := TRUNC(v_nhh);
    END IF;

    -- Có KTRT h?p l?: ngày tha TH?T ?áng tin h?n k?t qu? lý thuy?t v_nhh c?a GENERAL — luôn
    -- override, k? c? khi v_nhh là NULL (vd chung thân/tù hình gi?m xu?ng mà GENERAL không tr?
    -- p_NGAY_HET_HAN theo lý thuy?t, nh?ng PN ?ã ra tr?i th?t theo KTRT).
    IF v_ktrt_cap_ngay_tha IS NOT NULL THEN
      p_ngay_het := v_ktrt_cap_ngay_tha;
    END IF;

    -- Gi? giá tr? GENERAL tính t??i TR??C khi ?u tiên THA_NGAY_HET_HAN ?ã l?u — dùng cho các tính
    -- toán không ???c phép tin THA_NGAY_HET_HAN (vd "th?i gian th? thách" THC?K, n?i THA_NGAY_HET_HAN
    -- chính là giá tr? b? ghi ?è b?i ngày tha, nên ?u tiên nó s? luôn cho k?t qu? sai).
    p_ngay_het_raw := p_ngay_het;

    -- ?ã CH/còn l?i THÔ t? SP — cùng nguyên t?c "raw" nh? p_ngay_het_raw, gán TR??C khi có b?t
    -- k? override nào (SP này không có override ?ã CH/còn l?i nào c?, ch? ngày h?t m?i có).
    -- v_da_n/t/g gi? ?ÚNG k? c? khi có KTRT, vì GENERAL v?a ch?y ??y ?? B??C 2-13 (p_BO_QUA_KTRT=1
    -- t?t nhánh naive n?i b?) v?i p_NGAY_YC_TINH ?ã b? ch?t <= ngày tha th?t ? trên.
    p_da_ch_raw_nam := v_da_n; p_da_ch_raw_thang := v_da_t; p_da_ch_raw_ngay := v_da_g;
    IF v_ktrt_cap_ngay_tha IS NOT NULL AND v_ngay_xet_eff >= v_ktrt_cap_ngay_tha THEN
      -- ?ang h?i ?/sau th?i ?i?m ra tr?i th?t: không còn "th?i gian còn l?i" nào t? góc nhìn
      -- hi?n t?i, dù v_cl_n/t/g c?a GENERAL (tính t?i m?c b? cap = ngày tha) có khác 0.
      p_tg_con_raw_nam := 0; p_tg_con_raw_thang := 0; p_tg_con_raw_ngay := 0;
    ELSE
      -- ?ang h?i ? 1 m?c l?ch s? TR??C khi ra tr?i th?t (ho?c không có KTRT): dùng k?t qu? GENERAL.
      p_tg_con_raw_nam := v_cl_n; p_tg_con_raw_thang := v_cl_t; p_tg_con_raw_ngay := v_cl_g;
    END IF;

    -- Ch?a quá h?n: ?u tiên THA_NGAY_HET_HAN ?ã l?u (kh?p SP_UPDATE / standalone) — tái dùng
    -- v_tha_ngay_het_han ?ã l?y cùng THA ??i di?n ? ??u th? t?c (b? SELECT trùng).
    -- B? qua khi THA_NGAY_HET_HAN trùng THA_CO_DIEU_KIENS.NGAY_THA c?a chính PN — t?c c?t này
    -- ?ã b? quy trình duy?t THC?K ghi ?è b?ng ngày tha s?m, không ph?i ngày h?t án lý thuy?t
    -- (cùng nguyên nhân v?i override KTRT_NGAY_THA ? trên; ?ây là ?i?m CÒN L?I ?ã ki?m ch?ng
    -- khi?n bug v?n x?y ra k? c? sau khi ch?n riêng KTRT).
    -- Thêm v_ktrt_cap_ngay_tha IS NULL: KHÔNG cho THA_NGAY_HET_HAN ?ã l?u (có th? c?/sai) ghi ?è
    -- lên p_ngay_het ?ã ???c ch?t ch?c ch?n b?ng KTRT th?t ? trên.
    IF v_gen_ngay_bat IS NOT NULL AND NVL(p_bo_qua_da_tha, 0) != 1 AND NVL(p_bo_qua_da_luu, 0) != 1
       AND v_ktrt_cap_ngay_tha IS NULL THEN
      IF v_tha_ngay_het_han IS NOT NULL
         AND TRUNC(v_tha_ngay_het_han) >= TRUNC(v_gen_ngay_bat)
         AND TRUNC(v_tha_ngay_het_han) >= v_ngay_xet_eff
         AND (v_thcdk_ngay_tha IS NULL OR TRUNC(v_tha_ngay_het_han) != v_thcdk_ngay_tha)
      THEN
        p_ngay_het := TRUNC(v_tha_ngay_het_han);
      END IF;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      p_ngay_het := NULL;
      p_blocked := 0;
  END get_ngay_het_via_general;

  FUNCTION get_ngay_het_general_fn(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE
  ) RETURN DATE IS
    v_het DATE;
    v_blk PLS_INTEGER;
    v_raw DATE;
    v_dcn NUMBER; v_dct NUMBER; v_dcg NUMBER;
    v_tcn NUMBER; v_tct NUMBER; v_tcg NUMBER;
  BEGIN
    get_ngay_het_via_general(p_id_pham_nhan, p_ngay_xet, v_het, v_blk, v_raw, v_dcn, v_dct, v_dcg, v_tcn, v_tct, v_tcg);
    IF v_blk = 1 THEN
      RETURN NULL;
    END IF;
    RETURN v_het;
  END get_ngay_het_general_fn;

  -- Ngày m? ch?n s?m nh?t (T?C/hoãn/tr?n) tr??c m?c xét, thu?c án [ngay_bat, ngay_xet) — trích xu?t m? không ch?n
  FUNCTION get_ngay_mo_chan_priv(
    p_id       NUMBER,
    p_ngay_xet DATE,
    p_ngay_bat DATE DEFAULT NULL
  ) RETURN DATE IS
    v_result DATE;
  BEGIN
    SELECT MIN(mo_dt)
      INTO v_result
      FROM (
        SELECT TRUNC(td.TU_NGAY) AS mo_dt
          FROM QLPN.TAM_DINH_CHIS td
         WHERE td.PHAM_NHAN_ID = p_id
           AND NVL(td.IS_DELETED, 0) = 0
           AND td.TU_NGAY IS NOT NULL
           AND td.NGAY_LAI IS NULL
           AND NOT EXISTS (
                 SELECT 1
                   FROM QLPN.DM_TINH_TRANG_TAM_DINH_CHIES tt
                  WHERE tt.ID = td.TINH_TRANG_ID
                    AND TRIM(CAST(tt.TTTDC_TEN AS NVARCHAR2(4000))) = u'Gia h\1ea1n'
               )
           AND td.TU_NGAY < p_ngay_xet + 1
           AND (p_ngay_bat IS NULL OR td.TU_NGAY >= TRUNC(p_ngay_bat))
        UNION ALL
        SELECT TRUNC(h.NGAY_HOAN)
          FROM QLPN.HOAN_THI_HANH_ANS h
         WHERE h.PHAM_NHAN_ID = p_id
           AND NVL(h.IS_DELETED, 0) = 0
           AND h.NGAY_HOAN IS NOT NULL
           AND h.NGAY_THI_HANH_AN IS NULL
           AND h.NGAY_HOAN < p_ngay_xet + 1
           AND (p_ngay_bat IS NULL OR h.NGAY_HOAN >= TRUNC(p_ngay_bat))
        UNION ALL
        SELECT TRUNC(tt.NGAY_TRON)
          FROM QLPN.TRON_TRAIS tt
         WHERE tt.PHAM_NHAN_ID = p_id
           AND NVL(tt.IS_DELETED, 0) = 0
           AND tt.NGAY_TRON IS NOT NULL
           AND tt.NGAY_BAT_LAI IS NULL
           AND tt.NGAY_TRON < p_ngay_xet + 1
           AND (p_ngay_bat IS NULL OR tt.NGAY_TRON >= TRUNC(p_ngay_bat))
      );
    RETURN v_result;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN NULL;
    WHEN OTHERS THEN
      RETURN NULL;
  END get_ngay_mo_chan_priv;

  -- Ngày ch?t g?n nh?t tr??c m?c xét (PN_KET_THUC_CHETS), thu?c án hi?n t?i [ngay_bat, ngay_xet]
  FUNCTION get_ngay_chet_priv(
    p_id       NUMBER,
    p_ngay_xet DATE,
    p_ngay_bat DATE DEFAULT NULL
  ) RETURN DATE IS
    v_result DATE;
  BEGIN
    SELECT TRUNC(k.KTC_NGAY_CHET)
      INTO v_result
      FROM QLPN.PN_KET_THUC_CHETS k
     WHERE k.KTC_PN_LAI_LICH_ID = p_id
       AND NVL(k.IS_DELETED, 0) = 0
       AND k.KTC_NGAY_CHET IS NOT NULL
       AND TRUNC(k.KTC_NGAY_CHET) < p_ngay_xet + 1
       AND (p_ngay_bat IS NULL OR TRUNC(k.KTC_NGAY_CHET) >= TRUNC(p_ngay_bat))
     ORDER BY k.KTC_NGAY_CHET DESC
     FETCH FIRST 1 ROW ONLY;
    RETURN v_result;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN NULL;
    WHEN OTHERS THEN
      RETURN NULL;
  END get_ngay_chet_priv;

  -- Ngày chuy?n giao g?n nh?t tr??c m?c xét (PN_CHUYEN_GIAO), thu?c án hi?n t?i [ngay_bat, ngay_xet]
  FUNCTION get_ngay_chuyen_giao_priv(
    p_id       NUMBER,
    p_ngay_xet DATE,
    p_ngay_bat DATE DEFAULT NULL
  ) RETURN DATE IS
    v_result DATE;
  BEGIN
    SELECT TRUNC(cg.PNCG_NGAY_CHUYEN_GIAO)
      INTO v_result
      FROM QLPN.PN_CHUYEN_GIAO cg
     WHERE cg.PNCG_LAI_LICH_ID = p_id
       AND NVL(cg.IS_DELETED, 0) = 0
       AND cg.PNCG_NGAY_CHUYEN_GIAO IS NOT NULL
       AND TRUNC(cg.PNCG_NGAY_CHUYEN_GIAO) < p_ngay_xet + 1
       AND (p_ngay_bat IS NULL OR TRUNC(cg.PNCG_NGAY_CHUYEN_GIAO) >= TRUNC(p_ngay_bat))
     ORDER BY cg.PNCG_NGAY_CHUYEN_GIAO DESC
     FETCH FIRST 1 ROW ONLY;
    RETURN v_result;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN NULL;
    WHEN OTHERS THEN
      RETURN NULL;
  END get_ngay_chuyen_giao_priv;

  -- Ngày tr? t? do s?m nh?t c?a h?y án m? (HUY_ANS ch?a có NGAY_TRO_LAI) tr??c m?c xét,
  -- thu?c án hi?n t?i [ngay_bat, ngay_xet] — cap ngày xét nh? ngày ch?t/chuy?n giao
  FUNCTION get_ngay_huy_an_priv(
    p_id       NUMBER,
    p_ngay_xet DATE,
    p_ngay_bat DATE DEFAULT NULL
  ) RETURN DATE IS
    v_result DATE;
  BEGIN
    SELECT MIN(TRUNC(hu.NGAY_TRA_TU_DO))
      INTO v_result
      FROM QLPN.HUY_ANS hu
     WHERE hu.PHAM_NHAN_ID = p_id
       AND NVL(hu.IS_DELETED, 0) = 0
       AND hu.NGAY_TRA_TU_DO IS NOT NULL
       AND hu.NGAY_TRO_LAI IS NULL
       AND hu.NGAY_TRA_TU_DO < p_ngay_xet + 1
       AND (p_ngay_bat IS NULL OR hu.NGAY_TRA_TU_DO >= TRUNC(p_ngay_bat));
    RETURN v_result;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN NULL;
    WHEN OTHERS THEN
      RETURN NULL;
  END get_ngay_huy_an_priv;

  FUNCTION get_tha_an_phat_priv(p_id NUMBER, p_ngay_xet DATE) RETURN NVARCHAR2 IS
    v_result NVARCHAR2(2000);
  BEGIN
    SELECT tha.THA_AN_PHAT INTO v_result
      FROM (
        SELECT t.THA_AN_PHAT, ROW_NUMBER() OVER (ORDER BY t.THA_NGAY_BAT DESC) AS rn
          FROM QLPN.PN_THI_HANH_AN t
         WHERE t.THA_PNLAI_LICH_ID = p_id
           AND NVL(t.IS_DELETED, 0) = 0
           AND t.THA_NGAY_BAT IS NOT NULL
           AND t.THA_NGAY_BAT < NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE)) + 1
      ) tha WHERE tha.rn = 1;
    RETURN v_result;
  EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL;
  END get_tha_an_phat_priv;

  FUNCTION calc_nguong_date(p_ngay_bat DATE, p_tong_thang NUMBER, p_ratio NUMBER) RETURN DATE IS
    v_thang_ng NUMBER;
    v_nguyen   NUMBER;
    v_le       NUMBER;
    v_ng_tm    NUMBER;
    v_nguong   DATE;
  BEGIN
    v_thang_ng := p_ratio * p_tong_thang;
    v_nguyen   := FLOOR(v_thang_ng);
    v_le       := v_thang_ng - v_nguyen;
    v_nguong   := ADD_MONTHS(p_ngay_bat, v_nguyen);
    IF v_le > 0.0001 THEN
      v_ng_tm  := ADD_MONTHS(p_ngay_bat, v_nguyen + 1) - ADD_MONTHS(p_ngay_bat, v_nguyen);
      v_nguong := v_nguong + (v_le * v_ng_tm);
    END IF;
    RETURN v_nguong;
  END calc_nguong_date;

  FUNCTION FN_NGAY_NGUONG_TU_TONG_THANG(
    p_ngay_bat      IN DATE,
    p_tong_thang_an IN NUMBER,
    p_ratio         IN NUMBER
  ) RETURN DATE IS
  BEGIN
    IF p_ngay_bat IS NULL OR p_tong_thang_an IS NULL OR p_tong_thang_an <= 0
       OR p_ratio IS NULL OR p_ratio <= 0 THEN
      RETURN NULL;
    END IF;
    RETURN calc_nguong_date(p_ngay_bat, p_tong_thang_an, p_ratio);
  EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
  END FN_NGAY_NGUONG_TU_TONG_THANG;

  -- Tra MA_TG tr?c ti?p b?ng s? tháng/ngày — không d?ng chu?i "X n?m Y tháng Z ngày" r?i tra text
  -- nh? lookup_mtg_ma_for_nam_thang_ngay_title (hàm ?ó ph?c v? hi?n th? t? chu?i có s?n; hàm này
  -- ph?c v? get_core_impl ghi MA_TG th?ng t? Y/M/D v?a tính, không qua s? ngày trung gian). Áp
  -- d?ng ?úng quy t?c làm tròn "ngày l? >= 30 -> +1 tháng" mà format_tg_from_days dùng (?? kh?p
  -- ?úng mi?n giá tr? MTG_NGAY 0-29 ?ã verify ph? ??y trong QLPN.DM_MA_THOI_GIANS). ??t tr??c
  -- get_core_impl vì ???c g?i t? bên trong ?ó.
  FUNCTION ymd_to_ma_tg(p_y IN NUMBER, p_m IN NUMBER, p_d IN NUMBER) RETURN NVARCHAR2 IS
    v_y NUMBER := NVL(p_y, 0);
    v_m NUMBER := NVL(p_m, 0);
    v_d NUMBER := NVL(p_d, 0);
    v_thang NUMBER;
    v_ma    NVARCHAR2(255);
  BEGIN
    IF p_y IS NULL AND p_m IS NULL AND p_d IS NULL THEN RETURN NULL; END IF;
    IF v_d >= 30 THEN
      v_m := v_m + 1; v_d := 0;
      IF v_m >= 12 THEN v_y := v_y + TRUNC(v_m/12); v_m := MOD(v_m,12); END IF;
    END IF;
    v_thang := v_y * 12 + v_m;
    IF v_thang = 0 AND v_d = 0 THEN RETURN '000000'; END IF;
    BEGIN
      SELECT MTG_MA INTO v_ma FROM QLPN.DM_MA_THOI_GIANS
       WHERE NVL(MTG_NAM,0)*12 + NVL(MTG_THANG,0) = v_thang
         AND NVL(MTG_NGAY,0) = v_d
         AND NVL(IS_DELETED,0) = 0
       FETCH FIRST 1 ROW ONLY;
    EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL; END;
    RETURN v_ma;
  EXCEPTION WHEN OTHERS THEN RETURN NULL;
  END ymd_to_ma_tg;

  -- Chi?u ng??c: MA_TG -> s? ngày th?t, neo b?ng ADD_MONTHS trên p_anchor (kh?p ?úng cách
  -- get_core_impl tính p_tg_da/p_tg_con t? Y/M/D — không dùng công th?c flat "m??n 30/12" c?a
  -- PKG_TRAIVIEN_TINH_AN.parse_muc_giam_to_days, ?ã ?o l?ch n?ng so v?i công th?c neo l?ch th?t
  -- trên d? li?u th?t). Dùng cho get_core_cached/get_tcdk_core_cached ??c l?i memo — ??t tr??c
  -- 2 hàm ?ó vì ???c g?i t? bên trong.
  FUNCTION parse_ma_tg_to_days(p_ma_tg IN NVARCHAR2, p_anchor IN DATE) RETURN NUMBER IS
    v_tong_thang NUMBER; v_ngay NUMBER;
  BEGIN
    IF p_ma_tg IS NULL OR p_anchor IS NULL THEN RETURN NULL; END IF;
    IF p_ma_tg = '000000' THEN RETURN 0; END IF;
    BEGIN
      SELECT NVL(MTG_NAM,0)*12 + NVL(MTG_THANG,0), NVL(MTG_NGAY,0)
        INTO v_tong_thang, v_ngay
        FROM QLPN.DM_MA_THOI_GIANS
       WHERE MTG_MA = p_ma_tg AND NVL(IS_DELETED,0) = 0
       FETCH FIRST 1 ROW ONLY;
    EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL; END;
    RETURN GREATEST(0, TRUNC(ADD_MONTHS(p_anchor, v_tong_thang) + v_ngay) - TRUNC(p_anchor));
  EXCEPTION WHEN OTHERS THEN RETURN NULL;
  END parse_ma_tg_to_days;

  -- Helper: tính th?c (không cache) — ???c g?i b?i get_core_cached và SP_POPULATE_CORE_MEMO
  -- p_gen_ngay_het/p_gen_blocked: k?t qu? thô get_ngay_het_via_general ?ã g?i bên trong;
  -- p_gen_valid = 1 khi GENERAL ch?y v?i ?úng TRUNC(p_ngay_xet) (không b? cap mo_chan/ch?t/chuy?n giao)
  -- ? caller tái dùng thay vì g?i get_ngay_het_general_fn l?n n?a.
  PROCEDURE get_core_impl(
    p_id_pham_nhan   IN  NUMBER,
    p_ngay_xet       IN  DATE,
    p_ngay_bat       OUT NOCOPY DATE,
    p_tg_da          OUT NOCOPY NUMBER,
    p_tg_con         OUT NOCOPY NUMBER,
    p_ngay_xet_tl    OUT NOCOPY DATE,
    p_gen_ngay_het   OUT NOCOPY DATE,
    p_gen_blocked    OUT NOCOPY PLS_INTEGER,
    p_gen_valid      OUT NOCOPY PLS_INTEGER,
    -- MA_TG (QLPN.DM_MA_THOI_GIANS.MTG_MA) tính tr?c ti?p t? Y/M/D t?i t?ng nhánh — không quy ??i
    -- qua p_tg_da/p_tg_con (s? ngày) r?i tính ng??c. Dùng ?? ghi DX_CORE_MEMO/TCDK_CORE_MEMO.
    p_tg_da_ma_tg    OUT NOCOPY NVARCHAR2,
    p_tg_con_ma_tg   OUT NOCOPY NVARCHAR2,
    -- Tham s? cu?i, có default, ?? không phá các l?i g?i v? trí (positional) hi?n có.
    -- 1 = b? qua fallback THA_NGAY_HET_HAN ??c tr?c ti?p bên d??i VÀ truy?n ti?p
    -- p_bo_qua_da_luu=>1 vào get_ngay_het_via_general (không ??ng p_bo_qua_da_tha nên
    -- PN_KET_THUC_RA_TRAIS v?n ???c tôn tr?ng bình th??ng) — dùng b?i get_tg_da_va_con_nocache.
    p_bo_qua_da_luu  IN  NUMBER DEFAULT 0
  ) IS
    v_ngay_xet       DATE;
    v_ngay_xet_raw   DATE;
    v_ngay_ra_trai   DATE;
    v_ngay_mo_chan   DATE;
    v_ngay_bat       DATE;
    v_upper_ap       NVARCHAR2(2000);
    v_an_phat_txt    NVARCHAR2(2000);
    v_block          PLS_INTEGER := 0;
    v_served_at_court BOOLEAN := FALSE;
    v_span           NUMBER;
    v_ngay_het       DATE;
    v_moc            DATE;
    v_blocked_gen    PLS_INTEGER := 0;
    v_gen_het_raw    DATE;
    -- ?ã CH / còn l?i THÔ (Y/M/D) t? get_ngay_het_via_general/SP — tái dùng cho nhánh bình
    -- th??ng thay vì t? query l?i T?C/hoãn/tr?n/h?y án (PKG_TINH_AN_USAGE.md §6.3).
    v_gen_da_n       NUMBER;
    v_gen_da_t       NUMBER;
    v_gen_da_g       NUMBER;
    v_gen_cl_n       NUMBER;
    v_gen_cl_t       NUMBER;
    v_gen_cl_g       NUMBER;
    v_tha_ngay_het_han DATE;
    -- Ngày tha THC?K g?n nh?t c?a PN (n?u có) — cùng m?c ?ích v?i get_ngay_het_via_general:
    -- không tin v_tha_ngay_het_han (??c tr?c ti?p THA_NGAY_HET_HAN bên d??i, ??c l?p v?i
    -- get_ngay_het_via_general) khi nó th?c ra là ngày tha s?m do THC?K b? ghi ?è vào c?t này.
    v_thcdk_ngay_tha   DATE;
  BEGIN
    p_ngay_bat := NULL;
    p_tg_da := NULL;
    p_tg_con := NULL;
    p_ngay_xet_tl := NULL;
    p_gen_ngay_het := NULL;
    p_gen_blocked := 0;
    p_gen_valid := 0;
    p_tg_da_ma_tg := NULL;
    p_tg_con_ma_tg := NULL;

    IF p_id_pham_nhan IS NULL THEN
      RETURN;
    END IF;

    -- NGÀY NH?P VÀO = ngày xét; n?u không có ngày xét thì SYSDATE
    v_ngay_xet := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));
    v_ngay_xet_raw := v_ngay_xet;

    BEGIN
      SELECT TRUNC(tcdk.NGAY_THA)
        INTO v_thcdk_ngay_tha
        FROM QLPN.THA_CO_DIEU_KIENS tcdk
       WHERE tcdk.PHAM_NHAN_ID = p_id_pham_nhan
         AND NVL(tcdk.IS_DELETED, 0) = 0
         AND tcdk.NGAY_THA IS NOT NULL
       ORDER BY tcdk.CREATION_TIME DESC
       FETCH FIRST 1 ROW ONLY;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_thcdk_ngay_tha := NULL;
    END;

    -- L?y ngày b?t + án ph?t + ngày h?t h?n t? THA ??i di?n (tr??c khi cap T?C — tránh T?C c? < ngày b?t làm m?t THA)
    -- T?m giam/t?m gi?/? tr??c/ch?a b?nh b?t bu?c KHÔNG c?n fetch riêng ? ?ây n?a — ?ã có s?n
    -- trong ?ã CH thô (v_gen_da_n/t/g) do get_ngay_het_via_general/SP c?ng vào (B??C 12).
    SELECT tha.ngay_bat,
           tha.THA_AN_PHAT,
           tha.THA_NGAY_HET_HAN
      INTO v_ngay_bat, v_an_phat_txt, v_ngay_ra_trai
      FROM (
        SELECT t.THA_NGAY_BAT AS ngay_bat,
               t.THA_AN_PHAT,
               t.THA_NGAY_HET_HAN,
               ROW_NUMBER() OVER (ORDER BY t.THA_NGAY_BAT DESC) AS rn
          FROM QLPN.PN_THI_HANH_AN t
         WHERE t.THA_PNLAI_LICH_ID = p_id_pham_nhan
           AND NVL(t.IS_DELETED, 0) = 0
           AND t.THA_NGAY_BAT IS NOT NULL
           AND t.THA_NGAY_BAT < v_ngay_xet + 1
      ) tha
     WHERE tha.rn = 1;

    IF v_ngay_bat IS NULL THEN
      RETURN;
    END IF;

    v_ngay_bat := TRUNC(v_ngay_bat);

    -- Ch?a b?nh b?t bu?c KHÔNG c?n fetch riêng ? ?ây n?a — get_ngay_het_via_general/SP t?
    -- query l?i và ?ã c?ng vào ?ã CH thô (v_gen_da_n/t/g, B??C 12).

    -- Tr?n/hoãn/T?C m?: cap m?c xét t?i ngày m? + ch?n còn l?i (?ã CH = span t?i ngày m?)
    v_ngay_mo_chan := get_ngay_mo_chan_priv(p_id_pham_nhan, v_ngay_xet, v_ngay_bat);

    IF v_ngay_mo_chan IS NOT NULL THEN
      v_ngay_xet := LEAST(v_ngay_xet, v_ngay_mo_chan);
      v_block := 1;
    END IF;

    -- PN ch?t / chuy?n giao / h?y án tr? t? do: ?ã CH tính ??n ngày k?t thúc
    DECLARE
      v_ngay_chet DATE;
      v_ngay_chuyen_giao DATE;
      v_ngay_huy_an DATE;
    BEGIN
      v_ngay_chet := get_ngay_chet_priv(p_id_pham_nhan, v_ngay_xet, v_ngay_bat);
      IF v_ngay_chet IS NOT NULL THEN
        v_ngay_xet := LEAST(v_ngay_xet, v_ngay_chet);
      END IF;
      v_ngay_chuyen_giao := get_ngay_chuyen_giao_priv(p_id_pham_nhan, v_ngay_xet, v_ngay_bat);
      IF v_ngay_chuyen_giao IS NOT NULL THEN
        v_ngay_xet := LEAST(v_ngay_xet, v_ngay_chuyen_giao);
      END IF;
      v_ngay_huy_an := get_ngay_huy_an_priv(p_id_pham_nhan, v_ngay_xet, v_ngay_bat);
      IF v_ngay_huy_an IS NOT NULL THEN
        v_ngay_xet := LEAST(v_ngay_xet, v_ngay_huy_an);
      END IF;
    END;

    -- (THA ?ã l?y ? trên — b? SELECT trùng)

    -- Gi? THA_NGAY_HET_HAN g?c (fallback khi GENERAL/KTRT tr? m?c x?u) — b? qua khi
    -- p_bo_qua_da_luu=1 (không tin c?t ?ã l?u, có th? l?ch d? li?u tính t??i). C?ng b? qua khi
    -- THA_NGAY_HET_HAN trùng THA_CO_DIEU_KIENS.NGAY_THA — c?t này ?ã b? quy trình duy?t THC?K
    -- ghi ?è b?ng ngày tha s?m, không ph?i ngày h?t án lý thuy?t (?ã ki?m ch?ng th?c t? qua
    -- SP_GET_THA_CDK_BAN_GIAO_PN).
    v_tha_ngay_het_han := NULL;
    IF NVL(p_bo_qua_da_luu, 0) = 1 THEN
      v_ngay_ra_trai := NULL;
    END IF;
    IF v_ngay_ra_trai IS NOT NULL
       AND (v_thcdk_ngay_tha IS NULL OR TRUNC(v_ngay_ra_trai) != v_thcdk_ngay_tha)
    THEN
      v_tha_ngay_het_han := TRUNC(v_ngay_ra_trai);
      v_ngay_ra_trai := NULL;
    END IF;

    -- Ngày h?t án (tr??c sub): cap v_ngay_xet t?i ngày h?t th?c t?, không dùng THA_NGAY_HET_HAN c? l?ch GENERAL
    v_upper_ap := UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(v_an_phat_txt), u'')));

    get_ngay_het_via_general(p_id_pham_nhan, v_ngay_xet, v_ngay_het, v_blocked_gen, v_gen_het_raw,
      v_gen_da_n, v_gen_da_t, v_gen_da_g, v_gen_cl_n, v_gen_cl_t, v_gen_cl_g,
      p_bo_qua_da_luu => p_bo_qua_da_luu);

    -- Gi? k?t qu? thô cho caller (ch? h?p l? khi ngày xét ch?a b? cap — cùng input v?i get_ngay_het_general_fn)
    p_gen_ngay_het := v_ngay_het;
    p_gen_blocked  := v_blocked_gen;
    IF v_ngay_xet = v_ngay_xet_raw THEN
      p_gen_valid := 1;
    END IF;

    IF v_ngay_het IS NOT NULL AND TRUNC(v_ngay_het) < v_ngay_bat THEN
      v_ngay_het := NULL;
    END IF;

    IF v_ngay_het IS NULL
       AND v_tha_ngay_het_han IS NOT NULL
       AND TRUNC(v_tha_ngay_het_han) >= v_ngay_bat
    THEN
      v_ngay_het := v_tha_ngay_het_han;
    ELSIF v_tha_ngay_het_han IS NOT NULL
       AND TRUNC(v_tha_ngay_het_han) >= v_ngay_bat
       AND TRUNC(v_tha_ngay_het_han) >= TRUNC(v_ngay_xet)
    THEN
      v_ngay_het := v_tha_ngay_het_han;
    END IF;

    IF v_block = 0
       AND v_ngay_het IS NOT NULL
       AND TRUNC(v_ngay_het) < TRUNC(v_ngay_xet)
    THEN
      v_ngay_ra_trai := TRUNC(v_ngay_het);
      v_ngay_xet := TRUNC(v_ngay_het);
    END IF;

    -- T?C ?ã ?óng / h?y án ?ã ?óng: KHÔNG c?n t? query l?i ? ?ây n?a — ?ã ???c
    -- get_ngay_het_via_general/SP quy ??i Y/M/D per-interval và tr? vào ?ã CH thô
    -- (v_gen_da_n/t/g) r?i (PKG_TINH_AN_USAGE.md §6.3). Vi?c phát hi?n T?C M? (ch?n) v?n do
    -- get_ngay_mo_chan_priv ? trên ??m nhi?m, không liên quan vòng l?p này.

    -- Hoãn: ch? còn c?n phát hi?n M? (ch?n) — ph?n c?ng d?n Y/M/D c?a kho?ng ?ã ?óng ?ã có
    -- s?n trong v_gen_da_n/t/g (SP).
    FOR r IN (
        SELECT h.NGAY_HOAN, h.NGAY_THI_HANH_AN
        FROM QLPN.HOAN_THI_HANH_ANS h
        WHERE h.PHAM_NHAN_ID = p_id_pham_nhan
          AND NVL(h.IS_DELETED, 0) = 0
          AND h.NGAY_HOAN IS NOT NULL
          AND h.NGAY_HOAN < v_ngay_xet + 1
          AND h.NGAY_HOAN >= v_ngay_bat
          AND h.NGAY_THI_HANH_AN IS NULL
    ) LOOP
        v_block := 1;
    END LOOP;

    -- Tr?n: ch? còn c?n phát hi?n M? (ch?n) — ph?n c?ng d?n Y/M/D c?a kho?ng ?ã ?óng ?ã có
    -- s?n trong v_gen_da_n/t/g (SP).
    FOR r IN (
        SELECT tt.NGAY_TRON, tt.NGAY_BAT_LAI
        FROM QLPN.TRON_TRAIS tt
        WHERE tt.PHAM_NHAN_ID = p_id_pham_nhan
          AND NVL(tt.IS_DELETED, 0) = 0
          AND tt.NGAY_TRON IS NOT NULL
          AND tt.NGAY_TRON < v_ngay_xet + 1
          AND tt.NGAY_TRON >= v_ngay_bat
          AND tt.NGAY_BAT_LAI IS NULL
    ) LOOP
        v_block := 1;
    END LOOP;

    -- Trích xu?t (k? c? ?ang m?, ch?a có TX_NGAY_TRA) không ch?n — th?i gian trích xu?t v?n tính là ?ang ch?p hành án.

    -- (get_ngay_het ?ã g?i ? trên — dùng l?i v_ngay_het / v_blocked_gen)

    IF v_ngay_het IS NULL OR v_blocked_gen = 1 THEN
      v_moc := TRUNC(v_ngay_xet);
    ELSE
      v_moc := LEAST(TRUNC(v_ngay_xet), TRUNC(v_ngay_het));
    END IF;

    p_ngay_bat := v_ngay_bat;
    v_span := GREATEST(0, TRUNC(v_moc) - TRUNC(v_ngay_bat));

    -- Phát hi?n "tuyên t? do t?i tòa" b?ng v_gen_het_raw (k?t qu? THÔ, luôn tính t??i t?
    -- SP_TINH_NGAY_HET_AN_GENERAL) — KHÔNG dùng v_ngay_het, vì v_ngay_het có th? ?ã b? ghi ?è
    -- b?ng THA_NGAY_HET_HAN C? ?ã l?u trong DB (2 l?p ?u tiên giá tr? ?ã l?u ? trên và trong
    -- get_ngay_het_via_general) — n?u b?n ghi ?ã ???c tính t? TR??C khi s?a B??C 11 c?a SP,
    -- c?t l?u v?n còn giá tr? c? (chi?u ngày h?t án ra t??ng lai), khi?n v_ngay_het != v_ngay_bat
    -- dù b?n ch?t v?n là case này, làm nhánh d??i (span+t?m giam) ch?y l?i và ??m trùng.
    IF v_gen_het_raw IS NOT NULL AND TRUNC(v_gen_het_raw) = v_ngay_bat THEN
      -- T?m giam/t?m gi?/? tr??c/ch?a b?nh b?t bu?c ?ã ?? bù án ph?t TR??C ngày b?t
      -- (SP_TINH_NGAY_HET_AN_GENERAL tr? ngày h?t án = ngày b?t — tín hi?u "tuyên t? do t?i
      -- tòa", B??C 11): ?ã ch?p hành = án ph?t g?c tr?c ti?p — KHÔNG c?ng span/t?m giam nh?
      -- nhánh d??i, vì v_span (ngày b?t ? m?c = ngày b?t) ?ã = 0 nh?ng c?ng thêm t?m giam vào
      -- ?ó s? ??m trùng (án ph?t g?c m?i là gi?i h?n ?úng, không ph?i t?ng t?m giam).
      v_served_at_court := TRUE;
      DECLARE
        v_ap_n NUMBER := 0; v_ap_t NUMBER := 0; v_ap_g NUMBER := 0;
      BEGIN
        sum_ymd_text(v_an_phat_txt, v_ap_n, v_ap_t, v_ap_g);
        p_tg_da := GREATEST(0, TRUNC(ADD_MONTHS(v_ngay_bat, v_ap_n * 12 + v_ap_t) + v_ap_g) - TRUNC(v_ngay_bat));
        p_tg_da_ma_tg := ymd_to_ma_tg(v_ap_n, v_ap_t, v_ap_g);
      END;
    ELSIF v_block = 1 THEN
      -- Ch?n m? (T?C/hoãn/tr?n): ch? tính span thô, không c?ng t?m giam/t?m gi?
      p_tg_da := v_span;
      DECLARE
        v_da_y NUMBER; v_da_m NUMBER; v_da_d NUMBER;
      BEGIN
        diff_ymd(v_ngay_bat, v_moc, v_da_y, v_da_m, v_da_d);
        p_tg_da_ma_tg := ymd_to_ma_tg(v_da_y, v_da_m, v_da_d);
      END;
    ELSE
      -- ?ã ch?p hành = Y/M/D THÔ ?ã tính s?n t? get_ngay_het_via_general/SP ? trên
      -- (v_gen_da_n/t/g — ?ã tr? T?C/hoãn/tr?n/h?y án theo t?ng kho?ng th?t + c?ng t?m
      -- giam/t?m gi?/? tr??c/ch?a b?nh b?t bu?c, B??C 12). KHÔNG t? query l?i 4 b?ng và t?
      -- tr?/c?ng l?n n?a (PKG_TINH_AN_USAGE.md §6.3) — ch? còn b??c quy v? s? ngày tuy?t ??i
      -- tính t? ngày b?t (DX_CORE_MEMO/TCDK_CORE_MEMO yêu c?u NUMBER, không có c?t Y/M/D riêng).
      p_tg_da := GREATEST(
        0,
        TRUNC(ADD_MONTHS(v_ngay_bat, NVL(v_gen_da_n, 0) * 12 + NVL(v_gen_da_t, 0)) + NVL(v_gen_da_g, 0)) - TRUNC(v_ngay_bat)
      );
      p_tg_da_ma_tg := ymd_to_ma_tg(v_gen_da_n, v_gen_da_t, v_gen_da_g);
    END IF;
    p_ngay_xet_tl := TRUNC(v_moc);

    -- Tính TG còn l?i (NULL ch? khi không xác ??nh ngày h?t án: chung thân/tù hình thu?n, ch?n m?, v.v.)
    IF v_served_at_court THEN
      -- ??ng b? p_tg_da ? trên: ?ã ch?p hành ?? ngay t?i tòa, còn l?i = 0 — không ph? thu?c
      -- v_ngay_het/v_moc (có th? v?n ?ang b? ghi ?è b?i THA_NGAY_HET_HAN c? ?ã l?u trong DB).
      p_tg_con := 0;
      p_tg_con_ma_tg := '000000';
    ELSIF v_upper_ap LIKE '%' || 'TUHINH' || '%' THEN
      p_tg_con := NULL;
      p_tg_con_ma_tg := NULL;
    ELSIF v_block = 1 OR v_blocked_gen = 1 THEN
      p_tg_con := NULL;
      p_tg_con_ma_tg := NULL;
    ELSIF v_ngay_het IS NULL THEN
      p_tg_con := NULL;
      p_tg_con_ma_tg := NULL;
    ELSIF v_ngay_ra_trai IS NOT NULL THEN
      p_tg_con := 0;
      p_tg_con_ma_tg := '000000';
    ELSE
      p_tg_con := GREATEST(0, TRUNC(v_ngay_het) - TRUNC(v_moc));
      DECLARE
        v_cl_y NUMBER; v_cl_m NUMBER; v_cl_d NUMBER;
      BEGIN
        diff_ymd(v_moc, v_ngay_het, v_cl_y, v_cl_m, v_cl_d);
        p_tg_con_ma_tg := ymd_to_ma_tg(v_cl_y, v_cl_m, v_cl_d);
      END;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      NULL;
    WHEN OTHERS THEN
      p_ngay_bat := NULL;
      p_tg_da := NULL;
      p_tg_con := NULL;
      p_ngay_xet_tl := NULL;
      p_gen_ngay_het := NULL;
      p_gen_blocked := 0;
      p_gen_valid := 0;
      p_tg_da_ma_tg := NULL;
      p_tg_con_ma_tg := NULL;
  END get_core_impl;

  -- ??c DX_CORE_MEMO tr??c; fallback g?i get_core_impl n?u ch?a có.
  FUNCTION get_core_cached(p_id_pham_nhan IN NUMBER, p_ngay_xet IN DATE)
    RETURN t_tinh_an_core_rec IS
    v_rec t_tinh_an_core_rec;
    v_key DATE := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));
    v_gen_het   DATE;
    v_gen_blk   PLS_INTEGER;
    v_gen_valid PLS_INTEGER;
    v_tg_da_ma  QLPN.DX_CORE_MEMO.TG_DA%TYPE;
    v_tg_con_ma QLPN.DX_CORE_MEMO.TG_CON%TYPE;
    v_dummy_da_ma  NVARCHAR2(255);
    v_dummy_con_ma NVARCHAR2(255);
  BEGIN
    BEGIN
      SELECT ngay_bat, tg_da, tg_con, ngay_xet_tl
        INTO v_rec.ngay_bat, v_tg_da_ma, v_tg_con_ma, v_rec.ngay_xet_tl
        FROM QLPN.DX_CORE_MEMO
       WHERE pn_id = p_id_pham_nhan AND ngay_xet_key = v_key;
      v_rec.tg_da  := parse_ma_tg_to_days(v_tg_da_ma,  v_rec.ngay_bat);
      v_rec.tg_con := parse_ma_tg_to_days(v_tg_con_ma, v_rec.ngay_xet_tl);
      RETURN v_rec;
    EXCEPTION WHEN NO_DATA_FOUND THEN NULL; END;
    get_core_impl(p_id_pham_nhan, p_ngay_xet, v_rec.ngay_bat, v_rec.tg_da, v_rec.tg_con, v_rec.ngay_xet_tl,
                  v_gen_het, v_gen_blk, v_gen_valid, v_dummy_da_ma, v_dummy_con_ma);
    RETURN v_rec;
  END get_core_cached;

  -- ??c ngay_het t? DX_CORE_MEMO n?u có; fallback tính tr?c ti?p.
  FUNCTION get_ngay_het_cached(p_id_pham_nhan IN NUMBER, p_ngay_bat IN DATE,
                               p_an_phat IN NVARCHAR2, p_ngay_xet IN DATE) RETURN DATE IS
    v DATE;
    v_key DATE := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));
    v_blk PLS_INTEGER;
    v_raw DATE;
    v_dcn NUMBER; v_dct NUMBER; v_dcg NUMBER;
    v_tcn NUMBER; v_tct NUMBER; v_tcg NUMBER;
  BEGIN
    BEGIN
      SELECT ngay_het INTO v FROM QLPN.DX_CORE_MEMO
       WHERE pn_id = p_id_pham_nhan AND ngay_xet_key = v_key;
      RETURN v;
    EXCEPTION WHEN NO_DATA_FOUND THEN
      get_ngay_het_via_general(p_id_pham_nhan, p_ngay_xet, v, v_blk, v_raw, v_dcn, v_dct, v_dcg, v_tcn, v_tct, v_tcg);
      IF v_blk = 1 THEN
        RETURN NULL;
      END IF;
      RETURN v;
    END;
  END get_ngay_het_cached;

  -- ??c TCDK_CORE_MEMO tr??c; fallback get_core_impl (lu?ng Tha có ?K).
  FUNCTION get_tcdk_core_cached(p_id_pham_nhan IN NUMBER, p_ngay_xet IN DATE)
    RETURN t_tinh_an_core_rec IS
    v_rec t_tinh_an_core_rec;
    v_key DATE := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));
    v_gen_het   DATE;
    v_gen_blk   PLS_INTEGER;
    v_gen_valid PLS_INTEGER;
    v_tg_da_ma  QLPN.TCDK_CORE_MEMO.TG_DA%TYPE;
    v_tg_con_ma QLPN.TCDK_CORE_MEMO.TG_CON%TYPE;
    v_dummy_da_ma  NVARCHAR2(255);
    v_dummy_con_ma NVARCHAR2(255);
  BEGIN
    BEGIN
      SELECT ngay_bat, tg_da, tg_con, ngay_xet_tl
        INTO v_rec.ngay_bat, v_tg_da_ma, v_tg_con_ma, v_rec.ngay_xet_tl
        FROM QLPN.TCDK_CORE_MEMO
       WHERE pn_id = p_id_pham_nhan AND ngay_xet_key = v_key;
      v_rec.tg_da  := parse_ma_tg_to_days(v_tg_da_ma,  v_rec.ngay_bat);
      v_rec.tg_con := parse_ma_tg_to_days(v_tg_con_ma, v_rec.ngay_xet_tl);
      RETURN v_rec;
    EXCEPTION WHEN NO_DATA_FOUND THEN NULL; END;
    get_core_impl(p_id_pham_nhan, p_ngay_xet, v_rec.ngay_bat, v_rec.tg_da, v_rec.tg_con, v_rec.ngay_xet_tl,
                  v_gen_het, v_gen_blk, v_gen_valid, v_dummy_da_ma, v_dummy_con_ma);
    RETURN v_rec;
  END get_tcdk_core_cached;

  -- ??c ngay_het t? TCDK_CORE_MEMO n?u có; fallback tính tr?c ti?p.
  FUNCTION get_ngay_het_tcdk_cached(p_id_pham_nhan IN NUMBER, p_ngay_bat IN DATE,
                                    p_an_phat IN NVARCHAR2, p_ngay_xet IN DATE) RETURN DATE IS
    v DATE;
    v_key DATE := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));
    v_blk PLS_INTEGER;
    v_raw DATE;
    v_dcn NUMBER; v_dct NUMBER; v_dcg NUMBER;
    v_tcn NUMBER; v_tct NUMBER; v_tcg NUMBER;
  BEGIN
    BEGIN
      SELECT ngay_het INTO v FROM QLPN.TCDK_CORE_MEMO
       WHERE pn_id = p_id_pham_nhan AND ngay_xet_key = v_key;
      RETURN v;
    EXCEPTION WHEN NO_DATA_FOUND THEN
      get_ngay_het_via_general(p_id_pham_nhan, p_ngay_xet, v, v_blk, v_raw, v_dcn, v_dct, v_dcg, v_tcn, v_tct, v_tcg);
      IF v_blk = 1 THEN
        RETURN NULL;
      END IF;
      RETURN v;
    END;
  END get_ngay_het_tcdk_cached;

  -- Wrapper: g?i qua cache
  PROCEDURE get_tg_da_va_con(
    p_id_pham_nhan IN NUMBER, p_ngay_xet IN DATE,
    p_ngay_bat OUT NOCOPY DATE, p_tg_da OUT NOCOPY NUMBER,
    p_tg_con OUT NOCOPY NUMBER, p_ngay_xet_tl OUT NOCOPY DATE
  ) IS
    v_rec t_tinh_an_core_rec;
  BEGIN
    v_rec := get_core_cached(p_id_pham_nhan, p_ngay_xet);
    p_ngay_bat := v_rec.ngay_bat; p_tg_da := v_rec.tg_da;
    p_tg_con := v_rec.tg_con; p_ngay_xet_tl := v_rec.ngay_xet_tl;
  END get_tg_da_va_con;

  -- Wrapper KHÔNG qua cache: g?i th?ng get_core_impl, b? qua DX_CORE_MEMO — dùng cho các FN c?n
  -- giá tr? tính t??i ngay l?p t?c (vd sau khi s?a logic SP_TINH_NGAY_HET_AN_GENERAL mà ch?a/không
  -- mu?n xóa cache; FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY / FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY).
  PROCEDURE get_tg_da_va_con_nocache(
    p_id_pham_nhan IN NUMBER, p_ngay_xet IN DATE,
    p_ngay_bat OUT NOCOPY DATE, p_tg_da OUT NOCOPY NUMBER,
    p_tg_con OUT NOCOPY NUMBER, p_ngay_xet_tl OUT NOCOPY DATE
  ) IS
    v_gen_het   DATE;
    v_gen_blk   PLS_INTEGER;
    v_gen_valid PLS_INTEGER;
    v_da_ma     NVARCHAR2(255);
    v_con_ma    NVARCHAR2(255);
  BEGIN
    get_core_impl(p_id_pham_nhan, p_ngay_xet, p_ngay_bat, p_tg_da, p_tg_con, p_ngay_xet_tl,
                  v_gen_het, v_gen_blk, v_gen_valid, v_da_ma, v_con_ma, p_bo_qua_da_luu => 1);
  END get_tg_da_va_con_nocache;

  FUNCTION get_tinh_an_core_rec(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE
  ) RETURN t_tinh_an_core_rec IS
    v_rec t_tinh_an_core_rec;
  BEGIN
    get_tg_da_va_con(
      p_id_pham_nhan,
      p_ngay_xet,
      v_rec.ngay_bat,
      v_rec.tg_da,
      v_rec.tg_con,
      v_rec.ngay_xet_tl
    );
    RETURN v_rec;
  END get_tinh_an_core_rec;

  -- Helper: format s? ngày thành "X Tháng Y ngày" ho?c "A n?m B tháng C ngày" (dùng ngày b?t làm g?c).
  -- Sau diff_ymd: n?u ph?n ngày >= 30 thì tròn lên 1 tháng (b? ngày; tháng >= 12 bù sang n?m).
  -- B? qua ph?n có giá tr? 0 trong chu?i; khi t?ng th?i gian = 0 thì tr? v? N'0' (không NULL).
  FUNCTION format_tg_from_days(p_ngay_bat DATE, p_so_ngay NUMBER, p_dang NUMBER) RETURN NVARCHAR2 IS
    v_ref DATE := NVL(p_ngay_bat, DATE '1900-01-01');
    v_y NUMBER; v_m NUMBER; v_d NUMBER;
    v_total_thang NUMBER;
  BEGIN
    IF p_so_ngay IS NULL OR p_so_ngay < 0 THEN RETURN NULL; END IF;
    diff_ymd(v_ref, v_ref + p_so_ngay, v_y, v_m, v_d);
    v_y := NVL(v_y, 0);
    v_m := NVL(v_m, 0);
    v_d := NVL(v_d, 0);
    -- Ph?n ngày l? >= 30 ? tròn lên 1 tháng (vd 104 tháng 30 ngày ? 105 tháng; 8 n?m 8 tháng 30 ngày ? 8 n?m 9 tháng)
    IF v_d >= 30 THEN
      v_m := v_m + 1;
      v_d := 0;
      IF v_m >= 12 THEN
        v_y := v_y + TRUNC(v_m / 12);
        v_m := MOD(v_m, 12);
      END IF;
    END IF;
    IF p_dang = 1 THEN
      v_total_thang := NVL(v_y, 0) * 12 + NVL(v_m, 0);
      IF v_total_thang = 0 AND NVL(v_d, 0) = 0 THEN
        RETURN TO_NCHAR(0);
      END IF;
      IF v_total_thang > 0 AND NVL(v_d, 0) > 0 THEN
        RETURN TO_NCHAR(v_total_thang) || u' Th\00e1ng ' || TO_NCHAR(v_d) || u' ng\00e0y';
      ELSIF v_total_thang > 0 THEN
        RETURN TO_NCHAR(v_total_thang) || u' Th\00e1ng';
      ELSE
        RETURN TO_NCHAR(v_d) || u' ng\00e0y';
      END IF;
    ELSE
      RETURN format_nam_thang_ngay_omit_zero(v_y, v_m, v_d);
    END IF;
  END format_tg_from_days;

  -- S? tháng t?ng (làm tròn ngày l? >=30 lên 1 tháng — CÙNG quy t?c format_tg_from_days dùng ??
  -- hi?n th? SNAP_*_TEXT) t? s? ngày k? t? p_ngay_neo. Dùng trong FN_SNAPSHOT_BATCH ?? ghi
  -- SNAP_DA_CH_THANG/SNAP_CON_LAI_THANG — s? chính xác, không ph?i REGEXP l?i chu?i hi?n th?. C? ý
  -- không refactor format_tg_from_days (gi? nguyên hàm g?c ?ã ?úng, tránh r?i ro).
  FUNCTION months_from_days(p_ngay_neo DATE, p_so_ngay NUMBER) RETURN NUMBER IS
    v_ref DATE := NVL(p_ngay_neo, DATE '1900-01-01');
    v_y NUMBER; v_m NUMBER; v_d NUMBER;
  BEGIN
    IF p_ngay_neo IS NULL OR p_so_ngay IS NULL OR p_so_ngay < 0 THEN RETURN NULL; END IF;
    diff_ymd(v_ref, v_ref + p_so_ngay, v_y, v_m, v_d);
    v_y := NVL(v_y, 0); v_m := NVL(v_m, 0); v_d := NVL(v_d, 0);
    IF v_d >= 30 THEN
      v_m := v_m + 1;
      IF v_m >= 12 THEN v_y := v_y + TRUNC(v_m / 12); v_m := MOD(v_m, 12); END IF;
    END IF;
    RETURN v_y * 12 + v_m;
  END months_from_days;

  -- Ph?n thân dùng chung c?a format_da_chap_hanh_text / format_da_chap_hanh_from_core: không
  -- xác ??nh / tg_da=0 / ngày b?t t??ng lai ? N'Không'. Nh?n (ngay_bat, tg_da, ngay_xet_tl) ?ã
  -- l?y s?n (qua cache/nocache ho?c t? p_core) t? caller.
  FUNCTION format_da_chap_hanh_render(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE,
    p_dang         IN NUMBER,
    p_ngay_bat     IN DATE,
    p_tg_da        IN NUMBER,
    p_ngay_xet_tl  IN DATE
  ) RETURN NVARCHAR2 IS
    v_xet DATE := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));
    v_cnt NUMBER;
  BEGIN
    IF p_ngay_bat IS NOT NULL AND TRUNC(p_ngay_bat) > v_xet THEN
      RETURN u'Kh\00f4ng';
    END IF;

    IF p_ngay_bat IS NULL THEN
      BEGIN
        SELECT 1
          INTO v_cnt
          FROM DUAL
         WHERE EXISTS (
                 SELECT 1
                   FROM QLPN.PN_THI_HANH_AN t
                  WHERE t.THA_PNLAI_LICH_ID = p_id_pham_nhan
                    AND NVL(t.IS_DELETED, 0) = 0
                    AND t.THA_NGAY_BAT IS NOT NULL
                    AND TRUNC(t.THA_NGAY_BAT) > v_xet
               );
        RETURN u'Kh\00f4ng';
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          RETURN u'Kh\00f4ng';
      END;
    END IF;

    IF p_tg_da IS NULL OR p_ngay_xet_tl IS NULL THEN
      RETURN u'Kh\00f4ng';
    END IF;

    IF p_tg_da = 0 THEN
      RETURN u'Kh\00f4ng';
    END IF;

    RETURN format_tg_from_days(p_ngay_bat, p_tg_da, p_dang);
  EXCEPTION
    WHEN OTHERS THEN
      RETURN u'Kh\00f4ng';
  END format_da_chap_hanh_render;

  -- Hi?n th? th?i gian ?ã CH: không xác ??nh / tg_da=0 / ngày b?t t??ng lai ? N'Không'
  -- p_bo_qua_cache = 1: b? qua DX_CORE_MEMO, luôn tính t??i qua get_core_impl (dùng b?i
  -- FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY).
  FUNCTION format_da_chap_hanh_text(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE,
    p_dang         IN NUMBER,
    p_bo_qua_cache IN NUMBER DEFAULT 0
  ) RETURN NVARCHAR2 IS
    v_ngay_bat    DATE;
    v_tg_da       NUMBER;
    v_tg_con      NUMBER;
    v_ngay_xet_tl DATE;
  BEGIN
    IF p_bo_qua_cache = 1 THEN
      get_tg_da_va_con_nocache(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    ELSE
      get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    END IF;

    RETURN format_da_chap_hanh_render(p_id_pham_nhan, p_ngay_xet, p_dang, v_ngay_bat, v_tg_da, v_ngay_xet_tl);
  EXCEPTION
    WHEN OTHERS THEN
      RETURN u'Kh\00f4ng';
  END format_da_chap_hanh_text;

  -- format_da_chap_hanh_text v?i core ?ã có (TCDK memo batch).
  FUNCTION format_da_chap_hanh_from_core(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE,
    p_dang         IN NUMBER,
    p_core         IN t_tinh_an_core_rec
  ) RETURN NVARCHAR2 IS
  BEGIN
    RETURN format_da_chap_hanh_render(p_id_pham_nhan, p_ngay_xet, p_dang, p_core.ngay_bat, p_core.tg_da, p_core.ngay_xet_tl);
  EXCEPTION
    WHEN OTHERS THEN
      RETURN u'Kh\00f4ng';
  END format_da_chap_hanh_from_core;

  -- B? d?n h?u t? 0 tháng / 0 ngày ?? kh?p DM_MA_THOI_GIANS.MTG_TITLE (vd danh m?c "1 n?m" vs chu?i tính "1 n?m 0 tháng 0 ngày")
  FUNCTION strip_zero_suffix_nam_thang_ngay(p_text IN NVARCHAR2) RETURN NVARCHAR2 IS
    v NVARCHAR2(4000);
  BEGIN
    IF p_text IS NULL THEN
      RETURN NULL;
    END IF;
    v := TRIM(p_text);
    IF REGEXP_LIKE(v, '^0\s+n?m\s+', 'i') THEN
      RETURN TRIM(REGEXP_REPLACE(v, '^0\s+n?m\s+', '', 1, 0, 'i'));
    END IF;
    IF REGEXP_LIKE(v, '\s+0\s+tháng\s+0\s+ngày\s*$', 'i') THEN
      RETURN TRIM(REGEXP_REPLACE(v, '\s+0\s+tháng\s+0\s+ngày\s*$', '', 1, 0, 'i'));
    END IF;
    IF REGEXP_LIKE(v, '\s+0\s+ngày\s*$', 'i') THEN
      RETURN TRIM(REGEXP_REPLACE(v, '\s+0\s+ngày\s*$', '', 1, 0, 'i'));
    END IF;
    IF REGEXP_LIKE(v, '\s+0\s+tháng\s*$', 'i') THEN
      RETURN TRIM(REGEXP_REPLACE(v, '\s+0\s+tháng\s*$', '', 1, 0, 'i'));
    END IF;
    RETURN v;
  END strip_zero_suffix_nam_thang_ngay;

  FUNCTION lookup_mtg_ma_for_nam_thang_ngay_title(p_tg_text IN NVARCHAR2) RETURN NVARCHAR2 IS
    v_try1 NVARCHAR2(4000);
    v_try2 NVARCHAR2(4000);
    v_try3 NVARCHAR2(4000);
    v_try4 NVARCHAR2(4000);
    v_id   NVARCHAR2(200);
  BEGIN
    IF p_tg_text IS NULL OR TRIM(p_tg_text) IS NULL THEN
      RETURN NULL;
    END IF;

    v_try1 := TRIM(p_tg_text);
    v_try2 := strip_zero_suffix_nam_thang_ngay(v_try1);
    v_try3 := strip_zero_suffix_nam_thang_ngay(v_try2);
    v_try4 := strip_zero_suffix_nam_thang_ngay(v_try3);

    SELECT y.MTG_MA
      INTO v_id
      FROM (
        SELECT dmtg.MTG_MA,
               CASE
                 WHEN UPPER(TRIM(CAST(dmtg.MTG_TITLE AS NVARCHAR2(4000)))) = UPPER(v_try1) THEN 1
                 WHEN UPPER(TRIM(CAST(dmtg.MTG_TITLE AS NVARCHAR2(4000)))) = UPPER(v_try2) THEN 2
                 WHEN UPPER(TRIM(CAST(dmtg.MTG_TITLE AS NVARCHAR2(4000)))) = UPPER(v_try3) THEN 3
                 WHEN UPPER(TRIM(CAST(dmtg.MTG_TITLE AS NVARCHAR2(4000)))) = UPPER(v_try4) THEN 4
                 ELSE 9
               END AS sort_order
          FROM QLPN.DM_MA_THOI_GIANS dmtg
         WHERE NVL(dmtg.IS_DELETED, 0) = 0
           AND (
                UPPER(TRIM(CAST(dmtg.MTG_TITLE AS NVARCHAR2(4000)))) = UPPER(v_try1)
             OR UPPER(TRIM(CAST(dmtg.MTG_TITLE AS NVARCHAR2(4000)))) = UPPER(v_try2)
             OR UPPER(TRIM(CAST(dmtg.MTG_TITLE AS NVARCHAR2(4000)))) = UPPER(v_try3)
             OR UPPER(TRIM(CAST(dmtg.MTG_TITLE AS NVARCHAR2(4000)))) = UPPER(v_try4)
           )
         ORDER BY sort_order, dmtg.MTG_MA
      ) y
     WHERE ROWNUM = 1;
    RETURN v_id;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN NULL;
    WHEN OTHERS THEN
      RETURN NULL;
  END lookup_mtg_ma_for_nam_thang_ngay_title;

  PROCEDURE calc_da_con_ma_tg(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE,
    p_da_ma_tg     OUT NOCOPY NVARCHAR2,
    p_con_ma_tg    OUT NOCOPY NVARCHAR2
  ) IS
    v_core        t_tinh_an_core_rec;
    v_tg_text     NVARCHAR2(200);
  BEGIN
    p_da_ma_tg := NULL;
    p_con_ma_tg := NULL;

    v_core := get_tinh_an_core_rec(p_id_pham_nhan, p_ngay_xet);

    v_tg_text := format_da_chap_hanh_text(p_id_pham_nhan, p_ngay_xet, 2);
    IF v_tg_text IS NOT NULL AND TRIM(v_tg_text) = u'Kh\00f4ng' THEN
      p_da_ma_tg := '000000';
    ELSIF v_tg_text IS NOT NULL THEN
      p_da_ma_tg := lookup_mtg_ma_for_nam_thang_ngay_title(v_tg_text);
    END IF;

    IF v_core.ngay_bat IS NOT NULL AND v_core.tg_con IS NOT NULL AND v_core.ngay_xet_tl IS NOT NULL THEN
      IF v_core.tg_con = 0 THEN
        v_tg_text := u'Kh\00f4ng';
      ELSE
        v_tg_text := format_tg_from_days(v_core.ngay_xet_tl, v_core.tg_con, 2);
      END IF;
      p_con_ma_tg := lookup_mtg_ma_for_nam_thang_ngay_title(v_tg_text);
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      p_da_ma_tg := NULL;
      p_con_ma_tg := NULL;
  END calc_da_con_ma_tg;

  -- B? qua DX_CORE_MEMO — luôn tính t??i qua get_core_impl (không ??c/không ghi cache). ??ng nh?t
  -- v?i FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY (cùng family ?ã CH).
  FUNCTION FN_TINH_THOI_GIAN_DA_CHAP_HANH(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NUMBER IS
    v_ngay_bat DATE; v_tg_da NUMBER; v_tg_con NUMBER; v_ngay_xet_tl DATE;
  BEGIN
    get_tg_da_va_con_nocache(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    -- ??ng b? chu?i Không / MTG_MA 000000: không tr? NULL ra ngoài
    RETURN NVL(v_tg_da, 0);
  EXCEPTION WHEN OTHERS THEN RETURN 0;
  END FN_TINH_THOI_GIAN_DA_CHAP_HANH;

  -- B? qua DX_CORE_MEMO — luôn tính t??i qua get_core_impl (không ??c/không ghi cache).
  FUNCTION FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2 IS
  BEGIN
    RETURN format_da_chap_hanh_text(p_id_pham_nhan, p_ngay_xet, 1, p_bo_qua_cache => 1);
  EXCEPTION WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY;

  -- B? qua DX_CORE_MEMO — luôn tính t??i qua get_core_impl (không ??c/không ghi cache).
  FUNCTION FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2 IS
  BEGIN
    RETURN NVL(format_da_chap_hanh_text(p_id_pham_nhan, p_ngay_xet, 2, p_bo_qua_cache => 1), u'Kh\00f4ng');
  EXCEPTION WHEN OTHERS THEN RETURN u'Kh\00f4ng';
  END FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY;

  FUNCTION FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY_MA_TG(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2 IS
    v_tg_text NVARCHAR2(200);
  BEGIN
    v_tg_text := FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(p_id_pham_nhan, p_ngay_xet);
    IF v_tg_text IS NULL OR TRIM(v_tg_text) = u'Kh\00f4ng' THEN
      RETURN '000000';
    END IF;

    RETURN lookup_mtg_ma_for_nam_thang_ngay_title(v_tg_text);
  END FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY_MA_TG;

  -- B? qua DX_CORE_MEMO — luôn tính t??i qua get_core_impl (không ??c/không ghi cache). ??ng nh?t
  -- v?i FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY (cùng family còn l?i).
  FUNCTION FN_TINH_THOI_GIAN_CON_LAI(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NUMBER IS
    v_ngay_bat DATE; v_tg_da NUMBER; v_tg_con NUMBER; v_ngay_xet_tl DATE;
  BEGIN
    get_tg_da_va_con_nocache(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    RETURN v_tg_con;
  EXCEPTION WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_THOI_GIAN_CON_LAI;

  -- B? qua DX_CORE_MEMO — luôn tính t??i qua get_core_impl (không ??c/không ghi cache).
  FUNCTION FN_TINH_THOI_GIAN_CON_LAI_THANG_NGAY(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2 IS
    v_ngay_bat DATE; v_tg_da NUMBER; v_tg_con NUMBER; v_ngay_xet_tl DATE;
    v_moc_con    DATE;
  BEGIN
    get_tg_da_va_con_nocache(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    IF v_ngay_bat IS NULL OR v_tg_con IS NULL OR v_ngay_xet_tl IS NULL THEN RETURN NULL; END IF;
    IF v_tg_con = 0 THEN
      RETURN u'Kh\00f4ng';
    END IF;
    -- M?c = TRUNC(ngày xét hi?u l?c), kh?p p_tg_con = TRUNC(ngày h?t án) - TRUNC(ngày xét): diff_ymd(xét..xét+con) = diff_ymd(xét..h?t án), tránh tách hai ?o?n t? ngày b?t v?i ngày b?t+tg_da gây c?ng chu?i > án.
    v_moc_con := v_ngay_xet_tl;
    RETURN format_tg_from_days(v_moc_con, v_tg_con, 1);
  EXCEPTION WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_THOI_GIAN_CON_LAI_THANG_NGAY;

  -- B? qua DX_CORE_MEMO — luôn tính t??i qua get_core_impl (không ??c/không ghi cache).
  FUNCTION FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2 IS
    v_ngay_bat DATE; v_tg_da NUMBER; v_tg_con NUMBER; v_ngay_xet_tl DATE;
    v_moc_con    DATE;
  BEGIN
    get_tg_da_va_con_nocache(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    IF v_ngay_bat IS NULL OR v_tg_con IS NULL OR v_ngay_xet_tl IS NULL THEN RETURN NULL; END IF;
    IF v_tg_con = 0 THEN
      RETURN u'Kh\00f4ng';
    END IF;
    v_moc_con := v_ngay_xet_tl;
    RETURN format_tg_from_days(v_moc_con, v_tg_con, 2);
  EXCEPTION WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY;

  -- Th?i gian th? thách THC?K: c? ý KHÔNG dùng get_tg_da_va_con/get_core_impl (?i qua
  -- get_ngay_het_via_general và ?u tiên THA_NGAY_HET_HAN ?ã l?u) — vì v?i ph?m nhân ?ã ???c
  -- duy?t THC?K, THA_NGAY_HET_HAN th??ng ?ã b? ghi ?è b?ng chính ngày tha, khi?n ?i?u ki?n
  -- "THA_NGAY_HET_HAN >= ngày_xét" luôn ?úng và còn l?i luôn ra 0. G?i get_ngay_het_via_general
  -- v?i p_bo_qua_da_tha=1 (b? qua c? RULE 3 l?n B??C 1/KTRT c?a SP_TINH_NGAY_HET_AN_GENERAL) ??
  -- ép tính l?i hoàn toàn t? THA_AN_PHAT_GOC. v_ngay_het_raw/v_blocked ch? dùng ?? xác ??nh
  -- "không xác ??nh ???c" (chung thân/t? hình/còn m? tr?n-T?C-hoãn); giá tr? TR? V? l?y t?
  -- v_tcn/v_tct/v_tcg (= p_tg_con_raw_*, chính là B??C 13 "CON_LAI = Án ph?t g?c ? ?ã ch?p hành
  -- ? Gi?m" c?a SP), neo lên p_ngay_tha b?ng ?úng công th?c Y/M/D->ngày dùng ? parse_ma_tg_to_days
  -- và get_core_impl, thay vì hi?u ngày (v_ngay_het_raw neo trên ngày b?t thi hành án th?t — hi?u
  -- ngày v?i p_ngay_tha không ph?n ánh ?úng "còn l?i" theo ?úng ngh?a B??C 13, và tr??c ?ây còn có
  -- r?i ro b? B??C 1/KTRT ghi ?è b?ng ngày ra tr?i ?ã s?a tay).
  FUNCTION FN_TINH_THOI_GIAN_THU_THACH(
    p_id_pham_nhan IN NUMBER,
    p_ngay_tha     IN DATE
  ) RETURN NUMBER IS
    v_ngay_het     DATE;
    v_ngay_het_raw DATE;
    v_blocked      PLS_INTEGER;
    v_dcn NUMBER; v_dct NUMBER; v_dcg NUMBER;
    v_tcn NUMBER; v_tct NUMBER; v_tcg NUMBER;
  BEGIN
    IF p_id_pham_nhan IS NULL OR p_ngay_tha IS NULL THEN
      RETURN NULL;
    END IF;
    get_ngay_het_via_general(p_id_pham_nhan, TRUNC(p_ngay_tha), v_ngay_het, v_blocked, v_ngay_het_raw,
      v_dcn, v_dct, v_dcg, v_tcn, v_tct, v_tcg, p_bo_qua_da_tha => 1);
    IF v_blocked = 1 OR v_ngay_het_raw IS NULL OR v_tcn IS NULL THEN
      RETURN NULL;
    END IF;
    RETURN GREATEST(0, TRUNC(ADD_MONTHS(TRUNC(p_ngay_tha), v_tcn * 12 + v_tct) + v_tcg) - TRUNC(p_ngay_tha));
  EXCEPTION WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_THOI_GIAN_THU_THACH;

  FUNCTION FN_TINH_THOI_GIAN_THU_THACH_NAM_THANG_NGAY(
    p_id_pham_nhan IN NUMBER,
    p_ngay_tha     IN DATE
  ) RETURN NVARCHAR2 IS
    v_con_lai NUMBER;
  BEGIN
    v_con_lai := FN_TINH_THOI_GIAN_THU_THACH(p_id_pham_nhan, p_ngay_tha);
    IF v_con_lai IS NULL THEN
      RETURN NULL;
    END IF;
    IF v_con_lai = 0 THEN
      RETURN u'Kh\00f4ng';
    END IF;
    RETURN format_tg_from_days(TRUNC(p_ngay_tha), v_con_lai, 2);
  EXCEPTION WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_THOI_GIAN_THU_THACH_NAM_THANG_NGAY;

  FUNCTION FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY_MA_TG(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2 IS
    v_tg_text NVARCHAR2(200);
  BEGIN
    v_tg_text := FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(p_id_pham_nhan, p_ngay_xet);
    IF v_tg_text IS NULL THEN
      RETURN NULL;
    END IF;

    RETURN lookup_mtg_ma_for_nam_thang_ngay_title(v_tg_text);
  END FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY_MA_TG;

  FUNCTION FN_TINH_TONG_THOI_GIAN_GIAM_MA_TG(
    p_id_pham_nhan IN NUMBER
  ) RETURN NVARCHAR2 IS
    v_tg_text NVARCHAR2(4000);
    v_mtg_ma  NVARCHAR2(200);
  BEGIN
    v_tg_text := FN_TINH_TONG_THOI_GIAN_GIAM(p_id_pham_nhan);
    IF v_tg_text IS NULL THEN
      RETURN NULL;
    END IF;
    IF TRIM(v_tg_text) IN (u'0', u'Kh\00f4ng') THEN
      RETURN lookup_mtg_ma_for_nam_thang_ngay_title(u'Kh\00f4ng');
    END IF;

    v_mtg_ma := lookup_mtg_ma_for_nam_thang_ngay_title(v_tg_text);
    IF v_mtg_ma IS NOT NULL THEN
      RETURN v_mtg_ma;
    END IF;

    IF INSTR(v_tg_text, u'; ') > 0 THEN
      RETURN lookup_mtg_ma_for_nam_thang_ngay_title(
        TRIM(SUBSTR(v_tg_text, INSTR(v_tg_text, u'; ', -1) + 2))
      );
    END IF;

    RETURN NULL;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN NULL;
  END FN_TINH_TONG_THOI_GIAN_GIAM_MA_TG;

  FUNCTION FN_TINH_NGAY_THA(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN DATE IS
    v_ngay_bat    DATE;
    v_tg_da       NUMBER;
    v_tg_con      NUMBER;
    v_ngay_xet_tl DATE;
    v_nhh         DATE;
    v_blocked     PLS_INTEGER;
    v_nhh_raw     DATE;
    v_dcn NUMBER; v_dct NUMBER; v_dcg NUMBER;
    v_tcn NUMBER; v_tct NUMBER; v_tcg NUMBER;
  BEGIN
    IF p_id_pham_nhan IS NULL THEN
      RETURN NULL;
    END IF;

    -- p_bo_qua_da_luu=>1: không tin THA_NGAY_HET_HAN ?ã l?u (có th? l?ch d? li?u tính t??i khi
    -- logic GENERAL v?a s?a nh?ng ch?a ch?y l?i SP_UPDATE_THA_TG_PARALLEL_ALL) — v?n tôn tr?ng
    -- PN_KET_THUC_RA_TRAIS bình th??ng (không set p_bo_qua_da_tha).
    get_ngay_het_via_general(p_id_pham_nhan, p_ngay_xet, v_nhh, v_blocked, v_nhh_raw, v_dcn, v_dct, v_dcg, v_tcn, v_tct, v_tcg,
      p_bo_qua_da_luu => 1);
    IF v_blocked = 1 OR v_nhh IS NULL THEN
      RETURN NULL;
    END IF;

    get_tg_da_va_con_nocache(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    IF v_ngay_bat IS NULL OR v_tg_da IS NULL OR v_ngay_xet_tl IS NULL THEN
      RETURN NULL;
    END IF;

    RETURN TRUNC(v_nhh);

  EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_NGAY_THA;

  FUNCTION FN_DA_CHAP_HANH_DAT_TY_LE(
    p_id_pham_nhan IN NUMBER,
    p_ratio        IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NUMBER IS
    v_ngay_bat    DATE;
    v_tg_da       NUMBER;
    v_tg_con      NUMBER;
    v_ngay_xet_tl DATE;
    v_ngay_het    DATE;
    v_an_phat     NVARCHAR2(2000);
    v_tong_thang  NUMBER;
    v_ngay_nguong DATE;
    v_ap_n NUMBER := 0; v_ap_t NUMBER := 0; v_ap_g NUMBER := 0;
  BEGIN
    IF p_id_pham_nhan IS NULL OR p_ratio IS NULL OR p_ratio <= 0 THEN
      RETURN NULL;
    END IF;

    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    IF v_ngay_bat IS NULL OR v_tg_da IS NULL OR v_tg_con IS NULL THEN
      RETURN NULL;
    END IF;

    v_an_phat  := get_tha_an_phat_priv(p_id_pham_nhan, p_ngay_xet);
    v_ngay_het := get_ngay_het_cached(p_id_pham_nhan, v_ngay_bat, v_an_phat, p_ngay_xet);
    IF v_ngay_het IS NULL THEN
      RETURN NULL;
    END IF;

    -- T?ng tháng án ph?t (n?m*12+tháng, b? ph?n ngày l?) — parse tr?c ti?p t? án ph?t, ??ng b?
    -- v?i eval_dieu_kien_thoi_gian (KHÔNG dùng ROUND(MONTHS_BETWEEN(...)) n?a vì làm tròn/?ánh
    -- m?t ph?n ngày l?, có th? cho k?t qu? khác eval_dieu_kien_thoi_gian v?i cùng PN/t? l?).
    sum_ymd_text(v_an_phat, v_ap_n, v_ap_t, v_ap_g);
    v_tong_thang := v_ap_n * 12 + v_ap_t;
    IF v_tong_thang IS NULL OR v_tong_thang <= 0 THEN
      RETURN NULL;
    END IF;

    v_ngay_nguong := calc_nguong_date(v_ngay_bat, v_tong_thang, p_ratio);

    -- Ngày ?ã ??t >= ngày ng??ng (b?t 14/09, ng??ng 14/03 ? 13/03 ch?a ??t)
    IF TRUNC(v_ngay_bat + v_tg_da) >= TRUNC(v_ngay_nguong) THEN
      RETURN 1;
    ELSE
      RETURN 0;
    END IF;

  EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
  END FN_DA_CHAP_HANH_DAT_TY_LE;

  FUNCTION FN_DA_CHAP_HANH_DAT_SO_NAM(
    p_id_pham_nhan IN NUMBER,
    p_so_nam       IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NUMBER IS
    v_ngay_bat    DATE;
    v_tg_da       NUMBER;
    v_tg_con      NUMBER;
    v_ngay_xet_tl DATE;
    v_y NUMBER; v_m NUMBER; v_d NUMBER;
  BEGIN
    IF p_id_pham_nhan IS NULL OR p_so_nam IS NULL OR p_so_nam <= 0 THEN
      RETURN NULL;
    END IF;

    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    -- v_tg_con NULL (vd ?ang b? ch?n m? T?C/hoãn/tr?n) ? v_tg_da khi ?ó ch? là span thô, ch?a
    -- tr? T?C ?óng/c?ng t?m giam ??y ?? — không ?? tin c?y ?? k?t lu?n ??t/không ??t.
    IF v_ngay_bat IS NULL OR v_tg_da IS NULL OR v_tg_con IS NULL THEN
      RETURN NULL;
    END IF;

    -- So n?m/tháng/ngày tr?c ti?p — CÙNG diff_ymd + quy t?c tròn >=30 ngày mà
    -- format_tg_from_days dùng ?? hi?n th? FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY, ??m
    -- b?o "?? N n?m" luôn kh?p v?i n?m hi?n th? cho ng??i dùng.
    diff_ymd(v_ngay_bat, v_ngay_bat + v_tg_da, v_y, v_m, v_d);
    v_y := NVL(v_y, 0); v_m := NVL(v_m, 0); v_d := NVL(v_d, 0);
    IF v_d >= 30 THEN
      v_m := v_m + 1;
      IF v_m >= 12 THEN
        v_y := v_y + TRUNC(v_m / 12);
      END IF;
    END IF;

    IF v_y >= p_so_nam THEN
      RETURN 1;
    END IF;

    RETURN 0;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN NULL;
  END FN_DA_CHAP_HANH_DAT_SO_NAM;

  FUNCTION eval_dieu_kien_thoi_gian(
    p_is_chung_than_giam IN NUMBER,
    p_is_chung_than_ctg  IN NUMBER,
    p_is_doi_tuong_db    IN NUMBER,
    p_ngay_bat           IN DATE,
    p_tg_da              IN NUMBER,
    p_tg_con             IN NUMBER,
    p_ngay_het           IN DATE,
    -- T?ng s? tháng án ph?t (n?m*12+tháng, ?ã b? ph?n ngày l?) — do caller parse s?n t? án ph?t
    -- (sum_ymd_text) và truy?n vào; KHÔNG suy ng??c t? ROUND(MONTHS_BETWEEN(p_ngay_het,p_ngay_bat))
    -- n?a vì cách ?ó làm tròn/?ánh m?t ph?n ngày l? c?a án khi tính ng??ng 1/3, 1/2.
    p_tong_thang_an      IN NUMBER
  ) RETURN NUMBER IS
    v_tong_thang NUMBER;
    v_dat_12     NUMBER := 0;
    v_dat_15     NUMBER := 0;
    v_dat_1_2    NUMBER := 0;
    v_dat_1_3    NUMBER := 0;
    v_y NUMBER; v_m NUMBER; v_d NUMBER;
  BEGIN
    IF NVL(p_is_chung_than_ctg, 0) = 1 THEN RETURN 3; END IF;
    -- p_tg_con NULL (vd ?ang b? ch?n m? T?C/hoãn/tr?n) ? p_tg_da khi ?ó ch? là span thô, ch?a
    -- tr? T?C ?óng/c?ng t?m giam ??y ?? — không ?? tin c?y ?? k?t lu?n ??/không ?? ?i?u ki?n
    -- (??ng b? FN_DA_CHAP_HANH_DAT_SO_NAM/TY_LE).
    IF p_ngay_bat IS NULL OR p_tg_da IS NULL OR p_tg_con IS NULL THEN RETURN 3; END IF;

    IF NVL(p_is_chung_than_giam, 0) = 1 THEN
      -- So n?m/tháng/ngày tr?c ti?p (diff_ymd + quy t?c tròn >=30 ngày mà format_tg_from_days
      -- dùng ?? hi?n th?) thay vì ng??ng-s?-ngày qua ADD_MONTHS — ??ng b?
      -- FN_DA_CHAP_HANH_DAT_SO_NAM, ??m b?o "?? N n?m" kh?p v?i n?m hi?n th? cho ng??i dùng.
      diff_ymd(p_ngay_bat, p_ngay_bat + p_tg_da, v_y, v_m, v_d);
      v_y := NVL(v_y, 0); v_m := NVL(v_m, 0); v_d := NVL(v_d, 0);
      IF v_d >= 30 THEN
        v_m := v_m + 1;
        IF v_m >= 12 THEN
          v_y := v_y + TRUNC(v_m / 12);
        END IF;
      END IF;
      IF v_y >= 12 THEN v_dat_12 := 1; END IF;
      IF v_y >= 15 THEN v_dat_15 := 1; END IF;
      IF NVL(p_is_doi_tuong_db, 0) = 1 AND v_dat_12 = 1 THEN RETURN 2; END IF;
      IF v_dat_15 = 1 THEN RETURN 1; END IF;
      RETURN 3;
    END IF;

    IF p_ngay_het IS NULL THEN RETURN 3; END IF;   -- gi? gate an toàn: ch?a xác ??nh ngày h?t án

    v_tong_thang := p_tong_thang_an;
    IF v_tong_thang IS NULL OR v_tong_thang <= 0 THEN RETURN 3; END IF;

    IF TRUNC(p_ngay_bat + p_tg_da) >= TRUNC(calc_nguong_date(p_ngay_bat, v_tong_thang, 1/3)) THEN v_dat_1_3 := 1; END IF;
    IF TRUNC(p_ngay_bat + p_tg_da) >= TRUNC(calc_nguong_date(p_ngay_bat, v_tong_thang, 0.5)) THEN v_dat_1_2 := 1; END IF;

    IF NVL(p_is_doi_tuong_db, 0) = 1 AND v_dat_1_3 = 1 THEN RETURN 2; END IF;
    IF v_dat_1_2 = 1 THEN RETURN 1; END IF;
    RETURN 3;
  END eval_dieu_kien_thoi_gian;

  FUNCTION FN_GET_DIEU_KIEN_THOI_GIAN(
    p_id_pham_nhan       IN NUMBER,
    p_ngay_xet           IN DATE,
    p_is_chung_than_giam IN NUMBER,
    p_is_chung_than_ctg  IN NUMBER,
    p_is_doi_tuong_db    IN NUMBER
  ) RETURN NUMBER IS
    v_ngay_bat    DATE;
    v_tg_da       NUMBER;
    v_tg_con      NUMBER;
    v_ngay_xet_tl DATE;
    v_an_phat     NVARCHAR2(2000);
    v_ngay_het    DATE;
    v_ap_n NUMBER := 0; v_ap_t NUMBER := 0; v_ap_g NUMBER := 0;
  BEGIN
    IF NVL(p_is_chung_than_ctg, 0) = 1 THEN RETURN 3; END IF;
    IF p_id_pham_nhan IS NULL THEN RETURN 3; END IF;

    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);

    IF NVL(p_is_chung_than_giam, 0) = 1 THEN
      v_ngay_het := NULL;
    ELSE
      v_an_phat  := get_tha_an_phat_priv(p_id_pham_nhan, p_ngay_xet);
      v_ngay_het := get_ngay_het_cached(p_id_pham_nhan, v_ngay_bat, v_an_phat, p_ngay_xet);
      sum_ymd_text(v_an_phat, v_ap_n, v_ap_t, v_ap_g);
    END IF;

    RETURN eval_dieu_kien_thoi_gian(
      p_is_chung_than_giam, p_is_chung_than_ctg, p_is_doi_tuong_db,
      v_ngay_bat, v_tg_da, v_tg_con, v_ngay_het, v_ap_n * 12 + v_ap_t
    );
  EXCEPTION
    WHEN OTHERS THEN RETURN 3;
  END FN_GET_DIEU_KIEN_THOI_GIAN;

  FUNCTION FN_GET_CHI_TIET_THOI_GIAN_THI_HANH(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN QLPN.TYP_TINH_AN_CHI_TIET_TBL PIPELINED IS
    v_ngay_xet DATE;
    v_ngay_ra_trai DATE;
    v_ngay_mo_chan DATE;
    v_ngay_bat DATE;
  BEGIN
    IF p_id_pham_nhan IS NULL THEN
      RETURN;
    END IF;

    v_ngay_xet := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));

    -- L?y ngày b?t + ngày h?t h?n t? THA ??i di?n tr??c khi cap T?C (cùng logic get_core_impl)
    BEGIN
      SELECT TRUNC(tha.ngay_bat), tha.THA_NGAY_HET_HAN
        INTO v_ngay_bat, v_ngay_ra_trai
        FROM (
          SELECT t.THA_NGAY_BAT AS ngay_bat,
                 t.THA_NGAY_HET_HAN,
                 ROW_NUMBER() OVER (ORDER BY t.THA_NGAY_BAT DESC) AS rn
            FROM QLPN.PN_THI_HANH_AN t
           WHERE t.THA_PNLAI_LICH_ID = p_id_pham_nhan
             AND NVL(t.IS_DELETED, 0) = 0
             AND t.THA_NGAY_BAT IS NOT NULL
             AND t.THA_NGAY_BAT < v_ngay_xet + 1
        ) tha
       WHERE tha.rn = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_ngay_bat := NULL;
        v_ngay_ra_trai := NULL;
    END;

    IF v_ngay_bat IS NULL THEN
      RETURN;
    END IF;

    -- Tr?n/hoãn/T?C m?: cap t?i ngày m? (??ng b? get_core_impl)
    v_ngay_mo_chan := get_ngay_mo_chan_priv(p_id_pham_nhan, v_ngay_xet, v_ngay_bat);

    IF v_ngay_mo_chan IS NOT NULL THEN
      v_ngay_xet := LEAST(v_ngay_xet, v_ngay_mo_chan);
    END IF;

    -- PN ch?t / chuy?n giao / h?y án tr? t? do: chi ti?t THA tính ??n ngày k?t thúc (??ng b? get_core_impl)
    DECLARE
      v_ngay_chet DATE;
      v_ngay_chuyen_giao DATE;
      v_ngay_huy_an DATE;
    BEGIN
      v_ngay_chet := get_ngay_chet_priv(p_id_pham_nhan, v_ngay_xet, v_ngay_bat);
      IF v_ngay_chet IS NOT NULL THEN
        v_ngay_xet := LEAST(v_ngay_xet, v_ngay_chet);
      END IF;
      v_ngay_chuyen_giao := get_ngay_chuyen_giao_priv(p_id_pham_nhan, v_ngay_xet, v_ngay_bat);
      IF v_ngay_chuyen_giao IS NOT NULL THEN
        v_ngay_xet := LEAST(v_ngay_xet, v_ngay_chuyen_giao);
      END IF;
      v_ngay_huy_an := get_ngay_huy_an_priv(p_id_pham_nhan, v_ngay_xet, v_ngay_bat);
      IF v_ngay_huy_an IS NOT NULL THEN
        v_ngay_xet := LEAST(v_ngay_xet, v_ngay_huy_an);
      END IF;
    END;

    -- THA_NGAY_HET_HAN ?ã qua: ch? cap khi ch?a b? ch?n m? (??ng b? get_core_impl)
    IF v_ngay_mo_chan IS NULL AND v_ngay_ra_trai IS NOT NULL THEN
      v_ngay_ra_trai := TRUNC(v_ngay_ra_trai);
      IF v_ngay_ra_trai < v_ngay_xet THEN
        v_ngay_xet := v_ngay_ra_trai;
      ELSE
        v_ngay_ra_trai := NULL;
      END IF;
    END IF;

    FOR rec IN (
      SELECT LOAI, TU_NGAY, DEN_NGAY, SO_NGAY, THU_TU
        FROM (
          SELECT u'NG\00c0Y B\1eaeT' AS LOAI, v_ngay_bat AS TU_NGAY, v_ngay_bat AS DEN_NGAY, NULL AS SO_NGAY, 1 AS THU_TU FROM DUAL
          UNION ALL
          SELECT u'T\1ea0M \0110\00ccNH CH\1ec8',
                 TRUNC(GREATEST(td.TU_NGAY, v_ngay_bat)),
                 TRUNC(LEAST(NVL(td.NGAY_LAI, v_ngay_xet), v_ngay_xet)),
                 GREATEST(0, TRUNC(LEAST(NVL(td.NGAY_LAI, v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(td.TU_NGAY, v_ngay_bat)) + 1),
                 2
            FROM QLPN.TAM_DINH_CHIS td
           WHERE td.PHAM_NHAN_ID = p_id_pham_nhan AND NVL(td.IS_DELETED, 0) = 0 AND td.TU_NGAY IS NOT NULL
             AND NOT EXISTS (
                   SELECT 1
                     FROM QLPN.DM_TINH_TRANG_TAM_DINH_CHIES tt
                    WHERE tt.ID = td.TINH_TRANG_ID
                      AND TRIM(CAST(tt.TTTDC_TEN AS NVARCHAR2(4000))) = u'Gia h\1ea1n'
                 )
             AND td.TU_NGAY <= v_ngay_xet AND (td.NGAY_LAI IS NULL OR td.NGAY_LAI >= v_ngay_bat)
          UNION ALL
          SELECT u'HO\00c3N',
                 TRUNC(GREATEST(h.NGAY_HOAN, v_ngay_bat)),
                 TRUNC(LEAST(NVL(h.NGAY_THI_HANH_AN, v_ngay_xet), v_ngay_xet)),
                 GREATEST(0, TRUNC(LEAST(NVL(h.NGAY_THI_HANH_AN, v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(h.NGAY_HOAN, v_ngay_bat)) + 1),
                 3
            FROM QLPN.HOAN_THI_HANH_ANS h
           WHERE h.PHAM_NHAN_ID = p_id_pham_nhan AND NVL(h.IS_DELETED, 0) = 0 AND h.NGAY_HOAN IS NOT NULL
             AND h.NGAY_HOAN <= v_ngay_xet AND (h.NGAY_THI_HANH_AN IS NULL OR h.NGAY_THI_HANH_AN >= v_ngay_bat)
          UNION ALL
          SELECT u'TRICH XUAT',
                 TRUNC(GREATEST(tx.TX_NGAY_TRICH_XUAT, v_ngay_bat)),
                 TRUNC(LEAST(NVL(tx.TX_NGAY_TRA, v_ngay_xet), v_ngay_xet)),
                 GREATEST(0, TRUNC(LEAST(NVL(tx.TX_NGAY_TRA, v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(tx.TX_NGAY_TRICH_XUAT, v_ngay_bat)) + 1),
                 4
            FROM QLPN.TRICH_XUATS tx
           WHERE tx.PHAM_NHAN_ID = p_id_pham_nhan
             AND NVL(tx.IS_DELETED, 0) = 0
             AND EXISTS (
                   SELECT 1
                     FROM QLPN.DM_LOAI_QUYET_DINH_TRICH_XUATS lq
                    WHERE lq.ID = tx.TX_LOAI_LENH_ID
                      AND NVL(lq.IS_DELETED, 0) = 0
                      AND TRIM(CAST(lq.LQDTX_TEN AS NVARCHAR2(4000))) = u'L\1ec7nh tr\00edch xu\1ea5t'
                 )
             AND tx.TX_NGAY_TRICH_XUAT IS NOT NULL
             AND tx.TX_NGAY_TRICH_XUAT <= v_ngay_xet
             AND (tx.TX_NGAY_TRA IS NULL OR tx.TX_NGAY_TRA >= v_ngay_bat)
          UNION ALL
          SELECT u'TR\1ed0N',
                 TRUNC(GREATEST(tt.NGAY_TRON, v_ngay_bat)),
                 TRUNC(LEAST(NVL(tt.NGAY_BAT_LAI, v_ngay_xet), v_ngay_xet)),
                 CASE
                   WHEN tt.NGAY_BAT_LAI IS NOT NULL THEN GREATEST(0, TRUNC(LEAST(tt.NGAY_BAT_LAI, v_ngay_xet)) - TRUNC(GREATEST(tt.NGAY_TRON, v_ngay_bat)) + 1)
                   ELSE CASE WHEN tt.NGAY_TRON <= v_ngay_xet THEN GREATEST(0, v_ngay_xet - TRUNC(GREATEST(tt.NGAY_TRON, v_ngay_bat)) + 1) ELSE 0 END
                 END,
                 5
            FROM QLPN.TRON_TRAIS tt
           WHERE tt.PHAM_NHAN_ID = p_id_pham_nhan AND NVL(tt.IS_DELETED, 0) = 0 AND tt.NGAY_TRON IS NOT NULL
             AND tt.NGAY_TRON <= v_ngay_xet AND (tt.NGAY_BAT_LAI IS NULL OR tt.NGAY_BAT_LAI >= v_ngay_bat)
          UNION ALL
          SELECT u'H\1ee6Y \00c1N',
                 TRUNC(GREATEST(hu.NGAY_TRA_TU_DO, v_ngay_bat)),
                 TRUNC(LEAST(NVL(hu.NGAY_TRO_LAI, v_ngay_xet), v_ngay_xet)),
                 GREATEST(0, TRUNC(LEAST(NVL(hu.NGAY_TRO_LAI, v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(hu.NGAY_TRA_TU_DO, v_ngay_bat)) + 1),
                 6
            FROM QLPN.HUY_ANS hu
           WHERE hu.PHAM_NHAN_ID = p_id_pham_nhan AND NVL(hu.IS_DELETED, 0) = 0 AND hu.NGAY_TRA_TU_DO IS NOT NULL
             AND hu.NGAY_TRA_TU_DO <= v_ngay_xet AND (hu.NGAY_TRO_LAI IS NULL OR hu.NGAY_TRO_LAI >= v_ngay_bat)
        )
       ORDER BY THU_TU, TU_NGAY
    ) LOOP
      PIPE ROW (QLPN.TYP_TINH_AN_CHI_TIET(rec.LOAI, rec.TU_NGAY, rec.DEN_NGAY, rec.SO_NGAY, rec.THU_TU));
    END LOOP;
    RETURN;

  EXCEPTION
    WHEN OTHERS THEN
      RAISE;
  END FN_GET_CHI_TIET_THOI_GIAN_THI_HANH;

  FUNCTION FN_GET_MUC_AN_ID_TU_AN_PHAT(
    p_tha_an_phat IN NVARCHAR2
  ) RETURN NUMBER IS
    v_upper NVARCHAR2(4000);
    v_norm  NVARCHAR2(4000);
    v_n     NUMBER;
    v_t     NUMBER;
    v_g     NUMBER;
    v_thang NUMBER;
    v_id    NUMBER;
    v_is_ct BOOLEAN;
  BEGIN
    IF p_tha_an_phat IS NULL OR TRIM(p_tha_an_phat) IS NULL THEN
      RETURN NULL;
    END IF;

    -- Hai tr??ng h?p ??c bi?t: so kh?p sau LOWER+TRIM (không dùng REGEXP — tránh PLS-00103 trên m?t s? b?n Oracle)
    v_norm := LOWER(TRIM(p_tha_an_phat));
    IF v_norm = u'chung th\00e2n gi\1ea3m xu\1ed1ng 20 n\0103m' THEN
      v_thang := 240;
      SELECT MIN(ma.ID)
        INTO v_id
        FROM QLPN.DM_MUC_ANS ma
       WHERE NVL(ma.IS_DELETED, 0) = 0
         AND ma.MA_TU < 900000
         AND v_thang >= ma.MA_TU
         AND v_thang <= ma.MA_DEN;
      RETURN v_id;
    END IF;
    IF v_norm = u'chung th\00e2n gi\1ea3m xu\1ed1ng 30 n\0103m' THEN
      v_thang := 360;
      SELECT MIN(ma.ID)
        INTO v_id
        FROM QLPN.DM_MUC_ANS ma
       WHERE NVL(ma.IS_DELETED, 0) = 0
         AND ma.MA_TU < 900000
         AND v_thang >= ma.MA_TU
         AND v_thang <= ma.MA_DEN;
      RETURN v_id;
    END IF;

    v_upper := UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(p_tha_an_phat), u'')));
    v_is_ct := v_upper LIKE '%' || 'CHUNGTHAN' || '%'
               AND v_upper NOT LIKE '%' || 'GIAMXUONG' || '%';

    IF v_is_ct THEN
      SELECT MIN(ma.ID)
        INTO v_id
        FROM QLPN.DM_MUC_ANS ma
       WHERE NVL(ma.IS_DELETED, 0) = 0
         AND ma.MA_TU >= 900000;
      RETURN v_id;
    END IF;

    v_n := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'NAM'), 0);
    v_t := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'THANG'), 0);
    v_g := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'NGAY'), 0);
    v_thang := v_n * 12 + v_t + v_g / 30;

    SELECT MIN(ma.ID)
      INTO v_id
      FROM QLPN.DM_MUC_ANS ma
     WHERE NVL(ma.IS_DELETED, 0) = 0
       AND ma.MA_TU < 900000
       AND v_thang >= ma.MA_TU
       AND v_thang <= ma.MA_DEN;

    RETURN v_id;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN NULL;
  END FN_GET_MUC_AN_ID_TU_AN_PHAT;

  -- =============================================================================
  -- Private helper: x? lý batch cho m?t range THA_PNLAI_LICH_ID.
  -- p_id_min/p_id_max = NULL ? không gi?i h?n (x? lý t?t c?).
  -- p_id_min = p_id_max = X  ? single prisoner.
  -- p_serving_only = TRUE  ? ch? TTPN_MA 111–114 (PN ?ang ch?p hành).
  -- p_serving_only = FALSE ? m?i THA (backfill toàn DB, cursor không join DM_TINH_TRANG).
  -- =============================================================================
  PROCEDURE do_batch_range(
    p_id_min       IN NUMBER,
    p_id_max       IN NUMBER,
    p_serving_only IN BOOLEAN,
    p_ok           IN OUT NUMBER,
    p_err          IN OUT NUMBER
  ) IS
    BATCH_SIZE CONSTANT PLS_INTEGER := 2000;

    TYPE t_rowid_arr IS TABLE OF UROWID        INDEX BY PLS_INTEGER;
    TYPE t_nv_arr    IS TABLE OF NVARCHAR2(200) INDEX BY PLS_INTEGER;
    TYPE t_num_arr   IS TABLE OF NUMBER         INDEX BY PLS_INTEGER;

    v_rowids t_rowid_arr;
    v_das    t_nv_arr;
    v_cons   t_nv_arr;
    v_giams  t_nv_arr;
    v_mucs   t_num_arr;

    v_da   NVARCHAR2(200);
    v_con  NVARCHAR2(200);
    v_giam NVARCHAR2(200);
    v_i    PLS_INTEGER := 0;

    PROCEDURE flush_batch IS
    BEGIN
      IF v_i = 0 THEN RETURN; END IF;
      FORALL j IN 1..v_i SAVE EXCEPTIONS
        UPDATE QLPN.PN_THI_HANH_AN t
           SET t.THA_THOI_GIAN_DA_CHAP_HANH = v_das(j),
               t.THA_THOI_GIAN_CON_LAI      = v_cons(j),
               t.THA_THOI_GIAN_DA_GIAM      = v_giams(j),
               t.THA_MUC_AN_ID              = v_mucs(j),
               t.LAST_MODIFICATION_TIME     = SYSTIMESTAMP
         WHERE t.ROWID = v_rowids(j);
      p_ok := p_ok + SQL%ROWCOUNT;
      COMMIT;
      v_i := 0;
      v_rowids.DELETE; v_das.DELETE; v_cons.DELETE; v_giams.DELETE; v_mucs.DELETE;
    END flush_batch;

    PROCEDURE append_row(
      p_rid       IN UROWID,
      p_pn_id     IN NUMBER,
      p_an_phat   IN NVARCHAR2
    ) IS
      v_idx PLS_INTEGER;
    BEGIN
      calc_da_con_ma_tg(p_pn_id, SYSDATE, v_da, v_con);
      v_giam := FN_TINH_TONG_THOI_GIAN_GIAM_MA_TG(p_pn_id);
      v_idx := v_i + 1;
      v_rowids(v_idx) := p_rid;
      v_das(v_idx)    := v_da;
      v_cons(v_idx)   := v_con;
      v_giams(v_idx)  := v_giam;
      v_mucs(v_idx)   := FN_GET_MUC_AN_ID_TU_AN_PHAT(TO_NCHAR(p_an_phat));
      v_i := v_idx;
      IF v_i >= BATCH_SIZE THEN
        flush_batch;
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        p_err := p_err + 1;
        DBMS_OUTPUT.PUT_LINE(
          u'[do_batch_range] Th\1ea5t b\1ea1i THA_PNLAI_LICH_ID=' ||
          TO_NCHAR(p_pn_id) || u': ' || SQLERRM
        );
    END append_row;

  BEGIN
    -- Không g?i FN trong m?nh ?? SET c?a UPDATE cùng b?ng PN_THI_HANH_AN mà hàm c?ng ??c b?ng này:
    -- trong ng? c?nh SQL có th? gây l?i/NULL; tính MTG_MA trong PL/SQL r?i gán scalar.
    IF p_serving_only THEN
      FOR r IN (
        SELECT t.ROWID AS rid,
               t.THA_PNLAI_LICH_ID AS pn_id,
               t.THA_AN_PHAT       AS tha_an_phat
          FROM QLPN.PN_THI_HANH_AN t
          INNER JOIN QLPN.PN_LAI_LICHS pll
                  ON pll.ID = t.THA_PNLAI_LICH_ID
                 AND NVL(pll.IS_DELETED, 0) = 0
          INNER JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
                  ON ttpn.ID = pll.LL_TINH_TRANG_ID
                 AND NVL(ttpn.IS_DELETED, 0) = 0
         WHERE NVL(t.IS_DELETED, 0) = 0
           AND t.THA_PNLAI_LICH_ID IS NOT NULL
           AND ttpn.TTPN_MA IN ('111', '112', '113', '114')
           AND (p_id_min IS NULL OR t.THA_PNLAI_LICH_ID >= p_id_min)
           AND (p_id_max IS NULL OR t.THA_PNLAI_LICH_ID <= p_id_max)
      ) LOOP
        append_row(r.rid, r.pn_id, r.tha_an_phat);
      END LOOP;
    ELSE
      -- Backfill toàn DB: b? join DM_TINH_TRANG (gi?m I/O); ch? l?c THA + lý l?ch còn hi?u l?c.
      FOR r IN (
        SELECT t.ROWID AS rid,
               t.THA_PNLAI_LICH_ID AS pn_id,
               t.THA_AN_PHAT       AS tha_an_phat
          FROM QLPN.PN_THI_HANH_AN t
          INNER JOIN QLPN.PN_LAI_LICHS pll
                  ON pll.ID = t.THA_PNLAI_LICH_ID
                 AND NVL(pll.IS_DELETED, 0) = 0
         WHERE NVL(t.IS_DELETED, 0) = 0
           AND t.THA_PNLAI_LICH_ID IS NOT NULL
           AND (p_id_min IS NULL OR t.THA_PNLAI_LICH_ID >= p_id_min)
           AND (p_id_max IS NULL OR t.THA_PNLAI_LICH_ID <= p_id_max)
      ) LOOP
        append_row(r.rid, r.pn_id, r.tha_an_phat);
      END LOOP;
    END IF;
    flush_batch;
  END do_batch_range;

  -- =============================================================================
  -- Public SP (backward-compatible): single ID ho?c t?t c? b?n ghi (p_tha_pnlai_lich_id=NULL)
  -- =============================================================================
  PROCEDURE SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI(
    p_tha_pnlai_lich_id IN NUMBER,
    p_thong_bao         OUT NVARCHAR2
  ) IS
    v_ok  NUMBER := 0;
    v_err NUMBER := 0;
  BEGIN
    p_thong_bao := u'0';
    -- NULL ? c? hai bound NULL ? x? lý t?t c?; X ? bound [X,X] ? single prisoner
    do_batch_range(
      p_id_min       => p_tha_pnlai_lich_id,
      p_id_max       => p_tha_pnlai_lich_id,
      p_serving_only => TRUE,
      p_ok           => v_ok,
      p_err          => v_err
    );
    IF v_err = 0 THEN
      p_thong_bao := u'1';
      DBMS_OUTPUT.PUT_LINE(
        u'[SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI] Th\00e0nh c\00f4ng: \0111\00e3 c\1eadp nh\1eadt ' ||
        TO_NCHAR(v_ok) || u' b\1ea3n ghi PN_THI_HANH_AN (THA_THOI_GIAN_DA_CHAP_HANH, THA_THOI_GIAN_CON_LAI, THA_THOI_GIAN_DA_GIAM, THA_MUC_AN_ID).'
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        u'[SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI] Ho\00e0n th\00e0nh c\00f3 l\1ed7i: th\00e0nh c\00f4ng ' ||
        TO_NCHAR(v_ok) || u' b\1ea3n ghi, l\1ed7i ' || TO_NCHAR(v_err) ||
        u' b\1ea3n ghi (xem t\1eebng d\00f2ng ph\00eda tr\00ean).'
      );
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      p_thong_bao := u'0';
      DBMS_OUTPUT.PUT_LINE(
        u'[SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI] Th\1ea5t b\1ea1i to\00e0n procedure: ' || SQLERRM
      );
      RAISE;
  END SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI;

  -- =============================================================================
  -- Range overload: g?i t? DBMS_PARALLEL_EXECUTE v?i :start_id / :end_id
  -- =============================================================================
  PROCEDURE SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI(
    p_id_min    IN NUMBER,
    p_id_max    IN NUMBER,
    p_thong_bao OUT NVARCHAR2
  ) IS
    v_ok  NUMBER := 0;
    v_err NUMBER := 0;
  BEGIN
    p_thong_bao := u'0';
    do_batch_range(
      p_id_min       => p_id_min,
      p_id_max       => p_id_max,
      p_serving_only => TRUE,
      p_ok           => v_ok,
      p_err          => v_err
    );
    IF v_err = 0 THEN
      p_thong_bao := u'1';
    END IF;
    DBMS_OUTPUT.PUT_LINE(
      u'[SP_UPDATE range ' || TO_NCHAR(p_id_min) || u'-' || TO_NCHAR(p_id_max) ||
      u'] ok=' || TO_NCHAR(v_ok) || u' err=' || TO_NCHAR(v_err)
    );
  EXCEPTION
    WHEN OTHERS THEN
      p_thong_bao := u'0';
      DBMS_OUTPUT.PUT_LINE(
        u'[SP_UPDATE range ' || TO_NCHAR(p_id_min) || u'-' || TO_NCHAR(p_id_max) ||
        u'] Exception: ' || SQLERRM
      );
      RAISE;
  END SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI;

  -- =============================================================================
  -- Parallel orchestrator: t? ??ng chia chunk và ch?y song song
  -- =============================================================================
  -- Helper dùng chung cho c? 2 parallel procedure
  PROCEDURE run_parallel_impl(
    p_task_name      IN VARCHAR2,
    p_sql            IN VARCHAR2,
    p_parallel_level IN PLS_INTEGER,
    p_chunk_size     IN NUMBER,
    p_thong_bao      OUT NVARCHAR2
  ) IS
    v_status NUMBER;
  BEGIN
    p_thong_bao := u'0';

    BEGIN
      DBMS_PARALLEL_EXECUTE.DROP_TASK(p_task_name);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;

    DBMS_PARALLEL_EXECUTE.CREATE_TASK(p_task_name);

    -- :start_id / :end_id là bind variables do DBMS_PARALLEL_EXECUTE t? inject per chunk
    DBMS_PARALLEL_EXECUTE.CREATE_CHUNKS_BY_NUMBER_COL(
      task_name    => p_task_name,
      table_owner  => 'QLPN',
      table_name   => 'PN_THI_HANH_AN',
      table_column => 'THA_PNLAI_LICH_ID',
      chunk_size   => p_chunk_size
    );

    DBMS_OUTPUT.PUT_LINE(
      u'[' || p_task_name || u'] B\1eaft \0111\1ea7u. parallel_level=' || p_parallel_level ||
      u' chunk_size=' || p_chunk_size
    );

    DBMS_PARALLEL_EXECUTE.RUN_TASK(
      task_name      => p_task_name,
      sql_stmt       => p_sql,
      language_flag  => DBMS_SQL.NATIVE,
      parallel_level => p_parallel_level
    );

    v_status := DBMS_PARALLEL_EXECUTE.TASK_STATUS(p_task_name);

    IF v_status = DBMS_PARALLEL_EXECUTE.FINISHED THEN
      p_thong_bao := u'1';
      DBMS_OUTPUT.PUT_LINE(u'[' || p_task_name || u'] Ho\00e0n th\00e0nh th\00e0nh c\00f4ng.');
    ELSE
      -- Th? l?i các chunk b? l?i m?t l?n
      DBMS_OUTPUT.PUT_LINE(
        u'[' || p_task_name || u'] C\00f3 chunk l\1ed7i (status=' || v_status ||
        u'). \0110ang resume...'
      );
      DBMS_PARALLEL_EXECUTE.RESUME_TASK(p_task_name);
      v_status := DBMS_PARALLEL_EXECUTE.TASK_STATUS(p_task_name);
      IF v_status = DBMS_PARALLEL_EXECUTE.FINISHED THEN
        p_thong_bao := u'1';
        DBMS_OUTPUT.PUT_LINE(u'[' || p_task_name || u'] Resume th\00e0nh c\00f4ng.');
      ELSE
        DBMS_OUTPUT.PUT_LINE(
          u'[' || p_task_name || u'] V\1eabn c\00f2n l\1ed7i sau resume. status=' || v_status ||
          u'. Ki\1ec3m tra: SELECT * FROM USER_PARALLEL_EXECUTE_CHUNKS WHERE TASK_NAME=''' ||
          p_task_name || u''' AND STATUS=''PROCESSED_WITH_ERROR'''
        );
      END IF;
    END IF;

    DBMS_PARALLEL_EXECUTE.DROP_TASK(p_task_name);
  EXCEPTION
    WHEN OTHERS THEN
      p_thong_bao := u'0';
      DBMS_OUTPUT.PUT_LINE(u'[' || p_task_name || u'] Exception: ' || SQLERRM);
      BEGIN DBMS_PARALLEL_EXECUTE.DROP_TASK(p_task_name); EXCEPTION WHEN OTHERS THEN NULL; END;
      RAISE;
  END run_parallel_impl;

  PROCEDURE SP_UPDATE_THA_TG_PARALLEL(
    p_parallel_level IN PLS_INTEGER DEFAULT 4,
    p_chunk_size     IN NUMBER      DEFAULT 10000,
    p_thong_bao      OUT NVARCHAR2
  ) IS
  BEGIN
    run_parallel_impl(
      p_task_name      => 'PKG_TINH_AN_UPDATE_THA',
      p_sql            => 'DECLARE v_msg NVARCHAR2(200); BEGIN ' ||
                          'QLPN.PKG_TINH_AN.SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI(' ||
                          'p_id_min => :start_id, p_id_max => :end_id, p_thong_bao => v_msg); END;',
      p_parallel_level => p_parallel_level,
      p_chunk_size     => p_chunk_size,
      p_thong_bao      => p_thong_bao
    );
  END SP_UPDATE_THA_TG_PARALLEL;

  -- =============================================================================
  -- Backfill toàn DB (m?i TTPN_MA): single / range / parallel
  -- =============================================================================
  PROCEDURE SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_ALL(
    p_tha_pnlai_lich_id IN NUMBER,
    p_thong_bao         OUT NVARCHAR2
  ) IS
    v_ok  NUMBER := 0;
    v_err NUMBER := 0;
  BEGIN
    p_thong_bao := u'0';
    do_batch_range(
      p_id_min       => p_tha_pnlai_lich_id,
      p_id_max       => p_tha_pnlai_lich_id,
      p_serving_only => FALSE,
      p_ok           => v_ok,
      p_err          => v_err
    );
    IF v_err = 0 THEN
      p_thong_bao := u'1';
      DBMS_OUTPUT.PUT_LINE(
        u'[SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_ALL] Th\00e0nh c\00f4ng: \0111\00e3 c\1eadp nh\1eadt ' ||
        TO_NCHAR(v_ok) || u' b\1ea3n ghi PN_THI_HANH_AN (to\00e0n DB, kh\00f4ng l\1ecdc TTPN_MA).'
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        u'[SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_ALL] Ho\00e0n th\00e0nh c\00f3 l\1ed7i: th\00e0nh c\00f4ng ' ||
        TO_NCHAR(v_ok) || u' b\1ea3n ghi, l\1ed7i ' || TO_NCHAR(v_err) ||
        u' b\1ea3n ghi (xem t\1eebng d\00f2ng ph\00eda tr\00ean).'
      );
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      p_thong_bao := u'0';
      DBMS_OUTPUT.PUT_LINE(
        u'[SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_ALL] Th\1ea5t b\1ea1i to\00e0n procedure: ' || SQLERRM
      );
      RAISE;
  END SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_ALL;

  PROCEDURE SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_ALL(
    p_id_min    IN NUMBER,
    p_id_max    IN NUMBER,
    p_thong_bao OUT NVARCHAR2
  ) IS
    v_ok  NUMBER := 0;
    v_err NUMBER := 0;
  BEGIN
    p_thong_bao := u'0';
    do_batch_range(
      p_id_min       => p_id_min,
      p_id_max       => p_id_max,
      p_serving_only => FALSE,
      p_ok           => v_ok,
      p_err          => v_err
    );
    IF v_err = 0 THEN
      p_thong_bao := u'1';
    END IF;
    DBMS_OUTPUT.PUT_LINE(
      u'[SP_UPDATE_ALL range ' || TO_NCHAR(p_id_min) || u'-' || TO_NCHAR(p_id_max) ||
      u'] ok=' || TO_NCHAR(v_ok) || u' err=' || TO_NCHAR(v_err)
    );
  EXCEPTION
    WHEN OTHERS THEN
      p_thong_bao := u'0';
      DBMS_OUTPUT.PUT_LINE(
        u'[SP_UPDATE_ALL range ' || TO_NCHAR(p_id_min) || u'-' || TO_NCHAR(p_id_max) ||
        u'] Exception: ' || SQLERRM
      );
      RAISE;
  END SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_ALL;

  PROCEDURE SP_UPDATE_THA_TG_PARALLEL_ALL(
    p_parallel_level IN PLS_INTEGER DEFAULT 4,
    p_chunk_size     IN NUMBER      DEFAULT 10000,
    p_thong_bao      OUT NVARCHAR2
  ) IS
  BEGIN
    run_parallel_impl(
      p_task_name      => 'PKG_TINH_AN_UPDATE_THA_ALL',
      p_sql            => 'DECLARE v_msg NVARCHAR2(200); BEGIN ' ||
                          'QLPN.PKG_TINH_AN.SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_ALL(' ||
                          'p_id_min => :start_id, p_id_max => :end_id, p_thong_bao => v_msg); END;',
      p_parallel_level => p_parallel_level,
      p_chunk_size     => p_chunk_size,
      p_thong_bao      => p_thong_bao
    );
  END SP_UPDATE_THA_TG_PARALLEL_ALL;

  FUNCTION FN_SNAPSHOT_BATCH(p_pn_ids IN QLPN.NUM_TBL, p_ngay_xet IN DATE DEFAULT NULL)
    RETURN t_snap_tbl PIPELINED IS
    v_core  t_tinh_an_core_rec;
    v_out   t_snap_row;
    v_empty t_snap_row;
  BEGIN
    IF p_pn_ids IS NULL THEN RETURN; END IF;
    FOR i IN 1 .. p_pn_ids.COUNT LOOP
      v_out := v_empty;
      v_out.pn_id := p_pn_ids(i);
      BEGIN
        v_core := get_core_cached(p_pn_ids(i), p_ngay_xet);
        v_out.tg_da  := NVL(v_core.tg_da, 0);
        v_out.tg_con := v_core.tg_con;
        v_out.ngay_bat    := v_core.ngay_bat;
        v_out.tg_da_thang := months_from_days(v_core.ngay_bat, v_core.tg_da);
        v_out.tg_da_text := format_da_chap_hanh_text(p_pn_ids(i), p_ngay_xet, 2);
        IF v_core.ngay_bat IS NOT NULL AND v_core.tg_con IS NOT NULL AND v_core.ngay_xet_tl IS NOT NULL THEN
          v_out.tg_con_thang := months_from_days(v_core.ngay_xet_tl, v_core.tg_con);
          IF v_core.tg_con = 0 THEN
            v_out.tg_con_text := u'Kh\00f4ng';
          ELSE
            v_out.tg_con_text := format_tg_from_days(v_core.ngay_xet_tl, v_core.tg_con, 2);
          END IF;
        END IF;
        v_out.tong_giam := tinh_tong_thoi_gian_giam_core(p_pn_ids(i), NULL, u'0');
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
      PIPE ROW (v_out);
    END LOOP;
    RETURN;
  END FN_SNAPSHOT_BATCH;

  PROCEDURE SP_POPULATE_CORE_MEMO(p_pn_ids IN QLPN.NUM_TBL, p_ngay_xet IN DATE) IS
    TYPE t_memo_tbl IS TABLE OF QLPN.DX_CORE_MEMO%ROWTYPE INDEX BY PLS_INTEGER;
    v_buf       t_memo_tbl;
    v_n         PLS_INTEGER := 0;
    v_key       DATE := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));
    v_rec       t_tinh_an_core_rec;
    v_gen_het   DATE;
    v_gen_blk   PLS_INTEGER;
    v_gen_valid PLS_INTEGER;
    v_tg_da_ma  QLPN.DX_CORE_MEMO.TG_DA%TYPE;
    v_tg_con_ma QLPN.DX_CORE_MEMO.TG_CON%TYPE;
  BEGIN
    IF p_pn_ids IS NULL THEN RETURN; END IF;
    FOR i IN 1 .. p_pn_ids.COUNT LOOP
      get_core_impl(p_pn_ids(i), p_ngay_xet, v_rec.ngay_bat, v_rec.tg_da, v_rec.tg_con, v_rec.ngay_xet_tl,
                    v_gen_het, v_gen_blk, v_gen_valid, v_tg_da_ma, v_tg_con_ma);

      -- Phòng v? dictionary-gap: có s? ngày th?t (khác NULL) nh?ng không tra ???c MA_TG (án quá
      -- dài, ngoài mi?n QLPN.DM_MA_THOI_GIANS) -> b? dòng, l?n ??c sau NO_DATA_FOUND -> fallback
      -- get_core_impl tính t??i thay vì l?u memo n?a v?i.
      IF (v_rec.tg_da  IS NOT NULL AND v_tg_da_ma  IS NULL)
      OR (v_rec.tg_con IS NOT NULL AND v_tg_con_ma IS NULL) THEN
        CONTINUE;
      END IF;

      v_n := v_n + 1;
      v_buf(v_n).pn_id        := p_pn_ids(i);
      v_buf(v_n).ngay_xet_key := v_key;
      v_buf(v_n).ngay_bat     := v_rec.ngay_bat;
      v_buf(v_n).tg_da        := v_tg_da_ma;
      v_buf(v_n).tg_con       := v_tg_con_ma;
      v_buf(v_n).ngay_xet_tl  := v_rec.ngay_xet_tl;
      -- Tái dùng GENERAL ?ã ch?y trong get_core_impl; ch? tính l?i khi ngày xét b? cap (hi?m)
      IF v_gen_valid = 1 THEN
        v_buf(v_n).ngay_het := CASE WHEN v_gen_blk = 1 THEN NULL ELSE v_gen_het END;
      ELSE
        v_buf(v_n).ngay_het := get_ngay_het_general_fn(p_pn_ids(i), p_ngay_xet);
      END IF;
      IF v_n >= 5000 THEN
        FORALL j IN 1 .. v_n INSERT INTO QLPN.DX_CORE_MEMO VALUES v_buf(j);
        COMMIT;
        v_n := 0; v_buf.DELETE;
      END IF;
    END LOOP;
    IF v_n > 0 THEN
      FORALL j IN 1 .. v_n INSERT INTO QLPN.DX_CORE_MEMO VALUES v_buf(j);
      COMMIT;
    END IF;
  END SP_POPULATE_CORE_MEMO;

  PROCEDURE SP_POPULATE_TCDK_CORE_MEMO(p_pn_ids IN QLPN.NUM_TBL, p_ngay_xet IN DATE) IS
    TYPE t_memo_tbl IS TABLE OF QLPN.TCDK_CORE_MEMO%ROWTYPE INDEX BY PLS_INTEGER;
    TYPE t_seen_tbl IS TABLE OF PLS_INTEGER INDEX BY PLS_INTEGER;
    v_buf       t_memo_tbl;
    v_seen      t_seen_tbl;
    v_n         PLS_INTEGER := 0;
    v_key       DATE := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));
    v_rec       t_tinh_an_core_rec;
    v_gen_het   DATE;
    v_gen_blk   PLS_INTEGER;
    v_gen_valid PLS_INTEGER;
    v_tg_da_ma  QLPN.TCDK_CORE_MEMO.TG_DA%TYPE;
    v_tg_con_ma QLPN.TCDK_CORE_MEMO.TG_CON%TYPE;
  BEGIN
    IF p_pn_ids IS NULL THEN RETURN; END IF;
    FOR i IN 1 .. p_pn_ids.COUNT LOOP
      IF v_seen.EXISTS(p_pn_ids(i)) THEN
        CONTINUE;
      END IF;
      v_seen(p_pn_ids(i)) := 1;
      get_core_impl(p_pn_ids(i), p_ngay_xet, v_rec.ngay_bat, v_rec.tg_da, v_rec.tg_con, v_rec.ngay_xet_tl,
                    v_gen_het, v_gen_blk, v_gen_valid, v_tg_da_ma, v_tg_con_ma);

      -- Phòng v? dictionary-gap (xem SP_POPULATE_CORE_MEMO) — b? dòng n?u có s? ngày nh?ng
      -- không tra ???c MA_TG.
      IF (v_rec.tg_da  IS NOT NULL AND v_tg_da_ma  IS NULL)
      OR (v_rec.tg_con IS NOT NULL AND v_tg_con_ma IS NULL) THEN
        CONTINUE;
      END IF;

      v_n := v_n + 1;
      v_buf(v_n).pn_id        := p_pn_ids(i);
      v_buf(v_n).ngay_xet_key := v_key;
      v_buf(v_n).ngay_bat     := v_rec.ngay_bat;
      v_buf(v_n).tg_da        := v_tg_da_ma;
      v_buf(v_n).tg_con       := v_tg_con_ma;
      v_buf(v_n).ngay_xet_tl  := v_rec.ngay_xet_tl;
      -- Tái dùng GENERAL ?ã ch?y trong get_core_impl; ch? tính l?i khi ngày xét b? cap (hi?m)
      IF v_gen_valid = 1 THEN
        v_buf(v_n).ngay_het := CASE WHEN v_gen_blk = 1 THEN NULL ELSE v_gen_het END;
      ELSE
        v_buf(v_n).ngay_het := get_ngay_het_general_fn(p_pn_ids(i), p_ngay_xet);
      END IF;
      IF v_n >= 5000 THEN
        FORALL j IN 1 .. v_n INSERT INTO QLPN.TCDK_CORE_MEMO VALUES v_buf(j);
        COMMIT;
        v_n := 0; v_buf.DELETE;
      END IF;
    END LOOP;
    IF v_n > 0 THEN
      FORALL j IN 1 .. v_n INSERT INTO QLPN.TCDK_CORE_MEMO VALUES v_buf(j);
      COMMIT;
    END IF;
  END SP_POPULATE_TCDK_CORE_MEMO;

  PROCEDURE SP_SNAPSHOT_TCDK_BATCH(
    p_pn_ids       IN QLPN.NUM_TBL,
    p_ngay_xet     IN DATE,
    p_delete_scope IN NUMBER DEFAULT 1
  ) IS
    v_key DATE := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));
  BEGIN
    -- Gi?ng DX_CORE_MEMO: ch? xóa ngay_xet_key ?ang warm (theo scope), gi? các k? khác
    IF p_delete_scope = 1 THEN
      DELETE FROM QLPN.TCDK_CORE_MEMO WHERE ngay_xet_key = v_key;
    ELSIF p_pn_ids IS NOT NULL AND p_pn_ids.COUNT > 0 THEN
      DELETE FROM QLPN.TCDK_CORE_MEMO m
       WHERE m.ngay_xet_key = v_key
         AND m.pn_id IN (SELECT COLUMN_VALUE FROM TABLE(p_pn_ids));
    END IF;
    SP_POPULATE_TCDK_CORE_MEMO(p_pn_ids, p_ngay_xet);
  END SP_SNAPSHOT_TCDK_BATCH;

  FUNCTION FN_SNAPSHOT_TCDK_BATCH(
    p_pn_ids    IN QLPN.NUM_TBL,
    p_ngay_xet  IN DATE,
    p_ct_giam   IN QLPN.NUM_TBL,
    p_ct_ctg    IN QLPN.NUM_TBL,
    p_dt_db     IN QLPN.NUM_TBL
  ) RETURN t_tcdk_snap_tbl PIPELINED IS
    v_core     t_tinh_an_core_rec;
    v_out      t_tcdk_snap_row;
    v_an_phat  NVARCHAR2(2000);
    v_ngay_het DATE;
    v_ap_n NUMBER; v_ap_t NUMBER; v_ap_g NUMBER;
  BEGIN
    IF p_pn_ids IS NULL OR p_ct_giam IS NULL OR p_ct_ctg IS NULL OR p_dt_db IS NULL THEN
      RETURN;
    END IF;
    IF p_pn_ids.COUNT != p_ct_giam.COUNT
       OR p_pn_ids.COUNT != p_ct_ctg.COUNT
       OR p_pn_ids.COUNT != p_dt_db.COUNT THEN
      RAISE_APPLICATION_ERROR(-20001, 'FN_SNAPSHOT_TCDK_BATCH: array counts must match');
    END IF;

    FOR i IN 1 .. p_pn_ids.COUNT LOOP
      v_out.pn_id               := p_pn_ids(i);
      v_out.dieu_kien_thoi_gian := NULL;
      v_out.tg_da_giam          := NULL;
      v_out.tg_chap_hanh        := NULL;
      v_out.tg_con_lai          := NULL;
      BEGIN
        v_core := get_tcdk_core_cached(p_pn_ids(i), p_ngay_xet);
        v_ap_n := 0; v_ap_t := 0; v_ap_g := 0;
        IF NVL(p_ct_giam(i), 0) = 1 THEN
          v_ngay_het := NULL;
        ELSE
          v_an_phat  := get_tha_an_phat_priv(p_pn_ids(i), p_ngay_xet);
          v_ngay_het := get_ngay_het_tcdk_cached(p_pn_ids(i), v_core.ngay_bat, v_an_phat, p_ngay_xet);
          sum_ymd_text(v_an_phat, v_ap_n, v_ap_t, v_ap_g);
        END IF;
        v_out.dieu_kien_thoi_gian := eval_dieu_kien_thoi_gian(
          p_ct_giam(i), p_ct_ctg(i), p_dt_db(i),
          v_core.ngay_bat, v_core.tg_da, v_core.tg_con, v_ngay_het, v_ap_n * 12 + v_ap_t
        );
        v_out.tg_chap_hanh := format_da_chap_hanh_from_core(p_pn_ids(i), p_ngay_xet, 2, v_core);
        IF v_core.ngay_bat IS NOT NULL AND v_core.tg_con IS NOT NULL AND v_core.ngay_xet_tl IS NOT NULL THEN
          IF v_core.tg_con = 0 THEN
            v_out.tg_con_lai := u'Kh\00f4ng';
          ELSE
            v_out.tg_con_lai := format_tg_from_days(v_core.ngay_xet_tl, v_core.tg_con, 2);
          END IF;
        END IF;
        v_out.tg_da_giam := FN_TINH_GIAM_AN_HIEN_THI(p_pn_ids(i));
      EXCEPTION
        WHEN OTHERS THEN NULL;
      END;
      PIPE ROW (v_out);
    END LOOP;
    RETURN;
  END FN_SNAPSHOT_TCDK_BATCH;

END PKG_TINH_AN;

/
--------------------------------------------------------
--  DDL for Package Body PKG_TINH_AN_V1
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "QLPN"."PKG_TINH_AN_V1" AS

  -- Chuy?n text "X n?m Y tháng Z ngày" sang s? ngày (theo l?ch)
  FUNCTION parse_ymd_to_days(p_text IN NVARCHAR2) RETURN NUMBER IS
    v_n NUMBER;
    v_t NUMBER;
    v_g NUMBER;
    v_ref DATE := DATE '1900-01-01';
  BEGIN
    IF p_text IS NULL OR TRIM(p_text) IS NULL THEN
      RETURN 0;
    END IF;
    v_n := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_text, 'NAM'), 0);
    v_t := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_text, 'THANG'), 0);
    v_g := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_text, 'NGAY'), 0);
    RETURN (ADD_MONTHS(v_ref, v_n * 12 + v_t) + v_g) - v_ref;
  EXCEPTION
    WHEN OTHERS THEN RETURN 0;
  END parse_ymd_to_days;

  -- Chuy?n m?c gi?m (MTG_TITLE/MTG_MA d?ng "n?m tháng ngày" ho?c "n1 n2 n3") sang s? ngày
  FUNCTION parse_muc_giam_to_days(p_text IN NVARCHAR2) RETURN NUMBER IS
  BEGIN
    IF p_text IS NULL OR TRIM(p_text) IS NULL THEN
      RETURN 0;
    END IF;
    -- Th? parse_ymd_to_days n?u có format "X n?m Y tháng Z ngày"
    IF REGEXP_LIKE(p_text, 'n?m|tháng|ngày', 'i') THEN
      RETURN parse_ymd_to_days(p_text);
    END IF;
    -- Format "n1 n2 n3" (n?m tháng ngày): REGEXP_SUBSTR l?y 3 s? ??u
    RETURN NVL(TO_NUMBER(REGEXP_SUBSTR(TRIM(p_text), '[0-9]+', 1, 1)), 0) * 365
         + NVL(TO_NUMBER(REGEXP_SUBSTR(TRIM(p_text), '[0-9]+', 1, 2)), 0) * 30
         + NVL(TO_NUMBER(REGEXP_SUBSTR(TRIM(p_text), '[0-9]+', 1, 3)), 0);
  EXCEPTION
    WHEN OTHERS THEN RETURN 0;
  END parse_muc_giam_to_days;

  -- Helper: chuy?n kho?ng (d1, d2) thành n?m, tháng, ngày (??t tr??c FN_TINH_TONG_THOI_GIAN_GIAM)
  PROCEDURE diff_ymd(
    d1 IN DATE, d2 IN DATE,
    y OUT NUMBER, m OUT NUMBER, d OUT NUMBER
  ) IS
    v_months NUMBER;
    v_tmp    DATE;
  BEGIN
    IF d2 <= d1 THEN
      y := 0; m := 0; d := 0;
      RETURN;
    END IF;
    v_months := TRUNC(MONTHS_BETWEEN(d2, d1));
    y := TRUNC(v_months / 12);
    m := MOD(v_months, 12);
    v_tmp := ADD_MONTHS(d1, y * 12 + m);
    d := TRUNC(d2 - v_tmp);
    IF d < 0 THEN
      m := m - 1;
      IF m < 0 THEN y := y - 1; m := m + 12; END IF;
      v_tmp := ADD_MONTHS(d1, y * 12 + m);
      d := GREATEST(TRUNC(d2 - v_tmp), 0);
    END IF;
  END diff_ymd;

  -- C?ng tháng theo l?ch nh?ng gi? ngày trong tháng (không kéo theo quy t?c "cu?i tháng" c?a ADD_MONTHS).
  -- Ví d?: 28/02 +1 tháng = 28/03; 30/04 +1 tháng = 30/05; 31/05 +1 tháng = 30/06.
  FUNCTION add_months_keep_day(p_date IN DATE, p_months IN NUMBER) RETURN DATE IS
    v_src DATE := TRUNC(p_date);
    v_day NUMBER;
    v_target_month_start DATE;
    v_target_last_day NUMBER;
  BEGIN
    IF p_date IS NULL THEN
      RETURN NULL;
    END IF;
    v_day := TO_NUMBER(TO_CHAR(v_src, 'DD'));
    v_target_month_start := TRUNC(ADD_MONTHS(v_src, NVL(p_months, 0)), 'MM');
    v_target_last_day := TO_NUMBER(TO_CHAR(LAST_DAY(v_target_month_start), 'DD'));
    RETURN v_target_month_start + LEAST(v_day, v_target_last_day) - 1;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN TRUNC(ADD_MONTHS(v_src, NVL(p_months, 0)));
  END add_months_keep_day;

  -- Helper n?i b?: tr? v? t?ng s? ngày gi?m (dùng cho tính toán)
  -- Dùng cursor loop vì parse_muc_giam_to_days không g?i ???c trong SQL
  FUNCTION calc_tong_thoi_giam_ngay(p_id_pham_nhan IN NUMBER) RETURN NUMBER IS
    v_tong NUMBER := 0;
  BEGIN
    IF p_id_pham_nhan IS NULL THEN RETURN 0; END IF;
    FOR rec IN (
      SELECT dm.MTG_TITLE
        FROM QLPN.GIAM_THOI_HANS gth
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dm ON dm.ID = gth.MUC_GIAM_ID AND NVL(dm.IS_DELETED, 0) = 0
       WHERE NVL(gth.IS_DELETED, 0) = 0
         AND gth.PHAM_NHAN_ID = p_id_pham_nhan
         AND gth.MUC_GIAM_ID IS NOT NULL
    ) LOOP
      v_tong := v_tong + parse_muc_giam_to_days(rec.MTG_TITLE);
    END LOOP;
    RETURN v_tong;
  EXCEPTION
    WHEN OTHERS THEN RETURN 0;
  END calc_tong_thoi_giam_ngay;

  -- Th?i h?n án t? chu?i: c?ng tháng gi? nguyên ngày trong tháng + c?ng ngày l?; không quy 30 ngày?tháng.
  -- Fallback: c?ng N ngày INTEGER khi không parse ???c N/T/G.
  FUNCTION an_phat_cong_len_lich(p_ngay_bat IN DATE, p_an_phat_txt IN NVARCHAR2) RETURN DATE IS
    v_n NUMBER;
    v_t NUMBER;
    v_g NUMBER;
  BEGIN
    IF p_ngay_bat IS NULL THEN
      RETURN NULL;
    END IF;
    IF p_an_phat_txt IS NULL OR TRIM(p_an_phat_txt) IS NULL THEN
      RETURN TRUNC(p_ngay_bat);
    END IF;
    v_n := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_an_phat_txt, 'NAM'), 0);
    v_t := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_an_phat_txt, 'THANG'), 0);
    v_g := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_an_phat_txt, 'NGAY'), 0);
    IF NVL(v_n, 0) > 0 OR NVL(v_t, 0) > 0 OR NVL(v_g, 0) > 0 THEN
      RETURN TRUNC(add_months_keep_day(TRUNC(p_ngay_bat), NVL(v_n, 0) * 12 + NVL(v_t, 0)) + NVL(v_g, 0));
    END IF;
    RETURN TRUNC(p_ngay_bat);
  EXCEPTION
    WHEN OTHERS THEN
      RETURN TRUNC(p_ngay_bat);
  END an_phat_cong_len_lich;

  -- Mi?n HP: t?ng dòng ADD_MONTHS(-n?m*12-tháng) - ngày trên m?c k?t thúc (rút ng?n h?n)
  FUNCTION apply_mien_hinh_phat_calendar(p_ngay_ket IN DATE, p_id IN NUMBER) RETURN DATE IS
    v_d DATE;
  BEGIN
    IF p_ngay_ket IS NULL OR p_id IS NULL THEN
      RETURN p_ngay_ket;
    END IF;
    v_d := TRUNC(p_ngay_ket);
    FOR m IN (
      SELECT NVL(x.MHP_THM_YEAR, 0) AS yn,
             NVL(x.MHP_THM_MONTH, 0) AS mn,
             NVL(x.MHP_THM_DAY, 0) AS dn,
             x.ID
        FROM QLPN.MIEN_HINH_PHATS x
       WHERE x.PN_LAI_LICH_ID = p_id
         AND NVL(x.IS_DELETED, 0) = 0
       ORDER BY x.ID
    ) LOOP
      IF NVL(m.yn, 0) > 0 OR NVL(m.mn, 0) > 0 THEN
        v_d := ADD_MONTHS(v_d, -(NVL(m.yn, 0) * 12 + NVL(m.mn, 0)));
      END IF;
      IF NVL(m.dn, 0) > 0 THEN
        v_d := v_d - NVL(m.dn, 0);
      END IF;
    END LOOP;
    RETURN v_d;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN p_ngay_ket;
  END apply_mien_hinh_phat_calendar;

  -- T?ng (10) / gi?m (20) hình ph?t: t?ng Q? trên DATE (N/T/G t? MTG_TITLE ho?c DM c?t NAM/THANG/NGAY)
  FUNCTION apply_tang_giam_hinh_phat_calendar(p_ngay_ket IN DATE, p_id IN NUMBER) RETURN DATE IS
    v_d       DATE;
    v_row_gn  NUMBER;
    v_row_gt  NUMBER;
    v_row_gg  NUMBER;
    v_days    NUMBER;
  BEGIN
    IF p_ngay_ket IS NULL OR p_id IS NULL THEN
      RETURN p_ngay_ket;
    END IF;
    v_d := TRUNC(p_ngay_ket);
    FOR rec IN (
      SELECT dt.LTGHP_MA,
             dm.MTG_TITLE,
             NVL(dm.MTG_NAM, 0) AS mn,
             NVL(dm.MTG_THANG, 0) AS mt,
             NVL(dm.MTG_NGAY, 0) AS mg,
             tg.ID
        FROM QLPN.TANG_GIAM_HINH_PHATS tg
        INNER JOIN QLPN.DM_LOAI_TANG_GIAM_HINH_PHATS dt
                ON dt.ID = tg.LOAI_TANG_GIAM_ID
               AND NVL(dt.IS_DELETED, 0) = 0
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dm
               ON dm.ID = tg.THOI_HAN_ID
              AND NVL(dm.IS_DELETED, 0) = 0
       WHERE tg.PHAM_NHAN_ID = p_id
         AND NVL(tg.IS_DELETED, 0) = 0
       ORDER BY tg.NGAY_QUYET_DINH NULLS LAST, tg.ID
    ) LOOP
      v_row_gn := 0;
      v_row_gt := 0;
      v_row_gg := 0;
      IF rec.MTG_TITLE IS NOT NULL AND REGEXP_LIKE(rec.MTG_TITLE, 'n?m|tháng|ngày', 'i') THEN
        v_row_gn := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NAM'), 0);
        v_row_gt := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'THANG'), 0);
        v_row_gg := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NGAY'), 0);
      ELSIF NVL(rec.mn, 0) + NVL(rec.mt, 0) + NVL(rec.mg, 0) > 0 THEN
        v_row_gn := rec.mn;
        v_row_gt := rec.mt;
        v_row_gg := rec.mg;
      END IF;
      IF v_row_gn + v_row_gt + v_row_gg > 0 THEN
        IF rec.LTGHP_MA = '10' THEN
          v_d := ADD_MONTHS(v_d, v_row_gn * 12 + v_row_gt) + v_row_gg;
        ELSIF rec.LTGHP_MA = '20' THEN
          v_d := ADD_MONTHS(v_d, -(v_row_gn * 12 + v_row_gt)) - v_row_gg;
        END IF;
      ELSIF rec.MTG_TITLE IS NOT NULL AND TRIM(rec.MTG_TITLE) IS NOT NULL THEN
        v_days := NVL(parse_muc_giam_to_days(rec.MTG_TITLE), 0);
        IF v_days > 0 THEN
          IF rec.LTGHP_MA = '10' THEN
            v_d := v_d + v_days;
          ELSIF rec.LTGHP_MA = '20' THEN
            v_d := v_d - v_days;
          END IF;
        END IF;
      END IF;
    END LOOP;
    RETURN v_d;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN p_ngay_ket;
  END apply_tang_giam_hinh_phat_calendar;

  /*
   * Tr? gi?m án l?n l??t t?ng b?n ghi (l?ch): ADD_MONTHS(-(n?m*12+tháng)) - ngày, ho?c tr? N ngày INTEGER khi ch? parse ???c t?ng ngày.
   */
  FUNCTION ket_an_subtract_giam_calendar(
    p_ngay_ket_truoc_giam IN DATE,
    p_id_pham_nhan       IN NUMBER
  ) RETURN DATE IS
    v_d       DATE;
    v_row_gn  NUMBER;
    v_row_gt  NUMBER;
    v_row_gg  NUMBER;
    v_days    NUMBER;
  BEGIN
    IF p_id_pham_nhan IS NULL OR p_ngay_ket_truoc_giam IS NULL THEN
      RETURN p_ngay_ket_truoc_giam;
    END IF;
    v_d := TRUNC(p_ngay_ket_truoc_giam);
    FOR rec IN (
      SELECT dm.MTG_TITLE,
             NVL(dm.MTG_NAM, 0) AS mn,
             NVL(dm.MTG_THANG, 0) AS mt,
             NVL(dm.MTG_NGAY, 0) AS mg,
             gth.ID,
             gth.NGAY_QUYET_DINH
        FROM QLPN.GIAM_THOI_HANS gth
        LEFT JOIN QLPN.DM_MA_THOI_GIANS dm ON dm.ID = gth.MUC_GIAM_ID AND NVL(dm.IS_DELETED, 0) = 0
       WHERE NVL(gth.IS_DELETED, 0) = 0
         AND gth.PHAM_NHAN_ID = p_id_pham_nhan
         AND gth.MUC_GIAM_ID IS NOT NULL
       ORDER BY gth.NGAY_QUYET_DINH NULLS LAST, gth.ID
    ) LOOP
      v_row_gn := 0;
      v_row_gt := 0;
      v_row_gg := 0;
      IF rec.MTG_TITLE IS NOT NULL AND REGEXP_LIKE(rec.MTG_TITLE, 'n?m|tháng|ngày', 'i') THEN
        v_row_gn := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NAM'), 0);
        v_row_gt := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'THANG'), 0);
        v_row_gg := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(rec.MTG_TITLE, 'NGAY'), 0);
      ELSIF NVL(rec.mn, 0) + NVL(rec.mt, 0) + NVL(rec.mg, 0) > 0 THEN
        v_row_gn := rec.mn;
        v_row_gt := rec.mt;
        v_row_gg := rec.mg;
      END IF;
      IF v_row_gn + v_row_gt + v_row_gg > 0 THEN
        v_d := ADD_MONTHS(v_d, -(v_row_gn * 12 + v_row_gt)) - v_row_gg;
      ELSIF rec.MTG_TITLE IS NOT NULL AND TRIM(rec.MTG_TITLE) IS NOT NULL THEN
        v_days := NVL(parse_muc_giam_to_days(rec.MTG_TITLE), 0);
        IF v_days > 0 THEN
          v_d := v_d - v_days;
        END IF;
      END IF;
    END LOOP;
    RETURN v_d;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN p_ngay_ket_truoc_giam;
  END ket_an_subtract_giam_calendar;

  -- Ngày h?t án (l?ch) sau án ph?t + gi?m + t?ng/gi?m HP + mi?n
  FUNCTION ngay_het_an_sau_dieuchinh(
    p_ngay_bat     IN DATE,
    p_an_phat_txt  IN NVARCHAR2,
    p_id_pham_nhan IN NUMBER
  ) RETURN DATE IS
    v_d    DATE;
    v_norm NVARCHAR2(4000);
  BEGIN
    IF p_ngay_bat IS NULL OR p_id_pham_nhan IS NULL THEN
      RETURN NULL;
    END IF;
    v_norm := UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(p_an_phat_txt), u'')));
    IF v_norm LIKE '%' || 'TUHINH' || '%' THEN
      RETURN NULL;
    END IF;
    IF v_norm LIKE '%' || 'CHUNGTHAN' || '%'
       AND v_norm NOT LIKE '%' || 'GIAMXUONG' || '%'
    THEN
      RETURN NULL;
    END IF;

    v_d := an_phat_cong_len_lich(p_ngay_bat, p_an_phat_txt);
    v_d := ket_an_subtract_giam_calendar(v_d, p_id_pham_nhan);
    v_d := apply_tang_giam_hinh_phat_calendar(v_d, p_id_pham_nhan);
    v_d := apply_mien_hinh_phat_calendar(v_d, p_id_pham_nhan);
    RETURN TRUNC(v_d);
  EXCEPTION
    WHEN OTHERS THEN
      RETURN NULL;
  END ngay_het_an_sau_dieuchinh;

  -- N?i "A n?m B tháng C ngày", b? thành ph?n = 0; c? ba = 0 ? N'0'
  FUNCTION format_nam_thang_ngay_omit_zero(p_y NUMBER, p_m NUMBER, p_d NUMBER) RETURN NVARCHAR2 IS
    v_parts NVARCHAR2(4000);
  BEGIN
    IF NVL(p_y, 0) = 0 AND NVL(p_m, 0) = 0 AND NVL(p_d, 0) = 0 THEN
      RETURN TO_NCHAR(0);
    END IF;
    v_parts := NULL;
    IF NVL(p_y, 0) > 0 THEN
      v_parts := TO_NCHAR(p_y) || u' n\0103m';
    END IF;
    IF NVL(p_m, 0) > 0 THEN
      IF v_parts IS NOT NULL THEN
        v_parts := v_parts || u' ' || TO_NCHAR(p_m) || u' th\00e1ng';
      ELSE
        v_parts := TO_NCHAR(p_m) || u' th\00e1ng';
      END IF;
    END IF;
    IF NVL(p_d, 0) > 0 THEN
      IF v_parts IS NOT NULL THEN
        v_parts := v_parts || u' ' || TO_NCHAR(p_d) || u' ng\00e0y';
      ELSE
        v_parts := TO_NCHAR(p_d) || u' ng\00e0y';
      END IF;
    END IF;
    RETURN v_parts;
  END format_nam_thang_ngay_omit_zero;

  FUNCTION FN_TINH_TONG_THOI_GIAN_GIAM(
    p_id_pham_nhan IN NUMBER
  ) RETURN NVARCHAR2 IS
    v_tong NUMBER;
    v_ref  DATE := DATE '1900-01-01';
    v_y    NUMBER;
    v_m    NUMBER;
    v_d    NUMBER;
  BEGIN
    v_tong := calc_tong_thoi_giam_ngay(p_id_pham_nhan);
    IF v_tong IS NULL OR v_tong <= 0 THEN
      RETURN '0';
    END IF;
    diff_ymd(v_ref, v_ref + v_tong, v_y, v_m, v_d);
    IF v_y >= 1 THEN
      RETURN format_nam_thang_ngay_omit_zero(v_y, v_m, v_d);
    ELSIF v_m >= 1 THEN
      IF NVL(v_d, 0) > 0 THEN
        RETURN TO_NCHAR(v_m) || u' Th\00e1ng ' || TO_NCHAR(v_d) || u' ng\00e0y';
      END IF;
      RETURN TO_NCHAR(v_m) || u' Th\00e1ng';
    ELSE
      RETURN TO_NCHAR(NVL(v_d, 0)) || u' ng\00e0y';
    END IF;
  EXCEPTION
    WHEN OTHERS THEN RETURN '0';
  END FN_TINH_TONG_THOI_GIAN_GIAM;

  FUNCTION FN_TINH_SO_LAN_GIAM_AN(
    p_id_pham_nhan IN NUMBER
  ) RETURN NUMBER IS
    v_count NUMBER := 0;
  BEGIN
    IF p_id_pham_nhan IS NULL THEN RETURN 0; END IF;
    SELECT COUNT(*)
      INTO v_count
      FROM QLPN.GIAM_THOI_HANS gth
     WHERE NVL(gth.IS_DELETED, 0) = 0
       AND gth.PHAM_NHAN_ID = p_id_pham_nhan
       AND gth.MUC_GIAM_ID IS NOT NULL;
    RETURN NVL(v_count, 0);
  EXCEPTION
    WHEN OTHERS THEN RETURN 0;
  END FN_TINH_SO_LAN_GIAM_AN;

  FUNCTION FN_TINH_GIAM_AN_HIEN_THI(
    p_id_pham_nhan IN NUMBER
  ) RETURN NVARCHAR2 IS
    v_so_lan  NUMBER;
    v_tong    NVARCHAR2(200);
  BEGIN
    v_so_lan := FN_TINH_SO_LAN_GIAM_AN(p_id_pham_nhan);
    v_tong   := FN_TINH_TONG_THOI_GIAN_GIAM(p_id_pham_nhan);
    IF v_so_lan = 0 OR v_tong IS NULL OR NULLIF(TRIM(v_tong), '0') IS NULL THEN
      RETURN u'Kh\00f4ng';
    END IF;
    RETURN TO_NCHAR(v_so_lan) || u' l\1ea7n = ' || v_tong;
  EXCEPTION
    WHEN OTHERS THEN RETURN u'Kh\00f4ng';
  END FN_TINH_GIAM_AN_HIEN_THI;

  FUNCTION FN_TINH_TONG_MIEN_HINH_PHAT_HIEN_THI(
    p_id_pham_nhan IN NUMBER
  ) RETURN NVARCHAR2 IS
    v_agg NVARCHAR2(4000);
  BEGIN
    IF p_id_pham_nhan IS NULL THEN
      RETURN u'Kh\00f4ng';
    END IF;
    SELECT SUBSTR(
        LISTAGG(
          TRIM(
            CASE
              WHEN NVL(x.MHP_THM_YEAR, 0) > 0
              THEN TO_NCHAR(x.MHP_THM_YEAR) || u' n\0103m '
              ELSE u''
            END
            || CASE
                 WHEN NVL(x.MHP_THM_MONTH, 0) > 0
                 THEN TO_NCHAR(x.MHP_THM_MONTH) || u' th\00e1ng '
                 ELSE u''
               END
            || CASE
                 WHEN NVL(x.MHP_THM_DAY, 0) > 0
                 THEN TO_NCHAR(x.MHP_THM_DAY) || u' ng\00e0y'
                 ELSE u''
               END
          ),
          CHR(10) ON OVERFLOW TRUNCATE u'...' WITH COUNT
        ) WITHIN GROUP (ORDER BY x.MHP_NGAY_QUYET_DINH NULLS LAST, x.ID),
        1,
        4000
      )
      INTO v_agg
      FROM QLPN.MIEN_HINH_PHATS x
     WHERE x.PN_LAI_LICH_ID = p_id_pham_nhan
       AND NVL(x.IS_DELETED, 0) = 0
       AND NVL(x.MHP_THM_YEAR, 0) + NVL(x.MHP_THM_MONTH, 0) + NVL(x.MHP_THM_DAY, 0) > 0;
    IF v_agg IS NULL OR TRIM(v_agg) IS NULL THEN
      RETURN u'Kh\00f4ng';
    END IF;
    RETURN v_agg;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RETURN u'Kh\00f4ng';
    WHEN OTHERS THEN
      RETURN u'Kh\00f4ng';
  END FN_TINH_TONG_MIEN_HINH_PHAT_HIEN_THI;

  -- Helper: l?y th?i gian th?c s? ?ã ? tù và th?i gian còn l?i
  PROCEDURE get_tg_da_va_con(
    p_id_pham_nhan   IN  NUMBER,
    p_ngay_xet       IN  DATE,
    p_ngay_bat       OUT NOCOPY DATE,
    p_tg_da          OUT NOCOPY NUMBER,
    p_tg_con         OUT NOCOPY NUMBER,
    p_ngay_xet_tl    OUT NOCOPY DATE
  ) IS
    v_ngay_xet       DATE;
    v_ngay_ra_trai   DATE;
    v_ngay_tdc_mo    DATE;
    v_ngay_bat       DATE;
    v_tg_tam_dinh    NUMBER := 0;
    v_tg_hoan        NUMBER := 0;
    v_tg_tron        NUMBER := 0;
    v_upper_ap       NVARCHAR2(2000);
    v_an_phat_txt    NVARCHAR2(2000);
    v_block          PLS_INTEGER := 0;
    v_span           NUMBER;
    v_sub            NUMBER;
    v_ngay_het       DATE;
    v_cnt            NUMBER;
  BEGIN
    p_ngay_bat := NULL;
    p_tg_da := NULL;
    p_tg_con := NULL;
    p_ngay_xet_tl := NULL;

    IF p_id_pham_nhan IS NULL THEN
      RETURN;
    END IF;

    -- NGÀY NH?P VÀO = ngày xét; n?u không có ngày xét thì SYSDATE
    v_ngay_xet := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));

    -- N?u ?ã có ngày ra tr?i/tha thì ch? tính ??n m?c này
    BEGIN
      SELECT MIN(TRUNC(k.KTRT_NGAY_THA))
        INTO v_ngay_ra_trai
        FROM QLPN.PN_KET_THUC_RA_TRAIS k
       WHERE k.KTRT_PN_LAI_LICH_ID = p_id_pham_nhan
         AND NVL(k.IS_DELETED, 0) = 0
         AND k.KTRT_NGAY_THA IS NOT NULL
         AND TRUNC(k.KTRT_NGAY_THA) <= v_ngay_xet;
    EXCEPTION
      WHEN OTHERS THEN
        v_ngay_ra_trai := NULL;
    END;

    IF v_ngay_ra_trai IS NOT NULL THEN
      v_ngay_xet := LEAST(v_ngay_xet, v_ngay_ra_trai);
    END IF;

    -- N?u ?ang t?m ?ình ch? (ch?a có ngày l?i), th?i gian thi hành án ch? tính ??n ngày b?t ??u t?m ?ình ch?
    BEGIN
      SELECT MIN(TRUNC(COALESCE(td.TU_NGAY, td.NGAY_TDC)))
        INTO v_ngay_tdc_mo
        FROM QLPN.TAM_DINH_CHIS td
       WHERE td.PHAM_NHAN_ID = p_id_pham_nhan
         AND NVL(td.IS_DELETED, 0) = 0
         AND COALESCE(td.TU_NGAY, td.NGAY_TDC) IS NOT NULL
         AND td.NGAY_LAI IS NULL
         AND TRUNC(COALESCE(td.TU_NGAY, td.NGAY_TDC)) <= v_ngay_xet;
    EXCEPTION
      WHEN OTHERS THEN
        v_ngay_tdc_mo := NULL;
    END;

    IF v_ngay_tdc_mo IS NOT NULL THEN
      v_ngay_xet := LEAST(v_ngay_xet, v_ngay_tdc_mo);
    END IF;

    -- L?y ngày b?t + án ph?t t? THA ??i di?n (PN_THI_HANH_AN)
    SELECT tha.ngay_bat,
           tha.THA_AN_PHAT
      INTO v_ngay_bat, v_an_phat_txt
      FROM (
        SELECT COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU) AS ngay_bat,
               t.THA_AN_PHAT,
               ROW_NUMBER() OVER (ORDER BY COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) AS rn
          FROM QLPN.PN_THI_HANH_AN t
         WHERE t.THA_PNLAI_LICH_ID = p_id_pham_nhan
           AND NVL(t.IS_DELETED, 0) = 0
           AND COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU) IS NOT NULL
           AND TRUNC(COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) <= v_ngay_xet
           AND (t.THA_NGAY_HET_HAN IS NULL OR TRUNC(t.THA_NGAY_HET_HAN) >= v_ngay_xet)
      ) tha
     WHERE tha.rn = 1;

    IF v_ngay_bat IS NULL THEN
      RETURN;
    END IF;

    v_ngay_bat := TRUNC(v_ngay_bat);

    -- TG t?m ?ình ch?: (ngày_k?t_thúc - t?_ngày + 1), ?u tiên NGAY_LAI, fallback NGAY_TDC; n?u ??u null thì l?y ngày xét
    SELECT NVL(SUM(
      GREATEST(0,
        TRUNC(LEAST(NVL(COALESCE(td.NGAY_LAI, td.NGAY_TDC), v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(COALESCE(td.TU_NGAY, td.NGAY_TDC), v_ngay_bat)) + 1
      )
    ), 0)
      INTO v_tg_tam_dinh
      FROM QLPN.TAM_DINH_CHIS td
     WHERE td.PHAM_NHAN_ID = p_id_pham_nhan
       AND NVL(td.IS_DELETED, 0) = 0
       AND COALESCE(td.TU_NGAY, td.NGAY_TDC) IS NOT NULL
       AND COALESCE(td.TU_NGAY, td.NGAY_TDC) <= v_ngay_xet
       AND (COALESCE(td.NGAY_LAI, td.NGAY_TDC) IS NULL OR COALESCE(td.NGAY_LAI, td.NGAY_TDC) >= v_ngay_bat);

    -- TG hoãn (kho?ng giao [ngày b?t, ngày xét]); ??m inclusive +1 — notebooks/tinh_an.txt §0–§1
    SELECT NVL(SUM(
      GREATEST(0,
        TRUNC(LEAST(NVL(h.NGAY_THI_HANH_AN, v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(h.NGAY_HOAN, v_ngay_bat)) + 1
      )
    ), 0)
      INTO v_tg_hoan
      FROM QLPN.HOAN_THI_HANH_ANS h
     WHERE h.PHAM_NHAN_ID = p_id_pham_nhan
       AND NVL(h.IS_DELETED, 0) = 0
       AND h.NGAY_HOAN IS NOT NULL
       AND h.NGAY_HOAN <= v_ngay_xet
       AND (h.NGAY_THI_HANH_AN IS NULL OR h.NGAY_THI_HANH_AN >= v_ngay_bat);

    -- TG tr?n: ch? k? ?ã b?t l?i; ??m inclusive +1 — §3
    SELECT NVL(SUM(
      GREATEST(0, TRUNC(LEAST(tt.NGAY_BAT_LAI, v_ngay_xet)) - TRUNC(GREATEST(tt.NGAY_TRON, v_ngay_bat)) + 1)
    ), 0)
      INTO v_tg_tron
      FROM QLPN.TRON_TRAIS tt
     WHERE tt.PHAM_NHAN_ID = p_id_pham_nhan
       AND NVL(tt.IS_DELETED, 0) = 0
       AND tt.NGAY_TRON IS NOT NULL
       AND tt.NGAY_BAT_LAI IS NOT NULL
       AND tt.NGAY_TRON <= v_ngay_xet
       AND tt.NGAY_BAT_LAI >= v_ngay_bat;

    -- Fallback §4: không tr? T?C/hoãn/tr?n
    IF v_ngay_tdc_mo IS NOT NULL THEN
      v_block := 1;
    END IF;

    -- Hoãn m? / tr?n ch?a b?t l?i / trích xu?t m?: m?t l?n EXISTS thay vì 3 l?n COUNT(*)
    IF v_block = 0 THEN
      BEGIN
        SELECT 1 INTO v_cnt
          FROM DUAL
         WHERE EXISTS (
                 SELECT 1
                   FROM QLPN.HOAN_THI_HANH_ANS h
                  WHERE h.PHAM_NHAN_ID = p_id_pham_nhan
                    AND NVL(h.IS_DELETED, 0) = 0
                    AND h.NGAY_HOAN IS NOT NULL
                    AND h.NGAY_THI_HANH_AN IS NULL
                    AND TRUNC(h.NGAY_HOAN) <= v_ngay_xet
               )
            OR EXISTS (
                 SELECT 1
                   FROM QLPN.TRON_TRAIS tt
                  WHERE tt.PHAM_NHAN_ID = p_id_pham_nhan
                    AND NVL(tt.IS_DELETED, 0) = 0
                    AND tt.NGAY_TRON IS NOT NULL
                    AND tt.NGAY_BAT_LAI IS NULL
                    AND TRUNC(tt.NGAY_TRON) <= v_ngay_xet
               )
            OR EXISTS (
                 SELECT 1
                   FROM QLPN.TRICH_XUATS tx
                  WHERE tx.PHAM_NHAN_ID = p_id_pham_nhan
                    AND NVL(tx.IS_DELETED, 0) = 0
                    AND tx.TX_NGAY_TRICH_XUAT IS NOT NULL
                    AND tx.TX_NGAY_TRA IS NULL
                    AND TRUNC(tx.TX_NGAY_TRICH_XUAT) <= v_ngay_xet
               );
        v_block := 1;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          NULL;
      END;
    END IF;

    p_ngay_bat := v_ngay_bat;
    v_span := GREATEST(0, TRUNC(v_ngay_xet) - TRUNC(v_ngay_bat));
    v_sub := NVL(v_tg_tam_dinh, 0) + NVL(v_tg_hoan, 0) + NVL(v_tg_tron, 0);

    IF v_block = 1 THEN
      p_tg_da := v_span;
    ELSE
      p_tg_da := GREATEST(0, v_span - v_sub);
    END IF;
    p_ngay_xet_tl := TRUNC(v_ngay_xet);

    -- TH?I GIAN CÒN L?I — “Ngày h?t h?n.txt”: TRUNC(ngày h?t l?ch) - TRUNC(ngày xét)
    v_upper_ap := UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(v_an_phat_txt), u'')));
    IF v_upper_ap LIKE '%' || 'TUHINH' || '%' THEN
      p_tg_con := NULL;
    ELSIF v_upper_ap LIKE '%' || 'CHUNGTHAN' || '%'
          AND v_upper_ap NOT LIKE '%' || 'GIAMXUONG' || '%'
    THEN
      p_tg_con := NULL;
    ELSE
      v_ngay_het := ngay_het_an_sau_dieuchinh(v_ngay_bat, v_an_phat_txt, p_id_pham_nhan);
      IF v_ngay_het IS NULL THEN
        p_tg_con := NULL;
      ELSE
        p_tg_con := GREATEST(0, v_ngay_het - TRUNC(v_ngay_xet));
      END IF;
    END IF;

  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      NULL;
    WHEN OTHERS THEN
      p_ngay_bat := NULL;
      p_tg_da := NULL;
      p_tg_con := NULL;
      p_ngay_xet_tl := NULL;
  END get_tg_da_va_con;

  -- Helper: format s? ngày thành "X Tháng Y ngày" ho?c "A n?m B tháng C ngày" (dùng ngày b?t làm g?c).
  -- B? qua ph?n có giá tr? 0 trong chu?i; khi t?ng th?i gian = 0 thì tr? v? N'0' (không NULL).
  FUNCTION format_tg_from_days(p_ngay_bat DATE, p_so_ngay NUMBER, p_dang NUMBER) RETURN NVARCHAR2 IS
    v_ref DATE := NVL(p_ngay_bat, DATE '1900-01-01');
    v_y NUMBER; v_m NUMBER; v_d NUMBER;
    v_total_thang NUMBER;
  BEGIN
    IF p_so_ngay IS NULL OR p_so_ngay < 0 THEN RETURN NULL; END IF;
    diff_ymd(v_ref, v_ref + p_so_ngay, v_y, v_m, v_d);
    IF p_dang = 1 THEN
      v_total_thang := NVL(v_y, 0) * 12 + NVL(v_m, 0);
      IF v_total_thang = 0 AND NVL(v_d, 0) = 0 THEN
        RETURN TO_NCHAR(0);
      END IF;
      IF v_total_thang > 0 AND NVL(v_d, 0) > 0 THEN
        RETURN TO_NCHAR(v_total_thang) || u' Th\00e1ng ' || TO_NCHAR(v_d) || u' ng\00e0y';
      ELSIF v_total_thang > 0 THEN
        RETURN TO_NCHAR(v_total_thang) || u' Th\00e1ng';
      ELSE
        RETURN TO_NCHAR(v_d) || u' ng\00e0y';
      END IF;
    ELSE
      RETURN format_nam_thang_ngay_omit_zero(v_y, v_m, v_d);
    END IF;
  END format_tg_from_days;

  -- B? d?n h?u t? 0 tháng / 0 ngày ?? kh?p DM_MA_THOI_GIANS.MTG_TITLE (vd danh m?c "1 n?m" vs chu?i tính "1 n?m 0 tháng 0 ngày")
  FUNCTION strip_zero_suffix_nam_thang_ngay(p_text IN NVARCHAR2) RETURN NVARCHAR2 IS
    v NVARCHAR2(4000);
  BEGIN
    IF p_text IS NULL THEN
      RETURN NULL;
    END IF;
    v := TRIM(p_text);
    IF REGEXP_LIKE(v, '^0\s+n?m\s+', 'i') THEN
      RETURN TRIM(REGEXP_REPLACE(v, '^0\s+n?m\s+', '', 1, 0, 'i'));
    END IF;
    IF REGEXP_LIKE(v, '\s+0\s+tháng\s+0\s+ngày\s*$', 'i') THEN
      RETURN TRIM(REGEXP_REPLACE(v, '\s+0\s+tháng\s+0\s+ngày\s*$', '', 1, 0, 'i'));
    END IF;
    IF REGEXP_LIKE(v, '\s+0\s+ngày\s*$', 'i') THEN
      RETURN TRIM(REGEXP_REPLACE(v, '\s+0\s+ngày\s*$', '', 1, 0, 'i'));
    END IF;
    IF REGEXP_LIKE(v, '\s+0\s+tháng\s*$', 'i') THEN
      RETURN TRIM(REGEXP_REPLACE(v, '\s+0\s+tháng\s*$', '', 1, 0, 'i'));
    END IF;
    RETURN v;
  END strip_zero_suffix_nam_thang_ngay;

  FUNCTION lookup_mtg_ma_for_nam_thang_ngay_title(p_tg_text IN NVARCHAR2) RETURN NVARCHAR2 IS
    v_try NVARCHAR2(4000);
    v_next NVARCHAR2(4000);
    v_id   NVARCHAR2(200);
    v_step PLS_INTEGER;
  BEGIN
    IF p_tg_text IS NULL OR TRIM(p_tg_text) IS NULL THEN
      RETURN NULL;
    END IF;
    v_try := TRIM(p_tg_text);
    FOR v_step IN 1..8 LOOP
      BEGIN
        SELECT y.MTG_MA
          INTO v_id
          FROM (
            SELECT dmtg.MTG_MA
              FROM QLPN.DM_MA_THOI_GIANS dmtg
             WHERE NVL(dmtg.IS_DELETED, 0) = 0
               AND UPPER(TRIM(CAST(dmtg.MTG_TITLE AS NVARCHAR2(4000)))) = UPPER(v_try)
             ORDER BY dmtg.MTG_MA
          ) y
         WHERE ROWNUM = 1;
        RETURN v_id;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          NULL;
      END;
      v_next := strip_zero_suffix_nam_thang_ngay(v_try);
      EXIT WHEN v_next IS NULL OR v_next = v_try;
      v_try := v_next;
    END LOOP;
    RETURN NULL;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN NULL;
  END lookup_mtg_ma_for_nam_thang_ngay_title;

  FUNCTION FN_TINH_THOI_GIAN_DA_CHAP_HANH(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NUMBER IS
    v_ngay_bat DATE; v_tg_da NUMBER; v_tg_con NUMBER; v_ngay_xet_tl DATE;
  BEGIN
    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    RETURN v_tg_da;
  EXCEPTION WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_THOI_GIAN_DA_CHAP_HANH;

  FUNCTION FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2 IS
    v_ngay_bat DATE; v_tg_da NUMBER; v_tg_con NUMBER; v_ngay_xet_tl DATE;
  BEGIN
    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    -- Gi?ng CON_LAI_*: ch? format khi ?? m?c; tg_da = 0 ? format_tg_from_days tr? N'0';
    IF v_ngay_bat IS NULL OR v_tg_da IS NULL OR v_ngay_xet_tl IS NULL THEN RETURN NULL; END IF;
    RETURN format_tg_from_days(v_ngay_bat, v_tg_da, 1);
  EXCEPTION WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_THOI_GIAN_DA_CHAP_HANH_THANG_NGAY;

  FUNCTION FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2 IS
    v_ngay_bat DATE; v_tg_da NUMBER; v_tg_con NUMBER; v_ngay_xet_tl DATE;
  BEGIN
    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    IF v_ngay_bat IS NULL OR v_tg_da IS NULL OR v_ngay_xet_tl IS NULL THEN RETURN NULL; END IF;
    RETURN format_tg_from_days(v_ngay_bat, v_tg_da, 2);
  EXCEPTION WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY;

  FUNCTION FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY_MA_TG(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2 IS
    v_tg_text NVARCHAR2(200);
  BEGIN
    v_tg_text := FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY(p_id_pham_nhan, p_ngay_xet);
    IF v_tg_text IS NULL THEN
      RETURN NULL;
    END IF;

    RETURN lookup_mtg_ma_for_nam_thang_ngay_title(v_tg_text);
  END FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY_MA_TG;

  FUNCTION FN_TINH_THOI_GIAN_CON_LAI(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NUMBER IS
    v_ngay_bat DATE; v_tg_da NUMBER; v_tg_con NUMBER; v_ngay_xet_tl DATE;
  BEGIN
    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    RETURN v_tg_con;
  EXCEPTION WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_THOI_GIAN_CON_LAI;

  FUNCTION FN_TINH_THOI_GIAN_CON_LAI_THANG_NGAY(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2 IS
    v_ngay_bat DATE; v_tg_da NUMBER; v_tg_con NUMBER; v_ngay_xet_tl DATE;
    v_moc_con    DATE;
  BEGIN
    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    IF v_ngay_bat IS NULL OR v_tg_con IS NULL OR v_ngay_xet_tl IS NULL THEN RETURN NULL; END IF;
    IF v_tg_con = 0 THEN
      RETURN u'Kh\00f4ng';
    END IF;
    -- M?c = TRUNC(ngày xét hi?u l?c), kh?p p_tg_con = TRUNC(ngày h?t án) - TRUNC(ngày xét): diff_ymd(xét..xét+con) = diff_ymd(xét..h?t án), tránh tách hai ?o?n t? ngày b?t v?i ngày b?t+tg_da gây c?ng chu?i > án.
    v_moc_con := v_ngay_xet_tl;
    RETURN format_tg_from_days(v_moc_con, v_tg_con, 1);
  EXCEPTION WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_THOI_GIAN_CON_LAI_THANG_NGAY;

  FUNCTION FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2 IS
    v_ngay_bat DATE; v_tg_da NUMBER; v_tg_con NUMBER; v_ngay_xet_tl DATE;
    v_moc_con    DATE;
  BEGIN
    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    IF v_ngay_bat IS NULL OR v_tg_con IS NULL OR v_ngay_xet_tl IS NULL THEN RETURN NULL; END IF;
    IF v_tg_con = 0 THEN
      RETURN u'Kh\00f4ng';
    END IF;
    v_moc_con := v_ngay_xet_tl;
    RETURN format_tg_from_days(v_moc_con, v_tg_con, 2);
  EXCEPTION WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY;

  FUNCTION FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY_MA_TG(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NVARCHAR2 IS
    v_tg_text NVARCHAR2(200);
  BEGIN
    v_tg_text := FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY(p_id_pham_nhan, p_ngay_xet);
    IF v_tg_text IS NULL THEN
      RETURN NULL;
    END IF;

    RETURN lookup_mtg_ma_for_nam_thang_ngay_title(v_tg_text);
  END FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY_MA_TG;

  FUNCTION FN_TINH_NGAY_THA(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN DATE IS
    v_ngay_bat       DATE;
    v_tg_da          NUMBER;
    v_tg_con         NUMBER;
    v_ngay_xet_tl    DATE;
    v_ngay_tha_calc  DATE;
    v_an_phat        NVARCHAR2(2000);
    v_an_phat_norm   NVARCHAR2(4000);
    v_cnt            NUMBER;
    v_ngay_xet_eff   DATE;
  BEGIN
    IF p_id_pham_nhan IS NULL THEN
      RETURN NULL;
    END IF;

    v_ngay_xet_eff := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));

    -- ?i?u ki?n ch?n ngày tha (tr?n/hoãn m?/T?C m?/trích m?): m?t round-trip EXISTS
    BEGIN
      SELECT 1 INTO v_cnt
        FROM DUAL
       WHERE EXISTS (
               SELECT 1
                 FROM QLPN.TRON_TRAIS tt
                WHERE tt.PHAM_NHAN_ID = p_id_pham_nhan
                  AND NVL(tt.IS_DELETED, 0) = 0
                  AND tt.NGAY_TRON IS NOT NULL
                  AND tt.NGAY_BAT_LAI IS NULL
                  AND TRUNC(tt.NGAY_TRON) <= v_ngay_xet_eff
             )
          OR EXISTS (
               SELECT 1
                 FROM QLPN.HOAN_THI_HANH_ANS h
                WHERE h.PHAM_NHAN_ID = p_id_pham_nhan
                  AND NVL(h.IS_DELETED, 0) = 0
                  AND h.NGAY_HOAN IS NOT NULL
                  AND h.NGAY_THI_HANH_AN IS NULL
                  AND TRUNC(h.NGAY_HOAN) <= v_ngay_xet_eff
             )
          OR EXISTS (
               SELECT 1
                 FROM QLPN.TAM_DINH_CHIS td
                WHERE td.PHAM_NHAN_ID = p_id_pham_nhan
                  AND NVL(td.IS_DELETED, 0) = 0
                  AND COALESCE(td.TU_NGAY, td.NGAY_TDC) IS NOT NULL
                  AND td.NGAY_LAI IS NULL
                  AND TRUNC(COALESCE(td.TU_NGAY, td.NGAY_TDC)) <= v_ngay_xet_eff
             )
          OR EXISTS (
               SELECT 1
                 FROM QLPN.TRICH_XUATS tx
                WHERE tx.PHAM_NHAN_ID = p_id_pham_nhan
                  AND NVL(tx.IS_DELETED, 0) = 0
                  AND tx.TX_NGAY_TRICH_XUAT IS NOT NULL
                  AND tx.TX_NGAY_TRA IS NULL
                  AND TRUNC(tx.TX_NGAY_TRICH_XUAT) <= v_ngay_xet_eff
             );
      RETURN NULL;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        NULL;
    END;

    -- L?y THA_AN_PHAT ?? ki?m tra chung thân
    SELECT tha.THA_AN_PHAT
      INTO v_an_phat
      FROM (
        SELECT t.THA_AN_PHAT,
               ROW_NUMBER() OVER (ORDER BY COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) AS rn
          FROM QLPN.PN_THI_HANH_AN t
         WHERE t.THA_PNLAI_LICH_ID = p_id_pham_nhan
           AND NVL(t.IS_DELETED, 0) = 0
           AND COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU) IS NOT NULL
           AND TRUNC(COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) <= v_ngay_xet_eff
           AND (t.THA_NGAY_HET_HAN IS NULL OR TRUNC(t.THA_NGAY_HET_HAN) >= v_ngay_xet_eff)
      ) tha
     WHERE tha.rn = 1;

    -- Chung thân thu?n (có "chung thân" nh?ng không có "gi?m xu?ng") ? NULL
    v_an_phat_norm := UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(v_an_phat), u'')));
    IF v_an_phat IS NOT NULL
       AND v_an_phat_norm LIKE '%' || 'CHUNGTHAN' || '%'
       AND v_an_phat_norm NOT LIKE '%' || 'GIAMXUONG' || '%'
    THEN
      RETURN NULL;
    END IF;

    IF v_an_phat_norm LIKE '%' || 'TUHINH' || '%' THEN
      RETURN NULL;
    END IF;

    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    IF v_ngay_bat IS NULL OR v_tg_da IS NULL THEN
      RETURN NULL;
    END IF;

    v_ngay_tha_calc := ngay_het_an_sau_dieuchinh(v_ngay_bat, v_an_phat, p_id_pham_nhan);
    IF v_ngay_tha_calc IS NULL THEN
      RETURN NULL;
    END IF;
    IF TRUNC(v_ngay_tha_calc) < TRUNC(v_ngay_xet_tl) THEN
      RETURN TRUNC(v_ngay_xet_tl);
    END IF;
    RETURN TRUNC(v_ngay_tha_calc);

  EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN NULL;
    WHEN OTHERS THEN RETURN NULL;
  END FN_TINH_NGAY_THA;

  FUNCTION FN_DA_CHAP_HANH_DAT_TY_LE(
    p_id_pham_nhan IN NUMBER,
    p_ratio        IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NUMBER IS
    v_ngay_bat       DATE;
    v_tg_da          NUMBER;
    v_tg_con         NUMBER;
    v_ngay_xet_tl    DATE;
    v_ngay_het       DATE;
    v_an_phat        NVARCHAR2(2000);
    v_tong_thang     NUMBER;
    v_thang_nguong   NUMBER;
    v_nguyen_thang   NUMBER;
    v_le_thang       NUMBER;
    v_ngay_trong_thang NUMBER;
    v_ngay_nguong    DATE;
  BEGIN
    IF p_id_pham_nhan IS NULL OR p_ratio IS NULL OR p_ratio <= 0 THEN
      RETURN NULL;
    END IF;

    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    IF v_ngay_bat IS NULL OR v_tg_da IS NULL OR v_tg_con IS NULL THEN
      RETURN NULL;
    END IF;

    BEGIN
      SELECT tha.THA_AN_PHAT
        INTO v_an_phat
        FROM (
          SELECT t.THA_AN_PHAT,
                 ROW_NUMBER() OVER (ORDER BY COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) AS rn
            FROM QLPN.PN_THI_HANH_AN t
           WHERE t.THA_PNLAI_LICH_ID = p_id_pham_nhan
             AND NVL(t.IS_DELETED, 0) = 0
             AND COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU) IS NOT NULL
             AND TRUNC(COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) <= NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE))
             AND (t.THA_NGAY_HET_HAN IS NULL OR TRUNC(t.THA_NGAY_HET_HAN) >= NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE)))
        ) tha
       WHERE tha.rn = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_an_phat := NULL;
    END;

    v_ngay_het := ngay_het_an_sau_dieuchinh(v_ngay_bat, v_an_phat, p_id_pham_nhan);
    IF v_ngay_het IS NULL THEN
      RETURN NULL;
    END IF;

    -- So sánh theo 1/2 s? tháng tr??c; n?u l? tháng thì m?i xét ??n ngày (t?ng tháng án = l?ch t? ngày b?t ??n ngày h?t)
    v_tong_thang := ROUND(MONTHS_BETWEEN(TRUNC(v_ngay_het), TRUNC(v_ngay_bat)), 0);
    IF v_tong_thang IS NULL OR v_tong_thang <= 0 THEN
      RETURN NULL;
    END IF;

    -- Ng??ng tháng theo t? l? (tháng = MONTHS_BETWEEN ngày h?t l?ch và ngày b?t, làm tròn)
    v_thang_nguong := p_ratio * v_tong_thang;
    v_nguyen_thang := FLOOR(v_thang_nguong);
    v_le_thang := v_thang_nguong - v_nguyen_thang;

    v_ngay_nguong := ADD_MONTHS(v_ngay_bat, v_nguyen_thang);
    IF v_le_thang > 0.0001 THEN
      v_ngay_trong_thang := ADD_MONTHS(v_ngay_bat, v_nguyen_thang + 1) - ADD_MONTHS(v_ngay_bat, v_nguyen_thang);
      v_ngay_nguong := v_ngay_nguong + (v_le_thang * v_ngay_trong_thang);
    END IF;

    -- Ngày ?ã ??t >= ngày ng??ng (b?t 14/09, ng??ng 14/03 ? 13/03 ch?a ??t)
    IF TRUNC(v_ngay_bat + v_tg_da) >= TRUNC(v_ngay_nguong) THEN
      RETURN 1;
    ELSE
      RETURN 0;
    END IF;

  EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
  END FN_DA_CHAP_HANH_DAT_TY_LE;

  FUNCTION FN_DA_CHAP_HANH_DAT_SO_NAM(
    p_id_pham_nhan IN NUMBER,
    p_so_nam       IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN NUMBER IS
    v_ngay_bat   DATE;
    v_tg_da      NUMBER;
    v_tg_con     NUMBER;
    v_ngay_xet_tl DATE;
    v_nguong     NUMBER;
  BEGIN
    IF p_id_pham_nhan IS NULL OR p_so_nam IS NULL OR p_so_nam <= 0 THEN
      RETURN NULL;
    END IF;

    get_tg_da_va_con(p_id_pham_nhan, p_ngay_xet, v_ngay_bat, v_tg_da, v_tg_con, v_ngay_xet_tl);
    IF v_ngay_bat IS NULL OR v_tg_da IS NULL THEN
      RETURN NULL;
    END IF;

    -- Ng??ng theo l?ch th?c: s? ngày th?c t? c?a p_so_nam n?m t? ngày b?t (ADD_MONTHS tính n?m nhu?n ?úng)
    v_nguong := TRUNC(ADD_MONTHS(v_ngay_bat, p_so_nam * 12)) - TRUNC(v_ngay_bat);

    IF v_tg_da >= v_nguong THEN
      RETURN 1;
    END IF;

    RETURN 0;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN NULL;
  END FN_DA_CHAP_HANH_DAT_SO_NAM;

  FUNCTION FN_GET_CHI_TIET_THOI_GIAN_THI_HANH(
    p_id_pham_nhan IN NUMBER,
    p_ngay_xet     IN DATE DEFAULT NULL
  ) RETURN QLPN.TYP_TINH_AN_CHI_TIET_TBL PIPELINED IS
    v_ngay_xet DATE;
    v_ngay_ra_trai DATE;
    v_ngay_tdc_mo  DATE;
    v_ngay_bat DATE;
  BEGIN
    IF p_id_pham_nhan IS NULL THEN
      RETURN;
    END IF;

    v_ngay_xet := NVL(TRUNC(p_ngay_xet), TRUNC(SYSDATE));

    -- Clamp ngày xét theo m?c nghi?p v? ?? chi ti?t kh?p logic tính t?ng
    -- 1) Có ngày ra tr?i/tha thì không v??t qua m?c này
    BEGIN
      SELECT MIN(TRUNC(k.KTRT_NGAY_THA))
        INTO v_ngay_ra_trai
        FROM QLPN.PN_KET_THUC_RA_TRAIS k
       WHERE k.KTRT_PN_LAI_LICH_ID = p_id_pham_nhan
         AND NVL(k.IS_DELETED, 0) = 0
         AND k.KTRT_NGAY_THA IS NOT NULL
         AND TRUNC(k.KTRT_NGAY_THA) <= v_ngay_xet;
    EXCEPTION
      WHEN OTHERS THEN
        v_ngay_ra_trai := NULL;
    END;

    IF v_ngay_ra_trai IS NOT NULL THEN
      v_ngay_xet := LEAST(v_ngay_xet, v_ngay_ra_trai);
    END IF;

    -- 2) N?u ?ang t?m ?ình ch? m? (NGAY_LAI IS NULL) thì ch?n t?i ngày m? t?m ?ình ch?
    BEGIN
      SELECT MIN(TRUNC(COALESCE(td.TU_NGAY, td.NGAY_TDC)))
        INTO v_ngay_tdc_mo
        FROM QLPN.TAM_DINH_CHIS td
       WHERE td.PHAM_NHAN_ID = p_id_pham_nhan
         AND NVL(td.IS_DELETED, 0) = 0
         AND COALESCE(td.TU_NGAY, td.NGAY_TDC) IS NOT NULL
         AND td.NGAY_LAI IS NULL
         AND TRUNC(COALESCE(td.TU_NGAY, td.NGAY_TDC)) <= v_ngay_xet;
    EXCEPTION
      WHEN OTHERS THEN
        v_ngay_tdc_mo := NULL;
    END;

    IF v_ngay_tdc_mo IS NOT NULL THEN
      v_ngay_xet := LEAST(v_ngay_xet, v_ngay_tdc_mo);
    END IF;

    -- L?y ngày b?t t? THA ??i di?n (cùng logic get_tg_da_va_con)
    BEGIN
      SELECT TRUNC(tha.ngay_bat)
        INTO v_ngay_bat
        FROM (
          SELECT COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU) AS ngay_bat,
                 ROW_NUMBER() OVER (ORDER BY COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) AS rn
            FROM QLPN.PN_THI_HANH_AN t
           WHERE t.THA_PNLAI_LICH_ID = p_id_pham_nhan
             AND NVL(t.IS_DELETED, 0) = 0
             AND COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU) IS NOT NULL
             AND TRUNC(COALESCE(t.THA_NGAY_BAT, t.THA_NGAY_BAT_DAU_O_TU)) <= v_ngay_xet
             AND (t.THA_NGAY_HET_HAN IS NULL OR TRUNC(t.THA_NGAY_HET_HAN) >= v_ngay_xet)
        ) tha
       WHERE tha.rn = 1;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        v_ngay_bat := NULL;
    END;

    IF v_ngay_bat IS NULL THEN
      RETURN;
    END IF;

    FOR rec IN (
      SELECT LOAI, TU_NGAY, DEN_NGAY, SO_NGAY, THU_TU
        FROM (
          SELECT u'NG\00c0Y B\1eaeT' AS LOAI, v_ngay_bat AS TU_NGAY, v_ngay_bat AS DEN_NGAY, NULL AS SO_NGAY, 1 AS THU_TU FROM DUAL
          UNION ALL
          SELECT u'T\1ea0M \0110\00ccNH CH\1ec8',
                 TRUNC(GREATEST(COALESCE(td.TU_NGAY, td.NGAY_TDC), v_ngay_bat)),
                 TRUNC(LEAST(NVL(COALESCE(td.NGAY_LAI, td.NGAY_TDC), v_ngay_xet), v_ngay_xet)),
                 GREATEST(0, TRUNC(LEAST(NVL(COALESCE(td.NGAY_LAI, td.NGAY_TDC), v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(COALESCE(td.TU_NGAY, td.NGAY_TDC), v_ngay_bat)) + 1),
                 2
            FROM QLPN.TAM_DINH_CHIS td
           WHERE td.PHAM_NHAN_ID = p_id_pham_nhan AND NVL(td.IS_DELETED, 0) = 0 AND COALESCE(td.TU_NGAY, td.NGAY_TDC) IS NOT NULL
             AND COALESCE(td.TU_NGAY, td.NGAY_TDC) <= v_ngay_xet AND (COALESCE(td.NGAY_LAI, td.NGAY_TDC) IS NULL OR COALESCE(td.NGAY_LAI, td.NGAY_TDC) >= v_ngay_bat)
          UNION ALL
          SELECT u'HO\00c3N',
                 TRUNC(GREATEST(h.NGAY_HOAN, v_ngay_bat)),
                 TRUNC(LEAST(NVL(h.NGAY_THI_HANH_AN, v_ngay_xet), v_ngay_xet)),
                 GREATEST(0, TRUNC(LEAST(NVL(h.NGAY_THI_HANH_AN, v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(h.NGAY_HOAN, v_ngay_bat)) + 1),
                 3
            FROM QLPN.HOAN_THI_HANH_ANS h
           WHERE h.PHAM_NHAN_ID = p_id_pham_nhan AND NVL(h.IS_DELETED, 0) = 0 AND h.NGAY_HOAN IS NOT NULL
             AND h.NGAY_HOAN <= v_ngay_xet AND (h.NGAY_THI_HANH_AN IS NULL OR h.NGAY_THI_HANH_AN >= v_ngay_bat)
          UNION ALL
          SELECT u'TRICH XUAT',
                 TRUNC(GREATEST(tx.TX_NGAY_TRICH_XUAT, v_ngay_bat)),
                 TRUNC(LEAST(NVL(tx.TX_NGAY_TRA, v_ngay_xet), v_ngay_xet)),
                 GREATEST(0, TRUNC(LEAST(NVL(tx.TX_NGAY_TRA, v_ngay_xet), v_ngay_xet)) - TRUNC(GREATEST(tx.TX_NGAY_TRICH_XUAT, v_ngay_bat)) + 1),
                 4
            FROM QLPN.TRICH_XUATS tx
           WHERE tx.PHAM_NHAN_ID = p_id_pham_nhan
             AND NVL(tx.IS_DELETED, 0) = 0
             AND tx.TX_NGAY_TRICH_XUAT IS NOT NULL
             AND tx.TX_NGAY_TRICH_XUAT <= v_ngay_xet
             AND (tx.TX_NGAY_TRA IS NULL OR tx.TX_NGAY_TRA >= v_ngay_bat)
          UNION ALL
          SELECT u'TR\1ed0N',
                 TRUNC(GREATEST(tt.NGAY_TRON, v_ngay_bat)),
                 TRUNC(LEAST(NVL(tt.NGAY_BAT_LAI, v_ngay_xet), v_ngay_xet)),
                 CASE
                   WHEN tt.NGAY_BAT_LAI IS NOT NULL THEN GREATEST(0, TRUNC(LEAST(tt.NGAY_BAT_LAI, v_ngay_xet)) - TRUNC(GREATEST(tt.NGAY_TRON, v_ngay_bat)) + 1)
                   ELSE CASE WHEN tt.NGAY_TRON <= v_ngay_xet THEN GREATEST(0, v_ngay_xet - TRUNC(GREATEST(tt.NGAY_TRON, v_ngay_bat)) + 1) ELSE 0 END
                 END,
                 5
            FROM QLPN.TRON_TRAIS tt
           WHERE tt.PHAM_NHAN_ID = p_id_pham_nhan AND NVL(tt.IS_DELETED, 0) = 0 AND tt.NGAY_TRON IS NOT NULL
             AND tt.NGAY_TRON <= v_ngay_xet AND (tt.NGAY_BAT_LAI IS NULL OR tt.NGAY_BAT_LAI >= v_ngay_bat)
        )
       ORDER BY THU_TU, TU_NGAY
    ) LOOP
      PIPE ROW (QLPN.TYP_TINH_AN_CHI_TIET(rec.LOAI, rec.TU_NGAY, rec.DEN_NGAY, rec.SO_NGAY, rec.THU_TU));
    END LOOP;
    RETURN;

  EXCEPTION
    WHEN OTHERS THEN
      RAISE;
  END FN_GET_CHI_TIET_THOI_GIAN_THI_HANH;

  FUNCTION FN_GET_MUC_AN_ID_TU_AN_PHAT(
    p_tha_an_phat IN NVARCHAR2
  ) RETURN NUMBER IS
    v_upper NVARCHAR2(4000);
    v_norm  NVARCHAR2(4000);
    v_n     NUMBER;
    v_t     NUMBER;
    v_g     NUMBER;
    v_thang NUMBER;
    v_id    NUMBER;
    v_is_ct BOOLEAN;
  BEGIN
    IF p_tha_an_phat IS NULL OR TRIM(p_tha_an_phat) IS NULL THEN
      RETURN NULL;
    END IF;

    -- Hai tr??ng h?p ??c bi?t: so kh?p sau LOWER+TRIM (không dùng REGEXP — tránh PLS-00103 trên m?t s? b?n Oracle)
    v_norm := LOWER(TRIM(p_tha_an_phat));
    IF v_norm = u'chung th\00e2n gi\1ea3m xu\1ed1ng 20 n\0103m' THEN
      v_thang := 240;
      SELECT MIN(ma.ID)
        INTO v_id
        FROM QLPN.DM_MUC_ANS ma
       WHERE NVL(ma.IS_DELETED, 0) = 0
         AND ma.MA_TU < 900000
         AND v_thang >= ma.MA_TU
         AND v_thang <= ma.MA_DEN;
      RETURN v_id;
    END IF;
    IF v_norm = u'chung th\00e2n gi\1ea3m xu\1ed1ng 30 n\0103m' THEN
      v_thang := 360;
      SELECT MIN(ma.ID)
        INTO v_id
        FROM QLPN.DM_MUC_ANS ma
       WHERE NVL(ma.IS_DELETED, 0) = 0
         AND ma.MA_TU < 900000
         AND v_thang >= ma.MA_TU
         AND v_thang <= ma.MA_DEN;
      RETURN v_id;
    END IF;

    v_upper := UPPER(QLPN.FN_NORMALIZE_VN(NVL(TO_NCHAR(p_tha_an_phat), u'')));
    v_is_ct := v_upper LIKE '%' || 'CHUNGTHAN' || '%'
               AND v_upper NOT LIKE '%' || 'GIAMXUONG' || '%';

    IF v_is_ct THEN
      SELECT MIN(ma.ID)
        INTO v_id
        FROM QLPN.DM_MUC_ANS ma
       WHERE NVL(ma.IS_DELETED, 0) = 0
         AND ma.MA_TU >= 900000;
      RETURN v_id;
    END IF;

    v_n := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'NAM'), 0);
    v_t := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'THANG'), 0);
    v_g := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'NGAY'), 0);
    v_thang := v_n * 12 + v_t + v_g / 30;

    SELECT MIN(ma.ID)
      INTO v_id
      FROM QLPN.DM_MUC_ANS ma
     WHERE NVL(ma.IS_DELETED, 0) = 0
       AND ma.MA_TU < 900000
       AND v_thang >= ma.MA_TU
       AND v_thang <= ma.MA_DEN;

    RETURN v_id;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN NULL;
  END FN_GET_MUC_AN_ID_TU_AN_PHAT;

  PROCEDURE SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI(
    p_tha_pnlai_lich_id IN NUMBER DEFAULT NULL,
    p_ngay_xet          IN DATE   DEFAULT NULL
  ) IS
    v_da         NVARCHAR2(200);
    v_con        NVARCHAR2(200);
    v_muc_an_id  NVARCHAR2(2000);
    v_ok         NUMBER := 0;
    v_err        NUMBER := 0;
  BEGIN
    -- Không g?i FN trong m?nh ?? SET c?a UPDATE cùng b?ng PN_THI_HANH_AN mà hàm c?ng ??c b?ng này:
    -- trong ng? c?nh SQL có th? gây l?i/NULL; tính MTG_MA trong PL/SQL r?i gán scalar.
    -- Thông báo: SET SERVEROUTPUT ON (SQL*Plus/SQLcl) ho?c t??ng ???ng trên IDE ?? xem DBMS_OUTPUT.
    FOR r IN (
      SELECT t.ROWID AS rid,
             t.THA_PNLAI_LICH_ID AS pn_id,
             t.THA_AN_PHAT       AS tha_an_phat
        FROM QLPN.PN_THI_HANH_AN t
        INNER JOIN QLPN.PN_LAI_LICHS pll
                ON pll.ID = t.THA_PNLAI_LICH_ID
               AND NVL(pll.IS_DELETED, 0) = 0
        INNER JOIN QLPN.DM_TINH_TRANG_PHAM_NHANS ttpn
                ON ttpn.ID = pll.LL_TINH_TRANG_ID
               AND NVL(ttpn.IS_DELETED, 0) = 0
               AND ttpn.TTPN_MA IN ('111', '112', '113', '114')
       WHERE NVL(t.IS_DELETED, 0) = 0
         AND t.THA_PNLAI_LICH_ID IS NOT NULL
         AND (p_tha_pnlai_lich_id IS NULL OR t.THA_PNLAI_LICH_ID = p_tha_pnlai_lich_id)
    ) LOOP
      BEGIN
        v_da := FN_TINH_THOI_GIAN_DA_CHAP_HANH_NAM_THANG_NGAY_MA_TG(r.pn_id, p_ngay_xet);
        v_con := FN_TINH_THOI_GIAN_CON_LAI_NAM_THANG_NGAY_MA_TG(r.pn_id, p_ngay_xet);
        -- THA_AN_PHAT trong PN_THI_HANH_AN chính là MTG_TITLE (gi?ng quy ??c migrate),
        -- nên có th? tính THA_MUC_AN_ID tr?c ti?p t? THA_AN_PHAT.
        -- TO_NCHAR: tránh CAST(... AS NVAR                                                             CHAR2(2000)) l?ng trong g?i hàm (PLS-00103 trên m?t s? b?n Oracle).
        v_muc_an_id := FN_GET_MUC_AN_ID_TU_AN_PHAT(TO_NCHAR(r.tha_an_phat));
        UPDATE QLPN.PN_THI_HANH_AN t
           SET t.THA_THOI_GIAN_DA_CHAP_HANH = v_da,
               t.THA_MUC_AN_ID            = v_muc_an_id,
               t.THA_THOI_GIAN_CON_LAI      = v_con,
               t.LAST_MODIFICATION_TIME     = SYSTIMESTAMP
         WHERE t.ROWID = r.rid;
        IF SQL%ROWCOUNT > 0 THEN
          v_ok := v_ok + 1;
        END IF;
      EXCEPTION
        WHEN OTHERS THEN
          v_err := v_err + 1;
          DBMS_OUTPUT.PUT_LINE(
            u'[SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI] Th\1ea5t b\1ea1i d\00f2ng THA_PNLAI_LICH_ID=' ||
            TO_NCHAR(r.pn_id) || u': ' || SQLERRM
          );
      END;
    END LOOP;

    IF v_err = 0 THEN
      DBMS_OUTPUT.PUT_LINE(
        u'[SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI] Th\00e0nh c\00f4ng: \0111\00e3 c\1eadp nh\1eadt ' ||
        TO_NCHAR(v_ok) || u' b\1ea3n ghi PN_THI_HANH_AN (THA_THOI_GIAN_DA_CHAP_HANH, THA_MUC_AN_ID, THA_THOI_GIAN_CON_LAI).'
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        u'[SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI] Ho\00e0n th\00e0nh c\00f3 l\1ed7i: th\00e0nh c\00f4ng ' ||
        TO_NCHAR(v_ok) || u' b\1ea3n ghi, l\1ed7i ' || TO_NCHAR(v_err) ||
        u' b\1ea3n ghi (xem t\1eebng d\00f2ng ph\00eda tr\00ean).'
      );
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE(
        u'[SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI] Th\1ea5t b\1ea1i to\00e0n procedure: ' || SQLERRM
      );
      RAISE;
  END SP_UPDATE_PN_THI_HANH_AN_THOI_GIAN_DA_VA_CON_LAI;

END PKG_TINH_AN_V1;





/
--------------------------------------------------------
--  DDL for Function ADD_MA_MUC_TG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."ADD_MA_MUC_TG" (vma1 varchar2, vma2 varchar2, vOper number default 1) return varchar2 is
  vnam    number;
  vthang  number;
  vngay   number;
  v1nam   number;
  v2nam   number;
  v1thang number;
  v2thang number;
  v1ngay  number;
  v2ngay  number;
begin
  select nam, thang, ngay into v1nam, v1thang, v1ngay from ma_muc_thoi_gian where ma=vma1;
  select nam, thang, ngay into v2nam, v2thang, v2ngay from ma_muc_thoi_gian where ma=vma2;
  if vOper<>-1 then
    vngay:=v1ngay+v2ngay;
    vthang:=v1thang+v2thang+trunc(vngay/30);
    vngay:=mod(vngay,30);
    vnam:=v1nam+v2nam+trunc(vthang/12);
    vthang:=mod(vthang,12);
  else
    vngay:=((v1nam*12+v1thang)*30+v1ngay)-((v2nam*12+v2thang)*30+v2ngay);
    vthang:=trunc(vngay/30);
    vnam:=trunc(vthang/12);
    vthang:=mod(vthang,12);
    vngay:=mod(vngay,30);
  end if;
 return lpad(vnam,2,'0')||lpad(vthang,2,'0')||lpad(vngay,2,'0');
end;



