  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."BODAU_HOTEN" (ho varchar2, ten_dem varchar2, ten varchar2) return varchar2 is
Begin
  return replace(bo_dau(ltrim(rtrim(ho))||' '||ltrim(rtrim(ten_dem))||' '||ltrim(rtrim(ten))),'  ',' ');
end;





