  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."BODAU_TENHO" (ho_ten varchar2) return varchar2 Deterministic is

  vTen varchar2(50);
  vDem varchar2(100);
  vHo  varchar2(50);
  --khanh sua ngay 13/11/2013
  --ly do khi tra cuu chi danh Ten Ho thi ham tra ve sai
  --vi du Pham Khanh tra ve KHANHPHAMPHAM
  tmp varchar2(100);--khanh them
Begin
  vTen:=substr(ho_ten,instr(ho_ten,' ',-1)+1);
  vDem:=substr(ho_ten,1,instr(ho_ten,' ',-1)-1);
	vDem:=substr(vDem,instr(vDem,' ')+1);
	vHo:=substr(ho_ten,1,instr(ho_ten,' ')-1);
  --khanh them
  if instr(ho_ten,' ')= 0 then
   tmp:=bo_dau(ho_ten);
  else
   if instr(ho_ten,' ',instr(ho_ten,' ')+1) =0 then --chi co ho va ten
    tmp:=bo_dau(ltrim(rtrim(vTen))||' '||ltrim(rtrim(vHo)));
   else
    tmp:=bo_dau(ltrim(rtrim(vTen))||' '||ltrim(rtrim(vHo))||' '||ltrim(rtrim(vDem)));
   end if;
  end if;
  --end khanh them
  --return bo_dau(ltrim(rtrim(vTen))||' '||ltrim(rtrim(vHo))||' '||ltrim(rtrim(vDem)));
  return tmp;
end;




