  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."BO_DAU" (strin varchar2) return varchar2 Deterministic  is
 str1 varchar2(1000):='Aaàá¿¿ãA¿¿¿¿¿Â¿¿¿¿â¿Uùú¿¿uuU¿¿¿¿¿Eèé¿¿¿Êê¿¿¿¿¿Ô¿¿¿¿¿Oo¿¿ô¿¿¿Oòó¿¿õìí¿¿iY¿ý¿¿¿Ðd ';
 str2 varchar2(1000):='AAAAAAAAAAAAAAAAAAAAUUUUUUUUUUUUUEEEEEEEEEEEEEOOOOOOOOOOOOOOOOOOOOIIIIIYYYYYYDD';
 str3 varchar2(1000):='` ´ ¿ ¿ ~ ';
 str4 varchar2(1000):=' ';
 vReturn varchar2(2000);
Begin
--vReturn:=upper(translate(upper(strin),upper(str1),str2));
vReturn:=upper(translate(upper(strin),upper(str3),str4));
vReturn:=upper(translate(upper(vReturn),upper(str1),str2));
return vReturn;
End;






