--  DDL for Function CADD_MONTHS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."CADD_MONTHS" (vNgay date, vSo number) Return Date Is
	vDate date;
	dRet  date;
Begin
	if vNgay is null then
		return null;
	end if;
	vDate:=add_months(vNgay,vSo);
	if to_char(vNgay,'dd')<to_char(vDate,'dd') then
  	vDate:=to_date(to_char(vNgay,'dd')||'/'||to_char(vDate,'mm/yyyy'),'dd/mm/yyyy');
	end if;
  return vDate;
End;





