--------------------------------------------------------
--  DDL for Function CONVERT_ARAB
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."CONVERT_ARAB" (so NUMBER) RETURN VARCHAR2 IS
  TYPE strarr IS TABLE OF VARCHAR2(7);
  tab1 strarr := strarr('không','m?t','hai','ba','b?n','n?m','sáu','b?y','tám','chín','m??i');
  tab2 strarr := strarr('','m?t','hai','ba','t?','l?m','sáu','b?y','tám','chín','m??i');
  n    NUMBER;
  m    NUMBER;
  temp VARCHAR(256);
BEGIN
  n := so;
  IF n < 0 THEN
    n := -n;
  END IF;

  IF n <= 10 THEN
    temp := tab1(n + 1) || ' ';

  ELSIF n < 20 THEN
    IF n = 15 THEN
      temp := tab1(11) || ' ' || tab2(6) || ' ';
