/
--------------------------------------------------------
--  DDL for Function CONVERT_DURATION_TO_DAYS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."CONVERT_DURATION_TO_DAYS" (p_duration IN VARCHAR2)
RETURN NUMBER
IS
    v_days NUMBER := 0;
    v_text VARCHAR2(200);
    v_nam NUMBER;
    v_thang NUMBER;
    v_ngay NUMBER;
BEGIN
    IF p_duration IS NULL OR TRIM(p_duration) IS NULL THEN
        RETURN 0;
    END IF;

    v_text := LOWER(p_duration);

    -- Extract "X nam" or "X n?m"
    v_nam := REGEXP_SUBSTR(v_text, '(\d+)\s*n[?a]m', 1, 1, NULL, 1);
    IF v_nam IS NOT NULL THEN
        v_days := v_days + TO_NUMBER(v_nam) * 365;
    END IF;

    -- Extract "X thang" or "X tháng"
    v_thang := REGEXP_SUBSTR(v_text, '(\d+)\s*th[?a]ng', 1, 1, NULL, 1);
    IF v_thang IS NOT NULL THEN
        v_days := v_days + TO_NUMBER(v_thang) * 30;
    END IF;

    -- Extract "X ngay" or "X ngày"
    v_ngay := REGEXP_SUBSTR(v_text, '(\d+)\s*ng[àa]y', 1, 1, NULL, 1);
    IF v_ngay IS NOT NULL THEN
        v_days := v_days + TO_NUMBER(v_ngay);
    END IF;

    RETURN v_days;
END;





/
--------------------------------------------------------
--  DDL for Function CONVERT_HOTEN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."CONVERT_HOTEN" (str varchar2) return varchar2 is
	strList    varchar2(100):=lower(str)||' ';
	i          number;
	pos        number;
	currstr    varchar2(100);
	the_return varchar2(100);
begin
	for i in 1..length(strList) loop
		pos:=instr(strList,' ');
		if pos>0  then
			currstr:=substr(strList,1,pos);
			currstr:=upper(substr(currstr,1,1))||substr(currstr,2);
			the_return:=the_return||currstr||'';
			strList:=ltrim(substr(strList,pos+1));
		end if;
	end loop;
	return the_return;
end;





/
--------------------------------------------------------
--  DDL for Function CONVERT_NGAY_TO_NAM_THANG_NGAY
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."CONVERT_NGAY_TO_NAM_THANG_NGAY" (p_days IN NUMBER)
RETURN VARCHAR2
IS
    v_nam NUMBER;
    v_thang NUMBER;
    v_ngay NUMBER;
    v_result VARCHAR2(100);
BEGIN
    IF p_days IS NULL OR p_days <= 0 THEN
        RETURN '0 ngày';
    END IF;

    v_nam := TRUNC(p_days / 365);
    v_thang := TRUNC(MOD(p_days, 365) / 30);
    v_ngay := MOD(p_days, 30);

    v_result := '';
    IF v_nam > 0 THEN
        v_result := v_result || v_nam || ' n?m ';
    END IF;
    IF v_thang > 0 THEN
        v_result := v_result || v_thang || ' tháng ';
    END IF;
    IF v_ngay > 0 OR (v_nam = 0 AND v_thang = 0) THEN
        v_result := v_result || v_ngay || ' ngày';
    END IF;

    RETURN TRIM(v_result);
END;






