--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."COUNTND" (vTab varchar2,curValue varchar2) return varchar2 is
 strSQL varchar2(2000);
 result varchar2(200);
 cCount number;
begin
 strSQL:='Select count(*) from '||vTab||' where upper(nd) like upper('||'''%'||curValue||'%'')';
 execute immediate strSql into cCount;
 if cCount>1 or cCount=0 then
   strSQL:='Select ma from '||vTab||' where upper(nd)=upper('||''''||curValue||''')';
   execute immediate strSql into result;
	 return result;
 else
 	 strSQL:='Select ma from '||vTab||' where upper(nd) like upper('||'''%'||curValue||'%'')';
	 execute immediate strSql into result;
	 return result;
 end if;
 exception
	when no_data_found then return null;
	when others then return null;
end;





