	 	The_SQL:=subStr(The_SQL,1,instr(The_SQL,'FROM')-1);
	 	The_SQL:=ltrim(rtrim(The_SQL));
	 	The_SQL:=replace(The_SQL,',',';');
	 	cCount:=CountStr(The_SQL)+1;
	 	for i in 1..cCount
	 	loop
			The_Col:=GetStr(The_SQL,i);
 			The_SQL:=replace(The_SQL,The_Col,The_Col||' COL'||to_char(i));
	 	end loop;

	 	The_SQL:=The_SQL||substr(strSQL,instr(upper(strSQL),' FROM'));
	 	The_SQL:=replace(The_SQL,';',',');
	 	--Execute immediate 'Drop table S_Dynamic_Report';
	 	--Execute immediate 'Create table S_Dynamic_Report as '||The_SQL;
	 	Return 'CREATE TABLE S_DYNAMIC_REPORT AS '||upper(The_SQL);
End;




