  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."DATE_MINUS" (vDate1 date, vDate2 date, vPart char) Return number Is
  vSonam1     number;
  vSothang1   number;
  vSongay1     number;
  vSonam2     number;
  vSothang2   number;
  vSongay2     number;
  vSonam       number;
  vSothang     number;
  vSongay     number;
  Date1        date;
  Date2        date;
Begin
  if vDate1 is null or vDate2 is null then
    return null;
  end if;
  Date1:=vDate1;
  Date2:=vDate2;

  if vDate1<=vDate2 then
    Date1:=vDate1;
    Date2:=vDate2;
  else
    Date2:=vDate1;
    Date1:=vDate2;
  end if;
  /*
