    vSongay1:=vSongay1+30;
    vSothang1:=vSothang1-1;
    vSongay:=vSongay1-vSongay2;
  else
    vSongay:=vSongay1-vSongay2;
  end if;
  */
  vSongay := Date2 - add_months(Date1,months_between(Date2,Date1));
  /*
  if vSothang1<vSothang2 then
    vSothang1:=vSothang1+12;
    vSonam1:=vSonam1-1;
    vSothang:=vSothang1-vSothang2;
  else
    vSothang:=vSothang1-vSothang2;
  end if;
  */
  vSothang := mod(trunc(months_between(Date2,Date1)),12);
  vSonam:=trunc(trunc(months_between(Date2,Date1))/12);
  if upper(vPart)='D' then
    return vSongay;
  elsif upper(vPart)='M' then
    return vSothang;
  elsif upper(vPart)='Y' then
    return vSonam;
  elsif upper(vPart)='MF' then
    return vSonam*12+vSothang;
  end if;
