--  DDL for Function DATE_PLUS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."DATE_PLUS" (vDate date, vSonam number, vSothang number, vSongay number) Return Date Is
 vNam     number;
 vThang   number;
 vNgay    number;
 Songay    number;
 DateRet   date;
 i         number;
Begin
  if vDate is null then
    return null;
  end if;
  i:=0;
  Songay:=vSongay;
  while Songay<-30 loop
      i:=i+1;
      Songay:=30+Songay;
  end loop;
  while Songay>=30 loop
      i:=i-1;
      Songay:=Songay-30;
  end loop;
  DateRet:=cadd_months(vDate,nvl(vSonam,0)*12+nvl(vSothang,0)-i);
  if Songay<>0 then
    DateRet:=DateRet+Songay;
  end if;
  return DateRet;
End; -- Of Date_Plus
