/
--------------------------------------------------------
--  DDL for Function FC_PARSE_MTG_TO_ABC
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FC_PARSE_MTG_TO_ABC" (p_text NVARCHAR2)
RETURN VARCHAR2
IS
    v_years  NUMBER := 0;
    v_months NUMBER := 0;
    v_days   NUMBER := 0;
BEGIN
    -- =========================
    -- NULL ho?c r?ng ? 0|0|0
    -- =========================
    IF p_text IS NULL OR TRIM(p_text) = '' THEN
        RETURN '0|0|0';
    END IF;

    -- =========================
    -- Parse N?M
    -- =========================
    IF REGEXP_LIKE(p_text, '([0-9]+)\s*n?m') THEN
        v_years := TO_NUMBER(
            REGEXP_SUBSTR(p_text, '([0-9]+)\s*n?m', 1, 1, NULL, 1)
        );
    END IF;

    -- =========================
    -- Parse THÁNG
    -- =========================
    IF REGEXP_LIKE(p_text, '([0-9]+)\s*tháng') THEN
        v_months := TO_NUMBER(
            REGEXP_SUBSTR(p_text, '([0-9]+)\s*tháng', 1, 1, NULL, 1)
        );
    END IF;

    -- =========================
    -- Parse NGÀY
    -- =========================
    IF REGEXP_LIKE(p_text, '([0-9]+)\s*ngày') THEN
        v_days := TO_NUMBER(
            REGEXP_SUBSTR(p_text, '([0-9]+)\s*ngày', 1, 1, NULL, 1)
        );
    END IF;

    -- =========================
    -- Return a|b|c
    -- =========================
    RETURN v_years || '|' || v_months || '|' || v_days;

EXCEPTION
    WHEN OTHERS THEN
        RETURN '-1';
END;





/
--------------------------------------------------------
--  DDL for Function FC_TINH_AN_GIAM_HINH_PHAT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FC_TINH_AN_GIAM_HINH_PHAT" (p_PN_ID NUMBER)
RETURN VARCHAR2
IS
    v_total_years  NUMBER := 0;
    v_total_months NUMBER := 0;
    v_total_days   NUMBER := 0;

    v_has_data BOOLEAN := FALSE;

    v_years  NUMBER;
    v_months NUMBER;
    v_days   NUMBER;
BEGIN
    FOR rec IN (
        SELECT dmtg.MTG_TITLE
        FROM TANG_GIAM_HINH_PHATS tghp
        JOIN DM_MA_THOI_GIANS dmtg 
          ON tghp.THOI_HAN_ID = dmtg.ID
        WHERE tghp.PHAM_NHAN_ID = p_PN_ID
          AND tghp.LOAI_TANG_GIAM_ID = 2 -- ? gi?m
          AND NVL(tghp.IS_DELETED, 0) = 0
          AND NVL(dmtg.IS_DELETED, 0) = 0
    ) LOOP

        v_has_data := TRUE;

        -- reset t?ng record
        v_years  := 0;
        v_months := 0;
        v_days   := 0;

        -- ? Validate
        IF rec.MTG_TITLE IS NULL THEN
            RETURN '-1';
        END IF;

        -- Parse n?m
        IF REGEXP_LIKE(rec.MTG_TITLE, '([0-9]+)\s*n?m') THEN
            v_years := TO_NUMBER(REGEXP_SUBSTR(rec.MTG_TITLE, '([0-9]+)\s*n?m', 1, 1, NULL, 1));
        END IF;

        -- Parse tháng
        IF REGEXP_LIKE(rec.MTG_TITLE, '([0-9]+)\s*tháng') THEN
            v_months := TO_NUMBER(REGEXP_SUBSTR(rec.MTG_TITLE, '([0-9]+)\s*tháng', 1, 1, NULL, 1));
        END IF;

        -- Parse ngày
        IF REGEXP_LIKE(rec.MTG_TITLE, '([0-9]+)\s*ngày') THEN
            v_days := TO_NUMBER(REGEXP_SUBSTR(rec.MTG_TITLE, '([0-9]+)\s*ngày', 1, 1, NULL, 1));
        END IF;

        -- C?ng d?n THÔ
        v_total_years  := v_total_years  + v_years;
        v_total_months := v_total_months + v_months;
        v_total_days   := v_total_days   + v_days;

    END LOOP;

	-- s?a ?o?n này
	IF NOT v_has_data THEN
	    RETURN '0|0|0';
	END IF;

    -- ? KHÔNG normalize
    RETURN v_total_years || '|' || v_total_months || '|' || v_total_days;

EXCEPTION
    WHEN OTHERS THEN
        RETURN '-1';
END;





