    -- Không có d? li?u
    IF v_count = 0 THEN
        RETURN '0|0|0';
    END IF;

    RETURN v_total_years || '|' || v_total_months || '|' || v_total_days;

EXCEPTION
    WHEN OTHERS THEN
        RETURN '-1';
END;





/
--------------------------------------------------------
--  DDL for Function FC_TINH_HOAN_THI_HANH_AN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FC_TINH_HOAN_THI_HANH_AN" (p_PN_ID NUMBER)
RETURN VARCHAR2
IS
    v_total_years  NUMBER := 0;
    v_total_months NUMBER := 0;
    v_total_days   NUMBER := 0;

    v_count NUMBER := 0;
BEGIN
    FOR rec IN (
        SELECT htha.NGAY_HOAN,
               htha.NGAY_THI_HANH_AN
        FROM HOAN_THI_HANH_ANS htha
        WHERE htha.PHAM_NHAN_ID = p_PN_ID
          AND NVL(htha.IS_DELETED, 0) = 0
    ) LOOP

        v_count := v_count + 1;

        -- ? Thi?u d? li?u ? return -1
        IF rec.NGAY_HOAN IS NULL OR rec.NGAY_THI_HANH_AN IS NULL THEN
            RETURN '-1';
        END IF;

        DECLARE
            v_start_date DATE := TRUNC(rec.NGAY_HOAN);
            v_end_date   DATE := TRUNC(rec.NGAY_THI_HANH_AN) + 1; -- ? +1 theo rule

            v_months NUMBER;
            v_years  NUMBER;
            v_month  NUMBER;
            v_days   NUMBER;
            v_tmp_date DATE;
        BEGIN
            -- T?ng tháng
            v_months := FLOOR(MONTHS_BETWEEN(v_end_date, v_start_date));

            -- Tách n?m + tháng
            v_years := FLOOR(v_months / 12);
            v_month := MOD(v_months, 12);

            -- Ngày l?
            v_tmp_date := ADD_MONTHS(v_start_date, v_months);
            v_days := v_end_date - v_tmp_date;

            -- C?ng d?n
            v_total_years  := v_total_years  + v_years;
            v_total_months := v_total_months + v_month;
            v_total_days   := v_total_days   + v_days;
        END;

    END LOOP;

    -- Không có d? li?u
    IF v_count = 0 THEN
        RETURN '0|0|0';
    END IF;

    RETURN v_total_years || '|' || v_total_months || '|' || v_total_days;

EXCEPTION
    WHEN OTHERS THEN
        RETURN '-1';
END;





