/
--------------------------------------------------------
--  DDL for Function FN_DIEU_KIEN_XLCT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_DIEU_KIEN_XLCT" (
    p_pham_nhan_id IN NUMBER,
    p_ky_giam_id   IN NUMBER,
    p_is_dac_biet  IN NUMBER
) RETURN NVARCHAR2
IS
    v_so_lan_giam   NUMBER := 0;
    v_du_quy        NUMBER := 0;

	C_LAN_DAU_TT CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - Gi?m l?n ??u (th??ng)');
	C_LAN_DAU_DB CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - Gi?m l?n ??u (??c bi?t)');
	C_LAN_SAU    CONSTANT NVARCHAR2(100) := TO_NCHAR('?? ?K - Gi?m l?n sau');
	C_KHONG_DU   CONSTANT NVARCHAR2(100) := TO_NCHAR('Không ?? ?K x?p lo?i');
BEGIN
    SELECT COUNT(*) INTO v_so_lan_giam
    FROM GIAM_THOI_HANS gth
    WHERE PHAM_NHAN_ID = p_pham_nhan_id
    AND TRUNC(gth.NGAY_XET) NOT IN (SELECT TRUNC(KGTH_NGAY_XET_GIAM) FROM GTH_KY_GIAM_THOI_HANS g WHERE g.ID = p_ky_giam_id)
    AND is_deleted = 0;

	v_du_quy := FN_XET_DU_DIEU_KIEN_QUY(p_pham_nhan_id, p_ky_giam_id).DU_DIEU_KIEN;

    IF v_du_quy = 0 THEN
        RETURN C_KHONG_DU;
    END IF; 

    IF v_so_lan_giam = 0 THEN
        IF p_is_dac_biet = 1 THEN
            RETURN C_LAN_DAU_DB;
        ELSE
            RETURN C_LAN_DAU_TT;
        END IF;
    END IF;

    RETURN C_LAN_SAU;

EXCEPTION
    WHEN OTHERS THEN RETURN C_KHONG_DU;
END FN_DIEU_KIEN_XLCT;


/
--------------------------------------------------------
--  DDL for Function FN_FORMAT_SORT_TEN_PN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_FORMAT_SORT_TEN_PN" (p_FullName IN VARCHAR2) 
RETURN VARCHAR2 IS
    v_Count NUMBER;
    v_Trimmed VARCHAR2(500);
    v_Result VARCHAR2(500) := '';
BEGIN
    IF p_FullName IS NULL THEN
        RETURN NULL;
    END IF;

    v_Trimmed := REGEXP_REPLACE(TRIM(p_FullName), '\s+', ' ');

    v_Count := REGEXP_COUNT(v_Trimmed, '[^ ]+');

    FOR i IN REVERSE 1..v_Count LOOP
        IF v_Result IS NOT NULL THEN
            v_Result := v_Result || ' ';
        END IF;
        v_Result := v_Result || REGEXP_SUBSTR(v_Trimmed, '[^ ]+', 1, i);
    END LOOP;

    RETURN v_Result;
END;




/
--------------------------------------------------------
--  DDL for Function FN_FORMAT_YMD
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_FORMAT_YMD" (
    p_nam   IN NUMBER,
    p_thang IN NUMBER,
    p_ngay  IN NUMBER
) RETURN NVARCHAR2
AS
BEGIN
    IF NVL(p_nam, 0) = 0 AND NVL(p_thang, 0) = 0 AND NVL(p_ngay, 0) = 0 THEN
        RETURN u'Kh\00f4ng';
    END IF;

    RETURN TRIM(
        CASE WHEN NVL(p_nam,   0) > 0 THEN TO_NCHAR(p_nam)   || u' n\0103m '   ELSE u'' END ||
        CASE WHEN NVL(p_thang, 0) > 0 THEN TO_NCHAR(p_thang) || u' th\00e1ng ' ELSE u'' END ||
        CASE WHEN NVL(p_ngay,  0) > 0 THEN TO_NCHAR(p_ngay)  || u' ng\00e0y'   ELSE u'' END
    );
END FN_FORMAT_YMD;





/
--------------------------------------------------------
--  DDL for Function FN_GET_CON_LAI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_CON_LAI" (p_PN_ID IN NUMBER)
RETURN NVARCHAR2
IS
    v_an_phat       NVARCHAR2(500);
    v_da_giam_ymd   YMD_OBJ;
    v_da_chap_hanh  YMD_OBJ;
    v_con_lai_ymd   YMD_OBJ;
BEGIN
    -- L?y án ph?t
    BEGIN
        SELECT THA_AN_PHAT INTO v_an_phat
          FROM PN_THI_HANH_AN
         WHERE THA_PNLAI_LICH_ID = p_PN_ID
           AND NVL(IS_DELETED, 0) = 0
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN RETURN TO_NCHAR('0 n?m 0 tháng 0 ngày');
    END;

    -- T?ng án gi?m
    v_da_giam_ymd  := FN_TINH_TONG_AN_GIAM(p_PN_ID);

    -- ?ã ch?p hành tính ??n hôm nay
    v_da_chap_hanh := FN_GET_DA_CHAP_HANH_THEO_NGAY(p_PN_ID, SYSDATE);

    -- Còn l?i = án ph?t - ?ã gi?m - ?ã ch?p hành
    v_con_lai_ymd  := FN_TINH_CON_LAI(v_an_phat, v_da_giam_ymd, v_da_chap_hanh);

    -- Ki?m tra ?ã h?t h?n
    IF NVL(v_con_lai_ymd.nam,   0) <= 0
   AND NVL(v_con_lai_ymd.thang, 0) <= 0
   AND NVL(v_con_lai_ymd.ngay,  0) <= 0
    THEN
        RETURN TO_NCHAR('?ã h?t h?n');
    END IF;

    -- Format k?t qu?
	RETURN 
	    TRIM(
	        CASE 
	            WHEN NVL(v_con_lai_ymd.nam, 0) > 0 
	            THEN v_con_lai_ymd.nam || TO_NCHAR(' n?m ') 
	            ELSE '' 
	        END ||
	        CASE 
	            WHEN NVL(v_con_lai_ymd.thang, 0) > 0 
	            THEN v_con_lai_ymd.thang || TO_NCHAR(' tháng ') 
	            ELSE '' 
	        END ||
	        CASE 
	            WHEN NVL(v_con_lai_ymd.ngay, 0) > 0 
	            THEN v_con_lai_ymd.ngay || TO_NCHAR(' ngày') 
	            ELSE '' 
	        END
	    );

EXCEPTION
    WHEN OTHERS THEN RETURN TO_NCHAR('N/A');
END FN_GET_CON_LAI;





/
--------------------------------------------------------
--  DDL for Function FN_GET_CON_LAI_THEO_NGAY
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_CON_LAI_THEO_NGAY" (
    p_PN_ID    IN NUMBER,
    p_NGAY_XET IN DATE
)
RETURN NUMBER
IS
    v_NGAY_HET_HAN  DATE;
    v_CON_LAI_NAM   NUMBER;
    v_CON_LAI_THANG NUMBER;
    v_CON_LAI_NGAY  NUMBER;
    v_TONG_NGAY     NUMBER;
    v_TEMP_DATE     DATE;
BEGIN
    -- L?y ngày h?t h?n t? PN_THI_HANH_AN
    SELECT ptha.THA_NGAY_HET_HAN
    INTO v_NGAY_HET_HAN
    FROM PN_THI_HANH_AN ptha
    WHERE ptha.THA_PNLAI_LICH_ID = p_PN_ID
    AND ROWNUM = 1;

    -- N?u ngày h?t h?n null ho?c ?ã qua ngày xét
    IF v_NGAY_HET_HAN IS NULL THEN
        RETURN 0;
    END IF;

    IF v_NGAY_HET_HAN <= p_NGAY_XET THEN
        RETURN 0;  -- ?ã h?t h?n
    END IF;

    -- Tính s? n?m
    v_CON_LAI_NAM := FLOOR(MONTHS_BETWEEN(v_NGAY_HET_HAN, p_NGAY_XET) / 12);
    v_TEMP_DATE   := ADD_MONTHS(p_NGAY_XET, v_CON_LAI_NAM * 12);

    -- Tính s? tháng còn l?i
    v_CON_LAI_THANG := FLOOR(MONTHS_BETWEEN(v_NGAY_HET_HAN, v_TEMP_DATE));
    v_TEMP_DATE     := ADD_MONTHS(v_TEMP_DATE, v_CON_LAI_THANG);

    -- Tính s? ngày còn l?i
    v_CON_LAI_NGAY := FLOOR(v_NGAY_HET_HAN - v_TEMP_DATE);

    -- Tính t?ng s? ngày: 1 n?m = 365 ngày, 1 tháng = 30 ngày
    v_TONG_NGAY := (v_CON_LAI_NAM * 365) + (v_CON_LAI_THANG * 30) + v_CON_LAI_NGAY;

    RETURN v_TONG_NGAY;

EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN 0;
    WHEN OTHERS THEN RETURN 0;
END FN_GET_CON_LAI_THEO_NGAY;






/
--------------------------------------------------------
--  DDL for Function FN_GET_DA_CHAP_HANH
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_DA_CHAP_HANH" (p_PN_ID IN NUMBER)
RETURN NVARCHAR2
IS
    v_NGAY_BAT_OUT DATE;
    v_AN_THUC_NAM NUMBER;
    v_AN_THUC_THANG NUMBER;
    v_AN_THUC_NGAY NUMBER; 
    v_DA_CHAP_HANH_NAM NUMBER;
    v_DA_CHAP_HANH_THANG NUMBER;
    v_DA_CHAP_HANH_NGAY NUMBER;
    v_NGAY_HET_HAN DATE;
    v_THONG_BAO NVARCHAR2(4000);
    v_RESULT NVARCHAR2(2000);
BEGIN
    -- G?i store procedure
    SP_TINH_NGAY_HET_AN_DEMO(
        p_PN_ID => p_PN_ID,
        p_NGAY_BAT_OUT => v_NGAY_BAT_OUT,
        p_AN_THUC_NAM => v_AN_THUC_NAM,
        p_AN_THUC_THANG => v_AN_THUC_THANG,
        p_AN_THUC_NGAY => v_AN_THUC_NGAY,
        p_DA_CHAP_HANH_NAM => v_DA_CHAP_HANH_NAM,
        p_DA_CHAP_HANH_THANG => v_DA_CHAP_HANH_THANG,
        p_DA_CHAP_HANH_NGAY => v_DA_CHAP_HANH_NGAY,
        p_NGAY_HET_HAN => v_NGAY_HET_HAN,
        p_THONG_BAO => v_THONG_BAO
    );

    -- Format chu?i k?t qu?
    v_RESULT := '';

    IF v_DA_CHAP_HANH_NAM > 0 THEN
        v_RESULT := v_RESULT || v_DA_CHAP_HANH_NAM || ' n?m';
    END IF;

    IF v_DA_CHAP_HANH_THANG > 0 THEN
        IF LENGTH(v_RESULT) > 0 THEN
            v_RESULT := v_RESULT || ', ';
        END IF;
        v_RESULT := v_RESULT || v_DA_CHAP_HANH_THANG || ' tháng';
    END IF;

    IF v_DA_CHAP_HANH_NGAY > 0 THEN
        IF LENGTH(v_RESULT) > 0 THEN
            v_RESULT := v_RESULT || ', ';
        END IF;
        v_RESULT := v_RESULT || v_DA_CHAP_HANH_NGAY || ' ngày';
    END IF;

    -- N?u t?t c? ??u = 0
    IF LENGTH(v_RESULT) = 0 THEN
        v_RESULT := '0 ngày';
    END IF;

    RETURN v_RESULT;
EXCEPTION
    WHEN OTHERS THEN
        RETURN 'N/A';
END;






