--  DDL for Function FN_GET_DA_CHAP_HANH_TEXT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_DA_CHAP_HANH_TEXT" (
    p_PN_ID    IN NUMBER,
    p_NGAY_XET IN DATE
)
RETURN NVARCHAR2
IS
    v_NGAY_BAT      DATE;
	v_NGAY_XET 		DATE;
    v_TG_TAM_GIAM   NVARCHAR2(500);
    v_TG_TAM_GIU    NVARCHAR2(500);
    v_TG_O_TRUOC    NVARCHAR2(500);
    v_TEMP_DATE     DATE;
    v_NAM           NUMBER := 0;
    v_THANG         NUMBER := 0;
    v_NGAY          NUMBER := 0;
    v_YMD_TG        YMD_OBJ;

    -- T?ng ngày c?n TR? ?i
    v_TONG_NGAY_TRU NUMBER := 0;

    -- Bi?n ki?m tra t?m ?ình ch?/tr?n tr?i/hoãn ch?a k?t thúc
    v_NGAY_GIOI_HAN DATE := NULL;  -- Ngày gi?i h?n tính ?ã ch?p hành

    PROCEDURE NORMALIZE IS
    BEGIN
        v_THANG := v_THANG + FLOOR(v_NGAY  / 30);
        v_NGAY  := MOD(v_NGAY,  30);
        v_NAM   := v_NAM   + FLOOR(v_THANG / 12);
        v_THANG := MOD(v_THANG, 12);
    END;

    PROCEDURE CONG_YMD(p_ymd IN YMD_OBJ) IS
    BEGIN
        IF p_ymd IS NULL THEN RETURN; END IF;
        v_NAM   := v_NAM   + NVL(p_ymd.nam,   0);
        v_THANG := v_THANG + NVL(p_ymd.thang, 0);
        v_NGAY  := v_NGAY  + NVL(p_ymd.ngay,  0);
        NORMALIZE();
    END;

    -- Tr? t?ng ngày kh?i YMD hi?n t?i r?i chu?n hóa
    PROCEDURE TRU_NGAY(p_so_ngay IN NUMBER) IS
        v_tong  NUMBER;
        v_n     NUMBER;
        v_t     NUMBER;
        v_ng    NUMBER;
    BEGIN
        IF p_so_ngay <= 0 THEN RETURN; END IF;

        -- Quy v? t?ng ngày r?i tr?
        v_tong := v_NAM * 365 + v_THANG * 30 + v_NGAY - p_so_ngay;

        IF v_tong < 0 THEN v_tong := 0; END IF;

        v_NAM   := FLOOR(v_tong / 365);
        v_THANG := FLOOR(MOD(v_tong, 365) / 30);
        v_NGAY  := MOD(MOD(v_tong, 365), 30);
    END;

BEGIN
	v_NGAY_XET := TO_DATE(p_NGAY_XET);
    SELECT
        CAST(ptha.THA_NGAY_BAT AS DATE),
        ptha.THA_THOI_GIAN_TAM_GIAM,
        ptha.THA_THOI_GIAN_TAM_GIU,
        ptha.THA_THOI_GIAN_O_TRUOC
    INTO v_NGAY_BAT, v_TG_TAM_GIAM, v_TG_TAM_GIU, v_TG_O_TRUOC
    FROM PN_THI_HANH_AN ptha
    WHERE ptha.THA_PNLAI_LICH_ID = p_PN_ID
      AND NVL(ptha.IS_DELETED, 0) = 0
      AND ROWNUM = 1;

    IF v_NGAY_BAT IS NULL OR v_NGAY_XET <= v_NGAY_BAT THEN
        RETURN TO_NCHAR('0 ngày');
    END IF;

    -- ==========================================
    -- KI?M TRA T?M ?ÌNH CH? CH?A K?T THÚC
    -- ==========================================
    BEGIN
        SELECT MIN(tdc.TU_NGAY)
        INTO v_NGAY_GIOI_HAN
        FROM TAM_DINH_CHIS tdc
        WHERE tdc.PHAM_NHAN_ID = p_PN_ID
          AND NVL(tdc.IS_DELETED, 0) = 0
          AND tdc.TU_NGAY IS NOT NULL
          AND tdc.NGAY_LAI IS NULL;  -- Ch?a có ngày l?i

        -- N?u có TDC ch?a k?t thúc ? Gi?i h?n tính ??n TU_NGAY s?m nh?t
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_NGAY_GIOI_HAN := NULL;
    END;

    -- ==========================================
    -- KI?M TRA TR?N TR?I CH?A B?T L?I
    -- ==========================================
    IF v_NGAY_GIOI_HAN IS NULL THEN
        BEGIN
            SELECT MIN(tt.NGAY_TRON)
            INTO v_NGAY_GIOI_HAN
            FROM TRON_TRAIS tt
            WHERE tt.PHAM_NHAN_ID = p_PN_ID
              AND NVL(tt.IS_DELETED, 0) = 0
              AND tt.NGAY_TRON IS NOT NULL
              AND tt.NGAY_BAT_LAI IS NULL;  -- Ch?a b?t l?i
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                NULL;
        END;
    END IF;

    -- ==========================================
    -- KI?M TRA HOÃN THI HÀNH ÁN CH?A TR? L?I
    -- ==========================================
    IF v_NGAY_GIOI_HAN IS NULL THEN
        BEGIN
            SELECT MIN(htha.NGAY_HOAN)
            INTO v_NGAY_GIOI_HAN
            FROM HOAN_THI_HANH_ANS htha
            WHERE htha.PHAM_NHAN_ID = p_PN_ID
              AND NVL(htha.IS_DELETED, 0) = 0
              AND htha.NGAY_HOAN IS NOT NULL
              AND htha.NGAY_THI_HANH_AN IS NULL;  -- Ch?a thi hành l?i
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                NULL;
        END;
    END IF;

    -- ==========================================
    -- N?U CÓ GI?I H?N ? TÍNH ??N NGÀY ?Ó
    -- ==========================================
    IF v_NGAY_GIOI_HAN IS NOT NULL THEN
        -- Tính th?i gian t? ngày b?t ??n ngày gi?i h?n
        IF v_NGAY_XET > v_NGAY_GIOI_HAN THEN
            -- N?u ngày xét sau ngày gi?i h?n ? Ch? tính ??n gi?i h?n
            v_NAM       := FLOOR(MONTHS_BETWEEN(v_NGAY_GIOI_HAN, v_NGAY_BAT) / 12);
            v_TEMP_DATE := ADD_MONTHS(v_NGAY_BAT, v_NAM * 12);
            v_THANG     := FLOOR(MONTHS_BETWEEN(v_NGAY_GIOI_HAN, v_TEMP_DATE));
            v_TEMP_DATE := ADD_MONTHS(v_TEMP_DATE, v_THANG);
            v_NGAY      := FLOOR(v_NGAY_GIOI_HAN - v_TEMP_DATE);
        ELSE
            -- N?u ngày xét tr??c ngày gi?i h?n ? Tính bình th??ng
            v_NAM       := FLOOR(MONTHS_BETWEEN(v_NGAY_XET, v_NGAY_BAT) / 12);
            v_TEMP_DATE := ADD_MONTHS(v_NGAY_BAT, v_NAM * 12);
            v_THANG     := FLOOR(MONTHS_BETWEEN(v_NGAY_XET, v_TEMP_DATE));
            v_TEMP_DATE := ADD_MONTHS(v_TEMP_DATE, v_THANG);
            v_NGAY      := FLOOR(v_NGAY_XET - v_TEMP_DATE);
        END IF;
    ELSE
        -- Không có gi?i h?n ? Tính bình th??ng
        v_NAM       := FLOOR(MONTHS_BETWEEN(v_NGAY_XET, v_NGAY_BAT) / 12);
        v_TEMP_DATE := ADD_MONTHS(v_NGAY_BAT, v_NAM * 12);
        v_THANG     := FLOOR(MONTHS_BETWEEN(v_NGAY_XET, v_TEMP_DATE));
        v_TEMP_DATE := ADD_MONTHS(v_TEMP_DATE, v_THANG);
        v_NGAY      := FLOOR(v_NGAY_XET - v_TEMP_DATE);
    END IF;

    -- C?ng t?m giam / t?m gi? / ? tr??c
    FOR i IN 1..3 LOOP
        DECLARE
            v_txt NVARCHAR2(500);
        BEGIN
            v_txt := CASE i
                         WHEN 1 THEN v_TG_TAM_GIAM
                         WHEN 2 THEN v_TG_TAM_GIU
                         ELSE        v_TG_O_TRUOC
                     END;
            IF v_txt IS NOT NULL AND LENGTH(TRIM(v_txt)) > 0 THEN
                v_YMD_TG := FN_PARSE_AN_PHAT_TO_YMD(v_txt);
                CONG_YMD(v_YMD_TG);
            END IF;
        END;
    END LOOP;

    -- ==========================================
    -- T?M ?ÌNH CH?: CH? TÍNH CÁC B?N GHI ?Ã K?T THÚC
    -- ==========================================
    BEGIN
        FOR rec IN (
            SELECT CAST(tdc.TU_NGAY AS DATE) AS TU_NGAY,
                   CAST(tdc.NGAY_LAI AS DATE) AS NGAY_LAI
            FROM TAM_DINH_CHIS tdc
            WHERE tdc.PHAM_NHAN_ID = p_PN_ID
              AND NVL(tdc.IS_DELETED, 0) = 0
              AND tdc.TU_NGAY IS NOT NULL
              AND tdc.NGAY_LAI IS NOT NULL  -- CH? l?y các b?n ghi ?ã có ngày l?i
        ) LOOP
            DECLARE
                v_so_ngay_tdc NUMBER;
            BEGIN
                v_so_ngay_tdc := FLOOR(rec.NGAY_LAI - rec.TU_NGAY) + 1;
                IF v_so_ngay_tdc > 0 THEN
                    v_TONG_NGAY_TRU := v_TONG_NGAY_TRU + v_so_ngay_tdc;
                END IF;
            END;
        END LOOP;
    EXCEPTION
        WHEN OTHERS THEN NULL;
    END;

    -- ==========================================
    -- HOÃN THI HÀNH ÁN: CH? TÍNH CÁC B?N GHI ?Ã TR? L?I
    -- ==========================================
    BEGIN
        FOR rec IN (
            SELECT CAST(htha.NGAY_THI_HANH_AN AS DATE) AS NGAY_THA,
                   CAST(htha.NGAY_HOAN AS DATE) AS NGAY_HOAN
            FROM HOAN_THI_HANH_ANS htha
            WHERE htha.PHAM_NHAN_ID = p_PN_ID
              AND NVL(htha.IS_DELETED, 0) = 0
              AND htha.NGAY_THI_HANH_AN IS NOT NULL  -- ?Ã có ngày thi hành l?i
              AND htha.NGAY_HOAN IS NOT NULL
        ) LOOP
            DECLARE
                v_so_ngay_hoan NUMBER;
            BEGIN
                v_so_ngay_hoan := FLOOR(rec.NGAY_THA - rec.NGAY_HOAN) + 1;
                IF v_so_ngay_hoan > 0 THEN
                    v_TONG_NGAY_TRU := v_TONG_NGAY_TRU + v_so_ngay_hoan;
                END IF;
            END;
        END LOOP;
    EXCEPTION
        WHEN OTHERS THEN NULL;
    END;

    -- ==========================================
    -- TR?N TR?I: CH? TÍNH CÁC B?N GHI ?Ã B?T L?I
    -- ==========================================
    BEGIN
        FOR rec IN (
            SELECT CAST(tt.NGAY_TRON AS DATE) AS NGAY_TRON,
                   CAST(tt.NGAY_BAT_LAI AS DATE) AS NGAY_BAT_LAI
            FROM TRON_TRAIS tt
            WHERE tt.PHAM_NHAN_ID = p_PN_ID
              AND NVL(tt.IS_DELETED, 0) = 0
              AND tt.NGAY_TRON IS NOT NULL
              AND tt.NGAY_BAT_LAI IS NOT NULL  -- ?Ã b?t l?i
        ) LOOP
            DECLARE
                v_so_ngay_tron NUMBER;
            BEGIN
                v_so_ngay_tron := FLOOR(rec.NGAY_BAT_LAI - rec.NGAY_TRON);
                IF v_so_ngay_tron > 0 THEN
                    v_TONG_NGAY_TRU := v_TONG_NGAY_TRU + v_so_ngay_tron;
                END IF;
            END;
        END LOOP;
    EXCEPTION
        WHEN OTHERS THEN NULL;
    END;

    -- Tr? t?ng th?i gian không ch?p hành
    TRU_NGAY(v_TONG_NGAY_TRU);

    DECLARE
        v_result NVARCHAR2(200) := '';
    BEGIN
        IF v_NAM   > 0 THEN v_result := v_result || v_NAM   || TO_NCHAR(' n?m ');   END IF;
        IF v_THANG > 0 THEN v_result := v_result || v_THANG || TO_NCHAR(' tháng '); END IF;
        IF v_NGAY  > 0 THEN v_result := v_result || v_NGAY  || TO_NCHAR(' ngày');   END IF;

        IF TRIM(v_result) IS NULL THEN
            RETURN TO_NCHAR('Không');
        END IF;
        RETURN TRIM(v_result);
    END;

EXCEPTION   
    WHEN NO_DATA_FOUND THEN RETURN TO_NCHAR('Không');
    WHEN OTHERS        THEN RETURN TO_NCHAR('Không');
END FN_GET_DA_CHAP_HANH_TEXT;


