            SELECT CAST(htha.NGAY_THI_HANH_AN AS DATE) AS NGAY_THA,
                   CAST(htha.NGAY_HOAN AS DATE) AS NGAY_HOAN
            FROM HOAN_THI_HANH_ANS htha
            WHERE htha.PHAM_NHAN_ID = p_PN_ID
              AND NVL(htha.IS_DELETED, 0) = 0
              AND htha.NGAY_THI_HANH_AN IS NOT NULL  -- ?Ã có ngày thi hành l?i
              AND htha.NGAY_HOAN IS NOT NULL
        ) LOOP
            DECLARE
                v_so_ngay_hoan NUMBER;
            BEGIN
                v_so_ngay_hoan := FLOOR(rec.NGAY_THA - rec.NGAY_HOAN) + 1;
                IF v_so_ngay_hoan > 0 THEN
                    v_TONG_NGAY_TRU := v_TONG_NGAY_TRU + v_so_ngay_hoan;
                END IF;
            END;
        END LOOP;
    EXCEPTION
        WHEN OTHERS THEN NULL;
    END;

    -- ==========================================
    -- TR?N TR?I: CH? TÍNH CÁC B?N GHI ?Ã B?T L?I
    -- ==========================================
    BEGIN
        FOR rec IN (
            SELECT CAST(tt.NGAY_TRON AS DATE) AS NGAY_TRON,
                   CAST(tt.NGAY_BAT_LAI AS DATE) AS NGAY_BAT_LAI
            FROM TRON_TRAIS tt
            WHERE tt.PHAM_NHAN_ID = p_PN_ID
              AND NVL(tt.IS_DELETED, 0) = 0
              AND tt.NGAY_TRON IS NOT NULL
              AND tt.NGAY_BAT_LAI IS NOT NULL  -- ?Ã b?t l?i
        ) LOOP
            DECLARE
                v_so_ngay_tron NUMBER;
            BEGIN
                v_so_ngay_tron := FLOOR(rec.NGAY_BAT_LAI - rec.NGAY_TRON);
                IF v_so_ngay_tron > 0 THEN
                    v_TONG_NGAY_TRU := v_TONG_NGAY_TRU + v_so_ngay_tron;
                END IF;
            END;
        END LOOP;
    EXCEPTION
        WHEN OTHERS THEN NULL;
    END;

    -- Tr? t?ng th?i gian không ch?p hành
    TRU_NGAY(v_TONG_NGAY_TRU);

    RETURN YMD_OBJ(v_NAM, v_THANG, v_NGAY);

EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN YMD_OBJ(0, 0, 0);
    WHEN OTHERS        THEN RETURN YMD_OBJ(0, 0, 0);
END FN_GET_DA_CHAP_HANH_THEO_NGAY;


/
--------------------------------------------------------
--  DDL for Function FN_GET_DA_CHAP_HANH_TRU_2_THANG_TEXT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_DA_CHAP_HANH_TRU_2_THANG_TEXT" (
    p_PN_ID    IN NUMBER,
    p_NGAY_XET IN DATE
)
RETURN NVARCHAR2
IS
    v_NGAY_BAT      DATE;
	v_NGAY_XET 		DATE;
    v_TG_TAM_GIAM   NVARCHAR2(500);
    v_TG_TAM_GIU    NVARCHAR2(500);
    v_TG_O_TRUOC    NVARCHAR2(500);
    v_TEMP_DATE     DATE;
    v_NAM           NUMBER := 0;
    v_THANG         NUMBER := 0;
    v_NGAY          NUMBER := 0;
    v_YMD_TG        YMD_OBJ;

    -- T?ng ngày c?n TR? ?i
    v_TONG_NGAY_TRU NUMBER := 0;

    -- Bi?n ki?m tra t?m ?ình ch?/tr?n tr?i/hoãn ch?a k?t thúc
    v_NGAY_GIOI_HAN DATE := NULL;  -- Ngày gi?i h?n tính ?ã ch?p hành

    -- S? tháng c?n tr? kh?i k?t qu? cu?i cùng (yêu c?u m?i)
    C_SO_THANG_TRU  CONSTANT NUMBER := 2;

    PROCEDURE NORMALIZE IS
    BEGIN
        v_THANG := v_THANG + FLOOR(v_NGAY  / 30);
        v_NGAY  := MOD(v_NGAY,  30);
        v_NAM   := v_NAM   + FLOOR(v_THANG / 12);
        v_THANG := MOD(v_THANG, 12);
    END;

    PROCEDURE CONG_YMD(p_ymd IN YMD_OBJ) IS
    BEGIN
        IF p_ymd IS NULL THEN RETURN; END IF;
        v_NAM   := v_NAM   + NVL(p_ymd.nam,   0);
        v_THANG := v_THANG + NVL(p_ymd.thang, 0);
        v_NGAY  := v_NGAY  + NVL(p_ymd.ngay,  0);
        NORMALIZE();
    END;

    -- Tr? t?ng ngày kh?i YMD hi?n t?i r?i chu?n hóa
    PROCEDURE TRU_NGAY(p_so_ngay IN NUMBER) IS
        v_tong  NUMBER;
    BEGIN
        IF p_so_ngay <= 0 THEN RETURN; END IF;

        -- Quy v? t?ng ngày r?i tr?
        v_tong := v_NAM * 365 + v_THANG * 30 + v_NGAY - p_so_ngay;

        IF v_tong < 0 THEN v_tong := 0; END IF;

        v_NAM   := FLOOR(v_tong / 365);
        v_THANG := FLOOR(MOD(v_tong, 365) / 30);
        v_NGAY  := MOD(MOD(v_tong, 365), 30);
    END;

    -- Tr? s? tháng kh?i (v_NAM, v_THANG) hi?n t?i, gi? nguyên v_NGAY, có ch?n d??i 0
    PROCEDURE TRU_THANG(p_so_thang IN NUMBER) IS
        v_tong_thang NUMBER;
    BEGIN
        IF p_so_thang <= 0 THEN RETURN; END IF;

        v_tong_thang := v_NAM * 12 + v_THANG - p_so_thang;

        IF v_tong_thang < 0 THEN v_tong_thang := 0; END IF;

        v_NAM   := FLOOR(v_tong_thang / 12);
        v_THANG := MOD(v_tong_thang, 12);
    END;

BEGIN
	v_NGAY_XET := TO_DATE(p_NGAY_XET);
    SELECT
        CAST(ptha.THA_NGAY_BAT AS DATE),
        ptha.THA_THOI_GIAN_TAM_GIAM,
        ptha.THA_THOI_GIAN_TAM_GIU,
        ptha.THA_THOI_GIAN_O_TRUOC
    INTO v_NGAY_BAT, v_TG_TAM_GIAM, v_TG_TAM_GIU, v_TG_O_TRUOC
    FROM PN_THI_HANH_AN ptha
    WHERE ptha.THA_PNLAI_LICH_ID = p_PN_ID
      AND NVL(ptha.IS_DELETED, 0) = 0
      AND ROWNUM = 1;

    IF v_NGAY_BAT IS NULL OR v_NGAY_XET <= v_NGAY_BAT THEN
        RETURN TO_NCHAR('0 ngày');
    END IF;

    -- ==========================================
    -- KI?M TRA T?M ?ÌNH CH? CH?A K?T THÚC
    -- ==========================================
    BEGIN
        SELECT MIN(tdc.TU_NGAY)
        INTO v_NGAY_GIOI_HAN
        FROM TAM_DINH_CHIS tdc
        WHERE tdc.PHAM_NHAN_ID = p_PN_ID
          AND NVL(tdc.IS_DELETED, 0) = 0
          AND tdc.TU_NGAY IS NOT NULL
          AND tdc.NGAY_LAI IS NULL;  -- Ch?a có ngày l?i

        -- N?u có TDC ch?a k?t thúc ? Gi?i h?n tính ??n TU_NGAY s?m nh?t
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_NGAY_GIOI_HAN := NULL;
    END;

    -- ==========================================
    -- KI?M TRA TR?N TR?I CH?A B?T L?I
    -- ==========================================
    IF v_NGAY_GIOI_HAN IS NULL THEN
        BEGIN
            SELECT MIN(tt.NGAY_TRON)
            INTO v_NGAY_GIOI_HAN
            FROM TRON_TRAIS tt
            WHERE tt.PHAM_NHAN_ID = p_PN_ID
              AND NVL(tt.IS_DELETED, 0) = 0
              AND tt.NGAY_TRON IS NOT NULL
              AND tt.NGAY_BAT_LAI IS NULL;  -- Ch?a b?t l?i
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                NULL;
        END;
    END IF;

    -- ==========================================
    -- KI?M TRA HOÃN THI HÀNH ÁN CH?A TR? L?I
    -- ==========================================
    IF v_NGAY_GIOI_HAN IS NULL THEN
        BEGIN
            SELECT MIN(htha.NGAY_HOAN)
            INTO v_NGAY_GIOI_HAN
            FROM HOAN_THI_HANH_ANS htha
            WHERE htha.PHAM_NHAN_ID = p_PN_ID
              AND NVL(htha.IS_DELETED, 0) = 0
              AND htha.NGAY_HOAN IS NOT NULL
              AND htha.NGAY_THI_HANH_AN IS NULL;  -- Ch?a thi hành l?i
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                NULL;
        END;
    END IF;

    -- ==========================================
    -- N?U CÓ GI?I H?N ? TÍNH ??N NGÀY ?Ó
    -- ==========================================
    IF v_NGAY_GIOI_HAN IS NOT NULL THEN
        -- Tính th?i gian t? ngày b?t ??n ngày gi?i h?n
        IF v_NGAY_XET > v_NGAY_GIOI_HAN THEN
            -- N?u ngày xét sau ngày gi?i h?n ? Ch? tính ??n gi?i h?n
            v_NAM       := FLOOR(MONTHS_BETWEEN(v_NGAY_GIOI_HAN, v_NGAY_BAT) / 12);
            v_TEMP_DATE := ADD_MONTHS(v_NGAY_BAT, v_NAM * 12);
            v_THANG     := FLOOR(MONTHS_BETWEEN(v_NGAY_GIOI_HAN, v_TEMP_DATE));
            v_TEMP_DATE := ADD_MONTHS(v_TEMP_DATE, v_THANG);
            v_NGAY      := FLOOR(v_NGAY_GIOI_HAN - v_TEMP_DATE);
        ELSE
            -- N?u ngày xét tr??c ngày gi?i h?n ? Tính bình th??ng
            v_NAM       := FLOOR(MONTHS_BETWEEN(v_NGAY_XET, v_NGAY_BAT) / 12);
            v_TEMP_DATE := ADD_MONTHS(v_NGAY_BAT, v_NAM * 12);
            v_THANG     := FLOOR(MONTHS_BETWEEN(v_NGAY_XET, v_TEMP_DATE));
            v_TEMP_DATE := ADD_MONTHS(v_TEMP_DATE, v_THANG);
            v_NGAY      := FLOOR(v_NGAY_XET - v_TEMP_DATE);
        END IF;
    ELSE
        -- Không có gi?i h?n ? Tính bình th??ng
        v_NAM       := FLOOR(MONTHS_BETWEEN(v_NGAY_XET, v_NGAY_BAT) / 12);
        v_TEMP_DATE := ADD_MONTHS(v_NGAY_BAT, v_NAM * 12);
        v_THANG     := FLOOR(MONTHS_BETWEEN(v_NGAY_XET, v_TEMP_DATE));
        v_TEMP_DATE := ADD_MONTHS(v_TEMP_DATE, v_THANG);
        v_NGAY      := FLOOR(v_NGAY_XET - v_TEMP_DATE);
    END IF;

    -- C?ng t?m giam / t?m gi? / ? tr??c
    FOR i IN 1..3 LOOP
        DECLARE
            v_txt NVARCHAR2(500);
        BEGIN
            v_txt := CASE i
                         WHEN 1 THEN v_TG_TAM_GIAM
                         WHEN 2 THEN v_TG_TAM_GIU
                         ELSE        v_TG_O_TRUOC
                     END;
            IF v_txt IS NOT NULL AND LENGTH(TRIM(v_txt)) > 0 THEN
                v_YMD_TG := FN_PARSE_AN_PHAT_TO_YMD(v_txt);
                CONG_YMD(v_YMD_TG);
            END IF;
        END;
    END LOOP;

    -- ==========================================
    -- T?M ?ÌNH CH?: CH? TÍNH CÁC B?N GHI ?Ã K?T THÚC
    -- ==========================================
    BEGIN
        FOR rec IN (
            SELECT CAST(tdc.TU_NGAY AS DATE) AS TU_NGAY,
                   CAST(tdc.NGAY_LAI AS DATE) AS NGAY_LAI
            FROM TAM_DINH_CHIS tdc
            WHERE tdc.PHAM_NHAN_ID = p_PN_ID
              AND NVL(tdc.IS_DELETED, 0) = 0
              AND tdc.TU_NGAY IS NOT NULL
              AND tdc.NGAY_LAI IS NOT NULL  -- CH? l?y các b?n ghi ?ã có ngày l?i
        ) LOOP
            DECLARE
                v_so_ngay_tdc NUMBER;
            BEGIN
                v_so_ngay_tdc := FLOOR(rec.NGAY_LAI - rec.TU_NGAY) + 1;
                IF v_so_ngay_tdc > 0 THEN
                    v_TONG_NGAY_TRU := v_TONG_NGAY_TRU + v_so_ngay_tdc;
                END IF;
            END;
        END LOOP;
    EXCEPTION
        WHEN OTHERS THEN NULL;
    END;

    -- ==========================================
    -- HOÃN THI HÀNH ÁN: CH? TÍNH CÁC B?N GHI ?Ã TR? L?I
    -- ==========================================
    BEGIN
        FOR rec IN (
            SELECT CAST(htha.NGAY_THI_HANH_AN AS DATE) AS NGAY_THA,
                   CAST(htha.NGAY_HOAN AS DATE) AS NGAY_HOAN
            FROM HOAN_THI_HANH_ANS htha
            WHERE htha.PHAM_NHAN_ID = p_PN_ID
              AND NVL(htha.IS_DELETED, 0) = 0
              AND htha.NGAY_THI_HANH_AN IS NOT NULL  -- ?Ã có ngày thi hành l?i
              AND htha.NGAY_HOAN IS NOT NULL
        ) LOOP
            DECLARE
                v_so_ngay_hoan NUMBER;
            BEGIN
                v_so_ngay_hoan := FLOOR(rec.NGAY_THA - rec.NGAY_HOAN) + 1;
                IF v_so_ngay_hoan > 0 THEN
                    v_TONG_NGAY_TRU := v_TONG_NGAY_TRU + v_so_ngay_hoan;
                END IF;
            END;
        END LOOP;
    EXCEPTION
        WHEN OTHERS THEN NULL;
    END;

    -- ==========================================
    -- TR?N TR?I: CH? TÍNH CÁC B?N GHI ?Ã B?T L?I
    -- ==========================================
    BEGIN
        FOR rec IN (
            SELECT CAST(tt.NGAY_TRON AS DATE) AS NGAY_TRON,
                   CAST(tt.NGAY_BAT_LAI AS DATE) AS NGAY_BAT_LAI
            FROM TRON_TRAIS tt
            WHERE tt.PHAM_NHAN_ID = p_PN_ID
              AND NVL(tt.IS_DELETED, 0) = 0
              AND tt.NGAY_TRON IS NOT NULL
              AND tt.NGAY_BAT_LAI IS NOT NULL  -- ?Ã b?t l?i
        ) LOOP
            DECLARE
                v_so_ngay_tron NUMBER;
            BEGIN
                v_so_ngay_tron := FLOOR(rec.NGAY_BAT_LAI - rec.NGAY_TRON);
                IF v_so_ngay_tron > 0 THEN
                    v_TONG_NGAY_TRU := v_TONG_NGAY_TRU + v_so_ngay_tron;
                END IF;
            END;
        END LOOP;
    EXCEPTION
        WHEN OTHERS THEN NULL;
    END;

    -- Tr? t?ng th?i gian không ch?p hành
    TRU_NGAY(v_TONG_NGAY_TRU);

    -- Tr? thêm C_SO_THANG_TRU tháng theo yêu c?u (không cho âm)
    TRU_THANG(C_SO_THANG_TRU);

    DECLARE
        v_result NVARCHAR2(200) := '';
    BEGIN
        IF v_NAM   > 0 THEN v_result := v_result || v_NAM   || TO_NCHAR(' n?m ');   END IF;
        IF v_THANG > 0 THEN v_result := v_result || v_THANG || TO_NCHAR(' tháng '); END IF;
        IF v_NGAY  > 0 THEN v_result := v_result || v_NGAY  || TO_NCHAR(' ngày');   END IF;

        IF TRIM(v_result) IS NULL THEN
            RETURN TO_NCHAR('Không');
        END IF;
        RETURN TRIM(v_result);
    END;

EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN TO_NCHAR('Không');
    WHEN OTHERS        THEN RETURN TO_NCHAR('Không');
END FN_GET_DA_CHAP_HANH_TRU_2_THANG_TEXT;

/
--------------------------------------------------------
--  DDL for Function FN_GET_DS_KY_XEP_LOAI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_DS_KY_XEP_LOAI" (
    p_pham_nhan_id IN NUMBER,
    p_ky_giam_id   IN NUMBER
) RETURN NVARCHAR2
IS
    DBG CONSTANT CHAR(1) := CHR(0);

    -- ??? BI?N T? BLOCK DECLARE ????????????????????????????
    v_dieu_kien_id NUMBER;
    v_an_phat      NVARCHAR2(500);
    v_xl_ten       NVARCHAR2(100);
    v_quy          NUMBER;

    -- ??? BI?N CHÍNH ??????????????????????????????????????????
    v_so_lan_giam      NUMBER := 0;
    v_ngay_giam_gan    DATE;
    v_ngay_xet         DATE;

    v_yc                QLPN.SO_QUY_YEU_CAU_OBJ;
    v_khung_ap_dung     NUMBER := 0;  -- 1=liên t?c, 2=không liên t?c, 3=??c bi?t

    -- S? quý th?c t?
    v_lien_ke_thuc_te   NUMBER := 0;
    v_tong_thuc_te      NUMBER := 0;

    -- Ràng bu?c
    v_rang_buoc_lien_ke NUMBER := 0;
    v_he_so_cc          NUMBER := 0;
    v_he_so_kl          NUMBER := 0;
    v_he_so_db_tren10   NUMBER := 0;
    v_he_so_db_duoi10   NUMBER := 0;
    v_co_canh_cao       NUMBER := 0;
    v_co_khien_trach    NUMBER := 0;
    v_co_giam_buong     NUMBER := 0;
    v_is_dac_biet       NUMBER := 0;
    v_tong_ngay_an      NUMBER := 0;

    -- S? quý c?n l?y (tùy khung)
    v_so_quy_can_lay    NUMBER := 0;

    v_result            NVARCHAR2(4000) := '';
    v_nam_xl            NUMBER;

    -- ??? DEBUG ????????????????????????????????????????????????
    PROCEDURE P(p_text IN VARCHAR2) IS
    BEGIN
        DBMS_OUTPUT.PUT_LINE(p_text);
    END;

BEGIN
    DBMS_OUTPUT.ENABLE(1000000);
    P('=== FN_GET_DS_KY_XEP_LOAI ===');
    P('  p_pham_nhan_id : ' || p_pham_nhan_id);
    P('  p_ky_giam_id   : ' || p_ky_giam_id);

    -- ?? [1] L?y ?i?u ki?n ID + ngày xét t? k? gi?m ??????????
    BEGIN
        SELECT dk.ID, CAST(kg.KGTH_NGAY_XET_GIAM AS DATE)
          INTO v_dieu_kien_id, v_ngay_xet
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS dk
          JOIN GTH_KY_GIAM_THOI_HANS kg ON kg.ID = p_ky_giam_id
         WHERE dk.GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
           AND dk.IS_DELETED = 0
           AND kg.IS_DELETED = 0
           AND ROWNUM = 1;
        P('  [1] v_dieu_kien_id : ' || v_dieu_kien_id);
        P('  [1] v_ngay_xet     : ' || TO_CHAR(v_ngay_xet, 'DD/MM/YYYY'));
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            P('  [1] L?I: Khong tim thay dieu kien/k? gi?m');
            RETURN NULL;
        WHEN OTHERS THEN
            P('  [1] L?I: ' || SQLERRM);
            RETURN NULL;
    END;

    -- ?? [2] Ki?m tra ?ã gi?m ch?a ????????????????????????????
    -- NGAY_XET trong GIAM_THOI_HANS là VARCHAR2(50) dd/mm/yyyy, dùng format mask tránh ORA-01830
    SELECT COUNT(*), MAX(NGAY_XET)
      INTO v_so_lan_giam, v_ngay_giam_gan
      FROM GIAM_THOI_HANS
     WHERE PHAM_NHAN_ID = p_pham_nhan_id
       AND IS_DELETED = 0
       AND NGAY_XET< v_ngay_xet;
    P('  [2] v_so_lan_giam  : ' || v_so_lan_giam);
    P('  [2] v_ngay_giam_gan: ' || CASE WHEN v_ngay_giam_gan IS NULL THEN 'NULL' ELSE TO_CHAR(v_ngay_giam_gan, 'DD/MM/YYYY') END);

    -- ?? [3] L?y s? quý yêu c?u t? c?u hình ??ng ??????????????
    v_yc := QLPN.FN_TINH_SO_QUY_YEU_CAU(p_pham_nhan_id, p_ky_giam_id);
    P('  [3] YC lien tuc    : ' || v_yc.SO_QUY_LIEN_TUC);
    P('  [3] YC khong lien tuc: ' || v_yc.SO_QUY_KHONG_LIEN_TUC);
    P('  [3] YC lien ke     : ' || v_yc.SO_QUY_LIEN_KE_YC);
    P('  [3] YC dac biet    : ' || v_yc.SO_QUY_TRUONG_HOP_DB);

    -- ?? [4] Check ??c bi?t + s? quý th?c t? ??????????????????
    v_is_dac_biet := QLPN.FN_IS_TRUONG_HOP_DAC_BIET(p_pham_nhan_id, p_ky_giam_id);
    P('  [4] v_is_dac_biet  : ' || v_is_dac_biet);

    v_lien_ke_thuc_te := QLPN.FN_TINH_SO_QUY_LIEN_KE_THEO_NGAY(p_pham_nhan_id, v_ngay_xet);
    P('  [4] v_lien_ke_thuc_te: ' || v_lien_ke_thuc_te);

    v_tong_thuc_te := QLPN.FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT(p_pham_nhan_id, NULL).SO_QUY;
    P('  [4] v_tong_thuc_te  : ' || v_tong_thuc_te);

    -- ?? [5] L?y h? s? k? lu?t ????????????????????????????????
    BEGIN
        SELECT
            NVL(DKGTH_TH_TAI_PHAM_CANH_CAO,      0),
            NVL(DKGTH_TH_TAI_PHAM_KY_LUAT,       0),
            NVL(DKGTH_TH_DAC_BIET_AN_TREN10_NAM, 0),
            NVL(DKGTH_TH_DAC_BIET_AN_DUOI10_NAM, 0)
          INTO v_he_so_cc, v_he_so_kl, v_he_so_db_tren10, v_he_so_db_duoi10
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS
         WHERE ID = v_dieu_kien_id
           AND IS_DELETED = 0;
        P('  [5] he_so_cc      : ' || v_he_so_cc);
        P('  [5] he_so_kl      : ' || v_he_so_kl);
        P('  [5] he_so_db_tren : ' || v_he_so_db_tren10);
        P('  [5] he_so_db_duoi : ' || v_he_so_db_duoi10);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_he_so_cc := 0; v_he_so_kl := 0;
            v_he_so_db_tren10 := 0; v_he_so_db_duoi10 := 0;
            P('  [5] Khong co cau hinh he so ky luat');
    END;

    -- ?? [6] ??m k? lu?t trong 4 quý g?n nh?t ?????????????????
    SELECT COUNT(*) INTO v_co_canh_cao
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%C%NH C%O%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH < v_ngay_xet;
    P('  [6] v_co_canh_cao  : ' || v_co_canh_cao);

    SELECT COUNT(*) INTO v_co_khien_trach
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%KHI%N TR%CH%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH < v_ngay_xet;
    P('  [6] v_co_khien_trach: ' || v_co_khien_trach);

    SELECT COUNT(*) INTO v_co_giam_buong
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%GIAM BU%NG%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH < v_ngay_xet;
    P('  [6] v_co_giam_buong : ' || v_co_giam_buong);

    -- ?? [7] L?y t?ng ngày án ?????????????????????????????????
    BEGIN
        SELECT THA_AN_PHAT
          INTO v_an_phat
          FROM PN_THI_HANH_AN
         WHERE THA_PNLAI_LICH_ID = p_pham_nhan_id
           AND NVL(IS_DELETED, 0) = 0
           AND ROWNUM = 1;
        v_tong_ngay_an := QLPN.FN_PARSE_AN_PHAT_TO_NGAY(v_an_phat);
        P('  [7] v_an_phat      : ' || NVL(v_an_phat, 'NULL'));
        P('  [7] v_tong_ngay_an : ' || v_tong_ngay_an);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_tong_ngay_an := 0;
            P('  [7] Khong co an phat');
    END;

    -- ?? [8] Tính ràng bu?c li?n k? ???????????????????????????
    P('  [8] Tinh rang buoc lien ke...');
    P('      so_lan_giam=' || v_so_lan_giam);
    IF v_so_lan_giam > 0 THEN
        IF    (v_co_canh_cao >= 1 OR v_co_khien_trach >= 1) AND v_co_giam_buong > 0 THEN
            v_rang_buoc_lien_ke := GREATEST(v_he_so_cc, v_he_so_kl);
            P('      [8a] CC/KT + GB -> GREATEST(cc,kl) = ' || v_rang_buoc_lien_ke);
        ELSIF (v_co_canh_cao >= 1 OR v_co_khien_trach >= 1) THEN
            v_rang_buoc_lien_ke := v_he_so_cc;
            P('      [8b] CC/KT -> he_so_cc = ' || v_he_so_cc);
        ELSIF v_co_giam_buong > 0 THEN
            v_rang_buoc_lien_ke := v_he_so_kl;
            P('      [8c] GB -> he_so_kl = ' || v_he_so_kl);
        END IF;
    ELSE
        P('      [8] Chua giam -> khong co rang buoc');
    END IF;

    IF v_is_dac_biet = 1 THEN
        IF v_tong_ngay_an >= 10 * 365 THEN
            v_rang_buoc_lien_ke := GREATEST(v_rang_buoc_lien_ke, v_he_so_db_tren10);
            P('      [8d] DB tren 10nam -> GREATEST(rb, db_tren10) = ' || v_rang_buoc_lien_ke);
        ELSE
            v_rang_buoc_lien_ke := GREATEST(v_rang_buoc_lien_ke, v_he_so_db_duoi10);
            P('      [8e] DB duoi 10nam -> GREATEST(rb, db_duoi10) = ' || v_rang_buoc_lien_ke);
        END IF;
    END IF;
    P('  [8] v_rang_buoc_lien_ke = ' || v_rang_buoc_lien_ke);

    -- ?? [9] RULE lo?i: vi ph?m ng??ng k? lu?t ????????????????
    P('  [9] Kiem tra nguong ky luat...');
    IF v_co_canh_cao > 1 OR v_co_khien_trach > 2 THEN
        P('  [9] LOAI: CC>' || v_co_canh_cao || ' hoac KT>' || v_co_khien_trach || ' -> RETURN NULL');
        RETURN NULL;
    END IF;
    P('  [9] Qua nguong: Khong');

    -- ?? [10] Xác ??nh khung áp d?ng ??????????????????????????
    -- Th? t? ?úng: Khung 2 ? Khung 1 ? Khung 3 (theo FN_XET_DU_DIEU_KIEN_QUY)
    P('  [10] Xac dinh khung...');
    P('      lien_ke_thuc_te=' || v_lien_ke_thuc_te || ', YC_lien_tuc=' || v_yc.SO_QUY_LIEN_TUC);
    P('      tong_thuc_te=' || v_tong_thuc_te || ', YC_khong_lien_tuc=' || v_yc.SO_QUY_KHONG_LIEN_TUC);
    P('      lien_ke_thuc_te=' || v_lien_ke_thuc_te || ', YC_lien_ke=' || v_yc.SO_QUY_LIEN_KE_YC);
    P('      lien_ke_thuc_te=' || v_lien_ke_thuc_te || ', YC_dac_biet=' || v_yc.SO_QUY_TRUONG_HOP_DB);
    P('      is_dac_biet=' || v_is_dac_biet || ', rang_buoc_lien_ke=' || v_rang_buoc_lien_ke);

    -- Khung 2: Không liên t?c (KHÔNG c?n ràng bu?c, ?u tiên cao nh?t)
    IF v_yc.SO_QUY_KHONG_LIEN_TUC > 0
       AND v_tong_thuc_te    >= v_yc.SO_QUY_KHONG_LIEN_TUC
       AND v_lien_ke_thuc_te >= v_yc.SO_QUY_LIEN_KE_YC
    THEN
        v_khung_ap_dung  := 2;
        v_so_quy_can_lay := v_yc.SO_QUY_KHONG_LIEN_TUC;
        P('  [10] KHUNG 2 - KHONG LIEN TUC -> lay ' || v_so_quy_can_lay || ' quy');
    -- Khung 1: Liên t?c (c?n ?? ràng bu?c li?n k?)
    ELSIF v_lien_ke_thuc_te >= v_rang_buoc_lien_ke
      AND v_lien_ke_thuc_te >= v_yc.SO_QUY_LIEN_TUC
    THEN
        v_khung_ap_dung  := 1;
        v_so_quy_can_lay := v_yc.SO_QUY_LIEN_TUC;
        P('  [10] KHUNG 1 - LIEN TUC -> lay ' || v_so_quy_can_lay || ' quy');
    -- Khung 3: ??c bi?t
    ELSIF v_is_dac_biet = 1
      AND v_lien_ke_thuc_te >= v_rang_buoc_lien_ke
      AND v_lien_ke_thuc_te >= v_yc.SO_QUY_TRUONG_HOP_DB
    THEN
        v_khung_ap_dung  := 3;
        v_so_quy_can_lay := v_yc.SO_QUY_TRUONG_HOP_DB;
        P('  [10] KHUNG 3 - DAC BIET -> lay ' || v_so_quy_can_lay || ' quy');
    ELSE
        P('  [10] KHONG XAC DINH DUOC KHUNG NAO -> RETURN NULL');
    END IF;

    IF v_khung_ap_dung = 0 THEN
        P('  [10] v_khung_ap_dung = 0 -> RETURN NULL');
        RETURN NULL;
    END IF;

    -- ?? [11] L?y danh sách quý t? XEP_LOAIS ??????????????????
    P('  [11] Lay danh sach quy (v_so_quy_can_lay=' || v_so_quy_can_lay || ')...');

    IF v_so_lan_giam = 0 THEN
        P('  [11] Chua giam -> lay N quy gan nhat');

        FOR rec IN (
            SELECT *
              FROM (
                  SELECT
                      xl.XEP_LOAI_NAM AS nam_xl,
                      q.quy,
                      CASE q.quy
                          WHEN 1 THEN xl.XEP_LOAI_QUY_I
                          WHEN 2 THEN xl.XEP_LOAI_QUY_II
                          WHEN 3 THEN xl.XEP_LOAI_QUY_III
                          WHEN 4 THEN xl.XEP_LOAI_QUY_IV
                      END AS xlct_id,
                      CASE q.quy
                          WHEN 1 THEN u'Qu\00fd I'
                          WHEN 2 THEN u'Qu\00fd II'
                          WHEN 3 THEN u'Qu\00fd III'
                          WHEN 4 THEN u'Qu\00fd IV'
                      END AS ten_ky,
                      ROW_NUMBER() OVER (ORDER BY xl.XEP_LOAI_NAM DESC, q.quy DESC) AS rn
                    FROM XEP_LOAIS xl
                    CROSS JOIN (
                        SELECT 1 AS quy FROM DUAL UNION ALL
                        SELECT 2 FROM DUAL UNION ALL
                        SELECT 3 FROM DUAL UNION ALL
                        SELECT 4 FROM DUAL
                    ) q
                   WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id
                     AND NVL(xl.IS_DELETED, 0) = 0
                     AND CASE q.quy
                             WHEN 1 THEN xl.XEP_LOAI_QUY_I
                             WHEN 2 THEN xl.XEP_LOAI_QUY_II
                             WHEN 3 THEN xl.XEP_LOAI_QUY_III
                             WHEN 4 THEN xl.XEP_LOAI_QUY_IV
                         END IS NOT NULL
                     AND (   xl.XEP_LOAI_NAM < EXTRACT(YEAR FROM v_ngay_xet)
                          OR (xl.XEP_LOAI_NAM = EXTRACT(YEAR FROM v_ngay_xet)
                              AND q.quy < CASE EXTRACT(MONTH FROM v_ngay_xet)
                                              WHEN 12 THEN 1 WHEN 1 THEN 1 WHEN 2 THEN 1
                                              WHEN 3  THEN 2 WHEN 4 THEN 2 WHEN 5 THEN 2
                                              WHEN 6  THEN 3 WHEN 7 THEN 3 WHEN 8 THEN 3
                                              ELSE 4
                                          END))
              )
             WHERE rn <= v_so_quy_can_lay
             ORDER BY nam_xl, quy
        ) LOOP
            P('  [11]  rec: nam=' || rec.nam_xl || ', quy=' || rec.quy || ', xlct_id=' || rec.xlct_id || ', ten_ky=' || rec.ten_ky);

            BEGIN
                SELECT NVL(xlct.XLCT_TEN, u'Ch\01b0a x\1ebfp lo\1ea1i')
                  INTO v_xl_ten
                  FROM DM_XEP_LOAI_CAI_TAOS xlct
                 WHERE xlct.ID = rec.xlct_id
                   AND NVL(xlct.IS_DELETED, 0) = 0;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN v_xl_ten := u'Ch\01b0a x\1ebfp lo\1ea1i';
            END;
            P('  [11]    xlct=' || v_xl_ten);

            IF v_nam_xl IS NULL OR v_nam_xl <> rec.nam_xl THEN
                v_result := v_result || CHR(10) || TO_CHAR(rec.nam_xl) || ': ' || rec.ten_ky || ': ' || v_xl_ten;
            ELSE
                v_result := v_result || '; ' || rec.ten_ky || ': ' || v_xl_ten;
            END IF;
            v_nam_xl := rec.nam_xl;
        END LOOP;
    ELSE
        P('  [11] Da giam -> lay tu lan giam gan nhat');

        v_nam_xl := NULL;
        FOR rec IN (
            SELECT
                xl.XEP_LOAI_NAM AS nam_xl,
                q.quy,
                CASE q.quy
                    WHEN 1 THEN xl.XEP_LOAI_QUY_I
                    WHEN 2 THEN xl.XEP_LOAI_QUY_II
                    WHEN 3 THEN xl.XEP_LOAI_QUY_III
                    WHEN 4 THEN xl.XEP_LOAI_QUY_IV
                END AS xlct_id,
                CASE q.quy
                    WHEN 1 THEN u'Qu\00fd I'
                    WHEN 2 THEN u'Qu\00fd II'
                    WHEN 3 THEN u'Qu\00fd III'
                    WHEN 4 THEN u'Qu\00fd IV'
                END AS ten_ky
              FROM XEP_LOAIS xl
              CROSS JOIN (
                  SELECT 1 AS quy FROM DUAL UNION ALL
                  SELECT 2 FROM DUAL UNION ALL
                  SELECT 3 FROM DUAL UNION ALL
                  SELECT 4 FROM DUAL
              ) q
             WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id
               AND NVL(xl.IS_DELETED, 0) = 0
               AND CASE q.quy
                       WHEN 1 THEN xl.XEP_LOAI_QUY_I
                       WHEN 2 THEN xl.XEP_LOAI_QUY_II
                       WHEN 3 THEN xl.XEP_LOAI_QUY_III
                       WHEN 4 THEN xl.XEP_LOAI_QUY_IV
                   END IS NOT NULL
               AND xl.XEP_LOAI_NAM >= EXTRACT(YEAR FROM TRUNC(v_ngay_giam_gan, 'MM'))
               AND (   xl.XEP_LOAI_NAM < EXTRACT(YEAR FROM v_ngay_xet)
                    OR (xl.XEP_LOAI_NAM = EXTRACT(YEAR FROM v_ngay_xet)
                        AND q.quy < CASE EXTRACT(MONTH FROM v_ngay_xet)
                                        WHEN 12 THEN 1 WHEN 1 THEN 1 WHEN 2 THEN 1
                                        WHEN 3  THEN 2 WHEN 4 THEN 2 WHEN 5 THEN 2
                                        WHEN 6  THEN 3 WHEN 7 THEN 3 WHEN 8 THEN 3
                                        ELSE 4
                                    END))
             ORDER BY xl.XEP_LOAI_NAM, q.quy
        ) LOOP
            P('  [11]  rec: nam=' || rec.nam_xl || ', quy=' || rec.quy || ', xlct_id=' || rec.xlct_id);

            BEGIN
                SELECT NVL(xlct.XLCT_TEN, u'Ch\01b0a x\1ebfp lo\1ea1i')
                  INTO v_xl_ten
                  FROM DM_XEP_LOAI_CAI_TAOS xlct
                 WHERE xlct.ID = rec.xlct_id
                   AND NVL(xlct.IS_DELETED, 0) = 0;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN v_xl_ten := u'Ch\01b0a x\1ebfp lo\1ea1i';
            END;

            IF v_nam_xl IS NULL OR v_nam_xl <> rec.nam_xl THEN
                v_result := v_result || CHR(10) || TO_CHAR(rec.nam_xl) || ': ' || rec.ten_ky || ': ' || v_xl_ten;
            ELSE
                v_result := v_result || '; ' || rec.ten_ky || ': ' || v_xl_ten;
            END IF;
            v_nam_xl := rec.nam_xl;
        END LOOP;
    END IF;

    P('  [12] v_result = [' || NVL(SUBSTR(v_result, 2), 'NULL') || ']');
    P('=== KET THUC ===');
    RETURN TRIM(LEADING CHR(10) FROM v_result);

EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('  [ERROR] ' || SQLERRM);
        DBMS_OUTPUT.PUT_LINE(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RETURN NULL;
END FN_GET_DS_KY_XEP_LOAI;




/
--------------------------------------------------------
--  DDL for Function FN_GET_GHI_CHU_DAC_BIET
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_GHI_CHU_DAC_BIET" (p_pn_id IN NUMBER)
RETURN VARCHAR2
AS
    v_result VARCHAR2(4000);
BEGIN
    SELECT LISTAGG(gcdb.GCDB_TEN, ', ') WITHIN GROUP (ORDER BY gcdb.GCDB_TEN)
    INTO v_result
    FROM (
        SELECT TO_NUMBER(REGEXP_SUBSTR(
                REPLACE(REPLACE(ptha.THA_GHI_CHU_DAC_BIET, '[', ''), ']', ''),
                '[^,]+', 1, LEVEL
               )) AS GCDB_ID
        FROM PN_THI_HANH_AN ptha
        WHERE ptha.THA_PNLAI_LICH_ID = p_pn_id
          AND ptha.THA_GHI_CHU_DAC_BIET IS NOT NULL
        CONNECT BY REGEXP_SUBSTR(
                REPLACE(REPLACE(ptha.THA_GHI_CHU_DAC_BIET, '[', ''), ']', ''),
                '[^,]+', 1, LEVEL
               ) IS NOT NULL
            AND PRIOR THA_PNLAI_LICH_ID = THA_PNLAI_LICH_ID
            AND PRIOR SYS_GUID() IS NOT NULL
    ) t
    JOIN DM_GHI_CHU_DAC_BIETS gcdb ON gcdb.ID = t.GCDB_ID;

    RETURN v_result;
EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
END FN_GET_GHI_CHU_DAC_BIET;




/
--------------------------------------------------------
--  DDL for Function FN_GET_GHI_CHU_DIEU_KIEN_QUY
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_GHI_CHU_DIEU_KIEN_QUY" (
    p_pham_nhan_id  IN NUMBER,
    p_dk_quy_obj    IN QLPN.DIEU_KIEN_QUY_OBJ  -- nh?n th?ng object t? CTE
) RETURN NVARCHAR2
IS
BEGIN
    -- Object null ho?c không ?? ?K ? không có ghi chú
    IF p_dk_quy_obj IS NULL
       OR p_dk_quy_obj.DU_DIEU_KIEN = 0
       OR p_dk_quy_obj.LOAI IS NULL
       OR p_dk_quy_obj.SO_QUY_YC IS NULL
    THEN
        RETURN NULL;
    END IF;

    -- G?i th?ng hàm li?t kê quý, tham s? ?ã có s?n trong object
    RETURN QLPN.FN_GET_QUY_XEP_LOAI_THOA_MAN(
        p_pham_nhan_id => p_pham_nhan_id,
        p_ngay_xet     => p_dk_quy_obj.NGAY_XET,
        p_so_quy_yc    => p_dk_quy_obj.SO_QUY_YC,
        p_loai         => p_dk_quy_obj.LOAI
    );

EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
END FN_GET_GHI_CHU_DIEU_KIEN_QUY;




/
--------------------------------------------------------
--  DDL for Function FN_GET_GHI_CHU_RIENG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_GHI_CHU_RIENG" (p_pn_id IN NUMBER)
RETURN VARCHAR2
AS
    v_result VARCHAR2(4000);
BEGIN
    SELECT LISTAGG(gcr.GCR_TEN, ', ') WITHIN GROUP (ORDER BY gcr.GCR_TEN)
    INTO v_result
    FROM (
        SELECT TO_NUMBER(REGEXP_SUBSTR(
                REPLACE(REPLACE(pll.LL_GHI_CHU_RIENG, '[', ''), ']', ''),
                '[^,]+', 1, LEVEL
               )) AS GCR_ID
        FROM PN_LAI_LICHS pll
        WHERE pll.ID = p_pn_id
          AND pll.LL_GHI_CHU_RIENG IS NOT NULL
        CONNECT BY REGEXP_SUBSTR(
                REPLACE(REPLACE(pll.LL_GHI_CHU_RIENG, '[', ''), ']', ''),
                '[^,]+', 1, LEVEL
               ) IS NOT NULL
            AND PRIOR ID = ID
            AND PRIOR SYS_GUID() IS NOT NULL
    ) t
    JOIN DM_GHI_CHU_RIENGS gcr ON gcr.ID = t.GCR_ID;

    RETURN v_result;
EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
END FN_GET_GHI_CHU_RIENG;




/
--------------------------------------------------------
--  DDL for Function FN_GET_GIAM_THOI_HAN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_GIAM_THOI_HAN" (
    p_pham_nhan_id IN NUMBER
)
RETURN VARCHAR2
IS
    v_tong_nam   NUMBER := 0;
    v_tong_thang NUMBER := 0;
    v_tong_ngay  NUMBER := 0;
    v_nam        NUMBER;
    v_thang      NUMBER;
    v_ngay       NUMBER;
    v_result     VARCHAR2(200);
BEGIN
    -- Duy?t qua t?t c? các b?n ghi gi?m th?i h?n c?a ph?m nhân
    FOR rec IN (
        SELECT dmtg.MTG_TITLE
        FROM GIAM_THOI_HANS gth
        INNER JOIN DM_MA_THOI_GIANS dmtg ON gth.MUC_GIAM_ID = dmtg.ID
        WHERE gth.PHAM_NHAN_ID = p_pham_nhan_id
          AND dmtg.MTG_TITLE IS NOT NULL
    )
    LOOP
        -- Trích xu?t s? n?m t? chu?i (ví d?: "2 n?m 3 tháng 5 ngày")
        BEGIN
            v_nam := TO_NUMBER(REGEXP_SUBSTR(rec.MTG_TITLE, '(\d+)\s*n?m', 1, 1, NULL, 1));
        EXCEPTION
            WHEN OTHERS THEN v_nam := 0;
        END;

        -- Trích xu?t s? tháng
        BEGIN
            v_thang := TO_NUMBER(REGEXP_SUBSTR(rec.MTG_TITLE, '(\d+)\s*tháng', 1, 1, NULL, 1));
        EXCEPTION
            WHEN OTHERS THEN v_thang := 0;
        END;

        -- Trích xu?t s? ngày
        BEGIN
            v_ngay := TO_NUMBER(REGEXP_SUBSTR(rec.MTG_TITLE, '(\d+)\s*ngày', 1, 1, NULL, 1));
        EXCEPTION
            WHEN OTHERS THEN v_ngay := 0;
        END;

        -- C?ng d?n vào t?ng
        v_tong_nam   := v_tong_nam   + NVL(v_nam, 0);
        v_tong_thang := v_tong_thang + NVL(v_thang, 0);
        v_tong_ngay  := v_tong_ngay  + NVL(v_ngay, 0);
    END LOOP;

    -- Chu?n hóa: chuy?n ??i ngày thành tháng, tháng thành n?m
    -- Gi? ??nh: 30 ngày = 1 tháng, 12 tháng = 1 n?m
    IF v_tong_ngay >= 30 THEN
        v_tong_thang := v_tong_thang + FLOOR(v_tong_ngay / 30);
        v_tong_ngay  := MOD(v_tong_ngay, 30);
    END IF;

    IF v_tong_thang >= 12 THEN
        v_tong_nam   := v_tong_nam + FLOOR(v_tong_thang / 12);
        v_tong_thang := MOD(v_tong_thang, 12);
    END IF;

    -- T?o chu?i k?t qu?
    v_result := '';

    IF v_tong_nam > 0 THEN
        v_result := v_result || v_tong_nam || ' n?m ';
    END IF;

    IF v_tong_thang > 0 THEN
        v_result := v_result || v_tong_thang || ' tháng ';
    END IF;

    IF v_tong_ngay > 0 THEN
        v_result := v_result || v_tong_ngay || ' ngày';
    END IF;

    -- N?u không có gì thì tr? v? "0 ngày"
    IF v_result IS NULL OR TRIM(v_result) = '' THEN
        v_result := 'Không';
    END IF;

    RETURN TRIM(v_result);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Không';
    WHEN OTHERS THEN
        RETURN 'Không';
END FN_GET_GIAM_THOI_HAN;





/
--------------------------------------------------------
--  DDL for Function FN_GET_HO_TEN_VC
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_HO_TEN_VC" (p_pham_nhan_id IN NUMBER) RETURN NVARCHAR2 IS
  v_result NVARCHAR2(500);
BEGIN
  SELECT tn.HO_TEN_THAN_NHAN INTO v_result FROM THAN_NHAN_NGUOI_THANS tn
  WHERE tn.PHAM_NHAN_ID = p_pham_nhan_id AND tn.QUAN_HE_ID IN (23, 42) AND NVL(tn.IS_DELETED, 0) = 0 FETCH FIRST 1 ROW ONLY;
  RETURN v_result;
EXCEPTION WHEN NO_DATA_FOUND THEN RETURN u'ch\01b0a c\00f3';
END FN_GET_HO_TEN_VC;






/
--------------------------------------------------------
--  DDL for Function FN_GET_KET_QUA_CAI_TAO_STR
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_KET_QUA_CAI_TAO_STR" (
    p_PHAM_NHAN_ID IN NUMBER
)
RETURN VARCHAR2
IS
    v_result VARCHAR2(4000);
BEGIN
    SELECT LISTAGG(
               'N?m ' || k.NAM ||
               ': Q1=' || k.QUY_1 ||
               ', Q2=' || k.QUY_2 ||
               ', 6T?N=' || k.DAU_NAM ||
               ', Q3=' || k.QUY_3 ||
               ', Q4=' || k.QUY_4 ||
               ', 6TCN=' || k.CUOI_NAM ||
               ', C? n?m=' || k.CA_NAM,
               ' | '
           ) WITHIN GROUP (ORDER BY k.NAM)
    INTO v_result
    FROM TABLE(FN_GET_KET_QUA_CAI_TAO(p_PHAM_NHAN_ID)) k;

    RETURN v_result;
END;






/
--------------------------------------------------------
--  DDL for Function FN_GET_KY_THA_CDK_XL
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_KY_THA_CDK_XL" (
    p_PHAM_NHAN_ID IN NUMBER,
    p_NGAY_XET     IN DATE,
    p_LOAI         IN NUMBER DEFAULT 0 -- 0: Ng?n g?n (Q1: Khá), 1: Chi ti?t (Quý I: Khá)
) RETURN NVARCHAR2
IS
    v_an_phat_txt     NVARCHAR2(2000);
    v_so_ky           NUMBER := 0;
    v_result          NVARCHAR2(4000) := '';
    v_result_dai      NVARCHAR2(4000) := '';
    v_nam_tam         NUMBER;

    v_thang_xet       NUMBER := EXTRACT(MONTH FROM p_NGAY_XET);
    v_nam_xet         NUMBER := EXTRACT(YEAR FROM p_NGAY_XET);

    v_quy_extra       NVARCHAR2(500) := '';
    v_quy_extra_dai   NVARCHAR2(500) := '';
    v_extra_xl_label  NVARCHAR2(200) := '';
    v_extra_xl_detail NVARCHAR2(200) := '';
    v_extra_found     NUMBER := 0;
    v_extra_nam       NUMBER;
    v_limit           NUMBER := 0;
    v_latest_xl_ten   NVARCHAR2(200) := '';
BEGIN
    -- 1. L?y thông tin án ph?t ?? xác ??nh s? k? c?n l?y
    BEGIN
        SELECT AN_PHAT INTO v_an_phat_txt
        FROM QLPN.VW_PN_LAI_LICH_CHI_TIET
        WHERE PHAM_NHAN_ID = p_PHAM_NHAN_ID
          AND ROWNUM = 1;
    EXCEPTION
        WHEN OTHERS THEN v_an_phat_txt := NULL;
    END;

    -- Xác ??nh s? k? (so_ky) d?a trên m?c án
    DECLARE
        v_muc_an_cat NVARCHAR2(500);
    BEGIN
        v_muc_an_cat := QLPN.FN_GET_MUC_AN_PHAT_TCDK(v_an_phat_txt);

        -- S? d?ng LIKE và t? khóa ?? so kh?p b?n v?ng h?n
        IF v_muc_an_cat LIKE u'%Chung th\00e2n%' THEN v_so_ky := 20;
        ELSIF v_muc_an_cat LIKE u'%20 - 30 n\0103m%' THEN v_so_ky := 16;
        ELSIF v_muc_an_cat LIKE u'%15 - 20 n\0103m%' THEN v_so_ky := 12;
        ELSIF v_muc_an_cat LIKE u'%10 - 15 n\0103m%' THEN v_so_ky := 8;
        ELSIF v_muc_an_cat LIKE u'%5 - 10 n\0103m%' THEN v_so_ky := 6;
        ELSIF v_muc_an_cat LIKE u'%3 - 5 n\0103m%'  THEN v_so_ky := 4;
        ELSIF v_muc_an_cat LIKE u'%d\01b0\1edbi 3 n\0103m%' OR v_muc_an_cat LIKE u'%\00edt h\01a1n 3 n\0103m%' THEN v_so_ky := 2;
        ELSE 
            -- M?c ??nh l?y theo ng??ng n?m n?u không map ???c b?ng chu?i dac_xa
            v_so_ky := 2; 
        END IF;
    END;

    IF v_so_ky = 0 THEN RETURN NULL; END IF;

    IF v_so_ky = 0 THEN RETURN NULL; END IF;

    -- 2. X? lý Quý ?ang xét (Extra) tr??c ?? tr? vào gi?i h?n loop
    -- ??t 1 (Tháng 3, 4, 5): Th??ng xét b? sung Quý I
    IF v_thang_xet IN (3, 4, 5) THEN
        BEGIN
            SELECT dm.XLCT_TEN, dm.XLCT_TEN
            INTO v_extra_xl_label, v_extra_xl_detail
            FROM QLPN.XEP_LOAIS x
            JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm ON dm.ID = x.XEP_LOAI_QUY_I AND NVL(dm.IS_DELETED,0)=0
            WHERE x.PHAM_NHAN_ID = p_PHAM_NHAN_ID 
              AND x.XEP_LOAI_NAM = v_nam_xet
              AND NVL(x.IS_DELETED,0)=0 AND x.XEP_LOAI_QUY_I IS NOT NULL;
            v_extra_found := 1;
            v_extra_nam := v_nam_xet;
            v_quy_extra := '; Q1: ' || v_extra_xl_label;
            v_quy_extra_dai := '; Quý 1: ' || v_extra_xl_detail;
            v_latest_xl_ten := v_extra_xl_label;
        EXCEPTION WHEN OTHERS THEN v_extra_found := 0;
        END;
    -- ??t 2 (Tháng 11, 12 ho?c tháng 1 n?m sau): Th??ng xét b? sung Quý III
    ELSIF (v_thang_xet IN (11, 12) OR v_thang_xet = 1) THEN
        BEGIN
            v_extra_nam := (CASE WHEN v_thang_xet = 1 THEN v_nam_xet - 1 ELSE v_nam_xet END);
            SELECT dm.XLCT_TEN, dm.XLCT_TEN
            INTO v_extra_xl_label, v_extra_xl_detail
            FROM QLPN.XEP_LOAIS x
            JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm ON dm.ID = x.XEP_LOAI_QUY_III AND NVL(dm.IS_DELETED,0)=0
            WHERE x.PHAM_NHAN_ID = p_PHAM_NHAN_ID 
              AND x.XEP_LOAI_NAM = v_extra_nam
              AND NVL(x.IS_DELETED,0)=0 AND x.XEP_LOAI_QUY_III IS NOT NULL;
            v_extra_found := 1;
            v_quy_extra := '; Q3: ' || v_extra_xl_label;
            v_quy_extra_dai := '; Quý 3: ' || v_extra_xl_detail;
            v_latest_xl_ten := v_extra_xl_label;
        EXCEPTION WHEN OTHERS THEN v_extra_found := 0;
        END;
    END IF;

    v_limit := v_so_ky - v_extra_found;

    -- 3. L?y danh sách k?t qu? x?p lo?i các quý g?n nh?t
    FOR r IN (
        WITH quarters AS (
            SELECT PHAM_NHAN_ID, XEP_LOAI_NAM AS nam, 'Q1' AS ky_ma, u'Qu\00fd 1' AS ky_label, 1 AS sort_order, XEP_LOAI_QUY_I AS xl_id, TO_DATE('31/03/'||XEP_LOAI_NAM, 'DD/MM/YYYY') AS ngay_xl FROM QLPN.XEP_LOAIS WHERE NVL(IS_DELETED,0)=0
            UNION ALL
            SELECT PHAM_NHAN_ID, XEP_LOAI_NAM, 'Q2', u'Qu\00fd 2', 2, XEP_LOAI_QUY_II, TO_DATE('30/06/'||XEP_LOAI_NAM, 'DD/MM/YYYY') FROM QLPN.XEP_LOAIS WHERE NVL(IS_DELETED,0)=0
            UNION ALL
            SELECT PHAM_NHAN_ID, XEP_LOAI_NAM, 'Q3', u'Qu\00fd 3', 3, XEP_LOAI_QUY_III, TO_DATE('30/09/'||XEP_LOAI_NAM, 'DD/MM/YYYY') FROM QLPN.XEP_LOAIS WHERE NVL(IS_DELETED,0)=0
            UNION ALL
            SELECT PHAM_NHAN_ID, XEP_LOAI_NAM, 'Q4', u'Qu\00fd 4', 4, XEP_LOAI_QUY_IV, TO_DATE('31/12/'||XEP_LOAI_NAM, 'DD/MM/YYYY') FROM QLPN.XEP_LOAIS WHERE NVL(IS_DELETED,0)=0
        )
        SELECT * FROM (
            SELECT q.nam, q.ky_ma, q.ky_label, dm.XLCT_TEN, q.ngay_xl
            FROM quarters q
            JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm ON dm.ID = q.xl_id AND NVL(dm.IS_DELETED,0)=0
            WHERE q.PHAM_NHAN_ID = p_PHAM_NHAN_ID
              AND q.ngay_xl < p_NGAY_XET
            ORDER BY q.ngay_xl DESC
        ) WHERE ROWNUM <= v_limit
        ORDER BY ngay_xl ASC
    ) LOOP
        -- Gi? l?i x?p lo?i m?i nh?t n?u ch?a có t? v_quy_extra
        IF v_latest_xl_ten IS NULL OR v_extra_found = 0 THEN
            v_latest_xl_ten := r.XLCT_TEN;
        END IF;

        IF v_nam_tam IS NULL OR v_nam_tam <> r.nam THEN
            v_result := v_result || CHR(10) || r.nam || ': ' || r.ky_ma || ': ' || r.XLCT_TEN;
            v_result_dai := v_result_dai || CHR(10) || '+ N?m ' || r.nam || ': ' || r.ky_label || ': ' || r.XLCT_TEN;
        ELSE
            v_result := v_result || '; ' || r.ky_ma || ': ' || r.XLCT_TEN;
            v_result_dai := v_result_dai || '; ' || r.ky_label || ': ' || r.XLCT_TEN;
        END IF;
        v_nam_tam := r.nam;
    END LOOP;

    -- X? lý thêm dòng cho Extra Quarter (??m b?o ?úng format xu?ng dòng n?u c?n)
    IF v_extra_found = 1 THEN
        IF v_nam_tam IS NULL OR v_nam_tam <> v_extra_nam THEN
            v_quy_extra := CHR(10) || v_extra_nam || ': ' || SUBSTR(v_quy_extra, 3);
            v_quy_extra_dai := CHR(10) || '+ N?m ' || v_extra_nam || ': ' || SUBSTR(v_quy_extra_dai, 3);
        END IF;
    END IF;

    -- 4. Tr? k?t qu? kèm ph?n h?u t? ?ánh giá ti?p theo
    IF p_LOAI = 1 THEN
        v_result_dai := NVL(SUBSTR(v_result_dai, 2), u'') || v_quy_extra_dai;
        IF v_latest_xl_ten IS NOT NULL THEN
            v_result_dai := v_result_dai || CHR(10) || u'Th\1eddi gian ti\1ebfp theo \111\01b0\1ee3c \111\00e1nh gi\00e1 c\1ea3i t\1ea1o: ' || v_latest_xl_ten;
        END IF;
        RETURN v_result_dai;
    ELSE
        v_result := NVL(SUBSTR(v_result, 2), u'') || v_quy_extra;
        IF v_latest_xl_ten IS NOT NULL THEN
            v_result := v_result || CHR(10) || u'Th\1eddi gian ti\1ebfp theo \111\01b0\1ee3c \111\00e1nh gi\00e1 c\1ea3i t\1ea1o: ' || v_latest_xl_ten;
        END IF;
        RETURN v_result;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN NULL;
END FN_GET_KY_THA_CDK_XL;

/
--------------------------------------------------------
--  DDL for Function FN_GET_LIET_KE_HPBS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_LIET_KE_HPBS" (
    v_PHAM_NHAN_ID NUMBER
)
RETURN VARCHAR2
IS
    v_tnds   VARCHAR2(4000);
    v_tien   VARCHAR2(4000);
    v_khac   VARCHAR2(4000);
    v_result VARCHAR2(4000);
BEGIN
    v_tnds := QLPN.FN_GET_LIET_KE_TRACH_NHIEM_DAN_SU_TIEN(v_PHAM_NHAN_ID);
    v_tien := QLPN.FN_GET_LIET_KE_HPBS_TIEN(v_PHAM_NHAN_ID);
    v_khac := QLPN.FN_GET_LIET_KE_HPBS_KHAC(v_PHAM_NHAN_ID);

    IF LENGTH(TRIM(NVL(v_tnds, ''))) > 0 THEN
        v_result := TRIM(v_tnds);
    END IF;

    IF LENGTH(TRIM(NVL(v_tien, ''))) > 0 THEN
        IF v_result IS NOT NULL THEN
            v_result := v_result || CHR(10);
        END IF;
        v_result := v_result || TRIM(v_tien);
    END IF;

    IF LENGTH(TRIM(NVL(v_khac, ''))) > 0 THEN
        IF v_result IS NOT NULL THEN
            v_result := v_result || CHR(10);
        END IF;
        v_result := v_result || TRIM(v_khac);
    END IF;

    RETURN NVL(v_result, '');
END FN_GET_LIET_KE_HPBS;




