/
--------------------------------------------------------
--  DDL for Function FN_GET_LIET_KE_HPBS_BANG_TIEN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_LIET_KE_HPBS_BANG_TIEN" (
    v_PHAM_NHAN_ID NUMBER
)
RETURN VARCHAR2
IS
    v_result VARCHAR2(4000);
BEGIN
    SELECT LISTAGG(dm.HPBS_TEN, '; ')
           WITHIN GROUP (ORDER BY dm.HPBS_TEN)
    INTO v_result
    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
    INNER JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
        ON dm.ID = hp.HPBS_HINH_PHAT
       AND NVL(dm.IS_DELETED, 0) = 0
       AND UPPER(TRIM(NVL(CAST(dm.HPBS_LOAI_HPBS AS VARCHAR2(50)), ''))) = 'HPBST'
    WHERE hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
      AND NVL(hp.IS_DELETED, 0) = 0;

    RETURN NVL(v_result, '');
END FN_GET_LIET_KE_HPBS_BANG_TIEN;



/
--------------------------------------------------------
--  DDL for Function FN_GET_LIET_KE_HPBS_CHI_TIET
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_LIET_KE_HPBS_CHI_TIET" (
--Li?t kê t?t c? các laoij trong b?ng DM_HINH_PHAT_BO_SUNGS
    v_PHAM_NHAN_ID NUMBER
)
RETURN VARCHAR2
IS
    v_tnds   VARCHAR2(4000);
    v_tien   VARCHAR2(4000);
    v_khac   VARCHAR2(4000);
    v_result VARCHAR2(4000);
    c_fmt CONSTANT VARCHAR2(200) := 'FM999G999G999G999G999G999G999G999G999';
BEGIN
  /* TNDS — trách nhi?m dân s? (ti?n) */
    SELECT LISTAGG(
               '+ ' || CAST(dm.HPBS_TEN AS VARCHAR2(500))
               || CASE
                    WHEN NVL(hp.HPBS_TONG_TIEN_PHAT, 0) > 0 THEN
                         ' ' || TO_CHAR(hp.HPBS_TONG_TIEN_PHAT, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') || ' ??ng'
                         || ', ?ã n?p '
                         || TO_CHAR(
                                NVL(hp.HPBS_TONG_TIEN_PHAT, 0) - NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0),
                                c_fmt,
                                'NLS_NUMERIC_CHARACTERS = '',.'''
                            )
                         || ' ??ng'
                         || CASE
                              WHEN NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0) > 0 THEN
                                   ', còn l?i '
                                   || TO_CHAR(hp.HPBS_TONG_TIEN_CON_LAI, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''')
                                   || ' ??ng'
                              WHEN NVL(hp.HPBS_TONG_TIEN_PHAT, 0) > 0
                               AND NVL(hp.HPBS_TONG_TIEN_PHAT, 0) - NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0)
                                   = NVL(hp.HPBS_TONG_TIEN_PHAT, 0) THEN
                                   ' (?ã ch?p hành xong hình ph?t)'
                              ELSE
                                   ''
                            END
                    ELSE
                         ''
                  END,
               CHR(10)
           )
           WITHIN GROUP (ORDER BY CAST(dm.HPBS_TEN AS VARCHAR2(500)))
    INTO v_tnds
    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
    JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
      ON dm.ID = hp.HPBS_HINH_PHAT
     AND NVL(dm.IS_DELETED, 0) = 0
     AND UPPER(TRIM(NVL(CAST(dm.HPBS_LOAI_HPBS AS VARCHAR2(50)), ''))) = 'TNDS'
    WHERE hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
      AND NVL(hp.IS_DELETED, 0) = 0;

  /* HPBST — hình ph?t b? sung ti?n */
    SELECT LISTAGG(
               '+ ' || CAST(dm.HPBS_TEN AS VARCHAR2(500))
               || CASE
                    WHEN NVL(hp.HPBS_TONG_TIEN_PHAT, 0) > 0 THEN
                         ' ' || TO_CHAR(hp.HPBS_TONG_TIEN_PHAT, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') || ' ??ng'
                         || ', ?ã n?p '
                         || TO_CHAR(
                                NVL(hp.HPBS_TONG_TIEN_PHAT, 0) - NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0),
                                c_fmt,
                                'NLS_NUMERIC_CHARACTERS = '',.'''
                            )
                         || ' ??ng'
                         || CASE
                              WHEN NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0) > 0 THEN
                                   ', còn l?i '
                                   || TO_CHAR(hp.HPBS_TONG_TIEN_CON_LAI, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''')
                                   || ' ??ng'
                              WHEN NVL(hp.HPBS_TONG_TIEN_PHAT, 0) > 0
                               AND NVL(hp.HPBS_TONG_TIEN_PHAT, 0) - NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0)
                                   = NVL(hp.HPBS_TONG_TIEN_PHAT, 0) THEN
                                   ' (?ã ch?p hành xong hình ph?t)'
                              ELSE
                                   ''
                            END
                    ELSE
                         ''
                  END,
               CHR(10)
           )
           WITHIN GROUP (ORDER BY CAST(dm.HPBS_TEN AS VARCHAR2(500)))
    INTO v_tien
    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
    JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
      ON dm.ID = hp.HPBS_HINH_PHAT
     AND NVL(dm.IS_DELETED, 0) = 0
     AND UPPER(TRIM(NVL(CAST(dm.HPBS_LOAI_HPBS AS VARCHAR2(50)), ''))) = 'HPBST'
    WHERE hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
      AND NVL(hp.IS_DELETED, 0) = 0;

  /* HPBS — hình ph?t b? sung khác (không ti?n) */
    SELECT LISTAGG(
               '+ ' || CAST(dm.HPBS_TEN AS VARCHAR2(500))
               || CASE
                    WHEN hp.HPBS_GHI_CHU_CHI_TIET IS NOT NULL
                     AND LENGTH(TRIM(CAST(hp.HPBS_GHI_CHU_CHI_TIET AS VARCHAR2(500)))) > 0 THEN
                         ' (' || TRIM(CAST(hp.HPBS_GHI_CHU_CHI_TIET AS VARCHAR2(500))) || ')'
                    ELSE
                         ''
                  END,
               CHR(10)
           )
           WITHIN GROUP (ORDER BY CAST(dm.HPBS_TEN AS VARCHAR2(500)))
    INTO v_khac
    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
    JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
      ON dm.ID = hp.HPBS_HINH_PHAT
     AND NVL(dm.IS_DELETED, 0) = 0
     AND UPPER(TRIM(NVL(CAST(dm.HPBS_LOAI_HPBS AS VARCHAR2(50)), ''))) = 'HPBS'
    WHERE hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
      AND NVL(hp.IS_DELETED, 0) = 0;

    IF LENGTH(TRIM(NVL(v_tnds, ''))) > 0 THEN
        v_result := '- Trách nhi?m dân s? :' || CHR(10) || TRIM(v_tnds);
    END IF;

    IF LENGTH(TRIM(NVL(v_tien, ''))) > 0 THEN
        IF v_result IS NOT NULL THEN
            v_result := v_result || CHR(10);
        END IF;
        v_result := v_result || '- Hình ph?t b? sung là ti?n:' || CHR(10) || TRIM(v_tien);
    END IF;

    IF LENGTH(TRIM(NVL(v_khac, ''))) > 0 THEN
        IF v_result IS NOT NULL THEN
            v_result := v_result || CHR(10);
        END IF;
        v_result := v_result || '- Hình ph?t b? sung khác:' || CHR(10) || TRIM(v_khac);
    END IF;

    RETURN NVL(v_result, '');
END FN_GET_LIET_KE_HPBS_CHI_TIET;




/
--------------------------------------------------------
--  DDL for Function FN_GET_LIET_KE_HPBS_CHI_TIET_GHI_CHU
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_LIET_KE_HPBS_CHI_TIET_GHI_CHU" (
    v_PHAM_NHAN_ID NUMBER
)
RETURN VARCHAR2
IS
    v_result VARCHAR2(4000);
BEGIN
    SELECT LISTAGG(
               dm.HPBS_TEN
               || ' '
               || TO_CHAR(hp.HPBS_TONG_TIEN_PHAT, 'FM999G999G999G999G999G999G999G999G999')
               || ' ??ng'
               || CASE
                    WHEN NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0) = NVL(hp.HPBS_TONG_TIEN_PHAT, 0)
                        THEN ' (ch?a n?p)'
                    ELSE
                        ' (?ã n?p '
                        || TO_CHAR(
                               NVL(hp.HPBS_TONG_TIEN_PHAT, 0) - NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0),
                               'FM999G999G999G999G999G999G999G999G999'
                           )
                        || ' ??ng)'
                  END
               -- Ghi chú n?i th?ng sau, cách nhau 1 d?u cách
               || CASE
                    WHEN NULLIF(TRIM(TO_CHAR(hp.HPBS_GHI_CHU_CHI_TIET)), '') IS NOT NULL
                        THEN ' ' || TRIM(TO_CHAR(hp.HPBS_GHI_CHU_CHI_TIET))
                    ELSE ''
                  END,
               '; '
           )
           WITHIN GROUP (ORDER BY dm.HPBS_TEN)
    INTO v_result
    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
    JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
        ON dm.ID = hp.HPBS_HINH_PHAT
       AND dm.IS_DELETED = 0
    WHERE hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
      AND hp.IS_DELETED = 0;

    RETURN NVL(v_result, '');
END FN_GET_LIET_KE_HPBS_CHI_TIET_GHI_CHU;




/
--------------------------------------------------------
--  DDL for Function FN_GET_LIET_KE_HPBS_HPBST
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_LIET_KE_HPBS_HPBST" (
--Li?t kê t?t c? các lo?i là HPBS và HPBST trong b?ng DM_HINH_PHAT_BO_SUNGS
    v_PHAM_NHAN_ID NUMBER
)
RETURN VARCHAR2
IS
    v_tnds   VARCHAR2(4000);
    v_tien   VARCHAR2(4000);
    v_khac   VARCHAR2(4000);
    v_result VARCHAR2(4000);
    c_fmt CONSTANT VARCHAR2(200) := 'FM999G999G999G999G999G999G999G999G999';
BEGIN

  /* HPBST — hình ph?t b? sung ti?n */
    SELECT LISTAGG(
               '+ ' || CAST(dm.HPBS_TEN AS VARCHAR2(500))
               || CASE
                    WHEN NVL(hp.HPBS_TONG_TIEN_PHAT, 0) > 0 THEN
                         ' ' || TO_CHAR(hp.HPBS_TONG_TIEN_PHAT, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') || ' ??ng'
                         || ', ?ã n?p '
                         || TO_CHAR(
                                NVL(hp.HPBS_TONG_TIEN_PHAT, 0) - NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0),
                                c_fmt,
                                'NLS_NUMERIC_CHARACTERS = '',.'''
                            )
                         || ' ??ng'
                         || CASE
                              WHEN NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0) > 0 THEN
                                   ', còn l?i '
                                   || TO_CHAR(hp.HPBS_TONG_TIEN_CON_LAI, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''')
                                   || ' ??ng'
                              WHEN NVL(hp.HPBS_TONG_TIEN_PHAT, 0) > 0
                               AND NVL(hp.HPBS_TONG_TIEN_PHAT, 0) - NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0)
                                   = NVL(hp.HPBS_TONG_TIEN_PHAT, 0) THEN
                                   ' (?ã ch?p hành xong hình ph?t)'
                              ELSE
                                   ''
                            END
                    ELSE
                         ''
                  END,
               CHR(10)
           )
           WITHIN GROUP (ORDER BY CAST(dm.HPBS_TEN AS VARCHAR2(500)))
    INTO v_tien
    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
    JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
      ON dm.ID = hp.HPBS_HINH_PHAT
     AND NVL(dm.IS_DELETED, 0) = 0
     AND UPPER(TRIM(NVL(CAST(dm.HPBS_LOAI_HPBS AS VARCHAR2(50)), ''))) = 'HPBST'
    WHERE hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
      AND NVL(hp.IS_DELETED, 0) = 0;

  /* HPBS — hình ph?t b? sung khác (không ti?n) */
    SELECT LISTAGG(
               '+ ' || CAST(dm.HPBS_TEN AS VARCHAR2(500))
               || CASE
                    WHEN hp.HPBS_GHI_CHU_CHI_TIET IS NOT NULL
                     AND LENGTH(TRIM(CAST(hp.HPBS_GHI_CHU_CHI_TIET AS VARCHAR2(500)))) > 0 THEN
                         ' (' || TRIM(CAST(hp.HPBS_GHI_CHU_CHI_TIET AS VARCHAR2(500))) || ')'
                    ELSE
                         ''
                  END,
               CHR(10)
           )
           WITHIN GROUP (ORDER BY CAST(dm.HPBS_TEN AS VARCHAR2(500)))
    INTO v_khac
    FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
    JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
      ON dm.ID = hp.HPBS_HINH_PHAT
     AND NVL(dm.IS_DELETED, 0) = 0
     AND UPPER(TRIM(NVL(CAST(dm.HPBS_LOAI_HPBS AS VARCHAR2(50)), ''))) = 'HPBS'
    WHERE hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
      AND NVL(hp.IS_DELETED, 0) = 0;


    IF LENGTH(TRIM(NVL(v_tien, ''))) > 0 THEN
        IF v_result IS NOT NULL THEN
            v_result := v_result || CHR(10);
        END IF;
        v_result := v_result || '- Hình ph?t b? sung là ti?n:' || CHR(10) || TRIM(v_tien);
    END IF;

    IF LENGTH(TRIM(NVL(v_khac, ''))) > 0 THEN
        IF v_result IS NOT NULL THEN
            v_result := v_result || CHR(10);
        END IF;
        v_result := v_result || '- Hình ph?t b? sung khác:' || CHR(10) || TRIM(v_khac);
    END IF;

    RETURN NVL(v_result, '');
END ;




