/
--------------------------------------------------------
--  DDL for Function FN_GET_LIST_GHI_CHU_RIENG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_LIST_GHI_CHU_RIENG" (
    p_ids IN NVARCHAR2
) RETURN NVARCHAR2 IS
    v_csv NVARCHAR2(32767);
    v_ret NVARCHAR2(32767);
BEGIN
    IF p_ids IS NULL OR LENGTH(TRIM(p_ids)) = 0 THEN
        RETURN NULL;
    END IF;

    v_csv := REPLACE(
        REPLACE(REPLACE(TRIM(p_ids), '[', ''), ']', ''),
        UNISTR('\FF0C'),
        ','
    );

    IF LENGTH(TRIM(v_csv)) = 0 OR NOT REGEXP_LIKE(v_csv, '[0-9]') THEN
        RETURN NULL;
    END IF;

    SELECT LISTAGG(g.GCR_TEN, '; ') WITHIN GROUP (ORDER BY x.FIRST_ORD)
      INTO v_ret
      FROM (
               SELECT TO_NUMBER(TRIM(tok.TOK)) AS GCR_ID,
                      MIN(tok.ORD_ROW)          AS FIRST_ORD
               FROM (
                        SELECT LEVEL                                              AS ORD_ROW,
                               TRIM(REGEXP_SUBSTR(v_csv, '[^,]+', 1, LEVEL)) AS TOK
                        FROM dual
                        CONNECT BY LEVEL <= REGEXP_COUNT(v_csv, ',') + 1
                    ) tok
               WHERE tok.TOK IS NOT NULL
                 AND REGEXP_LIKE(TRIM(tok.TOK), '^[0-9]+$')
               GROUP BY TO_NUMBER(TRIM(tok.TOK))
           ) x
               INNER JOIN DM_GHI_CHU_RIENGS g
                          ON g.ID = x.GCR_ID
                              AND NVL(g.IS_DELETED, 0) = 0;

    RETURN v_ret;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN NULL;
END FN_GET_LIST_GHI_CHU_RIENG;




/
--------------------------------------------------------
--  DDL for Function FN_GET_LIST_TOI_DANH
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_LIST_TOI_DANH" (
    p_ids IN NVARCHAR2
) RETURN NVARCHAR2 IS
    v_csv NVARCHAR2(32767);
    v_ret NVARCHAR2(32767);
BEGIN
    IF p_ids IS NULL OR LENGTH(TRIM(p_ids)) = 0 THEN
        RETURN NULL;
    END IF;

    v_csv := REPLACE(
        REPLACE(REPLACE(TRIM(p_ids), '[', ''), ']', ''),
        UNISTR('\FF0C'),
        ','
    );

    IF LENGTH(TRIM(v_csv)) = 0 OR NOT REGEXP_LIKE(v_csv, '[0-9]') THEN
        RETURN NULL;
    END IF;

    SELECT LISTAGG(td.TD_TEN, '; ') WITHIN GROUP (ORDER BY x.FIRST_ORD)
      INTO v_ret
      FROM (
               SELECT TO_NUMBER(TRIM(tok.TOK)) AS TID,
                      MIN(tok.ORD_ROW)          AS FIRST_ORD
               FROM (
                        SELECT LEVEL                                              AS ORD_ROW,
                               TRIM(REGEXP_SUBSTR(v_csv, '[^,]+', 1, LEVEL)) AS TOK
                        FROM dual
                        CONNECT BY LEVEL <= REGEXP_COUNT(v_csv, ',') + 1
                    ) tok
               WHERE tok.TOK IS NOT NULL
                 AND REGEXP_LIKE(TRIM(tok.TOK), '^[0-9]+$')
               GROUP BY TO_NUMBER(TRIM(tok.TOK))
           ) x
               INNER JOIN DM_TOI_DANHS td
                          ON td.ID = x.TID
                              AND NVL(td.IS_DELETED, 0) = 0;

    RETURN v_ret;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN NULL;
END FN_GET_LIST_TOI_DANH;




/
--------------------------------------------------------
--  DDL for Function FN_GET_MUC_AN_ID_GTH
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_MUC_AN_ID_GTH" (
    p_an_phat IN NVARCHAR2
)
RETURN NUMBER
IS
    v_nam        NUMBER := 0;
    v_thang      NUMBER := 0;
    v_ngay       NUMBER := 0;
    v_tong_thang NUMBER := 0;
    v_text       NVARCHAR2(1000);
BEGIN
    IF p_an_phat IS NULL THEN RETURN NULL; END IF;

    v_text := UPPER(TRIM(p_an_phat));

    -- Chung thân gi?m xu?ng 30 n?m
    IF v_text LIKE '%CHUNG TH%N%GI%M%30%' THEN
        RETURN 6;
    END IF;

    -- Chung thân gi?m xu?ng 20 n?m
    IF v_text LIKE '%CHUNG TH%N%GI%M%20%' THEN
        RETURN 5;
    END IF;

    -- Chung thân thông th??ng
    IF v_text LIKE '%CHUNG TH%N%' THEN
        RETURN 7;
    END IF;

    BEGIN
        v_nam := NVL(
            TO_NUMBER(REGEXP_SUBSTR(v_text, '(\d+)\s*N.M', 1, 1, NULL, 1)),
            0
        );
    EXCEPTION
        WHEN OTHERS THEN v_nam := 0;
    END;

    BEGIN
        v_thang := NVL(
            TO_NUMBER(REGEXP_SUBSTR(v_text, '(\d+)\s*TH.NG', 1, 1, NULL, 1)),
            0
        );
    EXCEPTION
        WHEN OTHERS THEN v_thang := 0;
    END;
-- Trích xu?t ngày: l?y s? ??ng TR??C t? "NGÀY"
    BEGIN
        v_ngay := NVL(
            TO_NUMBER(REGEXP_SUBSTR(v_text, '(\d+)\s*NG.Y', 1, 1, NULL, 1)),
            0
        );
    EXCEPTION
        WHEN OTHERS THEN v_ngay := 0;
    END;

    -- Quy ??i: 30 ngày = 1 tháng (làm tròn lên)
    v_tong_thang := (v_nam * 12) + v_thang + CEIL(v_ngay / 30);

    -- Phân lo?i m?c án
    IF    v_tong_thang <= 36  THEN RETURN 1;
    ELSIF v_tong_thang <= 60  THEN RETURN 2;
    ELSIF v_tong_thang <= 120 THEN RETURN 3;
    ELSIF v_tong_thang <= 180 THEN RETURN 4;
    ELSIF v_tong_thang <= 240 THEN RETURN 5;
    ELSIF v_tong_thang <= 360 THEN RETURN 6;
    ELSE                           RETURN 7;
    END IF;

EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
END FN_GET_MUC_AN_ID_GTH;




/
--------------------------------------------------------
--  DDL for Function FN_GET_MUC_AN_PHAT_DAC_XA
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_MUC_AN_PHAT_DAC_XA" (
    p_tha_an_phat IN NVARCHAR2
)
RETURN NVARCHAR2
DETERMINISTIC
IS
    v_upper      NVARCHAR2(4000);
    v_nam        NUMBER;
    v_thang      NUMBER;
    v_ngay       NUMBER;
    v_so_nam     NUMBER;  -- S? n?m t??ng ???ng (n?m + tháng/12 + ngày/365)
BEGIN
    IF p_tha_an_phat IS NULL OR TRIM(p_tha_an_phat) IS NULL THEN
        RETURN NULL;
    END IF;

    v_upper := UPPER(NVL(p_tha_an_phat, ''));

    -- 1. Chung thân gi?m xu?ng tù có th?i h?n
    -- Có "chung thân" và "gi?m xu?ng" (có d?u ho?c không)
    IF (v_upper LIKE '%CHUNG THAN%' OR v_upper LIKE '%CHUNG THÂN%')
       AND (v_upper LIKE '%GIAM XUONG%' OR v_upper LIKE '%GI?M XU?NG%')
    THEN
        RETURN u'Chung th\00e2n gi\1ea3m xu\1ed1ng t\00f9 c\00f3 th\1eddi h\1ea1n';
    END IF;

    -- Chung thân thu?n (không gi?m xu?ng): không thu?c m?c án x?p lo?i c?i t?o
    IF (v_upper LIKE '%CHUNG THAN%' OR v_upper LIKE '%CHUNG THÂN%') THEN
        RETURN NULL;
    END IF;

    -- 2. Án tù có th?i h?n: parse s? n?m t? text
    v_nam  := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'NAM'), 0);
    v_thang := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'THANG'), 0);
    v_ngay  := NVL(QLPN.FN_PARSE_THOI_GIAN_TEXT(p_tha_an_phat, 'NGAY'), 0);

    -- Quy ??i sang s? n?m (n?m + tháng/12 + ngày/365) ?? so sánh ng??ng
    v_so_nam := v_nam + (v_thang / 12) + (v_ngay / 365);

    -- 3. Phân lo?i theo ng??ng (theo th? t? t? cao xu?ng th?p)
    IF v_so_nam > 20 AND v_so_nam <= 30 THEN
        RETURN u'\00c1n t\00f9 20 - 30 n\0103m';
    ELSIF v_so_nam > 15 AND v_so_nam <= 20 THEN
        RETURN u'\00c1n t\00f9 15 - 20 n\0103m';
    ELSIF v_so_nam > 10 AND v_so_nam <= 15 THEN
        RETURN u'\00c1n t\00f9 10 - 15 n\0103m';
    ELSIF v_so_nam > 8 AND v_so_nam <= 10 THEN
        RETURN u'\00c1n t\00f9 8 - 10 n\0103m';
    ELSIF v_so_nam > 5 AND v_so_nam <= 8 THEN
        RETURN u'\00c1n t\00f9 5 - 8 n\0103m';
    ELSIF v_so_nam > 3 AND v_so_nam <= 5 THEN
        RETURN u'\00c1n t\00f9 3 - 5 n\0103m';
    ELSIF v_so_nam <= 3 THEN
        RETURN u'\00c1n d\01b0\1edbi 3 n\0103m';
    ELSE
        -- > 30 n?m: không n?m trong danh sách, tr? v? m?c cao nh?t ?? có c?u hình
        RETURN u'\00c1n t\00f9 20 - 30 n\0103m';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN NULL;
END FN_GET_MUC_AN_PHAT_DAC_XA;




