/
--------------------------------------------------------
--  DDL for Function FN_GET_NGUONG_TGCH
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_NGUONG_TGCH" (
    p_pham_nhan_id IN NUMBER,
    p_ky_giam_id   IN NUMBER,
    p_is_dac_biet  IN NUMBER,
    p_an_phat      IN NVARCHAR2
)
RETURN NVARCHAR2  -- tr? v? text ng??ng ?? dùng v?i FN_PARSE_NGUONG
IS
    v_dieu_kien_id      NUMBER;
    v_tong_ngay_an      NUMBER;
    v_da_giam           NUMBER := 0;
    v_co_pham_toi_moi   NUMBER := 0;
    v_muc_do_nt         NVARCHAR2(100);  -- m?c ?? nghiêm tr?ng

    -- C?t ng??ng t? c?u hình
    v_nguong_tt         NVARCHAR2(100);
    v_nguong_db         NVARCHAR2(100);
    v_nguong_dgptm_it   NVARCHAR2(100);  -- ?ã gi?m + ph?m t?i m?i ít NT
    v_nguong_dgptm      NVARCHAR2(100);  -- ?ã gi?m + ph?m t?i m?i NT/RNT/?BN
    v_tgch_loai         NVARCHAR2(500);
BEGIN
    -- L?y ?i?u ki?n ID
    BEGIN
        SELECT dk.ID
          INTO v_dieu_kien_id
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS dk
         WHERE dk.GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
           AND dk.IS_DELETED = 0
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN RETURN NULL;
    END;

    v_tong_ngay_an := FN_PARSE_AN_PHAT_TO_NGAY(p_an_phat);

    -- Ki?m tra ?ã t?ng gi?m
    SELECT COUNT(*) INTO v_da_giam
      FROM GIAM_THOI_HANS
     WHERE PHAM_NHAN_ID = p_pham_nhan_id
       AND IS_DELETED = 0;

    -- Ki?m tra ph?m t?i m?i
	IF v_da_giam > 0 THEN
	    BEGIN
	        SELECT COUNT(*),
	               MAX(ptm.MUC_DO_NGHIEM_TRONG)
	          INTO v_co_pham_toi_moi, v_muc_do_nt
	          FROM PHAM_TOI_MOIS ptm
	         WHERE ptm.PHAM_NHAN_ID = p_pham_nhan_id
	           AND NVL(ptm.IS_DELETED, 0) = 0;

	        -- N?u có b?n ghi nh?ng MUC_DO_NGHIEM_TRONG toàn NULL ? coi nh? không có
	        IF v_muc_do_nt IS NULL THEN
	            v_co_pham_toi_moi := 0;
	        END IF;
	    EXCEPTION
	        WHEN NO_DATA_FOUND THEN
	            v_co_pham_toi_moi := 0;
	    END;
	END IF;

    -- L?y t?t c? c?t ng??ng t? c?u hình
    BEGIN
        SELECT
            TGCH_LOAI_DOI_TUONG,
            TGCH_TRUONG_HOP_DAC_BIET,
            TGCH_DOI_TUONG_THONG_THUONG,
            TGCH_DA_GIAM_PHAM_TOI_MOI_IT_NT,
            TGCH_DA_GIAM_PHAM_TOI_MOI
          INTO
            v_tgch_loai,
            v_nguong_db,
            v_nguong_tt,
            v_nguong_dgptm_it,
            v_nguong_dgptm
          FROM GTH_THOI_GIAN_CHAP_HANHS
         WHERE GTH_DIEU_KIEN_GIAM_THOI_HAN_ID = v_dieu_kien_id
           AND IS_DELETED = 0
           AND (   (TGCH_LOAI_DOI_TUONG LIKE '%th?i h?n%' AND v_tong_ngay_an >  0)
                OR (TGCH_LOAI_DOI_TUONG LIKE '%Chung th%'  AND v_tong_ngay_an = -1))
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN RETURN NULL;
    END; 

    -- ?? Xác ??nh ng??ng áp d?ng ??????????????????????????????
    -- ?u tiên: ph?m t?i m?i > ??c bi?t > thông th??ng
    IF v_da_giam > 0 AND v_co_pham_toi_moi > 0 THEN
        IF UPPER(NVL(v_muc_do_nt, '')) LIKE '%ÍT%'
        OR UPPER(NVL(v_muc_do_nt, '')) LIKE '%IT%'
        THEN
            -- Ít nghiêm tr?ng
            RETURN NVL(v_nguong_dgptm_it, v_nguong_tt);
        ELSE
            -- Nghiêm tr?ng / R?t nghiêm tr?ng / ??c bi?t nghiêm tr?ng
            RETURN NVL(v_nguong_dgptm, v_nguong_tt);
        END IF;
    ELSIF p_is_dac_biet = 1 THEN
        RETURN v_nguong_db;
    ELSE
        RETURN v_nguong_tt;
    END IF;

EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
END FN_GET_NGUONG_TGCH;






/
--------------------------------------------------------
--  DDL for Function FN_GET_QLPN_DASHBOARD
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_QLPN_DASHBOARD" (
    p_tu_ngay IN DATE DEFAULT NULL,
    p_den_ngay IN DATE DEFAULT NULL
) RETURN SYS_REFCURSOR
AS
    v_tu_ngay  DATE := TRUNC(NVL(p_tu_ngay, TRUNC(SYSDATE, 'MM')));
    v_den_ngay DATE := TRUNC(NVL(p_den_ngay, LAST_DAY(SYSDATE)));
    v_cursor   SYS_REFCURSOR;
BEGIN
    IF v_tu_ngay > v_den_ngay THEN
        RAISE_APPLICATION_ERROR(-20001, 'Tu ngay phai nho hon hoac bang den ngay');
    END IF;

    OPEN v_cursor FOR
        WITH THANG AS (SELECT v_tu_ngay  AS TU_NGAY,
                              v_den_ngay AS DEN_NGAY
                       FROM DUAL),
             TANG_1 AS (SELECT COUNT(*) AS V
                        FROM QLPN.PN_LAI_LICHS LL
                                 JOIN PN_THI_HANH_AN ptha ON LL.ID = ptha.THA_PNLAI_LICH_ID AND ptha.IS_DELETED = 0
                                 CROSS JOIN THANG
                        WHERE NVL(LL.IS_DELETED, 0) = 0
                          AND QLPN.FN_GET_TINH_TRANG_TAI_NGAY_XET(LL.ID, THANG.TU_NGAY - 1)
                            IN ('111', '112', '113', '114')),
             TANG_3 AS (SELECT COUNT(*) AS V
                        FROM QLPN.PHAM_NHAN_CHUYEN_TRAI CT
                                 JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = CT.PNCT_LAI_LICH_ID
                                 CROSS JOIN THANG
                        WHERE CAST(CT.PNCT_NGAY_CHUYEN AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                          AND NVL(CT.IS_DELETED, 0) = 0
                          AND NVL(LL.IS_DELETED, 0) = 0),
             TANG_4 AS (SELECT COUNT(*) AS V
                        FROM QLPN.TRON_TRAIS TT
                                 JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TT.PHAM_NHAN_ID
                                 CROSS JOIN THANG
                        WHERE CAST(TT.NGAY_BAT_LAI AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                          AND NVL(TT.IS_DELETED, 0) = 0
                          AND NVL(LL.IS_DELETED, 0) = 0),
             TANG_5 AS (SELECT COUNT(*) AS V
                        FROM QLPN.TAM_DINH_CHIS TDC
                                 JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TDC.PHAM_NHAN_ID
                                 CROSS JOIN THANG
                        WHERE CAST(TDC.NGAY_LAI AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                          AND TDC.LOAI_QUYET_DINH_ID = 1
                          AND NVL(TDC.IS_DELETED, 0) = 0
                          AND NVL(LL.IS_DELETED, 0) = 0),
             TANG_6 AS (SELECT COUNT(*) AS V
                        FROM QLPN.TRICH_XUATS TX
                                 JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TX.PHAM_NHAN_ID
                                 CROSS JOIN THANG
                        WHERE CAST(TX.TX_NGAY_TRA AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                          AND TX.TX_LOAI_LENH_ID = 1
                          AND NVL(TX.IS_DELETED, 0) = 0
                          AND NVL(LL.IS_DELETED, 0) = 0),
             TANG_7A AS (SELECT COUNT(*) AS V
                         FROM QLPN.HUY_ANS HA
                                  JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = HA.PHAM_NHAN_ID
                                  CROSS JOIN THANG
                         WHERE CAST(HA.NGAY_TRO_LAI AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                           AND NVL(HA.IS_DELETED, 0) = 0
                           AND NVL(LL.IS_DELETED, 0) = 0),
             TANG_7B AS (SELECT COUNT(*) AS V
                         FROM QLPN.THA_CO_DIEU_KIENS TCK
                                  JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TCK.PHAM_NHAN_ID
                                  CROSS JOIN THANG
                         WHERE CAST(TCK.NGAY_BAT_LAI AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                           AND NVL(TCK.IS_DELETED, 0) = 0
                           AND NVL(LL.IS_DELETED, 0) = 0),
             TANG_7C AS (SELECT COUNT(*) AS V
                         FROM QLPN.CHUA_BENH_BAT_BUOCS CB
                                  JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = CB.PHAM_NHAN_ID
                                  CROSS JOIN THANG
                         WHERE CAST(CB.NGAY_KET_THUC AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                           AND NVL(CB.IS_DELETED, 0) = 0
                           AND NVL(LL.IS_DELETED, 0) = 0),
             GIAM_9 AS (SELECT COUNT(*) AS V
                        FROM (SELECT PN_LAI_LICH_ID
                              FROM (SELECT DX.PNLAI_LICH_ID AS PN_LAI_LICH_ID
                                    FROM QLPN.PN_DAC_XAS DX
                                             JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = DX.PNLAI_LICH_ID
                                             CROSS JOIN THANG
                                    WHERE CAST(DX.DX_NGAY_THA AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                                      AND NVL(DX.IS_DELETED, 0) = 0
                                      AND NVL(LL.IS_DELETED, 0) = 0
                                    UNION
                                    SELECT GTH.PHAM_NHAN_ID
                                    FROM QLPN.GIAM_THOI_HANS GTH
                                             JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = GTH.PHAM_NHAN_ID
                                             CROSS JOIN THANG
                                    WHERE CAST(GTH.NGAY_THA_GIAM_HET_AN AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                                      AND NVL(GTH.IS_DELETED, 0) = 0
                                      AND NVL(LL.IS_DELETED, 0) = 0
                                    UNION
                                    SELECT TCK.PHAM_NHAN_ID
                                    FROM QLPN.THA_CO_DIEU_KIENS TCK
                                             JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TCK.PHAM_NHAN_ID
                                             CROSS JOIN THANG
                                    WHERE CAST(TCK.NGAY_THA AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                                      AND NVL(TCK.IS_DELETED, 0) = 0
                                      AND NVL(LL.IS_DELETED, 0) = 0)
                              MINUS
                              (SELECT MHP.PN_LAI_LICH_ID
                               FROM QLPN.MIEN_HINH_PHATS MHP
                                        JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = MHP.PN_LAI_LICH_ID
                                        CROSS JOIN THANG
                               WHERE CAST(MHP.MHP_NGAY_TU_DO AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                                 AND NVL(MHP.IS_DELETED, 0) = 0
                                 AND NVL(LL.IS_DELETED, 0) = 0
                               UNION
                               SELECT CB.PHAM_NHAN_ID
                               FROM QLPN.CHUA_BENH_BAT_BUOCS CB
                                        CROSS JOIN THANG
                               WHERE CB.NGAY_KET_THUC IS NULL
                                  OR CAST(CB.NGAY_KET_THUC AS DATE) > THANG.DEN_NGAY
                               UNION
                               SELECT TX.PHAM_NHAN_ID
                               FROM QLPN.TRICH_XUATS TX
                                        CROSS JOIN THANG
                               WHERE TX.TX_LOAI_LENH_ID = 1
                                 AND (TX.TX_NGAY_TRA IS NULL
                                   OR CAST(TX.TX_NGAY_TRA AS DATE) > THANG.DEN_NGAY)))),
             GIAM_10 AS (SELECT COUNT(*) AS V
                         FROM QLPN.TRON_TRAIS TT
                                  JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TT.PHAM_NHAN_ID
                                  CROSS JOIN THANG
                         WHERE CAST(TT.NGAY_TRON AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                           AND NVL(TT.IS_DELETED, 0) = 0
                           AND NVL(LL.IS_DELETED, 0) = 0),
             GIAM_11 AS (SELECT COUNT(*) AS V
                         FROM QLPN.PN_KET_THUC_CHETS KC
                                  JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = KC.KTC_PN_LAI_LICH_ID
                                  LEFT JOIN QLPN.DM_TRUONG_HOP_CHETS THC ON THC.ID = KC.KTC_DM_TRUONG_HOP_CHET_ID
                                  CROSS JOIN THANG
                         WHERE CAST(KC.KTC_NGAY_CHET AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                           AND NVL(THC.THC_MA, '10') NOT IN ('30', '40', '50')
                           AND NVL(KC.IS_DELETED, 0) = 0
                           AND NVL(LL.IS_DELETED, 0) = 0),
             GIAM_12 AS (SELECT COUNT(*) AS V
                         FROM QLPN.TRICH_XUATS TX
                                  JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TX.PHAM_NHAN_ID
                                  CROSS JOIN THANG
                         WHERE CAST(TX.TX_NGAY_TRICH_XUAT AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                           AND TX.TX_LOAI_LENH_ID = 1
                           AND NVL(TX.IS_DELETED, 0) = 0
                           AND NVL(LL.IS_DELETED, 0) = 0),
             GIAM_13 AS (SELECT COUNT(*) AS V
                         FROM QLPN.TAM_DINH_CHIS TDC
                                  JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = TDC.PHAM_NHAN_ID
                                  CROSS JOIN THANG
                         WHERE CAST(TDC.NGAY_TDC AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                           AND TDC.LOAI_QUYET_DINH_ID = 1
                           AND NVL(TDC.IS_DELETED, 0) = 0
                           AND NVL(LL.IS_DELETED, 0) = 0),
             GIAM_14 AS (SELECT COUNT(*) AS V
                         FROM QLPN.PHAM_NHAN_CHUYEN_TRAI CT
                                  JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = CT.PNCT_LAI_LICH_ID
                                  LEFT JOIN QLPN.DM_TRUONG_HOP_CHUYEN_TRAIS THCT
                                            ON THCT.ID = CT.PNCT_TRUONG_HOP_CHUYEN_ID
                                  CROSS JOIN THANG
                         WHERE CAST(CT.PNCT_NGAY_CHUYEN AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                           AND NVL(THCT.THCT_MA, '10') IN ('10', '20', '90')
                           AND NVL(CT.IS_DELETED, 0) = 0
                           AND NVL(LL.IS_DELETED, 0) = 0),
             GIAM_15A AS (SELECT COUNT(*) AS V
                          FROM QLPN.HUY_ANS HA
                                   JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = HA.PHAM_NHAN_ID
                                   CROSS JOIN THANG
                          WHERE CAST(HA.NGAY_TRA_TU_DO AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                            AND NVL(HA.IS_DELETED, 0) = 0
                            AND NVL(LL.IS_DELETED, 0) = 0
                            AND HA.PHAM_NHAN_ID NOT IN (SELECT TX.PHAM_NHAN_ID
                                                        FROM QLPN.TRICH_XUATS TX
                                                        WHERE TX.TX_LOAI_LENH_ID = 1
                                                          AND (TX.TX_NGAY_TRA IS NULL
                                                            OR CAST(TX.TX_NGAY_TRA AS DATE) > THANG.DEN_NGAY))),
             GIAM_15B AS (SELECT COUNT(*) AS V
                          FROM QLPN.HOAN_THI_HANH_ANS HTHA
                                   JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = HTHA.PHAM_NHAN_ID
                                   CROSS JOIN THANG
                          WHERE CAST(HTHA.NGAY_HOAN AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                            AND NVL(HTHA.IS_DELETED, 0) = 0
                            AND NVL(LL.IS_DELETED, 0) = 0),
             GIAM_15C AS (SELECT COUNT(*) AS V
                          FROM QLPN.MIEN_HINH_PHATS MHP
                                   JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = MHP.PN_LAI_LICH_ID
                                   CROSS JOIN THANG
                          WHERE CAST(MHP.MHP_NGAY_TU_DO AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                            AND NVL(MHP.IS_DELETED, 0) = 0
                            AND NVL(LL.IS_DELETED, 0) = 0),
             GIAM_15D AS (SELECT COUNT(*) AS V
                          FROM QLPN.CHUA_BENH_BAT_BUOCS CB
                                   JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = CB.PHAM_NHAN_ID
                                   CROSS JOIN THANG
                          WHERE CAST(CB.NGAY_BAT_DAU AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                            AND NVL(CB.IS_DELETED, 0) = 0
                            AND NVL(LL.IS_DELETED, 0) = 0),
             GIAM_15E AS (SELECT COUNT(*) AS V
                          FROM QLPN.PN_CHUYEN_GIAO CG
                                   JOIN QLPN.PN_LAI_LICHS LL ON LL.ID = CG.PNCG_LAI_LICH_ID
                                   LEFT JOIN QLPN.DM_QUOC_TICHS QT ON QT.ID = CG.PNCG_NUOC_CHUYEN_GIAO_ID
                                   CROSS JOIN THANG
                          WHERE CAST(CG.PNCG_NGAY_CHUYEN_GIAO AS DATE) BETWEEN THANG.TU_NGAY AND THANG.DEN_NGAY
                            AND NVL(QT.QT_MA, '000') <> '250'
                            AND NVL(CG.IS_DELETED, 0) = 0
                            AND NVL(LL.IS_DELETED, 0) = 0)
        SELECT TANG_1.V                                AS SO_PN_THANG_TRUOC_CHUYEN_SANG,
               TANG_3.V + TANG_4.V + TANG_5.V + TANG_6.V
                   + TANG_7A.V + TANG_7B.V + TANG_7C.V AS SO_TANG_TRONG_THANG,
               GIAM_9.V + GIAM_10.V + GIAM_11.V + GIAM_12.V + GIAM_13.V
                   + GIAM_14.V + GIAM_15A.V + GIAM_15B.V + GIAM_15C.V
                   + GIAM_15D.V + GIAM_15E.V           AS SO_GIAM_TRONG_THANG,
               TANG_1.V
                   + (TANG_3.V + TANG_4.V + TANG_5.V + TANG_6.V
                   + TANG_7A.V + TANG_7B.V + TANG_7C.V)
                   - (GIAM_9.V + GIAM_10.V + GIAM_11.V + GIAM_12.V + GIAM_13.V
                   + GIAM_14.V + GIAM_15A.V + GIAM_15B.V + GIAM_15C.V
                   + GIAM_15D.V + GIAM_15E.V)          AS DANG_CHAP_HANH_AN
        FROM TANG_1,
             TANG_3,
             TANG_4,
             TANG_5,
             TANG_6,
             TANG_7A,
             TANG_7B,
             TANG_7C,
             GIAM_9,
             GIAM_10,
             GIAM_11,
             GIAM_12,
             GIAM_13,
             GIAM_14,
             GIAM_15A,
             GIAM_15B,
             GIAM_15C,
             GIAM_15D,
             GIAM_15E;

    RETURN v_cursor;
END FN_GET_QLPN_DASHBOARD;




/
--------------------------------------------------------
--  DDL for Function FN_GET_QUY_XEP_LOAI_THOA_MAN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_QUY_XEP_LOAI_THOA_MAN" (
    p_pham_nhan_id  IN NUMBER,
    p_ngay_xet      IN DATE,
    p_so_quy_yc     IN NUMBER,
    p_loai          IN VARCHAR2
) RETURN NVARCHAR2
IS
    TYPE t_quy_rec IS RECORD (
        nam      NUMBER,
        quy      NUMBER,
        ten_xl   NVARCHAR2(255)
    );
    TYPE t_quy_tab IS TABLE OF t_quy_rec INDEX BY PLS_INTEGER;

    v_selected      t_quy_tab;
    v_sel_cnt       PLS_INTEGER := 0;

    v_nam_xet       NUMBER := EXTRACT(YEAR  FROM p_ngay_xet);
    v_quy_xet       NUMBER := CEIL(EXTRACT(MONTH FROM p_ngay_xet) / 3.0);

    v_result        NVARCHAR2(4000);

    FUNCTION quy_ten(p_quy IN NUMBER) RETURN NVARCHAR2 IS
    BEGIN
        RETURN CASE p_quy
            WHEN 1 THEN u'Quý I'
            WHEN 2 THEN u'Quý II'
            WHEN 3 THEN u'Quý III'
            WHEN 4 THEN u'Quý IV'
            ELSE        u'Quý ' || TO_CHAR(p_quy)
        END;
    END;

BEGIN
    IF NVL(p_so_quy_yc, 0) <= 0 THEN
        RETURN u'(Không có yêu c?u quý)';
    END IF;

    -- ----------------------------------------------------------------
    -- LIEN_TUC
    -- ----------------------------------------------------------------
    IF UPPER(p_loai) = 'LIEN_TUC' THEN
        DECLARE
            v_cur_nam   NUMBER := v_nam_xet;
            v_cur_quy   NUMBER := v_quy_xet - 1;
            v_xl_id     NUMBER;
            v_xl_ten    NVARCHAR2(255);
        BEGIN
            IF v_cur_quy = 0 THEN
                v_cur_nam := v_cur_nam - 1;
                v_cur_quy := 4;
            END IF;

            WHILE v_sel_cnt < p_so_quy_yc LOOP
                BEGIN
                    SELECT
                        CASE v_cur_quy
                            WHEN 1 THEN xl.XEP_LOAI_QUY_I
                            WHEN 2 THEN xl.XEP_LOAI_QUY_II
                            WHEN 3 THEN xl.XEP_LOAI_QUY_III
                            WHEN 4 THEN xl.XEP_LOAI_QUY_IV
                        END,
                        dm.XLCT_TEN
                      INTO v_xl_id, v_xl_ten
                      FROM QLPN.XEP_LOAIS xl
                      JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm
                        ON dm.ID = CASE v_cur_quy
                                       WHEN 1 THEN xl.XEP_LOAI_QUY_I
                                       WHEN 2 THEN xl.XEP_LOAI_QUY_II
                                       WHEN 3 THEN xl.XEP_LOAI_QUY_III
                                       WHEN 4 THEN xl.XEP_LOAI_QUY_IV
                                   END
                       AND dm.XLCT_MA IN ('110', '120')
                       AND NVL(dm.IS_DELETED, 0) = 0
                     WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id
                       AND xl.XEP_LOAI_NAM = v_cur_nam
                       AND NVL(xl.IS_DELETED, 0) = 0;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN EXIT;
                END;

                v_sel_cnt := v_sel_cnt + 1;
                v_selected(v_sel_cnt).nam    := v_cur_nam;
                v_selected(v_sel_cnt).quy    := v_cur_quy;
                v_selected(v_sel_cnt).ten_xl := v_xl_ten;

                IF v_cur_quy = 1 THEN
                    v_cur_nam := v_cur_nam - 1;
                    v_cur_quy := 4;
                ELSE
                    v_cur_quy := v_cur_quy - 1;
                END IF;
            END LOOP;
        END;

    -- ----------------------------------------------------------------
    -- KHONG_LIEN_TUC
    -- ----------------------------------------------------------------
    ELSE
        FOR rec IN (
            SELECT *
              FROM (
                SELECT nam, quy, dm.XLCT_TEN AS ten_xl
                  FROM (
                    SELECT xl.XEP_LOAI_NAM AS nam, 1 AS quy, xl.XEP_LOAI_QUY_I   AS xl_id FROM QLPN.XEP_LOAIS xl WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(xl.IS_DELETED, 0) = 0
                    UNION ALL
                    SELECT xl.XEP_LOAI_NAM,         2,        xl.XEP_LOAI_QUY_II  FROM QLPN.XEP_LOAIS xl WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(xl.IS_DELETED, 0) = 0
                    UNION ALL
                    SELECT xl.XEP_LOAI_NAM,         3,        xl.XEP_LOAI_QUY_III FROM QLPN.XEP_LOAIS xl WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(xl.IS_DELETED, 0) = 0
                    UNION ALL
                    SELECT xl.XEP_LOAI_NAM,         4,        xl.XEP_LOAI_QUY_IV  FROM QLPN.XEP_LOAIS xl WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(xl.IS_DELETED, 0) = 0
                  ) raw1
                  JOIN QLPN.DM_XEP_LOAI_CAI_TAOS dm
                    ON dm.ID = xl_id
                   AND dm.XLCT_MA IN ('110', '120')
                   AND NVL(dm.IS_DELETED, 0) = 0
                 WHERE (nam < v_nam_xet)
                    OR (nam = v_nam_xet AND quy < v_quy_xet)
                 ORDER BY nam DESC, quy DESC
              )
             WHERE ROWNUM <= p_so_quy_yc
        ) LOOP
            v_sel_cnt := v_sel_cnt + 1;
            v_selected(v_sel_cnt).nam    := rec.nam;
            v_selected(v_sel_cnt).quy    := rec.quy;
            v_selected(v_sel_cnt).ten_xl := rec.ten_xl;
        END LOOP;
    END IF;

    IF v_sel_cnt = 0 THEN
        RETURN u'(Không có quý Khá/T?t phù h?p)';
    END IF;

    -- Bubble sort ASC (nam t?ng ? quy t?ng)
    DECLARE
        v_tmp t_quy_rec;
    BEGIN
        FOR i IN 1 .. v_sel_cnt - 1 LOOP
            FOR j IN 1 .. v_sel_cnt - i LOOP
                IF v_selected(j).nam > v_selected(j+1).nam
                   OR (    v_selected(j).nam  = v_selected(j+1).nam
                       AND v_selected(j).quy  > v_selected(j+1).quy)
                THEN
                    v_tmp           := v_selected(j);
                    v_selected(j)   := v_selected(j+1);
                    v_selected(j+1) := v_tmp;
                END IF;
            END LOOP;
        END LOOP;
    END;

    -- ----------------------------------------------------------------
    -- Build chu?i: group theo n?m, các quý li?t kê ngang trong 1 dòng
    --
    -- Ví d?:
    --   N?m 2024: Quý III - Khá, Quý IV - T?t
    --   N?m 2025: Quý I - T?t, Quý II - Khá, Quý IV - T?t
    -- ----------------------------------------------------------------
    DECLARE
        v_cur_nam       NUMBER  := NULL;
        v_dong_nam      NVARCHAR2(2000) := u'';
        v_first_in_nam  BOOLEAN := TRUE;
    BEGIN
        v_result := u'';

        FOR i IN 1 .. v_sel_cnt LOOP

            IF v_selected(i).nam != NVL(v_cur_nam, -1) THEN
                -- G?p n?m m?i ? flush dòng n?m c? (n?u có)
                IF v_cur_nam IS NOT NULL THEN
                    v_result := v_result
                             || CASE WHEN LENGTH(v_result) > 0 THEN CHR(10) ELSE u'' END
                             || u'N?m ' || TO_CHAR(v_cur_nam) || u': '
                             || v_dong_nam;
                END IF;
                -- Reset cho n?m m?i
                v_cur_nam      := v_selected(i).nam;
                v_dong_nam     := u'';
                v_first_in_nam := TRUE;
            END IF;

            -- N?i quý vào dòng n?m hi?n t?i
            v_dong_nam := v_dong_nam
                       || CASE WHEN v_first_in_nam THEN u'' ELSE u', ' END
                       || quy_ten(v_selected(i).quy)
                       || u' - ' || v_selected(i).ten_xl;
            v_first_in_nam := FALSE;

        END LOOP;

        -- Flush dòng n?m cu?i còn l?i
        IF v_cur_nam IS NOT NULL THEN
            v_result := v_result
                     || CASE WHEN LENGTH(v_result) > 0 THEN CHR(10) ELSE u'' END
                     || u'N?m ' || TO_CHAR(v_cur_nam) || u': '
                     || v_dong_nam;
        END IF;
    END;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN u'L?i FN_GET_QUY_XEP_LOAI_THOA_MAN: ' || SQLERRM;
END FN_GET_QUY_XEP_LOAI_THOA_MAN;




/
--------------------------------------------------------
--  DDL for Function FN_GET_SO_DU_HPBS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_SO_DU_HPBS" (
    v_PHAM_NHAN_ID NUMBER
)
    RETURN NUMBER
    IS
    v_balance    NUMBER := 0;
BEGIN
    -- T?ng ti?n ?ã n?p
    SELECT NVL(SUM(hp.HPBS_TONG_TIEN_CON_LAI), 0)
    INTO v_balance
    FROM PN_HINH_PHAT_BO_SUNGS hp
    WHERE hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
      AND hp.IS_DELETED = 0;

    RETURN CASE
               WHEN v_balance < 0 THEN 0
               ELSE v_balance
        END;
END;





/
--------------------------------------------------------
--  DDL for Function FN_GET_TEN_CON_CAI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_TEN_CON_CAI" (
    P_PHAM_NHAN_ID NUMBER
) RETURN NVARCHAR2
IS
    V_TEN_CON NVARCHAR2(4000);
BEGIN

    SELECT LISTAGG(HO_TEN_CON, ', ') WITHIN GROUP (ORDER BY HO_TEN_CON)
    INTO V_TEN_CON
    FROM THAN_NHAN_CON_CAIS
    WHERE PHAM_NHAN_ID = P_PHAM_NHAN_ID
      AND IS_DELETED = 0;

    RETURN NVL(V_TEN_CON, 'Không có');

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 'Không có';
END;






/
--------------------------------------------------------
--  DDL for Function FN_GET_THONG_TIN_HPBS_PT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_THONG_TIN_HPBS_PT" (
    v_PHAM_NHAN_ID NUMBER
) RETURN VARCHAR2
IS
    c_fmt   CONSTANT VARCHAR2(200) := 'FM999G999G999G999G999G999G999G999G999';
    c_dots  CONSTANT VARCHAR2(50)  := u'kh\00f4ng';

    v_result VARCHAR2(4000);

    -- L?y t?ng / ?ã th?c hi?n / ch?a th?c hi?n theo mã HPBS (1 mã)
    PROCEDURE get_amounts(
        p_ma         IN  NUMBER,
        p_tong       OUT NUMBER,
        p_da         OUT NUMBER,
        p_chua       OUT NUMBER,
        p_co_du_lieu OUT BOOLEAN
    ) IS
        v_tong    NUMBER;
        v_con_lai NUMBER;
    BEGIN
        SELECT SUM(NVL(hp.HPBS_TONG_TIEN_PHAT, 0)),
               SUM(NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0))
          INTO v_tong, v_con_lai
          FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
          JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
            ON dm.ID = hp.HPBS_HINH_PHAT
           AND NVL(dm.IS_DELETED, 0) = 0
           AND dm.HPBS_MA = p_ma          -- << ??i tên c?t n?u khác
         WHERE hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
           AND NVL(hp.IS_DELETED, 0) = 0;

        IF v_tong IS NULL OR v_tong = 0 THEN
            p_co_du_lieu := FALSE;
            p_tong := 0; p_da := 0; p_chua := 0;
        ELSE
            p_co_du_lieu := TRUE;
            p_tong := v_tong;
            p_chua := NVL(v_con_lai, 0);
            p_da   := v_tong - p_chua;
        END IF;
    END get_amounts;

    -- Gi?ng get_amounts nh?ng nh?n DANH SÁCH nhi?u mã, c?ng d?n t?t c? l?i.
    PROCEDURE get_amounts_multi(
        p_ma_list    IN  SYS.ODCINUMBERLIST,
        p_tong       OUT NUMBER,
        p_da         OUT NUMBER,
        p_chua       OUT NUMBER,
        p_co_du_lieu OUT BOOLEAN
    ) IS
        v_tong    NUMBER;
        v_con_lai NUMBER;
    BEGIN
        SELECT SUM(NVL(hp.HPBS_TONG_TIEN_PHAT, 0)),
               SUM(NVL(hp.HPBS_TONG_TIEN_CON_LAI, 0))
          INTO v_tong, v_con_lai
          FROM QLPN.PN_HINH_PHAT_BO_SUNGS hp
          JOIN QLPN.DM_HINH_PHAT_BO_SUNGS dm
            ON dm.ID = hp.HPBS_HINH_PHAT
           AND NVL(dm.IS_DELETED, 0) = 0
           AND dm.HPBS_MA IN (SELECT COLUMN_VALUE FROM TABLE(p_ma_list))
         WHERE hp.HPBS_MA_PHAM_NHAN = v_PHAM_NHAN_ID
           AND NVL(hp.IS_DELETED, 0) = 0;

        IF v_tong IS NULL OR v_tong = 0 THEN
            p_co_du_lieu := FALSE;
            p_tong := 0; p_da := 0; p_chua := 0;
        ELSE
            p_co_du_lieu := TRUE;
            p_tong := v_tong;
            p_chua := NVL(v_con_lai, 0);
            p_da   := v_tong - p_chua;
        END IF;
    END get_amounts_multi;

    -- Ch? l?y t?ng ti?n theo mã (dùng cho Ngh?a v? dân s? khác / Truy thu)
    FUNCTION get_tong_only(p_ma NUMBER) RETURN VARCHAR2 IS
        v_tong NUMBER; v_da NUMBER; v_chua NUMBER; v_has BOOLEAN;
    BEGIN
        get_amounts(p_ma, v_tong, v_da, v_chua, v_has);
        IF v_has THEN
            RETURN TO_CHAR(v_tong, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''');
        ELSE
            RETURN c_dots;
        END IF;
    END get_tong_only;

    -- Dòng d?ng: <nhãn>: t?ng ??ng; ?ã th?c hi?n: ...; ch?a th?c hi?n: ...;
    FUNCTION build_line3(p_label VARCHAR2, p_ma NUMBER) RETURN VARCHAR2 IS
        v_tong NUMBER; v_da NUMBER; v_chua NUMBER; v_has BOOLEAN;
    BEGIN
        get_amounts(p_ma, v_tong, v_da, v_chua, v_has);
        IF v_has THEN
            RETURN p_label || ': '
                || TO_CHAR(v_tong, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') || ' ??ng; '
                || '?ã th?c hi?n: '
                || TO_CHAR(v_da, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') || ' ??ng; '
                || 'ch?a th?c hi?n: '
                || TO_CHAR(v_chua, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') || ' ??ng;';
        ELSE
            RETURN p_label || ': ' || c_dots || ' ??ng; '
                || '?ã th?c hi?n: ' || c_dots || ' ??ng; '
                || 'ch?a th?c hi?n: ' || c_dots || ' ??ng;';
        END IF;
    END build_line3;

    -- Gi?ng build_line3 nh?ng nh?n danh sách nhi?u mã (c?ng d?n).
    FUNCTION build_line3_multi(p_label VARCHAR2, p_ma_list SYS.ODCINUMBERLIST) RETURN VARCHAR2 IS
        v_tong NUMBER; v_da NUMBER; v_chua NUMBER; v_has BOOLEAN;
    BEGIN
        get_amounts_multi(p_ma_list, v_tong, v_da, v_chua, v_has);
        IF v_has THEN
            RETURN p_label || ': '
                || TO_CHAR(v_tong, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') || ' ??ng; '
                || '?ã th?c hi?n: '
                || TO_CHAR(v_da, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') || ' ??ng; '
                || 'ch?a th?c hi?n: '
                || TO_CHAR(v_chua, c_fmt, 'NLS_NUMERIC_CHARACTERS = '',.''') || ' ??ng;';
        ELSE
            RETURN p_label || ': ' || c_dots || ' ??ng; '
                || '?ã th?c hi?n: ' || c_dots || ' ??ng; '
                || 'ch?a th?c hi?n: ' || c_dots || ' ??ng;';
        END IF;
    END build_line3_multi;

    -- Dòng: Ngh?a v? dân s? khác (237) + Truy thu (212), ch? l?y t?ng ti?n m?i cái
    FUNCTION build_line_nvks_truythu(p_ma_nvks NUMBER, p_ma_truythu NUMBER) RETURN VARCHAR2 IS
    BEGIN
        RETURN 'Ngh?a v? dân s? khác: ' || get_tong_only(p_ma_nvks) || ' ??ng'
            || ': Truy thu: ' || get_tong_only(p_ma_truythu) || ' ??ng;';
    END build_line_nvks_truythu;

BEGIN
    v_result :=
           build_line3('Ph?t ti?n', 220)                         || CHR(10) ||
           build_line3('B?i th??ng thi?t h?i', 236)               || CHR(10) ||
           build_line3('Ngh?a v? tr? l?i tài s?n', 235)           || CHR(10) ||
           build_line_nvks_truythu(237, 212)                      || CHR(10) ||
           -- TODO: ?i?n thêm mã c?n g?p vào list bên d??i, vd SYS.ODCINUMBERLIST(250, 251, 252)
           build_line3_multi('Án phí hình s?', SYS.ODCINUMBERLIST(250, 251, 252)) || CHR(10) ||
           build_line3('Án phí dân s?', 260);

    RETURN v_result;
END FN_GET_THONG_TIN_HPBS_PT;

/
--------------------------------------------------------
--  DDL for Function FN_GET_TIEN_AN_TONG_HOP
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_TIEN_AN_TONG_HOP" (
    P_LAI_LICH_ID IN NUMBER
)
RETURN OBJ_TIEN_AN_TONG_HOP
IS
    L_OBJ OBJ_TIEN_AN_TONG_HOP;
BEGIN
    IF P_LAI_LICH_ID IS NULL THEN
        RETURN OBJ_TIEN_AN_TONG_HOP(0, NULL);
    END IF;

    SELECT OBJ_TIEN_AN_TONG_HOP(
        NVL(agg.cnt, 0),
        CASE
            WHEN NVL(agg.cnt, 0) = 0 THEN
                u'Kh\00f4ng'
            ELSE
                SUBSTR(
                    NVL(
                        TO_NCHAR(DBMS_LOB.SUBSTR(agg.detail_lines, 4000, 1)),
                        u''
                    ),
                    1,
                    4000
                )
        END
    )
    INTO L_OBJ
    FROM (
        SELECT
            COUNT(*) AS cnt,
            RTRIM(
                XMLAGG(
                    XMLELEMENT(e, formatted_item || CHR(10))
                    ORDER BY sort_key, pta_id
                ).EXTRACT('//text()').GETCLOBVAL(),
                CHR(10)
            ) AS detail_lines
        FROM (
            SELECT
                pta.ID AS pta_id,
                (
                    u'- N\0103m '
                    || NVL(TO_NCHAR(pta.PNTA_NAM_XU), u'Kh\00f4ng r\00f5')
                    || u' '
                    || NVL(CAST(dcq.CQ_TEN AS NVARCHAR2(2000)), u'Kh\00f4ng r\00f5')
                    || u' x\1eed '
                    || NVL(CAST(dmtg.MTG_TITLE AS NVARCHAR2(500)), u'Kh\00f4ng r\00f5')
                    || u' v\1ec1 t\1ed9i '
                    || NVL(
                        CAST(
                            LISTAGG(CAST(dtd.TD_TEN AS NVARCHAR2(500)), u'; ')
                                WITHIN GROUP (ORDER BY dtd.TD_TEN) AS NVARCHAR2(2000)
                        ),
                        u'Kh\00f4ng r\00f5 t\1ed9i danh'
                      )
                    || u'.'
                ) AS formatted_item,
                NVL(pta.PNTA_NAM_XU, 0) AS sort_key
            FROM PN_TIEN_AN pta
            LEFT JOIN QLPN.DM_MA_THOI_GIANS dmtg
                ON dmtg.ID = pta.PNTA_MUC_AN_ID
               AND NVL(dmtg.IS_DELETED, 0) = 0
            LEFT JOIN DM_CO_QUANS dcq
                ON pta.PNTA_TOA_XU_ID = dcq.ID
               AND NVL(dcq.IS_DELETED, 0) = 0
            LEFT JOIN (
                SELECT
                    src.pta_id,
                    TO_NUMBER(TRIM(REGEXP_SUBSTR(src.csv, '[^,]+', 1, LEVEL))) AS toi_danh_id
                FROM (
                    SELECT
                        p.ID AS pta_id,
                        REPLACE(REPLACE(TRIM(p.PNTA_TOI_DANH_ID), '[', ''), ']', '') AS csv
                    FROM PN_TIEN_AN p
                    WHERE p.PNTA_LAI_LICH_ID = P_LAI_LICH_ID
                      AND NVL(p.IS_DELETED, 0) = 0
                      AND p.PNTA_TOI_DANH_ID IS NOT NULL
                      AND TRIM(p.PNTA_TOI_DANH_ID) IS NOT NULL
                ) src
                WHERE src.csv IS NOT NULL
                  AND REGEXP_LIKE(TRIM(src.csv), '[0-9]')
                CONNECT BY LEVEL <= REGEXP_COUNT(src.csv, ',') + 1
                  AND PRIOR src.pta_id = src.pta_id
                  AND PRIOR SYS_GUID() IS NOT NULL
                  AND REGEXP_SUBSTR(src.csv, '[^,]+', 1, LEVEL) IS NOT NULL
                  AND REGEXP_LIKE(TRIM(REGEXP_SUBSTR(src.csv, '[^,]+', 1, LEVEL)), '^[0-9]+$')
            ) toi
                ON toi.pta_id = pta.ID
            LEFT JOIN DM_TOI_DANHS dtd
                ON dtd.ID = toi.toi_danh_id
               AND NVL(dtd.IS_DELETED, 0) = 0
            WHERE pta.PNTA_LAI_LICH_ID = P_LAI_LICH_ID
              AND NVL(pta.IS_DELETED, 0) = 0
            GROUP BY
                pta.ID,
                dcq.CQ_TEN,
                pta.PNTA_NAM_XU,
                dmtg.MTG_TITLE
        )
    ) agg;

    RETURN L_OBJ;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN OBJ_TIEN_AN_TONG_HOP(0, NULL);
    WHEN OTHERS THEN
        RETURN OBJ_TIEN_AN_TONG_HOP(0, NULL);
END FN_GET_TIEN_AN_TONG_HOP;


/
--------------------------------------------------------
--  DDL for Function FN_GET_TINH_TRANG_TAI_NGAY_XET
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_TINH_TRANG_TAI_NGAY_XET" (
    P_PN_LAI_LICH_ID NUMBER,
    P_NGAY_XET DATE DEFAULT SYSDATE
) RETURN VARCHAR2 DETERMINISTIC PARALLEL_ENABLE IS
    NUM_REC               NUMBER;
    V_NGAY_XET            TIMESTAMP;
    V_TINH_TRANG_TAI_NGAY VARCHAR2(10);
    NUM_REC2              NUMBER;
    V_NGAY_DEN_TRAI       DATE;
    V_NGAY_RA_TRAI        DATE;
BEGIN
    V_NGAY_XET := CAST(P_NGAY_XET + 1 AS TIMESTAMP);

	DBMS_OUTPUT.PUT_LINE(P_PN_LAI_LICH_ID);

    BEGIN
	    DBMS_OUTPUT.PUT_LINE('9999'); 

        SELECT 1
        INTO NUM_REC
        FROM DUAL
        WHERE EXISTS (SELECT 1
                      FROM PN_LAI_LICHS LL
                               JOIN DM_TINH_TRANG_PHAM_NHANS TTPN ON TTPN.ID = LL.LL_TINH_TRANG_ID
                      WHERE LL.ID = P_PN_LAI_LICH_ID
                        AND TTPN.TTPN_MA = '9999'
                        AND TTPN.IS_DELETED = 0
                        AND LL.IS_DELETED = 0);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NUM_REC := 0;
    END;
    IF NUM_REC > 0 THEN RETURN '9999'; END IF;

    DBMS_OUTPUT.PUT_LINE('182'); 

    SELECT THA.THA_NGAY_DEN_TRAI
    INTO V_NGAY_DEN_TRAI
    FROM PN_THI_HANH_AN THA
             JOIN PN_LAI_LICHS LL ON THA.THA_PNLAI_LICH_ID = LL.ID AND LL.IS_DELETED = 0
    WHERE THA.THA_PNLAI_LICH_ID = P_PN_LAI_LICH_ID
      AND THA.THA_NGAY_DEN_TRAI IS NOT NULL
      AND THA.IS_DELETED = 0;

    IF V_NGAY_DEN_TRAI IS NULL OR V_NGAY_DEN_TRAI >= V_NGAY_XET THEN
        RETURN '182';
    END IF;

    DBMS_OUTPUT.PUT_LINE('171');
    BEGIN
        SELECT 1
        INTO NUM_REC
        FROM DUAL
        WHERE EXISTS (SELECT 1
                      FROM PN_KET_THUC_CHETS KC
                               LEFT JOIN DM_TRUONG_HOP_CHETS THC ON THC.ID = KC.KTC_DM_TRUONG_HOP_CHET_ID
                      WHERE KC.KTC_PN_LAI_LICH_ID = P_PN_LAI_LICH_ID
                        AND KC.KTC_NGAY_CHET < V_NGAY_XET + 1
                        AND (THC.THC_MA NOT IN ('30', '40', '50') OR THC.THC_MA IS NULL)
                        AND KC.IS_DELETED = 0);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NUM_REC := 0;
    END;
    IF NUM_REC > 0 THEN RETURN '171'; END IF;


    DBMS_OUTPUT.PUT_LINE('153'); 
    BEGIN
        SELECT 1
        INTO NUM_REC
        FROM DUAL
        WHERE EXISTS (SELECT 1
                      FROM TAM_DINH_CHIS TDC
                               JOIN DM_TINH_TRANG_TAM_DINH_CHIES TT ON TT.ID = TDC.TINH_TRANG_ID
                      WHERE TDC.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                        AND TDC.LOAI_QUYET_DINH_ID = 1
                        AND TDC.NGAY_TDC < V_NGAY_XET + 1
                        AND NVL(TDC.NGAY_LAI, V_NGAY_XET + 1) >= V_NGAY_XET + 1
                        AND TT.TTTDC_MA = '30'
                        AND TDC.IS_DELETED = 0);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NUM_REC := 0;
    END;
    IF NUM_REC > 0 THEN RETURN '153'; END IF;


	DBMS_OUTPUT.PUT_LINE('144');    
	BEGIN
        SELECT 1
        INTO NUM_REC
        FROM DUAL
        WHERE EXISTS (SELECT 1
                      FROM TRICH_XUATS TX
                               JOIN DM_TINH_TRANG_TRICH_XUATS TT ON TT.ID = TX.TX_TINH_TRANG_ID
                      WHERE TX.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                        AND TX.TX_LOAI_LENH_ID = 1
                        AND TX.TX_NGAY_TRICH_XUAT < V_NGAY_XET + 1
                        AND NVL(TX.TX_NGAY_TRA, V_NGAY_XET + 1) >= V_NGAY_XET + 1
                        AND TT.TTTX_MA = '40'
                        AND TX.IS_DELETED = 0);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NUM_REC := 0;
    END;
    IF NUM_REC > 0 THEN RETURN '144'; END IF;

    DBMS_OUTPUT.PUT_LINE('132');    
    BEGIN
        SELECT 1
        INTO NUM_REC
        FROM DUAL
        WHERE EXISTS (SELECT 1
                      FROM TRON_TRAIS TT
                               JOIN DM_TINH_TRANG_TRONS DTT ON DTT.ID = TT.TINH_TRANG_ID
                      WHERE TT.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                        AND TT.NGAY_TRON < V_NGAY_XET + 1
                        AND NVL(TT.NGAY_BAT_LAI, V_NGAY_XET + 1) >= V_NGAY_XET + 1
                        AND DTT.TTT_MA = '20'
                        AND TT.IS_DELETED = 0);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NUM_REC := 0;
    END;
    IF NUM_REC > 0 THEN RETURN '132'; END IF;

    DBMS_OUTPUT.PUT_LINE('145');    
    BEGIN
        SELECT 1
        INTO NUM_REC
        FROM DUAL
        WHERE EXISTS (SELECT 1
                      FROM TRICH_XUATS TX
                               JOIN DM_TINH_TRANG_TRICH_XUATS TT ON TT.ID = TX.TX_TINH_TRANG_ID
                      WHERE TX.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                        AND TX.TX_LOAI_LENH_ID = 1
                        AND TX.TX_NGAY_TRICH_XUAT < V_NGAY_XET + 1
                        AND (NVL(TX.TX_NGAY_TRA, V_NGAY_XET + 1) >= V_NGAY_XET + 1)
                        AND TT.TTTX_MA = '50'
                        AND TX.IS_DELETED = 0);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NUM_REC := 0;
    END;
    IF NUM_REC > 0 THEN RETURN '145'; END IF;

    DBMS_OUTPUT.PUT_LINE('150');    
    BEGIN
        SELECT 1
        INTO NUM_REC
        FROM DUAL
        WHERE EXISTS (SELECT 1
                      FROM TRICH_XUATS TX
                               JOIN DM_TINH_TRANG_TRICH_XUATS TT ON TT.ID = TX.TX_TINH_TRANG_ID
                      WHERE TX.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                        AND TX.TX_LOAI_LENH_ID = 1
                        AND TX.TX_NGAY_TRICH_XUAT < V_NGAY_XET + 1
                        AND NVL(TX.TX_NGAY_TRA, V_NGAY_XET + 1) >= V_NGAY_XET + 1
                        AND TT.TTTX_MA = '97'
                        AND TX.IS_DELETED = 0);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NUM_REC := 0;
    END;
    IF NUM_REC > 0 THEN RETURN '150'; END IF;

    DBMS_OUTPUT.PUT_LINE('154');    
    BEGIN
        SELECT 1
        INTO NUM_REC
        FROM DUAL
        WHERE EXISTS (SELECT 1
                      FROM TAM_DINH_CHIS TDC
                               JOIN DM_TINH_TRANG_TAM_DINH_CHIES TT ON TT.ID = TDC.TINH_TRANG_ID
                      WHERE TDC.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                        AND TDC.LOAI_QUYET_DINH_ID = 1
