                      WHERE TDC.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                        AND TDC.LOAI_QUYET_DINH_ID = 1
                        AND TDC.NGAY_TDC < V_NGAY_XET
                        AND NVL(TDC.NGAY_LAI, V_NGAY_XET) > V_NGAY_XET
                        AND TT.TTTDC_MA = '98'
                        AND TDC.IS_DELETED = 0);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NUM_REC := 0;
    END;
    IF NUM_REC > 0 THEN RETURN '158'; END IF;

    BEGIN
        SELECT 1
        INTO NUM_REC
        FROM DUAL
        WHERE EXISTS (SELECT 1
                      FROM TAM_DINH_CHIS TDC
                      WHERE TDC.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                        AND TDC.LOAI_QUYET_DINH_ID = 1
                        AND TDC.NGAY_TDC < V_NGAY_XET
                        AND NVL(TDC.NGAY_LAI, V_NGAY_XET) >= P_NGAY_XET
