                                AND TT.TTTX_MA = '20'
                                AND TX.IS_DELETED = 0);
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NUM_REC2 := 0;
            END;
            IF NUM_REC2 > 0 THEN
                RETURN '142';
            ELSE
                RETURN '141';
            END IF;
        END IF;
    END IF;

    SELECT ptha.THA_NGAY_HET_HAN
    INTO V_NGAY_RA_TRAI
    FROM PN_THI_HANH_AN ptha
             JOIN PN_LAI_LICHS pll ON ptha.THA_PNLAI_LICH_ID = pll.ID AND PLL.IS_DELETED = 0
    WHERE ptha.IS_DELETED = 0
      AND ptha.THA_PNLAI_LICH_ID = P_PN_LAI_LICH_ID;

    IF V_NGAY_RA_TRAI IS NOT NULL AND V_NGAY_RA_TRAI < V_NGAY_XET THEN
        BEGIN
            SELECT 1
            INTO NUM_REC2
            FROM DUAL
            WHERE EXISTS (SELECT 1
