    BEGIN
        SELECT 1
        INTO NUM_REC
        FROM DUAL
        WHERE EXISTS (SELECT 1
                      FROM TRICH_XUATS TX
                      WHERE TX.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                        AND TX.TX_LOAI_LENH_ID = 1
                        AND TX.TX_NGAY_TRICH_XUAT < V_NGAY_XET
                        AND NVL(TX.TX_NGAY_TRA, V_NGAY_XET) >= V_NGAY_XET
                        AND TX.IS_DELETED = 0);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NUM_REC := 0;
    END;
    IF NUM_REC > 0 THEN
        SELECT MIN(D)
        INTO V_NGAY_RA_TRAI
        FROM (SELECT HA.NGAY_TRA_TU_DO AS D
              FROM HUY_ANS HA
              WHERE HA.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                AND HA.NGAY_TRA_TU_DO IS NOT NULL
                AND HA.IS_DELETED = 0
              UNION ALL
              SELECT MHP.MHP_NGAY_TU_DO
              FROM MIEN_HINH_PHATS MHP
              WHERE MHP.PN_LAI_LICH_ID = P_PN_LAI_LICH_ID
                AND MHP.MHP_NGAY_TU_DO IS NOT NULL
                AND MHP.IS_DELETED = 0
              UNION ALL
              SELECT GTH.NGAY_THA_GIAM_HET_AN
              FROM GIAM_THOI_HANS GTH
              WHERE GTH.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                AND GTH.NGAY_THA_GIAM_HET_AN IS NOT NULL
                AND GTH.IS_DELETED = 0
              UNION ALL
              SELECT DX.DX_NGAY_THA
              FROM PN_DAC_XAS DX
              WHERE DX.PNLAI_LICH_ID = P_PN_LAI_LICH_ID
                AND DX.DX_NGAY_THA IS NOT NULL
                AND DX.IS_DELETED = 0
              UNION ALL
              SELECT TCK.NGAY_THA
              FROM THA_CO_DIEU_KIENS TCK
              WHERE TCK.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                AND TCK.NGAY_THA IS NOT NULL
                AND TCK.IS_DELETED = 0
              UNION ALL
              SELECT CG.PNCG_NGAY_CHUYEN_GIAO
              FROM PN_CHUYEN_GIAO CG
              WHERE CG.PNCG_LAI_LICH_ID = P_PN_LAI_LICH_ID
                AND CG.PNCG_NGAY_CHUYEN_GIAO IS NOT NULL
                AND CG.IS_DELETED = 0
              UNION ALL
              SELECT KT.KTRT_NGAY_THA
              FROM PN_KET_THUC_RA_TRAIS KT
              WHERE KT.KTRT_PN_LAI_LICH_ID = P_PN_LAI_LICH_ID
                AND KT.KTRT_NGAY_THA IS NOT NULL
                AND KT.IS_DELETED = 0);

        IF V_NGAY_RA_TRAI IS NOT NULL AND V_NGAY_RA_TRAI < (V_NGAY_XET) THEN
            RETURN '146';
        ELSE
            BEGIN
                SELECT 1
                INTO NUM_REC2
                FROM DUAL
                WHERE EXISTS (SELECT 1
                              FROM TRICH_XUATS TX
                                       JOIN DM_TINH_TRANG_TRICH_XUATS TT ON TT.ID = TX.TX_TINH_TRANG_ID
                              WHERE TX.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                                AND TX.TX_LOAI_LENH_ID = 1
                                AND TX.TX_NGAY_TRICH_XUAT < V_NGAY_XET
                                AND NVL(TX.TX_NGAY_TRA, V_NGAY_XET) > V_NGAY_XET
                                AND TT.TTTX_MA = '20'
                                AND TX.IS_DELETED = 0);
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NUM_REC2 := 0;
            END;
            IF NUM_REC2 > 0 THEN
                RETURN '142';
            ELSE
                RETURN '141';
            END IF;
        END IF;
    END IF;

    SELECT ptha.THA_NGAY_HET_HAN
    INTO V_NGAY_RA_TRAI
    FROM PN_THI_HANH_AN ptha
             JOIN PN_LAI_LICHS pll ON ptha.THA_PNLAI_LICH_ID = pll.ID AND PLL.IS_DELETED = 0
    WHERE ptha.IS_DELETED = 0
      AND ptha.THA_PNLAI_LICH_ID = P_PN_LAI_LICH_ID;

    IF V_NGAY_RA_TRAI IS NOT NULL AND V_NGAY_RA_TRAI < V_NGAY_XET THEN
        BEGIN
            SELECT 1
            INTO NUM_REC2
            FROM DUAL
            WHERE EXISTS (SELECT 1
                          FROM CHUA_BENH_BAT_BUOCS CB
                          WHERE CB.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                            AND NVL(CB.NGAY_KET_THUC, V_NGAY_XET) >= V_NGAY_XET
                            AND CB.IS_DELETED = 0);
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                NUM_REC2 := 0;
        END;
        IF NUM_REC2 > 0 THEN RETURN '125'; END IF;
    END IF;

    IF V_NGAY_RA_TRAI IS NULL OR V_NGAY_RA_TRAI > P_NGAY_XET THEN
        BEGIN
            SELECT 1
            INTO NUM_REC2
            FROM DUAL
            WHERE EXISTS (SELECT 1
                          FROM PN_GIAM_RIENGS GR
                          WHERE GR.GR_PN_LAI_LICH_ID = P_PN_LAI_LICH_ID
                            AND NVL(GR.GR_NGAY_KETTHUC, V_NGAY_XET) >= V_NGAY_XET
                            AND GR.IS_DELETED = 0);
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                NUM_REC2 := 0;
        END;
        IF NUM_REC2 > 0 THEN RETURN '112'; END IF;

        BEGIN
            SELECT 1
            INTO NUM_REC2
            FROM DUAL
            WHERE EXISTS (SELECT 1
                          FROM CHUA_BENH_BAT_BUOCS CB
                          WHERE CB.PHAM_NHAN_ID = P_PN_LAI_LICH_ID
                            AND NVL(CB.NGAY_KET_THUC, V_NGAY_XET) >= V_NGAY_XET
                            AND CB.IS_DELETED = 0);
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                NUM_REC2 := 0;
        END;
        IF NUM_REC2 > 0 THEN RETURN '113'; END IF;

        RETURN '111';
    ELSE
        RETURN '121';
    END IF;
END FN_GET_TINH_TRANG_TAI_NGAY_XET_ALT;


/
--------------------------------------------------------
--  DDL for Function FN_GET_TOI_DANH
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_TOI_DANH" (p_pn_id IN NUMBER)
RETURN VARCHAR2
AS
    v_result VARCHAR2(4000);
BEGIN
    SELECT LISTAGG(dtd.TD_TEN, ', ') WITHIN GROUP (ORDER BY dtd.TD_TEN)
    INTO v_result
    FROM (
        SELECT TO_NUMBER(REGEXP_SUBSTR(
                REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
                '[^,]+', 1, LEVEL
               )) AS TOI_DANH_ID
        FROM PN_THI_HANH_AN ptha
        WHERE ptha.THA_PNLAI_LICH_ID = p_pn_id
          AND ptha.THA_TOI_DANH IS NOT NULL
        CONNECT BY REGEXP_SUBSTR(
                REPLACE(REPLACE(ptha.THA_TOI_DANH, '[', ''), ']', ''),
                '[^,]+', 1, LEVEL
               ) IS NOT NULL
            AND PRIOR THA_PNLAI_LICH_ID = THA_PNLAI_LICH_ID
            AND PRIOR SYS_GUID() IS NOT NULL
    ) t
    JOIN DM_TOI_DANHS dtd ON dtd.ID = t.TOI_DANH_ID;

    RETURN v_result;
EXCEPTION
    WHEN OTHERS THEN RETURN NULL;
END FN_GET_TOI_DANH;




/
--------------------------------------------------------
--  DDL for Function FN_GET_TONG_CON_LAI_TIEN_LAO_DONG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_TONG_CON_LAI_TIEN_LAO_DONG" (
    p_pham_nhan_id IN NUMBER
) RETURN NUMBER
IS
    v_tong_thu NUMBER := 0;
    v_tong_chi NUMBER := 0;
BEGIN
    SELECT NVL(SUM(NVL(TIEN_Q1, 0) + NVL(TIEN_Q2, 0) + NVL(TIEN_Q3, 0)
                   + NVL(TIEN_Q4, 0) + NVL(TIEN_KHAC, 0)), 0)
      INTO v_tong_thu
      FROM TIEN_LAO_DONG_SAN_XUATS
     WHERE PHAM_NHAN_ID = p_pham_nhan_id
       AND NVL(IS_DELETED, 0) = 0;

    SELECT NVL(SUM(NVL(SO_TIEN, 0)), 0)
      INTO v_tong_chi
      FROM TIEN_CHI_LAO_DONG_SAN_XUATS
     WHERE PHAM_NHAN_ID = p_pham_nhan_id
       AND NVL(IS_DELETED, 0) = 0;

    RETURN v_tong_thu - v_tong_chi;
END FN_GET_TONG_CON_LAI_TIEN_LAO_DONG;

/
--------------------------------------------------------
--  DDL for Function FN_GET_TONG_MIEN_HINH_PHAT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_TONG_MIEN_HINH_PHAT" (
    P_PHAM_NHAN_ID NUMBER
) RETURN NVARCHAR2
IS
    V_YEAR  NUMBER := 0;
    V_MONTH NUMBER := 0;
    V_DAY   NUMBER := 0;

    V_RESULT NVARCHAR2(200);
BEGIN

    SELECT 
        NVL(SUM(M.MHP_THM_YEAR),0),
        NVL(SUM(M.MHP_THM_MONTH),0),
        NVL(SUM(M.MHP_THM_DAY),0)
    INTO 
        V_YEAR,
        V_MONTH,
        V_DAY
    FROM MIEN_HINH_PHATS M
    JOIN PN_LAI_LICHS LL
        ON LL.ID = M.PN_LAI_LICH_ID
    WHERE LL.ID = P_PHAM_NHAN_ID
      AND M.IS_DELETED = 0;

    -- Quy ??i ngày -> tháng
    V_MONTH := V_MONTH + TRUNC(V_DAY / 30);
    V_DAY := MOD(V_DAY,30);

    -- Quy ??i tháng -> n?m
    V_YEAR := V_YEAR + TRUNC(V_MONTH / 12);
    V_MONTH := MOD(V_MONTH,12);

    V_RESULT := '';

    IF V_YEAR > 0 THEN
        V_RESULT := V_RESULT || V_YEAR || ' n?m ';
    END IF;

    IF V_MONTH > 0 THEN
        V_RESULT := V_RESULT || V_MONTH || ' tháng ';
    END IF;

    IF V_DAY > 0 THEN
        V_RESULT := V_RESULT || V_DAY || ' ngày';
    END IF;

    RETURN TRIM(V_RESULT);

END;






/
--------------------------------------------------------
--  DDL for Function FN_GET_TONG_SO_NGAY_TRON
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GET_TONG_SO_NGAY_TRON" (
    P_PHAM_NHAN_ID NUMBER
) RETURN NVARCHAR2
    IS
    V_SO_NGAY NUMBER := 0;
    V_NAM     NUMBER;
    V_THANG   NUMBER;
    V_NGAY    NUMBER;
BEGIN

    SELECT NVL(SUM(TRUNC(NGAY_BAT_LAI) - TRUNC(NGAY_TRON)), 0)
    INTO V_SO_NGAY
    FROM TRON_TRAIS
    WHERE PHAM_NHAN_ID = P_PHAM_NHAN_ID
      AND IS_DELETED = 0
      AND NGAY_TRON IS NOT NULL
      AND NGAY_BAT_LAI IS NOT NULL;

    IF V_SO_NGAY < 30 AND V_SO_NGAY > 0 THEN
        RETURN V_SO_NGAY || ' ngày';
    END IF;

    V_NAM := TRUNC(V_SO_NGAY / 365);
    V_THANG := TRUNC(MOD(V_SO_NGAY, 365) / 30);
    V_NGAY := MOD(MOD(V_SO_NGAY, 365), 30);


    RETURN CASE
               WHEN V_NAM <= 0 AND V_THANG <= 0 AND V_NGAY <= 0 THEN 'Không'
               ELSE
                   CASE
                       WHEN
                           V_NAM IS NOT NULL AND V_NAM != 0 THEN V_NAM || ' n?m '
                       END
                       ||
                   CASE
                       WHEN
                           V_THANG IS NOT NULL AND V_THANG != 0
                           THEN V_THANG || ' tháng '
                       END ||
                   CASE
                       WHEN V_NGAY IS NOT NULL AND V_NGAY != 0 THEN
                           V_NGAY || ' ngày'
                       END
        END;

END;





/
--------------------------------------------------------
--  DDL for Function FN_GHI_CHU_PHAM_NHAN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_GHI_CHU_PHAM_NHAN" (
    p_pn_id IN NUMBER
)
RETURN NVARCHAR2
DETERMINISTIC
IS
    v_result NVARCHAR2(2000) := u'';
    v_gcr_raw VARCHAR2(4000);
    v_cnt     NUMBER;
    v_i       NUMBER;
    v_ten     NVARCHAR2(500);
BEGIN
    IF p_pn_id IS NULL THEN
        RETURN u'';
    END IF;

    SELECT REPLACE(REPLACE(REPLACE(NVL(TRIM(ll.LL_GHI_CHU_RIENG), CHR(32)), CHR(32), ''), '[', ''), ']', '')
    INTO v_gcr_raw
    FROM PN_LAI_LICHS ll
    WHERE ll.ID = p_pn_id
      AND NVL(ll.IS_DELETED, 0) = 0
      AND ll.LL_GHI_CHU_RIENG IS NOT NULL
      AND REGEXP_COUNT(REPLACE(REPLACE(REPLACE(NVL(TRIM(ll.LL_GHI_CHU_RIENG), CHR(32)), CHR(32), ''), '[', ''), ']', ''), '[0-9]+') > 0;

    v_cnt := REGEXP_COUNT(v_gcr_raw, '[0-9]+');

    FOR v_i IN 1 .. v_cnt LOOP
        BEGIN
            SELECT g.GCR_TEN
            INTO v_ten
            FROM DM_GHI_CHU_RIENGS g
            WHERE g.ID = TO_NUMBER(REGEXP_SUBSTR(v_gcr_raw, '[0-9]+', 1, v_i))
              AND NVL(g.IS_DELETED, 0) = 0;
            v_result := v_result || CASE WHEN LENGTH(v_result) > 0 THEN u', ' ELSE u'' END || v_ten;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                NULL;
        END;
    END LOOP;

    RETURN SUBSTR(NVL(v_result, u''), 1, 2000);

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN u'';
    WHEN OTHERS THEN
        RETURN u'';
END FN_GHI_CHU_PHAM_NHAN;






/
--------------------------------------------------------
--  DDL for Function FN_IS_TRUONG_HOP_DAC_BIET
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_IS_TRUONG_HOP_DAC_BIET" (
    p_pham_nhan_id IN NUMBER,
    p_ky_giam_id   IN NUMBER
)
RETURN NUMBER
IS
    v_count             NUMBER := 0;
    v_count_phu_nu_con  NUMBER := 0;
    v_nam_sinh          NUMBER;
    v_gioi_tinh         NUMBER;

    -- Cache c?u hình 1 l?n
    v_dieu_kien_db      NVARCHAR2(2000);
    v_dieu_kien_clean   VARCHAR2(2000);

    -- Cache GCR t? ph?m nhân 1 l?n
    v_gcr_ids           NVARCHAR2(2000);

    -- Flags các mã ??c bi?t
    v_co_ma_9999        NUMBER := 0;
    v_co_ma_9997        NUMBER := 0;
    v_co_ma_2402        NUMBER := 0;

    -- Helper: check mã có trong chu?i không (nhanh h?n REGEXP)
    FUNCTION HAS_MA(p_str IN VARCHAR2, p_ma IN VARCHAR2) RETURN BOOLEAN IS
    BEGIN
        RETURN INSTR(',' || p_str || ',', ',' || p_ma || ',') > 0;
    END;

BEGIN
    -- ?? B??c 1: L?y c?u hình 1 l?n duy nh?t ?????????????????
    BEGIN
        SELECT REPLACE(REPLACE(REPLACE(
                   NVL(DKGTH_DIEU_KIEN_DAC_BIET, ''),
                   '[', ''), ']', ''), '"', '')
          INTO v_dieu_kien_clean
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS
         WHERE GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
           AND IS_DELETED = 0
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN RETURN 0;
    END;

    -- Không có c?u hình ? không ??c bi?t
    IF v_dieu_kien_clean IS NULL OR LENGTH(TRIM(v_dieu_kien_clean)) = 0 THEN
        RETURN 0;
    END IF;

    -- ?? B??c 2: L?y GCR IDs c?a ph?m nhân 1 l?n ?????????????
    BEGIN
        SELECT NVL(LL_GHI_CHU_RIENG, '')
          INTO v_gcr_ids
          FROM PN_LAI_LICHS
         WHERE ID = p_pham_nhan_id
           AND NVL(IS_DELETED, 0) = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN v_gcr_ids := '';
    END;

    -- ?? B??c 3: Check match GCR_MA v?i c?u hình ?????????????
    -- Dùng JOIN + INSTR thay vì CONNECT BY
    IF LENGTH(TRIM(v_gcr_ids)) > 0 THEN
        SELECT COUNT(*) INTO v_count
          FROM DM_GHI_CHU_RIENGS dm
         WHERE NVL(dm.IS_DELETED, 0) = 0
           -- GCR_ID có trong danh sách ph?m nhân
           AND INSTR(',' || REPLACE(REPLACE(v_gcr_ids, '[',''), ']','') || ',',
                     ',' || TO_CHAR(dm.ID) || ',') > 0
           -- GCR_MA có trong danh sách c?u hình
           AND INSTR(',' || v_dieu_kien_clean || ',',
                     ',' || dm.GCR_MA || ',') > 0;

        IF v_count > 0 THEN RETURN 1; END IF;
    END IF;

    -- ?? B??c 4: ?ánh d?u các mã ??c bi?t c?n check ??????????
    v_co_ma_9999 := CASE WHEN HAS_MA(v_dieu_kien_clean, '9999') THEN 1 ELSE 0 END;
    v_co_ma_9997 := CASE WHEN HAS_MA(v_dieu_kien_clean, '9997') THEN 1 ELSE 0 END;
    v_co_ma_2402 := CASE WHEN HAS_MA(v_dieu_kien_clean, '2402') THEN 1 ELSE 0 END;

    -- Không có mã nào c?n check ? tr? v? luôn
    IF v_co_ma_9999 = 0 AND v_co_ma_9997 = 0 AND v_co_ma_2402 = 0 THEN
        RETURN 0;
    END IF;

    -- ?? B??c 5: Check 9999 - D??i 18 tu?i ???????????????????
    IF v_co_ma_9999 = 1 THEN
        BEGIN
            SELECT TO_NUMBER(SUBSTR(TRIM(ll.LL_NGAY_SINH), -4))
              INTO v_nam_sinh
              FROM PN_LAI_LICHS ll
             WHERE ll.ID = p_pham_nhan_id
               AND NVL(ll.IS_DELETED, 0) = 0;

            IF (EXTRACT(YEAR FROM SYSDATE) - v_nam_sinh) < 18 THEN
                RETURN 1;
            END IF;
        EXCEPTION
            WHEN OTHERS THEN NULL;
        END;
    END IF;

    -- ?? B??c 6: Check 9997 - ?m ?au th??ng xuyên ????????????
    IF v_co_ma_9997 = 1 THEN
        BEGIN
            SELECT COUNT(*) INTO v_count
              FROM (
                  SELECT EXTRACT(YEAR FROM CAST(cbbb.NGAY_BAT_DAU AS DATE)) AS NAM
                    FROM CHUA_BENH_BAT_BUOCS cbbb
                   WHERE cbbb.PHAM_NHAN_ID = p_pham_nhan_id
                     AND NVL(cbbb.IS_DELETED, 0) = 0
                     AND cbbb.NGAY_BAT_DAU IS NOT NULL
                   GROUP BY EXTRACT(YEAR FROM CAST(cbbb.NGAY_BAT_DAU AS DATE))
                  HAVING COUNT(*) >= 2
              );

            IF v_count > 0 THEN RETURN 1; END IF;
        EXCEPTION
            WHEN OTHERS THEN NULL;
        END;
    END IF;

    -- ?? B??c 7: Check 2402 - Ph? n? có con d??i 36 tháng ????
    IF v_co_ma_2402 = 1 THEN
        BEGIN
            SELECT ll.LL_DM_GIOI_TINH_ID
              INTO v_gioi_tinh
              FROM PN_LAI_LICHS ll
             WHERE ll.ID = p_pham_nhan_id
               AND NVL(ll.IS_DELETED, 0) = 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_gioi_tinh := NULL;
        END;

        IF v_gioi_tinh = 23 THEN
            SELECT COUNT(*) INTO v_count_phu_nu_con
              FROM THAN_NHAN_CON_CAIS tncc
             WHERE tncc.PHAM_NHAN_ID = p_pham_nhan_id
               AND NVL(tncc.IS_DELETED, 0) = 0
               AND tncc.NGAY_SINH IS NOT NULL
               AND LENGTH(TRIM(tncc.NGAY_SINH)) >= 4
               AND (EXTRACT(YEAR FROM SYSDATE)
                    - TO_NUMBER(SUBSTR(TRIM(tncc.NGAY_SINH), -4))) * 12 <= 36;

            IF v_count_phu_nu_con > 0 THEN RETURN 1; END IF;
        END IF;
    END IF;

    RETURN 0;

EXCEPTION
    WHEN OTHERS THEN RETURN 0;
END FN_IS_TRUONG_HOP_DAC_BIET;





