/
--------------------------------------------------------
--  DDL for Function FN_KET_QUA_CAI_TAO_MOI_NHAT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_KET_QUA_CAI_TAO_MOI_NHAT" (
    p_pham_nhan_id IN NUMBER
) RETURN NVARCHAR2 IS
    v_result NVARCHAR2(4000);
BEGIN
    SELECT
        u'N\0103m '
        || x.xep_loai_nam 
        || u': '
        || nvl(d.xlct_ten, u'')
    INTO v_result
    FROM
        xep_loais            x
        LEFT JOIN dm_xep_loai_cai_taos d ON d.id = x.xep_loai_ca_nam
                                                 AND nvl(d.is_deleted, 0) = 0
    WHERE
            x.pham_nhan_id = p_pham_nhan_id
        AND nvl(x.is_deleted, 0) = 0
        AND x.xep_loai_ca_nam IS NOT NULL
    ORDER BY
        x.xep_loai_nam DESC
    FETCH FIRST 1 ROW ONLY;

    RETURN v_result;
EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;
    WHEN OTHERS THEN
        RETURN NULL;
END fn_ket_qua_cai_tao_moi_nhat;




