    END IF;

    BEGIN
        SELECT t.ID_TINH, t.MA_TINH_NEW
        INTO v_id_tinh, v_ma_new
        FROM (
            SELECT dttp.ID AS ID_TINH,
                   TRIM(mp.MA_TINH_NEW) AS MA_TINH_NEW,
                   ROW_NUMBER() OVER (ORDER BY dttp.ID NULLS LAST) AS rn
            FROM MAPPING_PROVINCE mp
            LEFT JOIN DM_TINH_THANH_PHO dttp
              ON TRIM(mp.MA_TINH_NEW) = TRIM(dttp.TTP_MA)
             AND NVL(dttp.IS_DELETED, 0) = 0
            WHERE TRIM(TO_CHAR(mp.MA_TINH_OLD)) = TRIM(p_ma_dia_phuong)
        ) t
        WHERE t.rn = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_id_tinh := NULL;
            v_ma_new := NULL;
    END;

    IF p_ten_xa_phuong_cu IS NOT NULL
       AND TRIM(p_ten_xa_phuong_cu) IS NOT NULL
       AND v_ma_new IS NOT NULL
    THEN
        SELECT MIN(dxp.ID)
        INTO v_id_xa
        FROM DM_XA_PHUONG dxp
        WHERE NVL(dxp.IS_DELETED, 0) = 0
          AND TRIM(dxp.XP_MA_TINH_THANH_PHO) = TRIM(v_ma_new)
          AND REGEXP_REPLACE(TRIM(p_ten_xa_phuong_cu), '^(Xã|Ph??ng)\s+', '', 1, 0, 'i')
              = REGEXP_REPLACE(TRIM(dxp.XP_TEN), '^(Xã|Ph??ng)\s+', '', 1, 0, 'i');
    ELSE
        v_id_xa := NULL;
    END IF;

    RETURN TYP_TINH_XA_IDS(v_id_tinh, v_id_xa);
END FN_MAP_MA_DP_TEN_XA_TO_IDS;






/
--------------------------------------------------------
--  DDL for Function FN_MUC_AN_PHAT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_MUC_AN_PHAT" (
    p_thoi_gian IN NVARCHAR2
) RETURN NVARCHAR2
IS
    v_so_nam   NUMBER;
    v_ket_qua  NVARCHAR2(500);
BEGIN
    -- Convert v? s? n?m
    v_so_nam := FN_AN_PHAT_TO_NAM(p_thoi_gian);

    SELECT ma_ten_chi_tieu
    INTO v_ket_qua
    FROM (
        SELECT 
            ma_ten_chi_tieu,
            TO_NUMBER(REGEXP_SUBSTR(ma_ten_chi_tieu, '\d+', 1, 1)) AS tu_nam,
            TO_NUMBER(REGEXP_SUBSTR(ma_ten_chi_tieu, '\d+', 1, 2)) AS den_nam
        FROM dm_muc_ans
        WHERE ma_trang_thai = 1
          AND is_deleted = 0
    )
    WHERE
        (
            -- Case: "Tù 3 n?m tr? xu?ng"
            (tu_nam IS NOT NULL AND den_nam IS NULL AND v_so_nam <= tu_nam)

            OR

            -- Case: "Trên 5 n?m - 10 n?m"
            (tu_nam IS NOT NULL AND den_nam IS NOT NULL 
                AND v_so_nam > tu_nam 
                AND v_so_nam <= den_nam)

            OR

            -- Case: "Chung thân"
            (tu_nam IS NULL AND den_nam IS NULL 
                AND LOWER(ma_ten_chi_tieu) LIKE '%chung thân%')
        )
      AND ROWNUM = 1;

    RETURN v_ket_qua;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN NULL;
    WHEN OTHERS THEN
        RETURN NULL;
END FN_MUC_AN_PHAT;





/
--------------------------------------------------------
--  DDL for Function FN_NORMALIZE_VN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_NORMALIZE_VN" (p_str VARCHAR2)
RETURN VARCHAR2 DETERMINISTIC
IS
BEGIN
    RETURN REGEXP_REPLACE(
        INITCAP(
            TRANSLATE(
                LOWER(p_str),
                'àá??ãâ???????????èé???ê?????ìí???òó??õô???????????ùú??????????ý????',
                'aaaaaaaaaaaaaaaaaeeeeeeeeeeeiiiiiooooooooooooooooouuuuuuuuuuuyyyyyd'
            )
        ),
        '[^a-zA-Z0-9]',
        ''
    );
END;




/
--------------------------------------------------------
--  DDL for Function FN_PARSE_AN_PHAT_TO_NGAY
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_PARSE_AN_PHAT_TO_NGAY" (
    p_an_phat IN NVARCHAR2
)
RETURN NUMBER
IS
    v_nam    NUMBER := 0;
    v_thang  NUMBER := 0;
    v_ngay   NUMBER := 0;
    v_lower  NVARCHAR2(1000);
BEGIN
    IF p_an_phat IS NULL THEN RETURN 0; END IF;

    v_lower := LOWER(p_an_phat);

    -- ? Chung thân gi?m xu?ng 30 n?m ? 30 * 365
    IF v_lower LIKE '%chung th%n%gi%m%30%' THEN
        RETURN 30 * 365;
    END IF;

    -- ? Chung thân gi?m xu?ng 20 n?m ? 20 * 365
    IF v_lower LIKE '%chung th%n%gi%m%20%' THEN
        RETURN 20 * 365;
    END IF;

    -- Chung thân / t? hình ? -1
    IF v_lower LIKE '%chung th%n%'
    OR v_lower LIKE '%t%h%nh%' THEN
        RETURN -1;
    END IF;

    -- Parse s? n?m
    BEGIN
        v_nam := TO_NUMBER(TRIM(REGEXP_SUBSTR(p_an_phat, '(\d+)\s*n[a?]m', 1, 1, 'i', 1)));
    EXCEPTION WHEN OTHERS THEN v_nam := 0; END;

    -- Parse s? tháng
    BEGIN
        v_thang := TO_NUMBER(TRIM(REGEXP_SUBSTR(p_an_phat, '(\d+)\s*th[aá]ng', 1, 1, 'i', 1)));
    EXCEPTION WHEN OTHERS THEN v_thang := 0; END;

    -- Parse s? ngày
    BEGIN
        v_ngay := TO_NUMBER(TRIM(REGEXP_SUBSTR(p_an_phat, '(\d+)\s*ng[aà]y', 1, 1, 'i', 1)));
    EXCEPTION WHEN OTHERS THEN v_ngay := 0; END;

    RETURN (NVL(v_nam, 0) * 365) + (NVL(v_thang, 0) * 30) + NVL(v_ngay, 0);

EXCEPTION
    WHEN OTHERS THEN RETURN 0;
END FN_PARSE_AN_PHAT_TO_NGAY;







/
--------------------------------------------------------
--  DDL for Function FN_PARSE_AN_PHAT_TO_YMD
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_PARSE_AN_PHAT_TO_YMD" (
    p_an_phat IN NVARCHAR2  -- '2 n?m 8 tháng', '1 n?m 6 tháng 15 ngày', ...
)
RETURN YMD_OBJ  -- object (nam NUMBER, thang NUMBER, ngay NUMBER)
IS
    v_nam   NUMBER := 0;
    v_thang NUMBER := 0;
    v_ngay  NUMBER := 0;
    v_text  NVARCHAR2(500);
    v_pos   NUMBER;
    v_num   NVARCHAR2(20);
	v_lower NVARCHAR2(1000);
BEGIN
    v_text := TRIM(p_an_phat);
    v_lower := LOWER(p_an_phat);

    -- ? Chung thân gi?m xu?ng 30 n?m
    IF v_lower LIKE '%chung th%n%gi%m%30%' THEN
        RETURN YMD_OBJ(30, 0, 0);
    END IF;

    -- ? Chung thân gi?m xu?ng 20 n?m
    IF v_lower LIKE '%chung th%n%gi%m%20%' THEN
        RETURN YMD_OBJ(20, 0, 0);
    END IF;

    -- Chung thân / t? hình ? tr? 0
    IF v_lower LIKE '%chung th%n%'
    OR v_lower LIKE '%t%h%nh%' THEN
        RETURN YMD_OBJ(0, 0, 0);
    END IF;

    -- Tách n?m
    v_pos := INSTR(v_text, TO_NCHAR('n?m'));
    IF v_pos > 0 THEN
        v_num   := TRIM(REGEXP_SUBSTR(SUBSTR(v_text, 1, v_pos - 1), '\d+', 1, 1, 'i', 0));
        v_nam   := NVL(TO_NUMBER(v_num), 0);
        v_text  := TRIM(SUBSTR(v_text, v_pos + LENGTH(TO_NCHAR('n?m'))));
    END IF;

    -- Tách tháng
    v_pos := INSTR(v_text, TO_NCHAR('tháng'));
    IF v_pos > 0 THEN
        v_num   := TRIM(REGEXP_SUBSTR(SUBSTR(v_text, 1, v_pos - 1), '\d+', 1, 1, 'i', 0));
        v_thang := NVL(TO_NUMBER(v_num), 0);
        v_text  := TRIM(SUBSTR(v_text, v_pos + LENGTH(TO_NCHAR('tháng'))));
    END IF;

    -- Tách ngày
    v_pos := INSTR(v_text, TO_NCHAR('ngày'));
    IF v_pos > 0 THEN
        v_num  := TRIM(REGEXP_SUBSTR(SUBSTR(v_text, 1, v_pos - 1), '\d+', 1, 1, 'i', 0));
        v_ngay := NVL(TO_NUMBER(v_num), 0);
    END IF;

    RETURN YMD_OBJ(v_nam, v_thang, v_ngay);
EXCEPTION
    WHEN OTHERS THEN RETURN YMD_OBJ(0, 0, 0);
END FN_PARSE_AN_PHAT_TO_YMD;







/
--------------------------------------------------------
--  DDL for Function FN_PARSE_LL_NGAY_SINH
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_PARSE_LL_NGAY_SINH" (p_val IN VARCHAR2)
    RETURN DATE
    DETERMINISTIC
IS
    v_trim VARCHAR2(100);
    v_d    NUMBER;
    v_m    NUMBER;
    v_y    NUMBER;
    v_p1   NUMBER;
    v_p2   NUMBER;
    v_last NUMBER;
BEGIN
    IF p_val IS NULL OR TRIM(p_val) IS NULL THEN
        RETURN NULL;
    END IF;
    v_trim := TRIM(p_val);

    IF REGEXP_LIKE(v_trim, '^\d{1,2}/\d{1,2}/\d{4}$') THEN
        v_p1 := INSTR(v_trim, '/');
        v_p2 := INSTR(v_trim, '/', 1, 2);
        v_d := TO_NUMBER(SUBSTR(v_trim, 1, v_p1 - 1));
        v_m := TO_NUMBER(SUBSTR(v_trim, v_p1 + 1, v_p2 - v_p1 - 1));
        v_y := TO_NUMBER(SUBSTR(v_trim, v_p2 + 1));
        IF v_m NOT BETWEEN 1 AND 12 THEN
            RETURN NULL;
        END IF;
        v_last := EXTRACT(DAY FROM LAST_DAY(TO_DATE('01/' || v_m || '/' || v_y, 'DD/MM/YYYY')));
        IF v_d NOT BETWEEN 1 AND v_last THEN
            RETURN NULL;
        END IF;
        RETURN TO_DATE(v_trim, 'DD/MM/YYYY');
    ELSIF REGEXP_LIKE(v_trim, '^\d{1,2}/\d{4}$') THEN
        v_p1 := INSTR(v_trim, '/');
        v_m := TO_NUMBER(SUBSTR(v_trim, 1, v_p1 - 1));
        v_y := TO_NUMBER(SUBSTR(v_trim, v_p1 + 1));
        IF v_m NOT BETWEEN 1 AND 12 THEN
            RETURN NULL;
        END IF;
        RETURN TO_DATE('01/' || v_trim, 'DD/MM/YYYY');
    ELSIF REGEXP_LIKE(v_trim, '^\d{4}$') THEN
        RETURN TO_DATE('01/01/' || v_trim, 'DD/MM/YYYY');
    END IF;
    RETURN NULL;
EXCEPTION
    WHEN OTHERS THEN
        RETURN NULL;
END FN_PARSE_LL_NGAY_SINH;




/
--------------------------------------------------------
--  DDL for Function FN_PARSE_NAM_SINH
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_PARSE_NAM_SINH" (p_ngay_sinh IN NVARCHAR2) RETURN NVARCHAR2 IS
  v_txt NVARCHAR2(100);
  v_yr  NUMBER;
BEGIN
  v_txt := TRIM(NVL(p_ngay_sinh, ''));
  IF v_txt IS NULL OR LENGTH(v_txt) = 0 THEN RETURN NULL; END IF;
  IF REGEXP_LIKE(v_txt, '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$') THEN
    BEGIN v_yr := EXTRACT(YEAR FROM TO_DATE(v_txt, 'DD/MM/YYYY')); RETURN TO_NCHAR(v_yr);
    EXCEPTION WHEN OTHERS THEN RETURN NULL; END;
  END IF;
  IF REGEXP_LIKE(v_txt, '^[0-9]{4}$') THEN RETURN v_txt; END IF;
  RETURN NULL;
END FN_PARSE_NAM_SINH;







/
--------------------------------------------------------
--  DDL for Function FN_PARSE_NGAY_SINH
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_PARSE_NGAY_SINH" (
    P_TEXT IN NVARCHAR2
) RETURN DATE DETERMINISTIC IS
    V_S VARCHAR2(50);
BEGIN
    IF P_TEXT IS NULL THEN RETURN NULL; END IF;
    V_S := TRIM(P_TEXT);
    IF V_S IS NULL OR LENGTH(V_S) = 0 THEN RETURN NULL; END IF;

    IF REGEXP_LIKE(V_S, '^\d{4}$') THEN
        RETURN TO_DATE('01/01/' || V_S, 'dd/mm/yyyy');
    END IF;

    IF REGEXP_LIKE(V_S, '^\d{1,2}/\d{4}$') THEN
        RETURN TO_DATE('01/' || V_S, 'dd/mm/yyyy');
    END IF;

    IF REGEXP_LIKE(V_S, '^\d{1,2}/\d{1,2}/\d{4}$') THEN
        RETURN TO_DATE(V_S, 'dd/mm/yyyy');
    END IF;

    IF REGEXP_LIKE(V_S, '^\d{4}-\d{2}-\d{2}') THEN
        RETURN TO_DATE(SUBSTR(V_S, 1, 10), 'yyyy-mm-dd');
    END IF;

    RETURN NULL;
EXCEPTION
    WHEN OTHERS THEN
        RETURN NULL;
END FN_PARSE_NGAY_SINH;




/
--------------------------------------------------------
--  DDL for Function FN_PARSE_NGUONG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_PARSE_NGUONG" (
    p_an_phat IN NVARCHAR2,  -- '2 n?m 8 tháng'
    p_nguong  IN NVARCHAR2   -- '1/3', '1/4', '10' (s? n?m)
)
RETURN YMD_OBJ
IS
    v_tu        NUMBER;
    v_mau       NUMBER;
    v_src       YMD_OBJ;
    -- T?ng tháng/ngày sau khi chia
    v_tong_thang    NUMBER;
    v_du_thang      NUMBER;
    v_tong_ngay     NUMBER;
    v_res_nam       NUMBER;
    v_res_thang     NUMBER;
    v_res_ngay      NUMBER;
BEGIN
    -- Tr??ng h?p s? nguyên (s? n?m c? ??nh)
    IF INSTR(p_nguong, '/') = 0 THEN
        RETURN YMD_OBJ(TO_NUMBER(TRIM(p_nguong)), 0, 0);
    END IF;

    v_tu  := TO_NUMBER(TRIM(SUBSTR(p_nguong, 1, INSTR(p_nguong, '/') - 1)));
    v_mau := TO_NUMBER(TRIM(SUBSTR(p_nguong, INSTR(p_nguong, '/') + 1)));

    -- Parse án ph?t thành YMD
    v_src := FN_PARSE_AN_PHAT_TO_YMD(p_an_phat);

    -- B??c 1: Chia n?m
    v_res_nam    := FLOOR(v_src.nam * v_tu / v_mau);
    v_du_thang   := MOD(v_src.nam * v_tu, v_mau) * 12  -- ph?n d? n?m ? tháng
                  + v_src.thang * v_tu;

    -- B??c 2: Chia tháng
    v_res_thang  := FLOOR(v_du_thang / v_mau);
    v_tong_ngay  := MOD(v_du_thang, v_mau) * 30        -- ph?n d? tháng ? ngày
                  + v_src.ngay * v_tu;

    -- B??c 3: Chia ngày, làm tròn LÊN
    v_res_ngay   := CEIL(v_tong_ngay / v_mau);

    -- Chu?n hóa: ngày >= 30 ? ??y lên tháng, tháng >= 12 ? ??y lên n?m
    v_res_thang  := v_res_thang + FLOOR(v_res_ngay / 30);
    v_res_ngay   := MOD(v_res_ngay, 30);
    v_res_nam    := v_res_nam + FLOOR(v_res_thang / 12);
    v_res_thang  := MOD(v_res_thang, 12);

    RETURN YMD_OBJ(v_res_nam, v_res_thang, v_res_ngay);
EXCEPTION
    WHEN OTHERS THEN RETURN YMD_OBJ(0, 0, 0);
END FN_PARSE_NGUONG;







/
--------------------------------------------------------
--  DDL for Function FN_PARSE_THOI_GIAN_TEXT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_PARSE_THOI_GIAN_TEXT" (
    p_TEXT IN NVARCHAR2,
    p_LOAI IN VARCHAR2  -- 'NAM', 'THANG', 'NGAY'
) RETURN NUMBER
IS
    v_RESULT NUMBER := 0;
    v_TEXT NVARCHAR2(500);
    v_POS NUMBER;
    v_NUM_STR VARCHAR2(10);
BEGIN
    IF p_TEXT IS NULL THEN
        RETURN 0;
    END IF;

    -- Chuy?n v? lowercase và lo?i b? kho?ng tr?ng th?a
    v_TEXT := LOWER(TRIM(p_TEXT));

    -- Tìm s? tr??c t? khóa
    IF p_LOAI = 'NAM' THEN
        -- Tìm "X n?m" ho?c "X nam"
        v_POS := REGEXP_INSTR(v_TEXT, '[0-9]+\s*(n?m|nam)', 1, 1);
        IF v_POS > 0 THEN
            v_NUM_STR := REGEXP_SUBSTR(v_TEXT, '[0-9]+', v_POS);
            v_RESULT := TO_NUMBER(v_NUM_STR);
        END IF;
    ELSIF p_LOAI = 'THANG' THEN
        -- Tìm "X tháng" ho?c "X thang"
        v_POS := REGEXP_INSTR(v_TEXT, '[0-9]+\s*(tháng|thang)', 1, 1);
        IF v_POS > 0 THEN
            v_NUM_STR := REGEXP_SUBSTR(v_TEXT, '[0-9]+', v_POS);
            v_RESULT := TO_NUMBER(v_NUM_STR);
        END IF;
    ELSIF p_LOAI = 'NGAY' THEN
        -- Tìm "X ngày" ho?c "X ngay"
        v_POS := REGEXP_INSTR(v_TEXT, '[0-9]+\s*(ngày|ngay)', 1, 1);
        IF v_POS > 0 THEN
            v_NUM_STR := REGEXP_SUBSTR(v_TEXT, '[0-9]+', v_POS);
            v_RESULT := TO_NUMBER(v_NUM_STR);
        END IF;
    END IF;

    RETURN v_RESULT;
EXCEPTION
    WHEN OTHERS THEN
        RETURN 0;
END FN_PARSE_THOI_GIAN_TEXT;







/
--------------------------------------------------------
--  DDL for Function FN_PHAN_LOAI_THOI_GIAN_CON_LAI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_PHAN_LOAI_THOI_GIAN_CON_LAI" (
    p_THOI_GIAN_CON_LAI IN NVARCHAR2
)
RETURN VARCHAR2
IS
    v_nam NUMBER := 0;
    v_thang NUMBER := 0;
    v_tong_thang NUMBER;
BEGIN
    -- Ki?m tra ?ã h?t h?n
    IF p_THOI_GIAN_CON_LAI = '?ã h?t h?n' OR p_THOI_GIAN_CON_LAI IS NULL THEN
        RETURN 'HET_HAN';
    END IF;

    -- Parse s? n?m
    BEGIN
        IF REGEXP_INSTR(p_THOI_GIAN_CON_LAI, 'n?m') > 0 THEN
            v_nam := TO_NUMBER(REGEXP_SUBSTR(p_THOI_GIAN_CON_LAI, '\d+', 1, 1));
        END IF;
    EXCEPTION
        WHEN OTHERS THEN v_nam := 0;
    END;

    -- Parse s? tháng
    BEGIN
        IF REGEXP_INSTR(p_THOI_GIAN_CON_LAI, 'tháng') > 0 THEN
            v_thang := TO_NUMBER(REGEXP_SUBSTR(p_THOI_GIAN_CON_LAI, '\d+', 1, 2));
        END IF;
    EXCEPTION
        WHEN OTHERS THEN v_thang := 0;
    END;

    -- Tính t?ng tháng
    v_tong_thang := (v_nam * 12) + v_thang;

    -- Phân lo?i
    IF v_tong_thang <= 36 THEN
        RETURN '3N_TRO_XUONG';
    ELSIF v_tong_thang > 36 AND v_tong_thang <= 60 THEN
        RETURN 'TREN_3N_DEN_5N';
    ELSIF v_tong_thang > 60 AND v_tong_thang <= 84 THEN
        RETURN 'TREN_5N_DEN_7N';
    ELSIF v_tong_thang > 84 AND v_tong_thang <= 120 THEN
        RETURN 'TREN_7N_DEN_10N';
    ELSE
        RETURN 'TREN_10N';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN 'KHONG_XAC_DINH';
END;







/
--------------------------------------------------------
--  DDL for Function FN_PN_ID_HIEU_LUC
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_PN_ID_HIEU_LUC" (
        p_trai_giam_id IN NUMBER,
        p_ngay IN DATE
    ) RETURN TY_PN_ID_LIST PIPELINED AS
    BEGIN
        IF p_ngay IS NULL THEN
            FOR rec IN (
                SELECT ID
                  FROM PN_LAI_LICHS
                 WHERE NVL(LL_LA_BAN_DONG_BANG, 0) = 0
                   AND NVL(IS_DELETED, 0) = 0
                   AND (p_trai_giam_id IS NULL OR LL_TRAI_GIAM_ID = p_trai_giam_id)
            ) LOOP
                PIPE ROW (rec.ID);
            END LOOP;
            RETURN;
        END IF;

        IF p_trai_giam_id IS NULL THEN
            FOR rec IN (
                SELECT PHAM_NHAN_SONG_ID AS ID
                  FROM PN_QUA_TRINH_TRAIS
                 WHERE NVL(IS_DELETED, 0) = 0
                   AND DEN_NGAY IS NULL
                   AND TRUNC(TU_NGAY) <= TRUNC(p_ngay)
                UNION
                SELECT ll.ID
                  FROM PN_LAI_LICHS ll
                 WHERE NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
                   AND NVL(ll.IS_DELETED, 0) = 0
                   AND NOT EXISTS (
                       SELECT 1
                         FROM PN_QUA_TRINH_TRAIS qt
                        WHERE qt.PHAM_NHAN_SONG_ID = ll.ID
                          AND NVL(qt.IS_DELETED, 0) = 0
                   )
                   AND (
                        EXISTS (
                            SELECT 1
                              FROM PN_THI_HANH_AN tha
                             WHERE tha.THA_PNLAI_LICH_ID = ll.ID
                               AND tha.THA_NGAY_DEN_TRAI IS NOT NULL
                               AND NVL(tha.IS_DELETED, 0) = 0
                               AND TRUNC(tha.THA_NGAY_DEN_TRAI) <= TRUNC(p_ngay)
                        )
                        OR (
                            NOT EXISTS (
                                SELECT 1
                                  FROM PN_THI_HANH_AN tha
                                 WHERE tha.THA_PNLAI_LICH_ID = ll.ID
                                   AND tha.THA_NGAY_DEN_TRAI IS NOT NULL
                                   AND NVL(tha.IS_DELETED, 0) = 0
                            )
                            AND TRUNC(ll.CREATION_TIME) <= TRUNC(p_ngay)
                        )
                   )
            ) LOOP
                PIPE ROW (rec.ID);
            END LOOP;

            FOR rec IN (
                SELECT qt.HO_SO_DONG_BANG_ID AS ID
                  FROM PN_QUA_TRINH_TRAIS qt
                 WHERE NVL(qt.IS_DELETED, 0) = 0
                   AND qt.DEN_NGAY IS NOT NULL
                   AND qt.HO_SO_DONG_BANG_ID IS NOT NULL
                   AND TRUNC(qt.TU_NGAY) <= TRUNC(p_ngay)
                   AND TRUNC(qt.DEN_NGAY) >= TRUNC(p_ngay)
                   AND NOT EXISTS (
                       SELECT 1
                         FROM PN_QUA_TRINH_TRAIS mo
                        WHERE mo.PHAM_NHAN_SONG_ID = qt.PHAM_NHAN_SONG_ID
                          AND NVL(mo.IS_DELETED, 0) = 0
                          AND mo.DEN_NGAY IS NULL
                          AND TRUNC(mo.TU_NGAY) <= TRUNC(p_ngay)
                   )
            ) LOOP
                PIPE ROW (rec.ID);
            END LOOP;
            RETURN;
        END IF;

        FOR rec IN (
            SELECT HO_SO_DONG_BANG_ID AS ID
              FROM PN_QUA_TRINH_TRAIS
             WHERE TRAI_GIAM_ID = p_trai_giam_id
               AND NVL(IS_DELETED, 0) = 0
               AND DEN_NGAY IS NOT NULL
               AND HO_SO_DONG_BANG_ID IS NOT NULL
               AND TRUNC(TU_NGAY) <= TRUNC(p_ngay)
               AND TRUNC(DEN_NGAY) >= TRUNC(p_ngay)
        ) LOOP
            PIPE ROW (rec.ID);
        END LOOP;

        FOR rec IN (
            SELECT PHAM_NHAN_SONG_ID AS ID
              FROM PN_QUA_TRINH_TRAIS
             WHERE TRAI_GIAM_ID = p_trai_giam_id
               AND NVL(IS_DELETED, 0) = 0
               AND DEN_NGAY IS NULL
               AND TRUNC(TU_NGAY) <= TRUNC(p_ngay)
        ) LOOP
            PIPE ROW (rec.ID);
        END LOOP;

        FOR rec IN (
            SELECT ll.ID
              FROM PN_LAI_LICHS ll
             WHERE NVL(ll.LL_LA_BAN_DONG_BANG, 0) = 0
               AND NVL(ll.IS_DELETED, 0) = 0
               AND ll.LL_TRAI_GIAM_ID = p_trai_giam_id
               AND NOT EXISTS (
                   SELECT 1
                     FROM PN_QUA_TRINH_TRAIS qt
                    WHERE qt.PHAM_NHAN_SONG_ID = ll.ID
                      AND NVL(qt.IS_DELETED, 0) = 0
               )
               AND (
                    EXISTS (
                        SELECT 1
                          FROM PN_THI_HANH_AN tha
                         WHERE tha.THA_PNLAI_LICH_ID = ll.ID
                           AND tha.THA_NGAY_DEN_TRAI IS NOT NULL
                           AND NVL(tha.IS_DELETED, 0) = 0
                           AND TRUNC(tha.THA_NGAY_DEN_TRAI) <= TRUNC(p_ngay)
                    )
                    OR (
                        NOT EXISTS (
                            SELECT 1
                              FROM PN_THI_HANH_AN tha
                             WHERE tha.THA_PNLAI_LICH_ID = ll.ID
                               AND tha.THA_NGAY_DEN_TRAI IS NOT NULL
                               AND NVL(tha.IS_DELETED, 0) = 0
                        )
                        AND TRUNC(ll.CREATION_TIME) <= TRUNC(p_ngay)
                    )
               )
        ) LOOP
            PIPE ROW (rec.ID);
        END LOOP;
        RETURN;
END;

/
--------------------------------------------------------
--  DDL for Function FN_PN_TANG_GIAM_TRONG_KY
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_PN_TANG_GIAM_TRONG_KY" (
    p_tu_ngay             IN DATE,
    p_ngay_xet_exclusive  IN DATE,
    p_ma_trai_giam        IN NVARCHAR2 DEFAULT NULL
) RETURN QLPN.TY_TANG_GIAM_TAB PIPELINED
AS
BEGIN
    FOR r IN (
        WITH
        THANG AS (
            SELECT p_tu_ngay AS TU_NGAY, p_ngay_xet_exclusive AS NGAY_XET_EXCLUSIVE FROM DUAL
        ),

        -- ================================================================
        -- T?NG sub-components
        -- ================================================================

        -- LDT_MA 20211/20212/110/120/20324 = "chuy?n ??n" t? NGOÀI h? th?ng tr?i C10 (tr?i t?m giam,
        -- nhà t?m gi?, ho?c tr?n thi hành án quay l?i) — s? ki?n này x?y ra t?i THA_NGAY_DEN_TRAI
        -- (ngày ??n tr?i HI?N T?I), không ph?i THA_NGAY_BAT (ngày b?t/b?t ??u ch?p hành án g?c,
        -- có th? l?ch hàng ch?c n?m — ki?m ch?ng trên d? li?u th?t: 40.574/40.578 b?n ghi 20211,
        -- 108/108 b?n ghi 20212 có THA_NGAY_BAT khác THA_NGAY_DEN_TRAI).
        TANG_2_IDS AS (
            SELECT RT.PHAM_NHAN_ID AS ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(RT.THA_NGAY_DEN_TRAI AS DATE) AS EVENT_DATE
              FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
              JOIN QLPN.DM_LOAI_DOI_TUONGS LDT ON LDT.ID = RT.THA_DOI_TUONG AND NVL(LDT.IS_DELETED, 0) = 0
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE RT.THA_NGAY_DEN_TRAI >= THANG.TU_NGAY AND RT.THA_NGAY_DEN_TRAI < THANG.NGAY_XET_EXCLUSIVE
               AND LDT.LDT_MA IN ('20211', '20212', '110', '120', '20324')
               AND NVL(RT.IS_DELETED, 0) = 0
               AND RT.THA_ID IS NOT NULL
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        -- LDT_MA 20221 = "Tr?i giam khác chuy?n ??n" — tách riêng kh?i TANG_2 vì ?ây là chuy?n
        -- ??n T? M?T TR?I GIAM KHÁC (kh? n?ng cao là chuy?n tr?i n?i b? C10 — ch? 99/685 (14,5%)
        -- trùng v?i b?n ghi PHAM_NHAN_CHUYEN_TRAI dùng cho GIAM_14 nên không lo?i tr? hoàn toàn,
        -- nh?ng v?n tr? kh?i dòng t?ng C10 ?? không th?i ph?ng "t?ng" c?a c? h? th?ng — xem
        -- TANG_2_3B_INTRA_C10_IDS ? SP tiêu th?).
        TANG_3_IDS AS (
            SELECT RT.PHAM_NHAN_ID AS ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(RT.THA_NGAY_DEN_TRAI AS DATE) AS EVENT_DATE
              FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
              JOIN QLPN.DM_LOAI_DOI_TUONGS LDT ON LDT.ID = RT.THA_DOI_TUONG AND NVL(LDT.IS_DELETED, 0) = 0
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE RT.THA_NGAY_DEN_TRAI >= THANG.TU_NGAY AND RT.THA_NGAY_DEN_TRAI < THANG.NGAY_XET_EXCLUSIVE
               AND LDT.LDT_MA = '20221'
               AND NVL(RT.IS_DELETED, 0) = 0
               AND RT.THA_ID IS NOT NULL
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        TANG_4_IDS AS (
            SELECT RT.PHAM_NHAN_ID AS ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(TT.NGAY_BAT_LAI AS DATE) AS EVENT_DATE
              FROM QLPN.TRON_TRAIS TT
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = TT.PHAM_NHAN_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE TT.NGAY_BAT_LAI >= THANG.TU_NGAY
               AND TT.NGAY_BAT_LAI < THANG.NGAY_XET_EXCLUSIVE
               AND CAST(TT.NGAY_BAT_LAI AS DATE) >= CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
               AND NVL(TT.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND RT.THA_ID IS NOT NULL
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        TANG_5_IDS AS (
            SELECT RT.PHAM_NHAN_ID AS ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(TDC.NGAY_LAI AS DATE) AS EVENT_DATE
              FROM QLPN.TAM_DINH_CHIS TDC
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = TDC.PHAM_NHAN_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE TDC.NGAY_LAI >= THANG.TU_NGAY
               AND TDC.NGAY_LAI < THANG.NGAY_XET_EXCLUSIVE
               AND CAST(TDC.NGAY_TDC AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
               AND TDC.LOAI_QUYET_DINH_ID = 1
               AND NVL(TDC.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND RT.THA_ID IS NOT NULL
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        -- C?p nh?t 2026-08-21: thêm ?i?u ki?n TX_NGAY_TRA >= TX_NGAY_TRICH_XUAT — TX_NGAY_TRA
        -- l?i nh?p li?u (vd n?m b? gõ nh?m, ??ng TR??C ngày trích xu?t) coi nh? CH?A TR? L?I
        -- (không phát sinh s? ki?n TANG_6), thay vì âm th?m t?o 1 s? ki?n "tr? v?" gi? vào m?t
        -- k? báo cáo tr??c c? ngày ?i trích xu?t th?t (?ã g?p: PN 11032, TRICH_XUATS.ID=237,
        -- TX_NGAY_TRICH_XUAT=2022-01-12 nh?ng TX_NGAY_TRA=2021-01-14 — sai l?ch 1 n?m).
        TANG_6_IDS AS (
            SELECT RT.PHAM_NHAN_ID AS ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(TX.TX_NGAY_TRA AS DATE) AS EVENT_DATE
              FROM QLPN.TRICH_XUATS TX
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = TX.PHAM_NHAN_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE TX.TX_NGAY_TRA >= THANG.TU_NGAY
               AND TX.TX_NGAY_TRA < THANG.NGAY_XET_EXCLUSIVE
               AND CAST(TX.TX_NGAY_TRA AS DATE) >= CAST(TX.TX_NGAY_TRICH_XUAT AS DATE)
               AND CAST(TX.TX_NGAY_TRICH_XUAT AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
               AND TX.TX_LOAI_LENH_ID = 1
               AND NVL(TX.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND RT.THA_ID IS NOT NULL
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        TANG_7A_IDS AS (
            SELECT RT.PHAM_NHAN_ID AS ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(HA.NGAY_TRO_LAI AS DATE) AS EVENT_DATE
              FROM QLPN.HUY_ANS HA
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = HA.PHAM_NHAN_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE HA.NGAY_TRO_LAI >= THANG.TU_NGAY
               AND HA.NGAY_TRO_LAI < THANG.NGAY_XET_EXCLUSIVE
               AND CAST(HA.NGAY_TRA_TU_DO AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
               AND NVL(HA.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND RT.THA_ID IS NOT NULL
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        TANG_7B_IDS AS (
            SELECT RT.PHAM_NHAN_ID AS ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(TCK.NGAY_BAT_LAI AS DATE) AS EVENT_DATE
              FROM QLPN.THA_CO_DIEU_KIENS TCK
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = TCK.PHAM_NHAN_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE TCK.NGAY_BAT_LAI >= THANG.TU_NGAY
               AND TCK.NGAY_BAT_LAI < THANG.NGAY_XET_EXCLUSIVE
               AND NVL(TCK.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        -- TANG_7C_IDS (k?t thúc b?t bu?c ch?a b?nh) C? Ý không ???c UNION vào k?t qu? tr? v? —
        -- xem comment ??u file. Gi? ??nh ngh?a CTE ?? không ph?i xoá h?n logic ?ã ki?m th?,
        -- phòng khi c?n tra c?u l?i, nh?ng không dùng.
        TANG_7C_IDS AS (
            SELECT RT.PHAM_NHAN_ID AS ID, TG.TG_MA AS MA_TRAI_GIAM
              FROM QLPN.CHUA_BENH_BAT_BUOCS CB
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = CB.PHAM_NHAN_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE CB.NGAY_KET_THUC >= THANG.TU_NGAY
               AND CB.NGAY_KET_THUC < THANG.NGAY_XET_EXCLUSIVE
               AND NVL(CB.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        -- Tr?i NGU?N th?t (thu?c C10) cho các s? ki?n TANG_3 — dùng PN_THI_HANH_AN.THA_CHUYEN_DEN_TU_ID
        -- ("chuy?n ??n t? [tr?i nào]") l?c qua DM_TRAI_GIAMS.TG_MA_DD_DT IS NOT NULL ?? lo?i các
        -- "tr?i" không th?t (tr?i t?m giam t?nh khác... b? l?u chung DM_TRAI_GIAMS nh?ng không có
        -- mã ??nh danh ?i?n t? — vd 90680/95360/98409, xác nh?n qua ??i soát 2026-08-20). Cùng
        -- ?i?u ki?n ngày/LDT_MA v?i TANG_3_IDS vì là 2 m?t c?a CÙNG m?t s? ki?n chuy?n tr?i n?i b?.
        -- Ch? ~47% (321/685) s? ki?n TANG_3 xác ??nh ???c tr?i ngu?n (do THA_CHUYEN_DEN_TU_ID b? b?
        -- tr?ng ? ph?n còn l?i) — ph?n không xác ??nh ???c v?n x? lý nh? c? (t?ng-only ? ?ích, tr?
        -- qua TANG_2_3B_INTRA_C10_IDS ? SP tiêu th?, xem TANG_2_3B_INTRA_C10_IDS ? ?ó).
        GIAM_17_NOI_BO_IDS AS (
            SELECT RT.PHAM_NHAN_ID AS ID, TG_NGUON.TG_MA AS MA_TRAI_GIAM,
                   CAST(RT.THA_NGAY_DEN_TRAI AS DATE) AS EVENT_DATE
              FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
              JOIN QLPN.DM_LOAI_DOI_TUONGS LDT ON LDT.ID = RT.THA_DOI_TUONG AND NVL(LDT.IS_DELETED, 0) = 0
              JOIN QLPN.DM_TRAI_GIAMS TG_NGUON ON TG_NGUON.ID = RT.THA_CHUYEN_DEN_TU_ID
                                               AND NVL(TG_NGUON.IS_DELETED, 0) = 0
                                               AND TG_NGUON.TG_MA_DD_DT IS NOT NULL
             CROSS JOIN THANG
             WHERE RT.THA_NGAY_DEN_TRAI >= THANG.TU_NGAY AND RT.THA_NGAY_DEN_TRAI < THANG.NGAY_XET_EXCLUSIVE
               AND LDT.LDT_MA = '20221'
               AND NVL(RT.IS_DELETED, 0) = 0
               AND RT.THA_ID IS NOT NULL
               AND (p_ma_trai_giam IS NULL OR TG_NGUON.TG_MA = p_ma_trai_giam)
        ),

        -- ================================================================
        -- GI?M sub-components
        -- ================================================================

        GIAM_10_IDS AS (
            SELECT TT.PHAM_NHAN_ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(TT.NGAY_TRON AS DATE) AS EVENT_DATE
              FROM QLPN.TRON_TRAIS TT
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = TT.PHAM_NHAN_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE TT.NGAY_TRON >= THANG.TU_NGAY
               AND TT.NGAY_TRON < THANG.NGAY_XET_EXCLUSIVE
               AND CAST(TT.NGAY_TRON AS DATE) >= CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
               AND NVL(TT.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND RT.THA_ID IS NOT NULL
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        GIAM_11_IDS AS (
            SELECT KC.KTC_PN_LAI_LICH_ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(KC.KTC_NGAY_CHET AS DATE) AS EVENT_DATE
              FROM QLPN.PN_KET_THUC_CHETS KC
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = KC.KTC_PN_LAI_LICH_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
              LEFT JOIN QLPN.DM_TRUONG_HOP_CHETS THC ON THC.ID = KC.KTC_DM_TRUONG_HOP_CHET_ID
             CROSS JOIN THANG
             WHERE KC.KTC_NGAY_CHET >= THANG.TU_NGAY
               AND KC.KTC_NGAY_CHET < THANG.NGAY_XET_EXCLUSIVE
               AND CAST(KC.KTC_NGAY_CHET AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
               AND NVL(THC.THC_MA, '10') NOT IN ('30', '40', '50')
               AND NVL(KC.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND RT.THA_ID IS NOT NULL
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        GIAM_12_IDS AS (
            SELECT TX.PHAM_NHAN_ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(TX.TX_NGAY_TRICH_XUAT AS DATE) AS EVENT_DATE
              FROM QLPN.TRICH_XUATS TX
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = TX.PHAM_NHAN_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE TX.TX_NGAY_TRICH_XUAT >= THANG.TU_NGAY
               AND TX.TX_NGAY_TRICH_XUAT < THANG.NGAY_XET_EXCLUSIVE
               AND TX.TX_LOAI_LENH_ID = 1
               AND NVL(TX.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        GIAM_13_IDS AS (
            SELECT TDC.PHAM_NHAN_ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(TDC.NGAY_TDC AS DATE) AS EVENT_DATE
              FROM QLPN.TAM_DINH_CHIS TDC
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = TDC.PHAM_NHAN_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE TDC.NGAY_TDC >= THANG.TU_NGAY
               AND TDC.NGAY_TDC < THANG.NGAY_XET_EXCLUSIVE
               AND CAST(TDC.NGAY_TDC AS DATE) > CAST(RT.THA_NGAY_DEN_TRAI AS DATE)
               AND TDC.LOAI_QUYET_DINH_ID = 1
               AND NVL(TDC.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND RT.THA_ID IS NOT NULL
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        -- Chuy?n tr?i n?i b? C10 (PHAM_NHAN_CHUYEN_TRAI) KHÔNG ???c ??a vào GIAM:
        -- RT.LL_TRAI_GIAM_ID là tr?i HI?N T?I (?ích), không ph?i tr?i t?i th?i ?i?m chuy?n,
        -- và ??U_K? (T1)/DANG_CHAP_HANH_AN (DCHA) c?ng gán PN theo tr?i hi?n t?i nh? v?y.
        -- Vì c? T1 và DCHA ??u "vô hình hoá" vi?c chuy?n tr?i n?i b?, coi nó là GIAM ? ?ây s?
        -- phá v? ??ng th?c T1 + TANG - GIAM = DCHA (tr? nh?m ? ?úng tr?i ?ang ch?a PN ?ó).
        -- Xem README.md m?c "L?u ý nghi?p v? — GIAM_14 (chuy?n tr?i)".

        GIAM_15A_IDS AS (
            SELECT HA.PHAM_NHAN_ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(HA.NGAY_TRA_TU_DO AS DATE) AS EVENT_DATE
              FROM QLPN.HUY_ANS HA
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = HA.PHAM_NHAN_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE HA.NGAY_TRA_TU_DO >= THANG.TU_NGAY
               AND HA.NGAY_TRA_TU_DO < THANG.NGAY_XET_EXCLUSIVE
               AND NVL(HA.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
               AND HA.PHAM_NHAN_ID NOT IN (
                   SELECT TX.PHAM_NHAN_ID
                     FROM QLPN.TRICH_XUATS TX
                    WHERE TX.TX_LOAI_LENH_ID = 1
                      AND (TX.TX_NGAY_TRA IS NULL
                           OR TX.TX_NGAY_TRA >= THANG.NGAY_XET_EXCLUSIVE))
        ),

        GIAM_15B_IDS AS (
            SELECT HTHA.PHAM_NHAN_ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(HTHA.NGAY_HOAN AS DATE) AS EVENT_DATE
              FROM QLPN.HOAN_THI_HANH_ANS HTHA
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = HTHA.PHAM_NHAN_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE HTHA.NGAY_HOAN >= THANG.TU_NGAY
               AND HTHA.NGAY_HOAN < THANG.NGAY_XET_EXCLUSIVE
               AND NVL(HTHA.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        GIAM_15C_IDS AS (
            SELECT MHP.PN_LAI_LICH_ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(MHP.MHP_NGAY_TU_DO AS DATE) AS EVENT_DATE
              FROM QLPN.MIEN_HINH_PHATS MHP
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = MHP.PN_LAI_LICH_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE MHP.MHP_NGAY_TU_DO >= THANG.TU_NGAY
               AND MHP.MHP_NGAY_TU_DO < THANG.NGAY_XET_EXCLUSIVE
               AND NVL(MHP.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        -- GIAM_15D_IDS (b?t ??u b?t bu?c ch?a b?nh) C? Ý không ???c UNION vào k?t qu? tr? v? —
        -- xem comment ??u file. Gi? ??nh ngh?a CTE ?? không ph?i xoá h?n logic ?ã ki?m th?,
        -- phòng khi c?n tra c?u l?i, nh?ng không dùng.
        GIAM_15D_IDS AS (
            SELECT CB.PHAM_NHAN_ID, TG.TG_MA AS MA_TRAI_GIAM
              FROM QLPN.CHUA_BENH_BAT_BUOCS CB
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = CB.PHAM_NHAN_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE CB.NGAY_BAT_DAU >= THANG.TU_NGAY
               AND CB.NGAY_BAT_DAU < THANG.NGAY_XET_EXCLUSIVE
               AND NVL(CB.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        GIAM_15E_IDS AS (
            SELECT CG.PNCG_LAI_LICH_ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(CG.PNCG_NGAY_CHUYEN_GIAO AS DATE) AS EVENT_DATE
              FROM QLPN.PN_CHUYEN_GIAO CG
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = CG.PNCG_LAI_LICH_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
              LEFT JOIN QLPN.DM_QUOC_TICHS QT ON QT.ID = CG.PNCG_NUOC_CHUYEN_GIAO_ID
             CROSS JOIN THANG
             WHERE CG.PNCG_NGAY_CHUYEN_GIAO >= THANG.TU_NGAY
               AND CG.PNCG_NGAY_CHUYEN_GIAO < THANG.NGAY_XET_EXCLUSIVE
               AND NVL(QT.QT_MA, '000') <> '250'
               AND NVL(CG.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        -- Ra tr?i (không rõ lý do c? th?): dùng THA_NGAY_HET_HAN (b?n án m?i nh?t, ?ã có s?n
        -- trên RT) thay vì PN_KET_THUC_RA_TRAIS — ??ng b? v?i SP_CALC_TINH_TRANG_PHAM_NHAN.
        -- het_han_calc và SP_REFRESH_PN_TINH_TRANG_NGAY_CACHE.rel, ?? "gi?m" kh?p ?úng th?i
        -- ?i?m DCHA th?c s? gi?m thay vì ph? thu?c PN_KET_THUC_RA_TRAIS có ???c l?p k?p hay
        -- không. KHÔNG lo?i tr? theo giam riêng: PN ?ang giam riêng nh?ng THA_NGAY_HET_HAN ?ã
        -- qua v?n ???c coi là "?ã ch?p hành xong án ph?t tù" — giam riêng không kéo dài th?i
        -- h?n án ph?t tù.
        -- ??i tên _IDS -> _RAW_IDS 2026-08-21: guard (T1/TANG-trong-k?) chuy?n ra
        -- GIAM_RA_TRAI_GUARDED_IDS (T?ng C, sau ALL_TANG_RAW_IDS/ALL_GIAM_RAW_IDS) ?? dùng
        -- chung khuôn guard v?i toàn b? kh?i TANG/GIAM còn l?i — xem comment ??u file.
        -- C?p nh?t 2026-08-21: lo?i tr? tr??ng h?p PN ?ang trích xu?t CH?A V? t?i ?úng th?i
        -- ?i?m h?t h?n — GIAM_12 ?ã tính "r?i nhóm" 1 l?n khi ?i trích xu?t; n?u h?t h?n x?y ra
        -- trong lúc v?n ?ang ?i (ch?a có b?n ghi tr? v? h?p l? tr??c ho?c ?úng ngày h?t h?n),
        -- ?ây KHÔNG ph?i l?n r?i nhóm th? 2 — ch? là th? t?c hành chính xác nh?n h?t h?n trong
        -- lúc ?ã v?ng m?t s?n. Không lo?i (NOT EXISTS) s? ??m GIAM 2 l?n cho 1 l?n r?i nhóm
        -- th?c t?, phá v? T1+TANG-GIAM=DCHA (?ã g?p th?c t?: tr?i 94280/2024, 6 PN, vd 13937).
        -- TX_NGAY_TRA không h?p l? (NULL, ho?c < TX_NGAY_TRICH_XUAT do l?i nh?p li?u) coi nh?
        -- CH?A V? — cùng quy ??c v?i TANG_6_IDS phía trên.
        GIAM_RA_TRAI_RAW_IDS AS (
            SELECT RT.PHAM_NHAN_ID AS PN_LAI_LICH_ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(RT.THA_NGAY_HET_HAN AS DATE) AS EVENT_DATE
              FROM QLPN.PN_LAI_LICH_CHI_TIET_RT RT
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE RT.THA_NGAY_HET_HAN >= THANG.TU_NGAY
               AND RT.THA_NGAY_HET_HAN < THANG.NGAY_XET_EXCLUSIVE
               AND RT.THA_ID IS NOT NULL
               AND NVL(RT.IS_DELETED, 0) = 0
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
               AND NOT EXISTS (
                       SELECT 1 FROM QLPN.TRICH_XUATS TX
                        WHERE TX.PHAM_NHAN_ID = RT.PHAM_NHAN_ID
                          AND TX.TX_LOAI_LENH_ID = 1
                          AND NVL(TX.IS_DELETED, 0) = 0
                          AND CAST(TX.TX_NGAY_TRICH_XUAT AS DATE) <= CAST(RT.THA_NGAY_HET_HAN AS DATE)
                          AND (
                                  TX.TX_NGAY_TRA IS NULL
                               OR CAST(TX.TX_NGAY_TRA AS DATE) < CAST(TX.TX_NGAY_TRICH_XUAT AS DATE)
                               OR CAST(TX.TX_NGAY_TRA AS DATE) > CAST(RT.THA_NGAY_HET_HAN AS DATE)
                              )
                   )
        ),

        -- Chuy?n tr?i khác (mã TTPN 161, xem FN_TINH_TRANG_PN_TAI_NGAY.cand pri=12) — PN r?i
        -- nhóm 111-114 qua PHAM_NHAN_CHUYEN_TRAI v?i THCT_MA <> '50' ('T?m ?ình ch? chuy?n
        -- tr?i khác' — tr??ng h?p ?ó do nhánh TDC quy?t ??nh tình tr?ng, không ph?i 161).
        GIAM_16_CHUYEN_TRAI_KHAC_RAW_IDS AS (
            SELECT CT.PNCT_LAI_LICH_ID AS PN_LAI_LICH_ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(CT.PNCT_NGAY_CHUYEN AS DATE) AS EVENT_DATE
              FROM QLPN.PHAM_NHAN_CHUYEN_TRAI CT
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = CT.PNCT_LAI_LICH_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
              LEFT JOIN QLPN.DM_TRUONG_HOP_CHUYEN_TRAIS THCT ON THCT.ID = CT.PNCT_TRUONG_HOP_CHUYEN_ID
             CROSS JOIN THANG
             WHERE CT.PNCT_NGAY_CHUYEN >= THANG.TU_NGAY
               AND CT.PNCT_NGAY_CHUYEN < THANG.NGAY_XET_EXCLUSIVE
               AND (THCT.THCT_MA <> '50' OR THCT.THCT_MA IS NULL)
               AND NVL(CT.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        GIAM_DAC_XA_IDS AS (
            SELECT DX.PNLAI_LICH_ID AS PN_LAI_LICH_ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(DX.DX_NGAY_THA AS DATE) AS EVENT_DATE
              FROM QLPN.PN_DAC_XAS DX
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = DX.PNLAI_LICH_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE DX.DX_NGAY_THA >= THANG.TU_NGAY
               AND DX.DX_NGAY_THA < THANG.NGAY_XET_EXCLUSIVE
               AND DX.DX_TINH_TRANG_DAC_XA IN ('1', '2', '7')
               AND NVL(DX.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        GIAM_THA_TRUOC_IDS AS (
            SELECT TCK.PHAM_NHAN_ID AS PN_LAI_LICH_ID, TG.TG_MA AS MA_TRAI_GIAM,
                   CAST(TCK.NGAY_THA AS DATE) AS EVENT_DATE
              FROM QLPN.THA_CO_DIEU_KIENS TCK
              JOIN QLPN.PN_LAI_LICH_CHI_TIET_RT RT ON RT.PHAM_NHAN_ID = TCK.PHAM_NHAN_ID
              JOIN QLPN.DM_TRAI_GIAMS TG ON TG.ID = RT.LL_TRAI_GIAM_ID AND NVL(TG.IS_DELETED, 0) = 0
             CROSS JOIN THANG
             WHERE TCK.NGAY_THA >= THANG.TU_NGAY
               AND TCK.NGAY_THA < THANG.NGAY_XET_EXCLUSIVE
               AND (TCK.NGAY_BAT_LAI IS NULL OR TCK.NGAY_BAT_LAI >= THANG.NGAY_XET_EXCLUSIVE)
               AND NVL(TCK.IS_DELETED, 0) = 0
               AND NVL(RT.IS_DELETED, 0) = 0
               AND (p_ma_trai_giam IS NULL OR TG.TG_MA = p_ma_trai_giam)
        ),

        -- ================================================================
        -- T?ng B (2026-08-21) — g?p toàn b? s? ki?n TANG/GIAM thô (ch?a l?c guard) ??
        -- các CTE guarded ? T?ng C d??i ?ây tham chi?u chéo mà không t?o circular reference
        -- (TANG c?n bi?t GIAM ?ã x?y ra trong k? và ng??c l?i, nh?ng CTE không forward-reference
        -- ???c nhau). TANG_3_IDS và GIAM_17_NOI_BO_IDS (c?p chuy?n tr?i n?i b?) C? Ý không ??i
        -- x?ng: TANG_3 v?n ???c g?p vào ALL_TANG_RAW_IDS (gi? nguyên union inline ?ã có s?n
        -- trong 2 guard TANG-check c?, không ??i hành vi), nh?ng GIAM_17_NOI_BO KHÔNG ???c g?p
        -- vào ALL_GIAM_RAW_IDS — chuy?n tr?i n?i b? không ph?i PN "r?i nhóm" 111-114 th?t (ch?
        -- ??i tr?i), g?p vào s? khi?n guard TANG ? ch? khác l?m t??ng PN ?ã r?i nhóm.
        -- ================================================================
        -- C?p nh?t 2026-08-21 (sau khi ?o th?c t? th?y guard "OR có s? ki?n ??i l?p b?t k? lúc
        -- nào trong k?" hoàn toàn không l?c ???c gì ? k? N?M — 852/2385 PN tr?i 94280 có s?
        -- ki?n h?t h?n b?t k? trong n?m 2022, quá d? trùng h?p ng?u nhiên): m?i CTE raw gi?
        -- mang theo EVENT_DATE (ngày s? ki?n c?a chính nó), và ALL_TANG_RAW_IDS/ALL_GIAM_RAW_IDS
        -- g?p theo (ID, EVENT_DATE) ?? T?ng C có th? so sánh TH? T? TH?I GIAN — s? ki?n ??i l?p
        -- ph?i x?y ra TR??C HO?C CÙNG NGÀY v?i s? ki?n ?ang xét, không ph?i "b?t k? lúc nào
        -- trong k?" — m?i th?c s? lo?i ???c các tr??ng h?p trùng h?p ng?u nhiên không liên quan.
        ALL_TANG_RAW_IDS AS (
            SELECT ID, EVENT_DATE FROM TANG_2_IDS  UNION ALL
            SELECT ID, EVENT_DATE FROM TANG_3_IDS  UNION ALL
            SELECT ID, EVENT_DATE FROM TANG_4_IDS  UNION ALL
            SELECT ID, EVENT_DATE FROM TANG_5_IDS  UNION ALL
            SELECT ID, EVENT_DATE FROM TANG_6_IDS  UNION ALL
            SELECT ID, EVENT_DATE FROM TANG_7A_IDS UNION ALL
            SELECT ID, EVENT_DATE FROM TANG_7B_IDS
        ),
        ALL_GIAM_RAW_IDS AS (
            SELECT PHAM_NHAN_ID       AS ID, EVENT_DATE FROM GIAM_10_IDS               UNION ALL
            SELECT KTC_PN_LAI_LICH_ID AS ID, EVENT_DATE FROM GIAM_11_IDS               UNION ALL
            SELECT PHAM_NHAN_ID       AS ID, EVENT_DATE FROM GIAM_12_IDS               UNION ALL
            SELECT PHAM_NHAN_ID       AS ID, EVENT_DATE FROM GIAM_13_IDS               UNION ALL
            SELECT PHAM_NHAN_ID       AS ID, EVENT_DATE FROM GIAM_15A_IDS              UNION ALL
            SELECT PHAM_NHAN_ID       AS ID, EVENT_DATE FROM GIAM_15B_IDS              UNION ALL
            SELECT PN_LAI_LICH_ID     AS ID, EVENT_DATE FROM GIAM_15C_IDS              UNION ALL
            SELECT PNCG_LAI_LICH_ID   AS ID, EVENT_DATE FROM GIAM_15E_IDS              UNION ALL
            SELECT PN_LAI_LICH_ID     AS ID, EVENT_DATE FROM GIAM_RA_TRAI_RAW_IDS      UNION ALL
            SELECT PN_LAI_LICH_ID     AS ID, EVENT_DATE FROM GIAM_16_CHUYEN_TRAI_KHAC_RAW_IDS UNION ALL
            SELECT PN_LAI_LICH_ID     AS ID, EVENT_DATE FROM GIAM_DAC_XA_IDS           UNION ALL
            SELECT PN_LAI_LICH_ID     AS ID, EVENT_DATE FROM GIAM_THA_TRUOC_IDS
        ),

        -- ================================================================
        -- T?ng C (2026-08-21) — b?c guard "ch? tính khi th?c s? ??i nhóm 111-114":
        -- TANG ch? tính n?u PN KHÔNG ? nhóm 111-114 t?i T1 (NGAY_XET=TU_NGAY-1) HO?C ?ã r?i
        -- nhóm qua 1 s? ki?n GIAM th?t X?Y RA TR??C HO?C CÙNG NGÀY (EVENT_DATE <=) v?i s? ki?n
        -- TANG ?ang xét; GIAM ch? tính n?u PN ?ANG ? nhóm ?ó t?i T1 HO?C ?ã vào nhóm qua 1 s?
        -- ki?n TANG th?t x?y ra tr??c/cùng ngày. B?t bu?c so sánh th? t? th?i gian (không ch?
        -- "có x?y ra trong k?" nh? 2 guard c? GIAM_RA_TRAI/GIAM_16 ban ??u) — ?o th?c t? cho
        -- th?y n?u không so ngày, guard vô hi?u hoàn toàn ? k? N?M (852/2385 PN tr?i 94280 có
        -- s? ki?n h?t h?n b?t k? trong n?m 2022, quá d? trùng h?p ng?u nhiên không liên quan).
        -- TANG_3_IDS/GIAM_17_NOI_BO_IDS KHÔNG có wrapper — dùng th?ng, xem comment T?ng B.
        -- ================================================================
        TANG_2_GUARDED_IDS AS (
            SELECT T.ID, T.MA_TRAI_GIAM, T.EVENT_DATE
              FROM TANG_2_IDS T CROSS JOIN THANG TH
             WHERE NOT EXISTS (
                       SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                        WHERE ctt.PN_LAI_LICH_ID = T.ID
                          AND ctt.NGAY_XET = TH.TU_NGAY - 1
