                OR EXISTS (SELECT 1 FROM ALL_GIAM_RAW_IDS g WHERE g.ID = T.ID AND g.EVENT_DATE <= T.EVENT_DATE)
        ),
        TANG_4_GUARDED_IDS AS (
            SELECT T.ID, T.MA_TRAI_GIAM, T.EVENT_DATE
