        ),
        GIAM_15C_GUARDED_IDS AS (
            SELECT G.PN_LAI_LICH_ID, G.MA_TRAI_GIAM, G.EVENT_DATE
              FROM GIAM_15C_IDS G CROSS JOIN THANG TH
