        ),
        GIAM_15E_GUARDED_IDS AS (
            SELECT G.PNCG_LAI_LICH_ID, G.MA_TRAI_GIAM, G.EVENT_DATE
              FROM GIAM_15E_IDS G CROSS JOIN THANG TH
             WHERE EXISTS (
                       SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                        WHERE ctt.PN_LAI_LICH_ID = G.PNCG_LAI_LICH_ID
                          AND ctt.NGAY_XET = TH.TU_NGAY - 1
                          AND ctt.TTPN_MA IN ('111', '112', '113', '114')
                   )
                OR EXISTS (SELECT 1 FROM ALL_TANG_RAW_IDS t WHERE t.ID = G.PNCG_LAI_LICH_ID AND t.EVENT_DATE <= G.EVENT_DATE)
        ),
        GIAM_RA_TRAI_GUARDED_IDS AS (
            SELECT G.PN_LAI_LICH_ID, G.MA_TRAI_GIAM, G.EVENT_DATE
              FROM GIAM_RA_TRAI_RAW_IDS G CROSS JOIN THANG TH
             WHERE EXISTS (
                       SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                        WHERE ctt.PN_LAI_LICH_ID = G.PN_LAI_LICH_ID
                          AND ctt.NGAY_XET = TH.TU_NGAY - 1
                          AND ctt.TTPN_MA IN ('111', '112', '113', '114')
                   )
                OR EXISTS (SELECT 1 FROM ALL_TANG_RAW_IDS t WHERE t.ID = G.PN_LAI_LICH_ID AND t.EVENT_DATE <= G.EVENT_DATE)
        ),
        GIAM_16_CHUYEN_TRAI_KHAC_GUARDED_IDS AS (
            SELECT G.PN_LAI_LICH_ID, G.MA_TRAI_GIAM, G.EVENT_DATE
              FROM GIAM_16_CHUYEN_TRAI_KHAC_RAW_IDS G CROSS JOIN THANG TH
             WHERE EXISTS (
                       SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                        WHERE ctt.PN_LAI_LICH_ID = G.PN_LAI_LICH_ID
                          AND ctt.NGAY_XET = TH.TU_NGAY - 1
                          AND ctt.TTPN_MA IN ('111', '112', '113', '114')
                   )
                OR EXISTS (SELECT 1 FROM ALL_TANG_RAW_IDS t WHERE t.ID = G.PN_LAI_LICH_ID AND t.EVENT_DATE <= G.EVENT_DATE)
        ),
        GIAM_DAC_XA_GUARDED_IDS AS (
            SELECT G.PN_LAI_LICH_ID, G.MA_TRAI_GIAM, G.EVENT_DATE
              FROM GIAM_DAC_XA_IDS G CROSS JOIN THANG TH
             WHERE EXISTS (
                       SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                        WHERE ctt.PN_LAI_LICH_ID = G.PN_LAI_LICH_ID
                          AND ctt.NGAY_XET = TH.TU_NGAY - 1
                          AND ctt.TTPN_MA IN ('111', '112', '113', '114')
                   )
                OR EXISTS (SELECT 1 FROM ALL_TANG_RAW_IDS t WHERE t.ID = G.PN_LAI_LICH_ID AND t.EVENT_DATE <= G.EVENT_DATE)
        ),
        GIAM_THA_TRUOC_GUARDED_IDS AS (
            SELECT G.PN_LAI_LICH_ID, G.MA_TRAI_GIAM, G.EVENT_DATE
              FROM GIAM_THA_TRUOC_IDS G CROSS JOIN THANG TH
             WHERE EXISTS (
                       SELECT 1 FROM QLPN.PN_TINH_TRANG_TAI_NGAY_CACHE ctt
                        WHERE ctt.PN_LAI_LICH_ID = G.PN_LAI_LICH_ID
                          AND ctt.NGAY_XET = TH.TU_NGAY - 1
                          AND ctt.TTPN_MA IN ('111', '112', '113', '114')
                   )
                OR EXISTS (SELECT 1 FROM ALL_TANG_RAW_IDS t WHERE t.ID = G.PN_LAI_LICH_ID AND t.EVENT_DATE <= G.EVENT_DATE)
        )

        SELECT 'TANG' AS LOAI, 'TANG_2' AS NHOM, ID AS PHAM_NHAN_ID, MA_TRAI_GIAM, EVENT_DATE FROM TANG_2_GUARDED_IDS
        UNION ALL
        SELECT 'TANG', 'TANG_3', ID, MA_TRAI_GIAM, EVENT_DATE FROM TANG_3_IDS
        UNION ALL
        SELECT 'TANG', 'TANG_4', ID, MA_TRAI_GIAM, EVENT_DATE FROM TANG_4_GUARDED_IDS
        UNION ALL
        SELECT 'TANG', 'TANG_5', ID, MA_TRAI_GIAM, EVENT_DATE FROM TANG_5_GUARDED_IDS
        UNION ALL
        SELECT 'TANG', 'TANG_6', ID, MA_TRAI_GIAM, EVENT_DATE FROM TANG_6_GUARDED_IDS
        UNION ALL
        SELECT 'TANG', 'TANG_7A', ID, MA_TRAI_GIAM, EVENT_DATE FROM TANG_7A_GUARDED_IDS
        UNION ALL
        SELECT 'TANG', 'TANG_7B', ID, MA_TRAI_GIAM, EVENT_DATE FROM TANG_7B_GUARDED_IDS
        -- TANG_7C_IDS c? ý không UNION — xem comment ??u file
        UNION ALL
        SELECT 'GIAM', 'GIAM_10', PHAM_NHAN_ID, MA_TRAI_GIAM, EVENT_DATE FROM GIAM_10_GUARDED_IDS
        UNION ALL
        SELECT 'GIAM', 'GIAM_11', KTC_PN_LAI_LICH_ID, MA_TRAI_GIAM, EVENT_DATE FROM GIAM_11_GUARDED_IDS
        UNION ALL
        SELECT 'GIAM', 'GIAM_12', PHAM_NHAN_ID, MA_TRAI_GIAM, EVENT_DATE FROM GIAM_12_GUARDED_IDS
        UNION ALL
        SELECT 'GIAM', 'GIAM_13', PHAM_NHAN_ID, MA_TRAI_GIAM, EVENT_DATE FROM GIAM_13_GUARDED_IDS
        UNION ALL
        SELECT 'GIAM', 'GIAM_15A', PHAM_NHAN_ID, MA_TRAI_GIAM, EVENT_DATE FROM GIAM_15A_GUARDED_IDS
        UNION ALL
        SELECT 'GIAM', 'GIAM_15B', PHAM_NHAN_ID, MA_TRAI_GIAM, EVENT_DATE FROM GIAM_15B_GUARDED_IDS
        UNION ALL
        SELECT 'GIAM', 'GIAM_15C', PN_LAI_LICH_ID, MA_TRAI_GIAM, EVENT_DATE FROM GIAM_15C_GUARDED_IDS
        -- GIAM_15D_IDS c? ý không UNION — xem comment ??u file
        UNION ALL
        SELECT 'GIAM', 'GIAM_15E', PNCG_LAI_LICH_ID, MA_TRAI_GIAM, EVENT_DATE FROM GIAM_15E_GUARDED_IDS
        UNION ALL
        SELECT 'GIAM', 'GIAM_17_NOI_BO', ID, MA_TRAI_GIAM, EVENT_DATE FROM GIAM_17_NOI_BO_IDS
        UNION ALL
        SELECT 'GIAM', 'GIAM_RA_TRAI', PN_LAI_LICH_ID, MA_TRAI_GIAM, EVENT_DATE FROM GIAM_RA_TRAI_GUARDED_IDS
        UNION ALL
        SELECT 'GIAM', 'GIAM_16_CT_KHAC', PN_LAI_LICH_ID, MA_TRAI_GIAM, EVENT_DATE FROM GIAM_16_CHUYEN_TRAI_KHAC_GUARDED_IDS
        UNION ALL
        SELECT 'GIAM', 'GIAM_DAC_XA', PN_LAI_LICH_ID, MA_TRAI_GIAM, EVENT_DATE FROM GIAM_DAC_XA_GUARDED_IDS
        UNION ALL
        SELECT 'GIAM', 'GIAM_THA_TRUOC', PN_LAI_LICH_ID, MA_TRAI_GIAM, EVENT_DATE FROM GIAM_THA_TRUOC_GUARDED_IDS
    ) LOOP
        PIPE ROW (QLPN.TY_TANG_GIAM_ROW(r.LOAI, r.NHOM, r.PHAM_NHAN_ID, r.MA_TRAI_GIAM, r.EVENT_DATE));
    END LOOP;

    RETURN;
END FN_PN_TANG_GIAM_TRONG_KY;

