/
--------------------------------------------------------
--  DDL for Function FN_SO_NGAY_TAM_DINH_CHI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_SO_NGAY_TAM_DINH_CHI" (
    P_PHAM_NHAN_ID NUMBER
) RETURN NVARCHAR2
IS
    V_SO_NGAY NUMBER := 0;
    V_NAM NUMBER;
    V_THANG NUMBER;
    V_NGAY NUMBER;
BEGIN

    SELECT NVL(SUM(CAST(NGAY_LAI AS DATE) - CAST(TU_NGAY AS DATE)),0)
    INTO V_SO_NGAY
    FROM TAM_DINH_CHIS
    WHERE PHAM_NHAN_ID = P_PHAM_NHAN_ID
      AND IS_DELETED = 0
      AND TU_NGAY IS NOT NULL
      AND NGAY_LAI IS NOT NULL;

    IF V_SO_NGAY < 30 AND V_SO_NGAY > 0 THEN
        RETURN V_SO_NGAY || ' ngày';
    END IF;

    V_NAM := TRUNC(V_SO_NGAY / 365);
    V_THANG := TRUNC(MOD(V_SO_NGAY,365) / 30);
    V_NGAY := MOD(MOD(V_SO_NGAY,365),30);

    RETURN CASE
               WHEN V_NAM = 0 AND V_THANG = 0 AND V_NGAY = 0 THEN 'Không'
               ELSE
                   CASE
                       WHEN
                           V_NAM IS NOT NULL AND V_NAM != 0 THEN V_NAM || ' n?m '
                       END
                       ||
                   CASE
                       WHEN
                           V_THANG IS NOT NULL AND V_THANG != 0
                           THEN V_THANG || ' tháng '
                       END ||
                   CASE
                       WHEN V_NGAY IS NOT NULL AND V_NGAY != 0 THEN
                           V_NGAY || ' ngày'
                       END
    END;

END;





/
--------------------------------------------------------
--  DDL for Function FN_SWAP_FIRST_LAST_SORT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_SWAP_FIRST_LAST_SORT" (p_str VARCHAR2)
RETURN RAW
IS
    v_first  VARCHAR2(1000);
    v_last   VARCHAR2(1000);
    v_middle VARCHAR2(2000);
    v_str    VARCHAR2(4000);
BEGIN
    IF p_str IS NULL THEN
        RETURN NULL;
    END IF;

    -- L?y t? ??u
    v_first := REGEXP_SUBSTR(p_str, '^\S+');

    -- L?y t? cu?i
    v_last := REGEXP_SUBSTR(p_str, '\S+$');

    -- L?y ph?n gi?a
    v_middle := TRIM(
        REGEXP_REPLACE(p_str, '^\S+\s*|\s*\S+$', '')
    );

    -- Ghép l?i: last + middle + first
    v_str := v_last ||
             CASE WHEN v_middle IS NOT NULL THEN ' ' || v_middle ELSE '' END ||
             ' ' || v_first;

    RETURN NLSSORT(v_str, 'NLS_SORT = BINARY_AI');
END;




/
--------------------------------------------------------
--  DDL for Function FN_TAM_DINH_CHI_HIEN_THI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TAM_DINH_CHI_HIEN_THI" (p_id_pham_nhan IN NUMBER) RETURN NVARCHAR2 IS
  v_so_lan NUMBER;
  v_tong NUMBER;
  v_ref DATE := DATE '1900-01-01';
  v_y NUMBER;
  v_m NUMBER;
  v_d NUMBER;
  v_parts NVARCHAR2(400);
BEGIN
  v_so_lan := QLPN.FN_TINH_SO_LAN_TAM_DINH_CHI(p_id_pham_nhan);
  v_tong := QLPN.FN_TINH_TONG_THOI_GIAN_TAM_DINH_CHI(p_id_pham_nhan);
  IF v_so_lan = 0 OR v_tong IS NULL OR v_tong <= 0 THEN
    RETURN NULL;
  END IF;
  DECLARE
    d1 DATE := v_ref;
    d2 DATE := v_ref + v_tong;
    v_months NUMBER;
    v_tmp DATE;
  BEGIN
    v_months := TRUNC(MONTHS_BETWEEN(d2, d1));
    v_y := TRUNC(v_months / 12);
    v_m := MOD(v_months, 12);
    v_tmp := ADD_MONTHS(d1, v_y * 12 + v_m);
    v_d := TRUNC(d2 - v_tmp);
    IF v_d < 0 THEN
      v_m := v_m - 1;
      IF v_m < 0 THEN v_y := v_y - 1; v_m := v_m + 12; END IF;
      v_tmp := ADD_MONTHS(d1, v_y * 12 + v_m);
      v_d := GREATEST(TRUNC(d2 - v_tmp), 0);
    END IF;
  END;
  IF v_y >= 1 THEN
    v_parts := NULL;
    IF v_y > 0 THEN v_parts := TO_NCHAR(v_y) || ' nam'; END IF;
    IF v_m > 0 THEN v_parts := v_parts || ' ' || TO_NCHAR(v_m) || ' thang'; END IF;
    IF v_d > 0 THEN v_parts := v_parts || ' ' || TO_NCHAR(v_d) || ' ngay'; END IF;
    RETURN TO_NCHAR(v_so_lan) || ' lan = ' || v_parts;
  ELSIF v_m >= 1 THEN
    IF v_d > 0 THEN RETURN TO_NCHAR(v_so_lan) || ' lan = ' || TO_NCHAR(v_m) || ' Thang ' || TO_NCHAR(v_d) || ' ngay';
    ELSE RETURN TO_NCHAR(v_so_lan) || ' lan = ' || TO_NCHAR(v_m) || ' Thang';
    END IF;
  ELSE
    RETURN TO_NCHAR(v_so_lan) || ' lan = ' || TO_NCHAR(NVL(v_d, 0)) || ' ngay';
  END IF;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END FN_TAM_DINH_CHI_HIEN_THI;





