/
--------------------------------------------------------
--  DDL for Function FN_TINH_AN_DA_GIAM
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_AN_DA_GIAM" (
    p_PN_ID IN NUMBER
)
RETURN TINH_AN_OBJ
IS
    v_lan_giam   NUMBER;
    v_tong_ngay  NUMBER;
    v_cac_lan    NVARCHAR2(4000);
BEGIN
    SELECT
        COUNT(*),
        SUM(
            NVL(TO_NUMBER(REGEXP_SUBSTR(NVL(dm.MTG_TITLE, ''), '[0-9]+', 1, 1)), 0) * 365
          + NVL(TO_NUMBER(REGEXP_SUBSTR(NVL(dm.MTG_TITLE, ''), '[0-9]+', 1, 2)), 0) * 30
          + NVL(TO_NUMBER(REGEXP_SUBSTR(NVL(dm.MTG_TITLE, ''), '[0-9]+', 1, 3)), 0)
        ),
        NVL(
            LISTAGG(NVL(dm.MTG_TITLE, gth.DA_GIAM), CHR(10) ON OVERFLOW TRUNCATE '...' WITH COUNT)
                WITHIN GROUP (ORDER BY gth.NGAY_QUYET_DINH NULLS LAST, gth.NGAY_XET NULLS LAST, gth.ID),
            u'Kh\00f4ng'
        )
    INTO v_lan_giam, v_tong_ngay, v_cac_lan
    FROM GIAM_THOI_HANS gth
    LEFT JOIN DM_MA_THOI_GIANS dm
        ON dm.ID = gth.MUC_GIAM_ID
       AND NVL(dm.IS_DELETED, 0) = 0
    WHERE NVL(gth.IS_DELETED, 0) = 0
      AND gth.PHAM_NHAN_ID = p_PN_ID
      AND gth.MUC_GIAM_ID IS NOT NULL;

    RETURN TINH_AN_OBJ(
        v_lan_giam,
        CASE
            WHEN v_tong_ngay IS NULL OR v_tong_ngay = 0 THEN '0'
            ELSE
                TRUNC(v_tong_ngay / 365) || u' n\0103m ' ||
                TRUNC(MOD(v_tong_ngay, 365) / 30) || u' th\00e1ng ' ||
                MOD(MOD(v_tong_ngay, 365), 30) || u' ng\00e0y'
        END,
        v_cac_lan
    );
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN TINH_AN_OBJ(0, '0', u'Kh\00f4ng');
    WHEN OTHERS THEN
        RAISE;
END FN_TINH_AN_DA_GIAM;







/
--------------------------------------------------------
--  DDL for Function FN_TINH_AN_DA_GIAM_CHI_TIET
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_AN_DA_GIAM_CHI_TIET" (
    p_PN_ID IN NUMBER
)
RETURN NVARCHAR2
IS
    v_lan_giam        NUMBER := 0;
    v_tong_nam        NUMBER := 0;
    v_tong_thang      NUMBER := 0;
    v_tong_ngay       NUMBER := 0;

    v_lan_dac_biet    NUMBER := 0;
    v_ten_dac_biet    NVARCHAR2(1000) := '';

    v_nam_final       NUMBER;
    v_thang_final     NUMBER;
    v_ngay_final      NUMBER;
    v_text            NVARCHAR2(1000);
    v_phan_tg         NVARCHAR2(500);
    v_tong_lan        NUMBER := 0;
BEGIN

    -- ====================== PH?N 1: Các l?n gi?m bình th??ng (có th?i h?n) ======================
    -- Không tính các mã ??c bi?t (92xxx) và mã null
    SELECT COUNT(*),
           SUM(NVL(TO_NUMBER(REGEXP_SUBSTR(dm.MTG_TITLE, '(\d+)\s*n.m',   1, 1, NULL, 1)), 0)),
           SUM(NVL(TO_NUMBER(REGEXP_SUBSTR(dm.MTG_TITLE, '(\d+)\s*th.ng', 1, 1, NULL, 1)), 0)),
           SUM(NVL(TO_NUMBER(REGEXP_SUBSTR(dm.MTG_TITLE, '(\d+)\s*ng.y',  1, 1, NULL, 1)), 0))
      INTO v_lan_giam, v_tong_nam, v_tong_thang, v_tong_ngay
      FROM GIAM_THOI_HANS gth
      JOIN DM_MA_THOI_GIANS dm
        ON dm.ID = gth.MUC_GIAM_ID
       AND NVL(dm.IS_DELETED, 0) = 0
     WHERE gth.PHAM_NHAN_ID = p_PN_ID
       AND NVL(gth.IS_DELETED, 0) = 0
       AND gth.MUC_GIAM_ID IS NOT NULL
       AND NVL(dm.MTG_MA, 'x') NOT LIKE '9%';  -- Lo?i toàn b? mã ??c bi?t 9xxxx

    -- ====================== PH?N 2: Các mã ??c bi?t tính l?n ======================
    -- 912000, 921000, 923000 ? tính l?n + n?i tên
    -- 925000, 926000, 927000 ? b? qua hoàn toàn
    FOR rec IN (
        SELECT dm.MTG_MA, dm.MTG_TITLE
          FROM GIAM_THOI_HANS gth
          JOIN DM_MA_THOI_GIANS dm
            ON gth.MUC_GIAM_ID =dm.ID
           AND NVL(dm.IS_DELETED, 0) = 0
         WHERE gth.PHAM_NHAN_ID = p_PN_ID
           AND NVL(gth.IS_DELETED, 0) = 0
           AND gth.MUC_GIAM_ID IS NOT NULL
           AND dm.MTG_MA IN ('912000', '921000', '923000')
    ) LOOP
        v_lan_dac_biet := v_lan_dac_biet + 1;
        IF v_ten_dac_biet IS NOT NULL THEN
            v_ten_dac_biet := v_ten_dac_biet || '; ';
        END IF;
        v_ten_dac_biet := v_ten_dac_biet || rec.MTG_TITLE;
    END LOOP;

    -- ====================== T?NG S? L?N ======================
    v_tong_lan := NVL(v_lan_giam, 0) + v_lan_dac_biet;

    IF v_tong_lan = 0 THEN
        RETURN u'Không';
    END IF;

    -- ====================== QUY ??I TH?I GIAN ======================
    v_nam_final   := NVL(v_tong_nam, 0) + TRUNC(NVL(v_tong_thang, 0) / 12);
    v_thang_final := MOD(NVL(v_tong_thang, 0), 12);
    v_ngay_final  := NVL(v_tong_ngay, 0);

    -- ====================== T?O CHU?I K?T QU? ======================
    -- V? trái: s? l?n = th?i gian (ch? khi có l?n bình th??ng)
    v_phan_tg := '';
    IF v_lan_giam > 0 THEN
        IF v_nam_final   > 0 THEN v_phan_tg := v_phan_tg || v_nam_final   || u' n?m ';   END IF;
        IF v_thang_final > 0 THEN v_phan_tg := v_phan_tg || v_thang_final || u' tháng '; END IF;
        IF v_ngay_final  > 0 THEN v_phan_tg := v_phan_tg || v_ngay_final  || u' ngày';   END IF;
        IF TRIM(v_phan_tg) IS NULL THEN v_phan_tg := '0'; END IF;
    END IF;

    v_text := TO_CHAR(v_tong_lan) || u' l?n';

    IF TRIM(v_phan_tg) IS NOT NULL THEN
        v_text := v_text || ' = ' || TRIM(v_phan_tg);
    END IF;

    -- V? ph?i: n?i tên mã ??c bi?t n?u có
    IF v_ten_dac_biet IS NOT NULL THEN
        v_text := v_text || '; ' || v_ten_dac_biet;
    END IF;

    RETURN TRIM(v_text);

EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN u'Không';
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('[FN_TINH_AN_DA_GIAM] L?i PN_ID = ' || p_PN_ID || ' - ' || SQLERRM);
        RETURN u'Không';
END FN_TINH_AN_DA_GIAM_CHI_TIET;




/
--------------------------------------------------------
--  DDL for Function FN_TINH_AN_DA_GIAM_CHI_TIET_GTH
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_AN_DA_GIAM_CHI_TIET_GTH" (
    p_PN_ID IN NUMBER,
    p_ngay_xet IN DATE
)
RETURN NVARCHAR2
IS
    v_lan_giam        NUMBER := 0;
    v_tong_nam        NUMBER := 0;
    v_tong_thang      NUMBER := 0;
    v_tong_ngay       NUMBER := 0;

    v_lan_dac_biet    NUMBER := 0;
    v_ten_dac_biet    NVARCHAR2(1000) := '';

    v_nam_final       NUMBER;
    v_thang_final     NUMBER;
    v_ngay_final      NUMBER;
    v_text            NVARCHAR2(1000);
    v_phan_tg         NVARCHAR2(500);
    v_tong_lan        NUMBER := 0;
BEGIN

    -- ====================== PH?N 1: Các l?n gi?m bình th??ng (có th?i h?n) ======================
    -- Không tính các mã ??c bi?t (92xxx) và mã null
    SELECT COUNT(*),
           SUM(NVL(TO_NUMBER(REGEXP_SUBSTR(dm.MTG_TITLE, '(\d+)\s*n.m',   1, 1, NULL, 1)), 0)),
           SUM(NVL(TO_NUMBER(REGEXP_SUBSTR(dm.MTG_TITLE, '(\d+)\s*th.ng', 1, 1, NULL, 1)), 0)),
           SUM(NVL(TO_NUMBER(REGEXP_SUBSTR(dm.MTG_TITLE, '(\d+)\s*ng.y',  1, 1, NULL, 1)), 0))
      INTO v_lan_giam, v_tong_nam, v_tong_thang, v_tong_ngay
      FROM GIAM_THOI_HANS gth
      JOIN DM_MA_THOI_GIANS dm
        ON dm.ID = gth.MUC_GIAM_ID
       AND NVL(dm.IS_DELETED, 0) = 0
     WHERE gth.PHAM_NHAN_ID = p_PN_ID
       AND gth.NGAY_XET <> p_ngay_xet
       AND NVL(gth.IS_DELETED, 0) = 0
       AND gth.MUC_GIAM_ID IS NOT NULL
       AND NVL(dm.MTG_MA, 'x') NOT LIKE '9%';  -- Lo?i toàn b? mã ??c bi?t 9xxxx

    -- ====================== PH?N 2: Các mã ??c bi?t tính l?n ======================
    -- 912000, 921000, 923000 ? tính l?n + n?i tên
    -- 925000, 926000, 927000 ? b? qua hoàn toàn
    FOR rec IN (
        SELECT dm.MTG_MA, dm.MTG_TITLE
          FROM GIAM_THOI_HANS gth
          JOIN DM_MA_THOI_GIANS dm
            ON gth.MUC_GIAM_ID =dm.ID
           AND NVL(dm.IS_DELETED, 0) = 0
         WHERE gth.PHAM_NHAN_ID = p_PN_ID
           AND NVL(gth.IS_DELETED, 0) = 0
           AND gth.MUC_GIAM_ID IS NOT NULL
           AND dm.MTG_MA IN ('912000', '921000', '923000')
    ) LOOP
        v_lan_dac_biet := v_lan_dac_biet + 1;
        IF v_ten_dac_biet IS NOT NULL THEN
            v_ten_dac_biet := v_ten_dac_biet || '; ';
        END IF;
        v_ten_dac_biet := v_ten_dac_biet || rec.MTG_TITLE;
    END LOOP;

    -- ====================== T?NG S? L?N ======================
    v_tong_lan := NVL(v_lan_giam, 0) + v_lan_dac_biet;

    IF v_tong_lan = 0 THEN
        RETURN u'Không';
    END IF;

    -- ====================== QUY ??I TH?I GIAN ======================
    v_nam_final   := NVL(v_tong_nam, 0) + TRUNC(NVL(v_tong_thang, 0) / 12);
    v_thang_final := MOD(NVL(v_tong_thang, 0), 12);
    v_ngay_final  := NVL(v_tong_ngay, 0);

    -- ====================== T?O CHU?I K?T QU? ======================
    -- V? trái: s? l?n = th?i gian (ch? khi có l?n bình th??ng)
    v_phan_tg := '';
    IF v_lan_giam > 0 THEN
        IF v_nam_final   > 0 THEN v_phan_tg := v_phan_tg || v_nam_final   || u' n?m ';   END IF;
        IF v_thang_final > 0 THEN v_phan_tg := v_phan_tg || v_thang_final || u' tháng '; END IF;
        IF v_ngay_final  > 0 THEN v_phan_tg := v_phan_tg || v_ngay_final  || u' ngày';   END IF;
        IF TRIM(v_phan_tg) IS NULL THEN v_phan_tg := '0'; END IF;
    END IF;

    v_text := TO_CHAR(v_tong_lan) || u' l?n';

    IF TRIM(v_phan_tg) IS NOT NULL THEN
        v_text := v_text || ' = ' || TRIM(v_phan_tg);
    END IF;

    -- V? ph?i: n?i tên mã ??c bi?t n?u có
    IF v_ten_dac_biet IS NOT NULL THEN
        v_text := v_text || '; ' || v_ten_dac_biet;
    END IF;

    RETURN TRIM(v_text);

EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN u'Không';
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('[FN_TINH_AN_DA_GIAM] L?i PN_ID = ' || p_PN_ID || ' - ' || SQLERRM);
        RETURN u'Không';
END FN_TINH_AN_DA_GIAM_CHI_TIET_GTH;


/
--------------------------------------------------------
--  DDL for Function FN_TINH_CON_LAI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_CON_LAI" (
    p_an_phat      IN NVARCHAR2,  -- text '4 n?m 1 tháng'
    p_da_giam      IN YMD_OBJ,
    p_da_chap_hanh IN YMD_OBJ
)
RETURN YMD_OBJ
IS
    v_an_phat_ymd   YMD_OBJ;
    v_tong_ngay_ap  NUMBER;
    v_tong_ngay_dg  NUMBER;
    v_tong_ngay_dch NUMBER;
    v_con_lai_ngay  NUMBER;
    v_nam           NUMBER; 
    v_thang         NUMBER;
    v_ngay          NUMBER;
BEGIN
    v_an_phat_ymd   := FN_PARSE_AN_PHAT_TO_YMD(p_an_phat);

    -- Quy t?t c? v? ngày ?? tr?
    v_tong_ngay_ap  := NVL(v_an_phat_ymd.nam,   0) * 365
                     + NVL(v_an_phat_ymd.thang, 0) * 30
                     + NVL(v_an_phat_ymd.ngay,  0);

    v_tong_ngay_dg  := NVL(p_da_giam.nam,   0) * 365
                     + NVL(p_da_giam.thang, 0) * 30
                     + NVL(p_da_giam.ngay,  0);

    v_tong_ngay_dch := NVL(p_da_chap_hanh.nam,   0) * 365
                     + NVL(p_da_chap_hanh.thang, 0) * 30
                     + NVL(p_da_chap_hanh.ngay,  0);

    v_con_lai_ngay := v_tong_ngay_ap - v_tong_ngay_dg - v_tong_ngay_dch;

    IF v_con_lai_ngay <= 0 THEN
        RETURN YMD_OBJ(0, 0, 0);
    END IF;

    -- Chu?n hóa v? n?m/tháng/ngày
    v_nam   := FLOOR(v_con_lai_ngay / 365);
    v_thang := FLOOR(MOD(v_con_lai_ngay, 365) / 30);
    v_ngay  := MOD(MOD(v_con_lai_ngay, 365), 30);

    RETURN YMD_OBJ(v_nam, v_thang, v_ngay);

EXCEPTION
    WHEN OTHERS THEN RETURN YMD_OBJ(0, 0, 0);
END FN_TINH_CON_LAI;






/
--------------------------------------------------------
--  DDL for Function FN_TINH_NGAY_HET_HAN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_NGAY_HET_HAN" (
    p_day   NUMBER,
    p_month NUMBER,
    p_year  NUMBER
)
RETURN DATE
IS
    v_day   NUMBER := p_day;
    v_month NUMBER := p_month;
    v_year  NUMBER := p_year;

    v_date  DATE;
    v_days  NUMBER;
    v_total NUMBER := 0;
BEGIN

    -- chu?n hóa month > 12
    IF v_month > 12 THEN
        v_year  := v_year + FLOOR((v_month-1)/12);
        v_month := MOD(v_month-1,12) + 1;
    END IF;

    -- x? lý tháng âm
    IF v_month < 0 THEN

        FOR i IN 1 .. ABS(v_month) LOOP

            v_total :=
                v_total +
                EXTRACT(
                    DAY FROM LAST_DAY(
                        ADD_MONTHS(
                            TO_DATE('01/12/'||(v_year-1),'DD/MM/YYYY'),
                            -(i-1)
                        )
                    )
                );

        END LOOP;

        v_day := v_day - v_total;

        v_month := 1;

    END IF;

    v_date := TO_DATE('01/'||v_month||'/'||v_year,'DD/MM/YYYY');

    -- x? lý day âm
    WHILE v_day <= 0 LOOP

        v_date := ADD_MONTHS(v_date,-1);

        v_days := EXTRACT(DAY FROM LAST_DAY(v_date));

        v_day := v_day + v_days;

    END LOOP;

    -- x? lý day d??ng v??t tháng
    LOOP

        v_days := EXTRACT(DAY FROM LAST_DAY(v_date));

        EXIT WHEN v_day <= v_days;

        v_day := v_day - v_days;

        v_date := ADD_MONTHS(v_date,1);

    END LOOP;

    RETURN v_date + (v_day-1);

END;





