  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_SO_LAN_TAM_DINH_CHI" (p_id_pham_nhan IN NUMBER) RETURN NUMBER IS
  v_count NUMBER := 0;
BEGIN
  IF p_id_pham_nhan IS NULL THEN RETURN 0; END IF;
  SELECT COUNT(*)
    INTO v_count
    FROM QLPN.TAM_DINH_CHIS tdc
   WHERE tdc.PHAM_NHAN_ID = p_id_pham_nhan
     AND NVL(tdc.IS_DELETED, 0) = 0
     AND tdc.NGAY_LAI IS NOT NULL;
  RETURN v_count;
EXCEPTION
  WHEN OTHERS THEN RETURN 0;
END FN_TINH_SO_LAN_TAM_DINH_CHI;





