/
--------------------------------------------------------
--  DDL for Function FN_TINH_SO_QUY_LIEN_KE_THEO_NGAY
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_SO_QUY_LIEN_KE_THEO_NGAY" (
    p_pham_nhan_id IN NUMBER,
    p_ngay_xet     IN DATE
)
RETURN NUMBER
IS
    v_so_quy_lien_ke NUMBER := 0;
    v_nam_quy        NUMBER;
    v_quy_xet        NUMBER;
    v_thang          NUMBER;
    v_nam            NUMBER;
BEGIN
    v_thang := EXTRACT(MONTH FROM p_ngay_xet);
    v_nam   := EXTRACT(YEAR  FROM p_ngay_xet);

    SELECT CASE
        WHEN v_thang IN (12, 1, 2)  THEN 1
        WHEN v_thang IN (3,  4, 5)  THEN 2
        WHEN v_thang IN (6,  7, 8)  THEN 3
        WHEN v_thang IN (9, 10, 11) THEN 4
    END INTO v_quy_xet FROM DUAL;

    SELECT CASE WHEN v_thang = 12 THEN v_nam + 1 ELSE v_nam END
    INTO v_nam_quy FROM DUAL;

    SELECT NVL(COUNT(*), 0)
    INTO v_so_quy_lien_ke
    FROM (
        SELECT nam_quy, quy, is_kha_tot,
               ROW_NUMBER() OVER (ORDER BY nam_quy DESC, quy DESC) AS rn
        FROM (
            -- Q1: bao g?m c? NULL (is_kha_tot = 0 n?u không có x?p lo?i)
            SELECT xl.XEP_LOAI_NAM AS nam_quy, 1 AS quy,
                CASE
                    WHEN xl.XEP_LOAI_QUY_I IS NULL THEN 0  -- ? NULL ? coi là không ??t
                    WHEN xl.XEP_LOAI_QUY_I IN (
                        SELECT ID FROM DM_XEP_LOAI_CAI_TAOS
                        WHERE XLCT_TEN IN (TO_NCHAR('Khá'), TO_NCHAR('T?t'))
                          AND NVL(IS_DELETED, 0) = 0
                    ) THEN 1
                    ELSE 0
                END AS is_kha_tot
            FROM XEP_LOAIS xl
            WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id
              AND NVL(xl.IS_DELETED, 0) = 0
              -- ? B? ?i?u ki?n XEP_LOAI_QUY_I IS NOT NULL
              AND (   xl.XEP_LOAI_NAM < v_nam_quy
                   OR (xl.XEP_LOAI_NAM = v_nam_quy AND 1 < v_quy_xet))

            UNION ALL

            SELECT xl.XEP_LOAI_NAM, 2,
                CASE
                    WHEN xl.XEP_LOAI_QUY_II IS NULL THEN 0
                    WHEN xl.XEP_LOAI_QUY_II IN (
                        SELECT ID FROM DM_XEP_LOAI_CAI_TAOS
                        WHERE XLCT_TEN IN (TO_NCHAR('Khá'), TO_NCHAR('T?t'))
                          AND NVL(IS_DELETED, 0) = 0
                    ) THEN 1
                    ELSE 0
                END
            FROM XEP_LOAIS xl
            WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id
              AND NVL(xl.IS_DELETED, 0) = 0
              AND (   xl.XEP_LOAI_NAM < v_nam_quy
                   OR (xl.XEP_LOAI_NAM = v_nam_quy AND 2 < v_quy_xet))

            UNION ALL

            SELECT xl.XEP_LOAI_NAM, 3,
                CASE
                    WHEN xl.XEP_LOAI_QUY_III IS NULL THEN 0
                    WHEN xl.XEP_LOAI_QUY_III IN (
                        SELECT ID FROM DM_XEP_LOAI_CAI_TAOS
                        WHERE XLCT_TEN IN (TO_NCHAR('Khá'), TO_NCHAR('T?t'))
                          AND NVL(IS_DELETED, 0) = 0
                    ) THEN 1
                    ELSE 0
                END
            FROM XEP_LOAIS xl
            WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id
              AND NVL(xl.IS_DELETED, 0) = 0
              AND (   xl.XEP_LOAI_NAM < v_nam_quy
                   OR (xl.XEP_LOAI_NAM = v_nam_quy AND 3 < v_quy_xet))

            UNION ALL

            SELECT xl.XEP_LOAI_NAM, 4,
                CASE
                    WHEN xl.XEP_LOAI_QUY_IV IS NULL THEN 0
                    WHEN xl.XEP_LOAI_QUY_IV IN (
                        SELECT ID FROM DM_XEP_LOAI_CAI_TAOS
                        WHERE XLCT_TEN IN (TO_NCHAR('Khá'), TO_NCHAR('T?t'))
                          AND NVL(IS_DELETED, 0) = 0
                    ) THEN 1
                    ELSE 0
                END
            FROM XEP_LOAIS xl
            WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id
              AND NVL(xl.IS_DELETED, 0) = 0
              AND (   xl.XEP_LOAI_NAM < v_nam_quy
                   OR (xl.XEP_LOAI_NAM = v_nam_quy AND 4 < v_quy_xet))
        ) all_quy
    ) ranked
    WHERE rn <= (
        SELECT NVL(MIN(rn_break) - 1, MAX(rn))
        FROM (
            SELECT rn,
                   CASE WHEN is_kha_tot = 0 THEN rn END AS rn_break
            FROM (
                SELECT nam_quy, quy, is_kha_tot,
                       ROW_NUMBER() OVER (ORDER BY nam_quy DESC, quy DESC) AS rn
                FROM (
                    SELECT xl.XEP_LOAI_NAM AS nam_quy, 1 AS quy,
                        CASE WHEN xl.XEP_LOAI_QUY_I IS NULL THEN 0
                             WHEN xl.XEP_LOAI_QUY_I IN (
                                SELECT ID FROM DM_XEP_LOAI_CAI_TAOS
                                WHERE XLCT_TEN IN (TO_NCHAR('Khá'), TO_NCHAR('T?t'))
                                  AND NVL(IS_DELETED, 0) = 0
                             ) THEN 1 ELSE 0 END AS is_kha_tot
                    FROM XEP_LOAIS xl
                    WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id
                      AND NVL(xl.IS_DELETED, 0) = 0
                      AND (   xl.XEP_LOAI_NAM < v_nam_quy
                           OR (xl.XEP_LOAI_NAM = v_nam_quy AND 1 < v_quy_xet))
                    UNION ALL
                    SELECT xl.XEP_LOAI_NAM, 2,
                        CASE WHEN xl.XEP_LOAI_QUY_II IS NULL THEN 0
                             WHEN xl.XEP_LOAI_QUY_II IN (
                                SELECT ID FROM DM_XEP_LOAI_CAI_TAOS
                                WHERE XLCT_TEN IN (TO_NCHAR('Khá'), TO_NCHAR('T?t'))
                                  AND NVL(IS_DELETED, 0) = 0
                             ) THEN 1 ELSE 0 END
                    FROM XEP_LOAIS xl
                    WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id
                      AND NVL(xl.IS_DELETED, 0) = 0
                      AND (   xl.XEP_LOAI_NAM < v_nam_quy
                           OR (xl.XEP_LOAI_NAM = v_nam_quy AND 2 < v_quy_xet))
                    UNION ALL
                    SELECT xl.XEP_LOAI_NAM, 3,
                        CASE WHEN xl.XEP_LOAI_QUY_III IS NULL THEN 0
                             WHEN xl.XEP_LOAI_QUY_III IN (
                                SELECT ID FROM DM_XEP_LOAI_CAI_TAOS
                                WHERE XLCT_TEN IN (TO_NCHAR('Khá'), TO_NCHAR('T?t'))
                                  AND NVL(IS_DELETED, 0) = 0
                             ) THEN 1 ELSE 0 END
                    FROM XEP_LOAIS xl
                    WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id
                      AND NVL(xl.IS_DELETED, 0) = 0
                      AND (   xl.XEP_LOAI_NAM < v_nam_quy
                           OR (xl.XEP_LOAI_NAM = v_nam_quy AND 3 < v_quy_xet))
                    UNION ALL
                    SELECT xl.XEP_LOAI_NAM, 4,
                        CASE WHEN xl.XEP_LOAI_QUY_IV IS NULL THEN 0
                             WHEN xl.XEP_LOAI_QUY_IV IN (
                                SELECT ID FROM DM_XEP_LOAI_CAI_TAOS
                                WHERE XLCT_TEN IN (TO_NCHAR('Khá'), TO_NCHAR('T?t'))
                                  AND NVL(IS_DELETED, 0) = 0
                             ) THEN 1 ELSE 0 END
                    FROM XEP_LOAIS xl
                    WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id
                      AND NVL(xl.IS_DELETED, 0) = 0
                      AND (   xl.XEP_LOAI_NAM < v_nam_quy
                           OR (xl.XEP_LOAI_NAM = v_nam_quy AND 4 < v_quy_xet))
                ) all_quy
            ) ranked2
        )
    )
    AND is_kha_tot = 1;

    RETURN v_so_quy_lien_ke;

EXCEPTION
    WHEN OTHERS THEN RETURN 0;
END FN_TINH_SO_QUY_LIEN_KE_THEO_NGAY;





/
--------------------------------------------------------
--  DDL for Function FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT" (
    p_PHAM_NHAN_ID IN NUMBER,
    p_NGAY_XET     IN DATE DEFAULT SYSDATE
) RETURN QUY_KHA_TOT_OBJ
IS
    v_so_quy      NUMBER := 0;
    v_cac_quy     NVARCHAR2(4000);
    v_nam_xet     NUMBER;
    v_thang_xet   NUMBER;
BEGIN
    v_nam_xet   := EXTRACT(YEAR  FROM p_NGAY_XET);
    v_thang_xet := EXTRACT(MONTH FROM p_NGAY_XET);

    SELECT
        NVL(COUNT(*), 0),
        NVL(LISTAGG(nam || u'-Q' || quy, u', ') WITHIN GROUP (ORDER BY nam, quy), u'')
    INTO v_so_quy, v_cac_quy
    FROM (
        -- Sinh toàn b? (n?m, quý) ?ã k?t thúc tính ??n p_NGAY_XET (20 n?m tr? l?i)
        SELECT g.nam, g.quy,
            CASE WHEN (
                (g.quy = 1 AND xl.XEP_LOAI_QUY_I   IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED,0)=0))
             OR (g.quy = 2 AND xl.XEP_LOAI_QUY_II  IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED,0)=0))
             OR (g.quy = 3 AND xl.XEP_LOAI_QUY_III IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED,0)=0))
             OR (g.quy = 4 AND xl.XEP_LOAI_QUY_IV  IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED,0)=0))
            ) THEN 1 ELSE 0 END AS is_kha_tot
        FROM (
            -- L??i (nam x quy) ch? l?y quý ?ã k?t thúc — logic gi?ng hàm li?n k?
            SELECT y.nam, qrv.q AS quy
            FROM (
                SELECT v_nam_xet - 20 + LEVEL AS nam
                FROM DUAL CONNECT BY LEVEL <= 20
            ) y
            CROSS JOIN (
                SELECT 1 AS q FROM DUAL UNION ALL
                SELECT 2      FROM DUAL UNION ALL
                SELECT 3      FROM DUAL UNION ALL
                SELECT 4      FROM DUAL
            ) qrv
            WHERE y.nam <= v_nam_xet
              AND (
                  y.nam < v_nam_xet
               OR (y.nam = v_nam_xet AND (
                      (qrv.q = 1 AND v_thang_xet >= 3)
                   OR (qrv.q = 2 AND v_thang_xet >= 6)
                   OR (qrv.q = 3 AND v_thang_xet >= 9)
                   OR (qrv.q = 4 AND v_thang_xet >= 12)
                  ))
              )
        ) g
        LEFT JOIN XEP_LOAIS xl
            ON  xl.XEP_LOAI_NAM   = g.nam
            AND xl.PHAM_NHAN_ID   = p_PHAM_NHAN_ID
            AND NVL(xl.IS_DELETED, 0) = 0
    ) u
    WHERE u.is_kha_tot = 1;

    RETURN QUY_KHA_TOT_OBJ(v_so_quy, v_cac_quy);

EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN QUY_KHA_TOT_OBJ(0, NULL);
    WHEN OTHERS        THEN RETURN QUY_KHA_TOT_OBJ(NULL, NULL);
END;


/
--------------------------------------------------------
--  DDL for Function FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC" (
    p_PHAM_NHAN_ID IN NUMBER,
    p_NAM          IN NUMBER DEFAULT NULL  -- NULL: xét t?t c? các n?m
) RETURN QUY_KHA_TOT_OBJ
IS
    v_so_quy_lt   NUMBER := 0;
    v_cac_quy     NVARCHAR2(4000);
BEGIN
    -- S? quý liên t?c dài nh?t 
    SELECT NVL(MAX(cnt), 0)
    INTO v_so_quy_lt
    FROM (
        SELECT grp, COUNT(*) AS cnt
        FROM (
            SELECT nam, quy, is_kha_tot,
                ROW_NUMBER() OVER (ORDER BY nam, quy) - SUM(is_kha_tot) OVER (ORDER BY nam, quy) AS grp
            FROM (
                SELECT nam, quy,
                    CASE WHEN xep_loai_id IN (SELECT id FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0) THEN 1 ELSE 0 END AS is_kha_tot
                FROM (
                    SELECT xep_loai_nam AS nam, 1 AS quy, xep_loai_quy_i AS xep_loai_id FROM XEP_LOAIS WHERE PHAM_NHAN_ID = p_PHAM_NHAN_ID AND NVL(IS_DELETED, 0) = 0 AND (p_NAM IS NULL OR xep_loai_nam = p_NAM)
                    UNION ALL
                    SELECT xep_loai_nam, 2, xep_loai_quy_ii FROM XEP_LOAIS WHERE PHAM_NHAN_ID = p_PHAM_NHAN_ID AND NVL(IS_DELETED, 0) = 0 AND (p_NAM IS NULL OR xep_loai_nam = p_NAM)
                    UNION ALL
                    SELECT xep_loai_nam, 3, xep_loai_quy_iii FROM XEP_LOAIS WHERE PHAM_NHAN_ID = p_PHAM_NHAN_ID AND NVL(IS_DELETED, 0) = 0 AND (p_NAM IS NULL OR xep_loai_nam = p_NAM)
                    UNION ALL
                    SELECT xep_loai_nam, 4, xep_loai_quy_iv FROM XEP_LOAIS WHERE PHAM_NHAN_ID = p_PHAM_NHAN_ID AND NVL(IS_DELETED, 0) = 0 AND (p_NAM IS NULL OR xep_loai_nam = p_NAM)
                ) u
            ) t
        ) t2
        WHERE is_kha_tot = 1
        GROUP BY grp
    );

    -- Danh sách các quý ??t Khá/T?t (theo th? t? th?i gian)
    BEGIN
        SELECT NVL(LISTAGG(nam || u'-Q' || quy, u', ') WITHIN GROUP (ORDER BY nam, quy), u'')
        INTO v_cac_quy
        FROM (
            SELECT xep_loai_nam AS nam, 1 AS quy,
                CASE WHEN xep_loai_quy_i IN (SELECT id FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0) THEN 1 ELSE 0 END AS is_kha_tot
            FROM XEP_LOAIS WHERE PHAM_NHAN_ID = p_PHAM_NHAN_ID AND NVL(IS_DELETED, 0) = 0 AND (p_NAM IS NULL OR xep_loai_nam = p_NAM)
            UNION ALL
            SELECT xep_loai_nam, 2, CASE WHEN xep_loai_quy_ii IN (SELECT id FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0) THEN 1 ELSE 0 END FROM XEP_LOAIS WHERE PHAM_NHAN_ID = p_PHAM_NHAN_ID AND NVL(IS_DELETED, 0) = 0 AND (p_NAM IS NULL OR xep_loai_nam = p_NAM)
            UNION ALL
            SELECT xep_loai_nam, 3, CASE WHEN xep_loai_quy_iii IN (SELECT id FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0) THEN 1 ELSE 0 END FROM XEP_LOAIS WHERE PHAM_NHAN_ID = p_PHAM_NHAN_ID AND NVL(IS_DELETED, 0) = 0 AND (p_NAM IS NULL OR xep_loai_nam = p_NAM)
            UNION ALL
            SELECT xep_loai_nam, 4, CASE WHEN xep_loai_quy_iv IN (SELECT id FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0) THEN 1 ELSE 0 END FROM XEP_LOAIS WHERE PHAM_NHAN_ID = p_PHAM_NHAN_ID AND NVL(IS_DELETED, 0) = 0 AND (p_NAM IS NULL OR xep_loai_nam = p_NAM)
        ) u
        WHERE u.is_kha_tot = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_cac_quy := NULL;
    END;

    RETURN QUY_KHA_TOT_OBJ(v_so_quy_lt, v_cac_quy);
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN QUY_KHA_TOT_OBJ(0, NULL);
    WHEN OTHERS THEN
        RETURN QUY_KHA_TOT_OBJ(NULL, NULL);
END;




/
--------------------------------------------------------
--  DDL for Function FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC_LIEN_KE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC_LIEN_KE" (
    p_pham_nhan_id IN NUMBER,
    p_ngay_xet     IN DATE
)
RETURN NUMBER
IS
    v_so_quy_lien_ke NUMBER := 0;
    v_nam_xet        NUMBER;
    v_thang_xet      NUMBER;
    v_quy_gan_nhat   NUMBER := 0;
BEGIN
    -- Xác ??nh n?m và tháng c?a ngày xét
    v_nam_xet   := EXTRACT(YEAR FROM p_ngay_xet);
    v_thang_xet := EXTRACT(MONTH FROM p_ngay_xet);

    -- ??nh ngh?a quý: Q1=12(n?m tr??c)+1+2, Q2=3+4+5, Q3=6+7+8, Q4=9+10+11
    -- Quý ?ã k?t thúc khi p_ngay_xet >= ngày ??u tháng sau quý:
    --   Q1 k?t thúc 28/2 -> ?ã có x?p lo?i khi tháng >= 3 (vd: xét 15/3 ?ã có Q1)
    --   Q2 k?t thúc 31/5 -> tháng >= 6
    --   Q3 k?t thúc 31/8 -> tháng >= 9
    --   Q4 k?t thúc 30/11 -> tháng >= 12
    -- S? quý Khá/T?t li?n k?: ch? tính quý ?ã k?t thúc
    -- N?u quý g?n nh?t ?ã k?t thúc không có x?p lo?i ho?c không Khá/T?t thì tr? v? 0
    -- Ki?m tra quý g?n nh?t ?ã k?t thúc: tháng 1,2->Q4 n?m tr??c; 3-5->Q1; 6-8->Q2; 9-11->Q3; 12->Q4
    IF v_thang_xet IN (1, 2) THEN
        SELECT NVL(COUNT(*), 0) INTO v_quy_gan_nhat FROM XEP_LOAIS xl
        WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(xl.IS_DELETED, 0) = 0
          AND xl.XEP_LOAI_NAM = v_nam_xet - 1 AND xl.XEP_LOAI_QUY_IV IS NOT NULL
          AND xl.XEP_LOAI_QUY_IV IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0);
    ELSIF v_thang_xet IN (3, 4, 5) THEN
        SELECT NVL(COUNT(*), 0) INTO v_quy_gan_nhat FROM XEP_LOAIS xl
        WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(xl.IS_DELETED, 0) = 0
          AND xl.XEP_LOAI_NAM = v_nam_xet AND xl.XEP_LOAI_QUY_I IS NOT NULL
          AND xl.XEP_LOAI_QUY_I IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0);
    ELSIF v_thang_xet IN (6, 7, 8) THEN
        SELECT NVL(COUNT(*), 0) INTO v_quy_gan_nhat FROM XEP_LOAIS xl
        WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(xl.IS_DELETED, 0) = 0
          AND xl.XEP_LOAI_NAM = v_nam_xet AND xl.XEP_LOAI_QUY_II IS NOT NULL
          AND xl.XEP_LOAI_QUY_II IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0);
    ELSIF v_thang_xet IN (9, 10, 11) THEN
        SELECT NVL(COUNT(*), 0) INTO v_quy_gan_nhat FROM XEP_LOAIS xl
        WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(xl.IS_DELETED, 0) = 0
          AND xl.XEP_LOAI_NAM = v_nam_xet AND xl.XEP_LOAI_QUY_III IS NOT NULL
          AND xl.XEP_LOAI_QUY_III IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0);
    ELSE
        -- tháng 12: Q4 n?m hi?n t?i
        SELECT NVL(COUNT(*), 0) INTO v_quy_gan_nhat FROM XEP_LOAIS xl
        WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(xl.IS_DELETED, 0) = 0
          AND xl.XEP_LOAI_NAM = v_nam_xet AND xl.XEP_LOAI_QUY_IV IS NOT NULL
          AND xl.XEP_LOAI_QUY_IV IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0);
    END IF;
    IF v_quy_gan_nhat = 0 THEN RETURN 0; END IF;

    -- Bao g?m T?T C? quý ?ã k?t thúc; quý null/không có d? li?u = is_kha_tot 0 (ng?t chu?i)
    SELECT NVL(COUNT(*), 0)
    INTO v_so_quy_lien_ke
    FROM (
        SELECT nam, quy, is_kha_tot,
               ROW_NUMBER() OVER (ORDER BY nam DESC, quy DESC) AS rn,
               ROW_NUMBER() OVER (ORDER BY nam DESC, quy DESC)
                 - SUM(is_kha_tot) OVER (ORDER BY nam DESC, quy DESC) AS grp
        FROM (
            SELECT g.nam, g.quy,
                CASE WHEN (
                    (g.quy = 1 AND xl.XEP_LOAI_QUY_I IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0))
                    OR (g.quy = 2 AND xl.XEP_LOAI_QUY_II IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0))
                    OR (g.quy = 3 AND xl.XEP_LOAI_QUY_III IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0))
                    OR (g.quy = 4 AND xl.XEP_LOAI_QUY_IV IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0))
                ) THEN 1 ELSE 0 END AS is_kha_tot
            FROM (
                SELECT y.nam, qrv.q AS quy
                FROM (SELECT v_nam_xet - 20 + LEVEL AS nam FROM DUAL CONNECT BY LEVEL <= 20) y
                CROSS JOIN (SELECT 1 AS q FROM DUAL UNION ALL SELECT 2 FROM DUAL UNION ALL SELECT 3 FROM DUAL UNION ALL SELECT 4 FROM DUAL) qrv
                WHERE y.nam <= v_nam_xet
                  AND (y.nam < v_nam_xet OR (y.nam = v_nam_xet AND (
                    (qrv.q = 1 AND v_thang_xet >= 3) OR (qrv.q = 2 AND v_thang_xet >= 6)
                    OR (qrv.q = 3 AND v_thang_xet >= 9) OR (qrv.q = 4 AND v_thang_xet >= 12)
                  )))
            ) g
            LEFT JOIN XEP_LOAIS xl
                ON xl.XEP_LOAI_NAM = g.nam AND xl.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(xl.IS_DELETED, 0) = 0
        ) all_quy
    ) ranked
    WHERE is_kha_tot = 1
      AND grp = (SELECT r2.grp FROM (
          SELECT nam, quy, is_kha_tot,
                 ROW_NUMBER() OVER (ORDER BY nam DESC, quy DESC) AS rn,
                 ROW_NUMBER() OVER (ORDER BY nam DESC, quy DESC)
                   - SUM(is_kha_tot) OVER (ORDER BY nam DESC, quy DESC) AS grp
          FROM (
            SELECT g.nam, g.quy,
                CASE WHEN (
                    (g.quy = 1 AND xl.XEP_LOAI_QUY_I IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0))
                    OR (g.quy = 2 AND xl.XEP_LOAI_QUY_II IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0))
                    OR (g.quy = 3 AND xl.XEP_LOAI_QUY_III IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0))
                    OR (g.quy = 4 AND xl.XEP_LOAI_QUY_IV IN (SELECT ID FROM DM_XEP_LOAI_CAI_TAOS WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') AND NVL(IS_DELETED, 0) = 0))
                ) THEN 1 ELSE 0 END AS is_kha_tot
            FROM (
                SELECT y.nam, qrv.q AS quy
                FROM (SELECT v_nam_xet - 20 + LEVEL AS nam FROM DUAL CONNECT BY LEVEL <= 20) y
                CROSS JOIN (SELECT 1 AS q FROM DUAL UNION ALL SELECT 2 FROM DUAL UNION ALL SELECT 3 FROM DUAL UNION ALL SELECT 4 FROM DUAL) qrv
                WHERE y.nam <= v_nam_xet
                  AND (y.nam < v_nam_xet OR (y.nam = v_nam_xet AND (
                    (qrv.q = 1 AND v_thang_xet >= 3) OR (qrv.q = 2 AND v_thang_xet >= 6)
                    OR (qrv.q = 3 AND v_thang_xet >= 9) OR (qrv.q = 4 AND v_thang_xet >= 12)
                  )))
            ) g
            LEFT JOIN XEP_LOAIS xl
                ON xl.XEP_LOAI_NAM = g.nam AND xl.PHAM_NHAN_ID = p_pham_nhan_id AND NVL(xl.IS_DELETED, 0) = 0
        ) a2
      ) r2 WHERE r2.rn = 1 AND r2.is_kha_tot = 1);

    RETURN v_so_quy_lien_ke;

EXCEPTION
    WHEN OTHERS THEN RETURN 0;
END FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC_LIEN_KE;







/
--------------------------------------------------------
--  DDL for Function FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC_LIEN_KE_PHI_TEST
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC_LIEN_KE_PHI_TEST" (
    p_pham_nhan_id IN NUMBER,
    p_ngay_xet     IN DATE
) RETURN NUMBER
IS
    v_so_quy_lien_ke NUMBER := 0; 
    v_nam_xet        NUMBER;
    v_thang_xet      NUMBER;
    v_quy_gan_nhat   NUMBER := 0;

    TYPE t_ids IS TABLE OF NUMBER;
    v_khatot_ids t_ids;

BEGIN
    v_nam_xet   := EXTRACT(YEAR FROM p_ngay_xet);
    v_thang_xet := EXTRACT(MONTH FROM p_ngay_xet);

    -- Cache danh sách ID Khá / T?t
    SELECT ID 
      BULK COLLECT INTO v_khatot_ids
      FROM DM_XEP_LOAI_CAI_TAOS 
     WHERE XLCT_TEN IN (u'Kh\00e1', u'T\1ed1t') 
       AND NVL(IS_DELETED, 0) = 0;

    -- 1. Ki?m tra quý g?n nh?t có Khá/T?t không
    IF v_thang_xet IN (1, 2) THEN
        SELECT COUNT(*) INTO v_quy_gan_nhat
        FROM XEP_LOAIS xl
        WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id 
          AND NVL(xl.IS_DELETED,0) = 0
          AND xl.XEP_LOAI_NAM = v_nam_xet - 1
          AND xl.XEP_LOAI_QUY_IV IN (SELECT COLUMN_VALUE FROM TABLE(v_khatot_ids));

    ELSIF v_thang_xet IN (3, 4, 5) THEN
        SELECT COUNT(*) INTO v_quy_gan_nhat
        FROM XEP_LOAIS xl
        WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id 
          AND NVL(xl.IS_DELETED,0)=0
          AND xl.XEP_LOAI_NAM = v_nam_xet 
          AND xl.XEP_LOAI_QUY_I IN (SELECT COLUMN_VALUE FROM TABLE(v_khatot_ids));

    ELSIF v_thang_xet IN (6, 7, 8) THEN
        SELECT COUNT(*) INTO v_quy_gan_nhat
        FROM XEP_LOAIS xl
        WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id 
          AND NVL(xl.IS_DELETED,0)=0
          AND xl.XEP_LOAI_NAM = v_nam_xet 
          AND xl.XEP_LOAI_QUY_II IN (SELECT COLUMN_VALUE FROM TABLE(v_khatot_ids));

    ELSIF v_thang_xet IN (9, 10, 11) THEN
        SELECT COUNT(*) INTO v_quy_gan_nhat
        FROM XEP_LOAIS xl
        WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id 
          AND NVL(xl.IS_DELETED,0)=0
          AND xl.XEP_LOAI_NAM = v_nam_xet 
          AND xl.XEP_LOAI_QUY_III IN (SELECT COLUMN_VALUE FROM TABLE(v_khatot_ids));

    ELSE -- tháng 12
        SELECT COUNT(*) INTO v_quy_gan_nhat
        FROM XEP_LOAIS xl
        WHERE xl.PHAM_NHAN_ID = p_pham_nhan_id 
          AND NVL(xl.IS_DELETED,0)=0
          AND xl.XEP_LOAI_NAM = v_nam_xet 
          AND xl.XEP_LOAI_QUY_IV IN (SELECT COLUMN_VALUE FROM TABLE(v_khatot_ids));
    END IF;

    IF v_quy_gan_nhat = 0 THEN 
        RETURN 0; 
    END IF;

    -- 2. Tính chu?i quý li?n k? Khá/T?t
    WITH quy_da_ket_thuc AS (
        SELECT 
            g.nam,
            g.quy,
            CASE 
                WHEN g.quy = 1 AND xl.XEP_LOAI_QUY_I   IN (SELECT COLUMN_VALUE FROM TABLE(v_khatot_ids)) THEN 1
                WHEN g.quy = 2 AND xl.XEP_LOAI_QUY_II  IN (SELECT COLUMN_VALUE FROM TABLE(v_khatot_ids)) THEN 1
                WHEN g.quy = 3 AND xl.XEP_LOAI_QUY_III IN (SELECT COLUMN_VALUE FROM TABLE(v_khatot_ids)) THEN 1
                WHEN g.quy = 4 AND xl.XEP_LOAI_QUY_IV  IN (SELECT COLUMN_VALUE FROM TABLE(v_khatot_ids)) THEN 1
                ELSE 0 
            END AS is_kha_tot
        FROM (
            SELECT y.nam, q.q AS quy
            FROM (SELECT v_nam_xet - 30 + LEVEL AS nam FROM DUAL CONNECT BY LEVEL <= 30) y,
                 (SELECT 1 AS q FROM DUAL 
                  UNION ALL SELECT 2 
                  UNION ALL SELECT 3 
                  UNION ALL SELECT 4) q
            WHERE y.nam <= v_nam_xet
              AND ( y.nam < v_nam_xet 
                 OR (y.nam = v_nam_xet AND (
                       (q.q = 1 AND v_thang_xet >= 3) OR 
                       (q.q = 2 AND v_thang_xet >= 6) OR 
                       (q.q = 3 AND v_thang_xet >= 9) OR 
                       (q.q = 4 AND v_thang_xet >= 12))))
        ) g
        LEFT JOIN XEP_LOAIS xl 
          ON xl.XEP_LOAI_NAM = g.nam 
         AND xl.PHAM_NHAN_ID = p_pham_nhan_id 
         AND NVL(xl.IS_DELETED, 0) = 0
    )
    SELECT COUNT(*) 
      INTO v_so_quy_lien_ke
    FROM (
        SELECT is_kha_tot,
               ROW_NUMBER() OVER (ORDER BY nam DESC, quy DESC) 
                 - SUM(is_kha_tot) OVER (ORDER BY nam DESC, quy DESC) AS grp
        FROM quy_da_ket_thuc
    ) t
    WHERE is_kha_tot = 1 
      AND grp = (SELECT grp 
                   FROM (SELECT 
                            ROW_NUMBER() OVER (ORDER BY nam DESC, quy DESC) AS rn,
                            ROW_NUMBER() OVER (ORDER BY nam DESC, quy DESC) 
                              - SUM(is_kha_tot) OVER (ORDER BY nam DESC, quy DESC) AS grp
                         FROM quy_da_ket_thuc)
                  WHERE rn = 1 AND is_kha_tot = 1);

    RETURN NVL(v_so_quy_lien_ke, 0);

EXCEPTION
    WHEN OTHERS THEN RETURN 0;
END;





/
--------------------------------------------------------
--  DDL for Function FN_TINH_SO_QUY_YEU_CAU
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_SO_QUY_YEU_CAU" (
    p_pham_nhan_id IN NUMBER,
    p_ky_giam_id   IN NUMBER
) RETURN SO_QUY_YEU_CAU_OBJ
IS
    v_dieu_kien_id          NUMBER;

    -- S? quý base theo m?c án t? GTH_XEP_LOAI_CAI_TAOS
    v_quy_lien_tuc          NUMBER := 0;
    v_quy_khong_lien_tuc    NUMBER := 0;
    v_quy_truong_hop_db     NUMBER := 0;
    v_quy_lien_ke_yc        NUMBER := 0;

    -- H? s? ti?n án
    v_he_so_tren3           NUMBER := 0;
    v_he_so_duoi3           NUMBER := 0;

    v_da_giam_quy_lien_ke        NUMBER := 0;  -- khai báo thêm ? ??u function
    v_da_giam_quy_khong_lien_tuc NUMBER := 0;  -- khai báo thêm ? ??u function
    v_so_lan_giam                NUMBER := 0;  -- khai báo thêm ? ??u function


    -- Thông tin ph?m nhân
    v_tong_tien_an          NUMBER := 0;
    v_tong_ngay_an          NUMBER := 0;
    v_an_phat               NVARCHAR2(500);
    v_muc_an_text           NVARCHAR2(255);

    -- Ph?n c?ng thêm ti?n án
    v_cong_them_tien_an     NUMBER := 0;

    -- K?t qu?
    v_yc_lien_tuc           NUMBER := 0;
    v_yc_khong_lien_tuc     NUMBER := 0;
    v_yc_truong_hop_db      NUMBER := 0;
    v_yc_lien_ke            NUMBER := 0;
BEGIN
    -- 1. L?y ID ?i?u ki?n t? k? gi?m
    BEGIN
        SELECT ID
        INTO v_dieu_kien_id
        FROM GTH_DIEU_KIEN_GIAM_THOI_HANS
        WHERE GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
          AND IS_DELETED = 0
          AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN SO_QUY_YEU_CAU_OBJ(0, 0, 0, 0);
    END;

    -- 2. L?y án ph?t ? t?ng ngày
    BEGIN
        SELECT ptha.THA_AN_PHAT
        INTO v_an_phat
        FROM PN_THI_HANH_AN ptha
        WHERE ptha.THA_PNLAI_LICH_ID = p_pham_nhan_id
          AND NVL(ptha.IS_DELETED, 0) = 0
          AND ROWNUM = 1;
        v_tong_ngay_an := FN_PARSE_AN_PHAT_TO_NGAY(v_an_phat);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN v_tong_ngay_an := 0;
    END;

-- 3. Xác ??nh m?c án text
	DECLARE
	    v_muc_an_id NUMBER;
	BEGIN
	    v_muc_an_id := QLPN.FN_GET_MUC_AN_ID_GTH(v_an_phat);  -- ? dùng bi?n ?ã có

	    BEGIN
	        SELECT XLCT_MUC_AN
	        INTO v_muc_an_text
	        FROM GTH_XEP_LOAI_CAI_TAOS
	        WHERE GTH_DIEU_KIEN_GIAM_THOI_HAN_ID = v_dieu_kien_id
	          AND IS_DELETED = 0
	          AND (
	              (v_muc_an_id = 6 AND UPPER(XLCT_MUC_AN) LIKE '%20 - 30%')
	           OR (v_muc_an_id = 5 AND UPPER(XLCT_MUC_AN) LIKE '%15 - 20%')
	           OR (v_muc_an_id = 4 AND UPPER(XLCT_MUC_AN) LIKE '%10 - 15%')
	           OR (v_muc_an_id = 3 AND UPPER(XLCT_MUC_AN) LIKE '%5 - 10%')
	           OR (v_muc_an_id = 2 AND UPPER(XLCT_MUC_AN) LIKE '%3 - 5%')
	           OR (v_muc_an_id = 7 AND UPPER(XLCT_MUC_AN) LIKE '%CHUNG TH%N')
	           OR (v_muc_an_id = 1 AND UPPER(XLCT_MUC_AN) LIKE '%D%I 3%')
	           OR (v_muc_an_id IS NULL 
	               AND UPPER(v_an_phat) LIKE '%CHUNG TH%N%GI%M%'
	               AND UPPER(XLCT_MUC_AN) LIKE '%GI%M T%H%NH%')
	          )
	          AND ROWNUM = 1;
	    EXCEPTION
	        WHEN NO_DATA_FOUND THEN v_muc_an_text := NULL;
	    END;
	END;

    -- 4. L?y s? quý base t? GTH_XEP_LOAI_CAI_TAOS theo m?c án
    IF v_muc_an_text IS NOT NULL THEN
        BEGIN
            SELECT
                NVL(XLCT_XEP_LOAI_LIEN_TUC,  0),
                NVL(XLCT_QUY_KHONG_LIEN_TUC,  0),
                NVL(XLCT_QUY_LIEN_TUC,        0),
                NVL(XLCT_TRUONG_HOP_DAC_BIET, 0)
            INTO
                v_quy_lien_tuc,
                v_quy_khong_lien_tuc,
                v_quy_lien_ke_yc,
                v_quy_truong_hop_db
            FROM GTH_XEP_LOAI_CAI_TAOS
            WHERE GTH_DIEU_KIEN_GIAM_THOI_HAN_ID = v_dieu_kien_id
              AND UPPER(XLCT_MUC_AN) = UPPER(v_muc_an_text)  -- ? dùng UPPER ?? tránh collation
              AND IS_DELETED = 0
              AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                v_quy_lien_tuc       := 0;
                v_quy_khong_lien_tuc := 0;
                v_quy_lien_ke_yc     := 0;
                v_quy_truong_hop_db  := 0;
        END;
    END IF;

    -- 5. L?y h? s? ti?n án t? GTH_DIEU_KIEN_GIAM_THOI_HANS
--- 5. L?y h? s? ti?n án + h? s? ?ã gi?m
    BEGIN
        SELECT
            NVL(DKGTH_HE_SO_AN_TREN3_NAM,             0),
            NVL(DKGTH_HE_SO_AN_DUOI3_NAM,             0),
            NVL(DKGTH_TH_DA_GIAM_QUY_LIEN_KE,         0),
            NVL(DKGTH_TH_DA_GIAM_QUY_KHONG_LIEN_TUC,  0)
          INTO
            v_he_so_tren3,
            v_he_so_duoi3,
            v_da_giam_quy_lien_ke,
            v_da_giam_quy_khong_lien_tuc
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS
         WHERE ID = v_dieu_kien_id
           AND IS_DELETED = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN SO_QUY_YEU_CAU_OBJ(0, 0, 0, 0);
    END;

    -- 6. L?y t?ng ti?n án
    BEGIN
        SELECT pll.LL_SO_TIEN_AN
          INTO v_tong_tien_an
          FROM PN_LAI_LICHS pll
         WHERE pll.ID = p_pham_nhan_id
           AND NVL(IS_DELETED, 0) = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN v_tong_tien_an := 0;
    END;

    -- 7. Ki?m tra ?ã t?ng gi?m
    SELECT COUNT(*) INTO v_so_lan_giam
      FROM GIAM_THOI_HANS
     WHERE PHAM_NHAN_ID = p_pham_nhan_id
       AND IS_DELETED = 0;

    -- 8. Tính v_cong_them_tien_an
    IF v_tong_ngay_an > 0 AND v_tong_ngay_an < 3 * 365 THEN
        v_cong_them_tien_an := v_tong_tien_an * v_he_so_duoi3;
    ELSIF v_tong_ngay_an >= 3 * 365 OR v_tong_ngay_an = -1 THEN
        v_cong_them_tien_an := v_tong_tien_an * v_he_so_tren3;
    ELSE
        v_cong_them_tien_an := 0;
    END IF;

    -- 9. Gán YC sau khi ?ã có v_cong_them_tien_an
	v_yc_lien_tuc       := NVL(v_quy_lien_tuc,       0) + NVL(v_cong_them_tien_an, 0);
    v_yc_khong_lien_tuc := NVL(v_quy_khong_lien_tuc, 0) + NVL(v_cong_them_tien_an, 0);
    v_yc_truong_hop_db  := NVL(v_quy_truong_hop_db,  0) + NVL(v_cong_them_tien_an, 0);
    v_yc_lien_ke        := NVL(v_quy_lien_ke_yc,     0);

    -- 10. N?u ?ã gi?m ? l?y MAX v?i c?u hình ?ã gi?m
    IF v_so_lan_giam > 0 THEN
        v_yc_lien_tuc       := GREATEST(v_yc_lien_tuc,       v_da_giam_quy_lien_ke);
        v_yc_khong_lien_tuc := GREATEST(v_yc_khong_lien_tuc, v_da_giam_quy_khong_lien_tuc);
    END IF;

    RETURN SO_QUY_YEU_CAU_OBJ(
        v_yc_lien_tuc,
        v_yc_khong_lien_tuc,
        v_yc_truong_hop_db,
        v_yc_lien_ke
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN SO_QUY_YEU_CAU_OBJ(0, 0, 0, 0);
END FN_TINH_SO_QUY_YEU_CAU;






/
--------------------------------------------------------
--  DDL for Function FN_TINH_THOI_GIAN_CON_LAI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_THOI_GIAN_CON_LAI" (
    p_pham_nhan_id IN NUMBER,
    p_ngay_xet     IN DATE
)
RETURN NVARCHAR2
IS
    v_ngay_het_an DATE;
	v_ngay_xet	  DATE;
    v_an_phat_goc NVARCHAR2(500);
    v_an_phat_up  NVARCHAR2(500);
    v_nam         NUMBER := 0;
    v_thang       NUMBER := 0;
    v_ngay        NUMBER := 0;
    v_temp_date   DATE;
    v_result      NVARCHAR2(200);
BEGIN
	v_ngay_xet := to_date(p_ngay_xet);
    SELECT CAST(THA_NGAY_HET_HAN AS DATE), THA_AN_PHAT
      INTO v_ngay_het_an, v_an_phat_goc
      FROM PN_THI_HANH_AN 
     WHERE THA_PNLAI_LICH_ID = p_pham_nhan_id
       AND NVL(IS_DELETED, 0) = 0
       AND ROWNUM = 1;

    IF v_ngay_het_an IS NULL AND v_an_phat_goc IS NOT NULL THEN
        v_an_phat_up := UPPER(TRIM(v_an_phat_goc));

        IF v_an_phat_up LIKE '%CHUNG TH%N%'
           AND v_an_phat_up NOT LIKE '%GI%M%20%'
           AND v_an_phat_up NOT LIKE '%GI%M%30%'
        THEN
            RETURN TO_NCHAR('Chung thân');
        END IF;
    END IF;

    IF v_ngay_het_an IS NULL OR v_ngay_xet >= v_ngay_het_an THEN
        RETURN TO_NCHAR('?ã h?t án');
    END IF;

    v_nam       := FLOOR(MONTHS_BETWEEN(v_ngay_het_an, v_ngay_xet) / 12);
    v_temp_date := ADD_MONTHS(v_ngay_xet, v_nam * 12);
    v_thang     := FLOOR(MONTHS_BETWEEN(v_ngay_het_an, v_temp_date));
    v_temp_date := ADD_MONTHS(v_temp_date, v_thang);
    v_ngay      := FLOOR(v_ngay_het_an - v_temp_date);

    v_result := '';
    IF v_nam   > 0 THEN v_result := v_result || v_nam   || TO_NCHAR(' n?m ');   END IF;
    IF v_thang > 0 THEN v_result := v_result || v_thang || TO_NCHAR(' tháng '); END IF;
    IF v_ngay  > 0 THEN v_result := v_result || v_ngay  || TO_NCHAR(' ngày');   END IF;

    IF TRIM(v_result) IS NULL THEN
        RETURN TO_NCHAR('?ã h?t án');
    END IF;

    RETURN TRIM(v_result);

EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN TO_NCHAR('L?i');
    WHEN OTHERS        THEN RETURN TO_NCHAR('L?i');
END FN_TINH_THOI_GIAN_CON_LAI;




/
--------------------------------------------------------
--  DDL for Function FN_TINH_THOI_GIAN_DA_VA_CON
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_THOI_GIAN_DA_VA_CON" (
    p_PHAM_NHAN_ID IN NUMBER,
    p_AN_PHAT      IN NVARCHAR2,
    p_NGAY_XET     IN DATE,
    p_THA_NGAY_BAT IN DATE
) RETURN TG_DA_CON_OBJ
IS
    -- Án
    v_an_n NUMBER := 0;
    v_an_t NUMBER := 0;
    v_an_g NUMBER := 0;

    v_ngay_xet   DATE := NVL(p_NGAY_XET, SYSDATE);
    v_end        DATE;
    v_served_end DATE;

    -- ?ã ch?p hành
    v_da_n NUMBER := 0;
    v_da_t NUMBER := 0;
    v_da_g NUMBER := 0;

    -- Còn l?i
    v_con_n NUMBER := 0;
    v_con_t NUMBER := 0;
    v_con_g NUMBER := 0;

    FUNCTION format_ymd(n IN NUMBER, t IN NUMBER, g IN NUMBER)
        RETURN NVARCHAR2
    IS
    BEGIN
        RETURN TO_NCHAR(NVL(n,0)) || ' n?m '
             || TO_NCHAR(NVL(t,0)) || ' tháng '
             || TO_NCHAR(NVL(g,0)) || ' ngày';
    END;

    PROCEDURE diff_ymd(d1 IN DATE, d2 IN DATE,
                       y OUT NUMBER, m OUT NUMBER, d OUT NUMBER)
    IS
        v_months NUMBER;
        v_tmp    DATE;
    BEGIN
        IF d2 <= d1 THEN
            y := 0; m := 0; d := 0;
            RETURN;
        END IF;

        v_months := TRUNC(MONTHS_BETWEEN(d2, d1));

        y := TRUNC(v_months / 12);
        m := MOD(v_months, 12);

        v_tmp := ADD_MONTHS(d1, y * 12 + m);

        IF v_tmp > d2 THEN
            v_months := v_months - 1;
            y := TRUNC(v_months / 12);
            m := MOD(v_months, 12);
            v_tmp := ADD_MONTHS(d1, y * 12 + m);
        END IF;

        d := TRUNC(d2 - v_tmp);
        IF d < 0 THEN
            m := m - 1;
            IF m < 0 THEN
                y := y - 1;
                m := m + 12;
            END IF;
            v_tmp := ADD_MONTHS(d1, y * 12 + m);
            d := GREATEST(TRUNC(d2 - v_tmp), 0);
        END IF;
    END;

BEGIN
    IF p_THA_NGAY_BAT IS NULL THEN
        RETURN TG_DA_CON_OBJ('0 n?m 0 tháng 0 ngày',
                                  '0 n?m 0 tháng 0 ngày');
    END IF;

    -- Parse án
    v_an_n := NVL(FN_PARSE_THOI_GIAN_TEXT(p_AN_PHAT, 'NAM'), 0);
    v_an_t := NVL(FN_PARSE_THOI_GIAN_TEXT(p_AN_PHAT, 'THANG'), 0);
    v_an_g := NVL(FN_PARSE_THOI_GIAN_TEXT(p_AN_PHAT, 'NGAY'), 0);

    -- Ngày h?t án
    v_end := ADD_MONTHS(p_THA_NGAY_BAT, v_an_n * 12 + v_an_t) + v_an_g;

    -- M?c ?ã ch?p hành
    IF v_ngay_xet <= p_THA_NGAY_BAT THEN
        v_served_end := p_THA_NGAY_BAT;
    ELSIF v_ngay_xet >= v_end THEN
        v_served_end := v_end;
    ELSE
        v_served_end := v_ngay_xet;
    END IF;

    diff_ymd(p_THA_NGAY_BAT, v_served_end,
             v_da_n, v_da_t, v_da_g);

    IF v_ngay_xet >= v_end THEN
        v_con_n := 0; v_con_t := 0; v_con_g := 0;
    ELSE
        diff_ymd(v_ngay_xet, v_end,
                 v_con_n, v_con_t, v_con_g);
    END IF;

    RETURN TG_DA_CON_OBJ(
        format_ymd(v_da_n, v_da_t, v_da_g),
        format_ymd(v_con_n, v_con_t, v_con_g)
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN TG_DA_CON_OBJ('L?i', SQLERRM);
END;






/
--------------------------------------------------------
--  DDL for Function FN_TINH_TONG_AN_GIAM
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_TONG_AN_GIAM" (
    p_pham_nhan_id IN NUMBER
) RETURN YMD_OBJ IS
    v_ymd YMD_OBJ;
BEGIN
    SELECT 
        SUM(NVL(REGEXP_SUBSTR(dmtg.MTG_TITLE, '(\d+) n?m', 1, 1, NULL, 1), 0)) AS nam,
        SUM(NVL(REGEXP_SUBSTR(dmtg.MTG_TITLE, '(\d+) tháng', 1, 1, NULL, 1), 0)) AS thang,
        SUM(NVL(REGEXP_SUBSTR(dmtg.MTG_TITLE, '(\d+) ngày', 1, 1, NULL, 1), 0)) AS ngay
    INTO v_ymd.nam, v_ymd.thang, v_ymd.ngay
    FROM GIAM_THOI_HANS gth
    JOIN DM_MA_THOI_GIANS dmtg 
      ON dmtg.ID = gth.MUC_GIAM_ID
     AND NVL(dmtg.IS_DELETED, 0) = 0
    WHERE gth.PHAM_NHAN_ID = p_pham_nhan_id
      AND gth.IS_DELETED = 0
      AND dmtg.MTG_MA NOT IN ('921000','912000','911000','922000');

    -- Normalize (gi? nguyên logic c?)
    v_ymd.thang := v_ymd.thang + FLOOR(NVL(v_ymd.ngay,0)/30);
    v_ymd.ngay  := MOD(NVL(v_ymd.ngay,0), 30);
    v_ymd.nam   := v_ymd.nam + FLOOR(v_ymd.thang / 12);
    v_ymd.thang := MOD(v_ymd.thang, 12);

    RETURN v_ymd;

EXCEPTION
    WHEN OTHERS THEN 
        RETURN YMD_OBJ(0,0,0);
END;






/
--------------------------------------------------------
--  DDL for Function FN_TINH_TONG_THOI_GIAN_TAM_DINH_CHI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_TONG_THOI_GIAN_TAM_DINH_CHI" (p_id_pham_nhan IN NUMBER) RETURN NUMBER IS
  v_tong NUMBER := 0;
BEGIN
  IF p_id_pham_nhan IS NULL THEN RETURN 0; END IF;
  SELECT NVL(SUM(
    CASE
      WHEN tdc.NGAY_LAI IS NOT NULL AND tdc.TU_NGAY IS NOT NULL THEN
        TRUNC(CAST(tdc.NGAY_LAI AS DATE)) - TRUNC(CAST(tdc.TU_NGAY AS DATE))
      ELSE 0
    END
  ), 0)
  INTO v_tong
  FROM QLPN.TAM_DINH_CHIS tdc
  WHERE tdc.PHAM_NHAN_ID = p_id_pham_nhan
    AND NVL(tdc.IS_DELETED, 0) = 0
    AND tdc.NGAY_LAI IS NOT NULL;
  RETURN v_tong;
EXCEPTION
  WHEN OTHERS THEN RETURN 0;
END FN_TINH_TONG_THOI_GIAN_TAM_DINH_CHI;





/
--------------------------------------------------------
--  DDL for Function FN_TINH_TONG_THOI_GIAN_TRON_TRAI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_TONG_THOI_GIAN_TRON_TRAI" (p_id_pham_nhan IN NUMBER) RETURN NUMBER IS
  v_tong NUMBER := 0;
BEGIN
  IF p_id_pham_nhan IS NULL THEN RETURN 0; END IF;
  SELECT NVL(SUM(
    CASE
      WHEN tt.NGAY_BAT_LAI IS NOT NULL THEN
        TRUNC(CAST(tt.NGAY_BAT_LAI AS DATE)) - TRUNC(CAST(tt.NGAY_TRON AS DATE))
      WHEN tt.NGAY_DINH_NA IS NOT NULL THEN
        TRUNC(CAST(tt.NGAY_DINH_NA AS DATE)) - TRUNC(CAST(tt.NGAY_TRON AS DATE))
      ELSE 0
    END
  ), 0)
  INTO v_tong
  FROM QLPN.TRON_TRAIS tt
  WHERE tt.PHAM_NHAN_ID = p_id_pham_nhan
    AND NVL(tt.IS_DELETED, 0) = 0
    AND tt.NGAY_BAT_LAI IS NOT NULL;
  RETURN v_tong;
EXCEPTION
  WHEN OTHERS THEN RETURN 0;
END FN_TINH_TONG_THOI_GIAN_TRON_TRAI;





/
--------------------------------------------------------
--  DDL for Function FN_TINH_TRANG_PN_TAI_NGAY
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TINH_TRANG_PN_TAI_NGAY" (
    p_ngay_xet     IN DATE,
    p_pham_nhan_id IN NUMBER DEFAULT NULL
) RETURN QLPN.TY_TTPN_TAB PIPELINED
AS
    -- AUTONOMOUS_TRANSACTION: hàm này ??c QLPN.PN_LAI_LICHS (CTE base); khi
    -- SP_CALC_TINH_TRANG_PHAM_NHAN g?i hàm này bên trong chính MERGE INTO PN_LAI_LICHS,
    -- Oracle báo ORA-04091 (mutating table) n?u không tách giao d?ch ??c l?p. Hàm ch?
    -- SELECT (không DML) nên tách an toàn — COMMIT cu?i ch? ?? ?óng giao d?ch autonomous.
    PRAGMA AUTONOMOUS_TRANSACTION;
    v_ngay_xet DATE := TRUNC(p_ngay_xet);
BEGIN
    FOR r IN (
        WITH base AS (
            SELECT pll.ID AS pn_id
              FROM QLPN.PN_LAI_LICHS pll
             WHERE NVL(pll.IS_DELETED, 0) = 0
               AND (p_pham_nhan_id IS NULL OR pll.ID = p_pham_nhan_id)
               AND NOT EXISTS (
                   SELECT 1
                     FROM QLPN.DM_TINH_TRANG_PHAM_NHANS t
                    WHERE t.ID = pll.LL_TINH_TRANG_ID
                      AND t.TTPN_MA = '9999'
                      AND NVL(t.IS_DELETED, 0) = 0
               )
               AND EXISTS (
                   SELECT 1
                     FROM QLPN.PN_THI_HANH_AN tha
                    WHERE tha.THA_PNLAI_LICH_ID = pll.ID
                      AND tha.THA_NGAY_DEN_TRAI IS NOT NULL
                      AND CAST(tha.THA_NGAY_DEN_TRAI AS DATE) <= v_ngay_xet
                      AND NVL(tha.IS_DELETED, 0) = 0
               )
        ),
        rel AS (
            SELECT pn_id, MIN(d) AS ngay_ra
              FROM (
                -- FIX 2026-08-22: ch? tính n?u v?n ?ang hu? án t?i ngày xét (NGAY_TRO_LAI NULL
                -- ho?c > ngày xét) — kh?p ?úng ?i?u ki?n ?ã dùng ? nhánh pri=9/'181' bên d??i.
                -- Tr??c ?ây không check NGAY_TRO_LAI: PN ?ã hu? án r?i QUAY L?I t? lâu v?n b?
                -- "ngay_ra" ghim v?nh vi?n vào ngày hu? án c?, khi?n nhánh m?c ??nh (pri=30) tr?
                -- '121' dù PN ?ang ch?p hành án h?p l?, còn h?n xa (phát hi?n qua ??i soát PT80
                -- vs dashboard, tr?i C10 toàn qu?c, 22/08/2026 — 33/33 case do HUY_ANS/
                -- THA_CO_DIEU_KIENS c? gây ra).
                SELECT PHAM_NHAN_ID AS pn_id, CAST(NGAY_TRA_TU_DO AS DATE) AS d
                  FROM QLPN.HUY_ANS
                 WHERE NGAY_TRA_TU_DO IS NOT NULL AND NVL(IS_DELETED, 0) = 0
                   AND (NGAY_TRO_LAI IS NULL OR CAST(NGAY_TRO_LAI AS DATE) > v_ngay_xet)
                UNION ALL
                SELECT PN_LAI_LICH_ID, CAST(MHP_NGAY_TU_DO AS DATE)
                  FROM QLPN.MIEN_HINH_PHATS
                 WHERE MHP_NGAY_TU_DO IS NOT NULL AND NVL(IS_DELETED, 0) = 0
                UNION ALL
                SELECT PHAM_NHAN_ID, CAST(NGAY_THA_GIAM_HET_AN AS DATE)
                  FROM QLPN.GIAM_THOI_HANS
                 WHERE NGAY_THA_GIAM_HET_AN IS NOT NULL AND NVL(IS_DELETED, 0) = 0
                UNION ALL
                SELECT PNLAI_LICH_ID, CAST(DX_NGAY_THA AS DATE)
                  FROM QLPN.PN_DAC_XAS
                 WHERE DX_NGAY_THA IS NOT NULL AND NVL(IS_DELETED, 0) = 0
                UNION ALL
                -- FIX 2026-08-22: ch? tính n?u ch?a b? b?t l?i t?i ngày xét — kh?p ?úng ?i?u
                -- ki?n ?ã dùng ? nhánh pri=19/'126' bên d??i (cùng lý do nh? HUY_ANS ? trên).
                SELECT PHAM_NHAN_ID, CAST(NGAY_THA AS DATE)
                  FROM QLPN.THA_CO_DIEU_KIENS
                 WHERE NGAY_THA IS NOT NULL AND NVL(IS_DELETED, 0) = 0
                   AND (NGAY_BAT_LAI IS NULL OR CAST(NGAY_BAT_LAI AS DATE) > v_ngay_xet)
                UNION ALL
                SELECT PNCG_LAI_LICH_ID, CAST(PNCG_NGAY_CHUYEN_GIAO AS DATE)
                  FROM QLPN.PN_CHUYEN_GIAO
                 WHERE PNCG_NGAY_CHUYEN_GIAO IS NOT NULL AND NVL(IS_DELETED, 0) = 0
                UNION ALL
                -- Ra tr?i (không rõ lý do c? th?): THA_NGAY_HET_HAN c?a b?n án m?i nh?t — ??ng b?
                -- SP_QLPN_GET_TK_THANG_DASHBOARD/SP_QLPN_GET_TK_NAM_DASHBOARD.GIAM_RA_TRAI_IDS,
                -- SP_GET_TIM_KIEM_PN_LAI_LICH.giam_ids, SP_CALC_TINH_TRANG_PHAM_NHAN.het_han_calc —
                -- không còn dùng PN_KET_THUC_RA_TRAIS. KHÔNG lo?i tr? theo giam riêng: PN ?ang
                -- giam riêng nh?ng THA_NGAY_HET_HAN ?ã qua v?n ???c coi là "?ã ch?p hành xong án
                -- ph?t tù" — giam riêng không kéo dài th?i h?n án ph?t tù. CASE bên d??i (cand,
                -- pri 30) ?ã t? ??m b?o th? t? ?u tiên ?úng: rel.ngay_ra <= v_ngay_xet ???c xét
                -- TR??C gr, nên h?t h?n luôn th?ng giam riêng.
                SELECT tl.pn_id, CAST(tl.THA_NGAY_HET_HAN AS DATE)
                  FROM (
                        SELECT tha.THA_PNLAI_LICH_ID AS pn_id,
                               tha.THA_NGAY_HET_HAN,
                               ROW_NUMBER() OVER (
                                   PARTITION BY tha.THA_PNLAI_LICH_ID
                                   ORDER BY NVL(tha.THA_NGAY_BAN_AN, tha.CREATION_TIME) DESC, tha.ID DESC
                               ) rn
                          FROM QLPN.PN_THI_HANH_AN tha
                         WHERE tha.THA_NGAY_HET_HAN IS NOT NULL
                           AND NVL(tha.IS_DELETED, 0) = 0
                       ) tl
                 WHERE tl.rn = 1
              )
             GROUP BY pn_id
        ),
        txact AS (
            SELECT DISTINCT PHAM_NHAN_ID AS pn_id
              FROM QLPN.TRICH_XUATS
             WHERE TX_LOAI_LENH_ID = 1
               AND CAST(TX_NGAY_TRICH_XUAT AS DATE) <= v_ngay_xet
               AND NVL(CAST(TX_NGAY_TRA AS DATE), v_ngay_xet + 1) > v_ngay_xet
               AND NVL(IS_DELETED, 0) = 0
        ),
        tx20 AS (
            SELECT DISTINCT tx.PHAM_NHAN_ID AS pn_id
              FROM QLPN.TRICH_XUATS tx
              JOIN QLPN.DM_TINH_TRANG_TRICH_XUATS tt ON tt.ID = tx.TX_TINH_TRANG_ID
             WHERE tx.TX_LOAI_LENH_ID = 1
               AND CAST(tx.TX_NGAY_TRICH_XUAT AS DATE) <= v_ngay_xet
               AND NVL(CAST(tx.TX_NGAY_TRA AS DATE), v_ngay_xet + 1) > v_ngay_xet
               AND tt.TTTX_MA = '20'
               AND NVL(tx.IS_DELETED, 0) = 0
        ),
        cb AS (
            SELECT DISTINCT PHAM_NHAN_ID AS pn_id
              FROM QLPN.CHUA_BENH_BAT_BUOCS
             WHERE (NGAY_KET_THUC IS NULL OR CAST(NGAY_KET_THUC AS DATE) > v_ngay_xet)
               AND NVL(IS_DELETED, 0) = 0
        ),
        gr AS (
            SELECT DISTINCT GR_PN_LAI_LICH_ID AS pn_id
              FROM QLPN.PN_GIAM_RIENGS
             WHERE (GR_NGAY_KETTHUC IS NULL OR CAST(GR_NGAY_KETTHUC AS DATE) > v_ngay_xet)
               AND NVL(IS_DELETED, 0) = 0
        ),
        cand AS (
            SELECT kc.KTC_PN_LAI_LICH_ID AS pn_id, 1 AS pri, '171' AS ma
              FROM QLPN.PN_KET_THUC_CHETS kc
              LEFT JOIN QLPN.DM_TRUONG_HOP_CHETS thc ON thc.ID = kc.KTC_DM_TRUONG_HOP_CHET_ID
             WHERE TRUNC(CAST(kc.KTC_NGAY_CHET AS DATE)) <= v_ngay_xet
               AND NVL(thc.THC_MA, '90') NOT IN ('30', '40', '50')
               AND NVL(kc.IS_DELETED, 0) = 0
            UNION ALL
            SELECT tdc.PHAM_NHAN_ID,
                   CASE WHEN tt.TTTDC_MA = '50' THEN 16
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 AND tt.TTTDC_MA = '30' THEN 2
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 AND tt.TTTDC_MA = '40' THEN 7
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 AND tt.TTTDC_MA = '60' THEN 14
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 AND tt.TTTDC_MA = '20' THEN 22
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 AND tt.TTTDC_MA = '70' THEN 23
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 AND tt.TTTDC_MA = '80' THEN 24
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 AND tt.TTTDC_MA = '98' THEN 25
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 THEN 26 END,
                   CASE WHEN tt.TTTDC_MA = '50' THEN '155'
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 AND tt.TTTDC_MA = '30' THEN '153'
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 AND tt.TTTDC_MA = '40' THEN '154'
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 AND tt.TTTDC_MA = '60' THEN '156'
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 AND tt.TTTDC_MA = '20' THEN '152'
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 AND tt.TTTDC_MA = '70' THEN '157'
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 AND tt.TTTDC_MA = '80' THEN '159'
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 AND tt.TTTDC_MA = '98' THEN '158'
                        WHEN tdc.LOAI_QUYET_DINH_ID = 1 THEN '151' END
              FROM QLPN.TAM_DINH_CHIS tdc
              LEFT JOIN QLPN.DM_TINH_TRANG_TAM_DINH_CHIES tt ON tt.ID = tdc.TINH_TRANG_ID
             WHERE CAST(tdc.NGAY_TDC AS DATE) <= v_ngay_xet
               AND NVL(CAST(tdc.NGAY_LAI AS DATE), v_ngay_xet + 1) > v_ngay_xet
               AND NVL(tdc.IS_DELETED, 0) = 0
               AND (tt.TTTDC_MA = '50' OR tdc.LOAI_QUYET_DINH_ID = 1)
            UNION ALL
            SELECT tx.PHAM_NHAN_ID,
                   CASE WHEN tt.TTTX_MA = '80' THEN 15
                        WHEN tt.TTTX_MA = '70' THEN 27
                        WHEN tt.TTTX_MA = '98' THEN 28
                        WHEN tx.TX_LOAI_LENH_ID = 1 AND tt.TTTX_MA = '40' THEN 3
                        WHEN tx.TX_LOAI_LENH_ID = 1 AND tt.TTTX_MA = '50' THEN 5
                        WHEN tx.TX_LOAI_LENH_ID = 1 AND tt.TTTX_MA = '97' THEN 6
                        WHEN tx.TX_LOAI_LENH_ID = 1 AND tt.TTTX_MA = '30' THEN 13
                        WHEN tx.TX_LOAI_LENH_ID = 1 AND tt.TTTX_MA = '91' THEN 18 END,
                   CASE WHEN tt.TTTX_MA = '80' THEN '148'
                        WHEN tt.TTTX_MA = '70' THEN '147'
                        WHEN tt.TTTX_MA = '98' THEN '149'
                        WHEN tx.TX_LOAI_LENH_ID = 1 AND tt.TTTX_MA = '40' THEN '144'
                        WHEN tx.TX_LOAI_LENH_ID = 1 AND tt.TTTX_MA = '50' THEN '145'
                        WHEN tx.TX_LOAI_LENH_ID = 1 AND tt.TTTX_MA = '97' THEN '150'
                        WHEN tx.TX_LOAI_LENH_ID = 1 AND tt.TTTX_MA = '30' THEN '143'
                        WHEN tx.TX_LOAI_LENH_ID = 1 AND tt.TTTX_MA = '91' THEN '126' END
              FROM QLPN.TRICH_XUATS tx
              JOIN QLPN.DM_TINH_TRANG_TRICH_XUATS tt ON tt.ID = tx.TX_TINH_TRANG_ID
             WHERE CAST(tx.TX_NGAY_TRICH_XUAT AS DATE) <= v_ngay_xet
               AND NVL(CAST(tx.TX_NGAY_TRA AS DATE), v_ngay_xet + 1) > v_ngay_xet
               AND NVL(tx.IS_DELETED, 0) = 0
               AND (tt.TTTX_MA IN ('80', '70', '98')
                    OR (tx.TX_LOAI_LENH_ID = 1 AND tt.TTTX_MA IN ('40', '50', '97', '30', '91')))
            UNION ALL
            SELECT tt.PHAM_NHAN_ID, 4, '132'
              FROM QLPN.TRON_TRAIS tt
              JOIN QLPN.DM_TINH_TRANG_TRONS dtt ON dtt.ID = tt.TINH_TRANG_ID
             WHERE CAST(tt.NGAY_TRON AS DATE) <= v_ngay_xet
               AND (tt.NGAY_BAT_LAI IS NULL OR CAST(tt.NGAY_BAT_LAI AS DATE) > v_ngay_xet)
               AND dtt.TTT_MA = '20'
               AND NVL(tt.IS_DELETED, 0) = 0
            -- '133' (tr?n tr?i truy nã, DM_TINH_TRANG_TRONS.TTT_MA='30') — thêm 2026-08-13:
            -- SP_CALC_TINH_TRANG_PHAM_NHAN b?n c? (tr??c khi h?p nh?t) phân bi?t tr?n tr?i
            -- th??ng (131)/truy nã (133), ngu?n h?p nh?t ban ??u ch? có 131/132 (ch?t) — khôi
            -- ph?c 133 ?? không m?t thông tin khi h?p nh?t (xem HUONG_DAN_TRIEN_KHAI_HOP_NHAT_
            -- TINH_TRANG_2026-08.md m?c 3). Pri=7.5: sau 132 (ch?t, ?u tiên cao nh?t trong nhóm
            -- tr?n tr?i), tr??c 8 (131, m?c ??nh m?i tr?n tr?i còn l?i). S?A 2026-08-14: pri=6
            -- ban ??u ??NG v?i nhánh TX TTTX_MA='97'?'150' (c?ng pri=6, xem CASE phía trên) —
            -- MIN(c.ma) KEEP DENSE_RANK FIRST v?i 2 candidate cùng pri s? ch?n theo MIN(ma),
            -- '133' < '150' nên âm th?m th?ng '150' khi PN v?a tr?n-truy-nã v?a có trích xu?t
            -- h?y án ?ang hi?u l?c — sai. ??i sang 7.5 (s? th?c, không c?n renumber các pri
            -- nguyên khác) ?? tách kh?i collision, gi? ?úng v? trí ?u tiên d? ??nh.
            UNION ALL
            SELECT tt.PHAM_NHAN_ID, 7.5, '133'
              FROM QLPN.TRON_TRAIS tt
              JOIN QLPN.DM_TINH_TRANG_TRONS dtt ON dtt.ID = tt.TINH_TRANG_ID
             WHERE CAST(tt.NGAY_TRON AS DATE) <= v_ngay_xet
               AND (tt.NGAY_BAT_LAI IS NULL OR CAST(tt.NGAY_BAT_LAI AS DATE) > v_ngay_xet)
               AND dtt.TTT_MA = '30'
               AND NVL(tt.IS_DELETED, 0) = 0
            UNION ALL
            SELECT tt.PHAM_NHAN_ID, 8, '131'
              FROM QLPN.TRON_TRAIS tt
             WHERE TRUNC(CAST(tt.NGAY_TRON AS DATE)) <= v_ngay_xet
               AND (tt.NGAY_BAT_LAI IS NULL OR CAST(tt.NGAY_BAT_LAI AS DATE) > v_ngay_xet)
               AND NVL(tt.IS_DELETED, 0) = 0
            UNION ALL
            SELECT ha.PHAM_NHAN_ID, 9, '181'
              FROM QLPN.HUY_ANS ha
             WHERE CAST(ha.NGAY_TRA_TU_DO AS DATE) <= v_ngay_xet
               AND (ha.NGAY_TRO_LAI IS NULL OR CAST(ha.NGAY_TRO_LAI AS DATE) > v_ngay_xet)
               AND NVL(ha.IS_DELETED, 0) = 0
            UNION ALL
            SELECT cg.PNCG_LAI_LICH_ID, 10, '127'
              FROM QLPN.PN_CHUYEN_GIAO cg
             WHERE CAST(cg.PNCG_NGAY_CHUYEN_GIAO AS DATE) <= v_ngay_xet
               AND NVL(cg.IS_DELETED, 0) = 0
            UNION ALL
            SELECT mhp.PN_LAI_LICH_ID, 11, '124'
              FROM QLPN.MIEN_HINH_PHATS mhp
             WHERE CAST(mhp.MHP_NGAY_TU_DO AS DATE) <= v_ngay_xet
               AND NVL(mhp.IS_DELETED, 0) = 0
            UNION ALL
            SELECT ct.PNCT_LAI_LICH_ID, 12, '161'
              FROM QLPN.PHAM_NHAN_CHUYEN_TRAI ct
              LEFT JOIN QLPN.DM_TRUONG_HOP_CHUYEN_TRAIS thct ON thct.ID = ct.PNCT_TRUONG_HOP_CHUYEN_ID
             WHERE CAST(ct.PNCT_NGAY_CHUYEN AS DATE) <= v_ngay_xet
               AND NVL(CAST(ct.PNCT_NGAY_TRO_LAI AS DATE), v_ngay_xet + 1) > v_ngay_xet
               AND (thct.THCT_MA <> '50' OR thct.THCT_MA IS NULL)
               AND NVL(ct.IS_DELETED, 0) = 0
            UNION ALL
            SELECT dx.PNLAI_LICH_ID, 17, '123'
              FROM QLPN.PN_DAC_XAS dx
             WHERE dx.DX_NGAY_THA IS NOT NULL
               AND CAST(dx.DX_NGAY_THA AS DATE) <= v_ngay_xet
               AND NVL(dx.IS_DELETED, 0) = 0
            UNION ALL
            SELECT tck.PHAM_NHAN_ID, 19, '126'
              FROM QLPN.THA_CO_DIEU_KIENS tck
             WHERE tck.NGAY_THA IS NOT NULL
               AND CAST(tck.NGAY_THA AS DATE) <= v_ngay_xet
               AND NVL(CAST(tck.NGAY_BAT_LAI AS DATE), v_ngay_xet + 1) > v_ngay_xet
               AND NVL(tck.IS_DELETED, 0) = 0
            UNION ALL
            SELECT gth.PHAM_NHAN_ID, 20, '122'
              FROM QLPN.GIAM_THOI_HANS gth
             WHERE CAST(gth.NGAY_THA_GIAM_HET_AN AS DATE) <= v_ngay_xet
               AND NVL(gth.IS_DELETED, 0) = 0
            UNION ALL
            SELECT htha.PHAM_NHAN_ID, 21, '191'
              FROM QLPN.HOAN_THI_HANH_ANS htha
             WHERE CAST(htha.NGAY_HOAN AS DATE) < v_ngay_xet
               AND NVL(CAST(htha.NGAY_THI_HANH_AN AS DATE), v_ngay_xet + 1) > v_ngay_xet
               AND NVL(htha.IS_DELETED, 0) = 0
            UNION ALL
            SELECT t.pn_id, 29,
                   CASE WHEN r.ngay_ra IS NOT NULL AND r.ngay_ra <= v_ngay_xet THEN '146'
                        WHEN x20.pn_id IS NOT NULL THEN '142'
                        ELSE '141' END
              FROM txact t
              LEFT JOIN rel r ON r.pn_id = t.pn_id
              LEFT JOIN tx20 x20 ON x20.pn_id = t.pn_id
            UNION ALL
            SELECT b.pn_id, 30,
                   CASE
                     WHEN r.ngay_ra IS NOT NULL AND r.ngay_ra <= v_ngay_xet AND cb.pn_id IS NOT NULL THEN '125'
                     WHEN r.ngay_ra IS NULL OR r.ngay_ra > v_ngay_xet THEN
                        CASE WHEN gr.pn_id IS NOT NULL THEN '112'
                             WHEN cb.pn_id IS NOT NULL THEN '113'
                             ELSE '111' END
                     ELSE '121' END
              FROM base b
              LEFT JOIN rel r ON r.pn_id = b.pn_id
              LEFT JOIN cb ON cb.pn_id = b.pn_id
              LEFT JOIN gr ON gr.pn_id = b.pn_id
        )
        SELECT b.pn_id AS pn_id,
               MIN(c.ma) KEEP (DENSE_RANK FIRST ORDER BY c.pri) AS ma
          FROM base b
          JOIN cand c ON c.pn_id = b.pn_id
         GROUP BY b.pn_id
    ) LOOP
        PIPE ROW (QLPN.TY_TTPN_ROW(r.pn_id, r.ma));
    END LOOP;

    COMMIT; -- ?óng autonomous transaction (không có DML nào ???c th?c hi?n)
    RETURN;
END FN_TINH_TRANG_PN_TAI_NGAY;

/
--------------------------------------------------------
--  DDL for Function FN_TONG_HOP_KET_QUA_CAI_TAO
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TONG_HOP_KET_QUA_CAI_TAO" (
    p_pham_nhan_id IN NUMBER,
    p_nam          IN NUMBER DEFAULT NULL
) RETURN NVARCHAR2 IS
    v_result NVARCHAR2(4000);
BEGIN
    SELECT
        nvl(
            LISTAGG(u'N\0103m '
                    || nam
                    || u' '
                    || ky_label
                    || u': '
                    || nvl(d.xlct_ten, u''),
                    u'; ') WITHIN GROUP(
            ORDER BY
                nam,
                sort_order
            ),
            NULL)
    INTO v_result
    FROM
        (
            SELECT
                x.xep_loai_nam   AS nam,
                'Q1'             AS ky_ma,
                u'Qu\00fd I'     AS ky_label,
                1                AS sort_order,
                x.xep_loai_quy_i AS xep_loai_id
            FROM
                xep_loais x
            WHERE
                    x.pham_nhan_id = p_pham_nhan_id
                AND nvl(x.is_deleted, 0) = 0
                AND x.xep_loai_quy_i IS NOT NULL
            UNION ALL
            SELECT
                x.xep_loai_nam,
                'Q2',
                u'Qu\00fd II',
                2,
                x.xep_loai_quy_ii
            FROM
                xep_loais x
            WHERE
                    x.pham_nhan_id = p_pham_nhan_id
                AND nvl(x.is_deleted, 0) = 0
                AND x.xep_loai_quy_ii IS NOT NULL
            UNION ALL
            SELECT
                x.xep_loai_nam,
                'Q3',
                u'Qu\00fd III',
                3,
                x.xep_loai_quy_iii
            FROM
                xep_loais x
            WHERE
                    x.pham_nhan_id = p_pham_nhan_id
                AND nvl(x.is_deleted, 0) = 0
                AND x.xep_loai_quy_iii IS NOT NULL
            UNION ALL
            SELECT
                x.xep_loai_nam,
                'Q4',
                u'Qu\00fd IV',
                4,
                x.xep_loai_quy_iv
            FROM
                xep_loais x
            WHERE
                    x.pham_nhan_id = p_pham_nhan_id
                AND nvl(x.is_deleted, 0) = 0
                AND x.xep_loai_quy_iv IS NOT NULL
        )                         k
        LEFT JOIN dm_xep_loai_cai_taos d ON d.id = k.xep_loai_id
                                                 AND nvl(d.is_deleted, 0) = 0
    WHERE
        ( p_nam IS NULL
          OR k.nam = p_nam );

    RETURN v_result;
EXCEPTION
    WHEN no_data_found THEN
        RETURN NULL;
    WHEN OTHERS THEN
        RETURN NULL;
END fn_tong_hop_ket_qua_cai_tao;




/
--------------------------------------------------------
--  DDL for Function FN_TONG_HOP_TIEN_SU
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TONG_HOP_TIEN_SU" (
    P_TS_PN_LAI_LICH_ID NUMBER
) RETURN OBJ_TIEN_SU_TONG_HOP
IS
    V_SO_TIEN_SU NUMBER;
    V_HANH_VI    NVARCHAR2(4000);
BEGIN
    IF P_TS_PN_LAI_LICH_ID IS NULL THEN
        RETURN OBJ_TIEN_SU_TONG_HOP(0, NULL);
    END IF;

    SELECT
        NVL(agg.cnt, 0),
        CASE
            WHEN NVL(agg.cnt, 0) = 0 THEN
                NULL
            ELSE
                SUBSTR(NVL(agg.detail_lines, ''), 1, 4000)
        END
    INTO
        V_SO_TIEN_SU,
        V_HANH_VI
    FROM (
        SELECT
            COUNT(*) AS cnt,
            RTRIM(
                LISTAGG(
                    u'- '
                    || NVL(CAST(ts.TS_HANH_VI_VI_PHAM AS NVARCHAR2(2000)), u'Kh\00f4ng r\00f5')
                    || u'.',
                    CHR(10)
                ) WITHIN GROUP (ORDER BY ts.TS_NGAY_QUYET_DINH NULLS LAST, ts.ID),
                CHR(10)
            ) AS detail_lines
        FROM PN_TIEN_SUS ts
        WHERE ts.TS_PN_LAI_LICH_ID = P_TS_PN_LAI_LICH_ID
          AND NVL(ts.IS_DELETED, 0) = 0
    ) agg;

    RETURN OBJ_TIEN_SU_TONG_HOP(
        NVL(V_SO_TIEN_SU, 0),
        NVL(V_HANH_VI, NULL)
    );

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN OBJ_TIEN_SU_TONG_HOP(0, NULL);
    WHEN OTHERS THEN
        RETURN OBJ_TIEN_SU_TONG_HOP(0, NULL);
END FN_TONG_HOP_TIEN_SU;


/
--------------------------------------------------------
--  DDL for Function FN_TONG_HOP_XEP_LOAI_DN_CN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TONG_HOP_XEP_LOAI_DN_CN" (
    p_PHAM_NHAN_ID IN NUMBER,
    p_NAM          IN NUMBER DEFAULT NULL
) RETURN NVARCHAR2
IS
    v_result NVARCHAR2(4000);
BEGIN
    SELECT
        LISTAGG(
            TO_NCHAR(nam) || u': \0110N: ' || dn || u'; CN: ' || cn || u'; C\1ea3 n\0103m: ' || ca_nam,
            u' '
        ) WITHIN GROUP (ORDER BY nam)
    INTO v_result
    FROM (
        WITH src AS (
            SELECT
                x.XEP_LOAI_NAM AS nam,
                x.XEP_LOAI_6_THANG_DAU_NAM  AS dn_raw,
                x.XEP_LOAI_6_THANG_CUOI_NAM AS cn_raw,
                x.XEP_LOAI_CA_NAM           AS y_raw
            FROM XEP_LOAIS x
            WHERE x.PHAM_NHAN_ID = p_PHAM_NHAN_ID
              AND NVL(x.IS_DELETED, 0) = 0
              AND x.XEP_LOAI_NAM IS NOT NULL
              AND (p_NAM IS NULL OR x.XEP_LOAI_NAM = p_NAM)
        )
        SELECT
            s.nam,
            NVL(dn_dm.XLCT_TEN, TO_NCHAR(s.dn_raw)) AS dn,
            NVL(cn_dm.XLCT_TEN, TO_NCHAR(s.cn_raw)) AS cn,
            CASE
                WHEN NULLIF(TRIM(TO_NCHAR(s.y_raw)), u'') IS NULL THEN u'Ch\01b0a \0111\1ee7 TGXL'
                ELSE NVL(y_dm.XLCT_TEN, TO_NCHAR(s.y_raw))
            END AS ca_nam
        FROM src s
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS dn_dm
            ON dn_dm.ID = CASE
                              WHEN REGEXP_LIKE(TRIM(TO_NCHAR(s.dn_raw)), '^\d+$') THEN TO_NUMBER(TRIM(TO_NCHAR(s.dn_raw)))
                              ELSE NULL
                          END
           AND NVL(dn_dm.IS_DELETED, 0) = 0
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS cn_dm
            ON cn_dm.ID = CASE
                              WHEN REGEXP_LIKE(TRIM(TO_NCHAR(s.cn_raw)), '^\d+$') THEN TO_NUMBER(TRIM(TO_NCHAR(s.cn_raw)))
                              ELSE NULL
                          END
           AND NVL(cn_dm.IS_DELETED, 0) = 0
        LEFT JOIN DM_XEP_LOAI_CAI_TAOS y_dm
            ON y_dm.ID = CASE
                             WHEN REGEXP_LIKE(TRIM(TO_NCHAR(s.y_raw)), '^\d+$') THEN TO_NUMBER(TRIM(TO_NCHAR(s.y_raw)))
                             ELSE NULL
                         END
           AND NVL(y_dm.IS_DELETED, 0) = 0
    );

    RETURN v_result;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN NULL;
    WHEN OTHERS THEN
        RETURN NULL;
END FN_TONG_HOP_XEP_LOAI_DN_CN;







/
--------------------------------------------------------
--  DDL for Function FN_TO_ROMAN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TO_ROMAN" (p_num IN NUMBER) RETURN VARCHAR2 IS
    v_result VARCHAR2(100) := '';
    v_n      NUMBER := p_num;
    TYPE t_val IS TABLE OF NUMBER;
    TYPE t_sym IS TABLE OF VARCHAR2(10);
    v_vals t_val := t_val(1000,900,500,400,100,90,50,40,10,9,5,4,1);
    v_syms t_sym := t_sym('M','CM','D','CD','C','XC','L','XL','X','IX','V','IV','I');
BEGIN
    IF p_num IS NULL OR p_num <= 0 THEN RETURN TO_CHAR(p_num); END IF;
    FOR i IN 1..v_vals.COUNT LOOP
        WHILE v_n >= v_vals(i) LOOP
            v_result := v_result || v_syms(i);
            v_n      := v_n - v_vals(i);
        END LOOP;
    END LOOP;
    RETURN v_result;
END FN_TO_ROMAN;





/
--------------------------------------------------------
--  DDL for Function FN_TRAIVIEN_GET_TINH_TRANG_TAI_NGAY_XET
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TRAIVIEN_GET_TINH_TRANG_TAI_NGAY_XET" (
    P_LAI_LICH_ID NUMBER,
    P_NGAY_XET    DATE DEFAULT SYSDATE
) RETURN VARCHAR2
IS
    V_TTPN_MA_CURRENT VARCHAR2(50);
    V_REC             NUMBER;
    V_NGAY_HET_HAN    DATE;
BEGIN
    SELECT MAX(TRIM(CAST(TTPN.TTPN_MA AS VARCHAR2(50)))), MAX(LL.LL_NGAY_HET_HAN)
      INTO V_TTPN_MA_CURRENT, V_NGAY_HET_HAN
      FROM TRAIVIEN.LAI_LICHS LL
      LEFT JOIN TRAIVIEN.DM_TINH_TRANG_TRAI_VIEN TTPN ON TTPN.ID = LL.LL_TINH_TRANG_ID
     WHERE LL.ID = P_LAI_LICH_ID
       AND NVL(LL.IS_DELETED, 0) = 0
       AND NVL(TTPN.IS_DELETED, 0) = 0;

    IF V_TTPN_MA_CURRENT IS NULL THEN
        RETURN '99'; -- Xem lai thong tin
    END IF;

    -- 4: Chet
    SELECT COUNT(*)
      INTO V_REC
      FROM TRAIVIEN.KET_THUC_CHETS C
     WHERE C.KTC_PN_LAI_LICH_ID = P_LAI_LICH_ID
       AND C.KTC_NGAY_CHET IS NOT NULL
       AND TRUNC(C.KTC_NGAY_CHET) <= TRUNC(P_NGAY_XET)
       AND NVL(C.IS_DELETED, 0) = 0;
    IF V_REC > 0 THEN RETURN '4'; END IF;

    -- 8: Mien chap hanh
    SELECT COUNT(*)
      INTO V_REC
      FROM TRAIVIEN.TV_MIEN_CHAP_HANH_ANS M
     WHERE M.MCHA_TV_LAI_LICH_ID = P_LAI_LICH_ID
       AND M.MCHA_NGAY_RA IS NOT NULL
       AND TRUNC(M.MCHA_NGAY_RA) <= TRUNC(P_NGAY_XET)
       AND NVL(M.IS_DELETED, 0) = 0;
    IF V_REC > 0 THEN RETURN '8'; END IF;

    -- 3: Ra trai
    IF V_NGAY_HET_HAN IS NOT NULL AND TRUNC(V_NGAY_HET_HAN) <= TRUNC(P_NGAY_XET) THEN
        RETURN '3';
    END IF;

    -- 1: Tron (dang mo)
    SELECT COUNT(*)
      INTO V_REC
      FROM TRAIVIEN.TV_TRON_KHOI_CSGGBBS TT
     WHERE TT.TT_TRAI_VIEN_LAI_LICH_ID = P_LAI_LICH_ID
       AND TT.TT_NGAY_TRON IS NOT NULL
       AND TRUNC(TT.TT_NGAY_TRON) <= TRUNC(P_NGAY_XET)
       AND (TT.TT_NGAY_BAT_LAI IS NULL OR TRUNC(TT.TT_NGAY_BAT_LAI) > TRUNC(P_NGAY_XET))
       AND NVL(TT.IS_DELETED, 0) = 0;
    IF V_REC > 0 THEN RETURN '1'; END IF;

    -- 6: Tam dinh chi (dang mo)
    SELECT COUNT(*)
      INTO V_REC
      FROM TRAIVIEN.TV_TAM_DINH_CHIES TD
     WHERE TD.TDC_TRAI_VIEN_LAI_LICH_ID = P_LAI_LICH_ID
       AND TD.TDC_TU_NGAY IS NOT NULL
       AND TRUNC(TD.TDC_TU_NGAY) <= TRUNC(P_NGAY_XET)
       AND (TD.TDC_NGAY_LAI IS NULL OR TRUNC(TD.TDC_NGAY_LAI) > TRUNC(P_NGAY_XET))
       AND NVL(TD.IS_DELETED, 0) = 0;
    IF V_REC > 0 THEN RETURN '6'; END IF;

    -- 2: Tam thoi dua ra (dang mo)
    SELECT COUNT(*)
      INTO V_REC
      FROM TRAIVIEN.TV_TAM_THOI_DUA_RAS TD
     WHERE TD.TTDR_TRAI_VIEN_LAI_LICH_ID = P_LAI_LICH_ID
       AND TD.TTDR_NGAY_TAM_THOI_DUA_RA IS NOT NULL
       AND TRUNC(TD.TTDR_NGAY_TAM_THOI_DUA_RA) <= TRUNC(P_NGAY_XET)
       AND (TD.TTDR_NGAY_TRA_LAI IS NULL OR TRUNC(TD.TTDR_NGAY_TRA_LAI) > TRUNC(P_NGAY_XET))
       AND NVL(TD.IS_DELETED, 0) = 0;
    IF V_REC > 0 THEN RETURN '2'; END IF;

    -- 5: Chuyen trai
    SELECT COUNT(*)
      INTO V_REC
      FROM TRAIVIEN.TV_CHUYEN_CSGGBBS CCS
     WHERE CCS.CSGGBB_TV_LAI_LICH_ID = P_LAI_LICH_ID
       AND CCS.CCSGGBB_NGAY_CHUYEN IS NOT NULL
       AND TRUNC(CCS.CCSGGBB_NGAY_CHUYEN) <= TRUNC(P_NGAY_XET)
       AND NVL(CCS.IS_DELETED, 0) = 0;
    IF V_REC > 0 THEN RETURN '5'; END IF;

    RETURN '0';
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN '99';
END FN_TRAIVIEN_GET_TINH_TRANG_TAI_NGAY_XET;

/
--------------------------------------------------------
--  DDL for Function FN_TRON_TRAI_HIEN_THI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_TRON_TRAI_HIEN_THI" (p_id_pham_nhan IN NUMBER) RETURN NVARCHAR2 IS
  v_so_lan NUMBER;
  v_tong NUMBER;
  v_ref DATE := DATE '1900-01-01';
  v_y NUMBER;
  v_m NUMBER;
  v_d NUMBER;
  v_parts NVARCHAR2(400);
BEGIN
  v_so_lan := QLPN.FN_TINH_SO_LAN_TRON_TRAI(p_id_pham_nhan);
  v_tong := QLPN.FN_TINH_TONG_THOI_GIAN_TRON_TRAI(p_id_pham_nhan);
  IF v_so_lan = 0 OR v_tong IS NULL OR v_tong <= 0 THEN
    RETURN NULL;
  END IF;
  DECLARE
    d1 DATE := v_ref;
    d2 DATE := v_ref + v_tong;
    v_months NUMBER;
    v_tmp DATE;
  BEGIN
    v_months := TRUNC(MONTHS_BETWEEN(d2, d1));
    v_y := TRUNC(v_months / 12);
    v_m := MOD(v_months, 12);
    v_tmp := ADD_MONTHS(d1, v_y * 12 + v_m);
    v_d := TRUNC(d2 - v_tmp);
    IF v_d < 0 THEN
      v_m := v_m - 1;
      IF v_m < 0 THEN v_y := v_y - 1; v_m := v_m + 12; END IF;
      v_tmp := ADD_MONTHS(d1, v_y * 12 + v_m);
      v_d := GREATEST(TRUNC(d2 - v_tmp), 0);
    END IF;
  END;
  IF v_y >= 1 THEN
    v_parts := NULL;
    IF v_y > 0 THEN v_parts := TO_NCHAR(v_y) || ' nam'; END IF;
    IF v_m > 0 THEN v_parts := v_parts || ' ' || TO_NCHAR(v_m) || ' thang'; END IF;
    IF v_d > 0 THEN v_parts := v_parts || ' ' || TO_NCHAR(v_d) || ' ngay'; END IF;
    RETURN TO_NCHAR(v_so_lan) || ' lan = ' || v_parts;
  ELSIF v_m >= 1 THEN
    IF v_d > 0 THEN RETURN TO_NCHAR(v_so_lan) || ' lan = ' || TO_NCHAR(v_m) || ' Thang ' || TO_NCHAR(v_d) || ' ngay';
    ELSE RETURN TO_NCHAR(v_so_lan) || ' lan = ' || TO_NCHAR(v_m) || ' Thang';
    END IF;
  ELSE
    RETURN TO_NCHAR(v_so_lan) || ' lan = ' || TO_NCHAR(NVL(v_d, 0)) || ' ngay';
  END IF;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END FN_TRON_TRAI_HIEN_THI;





/
--------------------------------------------------------
--  DDL for Function FN_XET_DU_DIEU_KIEN_HPBS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_XET_DU_DIEU_KIEN_HPBS" (
    p_pham_nhan_id  IN NUMBER,
    p_dieu_kien_id  IN NUMBER
)
RETURN NUMBER
IS
    v_hpbs_1phan    NUMBER := 0;
    v_nguong_text   NVARCHAR2(255);
    v_tong_tien     NUMBER := 0;
    v_da_dong       NUMBER := 0;
    v_con_lai       NUMBER := 0;
    v_tu            NUMBER;
    v_mau           NUMBER;
    v_nguong_tien   NUMBER;
BEGIN
    -- L?y c?u hình HPBS
    BEGIN
        SELECT NVL(HPBS_BOI_THUONG1PHAN_NVDS, 0),
               HPBS_BOI_THUONG_DAN_SU
          INTO v_hpbs_1phan, v_nguong_text
          FROM GTH_HINH_PHAT_BO_SUNGS
         WHERE GTH_DIEU_KIEN_GIAM_THOI_HAN_ID = p_dieu_kien_id
           AND IS_DELETED = 0
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN RETURN 1;
    END;

    -- L?y t?ng ti?n + ?ã ?óng + còn l?i trong 1 l?n query
    SELECT
        NVL(SUM(NVL(phpbs.HPBS_TONG_TIEN_PHAT,    0)), 0),
        NVL(SUM(NVL(phpbs.HPBS_TONG_TIEN_PHAT,    0)), 0)
      - NVL(SUM(NVL(phpbs.HPBS_TONG_TIEN_CON_LAI, 0)), 0),
        NVL(SUM(NVL(phpbs.HPBS_TONG_TIEN_CON_LAI, 0)), 0)
      INTO v_tong_tien, v_da_dong, v_con_lai
      FROM PN_HINH_PHAT_BO_SUNGS phpbs
     WHERE phpbs.HPBS_MA_PHAM_NHAN = p_pham_nhan_id
       AND NVL(phpbs.IS_DELETED, 0) = 0;

    -- Không có ti?n ? m?c ??nh ??t
    IF v_tong_tien = 0 THEN
        RETURN 1;
    END IF;

    -- Rule 1: Ch? c?n ?óng 1 ph?n (da_dong > 0)
    IF v_hpbs_1phan = 1 THEN
        RETURN CASE WHEN v_da_dong > 0 THEN 1 ELSE 0 END;
    END IF;

    -- Rule 2: Ph?i ?óng >= ng??ng phân s?
    IF v_nguong_text IS NOT NULL AND INSTR(v_nguong_text, '/') > 0 THEN
        v_tu          := TO_NUMBER(TRIM(SUBSTR(v_nguong_text, 1, INSTR(v_nguong_text, '/') - 1)));
        v_mau         := TO_NUMBER(TRIM(SUBSTR(v_nguong_text, INSTR(v_nguong_text, '/') + 1)));
        v_nguong_tien := CEIL((v_tong_tien * v_tu) / v_mau);
        RETURN CASE WHEN v_da_dong >= v_nguong_tien THEN 1 ELSE 0 END;
    END IF;

    RETURN 1;

EXCEPTION
    WHEN OTHERS THEN RETURN 0;
END FN_XET_DU_DIEU_KIEN_HPBS;







/
--------------------------------------------------------
--  DDL for Function FN_XET_DU_DIEU_KIEN_QUY
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_XET_DU_DIEU_KIEN_QUY" (
    p_pham_nhan_id IN NUMBER,
    p_ky_giam_id   IN NUMBER
) RETURN QLPN.DIEU_KIEN_QUY_OBJ
IS
    v_dieu_kien_id          NUMBER;
    v_ngay_xet              DATE;
    v_yc_lien_tuc           NUMBER := 0;
    v_yc_khong_lien_tuc     NUMBER := 0;
    v_yc_lien_ke            NUMBER := 0;
    v_yc_truong_hop_db      NUMBER := 0;
    v_he_so_cc              NUMBER := 0;
    v_he_so_kl              NUMBER := 0;
    v_he_so_db_tren10       NUMBER := 0;
    v_he_so_db_duoi10       NUMBER := 0;
    v_lien_ke_thuc_te       NUMBER := 0;
    v_tong_thuc_te          NUMBER := 0;
    v_da_giam               NUMBER := 0;
    v_co_canh_cao           NUMBER := 0;
    v_co_khien_trach        NUMBER := 0;
    v_co_giam_buong         NUMBER := 0;
    v_is_dac_biet           NUMBER := 0;
    v_tong_ngay_an          NUMBER := 0;
    v_an_phat               NVARCHAR2(500);
    v_rang_buoc_lien_ke     NUMBER := 0;
    v_co_canh_cao_4quy      NUMBER := 0;
    v_co_khien_trach_4quy   NUMBER := 0;
BEGIN
    -- 1. L?y ?i?u ki?n ID và ngày xét
    BEGIN
        SELECT dk.ID, CAST(kg.KGTH_NGAY_XET_GIAM AS DATE)
          INTO v_dieu_kien_id, v_ngay_xet
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS dk
          JOIN GTH_KY_GIAM_THOI_HANS kg ON kg.ID = p_ky_giam_id
         WHERE dk.GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
           AND dk.IS_DELETED = 0
           AND kg.IS_DELETED = 0
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN QLPN.DIEU_KIEN_QUY_OBJ(0, NULL, NULL, NULL);
    END;

    -- 2. S? quý yêu c?u
    DECLARE
        v_yc QLPN.SO_QUY_YEU_CAU_OBJ;
    BEGIN
        v_yc                := QLPN.FN_TINH_SO_QUY_YEU_CAU(p_pham_nhan_id, p_ky_giam_id);
        v_yc_lien_tuc       := v_yc.SO_QUY_LIEN_TUC;
        v_yc_khong_lien_tuc := v_yc.SO_QUY_KHONG_LIEN_TUC;
        v_yc_truong_hop_db  := v_yc.SO_QUY_TRUONG_HOP_DB;
        v_yc_lien_ke        := v_yc.SO_QUY_LIEN_KE_YC;
    END;

    -- 3. H? s? ràng bu?c
    BEGIN
        SELECT
            NVL(DKGTH_TH_TAI_PHAM_CANH_CAO,      0),
            NVL(DKGTH_TH_TAI_PHAM_KY_LUAT,       0),
            NVL(DKGTH_TH_DAC_BIET_AN_TREN10_NAM, 0),
            NVL(DKGTH_TH_DAC_BIET_AN_DUOI10_NAM, 0)
          INTO v_he_so_cc, v_he_so_kl, v_he_so_db_tren10, v_he_so_db_duoi10
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS
         WHERE ID = v_dieu_kien_id
           AND IS_DELETED = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN QLPN.DIEU_KIEN_QUY_OBJ(0, NULL, NULL, v_ngay_xet);
    END;

    -- 4. Án ph?t
    BEGIN
        SELECT ptha.THA_AN_PHAT INTO v_an_phat
          FROM PN_THI_HANH_AN ptha
         WHERE ptha.THA_PNLAI_LICH_ID = p_pham_nhan_id
           AND NVL(ptha.IS_DELETED, 0) = 0
           AND ROWNUM = 1;
        v_tong_ngay_an := QLPN.FN_PARSE_AN_PHAT_TO_NGAY(v_an_phat);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN v_tong_ngay_an := 0;
    END;

    -- 5. ?ã t?ng gi?m
    SELECT COUNT(*) INTO v_da_giam
      FROM GIAM_THOI_HANS
     WHERE PHAM_NHAN_ID = p_pham_nhan_id
       AND IS_DELETED = 0;

    -- 6. K? lu?t
    SELECT COUNT(*) INTO v_co_canh_cao_4quy
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%C%NH C%O%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH <  v_ngay_xet;

    SELECT COUNT(*) INTO v_co_khien_trach_4quy
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%KHI%N TR%CH%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH <  v_ngay_xet;

    SELECT COUNT(*) INTO v_co_giam_buong
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%GIAM BU%NG%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH <  v_ngay_xet;

    v_co_canh_cao    := v_co_canh_cao_4quy;
    v_co_khien_trach := v_co_khien_trach_4quy;

    IF v_co_canh_cao_4quy > 1 OR v_co_khien_trach_4quy > 2 THEN
        RETURN QLPN.DIEU_KIEN_QUY_OBJ(0, NULL, NULL, v_ngay_xet);
    END IF;

    -- 7. TH ??c bi?t & s? quý th?c t?
    v_is_dac_biet     := QLPN.FN_IS_TRUONG_HOP_DAC_BIET(p_pham_nhan_id, p_ky_giam_id);
    v_lien_ke_thuc_te := QLPN.FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC_LIEN_KE(p_pham_nhan_id, v_ngay_xet);
    v_tong_thuc_te    := QLPN.FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT(p_pham_nhan_id, NULL).SO_QUY;

    -- 8. Ràng bu?c li?n k?
    IF v_da_giam > 0 THEN
        IF    (v_co_canh_cao >= 1 OR v_co_khien_trach >= 1) AND v_co_giam_buong > 0 THEN
            v_rang_buoc_lien_ke := GREATEST(v_he_so_cc, v_he_so_kl);
        ELSIF (v_co_canh_cao >= 1 OR v_co_khien_trach >= 1) THEN
            v_rang_buoc_lien_ke := v_he_so_cc;
        ELSIF v_co_giam_buong > 0 THEN
            v_rang_buoc_lien_ke := v_he_so_kl;
        END IF;
    END IF;

    IF v_is_dac_biet = 1 THEN
        IF v_tong_ngay_an >= 10 * 365 THEN
            v_rang_buoc_lien_ke := GREATEST(v_rang_buoc_lien_ke, v_he_so_db_tren10);
        ELSE
            v_rang_buoc_lien_ke := GREATEST(v_rang_buoc_lien_ke, v_he_so_db_duoi10);
        END IF;
    END IF;

    -- 9. Xét khung ? tr? Object v?i ??y ?? thông tin
    IF (v_rang_buoc_lien_ke = 0 OR v_lien_ke_thuc_te >= v_rang_buoc_lien_ke)
       AND v_lien_ke_thuc_te >= v_yc_lien_tuc
    THEN
        RETURN QLPN.DIEU_KIEN_QUY_OBJ(1, 'LIEN_TUC',        v_yc_lien_tuc,       v_ngay_xet);

    ELSIF v_yc_khong_lien_tuc > 0
      AND v_tong_thuc_te    >= v_yc_khong_lien_tuc
      AND v_lien_ke_thuc_te >= v_yc_lien_ke
    THEN
        RETURN QLPN.DIEU_KIEN_QUY_OBJ(1, 'KHONG_LIEN_TUC',  v_yc_khong_lien_tuc, v_ngay_xet);

    ELSIF v_is_dac_biet = 1
      AND (v_rang_buoc_lien_ke = 0 OR v_lien_ke_thuc_te >= v_rang_buoc_lien_ke)
      AND v_lien_ke_thuc_te >= v_yc_truong_hop_db
    THEN
        RETURN QLPN.DIEU_KIEN_QUY_OBJ(1, 'LIEN_TUC',        v_yc_truong_hop_db,  v_ngay_xet);

    ELSE
        RETURN QLPN.DIEU_KIEN_QUY_OBJ(0, NULL, NULL, v_ngay_xet);
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN QLPN.DIEU_KIEN_QUY_OBJ(0, NULL, NULL, NULL);
END FN_XET_DU_DIEU_KIEN_QUY;




/
--------------------------------------------------------
--  DDL for Function FN_XET_DU_DIEU_KIEN_QUY_OPT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_XET_DU_DIEU_KIEN_QUY_OPT" (
    p_pham_nhan_id IN NUMBER,
    p_ky_giam_id   IN NUMBER,
    p_trai_giam_id IN NUMBER  -- THÊM: filter s?m theo tr?i giam
) RETURN QLPN.DIEU_KIEN_QUY_OBJ
IS
    v_dieu_kien_id          NUMBER;
    v_ngay_xet              DATE;
    v_yc_lien_tuc           NUMBER := 0;
    v_yc_khong_lien_tuc     NUMBER := 0;
    v_yc_lien_ke            NUMBER := 0;
    v_yc_truong_hop_db      NUMBER := 0;
    v_he_so_cc              NUMBER := 0;
    v_he_so_kl              NUMBER := 0;
    v_he_so_db_tren10       NUMBER := 0;
    v_he_so_db_duoi10       NUMBER := 0;
    v_lien_ke_thuc_te       NUMBER := 0;
    v_tong_thuc_te          NUMBER := 0;
    v_da_giam               NUMBER := 0;
    v_co_canh_cao           NUMBER := 0;
    v_co_khien_trach        NUMBER := 0;
    v_co_giam_buong         NUMBER := 0;
    v_is_dac_biet           NUMBER := 0;
    v_tong_ngay_an          NUMBER := 0;
    v_an_phat               NVARCHAR2(500);
    v_rang_buoc_lien_ke     NUMBER := 0;
    v_co_canh_cao_4quy      NUMBER := 0;
    v_co_khien_trach_4quy   NUMBER := 0;
BEGIN
    -- 1. L?y ?i?u ki?n ID và ngày xét
    BEGIN
        SELECT dk.ID, CAST(kg.KGTH_NGAY_XET_GIAM AS DATE)
          INTO v_dieu_kien_id, v_ngay_xet
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS dk
          JOIN GTH_KY_GIAM_THOI_HANS kg ON kg.ID = p_ky_giam_id
         WHERE dk.GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
           AND dk.IS_DELETED = 0
           AND kg.IS_DELETED = 0
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN QLPN.DIEU_KIEN_QUY_OBJ(0, NULL, NULL, NULL);
    END;

    -- 2. S? quý yêu c?u (không c?n trai giam - b?ng GTH không partition theo trai giam)
    DECLARE
        v_yc QLPN.SO_QUY_YEU_CAU_OBJ;
    BEGIN
        v_yc                := QLPN.FN_TINH_SO_QUY_YEU_CAU(p_pham_nhan_id, p_ky_giam_id);
        v_yc_lien_tuc       := v_yc.SO_QUY_LIEN_TUC;
        v_yc_khong_lien_tuc := v_yc.SO_QUY_KHONG_LIEN_TUC;
        v_yc_truong_hop_db  := v_yc.SO_QUY_TRUONG_HOP_DB;
        v_yc_lien_ke        := v_yc.SO_QUY_LIEN_KE_YC;
    END;

    -- 3. H? s? ràng bu?c
    BEGIN
        SELECT
            NVL(DKGTH_TH_TAI_PHAM_CANH_CAO,      0),
            NVL(DKGTH_TH_TAI_PHAM_KY_LUAT,       0),
            NVL(DKGTH_TH_DAC_BIET_AN_TREN10_NAM, 0),
            NVL(DKGTH_TH_DAC_BIET_AN_DUOI10_NAM, 0)
          INTO v_he_so_cc, v_he_so_kl, v_he_so_db_tren10, v_he_so_db_duoi10
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS
         WHERE ID = v_dieu_kien_id
           AND IS_DELETED = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN QLPN.DIEU_KIEN_QUY_OBJ(0, NULL, NULL, v_ngay_xet);
    END;

    -- 4. Án ph?t (thêm filter trai giam vào PN_THI_HANH_AN)
    BEGIN
        SELECT ptha.THA_AN_PHAT INTO v_an_phat
          FROM PN_THI_HANH_AN ptha
          JOIN PN_LAI_LICHS ll ON ll.ID = ptha.THA_PNLAI_LICH_ID
         WHERE ptha.THA_PNLAI_LICH_ID = p_pham_nhan_id
           AND ll.LL_TRAI_GIAM_ID = p_trai_giam_id
           AND NVL(ptha.IS_DELETED, 0) = 0
           AND ROWNUM = 1;
        v_tong_ngay_an := QLPN.FN_PARSE_AN_PHAT_TO_NGAY(v_an_phat);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN v_tong_ngay_an := 0;
    END;

    -- 5. ?ã t?ng gi?m (không c?n filter trai giam)
    SELECT COUNT(*) INTO v_da_giam
      FROM GIAM_THOI_HANS
     WHERE PHAM_NHAN_ID = p_pham_nhan_id
       AND IS_DELETED = 0;

    -- 6. K? lu?t (không c?n filter trai giam - th??ng không partition)
    SELECT COUNT(*) INTO v_co_canh_cao_4quy
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%C%NH C%O%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH <  v_ngay_xet;

    SELECT COUNT(*) INTO v_co_khien_trach_4quy
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%KHI%N TR%CH%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH <  v_ngay_xet;

    SELECT COUNT(*) INTO v_co_giam_buong
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND UPPER(dm.HTKLPN_TEN) LIKE '%GIAM BU%NG%'
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH <  v_ngay_xet;

    v_co_canh_cao    := v_co_canh_cao_4quy;
    v_co_khien_trach := v_co_khien_trach_4quy;

    IF v_co_canh_cao_4quy > 1 OR v_co_khien_trach_4quy > 2 THEN
        RETURN QLPN.DIEU_KIEN_QUY_OBJ(0, NULL, NULL, v_ngay_xet);
    END IF;

    -- 7. TH ??c bi?t & s? quý th?c t? (dùng _OPT cho IS_DAC_BIET)
    v_is_dac_biet     := QLPN.FN_IS_TRUONG_HOP_DAC_BIET_OPT(p_pham_nhan_id, p_ky_giam_id, p_trai_giam_id);
    v_lien_ke_thuc_te := QLPN.FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC_LIEN_KE(p_pham_nhan_id, v_ngay_xet);
    v_tong_thuc_te    := QLPN.FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT(p_pham_nhan_id, v_ngay_xet).SO_QUY;

    -- 8. Ràng bu?c li?n k?
    IF v_da_giam > 0 THEN
        IF    (v_co_canh_cao >= 1 OR v_co_khien_trach >= 1) AND v_co_giam_buong > 0 THEN
            v_rang_buoc_lien_ke := GREATEST(v_he_so_cc, v_he_so_kl);
        ELSIF (v_co_canh_cao >= 1 OR v_co_khien_trach >= 1) THEN
            v_rang_buoc_lien_ke := v_he_so_cc;
        ELSIF v_co_giam_buong > 0 THEN
            v_rang_buoc_lien_ke := v_he_so_kl;
        END IF;
    END IF;

    IF v_is_dac_biet = 1 THEN
        IF v_tong_ngay_an >= 10 * 365 THEN
            v_rang_buoc_lien_ke := GREATEST(v_rang_buoc_lien_ke, v_he_so_db_tren10);
        ELSE
            v_rang_buoc_lien_ke := GREATEST(v_rang_buoc_lien_ke, v_he_so_db_duoi10);
        END IF;
    END IF;

    -- 9. Xét khung ? tr? Object v?i ??y ?? thông tin
    IF (v_rang_buoc_lien_ke = 0 OR v_lien_ke_thuc_te >= v_rang_buoc_lien_ke)
       AND v_lien_ke_thuc_te >= v_yc_lien_tuc
    THEN
        RETURN QLPN.DIEU_KIEN_QUY_OBJ(1, 'LIEN_TUC',        v_yc_lien_tuc,       v_ngay_xet);

    ELSIF v_yc_khong_lien_tuc > 0
      AND v_tong_thuc_te    >= v_yc_khong_lien_tuc
      AND v_lien_ke_thuc_te >= v_yc_lien_ke
    THEN
        RETURN QLPN.DIEU_KIEN_QUY_OBJ(1, 'KHONG_LIEN_TUC',  v_yc_khong_lien_tuc, v_ngay_xet);

    ELSIF v_is_dac_biet = 1
      AND (v_rang_buoc_lien_ke = 0 OR v_lien_ke_thuc_te >= v_rang_buoc_lien_ke)
      AND v_lien_ke_thuc_te >= v_yc_truong_hop_db
    THEN
        RETURN QLPN.DIEU_KIEN_QUY_OBJ(1, 'LIEN_TUC',        v_yc_truong_hop_db,  v_ngay_xet);

    ELSE
        RETURN QLPN.DIEU_KIEN_QUY_OBJ(0, NULL, NULL, v_ngay_xet);
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN QLPN.DIEU_KIEN_QUY_OBJ(0, NULL, NULL, NULL);
END FN_XET_DU_DIEU_KIEN_QUY_OPT;


/
--------------------------------------------------------
--  DDL for Function FN_XET_DU_DIEU_KIEN_QUY_PHI_TEST
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_XET_DU_DIEU_KIEN_QUY_PHI_TEST" (
    p_pham_nhan_id IN NUMBER,
    p_ky_giam_id   IN NUMBER
) RETURN NUMBER
IS
    v_dieu_kien_id          NUMBER;
    v_ngay_xet              DATE;

    v_yc_lien_tuc           NUMBER := 0;
    v_yc_khong_lien_tuc     NUMBER := 0;
    v_yc_lien_ke            NUMBER := 0;
    v_yc_truong_hop_db      NUMBER := 0;

    v_he_so_cc              NUMBER := 0;
    v_he_so_kl              NUMBER := 0;
    v_he_so_db_tren10       NUMBER := 0;
    v_he_so_db_duoi10       NUMBER := 0;

    v_da_giam               NUMBER := 0;
    v_is_dac_biet           NUMBER := 0;
    v_tong_ngay_an          NUMBER := 0;
    v_an_phat               NVARCHAR2(500);

    v_rang_buoc_lien_ke     NUMBER := 0;
    v_du_dieu_kien          NUMBER := 0;

    -- Bi?n k? lu?t
    v_co_canh_cao_4quy      NUMBER := 0;
    v_co_khien_trach_4quy   NUMBER := 0;
    v_co_giam_buong         NUMBER := 0;

    v_lien_ke_thuc_te       NUMBER := 0;
    v_tong_thuc_te          NUMBER := 0;

BEGIN
    -- 1. L?y ?i?u ki?n ID + ngày xét (1 query)
    BEGIN
        SELECT dk.ID, CAST(kg.KGTH_NGAY_XET_GIAM AS DATE)
          INTO v_dieu_kien_id, v_ngay_xet
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS dk
          JOIN GTH_KY_GIAM_THOI_HANS kg ON kg.ID = p_ky_giam_id
         WHERE dk.GTH_KY_GIAM_THOI_HAN_ID = p_ky_giam_id
           AND dk.IS_DELETED = 0
           AND kg.IS_DELETED = 0
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN RETURN 0;
    END;

    -- 2. L?y s? quý yêu c?u (ch? g?i 1 l?n)
    DECLARE
        v_yc QLPN.SO_QUY_YEU_CAU_OBJ;
    BEGIN
        v_yc := QLPN.FN_TINH_SO_QUY_YEU_CAU(p_pham_nhan_id, p_ky_giam_id);
        v_yc_lien_tuc      := v_yc.SO_QUY_LIEN_TUC;
        v_yc_khong_lien_tuc:= v_yc.SO_QUY_KHONG_LIEN_TUC;
        v_yc_truong_hop_db := v_yc.SO_QUY_TRUONG_HOP_DB;
        v_yc_lien_ke       := v_yc.SO_QUY_LIEN_KE_YC;
    END;

    -- 3. L?y h? s? ràng bu?c
    BEGIN
        SELECT NVL(DKGTH_TH_TAI_PHAM_CANH_CAO, 0),
               NVL(DKGTH_TH_TAI_PHAM_KY_LUAT, 0),
               NVL(DKGTH_TH_DAC_BIET_AN_TREN10_NAM, 0),
               NVL(DKGTH_TH_DAC_BIET_AN_DUOI10_NAM, 0)
          INTO v_he_so_cc, v_he_so_kl, v_he_so_db_tren10, v_he_so_db_duoi10
          FROM GTH_DIEU_KIEN_GIAM_THOI_HANS
         WHERE ID = v_dieu_kien_id
           AND IS_DELETED = 0;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN RETURN 0;
    END;

    -- 4. L?y án ph?t + parse (ch? 1 l?n)
    BEGIN
        SELECT THA_AN_PHAT
          INTO v_an_phat
          FROM PN_THI_HANH_AN
         WHERE THA_PNLAI_LICH_ID = p_pham_nhan_id
           AND NVL(IS_DELETED, 0) = 0
           AND ROWNUM = 1;

        v_tong_ngay_an := QLPN.FN_PARSE_AN_PHAT_TO_NGAY(v_an_phat);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN 
            v_tong_ngay_an := 0;
    END;

    -- 5. ?ã t?ng gi?m
    SELECT COUNT(*) INTO v_da_giam
      FROM GIAM_THOI_HANS
     WHERE PHAM_NHAN_ID = p_pham_nhan_id
       AND IS_DELETED = 0;

    -- 6. ??m t?t c? k? lu?t trong 1 query duy nh?t (t?i ?u l?n nh?t)
    SELECT 
        COUNT(CASE WHEN UPPER(dm.HTKLPN_TEN) LIKE '%C%NH C%O%'      THEN 1 END),   -- C?nh cáo 12 tháng
        COUNT(CASE WHEN UPPER(dm.HTKLPN_TEN) LIKE '%KHI%N TR%CH%'   THEN 1 END),   -- Khi?n trách 12 tháng
        COUNT(CASE WHEN UPPER(dm.HTKLPN_TEN) LIKE '%GIAM BU%NG%'    THEN 1 END)    -- Giam bu?ng 12 tháng
      INTO v_co_canh_cao_4quy, v_co_khien_trach_4quy, v_co_giam_buong
      FROM KY_LUATS kl
      JOIN DM_HINH_THUC_KY_LUAT_PHAM_NHANS dm 
        ON kl.MA_HINH_THUC_KY_LUAT_ID = dm.ID
     WHERE kl.PHAM_NHAN_ID = p_pham_nhan_id
       AND kl.NGAY_QUYET_DINH >= ADD_MONTHS(v_ngay_xet, -12)
       AND kl.NGAY_QUYET_DINH < v_ngay_xet;
--       AND kl.IS_DELETED = 0;   -- thêm n?u có c?t này

    -- RULE lo?i s?m n?u vi ph?m ng??ng
    IF v_co_canh_cao_4quy > 1 OR v_co_khien_trach_4quy > 2 THEN
        RETURN 0;
    END IF;

    -- TH ??c bi?t
    v_is_dac_biet := QLPN.FN_IS_TRUONG_HOP_DAC_BIET(p_pham_nhan_id, p_ky_giam_id);

    -- 7. S? quý th?c t? (g?i t?i thi?u)
    v_lien_ke_thuc_te := QLPN.FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT_LIEN_TUC_LIEN_KE(p_pham_nhan_id, v_ngay_xet);
    v_tong_thuc_te    := QLPN.FN_TINH_SO_QUY_XEP_LOAI_KHA_TOT(p_pham_nhan_id, NULL).SO_QUY;

    -- 8. Tính ràng bu?c li?n k?
    IF v_da_giam > 0 THEN
        IF (v_co_canh_cao_4quy >= 1 OR v_co_khien_trach_4quy >= 1) AND v_co_giam_buong > 0 THEN
            v_rang_buoc_lien_ke := GREATEST(v_he_so_cc, v_he_so_kl);
        ELSIF (v_co_canh_cao_4quy >= 1 OR v_co_khien_trach_4quy >= 1) THEN
            v_rang_buoc_lien_ke := v_he_so_cc;
        ELSIF v_co_giam_buong > 0 THEN
            v_rang_buoc_lien_ke := v_he_so_kl;
        END IF;
    END IF;

    IF v_is_dac_biet = 1 THEN
        v_rang_buoc_lien_ke := GREATEST(v_rang_buoc_lien_ke, 
                                 CASE WHEN v_tong_ngay_an >= 10*365 
                                      THEN v_he_so_db_tren10 
                                      ELSE v_he_so_db_duoi10 END);
    END IF;

    -- 9. Xét khung chính
    IF (v_rang_buoc_lien_ke = 0 OR v_lien_ke_thuc_te >= v_rang_buoc_lien_ke) 
       AND v_lien_ke_thuc_te >= v_yc_lien_tuc THEN
        v_du_dieu_kien := 1;

    ELSIF v_yc_khong_lien_tuc > 0 
      AND v_tong_thuc_te >= v_yc_khong_lien_tuc 
      AND v_lien_ke_thuc_te >= v_yc_lien_ke THEN
        v_du_dieu_kien := 1;

    ELSIF v_is_dac_biet = 1 
      AND (v_rang_buoc_lien_ke = 0 OR v_lien_ke_thuc_te >= v_rang_buoc_lien_ke) 
      AND v_lien_ke_thuc_te >= v_yc_truong_hop_db THEN
        v_du_dieu_kien := 1;

    ELSE
        v_du_dieu_kien := 0;
    END IF;

    RETURN v_du_dieu_kien;

EXCEPTION
    WHEN OTHERS THEN 
        RETURN 0;
END ;






/
--------------------------------------------------------
--  DDL for Function FN_YMD_GTE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."FN_YMD_GTE" (
    p_a IN YMD_OBJ,
    p_b IN YMD_OBJ
) RETURN NUMBER IS
    v_nam_a   NUMBER := NVL(p_a.nam,   0);
    v_thang_a NUMBER := NVL(p_a.thang, 0);
    v_ngay_a  NUMBER := NVL(p_a.ngay,  0);
    v_nam_b   NUMBER := NVL(p_b.nam,   0);
    v_thang_b NUMBER := NVL(p_b.thang, 0);
    v_ngay_b  NUMBER := NVL(p_b.ngay,  0);
BEGIN
    -- So sánh n?m tr??c
    IF    v_nam_a > v_nam_b THEN RETURN 1;
    ELSIF v_nam_a < v_nam_b THEN RETURN 0;
    END IF;

    -- N?m b?ng nhau ? so sánh tháng
    IF    v_thang_a > v_thang_b THEN RETURN 1;
    ELSIF v_thang_a < v_thang_b THEN RETURN 0;
    END IF;

    -- Tháng b?ng nhau ? so sánh ngày
    IF    v_ngay_a >= v_ngay_b THEN RETURN 1;
    ELSE                            RETURN 0;
    END IF;

EXCEPTION
    WHEN OTHERS THEN RETURN 0;
END FN_YMD_GTE;







/
--------------------------------------------------------
--  DDL for Function F_MA_THOI_HAN
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."F_MA_THOI_HAN" return T_MA_THOI_HAN as
 tRet T_MA_THOI_HAN;
 i number;
 j number;
 k number;
begin
 tRet:=T_MA_THOI_HAN();
 for i in 1..99 loop
  tRet.Extend;
  tRet(tRet.Count):=O_MA_THOI_HAN('0000'||lpad(i,2,'0'),i||' ngay',0,0,i);
 end loop;
 for i in 100..365 loop
  tRet.Extend;
  tRet(tRet.Count):=O_MA_THOI_HAN(i,i||' ngay',0,0,i);
 end loop;
 /*===========================================*/
 for j in 1..99 loop
   for i in 0..29 loop
    tRet.Extend;
    if i=0 then
     tRet(tRet.Count):=O_MA_THOI_HAN('00'||lpad(j,2,'0')||lpad(i,2,'0'),j||' thang',0,j,i);
    else
     tRet(tRet.Count):=O_MA_THOI_HAN('00'||lpad(j,2,'0')||lpad(i,2,'0'),j||' thang '||i||' ngay',0,j,i);
    end if;
   end loop;
  end loop;
  /*===============================================*/
  for k in 1..30 loop
    for j in 0..11 loop
     for i in 0..29 loop
      tRet.Extend;
      if i=0 and j=0 then
       tRet(tRet.Count):=O_MA_THOI_HAN(lpad(k,2,'0')||lpad(j,2,'0')||lpad(i,2,'0'),k||' nam',0,12*k+j,i);
      elsif i=0 and j>0 then
       tRet(tRet.Count):=O_MA_THOI_HAN(lpad(k,2,'0')||lpad(j,2,'0')||lpad(i,2,'0'),k||' nam '||j||' thang',0,12*k+j,i);
      elsif i>0 and j=0 then
       tRet(tRet.Count):=O_MA_THOI_HAN(lpad(k,2,'0')||lpad(j,2,'0')||lpad(i,2,'0'),k||' nam '||i||' ngay',0,12*k+j,i);
      else
       tRet(tRet.Count):=O_MA_THOI_HAN(lpad(k,2,'0')||lpad(j,2,'0')||lpad(i,2,'0'),k||' nam '||j||' thang '||i||' ngay',0,12*k+j,i);
      end if;
     end loop;
    end loop;
   end loop;
   tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('911000','An chung than',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('912000','Chung than (Gi?m t? t? hinh)',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('921000','Chung than Gi?m xu?ng 30 nam',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('922000','Chung than gi?m xu?ng 20 nam',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('923000','Gi?m h?t th?i h?n ch?p hanh hinh ph?t tu',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('924000','D?c xa',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('925000','Gi?m an - Dang lam th? t?c xet gi?m',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('926000','Gi?m an - C?c V26 khong xet',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('927000','Gi?m an - Toa an khong xet',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('931000','Trich xu?t khong th?i h?n',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('932000','Trich xu?t d?n khi h?t th?i h?n di?u tra',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('941000','T?m dinh ch? khong th?i h?n',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('941100','T?m dinh ch? d?n khi kh?i b?nh',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('941200','T?m dinh ch? d?n khi co QD thi hanh an c?a Toa an',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('941300','T?m dinh ch? d?n khi ph?c h?i s?c kh?e',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('910000','T? hinh',null,null,null);
    tRet.Extend;
    tRet(tRet.Count):=O_MA_THOI_HAN('941999','T?m dinh ch? khong r? th?i h?n',null,null,null);
 return tRet;
end;





/
--------------------------------------------------------
--  DDL for Function F_PT80
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."F_PT80" (v_tu_ngay date, v_den_ngay date) return T_PT80 as
 tRet T_PT80;
 i number;
 TYPE colval IS TABLE OF NUMBER(10) INDEX BY BINARY_INTEGER;
 colv colval;
begin
  ------
  tRet:=T_PT80();
  -- init
  ------------------
  tRet.Extend;
  select count(*) into i from pn_lai_lich l where l.ma_loai_doi_tuong='20211' and l.ngay_den_trai between v_tu_ngay and v_den_ngay;

  colv(2):=i;
  tRet(tRet.Count):=O_PT80(2,'Tr?i t?m giam chuy?n d?n',i);
  ------------------
  tRet.Extend;
  select count(*) into i from pn_lai_lich l where l.ma_loai_doi_tuong='20221' and l.ngay_den_trai between v_tu_ngay and v_den_ngay;
  colv(3):=i;
  tRet(tRet.Count):=O_PT80(3,'Tr?i giam khac chuy?n d?n',i);
