/
--------------------------------------------------------
--  DDL for Function GETSTR
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GETSTR" (str varchar2,pos number) RETURN varchar2 IS
 cCount number:=0;
 Result varchar2(1000);
 s      varchar2(2000):=str||';';
BEGIN
/*	 loop
	 	if instr(s,';')>0 then
	 		cCount:=cCount+1;
	 		if cCount=pos then
	 			s:=substr(s,1,instr(s,';')-1);
	 			return s;
	 		end if;
	 		s:=substr(s,instr(s,';')+1);
	 		exit when s is null;
	 	end if;
	 end loop;*/
	 	if pos>0 then
		 if instr(s,';',1,pos)>0 then
		 	if pos>1 then
		 		s:=substr(s,instr(s,';',1,pos-1)+1,instr(s,';',1,pos)-instr(s,';',1,pos-1)-1);
		 	else
		 		s:=substr(s,1,instr(s,';')-1);
		 	end if;
		 		return s;
		 	end if;
		end if;
	 return null;		
END;





/
--------------------------------------------------------
--  DDL for Function GET_6THANG_XEP_LOAI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_6THANG_XEP_LOAI" (v_ngay_xet date) Return varchar is
Begin
  if to_char(v_ngay_xet,'mm') in ('12','01','02','03','04','05') then
   	return 'ma_xep_loai_cuoi in (''110'',''120'') and nam_xl='||to_char(to_number(to_char(v_ngay_xet,'yyyy'))-1);
  else
   	return 'ma_xep_loai_cuoi in (''110'',''120'') and nam_xl='||to_char(v_ngay_xet,'yyyy');
  end if;
End;




/
--------------------------------------------------------
--  DDL for Function GET_ALL_XEP_LOAI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_ALL_XEP_LOAI" (v_ngay_xet date) return varchar2 is
str varchar2(3000);
begin
  if to_char(v_ngay_xet,'mm') in ('12','01','02') then
  	str:= 'ma_xep_loai_q4 in (''110'',''120'') and nam_xl='||to_char(to_number(to_char(v_ngay_xet,'yyyy'))-1);
  elsif to_char(v_ngay_xet,'mm') in ('03','04','05') then
  	str:= 'ma_xep_loai_q1 in (''110'',''120'') and nam_xl='||to_char(v_ngay_xet,'yyyy');
  elsif to_char(v_ngay_xet,'mm') in ('06','07','08') then
  	str:= 'ma_xep_loai_q2 in (''110'',''120'') and nam_xl='||to_char(v_ngay_xet,'yyyy');
  elsif to_char(v_ngay_xet,'mm') in ('09','10','11') then
  	str:= 'ma_xep_loai_q3 in (''110'',''120'') and nam_xl='||to_char(v_ngay_xet,'yyyy');
  end if;
  Return str;
end;




