Begin
		-- an phat nam
	  if an_nam is not null then
	  	vAnphat:= an_nam||' nam ';
	  end if;
	  -- an phat thang
	  if an_thang is not null then
	  	vAnphat:=vAnphat||an_thang||' tháng ';
	  end if;
	  -- an phat ngay
	  if an_ngay is not null then
	  	vAnphat:=vAnphat||an_ngay||' ngày ';
	  end if;
	  vAnphat:=rtrim(ltrim(vAnphat));
	  vAnphat:=replace(vAnphat,'  ',' ');
	  return vAnphat;
End;





/
--------------------------------------------------------
--  DDL for Function GET_CHUCAIDAU
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_CHUCAIDAU" (str varchar2) RETURN varchar2 IS
 sRet   varchar2(200);
 bpos   number;
 l      number;
BEGIN
 if str is not null then
 l:=length(str);
  bpos:=instr(str,' ',1,2);
  if l>20 then
    sRet:=substr(str,1,bpos);
  else
     return str;
  end if;
	 for i in 1..length(str) loop
    if i>=bpos and bpos>0 then
        if substr(str,i,1)=' ' then
          sRet:=sRet||substr(str,i+1,1);
        elsif substr(str,i,1)=';' then
          sRet:=sRet||';'||substr(str,i+1,1);
        elsif substr(str,i,1)=',' then
          sRet:=sRet||substr(str,i,1);
        elsif substr(str,i,1)=chr(10) then
          sRet:=sRet||chr(10)||substr(str,i+1,1);
        end if;
     end if;
	 end loop;
	 return sRet;
 end if;
   return null;
END;




/
--------------------------------------------------------
--  DDL for Function GET_CHUOI_KQCT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_CHUOI_KQCT" (p_pn_id varchar2,p_ngay_xet date,p_ma_muc_an_phat varchar2) return varchar IS
  Len number(4):=0;
  num_rec number(4):=0;
  p_so_nam_ct number(4):=0;
  len_str number(4):=0;
  p_so_ngay_an_phat number(10):=0;
  p_data varchar2(100);
  p_xlquy varchar2(100);
  p_data_ct varchar2(100);
  ---p_ketqua varchar2(2000);
BEGIN
  if p_ma_muc_an_phat in (911000,912000) then -- chung than then
    p_so_ngay_an_phat:=100*12*30; -- 100 nam;
  else
    p_so_ngay_an_phat:=pn_sys.get_number_from_ma_string(p_ma_muc_an_phat,'SD');
  end if;
  if p_so_ngay_an_phat=36000 then -- An chung than
    p_so_nam_ct:=5;
  elsif p_so_ngay_an_phat>5400 and p_so_ngay_an_phat<=10800 then -- Tren 15 den 30 nam
    p_so_nam_ct:=4;
  elsif p_so_ngay_an_phat>3600 and p_so_ngay_an_phat<=5400 then -- Tren 10 den 15 nam
    p_so_nam_ct:=3;
  elsif p_so_ngay_an_phat>2520 and p_so_ngay_an_phat<=3600 then -- Tren 7 den 10 nam
    p_so_nam_ct:=3;
  elsif p_so_ngay_an_phat>1800 and p_so_ngay_an_phat<=2520 then -- Tren 5 den 7 nam
    p_so_nam_ct:=2;
  elsif p_so_ngay_an_phat>1080 and p_so_ngay_an_phat<=1800 then -- Tren 3 den 5 nam
    p_so_nam_ct:=1;
  else
    p_so_nam_ct:=1;
  end if;
 for obj in (select nam_xl
          ,decode(to_number(substr(MA_XEP_LOAI_Q1,2,1)),null,'A',1,'B',2,'C',3,'D',4,'E') QUY1
          ,decode(to_number(substr(MA_XEP_LOAI_Q2,2,1)),null,'A',1,'B',2,'C',3,'D',4,'E') QUY2
          ,decode(to_number(substr(MA_XEP_LOAI_DAU,2,1)),null,'A',1,'B',2,'C',3,'D',4,'E') DAU_NAM
          ,decode(to_number(substr(MA_XEP_LOAI_Q3,2,1)),null,'A',1,'B',2,'C',3,'D',4,'E') QUY3
          --,decode(to_number(substr(MA_XEP_LOAI_Q4,2,1)),null,'A',1,'B',2,'C',3,'D',4,'E') QUY4
          ,decode(to_number(substr(MA_XEP_LOAI_CUOI,2,1)),null,'A',1,'B',2,'C',3,'D',4,'E') CUOI_NAM
          ,decode(to_number(substr(MA_XEP_LOAI_CA,2,1)),null,'A',1,'B',2,'C',3,'D',4,'E') CA_NAM
          --,decode(ghi_Chu,null,'',ghi_Chu||'.') nhan_xet
    from pn_ket_qua_cai_tao
    where pn_id=p_PN_ID  and nam_xl>=to_number(to_char(p_ngay_xet,'YYYY'))-p_so_nam_ct and nam_xl<=to_number(to_char(p_ngay_Xet,'YYYY'))
    order by nam_xl)
  Loop
    p_data:='';
    num_rec:=num_rec+1;
    if obj.dau_nam='A' then
     if obj.quy2 is not null then
        p_xlquy:=obj.quy2;
     else
        p_xlquy:=obj.quy1;
     end if;
     if obj.cuoi_nam<>'A' then
         if obj.quy3 is not null then
            p_xlquy:=obj.quy3;
         end if;
        p_data:=obj.cuoi_nam;
     end if;
    else
      if obj.cuoi_nam='A' then
        p_data:=obj.dau_nam;
      else
        p_data:=obj.dau_nam||obj.cuoi_nam;
      end if;
    end if;
    if p_data_ct is null then
      p_data_ct:=p_data;
    else
      p_data_ct:=p_data_Ct||p_data;
    end if;
  End loop;
  return p_data_ct;
end;




