  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_COLS" (tab varchar2) Return varchar2 is
str varchar2(4000);
Begin
	for obj in (select column_name from user_tab_columns where table_name=upper(tab))
	loop
		str:=str||obj.column_name||chr(10);
	end loop;
	Return str;
End;





