--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_COL_VALUE" (vTab varchar2, vCol varchar2, curValue varchar2) return varchar2 is
 strSQL varchar2(2000);
 result varchar2(500);
begin
 strSQL:='Select '||vCol||' from '||vTab||' where upper(ma)=upper('''||curValue||''')';
 execute immediate strSql into result;
 return result;
exception
	when no_data_found then return null;
	when others then return null;
end;





