--  DDL for Function GET_DEN_NGAY
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_DEN_NGAY" (v_tu_ngay date,v_ma_thoi_han varchar2) return varchar2 is
v_ngay 	number;
v_thang number;
Begin
  if v_ma_thoi_han in ('0000','9999') then 	return null; end if;
	v_thang:=to_number(substr(v_ma_thoi_han,1,2));
	v_ngay:=to_number(substr(v_ma_thoi_han,3));
	return (add_months(v_tu_ngay,v_thang)+v_ngay);
End;






