--  DDL for Function GET_DIA_CHI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_DIA_CHI" (str1 varchar2,str2 varchar2,str3 varchar2) return varchar2 Deterministic is
str varchar2(1000);
begin
	str:=nvl(str1,'@')||', '||nvl(str2,'@')||', '||nvl(str3,'@');
	str:=replace(str,'@,','');
	str:=replace(str,', @','');
	str:=replace(str,'  ',' ');
	return ltrim(rtrim(str));
end;






