/
--------------------------------------------------------
--  DDL for Function GET_ID
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_ID" (tab varchar2,column_id varchar2,p_pn_id varchar2) return char is
max_stt number(4);
p_ketqua varchar2(18);
strSQL	 varchar2(1000);
Begin
 if length(p_PN_ID)<>16 then return null;end if;
 strSQL:='select max(to_number(substr('||column_id||',17))) from '||tab||' where PN_ID='''||P_PN_ID||'''';
 execute immediate strSql into max_stt;
 if nvl(MAX_STT,0)=0 then
		p_ketqua:=p_pn_id||'01';
	else
		p_ketqua:=p_pn_id||lpad(to_Char(max_stt+1),2,'0');
 end if;
 if length(p_ketqua)<>18 then return null;end if;
 return p_ketqua;
End;




