 loai_ky2 varchar2(3);
 chia_ky number:=0;
 chia_ky2 number:=0;
 ----
 so_ky_thuc varchar2(2000);
 so_ky_thuc2 varchar2(2000);
 so_ky_thuc_dai varchar2(2000);
 so_ky_thuc_dai2 varchar2(2000);
 ----
 vnam_xl number;
 vNgayQDGth date;
 cGth number;
Begin
select count(*),max(ngay_qd_giam) into cGth,vNgayQDGth
