--  DDL for Function GET_KY_LUAT_CUOI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_KY_LUAT_CUOI" (vpn_id varchar2,vch varchar2) return varchar2 is
 v_kl varchar2(500);
Begin
 select 'K? lu?t: ngay '||u_date(k.ngay_qd_kl)||' '||k.hinh_thuc_kl
                        ||decode(k.ngay_qd_tb,null,null,'; ngay CN ti?n b? '||u_date(k.ngay_qd_tb))
    into v_kl
        from pn_kl_ky_luat k where pn_id=vpn_id
             and ngay_qd_kl=(select max(ngay_qd_kl) from pn_kl_ky_luat
                                where pn_id=vpn_id);
return vch||v_kl;
exception
when no_data_found then return null;
when others then return null;
end;


/
--------------------------------------------------------
--  DDL for Function GET_KY_XL_KEM
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_KY_XL_KEM" (vpn_id varchar2, kq number default 0) return varchar2 is
 s_kqct varchar2(4000);
 n_kqct varchar2(200);
 n_kqct1 varchar2(200);
 n_kqct2 varchar2(200);
 soquykem number:=0;
 tgchkem varchar2(10);
Begin
for n in (select distinct nam_xl from v_pn_kqkt_doc t
                 where ma_xep_loai='B' and pn_id=vpn_id
                       order by nam_xl)
loop
n_kqct:='';
for j in (select * from v_xlct
                 where pn_id=vpn_id and nam_xl=n.nam_xl)
loop
  if j.ma_xep_loai_ca in ('130','140') then
    n_kqct:=' x?p lo?i '||j.xep_loai_ca||';';
    soquykem:=soquykem+4;
  else
    if j.ma_xep_loai_cuoi in ('130','140') then
       n_kqct2:=' 6 thang cu?i nam x?p lo?i '||j.xep_loai_cuoi||';';
       soquykem:=soquykem+2;
    else
       if j.ma_xep_loai_q3 in ('130','140') then
         n_kqct2:=' Quy III x?p lo?i '||j.xep_loai_q3||';';
         soquykem:=soquykem+1;
       end if;
       if j.ma_xep_loai_q3 in ('130','140') then
         n_kqct2:=n_kqct2||' Quy IV x?p lo?i '||j.xep_loai_q4||';';
         soquykem:=soquykem+1;
       end if;
    end if;
    if j.ma_xep_loai_dau in ('130','140') then
       n_kqct1:=' 6 thang d?u nam x?p lo?i '||j.xep_loai_dau||';';
       soquykem:=soquykem+2;
    else
       if j.ma_xep_loai_q1 in ('130','140') then
         n_kqct1:=' Quy I x?p lo?i '||j.xep_loai_q1||';';
         soquykem:=soquykem+1;
       end if;
       if j.ma_xep_loai_q2 in ('130','140') then
         n_kqct1:=n_kqct1||' Quy II x?p lo?i '||j.xep_loai_q2||';';
         soquykem:=soquykem+1;
       end if;
    end if;
    n_kqct:=n_kqct1||n_kqct2;
  end if;
end loop;
  s_kqct:=s_kqct||chr(10)||' Nam '||to_char(n.nam_xl)||n_kqct;
end loop;
tgchkem:=lpad(to_char(floor(soquykem/4)),2,'0')||lpad(to_char(mod(soquykem,4)*3),2,'0')||'00';
if kq=0 then
return substr(s_kqct,2);
end if;
 return tgchkem;
end;


