  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_LAST_MA_PLGG" (v_pn_id varchar2,vngay_xet date default sysdate)  return varchar2 is
v_ma_pl varchar2(50);
begin
	select ma_den_loai into v_ma_pl
