/
--------------------------------------------------------
--  DDL for Function GET_NGAY_SINH
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_NGAY_SINH" (vNgaysinh number, vThangsinh number, vNamsinh number) Return Date Is
  Birth_day date;
Begin
  if (nvl(vNgaysinh,0)<>0) and (nvl(vThangsinh,0)<>0) then
	 Birth_day:=to_date(to_char(vNgaysinh)||'/'
	       ||to_char(vThangsinh)||'/'
	       ||to_char(vNamsinh),'dd/mm/yyyy');
	elsif (nvl(vNgaysinh,0)=0) and (nvl(vThangsinh,0)<>0) then
	 birth_day:=last_day(to_date('15/'||to_char(vThangsinh)||'/'
	     ||to_char(vNamsinh),'dd/mm/yyyy'));
	elsif (nvl(vNgaysinh,0)=0) and (nvl(vThangsinh,0)=0) then
	 birth_day:=to_date('31/12/'||to_char(vNamsinh),'dd/mm/yyyy');
	end if;
	Return birth_day;
exception
 when no_data_found then return null;
 when others then 
      begin
      if nvl(vThangsinh,0)<>0 then 
        return last_day(to_date('15/'||to_char(vThangsinh)||'/'||to_char(vNamsinh),'dd/mm/yyyy'));
      end if;
      return to_date('31/12/'||to_char(vNamsinh),'dd/mm/yyyy');
      end;
End;


