/
--------------------------------------------------------
--  DDL for Function GET_THANG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_THANG" (V_MUC_AN_PHAT VARCHAR2) RETURN NUMBER DETERMINISTIC IS
    V_THANG NUMBER;
    VTHANG  NUMBER;
    VNGAY   NUMBER;
BEGIN
    SELECT MTG_THANG, MTG_NGAY
      INTO VTHANG, VNGAY
      FROM QLPN.DM_MA_THOI_GIANS
     WHERE MTG_MA = V_MUC_AN_PHAT
       AND NVL(IS_DELETED, 0) = 0
       AND ROWNUM = 1;

    IF VTHANG IS NOT NULL AND VNGAY IS NOT NULL THEN
        V_THANG := VTHANG + (VNGAY / 30);
    ELSIF VTHANG IS NOT NULL THEN
        V_THANG := VTHANG;
    END IF;

    RETURN V_THANG;
EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN NULL;
    WHEN OTHERS        THEN RETURN NULL;
END GET_THANG;

/
--------------------------------------------------------
--  DDL for Function GET_THUONG_TRU
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_THUONG_TRU" (dc varchar2, xaphuong varchar2,dp varchar2) return varchar2 is
	ten_dp	varchar2(200);
Begin
