--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_TH_THA" (v_pn_id varchar2) return varchar2 is
 cCount number;
Begin
 select count(*) into cCount from pn_dx_dac_xa where pn_id=v_pn_id;
 if cCount>0 then
   return '23';
 end if;
 select count(*) into cCount from pn_giam_thoi_han where pn_id=v_pn_id and ngay_tha_giam_het_an is not null;
 if cCount>0 then
   return '22';
 end if;
 return '21';
exception
 when others then return null;
end;

