--------------------------------------------------------
--  DDL for Function GET_TINH_TRANG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_TINH_TRANG" (vpn_id varchar2, vngay date default sysdate) return varchar2 is
vRet varchar2(10);
Begin
select ma_tt into vRet
from (select * from v_pn_tt 
             where pn_id=vpn_id 
                   and ngay<=vngay 
                       and ngay is not null
             order by ngay desc) 
where rownum<2;
return vRet;
exception
 when others then return '100';
end;


