--  DDL for Function GET_TUOI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_TUOI" (Ngay_sinh date, Ngay_ss date default sysdate) Return Number Is
	Tuoi number;
Begin
  Tuoi:=trunc(months_between(Ngay_ss,Ngay_sinh)/12);
  return Tuoi;
End;


