--------------------------------------------------------
--  DDL for Function GET_VERSION_CODE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_VERSION_CODE" return varchar2 is
ver_code varchar2(10);
begin
select max(t.version_code) into ver_code from s_version t;
if ver_code is null then
  return '2.0';
end if;
return ver_code;
exception
when no_data_found then return '2.0';
when others then return '2.0';
end;

/
--------------------------------------------------------
--  DDL for Function GET_VERSION_DATE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_VERSION_DATE" return date is
ver_date date;
begin
select max(t.version_date) into ver_date from s_version t;
if ver_date is null then
  return to_date('01-JAN-2014','DD-MON-YYYY');
end if;
return ver_date;
exception
when no_data_found then return to_date('01-JAN-2014','DD-MON-YYYY');
when others then return to_date('01-JAN-2014','DD-MON-YYYY');
end;

