--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_XEP_LOAI_PHIEU_TDC" (v_pn_id varchar2) return varchar2 is
 str varchar2(3000);
begin
  for obj in (select * from pn_ket_qua_cai_tao where pn_id=v_pn_id and nam_xl=(select max(nam_xl)from pn_ket_qua_cai_tao where pn_id=v_pn_id  )) loop
  	str:=str||'Nam '||obj.nam_xl||':'||chr(9);
     	str:=str||'Quy I: '||nvl(countma('ma_xep_loai_cai_tao',obj.ma_xep_loai_q1),'.....')||';'||chr(9);
   		str:=str||' Quy II: '||nvl(countma('ma_xep_loai_cai_tao',obj.ma_xep_loai_q2),'.....')||';'||chr(9);
   		str:=str||' 6 thang d?u nam: '||nvl(countma('ma_xep_loai_cai_tao',obj.ma_xep_loai_dau),'.....')||';'||chr(9);
  		str:=str||chr(10)||chr(9)||chr(9)||' Quy III: '||nvl(countma('ma_xep_loai_cai_tao',obj.ma_xep_loai_q3),'.....')||';'||chr(9);
    	str:=str||' Quy IV: '||nvl(countma('ma_xep_loai_cai_tao',obj.ma_xep_loai_q4),'.....')||';'||chr(9);
 	    str:=str||' 6 thang cu?i nam: '||nvl(countma('ma_xep_loai_cai_tao',obj.ma_xep_loai_cuoi),'.....')||';'||chr(9);
    	str:=str||chr(10)||chr(9)||chr(9)||' C? nam: '||nvl(countma('ma_xep_loai_cai_tao',obj.ma_xep_loai_ca),'.....')||';'||chr(9);
end loop;
Return str;
exception
when others then return null;
end;

