--  DDL for Function GET_XL_RL
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."GET_XL_RL" (v_id varchar2) Return number Is
 vNamxet number(4);
 xl_q1tn  varchar2(1);
 xl_q2tn  varchar2(1);
 xl_q3tn  varchar2(1);
 xl_q4tn  varchar2(1);
 xl_q1t  varchar2(1);
 xl_q2t  varchar2(1);
 xl_q3t  varchar2(1);
 xl_q4t  varchar2(1);
 xl_q1n  varchar2(1);
 xl_q2n  varchar2(1);
 xl_q3n  varchar2(1);
 xl_q4n  varchar2(1);
 StrXlrl varchar2(12);
Begin
	begin
	  select max(nam_xet) into vNamxet
	  from tv_ket_qua_cai_tao
	  where tv_id=v_id;
	exception
		when no_data_found then return 0;
		when others then return 0;
  end;
 ----------------------------------------------------------------------------
 begin
  select decode(MA_XEP_LOAI_Q1,1,'1',2,'1',3,'2',null,null,0),
  			 decode(MA_XEP_LOAI_Q2,1,'1',2,'1',3,'2',null,null,0),
  			 decode(MA_XEP_LOAI_Q3,1,'1',2,'1',3,'2',null,null,0),
  			 decode(MA_XEP_LOAI_Q4,1,'1',2,'1',3,'2',null,null,0)
  into xl_q1n,xl_q2n,xl_q3n,xl_q4n
  from tv_ket_qua_cai_tao
  where tv_id=v_id
  and nam_xet=vNamxet;
  end;
 ----------------------------------------------------------------------------
 begin
  select decode(MA_XEP_LOAI_Q1,1,'1',2,'1',3,'2',null,null,0),
  			 decode(MA_XEP_LOAI_Q2,1,'1',2,'1',3,'2',null,null,0),
  			 decode(MA_XEP_LOAI_Q3,1,'1',2,'1',3,'2',null,null,0),
  			 decode(MA_XEP_LOAI_Q4,1,'1',2,'1',3,'2',null,null,0)
  into xl_q1t,xl_q2t,xl_q3t,xl_q4t
  from tv_ket_qua_cai_tao
  where tv_id=v_id
  and nam_xet=vNamxet-1;
 exception
 	when no_data_found then null;
 	when others then null;
 end;
/* begin
  select decode(MA_XEP_LOAI_Q1,1,'1',2,'1',3,'2',null,null),
  			 decode(MA_XEP_LOAI_Q2,1,'1',2,'1',3,'2',null,null),
  			 decode(MA_XEP_LOAI_Q3,1,'1',2,'1',3,'2',null,null),
  			 decode(MA_XEP_LOAI_Q4,1,'1',2,'1',3,'2',null,null)
  into xl_q1tn,xl_q2tn,xl_q3tn,xl_q4tn
  from xep_loai_ren_luyen
  where hs_hsld=vSohsld
  and nam_xet=vNamxet-2;
 end;*/
 ----------------------------------------------------------------------------
  StrXlrl:=xl_q4n||xl_q3n||xl_q2n||xl_q1n||xl_q4t||xl_q3t||xl_q2t||xl_q1t;--xl_q4tn||xl_q3tn||xl_q2tn||xl_q1tn;
 ----------------------------------------------------------------------------
		if substr(StrXlrl,1,8) in ('11111111','12111111','11211111','11121111','11112111','11111211','11111121','11111112') then
			return 8;
		elsif substr(StrXlrl,1,7) in ('1111111','1211111','1121111','1112111','1111211','1111121','1111112') then
			return 7;
		elsif substr(StrXlrl,1,6) in ('111111','121111','112111','111211','111121','111112') then
			return 6;
		elsif substr(StrXlrl,1,5) in ('11111','12111','11211','11121','11112') then
			return 5;
		elsif substr(StrXlrl,1,4) in ('1111','1211','1121','1112') then
			return 4;
		elsif substr(StrXlrl,1,3) in ('111','121','112') then
			return 3;
		elsif substr(StrXlrl,1,2)='11' then
			return 2;
		elsif substr(StrXlrl,1,1)='1' then
			return 1;
		end if;
		  return 0;
End;

/*		if countChar(substr(StrXlrl,1,8),'2')=1 and countChar(substr(StrXlrl,1,8),'0')=0 then
			return 8;
		elsif countChar(substr(StrXlrl,1,7),'2')=1 and countChar(substr(StrXlrl,1,7),'0')=0 then
			return 7;
		elsif countChar(substr(StrXlrl,1,6),'2')=1 and countChar(substr(StrXlrl,1,6),'0')=0 then
			return 6;
		elsif countChar(substr(StrXlrl,1,5),'2')=1 and countChar(substr(StrXlrl,1,5),'0')=0 then
			return 5;
		elsif countChar(substr(StrXlrl,1,4),'2')=1 and countChar(substr(StrXlrl,1,4),'0')=0 then
			return 4;
		elsif countChar(substr(StrXlrl,1,3),'2')=1 and countChar(substr(StrXlrl,1,3),'0')=0 then
