/
--------------------------------------------------------
--  DDL for Function IN_DS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."IN_DS" (vSo varchar2,vDanhsach varchar2,vNot number default 0) return number is
--
-- Ham tra ve gia tri 1 neu vSo co trong vDanhsach voi vNot mac dinh la 0 va nguoc lai
--
  cSo varchar2(10);
  cDanhsach varchar2(1000);
  i number;
  ret number:=0;
begin
	cDanhsach:=','||vDanhsach||',';
	if countChar(vSo,',')>0 then
		for i in 1..countChar(vSo,',')+1 loop
			cSo:=getStr(vSo,i);
			cSo:=','||cSo||',';
			if instr(cDanhsach,cSo)>0 then
				ret:=ret+1;
			end if;
		end loop;
	else
		cSo:=','||vSo||',';
		if instr(cDanhsach,cSo)>0 then
			ret:=ret+1;	
		end if;
	end if;
	if ret>0 then return ret; end if;
	return null;
end;


