  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."REMOVE_SIGN" (p_text IN VARCHAR2)
RETURN VARCHAR2
IS
    v_text VARCHAR2(4000);
BEGIN
    IF p_text IS NULL THEN
        RETURN NULL;
    END IF;

    v_text := p_text;

    -- Replace uppercase vowels with acute
