    v_text := REPLACE(v_text, '?', 'A');

    -- Replace lowercase vowels with acute
    v_text := REPLACE(v_text, 'à', 'a');
    v_text := REPLACE(v_text, '?', 'a');
    v_text := REPLACE(v_text, '?', 'a');
    v_text := REPLACE(v_text, '?', 'a');
    v_text := REPLACE(v_text, '?', 'a');
    v_text := REPLACE(v_text, '?', 'a');
