    v_text := REPLACE(v_text, '?', 'E');
    v_text := REPLACE(v_text, '?', 'E');
    v_text := REPLACE(v_text, '?', 'E');
    v_text := REPLACE(v_text, 'Ê', 'E');
    v_text := REPLACE(v_text, '?', 'E');
    v_text := REPLACE(v_text, '?', 'E');
    v_text := REPLACE(v_text, '?', 'E');
    v_text := REPLACE(v_text, '?', 'E');

    v_text := REPLACE(v_text, 'è', 'e');
    v_text := REPLACE(v_text, '?', 'e');
    v_text := REPLACE(v_text, '?', 'e');
    v_text := REPLACE(v_text, '?', 'e');
    v_text := REPLACE(v_text, 'ê', 'e');
    v_text := REPLACE(v_text, '?', 'e');
    v_text := REPLACE(v_text, '?', 'e');
    v_text := REPLACE(v_text, '?', 'e');
