    v_text := REPLACE(v_text, '?', 'i');
    v_text := REPLACE(v_text, '?', 'i');
    v_text := REPLACE(v_text, '?', 'i');

    -- Replace O with acute
    v_text := REPLACE(v_text, 'Ò', 'O');
