    v_text := REPLACE(v_text, '?', 'O');
    v_text := REPLACE(v_text, '?', 'O');
    v_text := REPLACE(v_text, '?', 'O');
    v_text := REPLACE(v_text, '?', 'O');

    v_text := REPLACE(v_text, 'ò', 'o');
    v_text := REPLACE(v_text, '?', 'o');
    v_text := REPLACE(v_text, 'õ', 'o');
    v_text := REPLACE(v_text, '?', 'o');
    v_text := REPLACE(v_text, 'ô', 'o');
