--------------------------------------------------------
--  DDL for Function SUBSTR_250
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."SUBSTR_250" (v_str varchar2,i number, s out number) return varchar2 IS
str varchar2(4000);
v_number number:=250;
j number;
n number;
vitri number;
begin
for j in 0..9 loop
  if substr(v_str,i,1) is not null and substr(v_str,i+250+j,1)<>' ' and substr(v_str,i+250+j+1,1)<>' ' then
    vitri:=i+250+j;
    n:=j;
    exit;
  else
    vitri:=i+250;
  end if;
end loop;
  str:=substr(v_str,i+1,250+n);
  s:=vitri;
  return str;
end;

