--  DDL for Function S_TK_COUNT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "QLPN"."S_TK_COUNT" (colId varchar2, colVal varchar2) return number is
result number;
sqlstr varchar2(2000);
i number(2):=countStr(colVal);
n number(2);
sqlRet varchar2(2000);
begin
 select SQL_TXT into sqlstr from S_TK_DEF where COT_TK=colID;
 for n in 1..i+1 loop
   sqlstr:=replace(sqlstr,':'||n,getstr(colVal,n));
 end loop;
 execute immediate 'select count(*) from ('||replace(sqlstr,'"','''')||')' into result;
 --sqlRet:='select count(*) from ('||sqlstr||')';
 --return sqlRet;
 return result;
exception
  when no_data_found then return 8888;
  when others then return 9999;
end;


